                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    EXISTS (SELECT 1 FROM SCM_MST_DIVISION G WHERE G.VALID_YN = 'Y' AND (G.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR G.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1))  /*[E20260923-DMF0014VALMSG] 가드: Division 오류 행은 제외(근본 원인 1건만)*/
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_MST_SITE S, SCM_MST_DIVISION D2
                        WHERE  S.DIVISION_ID = D2.DIVISION_ID
                        AND    S.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2
