            END;
            */
            --[E20260930-DMF0014ASISPM] 아래 Invalid Customer Project 블록(E20260923 분리 신설) 비활성 — AS-IS L399~427 /* */ 주석 파리티 (사용자 지적 2026-09-30)
--            IF V_DIVISION != '40' THEN
--                /* [E20260923-DMF0014VALMSG] Customer Project 분리 검증 — 종전엔 Customer Model 조합 검증이 Project 오류까지
--                   'Invalid Customer Model' 로 뭉뚱그렸다. 판정 = (Division, Sales Site, Customer Project) 가 고객모델 마스터에 없는 행.
--                   [E20260929-DMF0014PRJMDL] 종전의 [Project]/[Model] 품목 경로(SITE_ITEM) 구제는 제거했다 — 존재하지 않는
--                   Customer Project/Model 이 통과하던 결함(사용자 지적 2026-09-29). */
--                UPDATE SCM_ADM_EXCEL_UPLOAD
--                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Customer Project ['||v_h4||': '||NVL(ATTRIBUTE4,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Customer Project ['||v_h4||': '||NVL(ATTRIBUTE4,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
--                WHERE  PROGRAM_ID = V_PROGRAM_ID
--                AND    SHEET_NAME = V_SHEET_NAME
--                AND    CREATED_BY = P_CREATED_BY
--                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
--                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
--                AND    EXISTS (SELECT 1 FROM SCM_MST_SITE GS, SCM_MST_DIVISION GD WHERE GS.DIVISION_ID = GD.DIVISION_ID AND GS.VALID_YN = 'Y' AND GS.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1))  /*[E20260923-DMF0014VALMSG] 가드: Division/Sales Site 오류 행은 제외(근본 원인 1건만)*/
--                AND    NOT EXISTS (SELECT 1 FROM DM_MST_CUSTOMER_MODEL GC, SCM_MST_DIVISION GD WHERE GC.DIVISION_ID = GD.DIVISION_ID AND GC.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GC.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GC.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4);  /*[E20260929-DMF0014PRJMDL] [Project]/[Model] 품목 경로(SITE_ITEM) 구제 제거 — 고객모델 마스터 단독 판정*/
--                v_err_cnt := SQL%ROWCOUNT;
--                IF v_err_cnt > 0 THEN
--                    V_LOG_TYPE    := '61';
--                    V_LOG_MESSAGE := '########## ERROR Invalid Customer Project. ##########';
--                    V_DESCRIPTION := 'rows=' || TO_CHAR(v_err_cnt);
--                    D_EVENT_DATE  := SYSTIMESTAMP;
--                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
--                    COMMIT;   -- ERROR 상태 확정
--                END IF;
--            END IF;

            IF V_DIVISION != '40' THEN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Customer Model ['||v_h5||': '||NVL(ATTRIBUTE5,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Customer Model ['||v_h5||': '||NVL(ATTRIBUTE5,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    EXISTS (SELECT 1 FROM SCM_MST_SITE GS, SCM_MST_DIVISION GD WHERE GS.DIVISION_ID = GD.DIVISION_ID AND GS.VALID_YN = 'Y' AND GS.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1))  /*[E20260923-DMF0014VALMSG] 가드: Sales Site·Customer Project 통과 행만 — Project 오류는 위 'Invalid Customer Project' 가 담당*/
                --[E20260930-DMF0014ASISPM] Customer Project 통과 가드 비활성 — AS-IS 는 Customer Project 검증이 주석이라 Customer Model 이 직접 판정
--                AND    EXISTS (SELECT 1 FROM DM_MST_CUSTOMER_MODEL GC, SCM_MST_DIVISION GD WHERE GC.DIVISION_ID = GD.DIVISION_ID AND GC.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GC.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GC.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4)  /*[E20260923-DMF0014VALMSG] 가드: Sales Site·Customer Project 통과 행만 — Project 오류는 위 'Invalid Customer Project' 가 담당*/
                AND    NOT EXISTS (SELECT 1
                        FROM   DM_MST_CUSTOMER_MODEL CM, SCM_MST_DIVISION D2
                        WHERE  CM.DIVISION_ID = D2.DIVISION_ID
                        AND    CM.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2
                        AND    CM.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4
                        AND    CM.CUSTOMER_MODEL = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5
                        AND    (D2.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR D2.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1)
                        AND    CM.VALID_YN = 'Y'
                        UNION  /*[E20260930-DMF0014ASISPM] AS-IS L447~455 복원 — [Project]/[Model] 가 SCM_MST_SITE_ITEM 에 있으면 통과 (09-29 제거분 원복, 사용자 결정 2026-09-30)*/
                        SELECT 1
                        FROM   SCM_MST_SITE_ITEM SI, SCM_MST_DIVISION D3
                        WHERE  SI.DIVISION_ID = D3.DIVISION_ID
                        AND    SI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2
                        AND    SI.PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE12  /*AS-IS L453 = Project 열*/
                        AND    SI.ITEM_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13       /*AS-IS L454 = Model 열*/
                        AND    (D3.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR D3.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1)
                        AND    SI.VALID_YN = 'Y');
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '100';
                    V_LOG_MESSAGE := '########## ERROR Invalid Customer Model. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정
                    -- [E20260911-DMF0014MULTI] 즉시반환 제거 — 전 검증을 끝까지 수행하고 마지막에 사유를 모아 반환한다.
                    --   (행별 ERROR/MESSAGE_TEXT 마킹은 위에서 이미 끝났다. 적재 게이트 V_COUNT=0 은 그대로라 안전)
                END IF;
            END IF;

            --[E20260930-DMF0014PMSI] [Project]/[Model] DMF0005 마스터(SCM_MST_SITE_ITEM) 단독 검증 재활성 — [Project]=AAA/[Model]=BBB 통과 지적(사용자 2026-09-30). Customer Project 비활성·Customer Model AS-IS 판정은 [E20260930-DMF0014ASISPM] 유지
            /* [E20260929-DMF0014PRJMDL] [Project]/[Model] 열 존재 검증 (사용자 지시 2026-09-29).
               저장 시 DM_PLN_CUSTOMER_PSI.PROJECT_CODE/ITEM_ID 로 그대로 적재되고, 조회 시 SCM_MST_SITE_ITEM 과
               조인해 EDIT_FLAG(DEPT) 를 정하므로 (Division, Sales Site) 의 SCM_MST_SITE_ITEM(VALID_YN='Y') 에 있어야 한다.
               빈칸도 오류. 아래 사문 블록(AS-IS 'Invalid Project.'/'Invalid Model.', CUSTOMER_MODEL 매핑 일치 기준)은 채택하지 않음. */
            IF V_DIVISION != '40' THEN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Project ['||v_h12||': '||NVL(ATTRIBUTE12,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Project ['||v_h12||': '||NVL(ATTRIBUTE12,'(empty)')||']' END, 1, 4000)
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    EXISTS (SELECT 1 FROM SCM_MST_SITE GS, SCM_MST_DIVISION GD WHERE GS.DIVISION_ID = GD.DIVISION_ID AND GS.VALID_YN = 'Y' AND GS.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1))  /*[E20260929-DMF0014PRJMDL] 가드: Division/Sales Site 오류 행 제외*/
                AND    NOT EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM GI, SCM_MST_DIVISION GD WHERE GI.DIVISION_ID = GD.DIVISION_ID AND GI.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GI.PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE12);
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '103';
                    V_LOG_MESSAGE := '########## ERROR Invalid Project. ##########';
                    V_DESCRIPTION := 'rows=' || TO_CHAR(v_err_cnt);
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정 (전 검증 계속 수행 — E20260911-DMF0014MULTI)
                END IF;

                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Model ['||v_h13||': '||NVL(ATTRIBUTE13,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Model ['||v_h13||': '||NVL(ATTRIBUTE13,'(empty)')||']' END, 1, 4000)
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    EXISTS (SELECT 1 FROM SCM_MST_SITE GS, SCM_MST_DIVISION GD WHERE GS.DIVISION_ID = GD.DIVISION_ID AND GS.VALID_YN = 'Y' AND GS.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1))  /*[E20260929-DMF0014PRJMDL] 가드: Division/Sales Site 오류 행 제외*/
                AND    (EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM GI, SCM_MST_DIVISION GD WHERE GI.DIVISION_ID = GD.DIVISION_ID AND GI.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GI.PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE12)
                        OR NOT EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM GI, SCM_MST_DIVISION GD WHERE GI.DIVISION_ID = GD.DIVISION_ID AND GI.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GI.ITEM_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13))  /*[E20260930-DMF0014MDLIND] 구 가드 'Project 통과 행만' → Project 오류 행도 판정: Project 통과면 (Site,Project,Model) 조합, Project 오류면 (Site,Model) 자체 미등재일 때만 (사용자 지적 2026-09-30 — [Project]=AAA·[Model]=BBB 중 Model 미표기)*/
                AND    NOT EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM GI, SCM_MST_DIVISION GD WHERE GI.DIVISION_ID = GD.DIVISION_ID AND GI.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GI.PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE12 AND GI.ITEM_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13);
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '104';
                    V_LOG_MESSAGE := '########## ERROR Invalid Model ([Project]/[Model] SITE_ITEM). ##########';
                    V_DESCRIPTION := 'rows=' || TO_CHAR(v_err_cnt);
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정 (전 검증 계속 수행 — E20260911-DMF0014MULTI)
                END IF;
            END IF;

            /* [E20260915-DMF0014MSTCHK] ② Model 품목 마스터 — 저장 후 반영(PR_DM_PLN_CUST_FCST_TO_MKT_FCST)이
               품목 분류(SCM_MST_ITEM_SN)를 예외처리 없이 조회하므로(ORA-01403) 업로드 단계에서 오류 행으로 거른다.
               대상 품목 = 반영 프로시저와 동일 규칙: Customer Model 마스터 품목 → 없으면 [Model] 열. */
            IF V_DIVISION != '40' THEN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Model ['||v_h13||': '||NVL((SELECT MAX(GC.ITEM_ID) FROM DM_MST_CUSTOMER_MODEL GC, SCM_MST_DIVISION GD WHERE GC.DIVISION_ID = GD.DIVISION_ID AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GC.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GC.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4 AND GC.CUSTOMER_MODEL = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5), SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13)||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Model ['||v_h13||': '||NVL((SELECT MAX(GC.ITEM_ID) FROM DM_MST_CUSTOMER_MODEL GC, SCM_MST_DIVISION GD WHERE GC.DIVISION_ID = GD.DIVISION_ID AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GC.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GC.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4 AND GC.CUSTOMER_MODEL = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5), SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13)||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    (EXISTS (SELECT 1 FROM DM_MST_CUSTOMER_MODEL GC, SCM_MST_DIVISION GD WHERE GC.DIVISION_ID = GD.DIVISION_ID AND GC.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GC.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GC.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4 AND GC.CUSTOMER_MODEL = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5) OR EXISTS (SELECT 1 FROM SCM_MST_SITE_ITEM GI, SCM_MST_DIVISION GD WHERE GI.DIVISION_ID = GD.DIVISION_ID AND GI.VALID_YN = 'Y' AND (GD.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR GD.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1) AND GI.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2 AND GI.PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE12 AND GI.ITEM_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13))  /*[E20260923-DMF0014VALMSG] 가드: Customer Model/품목경로 통과 행만 — 표기 값 = 실제 대조한 품목(Customer Model 품목, 없으면 [Model] 열)*/
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_MST_ITEM_SN S
                        WHERE  S.ITEM_ID = NVL((SELECT MAX(CM.ITEM_ID)
                                                FROM   DM_MST_CUSTOMER_MODEL CM, SCM_MST_DIVISION D2
                                                WHERE  CM.DIVISION_ID = D2.DIVISION_ID
                                                AND    (D2.DIVISION_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1 OR D2.DIVISION_NAME = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1)
                                                AND    CM.SCM_SITE_ID = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE2
                                                AND    CM.CUSTOMER_PROJECT_CODE = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE4
                                                AND    CM.CUSTOMER_MODEL = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5), SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE13));
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '101';
                    V_LOG_MESSAGE := '########## ERROR Invalid Model. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정 (전 검증 계속 수행 — E20260911-DMF0014MULTI)
                END IF;

                /* [E20260915-DMF0014MSTCHK] ③ Customs Handbook = LOOKUP 'DOM/EXP' (AS-IS 주석 블록의 검증 의도 복원) */
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Customs Handbook ['||v_h8||': '||NVL(ATTRIBUTE8,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Customs Handbook ['||v_h8||': '||NVL(ATTRIBUTE8,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE  L.LOOKUP_TYPE = 'DOM/EXP'
                        AND    L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE8
                        AND    L.VALID_YN = 'Y');
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '102';
                    V_LOG_MESSAGE := '########## ERROR Invalid Customs Handbook. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정 (전 검증 계속 수행 — E20260911-DMF0014MULTI)
                END IF;
            END IF;

            BEGIN
                -- ---------------------------------------------------------------------
                --scm2_mgr.xLOG('Invalid Customer Model ', SQL%ROWCOUNT, 7, TRUE);
                V_LOG_TYPE    := '100';
                V_LOG_MESSAGE := '########## Invalid Customer Model ##########';
                V_DESCRIPTION := NULL;
                D_EVENT_DATE  := SYSTIMESTAMP;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                -- ---------------------------------------------------------------------
            END;

            BEGIN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Incoterms ['||v_h6||': '||NVL(ATTRIBUTE6,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Incoterms ['||v_h6||': '||NVL(ATTRIBUTE6,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE  L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE6
                        AND    L.LOOKUP_TYPE = 'INCOTERMS'
                        AND    L.VALID_YN = 'Y');
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '110';
                    V_LOG_MESSAGE := '########## ERROR Invalid Incoterms. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정
                    -- [E20260911-DMF0014MULTI] 즉시반환 제거 — 전 검증을 끝까지 수행하고 마지막에 사유를 모아 반환한다.
                    --   (행별 ERROR/MESSAGE_TEXT 마킹은 위에서 이미 끝났다. 적재 게이트 V_COUNT=0 은 그대로라 안전)
                END IF;
            END;

            BEGIN
                -- ---------------------------------------------------------------------
                --scm2_mgr.xLOG('Invalid Project ', SQL%ROWCOUNT, 9, TRUE);
                V_LOG_TYPE    := '110';
                V_LOG_MESSAGE := '########## Invalid Incoterms. ##########';
                V_DESCRIPTION := NULL;
                D_EVENT_DATE  := SYSTIMESTAMP;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                -- ---------------------------------------------------------------------
            END;

            BEGIN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid FCST Type ['||v_h7||': '||NVL(ATTRIBUTE7,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid FCST Type ['||v_h7||': '||NVL(ATTRIBUTE7,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE  L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE7
                        AND    L.LOOKUP_TYPE = 'SALES_TYPE_CODE'
                        AND    L.VALID_YN = 'Y'
                        UNION
                        SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL D
                        WHERE  D.VALID_YN = 'Y'
                        AND    D.DESCRIPTION = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE7);
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '120';
                    V_LOG_MESSAGE := '########## ERROR Invalid Sales Type. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정
                    -- [E20260911-DMF0014MULTI] 즉시반환 제거 — 전 검증을 끝까지 수행하고 마지막에 사유를 모아 반환한다.
                    --   (행별 ERROR/MESSAGE_TEXT 마킹은 위에서 이미 끝났다. 적재 게이트 V_COUNT=0 은 그대로라 안전)
                END IF;
            END;

            BEGIN
                -- validation이 끝났으니 code로 update
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    ATTRIBUTE7 =
                       (SELECT D.SEGMENT1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL D
                        WHERE  D.VALID_YN = 'Y'
                        AND    D.LOOKUP_TYPE = 'SALES_TYPE_CODE'
                        AND    D.SEGMENT2 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE7)
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE = 'UPLOAD'
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE  L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE7
                        AND    L.LOOKUP_TYPE = 'SALES_TYPE_CODE'
                        AND    L.VALID_YN = 'Y');
            END;

            BEGIN
                -- ---------------------------------------------------------------------
                --scm2_mgr.xLOG('Invalid Project ', SQL%ROWCOUNT, 9, TRUE);
                V_LOG_TYPE    := '120';
                V_LOG_MESSAGE := '########## Invalid Sales Type. ##########';
                V_DESCRIPTION := NULL;
                D_EVENT_DATE  := SYSTIMESTAMP;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                -- ---------------------------------------------------------------------
            END;

            /*
            BEGIN
            UPDATE SCM_ADM_EXCEL_UPLOAD
            SET    UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Customs Handbook'
            WHERE  PROGRAM_ID         = v_program_id
            AND    SHEET_NAME         = v_sheet_name
            AND    CREATED_BY         = p_created_by
            AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = v_creation_date
            AND    UPLOAD_STATUS_CODE = 'UPLOAD'
            AND NOT EXISTS (SELECT 1
                            FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                            WHERE  L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE8
                            AND    L.LOOKUP_TYPE = 'DOM/EXP'
                            AND    L.VALID_YN    = 'Y');
            END;

            BEGIN
            -- ---------------------------------------------------------------------
            --scm2_mgr.xLOG('Invalid Project ', SQL%ROWCOUNT, 9, TRUE);
            v_log_type := '12';
            v_log_message := '########## Invalid DOM/EXP. ##########';
            v_description := NULL;
            d_event_date := SYSTIMESTAMP;
            PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date);
            -- ---------------------------------------------------------------------
            END;
            */
            BEGIN
                UPDATE SCM_ADM_EXCEL_UPLOAD
                SET    UPLOAD_STATUS_CODE = 'ERROR', MESSAGE_TEXT = SUBSTR(CASE WHEN MESSAGE_TEXT IS NULL THEN 'Invalid Measure Group ['||v_h9||': '||NVL(ATTRIBUTE9,'(empty)')||']' ELSE MESSAGE_TEXT || ' / ' || 'Invalid Measure Group ['||v_h9||': '||NVL(ATTRIBUTE9,'(empty)')||']' END, 1, 4000)  /*[E20260923-DMF0014VALMSG]*/
                WHERE  PROGRAM_ID = V_PROGRAM_ID
                AND    SHEET_NAME = V_SHEET_NAME
                AND    CREATED_BY = P_CREATED_BY
                AND    TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                AND    UPLOAD_STATUS_CODE IN ('UPLOAD','ERROR')
                AND    NOT EXISTS (SELECT 1
                        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE  L.SEGMENT1 = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE9
                        AND    L.LOOKUP_TYPE = 'MEASURE_GROUP_CODE'
                        AND    L.SEGMENT1 = 'CUST_FCST'
                        AND    L.VALID_YN = 'Y');
                v_err_cnt := SQL%ROWCOUNT;
                IF v_err_cnt > 0 THEN
                    V_LOG_TYPE    := '130';
                    V_LOG_MESSAGE := '########## ERROR Invalid Measure Group. ##########';
                    V_DESCRIPTION := NULL;
                    D_EVENT_DATE  := SYSTIMESTAMP;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                    COMMIT;   -- ERROR 상태 확정
                    -- [E20260911-DMF0014MULTI] 즉시반환 제거 — 전 검증을 끝까지 수행하고 마지막에 사유를 모아 반환한다.
                    --   (행별 ERROR/MESSAGE_TEXT 마킹은 위에서 이미 끝났다. 적재 게이트 V_COUNT=0 은 그대로라 안전)
                END IF;
            END;

            --20230125 kdmcc14 [E20230119-000186-RPA 고객 FCST 가 소수점 단위로 Upload 될 경우 Error 팝업 및 사유 알람기능]
            BEGIN
                -- ---------------------------------------------------------------------
                --scm2_mgr.xLOG('Invalid Project ', SQL%ROWCOUNT, 9, TRUE);
                V_LOG_TYPE    := '130';
                V_LOG_MESSAGE := '########## Invalid Invalid Measure Group. ##########';
                V_DESCRIPTION := NULL;
                D_EVENT_DATE  := SYSTIMESTAMP;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
                -- ---------------------------------------------------------------------
            END;

            /* ==========================================================================
               [E20260923-DMF0014VALMSG] 동적(기간) 구간 = 셀 단위 검증 (사용자 지시 2026-09-23)
                 종전 = UNPIVOT 집계 후 행 단위 'Invalid Quantity' 1건 — 어느 기간 칸이 문제인지 알 수 없었다.
                 헤더행(V_TITLE)에 기간 값이 있는 칸(ATTRIBUTE14~200)마다, 기간 순서로 ' / ' 누적:
                   ① 숫자 아닌 값          → 'Please Input QTY [YYYYMMDD: 값]'   [E20260923-DMF0014BLANK] 문구 이동
                   ② 소수점(정수만 허용)    → 'Invalid Decimal [YYYYMMDD: 값]'   (E20230119-000186 정수 정책 유지)
                   ③ 빈값                  → **검사하지 않는다** (오류 아님 — 사용자 지시 2026-09-23)
                      - 구 정책(빈값 → 'Please Input QTY [기간]')은 폐기. 그에 딸린
                        DM_MST_CUSTOMER_FCST VALID_YN='Y' 상관 EXISTS 도 함께 제거했다.
                 한 행에 31칸 이상이면 30칸까지 표기 + ' ... (+N more)' (MESSAGE_TEXT 4000 보호, 12c 호환 — ON OVERFLOW 미사용)
               ========================================================================== */
            BEGIN
                MERGE INTO SCM_ADM_EXCEL_UPLOAD A
                USING (SELECT Q.UPLOAD_ID
                             ,LISTAGG(CASE WHEN Q.RN <= 30 THEN Q.MSG END, ' / ') WITHIN GROUP (ORDER BY Q.COL_IDX)
                              || CASE WHEN MAX(Q.CNT) > 30 THEN ' ... (+' || TO_CHAR(MAX(Q.CNT) - 30) || ' more)' END AS MSGS
                       FROM  (SELECT P.UPLOAD_ID, P.COL_IDX, P.MSG
                                    ,ROW_NUMBER() OVER (PARTITION BY P.UPLOAD_ID ORDER BY P.COL_IDX) RN
                                    ,COUNT(*)     OVER (PARTITION BY P.UPLOAD_ID) CNT
                              FROM  (SELECT V.UPLOAD_ID, V.COL_IDX
                                           ,CASE WHEN TRIM(V.VALUE) IS NULL THEN NULL   /*[E20260923-DMF0014BLANK] 빈칸 = 오류 아님 (사용자 지시 2026-09-23).
                                                        직전 회차의 'Please Input QTY [기간]' 빈값 검증을 폐기했다.
                                                        그 문구는 아래 비숫자 분기로 이동한다. */
                                                 WHEN NOT REGEXP_LIKE(TRIM(V.VALUE), '^-?[0-9]*\.?[0-9]+$')
                                                 THEN 'Please Input QTY [' || TRIM(H.HDR) || ': ' || V.VALUE || ']'
                                                 WHEN ROUND(TO_NUMBER(TRIM(V.VALUE)), 10) - FLOOR(ROUND(TO_NUMBER(TRIM(V.VALUE)), 10)) <> 0
                                                 THEN 'Invalid Decimal [' || TRIM(H.HDR) || ': ' || V.VALUE || ']'
                                            END AS MSG
                                     FROM  (SELECT UPLOAD_ID, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE10, COL_IDX, VALUE
