                            -- --------------------------------------------------------------------- 20180409 add
            -- inner join
            -- (select DIVISION_ID,SCM_SITE_ID,MEASURE,start_day,end_day
            -- from GT_DPCF_TMP_SITE_CUSTOMER_MAP_2 group by DIVISION_ID,SCM_SITE_ID,MEASURE,start_day,end_day) map

