                 WHERE ER.DIVISION_ID   = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE1
                   AND ER.UNIT_CURRENCY = SCM_ADM_EXCEL_UPLOAD.ATTRIBUTE5
               );

