                  AND FP.ITEM_ID = tmp.V_ITEM_ID AND FP.DOM_EXP = tmp.V_DOM_EXP
                  AND FP.FCST_TYPE = tmp.V_FCST_TYPE AND FP.INCOTERMS = tmp.V_INCOTERMS
                  AND FP.MEASURE = 'LOC' AND FP.CELL_PROD_SITE_ID = tmp.V_CELL_PROD_SITE_ID
                  AND CAL.BASIS_START_DATE = tmp.V_YYYYMMDD AND ROWNUM = 1
              ) AA WHERE AA.TBL = CASE WHEN AA.DIVISION_ID = '40' THEN 'DM_PLN_CFM_SELLING_PRICE' ELSE 'SCM_MST_FUTURE_PRICE' END
           ), 0)
         -- , V_CREATED_BY, V_LAST_UPDATED_BY, V_TEXT, V_DEPT_ID, V_CELL_PROD_SITE_ID, V_FROM_SITE_ID   --*[2026-09-22] POJ 원본
         -- [2026-09-22 / POJ] AS-IS 2081줄 — RTF_SYS_RP → SalesAmt_LOC 적재값
         --[E20260512-000502]_자동차 사업부 FROM SITE ID 추가하였으므로 81도 추가
         , V_CREATED_BY, V_LAST_UPDATED_BY, V_TEXT, V_DEPT_ID, CASE WHEN (tmp.V_DIVISION_ID = '40' OR SUBSTR(tmp.V_DIVISION_ID, 1, 2) = '81') THEN NVL(tmp.V_CELL_PROD_SITE_ID, '-') ELSE '-' END, V_FROM_SITE_ID --[E20260507-000749]_40 사업부 외에는 의미없는 값으로 CASE문으로 변경한다.
