          ,FORECAST_INFO_PRODUCT_GROUP
          ,FORECAST_INFO_CELL_MODEL
          ,FORECAST_INFO_CELL_PACK_COUNT
          ,FORECAST_INFO_SPEC
          ,FORECAST_INFOR_VERSION
          ,DOE
          ,INSULATION_COATING
          ,PACK_PRODUCT_GROUP_CODE
          ,CELL_QUANTITY
          ,SCP_EXTRA_SPEC
