          ,ITEM_CLASS_LEVEL_4
          ,ITEM_CLASS
          ,ITEM_CLASS_NAME
          ,MATERIAL_CLASS
          ,MATERIAL_CLASS_NAME
          ,ELECTRODE_TYPE
          ,SIDE_TYPE
          ,ITEM_GROUP_ID
          ,SETUP_GROUP_ID_1
          ,SETUP_GROUP_ID_2
          ,SETUP_GROUP_ID_3
          ,FLOW_ID
          ,ERP_EOL
          ,SCP_EOL
          ,ITEM_UOM
          ,SPEC
          ,DEMAND_LOT_SIZE
          ,ITEM_ATTRIBUTE
          ,SETUP_ATTRIBUTE
          ,BATCH_RATIO_ID
          ,OUTSOURCING_FACTORY
          ,FINITE_TERM
          ,FINITE_TERM_UOM
          ,COATED_LENGTH
