  PROCEDURE P_DMF0042_GET_EXCHANGE_PRICE
  (
      p_start_yyyymmdd VARCHAR2
    , p_end_yyyymmdd VARCHAR2
    , p_user_id VARCHAR2
    , p_menu_id VARCHAR2
