    P_SCM_SITE_ID           IN  CLOB,
    P_PROJECT_CODE          IN  CLOB,
    P_COMPANY_ID            IN  CLOB,
    P_FCST_TYPE             IN  CLOB,
    P_INCOTERMS             IN  CLOB,
    P_CELL_PROD_SITE        IN  CLOB,  /*[E20260911-CELLPRODKEY]*/
    P_PLANT_SITE_ID         IN  CLOB,  /*[E20260911-CELLPRODKEY]*/
