					GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
						, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '-'), M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							, B.SALES_COMPANY
						, B.ATTRIBUTE1
