					GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
						, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'), M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID
						, A.COMPANY_ID, B.ATTRIBUTE1
						, A.CELL_PROD_SITE_ID;			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
					--End [C20201014-000094] 82 사업부 비물동 구분코드 추가

					-- 소형 처리( 무상건 제외 )
					-- [C20210315-000140]
					IF p_division_id = '40' THEN
						DELETE FROM GT_DMF0_VERSION_COPY A
						WHERE EXISTS (
							SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
							WHERE A.FCST_TYPE = B.SEGMENT1 AND B.LOOKUP_TYPE = 'SALES_TYPE_CODE' AND B.SEGMENT4 = 'FREE'
						);
					END IF;

					-- RTF_SCP 처리
					IF p_division_id like '81%' THEN
						INSERT INTO GT_DMF0_VERSION_COPY (DIVISION_ID, VERSION_NO,CUTOFF_TYPE,CUTOFF_YYYYMMDD,PROJECT_CODE,SCM_SITE_ID,ITEM_ID
								, DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY, COMPANY_ID, SOLDTO_CUST_REPORT
							    , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						SELECT A.DIVISION_ID, A.VERSION_NO, 'REPORT_SP_W' as Cutoff_Type, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
								, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, '' AS CURRENCY, M.O_MEASURE AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
								, SUM(A.QTY) AS QTY
								, E.COMPANY_ID AS COMPANY_ID, B.ATTRIBUTE1
								--, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
								--, '-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
								, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_MKT_FCST_RESULT_C A
						JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'PLAN' AND M.CALC_YN = '-' AND M.SRC_TABLE = 'DM_PLN_MKT_FCST_RESULT_C'
						WHERE	A.VERSION_NO = 'MF_'  ||  SUBSTR(p_version_no,4,15)
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD < d_Result_Date   -- 과거실적구간으로 추출
							AND A.YYYYMMDD >= v_cp_MIN_YYYYMMDD
							AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
						GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							, E.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID;			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
					END IF;
					-- [C20210315-000347]
					IF p_division_id = '40' THEN

						-- SP 버전은 v002 등으로 재생성하더라도 보통 mf_w 는 v001 로 그대로 있으므로 끝자리는 고정한다.
						V_VERSION_NO_VMI := 'MF_W_' || TO_CHAR(FN_NEXT_DAY(TO_DATE(SUBSTR(p_version_no,6,8),'YYYYMMDD'), 'MON') + (-6), 'YYYYMMDD') --[E20260819-NLS1861]  -- 당주 월요일 이후인건만 추출
												 || '_V001';

						INSERT INTO GT_DMF0_VERSION_COPY (DIVISION_ID, VERSION_NO,CUTOFF_TYPE,CUTOFF_YYYYMMDD,PROJECT_CODE,SCM_SITE_ID,ITEM_ID
							, DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY, COMPANY_ID, SOLDTO_CUST_REPORT
							, CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						SELECT A.DIVISION_ID, A.VERSION_NO
								, v_cp_CUTOFF_TYPE  , v_cp_CUTOFF_YYYYMMDD --	, 'REPORT_SP_W' as Cutoff_Type , A.CUTOFF_YYYYMMDD
								, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
								, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, '' AS CURRENCY, M.O_MEASURE AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
								, SUM(A.QTY) AS QTY
								,'' AS COMPANY_ID  --, E.COMPANY_ID AS COMPANY_ID
								, B.ATTRIBUTE1
								--, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
								, A.CELL_PROD_SITE_ID AS CELL_PROD_SITE
						--[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
						--FROM DM_PLN_MKT_FCST_C A
						FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
						JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'PLAN' AND M.CALC_YN = '-' AND M.SRC_TABLE = 'DM_PLN_MKT_FCST_C'
						WHERE	A.VERSION_NO = V_VERSION_NO_VMI
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD >= NVL(d_Result_Date, '/')   -- 미래구간
							AND MEASURE IN ('VMI_In_Plan', 'VMI_In_Req')
							AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
						GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							, E.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID; --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경

						-- MKT FCST 테이블에서 데이터를 가져오면 Currency 및 Company_id 가 없어서 업데이트 해준다.
						-- 여기에서 하고 최종 INSERT INTO 전에 한 번 더 해준다.
						-- (MSSQL UPDATE...FROM...JOIN → Oracle MERGE. ON절 갱신컬럼 ORA-38104 회피 위해 필터는 WHEN MATCHED WHERE 로)
						MERGE INTO GT_DMF0_VERSION_COPY A
						USING ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, SUBSTR(YYYYMMDD, 1, 6) AS YYYYMM
									, MAX(CURRENCY) AS CURRENCY
								FROM DM_PLN_SALES_PLAN_C A
								WHERE A.VERSION_NO = p_version_no
									AND A.DIVISION_ID = p_division_id
									AND A.YYYYMMDD >= NVL(d_Result_Date, '/') -- 미래구간
								GROUP BY PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, SUBSTR(YYYYMMDD, 1, 6)
							) B ON ( A.PROJECT_CODE = B.PROJECT_CODE
								AND A.SCM_SITE_ID	= B.SCM_SITE_ID
								AND A.ITEM_ID		= B.ITEM_ID
								AND A.DOM_EXP		= B.DOM_EXP
								AND A.FCST_TYPE		= B.FCST_TYPE
								AND A.INCOTERMS		= B.INCOTERMS
								AND SUBSTR(A.YYYYMMDD, 1, 6)	= B.YYYYMM )
						WHEN MATCHED THEN UPDATE SET A.CURRENCY = B.CURRENCY
							WHERE A.MEASURE IN ('VMI_In_Plan', 'VMI_In_Req')
								AND A.CURRENCY IS NULL;

						MERGE INTO GT_DMF0_VERSION_COPY A
						USING ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
									, MAX(CURRENCY) AS CURRENCY
								FROM DM_PLN_SALES_PLAN_C A
								WHERE A.VERSION_NO = p_version_no
									AND A.DIVISION_ID = p_division_id
									AND A.YYYYMMDD >= NVL(d_Result_Date, '/') -- 미래구간
								GROUP BY PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
							) B ON ( A.PROJECT_CODE = B.PROJECT_CODE
								AND A.SCM_SITE_ID	= B.SCM_SITE_ID
								AND A.ITEM_ID		= B.ITEM_ID
								AND A.DOM_EXP		= B.DOM_EXP
								AND A.FCST_TYPE		= B.FCST_TYPE
								AND A.INCOTERMS		= B.INCOTERMS )
						WHEN MATCHED THEN UPDATE SET A.CURRENCY = B.CURRENCY
							WHERE A.MEASURE IN ('VMI_In_Plan', 'VMI_In_Req')
								AND A.CURRENCY IS NULL;

						MERGE INTO GT_DMF0_VERSION_COPY A
						USING SCM_MST_SITE_ITEM B
						ON ( A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID )
						WHEN MATCHED THEN UPDATE SET A.COMPANY_ID = B.SALES_COMPANY;
					END IF;
				ELSE
					INSERT INTO GT_DMF0_VERSION_COPY (DIVISION_ID, VERSION_NO,CUTOFF_TYPE,CUTOFF_YYYYMMDD,PROJECT_CODE,SCM_SITE_ID,ITEM_ID
						, DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY, COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, ITEM_USE, END_CUSTOMER
							, CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					SELECT A.DIVISION_ID, A.VERSION_NO
					    , 'REPORT_' ||  A.CUTOFF_TYPE AS CUTOFF_TYPE
						, A.CUTOFF_YYYYMMDD
						, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
						, A.FCST_TYPE, '' AS INCOTERMS, A.CURRENCY, A.MEASURE,A.PLANT_SITE_ID
						, A.YYYYMM  ||	'01', SUM(A.QTY) AS QTY
						, NVL(NULLIF(RTRIM(B.SALES_COMPANY),''), '/') AS COMPANY_ID
						, B.ATTRIBUTE1
						, CASE WHEN A.DIVISION_ID <> '40' THEN A.DEPT_ID ELSE NULL END AS DEPT_ID
						, NVL(NULLIF(RTRIM(A.ITEM_USE),''), '/') AS ITEM_USE, NVL(NULLIF(RTRIM(A.END_CUSTOMER),''), '/') AS END_CUSTOMER
						, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM DM_PLN_BP_FCST_C A
					LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
					LEFT OUTER JOIN SCM_MST_SITE C	ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
					JOIN ( SELECT DISTINCT I_MEASURE FROM GT_DMF0_MEASURE ) M ON A.MEASURE = M.I_MEASURE
					WHERE A.VERSION_NO = p_version_no
					--AND MEASURE IN ('SalesAmt_KRW', 'SalesAmt_LOC', 'SalesAmt_USD', 'Business_Plan','CAR_QTY')
					AND A.DIVISION_ID = p_division_id
					GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
						, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
						, A.FCST_TYPE, A.CURRENCY, A.MEASURE, A.PLANT_SITE_ID
						, A.YYYYMM, B.ATTRIBUTE1
						--[C20201125-000012] COMPANY_ID 변경(Site -> Sales Site Project Model)
						--, NVL(C.COMPANY_ID, NULL)
						, NVL(B.SALES_COMPANY, '-')
						, CASE WHEN A.DIVISION_ID <> '40' THEN A.DEPT_ID ELSE NULL END
						, NVL(A.ITEM_USE, '/'), NVL(A.END_CUSTOMER, '/'), A.CELL_PROD_SITE; --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				END IF;
			ELSIF p_action_type = 'CP' THEN
				-- NODATAGUARD 2026-08-10: 무방비 SELECT INTO → 표준 검증 예외로 전환.
				--   원본 버전 헤더가 없으면 ORA-01403 이 그대로 사용자에게 노출되던 결함.
				--   ⚠ 원문에 DIVISION_ID 필터가 없어 동명 버전이 타 division 에 있으면 TOO_MANY_ROWS —
				--      WHERE 절은 원문 보존하고 예외만 안내로 바꾼다(별건 보고).
				BEGIN
				SELECT VERSION_TYPE,
    YYYYMMDD
  INTO v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD
				FROM DM_MDF_VERSION
				WHERE VERSION_NO = p_version_no;
				EXCEPTION
					WHEN NO_DATA_FOUND THEN v_log_type := 'VERSION_NO_INVALID'; RAISE e_validation;
					WHEN TOO_MANY_ROWS THEN v_log_type := 'VERSION_NO_AMBIGUOUS'; RAISE e_validation;
				END;

				-- NODATAGUARD 2026-08-10: 원본 버전에 복사할 행이 없으면 ORA-01403 이 그대로 터지던 결함.
				--   (division 40 REPORT_SP_W 176본 중 데이터 보유 3본 — 사용자가 밟기 쉬운 경로)
				BEGIN
				SELECT A.VERSION_NO, MIN(A.YYYYMMDD)
				  INTO v_cp_VERSION_NO, v_cp_MIN_YYYYMMDD
				FROM DM_PLN_SALES_PLAN_REPORT_C A
				WHERE	A.VERSION_NO = p_version_no
					and A.Cutoff_type = v_cp_CUTOFF_TYPE
					and A.Data_type = '1'
				GROUP BY A.VERSION_NO;
				EXCEPTION
					WHEN NO_DATA_FOUND THEN v_log_type := 'SOURCE_VERSION_EMPTY'; RAISE e_validation;
				END;

				-- 실적 불러오기 처리시, 실적의 시작일자를 CUTOFF 일자를 기준으로 룩업에 세팅된 개월수만큼 전으로 가서 가져온다.

				SELECT TO_NUMBER(SEGMENT3)
				  INTO V_MON_CNT
				FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
				WHERE LOOKUP_TYPE = 'DMF0044_CONFIG'
					AND SEGMENT1 = P_DIVISION_ID
					AND SEGMENT2 = 'RESULT_START_PERIOD';

				v_cp_MIN_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(v_cp_CUTOFF_YYYYMMDD, 'YYYYMMDD'), V_MON_CNT * -1), 'YYYYMMDD');
				-- ----------------------------------------------------------------------------------------------------
				BEGIN
					-- 실적불러오기 선택을 하지 않은 순수한 복사시에만 기존 마스터 그대로 유지가 가능함. 아니면 항상 마스터 최신화 적용됨
					IF ( P_UPDATE_YN <> 'Y' AND d_Result_Date IS NULL) THEN
						INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
							 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
							 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
							 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
							 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
							 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
							 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
							 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
							 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
							 -- 2021.7.23
							 , SOLDTO_CUST_REPORT
							 , OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
							 , FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
							 , APPLICATION_GR, COUNTRY_KR_NAME, ROUTE
							 , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), V_NEW_VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
							 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
							 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
							 , A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(M.O_MEASURE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
							 , NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(A.QTY, 0), p_created_by, SYSDATE
							 , p_created_by, SYSDATE, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3
							 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
							 , A.ATTRIBUTE9, A.ATTRIBUTE10, A.COMPANY_ID
							 , A.SOLDTO_CUST_REPORT
							 , A.OWNER_NAME, A.CUST_GROUP_DTL, A.PRODUCT_DETAILS, A.FORECAST_INFO_SPEC, A.NICK_NAME
							 , A.FORECAST_INFO_CELL_MODEL, A.FORECAST_INFO_CELL_PACK_COUNT, A.FORECAST_INFO_BIZ_TYPE, A.COMPANY_NAME, A.APPLICATION
							 , A.APPLICATION_GR, A.COUNTRY_KR_NAME, A.ROUTE
							 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
						FROM   DM_PLN_SALES_PLAN_REPORT_C A
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'PLAN' AND M.CALC_YN = '-'
						WHERE A.VERSION_NO = p_version_no
							AND A.DATA_TYPE = '1'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD > NVL(d_Result_Date, '/'); -- 미래구간
					ELSE
						INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
							 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
							 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
							 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
							 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
							 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
							 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
							 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
							 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
							 -- 2021.7.23
							 , SOLDTO_CUST_REPORT
							 , OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
							 , FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
							 , APPLICATION_GR, COUNTRY_KR_NAME, ROUTE
							 , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), V_NEW_VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
							 , NVL(CASE WHEN LK1.SEGMENT1 IS NULL  THEN v_ETC_DEPARTMENT_ID ELSE A.DEPARTMENT_ID END, '/') AS DEPARTMENT_ID
							 , NVL(CASE WHEN LK1.SEGMENT1 IS NULL  THEN v_ETC_DEPARTMENT_NAME ELSE LK1.SEGMENT2 END, '/') AS DEPARTMENT_NAME
							 , NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(LK2.SEGMENT2),''), '/') AS DEPT_NAME, NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
							 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
							 , A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(M.O_MEASURE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
							 , NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(A.QTY, 0), p_created_by, SYSDATE
							 , p_created_by, SYSDATE
							 , CASE WHEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ IS NOT NULL THEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ ELSE '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ END
							 , A.ATTRIBUTE2, A.ATTRIBUTE3
							 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
							 , A.ATTRIBUTE9, A.ATTRIBUTE10, A.COMPANY_ID
							 , B.ATTRIBUTE1 AS SOLDTO_CUST_REPORT
							 , FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' )		 AS OWNER_NAME
							 , B.CUST_GROUP_DTL
							 , CASE WHEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ IS NOT NULL THEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ ELSE '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ END AS PRODUCT_DETAILS
							 , C.FORECAST_INFO_SPEC, C.NICK_NAME
							 , NULL/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→NULL*/ AS FORECAST_INFO_CELL_MODEL, C.FORECAST_INFO_CELL_PACK_COUNT, C.FORECAST_INFO_BIZ_TYPE
							 , D.SEGMENT2, B.APPLICATION, NULL/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→NULL*/ AS APPLICATION_GR, F.COUNTRY_KR_NAME, B.ROUTE
							 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
						FROM   DM_PLN_SALES_PLAN_REPORT_C A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
						LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V C ON A.ITEM_ID = C.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY'
						LEFT OUTER JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
						LEFT OUTER JOIN SCM_MST_COUNTRY F ON E.COUNTRY = F.COUNTRY
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'PLAN' AND M.CALC_YN = '-'
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT'
													 ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END AND LK1.VALID_YN = 'Y' AND LK1.SEGMENT3 = 'Y'
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK2 ON A.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2'
													 ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END AND LK2.VALID_YN = 'Y'
						WHERE A.VERSION_NO = p_version_no
							AND A.DATA_TYPE = '1'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD > NVL(d_Result_Date, '/'); -- 미래구간

					END IF;
					-- --------
					--UNION ALL -- 여기부터는 실적구간
					-- --------
					BEGIN

						INSERT INTO GT_DMF0_VERSION_COPY (DIVISION_ID, VERSION_NO,CUTOFF_TYPE,CUTOFF_YYYYMMDD,PROJECT_CODE,SCM_SITE_ID,ITEM_ID
								, DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY, COMPANY_ID, SOLDTO_CUST_REPORT
								, CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, M.O_MEASURE AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(QTY) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'RESULT' AND M.CALC_YN = '-'
						WHERE	A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD <= d_Result_Date   -- 과거실적구간으로 추출
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD >= v_cp_MIN_YYYYMMDD
							AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'), M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						-- ------
						UNION ALL -- 실적은 SalesAmt_USD 가 없어서 생성해준다.
						-- ------
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, 'SalesAmt_USD' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(CASE	WHEN NVL(FP.EXCHANGE_PRICE,0) = 0 THEN 0
										ELSE A.QTY/NVL(FP.EXCHANGE_PRICE,0)
										END) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						LEFT OUTER JOIN DM_PLN_SALES_REPORT_EXCHANGE_C FP
								 ON A.DIVISION_ID = FP.DIVISION_ID AND SUBSTR(A.YYYYMMDD,1,6) || '01' = FP.YYYYMMDD AND FP.UNIT_CURRENCY = 'USD' AND FP.VERSION_NO = V_NEW_VERSION_NO
						WHERE	A.MEASURE = 'SalesAmt_KRW'
							AND A.CURRENCY <> 'USD'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD <= d_Result_Date   -- 과거실적구간으로 추출
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD >= v_cp_MIN_YYYYMMDD
							AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'),  A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						-- ------
						UNION ALL -- 실적은 SalesAmt_USD 가 없어서 생성해준다.	( LOC = USD )
						-- ------
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, 'SalesAmt_USD' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(A.QTY) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						WHERE	A.MEASURE = 'SalesAmt_LOC'
							AND A.CURRENCY = 'USD'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD <= d_Result_Date   -- 과거실적구간으로 추출
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD >= v_cp_MIN_YYYYMMDD
							AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'),  A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						--Start [C20201014-000094] 82 사업부 비물동 구분코드 추가
						-- ------
						UNION ALL
						-- ------
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, M.O_MEASURE AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(QTY) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID'
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'RESULT' AND M.CALC_YN = '-'
						WHERE	A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD   <= d_Result_Date   -- 과거실적구간으로 추출
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD	 >= v_cp_MIN_YYYYMMDD
							AND D.COMPANY_ID IS NULL
							AND A.DIVISION_ID = '82'
							AND NVL(A.QTY,0) <> 0
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'), M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						-- ------
						UNION ALL -- 실적은 SalesAmt_USD 가 없어서 생성해준다.
						-- ------
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, 'SalesAmt_USD' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(CASE	WHEN NVL(FP.EXCHANGE_PRICE,0) = 0 THEN 0
										ELSE A.QTY/NVL(FP.EXCHANGE_PRICE,0)
										END) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID'
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						LEFT OUTER JOIN DM_PLN_SALES_REPORT_EXCHANGE_C FP
								 ON A.DIVISION_ID = FP.DIVISION_ID AND SUBSTR(A.YYYYMMDD,1,6) || '01' = FP.YYYYMMDD AND FP.UNIT_CURRENCY = 'USD' AND FP.VERSION_NO = V_NEW_VERSION_NO
						WHERE	A.MEASURE = 'SalesAmt_KRW'
							AND A.CURRENCY <> 'USD'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD	 <= d_Result_Date
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD	 >= v_cp_MIN_YYYYMMDD
							AND D.COMPANY_ID IS NULL
							AND A.DIVISION_ID = '82'
							AND NVL(A.QTY,0) <> 0
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'),  A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						-- ------
						UNION ALL -- 실적은 SalesAmt_USD 가 없어서 생성해준다. ( LOC = USD )
						-- ------
						SELECT A.DIVISION_ID, v_cp_VERSION_NO, v_cp_CUTOFF_TYPE, v_cp_CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
							 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY, 'SalesAmt_USD' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
							 , SUM(A.QTY) AS QTY
							 , A.COMPANY_ID, B.ATTRIBUTE1
							 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							 --,'-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
							, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						FROM DM_PLN_SALES_PLAN_RESULT A
						LEFT OUTER JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
						JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID'
						LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
						LEFT OUTER JOIN DM_PLN_SALES_REPORT_EXCHANGE_C FP
								 ON A.DIVISION_ID = FP.DIVISION_ID AND SUBSTR(A.YYYYMMDD,1,6) || '01' = FP.YYYYMMDD AND FP.UNIT_CURRENCY = 'USD' AND FP.VERSION_NO = V_NEW_VERSION_NO
						WHERE	A.MEASURE = 'SalesAmt_LOC'
							AND A.CURRENCY = 'USD'
							AND A.DIVISION_ID = p_division_id
							AND A.YYYYMMDD	 <= d_Result_Date
							AND d_Result_Date IS NOT NULL
							AND A.YYYYMMDD	 >= v_cp_MIN_YYYYMMDD
							--AND C.LOOKUP_TYPE IS NULL
							AND D.COMPANY_ID IS NULL
							AND A.DIVISION_ID = '82'
							AND NVL(A.QTY,0) <> 0
						GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
							, A.FCST_TYPE, A.INCOTERMS, NVL(A.CURRENCY, '/'),  A.PLANT_SITE_ID, A.YYYYMMDD, A.COMPANY_ID, B.ATTRIBUTE1
							, A.CELL_PROD_SITE_ID;			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						--End [C20201014-000094] 82 사업부 비물동 구분코드 추가

						-- RTF_SCP 처리
						IF p_division_id like '81%' THEN
							INSERT INTO GT_DMF0_VERSION_COPY (DIVISION_ID, VERSION_NO,CUTOFF_TYPE,CUTOFF_YYYYMMDD,PROJECT_CODE,SCM_SITE_ID,ITEM_ID
									  , DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY,MEASURE,PLANT_SITE_ID,YYYYMMDD,QTY, COMPANY_ID, SOLDTO_CUST_REPORT
									  , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
							SELECT A.DIVISION_ID, A.VERSION_NO, 'REPORT_SP_W' as Cutoff_Type, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
								 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, '' AS CURRENCY, M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
								 , SUM(A.QTY) AS QTY
								 , B.SALES_COMPANY AS COMPANY_ID
								 , B.ATTRIBUTE1
								 --, '' AS CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
								 --, '-' AS CELL_PROD_SITE --[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
								, A.CELL_PROD_SITE_ID			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
							FROM DM_PLN_MKT_FCST_RESULT_C A
							JOIN SCM_MST_SITE_ITEM B  ON B.DIVISION_ID = A.DIVISION_ID AND B.PROJECT_CODE = A.PROJECT_CODE AND B.SCM_SITE_ID = A.SCM_SITE_ID AND B.ITEM_ID = A.ITEM_ID
							LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C  ON A.ITEM_ID = C.SEGMENT1 AND A.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID' -- 20190906 Sales Plan에서 기타매출 등록한 것 제외
							LEFT OUTER JOIN SCM_MST_COMPANY_SN D  ON A.SCM_SITE_ID = D.COMPANY_ID
							JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
							JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'PLAN' AND M.CALC_YN = '-' AND M.SRC_TABLE = 'DM_PLN_MKT_FCST_RESULT_C'
							WHERE	A.VERSION_NO = 'MF_'  ||  SUBSTR(p_version_no,4,15)
								AND A.DIVISION_ID = p_division_id
								AND A.YYYYMMDD < d_Result_Date   -- 과거실적구간으로 추출
								AND d_Result_Date IS NOT NULL
								AND A.YYYYMMDD >= v_cp_MIN_YYYYMMDD
								AND C.LOOKUP_TYPE IS NULL
								AND D.COMPANY_ID IS NULL
							GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, B.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
								, A.FCST_TYPE, A.INCOTERMS, M.O_MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
								, B.SALES_COMPANY
								, B.ATTRIBUTE1
								, A.CELL_PROD_SITE_ID;			--[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
						END IF;
					END;

				END;

			END IF;

			-- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- DIV 별로 키값에 맞춰서 묶어준다. ( YYYYMMDD 때문에 단순 MAX 처리로는 안되고, 키값전체를 이용해서 정리해줘야 한다. )
			-- Scm_site_id 와 Project Code 를 뭉친다.
			-- ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			IF P_DIVISION_ID = '40' THEN

				-- [PJ2024-50611] 소형 매출 프로세스 개선
				IF (p_action_type IN ('CR') AND V_SP_BP = 'SP') THEN
				/*
					-- TODO:GTT:GT_DMF0_VERSION_COPY_RTF_ALLOC (구 RTF 로직 — 주석 보존)
					INSERT INTO GT_DMF0_VERSION_COPY_RTF_ALLOC
					SELECT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
						 , DOM_EXP, FCST_TYPE, INCOTERMS, CURRENCY, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
						 , COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, ITEM_USE, END_CUSTOMER, CELL_PROD_SITE
					FROM GT_DMF0_VERSION_COPY
					WHERE DIVISION_ID = P_DIVISION_ID
					AND   MEASURE IN ('RTF_SYS_RP','VMI_In_Plan','SalesAmt_KRW','SalesAmt_LOC','SalesAmt_USD');

					-- TODO:GTT:GT_DMF0_VERSION_COPY_RTF_ALLOC (구 RTF 로직 — 주석 보존)
					INSERT INTO GT_DMF0_VERSION_COPY_RTF_ALLOC
					SELECT	 DISTINCT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
							,DOM_EXP, FCST_TYPE, INCOTERMS, CURRENCY, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, COMPANY_ID, SOLDTO_CUST_REPORT
							,DEPT_ID,ITEM_USE, END_CUSTOMER, CELL_PROD_SITE
					FROM GT_DMF0_VERSION_COPY_RTF_ALLOC;

					DELETE GT_DMF0_VERSION_COPY
					WHERE DIVISION_ID	= P_DIVISION_ID
					AND   YYYYMMDD		> NVL(d_Result_Date, '-')
					AND   MEASURE IN ('RTF_SYS_RP','VMI_In_Plan','SalesAmt_KRW','SalesAmt_LOC','SalesAmt_USD');

					INSERT INTO GT_DMF0_VERSION_COPY
					(
						   DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
						 , DOM_EXP, FCST_TYPE, INCOTERMS, CURRENCY, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
						 , COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, ITEM_USE, END_CUSTOMER, CELL_PROD_SITE
					)
					SELECT A.DIVISION_ID, A.VERSION_NO,A.CUTOFF_TYPE,A.CUTOFF_YYYYMMDD,A.PROJECT_CODE,A.SCM_SITE_ID,A.ITEM_ID
							,A.DOM_EXP,A.FCST_TYPE,A.INCOTERMS,A.CURRENCY,A.MEASURE
							,B.PLANT_SITE_ID
							,B.YYYYMMDD
							,B.QTY, A.COMPANY_ID, A.SOLDTO_CUST_REPORT
							,A.DEPT_ID,A.ITEM_USE, A.END_CUSTOMER
							--, B.FROM_SITE_ID AS CELL_PROD_SITE
							,B.CELL_PROD_SITE_ID AS CELL_PROD_SITE
					FROM GT_DMF0_VERSION_COPY_RTF_ALLOC A
					--INNER JOIN DM_PLN_RTF_ALLOCATION_C B
					--[PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선 : CELL_PROD_SITE_ID 추가, 주요 테이블 변경
					 INNER JOIN DM_PLN_SALES_PLAN_C B
					ON	A.DIVISION_ID	= B.DIVISION_ID
					AND A.PROJECT_CODE  = B.PROJECT_CODE
					AND A.SCM_SITE_ID   = B.SCM_SITE_ID
					AND A.ITEM_ID	    = B.ITEM_ID
					AND A.DOM_EXP	    = B.DOM_EXP
					AND A.FCST_TYPE     = B.FCST_TYPE
					AND A.INCOTERMS     = B.INCOTERMS
					AND A.MEASURE		= B.MEASURE
					AND A.YYYYMMDD		= B.YYYYMMDD
					WHERE A.DIVISION_ID = P_DIVISION_ID
					AND   A.YYYYMMDD	> NVL(d_Result_Date, '-')
					AND   B.MEASURE IN ('RTF_SYS_RP','VMI_In_Plan','SalesAmt_KRW','SalesAmt_LOC','SalesAmt_USD')
					AND   B.VERSION_NO = p_version_no
					AND   B.CUTOFF_TYPE	= v_version_type;
					*/
					--[PJ2024-50611] Sales Report 생성 시 Catcu_Up 수량 더해줌 START
					MERGE INTO GT_DMF0_VERSION_COPY A
							USING GT_DMF0_PLAN_C_CATCHUP B
							ON   (	A.DIVISION_ID = B.DIVISION_ID
								AND A.VERSION_NO = B.VERSION_NO
								AND A.CUTOFF_TYPE= B.CUTOFF_TYPE
								AND A.CUTOFF_YYYYMMDD= B.CUTOFF_YYYYMMDD
								AND A.PROJECT_CODE = B.PROJECT_CODE
								AND A.SCM_SITE_ID = B.SCM_SITE_ID
								AND A.ITEM_ID = B.ITEM_ID
								AND A.DOM_EXP = B.DOM_EXP
								AND A.FCST_TYPE= B.FCST_TYPE
								AND A.INCOTERMS = B.INCOTERMS
								AND A.CURRENCY = B.CURRENCY
								AND A.MEASURE = B.MEASURE
								AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
								AND A.YYYYMMDD = B.YYYYMMDD
								AND A.COMPANY_ID = B.COMPANY_ID
								AND A.SOLDTO_CUST_REPORT = B.SOLDTO_CUST_REPORT
								AND A.CELL_PROD_SITE = B.CELL_PROD_SITE
								)
							WHEN MATCHED THEN
								UPDATE SET
									A.QTY = A.QTY + B.QTY
							WHEN NOT MATCHED THEN
								INSERT
								(
								   DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
								 , DOM_EXP, FCST_TYPE, INCOTERMS, CURRENCY, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
								 , COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, ITEM_USE, END_CUSTOMER, CELL_PROD_SITE
									)
								VALUES
								(
									B.DIVISION_ID
									,B.VERSION_NO
									,B.CUTOFF_TYPE
									,B.CUTOFF_YYYYMMDD
									,B.PROJECT_CODE
									,B.SCM_SITE_ID
									,B.ITEM_ID
									,B.DOM_EXP
									,B.FCST_TYPE
									,B.INCOTERMS
									,B.CURRENCY
									,B.MEASURE
									,B.PLANT_SITE_ID
									,B.YYYYMMDD
									,B.QTY
									,B.COMPANY_ID
									,B.SOLDTO_CUST_REPORT
									,'','',''
									,B.CELL_PROD_SITE
								);
						--[PJ2024-50611] Sales Report 생성 시 Catcu_Up 수량 더해줌 END
				END IF;

				-- 월별로 하나의 날짜로 변환시킴
				UPDATE GT_DMF0_VERSION_COPY
				SET YYYYMMDD = SUBSTR(YYYYMMDD, 1, 6)  ||  '01';


				-- VMI 의 경우 통화가 빠진 데이터가 있어서 여기서 업데이트 해준다.
				MERGE INTO GT_DMF0_VERSION_COPY A
				USING ( SELECT PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY, COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, END_CUSTOMER
						FROM GT_DMF0_VERSION_COPY
						WHERE CURRENCY IS NOT NULL
						GROUP BY PROJECT_CODE,SCM_SITE_ID,ITEM_ID,DOM_EXP,FCST_TYPE,INCOTERMS,CURRENCY, COMPANY_ID, SOLDTO_CUST_REPORT, DEPT_ID, END_CUSTOMER
					) B ON ( A.PROJECT_CODE = B.PROJECT_CODE
						AND A.SCM_SITE_ID = B.SCM_SITE_ID
						AND A.ITEM_ID = B.ITEM_ID
						AND A.DOM_EXP = B.DOM_EXP
						AND A.FCST_TYPE = B.FCST_TYPE
						AND A.INCOTERMS = B.INCOTERMS
						AND A.COMPANY_ID = B.COMPANY_ID
						AND NVL(A.SOLDTO_CUST_REPORT, '/') = NVL(B.SOLDTO_CUST_REPORT, '/')
						AND A.DEPT_ID = B.DEPT_ID
						AND NVL(A.END_CUSTOMER, '/') = NVL(B.END_CUSTOMER, '/') )
				WHEN MATCHED THEN UPDATE SET A.CURRENCY = B.CURRENCY
					WHERE A.CURRENCY IS NULL;

				MERGE INTO GT_DMF0_VERSION_COPY A
				USING ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, MAX(CURRENCY) AS CURRENCY, DOM_EXP, FCST_TYPE, INCOTERMS
						FROM DM_PLN_CFM_SELLING_PRICE A
						WHERE YYYYMMDD > NVL(d_Result_Date, '-') AND A.DIVISION_ID = P_DIVISION_ID
						GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
					) B ON ( A.DIVISION_ID = B.DIVISION_ID
						AND A.PROJECT_CODE = B.PROJECT_CODE
						AND A.SCM_SITE_ID = B.SCM_SITE_ID
						AND A.ITEM_ID = B.ITEM_ID
						AND A.DOM_EXP = B.DOM_EXP
						AND A.FCST_TYPE = B.FCST_TYPE
						AND A.INCOTERMS = B.INCOTERMS )
				WHEN MATCHED THEN UPDATE SET A.CURRENCY = B.CURRENCY
					WHERE A.CURRENCY IS NULL;

				INSERT INTO GT_DMF0_REPORT (CUTOFF_TYPE, CUTOFF_YYYYMMDD
						  , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
						  , CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP
						  , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
						  , PLANT_SITE_ID, YYYYMMDD, CURRENCY, QTY, COMPANY_ID, ATTRIBUTE1, SOLDTO_CUST_REPORT
						  , APPLICATION, CUST_GROUP_DTL, COUNTRY
						  , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
						, D.UPPER_DEPT_ID AS DEPARTMENT_ID, E.SEGMENT2 AS DEPARTMENT_NAME
						, D.DEPT_ID AS DEPT_ID, F.SEGMENT2 AS DEPT_NAME
						, '/'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/	AS CUST_REPORT    -- (DMS)판매처
						, NVL(NULLIF(RTRIM(B.attribute2),''), '/')	AS END_CUST_REPORT  -- (DMS)고객군
						, '/'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/	AS PRODUCT_GROUP
						, B.PROJECT_CODE, A.SCM_SITE_ID
						, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE
						, A.PLANT_SITE_ID, A.YYYYMMDD, A.CURRENCY
						--[C20210304-000196] 소형 부자재 및 전극 매출 수량 표기(biz_type is null 제외)
						/*, CASE WHEN V.FORECAST_INFO_BIZ_TYPE IS NULL AND ( A.MEASURE LIKE '%RTF%' OR A.MEASURE LIKE '%MKT_FCST%' ) THEN 0
								ELSE A.QTY END AS QTY*/
						, A.QTY AS QTY
						, NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
						, CASE WHEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ IS NOT NULL THEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ ELSE '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ END	AS ATTRIBUTE1
						, NVL(NULLIF(RTRIM(A.SOLDTO_CUST_REPORT),''), '/')
						, B.APPLICATION, B.CUST_GROUP_DTL
						, G.COUNTRY
						, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				FROM GT_DMF0_VERSION_COPY A
				JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
				-- [hook#150 2026-09-06 AJS] AS-IS: JOIN SCM_MST_SSO_USER_INFO C ON SUBSTR(B.OWNER, 1, CASE WHEN INSTR(B.OWNER, ',') > 0 THEN INSTR(B.OWNER, ',')-1 ELSE LENGTH(B.OWNER) END) = C.USER_ID
				JOIN SCM_MST_SSO_DEPT_INFO D ON B.DEPT_ID = D.DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: C.DEPT_ID = OWNER 경유 SSO_USER_INFO)
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND E.VALID_YN = 'Y'
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2' AND F.VALID_YN = 'Y'
				JOIN SCM_MST_SITE G ON B.DIVISION_ID = G.DIVISION_ID AND B.SCM_SITE_ID = G.SCM_SITE_ID
				LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V V ON A.ITEM_ID = V.ITEM_ID;

				-- 1~3 담당 외에는 기타로 묶는다.
				UPDATE GT_DMF0_REPORT A
				SET A.DEPARTMENT_ID = v_ETC_DEPARTMENT_ID
				WHERE NOT EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
					WHERE A.DEPARTMENT_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND B.SEGMENT3 = 'Y' AND B.VALID_YN = 'Y' );

--SELECT * FROM GT_DMF0_REPORT WHERE MEASURE = 'MKT_FCST'
				-- 인서트
				-- DYNSAMP 2026-08-10: GT_DMF0_REPORT 는 GTT 라 통계가 없다(NUM_ROWS NULL).
				--   optimizer_dynamic_sampling=2 로는 L8310~8323 자기조인 카디널리티가 46배 과소추정되어
				--   (EST 13,635 / ACT 633,479) NESTED LOOPS 로 폭주한다 → BP CREATE 60분+ 미완.
				--   레벨 11(AUTO)로 파싱 시 충분히 샘플링. 딕셔너리 기록·커밋이 없어 트랜잭션에 안전하다.
				INSERT /*+ DYNAMIC_SAMPLING(11) */ INTO DM_PLN_SALES_PLAN_REPORT_C (
					  DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
					, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID
					, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
					, PLANT_SITE_ID,YYYYMMDD,CURRENCY,QTY, COMPANY_ID
					, CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1
					-- 2021.7.23
					, SOLDTO_CUST_REPORT
					, OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
					, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
					, APPLICATION_GR, COUNTRY_KR_NAME, ROUTE
					, ATTRIBUTE3	-- CELL MODEL
					, CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(P_DIVISION_ID),''), '/') AS DIVISION_ID, V_NEW_VERSION_NO AS VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/')
					 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
					 , NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(A.MEASURE),''), '/')
					 , NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(A.QTY, 0), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/')
					 , p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE, A.ATTRIBUTE1
					 , B.ATTRIBUTE1 AS SOLDTO_CUST_REPORT
					 , FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' ) AS OWNER_NAME
					 , A.CUST_GROUP_DTL
					 , CASE WHEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ IS NOT NULL THEN '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ ELSE '-'/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→센티널 RPTGRP-STUB 2026-08-10*/ END AS PRODUCT_DETAILS
					 , C.FORECAST_INFO_SPEC, C.NICK_NAME
					 , NULL/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→NULL*/ AS FORECAST_INFO_CELL_MODEL, C.FORECAST_INFO_CELL_PACK_COUNT, C.FORECAST_INFO_BIZ_TYPE
					 , D.SEGMENT2, A.APPLICATION, NULL/*SITE_ITEM.REPORT_GROUP 미존재(Oracle마이그레이션)→NULL*/ AS APPLICATION_GR, F.COUNTRY_KR_NAME, B.ROUTE
					 , B.ATTRIBUTE5 AS CELL_MODEL
					 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					SELECT '1' AS DATA_TYPE, P_DIVISION_ID AS DIVISION_ID, B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
							, A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME, A.CUST_REPORT
							, A.END_CUST_REPORT, A.PRODUCT_GROUP
							, FN_SCM_SPLIT(A.MIX_VAL, 1, '^') AS PROJECT_CODE
							, FN_SCM_SPLIT(A.MIX_VAL, 2, '^') AS SCM_SITE_ID
							, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, B.MEASURE
							, A.PLANT_SITE_ID, B.YYYYMMDD, A.CURRENCY, SUM(B.QTY) as QTY, A.COMPANY_ID
							, B.ATTRIBUTE1
							, A.APPLICATION, A.CUST_GROUP_DTL
							, A.COUNTRY
							, B.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM (
						-- 병합처리를 위해 키 중 병합되지 않은 키만 분리 ( 하지만 SCM_SITE_ID-PROJECT_CODE-ITEM_ID 간의 관계는 유지되어야 함
						--- 그냥 MAX로 조합할 경우 SCM_MST_SITE_ITEM 에 JOIN 이 안됨 )
						SELECT A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
							, A.CUST_REPORT, A.END_CUST_REPORT, A.PRODUCT_GROUP, A.ITEM_ID, A.CURRENCY, A.COMPANY_ID, A.SOLDTO_CUST_REPORT
							, MAX((NVL(A.PROJECT_CODE, '/') || '^' || NVL(A.SCM_SITE_ID, '/'))) AS MIX_VAL
							, MAX(A.DOM_EXP) AS DOM_EXP
							, MAX(A.FCST_TYPE) AS FCST_TYPE, MAX(A.INCOTERMS) AS INCOTERMS, MAX(A.PLANT_SITE_ID) AS PLANT_SITE_ID
							, A.APPLICATION, A.CUST_GROUP_DTL, A.COUNTRY
						FROM GT_DMF0_REPORT A
						LEFT OUTER JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
						LEFT OUTER JOIN SCM_MST_COUNTRY C ON B.COUNTRY = C.COUNTRY
						GROUP BY A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
							, A.CUST_REPORT, A.END_CUST_REPORT, A.PRODUCT_GROUP, A.ITEM_ID, A.CURRENCY, A.COMPANY_ID, A.SOLDTO_CUST_REPORT
							, A.APPLICATION, A.CUST_GROUP_DTL, A.COUNTRY
						) A
					JOIN GT_DMF0_REPORT B ON A.DEPARTMENT_ID = B.DEPARTMENT_ID
							AND A.DEPARTMENT_NAME = B.DEPARTMENT_NAME
							AND A.DEPT_ID = B.DEPT_ID
							AND A.DEPT_NAME = B.DEPT_NAME
							AND A.CUST_REPORT = B.CUST_REPORT
							AND A.END_CUST_REPORT = B.END_CUST_REPORT
							AND A.PRODUCT_GROUP = B.PRODUCT_GROUP
							AND A.ITEM_ID = B.ITEM_ID
							AND A.CURRENCY = B.CURRENCY
							AND A.COMPANY_ID = B.COMPANY_ID
							AND A.SOLDTO_CUST_REPORT = B.SOLDTO_CUST_REPORT
							AND A.APPLICATION = B.APPLICATION
							AND A.CUST_GROUP_DTL = B.CUST_GROUP_DTL
							AND A.COUNTRY = B.COUNTRY
					GROUP BY B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
							, A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
							, A.CUST_REPORT, A.END_CUST_REPORT, A.PRODUCT_GROUP
							, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, B.MEASURE
							, A.PLANT_SITE_ID, B.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, B.ATTRIBUTE1
							, A.APPLICATION, A.CUST_GROUP_DTL
							, A.MIX_VAL, A.COUNTRY, B.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					) A
					LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
					LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V C ON A.ITEM_ID = C.ITEM_ID
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY'
					LEFT OUTER JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
					LEFT OUTER JOIN SCM_MST_COUNTRY F ON A.COUNTRY = F.COUNTRY;

			ELSIF P_DIVISION_ID like '81%' THEN
				IF V_SP_BP = 'SP' THEN
					-- 자동차는 팀 없는 건은 전송하지 않음.
					INSERT INTO GT_DMF0_REPORT (CUTOFF_TYPE, CUTOFF_YYYYMMDD
							  , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
							  , PROJECT_CODE, FCST_TYPE, PLANT_SITE_ID, ITEM_ID, SCM_SITE_ID
							  , INCOTERMS, CURRENCY
							  , MEASURE, YYYYMMDD, QTY
							  , DOM_EXP, COMPANY_ID
							  , CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP
							  , CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
						 , D.UPPER_DEPT_ID AS DEPARTMENT_ID, NVL(NULLIF(RTRIM(E.SEGMENT2),''), '/') AS DEPARTMENT_NAME
						 , D.DEPT_ID AS DEPT_ID, NVL(NULLIF(RTRIM(F.SEGMENT2),''), '/') AS DEPT_NAME
						 , NVL(NULLIF(RTRIM(B.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
						 , NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
						 , A.MEASURE, A.YYYYMMDD, A.QTY
						 , NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
						 , ''	AS CUST_REPORT    -- (DMS)판매처
						 , ''	AS END_CUST_REPORT  --
						 , ''	AS PRODUCT_GROUP
						 , A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM GT_DMF0_VERSION_COPY A
					JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
					JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
					JOIN SCM_MST_SSO_DEPT_INFO D ON B.DEPT_ID = D.DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: C.DEPT_ID = SCM_MST_SITE.DEPT_ID)
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT'  ||  p_division_id
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2'  ||  p_division_id
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL G ON A.FCST_TYPE = G.SEGMENT1 AND G.LOOKUP_TYPE = 'SALES_TYPE_CODE' AND G.SEGMENT4 <> 'FREE';
				ELSE
					INSERT INTO GT_DMF0_REPORT (CUTOFF_TYPE, CUTOFF_YYYYMMDD
							, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
							, PROJECT_CODE, FCST_TYPE, PLANT_SITE_ID, ITEM_ID, SCM_SITE_ID
							, INCOTERMS, CURRENCY
							, MEASURE, YYYYMMDD, QTY
							, DOM_EXP, COMPANY_ID
							, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP
							, CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
							, D.UPPER_DEPT_ID AS DEPARTMENT_ID, NVL(NULLIF(RTRIM(E.SEGMENT2),''), '/') AS DEPARTMENT_NAME
							, D.DEPT_ID AS DEPT_ID, NVL(NULLIF(RTRIM(F.SEGMENT2),''), '/') AS DEPT_NAME
							, NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
							, NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
							, A.MEASURE, A.YYYYMMDD, A.QTY
							, NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
							, ''	AS CUST_REPORT    -- (DMS)판매처
							, A.END_CUSTOMER	AS END_CUST_REPORT  --
							, ''	AS PRODUCT_GROUP
						    , A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM GT_DMF0_VERSION_COPY A
					JOIN SCM_MST_SSO_DEPT_INFO D ON A.DEPT_ID = D.DEPT_ID
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT'  ||  p_division_id
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2'  ||  p_division_id
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL G ON A.FCST_TYPE = G.SEGMENT1 AND G.LOOKUP_TYPE = 'SALES_TYPE_CODE' AND G.SEGMENT4 <> 'FREE';
				END IF;
--select * from GT_DMF0_MEASURE
--select measure, count(*) from GT_DMF0_VERSION_COPY group by measure
--select measure, count(*) from GT_DMF0_REPORT group by measure

				-- DYNSAMP 2026-08-10: GT_DMF0_REPORT 는 GTT 라 통계가 없다(NUM_ROWS NULL).
				--   optimizer_dynamic_sampling=2 로는 L8310~8323 자기조인 카디널리티가 46배 과소추정되어
				--   (EST 13,635 / ACT 633,479) NESTED LOOPS 로 폭주한다 → BP CREATE 60분+ 미완.
				--   레벨 11(AUTO)로 파싱 시 충분히 샘플링. 딕셔너리 기록·커밋이 없어 트랜잭션에 안전하다.
				INSERT /*+ DYNAMIC_SAMPLING(11) */ INTO DM_PLN_SALES_PLAN_REPORT_C (
					  DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
					, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID
					, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
					, PLANT_SITE_ID,YYYYMMDD,CURRENCY,QTY, COMPANY_ID
					, CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE
					, CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT '1' AS DATA_TYPE, NVL(NULLIF(RTRIM(P_DIVISION_ID),''), '/'), V_NEW_VERSION_NO, B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
						, NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/')
						, NVL(NULLIF(RTRIM(B.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(B.END_CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(B.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
						, NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(B.MEASURE),''), '/')
						, NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(SUBSTR(B.YYYYMMDD, 1, 6)  ||  '01', '/') AS YYYYMMDD, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(SUM(B.QTY), 0) as QTY, NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/')
						,'mdf_batch',SYSDATE,'mdf_batch',SYSDATE
						, NVL(B.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					-- 병합처리를 위해 키 중 병합되지 않은 키만 분리
					SELECT A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, A.PROJECT_CODE, A.FCST_TYPE, A.PLANT_SITE_ID, A.ITEM_ID, A.SCM_SITE_ID
						, A.INCOTERMS, A.CURRENCY
						, MAX(A.DOM_EXP) AS DOM_EXP, MAX(A.COMPANY_ID) AS COMPANY_ID
					FROM GT_DMF0_REPORT A
					GROUP BY A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, A.PROJECT_CODE, A.FCST_TYPE, A.PLANT_SITE_ID, A.ITEM_ID, A.SCM_SITE_ID
						, A.INCOTERMS, A.CURRENCY
					) A
				JOIN GT_DMF0_REPORT B ON A.DEPARTMENT_ID = B.DEPARTMENT_ID
						AND A.DEPARTMENT_NAME = B.DEPARTMENT_NAME
						AND A.DEPT_ID = B.DEPT_ID
						AND A.DEPT_NAME = B.DEPT_NAME
						AND A.PROJECT_CODE = B.PROJECT_CODE
						AND A.FCST_TYPE = B.FCST_TYPE
						AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
						AND A.ITEM_ID = B.ITEM_ID
						AND A.SCM_SITE_ID = B.SCM_SITE_ID
						AND A.INCOTERMS = B.INCOTERMS
						AND A.CURRENCY = B.CURRENCY
				GROUP BY B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
						, A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, B.CUST_REPORT, B.END_CUST_REPORT, B.PRODUCT_GROUP, A.PROJECT_CODE, A.SCM_SITE_ID
						, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, B.MEASURE
						, A.PLANT_SITE_ID, SUBSTR(B.YYYYMMDD, 1, 6), A.CURRENCY, A.COMPANY_ID, B.CELL_PROD_SITE; --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청

			ELSIF P_DIVISION_ID = '82' THEN

				IF V_SP_BP = 'SP' THEN
					INSERT INTO GT_DMF0_REPORT (CUTOFF_TYPE, CUTOFF_YYYYMMDD
							, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
							, PROJECT_CODE, FCST_TYPE, PLANT_SITE_ID, ITEM_ID, SCM_SITE_ID
							, INCOTERMS, CURRENCY
							, MEASURE, YYYYMMDD, QTY
							, DOM_EXP, COMPANY_ID
							, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP
							, CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
							, D.UPPER_DEPT_ID AS DEPARTMENT_ID, NVL(NULLIF(RTRIM(E.SEGMENT2),''), '/') AS DEPARTMENT_NAME
							, D.DEPT_ID AS DEPT_ID, NVL(NULLIF(RTRIM(F.SEGMENT2),''), '/') AS DEPT_NAME
							, NVL(NULLIF(RTRIM(B.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
							, NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
							, A.MEASURE, A.YYYYMMDD, A.QTY
							, NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
							, ''	AS CUST_REPORT    -- (DMS)판매처
							, ''	AS END_CUST_REPORT  --
							, ''	AS PRODUCT_GROUP
							, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM GT_DMF0_VERSION_COPY A
					JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
					JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
					JOIN SCM_MST_SSO_DEPT_INFO D ON B.DEPT_ID = D.DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: C.DEPT_ID = SCM_MST_SITE.DEPT_ID)
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT_82'
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2_82'
				    -- ------
					UNION ALL --[C20201014-000094] 82 사업부 비물동 구분코드 추가
					-- ------
					SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					        --[C20201014-000094] 82 사업부 비물동 구분코드 추가 (NVL(D.UPPER_DEPT_ID, NULL),  NVL(D.DEPT_ID, NULL))
							, NVL(NULLIF(RTRIM(D.UPPER_DEPT_ID),''), '/') AS DEPARTMENT_ID, NVL(NULLIF(RTRIM(E.SEGMENT2),''), '/') AS DEPARTMENT_NAME
							, NVL(NULLIF(RTRIM(D.DEPT_ID),''), '/') AS DEPT_ID, NVL(NULLIF(RTRIM(F.SEGMENT2),''), '/') AS DEPT_NAME
							, NVL(NULLIF(RTRIM(B.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
							, NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
							, A.MEASURE, A.YYYYMMDD, A.QTY
							, NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
							, ''	AS CUST_REPORT    -- (DMS)판매처
							, ''	AS END_CUST_REPORT  --
							, ''	AS PRODUCT_GROUP
							, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM GT_DMF0_VERSION_COPY A
					--[C20201014-000094] 82 사업부 비물동 구분코드 추가 (JOIN -> LEFT OUTER JOIN)
					LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
					LEFT OUTER JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
					LEFT OUTER JOIN SCM_MST_SSO_DEPT_INFO D ON B.DEPT_ID = D.DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: C.DEPT_ID = SCM_MST_SITE.DEPT_ID)
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT_82'
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2_82'
					--[C20201014-000094] 82 사업부 비물동 구분코드 추가
					JOIN SCM_ADM_LOOKUP_MASTER_DETAIL G  ON A.ITEM_ID = G.SEGMENT1 AND A.DIVISION_ID = G.SEGMENT3 AND G.LOOKUP_TYPE = 'SALES_PLAN_ITEM_ID'
					WHERE A.DIVISION_ID = '82';
				ELSE
					INSERT INTO GT_DMF0_REPORT (CUTOFF_TYPE, CUTOFF_YYYYMMDD
							, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
							, PROJECT_CODE, FCST_TYPE, PLANT_SITE_ID, ITEM_ID, SCM_SITE_ID
							, INCOTERMS, CURRENCY
							, MEASURE, YYYYMMDD, QTY
							, DOM_EXP, COMPANY_ID
							, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP
							, CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					SELECT A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
							, D.UPPER_DEPT_ID AS DEPARTMENT_ID, NVL(NULLIF(RTRIM(E.SEGMENT2),''), '/') AS DEPARTMENT_NAME
							, D.DEPT_ID AS DEPT_ID, NVL(NULLIF(RTRIM(F.SEGMENT2),''), '/') AS DEPT_NAME
							, A.ITEM_USE AS PROJECT_CODE, '' AS FCST_TYPE, '' AS PLANT_SITE_ID, '' AS ITEM_ID, '' AS SCM_SITE_ID
							, '' AS INCOTERMS, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
							, A.MEASURE, A.YYYYMMDD, A.QTY
							, NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
							, ''	AS CUST_REPORT    -- (DMS)판매처
							, ''	AS END_CUST_REPORT  --
							, ''	AS PRODUCT_GROUP
							, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM GT_DMF0_VERSION_COPY A
					LEFT OUTER JOIN SCM_MST_SSO_DEPT_INFO D ON A.DEPT_ID = D.DEPT_ID
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL E ON D.UPPER_DEPT_ID = E.SEGMENT1 AND E.LOOKUP_TYPE = 'MDF_DEPARTMENT_82'
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL F ON D.DEPT_ID = F.SEGMENT1 AND F.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2_82';

				END IF;

				-- DYNSAMP 2026-08-10: GT_DMF0_REPORT 는 GTT 라 통계가 없다(NUM_ROWS NULL).
				--   optimizer_dynamic_sampling=2 로는 L8310~8323 자기조인 카디널리티가 46배 과소추정되어
				--   (EST 13,635 / ACT 633,479) NESTED LOOPS 로 폭주한다 → BP CREATE 60분+ 미완.
				--   레벨 11(AUTO)로 파싱 시 충분히 샘플링. 딕셔너리 기록·커밋이 없어 트랜잭션에 안전하다.
				INSERT /*+ DYNAMIC_SAMPLING(11) */ INTO DM_PLN_SALES_PLAN_REPORT_C (
					  DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					, DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME
					, CUST_REPORT, END_CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID
					, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
					, PLANT_SITE_ID,YYYYMMDD,CURRENCY,QTY, COMPANY_ID
					, CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE
					, CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT '1' AS DATA_TYPE, NVL(NULLIF(RTRIM(P_DIVISION_ID),''), '/'), V_NEW_VERSION_NO, B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
						, NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/')
						, NVL(NULLIF(RTRIM(B.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(B.END_CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(B.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/')
						, NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(B.MEASURE),''), '/')
						, NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(SUBSTR(B.YYYYMMDD, 1, 6)  ||  '01', '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/'), NVL(SUM(B.QTY), 0) as QTY, NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/')
						,p_created_by, SYSDATE, p_created_by, SYSDATE
						, NVL(B.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					-- 병합처리를 위해 키 중 병합되지 않은 키만 분리
					SELECT A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, A.PROJECT_CODE, A.INCOTERMS, A.CURRENCY, A.SCM_SITE_ID, A.ITEM_ID
						, MAX(A.FCST_TYPE) AS FCST_TYPE, MAX(A.PLANT_SITE_ID) AS PLANT_SITE_ID
						, MAX(A.DOM_EXP) AS DOM_EXP, MAX(A.COMPANY_ID) AS COMPANY_ID
					FROM GT_DMF0_REPORT A
					GROUP BY A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, A.PROJECT_CODE, A.ITEM_ID, A.SCM_SITE_ID
						, A.INCOTERMS, A.CURRENCY
					) A
				JOIN GT_DMF0_REPORT B ON A.DEPARTMENT_ID = B.DEPARTMENT_ID
						AND A.DEPARTMENT_NAME = B.DEPARTMENT_NAME
						AND A.DEPT_ID = B.DEPT_ID
						AND A.DEPT_NAME = B.DEPT_NAME
						AND A.PROJECT_CODE = B.PROJECT_CODE
						AND A.ITEM_ID = B.ITEM_ID
						AND A.SCM_SITE_ID = B.SCM_SITE_ID
						AND A.INCOTERMS = B.INCOTERMS
						AND A.CURRENCY = B.CURRENCY
				GROUP BY B.CUTOFF_TYPE, B.CUTOFF_YYYYMMDD
						, A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME
						, B.CUST_REPORT, B.END_CUST_REPORT, B.PRODUCT_GROUP, A.PROJECT_CODE, A.SCM_SITE_ID
						, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, B.MEASURE
						, A.PLANT_SITE_ID, SUBSTR(B.YYYYMMDD, 1, 6), A.CURRENCY, A.COMPANY_ID, B.CELL_PROD_SITE; --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청


--SELECT SQL%ROWCOUNT AS ROW_CNT
--SELECT * FROM GT_DMF0_VERSION_COPY
--SELECT * FROM GT_DMF0_REPORT

			END IF;

			-- --------------------------------------------------------------------------------------------------
			--		PRICE 메저 생성
			-- --------------------------------------------------------------------------------------------------
DBMS_OUTPUT.PUT_LINE('B');
				-- LOC 메저는 CP, CR 관계없이 추가한다. ( 실적구간때문에 Loc 메저를 새로 만들어야 하는데, 기존 계획구간에는 Loc 메저가 있을 수도 있어서 복사시에는 Loc 를 복사하지 않고, 여기에서 한꺼번에 새로 만들어준다.
				-- RTF 가 있는 품목들에 대해서 Unit Price ( LOC ) 를 만들어준다. SalesAmt_LOC / Unit Price ( LOCAL )
				-- DYNSAMP2 2026-08-10: LOC 메저 생성 — 방금 적재된 REPORT_C 를 2회 GROUP BY 후 10컬럼 자기조인.
				--   GT_DMF0_MEASURE(무통계 GTT) 조인 오추정 → NL 폭주(V$SQL 실측 buffer 18.3억, 회당 ~270s).
				INSERT /*+ DYNAMIC_SAMPLING(11) */ INTO DM_PLN_SALES_PLAN_REPORT_C
				(  DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
				 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
				 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
				 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
				 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
				 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, COMPANY_ID
				 -- 2021.7.23
				 , SOLDTO_CUST_REPORT, OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC
				 , NICK_NAME, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME
				 , APPLICATION, APPLICATION_GR, COUNTRY_KR_NAME, ROUTE, ATTRIBUTE3
				 , CELL_PROD_SITE) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				-- DYNSAMP3 2026-08-10: JPPD(VIEW PUSHED PREDICATE) 차단 — B(AMT)를 1회 산출 후 해시조인.
				-- TUNE-T 2026-08-10: HINT_REPORT 실측 — NO_PUSH_PRED(B) 는 적용됐으나 옵티마이저가
				--   역할을 뒤집어 B 를 구동으로, A 를 VIEW PUSHED PREDICATE 로 만들었다(STARTS=37,617).
				--   A 가 푸시 대상이 되니 LEADING(A B)/USE_HASH(B) 가 U(Unused) 처리됨.
				--   양측 푸시를 모두 막아야(NO_PUSH_PRED(A) 추가) 해시조인이 성립한다.
				SELECT /*+ LEADING(A B) USE_HASH(B) NO_MERGE(A) NO_MERGE(B) NO_PUSH_PRED(A) NO_PUSH_PRED(B) */ A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/') ,NVL(NULLIF(RTRIM(A.VERSION_NO),''), '/') ,A.CUTOFF_TYPE ,A.CUTOFF_YYYYMMDD
					 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
					 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
					 , MAX(A.DOM_EXP) AS DOM_EXP, NVL(MAX(A.FCST_TYPE), '/') AS FCST_TYPE, NVL(MAX(A.INCOTERMS), '/') AS INCOTERMS, 'LOC' AS MEASURE, NVL(MAX(A.PLANT_SITE_ID), '/') AS PLANT_SITE_ID
					 , NVL(A.YYYYMM  || '01', '/') AS YYYYMMDD, NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
					 , NVL(CASE WHEN SUM(A.Qty) <> 0 THEN ROUND(SUM(B.Qty) / SUM(A.Qty), 3)
							ELSE 0 END, 0) AS Qty
					 , p_created_by, SYSDATE, p_created_by, SYSDATE, MAX(A.ATTRIBUTE1) AS ATTRIBUTE1
					 , NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/') AS COMPANY_ID
					 -- 2021.7.23
					 , MAX(A.SOLDTO_CUST_REPORT) AS SOLDTO_CUST_REPORT, MAX(A.OWNER_NAME) AS OWNER_NAME, MAX(A.CUST_GROUP_DTL) AS CUST_GROUP_DTL, MAX(A.PRODUCT_DETAILS) AS PRODUCT_DETAILS
					 , MAX(A.FORECAST_INFO_SPEC) AS FORECAST_INFO_SPEC, MAX(A.NICK_NAME) AS NICK_NAME, MAX(A.FORECAST_INFO_CELL_MODEL) AS FORECAST_INFO_CELL_MODEL, MAX(A.FORECAST_INFO_CELL_PACK_COUNT) AS FORECAST_INFO_CELL_PACK_COUNT
					 , MAX(A.FORECAST_INFO_BIZ_TYPE) AS FORECAST_INFO_BIZ_TYPE, MAX(A.COMPANY_NAME) AS COMPANY_NAME, MAX(A.APPLICATION) AS APPLICATION, MAX(A.APPLICATION_GR) AS APPLICATION_GR, A.COUNTRY_KR_NAME
					 , MAX(A.ROUTE) AS ROUTE, MAX(A.ATTRIBUTE3) AS CELL_MODEL
					 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					SELECT DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPARTMENT_NAME
						 , DEPT_ID, DEPT_NAME, END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, SCM_SITE_ID, ITEM_ID
						 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, SUBSTR(YYYYMMDD, 1, 6) AS YYYYMM, CURRENCY, SUM(QTY) AS QTY
						 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
						 , ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID, PROJECT_CODE
						 , SOLDTO_CUST_REPORT
						 , OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
						 , FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
						 , APPLICATION_GR, COUNTRY_KR_NAME, ROUTE, CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM DM_PLN_SALES_PLAN_REPORT_C A
					JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'LOC' AND M.QTY_AMT = 'QTY'
					WHERE DIVISION_ID = P_DIVISION_ID
						--AND MEASURE IN ( 'RTF', 'Business_Plan')
						AND VERSION_NO = V_NEW_VERSION_NO
					GROUP BY  DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPARTMENT_NAME
						, DEPT_ID, DEPT_NAME, END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, SCM_SITE_ID, ITEM_ID
						, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, SUBSTR(YYYYMMDD, 1, 6), CURRENCY
						, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
						, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID, PROJECT_CODE
						, SOLDTO_CUST_REPORT
						, OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
						, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
						, APPLICATION_GR, COUNTRY_KR_NAME, ROUTE, A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						) A
				JOIN (
					SELECT DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPARTMENT_NAME
						, DEPT_ID, DEPT_NAME, END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, SCM_SITE_ID, ITEM_ID
						, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, SUBSTR(YYYYMMDD, 1, 6) AS YYYYMM, CURRENCY, SUM(QTY) AS QTY
						, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
						, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID, PROJECT_CODE
						, SOLDTO_CUST_REPORT
						, OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
						, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
						, APPLICATION_GR, COUNTRY_KR_NAME, ROUTE, CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM DM_PLN_SALES_PLAN_REPORT_C A
					JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.PLAN_RESULT = 'LOC' AND M.QTY_AMT = 'AMT'
					WHERE DIVISION_ID = P_DIVISION_ID
						--AND MEASURE = 'SalesAmt_LOC'
						AND VERSION_NO = V_NEW_VERSION_NO
					GROUP BY DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPARTMENT_NAME
						, DEPT_ID, DEPT_NAME, END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, SCM_SITE_ID, ITEM_ID
						, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, SUBSTR(YYYYMMDD, 1, 6), CURRENCY
						, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
						, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID, PROJECT_CODE
						, SOLDTO_CUST_REPORT
						, OWNER_NAME, CUST_GROUP_DTL, PRODUCT_DETAILS, FORECAST_INFO_SPEC, NICK_NAME
						, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_BIZ_TYPE, COMPANY_NAME, APPLICATION
						, APPLICATION_GR, COUNTRY_KR_NAME, ROUTE, CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
						) B ON A.PROJECT_CODE = B.PROJECT_CODE AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
										AND A.YYYYMM = B.YYYYMM AND A.COMPANY_ID = B.COMPANY_ID AND A.CURRENCY = B.CURRENCY AND A.INCOTERMS = B.INCOTERMS
										AND A.COUNTRY_KR_NAME = B.COUNTRY_KR_NAME
										AND A.CELL_PROD_SITE  = B.CELL_PROD_SITE			--[PJ2024-50611] 소형 매출 프로세스 개선
				GROUP BY   A.DATA_TYPE, A.DIVISION_ID,A.VERSION_NO,A.CUTOFF_TYPE,A.CUTOFF_YYYYMMDD,A.DEPARTMENT_ID,A.DEPARTMENT_NAME,A.DEPT_ID,A.DEPT_NAME,A.END_CUST_REPORT,A.CUST_REPORT,A.PRODUCT_GROUP
							,A.PROJECT_CODE,A.SCM_SITE_ID,A.ITEM_ID,A.MEASURE,A.YYYYMM, A.CURRENCY, NVL(A.COMPANY_ID, '/'), A.COUNTRY_KR_NAME, A.CELL_PROD_SITE; --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청

DBMS_OUTPUT.PUT_LINE('C');

			-- 자동차 : KRW, USD 메저 생성
			IF ( P_DIVISION_ID LIKE '81%' ) THEN
					-- KRW
				INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
					 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
					 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
					 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
					 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
					 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
					 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
					 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
					 , CELL_PROD_SITE )--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), NVL(NULLIF(RTRIM(A.VERSION_NO),''), '/'), A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
					 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
					 , A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), 'KRW' AS MEASURE, NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
					 , NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
					 , NVL(A.QTY * EX.EXCHANGE_PRICE, 0)
					 , p_created_by, SYSDATE, p_created_by, SYSDATE
					 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
					 , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10, NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/')
					 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					SELECT DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
						 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
						 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
						 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
						 , YYYYMMDD, CURRENCY, QTY
						 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
						 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
						 , CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM DM_PLN_SALES_PLAN_REPORT_C A
					WHERE DIVISION_ID = P_DIVISION_ID
						AND MEASURE = 'LOC'
						AND VERSION_NO = V_NEW_VERSION_NO
						) A
				JOIN DM_PLN_SALES_REPORT_EXCHANGE_C EX ON A.DIVISION_ID = EX.DIVISION_ID AND A.CUTOFF_TYPE = EX.CUTOFF_TYPE
									AND A.CUTOFF_YYYYMMDD = EX.CUTOFF_YYYYMMDD AND EX.CURRENCY = 'KRW' AND A.CURRENCY = EX.UNIT_CURRENCY
									AND A.YYYYMMDD = EX.YYYYMMDD AND EX.VERSION_NO = V_NEW_VERSION_NO;

DBMS_OUTPUT.PUT_LINE('D');
					-- USD
				INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
					 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
					 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
					 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
					 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
					 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
					 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
					 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
					 , CELL_PROD_SITE )--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), NVL(NULLIF(RTRIM(A.VERSION_NO),''), '/'), A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					, NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
					, NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
					, A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), 'USD' AS MEASURE, NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
					, NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
					, NVL(CASE WHEN NVL(EX.EXCHANGE_PRICE, 0) <> 0 THEN ROUND( A.QTY / EX.EXCHANGE_PRICE, 3)
							ELSE 0 END, 0) AS QTY
					, p_created_by, SYSDATE, p_created_by, SYSDATE
					, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
					, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10, NVL(NULLIF(RTRIM(A.COMPANY_ID),''), '/')
					, NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM (
					SELECT DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
						 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
						 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
						 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
						 , YYYYMMDD, CURRENCY, QTY
						 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
						 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
						 , CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
					FROM DM_PLN_SALES_PLAN_REPORT_C A
					WHERE DIVISION_ID = P_DIVISION_ID
						AND MEASURE = 'KRW'
						AND VERSION_NO = V_NEW_VERSION_NO
						) A
				JOIN DM_PLN_SALES_REPORT_EXCHANGE_C EX ON A.DIVISION_ID = EX.DIVISION_ID AND A.CUTOFF_TYPE = EX.CUTOFF_TYPE
									AND A.CUTOFF_YYYYMMDD = EX.CUTOFF_YYYYMMDD AND EX.CURRENCY = 'KRW' AND EX.UNIT_CURRENCY = 'USD'
									AND A.YYYYMMDD = EX.YYYYMMDD AND EX.VERSION_NO = V_NEW_VERSION_NO;


			END IF;

DBMS_OUTPUT.PUT_LINE('E');
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 사업부별 메저 생성 ( 사업부별로 특성이 있는 메저들은 수량메저들이고, 40은 없음
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			IF ( P_DIVISION_ID LIKE '81%' ) THEN
				IF ( p_action_type = 'CP' ) THEN
					DELETE FROM DM_PLN_SALES_PLAN_REPORT_C
					WHERE DIVISION_ID = P_DIVISION_ID AND VERSION_NO = V_NEW_VERSION_NO AND MEASURE IN ( 'RTF_SYS_RP_CAR', 'RTF_SYS_RP_CELL');
				END IF;

				INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
					 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
					 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
					 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
					 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
					 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
					 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
					 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
					 , CELL_PROD_SITE ) --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), NVL(NULLIF(RTRIM(A.VERSION_NO),''), '/'), A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
					 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(C.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
					 , A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(M.O_MEASURE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
					 , NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
					 , NVL(CASE WHEN M.O_MEASURE IN ('RTF_SYS_RP_CAR', 'RTF_CAR') THEN
								CASE WHEN INSTR(B.ITEM_CLASS_NAME, 'Cell') > 0 AND C.CELL_PER_CAR > 0 THEN A.QTY / C.CELL_PER_CAR
									WHEN  INSTR(B.ITEM_CLASS_NAME, 'Module') > 0  AND C.CELL_PER_CAR > 0 AND C.CELL_PER_MODULE > 0 THEN A.QTY/ ( C.CELL_PER_CAR/ C.CELL_PER_MODULE )
									WHEN  INSTR(B.ITEM_CLASS_NAME, 'Pack') > 0  THEN A.QTY
									ELSE 0
								END
							WHEN M.O_MEASURE IN ('RTF_SYS_RP_CELL','RTF_CELL') THEN
								CASE WHEN INSTR(B.ITEM_CLASS_NAME, 'Cell') > 0 AND C.CELL_PER_CAR > 0 THEN A.QTY
									WHEN ( INSTR(B.ITEM_CLASS_NAME, 'Module') > 0 OR INSTR(B.ITEM_CLASS_NAME, 'Pack') > 0 ) AND C.CELL_PER_MODULE > 0 THEN A.QTY * C.CELL_PER_MODULE
									ELSE 0
								END
						END, 0) AS QTY
					 , p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
					 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3
					 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
					 , A.ATTRIBUTE9, A.ATTRIBUTE10, NVL(A.COMPANY_ID, '-')
					 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM   DM_PLN_SALES_PLAN_REPORT_C A
				JOIN GT_DMF0044_ITEM_SINGLE_V B ON A.ITEM_ID = B.ITEM_ID
				JOIN GT_DMF0_SCM_MST_SITE_ITEM C ON A.DIVISION_ID = C.DIVISION_ID AND A.PROJECT_CODE = C.PROJECT_CODE AND A.SCM_SITE_ID = C.SCM_SITE_ID AND A.ITEM_ID = C.ITEM_ID
				JOIN SCM_MST_SITE D ON A.DIVISION_ID = D.DIVISION_ID AND A.SCM_SITE_ID = D.SCM_SITE_ID
				JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.O_MEASURE IN ( 'RTF_SYS_RP_CAR', 'RTF_SYS_RP_CELL','RTF_CAR', 'RTF_CELL' ) AND M.PLAN_RESULT = 'PLAN'
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON D.END_CUSTOMER = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'DM_CAR_QTY_FORD' AND A.ITEM_ID = LK1.SEGMENT3
				WHERE A.DIVISION_ID = P_DIVISION_ID AND A.VERSION_NO = V_NEW_VERSION_NO
					AND ( M.O_MEASURE NOT IN ( 'RTF_SYS_RP_CAR', 'RTF_CAR') OR LK1.SEGMENT1 IS NULL ) -- FORD 환산건은 별도 처리
					AND D.END_CUSTOMER = 'FORD'
				-- FORD 환산건 추가
				UNION ALL
				SELECT A.DATA_TYPE, A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME, A.END_CUST_REPORT
					 , A.CUST_REPORT, A.PRODUCT_GROUP, C.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
					 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, M.O_MEASURE, A.PLANT_SITE_ID
					 , A.YYYYMMDD, A.CURRENCY
					 , ROUND(SUM(TO_NUMBER(C.CELL_PER_MODULE) * TO_NUMBER(A.QTY))/MAX(LK1.SEGMENT4), 0) AS QTY
					 , p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
					 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3
					 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
					 , A.ATTRIBUTE9, A.ATTRIBUTE10, A.COMPANY_ID
					 , A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				FROM   DM_PLN_SALES_PLAN_REPORT_C A
				JOIN GT_DMF0044_ITEM_SINGLE_V B ON A.ITEM_ID = B.ITEM_ID
				JOIN GT_DMF0_SCM_MST_SITE_ITEM C ON A.DIVISION_ID = C.DIVISION_ID AND A.PROJECT_CODE = C.PROJECT_CODE AND A.SCM_SITE_ID = C.SCM_SITE_ID AND A.ITEM_ID = C.ITEM_ID
				JOIN SCM_MST_SITE D ON A.DIVISION_ID = D.DIVISION_ID AND A.SCM_SITE_ID = D.SCM_SITE_ID
				JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.O_MEASURE IN ( 'RTF_SYS_RP_CAR', 'RTF_CAR' ) AND M.PLAN_RESULT = 'PLAN'
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON D.END_CUSTOMER = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'DM_CAR_QTY_FORD' AND A.ITEM_ID = LK1.SEGMENT3
				WHERE A.DIVISION_ID = P_DIVISION_ID AND A.VERSION_NO = V_NEW_VERSION_NO
					AND ( M.O_MEASURE IN ( 'RTF_SYS_RP_CAR', 'RTF_CAR') AND LK1.SEGMENT1 IS NOT NULL ) -- FORD 환산건
					AND D.END_CUSTOMER = 'FORD'
				GROUP BY A.DATA_TYPE, A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , A.DEPARTMENT_ID, A.DEPARTMENT_NAME, A.DEPT_ID, A.DEPT_NAME, A.END_CUST_REPORT
					 , A.CUST_REPORT, A.PRODUCT_GROUP, C.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
					 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, M.O_MEASURE, A.PLANT_SITE_ID
					 , A.YYYYMMDD, A.CURRENCY
					 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3
					 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
					 , A.ATTRIBUTE9, A.ATTRIBUTE10, A.COMPANY_ID
					 , A.CELL_PROD_SITE; --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청

			ELSIF P_DIVISION_ID = '82' THEN
				IF ( p_action_type = 'CP' ) THEN
					DELETE FROM DM_PLN_SALES_PLAN_REPORT_C
					WHERE DIVISION_ID = P_DIVISION_ID AND VERSION_NO = V_NEW_VERSION_NO AND MEASURE IN ( 'RTF_SYS_RP_CAR', 'RTF_SYS_RP_CELL');
				END IF;

DBMS_OUTPUT.PUT_LINE('F');
				INSERT INTO DM_PLN_SALES_PLAN_REPORT_C
					 ( DATA_TYPE, DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
					 , DEPARTMENT_ID, DEPARTMENT_NAME, DEPT_ID, DEPT_NAME, END_CUST_REPORT
					 , CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
					 , DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
					 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE
					 , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
					 , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8
					 , ATTRIBUTE9, ATTRIBUTE10, COMPANY_ID
					 , CELL_PROD_SITE	)--[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
				SELECT A.DATA_TYPE, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), NVL(NULLIF(RTRIM(A.VERSION_NO),''), '/'), A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
					 , NVL(NULLIF(RTRIM(A.DEPARTMENT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_ID),''), '/'), NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/'), NVL(NULLIF(RTRIM(A.END_CUST_REPORT),''), '/')
					 , NVL(NULLIF(RTRIM(A.CUST_REPORT),''), '/'), NVL(NULLIF(RTRIM(A.PRODUCT_GROUP),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/')
					 , A.DOM_EXP, NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/'), NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/'), NVL(NULLIF(RTRIM(M.O_MEASURE),''), '/'), NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/')
					 , NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), NVL(NULLIF(RTRIM(A.CURRENCY),''), '/')
					 , NVL(CASE WHEN M.O_MEASURE IN ('RTF_CELL', 'RTF_SYS_RP_CELL') THEN A.QTY * B.CELL_QUANTITY
							WHEN M.O_MEASURE IN ('RTF_ENG', 'RTF_SYS_RP_ENG')	THEN A.QTY * B.ENERGY/1000	-- ENERGY 컬럼값이 KWh 이므로 1,000 으로 나눠준다.
							END, 0) AS QTY
					 , p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
					 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3
					 , A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8
					 , A.ATTRIBUTE9, A.ATTRIBUTE10, NVL(A.COMPANY_ID, '-')
					 , NVL(A.CELL_PROD_SITE --[E20240429-000397]_[공급 SCM PI팀] Sales Report화면 Cell Prod Site(셀 생산지) 칼럼 추가요청
 , '/')
				FROM   DM_PLN_SALES_PLAN_REPORT_C A
				JOIN GT_DMF0044_ITEM_SINGLE_V B ON A.ITEM_ID = B.ITEM_ID
				JOIN GT_DMF0_MEASURE M ON A.MEASURE = M.I_MEASURE AND M.O_MEASURE IN ( 'RTF_CELL', 'RTF_ENG','RTF_SYS_RP_CELL', 'RTF_SYS_RP_ENG' ) AND M.PLAN_RESULT = 'PLAN' --[C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용
				WHERE A.DIVISION_ID = P_DIVISION_ID AND A.VERSION_NO = V_NEW_VERSION_NO
					--and a.item_id = 'EABB00252AA'
					--and a.yyyymmdd = '20191101'
					--and a.scm_site_id = 'Fluence_US_SAN'

				order by measure;
DBMS_OUTPUT.PUT_LINE('G');


			END IF;
			--RAISE_APPLICATION_ERROR(-20001, 'TEST')

			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 사업부별 메저 끝
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- 기타매출 복사 ---------------------------------------------------------------------------------------------------------------------------------------------------------------------
			-- ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
			/*
				기타매출 테이블에서 기타매출 테이블로 복사한다.
				COPY 시에는 실적 기준일이 있을 경우에는 해당 기준일을 기준으로 이전월은 실적으로 보고 해당 기간까지는 실적버전을 복사하고, 이 후 기간은 원본버전을 그대로 복사한다.
			              실적 기준일이 없을 경우에는 그냥 복사한다.
				CREATE 시에는 최신 버전을 그대로 복사한다.
			*/
			-- (인라인 DECLARE 제거: V_ETC_CUTOFF_TYPE/YYYYMMDD는 선언부에 이미 선언됨)
			SELECT MAX(CUTOFF_TYPE), MAX(CUTOFF_YYYYMMDD)
			  INTO V_ETC_CUTOFF_TYPE, V_ETC_CUTOFF_YYYYMMDD
			FROM DM_PLN_SALES_PLAN_REPORT_C
			WHERE DIVISION_ID = P_DIVISION_ID
				AND VERSION_NO = V_NEW_VERSION_NO;

--select V_ETC_CUTOFF_TYPE, V_ETC_CUTOFF_YYYYMMDD, V_NEW_VERSION_NO
			IF p_action_type = 'CR' THEN

				INSERT INTO DM_PLN_SALES_ETC_REPORT_C (
					VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
					, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
					, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
					, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
					-- 2021.07.23
					, OWNER_NAME, CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME
					, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE
					, DEPARTMENT_NAME, DEPT_NAME
					 )
				SELECT V_NEW_VERSION_NO, A.DIVISION_ID, A.DATA_SEQ, V_ETC_CUTOFF_TYPE, V_ETC_CUTOFF_YYYYMMDD
					, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_ID ELSE A.DEPARTMENT_ID END AS DEPARTMENT_ID
					, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_ID ELSE A.DEPT_ID END AS DEPT_ID
					, A.END_CUST_REPORT, A.CUST_REPORT, A.SOLDTO_CODE, A.SOLDTO_CUST_REPORT
					, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE, A.PROJECT_NAME, A.SCM_SITE_ID, A.ITEM_ID
					, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, A.QTY
					, p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
					, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
					-- 2021.07.23
					, FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' )		AS OWNER_NAME
					, B.CUST_GROUP_DTL, C.FORECAST_INFO_SPEC
					, NVL(LK3.ATTRIBUTE1, C.NICK_NAME ) AS NICK_NAME
					, NVL(CASE WHEN REGEXP_LIKE(LK3.ATTRIBUTE2, '^[+-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(LK3.ATTRIBUTE2) ELSE 0 END, C.FORECAST_INFO_CELL_PACK_COUNT ) AS FORECAST_INFO_CELL_PACK_COUNT
					, D.SEGMENT2, F.COUNTRY_KR_NAME, B.ROUTE
					, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME ELSE LK1.SEGMENT2 END AS DEPARTMENT_NAME
					, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME ELSE LK2.SEGMENT2 END AS DEPT_NAME
				FROM DM_PLN_SALES_ETC_REPORT_C A
				LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
				LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V C ON A.ITEM_ID = C.ITEM_ID
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY'
				--LEFT OUTER JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
				LEFT OUTER JOIN SCM_MST_COUNTRY F ON A.COUNTRY_CODE = F.COUNTRY
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END AND LK1.SEGMENT3 = 'Y'
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK2 ON A.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END
				LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK3 ON A.DIVISION_ID = LK3.SEGMENT1 AND A.ITEM_ID = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_SR_ETC_MODEL'
				WHERE A.DIVISION_ID = P_DIVISION_ID
					AND A.VERSION_NO = ( SELECT A.VERSION_NO
										FROM DM_MDF_VERSION A
										JOIN (
											SELECT MAX(A.CREATION_DATE) AS CREATION_DATE
											FROM DM_MDF_VERSION A
											JOIN DM_PLN_SALES_ETC_REPORT_C B ON A.DIVISION_ID = B.DIVISION_ID AND A.VERSION_NO = B.VERSION_NO
											WHERE A.DIVISION_ID = P_DIVISION_ID
											) B ON A.CREATION_DATE = B.CREATION_DATE
										WHERE A.DIVISION_ID = P_DIVISION_ID
										ORDER BY A.VERSION_NO DESC
										FETCH FIRST 1 ROWS ONLY
										);
--RAISE_APPLICATION_ERROR(-20001, 'SS')
DBMS_OUTPUT.PUT_LINE('H');

			ELSIF p_action_type = 'CP' THEN
				IF D_RESULT_DATE IS NULL THEN
					INSERT INTO DM_PLN_SALES_ETC_REPORT_C (
						VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
						, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
						, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
						, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
						, COMPANY_NAME, COUNTRY_KR_NAME, CUST_GROUP_DTL, DEPARTMENT_NAME, DEPT_NAME
						, FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_SPEC, NICK_NAME, OWNER_NAME, ROUTE
						  )
					SELECT V_NEW_VERSION_NO, A.DIVISION_ID, A.DATA_SEQ, V_ETC_CUTOFF_TYPE, V_ETC_CUTOFF_YYYYMMDD, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT, A.SOLDTO_CODE, A.SOLDTO_CUST_REPORT
						, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE, A.PROJECT_NAME, A.SCM_SITE_ID, A.ITEM_ID
						, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, A.QTY
						, p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
						, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
						, CASE WHEN p_update_yn = 'Y' AND D.SEGMENT2 IS NOT NULL THEN D.SEGMENT2 ELSE A.COMPANY_NAME END AS COMPANY_NAME
						, CASE WHEN p_update_yn = 'Y' AND F.COUNTRY_KR_NAME IS NOT NULL THEN F.COUNTRY_KR_NAME ELSE A.COUNTRY_KR_NAME END AS COUNTRY_KR_NAME
						, CASE WHEN p_update_yn = 'Y' AND B.CUST_GROUP_DTL IS NOT NULL THEN B.CUST_GROUP_DTL ELSE A.CUST_GROUP_DTL END AS CUST_GROUP_DTL
						, CASE WHEN p_update_yn = 'Y' AND P_DIVISION_ID = '40' AND LK1.SEGMENT2 IS NOT NULL THEN LK1.SEGMENT2
								WHEN p_update_yn = 'Y' AND P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME
								ELSE A.DEPARTMENT_NAME
								END AS DEPARTMENT_NAME
						, CASE WHEN p_update_yn = 'Y' AND P_DIVISION_ID = '40' AND LK2.SEGMENT2 IS NOT NULL THEN LK2.SEGMENT2
								WHEN p_update_yn = 'Y' AND P_DIVISION_ID = '40' AND LK2.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME
								ELSE A.DEPT_NAME
								END AS DEPT_NAME
						, CASE WHEN p_update_yn = 'Y' AND CASE WHEN REGEXP_LIKE(LK3.ATTRIBUTE2, '^[+-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(LK3.ATTRIBUTE2)
																ELSE NVL(C.FORECAST_INFO_CELL_PACK_COUNT,0)
																END <> 0
											THEN CASE WHEN REGEXP_LIKE(LK3.ATTRIBUTE2, '^[+-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(LK3.ATTRIBUTE2)
																ELSE NVL(C.FORECAST_INFO_CELL_PACK_COUNT,0) END
								ELSE A.FORECAST_INFO_CELL_PACK_COUNT END AS FORECAST_INFO_CELL_PACK_COUNT
						, CASE WHEN p_update_yn = 'Y' AND C.FORECAST_INFO_SPEC IS NOT NULL THEN C.FORECAST_INFO_SPEC ELSE A.FORECAST_INFO_SPEC END AS FORECAST_INFO_SPEC
						, CASE WHEN p_update_yn = 'Y' AND NVL(LK3.ATTRIBUTE1, C.NICK_NAME ) IS NOT NULL THEN NVL(LK3.ATTRIBUTE1, C.NICK_NAME ) ELSE A.NICK_NAME END AS NICK_NAME
						, CASE WHEN p_update_yn = 'Y' AND NVL(FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' ),'') IS NOT NULL THEN FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' ) ELSE A.OWNER_NAME END AS OWNER_NAME
						, CASE WHEN p_update_yn = 'Y' AND B.ROUTE IS NOT NULL THEN B.ROUTE ELSE A.ROUTE END AS ROUTE
					FROM DM_PLN_SALES_ETC_REPORT_C A
					LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
					LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V C ON A.ITEM_ID = C.ITEM_ID
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY'
					--LEFT OUTER JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
					LEFT OUTER JOIN SCM_MST_COUNTRY F ON A.COUNTRY_CODE = F.COUNTRY
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END AND LK1.SEGMENT3 = 'Y'
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK2 ON A.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK3 ON A.DIVISION_ID = LK3.SEGMENT1 AND A.ITEM_ID = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_SR_ETC_MODEL'
					WHERE A.DIVISION_ID = P_DIVISION_ID
						AND A.VERSION_NO = P_VERSION_NO;
DBMS_OUTPUT.PUT_LINE('I');
				ELSE  -- 실적기준일이 있는 복사일 경우 ( 최신화는 UI 에서 강제체크됨 )

					-- 실적을 복사할 버전을 찾는다.
					SELECT MIN(A.VERSION_NO)
  INTO V_MAX_ETC_RESULT_VERSION_NO
					FROM DM_MDF_VERSION A
					JOIN ( SELECT DIVISION_ID, MIN(ETC_RESULT_MONTH) AS ETC_RESULT_MONTH
							FROM DM_MDF_VERSION
							WHERE DIVISION_ID = P_DIVISION_ID
								AND ETC_RESULT_MONTH >= V_ETC_RESULT_MONTH
								AND VERSION_NO <> V_NEW_VERSION_NO
								AND VERSION_TYPE LIKE 'REPORT_SP%'
								AND SEND_YN <> 'D'
							GROUP BY DIVISION_ID
						) B ON A.DIVISION_ID = B.DIVISION_ID
							AND A.ETC_RESULT_MONTH = B.ETC_RESULT_MONTH
							AND A.VERSION_NO <> V_NEW_VERSION_NO
					WHERE A.VERSION_TYPE LIKE 'REPORT_SP%'
						AND A.SEND_YN <> 'D';

					-- LOOKUP 에 복사할 버전이 지정되어있으면 해당 버전을 사용한다.
					SELECT COUNT(1) SEGMENT2
					INTO v_cnt_1
					FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
					WHERE LOOKUP_TYPE = 'DM_SR_ETC_VERSION'
					AND SEGMENT1 = P_DIVISION_ID
					AND SEGMENT2 IS NOT NULL;
					IF v_cnt_1 > 0 THEN

						SELECT SEGMENT2
						  INTO V_MAX_ETC_RESULT_VERSION_NO
						FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
						WHERE LOOKUP_TYPE = 'DM_SR_ETC_VERSION'
							AND SEGMENT1 = P_DIVISION_ID
							AND SEGMENT2 IS NOT NULL;

						SELECT COUNT(*) INTO v_cnt_1
						FROM DM_MDF_VERSION
						WHERE DIVISION_ID = P_DIVISION_ID
						AND VERSION_NO = V_MAX_ETC_RESULT_VERSION_NO;
						IF v_cnt_1 = 0 THEN
							v_log_type := 'INVALID_ETC_VERSION';
							RAISE e_validation;
						END IF;
					END IF;  -- v_cnt_1>0 (룩업 ETC 버전 지정) 블록 종료 [MSSQL 2448]


					SELECT MAX(DATA_SEQ)
  INTO V_MAX_DATA_SEQ
					FROM DM_PLN_SALES_ETC_REPORT_C A
					WHERE A.DIVISION_ID = P_DIVISION_ID
						AND A.VERSION_NO = V_NEW_VERSION_NO;
DBMS_OUTPUT.PUT_LINE('J');
--SELECT V_MAX_ETC_RESULT_VERSION_NO, V_NEW_VERSION_NO, V_ETC_RESULT_MONTH, V_MAX_DATA_SEQ

					INSERT INTO DM_PLN_SALES_ETC_REPORT_C (
						VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
						, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
						, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
						, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
						-- 2021.07.23
						, OWNER_NAME, CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME
						, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE
						, DEPARTMENT_NAME, DEPT_NAME
						 )
					SELECT A.VERSION_NO, A.DIVISION_ID, A.DATA_SEQ, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD

						-- 최신화가 아닐 경우 기존 값 복사, 일치하는 부서가 없으면 DEAFULT 기타 부서로 세팅
						, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_ID ELSE A.DEPARTMENT_ID END AS DEPARTMENT_ID
						, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_ID ELSE A.DEPT_ID END AS DEPT_ID
						, A.END_CUST_REPORT, A.CUST_REPORT, A.SOLDTO_CODE, A.SOLDTO_CUST_REPORT
						, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE, A.PROJECT_NAME, A.SCM_SITE_ID, A.ITEM_ID
						, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
						, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
						-- 2021.07.23
						, FN_GET_DM_MKT_OWNER_NAME (B.OWNER, ',', 'KO' )       AS OWNER_NAME
						, B.CUST_GROUP_DTL, C.FORECAST_INFO_SPEC
						, NVL(LK3.ATTRIBUTE1, C.NICK_NAME ) AS NICK_NAME
						, NVL(CASE WHEN REGEXP_LIKE(LK3.ATTRIBUTE2, '^[+-]?[0-9]+(\.[0-9]+)?$') THEN TO_NUMBER(LK3.ATTRIBUTE2) ELSE 0 END, C.FORECAST_INFO_CELL_PACK_COUNT) AS FORECAST_INFO_CELL_PACK_COUNT
						, D.SEGMENT2, F.COUNTRY_KR_NAME, B.ROUTE

						, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME ELSE LK1.SEGMENT2 END AS DEPARTMENT_NAME
						, CASE WHEN P_DIVISION_ID = '40' AND LK1.SEGMENT1 IS NULL THEN v_ETC_DEPARTMENT_NAME ELSE LK2.SEGMENT2 END AS DEPT_NAME
					FROM (
						SELECT
							  V_NEW_VERSION_NO AS VERSION_NO, DIVISION_ID
							, DENSE_RANK() OVER (
									ORDER BY DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
									, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME
									, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CURRENCY, COMPANY_ID
									, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
									, SEQ_GRP  -- SEQGRP 2026-08-10
										 ) AS DATA_SEQ
							, V_ETC_CUTOFF_TYPE AS CUTOFF_TYPE, V_ETC_CUTOFF_YYYYMMDD AS CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
							, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
							, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY
							, p_created_by AS CREATED_BY, SYSDATE AS CREATION_DATE, p_created_by AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
							, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
							, OWNER_NAME, CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME
							, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE
							, DEPARTMENT_NAME, DEPT_NAME
						FROM (
							-- 계획구간
							SELECT DIVISION_ID
								, CUTOFF_TYPE, /* CUTOFF_YYYYMMDD ,*/ DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
								, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
								, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
								, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
								, OWNER_NAME, CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME
								, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE
								, DEPARTMENT_NAME, DEPT_NAME
								-- SEQGRP 2026-08-10: 같은 버전 안에서 속성이 동일하고 원본 DATA_SEQ 만 다른 행을 구분한다.
								--   (유일 행은 전부 1 이므로 교차버전 병합 동작은 그대로 유지된다)
								, DENSE_RANK() OVER (PARTITION BY DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CURRENCY, COMPANY_ID, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 ORDER BY DATA_SEQ) AS SEQ_GRP
							FROM DM_PLN_SALES_ETC_REPORT_C A
							WHERE A.DIVISION_ID = P_DIVISION_ID
								AND A.VERSION_NO = P_VERSION_NO
								AND A.YYYYMMDD > NVL(d_Result_Date, '/')
							-- 실적구간
							UNION ALL
							SELECT A.DIVISION_ID, CUTOFF_TYPE, /* CUTOFF_YYYYMMDD ,*/ DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
								, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
								, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
								, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
								, OWNER_NAME, CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME
								, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE
								, DEPARTMENT_NAME, DEPT_NAME
								-- SEQGRP 2026-08-10: 같은 버전 안에서 속성이 동일하고 원본 DATA_SEQ 만 다른 행을 구분한다.
								--   (유일 행은 전부 1 이므로 교차버전 병합 동작은 그대로 유지된다)
								, DENSE_RANK() OVER (PARTITION BY DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CURRENCY, COMPANY_ID, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 ORDER BY DATA_SEQ) AS SEQ_GRP
							FROM DM_PLN_SALES_ETC_REPORT_C A
							WHERE A.DIVISION_ID = P_DIVISION_ID
								AND A.VERSION_NO = V_MAX_ETC_RESULT_VERSION_NO
								AND A.YYYYMMDD <= d_Result_Date
							) A
						) A
					LEFT OUTER JOIN SCM_MST_SITE_ITEM B ON A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
					LEFT OUTER JOIN GT_DMF0044_ITEM_SINGLE_V C ON A.ITEM_ID = C.ITEM_ID
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D ON A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY'
					--LEFT OUTER JOIN SCM_MST_SITE E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID
					LEFT OUTER JOIN SCM_MST_COUNTRY F ON A.COUNTRY_CODE = F.COUNTRY
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END AND LK1.SEGMENT3 = 'Y'
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK2 ON A.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2' ||  CASE WHEN A.DIVISION_ID= '40' THEN '' ELSE '_'  ||  A.DIVISION_ID END
					LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK3 ON A.DIVISION_ID = LK3.SEGMENT1 AND A.ITEM_ID = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_SR_ETC_MODEL';

				END IF;
			END IF;  -- p_action_type CR/CP (ETC 매출 복사) 종료 [MSSQL 2542]


			-- 1~3 담당이 아니면 기타로 처리
			IF P_DIVISION_ID = '40' THEN
				UPDATE DM_PLN_SALES_ETC_REPORT_C A
				SET A.DEPARTMENT_ID = v_ETC_DEPARTMENT_ID
				  , A.DEPT_ID       = v_ETC_DEPARTMENT_ID
				WHERE A.DIVISION_ID = P_DIVISION_ID
				  AND A.VERSION_NO = V_NEW_VERSION_NO
				  AND NOT EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
					WHERE A.DEPARTMENT_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND B.SEGMENT3 = 'Y' );
			END IF;

--VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT
--, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME, SCM_SITE_ID, ITEM_ID
--, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
--, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10


			-- 기타매출 복사 끝 ------------------------------------------------------------------------------------------------------------------------------------------------------------------

--[E20230906-001160] GDW 송신용 데이터 Lookup 수정 특정 상품에 대한 BIZ_TYPE과 COUNT 정보를 변환하여 저장되도록 요청 20230907
DBMS_OUTPUT.PUT_LINE('K');
			BEGIN
			MERGE INTO DM_PLN_SALES_PLAN_REPORT_C A
			USING ( SELECT A.MODEL, A.BIZ_TYPE, A.CELL_PACK_COUNT, A.MODEL_RANK, A.DIVISION_ID
					FROM (
						SELECT SEGMENT2 AS MODEL, SEGMENT3 AS BIZ_TYPE, SEGMENT4 AS CELL_PACK_COUNT, SEGMENT1 AS DIVISION_ID
						     , RANK() OVER (PARTITION BY SEGMENT2 ORDER BY DISPLAY_SEQ DESC) MODEL_RANK
						FROM SCM_ADM_LOOKUP_MASTER_DETAIL
						WHERE LOOKUP_TYPE = 'DM_BIZ_TYPE_40'
					) A
					WHERE MODEL_RANK = '1'
				) LOOKA
			--[E20260828-SARGSWEEP] 버전 필터를 ON 절로 — 종전엔 WHEN MATCHED WHERE 에만 있어 전 버전 3.9M 원장을
			--  조인 스캔(CFMERGE 동계열). WHEN NOT MATCHED 부재 = ON 이동 등가. UPDATE WHERE 는 안전망으로 보존.
			ON ( LOOKA.MODEL = A.ITEM_ID AND LOOKA.DIVISION_ID = A.DIVISION_ID
			     AND A.DIVISION_ID = '40' AND A.VERSION_NO = V_NEW_VERSION_NO ) --[E20260828-SARGSWEEP]
			WHEN MATCHED THEN UPDATE SET A.FORECAST_INFO_CELL_PACK_COUNT = LOOKA.CELL_PACK_COUNT
				, A.FORECAST_INFO_BIZ_TYPE = LOOKA.BIZ_TYPE
				WHERE A.DIVISION_ID = '40' AND A.VERSION_NO = V_NEW_VERSION_NO;

			END;


		END IF;  -- 요청VERSION COPY (CR,CP) 래퍼 종료


    -- IF @V_TRANCOUNT > 0

-- 트랜잭션 (COMMIT)
    -- 트랜잭션 종료 (COMMIT) - 프로시저 종료 직전 1회
    COMMIT;

    -- 수행결과 성공 DISPLAY
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(n_merge_count) AS EVENT FROM DUAL;

    -- 종료 LOG
    v_log_type := 'END';
    v_log_message := '########## END of procedure ##########';
    v_description := 'delete_count: ' || TO_CHAR(n_delete_count) || ' / merge_count: ' || TO_CHAR(n_merge_count);
    d_event_date := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_description, d_event_date); END;

EXCEPTION
    -- 검증 실패 (구 GOTO ERR_RTN): 롤백 + 메시지 결과셋 반환 후 정상 종료 (원본 동등, 에러 raise 안함)
    WHEN e_validation THEN
        ROLLBACK;
        v_result_msg := CASE v_log_type
            WHEN 'DIVISION_INVALID'    THEN 'Division 값이 존재하지 않습니다.'
            WHEN 'VERSION_NO_INVALID'  THEN 'VERSION 값이 존재하지 않습니다.'
            WHEN 'INVALID_ETC_VERSION' THEN '룩업에 설정된 ETC 버전이 잘못되었습니다.'
            -- NODATAGUARD 2026-08-10
            WHEN 'SOURCE_VERSION_EMPTY' THEN '원본 버전에 복사할 데이터가 없습니다. 데이터가 있는 버전을 선택하세요.'
            WHEN 'VERSION_NO_AMBIGUOUS' THEN 'VERSION 값이 여러 Division 에 중복 존재합니다.'
            WHEN '이동계획 중복'        THEN v_description
            ELSE NVL(v_log_message, '저장할 수 없습니다.') END;
        v_log_message := '########## END of procedure ##########';
        d_event_date := SYSDATE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message, v_result_msg, d_event_date); END;
        OPEN O_RESULT_CURSOR FOR
        SELECT '1' AS CODE, v_result_msg AS MSG, NULL AS EVENT FROM DUAL;
    -- 실제 런타임 오류: 롤백 + 표준 에러로그 + 전파
    WHEN OTHERS THEN
        ROLLBACK;
        v_log_type := 'ERROR';
        v_log_message := 'EXCEPTION';
        v_description := '';
        d_event_date := SYSDATE;
        DECLARE
            V_SQL_CODE   VARCHAR2(100 CHAR)  := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG VARCHAR2(1000 CHAR) := SQLERRM;
            V_BACKTRACE  VARCHAR2(4000 CHAR) := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            V_PROC_INPUT VARCHAR2(4000 CHAR);
        BEGIN
            V_PROC_INPUT := JSON_OBJECT(
                'p_division_id' VALUE p_division_id, 'p_version_no' VALUE p_version_no,
                'p_version_description' VALUE p_version_description, 'p_created_by' VALUE p_created_by,
                'p_result_date' VALUE p_result_date, 'p_action_type' VALUE p_action_type,
                'p_mv_plan_yyyymm' VALUE p_mv_plan_yyyymm, 'p_update_yn' VALUE p_update_yn);
            BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(v_program_name, v_log_type, n_log_count, v_log_message,
                v_description, d_event_date, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
            RAISE_APPLICATION_ERROR(-20001,
                '[' || v_program_name || '] SQLCODE=' || V_SQL_CODE || ' / SQLERRM=' || V_SQL_ERRMSG ||
                ' / BACKTRACE=' || V_BACKTRACE || ' / PARAMS=' || V_PROC_INPUT);
        END;
END P_DMF0044_SAVE_SALES_PLAN_VERSION_COPY;


PROCEDURE P_DMF0044_SALES_REPORT_DEPT_CREATE 
(
    P_DIVISION_ID       IN  VARCHAR2,
    P_VERSION_NO        IN  VARCHAR2,
    P_ACTION_TYPE       IN  VARCHAR2,   -- T:Transfer, C:Cancel
    P_YYYY              IN  VARCHAR2,
    O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
/*
 * Program ID   : DMF0044_SALES_REPORT_DEPT_CREATE
 * Description  : 매출리포트용 데이터 생성 PROCEDURE
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 20190522 JSYOUN Initial Release [PJ20189106] 전지본부 GSCM(DM) 고도화 프로젝트
 * 20191021 kyh    rownumber 가 group by 랑 같이있어서 중복오류, Group By 에 Data_Type 제거 - 수정함
 * 20191023 kyh    Department_Name 가져오는 로직을 Sales Report 와 동일하게 Lookup 을 보도록 수정
 * 20191113 KYH		PACK 일 경우 수량환산
 * 20191118 hwi1993 파라미터 추가 및 데이터타입 변경 및 Cancel 기능 추가
 * 20200512 hwi1993 ETC 매출 테이블 추가
 * 20200525 hwi1993 소형 1~3 담당 외에는 기타로 묶음.
 * 20200610 hwi1993	ETC Data 중 Product Detail 이 빠지는 문제 수정
 * 20210716	HWI1993	상반기과제 ( GDW 마스터정비 ) bp 메저관련 및 기간조정
 * 20220616 hwi1993 [C20220608-000333] GDW 전송시 버전 종류에 따른 데이터 오류 수정 요청의 건
 * 2026/06/05	NextSCM Migration	[PJ202650304] 기존 배포본(미완성 자동변환, INVALID) 재변환. #TEMP_REPORT_C→GTT(GT_DMF0044_DEPT_RPT_C), CURSOR 루프→연도 CROSS JOIN(+ROW_NUMBER PARTITION BY YYYY), UPDATE..FROM→상관 UPDATE/NOT EXISTS, GETDATE→SYSDATE, 로깅/EXCEPTION/O_RESULT_CURSOR 표준. 템플릿=DMF0044_SALES_REPORT_EXCHANGE_RATE_CREATE(VALID)
 */
IS
    V_PROGRAM_NAME      VARCHAR2(200 CHAR);

    V_LOG_TYPE          VARCHAR2(100 CHAR);
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(4000 CHAR);
    V_DESCRIPTION       VARCHAR2(4000 CHAR);
    D_EVENT_DATE        DATE := SYSDATE;
    n_delete_count      PLS_INTEGER := 0;
    n_merge_count       PLS_INTEGER := 0;

    v_user_id           VARCHAR2(10 CHAR) := 'mdf_batch';
    v_ori_version_no    VARCHAR2(50 CHAR);
    V_SP_BP             VARCHAR2(2 CHAR);
    v_etc_department_id VARCHAR2(30 CHAR);
    v_bp_cnt            PLS_INTEGER := 0;

    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);

BEGIN
    --[E20260812-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어 (2026-08-06 표준, 2026-08-12 DMF0044/0049 일괄 적용)
    EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    -- 시작 LOG  (START)
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;
    V_LOG_MESSAGE := NULL;
    -- 시작 LOG  (END)

    -- 중복 VERSION이 있는경우 삭제후 COPY
    DELETE FROM SCM_MGR.DM_MOBILE_REPORT_DEPT
    WHERE  DIVISION_ID = P_DIVISION_ID
    AND    VERSION_NO  = P_VERSION_NO;

    n_delete_count := SQL%ROWCOUNT;

    IF P_ACTION_TYPE = 'T' THEN -- 전송일 경우만 인서트하고, C 일 경우는 자동삭제처리

        -- TUNE-J 2026-08-10: SELECT 컬럼절 서브쿼리(FROM DUAL 감싸기) 제거 → 직접 집계 조회.
        --   NVL(x, NULL) ≡ x (항등). PK_DM_MDF_VERSION=(DIVISION_ID,VERSION_NO) UNIQUE 이므로
        --   대상은 0 또는 1행 ⇒ MAX() 는 원본 ROWNUM=1 과 같은 값이며,
        --   집계라 행이 없어도 NO_DATA_FOUND 없이 NULL 을 돌려준다(원본과 동일 거동).
        SELECT MAX(ORI_VERSION_NO)
          INTO v_ori_version_no
          FROM SCM_MGR.DM_MDF_VERSION
         WHERE DIVISION_ID = P_DIVISION_ID AND VERSION_NO = P_VERSION_NO;

        -- GTT 초기화
        DELETE FROM SCM_MGR.GT_DMF0044_DEPT_RPT_C;

        -- 20210716 : Business_Plan 존재 여부로 SP/BP 결정
        SELECT COUNT(*) INTO v_bp_cnt
        FROM DM_PLN_SALES_PLAN_REPORT_C A
        WHERE A.DIVISION_ID = P_DIVISION_ID
          AND A.VERSION_NO  = P_VERSION_NO
          AND A.MEASURE = 'Business_Plan'
          AND ROWNUM = 1;

        IF v_bp_cnt > 0 THEN
            V_SP_BP := 'BP';
        ELSE
            V_SP_BP := 'SP';
        END IF;

        -- #TEMP_REPORT_C 적재 (SALES_PLAN + ETC UNION ALL)
        INSERT INTO SCM_MGR.GT_DMF0044_DEPT_RPT_C
            ( DIVISION_ID, PRODUCT_GROUP, MEASURE, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, QTY )
        -- TUNE-V 2026-08-10: hook #129 1순위(구조) — DM_MST_ITEM_SINGLE_V 사용 중단.
        --   ⚠ 앞선 TUNE-M(/*+ MATERIALIZE */ 로 1회 산출) 은 **실패한 조치**였다.
        --     리터럴 재현에서는 0.7초였으나, 바인드 실사용에서는 붕괴가 사라진 게 아니라
        --     "실체화하는 그 문장" 안으로 옮겨갔을 뿐이다. 그 근거를 남긴다:
        --     SID 512 / SQL_ID 5dchxk6z8k7hg — CPU 4,900초, buffer_gets 2.63억, 처리행 0,
        --     ASH 3,183 샘플 전량(100%)이 플랜 L11 INDEX SKIP SCAN PK_SCM_ITEM_M 한 곳.
        --     (L4 NESTED LOOPS EST 13억 / L6 VIEW PUSHED PREDICATE starts 35,238)
        --   원인: 뷰가 SCM_MST_ITEM_SN 을 SUBSTR(ITEM_ID,1,12) 로 집계한 인라인뷰와
        --     셀프조인하는 구조라, 옵티마이저가 PUSHED PREDICATE 를 걸면 GROUP BY 뷰가
        --     행별 상관 집계로 전개되고 비-SARGable SUBSTR 필터가 구동행 수만큼 반복된다.
        --   조치: 힌트로 판단을 바꾸는 대신 **셀프조인 자체를 제거** — PUSHED PREDICATE 가
        --     성립 불가능한 단일 패스 + 분석함수 형태로 바꾼다(2순위 SARGable 문제도 동시 소멸).
        --   등가: T2 는 같은 테이블을 같은 키로 집계한 것이라 T1 의 모든 행이 반드시 자기 그룹과
        --     매칭된다(inner join 이 행을 떨구지 않음) ⇒ "T1 그룹별 MAX(T2.col)"
        --     = "SUBSTR12 파티션 전체의 MAX(col)". 실측 DIVISION_ID='40':
        --     168,619행 / BIZ NOT NULL 9,895 / PACK 합 34,086 — OLD·NEW 완전일치,
        --     MINUS 양방향 0행 PASS, COST 1,618,474 → 8,499, 서버측 0.41초 → 0.21초.
        WITH ISV AS (
            -- /*+ MATERIALIZE */ 유지 사유: ISV 는 아래 UNION ALL 두 갈래에서 각각 참조된다.
            --   붕괴 방지용이 아니라 **중복 산출 방지용**이다(3순위 힌트는 불필요해짐).
            SELECT /*+ MATERIALIZE */ DIVISION_ID, ITEM_ID
                 , MAX(MAX(FORECAST_INFO_BIZ_TYPE))
                       OVER (PARTITION BY DIVISION_ID, SUBSTR(ITEM_ID,1,12)) AS FORECAST_INFO_BIZ_TYPE
                 , MAX(MAX(FORECAST_INFO_CELL_PACK_COUNT))
                       OVER (PARTITION BY DIVISION_ID, SUBSTR(ITEM_ID,1,12)) AS FORECAST_INFO_CELL_PACK_COUNT
              FROM SCM_MST_ITEM_SN
             -- TUNE-M2 2026-08-10: 사전필터(유지). 조인이 A.DIVISION_ID = B.DIVISION_ID 이고
             --   A 는 항상 DIVISION_ID = P_DIVISION_ID 로 걸리므로 타 division 행은
             --   조인될 수 없다 ⇒ 결과 불변.
             WHERE DIVISION_ID = P_DIVISION_ID
             GROUP BY DIVISION_ID, ITEM_ID )
        SELECT A.DIVISION_ID, A.PRODUCT_GROUP
             , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF' ELSE A.MEASURE END AS MEASURE
             , A.YYYYMMDD, A.ATTRIBUTE1, A.ATTRIBUTE2, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT
             , CASE WHEN A.MEASURE IN ('RTF','Business_Plan','RTF_SYS_RP') AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1)
                    ELSE A.QTY
               END AS QTY
          FROM DM_PLN_SALES_PLAN_REPORT_C A
          LEFT OUTER JOIN ISV B
            ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('Business_Plan', 'RTF','RTF_SYS_RP','SalesAmt_KRW')
           AND A.DATA_TYPE = '1'
        UNION ALL
        SELECT A.DIVISION_ID, A.PRODUCT_GROUP
             , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF'
                    WHEN A.MEASURE = 'RTF_SYS_RP' THEN CASE WHEN V_SP_BP = 'BP' THEN 'RTF' ELSE A.MEASURE END
                    ELSE A.MEASURE
               END AS MEASURE
             , A.YYYYMMDD, A.PRODUCT_DETAILS, A.ATTRIBUTE2, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT
             , CASE WHEN A.MEASURE IN ('RTF','Business_Plan') AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1)
                    ELSE A.QTY
               END AS QTY
          FROM DM_PLN_SALES_ETC_REPORT_C A
          LEFT OUTER JOIN ISV B
            ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('Business_Plan', 'RTF','RTF_SYS_RP','SalesAmt_KRW');

        -- 2020.05.25 1~3 담당 외에는 기타로 묶는다. (기타 부서코드 조회)
        BEGIN
            SELECT SEGMENT1 INTO v_etc_department_id
            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
            WHERE LOOKUP_TYPE = 'MDF_DEPARTMENT' AND ATTRIBUTE1 = 'Y' AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN v_etc_department_id := NULL;
        END;

        -- GTT 의 미등록 부서 → 기타
        UPDATE SCM_MGR.GT_DMF0044_DEPT_RPT_C A
        SET A.DEPARTMENT_ID = v_etc_department_id
        WHERE NOT EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                           WHERE A.DEPARTMENT_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND B.SEGMENT3 = 'Y' );

        -- 원본 테이블의 미등록 부서 → 기타 (원본 MSSQL 동작 보존)
        UPDATE DM_PLN_SALES_PLAN_REPORT_C A
        SET A.DEPARTMENT_ID = v_etc_department_id
          , A.DEPT_ID = v_etc_department_id
        WHERE A.DIVISION_ID = P_DIVISION_ID
          AND A.VERSION_NO = P_VERSION_NO
          AND NOT EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                           WHERE A.DEPARTMENT_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND B.SEGMENT3 = 'Y' );

        UPDATE DM_PLN_SALES_ETC_REPORT_C A
        SET A.DEPARTMENT_ID = v_etc_department_id
          , A.DEPT_ID = v_etc_department_id
        WHERE A.DIVISION_ID = P_DIVISION_ID
          AND A.VERSION_NO = P_VERSION_NO
          AND NOT EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                           WHERE A.DEPARTMENT_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'MDF_DEPARTMENT' AND B.SEGMENT3 = 'Y' );

        -- CURSOR 루프(연도) 대신 SALES_PLAN 연도 CROSS JOIN + ROW_NUMBER PARTITION BY YYYY
        INSERT INTO SCM_MGR.DM_MOBILE_REPORT_DEPT
             ( DIVISION_ID, VERSION_NO, YYYY, SP_BP_TYPE, UPPER_DEPT_NAME, DEPT_NAME, CUST_INFO
             , PRODUCT_NAME, PRODUCT_DETAIL, MEASURE
             , MM01, MM02, MM03, MM04, MM05, MM06, MM07, MM08, MM09, MM10, MM11, MM12
             , ORI_VERSION_NO, SORT_NO, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT A.DIVISION_ID
             , A.VERSION_NO
             , A.YYYY
             , A.SP_BP_TYPE
             -- [PRODUCTDETAIL 2026-08-10] DM_MOBILE_REPORT_DEPT 의 NOT NULL 5컬럼 —
             --   공급식이 NULL 가능(안쪽 L9462·L9464 NVL(...,'') = Oracle 에선 NULL,
             --   L9465·L9467·L9468 은 NVL 자체 없음) → ORA-01400. 센티널 '-' 를 경계에서 명시.
             --   ⚠ 안쪽이 아니라 여기서 감싼다 — L9423 `IS NULL` 정렬 분기를 보존하기 위함.
             , NVL(NULLIF(RTRIM(A.DEPARTMENT_NAME),''), '/')
             , NVL(NULLIF(RTRIM(A.DEPT_NAME),''), '/')
             , NVL(NULLIF(RTRIM(A.CUST_INFO),''), '/')
             , NVL(NULLIF(RTRIM(A.PRODUCT_NAME),''), '/')
             , NVL(NULLIF(RTRIM(A.PRODUCT_DETAIL),''), '/')
             , CASE WHEN A.MEASURE = 'RTF_SYS_RP' THEN 'RTF' ELSE A.MEASURE END AS MEASURE
             , A.MM01, A.MM02, A.MM03, A.MM04, A.MM05, A.MM06, A.MM07, A.MM08, A.MM09, A.MM10, A.MM11, A.MM12
             , v_ori_version_no AS ORI_VERSION_NO
             , ROW_NUMBER() OVER( PARTITION BY A.YYYY
                                  ORDER BY CASE WHEN A.DEPARTMENT_NAME IS NULL OR A.DEPARTMENT_NAME = '기타' THEN '힣' ELSE A.DEPARTMENT_NAME END
                                         , CASE WHEN A.DEPT_NAME = 'MDF' THEN '힣' ELSE A.DEPT_NAME END
                                         , A.DEPT_NAME
                                         , A.DISPLAY_SEQ
                                         , A.MEASURE) AS SORT_NO
             , v_user_id  AS CREATED_BY
             , SYSDATE    AS CREATION_DATE
             , v_user_id  AS LAST_UPDATED_BY
             , SYSDATE    AS LAST_UPDATE_DATE
        FROM (
                SELECT A.DIVISION_ID
                     , A.VERSION_NO
                     , A.YYYY
                     , A.SP_BP_TYPE
                     , A.DEPARTMENT_NAME
                     , A.DEPT_NAME
                     , A.CUST_REPORT AS CUST_INFO
                     , A.PRODUCT_NAME
                     , A.PRODUCT_DETAIL
                     , A.MEASURE
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '01' THEN A.QTY ELSE 0 END) AS MM01
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '02' THEN A.QTY ELSE 0 END) AS MM02
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '03' THEN A.QTY ELSE 0 END) AS MM03
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '04' THEN A.QTY ELSE 0 END) AS MM04
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '05' THEN A.QTY ELSE 0 END) AS MM05
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '06' THEN A.QTY ELSE 0 END) AS MM06
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '07' THEN A.QTY ELSE 0 END) AS MM07
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '08' THEN A.QTY ELSE 0 END) AS MM08
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '09' THEN A.QTY ELSE 0 END) AS MM09
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '10' THEN A.QTY ELSE 0 END) AS MM10
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '11' THEN A.QTY ELSE 0 END) AS MM11
                     , SUM(CASE WHEN A.YYYYMM = A.YYYY || '12' THEN A.QTY ELSE 0 END) AS MM12
                     , B.DISPLAY_SEQ
                  FROM (
                        SELECT C.DIVISION_ID
                             , P_VERSION_NO AS VERSION_NO
                             , Y.YYYY       AS YYYY
                             , 'SP'         AS SP_BP_TYPE
                             -- TUNE-J 2026-08-10: SELECT 컬럼절 스칼라 서브쿼리 → LEFT OUTER JOIN
                             --   (SELECT 목록 안의 SELECT 는 1순위 FUNCTION 과 동급 대체 대상 — 사용자 지시)
                             --   유일성 실측: SCM_ADM_LOOKUP_MASTER_DETAIL 의 (LOOKUP_TYPE, SEGMENT1) 은
                             --     MDF_DEPARTMENT 15행/15키, DMF0044_DEPARTMENT_TEAM2 29행/29키 로 1:1
                             --     ⇒ LEFT JOIN 이 행을 증식시키지 않는다(원본 ROWNUM=1 과 동일 결과).
                             --   NVL(x,'') 제거 사유: Oracle 은 '' = NULL 이라 NVL(x,'') ≡ x (항등).
                             --     미매치 시 NULL 유지는 **필수** — 바깥 ROW_NUMBER ORDER BY 의
                             --     `DEPARTMENT_NAME IS NULL` 분기와 GROUP BY 가 이 NULL 을 본다.
                             , LD.SEGMENT2  AS DEPARTMENT_NAME
                             , LT.SEGMENT2  AS DEPT_NAME
                             , C.CUST_REPORT
                             , C.END_CUST_REPORT
                             , C.PRODUCT_GROUP AS PRODUCT_NAME
                             -- TUNE-S 2026-08-10: 센티널 정규화를 **집계 안쪽**으로 이동 (ORA-00001 해소).
                             --   바깥에서만 NVL(...,'-') 하면, 원시 NULL 그룹과 리터럴 '-' 그룹이
                             --   따로 집계된 뒤 PK 단계에서 같은 값이 되어 충돌한다
                             --   (실측 PK 중복키 119 — 전부 이 원인. 다른 컬럼 기인 0건).
                             --   안쪽에서 감싸면 두 그룹이 하나로 합쳐지고 QTY 도 합산된다.
                             --   검증: 중복 119→0 / 행 821→702 / MM01~12 총합 차이 0(NUMBER 정밀).
                             --   AS-IS(L150220)는 ISNULL 없이 C.ATTRIBUTE1 — MSSQL 은 ''≠'-' 라
                             --   서로 다른 PK 였다. Oracle 은 ''=NULL 이라 센티널이 하나여야 한다.
                             , NVL(C.ATTRIBUTE1, '-') AS PRODUCT_DETAIL
                             , C.MEASURE
                             , SUBSTR(C.YYYYMMDD, 1, 6) AS YYYYMM
                             , C.QTY
                          FROM SCM_MGR.GT_DMF0044_DEPT_RPT_C C
                          CROSS JOIN ( SELECT DISTINCT SUBSTR(YYYYMMDD, 1, 4) AS YYYY
                                       FROM DM_PLN_SALES_PLAN_REPORT_C
                                       WHERE DIVISION_ID = P_DIVISION_ID AND VERSION_NO = P_VERSION_NO ) Y
                          -- TUNE-J 2026-08-10: 위 선택목록 스칼라 서브쿼리 2건의 조인 대체분
                          LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LD
                            ON LD.LOOKUP_TYPE = 'MDF_DEPARTMENT'           AND LD.SEGMENT1 = C.DEPARTMENT_ID
                          LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LT
                            ON LT.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2' AND LT.SEGMENT1 = C.DEPT_ID
                         WHERE 1 = 1
                           AND C.MEASURE IN ('Business_Plan', 'RTF','RTF_SYS_RP','SalesAmt_KRW')
                           AND C.YYYYMMDD LIKE Y.YYYY || '%'
                       ) A
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                    ON A.CUST_REPORT = B.SEGMENT1 AND B.LOOKUP_TYPE = 'REPORT_GROUP2'
                 GROUP BY A.DIVISION_ID, A.VERSION_NO, A.YYYY, A.SP_BP_TYPE, A.DEPARTMENT_NAME, A.DEPT_NAME
                        , A.CUST_REPORT, A.PRODUCT_NAME, A.PRODUCT_DETAIL, B.DISPLAY_SEQ, A.MEASURE
             ) A;

        n_merge_count := SQL%ROWCOUNT;

    END IF;

    -- 트랜잭션 (COMMIT) - 프로시저 종료 직전 1회
    COMMIT;

    N_LOG_COUNT := n_merge_count;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

    -- 종료 LOG
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'delete_count: ' || TO_CHAR(n_delete_count) || ' / merge_count: ' || TO_CHAR(n_merge_count);
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID' VALUE P_DIVISION_ID,
            'P_VERSION_NO'  VALUE P_VERSION_NO,
            'P_ACTION_TYPE' VALUE P_ACTION_TYPE,
            'P_YYYY'        VALUE P_YYYY
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0044_SALES_REPORT_DEPT_CREATE;


PROCEDURE P_DMF0044_SALES_REPORT_PRODUCT_CREATE 
(
    P_DIVISION_ID       IN  VARCHAR2,
    P_VERSION_NO        IN  VARCHAR2,
    P_ACTION_TYPE       IN  VARCHAR2,   -- T:Transfer, C:Cancel
    P_YYYY              IN  VARCHAR2,
    O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
/*
 * Program ID   : DMF0044_SALES_REPORT_PRODUCT_CREATE
 * Description  : 매출리포트용 데이터 생성 PROCEDURE
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 20190522 JSYOUN Initial Release [PJ20189106] 전지본부 GSCM(DM) 고도화 프로젝트
 * 20191113 KYH 팩일 경우 QTY 조정
 * 20191118 hwi1993 파라미터 추가 및 데이터타입 변경, Cancel 기능 추가
 * 20200512 hwi1993 ETC 매출 테이블 추가
 * 2020/09/09     P.C.I		[C20200909-000203] LOG 표준화 적용
 * 2026/06/05	NextSCM Migration	[PJ202650304] 기존 배포본(미완성 자동변환, INVALID) 재변환. CURSOR 루프→3개년 CROSS JOIN, #TEMP_REPORT_C→인라인, GETDATE→SYSDATE, 로깅/EXCEPTION/O_RESULT_CURSOR 표준 적용. 템플릿=DMF0044_SALES_REPORT_EXCHANGE_RATE_CREATE(VALID)
 */
IS
    V_PROGRAM_NAME      VARCHAR2(200 CHAR);

    -- LOG 용 변수 설정
    V_LOG_TYPE          VARCHAR2(100 CHAR);
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(4000 CHAR);
    V_DESCRIPTION       VARCHAR2(4000 CHAR);
    D_EVENT_DATE        DATE := SYSDATE;
    n_delete_count      PLS_INTEGER := 0;
    n_merge_count       PLS_INTEGER := 0;

    -- local 변수선언
    v_user_id           VARCHAR2(10 CHAR) := 'mdf_batch';

    -- EXCEPTION 블록 필수 변수
    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);

BEGIN
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    -- 시작 LOG  (START)
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;
    V_LOG_MESSAGE := NULL;      /*-- <- 변수 재사용을 위하여 초기화해야함 --*/
    -- 시작 LOG  (END)

    -----------------------------------------------------------------------------------------------------
    --                                                        중복 VERSION이 있는경우 삭제후 COPY (BEGIN)
    -----------------------------------------------------------------------------------------------------
    DELETE FROM SCM_MGR.DM_MOBILE_REPORT_PRODUCT
    WHERE  DIVISION_ID = P_DIVISION_ID
    AND    VERSION_NO  = P_VERSION_NO;

    n_delete_count := SQL%ROWCOUNT;
    -----------------------------------------------------------------------------------------------------
    --                                                        중복 VERSION이 있는경우 삭제후 COPY (END)
    -----------------------------------------------------------------------------------------------------

    -----------------------------------------------------------------------------------------------------
    --                                                                           요청VERSION COPY (BEGIN)
    -----------------------------------------------------------------------------------------------------
    IF P_ACTION_TYPE = 'T' THEN -- 2019.11.19 HWI1993 전송일 경우만 인서트하고, C 일 경우는 자동삭제처리

        -- CURSOR 루프(yyyy-1, yyyy, yyyy+1) 대신 3개 연도 CROSS JOIN 으로 한번에 처리
        INSERT INTO SCM_MGR.DM_MOBILE_REPORT_PRODUCT
             ( DIVISION_ID
             , VERSION_NO
             , YYYY
             , SP_BP_TYPE
             , PRODUCT_NAME
             , PRODUCT_DETAIL
             , MEASURE
             , MM01, MM02, MM03, MM04, MM05, MM06, MM07, MM08, MM09, MM10, MM11, MM12
             , ORI_VERSION_NO
             , SORT_NO
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        -- TUNE-V 2026-08-10: hook #129 1순위(구조) — DM_MST_ITEM_SINGLE_V 사용 중단.
        --   ⚠ 앞선 TUNE-M(/*+ MATERIALIZE */ 로 1회 산출) 은 **실패한 조치**였다.
        --     리터럴 재현에서는 0.7초였으나, 바인드 실사용에서는 붕괴가 사라진 게 아니라
        --     "실체화하는 그 문장" 안으로 옮겨갔을 뿐이다. 그 근거를 남긴다:
        --     SID 512 / SQL_ID 5dchxk6z8k7hg — CPU 4,900초, buffer_gets 2.63억, 처리행 0,
        --     ASH 3,183 샘플 전량(100%)이 플랜 L11 INDEX SKIP SCAN PK_SCM_ITEM_M 한 곳.
        --     (L4 NESTED LOOPS EST 13억 / L6 VIEW PUSHED PREDICATE starts 35,238)
        --   원인: 뷰가 SCM_MST_ITEM_SN 을 SUBSTR(ITEM_ID,1,12) 로 집계한 인라인뷰와
        --     셀프조인하는 구조라, 옵티마이저가 PUSHED PREDICATE 를 걸면 GROUP BY 뷰가
        --     행별 상관 집계로 전개되고 비-SARGable SUBSTR 필터가 구동행 수만큼 반복된다.
        --   조치: 힌트로 판단을 바꾸는 대신 **셀프조인 자체를 제거** — PUSHED PREDICATE 가
        --     성립 불가능한 단일 패스 + 분석함수 형태로 바꾼다(2순위 SARGable 문제도 동시 소멸).
        --   등가: T2 는 같은 테이블을 같은 키로 집계한 것이라 T1 의 모든 행이 반드시 자기 그룹과
        --     매칭된다(inner join 이 행을 떨구지 않음) ⇒ "T1 그룹별 MAX(T2.col)"
        --     = "SUBSTR12 파티션 전체의 MAX(col)". 실측 DIVISION_ID='40':
        --     168,619행 / BIZ NOT NULL 9,895 / PACK 합 34,086 — OLD·NEW 완전일치,
        --     MINUS 양방향 0행 PASS, COST 1,618,474 → 8,499, 서버측 0.41초 → 0.21초.
        WITH ISV AS (
            -- /*+ MATERIALIZE */ 유지 사유: ISV 는 아래 UNION ALL 두 갈래에서 각각 참조된다.
            --   붕괴 방지용이 아니라 **중복 산출 방지용**이다(3순위 힌트는 불필요해짐).
            SELECT /*+ MATERIALIZE */ DIVISION_ID, ITEM_ID
                 , MAX(MAX(FORECAST_INFO_BIZ_TYPE))
                       OVER (PARTITION BY DIVISION_ID, SUBSTR(ITEM_ID,1,12)) AS FORECAST_INFO_BIZ_TYPE
                 , MAX(MAX(FORECAST_INFO_CELL_PACK_COUNT))
                       OVER (PARTITION BY DIVISION_ID, SUBSTR(ITEM_ID,1,12)) AS FORECAST_INFO_CELL_PACK_COUNT
              FROM SCM_MST_ITEM_SN
             -- TUNE-M2 2026-08-10: 사전필터(유지). 조인이 A.DIVISION_ID = B.DIVISION_ID 이고
             --   A 는 항상 DIVISION_ID = P_DIVISION_ID 로 걸리므로 타 division 행은
             --   조인될 수 없다 ⇒ 결과 불변.
             WHERE DIVISION_ID = P_DIVISION_ID
             GROUP BY DIVISION_ID, ITEM_ID )
        SELECT A.DIVISION_ID
             , P_VERSION_NO AS VERSION_NO
             , Y.YYYY        AS YYYY
             , 'SP'          AS SP_BP_TYPE
             , A.PRODUCT_GROUP AS PRODUCT_NAME
             -- [PRODUCTDETAIL 2026-08-10] Oracle 은 '' = NULL 이라 NOT NULL 컬럼
             --   DM_MOBILE_REPORT_PRODUCT.PRODUCT_DETAIL 이 ORA-01400 으로 항상 실패했다
             --   (MSSQL 원문은 '' 가 빈 문자열이라 통과). 빈 값 센티널 '-' 명시 —
             --   같은 BODY L149·L677 이 이미 쓰는 값(hook #119 §1.5 계열, 사용자 확정).
             , CASE WHEN A.PRODUCT_GROUP = '파우치형' THEN NVL(A.ATTRIBUTE1,'-')
                    WHEN A.PRODUCT_GROUP = '원통형' THEN NVL(A.ATTRIBUTE2,'-')
                    ELSE '-'
               END           AS PRODUCT_DETAIL
             , A.MEASURE
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '01' THEN A.QTY ELSE 0 END) AS MM01
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '02' THEN A.QTY ELSE 0 END) AS MM02
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '03' THEN A.QTY ELSE 0 END) AS MM03
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '04' THEN A.QTY ELSE 0 END) AS MM04
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '05' THEN A.QTY ELSE 0 END) AS MM05
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '06' THEN A.QTY ELSE 0 END) AS MM06
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '07' THEN A.QTY ELSE 0 END) AS MM07
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '08' THEN A.QTY ELSE 0 END) AS MM08
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '09' THEN A.QTY ELSE 0 END) AS MM09
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '10' THEN A.QTY ELSE 0 END) AS MM10
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '11' THEN A.QTY ELSE 0 END) AS MM11
             , SUM(CASE WHEN SUBSTR(A.YYYYMMDD,1,6) = Y.YYYY || '12' THEN A.QTY ELSE 0 END) AS MM12
             -- TUNE-J 2026-08-10: SELECT 컬럼절 스칼라 서브쿼리 → LEFT OUTER JOIN.
             --   집계(MAX)만 있고 GROUP BY 가 없는 인라인뷰는 **항상 정확히 1행**을 돌려주므로
             --   LEFT JOIN ON 1=1 은 행을 떨구지도 늘리지도 않는다(0행이면 NULL → NVL 로 '-').
             --   PK_DM_MDF_VERSION=(DIVISION_ID,VERSION_NO) UNIQUE ⇒ MAX() = 원본 ROWNUM=1.
             , NVL(OV.ORI_VERSION_NO, '/') AS ORI_VERSION_NO
             , B.DISPLAY_SEQ AS SORT_NO
             , v_user_id   AS CREATED_BY
             , SYSDATE      AS CREATION_DATE
             , v_user_id   AS LAST_UPDATED_BY
             , SYSDATE      AS LAST_UPDATE_DATE
          FROM (
                SELECT A.DIVISION_ID, A.PRODUCT_GROUP
                     , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF' ELSE A.MEASURE END AS MEASURE
                     , A.YYYYMMDD, A.ATTRIBUTE1, A.ATTRIBUTE2
                     , CASE WHEN A.MEASURE = 'RTF' AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1)
                            ELSE A.QTY
                       END AS QTY
                  FROM DM_PLN_SALES_PLAN_REPORT_C A
                  LEFT OUTER JOIN ISV B
                    ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.MEASURE IN ('RTF','Business_Plan','SalesAmt_KRW')
                UNION ALL
                SELECT A.DIVISION_ID, A.PRODUCT_GROUP
                     , CASE WHEN A.MEASURE = 'Business_Plan' THEN 'RTF' ELSE A.MEASURE END AS MEASURE
                     , A.YYYYMMDD, A.ATTRIBUTE1, A.ATTRIBUTE2
                     , CASE WHEN A.MEASURE = 'RTF' AND B.FORECAST_INFO_BIZ_TYPE = 'PACK' AND B.FORECAST_INFO_CELL_PACK_COUNT <> 0 THEN A.QTY * NVL(B.FORECAST_INFO_CELL_PACK_COUNT, 1)
                            ELSE A.QTY
                       END AS QTY
                  FROM DM_PLN_SALES_ETC_REPORT_C A
                  LEFT OUTER JOIN ISV B
                    ON A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.MEASURE IN ('RTF','Business_Plan','SalesAmt_KRW')
               ) A
          LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
            ON A.PRODUCT_GROUP = B.SEGMENT1 AND B.LOOKUP_TYPE = 'REPORT_GROUP2'
          CROSS JOIN (
                SELECT TO_CHAR(TO_NUMBER(P_YYYY) - 1) AS YYYY FROM DUAL
                UNION ALL
                SELECT P_YYYY AS YYYY FROM DUAL
                UNION ALL
                SELECT TO_CHAR(TO_NUMBER(P_YYYY) + 1) AS YYYY FROM DUAL
               ) Y
          -- TUNE-J 2026-08-10: 위 ORI_VERSION_NO 스칼라 서브쿼리의 조인 대체분 (항상 1행)
          LEFT OUTER JOIN ( SELECT MAX(V.ORI_VERSION_NO) AS ORI_VERSION_NO
                              FROM SCM_MGR.DM_MDF_VERSION V
                             WHERE V.DIVISION_ID = P_DIVISION_ID
                               AND V.VERSION_NO  = P_VERSION_NO ) OV
            ON 1 = 1
         WHERE 1 = 1
           AND A.YYYYMMDD LIKE Y.YYYY || '%'
         GROUP BY A.DIVISION_ID
             , A.PRODUCT_GROUP
             , CASE WHEN A.PRODUCT_GROUP = '파우치형' THEN NVL(A.ATTRIBUTE1,'-')
                    WHEN A.PRODUCT_GROUP = '원통형' THEN NVL(A.ATTRIBUTE2,'-')
                    ELSE '-'
               END
             , A.MEASURE
             , B.DISPLAY_SEQ
             , Y.YYYY
             -- TUNE-J 2026-08-10: OV 는 전 행에 걸쳐 단일 값(1행 인라인뷰)이므로
             --   GROUP BY 에 추가해도 그룹 구성은 불변이다. 선택목록에 든 이상 문법상 필수.
             , OV.ORI_VERSION_NO;

        n_merge_count := SQL%ROWCOUNT;

    END IF;
    -----------------------------------------------------------------------------------------------------
    --                                                                           요청VERSION COPY (END)
    -----------------------------------------------------------------------------------------------------

    -- 트랜잭션 (COMMIT) - 프로시저 종료 직전 1회
    COMMIT;

    N_LOG_COUNT := n_merge_count;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

    -- 종료 LOG
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'delete_count: ' || TO_CHAR(n_delete_count) || ' / merge_count: ' || TO_CHAR(n_merge_count);
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID' VALUE P_DIVISION_ID,
            'P_VERSION_NO'  VALUE P_VERSION_NO,
            'P_ACTION_TYPE' VALUE P_ACTION_TYPE,
            'P_YYYY'        VALUE P_YYYY
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0044_SALES_REPORT_PRODUCT_CREATE;

END PKG_DMF0044;
/
SHOW ERRORS PACKAGE BODY PKG_DMF0044
-- ##### END PACKAGE BODY PKG_DMF0044

-- ##### START PACKAGE BODY PKG_DMF0045
CREATE OR REPLACE PACKAGE BODY PKG_DMF0045
AS
/****************************************************************************************************/
/* Program ID  : PKG_DMF0045                                                                        */
/* Description : Shipment Request                                                                   */
/* Program History                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2026.09.24  ZIONEX       [PJ202650304] MSSQL -> Oracle 전환                                      */
/****************************************************************************************************/

/****************************************************************************************************/
/* Program ID  : P_DMF0045_GET_SHIPMENT_REQUEST                                                     */
/* Description : 출하요청 조회                                                                      */
/****************************************************************************************************/
PROCEDURE P_DMF0045_GET_SHIPMENT_REQUEST
(
    P_SHEET_NAME        IN  VARCHAR2
  , P_DIVISION_ID       IN  VARCHAR2
  , P_TEAM_ID           IN  VARCHAR2
  , P_CUSTOMER          IN  VARCHAR2
  , P_SCM_SITE_ID       IN  VARCHAR2
  , P_PLANT_SITE_ID     IN  VARCHAR2
  , P_PROJECT_CODE      IN  VARCHAR2
  , P_ITEM_ID           IN  VARCHAR2
  , P_FROM_YYYYMMDD     IN  VARCHAR2
  , P_TO_YYYYMMDD       IN  VARCHAR2
  , P_CREATED_BY        IN  VARCHAR2
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    V_PROGRAM_ID                VARCHAR2(8 CHAR)    := 'DMF0045';
    V_STOCK_YYYYMMDD            VARCHAR2(8 CHAR);
    V_CUTOFF_DATE               VARCHAR2(8 CHAR);
    V_USER_MEA_CNT              NUMBER              := 0;
    V_BIZ_TYPE                  VARCHAR2(8 CHAR);
    V_LANG                      VARCHAR2(200 CHAR);

    V_SHEET_NAME                VARCHAR2(10 CHAR)   := P_SHEET_NAME;
    V_DIVISION_ID               VARCHAR2(30 CHAR)   := P_DIVISION_ID;
    V_TEAM_ID                   VARCHAR2(4000 CHAR) := P_TEAM_ID;
    V_CUSTOMER                  VARCHAR2(4000 CHAR) := P_CUSTOMER;
    V_SCM_SITE_ID               VARCHAR2(4000 CHAR) := P_SCM_SITE_ID;
    V_PLANT_SITE_ID             VARCHAR2(4000 CHAR) := P_PLANT_SITE_ID;
    V_PROJECT_CODE              VARCHAR2(4000 CHAR) := P_PROJECT_CODE;
    V_ITEM_ID                   VARCHAR2(4000 CHAR) := P_ITEM_ID;
    V_FROM_YYYYMMDD             VARCHAR2(8 CHAR)    := P_FROM_YYYYMMDD;
    V_TO_YYYYMMDD               VARCHAR2(8 CHAR)    := P_TO_YYYYMMDD;
    V_CREATED_BY                VARCHAR2(50 CHAR)   := P_CREATED_BY;

    V_SCP_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE             VARCHAR2(10 CHAR);
    V_SCP_SEQ                   NUMBER;

    V_QRY_SUM                   CLOB;
    V_EXEC                      CLOB;

BEGIN

    /* 조회조건 ALL 은 조건 없음으로 다룬다 */
    IF UPPER(TRIM(V_TEAM_ID))       = 'ALL' THEN V_TEAM_ID       := NULL; END IF;
    IF UPPER(TRIM(V_CUSTOMER))      = 'ALL' THEN V_CUSTOMER      := NULL; END IF;
    IF UPPER(TRIM(V_SCM_SITE_ID))   = 'ALL' THEN V_SCM_SITE_ID   := NULL; END IF;
    IF UPPER(TRIM(V_PLANT_SITE_ID)) = 'ALL' THEN V_PLANT_SITE_ID := NULL; END IF;
    IF UPPER(TRIM(V_PROJECT_CODE))  = 'ALL' THEN V_PROJECT_CODE  := NULL; END IF;
    IF UPPER(TRIM(V_ITEM_ID))       = 'ALL' THEN V_ITEM_ID       := NULL; END IF;

    V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 3, 'YYYYMMDD');   /* FROM -3일 */

    /* 2026.09.30 AJS 수정 (START) */
--    BEGIN
--        SELECT LANGUAGE
--          INTO V_LANG
--          FROM TB_FX_USER
--         WHERE USERID = V_CREATED_BY;
--    EXCEPTION
--        WHEN NO_DATA_FOUND THEN V_LANG := NULL;
--        WHEN TOO_MANY_ROWS THEN V_LANG := NULL;
--    END;
    BEGIN
        SELECT LANG_CD
          INTO V_LANG
          FROM SCM_ADM_USER_M
         WHERE USER_ID = V_CREATED_BY;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_LANG := NULL;
        WHEN TOO_MANY_ROWS THEN V_LANG := NULL;
    END;
    /* 2026.09.30 AJS 수정 (END) */

    /********************************************************************************
    * 임시테이블 초기화
    ********************************************************************************/
    DELETE FROM GT_DMF0045_LOC;
    DELETE FROM GT_DMF0045_MEASURE;
    DELETE FROM GT_DMF0045_SHIP_REQ;
    DELETE FROM GT_DMF0045_PLAN;
    DELETE FROM GT_DMF0045_SHIP_ROW;
    DELETE FROM GT_DMF0045_PIVOT;
    DELETE FROM GT_DMF0045_REQUESTOR;
    DELETE FROM GT_DMF0045_STOCK;
    DELETE FROM GT_DMF0045_PLAN_FG;
    DELETE FROM GT_DMF0045_MKT;
    DELETE FROM GT_DMF0045_ETD;
    DELETE FROM GT_DMF0045_BOH;

    IF V_SHEET_NAME = 'Pack Biz'
    THEN
        V_BIZ_TYPE := 'P';
        INSERT INTO GT_DMF0045_LOC (SHT_NAME, DIVISION_ID, LOC_CODE) VALUES (V_SHEET_NAME, V_DIVISION_ID, 'PACK_OWMS');
        INSERT INTO GT_DMF0045_LOC (SHT_NAME, DIVISION_ID, LOC_CODE) VALUES (V_SHEET_NAME, V_DIVISION_ID, 'CMA_BMA');
    ELSE
        V_BIZ_TYPE := 'A';
        INSERT INTO GT_DMF0045_LOC (SHT_NAME, DIVISION_ID, LOC_CODE) VALUES (V_SHEET_NAME, V_DIVISION_ID, 'CELL_OWMS');
        INSERT INTO GT_DMF0045_LOC (SHT_NAME, DIVISION_ID, LOC_CODE) VALUES (V_SHEET_NAME, V_DIVISION_ID, 'FORMATION_CHECK_PACKAGING');
    END IF;

    /* 측정값 설정 */
    IF V_BIZ_TYPE = 'P'
    THEN
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('RTF_SCP', 'RTF_System[R+P]', 'P', 'N', '219,229,241', 'Y', 1);
        /* [CSR 요청번호:C20200121-000352][c20200403-000258] */
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SCP_SHIP_PLAN', 'SCP Ship Plan', 'P', 'A', '252,213,180', 'Y', 2);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SHIP_REQ', 'Ship Req', 'P', 'N', '215,227,188', 'Y', 3);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SHIP_PLAN', 'Ship Plan', 'P', 'N', '255,255,255', 'Y', 4);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('PACK_FP', 'Pack FP', 'P', 'Y', '219,229,241', 'Y', 5);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('TOTAL_PLAN', 'Total(Plan)', 'P', 'Y', '219,229,241', 'Y', 6);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('TOTAL_REQ', 'Total(Req)', 'P', 'Y', '219,229,241', 'Y', 7);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('WH_BOH_PLAN', 'W/H BOH(Plan)', 'P', 'Y', '219,229,241', 'Y', 8);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('WH_BOH_REQ', 'W/H BOH(Req)', 'P', 'Y', '219,229,241', 'Y', 9);
    ELSE
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('RTF_SCP', 'RTF_System[R+P]', 'A', 'N', '219,229,241', 'Y', 1);
        /* [CSR 요청번호:C20200121-000352][c20200403-000258] */
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SCP_SHIP_PLAN', 'SCP Ship Plan', 'A', 'A', '252,213,180', 'Y', 2);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SHIP_REQ', 'Ship Req', 'A', 'N', '215,227,188', 'Y', 3);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SHIP_PLAN', 'Ship Plan', 'A', 'N', '255,255,255', 'Y', 4);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('SITE_MOVE', 'Site-Move Plan', 'A', 'Y', '219,229,241', 'Y', 5);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('INTN_MOVEMENT', 'Internal movement', 'A', 'Y', '219,229,241', 'Y', 6);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('INSP_PLAN', 'Inspection plan', 'A', 'Y', '219,229,241', 'Y', 7);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('TOTAL_PLAN', 'Total(Plan)', 'A', 'Y', '219,229,241', 'Y', 8);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('TOTAL_REQ', 'Total(Req)', 'A', 'Y', '219,229,241', 'Y', 9);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('WH_BOH_PLAN', 'W/H BOH(Plan)', 'A', 'Y', '219,229,241', 'Y', 10);
        INSERT INTO GT_DMF0045_MEASURE (MEASURE, MEASURE_LABEL, BIZ_TYPE, SUM_CHECK, MEASURE_COLOR, DEL_FLAG, SEQ) VALUES ('WH_BOH_REQ', 'W/H BOH(Req)', 'A', 'Y', '219,229,241', 'Y', 11);
    END IF;

    /* 사용자 측정값 처리 */
    SELECT COUNT(*)
      INTO V_USER_MEA_CNT
      FROM SCM_MST_TITLESET_USER
     WHERE PROGRAM_ID                      = V_PROGRAM_ID
       AND SHEET_NAME                      = V_SHEET_NAME
       AND USER_INQUIRY_COLUMN_TYPE_CODE   = 'M'
       AND USER_ID                         = V_CREATED_BY;

    IF V_USER_MEA_CNT = 0
    THEN
        INSERT INTO SCM_MST_TITLESET_USER
                    (
                      USER_ID
                    , PROGRAM_ID
                    , SHEET_NAME
                    , USER_INQUIRY_COLUMN_TYPE_CODE
                    , COLUMN_NAME
                    , SORT_ORDER_NO
                    , SUB_TOTAL_FLAG
                    , DATA_SORT_METHOD_CODE
                    , CREATED_BY
                    , CREATION_DATE
                    , LAST_UPDATED_BY
                    , LAST_UPDATE_DATE
                    )
        SELECT V_CREATED_BY
             , PROGRAM_ID
             , SHEET_NAME
             , 'M'
             , COLUMN_NAME
             , SORT_ORDER_NO
             , 'N'
             , '-'
             , V_CREATED_BY
             , SYSDATE
             , V_CREATED_BY
             , SYSDATE
          FROM SCM_MST_SHEET_MEASURE
         WHERE PROGRAM_ID   = V_PROGRAM_ID
           AND SHEET_NAME   = V_SHEET_NAME
           AND DEFAULT_FLAG = 'Y'
           AND VALID_YN     = 'Y';
    END IF;

    UPDATE GT_DMF0045_MEASURE A
       SET A.DEL_FLAG = 'N'
     WHERE EXISTS (SELECT 1
                     FROM SCM_MST_TITLESET_USER B
                    WHERE B.COLUMN_NAME                     = A.MEASURE
                      AND B.PROGRAM_ID                      = V_PROGRAM_ID
                      AND B.SHEET_NAME                      = V_SHEET_NAME
                      AND B.USER_ID                         = V_CREATED_BY
                      AND B.USER_INQUIRY_COLUMN_TYPE_CODE   = 'M');

    -----------------------------------------------
    -- 3. Ship Req : 출하 요청(Sales향 Ship Req)
    --               DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ'
    -----------------------------------------------
    INSERT INTO GT_DMF0045_SHIP_REQ
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, CREATED_BY, QTY, SEQ, RN
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.PLANT_SITE_ID                                                  AS FROM_SITE
         , A.SCM_SITE_ID                                                    AS TO_SITE
         , CASE V_LANG WHEN 'EN' THEN C.DEPT_NAME_EN
                       WHEN 'CN' THEN C.DEPT_NAME_CN
                       ELSE C.DEPT_NAME_KO
           END                                                              AS DEPT
         , B.END_CUSTOMER
         , A.PROJECT_CODE
         , A.INCOTERMS
         , A.FCST_TYPE                                                      AS FCST_TYPE
         , A.TRANSPORT_MODE                                                 AS TR_MODE
         , A.BOD_ID
         , 'SHIP_REQ'                                                       AS MEASURE
         , A.YYYYMMDD
         , A.LAST_UPDATED_BY                                                AS CREATED_BY
         , A.QTY
         , 3                                                                AS SEQ
         , RANK() OVER (PARTITION BY A.DIVISION_ID, A.ITEM_ID, A.PLANT_SITE_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.FCST_TYPE
                                   , A.INCOTERMS, A.TRANSPORT_MODE
                            ORDER BY A.LAST_UPDATE_DATE DESC)               AS RN
      FROM DM_PLN_SHIPMENT_REQ A
         , SCM_MST_SITE B
         /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
         , SCM_MST_SITE_ITEM_DEPT_V IB
         /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
         , SCM_MST_SSO_DEPT_INFO C
         , (SELECT DISTINCT DIVISION_ID
                 , ITEM_ID
                 , SCP_OPERATION_GROUP
              FROM SCM_MST_ITEM_SN
             WHERE DIVISION_ID         = V_DIVISION_ID
               AND ACTIVE_FLAG         = 'Y'
               AND SCP_OPERATION_GROUP = V_BIZ_TYPE                             /* CELL/PACK 구분 */
           ) IA
     WHERE A.DIVISION_ID       = B.DIVISION_ID
       AND A.SCM_SITE_ID       = B.SCM_SITE_ID
       AND B.VALID_YN          = 'Y'
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND B.DEPT_ID           = C.DEPT_ID(+)
       AND A.DIVISION_ID       = IB.DIVISION_ID(+)
       AND A.SCM_SITE_ID       = IB.SCM_SITE_ID(+)
       AND A.ITEM_ID           = IB.ITEM_ID(+)
       AND IB.DEPT_ID          = C.DEPT_ID(+)
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND A.DIVISION_ID       = IA.DIVISION_ID
       AND A.ITEM_ID           = IA.ITEM_ID
       AND A.SCM_SITE_ID NOT IN (SELECT SEGMENT1
                                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                  WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
                                    AND VALID_YN    = 'Y'
                                    AND SEGMENT3    = V_DIVISION_ID)
       AND A.MEASURE           = 'SHIP_REQ'
       AND A.SITE_TYPE         = 'SALES'
       AND A.QTY               > 0
       AND A.DIVISION_ID       = V_DIVISION_ID
       AND A.YYYYMMDD          >= V_FROM_YYYYMMDD
       AND A.YYYYMMDD          <= V_TO_YYYYMMDD
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND (TRIM(V_TEAM_ID) IS NULL OR B.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       AND (TRIM(V_TEAM_ID) IS NULL OR IB.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.PLANT_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
       AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

    -----------------------------------------------
    -- 1. RTF
    -- FromSite 를 Global PSI 에서 Div, Item_Id, To_Site, Incoterms 기준으로 찾아와서 사용한다.
    -----------------------------------------------
    BEGIN
        SELECT PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , PLAN_SEQ
          INTO V_SCP_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , V_SCP_SEQ
          FROM (SELECT A.PLAN_START_YYYYMMDD
                     , A.PLAN_TYPE
                     , A.PLAN_SEQ
                  FROM SCP_PLAN_VERSION_V A
                 WHERE A.DIVISION_ID = V_DIVISION_ID
                   AND A.PLAN_CYCLE  = 'WEEKLY'
                   AND A.PLAN_TYPE   = 'FN'
                 ORDER BY A.PLAN_START_YYYYMMDD DESC
                        , A.PLAN_TYPE_ORDER DESC
                        , A.PLAN_SEQ DESC
               )
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_SCP_PLAN_START_YYYYMMDD := NULL;
            V_SCP_PLAN_TYPE           := NULL;
            V_SCP_SEQ                 := NULL;
    END;

    /* [C20200701-000388]                                                                       */
    /* SCP_ANL_SHIPMENT_PLAN_FG에는 없는 FCST_TYPE 추출을 위해                                  */
    /* SCP_ANL_SHIPMENT_PLAN_FG의 원천인 SCP_PLN_SHIPMENT_PLAN_PEGGING + SCP_PLN_SHIPMENT_PLAN   */
    INSERT INTO GT_DMF0045_PLAN_FG
                (
                  DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
                , ITEM_ID, TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, TRANSPORT_MODE, MEASURE, YYYYMMDD, QTY
                )
    SELECT DIVISION_ID
         , PLAN_START_YYYYMMDD
         , PLAN_TYPE
         , SEQ
         , MAX(OPERATION_GROUP)                                             AS BIZ_TYPE
         , NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/')                                           AS PROJECT_CODE
         , FCST_TYPE
         , ITEM_ID
         , TO_SITE
         , INCOTERMS
         , FROM_SITE
         , BOD_ID
         , TRANSPORT_MODE
         , MEASURE
         , YYYYMMDD
         , SUM(QTY)                                                         AS QTY
      FROM (SELECT B.DIVISION_ID
                 , B.PLAN_START_YYYYMMDD
                 , B.PLAN_TYPE
                 , B.SEQ
                 , B.OPERATION_GROUP
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , B.ITEM_ID
                 , B.TO_SITE
                 , (SELECT X.SSP_INCOTERMS
                      FROM SCP_MST_BOD_N_V X
                     WHERE X.DIVISION_ID = B.DIVISION_ID
                       AND X.BOD_ID      = B.BOD_ID
                       AND ROWNUM        = 1)                               AS INCOTERMS
                 , B.FROM_SITE
                 , B.BOD_ID
                 , B.TRANSPORT_MODE
                 , B.MEASURE
                 , B.YYYYMMDD
                 , A.ALLOCATION_QTY                                         AS QTY
              FROM SCP_PLN_SHIPMENT_PLAN_PEGGING A
                 , SCP_PLN_SHIPMENT_PLAN B
             WHERE A.MASTER_ID               = B.MASTER_ID(+)
               AND A.PLAN_ID                 = B.PLAN_ID(+)
               AND A.OUT_VERSION_ID          = B.OUT_VERSION_ID(+)
               AND A.DIVISION_ID             = B.DIVISION_ID(+)
               AND A.PLAN_START_YYYYMMDD     = B.PLAN_START_YYYYMMDD(+)
               AND A.PLAN_TYPE               = B.PLAN_TYPE(+)
               AND A.SEQ                     = B.SEQ(+)
               AND A.ORDER_ID                = B.ORDER_ID(+)
               AND B.MEASURE(+)              = 'SHIP_PLAN'
               AND B.SEMI_YN(+)              = 'N'
               AND B.DIVISION_ID            IS NOT NULL
               AND B.OPERATION_GROUP         = V_BIZ_TYPE
               AND B.YYYYMMDD               >= V_FROM_YYYYMMDD
               AND B.YYYYMMDD               <= V_TO_YYYYMMDD
               AND B.TO_SITE            NOT IN (SELECT SEGMENT1
                                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                 WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
                                                   AND VALID_YN    = 'Y'
                                                   AND SEGMENT3    = V_DIVISION_ID)
               AND A.DIVISION_ID             = V_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD     = V_SCP_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE               = V_SCP_PLAN_TYPE
               AND A.SEQ                     = V_SCP_SEQ
           ) XA
     GROUP BY DIVISION_ID
            , PLAN_START_YYYYMMDD
            , PLAN_TYPE
            , SEQ
            , NVL(PROJECT_CODE, '/')
            , FCST_TYPE
            , ITEM_ID
            , TO_SITE
            , INCOTERMS
            , FROM_SITE
            , TRANSPORT_MODE
            , BOD_ID
            , MEASURE
            , YYYYMMDD;

    /* 82 일 경우 RTF 대신 SCP_Ship_plan 추가 [CSR 요청번호:C20200121-000352][c20200403-000258] */
    INSERT INTO GT_DMF0045_PLAN
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.FROM_SITE
         , A.TO_SITE
         , CASE V_LANG WHEN 'EN' THEN D.DEPT_NAME_EN
                       WHEN 'CN' THEN D.DEPT_NAME_CN
                       ELSE D.DEPT_NAME_KO
           END                                                              AS DEPT
         , C.END_CUSTOMER                                                   AS END_CUSTOMER
         , A.PROJECT_CODE
         , A.INCOTERMS
         , NVL(A.FCST_TYPE, '')                                             AS FCST_TYPE
         , A.TRANSPORT_MODE                                                 AS TR_MODE
         , A.BOD_ID
         , 'SCP_SHIP_PLAN'                                                  AS MEASURE
         , A.YYYYMMDD
         , A.QTY
         , 2                                                                AS SEQ
      FROM GT_DMF0045_PLAN_FG A
         , SCM_SYS_CALENDAR_M B
         , SCM_MST_SITE C
         /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
         , SCM_MST_SITE_ITEM_DEPT_V IB
         /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
         , SCM_MST_SSO_DEPT_INFO D
     WHERE A.YYYYMMDD          = B.BASIS_YYYYMMDD
       AND A.TO_SITE           = C.SCM_SITE_ID
       AND A.DIVISION_ID       = C.DIVISION_ID
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND C.DEPT_ID           = D.DEPT_ID(+)
       AND A.DIVISION_ID       = IB.DIVISION_ID(+)
       AND A.TO_SITE           = IB.SCM_SITE_ID(+)
       AND A.ITEM_ID           = IB.ITEM_ID(+)
       AND IB.DEPT_ID          = D.DEPT_ID(+)
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND A.MEASURE           = 'SHIP_PLAN'
       AND A.BIZ_TYPE          = V_BIZ_TYPE
       AND A.DIVISION_ID       = V_DIVISION_ID
       AND A.YYYYMMDD          >= V_FROM_YYYYMMDD
       AND A.YYYYMMDD          <= V_TO_YYYYMMDD
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND (TRIM(V_TEAM_ID) IS NULL OR C.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       AND (TRIM(V_TEAM_ID) IS NULL OR IB.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
       AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))));

    /* AS 고객향 DM MKT_FCST 적용                                                            */
    /* ★ 출발일 계산 함수(FN_GET_SSP_ETD_DATE)가 한 번에 0.3초 걸리므로                      */
    /*   대상을 먼저 담고, 같은 (사업부 · BOD · 도착일) 은 한 번만 계산해 붙인다.            */
    INSERT INTO GT_DMF0045_MKT
                (
                  DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, FCST_TYPE, INCOTERMS
                , BOD_ID, PLANT_SITE_ID, DM_YYYYMMDD, QTY, END_CUSTOMER, DEPT
                )
    SELECT A.DIVISION_ID
         , A.PROJECT_CODE
         , A.SCM_SITE_ID
         , A.ITEM_ID
         , A.FCST_TYPE
         , A.INCOTERMS
         , (SELECT BOD_ID
              FROM (SELECT BOD_ID
                      FROM SCP_MST_BOD_V                                        /* 현재일 기준으로 */
                     WHERE DIVISION_ID   = A.DIVISION_ID
                       AND FROM_SITE     = A.ATTRIBUTE10
                       AND TO_SITE       = A.SCM_SITE_ID
                       AND INCOTERMS     = A.INCOTERMS
                       AND BOD_VALID_YN  = 'Y'
                     ORDER BY PRIORITY
                   )
             WHERE ROWNUM = 1)                                                  AS BOD_ID
         , A.ATTRIBUTE10                                                        AS PLANT_SITE_ID
         , A.YYYYMMDD                                                           AS DM_YYYYMMDD
         , A.QTY
         , C.END_CUSTOMER
         , CASE V_LANG WHEN 'EN' THEN D.DEPT_NAME_EN
                       WHEN 'CN' THEN D.DEPT_NAME_CN
                       ELSE D.DEPT_NAME_KO
           END                                                                  AS DEPT
      FROM DM_PLN_MKT_FCST A
         , SCM_MST_SITE B
         , SCM_MST_SITE C
         /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
         , SCM_MST_SITE_ITEM_DEPT_V IB
         /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
         , SCM_MST_SSO_DEPT_INFO D
     WHERE A.DIVISION_ID       = B.DIVISION_ID
       AND A.ATTRIBUTE10       = B.SCM_SITE_ID
       AND B.SITE_TYPE         = 'PLANT'
       AND B.OPERATION_GROUP   = CASE WHEN V_BIZ_TYPE = 'P' THEN 'W' ELSE 'Z' END
       AND B.VALID_YN          = 'Y'
       AND A.DIVISION_ID       = C.DIVISION_ID
       AND A.SCM_SITE_ID       = C.SCM_SITE_ID
       AND C.SITE_TYPE         = 'SALES'
       AND C.VALID_YN          = 'Y'
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND C.DEPT_ID           = D.DEPT_ID(+)
       AND A.DIVISION_ID       = IB.DIVISION_ID(+)
       AND A.SCM_SITE_ID       = IB.SCM_SITE_ID(+)
       AND A.ITEM_ID           = IB.ITEM_ID(+)
       AND IB.DEPT_ID          = D.DEPT_ID(+)
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND A.MEASURE           = 'MKT_FCST'
       AND NVL(C.ATTRIBUTE2, 'N') = 'Y'                                         /* 자동 생성 여부 */
       AND A.QTY               > 0
       AND A.DIVISION_ID       = V_DIVISION_ID
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND (TRIM(V_TEAM_ID) IS NULL OR C.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       AND (TRIM(V_TEAM_ID) IS NULL OR IB.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
       AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.ATTRIBUTE10 IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))));

    INSERT INTO GT_DMF0045_ETD
                (
                  DIVISION_ID, BOD_ID, DM_YYYYMMDD, ETD_YYYYMMDD
                )
    SELECT DIVISION_ID
         , BOD_ID
         , DM_YYYYMMDD
         , FN_GET_SSP_ETD_DATE(DIVISION_ID, BOD_ID, DM_YYYYMMDD)                AS ETD_YYYYMMDD
      FROM (SELECT DISTINCT A.DIVISION_ID
                 , A.BOD_ID
                 , A.DM_YYYYMMDD
              FROM GT_DMF0045_MKT A
                 , SCP_MST_BOD_N_V B
             WHERE A.BOD_ID = B.BOD_ID
           );

    INSERT INTO GT_DMF0045_PLAN
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.PLANT_SITE_ID                                                      AS FROM_SITE
         , A.SCM_SITE_ID                                                        AS TO_SITE
         , A.DEPT
         , A.END_CUSTOMER
         , A.PROJECT_CODE
         , NVL(B.SSP_INCOTERMS, B.INCOTERMS)                                    AS INCOTERMS
         , A.FCST_TYPE
         , B.TRANSPORT_MODE                                                     AS TR_MODE
         , B.BOD_ID
         , 'SCP_SHIP_PLAN'                                                      AS MEASURE
         , C.ETD_YYYYMMDD                                                       AS YYYYMMDD
         , A.QTY
         , 2                                                                    AS SEQ
      FROM GT_DMF0045_MKT A
         , SCP_MST_BOD_N_V B
         , GT_DMF0045_ETD C
     WHERE A.BOD_ID          = B.BOD_ID
       AND A.DIVISION_ID     = C.DIVISION_ID
       AND A.BOD_ID          = C.BOD_ID
       AND A.DM_YYYYMMDD     = C.DM_YYYYMMDD
       AND C.ETD_YYYYMMDD   >= V_FROM_YYYYMMDD
       AND C.ETD_YYYYMMDD   <= V_TO_YYYYMMDD;

    IF V_BIZ_TYPE = 'A'
    THEN
        -----------------------------------------------
        -- 2019.12.23 정리
        -- 확정구간 내에서는 Ship Plan 만 가져온다.
        -- 확정구간 밖에서는 Ship Plan + Ship Req 를 가져온다.
        -- SCP Plan 을 가져오던 것을 Ship Plan 을 가져오도록 변경함 ( 2019.10.07 )
        -----------------------------------------------
        INSERT INTO GT_DMF0045_PLAN
                    (
                      DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                    , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                    )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE                                                  AS FROM_SITE
             , '-'                                                           AS TO_SITE
             , '-'                                                           AS DEPT
             , '/'                                                           AS END_CUSTOMER
             , '/'                                                           AS PROJECT_CODE
             , '/'                                                           AS INCOTERMS
             , '/'                                                           AS FCST_TYPE
             , '-'                                                           AS TR_MODE
             , '-'                                                           AS BOD_ID
             , 'SITE_MOVE'                                                  AS MEASURE
             , A.YYYYMMDD
             , A.QTY
             , 2                                                            AS SEQ
          FROM SSP_ANL_SHIP_CONFIRM A
             , SCP_MST_BOD_N_V B
             , SCM_MST_SITE C
             , SCM_MST_SITE D
         WHERE A.DIVISION_ID   = B.DIVISION_ID
           AND A.BOD_ID        = B.BOD_ID
           AND A.DIVISION_ID   = C.DIVISION_ID
           AND A.TO_SITE       = C.SCM_SITE_ID
           AND C.SITE_TYPE     = 'PLANT'
           AND C.VALID_YN      = 'Y'
           AND A.DIVISION_ID   = D.DIVISION_ID
           AND A.FROM_SITE     = D.SCM_SITE_ID
           AND D.VALID_YN      = 'Y'
           AND C.PLANT_ID     <> D.PLANT_ID
           AND A.CHANGE_TYPE   = 'C'
           AND A.BIZ_TYPE      = V_BIZ_TYPE
           AND A.QTY           > 0
           AND A.DIVISION_ID   = V_DIVISION_ID
           AND A.YYYYMMDD     >= V_FROM_YYYYMMDD
           AND A.YYYYMMDD     <= V_TO_YYYYMMDD
           AND (TRIM(V_SCM_SITE_ID) IS NULL OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_SCM_SITE_ID, ','))))
           AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

        /* 2019.10.7 scp에서 ship_plan 이 컨펌된 수량 + Req 수량이라 req도 추가함 */
        INSERT INTO GT_DMF0045_PLAN
                    (
                      DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                    , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                    )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.PLANT_SITE_ID                                              AS FROM_SITE
             , '-'                                                           AS TO_SITE
             , '-'                                                           AS DEPT
             , '/'                                                           AS END_CUSTOMER
             , '/'                                                           AS PROJECT_CODE
             , '/'                                                           AS INCOTERMS
             , '/'                                                           AS FCST_TYPE
             , '-'                                                           AS TR_MODE
             , '-'                                                           AS BOD_ID
             , 'SITE_MOVE'                                                  AS MEASURE
             , A.YYYYMMDD
             , A.QTY
             , 2                                                            AS SEQ
          FROM DM_PLN_SHIPMENT_REQ A
             , SCM_MST_SITE B
             , SCM_MST_SITE C
         WHERE A.DIVISION_ID      = B.DIVISION_ID
           AND A.PLANT_SITE_ID    = B.SCM_SITE_ID
           AND B.SITE_TYPE        = 'PLANT'
           AND B.OPERATION_GROUP  = V_BIZ_TYPE
           AND B.OSP_YN           = 'N'
           AND B.VALID_YN         = 'Y'
           AND A.DIVISION_ID      = C.DIVISION_ID
           AND A.SCM_SITE_ID      = C.SCM_SITE_ID
           AND C.SITE_TYPE        = 'PLANT'
           AND C.VALID_YN         = 'Y'
           AND A.MEASURE          = 'SHIP_REQ'                                  /* 확정 후 수정할 것 */
           AND A.QTY              > 0
           AND A.DIVISION_ID      = V_DIVISION_ID
           AND A.YYYYMMDD        >= V_FROM_YYYYMMDD
           AND A.YYYYMMDD        <= V_TO_YYYYMMDD
           AND A.YYYYMMDD        >= TO_CHAR(SYSDATE + NVL(B.SHIP_FROZEN, 0), 'YYYYMMDD')     /* 2019.12.23 */
           AND (TRIM(V_SCM_SITE_ID) IS NULL OR A.PLANT_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_SCM_SITE_ID, ','))))
           AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

        -----------------------------------------------
        -- 5. Internal movement
        -----------------------------------------------
        INSERT INTO GT_DMF0045_PLAN
                    (
                      DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                    , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                    )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.SCM_SITE_ID                                                AS FROM_SITE
             , '-'                                                           AS TO_SITE
             , '-'                                                           AS DEPT
             , '/'                                                           AS END_CUSTOMER
             , '/'                                                           AS PROJECT_CODE
             , '/'                                                           AS INCOTERMS
             , '/'                                                           AS FCST_TYPE
             , '-'                                                           AS TR_MODE
             , '-'                                                           AS BOD_ID
             , 'INTN_MOVEMENT'                                              AS MEASURE
             , TO_CHAR(A.PLAN_DATE, 'YYYYMMDD')                             AS YYYYMMDD
             , A.QTY
             , 5                                                            AS SEQ
          FROM SCM_DNM_CELL_INHOUSE_PLAN_SN A
             , SCM_MST_SITE B
         WHERE A.DIVISION_ID      = B.DIVISION_ID
           AND A.PLANT_ID         = B.PLANT_ID
           AND B.SITE_TYPE        = 'PLANT'
           AND B.OSP_YN           = 'N'
           AND B.VALID_YN         = 'Y'
           AND B.OPERATION_GROUP  = V_BIZ_TYPE
           AND A.CATEGORY         = 'MOVING'
           AND A.QTY              > 0
           AND A.DIVISION_ID      = V_DIVISION_ID
           AND A.PLAN_DATE       >= TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD')
           AND A.PLAN_DATE       <= TO_DATE(V_TO_YYYYMMDD, 'YYYYMMDD')
           AND (TRIM(V_PLANT_SITE_ID) IS NULL OR B.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
           AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

    END IF;
    --------------------------------- CELL Biz 끝 -------------------------------------------------------------

    -----------------------------------------------
    -- 2. Ship Plan : SSP(Daily) Sales향 Shipment Plan
    -----------------------------------------------
    INSERT INTO GT_DMF0045_PLAN
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.FROM_SITE
         , A.TO_SITE
         , CASE V_LANG WHEN 'EN' THEN D.DEPT_NAME_EN
                       WHEN 'CN' THEN D.DEPT_NAME_CN
                       ELSE D.DEPT_NAME_KO
           END                                                              AS DEPT
         , C.END_CUSTOMER
         , A.PROJECT_CODE
         , B.SSP_INCOTERMS                                                  AS INCOTERMS
         , A.FCST_TYPE
         , B.TRANSPORT_MODE                                                 AS TR_MODE
         , B.BOD_ID
         , 'SHIP_PLAN'                                                      AS MEASURE
         , A.YYYYMMDD
         , A.QTY
         , 2                                                                AS SEQ
      FROM SSP_ANL_SHIP_CONFIRM A
         , SCP_MST_BOD_N_V B
         , SCM_MST_SITE C
         /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
         , SCM_MST_SITE_ITEM_DEPT_V IB
         /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
         , SCM_MST_SSO_DEPT_INFO D
         , (SELECT DISTINCT DIVISION_ID
                 , ITEM_ID
                 , SCP_OPERATION_GROUP
              FROM SCM_MST_ITEM_SN
             WHERE DIVISION_ID         = V_DIVISION_ID
               AND SCP_OPERATION_GROUP = V_BIZ_TYPE                             /* CELL/PACK 구분 */
               AND ACTIVE_FLAG         = 'Y'
           ) IA
     WHERE A.DIVISION_ID   = B.DIVISION_ID
       AND A.BOD_ID        = B.BOD_ID
       AND A.DIVISION_ID   = C.DIVISION_ID
       AND A.TO_SITE       = C.SCM_SITE_ID
       AND (C.SITE_TYPE = 'SALES' OR (C.SITE_TYPE = 'PLANT' AND C.OSP_YN = 'Y'))
       AND C.VALID_YN      = 'Y'
       /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--       AND C.DEPT_ID       = D.DEPT_ID(+)
       AND A.DIVISION_ID   = IB.DIVISION_ID(+)
       AND A.TO_SITE       = IB.SCM_SITE_ID(+)
       AND A.ITEM_ID       = IB.ITEM_ID(+)
       AND IB.DEPT_ID      = D.DEPT_ID(+)
       /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
       AND A.DIVISION_ID   = IA.DIVISION_ID
       AND A.ITEM_ID       = IA.ITEM_ID
       AND A.TO_SITE NOT IN (SELECT SEGMENT1
                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                              WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
                                AND VALID_YN    = 'Y'
                                AND SEGMENT3    = V_DIVISION_ID)
       AND A.CHANGE_TYPE   = 'C'
       AND A.QTY           > 0
       AND A.DIVISION_ID   = V_DIVISION_ID
       AND A.YYYYMMDD     >= V_FROM_YYYYMMDD
       AND A.YYYYMMDD     <= V_TO_YYYYMMDD
       AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
       AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
     UNION ALL
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.FROM_SITE
         , A.TO_SITE
         , A.DEPT
         , A.END_CUSTOMER
         , A.PROJECT_CODE
         , A.INCOTERMS
         , A.FCST_TYPE
         , A.TR_MODE
         , A.BOD_ID
         , 'SHIP_PLAN'                                                      AS MEASURE
         , A.YYYYMMDD
         , A.QTY
         , 2                                                                AS SEQ
      FROM GT_DMF0045_SHIP_REQ A
         , SCM_MST_SITE B
     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
       AND A.FROM_SITE     = B.SCM_SITE_ID(+)
       AND B.VALID_YN(+)   = 'Y'
       AND A.YYYYMMDD     >= TO_CHAR(SYSDATE + NVL(B.SHIP_FROZEN, 0), 'YYYYMMDD');   /* 확정구간의 다음날짜가 나오므로 >= 로 처리함 */

    -----------------------------------------------
    -- 6. TOTOAL(PLAN)
    -----------------------------------------------
    INSERT INTO GT_DMF0045_PLAN
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT DIVISION_ID
         , ITEM_ID
         , FROM_SITE                                                        AS FROM_SITE
         , '-'                                                               AS TO_SITE
         , '-'                                                               AS DEPT
         , '/'                                                               AS END_CUSTOMER
         , '/'                                                               AS PROJECT_CODE
         , '/'                                                               AS INCOTERMS
         , '/'                                                               AS FCST_TYPE
         , '-'                                                               AS TR_MODE
         , '-'                                                               AS BOD_ID
         , 'TOTAL_PLAN'                                                     AS MEASURE
         , YYYYMMDD
         , SUM(QTY)                                                         AS QTY
         , 6                                                                AS SEQ
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.FROM_SITE                                              AS FROM_SITE
                 , A.YYYYMMDD
                 , SUM(CASE WHEN A.MEASURE IN ('SHIP_PLAN', 'SITE_MOVE', 'INTN_MOVEMENT') THEN A.QTY ELSE 0 END) AS QTY
              FROM GT_DMF0045_PLAN A
             GROUP BY A.DIVISION_ID
                    , A.ITEM_ID
                    , A.YYYYMMDD
                    , A.FROM_SITE
           ) XA
     GROUP BY DIVISION_ID
            , ITEM_ID
            , YYYYMMDD
            , FROM_SITE;

    -----------------------------------------------
    -- 7. TOTOAL(REQ)
    -----------------------------------------------
    INSERT INTO GT_DMF0045_PLAN
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , IA.FROM_SITE                                                     AS FROM_SITE
         , '-'                                                               AS TO_SITE
         , '-'                                                               AS DEPT
         , '/'                                                               AS END_CUSTOMER
         , '/'                                                               AS PROJECT_CODE
         , '/'                                                               AS INCOTERMS
         , '/'                                                               AS FCST_TYPE
         , '-'                                                               AS TR_MODE
         , '-'                                                               AS BOD_ID
         , 'TOTAL_REQ'                                                      AS MEASURE
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                                      AS QTY
         , 7                                                                AS SEQ
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.FROM_SITE                                              AS FROM_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , SUM(CASE WHEN A.MEASURE IN ('SHIP_REQ', 'SITE_MOVE', 'INTN_MOVEMENT') THEN A.QTY ELSE 0 END) AS QTY
              FROM GT_DMF0045_SHIP_REQ A
             GROUP BY A.DIVISION_ID
                    , A.ITEM_ID
                    , A.YYYYMMDD
                    , A.MEASURE
                    , A.FROM_SITE
             UNION ALL
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.FROM_SITE                                              AS FROM_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , SUM(CASE WHEN A.MEASURE IN ('SHIP_REQ', 'SITE_MOVE', 'INTN_MOVEMENT') THEN A.QTY ELSE 0 END) AS QTY
              FROM GT_DMF0045_PLAN A
             GROUP BY A.DIVISION_ID
                    , A.ITEM_ID
                    , A.YYYYMMDD
                    , A.MEASURE
                    , A.FROM_SITE
           ) IA
     GROUP BY IA.DIVISION_ID
            , IA.ITEM_ID
            , IA.YYYYMMDD
            , IA.FROM_SITE;

    IF V_BIZ_TYPE = 'P'
    THEN
        IF V_DIVISION_ID = '81'
        THEN
            -----------------------------------------------
            -- 6. PACK_FP
            -----------------------------------------------
            INSERT INTO GT_DMF0045_PLAN
                        (
                          DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                        , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                        )
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID                                            AS FROM_SITE
                 , '-'                                                       AS TO_SITE
                 , '-'                                                       AS DEPT
                 , '/'                                                       AS END_CUSTOMER
                 , '/'                                                       AS PROJECT_CODE
                 , '/'                                                       AS INCOTERMS
                 , '/'                                                       AS FCST_TYPE
                 , '-'                                                       AS TR_MODE
                 , '-'                                                       AS BOD_ID
                 , 'PACK_FP'                                                AS MEASURE
                 , A.PLAN_DATE                                              AS YYYYMMDD
                 , A.PLAN_QTY                                               AS QTY
                 , 8                                                        AS SEQ
              FROM SSP_DNM_FP_PLAN_FROZEN A
                 , SCM_MST_SITE B
             WHERE A.DIVISION_ID      = B.DIVISION_ID
               AND A.SCM_SITE_ID      = B.SCM_SITE_ID
               AND B.SITE_TYPE        = 'PLANT'
               AND B.OSP_YN           = 'N'
               AND B.VALID_YN         = 'Y'
               AND A.OPERATION_ID    IN (SELECT B.SEGMENT4
                                           FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                                              , SCM_ADM_LOOKUP_MASTER_DETAIL B
                                          WHERE A.SEGMENT1    = B.SEGMENT1
                                            AND A.LOOKUP_TYPE = 'LOCATION_GROUP'
                                            AND A.SEGMENT3    = 'P'                 /* PACK 공정 */
                                            AND A.SEGMENT4    = 'Y'                 /* CAPA 공정 여부 */
                                            AND A.SEGMENT5    = 'Y'                 /* LINE 별 CAPA 적용 공정 */
                                            AND A.VALID_YN    = 'Y'
                                            AND B.LOOKUP_TYPE = 'LOCATION_GROUP_ROUTE'
                                            AND B.VALID_YN    = 'Y'
                                            AND B.SEGMENT3    = 'Y')                /* CAPA 세부 공정 여부 */
               AND A.DIVISION_ID      = V_DIVISION_ID
               AND A.PLAN_DATE       >= V_FROM_YYYYMMDD
               AND A.PLAN_DATE       <= V_TO_YYYYMMDD
               AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
             UNION ALL
            /* A/S PLANT ETA 기준 */
            SELECT A.DIVISION_ID                                            AS DIVISION_ID
                 , A.ITEM_ID                                                AS ITEM_ID
                 , A.TO_SITE                                                AS FROM_SITE
                 , '-'                                                       AS TO_SITE
                 , '-'                                                       AS DEPT
                 , '/'                                                       AS END_CUSTOMER
                 , '/'                                                       AS PROJECT_CODE
                 , '/'                                                       AS INCOTERMS
                 , '/'                                                       AS FCST_TYPE
                 , '-'                                                       AS TR_MODE
                 , '-'                                                       AS BOD_ID
                 , 'PACK_FP'                                                AS MEASURE
                 , A.ETA_DATE                                               AS YYYYMMDD
                 , A.QTY                                                    AS QTY
                 , 8                                                        AS SEQ
              FROM SSP_ANL_SHIP_CONFIRM A
                 , SCM_MST_SITE B
             WHERE A.DIVISION_ID      = B.DIVISION_ID
               AND A.TO_SITE          = B.SCM_SITE_ID
               AND B.OPERATION_GROUP  = 'W'
               AND B.SITE_TYPE        = 'PLANT'
               AND B.VALID_YN         = 'Y'
               AND A.QTY              > 0
               AND A.DIVISION_ID      = V_DIVISION_ID
               AND A.ETA_DATE        >= V_FROM_YYYYMMDD
               AND A.ETA_DATE        <= V_TO_YYYYMMDD
               AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.TO_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

        ELSIF V_DIVISION_ID = '82'
        THEN
            /* 해당 쿼리는 최근 2주간 실행된 SCP Plan중 가장 최신의 Plan 수량을 가져오는 쿼리로 보입니다. (Pack 대상) */
            INSERT INTO GT_DMF0045_PLAN
                        (
                          DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                        , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                        )
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID                                            AS FROM_SITE
                 , '-'                                                       AS TO_SITE
                 , '-'                                                       AS DEPT
                 , '/'                                                       AS END_CUSTOMER
                 , '/'                                                       AS PROJECT_CODE
                 , '/'                                                       AS INCOTERMS
                 , '/'                                                       AS FCST_TYPE
                 , '-'                                                       AS TR_MODE
                 , '-'                                                       AS BOD_ID
                 , 'PACK_FP'                                                AS MEASURE      /* SCP PROD Plan */
                 , A.YYYYMMDD
                 , A.QTY
                 , 8                                                        AS SEQ
              FROM SCP_ANL_PRODUCTION_PLAN A
                 , SCM_MST_SITE B
                 , (SELECT DIVISION_ID
                         , PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , PLAN_SEQ
                         , PLAN_ID
                         , MODELING_ID
                         , ROW_NUMBER() OVER (ORDER BY PLAN_START_YYYYMMDD DESC, PLAN_SEQ DESC) AS ROW_NUM
                      FROM (SELECT DIVISION_ID
                                 , PLAN_START_YYYYMMDD
                                 , PLAN_TYPE
                                 , PLAN_SEQ
                                 , PLAN_ID
                                 , MODELING_ID
                              FROM SCP_PLAN_VERSION_V
                             WHERE DIVISION_ID          = V_DIVISION_ID
                               AND PLAN_CYCLE           = 'WEEKLY'
                               AND PLAN_TYPE            = 'FN'
                               AND PLAN_START_YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 14, 'YYYYMMDD')
                           ) IA
                   ) SA
             WHERE A.DIVISION_ID         = SA.DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = SA.PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = SA.PLAN_TYPE
               AND A.SEQ                 = SA.PLAN_SEQ
               AND SA.ROW_NUM            = 1
               AND A.DIVISION_ID         = B.DIVISION_ID
               AND A.SCM_SITE_ID         = B.SCM_SITE_ID
               AND B.SITE_TYPE           = 'PLANT'
               AND B.OPERATION_GROUP     = 'P'
               AND B.VALID_YN            = 'Y'
               AND A.MEASURE             = 'PROD_PLAN_AMEND'
               AND A.QTY                 > 0
               AND A.DIVISION_ID         = V_DIVISION_ID
               AND A.YYYYMMDD           >= V_FROM_YYYYMMDD
               AND A.YYYYMMDD           <= V_TO_YYYYMMDD
               AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
             UNION ALL
            /* A/S PLANT ETA 기준 */
            SELECT A.DIVISION_ID                                            AS DIVISION_ID
                 , A.ITEM_ID                                                AS ITEM_ID
                 , A.TO_SITE                                                AS FROM_SITE
                 , '-'                                                       AS TO_SITE
                 , '-'                                                       AS DEPT
                 , '/'                                                       AS END_CUSTOMER
                 , '/'                                                       AS PROJECT_CODE
                 , '/'                                                       AS INCOTERMS
                 , '/'                                                       AS FCST_TYPE
                 , '-'                                                       AS TR_MODE
                 , '-'                                                       AS BOD_ID
                 , 'PACK_FP'                                                AS MEASURE
                 , A.ETA_DATE                                               AS YYYYMMDD
                 , A.QTY                                                    AS QTY
                 , 8                                                        AS SEQ
              FROM SSP_ANL_SHIP_CONFIRM A
                 , SCM_MST_SITE B
             WHERE A.DIVISION_ID      = B.DIVISION_ID
               AND A.TO_SITE          = B.SCM_SITE_ID
               AND B.OPERATION_GROUP  = 'W'
               AND B.SITE_TYPE        = 'PLANT'
               AND B.VALID_YN         = 'Y'
               AND A.QTY              > 0
               AND A.DIVISION_ID      = V_DIVISION_ID
               AND A.ETA_DATE        >= V_FROM_YYYYMMDD
               AND A.ETA_DATE        <= V_TO_YYYYMMDD
               AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.TO_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))));

        END IF;
    END IF;

    IF V_BIZ_TYPE = 'A'
    THEN
        -----------------------------------------------
        -- 7. Inspection plan : FP 특성계획
        -----------------------------------------------
        INSERT INTO GT_DMF0045_PLAN
                    (
                      DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                    , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                    )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID                                                AS FROM_SITE
             , '-'                                                           AS TO_SITE
             , '-'                                                           AS DEPT
             , '/'                                                           AS END_CUSTOMER
             , '/'                                                           AS PROJECT_CODE
             , '/'                                                           AS INCOTERMS
             , '/'                                                           AS FCST_TYPE
             , '-'                                                           AS TR_MODE
             , '-'                                                           AS BOD_ID
             , 'INSP_PLAN'                                                  AS MEASURE
             , A.PLAN_DATE                                                  AS YYYYMMDD
             , A.PLAN_QTY                                                   AS QTY
             , 8                                                            AS SEQ
          FROM SSP_DNM_FP_PLAN_FROZEN A
             , SCM_MST_SITE B
         WHERE A.DIVISION_ID      = B.DIVISION_ID
           AND A.SCM_SITE_ID      = B.SCM_SITE_ID
           AND B.SITE_TYPE        = 'PLANT'
           AND B.OSP_YN           = 'N'
           AND B.VALID_YN         = 'Y'
           /* (참고) division_id <> '40' 일때는 'F6000' 데이터만 존재 */
           AND A.OPERATION_ID    IN (SELECT SEGMENT1
                                       FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                      WHERE LOOKUP_TYPE = 'OPERATION_CHAR'
                                        AND VALID_YN    = 'Y')
           AND (EXISTS (SELECT 1
                          FROM GT_DMF0045_SHIP_REQ SA
                         WHERE SA.DIVISION_ID = A.DIVISION_ID
                           AND SA.ITEM_ID     = A.ITEM_ID)
             OR EXISTS (SELECT 1
                          FROM GT_DMF0045_PLAN SA
                         WHERE SA.DIVISION_ID = A.DIVISION_ID
                           AND SA.ITEM_ID     = A.ITEM_ID))
           AND A.DIVISION_ID      = V_DIVISION_ID
           AND A.PLAN_DATE       >= V_FROM_YYYYMMDD
           AND A.PLAN_DATE       <= V_TO_YYYYMMDD
           AND (TRIM(V_PLANT_SITE_ID) IS NULL OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))));

    END IF;

    /* ROW DATA 생성 */
    INSERT INTO GT_DMF0045_SHIP_ROW
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , MAX(NVL(XA.NICK_NAME, ''))                                       AS NICK_NAME
         , IA.FROM_SITE
         , IA.TO_SITE
         , IA.DEPT
         , IA.END_CUSTOMER
         , IA.PROJECT_CODE
         , IA.INCOTERMS
         , IA.FCST_TYPE
         , IA.TR_MODE
         , NULL                                                             AS BOD_ID
         , IA.MEASURE
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                                      AS QTY
         , IA.SEQ
      FROM (/* 1.RTF, 2.SHIP_PLAN, 4.TOTOAL(PLAN), 5.TOTOAL(REQ), 6.PACK FP */
            SELECT DIVISION_ID
                 , ITEM_ID
                 , FROM_SITE
                 , TO_SITE
                 , DEPT
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , INCOTERMS
                 , FCST_TYPE
                 , TR_MODE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , SEQ
              FROM GT_DMF0045_PLAN
             UNION ALL
            /* 3.SHIP REQ 추가 */
            SELECT DIVISION_ID
                 , ITEM_ID
                 , FROM_SITE
                 , TO_SITE
                 , DEPT
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , INCOTERMS
                 , FCST_TYPE
                 , TR_MODE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , 3                                                        AS SEQ
              FROM GT_DMF0045_SHIP_REQ
           ) IA
         , (SELECT DIVISION_ID
                 , ITEM_ID
                 , MAX(NVL(NICK_NAME, ''))                                  AS NICK_NAME
              FROM SCM_MST_ITEM_SN
             WHERE NICK_NAME  IS NOT NULL
               AND DIVISION_ID = V_DIVISION_ID
               AND ACTIVE_FLAG = 'Y'
             GROUP BY DIVISION_ID
                    , ITEM_ID
           ) XA
     WHERE IA.ITEM_ID     = XA.ITEM_ID(+)
       AND IA.DIVISION_ID = XA.DIVISION_ID(+)
     GROUP BY IA.DIVISION_ID
            , IA.ITEM_ID
            , IA.FROM_SITE
            , IA.TO_SITE
            , IA.DEPT
            , IA.END_CUSTOMER
            , IA.PROJECT_CODE
            , IA.INCOTERMS
            , IA.FCST_TYPE
            , IA.TR_MODE
            , IA.MEASURE
            , IA.YYYYMMDD
            , IA.SEQ;

    -----------------------------------------------
    -- 8. W/H BOH(Plan) : Cell Plant의 Cell 재고
    --                    일자별 BOH 계산  : BOH(D+1) = BOH(D) - Ship Req(D) - Customer Req(D) - Internal movement(D) + Inspection Plan(D)
    -----------------------------------------------
    SELECT TO_CHAR(MAX(CUTOFF_DATE), 'YYYYMMDD')
      INTO V_CUTOFF_DATE
      FROM SSP_DNM_STOCK_C
     WHERE DIVISION_ID  = V_DIVISION_ID
       AND STOCK_TYPE  IN ('INVENTORY', 'WIP')
       AND CUTOFF_DATE  > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')                 /* 현재일 - 3 */
       AND CUTOFF_DATE <= TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD');                 /* 변수 : 현재일 */

    INSERT INTO GT_DMF0045_STOCK
                (
                  DIVISION_ID, SCM_SITE_ID, STORAGE_ID, ITEM_ID, SSP_QTY, YYYYMMDD
                )
    SELECT DIVISION_ID
         , SCM_SITE_ID
         , STORAGE_ID
         , ITEM_ID
         , SSP_QTY
         , TO_CHAR(CUTOFF_DATE, 'YYYYMMDD')                                 AS YYYYMMDD
      FROM SSP_DNM_STOCK_C
     WHERE DIVISION_ID  = V_DIVISION_ID
       AND STOCK_TYPE  IN ('INVENTORY', 'WIP')
       AND CUTOFF_DATE  = TO_DATE(V_CUTOFF_DATE, 'YYYYMMDD');

    /* 사업부별 기초재고 */
    INSERT INTO GT_DMF0045_BOH
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, YYYYMMDD, QTY
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , IA.FROM_SITE
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                                      AS QTY
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID                                            AS FROM_SITE
                 , V_FROM_YYYYMMDD                                          AS YYYYMMDD
                 , A.SSP_QTY                                                AS QTY      /* SSP용 */
              FROM GT_DMF0045_STOCK A
                 , SCM_MST_SITE B
                 , SCP_MST_FINAL_ITEM C
                 , (SELECT DISTINCT A.STORAGE_ID
                         , A.LOCATION_CODE
                         , A.SCM_SITE_ID
                         , A.DIVISION_ID
                      FROM SCM_MST_LOCATION A
                         , SCM_MST_SITE B
                         , GT_DMF0045_LOC C
                     WHERE A.SCM_SITE_ID     = B.SCM_SITE_ID
                       AND B.DIVISION_ID     = V_DIVISION_ID
                       AND B.VALID_YN        = 'Y'
                       AND B.OPERATION_GROUP = V_BIZ_TYPE                       /* Cell Plant Site */
                       AND A.DIVISION_ID     = C.DIVISION_ID
                       AND A.LOCATION_CODE   = C.LOC_CODE
                       AND C.SHT_NAME        = V_SHEET_NAME
                       AND A.DIVISION_ID     = V_DIVISION_ID
                       AND A.VALID_YN        = 'Y'
                       AND A.STORAGE_ID     IS NOT NULL
                       AND A.STORAGE_ID     <> ''
                     UNION ALL
                    SELECT DISTINCT A.SEGMENT4                              AS STORAGE_ID
                         , 'AS'                                             AS LOCATION_CODE
                         , A.SEGMENT2                                       AS SCM_SITE_ID
                         , A.SEGMENT1                                       AS DIVISION_ID
                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                         , SCM_MST_SITE B
                     WHERE A.SEGMENT1    = B.DIVISION_ID
                       AND A.SEGMENT2    = B.SCM_SITE_ID
                       AND A.SEGMENT3    = B.PLANT_ID
                       AND A.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                       AND A.VALID_YN    = 'Y'
                       AND B.VALID_YN    = 'Y'
                       AND B.SITE_TYPE   = 'PLANT'
                       AND A.SEGMENT1    = V_DIVISION_ID
                   ) XA                                                         /* 셀 storage_id 별 사용대상 조회 */
             WHERE A.DIVISION_ID      = B.DIVISION_ID
               AND A.SCM_SITE_ID      = B.SCM_SITE_ID
               AND B.DIVISION_ID      = V_DIVISION_ID
               AND B.SITE_TYPE        = 'PLANT'
               AND B.OPERATION_GROUP IN (V_BIZ_TYPE, 'W')
               AND B.VALID_YN         = 'Y'
               AND A.DIVISION_ID      = XA.DIVISION_ID
               AND A.SCM_SITE_ID      = XA.SCM_SITE_ID
               AND A.STORAGE_ID       = XA.STORAGE_ID
               AND A.DIVISION_ID      = C.DIVISION_ID
               AND A.ITEM_ID          = C.ITEM_ID
               AND C.OPERATION_GROUP IN (V_BIZ_TYPE, 'W')
               AND V_DIVISION_ID      = '81'
               AND (TRIM(V_SCM_SITE_ID) IS NULL OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_SCM_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
           ) IA
     WHERE V_DIVISION_ID = '81'
     GROUP BY IA.DIVISION_ID
            , IA.ITEM_ID
            , IA.FROM_SITE
            , IA.YYYYMMDD
     /* [CSR 요청번호:C20200121-000352] */
     UNION ALL
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , IA.FROM_SITE
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                                      AS QTY
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID                                            AS FROM_SITE
                 , V_FROM_YYYYMMDD                                          AS YYYYMMDD
                 , A.SSP_QTY                                                AS QTY      /* SSP용 */
              FROM SSP_DNM_ESS_PACKER_STOCK_V A
                 , SCM_MST_SITE B
                 , SCP_MST_FINAL_ITEM C
                 , (SELECT DIVISION_ID
                         , SITE_ID
                         , MAX(CUTOFF_DATE)                                 AS MAX_CUTOFF_DATE
                      FROM SSP_DNM_ESS_PACKER_STOCK_V
                     WHERE DIVISION_ID  = V_DIVISION_ID
                       AND CUTOFF_DATE  > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')     /* 현재일 - 3 */
                       AND CUTOFF_DATE <= TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD')      /* 변수 : 현재일 */
                     GROUP BY DIVISION_ID
                            , SITE_ID
                   ) XA
             WHERE A.DIVISION_ID      = XA.DIVISION_ID
               AND A.SITE_ID          = XA.SITE_ID
               AND A.CUTOFF_DATE      = XA.MAX_CUTOFF_DATE
               AND A.CUTOFF_DATE      > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')
               AND A.DIVISION_ID      = B.DIVISION_ID
               AND A.SCM_SITE_ID      = B.SCM_SITE_ID
               AND B.DIVISION_ID      = V_DIVISION_ID
               AND B.SITE_TYPE        = 'PLANT'
               AND B.OPERATION_GROUP IN (V_BIZ_TYPE, 'W')
               AND B.VALID_YN         = 'Y'
               AND A.DIVISION_ID      = C.DIVISION_ID
               AND A.ITEM_ID          = C.ITEM_ID
               AND C.OPERATION_GROUP IN (V_BIZ_TYPE, 'W')
               AND V_DIVISION_ID      = '82'
               AND (TRIM(V_SCM_SITE_ID) IS NULL OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_SCM_SITE_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
           ) IA
     WHERE V_DIVISION_ID = '82'
     GROUP BY IA.DIVISION_ID
            , IA.ITEM_ID
            , IA.FROM_SITE
            , IA.YYYYMMDD;

    INSERT INTO GT_DMF0045_SHIP_ROW
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY, SEQ
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.NICK_NAME
         , A.FROM_SITE                                                      AS FROM_SITE
         , '-'                                                               AS TO_SITE
         , '-'                                                               AS DEPT
         , '/'                                                               AS END_CUSTOMER
         , '/'                                                               AS PROJECT_CODE
         , '/'                                                               AS INCOTERMS
         , '/'                                                               AS FCST_TYPE
         , '-'                                                               AS TR_MODE
         , '-'                                                               AS BOD_ID
         , 'WH_BOH_PLAN'                                                    AS MEASURE
         , A.YYYYMMDD
         , SUM(CASE WHEN C.MEASURE  = 'TOTAL_PLAN' AND C.YYYYMMDD > V_FROM_YYYYMMDD THEN -1 * NVL(C.QTY, 0)
                    WHEN C.MEASURE <> 'TOTAL_PLAN' AND C.YYYYMMDD < A.YYYYMMDD      THEN NVL(C.QTY, 0)
                    ELSE 0
               END) + NVL(B.QTY, 0)                                         AS QTY
         , 9                                                                AS SEQ
      FROM (SELECT DISTINCT XA.DIVISION_ID
                 , XA.ITEM_ID
                 , XA.NICK_NAME
                 , XA.FROM_SITE
                 , A.BASIS_YYYYMMDD                                         AS YYYYMMDD
              FROM SCM_SYS_CALENDAR_M A
                 , (SELECT DISTINCT DIVISION_ID
                         , ITEM_ID
                         , NICK_NAME
                         , FROM_SITE
                      FROM GT_DMF0045_SHIP_ROW
                   ) XA
             WHERE A.BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= V_TO_YYYYMMDD
           ) A
         , GT_DMF0045_BOH B
         , GT_DMF0045_PLAN C
     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
       AND A.ITEM_ID       = B.ITEM_ID(+)
       AND A.FROM_SITE     = B.FROM_SITE(+)
       AND A.DIVISION_ID   = C.DIVISION_ID(+)
       AND A.FROM_SITE     = C.FROM_SITE(+)
       AND A.ITEM_ID       = C.ITEM_ID(+)
       AND A.YYYYMMDD     >= C.YYYYMMDD(+)
       AND C.MEASURE(+)   IN ('TOTAL_PLAN', 'PACK_FP', 'INSP_PLAN')
     GROUP BY A.DIVISION_ID
            , A.ITEM_ID
            , A.NICK_NAME
            , A.YYYYMMDD
            , B.QTY
            , A.FROM_SITE
     UNION ALL
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.NICK_NAME
         , A.FROM_SITE                                                      AS FROM_SITE
         , '-'                                                               AS TO_SITE
         , '-'                                                               AS DEPT
         , '/'                                                               AS END_CUSTOMER
         , '/'                                                               AS PROJECT_CODE
         , '/'                                                               AS INCOTERMS
         , '/'                                                               AS FCST_TYPE
         , '-'                                                               AS TR_MODE
         , '-'                                                               AS BOD_ID
         , 'WH_BOH_REQ'                                                     AS MEASURE
         , A.YYYYMMDD
         , SUM(CASE WHEN C.MEASURE  = 'TOTAL_REQ' AND C.YYYYMMDD > V_FROM_YYYYMMDD THEN -1 * NVL(C.QTY, 0)
                    WHEN C.MEASURE <> 'TOTAL_REQ' AND C.YYYYMMDD < A.YYYYMMDD      THEN NVL(C.QTY, 0)
                    ELSE 0
               END) + NVL(B.QTY, 0)                                         AS QTY
         , 9                                                                AS SEQ
      FROM (SELECT DISTINCT XA.DIVISION_ID
                 , XA.ITEM_ID
                 , XA.NICK_NAME
                 , XA.FROM_SITE
                 , A.BASIS_YYYYMMDD                                         AS YYYYMMDD
              FROM SCM_SYS_CALENDAR_M A
                 , (SELECT DISTINCT DIVISION_ID
                         , ITEM_ID
                         , NICK_NAME
                         , FROM_SITE
                      FROM GT_DMF0045_SHIP_ROW
                   ) XA
             WHERE A.BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= V_TO_YYYYMMDD
           ) A
         , GT_DMF0045_BOH B
         , GT_DMF0045_PLAN C
     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
       AND A.ITEM_ID       = B.ITEM_ID(+)
       AND A.FROM_SITE     = B.FROM_SITE(+)
       AND A.DIVISION_ID   = C.DIVISION_ID(+)
       AND A.FROM_SITE     = C.FROM_SITE(+)
       AND A.ITEM_ID       = C.ITEM_ID(+)
       AND A.YYYYMMDD     >= C.YYYYMMDD(+)
       AND C.MEASURE(+)   IN ('TOTAL_REQ', 'PACK_FP', 'INSP_PLAN')
     GROUP BY A.DIVISION_ID
            , A.ITEM_ID
            , A.NICK_NAME
            , A.YYYYMMDD
            , B.QTY
            , A.FROM_SITE;

    /* 'SCP_SHIP_PLAN', 'SHIP_REQ', 'SHIP_PLAN' 메저 없는것 제거 */
    DELETE FROM GT_DMF0045_SHIP_ROW A
     WHERE NOT EXISTS (SELECT 1
                         FROM GT_DMF0045_SHIP_ROW XA
                        WHERE XA.MEASURE IN ('SCP_SHIP_PLAN', 'SHIP_REQ', 'SHIP_PLAN')
                          AND A.DIVISION_ID = XA.DIVISION_ID
                          AND A.FROM_SITE   = XA.FROM_SITE
                          AND A.ITEM_ID     = XA.ITEM_ID);

    -----------------------------------------------
    -- 10. Requestor
    -----------------------------------------------
    INSERT INTO GT_DMF0045_REQUESTOR
                (
                  DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, FCST_TYPE, MEASURE, CREATED_BY
                )
    SELECT DIVISION_ID
         , ITEM_ID
         , FROM_SITE
         , TO_SITE
         , TR_MODE
         , INCOTERMS
         , FCST_TYPE
         , MEASURE
         , CREATED_BY
      FROM (SELECT DIVISION_ID
                 , ITEM_ID
                 , FROM_SITE
                 , TO_SITE
                 , TR_MODE
                 , INCOTERMS
                 , FCST_TYPE
                 , MEASURE
                 , CREATED_BY
                 , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, FCST_TYPE, MEASURE
                                          ORDER BY RN)                      AS RN2
              FROM GT_DMF0045_SHIP_REQ
           ) XA
     WHERE XA.RN2 = 1;

    /* PIVOT용 Data정리 */
    INSERT INTO GT_DMF0045_PIVOT
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ
                )
    SELECT A.DIVISION_ID
         , A.ITEM_ID
         , A.NICK_NAME
         , A.FROM_SITE
         , A.TO_SITE
         , A.DEPT
         , A.END_CUSTOMER
         , A.PROJECT_CODE
         , A.INCOTERMS
         , A.FCST_TYPE
         , A.TR_MODE
         , A.BOD_ID
         , A.MEASURE
         , 'D_' || A.YYYYMMDD                                               AS YYYYMMDD
         , B.BASIS_YYYYMM                                                   AS YYYYMM
         , SUBSTR(B.BASIS_YYYYMM, -4) || B.ISO_WEEK                         AS ISO_WEEK
         , A.QTY
         , A.SEQ
      FROM GT_DMF0045_SHIP_ROW A
         , SCM_SYS_CALENDAR_M B
     WHERE A.YYYYMMDD = B.BASIS_YYYYMMDD
    /* 20210304 KIMYONGHO 임시조치 */
    /* 조회 FILTER 조건 부정확으로 PIVOT 직전 FILTER 다시 설정 */
       AND A.ITEM_ID IN (SELECT DISTINCT XA.ITEM_ID
                           FROM GT_DMF0045_SHIP_ROW XA
                              , SCM_MST_SITE SA
                              /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
                              , SCM_MST_SITE_ITEM_DEPT_V XB
                              /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
                          WHERE XA.TO_SITE     = SA.SCM_SITE_ID
                            AND XA.DIVISION_ID = SA.DIVISION_ID
                            /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
                            AND XA.DIVISION_ID = XB.DIVISION_ID(+)
                            AND XA.TO_SITE     = XB.SCM_SITE_ID(+)
                            AND XA.ITEM_ID     = XB.ITEM_ID(+)
                            /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
                            AND XA.MEASURE    IN ('SCP_SHIP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
                            /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--                            AND (TRIM(V_TEAM_ID) IS NULL OR SA.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
                            AND (TRIM(V_TEAM_ID) IS NULL OR XB.DEPT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_TEAM_ID, ','))))
                            /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
                            AND (TRIM(V_CUSTOMER) IS NULL OR XA.END_CUSTOMER IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_CUSTOMER, ','))))
                            AND (TRIM(V_ITEM_ID) IS NULL OR XA.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_ITEM_ID, ','))))
                            AND (TRIM(V_SCM_SITE_ID) IS NULL OR XA.TO_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_SCM_SITE_ID, ','))))
                            AND (TRIM(V_PLANT_SITE_ID) IS NULL OR XA.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE_ID, ','))))
                            AND (TRIM(V_PROJECT_CODE) IS NULL OR XA.PROJECT_CODE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PROJECT_CODE, ','))))
                            AND XA.DIVISION_ID = V_DIVISION_ID);

    ------ 빠져있는 메저 추가 ------
    /* SHIP_REQ, RTF, RTF_SCP 중 하나의 MEASURE 라도 있으면 아래와 같이 모든 메저를 채워준다.  */
    /* 개별은 TO_SITE 까지를 개별로 보고, 공통은 FROM_SITE 까지를 공통으로 본다.               */
    /* 공통/개별 : SHIP_REQ, RTF, RTF_SCP, SHIP_PLAN                                            */
    /* PACK/합계 : PACK_FP                                                                      */
    /* CELL/합계 : SITE_MOVE, INTN_MOVEMENT, INSP_PLAN                                          */
    /* 공통/합계 : TOTAL_PLAN, TOTAL_REQ, WH_BOH_PLAN, WH_BOH_REQ                               */

    /* 개별 처리 -- 개별로 들어가야 할 MEASURE 중에 없는 것이 있으면 추가한다. */
    INSERT INTO GT_DMF0045_PIVOT
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , '/'
         , IA.FROM_SITE
         , IA.TO_SITE
         , IA.DEPT
         , IA.END_CUSTOMER
         , IA.PROJECT_CODE
         , IA.INCOTERMS
         , IA.FCST_TYPE
         , IA.TR_MODE
         , B.MEASURE
         , IA.YYYYMMDD
         , IA.YYYYMM
         , IA.ISO_WEEK
         , 0
         , 0
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.DEPT
                 , A.END_CUSTOMER
                 , A.PROJECT_CODE
                 , A.INCOTERMS
                 , A.FCST_TYPE
                 , A.TR_MODE
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.ISO_WEEK
              FROM GT_DMF0045_PIVOT A
             WHERE NVL(A.FROM_SITE, '/') <> '/'
             GROUP BY A.DIVISION_ID
                    , A.ITEM_ID
                    , A.FROM_SITE
                    , A.TO_SITE
                    , A.DEPT
                    , A.END_CUSTOMER
                    , A.PROJECT_CODE
                    , A.INCOTERMS
                    , A.FCST_TYPE
                    , A.TR_MODE
                    , A.YYYYMMDD
                    , A.YYYYMM
                    , A.ISO_WEEK
           ) IA
         , GT_DMF0045_MEASURE B
     WHERE B.BIZ_TYPE      = V_BIZ_TYPE
       AND B.SUM_CHECK     = 'N'
       AND NVL(IA.TO_SITE, '/') <> '/'
       AND NOT EXISTS (SELECT 1
                         FROM GT_DMF0045_PIVOT SA
                        WHERE IA.DIVISION_ID          = SA.DIVISION_ID
                          AND IA.ITEM_ID              = SA.ITEM_ID
                          AND IA.FROM_SITE            = SA.FROM_SITE
                          AND IA.TO_SITE              = SA.TO_SITE
                          AND B.MEASURE               = SA.MEASURE
                          AND IA.YYYYMMDD             = SA.YYYYMMDD
                          AND IA.YYYYMM               = SA.YYYYMM
                          AND IA.ISO_WEEK             = SA.ISO_WEEK
                          AND NVL(IA.DEPT, '-')          = NVL(SA.DEPT, '-')
                          AND NVL(IA.END_CUSTOMER, '/')  = NVL(SA.END_CUSTOMER, '/')
                          AND NVL(IA.PROJECT_CODE, '/')  = NVL(SA.PROJECT_CODE, '/')
                          AND NVL(IA.INCOTERMS, '/')     = NVL(SA.INCOTERMS, '/')
                          AND NVL(IA.FCST_TYPE, '/')     = NVL(SA.FCST_TYPE, '/')
                          AND NVL(IA.TR_MODE, '-')       = NVL(SA.TR_MODE, '-'));

    /* [CSR 요청번호:C20200121-000352]                                       */
    /* 20200618  수정 KIMYONGHO                                              */
    /* 81 사업부 조회 시 SCP SHIP PLAN Measure 미표시 문제로 변경 (82 조건 제외) */

    /* FROM Site 가 없는 건들은 지운다. */
    DELETE FROM GT_DMF0045_PIVOT
     WHERE NVL(FROM_SITE, '/') = '/';

    INSERT INTO GT_DMF0045_PIVOT
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , '/'
         , IA.FROM_SITE
         , IA.TO_SITE
         , IA.DEPT
         , IA.END_CUSTOMER
         , IA.PROJECT_CODE
         , IA.INCOTERMS
         , IA.FCST_TYPE
         , IA.TR_MODE
         , B.MEASURE
         , IA.YYYYMMDD
         , IA.YYYYMM
         , IA.ISO_WEEK
         , 0
         , 0
      FROM (SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.DEPT
                 , A.END_CUSTOMER
                 , A.PROJECT_CODE
                 , A.INCOTERMS
                 , A.FCST_TYPE
                 , A.TR_MODE
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.ISO_WEEK
              FROM GT_DMF0045_PIVOT A
             WHERE NVL(A.FROM_SITE, '/') <> '/'
             GROUP BY A.DIVISION_ID
                    , A.ITEM_ID
                    , A.FROM_SITE
                    , A.TO_SITE
                    , A.DEPT
                    , A.END_CUSTOMER
                    , A.PROJECT_CODE
                    , A.INCOTERMS
                    , A.FCST_TYPE
                    , A.TR_MODE
                    , A.YYYYMMDD
                    , A.YYYYMM
                    , A.ISO_WEEK
           ) IA
         , GT_DMF0045_MEASURE B
     WHERE B.BIZ_TYPE      = V_BIZ_TYPE
       AND B.SUM_CHECK     = 'A'
       AND NVL(IA.TO_SITE, '/') <> '/'
       AND NOT EXISTS (SELECT 1
                         FROM GT_DMF0045_PIVOT SA
                        WHERE IA.DIVISION_ID          = SA.DIVISION_ID
                          AND IA.ITEM_ID              = SA.ITEM_ID
                          AND IA.FROM_SITE            = SA.FROM_SITE
                          AND IA.TO_SITE              = SA.TO_SITE
                          AND B.MEASURE               = SA.MEASURE
                          AND IA.YYYYMMDD             = SA.YYYYMMDD
                          AND IA.YYYYMM               = SA.YYYYMM
                          AND IA.ISO_WEEK             = SA.ISO_WEEK
                          AND NVL(IA.DEPT, '-')          = NVL(SA.DEPT, '-')
                          AND NVL(IA.END_CUSTOMER, '/')  = NVL(SA.END_CUSTOMER, '/')
                          AND NVL(IA.INCOTERMS, '/')     = NVL(SA.INCOTERMS, '/')
                          AND NVL(IA.TR_MODE, '-')       = NVL(SA.TR_MODE, '-'));

    /* 공통 처리 -- 공통으로 들어가야 할 MEASURE 중에 없는 것이 있으면 추가한다. */
    INSERT INTO GT_DMF0045_PIVOT
                (
                  DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, DEPT, END_CUSTOMER, PROJECT_CODE
                , INCOTERMS, FCST_TYPE, TR_MODE, BOD_ID, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ
                )
    SELECT IA.DIVISION_ID
         , IA.ITEM_ID
         , '/'
         , IA.FROM_SITE
         , '-'
         , '-'
         , '/'
         , '/'
         , '/'
         , '/'
         , '-'
         , '-'
         , A.MEASURE
         , IA.YYYYMMDD
         , IA.YYYYMM
         , IA.ISO_WEEK
         , 0
         , 0
      FROM GT_DMF0045_MEASURE A
         , (SELECT XA.DIVISION_ID
                 , XA.ITEM_ID
                 , XA.FROM_SITE
                 , XA.YYYYMMDD
                 , XA.YYYYMM
                 , XA.ISO_WEEK
              FROM GT_DMF0045_PIVOT XA
             GROUP BY XA.DIVISION_ID
                    , XA.ITEM_ID
                    , XA.FROM_SITE
                    , XA.YYYYMMDD
                    , XA.YYYYMM
                    , XA.ISO_WEEK
           ) IA
     WHERE A.BIZ_TYPE  = V_BIZ_TYPE
       AND A.SUM_CHECK = 'Y'
       AND NOT EXISTS (SELECT 1
                         FROM GT_DMF0045_PIVOT SA
                        WHERE IA.DIVISION_ID = SA.DIVISION_ID
                          AND IA.ITEM_ID     = SA.ITEM_ID
                          AND IA.YYYYMMDD    = SA.YYYYMMDD
                          AND IA.YYYYMM      = SA.YYYYMM
                          AND IA.ISO_WEEK    = SA.ISO_WEEK
                          AND A.MEASURE      = SA.MEASURE
                          AND IA.FROM_SITE   = SA.FROM_SITE);

    /* [CSR 요청번호:C20200121-000352] 82번일 경우 RTF 관련 메저 삭제 */
    /* [c20200403-000258] 81 번도 삭제                                */
    DELETE FROM GT_DMF0045_PIVOT A
     WHERE A.MEASURE LIKE '%RTF%'
       AND EXISTS (SELECT 1
                     FROM GT_DMF0045_MEASURE B
                    WHERE A.MEASURE = B.MEASURE);

    UPDATE GT_DMF0045_PIVOT A
       SET A.BOD_ID    = (SELECT BOD_ID
                            FROM (SELECT B.BOD_ID
                                    FROM SCP_MST_BOD_V B
                                   WHERE A.DIVISION_ID = B.DIVISION_ID
                                     AND A.FROM_SITE   = B.FROM_SITE
                                     AND A.TO_SITE     = B.TO_SITE
                                     AND A.INCOTERMS   = B.INCOTERMS
                                     AND A.TR_MODE     = B.TRANSPORT_MODE
                                   ORDER BY B.BOD_VALID_YN DESC                 /* 유효한 것 먼저 */
                                          , B.PRIORITY
                                          , B.BOD_ID
                                 )
                           WHERE ROWNUM = 1)
         , A.NICK_NAME = NVL((SELECT MAX(NVL(B.NICK_NAME, ''))
                                FROM SCM_MST_ITEM_SN B
                               WHERE B.NICK_NAME  IS NOT NULL
                                 AND B.DIVISION_ID = V_DIVISION_ID
                                 AND B.ACTIVE_FLAG = 'Y'
                                 AND A.ITEM_ID     = B.ITEM_ID
                                 AND A.DIVISION_ID = B.DIVISION_ID), '');

    /********************************************************************************
    * PIVOT 처리
    * 화면 칸이 조회 기간에 따라 달라지므로 이 구간만 동적 SQL 을 쓴다
    ********************************************************************************/
    V_QRY_SUM := '';

    FOR C1 IN (SELECT YYYYMMDD
                 FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK                      AS YYYYMMDD
                            , A.BASIS_START_DATE || '21'                                AS SORT_ORDER_NO
                         FROM SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                        GROUP BY A.BASIS_YYYYMM
                               , A.ISO_WEEK
                               , A.BASIS_START_DATE
                        UNION ALL
                       SELECT 'M_' || A.BASIS_YYYYMM                                    AS YYYYMMDD
                            , MIN(A.BASIS_START_DATE) || '01'                           AS SORT_ORDER_NO
                         FROM SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                        GROUP BY A.BASIS_YYYYMM
                               , A.MONTH_NAME
                        UNION ALL
                       SELECT 'D_' || A.BASIS_YYYYMMDD                                  AS YYYYMMDD
                            , A.BASIS_YYYYMMDD || '31'                                  AS SORT_ORDER_NO
                         FROM SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                        GROUP BY A.BASIS_YYYYMMDD
                      )
                ORDER BY SORT_ORDER_NO)
    LOOP
        IF SUBSTR(C1.YYYYMMDD, 1, 2) = 'M_'
        THEN
            V_QRY_SUM := V_QRY_SUM || ', CASE WHEN SUM(CASE WHEN A.YYYYMM = SUBSTR(''' || C1.YYYYMMDD || ''', -6) THEN A.QTY ELSE 0 END) = 0 AND A.MEASURE NOT LIKE ''WH%'' THEN NULL ELSE SUM(CASE WHEN A.YYYYMM = SUBSTR(''' || C1.YYYYMMDD || ''', -6) THEN A.QTY ELSE 0 END) END AS ' || C1.YYYYMMDD || CHR(10);
        ELSIF SUBSTR(C1.YYYYMMDD, 1, 2) = 'W_'
        THEN
            V_QRY_SUM := V_QRY_SUM || ', CASE WHEN SUM(CASE WHEN A.ISO_WEEK = SUBSTR(''' || C1.YYYYMMDD || ''', -6) THEN A.QTY ELSE 0 END) = 0 AND A.MEASURE NOT LIKE ''WH%'' THEN NULL ELSE SUM(CASE WHEN A.ISO_WEEK = SUBSTR(''' || C1.YYYYMMDD || ''', -6) THEN A.QTY ELSE 0 END) END AS ' || C1.YYYYMMDD || CHR(10);
        ELSE
            V_QRY_SUM := V_QRY_SUM || ', CASE WHEN SUM(CASE WHEN A.YYYYMMDD = ''' || C1.YYYYMMDD || ''' THEN A.QTY ELSE 0 END) = 0 AND A.MEASURE NOT LIKE ''WH%'' THEN NULL ELSE SUM(CASE WHEN A.YYYYMMDD = ''' || C1.YYYYMMDD || ''' THEN A.QTY ELSE 0 END) END AS ' || C1.YYYYMMDD || CHR(10);
        END IF;
    END LOOP;

    V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
           || '     , A.ITEM_ID' || CHR(10)
           || '     , CASE WHEN NVL(MAX(A.NICK_NAME), ''-'') = ''-'' THEN ''-'' ELSE MAX(A.NICK_NAME) END AS NICK_NAME' || CHR(10)
           || '     , A.FROM_SITE AS FROM_SITE' || CHR(10)
           || '     , A.TO_SITE AS TO_SITE' || CHR(10)
           || '     , A.DEPT AS TEAM_NAME_KO' || CHR(10)
           || '     , A.END_CUSTOMER AS END_CUSTOMER' || CHR(10)
           || '     , A.PROJECT_CODE AS PROJECT_CODE' || CHR(10)
           || '     , A.INCOTERMS AS INCOTERMS' || CHR(10)
           || '     , A.FCST_TYPE AS FCST_TYPE' || CHR(10)
           || '     , A.TR_MODE AS TR_MODE' || CHR(10)
           || '     , MAX(A.BOD_ID) AS BOD_ID' || CHR(10)
           /* 2026.09.30 AJS 수정 (START) */
--           || '     , CASE WHEN D.USERNAME IS NOT NULL THEN D.USERNAME || ''('' || B.CREATED_BY || '')'' ELSE B.CREATED_BY END AS LAST_UPDATED_BY' || CHR(10)
           || '     , CASE WHEN D.USER_NM IS NOT NULL THEN D.USER_NM || ''('' || B.CREATED_BY || '')'' ELSE B.CREATED_BY END AS LAST_UPDATED_BY' || CHR(10)
           /* 2026.09.30 AJS 수정 (END) */
           || '     , C.MEASURE_COLOR AS MEASURE_COLOR' || CHR(10)
           || '     , C.MEASURE_LABEL AS MEASURE_LABEL' || CHR(10)
           || '     , A.MEASURE' || CHR(10)
           || '     , NVL(E.SHIP_FROZEN, 0) AS SHIP_FROZEN' || CHR(10)
           || V_QRY_SUM
           || '  FROM GT_DMF0045_PIVOT A' || CHR(10)
           || '     , GT_DMF0045_REQUESTOR B' || CHR(10)
           || '     , GT_DMF0045_MEASURE C' || CHR(10)
           /* 2026.09.30 AJS 수정 (START) */
--           || '     , TB_FX_USER D' || CHR(10)
           || '     , SCM_ADM_USER_M D' || CHR(10)
           /* 2026.09.30 AJS 수정 (END) */
           || '     , SCM_MST_SITE E' || CHR(10)
           || ' WHERE A.DIVISION_ID   = B.DIVISION_ID(+)' || CHR(10)
           || '   AND A.ITEM_ID       = B.ITEM_ID(+)' || CHR(10)
           || '   AND A.FROM_SITE     = B.FROM_SITE(+)' || CHR(10)
           || '   AND A.TO_SITE       = B.TO_SITE(+)' || CHR(10)
           || '   AND A.TR_MODE       = B.TR_MODE(+)' || CHR(10)
           || '   AND A.INCOTERMS     = B.INCOTERMS(+)' || CHR(10)
           || '   AND A.FCST_TYPE     = B.FCST_TYPE(+)' || CHR(10)
           || '   AND A.MEASURE       = B.MEASURE(+)' || CHR(10)
           /* 2026.09.30 AJS 수정 (START) */
--           || '   AND B.CREATED_BY    = D.USERID(+)' || CHR(10)
           || '   AND B.CREATED_BY    = D.USER_ID(+)' || CHR(10)
           /* 2026.09.30 AJS 수정 (END) */
           || '   AND A.MEASURE       = C.MEASURE' || CHR(10)
           || '   AND C.BIZ_TYPE      = ''' || V_BIZ_TYPE || '''' || CHR(10)
           || '   AND A.DIVISION_ID   = E.DIVISION_ID(+)' || CHR(10)
           || '   AND A.FROM_SITE     = E.SCM_SITE_ID(+)' || CHR(10)
           || '   AND E.VALID_YN(+)   = ''Y''' || CHR(10)
           || '   AND EXISTS (SELECT 1' || CHR(10)
           || '                 FROM (SELECT DIVISION_ID, ITEM_ID FROM GT_DMF0045_SHIP_REQ' || CHR(10)
           || '                        UNION' || CHR(10)
           || '                       SELECT DIVISION_ID, ITEM_ID FROM GT_DMF0045_PLAN) SA' || CHR(10)
           || '                WHERE A.DIVISION_ID = SA.DIVISION_ID' || CHR(10)
           || '                  AND A.ITEM_ID     = SA.ITEM_ID)' || CHR(10)
           || ' GROUP BY A.DIVISION_ID' || CHR(10)
           || '        , A.ITEM_ID' || CHR(10)
           || '        , A.FROM_SITE' || CHR(10)
           || '        , A.TO_SITE' || CHR(10)
           || '        , A.DEPT' || CHR(10)
           || '        , A.END_CUSTOMER' || CHR(10)
           || '        , A.PROJECT_CODE' || CHR(10)
           || '        , A.INCOTERMS' || CHR(10)
           || '        , A.FCST_TYPE' || CHR(10)
           || '        , A.TR_MODE' || CHR(10)
           || '        , NVL(E.SHIP_FROZEN, 0)' || CHR(10)
           || '        , A.MEASURE' || CHR(10)
           || '        , B.CREATED_BY' || CHR(10)
           /* 2026.09.30 AJS 수정 (START) */
--           || '        , D.USERNAME' || CHR(10)
           || '        , D.USER_NM' || CHR(10)
           /* 2026.09.30 AJS 수정 (END) */
           || '        , C.MEASURE_COLOR' || CHR(10)
           || '        , C.MEASURE_LABEL' || CHR(10)
           || '        , C.SEQ' || CHR(10)
           /* MSSQL 정렬 규칙에 맞춘다                                          */
           /*  - 빈 값 : 오름차순은 앞, 내림차순은 뒤                            */
           /*  - 대문자 · 소문자를 가리지 않는다                                 */
           /*  - 하이픈 · 밑줄 같은 기호는 빼고 견준다                           */
           || ' ORDER BY A.DIVISION_ID NULLS FIRST' || CHR(10)
           || '        , NLSSORT(REGEXP_REPLACE(A.ITEM_ID, ''[^[:alnum:] ]'', ''''), ''NLS_SORT=BINARY_CI'') NULLS FIRST' || CHR(10)
           || '        , NLSSORT(A.ITEM_ID, ''NLS_SORT=BINARY_CI'') NULLS FIRST' || CHR(10)
           || '        , NLSSORT(REGEXP_REPLACE(A.FROM_SITE, ''[^[:alnum:] ]'', ''''), ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.FROM_SITE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(REGEXP_REPLACE(A.TO_SITE, ''[^[:alnum:] ]'', ''''), ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.TO_SITE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.PROJECT_CODE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.FCST_TYPE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.TR_MODE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , NLSSORT(A.INCOTERMS, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
           || '        , C.SEQ';

    OPEN O_RC1 FOR V_EXEC;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_DMF0045_GET_SHIPMENT_REQUEST;

/****************************************************************************************************/
/* Program ID  : P_DMF0045_GET_SPREAD_TITLE                                                         */
/* Description : Shipment Reqeust 칼럼 해더 데이터                                                  */
/****************************************************************************************************/
PROCEDURE P_DMF0045_GET_SPREAD_TITLE
(
    P_START_DT          IN  VARCHAR2
  , P_END_DT            IN  VARCHAR2
  , P_CREATED_BY        IN  VARCHAR2
  , P_SHEET_NAME        IN  VARCHAR2
  , P_DIVISION_ID       IN  VARCHAR2
  , O_RC1               OUT SYS_REFCURSOR
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    V_PROGRAM_ID    VARCHAR2(50 CHAR) := 'DMF0045';

BEGIN

    OPEN O_RC1 FOR
        SELECT PROGRAM_ID
             , SHEET_NAME
             , COLUMN_NAME
             , COLUMN_LABEL_NAME
             , SORT_ORDER_NO
             , DATA_SORT_METHOD_CODE
             , SMALL_CLASS_LABEL_NAME
             , LARGE_CLASS_LABEL_NAME
             , ''                                                           AS DAY_CODE
             , FIXED_FLAG
             , COLUMN_WIDTH
             , CELL_CONTROL_OBJECT_TYPE_CODE
             , CELL_COMBO_DATA_TYPE
             , DATA_SCALE_NUMBER
             , DATA_MAX_LENGTH
             , HORIZONTAL_ALIGN_CODE
             , UPPERCASE_APPLY_FLAG
             , VISIBLE_FLAG
             , DEFAULT_FLAG
             , USER_SELECTABLE_FLAG
             , VALID_YN
             , DIVISION_ID
          FROM SCM_MST_SHEET_COLUMNS
         WHERE PROGRAM_ID     = V_PROGRAM_ID
           AND SHEET_NAME     = P_SHEET_NAME
           AND VALID_YN       = 'Y'
           AND P_DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(DIVISION_ID, ',')))
         UNION ALL
        SELECT V_PROGRAM_ID                                                 AS PROGRAM_ID
             , P_SHEET_NAME                                                 AS SHEET_NAME
             , IA.COLUMN_NAME
             , IA.COLUMN_LABEL_NAME
             , IA.SORT_ORDER_NO
             , ''                                                           AS DATA_SORT_METHOD_CODE
             , IA.SMALL_CLASS_LABEL_NAME
             , IA.LARGE_CLASS_LABEL_NAME
             , IA.DAY_CODE
             , ''                                                           AS FIXED_FLAG
             , 70                                                           AS COLUMN_WIDTH
             , 'FPNumber'                                                   AS CELL_CONTROL_OBJECT_TYPE_CODE
             , ''                                                           AS CELL_COMBO_DATA_TYPE
             , 0                                                            AS DATA_SCALE_NUMBER
             , 10                                                           AS DATA_MAX_LENGTH
             , 'R'                                                          AS HORIZONTAL_ALIGN_CODE
             , ''                                                           AS UPPERCASE_APPLY_FLAG
             , 'Y'                                                          AS VISIBLE_FLAG
             , ''                                                           AS DEFAULT_FLAG
             , ''                                                           AS USER_SELECTABLE_FLAG
             , ''                                                           AS VALID_YN
             , ''                                                           AS DIVISION_ID
          FROM (SELECT 'D_' || A.BASIS_YYYYMMDD                             AS COLUMN_NAME
                     , A.CALENDAR_DAY                                       AS COLUMN_LABEL_NAME
                     , A.WEEK_NAME                                          AS SMALL_CLASS_LABEL_NAME
                     , A.MONTH_NAME                                         AS LARGE_CLASS_LABEL_NAME
                     , A.DAYOFWEEK                                          AS DAY_CODE
                     , TO_NUMBER(A.BASIS_YYYYMMDD || '31')                  AS SORT_ORDER_NO
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD >= P_START_DT
                   AND A.BASIS_YYYYMMDD <= P_END_DT
                 UNION ALL
                SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK                 AS COLUMN_NAME
                     , A.WEEK_NAME                                          AS COLUMN_LABEL_NAME
                     , A.WEEK_NAME                                          AS SMALL_CLASS_LABEL_NAME
                     , A.MONTH_NAME                                         AS LARGE_CLASS_LABEL_NAME
                     , ''                                                   AS DAY_CODE
                     , TO_NUMBER(A.BASIS_START_DATE || '21')                AS SORT_ORDER_NO
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD >= P_START_DT
                   AND A.BASIS_YYYYMMDD <= P_END_DT
                 GROUP BY A.BASIS_YYYYMM
                        , A.ISO_WEEK
                        , A.WEEK_NAME
                        , A.MONTH_NAME
                        , A.BASIS_START_DATE
                 UNION ALL
                SELECT 'M_' || A.BASIS_YYYYMM                               AS COLUMN_NAME
                     , A.MONTH_NAME                                         AS COLUMN_LABEL_NAME
                     , A.MONTH_NAME                                         AS SMALL_CLASS_LABEL_NAME
                     , A.MONTH_NAME                                         AS LARGE_CLASS_LABEL_NAME
                     , ''                                                   AS DAY_CODE
                     , TO_NUMBER(MIN(A.BASIS_START_DATE) || '01')           AS SORT_ORDER_NO
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD >= P_START_DT
                   AND A.BASIS_YYYYMMDD <= P_END_DT
                 GROUP BY A.BASIS_YYYYMM
                        , A.MONTH_NAME
               ) IA
         ORDER BY SORT_ORDER_NO;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_DMF0045_GET_SPREAD_TITLE;

/****************************************************************************************************/
/* Program ID  : P_DMF0045_SAVE_SHIPMENT_REQUEST                                                    */
/* Description : Shipment Request 입력                                                              */
/****************************************************************************************************/
PROCEDURE P_DMF0045_SAVE_SHIPMENT_REQUEST
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_FROM_SITE         IN  CLOB
  , P_TO_SITE           IN  CLOB
  , P_PROJECT_CODE      IN  CLOB
  , P_INCOTERMS         IN  CLOB
  , P_FCST_TYPE         IN  CLOB
  , P_TRANSPORT_MODE    IN  CLOB
  , P_BOD_ID            IN  CLOB
  , P_MEASURE           IN  CLOB
  , P_YYYYMMDD          IN  CLOB
  , P_QTY               IN  CLOB
  , P_CREATED_BY        IN  VARCHAR2
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
IS
    V_DELIMITER         VARCHAR2(1 CHAR)    := '^';
    V_MAX_LOOP_CNT      NUMBER              := 0;
    V_MST_LOOP_CNT      NUMBER              := 0;

    V_PROGRAM_NAME      VARCHAR2(150 CHAR)  := 'PKG_DMF0045.P_DMF0045_SAVE_SHIPMENT_REQUEST';
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    V_LOG_COUNT         NUMBER              := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    V_EVENT_DATE        DATE;

    V_CNT_NO_BOD        NUMBER              := 0;
    V_STR_NO_BOD        VARCHAR2(150 CHAR)  := '';
    V_ERR_MESSAGE       VARCHAR2(4000 CHAR) := '';
    V_ERR_CODE          NUMBER;
    V_SQLERRM           VARCHAR2(4000 CHAR);
    V_SQLCODE           NUMBER;

BEGIN

    /* 임시테이블 초기화 */
    DELETE FROM GT_DMF0045_SAVE;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

    /* 프로시저 LOOP 길이를 판단 */
    V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ITEM_ID, V_DELIMITER);

    /*** 1. 신규건 MEASURE별 입력데이터 정리 *****/
    WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT
    LOOP
        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        INSERT INTO GT_DMF0045_SAVE
                    (
                      ACTIVE_FLAG, DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, PROJECT_CODE
                    , INCOTERMS, FCST_TYPE, TRANSPORT_MODE, BOD_ID, MEASURE, YYYYMMDD, QTY
                    )
        SELECT SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,     V_DELIMITER, V_MST_LOOP_CNT)     AS ACTIVE_FLAG
             , SCM_ARR_SPL_VAL(P_DIVISION_ID,     V_DELIMITER, V_MST_LOOP_CNT)     AS DIVISION_ID
             , SCM_ARR_SPL_VAL(P_ITEM_ID,         V_DELIMITER, V_MST_LOOP_CNT)     AS ITEM_ID
             , SCM_ARR_SPL_VAL(P_FROM_SITE,       V_DELIMITER, V_MST_LOOP_CNT)     AS FROM_SITE
             , SCM_ARR_SPL_VAL(P_TO_SITE,         V_DELIMITER, V_MST_LOOP_CNT)     AS TO_SITE
             , SCM_ARR_SPL_VAL(P_PROJECT_CODE,    V_DELIMITER, V_MST_LOOP_CNT)     AS PROJECT_CODE
             , SCM_ARR_SPL_VAL(P_INCOTERMS,       V_DELIMITER, V_MST_LOOP_CNT)     AS INCOTERMS
             , SCM_ARR_SPL_VAL(P_FCST_TYPE,       V_DELIMITER, V_MST_LOOP_CNT)     AS FCST_TYPE
             , SCM_ARR_SPL_VAL(P_TRANSPORT_MODE,  V_DELIMITER, V_MST_LOOP_CNT)     AS TRANSPORT_MODE
             , SCM_ARR_SPL_VAL(P_BOD_ID,          V_DELIMITER, V_MST_LOOP_CNT)     AS BOD_ID
             , SCM_ARR_SPL_VAL(P_MEASURE,         V_DELIMITER, V_MST_LOOP_CNT)     AS MEASURE
             , SCM_ARR_SPL_VAL(P_YYYYMMDD,        V_DELIMITER, V_MST_LOOP_CNT)     AS YYYYMMDD
             , SCM_ARR_SPL_VAL(P_QTY,             V_DELIMITER, V_MST_LOOP_CNT)     AS QTY
          FROM DUAL;
    END LOOP;

    /* BOD ID Update                                          */
    /* Active Flag가 M이여도 로직 상 Insert 대상인 건들이 있음 */
    UPDATE GT_DMF0045_SAVE A
       SET A.BOD_ID = (SELECT IA.BOD_ID
                         FROM (SELECT B.BOD_ID
                                    , B.DIVISION_ID
                                    , B.FROM_SITE
                                    , B.TO_SITE
                                    , B.ATTRIBUTE1
                                    , B.ATTRIBUTE2
                                    , B.ATTRIBUTE3
                                    , B.VALID_YN
                                    , C.TRANSPORT_MODE
                                    , ROW_NUMBER() OVER (PARTITION BY A.FROM_SITE, A.TO_SITE, A.INCOTERMS, A.TRANSPORT_MODE
                                                             ORDER BY B.PRIORITY ASC) AS RNUM
                                 FROM GT_DMF0045_SAVE A
                                    , SCP_MST_BOD B
                                    , SCP_MST_DISTRIBUTION_ROUTE C
                                WHERE A.DIVISION_ID    = B.DIVISION_ID
                                  AND A.FROM_SITE      = B.FROM_SITE
                                  AND A.TO_SITE        = B.TO_SITE
                                  /* 2020/09/21  KIMYONGHO     SSP INCOTERMS 변경 작업 */
                                  AND A.INCOTERMS      = B.ATTRIBUTE1
                                  AND B.VALID_YN       = 'Y'
                                  AND B.ATTRIBUTE2    <= A.YYYYMMDD
                                  AND B.ATTRIBUTE3    >= A.YYYYMMDD
                                  AND B.ROUTE_ID       = C.ROUTE_ID
                                  AND C.TRANSPORT_MODE = A.TRANSPORT_MODE
                                  AND A.ACTIVE_FLAG    = 'M'
                              ) IA
                        WHERE A.DIVISION_ID    = IA.DIVISION_ID
                          AND A.FROM_SITE      = IA.FROM_SITE
                          AND A.TO_SITE        = IA.TO_SITE
                          AND A.INCOTERMS      = IA.ATTRIBUTE1
                          AND IA.VALID_YN      = 'Y'
                          AND IA.ATTRIBUTE2   <= A.YYYYMMDD
                          AND IA.ATTRIBUTE3   >= A.YYYYMMDD
                          AND IA.RNUM          = 1)
     WHERE EXISTS (SELECT 1
                     FROM (SELECT B.BOD_ID
                                , B.DIVISION_ID
                                , B.FROM_SITE
                                , B.TO_SITE
                                , B.ATTRIBUTE1
                                , B.ATTRIBUTE2
                                , B.ATTRIBUTE3
                                , B.VALID_YN
                                , ROW_NUMBER() OVER (PARTITION BY A.FROM_SITE, A.TO_SITE, A.INCOTERMS, A.TRANSPORT_MODE
                                                         ORDER BY B.PRIORITY ASC) AS RNUM
                             FROM GT_DMF0045_SAVE A
                                , SCP_MST_BOD B
                                , SCP_MST_DISTRIBUTION_ROUTE C
                            WHERE A.DIVISION_ID    = B.DIVISION_ID
                              AND A.FROM_SITE      = B.FROM_SITE
                              AND A.TO_SITE        = B.TO_SITE
                              AND A.INCOTERMS      = B.ATTRIBUTE1
                              AND B.VALID_YN       = 'Y'
                              AND B.ATTRIBUTE2    <= A.YYYYMMDD
                              AND B.ATTRIBUTE3    >= A.YYYYMMDD
                              AND B.ROUTE_ID       = C.ROUTE_ID
                              AND C.TRANSPORT_MODE = A.TRANSPORT_MODE
                              AND A.ACTIVE_FLAG    = 'M'
                          ) IA
                    WHERE A.DIVISION_ID    = IA.DIVISION_ID
                      AND A.FROM_SITE      = IA.FROM_SITE
                      AND A.TO_SITE        = IA.TO_SITE
                      AND A.INCOTERMS      = IA.ATTRIBUTE1
                      AND IA.VALID_YN      = 'Y'
                      AND IA.ATTRIBUTE2   <= A.YYYYMMDD
                      AND IA.ATTRIBUTE3   >= A.YYYYMMDD
                      AND IA.RNUM          = 1);

    /* BOD CHECK */
    SELECT COUNT(*)
      INTO V_CNT_NO_BOD
      FROM GT_DMF0045_SAVE
     WHERE ACTIVE_FLAG = 'M'
       AND BOD_ID     IS NULL;

    IF V_CNT_NO_BOD > 0
    THEN
        SELECT NO_BOD
          INTO V_STR_NO_BOD
          FROM (SELECT DIVISION_ID || '/' || FROM_SITE || '/' || TO_SITE || '/' || INCOTERMS || '/' || TRANSPORT_MODE AS NO_BOD
                  FROM GT_DMF0045_SAVE
                 WHERE ACTIVE_FLAG = 'M'
                   AND BOD_ID     IS NULL
               )
         WHERE ROWNUM = 1;

        V_ERR_MESSAGE := 'Div, From Site, To Site 에 해당되는 BOD(Trans mode, Incoterms) 정보가 유효하지 않습니다. ' || V_STR_NO_BOD;
        RAISE_APPLICATION_ERROR(-20111, V_ERR_MESSAGE);                     /* 예외발생 */
    END IF;

    V_EVENT_DATE := SYSDATE;

    /* 수정                                                                             */
    /* 삭제기능은 없으므로 Active Flag는 'I' 또는 'M'으로 가정하고 입력/수정만 진행      */
    UPDATE DM_PLN_SHIPMENT_REQ A
       SET (A.QTY, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE, A.ATTRIBUTE1)
             = (SELECT TO_NUMBER(B.QTY)
                     , P_CREATED_BY
                     , V_EVENT_DATE
                     , 'Y'
                  FROM GT_DMF0045_SAVE B
                 WHERE A.DIVISION_ID    = B.DIVISION_ID
                   AND A.SCM_SITE_ID    = B.TO_SITE
                   AND A.PROJECT_CODE   = B.PROJECT_CODE
                   AND A.ITEM_ID        = B.ITEM_ID
                   AND A.INCOTERMS      = B.INCOTERMS
                   AND A.BOD_ID         = B.BOD_ID                              /* 20200624 KIMYONGHO 저장 문제로 해당 조건 추가 */
                   AND A.FCST_TYPE      = B.FCST_TYPE                           /* 20200624 KIMYONGHO 저장 문제로 해당 조건 추가 */
                   AND A.TRANSPORT_MODE = B.TRANSPORT_MODE
                   AND A.MEASURE        = B.MEASURE
                   AND A.PLANT_SITE_ID  = B.FROM_SITE
                   AND A.YYYYMMDD       = B.YYYYMMDD
                   AND ROWNUM           = 1)
     WHERE EXISTS (SELECT 1
                     FROM GT_DMF0045_SAVE B
                    WHERE A.DIVISION_ID    = B.DIVISION_ID
                      AND A.SCM_SITE_ID    = B.TO_SITE
                      AND A.PROJECT_CODE   = B.PROJECT_CODE
                      AND A.ITEM_ID        = B.ITEM_ID
                      AND A.INCOTERMS      = B.INCOTERMS
                      AND A.BOD_ID         = B.BOD_ID
                      AND A.FCST_TYPE      = B.FCST_TYPE
                      AND A.TRANSPORT_MODE = B.TRANSPORT_MODE
                      AND A.MEASURE        = B.MEASURE
                      AND A.PLANT_SITE_ID  = B.FROM_SITE
                      AND A.YYYYMMDD       = B.YYYYMMDD);

    /* 입력 */
    INSERT INTO DM_PLN_SHIPMENT_REQ
                (
                  DIVISION_ID,   PROJECT_CODE,   SCM_SITE_ID,     ITEM_ID,          FCST_TYPE
                , INCOTERMS,     TRANSPORT_MODE, MEASURE,         PLANT_SITE_ID,    YYYYMMDD,         QTY
                , BOD_ID,        SITE_TYPE,      CREATED_BY,      CREATION_DATE,    LAST_UPDATED_BY,  LAST_UPDATE_DATE
                , ATTRIBUTE1
                )
    SELECT B.DIVISION_ID
         , B.PROJECT_CODE
         , B.TO_SITE
         , B.ITEM_ID
         , B.FCST_TYPE
         , B.INCOTERMS
         , B.TRANSPORT_MODE
         , B.MEASURE
         , B.FROM_SITE
         , B.YYYYMMDD
         , TO_NUMBER(B.QTY)
         , B.BOD_ID
         , 'SALES'
         , P_CREATED_BY
         , V_EVENT_DATE
         , P_CREATED_BY
         , V_EVENT_DATE
         , 'Y'
      FROM GT_DMF0045_SAVE B
     WHERE NOT EXISTS (SELECT 1
                         FROM DM_PLN_SHIPMENT_REQ A
                        WHERE A.DIVISION_ID    = B.DIVISION_ID
                          AND A.PROJECT_CODE   = B.PROJECT_CODE
                          AND A.SCM_SITE_ID    = B.TO_SITE
                          AND A.ITEM_ID        = B.ITEM_ID
                          AND A.INCOTERMS      = B.INCOTERMS
                          AND A.BOD_ID         = B.BOD_ID                       /* 20200624 KIMYONGHO 저장 문제로 해당 조건 추가 */
                          AND A.FCST_TYPE      = B.FCST_TYPE                    /* 20200624 KIMYONGHO 저장 문제로 해당 조건 추가 */
                          AND A.TRANSPORT_MODE = B.TRANSPORT_MODE
                          AND A.MEASURE        = B.MEASURE
                          AND A.PLANT_SITE_ID  = B.FROM_SITE
                          AND A.YYYYMMDD       = B.YYYYMMDD);

    /* History */
    INSERT INTO DM_PLN_SHIPMENT_REQ_H
                (
                  DIVISION_ID,   PROJECT_CODE,   SCM_SITE_ID,     ITEM_ID,          FCST_TYPE
                , INCOTERMS,     TRANSPORT_MODE, MEASURE,         PLANT_SITE_ID,    YYYYMMDD,         QTY
                , BOD_ID,        SITE_TYPE,      CREATED_BY,      CREATION_DATE,    LAST_UPDATED_BY,  LAST_UPDATE_DATE
                , ATTRIBUTE1
                )
    SELECT B.DIVISION_ID
         , B.PROJECT_CODE
         , B.TO_SITE
         , B.ITEM_ID
         , B.FCST_TYPE
         , B.INCOTERMS
         , B.TRANSPORT_MODE
         , B.MEASURE
         , B.FROM_SITE
         , B.YYYYMMDD
         , TO_NUMBER(B.QTY)
         , B.BOD_ID
         , 'SALES'
         , P_CREATED_BY
         , V_EVENT_DATE
         , P_CREATED_BY
         , V_EVENT_DATE
         , 'Y'
      FROM GT_DMF0045_SAVE B;

    OPEN O_RESULT_CURSOR FOR
        SELECT 'S'  AS RESULT_CODE
             , ''   AS MSG
          FROM DUAL;

    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

EXCEPTION
    WHEN OTHERS THEN
        V_SQLCODE := SQLCODE;
        V_SQLERRM := SQLERRM;

        ROLLBACK;

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME
                    , LOG_TYPE
                    , LOG_COUNT
                    , LOG_MESSAGE
                    , DESCRIPTION
                    , EVENT_DATE
                    , CREATION_DATE
                    , CREATED_BY
                    , LAST_UPDATE_DATE
                    , LAST_UPDATED_BY
                    )
        VALUES      (
                      V_PROGRAM_NAME
                    , 'ERROR'
                    , NULL
                    , V_SQLERRM
                    , NULL
                    , SYSDATE
                    , SYSDATE
                    , V_PROGRAM_NAME
                    , SYSDATE
                    , V_PROGRAM_NAME
                    );
        COMMIT;

        /* error코드, errror 메시지 반환 */
        IF V_SQLCODE = -20111
        THEN
            OPEN O_RESULT_CURSOR FOR
                SELECT 'N'              AS RESULT_CODE
                     , V_ERR_MESSAGE    AS ERR_MESSAGE
                  FROM DUAL;
        ELSE
            OPEN O_RESULT_CURSOR FOR
                SELECT 'F'                                      AS RESULT_CODE
                     , '[' || V_SQLCODE || ']' || V_SQLERRM     AS ERR_MESSAGE
                  FROM DUAL;
        END IF;

END P_DMF0045_SAVE_SHIPMENT_REQUEST;

END PKG_DMF0045;
/
SHOW ERRORS PACKAGE BODY PKG_DMF0045
-- ##### END PACKAGE BODY PKG_DMF0045

-- ##### START PACKAGE BODY PKG_DMF0049
CREATE OR REPLACE PACKAGE BODY           "PKG_DMF0049" IS

    PROCEDURE P_DMF0049_GET_MEASURE
    (
        P_DIVISION_ID   VARCHAR2
       ,P_USER_ID       VARCHAR2
       ,P_MENU_ID       VARCHAR2
       ,O_RC1           OUT SYS_REFCURSOR
       ,O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    /*
         * Program ID   : DMF0049_GET_MEASURE
         * Description  :  Sales ETC Report 메저 가져오기
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020/03/30 HWI1993   Initial Release -- dmf0044 에서 복사해서 생성
         * 2020/05/04 HWI1993   DIVISION_ID 를 WHERE 절에 추가
         * 2020/06/10 HWI1993   40이 아닌 경우 USD 추가
         * 2021/01/28 P.C.I   [C20210125-000207] 소형사업부 RTF_SYS_RP Measure 추가
           2022.04.25 HWI1993   GM JV 작업
           2026.03.14 김준규   [PJ20264226] NextSCM Pilot 설계 및 개발
        */
     AS

        V_PROGRAM_NAME VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
        V_LOG_TYPE     VARCHAR2(30 CHAR);
        N_LOG_COUNT    INTEGER := 0;
        V_LOG_MESSAGE  VARCHAR2(1000 CHAR);
        V_DESCRIPTION  VARCHAR2(500 CHAR);
        D_EVENT_DATE   DATE;
        V_IN_PARA_DATA VARCHAR2(4000);
    BEGIN

        V_IN_PARA_DATA := JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID);

        IF P_DIVISION_ID = '40' THEN
            OPEN O_RC1 FOR
                SELECT COLUMN_NAME AS CODE, COLUMN_LABEL_NAME NAME, TEI.EDIT_YN
                FROM   SCM_MST_SHEET_MEASURE A
                INNER  JOIN TABLE(PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                -- [MSRUNIT 2026-08-11] 조인 대상을 A.DIVISION_ID(콤마 목록) → 요청 division 으로.
                --   등호 비교라 목록형 행이 전부 탈락해 div40=1행 / div81·82=0행이었다(삽입 차단).
                --   TEI 조인은 권한(EDIT_YN) 획득용이고, division 필터는 아래 INSTR 라인이 담당한다.
                ON     TEI.UNIT_ID = P_DIVISION_ID
                WHERE  1 = 1
                AND    PROGRAM_ID = 'DMF0049'
                AND    SHEET_NAME IN ( 'MDF Reports','mdfReports' )
                AND    COLUMN_NAME IN ('SalesAmt_KRW', 'SalesAmt_LOC', 'RTF_SYS_RP') --[C20210125-000207] 소형사업부 RTF_SYS_RP Measure 추가
                AND    INSTR(A.DIVISION_ID, P_DIVISION_ID) > 0
                ORDER  BY SORT_ORDER_NO;
        ELSE
            OPEN O_RC1 FOR
                SELECT COLUMN_NAME AS CODE, COLUMN_LABEL_NAME NAME, TEI.EDIT_YN
                FROM   SCM_MST_SHEET_MEASURE A
                INNER  JOIN TABLE(PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                -- [MSRUNIT 2026-08-11] 조인 대상을 A.DIVISION_ID(콤마 목록) → 요청 division 으로.
                --   등호 비교라 목록형 행이 전부 탈락해 div40=1행 / div81·82=0행이었다(삽입 차단).
                --   TEI 조인은 권한(EDIT_YN) 획득용이고, division 필터는 아래 INSTR 라인이 담당한다.
                ON     TEI.UNIT_ID = P_DIVISION_ID
                WHERE  1 = 1
                AND    PROGRAM_ID = 'DMF0049'
                AND    SHEET_NAME IN ( 'MDF Reports','mdfReports' )
                AND    COLUMN_NAME IN ('SalesAmt_KRW', 'SalesAmt_LOC', 'SalesAmt_USD')
                AND    INSTR(A.DIVISION_ID, P_DIVISION_ID) > 0
                ORDER  BY SORT_ORDER_NO;
        END IF;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;
    EXCEPTION
        WHEN OTHERS THEN
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                                ,V_LOG_TYPE
                                ,N_LOG_COUNT
                                ,V_LOG_MESSAGE
                                ,V_DESCRIPTION
                                ,D_EVENT_DATE
                                ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                                ,P_SQL_ERR_CODE  => SQLCODE
                                ,P_SQL_ERR_MSG   => SQLERRM
                                ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            RAISE_APPLICATION_ERROR(-20001
                                   ,'[' || $$PLSQL_UNIT || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                    DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
    END P_DMF0049_GET_MEASURE;

    PROCEDURE P_DMF0049_GET_SPREAD_TITLE
    (
        P_DIVISION_ID   VARCHAR2
       ,P_CREATED_BY    VARCHAR2
       ,P_START_DT      VARCHAR2
       ,P_END_DT        VARCHAR2
       ,P_USER_ID       VARCHAR2
       ,P_MENU_ID       VARCHAR2
       ,O_RC1           OUT SYS_REFCURSOR
       ,O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    /*
        * Program ID   : DMF0049_GET_SPREAD_TITLE
        * Description  :
        * Program History
        *===================================================================================================
        *   Date       In Charge      Description
        *===================================================================================================
        * 2020/04/02 hwi1993   DMF0049_GET_SPREAD_TITLE
        * 2022/05/12 hwi1993   GM JV
        * 2026/03/15 김준규      [PJ20264226] NextSCM Pilot 설계 및 개발
        */
     AS

        P_PROGRAM_ID   VARCHAR2(50 CHAR);
        P_SHEET_NAME   VARCHAR2(50 CHAR);
        V_IN_PARA_DATA VARCHAR2(4000);
        V_LOG_TYPE     VARCHAR2(20) := NULL;
        N_LOG_COUNT    NUMBER := 0;
        V_LOG_MESSAGE  VARCHAR2(4000 CHAR) := NULL;
        V_DESCRIPTION  VARCHAR2(4000 CHAR) := NULL;
        D_EVENT_DATE   DATE := SYSDATE;
        V_PROC_INPUT   CLOB := NULL;
        V_SQL_CODE     VARCHAR2(100) := NULL;
        V_SQL_ERRMSG   VARCHAR2(4000 CHAR) := NULL;
        V_BACKTRACE    VARCHAR2(4000 CHAR) := NULL;
    BEGIN

        V_IN_PARA_DATA := JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID
                                     ,'p_created_by' VALUE P_CREATED_BY
                                     ,'p_start_dt' VALUE P_START_DT
                                     ,'p_end_dt' VALUE P_END_DT);

        P_PROGRAM_ID := 'DMF0049';
        P_SHEET_NAME := 'MDF Reports';

        OPEN O_RC1 FOR
            SELECT C.PROGRAM_ID
                  ,C.SHEET_NAME
                  ,C.COLUMN_NAME
                  ,C.COLUMN_LABEL_NAME
                   --, C.SORT_ORDER_NO        --TO_CHAR(U.SORT_ORDER_NO) SORT_ORDER_NO
                  ,CASE
                       WHEN P_DIVISION_ID = '40' THEN
                        TO_CHAR(C.SORT_ORDER_NO)
                       WHEN P_DIVISION_ID LIKE '81%' THEN
                        C.ATTRIBUTE2
                       WHEN P_DIVISION_ID = '82' THEN
                        C.ATTRIBUTE3
                   END AS SORT_ORDER_NO
                  ,C.DATA_SORT_METHOD_CODE
                  ,C.SMALL_CLASS_LABEL_NAME
                  ,C.LARGE_CLASS_LABEL_NAME
                  ,'' AS DAY_CODE
                  ,C.FIXED_FLAG
                  ,CASE
                       WHEN CASE
                                WHEN P_DIVISION_ID = '40' THEN
                                 C.VISIBLE_FLAG
                                WHEN P_DIVISION_ID LIKE '81%' THEN
                                 C.ATTRIBUTE4
                                WHEN P_DIVISION_ID = '82' THEN
                                 C.ATTRIBUTE5
                            END = 'Y' THEN
                        C.COLUMN_WIDTH
                       ELSE
                        0
                   END AS COLUMN_WIDTH
                  ,C.CELL_CONTROL_OBJECT_TYPE_CODE
                  ,C.CELL_COMBO_DATA_TYPE
                  ,TO_CHAR(C.DATA_SCALE_NUMBER) DATA_SCALE_NUMBER
                  ,TO_CHAR(C.DATA_MAX_LENGTH) DATA_MAX_LENGTH
                  ,C.HORIZONTAL_ALIGN_CODE
                  ,C.UPPERCASE_APPLY_FLAG
                  ,CASE
                       WHEN P_DIVISION_ID = '40' THEN
                        C.VISIBLE_FLAG
                       WHEN P_DIVISION_ID LIKE '81%' THEN
                        C.ATTRIBUTE4
                       WHEN P_DIVISION_ID = '82' THEN
                        C.ATTRIBUTE5
                   END AS VISIBLE_FLAG
                  ,C.DEFAULT_FLAG
                  ,C.USER_SELECTABLE_FLAG
                  ,C.VALID_YN
                  ,C.DIVISION_ID
                  ,P_DIVISION_ID ATTRIBUTE1 -- COMMONDATALIST 에서 사용하도록 DIVISION 을 넣어준다.
                  ,CASE
                       WHEN CELL_COMBO_DATA_TYPE = 'DM_LOOKUP_DIV' THEN
                        C.ATTRIBUTE1
                       ELSE
                        C.ATTRIBUTE1
                   END AS ATTRIBUTE2
                  ,'' AS ATTRIBUTE3
                  ,'' AS ATTRIBUTE4
                  ,'' AS ATTRIBUTE5
                  ,TEI.EDIT_YN
            FROM   SCM_MST_SHEET_COLUMNS C
            INNER  JOIN TABLE(PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
            ON     TEI.UNIT_ID = C.DIVISION_ID
            WHERE  1 = 1
            AND    C.PROGRAM_ID = P_PROGRAM_ID
            AND    C.SHEET_NAME = P_SHEET_NAME
            AND    C.VALID_YN = 'Y'
            AND    C.DIVISION_ID LIKE '%' || P_DIVISION_ID || '%'
            UNION ALL

            SELECT P_PROGRAM_ID PROGRAM_ID
                  ,P_SHEET_NAME SHEET_NAME
                  ,MA.COLUMN_NAME
                  ,MA.COLUMN_LABEL_NAME
                  ,MA.SORT_ORDER_NO
                  ,'' AS DATA_SORT_METHOD_CODE
                  ,MA.SMALL_CLASS_LABEL_NAME
                  ,MA.LARGE_CLASS_LABEL_NAME
                  ,MA.DAY_CODE
                  ,'' AS FIXED_FLAG
                  ,120 COLUMN_WIDTH
                  ,MA.CELL_CONTROL_OBJECT_TYPE_CODE --'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                  ,'' AS CELL_COMBO_DATA_TYPE
                   --, '2'         AS DATA_SCALE_NUMBER
                  ,'3' AS DATA_SCALE_NUMBER -- 20181029
                  ,'2' AS DATA_MAX_LENGTH
                  ,'R' AS HORIZONTAL_ALIGN_CODE
                  ,'' AS UPPERCASE_APPLY_FLAG
                  ,'Y' AS VISIBLE_FLAG
                  ,'' AS DEFAULT_FLAG
                  ,'' AS USER_SELECTABLE_FLAG
                  ,'' AS VALID_YN
                  ,'' AS DIVISION_ID
                  ,'' AS ATTRIBUTE1
                  ,'' AS ATTRIBUTE2
                  ,'' AS ATTRIBUTE3
                  ,'' AS ATTRIBUTE4
                  ,'' AS ATTRIBUTE5
                  ,'N' AS EDIT_YN
            FROM   (SELECT DISTINCT 'M_' || BASIS_YYYYMM AS COLUMN_NAME
                                   ,MONTH_NAME COLUMN_LABEL_NAME
                                   ,MONTH_NAME SMALL_CLASS_LABEL_NAME
                                   ,MONTH_NAME LARGE_CLASS_LABEL_NAME
                                   ,'' AS DAY_CODE
                                   ,TO_CHAR(BASIS_YYYYMM) SORT_ORDER_NO
                                   ,'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                    FROM   SCM_SYS_CALENDAR_M
                    WHERE  BASIS_YYYYMMDD >= P_START_DT
                    AND    BASIS_YYYYMMDD <= P_END_DT

                    ) MA

            ORDER  BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE   := 'ERROR';
            V_SQL_CODE   := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG := SQLERRM;
            V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT
                                ,V_LOG_TYPE
                                ,N_LOG_COUNT
                                ,V_LOG_MESSAGE
                                ,V_DESCRIPTION
                                ,D_EVENT_DATE
                                ,V_PROC_INPUT
                                ,V_SQL_CODE
                                ,V_SQL_ERRMSG
                                ,V_BACKTRACE);
            RAISE_APPLICATION_ERROR(-20001
                                   ,'[' || $$PLSQL_UNIT || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                    DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
    END P_DMF0049_GET_SPREAD_TITLE;

  PROCEDURE P_DMF0049_GET_SALES_ETC_REPORTS_DATA 
(
    p_division_id     IN  VARCHAR2,
    p_mdf_type        IN  VARCHAR2,
    p_yyyy            IN  VARCHAR2,
    p_sp_version_no   IN  VARCHAR2,
    p_user_group      IN  VARCHAR2,
    p_created_by      IN  VARCHAR2,
    p_user_id         IN  VARCHAR2,   -- For EditYn
    p_menu_id         IN  VARCHAR2,   -- For EditYn
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*
 * Program ID   : DMF0049_GET_SALES_ETC_REPORTS_DATA
 * Description  : ETC Sales Reports 메인 데이터 조회
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/04/02  HWI1993	Initial Release
 * 2020/05/19	HWI1993	SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, ITEM_USE ISNULL 처리 ( NULL 과 공백이 GROUPING 분리됨 )
 * 2021/01/26     P.C.I		[C20210125-000207] 40사업부 RTF Measure, CELL_MODEL_INFO 컬럼 추가
 * 2022/01/12	rosia27		[C20220105-000064]ETC Report 구버전 조회시 조직 명칭 오류의 건
 * 2022/01/21	rosia27		[C20211112-000213]GSCM의 Cell Model 컬럼 관련 요청의 건
 * 2026/06/05	NextSCM Migration	[PJ202650304] 기존 배포본(미완성 자동변환, INVALID) 전면 재변환. #SELECT_MEASURE/#PJT/#temp→GTT(GT_DMF0049_*), @PROD 누적→FOR LOOP, 동적 SQL/PIVOT 정정(EXECUTE 대신 OPEN O_RC1 FOR), Pilot 표준 적용(로깅/EXCEPTION/O_RESULT_CURSOR/EDIT_YN 권한 INNER JOIN). 템플릿=DMF0044_GET_SALES_REPORTS_DATA(VALID)
 */
IS

    V_PROD          VARCHAR2(4000 CHAR) := '';   -- PIVOT IN 절 (값 AS 별칭)
    V_COLS          VARCHAR2(4000 CHAR) := '';   -- 외부 SELECT 의 PIVOT 컬럼 참조
    V_SQL           VARCHAR2(32767 CHAR) := '';
    V_GROUP_ID      VARCHAR2(100 CHAR) := '';
    V_TEAM_ID       VARCHAR2(100 CHAR) := '';
    V_USER_MEA_CNT  PLS_INTEGER := 0;

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN
    --[E20260812-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어 (2026-08-06 표준, 2026-08-12 DMF0044/0049 일괄 적용)
    EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── GTT 초기화 (세션 보존 GTT 이므로 DELETE) ── */
    DELETE FROM SCM_MGR.GT_DMF0049_SELECT_MEASURE;
    DELETE FROM SCM_MGR.GT_DMF0049_PJT;
    DELETE FROM SCM_MGR.GT_DMF0049_T;

    ---------------------------------------------------------------------------------
    --            20200313 KHSONG C20200103-000586 권한그룹을 LOOKUP관리 (BEGIN)
    ---------------------------------------------------------------------------------
    BEGIN
        SELECT 1
        INTO   V_USER_MEA_CNT
        FROM   DUAL
        WHERE  EXISTS (
            SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL
            WHERE  LOOKUP_TYPE = 'GET_ADMIN_GROUP'
            AND    VALID_YN = 'Y'
            AND    SEGMENT2 = 'ALL'  -- 'ALL'인경우 기본값(특정화면에서 추가된 그룹을 제외)
            AND    (SEGMENT1 = p_user_group  --[AUTHUNION 2026-08-09] 보유그룹 합집합 판정 (사용자 승인)
                    OR SEGMENT1 IN (SELECT G.USER_GR_ID FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                                    WHERE G.USER_ID IN (p_user_group, p_user_id, p_created_by)
                                      AND G.USE_YN = 'Y'))
        );
        V_GROUP_ID := 'ADMIN';
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_GROUP_ID := '';
    END;
    ---------------------------------------------------------------------------------
    --            20200313 KHSONG C20200103-000586 권한그룹을 LOOKUP관리 (END)
    ---------------------------------------------------------------------------------

    -- 팀 권한
    BEGIN
        SELECT DEPT_ID
        INTO   V_TEAM_ID
        /* 2026.09.30 AJS 수정 (START) */
--        FROM   TB_FX_USER
--        WHERE  USERID = p_created_by;
        FROM   SCM_ADM_USER_M
        WHERE  USER_ID = p_created_by;
        /* 2026.09.30 AJS 수정 (END) */
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_TEAM_ID := '';
        WHEN TOO_MANY_ROWS THEN
            V_TEAM_ID := '';
    END;

    V_USER_MEA_CNT := 0;

    -- MEASURE JOIN 처리용
    -- 사용자메저 처리
    BEGIN
        SELECT 1
        INTO   V_USER_MEA_CNT
        FROM   DUAL
        WHERE  EXISTS (
            SELECT 1
            FROM   SCM_MST_TITLESET_USER U
            WHERE  U.PROGRAM_ID = 'DMF0049'
            AND    U.SHEET_NAME = 'MDF Reports'
            AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'M'
            AND    U.USER_ID    = p_created_by
        );
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_USER_MEA_CNT := 0;
    END;

    IF V_USER_MEA_CNT = 0 THEN
        INSERT INTO SCM_MST_TITLESET_USER
        ( USER_ID
        , PROGRAM_ID
        , SHEET_NAME
        , USER_INQUIRY_COLUMN_TYPE_CODE
        , COLUMN_NAME
        , SORT_ORDER_NO
        , SUB_TOTAL_FLAG
        , DATA_SORT_METHOD_CODE
        , CREATED_BY
        , CREATION_DATE
        , LAST_UPDATED_BY
        , LAST_UPDATE_DATE
        )
        SELECT p_created_by
             , C.PROGRAM_ID
             , C.SHEET_NAME
             , 'M'
             , C.COLUMN_NAME
             , C.SORT_ORDER_NO
             , 'N'
             , ''
             , p_created_by
             , SYSDATE                 -- [PJ202650304] DATE 컬럼: 문자열 변환 제거(ORA-01861 예방)
             , p_created_by
             , SYSDATE
        FROM   SCM_MST_SHEET_MEASURE C
        WHERE  1 = 1
        AND    C.PROGRAM_ID  = 'DMF0049'
        AND    C.SHEET_NAME  = 'MDF Reports'
        AND    C.DEFAULT_FLAG = 'Y'
        AND    C.VALID_YN     = 'Y';
    END IF;

    /* ── GT_DMF0049_SELECT_MEASURE 적재 (#SELECT_MEASURE) ── */
    INSERT INTO SCM_MGR.GT_DMF0049_SELECT_MEASURE
        (PROGRAM_ID, SHEET_NAME, USER_ID, MEASURE, SORT_ORDER_NO)
    SELECT U.PROGRAM_ID
         , U.SHEET_NAME
         , U.USER_ID
         , U.COLUMN_NAME AS MEASURE
         , U.SORT_ORDER_NO
    FROM SCM_MST_TITLESET_USER U
    WHERE 1 = 1
    AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'M'
    AND U.PROGRAM_ID   = 'DMF0049'
    AND U.USER_ID      = p_created_by;

    /* ── GT_DMF0049_PJT 적재 (#PJT) ── */
    INSERT INTO SCM_MGR.GT_DMF0049_PJT
        (DIVISION_ID, PROJECT_CODE, PROJECT_NAME, PRODUCT_GROUP_NAME)
    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.PROJECT_NAME, A.PRODUCT_GROUP_NAME
    FROM SCM_MST_PROJECT A
    JOIN (
        SELECT PROJECT_CODE, MAX(PROJECT_VER_SEQ) AS SEQ
        FROM SCM_MST_PROJECT
        WHERE DIVISION_ID = p_division_id
        GROUP BY PROJECT_CODE
    ) B ON A.PROJECT_CODE = B.PROJECT_CODE AND A.PROJECT_VER_SEQ = B.SEQ
    WHERE A.DIVISION_ID = p_division_id;

    -- 단계1. 데이터 쿼리 ########################################################
    /* ── GT_DMF0049_T 적재 (#temp) ── */
    INSERT INTO SCM_MGR.GT_DMF0049_T
         ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID
         , T_DEPARTMENT_ID, T_DEPARTMENT_NAME, DEPT_ID, T_DEPT_ID, T_DEPT_NAME
         , END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID
         , ITEM_ID, NICK_NAME, MEASURE, PLANT_SITE_ID, COMPANY_ID
         , YYYYMM, CURRENCY, QTY, EDIT_FLAG, APP
         , SOLDTO_CUST_REPORT, DMS_CUSTOMER, BIZ_TYPE, APPLICATION_GR, PRODUCT_DETAILS
         , DISPLAY_SEQ1, DISPLAY_SEQ2, COUNTRY_CODE, SOLDTO_CODE, CELL_PER_CAR
         , CELL_NAME, FCST_TYPE, DATA_SEQ, INCOTERMS, ITEM_USE
         , MODEL_TYPE, MODULE_PER_CAR, PROJECT_NAME, SOLDTO_COUNTRY, SHIPTO_COUNTRY
         , END_CUSTOMER, CELL_MODEL, CELL_MODEL_INFO )
    SELECT
        R.DIVISION_ID
        , R.VERSION_NO
        , R.CUTOFF_TYPE
        , R.CUTOFF_YYYYMMDD
        , R.DEPARTMENT_ID
        , R.DEPARTMENT_ID AS T_DEPARTMENT_ID
        , CASE WHEN R.DEPARTMENT_NAME IS NOT NULL THEN R.DEPARTMENT_NAME ELSE LK1.SEGMENT2 END AS T_DEPARTMENT_NAME
        , R.DEPT_ID
        , R.DEPT_ID AS T_DEPT_ID
        , CASE WHEN R.DEPT_NAME IS NOT NULL THEN R.DEPT_NAME ELSE LK2.SEGMENT2 END AS T_DEPT_NAME
        , R.END_CUST_REPORT
        , R.CUST_REPORT
        , R.PRODUCT_GROUP
        , R.PROJECT_CODE
        , R.SCM_SITE_ID
        , R.ITEM_ID
        , SINGLE.NICK_NAME
        , R.MEASURE
        , R.PLANT_SITE_ID
        , R.COMPANY_ID
        , 'M_' || SUBSTR(R.YYYYMMDD, 1, 6) AS YYYYMM
        , R.CURRENCY
        , SUM(R.QTY) AS QTY
        , CASE WHEN (V_GROUP_ID = 'ADMIN') THEN 'Y' ELSE 'N' END AS EDIT_FLAG
        , R.APPLICATION AS APP
        , R.SOLDTO_CUST_REPORT
        , NVL(SI.ATTRIBUTE2,'') AS DMS_CUSTOMER
        , R.BIZ_TYPE AS BIZ_TYPE
        , R.APPLICATION_GR AS APPLICATION_GR
        , R.PRODUCT_DETAILS AS PRODUCT_DETAILS
        , LK1.DISPLAY_SEQ AS DISPLAY_SEQ1
        , LK2.DISPLAY_SEQ AS DISPLAY_SEQ2
        , R.COUNTRY_CODE
        , R.SOLDTO_CODE
        , SI.CELL_PER_CAR
        , '' AS CELL_NAME
        , R.FCST_TYPE
        , R.DATA_SEQ
        , R.INCOTERMS
        , NVL(R.ITEM_USE,'') AS ITEM_USE
        , ITEM_V.ITEM_CLASS_NAME AS MODEL_TYPE
        , CASE WHEN SI.CELL_PER_MODULE <> 0 THEN SI.CELL_PER_CAR / SI.CELL_PER_MODULE END AS MODULE_PER_CAR
        , LK3.SEGMENT3 AS PROJECT_NAME
        , NVL(R.SOLDTO_COUNTRY,'') AS SOLDTO_COUNTRY
        , NVL(R.SHIPTO_COUNTRY,'') AS SHIPTO_COUNTRY
        , NVL(R.END_CUSTOMER,'') AS END_CUSTOMER
        , NVL(R.ATTRIBUTE3,'') AS CELL_MODEL          --[C20211112-000213]
        , NVL(R.CELL_MODEL_INFO, '') AS CELL_MODEL_INFO --[C20211112-000213]
    FROM DM_PLN_SALES_ETC_REPORT_C R
    LEFT JOIN SCM_MST_SITE_ITEM SI
        ON R.DIVISION_ID = SI.DIVISION_ID
            AND R.PROJECT_CODE = SI.PROJECT_CODE
            AND R.SCM_SITE_ID = SI.SCM_SITE_ID
            AND R.ITEM_ID = SI.ITEM_ID
    LEFT JOIN DM_MST_ITEM_SINGLE_V SINGLE
        ON SI.DIVISION_ID = SINGLE.DIVISION_ID
            AND SI.ITEM_ID = SINGLE.ITEM_ID
    LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK1 ON R.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT' || CASE WHEN R.DIVISION_ID = '40' THEN '' ELSE '_' || R.DIVISION_ID END
    LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK2 ON R.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0049_DEPARTMENT_TEAM2' || CASE WHEN R.DIVISION_ID = '40' THEN '' ELSE '_' || R.DIVISION_ID END
    LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL LK3 ON R.PROJECT_CODE = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_ETC_PROJECT' AND LK3.SEGMENT1 = R.DIVISION_ID
    LEFT OUTER JOIN SCM_MST_SITE ST ON R.SCM_SITE_ID = ST.SCM_SITE_ID AND R.DIVISION_ID = ST.DIVISION_ID
    LEFT OUTER JOIN SCM_MST_COUNTRY CO ON ST.COUNTRY = CO.COUNTRY
    LEFT OUTER JOIN SCM_MST_SITE_CUSTOMER CS ON R.DIVISION_ID = CS.DIVISION_ID AND R.SCM_SITE_ID = CS.SCM_SITE_ID AND CS.REP_YN = 'Y' AND CS.VALID_YN = 'Y'
    LEFT OUTER JOIN SCM_MGR.GT_DMF0049_PJT PJT ON R.DIVISION_ID = PJT.DIVISION_ID AND R.PROJECT_CODE = PJT.PROJECT_CODE
    LEFT OUTER JOIN DM_MST_ITEM_SINGLE_V ITEM_V ON R.DIVISION_ID = ITEM_V.DIVISION_ID AND R.ITEM_ID = ITEM_V.ITEM_ID
    WHERE R.DIVISION_ID = p_division_id
        AND R.CUTOFF_TYPE = p_mdf_type
        AND SUBSTR(R.YYYYMMDD, 1, 4) = p_yyyy
        AND R.VERSION_NO = p_sp_version_no
    GROUP BY
        R.DIVISION_ID
        , R.VERSION_NO
        , R.CUTOFF_TYPE
        , R.CUTOFF_YYYYMMDD
        , R.DEPARTMENT_ID
        , R.DEPT_ID
        , R.END_CUST_REPORT
        , R.CUST_REPORT
        , R.PRODUCT_GROUP
        , R.PROJECT_CODE
        , R.SCM_SITE_ID
        , R.ITEM_ID
        , SINGLE.NICK_NAME
        , R.MEASURE
        , R.PLANT_SITE_ID
        , R.COMPANY_ID
        , SUBSTR(R.YYYYMMDD, 1, 6)
        , R.CURRENCY
        , R.APPLICATION
        , R.SOLDTO_CUST_REPORT
        , NVL(SI.ATTRIBUTE2,'')
        , R.BIZ_TYPE
        , R.APPLICATION_GR
        , R.PRODUCT_DETAILS
        , LK1.DISPLAY_SEQ
        , LK2.DISPLAY_SEQ
        , R.COUNTRY_CODE
        , R.SOLDTO_CODE
        , SI.CELL_PER_CAR
        , R.FCST_TYPE
        , R.DATA_SEQ
        , R.INCOTERMS
        , SUBSTR(R.PROJECT_CODE, 1, 1)
        , ITEM_V.ITEM_CLASS_NAME
        , CASE WHEN SI.CELL_PER_MODULE <> 0 THEN SI.CELL_PER_CAR / SI.CELL_PER_MODULE END
        , LK3.SEGMENT3
        , NVL(R.SOLDTO_COUNTRY, '')
        , NVL(R.SHIPTO_COUNTRY, '')
        , NVL(R.END_CUSTOMER, '')
        , NVL(R.ITEM_USE, '')
        , NVL(R.ATTRIBUTE3,'')          --[C20211112-000213]
        , NVL(R.CELL_MODEL_INFO, '')    --[C20211112-000213]
        , CASE WHEN R.DEPT_NAME IS NOT NULL THEN R.DEPT_NAME ELSE LK2.SEGMENT2 END
        , CASE WHEN R.DEPARTMENT_NAME IS NOT NULL THEN R.DEPARTMENT_NAME ELSE LK1.SEGMENT2 END;

    -- 단계3. PIVOT 기간 쿼리 ########################################################
    V_PROD := '';
    V_COLS := '';
    FOR rec IN (
        SELECT DISTINCT BASIS_YYYYMM
        FROM SCM_SYS_CALENDAR_M
        WHERE CALENDAR_YYYY = p_yyyy
        ORDER BY BASIS_YYYYMM
    )
    LOOP
        V_PROD := V_PROD || '''M_' || rec.BASIS_YYYYMM || ''' AS "M_' || rec.BASIS_YYYYMM || '",';
        V_COLS := V_COLS || '"M_' || rec.BASIS_YYYYMM || '",';
    END LOOP;

    IF V_PROD IS NOT NULL AND LENGTH(V_PROD) > 0 THEN
        V_PROD := RTRIM(V_PROD, ',');
        V_COLS := RTRIM(V_COLS, ',');
    END IF;

    -- 단계4. 실행 쿼리 ########################################################
    V_SQL :=
       'SELECT DIVISION_ID, VERSION_NO, DEPARTMENT_ID, T_DEPARTMENT_ID, T_DEPARTMENT_NAME, DEPT_ID, T_DEPT_ID, T_DEPT_NAME'
    || ', NVL(END_CUST_REPORT, '''') AS END_CUST_REPORT, CUST_REPORT, PRODUCT_GROUP, PROJECT_CODE, SCM_SITE_ID, ITEM_ID'
    || ', NVL(NICK_NAME, '''') AS NICK_NAME, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, COMPANY_ID, CURRENCY'
    || ', NVL(APP, '''') AS APPLICATION, EDIT_FLAG, SOLDTO_CUST_REPORT, BIZ_TYPE, APPLICATION_GR, PRODUCT_DETAILS'
    || ', CELL_MODEL_INFO, CELL_MODEL, COUNTRY_CODE, SOLDTO_CODE, CELL_PER_CAR, CELL_NAME, DATA_SEQ, FCST_TYPE, INCOTERMS'
    || ', ITEM_USE, MODEL_TYPE, MODULE_PER_CAR, PROJECT_NAME, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER'
    || CASE WHEN V_COLS IS NOT NULL AND LENGTH(V_COLS) > 0 THEN ', ' || V_COLS ELSE '' END
    -- || ' FROM ( SELECT A.* FROM SCM_MGR.GT_DMF0049_T A'   --*[2026-09-21] POJ 원본
    -- [2026-09-21 / POJ] 메저 팝업 순번을 PIVOT 밖으로 꺼낸다
    || ' FROM ( SELECT A.*, B.SORT_ORDER_NO FROM SCM_MGR.GT_DMF0049_T A'
    || ' JOIN SCM_MGR.GT_DMF0049_SELECT_MEASURE B ON A.MEASURE = B.MEASURE'
    || ' INNER JOIN ( SELECT * FROM SCM_ADM_USER_MNU_EDIT_AUTH_V WHERE USER_ID = ''' || p_user_id || ''' AND MNU_ID = ''' || p_menu_id || ''' AND UNIT_TP_CD = ''D'' ) T2 ON A.DIVISION_ID = T2.UNIT_ID'
    || ' ) T'
    || ' PIVOT ( SUM(QTY) FOR YYYYMM IN ( ' || V_PROD || ' ) ) PVT'
    || ' ORDER BY DIVISION_ID, VERSION_NO, DISPLAY_SEQ1, DISPLAY_SEQ2, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT'
    || ', PRODUCT_GROUP, ITEM_ID, NICK_NAME, PRODUCT_DETAILS, CELL_MODEL_INFO, CELL_MODEL, CURRENCY, COMPANY_ID, BIZ_TYPE, APPLICATION_GR, NVL(APP, ''''), COUNTRY_CODE, DATA_SEQ'
    -- || ', CASE WHEN MEASURE IN (''LOC'') THEN 1 WHEN MEASURE IN (''RTF'',''Business_Plan'') THEN 2 WHEN MEASURE IN (''SalesAmt_LOC'') THEN 3 WHEN MEASURE IN (''SalesAmt_KRW'') THEN 4 ELSE 5 END'   --*[2026-09-21] POJ 원본
    -- [2026-09-21 / POJ] 메저 정렬을 고정 식에서 팝업 순번으로 바꾼다
    || ', SORT_ORDER_NO'
    || ', END_CUSTOMER';

    OPEN O_RC1 FOR V_SQL;

    /* ── COMMIT (종료 직전 1회) ── */
    COMMIT;

    /* ── 프로시저 처리 결과 반환 (O_RESULT_CURSOR) — 조회+DML 성공 ── */
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'p_division_id'   VALUE p_division_id,
            'p_mdf_type'      VALUE p_mdf_type,
            'p_yyyy'          VALUE p_yyyy,
            'p_sp_version_no' VALUE p_sp_version_no,
            'p_user_group'    VALUE p_user_group,
            'p_created_by'    VALUE p_created_by,
            'p_user_id'       VALUE p_user_id,
            'p_menu_id'       VALUE p_menu_id
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;
        RAISE_APPLICATION_ERROR(-20001,
          '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0049_GET_SALES_ETC_REPORTS_DATA;


  PROCEDURE P_DMF0049_SAVE_SALES_ETC_REPORT_C 
(
      p_active_flag           IN VARCHAR2
    , p_result_month          IN VARCHAR2
    , p_division_id           IN VARCHAR2
    , p_version_no            IN VARCHAR2
    , p_data_seq              IN VARCHAR2
    , p_department_id         IN VARCHAR2
    , p_department_edit_flag  IN VARCHAR2
    , p_department_name       IN VARCHAR2
    , p_dept_id               IN VARCHAR2
    , p_cust_report           IN VARCHAR2
    , p_end_cust_report       IN VARCHAR2
    , p_soldto_code           IN VARCHAR2
    , p_soldto_cust_report    IN VARCHAR2
    , p_product_group         IN VARCHAR2
    , p_item_id               IN VARCHAR2
    , p_product_details       IN VARCHAR2
    , p_currency              IN VARCHAR2
    , p_company_id            IN VARCHAR2
    , p_biz_type              IN VARCHAR2
    , p_application_gr        IN VARCHAR2
    , p_application           IN VARCHAR2
    , p_country_code          IN VARCHAR2
    , p_project_code          IN VARCHAR2
    , p_scm_site_id           IN VARCHAR2
    , p_fcst_type             IN VARCHAR2
    , p_item_use              IN VARCHAR2
    , p_soldto_country        IN VARCHAR2
    , p_shipto_country        IN VARCHAR2
    , p_end_customer          IN VARCHAR2
    , p_etc_descr             IN VARCHAR2
    , p_cell_model_info       IN VARCHAR2   --[C20210125-000207] 40사업부 CELL_MODEL_INFO 컬럼 추가
    , p_cell_model            IN VARCHAR2   --[C20211112-000213]
    , p_measure               IN VARCHAR2
    , p_yyyymmdd              IN VARCHAR2
    , p_qty                   IN VARCHAR2
    , p_created_by            IN VARCHAR2
    , O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
/*
 * Program ID   : DMF0049_SAVE_SALES_ETC_REPORT_C
 * Description  : 'DM_PLN_SALES_ETC_REPORT_C' TABLE INSERT/UPDATE/DELETE
 * Program History
 *========================================================================================================================
 * 2020/04/08	HWI1993		Initial Release
 * 2020/05/22	hwi1993		Save 이후에 Transfer 처리
 * 2020/09/09   P.C.I		[C20200909-000203] LOG 표준화 적용
 * 2021/01/26   P.C.I		[C20210125-000207] 40사업부 RTF Measure, CELL_MODEL_INFO 컬럼 추가
 * 2021/08/16	hwi1993		[C20210811-000341] ETC Report - GDW 전송시 누락 컬럼 점검
 * 2022/01/14	rosia27		[C20220105-000064]ETC Report 구버전 조회시 조직 명칭 오류의 건
 * 2022/01/21	rosia27		[C20211112-000213]GSCM의 Cell Model 컬럼 관련 요청의 건
 * 2025/05/09	JSSBAE		[E20250418-001567]_40사업부 Sales Report, ETC Report 개선
 * 2025/07/21	JSSBAE		[E20250522-001188]_Business Plan UI 데이터 저장 시 Trim 처리
 * 2026/02/03	JSSBAE		[E20260107-001542]_DM_COMPANY 룩업코드 로직 개선
 * 2026/06/05	NextSCM Migration	[PJ202650304] 기존 배포본(미완성 자동변환, INVALID) 전면 재변환. ^구분 WHILE파싱→행생성기 분리 INSERT(빈필드 보존), #temp→GTT(GT_DMF0049_RESULTS_MST/_PRICE/_TEMP_ITEM_SINGLE), GOTO ERR_RTN→구조화 조기 RETURN, UPDATE..FROM/DELETE..JOIN→MERGE/상관서브쿼리/EXISTS, NEXT VALUE FOR SEQ1_DM_PLN_SALES_ETC_REPORT_H 시퀀스 신설, GETDATE→SYSDATE, QTY 문자열↔TO_NUMBER, 로깅(PR_DM_SYS_LOG_BATCH)/EXCEPTION/O_RESULT_CURSOR 표준
 */
IS
    V_PROGRAM_NAME      VARCHAR2(200 CHAR) := 'DMF0049_SAVE_SALES_ETC_REPORT_C';
    V_LOG_TYPE          VARCHAR2(100 CHAR);
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(4000 CHAR);
    V_LOG_DESCRIPTION   VARCHAR2(4000 CHAR);
    D_EVENT_DATE        DATE := SYSDATE;
    n_delete_count      PLS_INTEGER := 0;
    n_insert_count      PLS_INTEGER := 0;
    n_input_count       PLS_INTEGER := 0;

    v_log_user          VARCHAR2(150 CHAR);
    v_division_id       VARCHAR2(4000 CHAR);
    v_version_no        VARCHAR2(4000 CHAR);
    v_result_month      VARCHAR2(4000 CHAR);
    v_cutoff_yyyymmdd   VARCHAR2(8 CHAR);
    v_cutoff_type       VARCHAR2(20 CHAR);
    v_max_seq           NUMBER := 0;
    v_etc_department_id   VARCHAR2(30 CHAR);
    v_etc_department_name VARCHAR2(100 CHAR);
    v_chk               PLS_INTEGER := 0;
    v_dup_msg           VARCHAR2(2000 CHAR);

    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);

    PROCEDURE LOG_END IS
    BEGIN
        V_LOG_TYPE        := 'END';
        V_LOG_MESSAGE     := '########## END of procedure ##########';
        V_LOG_DESCRIPTION := 'input_count: ' || TO_CHAR(n_input_count);
        D_EVENT_DATE      := SYSDATE;
        SCM_MGR.PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, v_log_user);
    END LOG_END;

BEGIN
    --[E20260812-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어 (2026-08-06 표준, 2026-08-12 DMF0044/0049 일괄 적용)
    EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';
    -- 로그 사용자 (p_created_by 의 첫 '^' 토큰)
    IF INSTR(p_created_by, '^') > 1 THEN
        v_log_user := SUBSTR(p_created_by, 1, INSTR(p_created_by, '^') - 1);
    ELSE
        v_log_user := p_created_by;
    END IF;

    -- 시작 LOG  (START)
    V_LOG_TYPE        := 'START';
    V_LOG_MESSAGE     := '########## Start of procedure @@@##########';
    V_LOG_DESCRIPTION := '';
    D_EVENT_DATE      := SYSDATE;
    SCM_MGR.PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, v_log_user);
    V_LOG_MESSAGE := NULL;

    -- GTT 초기화
    DELETE FROM SCM_MGR.GT_DMF0049_RESULTS_MST;
    DELETE FROM SCM_MGR.GT_DMF0049_RESULTS_MST_PRICE;
    DELETE FROM SCM_MGR.GT_DMF0049_TEMP_ITEM_SINGLE;

    -----------------------------------------------------------------------------------------------------------------------
    -- ^ 구분 입력 파싱 → #results_MST (원본 WHILE 루프 대체: 행 생성기 + 위치 기반 분리, 빈 필드 보존)
    -----------------------------------------------------------------------------------------------------------------------
    INSERT INTO SCM_MGR.GT_DMF0049_RESULTS_MST
        ( ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
        , DEPARTMENT_ID, DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME, DEPT_ID, CUST_REPORT
        , END_CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID
        , PRODUCT_DETAILS, CURRENCY, COMPANY_ID, BIZ_TYPE, APPLICATION_GR
        , APPLICATION, COUNTRY_CODE, PROJECT_CODE, SCM_SITE_ID, CELL_MODEL_INFO
        , CELL_MODEL, FCST_TYPE, MEASURE, YYYYMMDD, QTY
        , CREATED_BY, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER )
    SELECT TRIM(REGEXP_SUBSTR(RTRIM(p_active_flag)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_result_month)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_division_id)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_version_no)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_data_seq)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_department_id)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_department_edit_flag)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_department_name)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_dept_id)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_cust_report)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_end_cust_report)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_soldto_code)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_soldto_cust_report)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_product_group)||'^','(.*?)\^',1,n,NULL,1))
         , REPLACE(REPLACE(REPLACE(REPLACE(TRIM(REGEXP_SUBSTR(RTRIM(p_item_id)||'^','(.*?)\^',1,n,NULL,1)),CHR(13),''),CHR(10),''),CHR(9),''),' ','')
         , TRIM(REGEXP_SUBSTR(RTRIM(p_product_details)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_currency)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_company_id)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_biz_type)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_application_gr)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_application)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_country_code)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_project_code)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_scm_site_id)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_cell_model_info)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_cell_model)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_fcst_type)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_measure)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_yyyymmdd)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_qty)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_created_by)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_item_use)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_soldto_country)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_shipto_country)||'^','(.*?)\^',1,n,NULL,1))
         , TRIM(REGEXP_SUBSTR(RTRIM(p_end_customer)||'^','(.*?)\^',1,n,NULL,1))
    FROM ( SELECT LEVEL AS n FROM DUAL
           CONNECT BY LEVEL <= REGEXP_COUNT(RTRIM(p_division_id)||'^','\^') );

    -----------------------------------------------------------------------------------------------------------------------
    -- [E20260107-001542]_DM_COMPANY 룩업코드 검증 (구코드 COMPANY_ID 저장 불가)
    -----------------------------------------------------------------------------------------------------------------------
    -- [E20261006-ASISPARITY] 구코드 COMPANY_ID 검증 비활성 — AS-IS 운영 일치 — 운영 미배포 개발 SR [E20260107-001542] 잔존
--[E20261006-ASISPARITY]     SELECT COUNT(*) INTO v_chk FROM SCM_MGR.GT_DMF0049_RESULTS_MST R
--[E20261006-ASISPARITY]      WHERE R.COMPANY_ID IN ( SELECT OLD_VALUE1 FROM NERP_CONV_MASTER WHERE CODETYPE = 'COMPANY_ID' GROUP BY OLD_VALUE1 )
--[E20261006-ASISPARITY]        AND ROWNUM = 1;
--[E20261006-ASISPARITY]     IF v_chk > 0 THEN
--[E20261006-ASISPARITY]         ROLLBACK;
--[E20261006-ASISPARITY]         V_LOG_TYPE := 'INVALID'; V_LOG_MESSAGE := '구코드 COMPANY_ID는 저장할 수 없습니다.'; V_LOG_DESCRIPTION := ''; D_EVENT_DATE := SYSDATE;
--[E20261006-ASISPARITY]         SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE);
--[E20261006-ASISPARITY]         LOG_END;
--[E20261006-ASISPARITY]         OPEN O_RESULT_CURSOR FOR SELECT '구코드 COMPANY_ID는 저장할 수 없습니다.' AS MSG FROM DUAL;
--[E20261006-ASISPARITY]         RETURN;
--[E20261006-ASISPARITY]     END IF;

    -----------------------------------------------------------------------------------------------------------------------
    -- 가공처리
    -----------------------------------------------------------------------------------------------------------------------
    -- 수량 공백 → 0
    UPDATE SCM_MGR.GT_DMF0049_RESULTS_MST SET QTY = '0' WHERE QTY IS NULL;

    --[E20260828-SARGSWEEP] DIVISION_ID = NOT NULL 규약 — 공백은 적재 시점에 초기값 '-' 로 정규화하고
    --  WHERE/JOIN 의 NVL(DIVISION_ID,'-') 은 제거한다 (사용자 지시 2026-08-28).
    UPDATE SCM_MGR.GT_DMF0049_RESULTS_MST SET DIVISION_ID = '/' WHERE DIVISION_ID IS NULL;

    --[C20210125-000207] 40사업부 RTF Measure 없으면 Row 삭제
    --[E20260930-DMF0049SETFULL] 비활성 (사용자 지시 2026-09-30 — RTF_SYS_RP 0 행도 세트로 저장) : DELETE FROM SCM_MGR.GT_DMF0049_RESULTS_MST
    --[E20260930-DMF0049SETFULL] 비활성 : WHERE DIVISION_ID = '40' AND MEASURE = 'RTF_SYS_RP' AND ACTIVE_FLAG = 'I' AND QTY = '0';

    UPDATE SCM_MGR.GT_DMF0049_RESULTS_MST
    SET QTY = TO_CHAR(ROUND(TO_NUMBER(QTY), 3))
    WHERE DIVISION_ID = '40' AND MEASURE = 'RTF_SYS_RP';

    /*[E20260930-DMF0049SETFULL2] 메저 세트 보충 (2차 — 1차 [E20260930-DMF0049SETFULL] 블록 교체) — 사용자 지시 2026-09-30 "Insert 시 3개 ROW 가 생성되고 값을 1개 ROW 에만
       입력해도 3개 ROW 가 항상 같이 저장". 세트 판정 = PK 축(VERSION·DIVISION·DATA_SEQ) + INSERT 경로 DATA_SEQ 채번 키(DENSE_RANK 19컬럼) + 월.
       1차는 식별 33컬럼 전부 동일을 요구해 세트 행 간 비-키 컬럼(부서명·편집플래그·FCST_TYPE 등)이 다르면 같은 (DATA_SEQ, MEASURE, 월) 보충 행이
       두 벌 생겨 클라우드 ORA-00001(2026-09-30 19:41) — 비-키 컬럼은 그룹 MAX 대표값. division 메저 목록 = P_DMF0049_GET_MEASURE 와 같은 원천·INSTR.
       원장에 그 세트·월·메저가 이미 있으면 보충하지 않는다(수정 경로 실제 값 보존). 위 [C20210125-000207] RTF_SYS_RP 0 행 삭제는 1차와 같이 비활성. */
    INSERT INTO SCM_MGR.GT_DMF0049_RESULTS_MST
        ( VERSION_NO, DIVISION_ID, DATA_SEQ, DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE, SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY, COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, YYYYMMDD, ACTIVE_FLAG, RESULT_MONTH, DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME, PROJECT_CODE, SCM_SITE_ID, CELL_MODEL_INFO, CELL_MODEL, FCST_TYPE, CREATED_BY
        , MEASURE, QTY )
    SELECT S.VERSION_NO, S.DIVISION_ID, S.DATA_SEQ, S.DEPARTMENT_ID, S.DEPT_ID, S.CUST_REPORT, S.END_CUST_REPORT, S.SOLDTO_CODE, S.SOLDTO_CUST_REPORT, S.PRODUCT_GROUP, S.ITEM_ID, S.PRODUCT_DETAILS, S.CURRENCY, S.COMPANY_ID, S.BIZ_TYPE, S.APPLICATION_GR, S.APPLICATION, S.COUNTRY_CODE, S.ITEM_USE, S.SOLDTO_COUNTRY, S.SHIPTO_COUNTRY, S.END_CUSTOMER, S.YYYYMMDD, S.ACTIVE_FLAG, S.RESULT_MONTH, S.DEPARTMENT_EDIT_FLAG, S.T_DEPARTMENT_NAME, S.PROJECT_CODE, S.SCM_SITE_ID, S.CELL_MODEL_INFO, S.CELL_MODEL, S.FCST_TYPE, S.CREATED_BY
         , M.COLUMN_NAME, '0'
      FROM ( SELECT B.VERSION_NO, B.DIVISION_ID, B.DATA_SEQ, B.DEPARTMENT_ID, B.DEPT_ID, B.CUST_REPORT, B.END_CUST_REPORT, B.SOLDTO_CODE, B.SOLDTO_CUST_REPORT, B.PRODUCT_GROUP, B.ITEM_ID, B.PRODUCT_DETAILS, B.CURRENCY, B.COMPANY_ID, B.BIZ_TYPE, B.APPLICATION_GR, B.APPLICATION, B.COUNTRY_CODE, B.ITEM_USE, B.SOLDTO_COUNTRY, B.SHIPTO_COUNTRY, B.END_CUSTOMER, B.YYYYMMDD, MAX(B.ACTIVE_FLAG) AS ACTIVE_FLAG, MAX(B.RESULT_MONTH) AS RESULT_MONTH, MAX(B.DEPARTMENT_EDIT_FLAG) AS DEPARTMENT_EDIT_FLAG, MAX(B.T_DEPARTMENT_NAME) AS T_DEPARTMENT_NAME, MAX(B.PROJECT_CODE) AS PROJECT_CODE, MAX(B.SCM_SITE_ID) AS SCM_SITE_ID, MAX(B.CELL_MODEL_INFO) AS CELL_MODEL_INFO, MAX(B.CELL_MODEL) AS CELL_MODEL, MAX(B.FCST_TYPE) AS FCST_TYPE, MAX(B.CREATED_BY) AS CREATED_BY
               FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
              WHERE NVL(B.ACTIVE_FLAG, '/') <> 'D'
              GROUP BY B.VERSION_NO, B.DIVISION_ID, B.DATA_SEQ, B.DEPARTMENT_ID, B.DEPT_ID, B.CUST_REPORT, B.END_CUST_REPORT, B.SOLDTO_CODE, B.SOLDTO_CUST_REPORT, B.PRODUCT_GROUP, B.ITEM_ID, B.PRODUCT_DETAILS, B.CURRENCY, B.COMPANY_ID, B.BIZ_TYPE, B.APPLICATION_GR, B.APPLICATION, B.COUNTRY_CODE, B.ITEM_USE, B.SOLDTO_COUNTRY, B.SHIPTO_COUNTRY, B.END_CUSTOMER, B.YYYYMMDD ) S
      JOIN SCM_MST_SHEET_MEASURE M
        ON M.PROGRAM_ID = 'DMF0049'
       AND M.SHEET_NAME IN ( 'MDF Reports', 'mdfReports' )
       AND M.COLUMN_NAME IN ('SalesAmt_KRW', 'SalesAmt_LOC', 'RTF_SYS_RP')
       AND M.VALID_YN = 'Y'
       AND INSTR(M.DIVISION_ID, S.DIVISION_ID) > 0
     WHERE NOT EXISTS ( SELECT 1 FROM SCM_MGR.GT_DMF0049_RESULTS_MST C
                         WHERE C.MEASURE = M.COLUMN_NAME
                           AND NVL(C.ACTIVE_FLAG, '/') <> 'D'
                         AND DECODE(C.VERSION_NO, S.VERSION_NO, 1, 0) = 1
                         AND DECODE(C.DIVISION_ID, S.DIVISION_ID, 1, 0) = 1
                         AND DECODE(C.DATA_SEQ, S.DATA_SEQ, 1, 0) = 1
                         AND DECODE(C.DEPARTMENT_ID, S.DEPARTMENT_ID, 1, 0) = 1
                         AND DECODE(C.DEPT_ID, S.DEPT_ID, 1, 0) = 1
                         AND DECODE(C.CUST_REPORT, S.CUST_REPORT, 1, 0) = 1
                         AND DECODE(C.END_CUST_REPORT, S.END_CUST_REPORT, 1, 0) = 1
                         AND DECODE(C.SOLDTO_CODE, S.SOLDTO_CODE, 1, 0) = 1
                         AND DECODE(C.SOLDTO_CUST_REPORT, S.SOLDTO_CUST_REPORT, 1, 0) = 1
                         AND DECODE(C.PRODUCT_GROUP, S.PRODUCT_GROUP, 1, 0) = 1
                         AND DECODE(C.ITEM_ID, S.ITEM_ID, 1, 0) = 1
                         AND DECODE(C.PRODUCT_DETAILS, S.PRODUCT_DETAILS, 1, 0) = 1
                         AND DECODE(C.CURRENCY, S.CURRENCY, 1, 0) = 1
                         AND DECODE(C.COMPANY_ID, S.COMPANY_ID, 1, 0) = 1
                         AND DECODE(C.BIZ_TYPE, S.BIZ_TYPE, 1, 0) = 1
                         AND DECODE(C.APPLICATION_GR, S.APPLICATION_GR, 1, 0) = 1
                         AND DECODE(C.APPLICATION, S.APPLICATION, 1, 0) = 1
                         AND DECODE(C.COUNTRY_CODE, S.COUNTRY_CODE, 1, 0) = 1
                         AND DECODE(C.ITEM_USE, S.ITEM_USE, 1, 0) = 1
                         AND DECODE(C.SOLDTO_COUNTRY, S.SOLDTO_COUNTRY, 1, 0) = 1
                         AND DECODE(C.SHIPTO_COUNTRY, S.SHIPTO_COUNTRY, 1, 0) = 1
                         AND DECODE(C.END_CUSTOMER, S.END_CUSTOMER, 1, 0) = 1
                         AND DECODE(C.YYYYMMDD, S.YYYYMMDD, 1, 0) = 1 )
       -- 원장에 그 세트·월·메저가 이미 있으면 보충하지 않는다 (GTT YYYYMMDD 는 이 시점 yyyymm)
       AND NOT EXISTS ( SELECT 1 FROM DM_PLN_SALES_ETC_REPORT_C A
                         WHERE S.DATA_SEQ IS NOT NULL
                           AND A.VERSION_NO = S.VERSION_NO
                           AND A.DIVISION_ID = NVL(S.DIVISION_ID, '/')
                           AND TO_CHAR(A.DATA_SEQ) = S.DATA_SEQ
                           AND A.MEASURE = M.COLUMN_NAME
                           AND SUBSTR(A.YYYYMMDD, 1, 6) = SUBSTR(S.YYYYMMDD, 1, 6) );

    --Start [C20210125-000207] 40사업부 Unit Price Measure 추가
    INSERT INTO SCM_MGR.GT_DMF0049_RESULTS_MST_PRICE
        ( ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
        , DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE
        , SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY
        , COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE
        , PROJECT_CODE, SCM_SITE_ID, FCST_TYPE, CELL_MODEL_INFO, CELL_MODEL
        , MEASURE, YYYYMMDD, SALESAMT_LOC, RTF_SYS_RP, CREATED_BY
        , ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME )
    SELECT ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
         , DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE
         , SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY
         , COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE
         , PROJECT_CODE, SCM_SITE_ID, FCST_TYPE, CELL_MODEL_INFO, CELL_MODEL
         , 'LOC' AS MEASURE, YYYYMMDD
         , SUM(CASE WHEN MEASURE = 'SalesAmt_LOC' THEN ROUND(TO_NUMBER(QTY),3) ELSE 0.0 END) AS SALESAMT_LOC
         , SUM(CASE WHEN MEASURE = 'RTF_SYS_RP' THEN ROUND(TO_NUMBER(QTY),3) ELSE 0.0 END) AS RTF_SYS_RP
         , MAX(CREATED_BY) AS CREATED_BY, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER
         , DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME
    FROM SCM_MGR.GT_DMF0049_RESULTS_MST
    WHERE MEASURE IN ('SalesAmt_LOC','RTF_SYS_RP')
      AND DIVISION_ID = '40'
    GROUP BY ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
         , DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE
         , SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY
         , COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE
         , PROJECT_CODE, SCM_SITE_ID, FCST_TYPE, CELL_MODEL_INFO, CELL_MODEL
         , YYYYMMDD, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER
         , DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME;

    INSERT INTO SCM_MGR.GT_DMF0049_RESULTS_MST
        ( ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
        , DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE
        , SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY
        , COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE
        , PROJECT_CODE, SCM_SITE_ID, FCST_TYPE, CELL_MODEL_INFO, CELL_MODEL
        , MEASURE, YYYYMMDD, QTY, CREATED_BY, ITEM_USE
        , SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME )
    SELECT ACTIVE_FLAG, RESULT_MONTH, DIVISION_ID, VERSION_NO, DATA_SEQ
         , DEPARTMENT_ID, DEPT_ID, CUST_REPORT, END_CUST_REPORT, SOLDTO_CODE
         , SOLDTO_CUST_REPORT, PRODUCT_GROUP, ITEM_ID, PRODUCT_DETAILS, CURRENCY
         , COMPANY_ID, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE
         , PROJECT_CODE, SCM_SITE_ID, FCST_TYPE, CELL_MODEL_INFO, CELL_MODEL
         , MEASURE, YYYYMMDD
         , TO_CHAR(CASE WHEN NVL(RTF_SYS_RP, 0) = 0 THEN 0 ELSE SALESAMT_LOC / RTF_SYS_RP END) AS QTY
         , CREATED_BY, ITEM_USE
         , SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, DEPARTMENT_EDIT_FLAG, T_DEPARTMENT_NAME
    FROM SCM_MGR.GT_DMF0049_RESULTS_MST_PRICE
    WHERE NVL(RTF_SYS_RP, 0) != 0;
    --End [C20210125-000207]

    -- yyyymm 값을 월별 첫 영업일(yyyymmdd)로 변환
    UPDATE SCM_MGR.GT_DMF0049_RESULTS_MST A
    SET A.YYYYMMDD = ( SELECT MIN(BASIS_START_DATE) FROM SCM_SYS_CALENDAR_M C
                       WHERE SUBSTR(C.BASIS_YYYYMMDD,1,6) = SUBSTR(A.YYYYMMDD,1,6)
                       AND C.DAYOFWEEK IN ('MON','TUE','WED','THU','FRI') );

    -- 폼에서 result_month 는 실적 편집 시에만 넘김. division/version/result_month 대표값
    BEGIN
        SELECT DIVISION_ID, VERSION_NO, RESULT_MONTH
          INTO v_division_id, v_version_no, v_result_month
        FROM SCM_MGR.GT_DMF0049_RESULTS_MST WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_division_id := NULL; v_version_no := NULL; v_result_month := NULL;
    END;

    -----------------------------------------------------------------------------------------------------------------------
    --[E20250418-001567]_저장 시 VALIDATION (Sales Report 테이블 기준 중복 검증)
    -----------------------------------------------------------------------------------------------------------------------
    SELECT COUNT(*) INTO v_chk FROM (
        SELECT A.VERSION_NO
          FROM DM_PLN_SALES_ETC_REPORT_C A
          INNER JOIN SCM_MGR.GT_DMF0049_RESULTS_MST B
                  ON A.VERSION_NO = B.VERSION_NO
                 AND A.DIVISION_ID = B.DIVISION_ID
                 AND A.DEPARTMENT_ID = B.DEPARTMENT_ID
                 AND A.DEPT_ID = B.DEPT_ID
                 AND A.ITEM_ID = B.ITEM_ID
                 AND A.MEASURE = B.MEASURE
                 AND A.YYYYMMDD = B.YYYYMMDD
                 AND A.CURRENCY = B.CURRENCY
                 AND A.COMPANY_ID = B.COMPANY_ID
                 AND A.END_CUST_REPORT = B.END_CUST_REPORT
                 AND A.CUST_REPORT = B.CUST_REPORT
                 AND A.PRODUCT_GROUP = B.PRODUCT_GROUP
                 AND A.COUNTRY_CODE = B.COUNTRY_CODE
         WHERE A.DIVISION_ID = v_division_id
           AND A.VERSION_NO = v_version_no
           AND ( (B.ACTIVE_FLAG != 'D') OR (NVL(TO_NUMBER(B.QTY),0) > 0) )
         GROUP BY A.VERSION_NO, A.DIVISION_ID, A.DEPARTMENT_ID, A.DEPT_ID, A.ITEM_ID
                , A.MEASURE, A.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, A.END_CUST_REPORT
                , A.CUST_REPORT, A.PRODUCT_GROUP, SCM_MGR.FN_GET_COUNTRY_KR_NAME(A.COUNTRY_CODE)
        HAVING COUNT(*) > 1
    );
    IF v_chk > 0 THEN
        ROLLBACK;
        v_dup_msg := 'GDW에 데이터를 전송할때는 Sales Report에 ETC Report가 포함되어 전송됩니다. Sales Report 테이블 기준으로 중복되는 값이 발생했습니다.' || CHR(10)
                  || '데이터 저장 시 중복되지 않아야하는 값은' || CHR(10)
                  || 'Division, Department, Team, Model, Measure, YYYYMM, Currency, Company Id, End Cust.(Report), Cust. (Report), Product Gr.(Report), Country Name' || CHR(10)
                  || '저장하시려는 데이터를 다시 한번 확인하시기 바랍니다.';
        V_LOG_TYPE := 'DUPICATION_INVALID'; V_LOG_MESSAGE := '데이터 저장 시 중복값이 발생했습니다. '; V_LOG_DESCRIPTION := ''; D_EVENT_DATE := SYSDATE;
        SCM_MGR.PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESCRIPTION, D_EVENT_DATE, p_created_by);
        LOG_END;
        OPEN O_RESULT_CURSOR FOR SELECT v_dup_msg AS MSG FROM DUAL;
        RETURN;
    END IF;

    -- cutoff 정보
    BEGIN
        SELECT B.YYYYMMDD, A.VERSION_TYPE
          INTO v_cutoff_yyyymmdd, v_cutoff_type
        FROM DM_MDF_VERSION A
        JOIN DM_MST_VERSION B ON A.DIVISION_ID = B.DIVISION_ID AND A.ORI_CUTOFF_VERSION_NO = B.VERSION_NO
        WHERE A.VERSION_NO = v_version_no AND A.DIVISION_ID = v_division_id AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_cutoff_yyyymmdd := NULL; v_cutoff_type := NULL;
    END;

    -- INPUT COUNT 확인
    SELECT COUNT(ACTIVE_FLAG) INTO n_input_count FROM SCM_MGR.GT_DMF0049_RESULTS_MST;

    -----------------------------------------------------------------------------------------------------------------------
    -- DM_PLN_SALES_ETC_REPORT_C 테이블 DELETE (ACTIVE_FLAG='D')
    -----------------------------------------------------------------------------------------------------------------------
    DELETE FROM DM_PLN_SALES_ETC_REPORT_C A
    WHERE A.DIVISION_ID = v_division_id AND A.VERSION_NO = v_version_no --[E20260828-SARGSWEEP] PK 선두 직접 술어 — 상관 EXISTS 만으론 FULL SCAN (대표값=GTT ROWNUM=1, GTT 공백 시 양쪽 0행 등가)
      AND EXISTS ( SELECT 1 FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
                   WHERE A.VERSION_NO = B.VERSION_NO
                     AND A.DIVISION_ID = B.DIVISION_ID
                     AND TO_CHAR(A.DATA_SEQ) = B.DATA_SEQ
                     AND A.MEASURE = B.MEASURE
                     AND A.YYYYMMDD = B.YYYYMMDD
                     AND B.ACTIVE_FLAG = 'D' );
    n_delete_count := SQL%ROWCOUNT;

    -- 아래서 다시 ACTIVE_FLAG 를 사용하지 않도록 지운다.
    DELETE FROM SCM_MGR.GT_DMF0049_RESULTS_MST WHERE ACTIVE_FLAG = 'D';

    -----------------------------------------------------------------------------------------------------------------------
    -- DM_PLN_SALES_ETC_REPORT_C 테이블 UPDATE (수량만)
    -----------------------------------------------------------------------------------------------------------------------
    UPDATE DM_PLN_SALES_ETC_REPORT_C A
    SET A.QTY = ( SELECT MAX(TO_NUMBER(B.QTY)) FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
                  WHERE A.VERSION_NO = B.VERSION_NO AND A.DIVISION_ID = B.DIVISION_ID
                    AND TO_CHAR(A.DATA_SEQ) = B.DATA_SEQ AND A.MEASURE = B.MEASURE AND A.YYYYMMDD = B.YYYYMMDD )
    WHERE A.DIVISION_ID = v_division_id AND A.VERSION_NO = v_version_no --[E20260828-SARGSWEEP]
      AND EXISTS ( SELECT 1 FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
                   WHERE A.VERSION_NO = B.VERSION_NO AND A.DIVISION_ID = B.DIVISION_ID
                     AND TO_CHAR(A.DATA_SEQ) = B.DATA_SEQ AND A.MEASURE = B.MEASURE AND A.YYYYMMDD = B.YYYYMMDD );

    -- 2021.08.28 추가된 컬럼 적용
    INSERT INTO SCM_MGR.GT_DMF0049_TEMP_ITEM_SINGLE
        ( ITEM_ID, ITEM_CLASS_NAME, ENERGY, CELL_QUANTITY, FORECAST_INFO_BIZ_TYPE
        , FORECAST_INFO_SPEC, NICK_NAME, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT )
    SELECT DISTINCT ITEM_ID, ITEM_CLASS_NAME
         , CASE WHEN REGEXP_LIKE(ENERGE, '^\d+\.?\d*$') THEN TO_NUMBER(ENERGE) ELSE 0 END AS ENERGY
         , CASE WHEN REGEXP_LIKE(CELL_QUANTITY, '^\d+\.?\d*$') THEN TO_NUMBER(CELL_QUANTITY) ELSE 0 END AS CELL_QUANTITY
         , FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_SPEC, NICK_NAME, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT
    FROM DM_MST_ITEM_SINGLE_V
    WHERE DIVISION_ID = v_division_id;  --[E20260820-DIVIDSCALAR] p_division_id 는 '^' 벌크 원문 → 2행 이상 payload 에서 항상 0행(부가정보 NULL 덮어쓰기). 파싱 대표값 사용

    -- 1~3 담당 외 기타 부서코드
    BEGIN
        SELECT SEGMENT1, SEGMENT2 INTO v_etc_department_id, v_etc_department_name
        FROM SCM_ADM_LOOKUP_MASTER_DETAIL
        WHERE LOOKUP_TYPE = 'MDF_DEPARTMENT' AND SEGMENT3 = 'Y' AND ATTRIBUTE1 = 'Y' AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN v_etc_department_id := NULL; v_etc_department_name := NULL;
    END;

    -- #results_MST 부가정보 갱신 (원본 UPDATE..FROM → 상관 서브쿼리)
    UPDATE SCM_MGR.GT_DMF0049_RESULTS_MST A
    SET A.OWNER_NAME = ( SELECT SCM_MGR.FN_GET_DM_MKT_OWNER_NAME(B.OWNER, ',', 'KO') FROM SCM_MST_SITE_ITEM B
                          WHERE A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND ROWNUM = 1 )
      , A.CUST_GROUP_DTL = ( SELECT B.CUST_GROUP_DTL FROM SCM_MST_SITE_ITEM B
                          WHERE A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND ROWNUM = 1 )
      , A.ROUTE = ( SELECT B.ROUTE FROM SCM_MST_SITE_ITEM B
                          WHERE A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND ROWNUM = 1 )
      , A.FORECAST_INFO_SPEC = ( SELECT C.FORECAST_INFO_SPEC FROM SCM_MGR.GT_DMF0049_TEMP_ITEM_SINGLE C WHERE A.ITEM_ID = C.ITEM_ID AND ROWNUM = 1 )
      , A.NICK_NAME = ( SELECT NVL((SELECT LK3.ATTRIBUTE1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK3
                                     WHERE A.DIVISION_ID = LK3.SEGMENT1 AND A.ITEM_ID = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_SR_ETC_MODEL' AND ROWNUM = 1),
                                    C.NICK_NAME) FROM SCM_MGR.GT_DMF0049_TEMP_ITEM_SINGLE C WHERE A.ITEM_ID = C.ITEM_ID AND ROWNUM = 1 )
      , A.FORECAST_INFO_CELL_PACK_COUNT = ( SELECT NVL((SELECT CASE WHEN REGEXP_LIKE(LK3.ATTRIBUTE2,'^\d+\.?\d*$') THEN LK3.ATTRIBUTE2 ELSE '0' END FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK3
                                     WHERE A.DIVISION_ID = LK3.SEGMENT1 AND A.ITEM_ID = LK3.SEGMENT2 AND LK3.LOOKUP_TYPE = 'DM_SR_ETC_MODEL' AND ROWNUM = 1),
                                    C.FORECAST_INFO_CELL_PACK_COUNT) FROM SCM_MGR.GT_DMF0049_TEMP_ITEM_SINGLE C WHERE A.ITEM_ID = C.ITEM_ID AND ROWNUM = 1 )
      , A.COMPANY_NAME = ( SELECT D.SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL D WHERE A.COMPANY_ID = D.SEGMENT1 AND D.LOOKUP_TYPE = 'DM_COMPANY' AND ROWNUM = 1 )
      , A.COUNTRY_KR_NAME = ( SELECT F.COUNTRY_KR_NAME FROM SCM_MST_COUNTRY F WHERE A.COUNTRY_CODE = F.COUNTRY AND ROWNUM = 1 )
      -- [E20261001-DEPTNAMEID] 부서명 = ID 기준 룩업 + NVL '-' (그리드에서 DEPARTMENT_NAME 제외 → EDIT_FLAG/화면 부서명 미전달)
      --   구 식은 DEPARTMENT_EDIT_FLAG/T_DEPARTMENT_NAME 의존 + 마지막 분기 '' (MSSQL 빈문자 → Oracle NULL) → NULL 저장
      --   → DMF0044/DMF0049 Transfer 'DEPARTMENT_NAME 정보가 존재하지 않아 저장할 수 없습니다.' 차단.
      --   DEPARTMENT_NAME ← DEPARTMENT_ID (MDF_DEPARTMENT[_div], SEGMENT3='Y') / DEPT_NAME ← DEPT_ID (DMF0044_DEPARTMENT_TEAM2[_div])
      --   40 + 담당 룩업 없음 = 기타 부서명 (버전 생성 P_DMF0044_SAVE_SALES_PLAN_VERSION_COPY 와 동일 규칙) / 값 없으면 '-'
      , A.DEPARTMENT_NAME = NVL( CASE WHEN v_division_id = '40'  /*[E20260820-DIVIDSCALAR]*/ AND NOT EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK1 WHERE A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT'||CASE WHEN A.DIVISION_ID='40' THEN '' ELSE '_'||A.DIVISION_ID END AND LK1.SEGMENT3='Y') THEN v_etc_department_name
                                      ELSE ( SELECT LK1.SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK1 WHERE A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT'||CASE WHEN A.DIVISION_ID='40' THEN '' ELSE '_'||A.DIVISION_ID END AND LK1.SEGMENT3='Y' AND ROWNUM=1 )
                                 END, '/')
      , A.DEPT_NAME = NVL( CASE WHEN v_division_id = '40'  /*[E20260820-DIVIDSCALAR]*/ AND NOT EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK1 WHERE A.DEPARTMENT_ID = LK1.SEGMENT1 AND LK1.LOOKUP_TYPE = 'MDF_DEPARTMENT'||CASE WHEN A.DIVISION_ID='40' THEN '' ELSE '_'||A.DIVISION_ID END AND LK1.SEGMENT3='Y') THEN v_etc_department_name
                                ELSE ( SELECT LK2.SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL LK2 WHERE A.DEPT_ID = LK2.SEGMENT1 AND LK2.LOOKUP_TYPE = 'DMF0044_DEPARTMENT_TEAM2'||CASE WHEN A.DIVISION_ID='40' THEN '' ELSE '_'||A.DIVISION_ID END AND ROWNUM=1 )
                           END, '/');

    -----------------------------------------------------------------------------------------------------------------------
    -- UPDATE 대상(DATA_SEQ 존재): 동일 년월/메저 삭제 후 인서트
    -----------------------------------------------------------------------------------------------------------------------
    SELECT COUNT(*) INTO v_chk FROM SCM_MGR.GT_DMF0049_RESULTS_MST WHERE DATA_SEQ IS NOT NULL AND ROWNUM = 1;
    IF v_chk > 0 THEN
        DELETE FROM DM_PLN_SALES_ETC_REPORT_C A
        WHERE A.DIVISION_ID = v_division_id
          AND A.VERSION_NO = v_version_no
          AND EXISTS ( SELECT 1 FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
                       WHERE TO_CHAR(A.DATA_SEQ) = B.DATA_SEQ
                         AND NVL(A.FCST_TYPE,'/') = NVL(B.FCST_TYPE,'/')  --[E20260812-FCSTNULL] NULL=NULL 은 UNKNOWN → 선삭제 매칭 실패 → INSERT ORA-00001 (클라우드 실사고. hook #131 센티널 계보 — 양변 NVL)
                         AND A.MEASURE = B.MEASURE
                         AND A.YYYYMMDD LIKE SUBSTR(B.YYYYMMDD, 1, 6) || '%' );

        --[E20260812-PKGUARD] INSERT 가 적재할 PK 조합 그대로 정밀 선삭제 — 부속컬럼 매칭(FCST_TYPE 등)이
        --  빗나가 잔존한 행이 무엇이든 PK 기준으로 제거(클라우드 ORA-00001 잔존 사고. 키 변환식 = INSERT SELECT 와 동일)
        DELETE FROM DM_PLN_SALES_ETC_REPORT_C A
        WHERE A.DIVISION_ID = v_division_id AND A.VERSION_NO = v_version_no --[E20260828-SARGSWEEP] 직접 술어 (DIVISION 은 적재 시 '-' 정규화 — WHERE/JOIN NVL 제거)
          AND (A.VERSION_NO, A.DIVISION_ID, A.DATA_SEQ, A.MEASURE, A.YYYYMMDD) IN
              ( SELECT B.VERSION_NO, B.DIVISION_ID, TO_NUMBER(B.DATA_SEQ), B.MEASURE, NVL(B.YYYYMMDD,'/')
                  FROM SCM_MGR.GT_DMF0049_RESULTS_MST B
                 WHERE B.DATA_SEQ IS NOT NULL
                   AND B.ACTIVE_FLAG <> 'D' );

        INSERT INTO DM_PLN_SALES_ETC_REPORT_C
        ( VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE
        , SOLDTO_CUST_REPORT, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME
        , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, INCOTERMS, MEASURE
        , PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1
        , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, OWNER_NAME
        , CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE, DEPARTMENT_NAME, DEPT_NAME )
        SELECT A.VERSION_NO, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), TO_NUMBER(A.DATA_SEQ), v_cutoff_type, v_cutoff_yyyymmdd, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT, NVL(NULLIF(RTRIM(A.SOLDTO_CODE),''), '/')  /* [SOLDTO-SENTINEL 2026-08-11] 빈값→'-' 통일 */
        , A.SOLDTO_CUST_REPORT, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE, '' AS PROJECT_NAME
        , A.SCM_SITE_ID, A.ITEM_ID, '-' AS DOM_EXP, A.FCST_TYPE, A.ITEM_USE, A.SOLDTO_COUNTRY, A.SHIPTO_COUNTRY, A.END_CUSTOMER, '-' AS INCOTERMS, NVL(NULLIF(RTRIM(A.MEASURE),''), '/')
        , '-' AS PLANT_SITE_ID, NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), A.CURRENCY, A.COMPANY_ID, TO_NUMBER(A.QTY), v_log_user, SYSDATE, v_log_user, SYSDATE, '' AS ATTRIBUTE1
        , '' AS ATTRIBUTE2, NVL(A.CELL_MODEL,'') AS ATTRIBUTE3, '', '', '', '', '', '', '', A.OWNER_NAME
        , A.CUST_GROUP_DTL, A.FORECAST_INFO_SPEC, A.NICK_NAME, A.FORECAST_INFO_CELL_PACK_COUNT, A.COMPANY_NAME, A.COUNTRY_KR_NAME, A.ROUTE, A.DEPARTMENT_NAME, A.DEPT_NAME
        FROM ( SELECT G.*, ROW_NUMBER() OVER (
                       PARTITION BY G.VERSION_NO, NVL(G.DIVISION_ID,'/'), G.DATA_SEQ, G.MEASURE, NVL(G.YYYYMMDD,'/')
                       ORDER BY G.ROWID ) AS PK_DEDUP_RN
                 FROM SCM_MGR.GT_DMF0049_RESULTS_MST G
                WHERE G.DATA_SEQ IS NOT NULL
                  AND G.ACTIVE_FLAG <> 'D' ) A
        WHERE A.PK_DEDUP_RN = 1;  --[E20260812-PKGUARD] payload 내 동일 PK 중복 행 자기충돌 방어(1행 채택)
    END IF;

    -----------------------------------------------------------------------------------------------------------------------
    -- INSERT 대상(DATA_SEQ 미존재): DATA_SEQ 채번 후 인서트
    -----------------------------------------------------------------------------------------------------------------------
    SELECT COUNT(*) INTO v_chk FROM SCM_MGR.GT_DMF0049_RESULTS_MST WHERE DATA_SEQ IS NULL AND ROWNUM = 1;
    IF v_chk > 0 THEN
        SELECT NVL(MAX(DATA_SEQ), 1) INTO v_max_seq FROM DM_PLN_SALES_ETC_REPORT_C
        WHERE DIVISION_ID = v_division_id AND VERSION_NO = v_version_no;

        INSERT INTO DM_PLN_SALES_ETC_REPORT_C
        ( VERSION_NO, DIVISION_ID, DATA_SEQ, CUTOFF_TYPE, CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT, SOLDTO_CODE
        , SOLDTO_CUST_REPORT, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE, APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE, PROJECT_NAME
        , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, ITEM_USE, SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, INCOTERMS, MEASURE
        , PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1
        , ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, OWNER_NAME
        , CUST_GROUP_DTL, FORECAST_INFO_SPEC, NICK_NAME, FORECAST_INFO_CELL_PACK_COUNT, COMPANY_NAME, COUNTRY_KR_NAME, ROUTE, DEPARTMENT_NAME, DEPT_NAME )
        SELECT A.VERSION_NO, NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/')
             , DENSE_RANK() OVER ( ORDER BY A.DEPARTMENT_ID, A.DEPT_ID, A.CUST_REPORT, A.END_CUST_REPORT
                                          , A.SOLDTO_CODE, A.SOLDTO_CUST_REPORT, A.PRODUCT_GROUP, A.ITEM_ID, A.PRODUCT_DETAILS, A.CURRENCY
                                          , A.COMPANY_ID, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.ITEM_USE, A.SOLDTO_COUNTRY, A.SHIPTO_COUNTRY, A.END_CUSTOMER ) + v_max_seq AS DATA_SEQ
             , v_cutoff_type, v_cutoff_yyyymmdd, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT, NVL(NULLIF(RTRIM(A.SOLDTO_CODE),''), '/')  /* [SOLDTO-SENTINEL 2026-08-11] 빈값→'-' 통일 */
             , A.SOLDTO_CUST_REPORT, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE, A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE, '' AS PROJECT_NAME
             , A.SCM_SITE_ID, A.ITEM_ID, '-' AS DOM_EXP, A.FCST_TYPE, A.ITEM_USE, A.SOLDTO_COUNTRY, A.SHIPTO_COUNTRY, A.END_CUSTOMER, '-' AS INCOTERMS, NVL(NULLIF(RTRIM(A.MEASURE),''), '/')
             , '-' AS PLANT_SITE_ID, NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), A.CURRENCY, A.COMPANY_ID, TO_NUMBER(A.QTY), v_log_user, SYSDATE, v_log_user, SYSDATE, '' AS ATTRIBUTE1
             , '' AS ATTRIBUTE2, NVL(A.CELL_MODEL,'') AS ATTRIBUTE3, '', '', '', '', '', '', '', A.OWNER_NAME
             , A.CUST_GROUP_DTL, A.FORECAST_INFO_SPEC, A.NICK_NAME, A.FORECAST_INFO_CELL_PACK_COUNT, A.COMPANY_NAME, A.COUNTRY_KR_NAME, A.ROUTE, A.DEPARTMENT_NAME, A.DEPT_NAME
        FROM SCM_MGR.GT_DMF0049_RESULTS_MST A
        WHERE A.DATA_SEQ IS NULL;
    END IF;

    -----------------------------------------------------------------------------------------------------------------------
    --[E20250418-001567]_HISTORY 데이터 적재
    -----------------------------------------------------------------------------------------------------------------------
    INSERT INTO DM_PLN_SALES_ETC_REPORT_H
    ( VERSION_NO, DIVISION_ID, HISTORY_SEQ, DATA_SEQ, CUTOFF_TYPE
    , CUTOFF_YYYYMMDD, DEPARTMENT_ID, DEPT_ID, END_CUST_REPORT, CUST_REPORT
    , SOLDTO_CODE, SOLDTO_CUST_REPORT, PRODUCT_DETAILS, CELL_MODEL_INFO, BIZ_TYPE
    , APPLICATION_GR, APPLICATION, COUNTRY_CODE, PRODUCT_GROUP, PROJECT_CODE
    , PROJECT_NAME, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
    , SOLDTO_COUNTRY, SHIPTO_COUNTRY, END_CUSTOMER, INCOTERMS, MEASURE
    , PLANT_SITE_ID, YYYYMMDD, CURRENCY, COMPANY_ID, ITEM_USE
    , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
    , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
    , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, COMPANY_NAME
    , COUNTRY_KR_NAME, CUST_GROUP_DTL, DEPARTMENT_NAME, DEPT_NAME, FORECAST_INFO_CELL_PACK_COUNT
    , FORECAST_INFO_SPEC, NICK_NAME, OWNER_NAME, ROUTE )
    SELECT A.VERSION_NO, A.DIVISION_ID, SCM_MGR.SEQ1_DM_PLN_SALES_ETC_REPORT_H.NEXTVAL, A.DATA_SEQ, A.CUTOFF_TYPE
         , A.CUTOFF_YYYYMMDD, A.DEPARTMENT_ID, A.DEPT_ID, A.END_CUST_REPORT, A.CUST_REPORT
         , A.SOLDTO_CODE, A.SOLDTO_CUST_REPORT, A.PRODUCT_DETAILS, A.CELL_MODEL_INFO, A.BIZ_TYPE
         , A.APPLICATION_GR, A.APPLICATION, A.COUNTRY_CODE, A.PRODUCT_GROUP, A.PROJECT_CODE
         , A.PROJECT_NAME, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE
         , A.SOLDTO_COUNTRY, A.SHIPTO_COUNTRY, A.END_CUSTOMER, A.INCOTERMS, A.MEASURE
         , A.PLANT_SITE_ID, A.YYYYMMDD, A.CURRENCY, A.COMPANY_ID, A.ITEM_USE
         , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
         , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
         , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
         , A.COMPANY_NAME, A.COUNTRY_KR_NAME, A.CUST_GROUP_DTL, A.DEPARTMENT_NAME, A.DEPT_NAME
         , A.FORECAST_INFO_CELL_PACK_COUNT, A.FORECAST_INFO_SPEC, A.NICK_NAME, A.OWNER_NAME, A.ROUTE
    FROM DM_PLN_SALES_ETC_REPORT_C A
    INNER JOIN SCM_MGR.GT_DMF0049_RESULTS_MST B
            ON A.VERSION_NO = B.VERSION_NO
           AND A.DIVISION_ID = B.DIVISION_ID
           AND TO_CHAR(A.DATA_SEQ) = B.DATA_SEQ
           AND A.MEASURE = B.MEASURE
           AND A.YYYYMMDD = B.YYYYMMDD;

    -- UPDATE 후에 전송처리를 다시 한다.
    SELECT COUNT(*) INTO v_chk FROM DM_MDF_VERSION
     WHERE DIVISION_ID = v_division_id AND VERSION_NO = v_version_no AND SEND_YN = 'Y' AND ROWNUM = 1;
    IF v_chk > 0 THEN
        PKG_DMF0044.P_DMF0044_MOBILE_REPORT_CREATE(v_division_id, v_version_no, v_cutoff_type, 'T', v_log_user, O_RESULT_CURSOR);
    END IF;

    COMMIT;

    -- 수행결과 성공
    IF O_RESULT_CURSOR IS NULL OR NOT O_RESULT_CURSOR%ISOPEN THEN
        OPEN O_RESULT_CURSOR FOR SELECT 'success' AS MSG FROM DUAL;
    END IF;

    -- 종료 LOG
    LOG_END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE        := 'ERROR';
        V_LOG_MESSAGE     := 'EXCEPTION';
        V_LOG_DESCRIPTION := '';
        D_EVENT_DATE      := SYSDATE;
        V_SQL_CODE        := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG      := SQLERRM;
        V_PROC_INPUT      := JSON_OBJECT(
            'p_division_id' VALUE p_division_id,
            'p_version_no'  VALUE p_version_no,
            'p_created_by'  VALUE p_created_by
        );
        V_BACKTRACE       := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN
            SCM_MGR.PR_DM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_LOG_DESCRIPTION, D_EVENT_DATE, v_log_user,
                V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0049_SAVE_SALES_ETC_REPORT_C;

END PKG_DMF0049;
/
SHOW ERRORS PACKAGE BODY PKG_DMF0049
-- ##### END PACKAGE BODY PKG_DMF0049

-- ##### START PACKAGE BODY PKG_DMF0051
CREATE OR REPLACE PACKAGE BODY           "PKG_DMF0051" IS

    PROCEDURE P_DMF0051_GET_SPREAD_TITLE
    (
        P_START_YYYYMMDD VARCHAR2
       ,P_END_YYYYMMDD   VARCHAR2
       ,P_CREATED_BY     VARCHAR2
       ,P_DIVISION_ID    VARCHAR2
       ,P_BUCKET         VARCHAR2
       ,P_USER_ID        VARCHAR2
       ,P_MENU_ID        VARCHAR2
       ,O_RC1            OUT SYS_REFCURSOR
       ,O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    /*
        * Program ID   : DMF0051_GET_SPREAD_TITLE
        * Description  :
        * Program History
        *===================================================================================================
        *   Date       In Charge      Description
        *===================================================================================================
        * 20220603     kdw2819         Initial Release PJ20216891R
        * 20221116     kdw2819         [C20221107-000343]BP Waterfall 오류 수정 요청의 건
        * 2026/03/15 김준규            [PJ20264226] NextSCM Pilot 설계 및 개발
        */
     AS

        I_COUNT        INTEGER := 0;
        V_PROGRAM_ID   VARCHAR2(50 CHAR) := 'DMF0035';  --[E20260909-TYPEAXIS] SHEET_COLUMNS/SHEET_MEASURE/TITLESET 축 = PROGRAM_ID 'DMF0035' + AS-IS 실등록 시트명 (사용자 지시 2026-09-09). PKG 명은 유지.
        V_SHEET_NAME   VARCHAR2(50 CHAR) := 'Biz Plan Waterfall';
        V_IN_PARA_DATA VARCHAR2(4000);
        V_LOG_TYPE     VARCHAR2(20) := NULL;
        N_LOG_COUNT    NUMBER := 0;
        V_LOG_MESSAGE  VARCHAR2(4000 CHAR) := NULL;
        V_DESCRIPTION  VARCHAR2(4000 CHAR) := NULL;
        D_EVENT_DATE   DATE := SYSDATE;
        V_PROC_INPUT   CLOB := NULL;
        V_SQL_CODE     VARCHAR2(100) := NULL;
        V_SQL_ERRMSG   VARCHAR2(4000 CHAR) := NULL;
        V_BACKTRACE    VARCHAR2(4000 CHAR) := NULL;
    BEGIN

        V_IN_PARA_DATA := JSON_OBJECT('p_start_yyyymmdd' VALUE P_START_YYYYMMDD
                                     ,'p_end_yyyymmdd' VALUE P_END_YYYYMMDD
                                     ,'p_created_by' VALUE P_CREATED_BY
                                     ,'p_division_id' VALUE P_DIVISION_ID
                                     ,'p_bucket' VALUE P_BUCKET);

        SELECT COUNT(*)
        INTO   I_COUNT
        FROM   SCM_MST_TITLESET_USER U

        WHERE  1 = 1
        AND    U.PROGRAM_ID = V_PROGRAM_ID
        AND    U.SHEET_NAME = V_SHEET_NAME
        AND    U.USER_ID = P_CREATED_BY
        AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C';

        IF I_COUNT > 0 THEN
            OPEN O_RC1 FOR
                SELECT C.PROGRAM_ID
                      ,C.SHEET_NAME
                      ,C.COLUMN_NAME
                      ,CASE
                           WHEN P_DIVISION_ID LIKE '81%' THEN
                            (CASE
                                WHEN C.ATTRIBUTE4 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           WHEN P_DIVISION_ID = '82' THEN
                            (CASE
                                WHEN C.ATTRIBUTE5 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           ELSE
                            C.COLUMN_LABEL_NAME
                       END AS COLUMN_LABEL_NAME
                       -- [C20221107-000343]BP Waterfall 오류 수정 요청의 건
                      ,TO_CHAR(U.SORT_ORDER_NO) SORT_ORDER_NO
                      ,C.DATA_SORT_METHOD_CODE
                      ,C.SMALL_CLASS_LABEL_NAME
                      ,C.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,C.FIXED_FLAG
                      ,C.COLUMN_WIDTH
                      ,C.CELL_CONTROL_OBJECT_TYPE_CODE
                      ,C.CELL_COMBO_DATA_TYPE
                      ,C.DATA_SCALE_NUMBER
                      ,C.DATA_MAX_LENGTH
                      ,C.HORIZONTAL_ALIGN_CODE
                      ,C.UPPERCASE_APPLY_FLAG
                      ,C.VISIBLE_FLAG
                      ,C.DEFAULT_FLAG
                      ,C.USER_SELECTABLE_FLAG
                      ,C.VALID_YN
                      ,C.DIVISION_ID
                      ,P_DIVISION_ID ATTRIBUTE1
                      ,CASE
                           WHEN CELL_COMBO_DATA_TYPE = 'DM_LOOKUP_DIV' THEN
                            C.ATTRIBUTE1
                           ELSE
                            ''
                       END AS ATTRIBUTE2
                      ,'' AS ATTRIBUTE3
                      ,C.ATTRIBUTE4
                      ,C.ATTRIBUTE5
                      ,TEI.EDIT_YN
                FROM   SCM_MST_TITLESET_USER U, SCM_MST_SHEET_COLUMNS C
                INNER  JOIN TABLE(PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                ON     TEI.UNIT_ID = P_DIVISION_ID --[E20260831-W41] C.DIVISION_ID 는 콤마 목록 — 정확일치 조인은 단독값 행만 생존(0022 [E20260806-WF] 동형). 사업부 매칭은 WHERE 의 FN_SPLITSTRING 이 담당
                WHERE  1 = 1
                AND    U.PROGRAM_ID = C.PROGRAM_ID
                AND    U.SHEET_NAME = C.SHEET_NAME
                AND    U.COLUMN_NAME = C.COLUMN_NAME
                AND    U.PROGRAM_ID = V_PROGRAM_ID
                AND    U.SHEET_NAME = V_SHEET_NAME
                AND    U.USER_ID = P_CREATED_BY
                AND    U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
                AND    P_DIVISION_ID IN (SELECT VALUE FROM TABLE(FN_SPLITSTRING(C.DIVISION_ID, ',')))
                UNION ALL
                SELECT C.PROGRAM_ID
                      ,C.SHEET_NAME
                      ,C.COLUMN_NAME
                      ,CASE
                           WHEN P_DIVISION_ID LIKE '81%' THEN
                            (CASE
                                WHEN C.ATTRIBUTE4 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           WHEN P_DIVISION_ID = '82' THEN
                            (CASE
                                WHEN C.ATTRIBUTE5 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           ELSE
                            C.COLUMN_LABEL_NAME
                       END AS COLUMN_LABEL_NAME
                      ,TO_CHAR(C.SORT_ORDER_NO) SORT_ORDER_NO
                      ,C.DATA_SORT_METHOD_CODE
                      ,C.SMALL_CLASS_LABEL_NAME
                      ,C.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,C.FIXED_FLAG
                      ,C.COLUMN_WIDTH
                      ,C.CELL_CONTROL_OBJECT_TYPE_CODE
                      ,C.CELL_COMBO_DATA_TYPE
                      ,C.DATA_SCALE_NUMBER
                      ,C.DATA_MAX_LENGTH
                      ,C.HORIZONTAL_ALIGN_CODE
                      ,C.UPPERCASE_APPLY_FLAG
                      ,C.VISIBLE_FLAG
                      ,C.DEFAULT_FLAG
                      ,C.USER_SELECTABLE_FLAG
                      ,C.VALID_YN
                      ,C.DIVISION_ID
                      ,P_DIVISION_ID ATTRIBUTE1
                      ,C.ATTRIBUTE2
                      ,C.ATTRIBUTE3
                      ,C.ATTRIBUTE4
                      ,C.ATTRIBUTE5
                      ,'N' AS EDIT_YN
                FROM   SCM_MST_SHEET_COLUMNS C
                WHERE  1 = 1
                AND    C.PROGRAM_ID = V_PROGRAM_ID
                AND    C.SHEET_NAME = V_SHEET_NAME
                AND    C.VISIBLE_FLAG = 'N'
                AND    RTRIM(C.DEFAULT_FLAG, ' -') IS NULL  --[E20260831-W34] AS-IS DEFAULT_FLAG='' 숨은컬럼 arm — ''=NULL(' '/'-' 흡수) 정정
                AND    C.VALID_YN = 'Y'
                AND    P_DIVISION_ID IN (SELECT VALUE FROM TABLE(FN_SPLITSTRING(C.DIVISION_ID, ','))) -- 20180620 division 추가

                UNION ALL

                SELECT V_PROGRAM_ID AS PROGRAM_ID
                      ,V_SHEET_NAME SHEET_NAME
                      ,T.COLUMN_NAME
                      ,T.COLUMN_LABEL_NAME
                      ,T.SORT_ORDER_NO
                      ,'' AS DATA_SORT_METHOD_CODE
                      ,T.SMALL_CLASS_LABEL_NAME
                      ,T.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,'' AS FIXED_FLAG
                      ,CAST(50 AS NUMBER) COLUMN_WIDTH
                      ,'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                      ,'' AS CELL_COMBO_DATA_TYPE
                      ,CAST('3' AS NUMBER) DATA_SCALE_NUMBER
                      ,CAST(NULL AS NUMBER) DATA_MAX_LENGTH
                      ,'R' AS HORIZONTAL_ALIGN_CODE
                      ,'Y' AS UPPERCASE_APPLY_FLAG
                      ,'Y' AS VISIBLE_FLAG
                      ,'' AS DEFAULT_FLAG
                      ,'' AS USER_SELECTABLE_FLAG
                      ,'' AS VALID_YN
                      ,'' AS DIVISION_ID
                      ,'' AS ATTRIBUTE1
                      ,'' AS ATTRIBUTE2
                      ,'' AS ATTRIBUTE3
                      ,'' AS ATTRIBUTE4
                      ,'' AS ATTRIBUTE5
                      ,'N' AS EDIT_YN
                FROM   (SELECT *
                        FROM   (
                                -- Monthly
                                SELECT 'M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                                       ,A.MONTH_NAME COLUMN_LABEL_NAME
                                       ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) SMALL_CLASS_LABEL_NAME
                                       ,TO_CHAR(A.CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                       ,BASIS_YYYYMM || '01' AS SORT_ORDER_NO
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                                GROUP  BY CALENDAR_YYYY, A.BASIS_YYYYMM, A.MONTH_NAME
                                UNION ALL
                                -- Quarterly
                                SELECT DISTINCT 'Q_' || CALENDAR_YYYY || '_' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) COLUMN_NAME
                                                ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) COLUMN_LABEL_NAME
                                                ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) SMALL_CLASS_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                                ,CASE
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 1 THEN
                                                      CALENDAR_YYYY || '0100'
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 2 THEN
                                                      CALENDAR_YYYY || '0400'
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 3 THEN
                                                      CALENDAR_YYYY || '0700'
                                                     ELSE
                                                      CALENDAR_YYYY || '1000'
                                                 END AS SORT_ORDER_NO
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD

                                UNION ALL
                                -- Yearly
                                SELECT DISTINCT 'Y_' || CALENDAR_YYYY AS COLUMN_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) COLUMN_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) SMALL_CLASS_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                                ,CALENDAR_YYYY || '0000' AS SORT_ORDER_NO
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD) MA) T
                ORDER  BY SORT_ORDER_NO;

        ELSE
            OPEN O_RC1 FOR
                SELECT C.PROGRAM_ID
                      ,C.SHEET_NAME
                      ,C.COLUMN_NAME
                      ,CASE
                           WHEN P_DIVISION_ID LIKE '81%' THEN
                            (CASE
                                WHEN C.ATTRIBUTE4 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           WHEN P_DIVISION_ID = '82' THEN
                            (CASE
                                WHEN C.ATTRIBUTE5 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           ELSE
                            C.COLUMN_LABEL_NAME
                       END AS COLUMN_LABEL_NAME
                      ,TO_CHAR(C.SORT_ORDER_NO) SORT_ORDER_NO
                      ,C.DATA_SORT_METHOD_CODE
                      ,C.SMALL_CLASS_LABEL_NAME
                      ,C.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,C.FIXED_FLAG
                      ,C.COLUMN_WIDTH
                      ,C.CELL_CONTROL_OBJECT_TYPE_CODE
                      ,C.CELL_COMBO_DATA_TYPE
                      ,C.DATA_SCALE_NUMBER
                      ,C.DATA_MAX_LENGTH
                      ,C.HORIZONTAL_ALIGN_CODE
                      ,C.UPPERCASE_APPLY_FLAG
                      ,C.VISIBLE_FLAG
                      ,C.DEFAULT_FLAG
                      ,C.USER_SELECTABLE_FLAG
                      ,C.VALID_YN
                      ,C.DIVISION_ID
                      ,P_DIVISION_ID ATTRIBUTE1
                      ,CASE
                           WHEN CELL_COMBO_DATA_TYPE = 'DM_LOOKUP_DIV' THEN
                            C.ATTRIBUTE1
                           ELSE
                            ''
                       END AS ATTRIBUTE2
                      ,'' AS ATTRIBUTE3
                      ,C.ATTRIBUTE4
                      ,C.ATTRIBUTE5
                      ,TEI.EDIT_YN
                FROM   SCM_MST_SHEET_COLUMNS C
                INNER  JOIN TABLE(PKG_SCM_USER_MNU.PR_SCM_EDIT_YN(P_USER_ID, P_MENU_ID)) TEI
                ON     TEI.UNIT_ID = P_DIVISION_ID --[E20260831-W41] C.DIVISION_ID 는 콤마 목록 — 정확일치 조인은 단독값 행만 생존(0022 [E20260806-WF] 동형). 사업부 매칭은 WHERE 의 FN_SPLITSTRING 이 담당
                WHERE  1 = 1
                AND    C.PROGRAM_ID = V_PROGRAM_ID
                AND    C.SHEET_NAME = V_SHEET_NAME
                AND    C.DEFAULT_FLAG = 'Y'
                AND    C.VALID_YN = 'Y'
                AND    P_DIVISION_ID IN (SELECT VALUE FROM TABLE(FN_SPLITSTRING(C.DIVISION_ID, ',')))

                UNION ALL

                SELECT C.PROGRAM_ID
                      ,C.SHEET_NAME
                      ,C.COLUMN_NAME
                      ,CASE
                           WHEN P_DIVISION_ID LIKE '81%' THEN
                            (CASE
                                WHEN C.ATTRIBUTE4 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           WHEN P_DIVISION_ID = '82' THEN
                            (CASE
                                WHEN C.ATTRIBUTE5 = 'Y' THEN
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '') || '*'
                                ELSE
                                 REPLACE(C.COLUMN_LABEL_NAME, '*', '')
                            END)
                           ELSE
                            C.COLUMN_LABEL_NAME
                       END AS COLUMN_LABEL_NAME
                      ,TO_CHAR(C.SORT_ORDER_NO) SORT_ORDER_NO
                      ,C.DATA_SORT_METHOD_CODE
                      ,C.SMALL_CLASS_LABEL_NAME
                      ,C.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,C.FIXED_FLAG
                      ,C.COLUMN_WIDTH
                      ,C.CELL_CONTROL_OBJECT_TYPE_CODE
                      ,C.CELL_COMBO_DATA_TYPE
                      ,C.DATA_SCALE_NUMBER
                      ,C.DATA_MAX_LENGTH
                      ,C.HORIZONTAL_ALIGN_CODE
                      ,C.UPPERCASE_APPLY_FLAG
                      ,C.VISIBLE_FLAG
                      ,C.DEFAULT_FLAG
                      ,C.USER_SELECTABLE_FLAG
                      ,C.VALID_YN
                      ,C.DIVISION_ID
                      ,P_DIVISION_ID ATTRIBUTE1
                      ,CASE
                           WHEN CELL_COMBO_DATA_TYPE = 'DM_LOOKUP_DIV' THEN
                            C.ATTRIBUTE1
                           ELSE
                            C.ATTRIBUTE1
                       END AS ATTRIBUTE2
                      ,C.ATTRIBUTE3
                      ,C.ATTRIBUTE4
                      ,C.ATTRIBUTE5
                      ,'N' AS EDIT_YN
                FROM   SCM_MST_SHEET_COLUMNS C
                WHERE  1 = 1
                AND    C.PROGRAM_ID = V_PROGRAM_ID
                AND    C.SHEET_NAME = V_SHEET_NAME
                AND    C.VISIBLE_FLAG = 'N'
                AND    RTRIM(C.DEFAULT_FLAG, ' -') IS NULL  --[E20260831-W34] AS-IS DEFAULT_FLAG='' 숨은컬럼 arm — ''=NULL(' '/'-' 흡수) 정정
                AND    C.VALID_YN = 'Y'
                AND    P_DIVISION_ID IN (SELECT VALUE FROM TABLE(FN_SPLITSTRING(C.DIVISION_ID, ','))) -- 20180620 division 추가

                UNION ALL

                SELECT V_PROGRAM_ID AS PROGRAM_ID
                      ,V_SHEET_NAME SHEET_NAME
                      ,T.COLUMN_NAME
                      ,T.COLUMN_LABEL_NAME
                      ,T.SORT_ORDER_NO
                      ,'' AS DATA_SORT_METHOD_CODE
                      ,T.SMALL_CLASS_LABEL_NAME
                      ,T.LARGE_CLASS_LABEL_NAME
                      ,'' AS DAY_CODE
                      ,'' AS FIXED_FLAG
                      ,CAST(50 AS NUMBER) COLUMN_WIDTH
                      ,'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
                      ,'' AS CELL_COMBO_DATA_TYPE
                      ,CAST('3' AS NUMBER) DATA_SCALE_NUMBER
                      ,CAST(NULL AS NUMBER) DATA_MAX_LENGTH
                      ,'R' AS HORIZONTAL_ALIGN_CODE
                      ,'Y' AS UPPERCASE_APPLY_FLAG
                      ,'Y' AS VISIBLE_FLAG
                      ,'' AS DEFAULT_FLAG
                      ,'' AS USER_SELECTABLE_FLAG
                      ,'' AS VALID_YN
                      ,'' AS DIVISION_ID
                      ,'' AS ATTRIBUTE1
                      ,'' AS ATTRIBUTE2
                      ,'' AS ATTRIBUTE3
                      ,'' AS ATTRIBUTE4
                      ,'' AS ATTRIBUTE5
                      ,'N' AS EDIT_YN
                FROM   (SELECT *
                        FROM   (
                                -- Monthly
                                SELECT 'M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                                       ,A.MONTH_NAME COLUMN_LABEL_NAME
                                       ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) SMALL_CLASS_LABEL_NAME
                                       ,TO_CHAR(A.CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                       ,BASIS_YYYYMM || '01' AS SORT_ORDER_NO
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
                                GROUP  BY CALENDAR_YYYY, A.BASIS_YYYYMM, A.MONTH_NAME
                                UNION ALL
                                -- Quarterly
                                SELECT DISTINCT 'Q_' || CALENDAR_YYYY || '_' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) COLUMN_NAME
                                                ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) COLUMN_LABEL_NAME
                                                ,'Q' || TO_CHAR(TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q'))) SMALL_CLASS_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                                ,CASE
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 1 THEN
                                                      CALENDAR_YYYY || '0100'
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 2 THEN
                                                      CALENDAR_YYYY || '0400'
                                                     WHEN TO_NUMBER(TO_CHAR(TO_DATE(A.BASIS_YYYYMM || '01', 'YYYYMMDD'), 'Q')) = 3 THEN
                                                      CALENDAR_YYYY || '0700'
                                                     ELSE
                                                      CALENDAR_YYYY || '1000'
                                                 END
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD

                                UNION ALL
                                -- Yearly
                                SELECT DISTINCT 'Y_' || CALENDAR_YYYY AS COLUMN_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) COLUMN_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) SMALL_CLASS_LABEL_NAME
                                                ,TO_CHAR(CALENDAR_YYYY) LARGE_CLASS_LABEL_NAME
                                                ,CALENDAR_YYYY || '0000' AS SORT_ORDER_NO
                                FROM   SCM_SYS_CALENDAR_M A
                                WHERE  A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
                                AND    A.BASIS_YYYYMMDD <= P_END_YYYYMMDD) MA) T
                ORDER  BY SORT_ORDER_NO;
        END IF;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_LOG_TYPE   := 'ERROR';
            V_SQL_CODE   := TO_CHAR(SQLCODE);
            V_SQL_ERRMSG := SQLERRM;
            V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT
                                ,V_LOG_TYPE
                                ,N_LOG_COUNT
                                ,V_LOG_MESSAGE
                                ,V_DESCRIPTION
                                ,D_EVENT_DATE
                                ,V_PROC_INPUT
                                ,V_SQL_CODE
                                ,V_SQL_ERRMSG
                                ,V_BACKTRACE);
            RAISE_APPLICATION_ERROR(-20001
                                   ,'[' || $$PLSQL_UNIT || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                    DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
    END P_DMF0051_GET_SPREAD_TITLE;


    PROCEDURE P_DMF0051_GET_DM_PLN_BIZ_PLAN_WATERFALL
    (
        P_DIVISION_ID       IN VARCHAR2,
        P_DEPT_ID           IN VARCHAR2,
        P_END_CUSTOMER      IN VARCHAR2,
        P_SCM_SITE_ID       IN VARCHAR2,
        P_PROJECT_CODE      IN VARCHAR2,
        P_ITEM_ID           IN VARCHAR2,
        P_ITEM_TYPE         IN VARCHAR2,
        P_FROM_YYYYMMDD     IN VARCHAR2,
        P_NOW_YYYYMMDD      IN VARCHAR2,   -- AS-IS 수신만·본문 미사용 (계약 보존 — DMF0035 통합분석 §3.B)
        P_TO_YYYYMMDD       IN VARCHAR2,
        P_CREATED_BY        IN VARCHAR2,
        P_PLANT_SITE_ID     IN VARCHAR2,
        P_BIZTYPE           IN VARCHAR2,
        P_OWNER             IN VARCHAR2,
        P_VERSION_TYPE      IN VARCHAR2,
        P_CELL_YN           IN VARCHAR2,
        P_QTY_YN            IN VARCHAR2,
        P_USER_ID           IN VARCHAR2,
        P_MENU_ID           IN VARCHAR2,

        O_RC1               OUT SYS_REFCURSOR,
        O_RC2               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    /*=====================================================================================================================================================
     * [E20260806-WF] DMF0035 Demand Plan Waterfall 통합 — AS-IS DMF0051_GET_DM_PLN_BIZ_PLAN_WATERFALL 6-Stage 재변환
     * Program ID   : DMF0051_GET_DM_PLN_BIZ_PLAN_WATERFALL
     * Description  : Business Plan Waterfall 조회
     * Program History (AS-IS 원문 이력 보존)
     *=====================================================================================================================================================
     *   Date       In Charge      Description
     *=====================================================================================================================================================
     * 2022.06.10  rosia27      Initial Release [PJ20216891R]
     * 2022.10.31  rosia27      [C20221024-000510]DM UI 소스 정리 요청
     * 2022.11.16  kdw2819      [C20221107-000343]BP Waterfall 오류 수정 요청의 건
     * 2024/08/29  KJJ          [PJ2024-50461] Team Mapping
     * 2024.09.12  JSSBAE       [E20240920-000300]_SCM.DM 화면 조회 속도 개선
     * 2026.08.06  Claude       [E20260806-WF] MSSQL 1,296행 → Oracle PKG 멤버 재변환 (패턴 정본=PKG_DMF0022.P_DMF0022_GET_DM_PLN_SALES_PLAN_WATERFALL)
     *=====================================================================================================================================================
     * 계약: IN 19 (AS-IS 17 positional 그대로 + P_USER_ID/P_MENU_ID) / OUT 3 (O_RC1 피벗 본문+EDIT_YN, O_RC2 금일 ISO_WEEK·BASIS_DATE, O_RESULT_CURSOR 결과코드)
     * 이관 제외/변형 (전수):
     *   1) #T_PRICE — AS-IS 에서 DROP 만 존재하는 미사용 잔재 → 이관 제외
     *   2) 3번째 결과셋(실행 SQL 의 FOR XML 디버그 덤프) → 0022 선례대로 O_RESULT_CURSOR(결과코드) + DBMS_OUTPUT.PUT_LINE(v_sql_text) 로 대체
     *   3) #TEMP_SCM_MST_SSO_USER_INFO(단순 사본) → 0022 선례대로 SCM_MST_SSO_USER_INFO 직접 조회
     *   4) c_bucket FAST_FORWARD 커서 → FOR 커서 루프 (0022 선례)
     *   5) CREATE CLUSTERED INDEX(#TEMP_DM_MST_ITEM_SINGLE_V) → GTT + DBMS_STATS.GATHER_TABLE_STATS 로 대체 (0022 선례)
     *   6) String_Split → TABLE(UF_FX_STRING_SPLIT(REPLACE(p,'^',','),',')) — ',' 와 '^' 겸용 토큰화
     *   7) DEFAULT_FLAG = '' 판정 → RTRIM(DEFAULT_FLAG,' -') IS NULL (PKG_DMF0042 [E20260806-00979] 계보 — ''=NULL·'-' 센티널 흡수)
     *   8) titleset 'M' 0건 DEFAULT INSERT = 원본 유지 (PKG_DMF0022/PKG_DMF0035 변환판 모두 면역 가드 미적용 — 동일 수준)
     * GTT: 재사용 GT_DM22_V_VERSION_NO/GT_DM22_SELECT_MEASURE/GT_DM22_T_COLUMN_SETUP/GT_DM22_T/GT_DM22_DM_MST_ITEM_SINGLE_{ORI_V,A_V,B_V,V}
     *      신규 GT_DM51_RAW_DATA/GT_DM51_SCM_MST_SITE_ITEM/GT_DM51_SCM_CITY (별도 DDL: DMF0051_PKG_GET_WATERFALL_20260806_GTT_DDL.sql)
     *===================================================================================================================================================*/
    AS
        v_program_id    VARCHAR2(50  CHAR) := 'DMF0035';  --[E20260909-TYPEAXIS] SHEET_COLUMNS/SHEET_MEASURE/TITLESET 축 = PROGRAM_ID 'DMF0035' + AS-IS 실등록 시트명 (사용자 지시 2026-09-09). PKG 명은 유지.
        v_sheet_name    VARCHAR2(50  CHAR) := 'Biz Plan Waterfall';

        v_ColList       VARCHAR2(32767 CHAR) := '';
        v_OrderList     VARCHAR2(32767 CHAR) := '';
        i_count         PLS_INTEGER := 0;
        v_user_mea_cnt  PLS_INTEGER := 0;

        -- Dynamic SQL 변수
        v_sql_text      VARCHAR2(32767 CHAR);
        V_PV_LIST       VARCHAR2(32767 CHAR);
        V_PV_COL_LIST   VARCHAR2(32767 CHAR);
        V_SQL_SELECT    VARCHAR2(32767 CHAR);
        v_I             PLS_INTEGER;
        v_CNT           PLS_INTEGER;

        V_PROC_INPUT    CLOB;
        V_BACKTRACE     VARCHAR2(4000 CHAR);
        V_SQL_CODE      VARCHAR2(100  CHAR);
        V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
        n_log_count     PLS_INTEGER := 0;
        V_PROGRAM_NAME  VARCHAR2(150 CHAR) := $$PLSQL_UNIT;

    BEGIN
    --[E20260820-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어
    --  통계 없는 GTT 가 카디널리티 1 로 추정되어 NL 이 선택되면 대용량 표를 행 단위로 훑는다
    --  (클라우드 실측: GT_DM35_T_LAST_SETUP_C 적재문 1,302초/회, cell single block read).
    EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';

        IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
            V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
        ELSE
            V_PROGRAM_NAME := $$PLSQL_UNIT;
        END IF;

        --[E20260806-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어 (2026-08-06 사용자 지시)
        --  Oracle 기본값 2 복원. 트랜잭션 무관 세션 파라미터(ENABLE PARALLEL DML 계열 아님 — ORA-12841 리스크 없음).
        EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';

        -- SET NOCOUNT ON / SET ANSI_NULLS ON / SET ANSI_WARNINGS ON;  (Oracle: 불필요)

        -- GTT 세션 통계 설정 (19c GLOBAL_TEMP_TABLE_STATS=SESSION 표준)
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_V_VERSION_NO',             'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_SELECT_MEASURE',           'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM51_RAW_DATA',                 'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_DM_MST_ITEM_SINGLE_ORI_V', 'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_DM_MST_ITEM_SINGLE_A_V',   'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_DM_MST_ITEM_SINGLE_B_V',   'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_DM_MST_ITEM_SINGLE_V',     'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM51_SCM_MST_SITE_ITEM',        'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM51_SCM_CITY',                 'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_T_COLUMN_SETUP',           'GLOBAL_TEMP_TABLE_STATS','SESSION');
        DBMS_STATS.SET_TABLE_PREFS('SCM_MGR','GT_DM22_T',                        'GLOBAL_TEMP_TABLE_STATS','SESSION');

        --=================================================================================================================================
        -- Temp Table 존재 여부 체크 (BEGIN)  — 원본 MSSQL DROP TABLE #X → Oracle GTT.
        -- ON COMMIT PRESERVE ROWS + 커넥션 풀 세션 재사용 대비 시작 시 DELETE 초기화 (부록 C-2/C-5 — TRUNCATE 금지)
        --=================================================================================================================================
        DELETE FROM SCM_MGR.GT_DM22_V_VERSION_NO;
        DELETE FROM SCM_MGR.GT_DM22_SELECT_MEASURE;
        DELETE FROM SCM_MGR.GT_DM51_RAW_DATA;
        DELETE FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_ORI_V;
        DELETE FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_A_V;
        DELETE FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_B_V;
        DELETE FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_V;
        DELETE FROM SCM_MGR.GT_DM51_SCM_MST_SITE_ITEM;
        DELETE FROM SCM_MGR.GT_DM51_SCM_CITY;
        DELETE FROM SCM_MGR.GT_DM22_T_COLUMN_SETUP;
        DELETE FROM SCM_MGR.GT_DM22_T;

        --=================================================================================================================================
        -- 버전 토큰 사전 분해 (0022 선례 [E20250529-001488] 패턴) — '(' 앞 버전 토큰 절단 + ','/'^' 겸용 분해
        --   AS-IS: A.VERSION_NO IN (SELECT LEFT(token, CASE WHEN CHARINDEX('(',token)=0 THEN LEN(token) ELSE CHARINDEX('(',token)-1 END)
        --                             FROM dbo.String_Split(@p_version_type ,','))  (dump:369/403/456 3개소 공통)
        --=================================================================================================================================
        INSERT INTO SCM_MGR.GT_DM22_V_VERSION_NO
            (VERSION_NO, TOBE_VERSION_NO)
        SELECT TRIM(CASE WHEN INSTR(TOKEN, '(') = 0
                         THEN TOKEN
                         ELSE SUBSTR(TOKEN, 1, INSTR(TOKEN, '(') - 1)
                    END) AS VERSION_NO,
               NULL AS TOBE_VERSION_NO
          FROM (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_VERSION_TYPE, '^', ','), ',')) P)
        ;

        DBMS_OUTPUT.PUT_LINE(v_program_id || ' : A001--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '=>' || TO_CHAR(SQL%ROWCOUNT));

        --=================================================================================================================================
        -- titleset 'M' 0건 시 DEFAULT INSERT (AS-IS dump:103-145 원본 유지 — PKG_DMF0022/0035 변환판과 동일 수준, 면역 가드 미적용)
        --=================================================================================================================================
        SELECT COUNT(*)
          INTO v_user_mea_cnt
          FROM SCM_MGR.SCM_MST_TITLESET_USER U
         WHERE 1 = 1
           AND U.PROGRAM_ID                    = v_program_id
           AND U.SHEET_NAME                    = v_sheet_name
           AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'M'
           AND U.USER_ID                       = P_CREATED_BY;

        IF v_user_mea_cnt = 0 THEN
            INSERT INTO SCM_MGR.SCM_MST_TITLESET_USER
                ( USER_ID
                , PROGRAM_ID
                , SHEET_NAME
                , USER_INQUIRY_COLUMN_TYPE_CODE
                , COLUMN_NAME
                , SORT_ORDER_NO
                , SUB_TOTAL_FLAG
                , DATA_SORT_METHOD_CODE
                , CREATED_BY
                , CREATION_DATE
                , LAST_UPDATED_BY
                , LAST_UPDATE_DATE
                )
            SELECT P_CREATED_BY
                 , C.PROGRAM_ID
                 , C.SHEET_NAME
                 , 'M'
                 , C.COLUMN_NAME
                 , C.SORT_ORDER_NO
                 , 'N'
                 , ''
                 , P_CREATED_BY
                 , SYSDATE
                 , P_CREATED_BY
                 , SYSDATE
              FROM SCM_MGR.SCM_MST_SHEET_MEASURE C
             WHERE 1 = 1
               AND C.PROGRAM_ID   = v_program_id
               AND C.SHEET_NAME   = v_sheet_name
               AND C.DEFAULT_FLAG = 'Y'
               AND C.VALID_YN     = 'Y';
        END IF;

        --=================================================================================================================================
        -- #SELECT_MEASURE (AS-IS dump:147-158)
        --   * AS-IS 의 PROGRAM_ID/SHEET_NAME 컬럼은 상수(v_program_id/v_sheet_name)이며 하류 미사용 → GT_DM22_SELECT_MEASURE 재사용 위해 제외
        --=================================================================================================================================
        INSERT INTO SCM_MGR.GT_DM22_SELECT_MEASURE
            (MEASURE, SORT_ORDER_NO)
        SELECT DISTINCT
               U.COLUMN_NAME AS MEASURE
             , U.SORT_ORDER_NO
          FROM SCM_MGR.SCM_MST_TITLESET_USER U
         WHERE 1 = 1
           AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'M'
           AND U.PROGRAM_ID = v_program_id
           AND U.SHEET_NAME = v_sheet_name
           AND U.USER_ID    = P_CREATED_BY
           --[E20260910-MEASDIV] 개인화에 남아 있어도 '조회 대상이 아닌 메저'는 제외한다.
           --  메저 모달은 콤보 DMF0035_BP_Measure 로 SCM_MST_SHEET_MEASURE 를 DIVISION_ID 로 걸러 보여준다.
           --    AND ( NVL(TRIM(@divisionId),'-')='-' OR INSTR(','||DIVISION_ID||',', ','||@divisionId||',')>0 )
           --  그런데 SP 는 개인화(TITLESET_USER TYPE='M') 만 읽어 마스터 검증이 없었다.
           --  KRW / USD 는 DIVISION_ID 가 NULL 이라 ','||NULL||',' = ',,' → 어느 division 에서도 모달에
           --  노출되지 않는다. 그래서 개인화에 남은 행을 사용자가 UI 로 지울 수 없고 그리드에만 나왔다.
           --  (AS-IS 도 동일 상태 — DIVISION_ID 공백. 사용자 지시 2026-09-10 로 조회에서 제외하도록 보완)
           --  판정 기준은 콤보와 동일하게 SCM_MST_SHEET_MEASURE + VALID_YN='Y' + DIVISION_ID 포함.
           AND EXISTS ( SELECT 1
                          FROM SCM_MGR.SCM_MST_SHEET_MEASURE M
                         WHERE M.PROGRAM_ID  = v_program_id
                           AND M.SHEET_NAME  = v_sheet_name
                           AND M.COLUMN_NAME = U.COLUMN_NAME
                           AND M.VALID_YN    = 'Y'
                           AND INSTR(',' || M.DIVISION_ID || ',', ',' || P_DIVISION_ID || ',') > 0 );

        DBMS_OUTPUT.PUT_LINE(v_program_id || ' : A002--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '=>' || TO_CHAR(SQL%ROWCOUNT));

        --=================================================================================================================================
        -- CURRENT버전 (AS-IS dump:189-328) — DM_PLN_BP_FCST(라이브) 월 적재 → 분기 → 연 3단 롤업
        --=================================================================================================================================
        IF ( UPPER(P_VERSION_TYPE) LIKE '%CURRENT%' ) THEN  --[E20260831-VERCASE] MSSQL CI 콜레이션 1:1 — 'Current' 등 대소문자 변형 흡수
            --MONTHLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT 'CURRENT' AS VERSION_NO
                 , NULL AS CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.YYYYMM
                 , CAL.CALENDAR_YYYYQQ AS CAL_YYYYQQ
                 , CAL.CALENDAR_YYYY AS CAL_YYYY
                 , A.QTY
                 , 'M_' || A.YYYYMM AS COLNAME
                 , A.DEPT_ID
                 , A.END_CUSTOMER
                 , A.BIZ_TYPE
                 , A.PROJECT_NAME
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.DM_PLN_BP_FCST A
              JOIN SCM_MGR.GT_DM22_SELECT_MEASURE B ON A.MEASURE = B.MEASURE
             INNER JOIN (SELECT CALENDAR_YYYY, CALENDAR_YYYYQQ, BASIS_YYYYMM
                           FROM SCM_MGR.SCM_SYS_CALENDAR_M
                          WHERE (BASIS_YYYYMM >= SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND BASIS_YYYYMM <= SUBSTR(P_TO_YYYYMMDD, 1, 6))
                          GROUP BY CALENDAR_YYYY, CALENDAR_YYYYQQ, BASIS_YYYYMM) CAL
                     ON CAL.BASIS_YYYYMM = A.YYYYMM
             WHERE A.YYYYMM >= SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND A.YYYYMM <= SUBSTR(P_TO_YYYYMMDD, 1, 6)
               AND A.DIVISION_ID = P_DIVISION_ID
            ;

            --QUATERLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT 'CURRENT' AS VERSION_NO
                 , NULL AS CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.CAL_YYYYQQ AS YYYYMM
                 , A.CAL_YYYYQQ AS CAL_YYYYQQ
                 , A.CAL_YYYY AS CAL_YYYY
                 , CASE WHEN MEASURE = 'SalesAmt_KRW' OR MEASURE = 'SalesAmt_LOC' OR MEASURE = 'SalesAmt_USD' OR MEASURE = 'Business_Plan'
                        THEN SUM(QTY)
                        ELSE MAX(QTY)
                   END QTY
                 , 'Q_' || REPLACE(A.CAL_YYYYQQ, 'Q', '_') AS COLNAME
                 , A.DEPT_ID
                 , MAX(A.END_CUSTOMER)
                 , MAX(A.BIZ_TYPE)
                 , MAX(A.PROJECT_NAME)
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.GT_DM51_RAW_DATA A
             GROUP BY A.DIVISION_ID
                    , A.PROJECT_CODE
                    , A.SCM_SITE_ID
                    , PLANT_SITE_ID
                    , A.ITEM_ID
                    , A.INCOTERMS
                    , A.CELL_PROD_SITE
                    , A.FCST_TYPE
                    , A.CURRENCY
                    , A.MEASURE
                    , A.YYYYMM
                    , A.CAL_YYYYQQ
                    , A.CAL_YYYY
                    , A.DEPT_ID
                    , A.ITEM_USE
                    , A.UNIT_ENERGY
            ;

            --YEARLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT 'CURRENT' AS VERSION_NO
                 , NULL AS CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.CAL_YYYY AS YYYYMM
                 , A.CAL_YYYY AS CAL_YYYYQQ
                 , A.CAL_YYYY
                 , CASE WHEN MEASURE = 'SalesAmt_KRW' OR MEASURE = 'SalesAmt_LOC' OR MEASURE = 'SalesAmt_USD' OR MEASURE = 'Business_Plan'
                        THEN SUM(QTY)
                        ELSE MAX(QTY)
                   END QTY
                 , 'Y_' || A.CAL_YYYY AS COLNAME
                 , A.DEPT_ID
                 , MAX(A.END_CUSTOMER)
                 , MAX(A.BIZ_TYPE)
                 , MAX(A.PROJECT_NAME)
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE COLNAME LIKE 'Q_%'
             GROUP BY A.DIVISION_ID
                    , A.PROJECT_CODE
                    , A.SCM_SITE_ID
                    , PLANT_SITE_ID
                    , A.ITEM_ID
                    , A.INCOTERMS
                    , A.CELL_PROD_SITE
                    , A.FCST_TYPE
                    , A.CURRENCY
                    , A.MEASURE
                    , A.YYYYMM
                    , A.CAL_YYYYQQ
                    , A.CAL_YYYY
                    , A.DEPT_ID
                    , A.ITEM_USE
                    , A.UNIT_ENERGY
            ;

        END IF;

        --=================================================================================================================================
        -- CUTOFF버전 (AS-IS dump:330-477) — DM_PLN_BP_FCST_C, 버전 필터 = GT_DM22_V_VERSION_NO ('(' 절단 사전분해)
        --=================================================================================================================================
        IF ( P_VERSION_TYPE LIKE '%BP_%' ) THEN   -- AS-IS 동일: '_' 는 1글자 와일드카드 (MSSQL LIKE 와 동의미 — 이스케이프 미사용 1:1)
            --MONTHLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT A.VERSION_NO
                 , A.CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , A.PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.YYYYMM
                 , CAL.CALENDAR_YYYYQQ AS CAL_YYYYQQ
                 , CAL.CALENDAR_YYYY AS CAL_YYYY
                 , A.QTY
                 , 'M_' || A.YYYYMM AS COLNAME
                 , A.DEPT_ID
                 , A.END_CUSTOMER
                 , A.BIZ_TYPE
                 , A.PROJECT_NAME
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.DM_PLN_BP_FCST_C A
              JOIN SCM_MGR.GT_DM22_SELECT_MEASURE B ON A.MEASURE = B.MEASURE
             INNER JOIN (SELECT CALENDAR_YYYY, CALENDAR_YYYYQQ, BASIS_YYYYMM
                           FROM SCM_MGR.SCM_SYS_CALENDAR_M
                          WHERE (BASIS_YYYYMM >= SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND BASIS_YYYYMM <= SUBSTR(P_TO_YYYYMMDD, 1, 6))
                          GROUP BY CALENDAR_YYYY, CALENDAR_YYYYQQ, BASIS_YYYYMM) CAL
                     ON CAL.BASIS_YYYYMM = A.YYYYMM
             WHERE A.YYYYMM >= SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND A.YYYYMM <= SUBSTR(P_TO_YYYYMMDD, 1, 6)
               AND A.DIVISION_ID = P_DIVISION_ID
               AND A.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM22_V_VERSION_NO)
            ;

            --QUATERLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT VERSION_NO
                 , A.CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , A.PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.CAL_YYYYQQ AS YYYYMM
                 , A.CAL_YYYYQQ AS CAL_YYYYQQ
                 , A.CAL_YYYY AS CAL_YYYY
                 , CASE WHEN MEASURE = 'SalesAmt_KRW' OR MEASURE = 'SalesAmt_LOC' OR MEASURE = 'SalesAmt_USD' OR MEASURE = 'Business_Plan'
                        THEN SUM(QTY)
                        ELSE MAX(QTY)
                   END QTY
                 , 'Q_' || REPLACE(A.CAL_YYYYQQ, 'Q', '_') AS COLNAME
                 , A.DEPT_ID
                 , MAX(A.END_CUSTOMER)
                 , MAX(A.BIZ_TYPE)
                 , MAX(A.PROJECT_NAME)
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE A.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM22_V_VERSION_NO)
               AND NOT (A.VERSION_NO = 'CURRENT')
             GROUP BY VERSION_NO
                    , A.DIVISION_ID
                    , A.CUTOFF_YYYYMMDD
                    , A.PROJECT_CODE
                    , A.SCM_SITE_ID
                    , A.PLANT_SITE_ID
                    , A.ITEM_ID
                    , A.INCOTERMS
                    , A.CELL_PROD_SITE
                    , A.FCST_TYPE
                    , A.CURRENCY
                    , A.MEASURE
                    , A.YYYYMM
                    , A.CAL_YYYYQQ
                    , A.CAL_YYYY
                    , A.DEPT_ID
                    , A.ITEM_USE
                    , A.UNIT_ENERGY
            ;

            --YEARLY
            INSERT INTO SCM_MGR.GT_DM51_RAW_DATA
                ( VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE, YYYYMM, CAL_YYYYQQ, CAL_YYYY, QTY
                , COLNAME, DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME, ITEM_USE, UNIT_ENERGY )
            SELECT VERSION_NO
                 , A.CUTOFF_YYYYMMDD
                 , A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , A.PLANT_SITE_ID
                 , A.ITEM_ID
                 , A.INCOTERMS
                 , A.CELL_PROD_SITE
                 , A.FCST_TYPE
                 , A.CURRENCY
                 , A.MEASURE
                 , A.CAL_YYYY AS YYYYMM
                 , A.CAL_YYYY AS CAL_YYYYQQ
                 , A.CAL_YYYY
                 , CASE WHEN MEASURE = 'SalesAmt_KRW' OR MEASURE = 'SalesAmt_LOC' OR MEASURE = 'SalesAmt_USD' OR MEASURE = 'Business_Plan'
                        THEN SUM(QTY)
                        ELSE MAX(QTY)
                   END QTY
                 , 'Y_' || A.CAL_YYYY AS COLNAME
                 , A.DEPT_ID
                 , MAX(A.END_CUSTOMER)
                 , MAX(A.BIZ_TYPE)
                 , MAX(A.PROJECT_NAME)
                 , A.ITEM_USE
                 , A.UNIT_ENERGY
              FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE A.VERSION_NO IN (SELECT VERSION_NO FROM SCM_MGR.GT_DM22_V_VERSION_NO)
               AND NOT (A.VERSION_NO = 'CURRENT')
               AND A.COLNAME LIKE 'Q_%'
             GROUP BY VERSION_NO
                    , A.DIVISION_ID
                    , A.CUTOFF_YYYYMMDD
                    , A.PROJECT_CODE
                    , A.SCM_SITE_ID
                    , PLANT_SITE_ID
                    , A.ITEM_ID
                    , A.INCOTERMS
                    , A.CELL_PROD_SITE
                    , A.FCST_TYPE
                    , A.CURRENCY
                    , A.MEASURE
                    , A.YYYYMM
                    , A.CAL_YYYYQQ
                    , A.CAL_YYYY
                    , A.DEPT_ID
                    , A.ITEM_USE
                    , A.UNIT_ENERGY
            ;
        END IF;

        DBMS_OUTPUT.PUT_LINE(v_program_id || ' : A--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '=>' || TO_CHAR(SQL%ROWCOUNT));

        --=================================================================================================================================
        --[E20240920-000300]_SCM.DM 화면 조회 속도 개선 START (AS-IS dump:505-616)
        --> SCM_MST_ITEM_SN 테이블을 TEMP로 넣는다. (0022 선례 — 명시 컬럼 리스트)
        --=================================================================================================================================
        INSERT INTO SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_ORI_V
              (COMPANY_ID, DIVISION_ID, SITE_ID, ITEM_ID, ITEM_NAME, NICK_NAME, ITEM_TYPE
              ,ITEM_CLASS_LEVEL_1, ITEM_CLASS_LEVEL_2, ITEM_CLASS_LEVEL_3, ITEM_CLASS_LEVEL_4
              ,ITEM_CLASS, ITEM_CLASS_NAME, MATERIAL_CLASS, MATERIAL_CLASS_NAME, ELECTRODE_TYPE, SIDE_TYPE
              ,ITEM_GROUP_ID, SETUP_GROUP_ID_1, SETUP_GROUP_ID_2, SETUP_GROUP_ID_3, FLOW_ID, ERP_EOL, SCP_EOL
              ,ITEM_UOM, SPEC, DEMAND_LOT_SIZE, ITEM_ATTRIBUTE, SETUP_ATTRIBUTE, BATCH_RATIO_ID, OUTSOURCING_FACTORY
              ,FINITE_TERM, FINITE_TERM_UOM, COATED_LENGTH, UNCOATED_LENGTH, LENGTH_UOM, SLURRY_LOSS_RATE
              ,DESCRIPTION, ACTIVE_FLAG, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, APPLIED_MODEL, CELL_TYPE
              ,MAKE_AND_BUY, COLOR_ATTRIBUTE, FORMATION_FLOW_ID, STANDARD_COST, CURRENCY, FORM_ATTRIBUTE, ENERGE
              ,SCP_FLOW_ID, SCP_OPERATION_GROUP, SCP_OPERATION_GROUP_ID, MDM_PROJECT_NAME, MIN_CAPACITY, MOBILE_MODEL_ID
              ,FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_PRODUCT_GROUP, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT
              ,FORECAST_INFO_SPEC, FORECAST_INFOR_VERSION, DOE, INSULATION_COATING, PACK_PRODUCT_GROUP_CODE
              ,CELL_QUANTITY, SCP_EXTRA_SPEC, SCM_PIC, REP_CUSTOMER, MAKER, EVAL_CLASS, EVAL_CLASS_INFO
              ,FP_EXTRA_SPEC, MRP_USE_FLAG, ITEM_RAW_PLANT_ID, ITEM_COPY_YN)
        SELECT COMPANY_ID, DIVISION_ID, SITE_ID, ITEM_ID, ITEM_NAME, NICK_NAME, ITEM_TYPE
              ,ITEM_CLASS_LEVEL_1, ITEM_CLASS_LEVEL_2, ITEM_CLASS_LEVEL_3, ITEM_CLASS_LEVEL_4
              ,ITEM_CLASS, ITEM_CLASS_NAME, MATERIAL_CLASS, MATERIAL_CLASS_NAME, ELECTRODE_TYPE, SIDE_TYPE
              ,ITEM_GROUP_ID, SETUP_GROUP_ID_1, SETUP_GROUP_ID_2, SETUP_GROUP_ID_3, FLOW_ID, ERP_EOL, SCP_EOL
              ,ITEM_UOM, SPEC, DEMAND_LOT_SIZE, ITEM_ATTRIBUTE, SETUP_ATTRIBUTE, BATCH_RATIO_ID, OUTSOURCING_FACTORY
              ,FINITE_TERM, FINITE_TERM_UOM, COATED_LENGTH, UNCOATED_LENGTH, LENGTH_UOM, SLURRY_LOSS_RATE
              ,DESCRIPTION, ACTIVE_FLAG, INSERT_ID, INSERT_TIME, UPDATE_ID, UPDATE_TIME, APPLIED_MODEL, CELL_TYPE
              ,MAKE_AND_BUY, COLOR_ATTRIBUTE, FORMATION_FLOW_ID, STANDARD_COST, CURRENCY, FORM_ATTRIBUTE, ENERGE
              ,SCP_FLOW_ID, SCP_OPERATION_GROUP, SCP_OPERATION_GROUP_ID, MDM_PROJECT_NAME, MIN_CAPACITY, MOBILE_MODEL_ID
              ,FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_PRODUCT_GROUP, FORECAST_INFO_CELL_MODEL, FORECAST_INFO_CELL_PACK_COUNT
              ,FORECAST_INFO_SPEC, FORECAST_INFOR_VERSION, DOE, INSULATION_COATING, PACK_PRODUCT_GROUP_CODE
              ,CELL_QUANTITY, SCP_EXTRA_SPEC, SCM_PIC, REP_CUSTOMER, MAKER, EVAL_CLASS, EVAL_CLASS_INFO
              ,FP_EXTRA_SPEC, MRP_USE_FLAG, ITEM_RAW_PLANT_ID, ITEM_COPY_YN
          FROM SCM_MGR.SCM_MST_ITEM_SN
         WHERE DIVISION_ID = P_DIVISION_ID
        --[E20260820-D51ITEMPFX] hook #129 ④ 선행축소 — 소비되지 않는 품목을 GTT 에 싣지 않는다.
        --  ⚠ 축소 단위는 반드시 SUBSTR(ITEM_ID,1,12) prefix.
        --     하류 _B_V 가 (DIVISION_ID, SUBSTR(ITEM_ID,1,12)) 로 MAX 집계하므로 정확 ITEM_ID 로 축소하면
        --     같은 prefix 를 공유하는 형제 품목이 빠져 MAX 그룹이 바뀐다(값 등가 파괴). prefix 단위면 그룹 원형 보존.
        --  전제(정적 확인): GT_DM51_RAW_DATA 의 INSERT 는 전부 이 문장보다 위(본문 688/727/777/834/874/928)에서 끝나고,
        --     이 아래는 DELETE(1215~1324) 뿐이라 prefix 집합은 최종 집합의 상위집합 → 축소 과소 위험 없음.
        --  등가: 소비처는 모두 정확 (DIVISION_ID, ITEM_ID) 로 조인/EXISTS 하며, RAW_DATA 의 ITEM_ID 는
        --     정의상 자기 prefix 가 집합에 있으므로 SN 에 존재하면 반드시 잔류한다(=조인 결과 불변).
        --  사내 div40 실측: 243,050행 → 6,053행 (-97.5%), 원장 prefix 899종
           AND SUBSTR(ITEM_ID, 1, 12) IN (SELECT DISTINCT SUBSTR(R.ITEM_ID, 1, 12)
                                            FROM SCM_MGR.GT_DM51_RAW_DATA R)
        ;

        --멈춤 현상이 발생하므로, 아예 모두 나눠서 INSERT 한다.
        INSERT INTO SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_A_V
              (DIVISION_ID, ITEM_ID, ITEM_NAME, ITEM_CLASS, ITEM_CLASS_NAME, NICK_NAME, ITEM_TYPE
              ,MATERIAL_CLASS_NAME, ITEM_UOM, SPEC, MDM_PROJECT_NAME, MIN_CAPACITY, ACTIVE_FLAG
              ,ENERGE, CELL_QUANTITY, SCP_EXTRA_SPEC)
        SELECT T1.DIVISION_ID
             , T1.ITEM_ID
             , MAX(T1.ITEM_NAME)                        AS ITEM_NAME
             , MAX(T1.ITEM_CLASS)                       AS ITEM_CLASS
             , MAX(T1.ITEM_CLASS_NAME)                  AS ITEM_CLASS_NAME
             , MAX(T1.NICK_NAME)                        AS NICK_NAME
             , CASE MIN( CASE WHEN T1.ITEM_TYPE = 'P' THEN 1
                              WHEN T1.ITEM_TYPE = 'H' THEN 2
                              WHEN T1.ITEM_TYPE = 'Q' THEN 3
                         ELSE 4 END )
                                        WHEN 1 THEN 'P'
                                        WHEN 2 THEN 'H'
                                        WHEN 3 THEN 'Q'
                                        ELSE 'R' END    AS ITEM_TYPE
             , MAX(T1.MATERIAL_CLASS_NAME)              AS MATERIAL_CLASS_NAME
             , MAX(T1.ITEM_UOM)                         AS ITEM_UOM
             , MAX(T1.SPEC)                             AS SPEC
             , MAX(T1.MDM_PROJECT_NAME)                 AS MDM_PROJECT_NAME
             , MAX(T1.MIN_CAPACITY)                     AS MIN_CAPACITY
             , MAX(T1.ACTIVE_FLAG)                      AS ACTIVE_FLAG
             , MAX(T1.ENERGE)                           AS ENERGE
             , MAX(T1.CELL_QUANTITY)                    AS CELL_QUANTITY
             , MAX(T1.SCP_EXTRA_SPEC)                   AS SCP_EXTRA_SPEC
          FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_ORI_V T1
         WHERE 1=1
         GROUP BY T1.DIVISION_ID, T1.ITEM_ID
        ;

        --멈춤 현상이 발생하므로, 아예 모두 나눠서 INSERT 한다.
        INSERT INTO SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_B_V
              (DIVISION_ID, ITEM_ID, FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_PRODUCT_GROUP, FORECAST_INFO_CELL_MODEL
              ,FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_SPEC, FORECAST_INFOR_VERSION, CELL_TYPE)
        SELECT DIVISION_ID
             , SUBSTR(ITEM_ID, 1, 12) AS ITEM_ID
             , MAX(FORECAST_INFO_BIZ_TYPE) AS FORECAST_INFO_BIZ_TYPE
             , MAX(FORECAST_INFO_PRODUCT_GROUP) AS FORECAST_INFO_PRODUCT_GROUP
             , MAX(FORECAST_INFO_CELL_MODEL) AS FORECAST_INFO_CELL_MODEL
             , MAX(FORECAST_INFO_CELL_PACK_COUNT) AS FORECAST_INFO_CELL_PACK_COUNT
             , MAX(FORECAST_INFO_SPEC) AS FORECAST_INFO_SPEC
             , MAX(FORECAST_INFOR_VERSION) AS FORECAST_INFOR_VERSION
             , MAX(CELL_TYPE) AS CELL_TYPE
          FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_ORI_V T2
         GROUP BY DIVISION_ID, SUBSTR(ITEM_ID, 1, 12)
        ;

        --TEMP 테이블에 넣은 데이터를 JOIN 한다. (AS-IS dump:555-614 — 0022 와 달리 RAW_DATA 필터 없음, 1:1 유지)
        INSERT INTO SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_V
              (DIVISION_ID, ITEM_ID, ITEM_NAME, ITEM_CLASS, ITEM_CLASS_NAME, NICK_NAME, ITEM_TYPE
              ,MATERIAL_CLASS_NAME, ITEM_UOM, SPEC, MDM_PROJECT_NAME, MIN_CAPACITY
              ,FORECAST_INFO_BIZ_TYPE, FORECAST_INFO_PRODUCT_GROUP, FORECAST_INFO_CELL_MODEL
              ,FORECAST_INFO_CELL_PACK_COUNT, FORECAST_INFO_SPEC, FORECAST_INFOR_VERSION
              ,ACTIVE_FLAG, CELL_TYPE, ENERGE, CELL_QUANTITY, SCP_EXTRA_SPEC)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.ITEM_NAME
             , A.ITEM_CLASS
             , A.ITEM_CLASS_NAME
             , A.NICK_NAME
             , A.ITEM_TYPE
             , A.MATERIAL_CLASS_NAME
             , A.ITEM_UOM
             , A.SPEC
             , A.MDM_PROJECT_NAME
             , A.MIN_CAPACITY
             , A.FORECAST_INFO_BIZ_TYPE
             , A.FORECAST_INFO_PRODUCT_GROUP
             , A.FORECAST_INFO_CELL_MODEL
             , A.FORECAST_INFO_CELL_PACK_COUNT
             , A.FORECAST_INFO_SPEC
             , A.FORECAST_INFOR_VERSION
             , A.ACTIVE_FLAG
             , A.CELL_TYPE
             , A.ENERGE
             , A.CELL_QUANTITY
             , A.SCP_EXTRA_SPEC
          FROM
          (
              SELECT T1.DIVISION_ID
                   , T1.ITEM_ID
                   , T1.ITEM_NAME                          AS ITEM_NAME
                   , T1.ITEM_CLASS                         AS ITEM_CLASS
                   , T1.ITEM_CLASS_NAME                    AS ITEM_CLASS_NAME
                   , T1.NICK_NAME                          AS NICK_NAME
                   , T1.ITEM_TYPE                          AS ITEM_TYPE
                   , T1.MATERIAL_CLASS_NAME                AS MATERIAL_CLASS_NAME
                   , T1.ITEM_UOM                           AS ITEM_UOM
                   , T1.SPEC                               AS SPEC
                   , T1.MDM_PROJECT_NAME                   AS MDM_PROJECT_NAME
                   , T1.MIN_CAPACITY                       AS MIN_CAPACITY
                   , T2.FORECAST_INFO_BIZ_TYPE             AS FORECAST_INFO_BIZ_TYPE
                   , T2.FORECAST_INFO_PRODUCT_GROUP        AS FORECAST_INFO_PRODUCT_GROUP
                   , T2.FORECAST_INFO_CELL_MODEL           AS FORECAST_INFO_CELL_MODEL
                   , T2.FORECAST_INFO_CELL_PACK_COUNT      AS FORECAST_INFO_CELL_PACK_COUNT
                   , T2.FORECAST_INFO_SPEC                 AS FORECAST_INFO_SPEC
                   , T2.FORECAST_INFOR_VERSION             AS FORECAST_INFOR_VERSION
                   , T1.ACTIVE_FLAG                        AS ACTIVE_FLAG
                   , T2.CELL_TYPE                          AS CELL_TYPE
                   , T1.ENERGE                             AS ENERGE
                   , T1.CELL_QUANTITY                      AS CELL_QUANTITY
                   , T1.SCP_EXTRA_SPEC                     AS SCP_EXTRA_SPEC
                FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_A_V T1
               INNER JOIN SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_B_V T2
                       ON T1.DIVISION_ID = T2.DIVISION_ID
                      AND SUBSTR(T1.ITEM_ID, 1, 12) = T2.ITEM_ID
               WHERE 1=1
          ) A
        --[E20260820-D51REGROUP] 무용 GROUP BY 제거 (값 무영향 — 증명):
        --  A_V = GROUP BY (DIVISION_ID, ITEM_ID)           → (DIVISION_ID, ITEM_ID) 유일
        --  B_V = GROUP BY (DIVISION_ID, SUBSTR(ITEM_ID,1,12)) → 조인키당 최대 1행
        --  ⇒ 인라인뷰 A 는 이미 (DIVISION_ID, ITEM_ID) 유일이고 GROUP BY 목록이 그 두 컬럼을 포함하므로
        --    전 컬럼 GROUP BY 는 항등 연산(행 축약 0). 사내 실측 169,928행 IN = 169,928행 OUT.
        ;
        --[E20240920-000300]_SCM.DM 화면 조회 속도 개선 END

        DBMS_OUTPUT.PUT_LINE(v_program_id || ' : B--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '=>' || TO_CHAR(SQL%ROWCOUNT));

        --AS-IS CREATE CLUSTERED INDEX IDX1_TEMP_DM_MST_ITEM_SINGLE_V (division_id, item_id)
        -- → Oracle GTT: 세션 통계 수집으로 대체 (0022 선례)
        DBMS_STATS.GATHER_TABLE_STATS('SCM_MGR','GT_DM22_DM_MST_ITEM_SINGLE_V',
            estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1', no_invalidate => FALSE);

        --=================================================================================================================================
        -- SCM_MST_SSO_USER_INFO 임시테이블(#TEMP_SCM_MST_SSO_USER_INFO — 단순 사본) → 0022 선례대로 원 테이블 직접 조회로 대체
        -- SCM_MST_SITE_ITEM 임시테이블 생성 (AS-IS dump:634-647)
        --=================================================================================================================================
        INSERT INTO SCM_MGR.GT_DM51_SCM_MST_SITE_ITEM
            (DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, CURRENCY, CUST_GROUP
            ,CUST_GROUP_DTL, APPLICATION, ROUTE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE5
            ,REPORT_GROUP1, REPORT_GROUP2, REPORT_GROUP3, REPORT_GROUP4, REPORT_GROUP5
            ,REPORT_GROUP6, OWNER, CELL_PER_CAR, CELL_PER_MODULE
            ,OWNER_NAME, OWNER_NAME_KO, DEPT_ID)
        --[E20260820-D51SCALAR] hook #129 ① SELECT 목록 행별 상관 스칼라/함수 제거 → 선계산 + LEFT JOIN
        --  FN_GET_DM_MKT_OWNER_NAME(EN/KO) 와 DEPT_ID 스칼라 서브쿼리는 모두 OWNER 만의 결정함수이므로
        --  DISTINCT OWNER 당 1회만 평가한 뒤 조인한다. 값 산식·NULL 거동(미매칭 → NULL) 원본 동일.
        --  사내 div40 실측: 대상 23,193행 / DISTINCT OWNER 88종 (함수·서브쿼리 평가 69,579회 → 264회)
        SELECT SMSI.DIVISION_ID, SMSI.SCM_SITE_ID, SMSI.PROJECT_CODE, SMSI.ITEM_ID, SMSI.CURRENCY, SMSI.CUST_GROUP
             , SMSI.CUST_GROUP_DTL, SMSI.APPLICATION, SMSI.ROUTE, SMSI.ATTRIBUTE1, SMSI.ATTRIBUTE2, SMSI.ATTRIBUTE5
             , SMSI.REPORT_GROUP1, SMSI.REPORT_GROUP2, SMSI.REPORT_GROUP3, SMSI.REPORT_GROUP4, SMSI.REPORT_GROUP5
             , SMSI.REPORT_GROUP6, SMSI.OWNER, SMSI.CELL_PER_CAR, SMSI.CELL_PER_MODULE
             , OW.OWNER_NAME                                                          AS OWNER_NAME
             , OW.OWNER_NAME_KO                                                       AS OWNER_NAME_KO
             , SMSI.DEPT_ID                                                           AS DEPT_ID  -- 2026-09-06 hook#150 AJS (AS-IS: OW.DEPT_ID = OWNER 경유)
          FROM SCM_MGR.SCM_MST_SITE_ITEM SMSI
          LEFT JOIN ( SELECT O.OWNER                                                  AS OWNER
                           , SCM_MGR.FN_GET_DM_MKT_OWNER_NAME(O.OWNER, ',', 'EN')     AS OWNER_NAME
                           , SCM_MGR.FN_GET_DM_MKT_OWNER_NAME(O.OWNER, ',', 'KO')     AS OWNER_NAME_KO
                           -- [hook#150 2026-09-06 AJS] AS-IS: , ( SELECT SU.DEPT_ID
                                 -- [hook#150 2026-09-06 AJS] AS-IS: FROM SCM_MGR.SCM_MST_SSO_USER_INFO SU
                                -- [hook#150 2026-09-06 AJS] AS-IS: WHERE SU.USER_ID = (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(O.OWNER, ',')) P WHERE ROWNUM = 1)
                             -- [hook#150 2026-09-06 AJS] AS-IS: ) AS DEPT_ID
                        FROM ( SELECT DISTINCT OWNER
                                 FROM SCM_MGR.SCM_MST_SITE_ITEM
                                WHERE DIVISION_ID = P_DIVISION_ID ) O
                    ) OW
                 ON OW.OWNER = SMSI.OWNER
         WHERE SMSI.DIVISION_ID = P_DIVISION_ID
        ;

        DBMS_STATS.GATHER_TABLE_STATS('SCM_MGR','GT_DM51_SCM_MST_SITE_ITEM',
            estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1', no_invalidate => FALSE);

        --=================================================================================================================================
        -- CITY, COUNTRY 취득할 임시테이블 생성 (AS-IS dump:650-678 1:1)
        --=================================================================================================================================
        INSERT INTO SCM_MGR.GT_DM51_SCM_CITY
            (DIVISION_ID, SOLDTO_CUSTOMER, END_CUSTOMER, DEPT_ID, SCM_SITE_ID, VMI_YN, VALID_YN, CITY_NAME, COUNTRY_NAME)
        SELECT S.DIVISION_ID
             , S.SOLDTO_CUSTOMER
             , S.END_CUSTOMER
             , SI.DEPT_ID  -- 2026-09-06 hook#150 AJS: DEPT_ID 원천 = SCM_MST_SITE_ITEM.DEPT_ID (SCM_MST_SITE.DEPT_ID 삭제 예정 / OWNER 경유 폐기) (AS-IS: S.DEPT_ID = SCM_MST_SITE.DEPT_ID)
             , S.SCM_SITE_ID
             , S.VMI_YN
             , S.VALID_YN
             , S.CITY_NAME
             , S.COUNTRY_NAME
          FROM SCM_MGR.DM_PLN_BP_FCST A
          LEFT JOIN (SELECT X.DIVISION_ID
                          , X.SOLDTO_CUSTOMER
                          , X.END_CUSTOMER
                          -- [hook#150 2026-09-06 AJS] AS-IS: , X.DEPT_ID
                          , X.SCM_SITE_ID
                          , X.VMI_YN
                          , X.VALID_YN
                          , Y.CITY_NAME
                          , Z.COUNTRY_NAME
                       FROM SCM_MGR.SCM_MST_SITE    X
                          , SCM_MGR.SCM_MST_CITY    Y
                          , SCM_MGR.SCM_MST_COUNTRY Z
                      WHERE X.CITY = Y.CITY AND X.COUNTRY = Z.COUNTRY
                    ) S
                 ON A.DIVISION_ID = S.DIVISION_ID
                AND A.SCM_SITE_ID = S.SCM_SITE_ID
          LEFT JOIN SCM_MGR.SCM_MST_SITE_ITEM SI  -- 2026-09-06 hook#150 AJS: DEPT_ID 원천 (A 의 PK 4키 1:1 -> 건수 불변)
                 ON SI.DIVISION_ID  = A.DIVISION_ID
                AND SI.PROJECT_CODE = A.PROJECT_CODE
                AND SI.SCM_SITE_ID  = A.SCM_SITE_ID
                AND SI.ITEM_ID      = A.ITEM_ID
         WHERE A.DIVISION_ID = P_DIVISION_ID
        ;

        DBMS_STATS.GATHER_TABLE_STATS('SCM_MGR','GT_DM51_SCM_CITY',
            estimate_percent => DBMS_STATS.AUTO_SAMPLE_SIZE, method_opt => 'FOR ALL COLUMNS SIZE 1', no_invalidate => FALSE);

        --=================================================================================================================================
        -- 조회조건에 따른 필터링 처리 ( PRICE 계산시 부하문제로 필터링은 여기서 하고, 필요없는 메저는 PRICE 끝난 후 제거 )
        -- (AS-IS dump:680-875 — DELETE+LEFT JOIN → DELETE WHERE NOT EXISTS, 0022 선례 형식)
        --=================================================================================================================================
        -- 필터링 시작
        IF NVL(P_PROJECT_CODE, '@#@#@#') <> '@#@#@#' THEN -- 소형은 UI 에서 PROJECT DISABLE 됨
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE NOT EXISTS (
                       SELECT 1 FROM SCM_MGR.SCM_MST_PROJECT B
                        WHERE A.DIVISION_ID  = B.DIVISION_ID
                          AND A.PROJECT_CODE = B.PROJECT_CODE
                          AND (EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_PROJECT_CODE,'^',','),',')) P WHERE B.PROJECT_CODE LIKE '%' || P.TOKEN || '%')
                               OR
                               EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_PROJECT_CODE,'^',','),',')) P WHERE B.PROJECT_NAME LIKE '%' || P.TOKEN || '%')
                              )
                   );
        END IF;

        IF NVL(P_ITEM_ID, '@#@#@#') <> '@#@#@#' THEN
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE NOT EXISTS (
                       SELECT 1 FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_V B
                        WHERE A.ITEM_ID = B.ITEM_ID
                          AND (EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_ITEM_ID,'^',','),',')) P WHERE A.ITEM_ID LIKE '%' || P.TOKEN || '%')
                               OR
                               EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_ITEM_ID,'^',','),',')) P WHERE B.NICK_NAME LIKE '%' || P.TOKEN || '%')
                              )
                   );
        END IF;

        IF NVL(P_OWNER, '@#@#@#') <> '@#@#@#' THEN
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE NOT EXISTS (
                       SELECT 1 FROM SCM_MGR.GT_DM51_SCM_MST_SITE_ITEM B
                        WHERE A.ITEM_ID      = B.ITEM_ID
                          AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                          AND A.PROJECT_CODE = B.PROJECT_CODE
                          AND (EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_OWNER,'^',','),',')) P WHERE B.OWNER LIKE '%' || P.TOKEN || '%')
                               OR
                               EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_OWNER,'^',','),',')) P WHERE B.OWNER_NAME LIKE '%' || P.TOKEN || '%')
                               OR
                               EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_OWNER,'^',','),',')) P WHERE B.OWNER_NAME_KO LIKE '%' || P.TOKEN || '%')
                              )
                   );
        END IF;

        IF P_DEPT_ID <> 'ALL' THEN
            --[PJ2024-50461] Team Mapping------------------------------------
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE NOT EXISTS (
                       SELECT 1 FROM SCM_MGR.GT_DM51_SCM_MST_SITE_ITEM B
                        WHERE A.ITEM_ID      = B.ITEM_ID
                          AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                          AND A.PROJECT_CODE = B.PROJECT_CODE
                          AND B.DEPT_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_DEPT_ID,'^',','),',')) P)
                   );
        END IF;

        IF P_END_CUSTOMER <> 'ALL' THEN
            IF P_DIVISION_ID = '40' THEN
                DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
                 WHERE A.PROJECT_CODE NOT IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_END_CUSTOMER,'^',','),',')) P)
                ;
            ELSE
                DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
                 WHERE NOT EXISTS (
                           SELECT 1 FROM SCM_MGR.SCM_MST_SITE B
                            WHERE A.SCM_SITE_ID = B.SCM_SITE_ID AND B.DIVISION_ID = P_DIVISION_ID
                              AND B.END_CUSTOMER IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_END_CUSTOMER,'^',','),',')) P)
                       );
            END IF;
        END IF;

        IF P_SCM_SITE_ID <> 'ALL' THEN
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE A.SCM_SITE_ID NOT IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_SCM_SITE_ID,'^',','),',')) P)
            ;
        END IF;

        IF P_PLANT_SITE_ID <> 'ALL' THEN
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE A.PLANT_SITE_ID NOT IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_PLANT_SITE_ID,'^',','),',')) P)
            ;
        END IF;

        IF P_ITEM_TYPE <> 'ALL' THEN
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE NOT EXISTS (
                       SELECT 1 FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_V B
                        WHERE A.ITEM_ID = B.ITEM_ID
                          AND B.ITEM_TYPE IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_ITEM_TYPE,'^',','),',')) P)
                   );
        END IF;

        IF P_BIZTYPE <> 'ALL' THEN
            IF P_DIVISION_ID = '40' THEN
                DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
                 WHERE NOT EXISTS (
                           SELECT 1 FROM SCM_MGR.GT_DM22_DM_MST_ITEM_SINGLE_V B
                            WHERE A.ITEM_ID = B.ITEM_ID
                              AND B.FORECAST_INFO_BIZ_TYPE IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_BIZTYPE,'^',','),',')) P)
                       );
            ELSE
                DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
                 WHERE NOT EXISTS (
                           SELECT 1 FROM SCM_MGR.SCM_MST_PROJECT B
                            WHERE A.DIVISION_ID  = B.DIVISION_ID
                              AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND EXISTS (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(REPLACE(P_BIZTYPE,'^',','),',')) P WHERE B.BIZ_TYPE LIKE '%' || P.TOKEN || '%')
                       );
            END IF;
        END IF;

        IF P_QTY_YN = 'Y' THEN
            -- [C20221107-000343]BP Waterfall 오류 수정 요청의 건 — Business_Plan SUM(QTY)=0 차원조합 전체 제거
            DELETE FROM SCM_MGR.GT_DM51_RAW_DATA A
             WHERE EXISTS (
                       SELECT 1
                         FROM (SELECT VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                                    , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE
                                    , DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME
                                 FROM SCM_MGR.GT_DM51_RAW_DATA
                                WHERE MEASURE = 'Business_Plan'
                                GROUP BY VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID
                                       , INCOTERMS, CELL_PROD_SITE, FCST_TYPE, CURRENCY, MEASURE
                                       , DEPT_ID, END_CUSTOMER, BIZ_TYPE, PROJECT_NAME
                               HAVING SUM(QTY) = 0) B
                        WHERE A.VERSION_NO     = B.VERSION_NO
                          AND A.DIVISION_ID    = B.DIVISION_ID
                          AND A.PROJECT_CODE   = B.PROJECT_CODE
                          AND A.SCM_SITE_ID    = B.SCM_SITE_ID
                          AND A.ITEM_ID        = B.ITEM_ID
                          AND A.FCST_TYPE      = B.FCST_TYPE
                          AND A.PLANT_SITE_ID  = B.PLANT_SITE_ID
                          AND A.DEPT_ID        = B.DEPT_ID
                          AND A.END_CUSTOMER   = B.END_CUSTOMER
                          AND A.BIZ_TYPE       = B.BIZ_TYPE
                          AND A.CURRENCY       = B.CURRENCY
                          AND A.INCOTERMS      = B.INCOTERMS
                          AND A.CELL_PROD_SITE = B.CELL_PROD_SITE
                   );
        END IF;
        -- 필터링 끝

        DBMS_OUTPUT.PUT_LINE(v_program_id || ' : C--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || '=>' || TO_CHAR(SQL%ROWCOUNT));

        --=================================================================================================================================
        -- 컬럼리스트 만들고, MKT FCST 와 비슷한 방식으로, CTE 로 데이터를 만들고, CTE SELECT 문에 컬럼리스트 삽입한다.
        --=================================================================================================================================

        -----   날짜컬럼 (AS-IS dump:897-937 c_bucket FAST_FORWARD 커서 → FOR 루프, 0022 선례) -----------------------------------------
        -- [C20221107-000343]BP Waterfall 오류 수정 요청의 건
        V_PV_LIST     := '';
        V_PV_COL_LIST := '';

        FOR r IN (
            SELECT COLUMN_NAME, PV_NAME, SORT_ORDER_NO
              FROM (
                       -- MONTHLY
                       SELECT '''M_' || A.BASIS_YYYYMM || '''  AS M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                            , 'M_' || A.BASIS_YYYYMM || ' ' AS PV_NAME
                            , MIN(A.BASIS_START_DATE) || '_' || TO_CHAR(1, 'FM00') AS SORT_ORDER_NO
                         FROM SCM_MGR.SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                          AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                        GROUP BY A.BASIS_YYYYMM
                       UNION ALL
                       -- QUATERLY
                       SELECT '''Q_' || REPLACE(A.CALENDAR_YYYYQQ, 'Q', '_') || '''  AS Q_' || REPLACE(A.CALENDAR_YYYYQQ, 'Q', '_') AS COLUMN_NAME
                            , 'Q_' || REPLACE(A.CALENDAR_YYYYQQ, 'Q', '_') || ' ' AS PV_NAME
                            , MIN(A.BASIS_START_DATE) || '_' || TO_CHAR(1, 'FM00') AS SORT_ORDER_NO
                         FROM SCM_MGR.SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                          AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                        GROUP BY A.CALENDAR_YYYYQQ
                       UNION ALL
                       -- YEARLY
                       SELECT '''Y_' || A.CALENDAR_YYYY || '''  AS Y_' || A.CALENDAR_YYYY AS COLUMN_NAME
                            , 'Y_' || A.CALENDAR_YYYY || ' ' AS PV_NAME
                            , MIN(A.BASIS_START_DATE) || '_' || TO_CHAR(1, 'FM00') AS SORT_ORDER_NO
                         FROM SCM_MGR.SCM_SYS_CALENDAR_M A
                        WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                          AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                        GROUP BY A.CALENDAR_YYYY
                   )
             ORDER BY SORT_ORDER_NO
        ) LOOP
            IF V_PV_COL_LIST IS NOT NULL AND LENGTH(V_PV_COL_LIST) > 0 THEN
                V_PV_COL_LIST := V_PV_COL_LIST || ',' || r.COLUMN_NAME || CHR(10);
                V_PV_LIST     := V_PV_LIST     || ',' || r.PV_NAME || CHR(10);
            ELSE
                V_PV_COL_LIST := r.COLUMN_NAME || CHR(10);
                V_PV_LIST     := r.PV_NAME || CHR(10);
            END IF;
        END LOOP;

        -----   일반 컬럼 (AS-IS dump:940-1016) ---------------------------------------------------------------------------------------
        SELECT COUNT(*)
          INTO i_count
          FROM SCM_MGR.SCM_MST_TITLESET_USER U
         WHERE 1 = 1
           AND U.PROGRAM_ID = v_program_id
           AND U.SHEET_NAME = v_sheet_name
           AND U.USER_ID    = P_CREATED_BY
           AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C';

        IF i_count = 0 THEN
            FOR r IN (
                -- ★★ ORDER BY 가능하려면 컬럼정의 100개 넘지 않아야함
                SELECT C.SORT_ORDER_NO
                     , C.COLUMN_NAME, C.DATA_SORT_METHOD_CODE
                  FROM SCM_MGR.SCM_MST_SHEET_COLUMNS C
                 WHERE 1 = 1
                   AND C.PROGRAM_ID = v_program_id
                   AND C.SHEET_NAME = v_sheet_name
                   AND ( C.DEFAULT_FLAG = 'Y' OR
                       (     C.VISIBLE_FLAG = 'N'
                         AND RTRIM(C.DEFAULT_FLAG, ' -') IS NULL   --[E20260806-00979] 빈값 판정: 공백(' ')과 '-' 동일 취급 (데이터 무수정 방침 — 클라우드 '-' 변형 흡수)
                         AND C.VALID_YN     = 'Y'
                       )
                       )
                 ORDER BY SORT_ORDER_NO
            ) LOOP
                IF v_ColList IS NOT NULL AND LENGTH(v_ColList) > 0 THEN
                    v_ColList   := v_ColList   || ',' || r.COLUMN_NAME || ' ' || CHR(10);
                    v_OrderList := v_OrderList || ',' || r.COLUMN_NAME || ' ' || r.DATA_SORT_METHOD_CODE || CHR(10);
                ELSE
                    v_ColList   := ' ' || r.COLUMN_NAME || ' ' || CHR(10);
                    v_OrderList := ' ' || r.COLUMN_NAME || ' ' || r.DATA_SORT_METHOD_CODE || CHR(10);
                END IF;
            END LOOP;
        ELSE
            FOR r IN (
                SELECT U.SORT_ORDER_NO, C.COLUMN_NAME, U.DATA_SORT_METHOD_CODE
                  FROM SCM_MGR.SCM_MST_TITLESET_USER U
                 INNER JOIN SCM_MGR.SCM_MST_SHEET_COLUMNS C
                         ON U.PROGRAM_ID  = C.PROGRAM_ID
                        AND U.SHEET_NAME  = C.SHEET_NAME
                        AND U.COLUMN_NAME = C.COLUMN_NAME
                        AND U.PROGRAM_ID  = v_program_id
                        AND U.SHEET_NAME  = v_sheet_name
                        AND U.USER_ID     = P_CREATED_BY
                        AND U.USER_INQUIRY_COLUMN_TYPE_CODE = 'C'
                        -- [C20221107-000343]BP Waterfall 오류 수정 요청의 건
                        AND P_DIVISION_ID IN (SELECT TOKEN FROM TABLE(SCM_MGR.UF_FX_STRING_SPLIT(C.DIVISION_ID, ',')) P)
                ---------
                UNION ALL
                ---------
                SELECT SORT_ORDER_NO, COLUMN_NAME, DATA_SORT_METHOD_CODE
                  FROM (SELECT C.SORT_ORDER_NO, C.COLUMN_NAME, C.DATA_SORT_METHOD_CODE   -- AS-IS TOP 100
                          FROM SCM_MGR.SCM_MST_SHEET_COLUMNS C
                         WHERE 1 = 1
                           AND C.PROGRAM_ID   = v_program_id
                           AND C.SHEET_NAME   = v_sheet_name
                           AND C.VISIBLE_FLAG = 'N'
                           AND RTRIM(C.DEFAULT_FLAG, ' -') IS NULL   --[E20260806-00979] 빈값 판정: 공백(' ')과 '-' 동일 취급 (데이터 무수정 방침 — 클라우드 '-' 변형 흡수)
                           AND C.VALID_YN     = 'Y')
                 WHERE ROWNUM <= 100
                 ORDER BY SORT_ORDER_NO
            ) LOOP
                IF v_ColList IS NOT NULL AND LENGTH(v_ColList) > 0 THEN
                    v_ColList   := v_ColList   || ',' || r.COLUMN_NAME || ' ' || CHR(10);
                    v_OrderList := v_OrderList || ',' || r.COLUMN_NAME || ' ' || r.DATA_SORT_METHOD_CODE || CHR(10);
                ELSE
                    v_ColList   := ' ' || r.COLUMN_NAME || ' ' || CHR(10);
                    v_OrderList := ' ' || r.COLUMN_NAME || ' ' || r.DATA_SORT_METHOD_CODE || CHR(10);
                END IF;
            END LOOP;
        END IF;

        -- AS-IS 의 마지막 콤마 제거(LEFT(@ColList, LEN-1))는 Oracle 조립 방식(선행 콤마)에서는 불필요 (0022 선례)
        --[E20260910-MEASURECOL] MEASURE 컬럼 보장 — PKG_DMF0035/PKG_DMF0022 동일 방식.
        --  최종 집계부가 MEASURE 를 **무조건** 참조한다(LOC/USD/KRW=MAX, 그 외 SUM).
        --  T_DM51_WF 의 SELECT 는 개인화 컬럼목록(v_ColList)을 사전과 조인해 만들므로,
        --  개인화에 MEASURE 가 없으면 컬럼이 생성되지 않아 ORA-00904 로 조회가 통째로 실패한다.
        --  MEASURE 는 개인화 모달에 노출되지 않는 축이라 사용자 선택과 무관하게 항상 보장한다.
        --  이미 목록에 있으면 덧붙이지 않는다(중복 ORA-00918 방지).
        IF INSTR(',' || REPLACE(REPLACE(v_ColList, ' ', ''), CHR(10), '') || ',', ',MEASURE,') = 0 THEN
            v_ColList := v_ColList || ',MEASURE';
            --[E20260917-MEASUREORDER] 정렬축도 함께 보강 — PKG_DMF0035 동일 정정(사용자 신고 2026-09-17).
            --  종전에는 v_ColList 에만 넣어, 아래 REPLACE(v_OrderList,'MEASURE',...) 가 치환 대상을
            --  못 찾고 무동작 → ORDER BY 에 SORT_ORDER_NO 가 빠져 MEASURE POPUP 순서가 무시됐다.
            --  실측: SALES 'Sales Plan Waterfall' MEASURE = DEFAULT_FLAG '-' 라 개인화 없는 사용자에서
            --        컬럼목록에 아예 들어오지 않았다(BIZ 는 DEFAULT 'Y' 라 현행 정상 — 예방 목적).
            v_OrderList := CASE WHEN v_OrderList IS NULL OR LENGTH(TRIM(v_OrderList)) = 0
                                THEN 'MEASURE ASC' ELSE v_OrderList || ',MEASURE ASC' END;
        END IF;
        v_ColList   := REPLACE(v_ColList,   'VERSION_NO', 'VERSION_SORT,VERSION_NO');
        v_OrderList := REPLACE(v_OrderList, 'VERSION_NO', 'VERSION_SORT DESC,VERSION_NO');
        v_OrderList := REPLACE(v_OrderList, 'MEASURE',    'SORT_ORDER_NO,MEASURE');
        --  컬럼생성 끝 -----------------------------------------------------------------------------------------------------------------

