        INSERT INTO SCM_MGR.GT_DM22_T_COLUMN_SETUP VALUES ( 'AC', 'CURRENCY', 'CASE WHEN NVL(TRIM(A.CURRENCY),  ''/'') <> ''/'' THEN A.CURRENCY ELSE C.CURRENCY END AS CURRENCY ', 1);
