    --*[2026-09-06] SSPM 적용 기준
      SELECT DISTINCT
             C.DEPT_ID      AS CODE,   /* 부서코드 : 아이템 원장 */                    -- 2026.09.06 AJS
             B.DEPT_NAME_KO AS NAME
             
        FROM SCM_MGR.SCM_MST_SITE_ITEM     C,   /* 아이템 원장 추가 */                 -- 2026.09.06 AJS
