        AND    LENGTH(ATTRIBUTE14) > 0
        AND    NOT EXISTS (  SELECT 1
                               FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                              WHERE LUP.LOOKUP_TYPE = 'METAL_KEY_VALUE'
