 --  , MA.DAY_CODE
 --  , ''         AS FIXED_FLAG
 --  , 120         AS COLUMN_WIDTH
 --  , MA.CELL_CONTROL_OBJECT_TYPE_CODE   --'FPNumber' AS CELL_CONTROL_OBJECT_TYPE_CODE
 --  , ''         AS CELL_COMBO_DATA_TYPE
 --  --, '2'         AS DATA_SCALE_NUMBER
