 -- ORDER BY SORT_ORDER_NO, COLUMN_LABEL_NAME, COLUMN_NAME
 --END

END P_DMF0082_POPUP_GET_SPREAD_TITLE_SAVE_PRICE;


PROCEDURE P_DMF0082_SAVE_MAIN_DATA
(   p_active_flag         IN CLOB
  , p_division_id         IN CLOB
  , p_project_code        IN CLOB
  , p_end_customer        IN CLOB
  , p_scm_site_id         IN CLOB
  , p_item_id             IN CLOB
  , p_dom_exp             IN CLOB
  , p_fcst_type           IN CLOB
  , p_incoterms           IN CLOB
  , p_measure             IN CLOB
  , p_plant_site_id       IN CLOB
  , p_cell_prod_site_id   IN CLOB
  , p_yyyymmdd            IN CLOB
  , p_currency            IN CLOB
