    v_p_active_flag     CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_division_id     CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_project_code    CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_end_customer    CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_scm_site_id     CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_item_id         CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_dom_exp         CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_fcst_type       CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_incoterms       CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_measure         CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_plant_site_id   CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_cell_prod_site_id CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_yyyymmdd        CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_currency        CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_qty             CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_created_by_raw  CLOB;  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    v_p_as_from_site_raw CLOB;  --[E20260805-AFS]  --[E20260901-SAVECLOB] hook #106 §2 패턴B: '^' 페이로드 홀더 → CLOB (다건 4000자 초과 ORA-06502 차단)
    --[E20260813-UPLOADSAVE] '^' 파싱부 skip 여부 (Excel Upload 적재 경로가 GT_PRDM1_T_MAIN 을 직접 적재)
    v_skip_parse        VARCHAR2(1 CHAR);

    -- 루프용 행별 변수
    v_active_flag       VARCHAR2(4000 CHAR);
    v_p_division_id_val VARCHAR2(4000 CHAR);
    v_project_code      VARCHAR2(4000 CHAR);
    v_end_customer      VARCHAR2(4000 CHAR);
    v_scm_site_id       VARCHAR2(4000 CHAR);
    v_item_id           VARCHAR2(4000 CHAR);
    v_dom_exp           VARCHAR2(4000 CHAR);
    v_fcst_type         VARCHAR2(4000 CHAR);
    v_incoterms         VARCHAR2(4000 CHAR);
    v_measure           VARCHAR2(4000 CHAR);
    v_plant_site_id     VARCHAR2(4000 CHAR);
    v_cell_prod_site_id VARCHAR2(4000 CHAR);
    v_yyyymmdd          VARCHAR2(4000 CHAR);
