    --==========================================================================================================================
    -- PR_DM_PLN_CFM_TO_MKT_FCST 프로시져 실행 START (START)
    --==========================================================================================================================
    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := '■ 9. PR_DM_PLN_CFM_TO_MKT_FCST START';
    N_LOG_COUNT   := n_update_cnt;
