    --==========================================================================================================================

    --==========================================================================================================================
    -- MKT FCST 데이터 생성 프로시저 호출 시작 (START)
    --==========================================================================================================================
    --[DIV81] 81 은 DM_PLN_MKT_FCST 에 직접 기록하므로 CFM→MKT_FCST 전파 프로시저 skip (게이트 — 2026-07-14 소스 실측 근거)
    --  1) PR 내부 V_DIVISION_ID='40' 하드코딩 — 동기화 자체는 40 한정.
    --  2) 단, GT_PRDM_SEND_TARGET_DATA 적재에 division 필터가 없어 81 행 유입 시 40 BALANCE 재생성이 불필요 실행됨.
    --  3) [E20260922-TMAINFIX] 해소: PR 이 GT_PRDM_T_MAIN(무 '1', 적재자 0건)을 읽어 40 전파가 no-op 이던 결함 정정 —
    --     PR 을 본 SP 적재 GTT(GT_PRDM1_T_MAIN)로 전환 + VMI 메저 표기 'VMI_In_Req' 정정. 상세: work_report 2026-09-22.
    IF v_is_81 = 'N' THEN
        --[E20260929-DMF0082SAVETXN] 1단계(저장 본체: RTF_SYS_RP·판가·수요·_H) 원자 확정. 아래 전파 PR 과 그 안의 공용
        --  PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE(배치 JOB 공유, DBMS_STATS 다수)가 내부에서 커밋하므로 원래도
        --  여기서 확정되고 있었다(전파 PR 첫 TRUNCATE). 경계를 명시해 본체가 쪼개져 확정되지 않게 한다.
        COMMIT;
        P_PR_DM_PLN_CFM_TO_MKT_FCST(v_created_by, v_inner_result_cursor);
    ELSE
        --[E20260930-DMF0082-81SP] 81 저장 후속처리 — 구 게이트는 81 을 통째로 skip 해 아래 3종이 누락돼 있었다(사용자 확인 2026-09-30).
        --  기준: AS-IS DMF0003_SAVE_MKT_FCST(81 정본) 저장 후속 + TO-BE 가 81 에 연 SCM_FCST 는 AS-IS 40 의 Sales Plan 동기화.
        --  40 전파 PR(P_PR_DM_PLN_CFM_TO_MKT_FCST)은 내부 division '40' 고정이라 재사용 불가 → 81 전용 순서로 직접 호출.
        --  1단계(저장 본체) 원자 확정 경계 = 40 과 동일 (BALANCE_CREATE 가 내부 커밋).
        COMMIT;
        DECLARE
            v_81_bal_rc     SYS_REFCURSOR;
            v_81_start      VARCHAR2(8 CHAR) := TO_CHAR(SCM_MGR.FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');  -- 당주 월요일
            n_81_cnt        NUMBER;
        BEGIN
            -- ① RMA → RTF_SYS_RP = MKT_FCST (AS-IS DMF0003 L2499~2591 / TO-BE PKG_DMF0003 L12055~12114 1:1 — 결과표 = GT_PRDM1_T_MAIN)
            DELETE FROM SCM_MGR.DM_PLN_MKT_FCST
            WHERE  MEASURE  = 'RTF_SYS_RP'
              AND  YYYYMMDD >= v_81_start
              AND  EXISTS (
                       SELECT 1
                       FROM   SCM_MGR.GT_PRDM1_T_MAIN RSLT
                       JOIN   SCM_MGR.DM_MST_ITEM_SINGLE_V ITEM
                         ON   RSLT.DIVISION_ID = ITEM.DIVISION_ID
                        AND   RSLT.ITEM_ID     = ITEM.ITEM_ID
                       WHERE  DM_PLN_MKT_FCST.DIVISION_ID   = RSLT.DIVISION_ID
                         AND  DM_PLN_MKT_FCST.PROJECT_CODE  = RSLT.PROJECT_CODE
                         AND  DM_PLN_MKT_FCST.SCM_SITE_ID   = RSLT.SCM_SITE_ID
                         AND  DM_PLN_MKT_FCST.ITEM_ID       = RSLT.ITEM_ID
                         AND  DM_PLN_MKT_FCST.DOM_EXP       = RSLT.DOM_EXP
                         AND  DM_PLN_MKT_FCST.FCST_TYPE     = RSLT.FCST_TYPE
                         AND  DM_PLN_MKT_FCST.INCOTERMS     = RSLT.INCOTERMS
                         AND  DM_PLN_MKT_FCST.PLANT_SITE_ID = RSLT.PLANT_SITE_ID
                         AND  DM_PLN_MKT_FCST.YYYYMMDD     >= v_81_start
                         AND  ITEM.ACTIVE_FLAG  = 'Y'
                         AND  RSLT.FCST_TYPE    = 'RMA'
                   );

            INSERT INTO SCM_MGR.DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
            , INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE
            , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
            , ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT NVL(NULLIF(RTRIM(A.DIVISION_ID),''), '/'), NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/'), NVL(NULLIF(RTRIM(A.SCM_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.ITEM_ID),''), '/'), NVL(NULLIF(RTRIM(A.DOM_EXP),''), '/'), NVL(NULLIF(RTRIM(A.FCST_TYPE),''), '/')
                 , NVL(NULLIF(RTRIM(A.INCOTERMS),''), '/')
                 , 'RTF_SYS_RP'
                 , NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/'), NVL(NULLIF(RTRIM(A.YYYYMMDD),''), '/'), A.QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
                 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4
                 , A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
            FROM   SCM_MGR.DM_PLN_MKT_FCST A
            WHERE  A.MEASURE   = 'MKT_FCST'
              AND  A.YYYYMMDD >= v_81_start
              AND  EXISTS (
                       SELECT 1
                       FROM   SCM_MGR.GT_PRDM1_T_MAIN RSLT
                       JOIN   SCM_MGR.DM_MST_ITEM_SINGLE_V ITEM
                         ON   RSLT.DIVISION_ID = ITEM.DIVISION_ID
                        AND   RSLT.ITEM_ID     = ITEM.ITEM_ID
                       WHERE  A.DIVISION_ID   = RSLT.DIVISION_ID
                         AND  A.PROJECT_CODE  = RSLT.PROJECT_CODE
                         AND  A.SCM_SITE_ID   = RSLT.SCM_SITE_ID
                         AND  A.ITEM_ID       = RSLT.ITEM_ID
                         AND  A.DOM_EXP       = RSLT.DOM_EXP
                         AND  A.FCST_TYPE     = RSLT.FCST_TYPE
                         AND  A.INCOTERMS     = RSLT.INCOTERMS
                         AND  A.PLANT_SITE_ID = RSLT.PLANT_SITE_ID
                         AND  ITEM.ACTIVE_FLAG = 'Y'
                         AND  RSLT.FCST_TYPE   = 'RMA'
                   );
            COMMIT;

            -- ② BALANCE_CREATE 'CALL' (AS-IS DMF0003 L2595~2634: 저장 키 전부 · CELL_PROD '-' · VMI_YN 'N' 초기값)
            --    피호출측 CALL 모드는 GT_PRDM_SEND_TARGET_DATA 를 읽는다 (PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE L1375~1380).
            DELETE FROM SCM_MGR.GT_PRDM_SEND_TARGET_DATA;
            INSERT INTO SCM_MGR.GT_PRDM_SEND_TARGET_DATA
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, VMI_YN )
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, '-', 'N'
            FROM   SCM_MGR.GT_PRDM1_T_MAIN
            GROUP  BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID;
            n_81_cnt := SQL%ROWCOUNT;
            IF n_81_cnt > 0 THEN
                SCM_MGR.PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE(p_division_id => V_DIVISION_ID, p_plan_id => 'CALL', o_result_cursor => v_81_bal_rc);
                IF v_81_bal_rc%ISOPEN THEN CLOSE v_81_bal_rc; END IF;
            END IF;

            -- ③ Sales Plan 동기화 — 40 전파 PR L15721~15771 동형 (81 키 = PROJECT_CODE, 81 은 END_CUSTOMER '-')
            DELETE FROM SCM_MGR.GT_PRDM_RESULTS;
            INSERT INTO SCM_MGR.GT_PRDM_RESULTS
            ( V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_MEASURE, V_PLANT_SITE_ID, V_YYYYMMDD, V_CREATED_BY )
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, v_created_by
            FROM   SCM_MGR.GT_PRDM1_T_MAIN
            WHERE  MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'LOC', 'KRW', 'USD')
              AND  YYYYMMDD >= v_81_start
            GROUP  BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD;
            n_81_cnt := SQL%ROWCOUNT;
            IF n_81_cnt > 0 THEN
                SCM_MGR.PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE;
            END IF;
            DELETE FROM SCM_MGR.GT_PRDM_RESULTS;
            DELETE FROM SCM_MGR.GT_PRDM_SEND_TARGET_DATA;
        END;
    END IF;
    --==========================================================================================================================
    -- MKT FCST 데이터 생성 프로시저 호출 시작 (END)
    --==========================================================================================================================

    --==========================================================================================================================
    -- PR_DM_PLN_CFM_TO_MKT_FCST 프로시져 실행 END (END)
    --==========================================================================================================================
    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := '■ 10. PR_DM_PLN_CFM_TO_MKT_FCST END';
    N_LOG_COUNT   := n_update_cnt;
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION,
        D_EVENT_DATE, v_created_by, V_PROC_INPUT, NULL, NULL, NULL); END;
    --==========================================================================================================================
    -- PR_DM_PLN_CFM_TO_MKT_FCST 프로시져 실행 END (END)
    --==========================================================================================================================

    BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, 'ING', N_LOG_COUNT,
        '■ : A028--' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'), '', SYSDATE,
        v_created_by,
        V_PROC_INPUT, NULL, NULL, NULL); END;

    --=============================================================================================================================
    -- 종료 LOG (START)
    --=============================================================================================================================
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## SUCCESS END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    -- [E20250915-000105]_로그저장시 사용자ID로 저장되도록 변수 추가 및 원소스 로그처리 주석 후 작성 (START)
    --EXEC PR_SCM_SYS_LOG_BATCH $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE;
    BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION,
        D_EVENT_DATE, v_created_by, V_PROC_INPUT, NULL, NULL, NULL); END;
    -- [E20250915-000105]_로그저장시 사용자ID로 저장되도록 변수 추가 및 원소스 로그처리 주석 후 작성 (END)
    --=============================================================================================================================
    -- 종료 LOG (END)
    --=============================================================================================================================

    --=============================================================================================================================
    -- 결과코드, 결과 카운트 반환
    --=============================================================================================================================
    COMMIT;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS RESULT_CODE, 'SUCCESS' AS RESULT_MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

EXCEPTION
    WHEN e_validation_error THEN
        ROLLBACK;
        BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, 'END', N_LOG_COUNT,
            '########## FAIL-2 END of procedure ##########', V_DESCRIPTION,
            SYSDATE, v_created_by, V_PROC_INPUT, NULL, NULL, NULL); END;

        -- 결과코드, 결과 카운트 반환
        OPEN O_RESULT_CURSOR FOR
            SELECT 'F' AS RESULT_CODE, V_DESCRIPTION AS RESULT_MSG, 'Validation Check' AS ERR_EVENT FROM DUAL;

    WHEN OTHERS THEN
        ROLLBACK;
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := '########## FAIL-1 END of procedure ##########';
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SUBSTR(SQLERRM, 1, 4000);
        V_BACKTRACE   := SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 4000);
        D_EVENT_DATE  := SYSDATE;
        BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH(
            $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION,
            D_EVENT_DATE, v_created_by, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
        ); END;
        RAISE_APPLICATION_ERROR(-20001, V_SQL_ERRMSG || ' ' || V_BACKTRACE);

END P_DMF0082_SAVE_MAIN_DATA;


-- ============================================================================
-- [E20260813-EXCELFORM] DMF0082 Excel Form 조회 SP 신설 — BODY 구현부
--
--  ⭐ 설계 요지 (근거)
--   1) 조회조건 필터는 **MAIN GET 을 그대로 호출**해 재사용한다. MAIN 이 스테이징하는
--      GT_DMF0082_TEMP_FCST_N_PRICE 가 키 10 + 정보성 컬럼 전량을 이미 보유하므로,
--      필터 로직을 복제하지 않고도 "MAIN 조회조건에 맞는 데이터 전체"가 정의상 보장된다.
--      (사내 실측 2026-08-13: div40 3개월 = GET 6.9s / GTT 938,540행 / DISTINCT 키 2,559)
--   2) measure 는 화면 개인화(titleset)와 **무관**하게 LOOKUP 'DM_UI_EDITABLE_MEASURE'
--      (SEGMENT1='DMF0082', ATTRIBUTE1='Y' = INSERT_YN)로 CROSS JOIN 한다 — 사용자 요구
--      "입력 가능 메저 전체 대상". VMI 조건(ATTRIBUTE3)은 검증 SP L4711~4716 과 동일 술어를 쓴다.
--   3) 각 컬럼 값은 **검증 SP 가 기대하는 표기**로 내린다 (검증 SP 원문 실측):
--        Div              = 코드 그대로                              (L4330)
--        End Customer     = END_CUSTOMER lookup SEGMENT3(명칭)        (L4394 EC.NAME = ATTRIBUTE2)
--        Sales Site       = SCM_SITE_ID 코드 그대로                   (L4433)
--        Model            = ITEM_ID 코드 그대로                       (L4513)
--        Incoterms        = INCOTERMS lookup SEGMENT2(=SEGMENT1)      (L4552)
--        FCST Type        = SALES_TYPE_CODE lookup SEGMENT2(명칭)     (L4591)
--        Customs Handbook = DM_CUSTOMS_HANDBOOK_40 SEGMENT2(=SEG1)    (L4629)
--        Cell Prod Site   = SP_CELL_PROD_SITE ATTRIBUTE1(명칭)        (L4667)
--        Currency         = CURRENCY_LIST SEGMENT2(=SEGMENT1)         (L4761, LOC 행만 검증)
--        Measure          = DM_UI_EDITABLE_MEASURE SEGMENT4(표시명)   (L4722)
--      → 본 SP 는 검증 SP 의 역함수. 양식→업로드 왕복이 구조적으로 보장된다.
--   4) 정보성 컬럼은 키별 MAX() 로 축약한다. DISTINCT 에 넣으면 정보성 값 변형 1건이
--      키를 쪼개 행이 불어난다(중복 양식 행 = 업로드 중복키 ERROR 유발).
-- ============================================================================
PROCEDURE P_DMF0082_GET_EXCEL_FORM_DATA (
    p_division_id               IN  VARCHAR2
  , p_dept_id                   IN  VARCHAR2
  , p_end_customer              IN  VARCHAR2
  , p_biz_type                  IN  VARCHAR2
  , p_from_yyyymmdd             IN  VARCHAR2
  , p_to_yyyymmdd               IN  VARCHAR2
  , p_sales_site                IN  VARCHAR2
  , p_item_id                   IN  VARCHAR2
  , p_version_type              IN  VARCHAR2
  , p_qty_yn                    IN  VARCHAR2
  , p_ses_user_id               IN  VARCHAR2
  , p_user_group                IN  VARCHAR2
  , p_plant_site_id             IN  VARCHAR2 DEFAULT 'ALL'
  , p_project_code              IN  VARCHAR2 DEFAULT 'ALL'
  , p_owner                     IN  VARCHAR2 DEFAULT 'ALL'
  , p_sender_code               IN  VARCHAR2 DEFAULT 'ALL'
  , o_rc1                       OUT SYS_REFCURSOR
  , o_result_cursor             OUT SYS_REFCURSOR
)
AS
/* ============================================================================================
 * [E20260921-XLSFORMASIS] Excel Form = **AS-IS DMF0020 파리티 전면 이식** (사용자 지시 2026-09-21)
 *
 *   지시 : "EXCEL FORM, UPLOAD 을 AS-IS DMF0020 의 EXCEL FORM, UPLOAD 와 동일하게 기능 구현"
 *          "EXCEL FORM COLUMN - Div / Team / End Customer / Project Code / Currency / Model / M0 ~ M12"
 *          "to-be 도 m0 - m12 까지는 빈칸"
 *
 *   원천 = AS-IS `DMF0020_SalesPriceTemplatePopup` 이 호출하는
 *          `DM.DMF0020_GET_SALES_PRICE_TEMPLATE` (TO-BE 변환본 = PKG_DMF0020.P_DMF0020_GET_SALES_PRICE_TEMPLATE,
 *          사내 live VALID 실측 2026-09-21). 본문 SQL 을 그 원문 그대로 옮겼다.
 *
 *   ⭐ 구 구현과의 차이 (의도된 교체 — 사용자 확정):
 *     (1) 행 원천 : SCM_MST_FUTURE_PRICE(단가 원장 키) -> **DM_PLN_SALES_PLAN_C ∪ DM_PLN_SALES_PLAN_RESULT_C**
 *                   (MEASURE='RTF_SYS_RP', QTY<>0, DIV 최신 SP_W 버전, 52주 창) = AS-IS 원문
 *     (2) 출력 축 : 23컬럼(Sales Site/Plant Site/Incoterms/FCST Type/Customs Handbook/Measure/
 *                   Project/Project Owner/FORM_WARN 포함) -> **AS-IS 19컬럼 + EDIT_YN**
 *     (3) M0~M12  : 구 구현은 LOC 원장 월별 대표단가를 프리필했다(사용자 지적 "조회 시 값 보임").
 *                   AS-IS 는 `'' AS M0 … '' AS M12` -> **전부 빈 문자열**로 환원. LP 프리필 조인 제거.
 *     (4) 선택 필터: AS-IS 양식은 division 단위 전량이라 조회조건 필터가 없다.
 *                   p_sales_site/p_item_id/p_end_customer/p_plant_site_id/p_project_code 는
 *                   **AS-IS 파리티를 위해 미적용**(시그니처는 PROC_M 배선 보존 목적으로 그대로 둔다).
 *
 *   ⚠ [NLSFIX 2026-09-21] AS-IS 변환 원본(PKG_DMF0020.P_DMF0020_GET_SALES_PRICE_TEMPLATE)은
 *      `FN_NEXT_DAY(T_VER.YYYYMMDD,'MON')` 로 **VARCHAR2 를 DATE 파라미터에 암묵 전달**한다.
 *      FN_NEXT_DAY 는 (P_DATEVAL DATE, P_WEEK VARCHAR2) 이므로 세션 NLS_DATE_FORMAT 에 의존하며,
 *      기본값 'DD-MON-RR' 세션(=BE 기본)에서 **ORA-01861** 로 실패한다(2026-09-21 실측 — 원본도 동일 재현).
 *      이식본은 `TO_DATE(T_VER.YYYYMMDD,'YYYYMMDD')` 로 명시 변환한다 (hook #109 NLS 암묵 형변환).
 *      ⇒ 원본 PKG_DMF0020 쪽은 본 회차 범위 밖이라 미수정 — 별건으로 보고.
 *   시그니처 : 17 IN + 2 OUT **무변경** — SCM_ADM_PROC_M(DMF0082/FcstNPrice/FORM_DATA) 재배선 불필요.
 *   AS-IS MNU 파라미터 대응 : P_USER_ID <- p_ses_user_id / P_MNU_ID <- 'DMF0082' (EDIT_YN 권한 뷰 조회용).
 *   division 가드 : AS-IS 도 81 사업부 전용(DMF0020_SalesFuturePrice.cs L203/L2579
 *                   `clbDivisions.ControlValues.Substring(0,2)=="81"` 일 때만 버튼 노출) — 기존 가드 유지.
 *   결과커서 MONTH_LIST : FE 계약 보존용으로 유지(양식 라벨은 FE 가 M{n} -> YYYYMM 로 환산).
 * ============================================================================================ */
    V_MONTH_LIST                VARCHAR2(400 CHAR);
    n_key_cnt                   PLS_INTEGER := 0;

    V_PROC_INPUT                VARCHAR2(4000 CHAR);
    V_BACKTRACE                 VARCHAR2(4000 CHAR);
    V_SQL_CODE                  VARCHAR2(100  CHAR);
    V_SQL_ERRMSG                VARCHAR2(1000 CHAR);
    n_log_count                 PLS_INTEGER := 0;
    V_PROGRAM_NAME              VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
BEGIN
    --[E20260806-DS2] GT/GTT 사용 SP 표준 — 클라우드 optimizer_dynamic_sampling=0 방어
    EXECUTE IMMEDIATE 'ALTER SESSION SET optimizer_dynamic_sampling = 2';

    /* [E20260819-XLS81LOC] Excel Form = Division 81 계열 전용 (AS-IS 동일 — .cs L203 실측).
       비대상 division 은 처리 없이 결과커서 CODE '1' + MSG01014. FE 는 81 외 버튼 비노출(서버 권위 방어). */
    IF p_division_id IS NULL OR p_division_id NOT LIKE '81%' THEN
        OPEN o_rc1 FOR SELECT CAST(NULL AS VARCHAR2(10)) AS DIVISION_ID FROM DUAL WHERE 1 = 0;
        OPEN o_result_cursor FOR
            SELECT '1' AS RESULT_CODE, 'MSG01014' AS RESULT_MSG, '0' AS EVENT
                 , CAST(NULL AS VARCHAR2(400)) AS MONTH_LIST FROM DUAL;
        RETURN;
    END IF;

    /* [E20260921-XLSFORMASIS] 월 목록 CSV(YYYYMM 13개) — 값이 아니라 **라벨 축** 전달용.
       M0=당월 … M12=당월+12 (업로드 저장이 M{n} -> ADD_MONTHS(SYSDATE,n) 로 해석하는 축과 동일). */
    SELECT LISTAGG(TO_CHAR(ADD_MONTHS(SYSDATE, LV - 1), 'YYYYMM'), ',') WITHIN GROUP (ORDER BY LV)
      INTO V_MONTH_LIST
      FROM (SELECT LEVEL AS LV FROM DUAL CONNECT BY LEVEL <= 13);

    -- ================================================================
    -- 메인 조회 — AS-IS DMF0020_GET_SALES_PRICE_TEMPLATE 원문 1:1
    -- ================================================================
    OPEN o_rc1 FOR
    WITH TEMP_VERSION_NO AS (
        --DIV별 최신 버전(2024.10.04)---------------------
        SELECT /*+ MATERIALIZE */
               A.DIVISION_ID, A.VERSION_NO, A.YYYYMMDD, B.BASIS_YYYYMM AS YYYYMM
        FROM
        (
            SELECT DIVISION_ID, MAX(VERSION_NO) AS VERSION_NO, MAX(YYYYMMDD) AS YYYYMMDD
            FROM DM_MST_VERSION
            WHERE DIVISION_ID = p_division_id
            AND VERSION_TYPE = 'SP_W'
            GROUP BY DIVISION_ID
        ) A
        INNER JOIN SCM_SYS_CALENDAR_M B
                ON B.BASIS_YYYYMMDD = A.YYYYMMDD
    )
    SELECT DISTINCT
        A.DIVISION_ID
        , A.DEPT_NAME_KO AS DEPT_NAME
        , A.END_CUSTOMER
        , A.PROJECT_CODE
        , MAX(A.CURRENCY) AS CURRENCY -- Model별로 하나의 CURRENCY만 있어야 하므로 MAX값 취함
        , A.ITEM_ID
        /* [E20260921-XLSFORMASIS] 양식 = 사용자 입력칸. AS-IS 원문과 동일하게 전부 빈칸. */
        , '' AS M0
        , '' AS M1
        , '' AS M2
        , '' AS M3
        , '' AS M4
        , '' AS M5
        , '' AS M6
        , '' AS M7
        , '' AS M8
        , '' AS M9
        , '' AS M10
        , '' AS M11
        , '' AS M12
        , EDIT_YN
    FROM
    (
        SELECT
        SP.DIVISION_ID
        , TEAM.DEPT_ID
        , TEAM.DEPT_NAME_KO
        , MS.END_CUSTOMER
        , SP.PROJECT_CODE
        , MP.PROJECT_NAME
        , SP.ITEM_ID
        , SP.SCM_SITE_ID
        /* [E20260923-XLSFORMCURCHAIN] CURRENCY 폴백 체인 (사용자 지시 2026-09-23 — "CURRENCY 가 존재하지 않는 ROW 가 없도록").
           AS-IS(DMF0020 L74/L119)는 L1→L2 2단뿐이고 MSSQL 에서는 그것으로 빈칸이 안 난다.
           TO-BE 는 [E20260923-XLSFORMCURRENCY] 로 2단을 복원한 위에, 데이터 변동에도 빈칸 0 을 보장하도록 L3~L5 를 덧댄다.
           COALESCE 는 좌→우 단락평가라 앞 단계가 채우면 뒤 서브쿼리는 실행되지 않는다(현 데이터는 L2 에서 100% 종료). */
        , COALESCE( NULLIF(TRIM(SP.CURRENCY), '')                                    /* L1 판매계획 실적 통화 */
                  , NULLIF(TRIM(SI.CURRENCY), '')                                    /* L2 SSPM SITE_ITEM 4키 — AS-IS 동일 단계 */
                  , (SELECT MAX(FP.CURRENCY) FROM SCM_MST_FUTURE_PRICE FP            /* L3 같은 키의 기존 단가 통화(저장 원장) */
                      WHERE FP.DIVISION_ID  = SP.DIVISION_ID
                        AND FP.PROJECT_CODE = SP.PROJECT_CODE
                        AND FP.SCM_SITE_ID  = SP.SCM_SITE_ID
                        AND FP.ITEM_ID      = SP.ITEM_ID)
                  , (SELECT MAX(S2.CURRENCY) FROM SCM_MST_SITE_ITEM S2                /* L4 SITE_ITEM 3키(프로젝트 무시) */
                      WHERE S2.DIVISION_ID = SP.DIVISION_ID
                        AND S2.SCM_SITE_ID = SP.SCM_SITE_ID
                        AND S2.ITEM_ID     = SP.ITEM_ID
                        AND S2.VALID_YN    = 'Y')
                  , NULLIF(TRIM(MP.CURRENCY), '')                                     /* L5 프로젝트 기본통화 — 키 194/194 전수 커버 */
                  ) AS CURRENCY
        , NVL(T2.EDIT_YN,'N') AS EDIT_YN

        FROM DM_PLN_SALES_PLAN_C SP

            INNER JOIN (SELECT * -- EDIT_YN
                FROM SCM_ADM_USER_MNU_EDIT_AUTH_V
                WHERE USER_ID = p_ses_user_id
                AND MNU_ID = 'DMF0082'
                AND UNIT_TP_CD = 'D') T2
            ON SP.DIVISION_ID = T2.UNIT_ID

        INNER JOIN SCM_MST_SITE MS
            ON MS.DIVISION_ID = SP.DIVISION_ID
            AND MS.SCM_SITE_ID = SP.SCM_SITE_ID
            AND MS.VALID_YN = 'Y'
        -- 2026-09-07 hook#150: site 대표부서 = (DIVISION_ID, SCM_SITE_ID) 기준 MAX(DEPT_ID) 1건.
        --   AS-IS 는 IM 을 DIV+SITE 단독 INNER JOIN 하여 SITE_ITEM 행수만큼 증식한다(실측: 키당 최대 3,506행).
        INNER JOIN (SELECT SA.DIVISION_ID, SA.SCM_SITE_ID, MAX(SA.DEPT_ID) AS DEPT_ID
                      FROM SCM_MST_SITE_ITEM SA
                     INNER JOIN SCM_MST_SSO_DEPT_INFO SD
                        ON SD.DEPT_ID  = SA.DEPT_ID
                       AND SD.VALID_YN = 'Y'
                     WHERE SA.DEPT_ID IS NOT NULL
                     GROUP BY SA.DIVISION_ID, SA.SCM_SITE_ID) IM
            ON MS.DIVISION_ID = IM.DIVISION_ID
            AND MS.SCM_SITE_ID = IM.SCM_SITE_ID

        INNER JOIN SCM_MST_SSO_DEPT_INFO DI
            ON DI.DEPT_ID = IM.DEPT_ID
            AND DI.VALID_YN = 'Y'

        INNER JOIN SCM_MST_PROJECT MP
            ON MP.DIVISION_ID = SP.DIVISION_ID
            AND MP.PROJECT_CODE = SP.PROJECT_CODE --2026-07-03 perf: AS-IS 원문 활성 조인 복원

        INNER JOIN SCM_MST_SITE_ITEM SI
            ON SI.DIVISION_ID = SP.DIVISION_ID
            AND SI.PROJECT_CODE = SP.PROJECT_CODE
            AND SI.SCM_SITE_ID = SP.SCM_SITE_ID
            AND SI.ITEM_ID = SP.ITEM_ID
            AND SI.VALID_YN = 'Y'
        INNER JOIN TEMP_VERSION_NO T_VER--DIV별 최신버전(2024.10.04)
            ON SP.DIVISION_ID = T_VER.DIVISION_ID
            AND SP.VERSION_NO = T_VER.VERSION_NO
        -- 2026-09-06 hook#150 AJS: DEPT_ID 원천 = SCM_MST_SITE_ITEM.DEPT_ID (OWNER 경유 폐기)
        LEFT JOIN SCM_MST_SSO_DEPT_INFO TEAM
            ON TEAM.DEPT_ID = SI.DEPT_ID
        WHERE SP.DIVISION_ID = p_division_id
        AND SP.QTY <> 0
        AND SP.MEASURE = 'RTF_SYS_RP'   /*[E20260923-XLSFORMMEASUREOFF] 임시 합집합(MKT_FCST 추가) 해제 — AS-IS 파리티 복귀 (사용자 지시 2026-09-23).
           AS-IS DMF0020_GET_SALES_PRICE_TEMPLATE L105/L150 과 동일한 단일 measure.
           건수 부족의 원인은 measure 가 아니라 컷오프 스냅샷 결함이었다 — 원장 RTF_SYS_RP 6,152행 정상인데
           컷오프 SP_W_20260923_V001(13:12)은 RTF_PR 0 / SalesAmt_* 0 / RTF_SYS_RP 8 로 RTF·금액 계열 5종이 통째 누락
           (원장 6,152행 전부 13:12 갱신 = 컷오프가 금액배치 전/중에 읽음). 근본 해소 = 컷오프 재수행. */
        --버전의 날짜로 처리(2024.10.04)
        AND SP.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(T_VER.YYYYMMDD, 'YYYYMMDD'), 'MON') - 7, 'YYYYMMDD')
        AND SP.YYYYMMDD <= TO_CHAR(TO_DATE(TO_CHAR(FN_NEXT_DAY(TO_DATE(T_VER.YYYYMMDD, 'YYYYMMDD'), 'MON') - 7, 'YYYYMMDD'), 'YYYYMMDD') + (52 * 7) - 1, 'YYYYMMDD')
        UNION ALL

        SELECT
        SP.DIVISION_ID
        , TEAM.DEPT_ID
        , TEAM.DEPT_NAME_KO
        , MS.END_CUSTOMER
        , SP.PROJECT_CODE
        , MP.PROJECT_NAME
        , SP.ITEM_ID
        , SP.SCM_SITE_ID
        /* [E20260923-XLSFORMCURCHAIN] CURRENCY 폴백 체인 (사용자 지시 2026-09-23 — "CURRENCY 가 존재하지 않는 ROW 가 없도록").
           AS-IS(DMF0020 L74/L119)는 L1→L2 2단뿐이고 MSSQL 에서는 그것으로 빈칸이 안 난다.
           TO-BE 는 [E20260923-XLSFORMCURRENCY] 로 2단을 복원한 위에, 데이터 변동에도 빈칸 0 을 보장하도록 L3~L5 를 덧댄다.
           COALESCE 는 좌→우 단락평가라 앞 단계가 채우면 뒤 서브쿼리는 실행되지 않는다(현 데이터는 L2 에서 100% 종료). */
        , COALESCE( NULLIF(TRIM(SP.CURRENCY), '')                                    /* L1 판매계획 실적 통화 */
                  , NULLIF(TRIM(SI.CURRENCY), '')                                    /* L2 SSPM SITE_ITEM 4키 — AS-IS 동일 단계 */
                  , (SELECT MAX(FP.CURRENCY) FROM SCM_MST_FUTURE_PRICE FP            /* L3 같은 키의 기존 단가 통화(저장 원장) */
                      WHERE FP.DIVISION_ID  = SP.DIVISION_ID
                        AND FP.PROJECT_CODE = SP.PROJECT_CODE
                        AND FP.SCM_SITE_ID  = SP.SCM_SITE_ID
                        AND FP.ITEM_ID      = SP.ITEM_ID)
                  , (SELECT MAX(S2.CURRENCY) FROM SCM_MST_SITE_ITEM S2                /* L4 SITE_ITEM 3키(프로젝트 무시) */
                      WHERE S2.DIVISION_ID = SP.DIVISION_ID
                        AND S2.SCM_SITE_ID = SP.SCM_SITE_ID
                        AND S2.ITEM_ID     = SP.ITEM_ID
                        AND S2.VALID_YN    = 'Y')
                  , NULLIF(TRIM(MP.CURRENCY), '')                                     /* L5 프로젝트 기본통화 — 키 194/194 전수 커버 */
                  ) AS CURRENCY
        , NVL(T2.EDIT_YN,'N') AS EDIT_YN
        FROM DM_PLN_SALES_PLAN_RESULT_C SP

        INNER JOIN (SELECT * -- EDIT_YN
                FROM SCM_ADM_USER_MNU_EDIT_AUTH_V
                WHERE USER_ID = p_ses_user_id
                AND MNU_ID = 'DMF0082'
                AND UNIT_TP_CD = 'D') T2
            ON SP.DIVISION_ID = T2.UNIT_ID

        INNER JOIN SCM_MST_SITE MS
            ON MS.DIVISION_ID = SP.DIVISION_ID
            AND MS.SCM_SITE_ID = SP.SCM_SITE_ID
            AND MS.VALID_YN = 'Y'

        INNER JOIN (SELECT SA.DIVISION_ID, SA.SCM_SITE_ID, MAX(SA.DEPT_ID) AS DEPT_ID
                      FROM SCM_MST_SITE_ITEM SA
                     INNER JOIN SCM_MST_SSO_DEPT_INFO SD
                        ON SD.DEPT_ID  = SA.DEPT_ID
                       AND SD.VALID_YN = 'Y'
                     WHERE SA.DEPT_ID IS NOT NULL
                     GROUP BY SA.DIVISION_ID, SA.SCM_SITE_ID) IM
            ON MS.DIVISION_ID = IM.DIVISION_ID
            AND MS.SCM_SITE_ID = IM.SCM_SITE_ID

        INNER JOIN SCM_MST_SSO_DEPT_INFO DI
            ON DI.DEPT_ID = IM.DEPT_ID
            AND DI.VALID_YN = 'Y'

        INNER JOIN SCM_MST_PROJECT MP
            ON MP.DIVISION_ID = SP.DIVISION_ID
            AND MP.PROJECT_CODE = SP.PROJECT_CODE
        INNER JOIN SCM_MST_SITE_ITEM SI
            ON SI.DIVISION_ID = SP.DIVISION_ID
            AND SI.PROJECT_CODE = SP.PROJECT_CODE
            AND SI.SCM_SITE_ID = SP.SCM_SITE_ID
            AND SI.ITEM_ID = SP.ITEM_ID
            AND SI.VALID_YN = 'Y'
        INNER JOIN TEMP_VERSION_NO T_VER--DIV별 최신버전(2024.10.04)
            ON SP.DIVISION_ID = T_VER.DIVISION_ID
            AND SP.VERSION_NO = T_VER.VERSION_NO
        LEFT JOIN SCM_MST_SSO_DEPT_INFO TEAM
            ON TEAM.DEPT_ID = SI.DEPT_ID
        WHERE SP.DIVISION_ID = p_division_id
        AND SP.QTY <> 0
        AND SP.MEASURE = 'RTF_SYS_RP'   /*[E20260923-XLSFORMMEASUREOFF] 임시 합집합(MKT_FCST 추가) 해제 — AS-IS 파리티 복귀 (사용자 지시 2026-09-23).
           AS-IS DMF0020_GET_SALES_PRICE_TEMPLATE L105/L150 과 동일한 단일 measure.
           건수 부족의 원인은 measure 가 아니라 컷오프 스냅샷 결함이었다 — 원장 RTF_SYS_RP 6,152행 정상인데
           컷오프 SP_W_20260923_V001(13:12)은 RTF_PR 0 / SalesAmt_* 0 / RTF_SYS_RP 8 로 RTF·금액 계열 5종이 통째 누락
           (원장 6,152행 전부 13:12 갱신 = 컷오프가 금액배치 전/중에 읽음). 근본 해소 = 컷오프 재수행. */
        AND SP.YYYYMMDD >= T_VER.YYYYMM || '01'
        AND SP.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(TO_DATE(T_VER.YYYYMMDD, 'YYYYMMDD'), 'MON') - 7, 'YYYYMMDD')
    ) A
    GROUP BY
    A.DIVISION_ID
    , A.DEPT_ID
    , A.DEPT_NAME_KO
    , A.END_CUSTOMER
    , A.PROJECT_CODE
    , A.PROJECT_NAME
    , A.ITEM_ID
    , A.SCM_SITE_ID
    , A.EDIT_YN
    /* [E20260923-XLSFORMSORT] 정렬 신설 (사용자 지시 2026-09-23) — 양식 표시 컬럼 순서와 동일.
       AS-IS 원문(DMF0020_GET_SALES_PRICE_TEMPLATE)에는 ORDER BY 가 없어 순서가 비결정적이었다.
       Currency 는 MAX() 집계값이라 정렬 키 제외. Team 미지정(NULL) 행은 뒤로 보낸다. */
    ORDER BY DIVISION_ID, DEPT_NAME NULLS LAST, END_CUSTOMER, PROJECT_CODE, ITEM_ID
    ;

    OPEN o_result_cursor FOR
        SELECT '0' AS RESULT_CODE, 'SUCCESS' AS RESULT_MSG, TO_CHAR(n_key_cnt) AS EVENT
             , V_MONTH_LIST AS MONTH_LIST
        FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := JSON_OBJECT(
            'p_division_id'    VALUE SUBSTR(p_division_id, 1, 50)
          , 'p_ses_user_id'    VALUE SUBSTR(p_ses_user_id, 1, 50)
          , 'p_from_yyyymmdd'  VALUE SUBSTR(p_from_yyyymmdd, 1, 50)
          , 'p_to_yyyymmdd'    VALUE SUBSTR(p_to_yyyymmdd, 1, 50));
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, 'ERROR', n_log_count, 'EXCEPTION',
                '', SYSDATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
          '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END P_DMF0082_GET_EXCEL_FORM_DATA;


-- ====================================================================================================
-- [2026.08.15 AJS 신뢰도검사 발견1] MSSQL DMF0082_POPUP_GET_SPREAD_TITLE_DATE (원본 34~50행) 이관.
--   기존에는 SCM_MGR 에 대응 객체가 없고 SCMC(전환 테스트용 스키마)에만 남아 있었다.
--   본문은 MSSQL 원본과 동일하며, 표준 예외 처리와 결과 커서만 패키지 규약에 맞춘다.
-- ====================================================================================================
PROCEDURE P_DMF0082_POPUP_GET_SPREAD_TITLE_DATE
(
    p_start_yyyymmdd  IN  VARCHAR2
  , p_end_yyyymmdd    IN  VARCHAR2
  , p_created_by      IN  VARCHAR2
  , O_RC1             OUT SYS_REFCURSOR
  , O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : DMF0082_POPUP_GET_SPREAD_TITLE_DATE
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2025-02-25   dsiol     Initial Release [PJ2025-50017]LGES SCM DM 소형사업부 매출계획 동기화 개선
 * 2026.08.15   AJS       신뢰도 검사 — MSSQL 원본 미이관분 이관
 */
    V_PROGRAM_NAME  VARCHAR2(200 CHAR);
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;
BEGIN
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    OPEN O_RC1 FOR
        SELECT MIN(BASIS_START_DATE)         AS BASIS_START_DATE
             , BASIS_YYYYMM
             , WEEK_NAME
             , SUBSTR(BASIS_START_DATE, 5, 4) AS DATE_SHORT1_NAME
          FROM SCM_MGR.SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD >= p_start_yyyymmdd
           AND BASIS_YYYYMMDD <= p_end_yyyymmdd
         GROUP BY BASIS_YYYYMM, WEEK_NAME, SUBSTR(BASIS_START_DATE, 5, 4)
         ORDER BY BASIS_START_DATE;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE,
               'SUCCESS' AS MSG,
               CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
                             'p_start_yyyymmdd' VALUE p_start_yyyymmdd,
                             'p_end_yyyymmdd'   VALUE p_end_yyyymmdd,
                             'p_created_by'     VALUE p_created_by
                         );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); EXCEPTION WHEN OTHERS THEN NULL; END;

        RAISE_APPLICATION_ERROR(
            -20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0082_POPUP_GET_SPREAD_TITLE_DATE;

    -- [2026-09-15 UIPKG] standalone PR_DM_PLN_CFM_TO_MKT_FCST 취합
PROCEDURE P_PR_DM_PLN_CFM_TO_MKT_FCST
(
    p_created_by        IN  VARCHAR2
  , O_RESULT_CURSOR     OUT SYS_REFCURSOR
)
--EXEC PR_DM_PLN_CFM_TO_MKT_FCST '81'
/*=====================================================================================================================================================
 * Program ID   : PR_DM_PLN_CFM_TO_MKT_FCST
 * Description  :
 * Program History
 *=====================================================================================================================================================
 *   Date       In Charge      Description
 *=====================================================================================================================================================
 * 2025-01-23	KANG.H.J		[PJ2025-50017] [소형매출동기화] Cell_Prod_Site 기반으로 데이터 생성 - 최초 개발
 * 2025-01-23	KANG.H.J		[PJ2025-50188] [소형매출동기화] 기준수요 반영
 * 2025-05-20	KANG.H.J		[PJ2025-50017] #SEND_TARGET_DATA에 CELL_PROD_SITE_ID 추가
 * 2025-11-04	JSSBAE			[E20251021-000634]_FCST&PRICE MGMT SALES PLAN 데이터 동기화 속도개선
 * 2025-12-29	JSSBAE			[E20251223-000672]_Sales Price 동기화 배치 생성 요청
 * 2026-03-09	JSSBAE			[E20260309-000271]_DMF0082 UI Sales Price 저장 로직 개선
*===================================================================================================================================================*/
IS
    --=====================================================================================================================================================
    -- LOG 용 변수 설정 (START)
    v_log_type      VARCHAR2(30 CHAR);  -- START/END/ERROR/...
    n_log_count     PLS_INTEGER := 0;
    v_log_message   VARCHAR2(1000 CHAR);
    v_description   VARCHAR2(500 CHAR);
    d_event_date    DATE;
    v_proc_input    VARCHAR2(4000 CHAR);
    v_sql_code      VARCHAR2(20 CHAR);
    v_sql_errmsg    VARCHAR2(2000 CHAR);
    v_backtrace     VARCHAR2(4000 CHAR);
    -- LOG 용 변수 설정 (END)
    --=====================================================================================================================================================

    --=====================================================================================================================================================
    -- 프로시져 사용 변수 설정  (START)
    v_division_id           VARCHAR2(30 CHAR);
    v_created_by            VARCHAR2(100 CHAR);
    --[E20251223-000672]_변수 사용시 규칙에 맞게 변경 원소스 주석처리 후 변수명 변경 (START)
    --DECLARE @plan_start_yyyymmdd			NVARCHAR(8);
    v_plan_start_yyyymmdd   VARCHAR2(8 CHAR);
    --[E20251223-000672]_변수 사용시 규칙에 맞게 변경 원소스 주석처리 후 변수명 변경 (END)

    n_send_count    PLS_INTEGER := 0;
    n_result_count  PLS_INTEGER := 0;
    v_qty_balance_rc SYS_REFCURSOR;
    -- 프로시져 사용 변수 설정  (END)
    --=====================================================================================================================================================

BEGIN
    --=====================================================================================================================================================
    -- 프로시져 사용 변수 초기화
    v_proc_input := JSON_OBJECT('p_created_by' VALUE p_created_by);

    --SET @plan_start_yyyymmdd	= CONVERT(CHAR(8), DATEADD(DD, -7, dbo.FN_NEXT_DAY(GETDATE(), 'MON')), 112)   -- 월요일
    v_plan_start_yyyymmdd := TO_CHAR(SCM_MGR.FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');  -- 월요일

    --SET @p_created_by			= RTRIM(@p_created_by    ) + '^';
    --SET @v_created_by			= LEFT(@P_created_by, CASE WHEN PATINDEX('%^%', @P_created_by) > 1 THEN PATINDEX('%^%', @P_created_by) ELSE 100 END -1)
    v_created_by := SUBSTR(p_created_by, 1, CASE WHEN INSTR(p_created_by || '^', '^') > 1 THEN INSTR(p_created_by || '^', '^') - 1 ELSE 99 END);
    v_division_id := '40';
    --=====================================================================================================================================================

    --=====================================================================================================================================================
    -- 시작 LOG  (START)
    v_log_type    := 'START';
    v_log_message := '########## Start of procedure ##########';
    v_description := '@p_created_by : ' || p_created_by;
    d_event_date  := SYSDATE;
    BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, v_log_type, n_log_count, v_log_message, v_description, d_event_date, v_created_by, v_proc_input, NULL, NULL, NULL); END;
    v_log_message := NULL;
    -- 시작 LOG  (END)
    --=====================================================================================================================================================

    --=====================================================================================================================================================
    -- TEMP 테이블 초기화 (GTT TRUNCATE)
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -- DM_PLN_CFM_MKT_DEMAND_PLAN 테이블 데이터 DM_PLN_MKT_FCST 기준 테이블 데이터로 임시 테이블 존재 여부 확인 후 DROP
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_TEMP_MKT_DEMAND_PLAN';
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -- DM_PLN_CFM_SELLING_PRICE 테이블 데이터 SCM_MST_FUTURE_PRICE 기준 테이블 데이터로 임시 테이블 존재 여부 확인 후 DROP
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_TEMP_SELLING_PRICE';
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -- #SEND_TARGET_DATA 기준 테이블 데이터로 임시 테이블 존재 여부 확인 후 DROP & CREATE
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_SEND_TARGET_DATA';
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -------------------------------------------------------------------------------------------------------------------------------------------------------
    -- #results 기준 테이블 데이터로 임시 테이블 존재 여부 확인 후 DROP & CREATE
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_RESULTS';
    -- TEMP 테이블 초기화 (END)
    --=====================================================================================================================================================

    --=====================================================================================================================================================
    -- [E20251223-000672]_굳이 TEMP로 계속 담아 작업을 하지 않아도됨. 간략하게 진행하기 위해 원소스 주석 후 생성한다 (START)
    -- [E20251223-000672]_굳이 TEMP로 계속 담아 작업을 하지 않아도됨. 간략하게 진행하기 위해 원소스 주석 후 생성한다 (END)

    --=============================================================================================================================================
    -- 1. 받아온 데이터 기준으로 DM_PLN_MKT_FCST 데이터 동기화 (START)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 1). #T_MAIN 테이블 데이터를 DM_PLN_MKT_FCST 적재기준으로 -> TEMP TABLE[#TEMP_DM_PLN_CFM_MKT_DEMAND_PLAN]에 INSERT (START)

    INSERT INTO SCM_MGR.GT_PRDM_TEMP_MKT_DEMAND_PLAN
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID
    , QTY )
    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID
           --[E20260309-000271]_ISNULL처리 추가 (START)
           --, SUM(QTY_PRICE) AS QTY --[E20260309-000271]_원소스 주석처리
           , SUM(NVL(QTY_PRICE, 0)) AS QTY --[E20260309-000271]_ISNULL처리 추가
           --[E20260309-000271]_ISNULL처리 추가 (END)
    FROM SCM_MGR.GT_PRDM1_T_MAIN  --[E20260922-TMAINFIX] GT_PRDM_T_MAIN->GT_PRDM1_T_MAIN (SAVE 적재 GTT 일치)
    WHERE DIVISION_ID   = v_division_id
    AND   MEASURE       IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req')          -- [PJ2025-50188] 기준수요 포함  --[E20260922-TMAINFIX] 'VMI_IN_REQ'->'VMI_In_Req' (Oracle 대소문자 구분, 저장값 실측)
    AND   YYYYMMDD      >= v_plan_start_yyyymmdd
    GROUP BY  DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM_TEMP_MKT_DEMAND_PLAN', NO_INVALIDATE => FALSE);

    -- 1). #T_MAIN 테이블 데이터를 DM_PLN_MKT_FCST 적재기준으로 -> TEMP TABLE[#TEMP_DM_PLN_CFM_MKT_DEMAND_PLAN]에 INSERT(END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 2). 당주 월요일 이후 TEMP 테이블에 적재된 데이터와 동일한 DM_PLN_MKT_FCST 데이터를 삭제한다 (START)

    DELETE SCM_MGR.DM_PLN_MKT_FCST A
    WHERE EXISTS (
        SELECT 1
        FROM SCM_MGR.GT_PRDM_TEMP_MKT_DEMAND_PLAN B
        WHERE A.DIVISION_ID   = B.DIVISION_ID
          AND A.PROJECT_CODE  = B.PROJECT_CODE
          AND A.SCM_SITE_ID   = B.SCM_SITE_ID
          AND A.ITEM_ID       = B.ITEM_ID
          AND A.DOM_EXP       = B.DOM_EXP
          AND A.FCST_TYPE     = B.FCST_TYPE
          AND A.INCOTERMS     = B.INCOTERMS
          AND A.MEASURE       = B.MEASURE
          AND A.YYYYMMDD      = B.YYYYMMDD
          AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
    )
    AND A.DIVISION_ID = v_division_id
    AND A.YYYYMMDD   >= v_plan_start_yyyymmdd
    AND A.MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req');  --[E20260922-TMAINFIX] 'VMI_IN_REQ'->'VMI_In_Req' (Oracle 대소문자 구분, 저장값 실측)

    -- 2). 당주 월요일 이후 TEMP 테이블에 적재된 데이터와 동일한 DM_PLN_MKT_FCST 데이터를 삭제한다 (END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 3). TEMP TABLE[#TEMP_DM_PLN_CFM_MKT_DEMAND_PLAN]데이터로 -> MKT FCST 데이터를 적재한다 (START)

    INSERT INTO SCM_MGR.DM_PLN_MKT_FCST
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
    , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
         , A.QTY, p_created_by, SYSDATE, p_created_by, SYSDATE
    FROM SCM_MGR.GT_PRDM_TEMP_MKT_DEMAND_PLAN A;

    -- 3). TEMP TABLE[#TEMP_DM_PLN_CFM_MKT_DEMAND_PLAN]데이터로 -> MKT FCST 데이터를 적재한다 (END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 1. 받아온 데이터 기준으로 DM_PLN_MKT_FCST 데이터 동기화 (END)
    --=============================================================================================================================================
    --=============================================================================================================================================
    -- 2. 받아온 데이터 기준으로 SCM_MST_FUTURE_PRICE 데이터 동기화 (START)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 1). #T_MAIN 테이블 데이터를 DM_PLN_CFM_SELLING_PRICE 적재기준으로 -> TEMP TABLE[#TEMP_DM_PLN_CFM_SELLING_PRICE]에 INSERT (START)
    -- 데이터가 하나 이상인 경우가 존재할 수 있으므로, 평균값으로 저장한다.

    INSERT INTO SCM_MGR.GT_PRDM_TEMP_SELLING_PRICE
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, YYYYMMDD, CURRENCY, MEASURE, DOM_EXP, FCST_TYPE
    , INCOTERMS, PRICE )
    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.YYYYMMDD, A.CURRENCY, A.MEASURE, A.DOM_EXP, A.FCST_TYPE
         , A.INCOTERMS
         --[E20260309-000271]_ISNULL처리 추가 (START)
         --, AVG(A.QTY_PRICE) AS PRICE--[E20260309-000271]_원소스 주석처리
         , AVG(NVL(A.QTY_PRICE, 0)) AS PRICE
         --[E20260309-000271]_ISNULL처리 추가 (END)
    FROM SCM_MGR.GT_PRDM1_T_MAIN A  --[E20260922-TMAINFIX] GT_PRDM_T_MAIN->GT_PRDM1_T_MAIN (SAVE 적재 GTT 일치)
    WHERE A.DIVISION_ID = v_division_id
      AND A.MEASURE IN ('LOC', 'KRW', 'USD')
      AND A.YYYYMMDD >= v_plan_start_yyyymmdd
    GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.YYYYMMDD, A.CURRENCY, A.MEASURE, A.DOM_EXP, A.FCST_TYPE
           , A.INCOTERMS;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM_TEMP_SELLING_PRICE', NO_INVALIDATE => FALSE);

    -- 1). DM_PLN_CFM_SELLING_PRICE테이블 데이터를 SCM_MST_FUTURE_PRICE 적재기준으로 -> TEMP TABLE[#TEMP_DM_PLN_CFM_SELLING_PRICE]에 INSERT (END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 2). 당주 월요일 이후 TEMP 테이블에 적재된 데이터와 동일한 SCM_MST_FUTURE_PRICE 데이터를 삭제한다 (START)

    DELETE SCM_MGR.SCM_MST_FUTURE_PRICE A
    WHERE EXISTS (
        SELECT 1
        FROM SCM_MGR.GT_PRDM_TEMP_SELLING_PRICE B
        WHERE A.DIVISION_ID   = B.DIVISION_ID
          AND A.PROJECT_CODE  = B.PROJECT_CODE
          AND A.SCM_SITE_ID   = B.SCM_SITE_ID
          AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
          AND A.ITEM_ID       = B.ITEM_ID
          AND A.YYYYMMDD      = B.YYYYMMDD
          AND A.MEASURE       = B.MEASURE
          AND A.DOM_EXP       = B.DOM_EXP
          AND A.FCST_TYPE     = B.FCST_TYPE
          AND A.INCOTERMS     = B.INCOTERMS
    )
    AND A.DIVISION_ID = v_division_id
    AND A.YYYYMMDD   >= v_plan_start_yyyymmdd
    AND A.MEASURE IN ('LOC', 'KRW', 'USD');

    -- 2). 당주 월요일 이후 TEMP 테이블에 적재된 데이터와 동일한 SCM_MST_FUTURE_PRICE 데이터를 삭제한다 (END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 3). TEMP TABLE[#TEMP_DM_PLN_CFM_SELLING_PRICE]데이터로 -> SCM_MST_FUTURE_PRICE 데이터를 적재한다 (START)

    INSERT INTO SCM_MGR.SCM_MST_FUTURE_PRICE
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, YYYYMMDD, CURRENCY, MEASURE, DOM_EXP, FCST_TYPE
    , INCOTERMS, PRICE, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.YYYYMMDD, A.CURRENCY, A.MEASURE, A.DOM_EXP, A.FCST_TYPE
         , A.INCOTERMS, A.PRICE, p_created_by, SYSDATE, p_created_by, SYSDATE
    FROM SCM_MGR.GT_PRDM_TEMP_SELLING_PRICE A;

    -- 3). TEMP TABLE[#TEMP_DM_PLN_CFM_SELLING_PRICE]데이터로 -> SCM_MST_FUTURE_PRICE 데이터를 적재한다 (END)
    -----------------------------------------------------------------------------------------------------------------------------------------------
    -- 2. DM_PLN_CFM_SELLING_PRICE 기준으로 SCM_MST_FUTURE_PRICE 데이터 동기화 (END)
    --=============================================================================================================================================
    -- [E20251223-000672]_굳이 TEMP로 계속 담아 작업을 하지 않아도됨. 간략하게 진행하기 위해 원소스 주석 후 생성한다 (END)

    -- [PJ2025-50017] MKT_FCST 수정으로 DM_PLN_MKT_FCST의 BALANCE 데이터 재생성
    -- [E20251223-000672]_DROP, TEMP 테이블은 가장 상단으로 이동한다 (START)
    /*
    IF OBJECT_ID (N'tempdb..#SEND_TARGET_DATA', N'U') IS NOT NULL THEN
        DROP TABLE #SEND_TARGET_DATA

    CREATE TABLE #SEND_TARGET_DATA
    ( DIVISION_ID		NVARCHAR(30) NOT NULL
    , PROJECT_CODE		NVARCHAR(50) NOT NULL
    , SCM_SITE_ID		NVARCHAR(30) NOT NULL
    , ITEM_ID			NVARCHAR(50) NOT NULL
    , DOM_EXP			NVARCHAR(03) NOT NULL
    , FCST_TYPE			NVARCHAR(20) NOT NULL
    , INCOTERMS			NVARCHAR(10) NOT NULL
    , PLANT_SITE_ID		NVARCHAR(30) NOT NULL
    , CELL_PROD_SITE_ID NVARCHAR(30) NULL
    , VMI_YN			NVARCHAR(01) NULL)*/
    -- [E20251223-000672]_DROP, TEMP 테이블은 가장 상단으로 이동한다 (END)

    -- [E20251223-000672]_해당 변수의 사용이유를 모르겠으니 주석처리
    --DECLARE @c_division_id         NVARCHAR(MAX);

    INSERT INTO SCM_MGR.GT_PRDM_SEND_TARGET_DATA
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, VMI_YN )
    SELECT DIVISION_ID, END_CUSTOMER AS PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, 'N' -- vmi_yn 초기값
      -- [E20251223-000672]_굳이 TEMP로 담을 필요 없이, 전달받은 데이터를 사용한다. TEMP 주석 후 전달받은 TABLE 사용하도록 수정(START)
      -- FROM  #results_MKT_FCST
    FROM SCM_MGR.GT_PRDM1_T_MAIN  --[E20260922-TMAINFIX] GT_PRDM_T_MAIN->GT_PRDM1_T_MAIN (SAVE 적재 GTT 일치)
      -- [E20251223-000672]_굳이 TEMP로 담을 필요 없이, 전달받은 데이터를 사용한다. TEMP 주석 후 전달받은 TABLE 사용하도록 수정(END)
    WHERE MEASURE IN ('MKT_FCST', 'VMI_In_Req')  --[E20260922-TMAINFIX] 'VMI_IN_REQ'->'VMI_In_Req' (Oracle 대소문자 구분, 저장값 실측)
    GROUP BY DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM_SEND_TARGET_DATA', NO_INVALIDATE => FALSE);

    SELECT NVL(COUNT(1), 0) INTO n_send_count FROM SCM_MGR.GT_PRDM_SEND_TARGET_DATA;

    IF n_send_count > 0 THEN
        -- [E20251223-000672]_해당 변수의 사용이유를 모르겠으니 주석처리
        --SET @c_division_id = (SELECT TOP 1 DIVISION_ID FROM #SEND_TARGET_DATA)
        --EXEC PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE @c_division_id, @p_plan_id = 'CALL'
        SCM_MGR.PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE(p_division_id => v_division_id, p_plan_id => 'CALL', o_result_cursor => v_qty_balance_rc);
        IF v_qty_balance_rc%ISOPEN THEN CLOSE v_qty_balance_rc; END IF;
    END IF;

    -- [E20251223-000672]_DROP, TEMP 테이블은 가장 상단으로 이동한다 (START)
    /*
    -- [PJ2025-50017] MKT_FCST 수정으로 DM_PLN_MKT_FCST의 MKT_AMT 데이터 업데이트
    IF OBJECT_ID (N'tempdb..#results', N'U') IS NOT NULL THEN
        DROP TABLE #results

    CREATE TABLE #results
    ( v_division_id		NVARCHAR(30) NOT NULL
    , v_project_code	NVARCHAR(50) NOT NULL
    , v_scm_site_id		NVARCHAR(30) NOT NULL
    , v_item_id			NVARCHAR(50) NOT NULL
    , v_dom_exp			NVARCHAR(03) NOT NULL
    , v_fcst_type		NVARCHAR(20) NOT NULL
    , v_incoterms		NVARCHAR(10) NOT NULL
    , v_measure			NVARCHAR(50) NOT NULL
    , v_plant_site_id	NVARCHAR(30) NOT NULL
    , v_yyyymmdd		NVARCHAR(08) NOT NULL
    , v_created_by		NVARCHAR(150) NULL )
    */
    -- [E20251223-000672]_DROP, TEMP 테이블은 가장 상단으로 이동한다 (END)

    INSERT INTO SCM_MGR.GT_PRDM_RESULTS
    ( V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_MEASURE, V_PLANT_SITE_ID, V_YYYYMMDD, V_CREATED_BY )
    SELECT DIVISION_ID, END_CUSTOMER AS PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, p_created_by AS CREATED_BY
    -- [E20251223-000672]_굳이 TEMP로 담을 필요 없이, 전달받은 데이터를 사용한다. TEMP 주석 후 전달받은 TABLE 사용하도록 수정(START)
    --FROM  #results_MKT_FCST
    FROM SCM_MGR.GT_PRDM1_T_MAIN  --[E20260922-TMAINFIX] GT_PRDM_T_MAIN->GT_PRDM1_T_MAIN (SAVE 적재 GTT 일치)
    -- [E20251223-000672]_굳이 TEMP로 담을 필요 없이, 전달받은 데이터를 사용한다. TEMP 주석 후 전달받은 TABLE 사용하도록 수정(END)
    WHERE DIVISION_ID   = v_division_id
      AND MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'LOC', 'KRW', 'USD') -- [E20251223-000672]_'LOC', 'KRW', 'USD'메져를 추가하여 한번에 조회한다  --[E20260922-TMAINFIX] 'VMI_IN_REQ'->'VMI_In_Req' (Oracle 대소문자 구분, 저장값 실측)
      AND YYYYMMDD  >= v_plan_start_yyyymmdd
    GROUP BY DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD;
    -- [E20251223-000672]_굳이 해당 부분으로 담을 필요 없이, 한번에 전달받은 TEMP 테이블에서 담는다. 필요없는 부분 주석처리 (START)
    /*
    UNION
    SELECT DISTINCT
             DIVISION_ID
           , END_CUSTOMER	AS PROJECT_CODE
           , SCM_SITE_ID
           , ITEM_ID
           , DOM_EXP
           , FCST_TYPE
           , INCOTERMS
           , MEASURE
           , PLANT_SITE_ID
           , YYYYMMDD
           , @v_created_by		AS CREATED_BY
    FROM  #results_FUTURE_PRICE
    WHERE DIVISION_ID	= @v_division_id
    AND   MEASURE IN ('LOC', 'KRW', 'USD')
    AND   YYYYMMDD		>= @v_plan_start_yyyymmdd
    GROUP BY DIVISION_ID
           , END_CUSTOMER
           , SCM_SITE_ID
           , ITEM_ID
           , DOM_EXP
           , FCST_TYPE
           , INCOTERMS
           , MEASURE
           , PLANT_SITE_ID
           , YYYYMMDD
    */
    -- [E20251223-000672]_굳이 해당 부분으로 담을 필요 없이, 한번에 전달받은 TEMP 테이블에서 담는다. 필요없는 부분 주석처리 (END)

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM_RESULTS', NO_INVALIDATE => FALSE);

    --[E20251021-000634]_주석처리한 부분 주석 삭제
    SELECT NVL(COUNT(1), 0) INTO n_result_count FROM SCM_MGR.GT_PRDM_RESULTS WHERE V_DIVISION_ID = '40';

    IF n_result_count > 0 THEN
        SCM_MGR.PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE;
    END IF;

    ---------------------------------------------------------------------------------------------------------------------------------------------------
    -- [E20251223-000672]_작업이 모두 종료되었으므로, 사용했던 모든 TEMP 테이블 종료 시 DROP 작업 진행 (START)
    -- GTT는 ON COMMIT PRESERVE ROWS이므로 TRUNCATE로 정리
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM1_T_MAIN';  --[E20260922-TMAINFIX] GT_PRDM_T_MAIN->GT_PRDM1_T_MAIN (SAVE 적재 GTT 일치)
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_RESULTS';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_SEND_TARGET_DATA';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_TEMP_MKT_DEMAND_PLAN';
    EXECUTE IMMEDIATE 'TRUNCATE TABLE SCM_MGR.GT_PRDM_TEMP_SELLING_PRICE';
    -- [E20251223-000672]_작업이 모두 종료되었으므로, 사용했던 모든 TEMP 테이블 종료 시 DROP 작업 진행 (END)
    ---------------------------------------------------------------------------------------------------------------------------------------------------

    COMMIT;

    --=====================================================================================================================================================
    -- 종료 LOG (START)
    v_log_type    := 'END';
    v_log_message := '########## END of procedure ##########';
    --SET @v_description = '@p_division_id : ' + @p_division_id ;
    d_event_date  := SYSDATE;
    BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, v_log_type, n_log_count, v_log_message, v_description, d_event_date, v_created_by, v_proc_input, NULL, NULL, NULL); END;
    -- 종료 LOG (END)
    --=====================================================================================================================================================

    OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MESSAGE FROM DUAL;

EXCEPTION
    --=====================================================================================================================================================
    -- 오류 발생시 TRANSACTION 롤백 및 로그적재 (START)
    WHEN OTHERS THEN
        ---------------------------------------------------------------------------------------------------------------------------------------------------
        -- ERROR LOG VALUE SAVE (START)
        --[E20260309-000271]_오류가 발생하는 경우 정상적으로 찍히지 않아서 수정함 (START)
        --ROLLBACK TRANSACTION PR_DM_PLN_CFM_TO_MKT_FCST;  --[E20260309-000271]_원소스주석처리
        ROLLBACK;
        --[E20260309-000271]_오류가 발생하는 경우 정상적으로 찍히지 않아서 수정함 (END)

        v_log_type    := 'ERROR';
        v_sql_code    := TO_CHAR(SQLCODE);
        v_sql_errmsg  := SQLERRM;
        v_backtrace   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        v_log_message := SUBSTR(v_sql_errmsg, 1, 1000);
        v_description := SUBSTR(v_backtrace, 1, 500);
        d_event_date  := SYSDATE;

        BEGIN SCM_MGR.PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, v_log_type, n_log_count, v_log_message, v_description, d_event_date, v_created_by, v_proc_input, v_sql_code, v_sql_errmsg, v_backtrace); END;
        -- ERROR LOG VALUE SAVE (END)
        ---------------------------------------------------------------------------------------------------------------------------------------------------

        RAISE_APPLICATION_ERROR(-20001, '[' || v_sql_code || '] ' || v_sql_errmsg || ' | ' || v_backtrace);
    -- 오류 발생시 TRANSACTION 롤백 및 로그적재 (END)
    --=====================================================================================================================================================

END P_PR_DM_PLN_CFM_TO_MKT_FCST;

    -- [2026-09-15 UIPKG] standalone PR_SCM_MST_EXCHANGE_RATE 취합
PROCEDURE P_PR_SCM_MST_EXCHANGE_RATE
(
      P_BATCH_YN  VARCHAR2 DEFAULT 'Y'  /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가하여 배치수행/화면수행 구분 */
)
/*
    * Program ID   : PR_SCM_MST_EXCHANGE_RATE
    * Description  : Chempion 환율 I/F Procedure
    * PARAMETER    : N/A
    * DESCRIPTION  : Chempion 환율 I/F
    * I/F Table    : XIF_GSC_MOVE_EXCHANGE_RATE_SN
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    * 2021.05.13   P.C.I          PJ20209642R Chempion 환율 I/F
    * 2022.03.25   sclee          PJ20216891 LGES Digital SCM 3 Level 가속화를 위한 개선 - 새사업부 추가
    * 2022.05.11   HWI1993        GM JV 수정
    * 2022.11.17   kdw2819        [C20221116-000471]환율정보 수신 배치 오류
    * 2022.11.28   chano0612      [C20221124-000290]환율 IF관련 수정 요청 건
    * 2025.06.24   kjiyoon        [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 - 화면 호출용 프로시저 수행 성공/실패 output 추가
    * 2025.07.03   kjiyoon        [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가
    * 2025.09.15   김준규           IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경
    * 2026.03.24   김준규           [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06	ZIONEX		[PJ202650304] NextSCM Migration
    */
 AS
    /* ------------------------------------------------------------------------- */
    C_DIVISION_ID       VARCHAR2(30 CHAR);
    C_SCENARIO_TYPE_CD  VARCHAR2(06 CHAR);
    C_PLN_PERIOD_YYYYMM VARCHAR2(06 CHAR);
    C_CURRENCY_CD       VARCHAR2(15 CHAR);
    C_IF_SEQ            NUMBER(16, 0);
    V_RECEIVE_CNT       NUMBER(16, 0);
    V_BATCH_USER        VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE          VARCHAR2(30 CHAR);
    N_LOG_COUNT         INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    N_HISTORY_SEQ       NUMBER;
    V_IFSEQNO           VARCHAR2(30 CHAR);
    V_IN_PARA_DATA      VARCHAR2(4000 CHAR);
    V_RESULT_CURSOR     SYS_REFCURSOR;
    CUR_E               SYS_REFCURSOR;

    CURSOR CUR_D IS
        SELECT DIVISION_ID
          FROM GT_SMER_I_DIVISION;
BEGIN

    /* ------------------------------------------------------------------------- */
    /* LOG 용 변수 설정 */
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := ('P_BATCH_YN = ' || NVL(P_BATCH_YN, 'X')); /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* GTT 초기화 : TRUNCATE 는 DDL 이라 암시 COMMIT 이 발생해 상위 트랜잭션의 ROLLBACK 을 무력화한다 -> DELETE 사용 */
    DELETE FROM GT_SMER_I_DIVISION;

    /* 자동차, ESS, 소형 작업 */
    /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 START */
    /* 기존로직 주석처리 */
    /* INSERT +NO_PARALLEL INTO GT_SMER_I_DIVISION (division_id) */
    /* SELECT DIVISION_ID */
    /* FROM SCM_MST_DIVISION */
    /* WHERE ATTRIBUTE3 IN ('40','81', '82' ) */
    IF P_BATCH_YN = 'Y' THEN
        /* 대상 사업부 */
        INSERT
          INTO GT_SMER_I_DIVISION
             ( DIVISION_ID )
        SELECT DIVISION_ID
          FROM SCM_MST_DIVISION
         WHERE ATTRIBUTE3 IN ('81', '82');

        /* 대상 IF 환율 */

        /* CUR_E CURSOR LOCAL FOR */
        OPEN CUR_E FOR
        SELECT SCENARIO_TYPE_CD
             , PLN_PERIOD_YYYYMM
             , CURRENCY_CD
             , IF_SEQ
          FROM (SELECT E.SCENARIO_TYPE_CD
                     , E.PLN_PERIOD_YYYYMM
                     , E.CURRENCY_CD
                     , E.IF_SEQ
                  FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN E
                 WHERE NVL(E.TRANSF_FLAG, 'N') = 'N'
                   AND SCENARIO_TYPE_CD IN ('ML', 'RF') /* [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
                 GROUP BY E.SCENARIO_TYPE_CD, E.PLN_PERIOD_YYYYMM, E.CURRENCY_CD, E.IF_SEQ) X
         ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD;
    ELSE
        /* 대상 사업부 */
        INSERT
          INTO GT_SMER_I_DIVISION
             ( DIVISION_ID )
        SELECT DIVISION_ID
          FROM SCM_MST_DIVISION
         WHERE ATTRIBUTE3 IN ('40');

        /* 대상 IF 환율 */

        /* CUR_E CURSOR LOCAL FOR */
        OPEN CUR_E FOR
        SELECT SCENARIO_TYPE_CD
             , PLN_PERIOD_YYYYMM
             , CURRENCY_CD
             , IF_SEQ
          FROM (SELECT E.SCENARIO_TYPE_CD
                     , E.PLN_PERIOD_YYYYMM
                     , E.CURRENCY_CD
                     , E.IF_SEQ
                  FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN E
                 WHERE E.TRANSF_DATE = (SELECT MAX(A.TRANSF_DATE)
                                          FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN A
                                         WHERE 1 = 1
                                           AND A.SCENARIO_TYPE_CD IN ('ML', 'RF'))
                   AND SCENARIO_TYPE_CD IN ('ML', 'RF') /* [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
                 GROUP BY E.SCENARIO_TYPE_CD, E.PLN_PERIOD_YYYYMM, E.CURRENCY_CD, E.IF_SEQ) X
         ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD;
    END IF;

    /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 END */
    /* DELETE FROM DM_MST_EXCHANGE_RATE WHERE YYYYMMDD BETWEEN TO_CHAR(ADD_MONTHS(SYSDATE, 0), 'YYYYMMDD') || '01' AND TO_CHAR(ADD_MONTHS(SYSDATE, 12), 'YYYYMMDD') || '01' */
    /* [C20221124-000290] DM_MST_EXCHANGE_RATE 에 존재하는 기존 데이터를 삭제한다. */
    /* 위로 로직 이동해서 아래 CURSOR 주석처리 - [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
    /* CURSOR 환율 정보 수신 (KEY : SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ) */

    /* CUR_E CURSOR LOCAL FOR */
    /* select SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ */
    /* from ( select E.SCENARIO_TYPE_CD */
    /*           , E.PLN_PERIOD_YYYYMM */
    /*           , E.CURRENCY_CD */
    /*           , E.IF_SEQ */
    /*       from XIF_GSC_MOVE_EXCHANGE_RATE_SN E */

    /*       AND SCENARIO_TYPE_CD IN ('ML', 'RF') [C20221124-000290] SCENARIO_TYPE_CD를 ML, RF만 등록한다.. */
    /*       group by E.SCENARIO_TYPE_CD */
    /*           , E.PLN_PERIOD_YYYYMM */
    /*           , E.CURRENCY_CD */
    /*           , E.IF_SEQ */
    /*           ) x */
    /* ORDER BY PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ, SCENARIO_TYPE_CD */
    /* CURSOR 환율 정보 수신 (KEY : SCENARIO_TYPE_CD, PLN_PERIOD_YYYYMM, CURRENCY_CD, IF_SEQ) */

    /* CUR_D CURSOR FOR */

    NULL;

    /* ------------------------------------------------------------------------- */

    /* Start 환율 Cursor */
    V_RECEIVE_CNT := 0;

    FETCH CUR_E
        INTO C_SCENARIO_TYPE_CD, C_PLN_PERIOD_YYYYMM, C_CURRENCY_CD, C_IF_SEQ;
    WHILE (CUR_E%FOUND) LOOP
        /* ----------------------------------------------------------------- */
        /* * IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경 시작 */
        /* 변경전 상태 USING ( SELECT B.DIVISION_ID, A.YYYYMMDD, A.CURRENCY, REPLACE(A.UNIT_CURRENCY, 'CNY', 'RMB') UNIT_CURRENCY, A.EXCHANGE_PRICE */
        MERGE INTO DM_MST_EXCHANGE_RATE DME
        USING (SELECT B.DIVISION_ID
                    , A.YYYYMMDD
                    , A.CURRENCY
                    , /*REPLACE(A.UNIT_CURRENCY, 'CNY', 'RMB')*/ A.UNIT_CURRENCY AS UNIT_CURRENCY
                    , A.EXCHANGE_PRICE
                 FROM (SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'KRW' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , KRW_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ
                        UNION ALL
                       SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'USD' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , USD_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ
                        UNION ALL
                       SELECT PLN_YYYYMM || '01' AS YYYYMMDD
                            , 'EUR' AS CURRENCY
                            , CURRENCY_CD UNIT_CURRENCY
                            , EUR_CNVT_RATE EXCHANGE_PRICE
                         FROM XIF_GSC_MOVE_EXCHANGE_RATE_SN
                        WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
                          AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
                          AND CURRENCY_CD = C_CURRENCY_CD
                          AND IF_SEQ = C_IF_SEQ) A
                    , GT_SMER_I_DIVISION B) XXX
        /* * IT20250117A NERP ROLLIN 3차 현재 CNY를 RMB로 변경 저장하는 것을 CNY 그대로 저장변경 종료 */
        ON (DME.DIVISION_ID = XXX.DIVISION_ID AND DME.YYYYMMDD = XXX.YYYYMMDD AND DME.CURRENCY = XXX.CURRENCY AND DME.UNIT_CURRENCY = XXX.UNIT_CURRENCY)
        WHEN MATCHED THEN
            UPDATE SET DME.EXCHANGE_PRICE = XXX.EXCHANGE_PRICE
                     , DME.LAST_UPDATED_BY = 'SYSTEM'
                     , DME.LAST_UPDATE_DATE = SYSDATE
        WHEN NOT MATCHED THEN
            INSERT
                 ( DIVISION_ID
                 , YYYYMMDD
                 , CURRENCY
                 , UNIT_CURRENCY
                 , EXCHANGE_PRICE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            VALUES ( XXX.DIVISION_ID
                   , XXX.YYYYMMDD
                   , XXX.CURRENCY
                   , XXX.UNIT_CURRENCY
                   , XXX.EXCHANGE_PRICE
                   , 'SYSTEM'
                   , SYSDATE
                   , 'SYSTEM'
                   , SYSDATE );
        /* ----------------------------------------------------------------- */
        /* 배치일때만 업데이트하도록 조건추가 - [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : P_BATCH_YN 파라미터 추가 */
        IF P_BATCH_YN = 'Y' THEN
            /* I/F Table TRANSF_FLAG 변경 */
            UPDATE XIF_GSC_MOVE_EXCHANGE_RATE_SN
               SET TRANSF_FLAG = 'Y'
             WHERE SCENARIO_TYPE_CD = C_SCENARIO_TYPE_CD
               AND PLN_PERIOD_YYYYMM = C_PLN_PERIOD_YYYYMM
               AND CURRENCY_CD = C_CURRENCY_CD
               AND IF_SEQ = C_IF_SEQ;
        END IF;

        V_RECEIVE_CNT := V_RECEIVE_CNT + 1;
        /* ----------------------------------------------------------------- */
        FETCH CUR_E
            INTO C_SCENARIO_TYPE_CD, C_PLN_PERIOD_YYYYMM, C_CURRENCY_CD, C_IF_SEQ;
    END LOOP;
    CLOSE CUR_E;

    /* End  환율 Cursor */
    /* Start  Sales Price, Sales Plan Cursor */
    /* select 'V_RECEIVE_CNT', V_RECEIVE_CNT */
    IF (V_RECEIVE_CNT > 0) THEN

        OPEN CUR_D;
        FETCH CUR_D
            INTO C_DIVISION_ID;
        WHILE (CUR_D%FOUND) LOOP

            /* select 'C_DIVISION_ID', C_DIVISION_ID */
            /* Sales Price Update */
            PKG_DMF0020.P_DMF0020_SAVE_SCM_MST_FUTURE_PRICE_CONVERSION(C_DIVISION_ID, V_RESULT_CURSOR);   /* [E20260824-PKGCONSOL] 단독 SP -> PKG 내부 프로시저. 시그니처 동일(2-arg) 실측 확인 */

            /* Sales Plan Update */
            PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW(C_DIVISION_ID, 'EXCHANGE_RATE');

            FETCH CUR_D
                INTO C_DIVISION_ID;
        END LOOP;
        CLOSE CUR_D;

    END IF;
    /* End  Sales Price, Sales Plan Cursor */
    /* 트랜잭션 종료 */
    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;
    NULL; /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 */


EXCEPTION
    WHEN OTHERS THEN

        /* ERROR LOG */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || TO_CHAR(NULL);
        D_EVENT_DATE  := SYSTIMESTAMP;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        NULL;
        /* [PJ2025-50188]소형 매출계획 동기화 개선 고도화 : 사용자 환율팝업 적용 */


        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || $$PLSQL_UNIT || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END P_PR_SCM_MST_EXCHANGE_RATE;

    -- [2026-09-15 UIPKG] standalone PR_SCM_MST_EXCHANGE_RATE_UI 취합
PROCEDURE P_PR_SCM_MST_EXCHANGE_RATE_UI (
    P_BATCH_YN      IN  VARCHAR2 DEFAULT 'N',
    O_RESULT_CURSOR OUT SYS_REFCURSOR
) AS
    V_ERR        VARCHAR2(200 CHAR);
    V_TARGET_CNT NUMBER;
BEGIN
    --[E20260915-BPSIFNODATA] 반영 대상 0건 안내 (사용자 지시 2026-09-15).
    --  공유 배치 PR_SCM_MST_EXCHANGE_RATE 는 대상이 없어도 오류 없이 끝나 이 래퍼가 항상 success 를 돌려줬고,
    --  화면은 "정상 반영" 토스트 후 값이 그대로여서 반영된 것으로 오인됐다(사내 XIF 0행 실측).
    --  → 배치 CUR_E 와 **동일 조건**으로 대상 건수를 먼저 세고, 0건이면 배치를 호출하지 않고 안내를 돌려준다.
    --  CODE <> '0' 이면 FE(ExchangeRateModal handleBpsIf)가 RESULT_MSG 를 Alert 로 표시한다 — FE 무변경.
    --  공유 배치 본문은 무수정(야간 배치 P_BATCH_YN='Y' 경로 영향 없음).
    IF P_BATCH_YN = 'Y' THEN
        SELECT COUNT(*)
          INTO V_TARGET_CNT
          FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN E
         WHERE NVL(E.TRANSF_FLAG, 'N') = 'N'
           AND E.SCENARIO_TYPE_CD IN ('ML', 'RF');
    ELSE
        SELECT COUNT(*)
          INTO V_TARGET_CNT
          FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN E
         WHERE E.TRANSF_DATE = (SELECT MAX(A.TRANSF_DATE)
                                  FROM SCM_MGR.XIF_GSC_MOVE_EXCHANGE_RATE_SN A
                                 WHERE A.SCENARIO_TYPE_CD IN ('ML', 'RF'))
           AND E.SCENARIO_TYPE_CD IN ('ML', 'RF');
    END IF;

    IF V_TARGET_CNT = 0 THEN
        OPEN O_RESULT_CURSOR FOR
            SELECT '1' AS CODE, '반영할 환율 정보가 없습니다' AS RESULT_MSG, CAST(NULL AS VARCHAR2(200 CHAR)) AS EVENT FROM DUAL;
        RETURN;
    END IF;

    P_PR_SCM_MST_EXCHANGE_RATE(P_BATCH_YN);
    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'success' AS RESULT_MSG, CAST(NULL AS VARCHAR2(200 CHAR)) AS EVENT FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        V_ERR := SUBSTR(SQLERRM, 1, 200);
        ROLLBACK;
        OPEN O_RESULT_CURSOR FOR
            SELECT '9' AS CODE, 'fail' AS RESULT_MSG, V_ERR AS EVENT FROM DUAL;
END P_PR_SCM_MST_EXCHANGE_RATE_UI;


-- ====================================================================================================
-- [E20261002-BTNAUTH] DMF0082 버튼 활성화 여부 조회 SP 신설 (사용자 요청 2026-10-02)
--
--  목적: 화면 오픈 직후 Division 초기값 확정 시 / Division 변경 시, **메인 조회 없이** 버튼 노출 여부를 판정한다.
--        종전에는 판정 근거(메저별 편집권한)가 P_DMF0082_GET_MAIN_DATA 의 O_RC4 로만 내려와 조회 후에야 알 수 있었다.
--
--  IN  : p_division_id / p_created_by(세션 사용자) / p_user_group — P_DMF0082_GET_MAIN_DATA 와 동일 축·동일 명명.
--  OUT :
--   O_RC1 (1행) 버튼 활성화 — 현행 화면 판정식과 동일 규칙
--       EDIT_AUTH_YN    : 편집 가능 메저가 하나라도 있는가 (O_RC2 에 EDIT_AUTH_YN='Y' 존재)
--       SAVE_YN         : EDIT_AUTH_YN='Y' 이고 Division <> '82'  (82 = 조회 전용 — SAVE V82-00 가드와 동일)
--       DELETE_YN       : SAVE_YN 과 동일
--       INSERT_YN       : SAVE_YN='Y' 이고 MKT_FCST / LOC / VMI_In_Req 중 하나라도 'Y' (SCP Planner 단독 = 신규행 불가)
--       PRICE_BATCH_YN  : Division <> '82' 이고 LOC='Y'  (Price Batch Input)
--       EXCEL_FORM_YN   : Division 81 계열  (Excel Form — [E20260819-XLS81LOC])
--       EXCEL_UPLOAD_YN : Division 81 계열  (Excel Upload — 상동)
--   O_RC2 (메저별) MEASURE / EDIT_AUTH_YN('Y'·'N'·'T'=시간창 밖) / TODAY_LIMIT_YN / TODAY_DAY_LIST
--       = P_DMF0082_GET_MAIN_DATA O_RC4 와 **같은 컬럼·같은 값** (화면의 메저 편집권한 반영부를 그대로 쓸 수 있다)
--
--  ⚠ 이 SP 가 판정하지 않는 것 (화면에 그대로 남는 조건):
--     - 메뉴 버튼 권한(그룹×메뉴×버튼, SCM_ADM_USER_GR_MNU_BTN_MPG_M) — 화면이 별도로 받아 AND 한다.
--     - 조회 버전의 편집 가능 여부(과거 버전 = 조회 전용) — 조회 결과 행의 EDIT_FLAG 로 판정한다.
--  ⚠ 메저 편집권한 산출부는 P_DMF0082_GET_MAIN_DATA 의 해당 블록을 **원문 그대로** 옮긴 것이다(요일·시간창·LIMIT 포함).
--     그쪽 블록을 고치면 이 블록도 같이 고쳐야 조회 전/후 버튼 상태가 어긋나지 않는다.
-- ====================================================================================================
PROCEDURE P_DMF0082_GET_BUTTON_AUTH
(
    p_division_id    IN  VARCHAR2
  , p_created_by     IN  VARCHAR2
  , p_user_group     IN  VARCHAR2
  , O_RC1            OUT SYS_REFCURSOR   /* 버튼 활성화 1행 */
  , O_RC2            OUT SYS_REFCURSOR   /* 메저별 편집권한 (= GET_MAIN_DATA O_RC4) */
  , O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
IS
    VA_PROGRAM_ID       VARCHAR2(50 CHAR) := 'DMF0082';

    V_EDIT_AUTH_YN      VARCHAR2(1 CHAR) := 'N';
    V_MKT_FCST_YN       VARCHAR2(1 CHAR) := 'N';
    V_LOC_YN            VARCHAR2(1 CHAR) := 'N';
    V_VMI_YN            VARCHAR2(1 CHAR) := 'N';
    V_SAVE_YN           VARCHAR2(1 CHAR) := 'N';
    V_INSERT_YN         VARCHAR2(1 CHAR) := 'N';
    V_PRICE_BATCH_YN    VARCHAR2(1 CHAR) := 'N';
    V_EXCEL_YN          VARCHAR2(1 CHAR) := 'N';

    -- LOG 용 변수
    V_PROGRAM_NAME      VARCHAR2(200 CHAR);
    V_LOG_TYPE          VARCHAR2(100 CHAR);
    N_LOG_COUNT         PLS_INTEGER := 0;
    V_LOG_MESSAGE       VARCHAR2(4000 CHAR);
    V_DESCRIPTION       VARCHAR2(4000 CHAR);
    D_EVENT_DATE        DATE := SYSDATE;

    -- EXCEPTION 블록 필수 변수
    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100 CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    -- ▼▼▼ P_DMF0082_GET_MAIN_DATA 메저 편집권한 산출 블록 — 원문 그대로 ([E20261002-BTNAUTH]) ▼▼▼
    DELETE FROM SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE;

    --1). GET_ADMIN_GROUP_MEASURE 룩업에서 데이터를 TEMP로 담는다
    --    (CROSS APPLY STRING_SPLIT × 2 → CROSS JOIN LATERAL REGEXP_SUBSTR CONNECT BY)
    --    (C-11) DATEPART(WEEKDAY)/CONVERT(...,24) → TO_CHAR(SYSDATE,'DY','NLS_DATE_LANGUAGE=ENGLISH') / TO_CHAR(SYSDATE,'HH24MI')
    --    (C-7)  ISNULL(REPLACE(x,' ',''),'')='' 빈값 판정 → REPLACE(x,' ','') IS NULL (빈값 = 제한 없음 = 행 유지)
    INSERT INTO SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE
    ( USER_GROUP, DIVISION_ID, MEASURE, DAYS, FROM_TIME, TO_TIME, LIMIT_MEASURE )
    SELECT B.USER_GROUP, B.DIVISION_ID, B.MEASURE, B.DAYS, B.FROM_TIME, B.TO_TIME, LM.TOKEN AS LIMIT_MEASURE
    FROM  (SELECT A.SEGMENT1 AS USER_GROUP, A.SEGMENT3 AS DIVISION_ID, A.SEGMENT4 AS MEASURE, DT.TOKEN AS DAYS
                , A.ATTRIBUTE2 AS FROM_TIME, A.ATTRIBUTE3 AS TO_TIME, A.ATTRIBUTE4 AS LIMIT_MEASURE
           FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL A
           CROSS JOIN LATERAL (SELECT REGEXP_SUBSTR(A.ATTRIBUTE1, '[^,]+', 1, LEVEL) AS TOKEN
                               FROM   DUAL
                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(A.ATTRIBUTE1, ','), 0) + 1) DT
           WHERE  A.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
           AND    A.VALID_YN = 'Y'
           AND (A.SEGMENT1 = p_user_group  --[AUTHUNION 2026-08-04] 보유그룹 합집합 판정 (사용자 확정)
             OR A.SEGMENT1 IN (SELECT G.USER_GR_ID FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                             WHERE G.USER_ID IN (p_user_group, p_created_by) AND G.USE_YN = 'Y'))
           AND    A.SEGMENT2 = VA_PROGRAM_ID
           AND    A.SEGMENT3 = p_division_id
          ) B
    CROSS JOIN LATERAL (SELECT REGEXP_SUBSTR(B.LIMIT_MEASURE, '[^,]+', 1, LEVEL) AS TOKEN
                        FROM   DUAL
                        CONNECT BY LEVEL <= NVL(REGEXP_COUNT(B.LIMIT_MEASURE, ','), 0) + 1) LM
    WHERE (REPLACE(B.DAYS, ' ', '') IS NULL
           OR B.DAYS = TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH'))   --일~토 = SUN~SAT
    AND   (REPLACE(B.FROM_TIME, ' ', '') IS NULL
           OR B.FROM_TIME <= TO_CHAR(SYSDATE, 'HH24MI'))
    AND   (REPLACE(B.TO_TIME, ' ', '') IS NULL
           OR B.TO_TIME >= TO_CHAR(SYSDATE, 'HH24MI'));

    -- ====================================================================================================
    -- TEMP_ADMIN_GROUP_MEASURE — 메저별 당일 수정권한 ([E20260819-LIMITMEAS] EDIT_AUTH_YN 원천 = 요일/시간창 반영 INTO)
    -- ====================================================================================================

    DELETE FROM SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE;

    INSERT INTO SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE (MEASURE, EDIT_AUTH_YN, TODAY_LIMIT_YN, TODAY_DAY_LIST)
    SELECT A.SEGMENT4 AS MEASURE
         , CASE WHEN EXISTS (
                    SELECT 1
                    FROM   SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE B
                    WHERE  B.MEASURE = A.SEGMENT4
               ) THEN 'Y'
                --[E20260826-AUTHVIEW] 시간창 因 잠금 구분값 'T' — 보유그룹의 시간창 정의 행(A1 요일)이 있으나
                --  지금이 창 밖이라 INTO 에서 탈락한 경우. FE 는 'Y' 비교라 'T'=잠금 유지, MSG00477 표기에만 사용.
                --  (그룹 미보유 因 잠금 'N' 과 구분 — DM Viewer 등에 시간 메시지 오표기 방지)
                WHEN EXISTS (
                    SELECT 1
                    FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL T
                    WHERE  T.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
                    AND    T.VALID_YN = 'Y'
                    AND   (T.SEGMENT1 = p_user_group
                           OR T.SEGMENT1 IN (SELECT G.USER_GR_ID FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                                             WHERE G.USER_ID IN (p_user_group, p_created_by) AND G.USE_YN = 'Y'))
                    AND    T.SEGMENT2 = VA_PROGRAM_ID
                    AND    T.SEGMENT3 = p_division_id
                    AND    T.SEGMENT4 = A.SEGMENT4
                    AND    REPLACE(T.ATTRIBUTE1, ' ', '') IS NOT NULL
               ) THEN 'T'
                ELSE 'N' END AS EDIT_AUTH_YN
         , CASE WHEN A.ATTRIBUTE1 IS NOT NULL THEN 'Y' ELSE 'N' END AS TODAY_LIMIT_YN
         , A.ATTRIBUTE1 AS TODAY_DAY_LIST
    FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL A
    WHERE  A.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
    AND    A.VALID_YN    = 'Y'
    AND    A.SEGMENT2    = VA_PROGRAM_ID
    GROUP BY A.SEGMENT4, A.ATTRIBUTE1;

    /* [E20260820-MEASRULE] measure 별 입력 게이트 명세 반영 (2026-08-20 PI 테스트 시트 — 사용자 확인 요청):
       - LOC        : 항상 입력 가능 (룩업 그룹 통제 제외 — "Unit Price(LOC) 입력 가능해야 함")
       - AS_In_Req  : 81 계열('81%')·82 + DM Planner (W/S) 소속일 때만 (AUTHUNION 동형 판정)
       - VMI_In_Req : 40·82 + 권한 무관. 행 단위 "Sales Site VMI_YN='Y'" 조건은 행별 후보 콤보
                      FcstPriceEditMeasure + DM_UI_EDITABLE_MEASURE VMI_COND 가 담당(실측 기구현) — 메저 게이트만 개방.
       - MKT_FCST/SCM_FCST : 종전대로 GET_ADMIN_GROUP_MEASURE 룩업 통제(요일/시간창/LIMIT — E20260819-LIMITMEAS).
       신규 division(81_JV 등)은 패턴으로 자동 커버. 근거 실측(2026-08-20): 81_JV 는 룩업·SITE·SITE_ITEM 전부 0행
       (division 프로비저닝 미완) + 순수 W/S 계정은 40 룩업 행 부재로 전 메저 'N' — LIMITMEAS 회귀 아님(구 코드 동일 필터). */
    /* [E20260825-SCPPLOC] SCP Planner = LOC 편집 불가 정정 (사용자 지적 2026-08-25).
       AS-IS 파리티: DMF0082_FcstNPrice_Mgmt.cs L9172 은 bEDIT_AUTH_LOC 을 GET_ADMIN_GROUP_MEASURE
       룽업 결과(Tables[3] MEASURE='LOC' 의 EDIT_FLAG) 그대로 읽고, L9229 case "LOC" 에서
       권한이 없으면 언락하지 않아 셀이 잠긴다. 룽업상 SCP Planner 행은 SCM_FCST(MON 1500~1830) 1건뿐이라
       AS-IS 에서 SCP Planner 는 LOC 를 못 고친다. 위 2026-08-20 measure 게이트 명세의 무조건 개방이 그 통제를
       벗겨 SCP Planner 까지 편집 가능해졌다.
       ⚠ 개방을 통째로 걷어내면 룽업 미프로비저닝 division(81/81_JV/82 = 룽업 0행)까지 잠겨
       원장 REQ:1ST-41-1 / REQ:1ST-63-3 (81 에서 LOC 입력) 이 깨진다 → 두 조건을 모두 만족할 때만 제외한다:
         (1) 해당 division 에 GET_ADMIN_GROUP_MEASURE 룽업이 존재(현재 40) 그리고
         (2) 세션 보유그룹에 'SCP Planner' 포함(AUTHUNION 동형 판정 — 타 그룹 겸유 시는 룽업이 이미 'Y' 부여).
       다른 그룹·다른 메저·다른 division 은 문장 불변(회귀 0). */
    UPDATE SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE
    SET    EDIT_AUTH_YN = 'Y'
    WHERE  MEASURE = 'LOC'
    AND  ( NOT EXISTS (SELECT 1
                       FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L
                       WHERE  L.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
                       AND    L.VALID_YN    = 'Y'
                       AND    L.SEGMENT2    = VA_PROGRAM_ID
                       AND    L.SEGMENT3    = p_division_id)   -- 룽업 미프로비저닝 division = 종전 개방 유지
           --[E20260825-81AUTH] 81 계열은 룩업 전권 — 강제 개방 분기에서 제외 (LOC = 룩업 4그룹 통제, W/S 제외).
           --  40 은 현행 유지(비 SCP 강제 개방 — REQ:1ST-36-1 계보).
           OR ( p_division_id NOT LIKE '81%'
                AND NOT ( p_user_group = 'SCP Planner'
                    OR EXISTS (SELECT 1
                               FROM   SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                               WHERE  G.USER_ID    IN (p_user_group, p_created_by)
                               AND    G.USER_GR_ID = 'SCP Planner'
                               AND    G.USE_YN     = 'Y') )    -- SCP Planner 미보유 = 종전 개방 유지
                --[E20260826-AUTHVIEW] DM Viewer = 편집 전면 불가 (사용자 지시 2026-08-26) — 강제 개방에서 제외.
                --  AS-IS 파리티: 40 룩업 LOC 4그룹(ADMIN/DM ADMIN/DM Planner/SCM PI Admin)에 Viewer 없음 = bEDIT_AUTH_LOC false.
                --  겸유자(Viewer+편집그룹)는 룩업 INTO 경유 기본 'Y' 라 회귀 없음.
                AND NOT ( p_user_group = 'DM Viewer'
                    OR EXISTS (SELECT 1
                               FROM   SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                               WHERE  G.USER_ID    IN (p_user_group, p_created_by)
                               AND    G.USER_GR_ID = 'DM Viewer'
                               AND    G.USE_YN     = 'Y') ) )
         );

    UPDATE SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE
    SET    EDIT_AUTH_YN = CASE WHEN (p_division_id LIKE '81%' OR p_division_id = '82')
                                AND EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                                            WHERE G.USER_ID IN (p_user_group, p_created_by)
                                            AND   G.USER_GR_ID = 'DM Planner (W/S)' AND G.USE_YN = 'Y')
                               THEN 'Y' ELSE 'N' END
    WHERE  MEASURE = 'AS_In_Req';

    UPDATE SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE
    SET    EDIT_AUTH_YN = CASE WHEN p_division_id IN ('40', '82')
                                --[E20260826-AUTHVIEW] DM Viewer 단독(편집그룹 룩업 행 INTO 부재) = VMI 차단 (사용자 지시 2026-08-26).
                                --  겸유자(Viewer+편집그룹)는 INTO 에 그 그룹의 VMI 행이 있어 개방 유지 — 회귀 없음.
                                --[E20260826-SCPVMI] SCP Planner 도 제외 (사용자 지시 2026-08-26 "시간 밖 = 수정·INSERT/DELETE 전면 불가").
                                --  AS-IS 파리티: 40 VMI 룩업 4그룹(ADMIN/DM ADMIN/DM Planner/SCM PI Admin)에 SCP 없음 = bEDIT_AUTH_VMI false.
                                --  겸유자(편집그룹 겸유)는 INTO 에 그 그룹 VMI 행이 있어 개방 유지 — 회귀 없음.
                                AND NOT ( ( p_user_group IN ('DM Viewer', 'SCP Planner')
                                            OR EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M G
                                                       WHERE G.USER_ID IN (p_user_group, p_created_by)
                                                       AND   G.USER_GR_ID IN ('DM Viewer', 'SCP Planner') AND G.USE_YN = 'Y') )
                                          AND NOT EXISTS (SELECT 1 FROM SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE B
                                                          WHERE B.MEASURE = 'VMI_In_Req') )
                               THEN 'Y' ELSE 'N' END
    WHERE  MEASURE = 'VMI_In_Req';

    --3). [E20260819-LIMITMEAS] LIMIT_MEASURE 존재 시 해당 메저 강제 'N' (donor 이식 — EDIT_FLAG→EDIT_AUTH_YN 컬럼명만 상이)
    /* [E20260907-LIMITMEAS-DIV] LIMIT_MEASURE 잠금 판정 = **division 범위** (사용자 지시 2026-09-07).
       요건 원문 = 본 블록 말미 [E20250729-000433] "월요일 SCM FCST 입력 시 MKT FCST 수정 불가".
       ⛔ 구 판정의 결함: 잠금 근거를 GTT_TEMP_INTO_GROUP_MEASURE(= **내 보유그룹 행만**)에서 찾았다.
          40 의 SCM_FCST(MON 1000~1900, A4=MKT_FCST) 행은 ADMIN/SCM PI Admin/SCP Planner 3그룹에만
          있어서, 그 그룹이 아닌 DM Planner 로 로그인하면 INTO 에 LIMIT_MEASURE 행이 0건 →
          V_LIMIT_CNT=0 → 강제 'N' 이 아예 발동하지 않고 MKT_FCST 가 열린 채 남았다
          (실증 2026-09-07 MON 16:35 · eunah.koo(DM Planner)/40 · INTO 3행 전부 A4 NULL).
       ⭐ 잠금의 주체는 '내 그룹'이 아니라 '이 division 의 SCM_FCST 입력 시간창'이므로
          SEGMENT1(그룹) 조건을 빼고 (SEGMENT2, SEGMENT3) 범위로 판정한다. 요일·시간창 판정식은
          위 INTO 적재분과 **동일**(빈값 = 제한 없음)이라 그룹 축만 넓힌 변경이다.
       ⚠ 81 계열의 ATTRIBUTE4 는 '메저명'이 아니라 잠금 유발 **그룹명**('SCP Planner')이다
          ([E20260825-81AUTH], 아래 블록 담당) → 토큰이 같은 division 의 SEGMENT1(그룹명)과
          일치하면 이 해석에서 제외한다. 두 해석은 상호배타.
       실측(2026-09-07): DMF0082 의 A4 보유행은 전 division 이 SCM_FCST→'MKT_FCST' 21행뿐이고
          그룹명 토큰은 0건이라, 이 정정의 실효 = "SCM_FCST 시간창 동안 MKT_FCST 전원 잠금". */
    UPDATE SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE A
    SET    A.EDIT_AUTH_YN = 'N'
    WHERE  EXISTS (SELECT 1
                   FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L
                   CROSS JOIN LATERAL (SELECT REGEXP_SUBSTR(L.ATTRIBUTE4, '[^,]+', 1, LEVEL) AS TOKEN
                                       FROM   DUAL
                                       CONNECT BY LEVEL <= NVL(REGEXP_COUNT(L.ATTRIBUTE4, ','), 0) + 1) LM
                   WHERE  L.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
                   AND    L.VALID_YN    = 'Y'
                   AND    L.SEGMENT2    = VA_PROGRAM_ID
                   AND    L.SEGMENT3    = p_division_id
                   AND    REPLACE(L.ATTRIBUTE4, ' ', '') IS NOT NULL
                   AND   (REPLACE(L.ATTRIBUTE1, ' ', '') IS NULL          -- 요일 미지정 = 상시
                          OR INSTR(',' || REPLACE(L.ATTRIBUTE1, ' ', '') || ',',
                                   ',' || TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') || ',') > 0)
                   AND   (REPLACE(L.ATTRIBUTE2, ' ', '') IS NULL
                          OR L.ATTRIBUTE2 <= TO_CHAR(SYSDATE, 'HH24MI'))
                   AND   (REPLACE(L.ATTRIBUTE3, ' ', '') IS NULL
                          OR L.ATTRIBUTE3 >= TO_CHAR(SYSDATE, 'HH24MI'))
                   AND    TRIM(LM.TOKEN) = A.MEASURE
                   AND    NOT EXISTS (SELECT 1                            -- 토큰=그룹명 → 81AUTH 해석
                                      FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L3
                                      WHERE  L3.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
                                      AND    L3.VALID_YN    = 'Y'
                                      AND    L3.SEGMENT2    = VA_PROGRAM_ID
                                      AND    L3.SEGMENT3    = p_division_id
                                      AND    L3.SEGMENT1    = TRIM(LM.TOKEN)));


    /* [E20260825-81AUTH] LIMIT_AUTH(그룹 잠금) 해석 — AS-IS DMF0003 판 의미 이식 (사용자 확정 2026-08-25).
       81 계열 룩업 행의 ATTRIBUTE4 는 "메저명"이 아니라 **잠금 유발 권한그룹명**('SCP Planner')이다:
       그 그룹의 같은 (S2,S3,S4) 행이 지금 요일·시간창 안이면 내 메저는 편집 불가.
       (원형 = PKG_DMF0003 AUTHGATE L10270~10296. 40 의 LIMIT_MEASURE(메저 잠금)과 공존 —
        A4 값이 그룹 행(SEGMENT1)과 매칭될 때만 발동. 40 의 'MKT_FCST' 토큰은 그룹 미매칭 = 영향 0.)
       합집합(AUTHUNION) 보존 — 보유그룹 행 중 잠기지 않은 행이 하나라도 있으면 Y 유지.
       ⚠ 한계: A4 가 콤마 다중 그룹이면 토큰별 개별 판정(현 데이터 = 단일 'SCP Planner' 뿐). */
    UPDATE SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE A
    SET    A.EDIT_AUTH_YN = 'N'
    WHERE  A.EDIT_AUTH_YN = 'Y'
    AND    EXISTS (SELECT 1 FROM SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE B WHERE B.MEASURE = A.MEASURE)
    AND    NOT EXISTS (
             SELECT 1
             FROM   SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE B
             WHERE  B.MEASURE = A.MEASURE
             AND    NOT EXISTS (
                      SELECT 1
                      FROM   SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL L2
                      WHERE  L2.LOOKUP_TYPE = 'GET_ADMIN_GROUP_MEASURE'
                      AND    L2.VALID_YN    = 'Y'
                      AND    L2.SEGMENT2    = VA_PROGRAM_ID
                      AND    L2.SEGMENT3    = p_division_id
                      AND    L2.SEGMENT4    = B.MEASURE
                      AND    L2.SEGMENT1    = B.LIMIT_MEASURE   -- LIMIT 토큰 = 그룹명일 때만 발동
                      AND    REPLACE(L2.ATTRIBUTE1, ' ', '') IS NOT NULL  -- 시간창 정의 행만
                      AND    INSTR(',' || REPLACE(L2.ATTRIBUTE1, ' ', '') || ',',
                                   ',' || TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') || ',') > 0
                      AND    L2.ATTRIBUTE2 <= TO_CHAR(SYSDATE, 'HH24MI')
                      AND    L2.ATTRIBUTE3 >= TO_CHAR(SYSDATE, 'HH24MI')));

    DELETE FROM SCM_MGR.GTT_TEMP_INTO_GROUP_MEASURE;
    -- ▲▲▲ P_DMF0082_GET_MAIN_DATA 메저 편집권한 산출 블록 끝 ▲▲▲

    -- Division 미확정(화면 오픈 직후 콤보 도착 전 호출) = 전 버튼 'N' · 메저 0행.
    --   위 블록의 LOC 강제 개방은 "룩업 미등록 division" 을 개방 대상으로 보므로 빈 division 이 열리지 않게 비운다.
    IF TRIM(p_division_id) IS NULL THEN
        DELETE FROM SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE;
    END IF;

    SELECT NVL(MAX(CASE WHEN EDIT_AUTH_YN = 'Y' THEN 'Y' END), 'N')
         , NVL(MAX(CASE WHEN MEASURE = 'MKT_FCST'   AND EDIT_AUTH_YN = 'Y' THEN 'Y' END), 'N')
         , NVL(MAX(CASE WHEN MEASURE = 'LOC'        AND EDIT_AUTH_YN = 'Y' THEN 'Y' END), 'N')
         , NVL(MAX(CASE WHEN MEASURE = 'VMI_In_Req' AND EDIT_AUTH_YN = 'Y' THEN 'Y' END), 'N')
    INTO   V_EDIT_AUTH_YN, V_MKT_FCST_YN, V_LOC_YN, V_VMI_YN
    FROM   SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE;

    -- 82 = 조회 전용 (SAVE V82-00 가드와 동일 판정식)
    IF V_EDIT_AUTH_YN = 'Y' AND p_division_id <> '82' THEN
        V_SAVE_YN := 'Y';
    END IF;
    -- 신규행 생성 자격 — SCP Planner 단독은 SCM_FCST 수정만 가능 (MKT_FCST·LOC·VMI_In_Req 전부 'N')
    IF V_SAVE_YN = 'Y' AND (V_MKT_FCST_YN = 'Y' OR V_LOC_YN = 'Y' OR V_VMI_YN = 'Y') THEN
        V_INSERT_YN := 'Y';
    END IF;
    IF V_LOC_YN = 'Y' AND p_division_id <> '82' THEN
        V_PRICE_BATCH_YN := 'Y';
    END IF;
    IF p_division_id LIKE '81%' THEN
        V_EXCEL_YN := 'Y';
    END IF;

    OPEN O_RC1 FOR
        SELECT p_division_id     AS DIVISION_ID
             , V_INSERT_YN       AS INSERT_YN
             , V_SAVE_YN         AS DELETE_YN
             , V_SAVE_YN         AS SAVE_YN
             , V_PRICE_BATCH_YN  AS PRICE_BATCH_YN
             , V_EXCEL_YN        AS EXCEL_FORM_YN
             , V_EXCEL_YN        AS EXCEL_UPLOAD_YN
             , V_EDIT_AUTH_YN    AS EDIT_AUTH_YN
        FROM   DUAL;

    OPEN O_RC2 FOR
        SELECT MEASURE, EDIT_AUTH_YN, TODAY_LIMIT_YN, TODAY_DAY_LIST
        FROM   SCM_MGR.GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE
        ORDER BY MEASURE;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'p_division_id' VALUE p_division_id,
            'p_created_by'  VALUE p_created_by,
            'p_user_group'  VALUE p_user_group
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
END P_DMF0082_GET_BUTTON_AUTH;

END PKG_DMF0082;
/
SHOW ERRORS PACKAGE BODY PKG_DMF0082
-- ##### END PACKAGE BODY PKG_DMF0082

-- ##### START PACKAGE BODY PKG_NSCM_UI_COM_LOOKUP
CREATE OR REPLACE PACKAGE BODY         "PKG_NSCM_UI_COM_LOOKUP" 
AS

    PROCEDURE PR_GET_LOOKUP_INFO_LIST ( 
                                        P_LOOKUP_TYPE	IN 		VARCHAR2,
                                        O_CURSOR		  OUT		SYS_REFCURSOR
                                      ) 
    AS
    --------------------------------------------------------------
        V_MASTER_CNT	INT := 0;
        V_SQL    VARCHAR2(8000);  
        V_COLS   VARCHAR2(4000);
        V_SELECT_COLS VARCHAR2(4000); -- 최종 SELECT할 컬럼 리스트
        -------------------------------------------------------------- 
        V_ERR_CODE  NUMBER;
        V_ERR_MSG   VARCHAR2(4000);
    --------------------------------------------------------------    
		BEGIN
	
          -- LOOKUP TABLE
  			
          -- 0. validation
          SELECT  COUNT(1)
            INTO  V_MASTER_CNT
            FROM  SCM_ADM_LOOKUP_MASTER
           WHERE  LOOKUP_TYPE = P_LOOKUP_TYPE;
  				
          IF(V_MASTER_CNT <> 1) THEN 
            RAISE_APPLICATION_ERROR(-20002, 'Error: LOOKUP_TYPE [' || P_LOOKUP_TYPE || '] is not valid type.');
          END IF;
          -- 0. validation End
  			
          -- 1. 조회 컬럼 
            SELECT 
                LISTAGG('''' || HEADER_VAL || ''' AS "' || HEADER_VAL || '"', ', ') WITHIN GROUP (ORDER BY MIN_LVL),
                LISTAGG('"' || HEADER_VAL || '"', ', ') WITHIN GROUP (ORDER BY MIN_LVL)
            INTO V_COLS, V_SELECT_COLS
            FROM (
            	SELECT HEADER_VAL, MIN(LVL) MIN_LVL
    			FROM (
	                SELECT SEGMENT1 AS HEADER_VAL, 1 AS LVL FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND SEGMENT1 IS NOT NULL AND SEGMENT1 <> '/'
	                UNION ALL
	                SELECT SEGMENT2, 2 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND SEGMENT2 IS NOT NULL AND SEGMENT2 <> '-'
	                UNION ALL
	                SELECT SEGMENT3, 3 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND SEGMENT3 IS NOT NULL AND SEGMENT3 <> '-'
	                UNION ALL
	                SELECT SEGMENT4, 4 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND SEGMENT4 IS NOT NULL AND SEGMENT4 <> '-'
	                UNION ALL
	                SELECT SEGMENT5, 5 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND SEGMENT5 IS NOT NULL AND SEGMENT5 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE1, 6 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE1 IS NOT NULL AND ATTRIBUTE1 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE2, 7 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE2 IS NOT NULL AND ATTRIBUTE2 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE3, 8 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE3 IS NOT NULL AND ATTRIBUTE3 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE4, 9 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE4 IS NOT NULL AND ATTRIBUTE4 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE5, 10 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE5 IS NOT NULL AND ATTRIBUTE5 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE6, 11 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE6 IS NOT NULL AND ATTRIBUTE6 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE7, 12 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE7 IS NOT NULL AND ATTRIBUTE7 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE8, 13 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE8 IS NOT NULL AND ATTRIBUTE8 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE9, 14 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE9 IS NOT NULL AND ATTRIBUTE9 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE10, 15 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE10 IS NOT NULL AND ATTRIBUTE10 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE11, 16 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE11 IS NOT NULL AND ATTRIBUTE11 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE12, 17 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE12 IS NOT NULL AND ATTRIBUTE12 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE13, 18 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE13 IS NOT NULL AND ATTRIBUTE13 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE14, 19 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE14 IS NOT NULL AND ATTRIBUTE14 <> '-'
	                UNION ALL
	                SELECT ATTRIBUTE15, 20 FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE = P_LOOKUP_TYPE AND ATTRIBUTE15 IS NOT NULL AND ATTRIBUTE15 <> '-'
	            )
    			GROUP BY HEADER_VAL
            );
  					   
  --			   DBMS_OUTPUT.PUT_LINE('COLS>>>>  '||V_SELECT_COLS);
  			   
            -- 2. 동적 SQL 조립
            -- 가장 바깥쪽 SELECT에서 LOOKUP_TYPE과 동적 컬럼들만 지정하여 ROW_IDENTIFIER를 제거합니다.
            V_SQL := 'SELECT LOOKUP_TYPE, ' || V_SELECT_COLS || ' FROM (
                        SELECT * FROM (
                            SELECT 
                                LOOKUP_TYPE, ROW_IDENTIFIER, M_VAL AS COL_HEADER, D_VAL AS DATA_VALUE
                                , ROW_DISPLAY_SEQ /* 2026.09.15 AJS */
                            FROM (
                                SELECT 
                                    SALD.LOOKUP_TYPE, 
                                    SALD.ROWID AS ROW_IDENTIFIER,
                                    SALD.DISPLAY_SEQ AS ROW_DISPLAY_SEQ, /* 2026.09.15 AJS */
                                    SALM.SEGMENT1 AS M1, SALM.SEGMENT2 AS M2, SALM.SEGMENT3 AS M3, SALM.SEGMENT4 AS M4, SALM.SEGMENT5 AS M5,
                                    SALD.SEGMENT1 AS D1, SALD.SEGMENT2 AS D2, SALD.SEGMENT3 AS D3, SALD.SEGMENT4 AS D4, SALD.SEGMENT5 AS D5,
                      SALM.ATTRIBUTE1 AS M6, SALM.ATTRIBUTE2 AS M7, SALM.ATTRIBUTE3 AS M8, SALM.ATTRIBUTE4 AS M9, SALM.ATTRIBUTE5 AS M10,
                                    SALD.ATTRIBUTE1 AS D6, SALD.ATTRIBUTE2 AS D7, SALD.ATTRIBUTE3 AS D8, SALD.ATTRIBUTE4 AS D9, SALD.ATTRIBUTE5 AS D10,
                      SALM.ATTRIBUTE6 AS M11, SALM.ATTRIBUTE7 AS M12, SALM.ATTRIBUTE8 AS M13, SALM.ATTRIBUTE9 AS M14, SALM.ATTRIBUTE10 AS M15,
                                    SALD.ATTRIBUTE6 AS D11, SALD.ATTRIBUTE7 AS D12, SALD.ATTRIBUTE8 AS D13, SALD.ATTRIBUTE9 AS D14, SALD.ATTRIBUTE10 AS D15,
                      SALM.ATTRIBUTE11 AS M16, SALM.ATTRIBUTE12 AS M17, SALM.ATTRIBUTE13 AS M18, SALM.ATTRIBUTE14 AS M19, SALM.ATTRIBUTE15 AS M20,
                                    SALD.ATTRIBUTE11 AS D16, SALD.ATTRIBUTE12 AS D17, SALD.ATTRIBUTE13 AS D18, SALD.ATTRIBUTE14 AS D19, SALD.ATTRIBUTE15 AS D20
                                FROM SCM_ADM_LOOKUP_MASTER SALM
                                JOIN SCM_ADM_LOOKUP_MASTER_DETAIL SALD ON SALM.LOOKUP_TYPE = SALD.LOOKUP_TYPE
                                WHERE SALM.VALID_YN = ''Y'' AND SALD.VALID_YN = ''Y''
								  AND SALM.LOOKUP_TYPE = ''' || P_LOOKUP_TYPE || '''
                            )
                            UNPIVOT (
                                (M_VAL, D_VAL) FOR LVL IN (
                                    (M1, D1) AS 1, (M2, D2) AS 2, (M3, D3) AS 3, (M4, D4) AS 4, (M5, D5) AS 5,
                      (M6, D6) AS 6, (M7, D7) AS 7, (M8, D8) AS 8, (M9, D9) AS 9, (M10, D10) AS 10,
                      (M11, D11) AS 11, (M12, D12) AS 12, (M13, D13) AS 13, (M14, D14) AS 14, (M15, D15) AS 15,
                      (M16, D16) AS 16, (M17, D17) AS 17, (M18, D18) AS 18, (M19, D19) AS 19, (M20, D20) AS 20
                                )
                            )
                            WHERE M_VAL <> ''-''
                        )
                        PIVOT (
                            MAX(DATA_VALUE)
                            FOR COL_HEADER IN (' || V_COLS || ')
                        )
                )';
		--	              ) ORDER BY 1'; -- 첫 번째 컬럼(LOOKUP_TYPE) 기준으로 정렬
				
                -- 2. SORT_ORD 존재 여부에 따른 ORDER BY 추가 로직
				-- V_COLS 문자열 안에 'SORT_ORD'라는 단어가 있는지 확인합니다.
				-- SYSTEM_ADM 은 상세 테이블 DISPLAY_SEQ 순으로 정렬                -- 2026.09.15 AJS
				/* 2026.09.30 AJS 수정 (START) */
				/* WEEK_WORK_TIME 편입 : 요일 구분 목록을 상세 테이블 DISPLAY_SEQ 순으로 정렬 */
--				IF P_LOOKUP_TYPE = 'SYSTEM_ADM' THEN                              -- 2026.09.15 AJS
				IF P_LOOKUP_TYPE IN ('SYSTEM_ADM', 'WEEK_WORK_TIME') THEN
				/* 2026.09.30 AJS 수정 (END) */
				    V_SQL := V_SQL || ' ORDER BY ROW_DISPLAY_SEQ ASC';            -- 2026.09.15 AJS
--				IF INSTR(V_COLS, '''SORT_ORD''') > 0 THEN
				ELSIF INSTR(V_COLS, '''SORT_ORD''') > 0 THEN                      -- 2026.09.15 AJS
				    -- SORT_ORD 컬럼이 PIVOT 리스트에 있다면 해당 컬럼으로 정렬
				    V_SQL := V_SQL || ' ORDER BY TO_NUMBER("SORT_ORD") ASC';
				ELSE
				    -- 없다면 기본값인 첫 번째 컬럼(LOOKUP_TYPE)으로 정렬
				    V_SQL := V_SQL || ' ORDER BY 1';
				END IF;
							    -- 디버깅용 쿼리 출력
			    DBMS_OUTPUT.PUT_LINE(V_SQL);
		
			    -- 3. 커서 오픈
			    OPEN O_CURSOR FOR V_SQL;
	   

		--------------------------------------------------------------
		EXCEPTION
    --------------------------------------------------------------  
		    WHEN OTHERS THEN
		    	V_ERR_CODE := SQLCODE;
		        V_ERR_MSG := REPLACE(V_ERR_MSG, CHR(10), SQLERRM); 
--	        	V_ERR_MSG := REPLACE(V_ERR_MSG, CHR(13), '');
	        	RAISE_APPLICATION_ERROR(V_ERR_CODE, V_ERR_MSG);
    --------------------------------------------------------------          
		END;
--------------------------------------------------------------	
END PKG_NSCM_UI_COM_LOOKUP;
/
SHOW ERRORS PACKAGE BODY PKG_NSCM_UI_COM_LOOKUP
-- ##### END PACKAGE BODY PKG_NSCM_UI_COM_LOOKUP

-- ##### START PACKAGE BODY PKG_S39V2
CREATE OR REPLACE PACKAGE BODY PKG_S39V2
IS

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.ORIGIN_DIVISION_ID  = A.ORIGIN_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.CELL_TYPE NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN  A
             , GT_0039_SCP_PLAN_VERSION B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , GT_0039_SCP_PLAN_VERSION  B
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION   A
             , SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V2;
/
SHOW ERRORS PACKAGE BODY PKG_S39V2
-- ##### END PACKAGE BODY PKG_S39V2

-- ##### START PACKAGE BODY PKG_S39V3
CREATE OR REPLACE PACKAGE BODY PKG_S39V3
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
    BEGIN
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.ORIGIN_DIVISION_ID  = A.ORIGIN_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.CELL_TYPE NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN  A
             , GT_0039_SCP_PLAN_VERSION B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , GT_0039_SCP_PLAN_VERSION  B
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION   A
             , SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V3;
/
SHOW ERRORS PACKAGE BODY PKG_S39V3
-- ##### END PACKAGE BODY PKG_S39V3

-- ##### START PACKAGE BODY PKG_S39V4
CREATE OR REPLACE PACKAGE BODY PKG_S39V4
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
    BEGIN
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.ORIGIN_DIVISION_ID  = A.ORIGIN_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN  A
             , GT_0039_SCP_PLAN_VERSION B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(D.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , GT_0039_SCP_PLAN_VERSION  B
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION   A
             , SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V4;
/
SHOW ERRORS PACKAGE BODY PKG_S39V4
-- ##### END PACKAGE BODY PKG_S39V4

-- ##### START PACKAGE BODY PKG_S39V5
CREATE OR REPLACE PACKAGE BODY PKG_S39V5
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
    BEGIN
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.ORIGIN_DIVISION_ID  = V_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN A
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(D.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           /* ★AS-IS 와 결과가 갈리는 자리 (구조적으로 재현 불가)
              F_DEST_ATA_DATE 는 이관 시 빈 문자열이 NULL 로 들어와 MSSQL 의 '빈 문자열' 과
              '진짜 NULL' 을 Oracle 에서 구분할 수 없다. AS-IS 는 진짜 NULL 만 미착으로 보아
              빈 문자열 건을 제외하지만(82 기준 8,197 건), 업무 의미로는 값이 비었으면 미착이므로
              아래 조건은 그 건을 포함한다. 포함 여부는 업무 확정 후 조정할 것. */
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V5;
/
SHOW ERRORS PACKAGE BODY PKG_S39V5
-- ##### END PACKAGE BODY PKG_S39V5

-- ##### START PACKAGE BODY PKG_S39V6
CREATE OR REPLACE PACKAGE BODY PKG_S39V6
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
    BEGIN
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '40';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '40' 고정 - 40만 조회 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '82';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '82' 고정 - 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.ORIGIN_DIVISION_ID  = V_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN A
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(D.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           /* ★AS-IS 와 결과가 갈리는 자리 (구조적으로 재현 불가)
              F_DEST_ATA_DATE 는 이관 시 빈 문자열이 NULL 로 들어와 MSSQL 의 '빈 문자열' 과
              '진짜 NULL' 을 Oracle 에서 구분할 수 없다. AS-IS 는 진짜 NULL 만 미착으로 보아
              빈 문자열 건을 제외하지만(82 기준 8,197 건), 업무 의미로는 값이 비었으면 미착이므로
              아래 조건은 그 건을 포함한다. 포함 여부는 업무 확정 후 조정할 것. */
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V6;
/
SHOW ERRORS PACKAGE BODY PKG_S39V6
-- ##### END PACKAGE BODY PKG_S39V6

-- ##### START PACKAGE BODY PKG_S39V7
CREATE OR REPLACE PACKAGE BODY PKG_S39V7
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
    BEGIN
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '40';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '40' 고정 - 40만 조회 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '82';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '82' 고정 - 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.ORIGIN_DIVISION_ID  = V_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN A
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(D.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           /* ★AS-IS 와 결과가 갈리는 자리 (구조적으로 재현 불가)
              F_DEST_ATA_DATE 는 이관 시 빈 문자열이 NULL 로 들어와 MSSQL 의 '빈 문자열' 과
              '진짜 NULL' 을 Oracle 에서 구분할 수 없다. AS-IS 는 진짜 NULL 만 미착으로 보아
              빈 문자열 건을 제외하지만(82 기준 8,197 건), 업무 의미로는 값이 비었으면 미착이므로
              아래 조건은 그 건을 포함한다. 포함 여부는 업무 확정 후 조정할 것. */
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_S39V7;
/
SHOW ERRORS PACKAGE BODY PKG_S39V7
-- ##### END PACKAGE BODY PKG_S39V7

-- ##### START PACKAGE BODY PKG_SCM0002
CREATE OR REPLACE PACKAGE BODY         "PKG_SCM0002" IS


/* ============================================================
   1. P_SCM0002_GET_BOD_FG_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_BOD_FG_POPUP
(
    P_DIVISION_ID          IN VARCHAR2,
    P_BOD_ID               IN VARCHAR2,
    P_FROM_SITE            IN VARCHAR2,
    P_TO_SITE              IN VARCHAR2,
    P_PLAN_START_YYYYMMDD  IN DATE,
    P_OPER_GRP             IN VARCHAR2,
    P_ITEM_ID              IN VARCHAR2,
    P_ORIGION_DIVISION_ID  IN VARCHAR2 DEFAULT '',
    DEBUG_MODE             IN VARCHAR2 DEFAULT 'F',
    O_RC1                  OUT SYS_REFCURSOR,
    O_RESULT_CURSOR        OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : P_SCM0002_GET_BOD_POPUP
 * Description  : BOD Popup 조회
  * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/01/15   byunghunjung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/05/24   KYH            ITEM_ID , OPERATION GROUP 추가
 * 2018/05/29   KYH            중복되는 값 없애기위해 distinct 추가
 * 2018/09/05   ygkim          @p_origion_division_id 추가
 * 2021/07/07   khj79          PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD 2단계 개발 : FROM,TO 추가 , scp_mst_bod_v=> scp_mst_bod_n_v
 * 2022.05.13   LSC            PJ20216891 Digital SCM 3 Level 가속화를 위한 개선 : GM JV 추가
 * 2026.03.24   kimcd          [PJ20264226] NextSCM Pilot 설계 및 개발
 */

    -- first : to site
    -- second : from site

    V_PROGRAM_NAME  VARCHAR2(200 CHAR);
    V_PLAN_START_DATE  VARCHAR2(8 CHAR);
    V_MDQRY            VARCHAR2(32767 CHAR) := '';
    V_POS              PLS_INTEGER;
    V_LEN              PLS_INTEGER;

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    V_PLAN_START_DATE := TO_CHAR(P_PLAN_START_YYYYMMDD, 'YYYYMMDD');

    V_MDQRY := V_MDQRY || ' SELECT DISTINCT                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     '''' AS CHK                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , '''' AS IS_LOCK                                                                                           ' || CHR(10);
    --SET @mDQry = @mDQry + '   , (m.DIVISION_ID + m.FROM_SITE + m.TO_SITE + m.transport_mode) as key_idx                               ' + char(10) ;
    IF P_DIVISION_ID = 'EE_UC' THEN
        V_MDQRY := V_MDQRY || '     , (''EE_UC'' || M.FROM_SITE || M.TO_SITE || M.TRANSPORT_MODE || M.BOD_ID) AS KEY_IDX                   ' || CHR(10);
    ELSIF P_DIVISION_ID = 'EE' THEN
        V_MDQRY := V_MDQRY || '     , (''EE'' || M.FROM_SITE || M.TO_SITE || M.TRANSPORT_MODE || M.BOD_ID) AS KEY_IDX                      ' || CHR(10);
    ELSE
        V_MDQRY := V_MDQRY || '     , (M.DIVISION_ID || M.FROM_SITE || M.TO_SITE || M.TRANSPORT_MODE || M.BOD_ID) AS KEY_IDX               ' || CHR(10);
    END IF;

    V_MDQRY := V_MDQRY || '     , M.BOD_ID                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.TO_SITE   AS FIRST_SITE                                                                                ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , SCM_MGR.FN_GET_SCM_SITE_DESCRIPTION(M.DIVISION_ID, M.TO_SITE)   AS FIRST_SITE_NAME                      ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.FROM_SITE AS SECOND_SITE                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , SCM_MGR.FN_GET_SCM_SITE_DESCRIPTION(M.DIVISION_ID, M.FROM_SITE) AS SECOND_SITE_NAME                     ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.PRIORITY                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.INCOTERMS                                                                                              ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.TRANSPORT_MODE                                                                                         ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_MON                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_TUE                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_WED                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_THU                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_FRI                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_SAT                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_SUN                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.LT_TOTAL                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , TO_DATE(''' || V_PLAN_START_DATE || ''', ''YYYYMMDD'')                                                   ' || CHR(10);
    V_MDQRY := V_MDQRY || '       + NVL((SELECT SHIP_FROZEN FROM SCM_MGR.SCM_MST_SITE                                                      ' || CHR(10);
    V_MDQRY := V_MDQRY || '              WHERE DIVISION_ID = M.DIVISION_ID AND SCM_SITE_ID = FROM_SITE), 0)  AS SHIP_FROZEN                ' || CHR(10);
    --IF @p_division_id != 'EE'
    --  BEGIN SET @mDQry = @mDQry + '       where division_id='''+@p_division_id+''' and scm_site_id= from_site)                            ' + char(10) ; END
    --ELSE
    --  BEGIN SET @mDQry = @mDQry + '       where division_id='''+@p_origion_division_id+''' and scm_site_id= from_site)                    ' + char(10) ; END
    -- BOD 2단계 개발 : 시작
    V_MDQRY := V_MDQRY || '     , TO_DATE(M.FROM_YYYYMMDD, ''YYYYMMDD'') AS FROM_YYYYMMDD                                                  ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , TO_DATE(M.TO_YYYYMMDD,   ''YYYYMMDD'') AS TO_YYYYMMDD                                                    ' || CHR(10);
    --SET @mDQry = @mDQry + ' FROM scp_mst_bod_v m  WITH(NOLOCK)                                                                            ' + char(10) ;
    V_MDQRY := V_MDQRY || ' FROM SCM_MGR.SCP_MST_BOD_N_V M                                                                                 ' || CHR(10);
    -- BOD 2단계 개발 : 끝
    V_MDQRY := V_MDQRY || ' INNER JOIN SCM_MGR.SCM_MST_SITE S                                                                              ' || CHR(10);
    V_MDQRY := V_MDQRY || '     ON M.DIVISION_ID = S.DIVISION_ID AND M.FROM_SITE = S.SCM_SITE_ID                                           ' || CHR(10);
    V_MDQRY := V_MDQRY || ' INNER JOIN SCM_MGR.SCM_MST_SITE_ITEM_PRIORITY P                                                                ' || CHR(10);
    V_MDQRY := V_MDQRY || '     ON M.DIVISION_ID = P.DIVISION_ID AND P.ITEM_ID = ''' || P_ITEM_ID || '''                                   ' || CHR(10);
    V_MDQRY := V_MDQRY || ' WHERE 1 = 1                                                                                                    ' || CHR(10);

    IF P_DIVISION_ID = 'EE' THEN
        V_MDQRY := V_MDQRY || ' AND M.DIVISION_ID IN (''40'',''81'',''82'')                                                                ' || CHR(10);
    ELSIF P_DIVISION_ID = 'EE_UC' THEN
        V_MDQRY := V_MDQRY || ' AND M.DIVISION_ID = ''81_UC''                                                                              ' || CHR(10);
    ELSE
        V_MDQRY := V_MDQRY || ' AND M.DIVISION_ID = ''' || P_DIVISION_ID || '''                                                            ' || CHR(10);
    END IF;

    V_MDQRY := V_MDQRY || ' AND M.TO_SITE = ''' || P_TO_SITE || '''                                                                        ' || CHR(10);
    V_MDQRY := V_MDQRY || ' --and m.bod_id = @p_bod_id                                                                                     ' || CHR(10);
    V_MDQRY := V_MDQRY || ' AND S.OPERATION_GROUP = ''' || P_OPER_GRP || '''                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || ' ORDER BY TO_SITE ASC, FROM_SITE ASC                                                                            ' || CHR(10);

    IF DEBUG_MODE = 'T' THEN
        V_POS := 1;
        V_LEN := LENGTH(V_MDQRY);
        WHILE V_POS <= V_LEN LOOP
            DBMS_OUTPUT.PUT_LINE(SUBSTR(V_MDQRY, V_POS, 4000));
            V_POS := V_POS + 4000;
        END LOOP;
    END IF;

    OPEN O_RC1 FOR V_MDQRY;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID'         VALUE P_DIVISION_ID,
            'P_BOD_ID'              VALUE P_BOD_ID,
            'P_FROM_SITE'           VALUE P_FROM_SITE,
            'P_TO_SITE'             VALUE P_TO_SITE,
            'P_PLAN_START_YYYYMMDD' VALUE TO_CHAR(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'),
            'P_OPER_GRP'            VALUE P_OPER_GRP,
            'P_ITEM_ID'             VALUE P_ITEM_ID,
            'P_ORIGION_DIVISION_ID' VALUE P_ORIGION_DIVISION_ID,
            'DEBUG_MODE'            VALUE DEBUG_MODE
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_BOD_FG_POPUP;



/* ============================================================
   2. P_SCM0002_GET_BOD_SEMI_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_BOD_SEMI_POPUP
(
    P_DIVISION_ID          IN VARCHAR2,
    P_BOD_ID               IN VARCHAR2,
    P_FROM_SITE            IN VARCHAR2,
    P_TO_SITE              IN VARCHAR2,
    P_PLAN_START_YYYYMMDD  IN DATE,
    P_OPER_GRP             IN VARCHAR2,
    P_ITEM_ID              IN VARCHAR2,
    P_ORIGION_DIVISION_ID  IN VARCHAR2 DEFAULT '',
    DEBUG_MODE             IN VARCHAR2 DEFAULT 'F',
    O_RC1                  OUT SYS_REFCURSOR,
    O_RESULT_CURSOR        OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : SCM0002_GET_BOD_POPUP
 * Description  : BOD Popup 조회
  * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/01/15   byunghunjung    Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/05      KYH             ITEM_ID , OPERATION GROUP 추가
 * 2018/05/29 KYH           중복되는 값 없애기위해 distinct 추가
 * 2018/09/05   ygkim       @p_origion_division_id 추가, from_site 조건 제거, @p_oper_grp 조건 추가
 * 2021/07/07   khj79       PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD 2단계 개발 : FROM,TO 추가 , scp_mst_bod_v=> scp_mst_bod_n_v
 * 2022.05.13   LSC             PJ20216891 Digital SCM 3 Level 가속화를 위한 개선 : GM JV 추가
 * 2026.03.24   kimcd       [PJ20264226] NextSCM Pilot 설계 및 개발
 */

    -- first : from site
    -- second : to site

    V_PROGRAM_NAME     VARCHAR2(200 CHAR);
    V_PLAN_START_DATE  VARCHAR2(8 CHAR);
    V_MDQRY            VARCHAR2(32767 CHAR) := '';
    V_POS              PLS_INTEGER;
    V_LEN              PLS_INTEGER;

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    V_PLAN_START_DATE := TO_CHAR(P_PLAN_START_YYYYMMDD, 'YYYYMMDD');

    V_MDQRY := V_MDQRY || ' SELECT DISTINCT                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     '''' AS CHK                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , '''' AS IS_LOCK                                                                                           ' || CHR(10);
    --SET @mDQry = @mDQry + '   , (m.DIVISION_ID + m.FROM_SITE + m.TO_SITE + m.transport_mode) as key_idx                               ' + char(10) ;
    IF P_DIVISION_ID IN ('EE', 'EE_UC') THEN
        V_MDQRY := V_MDQRY || '     , (''' || P_DIVISION_ID || ''' || M.FROM_SITE || M.TO_SITE || M.TRANSPORT_MODE || M.BOD_ID) AS KEY_IDX  ' || CHR(10); -- BOD 2단계 개발 : BOD_ID 추가
    ELSE
        V_MDQRY := V_MDQRY || '     , (M.DIVISION_ID || M.FROM_SITE || M.TO_SITE || M.TRANSPORT_MODE || M.BOD_ID) AS KEY_IDX                ' || CHR(10); -- BOD 2단계 개발 : BOD_ID 추가
    END IF;

    V_MDQRY := V_MDQRY || '     , M.BOD_ID                                                                                                 ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.FROM_SITE AS FIRST_SITE                                                                                ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , SCM_MGR.FN_GET_SCM_SITE_DESCRIPTION(M.DIVISION_ID, M.FROM_SITE) AS FIRST_SITE_NAME                      ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.TO_SITE   AS SECOND_SITE                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , SCM_MGR.FN_GET_SCM_SITE_DESCRIPTION(M.DIVISION_ID, M.TO_SITE)   AS SECOND_SITE_NAME                     ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.PRIORITY                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.INCOTERMS                                                                                              ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.TRANSPORT_MODE                                                                                         ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_MON                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_TUE                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_WED                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_THU                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_FRI                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_SAT                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.DAYS_SUN                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , M.LT_TOTAL                                                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , CASE WHEN SUBSTR(M.FROM_SITE, 1, 4) = SUBSTR(M.TO_SITE, 1, 4) THEN                                       ' || CHR(10);
    V_MDQRY := V_MDQRY || '           TO_DATE(''' || V_PLAN_START_DATE || ''', ''YYYYMMDD'')                                                ' || CHR(10);

    IF P_DIVISION_ID NOT IN ('EE', 'EE_UC') THEN
        V_MDQRY := V_MDQRY || '           + NVL((SELECT NVL(SHIP_FROZEN, 0) FROM SCM_MGR.SCM_MST_SITE WHERE DIVISION_ID = ''' || P_DIVISION_ID || ''' AND SCM_SITE_ID = FROM_SITE), 0)   ' || CHR(10);
    ELSE
        V_MDQRY := V_MDQRY || '           + NVL((SELECT NVL(SHIP_FROZEN, 0) FROM SCM_MGR.SCM_MST_SITE WHERE DIVISION_ID = ''' || P_ORIGION_DIVISION_ID || ''' AND SCM_SITE_ID = FROM_SITE), 0)   ' || CHR(10);
    END IF;

    V_MDQRY := V_MDQRY || '       ELSE                                                                                                     ' || CHR(10);
    -- @@DATEFIRST - DATEPART(dw, GETDATE()) - 5 → Oracle: TRUNC(SYSDATE, 'IW') (직전 월요일)
    V_MDQRY := V_MDQRY || '           (TRUNC(SYSDATE, ''IW'') )                                                                         ' || CHR(10);
    V_MDQRY := V_MDQRY || '       END AS SHIP_FROZEN                                                                                        ' || CHR(10);
    -- BOD 2단계 개발 : 시작
    V_MDQRY := V_MDQRY || '     , TO_DATE(M.FROM_YYYYMMDD, ''YYYYMMDD'') AS FROM_YYYYMMDD                                                  ' || CHR(10);
    V_MDQRY := V_MDQRY || '     , TO_DATE(M.TO_YYYYMMDD,   ''YYYYMMDD'') AS TO_YYYYMMDD                                                    ' || CHR(10);
    --SET @mDQry = @mDQry + ' FROM scp_mst_bod_v m  WITH(NOLOCK)                                                                            ' + char(10) ;
    V_MDQRY := V_MDQRY || ' FROM SCM_MGR.SCP_MST_BOD_N_V M                                                                                 ' || CHR(10);
    -- BOD 2단계 개발 : 끝
    V_MDQRY := V_MDQRY || ' INNER JOIN SCM_MGR.SCM_MST_SITE_ITEM_PRIORITY P                                                                ' || CHR(10);
    V_MDQRY := V_MDQRY || '     ON M.DIVISION_ID = P.DIVISION_ID AND P.ITEM_ID = ''' || P_ITEM_ID || '''                                   ' || CHR(10);
    V_MDQRY := V_MDQRY || ' INNER JOIN SCM_MGR.SCM_MST_SITE S                                                                              ' || CHR(10);
    V_MDQRY := V_MDQRY || '     ON S.DIVISION_ID = M.DIVISION_ID AND S.SCM_SITE_ID = M.FROM_SITE AND S.VALID_YN = ''Y''                    ' || CHR(10);
    V_MDQRY := V_MDQRY || ' WHERE 1 = 1                                                                                                    ' || CHR(10);

    IF P_DIVISION_ID NOT IN ('EE', 'EE_UC') THEN
        V_MDQRY := V_MDQRY || ' AND M.DIVISION_ID = ''' || P_DIVISION_ID || '''                                                            ' || CHR(10);
    ELSE
        V_MDQRY := V_MDQRY || ' AND M.DIVISION_ID = ''' || P_ORIGION_DIVISION_ID || '''                                                    ' || CHR(10);
    END IF;

    --AND m.from_site = @p_from_site
    V_MDQRY := V_MDQRY || ' AND M.BOD_TYPE = ''PLANT''                                                                                     ' || CHR(10);
    V_MDQRY := V_MDQRY || ' AND S.OPERATION_GROUP = ''' || P_OPER_GRP || '''                                                               ' || CHR(10);
    V_MDQRY := V_MDQRY || ' AND M.TO_SITE = ''' || P_TO_SITE || '''                                                                        ' || CHR(10);
    V_MDQRY := V_MDQRY || ' ORDER BY FROM_SITE ASC, TO_SITE ASC                                                                            ' || CHR(10);

    IF DEBUG_MODE = 'T' THEN
        V_POS := 1;
        V_LEN := LENGTH(V_MDQRY);
        WHILE V_POS <= V_LEN LOOP
            DBMS_OUTPUT.PUT_LINE(SUBSTR(V_MDQRY, V_POS, 4000));
            V_POS := V_POS + 4000;
        END LOOP;
    END IF;

    OPEN O_RC1 FOR V_MDQRY;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID'         VALUE P_DIVISION_ID,
            'P_BOD_ID'              VALUE P_BOD_ID,
            'P_FROM_SITE'           VALUE P_FROM_SITE,
            'P_TO_SITE'             VALUE P_TO_SITE,
            'P_PLAN_START_YYYYMMDD' VALUE TO_CHAR(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'),
            'P_OPER_GRP'            VALUE P_OPER_GRP,
            'P_ITEM_ID'             VALUE P_ITEM_ID,
            'P_ORIGION_DIVISION_ID' VALUE P_ORIGION_DIVISION_ID,
            'DEBUG_MODE'            VALUE DEBUG_MODE
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_BOD_SEMI_POPUP;


/* ============================================================
   3. P_SCM0002_GET_CAPACITY_ALLOCATION_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_CAPACITY_ALLOCATION_POPUP
(
    --chaan   @p_division_id    NVARCHAR(2),
    P_DIVISION_ID   IN VARCHAR2,  --chaan
    P_ACTION_FLAG   IN VARCHAR2 DEFAULT '',
    P_ITEM_ID       IN VARCHAR2 DEFAULT '',
    O_RC1           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : P_SCM0002_GET_CAPACITY_ALLOCATION_POPUP
 * Description  : Capacity Allocation 입력/삭제 대상목록 조회
 * Program History

 *===================================================================================================
 *   Date       In Charge   Description
 *===================================================================================================
 * 2018/08/24   YHW             Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018/09/05   YHW             조회조건 수정
 * 2022/04/29   chaan       81_UC, EE_UC 추가로 DIVSION 크기 확장
 * 2026.03.24   kimcd           [PJ20264226] NextSCM Pilot 설계 및 개발
 */
    V_PROGRAM_NAME  VARCHAR2(200 CHAR);

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    IF P_ACTION_FLAG = 'I' THEN

        OPEN O_RC1 FOR
            SELECT DISTINCT B.DIVISION_ID, B.ITEM_ID, D.NICK_NAME
            FROM   SCM_MGR.SCM_MST_SITE_ITEM      B
            JOIN   SCM_MGR.SCM_MST_SITE            C ON B.DIVISION_ID = C.DIVISION_ID AND B.SCM_SITE_ID = C.SCM_SITE_ID
            JOIN   SCM_MGR.SCM_MST_ITEM_SN         D ON B.DIVISION_ID = D.DIVISION_ID AND B.ITEM_ID     = D.ITEM_ID
            WHERE  1 = 1
            AND    B.DIVISION_ID = P_DIVISION_ID
            AND    (
                       (P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                       OR B.ITEM_ID  LIKE '%' || P_ITEM_ID || '%'
                       OR D.NICK_NAME LIKE P_ITEM_ID || '%'
                   )
            AND    C.SITE_TYPE            = 'SALES'
            AND    D.SCP_OPERATION_GROUP  = 'A'
            AND    NOT EXISTS (
                       SELECT 'X' FROM SCM_MGR.DM_MST_CAPACITY_ALLOCATION A
                       WHERE  B.DIVISION_ID = A.DIVISION_ID
                       AND    B.ITEM_ID     = A.ITEM_ID
                   )
            AND    B.VALID_YN = 'Y'
            AND    C.VALID_YN = 'Y'
            ORDER BY ITEM_ID;

    ELSIF P_ACTION_FLAG = 'D' THEN

        OPEN O_RC1 FOR
            SELECT DISTINCT DIVISION_ID
                          , ITEM_ID
                          , (SELECT CASE WHEN X.NICK_NAME IS NULL THEN '-'
                                         WHEN X.NICK_NAME = ''   THEN '-'
                                         ELSE X.NICK_NAME
                                    END
                             FROM   SCM_MGR.SCM_MST_ITEM_SN X
                             WHERE  X.ITEM_ID = A.ITEM_ID
                             AND    ROWNUM    = 1
                            ) AS NICK_NAME
            FROM   SCM_MGR.DM_MST_CAPACITY_ALLOCATION A
            WHERE  A.DIVISION_ID = P_DIVISION_ID
            AND    (
                       (P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                       OR A.ITEM_ID LIKE '%' || P_ITEM_ID || '%'
                       OR (SELECT CASE WHEN X.NICK_NAME IS NULL THEN '-'
                                       WHEN X.NICK_NAME = ''   THEN '-'
                                       ELSE X.NICK_NAME
                                  END
                           FROM   SCM_MGR.SCM_MST_ITEM_SN X
                           WHERE  X.ITEM_ID = A.ITEM_ID
                           AND    ROWNUM    = 1
                          ) LIKE P_ITEM_ID || '%'
                   );

    ELSE
        OPEN O_RC1 FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1 = 0;
    END IF;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DIVISION_ID' VALUE P_DIVISION_ID,
            'P_ACTION_FLAG' VALUE P_ACTION_FLAG,
            'P_ITEM_ID'     VALUE P_ITEM_ID
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_CAPACITY_ALLOCATION_POPUP;



/* ============================================================
   4. P_SCM0002_GET_CITY_BY_COUNTY_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_CITY_BY_COUNTY_POPUP
(
    P_COUNTRY       IN VARCHAR2,
    P_CITY          IN VARCHAR2,
    O_RC1           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
)
AS
/****************************************************************************************************/
/* Program ID  : SCM0002_GET_CITY_BY_COUNTY_POPUP                                                   */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2017/12/06  SongDH       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트      */
/* 2026.03.24  kimcd        [PJ20264226] NextSCM Pilot 설계 및 개발                                   */
/*                                                                                                  */
/****************************************************************************************************/

/*****************************************************************************************************
 ※ 작성 Rule
   1. 대문자, 소문자
      - 테이블, 컬럼, 변수는 소문자로 작성하고, 그 이외는 대문자로 통일
   2. Naming Rule - Prefix
      - 파라메터 : @p_
      - 변수 : 데이타 타입에 따라 @v_(문자), @n_(숫자), @d_(날짜)
   3. 들여쓰기 : 2 space
   4. 기타
      - SQL 수직 배치 : SQL 구문의 세로줄(왼쪽)로 맞춤, 컬럼이나 변수도 KEYWORD 이후 왼쪽 정렬
      - 콤마로 분리된 ID 가 여러 줄에 걸쳐 나올 때, 콤마를 라인의 처음에 위치
******************************************************************************************************/
    V_PROGRAM_NAME  VARCHAR2(200 CHAR);

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    OPEN O_RC1 FOR
        SELECT A.COUNTRY
             , A.COUNTRY_NAME
             , B.CITY
             , B.CITY_NAME
             , B.STATE_NM
        FROM   SCM_MGR.SCM_MST_COUNTRY A
             , SCM_MGR.SCM_MST_CITY    B
        WHERE  A.COUNTRY  = B.COUNTRY
        AND    A.VALID_YN = 'Y'
        AND    B.VALID_YN = 'Y'
        AND    (   A.COUNTRY      LIKE '%' || P_COUNTRY || '%'
                OR A.COUNTRY_NAME LIKE '%' || P_COUNTRY || '%'
               )
        AND    (   B.CITY      LIKE '%' || P_CITY || '%'
                OR B.CITY_NAME LIKE '%' || P_CITY || '%'
               );

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_COUNTRY' VALUE P_COUNTRY,
            'P_CITY'    VALUE P_CITY
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;
        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );

END P_SCM0002_GET_CITY_BY_COUNTY_POPUP;

/* ============================================================
   5. P_SCM0002_GET_CUSTOMER_BY_DIVISION_POPUP
   ============================================================ */
PROCEDURE P_SCM0002_GET_CUSTOMER_BY_DIVISION_POPUP
(
    P_DIVISION_ID   IN VARCHAR2,
    P_SOLDTO_CODE   IN VARCHAR2,
    P_SHIPTO_CODE   IN VARCHAR2,
    O_RC1           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : SCM0002_GET_CUSTOMER_BY_DIVISION_POPUP
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2017/12/04   songdh         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 20180604 주석제거 modified by khsong
 * 2026.03.24   kimcd          [PJ20264226] NextSCM Pilot 설계 및 개발

 */
    V_PROGRAM_NAME  VARCHAR2(200 CHAR);

    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100  CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100  CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER        := 0;
    D_EVENT_DATE    DATE               := SYSDATE;

BEGIN
    -- 프로그램명 설정 (패키지 바디 이관 시 패키지명.프로시저명 자동 기록)
    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    ELSE
        V_PROGRAM_NAME := $$PLSQL_UNIT;
    END IF;

    OPEN O_RC1 FOR
        SELECT C.DIVISION_ID
             , D.DIVISION_NAME
             , C.SOLDTO_CODE
             , C.SOLDTO_DESCRIPTION
             , C.SHIPTO_CODE
             , C.SHIPTO_DESCRIPTION
             , C.SHIPTO_REGION_NAME
             , C.SHIPTO_CITY_NAME
        FROM   SCM_MGR.SCM_MST_CUSTOMER  C
             , SCM_MGR.SCM_MST_DIVISION  D
        WHERE  C.DIVISION_ID = D.DIVISION_ID
        AND    C.VALID_YN    = 'Y'
        -- CASE WHEN ALL → UNION ALL 분해 (Predicate Pushdown 유도)
        AND    (
                   P_DIVISION_ID = 'ALL'
                   OR C.DIVISION_ID IN (
                          SELECT TRIM(REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL))
                          FROM   DUAL
                          CONNECT BY REGEXP_SUBSTR(P_DIVISION_ID, '[^,]+', 1, LEVEL) IS NOT NULL
                      )
               )
        AND    (   C.SHIPTO_CODE        LIKE '%' || P_SHIPTO_CODE || '%'
                OR C.SHIPTO_DESCRIPTION LIKE '%' || P_SHIPTO_CODE || '%'
               )
        AND    (   C.SOLDTO_CODE        LIKE '%' || P_SOLDTO_CODE || '%'
                OR C.SOLDTO_DESCRIPTION LIKE '%' || P_SOLDTO_CODE || '%'
               )
        AND    NOT EXISTS (
                   SELECT 1
                   FROM   SCM_MGR.SCM_MST_SITE_CUSTOMER SC
                        , SCM_MGR.SCM_MST_SITE           B  -- added by ytchoi 20180730 plant와 구분 하기 위해서
                   WHERE  1 = 1
                   AND    SC.SOLDTO_CODE  = C.SOLDTO_CODE  -- 20180604 주석제거 modified by khsong
                   AND    SC.SHIPTO_CODE  = C.SHIPTO_CODE
                   AND    SC.DIVISION_ID  = C.DIVISION_ID
                   AND    SC.VALID_YN     = 'Y'
                   -- added by ytchoi 20180730 plant와 구분 하기 위해서
                   AND    SC.DIVISION_ID  = B.DIVISION_ID
                   AND    SC.SCM_SITE_ID  = B.SCM_SITE_ID
                   AND    B.SITE_TYPE     = 'SALES'
               );

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
