             , NVL(NVL(JT.BOD1, JT.BOD2), JT.BOD3)   /* AJS 20261007 화면검증 */
/* , NVL(JT.MSR1, JT.MSR2) */
             , NVL(NVL(JT.MSR1, JT.MSR2), JT.MSR3)   /* AJS 20261007 화면검증 */
/* , NVL(JT.YMD1, JT.YMD2) */
             , NVL(NVL(JT.YMD1, JT.YMD2), JT.YMD3)   /* AJS 20261007 화면검증 */
