        INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
             (
               HISTORY_SEQ
              ,FIX_ID
              ,DIVISION_ID
              ,OPERATION_GROUP
              ,SCM_SITE_ID
              ,ITEM_ID
              ,LINE_ID
              ,OPERATION_ID
              ,YYYYMMDD
              ,QTY
              ,FIX_REASON
              ,ORIGIN_DIVISION_ID
              ,ELECTRODE_TYPE
