  -- 2026.09.18 저장 순서를 AS-IS 와 같게 다시 작성 · 이력 ATTRIBUTE1 = 처리구분 (START)
  --   AS-IS 처리 순서 : 삭제(원래 키) → 수정(원래 키) → 신규(새 키가 없을 때만) → 전 행 이력(전송값)
  PROCEDURE P_SCP0020_SAVE_TACT_TIME_EXCEPT_OSP(P_DATA IN CLOB, P_USER_ID IN VARCHAR2, O_RESULT_CURSOR OUT SYS_REFCURSOR) IS
    V_ERR_MSG VARCHAR2(4000); V_ROW_CNT NUMBER := 0; V_NOW DATE := SYSDATE;
    TYPE T_ROW IS RECORD (
      CRUD_TYPE                VARCHAR2(10),
      DIVISION_ID              VARCHAR2(60),
      PLANT_SITE_ID            VARCHAR2(60),
      ITEM_ID                  VARCHAR2(100),
      OPERATION_ID             VARCHAR2(60),
      LINE_ID                  VARCHAR2(100),
      TACT_TIME_START_DATE     VARCHAR2(8),
      TACT_TIME_END_DATE       VARCHAR2(8),
      TACT_TIME                VARCHAR2(50),
      YIELD                    VARCHAR2(50),
      DAILY_CAPACITY           VARCHAR2(50),
      EXCEPT_COMMENT           VARCHAR2(400),
      USE_YN                   VARCHAR2(10),
      ORG_DIVISION_ID          VARCHAR2(60),
      ORG_PLANT_SITE_ID        VARCHAR2(60),
      ORG_ITEM_ID              VARCHAR2(100),
      ORG_OPERATION_ID         VARCHAR2(60),
      ORG_LINE_ID              VARCHAR2(100),
      ORG_TACT_TIME_START_DATE VARCHAR2(8),
      ORG_TACT_TIME_END_DATE   VARCHAR2(8));
    TYPE T_ROWS IS TABLE OF T_ROW;
    V_ROWS T_ROWS;
  BEGIN
    SELECT TRIM(JT.CRUD_TYPE)
         , TRIM(JT.DIVISION_ID)
         , TRIM(JT.PLANT_SITE_ID)
         , TRIM(JT.ITEM_ID)
         , TRIM(JT.OPERATION_ID)
         , TRIM(JT.LINE_ID)
         , TRIM(JT.TACT_TIME_START_DATE)
         , TRIM(JT.TACT_TIME_END_DATE)
         , JT.TACT_TIME
         , JT.YIELD
         , JT.DAILY_CAPACITY
         , JT.EXCEPT_COMMENT
         , JT.USE_YN
         , TRIM(JT.ORG_DIVISION_ID)
         , TRIM(JT.ORG_PLANT_SITE_ID)
         , TRIM(JT.ORG_ITEM_ID)
         , TRIM(JT.ORG_OPERATION_ID)
         , TRIM(JT.ORG_LINE_ID)
         , TRIM(JT.ORG_TACT_TIME_START_DATE)
         , TRIM(JT.ORG_TACT_TIME_END_DATE)
      BULK COLLECT INTO V_ROWS
      FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS(
             CRUD_TYPE                VARCHAR2(10)  PATH '$."CRUD_TYPE"'                NULL ON EMPTY NULL ON ERROR,
             DIVISION_ID              VARCHAR2(60)  PATH '$."DIVISION_ID"'              NULL ON EMPTY NULL ON ERROR,
             PLANT_SITE_ID            VARCHAR2(60)  PATH '$."PLANT_SITE_ID"'            NULL ON EMPTY NULL ON ERROR,
             ITEM_ID                  VARCHAR2(100) PATH '$."ITEM_ID"'                  NULL ON EMPTY NULL ON ERROR,
             OPERATION_ID             VARCHAR2(60)  PATH '$."OPERATION_ID"'             NULL ON EMPTY NULL ON ERROR,
             LINE_ID                  VARCHAR2(100) PATH '$."LINE_ID"'                  NULL ON EMPTY NULL ON ERROR,
             TACT_TIME_START_DATE     VARCHAR2(8)   PATH '$."TACT_TIME_START_DATE"'     NULL ON EMPTY NULL ON ERROR,
             TACT_TIME_END_DATE       VARCHAR2(8)   PATH '$."TACT_TIME_END_DATE"'       NULL ON EMPTY NULL ON ERROR,
             TACT_TIME                VARCHAR2(50)  PATH '$."TACT_TIME"'                NULL ON EMPTY NULL ON ERROR,
             YIELD                    VARCHAR2(50)  PATH '$."YIELD"'                    NULL ON EMPTY NULL ON ERROR,
             DAILY_CAPACITY           VARCHAR2(50)  PATH '$."DAILY_CAPACITY"'           NULL ON EMPTY NULL ON ERROR,
             EXCEPT_COMMENT           VARCHAR2(400) PATH '$."EXCEPT_COMMENT"'           NULL ON EMPTY NULL ON ERROR,
             USE_YN                   VARCHAR2(10)  PATH '$."USE_YN"'                   NULL ON EMPTY NULL ON ERROR,
             ORG_DIVISION_ID          VARCHAR2(60)  PATH '$."ORG_DIVISION_ID"'          NULL ON EMPTY NULL ON ERROR,
             ORG_PLANT_SITE_ID        VARCHAR2(60)  PATH '$."ORG_PLANT_SITE_ID"'        NULL ON EMPTY NULL ON ERROR,
             ORG_ITEM_ID              VARCHAR2(100) PATH '$."ORG_ITEM_ID"'              NULL ON EMPTY NULL ON ERROR,
             ORG_OPERATION_ID         VARCHAR2(60)  PATH '$."ORG_OPERATION_ID"'         NULL ON EMPTY NULL ON ERROR,
             ORG_LINE_ID              VARCHAR2(100) PATH '$."ORG_LINE_ID"'              NULL ON EMPTY NULL ON ERROR,
             ORG_TACT_TIME_START_DATE VARCHAR2(8)   PATH '$."ORG_TACT_TIME_START_DATE"' NULL ON EMPTY NULL ON ERROR,
             ORG_TACT_TIME_END_DATE   VARCHAR2(8)   PATH '$."ORG_TACT_TIME_END_DATE"'   NULL ON EMPTY NULL ON ERROR)) JT;

    /* 삭제 (원래 키) */
    FOR I IN 1 .. V_ROWS.COUNT LOOP
      IF V_ROWS(I).CRUD_TYPE = 'D' THEN
        DELETE FROM SCP_MST_TACT_TIME_EXCEPT_OSP
         WHERE DIVISION_ID          = V_ROWS(I).ORG_DIVISION_ID
           AND PLANT_SITE_ID        = V_ROWS(I).ORG_PLANT_SITE_ID
           AND ITEM_ID              = V_ROWS(I).ORG_ITEM_ID
           AND OPERATION_ID         = V_ROWS(I).ORG_OPERATION_ID
           AND LINE_ID              = V_ROWS(I).ORG_LINE_ID
           AND TACT_TIME_START_DATE = V_ROWS(I).ORG_TACT_TIME_START_DATE
           AND TACT_TIME_END_DATE   = V_ROWS(I).ORG_TACT_TIME_END_DATE;
      END IF;
    END LOOP;

    /* 수정 (원래 키) */
    FOR I IN 1 .. V_ROWS.COUNT LOOP
      IF V_ROWS(I).CRUD_TYPE IN ('I', 'M') THEN
        UPDATE SCP_MST_TACT_TIME_EXCEPT_OSP
           SET TACT_TIME_START_DATE = V_ROWS(I).TACT_TIME_START_DATE
             , TACT_TIME_END_DATE   = V_ROWS(I).TACT_TIME_END_DATE
             , TACT_TIME            = TO_NUMBER(V_ROWS(I).TACT_TIME)
             , YIELD                = TO_NUMBER(V_ROWS(I).YIELD) / 100
             , DAILY_CAPACITY       = TO_NUMBER(V_ROWS(I).DAILY_CAPACITY)
             , EXCEPT_COMMENT       = V_ROWS(I).EXCEPT_COMMENT
             , USE_YN               = V_ROWS(I).USE_YN
             , LAST_UPDATED_BY      = P_USER_ID
             , LAST_UPDATE_DATE     = V_NOW
         WHERE DIVISION_ID          = V_ROWS(I).ORG_DIVISION_ID
           AND PLANT_SITE_ID        = V_ROWS(I).ORG_PLANT_SITE_ID
           AND ITEM_ID              = V_ROWS(I).ORG_ITEM_ID
           AND OPERATION_ID         = V_ROWS(I).ORG_OPERATION_ID
           AND LINE_ID              = V_ROWS(I).ORG_LINE_ID
           AND TACT_TIME_START_DATE = V_ROWS(I).ORG_TACT_TIME_START_DATE
           AND TACT_TIME_END_DATE   = V_ROWS(I).ORG_TACT_TIME_END_DATE;
      END IF;
    END LOOP;

    /* 신규 (새 키가 없을 때만) */
    FOR I IN 1 .. V_ROWS.COUNT LOOP
      IF V_ROWS(I).CRUD_TYPE IN ('I', 'M') THEN
        INSERT INTO SCP_MST_TACT_TIME_EXCEPT_OSP
             ( DIVISION_ID
             , PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , TACT_TIME_START_DATE
             , TACT_TIME_END_DATE
             , TACT_TIME
             , YIELD
             , DAILY_CAPACITY
             , EXCEPT_COMMENT
             , USE_YN
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE )
        SELECT V_ROWS(I).DIVISION_ID
             , V_ROWS(I).PLANT_SITE_ID
             , V_ROWS(I).ITEM_ID
             , V_ROWS(I).OPERATION_ID
             , V_ROWS(I).LINE_ID
             , V_ROWS(I).TACT_TIME_START_DATE
             , V_ROWS(I).TACT_TIME_END_DATE
             , TO_NUMBER(V_ROWS(I).TACT_TIME)
             , TO_NUMBER(V_ROWS(I).YIELD) / 100
             , TO_NUMBER(V_ROWS(I).DAILY_CAPACITY)
             , V_ROWS(I).EXCEPT_COMMENT
             , V_ROWS(I).USE_YN
             , P_USER_ID
             , V_NOW
             , P_USER_ID
             , V_NOW
          FROM DUAL
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_MST_TACT_TIME_EXCEPT_OSP A
                            WHERE A.DIVISION_ID          = V_ROWS(I).DIVISION_ID
                              AND A.PLANT_SITE_ID        = V_ROWS(I).PLANT_SITE_ID
                              AND A.ITEM_ID              = V_ROWS(I).ITEM_ID
                              AND A.OPERATION_ID         = V_ROWS(I).OPERATION_ID
                              AND A.LINE_ID              = V_ROWS(I).LINE_ID
                              AND A.TACT_TIME_START_DATE = V_ROWS(I).TACT_TIME_START_DATE
                              AND A.TACT_TIME_END_DATE   = V_ROWS(I).TACT_TIME_END_DATE);
      END IF;
    END LOOP;

    /* 전 행 이력 (전송값) */
    FOR I IN 1 .. V_ROWS.COUNT LOOP
      INSERT INTO SCP_MST_TACT_TIME_EXCEPT_OSP_H
           ( HISTORY_SEQ
           , DIVISION_ID
           , PLANT_SITE_ID
           , ITEM_ID
           , OPERATION_ID
           , LINE_ID
           , TACT_TIME_START_DATE
           , TACT_TIME_END_DATE
           , TACT_TIME
           , YIELD
           , DAILY_CAPACITY
           , EXCEPT_COMMENT
           , USE_YN
           , CREATED_BY
           , CREATION_DATE
           , LAST_UPDATED_BY
           , LAST_UPDATE_DATE
           , HISTORY_CREATION_DATE
           , ATTRIBUTE1 )
      VALUES
           ( SEQ1_SCP_MST_TACT_TIME_EXCEPT_OSP_H.NEXTVAL
           , V_ROWS(I).DIVISION_ID
           , V_ROWS(I).PLANT_SITE_ID
           , V_ROWS(I).ITEM_ID
           , V_ROWS(I).OPERATION_ID
           , V_ROWS(I).LINE_ID
           , V_ROWS(I).TACT_TIME_START_DATE
           , V_ROWS(I).TACT_TIME_END_DATE
           , TO_NUMBER(V_ROWS(I).TACT_TIME)
           , TO_NUMBER(V_ROWS(I).YIELD)
           , TO_NUMBER(V_ROWS(I).DAILY_CAPACITY)
           , V_ROWS(I).EXCEPT_COMMENT
           , V_ROWS(I).USE_YN
           , P_USER_ID
           , V_NOW
           , P_USER_ID
           , SYSDATE
           , SYSDATE
           , V_ROWS(I).CRUD_TYPE );
    END LOOP;

    V_ROW_CNT := V_ROWS.COUNT;
    COMMIT;
    OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(V_ROW_CNT) AS EVENT FROM DUAL;
  EXCEPTION
    WHEN OTHERS THEN ROLLBACK; V_ERR_MSG := SQLERRM; OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;
  END P_SCP0020_SAVE_TACT_TIME_EXCEPT_OSP;
  -- 2026.09.18 저장 순서를 AS-IS 와 같게 다시 작성 (END)

END PKG_SCP0020;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0020
-- ##### END PACKAGE BODY PKG_SCP0020

-- ##### START PACKAGE BODY PKG_SCP0025
CREATE OR REPLACE PACKAGE BODY PKG_SCP0025
IS
    /*
     * Program ID   : PKG_SCP0025
     * Description  : SCP0025 Shipment Plan Fix 화면 - Fix 계획 조회 / Unfix(삭제) 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.17   AJS            AS-IS(LGCE_SCMDEV) 프로시저 2 건 패키지 전환
     * 2026.10.08   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치 · 대소문자 무시 · ALL 은 조건 없음
     */

    /* ==============================================================================================
       SCP0025_GET_SHIPMENT_PLAN_FIX
       ============================================================================================== */
    PROCEDURE P_SCP0025_GET_SHIP_PLAN_FIX
    (
        P_DIVISION_ID       IN  VARCHAR2,
        P_BIZ_TYPE          IN  VARCHAR2,
        P_ITEM_ID           IN  VARCHAR2,
        P_FROM_YYYYMMDD     IN  VARCHAR2,
        P_TO_YYYYMMDD       IN  VARCHAR2,
        P_ELECTYPE          IN  VARCHAR2,
        P_PROGRAM_ID        IN  VARCHAR2 DEFAULT 'SCP0025',
        P_SHEET_NAME        IN  VARCHAR2 DEFAULT 'Shipment Plan Fix',
        P_USER_ID           IN  VARCHAR2 DEFAULT NULL,
        P_DEBUG_MODE        IN  VARCHAR2 DEFAULT 'F',
        O_RC1               OUT SYS_REFCURSOR,
        O_RC2               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SCP0025_GET_SHIPMENT_PLAN_FIX
     * Description  : Production Plan Line 별 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge			Description
     *===================================================================================================
     * 2018/05/28   byunghunjung		Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
     * 2018/05/31	KYH					년조회시 년도가 다른 같은 월 조회시 sum이 표시되는 문제 ex) 2018.0528 ~ 2019.0527 조회시 2019.5월 (마지막 주)에 2018.5월 sum값 표시2018.5월의 sum이 표시된다
     * 2018/07/02	KYH					신규 컬럼 추가 조회. (ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, ELECTRODE_TYPE)
     * 2019/06/07	HWYOON				[CSR ID:4010290] SCP UI 생산/출하 계획 저장속도 개선
     * 2019/07/15	HWYOON				[CSR ID:4071705] Production Plan Fix에서 Unfix 기능 추가 - BOD 조회추가
     * 2021/07/07   khj79			    PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD 2단계 개발 : FROM,TO 추가 , scp_mst_bod_v=> scp_mst_bod_n_v
     * 2022/04/29   chaan				81_UC, EE_UC 추가로 DIVSION 크기 확장
     * 2023/04/10   LWY					PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 이행 - DIVISION_ID 공통화 작업(div_commonization)
     * 2026.09.17   AJS                 [MSSQL -> Oracle 전환]
     *                                  - 임시테이블(#TblDynamicPivot_SCP0025) 적재 대신 피벗 문장 안의 인라인 뷰로 조회
     *                                    (반환 커서가 임시테이블을 읽으면 커밋 시 비는 문제 · 세션 재사용 시 누적 문제 회피)
     *                                  - 임시테이블 수량 칸 NUMERIC(20,0) 반올림을 ROUND(QTY, 0) 으로 재현
     *                                  - 업무유형명 룩업 유형을 대문자 'BIZ_TYPE' 로 호출 (Oracle 은 대소문자 구분)
     *                                  - 별칭 없음 판정 ('' 비교) 을 NVL 로 재현
     *                                  - 조회조건 대소문자 무시 재현 (사업부 · 업무유형 · 아이템 · 전극유형 파라미터 UPPER)
     *                                  - 정렬 : 옛 정렬규칙(대소문자 무시 · 하이픈 무시 · 밑줄 우선) 재현
     *
     ex) EXEC SCP0025_GET_SHIPMENT_PLAN_FIX @p_division_id='81', @p_biz_type='P', @p_item_id='', @p_from_yyyymmdd='20180702', @p_to_yyyymmdd='20190630', @p_electype='', @p_program_id='SCP0025', @p_sheet_name='Shipment Plan Fix', @p_user_id='kaiser99', @debug_mode='T'
     */
        V_DIVISION_ID   VARCHAR2(30 CHAR)  := UPPER(P_DIVISION_ID);
        V_BIZ_TYPE      VARCHAR2(30 CHAR)  := UPPER(P_BIZ_TYPE);
--      V_ITEM_ID       VARCHAR2(32767)    := UPPER(P_ITEM_ID);   --  2026.10.08 AJS
        V_ITEM_ID       VARCHAR2(32767)    := CASE WHEN UPPER(TRIM(P_ITEM_ID)) = 'ALL' THEN NULL ELSE UPPER(TRIM(P_ITEM_ID)) END;   /* 조회조건 ALL 은 조건 없음 */   --  2026.10.08 AJS
        V_ELECTYPE      VARCHAR2(300 CHAR) := UPPER(P_ELECTYPE);
        V_EE_CNT        PLS_INTEGER        := 0;
        V_MQUERY        CLOB;
        V_MEXEC         CLOB;
        V_INNER         VARCHAR2(32767);
        V_POS           PLS_INTEGER;
        V_LEN           PLS_INTEGER;
        V_ERR           VARCHAR2(4000 CHAR);

        /* 사업부별 조회 원본 (Ship Plan · Fix Reason 두 갈래)
           P_EE = TRUE  : EE 계열 사업부 - BOD 조인에 사업부 조건 없음 · 전극유형 조건 있음
           P_EE = FALSE : 그 외 사업부   - BOD 조인에 사업부 조건 있음 · 전극유형 조건 주석 처리(AS-IS) */
        FUNCTION F_INNER_SQL(P_EE IN BOOLEAN) RETURN VARCHAR2
        IS
            V_TXT   VARCHAR2(32767);
        BEGIN
            V_TXT :=           '                SELECT A.DIVISION_ID'
                || CHR(10) ||  '                     , A.BIZ_TYPE'
                || CHR(10) ||  '                     , A.ITEM_ID'
                || CHR(10) ||  '                     , NVL(A.ELECTRODE_TYPE, ''-'') AS ELECTRODE_TYPE'
                || CHR(10) ||  '                     , NVL(A.ORIGIN_TO_DIVISION_ID, ''-'') AS ORIGIN_TO_DIVISION_ID'
                || CHR(10) ||  '                     , A.TO_SITE'
                || CHR(10) ||  '                     , NVL(A.ORIGIN_FROM_DIVISION_ID, ''-'') AS ORIGIN_FROM_DIVISION_ID'
                || CHR(10) ||  '                     , A.FROM_SITE'
                || CHR(10) ||  '                     , A.INCOTERMS'
                || CHR(10) ||  '                     , A.PROJECT_CODE'
                || CHR(10) ||  '                     , B.TRANSPORT_MODE'
                || CHR(10) ||  '                     , B.LT_TOTAL'
                || CHR(10) ||  '                     , ''Ship Plan'' AS MEASURE'
                || CHR(10) ||  '                     , A.YYYYMMDD'
                || CHR(10) ||  '                     , ROUND(A.QTY, 0) AS QTY /* AS-IS 임시테이블 NUMERIC(20,0) 적재 시 반올림 */'
                || CHR(10) ||  '                     , A.BOD_ID'
                || CHR(10) ||  '                     , B.FROM_YYYYMMDD AS BOD_FROM_YYYYMMDD'
                || CHR(10) ||  '                     , B.TO_YYYYMMDD AS BOD_TO_YYYYMMDD'
                || CHR(10) ||  '                  FROM SCP_ANL_SHIPMENT_PLAN_FIX A'
                || CHR(10) ||  '                     , SCP_MST_BOD_N_V B'
                || CHR(10) ||  CASE WHEN P_EE
                                    THEN '                 WHERE A.BOD_ID = B.BOD_ID'
                                    ELSE '                 WHERE A.DIVISION_ID = B.DIVISION_ID'
                                         || CHR(10) || '                   AND A.BOD_ID = B.BOD_ID'
                               END
--              || CHR(10) ||  '                   AND (:ITEM_ID1 IS NULL OR A.ITEM_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(STRING_SPLIT(:ITEM_ID2, '','')) SA))'   --  2026.10.08 AJS
                || CHR(10) ||  '                   AND (:ITEM_ID1 IS NULL OR EXISTS (SELECT 1 FROM TABLE(STRING_SPLIT(:ITEM_ID2, '','')) SA WHERE TRIM(SA.COLUMN_VALUE) IS NOT NULL AND (UPPER(A.ITEM_ID) LIKE ''%'' || UPPER(TRIM(SA.COLUMN_VALUE)) || ''%'' OR UPPER(FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)) LIKE ''%'' || UPPER(TRIM(SA.COLUMN_VALUE)) || ''%'')))'   --  2026.10.08 AJS
                || CASE WHEN P_EE
                        THEN CHR(10) || '                   AND (:ELECTYPE1 IS NULL OR A.ELECTRODE_TYPE IN (SELECT SB.COLUMN_VALUE FROM TABLE(STRING_SPLIT(:ELECTYPE2, '','')) SB))'
                   END
                || CHR(10) ||  '                   AND A.YYYYMMDD >= :FROM_YYYYMMDD'
                || CHR(10) ||  '                   AND A.YYYYMMDD <= :TO_YYYYMMDD'
                || CHR(10) ||  '                   AND A.DIVISION_ID = :DIVISION_ID'
                || CHR(10) ||  '                   AND A.BIZ_TYPE = :BIZ_TYPE'
                || CHR(10) ||  '                 UNION ALL'
                || CHR(10) ||  '                SELECT C.DIVISION_ID'
                || CHR(10) ||  '                     , C.BIZ_TYPE'
                || CHR(10) ||  '                     , C.ITEM_ID'
                || CHR(10) ||  '                     , NVL(C.ELECTRODE_TYPE, ''-'') AS ELECTRODE_TYPE'
                || CHR(10) ||  '                     , NVL(C.ORIGIN_TO_DIVISION_ID, ''-'') AS ORIGIN_TO_DIVISION_ID'
                || CHR(10) ||  '                     , C.TO_SITE'
                || CHR(10) ||  '                     , NVL(C.ORIGIN_FROM_DIVISION_ID, ''-'') AS ORIGIN_FROM_DIVISION_ID'
                || CHR(10) ||  '                     , C.FROM_SITE'
                || CHR(10) ||  '                     , C.INCOTERMS'
                || CHR(10) ||  '                     , C.PROJECT_CODE'
                || CHR(10) ||  '                     , D.TRANSPORT_MODE'
                || CHR(10) ||  '                     , D.LT_TOTAL'
                || CHR(10) ||  '                     , ''Fix Reason'' AS MEASURE'
                || CHR(10) ||  '                     , C.YYYYMMDD'
                || CHR(10) ||  '                     , NULL AS QTY'
                || CHR(10) ||  '                     , C.BOD_ID'
                || CHR(10) ||  '                     , D.FROM_YYYYMMDD AS BOD_FROM_YYYYMMDD'
                || CHR(10) ||  '                     , D.TO_YYYYMMDD AS BOD_TO_YYYYMMDD'
                || CHR(10) ||  '                  FROM SCP_ANL_SHIPMENT_PLAN_FIX C'
                || CHR(10) ||  '                     , SCP_MST_BOD_N_V D'
                || CHR(10) ||  CASE WHEN P_EE
                                    THEN '                 WHERE C.BOD_ID = D.BOD_ID'
                                    ELSE '                 WHERE C.DIVISION_ID = D.DIVISION_ID'
                                         || CHR(10) || '                   AND C.BOD_ID = D.BOD_ID'
                               END
--              || CHR(10) ||  '                   AND (:ITEM_ID3 IS NULL OR C.ITEM_ID IN (SELECT XA.COLUMN_VALUE FROM TABLE(STRING_SPLIT(:ITEM_ID4, '','')) XA))'   --  2026.10.08 AJS
                || CHR(10) ||  '                   AND (:ITEM_ID3 IS NULL OR EXISTS (SELECT 1 FROM TABLE(STRING_SPLIT(:ITEM_ID4, '','')) XA WHERE TRIM(XA.COLUMN_VALUE) IS NOT NULL AND (UPPER(C.ITEM_ID) LIKE ''%'' || UPPER(TRIM(XA.COLUMN_VALUE)) || ''%'' OR UPPER(FN_GET_ITEM_NICKNAME(C.DIVISION_ID, C.ITEM_ID)) LIKE ''%'' || UPPER(TRIM(XA.COLUMN_VALUE)) || ''%'')))'   --  2026.10.08 AJS
                || CASE WHEN P_EE
                        THEN CHR(10) || '                   AND (:ELECTYPE3 IS NULL OR C.ELECTRODE_TYPE IN (SELECT XB.COLUMN_VALUE FROM TABLE(STRING_SPLIT(:ELECTYPE4, '','')) XB))'
                   END
                || CHR(10) ||  '                   AND C.YYYYMMDD >= :FROM_YYYYMMDD2'
                || CHR(10) ||  '                   AND C.YYYYMMDD <= :TO_YYYYMMDD2'
                || CHR(10) ||  '                   AND C.DIVISION_ID = :DIVISION_ID2'
                || CHR(10) ||  '                   AND C.BIZ_TYPE = :BIZ_TYPE2';
            RETURN V_TXT;
        END F_INNER_SQL;

    BEGIN
        /********************************************************************************
        * 데이타조회 대상 사업부 구분
        ********************************************************************************/
        --IF @p_division_id NOT IN ('EE','EE_UC')
        SELECT COUNT(*)
          INTO V_EE_CNT
          FROM TABLE(FN_GET_DIVISION_DIV('EE')) A
         WHERE ROWNUM = 1
           AND A.COLUMN_VALUE = V_DIVISION_ID; --div_commonization

        -- BOD 2단계 개발 : FROM , TO 추가
        V_INNER := F_INNER_SQL(V_EE_CNT > 0);

        /********************************************************************************
        * PIVOIT처리
        ********************************************************************************/
        -- PIVOIT 대상 날짜문자열 생성
        --SELECT @mQuery = @mQuery + '[' + yyyymmdd + '], '
        FOR R IN (SELECT IA.YYYYMMDD
                    FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                               , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM
                                  , A.ISO_WEEK
                                  , A.BASIS_START_DATE
                           UNION ALL
                          SELECT 'M_' || B.BASIS_YYYYMM AS YYYYMMDD
                               , MIN(B.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M B
                           WHERE B.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY B.BASIS_YYYYMM
                                  , B.MONTH_NAME
                           UNION ALL
                          SELECT 'D_' || C.BASIS_YYYYMMDD AS YYYYMMDD
                               , C.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M C
                           WHERE C.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           GROUP BY C.BASIS_YYYYMMDD) IA
                   ORDER BY IA.SORT_ORDER_NO)
        LOOP
            V_MQUERY := V_MQUERY
                     || '     , '
                     || CASE WHEN SUBSTR(R.YYYYMMDD, 1, 2) = 'M_'
                             THEN 'TO_CHAR(SUM(CASE WHEN IA.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN IA.QTY END)) AS ' || R.YYYYMMDD
                             WHEN SUBSTR(R.YYYYMMDD, 1, 2) = 'W_'
                             THEN 'TO_CHAR(SUM(CASE WHEN IA.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN IA.QTY END)) AS ' || R.YYYYMMDD
                             WHEN SUBSTR(R.YYYYMMDD, 1, 2) = 'D_'
                             THEN 'TO_CHAR(SUM(CASE WHEN IA.YYYYMMDD = ''' || SUBSTR(R.YYYYMMDD, 3) || ''' THEN IA.QTY END)) AS ' || R.YYYYMMDD
                        END
                     || CHR(10);
        END LOOP;

        V_MEXEC :=            'SELECT IA.DIVISION_ID'
            || CHR(10) ||     '     , FN_GET_DIVISION_NAME(IA.DIVISION_ID) AS DIVISION_NAME'
            || CHR(10) ||     '     , IA.BIZ_TYPE'
            || CHR(10) ||     '     , FN_GET_LOOKUP_CODE_DESC(''BIZ_TYPE'', IA.BIZ_TYPE) AS BIZ_TYPE_NAME'
            || CHR(10) ||     '     , IA.ITEM_ID'
            || CHR(10) ||     '     , NVL(FN_GET_ITEM_NICKNAME(IA.DIVISION_ID, IA.ITEM_ID), ''-'') AS NICK_NAME'
            || CHR(10) ||     '     , IA.ORIGIN_TO_DIVISION_ID'
            || CHR(10) ||     '     , IA.TO_SITE'
            || CHR(10) ||     '     , FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.TO_SITE) AS TO_SITE_DESCRIPTION'
            || CHR(10) ||     '     , IA.ORIGIN_FROM_DIVISION_ID'
            || CHR(10) ||     '     , IA.FROM_SITE'
            || CHR(10) ||     '     , FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.FROM_SITE) AS FROM_SITE_DESCRIPTION'
            || CHR(10) ||     '     , NVL(IA.INCOTERMS, ''/'') AS INCOTERMS'
            || CHR(10) ||     '     , NVL(IA.PROJECT_CODE, ''-'') AS PROJECT_CODE'
            || CHR(10) ||     '     , IA.TRANSPORT_MODE'
            || CHR(10) ||     '     , IA.LT_TOTAL'
            || CHR(10) ||     '     , IA.ELECTRODE_TYPE'
            || CHR(10) ||     '     , IA.BOD_ID'
            || CHR(10) ||     '     , IA.BOD_FROM_YYYYMMDD'
            || CHR(10) ||     '     , IA.BOD_TO_YYYYMMDD'
            || CHR(10) ||     '     , IA.MEASURE'
            || CHR(10) ||     V_MQUERY
            ||                '  FROM (SELECT IB.DIVISION_ID'
            || CHR(10) ||     '             , IB.BIZ_TYPE'
            || CHR(10) ||     '             , IB.ITEM_ID'
            || CHR(10) ||     '             , IB.ELECTRODE_TYPE'
            || CHR(10) ||     '             , IB.ORIGIN_TO_DIVISION_ID'
            || CHR(10) ||     '             , IB.TO_SITE'
            || CHR(10) ||     '             , IB.ORIGIN_FROM_DIVISION_ID'
            || CHR(10) ||     '             , IB.FROM_SITE'
            || CHR(10) ||     '             , IB.INCOTERMS'
            || CHR(10) ||     '             , IB.PROJECT_CODE'
            || CHR(10) ||     '             , IB.TRANSPORT_MODE'
            || CHR(10) ||     '             , IB.LT_TOTAL'
            || CHR(10) ||     '             , IB.MEASURE'
            || CHR(10) ||     '             , IB.QTY'
            || CHR(10) ||     '             , IB.YYYYMMDD'
            || CHR(10) ||     '             , E.BASIS_YYYYMM AS YYYYMM'
            || CHR(10) ||     '             , SUBSTR(E.BASIS_YYYYMM, -4) || E.ISO_WEEK AS ISO_WEEK'
            || CHR(10) ||     '             , IB.BOD_ID'
            || CHR(10) ||     '             , IB.BOD_FROM_YYYYMMDD'
            || CHR(10) ||     '             , IB.BOD_TO_YYYYMMDD'
            || CHR(10) ||     '          FROM ('
            || CHR(10) ||     V_INNER
            || CHR(10) ||     '               ) IB'
            || CHR(10) ||     '             , SCM_SYS_CALENDAR_M E'
            || CHR(10) ||     '         WHERE IB.YYYYMMDD = E.BASIS_YYYYMMDD'
            || CHR(10) ||     '       ) IA'
            || CHR(10) ||     ' GROUP BY IA.DIVISION_ID'
            || CHR(10) ||     '        , IA.BIZ_TYPE'
            || CHR(10) ||     '        , IA.ITEM_ID'
            || CHR(10) ||     '        , IA.TO_SITE'
            || CHR(10) ||     '        , IA.FROM_SITE'
            || CHR(10) ||     '        , IA.INCOTERMS'
            || CHR(10) ||     '        , IA.PROJECT_CODE'
            || CHR(10) ||     '        , IA.TRANSPORT_MODE'
            || CHR(10) ||     '        , IA.LT_TOTAL'
            || CHR(10) ||     '        , IA.MEASURE'
            || CHR(10) ||     '        , IA.ELECTRODE_TYPE'
            || CHR(10) ||     '        , IA.ORIGIN_FROM_DIVISION_ID'
            || CHR(10) ||     '        , IA.ORIGIN_TO_DIVISION_ID'
            || CHR(10) ||     '        , IA.BOD_ID'
            || CHR(10) ||     '        , IA.BOD_FROM_YYYYMMDD'
            || CHR(10) ||     '        , IA.BOD_TO_YYYYMMDD'
            /* 옛 정렬규칙 재현 : 대소문자 무시 · 하이픈 무시 · 밑줄은 글자·숫자보다 앞 · 빈값 맨 앞 */
            || CHR(10) ||     ' ORDER BY UPPER(TRANSLATE(IA.DIVISION_ID, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.DIVISION_ID NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.BIZ_TYPE, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.BIZ_TYPE NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.ITEM_ID, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.ITEM_ID NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.TO_SITE, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.TO_SITE NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.FROM_SITE, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.FROM_SITE NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.TRANSPORT_MODE, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.TRANSPORT_MODE NULLS FIRST'
            || CHR(10) ||     '        , UPPER(TRANSLATE(NVL(IA.INCOTERMS, ''/''), ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , NVL(IA.INCOTERMS, ''/'')'
            || CHR(10) ||     '        , UPPER(TRANSLATE(NVL(IA.PROJECT_CODE, ''-''), ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , NVL(IA.PROJECT_CODE, ''-'')'
            || CHR(10) ||     '        , UPPER(TRANSLATE(IA.BOD_ID, ''_-'', ''/'')) NULLS FIRST'
            || CHR(10) ||     '        , IA.BOD_ID NULLS FIRST'
            || CHR(10) ||     '        , IA.MEASURE DESC';
            --SET @mEXEC = @mEXEC+'		ORDER BY  division_id, biz_type, item_id, to_site, from_site, transport_mode, incoterms, project_code, measure desc '+CHAR(10);

        -----------------------------------------------------------
        -- DEBUG QRY 출력
        -----------------------------------------------------------
        IF P_DEBUG_MODE = 'T' THEN
            BEGIN
                V_POS := 1;
                V_LEN := DBMS_LOB.GETLENGTH(V_MEXEC);
                WHILE V_POS <= V_LEN LOOP
                    DBMS_OUTPUT.PUT_LINE(DBMS_LOB.SUBSTR(V_MEXEC, 4000, V_POS));
                    V_POS := V_POS + 4000;
                END LOOP;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;   /* 출력 버퍼 한도 초과는 조회 결과와 무관하므로 무시 */
            END;
        END IF;
        -----------------------------------------------------------

        /* 피벗 칸이 조회기간에 따라 달라지므로 동적 문장으로 연다 (조건값은 모두 바인드) */
        IF V_EE_CNT > 0 THEN
            OPEN O_RC1 FOR V_MEXEC
            USING V_ITEM_ID, V_ITEM_ID, V_ELECTYPE, V_ELECTYPE, P_FROM_YYYYMMDD, P_TO_YYYYMMDD, V_DIVISION_ID, V_BIZ_TYPE
                , V_ITEM_ID, V_ITEM_ID, V_ELECTYPE, V_ELECTYPE, P_FROM_YYYYMMDD, P_TO_YYYYMMDD, V_DIVISION_ID, V_BIZ_TYPE;
        ELSE
            OPEN O_RC1 FOR V_MEXEC
            USING V_ITEM_ID, V_ITEM_ID, P_FROM_YYYYMMDD, P_TO_YYYYMMDD, V_DIVISION_ID, V_BIZ_TYPE
                , V_ITEM_ID, V_ITEM_ID, P_FROM_YYYYMMDD, P_TO_YYYYMMDD, V_DIVISION_ID, V_BIZ_TYPE;
        END IF;

        --IF @p_division_id NOT IN ('EE','EE_UC')
        IF V_EE_CNT = 0 THEN --div_commonization
            OPEN O_RC2 FOR
                SELECT A.DIVISION_ID
                     , A.BIZ_TYPE
                     , A.ITEM_ID
                     , NVL(A.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                     , NVL(A.ORIGIN_TO_DIVISION_ID, '-') AS ORIGIN_TO_DIVISION_ID
                     , A.TO_SITE
                     , NVL(A.ORIGIN_FROM_DIVISION_ID, '-') AS ORIGIN_FROM_DIVISION_ID
                     , A.FROM_SITE
                     , A.INCOTERMS
                     , A.PROJECT_CODE
                     , B.TRANSPORT_MODE
                     , B.LT_TOTAL
                     , B.BOD_ID                         -- BOD 2단계 개발
                     , 'Fix Reason' AS MEASURE
                     , A.YYYYMMDD
                     , A.FIX_REASON
                  FROM SCP_ANL_SHIPMENT_PLAN_FIX A
                     -- BOD 2단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v
                     , SCP_MST_BOD_N_V B
                 WHERE A.DIVISION_ID = B.DIVISION_ID
                   AND A.BOD_ID = B.BOD_ID
--                 AND (V_ITEM_ID IS NULL OR A.ITEM_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA))   --  2026.10.08 AJS
                   /* 2026.10.08 AJS Model/Nickname 검색 (START) : 입력값(쉼표 여러 개)이 코드 또는 닉네임에 부분일치 */
                   AND (   V_ITEM_ID IS NULL
                        OR EXISTS (SELECT 1
                                     FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA
                                    WHERE TRIM(SA.COLUMN_VALUE) IS NOT NULL
                                      AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(TRIM(SA.COLUMN_VALUE)) || '%'
                                           OR UPPER(FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)) LIKE '%' || UPPER(TRIM(SA.COLUMN_VALUE)) || '%')))
                   /* 2026.10.08 AJS Model/Nickname 검색 (END) */
                   --AND ( ( @p_electype IS NULL OR  @p_electype ='') OR A.ELECTRODE_TYPE	IN (SELECT token FROM dbo.String_Split(@p_electype, ',')))
                   AND A.YYYYMMDD >= P_FROM_YYYYMMDD
                   AND A.YYYYMMDD <= P_TO_YYYYMMDD
                   AND A.DIVISION_ID = V_DIVISION_ID
                   AND A.BIZ_TYPE = V_BIZ_TYPE
                 ORDER BY UPPER(TRANSLATE(A.DIVISION_ID, '_-', '/')) NULLS FIRST
                        , A.DIVISION_ID NULLS FIRST
                        , UPPER(TRANSLATE(A.BIZ_TYPE, '_-', '/')) NULLS FIRST
                        , A.BIZ_TYPE NULLS FIRST
                        , UPPER(TRANSLATE(A.ITEM_ID, '_-', '/')) NULLS FIRST
                        , A.ITEM_ID NULLS FIRST
                        , UPPER(TRANSLATE(A.TO_SITE, '_-', '/')) NULLS FIRST
                        , A.TO_SITE NULLS FIRST
                        , UPPER(TRANSLATE(A.FROM_SITE, '_-', '/')) NULLS FIRST
                        , A.FROM_SITE NULLS FIRST
                        , MEASURE DESC;
        ELSE
            OPEN O_RC2 FOR
                SELECT A.DIVISION_ID
                     , A.BIZ_TYPE
                     , A.ITEM_ID
                     , NVL(A.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                     , NVL(A.ORIGIN_TO_DIVISION_ID, '-') AS ORIGIN_TO_DIVISION_ID
                     , A.TO_SITE
                     , NVL(A.ORIGIN_FROM_DIVISION_ID, '-') AS ORIGIN_FROM_DIVISION_ID
                     , A.FROM_SITE
                     , A.INCOTERMS
                     , A.PROJECT_CODE
                     , B.TRANSPORT_MODE
                     , B.LT_TOTAL
                     , B.BOD_ID                         -- BOD 2단계 개발
                     , 'Fix Reason' AS MEASURE
                     , A.YYYYMMDD
                     , A.FIX_REASON
                  FROM SCP_ANL_SHIPMENT_PLAN_FIX A
                     -- BOD 2단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v
                     , SCP_MST_BOD_N_V B
                 WHERE A.BOD_ID = B.BOD_ID
--                 AND (V_ITEM_ID IS NULL OR A.ITEM_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA))   --  2026.10.08 AJS
                   /* 2026.10.08 AJS Model/Nickname 검색 (START) : 입력값(쉼표 여러 개)이 코드 또는 닉네임에 부분일치 */
                   AND (   V_ITEM_ID IS NULL
                        OR EXISTS (SELECT 1
                                     FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA
                                    WHERE TRIM(SA.COLUMN_VALUE) IS NOT NULL
                                      AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(TRIM(SA.COLUMN_VALUE)) || '%'
                                           OR UPPER(FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)) LIKE '%' || UPPER(TRIM(SA.COLUMN_VALUE)) || '%')))
                   /* 2026.10.08 AJS Model/Nickname 검색 (END) */
                   AND (V_ELECTYPE IS NULL OR A.ELECTRODE_TYPE IN (SELECT XA.COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ELECTYPE, ',')) XA))
                   AND A.YYYYMMDD >= P_FROM_YYYYMMDD
                   AND A.YYYYMMDD <= P_TO_YYYYMMDD
                   AND A.DIVISION_ID = V_DIVISION_ID
                   AND A.BIZ_TYPE = V_BIZ_TYPE
                 ORDER BY UPPER(TRANSLATE(A.DIVISION_ID, '_-', '/')) NULLS FIRST
                        , A.DIVISION_ID NULLS FIRST
                        , UPPER(TRANSLATE(A.BIZ_TYPE, '_-', '/')) NULLS FIRST
                        , A.BIZ_TYPE NULLS FIRST
                        , UPPER(TRANSLATE(A.ITEM_ID, '_-', '/')) NULLS FIRST
                        , A.ITEM_ID NULLS FIRST
                        , UPPER(TRANSLATE(A.TO_SITE, '_-', '/')) NULLS FIRST
                        , A.TO_SITE NULLS FIRST
                        , UPPER(TRANSLATE(A.FROM_SITE, '_-', '/')) NULLS FIRST
                        , A.FROM_SITE NULLS FIRST
                        , MEASURE DESC;
        END IF;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);
            OPEN O_RC1 FOR
                SELECT NULL AS DUMMY
                  FROM DUAL
                 WHERE 1 = 0;
            OPEN O_RC2 FOR
                SELECT NULL AS DUMMY
                  FROM DUAL
                 WHERE 1 = 0;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1'  AS CODE
                     , V_ERR AS MSG
                  FROM DUAL;
    END P_SCP0025_GET_SHIP_PLAN_FIX;

    /* ==============================================================================================
       SCP0025_SAVE_SHIPMENT_PLAN_FIX_DATASET
       ============================================================================================== */
    PROCEDURE P_SCP0025_SAVE_FIX_DATASET
    (
        P_DATA              IN  CLOB,
        P_USER_ID           IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SCP0025_SAVE_SHIPMENT_PLAN_FIX_DATASET
     * Description  : SHIPMENT PLAN FG/SEMI FIX 삭제
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2019/07/25   yhw				[CSR ID:4071705] Production Plan Fix에서 Unfix 기능 추가
     * 2022/04/29   chaan			81_UC, EE_UC 추가로 DIVSION 크기 확장
     * 2025/11/11   hrkim			[PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선
     *								  : ESS 가상 사이트 계획을 매핑된 JV 사이트 계획으로 동기화 저장 (ESS 가상 -> JV Real 단방향 저장)
     *									- @SCP0025를 @SCP0025_WITH_JV 변수로 대체하여 사용
     *									- TO Site 정보는 그대로 가져간다. (BOD_ID는 매핑이 안되면 '-')
     *								    - 2025.12.16 동기화 대상 데이터 from/to 사이트와 무관하게 origin from/to division_id 컬럼 division_id와 같은 값으로 저장(81_ST) : 김춘동 책임님
     *								    - 2025.12.23 동기화 데이터 생성시 BOD_ID 매핑이 안되는 경우 ESS 가상 사이트 BOD_ID 유지
     * 2026.09.17   AJS             [MSSQL -> Oracle 전환]
     *                              - 테이블 형식 파라미터 @SCP0025 -> JSON 배열(P_DATA) · 행 키는 파일 머리 설명 참조
     *                              - @SCP0025_WITH_JV 변수 -> GT_SCP0025_FIX_DATA (ON COMMIT DELETE ROWS)
     *                              - #JV_ESS_SCM_SITE_MAP · #DIVISION_LAST_PLAN_INFO · #BOD_ITEM -> 인라인 뷰
     *                              - 등록자(p_created_by) 는 행 값 대신 세션 사용자(P_USER_ID)
     *                              - 트랜잭션 : AS-IS 는 BEGIN TRAN 없이 문장 단위로 반영되고 CATCH 에서 COMMIT 한다.
     *                                           실패한 문장만 되돌려지고 앞 문장 반영분은 남는 동작을 그대로 유지한다.
     *                              - 키 비교 대소문자 무시 재현 : 삭제 플래그 · 입력 키 UPPER,
     *                                원장에 소문자가 있는 칸(TO_SITE · PROJECT_CODE, BOD 의 TO_SITE)은 양쪽 UPPER
     *                              - BOD 대표 선정 : 이관 시 수정일시 밀리초가 잘려 생긴 동률을 BOD_ID 내림차순으로 고정
     */
        V_MAX_LOOP_CNT      VARCHAR2(50 CHAR);

        -- LOG 용 변수 설정
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0025_SAVE_SHIPMENT_PLAN_FIX_DATASET';
        V_LOG_TYPE          VARCHAR2(30 CHAR);     -- START/END/ERROR/...
        V_N_LOG_COUNT       PLS_INTEGER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        V_EVENT_DATE        DATE;

        -- 실행시간 확인용
        V_START_TIME        DATE := SYSDATE;
        V_EXEC_TIME         VARCHAR2(10 CHAR) := ''; --'00:00';

        V_TODAY             VARCHAR2(8 CHAR) := TO_CHAR(SYSDATE, 'YYYYMMDD');
        V_BEFORE_20         VARCHAR2(8 CHAR) := TO_CHAR(SYSDATE - 20, 'YYYYMMDD');
        V_BEFORE_7          VARCHAR2(8 CHAR) := TO_CHAR(SYSDATE - 7, 'YYYYMMDD');
        V_LAST_MONDAY       VARCHAR2(8 CHAR);

        V_ERR_CODE          VARCHAR2(20 CHAR);
        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);
    BEGIN
        /* GTT 초기화 (TRUNCATE 금지) */
        DELETE FROM GT_SCP0025_FIX_DATA;

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        V_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

        -------------------------------------------------------------------------------------------------------------------------------------------------------
        --### Start : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : ESS 가상 라인 계획으로 매핑된 JV 라인 계획 동기화 저장 (ESS 가상 -> JV Real 단방향 저장)
        -------------------------------------------------------------------------------------------------------------------------------------------------------
        ------------------------------------------------------------------------------------------------------------------
        -- 파마미터로 받은 데이터 @SCP0025_WITH_JV 변수에 추가
        -- ESS MI법인 -> JV 동기화 저장 (단방향 저장으로 가상 사이트에 매핑된 JV 사이트 데이터는 제외)
        ------------------------------------------------------------------------------------------------------------------
        INSERT INTO GT_SCP0025_FIX_DATA
             (
               P_ACTIVE_FLAG
             , P_DIVISION_ID
             , P_OPERATION_GROUP
             , P_ITEM_ID
             , P_TO_SITE
             , P_FROM_SITE
             , P_BOD_ID
             , P_YYYYMMDD
             , P_PROJECT_CODE
             , P_INCOTERMS
             , P_QTY
             , P_ORIGIN_FROM_DIVISION_ID
             , P_ORIGIN_TO_DIVISION_ID
             , P_ELECTRODE_TYPE
             , P_CREATED_BY
             )
        SELECT A.ACTIVE_FLAG
             , A.DIVISION_ID
             , A.BIZ_TYPE
             , A.ITEM_ID
             , A.TO_SITE
             , A.FROM_SITE
             , A.BOD_ID
             , A.YYYYMMDD
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ELECTRODE_TYPE
             , P_USER_ID
          FROM JSON_TABLE(P_DATA, '$[*]' ERROR ON ERROR
                          COLUMNS ( ACTIVE_FLAG             VARCHAR2(4000) PATH '$.ACTIVE_FLAG'             NULL ON EMPTY
                                  , DIVISION_ID             VARCHAR2(4000) PATH '$.DIVISION_ID'             NULL ON EMPTY
                                  , BIZ_TYPE                VARCHAR2(4000) PATH '$.BIZ_TYPE'                NULL ON EMPTY
                                  , ITEM_ID                 VARCHAR2(4000) PATH '$.ITEM_ID'                 NULL ON EMPTY
                                  , TO_SITE                 VARCHAR2(4000) PATH '$.TO_SITE'                 NULL ON EMPTY
                                  , FROM_SITE               VARCHAR2(4000) PATH '$.FROM_SITE'               NULL ON EMPTY
                                  , BOD_ID                  VARCHAR2(4000) PATH '$.BOD_ID'                  NULL ON EMPTY
                                  , YYYYMMDD                VARCHAR2(4000) PATH '$.YYYYMMDD'                NULL ON EMPTY
                                  , PROJECT_CODE            VARCHAR2(4000) PATH '$.PROJECT_CODE'            NULL ON EMPTY
                                  , INCOTERMS               VARCHAR2(4000) PATH '$.INCOTERMS'               NULL ON EMPTY
                                  , QTY                     VARCHAR2(4000) PATH '$.QTY'                     NULL ON EMPTY
                                  , ORIGIN_FROM_DIVISION_ID VARCHAR2(4000) PATH '$.ORIGIN_FROM_DIVISION_ID' NULL ON EMPTY
                                  , ORIGIN_TO_DIVISION_ID   VARCHAR2(4000) PATH '$.ORIGIN_TO_DIVISION_ID'   NULL ON EMPTY
                                  , ELECTRODE_TYPE          VARCHAR2(4000) PATH '$.ELECTRODE_TYPE'          NULL ON EMPTY
                                  )) A;
        -- 2025.12.16 주석 처리 (자동차 품목 생산될 수 있음) 	  LEFT JOIN #JV_ESS_SCM_SITE_MAP SM
        -- 2025.12.16 주석 처리 (자동차 품목 생산될 수 있음) 		     ON SM.RP_DIVISION_ID	= PR.P_DIVISION_ID
        -- 2025.12.16 주석 처리 (자동차 품목 생산될 수 있음) 		    AND SM.RP_SCM_SITE_ID	= PR.P_FROM_SITE
        -- 2025.12.16 주석 처리 (자동차 품목 생산될 수 있음) WHERE SM.RP_DIVISION_ID IS NULL  --- 가상 사이트에 매핑된 JV 사이트 데이터는 제외

        ------------------------------------------------------------------------------------------------------------------
        -- 가상 사이트에 매핑된 JV 사이트 데이터 @SCP0025_WITH_JV 변수에 추가
        -- ESS MI법인 -> JV 동기화 저장 (단방향 저장으로 가상 사이트에 매핑된 JV 사이트 데이터는 제외)
        ------------------------------------------------------------------------------------------------------------------
        SELECT MAX(YYYYMMDD)
          INTO V_LAST_MONDAY
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD <= V_TODAY
           AND DAYOFWEEK = 'MON';

        INSERT INTO GT_SCP0025_FIX_DATA
             (
               P_ACTIVE_FLAG
             , P_DIVISION_ID
             , P_OPERATION_GROUP
             , P_ITEM_ID
             , P_TO_SITE
             , P_FROM_SITE
             , P_BOD_ID
             , P_YYYYMMDD
             , P_PROJECT_CODE
             , P_INCOTERMS
             , P_QTY
             , P_ORIGIN_FROM_DIVISION_ID
             , P_ORIGIN_TO_DIVISION_ID
             , P_ELECTRODE_TYPE
             , P_CREATED_BY
             )
        SELECT A.P_ACTIVE_FLAG
             , B.RP_DIVISION_ID AS P_DIVISION_ID
             , A.P_OPERATION_GROUP
             , A.P_ITEM_ID
             , A.P_TO_SITE
             , B.RP_SCM_SITE_ID AS P_FROM_SITE
             , NVL(NVL(XA.BOD_ID, A.P_BOD_ID), '/') AS P_BOD_ID       -- 2025.12.23 bod_id 매핑이 안되는 경우 ESS가상 사이트 기준 BOD_ID 유지
             , A.P_YYYYMMDD
             , A.P_PROJECT_CODE
             , A.P_INCOTERMS
             , A.P_QTY
             , B.RP_DIVISION_ID AS P_ORIGIN_FROM_DIVISION_ID
             , B.RP_DIVISION_ID AS P_ORIGIN_TO_DIVISION_ID            -- 2025.12.16 division_id와 같은 값으로
             , A.P_ELECTRODE_TYPE
             , A.P_CREATED_BY
          FROM GT_SCP0025_FIX_DATA A
             , TABLE(FN_GET_JV_REAL_ESS_VIRTUAL_SITE_MAP()) B
               ------------------------------------------------------------------------------------------------------------
               -- DIVISION 주차별 최종 수행 Plan 버전 정보
               -- ESS 가상 라인 매핑 JV division의 동기화 대상 버전 정보 확인을 위한 데이터
               -- Final Plan은 수정 대상에서 제외 ?
               ------------------------------------------------------------------------------------------------------------
             , (SELECT SA.DIVISION_ID
                     , SA.PLAN_START_YYYYMMDD
                  FROM (SELECT E.DIVISION_ID
                             , D.PLAN_NAME AS PLAN_START_YYYYMMDD
                             , E.PLAN_TYPE
                             , ROW_NUMBER() OVER (PARTITION BY E.DIVISION_ID
                                                             , D.PLAN_NAME
                                                      ORDER BY CASE WHEN E.PLAN_TYPE = 'PR' THEN 4
                                                                    WHEN E.PLAN_TYPE = 'MA' THEN 3
                                                                    WHEN E.PLAN_TYPE = 'SE' THEN 2
                                                                    WHEN E.PLAN_TYPE = 'FN' THEN 1
                                                                    ELSE 0
                                                               END
                                                             , E.PLAN_SEQ DESC NULLS LAST
                                                             , E.INPUT_START_DATE DESC NULLS LAST) AS RN
                          FROM SCM_MST_PLAN D
                             , SCM_MST_PLAN_DETAIL E
                             , SCM_MST_DIVISION F
                         WHERE E.DIVISION_ID = D.DIVISION_ID
                           AND E.PLAN_ID = D.PLAN_ID
                           AND F.DIVISION_ID = D.DIVISION_ID
                           AND E.PLAN_STATUS = '1'
                           AND F.ATTRIBUTE3 != 'EE'
                           AND D.PLAN_CYCLE = 'WEEKLY'
                           AND D.PLAN_NAME >= V_BEFORE_20) SA
                 WHERE SA.RN = 1
                   AND SA.PLAN_TYPE != 'FN') IA  -- Final plan 대상에서 제외
             , SCP_MST_BOD C
               ------------------------------------------------------------------------------------------------------------------
               -- BOD 및 BOD ITEM 정보
               ------------------------------------------------------------------------------------------------------------------
             , (SELECT SB.DIVISION_ID
                     , SB.FROM_SITE
                     , SB.TO_SITE
                     , SB.INCOTERMS
                     , SB.ITEM_ID
                     , SB.BOD_ID
                  FROM (SELECT G.DIVISION_ID
                             , G.FROM_SITE
                             , G.TO_SITE
                             , G.INCOTERMS
                             , H.ITEM_ID
                             , G.BOD_ID
                             , ROW_NUMBER() OVER (PARTITION BY G.DIVISION_ID
                                                             , G.FROM_SITE
                                                             , G.TO_SITE
                                                             , G.INCOTERMS
                                                             , H.ITEM_ID
                                                      ORDER BY G.PRIORITY NULLS FIRST
                                                             , H.PRIORITY NULLS FIRST
                                                             , G.ATTRIBUTE3 DESC NULLS LAST
                                                             , G.LAST_UPDATE_DATE DESC NULLS LAST
                                                             , LENGTH(G.BOD_ID) DESC       /* 수정일시 밀리초 절삭 동률 고정 */
                                                             , G.BOD_ID DESC) AS RN
                          FROM SCP_MST_BOD G
                             , SCP_MST_BOD_ITEM H
                         WHERE H.BOD_ID = G.BOD_ID
                           AND EXISTS (SELECT 1
                                         FROM TABLE(FN_GET_JV_REAL_ESS_VIRTUAL_SITE_MAP()) SC
                                        WHERE SC.RP_DIVISION_ID = G.DIVISION_ID
                                          AND SC.RP_SCM_SITE_ID = G.FROM_SITE)
                           AND H.VALID_YN = 'Y'
                           AND G.VALID_YN = 'Y'
                           AND H.TO_YYYYMMDD >= V_BEFORE_7
                           AND G.ATTRIBUTE3 > V_BEFORE_7) SB
                 WHERE SB.RN = 1) XA
         WHERE B.VP_DIVISION_ID = UPPER(A.P_DIVISION_ID)
           AND B.VP_SCM_SITE_ID = UPPER(A.P_FROM_SITE)
           AND IA.DIVISION_ID = B.RP_DIVISION_ID            -- 수정할 대상 버전이 있어야 수정 (FN 까지 완료된 경우 수정하지 않음)
           AND C.BOD_ID(+) = UPPER(A.P_BOD_ID)
           AND XA.DIVISION_ID(+) = B.RP_DIVISION_ID
           AND XA.FROM_SITE(+) = B.RP_SCM_SITE_ID
           AND UPPER(XA.TO_SITE(+)) = UPPER(A.P_TO_SITE)
           AND XA.INCOTERMS(+) = C.INCOTERMS
           AND XA.ITEM_ID(+) = UPPER(A.P_ITEM_ID)
           AND IA.PLAN_START_YYYYMMDD = V_LAST_MONDAY;
        -------------------------------------------------------------------------------------------------------------------------------------------------------
        --### End : [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : ESS 가상 라인 계획으로 매핑된 JV 라인 계획 동기화 저장 (ESS 가상 -> JV Real 단방향 저장)
        -------------------------------------------------------------------------------------------------------------------------------------------------------

        --수정 Row
        SELECT TO_CHAR(COUNT(*))
          INTO V_MAX_LOOP_CNT
          FROM GT_SCP0025_FIX_DATA; -- PJ2025F254 : @SCP0025를 @SCP0025_WITH_JV 변수로 대체하여 사용

        --3. Fix History
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
             (
               HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , BIZ_TYPE
             , ITEM_ID
             , TO_SITE
             , FROM_SITE
             , PROJECT_CODE
             , INCOTERMS
             , BOD_ID
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , FIX_REASON
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , HISTORY_CREATION_DATE
             , ATTRIBUTE1
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
             , B.FIX_ID
             , A.P_DIVISION_ID
             , A.P_OPERATION_GROUP
             , A.P_ITEM_ID
             , A.P_TO_SITE
             , A.P_FROM_SITE
             , A.P_PROJECT_CODE
             , A.P_INCOTERMS
             , A.P_BOD_ID
             , A.P_YYYYMMDD
             , TRUNC(TO_NUMBER(A.P_QTY))       /* cast(round(x, 0, 1) as int) : 세 번째 인자 1 은 절삭 */
             , A.P_ORIGIN_FROM_DIVISION_ID
             , A.P_ORIGIN_TO_DIVISION_ID
             , A.P_ELECTRODE_TYPE
             , B.FIX_REASON
             , A.P_CREATED_BY
             , SYSDATE
             , A.P_CREATED_BY
             , SYSDATE
             , SYSDATE
             , A.P_ACTIVE_FLAG
          FROM GT_SCP0025_FIX_DATA A -- PJ2025F254 : @SCP0025를 @SCP0025_WITH_JV 변수로 대체하여 사용 B
             , SCP_ANL_SHIPMENT_PLAN_FIX B
         WHERE B.DIVISION_ID = UPPER(A.P_DIVISION_ID)
           AND B.BIZ_TYPE = UPPER(A.P_OPERATION_GROUP)
           AND B.ITEM_ID = UPPER(A.P_ITEM_ID)
           AND UPPER(B.TO_SITE) = UPPER(A.P_TO_SITE)
           AND B.FROM_SITE = UPPER(A.P_FROM_SITE)
           AND UPPER(NVL(B.PROJECT_CODE, '-')) = UPPER(NVL(A.P_PROJECT_CODE, '-'))
           AND NVL(B.INCOTERMS, '-') = UPPER(NVL(A.P_INCOTERMS, '-'))
           AND B.BOD_ID = UPPER(A.P_BOD_ID)
           AND B.YYYYMMDD = A.P_YYYYMMDD
           AND NVL(B.ORIGIN_FROM_DIVISION_ID, '-') = UPPER(NVL(A.P_ORIGIN_FROM_DIVISION_ID, '-'))
           AND NVL(B.ORIGIN_TO_DIVISION_ID, '-') = UPPER(NVL(A.P_ORIGIN_TO_DIVISION_ID, '-'))
           AND NVL(B.ELECTRODE_TYPE, '-') = UPPER(NVL(A.P_ELECTRODE_TYPE, '-'));

        --4. 삭제
        DELETE FROM SCP_ANL_SHIPMENT_PLAN_FIX A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0025_FIX_DATA SA -- PJ2025F254 : @SCP0025를 @SCP0025_WITH_JV 변수로 대체하여 사용 B
                        WHERE A.DIVISION_ID = UPPER(SA.P_DIVISION_ID)
                          AND A.BIZ_TYPE = UPPER(SA.P_OPERATION_GROUP)
                          AND A.ITEM_ID = UPPER(SA.P_ITEM_ID)
                          AND UPPER(A.TO_SITE) = UPPER(SA.P_TO_SITE)
                          AND A.FROM_SITE = UPPER(SA.P_FROM_SITE)
                          AND UPPER(NVL(A.PROJECT_CODE, '-')) = UPPER(NVL(SA.P_PROJECT_CODE, '-'))
                          AND NVL(A.INCOTERMS, '-') = UPPER(NVL(SA.P_INCOTERMS, '-'))
                          AND A.BOD_ID = UPPER(SA.P_BOD_ID)
                          AND A.YYYYMMDD = SA.P_YYYYMMDD
                          AND NVL(A.ORIGIN_FROM_DIVISION_ID, '-') = UPPER(NVL(SA.P_ORIGIN_FROM_DIVISION_ID, '-'))
                          AND NVL(A.ORIGIN_TO_DIVISION_ID, '-') = UPPER(NVL(SA.P_ORIGIN_TO_DIVISION_ID, '-'))
                          AND NVL(A.ELECTRODE_TYPE, '-') = UPPER(NVL(SA.P_ELECTRODE_TYPE, '-'))
                          AND UPPER(SA.P_ACTIVE_FLAG) = 'D');

        V_EXEC_TIME := LPAD(TO_CHAR(TRUNC(((SYSDATE - V_START_TIME) * 86400) / 60)), 2, '0')
                    || ':'
                    || LPAD(TO_CHAR(MOD(TRUNC((SYSDATE - V_START_TIME) * 86400), 60)), 2, '0');

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        V_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

        COMMIT;

        -- 결과코드, 결과 카운트 반환
        OPEN O_RESULT_CURSOR FOR
            SELECT 'S'            AS RESULT_CODE
                 , V_MAX_LOOP_CNT AS RESULT_CNT
                 , '0'            AS CODE
                 , 'SUCCESS'      AS MSG
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            /* SQLCODE · SQLERRM 은 SQL 문 안에서 바로 쓸 수 없으므로 변수로 받는다 */
            V_ERR_CODE    := TO_CHAR(SQLCODE);
            V_ERR_MESSAGE := SUBSTR(SQLERRM, 1, 4000);

            INSERT INTO SCM_SYS_LOG_BATCH
                 (
                   PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 )
            VALUES
                 (
                   V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_ERR_MESSAGE
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME
                 );

            /* IF @@TRANCOUNT > 0 COMMIT WORK - 실패한 문장 이전 반영분 유지 */
            COMMIT;

            -- error코드, errror 메시지 반환
            OPEN O_RESULT_CURSOR FOR
                SELECT 'F'                                        AS RESULT_CODE
                     , '[' || V_ERR_CODE || ']' || V_ERR_MESSAGE  AS ERR_MESSAGE
                     , '-1'                                       AS CODE
                     , '[' || V_ERR_CODE || ']' || V_ERR_MESSAGE  AS MSG
                  FROM DUAL;
    END P_SCP0025_SAVE_FIX_DATASET;

END PKG_SCP0025;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0025
-- ##### END PACKAGE BODY PKG_SCP0025

-- ##### START PACKAGE BODY PKG_SCP0027
CREATE OR REPLACE PACKAGE BODY PKG_SCP0027
AS
/****************************************************************************************************/
/* Program ID  : PKG_SCP0027                                                                        */
/* Description : ProjectRoute Electrode                                                             */
/* Program History                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2026.09.24  ZIONEX       [PJ202650304] MSSQL -> Oracle 전환                                      */
/* 2026.10.06  AJS          P_SCP0027_GET_PROJECTROUTE_ELECTRODE 조회 속도 개선(라인 확인 하위질의 IX01_SCM_LINE_M 사용) */
/* 2026.10.07  AJS          P_SCP0027_GET_PROJECTROUTE_ELECTRODE 조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시 */
/****************************************************************************************************/

    TYPE T_TOK IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;

    /* ------------------------------------------------------------
       ^ 구분 CLOB 분리 (AS-IS SCM_ARR_SPL_VAL · SCM_ARR_SPL_CNT 대응)
       - 토큰 앞뒤 공백 제거, 순번 1 부터
       - O_CNT : AS-IS SCM_ARR_SPL_CNT (구분자 수 + 1, 입력이 비면 0)
       ------------------------------------------------------------ */
    PROCEDURE P_SPLIT_TOKEN
    (
        P_STR       IN  CLOB
      , P_DELIM     IN  VARCHAR2
      , O_TAB       OUT T_TOK
      , O_CNT       OUT PLS_INTEGER
    )
    IS
        V_POS       PLS_INTEGER;
        V_FROM      PLS_INTEGER := 1;
        V_NR        PLS_INTEGER := 0;
        V_LEN       PLS_INTEGER := NVL(DBMS_LOB.GETLENGTH(P_STR), 0);
    BEGIN

        IF V_LEN = 0
        THEN
            O_CNT := 0;
            RETURN;
        END IF;

        LOOP
            V_POS := DBMS_LOB.INSTR(P_STR, P_DELIM, V_FROM, 1);

            EXIT WHEN V_POS = 0 OR V_POS IS NULL;

            V_NR := V_NR + 1;
            O_TAB(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_STR, V_POS - V_FROM, V_FROM));
            V_FROM := V_POS + 1;
        END LOOP;

        V_NR := V_NR + 1;

        IF V_FROM <= V_LEN
        THEN
            O_TAB(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_STR, V_LEN - V_FROM + 1, V_FROM));
        END IF;

        O_CNT := V_NR;

    END P_SPLIT_TOKEN;

    /* 토큰 꺼내기 - 없는 순번이면 빈 값 (AS-IS SCM_ARR_SPL_VAL 과 같음) */
    FUNCTION F_TOKEN
    (
        P_TAB       IN  T_TOK
      , P_IDX       IN  PLS_INTEGER
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF P_TAB.EXISTS(P_IDX)
        THEN
            RETURN P_TAB(P_IDX);
        END IF;

        RETURN NULL;
    END F_TOKEN;

    /* ------------------------------------------------------------
       AS-IS 등록일시 문자열 -> DATETIME 암묵 변환 대응
       - 빈 값은 MSSQL 이 1900-01-01 로 바꾼다
       - 바꿀 수 없는 값은 AS-IS 처럼 오류
       ------------------------------------------------------------ */
    FUNCTION F_TO_DATETIME
    (
        P_STR       IN  VARCHAR2
    )
    RETURN DATE
    IS
        V_DATE      DATE;
    BEGIN
        IF RTRIM(P_STR) IS NULL
        THEN
            RETURN DATE '1900-01-01';
        END IF;

        V_DATE := CAST(TO_TIMESTAMP(TRIM(P_STR) DEFAULT NULL ON CONVERSION ERROR, 'YYYY-MM-DD HH24:MI:SS.FF') AS DATE);

        IF V_DATE IS NULL
        THEN
            V_DATE := TO_DATE(TRIM(P_STR) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS');
        END IF;

        IF V_DATE IS NULL
        THEN
            RAISE_APPLICATION_ERROR(-20001, 'Conversion failed when converting date and/or time from character string. [' || P_STR || ']');
        END IF;

        RETURN V_DATE;
    END F_TO_DATETIME;


/****************************************************************************************************/
/* Program ID  : P_SCP0027_GET_PROJECTROUTE_ELECTRODE                                               */
/* Description : Project Route Plant Site(Electrode) 조회                                           */
/****************************************************************************************************/
PROCEDURE P_SCP0027_GET_PROJECTROUTE_ELECTRODE
(
    P_DIVISION_ID       IN  VARCHAR2
  , P_PLANT_SITE        IN  VARCHAR2
  , P_OPERATION_GROUP   IN  VARCHAR2
  , P_ITEM_ID           IN  VARCHAR2
  , P_FROM_YYYYMM       IN  VARCHAR2
  , P_TO_YYYYMM         IN  VARCHAR2
  , P_VALID_FLAG        IN  VARCHAR2
  , O_MAIN_LIST         OUT SYS_REFCURSOR
  , O_ALL_LIST          OUT SYS_REFCURSOR
  , O_ITEM_LIST         OUT SYS_REFCURSOR
  , O_RESULT_CODE       OUT VARCHAR2
  , O_RESULT_MSG        OUT VARCHAR2
)
IS
    V_DIVISION_ID       VARCHAR2(4000 CHAR) := P_DIVISION_ID;
    V_PLANT_SITE        VARCHAR2(4000 CHAR) := P_PLANT_SITE;
    V_OPERATION_GROUP   VARCHAR2(4000 CHAR) := P_OPERATION_GROUP;
    V_ITEM_ID           VARCHAR2(200 CHAR)  := P_ITEM_ID;
    V_VALID_FLAG        VARCHAR2(200 CHAR)  := P_VALID_FLAG;
    V_ITEM_TAB          T_STR_TAB           := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */

BEGIN

    /* 조회조건 ALL 은 조건 없음으로 다룬다 */
    IF UPPER(TRIM(V_DIVISION_ID))     = 'ALL' THEN V_DIVISION_ID     := NULL; END IF;
    IF UPPER(TRIM(V_PLANT_SITE))      = 'ALL' THEN V_PLANT_SITE      := NULL; END IF;
    IF UPPER(TRIM(V_OPERATION_GROUP)) = 'ALL' THEN V_OPERATION_GROUP := NULL; END IF;
    IF UPPER(TRIM(V_ITEM_ID))         = 'ALL' THEN V_ITEM_ID         := NULL; END IF;
    IF UPPER(TRIM(V_VALID_FLAG))      = 'ALL' THEN V_VALID_FLAG      := NULL; END IF;

    /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력 토큰(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
       대상 품목 = 사이트별 품목 우선순위 원장 품목(등록분) + 품목 원장 품목(미등록 전극 하위품목 : BOM 뷰가 품목 원장과 내부조인하므로 품목 원장에 있다)
       닉네임 출처 = 품목 원장(사업부 무관 : 미등록분 하위품목의 품목 원장 사업부가 행 사업부와 다를 수 있다) */
    IF TRIM(V_ITEM_ID) IS NOT NULL THEN
      SELECT IA.ITEM_ID
        BULK COLLECT INTO V_ITEM_TAB
        FROM SCM_MST_SITE_ITEM_PRIORITY IA
           , TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA
       WHERE SA.COLUMN_VALUE IS NOT NULL
         AND UPPER(IA.ITEM_ID) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'
      UNION
      SELECT XA.ITEM_ID
        FROM SCM_MST_ITEM_SN XA
           , TABLE(STRING_SPLIT(V_ITEM_ID, ',')) XB
       WHERE XB.COLUMN_VALUE IS NOT NULL
         AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(XB.COLUMN_VALUE) || '%'
              OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(XB.COLUMN_VALUE) || '%');
    END IF;
    /* 2026.10.07 AJS Model/Nickname 검색 (END) */

    /* 1. 주 목록 — Cell계획기준 전극미등록 모델 리스트 + 등록분 */
    OPEN O_MAIN_LIST FOR
        SELECT PRIORITY_SEQ
             , DIVISION_ID
             , PROJECT_CODE
             , ITEM_ID
             , SCM_SITE_ID
             , PLANT_SITE_ID_B
             , PLANT_SITE_ID
             , TACT_TIME_FLAG
             , PRIORITY
             , VALID_YN
             , ORG_VALID_YN
             , FROM_YYYYMMDD
             , TO_YYYYMMDD
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , OPERATION_GROUP
             , ORG_FROM_YYYYMMDD
             , ORG_TO_YYYYMMDD
             , MERGE_DATE
             , IS_PASS_N1
             , IS_PASS_N2
             , IS_PASS_N3
             , IS_PASS_N4
             , IS_PASS_N5
             , IS_PASS_N6
             , IS_PASS_N7
             , NICK_NAME
             , OPERATION_GROUP_NAME
             , ACTION_FLAG_DIV
             , ROW_COLOR_INDEX
             , SORT_ORDER
          FROM (SELECT ''                                                       AS PRIORITY_SEQ
                     , A.DIVISION_ID
                     , '-'                                                      AS PROJECT_CODE
                     , A.CHILD_ITEM_ID                                          AS ITEM_ID
                     , '-'                                                      AS SCM_SITE_ID
                     , ''                                                       AS PLANT_SITE_ID_B
                     , ''                                                       AS PLANT_SITE_ID
                     , ''                                                       AS TACT_TIME_FLAG
                     , 0                                                        AS PRIORITY     /* AS-IS 는 빈 문자를 숫자 칸과 UNION 해 0 이 된다 */
                     , 'Y'                                                      AS VALID_YN
                     , 'Y'                                                      AS ORG_VALID_YN
                     , ''                                                       AS FROM_YYYYMMDD
                     , ''                                                       AS TO_YYYYMMDD
                     , ''                                                       AS CREATED_BY
                     , CAST(NULL AS DATE)                                       AS CREATION_DATE
                     , ''                                                       AS LAST_UPDATED_BY
                     , CAST(NULL AS DATE)                                       AS LAST_UPDATE_DATE
                     , A.OPERATION_GROUP_ID                                     AS OPERATION_GROUP
                     , ''                                                       AS ORG_FROM_YYYYMMDD
                     , ''                                                       AS ORG_TO_YYYYMMDD
                     , ''                                                       AS MERGE_DATE
                     , ''                                                       AS IS_PASS_N1
                     , ''                                                       AS IS_PASS_N2
                     , ''                                                       AS IS_PASS_N3
                     , ''                                                       AS IS_PASS_N4
                     , ''                                                       AS IS_PASS_N5
                     , ''                                                       AS IS_PASS_N6
                     , ''                                                       AS IS_PASS_N7
                     , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.CHILD_ITEM_ID)     AS NICK_NAME
                     , C.SEGMENT2                                               AS OPERATION_GROUP_NAME
                     , '-'                                                      AS ACTION_FLAG_DIV
                     , 0                                                        AS ROW_COLOR_INDEX
                     , 0                                                        AS SORT_ORDER
                  FROM SCM_MST_MODEL_FINAL_ITEM_BOM_V A
                     , SCM_ADM_LOOKUP_MASTER B
                     , SCM_ADM_LOOKUP_MASTER_DETAIL C
                     , (SELECT DISTINCT DIVISION_ID
                             , ITEM_ID
                          FROM SCP_ANL_PRODUCTION_PLAN
                         WHERE DIVISION_ID          IN (SELECT DIVISION_ID
                                                          FROM SCM_MST_DIVISION
                                                         WHERE ATTRIBUTE3  <> 'EE'
                                                           AND DIVISION_ID <> '82')
                           AND PLAN_START_YYYYMMDD  >= FN_GET_BUCKET_YYYYMMDD(-1)
                           AND OPERATION_GROUP       = 'A'
                           AND MEASURE               = 'PROD_PLAN_AMEND'
                       ) IA
                 WHERE B.LOOKUP_TYPE          = 'OPERATION_GROUP'
                   AND B.VALID_YN             = 'Y'
                   AND C.LOOKUP_TYPE          = B.LOOKUP_TYPE
                   AND C.VALID_YN             = 'Y'
                   AND C.SEGMENT1             = 'E'
                   AND IA.DIVISION_ID         = A.DIVISION_ID
                   AND IA.ITEM_ID             = A.MODEL_ID
                   AND A.OPERATION_GROUP_ID   = 'E'
                   AND NOT EXISTS (SELECT 1
                                     FROM SCM_MST_SITE_ITEM_PRIORITY T
                                    WHERE T.DIVISION_ID = A.DIVISION_ID
                                      AND T.ITEM_ID     = A.CHILD_ITEM_ID
                                      AND T.VALID_YN    = 'Y')
                   AND (TRIM(V_OPERATION_GROUP) IS NULL OR A.OPERATION_GROUP_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_OPERATION_GROUP, ','))))
--                 AND (TRIM(V_ITEM_ID) IS NULL OR A.CHILD_ITEM_ID LIKE '%' || V_ITEM_ID || '%')   --  2026.10.07 AJS
                   AND (TRIM(V_ITEM_ID) IS NULL OR A.CHILD_ITEM_ID IN (SELECT XT.COLUMN_VALUE FROM TABLE(V_ITEM_TAB) XT))   --  2026.10.07 AJS
                 UNION ALL
                SELECT IA.PRIORITY_SEQ
                     , IA.DIVISION_ID
                     , IA.PROJECT_CODE
                     , IA.ITEM_ID
                     , IA.SCM_SITE_ID
                     , IA.PLANT_SITE_ID                                         AS PLANT_SITE_ID_B
                     /* ESS 외주 Pakcer Line 생산 Target 적용 */
                     , IA.DIVISION_ID || '   ' || IA.PLANT_SITE_ID || '   ' || IA.SITE_DESCRIPTION
                       || CASE WHEN (IA.TACT_CNT > 0 AND IA.OSP_YN = 'N')
                                 OR (IA.OUT_CAPA_CNT > 0 AND IA.ATTRIBUTE1 IN ('-', 'N'))
                                 OR (IA.OUT_TACT_CNT > 0 AND IA.ATTRIBUTE1 = 'Y')
                               THEN ' Y'
                               ELSE ' N'
                          END                                                   AS PLANT_SITE_ID
                     , CASE WHEN (IA.TACT_CNT > 0 AND IA.OSP_YN = 'N')
                              OR (IA.OUT_CAPA_CNT > 0 AND IA.ATTRIBUTE1 IN ('-', 'N'))
                              OR (IA.OUT_TACT_CNT > 0 AND IA.ATTRIBUTE1 = 'Y')
                            THEN ' Y'
                            ELSE ' N'
                       END                                                      AS TACT_TIME_FLAG
                     , IA.PRIORITY
                     , IA.VALID_YN
                     , IA.ORG_VALID_YN
                     , IA.FROM_YYYYMMDD
                     , IA.TO_YYYYMMDD
                     , IA.CREATED_BY
                     , IA.CREATION_DATE
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                     , IA.OPERATION_GROUP
                     , IA.ORG_FROM_YYYYMMDD
                     , IA.ORG_TO_YYYYMMDD
                     , IA.MERGE_DATE
                     , IA.IS_PASS_N1
                     , IA.IS_PASS_N2
                     , IA.IS_PASS_N3
                     , IA.IS_PASS_N4
                     , IA.IS_PASS_N5
                     , IA.IS_PASS_N6
                     , IA.IS_PASS_N7
                     , IA.NICK_NAME
                     , IA.OPERATION_GROUP_NAME
                     , IA.ACTION_FLAG_DIV
                     , IA.ROW_COLOR_INDEX
                     , IA.SORT_ORDER
                  FROM (SELECT TO_CHAR(A.PRIORITY_SEQ)                          AS PRIORITY_SEQ
                             , A.DIVISION_ID
                             , NVL(NULLIF(A.PROJECT_CODE, '-'), '/')            AS PROJECT_CODE
                             , A.ITEM_ID
                             , NVL(NULLIF(A.SALES_SITE_ID, '-'), '/')           AS SCM_SITE_ID
                             , A.PLANT_SITE_ID
                             , A.PRIORITY
                             , A.VALID_YN
                             , A.VALID_YN                                       AS ORG_VALID_YN
                             /* ★원장에 달력에 없는 날짜가 섞여 있어 바꿀 수 없으면 원래 값을 그대로 보여준다 */
                             , NVL(TO_CHAR(TO_DATE(A.FROM_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.FROM_YYYYMMDD) AS FROM_YYYYMMDD
                             , NVL(TO_CHAR(TO_DATE(A.TO_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.TO_YYYYMMDD)     AS TO_YYYYMMDD
                             , A.CREATED_BY
                             , A.CREATION_DATE
                             , A.LAST_UPDATED_BY
                             , A.LAST_UPDATE_DATE
                             , B.OPERATION_GROUP
                             , A.FROM_YYYYMMDD                                  AS ORG_FROM_YYYYMMDD
                             , A.TO_YYYYMMDD                                    AS ORG_TO_YYYYMMDD
                             , A.FROM_YYYYMMDD || A.TO_YYYYMMDD                 AS MERGE_DATE
                             , ''                                               AS IS_PASS_N1
                             , ''                                               AS IS_PASS_N2
                             , ''                                               AS IS_PASS_N3
                             , ''                                               AS IS_PASS_N4
                             , ''                                               AS IS_PASS_N5
                             , ''                                               AS IS_PASS_N6
                             , ''                                               AS IS_PASS_N7
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)   AS NICK_NAME
                             , D.SEGMENT2                                       AS OPERATION_GROUP_NAME
                             , '-'                                              AS ACTION_FLAG_DIV
                             , 0                                                AS ROW_COLOR_INDEX
                             , 1                                                AS SORT_ORDER
--                             , NVL((SELECT COUNT(X.PLANT_SITE_ID)   --  2026.10.06 AJS
                             , NVL((SELECT /*+ INDEX(Y IX01_SCM_LINE_M) */ COUNT(X.PLANT_SITE_ID)   --  2026.10.06 AJS
                                      FROM SCP_MST_TACT_TIME X
                                         , SCM_MST_LINE_SN Y
                                     WHERE Y.COMPANY_ID    = B.COMPANY_ID
                                       AND Y.DIVISION_ID   = X.DIVISION_ID
                                       AND Y.SITE_ID       = B.SITE_ID
                                       AND Y.PLANT_ID      = B.PLANT_ID
                                       AND Y.OPERATION_ID  = X.OPERATION_ID
                                       AND Y.LINE_ID       = X.LINE_ID
                                       AND Y.ACTIVE_FLAG   = 'Y'
                                       AND X.ITEM_ID       = A.ITEM_ID
                                       AND X.VALID_YN      = 'Y'
                                       AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                                       AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                                     GROUP BY X.ITEM_ID
                                            , X.PLANT_SITE_ID), 0)              AS TACT_CNT
                             , NVL((SELECT COUNT(X.PLANT_SITE_ID)
                                      FROM SCP_MST_OUTSOURCING_CAPA X
                                     WHERE X.ITEM_ID       = A.ITEM_ID
                                       AND X.VALID_YN      = 'Y'
                                       AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                                       AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                                     GROUP BY X.PLANT_SITE_ID
                                            , X.ITEM_ID), 0)                    AS OUT_CAPA_CNT
                             , B.SITE_DESCRIPTION
                             /* ESS 외주 Pakcer Line 생산 Target 적용 */
                             , NVL((SELECT COUNT(X.PLANT_SITE_ID)
                                      FROM SCP_MST_TACT_TIME_OSP X
                                         , SCM_MST_LINE_OSP Y
                                     WHERE Y.DIVISION_ID   = X.DIVISION_ID
                                       AND Y.SCM_SITE_ID   = X.PLANT_SITE_ID
                                       AND Y.LINE_ID       = X.LINE_ID
                                       AND Y.VALID_YN      = 'Y'
                                       AND X.ITEM_ID       = A.ITEM_ID
                                       AND X.VALID_YN      = 'Y'
                                       AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                                       AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                                     GROUP BY X.PLANT_SITE_ID
                                            , X.ITEM_ID), 0)                    AS OUT_TACT_CNT
                             , NVL(B.OSP_YN, 'N')                               AS OSP_YN
                             , NVL(B.ATTRIBUTE1, 'N')                           AS ATTRIBUTE1
                          FROM SCM_MST_SITE_ITEM_PRIORITY A
                             , SCM_MST_SITE B
                             , SCM_ADM_LOOKUP_MASTER C
                             , SCM_ADM_LOOKUP_MASTER_DETAIL D
                         WHERE ((A.DIVISION_ID = B.DIVISION_ID AND B.OPERATION_GROUP <> 'E') OR B.OPERATION_GROUP = 'E')
                           AND A.PLANT_SITE_ID = B.SCM_SITE_ID
                           AND C.LOOKUP_TYPE   = 'OPERATION_GROUP'
                           AND C.VALID_YN      = 'Y'
                           AND D.LOOKUP_TYPE   = C.LOOKUP_TYPE
                           AND D.VALID_YN      = 'Y'
                           AND D.SEGMENT1      = B.OPERATION_GROUP
                           AND B.SITE_TYPE     = 'PLANT'
                           AND (TRIM(V_DIVISION_ID) IS NULL OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                           AND (TRIM(V_PLANT_SITE) IS NULL OR A.PLANT_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE, ','))))
--                         AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID LIKE '%' || V_ITEM_ID || '%')   --  2026.10.07 AJS
                           AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT XT.COLUMN_VALUE FROM TABLE(V_ITEM_TAB) XT))   --  2026.10.07 AJS
                           AND (TRIM(V_OPERATION_GROUP) IS NULL OR B.OPERATION_GROUP IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_OPERATION_GROUP, ','))))
                           AND (TRIM(V_VALID_FLAG) IS NULL OR A.VALID_YN = V_VALID_FLAG)
                       ) IA
               )
         GROUP BY PRIORITY_SEQ
                , DIVISION_ID
                , PROJECT_CODE
                , ITEM_ID
                , SCM_SITE_ID
                , PLANT_SITE_ID_B
                , PLANT_SITE_ID
                , TACT_TIME_FLAG
                , PRIORITY
                , VALID_YN
                , ORG_VALID_YN
                , FROM_YYYYMMDD
                , TO_YYYYMMDD
                , CREATED_BY
                , CREATION_DATE
                , LAST_UPDATED_BY
                , LAST_UPDATE_DATE
                , OPERATION_GROUP
                , ORG_FROM_YYYYMMDD
                , ORG_TO_YYYYMMDD
                , MERGE_DATE
                , IS_PASS_N1
                , IS_PASS_N2
                , IS_PASS_N3
                , IS_PASS_N4
                , IS_PASS_N5
                , IS_PASS_N6
                , IS_PASS_N7
                , NICK_NAME
                , OPERATION_GROUP_NAME
                , ACTION_FLAG_DIV
                , ROW_COLOR_INDEX
                , SORT_ORDER
         ORDER BY SORT_ORDER
                , NLSSORT(DIVISION_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , NLSSORT(ITEM_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , FROM_YYYYMMDD NULLS FIRST
                , PRIORITY NULLS FIRST
                , VALID_YN DESC NULLS LAST
                , TO_YYYYMMDD NULLS FIRST;

    /* 2. 전체조회 */
    OPEN O_ALL_LIST FOR
        SELECT TO_CHAR(A.PRIORITY_SEQ)                                          AS PRIORITY_SEQ
             , A.DIVISION_ID
             , NVL(A.PROJECT_CODE, '/')                                         AS PROJECT_CODE
             , A.ITEM_ID
             , NVL(A.SALES_SITE_ID, '/')                                        AS SCM_SITE_ID
             , A.PLANT_SITE_ID
             , A.PRIORITY
             , A.VALID_YN
             , A.VALID_YN                                                       AS ORG_VALID_YN
             /* ★원장에 달력에 없는 날짜가 섞여 있어 바꿀 수 없으면 원래 값을 그대로 보여준다 */
             , NVL(TO_CHAR(TO_DATE(A.FROM_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.FROM_YYYYMMDD) AS FROM_YYYYMMDD
             , NVL(TO_CHAR(TO_DATE(A.TO_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.TO_YYYYMMDD)     AS TO_YYYYMMDD
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , B.OPERATION_GROUP
             , A.FROM_YYYYMMDD                                                  AS ORG_FROM_YYYYMMDD
             , A.TO_YYYYMMDD                                                    AS ORG_TO_YYYYMMDD
             , A.FROM_YYYYMMDD || A.TO_YYYYMMDD                                 AS MERGE_DATE
             , ''                                                               AS IS_PASS_N1
             , ''                                                               AS IS_PASS_N2
             , ''                                                               AS IS_PASS_N3
             , ''                                                               AS IS_PASS_N4
             , ''                                                               AS IS_PASS_N5
             , ''                                                               AS IS_PASS_N6
             , ''                                                               AS IS_PASS_N7
             , '-'                                                              AS ACTION_FLAG_DIV
             , 0                                                                AS ROW_COLOR_INDEX
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE B
         WHERE ((A.DIVISION_ID = B.DIVISION_ID AND B.OPERATION_GROUP <> 'E') OR B.OPERATION_GROUP = 'E')
           AND A.PLANT_SITE_ID = B.SCM_SITE_ID
           AND B.SITE_TYPE     = 'PLANT'
           AND A.VALID_YN      = 'Y'
           AND (TRIM(V_DIVISION_ID) IS NULL OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
         ORDER BY NLSSORT(A.DIVISION_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , NLSSORT(A.ITEM_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , A.FROM_YYYYMMDD NULLS FIRST
                , A.PRIORITY NULLS FIRST
                , A.VALID_YN DESC NULLS LAST
                , A.TO_YYYYMMDD NULLS FIRST;

    /* 3. 아이템 조회용 */
    OPEN O_ITEM_LIST FOR
        SELECT IA.ITEM_ID
             , IA.NICK_NAME
          FROM (SELECT A.ITEM_ID
                     , A.NICK_NAME
                     , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID, A.NICK_NAME ORDER BY A.NICK_NAME ASC) AS NUMS
                  FROM SCP_MST_FINAL_ITEM A
                 WHERE A.OPERATION_GROUP = 'E'
                 GROUP BY A.ITEM_ID
                        , A.NICK_NAME
               ) IA
         WHERE IA.NUMS = 1
         /* AS-IS 에는 정렬이 없어 화면에서 순서가 흔들린다 — 품목 순으로 고정한다 */
         ORDER BY NLSSORT(IA.ITEM_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST;

    O_RESULT_CODE := '0';
    O_RESULT_MSG  := 'SUCCESS';

END P_SCP0027_GET_PROJECTROUTE_ELECTRODE;

/****************************************************************************************************/
/* Program ID  : P_SCP0027_SAVE_PROJECTROUTE_ELECTRODE                                              */
/* Description : Project Route Plant Site 등록,수정                                                 */
/****************************************************************************************************/
PROCEDURE P_SCP0027_SAVE_PROJECTROUTE_ELECTRODE
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_PRIORITY_SEQ      IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_PROJECT_CODE      IN  CLOB
  , P_SCM_SITE_ID       IN  CLOB
  , P_PLANT_SITE_ID     IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_CREATED_BY        IN  CLOB
  , P_CREATION_DATE     IN  CLOB
  , P_LAST_UPDATED_BY   IN  CLOB
  , P_PRIORITY          IN  CLOB
  , P_FROM_YYYYMMDD     IN  CLOB
  , P_TO_YYYYMMDD       IN  CLOB
  , P_VALID_YN          IN  CLOB
  , P_DEBUG_MODE        IN  VARCHAR2 DEFAULT 'F'
  , O_RESULT_CODE       OUT VARCHAR2
  , O_RESULT_CNT        OUT NUMBER
  , O_RESULT_MSG        OUT VARCHAR2
)
IS
    C_DELIM                 CONSTANT VARCHAR2(1 CHAR) := '^';
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCP0027_SAVE_PROJECTROUTE_ELECTRODE';

    T_ACTIVE_FLAG           T_TOK;
    T_PRIORITY_SEQ          T_TOK;
    T_DIVISION_ID           T_TOK;
    T_PROJECT_CODE          T_TOK;
    T_SCM_SITE_ID           T_TOK;
    T_PLANT_SITE_ID         T_TOK;
    T_ITEM_ID               T_TOK;
    T_CREATED_BY            T_TOK;
    T_CREATION_DATE         T_TOK;
    T_LAST_UPDATED_BY       T_TOK;
    T_PRIORITY              T_TOK;
    T_FROM_YYYYMMDD         T_TOK;
    T_TO_YYYYMMDD           T_TOK;
    T_VALID_YN              T_TOK;

    V_LOOP_CNT              PLS_INTEGER := 0;
    V_DUMMY_CNT             PLS_INTEGER := 0;

    V_ACTIVE_FLAG           VARCHAR2(4000 CHAR);
    V_PRIORITY_SEQ          VARCHAR2(4000 CHAR);
    V_DIVISION_ID           VARCHAR2(4000 CHAR);
    V_PROJECT_CODE          VARCHAR2(4000 CHAR);
    V_SCM_SITE_ID           VARCHAR2(4000 CHAR);
    V_PLANT_SITE_ID         VARCHAR2(4000 CHAR);
    V_ITEM_ID               VARCHAR2(4000 CHAR);
    V_S_VALID_YN            VARCHAR2(4000 CHAR);
    V_CREATED_BY            VARCHAR2(4000 CHAR);
    V_CREATION_DATE         DATE;
    V_LAST_UPDATED_BY       VARCHAR2(4000 CHAR);
    V_PRIORITY              VARCHAR2(4000 CHAR);
    V_FROM_YYYYMMDD         VARCHAR2(4000 CHAR);
    V_TO_YYYYMMDD           VARCHAR2(4000 CHAR);
    V_VALID_YN              VARCHAR2(4000 CHAR);

    V_CURRENCY              VARCHAR2(4000 CHAR) := NULL;
    V_LIABILITY_PERIOD      VARCHAR2(4000 CHAR) := NULL;
    V_SALES_PLAN_ADJUST_YN  VARCHAR2(4000 CHAR) := NULL;
    V_ITEM_HRCY_ID          VARCHAR2(4000 CHAR) := NULL;
    V_BPMS_EXIST            VARCHAR2(1 CHAR)    := 'Y';

    /* 2025/10/24 kimcd [PJ2025F254] JV법인 ESS 혼용 생산 시스템 개선 */
    V_LINK_PLANT_SITE_ID    VARCHAR2(4000 CHAR);
    V_LINK_DIVISION_ID      VARCHAR2(4000 CHAR);
    V_LINK_CP_PRIORITY_SEQ  NUMBER(19);

    V_CNT                   PLS_INTEGER;
    V_SQLERRM               VARCHAR2(4000 CHAR);
    V_SQLCODE               NUMBER;

BEGIN

    /* 시작 LOG */
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', NULL, SYSDATE);

    /* 각 컬럼들에 대한 스플릿처리 */
    P_SPLIT_TOKEN(P_ACTIVE_FLAG     , C_DELIM, T_ACTIVE_FLAG     , V_LOOP_CNT);     /* 프로시저 LOOP 길이를 판단 */
    P_SPLIT_TOKEN(P_PRIORITY_SEQ    , C_DELIM, T_PRIORITY_SEQ    , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_DIVISION_ID     , C_DELIM, T_DIVISION_ID     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PROJECT_CODE    , C_DELIM, T_PROJECT_CODE    , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_SCM_SITE_ID     , C_DELIM, T_SCM_SITE_ID     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PLANT_SITE_ID   , C_DELIM, T_PLANT_SITE_ID   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_ITEM_ID         , C_DELIM, T_ITEM_ID         , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_CREATED_BY      , C_DELIM, T_CREATED_BY      , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_CREATION_DATE   , C_DELIM, T_CREATION_DATE   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_LAST_UPDATED_BY , C_DELIM, T_LAST_UPDATED_BY , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PRIORITY        , C_DELIM, T_PRIORITY        , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_FROM_YYYYMMDD   , C_DELIM, T_FROM_YYYYMMDD   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_TO_YYYYMMDD     , C_DELIM, T_TO_YYYYMMDD     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_VALID_YN        , C_DELIM, T_VALID_YN        , V_DUMMY_CNT);

    FOR I IN 1 .. V_LOOP_CNT
    LOOP

        V_PRIORITY_SEQ := F_TOKEN(T_PRIORITY_SEQ, I);

        IF V_PRIORITY_SEQ IS NULL
        THEN
            V_PRIORITY_SEQ := TO_CHAR(SEQ1_SCM_MST_SITE_ITEM_PRIORITY.NEXTVAL);
        END IF;

        V_ACTIVE_FLAG     := F_TOKEN(T_ACTIVE_FLAG, I);
        V_DIVISION_ID     := F_TOKEN(T_DIVISION_ID, I);
        V_PROJECT_CODE    := F_TOKEN(T_PROJECT_CODE, I);
        V_SCM_SITE_ID     := F_TOKEN(T_SCM_SITE_ID, I);
        V_PLANT_SITE_ID   := F_TOKEN(T_PLANT_SITE_ID, I);
        V_ITEM_ID         := F_TOKEN(T_ITEM_ID, I);
        V_CREATED_BY      := F_TOKEN(T_CREATED_BY, I);
        V_CREATION_DATE   := F_TO_DATETIME(F_TOKEN(T_CREATION_DATE, I));
        V_LAST_UPDATED_BY := F_TOKEN(T_LAST_UPDATED_BY, I);
        V_PRIORITY        := F_TOKEN(T_PRIORITY, I);
        V_FROM_YYYYMMDD   := F_TOKEN(T_FROM_YYYYMMDD, I);
        V_TO_YYYYMMDD     := F_TOKEN(T_TO_YYYYMMDD, I);
        V_VALID_YN        := F_TOKEN(T_VALID_YN, I);

        BEGIN
            SELECT VALID_YN
              INTO V_S_VALID_YN
              FROM SCM_MST_SITE_ITEM
             WHERE DIVISION_ID  = V_DIVISION_ID
               AND SCM_SITE_ID  = V_SCM_SITE_ID
               AND ITEM_ID      = V_ITEM_ID
               AND PROJECT_CODE = V_PROJECT_CODE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_S_VALID_YN := NULL;
            WHEN TOO_MANY_ROWS THEN V_S_VALID_YN := NULL;
        END;

        /* 이력저장 */
        PR_SCM_MST_SITE_ITEM_HIST(V_DIVISION_ID, V_PROJECT_CODE, V_PLANT_SITE_ID, V_ITEM_ID
                                , V_CURRENCY, V_LIABILITY_PERIOD, V_SALES_PLAN_ADJUST_YN, V_ITEM_HRCY_ID
                                , V_S_VALID_YN, V_BPMS_EXIST, V_CREATED_BY, TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

        PR_SCM_MST_SITE_ITEM_PRIORITY_HIST(V_PRIORITY_SEQ, V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID
                                         , V_PLANT_SITE_ID, V_ITEM_ID, V_PRIORITY, V_FROM_YYYYMMDD
                                         , V_TO_YYYYMMDD, V_VALID_YN, V_CREATED_BY
                                         , TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

        /* 데이터 저장 — AS-IS MERGE 를 조회 후 수정 · 넣기로 나눈다 (온라인 SQL 은 MERGE 금지) */
        UPDATE SCM_MST_SITE_ITEM
           SET LAST_UPDATED_BY   = V_LAST_UPDATED_BY
             , LAST_UPDATE_DATE  = SYSDATE
         WHERE DIVISION_ID  = V_DIVISION_ID
           AND PROJECT_CODE = V_PROJECT_CODE
           AND SCM_SITE_ID  = V_PLANT_SITE_ID
           AND ITEM_ID      = V_ITEM_ID;

        IF SQL%ROWCOUNT = 0
        THEN
            INSERT INTO SCM_MST_SITE_ITEM
                        (
                          DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                        , CURRENCY, LIABILITY_PERIOD, SALES_PLAN_ADJUST_YN, ITEM_HRCY_ID
                        , VALID_YN, BPMS_EXIST
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        )
            VALUES      (
                          V_DIVISION_ID, V_PROJECT_CODE, V_PLANT_SITE_ID, V_ITEM_ID
                        , NULL, NULL, NULL, NULL
                        , 'Y', 'Y'
                        , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                        );
        END IF;

        /* SCM_MST_SITE_ITEM_PRIORITY 입력/수정 */
        IF V_ACTIVE_FLAG = 'M'
        THEN
            UPDATE SCM_MST_SITE_ITEM_PRIORITY
               SET SALES_SITE_ID     = V_SCM_SITE_ID
                 , PLANT_SITE_ID     = V_PLANT_SITE_ID
                 , PRIORITY          = V_PRIORITY
                 , FROM_YYYYMMDD     = V_FROM_YYYYMMDD
                 , TO_YYYYMMDD       = V_TO_YYYYMMDD
                 , VALID_YN          = V_VALID_YN
                 , LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE  = SYSDATE
             WHERE PRIORITY_SEQ = TO_NUMBER(V_PRIORITY_SEQ);

        ELSIF V_ACTIVE_FLAG = 'I'
        THEN
            INSERT INTO SCM_MST_SITE_ITEM_PRIORITY
                        (
                          PRIORITY_SEQ, DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID
                        , PRIORITY, FROM_YYYYMMDD, TO_YYYYMMDD, VALID_YN
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        )
            VALUES      (
                          TO_NUMBER(V_PRIORITY_SEQ), V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_PLANT_SITE_ID, V_ITEM_ID
                        , V_PRIORITY, V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_VALID_YN
                        , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                        );
        END IF;

        /* 2025/10/31 kimcd [PJ2025F254] JV법인 ESS 혼용 생산 시스템 개선 — JV 동기화 시작 */
        V_LINK_PLANT_SITE_ID   := NULL;
        V_LINK_DIVISION_ID     := NULL;
        V_LINK_CP_PRIORITY_SEQ := NULL;

        BEGIN
            SELECT DIVISION_ID
                 , SCM_SITE_ID
              INTO V_LINK_DIVISION_ID
                 , V_LINK_PLANT_SITE_ID
              FROM (SELECT B.DIVISION_ID
                         , B.SCM_SITE_ID
                      FROM SCM_MST_SITE A
                         , SCM_MST_SITE B
                     WHERE B.SCM_SITE_ID = A.ATTRIBUTE9
                       AND A.SCM_SITE_ID = V_PLANT_SITE_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                   )
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_LINK_DIVISION_ID   := NULL;
                V_LINK_PLANT_SITE_ID := NULL;
        END;

        IF V_LINK_DIVISION_ID IS NOT NULL AND V_LINK_PLANT_SITE_ID IS NOT NULL
        THEN
            UPDATE SCM_MST_SITE_ITEM
               SET LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE  = SYSDATE
             WHERE DIVISION_ID  = V_LINK_DIVISION_ID
               AND PROJECT_CODE = V_PROJECT_CODE
               AND SCM_SITE_ID  = V_LINK_PLANT_SITE_ID
               AND ITEM_ID      = V_ITEM_ID;

            IF SQL%ROWCOUNT = 0
            THEN
                INSERT INTO SCM_MST_SITE_ITEM
                            (
                              DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                            , CURRENCY, LIABILITY_PERIOD, SALES_PLAN_ADJUST_YN, ITEM_HRCY_ID
                            , VALID_YN, BPMS_EXIST
                            , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                            )
                VALUES      (
                              V_LINK_DIVISION_ID, V_PROJECT_CODE, V_LINK_PLANT_SITE_ID, V_ITEM_ID
                            , NULL, NULL, NULL, NULL
                            , 'Y', 'Y'
                            , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                            );
            END IF;

            /* SCM_MST_SITE_ITEM_PRIORITY 입력/수정 */
            BEGIN
                SELECT PRIORITY_SEQ
                  INTO V_LINK_CP_PRIORITY_SEQ
                  FROM (SELECT PRIORITY_SEQ
                          FROM SCM_MST_SITE_ITEM_PRIORITY
                         WHERE DIVISION_ID    = V_LINK_DIVISION_ID
                           AND PROJECT_CODE   = V_PROJECT_CODE
                           AND SALES_SITE_ID  = V_SCM_SITE_ID
                           AND PLANT_SITE_ID  = V_LINK_PLANT_SITE_ID
                           AND ITEM_ID        = V_ITEM_ID
                           AND FROM_YYYYMMDD <= V_TO_YYYYMMDD
                           AND TO_YYYYMMDD   >= V_FROM_YYYYMMDD
                       )
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN V_LINK_CP_PRIORITY_SEQ := NULL;
            END;

            IF V_LINK_CP_PRIORITY_SEQ IS NOT NULL
            THEN
                UPDATE SCM_MST_SITE_ITEM_PRIORITY
                   SET SALES_SITE_ID     = V_SCM_SITE_ID
                     , PRIORITY          = V_PRIORITY
                     , FROM_YYYYMMDD     = V_FROM_YYYYMMDD
                     , TO_YYYYMMDD       = V_TO_YYYYMMDD
                     , VALID_YN          = V_VALID_YN
                     , LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                     , LAST_UPDATE_DATE  = SYSDATE
                 WHERE PRIORITY_SEQ = V_LINK_CP_PRIORITY_SEQ;
            ELSE
                V_LINK_CP_PRIORITY_SEQ := SEQ1_SCM_MST_SITE_ITEM_PRIORITY.NEXTVAL;

                INSERT INTO SCM_MST_SITE_ITEM_PRIORITY
                            (
                              PRIORITY_SEQ, DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID
                            , PRIORITY, FROM_YYYYMMDD, TO_YYYYMMDD, VALID_YN
                            , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                            )
                VALUES      (
                              V_LINK_CP_PRIORITY_SEQ, V_LINK_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_LINK_PLANT_SITE_ID, V_ITEM_ID
                            , V_PRIORITY, V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_VALID_YN
                            , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                            );
            END IF;

            PR_SCM_MST_SITE_ITEM_HIST(V_LINK_DIVISION_ID, V_PROJECT_CODE, V_LINK_PLANT_SITE_ID, V_ITEM_ID
                                    , V_CURRENCY, V_LIABILITY_PERIOD, V_SALES_PLAN_ADJUST_YN, V_ITEM_HRCY_ID
                                    , V_S_VALID_YN, V_BPMS_EXIST, V_CREATED_BY, TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

            PR_SCM_MST_SITE_ITEM_PRIORITY_HIST(TO_CHAR(V_LINK_CP_PRIORITY_SEQ), V_LINK_DIVISION_ID, V_PROJECT_CODE
                                             , V_SCM_SITE_ID, V_LINK_PLANT_SITE_ID, V_ITEM_ID, V_PRIORITY
                                             , V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_VALID_YN
                                             , V_CREATED_BY, TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

        END IF;
        /* JV 동기화 끝 */

    END LOOP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', NULL, SYSDATE);

    COMMIT;

    /* 결과코드, 결과 카운트 반환 */
    O_RESULT_CODE := 'S';
    O_RESULT_CNT  := V_LOOP_CNT;
    O_RESULT_MSG  := NULL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLCODE := SQLCODE;
        V_SQLERRM := SQLERRM;

        ROLLBACK;                                                               /* 입력 데이타 롤백 처리 */

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
        VALUES      (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );
        COMMIT;

        /* error코드, errror 메시지 반환 */
        O_RESULT_CODE := 'F';
        O_RESULT_CNT  := 0;
        O_RESULT_MSG  := '[' || V_SQLCODE || ']' || V_SQLERRM;

END P_SCP0027_SAVE_PROJECTROUTE_ELECTRODE;

END PKG_SCP0027;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0027
-- ##### END PACKAGE BODY PKG_SCP0027

-- ##### START PACKAGE BODY PKG_SCP0030
CREATE OR REPLACE PACKAGE BODY PKG_SCP0030
IS

    /* =========================================================================================
     * 쉼표 목록 분리 (AS-IS dbo.String_Split : 토큰 앞뒤 공백 제거, 빈 토큰 유지)
     *   P_KEEP_EMPTY = 'Y' : 빈 토큰도 원소로 남김(NULL). 입력이 NULL 이면 빈 토큰 1개
     *   P_KEEP_EMPTY = 'N' : 빈 토큰 제외 (IN 목록 비교용 — 빈 문자열과 같은 값이 원장에 없음)
     *   대소문자 무시 비교(AS-IS 정렬 규칙 Latin1_General_CI_AS)를 위해 대문자로 반환
     * ========================================================================================= */
    FUNCTION F_SPLIT_LIST
    (
        P_STR         IN VARCHAR2
      , P_KEEP_EMPTY  IN VARCHAR2
    )
    RETURN T_STR_TAB
    IS
        V_TAB    T_STR_TAB := T_STR_TAB();
        V_POS    PLS_INTEGER := 1;
        V_IDX    PLS_INTEGER;
        V_TOKEN  VARCHAR2(4000);
    BEGIN
        IF P_STR IS NULL THEN
            IF P_KEEP_EMPTY = 'Y' THEN
                V_TAB.EXTEND;
                V_TAB(V_TAB.COUNT) := NULL;
            END IF;
            RETURN V_TAB;
        END IF;

        LOOP
            V_IDX := INSTR(P_STR, ',', V_POS);
            IF V_IDX = 0 THEN
                V_TOKEN := SUBSTR(P_STR, V_POS);
            ELSE
                V_TOKEN := SUBSTR(P_STR, V_POS, V_IDX - V_POS);
            END IF;
            V_TOKEN := UPPER(TRIM(V_TOKEN));

            IF V_TOKEN IS NOT NULL OR P_KEEP_EMPTY = 'Y' THEN
                V_TAB.EXTEND;
                V_TAB(V_TAB.COUNT) := V_TOKEN;
            END IF;

            EXIT WHEN V_IDX = 0;
            V_POS := V_IDX + 1;
        END LOOP;

        RETURN V_TAB;
    END F_SPLIT_LIST;

    /* =========================================================================================
     * 목록 조건 사용 여부 : AS-IS IF NOT(@p IS NULL OR @p = '') — 공백만 입력도 조건 없음
     *   화면 전체 선택값 'ALL' 도 조건 없음 (AS-IS 화면은 전체 선택 시 목록 전체 코드를 전달)
     * ========================================================================================= */
    FUNCTION F_USE_LIST
    (
        P_STR  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF TRIM(P_STR) IS NULL OR UPPER(TRIM(P_STR)) = 'ALL' THEN
            RETURN 'N';
        END IF;
        RETURN 'Y';
    END F_USE_LIST;

    /* =========================================================================================
     * 저장 날짜 값 정리 : AS-IS 화면이 그리드 날짜를 Replace("-","").Substring(0,8) 로 보냄
     *   조회 결과(DATE)가 문자열로 되돌아오는 형식(YYYY-MM-DD …)과 YYYYMMDD 를 모두 받음
     * ========================================================================================= */
    FUNCTION F_TO_YYYYMMDD
    (
        P_VAL  IN VARCHAR2
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF REGEXP_LIKE(P_VAL, '^[0-9]{4}-[0-9]{2}-[0-9]{2}') THEN
            RETURN SUBSTR(REPLACE(P_VAL, '-', ''), 1, 8);
        END IF;
        RETURN P_VAL;
    END F_TO_YYYYMMDD;

    /* =========================================================================================
     * 정수 칸 형변환 : AS-IS nvarchar → int 암묵 변환 (빈 문자열 = 0, 정수 형식 아니면 오류)
     * ========================================================================================= */
    FUNCTION F_TO_INT
    (
        P_VAL  IN VARCHAR2
    )
    RETURN NUMBER
    IS
    BEGIN
        IF P_VAL IS NULL THEN
            RETURN 0;
        END IF;
        IF NOT REGEXP_LIKE(P_VAL, '^[+-]?[0-9]+$') THEN
            RAISE_APPLICATION_ERROR(-20245, 'Conversion failed when converting the nvarchar value ''' || P_VAL || ''' to data type int.');
        END IF;
        RETURN TO_NUMBER(P_VAL);
    END F_TO_INT;

    /* =========================================================================================
     * 소수 칸 형변환 : AS-IS nvarchar → numeric 암묵 변환 (빈 문자열·숫자 형식 아니면 오류)
     *   P_EXISTS = 'N' (값 자체가 없음) 이면 NULL — AS-IS SCM_ARR_SPL_VAL 토큰 부족과 같음
     * ========================================================================================= */
    FUNCTION F_TO_DEC
    (
        P_VAL     IN VARCHAR2
      , P_EXISTS  IN VARCHAR2
    )
    RETURN NUMBER
    IS
    BEGIN
        IF P_EXISTS = 'N' THEN
            RETURN NULL;
        END IF;
        IF P_VAL IS NULL OR NOT REGEXP_LIKE(P_VAL, '^[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)$') THEN
            RAISE_APPLICATION_ERROR(-20814, 'Error converting data type nvarchar to numeric.');
        END IF;
        RETURN TO_NUMBER(P_VAL);
    END F_TO_DEC;

    /* =========================================================================================
     * BOD ITEM 이력 적재 (AS-IS PR_SCP_MST_BOD_ITEM_HIST — SCP0030 저장 전용, 패키지 내부 흡수)
     * ========================================================================================= */
    PROCEDURE P_SCP_MST_BOD_ITEM_HIST
    (
        P_SEQ               IN NUMBER
      , P_BOD_ID            IN VARCHAR2
      , P_DIVISION_ID       IN VARCHAR2
      , P_ITEM_ID           IN VARCHAR2
      , P_PRIORITY          IN NUMBER
      , P_FROM_YYYYMMDD     IN VARCHAR2
      , P_TO_YYYYMMDD       IN VARCHAR2
      , P_SAFETY_STOCK      IN NUMBER
      , P_VALID_YN          IN VARCHAR2
      , P_CREATED_BY        IN VARCHAR2
      , P_CREATION_DATE     IN DATE
      , P_LAST_UPDATED_BY   IN VARCHAR2
      , P_LAST_UPDATE_DATE  IN DATE
    )
    IS
    BEGIN
        INSERT
          INTO SCP_MST_BOD_ITEM_H
             ( HISTORY_SEQ
             , SEQ
             , DIVISION_ID
             , BOD_ID
             , ITEM_ID
             , PRIORITY
             , FROM_YYYYMMDD
             , TO_YYYYMMDD
             , SAFETY_STOCK
             , VALID_YN
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , HISTORY_CREATION_DATE
             )
        VALUES
             ( SEQ1_SCP_MST_BOD_ITEM_H.NEXTVAL
             , P_SEQ
             , P_DIVISION_ID
             , P_BOD_ID
             , P_ITEM_ID
             , P_PRIORITY
             , P_FROM_YYYYMMDD
             , P_TO_YYYYMMDD
             , P_SAFETY_STOCK
             , P_VALID_YN
             , P_CREATED_BY
             , P_CREATION_DATE
             , P_LAST_UPDATED_BY
             , P_LAST_UPDATE_DATE
             , SYSDATE
             );
    END P_SCP_MST_BOD_ITEM_HIST;

    /* =========================================================================================
     * BOD ITEM 조회 (AS-IS SCP0030_GET_BOD_ITEM)
     *   AS-IS 동적 SQL(조건별 문자열 조립) → 조건 사용 여부 변수로 정적 SQL
     *   AS-IS #TblDynamicPivot_SCP0030_Inactive(dbo.FN_GET_SCP_ITEM_INACTIVE) →
     *     조회 사업부의 (사업부, 품목) 중 ACTIVE_FLAG 가 N 만 있는 품목을 NOT EXISTS 로 제외
     *     2026.10.06 AJS NOT EXISTS → 외부조인 + IS NULL 로 변경(품목마다 반복 조회 제거, 결과 동일)
     *     (AS-IS 함수는 품목 인자를 쓰지 않음 · 사업부 인자가 비면 제외 대상 없음)
     *   사이트 키 비교는 대문자로(AS-IS 대소문자 무시 — 대소문자만 다른 사이트 ID 3쌍 존재)
     * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
     * ========================================================================================= */
    PROCEDURE P_SCP0030_GET_BOD_ITEM
    (
        P_DIVISION_ID     IN  VARCHAR2
      , P_FROM_SITE       IN  VARCHAR2
      , P_TO_SITE         IN  VARCHAR2
      , P_INCOTERMS       IN  VARCHAR2
      , P_TRANS_MODE      IN  VARCHAR2
      , P_ITEM_ID         IN  VARCHAR2
      , P_NICK_NAME       IN  VARCHAR2
      , P_VALID           IN  VARCHAR2
      , P_USER_ID         IN  VARCHAR2
      , P_MENU_ID         IN  VARCHAR2
      , O_RC1             OUT SYS_REFCURSOR
      , O_RESULT_CURSOR   OUT SYS_REFCURSOR
    )
    IS
        V_DIV_USE      VARCHAR2(1)   := F_USE_LIST(P_DIVISION_ID);
        V_FROM_USE     VARCHAR2(1)   := F_USE_LIST(P_FROM_SITE);
        V_TO_USE       VARCHAR2(1)   := F_USE_LIST(P_TO_SITE);
        V_INCO_USE     VARCHAR2(1)   := F_USE_LIST(P_INCOTERMS);
        V_TRANS_USE    VARCHAR2(1)   := F_USE_LIST(P_TRANS_MODE);
        V_ITEM_USE     VARCHAR2(1)   := F_USE_LIST(P_ITEM_ID);
        V_DIV_TAB      T_STR_TAB     := F_SPLIT_LIST(P_DIVISION_ID, 'N');
        V_FROM_TAB     T_STR_TAB     := F_SPLIT_LIST(P_FROM_SITE, 'N');
        V_TO_TAB       T_STR_TAB     := F_SPLIT_LIST(P_TO_SITE, 'N');
        V_INCO_TAB     T_STR_TAB     := F_SPLIT_LIST(P_INCOTERMS, 'N');
        V_TRANS_TAB    T_STR_TAB     := F_SPLIT_LIST(P_TRANS_MODE, 'N');
        V_ITEM_TAB     T_STR_TAB     := F_SPLIT_LIST(P_ITEM_ID, 'N');
        V_EXC_MODE     VARCHAR2(1);
        V_VALID        VARCHAR2(4 CHAR);
        V_NICK_NAME    VARCHAR2(4000);
    BEGIN
        /* 비활성 품목 제외 범위 : N = 없음(사업부 미입력) · A = 전체 사업부('ALL') · L = 입력 사업부 */
        V_EXC_MODE := CASE WHEN TRIM(P_DIVISION_ID) IS NULL THEN 'N'
                           WHEN UPPER(TRIM(P_DIVISION_ID)) = 'ALL' THEN 'A'
                           ELSE 'L'
                      END;

        /* AS-IS @p_valid NVARCHAR(1) — 첫 글자만 비교 */
        V_VALID := CASE WHEN UPPER(TRIM(P_VALID)) = 'ALL' THEN NULL
                        ELSE UPPER(TRIM(SUBSTR(P_VALID, 1, 1)))
                   END;

        /* AS-IS LIKE '%' + @p_nick_name + '%' (공백만 입력이면 조건 없음) */
        V_NICK_NAME := CASE WHEN TRIM(P_NICK_NAME) IS NULL
                              OR UPPER(TRIM(P_NICK_NAME)) = 'ALL' THEN NULL   /* 조회조건 ALL 은 조건 없음 */
                            ELSE UPPER(P_NICK_NAME)
                       END;

        OPEN O_RC1 FOR
        SELECT IA.SEQ
             , IA.DIVISION_ID
             , IA.CUSTOMER
             , IA.FROM_SITE_CODE
             , IA.FROM_CITY
             , IA.TO_SITE_CODE
             , IA.TO_CITY
             , IA.INCOTERMS
             , IA.SAFETY_STOCK
             , IA.TRANSPORT_MODE
             , IA.ITEM_ID
             , IA.NICK_NAME
             , IA.FROM_YYYYMMDD
             , IA.TO_YYYYMMDD
             , IA.PRIORITY
             , IA.BOD_ITEM_VALID
             , IA.BOD_VALID
             , IA.ROUTE_VALID
             , IA.ROUTE_ID
             , IA.DAYS_MON
             , IA.DAYS_TUE
             , IA.DAYS_WED
             , IA.DAYS_THU
             , IA.DAYS_FRI
             , IA.DAYS_SAT
             , IA.DAYS_SUN
             , IA.LEAD_TIME
             , IA.CREATED_BY
             , IA.CREATION_DATE
             , IA.LAST_UPDATED_BY
             , IA.LAST_UPDATE_DATE
             , IA.BOD_ID
             , IA.ORG_FROM_YYYYMMDD
             , IA.ORG_TO_YYYYMMDD
             , IA.MERGE_DATE
             , CAST(NULL AS VARCHAR2(1000 CHAR)) AS Y          /* AS-IS W.ACTIVE_FLAG — 제외 조건상 항상 NULL */
             , IA.COMPANY_ID
          FROM (SELECT DISTINCT
                       A.SEQ
                     , A.DIVISION_ID
                     , NVL(D.END_CUSTOMER, '-') AS CUSTOMER
                     , B.FROM_SITE AS FROM_SITE_CODE
                     , XB.COMPANY_ID
                     , E.CITY AS FROM_CITY
                     , B.TO_SITE AS TO_SITE_CODE
                     , XA.CITY AS TO_CITY
                     , B.INCOTERMS
                     , A.SAFETY_STOCK
                     , C.TRANSPORT_MODE
                     , A.ITEM_ID
                     , NVL(XC.NICK_NAME, '-') AS NICK_NAME
                     , TO_DATE(A.FROM_YYYYMMDD, 'YYYYMMDD') AS FROM_YYYYMMDD
                     , TO_DATE(A.TO_YYYYMMDD, 'YYYYMMDD') AS TO_YYYYMMDD
                     , A.PRIORITY
                     , A.VALID_YN AS BOD_ITEM_VALID
                     , B.VALID_YN AS BOD_VALID
                     , C.VALID_YN AS ROUTE_VALID
                     , C.ROUTE_ID
                     , C.DAYS_MON
                     , C.DAYS_TUE
                     , C.DAYS_WED
                     , C.DAYS_THU
                     , C.DAYS_FRI
                     , C.DAYS_SAT
                     , C.DAYS_SUN
                     , XD.LT_TOTAL AS LEAD_TIME
                    -- 2025.04.07 kimcd PJ20249548R  LGES SCP역량 강화를 위한 기준정보PSI엔진 기능개선 - LEAD TIME 조회 안 되어서 SCP_MST_BOD_V를 SCP_MST_BOD_N_V 로 변경
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , A.LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                     , B.BOD_ID
                     , A.FROM_YYYYMMDD AS ORG_FROM_YYYYMMDD
                     , A.TO_YYYYMMDD AS ORG_TO_YYYYMMDD
                     , A.FROM_YYYYMMDD || A.TO_YYYYMMDD AS MERGE_DATE
                  FROM SCP_MST_BOD_ITEM A
                     , SCP_MST_BOD B
                     , SCP_MST_DISTRIBUTION_ROUTE C
                     , SCM_MST_SITE D                                  /* 고객 : 품목 사업부 + 도착 사이트 */
                     , SCM_MST_SITE E                                  /* 출발 도시 : 품목 사업부 + 출발 사이트 */
                     , (SELECT DISTINCT
                               UPPER(SCM_SITE_ID) AS SITE_KEY
                             , CITY
                          FROM SCM_MST_SITE
                       ) XA                                            /* 도착 도시 */
                     , (SELECT UPPER(SCM_SITE_ID) AS SITE_KEY
                             , MAX(COMPANY_ID) AS COMPANY_ID
                          FROM SCM_MST_SITE
                         GROUP BY UPPER(SCM_SITE_ID)
                       ) XB                                            /* 출발 사이트 법인 */
                     , (SELECT ITEM_ID
                             , MAX(NICK_NAME) AS NICK_NAME
                          FROM SCM_MST_ITEM_SN
                         WHERE NICK_NAME IS NOT NULL
                         GROUP BY ITEM_ID
                       ) XC                                            /* 품목 별칭 (품목별 별칭 1종) */
                     , (SELECT DIVISION_ID
                             , BOD_ID
                             , LT_TOTAL
                             , ROWNUM AS RN
                          FROM SCP_MST_BOD_N_V
                       ) XD                                            /* 리드타임 (사업부 + BOD 유일) — 행마다 뷰 재계산 방지(ROWNUM) */
                 WHERE A.BOD_ID = B.BOD_ID
                   AND B.ROUTE_ID = C.ROUTE_ID(+)
                   AND A.DIVISION_ID = D.DIVISION_ID(+)
                   AND UPPER(B.TO_SITE) = UPPER(D.SCM_SITE_ID(+))
                   AND A.DIVISION_ID = E.DIVISION_ID(+)
                   AND UPPER(B.FROM_SITE) = UPPER(E.SCM_SITE_ID(+))
                   AND UPPER(B.TO_SITE) = XA.SITE_KEY(+)
                   AND UPPER(B.FROM_SITE) = XB.SITE_KEY(+)
                   AND A.ITEM_ID = XC.ITEM_ID(+)
                   AND B.DIVISION_ID = XD.DIVISION_ID(+)
                   AND B.BOD_ID = XD.BOD_ID(+)
                   AND (V_DIV_USE = 'N' OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_DIV_TAB)))
                   AND (V_FROM_USE = 'N' OR UPPER(B.FROM_SITE) IN (SELECT COLUMN_VALUE FROM TABLE(V_FROM_TAB)))
                   AND (V_TO_USE = 'N' OR UPPER(B.TO_SITE) IN (SELECT COLUMN_VALUE FROM TABLE(V_TO_TAB)))
                   AND (V_INCO_USE = 'N' OR UPPER(B.INCOTERMS) IN (SELECT COLUMN_VALUE FROM TABLE(V_INCO_TAB)))
                   AND (V_TRANS_USE = 'N' OR UPPER(C.TRANSPORT_MODE) IN (SELECT COLUMN_VALUE FROM TABLE(V_TRANS_TAB)))
                   /* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                 AND (V_ITEM_USE = 'N' OR UPPER(A.ITEM_ID) IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                   AND (V_ITEM_USE = 'N'
                        OR EXISTS (SELECT 1
                                     FROM TABLE(V_ITEM_TAB) SA
                                    WHERE UPPER(A.ITEM_ID)   LIKE '%' || SA.COLUMN_VALUE || '%'
                                       OR UPPER(XC.NICK_NAME) LIKE '%' || SA.COLUMN_VALUE || '%'))
                   /* 2026.10.07 AJS Model/Nickname 검색 (END) */
                   AND (V_VALID IS NULL OR UPPER(A.VALID_YN) = V_VALID)
               ) IA
         /* 2026.10.06 AJS 비활성 품목 제외 성능 개선 (START) : 품목마다 반복하던 NOT EXISTS → AS-IS 와 같은 외부조인 + IS NULL (결과 동일) */
--         WHERE NOT EXISTS (SELECT 1
--                             FROM (SELECT SA.DIVISION_ID
--                                        , SA.ITEM_ID
--                                     FROM SCM_MST_ITEM_SN SA
--                                        , SCM_MST_ITEM_CLASS_SN SB
--                                    WHERE SA.ITEM_CLASS = SB.CLASS_ID
--                                      AND SB.USE_FLAG = 'Y'
--                                      AND V_EXC_MODE <> 'N'
--                                      AND (V_EXC_MODE = 'A' OR SA.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_DIV_TAB)))
--                                    GROUP BY SA.DIVISION_ID
--                                           , SA.ITEM_ID
--                                   HAVING MAX(DECODE(SA.ACTIVE_FLAG, 'N', 1, 0)) = 1
--                                      AND MAX(DECODE(SA.ACTIVE_FLAG, 'Y', 1, 0)) = 0
--                                  ) SC
--                            WHERE SC.ITEM_ID = IA.ITEM_ID)
             , (SELECT SC.ITEM_ID
                  FROM (SELECT SA.DIVISION_ID
                                        , SA.ITEM_ID
                                     FROM SCM_MST_ITEM_SN SA
                                        , SCM_MST_ITEM_CLASS_SN SB
                                    WHERE SA.ITEM_CLASS = SB.CLASS_ID
                                      AND SB.USE_FLAG = 'Y'
                                      AND V_EXC_MODE <> 'N'
                                      AND (V_EXC_MODE = 'A' OR SA.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_DIV_TAB)))
                                    GROUP BY SA.DIVISION_ID
                                           , SA.ITEM_ID
                                   HAVING MAX(DECODE(SA.ACTIVE_FLAG, 'N', 1, 0)) = 1
                                      AND MAX(DECODE(SA.ACTIVE_FLAG, 'Y', 1, 0)) = 0
                                  ) SC
                 GROUP BY SC.ITEM_ID
               ) XE                                            /* 비활성 품목 (AS-IS #TblDynamicPivot_SCP0030_Inactive) */
         WHERE IA.ITEM_ID = XE.ITEM_ID(+)
           AND XE.ITEM_ID IS NULL
         /* 2026.10.06 AJS 비활성 품목 제외 성능 개선 (END) */
           AND (V_NICK_NAME IS NULL OR UPPER(IA.NICK_NAME) LIKE '%' || V_NICK_NAME || '%')
         ORDER BY UPPER(TRANSLATE(IA.DIVISION_ID, '_-', '/')) NULLS FIRST
                , UPPER(TRANSLATE(IA.ITEM_ID, '_-', '/')) NULLS FIRST
                , UPPER(TRANSLATE(IA.FROM_SITE_CODE, '_-', '/')) NULLS FIRST
                , UPPER(TRANSLATE(IA.TO_SITE_CODE, '_-', '/')) NULLS FIRST
                , UPPER(TRANSLATE(IA.TRANSPORT_MODE, '_-', '/')) NULLS FIRST
                , IA.SEQ;

        OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , '0' AS EVENT
          FROM DUAL;
    END P_SCP0030_GET_BOD_ITEM;

    /* =========================================================================================
     * Excluded Item 조회 (AS-IS SCP0030_GET_BOD_EXCLUDED_ITEM)
     *   품목·별칭은 쉼표 토큰마다 부분 일치 조인(AS-IS 와 같이 토큰 여러 개에 걸리면 행이 늘어남,
     *   빈 토큰은 전체 일치). Plan Group 조건은 AS-IS 가 항상 빈 값으로 덮어써 사용하지 않음.
     *   AS-IS 는 정렬 없음.
     * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
     * ========================================================================================= */
    PROCEDURE P_SCP0030_GET_BOD_EXCLUDED_ITEM
    (
        P_DIVISION_ID     IN  VARCHAR2
      , P_FROM_SITE       IN  VARCHAR2
      , P_TO_SITE         IN  VARCHAR2
      , P_INCOTERMS       IN  VARCHAR2
      , P_TRANS_MODE      IN  VARCHAR2
      , P_ITEM_ID         IN  VARCHAR2
      , P_NICK_NAME       IN  VARCHAR2
      , P_VALID           IN  VARCHAR2
      , P_PLAN_GROUP_ID   IN  VARCHAR2
      , P_USER_ID         IN  VARCHAR2
      , P_MENU_ID         IN  VARCHAR2
      , O_RC1             OUT SYS_REFCURSOR
      , O_RESULT_CURSOR   OUT SYS_REFCURSOR
    )
    IS
        V_DIV_USE      VARCHAR2(1)   := F_USE_LIST(P_DIVISION_ID);
        V_FROM_USE     VARCHAR2(1)   := F_USE_LIST(P_FROM_SITE);
        V_TO_USE       VARCHAR2(1)   := F_USE_LIST(P_TO_SITE);
        V_INCO_USE     VARCHAR2(1)   := F_USE_LIST(P_INCOTERMS);
        V_TRANS_USE    VARCHAR2(1)   := F_USE_LIST(P_TRANS_MODE);
        V_DIV_TAB      T_STR_TAB     := F_SPLIT_LIST(P_DIVISION_ID, 'N');
        V_FROM_TAB     T_STR_TAB     := F_SPLIT_LIST(P_FROM_SITE, 'N');
        V_TO_TAB       T_STR_TAB     := F_SPLIT_LIST(P_TO_SITE, 'N');
        V_INCO_TAB     T_STR_TAB     := F_SPLIT_LIST(P_INCOTERMS, 'N');
        V_TRANS_TAB    T_STR_TAB     := F_SPLIT_LIST(P_TRANS_MODE, 'N');
        V_ITEM_TAB     T_STR_TAB     := F_SPLIT_LIST(P_ITEM_ID, 'Y');
        V_NICK_TAB     T_STR_TAB     := F_SPLIT_LIST(P_NICK_NAME, 'Y');
        V_VALID        VARCHAR2(4 CHAR);
    BEGIN
        /* AS-IS @p_valid NVARCHAR(1) — 첫 글자만 비교 */
        V_VALID := CASE WHEN UPPER(TRIM(P_VALID)) = 'ALL' THEN NULL
                        ELSE UPPER(TRIM(SUBSTR(P_VALID, 1, 1)))
                   END;

        OPEN O_RC1 FOR
        SELECT IA.DIVISION_ID
             , IA.OPMZ_PLAN_GR_NAME
             , IA.ITEM_ID
             , IA.NICK_NAME
             , IA.BOD_ID
             , IA.FROM_SITE_NAME
             , IA.TO_SITE_NAME
             , IA.INCOTERMS
             , IA.TRANSPORT_MODE
             , IA.BOD_EX_FROM_YYYYMMDD
             , IA.BOD_EX_TO_YYYYMMDD
             , IA.VALID_YN
             , IA.LAST_UPDATED_BY
             , IA.LAST_UPDATE_DATE
             , IA.DIVISION_ID || '|' || IA.ITEM_ID || '|' || IA.BOD_ID || '|' || IA.ORG_BOD_EX_FROM_YYYYMMDD || '|' || IA.ORG_BOD_EX_TO_YYYYMMDD AS PRE_KEY_VALUES
          FROM (SELECT XC.DIVISION_ID
                     , XC.OPMZ_PLAN_GR_NAME
                     , XC.ITEM_ID
                     , XC.NICK_NAME
                     , XC.BOD_ID
                     , XC.FROM_SITE_NAME
                     , XC.TO_SITE_NAME
                     , XC.INCOTERMS
                     , XC.TRANSPORT_MODE
                     , XC.BOD_EX_FROM_YYYYMMDD
                     , XC.BOD_EX_TO_YYYYMMDD
                     , XC.VALID_YN
                     , XC.LAST_UPDATED_BY
                     , XC.LAST_UPDATE_DATE
                     , XC.ORG_BOD_EX_FROM_YYYYMMDD
                     , XC.ORG_BOD_EX_TO_YYYYMMDD
                     , XC.FROM_SITE
                     , XC.TO_SITE
                  FROM (
                /* AS-IS SELECT DISTINCT — 대소문자만 다른 행(사이트 ID 가 대소문자만 다른 사이트 이름)은 한 행으로.
                   대표값은 품목 사업부의 사이트 이름 우선(AS-IS 는 임의 선택) */
                SELECT A.DIVISION_ID
                     , ' ' AS OPMZ_PLAN_GR_NAME
                     , A.ITEM_ID
                     , G.NICK_NAME
                     , A.BOD_ID
                     , D.SITE_DESCRIPTION AS FROM_SITE_NAME
                     , E.SITE_DESCRIPTION AS TO_SITE_NAME
                     , C.INCOTERMS
                     , F.TRANSPORT_MODE
                     , TO_DATE(A.BOD_EX_FROM_YYYYMMDD, 'YYYYMMDD') AS BOD_EX_FROM_YYYYMMDD
                     , TO_DATE(A.BOD_EX_TO_YYYYMMDD, 'YYYYMMDD') AS BOD_EX_TO_YYYYMMDD
                     , A.VALID_YN
                     , A.LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                     , A.BOD_EX_FROM_YYYYMMDD AS ORG_BOD_EX_FROM_YYYYMMDD
                     , A.BOD_EX_TO_YYYYMMDD AS ORG_BOD_EX_TO_YYYYMMDD
                     , C.FROM_SITE
                     , C.TO_SITE
                     , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                     , A.ITEM_ID
                                                     , A.BOD_ID
                                                     , A.BOD_EX_FROM_YYYYMMDD
                                                     , A.BOD_EX_TO_YYYYMMDD
                                                     , UPPER(G.NICK_NAME)
                                                     , UPPER(D.SITE_DESCRIPTION)
                                                     , UPPER(E.SITE_DESCRIPTION)
                                                     , UPPER(C.INCOTERMS)
                                                     , UPPER(F.TRANSPORT_MODE)
                                                     , UPPER(C.FROM_SITE)
                                                     , UPPER(C.TO_SITE)
                                              ORDER BY DECODE(E.DIVISION_ID, A.DIVISION_ID, 0, 1)
                                                     , E.SITE_DESCRIPTION
                                                     , D.SITE_DESCRIPTION
                                                     , C.TO_SITE
                                                     , C.FROM_SITE) AS RN
                  FROM SCP_OPMZ_BOD_EXCLUDED_ITEM A
                     , SCP_MST_BOD_ITEM B
                     , SCP_MST_BOD C
                     , SCM_MST_SITE D                                  /* 출발 사이트 (PLANT, 품목 사업부) */
                     , SCM_MST_SITE E                                  /* 도착 사이트 (사업부 조건 없음 — AS-IS 동일) */
                     , SCP_MST_DISTRIBUTION_ROUTE F
                     , SCP_MST_FINAL_ITEM G
                 WHERE B.DIVISION_ID = A.DIVISION_ID
                   AND B.ITEM_ID = A.ITEM_ID
                   AND B.BOD_ID = A.BOD_ID
                   AND C.BOD_ID = B.BOD_ID
                   AND UPPER(D.SCM_SITE_ID) = UPPER(C.FROM_SITE)
                   AND D.DIVISION_ID = B.DIVISION_ID
                   AND UPPER(E.SCM_SITE_ID) = UPPER(C.TO_SITE)
                   -- E20260511-000181 BOD ITEM-Excluded Item Tab 조회저장 로직 수정요청 주석처리.
                   --AND ST.SITE_TYPE ='SALES'
                   AND F.ROUTE_ID = C.ROUTE_ID
                   AND G.DIVISION_ID = A.DIVISION_ID
                   AND G.ITEM_ID = A.ITEM_ID
                   AND D.SITE_TYPE = 'PLANT'
                       ) XC
                 WHERE XC.RN = 1
               ) IA
             , (SELECT DISTINCT
                       /* 조회조건 ALL 은 조건 없음 — 부분일치라 무늬를 '%%' 로 만든다 */
                       '%' || CASE WHEN UPPER(TRIM(COLUMN_VALUE)) = 'ALL' THEN NULL
                                   ELSE COLUMN_VALUE END || '%' AS TST
                  FROM TABLE(V_ITEM_TAB)
               ) XA
             , (SELECT DISTINCT
                       /* 조회조건 ALL 은 조건 없음 — 부분일치라 무늬를 '%%' 로 만든다 */
                       '%' || CASE WHEN UPPER(TRIM(COLUMN_VALUE)) = 'ALL' THEN NULL
                                   ELSE COLUMN_VALUE END || '%' AS TST
                  FROM TABLE(V_NICK_TAB)
               ) XB
--       WHERE UPPER(IA.ITEM_ID) LIKE XA.TST   --  2026.10.07 AJS
         WHERE (UPPER(IA.ITEM_ID) LIKE XA.TST OR UPPER(IA.NICK_NAME) LIKE XA.TST)   --  2026.10.07 AJS
           AND UPPER(IA.NICK_NAME) LIKE XB.TST
           AND (V_DIV_USE = 'N' OR IA.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_DIV_TAB)))
           AND (V_INCO_USE = 'N' OR UPPER(IA.INCOTERMS) IN (SELECT COLUMN_VALUE FROM TABLE(V_INCO_TAB)))
           AND (V_TRANS_USE = 'N' OR UPPER(IA.TRANSPORT_MODE) IN (SELECT COLUMN_VALUE FROM TABLE(V_TRANS_TAB)))
           AND (V_FROM_USE = 'N' OR UPPER(IA.FROM_SITE) IN (SELECT COLUMN_VALUE FROM TABLE(V_FROM_TAB)))
           AND (V_TO_USE = 'N' OR UPPER(IA.TO_SITE) IN (SELECT COLUMN_VALUE FROM TABLE(V_TO_TAB)))
           AND (V_VALID IS NULL OR UPPER(IA.VALID_YN) = V_VALID);

        OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , '0' AS EVENT
          FROM DUAL;
    END P_SCP0030_GET_BOD_EXCLUDED_ITEM;

    /* =========================================================================================
     * BOD ITEM 등록·수정 (AS-IS SCP0030_SAVE_BOD_ITEM)
     *   화면 저장 규격 : P_DATA = 그리드 행 JSON 배열(조회 칸 이름 + CRUD_TYPE)
     *   I·M 행만 처리(D 는 AS-IS 도 처리하지 않음) — 행마다 순번 채번 → 이력 적재 → 수정, 없으면 등록
     *   값은 AS-IS SCM_ARR_SPL_VAL 과 같이 앞뒤 공백 제거, 빈 값은 필수 칸 '-' · 선택 칸 NULL
     *   오류 시 이 프로시저에서 바꾼 내용만 되돌림(SAVEPOINT)
     * ========================================================================================= */
    PROCEDURE P_SCP0030_SAVE_BOD_ITEM
    (
        P_DATA            IN  CLOB
      , P_USER_ID         IN  VARCHAR2
      , O_RESULT_CURSOR   OUT SYS_REFCURSOR
    )
    IS
        V_PROGRAM_NAME   VARCHAR2(150)  := 'SCP0030_SAVE_BOM_ITEM';
        V_UNIT_NAME      VARCHAR2(150)  := 'PKG_SCP0030.P_SCP0030_SAVE_BOD_ITEM';
        V_WORKING_TIME   DATE;
        V_LOOP_CNT       PLS_INTEGER    := 0;
        V_SEQ            NUMBER(19);
        V_PRIORITY       NUMBER;
        V_SAFETY_STOCK   NUMBER;
        V_DIVISION_ID    VARCHAR2(4000);
        V_BOD_ID         VARCHAR2(4000);
        V_ITEM_ID        VARCHAR2(4000);
        V_FROM_YYYYMMDD  VARCHAR2(4000);
        V_TO_YYYYMMDD    VARCHAR2(4000);
        V_COMMITTED      VARCHAR2(1)    := 'N';
        V_ERR_MSG        VARCHAR2(4000);
    BEGIN
        SAVEPOINT SP_SCP0030_SAVE_BOD_ITEM;
        V_WORKING_TIME := SYSDATE;

        /* 시작 LOG */
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', SYSDATE);

        FOR R IN (SELECT UPPER(TRIM(JT.CRUD_TYPE)) AS CRUD_TYPE
                       , TRIM(JT.SEQ) AS SEQ
                       , TRIM(JT.BOD_ID) AS BOD_ID
                       , TRIM(JT.DIVISION_ID) AS DIVISION_ID
                       , TRIM(JT.ITEM_ID) AS ITEM_ID
                       , TRIM(JT.PRIORITY) AS PRIORITY
                       , TRIM(JT.FROM_YYYYMMDD) AS FROM_YYYYMMDD
                       , TRIM(JT.TO_YYYYMMDD) AS TO_YYYYMMDD
                       , TRIM(JT.SAFETY_STOCK) AS SAFETY_STOCK
                       , DECODE(JT.SAFETY_STOCK_EXISTS, 'true', 'Y', 'N') AS SAFETY_STOCK_EXISTS
                       , TRIM(JT.BOD_ITEM_VALID) AS BOD_ITEM_VALID
                    FROM JSON_TABLE(P_DATA, '$[*]' ERROR ON ERROR
                             COLUMNS ( CRUD_TYPE            VARCHAR2(4000) PATH '$."CRUD_TYPE"'
                                     , SEQ                  VARCHAR2(4000) PATH '$."SEQ"'
                                     , BOD_ID               VARCHAR2(4000) PATH '$."BOD_ID"'
                                     , DIVISION_ID          VARCHAR2(4000) PATH '$."DIVISION_ID"'
                                     , ITEM_ID              VARCHAR2(4000) PATH '$."ITEM_ID"'
                                     , PRIORITY             VARCHAR2(4000) PATH '$."PRIORITY"'
                                     , FROM_YYYYMMDD        VARCHAR2(4000) PATH '$."FROM_YYYYMMDD"'
                                     , TO_YYYYMMDD          VARCHAR2(4000) PATH '$."TO_YYYYMMDD"'
                                     , SAFETY_STOCK         VARCHAR2(4000) PATH '$."SAFETY_STOCK"'
                                     , SAFETY_STOCK_EXISTS  VARCHAR2(5)    EXISTS PATH '$."SAFETY_STOCK"'
                                     , BOD_ITEM_VALID       VARCHAR2(4000) PATH '$."BOD_ITEM_VALID"'
                                     )
                                    ) JT
                   WHERE UPPER(TRIM(JT.CRUD_TYPE)) IN ('I', 'M', 'D'))
        LOOP
            V_LOOP_CNT := V_LOOP_CNT + 1;

            IF R.CRUD_TYPE IN ('M', 'I') THEN
                IF R.SEQ IS NULL THEN
                    V_SEQ := SEQ1_SCP_MST_BOD_ITEM.NEXTVAL;
                ELSE
                    V_SEQ := F_TO_INT(R.SEQ);
                END IF;

                V_DIVISION_ID   := NVL(R.DIVISION_ID, '/');
                V_BOD_ID        := NVL(R.BOD_ID, '/');
                V_ITEM_ID       := NVL(R.ITEM_ID, '/');
                V_FROM_YYYYMMDD := NVL(F_TO_YYYYMMDD(R.FROM_YYYYMMDD), '-');
                V_TO_YYYYMMDD   := NVL(F_TO_YYYYMMDD(R.TO_YYYYMMDD), '-');
                V_PRIORITY      := F_TO_INT(R.PRIORITY);
                V_SAFETY_STOCK  := F_TO_DEC(R.SAFETY_STOCK, R.SAFETY_STOCK_EXISTS);

                /* 이력저장 */
                P_SCP_MST_BOD_ITEM_HIST(V_SEQ
                                      , V_BOD_ID
                                      , V_DIVISION_ID
                                      , V_ITEM_ID
                                      , V_PRIORITY
                                      , V_FROM_YYYYMMDD
                                      , V_TO_YYYYMMDD
                                      , V_SAFETY_STOCK
                                      , R.BOD_ITEM_VALID
                                      , P_USER_ID
                                      , V_WORKING_TIME
                                      , P_USER_ID
                                      , V_WORKING_TIME);

                /* AS-IS MERGE (WHEN MATCHED UPDATE / NOT MATCHED INSERT) */
                UPDATE SCP_MST_BOD_ITEM
                   SET DIVISION_ID      = V_DIVISION_ID
                     , FROM_YYYYMMDD    = V_FROM_YYYYMMDD
                     , TO_YYYYMMDD      = V_TO_YYYYMMDD
                     , PRIORITY         = V_PRIORITY
                     , SAFETY_STOCK     = V_SAFETY_STOCK
                     , VALID_YN         = R.BOD_ITEM_VALID
                     , LAST_UPDATED_BY  = P_USER_ID
                     , LAST_UPDATE_DATE = V_WORKING_TIME
                 WHERE SEQ = V_SEQ;

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT
                      INTO SCP_MST_BOD_ITEM
                         ( SEQ
                         , DIVISION_ID
                         , BOD_ID
                         , ITEM_ID
                         , PRIORITY
                         , FROM_YYYYMMDD
                         , TO_YYYYMMDD
                         , SAFETY_STOCK
                         , VALID_YN
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE
                         )
                    VALUES
                         ( V_SEQ
                         , V_DIVISION_ID
                         , V_BOD_ID
                         , V_ITEM_ID
                         , V_PRIORITY
                         , V_FROM_YYYYMMDD
                         , V_TO_YYYYMMDD
                         , V_SAFETY_STOCK
                         , R.BOD_ITEM_VALID
                         , P_USER_ID
                         , V_WORKING_TIME
                         , P_USER_ID
                         , V_WORKING_TIME
                         );
                END IF;
            END IF;
        END LOOP;

        /* 종료 LOG */
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', SYSDATE);

        COMMIT;
        V_COMMITTED := 'Y';

        OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , TO_CHAR(V_LOOP_CNT) AS EVENT
             , 'S' AS RESULT_CODE
             , V_LOOP_CNT AS RESULT_CNT
          FROM DUAL;
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SUBSTR(SQLERRM, 1, 4000);
            IF V_COMMITTED = 'N' THEN
                ROLLBACK TO SAVEPOINT SP_SCP0030_SAVE_BOD_ITEM;
            END IF;
            PR_SCM_SYS_LOG_BATCH(V_UNIT_NAME, 'ERROR', NULL, V_ERR_MSG, NULL, SYSDATE);

            OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE
                 , V_ERR_MSG AS MSG
                 , '0' AS EVENT
                 , 'F' AS RESULT_CODE
                 , 0 AS RESULT_CNT
              FROM DUAL;
    END P_SCP0030_SAVE_BOD_ITEM;

    /* =========================================================================================
     * Excluded Item 등록·수정·삭제 (AS-IS SCP0030_SAVE_BOD_EXCLUDED_ITEM)
     *   변경 전 키 = PRE_KEY_VALUES (사업부|품목|BOD|시작일|종료일, 조회 결과 그대로)
     *   AS-IS 는 신규 행의 변경 전 키가 빈 문자열이라 「자기 자신 제외」 조건이 항상 거짓 →
     *   중복·기간 겹침 검사가 신규 행에도 적용됨. 빈 값은 비교 불가 값으로 바꿔 같은 결과를 냄.
     *   오류 시 이 프로시저에서 바꾼 내용만 되돌림(SAVEPOINT)
     * ========================================================================================= */
    PROCEDURE P_SCP0030_SAVE_BOD_EXCLUDED_ITEM
    (
        P_DATA            IN  CLOB
      , P_USER_ID         IN  VARCHAR2
      , O_RESULT_CURSOR   OUT SYS_REFCURSOR
    )
    IS
        V_PROGRAM_NAME          VARCHAR2(150)  := 'SCP0030_SAVE_BOD_EXCLUDED_ITEM';
        V_UNIT_NAME             VARCHAR2(150)  := 'PKG_SCP0030.P_SCP0030_SAVE_BOD_EXCLUDED_ITEM';
        V_NONE                  VARCHAR2(1)    := CHR(0);          /* AS-IS 빈 문자열 비교(항상 거짓) 대용 */
        V_LOOP_CNT              PLS_INTEGER    := 0;
        V_CNT                   PLS_INTEGER    := 0;
        V_DIVISION_ID           VARCHAR2(4000);
        V_ITEM_ID               VARCHAR2(4000);
        V_BOD_ID                VARCHAR2(4000);
        V_FROM_YYYYMMDD         VARCHAR2(4000);
        V_TO_YYYYMMDD           VARCHAR2(4000);
        V_PRE_DIVISION_ID       VARCHAR2(4000);
        V_PRE_ITEM_ID           VARCHAR2(4000);
        V_PRE_BOD_ID            VARCHAR2(4000);
        V_PRE_FROM_YYYYMMDD     VARCHAR2(4000);
        V_PRE_TO_YYYYMMDD       VARCHAR2(4000);
        V_COMMITTED             VARCHAR2(1)    := 'N';
        V_ERR_MSG               VARCHAR2(4000);
        EX_BIZ                  EXCEPTION;
    BEGIN
        SAVEPOINT SP_SCP0030_SAVE_BOD_EX_ITEM;

        /* 시작 LOG */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', SYSDATE);

        FOR R IN (SELECT UPPER(TRIM(JT.CRUD_TYPE)) AS CRUD_TYPE
                       , TRIM(JT.DIVISION_ID) AS DIVISION_ID
                       , TRIM(JT.ITEM_ID) AS ITEM_ID
                       , TRIM(JT.BOD_ID) AS BOD_ID
                       , TRIM(JT.BOD_EX_FROM_YYYYMMDD) AS BOD_EX_FROM_YYYYMMDD
                       , TRIM(JT.BOD_EX_TO_YYYYMMDD) AS BOD_EX_TO_YYYYMMDD
                       , TRIM(JT.VALID_YN) AS VALID_YN
                       , JT.PRE_KEY_VALUES
                    FROM JSON_TABLE(P_DATA, '$[*]' ERROR ON ERROR
                             COLUMNS ( CRUD_TYPE             VARCHAR2(4000) PATH '$."CRUD_TYPE"'
                                     , DIVISION_ID           VARCHAR2(4000) PATH '$."DIVISION_ID"'
                                     , ITEM_ID               VARCHAR2(4000) PATH '$."ITEM_ID"'
                                     , BOD_ID                VARCHAR2(4000) PATH '$."BOD_ID"'
                                     , BOD_EX_FROM_YYYYMMDD  VARCHAR2(4000) PATH '$."BOD_EX_FROM_YYYYMMDD"'
                                     , BOD_EX_TO_YYYYMMDD    VARCHAR2(4000) PATH '$."BOD_EX_TO_YYYYMMDD"'
                                     , VALID_YN              VARCHAR2(4000) PATH '$."VALID_YN"'
                                     , PRE_KEY_VALUES        VARCHAR2(4000) PATH '$."PRE_KEY_VALUES"'
                                     )
                                    ) JT
                   WHERE UPPER(TRIM(JT.CRUD_TYPE)) IN ('I', 'M', 'D'))
        LOOP
            V_LOOP_CNT := V_LOOP_CNT + 1;

            V_DIVISION_ID   := NVL(R.DIVISION_ID, '/');
            V_ITEM_ID       := NVL(R.ITEM_ID, '/');
            V_BOD_ID        := NVL(R.BOD_ID, '/');
            V_FROM_YYYYMMDD := NVL(F_TO_YYYYMMDD(R.BOD_EX_FROM_YYYYMMDD), '-');
            V_TO_YYYYMMDD   := NVL(F_TO_YYYYMMDD(R.BOD_EX_TO_YYYYMMDD), '-');

            /* 변경 전 키 (AS-IS 화면 : 신규 행은 빈 값, 그 외 PRE_KEY_VALUES 를 '|' 로 분리) */
            IF R.CRUD_TYPE = 'I' OR R.PRE_KEY_VALUES IS NULL THEN
                V_PRE_DIVISION_ID   := V_NONE;
                V_PRE_ITEM_ID       := V_NONE;
                V_PRE_BOD_ID        := V_NONE;
                V_PRE_FROM_YYYYMMDD := V_NONE;
                V_PRE_TO_YYYYMMDD   := V_NONE;
            ELSE
                V_PRE_DIVISION_ID   := NVL(TRIM(REGEXP_SUBSTR(R.PRE_KEY_VALUES, '([^|]*)(\||$)', 1, 1, NULL, 1)), V_NONE);
                V_PRE_ITEM_ID       := NVL(TRIM(REGEXP_SUBSTR(R.PRE_KEY_VALUES, '([^|]*)(\||$)', 1, 2, NULL, 1)), V_NONE);
                V_PRE_BOD_ID        := NVL(TRIM(REGEXP_SUBSTR(R.PRE_KEY_VALUES, '([^|]*)(\||$)', 1, 3, NULL, 1)), V_NONE);
                V_PRE_FROM_YYYYMMDD := NVL(TRIM(REGEXP_SUBSTR(R.PRE_KEY_VALUES, '([^|]*)(\||$)', 1, 4, NULL, 1)), V_NONE);
                V_PRE_TO_YYYYMMDD   := NVL(TRIM(REGEXP_SUBSTR(R.PRE_KEY_VALUES, '([^|]*)(\||$)', 1, 5, NULL, 1)), V_NONE);
            END IF;

            /* 삭제가 아닌 경우, 중복체크 */
            IF R.CRUD_TYPE <> 'D' THEN
                /***** 중복체크 *****/
                SELECT COUNT(*)
                  INTO V_CNT
                  FROM SCP_OPMZ_BOD_EXCLUDED_ITEM
                 WHERE UPPER(DIVISION_ID)   = UPPER(V_DIVISION_ID)
                   AND UPPER(ITEM_ID)       = UPPER(V_ITEM_ID)
                   AND UPPER(BOD_ID)        = UPPER(V_BOD_ID)
                   AND BOD_EX_FROM_YYYYMMDD = V_FROM_YYYYMMDD
                   AND BOD_EX_TO_YYYYMMDD   = V_TO_YYYYMMDD
                   AND NOT (    UPPER(DIVISION_ID)   = UPPER(V_PRE_DIVISION_ID)
                            AND UPPER(ITEM_ID)       = UPPER(V_PRE_ITEM_ID)
                            AND UPPER(BOD_ID)        = UPPER(V_PRE_BOD_ID)
                            AND BOD_EX_FROM_YYYYMMDD = V_PRE_FROM_YYYYMMDD
                            AND BOD_EX_TO_YYYYMMDD   = V_PRE_TO_YYYYMMDD
                           );

                IF V_CNT > 0 THEN
                    V_ERR_MSG := '[99010] 입력 데이터 중 중복된 데이터가 있습니다.';
                    RAISE EX_BIZ;
                END IF;

                /**** 날짜 중복 체크 ****/
                SELECT COUNT(1)
                  INTO V_CNT
                  FROM SCP_OPMZ_BOD_EXCLUDED_ITEM X
                 WHERE UPPER(X.DIVISION_ID) = UPPER(V_DIVISION_ID)
                   AND UPPER(X.ITEM_ID)     = UPPER(V_ITEM_ID)
                   AND UPPER(X.BOD_ID)      = UPPER(V_BOD_ID)
                   AND NOT (V_TO_YYYYMMDD < X.BOD_EX_FROM_YYYYMMDD OR V_FROM_YYYYMMDD > X.BOD_EX_TO_YYYYMMDD)
                   AND NOT (X.BOD_EX_FROM_YYYYMMDD = V_PRE_FROM_YYYYMMDD AND X.BOD_EX_TO_YYYYMMDD = V_PRE_TO_YYYYMMDD);   /* 기존 값 */

                IF V_CNT > 0 THEN
                    V_ERR_MSG := '[99010] 입력 데이터 중 날짜가 중복되는 데이터가 있습니다.';
                    RAISE EX_BIZ;
                END IF;
            END IF;

            IF R.CRUD_TYPE = 'I' THEN
                INSERT
                  INTO SCP_OPMZ_BOD_EXCLUDED_ITEM
                     ( DIVISION_ID
                     , ITEM_ID
                     , BOD_ID
                     , BOD_EX_FROM_YYYYMMDD
                     , BOD_EX_TO_YYYYMMDD
                     , VALID_YN
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     )
                VALUES
                     ( V_DIVISION_ID
                     , V_ITEM_ID
                     , V_BOD_ID
                     , V_FROM_YYYYMMDD
                     , V_TO_YYYYMMDD
                     , R.VALID_YN
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     );
            ELSIF R.CRUD_TYPE = 'M' THEN
                UPDATE SCP_OPMZ_BOD_EXCLUDED_ITEM
                   SET DIVISION_ID          = V_DIVISION_ID
                     , ITEM_ID              = V_ITEM_ID
                     , BOD_ID               = V_BOD_ID
                     , BOD_EX_FROM_YYYYMMDD = V_FROM_YYYYMMDD
                     , BOD_EX_TO_YYYYMMDD   = V_TO_YYYYMMDD
                     , VALID_YN             = R.VALID_YN
                     , LAST_UPDATED_BY      = P_USER_ID
                     , LAST_UPDATE_DATE     = SYSDATE
                 WHERE UPPER(DIVISION_ID)   = UPPER(V_PRE_DIVISION_ID)
                   AND UPPER(ITEM_ID)       = UPPER(V_PRE_ITEM_ID)
                   AND UPPER(BOD_ID)        = UPPER(V_PRE_BOD_ID)
                   AND BOD_EX_FROM_YYYYMMDD = V_PRE_FROM_YYYYMMDD
                   AND BOD_EX_TO_YYYYMMDD   = V_PRE_TO_YYYYMMDD;
            /* 삭제기능 추가 (2025-07-16) */
            ELSIF R.CRUD_TYPE = 'D' THEN
                DELETE
                  FROM SCP_OPMZ_BOD_EXCLUDED_ITEM
                 WHERE UPPER(DIVISION_ID)   = UPPER(V_PRE_DIVISION_ID)
                   AND UPPER(ITEM_ID)       = UPPER(V_PRE_ITEM_ID)
                   AND UPPER(BOD_ID)        = UPPER(V_PRE_BOD_ID)
                   AND BOD_EX_FROM_YYYYMMDD = V_PRE_FROM_YYYYMMDD
                   AND BOD_EX_TO_YYYYMMDD   = V_PRE_TO_YYYYMMDD;
            END IF;
        END LOOP;

        /* 종료 LOG */
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', SYSDATE);

        COMMIT;
        V_COMMITTED := 'Y';

        OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE
             , 'SUCCESS' AS MSG
             , TO_CHAR(V_LOOP_CNT) AS EVENT
             , 'S' AS RESULT_CODE
             , V_LOOP_CNT AS RESULT_CNT
          FROM DUAL;
    EXCEPTION
        WHEN EX_BIZ THEN
            ROLLBACK TO SAVEPOINT SP_SCP0030_SAVE_BOD_EX_ITEM;
            PR_SCM_SYS_LOG_BATCH(V_UNIT_NAME, 'ERROR', NULL, V_ERR_MSG, NULL, SYSDATE);

            OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE
                 , V_ERR_MSG AS MSG
                 , '0' AS EVENT
                 , 'F' AS RESULT_CODE
                 , 0 AS RESULT_CNT
              FROM DUAL;
        WHEN OTHERS THEN
            V_ERR_MSG := SUBSTR(SQLERRM, 1, 4000);
            IF V_COMMITTED = 'N' THEN
                ROLLBACK TO SAVEPOINT SP_SCP0030_SAVE_BOD_EX_ITEM;
            END IF;
            PR_SCM_SYS_LOG_BATCH(V_UNIT_NAME, 'ERROR', NULL, V_ERR_MSG, NULL, SYSDATE);

            OPEN O_RESULT_CURSOR FOR
            SELECT '-1' AS CODE
                 , V_ERR_MSG AS MSG
                 , '0' AS EVENT
                 , 'F' AS RESULT_CODE
                 , 0 AS RESULT_CNT
              FROM DUAL;
    END P_SCP0030_SAVE_BOD_EXCLUDED_ITEM;

END PKG_SCP0030;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0030
-- ##### END PACKAGE BODY PKG_SCP0030

-- ##### START PACKAGE BODY PKG_SCP0031
CREATE OR REPLACE PACKAGE BODY PKG_SCP0031
IS
/*
 * Program ID   : PKG_SCP0031
 * Description  : SCP0031 Global PSI
 * Program History
 *===================================================================================================
 * Date         In Charge		Description
 *===================================================================================================
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 : 품목 뷰(SCM_MST_FINAL_ITEM_V) 외부조인에 조회 사업부 조건 추가 - 전 사업부 뷰 전개(약 26만 블록) 제거
 */

    /* AS-IS 피벗 집계에서 되풀이되는 MEASURE 목록 */
    C_MEASURE_BAL    CONSTANT VARCHAR2(200) := '''MODEL_INVENTORY'',''WH_IN_BALANCE'',''BALANCE'',''CHAR_AVAILABLE'',''ACTIVATE_PROGRESS'',''SAFETY_STOCK'',''GAP'',''DIO''';
    C_MEASURE_NOTIN  CONSTANT VARCHAR2(240) := '''MODEL_INVENTORY'',''WH_IN_BALANCE'',''BALANCE'',''CHAR_AVAILABLE'',''ACTIVATE_PROGRESS'',''LINE_TOTAL_LOAD_ENGINE'',''SAFETY_STOCK'',''GAP'',''DIO''';

    PROCEDURE P_SCP0031_GET_GLOBAL_PSI
    (
        P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_DIVISION_ID           IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_NICK_NAME             IN  VARCHAR2
      , P_FROM_SITE             IN  VARCHAR2
      , P_TO_SITE               IN  VARCHAR2
      , P_PLAN_START_YYYYMMDD   IN  VARCHAR2
      , P_PLAN_TYPE             IN  VARCHAR2
      , P_SEQ                   IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , P_BUCKET                IN  VARCHAR2
      , P_CHK_ALL               IN  VARCHAR2
      , P_DEBUG_MODE            IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS

        V_CNT_USR_MEASURE    VARCHAR2(1)   := '0';   /* AS-IS 는 NVARCHAR(1) 이라 10 이상이면 앞 한 자리만 남는다 */
        V_FROM_YYYYMMDD      VARCHAR2(32);
        V_TO_YYYYMMDD        VARCHAR2(32);
        V_FROM_RESULT        VARCHAR2(32);
        V_TO_RESULT          VARCHAR2(32);
        V_BUCKET             VARCHAR2(10)  := P_BUCKET;
        V_SEQ                NUMBER        := TO_NUMBER(P_SEQ);
        V_QRY_SUM            CLOB;
        V_EXEC               CLOB;
        V_EE_YN              VARCHAR2(1)   := 'N';   /* 조회 사업부가 EE 계열인지 */
        V_ERR_MSG            VARCHAR2(4000);

    BEGIN

        /* 세션에 남은 임시 자료 정리 */
        DELETE GT_SCP0031_NICKITEM;
        DELETE GT_SCP0031_RANK;
        DELETE GT_SCP0031_ITEM;
        DELETE GT_SCP0031_MEASURE;
        DELETE GT_SCP0031_MAIN;
        DELETE GT_SCP0031_RESULT;
        DELETE GT_SCP0031_LOADBASE;
        DELETE GT_SCP0031_LOAD;
        DELETE GT_SCP0031_FNL;

        SELECT SUBSTR(TO_CHAR(NVL(( SELECT COUNT(*)
                                      FROM SCM_MST_TITLESET_USER
                                     WHERE 1 = 1
                                       AND PROGRAM_ID = P_PROGRAM_ID
                                       AND SHEET_NAME = P_SHEET_NAME
                                       AND USER_ID    = P_USER_ID
                                  ), 0)), 1, 1)
          INTO V_CNT_USR_MEASURE
          FROM DUAL;

        BEGIN
            SELECT C.BASIS_START_DATE
              INTO V_FROM_YYYYMMDD
              FROM SCM_SYS_CALENDAR_M      C
             WHERE 1 = 1
               AND C.BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_FROM_YYYYMMDD := NULL;
        END;

        BEGIN
            SELECT C.BASIS_START_DATE
              INTO V_FROM_RESULT
              FROM SCM_SYS_CALENDAR_M      C
             WHERE 1 = 1
               AND C.BASIS_YYYYMMDD = P_FROM_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_FROM_RESULT := NULL;
        END;

        BEGIN
            SELECT C.BASIS_START_DATE
              INTO V_TO_RESULT
              FROM SCM_SYS_CALENDAR_M      C
             WHERE 1 = 1
               AND C.BASIS_YYYYMMDD = P_TO_YYYYMMDD;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_TO_RESULT := NULL;
        END;

        /* AS-IS 변수 초기값이 빈 문자라 미조회 시에도 비교가 성립한다. NVL 로 같은 분기를 태운다 */
        IF NVL(V_FROM_YYYYMMDD, ' ') > NVL(V_FROM_RESULT, ' ') THEN
            /* 실적 보여줌 */
            V_TO_YYYYMMDD := P_TO_YYYYMMDD;
            V_TO_RESULT   := V_FROM_YYYYMMDD;
        ELSIF NVL(V_FROM_YYYYMMDD, ' ') <= NVL(V_FROM_RESULT, ' ') THEN
            /* 실적 없음 */
            V_TO_YYYYMMDD := P_TO_YYYYMMDD;
            V_FROM_RESULT := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), 6), 'YYYYMMDD');
            V_TO_RESULT   := TO_CHAR(ADD_MONTHS(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
        END IF;
        /* AS-IS 의 나머지 두 분기(> v_to_result · = v_to_result)는 위 두 조건이 전 구간을 덮어 도달하지 않는다. 원문 유지 */

        /* 2021/12/14 Start */
        IF P_CHK_ALL = 'Y' THEN
            V_BUCKET := 'DAILY';   /* 2021/12/14 */
        END IF;
        /* 2021/12/14 End */

        SELECT CASE WHEN EXISTS ( SELECT 1
                                    FROM TABLE(FN_GET_DIVISION_DIV('EE'))
                                   WHERE COLUMN_VALUE = P_DIVISION_ID
                                ) THEN 'Y' ELSE 'N' END
          INTO V_EE_YN
          FROM DUAL;

        /* NICK NAME 조회조건으로 ITEM 추출 */
        INSERT INTO GT_SCP0031_NICKITEM
        (
            ITEM_ID
        )
        SELECT DISTINCT ITEM_ID
          FROM SCM_MST_ITEM_SN
         WHERE 1 = 1
           AND NICK_NAME IS NOT NULL
           AND TRIM(P_NICK_NAME) IS NOT NULL
           AND NICK_NAME LIKE P_NICK_NAME || '%';

        /* PSI CELL/PACK ITEM 세트 */
        INSERT INTO GT_SCP0031_RANK
        (
            CELL_ITEM_ID
          , ITEM_ID
          , RANK_NO
        )
        SELECT CELL_ITEM_ID
             , ITEM_ID
             , RANK() OVER (ORDER BY CELL_ITEM_ID ASC) AS RANK_NO
          FROM SCP_ANL_PSI_GLOBAL
         WHERE DIVISION_ID         = P_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_TYPE           = P_PLAN_TYPE
           AND SEQ                 = V_SEQ
           AND YYYYMMDD           >= P_FROM_YYYYMMDD
           AND YYYYMMDD           <= P_TO_YYYYMMDD
         GROUP BY CELL_ITEM_ID
                , ITEM_ID;

        /* 조회조건에 해당하는 세트 모두 추출 */
        INSERT INTO GT_SCP0031_ITEM
        (
            CELL_ITEM_ID
          , ITEM_ID
        )
        SELECT A.CELL_ITEM_ID
             , A.ITEM_ID
          FROM GT_SCP0031_RANK      A
         WHERE A.RANK_NO IN
               (
                 SELECT B.RANK_NO
                   FROM GT_SCP0031_RANK      B
                  WHERE 1 = 1
                    AND (
                          ( B.ITEM_ID IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_ITEM_ID, ','))) )
                          OR
                          ( B.ITEM_ID IN (SELECT ITEM_ID FROM GT_SCP0031_NICKITEM) )
                          OR
                          ( B.CELL_ITEM_ID IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_ITEM_ID, ','))) )
                          OR
                          ( B.CELL_ITEM_ID IN (SELECT ITEM_ID FROM GT_SCP0031_NICKITEM) )
                        )
               );

        /* 유저 MEASURE 세팅값 추출 */ /* 로드율은 PRODUCTION과 동일한 SORT 값을 강제 셋팅 */
        INSERT INTO GT_SCP0031_MEASURE
        (
            COLUMN_NAME
          , COLUMN_LABEL_NAME
          , SORT_ORDER_NO
          , ATTRIBUTE3
        )
        SELECT M.COLUMN_NAME
             , M.COLUMN_LABEL_NAME
             , CASE WHEN M.COLUMN_NAME = 'LINE_TOTAL_LOAD_ENGINE' AND TO_NUMBER(V_CNT_USR_MEASURE) > 0 THEN NVL(( SELECT T.SORT_ORDER_NO
                                                                                                                    FROM SCM_MST_TITLESET_USER      T
                                                                                                                   WHERE T.PROGRAM_ID  = M.PROGRAM_ID
                                                                                                                     AND T.SHEET_NAME  = M.SHEET_NAME
                                                                                                                     AND T.COLUMN_NAME = 'PRODUCTION'
                                                                                                                     AND T.USER_ID     = U.USER_ID
                                                                                                                ), U.SORT_ORDER_NO)
                    WHEN M.COLUMN_NAME = 'LINE_TOTAL_LOAD_ENGINE' AND TO_NUMBER(V_CNT_USR_MEASURE) = 0 THEN P.SORT_ORDER_NO
                    WHEN M.COLUMN_NAME = 'SHIP_PLAN'              AND TO_NUMBER(V_CNT_USR_MEASURE) > 0 THEN NVL(( SELECT T.SORT_ORDER_NO
                                                                                                                    FROM SCM_MST_TITLESET_USER      T
                                                                                                                   WHERE T.PROGRAM_ID  = M.PROGRAM_ID
                                                                                                                     AND T.SHEET_NAME  = M.SHEET_NAME
                                                                                                                     AND T.COLUMN_NAME = 'SHIP_REQ'
                                                                                                                     AND T.USER_ID     = U.USER_ID
                                                                                                                ), U.SORT_ORDER_NO)
                    WHEN M.COLUMN_NAME = 'SHIP_PLAN'              AND TO_NUMBER(V_CNT_USR_MEASURE) = 0 THEN S.SORT_ORDER_NO
                    ELSE NVL(U.SORT_ORDER_NO, M.SORT_ORDER_NO)
               END AS SORT_ORDER_NO
             , M.ATTRIBUTE3   /* MEASURE 별 COLOR RGB코드 */
          FROM SCM_MST_SHEET_MEASURE      M
             , SCM_MST_TITLESET_USER      U
             , SCM_MST_SHEET_MEASURE      P
             , SCM_MST_SHEET_MEASURE      S
         WHERE U.PROGRAM_ID(+)  = M.PROGRAM_ID
           AND U.SHEET_NAME(+)  = M.SHEET_NAME
           AND U.COLUMN_NAME(+) = M.COLUMN_NAME
           AND U.USER_ID(+)     = P_USER_ID
           AND P.PROGRAM_ID(+)  = M.PROGRAM_ID
           AND P.SHEET_NAME(+)  = M.SHEET_NAME
           AND P.COLUMN_NAME(+) = 'PRODUCTION'
           AND S.PROGRAM_ID(+)  = M.PROGRAM_ID
           AND S.SHEET_NAME(+)  = M.SHEET_NAME
           AND S.COLUMN_NAME(+) = 'SHIP_REQ'
           AND M.PROGRAM_ID     = 'SCP0031'
           AND M.VALID_YN       = 'Y'
           AND ( TO_NUMBER(V_CNT_USR_MEASURE) = 0 OR NVL(U.SORT_ORDER_NO, 0) > 0 );

        /*******************************************************************************
         * 데이타조회, 임시테이블에 저장
         *   AS-IS 는 조회조건 유무에 따라 문장을 조립했다. 조건별 정적 SQL 로 옮긴다
         *******************************************************************************/
        IF TRIM(P_ITEM_ID) IS NOT NULL OR TRIM(P_NICK_NAME) IS NOT NULL THEN

            INSERT INTO GT_SCP0031_MAIN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , B_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , QTY
              , ISO_WEEK
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , NVL(NULLIF(A.TO_SITE, ''), '/') AS TO_SITE
                 , CASE WHEN SUBSTR(NVL(NULLIF(A.TO_SITE, ''), '/'), -2) = '-S' THEN SUBSTR(NVL(NULLIF(A.TO_SITE, ''), '/'), 1, LENGTH(RTRIM(NVL(NULLIF(A.TO_SITE, ''), '/'))) - 2) ELSE NVL(NULLIF(A.TO_SITE, ''), '/') END AS TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , A.YYYYMMDD AS B_YYYYMMDD
                 , 'D_' || A.YYYYMMDD AS YYYYMMDD
                 , O.BASIS_YYYYMM AS YYYYMM
                 , NVL(A.QTY, 0) AS QTY
                 , SUBSTR(O.BASIS_YYYYMM, -4) || O.ISO_WEEK AS ISO_WEEK
                 , M.SORT_ORDER_NO
                 , M.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9    /* OPERATION ID */
                 , A.ATTRIBUTE10   /* P:1, A:2 */
                 , M.ATTRIBUTE3    /* UI용 MEASURE COLOR */
              FROM SCP_ANL_PSI_GLOBAL      A
                 , SCM_SYS_CALENDAR_M      O
                 , GT_SCP0031_MEASURE      M
                 , GT_SCP0031_ITEM         I
             WHERE A.YYYYMMDD            = O.BASIS_YYYYMMDD
               AND M.COLUMN_NAME         = A.MEASURE
               AND A.CELL_ITEM_ID        = I.CELL_ITEM_ID
               AND A.ITEM_ID             = I.ITEM_ID
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = V_SEQ
               AND A.YYYYMMDD           >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD           <= P_TO_YYYYMMDD
               AND ( TO_NUMBER(V_CNT_USR_MEASURE) = 0 OR NVL(M.SORT_ORDER_NO, 0) > 0 )
               AND ( TRIM(P_FROM_SITE) IS NULL OR NVL(NULLIF(A.FROM_SITE, ''), '/') IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_FROM_SITE, ','))) )
               AND ( TRIM(P_TO_SITE)   IS NULL OR NVL(NULLIF(A.TO_SITE, ''), '/')   IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_TO_SITE, ','))) );

        ELSE

            INSERT INTO GT_SCP0031_MAIN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , B_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , QTY
              , ISO_WEEK
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , NVL(NULLIF(A.TO_SITE, ''), '/') AS TO_SITE
                 , CASE WHEN SUBSTR(NVL(NULLIF(A.TO_SITE, ''), '/'), -2) = '-S' THEN SUBSTR(NVL(NULLIF(A.TO_SITE, ''), '/'), 1, LENGTH(RTRIM(NVL(NULLIF(A.TO_SITE, ''), '/'))) - 2) ELSE NVL(NULLIF(A.TO_SITE, ''), '/') END AS TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , A.YYYYMMDD AS B_YYYYMMDD
                 , 'D_' || A.YYYYMMDD AS YYYYMMDD
                 , O.BASIS_YYYYMM AS YYYYMM
                 , NVL(A.QTY, 0) AS QTY
                 , SUBSTR(O.BASIS_YYYYMM, -4) || O.ISO_WEEK AS ISO_WEEK
                 , M.SORT_ORDER_NO
                 , M.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9    /* OPERATION ID */
                 , A.ATTRIBUTE10   /* P:1, A:2 */
                 , M.ATTRIBUTE3    /* UI용 MEASURE COLOR */
              FROM SCP_ANL_PSI_GLOBAL      A
                 , SCM_SYS_CALENDAR_M      O
                 , GT_SCP0031_MEASURE      M
             WHERE A.YYYYMMDD            = O.BASIS_YYYYMMDD
               AND M.COLUMN_NAME         = A.MEASURE
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = V_SEQ
               AND A.YYYYMMDD           >= P_FROM_YYYYMMDD
               AND A.YYYYMMDD           <= P_TO_YYYYMMDD
               AND ( TO_NUMBER(V_CNT_USR_MEASURE) = 0 OR NVL(M.SORT_ORDER_NO, 0) > 0 )
               AND ( TRIM(P_FROM_SITE) IS NULL OR NVL(NULLIF(A.FROM_SITE, ''), '/') IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_FROM_SITE, ','))) )
               AND ( TRIM(P_TO_SITE)   IS NULL OR NVL(NULLIF(A.TO_SITE, ''), '/')   IN (SELECT TOKEN FROM TABLE(UF_FX_STRING_SPLIT(P_TO_SITE, ','))) );

        END IF;

        /*******************************************************************************
         * 1. Line Load(%) Temp
         *******************************************************************************/
        INSERT INTO GT_SCP0031_LOADBASE
        (
            DIVISION_ID
          , OPERATION_GROUP
          , FROM_SITE
          , ATTRIBUTE9
          , TRANSPORT_MODE_LINE
          , SUM_LOAD_QTY
          , QTY
          , WORKING_TIME
          , B_YYYYMMDD
          , YYYYMM
          , ISO_WEEK
          , WEEK_YYYYMMDD
          , MONTH_YYYYMMDD
        )
        SELECT A.DIVISION_ID
             , A.OPERATION_GROUP
             , A.FROM_SITE
             , A.ATTRIBUTE9
             , A.TRANSPORT_MODE_LINE
             , ROUND(SUM(A.QTY * (E.TACT_TIME / 60)), 0) AS SUM_LOAD_QTY
             , CASE WHEN D.WORKING_TIME <= 0.0 THEN 0
                    ELSE NVL(( ( ROUND(SUM(A.QTY * (E.TACT_TIME / 60)), 0) / D.WORKING_TIME ) ), 0) * 100
               END AS QTY
             , D.WORKING_TIME
             , A.YYYYMMDD AS B_YYYYMMDD
             , O.BASIS_YYYYMM AS YYYYMM
             , O.ISO_WEEK
             , 'W_' || O.BASIS_YYYYMM || O.ISO_WEEK AS WEEK_YYYYMMDD
             , 'M_' || O.BASIS_YYYYMM AS MONTH_YYYYMMDD
          FROM SCP_ANL_PSI_GLOBAL          A
             , SCM_SYS_CALENDAR_M          O
             , SCM_MST_SHEET_MEASURE       M
             , SCP_ANL_WORKING_TIME        D
             , SCP_ANL_TACT_TIME           E
         WHERE A.YYYYMMDD            = O.BASIS_YYYYMMDD
           AND M.PROGRAM_ID          = P_PROGRAM_ID
           AND M.COLUMN_NAME         = A.MEASURE
           AND A.DIVISION_ID         = D.DIVISION_ID
           AND A.ATTRIBUTE9          = D.OPERATION_ID
           AND A.FROM_SITE           = D.SCM_SITE_ID
           AND A.TRANSPORT_MODE_LINE = D.LINE_ID
           AND A.YYYYMMDD            = D.YYYYMMDD
           AND A.DIVISION_ID         = E.DIVISION_ID
           AND A.ATTRIBUTE9          = E.OPERATION_ID
           AND A.FROM_SITE           = E.SCM_SITE_ID
           AND A.TRANSPORT_MODE_LINE = E.LINE_ID
           AND (CASE WHEN A.OPERATION_GROUP = 'P' THEN A.ITEM_ID ELSE A.CELL_ITEM_ID END) = E.ITEM_ID
           AND A.YYYYMMDD            = E.YYYYMMDD
           AND A.DIVISION_ID         = P_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_TYPE           = P_PLAN_TYPE
           AND A.SEQ                 = V_SEQ
           AND A.YYYYMMDD           >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD           <= P_TO_YYYYMMDD
           AND ( TO_NUMBER(V_CNT_USR_MEASURE) = 0 OR NVL(M.SORT_ORDER_NO, 0) > 0 )
           AND A.MEASURE             = 'PRODUCTION'
         GROUP BY A.DIVISION_ID
                , A.OPERATION_GROUP
                , A.FROM_SITE
                , A.ATTRIBUTE9
                , A.TRANSPORT_MODE_LINE
                , A.YYYYMMDD
                , O.BASIS_YYYYMM
                , O.ISO_WEEK
                , D.WORKING_TIME;

        /*******************************************************************************
         * 2. 과거 실적구간 temp
         *******************************************************************************/
        IF V_FROM_RESULT < V_TO_RESULT THEN

            INSERT INTO GT_SCP0031_RESULT
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT DISTINCT A.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , A.SORT_ORDER_NO
                 , A.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9
                 , A.ATTRIBUTE10
                 , A.ATTRIBUTE3
              FROM GT_SCP0031_MAIN      A
             WHERE A.MEASURE IN ('PRODUCTION', 'SHIP_PLAN', 'ALLOCATION');

        END IF;

        /* Line Load(%) Insert */
        INSERT INTO GT_SCP0031_LOAD
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
          , SUM_LOAD_QTY
          , WORKING_TIME
          , WEEK_YYYYMMDD
          , MONTH_YYYYMMDD
        )
        SELECT A.DIVISION_ID
             , A.OPERATION_GROUP
             , A.CELL_ITEM_ID
             , A.ITEM_ID
             , A.TO_SITE
             , A.TO_SITE2
             , A.TO_BOH_QTY
             , A.FROM_BOH_QTY
             , A.INCOTERMS
             , A.FROM_SITE
             , A.TRANSPORT_MODE_LINE
             , 'LINE_TOTAL_LOAD_ENGINE' AS MEASURE
             , A.B_YYYYMMDD
             , A.YYYYMMDD
             , A.YYYYMM
             , B.QTY
             , A.ISO_WEEK
             , M.SORT_ORDER_NO
             , M.COLUMN_LABEL_NAME
             , A.BOD_ID
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , M.ATTRIBUTE3
             , B.SUM_LOAD_QTY
             , B.WORKING_TIME
             , B.WEEK_YYYYMMDD
             , B.MONTH_YYYYMMDD
          FROM GT_SCP0031_MAIN          A
             , GT_SCP0031_LOADBASE      B
             , GT_SCP0031_MEASURE       M
         WHERE A.DIVISION_ID         = B.DIVISION_ID
           AND A.OPERATION_GROUP     = B.OPERATION_GROUP
           AND A.FROM_SITE           = B.FROM_SITE
           AND A.ATTRIBUTE9          = B.ATTRIBUTE9
           AND A.TRANSPORT_MODE_LINE = B.TRANSPORT_MODE_LINE
           AND A.B_YYYYMMDD          = B.B_YYYYMMDD
           AND M.COLUMN_NAME         = 'LINE_TOTAL_LOAD_ENGINE';

        /* Load율 개선(Daily) */
        INSERT INTO GT_SCP0031_MAIN
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
        )
        SELECT A.DIVISION_ID
             , A.OPERATION_GROUP
             , A.CELL_ITEM_ID
             , A.ITEM_ID
             , A.TO_SITE
             , A.TO_SITE2
             , A.TO_BOH_QTY
             , A.FROM_BOH_QTY
             , A.INCOTERMS
             , A.FROM_SITE
             , A.TRANSPORT_MODE_LINE
             , A.MEASURE
             , A.B_YYYYMMDD
             , A.YYYYMMDD
             , A.YYYYMM
             , A.QTY
             , A.ISO_WEEK
             , A.SORT_ORDER_NO
             , A.COLUMN_LABEL_NAME
             , A.BOD_ID
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , A.ATTRIBUTE3
          FROM GT_SCP0031_LOAD      A;

        /* Load율 개선(Week) */
        INSERT INTO GT_SCP0031_MAIN
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
        )
        SELECT DIVISION_ID
             , OPERATION_GROUP
             , CELL_ITEM_ID
             , ITEM_ID
             , TO_SITE
             , TO_SITE2
             , TO_BOH_QTY
             , FROM_BOH_QTY
             , INCOTERMS
             , FROM_SITE
             , TRANSPORT_MODE_LINE
             , MEASURE
             , '-' AS B_YYYYMMDD
             , WEEK_YYYYMMDD AS YYYYMMDD
             , '/' AS YYYYMM
             , CASE WHEN SUM(WORKING_TIME) <= 0.0 THEN 0
                    ELSE NVL(( SUM(SUM_LOAD_QTY) / SUM(WORKING_TIME) ), 0) * 100
               END AS QTY
             , '-' AS ISO_WEEK
             , SORT_ORDER_NO
             , COLUMN_LABEL_NAME
             , BOD_ID
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE3
          FROM GT_SCP0031_LOAD
         GROUP BY DIVISION_ID
                , OPERATION_GROUP
                , CELL_ITEM_ID
                , ITEM_ID
                , TO_SITE
                , TO_SITE2
                , TO_BOH_QTY
                , FROM_BOH_QTY
                , INCOTERMS
                , FROM_SITE
                , TRANSPORT_MODE_LINE
                , MEASURE
                , SORT_ORDER_NO
                , COLUMN_LABEL_NAME
                , BOD_ID
                , ATTRIBUTE9
                , ATTRIBUTE10
                , ATTRIBUTE3
                , WEEK_YYYYMMDD
                , MONTH_YYYYMMDD;

        /* Load율 개선(Month) */
        INSERT INTO GT_SCP0031_MAIN
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
        )
        SELECT DIVISION_ID
             , OPERATION_GROUP
             , CELL_ITEM_ID
             , ITEM_ID
             , TO_SITE
             , TO_SITE2
             , TO_BOH_QTY
             , FROM_BOH_QTY
             , INCOTERMS
             , FROM_SITE
             , TRANSPORT_MODE_LINE
             , MEASURE
             , '-' AS B_YYYYMMDD
             , MONTH_YYYYMMDD AS YYYYMMDD
             , '/' AS YYYYMM
             , CASE WHEN SUM(WORKING_TIME) <= 0.0 THEN 0
                    ELSE NVL(( SUM(SUM_LOAD_QTY) / SUM(WORKING_TIME) ), 0) * 100
               END AS QTY
             , '-' AS ISO_WEEK
             , SORT_ORDER_NO
             , COLUMN_LABEL_NAME
             , BOD_ID
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE3
          FROM GT_SCP0031_LOAD
         GROUP BY DIVISION_ID
                , OPERATION_GROUP
                , CELL_ITEM_ID
                , ITEM_ID
                , TO_SITE
                , TO_SITE2
                , TO_BOH_QTY
                , FROM_BOH_QTY
                , INCOTERMS
                , FROM_SITE
                , TRANSPORT_MODE_LINE
                , MEASURE
                , SORT_ORDER_NO
                , COLUMN_LABEL_NAME
                , BOD_ID
                , ATTRIBUTE9
                , ATTRIBUTE10
                , ATTRIBUTE3
                , MONTH_YYYYMMDD;

        /* 생산/출하/매출 실적 insert */
        IF V_FROM_RESULT < V_TO_RESULT THEN

            /* 1. 생산실적 insert */
            INSERT INTO GT_SCP0031_MAIN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , B_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , QTY
              , ISO_WEEK
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT DISTINCT R.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , TO_CHAR(R.PLAN_DATE, 'YYYYMMDD') AS B_YYYYMMDD
                 , 'D_' || TO_CHAR(R.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                 , C.BASIS_YYYYMM AS YYYYMM
                 , R.ACTUAL_GOOD_QTY AS QTY
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK AS ISO_WEEK
                 , A.SORT_ORDER_NO
                 , A.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9
                 , A.ATTRIBUTE10
                 , A.ATTRIBUTE3
              FROM SCM_DNM_PRODUCT_RESULT_V      R
                 , SCM_SYS_CALENDAR_M            C
                 , SCP_MST_FINAL_ITEM            B
                 , GT_SCP0031_RESULT             A
             WHERE TO_CHAR(R.PLAN_DATE, 'YYYYMMDD') = C.BASIS_YYYYMMDD
               AND R.DIVISION_ID          = B.DIVISION_ID(+)
               AND R.ITEM_ID              = B.ITEM_ID(+)
               AND R.SCP_OPERATION_GROUP  = B.OPERATION_GROUP(+)
               AND A.MEASURE              = 'PRODUCTION'
               AND A.DIVISION_ID          = R.DIVISION_ID
               AND A.OPERATION_GROUP      = R.SCP_OPERATION_GROUP
               AND A.FROM_SITE            = R.SCM_SITE_ID
               AND A.ITEM_ID              = R.ITEM_ID
               AND A.ATTRIBUTE9           = R.OPERATION_ID
               AND A.TRANSPORT_MODE_LINE  = R.LINE_ID
               AND R.PLAN_DATE           >= TO_DATE(V_FROM_RESULT, 'YYYYMMDD')
               AND R.PLAN_DATE            < TO_DATE(V_TO_RESULT, 'YYYYMMDD')
               AND R.DIVISION_ID          = P_DIVISION_ID
               AND R.SCP_OPERATION_GROUP IN ('A', 'P')
               AND ( SUBSTR(R.OPERATION_ID, 1, 5) IN ( /* LOOKUP_TYPE 'SCP_PLAN_OPERATION' 에 정의된 공정만 조회 */
                                                       SELECT SEGMENT1 AS OPERATION_ID
                                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                        WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                          AND SEGMENT1   <> 'F6000'
                                                          AND VALID_YN    = 'Y'
                                                     )
                     OR R.OPERATION_ID IN ( /* 외주PACKER의 업체코드 */
                                            SELECT PLANT_ID AS OPERATION_ID
                                              FROM SCM_MST_SITE
                                             WHERE 1 = 1
                                               AND DIVISION_ID = P_DIVISION_ID
                                               AND SITE_TYPE   = 'PLANT'
                                               AND OSP_YN      = 'Y'
                                               AND VALID_YN    = 'Y'
                                          ) );

            /* 2. 출하실적 insert */
            INSERT INTO GT_SCP0031_MAIN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , B_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , QTY
              , ISO_WEEK
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT R.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , R.EXFACTORY_DATE AS B_YYYYMMDD
                 , 'D_' || R.EXFACTORY_DATE AS YYYYMMDD
                 , C.BASIS_YYYYMM AS YYYYMM
                 , R.EXFACTORY_QTY AS QTY
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK AS ISO_WEEK
                 , A.SORT_ORDER_NO
                 , A.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9
                 , A.ATTRIBUTE10
                 , A.ATTRIBUTE3
              FROM SCM_DNM_EXFACTORY_RESULT      R
                 , SCM_SYS_CALENDAR_M            C
                 , SCM_MST_SITE                  B
                 , GT_SCP0031_RESULT             A
             WHERE R.EXFACTORY_DATE     = C.BASIS_YYYYMMDD
               AND B.SCM_SITE_ID(+)     = R.TO_SCM_SITE_ID
               AND B.SITE_TYPE(+)       = 'PLANT'
               AND A.MEASURE            = 'SHIP_PLAN'
               AND A.DIVISION_ID        = R.DIVISION_ID
               AND A.ITEM_ID            = R.ITEM_ID
               AND A.FROM_SITE          = R.FROM_SCM_SITE_ID
               AND A.TO_SITE            = R.TO_SCM_SITE_ID
               AND A.TRANSPORT_MODE_LINE = R.TRANSPORT_MODE
               AND R.EXFACTORY_DATE    >= V_FROM_RESULT
               AND R.EXFACTORY_DATE     < V_TO_RESULT
               AND R.DIVISION_ID        = P_DIVISION_ID
               AND ( B.PLANT_ID IS NOT NULL OR (B.PLANT_ID IS NULL AND A.INCOTERMS = R.INCOTERMS) )   /* FG의 경우 incoterms 비교 */
               AND R.EXFACTORY_STATUS IN ('D20', 'D30', 'D40');

            /* 3. 매출실적 insert */
            INSERT INTO GT_SCP0031_MAIN
            (
                DIVISION_ID
              , OPERATION_GROUP
              , CELL_ITEM_ID
              , ITEM_ID
              , TO_SITE
              , TO_SITE2
              , TO_BOH_QTY
              , FROM_BOH_QTY
              , INCOTERMS
              , FROM_SITE
              , TRANSPORT_MODE_LINE
              , MEASURE
              , B_YYYYMMDD
              , YYYYMMDD
              , YYYYMM
              , QTY
              , ISO_WEEK
              , SORT_ORDER_NO
              , COLUMN_LABEL_NAME
              , BOD_ID
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE3
            )
            SELECT R.DIVISION_ID
                 , A.OPERATION_GROUP
                 , A.CELL_ITEM_ID
                 , A.ITEM_ID
                 , A.TO_SITE
                 , A.TO_SITE2
                 , A.TO_BOH_QTY
                 , A.FROM_BOH_QTY
                 , A.INCOTERMS
                 , A.FROM_SITE
                 , A.TRANSPORT_MODE_LINE
                 , A.MEASURE
                 , R.YYYYMMDD AS B_YYYYMMDD
                 , 'D_' || R.YYYYMMDD AS YYYYMMDD
                 , C.BASIS_YYYYMM AS YYYYMM
                 , R.QTY AS QTY
                 , SUBSTR(C.BASIS_YYYYMM, -4) || C.ISO_WEEK AS ISO_WEEK
                 , A.SORT_ORDER_NO
                 , A.COLUMN_LABEL_NAME
                 , A.BOD_ID
                 , A.ATTRIBUTE9
                 , A.ATTRIBUTE10
                 , A.ATTRIBUTE3
              FROM DM_PLN_SALES_PLAN_RESULT      R
                 , SCM_SYS_CALENDAR_M            C
                 , GT_SCP0031_RESULT             A
             WHERE R.YYYYMMDD      = C.BASIS_YYYYMMDD
               AND A.MEASURE       = 'ALLOCATION'
               AND A.DIVISION_ID   = R.DIVISION_ID
               AND A.ITEM_ID       = R.ITEM_ID
               AND A.TO_SITE       = R.SCM_SITE_ID
               AND A.INCOTERMS     = R.INCOTERMS
               AND R.YYYYMMDD     >= V_FROM_RESULT
               AND R.YYYYMMDD      < V_TO_RESULT
               AND R.DIVISION_ID   = P_DIVISION_ID
               AND R.MEASURE       = 'RTF';

        END IF;

        /* 2021/11/02 Start UI 속도 개선 */
        INSERT INTO GT_SCP0031_FNL
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
        )
        SELECT DIVISION_ID
             , OPERATION_GROUP
             , CELL_ITEM_ID
             , ITEM_ID
             , TO_SITE
             , TO_SITE2
             , TO_BOH_QTY
             , FROM_BOH_QTY
             , INCOTERMS
             , FROM_SITE
             , TRANSPORT_MODE_LINE
             , MEASURE
             , B_YYYYMMDD
             , YYYYMMDD
             , YYYYMM
             , QTY
             , ISO_WEEK
             , SORT_ORDER_NO
             , COLUMN_LABEL_NAME
             , BOD_ID
             , ATTRIBUTE9
             , ATTRIBUTE10
             , ATTRIBUTE3
          FROM GT_SCP0031_MAIN;

        /* chaan begin V1.5 VMI 안전재고설정 추가 - Measure가 없는 Gap용 가상행을 추가함(Safety Stock 행 복사후 Measure, ATTRIBUTE3-라인색상 등만 Gap용으로 변경) */
        INSERT INTO GT_SCP0031_FNL
        (
            DIVISION_ID
          , OPERATION_GROUP
          , CELL_ITEM_ID
          , ITEM_ID
          , TO_SITE
          , TO_SITE2
          , TO_BOH_QTY
          , FROM_BOH_QTY
          , INCOTERMS
          , FROM_SITE
          , TRANSPORT_MODE_LINE
          , MEASURE
          , B_YYYYMMDD
          , YYYYMMDD
          , YYYYMM
          , QTY
          , ISO_WEEK
          , SORT_ORDER_NO
          , COLUMN_LABEL_NAME
          , BOD_ID
          , ATTRIBUTE9
          , ATTRIBUTE10
          , ATTRIBUTE3
          , WEEK_YN
          , MONTH_YN
        )
        SELECT F.DIVISION_ID
             , F.OPERATION_GROUP
             , F.CELL_ITEM_ID
             , F.ITEM_ID
             , F.TO_SITE
             , F.TO_SITE2
             , F.TO_BOH_QTY
             , F.FROM_BOH_QTY
             , F.INCOTERMS
             , F.FROM_SITE
             , F.TRANSPORT_MODE_LINE
             , F.MEASURE
             , F.B_YYYYMMDD
             , F.YYYYMMDD
             , F.YYYYMM
             , F.QTY
             , F.ISO_WEEK
             , C.SORT_ORDER_NO
             , C.COLUMN_LABEL_NAME
             , F.BOD_ID
             , F.ATTRIBUTE9
             , F.ATTRIBUTE10
             , C.ATTRIBUTE3
             , F.WEEK_YN
             , F.MONTH_YN
          FROM (
                 SELECT S.DIVISION_ID
                      , S.OPERATION_GROUP
                      , S.CELL_ITEM_ID
                      , S.ITEM_ID
                      , S.TO_SITE
                      , S.TO_SITE2
                      , S.TO_BOH_QTY
                      , S.FROM_BOH_QTY
                      , S.INCOTERMS
                      , S.FROM_SITE
                      , S.TRANSPORT_MODE_LINE
                      , 'GAP' AS MEASURE
                      , S.B_YYYYMMDD
                      , S.YYYYMMDD
                      , S.YYYYMM
                      , (NVL(B.QTY, 0) - NVL(S.QTY, 0)) AS QTY
                      , S.ISO_WEEK
                      , S.SORT_ORDER_NO
                      , S.COLUMN_LABEL_NAME
                      , S.BOD_ID
                      , S.ATTRIBUTE9
                      , S.ATTRIBUTE10
                      , S.ATTRIBUTE3
                      , S.WEEK_YN
                      , S.MONTH_YN
                   FROM ( SELECT *
                            FROM GT_SCP0031_FNL
                           WHERE MEASURE = 'SAFETY_STOCK'
                        )  S
                      , ( SELECT *
                            FROM GT_SCP0031_FNL
                           WHERE MEASURE = 'WH_IN_BALANCE'
                        )  B
                  /* Safet Stocck 을 기준으로 하므로 Safety Stock 행이 없으면 Gap 행도 만들 수 없음 */
                  WHERE S.DIVISION_ID          = B.DIVISION_ID(+)
                    AND S.OPERATION_GROUP      = B.OPERATION_GROUP(+)
                    AND S.CELL_ITEM_ID         = B.CELL_ITEM_ID(+)
                    AND S.ITEM_ID              = B.ITEM_ID(+)
                    AND S.TO_SITE              = B.TO_SITE(+)
                    AND S.TO_SITE2             = B.TO_SITE2(+)
                    AND S.INCOTERMS            = B.INCOTERMS(+)
                    AND S.FROM_SITE            = B.FROM_SITE(+)
                    AND S.TRANSPORT_MODE_LINE  = B.TRANSPORT_MODE_LINE(+)
                    AND S.B_YYYYMMDD           = B.B_YYYYMMDD(+)
                    AND S.YYYYMMDD             = B.YYYYMMDD(+)
                    AND S.YYYYMM               = B.YYYYMM(+)
                    AND S.ISO_WEEK             = B.ISO_WEEK(+)
                    AND S.BOD_ID               = B.BOD_ID(+)
               )  F
             , ( SELECT M.PROGRAM_ID
                      , M.SHEET_NAME
                      , M.COLUMN_NAME
                      , M.COLUMN_LABEL_NAME
                      , T.SORT_ORDER_NO
                      , 'GAP' AS MEASURE
                      , M.ATTRIBUTE9
                      , M.ATTRIBUTE10
                      , M.ATTRIBUTE3
                   FROM SCM_MST_SHEET_MEASURE      M
                      , SCM_MST_TITLESET_USER      T
                  WHERE 1 = 1
                    AND M.PROGRAM_ID  = T.PROGRAM_ID
                    AND M.SHEET_NAME  = T.SHEET_NAME
                    AND M.COLUMN_NAME = T.COLUMN_NAME
                    AND M.COLUMN_NAME = 'GAP'
                    AND T.PROGRAM_ID  = P_PROGRAM_ID
                    AND T.SHEET_NAME  = P_SHEET_NAME
                    AND T.USER_ID     = P_USER_ID
               )  C
         WHERE F.MEASURE = C.MEASURE(+);
        /* chaan end V1.5 VMI 안전재고설정 추가 - Measure가 없는 Gap용 가상행을 추가함(Safety Stock 행 복사후 Measure, ATTRIBUTE3-라인색상 등만 Gap용으로 변경) */

        UPDATE GT_SCP0031_FNL      A
           SET A.WEEK_YN = 'Y'
         WHERE A.MEASURE IN ('MODEL_INVENTORY', 'WH_IN_BALANCE', 'BALANCE', 'CHAR_AVAILABLE', 'ACTIVATE_PROGRESS', 'SAFETY_STOCK', 'GAP', 'DIO')
           AND EXISTS ( SELECT 1
                          FROM ( SELECT ISO_WEEK
                                      , PARTIAL_WEEK_NAME
                                      , CALENDAR_YYYY
                                      , MAX(BASIS_YYYYMMDD) AS YYYYMMDD
                                   FROM SCM_SYS_CALENDAR_M
                                  WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                    AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD   /* 마지막 구간 오류 발생으로 1개월 더함 */
                                  GROUP BY ISO_WEEK
                                         , PARTIAL_WEEK_NAME
                                         , CALENDAR_YYYY
                               )  XA
                         WHERE SUBSTR(A.YYYYMMDD, -8) = XA.YYYYMMDD
                      );

        UPDATE GT_SCP0031_FNL      A
           SET A.MONTH_YN = 'Y'
         WHERE A.MEASURE IN ('MODEL_INVENTORY', 'WH_IN_BALANCE', 'BALANCE', 'CHAR_AVAILABLE', 'ACTIVATE_PROGRESS', 'SAFETY_STOCK', 'GAP', 'DIO')
           AND EXISTS ( SELECT 1
                          FROM ( SELECT BASIS_YYYYMM
                                      , MAX(BASIS_YYYYMMDD) AS YYYYMMDD
                                   FROM SCM_SYS_CALENDAR_M
                                  WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                    AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD   /* 마지막 구간 오류 발생으로 1개월 더함 */
                                  GROUP BY BASIS_YYYYMM
                               )  XA
                         WHERE SUBSTR(A.YYYYMMDD, -8) = XA.YYYYMMDD
                      );
        /* 2021/11/02 End UI 속도 개선 */

        /*******************************************************************************
         * PIVOIT처리
         *   집계 대상 날짜가 조회 구간에 따라 달라져 컬럼 자체가 가변이므로
         *   이 구간만 동적 SQL 로 둔다(06 보고서 6항)
         *******************************************************************************/
        /* PIVOIT 대상 날짜문자열 생성 */
        V_QRY_SUM := EMPTY_CLOB();
        DBMS_LOB.CREATETEMPORARY(V_QRY_SUM, TRUE);

        FOR R IN ( SELECT YYYYMMDD
                     FROM ( SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                                 , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M      A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND ( V_BUCKET = 'DAILY' OR V_BUCKET = 'WEEKLY' )
                             GROUP BY A.BASIS_YYYYMM
                                    , A.ISO_WEEK
                                    , A.BASIS_START_DATE
                            UNION ALL
                            SELECT 'M_' || A.BASIS_YYYYMM AS YYYYMMDD
                                 , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M      A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY A.BASIS_YYYYMM
                                    , A.MONTH_NAME
                            UNION ALL
                            SELECT 'D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                                 , A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M      A
                             WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND V_BUCKET = 'DAILY'
                             GROUP BY A.BASIS_YYYYMMDD
                          )  IA
                    ORDER BY SORT_ORDER_NO
                 )
        LOOP

            IF INSTR(R.YYYYMMDD, 'M_') = 1 THEN
                DBMS_LOB.WRITEAPPEND(V_QRY_SUM, LENGTH(','), ',');
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(
                    'SUM( CASE WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) AND MEASURE IN     (' || C_MEASURE_BAL || ') AND MONTH_YN = ''Y''       THEN CAST(QTY AS NUMBER(15,2)) '
                 || 'WHEN YYYYMM = SUBSTR(''' || R.YYYYMMDD || ''', -6) AND MEASURE NOT IN (' || C_MEASURE_NOTIN || ') THEN CAST(QTY AS NUMBER(15,2)) ELSE 0 END   ) AS ' || R.YYYYMMDD || CHR(10)));
            ELSIF INSTR(R.YYYYMMDD, 'W_') = 1 THEN
                DBMS_LOB.WRITEAPPEND(V_QRY_SUM, LENGTH(','), ',');
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(
                    'SUM( CASE WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', -6) AND MEASURE IN     (' || C_MEASURE_BAL || ') AND WEEK_YN = ''Y''        THEN CAST(QTY AS NUMBER(15,2)) '
                 || 'WHEN ISO_WEEK = SUBSTR(''' || R.YYYYMMDD || ''', -6) AND MEASURE NOT IN (' || C_MEASURE_NOTIN || ') THEN CAST(QTY AS NUMBER(15,2)) ELSE 0 END   ) AS ' || R.YYYYMMDD || CHR(10)));
            ELSIF INSTR(R.YYYYMMDD, 'D_') = 1 THEN
                DBMS_LOB.WRITEAPPEND(V_QRY_SUM, LENGTH(','), ',');
                DBMS_LOB.APPEND(V_QRY_SUM, TO_CLOB(
                    ' SUM(CASE WHEN YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN QTY END ) AS ' || R.YYYYMMDD || CHR(10)));
            END IF;

        END LOOP;

        V_EXEC := EMPTY_CLOB();
        DBMS_LOB.CREATETEMPORARY(V_EXEC, TRUE);

        /* 주의 : 조회항목 변경 시 M_,W_,D_ 컬럼이 항상 뒤에 나와야함
                  UI에서 합계계산 시 COLUMN COUNT INDEX 계산 */
        DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
            'SELECT CASE WHEN A.BOD_ID = ''-'' THEN ''-'' ELSE TO_CHAR(B.LT_TOTAL) END AS LT_DAY' || CHR(10)
         || '     , NVL(NULLIF(A.CELL_QTY_PACK_T, ''''), ''-'') AS CELL_QTY_PACK' || CHR(10)
         || '     , NVL(D.SEGMENT2, ''/'') AS OPERATION_GROUP_NAME' || CHR(10)
         || '     , NVL(( SELECT H.DEPT_NAME_KO' || CHR(10)
         || '               FROM SCM_MST_SSO_DEPT_INFO      H' || CHR(10)
         -- 2026.09.30 AJS 부서 열쇠를 사이트 대표 부서 뷰로 변경 (START)
         -- || '              WHERE H.DEPT_ID = CASE WHEN ' || CASE WHEN V_EE_YN = 'Y' THEN 'A.ORIGIN_TO_DIVISION_ID' ELSE 'A.DIVISION_ID' END || ' = ''40'' THEN G.DEPT_ID ELSE E.DEPT_ID END' || CHR(10)
         || '              WHERE H.DEPT_ID = CASE WHEN ' || CASE WHEN V_EE_YN = 'Y' THEN 'A.ORIGIN_TO_DIVISION_ID' ELSE 'A.DIVISION_ID' END || ' = ''40'' THEN G.DEPT_ID ELSE C.DEPT_ID END' || CHR(10)
         -- 2026.09.30 AJS 부서 열쇠를 사이트 대표 부서 뷰로 변경 (END)
         || '                AND ROWNUM = 1 ), ''-'') AS DEPT_NAME' || CHR(10)
         || '     , A.*' || CHR(10)
         || '     , FN_GET_SCP_CELL_TYPE_SORT(V.CELL_TYPE) AS CELL_TYPE_SORT' || CHR(10)   /* 20230613 Final Item) Cell Type Sort */
         || '  FROM ( SELECT A.DIVISION_ID' || CHR(10)
         || '              , A.OPERATION_GROUP' || CHR(10)
         || '              , A.CELL_ITEM_ID' || CHR(10)
         || '              , A.ITEM_ID' || CHR(10)
         || '              , ( SELECT (CASE WHEN X.NICK_NAME IS NULL THEN ''-''  WHEN X.NICK_NAME = ''''    THEN ''-''  ELSE X.NICK_NAME END) FROM SCM_MST_ITEM_SN X  WHERE  X.ITEM_ID  = A.ITEM_ID AND X.NICK_NAME IS NOT NULL AND ROWNUM = 1 ) AS NICK_NAME' || CHR(10)
         || '              , CASE WHEN A.OPERATION_GROUP = ''A'' THEN ''-'' ELSE ( SELECT TO_CHAR(CEIL(V.ACCUMULATED_CHILD_QTY))' || CHR(10)
         || '                                                                       FROM SCM_MST_MODEL_FINAL_ITEM_BOM_V V' || CHR(10)
         || '                                                                      WHERE V.DIVISION_ID = A.DIVISION_ID AND V.OPERATION_GROUP_ID = ''A''' || CHR(10)
         || '                                                                        AND V.MODEL_ID = A.ITEM_ID AND V.CHILD_ITEM_ID = A.CELL_ITEM_ID' || CHR(10)
         || '                                                                        AND ROWNUM = 1 ) END AS CELL_QTY_PACK_T' || CHR(10)
         || '              , A.TO_SITE' || CHR(10)
         || '              , A.TO_SITE2' || CHR(10)
         || '              , NVL(NULLIF(( SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = A.TO_SITE AND ROWNUM = 1 ), ''''), ''/'') AS TO_SITE_DESCRIPTION' || CHR(10)
         || '              , A.TO_BOH_QTY' || CHR(10)
         || '              , A.FROM_BOH_QTY' || CHR(10)
         || '              , NVL(NULLIF(A.INCOTERMS, ''''), ''/'') AS INCOTERMS' || CHR(10)
         || '              , A.FROM_SITE' || CHR(10)
         || '              , NVL(NULLIF(( SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = A.FROM_SITE AND ROWNUM = 1 ), ''''), ''/'') AS FROM_SITE_DESCRIPTION' || CHR(10)
         || '              , NVL(NULLIF(A.TRANSPORT_MODE_LINE, ''''), ''/'') AS TRANSPORT_MODE_LINE' || CHR(10)
         || '              , A.BOD_ID' || CHR(10)
         || '              , A.ATTRIBUTE10' || CHR(10)
         || '              , A.MEASURE' || CHR(10)
         || '              , A.COLUMN_LABEL_NAME AS MEASURE_LABEL' || CHR(10)
         || '              , A.SORT_ORDER_NO' || CHR(10)
         || '              , A.ATTRIBUTE3 AS MEASURE_COLOR' || CHR(10)));

        DBMS_LOB.APPEND(V_EXEC, V_QRY_SUM);

        DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
            '           FROM GT_SCP0031_FNL      A' || CHR(10)
         || '          GROUP BY A.DIVISION_ID' || CHR(10)
         || '                 , A.OPERATION_GROUP' || CHR(10)
         || '                 , A.CELL_ITEM_ID' || CHR(10)
         || '                 , A.ITEM_ID' || CHR(10)
         || '                 , A.TO_SITE' || CHR(10)
         || '                 , A.TO_SITE2' || CHR(10)
         || '                 , A.TO_BOH_QTY' || CHR(10)
         || '                 , A.FROM_BOH_QTY' || CHR(10)
         || '                 , A.INCOTERMS' || CHR(10)
         || '                 , A.FROM_SITE' || CHR(10)
         || '                 , A.TRANSPORT_MODE_LINE' || CHR(10)
         || '                 , A.BOD_ID' || CHR(10)
         || '                 , A.ATTRIBUTE10' || CHR(10)
         || '                 , A.MEASURE' || CHR(10)
         || '                 , A.SORT_ORDER_NO' || CHR(10)
         || '                 , A.COLUMN_LABEL_NAME' || CHR(10)
         || '                 , A.ATTRIBUTE3' || CHR(10)
         || '       )  A' || CHR(10)
         || '     , SCP_ANL_BOD_N_V_PLAN_H         B' || CHR(10)
         || '     , SCM_ADM_LOOKUP_MASTER_DETAIL   D' || CHR(10)
         -- 2026.09.30 AJS SCM_MST_SITE.DEPT_ID 삭제에 따라 사이트 대표 부서 뷰를 덧붙임 (START)
         || '     , SCM_MST_SITE                   E' || CHR(10)
         || '     , SCM_MST_SITE_DEPT_REP_V    C' || CHR(10)
         -- 2026.09.30 AJS SCM_MST_SITE.DEPT_ID 삭제에 따라 사이트 대표 부서 뷰를 덧붙임 (END)
         || '     , ( SELECT XA.*' || CHR(10)
         || '              , ROW_NUMBER() OVER (PARTITION BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.ITEM_ID ORDER BY XA.PROJECT_CODE) AS RANK_NUMBER' || CHR(10)
         || '           FROM SCM_MST_SITE_ITEM      XA' || CHR(10)
         || '          WHERE XA.VALID_YN = ''Y''' || CHR(10)
         || '       )  F' || CHR(10)
         || '     , SCM_MST_SSO_USER_INFO          G' || CHR(10)
         || '     , SCM_MST_FINAL_ITEM_V           V' || CHR(10)
         || ' WHERE B.DIVISION_ID(+) = A.DIVISION_ID' || CHR(10)
         || '   AND B.BOD_ID(+)      = A.BOD_ID' || CHR(10)
         || '   AND B.FROM_SITE(+)   = A.FROM_SITE' || CHR(10)
         || '   AND B.PLAN_NAME(+)   = ''' || P_PLAN_START_YYYYMMDD || '''' || CHR(10)
         || '   AND B.PLAN_TYPE(+)   = ''' || P_PLAN_TYPE || '''' || CHR(10)
         /* ★차수가 비면 AS-IS 는 조회문 전체가 값 없음이 되어 결과 0건을 돌려준다.
            Oracle 은 빈 값을 빈 글자로 이어 붙여 끊긴 문장을 만들므로 조건으로 막아 같은 결과가 되게 한다. */
         || CASE WHEN V_SEQ IS NULL
                 THEN '   AND 1 = 0' || CHR(10)
                 ELSE '   AND B.PLAN_SEQ(+)    = ' || TO_CHAR(V_SEQ) || CHR(10)
            END
         || '   AND D.LOOKUP_TYPE(+) = ''OPERATION_GROUP''' || CHR(10)
         || '   AND D.SEGMENT1(+)    = A.OPERATION_GROUP' || CHR(10)));

        /********** DEPT NAME START **********/
        IF V_EE_YN = 'N' THEN
            DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
                '   AND E.DIVISION_ID(+) = A.DIVISION_ID' || CHR(10)
             || '   AND E.SCM_SITE_ID(+) = A.TO_SITE' || CHR(10)));
        ELSE
            DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
                '   AND E.DIVISION_ID(+) = A.ORIGIN_TO_DIVISION_ID' || CHR(10)
             || '   AND E.SCM_SITE_ID(+) = A.TO_SITE2' || CHR(10)));
        END IF;

        DBMS_LOB.APPEND(V_EXEC, TO_CLOB('   AND E.VALID_YN(+)    = ''Y''' || CHR(10)));

        -- 2026.09.30 AJS 사이트 대표 부서 뷰 조인 추가 (START)
        DBMS_LOB.APPEND(V_EXEC, TO_CLOB('   AND C.DIVISION_ID(+) = E.DIVISION_ID' || CHR(10)
                                      || '   AND C.SCM_SITE_ID(+) = E.SCM_SITE_ID' || CHR(10)));
        -- 2026.09.30 AJS 사이트 대표 부서 뷰 조인 추가 (END)

        IF V_EE_YN = 'N' THEN
            DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
                '   AND F.DIVISION_ID(+) = A.DIVISION_ID' || CHR(10)
             || '   AND F.SCM_SITE_ID(+) = A.TO_SITE' || CHR(10)));
        ELSE
            DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
                '   AND F.DIVISION_ID(+) = A.ORIGIN_TO_DIVISION_ID' || CHR(10)
             || '   AND F.SCM_SITE_ID(+) = A.TO_SITE2' || CHR(10)));
        END IF;

        DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
            '   AND F.ITEM_ID(+)     = A.ITEM_ID' || CHR(10)
         || '   AND F.VALID_YN(+)    = ''Y''' || CHR(10)
         || '   AND F.RANK_NUMBER(+) = 1' || CHR(10)   /* PROJECT_CODE 가 없어 1건만 가져오기 위해 처리 */
         || '   AND SUBSTR(F.OWNER, 1, CASE WHEN INSTR(F.OWNER, '','') = 0 THEN LENGTH(RTRIM(F.OWNER)) ELSE INSTR(F.OWNER, '','') - 1 END) = G.USER_ID(+)' || CHR(10)));
        /********** DEPT NAME END **********/

        /* 20220125 vadabi3 DC Link Sort 적용 (Rack_YN, DC_YN Sort 적용) */
        DBMS_LOB.APPEND(V_EXEC, TO_CLOB(
            '   AND V.DIVISION_ID(+)         = A.DIVISION_ID' || CHR(10)
         || '   AND V.ITEM_ID(+)             = A.ITEM_ID' || CHR(10)
         || '   AND V.OPERATION_GROUP_ID(+)  = A.OPERATION_GROUP' || CHR(10)
         || '   AND V.DIVISION_ID(+)         = :B_DIVISION_ID' || CHR(10)   /* 품목 뷰를 조회 사업부로 한정 (적재 자료는 모두 조회 사업부) */   --  2026.10.06 AJS
         || ' ORDER BY A.DIVISION_ID' || CHR(10)
         || '        , A.CELL_ITEM_ID' || CHR(10)
         || '        , A.OPERATION_GROUP DESC NULLS LAST' || CHR(10)
         || '        , V.RACK_YN DESC NULLS LAST' || CHR(10)
         || '        , V.DC_YN DESC NULLS LAST' || CHR(10)
         || '        , CELL_TYPE_SORT' || CHR(10)
         || '        , A.ITEM_ID' || CHR(10)
         || '        , A.ATTRIBUTE10 NULLS FIRST' || CHR(10)
         || '        , NLSSORT(A.TO_SITE, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)
         || '        , A.INCOTERMS' || CHR(10)
         || '        , A.FROM_SITE' || CHR(10)
         || '        , A.SORT_ORDER_NO NULLS FIRST' || CHR(10)
         || '        , A.TRANSPORT_MODE_LINE' || CHR(10)
         || '        , A.BOD_ID' || CHR(10)
         || '        , NLSSORT(A.MEASURE_LABEL, ''NLS_SORT=BINARY_CI'') DESC NULLS LAST' || CHR(10)));

--        OPEN O_RC1 FOR V_EXEC;                                                                   --  2026.10.06 AJS
        OPEN O_RC1 FOR V_EXEC USING P_DIVISION_ID;                                                   --  2026.10.06 AJS

        DBMS_LOB.FREETEMPORARY(V_QRY_SUM);

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SCP0031_GET_GLOBAL_PSI;

END PKG_SCP0031;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0031
-- ##### END PACKAGE BODY PKG_SCP0031

-- ##### START PACKAGE BODY PKG_SCP0039
CREATE OR REPLACE PACKAGE BODY PKG_SCP0039
IS

    /************************************************************************************************/
    /* [공통] GTT 통계 수집 - CNS 전환가이드 7항                                                     */
    /*        GTT 는 통계가 없으면 옵티마이저가 1행으로 보고 NESTED LOOP 를 골라 조회가 폭주한다.    */
    /*        세션 레벨 통계이므로 다른 세션에 영향을 주지 않는다.                                   */
    /************************************************************************************************/
    PROCEDURE P_GATHER
    (
        P_TAB_NAME  IN VARCHAR2
    )
    IS
        V_ROWS  NUMBER := SQL%ROWCOUNT;   /* 직전 INSERT 건수 (호출 직전 문장 기준) */   /* AJS 20261007 속도 */
    BEGIN
        /* 넣은 행이 없으면 통계 수집을 생략한다(수집 1회 약 1,800블록 · 결과 영향 없음).
           1,000건 기준(CNS 가이드 7항)으로 줄이면 소량 GTT 통계가 빠져 계획이 나빠지는 것을 실측해 0건만 생략한다 */   /* AJS 20261007 속도 */
        IF NVL(V_ROWS, 0) = 0 THEN   /* AJS 20261007 속도 */
            RETURN;   /* AJS 20261007 속도 */
        END IF;   /* AJS 20261007 속도 */
--        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => USER
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME       => $$PLSQL_UNIT_OWNER   -- 2026.09.16 AJS
                                    , TABNAME       => P_TAB_NAME
                                    , NO_INVALIDATE => FALSE);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;   /* 통계 수집 실패가 조회를 막지 않도록 한다 */
    END P_GATHER;

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD');

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCP_PLAN_OPERATION');

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;
        P_GATHER('GT_0039_PLAN_GROUP_LINE');

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');
        P_GATHER('GT_0039_ITEM_LINE_ASSIGN');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;
        P_GATHER('GT_0039_PLAN_GR_LINE_MODEL');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';
        P_GATHER('GT_0039_PG_LINE_MDL_BSC_NICK');

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        P_GATHER('GT_0039_PLAN_GROUP_INFO');

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_AS_SITE_PLANT');

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';
        P_GATHER('GT_0039_CFM_MKT_DMND_PLAN');

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
        V_CFM_CNT  NUMBER;   /* AJS 20261007 속도 */
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        /* 이 목록은 CELL_PROD_SITE_ID 외부조인(이름 표시)에만 쓰이고, CELL_PROD_SITE_ID 값은 모두
           GT_0039_CFM_MKT_DMND_PLAN 에서 온다. 그 테이블이 비어 있으면 조인이 맞을 행이 없으므로
           품목 원장 전체 읽기를 생략한다(사업부 81 · 82 는 항상 비어 있음) */   /* AJS 20261007 속도 */
        SELECT COUNT(*)   /* AJS 20261007 속도 */
          INTO V_CFM_CNT   /* AJS 20261007 속도 */
          FROM GT_0039_CFM_MKT_DMND_PLAN   /* AJS 20261007 속도 */
         WHERE ROWNUM = 1;   /* AJS 20261007 속도 */

        IF V_CFM_CNT = 0 THEN   /* AJS 20261007 속도 */
            RETURN;   /* AJS 20261007 속도 */
        END IF;   /* AJS 20261007 속도 */

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';
        P_GATHER('GT_0039_CELL_PROD_SITE_ID');

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;
        P_GATHER('GT_0039_ELEC_APPLIED_MODEL');

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_TGT_DATA_PLAN_GROUP');

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN TO_CHAR(SYSDATE - 45, 'YYYYMMDD')
                            AND TO_CHAR(SYSDATE     , 'YYYYMMDD')
           AND DAYOFWEEK = 'SUN';
        P_GATHER('GT_0039_TARGET_SUNDAY');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_PACKER_SITE_INFO');

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;
        P_GATHER('GT_0039_PACKER_UPLOAD_ITEM_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_MKT_FCST_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_GATHER('GT_0039_SCP_FINAL_OPERATION');
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;
        P_GATHER('GT_0039_BOM_CHILD_CNT');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );
        P_GATHER('GT_0039_BOM_CHILD_CNT_0');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';
        P_GATHER('GT_0039_BOM_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;
        P_GATHER('GT_0039_ITEM_TYPE_IS_NULL');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '40';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '40' 고정 - 40만 조회 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := '82';   /* AS-IS 원문 그대로 : @p_division_id 가 아니라 '82' 고정 - 김도형선임 (2025.07.15) */
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_PRE_NOT_EXISTS');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM SCP_ANL_PRODUCTION_PLAN B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.ORIGIN_DIVISION_ID  = V_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        P_GATHER('GT_0039_TARGET_CASE2');
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        P_GATHER('GT_0039_TARGET_CASE3');
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN A
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_SCP_PROD_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;
        P_GATHER('GT_0039_TARGET_CASE4');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;
        P_GATHER('GT_0039_TARGET_CASE5');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';
        P_GATHER('GT_0039_CELL_PROD_ASSY_MAP');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND NVL(B.CELL_TYPE, ' ') NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        P_GATHER('GT_0039_FP_TACT_TIME');
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME');

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';
        P_GATHER('GT_0039_SCP_TACT_TIME_EXCEPT');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;
        P_GATHER('GT_0039_LINE_ASSIGN_MODEL');

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );
        P_GATHER('GT_0039_TT_CASE_3');

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_MKT_FCST_MDL_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL');

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(D.ATTRIBUTE8, ' ') NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);
        P_GATHER('GT_0039_LINE_ASSIGN_CELL_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= TO_CHAR(SYSDATE, 'YYYYMMDD');
        P_GATHER('GT_0039_PROJECT_ROUTE_ELEC');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );
        P_GATHER('GT_0039_TT_CASE_4');

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );
        P_GATHER('GT_0039_TT_CASE_4_2');

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE A.DIVISION_ID         = V_PLAN_DIVISION
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND A.PLAN_TYPE           = V_PLAN_TYPE
           AND A.SEQ                 = V_PLAN_SEQ
           AND A.YYYYMMDD           <= V_HORIZON_END
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= TO_CHAR(SYSDATE, 'YYYYMM')
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);
        P_GATHER('GT_0039_TT_CASE_5');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;
        P_GATHER('GT_0039_TARGET_DATA');

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
        V_PLAN_DIVISION  VARCHAR2(30 CHAR);
        V_PLAN_TYPE      VARCHAR2(50 CHAR);
        V_PLAN_SEQ       NUMBER;
        V_PLAN_START     VARCHAR2(8  CHAR);
        V_HORIZON_END    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';
        P_GATHER('GT_0039_SCM_MST_SITE_FROM');

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;
        P_GATHER('GT_0039_SCM_MST_SITE_TO');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;
        P_GATHER('GT_0039_MKT_FCST');

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND NVL(C.ATTRIBUTE8, ' ') NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );
        P_GATHER('GT_0039_SCP_BOM');

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_PROJECT_ROUTE');

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );
        P_GATHER('GT_0039_PR_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;
        P_GATHER('GT_0039_BOD');

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';
        P_GATHER('GT_0039_TRANSPORT_MODE');

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        P_GATHER('GT_0039_FROM_SITE_BY_PR');
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );
        P_GATHER('GT_0039_BOD_NOT_EXISTS');

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;
        P_GATHER('GT_0039_SCP_PLAN_VERSION');

        /* 계획 버전은 PLAN_PRIORITY = 1 로 한 건이다. GTT 와 조인하면 대용량 파티션 테이블에
           파티션 프루닝이 걸리지 않아 조회가 폭주하므로, 값을 변수로 받아 상수 조건으로 준다. */
        SELECT MAX(DIVISION_ID)
             , MAX(PLAN_TYPE)
             , MAX(PLAN_SEQ)
             , MAX(PLAN_START_YYYYMMDD)
             , MAX(HORIZON_END_DATE)
          INTO V_PLAN_DIVISION
             , V_PLAN_TYPE
             , V_PLAN_SEQ
             , V_PLAN_START
             , V_HORIZON_END
          FROM GT_0039_SCP_PLAN_VERSION;


        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_FG');

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = V_PLAN_DIVISION
           AND B.PLAN_START_YYYYMMDD = V_PLAN_START
           /* 파티션 프루닝용 조건. 파티션 키 PLAN_START_YYYYMMDD_DATE 는
              TO_DATE(PLAN_START_YYYYMMDD,'YYYYMMDD') 로 만든 가상 컬럼이라 결과는 달라지지 않는다. */
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START, 'YYYYMMDD')
           AND B.PLAN_TYPE           = V_PLAN_TYPE
           AND B.SEQ                 = V_PLAN_SEQ
           AND B.YYYYMMDD           <= V_HORIZON_END
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;
        P_GATHER('GT_0039_SHIP_PLAN_SEMI');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;
        P_GATHER('GT_0039_INVALID_BOD_SHIP_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;
        P_GATHER('GT_0039_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;
        P_GATHER('GT_0039_TARGET_DATA_BC_NICK');

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;
        P_GATHER('GT_0039_INTRANSIT_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;
        P_GATHER('GT_0039_SALES_SITE_INVENTORY');

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;
        P_GATHER('GT_0039_DEMAND_PLAN');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;
        P_GATHER('GT_0039_INT_TGT_CASE_1');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );
        P_GATHER('GT_0039_INT_TGT_CASE_2');

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           /* ★AS-IS 와 결과가 갈리는 자리 (구조적으로 재현 불가)
              F_DEST_ATA_DATE 는 이관 시 빈 문자열이 NULL 로 들어와 MSSQL 의 '빈 문자열' 과
              '진짜 NULL' 을 Oracle 에서 구분할 수 없다. AS-IS 는 진짜 NULL 만 미착으로 보아
              빈 문자열 건을 제외하지만(82 기준 8,197 건), 업무 의미로는 값이 비었으면 미착이므로
              아래 조건은 그 건을 포함한다. 포함 여부는 업무 확정 후 조정할 것. */
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        P_GATHER('GT_0039_INT_TGT_CASE_3');
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;
        P_GATHER('GT_0039_INT_TARGET_DATA');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;
        P_GATHER('GT_0039_INT_TGT_BC_NICK');

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;
        P_GATHER('GT_0039_INT_TGT_PLAN_GROUP');

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;
        P_GATHER('GT_0039_BOD_II');

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
--               , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST   --  2026.10.07 AJS
                 , ( SELECT DISTINCT '%' || UPPER(TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL))) || '%' AS TST   --  2026.10.07 AJS
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0) ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_SCP0039;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0039
-- ##### END PACKAGE BODY PKG_SCP0039

-- ##### START PACKAGE BODY PKG_SCP0039_VF
CREATE OR REPLACE PACKAGE BODY PKG_SCP0039_VF
IS

    /************************************************************************************************/
    /* [공통] 기준 일자 정보 - 당주 월요일(plan_start_yyyymmdd) 과 plan horizon_end_date            */
    /************************************************************************************************/
    PROCEDURE P_SET_BASE_DATE
    (
        P_DIVISION_ID     IN  VARCHAR2,
        O_FROM_YYYYMMDD   OUT VARCHAR2,
        O_TO_YYYYMMDD     OUT VARCHAR2
    )
    IS
    BEGIN

        /* 당주 월요일 (plan_start_yyyymmdd) */
        SELECT MAX(B.YYYYMMDD)
          INTO O_FROM_YYYYMMDD
          FROM SCM_MST_BUCKET A
             , SCM_MST_BUCKET B
         WHERE B.YYYYWW = A.YYYYWW
           AND B.DAYOFWEEK = 'MON'
           AND A.YYYYMMDD = '20260824';

        /* plan horizon_end_date */
        SELECT MAX(HORIZON_END_DATE)
          INTO O_TO_YYYYMMDD
          FROM SCM_MST_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND PLAN_NAME   = O_FROM_YYYYMMDD
           AND PLAN_CYCLE  = 'WEEKLY';

    END P_SET_BASE_DATE;

    /************************************************************************************************/
    /* [공통] SCP Plan 공정 정보 (2025.08.14 추가)                                                  */
    /************************************************************************************************/
    PROCEDURE P_LOAD_SCP_PLAN_OPERATION
    IS
    BEGIN

        DELETE FROM GT_0039_SCP_PLAN_OPERATION;

        INSERT INTO GT_0039_SCP_PLAN_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND VALID_YN    = 'Y';

    END P_LOAD_SCP_PLAN_OPERATION;

    /************************************************************************************************/
    /* [공통] Plan Group 정보 (Plan Group Line -> Item Line Assign -> Line Model -> Basic Nick)      */
    /************************************************************************************************/
    PROCEDURE P_LOAD_PLAN_GROUP_INFO
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_PLAN_GROUP_LINE;
        DELETE FROM GT_0039_ITEM_LINE_ASSIGN;
        DELETE FROM GT_0039_PLAN_GR_LINE_MODEL;
        DELETE FROM GT_0039_PG_LINE_MDL_BSC_NICK;
        DELETE FROM GT_0039_PLAN_GROUP_INFO;

        /* Plan Group Line 정보 */
        INSERT INTO GT_0039_PLAN_GROUP_LINE
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
        )
        SELECT B.OPMZ_PLAN_GR_ID
             , B.OPMZ_PLAN_GR_NAME
             , B.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , A.ITEM_ID
          FROM SCP_OPMZ_PLAN_GR_LINE_M A
             , SCP_OPMZ_PLAN_GR_M      B
         WHERE B.OPMZ_PLAN_GR_ID = A.OPMZ_PLAN_GR_ID
           AND B.VALID_YN = 'Y'
           /* PJ20257329 2025.09.12 변경전  INNER JOIN SCM_MST_DIVISION DM ON DM.DIVISION_ID = GM.DIVISION_ID AND DM.ATTRIBUTE3 = '81' */
           AND B.DIVISION_ID = P_DIVISION_ID
           AND A.VALID_YN = 'Y'
         ORDER BY A.LINE_ID;

        /* ITEM Line Assign 정보 */
        INSERT INTO GT_0039_ITEM_LINE_ASSIGN
        (
            DIVISION_ID
          , PLANT_ID
          , FACTORY_ID
          , OPERATION_ID
          , LINE_ID
          , ITEM_ID
        )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN  A
             , GT_0039_SCP_PLAN_OPERATION   B   /* 2025.08.14 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE B.OPERATION_ID = A.OPERATION_ID
           AND A.ACTIVE_FLAG = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(P_FROM_YYYYMMDD, 1, 6) AND SUBSTR(P_TO_YYYYMMDD, 1, 6)   /* 2025.08.14 당월부터 plan horizon end date 까지 참조 */
           AND A.PRIORITY NOT IN ('0', '9');

        /* Plan Group Line Model 정보 */
        INSERT INTO GT_0039_PLAN_GR_LINE_MODEL
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID
             , SUBSTR(A.OPERATION_ID, 1, 1)  AS OPERATION_GROUP
          FROM GT_0039_PLAN_GROUP_LINE  A
             , GT_0039_ITEM_LINE_ASSIGN B
         WHERE B.LINE_ID      = A.LINE_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = CASE WHEN A.ITEM_ID = '/'
                                     THEN B.ITEM_ID
                                     ELSE A.ITEM_ID
                                END;

        /* Plan Group Line Model / Cell model Basic Nick name 정보 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , SUBSTR(A.OPMZ_PLAN_GR_NAME, 1, 100)  AS OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , SUBSTR(A.ITEM_ID, 1, 100)            AS ITEM_ID
             , A.OPERATION_GROUP
             , SUBSTR(E.BASIC_NICK_NAME, 1, 500)    AS BASIC_NICK_NAME
          FROM GT_0039_PLAN_GR_LINE_MODEL A
             , SCP_MST_FINAL_ITEM         B    /* Final Pack */
             , SCP_MST_ITEM_BSI_IFO       C    /* Doe model */
             , SCP_MST_FINAL_ITEM         D
             , SCP_MST_ITEM_BSI_IFO       E    /* Cell Model 기준 Basic nick name 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.ITEM_ID(+)     = C.APPLIED_DOE
           AND E.ITEM_ID(+)     = CASE WHEN A.OPERATION_GROUP = 'P'
                                       THEN NVL(B.ATTRIBUTE1, D.ATTRIBUTE1)
                                       ELSE A.ITEM_ID
                                  END;

        /* Plan Group Line Model / Cell model Basic Nick name 정보 - Cell Product 추가 */
        INSERT INTO GT_0039_PG_LINE_MDL_BSC_NICK
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , DIVISION_ID
          , LINE_ID
          , FACTORY_ID
          , PLANT_ID
          , OPERATION_ID
          , ITEM_ID
          , OPERATION_GROUP
          , BASIC_NICK_NAME
        )
        SELECT A.OPMZ_PLAN_GR_ID
             , A.OPMZ_PLAN_GR_NAME
             , A.DIVISION_ID
             , A.LINE_ID
             , A.FACTORY_ID
             , A.PLANT_ID
             , A.OPERATION_ID
             , B.ITEM_ID_PROD   AS ITEM_ID_PROD
             , A.OPERATION_GROUP
             , A.BASIC_NICK_NAME
          FROM GT_0039_PG_LINE_MDL_BSC_NICK A
             , SCP_MST_CELL_PROD_ASSY_MAP   B
         WHERE B.DIVISION_ID  = A.DIVISION_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.ITEM_ID_ASSY = A.ITEM_ID
           AND B.VALID_YN = 'Y'                 /* 2025.07.24 추가(김혜라 C) */
           AND A.OPERATION_GROUP = 'A';

        /* PLAN_GROUP_INFO 임시테이블 */
        INSERT INTO GT_0039_PLAN_GROUP_INFO
        (
            ITEM_ID
          , DIVISION_ID
          , LINE_ID
          , OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , BASIC_NICK_NAME
          , RN
          , RN_NICK
        )
        SELECT ITEM_ID
             , DIVISION_ID
             , LINE_ID
             , OPMZ_PLAN_GR_ID
             , OPMZ_PLAN_GR_NAME
             , BASIC_NICK_NAME
             , ROW_NUMBER() OVER (PARTITION BY ITEM_ID
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN
             , ROW_NUMBER() OVER (PARTITION BY BASIC_NICK_NAME
                                             , DIVISION_ID
                                      ORDER BY OPMZ_PLAN_GR_ID DESC
                                             , LINE_ID DESC)   AS RN_NICK
          FROM GT_0039_PG_LINE_MDL_BSC_NICK;

    END P_LOAD_PLAN_GROUP_INFO;

    /************************************************************************************************/
    /* [공통] AS_SITE_PLANT - PJ20257329 2025.09.05 AS Sales Site 제외                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_AS_SITE_PLANT
    IS
    BEGIN

        DELETE FROM GT_0039_AS_SITE_PLANT;

        INSERT INTO GT_0039_AS_SITE_PLANT
        (
            SCM_SITE_ID
          , DIVISION_ID
        )
        SELECT DISTINCT
               SEGMENT1  AS SCM_SITE_ID
             , SEGMENT3  AS DIVISION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'AS_SITE_PLANT'
           AND VALID_YN    = 'Y';

    END P_LOAD_AS_SITE_PLANT;

    /************************************************************************************************/
    /* [공통] MKT FCST Cell Prod Site 정보 - PJ20257329 2025.09.12 소형 Cell Prod Site 적용          */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CFM_MKT_DEMAND_PLAN
    (
        P_DIVISION_ID     IN VARCHAR2,
        P_FROM_YYYYMMDD   IN VARCHAR2,
        P_TO_YYYYMMDD     IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_CFM_MKT_DMND_PLAN;

        INSERT INTO GT_0039_CFM_MKT_DMND_PLAN
        (
            DIVISION_ID
          , PROJECT_CODE
          , SCM_SITE_ID
          , ITEM_ID
          , DOM_EXP
          , FCST_TYPE
          , INCOTERMS
          , MEASURE
          , YYYYMMDD
          , PLANT_SITE_ID
          , CELL_PROD_SITE_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , RN
        )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.YYYYMMDD
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , CASE WHEN B.OSP_YN = 'Y'
                    THEN B.LOGISTIC_PLANT_ID
                    ELSE B.PLANT_ID
               END                              AS PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PROJECT_CODE
                                             , A.SCM_SITE_ID
                                             , A.ITEM_ID
                                             , A.DOM_EXP
                                             , A.FCST_TYPE
                                             , A.INCOTERMS
                                             , A.MEASURE
                                             , A.YYYYMMDD
                                             , A.PLANT_SITE_ID
                                      ORDER BY A.CELL_PROD_SITE_ID)  AS RN
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.CELL_PROD_SITE_ID
           AND A.DIVISION_ID = CASE WHEN P_DIVISION_ID = '40'   /* 소형 전용 */
                                    THEN P_DIVISION_ID
                                    ELSE NULL
                               END
           AND A.MEASURE IN ('MKT_FCST', 'VMI_In_Req', 'AS_In_Req')
           AND A.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
           /* AS-IS : CELL_PROD_SITE_ID NOT IN ('-', '')
              이관 시 빈값은 '-' 또는 공백으로 들어오므로 NULL·공백·'-' 를 모두 제외한다 */
           AND TRIM(A.CELL_PROD_SITE_ID) IS NOT NULL
           AND A.CELL_PROD_SITE_ID != '-';

    END P_LOAD_CFM_MKT_DEMAND_PLAN;

    /************************************************************************************************/
    /* [공통] CELL_PROD_SITE_ID 공통코드 목록                                                       */
    /*        AS-IS : EXEC UP_FX_GetCommonDataList @Code='CELL_PROD_SITE_ID' (파라미터 전부 NULL)    */
    /*        -> 해당 갈래(@PARAM1 이 빈 값)의 조회문을 그대로 옮긴다.                                */
    /************************************************************************************************/
    PROCEDURE P_LOAD_CELL_PROD_SITE_ID
    IS
    BEGIN

        DELETE FROM GT_0039_CELL_PROD_SITE_ID;

        INSERT INTO GT_0039_CELL_PROD_SITE_ID
        (
            CODE
          , NAME
        )
        /* [PJ2025-50188] 고도화 - Common 도 Lookup 으로 가져오도록 수정 */
        /* 기본적으로 사용되는 CODE '-' 를 강제로 추가 */
        SELECT SEGMENT1   AS CODE
             , ATTRIBUTE1 AS NAME
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND SEGMENT1    = '-'
           AND VALID_YN    = 'Y'
         UNION ALL
        /* 현재 사용 중인 모든 셀생산지 리스트 가져오기 */
        SELECT DISTINCT
               A.SCM_SITE_ID  AS CODE
             , C.ATTRIBUTE1   AS NAME
          FROM SCM_MST_SITE                  A
             , ( SELECT DISTINCT IA.DIVISION_ID, IA.COMPANY_ID, IA.SCP_OPERATION_GROUP
                   /* [C20200608-000328] SALESCOMPANY 콤보는 ITEM MASTER 의 COMPANY ID, OPERATION GROUP 기준으로 조회 */
                   FROM SCM_MST_ITEM_SN IA
                  WHERE IA.ACTIVE_FLAG = 'Y'
                    AND IA.ITEM_TYPE IS NOT NULL
                    AND IA.FORECAST_INFO_BIZ_TYPE = 'CELL' ) B
             , SCM_ADM_LOOKUP_MASTER_DETAIL  C
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.OPERATION_GROUP = B.SCP_OPERATION_GROUP
           AND A.COMPANY_ID      = B.COMPANY_ID
           AND C.LOOKUP_TYPE = 'SP_CELL_PROD_SITE'
           AND A.SCM_SITE_ID = C.SEGMENT1
           AND C.VALID_YN    = 'Y'
           AND A.SITE_TYPE       = 'PLANT'
           AND A.OPERATION_GROUP = 'A'
           AND A.OSP_YN          = 'N';

    END P_LOAD_CELL_PROD_SITE_ID;

    /************************************************************************************************/
    /* [공통] 전극 Applied Cell Model                                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_ELEC_APPLIED_MODEL
    (
        P_DIVISION_ID  IN VARCHAR2
    )
    IS
    BEGIN

        DELETE FROM GT_0039_ELEC_APPLIED_MODEL;

        INSERT INTO GT_0039_ELEC_APPLIED_MODEL
        (
            DIVISION_ID
          , ITEM_ID
          , APPLIED_MODEL
          , RN
        )
        SELECT IA.DIVISION_ID
             , IA.ITEM_ID
             , IA.APPLIED_MODEL
             , IA.RN
          FROM ( SELECT A.DIVISION_ID
                      , A.ITEM_ID
                      , B.APPLIED_MODEL
                      , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                                      ,A.ITEM_ID
                                               ORDER BY CASE WHEN C.ATTRIBUTE3 = '81' AND A.ITEM_ID LIKE 'A%' THEN 1
                                                             WHEN C.ATTRIBUTE3 = '40' AND A.ITEM_ID LIKE 'M%' THEN 2
                                                             WHEN C.ATTRIBUTE3 = '82' AND A.ITEM_ID LIKE 'M%' THEN 3
                                                             ELSE 9
                                                        END)  AS RN
                   FROM SCP_MST_FINAL_ITEM A
                      , SCM_MST_ITEM_SN    B
                      , SCM_MST_DIVISION   C
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.ITEM_ID     = A.ITEM_ID
                    AND C.DIVISION_ID = A.DIVISION_ID
                    AND B.ACTIVE_FLAG = 'Y'
                    AND NVL(B.APPLIED_MODEL, 'Z') != 'Z'
                    AND A.DIVISION_ID     = P_DIVISION_ID
                    AND A.OPERATION_GROUP = 'E' ) IA
         WHERE IA.RN = 1;

    END P_LOAD_ELEC_APPLIED_MODEL;

    /************************************************************************************************/
    /* [공통] 확인 대상 전체 데이터 - Plan Group 매핑                                               */
    /************************************************************************************************/
    PROCEDURE P_LOAD_TARGET_DATA_PLAN_GROUP
    IS
    BEGIN

        DELETE FROM GT_0039_TGT_DATA_PLAN_GROUP;

        INSERT INTO GT_0039_TGT_DATA_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
          , YIELD
          , FROM_UI
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_MSG
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
             , A.YIELD
             , A.FROM_UI
          FROM GT_0039_TARGET_DATA_BC_NICK A
             , GT_0039_PLAN_GROUP_INFO     B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO     C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.MODEL_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

    END P_LOAD_TARGET_DATA_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_STOCK_OSP                                               */
    /* Description : Stock OSP 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh   Initial Release PJ2024A332R                                                 */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_STOCK_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
    BEGIN

/*
--================================================================================================================================
### Stock OSP 요구사항

1) 협력사별 자료 업로드 여부 (DIVISION PLANT(패커사별)별)
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_SUNDAY;
        DELETE FROM GT_0039_PACKER_SITE_INFO;
        DELETE FROM GT_0039_PACKER_UPLOAD_ITEM_CNT;

        /* ---------------------------------------------------------------------------------------- */
        /* UPLOAD 재고 기준 일자 - 일요일                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_SUNDAY';
        INSERT INTO GT_0039_TARGET_SUNDAY
        (
            YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT YYYYMMDD
             , 'D_' || YYYYMMDD  AS D_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY 'A' ORDER BY YYYYMMDD DESC)  AS YMD_SEQ
          FROM SCM_MST_BUCKET
         WHERE YYYYMMDD BETWEEN '20260710'
                            AND '20260824'
           AND DAYOFWEEK = 'SUN';

        /* ---------------------------------------------------------------------------------------- */
        /* Packer Site                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_SITE_INFO';
        INSERT INTO GT_0039_PACKER_SITE_INFO
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ATTRIBUTE1
          , ATTRIBUTE2
          , YYYYMMDD
          , D_YYYYMMDD
          , YMD_SEQ
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , B.YYYYMMDD
             , B.D_YYYYMMDD
             , B.YMD_SEQ
          FROM SCM_MST_SITE          A
             , GT_0039_TARGET_SUNDAY B
         WHERE 1 = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.OSP_YN      = 'Y'
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* Packer 별 Upload Item 건수                                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PACKER_UPLOAD_ITEM_CNT';
        INSERT INTO GT_0039_PACKER_UPLOAD_ITEM_CNT
        (
            DIVISION_ID
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , W0
          , W0_LAST_UPDATE_DATE
          , W0_ITEM_COUNT
          , "W-1_ITEM_COUNT"
          , "W-2_ITEM_COUNT"
          , "W-3_ITEM_COUNT"
          , "W-4_ITEM_COUNT"
          , MASTER_INVLD_CD
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.SITE_DESCRIPTION
             , MAX(CASE WHEN A.YMD_SEQ = 1 THEN A.YYYYMMDD ELSE NULL END)                       AS W0
             , NVL(MAX(DISTINCT CASE WHEN A.YMD_SEQ = 1
                                     THEN TO_CHAR(B.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS')
                                     ELSE NULL
                                END), '미입력')                                                 AS W0_LAST_UPDATE_DATE
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END)             AS W0_ITEM_COUNT
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 2 THEN B.ITEM_ID ELSE NULL END)             AS "W-1_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 3 THEN B.ITEM_ID ELSE NULL END)             AS "W-2_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 4 THEN B.ITEM_ID ELSE NULL END)             AS "W-3_ITEM_COUNT"
             , COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 5 THEN B.ITEM_ID ELSE NULL END)             AS "W-4_ITEM_COUNT"
             , CASE WHEN COUNT(DISTINCT CASE WHEN A.YMD_SEQ = 1 THEN B.ITEM_ID ELSE NULL END) = 0
                    THEN 'SP001'
                    ELSE NULL
               END                                                                              AS MASTER_INVLD_CD
          FROM GT_0039_PACKER_SITE_INFO A
             , SCM_DNM_STOCK_OSP        B   /* DIVISION_ID, SCM_SITE_ID, ITEM_ID, YYYYMMDD, ATTRIBUTE1, ATTRIBUTE2 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.YYYYMMDD(+)    = A.YYYYMMDD
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.SITE_DESCRIPTION
         ORDER BY A.SITE_DESCRIPTION;

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 결과 조회                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.SITE_DESCRIPTION
                 , A.W0
                 , A.W0_LAST_UPDATE_DATE
                 , A.W0_ITEM_COUNT
                 , A."W-1_ITEM_COUNT"
                 , A."W-2_ITEM_COUNT"
                 , A."W-3_ITEM_COUNT"
                 , A."W-4_ITEM_COUNT"
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                 AS MASTER_INVLD_MSG
              FROM GT_0039_PACKER_UPLOAD_ITEM_CNT  A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y';

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_STOCK_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PLAN_GROUP                                              */
    /* Description : Plan Group 조회                                                                */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 MKT FCST 최종 수정일시 추가, plan group 미매핑 데이터만 조회   */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PLAN_GROUP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);   /* 당주 월요일 (plan_start_yyyymmdd) */
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);   /* horizon_end_date */
    BEGIN

/*
--================================================================================================================================
### Plan Group  요구사항

1) CURRENT MKT FCST DP에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 Plan Group이 설정되어 있지 않은 경우

※1. Plan Group 입력 영향을 받지 않고 모두 조회함
※2. 81 like division은 기입력된 plan group 의 모델정보를 활용하여 수요의 모델을 엮을것.
    : 로직은 left 12 / distinct
※3. 2번로직으로 찾은 모델은 PLAN GROUP에 '(예상)' 추가하여 송출함

* 40 / 82 는 최적화 확장시에 논의하여 결정필요..
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , BASIC_CELL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.DIVISION_ID
             , A.SCM_SITE_ID                      AS SALES_SITE_ID
             , A.PROJECT_CODE                     AS PROJECT_CODE
             , A.ITEM_ID                          AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)            AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP                  AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                        AS MODEL_NICK_NAME
             , F.BASIC_NICK_NAME                  AS BASIC_CELL_NICK_NAME
             , MIN(A.YYYYMMDD)                    AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                    AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                         AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , SCP_MST_ITEM_BSI_IFO   D   /* Doe model */
             , SCP_MST_FINAL_ITEM     E
             , SCP_MST_ITEM_BSI_IFO   F   /* Cell Model 기준 Basic nick name 참조 */
             , GT_0039_AS_SITE_PLANT  G   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.ITEM_ID(+)     = A.ITEM_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.ITEM_ID(+)     = D.APPLIED_DOE
           AND F.ITEM_ID(+)     = CASE WHEN C.OPERATION_GROUP = 'P'
                                       THEN NVL(C.ATTRIBUTE1, E.ATTRIBUTE1)
                                       ELSE A.ITEM_ID   /* sales_item_id */
                                  END
           AND G.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND G.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND G.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.DIVISION_ID
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , F.BASIC_NICK_NAME;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST Plan group 매핑                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_PLAN_GROUP';
        INSERT INTO GT_0039_MKT_FCST_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID
          , OPMZ_PLAN_GR_NAME
          , LINE_ID
          , BASIC_NICK_NAME
          , DV
          , BASIC_CELL_NICK_NAME
          , DIVISION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME
             , A.DIVISION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
          FROM GT_0039_MKT_FCST         A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.SALES_ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* 최종 확인 필요 대상 조회 - Plan Group 미등록                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.SALES_ITEM_ID                  AS ITEM_ID
                 , A.MODEL_NICK_NAME                AS NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.DV                             AS PLAN_GROUP_MAPPING_DV
                 , B.SEGMENT1                       AS MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , C.SITE_DESCRIPTION               AS SALES_PLANT_SITE
                 , A.PROJECT_CODE                   AS PROJECT_OPERATION
                 , A.INCOTERMS                      AS INCOERMS_LINE
                 , A.QTY
                 , 'Sales기간:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
                                || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE
                                || ', Sales Site:'        || A.SALES_SITE_ID
                                                    AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
              FROM GT_0039_MKT_FCST_PLAN_GROUP  A
                 , SCM_MST_SITE                 C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE C.DIVISION_ID = V_DIVISION_ID
               AND C.SCM_SITE_ID = A.SALES_SITE_ID
               /* AS-IS 는 ON 절에 ISNULL(OPMZ_PLAN_GR_ID,'-')='-' 를 두었으나 아래 WHERE 조건과 동일하므로 생략 */
               AND B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = 'PG001'
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.SALES_ITEM_ID   LIKE IA.TST
                  OR A.MODEL_NICK_NAME LIKE IA.TST )
               AND NVL(A.OPMZ_PLAN_GR_ID, '-') = '-'   /* 2025.08.14 plan group 매핑이 안되는 데이터만 조회 */
             ORDER BY A.DIVISION_ID
                    , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                           WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                           ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                      END
                    , A.MODEL_OPERATION_GROUP
                    , A.MODEL_NICK_NAME
                    , A.SALES_ITEM_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PLAN_GROUP;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_YIELD                                                   */
    /* Description : 수율 조회                                                                      */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 SCP 완성공정 조건 하드코딩 lookup 데이터 참조로 변경           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_YIELD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### 수율 요구사항
------------------------------------------------------------------------------
1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
 >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우

2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
  >> 활성화/특성 공정의 수율이 50% 미만인경우"

### 메시지
------------------------------------------------------------------------------
1) CAPA 수율이 50%미만으로 낮습니다. 확인필요합니다.
2) FORMATION 수율이 50%미만으로 낮습니다. 확인필요합니다."
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        /* [PJ20257329] 2025.08.26 SCP 완성 공정 하드 코딩 변경 (임시 테이블) */
        V_STEP := 'SCP_FINAL_OPERATION';
        DELETE FROM GT_0039_SCP_FINAL_OPERATION;

        INSERT INTO GT_0039_SCP_FINAL_OPERATION
        (
            OPERATION_ID
        )
        SELECT DISTINCT SEGMENT1  AS OPERATION_ID
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
           AND ATTRIBUTE1  = 'Y';   /* Final Operation */

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        /*
         1) CURRENT CAPA 입력되어 있는 'LINE', '모델' 정보를 기반으로
         >> E2000, A9000, P5500, P9500 공정의 수율이 50% 미만인경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID                    AS MODEL_ID
             , C.NICK_NAME
             , 'YLD01'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , A.OPERATION_ID               AS PROJECT_OPERATION
             , A.LINE_ID                    AS INCOTERMS_LINE
             , A.YIELD
             , 'CAPA'                       AS FROM_UI
             , 'Min/Max Month : ' || MIN(A.MONTH) || '/' || MAX(A.MONTH)  AS MASTER_INVLD_CTN
          FROM SCM_MST_YIELD_SN            A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID, ITEM_ID, MONTH */
             , SCM_MST_SITE                B
             , SCP_MST_FINAL_ITEM          C
             , GT_0039_SCP_FINAL_OPERATION D   /* PJ20257329 2025.08.26 완성 공정 하드 코딩 변경 */
         WHERE B.DIVISION_ID     = A.DIVISION_ID
           AND B.PLANT_ID        = A.PLANT_ID
           AND B.OPERATION_GROUP = SUBSTR(A.OPERATION_ID, 1, 1)
           AND B.COMPANY_ID      = A.COMPANY_ID
           AND C.DIVISION_ID     = A.DIVISION_ID
           AND C.ITEM_ID         = A.ITEM_ID
           AND D.OPERATION_ID    = A.OPERATION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
           AND NVL(A.YIELD, 1) < 0.5
         GROUP BY A.DIVISION_ID
                , A.ITEM_ID
                , C.NICK_NAME
                , B.SITE_DESCRIPTION
                , A.OPERATION_ID
                , A.LINE_ID
                , A.YIELD
                , B.SCM_SITE_ID
         UNION ALL
        /*
        2) CURRENT FORMATION 입력되어 있는 'LINE', '모델' 정보를 기반으로
          >> 활성화/특성 공정의 수율이 50% 미만인경우"
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , C.NICK_NAME
             , 'YLD02'                      AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION           AS SALES_PLANT_SITE
             , NULL                         AS PROJECT_OPERATION
             , NULL                         AS INCOTERMS_LINE
             , NVL(A.SSP_MODIFY_YIELD
                  ,A.FORMATION_TOTAL_YIELD) AS YIELD
             , 'FORMATION'                  AS FROM_UI
               /* AS-IS CONVERT(NVARCHAR(50), numeric(20,10)) 은 소수 10자리를 고정 표기하므로
                  TO_CHAR 기본 서식(.03)이 아니라 자릿수 서식(0.0300000000)을 쓴다 */
             , 'FORMATION YIELD :' || TO_CHAR(A.FORMATION_YIELD, 'FM9999999990.0000000000')
            || 'CHAR_YIELD :'      || TO_CHAR(A.CHAR_YIELD     , 'FM9999999990.0000000000')  AS MASTER_INVLD_CTN
          FROM SCP_MST_FORMATION_V A   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
             , SCM_MST_SITE        B
             , SCP_MST_FINAL_ITEM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND NVL(A.SSP_MODIFY_YIELD, A.FORMATION_TOTAL_YIELD) < 0.5;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , YIELD
          , FROM_UI
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.YIELD
             , A.FROM_UI
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.YIELD
                 , A.FROM_UI
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND A.YIELD != 0
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_YIELD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOM                                                     */
    /* Description : BOD                                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* Initial Release  PJ2024A332R 독립적 Planning 체계 및 Master Validation UI 구축                */
    /* 2025/08/14  hrkim   PJ20257329 line assign 참조시 scp plan operation 으로 공정 참조 범위 제한 */
    /* 2025/08/26  hrkim   PJ20257329 Model BOM 참조시 parent/child FP item master active 'Y'만 참조 */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOM
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### BOM 요구사항 ###############################################################

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보를 기반으로
 >> 해당 모델의 A9000(조립)/ E2000(전극) 공정에 대한 PLANT 확장 정보가 미존재하는 경우 (모든 PLANT 중)

2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
   해당모델의 A900(조립)/E2000(전극)공정 '모델' 기반으로
 >> ITEM TYPE = NULL 인경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_BOM_CHILD_CNT;
        DELETE FROM GT_0039_BOM_CHILD_CNT_0;
        DELETE FROM GT_0039_BOM_NOT_EXISTS;
        DELETE FROM GT_0039_ITEM_TYPE_IS_NULL;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* PK : DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS,      */
        /*      MEASURE, YYYYMMDD, PLANT_SITE_ID                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A   /* DIVISION_ID, MEASURE, YYYYMMDD */
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
             , GT_0039_CFM_MKT_DMND_PLAN E   /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 가 존재하는 모델 BOM                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , MODEL_OPERATION_GROUP
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CHILD_ITEM_TYPE
          , CHILD_ITEM_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , B.OPERATION_GROUP        AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , A.CHILD_DIVISION_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.ITEM_TYPE              AS CHILD_ITEM_TYPE
             , D.NICK_NAME              AS CHILD_ITEM_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A   /* COMPANY_ID, DIVISION_ID, SITE_ID, PLANT_ID, MODEL_ID, CONCATENATE_ITEM */
             , SCP_MST_FINAL_ITEM  B   /* PJ20257329 2025.09.05 추가 JOIN */
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'           /* PJ20257329 2025.08.26 child item master active 'Y'만 참조 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL)   /* PJ20257329 2025.08.26 parent/child item master active 'Y'만 참조 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 건수 정보                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT';
        INSERT INTO GT_0039_BOM_CHILD_CNT
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MAX(MODEL_OPERATION_GROUP)                                                                         AS MODEL_OPERATION_GROUP   /* PJ20257329 2025.09.05 추가 */
             , MAX(CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)                        AS CELL_MODEL_ID           /* PJ20257329 2025.09.05 추가 */
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'A' THEN CHILD_ITEM_ID ELSE NULL END)             AS CELL_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'ANODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS ANODE_CNT
             , COUNT(DISTINCT CASE WHEN CHILD_OPERATION_GROUP = 'E' AND CHILD_ELECTRODE_TYPE = 'CATHODE'
                                   THEN CHILD_ITEM_ID ELSE NULL END)                                              AS CATHODE_CNT
          FROM GT_0039_SCP_BOM
         GROUP BY MODEL_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM - 모델별 셀 또는 전극(Anode/Cathod) 0 인 건                                           */
        /* PJ20257329 2025.09.05 추가                                                                */
        /* Pack Model기준 Cell모델 확장 / 동일 plant 전극 미확장 이더라도                            */
        /* 타 plant에 해당 cell 모델의 전극 BOM확장된 경우 -> BOM 확장 된 것으로 본다.                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_CHILD_CNT_0';
        INSERT INTO GT_0039_BOM_CHILD_CNT_0
        (
            MODEL_ID
          , MODEL_OPERATION_GROUP
          , CELL_MODEL_ID
          , CELL_CNT
          , ANODE_CNT
          , CATHODE_CNT
        )
        SELECT MODEL_ID
             , MODEL_OPERATION_GROUP
             , CELL_MODEL_ID
             , CELL_CNT
             , ANODE_CNT
             , CATHODE_CNT
          FROM GT_0039_BOM_CHILD_CNT A
         WHERE (A.CELL_CNT = 0 OR A.ANODE_CNT = 0 OR A.CATHODE_CNT = 0)
           AND NOT EXISTS ( SELECT 1   /* Pack model 기준 Cell 확인되어 있고 */
                              FROM GT_0039_BOM_CHILD_CNT XA
                             WHERE XA.MODEL_ID = A.CELL_MODEL_ID
                               AND XA.MODEL_OPERATION_GROUP = 'A'
                               AND A.MODEL_OPERATION_GROUP  = 'P'
                               AND A.CELL_CNT     > 0   /* Pack model의 하위 cell 확장 */
                               AND XA.ANODE_CNT   > 0   /* Cell 모델의 하위 전극 확장 */
                               AND XA.CATHODE_CNT > 0 );

        /* ---------------------------------------------------------------------------------------- */
        /* BOM에 Sales Model 또는 하위 Child item이 없는 경우                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOM_NOT_EXISTS';
        INSERT INTO GT_0039_BOM_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* ### 1. BOM에 Sales Model이 없는 경우 */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM01'                                                    AS MASTER_INVLD_CD
             , 'Model:0' || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                                 THEN ''
                                 ELSE ' ,Cell Prod Site : ' || B.NAME     /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
                            END                                           AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.CODE(+) = A.CELL_PROD_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_BOM XA
                             WHERE XA.MODEL_ID = A.SALES_ITEM_ID )
         UNION ALL
        /* ### 2. BOM에 Sales Model 정보는 있으나, BOM 하위에 Cell 또는 전극(양극 또는 음극) 품목이 없는 경우 (Final item 기준) */
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , 'BOM02'                                                    AS MASTER_INVLD_CD
             , 'Cell:'      || TO_CHAR(C.CELL_CNT)
            || ',Anode:'    || TO_CHAR(C.ANODE_CNT)
            || ',Cathode:'  || TO_CHAR(C.CATHODE_CNT)
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || B.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_MKT_FCST           A
             , GT_0039_BOM_CHILD_CNT_0    C   /* PJ20257329 2025.09.05 변경 (#SCP_BOM_CHILD_CNT -> #SCP_BOM_CHILD_CNT_0) */
             , GT_0039_CELL_PROD_SITE_ID  B   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE C.MODEL_ID = A.SALES_ITEM_ID
           AND B.CODE(+)  = A.CELL_PROD_SITE_ID
           AND A.MODEL_OPERATION_GROUP != 'E';

        /* ---------------------------------------------------------------------------------------- */
        /* Item Type is NULL                                                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'ITEM_TYPE_IS_NULL';
        INSERT INTO GT_0039_ITEM_TYPE_IS_NULL
        (
            CHILD_ITEM_TYPE
          , CHILD_DIVISION_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_ITEM_ID
          , CHILD_ITEM_NICK_NAME
          , CHILD_OPERATION_GROUP
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.CHILD_ITEM_TYPE
             , B.CHILD_DIVISION_ID
             , B.CHILD_COMPANY_ID
             , B.CHILD_SITE_ID
             , B.CHILD_ITEM_ID
             , B.CHILD_ITEM_NICK_NAME
             , B.CHILD_OPERATION_GROUP
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_OPERATION_ID
             , B.CHILD_ELECTRODE_TYPE
             , 'BOM03'                                                    AS MASTER_INVLD_CD
             , 'Child Division:' || B.CHILD_DIVISION_ID
            || ', Sales Item : ' || A.SALES_ITEM_ID
            || ', Company:'      || C.COMPANY_NAME
            || CASE WHEN A.CELL_PROD_SITE_ID IS NULL
                    THEN ''
                    ELSE ', Cell Prod Site ID : ' || D.NAME               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
               END                                                        AS MASTER_INVLD_CTN
          FROM GT_0039_MKT_FCST           A
             , GT_0039_SCP_BOM            B   /* BOM이 존재한다는 전제하에 project route 확인 대상 */
             , SCM_MST_COMPANY_SN         C
             , GT_0039_CELL_PROD_SITE_ID  D   /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.COMPANY_ID(+) = B.CHILD_COMPANY_ID
           AND D.CODE(+)       = A.CELL_PROD_SITE_ID
           AND B.CHILD_ITEM_TYPE IS NULL;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터                                                                 */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        /* BOM not exists */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.SALES_ITEM_ID        AS MODEL_ID
             , A.MODEL_NICK_NAME      AS NICK_NAME
             , A.SALES_SITE_ID        AS SALES_PLANT_SITE
             , A.PROJECT_CODE         AS PROJECT_OPERATION
             , A.INCOTERMS            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_BOM_NOT_EXISTS A
         UNION ALL
        /* Item_type is null (SCM_MST_ITEM_SN) */
        SELECT V_DIVISION_ID          AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS MODE_ID
             , A.CHILD_ITEM_NICK_NAME AS NICK_NAME
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.INCOTERMS
             , A.QTY
             , A.MASTER_INVLD_CD
             , A.MASTER_INVLD_CTN
          FROM GT_0039_ITEM_TYPE_IS_NULL A;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* BOM 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME       AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOM;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE                                           */
    /* Description : Project Route 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 parent/child FP item master active 'Y'만 참조                  */
    /* 2025/09/05  hrkim   PJ20257329 MKT_FCST 참조시 AS Sales 사이트 제외                           */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PROJECT_ROUTE
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
### Project Route 요구사항

1) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와 해당 모델의 BOM 정보를 기반으로
 >> PJT ROUTE 미등록인 경우

2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP != 'W'   /* AS plant site 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'PR001'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Child Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* SCP Plan 버전 정보                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
         GROUP BY A.ITEM_ID_ASSY;

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 생산계획                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.ITEM_ID
             , B.SCM_SITE_ID        AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)      AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)      AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)           AS QTY
             , 'PR002'              AS MASTER_INVLD_CD
             , 'Min:'        || MIN(B.YYYYMMDD)
            || ', Max:'      || MAX(B.YYYYMMDD)
            || ', Cell Assy:'|| B.ITEM_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )  /* Project Route 범위 밖 기간의 생산계획 정보 */
         GROUP BY B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT_ROUTE 확인 대상 전체 데이터                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS       A
             , SCM_MST_SITE                B
             , GT_0039_CELL_PROD_SITE_ID   C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE C.ITEM_ID_PROD
               END                  AS MODEL_ID
             , C.ITEM_ID_PROD_NICK_NAME  AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_ASSY_MAP C
         WHERE B.DIVISION_ID   = V_DIVISION_ID
           AND B.SCM_SITE_ID   = A.PLANT_SITE_ID
           AND C.ITEM_ID_ASSY(+) = A.ITEM_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PROJECT_ROUTE;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_OUTSOURCING_CAPACITY                                    */
    /* Description : 외주 Capacity 조회                                                             */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_OS_CAPACITY
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82')
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST / Project Route 기준 외주 Capa 존재하지 않는 경우                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_MSG
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS        A
             , SCM_MST_SITE                 B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = A.MASTER_INVLD_CD
           AND C.VALID_YN(+)    = 'Y'
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , C.SEGMENT1           AS MASTER_INVLD_CD
             , C.ATTRIBUTE2         AS MASTER_INVLD_MSG
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID = A.SALES_ITEM_ID
                    /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
                    AND B.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                                               THEN A.CELL_PROD_SITE_ID
                                               ELSE B.PLANT_SITE_ID
                                          END
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'
                    AND C.VALID_YN    = 'Y'
                    AND NVL(C.ATTRIBUTE1, 'N') != 'Y'   /* ESS 외주 Pakcer Line 생산 Target 적용 */
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_OUTSOURCING_CAPA XA   /* DIVISION_ID, PLANT_SITE_ID, ITEM_ID */
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.DAILY_CAPA_QTY != 0 ) ) IA
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
         WHERE C.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
           AND C.SEGMENT1(+)    = 'OC002'
           AND C.VALID_YN(+)    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_OS_CAPACITY;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME_OSP                                           */
    /* Description : 외주 Tact Time 조회                                                            */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME_OSP
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(A.QTY)                     AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.14 추가 */
          FROM DM_PLN_MKT_FCST        A
             , SCM_MST_SITE           B
             , SCP_MST_FINAL_ITEM     C
             , GT_0039_AS_SITE_PLANT  D   /* PJ20257329 2025.09.05 AS Sales Site 제외 */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           /* ??AND FI.OPERATION_GROUP = 'P'  -- ESS Pack */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP != 'E'      /* 전극 제외 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE - 40/82 소형과 ESS는 Sales site 및 project Code 값이 없음 ('-')             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , OSP_YN
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , B.OSP_YN
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item :' || A.SALES_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS A
             , SCM_MST_SITE          B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
         UNION ALL
        /*
        2) CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , IA.SALES_ITEM_ID     AS MODEL_ID
             , IA.MODEL_NICK_NAME   AS NICK_NAME
             , 'TTO02'              AS MASTER_INVLD_ID
             , IA.PLANT_SITE        AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , IA.INCOTERMS         AS INCOTERMS_LINE
             , IA.QTY
             , IA.MASTER_INVLD_CTN
          FROM ( SELECT DISTINCT
                        A.SALES_ITEM_ID
                      , A.SALES_SITE_ID
                      , A.INCOTERMS
                      , A.MODEL_NICK_NAME
                      , A.QTY
                      , A.SALES_FROM_YYYYMMDD
                      , A.SALES_TO_YYYYMMDD
                      , B.PLANT_SITE_ID
                      , C.SITE_DESCRIPTION  AS PLANT_SITE
                      , B.ITEM_ID
                      , B.COUNTRY
                      , B.CITY
                      , 'SalesSite:' || A.SALES_SITE_ID  AS MASTER_INVLD_CTN   /* 상세내용 */
                   FROM GT_0039_MKT_FCST      A
                      , GT_0039_PROJECT_ROUTE B
                      , SCM_MST_SITE          C
                  WHERE B.ITEM_ID   = A.SALES_ITEM_ID
                    AND C.DIVISION_ID = V_DIVISION_ID
                    AND C.SCM_SITE_ID = B.PLANT_SITE_ID
                    AND C.OSP_YN      = 'Y'   /* OSP 외주 */
                    AND C.VALID_YN    = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCP_MST_TACT_TIME_OSP XA
                                      WHERE XA.DIVISION_ID   = C.DIVISION_ID
                                        AND XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                                        AND XA.ITEM_ID       = B.ITEM_ID
                                        AND XA.TACT_TIME != 0 ) ) IA;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME_OSP;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_PROJECT_ROUTE_ELEC                                      */
    /* Description : 전극 Project Route 조회                                                        */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용                                       */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_PR_ELEC
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'생산계획날짜' 정보를 기반으로
 >> 생산계획 시기가 PJT ROUTE - PLANT ASSGIN의 FROM TO 날짜외 구간에 입력되어 있는 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PRE_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT_FCST 기준 Model Cell BOM                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_COMPANY_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
        )
        SELECT A.ITEM_ID_ASSY
             , MAX(A.ITEM_ID_PROD)  AS ITEM_ID_PROD
             , MAX(B.NICK_NAME)     AS ITEM_ID_PROD_NICK_NAME
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND B.FLOW_ID LIKE 'A%'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = A.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
         GROUP BY A.ITEM_ID_ASSY;

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , C.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(B.NICK_NAME)     AS CELL_NICK_NAME
             , MIN(A.MONTH)         AS FROM_ASSIGNED_MONTH   /* 2025.07.09 */
             , MIN(A.MONTH)         AS TO_ASSIGNED_MONTH     /* 2025.07.09 */
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCP_MST_FINAL_ITEM          B
             , GT_0039_CELL_PROD_ASSY_MAP  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND B.OPERATION_GROUP = 'A'
           AND C.ITEM_ID_ASSY = A.ITEM_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID    = C.ITEM_ID_PROD
                           AND XA.CHILD_COMPANY_ID = A.COMPANY_ID
                           AND XA.CHILD_SITE_ID    = A.SITE_ID
                           AND XA.CHILD_PLANT_ID   = A.PLANT_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , C.ITEM_ID_PROD;

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
          , FROM_ASSIGNED_MONTH
          , TO_ASSIGNED_MONTH
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.NICK_NAME              AS ELEC_NICK_NAME
             , B.FROM_ASSIGNED_MONTH    /* 7/9 추가 */
             , B.TO_ASSIGNED_MONTH      /* 7/9 추가 */
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          D
             , SCP_MST_FINAL_ITEM       C
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND D.DIVISION_ID = A.CHILD_DIVISION_ID
           AND D.SITE_ID     = A.CHILD_SITE_ID
           AND D.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND C.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , PLANT_ID
          , COMPANY_ID
          , SITE_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.PLANT_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign Cell 기준 전극 Project Route 가 없는 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PRE_NOT_EXISTS';
        INSERT INTO GT_0039_PRE_NOT_EXISTS
        (
            MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
        )
        SELECT A.CHILD_ITEM_ID       AS MODEL_ID   /* 전극 */
             , A.ELEC_NICK_NAME      AS NICK_NAME
             , 'PRE01'               AS MASTER_INVLD_CD
             , 'Assigned Period: ' || A.FROM_ASSIGNED_MONTH || '~' || A.TO_ASSIGNED_MONTH
            || ', Cell Model:'      || A.MODEL_ID                       AS MASTER_INVLD_CTN   /* 상세내용 */
             , B.SITE_DESCRIPTION    AS SALES_PLANT_SITE   /* Cell Plant Site */
             , A.CHILD_OPERATION_ID  AS PROJECT_OPERATION
             , NULL                  AS INCOTERMS_LINE
             , NULL                  AS QTY
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , SCM_MST_SITE                 B
         WHERE B.DIVISION_ID = V_DIVISION_ID   /* Cell model 기준 Division */
           AND B.SCM_SITE_ID = A.PLANT_ID || '-' || 'A'   /* Cell 기준 Plant 사이트 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = A.CHILD_ITEM_ID );   /* 전극 */

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 SCP Plan 버전 정보                                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            ORIGIN_DIVISION_ID
          , DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT V_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT C.DIVISION_ID
                      , D.PLAN_TYPE
                      , D.PLAN_SEQ
                      , C.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(C.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , D.PLAN_STATUS
                      , D.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY C.DIVISION_ID
                                               ORDER BY C.PLAN_NAME DESC
                                                      , D.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_DIVISION    A
                      , SCM_MST_DIVISION    B
                      , SCM_MST_PLAN        C
                      , SCM_MST_PLAN_DETAIL D
                  WHERE A.VALID_YN   = 'Y'
                    AND B.ATTRIBUTE3 = 'EE'
                    AND B.ATTRIBUTE4 = A.ATTRIBUTE4
                    AND C.DIVISION_ID = B.DIVISION_ID   /* 전극 Division */
                    AND D.DIVISION_ID = C.DIVISION_ID
                    AND D.PLAN_ID     = C.PLAN_ID
                    AND D.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND C.PLAN_CYCLE  = 'WEEKLY'
                    AND C.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Project Route 기간 범위 밖의 전극 생산계획                                                */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN_ELEC';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , ORIGIN_DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_GROUP
          , OPERATION_ID
          , LINE_ID
          , PROD_FROM_YYYYMMDD
          , PROD_TO_YYYYMMDD
          , QTY
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT B.DIVISION_ID         AS EE_DIVISION_ID
             , B.ORIGIN_DIVISION_ID  AS ORIGIN_DIVISION_ID
             , B.ITEM_ID
             , B.SCM_SITE_ID         AS PLANT_SITE_ID
             , B.OPERATION_GROUP
             , B.OPERATION_ID
             , B.LINE_ID
             , MIN(B.YYYYMMDD)       AS PROD_FROM_YYYYMMDD
             , MAX(B.YYYYMMDD)       AS PROD_TO_YYYYMMDD
             , SUM(B.QTY)            AS QTY
             , 'PRE02'               AS MASTER_INVLD_CD
             , 'Min:'   || MIN(B.YYYYMMDD)
            || ', Max:' || MAX(B.YYYYMMDD)                      AS MASTER_INVLD_CTN   /* 상세내용 */
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_PRODUCTION_PLAN  B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.OPERATION_GROUP     = 'E'   /* 전극 생산계획 */
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.ORIGIN_DIVISION_ID  = A.ORIGIN_DIVISION_ID
           AND B.MEASURE = 'PROD_PLAN_AMEND'
           AND B.QTY > 0
           AND EXISTS ( SELECT 1
                          FROM GT_0039_PROJECT_ROUTE XA
                         WHERE XA.ITEM_ID       = B.ITEM_ID
                           AND XA.PLANT_SITE_ID = B.SCM_SITE_ID )   /* 생산 Plant 정보 존재 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XB
                             WHERE XB.ITEM_ID       = B.ITEM_ID
                               AND XB.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND B.YYYYMMDD BETWEEN XB.FROM_YYYYMMDD AND XB.TO_YYYYMMDD )
         GROUP BY B.DIVISION_ID
                , B.ORIGIN_DIVISION_ID
                , B.ITEM_ID
                , B.SCM_SITE_ID
                , B.OPERATION_GROUP
                , B.OPERATION_ID
                , B.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* 전극 Project Route 미등록 */
        SELECT V_DIVISION_ID              AS DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , SUBSTR(A.INCOTERMS_LINE, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_PRE_NOT_EXISTS A
         UNION ALL
        /* 범위 밖 생산계획 */
        SELECT A.ORIGIN_DIVISION_ID       AS DIVISION_ID
             , A.ITEM_ID                  AS MODEL_ID   /* 전극 */
             , B.NICK_NAME                AS NICK_NAME
             , A.MASTER_INVLD_CD
             , C.SITE_DESCRIPTION         AS SALES_PLANT_SITE
             , A.OPERATION_ID             AS PROJECT_OPERATION
             , SUBSTR(A.LINE_ID, 1, 100)  AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_SCP_PROD_PLAN A
             , SCP_MST_FINAL_ITEM    B
             , SCM_MST_SITE          C
         WHERE B.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.ORIGIN_DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.MODEL_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_PR_ELEC;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_LINE_ASSIGN                                             */
    /* Description : Line Assign 조회                                                               */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_LINE_ASSIGN
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_TARGET_CASE2;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TARGET_CASE3;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SCP_PROD_PLAN;
        DELETE FROM GT_0039_TARGET_CASE4;
        DELETE FROM GT_0039_TARGET_CASE5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 기준 */
           AND C.OPERATION_GROUP = 'A'       /* Cell */
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE XA.SALES_ITEM_ID = A.MODEL_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP     A
             , SCP_MST_FINAL_ITEM             B
             , GT_0039_MKT_FCST_MDL_CELL_BOM  C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Line Assign 누락 데이터                                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE2';
        INSERT INTO GT_0039_TARGET_CASE2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , G.LINE_ID
          FROM GT_0039_MKT_FCST             A
             , GT_0039_SCP_BOM              B
             , GT_0039_PROJECT_ROUTE        C
             , SCM_MST_SITE                 D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP   E
             , GT_0039_CELL_PROD_ASSY_MAP   F
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) G
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.CELL_TYPE NOT LIKE 'CP%'   /* Cell Assy 기준 (CP 제외) */
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.DIVISION_ID = V_DIVISION_ID
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND G.COMPANY_ID(+)  = D.COMPANY_ID
           AND G.DIVISION_ID(+) = D.DIVISION_ID
           AND G.SITE_ID(+)     = D.SITE_ID
           AND G.PLANT_ID(+)    = D.PLANT_ID
           AND G.ITEM_ID(+)     = C.ITEM_ID
           AND G.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 2025.08.20 당월부터 plan horizon end date 까지 참조 */
           AND G.LINE_ID IS NULL;   /* line assign 안된 Cell/Pack Project Route 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 Cell 모델 (Cell Product 기준)                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , E.ITEM_ID_PROD       AS CELL_MODEL_ID
             , MAX(D.NICK_NAME)     AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID  = A.DIVISION_ID
           AND E.PLANT_ID     = A.PLANT_ID
           AND E.ITEM_ID_ASSY = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY = 1
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = E.ITEM_ID_PROD )   /* MKT FCST 기준 생산 대상 Cell Model */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')   /* FP에서 0 / 9 는 생산 대상 아님 */
           AND EXISTS ( SELECT 1   /* 2025.08.20 Project route 가 존재하는 cell model */
                          FROM GT_0039_PROJECT_ROUTE XB
                         WHERE XB.ITEM_ID = A.ITEM_ID )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , E.ITEM_ID_PROD;

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       E   /* Cell Model */
             , SCP_MST_FINAL_ITEM       D   /* Child 전극 */
             , SCM_MST_ITEM_SN          F
         WHERE B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND E.DIVISION_ID = A.DIVISION_ID
           AND E.ITEM_ID     = A.MODEL_ID
           AND E.OPERATION_GROUP = 'A'   /* Cell Model */
           AND E.FLOW_ID LIKE 'A%'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.OPERATION_GROUP = 'E'   /* Child 전극 */
           AND F.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND F.COMPANY_ID(+)  = A.COMPANY_ID
           AND F.DIVISION_ID(+) = A.DIVISION_ID
           AND F.SITE_ID(+)     = A.SITE_ID
           AND F.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR F.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE3';
        INSERT INTO GT_0039_TARGET_CASE3
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
        )
        SELECT DISTINCT
               A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.ITEM_ID(+)     = B.ITEM_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND C.LINE_ID IS NULL;   /* 전극 line assign 누락 데이터 */

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* SCP 생산계획 (2025.08.20 추가)                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PROD_PLAN';
        INSERT INTO GT_0039_SCP_PROD_PLAN
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , YYYYMM
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS YYYYMM
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN  A
             , GT_0039_SCP_PLAN_VERSION B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - line assign 범위 밖의 생산계획                                         */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE4';
        INSERT INTO GT_0039_TARGET_CASE4
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , MIN_PROD_MONTH
          , MAX_PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION
             , CASE WHEN A.OPERATION_GROUP = 'P'
                    THEN A.ITEM_ID
                    ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
               END                      AS ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , MIN(A.YYYYMM)            AS MIN_PROD_MONTH
             , MAX(A.YYYYMM)            AS MAX_PROD_MONTH
             , SUM(A.QTY)               AS QTY
          FROM GT_0039_SCP_PROD_PLAN       A
             , SCM_MST_SITE                B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
             , GT_0039_CELL_PROD_ASSY_MAP  D
             , GT_0039_CELL_PROD_ASSY_MAP  E
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND C.COMPANY_ID(+)  = B.COMPANY_ID
           AND C.DIVISION_ID(+) = B.DIVISION_ID
           AND C.SITE_ID(+)     = B.SITE_ID
           AND C.PLANT_ID(+)    = B.PLANT_ID
           AND C.LINE_ID(+)     = A.LINE_ID
           AND C.ITEM_ID(+)     = A.ITEM_ID
           AND C.MONTH(+)       = A.YYYYMM   /* 해당 범위 내 */
           AND D.DIVISION_ID(+)  = B.DIVISION_ID
           AND D.PLANT_ID(+)     = B.PLANT_ID
           AND D.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND D.ITEM_ID_PROD_PRIORITY(+) = 1
           AND E.DIVISION_ID(+)  = B.DIVISION_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND C.LINE_ID IS NULL   /* 범위 밖의 Line Assign */
           AND EXISTS ( SELECT 1   /* line Assign 이 존재 */
                          FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                             , SCM_MST_LINE_SN             XB   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
                             , GT_0039_SCP_PLAN_OPERATION  XC   /* 2025.08.20 scp 계획 공정으로 범위 제한 */
                         WHERE XB.COMPANY_ID   = XA.COMPANY_ID
                           AND XB.DIVISION_ID  = XA.DIVISION_ID
                           AND XB.SITE_ID      = XA.SITE_ID
                           AND XB.PLANT_ID     = XA.PLANT_ID
                           AND XB.FACTORY_ID   = XA.FACTORY_ID
                           AND XB.OPERATION_ID = XA.OPERATION_ID
                           AND XB.LINE_ID      = XA.LINE_ID
                           AND XB.ACTIVE_FLAG  = 'Y'
                           AND XC.OPERATION_ID = XA.OPERATION_ID
                           AND XA.COMPANY_ID  = B.COMPANY_ID
                           AND XA.DIVISION_ID = B.DIVISION_ID
                           AND XA.SITE_ID     = B.SITE_ID
                           AND XA.PLANT_ID    = B.PLANT_ID
                           AND XA.LINE_ID     = A.LINE_ID
                           AND XA.ITEM_ID     = A.ITEM_ID
                           AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                           AND XA.ACTIVE_FLAG = 'Y'
                           AND XA.PRIORITY NOT IN ('0', '9') )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , B.SITE_DESCRIPTION
                , CASE WHEN A.OPERATION_GROUP = 'P'
                       THEN A.ITEM_ID
                       ELSE NVL(NVL(D.ITEM_ID_PROD, E.ITEM_ID_PROD), A.ITEM_ID)
                  END
                , A.LINE_ID
                , A.OPERATION_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : 전극 Line Assign Lane 수량이 1보다 작은 데이터                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_CASE5';
        INSERT INTO GT_0039_TARGET_CASE5
        (
            DIVISION_ID
          , ELEC_ITEM_ID
          , ELEC_NICK_NAME
          , OPERATION_ID
          , PLANT_SITE_ID
          , MODEL_ID
          , MODEL_PLANT_ID
          , LINE_ID
          , MONTH_MIN
          , MONTH_MAX
        )
        SELECT A.CHILD_DIVISION_ID    AS DIVISION_ID
             , A.CHILD_ITEM_ID        AS ELEC_ITEM_ID
             , A.ELEC_NICK_NAME
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , B.PLANT_SITE_ID
             , A.MODEL_ID
             , A.PLANT_ID             AS MODEL_PLANT_ID
             , C.LINE_ID
             , MIN(C.MONTH)           AS MONTH_MIN
             , MAX(C.MONTH)           AS MONTH_MAX
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = 'E2000'   /* 6/20 추가 */
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.LANE_QTY < 1   /* lane 수가 1 미만인 경우 */
         GROUP BY A.CHILD_DIVISION_ID
                , A.CHILD_ITEM_ID
                , A.ELEC_NICK_NAME
                , A.CHILD_OPERATION_ID
                , B.PLANT_SITE_ID
                , A.MODEL_ID
                , A.PLANT_ID
                , C.LINE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 LINE ASSIGN 이 조회되지 않는경우
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'LNA02'                   AS MASTER_INVLD_CD
             , A.PLANT_SITE              AS SALES_PLANT_SITE
             , A.CHILD_OPERATION_ID      AS PROJECT_OPERATION
             , A.LINE_ID                 AS INCOERMS_LINE
             , NULL                      AS QTY
             , 'Sales Item :' || A.SALES_ITEM_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_TARGET_CASE2 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (전극)CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 PLANT ASSIGN 정보가 경우 (ROUTE 미등록)
        */
        SELECT DISTINCT   /* PJ20257329 2025.09.12 distinct 추가 */
               A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Cell Model :' || A.MODEL_ID  AS MASTER_INVLD_CTN   /* PJ20257329 2025.09.12 Model Plant 정보 제외 */
          FROM GT_0039_TARGET_CASE3 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        4) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 LINE ASSIGN의 FROM TO 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'LNA04'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , A.QTY                AS QTY
             , 'Min Month :' || A.MIN_PROD_MONTH || ', Max Month :' || A.MAX_PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE4 A
             , SCP_MST_FINAL_ITEM   B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
         UNION ALL
        /*
        5) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> E2000 공정의 LANE 정보가 1이상의 정수가 아닌경우 (LANE정보 미등록)
        */
        SELECT A.DIVISION_ID
             , A.ELEC_ITEM_ID       AS MODEL_ID
             , A.ELEC_NICK_NAME     AS NICK_NAME
             , 'LNA05'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOERMS_LINE
             , NULL                 AS QTY
             , 'Min Month:' || A.MONTH_MIN || ' Max Month:' || A.MONTH_MAX
            || '. Cell Model :' || A.MODEL_ID || ', Plant :' || A.MODEL_PLANT_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TARGET_CASE5 A
             , SCM_MST_SITE         B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_LINE_ASSIGN;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_TACT_TIME                                               */
    /* Description : Tact Time 조회                                                                 */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/20  hrkim   PJ20257329 유효 라인/SCP Plan Operation 범위 제한                         */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 제거                            */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_TACT_TIME
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_CELL_PROD_ASSY_MAP;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_FP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME;
        DELETE FROM GT_0039_SCP_TACT_TIME_EXCEPT;
        DELETE FROM GT_0039_TT_CASE_2;
        DELETE FROM GT_0039_LINE_ASSIGN_MODEL;
        DELETE FROM GT_0039_TT_CASE_3;
        DELETE FROM GT_0039_MKT_FCST_MDL_CELL_BOM;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL;
        DELETE FROM GT_0039_LINE_ASSIGN_CELL_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE_ELEC;
        DELETE FROM GT_0039_TT_CASE_4;
        DELETE FROM GT_0039_TT_CASE_4_2;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_TT_CASE_5;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST                                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , CELL_TYPE
          , CHILD_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , C.OPERATION_GROUP        AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , C.ATTRIBUTE8             AS CELL_TYPE
             , C.NICK_NAME              AS CHILD_NICK_NAME
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Cell Assy/Prod Mapping 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'CELL_PROD_ASSY_MAP';
        INSERT INTO GT_0039_CELL_PROD_ASSY_MAP
        (
            DIVISION_ID
          , PLANT_ID
          , ITEM_ID_ASSY
          , ITEM_ID_PROD
          , ITEM_ID_PROD_NICK_NAME
          , CHILD_ITEM_ID
          , ITEM_ID_PROD_PRIORITY
          , ITEM_ID_PROD_PRIORITY2
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.ITEM_ID_ASSY
             , A.ITEM_ID_PROD
             , B.NICK_NAME          AS ITEM_ID_PROD_NICK_NAME
             , C.CHILD_ITEM_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.PLANT_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.ITEM_ID_ASSY
                                      ORDER BY CASE WHEN C.CHILD_ITEM_ID IS NOT NULL
                                                    THEN 1
                                                    ELSE 0
                                               END DESC
                                             , A.ITEM_ID_PROD DESC)  AS ITEM_ID_PROD_PRIORITY2
          FROM SCP_MST_CELL_PROD_ASSY_MAP A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_SCP_BOM            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID_PROD
           AND C.CHILD_ITEM_ID(+) = A.ITEM_ID_PROD
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                        AS MASTER_INVLD_CD
             , 'Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE AS MASTER_INVLD_CTN   /* 2025.08.14 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND B.CELL_TYPE NOT LIKE 'CA%'
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : FP / SCP Tact Time                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FP_TACT_TIME';
        INSERT INTO GT_0039_FP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , OPERATION_ID
          , LINE_ID
          , MONTH
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , MONTH
          FROM SCM_MST_TACT_TIME_VER_H_V
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6);   /* 2025.08.20 PJ20257329 */

        V_STEP := 'SCP_TACT_TIME';
        INSERT INTO GT_0039_SCP_TACT_TIME
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME
         WHERE DIVISION_ID = V_DIVISION_ID
           AND TACT_TIME > 0
           AND VALID_YN  = 'Y';

        V_STEP := 'SCP_TACT_TIME_EXCEPT';
        INSERT INTO GT_0039_SCP_TACT_TIME_EXCEPT
        (
            PLANT_SITE_ID
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
        )
        SELECT DISTINCT
               PLANT_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
          FROM SCP_MST_TACT_TIME_EXCEPT
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND TACT_TIME_END_DATE  > V_FROM_YYYYMMDD
           AND TACT_TIME > 0
           AND USE_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩/전극 Tact Time 누락 데이터 (MKT_FCST & BOM & PROJECT_ROUTE)                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_2';
        INSERT INTO GT_0039_TT_CASE_2
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               C.PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , D.COMPANY_ID
             , D.DIVISION_ID
             , D.SITE_ID
             , D.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_PROJECT_ROUTE       C
             , SCM_MST_SITE                D   /* plant site */
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND NVL(B.CELL_TYPE, '-') != 'CP'   /* Cell Tact Time 은 Cell Assy 기준으로 관리 */
           AND B.CHILD_OPERATION_GROUP != 'E'  /* 전극 제외 */
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND C.ITEM_ID      = B.CHILD_ITEM_ID
           AND C.PROJECT_CODE = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                     THEN '/'
                                     ELSE A.PROJECT_CODE
                                END
           AND C.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                      THEN '-'
                                      ELSE A.SALES_SITE_ID
                                 END
           AND D.VALID_YN    = 'Y'
           AND D.SITE_TYPE   = 'PLANT'
           AND D.SCM_SITE_ID = C.PLANT_SITE_ID
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'   /* 2025.08.06 Warranty Plant 제외 */
           AND NVL(D.OSP_YN, 'Z')          != 'Y'   /* 2025.08.06 OSP 제외 */
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.PLANT_ID(+)     = D.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = D.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = C.PLANT_SITE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : Line Assign 된 모델                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_MODEL';
        INSERT INTO GT_0039_LINE_ASSIGN_MODEL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , LINE_ID
          , ITEM_ID
          , NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.LINE_ID
             , A.ITEM_ID
             , MAX(D.NICK_NAME)  AS NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , A.LINE_ID
                , A.ITEM_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* 조립/팩 Tact Time 누락 데이터 (MKT_FCST & BOM & Line Assign)                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_3';
        INSERT INTO GT_0039_TT_CASE_3
        (
            PLANT_SITE_ID
          , PLANT_SITE
          , MODEL_ID
          , LINE_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , DESCR
        )
        SELECT DISTINCT
               D.SCM_SITE_ID        AS PLANT_SITE_ID
             , D.SITE_DESCRIPTION   AS PLANT_SITE
             , CASE WHEN B.CHILD_OPERATION_GROUP = 'A'
                    THEN NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), C.ITEM_ID)
                    ELSE C.ITEM_ID
               END                  AS MODEL_ID
             , C.LINE_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , C.COMPANY_ID
             , C.DIVISION_ID
             , C.SITE_ID
             , C.PLANT_ID
             , 'Sales Model:' || A.SALES_ITEM_ID  AS DESCR   /* PJ20257329 2025.09.12 Sales Site 및 Project Code 정보 제외 */
          FROM GT_0039_MKT_FCST            A
             , GT_0039_SCP_BOM             B
             , GT_0039_LINE_ASSIGN_MODEL   C   /* 전극을 제외한 Line Assign 된 모델 */
             , SCM_MST_SITE                D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.MODEL_ID = A.SALES_ITEM_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NVL(B.CELL_TYPE, '-') != 'CP'
           AND B.CHILD_OPERATION_GROUP != 'E'
           AND C.ITEM_ID = B.CHILD_ITEM_ID
           AND D.DIVISION_ID     = C.DIVISION_ID
           AND D.PLANT_ID        = C.PLANT_ID
           AND D.SITE_TYPE       = 'PLANT'
           AND D.OPERATION_GROUP = B.CHILD_OPERATION_GROUP
           AND D.VALID_YN        = 'Y'
           AND NVL(D.OPERATION_GROUP, 'Z') != 'W'
           AND NVL(D.OSP_YN, 'Z')          != 'Y'
           AND E.DIVISION_ID(+)  = C.DIVISION_ID
           AND E.PLANT_ID(+)     = C.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = C.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = C.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND B.CHILD_OPERATION_ID NOT LIKE 'F%'
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = D.SCM_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 4 : MKT_FCST 기준 Model Cell BOM                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST_MDL_CELL_BOM';
        INSERT INTO GT_0039_MKT_FCST_MDL_CELL_BOM
        (
            MODEL_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     D
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
         WHERE D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.OPERATION_GROUP = 'A'   /* Cell */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* Line Assign 된 Cell 모델 (Cell Product 기준)                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL
        (
            COMPANY_ID
          , DIVISION_ID
          , SITE_ID
          , PLANT_ID
          , CELL_MODEL_ID
          , CELL_NICK_NAME
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID)                                     AS CELL_MODEL_ID
             , MAX(NVL(NVL(E.ITEM_ID_PROD_NICK_NAME, F.ITEM_ID_PROD_NICK_NAME), D.NICK_NAME))          AS CELL_NICK_NAME
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , SCM_MST_LINE_SN             B   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION  C   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
             , SCP_MST_FINAL_ITEM          D
             , GT_0039_CELL_PROD_ASSY_MAP  E
             , GT_0039_CELL_PROD_ASSY_MAP  F
         WHERE B.COMPANY_ID   = A.COMPANY_ID
           AND B.DIVISION_ID  = A.DIVISION_ID
           AND B.SITE_ID      = A.SITE_ID
           AND B.PLANT_ID     = A.PLANT_ID
           AND B.FACTORY_ID   = A.FACTORY_ID
           AND B.OPERATION_ID = A.OPERATION_ID
           AND B.LINE_ID      = A.LINE_ID
           AND B.ACTIVE_FLAG  = 'Y'
           AND C.OPERATION_ID = A.OPERATION_ID
           AND D.DIVISION_ID  = A.DIVISION_ID
           AND D.ITEM_ID      = A.ITEM_ID
           AND D.OPERATION_GROUP = 'A'
           AND E.DIVISION_ID(+)  = A.DIVISION_ID
           AND E.PLANT_ID(+)     = A.PLANT_ID
           AND E.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND E.ITEM_ID_PROD_PRIORITY(+) = 1
           AND F.DIVISION_ID(+)  = A.DIVISION_ID
           AND F.ITEM_ID_ASSY(+) = A.ITEM_ID
           AND F.ITEM_ID_PROD_PRIORITY2(+) = 1
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
           AND A.ACTIVE_FLAG = 'Y'
           AND A.PRIORITY NOT IN ('0', '9')
           AND EXISTS ( SELECT 1   /* 상위 모델 MKT FCST 존재 6/24 */
                          FROM GT_0039_MKT_FCST_MDL_CELL_BOM XA
                         WHERE XA.CHILD_ITEM_ID = NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID) )
         GROUP BY A.COMPANY_ID
                , A.DIVISION_ID
                , A.SITE_ID
                , A.PLANT_ID
                , NVL(NVL(E.ITEM_ID_PROD, F.ITEM_ID_PROD), A.ITEM_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 라인 Assign 된 Cell Model BOM (셀-전극)                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'LINE_ASSIGN_CELL_BOM';
        INSERT INTO GT_0039_LINE_ASSIGN_CELL_BOM
        (
            MODEL_ID
          , PLANT_ID
          , CHILD_COMPANY_ID
          , CHILD_DIVISION_ID
          , CHILD_SITE_ID
          , CHILD_PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
          , ELEC_NICK_NAME
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.PLANT_ID
             , A.CHILD_COMPANY_ID
             , A.CHILD_DIVISION_ID
             , A.CHILD_SITE_ID
             , A.CHILD_PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN D.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE D.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(D.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , D.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
             , D.NICK_NAME              AS ELEC_NICK_NAME
          FROM SCM_MST_MODEL_BOM        A
             , SCM_MST_ITEM_SN          E   /* PJ20257329 2025.08.26 parent item master active 'Y'만 참조 */
             , GT_0039_LINE_ASSIGN_CELL B
             , SCM_MST_ITEM_SN          C
             , SCP_MST_FINAL_ITEM       D
         WHERE E.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND E.COMPANY_ID(+)  = A.COMPANY_ID
           AND E.DIVISION_ID(+) = A.DIVISION_ID
           AND E.SITE_ID(+)     = A.SITE_ID
           AND E.ACTIVE_FLAG(+) = 'Y'
           AND B.COMPANY_ID    = A.COMPANY_ID
           AND B.DIVISION_ID   = A.DIVISION_ID
           AND B.SITE_ID       = A.SITE_ID
           AND B.PLANT_ID      = A.PLANT_ID
           AND B.CELL_MODEL_ID = A.MODEL_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND C.DIVISION_ID = A.CHILD_DIVISION_ID
           AND C.SITE_ID     = A.CHILD_SITE_ID
           AND C.ACTIVE_FLAG = 'Y'
           AND D.DIVISION_ID = A.DIVISION_ID
           AND D.ITEM_ID     = A.CHILD_ITEM_ID
           AND D.ATTRIBUTE8 NOT LIKE 'CA%'   /* Cell Assy 제외 */
           AND D.OPERATION_GROUP = 'E'       /* Child 전극 */
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR E.ITEM_ID IS NOT NULL);

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 PROJECT ROUTE                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE_ELEC';
        INSERT INTO GT_0039_PROJECT_ROUTE_ELEC
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , PLANT_SITE_ID
          , DIVISION_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , A.PLANT_SITE_ID
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE               B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND B.SITE_TYPE   = 'PLANT'
           AND B.VALID_YN    = 'Y'
           AND B.OPERATION_GROUP = 'E'   /* 전극 Plant Site */
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= '20260824';

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 안된 데이터                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4';
        INSERT INTO GT_0039_TT_CASE_4
        (
            DIVISION_ID
          , ELEC_MODEL_ID
          , ELEC_NICK_NAME
          , PLANT_SITE_ID
          , OPERATION_ID
          , MASTER_INVLD_CTN
        )
        SELECT DISTINCT
               B.DIVISION_ID          AS DIVISION_ID
             , B.ITEM_ID              AS ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , B.PLANT_SITE_ID
             , A.CHILD_OPERATION_ID   AS OPERATION_ID
             , CAST(NULL AS VARCHAR2(250 CHAR))  AS MASTER_INVLD_CTN
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
               /* AS-IS 의 LEFT JOIN ON 절에 있던 SCP 계획 공정 제한 / ACTIVE_FLAG / PRIORITY 조건은
                  인라인 뷰로 옮긴다 (Oracle 은 (+) 조인 조건에 서브쿼리를 쓸 수 없다 - ORA-01799) */
             , ( SELECT XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.ITEM_ID
                      , XA.OPERATION_ID
                      , XA.MONTH
                      , XA.LINE_ID
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                      , GT_0039_SCP_PLAN_OPERATION  XB   /* scp 계획 공정으로 범위 제한 */
                  WHERE XB.OPERATION_ID = XA.OPERATION_ID
                    AND XA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY NOT IN ('0', '9') ) C
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID   /* 2025.08.20 PJ20257329 cell/전극 동일 plant 조건 추가 */
           AND C.COMPANY_ID(+)   = B.COMPANY_ID
           AND C.DIVISION_ID(+)  = B.DIVISION_ID
           AND C.SITE_ID(+)      = B.SITE_ID
           AND C.PLANT_ID(+)     = B.PLANT_ID
           AND C.ITEM_ID(+)      = B.ITEM_ID
           AND C.OPERATION_ID(+) = A.CHILD_OPERATION_ID
           AND C.MONTH(+) BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.LINE_ID IS NULL   /* 전극 line assign 누락 데이터 */
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                 , SCM_MST_LINE_SN             XC
                             WHERE XC.COMPANY_ID   = XB.COMPANY_ID
                               AND XC.DIVISION_ID  = XB.DIVISION_ID
                               AND XC.SITE_ID      = XB.SITE_ID
                               AND XC.PLANT_ID     = XB.PLANT_ID
                               AND XC.FACTORY_ID   = XB.FACTORY_ID
                               AND XC.OPERATION_ID = XB.OPERATION_ID
                               AND XC.LINE_ID      = XB.LINE_ID
                               AND XC.ACTIVE_FLAG  = 'Y'
                               AND XB.COMPANY_ID   = B.COMPANY_ID
                               AND XB.DIVISION_ID  = B.DIVISION_ID
                               AND XB.SITE_ID      = B.SITE_ID
                               AND XB.PLANT_ID     = B.PLANT_ID
                               AND XB.ITEM_ID      = B.ITEM_ID
                               AND XB.OPERATION_ID = A.CHILD_OPERATION_ID
                               AND XB.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                               AND XB.PRIORITY NOT IN ('0', '9')
                               AND XB.ACTIVE_FLAG = 'Y'
                               AND XB.OPERATION_ID IN ( SELECT XD.OPERATION_ID FROM GT_0039_SCP_PLAN_OPERATION XD ) );

        /* ---------------------------------------------------------------------------------------- */
        /* 전극 Line Assign 되고 Tact Time 미등록 데이터                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_4_2';
        INSERT INTO GT_0039_TT_CASE_4_2
        (
            DIVISION_ID
          , ITEM_ID
          , PLANT_SITE_ID
          , OPERATION_ID
          , LINE_ID
        )
        SELECT DISTINCT
               C.DIVISION_ID
             , C.ITEM_ID
             , B.PLANT_SITE_ID
             , C.OPERATION_ID
             , C.LINE_ID
          FROM GT_0039_LINE_ASSIGN_CELL_BOM A
             , GT_0039_PROJECT_ROUTE_ELEC   B
             , SCM_MST_ITEM_LINE_ASSIGN_SN  C
             , SCM_MST_LINE_SN              D   /* 2025.08.20 PJ20257329 유효한 라인만 참조 */
             , GT_0039_SCP_PLAN_OPERATION   E   /* 2025.08.20 PJ20257329 SCP Plan Operation 으로 참조 범위 제한 */
         WHERE A.CHILD_ITEM_ID = B.ITEM_ID
           AND A.PLANT_ID      = B.PLANT_ID
           AND C.COMPANY_ID   = B.COMPANY_ID
           AND C.DIVISION_ID  = B.DIVISION_ID
           AND C.SITE_ID      = B.SITE_ID
           AND C.PLANT_ID     = B.PLANT_ID
           AND C.ITEM_ID      = B.ITEM_ID
           AND C.OPERATION_ID = A.CHILD_OPERATION_ID
           AND C.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)   /* 6/30 */
           AND C.PRIORITY NOT IN ('0', '9')
           AND C.ACTIVE_FLAG = 'Y'   /* 6/30 */
           AND D.COMPANY_ID   = C.COMPANY_ID
           AND D.DIVISION_ID  = C.DIVISION_ID
           AND D.SITE_ID      = C.SITE_ID
           AND D.PLANT_ID     = C.PLANT_ID
           AND D.FACTORY_ID   = C.FACTORY_ID
           AND D.OPERATION_ID = C.OPERATION_ID
           AND D.LINE_ID      = C.LINE_ID
           AND D.ACTIVE_FLAG  = 'Y'
           AND E.OPERATION_ID = C.OPERATION_ID
           AND NOT EXISTS ( SELECT 1   /* fp tact time */
                              FROM GT_0039_FP_TACT_TIME XA
                             WHERE XA.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XA.ITEM_ID       = C.ITEM_ID
                               AND XA.LINE_ID       = C.LINE_ID
                               AND XA.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME XB
                             WHERE XB.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XB.LINE_ID       = C.LINE_ID
                               AND XB.ITEM_ID       = C.ITEM_ID
                               AND XB.OPERATION_ID  = C.OPERATION_ID )
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_SCP_TACT_TIME_EXCEPT XC
                             WHERE XC.PLANT_SITE_ID = B.PLANT_SITE_ID
                               AND XC.LINE_ID       = C.LINE_ID
                               AND XC.ITEM_ID       = C.ITEM_ID
                               AND XC.OPERATION_ID  = C.OPERATION_ID );

        /* ---------------------------------------------------------------------------------------- */
        /* case 5 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* Current 생산계획 - Tact Time 범위 밖의 생산계획                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TT_CASE_5';
        INSERT INTO GT_0039_TT_CASE_5
        (
            DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , OPERATION_GROUP
          , SCM_SITE_ID
          , SITE_DESCRIPTION
          , ITEM_ID
          , LINE_ID
          , OPERATION_ID
          , PROD_MONTH
          , QTY
        )
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , C.SITE_DESCRIPTION
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , SUBSTR(A.YYYYMMDD, 1, 6)  AS PROD_MONTH
             , SUM(A.QTY)                AS QTY
          FROM SCP_ANL_PRODUCTION_PLAN   A
             , GT_0039_SCP_PLAN_VERSION  B
             , SCM_MST_SITE              C
             , SCM_MST_TACT_TIME_SN      D
             , SCP_MST_TACT_TIME_EXCEPT  E
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.PLAN_SEQ            = A.SEQ
           AND B.HORIZON_END_DATE   >= A.YYYYMMDD
           AND C.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.SITE_TYPE   = 'PLANT'
           AND C.VALID_YN    = 'Y'
           AND D.COMPANY_ID(+)   = C.COMPANY_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.SITE_ID(+)      = C.SITE_ID
           AND D.PLANT_ID(+)     = C.PLANT_ID
           AND D.OPERATION_ID(+) = A.OPERATION_ID
           AND D.LINE_ID(+)      = A.LINE_ID
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND D.MONTH(+)       >= '202608'
           AND D.MONTH(+)        = SUBSTR(A.YYYYMMDD, 1, 6)   /* 해당 범위 내 */
           AND D.TACT_TIME(+)   != 0
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PLANT_SITE_ID(+) = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.OPERATION_ID(+)  = A.OPERATION_ID
           AND E.LINE_ID(+)       = A.LINE_ID
           AND E.USE_YN(+)        = 'Y'
           AND E.TACT_TIME(+)     > 0
           AND A.MEASURE = 'PROD_PLAN_AMEND'
           AND A.QTY != 0
           AND D.ITEM_ID IS NULL   /* FP Tact Time 기간 범위내 생산계획이 아닌 경우 */
           AND E.ITEM_ID IS NULL   /* SCP Tact Time Except 기간 범위내 생산계획이 아닌 경우 */
           AND (
                 EXISTS ( SELECT 1   /* fp tact time 존재 */
                            FROM SCM_MST_TACT_TIME_SN XA
                           WHERE XA.COMPANY_ID  = C.COMPANY_ID
                             AND XA.DIVISION_ID = C.DIVISION_ID
                             AND XA.SITE_ID     = C.SITE_ID
                             AND XA.PLANT_ID    = C.PLANT_ID
                             AND XA.LINE_ID     = A.LINE_ID
                             AND XA.ITEM_ID     = A.ITEM_ID
                             AND XA.MONTH BETWEEN SUBSTR(V_FROM_YYYYMMDD, 1, 6) AND SUBSTR(V_TO_YYYYMMDD, 1, 6)
                             AND XA.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME XB
                           WHERE XB.DIVISION_ID   = A.DIVISION_ID
                             AND XB.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XB.ITEM_ID       = A.ITEM_ID
                             AND XB.OPERATION_ID  = A.OPERATION_ID
                             AND XB.LINE_ID       = A.LINE_ID
                             AND XB.VALID_YN  = 'Y'
                             AND XB.TACT_TIME > 0 )
                 OR
                 EXISTS ( SELECT 1
                            FROM SCP_MST_TACT_TIME_EXCEPT XC
                           WHERE XC.DIVISION_ID   = A.DIVISION_ID
                             AND XC.PLANT_SITE_ID = A.SCM_SITE_ID
                             AND XC.ITEM_ID       = A.ITEM_ID
                             AND XC.OPERATION_ID  = A.OPERATION_ID
                             AND XC.LINE_ID       = A.LINE_ID
                             AND XC.USE_YN    = 'Y'
                             AND XC.TACT_TIME > 0 )
               )
         GROUP BY A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , C.SITE_DESCRIPTION
                , A.ITEM_ID
                , A.LINE_ID
                , A.OPERATION_ID
                , SUBSTR(A.YYYYMMDD, 1, 6);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , SCM_MST_SITE               B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /*
        2) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 PJT ROUTE의 'PLANT' 정보를 기반으로
         >> ASSIGN 된 PLANT 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT02'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_2  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        3) (조립)CURRENT MKT FCST 에 입력되어 있는 '모델' 정보와
           해당 모델의 'LINE' ASSIGN 정보를 기반으로
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회되지 않는경우
        */
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , B.NICK_NAME
             , 'TTT03'              AS MASTER_INVLD_CD
             , A.PLANT_SITE
             , A.CHILD_OPERATION_ID AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , NULL                 AS QTY
             , A.DESCR              AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_3  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
         UNION ALL
        /*
        4) (전극) CURRENT 상위BOM '셀' LINE ASSIGN이 되어있는 '모델' 정보와
           해당 모델의 E2000(코팅) 공정의 BOM 정보를 기반으로
         >> 전극 LINE ASSIGN 정보가 모든 PLANT에서 없거나(LINE ASSIGN미등록)
         >> ASSIGN 된 LINE 내 TACT TIME 이 조회
        */
        SELECT A.DIVISION_ID
             , A.ELEC_MODEL_ID
             , A.ELEC_NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 미등록'  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4 A   /* line assign 미등록 */
             , SCM_MST_SITE      B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT04'              AS MASTER_INVLD_CD
             , C.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , NULL                 AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'line assign 등록 / tact time 미등록 / Line ' || A.LINE_ID  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_4_2 A   /* line assign 등록 / tact time 미등록 */
             , SCP_MST_FINAL_ITEM  B
             , SCM_MST_SITE        C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.SCM_SITE_ID = A.PLANT_SITE_ID
         UNION ALL
        /*
        5) CURRENT PROD AMEND 에 입력되어 있는 '모델'/'PLANT'/'LINE'/'생산계획날짜' 정보를 기반으로
         >> 생산계획 시기가 CAPA:TACT TIME 날짜외 구간에 입력되어 있는 경우
        */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , 'TTT05'              AS MASTER_INVLD_CD
             , A.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.OPERATION_ID       AS PROJECT_OPERATION
             , A.LINE_ID            AS INCOTERMS_LINE
             , A.QTY
             , 'Prod Plan Month :' || A.PROD_MONTH  AS MASTER_INVLD_CTN
          FROM GT_0039_TT_CASE_5  A
             , SCP_MST_FINAL_ITEM B
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID;

        V_STEP := '전극 Applied Cell Model';
        P_LOAD_ELEC_APPLIED_MODEL(V_DIVISION_ID);

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 - Basic Cell Nick Name 매핑                                           */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , D.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA        A
             , SCP_MST_FINAL_ITEM         B
             , GT_0039_ELEC_APPLIED_MODEL C
             , SCP_MST_ITEM_BSI_IFO       D
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.DIVISION_ID(+) = A.DIVISION_ID
           AND C.ITEM_ID(+)     = A.MODEL_ID
           AND D.ITEM_ID(+)     = CASE WHEN B.OPERATION_GROUP = 'E' THEN C.APPLIED_MODEL
                                       WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                       ELSE A.MODEL_ID
                                  END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_TACT_TIME;

    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_BOD                                                     */
    /* Description : BOD 조회                                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release PJ2024A332R                                              */
    /* 2025/08/13  hrkim   PJ20257329 수요 최종 변경일 추가                                          */
    /* 2025/09/12  hrkim   PJ20257329 소형 Cell Prod Site 적용, 중복 데이터 제거                     */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_BOD
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT     VARCHAR2(4000);
        V_STEP           VARCHAR2(100);
        V_DIVISION_ID    VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID  VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD  VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD    VARCHAR2(8  CHAR);
    BEGIN

/*
--================================================================================================================================
2) CURRENT MKT FCST DP에 입력되어 있는 '모델' / TO SITE'/ 'INCOTERMS'와
   해당 모델의 PJT ROUTE의 FROM SITE 정보를 기반으로
 >> FROM SITE/TO SITE/INCOTERMS 로 MAPPING되는 BOD ID 정보가 없는 경우

3) CURRENT SHIP SEMI/FG SHIP PLAN 에 입력되어 있는 모델
 >> 해당 모델의 출하계획 시기가 BOD ID의 FROM-TO 날짜외 계획있는 경우, 사용한 BOD ID의 VALID N 인 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'AS_SITE_PLANT';
        P_LOAD_AS_SITE_PLANT;

        V_STEP := 'CFM_MKT_DEMAND_PLAN';
        P_LOAD_CFM_MKT_DEMAND_PLAN(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'CELL_PROD_SITE_ID';
        P_LOAD_CELL_PROD_SITE_ID;

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_SCM_MST_SITE_FROM;
        DELETE FROM GT_0039_SCM_MST_SITE_TO;
        DELETE FROM GT_0039_MKT_FCST;
        DELETE FROM GT_0039_SCP_BOM;
        DELETE FROM GT_0039_PROJECT_ROUTE;
        DELETE FROM GT_0039_PR_NOT_EXISTS;
        DELETE FROM GT_0039_BOD;
        DELETE FROM GT_0039_TRANSPORT_MODE;
        DELETE FROM GT_0039_FROM_SITE_BY_PR;
        DELETE FROM GT_0039_BOD_NOT_EXISTS;
        DELETE FROM GT_0039_SCP_PLAN_VERSION;
        DELETE FROM GT_0039_SHIP_PLAN_FG;
        DELETE FROM GT_0039_SHIP_PLAN_SEMI;
        DELETE FROM GT_0039_INVALID_BOD_SHIP_PLAN;
        DELETE FROM GT_0039_TARGET_DATA;
        DELETE FROM GT_0039_TARGET_DATA_BC_NICK;

        /* ---------------------------------------------------------------------------------------- */
        /* From Site (SCM_MST_SITE) -- 6/27                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_FROM';
        INSERT INTO GT_0039_SCM_MST_SITE_FROM
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , OSP_YN
          , OPERATION_GROUP
          , COUNTRY
          , CITY
        )
        SELECT SCM_SITE_ID
             , SITE_DESCRIPTION
             , OSP_YN
             , OPERATION_GROUP
             , COUNTRY
             , CITY
          FROM SCM_MST_SITE
         WHERE DIVISION_ID = V_DIVISION_ID
           AND SITE_TYPE   = 'PLANT'
           AND VALID_YN    = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* To Site (SCM_MST_SITE) -- 6/27                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCM_MST_SITE_TO';
        INSERT INTO GT_0039_SCM_MST_SITE_TO
        (
            SCM_SITE_ID
          , SITE_DESCRIPTION
          , SITE_TYPE
          , OPERATION_GROUP
          , VMI_YN
          , COUNTRY
          , CITY
          , END_CUSTOMER
        )
        SELECT IA.SCM_SITE_ID
             , MAX(IA.SITE_DESCRIPTION)                                                                                AS SITE_DESCRIPTION
             , MAX(IA.SITE_TYPE)                                                                                       AS SITE_TYPE
             , MAX(IA.OPERATION_GROUP)                                                                                 AS OPERATION_GROUP
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.VMI_YN       ELSE NULL END)  AS VMI_YN
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.COUNTRY      ELSE NULL END)  AS COUNTRY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.CITY         ELSE NULL END)  AS CITY
             , MAX(CASE WHEN IA.SITE_TYPE = 'SALES' AND IA.DIVISION_ID = V_DIVISION_ID THEN IA.END_CUSTOMER ELSE NULL END)  AS END_CUSTOMER
          FROM ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN    = 'Y'
                    AND DIVISION_ID = V_DIVISION_ID
                  UNION
                 SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , SITE_DESCRIPTION
                      , SITE_TYPE
                      , OPERATION_GROUP
                      , VMI_YN
                      , COUNTRY
                      , CITY
                      , END_CUSTOMER
                   FROM SCM_MST_SITE
                  WHERE VALID_YN = 'Y'
                    AND SCM_SITE_ID LIKE '%' || '-A' ) IA
         GROUP BY IA.SCM_SITE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST (To Site)                                                                        */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'MKT_FCST';
        INSERT INTO GT_0039_MKT_FCST
        (
            SALES_SITE_ID
          , TO_COUNTRY
          , TO_CITY
          , CUSTOMER
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MEASURE
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
        )
        SELECT A.SCM_SITE_ID                  AS SALES_SITE_ID
             , B.COUNTRY                      AS TO_COUNTRY
             , B.CITY                         AS TO_CITY
             , B.END_CUSTOMER                 AS CUSTOMER
             , A.PROJECT_CODE                 AS PROJECT_CODE
             , A.ITEM_ID                      AS SALES_ITEM_ID
             , A.INCOTERMS
             , A.MEASURE
             , SUBSTR(C.FLOW_ID, 1, 5)        AS MODEL_OPERATION_ID
             , C.OPERATION_GROUP              AS MODEL_OPERATION_GROUP
             , C.NICK_NAME                    AS MODEL_NICK_NAME
             , MIN(A.YYYYMMDD)                AS SALES_FROM_YYYYMMDD
             , MAX(A.YYYYMMDD)                AS SALES_TO_YYYYMMDD
             , SUM(CASE WHEN NVL(E.RN, 1) = 1 THEN A.QTY ELSE 0 END)  AS QTY
             , TO_CHAR(MAX(A.LAST_UPDATE_DATE), 'YYYY-MM-DD HH24:MI:SS')  AS MF_LAST_UPDATE_DATE   /* 2025.08.13 추가 */
             , E.CELL_PROD_SITE_ID
             , E.COMPANY_ID                   AS COMPANY_ID_CELL_PROD
             , E.SITE_ID                      AS SITE_ID_CELL_PROD
             , E.PLANT_ID                     AS PLANT_ID_CELL_PROD
          FROM DM_PLN_MKT_FCST           A
             , GT_0039_SCM_MST_SITE_TO   B
             , SCP_MST_FINAL_ITEM        C
             , GT_0039_AS_SITE_PLANT     D
             , GT_0039_CFM_MKT_DMND_PLAN E
         WHERE B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND C.OPERATION_GROUP != 'E'   /* 전극 제외 */
           AND D.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND E.DIVISION_ID(+)   = A.DIVISION_ID
           AND E.PROJECT_CODE(+)  = A.PROJECT_CODE
           AND E.SCM_SITE_ID(+)   = A.SCM_SITE_ID
           AND E.ITEM_ID(+)       = A.ITEM_ID
           AND E.DOM_EXP(+)       = A.DOM_EXP
           AND E.FCST_TYPE(+)     = A.FCST_TYPE
           AND E.INCOTERMS(+)     = A.INCOTERMS
           AND E.MEASURE(+)       = A.MEASURE
           AND E.YYYYMMDD(+)      = A.YYYYMMDD
           AND E.PLANT_SITE_ID(+) = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.MEASURE     = CASE WHEN B.SITE_TYPE = 'SALES' AND B.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                    WHEN B.VMI_YN = 'Y'                                    THEN 'VMI_In_Req'
                                    WHEN TRIM(A.ATTRIBUTE10) IS NULL                       THEN 'MKT_FCST'   /* AS-IS ISNULL(ATTRIBUTE10,'')='' - 이관 시 빈값이 공백으로 들어와 IS NULL 만으로는 빠진다 */
                               END
           AND A.YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
           AND A.QTY != 0
           AND D.SCM_SITE_ID IS NULL
         GROUP BY A.SCM_SITE_ID
                , B.COUNTRY
                , B.CITY
                , B.END_CUSTOMER
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.INCOTERMS
                , A.MEASURE
                , C.FLOW_ID
                , C.OPERATION_GROUP
                , C.NICK_NAME
                , E.CELL_PROD_SITE_ID
                , E.COMPANY_ID
                , E.SITE_ID
                , E.PLANT_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* BOM                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_BOM';
        INSERT INTO GT_0039_SCP_BOM
        (
            MODEL_ID
          , COMPANY_ID
          , SITE_ID
          , PLANT_ID
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , CHILD_ELECTRODE_TYPE
        )
        SELECT DISTINCT
               A.MODEL_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.CHILD_ITEM_ID
             , CASE WHEN C.OPERATION_GROUP_ID NOT IN ('A', 'E')
                    THEN 'P'
                    ELSE C.OPERATION_GROUP_ID
               END                      AS CHILD_OPERATION_GROUP
             , SUBSTR(C.FLOW_ID, 1, 5)  AS CHILD_OPERATION_ID
             , C.ELECTRODE_TYPE         AS CHILD_ELECTRODE_TYPE
          FROM SCM_MST_MODEL_BOM   A
             , SCM_MST_ITEM_SN     B
             , SCP_MST_FINAL_ITEM  C
             , SCM_MST_ITEM_SN     D
         WHERE B.ITEM_ID     = A.CHILD_ITEM_ID
           AND B.COMPANY_ID  = A.CHILD_COMPANY_ID
           AND B.DIVISION_ID = A.CHILD_DIVISION_ID
           AND B.SITE_ID     = A.CHILD_SITE_ID
           AND B.ACTIVE_FLAG = 'Y'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.CHILD_ITEM_ID
           AND C.ATTRIBUTE8 NOT LIKE 'CA%'
           AND C.OPERATION_GROUP != 'E'
           AND D.ITEM_ID(+)     = A.PARENT_ITEM_ID
           AND D.COMPANY_ID(+)  = A.COMPANY_ID
           AND D.DIVISION_ID(+) = A.DIVISION_ID
           AND D.SITE_ID(+)     = A.SITE_ID
           AND D.ACTIVE_FLAG(+) = 'Y'
           AND A.DIVISION_ID  = V_DIVISION_ID
           AND A.ALT_PRIORITY = 'Y'
           AND (A.PARENT_ITEM_ID = '*' OR D.ITEM_ID IS NOT NULL)
           AND EXISTS ( SELECT 1
                          FROM GT_0039_MKT_FCST XA
                         WHERE A.MODEL_ID   = XA.SALES_ITEM_ID
                           AND A.COMPANY_ID = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.COMPANY_ID_CELL_PROD
                                                   ELSE A.COMPANY_ID
                                              END
                           AND A.SITE_ID    = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.SITE_ID_CELL_PROD
                                                   ELSE A.SITE_ID
                                              END
                           AND A.PLANT_ID   = CASE WHEN XA.CELL_PROD_SITE_ID IS NOT NULL AND C.OPERATION_GROUP = 'A'
                                                   THEN XA.PLANT_ID_CELL_PROD
                                                   ELSE A.PLANT_ID
                                              END );

        /* ---------------------------------------------------------------------------------------- */
        /* PROJECT ROUTE                                                                             */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PROJECT_ROUTE';
        INSERT INTO GT_0039_PROJECT_ROUTE
        (
            ITEM_ID
          , SALES_SITE_ID
          , PROJECT_CODE
          , PLANT_SITE_ID
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , COUNTRY
          , CITY
          , PR_PRIORITY
        )
        SELECT A.ITEM_ID
             , A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.PLANT_SITE_ID
             , A.FROM_YYYYMMDD
             , A.TO_YYYYMMDD
             , B.COUNTRY
             , B.CITY
             , ROW_NUMBER() OVER (PARTITION BY A.ITEM_ID
                                             , A.SALES_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.FROM_YYYYMMDD
                                             , A.TO_YYYYMMDD
                                      ORDER BY A.PRIORITY)  AS PR_PRIORITY
          FROM SCM_MST_SITE_ITEM_PRIORITY  A
             , GT_0039_SCM_MST_SITE_FROM   B
         WHERE B.SCM_SITE_ID = A.PLANT_SITE_ID
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.VALID_YN    = 'Y'
           AND A.TO_YYYYMMDD >= V_FROM_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* MKT FCST 기준 Project Route 존재하지 않는 데이터                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'PR_NOT_EXISTS';
        INSERT INTO GT_0039_PR_NOT_EXISTS
        (
            SALES_SITE_ID
          , PROJECT_CODE
          , SALES_ITEM_ID
          , INCOTERMS
          , MODEL_OPERATION_ID
          , MODEL_OPERATION_GROUP
          , MODEL_NICK_NAME
          , SALES_FROM_YYYYMMDD
          , SALES_TO_YYYYMMDD
          , QTY
          , MF_LAST_UPDATE_DATE
          , CELL_PROD_SITE_ID
          , COMPANY_ID_CELL_PROD
          , SITE_ID_CELL_PROD
          , PLANT_ID_CELL_PROD
          , CHILD_ITEM_ID
          , CHILD_OPERATION_GROUP
          , CHILD_OPERATION_ID
          , MASTER_INVLD_CD
          , MASTER_INVLD_CTN
        )
        SELECT A.SALES_SITE_ID
             , A.PROJECT_CODE
             , A.SALES_ITEM_ID
             , A.INCOTERMS
             , A.MODEL_OPERATION_ID
             , A.MODEL_OPERATION_GROUP
             , A.MODEL_NICK_NAME
             , A.SALES_FROM_YYYYMMDD
             , A.SALES_TO_YYYYMMDD
             , A.QTY
             , A.MF_LAST_UPDATE_DATE
             , A.CELL_PROD_SITE_ID
             , A.COMPANY_ID_CELL_PROD
             , A.SITE_ID_CELL_PROD
             , A.PLANT_ID_CELL_PROD
             , B.CHILD_ITEM_ID
             , B.CHILD_OPERATION_GROUP
             , B.CHILD_OPERATION_ID
             , 'COM01'                                       AS MASTER_INVLD_CD
             , 'Sales Period:' || A.SALES_FROM_YYYYMMDD || '~' || A.SALES_TO_YYYYMMDD
            || ', Target Item:' || B.CHILD_ITEM_ID
            || ', FCST Last Update :' || A.MF_LAST_UPDATE_DATE  AS MASTER_INVLD_CTN   /* 2025.08.13 수요 최종 변경일 추가 */
          FROM GT_0039_MKT_FCST A
             , GT_0039_SCP_BOM  B
         WHERE A.SALES_ITEM_ID = B.MODEL_ID
           AND B.COMPANY_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.COMPANY_ID_CELL_PROD
                                   ELSE B.COMPANY_ID
                              END
           AND B.SITE_ID    = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.SITE_ID_CELL_PROD
                                   ELSE B.SITE_ID
                              END
           AND B.PLANT_ID   = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                   THEN A.PLANT_ID_CELL_PROD
                                   ELSE B.PLANT_ID
                              END
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_PROJECT_ROUTE XA
                             WHERE XA.ITEM_ID = B.CHILD_ITEM_ID
                               AND XA.PLANT_SITE_ID = CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND B.CHILD_OPERATION_GROUP = 'A'
                                                           THEN A.CELL_PROD_SITE_ID
                                                           ELSE XA.PLANT_SITE_ID
                                                      END
                               AND XA.PROJECT_CODE  = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '/'
                                                           ELSE A.PROJECT_CODE
                                                      END
                               AND XA.SALES_SITE_ID = CASE WHEN V_DIVISION_ID IN ('40', '82') OR B.CHILD_OPERATION_GROUP = 'E'
                                                           THEN '-'
                                                           ELSE A.SALES_SITE_ID
                                                      END );

        /* ---------------------------------------------------------------------------------------- */
        /* case 2 : BOD                                                                              */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* Transport Mode                                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TRANSPORT_MODE';
        INSERT INTO GT_0039_TRANSPORT_MODE
        (
            FROM_COUNTRY
          , FROM_CITY
          , TO_COUNTRY
          , TO_CITY
          , TRANSPORT_MODE
        )
        SELECT DISTINCT
               FROM_COUNTRY
             , FROM_CITY
             , TO_COUNTRY
             , TO_CITY
             , TRANSPORT_MODE
          FROM SCP_MST_DISTRIBUTION_ROUTE
         WHERE VALID_YN = 'Y';

        /* ---------------------------------------------------------------------------------------- */
        /* From Site - Project Route 기준                                                            */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'FROM_SITE_BY_PR';
        INSERT INTO GT_0039_FROM_SITE_BY_PR
        (
            DIVISION_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , ITEM_ID
          , PROJECT_CODE
          , SALES_SITE_ID
          , PLANT_TYPE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , A.SCM_SITE_ID                    AS FROM_SITE
             , A.COUNTRY                        AS FROM_COUNTRY
             , A.CITY                           AS FROM_CITY
             , B.ITEM_ID                        AS ITEM_ID
             , B.PROJECT_CODE                   AS PROJECT_CODE
             , C.SALES_SITE_ID
             , SUBSTR(C.PLANT_SITE_ID, -1)      AS PLANT_TYPE
             , C.FROM_YYYYMMDD
             , C.TO_YYYYMMDD
          FROM GT_0039_SCM_MST_SITE_FROM A   /* From site (Plant Site) */
             , SCM_MST_SITE_ITEM         B
             , GT_0039_PROJECT_ROUTE     C
         WHERE B.DIVISION_ID = V_DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.VALID_YN    = 'Y'
           AND C.PLANT_SITE_ID = B.SCM_SITE_ID
           AND C.PROJECT_CODE  = B.PROJECT_CODE
           AND C.ITEM_ID       = B.ITEM_ID
           AND NOT (A.OSP_YN = 'Y' AND A.OPERATION_GROUP = 'A');   /* From site 가 외주 Cell 사이트인 경우 제외 (소형 KR02149300_40-A) : asis 로직 */

        /* ---------------------------------------------------------------------------------------- */
        /* To Sales BOD 가 없는 경우 - Sales Model                                                   */
        /* BOD Requried Case 1 (asis 1.1과 1.2)                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD_NOT_EXISTS';
        INSERT INTO GT_0039_BOD_NOT_EXISTS
        (
            DIVISION_ID
          , ITEM_ID
          , FROM_SITE
          , FROM_COUNTRY
          , FROM_CITY
          , TO_SITE
          , TO_COUNTRY
          , TO_CITY
          , INCOTERMS
          , PROJECT_CODE
          , OPERATION_GROUP
          , NICK_NAME
        )
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , A.INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID   /* Sales Model */
           /* PJ20257329 2025.09.12 소형 Cell Prod Site 적용 */
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = A.INCOTERMS
                               AND XB.ITEM_ID     = B.ITEM_ID          /* 7/2 BOD item 확인 */
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD )
         UNION
        /* To Sales(VMI 및 AS창고) incoterms DAP BOD 가 없는 경우 - BOD Requried Case 2 (asis 2.1과 2.2) */
        SELECT DISTINCT
               B.DIVISION_ID
             , B.ITEM_ID
             , B.FROM_SITE
             , B.FROM_COUNTRY
             , B.FROM_CITY
             , A.SALES_SITE_ID           AS TO_SITE
             , A.TO_COUNTRY
             , A.TO_CITY
             , 'DAP'                     AS INCOTERMS
             , A.PROJECT_CODE
             , A.MODEL_OPERATION_GROUP   AS OPERATION_GROUP
             , A.MODEL_NICK_NAME         AS NICK_NAME
          FROM GT_0039_MKT_FCST        A
             , GT_0039_FROM_SITE_BY_PR B
         WHERE A.SALES_ITEM_ID = B.ITEM_ID
           AND CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.MODEL_OPERATION_GROUP = 'A'
                    THEN A.CELL_PROD_SITE_ID
                    ELSE B.FROM_SITE
               END = B.FROM_SITE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '/'
                    ELSE A.PROJECT_CODE
               END = B.PROJECT_CODE
           AND CASE WHEN V_DIVISION_ID IN ('40', '82') OR A.MODEL_OPERATION_GROUP = 'E'
                    THEN '-'
                    ELSE A.SALES_SITE_ID
               END = B.SALES_SITE_ID
           AND A.MEASURE IN ('AS_In_Req', 'VMI_In_Req')
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_BOD      XA
                                 , SCP_MST_BOD_ITEM XB   /* 7/2 추가 */
                             WHERE XB.BOD_ID = XA.BOD_ID
                               AND XA.DIVISION_ID = B.DIVISION_ID
                               AND XA.FROM_SITE   = B.FROM_SITE
                               AND XA.TO_SITE     = A.SALES_SITE_ID
                               AND XA.INCOTERMS   = 'DAP'
                               AND XB.ITEM_ID     = B.ITEM_ID
                               AND XB.TO_YYYYMMDD >= V_FROM_YYYYMMDD );

        /* ---------------------------------------------------------------------------------------- */
        /* case 3 : SCP Plan 버전 정보                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SCP_PLAN_VERSION';
        INSERT INTO GT_0039_SCP_PLAN_VERSION
        (
            DIVISION_ID
          , PLAN_TYPE
          , PLAN_SEQ
          , PLAN_START_YYYYMMDD
          , HORIZON_END_DATE
          , PLAN_STATUS
          , CONFIRM_FLAG
          , PLAN_PRIORITY
        )
        SELECT IA.DIVISION_ID
             , IA.PLAN_TYPE
             , IA.PLAN_SEQ
             , IA.PLAN_START_YYYYMMDD
             , IA.HORIZON_END_DATE
             , IA.PLAN_STATUS
             , IA.CONFIRM_FLAG
             , IA.PLAN_PRIORITY
          FROM ( SELECT A.DIVISION_ID
                      , B.PLAN_TYPE
                      , B.PLAN_SEQ
                      , A.PLAN_NAME                            AS PLAN_START_YYYYMMDD
                      , SUBSTR(A.HORIZON_END_DATE, 1, 8)       AS HORIZON_END_DATE
                      , B.PLAN_STATUS
                      , B.CONFIRM_FLAG
                      , DENSE_RANK() OVER (PARTITION BY A.DIVISION_ID
                                               ORDER BY A.PLAN_NAME DESC
                                                      , B.INPUT_START_DATE DESC)  AS PLAN_PRIORITY
                   FROM SCM_MST_PLAN        A
                      , SCM_MST_PLAN_DETAIL B
                  WHERE B.DIVISION_ID = A.DIVISION_ID
                    AND B.PLAN_ID     = A.PLAN_ID
                    AND B.PLAN_STATUS = '1'   /* 정상 완료 */
                    AND A.DIVISION_ID = V_DIVISION_ID
                    AND A.PLAN_CYCLE  = 'WEEKLY'
                    AND A.PLAN_NAME   = V_FROM_YYYYMMDD ) IA
         WHERE IA.PLAN_PRIORITY = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* FG 출하계획 -- 6/27                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_FG';
        INSERT INTO GT_0039_SHIP_PLAN_FG
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION A
             , SCP_ANL_SHIPMENT_PLAN_FG B
         WHERE B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE   /* 6/13 */
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;

        /* ---------------------------------------------------------------------------------------- */
        /* SEMI 출하계획 -- 6/27                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SHIP_PLAN_SEMI';
        INSERT INTO GT_0039_SHIP_PLAN_SEMI
        (
            DIVISION_ID
          , ITEM_ID
          , YYYYMMDD
          , BOD_ID
          , QTY
        )
        SELECT B.DIVISION_ID
             , B.ITEM_ID
             , B.YYYYMMDD
             , B.BOD_ID
             , B.QTY
          FROM GT_0039_SCP_PLAN_VERSION   A
             , SCP_ANL_SHIPMENT_PLAN_SEMI B
         WHERE B.DIVISION_ID         = A.DIVISION_ID
           AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND B.PLAN_TYPE           = A.PLAN_TYPE
           AND B.SEQ                 = A.PLAN_SEQ
           AND B.YYYYMMDD           <= A.HORIZON_END_DATE
           AND B.MEASURE = 'SHIP_PLAN_AMEND'
           AND B.QTY != 0;

        /* ---------------------------------------------------------------------------------------- */
        /* BOD Valid N 인 FG/SEMI 출하 계획                                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INVALID_BOD_SHIP_PLAN';
        INSERT INTO GT_0039_INVALID_BOD_SHIP_PLAN
        (
            DV
          , BOD_VALID_YN
          , DIVISION_ID
          , ITEM_ID
          , NICK_NAME
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , QTY
          , MIN_YMD
          , MAX_YMD
        )
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 FG출하 계획 */
        SELECT 'FG'             AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_FG A
             , SCP_MST_FINAL_ITEM   B
             , GT_0039_BOD          C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)   /* 유효기간 범위 밖 출하계획 */
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE
         UNION ALL
        /* BOD Valid 'N' 이거나 BOD 유효기간 범위 밖 SEMI출하 계획 */
        SELECT 'SEMI'           AS DV
             , C.BOD_VALID_YN
             , A.DIVISION_ID
             , A.ITEM_ID
             , B.NICK_NAME
             , C.FROM_SITE
             , C.TO_SITE
             , C.INCOTERMS
             , C.TRANSPORT_MODE
             , SUM(A.QTY)       AS QTY
             , MIN(A.YYYYMMDD)  AS MIN_YMD
             , MAX(A.YYYYMMDD)  AS MAX_YMD
          FROM GT_0039_SHIP_PLAN_SEMI A
             , SCP_MST_FINAL_ITEM     B
             , GT_0039_BOD            C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.BOD_ID      = A.BOD_ID
           AND ( C.BOD_VALID_YN = 'N'
                 OR
                 NOT (A.YYYYMMDD BETWEEN C.FROM_YYYYMMDD AND C.TO_YYYYMMDD)
               )
         GROUP BY C.BOD_VALID_YN
                , A.DIVISION_ID
                , A.ITEM_ID
                , B.NICK_NAME
                , C.FROM_SITE
                , C.TO_SITE
                , C.INCOTERMS
                , C.TRANSPORT_MODE;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인대상 데이터 전체                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA';
        INSERT INTO GT_0039_TARGET_DATA
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        /* Project Route 미등록 */
        SELECT V_DIVISION_ID        AS DIVISION_ID
             , A.SALES_ITEM_ID      AS MODEL_ID
             , A.MODEL_NICK_NAME    AS NICK_NAME
             , A.MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
               /* PJ20257329 2025.09.12 소형 Cell Prod Site 정보 추가 */
            || CASE WHEN A.CELL_PROD_SITE_ID IS NOT NULL AND A.CHILD_OPERATION_GROUP = 'A'
                    THEN ' ,Cell Prod Site : ' || C.NAME
                    ELSE ''
               END                  AS MASTER_INVLD_CTN
          FROM GT_0039_PR_NOT_EXISTS      A
             , GT_0039_SCM_MST_SITE_TO    B
             , GT_0039_CELL_PROD_SITE_ID  C
         WHERE B.SCM_SITE_ID = A.SALES_SITE_ID
           AND C.CODE(+)     = A.CELL_PROD_SITE_ID
         UNION ALL
        /* BOD 미등록 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD02'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , A.PROJECT_CODE       AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , NULL                 AS QTY
             , 'From Site:' || C.SITE_DESCRIPTION  AS MASTER_INVLD_CTN
          FROM GT_0039_BOD_NOT_EXISTS    A
             , GT_0039_SCM_MST_SITE_TO   B
             , GT_0039_SCM_MST_SITE_FROM C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE
         UNION ALL
        /* BOD 유효기간 밖의 출하계획 또는 invalid BOD */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , 'BOD03'              AS MASTER_INVLD_CD
             , B.SITE_DESCRIPTION   AS SALES_PLANT_SITE
             , NULL                 AS PROJECT_OPERATION
             , A.INCOTERMS          AS INCOTERMS_LINE
             , A.QTY
             , 'From Site:' || C.SITE_DESCRIPTION
            || ', FROM YMD : ' || A.MIN_YMD
            || ', TO_YMD : '   || A.MAX_YMD      AS MASTER_INVLD_CTN
          FROM GT_0039_INVALID_BOD_SHIP_PLAN A
             , GT_0039_SCM_MST_SITE_TO       B
             , GT_0039_SCM_MST_SITE_FROM     C
         WHERE B.SCM_SITE_ID = A.TO_SITE
           AND C.SCM_SITE_ID = A.FROM_SITE;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'TARGET_DATA_BC_NICK';
        INSERT INTO GT_0039_TARGET_DATA_BC_NICK
        (
            DIVISION_ID
          , MODEL_ID
          , NICK_NAME
          , BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , SALES_PLANT_SITE
          , PROJECT_OPERATION
          , INCOTERMS_LINE
          , QTY
          , MASTER_INVLD_CTN
        )
        SELECT A.DIVISION_ID
             , A.MODEL_ID
             , A.NICK_NAME
             , C.BASIC_NICK_NAME    AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.SALES_PLANT_SITE
             , A.PROJECT_OPERATION
             , A.INCOTERMS_LINE
             , A.QTY
             , A.MASTER_INVLD_CTN
          FROM GT_0039_TARGET_DATA  A
             , SCP_MST_FINAL_ITEM   B
             , SCP_MST_ITEM_BSI_IFO C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.MODEL_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.MODEL_ID
                               END;

        V_STEP := 'TARGET_DATA_PLAN_GROUP';
        P_LOAD_TARGET_DATA_PLAN_GROUP;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT DISTINCT   /* PJ20257329 2025.09.12 중복 데이터 제거 */
                   A.DIVISION_ID
                 , A.MODEL_ID                       AS ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                              AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')      AS OPMZ_PLAN_GR_ID
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                     AS MASTER_INVLD_MSG
                 , A.SALES_PLANT_SITE
                 , A.PROJECT_OPERATION
                 , A.INCOTERMS_LINE
                 , A.QTY
                 , A.MASTER_INVLD_CTN
                 , A.DV                             /* 2025.08.13 확인 차원에서 추가 */
              FROM GT_0039_TGT_DATA_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND ( A.MODEL_ID  LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY MASTER_INVLD_MSG
                    , A.DIVISION_ID
                    , ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_BOD;


    /************************************************************************************************/
    /* Program ID  : SCP0039_GET_VALIDATION_INTRANSIT_INVENTORY                                     */
    /* Description : Intransit Inventory 조회                                                       */
    /*----------------------------------------------------------------------------------------------*/
    /* 2025/07/10  kh      Initial Release                                                          */
    /* 2025/08/14  hrkim   PJ20257329 scp plan operation 으로 공정 참조 범위 제한                    */
    /* 2025/08/26  hrkim   PJ20257329 plan_group_info 임시테이블 추가 사용                           */
    /* 2025/09/12  hrkim   PJ20257329 소형/ESS plan group 매핑 로직 자동차와 동일하게 적용           */
    /* 2026.09.11  [MSSQL -> Oracle 전환]                                                           */
    /************************************************************************************************/
    PROCEDURE P_SCP0039_GET_VALIDATION_INTRANSIT_INV
    (
        P_DIVISION_ID    IN  VARCHAR2,
        P_SEARCH_TYPE    IN  VARCHAR2,
        P_PLAN_GROUP_ID  IN  VARCHAR2,
        P_ITEM_ID        IN  VARCHAR2,
        O_RC1            OUT SYS_REFCURSOR
    )
    IS
        V_PROC_INPUT            VARCHAR2(4000);
        V_STEP                  VARCHAR2(100);
        V_DIVISION_ID           VARCHAR2(30 CHAR) := P_DIVISION_ID;
        V_PLAN_GROUP_ID         VARCHAR2(30 CHAR) := P_PLAN_GROUP_ID;
        V_FROM_YYYYMMDD         VARCHAR2(8  CHAR);
        V_TO_YYYYMMDD           VARCHAR2(8  CHAR);
        V_LAST_SUNDAY           VARCHAR2(8  CHAR);   /* 재고 기준 일자 */
        V_DM_CUTOFF_YYYYMMDD    VARCHAR2(8  CHAR);
        V_DM_VERSION_NO         VARCHAR2(50 CHAR);
    BEGIN

/*
--================================================================================================================================
### Intransit Invetory 요구사항

※ 조회되는 정보는 조회되는주 일요일 CUT-OFF된 재고로 제한
※ DEMAND GROUPING 고려해야함.

1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로
 >> DP에 해당 SALES SITE정보 없는 경우
 ** 고객위탁 정보도 활용해야함 (SO RESERVED)

2) INTRANST INV에 모델, TO SITE, INCOTERMS 정보를 기반으로
 >>  DP에 해당 SALES SITE의 INCOTERMS 가 없는 경우

3) INTRANST INV 도착예상 일자정보를 기반으로
 >> 금주 월요일이 1주일이상 지연 경우
--================================================================================================================================
*/

        V_PROC_INPUT := 'P_DIVISION_ID='   || P_DIVISION_ID
                     || ',P_SEARCH_TYPE='  || P_SEARCH_TYPE
                     || ',P_PLAN_GROUP_ID='|| P_PLAN_GROUP_ID
                     || ',P_ITEM_ID='      || P_ITEM_ID;

        V_STEP := '기준 일자 정보';
        P_SET_BASE_DATE(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        /* 마지막 일요일 (재고 참조 기준일자) */
        V_LAST_SUNDAY := TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* DM Cutoff YYYYMMDD / 버전 정보 */
        V_STEP := 'DM Cutoff / 버전 정보';
        SELECT MAX(IA.CUTOFF_YYYYMMDD)
             , MAX(IA.VERSION_NO)
          INTO V_DM_CUTOFF_YYYYMMDD
             , V_DM_VERSION_NO
          FROM ( SELECT A.CUTOFF_YYYYMMDD
                      , A.VERSION_NO
                   FROM DM_PLN_NET_DEMAND A   /* DIVISION_ID, CUTOFF_YYYYMMDD (IDX01_DM_PLN_NET_DEMAND) */
                      , DM_MST_VERSION     B  /* DIVISION_ID, VERSION_NO */
                  WHERE B.DIVISION_ID  = A.DIVISION_ID
                    AND B.VERSION_NO   = A.VERSION_NO
                    AND B.VERSION_TYPE = 'MF_W'
                    AND A.DIVISION_ID  = V_DIVISION_ID
                  ORDER BY A.CUTOFF_YYYYMMDD DESC
                         , A.VERSION_NO      DESC ) IA
         WHERE ROWNUM = 1;

        V_STEP := 'SCP Plan 공정 정보';
        P_LOAD_SCP_PLAN_OPERATION;

        V_STEP := 'Plan Group 정보';
        P_LOAD_PLAN_GROUP_INFO(V_DIVISION_ID, V_FROM_YYYYMMDD, V_TO_YYYYMMDD);

        V_STEP := 'GTT 초기화';
        DELETE FROM GT_0039_INTRANSIT_INVENTORY;
        DELETE FROM GT_0039_SALES_SITE_INVENTORY;
        DELETE FROM GT_0039_DEMAND_PLAN;
        DELETE FROM GT_0039_INT_TGT_CASE_1;
        DELETE FROM GT_0039_INT_TGT_CASE_2;
        DELETE FROM GT_0039_INT_TGT_CASE_3;
        DELETE FROM GT_0039_INT_TARGET_DATA;
        DELETE FROM GT_0039_INT_TGT_BC_NICK;
        DELETE FROM GT_0039_INT_TGT_PLAN_GROUP;
        DELETE FROM GT_0039_BOD_II;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INTRANSIT_INVENTORY';
        INSERT INTO GT_0039_INTRANSIT_INVENTORY
        (
            GROUP_ID
          , GROUP_NAME
          , NICK_NAME
          , RESULT_DATE
          , RESULT_TYPE
          , DIVISION_ID
          , COMPANY_ID
          , PLANT_ID
          , SHIPMENT_NO
          , PROJECT_CODE
          , ITEM_ID
          , PLANT_ISSUE_DATE
          , INCOTERMS_ORG
          , INCOTERMS
          , SHIPTO_CODE
          , FROM_SCM_SITE_ID
          , TO_SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , DELIVERY_QTY
          , UOM
          , TRANSPORT_MODE
          , F_DEST_ETA_DATE
          , F_DEST_ATA_DATE
        )
        SELECT NVL(D.GROUP_ID, 'NONE')             AS GROUP_ID
             , E.GROUP_NAME
             , C.NICK_NAME
             , A.RESULT_DATE
             , A.RESULT_TYPE
             , A.DIVISION_ID
             , A.COMPANY_ID
             , A.PLANT_ID
             , A.SHIPMENT_NO
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.PLANT_ISSUE_DATE
             , A.INCOTERMS                         AS INCOTERMS_ORG
             , NVL(A.FINAL_INCOTERMS, A.INCOTERMS) AS INCOTERMS
             , A.SHIPTO_CODE
             , A.FROM_SCM_SITE_ID
             , A.TO_SCM_SITE_ID
             , B.SITE_DESCRIPTION                  AS SALES_SITE_DESCRIPTION
             , A.DELIVERY_QTY
             , A.UOM
             , A.TRANSPORT_MODE
             , A.F_DEST_ETA_DATE
             , A.F_DEST_ATA_DATE
          FROM SCM_DNM_INTRANSIT_C       A
             , SCM_MST_SITE              B
             , SCP_MST_FINAL_ITEM        C
             , SCP_MST_ITEM_GROUP_DETAIL D   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        E   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.TO_SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND D.DIVISION_ID(+)  = A.DIVISION_ID
           AND D.PROJECT_CODE(+) = A.PROJECT_CODE
           AND D.ITEM_ID(+)      = A.ITEM_ID
           AND E.DIVISION_ID(+)  = D.DIVISION_ID
           AND E.GROUP_ID(+)     = D.GROUP_ID
           AND ( D.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = D.DIVISION_ID
                                AND XA.GROUP_ID    = D.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.RESULT_DATE = V_LAST_SUNDAY
           AND A.RESULT_TYPE IN ('C', 'B', 'I')   /* C(법인간)/B(SO Reserved)/I(GTS) */
           AND A.DIVISION_ID = V_DIVISION_ID;

        /* ---------------------------------------------------------------------------------------- */
        /* Sales Site Inventory                                                                      */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'SALES_SITE_INVENTORY';
        INSERT INTO GT_0039_SALES_SITE_INVENTORY
        (
            CUTOFF_DATE
          , STOCK_TYPE
          , COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , NICK_NAME
          , ITEM_ID
          , CUSTOMER_CODE
          , SCM_SITE_ID
          , SALES_SITE_DESCRIPTION
          , SCM_QTY
          , QTY_UOM
        )
        SELECT A.CUTOFF_DATE
             , A.STOCK_TYPE
             , A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , C.NICK_NAME
             , A.ITEM_ID
             , CASE A.STOCK_TYPE
                    WHEN 'VMI' THEN A.STORAGE_ID
                    ELSE NULL
               END                   AS CUSTOMER_CODE
             , A.SCM_SITE_ID
             , B.SITE_DESCRIPTION    AS SALES_SITE_DESCRIPTION
             , A.SCM_QTY
             , A.QTY_UOM
          FROM SCM_DNM_STOCK      A
             , SCM_MST_SITE       B
             , SCP_MST_FINAL_ITEM C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND B.SITE_TYPE   = 'SALES'
           AND C.DIVISION_ID = A.DIVISION_ID
           AND C.ITEM_ID     = A.ITEM_ID
           AND A.CUTOFF_DATE = V_LAST_SUNDAY
           AND A.DIVISION_ID = V_DIVISION_ID
           AND A.SCM_QTY > 0;

        /* ---------------------------------------------------------------------------------------- */
        /* Demand Plan                                                                               */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'DEMAND_PLAN';
        INSERT INTO GT_0039_DEMAND_PLAN
        (
            DIVISION_ID
          , GROUP_ID
          , GROUP_NAME
          , ITEM_ID
          , SCM_SITE_ID
          , INCOTERMS
          , PROJECT_CODE
          , CUTOFF_YYYYMMDD
          , QTY
          , RN_1
          , RN_2
          , RN_3
        )
        SELECT A.DIVISION_ID
             , NVL(D.GROUP_ID, 'NONE')  AS GROUP_ID
             , D.GROUP_NAME
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , CASE WHEN B.VMI_YN = 'Y'
                    THEN 'DAP'
                    ELSE A.INCOTERMS
               END                      AS INCOTERMS
             , A.PROJECT_CODE
             , A.CUTOFF_YYYYMMDD
             , A.QTY
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                      ORDER BY A.QTY DESC)  AS RN_1
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                             , A.PROJECT_CODE
                                             , A.INCOTERMS
                                      ORDER BY A.QTY DESC)  AS RN_2
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , NVL(C.ITEM_ID, A.ITEM_ID)
                                             , A.SCM_SITE_ID
                                      ORDER BY A.QTY DESC)  AS RN_3   /* sales site 재고 확인용 */
          FROM DM_PLN_NET_DEMAND        A
             , SCM_MST_SITE             B
             , SCP_MST_ITEM_GROUP_DETAIL C   /* DIVISION_ID, PROJECT_CODE, ITEM_ID */
             , SCP_MST_ITEM_GROUP        D   /* DIVISION_ID, GROUP_ID */
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.SCM_SITE_ID = A.SCM_SITE_ID
           AND C.DIVISION_ID(+)  = A.DIVISION_ID
           AND C.PROJECT_CODE(+) = A.PROJECT_CODE
           AND C.ITEM_ID(+)      = A.ITEM_ID
           AND D.DIVISION_ID(+)  = C.DIVISION_ID
           AND D.GROUP_ID(+)     = C.GROUP_ID
           AND ( C.GROUP_ID IS NULL
                 OR EXISTS ( SELECT 1
                               FROM SCP_MST_ITEM_GROUP XA
                              WHERE XA.DIVISION_ID = C.DIVISION_ID
                                AND XA.GROUP_ID    = C.GROUP_ID
                                AND XA.VALID_YN    = 'Y' ) )
           AND A.DIVISION_ID     = V_DIVISION_ID
           AND A.VERSION_NO      = V_DM_VERSION_NO
           AND A.CUTOFF_YYYYMMDD = V_DM_CUTOFF_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 1                                                      */
        /* 1) INTRANST INV에 모델 및 TO SITE 정보를 기반으로 DP에 해당 SALES SITE정보 없는 경우       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_1';
        INSERT INTO GT_0039_INT_TGT_CASE_1
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.RN_1         = 1
         WHERE B.SCM_SITE_ID IS NULL
         UNION ALL
        SELECT NULL                    AS GROUP_ID
             , NULL                    AS GROUP_NAME
             , A.NICK_NAME
             , A.CUTOFF_DATE           AS RESULT_DATE
             , A.STOCK_TYPE            AS RESULT_TYPE
             , A.DIVISION_ID
             , NULL                    AS COMPANY_ID
             , NULL                    AS PLANT_ID
             , NULL                    AS SHIPMENT_NO
             , NULL                    AS PROJECT_CODE
             , A.ITEM_ID
             , NULL                    AS PLANT_ISSUE_DATE
             , NULL                    AS INCOTERMS_ORG
             , NULL                    AS INCOTERMS
             , NULL                    AS SHIPTO_CODE
             , NULL                    AS FROM_SCM_SITE_ID
             , A.SCM_SITE_ID           AS TO_SCM_SITE_ID
             , A.SALES_SITE_DESCRIPTION
             , A.SCM_QTY               AS DELIVERY_QTY
             , A.QTY_UOM               AS UOM
             , NULL                    AS TRANSPORT_MODE
             , NULL                    AS F_DEST_ETA_DATE
             , NULL                    AS F_DEST_ATA_DATE
          FROM GT_0039_SALES_SITE_INVENTORY A
             , GT_0039_DEMAND_PLAN          B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.SCM_SITE_ID(+) = A.SCM_SITE_ID
           AND B.RN_3(+)        = 1
           AND B.SCM_SITE_ID IS NULL;

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 2                                                      */
        /* 2) INTRANST INV에 모델, TO SITE, INCOTERMS 기준 DP에 해당 SALES SITE의 INCOTERMS 가 없는 것*/
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_2';
        INSERT INTO GT_0039_INT_TGT_CASE_2
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          /* AS-IS 의 LEFT JOIN ON 절에 자기 테이블 컬럼(DP.PROJECT_CODE)을 되받는 CASE 가 있어
             Oracle (+) 로는 표현할 수 없다(ORA-01416). 이 한 곳만 ANSI OUTER JOIN 으로 둔다. */
          FROM GT_0039_INTRANSIT_INVENTORY A
          LEFT OUTER JOIN GT_0039_DEMAND_PLAN B
            ON B.DIVISION_ID  = A.DIVISION_ID
           AND B.ITEM_ID      = A.ITEM_ID
           AND B.SCM_SITE_ID  = A.TO_SCM_SITE_ID
           AND B.PROJECT_CODE = CASE WHEN A.PROJECT_CODE LIKE '000%'
                                       OR A.PROJECT_CODE = '/'
                                       OR A.PROJECT_CODE = 'TBD'
                                       OR TRIM(A.PROJECT_CODE) IS NULL
                                     THEN B.PROJECT_CODE
                                     ELSE A.PROJECT_CODE
                                END
           AND B.INCOTERMS    = A.INCOTERMS
           AND B.RN_2         = 1
         WHERE B.SCM_SITE_ID IS NULL
           AND NOT EXISTS ( SELECT 1
                              FROM GT_0039_INT_TGT_CASE_1 XA
                             WHERE XA.DIVISION_ID    = A.DIVISION_ID
                               AND XA.ITEM_ID        = A.ITEM_ID
                               AND XA.TO_SCM_SITE_ID = A.TO_SCM_SITE_ID
                               AND XA.PROJECT_CODE   = A.PROJECT_CODE );

        /* ---------------------------------------------------------------------------------------- */
        /* Intransit Inventory 확인 대상 Case 3                                                      */
        /* 3) INTRANST INV 도착예상 일자정보 기준 금주 월요일이 1주일이상 지연 경우                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_CASE_3';
        INSERT INTO GT_0039_INT_TGT_CASE_3
        (
            GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INTRANSIT_INVENTORY
         WHERE F_DEST_ETA_DATE IS NOT NULL   /* 도착예정일 */
           AND TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - TO_DATE(F_DEST_ETA_DATE, 'YYYYMMDD') > 7
           AND F_DEST_ATA_DATE IS NULL;      /* 실제도착일(미착) */

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터                                                                     */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TARGET_DATA';
        INSERT INTO GT_0039_INT_TARGET_DATA
        (
            MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT 'INT01'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_1
         UNION ALL
        SELECT 'INT02'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_2
         UNION ALL
        SELECT 'INT03'  AS MASTER_INVLD_CD
             , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
             , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
             , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
             , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_CASE_3;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Basic Cell Nickname 매핑                                          */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_BC_NICK';
        INSERT INTO GT_0039_INT_TGT_BC_NICK
        (
            BASIC_CELL_NICK_NAME
          , MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT C.BASIC_NICK_NAME  AS BASIC_CELL_NICK_NAME
             , A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TARGET_DATA A
             , SCP_MST_FINAL_ITEM      B
             , SCP_MST_ITEM_BSI_IFO    C
         WHERE B.DIVISION_ID = A.DIVISION_ID
           AND B.ITEM_ID     = A.ITEM_ID
           AND C.ITEM_ID(+)  = CASE WHEN B.OPERATION_GROUP = 'P' THEN B.ATTRIBUTE1
                                    ELSE A.ITEM_ID
                               END;

        /* ---------------------------------------------------------------------------------------- */
        /* 확인 대상 전체 데이터 - Plan Group 매핑                                                   */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'INT_TGT_PLAN_GROUP';
        INSERT INTO GT_0039_INT_TGT_PLAN_GROUP
        (
            OPMZ_PLAN_GR_ID, OPMZ_PLAN_GR_NAME, LINE_ID, BASIC_NICK_NAME, DV
          , BASIC_CELL_NICK_NAME, MASTER_INVLD_CD
          , GROUP_ID, GROUP_NAME, NICK_NAME, RESULT_DATE, RESULT_TYPE, DIVISION_ID, COMPANY_ID
          , PLANT_ID, SHIPMENT_NO, PROJECT_CODE, ITEM_ID, PLANT_ISSUE_DATE, INCOTERMS_ORG, INCOTERMS
          , SHIPTO_CODE, FROM_SCM_SITE_ID, TO_SCM_SITE_ID, SALES_SITE_DESCRIPTION, DELIVERY_QTY
          , UOM, TRANSPORT_MODE, F_DEST_ETA_DATE, F_DEST_ATA_DATE
        )
        SELECT NVL(B.OPMZ_PLAN_GR_ID  , C.OPMZ_PLAN_GR_ID  )  AS OPMZ_PLAN_GR_ID
             , NVL(B.OPMZ_PLAN_GR_NAME, C.OPMZ_PLAN_GR_NAME)  AS OPMZ_PLAN_GR_NAME
             , NVL(B.LINE_ID          , C.LINE_ID          )  AS LINE_ID
             , NVL(B.BASIC_NICK_NAME  , C.BASIC_NICK_NAME  )  AS BASIC_NICK_NAME
             , CASE WHEN B.LINE_ID IS NOT NULL THEN 'A'   /* item id mapping */
                    WHEN C.LINE_ID IS NOT NULL THEN 'B'   /* basic cell nick name mapping */
                    ELSE 'Z'
               END                                            AS DV
             , A.BASIC_CELL_NICK_NAME, A.MASTER_INVLD_CD
             , A.GROUP_ID, A.GROUP_NAME, A.NICK_NAME, A.RESULT_DATE, A.RESULT_TYPE, A.DIVISION_ID, A.COMPANY_ID
             , A.PLANT_ID, A.SHIPMENT_NO, A.PROJECT_CODE, A.ITEM_ID, A.PLANT_ISSUE_DATE, A.INCOTERMS_ORG, A.INCOTERMS
             , A.SHIPTO_CODE, A.FROM_SCM_SITE_ID, A.TO_SCM_SITE_ID, A.SALES_SITE_DESCRIPTION, A.DELIVERY_QTY
             , A.UOM, A.TRANSPORT_MODE, A.F_DEST_ETA_DATE, A.F_DEST_ATA_DATE
          FROM GT_0039_INT_TGT_BC_NICK  A
             , GT_0039_PLAN_GROUP_INFO  B   /* item_id 로 매핑 */
             , GT_0039_PLAN_GROUP_INFO  C   /* basic cell nick name 으로 매핑 */
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.ITEM_ID(+)     = A.ITEM_ID
           AND B.RN(+)          = 1
           AND C.DIVISION_ID(+)     = A.DIVISION_ID
           AND C.BASIC_NICK_NAME(+) = A.BASIC_CELL_NICK_NAME
           AND C.RN_NICK(+)         = 1;

        /* ---------------------------------------------------------------------------------------- */
        /* BOD                                                                                       */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'BOD';
        INSERT INTO GT_0039_BOD_II
        (
            BOD_ID
          , ROUTE_ID
          , DIVISION_ID
          , FROM_SITE
          , TO_SITE
          , INCOTERMS
          , TRANSPORT_MODE
          , FROM_YYYYMMDD
          , TO_YYYYMMDD
          , BOD_VALID_YN
          , ROUTE_VALID_YN
          , RN
        )
        SELECT A.BOD_ID
             , B.ROUTE_ID
             , A.DIVISION_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.INCOTERMS
             , B.TRANSPORT_MODE
             , A.ATTRIBUTE2  AS FROM_YYYYMMDD
             , A.ATTRIBUTE3  AS TO_YYYYMMDD
             , A.VALID_YN    AS BOD_VALID_YN
             , B.VALID_YN    AS ROUTE_VALID_YN
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID
                                             , A.FROM_SITE
                                             , A.TO_SITE
                                             , A.INCOTERMS
                                             , B.TRANSPORT_MODE
                                      ORDER BY A.VALID_YN DESC
                                             , B.VALID_YN DESC
                                             , A.PRIORITY
                                             , B.PRIORITY
                                             , A.BOD_ID DESC)  AS RN
          FROM SCP_MST_BOD                A
             , SCP_MST_DISTRIBUTION_ROUTE B
         WHERE B.ROUTE_ID = A.ROUTE_ID
           AND A.ATTRIBUTE3 >= V_FROM_YYYYMMDD;

        /* ---------------------------------------------------------------------------------------- */
        /* 전체 확인 필요 대상 조회                                                                  */
        /* ---------------------------------------------------------------------------------------- */
        V_STEP := 'O_RC1';
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ITEM_ID
                 , A.NICK_NAME
                 , A.BASIC_CELL_NICK_NAME
                 , CASE WHEN A.DV IN ('A', 'B')                THEN A.OPMZ_PLAN_GR_NAME
                        WHEN A.BASIC_CELL_NICK_NAME IS NULL    THEN '-'
                        ELSE A.BASIC_CELL_NICK_NAME || ' (예상)'
                   END                                      AS PLAN_GROUP
                 , NVL(A.OPMZ_PLAN_GR_ID, '-')              AS OPMZ_PLAN_GR_ID
                 , A.DV
                 , A.MASTER_INVLD_CD
                 , B.ATTRIBUTE2                             AS MASTER_INVLD_MSG
                 , A.FROM_SCM_SITE_ID                       AS PLANT_SITE
                 , A.TO_SCM_SITE_ID                         AS SALES_SITE
                 , A.INCOTERMS
                 , A.SHIPMENT_NO
                 , A.RESULT_TYPE
                 , A.DELIVERY_QTY
                 , TO_DATE(A.PLANT_ISSUE_DATE, 'YYYYMMDD')  AS EXFACTORY_DATE     /* 출하일자 */
                 , TO_DATE(A.F_DEST_ETA_DATE , 'YYYYMMDD')  AS F_DEST_ETA_DATE    /* 도착예정일 */
                 , A.F_DEST_ATA_DATE                                              /* 실제도착일 */
                 , A.TRANSPORT_MODE
                 , C.BOD_ID
                 , V_FROM_YYYYMMDD                          AS PLAN_START_YYYYMMDD
                 , V_DM_CUTOFF_YYYYMMDD                     AS DM_CUTOFF_YYYYMMDD
                 , V_DM_VERSION_NO                          AS DM_VERSION_NO
              FROM GT_0039_INT_TGT_PLAN_GROUP A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , GT_0039_BOD_II              C
                 , ( SELECT DISTINCT '%' || TRIM(REGEXP_SUBSTR(P_ITEM_ID, '[^,]+', 1, LEVEL)) || '%' AS TST
                       FROM DUAL
                     CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_ITEM_ID, ',') + 1, 0)
                      UNION ALL
                     SELECT '%' AS TST
                       FROM DUAL
                      WHERE P_ITEM_ID IS NULL ) IA
             WHERE B.LOOKUP_TYPE(+) = 'MASTER_INVLD_CD'
               AND B.SEGMENT1(+)    = A.MASTER_INVLD_CD
               AND B.VALID_YN(+)    = 'Y'
               AND C.DIVISION_ID(+)    = A.DIVISION_ID
               AND C.FROM_SITE(+)      = A.FROM_SCM_SITE_ID
               AND C.TO_SITE(+)        = A.TO_SCM_SITE_ID
               AND C.INCOTERMS(+)      = A.INCOTERMS
               AND C.TRANSPORT_MODE(+) = A.TRANSPORT_MODE
               AND ( A.ITEM_ID   LIKE IA.TST
                  OR A.NICK_NAME LIKE IA.TST )
               AND ( P_PLAN_GROUP_ID IS NULL
                     OR A.OPMZ_PLAN_GR_ID IN ( SELECT TRIM(REGEXP_SUBSTR(P_PLAN_GROUP_ID, '[^,]+', 1, LEVEL))
                                                 FROM DUAL
                                               CONNECT BY LEVEL <= NVL(REGEXP_COUNT(P_PLAN_GROUP_ID, ',') + 1, 0) ) )
             ORDER BY A.MASTER_INVLD_CD
                    , A.DIVISION_ID
                    , A.ITEM_ID
                    , A.NICK_NAME
                    , A.BASIC_CELL_NICK_NAME
                    , PLAN_GROUP
                    , OPMZ_PLAN_GR_ID;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] STEP=' || V_STEP
                                          || ' INPUT=' || V_PROC_INPUT || ' / ' || SQLERRM);
    END P_SCP0039_GET_VALIDATION_INTRANSIT_INV;

END PKG_SCP0039_VF;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0039_VF
-- ##### END PACKAGE BODY PKG_SCP0039_VF

-- ##### START PACKAGE BODY PKG_SCP0048
CREATE OR REPLACE PACKAGE BODY PKG_SCP0048
AS
/****************************************************************************************************/
/* Program ID  : PKG_SCP0048                                                                        */
/* Description : ProjectRoute Warranty                                                             */
/* Program History                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2026.09.24  ZIONEX       [PJ202650304] MSSQL -> Oracle 전환                                      */
/* 2026.10.07  AJS          P_SCP0048_GET_PROJECTROUTE_WARRANTY 조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시 */
/****************************************************************************************************/

    TYPE T_TOK IS TABLE OF VARCHAR2(4000 CHAR) INDEX BY PLS_INTEGER;

    /* ------------------------------------------------------------
       ^ 구분 CLOB 분리 (AS-IS SCM_ARR_SPL_VAL · SCM_ARR_SPL_CNT 대응)
       - 토큰 앞뒤 공백 제거, 순번 1 부터
       - O_CNT : AS-IS SCM_ARR_SPL_CNT (구분자 수 + 1, 입력이 비면 0)
       ------------------------------------------------------------ */
    PROCEDURE P_SPLIT_TOKEN
    (
        P_STR       IN  CLOB
      , P_DELIM     IN  VARCHAR2
      , O_TAB       OUT T_TOK
      , O_CNT       OUT PLS_INTEGER
    )
    IS
        V_POS       PLS_INTEGER;
        V_FROM      PLS_INTEGER := 1;
        V_NR        PLS_INTEGER := 0;
        V_LEN       PLS_INTEGER := NVL(DBMS_LOB.GETLENGTH(P_STR), 0);
    BEGIN

        IF V_LEN = 0
        THEN
            O_CNT := 0;
            RETURN;
        END IF;

        LOOP
            V_POS := DBMS_LOB.INSTR(P_STR, P_DELIM, V_FROM, 1);

            EXIT WHEN V_POS = 0 OR V_POS IS NULL;

            V_NR := V_NR + 1;
            O_TAB(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_STR, V_POS - V_FROM, V_FROM));
            V_FROM := V_POS + 1;
        END LOOP;

        V_NR := V_NR + 1;

        IF V_FROM <= V_LEN
        THEN
            O_TAB(V_NR) := TRIM(DBMS_LOB.SUBSTR(P_STR, V_LEN - V_FROM + 1, V_FROM));
        END IF;

        O_CNT := V_NR;

    END P_SPLIT_TOKEN;

    /* 토큰 꺼내기 - 없는 순번이면 빈 값 (AS-IS SCM_ARR_SPL_VAL 과 같음) */
    FUNCTION F_TOKEN
    (
        P_TAB       IN  T_TOK
      , P_IDX       IN  PLS_INTEGER
    )
    RETURN VARCHAR2
    IS
    BEGIN
        IF P_TAB.EXISTS(P_IDX)
        THEN
            RETURN P_TAB(P_IDX);
        END IF;

        RETURN NULL;
    END F_TOKEN;

    /* ------------------------------------------------------------
       AS-IS 등록일시 문자열 -> DATETIME 암묵 변환 대응
       - 빈 값은 MSSQL 이 1900-01-01 로 바꾼다
       - 바꿀 수 없는 값은 AS-IS 처럼 오류
       ------------------------------------------------------------ */
    FUNCTION F_TO_DATETIME
    (
        P_STR       IN  VARCHAR2
    )
    RETURN DATE
    IS
        V_DATE      DATE;
    BEGIN
        IF RTRIM(P_STR) IS NULL
        THEN
            RETURN DATE '1900-01-01';
        END IF;

        V_DATE := CAST(TO_TIMESTAMP(TRIM(P_STR) DEFAULT NULL ON CONVERSION ERROR, 'YYYY-MM-DD HH24:MI:SS.FF') AS DATE);

        IF V_DATE IS NULL
        THEN
            V_DATE := TO_DATE(TRIM(P_STR) DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDDHH24MISS');
        END IF;

        IF V_DATE IS NULL
        THEN
            RAISE_APPLICATION_ERROR(-20001, 'Conversion failed when converting date and/or time from character string. [' || P_STR || ']');
        END IF;

        RETURN V_DATE;
    END F_TO_DATETIME;



/****************************************************************************************************/
/* Program ID  : P_SCP0048_GET_PROJECTROUTE_WARRANTY                                                */
/* Description : Project Route Plant Site(Warranty) 조회                                            */
/****************************************************************************************************/
PROCEDURE P_SCP0048_GET_PROJECTROUTE_WARRANTY
(
    P_DIVISION_ID       IN  VARCHAR2
  , P_PLANT_SITE        IN  VARCHAR2
  , P_OPERATION_GROUP   IN  VARCHAR2
  , P_ITEM_ID           IN  VARCHAR2
  , P_FROM_YYYYMM       IN  VARCHAR2
  , P_TO_YYYYMM         IN  VARCHAR2
  , P_VALID_FLAG        IN  VARCHAR2
  , O_MAIN_LIST         OUT SYS_REFCURSOR
  , O_ALL_LIST          OUT SYS_REFCURSOR
  , O_ITEM_LIST         OUT SYS_REFCURSOR
  , O_RESULT_CODE       OUT VARCHAR2
  , O_RESULT_MSG        OUT VARCHAR2
)
IS
    V_DIVISION_ID       VARCHAR2(4000 CHAR) := P_DIVISION_ID;
    V_PLANT_SITE        VARCHAR2(4000 CHAR) := P_PLANT_SITE;
    V_OPERATION_GROUP   VARCHAR2(4000 CHAR) := P_OPERATION_GROUP;
    V_ITEM_ID           VARCHAR2(200 CHAR)  := P_ITEM_ID;
    V_VALID_FLAG        VARCHAR2(200 CHAR)  := P_VALID_FLAG;
    V_ITEM_TAB          T_STR_TAB           := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */

BEGIN

    /* 조회조건 ALL 은 조건 없음으로 다룬다 */
    IF UPPER(TRIM(V_DIVISION_ID))     = 'ALL' THEN V_DIVISION_ID     := NULL; END IF;
    IF UPPER(TRIM(V_PLANT_SITE))      = 'ALL' THEN V_PLANT_SITE      := NULL; END IF;
    IF UPPER(TRIM(V_OPERATION_GROUP)) = 'ALL' THEN V_OPERATION_GROUP := NULL; END IF;
    IF UPPER(TRIM(V_ITEM_ID))         = 'ALL' THEN V_ITEM_ID         := NULL; END IF;
    IF UPPER(TRIM(V_VALID_FLAG))      = 'ALL' THEN V_VALID_FLAG      := NULL; END IF;

    /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력 토큰(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
       대상 품목 = 결과가 나오는 사이트별 품목 우선순위 원장 품목 · 닉네임은 같은 사업부 품목 원장 */
    IF TRIM(V_ITEM_ID) IS NOT NULL THEN
      SELECT IA.ITEM_ID
        BULK COLLECT INTO V_ITEM_TAB
        FROM SCM_MST_SITE_ITEM_PRIORITY IA
           , TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA
       WHERE SA.COLUMN_VALUE IS NOT NULL
         AND UPPER(IA.ITEM_ID) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'
      UNION
      SELECT XA.ITEM_ID
        FROM SCM_MST_SITE_ITEM_PRIORITY XA
           , SCM_MST_ITEM_SN XB
           , TABLE(STRING_SPLIT(V_ITEM_ID, ',')) XC
       WHERE XB.ITEM_ID     = XA.ITEM_ID
         AND XB.DIVISION_ID = XA.DIVISION_ID
         AND XC.COLUMN_VALUE IS NOT NULL
         AND UPPER(XB.NICK_NAME) LIKE '%' || UPPER(XC.COLUMN_VALUE) || '%';
    END IF;
    /* 2026.10.07 AJS Model/Nickname 검색 (END) */

    /* 1. 주 목록 */
    OPEN O_MAIN_LIST FOR
        SELECT IA.PRIORITY_SEQ
             , IA.DIVISION_ID
             , IA.PROJECT_CODE
             , IA.ITEM_ID
             , IA.SCM_SITE_ID
             , IA.PLANT_SITE_ID                                             AS PLANT_SITE_ID_B
             /* ESS 외주 Pakcer Line 생산 Target 적용 */
             , IA.DIVISION_ID || '   ' || IA.PLANT_SITE_ID || '   ' || IA.SITE_DESCRIPTION
               || CASE WHEN (IA.TACT_CNT > 0 AND IA.OSP_YN = 'N')
                         OR (IA.OUT_CAPA_CNT > 0 AND IA.ATTRIBUTE1 IN ('-', 'N'))
                         OR (IA.OUT_TACT_CNT > 0 AND IA.ATTRIBUTE1 = 'Y')
                       THEN ' Y'
                       ELSE ' N'
                  END                                                       AS PLANT_SITE_ID
             , CASE WHEN (IA.TACT_CNT > 0 AND IA.OSP_YN = 'N')
                      OR (IA.OUT_CAPA_CNT > 0 AND IA.ATTRIBUTE1 IN ('-', 'N'))
                      OR (IA.OUT_TACT_CNT > 0 AND IA.ATTRIBUTE1 = 'Y')
                    THEN ' Y'
                    ELSE ' N'
               END                                                          AS TACT_TIME_FLAG
             , IA.PRIORITY
             , IA.VALID_YN
             , IA.ORG_VALID_YN
             , IA.FROM_YYYYMMDD
             , IA.TO_YYYYMMDD
             , IA.CREATED_BY
             , IA.CREATION_DATE
             , IA.LAST_UPDATED_BY
             , IA.LAST_UPDATE_DATE
             , IA.OPERATION_GROUP
             , IA.ORG_FROM_YYYYMMDD
             , IA.ORG_TO_YYYYMMDD
             , IA.MERGE_DATE
             , IA.IS_PASS_N1
             , IA.IS_PASS_N2
             , IA.IS_PASS_N3
             , IA.IS_PASS_N4
             , IA.IS_PASS_N5
             , IA.IS_PASS_N6
             , IA.IS_PASS_N7
             , IA.NICK_NAME
             , IA.ACTION_FLAG_DIV
             , IA.ROW_COLOR_INDEX
             , IA.SORT_ORDER
          FROM (SELECT TO_CHAR(A.PRIORITY_SEQ)                              AS PRIORITY_SEQ
                     , A.DIVISION_ID
                     , NVL(NULLIF(A.PROJECT_CODE, '-'), '/')                AS PROJECT_CODE
                     , A.ITEM_ID
                     , NVL(NULLIF(A.SALES_SITE_ID, '-'), '/')               AS SCM_SITE_ID
                     , A.PLANT_SITE_ID
                     , A.PRIORITY
                     , A.VALID_YN
                     , A.VALID_YN                                           AS ORG_VALID_YN
                     /* ★원장에 달력에 없는 날짜가 섞여 있다. AS-IS 는 FN_CHAR_TO_DATE 를 쓰지만 그 함수는 오류를 내므로  */
                     /*   같은 형식으로 직접 바꾸되, 바꿀 수 없으면 원래 값을 그대로 보여준다                        */
                     , NVL(TO_CHAR(TO_DATE(A.FROM_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.FROM_YYYYMMDD) AS FROM_YYYYMMDD
                     , NVL(TO_CHAR(TO_DATE(A.TO_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.TO_YYYYMMDD)     AS TO_YYYYMMDD
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , A.LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                     , B.OPERATION_GROUP
                     , A.FROM_YYYYMMDD                                      AS ORG_FROM_YYYYMMDD
                     , A.TO_YYYYMMDD                                        AS ORG_TO_YYYYMMDD
                     , A.FROM_YYYYMMDD || A.TO_YYYYMMDD                     AS MERGE_DATE
                     , ''                                                   AS IS_PASS_N1
                     , ''                                                   AS IS_PASS_N2
                     , ''                                                   AS IS_PASS_N3
                     , ''                                                   AS IS_PASS_N4
                     , ''                                                   AS IS_PASS_N5
                     , ''                                                   AS IS_PASS_N6
                     , ''                                                   AS IS_PASS_N7
                     , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)       AS NICK_NAME
                     , '-'                                                  AS ACTION_FLAG_DIV
                     , 0                                                    AS ROW_COLOR_INDEX
                     , 1                                                    AS SORT_ORDER
                     , NVL((SELECT COUNT(X.PLANT_SITE_ID)
                              FROM SCP_MST_TACT_TIME X
                                 , SCM_MST_LINE_SN Y
                             WHERE Y.COMPANY_ID    = B.COMPANY_ID
                               AND Y.DIVISION_ID   = X.DIVISION_ID
                               AND Y.SITE_ID       = B.SITE_ID
                               AND Y.PLANT_ID      = B.PLANT_ID
                               AND Y.OPERATION_ID  = X.OPERATION_ID
                               AND Y.LINE_ID       = X.LINE_ID
                               AND Y.ACTIVE_FLAG   = 'Y'
                               AND X.ITEM_ID       = A.ITEM_ID
                               AND X.VALID_YN      = 'Y'
                               AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                             GROUP BY X.ITEM_ID
                                    , X.PLANT_SITE_ID), 0)                  AS TACT_CNT
                     , NVL((SELECT COUNT(X.PLANT_SITE_ID)
                              FROM SCP_MST_OUTSOURCING_CAPA X
                             WHERE X.ITEM_ID       = A.ITEM_ID
                               AND X.VALID_YN      = 'Y'
                               AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                             GROUP BY X.PLANT_SITE_ID
                                    , X.ITEM_ID), 0)                        AS OUT_CAPA_CNT
                     , B.SITE_DESCRIPTION
                     /* ESS 외주 Pakcer Line 생산 Target 적용 */
                     , NVL((SELECT COUNT(X.PLANT_SITE_ID)
                              FROM SCP_MST_TACT_TIME_OSP X
                                 , SCM_MST_LINE_OSP Y
                             WHERE Y.DIVISION_ID   = X.DIVISION_ID
                               AND Y.SCM_SITE_ID   = X.PLANT_SITE_ID
                               AND Y.LINE_ID       = X.LINE_ID
                               AND Y.VALID_YN      = 'Y'
                               AND X.ITEM_ID       = A.ITEM_ID
                               AND X.VALID_YN      = 'Y'
                               AND X.PLANT_SITE_ID = B.SCM_SITE_ID
                               AND (TRIM(V_DIVISION_ID) IS NULL OR X.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                             GROUP BY X.PLANT_SITE_ID
                                    , X.ITEM_ID), 0)                        AS OUT_TACT_CNT
                     , NVL(B.OSP_YN, 'N')                                   AS OSP_YN
                     , NVL(B.ATTRIBUTE1, 'N')                               AS ATTRIBUTE1
                  FROM SCM_MST_SITE_ITEM_PRIORITY A
                     , SCM_MST_SITE B
                 WHERE ((A.DIVISION_ID = B.DIVISION_ID AND B.OPERATION_GROUP <> 'W') OR B.OPERATION_GROUP = 'W')
                   AND A.PLANT_SITE_ID = B.SCM_SITE_ID
                   AND B.SITE_TYPE     = 'PLANT'
                   AND (TRIM(V_DIVISION_ID) IS NULL OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
                   AND (TRIM(V_PLANT_SITE) IS NULL OR A.PLANT_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_PLANT_SITE, ','))))
--                 AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID LIKE '%' || V_ITEM_ID || '%')   --  2026.10.07 AJS
                   AND (TRIM(V_ITEM_ID) IS NULL OR A.ITEM_ID IN (SELECT XT.COLUMN_VALUE FROM TABLE(V_ITEM_TAB) XT))   --  2026.10.07 AJS
                   AND (TRIM(V_VALID_FLAG) IS NULL OR A.VALID_YN = V_VALID_FLAG)
               ) IA
         WHERE EXISTS (SELECT 1
                         FROM SCM_MST_SITE_ITEM_PRIORITY XA
                            , SCM_MST_SITE SA
                        WHERE XA.DIVISION_ID   = SA.DIVISION_ID
                          AND XA.PLANT_SITE_ID = SA.SCM_SITE_ID
                          AND SA.OPERATION_GROUP = 'W'
                          AND XA.ITEM_ID       = IA.ITEM_ID
                          AND (TRIM(V_DIVISION_ID) IS NULL OR XA.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ',')))))
         ORDER BY NLSSORT(IA.DIVISION_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , NLSSORT(IA.ITEM_ID, 'NLS_SORT=BINARY_CI') DESC NULLS LAST;

    /* 2. 전체조회 */
    OPEN O_ALL_LIST FOR
        SELECT TO_CHAR(A.PRIORITY_SEQ)                                      AS PRIORITY_SEQ
             , A.DIVISION_ID
             , NVL(A.PROJECT_CODE, '/')                                     AS PROJECT_CODE
             , A.ITEM_ID
             , NVL(A.SALES_SITE_ID, '/')                                    AS SCM_SITE_ID
             , A.PLANT_SITE_ID
             , A.PRIORITY
             , A.VALID_YN
             , A.VALID_YN                                                   AS ORG_VALID_YN
             /* ★원장에 달력에 없는 날짜가 섞여 있다. AS-IS 는 FN_CHAR_TO_DATE 를 쓰지만 그 함수는 오류를 내므로  */
                     /*   같은 형식으로 직접 바꾸되, 바꿀 수 없으면 원래 값을 그대로 보여준다                        */
             , NVL(TO_CHAR(TO_DATE(A.FROM_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.FROM_YYYYMMDD) AS FROM_YYYYMMDD
             , NVL(TO_CHAR(TO_DATE(A.TO_YYYYMMDD DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.TO_YYYYMMDD)     AS TO_YYYYMMDD
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
             , B.OPERATION_GROUP
             , A.FROM_YYYYMMDD                                              AS ORG_FROM_YYYYMMDD
             , A.TO_YYYYMMDD                                                AS ORG_TO_YYYYMMDD
             , A.FROM_YYYYMMDD || A.TO_YYYYMMDD                             AS MERGE_DATE
             , ''                                                           AS IS_PASS_N1
             , ''                                                           AS IS_PASS_N2
             , ''                                                           AS IS_PASS_N3
             , ''                                                           AS IS_PASS_N4
             , ''                                                           AS IS_PASS_N5
             , ''                                                           AS IS_PASS_N6
             , ''                                                           AS IS_PASS_N7
             , '-'                                                          AS ACTION_FLAG_DIV
             , 0                                                            AS ROW_COLOR_INDEX
          FROM SCM_MST_SITE_ITEM_PRIORITY A
             , SCM_MST_SITE B
         WHERE ((A.DIVISION_ID = B.DIVISION_ID AND B.OPERATION_GROUP <> 'W') OR B.OPERATION_GROUP = 'W')
           AND A.PLANT_SITE_ID = B.SCM_SITE_ID
           AND B.SITE_TYPE     = 'PLANT'
           AND A.VALID_YN      = 'Y'
           AND (TRIM(V_DIVISION_ID) IS NULL OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(V_DIVISION_ID, ','))))
         ORDER BY NLSSORT(A.DIVISION_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , NLSSORT(A.ITEM_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST
                , A.FROM_YYYYMMDD NULLS FIRST
                , A.PRIORITY NULLS FIRST
                , A.VALID_YN DESC NULLS LAST
                , A.TO_YYYYMMDD NULLS FIRST;

    /* 3. 아이템 조회용 */
    OPEN O_ITEM_LIST FOR
        SELECT A.ITEM_ID
             , D.NICK_NAME
          FROM SCM_MST_SITE_ITEM A
             , SCM_MST_DIVISION B
             , SCM_MST_SITE C
             , SCM_MST_ITEM_SN D
             , SCM_MST_PROJECT E
         WHERE A.DIVISION_ID  = B.DIVISION_ID
           AND A.DIVISION_ID  = C.DIVISION_ID
           AND A.SCM_SITE_ID  = C.SCM_SITE_ID
           AND A.DIVISION_ID  = D.DIVISION_ID
           AND A.ITEM_ID      = D.ITEM_ID
           AND A.DIVISION_ID  = E.DIVISION_ID(+)
           AND A.PROJECT_CODE = E.PROJECT_CODE(+)
         GROUP BY A.ITEM_ID
                , D.ITEM_NAME
                , D.ITEM_TYPE
                , D.NICK_NAME
                , D.ITEM_CLASS_NAME
         /* AS-IS 에는 정렬이 없어 화면에서 순서가 흔들린다 — 품목 순으로 고정한다 */
         ORDER BY NLSSORT(A.ITEM_ID, 'NLS_SORT=BINARY_CI') NULLS FIRST;

    O_RESULT_CODE := '0';
    O_RESULT_MSG  := 'SUCCESS';

END P_SCP0048_GET_PROJECTROUTE_WARRANTY;

/****************************************************************************************************/
/* Program ID  : P_SCP0048_SAVE_PROJECTROUTE_WARRANTY                                              */
/* Description : Project Route Plant Site 등록,수정                                                 */
/****************************************************************************************************/
PROCEDURE P_SCP0048_SAVE_PROJECTROUTE_WARRANTY
(
    P_ACTIVE_FLAG       IN  CLOB
  , P_PRIORITY_SEQ      IN  CLOB
  , P_DIVISION_ID       IN  CLOB
  , P_PROJECT_CODE      IN  CLOB
  , P_SCM_SITE_ID       IN  CLOB
  , P_PLANT_SITE_ID     IN  CLOB
  , P_ITEM_ID           IN  CLOB
  , P_CREATED_BY        IN  CLOB
  , P_CREATION_DATE     IN  CLOB
  , P_LAST_UPDATED_BY   IN  CLOB
  , P_PRIORITY          IN  CLOB
  , P_FROM_YYYYMMDD     IN  CLOB
  , P_TO_YYYYMMDD       IN  CLOB
  , P_VALID_YN          IN  CLOB
  , P_DEBUG_MODE        IN  VARCHAR2 DEFAULT 'F'
  , O_RESULT_CODE       OUT VARCHAR2
  , O_RESULT_CNT        OUT NUMBER
  , O_RESULT_MSG        OUT VARCHAR2
)
IS
    C_DELIM                 CONSTANT VARCHAR2(1 CHAR) := '^';
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SCP0048_SAVE_PROJECTROUTE_WARRANTY';

    T_ACTIVE_FLAG           T_TOK;
    T_PRIORITY_SEQ          T_TOK;
    T_DIVISION_ID           T_TOK;
    T_PROJECT_CODE          T_TOK;
    T_SCM_SITE_ID           T_TOK;
    T_PLANT_SITE_ID         T_TOK;
    T_ITEM_ID               T_TOK;
    T_CREATED_BY            T_TOK;
    T_CREATION_DATE         T_TOK;
    T_LAST_UPDATED_BY       T_TOK;
    T_PRIORITY              T_TOK;
    T_FROM_YYYYMMDD         T_TOK;
    T_TO_YYYYMMDD           T_TOK;
    T_VALID_YN              T_TOK;

    V_LOOP_CNT              PLS_INTEGER := 0;
    V_DUMMY_CNT             PLS_INTEGER := 0;

    V_ACTIVE_FLAG           VARCHAR2(4000 CHAR);
    V_PRIORITY_SEQ          VARCHAR2(4000 CHAR);
    V_DIVISION_ID           VARCHAR2(4000 CHAR);
    V_PROJECT_CODE          VARCHAR2(4000 CHAR);
    V_SCM_SITE_ID           VARCHAR2(4000 CHAR);
    V_PLANT_SITE_ID         VARCHAR2(4000 CHAR);
    V_ITEM_ID               VARCHAR2(4000 CHAR);
    V_S_VALID_YN            VARCHAR2(4000 CHAR);
    V_CREATED_BY            VARCHAR2(4000 CHAR);
    V_CREATION_DATE         DATE;
    V_LAST_UPDATED_BY       VARCHAR2(4000 CHAR);
    V_PRIORITY              VARCHAR2(4000 CHAR);
    V_FROM_YYYYMMDD         VARCHAR2(4000 CHAR);
    V_TO_YYYYMMDD           VARCHAR2(4000 CHAR);
    V_VALID_YN              VARCHAR2(4000 CHAR);

    V_CURRENCY              VARCHAR2(4000 CHAR) := NULL;
    V_LIABILITY_PERIOD      VARCHAR2(4000 CHAR) := NULL;
    V_SALES_PLAN_ADJUST_YN  VARCHAR2(4000 CHAR) := NULL;
    V_ITEM_HRCY_ID          VARCHAR2(4000 CHAR) := NULL;
    V_BPMS_EXIST            VARCHAR2(1 CHAR)    := 'Y';


    V_CNT                   PLS_INTEGER;
    V_SQLERRM               VARCHAR2(4000 CHAR);
    V_SQLCODE               NUMBER;

BEGIN

    /* 시작 LOG */
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', NULL, SYSDATE);

    /* 각 컬럼들에 대한 스플릿처리 */
    P_SPLIT_TOKEN(P_ACTIVE_FLAG     , C_DELIM, T_ACTIVE_FLAG     , V_LOOP_CNT);     /* 프로시저 LOOP 길이를 판단 */
    P_SPLIT_TOKEN(P_PRIORITY_SEQ    , C_DELIM, T_PRIORITY_SEQ    , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_DIVISION_ID     , C_DELIM, T_DIVISION_ID     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PROJECT_CODE    , C_DELIM, T_PROJECT_CODE    , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_SCM_SITE_ID     , C_DELIM, T_SCM_SITE_ID     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PLANT_SITE_ID   , C_DELIM, T_PLANT_SITE_ID   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_ITEM_ID         , C_DELIM, T_ITEM_ID         , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_CREATED_BY      , C_DELIM, T_CREATED_BY      , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_CREATION_DATE   , C_DELIM, T_CREATION_DATE   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_LAST_UPDATED_BY , C_DELIM, T_LAST_UPDATED_BY , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_PRIORITY        , C_DELIM, T_PRIORITY        , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_FROM_YYYYMMDD   , C_DELIM, T_FROM_YYYYMMDD   , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_TO_YYYYMMDD     , C_DELIM, T_TO_YYYYMMDD     , V_DUMMY_CNT);
    P_SPLIT_TOKEN(P_VALID_YN        , C_DELIM, T_VALID_YN        , V_DUMMY_CNT);

    FOR I IN 1 .. V_LOOP_CNT
    LOOP

        V_PRIORITY_SEQ := F_TOKEN(T_PRIORITY_SEQ, I);

        IF V_PRIORITY_SEQ IS NULL
        THEN
            V_PRIORITY_SEQ := TO_CHAR(SEQ1_SCM_MST_SITE_ITEM_PRIORITY.NEXTVAL);
        END IF;

        V_ACTIVE_FLAG     := F_TOKEN(T_ACTIVE_FLAG, I);
        V_DIVISION_ID     := F_TOKEN(T_DIVISION_ID, I);
        V_PROJECT_CODE    := F_TOKEN(T_PROJECT_CODE, I);
        V_SCM_SITE_ID     := F_TOKEN(T_SCM_SITE_ID, I);
        V_PLANT_SITE_ID   := F_TOKEN(T_PLANT_SITE_ID, I);
        V_ITEM_ID         := F_TOKEN(T_ITEM_ID, I);
        V_CREATED_BY      := F_TOKEN(T_CREATED_BY, I);
        V_CREATION_DATE   := F_TO_DATETIME(F_TOKEN(T_CREATION_DATE, I));
        V_LAST_UPDATED_BY := F_TOKEN(T_LAST_UPDATED_BY, I);
        V_PRIORITY        := F_TOKEN(T_PRIORITY, I);
        V_FROM_YYYYMMDD   := F_TOKEN(T_FROM_YYYYMMDD, I);
        V_TO_YYYYMMDD     := F_TOKEN(T_TO_YYYYMMDD, I);
        V_VALID_YN        := F_TOKEN(T_VALID_YN, I);

        BEGIN
            SELECT VALID_YN
              INTO V_S_VALID_YN
              FROM SCM_MST_SITE_ITEM
             WHERE DIVISION_ID  = V_DIVISION_ID
               AND SCM_SITE_ID  = V_SCM_SITE_ID
               AND ITEM_ID      = V_ITEM_ID
               AND PROJECT_CODE = V_PROJECT_CODE;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN V_S_VALID_YN := NULL;
            WHEN TOO_MANY_ROWS THEN V_S_VALID_YN := NULL;
        END;

        /* 이력저장 */
        PR_SCM_MST_SITE_ITEM_HIST(V_DIVISION_ID, V_PROJECT_CODE, V_PLANT_SITE_ID, V_ITEM_ID
                                , V_CURRENCY, V_LIABILITY_PERIOD, V_SALES_PLAN_ADJUST_YN, V_ITEM_HRCY_ID
                                , V_S_VALID_YN, V_BPMS_EXIST, V_CREATED_BY, TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

        PR_SCM_MST_SITE_ITEM_PRIORITY_HIST(V_PRIORITY_SEQ, V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID
                                         , V_PLANT_SITE_ID, V_ITEM_ID, V_PRIORITY, V_FROM_YYYYMMDD
                                         , V_TO_YYYYMMDD, V_VALID_YN, V_CREATED_BY
                                         , TO_CHAR(V_CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS'), V_LAST_UPDATED_BY);

        /* 데이터 저장 — AS-IS MERGE 를 조회 후 수정 · 넣기로 나눈다 (온라인 SQL 은 MERGE 금지) */
        UPDATE SCM_MST_SITE_ITEM
           SET LAST_UPDATED_BY   = V_LAST_UPDATED_BY
             , LAST_UPDATE_DATE  = SYSDATE
         WHERE DIVISION_ID  = V_DIVISION_ID
           AND PROJECT_CODE = V_PROJECT_CODE
           AND SCM_SITE_ID  = V_PLANT_SITE_ID
           AND ITEM_ID      = V_ITEM_ID;

        IF SQL%ROWCOUNT = 0
        THEN
            INSERT INTO SCM_MST_SITE_ITEM
                        (
                          DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                        , CURRENCY, LIABILITY_PERIOD, SALES_PLAN_ADJUST_YN, ITEM_HRCY_ID
                        , VALID_YN, BPMS_EXIST
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        )
            VALUES      (
                          V_DIVISION_ID, V_PROJECT_CODE, V_PLANT_SITE_ID, V_ITEM_ID
                        , NULL, NULL, NULL, NULL
                        , 'Y', 'Y'
                        , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                        );
        END IF;

        /* SCM_MST_SITE_ITEM_PRIORITY 입력/수정 */
        IF V_ACTIVE_FLAG = 'M'
        THEN
            UPDATE SCM_MST_SITE_ITEM_PRIORITY
               SET SALES_SITE_ID     = V_SCM_SITE_ID
                 , PLANT_SITE_ID     = V_PLANT_SITE_ID
                 , PRIORITY          = V_PRIORITY
                 , FROM_YYYYMMDD     = V_FROM_YYYYMMDD
                 , TO_YYYYMMDD       = V_TO_YYYYMMDD
                 , VALID_YN          = V_VALID_YN
                 , LAST_UPDATED_BY   = V_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE  = SYSDATE
             WHERE PRIORITY_SEQ = TO_NUMBER(V_PRIORITY_SEQ);

        ELSIF V_ACTIVE_FLAG = 'I'
        THEN
            INSERT INTO SCM_MST_SITE_ITEM_PRIORITY
                        (
                          PRIORITY_SEQ, DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID
                        , PRIORITY, FROM_YYYYMMDD, TO_YYYYMMDD, VALID_YN
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        )
            VALUES      (
                          TO_NUMBER(V_PRIORITY_SEQ), V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_PLANT_SITE_ID, V_ITEM_ID
                        , V_PRIORITY, V_FROM_YYYYMMDD, V_TO_YYYYMMDD, V_VALID_YN
                        , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                        );
        END IF;


    END LOOP;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', NULL, SYSDATE);

    COMMIT;

    /* 결과코드, 결과 카운트 반환 */
    O_RESULT_CODE := 'S';
    O_RESULT_CNT  := V_LOOP_CNT;
    O_RESULT_MSG  := NULL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLCODE := SQLCODE;
        V_SQLERRM := SQLERRM;

        ROLLBACK;                                                               /* 입력 데이타 롤백 처리 */

        INSERT INTO SCM_SYS_LOG_BATCH
                    (
                      PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                    , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY
                    )
        VALUES      (
                      V_PROGRAM_NAME, 'ERROR', NULL, V_SQLERRM, NULL
                    , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME
                    );
        COMMIT;

        /* error코드, errror 메시지 반환 */
        O_RESULT_CODE := 'F';
        O_RESULT_CNT  := 0;
        O_RESULT_MSG  := '[' || V_SQLCODE || ']' || V_SQLERRM;

END P_SCP0048_SAVE_PROJECTROUTE_WARRANTY;

END PKG_SCP0048;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0048
-- ##### END PACKAGE BODY PKG_SCP0048

-- ##### START PACKAGE BODY PKG_SCP0049
CREATE OR REPLACE PACKAGE BODY PKG_SCP0049 IS

/* ==================================================================================================
 * PKG_SCP0049 바디
 *
 * Program ID   : PR_SCP_CAPA_HIST_DATASET  ->  PKG_SCP0049.P_CAPA_HIST_DATASET
 * Description  : CAPA 이력 저장(LINE ASSIGN , TACT TIME , YIELD)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021/08/23   khj79          [PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - 최초작성
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *
 * 전환 주기
 *---------------------------------------------------------------------------------------------------
 * 인자         : AS-IS 는 테이블 형식 인자 @SCP0049(DBO.SCP0049 READONLY) 하나뿐이다.
 *                TO-BE 는 인자 없음. AS-IS 가 @SCP0049 를 읽던 자리를 전부 GT_SCP0049_DS 로 바꾼다.
 *                ★ GT_SCP0049_DS 는 호출자가 채운다. 이 프로시저 안에서는 DELETE 하지 않는다.
 * #TMP_CAPA_HIST → GT_SCP0049_CAPA_HIST (신규 GTT · 본문 시작에서 DELETE 로 초기화)
 * CROSS APPLY (상관 조건이 단순 등치) → 인라인 뷰 + 쉼표 조인(내부조인 의미 동일)
 * INNER JOIN   → 쉼표 조인. 원문에 OUTER JOIN 은 없다.
 * SYSDATETIME()                        → SYSDATE (JOB_TIME 이 DATE)
 * CONVERT(NVARCHAR(6), GETDATE(), 112) → TO_CHAR(SYSDATE, 'YYYYMM')
 * CONVERT(NVARCHAR(8), x, 112)         → TO_CHAR(x, 'YYYYMMDD')
 * ISNULL(CONVERT(INT,CONVERT(NUMERIC(20,10),P_DAY_QTY)),0)
 *                                      → NVL(TRUNC(ROUND(TO_NUMBER(P_DAY_QTY), 10)), 0)
 *                                        (CONVERT(INT, numeric) 은 반올림이 아니라 절삭)
 * 트랜잭션     : AS-IS 에 BEGIN TRAN · COMMIT · ROLLBACK · TRY/CATCH 가 없다.
 *                호출자(P_SAVE_CAPA · P_CAPA_EXCEL_UPLOAD · P_SAVE_NEW_MODEL)의 트랜잭션 안에서 돌고
 *                호출자가 SAVEPOINT 를 잡고 있으므로 여기서는 COMMIT · ROLLBACK 을 하지 않는다.
 *                오류는 로그만 남기고 그대로 호출자에게 올린다(RAISE).
 * 이력 테이블  : HIS_ITEM_LINE_ASSIGN_M_SN · HIS_ITEM_LINE_ASSIGN_EXCEPT_M_SN ·
 *                HIS_TACT_TIME_M_SN · HIS_TACT_TIME_EXCEPT_M_SN ·
 *                HIS_YIELD_M_SN · HIS_YIELD_EXCEPT_M_SN
 *                (JOB_SEQ 는 IDENTITY 컬럼이므로 INSERT 목록에서 제외한다)
 * ================================================================================================== */
    PROCEDURE P_CAPA_HIST_DATASET
    IS

        -- 이력용 변수 설정
        V_JOB_TYPE          VARCHAR2(10 CHAR) := 'MERGE';

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0049_CAPA_HIST_DATASET';

    BEGIN

        /* 이력 저장용 테이블 생성
           AS-IS : IF OBJECT_ID('TEMPDB..#TMP_CAPA_HIST') IS NOT NULL DROP TABLE #TMP_CAPA_HIST;
                   CREATE TABLE #TMP_CAPA_HIST ( ... )
           TO-BE : 전용 GTT 를 DELETE 로 초기화(TRUNCATE 금지 — 암묵적 커밋으로 호출자 롤백이 깨진다) */
        DELETE FROM GT_SCP0049_CAPA_HIST;

        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT P_DATA_TABLE
             , P_DATA_TYPE
             , P_LOSS_CODE
             , P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_ELECTRODE_TYPE
             , P_OPERATION_ID
             , P_ITEM_ID
             , P_LANE_QTY
             , P_DAY_NAME
             , P_UPDATE_ID
          FROM GT_SCP0049_DS
         WHERE P_DATA_TABLE IN ('LA','T','Y') -- LINE ASSIGN, TACT TIME , YIELD 만 생성
        ;

        -- 삭제( LINE ASSIGN 9 값) 인 TACT TIME , YIELD 이력 저장
        -- 기존 변경 데이터가 있으면 제외 처리
        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT 'T'                      AS DATA_TABLE
             , A.P_DATA_TYPE
             , A.P_LOSS_CODE
             , A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_ELECTRODE_TYPE
             , A.P_OPERATION_ID
             , A.P_ITEM_ID
             , A.P_LANE_QTY
             , A.P_DAY_NAME
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DS A
         WHERE A.P_DATA_TABLE = 'LA'
           AND A.P_DATA_TYPE  <> 'LQ'
           AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
           AND NOT EXISTS (SELECT 1
                             FROM GT_SCP0049_CAPA_HIST XA
                            WHERE A.P_FACTORY_ID        = XA.FACTORY_ID
                              AND A.P_LINE_ID           = XA.LINE_ID
                              AND A.P_OPERATION_ID      = XA.OPERATION_ID
                              AND A.P_ELECTRODE_TYPE    = XA.ELECTRODE_TYPE
                              AND A.P_ITEM_ID           = XA.ITEM_ID
                              AND A.P_DAY_NAME          = XA.DAY_NAME
                              AND A.P_DATA_TYPE         = XA.DATA_TYPE
                              AND XA.DATA_TABLE         = 'T'
                          )
        ;

        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT 'Y'                      AS DATA_TABLE
             , A.P_DATA_TYPE
             , A.P_LOSS_CODE
             , A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_ELECTRODE_TYPE
             , A.P_OPERATION_ID
             , A.P_ITEM_ID
             , A.P_LANE_QTY
             , A.P_DAY_NAME
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DS A
         WHERE A.P_DATA_TABLE = 'LA'
           AND A.P_DATA_TYPE  <> 'LQ'
           AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
           AND NOT EXISTS (SELECT 1
                             FROM GT_SCP0049_CAPA_HIST XA
                            WHERE A.P_FACTORY_ID        = XA.FACTORY_ID
                              AND A.P_LINE_ID           = XA.LINE_ID
                              AND A.P_OPERATION_ID      = XA.OPERATION_ID
                              AND A.P_ITEM_ID           = XA.ITEM_ID
                              AND A.P_DAY_NAME          = XA.DAY_NAME
                              AND A.P_DATA_TYPE         = XA.DATA_TYPE
                              AND XA.DATA_TABLE         = 'Y'
                          )
        ;

        -- 삭제( LINE ASSIGN 9 값) 인 LINE ASSIGN 이력 저장
        -- 월 삭제인 경우 일자 이력 저장을 위해 일별 데이터 생성
        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT 'LA'                     AS DATA_TABLE
             , 'D'                      AS DATA_TYPE
             , A.P_LOSS_CODE
             , A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_ELECTRODE_TYPE
             , A.P_OPERATION_ID
             , A.P_ITEM_ID
             , A.P_LANE_QTY
             , IA.BASIS_YYYYMMDD        AS DAY_NAME
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DS A
             , ( SELECT DISTINCT BASIS_YYYYMM
                      , BASIS_YYYYMMDD
                   FROM SCM_SYS_CALENDAR_M
               ) IA
         WHERE A.P_DAY_NAME = IA.BASIS_YYYYMM /* AS-IS CROSS APPLY 의 상관 조건 — 내부조인과 같다 */
           AND A.P_DATA_TABLE = 'LA'
           AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
           AND A.P_DATA_TYPE = 'M'
           AND NOT EXISTS (SELECT 1
                             FROM GT_SCP0049_CAPA_HIST XA
                            WHERE A.P_FACTORY_ID        = XA.FACTORY_ID
                              AND A.P_LINE_ID           = XA.LINE_ID
                              AND A.P_OPERATION_ID      = XA.OPERATION_ID
                              AND A.P_ELECTRODE_TYPE    = XA.ELECTRODE_TYPE
                              AND A.P_ITEM_ID           = XA.ITEM_ID
                              AND IA.BASIS_YYYYMMDD     = XA.DAY_NAME
                              AND A.P_DATA_TYPE         = XA.DATA_TYPE
                              AND XA.DATA_TABLE         = 'LA'
                          )
        ;

        -- 삭제( LINE ASSIGN 9 값) 인 TACT TIME , YIELD 이력 저장
        -- 월 삭제인 경우 일자 이력 저장을 위해 일별 데이터 생성
        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT 'T'                      AS DATA_TABLE
             , 'D'                      AS DATA_TYPE
             , A.P_LOSS_CODE
             , A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_ELECTRODE_TYPE
             , A.P_OPERATION_ID
             , A.P_ITEM_ID
             , A.P_LANE_QTY
             , IA.BASIS_YYYYMMDD        AS DAY_NAME
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DS A
             , ( SELECT DISTINCT BASIS_YYYYMM
                      , BASIS_YYYYMMDD
                   FROM SCM_SYS_CALENDAR_M
               ) IA
         WHERE A.P_DAY_NAME = IA.BASIS_YYYYMM /* AS-IS CROSS APPLY 의 상관 조건 — 내부조인과 같다 */
           AND A.P_DATA_TABLE = 'LA'
           AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
           AND A.P_DATA_TYPE = 'M'
           AND NOT EXISTS (SELECT 1
                             FROM GT_SCP0049_CAPA_HIST XA
                            WHERE A.P_FACTORY_ID        = XA.FACTORY_ID
                              AND A.P_LINE_ID           = XA.LINE_ID
                              AND A.P_OPERATION_ID      = XA.OPERATION_ID
                              AND A.P_ELECTRODE_TYPE    = XA.ELECTRODE_TYPE
                              AND A.P_ITEM_ID           = XA.ITEM_ID
                              AND IA.BASIS_YYYYMMDD     = XA.DAY_NAME
                              AND A.P_DATA_TYPE         = XA.DATA_TYPE
                              AND XA.DATA_TABLE         = 'T'
                          )
        ;

        -- 삭제( LINE ASSIGN 9 값) 인 TACT TIME , YIELD 이력 저장
        -- 월 삭제인 경우 일자 이력 저장을 위해 일별 데이터 생성
        INSERT INTO GT_SCP0049_CAPA_HIST
                  ( DATA_TABLE
                  , DATA_TYPE
                  , LOSS_CODE
                  , DIVISION_ID
                  , COMPANY_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , OPERATION_ID
                  , ITEM_ID
                  , LANE_QTY
                  , DAY_NAME
                  , UPDATE_ID
                  )
        SELECT 'Y'                      AS DATA_TABLE
             , 'D'                      AS DATA_TYPE
             , A.P_LOSS_CODE
             , A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_ELECTRODE_TYPE
             , A.P_OPERATION_ID
             , A.P_ITEM_ID
             , A.P_LANE_QTY
             , IA.BASIS_YYYYMMDD        AS DAY_NAME
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DS A
             , ( SELECT DISTINCT BASIS_YYYYMM
                      , BASIS_YYYYMMDD
                   FROM SCM_SYS_CALENDAR_M
               ) IA
         WHERE A.P_DAY_NAME = IA.BASIS_YYYYMM /* AS-IS CROSS APPLY 의 상관 조건 — 내부조인과 같다 */
           AND A.P_DATA_TABLE = 'LA'
           AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
           AND A.P_DATA_TYPE = 'M'
           AND NOT EXISTS (SELECT 1
                             FROM GT_SCP0049_CAPA_HIST XA
                            WHERE A.P_FACTORY_ID        = XA.FACTORY_ID
                              AND A.P_LINE_ID           = XA.LINE_ID
                              AND A.P_OPERATION_ID      = XA.OPERATION_ID
                              AND A.P_ITEM_ID           = XA.ITEM_ID
                              AND IA.BASIS_YYYYMMDD     = XA.DAY_NAME
                              AND A.P_DATA_TYPE         = XA.DATA_TYPE
                              AND XA.DATA_TABLE         = 'Y'
                          )
        ;

        -- LINE ASSIGN 월별 이력 저장
        INSERT INTO HIS_ITEM_LINE_ASSIGN_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , LANE_QTY
                  , MONTH
                  , WORK_CENTER_ID
                  , PRIORITY
                  , CERTIFICATION_FLAG
                  , CERTIFICATION_DATE
                  , ACTIVE_FLAG
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , WIP_LEVEL_QTY
                  , ELECTRODE_TYPE
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.LANE_QTY
             , A.MONTH
             , A.WORK_CENTER_ID
             , A.PRIORITY
             , A.CERTIFICATION_FLAG
             , A.CERTIFICATION_DATE
             , A.ACTIVE_FLAG
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , A.WIP_LEVEL_QTY
             , A.ELECTRODE_TYPE
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , GT_SCP0049_CAPA_HIST B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND A.MONTH          >= TO_CHAR(SYSDATE, 'YYYYMM')
           AND B.DATA_TYPE      = 'LQ'
        ;

        -- LINE ASSIGN 일별 이력 저장
        INSERT INTO HIS_ITEM_LINE_ASSIGN_EXCEPT_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , ITEM_ID
                  , OPERATION_ID
                  , LINE_ID
                  , WORK_CENTER_ID
                  , PRIORITY
                  , START_TIME
                  , END_TIME
                  , DESCRIPTION
                  , ACTIVE_FLAG
                  , ELECTRODE_TYPE
                  , LANE_QTY
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.WORK_CENTER_ID
             , A.PRIORITY
             , A.START_TIME
             , A.END_TIME
             , A.DESCRIPTION
             , A.ACTIVE_FLAG
             , A.ELECTRODE_TYPE
             , A.LANE_QTY
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
             , GT_SCP0049_CAPA_HIST B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND TO_CHAR(A.START_TIME, 'YYYYMM') >= TO_CHAR(SYSDATE, 'YYYYMM')
           AND B.DATA_TYPE      = 'LQ'
        ;

        -- LINE_ASSIGN 월별 이력 저장
        INSERT INTO HIS_ITEM_LINE_ASSIGN_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , LANE_QTY
                  , MONTH
                  , WORK_CENTER_ID
                  , PRIORITY
                  , CERTIFICATION_FLAG
                  , CERTIFICATION_DATE
                  , ACTIVE_FLAG
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , WIP_LEVEL_QTY
                  , ELECTRODE_TYPE
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.LANE_QTY
             , A.MONTH
             , A.WORK_CENTER_ID
             , A.PRIORITY
             , A.CERTIFICATION_FLAG
             , A.CERTIFICATION_DATE
             , A.ACTIVE_FLAG
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , A.WIP_LEVEL_QTY
             , A.ELECTRODE_TYPE
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
             , ( SELECT IA.COMPANY_ID
                      , IA.DIVISION_ID
                      , IA.SITE_ID
                      , IA.PLANT_ID
                      , IA.FACTORY_ID
                      , IA.ITEM_ID
                      , IA.OPERATION_ID
                      , IA.LINE_ID
                      , IA.ELECTRODE_TYPE
                      , IB.BASIS_YYYYMM         AS WORK_MONTH
                      , IA.DATA_TYPE
                      , IA.UPDATE_ID
                   FROM GT_SCP0049_CAPA_HIST IA
                      , ( SELECT DISTINCT BASIS_YYYYMM
                               , CALENDAR_YYYY
                            FROM SCM_SYS_CALENDAR_M
                        ) IB
                  WHERE CASE WHEN IA.DATA_TYPE = 'Y' THEN IB.CALENDAR_YYYY
                             WHEN IA.DATA_TYPE = 'M' THEN IB.BASIS_YYYYMM
                        END = IA.DAY_NAME
                    AND IA.DATA_TABLE = 'LA'  -- SCM_ITEM_LINE_ASSIGN_M
                    AND IA.DATA_TYPE IN ( 'M' , 'Y')
               ) B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND A.MONTH          = B.WORK_MONTH
        ;

        -- LINE_ASSIGN 일별 이력 저장
        INSERT INTO HIS_ITEM_LINE_ASSIGN_EXCEPT_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , ITEM_ID
                  , OPERATION_ID
                  , LINE_ID
                  , WORK_CENTER_ID
                  , PRIORITY
                  , START_TIME
                  , END_TIME
                  , DESCRIPTION
                  , ACTIVE_FLAG
                  , ELECTRODE_TYPE
                  , LANE_QTY
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.WORK_CENTER_ID
             , A.PRIORITY
             , A.START_TIME
             , A.END_TIME
             , A.DESCRIPTION
             , A.ACTIVE_FLAG
             , A.ELECTRODE_TYPE
             , A.LANE_QTY
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
             , GT_SCP0049_CAPA_HIST B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND NVL(A.LANE_QTY, 0) = NVL(TO_NUMBER(B.LANE_QTY), 0) /* AS-IS ISNULL(M.LANE_QTY,0) = ISNULL(B.LANE_QTY,0) — 문자 칸이 숫자로 암시 변환된다 */
           AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
           AND B.DATA_TABLE     = 'LA'
           AND B.DATA_TYPE      = 'D'
        ;

        -- TACT_TIME 월별 이력 저장
        INSERT INTO HIS_TACT_TIME_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , MONTH
                  , WORK_CENTER_ID
                  , TACT_TIME
                  , TACT_TIME_UOM
                  , ELECTRODE_TYPE
                  , DAILY_CAPA
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.MONTH
             , A.WORK_CENTER_ID
             , A.TACT_TIME
             , A.TACT_TIME_UOM
             , A.ELECTRODE_TYPE
             , A.DAILY_CAPA
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_TACT_TIME_SN A
             , ( SELECT IA.COMPANY_ID
                      , IA.DIVISION_ID
                      , IA.SITE_ID
                      , IA.PLANT_ID
                      , IA.FACTORY_ID
                      , IA.ITEM_ID
                      , IA.OPERATION_ID
                      , IA.LINE_ID
                      , IA.ELECTRODE_TYPE
                      , IB.BASIS_YYYYMM         AS WORK_MONTH
                      , IA.UPDATE_ID
                   FROM GT_SCP0049_CAPA_HIST IA
                      , ( SELECT DISTINCT BASIS_YYYYMM
                               , CALENDAR_YYYY
                            FROM SCM_SYS_CALENDAR_M
                        ) IB
                  WHERE CASE WHEN IA.DATA_TYPE = 'Y' THEN IB.CALENDAR_YYYY
                             WHEN IA.DATA_TYPE = 'M' THEN IB.BASIS_YYYYMM
                        END = IA.DAY_NAME
                    AND IA.DATA_TABLE = 'T'   -- SCM_TACT_TIME_M
                    AND IA.DATA_TYPE IN ( 'M' , 'Y')
               ) B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND A.MONTH          = B.WORK_MONTH
        ;

        -- TACT_TIME 일별 이력 저장
        INSERT INTO HIS_TACT_TIME_EXCEPT_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , WORK_CENTER_ID
                  , TACT_TIME
                  , TACT_TIME_UOM
                  , START_TIME
                  , END_TIME
                  , ACTIVE_FLAG
                  , ELECTRODE_TYPE
                  , DAILY_CAPA
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.WORK_CENTER_ID
             , A.TACT_TIME
             , A.TACT_TIME_UOM
             , A.START_TIME
             , A.END_TIME
             , A.ACTIVE_FLAG
             , A.ELECTRODE_TYPE
             , A.DAILY_CAPA
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_TACT_TIME_EXCEPT_SN A
             , GT_SCP0049_CAPA_HIST B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
           AND B.DATA_TABLE     = 'T'
           AND B.DATA_TYPE      = 'D'
        ;


        -- YIELD 월별 이력 저장
        INSERT INTO HIS_YIELD_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , MONTH
                  , WORK_CENTER_ID
                  , YIELD
                  , DESCRIPTION
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.MONTH
             , A.WORK_CENTER_ID
             , A.YIELD
             , A.DESCRIPTION
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_YIELD_SN A
             , ( SELECT IA.COMPANY_ID
                      , IA.DIVISION_ID
                      , IA.SITE_ID
                      , IA.PLANT_ID
                      , IA.FACTORY_ID
                      , IA.ITEM_ID
                      , IA.OPERATION_ID
                      , IA.LINE_ID
                      , IB.BASIS_YYYYMM         AS WORK_MONTH
                      , IA.DATA_TYPE
                      , IA.UPDATE_ID
                   FROM GT_SCP0049_CAPA_HIST IA
                      , ( SELECT DISTINCT BASIS_YYYYMM
                               , CALENDAR_YYYY
                            FROM SCM_SYS_CALENDAR_M
                        ) IB
                  WHERE CASE WHEN IA.DATA_TYPE = 'Y' THEN IB.CALENDAR_YYYY
                             WHEN IA.DATA_TYPE = 'M' THEN IB.BASIS_YYYYMM
                        END = IA.DAY_NAME
                    AND IA.DATA_TABLE = 'Y'
                    AND IA.DATA_TYPE IN ( 'M' , 'Y')
               ) B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.MONTH          = B.WORK_MONTH
        ;

        -- YIELD 일별 이력 저장
        INSERT INTO HIS_YIELD_EXCEPT_M_SN
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ITEM_ID
                  , WORK_CENTER_ID
                  , YIELD
                  , START_TIME
                  , END_TIME
                  , ACTIVE_FLAG
                  , INSERT_ID
                  , INSERT_TIME
                  , UPDATE_ID
                  , UPDATE_TIME
                  , JOB_USER_ID
                  , JOB_TIME
                  , JOB_TYPE
                  )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.WORK_CENTER_ID
             , A.YIELD
             , A.START_TIME
             , A.END_TIME
             , A.ACTIVE_FLAG
             , A.INSERT_ID
             , A.INSERT_TIME
             , A.UPDATE_ID
             , A.UPDATE_TIME
             , B.UPDATE_ID
             , SYSDATE
             , V_JOB_TYPE
          FROM SCM_MST_YIELD_EXCEPT_SN A
             , GT_SCP0049_CAPA_HIST B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.ITEM_ID        = B.ITEM_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
           AND B.DATA_TABLE     = 'Y'
           AND B.DATA_TYPE      = 'D'
        ;

    EXCEPTION
        WHEN OTHERS THEN

            /* AS-IS 에는 TRY/CATCH 가 없다. 호출자의 트랜잭션 안에서 도는 하위 프로시저이므로
               여기서 COMMIT · ROLLBACK 을 하지 않고 로그만 남긴 뒤 호출자에게 오류를 그대로 올린다. */
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, SQLERRM, NULL, SYSDATE, NULL
                               , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

            RAISE;

    END P_CAPA_HIST_DATASET;

/* ==================================================================================================
 * PKG_SCP0049 바디
 *
 * Program ID   : PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET  ->  PKG_SCP0049.P_CAPA_LINE_ASSIGN_DELETE_DATASET
 * Description  : LINE ASSIGN 삭제(TACT TIME , YIELD 삭제 동기화)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2021/08/24   khj79          [PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - 최초작성
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *
 * 전환 주기
 *---------------------------------------------------------------------------------------------------
 * 인자         : AS-IS 는 테이블 형식 인자 @SCP0049(DBO.SCP0049 READONLY) 하나뿐이다.
 *                TO-BE 는 인자 없음. AS-IS 가 @SCP0049 를 읽던 자리를 전부 GT_SCP0049_DS 로 바꾼다.
 *                ★ GT_SCP0049_DS 는 호출자가 채운다. 이 프로시저 안에서는 DELETE 하지 않는다.
 * 전용 GTT     : 없음(AS-IS 에 임시테이블이 없다).
 * DELETE X FROM 원장 X JOIN @SCP0049 T ON ...
 *              → DELETE FROM 원장 A WHERE EXISTS (SELECT 1 FROM GT_SCP0049_DS XA WHERE ...)
 *                (내부조인이므로 EXISTS 로 옮겨도 삭제 대상이 같다. 조건 개수는 원문과 동일)
 * CONVERT(VARCHAR(8), x, 112) → TO_CHAR(x, 'YYYYMMDD')
 * CONVERT(VARCHAR(6), x, 112) → TO_CHAR(x, 'YYYYMM')
 * 변수 @v_job_type 은 AS-IS 에서 선언만 하고 쓰지 않는다 — 옮기지 않는다.
 * 트랜잭션     : AS-IS 에 BEGIN TRAN · COMMIT · ROLLBACK · TRY/CATCH 가 없다.
 *                호출자(P_SAVE_CAPA · P_CAPA_EXCEL_UPLOAD · P_SAVE_NEW_MODEL)의 트랜잭션 안에서 돌고
 *                호출자가 SAVEPOINT 를 잡고 있으므로 여기서는 COMMIT · ROLLBACK 을 하지 않는다.
 *                오류는 로그만 남기고 그대로 호출자에게 올린다(RAISE).
 * ================================================================================================== */
    PROCEDURE P_CAPA_LINE_ASSIGN_DELETE_DATASET
    IS

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0049_CAPA_LINE_ASSIGN_DELETE_DATASET';

    BEGIN

        -- 1. LINE ASSIGN 월별 데이터 삭제
        DELETE FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ELECTRODE_TYPE   = A.ELECTRODE_TYPE
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND XA.P_DAY_NAME         = A.MONTH
                          AND XA.P_DATA_TYPE        = 'M'
                      )
        ;

        -- 2. LINE ASSIGN 일별 데이터 삭제
        DELETE FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ELECTRODE_TYPE   = A.ELECTRODE_TYPE
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND (
                                   (XA.P_DATA_TYPE  = 'D' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMMDD') )
                               OR  (XA.P_DATA_TYPE  = 'M' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMM') )
                              )
                      )
        ;

        -- 3. TACT TIME 월별 데이터 삭제
        DELETE FROM SCM_MST_TACT_TIME_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ELECTRODE_TYPE   = A.ELECTRODE_TYPE
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND XA.P_DAY_NAME         = A.MONTH
                          AND XA.P_DATA_TYPE        = 'M'
                      )
        ;

        -- 4. TACT TIME 일별 데이터 삭제
        DELETE FROM SCM_MST_TACT_TIME_EXCEPT_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ELECTRODE_TYPE   = A.ELECTRODE_TYPE
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND (
                                   (XA.P_DATA_TYPE  = 'D' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMMDD') )
                               OR  (XA.P_DATA_TYPE  = 'M' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMM') )
                              )
                      )
        ;

        -- 5. YIELD 월별 데이터 삭제
        DELETE FROM SCM_MST_YIELD_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND XA.P_DAY_NAME         = A.MONTH
                          AND XA.P_DATA_TYPE        = 'M'
                      )
        ;


        -- 6. YIELD 일별 데이터 삭제
        DELETE FROM SCM_MST_YIELD_EXCEPT_SN A
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_DS XA
                        WHERE XA.P_DIVISION_ID      = A.DIVISION_ID
                          AND XA.P_COMPANY_ID       = A.COMPANY_ID
                          AND XA.P_SITE_ID          = A.SITE_ID
                          AND XA.P_PLANT_ID         = A.PLANT_ID
                          AND XA.P_FACTORY_ID       = A.FACTORY_ID
                          AND XA.P_LINE_ID          = A.LINE_ID
                          AND XA.P_OPERATION_ID     = A.OPERATION_ID
                          AND XA.P_ITEM_ID          = A.ITEM_ID
                          AND (
                                   (XA.P_DATA_TYPE  = 'D' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMMDD') )
                               OR  (XA.P_DATA_TYPE  = 'M' AND XA.P_DAY_NAME = TO_CHAR(A.START_TIME, 'YYYYMM') )
                              )
                      )
        ;

    EXCEPTION
        WHEN OTHERS THEN

            /* AS-IS 에는 TRY/CATCH 가 없다. 호출자의 트랜잭션 안에서 도는 하위 프로시저이므로
               여기서 COMMIT · ROLLBACK 을 하지 않고 로그만 남긴 뒤 호출자에게 오류를 그대로 올린다. */
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, SQLERRM, NULL, SYSDATE, NULL
                               , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

            RAISE;

    END P_CAPA_LINE_ASSIGN_DELETE_DATASET;

