               AND LV.ACTIVE_FLAG      = 'Y'
               --AND LV.ATTRIBUTE1     = 'TACT TIME'
               AND TE.VERSION_ID       = P_VERSION_ID
               AND SUBSTR(TE.MONTH, 1, 4) >= V_START_YEAR
               AND SUBSTR(TE.MONTH, 1, 4) <= V_END_YEAR
          GROUP BY TE.COMPANY_ID
                 , TE.DIVISION_ID
                 , TE.SITE_ID
                 , TE.PLANT_ID
                 , TE.FACTORY_ID
                 , TE.OPERATION_ID
                 , TE.LINE_ID
                 , TE.ELECTRODE_TYPE
                 , TE.ITEM_ID
                 , SUBSTR(TE.MONTH, 1, 4);
         END IF;

         IF P_CHECK_YIELD = 'Y' THEN
            INSERT INTO GT_SCP0049_LTY
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , LANE_QTY
                      , YYYYMMDD
                      , YYYYMM
                      , YYYY
                      , ITEM_VALUE )
            SELECT YE.DIVISION_ID
                 , YE.COMPANY_ID
                 , YE.SITE_ID
                 , YE.PLANT_ID
                 , YE.FACTORY_ID
                 , YE.LINE_ID
                 , '/'                                     /* ELECTRODE_TYPE */   -- I.ELECTRODE_TYPE
                 , YE.OPERATION_ID
                 , 'LA003'                                 /* LOSS_CODE */
                 , YE.ITEM_ID
                 , 0                                       /* LANE_QTY */
                 , NULL                                    /* YYYYMMDD */
                 , NULL                                    /* YYYYMM */
                 , SUBSTR(YE.MONTH, 1, 4)                  /* YYYY */
                 , ROUND(MAX(YE.YIELD * 100), 2)           /* ITEM_VALUE */
              FROM SCM_YIELD_VER_H_SN        YE            -- VERSION 테이블
                 , GT_SCP0049_STD_ITEM_YIELD I
             WHERE 1 = 1
               AND YE.DIVISION_ID  = I.DIVISION_ID
               AND YE.COMPANY_ID   = I.COMPANY_ID
               AND YE.SITE_ID      = I.SITE_ID
               AND YE.PLANT_ID     = I.PLANT_ID
               AND YE.FACTORY_ID   = I.FACTORY_ID
               AND YE.OPERATION_ID = I.OPERATION_ID
               AND YE.LINE_ID      = I.LINE_ID
               AND YE.ITEM_ID      = I.ITEM_ID
               AND YE.VERSION_ID   = P_VERSION_ID
               AND SUBSTR(YE.MONTH, 1, 4) >= V_START_YEAR
               AND SUBSTR(YE.MONTH, 1, 4) <= V_END_YEAR
          GROUP BY YE.COMPANY_ID
                 , YE.DIVISION_ID
                 , YE.SITE_ID
                 , YE.PLANT_ID
                 , YE.FACTORY_ID
                 , YE.OPERATION_ID
                 , YE.LINE_ID
                 , YE.ITEM_ID
                 , SUBSTR(YE.MONTH, 1, 4);
         END IF;

         /* /////////////////////////////////////////////////////////////////////////////// */
         /* DAILY , MM ,YEAR 합기기                                                         */
         /* AS-IS #TMP_SCP0049_DAILY2 · #TMP_SCP0049_MM2 · #TMP_SCP0049_YEAR2 은 각각       */
         /* 한 번만 참조하므로 인라인으로 옮긴다                                            */
         /* /////////////////////////////////////////////////////////////////////////////// */
         IF P_CHECK_LOSS = 'Y' THEN
            INSERT INTO GT_SCP0049_DMY
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , YYYYMMDD
                      , YYYYMM
                      , YYYY
                      , ITEM_VALUE )
            /* 일별 테이블 조회 (AS-IS #TMP_SCP0049_DAILY2) */
            SELECT CM.DIVISION_ID
                 , CM.COMPANY_ID
                 , CM.SITE_ID
                 , CM.PLANT_ID
                 , CM.FACTORY_ID
                 , CM.LINE_ID
                 , CM.ELECTRODE_TYPE
                 , CM.OPERATION_ID
                 , LU.LOSS_CODE
                 , TO_CHAR(CM.WORK_DATE, 'YYYYMMDD')       /* YYYYMMDD */
                 , CAST(NULL AS VARCHAR2(6))               /* YYYYMM */
                 , CAST(NULL AS VARCHAR2(4))               /* YYYY */
                 , NVL(CM.TIME_TERM, 0)                    /* ITEM_VALUE */
              FROM GT_SCP0049_LOOKUP     LU
                 , SCM_WORK_CAL_VER_H_SN CM                -- VERSION 테이블
                 , GT_SCP0049_STD        L
             WHERE 1 = 1
               AND CM.LOSS_CODE      = LU.LOSS_CODE
               AND CM.DIVISION_ID    = L.DIVISION_ID
               AND CM.COMPANY_ID     = L.COMPANY_ID
               AND CM.SITE_ID        = L.SITE_ID
               AND CM.PLANT_ID       = L.PLANT_ID
               AND CM.FACTORY_ID     = L.FACTORY_ID
               AND CM.OPERATION_ID   = L.OPERATION_ID
               AND CM.LINE_ID        = L.LINE_ID
               AND UPPER(CM.ELECTRODE_TYPE) = UPPER(L.ELECTRODE_TYPE)
               AND LU.DATA_TABLE     = 'SCM_WORK_CALENDAR_M'
               AND CM.VERSION_ID     = P_VERSION_ID
               AND TO_CHAR(CM.WORK_DATE, 'YYYYMMDD') >= V_START_DAY
               AND TO_CHAR(CM.WORK_DATE, 'YYYYMMDD') <= V_END_DAY

            UNION ALL

            /* 월 합계 (AS-IS #TMP_SCP0049_MM2) */
            SELECT CM.DIVISION_ID
                 , CM.COMPANY_ID
                 , CM.SITE_ID
                 , CM.PLANT_ID
                 , CM.FACTORY_ID
                 , CM.LINE_ID
                 , CM.ELECTRODE_TYPE
                 , CM.OPERATION_ID
                 , CM.LOSS_CODE
                 , CAST(NULL AS VARCHAR2(8))               /* YYYYMMDD */
                 , TO_CHAR(CM.WORK_DATE, 'YYYYMM')         /* YYYYMM */
                 , CAST(NULL AS VARCHAR2(4))               /* YYYY */
                 , SUM(CM.TIME_TERM)                       /* ITEM_VALUE */
              FROM GT_SCP0049_LOOKUP     LU
                 , SCM_WORK_CAL_VER_H_SN CM                -- VERSION 테이블
                 , GT_SCP0049_STD        L
             WHERE 1 = 1
               AND CM.LOSS_CODE      = LU.LOSS_CODE
               AND CM.DIVISION_ID    = L.DIVISION_ID
               AND CM.COMPANY_ID     = L.COMPANY_ID
               AND CM.SITE_ID        = L.SITE_ID
               AND CM.PLANT_ID       = L.PLANT_ID
               AND CM.FACTORY_ID     = L.FACTORY_ID
               AND CM.OPERATION_ID   = L.OPERATION_ID
               AND CM.LINE_ID        = L.LINE_ID
               AND UPPER(CM.ELECTRODE_TYPE) = UPPER(L.ELECTRODE_TYPE)
               AND LU.DATA_TABLE     = 'SCM_WORK_CALENDAR_M'
               AND CM.VERSION_ID     = P_VERSION_ID
               AND TO_CHAR(CM.WORK_DATE, 'YYYYMM') >= V_START_MONTH  -- '202008'
               AND TO_CHAR(CM.WORK_DATE, 'YYYYMM') <= V_END_MONTH    -- '202106'
          GROUP BY CM.COMPANY_ID
                 , CM.DIVISION_ID
                 , CM.SITE_ID
                 , CM.PLANT_ID
                 , CM.FACTORY_ID
                 , CM.OPERATION_ID
                 , CM.LINE_ID
                 , CM.ELECTRODE_TYPE
                 , CM.LOSS_CODE
                 , TO_CHAR(CM.WORK_DATE, 'YYYYMM')

            UNION ALL

            -- SCM_LOSS_M_SN  (AS-IS #TMP_SCP0049_MM2)
            SELECT LM.DIVISION_ID
                 , LM.COMPANY_ID
                 , LM.SITE_ID
                 , LM.PLANT_ID
                 , LM.FACTORY_ID
                 , LM.LINE_ID
                 , LM.ELECTRODE_TYPE
                 , LM.OPERATION_ID
                 , LU.LOSS_CODE
                 , CAST(NULL AS VARCHAR2(8))               /* YYYYMMDD */
                 , LM.WORK_MONTH                           /* YYYYMM */
                 , CAST(NULL AS VARCHAR2(4))               /* YYYY */
                 , NVL(ROUND(LM.LOSS_RATE * 100, 2), 0)    /* ITEM_VALUE */
              FROM GT_SCP0049_LOOKUP LU
                 , SCM_LOSS_VER_H_SN  LM                   -- VERSION 테이블
                 , GT_SCP0049_STD     L
             WHERE 1 = 1
               AND LM.LOSS_CODE      = LU.LOSS_CODE
               AND LM.DIVISION_ID    = L.DIVISION_ID
               AND LM.COMPANY_ID     = L.COMPANY_ID
               AND LM.SITE_ID        = L.SITE_ID
               AND LM.PLANT_ID       = L.PLANT_ID
               AND LM.FACTORY_ID     = L.FACTORY_ID
               AND LM.OPERATION_ID   = L.OPERATION_ID
               AND LM.LINE_ID        = L.LINE_ID
               AND UPPER(LM.ELECTRODE_TYPE) = UPPER(L.ELECTRODE_TYPE)
               AND LU.LOSS_CODE     <> 'M08'
               AND LU.DATA_TABLE     = 'SCM_LOSS_M'
               AND LM.VERSION_ID     = P_VERSION_ID
               AND LM.WORK_MONTH    >= V_START_MONTH
               AND LM.WORK_MONTH    <= V_END_MONTH

            UNION ALL

            /* 연 합계 (AS-IS #TMP_SCP0049_YEAR2) */
            SELECT CM.DIVISION_ID
                 , CM.COMPANY_ID
                 , CM.SITE_ID
                 , CM.PLANT_ID
                 , CM.FACTORY_ID
                 , CM.LINE_ID
                 , CM.ELECTRODE_TYPE
                 , CM.OPERATION_ID
                 , CM.LOSS_CODE
                 , CAST(NULL AS VARCHAR2(8))               /* YYYYMMDD */
                 , CAST(NULL AS VARCHAR2(6))               /* YYYYMM */
                 , TO_CHAR(CM.WORK_DATE, 'YYYY')           /* YYYY */
                 , SUM(CM.TIME_TERM)                       /* ITEM_VALUE */
              FROM GT_SCP0049_LOOKUP     LU
                 , SCM_WORK_CAL_VER_H_SN CM                -- VERSION 테이블
                 , GT_SCP0049_STD        L
             WHERE 1 = 1
               AND CM.LOSS_CODE      = LU.LOSS_CODE
               AND CM.DIVISION_ID    = L.DIVISION_ID
               AND CM.COMPANY_ID     = L.COMPANY_ID
               AND CM.SITE_ID        = L.SITE_ID
               AND CM.PLANT_ID       = L.PLANT_ID
               AND CM.FACTORY_ID     = L.FACTORY_ID
               AND CM.OPERATION_ID   = L.OPERATION_ID
               AND CM.LINE_ID        = L.LINE_ID
               AND UPPER(CM.ELECTRODE_TYPE) = UPPER(L.ELECTRODE_TYPE)
               AND LU.DATA_TABLE     = 'SCM_WORK_CALENDAR_M'
               AND CM.VERSION_ID     = P_VERSION_ID
               AND TO_CHAR(CM.WORK_DATE, 'YYYY') >= V_START_YEAR  -- '2021'
               AND TO_CHAR(CM.WORK_DATE, 'YYYY') <= V_END_YEAR    -- '2023'
          GROUP BY CM.COMPANY_ID
                 , CM.DIVISION_ID
                 , CM.SITE_ID
                 , CM.PLANT_ID
                 , CM.FACTORY_ID
                 , CM.OPERATION_ID
                 , CM.LINE_ID
                 , CM.ELECTRODE_TYPE
                 , CM.LOSS_CODE
                 , TO_CHAR(CM.WORK_DATE, 'YYYY')

            UNION ALL

            -- SCM_LOSS_M_SN  (AS-IS #TMP_SCP0049_YEAR2)
            SELECT LM.DIVISION_ID
                 , LM.COMPANY_ID
                 , LM.SITE_ID
                 , LM.PLANT_ID                             -- 공장(오창)
                 , LM.FACTORY_ID
                 , LM.LINE_ID                              -- 라인
                 , LM.ELECTRODE_TYPE                       -- 라인 구분
                 , LM.OPERATION_ID                         -- 공정
                 , LM.LOSS_CODE
                 , CAST(NULL AS VARCHAR2(8))               /* YYYYMMDD */
                 , CAST(NULL AS VARCHAR2(6))               /* YYYYMM */
                 , SUBSTR(LM.WORK_MONTH, 1, 4)             /* YYYY */
                 , SUM(LM.LOSS_RATE)                       /* ITEM_VALUE */
              FROM GT_SCP0049_LOOKUP LU
                 , SCM_LOSS_VER_H_SN  LM                   -- VERSION 테이블
                 , GT_SCP0049_STD     L
             WHERE 1 = 1
               AND LM.LOSS_CODE      = LU.LOSS_CODE
               AND LM.DIVISION_ID    = L.DIVISION_ID
               AND LM.COMPANY_ID     = L.COMPANY_ID
               AND LM.SITE_ID        = L.SITE_ID
               AND LM.PLANT_ID       = L.PLANT_ID
               AND LM.FACTORY_ID     = L.FACTORY_ID
               AND LM.OPERATION_ID   = L.OPERATION_ID
               AND LM.LINE_ID        = L.LINE_ID
               AND UPPER(LM.ELECTRODE_TYPE) = UPPER(L.ELECTRODE_TYPE)
               AND LU.DATA_TABLE     = 'SCM_LOSS_M'
               AND LM.VERSION_ID     = P_VERSION_ID
               AND SUBSTR(LM.WORK_MONTH, 1, 4) >= V_START_YEAR
               AND SUBSTR(LM.WORK_MONTH, 1, 4) <= V_END_YEAR
          GROUP BY LM.COMPANY_ID
                 , LM.DIVISION_ID
                 , LM.SITE_ID
                 , LM.PLANT_ID
                 , LM.FACTORY_ID
                 , LM.OPERATION_ID
                 , LM.LINE_ID
                 , LM.ELECTRODE_TYPE
                 , LM.LOSS_CODE
                 , SUBSTR(LM.WORK_MONTH, 1, 4);
         END IF;

         /* /////////////////////////////////////////////////////////////////////////////// */
         /* AVG 정보 추가                                                                   */
         /* /////////////////////////////////////////////////////////////////////////////// */
         IF P_CHECK_LOSS = 'Y' THEN
            INSERT INTO GT_SCP0049_ADD_STD
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , YYYYMMDD
                      , YYYYMM
                      , YYYY
                      , ITEM_VALUE )
            SELECT DISTINCT
                   XA.DIVISION_ID
                 , XA.COMPANY_ID
                 , XA.SITE_ID
                 , XA.PLANT_ID
                 , XA.FACTORY_ID
                 , XA.LINE_ID
                 , XA.ELECTRODE_TYPE
                 , XA.OPERATION_ID
                 , XA.LOSS_CODE
                 , XA.YYYYMMDD
                 , XA.YYYYMM
                 , XA.YYYY
                 , R.ITEM_VALUE
              FROM ( SELECT DISTINCT
                            IA.DIVISION_ID
                          , IA.COMPANY_ID
                          , IA.SITE_ID
                          , IA.PLANT_ID
                          , IA.FACTORY_ID
                          , IA.LINE_ID
                          , IA.ELECTRODE_TYPE
                          , IA.OPERATION_ID
                          , LU.LOSS_CODE
                          , IA.YYYYMMDD
                          , IA.YYYYMM
                          , IA.YYYY
                       FROM ( SELECT A.DIVISION_ID
                                   , A.COMPANY_ID
                                   , A.SITE_ID
                                   , A.PLANT_ID
                                   , A.FACTORY_ID
                                   , A.LINE_ID
                                   , A.ELECTRODE_TYPE
                                   , A.OPERATION_ID
                                   , B.YYYYMMDD
                                   , B.YYYYMM
                                   , B.YYYY
                                FROM GT_SCP0049_STD A
                                   , GT_SCP0049_DMY B
                               WHERE A.DIVISION_ID    = B.DIVISION_ID(+)
                                 AND A.COMPANY_ID     = B.COMPANY_ID(+)
                                 AND A.SITE_ID        = B.SITE_ID(+)
                                 AND A.PLANT_ID       = B.PLANT_ID(+)
                                 AND A.FACTORY_ID     = B.FACTORY_ID(+)
                                 AND A.LINE_ID        = B.LINE_ID(+)
                                 AND UPPER(A.ELECTRODE_TYPE) = UPPER(B.ELECTRODE_TYPE(+))
                                 AND A.OPERATION_ID   = B.OPERATION_ID(+)
                            ) IA
                          , GT_SCP0049_LOOKUP LU
                      WHERE 1 = 1
                        AND LU.DATA_TABLE IN ('SCM_WORK_CALENDAR_M', 'SCM_LOSS_M')
                   ) XA   -- LOOKUP 정보 추가
                 , GT_SCP0049_DMY R
             WHERE R.DIVISION_ID(+)         = XA.DIVISION_ID
               AND R.COMPANY_ID(+)          = XA.COMPANY_ID
               AND R.SITE_ID(+)             = XA.SITE_ID
               AND R.PLANT_ID(+)            = XA.PLANT_ID
               AND R.FACTORY_ID(+)          = XA.FACTORY_ID
               AND R.LINE_ID(+)             = XA.LINE_ID
               AND UPPER(R.ELECTRODE_TYPE(+))      = UPPER(XA.ELECTRODE_TYPE)
               AND R.OPERATION_ID(+)        = XA.OPERATION_ID
               AND R.LOSS_CODE(+)           = XA.LOSS_CODE
               AND NVL(TRIM(R.YYYYMMDD(+)), '-')  = NVL(TRIM(XA.YYYYMMDD), '-')
               AND NVL(TRIM(R.YYYYMM(+)), '-')    = NVL(TRIM(XA.YYYYMM), '-')
               AND NVL(TRIM(R.YYYY(+)), '-')      = NVL(TRIM(XA.YYYY), '-');
         END IF;

         /* /////////////////////////////////////////////////////////////////////////////// */
         /* LTY Line Priority 기준으로 정보 Tact Time , Yield 추가                          */
         /* /////////////////////////////////////////////////////////////////////////////// */
         IF P_CHECK_TACT = 'Y' THEN
            INSERT INTO GT_SCP0049_LTY
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , YYYYMM )
            SELECT DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , 'LA002'
                 , ITEM_ID
                 , V_START_MONTH                           -- 조회 시작일자
              FROM ( SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , R.ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                       FROM GT_SCP0049_STD_ITEM R

                     MINUS

                     SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , R.ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                       FROM GT_SCP0049_LTY R
                      WHERE R.LOSS_CODE = 'LA002'
                   ) IA;

            -- TACT TIME 공정 인 경우 DAILY CAPA 도 보여주기 위한 처리
            INSERT INTO GT_SCP0049_LTY
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , YYYYMM )
            SELECT DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , LOSS_CODE                               --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시
                 , ITEM_ID
                 , V_START_MONTH                           -- 조회 시작일자
              FROM ( SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , R.ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                          , CASE WHEN LV.ATTRIBUTE1 = 'TACT TIME' THEN 'LA999' ELSE 'LA998' END AS LOSS_CODE   --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시
                       FROM GT_SCP0049_LTY        R
                          , SCM_SYS_LOOKUP_VALUE_SN LV     -- 2020/11/18, khj79
                      WHERE 1 = 1
                        AND R.PLANT_ID     = LV.SEGMENT2
                        AND R.OPERATION_ID = LV.SEGMENT3
                        AND LV.LOOKUP_TYPE_CODE = 'CAPA_UI_CAPA_DEFINIT'
                        AND LV.SEGMENT1         = 'LA002'
                        AND LV.ACTIVE_FLAG      = 'Y'
                        --AND LV.ATTRIBUTE1     = 'TACT TIME'
                        AND R.LOSS_CODE         = 'LA002'  --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시 : 버그 수정

                     MINUS

                     SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , R.ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                          , R.LOSS_CODE                    --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시
                       FROM GT_SCP0049_LTY R
                      WHERE R.LOSS_CODE IN ('LA999', 'LA998')   --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시
                   ) IA;
         END IF;

         IF P_CHECK_YIELD = 'Y' THEN
            INSERT INTO GT_SCP0049_LTY
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , YYYYMM )
            SELECT DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , 'LA003'
                 , ITEM_ID
                 , V_START_MONTH                           -- 조회 시작일자
              FROM ( SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , '-'  AS ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                       FROM GT_SCP0049_STD_ITEM R

                     MINUS

                     SELECT DISTINCT
                            R.DIVISION_ID
                          , R.COMPANY_ID
                          , R.SITE_ID
                          , R.PLANT_ID
                          , R.FACTORY_ID
                          , R.LINE_ID
                          , '-'  AS ELECTRODE_TYPE
                          , R.OPERATION_ID
                          , R.ITEM_ID
                       FROM GT_SCP0049_LTY R
                      WHERE R.LOSS_CODE = 'LA003'
                   ) IA;
         END IF;

         /* AS-IS #TMP_SCP0049_NOT_LA_VER 는 한 번만 참조하므로 인라인 뷰로 옮긴다 */
         IF P_CHECK_EMPTY = 'Y' THEN
            INSERT INTO GT_SCP0049_LTY_RESULT
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , LANE_QTY
                      , YYYYMMDD
                      , YYYYMM
                      , YYYY
                      , ITEM_VALUE )
            SELECT A.DIVISION_ID
                 , A.COMPANY_ID
                 , A.SITE_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.LINE_ID
                 , A.ELECTRODE_TYPE
                 , A.OPERATION_ID
                 , A.LOSS_CODE
                 , A.ITEM_ID
                 , A.LANE_QTY
                 , A.YYYYMMDD
                 , A.YYYYMM
                 , A.YYYY
                 , A.ITEM_VALUE
              FROM GT_SCP0049_LTY A
             WHERE NOT EXISTS
                   ( SELECT 1
                       FROM ( /* AS-IS #TMP_SCP0049_NOT_LA_VER */
                              SELECT IB.DIVISION_ID
                                   , IB.COMPANY_ID
                                   , IB.SITE_ID
                                   , IB.PLANT_ID
                                   , IB.FACTORY_ID
                                   , IB.LINE_ID
                                   , IB.ELECTRODE_TYPE
                                   , IB.OPERATION_ID
                                   , IC.LOSS_CODE
                                   , IB.ITEM_ID
                                FROM ( SELECT 'X' AS J_KEY
                                            , DIVISION_ID
                                            , COMPANY_ID
                                            , SITE_ID
                                            , PLANT_ID
                                            , FACTORY_ID
                                            , LINE_ID
                                            , ELECTRODE_TYPE
                                            , OPERATION_ID
                                            , LOSS_CODE
                                            , ITEM_ID
                                            , ITEM_VALUE
                                            , YYYYMM
                                         FROM GT_SCP0049_LTY
                                     ) IB
                                   , ( SELECT 'X' AS J_KEY
                                            , LOSS_CODE
                                         FROM GT_SCP0049_LOOKUP
                                        WHERE ( ( P_CHECK_TACT  = 'Y' AND LOSS_CODE = 'LA002' )
                                             OR ( P_CHECK_YIELD = 'Y' AND LOSS_CODE = 'LA003' ) )
                                     ) IC
                               WHERE IB.J_KEY      = IC.J_KEY(+)
                                 AND IB.LOSS_CODE  = 'LA001'
                                 AND IB.ITEM_VALUE = 9.0
                                 AND IB.YYYYMM IS NOT NULL
                            GROUP BY IB.DIVISION_ID
                                   , IB.COMPANY_ID
                                   , IB.SITE_ID
                                   , IB.PLANT_ID
                                   , IB.FACTORY_ID
                                   , IB.LINE_ID
                                   , IB.ELECTRODE_TYPE
                                   , IB.OPERATION_ID
                                   , IC.LOSS_CODE
                                   , IB.ITEM_ID
                              HAVING COUNT(1) = V_MONTH_CNT

                              UNION ALL

                              SELECT DIVISION_ID
                                   , COMPANY_ID
                                   , SITE_ID
                                   , PLANT_ID
                                   , FACTORY_ID
                                   , LINE_ID
                                   , ELECTRODE_TYPE
                                   , OPERATION_ID
                                   , LOSS_CODE
                                   , ITEM_ID
                                FROM GT_SCP0049_LTY
                               WHERE LOSS_CODE   = 'LA002'
                                 AND ITEM_VALUE  > 0
                                 AND YYYYMM IS NOT NULL
                                 AND P_CHECK_TACT = 'Y'
                            GROUP BY DIVISION_ID
                                   , COMPANY_ID
                                   , SITE_ID
                                   , PLANT_ID
                                   , FACTORY_ID
                                   , LINE_ID
                                   , ELECTRODE_TYPE
                                   , OPERATION_ID
                                   , LOSS_CODE
                                   , ITEM_ID
                              HAVING COUNT(1) = V_MONTH_CNT

                              UNION ALL

                              SELECT DIVISION_ID
                                   , COMPANY_ID
                                   , SITE_ID
                                   , PLANT_ID
                                   , FACTORY_ID
                                   , LINE_ID
                                   , ELECTRODE_TYPE
                                   , OPERATION_ID
                                   , LOSS_CODE
                                   , ITEM_ID
                                FROM GT_SCP0049_LTY
                               WHERE LOSS_CODE    = 'LA003'
                                 AND ITEM_VALUE   > 0
                                 AND YYYYMM IS NOT NULL
                                 AND P_CHECK_YIELD = 'Y'
                            GROUP BY DIVISION_ID
                                   , COMPANY_ID
                                   , SITE_ID
                                   , PLANT_ID
                                   , FACTORY_ID
                                   , LINE_ID
                                   , ELECTRODE_TYPE
                                   , OPERATION_ID
                                   , LOSS_CODE
                                   , ITEM_ID
                              HAVING COUNT(1) = V_MONTH_CNT
                            ) SA
                      WHERE SA.DIVISION_ID  = A.DIVISION_ID
                        AND SA.COMPANY_ID   = A.COMPANY_ID
                        AND SA.SITE_ID      = A.SITE_ID
                        AND SA.PLANT_ID     = A.PLANT_ID
                        AND SA.FACTORY_ID   = A.FACTORY_ID
                        AND SA.OPERATION_ID = A.OPERATION_ID
                        AND SA.LINE_ID      = A.LINE_ID
                        AND SA.ITEM_ID      = A.ITEM_ID
                        AND SA.LOSS_CODE    = CASE WHEN A.LOSS_CODE IN ('LA999', 'LA998') THEN 'LA002' ELSE A.LOSS_CODE END   --E20260629-000313 DAILY_CAPA/TACT_TIME 둘다 항상 표시
                   );
         ELSE
            INSERT INTO GT_SCP0049_LTY_RESULT
                      ( DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , LINE_ID
                      , ELECTRODE_TYPE
                      , OPERATION_ID
                      , LOSS_CODE
                      , ITEM_ID
                      , LANE_QTY
                      , YYYYMMDD
                      , YYYYMM
                      , YYYY
                      , ITEM_VALUE )
            SELECT DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , LOSS_CODE
                 , ITEM_ID
                 , LANE_QTY
                 , YYYYMMDD
                 , YYYYMM
                 , YYYY
                 , ITEM_VALUE
              FROM GT_SCP0049_LTY;
         END IF;

         /* /////////////////////////////////////////////////////////////////////////////// */
         /* 데이터 합치기                                                                   */
         /* /////////////////////////////////////////////////////////////////////////////// */
         INSERT INTO GT_SCP0049_ALL
                   ( DIVISION_ID
                   , COMPANY_ID
                   , SITE_ID
                   , PLANT_ID
                   , FACTORY_ID
                   , LINE_ID
                   , ELECTRODE_TYPE
                   , OPERATION_ID
                   , LOSS_CODE
                   , ITEM_ID
                   , LANE_QTY
