         /* ///////////////////////////////// XA001 데이터 넣기 날짜별 생성 //////////////// */
         INSERT INTO GT_SCP0049_ALL
                   ( COMPANY_ID
                   , DIVISION_ID
                   , SITE_ID
                   , PLANT_ID
                   , FACTORY_ID
                   , OPERATION_ID
                   , LINE_ID
                   , ELECTRODE_TYPE
                   , LOSS_CODE
                   , ITEM_ID
                   , YYYYMMDD
                   , YYYYMM
