              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , MONTH
              , PRIORITY
              , LANE_QTY
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , IA.BASIS_YYYYMM
         , TO_CHAR(NVL(TRUNC(ROUND(TO_NUMBER(A.DAY_QTY), 10)), 0))
         , NVL(CASE WHEN TRIM(A.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(A.LANE_QTY), 10) END, 0)
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_SAVE_DATA A
         , (SELECT DISTINCT BASIS_YYYYMM
                 , CALENDAR_YYYY
              FROM SCM_SYS_CALENDAR_M
           ) IA
     WHERE CASE WHEN A.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                WHEN A.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
            END                = A.DAY_NAME
       AND A.DATA_TABLE        = 'LA'                      -- SCM_ITEM_LINE_ASSIGN_M
       AND A.DATA_TYPE        IN ( 'M' , 'Y')
       AND A.OPERATION_ID     IN ('E2000')
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_ITEM_LINE_ASSIGN_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                          AND NVL(XA.LANE_QTY, 0) = NVL(CASE WHEN TRIM(A.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(A.LANE_QTY), 10) END, 0)
                          AND XA.MONTH           = IA.BASIS_YYYYMM
                      )
    ;

    -- 전극 line assign 저장시 없는 환산자 use 정보 추가 저장... 20230313
    INSERT INTO SCM_MST_ITEM_CONV_CALC_USE_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , MODEL_ID
              , ITEM_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , VERSION
              , ACTIVE_FLAG
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT SA.COMPANY_ID
         , SA.DIVISION_ID
         , SA.SITE_ID
         , SA.PLANT_ID
         , SA.FACTORY_ID
         , SA.OPERATION_ID
         , SA.MODEL_ID
         , SA.ITEM_ID
         , SA.LINE_ID
         , SA.ELECTRODE_TYPE
         , SA.VERSION
         , 'Y'
         , NULL
         , SA.UPDATE_ID
         , SYSDATE
         , SA.UPDATE_ID
         , SYSDATE
      FROM (SELECT DISTINCT
                   IA.COMPANY_ID
                 , IA.DIVISION_ID
                 , IA.SITE_ID
                 , IA.PLANT_ID
                 , IA.FACTORY_ID
                 , IA.OPERATION_ID
                 , IB.MODEL_ID
                 , IA.ITEM_ID
                 , IA.LINE_ID
                 , IA.ELECTRODE_TYPE
                 , IB.VERSION
                 , IA.UPDATE_ID
              FROM (SELECT DISTINCT
                           A.COMPANY_ID
                         , A.DIVISION_ID
                         , A.SITE_ID
                         , A.PLANT_ID
                         , A.FACTORY_ID
                         , A.OPERATION_ID
                         , A.ITEM_ID
                         , A.LINE_ID
                         , A.ELECTRODE_TYPE
                         , B.UPDATE_ID
                      FROM SCM_MST_ITEM_LINE_ASSIGN_SN A
                         , GT_SCP0049_SAVE_DATA B
                     WHERE A.COMPANY_ID     = B.COMPANY_ID
                       AND A.DIVISION_ID    = B.DIVISION_ID
                       AND A.SITE_ID        = B.SITE_ID
                       AND A.PLANT_ID       = B.PLANT_ID
                       AND A.FACTORY_ID     = B.FACTORY_ID
                       AND A.ITEM_ID        = B.ITEM_ID
                       AND A.OPERATION_ID   = B.OPERATION_ID
                       AND A.LINE_ID        = B.LINE_ID
                       AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
                       AND A.MONTH          = V_YYYYMM
                       AND A.ACTIVE_FLAG    = 'Y'
                       AND A.PRIORITY      IN ('1','2','3','4','5','6','7','8')
                       AND A.OPERATION_ID   = 'E2000'
                       AND B.DATA_TABLE     = 'LA'         -- SCM_ITEM_LINE_ASSIGN_M
                       AND B.DATA_TYPE     IN ( 'M' , 'Y')
                   ) IA
                 , (SELECT DISTINCT
                           C.COMPANY_ID
                         , C.DIVISION_ID
                         , C.SITE_ID
                         , C.PLANT_ID
                         , C.FACTORY_ID
                         , C.OPERATION    AS OPERATION_ID
                         , C.MODEL_ID
                         , C.ITEM_ID
                         , C.VERSION
                         , C.PROD_VERSION_TYPE
                         , C.MAX_VER_FLAG
                         , C.VERSION_TYPE
                      FROM SCM_MST_ITEM_CONV_CALC_SN C
                         , GT_SCP0049_SAVE_DATA D
                     WHERE C.COMPANY_ID     = D.COMPANY_ID
                       AND C.FACTORY_ID     = D.FACTORY_ID
                       AND C.OPERATION      = D.OPERATION_ID
                       AND C.ITEM_ID        = D.ITEM_ID
                       AND C.OPERATION      = 'E2000'
                       AND C.CATEGORY      IN ( 'cell/batch', 'Jumbo Roll (cell/m)', 'Jumbo Roll (m/batch)', 'Lane Number', 'Pancake (cell/m)', 'Pancake (m/batch)' )
                       AND D.DATA_TABLE     = 'LA'         -- SCM_ITEM_LINE_ASSIGN_M
                       AND D.DATA_TYPE     IN ( 'M' , 'Y')
                   ) IB
                 , SCM_LINE_M_SN E
             WHERE IA.COMPANY_ID       = IB.COMPANY_ID
               AND IA.DIVISION_ID      = IB.DIVISION_ID
               AND IA.SITE_ID          = IB.SITE_ID
               AND IA.PLANT_ID         = IB.PLANT_ID
               AND IA.FACTORY_ID       = IB.FACTORY_ID
               AND IA.OPERATION_ID     = IB.OPERATION_ID
               AND IA.ITEM_ID          = IB.ITEM_ID
               AND IA.COMPANY_ID       = E.COMPANY_ID
               AND IA.DIVISION_ID      = E.DIVISION_ID
               AND IA.SITE_ID          = E.SITE_ID
               AND IA.PLANT_ID         = E.PLANT_ID
               AND IA.FACTORY_ID       = E.FACTORY_ID
               AND IA.OPERATION_ID     = E.OPERATION_ID
               AND IA.LINE_ID          = E.LINE_ID
               AND IA.ELECTRODE_TYPE   = E.ELECTRODE_TYPE
               AND IB.PROD_VERSION_TYPE = E.PROD_VERSION_TYPE
           ) SA
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MST_ITEM_CONV_CALC_USE_SN XA
                        WHERE XA.FACTORY_ID      = SA.FACTORY_ID
                          AND XA.MODEL_ID        = SA.MODEL_ID
                          AND XA.ITEM_ID         = SA.ITEM_ID
                          AND XA.LINE_ID         = SA.LINE_ID
                          AND XA.ELECTRODE_TYPE  = SA.ELECTRODE_TYPE
                          AND XA.VERSION         = SA.VERSION
                      )
    ;

    -- pancake master 에 lane 값 동기화...기존 lane 삭제 ... 20230331
    DELETE FROM GT_SCP0049_LANE_SYNC;

