    /* ############################################################ */
    -- 1. LINE ASSIGN 정보의 일별 데이터를 추가/수정 한다.
    -- 2. 월,년 데이터 수정은 별도의 테이블에 저장한다.
    -- 3. LINE ASSIGN 은 LANE QTY 때문에 OPERATION 분리하여 수정한다.
    /* ############################################################ */
    --IF @v_line_cnt > 0
    -- LANE QTY 가 존재하는 공정(E2000, E3000, E4000)
    UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
       SET ( PRIORITY
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT TO_CHAR(NVL(TRUNC(ROUND(TO_NUMBER(B.DAY_QTY), 10)), 0))
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_SAVE_DATA B
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                   AND NVL(A.LANE_QTY, 0) = NVL(CASE WHEN TRIM(B.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(B.LANE_QTY), 10) END, 0)
                   AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
                   AND B.DATA_TABLE       = 'LA'           -- SCM_ITEM_LINE_ASSIGN_M
                   AND B.DATA_TYPE        = 'D'            -- DAY
                   AND B.OPERATION_ID    IN ('E2000')
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_SAVE_DATA XA
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                      AND NVL(A.LANE_QTY, 0) = NVL(CASE WHEN TRIM(XA.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(XA.LANE_QTY), 10) END, 0)
                      AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = XA.DAY_NAME
                      AND XA.DATA_TABLE     = 'LA'         -- SCM_ITEM_LINE_ASSIGN_M
                      AND XA.DATA_TYPE      = 'D'          -- DAY
                      AND XA.OPERATION_ID  IN ('E2000')
                  )
    ;

    INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , LANE_QTY
              , START_TIME
              , END_TIME
              , PRIORITY
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , NVL(CASE WHEN TRIM(A.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(A.LANE_QTY), 10) END, 0)
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_CHAR(NVL(TRUNC(ROUND(TO_NUMBER(A.DAY_QTY), 10)), 0))
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_SAVE_DATA A
     WHERE A.DATA_TABLE     = 'LA'                         -- SCM_ITEM_LINE_ASSIGN_M
       AND A.DATA_TYPE      = 'D'                          -- DAY
       AND A.OPERATION_ID  IN ('E2000')
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                          AND NVL(XA.LANE_QTY, 0) = NVL(CASE WHEN TRIM(A.LANE_QTY) IS NULL THEN 0.0 ELSE ROUND(TO_NUMBER(A.LANE_QTY), 10) END, 0)
                          AND TO_CHAR(XA.START_TIME, 'YYYYMMDD') = A.DAY_NAME
                      )
    ;

    -- LANE QTY 가 존재하지 않는 공정(E2000, E3000, E4000)
    UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
       SET ( PRIORITY
           , LANE_QTY
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT TO_CHAR(NVL(TRUNC(ROUND(TO_NUMBER(B.DAY_QTY), 10)), 0))
                     , 0
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_SAVE_DATA B
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                   AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
                   AND B.DATA_TABLE       = 'LA'           -- SCM_ITEM_LINE_ASSIGN_M
                   AND B.DATA_TYPE        = 'D'            -- DAY
                   AND B.OPERATION_ID NOT IN ('E2000')
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_SAVE_DATA XA
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                      AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = XA.DAY_NAME
                      AND XA.DATA_TABLE     = 'LA'         -- SCM_ITEM_LINE_ASSIGN_M
                      AND XA.DATA_TYPE      = 'D'          -- DAY
                      AND XA.OPERATION_ID NOT IN ('E2000')
                  )
    ;

    INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , LANE_QTY
              , START_TIME
              , END_TIME
              , PRIORITY
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , 0
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_CHAR(NVL(TRUNC(ROUND(TO_NUMBER(A.DAY_QTY), 10)), 0))
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_SAVE_DATA A
     WHERE A.DATA_TABLE      = 'LA'                        -- SCM_ITEM_LINE_ASSIGN_M
       AND A.DATA_TYPE       = 'D'                         -- DAY
       AND A.OPERATION_ID NOT IN ('E2000')
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                          AND TO_CHAR(XA.START_TIME, 'YYYYMMDD') = A.DAY_NAME
                      )
    ;

    /* ############################################################ */
    -- 1. TACT TIME, DAILY CAPA  정보의 월,년도 데이터를 추가/저장 한다.
    -- 2. 일별 데이터 수정은 별도의 테이블에 저장한다.
    -- 3. TACT TIME 정보를 수정 했을 때 DAILY CAPA 값을 산출해서 저장한다.
    -- 4. DAILY CAPA 정보를 수정 했을 때 TACT TIME 값을 산출해서 저장한다.
    -- 5. TACT TIME 과 DAILY CAPA 데이터 산출을 위해 LOSS 테이블의 조회 후 임시 테이블에 저장한다.
    /* ############################################################ */
    --IF @v_tact_cnt > 0
    -- LOSS UTIL 산출 임시 테이블 저장
    INSERT INTO GT_SCP0049_SAVE_LOSS_UTIL_TACT
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , WORK_MONTH
              , LOSS_UTIL
              )
    SELECT SA.COMPANY_ID
         , SA.DIVISION_ID
         , SA.SITE_ID
         , SA.PLANT_ID
         , SA.FACTORY_ID
         , SA.OPERATION_ID
         , SA.LINE_ID
         , SA.ELECTRODE_TYPE
         , SA.WORK_MONTH
         --, ROUND(EXP(SUM(ROUND(LOG(1-ISNULL(L.LOSS_RATE,0)),4))),4) AS LOSS_UTIL
         , 1 - ROUND(SUM(NVL(B.LOSS_RATE, 0)), 4)          AS UTIL
      FROM (SELECT DISTINCT
                   A.COMPANY_ID
                 , A.DIVISION_ID
                 , A.SITE_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.ELECTRODE_TYPE
                 , IA.BASIS_YYYYMM      AS WORK_MONTH
              FROM GT_SCP0049_SAVE_DATA A
                 , (SELECT BASIS_YYYYMM
                         , CALENDAR_YYYY
                         , BASIS_YYYYMMDD
                      FROM SCM_SYS_CALENDAR_M
                   ) IA
             WHERE CASE WHEN A.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                        WHEN A.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
                        WHEN A.DATA_TYPE = 'D' THEN IA.BASIS_YYYYMMDD
                    END            = A.DAY_NAME
               AND A.DATA_TABLE     = 'T'                  --  SCM_TACT_TIME_M
               AND A.DATA_TYPE     IN ('Y','M','D')        -- YEAR , MONTH , DAY
            ) SA
         , SCM_LOSS_M_SN B
         , (SELECT SEGMENT1  AS LOSS_CODE
              FROM SCM_SYS_LOOKUP_VALUE_SN
             WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
               AND ATTRIBUTE5       = 'Y'
           ) IB
     WHERE B.COMPANY_ID       = SA.COMPANY_ID
       AND B.DIVISION_ID      = SA.DIVISION_ID
       AND B.SITE_ID          = SA.SITE_ID
       AND B.PLANT_ID         = SA.PLANT_ID
       AND B.FACTORY_ID       = SA.FACTORY_ID
       AND B.OPERATION_ID     = SA.OPERATION_ID
       AND B.LINE_ID          = SA.LINE_ID
       AND B.ELECTRODE_TYPE   = SA.ELECTRODE_TYPE
       AND B.WORK_MONTH       = SA.WORK_MONTH
       AND B.LOSS_CODE        = IB.LOSS_CODE
     GROUP BY SA.COMPANY_ID
            , SA.DIVISION_ID
            , SA.SITE_ID
            , SA.PLANT_ID
            , SA.FACTORY_ID
            , SA.OPERATION_ID
            , SA.LINE_ID
            , SA.ELECTRODE_TYPE
            , SA.WORK_MONTH
    ;

    -- 데이터 추가/수정
    /* 원천을 GTT 에 적재(UPDATE·INSERT 두 번 이상 참조) */
    INSERT INTO GT_SCP0049_TACT_MM
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , WORK_MONTH
              , UPDATE_ID
              , QTY_TACT
              , QTY_DAILY
              )
    SELECT IC.COMPANY_ID
         , IC.DIVISION_ID
         , IC.SITE_ID
         , IC.PLANT_ID
         , IC.FACTORY_ID
         , IC.ITEM_ID
         , IC.OPERATION_ID
         , IC.LINE_ID
         , IC.ELECTRODE_TYPE
         , IC.WORK_MONTH
         , IC.UPDATE_ID
         , CASE WHEN IC.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(ROUND(TO_NUMBER(IC.DAY_QTY), 10), 0) = 0 THEN 0
                WHEN IC.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / ROUND(TO_NUMBER(IC.DAY_QTY), 10) * NVL(TO_NUMBER(IC.LOSS_UTIL), 1)
                ELSE ROUND(TO_NUMBER(IC.DAY_QTY), 10) END AS QTY_TACT
         , CASE WHEN IC.TACT_DATA_TYPE = 'TACT TIME' AND NVL(ROUND(TO_NUMBER(IC.DAY_QTY), 10), 0) = 0 THEN 0
                WHEN IC.TACT_DATA_TYPE = 'TACT TIME' AND NVL(ROUND(TO_NUMBER(IC.DAY_QTY), 10), 0) > 0 THEN ROUND(86400 / ROUND(TO_NUMBER(IC.DAY_QTY), 10) * NVL(TO_NUMBER(IC.LOSS_UTIL), 1), 0)
                ELSE ROUND(TO_NUMBER(IC.DAY_QTY), 10) END AS QTY_DAILY
      FROM (SELECT A.COMPANY_ID
                 , A.DIVISION_ID
                 , A.SITE_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.ELECTRODE_TYPE
                 , IA.BASIS_YYYYMM      AS WORK_MONTH
                 , A.DAY_QTY
                 , A.UPDATE_ID
                 , C.LOSS_UTIL
                 , IB.TACT_DATA_TYPE
              FROM GT_SCP0049_SAVE_DATA A
                 , (SELECT DISTINCT BASIS_YYYYMM
                          , CALENDAR_YYYY
                      FROM SCM_SYS_CALENDAR_M
                   ) IA
                 , (SELECT ATTRIBUTE1  AS TACT_DATA_TYPE
                         , SEGMENT2    AS PLANT_ID
                         , SEGMENT3    AS OPERATION_ID
                      FROM SCM_SYS_LOOKUP_VALUE_SN
                     WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_CAPA_DEFINIT'
                       AND SEGMENT1         = 'LA002'
                       AND ACTIVE_FLAG      = 'Y'
                   ) IB
                 , GT_SCP0049_SAVE_LOSS_UTIL_TACT C
             WHERE CASE WHEN A.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                        WHEN A.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
                    END                 = A.DAY_NAME
               AND A.PLANT_ID           = IB.PLANT_ID
               AND A.OPERATION_ID       = IB.OPERATION_ID
               AND A.COMPANY_ID         = C.COMPANY_ID(+)
               AND A.DIVISION_ID        = C.DIVISION_ID(+)
               AND A.SITE_ID            = C.SITE_ID(+)
               AND A.PLANT_ID           = C.PLANT_ID(+)
               AND A.FACTORY_ID         = C.FACTORY_ID(+)
               AND A.OPERATION_ID       = C.OPERATION_ID(+)
               AND A.LINE_ID            = C.LINE_ID(+)
               AND A.ELECTRODE_TYPE     = C.ELECTRODE_TYPE(+)
               AND A.DAY_NAME           = C.WORK_MONTH(+)
               AND A.DATA_TABLE         = 'T'              -- SCM_TACT_TIME_M
               AND A.DATA_TYPE         IN ( 'M' , 'Y')
            ) IC
    ;

    UPDATE SCM_MST_TACT_TIME_SN A
       SET ( TACT_TIME
           , DAILY_CAPA
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT B.QTY_TACT
                     , TRUNC(B.QTY_DAILY)
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_TACT_MM B
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                   AND A.MONTH            = B.WORK_MONTH
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_TACT_MM XA
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                      AND A.MONTH           = XA.WORK_MONTH
                  )
    ;

    INSERT INTO SCM_MST_TACT_TIME_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , MONTH
              , TACT_TIME
              , DAILY_CAPA
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.WORK_MONTH
         , A.QTY_TACT
         , TRUNC(A.QTY_DAILY)
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_TACT_MM A
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MST_TACT_TIME_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                          AND XA.MONTH           = A.WORK_MONTH
                      )
    ;

    /* ############################################################ */
    -- 1. TACT TIME, DAILY CAPA  정보의 일별 데이터를 추가/저장 한다.
    -- 2. 월별 년도별 데이터 수정은 별도의 테이블에 저장한다.
    -- 3. TACT TIME 정보를 수정 했을 때 DAILY CAPA 값을 산출해서 저장한다.
    -- 4. DAILY CAPA 정보를 수정 했을 때 TACT TIME 값을 산출해서 저장한다.
    -- 5. TACT TIME 과 DAILY CAPA 데이터 산출을 위해 LOSS 테이블의 조회 후 임시 테이블에 저장한다.
    /* ############################################################ */
    --IF @v_tact_cnt > 0
    -- 데이터 저장
    INSERT INTO GT_SCP0049_TACT_DD
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , DAY_NAME
              , UPDATE_ID
              , QTY_TACT
              , QTY_DAILY
              )
    SELECT IB.COMPANY_ID
         , IB.DIVISION_ID
         , IB.SITE_ID
         , IB.PLANT_ID
         , IB.FACTORY_ID
         , IB.ITEM_ID
         , IB.OPERATION_ID
         , IB.LINE_ID
         , IB.ELECTRODE_TYPE
         , IB.DAY_NAME
         , IB.UPDATE_ID
         , CASE WHEN IB.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(ROUND(TO_NUMBER(IB.DAY_QTY), 10), 0) = 0 THEN 0
                WHEN IB.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / ROUND(TO_NUMBER(IB.DAY_QTY), 10) * NVL(TO_NUMBER(IB.LOSS_UTIL), 1)
                ELSE ROUND(TO_NUMBER(IB.DAY_QTY), 10) END AS QTY_TACT
         , CASE WHEN IB.TACT_DATA_TYPE = 'TACT TIME' AND NVL(ROUND(TO_NUMBER(IB.DAY_QTY), 10), 0) = 0 THEN 0
                WHEN IB.TACT_DATA_TYPE = 'TACT TIME' AND NVL(ROUND(TO_NUMBER(IB.DAY_QTY), 10), 0) > 0 THEN ROUND(86400 / ROUND(TO_NUMBER(IB.DAY_QTY), 10) * NVL(TO_NUMBER(IB.LOSS_UTIL), 1), 0)
                ELSE ROUND(TO_NUMBER(IB.DAY_QTY), 10) END AS QTY_DAILY
      FROM (SELECT A.COMPANY_ID
                 , A.DIVISION_ID
                 , A.SITE_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.ITEM_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.ELECTRODE_TYPE
                 , A.DAY_NAME
                 , A.DAY_QTY
                 , A.UPDATE_ID
                 , C.LOSS_UTIL
                 , IA.TACT_DATA_TYPE
              FROM GT_SCP0049_SAVE_DATA A
                 , (SELECT ATTRIBUTE1  AS TACT_DATA_TYPE
                         , SEGMENT2    AS PLANT_ID
                         , SEGMENT3    AS OPERATION_ID
                      FROM SCM_SYS_LOOKUP_VALUE_SN                   -- 2020/11/18, khj79
                     WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_CAPA_DEFINIT'
                       AND SEGMENT1         = 'LA002'
                       AND ACTIVE_FLAG      = 'Y'
                   ) IA
                 , GT_SCP0049_SAVE_LOSS_UTIL_TACT C
             WHERE A.PLANT_ID             = IA.PLANT_ID
               AND A.OPERATION_ID         = IA.OPERATION_ID
               AND A.COMPANY_ID           = C.COMPANY_ID(+)
               AND A.DIVISION_ID          = C.DIVISION_ID(+)
               AND A.SITE_ID              = C.SITE_ID(+)
               AND A.PLANT_ID             = C.PLANT_ID(+)
               AND A.FACTORY_ID           = C.FACTORY_ID(+)
               AND A.OPERATION_ID         = C.OPERATION_ID(+)
               AND A.LINE_ID              = C.LINE_ID(+)
               AND A.ELECTRODE_TYPE       = C.ELECTRODE_TYPE(+)
               AND SUBSTR(A.DAY_NAME,1,6) = C.WORK_MONTH(+)
               AND A.DATA_TABLE           = 'T'            -- SCM_TACT_TIME_M
               AND A.DATA_TYPE            = 'D'
            ) IB
    ;

    UPDATE SCM_MST_TACT_TIME_EXCEPT_SN A
       SET ( TACT_TIME
           , DAILY_CAPA
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT B.QTY_TACT
                     , TRUNC(B.QTY_DAILY)
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_TACT_DD B
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                   AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_TACT_DD XA
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                      AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = XA.DAY_NAME
                  )
    ;

    INSERT INTO SCM_MST_TACT_TIME_EXCEPT_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , START_TIME
              , END_TIME
              , TACT_TIME
              , DAILY_CAPA
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , A.QTY_TACT
         , TRUNC(A.QTY_DAILY)
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_TACT_DD A
     WHERE NOT EXISTS (SELECT 1
                         FROM SCM_MST_TACT_TIME_EXCEPT_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                          AND TO_CHAR(XA.START_TIME, 'YYYYMMDD') = A.DAY_NAME
                      )
    ;

    /* ############################################################ */
    -- 1. YIELD 정보의 월,년도 데이터를 추가/수정 한다.
    -- 2. 일별 데이터 수정은 별도의 테이블에 저장한다.
    /* ############################################################ */
    --IF @v_yield_cnt > 0
    UPDATE SCM_MST_YIELD_SN A
       SET ( YIELD
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT ROUND(TO_NUMBER(B.DAY_QTY), 6) / 100
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_SAVE_DATA B
                     , (SELECT DISTINCT BASIS_YYYYMM
                             , CALENDAR_YYYY
                          FROM SCM_SYS_CALENDAR_M
                       ) IA
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND A.MONTH            = IA.BASIS_YYYYMM
                   AND CASE WHEN B.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                            WHEN B.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
                       END                = B.DAY_NAME
                   AND B.DATA_TABLE       = 'Y'            -- SCM_YIELD_M
                   AND B.DATA_TYPE       IN ( 'M' , 'Y')
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_SAVE_DATA XA
                        , (SELECT DISTINCT BASIS_YYYYMM
                                , CALENDAR_YYYY
                             FROM SCM_SYS_CALENDAR_M
                          ) XB
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND A.MONTH           = XB.BASIS_YYYYMM
                      AND CASE WHEN XA.DATA_TYPE = 'Y' THEN XB.CALENDAR_YYYY
                               WHEN XA.DATA_TYPE = 'M' THEN XB.BASIS_YYYYMM
                          END               = XA.DAY_NAME
                      AND XA.DATA_TABLE     = 'Y'          -- SCM_YIELD_M
                      AND XA.DATA_TYPE     IN ( 'M' , 'Y')
                  )
    ;

    INSERT INTO SCM_MST_YIELD_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , MONTH
              , YIELD
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , IA.BASIS_YYYYMM
         , ROUND(TO_NUMBER(A.DAY_QTY), 6) / 100
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_SAVE_DATA A
         , (SELECT DISTINCT BASIS_YYYYMM
                 , CALENDAR_YYYY
              FROM SCM_SYS_CALENDAR_M
           ) IA
     WHERE CASE WHEN A.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                WHEN A.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
            END              = A.DAY_NAME
       AND A.DATA_TABLE       = 'Y'                        -- SCM_YIELD_M
       AND A.DATA_TYPE       IN ( 'M' , 'Y')
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_YIELD_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND XA.MONTH           = IA.BASIS_YYYYMM
                      )
    ;

    /* ############################################################ */
    -- 1. YIELD 정보의 일별 데이터를 추가/수정 한다.
    -- 2. 월,년 데이터 수정은 별도의 테이블에 저장한다.
    /* ############################################################ */
    --IF @v_yield_cnt > 0
    UPDATE SCM_MST_YIELD_EXCEPT_SN A
       SET ( YIELD
           , UPDATE_ID
           , UPDATE_TIME
           ) = (SELECT ROUND(TO_NUMBER(B.DAY_QTY), 10) / 100
                     , B.UPDATE_ID
                     , SYSDATE
                  FROM GT_SCP0049_SAVE_DATA B
                 WHERE A.COMPANY_ID       = B.COMPANY_ID
                   AND A.DIVISION_ID      = B.DIVISION_ID
                   AND A.SITE_ID          = B.SITE_ID
                   AND A.PLANT_ID         = B.PLANT_ID
                   AND A.FACTORY_ID       = B.FACTORY_ID
                   AND A.ITEM_ID          = B.ITEM_ID
                   AND A.OPERATION_ID     = B.OPERATION_ID
                   AND A.LINE_ID          = B.LINE_ID
                   AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
                   AND B.DATA_TABLE       = 'Y'            -- SCM_YIELD_M
                   AND B.DATA_TYPE        = 'D'
                   AND (CASE WHEN TRIM(B.DAY_QTY) IS NULL OR TRIM(B.DAY_QTY) = '0' THEN 0 ELSE ROUND(TO_NUMBER(B.DAY_QTY), 10) END) > 0 -- [E20240927-001617]Daily Yield 삭제 기능 추가
                   AND ROWNUM             = 1
               )
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_SAVE_DATA XA
                    WHERE A.COMPANY_ID      = XA.COMPANY_ID
                      AND A.DIVISION_ID     = XA.DIVISION_ID
                      AND A.SITE_ID         = XA.SITE_ID
                      AND A.PLANT_ID        = XA.PLANT_ID
                      AND A.FACTORY_ID      = XA.FACTORY_ID
                      AND A.ITEM_ID         = XA.ITEM_ID
                      AND A.OPERATION_ID    = XA.OPERATION_ID
                      AND A.LINE_ID         = XA.LINE_ID
                      AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = XA.DAY_NAME
                      AND XA.DATA_TABLE     = 'Y'          -- SCM_YIELD_M
                      AND XA.DATA_TYPE      = 'D'
                      AND (CASE WHEN TRIM(XA.DAY_QTY) IS NULL OR TRIM(XA.DAY_QTY) = '0' THEN 0 ELSE ROUND(TO_NUMBER(XA.DAY_QTY), 10) END) > 0
                  )
    ;

    INSERT INTO SCM_MST_YIELD_EXCEPT_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , START_TIME
              , END_TIME
              , YIELD
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.ITEM_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , TO_DATE(A.DAY_NAME, 'YYYYMMDD')
         , ROUND(TO_NUMBER(A.DAY_QTY), 10) / 100
         , A.UPDATE_ID
         , SYSDATE
         , A.UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_SAVE_DATA A
     WHERE A.DATA_TABLE = 'Y'                              -- SCM_YIELD_M
       AND A.DATA_TYPE  = 'D'
       AND (CASE WHEN TRIM(A.DAY_QTY) IS NULL OR TRIM(A.DAY_QTY) = '0' THEN 0 ELSE ROUND(TO_NUMBER(A.DAY_QTY), 10) END) > 0 -- [E20240927-001617]Daily Yield 삭제 기능 추가
       AND NOT EXISTS (SELECT 1
                         FROM SCM_MST_YIELD_EXCEPT_SN XA
                        WHERE XA.COMPANY_ID      = A.COMPANY_ID
                          AND XA.DIVISION_ID     = A.DIVISION_ID
                          AND XA.SITE_ID         = A.SITE_ID
                          AND XA.PLANT_ID        = A.PLANT_ID
                          AND XA.FACTORY_ID      = A.FACTORY_ID
                          AND XA.ITEM_ID         = A.ITEM_ID
                          AND XA.OPERATION_ID    = A.OPERATION_ID
                          AND XA.LINE_ID         = A.LINE_ID
                          AND TO_CHAR(XA.START_TIME, 'YYYYMMDD') = A.DAY_NAME
                      )
    ;

    -- [E20240927-001617]Daily Yield 삭제 기능 추가
    DELETE FROM SCM_MST_YIELD_EXCEPT_SN A
     WHERE EXISTS (SELECT 1
                     FROM GT_SCP0049_SAVE_DATA B
                    WHERE A.COMPANY_ID      = B.COMPANY_ID
                      AND A.DIVISION_ID     = B.DIVISION_ID
                      AND A.SITE_ID         = B.SITE_ID
                      AND A.PLANT_ID        = B.PLANT_ID
                      AND A.FACTORY_ID      = B.FACTORY_ID
                      AND A.ITEM_ID         = B.ITEM_ID
                      AND A.OPERATION_ID    = B.OPERATION_ID
                      AND A.LINE_ID         = B.LINE_ID
                      AND TO_CHAR(A.START_TIME, 'YYYYMMDD') = B.DAY_NAME
                      AND B.DATA_TABLE      = 'Y'          -- SCM_YIELD_M
                      AND B.DATA_TYPE       = 'D'
                      AND (CASE WHEN TRIM(B.DAY_QTY) IS NULL OR TRIM(B.DAY_QTY) = '0' THEN 0 ELSE ROUND(TO_NUMBER(B.DAY_QTY), 10) END) = 0
                  )
    ;

    /* ############################################################ */
    -- LINE ASSIGN 삭제(TACT TIME , YIELD 삭제 동기화)
    /* ############################################################ */
    INSERT INTO GT_SCP0049_DELETE
              ( P_DIVISION_ID
              , P_COMPANY_ID
              , P_SITE_ID
              , P_PLANT_ID
              , P_FACTORY_ID
              , P_LINE_ID
              , P_OPERATION_ID
              , P_ELECTRODE_TYPE
              , P_ITEM_ID
              , P_LOSS_CODE
              , P_DATA_TABLE
              , P_DATA_TYPE
              , P_DAY_NAME
              , P_DAY_QTY
              , P_LANE_QTY
              , P_CONFIRM_FLAG
              , P_UPDATE_ID
              )
    SELECT A.P_DIVISION_ID
         , A.P_COMPANY_ID
         , A.P_SITE_ID
         , A.P_PLANT_ID
         , A.P_FACTORY_ID
         , A.P_LINE_ID
         , A.P_OPERATION_ID
         , A.P_ELECTRODE_TYPE
         , A.P_ITEM_ID
         , A.P_LOSS_CODE
         , A.P_DATA_TABLE
         , A.P_DATA_TYPE
         , A.P_DAY_NAME
         , A.P_DAY_QTY
         , A.P_LANE_QTY
         , A.P_CONFIRM_FLAG
         , A.P_UPDATE_ID
      FROM GT_SCP0049_INC_VIRTAUL_LINE A                   -- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : @SCP0049를 @SCP0049_INC_VIRTAUL_LINE로 변경 적용 (Real+Virtual)
     WHERE A.P_DATA_TABLE = 'LA'
       AND A.P_DATA_TYPE <> 'LQ'
       AND NVL(TRUNC(ROUND(TO_NUMBER(A.P_DAY_QTY), 10)), 0) = 9
    ;

    /* AS-IS EXEC [dbo].[PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET] @SCP0049_DELETE 대응 */
    DELETE FROM GT_SCP0049_DS;

    INSERT INTO GT_SCP0049_DS
              ( P_DIVISION_ID
              , P_COMPANY_ID
              , P_SITE_ID
              , P_PLANT_ID
              , P_FACTORY_ID
              , P_LINE_ID
              , P_OPERATION_ID
              , P_ELECTRODE_TYPE
              , P_ITEM_ID
              , P_LOSS_CODE
              , P_DATA_TABLE
              , P_DATA_TYPE
              , P_DAY_NAME
              , P_DAY_QTY
              , P_LANE_QTY
              , P_CONFIRM_FLAG
              , P_UPDATE_ID
              )
    SELECT A.P_DIVISION_ID
         , A.P_COMPANY_ID
         , A.P_SITE_ID
         , A.P_PLANT_ID
         , A.P_FACTORY_ID
         , A.P_LINE_ID
         , A.P_OPERATION_ID
         , A.P_ELECTRODE_TYPE
         , A.P_ITEM_ID
         , A.P_LOSS_CODE
         , A.P_DATA_TABLE
         , A.P_DATA_TYPE
         , A.P_DAY_NAME
         , A.P_DAY_QTY
         , A.P_LANE_QTY
         , A.P_CONFIRM_FLAG
         , A.P_UPDATE_ID
      FROM GT_SCP0049_DELETE A
    ;

    P_CAPA_LINE_ASSIGN_DELETE_DATASET;

    /* ############################################################ */
    -- 1. LOSS 'No-Run' 데이터가 수정되면 TACT TIME 과 DAILY CAPA 산출 값이 달라진다.
    -- 2. SCM_MST_TACT_TIME_SN , SCM_MST_TACT_TIME_EXCEPT_SN 값을 수정한다.
    /* ############################################################ */
    --IF @v_loss_cnt > 0
    SELECT COUNT(1)
      INTO V_MOD_CNT
      FROM GT_SCP0049_SAVE_DATA
     WHERE DATA_TABLE = 'L'                                -- SCM_LOSS_M
       AND DATA_TYPE NOT IN ('CF','LQ')
       AND LOSS_CODE <> 'EL009'                            -- No-Run < Model Change 제외
    ;

    IF V_MOD_CNT > 0 THEN

        /* ############################################################ */
        -- 1. TACT TIME, DAILY CAPA  정보의 일별 데이터를 추가/저장 한다.
        -- 2. 월별 년도별 데이터 수정은 별도의 테이블에 저장한다.
        -- 3. TACT TIME 정보를 수정 했을 때 DAILY CAPA 값을 산출해서 저장한다.
        -- 4. DAILY CAPA 정보를 수정 했을 때 TACT TIME 값을 산출해서 저장한다.
        -- 5. TACT TIME 과 DAILY CAPA 데이터 산출을 위해 LOSS 테이블의 조회 후 임시 테이블에 저장한다.
        /* ############################################################ */

        -- LOSS UTIL 임시 테이블 저장
        INSERT INTO GT_SCP0049_SAVE_LOSS_UTIL_LOSS
                  ( COMPANY_ID
                  , DIVISION_ID
                  , SITE_ID
                  , PLANT_ID
                  , FACTORY_ID
                  , OPERATION_ID
                  , LINE_ID
                  , ELECTRODE_TYPE
                  , WORK_MONTH
                  , TACT_DATA_TYPE
                  , LOSS_UTIL
                  , UPDATE_ID
                  )
        SELECT SA.COMPANY_ID
             , SA.DIVISION_ID
             , SA.SITE_ID
             , SA.PLANT_ID
             , SA.FACTORY_ID
             , SA.OPERATION_ID
             , SA.LINE_ID
             , SA.ELECTRODE_TYPE
             , SA.WORK_MONTH
             , IC.TACT_DATA_TYPE
             --, ROUND(EXP(SUM(ROUND(LOG(1-ISNULL(L.LOSS_RATE,0)),4))),4) AS LOSS_UTIL
             , 1 - ROUND(SUM(NVL(B.LOSS_RATE, 0)), 4)      AS UTIL
             , SA.UPDATE_ID
          FROM (SELECT DISTINCT
                       A.COMPANY_ID
                     , A.DIVISION_ID
                     , A.SITE_ID
                     , A.PLANT_ID
                     , A.FACTORY_ID
                     , A.OPERATION_ID
                     , A.LINE_ID
                     , A.ELECTRODE_TYPE
                     , IA.BASIS_YYYYMM      AS WORK_MONTH
                     , A.UPDATE_ID
                  FROM GT_SCP0049_SAVE_DATA A
                     , (SELECT DISTINCT BASIS_YYYYMM
                              , CALENDAR_YYYY
                          FROM SCM_SYS_CALENDAR_M
                       ) IA
                 WHERE CASE WHEN A.DATA_TYPE = 'Y' THEN IA.CALENDAR_YYYY
                            WHEN A.DATA_TYPE = 'M' THEN IA.BASIS_YYYYMM
                        END              = A.DAY_NAME
                   AND A.DATA_TABLE       = 'L'            -- SCM_LOSS_M
                   AND A.DATA_TYPE NOT IN ('CF','LQ')
                   AND A.LOSS_CODE       <> 'EL009'        -- No-Run < Model Change 제외
                ) SA
             , SCM_LOSS_M_SN B                             -- LOSS UTIL 값 조회
             , (SELECT SEGMENT1  AS LOSS_CODE
                  FROM SCM_SYS_LOOKUP_VALUE_SN
                 WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                   AND ATTRIBUTE5       = 'Y'
               ) IB
             , (SELECT ATTRIBUTE1  AS TACT_DATA_TYPE
                     , SEGMENT2    AS PLANT_ID
                     , SEGMENT3    AS OPERATION_ID
                  FROM SCM_SYS_LOOKUP_VALUE_SN             -- TACT TIME , DAILY CAPA 조회
                 WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_CAPA_DEFINIT'
                   AND SEGMENT1         = 'LA002'
                   AND ACTIVE_FLAG      = 'Y'
               ) IC
         WHERE B.COMPANY_ID       = SA.COMPANY_ID
           AND B.DIVISION_ID      = SA.DIVISION_ID
           AND B.SITE_ID          = SA.SITE_ID
           AND B.PLANT_ID         = SA.PLANT_ID
           AND B.FACTORY_ID       = SA.FACTORY_ID
           AND B.OPERATION_ID     = SA.OPERATION_ID
           AND B.LINE_ID          = SA.LINE_ID
           AND B.ELECTRODE_TYPE   = SA.ELECTRODE_TYPE
           AND B.WORK_MONTH       = SA.WORK_MONTH
           AND B.LOSS_CODE        = IB.LOSS_CODE
           AND SA.PLANT_ID        = IC.PLANT_ID
           AND SA.OPERATION_ID    = IC.OPERATION_ID
         GROUP BY SA.COMPANY_ID
                , SA.DIVISION_ID
                , SA.SITE_ID
                , SA.PLANT_ID
                , SA.FACTORY_ID
                , SA.OPERATION_ID
                , SA.LINE_ID
                , SA.ELECTRODE_TYPE
                , SA.WORK_MONTH
                , IC.TACT_DATA_TYPE
                , SA.UPDATE_ID
        ;

        /* ############################################################ */
        -- 이력저장
        /* ############################################################ */
        INSERT INTO GT_SCP0049_LOSS
                  ( P_DATA_TABLE
                  , P_DATA_TYPE
                  , P_DIVISION_ID
                  , P_COMPANY_ID
                  , P_SITE_ID
                  , P_PLANT_ID
                  , P_FACTORY_ID
                  , P_LINE_ID
                  , P_ELECTRODE_TYPE
                  , P_OPERATION_ID
                  , P_ITEM_ID
                  , P_DAY_NAME
                  , P_UPDATE_ID
                  )
        SELECT 'T'                AS DATA_TABLE
             , 'M'                AS DATA_TYPE
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.LINE_ID
             , B.ELECTRODE_TYPE
             , B.OPERATION_ID
             , B.ITEM_ID          AS ITEM_ID
             , A.WORK_MONTH       AS DAY_NAME
             , A.UPDATE_ID
          FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS A
             , SCM_MST_TACT_TIME_SN B
         WHERE B.COMPANY_ID       = A.COMPANY_ID
           AND B.DIVISION_ID      = A.DIVISION_ID
           AND B.SITE_ID          = A.SITE_ID
           AND B.PLANT_ID         = A.PLANT_ID
           AND B.FACTORY_ID       = A.FACTORY_ID
           AND B.OPERATION_ID     = A.OPERATION_ID
           AND B.LINE_ID          = A.LINE_ID
           AND B.ELECTRODE_TYPE   = A.ELECTRODE_TYPE
           AND B.MONTH            = A.WORK_MONTH
        ;

        INSERT INTO GT_SCP0049_LOSS
                  ( P_DATA_TABLE
                  , P_DATA_TYPE
                  , P_DIVISION_ID
                  , P_COMPANY_ID
                  , P_SITE_ID
                  , P_PLANT_ID
                  , P_FACTORY_ID
                  , P_LINE_ID
                  , P_ELECTRODE_TYPE
                  , P_OPERATION_ID
                  , P_ITEM_ID
                  , P_DAY_NAME
                  , P_UPDATE_ID
                  )
        SELECT 'T'                AS DATA_TABLE
             , 'D'                AS DATA_TYPE
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.LINE_ID
             , B.ELECTRODE_TYPE
             , B.OPERATION_ID
             , B.ITEM_ID                              AS ITEM_ID
             , TO_CHAR(B.START_TIME, 'YYYYMMDD')      AS DAY_NAME
             , A.UPDATE_ID
          FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS A
             , SCM_MST_TACT_TIME_EXCEPT_SN B
         WHERE B.COMPANY_ID       = A.COMPANY_ID
           AND B.DIVISION_ID      = A.DIVISION_ID
           AND B.SITE_ID          = A.SITE_ID
           AND B.PLANT_ID         = A.PLANT_ID
           AND B.FACTORY_ID       = A.FACTORY_ID
           AND B.OPERATION_ID     = A.OPERATION_ID
           AND B.LINE_ID          = A.LINE_ID
           AND B.ELECTRODE_TYPE   = A.ELECTRODE_TYPE
           AND TO_CHAR(B.START_TIME, 'YYYYMM') = A.WORK_MONTH
        ;

        /* AS-IS EXEC [dbo].[PR_SCP_CAPA_HIST_DATASET] @SCP0049_LOSS 대응 */
        DELETE FROM GT_SCP0049_DS;

        INSERT INTO GT_SCP0049_DS
                  ( P_DIVISION_ID
                  , P_COMPANY_ID
                  , P_SITE_ID
                  , P_PLANT_ID
                  , P_FACTORY_ID
                  , P_LINE_ID
                  , P_OPERATION_ID
                  , P_ELECTRODE_TYPE
                  , P_ITEM_ID
                  , P_LOSS_CODE
                  , P_DATA_TABLE
                  , P_DATA_TYPE
                  , P_DAY_NAME
                  , P_DAY_QTY
                  , P_LANE_QTY
                  , P_CONFIRM_FLAG
                  , P_UPDATE_ID
                  )
        SELECT A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_OPERATION_ID
             , A.P_ELECTRODE_TYPE
             , A.P_ITEM_ID
             , A.P_LOSS_CODE
             , A.P_DATA_TABLE
             , A.P_DATA_TYPE
             , A.P_DAY_NAME
             , A.P_DAY_QTY
             , A.P_LANE_QTY
             , A.P_CONFIRM_FLAG
             , A.P_UPDATE_ID
          FROM GT_SCP0049_LOSS A
        ;

        P_CAPA_HIST_DATASET;

        -- 데이터 추가/수정
        UPDATE SCM_MST_TACT_TIME_SN A
           SET ( TACT_TIME
               , DAILY_CAPA
               , UPDATE_ID
               , UPDATE_TIME
               ) = (SELECT CASE WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(A.DAILY_CAPA, 0) = 0 THEN 0
                                WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / A.DAILY_CAPA * NVL(TO_NUMBER(B.LOSS_UTIL), 1)
                                ELSE A.TACT_TIME END
                         , TRUNC(CASE WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) = 0 THEN 0
                                      WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) > 0 THEN ROUND(86400 / A.TACT_TIME * NVL(TO_NUMBER(B.LOSS_UTIL), 1), 0)
                                      ELSE A.DAILY_CAPA END)
                         , B.UPDATE_ID
                         , SYSDATE
                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS B
                     WHERE A.COMPANY_ID       = B.COMPANY_ID
                       AND A.DIVISION_ID      = B.DIVISION_ID
                       AND A.SITE_ID          = B.SITE_ID
                       AND A.PLANT_ID         = B.PLANT_ID
                       AND A.FACTORY_ID       = B.FACTORY_ID
                       AND A.OPERATION_ID     = B.OPERATION_ID
                       AND A.LINE_ID          = B.LINE_ID
                       AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                       AND A.MONTH            = B.WORK_MONTH
                       AND ROWNUM             = 1
                   )
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS XA
                        WHERE A.COMPANY_ID      = XA.COMPANY_ID
                          AND A.DIVISION_ID     = XA.DIVISION_ID
                          AND A.SITE_ID         = XA.SITE_ID
                          AND A.PLANT_ID        = XA.PLANT_ID
                          AND A.FACTORY_ID      = XA.FACTORY_ID
                          AND A.OPERATION_ID    = XA.OPERATION_ID
                          AND A.LINE_ID         = XA.LINE_ID
                          AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                          AND A.MONTH           = XA.WORK_MONTH
                      )
        ;

        -- 데이터 저장
        UPDATE SCM_MST_TACT_TIME_EXCEPT_SN A
           SET ( TACT_TIME
               , DAILY_CAPA
               , UPDATE_ID
               , UPDATE_TIME
               ) = (SELECT CASE WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(A.DAILY_CAPA, 0) = 0 THEN 0
                                WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / A.DAILY_CAPA * NVL(TO_NUMBER(B.LOSS_UTIL), 1)
                                ELSE A.TACT_TIME END
                         , TRUNC(CASE WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) = 0 THEN 0
                                      WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) > 0 THEN ROUND(86400 / A.TACT_TIME * NVL(TO_NUMBER(B.LOSS_UTIL), 1), 0)
                                      ELSE A.DAILY_CAPA END)
                         , B.UPDATE_ID
                         , SYSDATE
                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS B
                     WHERE A.COMPANY_ID       = B.COMPANY_ID
                       AND A.DIVISION_ID      = B.DIVISION_ID
                       AND A.SITE_ID          = B.SITE_ID
                       AND A.PLANT_ID         = B.PLANT_ID
                       AND A.FACTORY_ID       = B.FACTORY_ID
                       AND A.OPERATION_ID     = B.OPERATION_ID
                       AND A.LINE_ID          = B.LINE_ID
                       AND A.ELECTRODE_TYPE   = B.ELECTRODE_TYPE
                       AND TO_CHAR(A.START_TIME, 'YYYYMM') = B.WORK_MONTH
                       AND ROWNUM             = 1
                   )
         WHERE EXISTS (SELECT 1
                         FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS XA
                        WHERE A.COMPANY_ID      = XA.COMPANY_ID
                          AND A.DIVISION_ID     = XA.DIVISION_ID
                          AND A.SITE_ID         = XA.SITE_ID
                          AND A.PLANT_ID        = XA.PLANT_ID
                          AND A.FACTORY_ID      = XA.FACTORY_ID
                          AND A.OPERATION_ID    = XA.OPERATION_ID
                          AND A.LINE_ID         = XA.LINE_ID
                          AND A.ELECTRODE_TYPE  = XA.ELECTRODE_TYPE
                          AND TO_CHAR(A.START_TIME, 'YYYYMM') = XA.WORK_MONTH
                      )
        ;

    END IF;

    COMMIT;

    SELECT COUNT(1)
      INTO V_MOD_CNT
      FROM GT_SCP0049_SAVE_DATA                            -- 2025.12.26 End [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : 적용 건수 오류 수정 :  @SCP0049_INC_VIRTAUL_LINE	-- [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : @SCP0049를 @SCP0049_INC_VIRTAUL_LINE로 변경 적용 (Real+Virtual)
    ;

    -- 결과코드, 결과 카운트 반환
    OPEN O_RESULT_CURSOR FOR
         SELECT 'S'            AS RESULT_CODE
              , V_MOD_CNT      AS RESULT_CNT
              , CAST(NULL AS VARCHAR2(4000)) AS ERR_MESSAGE
           FROM DUAL
    ;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_SES_USER_ID);

  EXCEPTION
    WHEN OTHERS THEN

      /* AS-IS BEGIN CATCH : if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리 */
      V_ERR_MESSAGE := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

      ROLLBACK TO SAVEPOINT SP_SCP0049_SAVE_CAPA;

      /* AS-IS 의 scm_sys_log_batch 직접 INSERT 는 자율 트랜잭션 로그 프로시저로 대체 */
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, SQLERRM, NULL, SYSDATE, P_SES_USER_ID
                         , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

      -- error코드, errror 메시지 반환
      OPEN O_RESULT_CURSOR FOR
           SELECT 'F'              AS RESULT_CODE
                , 0                AS RESULT_CNT
                , V_ERR_MESSAGE    AS ERR_MESSAGE
             FROM DUAL
      ;

      /* 종료 LOG */
      V_LOG_TYPE    := 'END';
      V_LOG_MESSAGE := '########## END of procedure ##########';
      V_DESCRIPTION := '';
      D_EVENT_DATE  := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, P_SES_USER_ID);

  END P_SAVE_CAPA;

/* ==================================================================================================
 * PACKAGE BODY 본문
 *
 * Program ID   : SCP0049_SAVE_NEW_MODEL  ->  PKG_SCP0049.P_SAVE_NEW_MODEL
 * Description  : CAPAA SAVE NEW MODEL
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/08/13   khj79          [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선 - 최초작성
 * 2021/05/17   khj79          [PJ20209642] LGES Digital SCM Level.3 달성을 위한 개선 - TACT TIME 저장되도록 수정
 * 2021/07/20   kmj            [PJ20209642] LGES Digital SCM Level.3 달성을 위한 개선 - Coater(E2000) Line assign 생성 시(New모델로 생성 시만) Mixer(E1000) 도 동일 라인/BOM 기준으로 자동 생성
 * 2021/08/24   kmj            [PJ20209642] LGES Digital SCM Level.3 달성을 위한 개선 - 이력 저장 및 LINE ASSIGN 9 입력시 삭제 처리
 * 2022/08/24   cys            E1000 데이타가 동시에 들어올 경우 E1000 자동등록 부분에서 중복으로 추가되어 PK 오류 발생되어 수정 (D.20220824~R.0824.01)
 * 2023/03/31   leejsthira2    line assign, lane 저장시 pancake master 정보 동기화 처리
 * 2025/10/15   hrkim          [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : JV 셀생산 Real Line 기준으로 ESS Virtual Line Capa정보 동기화 저장
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *
 * 전환 주기
 *---------------------------------------------------------------------------------------------------
 * @SCP0049_HIST(DBO.SCP0049 테이블 형식)   → GT_SCP0049        (이미 존재)
 * @SCP0049_DELETE(DBO.SCP0049 테이블 형식) → GT_SCP0049_DELETE (이미 존재)
 * #TMP_SCP0049_SAVE_NEW_MODEL              → GT_SCP0049_SAVE_NEW_MODEL (신규)
 * MERGE 4군데는 모두 상관 서브쿼리 UPDATE + NOT EXISTS INSERT 로 펼쳤다(온라인 SQL 에서 MERGE 금지).
 * BEGIN TRAN → SAVEPOINT , CATCH 의 ROLLBACK TRAN → ROLLBACK TO SAVEPOINT (커서 OPEN 앞).
 * 내부 프로시저 의존 : P_CAPA_HIST_DATASET · P_CAPA_LINE_ASSIGN_DELETE_DATASET (둘 다 인자 없음 · GT_SCP0049_DS 를 읽음)
 *            (AS-IS PR_SCP_CAPA_HIST_DATASET · PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET 흡수분 · P_SAVE_CAPA 와 같은 규약)
 * ================================================================================================== */
    PROCEDURE P_SAVE_NEW_MODEL
    (
        P_ACTIVE_FLAG       IN  VARCHAR2
      , P_TODAY_YYYYMMDD    IN  VARCHAR2
      , P_DIVISION_ID       IN  VARCHAR2
      , P_COMPANY_ID        IN  VARCHAR2
      , P_SITE_ID           IN  VARCHAR2
      , P_PLANT_ID          IN  VARCHAR2
      , P_FACTORY_ID        IN  VARCHAR2
      , P_OPERATION_ID      IN  VARCHAR2
      , P_ITEM_ID           IN  VARCHAR2
      , P_LINE_ID           IN  VARCHAR2
      , P_ELECTRODE_TYPE    IN  VARCHAR2
      , P_DAY_NAME          IN  VARCHAR2
      , P_DAY_QTY           IN  VARCHAR2
      , P_LANE_QTY          IN  VARCHAR2
      , P_DATA_TYPE         IN  VARCHAR2
      , P_UPDATE_ID         IN  VARCHAR2
      , O_RC                OUT SYS_REFCURSOR
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        V_DELIMITER         VARCHAR2(1 CHAR);

        -- LOG 용 변수 설정
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0049_SAVE_NEW_MODEL';
        V_LOG_TYPE          VARCHAR2(30 CHAR);   -- START/END/ERROR/...
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

        -- 결과 반환 변수 설정
        V_MOD_CNT           NUMBER(10) := 0;

        /* AS-IS UF_FX_String_Split 14벌을 NR 로 INNER JOIN 하므로 가장 짧은 목록 길이만큼만 행이 생긴다.
           그 행수를 미리 구해 CONNECT BY 로 만든다. */
        V_ROW_CNT           NUMBER(10) := 0;

        V_ERR_MSG           VARCHAR2(4000 CHAR);
    BEGIN

        V_DELIMITER := '^';

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        -- 트렌젝션 시작
        SAVEPOINT SP_SCP0049_SAVE_NEW_MODEL;

        /* GTT 초기화 (TRUNCATE 금지) */
        DELETE FROM GT_SCP0049_SAVE_NEW_MODEL;
        DELETE FROM GT_SCP0049;
        DELETE FROM GT_SCP0049_DELETE;
        DELETE FROM GT_SCP0049_DS;

        V_ROW_CNT := LEAST( TO_NUMBER(SCM_ARR_SPL_CNT(P_DATA_TYPE,      V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_DIVISION_ID,    V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_COMPANY_ID,     V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_SITE_ID,        V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_PLANT_ID,       V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_FACTORY_ID,     V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_LINE_ID,        V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_ELECTRODE_TYPE, V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_OPERATION_ID,   V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_ITEM_ID,        V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_LANE_QTY,       V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_DAY_NAME,       V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_DAY_QTY,        V_DELIMITER))
                          , TO_NUMBER(SCM_ARR_SPL_CNT(P_UPDATE_ID,      V_DELIMITER))
                          );

        /* CONNECT BY LEVEL <= 0 은 1행이 나오므로 0 이하는 아예 INSERT 하지 않는다. */
        IF V_ROW_CNT > 0 THEN

            INSERT INTO GT_SCP0049_SAVE_NEW_MODEL
                 ( DATA_TYPE
                 , DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , ITEM_ID
                 , LANE_QTY
                 , DAY_NAME
                 , DAY_QTY
                 , UPDATE_ID
                 )
            SELECT SCM_ARR_SPL_VAL(P_DATA_TYPE,      V_DELIMITER, LEVEL) AS DATA_TYPE
                 , SCM_ARR_SPL_VAL(P_DIVISION_ID,    V_DELIMITER, LEVEL) AS DIVISION_ID
                 , SCM_ARR_SPL_VAL(P_COMPANY_ID,     V_DELIMITER, LEVEL) AS COMPANY_ID
                 , SCM_ARR_SPL_VAL(P_SITE_ID,        V_DELIMITER, LEVEL) AS SITE_ID
                 , SCM_ARR_SPL_VAL(P_PLANT_ID,       V_DELIMITER, LEVEL) AS PLANT_ID
                 , SCM_ARR_SPL_VAL(P_FACTORY_ID,     V_DELIMITER, LEVEL) AS FACTORY_ID
                 , SCM_ARR_SPL_VAL(P_LINE_ID,        V_DELIMITER, LEVEL) AS LINE_ID
                 , SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE, V_DELIMITER, LEVEL) AS ELECTRODE_TYPE
                 , SCM_ARR_SPL_VAL(P_OPERATION_ID,   V_DELIMITER, LEVEL) AS OPERATION_ID
                 , SCM_ARR_SPL_VAL(P_ITEM_ID,        V_DELIMITER, LEVEL) AS ITEM_ID
                 , SCM_ARR_SPL_VAL(P_LANE_QTY,       V_DELIMITER, LEVEL) AS LANE_QTY
                 , SCM_ARR_SPL_VAL(P_DAY_NAME,       V_DELIMITER, LEVEL) AS DAY_NAME
                 , SCM_ARR_SPL_VAL(P_DAY_QTY,        V_DELIMITER, LEVEL) AS DAY_QTY
                 , SCM_ARR_SPL_VAL(P_UPDATE_ID,      V_DELIMITER, LEVEL) AS UPDATE_ID
              FROM DUAL
            CONNECT BY LEVEL <= V_ROW_CNT
            ;

        END IF;

        ------------------ Start [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ---------------------------------------------------------------------
        --### virtual line 데이터 삭제
        DELETE FROM GT_SCP0049_SAVE_NEW_MODEL PD
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_LINE_SN
                         WHERE DIVISION_ID     = PD.DIVISION_ID
                           AND COMPANY_ID      = PD.COMPANY_ID
                           AND SITE_ID         = PD.SITE_ID
                           AND PLANT_ID        = PD.PLANT_ID
                           AND FACTORY_ID      = PD.FACTORY_ID
                           AND LINE_ID         = PD.LINE_ID
                           AND OPERATION_ID    = PD.OPERATION_ID
                           AND ELECTRODE_TYPE  = PD.ELECTRODE_TYPE
                           AND VIRTUAL_LINE_YN = 'Y' )   -- ESS 가상 Line
        ;

        --### virtual line 데이터 추가
        INSERT INTO GT_SCP0049_SAVE_NEW_MODEL
             ( DATA_TYPE
             , DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , OPERATION_ID
             , ITEM_ID
             , LANE_QTY
             , DAY_NAME
             , DAY_QTY
             , UPDATE_ID
             )
        SELECT A.DATA_TYPE
             , B.DIVISION_ID
             , B.COMPANY_ID
             , B.SITE_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.LINE_ID
             , B.ELECTRODE_TYPE
             , B.OPERATION_ID
             , A.ITEM_ID
             , A.LANE_QTY
             , A.DAY_NAME
             , A.DAY_QTY
             , A.UPDATE_ID
          FROM GT_SCP0049_SAVE_NEW_MODEL A        /* AS-IS 별칭 RD */
             , SCM_MST_LINE_SN B                  /* AS-IS 별칭 VL */
         WHERE B.OPERATION_ID    = A.OPERATION_ID
           AND B.LINK_LINE_ID    = A.LINE_ID
           AND B.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
           AND B.ACTIVE_FLAG     = 'Y'
           AND B.VIRTUAL_LINE_YN = 'Y'            -- ESS 가상 Line
        ;
        ------------------ End [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ---------------------------------------------------------------------

        -- 이력 저장
        INSERT INTO GT_SCP0049
             ( P_DATA_TABLE
             , P_DATA_TYPE
             , P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_ELECTRODE_TYPE
             , P_OPERATION_ID
             , P_ITEM_ID
             , P_DAY_NAME
             , P_DAY_QTY
             , P_UPDATE_ID
             )
        SELECT 'LA' AS P_DATA_TABLE
             , CASE WHEN DATA_TYPE = 'LANE_QTY_DATA' THEN 'LQ'
                    WHEN DATA_TYPE = 'PRIORITY_DATA' THEN 'M'
               END  AS P_DATA_TYPE
             , DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , OPERATION_ID
             , ITEM_ID
             , DAY_NAME
             , DAY_QTY
             , UPDATE_ID
          FROM GT_SCP0049_SAVE_NEW_MODEL
        ;

        -- 이력저장
        /* AS-IS EXEC [dbo].[PR_SCP_CAPA_HIST_DATASET] @SCP0049_HIST 대응 */
        /* 테이블 파라미터는 전달용 GTT(GT_SCP0049_DS)로 인계한다 */
        DELETE FROM GT_SCP0049_DS;

        INSERT INTO GT_SCP0049_DS
             ( P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_OPERATION_ID
             , P_ELECTRODE_TYPE
             , P_ITEM_ID
             , P_LOSS_CODE
             , P_DATA_TABLE
             , P_DATA_TYPE
             , P_DAY_NAME
             , P_DAY_QTY
             , P_LANE_QTY
             , P_CONFIRM_FLAG
             , P_UPDATE_ID
             )
        SELECT A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_OPERATION_ID
             , A.P_ELECTRODE_TYPE
             , A.P_ITEM_ID
             , A.P_LOSS_CODE
             , A.P_DATA_TABLE
             , A.P_DATA_TYPE
             , A.P_DAY_NAME
             , A.P_DAY_QTY
             , A.P_LANE_QTY
             , A.P_CONFIRM_FLAG
             , A.P_UPDATE_ID
          FROM GT_SCP0049 A
        ;

        P_CAPA_HIST_DATASET;

        -- 데이터 삭제를 위한 변수 설정
        INSERT INTO GT_SCP0049_DELETE
             ( P_DATA_TABLE
             , P_DATA_TYPE
             , P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_ELECTRODE_TYPE
             , P_OPERATION_ID
             , P_ITEM_ID
             , P_LOSS_CODE
             , P_LANE_QTY
             , P_CONFIRM_FLAG
             , P_DAY_NAME
             , P_DAY_QTY
             , P_UPDATE_ID
             )
        SELECT P_DATA_TABLE
             , P_DATA_TYPE
             , P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_ELECTRODE_TYPE
             , P_OPERATION_ID
             , P_ITEM_ID
             , P_LOSS_CODE
             , P_LANE_QTY
             , P_CONFIRM_FLAG
             , P_DAY_NAME
             , P_DAY_QTY
             , P_UPDATE_ID
          FROM GT_SCP0049
         WHERE NVL(TRUNC(ROUND(TO_NUMBER(P_DAY_QTY), 10)), 0) = 9
        ;

        -- 데이터 삭제(LINE_ASSIGN,TACT_TIME,YIELD)
        /* AS-IS EXEC [dbo].[PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET] @SCP0049_DELETE 대응 */
        DELETE FROM GT_SCP0049_DS;

        INSERT INTO GT_SCP0049_DS
             ( P_DIVISION_ID
             , P_COMPANY_ID
             , P_SITE_ID
             , P_PLANT_ID
             , P_FACTORY_ID
             , P_LINE_ID
             , P_OPERATION_ID
             , P_ELECTRODE_TYPE
             , P_ITEM_ID
             , P_LOSS_CODE
             , P_DATA_TABLE
             , P_DATA_TYPE
             , P_DAY_NAME
             , P_DAY_QTY
             , P_LANE_QTY
             , P_CONFIRM_FLAG
             , P_UPDATE_ID
             )
        SELECT A.P_DIVISION_ID
             , A.P_COMPANY_ID
             , A.P_SITE_ID
             , A.P_PLANT_ID
             , A.P_FACTORY_ID
             , A.P_LINE_ID
             , A.P_OPERATION_ID
             , A.P_ELECTRODE_TYPE
             , A.P_ITEM_ID
             , A.P_LOSS_CODE
             , A.P_DATA_TABLE
             , A.P_DATA_TYPE
             , A.P_DAY_NAME
             , A.P_DAY_QTY
             , A.P_LANE_QTY
             , A.P_CONFIRM_FLAG
             , A.P_UPDATE_ID
          FROM GT_SCP0049_DELETE A
        ;

        P_CAPA_LINE_ASSIGN_DELETE_DATASET;

        -- 9 값은 삭제
        DELETE FROM GT_SCP0049_SAVE_NEW_MODEL
         WHERE NVL(TRUNC(ROUND(TO_NUMBER(DAY_QTY), 10)), 0) = 9
        ;

        -- E2000(coating) NEW MODEL 등록시(신규 등록시만/수정X)
        -- E1000(mixing) 자동 등록
        INSERT INTO GT_SCP0049_SAVE_NEW_MODEL
             ( DATA_TYPE
             , COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , OPERATION_ID
             , ITEM_ID
             , LANE_QTY
             , DAY_NAME
             , DAY_QTY
             , UPDATE_ID
             )
        SELECT DISTINCT IA.DATA_TYPE
             , IA.COMPANY_ID
             , IA.DIVISION_ID
             , IA.SITE_ID
             , IA.PLANT_ID
             , IA.FACTORY_ID
             , IA.LINE_ID
             , IA.ELECTRODE_TYPE
             , ( CASE WHEN B.ITEM_CLASS = 'ES0109' THEN 'E0430' ELSE A.OPERATION_ID END ) AS OPERATION_ID   -- [E20240711-001442]신규 공정(DAM Slurry Mixing) 개발로 인한 FP WO 생성 기능 개발 요청 건
             , B.ITEM_ID
             , IA.LANE_QTY
             , IA.DAY_NAME
             , IA.DAY_QTY
             , IA.UPDATE_ID
          FROM SCM_LINE_HIERARCHY_V_SN A
             , SCM_ITEM_M_SN B
             , SCM_MST_BOM_ENG_SN C                 /* AS-IS 별칭 BO : SCM_BOM_M */
             , ( SELECT XA.DATA_TYPE
                      , XA.COMPANY_ID
                      , XA.DIVISION_ID
                      , XA.SITE_ID
                      , XA.PLANT_ID
                      , XA.FACTORY_ID
                      , XA.LINE_ID
                      , XA.ELECTRODE_TYPE
                      , XA.OPERATION_ID
                      , XA.ITEM_ID
                      , XA.LANE_QTY
                      , XA.DAY_NAME
                      , XA.DAY_QTY
                      , XA.UPDATE_ID
                   FROM GT_SCP0049_SAVE_NEW_MODEL XA
                  WHERE XA.OPERATION_ID = 'E2000'
                    AND NOT EXISTS ( SELECT 1                           /* AS-IS 스칼라 서브쿼리 CNT = 0 */
                                       FROM SCM_MST_ITEM_LINE_ASSIGN_SN XB
                                      WHERE XB.COMPANY_ID     = XA.COMPANY_ID
                                        AND XB.DIVISION_ID    = XA.DIVISION_ID
                                        AND XB.SITE_ID        = XA.SITE_ID
                                        AND XB.PLANT_ID       = XA.PLANT_ID
                                        AND XB.FACTORY_ID     = XA.FACTORY_ID
                                        AND XB.ITEM_ID        = XA.ITEM_ID
                                        AND XB.OPERATION_ID   = XA.OPERATION_ID
                                        AND XB.LINE_ID        = XA.LINE_ID
                                        AND XB.ELECTRODE_TYPE = XA.ELECTRODE_TYPE
                                        AND XB.MONTH          = XA.DAY_NAME ) ) IA    /* AS-IS 별칭 M */
         WHERE A.DIVISION_ID   = B.DIVISION_ID
           AND A.SITE_ID       = B.SITE_ID
           AND (  INSTR(B.FLOW_ID, A.OPERATION_ID) > 0
               OR INSTR(B.FORMATION_FLOW_ID, A.OPERATION_ID) > 0
               )
           AND A.DIVISION_ID   = C.DIVISION_ID
           AND A.SITE_ID       = C.SITE_ID
           AND A.PLANT_ID      = C.PLANT_ID
           AND B.ITEM_ID       = C.CHILD_ITEM_ID
           AND C.DIVISION_ID   = IA.DIVISION_ID
           AND C.PLANT_ID      = IA.PLANT_ID
           AND C.COMPANY_ID    = IA.COMPANY_ID
           AND C.PARENT_ITEM_ID = IA.ITEM_ID
           AND C.SITE_ID       = IA.SITE_ID
           AND A.FACTORY_ID    = IA.FACTORY_ID
           AND A.LINE_ID       = IA.LINE_ID
           AND A.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
           AND NOT EXISTS ( SELECT 1                                    -- (D.20220824~R.0824.01)
                              FROM GT_SCP0049_SAVE_NEW_MODEL SA
                             WHERE SA.COMPANY_ID     = IA.COMPANY_ID
                               AND SA.DIVISION_ID    = IA.DIVISION_ID
                               AND SA.SITE_ID        = IA.SITE_ID
                               AND SA.PLANT_ID       = IA.PLANT_ID
                               AND SA.FACTORY_ID     = IA.FACTORY_ID
                               AND SA.ITEM_ID        = B.ITEM_ID
                               AND SA.OPERATION_ID   = A.OPERATION_ID
                               AND SA.LINE_ID        = IA.LINE_ID
                               AND SA.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                               AND SA.DAY_NAME       = IA.DAY_NAME
                               AND SA.OPERATION_ID   = 'E1000' )
           AND B.ACTIVE_FLAG   = 'Y'
           AND C.ACTIVE_FLAG   = 'Y'
           AND C.EFF_END_DATE >= SYSDATE
           AND INSTR(B.FLOW_ID, 'E1000') > 0
        ;

        /* ############################################################################ */
        /* LANE QTY 는 PRIORITY 가 다 처리된 다음 UPDATE 를 진행해야 누락이 발생하지 않는다 */
        /* ############################################################################ */

        /* AS-IS MERGE ① : SCM_MST_ITEM_LINE_ASSIGN_SN 의 LANE_QTY (WHEN MATCHED 만 있음 -> UPDATE 만) */
        UPDATE SCM_MST_ITEM_LINE_ASSIGN_SN A
           SET ( LANE_QTY
               , UPDATE_ID
               , UPDATE_TIME ) = ( SELECT TO_NUMBER(B.LANE_QTY)
                                          , B.UPDATE_ID
                                          , SYSDATE
                                       FROM GT_SCP0049_SAVE_NEW_MODEL B
                                      WHERE B.COMPANY_ID     = A.COMPANY_ID
                                        AND B.DIVISION_ID    = A.DIVISION_ID
                                        AND B.SITE_ID        = A.SITE_ID
                                        AND B.PLANT_ID       = A.PLANT_ID
                                        AND B.FACTORY_ID     = A.FACTORY_ID
                                        AND B.ITEM_ID        = A.ITEM_ID
                                        AND B.OPERATION_ID   = A.OPERATION_ID
                                        AND B.LINE_ID        = A.LINE_ID
                                        AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                        AND B.DATA_TYPE      = 'LANE_QTY_DATA' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0049_SAVE_NEW_MODEL SA
                         WHERE SA.COMPANY_ID     = A.COMPANY_ID
                           AND SA.DIVISION_ID    = A.DIVISION_ID
                           AND SA.SITE_ID        = A.SITE_ID
                           AND SA.PLANT_ID       = A.PLANT_ID
                           AND SA.FACTORY_ID     = A.FACTORY_ID
                           AND SA.ITEM_ID        = A.ITEM_ID
                           AND SA.OPERATION_ID   = A.OPERATION_ID
                           AND SA.LINE_ID        = A.LINE_ID
                           AND SA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                           AND SA.DATA_TYPE      = 'LANE_QTY_DATA' )
           AND A.MONTH >= SUBSTR(P_TODAY_YYYYMMDD, 1, 6)
        ;

        -- pancake master 에 lane 값 동기화...기존 lane 삭제 ... 20230331
        DELETE FROM SCM_ITEM_LANE_M_SN A
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0049_SAVE_NEW_MODEL SA
                             , SCM_LINE_M_SN SB
                         WHERE SA.COMPANY_ID       = SB.COMPANY_ID
                           AND SA.DIVISION_ID      = SB.DIVISION_ID
                           AND SA.SITE_ID          = SB.SITE_ID
                           AND SA.PLANT_ID         = SB.PLANT_ID
                           AND SA.FACTORY_ID       = SB.FACTORY_ID
                           AND SA.OPERATION_ID     = SB.OPERATION_ID
                           AND SA.LINE_ID          = SB.LINE_ID
                           AND SA.ELECTRODE_TYPE   = SB.ELECTRODE_TYPE
                           AND A.COMPANY_ID        = SA.COMPANY_ID
                           AND A.DIVISION_ID       = SA.DIVISION_ID
                           AND A.SITE_ID           = SA.SITE_ID
                           AND A.PLANT_ID          = SA.PLANT_ID
                           AND A.ITEM_ID           = SA.ITEM_ID
                           AND A.FACTORY_ID        = SA.FACTORY_ID
                           AND A.PROD_VERSION_TYPE = NVL(SB.PROD_VERSION_TYPE, 'GENERAL')
                           AND A.LANE_QTY         <> TO_NUMBER(SA.LANE_QTY)   -- 저장할 LANE 과 같지 않은 lane 삭제
                           AND SA.DATA_TYPE        = 'LANE_QTY_DATA'
                           AND SA.OPERATION_ID IN ('E2000', 'E3000', 'E4000') )
        ;

        /* AS-IS MERGE ② : pancake master 에 lane 값 동기화... 20230331 (UPDATE + INSERT 로 펼침) */
        UPDATE SCM_ITEM_LANE_M_SN A
           SET ( ACTIVE_FLAG
               , UPDATE_ID
               , UPDATE_TIME ) = ( SELECT 'Y'
                                          , MAX(B.UPDATE_ID)
                                          , SYSDATE
                                       FROM GT_SCP0049_SAVE_NEW_MODEL B
                                          , SCM_LINE_M_SN C
                                      WHERE B.COMPANY_ID     = C.COMPANY_ID
                                        AND B.DIVISION_ID    = C.DIVISION_ID
                                        AND B.SITE_ID        = C.SITE_ID
                                        AND B.PLANT_ID       = C.PLANT_ID
                                        AND B.FACTORY_ID     = C.FACTORY_ID
                                        AND B.OPERATION_ID   = C.OPERATION_ID
                                        AND B.LINE_ID        = C.LINE_ID
                                        AND B.ELECTRODE_TYPE = C.ELECTRODE_TYPE
                                        AND A.COMPANY_ID     = B.COMPANY_ID
                                        AND A.DIVISION_ID    = B.DIVISION_ID
                                        AND A.SITE_ID        = B.SITE_ID
                                        AND A.PLANT_ID       = B.PLANT_ID
                                        AND A.ITEM_ID        = B.ITEM_ID
                                        AND A.FACTORY_ID     = B.FACTORY_ID
                                        AND A.PROD_VERSION_TYPE = NVL(C.PROD_VERSION_TYPE, 'GENERAL')
                                        AND A.LANE_QTY       = NVL(CASE WHEN B.LANE_QTY IS NULL THEN 0.0 ELSE TO_NUMBER(B.LANE_QTY) END, 0)
                                        AND B.DATA_TYPE      = 'LANE_QTY_DATA'
                                        AND B.OPERATION_ID IN ('E2000', 'E3000', 'E4000') )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0049_SAVE_NEW_MODEL SA
                             , SCM_LINE_M_SN SB
                         WHERE SA.COMPANY_ID     = SB.COMPANY_ID
                           AND SA.DIVISION_ID    = SB.DIVISION_ID
                           AND SA.SITE_ID        = SB.SITE_ID
                           AND SA.PLANT_ID       = SB.PLANT_ID
                           AND SA.FACTORY_ID     = SB.FACTORY_ID
                           AND SA.OPERATION_ID   = SB.OPERATION_ID
                           AND SA.LINE_ID        = SB.LINE_ID
                           AND SA.ELECTRODE_TYPE = SB.ELECTRODE_TYPE
                           AND A.COMPANY_ID      = SA.COMPANY_ID
                           AND A.DIVISION_ID     = SA.DIVISION_ID
                           AND A.SITE_ID         = SA.SITE_ID
                           AND A.PLANT_ID        = SA.PLANT_ID
                           AND A.ITEM_ID         = SA.ITEM_ID
                           AND A.FACTORY_ID      = SA.FACTORY_ID
                           AND A.PROD_VERSION_TYPE = NVL(SB.PROD_VERSION_TYPE, 'GENERAL')
                           AND A.LANE_QTY        = NVL(CASE WHEN SA.LANE_QTY IS NULL THEN 0.0 ELSE TO_NUMBER(SA.LANE_QTY) END, 0)
                           AND SA.DATA_TYPE      = 'LANE_QTY_DATA'
                           AND SA.OPERATION_ID IN ('E2000', 'E3000', 'E4000') )
        ;

        INSERT INTO SCM_ITEM_LANE_M_SN
             ( COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , ITEM_ID
             , LANE_QTY
             , SLIT_WIDTH
             , MAIN_LANE_QTY
             , SUB_LANE_QTY
             , PATTERN_QTY
             , HALF_SLIT_FLAG
             , FOIL_ID
             , ACTIVE_FLAG
             , DESCRIPTION
             , INSERT_ID
             , INSERT_TIME
             , UPDATE_ID
             , UPDATE_TIME
             , PC_ROLL_LENGTH
             , PC_ROLL_LENGTH_UOM
             , GPLM_LANE_QTY
             , GPLM_MAIN_LANE_QTY
             , GPLM_SUB_LANE_QTY
             , PROD_VERSION_TYPE
             , JUMBO_ROLL_LENGTH
             , GPLM_PC_ROLL_LENGTH
             , GPLM_JUMBO_ROLL_LENGTH
             )
        SELECT DISTINCT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , NVL(CASE WHEN A.LANE_QTY IS NULL THEN 0.0 ELSE TO_NUMBER(A.LANE_QTY) END, 0) AS LANE_QTY
             , 0
             , NVL(CASE WHEN A.LANE_QTY IS NULL THEN 0.0 ELSE TO_NUMBER(A.LANE_QTY) END, 0) AS MAIN_LANE_QTY
             , 0
             , 1
             , 'N'
             , NULL
             , 'Y'
             , ''
             , A.UPDATE_ID
             , SYSDATE
             , A.UPDATE_ID
             , SYSDATE
             , NULL
             , ''
             , NULL
             , NULL
             , NULL
             , NVL(B.PROD_VERSION_TYPE, 'GENERAL') AS PROD_VERSION_TYPE
             , NULL
             , NULL
             , NULL
          FROM GT_SCP0049_SAVE_NEW_MODEL A
             , SCM_LINE_M_SN B
         WHERE A.COMPANY_ID     = B.COMPANY_ID
           AND A.DIVISION_ID    = B.DIVISION_ID
           AND A.SITE_ID        = B.SITE_ID
           AND A.PLANT_ID       = B.PLANT_ID
           AND A.FACTORY_ID     = B.FACTORY_ID
           AND A.OPERATION_ID   = B.OPERATION_ID
           AND A.LINE_ID        = B.LINE_ID
           AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
           AND NOT EXISTS ( SELECT 1
                              FROM SCM_ITEM_LANE_M_SN SA
                             WHERE SA.COMPANY_ID        = A.COMPANY_ID
                               AND SA.DIVISION_ID       = A.DIVISION_ID
                               AND SA.SITE_ID           = A.SITE_ID
                               AND SA.PLANT_ID          = A.PLANT_ID
                               AND SA.ITEM_ID           = A.ITEM_ID
                               AND SA.FACTORY_ID        = A.FACTORY_ID
                               AND SA.PROD_VERSION_TYPE = NVL(B.PROD_VERSION_TYPE, 'GENERAL')
                               AND SA.LANE_QTY          = NVL(CASE WHEN A.LANE_QTY IS NULL THEN 0.0 ELSE TO_NUMBER(A.LANE_QTY) END, 0) )
           AND A.DATA_TYPE      = 'LANE_QTY_DATA'
           AND A.OPERATION_ID IN ('E2000', 'E3000', 'E4000')
        ;

        /* #################################################### */
        /* SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN                   */
        /* LANE QTY 정보 UPDATE                                 */
        /* #################################################### */
        /* AS-IS MERGE ③ : WHEN MATCHED 만 있음 -> UPDATE 만 */
        UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
           SET ( LANE_QTY
               , UPDATE_ID
               , UPDATE_TIME ) = ( SELECT TO_NUMBER(B.LANE_QTY)
                                          , B.UPDATE_ID
                                          , SYSDATE
                                       FROM GT_SCP0049_SAVE_NEW_MODEL B
                                      WHERE B.COMPANY_ID     = A.COMPANY_ID
                                        AND B.DIVISION_ID    = A.DIVISION_ID
                                        AND B.SITE_ID        = A.SITE_ID
                                        AND B.PLANT_ID       = A.PLANT_ID
                                        AND B.FACTORY_ID     = A.FACTORY_ID
                                        AND B.ITEM_ID        = A.ITEM_ID
                                        AND B.OPERATION_ID   = A.OPERATION_ID
                                        AND B.LINE_ID        = A.LINE_ID
                                        AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                        AND B.DATA_TYPE      = 'LANE_QTY_DATA' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0049_SAVE_NEW_MODEL SA
                         WHERE SA.COMPANY_ID     = A.COMPANY_ID
                           AND SA.DIVISION_ID    = A.DIVISION_ID
                           AND SA.SITE_ID        = A.SITE_ID
                           AND SA.PLANT_ID       = A.PLANT_ID
                           AND SA.FACTORY_ID     = A.FACTORY_ID
                           AND SA.ITEM_ID        = A.ITEM_ID
                           AND SA.OPERATION_ID   = A.OPERATION_ID
                           AND SA.LINE_ID        = A.LINE_ID
                           AND SA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                           AND SA.DATA_TYPE      = 'LANE_QTY_DATA' )
           AND TO_CHAR(A.START_TIME, 'YYYYMM') >= SUBSTR(P_TODAY_YYYYMMDD, 1, 6)
        ;

        /* AS-IS MERGE ④ : SCM_MST_ITEM_LINE_ASSIGN_SN 의 PRIORITY (UPDATE + INSERT 로 펼침) */
        UPDATE SCM_MST_ITEM_LINE_ASSIGN_SN A
           SET ( PRIORITY
               , UPDATE_ID
               , UPDATE_TIME ) = ( SELECT NVL(TRUNC(TO_NUMBER(B.DAY_QTY)), 0)   /* AS-IS CONVERT(INT, DAY_QTY) - MSSQL 은 빈 문자를 0 으로 변환 */
                                          , B.UPDATE_ID
                                          , SYSDATE
                                       FROM GT_SCP0049_SAVE_NEW_MODEL B
                                      WHERE B.COMPANY_ID     = A.COMPANY_ID
                                        AND B.DIVISION_ID    = A.DIVISION_ID
                                        AND B.SITE_ID        = A.SITE_ID
                                        AND B.PLANT_ID       = A.PLANT_ID
                                        AND B.FACTORY_ID     = A.FACTORY_ID
                                        AND B.ITEM_ID        = A.ITEM_ID
                                        AND B.OPERATION_ID   = A.OPERATION_ID
                                        AND B.LINE_ID        = A.LINE_ID
                                        AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                        AND B.DAY_NAME       = A.MONTH
                                        AND B.DATA_TYPE      = 'PRIORITY_DATA' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0049_SAVE_NEW_MODEL SA
                         WHERE SA.COMPANY_ID     = A.COMPANY_ID
                           AND SA.DIVISION_ID    = A.DIVISION_ID
                           AND SA.SITE_ID        = A.SITE_ID
                           AND SA.PLANT_ID       = A.PLANT_ID
                           AND SA.FACTORY_ID     = A.FACTORY_ID
                           AND SA.ITEM_ID        = A.ITEM_ID
                           AND SA.OPERATION_ID   = A.OPERATION_ID
                           AND SA.LINE_ID        = A.LINE_ID
                           AND SA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                           AND SA.DAY_NAME       = A.MONTH
                           AND SA.DATA_TYPE      = 'PRIORITY_DATA' )
        ;

        INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_SN
             ( COMPANY_ID
             , DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , MONTH
             , LANE_QTY
             , PRIORITY
             , INSERT_ID
             , INSERT_TIME
             , UPDATE_ID
             , UPDATE_TIME
             )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.ITEM_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ELECTRODE_TYPE
             , A.DAY_NAME
             , CASE WHEN A.OPERATION_ID != 'E2000' OR A.LANE_QTY IS NULL THEN 0.0 ELSE NVL(TO_NUMBER(A.LANE_QTY), 0) END
             , NVL(TRUNC(TO_NUMBER(A.DAY_QTY)), 0)        /* AS-IS CONVERT(INT, DAY_QTY) - MSSQL 은 빈 문자를 0 으로 변환 */
             , A.UPDATE_ID
             , SYSDATE
             , A.UPDATE_ID
             , SYSDATE
          FROM GT_SCP0049_SAVE_NEW_MODEL A
         WHERE NOT EXISTS ( SELECT 1
                              FROM SCM_MST_ITEM_LINE_ASSIGN_SN SA
                             WHERE SA.COMPANY_ID     = A.COMPANY_ID
                               AND SA.DIVISION_ID    = A.DIVISION_ID
                               AND SA.SITE_ID        = A.SITE_ID
                               AND SA.PLANT_ID       = A.PLANT_ID
                               AND SA.FACTORY_ID     = A.FACTORY_ID
                               AND SA.ITEM_ID        = A.ITEM_ID
                               AND SA.OPERATION_ID   = A.OPERATION_ID
                               AND SA.LINE_ID        = A.LINE_ID
                               AND SA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                               AND SA.MONTH          = A.DAY_NAME )
           AND A.DATA_TYPE = 'PRIORITY_DATA'
        ;

        COMMIT;

        SELECT COUNT(1)
          INTO V_MOD_CNT
          FROM GT_SCP0049
        ;

        -- 종료 LOG
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        -- 결과코드, 결과 카운트 반환
        OPEN O_RC FOR
            SELECT 'S'       AS RESULT_CODE
                 , V_MOD_CNT AS RESULT_CNT
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT 'S'           AS RESULT_CODE
                 , TO_CHAR(NULL) AS RESULT_MSG
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

            /* AS-IS : if (xact_state() <> 0) ROLLBACK TRAN
               COMMIT 뒤에 난 오류면 SAVEPOINT 가 이미 없으므로(ORA-01086) 감싸 둔다. */
            BEGIN
                ROLLBACK TO SAVEPOINT SP_SCP0049_SAVE_NEW_MODEL;   --입력 데이타 롤백 처리
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;

            /* 에러나도 로그는 인서트 (PR_SCM_SYS_LOG_BATCH 는 자율 트랜잭션이라 롤백에 지워지지 않는다) */
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, SQLERRM, NULL, SYSDATE, NULL, TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

            -- 종료 LOG
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', N_LOG_COUNT, '########## END of procedure ##########', '', SYSDATE, NULL, NULL, NULL, NULL);

            -- error코드, errror 메시지 반환
            IF NOT O_RC%ISOPEN THEN
                OPEN O_RC FOR
                    SELECT 'F' AS RESULT_CODE
                         , 0   AS RESULT_CNT
                      FROM DUAL;
            END IF;

            OPEN O_RESULT_CURSOR FOR
                SELECT '-1'      AS RESULT_CODE
                     , V_ERR_MSG AS RESULT_MSG
                  FROM DUAL;
    END P_SAVE_NEW_MODEL;

/*
 * Program ID   : SCP0049_SAVE_NEW_VERSION
 * Description  : Master Data Management New Version 저장
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/08/25   khj79          [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선 - 최초작성
 * 2021/01/14   khj79          [PJ20199555] VERSION 정보가 DIVISION ID 별 저장되도록 수정 , DIVISION_ID 가 'EE' 인 경우 전체 저장 그외 해당 DIV 만 저장
 * 2021/02/05   khj79          [PJ20199555] LOSS Available(%) , Loading(%) , Operating(%) , OEE(%) 계산 로직 추가
 * 2021/03/10   khj79          부동 소수점 오류 개선
 * 2021/10/07	khj79	       [PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.3) - M11 => M12 로 변경
 * 2024/01/10   leejsthira2    [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
  PROCEDURE P_SAVE_NEW_VERSION
  (
      P_TODAY_YYYYMMDD    IN  VARCHAR2
    , P_CHK_BP            IN  VARCHAR2
    , P_CHK_RP            IN  VARCHAR2
    , P_CHK_SCP           IN  VARCHAR2
    , P_VERSION_DIVISION  IN  VARCHAR2
    , P_VERSION_NAME      IN  VARCHAR2
    , P_UPDATE_ID         IN  VARCHAR2
    , O_RESULT_CURSOR     OUT SYS_REFCURSOR
  )
  IS

    V_MAX_LOOP_CNT      NUMBER(10)          := 0;
    V_MST_LOOP_CNT      NUMBER(10)          := 0;
    V_DELIMITER         VARCHAR2(1 CHAR)    := ',';

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME      VARCHAR2(150 CHAR)  := 'SCP0049_SAVE_NEW_VERSION';
    V_LOG_TYPE          VARCHAR2(30 CHAR);                          /* START/END/ERROR/... */
    N_LOG_COUNT         NUMBER(10)          := 0;
    V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
    V_DESCRIPTION       VARCHAR2(500 CHAR);
    D_EVENT_DATE        DATE;
    V_PROGRESS          NUMBER(20,10);

    V_ISO_YYYYWW        VARCHAR2(6 CHAR);
    V_START_MONTH       VARCHAR2(6 CHAR);
    V_END_MONTH         VARCHAR2(6 CHAR);   /* LOSS Available(%) 등을 계산하기 위한 월 */

    V_MAX_VERSION_ID    VARCHAR2(15 CHAR);
    V_NEW_VERSION_ID    VARCHAR2(15 CHAR);

    V_DIVISION_ID       VARCHAR2(10 CHAR);

    V_SEQ_NUM           NUMBER(10);
    V_SEQ_NUM_TXT       VARCHAR2(3 CHAR);

    V_ERR_MESSAGE       VARCHAR2(4000 CHAR);

  BEGIN

    /* 저장 시작 지점(오류 시 앞 행 저장분 복구) */
    SAVEPOINT SP_SCP0049_SAVE_NEW_VER;

    V_START_MONTH := TO_CHAR(ADD_MONTHS(TO_DATE(P_TODAY_YYYYMMDD, 'YYYYMMDD'), -3), 'YYYYMM');

    SELECT MAX(WORK_MONTH)
      INTO V_END_MONTH
      FROM SCM_LOSS_M_SN
    ;

    -- ////////////////////////////////////////// SUM 임시 테이블 //////////////////////////////////////////////////////
    /* ############################################################ */
    /* GTT 초기화 (AS-IS 의 #TMP DROP/CREATE 대응. TRUNCATE 금지) */
    /* ############################################################ */
    DELETE FROM GT_SCP0049_VER_LOOKUP;
    DELETE FROM GT_SCP0049_VER_DAY_OF_MONTH;
    DELETE FROM GT_SCP0049_VER_MM;
    DELETE FROM GT_SCP0049_VER_STD;
    DELETE FROM GT_SCP0049_VER_STD_SUM;
    DELETE FROM GT_SCP0049_VER_STD_CAL;

    -- LOOKUP 정보 조회
    INSERT INTO GT_SCP0049_VER_LOOKUP
              ( LOSS_CODE
              , CATEGORY_ID
              , KEY_ID
              , DATA_TABLE
              , CATEGORY_ORDER
              , UOM
              , SORT_ORDER
              )
    SELECT SEGMENT1      AS LOSS_CODE
         , ATTRIBUTE1    AS CATEGORY_ID
         , ATTRIBUTE2    AS KEY_ID
         , ATTRIBUTE3    AS DATA_TABLE
         , ROUND(TO_NUMBER(ATTRIBUTE8), 10) AS CATEGORY_ORDER
         , ATTRIBUTE9    AS UOM
         , SORT_ORDER
      FROM SCM_SYS_LOOKUP_VALUE_SN
     WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
       AND ACTIVE_FLAG      = 'Y'
    ;

    -- 월별 날짜 저장
    -- 날짜별 시간을 곱한 값 ( 일수 * 1440)
    INSERT INTO GT_SCP0049_VER_DAY_OF_MONTH
              ( YYYYMM
              , WORKING_DAY
              , WORKING_TIME
              )
    SELECT BASIS_YYYYMM                     AS YYYYMM
         , TRUNC(TO_NUMBER(MAX(CALENDAR_DAY)))        AS WORKING_DAY
         , TRUNC(TO_NUMBER(MAX(CALENDAR_DAY))) * 1440 AS WORKING_TIME
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMM >= V_START_MONTH
       AND BASIS_YYYYMM <= V_END_MONTH
     GROUP BY BASIS_YYYYMM
    ;

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* 트렌젝션 시작 (AS-IS BEGIN TRAN → 위 SAVEPOINT 가 대응) */
    /* AS-IS BEGIN TRY 구간 시작 */

    -- /////////////////////////////////////////////////////////////////
    -- VERSION_ID 생성
    -- /////////////////////////////////////////////////////////////////
    -- 현재일 기준 생성주차 확인
    SELECT MAX(ISO_YYYYWW)
      INTO V_ISO_YYYYWW
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD = P_TODAY_YYYYMMDD
    ;

    -- 생성주차 일련번호 확인
    SELECT SUBSTR(MAX(VERSION_ID), 8, 3)
      INTO V_MAX_VERSION_ID
      FROM SCM_MASTER_VERSION_INFO_H_SN
      --WHERE SUBSTRING(VERSION_ID , 1, 6) = @p_iso_yyyyww;
     WHERE SUBSTR(VERSION_ID, 1, 6) = V_ISO_YYYYWW
    ;

    IF V_MAX_VERSION_ID IS NULL THEN
        -- 생성주차에 일련번호 없으면 신규 생성
        V_NEW_VERSION_ID := V_ISO_YYYYWW || '_001';
    ELSE
        -- 생성주차에 일련번호 있으면 일련번호 + 1
        V_SEQ_NUM     := TO_NUMBER(V_MAX_VERSION_ID) + 1;
        V_SEQ_NUM_TXT := SUBSTR('000' || TO_CHAR(V_SEQ_NUM), -3);
        V_NEW_VERSION_ID := V_ISO_YYYYWW || '_' || V_SEQ_NUM_TXT;
    END IF;

    -- /////////////////////////////////////////////////////////////////
    -- PROGRESS 정보 설정
    -- /////////////////////////////////////////////////////////////////
    /* AS-IS SET ARITHIGNORE ON : 0 으로 나누면 오류가 아니라 NULL 이므로 CASE 로 가른다 */
    SELECT CASE WHEN COUNT(*) = 0 THEN NULL
                ELSE ROUND(COUNT(CASE WHEN CONFIRM_FLAG = 'Y' THEN 1 END) / COUNT(*) * 100, 2)
            END
      INTO V_PROGRESS
      FROM SCM_MASTER_MANAGER_M_SN
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_MASTER_VERSION_INFO_H_SN 기준 버전 정보 생성
    -- DIVISION ID 별 저장
    -- /////////////////////////////////////////////////////////////////
    V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_VERSION_DIVISION, V_DELIMITER));

    WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

        V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

        V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_VERSION_DIVISION, V_DELIMITER, V_MST_LOOP_CNT);

        INSERT INTO SCM_MASTER_VERSION_INFO_H_SN
                  ( VERSION_ID
                  , VERSION_NAME
                  , DIVISION_ID
                  , SCP_USE_FLAG
                  , BP_USE_FLAG
                  , RP_USE_FLAG
                  , SYSTEM1_USE_FLAG
                  , SYSTEM2_USE_FLAG
                  , SYSTEM3_USE_FLAG
                  , PROGRESS
                  , DESCRIPTION
                  , INSERT_ID
                  , INSERT_TIME
                  )
             VALUES
                  ( V_NEW_VERSION_ID
                  , P_VERSION_NAME
                  , V_DIVISION_ID
                  , P_CHK_SCP
                  , P_CHK_BP
                  , P_CHK_RP
                  , NULL
                  , NULL
                  , NULL
                  , V_PROGRESS
                  , NULL
                  , P_UPDATE_ID
                  , SYSDATE
                  )
        ;

    END LOOP;

    -- /////////////////////////////////////////////////////////////////
    -- 기준 데이터 생성
    -- 전극 포함이면 전체 DIVISION 저장 , 그외 해당 DIVISION 만 저장 한다
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO GT_SCP0049_VER_STD
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , OPERATION_GROUP_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              )
    SELECT DISTINCT
           DIVISION_ID
         , COMPANY_ID
         , SITE_ID
         , PLANT_ID
         , OPERATION_GROUP_ID
         , FACTORY_ID
         , OPERATION_ID
         , LINE_ID
         , ELECTRODE_TYPE
      FROM SCM_LINE_HIERARCHY_V_SN
     WHERE ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    /* ############################################################ */
    /* AS-IS 는 아래 세 임시테이블을 만들기만 하고 이 프로시저 안에서 다시 읽지 않는다(사용처 없음). */
    /*   #TMP_SCP0049_VER_STD_ITEM        : 기준 ITEM 데이터 생성 */
    /*   #TMP_SCP0049_VER_STD_ITEM_TACT   : 기준 ITEM 데이터 생성(TACT TIME) */
    /*   #TMP_SCP0049_VER_STD_ITEM_YIELD  : 기준 ITEM 데이터 생성( YIELD) */
    /* 저장 결과에 영향이 없고 대량 조인만 유발하므로 옮기지 않는다. */
    /* ############################################################ */

    -- /////////////////////////////////////////////////////////////////
    -- SCM_WORK_CALENDAR_M 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_WORK_CAL_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , WORK_DATE
              , LOSS_CODE
              , TIME_TERM
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.WORK_DATE
         , A.LOSS_CODE
         , A.TIME_TERM
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_WORK_CALENDAR_M_SN A
         , SCM_LINE_M_SN B
     WHERE A.COMPANY_ID     = B.COMPANY_ID
       AND A.DIVISION_ID    = B.DIVISION_ID
       AND A.SITE_ID        = B.SITE_ID
       AND A.PLANT_ID       = B.PLANT_ID
       AND A.FACTORY_ID     = B.FACTORY_ID
       AND A.OPERATION_ID   = B.OPERATION_ID
       AND A.LINE_ID        = B.LINE_ID
       AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
       AND B.ACTIVE_FLAG    = 'Y'                          -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
       AND TO_CHAR(A.WORK_DATE, 'YYYYMM') >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_LOSS_M_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_LOSS_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , WORK_MONTH
              , LOSS_CODE
              , LOSS_RATE
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.WORK_MONTH
         , A.LOSS_CODE
         , A.LOSS_RATE
         , A.DESCRIPTION
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_LOSS_M_SN A
         , SCM_LINE_M_SN B
     WHERE A.COMPANY_ID     = B.COMPANY_ID
       AND A.DIVISION_ID    = B.DIVISION_ID
       AND A.SITE_ID        = B.SITE_ID
       AND A.PLANT_ID       = B.PLANT_ID
       AND A.FACTORY_ID     = B.FACTORY_ID
       AND A.OPERATION_ID   = B.OPERATION_ID
       AND A.LINE_ID        = B.LINE_ID
       AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
       AND B.ACTIVE_FLAG    = 'Y'                          -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
       AND A.WORK_MONTH    >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_MST_ITEM_LINE_ASSIGN_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_ITEM_LINE_ASSIGN_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , MONTH
              , LANE_QTY
              , WORK_CENTER_ID
              , PRIORITY
              , CERTIFICATION_DATE
              , ACTIVE_FLAG
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT COMPANY_ID
         , DIVISION_ID
         , SITE_ID
         , PLANT_ID
         , FACTORY_ID
         , ITEM_ID
         , OPERATION_ID
         , LINE_ID
         , ELECTRODE_TYPE
         , MONTH
         , LANE_QTY
         , WORK_CENTER_ID
         , PRIORITY
         , CERTIFICATION_DATE
         , ACTIVE_FLAG
         , DESCRIPTION
         , INSERT_ID
         , INSERT_TIME
         , UPDATE_ID
         , UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_ITEM_LINE_ASSIGN_SN
     WHERE MONTH >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_LINE_ASSIGN_EXCT_VER_H_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_LINE_ASSIGN_EXCT_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , ITEM_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , WORK_CENTER_ID
              , PRIORITY
              , START_TIME
              , END_TIME
              , DESCRIPTION
              , ACTIVE_FLAG
              , LANE_QTY
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT COMPANY_ID
         , DIVISION_ID
         , SITE_ID
         , PLANT_ID
         , FACTORY_ID
         , ITEM_ID
         , OPERATION_ID
         , LINE_ID
         , ELECTRODE_TYPE
         , WORK_CENTER_ID
         , PRIORITY
         , START_TIME
         , END_TIME
         , DESCRIPTION
         , ACTIVE_FLAG
         , LANE_QTY
         , INSERT_ID
         , INSERT_TIME
         , UPDATE_ID
         , UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN
     WHERE TO_CHAR(START_TIME, 'YYYYMM') >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_TACT_TIME_VER_H 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_TACT_TIME_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , ITEM_ID
              , MONTH
              , WORK_CENTER_ID
              , TACT_TIME
              , TACT_TIME_UOM
              , DAILY_CAPA
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.ITEM_ID
         , A.MONTH
         , A.WORK_CENTER_ID
         , A.TACT_TIME
         , A.TACT_TIME_UOM
         , A.DAILY_CAPA
         , A.DESCRIPTION
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_TACT_TIME_SN A
         , SCM_LINE_M_SN B
     WHERE A.COMPANY_ID     = B.COMPANY_ID
       AND A.DIVISION_ID    = B.DIVISION_ID
       AND A.SITE_ID        = B.SITE_ID
       AND A.PLANT_ID       = B.PLANT_ID
       AND A.FACTORY_ID     = B.FACTORY_ID
       AND A.OPERATION_ID   = B.OPERATION_ID
       AND A.LINE_ID        = B.LINE_ID
       AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
       AND B.ACTIVE_FLAG    = 'Y'                          -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
       AND A.MONTH         >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_TACT_TIME_EXCT_VER_H_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_TACT_TIME_EXCT_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , ITEM_ID
              , WORK_CENTER_ID
              , TACT_TIME
              , TACT_TIME_UOM
              , DAILY_CAPA
              , START_TIME
              , END_TIME
              , ACTIVE_FLAG
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.ITEM_ID
         , A.WORK_CENTER_ID
         , A.TACT_TIME
         , A.TACT_TIME_UOM
         , A.DAILY_CAPA
         , A.START_TIME
         , A.END_TIME
         , A.ACTIVE_FLAG
         , A.DESCRIPTION
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_TACT_TIME_EXCEPT_SN A
         , SCM_LINE_M_SN B
     WHERE A.COMPANY_ID     = B.COMPANY_ID
       AND A.DIVISION_ID    = B.DIVISION_ID
       AND A.SITE_ID        = B.SITE_ID
       AND A.PLANT_ID       = B.PLANT_ID
       AND A.FACTORY_ID     = B.FACTORY_ID
       AND A.OPERATION_ID   = B.OPERATION_ID
       AND A.LINE_ID        = B.LINE_ID
       AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
       AND B.ACTIVE_FLAG    = 'Y'                          -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
       AND TO_CHAR(A.START_TIME, 'YYYYMM') >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_YIELD_VER_H_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_YIELD_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ITEM_ID
              , MONTH
              , WORK_CENTER_ID
              , YIELD
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ITEM_ID
         , A.MONTH
         , A.WORK_CENTER_ID
         , A.YIELD
         , A.DESCRIPTION
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_YIELD_SN A
         , (SELECT COMPANY_ID
                 , DIVISION_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , OPERATION_ID
                 , LINE_ID
              FROM SCM_LINE_M_SN
             WHERE ACTIVE_FLAG = 'Y'                       -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
             GROUP BY COMPANY_ID
                    , DIVISION_ID
                    , SITE_ID
                    , PLANT_ID
                    , FACTORY_ID
                    , OPERATION_ID
                    , LINE_ID
           ) IA
     WHERE A.COMPANY_ID   = IA.COMPANY_ID
       AND A.DIVISION_ID  = IA.DIVISION_ID
       AND A.SITE_ID      = IA.SITE_ID
       AND A.PLANT_ID     = IA.PLANT_ID
       AND A.FACTORY_ID   = IA.FACTORY_ID
       AND A.OPERATION_ID = IA.OPERATION_ID
       AND A.LINE_ID      = IA.LINE_ID
       AND A.MONTH       >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_YIELD_EXCT_VER_H_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_YIELD_EXCT_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ITEM_ID
              , WORK_CENTER_ID
              , YIELD
              , START_TIME
              , END_TIME
              , ACTIVE_FLAG
              , DESCRIPTION
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT A.COMPANY_ID
         , A.DIVISION_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.OPERATION_ID
         , A.LINE_ID
         , A.ITEM_ID
         , A.WORK_CENTER_ID
         , A.YIELD
         , A.START_TIME
         , A.END_TIME
         , A.ACTIVE_FLAG
         , A.DESCRIPTION
         , A.INSERT_ID
         , A.INSERT_TIME
         , A.UPDATE_ID
         , A.UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MST_YIELD_EXCEPT_SN A
         , (SELECT COMPANY_ID
                 , DIVISION_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , OPERATION_ID
                 , LINE_ID
              FROM SCM_LINE_M_SN
             WHERE ACTIVE_FLAG = 'Y'                       -- [ES20240109-00456] 비활성화 라인 정보 생성 수정 요청
             GROUP BY COMPANY_ID
                    , DIVISION_ID
                    , SITE_ID
                    , PLANT_ID
                    , FACTORY_ID
                    , OPERATION_ID
                    , LINE_ID
           ) IA
     WHERE A.COMPANY_ID   = IA.COMPANY_ID
       AND A.DIVISION_ID  = IA.DIVISION_ID
       AND A.SITE_ID      = IA.SITE_ID
       AND A.PLANT_ID     = IA.PLANT_ID
       AND A.FACTORY_ID   = IA.FACTORY_ID
       AND A.OPERATION_ID = IA.OPERATION_ID
       AND A.LINE_ID      = IA.LINE_ID
       AND TO_CHAR(A.START_TIME, 'YYYYMM') >= V_START_MONTH
       AND ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR A.DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    -- SCM_MASTER_MANAGER_VER_H_SN 정보 생성
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO SCM_MASTER_MANAGER_VER_H_SN
              ( COMPANY_ID
              , DIVISION_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , OPERATION_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , LOSS_CODE
              , USER_ID_1
              , USER_ID_2
              , USER_ID_3
              , USER_ID_4
              , USER_ID_5
              , USER_ID_6
              , USER_ID_7
              , USER_ID_8
              , USER_ID_9
              , USER_ID_10
              , DESCRIPTION
              , CONFIRM_FLAG
              , CONFIRM_ID
              , CONFIRM_TIME
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              , VERSION_ID
              , RELEASE_TIME
              )
    SELECT COMPANY_ID
         , DIVISION_ID
         , SITE_ID
         , PLANT_ID
         , FACTORY_ID
         , OPERATION_ID
         , LINE_ID
         , ELECTRODE_TYPE
         , LOSS_CODE
         , USER_ID_1
         , USER_ID_2
         , USER_ID_3
         , USER_ID_4
         , USER_ID_5
         , USER_ID_6
         , USER_ID_7
         , USER_ID_8
         , USER_ID_9
         , USER_ID_10
         , DESCRIPTION
         , CONFIRM_FLAG
         , CONFIRM_ID
         , CONFIRM_TIME
         , INSERT_ID
         , INSERT_TIME
         , UPDATE_ID
         , UPDATE_TIME
         , V_NEW_VERSION_ID
         , SYSDATE
      FROM SCM_MASTER_MANAGER_M_SN
     WHERE ( CASE WHEN INSTR(P_VERSION_DIVISION, 'EE') > 0 THEN 'Y' ELSE 'N' END = 'Y'
             OR DIVISION_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(P_VERSION_DIVISION, ',')))
           )
    ;

    -- /////////////////////////////////////////////////////////////////
    --  LOSS 계산을 위한 월별 데이터 조회
    -- /////////////////////////////////////////////////////////////////
    INSERT INTO GT_SCP0049_VER_MM
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , LOSS_CODE
              , YYYYMM
              , ITEM_VALUE
              )
    SELECT B.DIVISION_ID
         , B.COMPANY_ID
         , B.SITE_ID
         , B.PLANT_ID
         , B.FACTORY_ID
         , B.LINE_ID
         , B.ELECTRODE_TYPE
         , B.OPERATION_ID
         , B.LOSS_CODE
         , TO_CHAR(B.WORK_DATE, 'YYYYMM')       AS YYYYMM
         , SUM(B.TIME_TERM)                     AS ITEM_VALUE
      FROM GT_SCP0049_VER_LOOKUP A
         , SCM_WORK_CALENDAR_M_SN B
         , GT_SCP0049_VER_STD C
     WHERE B.LOSS_CODE        = A.LOSS_CODE
       AND B.DIVISION_ID      = C.DIVISION_ID
       AND B.COMPANY_ID       = C.COMPANY_ID
       AND B.SITE_ID          = C.SITE_ID
       AND B.PLANT_ID         = C.PLANT_ID
       AND B.FACTORY_ID       = C.FACTORY_ID
       AND B.OPERATION_ID     = C.OPERATION_ID
       AND B.LINE_ID          = C.LINE_ID
       AND B.ELECTRODE_TYPE   = C.ELECTRODE_TYPE
       AND A.DATA_TABLE       = 'SCM_WORK_CALENDAR_M'
       AND TO_CHAR(B.WORK_DATE, 'YYYYMM') >= V_START_MONTH  -- '202008'
       AND TO_CHAR(B.WORK_DATE, 'YYYYMM') <= V_END_MONTH    -- '202106'
     GROUP BY B.COMPANY_ID
            , B.DIVISION_ID
            , B.SITE_ID
            , B.PLANT_ID
            , B.FACTORY_ID
            , B.OPERATION_ID
            , B.LINE_ID
            , B.ELECTRODE_TYPE
            , B.LOSS_CODE
            , TO_CHAR(B.WORK_DATE, 'YYYYMM')
    UNION ALL
    -- SCM_LOSS_M_SN
    SELECT E.DIVISION_ID
         , E.COMPANY_ID                         AS COMPANY_ID
         , E.SITE_ID                            AS SITE_ID
         , E.PLANT_ID                           AS PLANT_ID
         , E.FACTORY_ID                         AS FACTORY_ID
         , E.LINE_ID                            AS LINE_ID
         , E.ELECTRODE_TYPE                     AS ELECTRODE_TYPE
         , E.OPERATION_ID                       AS OPERATION_ID
         , D.LOSS_CODE                          AS LOSS_CODE
         , E.WORK_MONTH                         AS YYYYMM
         , NVL(ROUND(E.LOSS_RATE * 100, 2), 0)  AS ITEM_VALUE
      FROM GT_SCP0049_VER_LOOKUP D
         , SCM_LOSS_M_SN E
         , GT_SCP0049_VER_STD F
     WHERE E.LOSS_CODE        = D.LOSS_CODE
       AND E.DIVISION_ID      = F.DIVISION_ID
       AND E.COMPANY_ID       = F.COMPANY_ID
       AND E.SITE_ID          = F.SITE_ID
       AND E.PLANT_ID         = F.PLANT_ID
       AND E.FACTORY_ID       = F.FACTORY_ID
       AND E.OPERATION_ID     = F.OPERATION_ID
       AND E.LINE_ID          = F.LINE_ID
       AND E.ELECTRODE_TYPE   = F.ELECTRODE_TYPE
       AND D.LOSS_CODE       <> 'M08'
       AND D.DATA_TABLE       = 'SCM_LOSS_M'
       AND E.WORK_MONTH      >= V_START_MONTH
       AND E.WORK_MONTH      <= V_END_MONTH
    ;
    -- // 현재(Current) LOSS

    -- /////////////////////////////////////////////////////////////////
    --  LOSS Available(%) , Loading(%) , Operating(%) , OEE(%) 계산 로직 추가
    -- /////////////////////////////////////////////////////////////////
    -- ##############################################################
    -- 1. SUM 값 (NON OPERATION,NO_ROAD,NO_RUN_NOT_PM,NO_RUN_PM)
    -- ##############################################################
    INSERT INTO GT_SCP0049_VER_STD_SUM
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , YYYYMM
              , NON_OPERATION_VALUE
              , NO_LOAD_VALUE
              , NO_RUN_NOT_PM_VALUE
              , NO_RUN_PM_VALUE
              )
    SELECT A.DIVISION_ID
         , A.COMPANY_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.OPERATION_ID
         , A.YYYYMM
         , SUM(CASE WHEN B.CATEGORY_ID = 'Not-Available'                THEN A.ITEM_VALUE ELSE 0 END ) AS NON_OPERATION_VALUE
         , SUM(CASE WHEN B.CATEGORY_ID = 'No-Load'                      THEN A.ITEM_VALUE ELSE 0 END ) AS NO_LOAD_VALUE
         , SUM(CASE WHEN B.CATEGORY_ID = 'No-Run' AND B.KEY_ID <> 'PM'  THEN A.ITEM_VALUE ELSE 0 END ) AS NO_RUN_NOT_PM_VALUE
         , SUM(CASE WHEN B.CATEGORY_ID = 'No-Run' AND B.KEY_ID =  'PM'  THEN A.ITEM_VALUE ELSE 0 END ) AS NO_RUN_PM_VALUE
      FROM GT_SCP0049_VER_MM A
         , GT_SCP0049_VER_LOOKUP B
     WHERE A.LOSS_CODE     = B.LOSS_CODE
       AND B.LOSS_CODE NOT LIKE 'X%'
     GROUP BY A.DIVISION_ID
            , A.COMPANY_ID
            , A.SITE_ID
            , A.PLANT_ID
            , A.FACTORY_ID
            , A.LINE_ID
            , A.ELECTRODE_TYPE
            , A.OPERATION_ID
            , A.YYYYMM
    ;

    -- ##############################################################
    -- 2. Available(%)
    -- ##############################################################
    /* AS-IS SET ARITHIGNORE ON : 0 으로 나누면 오류가 아니라 NULL 이므로 CASE 로 가른다 */
    INSERT INTO GT_SCP0049_VER_STD_CAL
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , YYYYMM
              , ITEM_VALUE
              , LOSS_CODE
              )
    SELECT A.DIVISION_ID
         , A.COMPANY_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.OPERATION_ID
         , A.YYYYMM
         , CASE WHEN B.WORKING_TIME = 0 THEN NULL
                ELSE (B.WORKING_TIME - A.NON_OPERATION_VALUE) / B.WORKING_TIME * 100
            END                AS AVAILABLE
         , 'XB021'
      FROM GT_SCP0049_VER_STD_SUM A
         , GT_SCP0049_VER_DAY_OF_MONTH B
     WHERE A.YYYYMM = B.YYYYMM
    ;

    -- ##############################################################
    -- 3. Loading(%)
    -- ##############################################################
    INSERT INTO GT_SCP0049_VER_STD_CAL
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , YYYYMM
              , ITEM_VALUE
              , LOSS_CODE
              )
    SELECT A.DIVISION_ID
         , A.COMPANY_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.OPERATION_ID
         , A.YYYYMM
         , CASE WHEN (B.WORKING_TIME - A.NON_OPERATION_VALUE) = 0 THEN NULL
                ELSE ( (B.WORKING_TIME - ( A.NON_OPERATION_VALUE + A.NO_LOAD_VALUE) ) / (B.WORKING_TIME - A.NON_OPERATION_VALUE ) ) * 100
            END                AS LOADING
         , 'XC042'
      FROM GT_SCP0049_VER_STD_SUM A
         , GT_SCP0049_VER_DAY_OF_MONTH B
     WHERE A.YYYYMM = B.YYYYMM
    ;

    -- ##############################################################
    -- 4. Operating(%)
    -- ##############################################################
    INSERT INTO GT_SCP0049_VER_STD_CAL
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , YYYYMM
              , ITEM_VALUE
              , LOSS_CODE
              )
    SELECT A.DIVISION_ID
         , A.COMPANY_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.OPERATION_ID
         , A.YYYYMM
         , CASE WHEN (B.WORKING_TIME - (A.NON_OPERATION_VALUE + A.NO_LOAD_VALUE)) = 0 THEN NULL
                ELSE 100 - (A.NO_RUN_NOT_PM_VALUE + ( A.NO_RUN_PM_VALUE / ( B.WORKING_TIME - (A.NON_OPERATION_VALUE + A.NO_LOAD_VALUE) ) * 100) )
            END                AS OPERATING
         , 'M08'
      FROM GT_SCP0049_VER_STD_SUM A
         , GT_SCP0049_VER_DAY_OF_MONTH B
     WHERE A.YYYYMM = B.YYYYMM
    ;

    -- ##############################################################
    -- 5. OEE(%)
    -- ##############################################################
    /* AS-IS SET ARITHIGNORE ON : LOG(0) 이 오류가 아니라 NULL 이고 SUM 이 NULL 을 건너뛰므로 CASE 로 가른다 */
    INSERT INTO GT_SCP0049_VER_STD_CAL
              ( DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , YYYYMM
              , ITEM_VALUE
              , LOSS_CODE
              )
    SELECT A.DIVISION_ID
         , A.COMPANY_ID
         , A.SITE_ID
         , A.PLANT_ID
         , A.FACTORY_ID
         , A.LINE_ID
         , A.ELECTRODE_TYPE
         , A.OPERATION_ID
         , A.YYYYMM
         , NVL((EXP(SUM(CASE WHEN C.ITEM_VALUE > 0 THEN LN(C.ITEM_VALUE) END)) * NVL(A.ITEM_VALUE, 1) ) / 10000, 0 ) AS OEE
         , 'XD101'
      FROM GT_SCP0049_VER_STD_CAL A
         , GT_SCP0049_VER_DAY_OF_MONTH B
         , (SELECT DIVISION_ID                             /* (+) 는 IN 의 피연산자로 쓸 수 없어 인라인 뷰로 옮긴다 */
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , YYYYMM
                 , ITEM_VALUE
              FROM GT_SCP0049_VER_MM
             --WHERE LOSS_CODE		IN ( 'M10','M11')
             WHERE LOSS_CODE IN ( 'M10','M12')             -- M11 => M12 로 변경
           ) C
     WHERE A.YYYYMM         = B.YYYYMM
       AND A.DIVISION_ID    = C.DIVISION_ID(+)
       AND A.COMPANY_ID     = C.COMPANY_ID(+)
       AND A.SITE_ID        = C.SITE_ID(+)
       AND A.PLANT_ID       = C.PLANT_ID(+)
       AND A.FACTORY_ID     = C.FACTORY_ID(+)
       AND A.LINE_ID        = C.LINE_ID(+)
       AND A.ELECTRODE_TYPE = C.ELECTRODE_TYPE(+)
       AND A.OPERATION_ID   = C.OPERATION_ID(+)
       AND A.YYYYMM         = C.YYYYMM(+)
       AND A.LOSS_CODE      = 'M08'
     GROUP BY A.DIVISION_ID
            , A.COMPANY_ID
            , A.SITE_ID
            , A.PLANT_ID
            , A.FACTORY_ID
            , A.LINE_ID
            , A.ELECTRODE_TYPE
            , A.OPERATION_ID
            , A.YYYYMM
            , A.ITEM_VALUE
    ;

    -- ##############################################################
    -- 6. 데이터 저장
    -- ##############################################################
    INSERT INTO SCM_LOSS_REPORT_VER_H_SN
              ( VERSION_ID
              , DIVISION_ID
              , COMPANY_ID
              , SITE_ID
              , PLANT_ID
              , FACTORY_ID
              , LINE_ID
              , ELECTRODE_TYPE
              , OPERATION_ID
              , WORK_MONTH
              , LOSS_CODE
              , LOSS_RATE
              , INSERT_ID
              , INSERT_TIME
              , UPDATE_ID
              , UPDATE_TIME
              )
    SELECT V_NEW_VERSION_ID      AS VERSION_ID
         , DIVISION_ID
         , COMPANY_ID
         , SITE_ID
         , PLANT_ID
         , FACTORY_ID
         , LINE_ID
         , ELECTRODE_TYPE
         , OPERATION_ID
         , YYYYMM
         , LOSS_CODE
         , ITEM_VALUE
         , P_UPDATE_ID
         , SYSDATE
         , P_UPDATE_ID
         , SYSDATE
      FROM GT_SCP0049_VER_STD_CAL
     WHERE ITEM_VALUE IS NOT NULL
    ;

    COMMIT;

    -- 결과코드 반환
    OPEN O_RESULT_CURSOR FOR
         SELECT 'S'            AS RESULT_CODE
              , CAST(NULL AS VARCHAR2(4000)) AS ERR_MESSAGE
           FROM DUAL
    ;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

  EXCEPTION
    WHEN OTHERS THEN

      /* AS-IS BEGIN CATCH : if (xact_state() <> 0) ROLLBACK TRAN; --입력 데이타 롤백 처리 */
      V_ERR_MESSAGE := '[' || TO_CHAR(SQLCODE) || ']' || SQLERRM;

      ROLLBACK TO SAVEPOINT SP_SCP0049_SAVE_NEW_VER;

      /* AS-IS 의 scm_sys_log_batch 직접 INSERT 는 자율 트랜잭션 로그 프로시저로 대체 */
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, SQLERRM, NULL, SYSDATE, NULL
                         , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

      -- error코드, errror 메시지 반환
      OPEN O_RESULT_CURSOR FOR
           SELECT 'F'              AS RESULT_CODE
                , V_ERR_MESSAGE    AS ERR_MESSAGE
             FROM DUAL
      ;

      /* 종료 LOG */
      V_LOG_TYPE    := 'END';
      V_LOG_MESSAGE := '########## END of procedure ##########';
      V_DESCRIPTION := '';
      D_EVENT_DATE  := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

  END P_SAVE_NEW_VERSION;

/*
     * Program ID   : SCP0049
     * Description  : SCP MAIL 발송 (Master < Supply Master < Capa ( NewModel Popup 요청)
     * Program History
     *===================================================================================================
     *   Date       In Charge		Description
     *===================================================================================================
     * 2021/03/26   khj79      최초작성
     * 2021/06/15   khj79      최초작성 - USER_ID_2 ~ USER_ID_10 추가 메일 발송
     * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */
    PROCEDURE P_SAVE_MAIL_SEND_REQUEST
    (
        P_DIVISION_ID       IN  VARCHAR2
      , P_COMPANY_ID        IN  VARCHAR2
      , P_SITE_ID           IN  VARCHAR2
      , P_PLANT_ID          IN  VARCHAR2
      , P_FACTORY_ID        IN  VARCHAR2
      , P_OPERATION_ID      IN  VARCHAR2
      , P_LINE_ID           IN  VARCHAR2
      , P_ELECTRODE_TYPE    IN  VARCHAR2
      , P_ITEM_ID           IN  VARCHAR2
      , P_LANE_QTY          IN  VARCHAR2
      , P_LOSS_CODE         IN  VARCHAR2
      , P_UPDATE_ID         IN  VARCHAR2
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS

        V_DELIMITER         VARCHAR2(1 CHAR);

        -- mail 전송을 위한 변수 설정
        V_TOKEN_CNT         NUMBER(10);

        -- LOG 용 변수 설정
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0049_SAVE_MAIL_SEND_REQUEST';
        V_LOG_TYPE          VARCHAR2(30 CHAR);
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;
        V_ERR               VARCHAR2(4000 CHAR);

    BEGIN

        V_DELIMITER := '^';

        -- 시작 LOG
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        SAVEPOINT SP_SAVE_MAIL_SEND_REQUEST;

        /* 구분자로 나눈 토큰 개수 — AS-IS 는 각 인자를 따로 나눈 뒤 NR 로 내부조인하므로
           인자별 토큰 개수의 최소값이 결과 행 수가 된다 */
        V_TOKEN_CNT := LEAST(CASE WHEN P_DIVISION_ID    IS NULL THEN 0 ELSE LENGTH(P_DIVISION_ID)    - LENGTH(REPLACE(P_DIVISION_ID   , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_COMPANY_ID     IS NULL THEN 0 ELSE LENGTH(P_COMPANY_ID)     - LENGTH(REPLACE(P_COMPANY_ID    , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_SITE_ID        IS NULL THEN 0 ELSE LENGTH(P_SITE_ID)        - LENGTH(REPLACE(P_SITE_ID       , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_PLANT_ID       IS NULL THEN 0 ELSE LENGTH(P_PLANT_ID)       - LENGTH(REPLACE(P_PLANT_ID      , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_FACTORY_ID     IS NULL THEN 0 ELSE LENGTH(P_FACTORY_ID)     - LENGTH(REPLACE(P_FACTORY_ID    , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_LINE_ID        IS NULL THEN 0 ELSE LENGTH(P_LINE_ID)        - LENGTH(REPLACE(P_LINE_ID       , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_ELECTRODE_TYPE IS NULL THEN 0 ELSE LENGTH(P_ELECTRODE_TYPE) - LENGTH(REPLACE(P_ELECTRODE_TYPE, V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_OPERATION_ID   IS NULL THEN 0 ELSE LENGTH(P_OPERATION_ID)   - LENGTH(REPLACE(P_OPERATION_ID  , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_ITEM_ID        IS NULL THEN 0 ELSE LENGTH(P_ITEM_ID)        - LENGTH(REPLACE(P_ITEM_ID       , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_LANE_QTY       IS NULL THEN 0 ELSE LENGTH(P_LANE_QTY)       - LENGTH(REPLACE(P_LANE_QTY      , V_DELIMITER, '')) + 1 END
                           , CASE WHEN P_LOSS_CODE      IS NULL THEN 0 ELSE LENGTH(P_LOSS_CODE)      - LENGTH(REPLACE(P_LOSS_CODE     , V_DELIMITER, '')) + 1 END);

        /* ★CONNECT BY LEVEL <= 0 은 0행이 아니라 1행을 낸다 — 토큰이 없을 때
           엉뚱한 한 행이 들어가지 않도록 여기서 먼저 가른다 */
        IF V_TOKEN_CNT > 0 THEN

            -- 요청 정보를 임시 테이블에 저장
            INSERT INTO SCM_CAPA_MAIL_SEND_H_SN
                 (
                   DIVISION_ID
                 , COMPANY_ID
                 , SITE_ID
                 , PLANT_ID
                 , FACTORY_ID
                 , LINE_ID
                 , ELECTRODE_TYPE
                 , OPERATION_ID
                 , ITEM_ID
                 , LANE_QTY
                 , LOSS_CODE
                 , SEND_USER_ID
                 , MAIL_SEND_YN
                 , MAIL_REQUEST_TIME
                 )
            SELECT NVL(SCM_ARR_SPL_VAL(P_DIVISION_ID    , V_DELIMITER, NR), '-')   AS DIVISION_ID
                 , NVL(SCM_ARR_SPL_VAL(P_COMPANY_ID     , V_DELIMITER, NR), '-')   AS COMPANY_ID
                 , NVL(SCM_ARR_SPL_VAL(P_SITE_ID        , V_DELIMITER, NR), '-')   AS SITE_ID
                 , NVL(SCM_ARR_SPL_VAL(P_PLANT_ID       , V_DELIMITER, NR), '-')   AS PLANT_ID
                 , NVL(SCM_ARR_SPL_VAL(P_FACTORY_ID     , V_DELIMITER, NR), '-')   AS FACTORY_ID
                 , NVL(SCM_ARR_SPL_VAL(P_LINE_ID        , V_DELIMITER, NR), '-')   AS LINE_ID
                 , NVL(SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE , V_DELIMITER, NR), '-')   AS ELECTRODE_TYPE
                 , NVL(SCM_ARR_SPL_VAL(P_OPERATION_ID   , V_DELIMITER, NR), '-')   AS OPERATION_ID
                 , NVL(SCM_ARR_SPL_VAL(P_ITEM_ID        , V_DELIMITER, NR), '-')   AS ITEM_ID
                 , CASE
                       WHEN SCM_ARR_SPL_VAL(P_LANE_QTY, V_DELIMITER, NR) = '-'
                         OR SCM_ARR_SPL_VAL(P_LANE_QTY, V_DELIMITER, NR) IS NULL THEN 0.0
                       ELSE TO_NUMBER(SCM_ARR_SPL_VAL(P_LANE_QTY, V_DELIMITER, NR))
                   END                                                             AS LANE_QTY
                 , NVL(SCM_ARR_SPL_VAL(P_LOSS_CODE      , V_DELIMITER, NR), '-')   AS LOSS_CODE
                 , P_UPDATE_ID                                                     AS SEND_USER_ID
                 , 'N'                                                             AS MAIL_SEND_YN
                 , SYSDATE                                                         AS MAIL_SEND_TIME
              FROM (
                    SELECT LEVEL AS NR
                      FROM DUAL
                   CONNECT BY LEVEL <= V_TOKEN_CNT
                   ) IA;

        END IF;

        -- 사용자 정보 INSERT(PIC 에 등록된 사용자 중 USER_ID_1 을 제외한 사용자)
        INSERT INTO SCM_CAPA_MAIL_SEND_H_SN
             (
               DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , LOSS_CODE
             , LANE_QTY
             , SEND_USER_ID
             , RECV_USER_ID
             , MAIL_SEND_YN
             , MAIL_REQUEST_TIME
             )
        SELECT DISTINCT DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , ITEM_ID
             , OPERATION_ID
             , LINE_ID
             , ELECTRODE_TYPE
             , LOSS_CODE
             , LANE_QTY
             , SEND_USER_ID
             , USER_INFO_DATA
             , 'N'          -- MAIL_SEND_YN
             , SYSDATE      -- MAIL_SEND_TIME
          FROM (
                SELECT A.DIVISION_ID
                     , A.COMPANY_ID
                     , A.SITE_ID
                     , A.PLANT_ID
                     , A.FACTORY_ID
                     , B.ITEM_ID
                     , A.OPERATION_ID
                     , A.LINE_ID
                     , A.ELECTRODE_TYPE
                     , A.LOSS_CODE
                     , B.LANE_QTY
                     , B.SEND_USER_ID
                     , A.USER_ID_2
                     , A.USER_ID_3
                     , A.USER_ID_4
                     , A.USER_ID_5
                     , A.USER_ID_6
                     , A.USER_ID_7
                     , A.USER_ID_8
                     , A.USER_ID_9
                     , A.USER_ID_10
                  FROM SCM_MASTER_MANAGER_M_SN A
                     , SCM_CAPA_MAIL_SEND_H_SN B
                 WHERE A.LINE_ID        = B.LINE_ID
                   AND A.OPERATION_ID   = B.OPERATION_ID
                   AND A.ELECTRODE_TYPE = B.ELECTRODE_TYPE
                   AND A.LOSS_CODE      = B.LOSS_CODE
                   AND NVL(B.MAIL_SEND_YN, 'N') = 'N'
               )
        UNPIVOT ( USER_INFO_DATA FOR COLUMN_NAME IN ( USER_ID_2
                                                    , USER_ID_3
                                                    , USER_ID_4
                                                    , USER_ID_5
                                                    , USER_ID_6
                                                    , USER_ID_7
                                                    , USER_ID_8
                                                    , USER_ID_9
                                                    , USER_ID_10) )
         WHERE USER_INFO_DATA IS NOT NULL
           /* AS-IS <> 빈값 — 이관 시 빈값이 공백 한 칸 또는 '-' 로 채워진 행까지 같은 갈래로 본다 */
           AND TRIM(USER_INFO_DATA) IS NOT NULL
           AND USER_INFO_DATA <> '-';

        /* 사용자 정보 UPDATE(PIC 에 등록된 USER_ID_1 사용자)
           AS-IS 의 UPDATE … FROM JOIN 은 Oracle 에서 ORA-01779 이므로 상관 서브쿼리로 옮긴다.
           담당자 원장에 같은 열쇠가 여러 행이면 AS-IS 는 그중 하나를 임의로 쓰는데
           Oracle 상관 서브쿼리는 ORA-01427 이 되므로 MAX 로 한 값을 고정한다 */
        UPDATE SCM_CAPA_MAIL_SEND_H_SN A
           SET A.RECV_USER_ID = (
                                 SELECT MAX(B.USER_ID_1)
                                   FROM SCM_MASTER_MANAGER_M_SN B
                                  WHERE B.DIVISION_ID    = A.DIVISION_ID
                                    AND B.COMPANY_ID     = A.COMPANY_ID
                                    AND B.SITE_ID        = A.SITE_ID
                                    AND B.PLANT_ID       = A.PLANT_ID
                                    AND B.FACTORY_ID     = A.FACTORY_ID
                                    AND B.OPERATION_ID   = A.OPERATION_ID
                                    AND B.LINE_ID        = A.LINE_ID
                                    AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                    AND B.LOSS_CODE      = A.LOSS_CODE
                                )
         WHERE EXISTS (
                       SELECT 1
                         FROM SCM_MASTER_MANAGER_M_SN B
                        WHERE B.DIVISION_ID    = A.DIVISION_ID
                          AND B.COMPANY_ID     = A.COMPANY_ID
                          AND B.SITE_ID        = A.SITE_ID
                          AND B.PLANT_ID       = A.PLANT_ID
                          AND B.FACTORY_ID     = A.FACTORY_ID
                          AND B.OPERATION_ID   = A.OPERATION_ID
                          AND B.LINE_ID        = A.LINE_ID
                          AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                          AND B.LOSS_CODE      = A.LOSS_CODE
                      )
           AND NVL(A.MAIL_SEND_YN, 'N') = 'N'
           AND A.RECV_USER_ID IS NULL;

        -- 종료 LOG
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        -- 결과 코드 반환
        OPEN O_RESULT_CURSOR FOR
            SELECT 'S' AS RESULT_CODE
              FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            /* SQLERRM 은 SQL 문 안에서 직접 쓸 수 없어 변수로 받는다 */
            V_ERR := SQLERRM;

            /* AS-IS CATCH 는 오류 내용을 기록한 뒤 열린 트랜잭션을 COMMIT 한다 — 동작을 그대로 옮긴다 */
            INSERT INTO SCM_SYS_LOG_BATCH
                 (
                   PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 )
            VALUES
                 (
                   V_PROGRAM_NAME
                 , 'ERROR'
                 , NULL
                 , V_ERR
                 , NULL
                 , SYSDATE
                 , SYSDATE
                 , V_PROGRAM_NAME
                 , SYSDATE
                 , V_PROGRAM_NAME
                 );

            IF DBMS_TRANSACTION.LOCAL_TRANSACTION_ID IS NOT NULL THEN
                COMMIT;
            END IF;

    END P_SAVE_MAIL_SEND_REQUEST;

/*==============================================================================================
     * Program ID   : PKG_SCP0049.P_CAPA_EXCEL_UPLOAD
     * Description  : CAPA 월별 엑셀 업로드 검증(모드 0) · 반영(모드 1 이상)
     * AS-IS        : SCP0049_CAPA_EXCEL_UPLOAD (MSSQL)
     *
     * AS-IS 주석 원문 보존
     * ---------------------------------------------------------------------------------------------
     * 2021.01.05	khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선 - 최초작성
     * 2021.03.17	khj79			SCM PI Admin 수정 가능하도록 권한 추가
     * 2021.03.16	khj79			Invalid Line Operation YIELD 제외 추가
     * 2021.03.17	khj79			LANE QTY 변경 ( E3000 , E4000 ) 추가
     * 2021.08.24   khj79			[PJ20209643] LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - 이력 저장 및 LINE ASSIGN 삭제(TACT TIME, YIELD 삭제 동기화)
     * 2025.08.01   hrkim			PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 완성 공정 하드코딩 변경
     * 2025/10/15   hrkim		    [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : JV 셀생산 Real Line 기준으로 ESS Virtual Line Capa정보 동기화 저장
     * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     *
     * EX > Div*	Company*	FromSite*	Material*	yyyyMMdd*	Qty*
     * ---------------------------------------------------------------------------------------------
     *
     * 인자 : 화면(서버) 호출 규약 5인자
     *   P_MODE          - 0 = 검증 · 1 이상 = 반영 (AS-IS @p_mode)
     *   P_SES_USER_ID   - 업로드 작성자 (AS-IS @p_created_by)
     *   P_MNU_ID        - 화면(메뉴) 식별자. AS-IS 가 쓰지 않으므로 본문에서 사용하지 않음
     *                     (프로그램 구분은 AS-IS 와 같이 'SCP0049' 고정)
     *   P_SHT_NM        - 업로드 시트 이름. AS-IS 가 쓰지 않으므로 본문에서 사용하지 않음
     *                     (월별 · 일별 프로시저가 시트 이름으로 갈리므로 'CAPA' 고정)
     *   O_RESULT_CURSOR - 결과 커서 1개 (정상 RESULT_CODE 'S' · 오류 CODE '-1' + MSG)
     *
     * 사용 GTT : GT_SCP0049_UPL_DATA(신규) · GT_SCP0049_UPL_VALID(신규)
     *            GT_SCP0049(이력) · GT_SCP0049_DELETE(삭제) · GT_SCP0049_LOSS(LOSS 이력)
     *            GT_SCP0049_DS(이력 프로시저 인계용) · GT_SCP0049_SAVE_LOSS_UTIL_TACT · GT_SCP0049_SAVE_LOSS_UTIL_LOSS
     *
     * 내부 프로시저 의존 : P_CAPA_HIST_DATASET · P_CAPA_LINE_ASSIGN_DELETE_DATASET (둘 다 인자 없음 · GT_SCP0049_DS 를 읽음)
     *            (AS-IS PR_SCP_CAPA_HIST_DATASET · PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET 흡수분 · P_SAVE_CAPA 와 같은 규약)
     *==============================================================================================*/
    PROCEDURE P_CAPA_EXCEL_UPLOAD
    (
        P_MODE           IN  NUMBER,
        P_SES_USER_ID    IN  VARCHAR2,
        P_MNU_ID         IN  VARCHAR2,
        P_SHT_NM         IN  VARCHAR2,
        O_RESULT_CURSOR  OUT SYS_REFCURSOR
    )
    IS
        V_PROGRAM_ID      VARCHAR2(40 CHAR)   := 'SCP0049';
        V_SHEET_NAME      VARCHAR2(40 CHAR)   := 'CAPA';
        V_CREATION_DATE   VARCHAR2(40 CHAR);
        V_COUNT           NUMBER(10);

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME    VARCHAR2(150 CHAR)  := 'SCP0049_CAPA_EXCEL_UPLOAD';
        V_LOG_TYPE        VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
        N_LOG_COUNT       NUMBER(10)          := 0;
        V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
        V_DESCRIPTION     VARCHAR2(500 CHAR);
        D_EVENT_DATE      DATE;
        V_LOG_ERROR       VARCHAR2(1000 CHAR);

        V_STD_YYYYMMDD    VARCHAR2(8 CHAR);   /* 수정 가능 기준 날짜 설정 */
        V_STD_YYYYMM      VARCHAR2(6 CHAR);   /* 수정 가능 기준 날짜 설정 */
        V_STD_YYYY        VARCHAR2(4 CHAR);   /* 수정 가능 기준 날짜 설정 */

        V_CREATED_BY      VARCHAR2(150 CHAR);

        /* 수정 결과 카운트 */
        V_MOD_CNT         NUMBER(10)          := 0;

        /* AS-IS @@ROWCOUNT 재현 */
        V_ROWCOUNT        NUMBER(10)          := 0;

        /* 결과 커서 값 */
        V_ERR             VARCHAR2(4000 CHAR);
        V_RESULT_EVENT    NUMBER(10)          := 0;

        /* AS-IS 의 EXEC PR_SCM_SYS_LOG_BATCH 반복 호출 묶음 (PR_SCM_SYS_LOG_BATCH 는 자율 트랜잭션) */
        PROCEDURE P_LOG
        (
            P_LOG_TYPE     IN  VARCHAR2,
            P_LOG_MESSAGE  IN  VARCHAR2,
            P_DESC         IN  VARCHAR2
        )
        IS
        BEGIN
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, P_LOG_TYPE, N_LOG_COUNT, P_LOG_MESSAGE, P_DESC, D_EVENT_DATE);
        END P_LOG;

    BEGIN

        /* 기준 일자 설정 */
        V_STD_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');  /* 오늘 날짜 */
        V_STD_YYYYMM   := TO_CHAR(SYSDATE, 'YYYYMM');    /* 해당 월 */
        V_STD_YYYY     := TO_CHAR(SYSDATE, 'YYYY');      /* 해당 월 */

        /*------------------------------------------------------------------------------------------
         * [PJ20257329] Cell 완성 공정 하드 코딩 변경
         *   SCP Cell Final 공정 정보 - Cell Packaging/Assembly
         * AS-IS 테이블 변수 @SCP_CELL_FINAL_OPERATION 은 한 곳에서만 참조하므로 인라인 뷰로 흡수
         *------------------------------------------------------------------------------------------*/

        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        SELECT TO_CHAR(MAX(CREATION_DATE), 'YYYY-MM-DD HH24:MI:SS.FF3')
          INTO V_CREATION_DATE
          FROM SCM_ADM_EXCEL_UPLOAD
         WHERE PROGRAM_ID = V_PROGRAM_ID
           AND SHEET_NAME = V_SHEET_NAME
           AND CREATED_BY = P_SES_USER_ID;

        IF V_CREATION_DATE IS NULL THEN
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := 'Data Not Found [' || V_CREATION_DATE || ']';
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);
        END IF;

        /* 사용자 정보 설정 */
        V_CREATED_BY := P_SES_USER_ID;

        /* @p_mode = 0 이면 Validation */
        IF NVL(P_MODE, 0) = 0 THEN

            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = 'UPLOAD'
                 , MESSAGE_TEXT       = NULL
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID = V_PROGRAM_ID
               AND SHEET_NAME = V_SHEET_NAME
               AND CREATED_BY = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND NVL(UPLOAD_STATUS_CODE, 'X') != 'UPLOAD';

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## RESET Status = UPLOAD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ///////////////////////////// VALIDATION CHECK ///////////////////////// */

            /* ######################################################## */
            /* TITLE 처리												*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = '@TITLE'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID = V_PROGRAM_ID
               AND SHEET_NAME = V_SHEET_NAME
               AND CREATED_BY = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND (UPPER(ATTRIBUTE1) = 'DIV*' OR UPPER(ATTRIBUTE1) = 'DIV' OR UPPER(ATTRIBUTE1) = 'DIVISION');

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## TITLE Header Line ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);
            /* #################################################### */
            /* 필수 값 NULL 값 체크									*/
            /* ATTRIBUTE6  : Line*									*/
            /* ATTRIBUTE7  : Operation*								*/
            /* ATTRIBUTE8  : Line Type*								*/
            /* ATTRIBUTE10 : Level 1*								*/
            /* ATTRIBUTE11 : Level 2*								*/
            /* ATTRIBUTE12 : Material*								*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = CASE WHEN TRIM(ATTRIBUTE6) IS NULL OR TRIM(ATTRIBUTE8) IS NULL THEN 'NULL LINE & TYPE Data.'
                                             WHEN TRIM(ATTRIBUTE7) IS NULL                            THEN 'NULL OPERATION Data.'
                                             WHEN TRIM(ATTRIBUTE10) IS NULL                           THEN 'NULL LEVEL 1 Data.'
                                             WHEN ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE11) IS NULL
                                                                                                      THEN 'NULL LEVEL 2(LOSS KEY) Data.'
                                             WHEN ATTRIBUTE10 IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE12) IS NULL
                                                                                                      THEN 'NULL ITEM Data.'
                                        END
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID         = V_PROGRAM_ID
               AND SHEET_NAME         = V_SHEET_NAME
               AND CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND UPLOAD_STATUS_CODE = 'UPLOAD'
               AND (   TRIM(ATTRIBUTE6) IS NULL OR TRIM(ATTRIBUTE7) IS NULL OR TRIM(ATTRIBUTE8) IS NULL OR TRIM(ATTRIBUTE10) IS NULL
                    OR ( ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE11) IS NULL )
                    OR ( ATTRIBUTE10 IN     ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE12) IS NULL )
                   );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## ERROR NULL Column Data ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LOSS 값 체크											*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Loss Type.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD')
               AND NOT EXISTS ( SELECT 1
                                  FROM (SELECT SEGMENT1    AS LOSS_CODE
                                             , ATTRIBUTE1   AS LEVEL1
                                             , ATTRIBUTE2   AS LEVEL2
                                          FROM SCM_SYS_LOOKUP_VALUE_SN
                                         WHERE 1 = 1
                                           AND LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT') IA
                                 WHERE 1 = 1
                                   AND IA.LEVEL1 = A.ATTRIBUTE10
                                   AND IA.LEVEL2 = A.ATTRIBUTE11
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Loss Type ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LINE 체크												*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line & Line Type.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10       != 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line & Line Type. ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LINE 체크		YIELD									*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line & Line Type. YIELD'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID = A.ATTRIBUTE6
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line & Line Type. YIELD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* OPERATION_ID 체크										*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line Operation.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10       != 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                                   AND B.OPERATION_ID   = A.ATTRIBUTE7
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line Operation ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* OPERATION_ID 체크		YIELD							*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line Operation. YIELD'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID      = A.ATTRIBUTE6
                                   AND B.OPERATION_ID = A.ATTRIBUTE7
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line Operation YIELD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* 필수 항목 기준으로 다른 Data Update 					*/
            /* AS-IS UPDATE ... FROM 2개 테이블 → 상관 서브쿼리 UPDATE	*/
            /* 계층 뷰가 같은 키로 여러 행이면 AS-IS 는 임의 1행을 쓰므로	*/
            /* ROWNUM = 1 로 같은 동작(ORA-01427 회피)을 재현			*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET (ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5)
                     = ( SELECT B.DIVISION_ID
                              , B.COMPANY_ID
                              , B.SITE_ID
                              , B.PLANT_ID
                              , B.FACTORY_ID
                           FROM SCM_LINE_HIERARCHY_V_SN B
                          WHERE B.LINE_ID        = A.ATTRIBUTE6
                            AND B.OPERATION_ID   = A.ATTRIBUTE7
                            AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                            AND ROWNUM           = 1 )
                 , LAST_UPDATED_BY  = V_CREATED_BY
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM SCM_LINE_HIERARCHY_V_SN C
                             WHERE C.LINE_ID        = A.ATTRIBUTE6
                               AND C.OPERATION_ID   = A.ATTRIBUTE7
                               AND C.ELECTRODE_TYPE = A.ATTRIBUTE8
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## LINE HIERACHY UPDATE ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* 권한 체크												*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Auth'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_MASTER_MANAGER_M_SN B
                                 WHERE 1 = 1
                                   AND B.DIVISION_ID    = A.ATTRIBUTE1
                                   AND B.COMPANY_ID     = A.ATTRIBUTE2
                                   AND B.SITE_ID        = A.ATTRIBUTE3
                                   AND B.PLANT_ID       = A.ATTRIBUTE4
                                   AND B.FACTORY_ID     = A.ATTRIBUTE5
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.OPERATION_ID   = A.ATTRIBUTE7
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                                   AND B.LOSS_CODE      = ( SELECT SEGMENT1
                                                              FROM SCM_SYS_LOOKUP_VALUE_SN C
                                                             WHERE 1 = 1
                                                               AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                               AND C.ACTIVE_FLAG      = 'Y'
                                                               AND C.ATTRIBUTE1       = CASE WHEN A.ATTRIBUTE10 = 'DAILY CAPA' THEN 'TACT TIME' ELSE A.ATTRIBUTE10 END
                                                               AND C.ATTRIBUTE2       = CASE WHEN A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD' ) THEN '-'
                                                                                             ELSE A.ATTRIBUTE11
                                                                                        END
                                                          )
                                   AND (B.USER_ID_1 = V_CREATED_BY OR B.USER_ID_2 = V_CREATED_BY OR B.USER_ID_3 = V_CREATED_BY OR B.USER_ID_4 = V_CREATED_BY OR B.USER_ID_5 = V_CREATED_BY
                                          OR B.USER_ID_6 = V_CREATED_BY OR B.USER_ID_7 = V_CREATED_BY OR B.USER_ID_8 = V_CREATED_BY OR B.USER_ID_9 = V_CREATED_BY OR B.USER_ID_10 = V_CREATED_BY
                                       )
                                UNION ALL
                                SELECT 1
                                  /* 2026.09.30 AJS 수정 (START) */
                                --FROM TB_FX_USERGROUPINFO
                               --WHERE USERID = V_CREATED_BY
                                 --AND USEYN  = 'Y'
                                  FROM SCM_ADM_USER_GR_MPG_M
                                 WHERE USER_ID = V_CREATED_BY
                                   AND USE_YN  = 'Y'
                                  /* 2026.09.30 AJS 수정 (END) */
                                   --AND GROUPID = 'SCM PI Admin'
                                   /* 2026.09.30 AJS 수정 (START) */
                                 --AND GROUPID IN ('SCM PI Admin', 'FP Planner', 'SCP Planner') -- FP Planner, SCP Planner 권한 추가
                                   AND USER_GR_ID IN ('SCM PI Admin', 'FP Planner', 'SCP Planner') -- FP Planner, SCP Planner 권한 추가
                                   /* 2026.09.30 AJS 수정 (END) */
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Auth ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID 체크											*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_ITEM_M_SN B
                                 WHERE 1 = 1
                                   AND B.DIVISION_ID = A.ATTRIBUTE1
                                   AND B.COMPANY_ID  = A.ATTRIBUTE2
                                   AND B.SITE_ID     = A.ATTRIBUTE3
                                   AND B.ITEM_ID     = A.ATTRIBUTE12
                                   AND B.ACTIVE_FLAG = 'Y'
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID - OPERATION 체크								*/
            /* AS-IS UPDATE ... FROM 2개 테이블 → EXISTS 로 변환		*/
            /* MSSQL SUBSTRING 은 범위를 넘으면 빈 문자를 주고			*/
            /* 빈 문자 != 'E2000' 이 참이 되므로 NVL(...,' ') 로 맞춘다	*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item - Operation'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND A.ATTRIBUTE7 NOT LIKE 'F%'
               AND EXISTS ( SELECT 1
                              FROM SCM_ITEM_M_SN B
                             WHERE B.DIVISION_ID = A.ATTRIBUTE1
                               AND B.COMPANY_ID  = A.ATTRIBUTE2
                               AND B.SITE_ID     = A.ATTRIBUTE3
                               AND B.ITEM_ID     = A.ATTRIBUTE12
                               AND B.ACTIVE_FLAG = 'Y'
                               AND B.FLOW_ID                          != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID,  1, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID,  6, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 11, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 16, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 12, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item - Operation ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID - OPERATION (FORMATION) 체크					*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item - Operation (FROMATION)'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND A.ATTRIBUTE7 LIKE 'F%'
               AND EXISTS ( SELECT 1
                              FROM SCM_ITEM_M_SN B
                             WHERE B.DIVISION_ID = A.ATTRIBUTE1
                               AND B.COMPANY_ID  = A.ATTRIBUTE2
                               AND B.SITE_ID     = A.ATTRIBUTE3
                               AND B.ITEM_ID     = A.ATTRIBUTE12
                               AND B.ACTIVE_FLAG = 'Y'
                               -- [PJ20257329] 변경전 AND (B.FLOW_ID NOT IN ('A3000','A9000') OR B.FORMATION_FLOW_ID IS NULL)
                               AND ( B.FLOW_ID NOT IN ( SELECT SEGMENT1
                                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                         WHERE 1 = 1
                                                           AND LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                           AND SEGMENT3    = 'A'  -- 공정그룹(Cell)
                                                           AND ATTRIBUTE1  = 'Y'  -- Final Operation
                                                       )
                                     OR B.FORMATION_FLOW_ID IS NULL )            -- [PJ20257329] Cell 완성 공정 하드 코딩 변경
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item - Operation (FORMATION) ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM , LANE QTY 체크 - E2000 공정만 체크				*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item. Lane Qty'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'LINE ASSIGN'
               AND A.ATTRIBUTE7         = 'E2000'
               AND NOT EXISTS ( SELECT 1
                                  FROM (SELECT B.COMPANY_ID
                                             , B.DIVISION_ID
                                             , B.SITE_ID
                                             , B.PLANT_ID
                                             , B.FACTORY_ID
                                             , B.ITEM_ID
                                             , C.LINE_ID
                                             , C.ELECTRODE_TYPE
                                             , C.OPERATION_ID
                                             , B.PROD_VERSION_TYPE
                                             , B.LANE_QTY
                                          FROM SCM_ITEM_LANE_M_SN B
                                             , SCM_LINE_M_SN C
                                         WHERE B.ACTIVE_FLAG       = 'Y'
                                           AND C.ACTIVE_FLAG       = 'Y'
                                           AND B.COMPANY_ID        = C.COMPANY_ID
                                           AND B.DIVISION_ID       = C.DIVISION_ID
                                           AND B.SITE_ID           = C.SITE_ID
                                           AND B.PLANT_ID          = C.PLANT_ID
                                           AND B.FACTORY_ID        = C.FACTORY_ID
                                           AND B.PROD_VERSION_TYPE = C.PROD_VERSION_TYPE
                                           AND C.OPERATION_ID      = 'E2000'  ) IA
                                 WHERE IA.DIVISION_ID     = A.ATTRIBUTE1
                                   AND IA.COMPANY_ID      = A.ATTRIBUTE2
                                   AND IA.SITE_ID         = A.ATTRIBUTE3
                                   AND IA.LINE_ID         = A.ATTRIBUTE6
                                   AND IA.OPERATION_ID    = A.ATTRIBUTE7
                                   AND IA.ELECTRODE_TYPE  = A.ATTRIBUTE8
                                   AND IA.ITEM_ID         = A.ATTRIBUTE12
                                   AND TRUNC(IA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(A.ATTRIBUTE13), '0'))), 0)
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item. Lane Qty ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ######################################################## */
            /* 중복 값 체크(LOSS) 체크									*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM ( SELECT PROGRAM_ID
                                          , SHEET_NAME
                                          , CREATION_DATE
                                          , ATTRIBUTE1   AS DIVISION_ID
                                          , ATTRIBUTE2   AS COMPANY_ID
                                          , ATTRIBUTE3   AS SITE_ID
                                          , ATTRIBUTE4   AS PLANT_ID
                                          , ATTRIBUTE5   AS FACTORY_ID
                                          , ATTRIBUTE6   AS LINE_ID
                                          , ATTRIBUTE7   AS OPERATION_ID
                                          , ATTRIBUTE8   AS ELECTRODE_TYPE
                                          , ATTRIBUTE10  AS DATA_TYPE_1
                                          , ATTRIBUTE11  AS DATA_TYPE_2
                                       FROM SCM_ADM_EXCEL_UPLOAD
                                      WHERE PROGRAM_ID = V_PROGRAM_ID
                                        AND SHEET_NAME = V_SHEET_NAME
                                        AND CREATED_BY = V_CREATED_BY
                                        AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                        AND UPLOAD_STATUS_CODE = 'UPLOAD'
                                        AND ATTRIBUTE10 IN ('No-Load','No-Run','Not-Available','Performance(%)','Quality(%)')
                                      GROUP BY PROGRAM_ID
                                             , SHEET_NAME
                                             , CREATION_DATE
                                             , ATTRIBUTE1
                                             , ATTRIBUTE2
                                             , ATTRIBUTE3
                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE8
                                             , ATTRIBUTE10
                                             , ATTRIBUTE11
                                     HAVING COUNT(1) > 1 ) IA
                             WHERE 1 = 1
                               AND IA.DIVISION_ID    = A.ATTRIBUTE1
                               AND IA.COMPANY_ID     = A.ATTRIBUTE2
                               AND IA.SITE_ID        = A.ATTRIBUTE3
                               AND IA.PLANT_ID       = A.ATTRIBUTE4
                               AND IA.FACTORY_ID     = A.ATTRIBUTE5
