            /* ################################################################ */
            /* CONFIRM 중복 값 체크(LINE ASSIGN,TACT TIME,DAILY CAPA,YIELD) 제외	*/
            /* ################################################################ */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Finish Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
