                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE8
                                             , ATTRIBUTE10
                                             , ATTRIBUTE11
                                             , ATTRIBUTE14
                                     HAVING COUNT(1) > 1 ) IA
