                            , DATA_TYPE_1
                            , DATA_TYPE_2
                            , ITEM_ID
                            , LANE_QTY
                            , FINISH
                            , UOM
                            , YYYYMMDD
                            , QTY
                            , CREATED_BY )
                SELECT B.DIVISION_ID
                     , B.COMPANY_ID
                     , B.SITE_ID
                     , B.PLANT_ID
                     , B.FACTORY_ID
                     , B.LINE_ID
                     , B.OPERATION_ID
                     , B.ELECTRODE_TYPE
                     , A.ATTRIBUTE9
                     , A.DATA_TYPE_1
                     , A.DATA_TYPE_2
                     , A.ITEM_ID
                     , A.LANE_QTY
                     , A.FINISH
                     , A.UOM
                     , A.YYYYMMDD
                     , A.QTY
                     , A.CREATED_BY
                  FROM GT_SCP0049_UPL_DATA A   -- 가상 Line validation 처리하여 모두 real line data임
                     , SCM_MST_LINE_SN B
                 WHERE 1 = 1
                   AND B.LINK_LINE_ID    = A.LINE_ID
                   AND B.OPERATION_ID    = A.OPERATION_ID
                   AND B.ELECTRODE_TYPE  = A.ELECTRODE_TYPE
                   AND B.ACTIVE_FLAG     = 'Y'
                   AND B.VIRTUAL_LINE_YN = 'Y';
                /*------------------ End [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ----------------*/

                /* #################################################### */
                /* 이력 저장				 								*/
                /* #################################################### */
                V_LOG_ERROR := 'CAPA HIST';

                DELETE FROM GT_SCP0049;
                DELETE FROM GT_SCP0049_DELETE;

                INSERT INTO GT_SCP0049
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_UPDATE_ID )
                SELECT DIVISION_ID
                     , COMPANY_ID
                     , SITE_ID
                     , PLANT_ID
                     , FACTORY_ID
                     , LINE_ID
                     , OPERATION_ID
                     , ELECTRODE_TYPE
                     , ITEM_ID
                     , CASE WHEN DATA_TYPE_1 = 'LINE ASSIGN' THEN 'LA'
                            WHEN DATA_TYPE_1 IN ('DAILY CAPA','TACT TIME') THEN 'T'
                            WHEN DATA_TYPE_1 = 'YIELD' THEN 'Y'
                       END        AS DATA_TABLE
                     , 'M'        AS DATA_TYPE  -- MONTH DATA 만 존재 함
                     , YYYYMMDD   AS DAY_NAME
                     , QTY        AS DAY_QTY
                     , CREATED_BY AS UPDATE_ID
                  FROM GT_SCP0049_UPL_DATA
                 WHERE DATA_TYPE_1 IN ( 'LINE ASSIGN','DAILY CAPA','TACT TIME','YIELD')
                   AND LENGTH(RTRIM(YYYYMMDD)) = 6;

                /* 이력 저장 */
                /* AS-IS EXEC [dbo].[PR_SCP_CAPA_HIST_DATASET] @SCP0049_HIST 대응 */
                /* 테이블 파라미터는 전달용 GTT(GT_SCP0049_DS)로 인계한다 */
                DELETE FROM GT_SCP0049_DS;

                INSERT INTO GT_SCP0049_DS
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049;

                P_CAPA_HIST_DATASET;

                V_LOG_ERROR := 'LINE ASSIGN DELETE';

                /* LINE ASSIGN 삭제(TACT TIME,YIELD 삭제 동기화) */
                INSERT INTO GT_SCP0049_DELETE
