                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049
                 WHERE P_DATA_TABLE = 'LA'
                   AND NVL(TRUNC(TO_NUMBER(P_DAY_QTY)), 0) = 9;

                /* LINE ASSIGN 데이터 삭제 */
                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 = 'LINE ASSIGN'
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID    = A.FACTORY_ID
                                   AND B.P_LINE_ID       = A.LINE_ID
                                   AND B.P_OPERATION_ID  = A.OPERATION_ID
                                   AND B.P_ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND B.P_ITEM_ID       = A.ITEM_ID
                                   AND B.P_DAY_NAME      = A.YYYYMMDD
                              );

                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 IN ('TACT TIME','DAILY CAPA')
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID    = A.FACTORY_ID
                                   AND B.P_LINE_ID       = A.LINE_ID
                                   AND B.P_OPERATION_ID  = A.OPERATION_ID
                                   AND B.P_ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND B.P_ITEM_ID       = A.ITEM_ID
                                   AND B.P_DAY_NAME      = A.YYYYMMDD
                              );

                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 = 'YIELD'
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID   = A.FACTORY_ID
                                   AND B.P_LINE_ID      = A.LINE_ID
                                   AND B.P_OPERATION_ID = A.OPERATION_ID
                                   AND B.P_ITEM_ID      = A.ITEM_ID
                                   AND B.P_DAY_NAME     = A.YYYYMMDD
                              );

                /* AS-IS EXEC [dbo].[PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET] @SCP0049_DELETE 대응 */
                DELETE FROM GT_SCP0049_DS;

                INSERT INTO GT_SCP0049_DS
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049_DELETE;

                P_CAPA_LINE_ASSIGN_DELETE_DATASET;

                /* #################################################### */
                /* SCM_LOSS_M_SN		 								*/
                /* 월별 입력	(PM 은 일별 입력한다)						*/
                /* QTY 는 0 보다 크거나 같은(>=) 값 입력					*/
                /* #################################################### */
                V_LOG_ERROR := 'LOSS MONTH';

                UPDATE SCM_LOSS_M_SN A
                   SET (LOSS_RATE, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_NUMBER(B.QTY) / 100
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = A.WORK_MONTH
                                AND ( SELECT SEGMENT1
                                        FROM SCM_SYS_LOOKUP_VALUE_SN C
                                       WHERE 1 = 1
                                         AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                         AND C.ACTIVE_FLAG      = 'Y'
                                         AND C.ATTRIBUTE1       = B.DATA_TYPE_1
                                         AND C.ATTRIBUTE2       = B.DATA_TYPE_2 ) = A.LOSS_CODE
                                AND B.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                                AND B.DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 6    -- MONTH
                                AND B.YYYYMMDD >= V_STD_YYYYMM
                                AND TO_NUMBER(B.QTY) >= 0.0 )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA D
                                 WHERE D.COMPANY_ID     = A.COMPANY_ID
                                   AND D.DIVISION_ID    = A.DIVISION_ID
                                   AND D.SITE_ID        = A.SITE_ID
                                   AND D.PLANT_ID       = A.PLANT_ID
                                   AND D.FACTORY_ID     = A.FACTORY_ID
                                   AND D.OPERATION_ID   = A.OPERATION_ID
                                   AND D.LINE_ID        = A.LINE_ID
                                   AND D.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND D.YYYYMMDD       = A.WORK_MONTH
                                   AND ( SELECT SEGMENT1
                                           FROM SCM_SYS_LOOKUP_VALUE_SN E
                                          WHERE 1 = 1
                                            AND E.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                            AND E.ACTIVE_FLAG      = 'Y'
                                            AND E.ATTRIBUTE1       = D.DATA_TYPE_1
                                            AND E.ATTRIBUTE2       = D.DATA_TYPE_2 ) = A.LOSS_CODE
                                   AND D.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                                   AND D.DATA_TYPE_2 <> 'PM'
                                   AND LENGTH(RTRIM(D.YYYYMMDD)) = 6
                                   AND D.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(D.QTY) >= 0.0
                              );

                INSERT INTO SCM_LOSS_M_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , WORK_MONTH
                            , LOSS_CODE
                            , LOSS_RATE
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.YYYYMMDD
                     , IA.LOSS_CODE
                     , IA.QTY / 100
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT A.DIVISION_ID
                              , A.COMPANY_ID
                              , A.SITE_ID
                              , A.PLANT_ID
                              , A.FACTORY_ID
                              , A.LINE_ID
                              , A.OPERATION_ID
                              , A.ELECTRODE_TYPE
                              , A.YYYYMMDD
                              , A.CREATED_BY
                              , TO_NUMBER(A.QTY) AS QTY
                              , ( SELECT SEGMENT1
                                    FROM SCM_SYS_LOOKUP_VALUE_SN B
                                   WHERE 1 = 1
                                     AND B.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                     AND B.ACTIVE_FLAG      = 'Y'
                                     AND B.ATTRIBUTE1       = A.DATA_TYPE_1
                                     AND B.ATTRIBUTE2       = A.DATA_TYPE_2 ) AS LOSS_CODE
                           FROM GT_SCP0049_UPL_DATA A
                          WHERE 1 = 1
                            AND A.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                            AND A.DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                            AND LENGTH(RTRIM(A.YYYYMMDD)) = 6    -- MONTH
                            AND A.YYYYMMDD >= V_STD_YYYYMM
                            AND TO_NUMBER(A.QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_LOSS_M_SN C
                                     WHERE C.COMPANY_ID     = IA.COMPANY_ID
                                       AND C.DIVISION_ID    = IA.DIVISION_ID
                                       AND C.SITE_ID        = IA.SITE_ID
                                       AND C.PLANT_ID       = IA.PLANT_ID
                                       AND C.FACTORY_ID     = IA.FACTORY_ID
                                       AND C.OPERATION_ID   = IA.OPERATION_ID
                                       AND C.LINE_ID        = IA.LINE_ID
                                       AND C.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND C.LOSS_CODE      = IA.LOSS_CODE
                                       AND C.WORK_MONTH     = IA.YYYYMMDD
                                  );

                /* #################################################### */
                /* SCM_LOSS_M_SN		 								*/
                /* 년도 입력 해당 년도에 월별 입력 한다.					*/
                /* 기준 월(현재월) 보다 크거나 같은(>=) 값 입력			*/
                /* QTY 는 0 보다 크거나 같은(>=) 값 입력					*/
                /* #################################################### */
                V_LOG_ERROR := 'LOSS YEAR';

                UPDATE SCM_LOSS_M_SN A
                   SET (LOSS_RATE, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_NUMBER(B.QTY) / 100
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                                  , (SELECT DISTINCT BASIS_YYYYMM
                                                   , CALENDAR_YYYY
                                       FROM SCM_SYS_CALENDAR_M
                                      WHERE BASIS_YYYYMM >= V_STD_YYYYMM   -- 기준월
                                    ) IA
                              WHERE IA.CALENDAR_YYYY = B.YYYYMMDD
                                AND B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND IA.BASIS_YYYYMM  = A.WORK_MONTH
                                AND ( SELECT SEGMENT1
                                        FROM SCM_SYS_LOOKUP_VALUE_SN C
                                       WHERE 1 = 1
                                         AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                         AND C.ACTIVE_FLAG      = 'Y'
                                         AND C.ATTRIBUTE1       = B.DATA_TYPE_1
                                         AND C.ATTRIBUTE2       = B.DATA_TYPE_2 ) = A.LOSS_CODE
                                AND B.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                                AND B.DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 4    -- YEAR
                                AND TO_NUMBER(B.QTY) >= 0.0 )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA D
                                     , (SELECT DISTINCT BASIS_YYYYMM
                                                      , CALENDAR_YYYY
                                          FROM SCM_SYS_CALENDAR_M
                                         WHERE BASIS_YYYYMM >= V_STD_YYYYMM
                                       ) XA
                                 WHERE XA.CALENDAR_YYYY = D.YYYYMMDD
                                   AND D.COMPANY_ID     = A.COMPANY_ID
                                   AND D.DIVISION_ID    = A.DIVISION_ID
                                   AND D.SITE_ID        = A.SITE_ID
                                   AND D.PLANT_ID       = A.PLANT_ID
                                   AND D.FACTORY_ID     = A.FACTORY_ID
                                   AND D.OPERATION_ID   = A.OPERATION_ID
                                   AND D.LINE_ID        = A.LINE_ID
                                   AND D.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND XA.BASIS_YYYYMM  = A.WORK_MONTH
                                   AND ( SELECT SEGMENT1
                                           FROM SCM_SYS_LOOKUP_VALUE_SN E
                                          WHERE 1 = 1
                                            AND E.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                            AND E.ACTIVE_FLAG      = 'Y'
                                            AND E.ATTRIBUTE1       = D.DATA_TYPE_1
                                            AND E.ATTRIBUTE2       = D.DATA_TYPE_2 ) = A.LOSS_CODE
                                   AND D.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                                   AND D.DATA_TYPE_2 <> 'PM'
                                   AND LENGTH(RTRIM(D.YYYYMMDD)) = 4
                                   AND TO_NUMBER(D.QTY) >= 0.0
                              );

                INSERT INTO SCM_LOSS_M_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , WORK_MONTH
                            , LOSS_CODE
                            , LOSS_RATE
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.YYYYMMDD
                     , IA.LOSS_CODE
                     , IA.QTY / 100
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT A.DIVISION_ID
                              , A.COMPANY_ID
                              , A.SITE_ID
                              , A.PLANT_ID
                              , A.FACTORY_ID
                              , A.LINE_ID
                              , A.OPERATION_ID
                              , A.ELECTRODE_TYPE
                              , C.BASIS_YYYYMM AS YYYYMMDD
                              , A.CREATED_BY
                              , TO_NUMBER(A.QTY) AS QTY
                              , ( SELECT SEGMENT1
                                    FROM SCM_SYS_LOOKUP_VALUE_SN B
                                   WHERE 1 = 1
                                     AND B.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                     AND B.ACTIVE_FLAG      = 'Y'
                                     AND B.ATTRIBUTE1       = A.DATA_TYPE_1
                                     AND B.ATTRIBUTE2       = A.DATA_TYPE_2 ) AS LOSS_CODE
                           FROM GT_SCP0049_UPL_DATA A
                              , (SELECT DISTINCT BASIS_YYYYMM
                                               , CALENDAR_YYYY
                                  FROM SCM_SYS_CALENDAR_M
                                 WHERE BASIS_YYYYMM >= V_STD_YYYYMM   -- 기준월
                                ) C
                          WHERE 1 = 1
                            AND C.CALENDAR_YYYY = A.YYYYMMDD
                            AND A.DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                            AND A.DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                            AND LENGTH(RTRIM(A.YYYYMMDD)) = 4    -- YEAR
                            AND TO_NUMBER(A.QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_LOSS_M_SN D
                                     WHERE D.COMPANY_ID     = IA.COMPANY_ID
                                       AND D.DIVISION_ID    = IA.DIVISION_ID
                                       AND D.SITE_ID        = IA.SITE_ID
                                       AND D.PLANT_ID       = IA.PLANT_ID
                                       AND D.FACTORY_ID     = IA.FACTORY_ID
                                       AND D.OPERATION_ID   = IA.OPERATION_ID
                                       AND D.LINE_ID        = IA.LINE_ID
                                       AND D.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND D.LOSS_CODE      = IA.LOSS_CODE
                                       AND D.WORK_MONTH     = IA.YYYYMMDD
                                  );

                /* #################################################### */
                /* SCM_MST_ITEM_LINE_ASSIGN_SN							*/
                /* LANE QTY 정보 UPDATE									*/
                /* #################################################### */
                V_LOG_ERROR := 'LANE QTY MONTH UPDATE';

                UPDATE SCM_MST_ITEM_LINE_ASSIGN_SN A
                   SET (LANE_QTY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT NVL(CASE WHEN TRIM(B.ATTRIBUTE13) IS NULL THEN 0.0 ELSE TO_NUMBER(B.ATTRIBUTE13) END, 0)
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM SCM_ADM_EXCEL_UPLOAD B
                              WHERE 1 = 1
                                AND B.ATTRIBUTE2  = A.COMPANY_ID
                                AND B.ATTRIBUTE1  = A.DIVISION_ID
                                AND B.ATTRIBUTE3  = A.SITE_ID
                                AND B.ATTRIBUTE4  = A.PLANT_ID
                                AND B.ATTRIBUTE5  = A.FACTORY_ID
                                AND B.ATTRIBUTE12 = A.ITEM_ID
                                AND B.ATTRIBUTE7  = A.OPERATION_ID
                                AND B.ATTRIBUTE6  = A.LINE_ID
                                AND B.ATTRIBUTE8  = A.ELECTRODE_TYPE
                                AND B.PROGRAM_ID         = V_PROGRAM_ID
                                AND B.SHEET_NAME         = V_SHEET_NAME
                                AND B.CREATED_BY         = V_CREATED_BY
                                AND B.UPLOAD_STATUS_CODE = 'SUCCESS'
                                AND TO_CHAR(B.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                AND B.ATTRIBUTE10 = 'LINE ASSIGN'
                                AND EXISTS ( SELECT 1
                                               FROM (SELECT C.COMPANY_ID, C.DIVISION_ID, C.SITE_ID, C.PLANT_ID, C.FACTORY_ID
                                                          , C.ITEM_ID, D.LINE_ID, D.ELECTRODE_TYPE, D.OPERATION_ID, C.PROD_VERSION_TYPE, C.LANE_QTY
                                                       FROM SCM_ITEM_LANE_M_SN C
                                                          , SCM_LINE_M_SN D
                                                      WHERE C.ACTIVE_FLAG       = 'Y'
                                                        AND D.ACTIVE_FLAG       = 'Y'
                                                        AND C.COMPANY_ID        = D.COMPANY_ID
                                                        AND C.DIVISION_ID       = D.DIVISION_ID
                                                        AND C.SITE_ID           = D.SITE_ID
                                                        AND C.PLANT_ID          = D.PLANT_ID
                                                        AND C.FACTORY_ID        = D.FACTORY_ID
                                                        AND C.PROD_VERSION_TYPE = D.PROD_VERSION_TYPE
                                                        AND D.OPERATION_ID      = 'E2000') SA
                                              WHERE SA.DIVISION_ID     = B.ATTRIBUTE1
                                                AND SA.COMPANY_ID      = B.ATTRIBUTE2
                                                AND SA.SITE_ID         = B.ATTRIBUTE3
                                                AND SA.LINE_ID         = B.ATTRIBUTE6
                                                AND SA.OPERATION_ID    = B.ATTRIBUTE7
                                                AND SA.ELECTRODE_TYPE  = B.ATTRIBUTE8
                                                AND SA.ITEM_ID         = B.ATTRIBUTE12
                                                AND TRUNC(SA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(B.ATTRIBUTE13), '0'))), 0)
                                           ) )
                 WHERE A.MONTH >= V_STD_YYYYMM
                   AND EXISTS ( SELECT 1
                                  FROM SCM_ADM_EXCEL_UPLOAD E
                                 WHERE 1 = 1
                                   AND E.ATTRIBUTE2  = A.COMPANY_ID
                                   AND E.ATTRIBUTE1  = A.DIVISION_ID
                                   AND E.ATTRIBUTE3  = A.SITE_ID
                                   AND E.ATTRIBUTE4  = A.PLANT_ID
                                   AND E.ATTRIBUTE5  = A.FACTORY_ID
                                   AND E.ATTRIBUTE12 = A.ITEM_ID
                                   AND E.ATTRIBUTE7  = A.OPERATION_ID
                                   AND E.ATTRIBUTE6  = A.LINE_ID
                                   AND E.ATTRIBUTE8  = A.ELECTRODE_TYPE
                                   AND E.PROGRAM_ID         = V_PROGRAM_ID
                                   AND E.SHEET_NAME         = V_SHEET_NAME
                                   AND E.CREATED_BY         = V_CREATED_BY
                                   AND E.UPLOAD_STATUS_CODE = 'SUCCESS'
                                   AND TO_CHAR(E.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                   AND E.ATTRIBUTE10 = 'LINE ASSIGN'
                                   AND EXISTS ( SELECT 1
                                                  FROM (SELECT F.COMPANY_ID, F.DIVISION_ID, F.SITE_ID, F.PLANT_ID, F.FACTORY_ID
                                                             , F.ITEM_ID, G.LINE_ID, G.ELECTRODE_TYPE, G.OPERATION_ID, F.PROD_VERSION_TYPE, F.LANE_QTY
                                                          FROM SCM_ITEM_LANE_M_SN F
                                                             , SCM_LINE_M_SN G
                                                         WHERE F.ACTIVE_FLAG       = 'Y'
                                                           AND G.ACTIVE_FLAG       = 'Y'
                                                           AND F.COMPANY_ID        = G.COMPANY_ID
                                                           AND F.DIVISION_ID       = G.DIVISION_ID
                                                           AND F.SITE_ID           = G.SITE_ID
                                                           AND F.PLANT_ID          = G.PLANT_ID
                                                           AND F.FACTORY_ID        = G.FACTORY_ID
                                                           AND F.PROD_VERSION_TYPE = G.PROD_VERSION_TYPE
                                                           AND G.OPERATION_ID      = 'E2000') XA
                                                 WHERE XA.DIVISION_ID     = E.ATTRIBUTE1
                                                   AND XA.COMPANY_ID      = E.ATTRIBUTE2
                                                   AND XA.SITE_ID         = E.ATTRIBUTE3
                                                   AND XA.LINE_ID         = E.ATTRIBUTE6
                                                   AND XA.OPERATION_ID    = E.ATTRIBUTE7
                                                   AND XA.ELECTRODE_TYPE  = E.ATTRIBUTE8
                                                   AND XA.ITEM_ID         = E.ATTRIBUTE12
                                                   AND TRUNC(XA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(E.ATTRIBUTE13), '0'))), 0)
                                              )
                              );

                /* #################################################### */
                /* SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN					*/
                /* LANE QTY 정보 UPDATE									*/
                /* #################################################### */
                V_LOG_ERROR := 'LANE QTY MONTH DAILY';

                UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
                   SET (LANE_QTY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT NVL(CASE WHEN TRIM(B.ATTRIBUTE13) IS NULL THEN 0.0 ELSE TO_NUMBER(B.ATTRIBUTE13) END, 0)
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM SCM_ADM_EXCEL_UPLOAD B
                              WHERE 1 = 1
                                AND B.ATTRIBUTE2  = A.COMPANY_ID
                                AND B.ATTRIBUTE1  = A.DIVISION_ID
                                AND B.ATTRIBUTE3  = A.SITE_ID
                                AND B.ATTRIBUTE4  = A.PLANT_ID
                                AND B.ATTRIBUTE5  = A.FACTORY_ID
                                AND B.ATTRIBUTE12 = A.ITEM_ID
                                AND B.ATTRIBUTE7  = A.OPERATION_ID
                                AND B.ATTRIBUTE6  = A.LINE_ID
                                AND B.ATTRIBUTE8  = A.ELECTRODE_TYPE
                                AND B.PROGRAM_ID         = V_PROGRAM_ID
                                AND B.SHEET_NAME         = V_SHEET_NAME
                                AND B.CREATED_BY         = V_CREATED_BY
                                AND B.UPLOAD_STATUS_CODE = 'SUCCESS'
                                AND TO_CHAR(B.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                AND B.ATTRIBUTE10 = 'LINE ASSIGN'
                                AND EXISTS ( SELECT 1
                                               FROM (SELECT C.COMPANY_ID, C.DIVISION_ID, C.SITE_ID, C.PLANT_ID, C.FACTORY_ID
                                                          , C.ITEM_ID, D.LINE_ID, D.ELECTRODE_TYPE, D.OPERATION_ID, C.PROD_VERSION_TYPE, C.LANE_QTY
                                                       FROM SCM_ITEM_LANE_M_SN C
                                                          , SCM_LINE_M_SN D
                                                      WHERE C.ACTIVE_FLAG       = 'Y'
                                                        AND D.ACTIVE_FLAG       = 'Y'
                                                        AND C.COMPANY_ID        = D.COMPANY_ID
                                                        AND C.DIVISION_ID       = D.DIVISION_ID
                                                        AND C.SITE_ID           = D.SITE_ID
                                                        AND C.PLANT_ID          = D.PLANT_ID
                                                        AND C.FACTORY_ID        = D.FACTORY_ID
                                                        AND C.PROD_VERSION_TYPE = D.PROD_VERSION_TYPE
                                                        AND D.OPERATION_ID      = 'E2000') SA
                                              WHERE SA.DIVISION_ID     = B.ATTRIBUTE1
                                                AND SA.COMPANY_ID      = B.ATTRIBUTE2
                                                AND SA.SITE_ID         = B.ATTRIBUTE3
                                                AND SA.LINE_ID         = B.ATTRIBUTE6
                                                AND SA.OPERATION_ID    = B.ATTRIBUTE7
                                                AND SA.ELECTRODE_TYPE  = B.ATTRIBUTE8
                                                AND SA.ITEM_ID         = B.ATTRIBUTE12
                                                AND TRUNC(SA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(B.ATTRIBUTE13), '0'))), 0)
                                           ) )
                 WHERE TO_CHAR(A.START_TIME, 'YYYYMM') >= V_STD_YYYYMM
                   AND EXISTS ( SELECT 1
                                  FROM SCM_ADM_EXCEL_UPLOAD E
                                 WHERE 1 = 1
                                   AND E.ATTRIBUTE2  = A.COMPANY_ID
                                   AND E.ATTRIBUTE1  = A.DIVISION_ID
                                   AND E.ATTRIBUTE3  = A.SITE_ID
                                   AND E.ATTRIBUTE4  = A.PLANT_ID
                                   AND E.ATTRIBUTE5  = A.FACTORY_ID
                                   AND E.ATTRIBUTE12 = A.ITEM_ID
                                   AND E.ATTRIBUTE7  = A.OPERATION_ID
                                   AND E.ATTRIBUTE6  = A.LINE_ID
                                   AND E.ATTRIBUTE8  = A.ELECTRODE_TYPE
                                   AND E.PROGRAM_ID         = V_PROGRAM_ID
                                   AND E.SHEET_NAME         = V_SHEET_NAME
                                   AND E.CREATED_BY         = V_CREATED_BY
                                   AND E.UPLOAD_STATUS_CODE = 'SUCCESS'
                                   AND TO_CHAR(E.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                   AND E.ATTRIBUTE10 = 'LINE ASSIGN'
                                   AND EXISTS ( SELECT 1
                                                  FROM (SELECT F.COMPANY_ID, F.DIVISION_ID, F.SITE_ID, F.PLANT_ID, F.FACTORY_ID
                                                             , F.ITEM_ID, G.LINE_ID, G.ELECTRODE_TYPE, G.OPERATION_ID, F.PROD_VERSION_TYPE, F.LANE_QTY
                                                          FROM SCM_ITEM_LANE_M_SN F
                                                             , SCM_LINE_M_SN G
                                                         WHERE F.ACTIVE_FLAG       = 'Y'
                                                           AND G.ACTIVE_FLAG       = 'Y'
                                                           AND F.COMPANY_ID        = G.COMPANY_ID
                                                           AND F.DIVISION_ID       = G.DIVISION_ID
                                                           AND F.SITE_ID           = G.SITE_ID
                                                           AND F.PLANT_ID          = G.PLANT_ID
                                                           AND F.FACTORY_ID        = G.FACTORY_ID
                                                           AND F.PROD_VERSION_TYPE = G.PROD_VERSION_TYPE
                                                           AND G.OPERATION_ID      = 'E2000') XA
                                                 WHERE XA.DIVISION_ID     = E.ATTRIBUTE1
                                                   AND XA.COMPANY_ID      = E.ATTRIBUTE2
                                                   AND XA.SITE_ID         = E.ATTRIBUTE3
                                                   AND XA.LINE_ID         = E.ATTRIBUTE6
                                                   AND XA.OPERATION_ID    = E.ATTRIBUTE7
                                                   AND XA.ELECTRODE_TYPE  = E.ATTRIBUTE8
                                                   AND XA.ITEM_ID         = E.ATTRIBUTE12
                                                   AND TRUNC(XA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(E.ATTRIBUTE13), '0'))), 0)
                                              )
                              );

                /* #################################################### */
                /* SCM_ITEM_LINE_ASSIGN_M	month ,year					*/
                /* 기준 월(현재월) 보다 크거나 같은(>=) 값 입력			*/
                /* QTY 는 0 보다 크거나 같은(>=) 값 입력					*/
                /* LINE ASSIGN 은 LANE QTY 때문에 OPERATION 분리하여 수정한다.*/
                /* #################################################### */
                V_LOG_ERROR := 'LINE ASSIGN MONTH';

                /* LANE QTY 가 존재하는 공정(E2000, E3000, E4000) */
                UPDATE SCM_MST_ITEM_LINE_ASSIGN_SN A
                   SET (PRIORITY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_CHAR(TRUNC(TO_NUMBER(B.QTY)))
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.ITEM_ID        = A.ITEM_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = A.MONTH
                                AND B.DATA_TYPE_1    = 'LINE ASSIGN'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 6           -- MONTH
                                AND B.YYYYMMDD >= V_STD_YYYYMM              -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) > 0.0
                                AND B.OPERATION_ID = 'E2000' )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID     = A.COMPANY_ID
                                   AND C.DIVISION_ID    = A.DIVISION_ID
                                   AND C.SITE_ID        = A.SITE_ID
                                   AND C.PLANT_ID       = A.PLANT_ID
                                   AND C.FACTORY_ID     = A.FACTORY_ID
                                   AND C.ITEM_ID        = A.ITEM_ID
                                   AND C.OPERATION_ID   = A.OPERATION_ID
                                   AND C.LINE_ID        = A.LINE_ID
                                   AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND C.YYYYMMDD       = A.MONTH
                                   AND C.DATA_TYPE_1    = 'LINE ASSIGN'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 6
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) > 0.0
                                   AND C.OPERATION_ID = 'E2000'
                              );

                INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , MONTH
                            , LANE_QTY
                            , PRIORITY
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.YYYYMMDD
                     , IA.LANE_QTY
                     , TO_CHAR(IA.QTY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , NVL(CASE WHEN TRIM(LANE_QTY) IS NULL THEN 0.0 ELSE TO_NUMBER(LANE_QTY) END, 0) AS LANE_QTY
                              , TRUNC(TO_NUMBER(QTY))  AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'LINE ASSIGN'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 6         -- MONTH
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) > 0.0
                            AND OPERATION_ID = 'E2000' ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_ITEM_LINE_ASSIGN_SN B
                                     WHERE B.COMPANY_ID     = IA.COMPANY_ID
                                       AND B.DIVISION_ID    = IA.DIVISION_ID
                                       AND B.SITE_ID        = IA.SITE_ID
                                       AND B.PLANT_ID       = IA.PLANT_ID
                                       AND B.FACTORY_ID     = IA.FACTORY_ID
                                       AND B.ITEM_ID        = IA.ITEM_ID
                                       AND B.OPERATION_ID   = IA.OPERATION_ID
                                       AND B.LINE_ID        = IA.LINE_ID
                                       AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND B.MONTH          = IA.YYYYMMDD
                                  );

                V_LOG_ERROR := 'LINE ASSIGN MONTH LQ';

                /* LANE QTY 가 존재하는 공정(E2000, E3000, E4000) */
                UPDATE SCM_MST_ITEM_LINE_ASSIGN_SN A
                   SET (PRIORITY, LANE_QTY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_CHAR(TRUNC(TO_NUMBER(B.QTY)))
                                  , 0
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.ITEM_ID        = A.ITEM_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = A.MONTH
                                AND B.DATA_TYPE_1    = 'LINE ASSIGN'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 6           -- MONTH
                                AND B.YYYYMMDD >= V_STD_YYYYMM              -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) > 0.0
                                AND B.OPERATION_ID NOT IN ('E2000') )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID     = A.COMPANY_ID
                                   AND C.DIVISION_ID    = A.DIVISION_ID
                                   AND C.SITE_ID        = A.SITE_ID
                                   AND C.PLANT_ID       = A.PLANT_ID
                                   AND C.FACTORY_ID     = A.FACTORY_ID
                                   AND C.ITEM_ID        = A.ITEM_ID
                                   AND C.OPERATION_ID   = A.OPERATION_ID
                                   AND C.LINE_ID        = A.LINE_ID
                                   AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND C.YYYYMMDD       = A.MONTH
                                   AND C.DATA_TYPE_1    = 'LINE ASSIGN'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 6
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) > 0.0
                                   AND C.OPERATION_ID NOT IN ('E2000')
                              );

                INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , MONTH
                            , LANE_QTY
                            , PRIORITY
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.YYYYMMDD
                     , IA.LANE_QTY
                     , TO_CHAR(IA.QTY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , 0                      AS LANE_QTY
                              , TRUNC(TO_NUMBER(QTY))  AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'LINE ASSIGN'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 6         -- MONTH
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) > 0.0
                            AND OPERATION_ID NOT IN ('E2000') ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_ITEM_LINE_ASSIGN_SN B
                                     WHERE B.COMPANY_ID     = IA.COMPANY_ID
                                       AND B.DIVISION_ID    = IA.DIVISION_ID
                                       AND B.SITE_ID        = IA.SITE_ID
                                       AND B.PLANT_ID       = IA.PLANT_ID
                                       AND B.FACTORY_ID     = IA.FACTORY_ID
                                       AND B.ITEM_ID        = IA.ITEM_ID
                                       AND B.OPERATION_ID   = IA.OPERATION_ID
                                       AND B.LINE_ID        = IA.LINE_ID
                                       AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND B.MONTH          = IA.YYYYMMDD
                                  );

                /* #################################################### */
                /* SCM_MST_TACT_TIME_SN									*/
                /* 기준 월(현재월) 보다 크거나 같은(>=) 값 입력			*/
                /* QTY 는 0 보다 크거나 같은(>=) 값 입력					*/
                /* #################################################### */
                V_LOG_ERROR := 'TACT TIME MONTH';

                INSERT INTO GT_SCP0049_SAVE_LOSS_UTIL_TACT
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , WORK_MONTH
                            , LOSS_UTIL )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.WORK_MONTH
                      --, ROUND(EXP(SUM(ROUND(LOG(1-ISNULL(L.LOSS_RATE,0)),4))),4) AS LOSS_UTIL
                     , TO_CHAR(1 - ROUND(SUM(NVL(B.LOSS_RATE, 0)), 4))  AS UTIL
                  FROM ( SELECT DISTINCT
                                COMPANY_ID
                              , DIVISION_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , OPERATION_ID
                              , LINE_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD   AS WORK_MONTH
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                            AND LENGTH(RTRIM(YYYYMMDD)) = 6         -- MONTH
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) >= 0.0 ) IA
                     , SCM_LOSS_M_SN B                              -- LOSS UTIL 값 조회
                     , (SELECT SEGMENT1  AS LOSS_CODE
                          FROM SCM_SYS_LOOKUP_VALUE_SN
                         WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                           AND ATTRIBUTE5       = 'Y'
                       ) XA
                 WHERE B.COMPANY_ID     = IA.COMPANY_ID
                   AND B.DIVISION_ID    = IA.DIVISION_ID
                   AND B.SITE_ID        = IA.SITE_ID
                   AND B.PLANT_ID       = IA.PLANT_ID
                   AND B.FACTORY_ID     = IA.FACTORY_ID
                   AND B.OPERATION_ID   = IA.OPERATION_ID
                   AND B.LINE_ID        = IA.LINE_ID
                   AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                   AND B.WORK_MONTH     = IA.WORK_MONTH
                   AND B.LOSS_CODE      = XA.LOSS_CODE
                 GROUP BY IA.COMPANY_ID
                        , IA.DIVISION_ID
                        , IA.SITE_ID
                        , IA.PLANT_ID
                        , IA.FACTORY_ID
                        , IA.OPERATION_ID
                        , IA.LINE_ID
                        , IA.ELECTRODE_TYPE
                        , IA.WORK_MONTH;

                UPDATE SCM_MST_TACT_TIME_SN A
                   SET (TACT_TIME, DAILY_CAPA, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT IA.QTY_TACT
                                  , TRUNC(IA.QTY_DAILY)
                                  , IA.CREATED_BY
                                  , SYSDATE
                               FROM ( SELECT B.DIVISION_ID
                                           , B.COMPANY_ID
                                           , B.SITE_ID
                                           , B.PLANT_ID
                                           , B.FACTORY_ID
                                           , B.LINE_ID
                                           , B.OPERATION_ID
                                           , B.ELECTRODE_TYPE
                                           , B.YYYYMMDD
                                           , B.CREATED_BY
                                             --, CONVERT(NUMERIC(20,10),T.QTY )	QTY
                                           , CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                                  WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1)
                                                  ELSE TO_NUMBER(B.QTY) END AS QTY_TACT
                                           , CASE WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                                  WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) > 0 THEN ROUND(86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1), 0)
                                                  ELSE TO_NUMBER(B.QTY) END AS QTY_DAILY
                                           , B.ITEM_ID
                                           , B.DATA_TYPE_1
                                        FROM GT_SCP0049_UPL_DATA B
                                           , GT_SCP0049_SAVE_LOSS_UTIL_TACT C
                                       WHERE B.COMPANY_ID     = C.COMPANY_ID(+)
                                         AND B.DIVISION_ID    = C.DIVISION_ID(+)
                                         AND B.SITE_ID        = C.SITE_ID(+)
                                         AND B.PLANT_ID       = C.PLANT_ID(+)
                                         AND B.FACTORY_ID     = C.FACTORY_ID(+)
                                         AND B.OPERATION_ID   = C.OPERATION_ID(+)
                                         AND B.LINE_ID        = C.LINE_ID(+)
                                         AND B.ELECTRODE_TYPE = C.ELECTRODE_TYPE(+)
                                         AND B.YYYYMMDD       = C.WORK_MONTH(+)
                                         AND B.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                                         AND LENGTH(RTRIM(B.YYYYMMDD)) = 6    -- MONTH
                                         AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                                         AND TO_NUMBER(B.QTY) >= 0.0 ) IA
                              WHERE IA.COMPANY_ID     = A.COMPANY_ID
                                AND IA.DIVISION_ID    = A.DIVISION_ID
                                AND IA.SITE_ID        = A.SITE_ID
                                AND IA.PLANT_ID       = A.PLANT_ID
                                AND IA.FACTORY_ID     = A.FACTORY_ID
                                AND IA.ITEM_ID        = A.ITEM_ID
                                AND IA.OPERATION_ID   = A.OPERATION_ID
                                AND IA.LINE_ID        = A.LINE_ID
                                AND IA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND IA.YYYYMMDD       = A.MONTH )
                 WHERE EXISTS ( SELECT 1
                                  FROM ( SELECT D.DIVISION_ID
                                              , D.COMPANY_ID
                                              , D.SITE_ID
                                              , D.PLANT_ID
                                              , D.FACTORY_ID
                                              , D.LINE_ID
                                              , D.OPERATION_ID
                                              , D.ELECTRODE_TYPE
                                              , D.YYYYMMDD
                                              , D.ITEM_ID
                                           FROM GT_SCP0049_UPL_DATA D
                                              , GT_SCP0049_SAVE_LOSS_UTIL_TACT E
                                          WHERE D.COMPANY_ID     = E.COMPANY_ID(+)
                                            AND D.DIVISION_ID    = E.DIVISION_ID(+)
                                            AND D.SITE_ID        = E.SITE_ID(+)
                                            AND D.PLANT_ID       = E.PLANT_ID(+)
                                            AND D.FACTORY_ID     = E.FACTORY_ID(+)
                                            AND D.OPERATION_ID   = E.OPERATION_ID(+)
                                            AND D.LINE_ID        = E.LINE_ID(+)
                                            AND D.ELECTRODE_TYPE = E.ELECTRODE_TYPE(+)
                                            AND D.YYYYMMDD       = E.WORK_MONTH(+)
                                            AND D.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                                            AND LENGTH(RTRIM(D.YYYYMMDD)) = 6
                                            AND D.YYYYMMDD >= V_STD_YYYYMM
                                            AND TO_NUMBER(D.QTY) >= 0.0 ) XA
                                 WHERE XA.COMPANY_ID     = A.COMPANY_ID
                                   AND XA.DIVISION_ID    = A.DIVISION_ID
                                   AND XA.SITE_ID        = A.SITE_ID
                                   AND XA.PLANT_ID       = A.PLANT_ID
                                   AND XA.FACTORY_ID     = A.FACTORY_ID
                                   AND XA.ITEM_ID        = A.ITEM_ID
                                   AND XA.OPERATION_ID   = A.OPERATION_ID
                                   AND XA.LINE_ID        = A.LINE_ID
                                   AND XA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND XA.YYYYMMDD       = A.MONTH
                              );

                INSERT INTO SCM_MST_TACT_TIME_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , MONTH
                            , TACT_TIME
                            , DAILY_CAPA
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.YYYYMMDD
                     , IA.QTY_TACT
                     , TRUNC(IA.QTY_DAILY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT B.DIVISION_ID
                              , B.COMPANY_ID
                              , B.SITE_ID
                              , B.PLANT_ID
                              , B.FACTORY_ID
                              , B.LINE_ID
                              , B.OPERATION_ID
                              , B.ELECTRODE_TYPE
                              , B.YYYYMMDD
                              , B.CREATED_BY
                              , CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                     WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1)
                                     ELSE TO_NUMBER(B.QTY) END AS QTY_TACT
                              , CASE WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                     WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) > 0 THEN ROUND(86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1), 0)
                                     ELSE TO_NUMBER(B.QTY) END AS QTY_DAILY
                              , B.ITEM_ID
                              , B.DATA_TYPE_1
                           FROM GT_SCP0049_UPL_DATA B
                              , GT_SCP0049_SAVE_LOSS_UTIL_TACT C
                          WHERE B.COMPANY_ID     = C.COMPANY_ID(+)
                            AND B.DIVISION_ID    = C.DIVISION_ID(+)
                            AND B.SITE_ID        = C.SITE_ID(+)
                            AND B.PLANT_ID       = C.PLANT_ID(+)
                            AND B.FACTORY_ID     = C.FACTORY_ID(+)
                            AND B.OPERATION_ID   = C.OPERATION_ID(+)
                            AND B.LINE_ID        = C.LINE_ID(+)
                            AND B.ELECTRODE_TYPE = C.ELECTRODE_TYPE(+)
                            AND B.YYYYMMDD       = C.WORK_MONTH(+)
                            AND B.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                            AND LENGTH(RTRIM(B.YYYYMMDD)) = 6    -- MONTH
                            AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                            AND TO_NUMBER(B.QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_TACT_TIME_SN D
                                     WHERE D.COMPANY_ID     = IA.COMPANY_ID
                                       AND D.DIVISION_ID    = IA.DIVISION_ID
                                       AND D.SITE_ID        = IA.SITE_ID
                                       AND D.PLANT_ID       = IA.PLANT_ID
                                       AND D.FACTORY_ID     = IA.FACTORY_ID
                                       AND D.ITEM_ID        = IA.ITEM_ID
                                       AND D.OPERATION_ID   = IA.OPERATION_ID
                                       AND D.LINE_ID        = IA.LINE_ID
                                       AND D.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND D.MONTH          = IA.YYYYMMDD
                                  );

                /* #################################################### */
                /* SCM_MST_YIELD_SN										*/
                /* 기준 월(현재월) 보다 크거나 같은(>=) 값 입력			*/
                /* QTY 는 0 보다 크거나 같은(>=) 값 입력					*/
                /* #################################################### */
                V_LOG_ERROR := 'YIELD MONTH';

                UPDATE SCM_MST_YIELD_SN A
                   SET (YIELD, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_NUMBER(B.QTY) / 100
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID   = A.COMPANY_ID
                                AND B.DIVISION_ID  = A.DIVISION_ID
                                AND B.SITE_ID      = A.SITE_ID
                                AND B.PLANT_ID     = A.PLANT_ID
                                AND B.FACTORY_ID   = A.FACTORY_ID
                                AND B.ITEM_ID      = A.ITEM_ID
                                AND B.OPERATION_ID = A.OPERATION_ID
                                AND B.LINE_ID      = A.LINE_ID
                                AND B.YYYYMMDD     = A.MONTH
                                AND B.DATA_TYPE_1  = 'YIELD'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 6    -- MONTH
                                AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) >= 0.0 )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID   = A.COMPANY_ID
                                   AND C.DIVISION_ID  = A.DIVISION_ID
                                   AND C.SITE_ID      = A.SITE_ID
                                   AND C.PLANT_ID     = A.PLANT_ID
                                   AND C.FACTORY_ID   = A.FACTORY_ID
                                   AND C.ITEM_ID      = A.ITEM_ID
                                   AND C.OPERATION_ID = A.OPERATION_ID
                                   AND C.LINE_ID      = A.LINE_ID
                                   AND C.YYYYMMDD     = A.MONTH
                                   AND C.DATA_TYPE_1  = 'YIELD'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 6
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) >= 0.0
                              );

                INSERT INTO SCM_MST_YIELD_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , MONTH
                            , YIELD
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.YYYYMMDD
                     , IA.QTY / 100
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , TO_NUMBER(QTY) AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'YIELD'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 6    -- MONTH
                            AND YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_YIELD_SN B
                                     WHERE B.COMPANY_ID   = IA.COMPANY_ID
                                       AND B.DIVISION_ID  = IA.DIVISION_ID
                                       AND B.SITE_ID      = IA.SITE_ID
                                       AND B.PLANT_ID     = IA.PLANT_ID
                                       AND B.FACTORY_ID   = IA.FACTORY_ID
                                       AND B.ITEM_ID      = IA.ITEM_ID
                                       AND B.OPERATION_ID = IA.OPERATION_ID
                                       AND B.LINE_ID      = IA.LINE_ID
                                       AND B.MONTH        = IA.YYYYMMDD
                                  );

                /* #################################################### */
                /* SCM_MASTER_MANAGER_M_SN	CONFIRM 저장					*/
                /* #################################################### */
                SELECT COUNT(1)
                  INTO V_MOD_CNT
                  FROM GT_SCP0049_UPL_DATA A
                     , SCM_SYS_LOOKUP_VALUE_SN B
                 WHERE A.DATA_TYPE_1 = B.ATTRIBUTE1
                   AND A.DATA_TYPE_2 = B.ATTRIBUTE2
                   AND B.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                   AND B.ATTRIBUTE5       = 'Y'
                   AND A.DATA_TYPE_1 = 'No-Run'
                   AND A.DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                   AND LENGTH(RTRIM(A.YYYYMMDD)) = 6    -- MONTH
                   AND A.YYYYMMDD >= V_STD_YYYYMM
                   AND TO_NUMBER(A.QTY) >= 0.0;

                IF V_MOD_CNT > 0 THEN

                    /* ############################################################ */
                    -- 1. TACT TIME, DAILY CAPA  정보의 일별 데이터를 추가/저장 한다.
                    -- 2. 월별 년도별 데이터 수정은 별도의 테이블에 저장한다.
                    -- 3. TACT TIME 정보를 수정 했을 때 DAILY CAPA 값을 산출해서 저장한다.
                    -- 4. DAILY CAPA 정보를 수정 했을 때 TACT TIME 값을 산출해서 저장한다.
                    -- 5. TACT TIME 과 DAILY CAPA 데이터 산출을 위해 LOSS 테이블의 조회 후 임시 테이블에 저장한다.
                    /* ############################################################ */

                    /* LOSS UTIL 임시 테이블 저장 */
                    INSERT INTO GT_SCP0049_SAVE_LOSS_UTIL_LOSS
                                ( COMPANY_ID
                                , DIVISION_ID
                                , SITE_ID
                                , PLANT_ID
                                , FACTORY_ID
                                , OPERATION_ID
                                , LINE_ID
                                , ELECTRODE_TYPE
                                , WORK_MONTH
                                , TACT_DATA_TYPE
                                , LOSS_UTIL
                                , UPDATE_ID )
                    SELECT IA.COMPANY_ID
                         , IA.DIVISION_ID
                         , IA.SITE_ID
                         , IA.PLANT_ID
                         , IA.FACTORY_ID
                         , IA.OPERATION_ID
                         , IA.LINE_ID
                         , IA.ELECTRODE_TYPE
                         , IA.WORK_MONTH
                         , SA.TACT_DATA_TYPE
                          --, ROUND(EXP(SUM(ROUND(LOG(1-ISNULL(L.LOSS_RATE,0)),4))),4) AS LOSS_UTIL
                         , TO_CHAR(1 - ROUND(SUM(NVL(B.LOSS_RATE, 0)), 4))  AS UTIL
                         , IA.CREATED_BY
                      FROM ( SELECT DISTINCT
                                    COMPANY_ID
                                  , DIVISION_ID
                                  , SITE_ID
                                  , PLANT_ID
                                  , FACTORY_ID
                                  , OPERATION_ID
                                  , LINE_ID
                                  , ELECTRODE_TYPE
                                  , YYYYMMDD    AS WORK_MONTH
                                  , CREATED_BY
                               FROM GT_SCP0049_UPL_DATA
                              WHERE 1 = 1
                                AND DATA_TYPE_1 = 'No-Run'
                                AND DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                                AND LENGTH(RTRIM(YYYYMMDD)) = 6    -- MONTH
                                AND YYYYMMDD >= V_STD_YYYYMM
                                AND TO_NUMBER(QTY) >= 0.0 ) IA
                         , SCM_LOSS_M_SN B                          -- LOSS UTIL 값 조회
                         , (SELECT SEGMENT1  AS LOSS_CODE
                              FROM SCM_SYS_LOOKUP_VALUE_SN
                             WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                               AND ATTRIBUTE5       = 'Y'
                           ) XA
                         , (SELECT ATTRIBUTE1  AS TACT_DATA_TYPE     -- TACT TIME , DAILY CAPA 조회
                                 , SEGMENT2    AS PLANT_ID
                                 , SEGMENT3    AS OPERATION_ID
                              FROM SCM_SYS_LOOKUP_VALUE_SN
                             WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_CAPA_DEFINIT'
                               AND SEGMENT1         = 'LA002'
                               AND ACTIVE_FLAG      = 'Y'
                           ) SA
                     WHERE B.COMPANY_ID     = IA.COMPANY_ID
                       AND B.DIVISION_ID    = IA.DIVISION_ID
                       AND B.SITE_ID        = IA.SITE_ID
                       AND B.PLANT_ID       = IA.PLANT_ID
                       AND B.FACTORY_ID     = IA.FACTORY_ID
                       AND B.OPERATION_ID   = IA.OPERATION_ID
                       AND B.LINE_ID        = IA.LINE_ID
                       AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                       AND B.WORK_MONTH     = IA.WORK_MONTH
                       AND B.LOSS_CODE      = XA.LOSS_CODE
                       AND IA.PLANT_ID      = SA.PLANT_ID
                       AND IA.OPERATION_ID  = SA.OPERATION_ID
                     GROUP BY IA.COMPANY_ID
                            , IA.DIVISION_ID
                            , IA.SITE_ID
                            , IA.PLANT_ID
                            , IA.FACTORY_ID
                            , IA.OPERATION_ID
                            , IA.LINE_ID
                            , IA.ELECTRODE_TYPE
                            , IA.WORK_MONTH
                            , SA.TACT_DATA_TYPE
                            , IA.CREATED_BY;

                    /* ############################################################ */
                    -- 이력저장
                    /* ############################################################ */
                    DELETE FROM GT_SCP0049_LOSS;

                    INSERT INTO GT_SCP0049_LOSS
                                ( P_DATA_TABLE
                                , P_DATA_TYPE
                                , P_DIVISION_ID
                                , P_COMPANY_ID
                                , P_SITE_ID
                                , P_PLANT_ID
                                , P_FACTORY_ID
                                , P_LINE_ID
                                , P_ELECTRODE_TYPE
                                , P_OPERATION_ID
                                , P_ITEM_ID
                                , P_DAY_NAME
                                , P_UPDATE_ID )
                    SELECT 'T'            AS DATA_TABLE
                         , 'M'            AS DATA_TYPE
                         , B.DIVISION_ID
                         , B.COMPANY_ID
                         , B.SITE_ID
                         , B.PLANT_ID
                         , B.FACTORY_ID
                         , B.LINE_ID
                         , B.ELECTRODE_TYPE
                         , B.OPERATION_ID
                         , B.ITEM_ID       AS ITEM_ID
                         , A.WORK_MONTH    AS DAY_NAME
                         , A.UPDATE_ID
                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS A
                         , SCM_MST_TACT_TIME_SN B
                     WHERE B.COMPANY_ID     = A.COMPANY_ID
                       AND B.DIVISION_ID    = A.DIVISION_ID
                       AND B.SITE_ID        = A.SITE_ID
                       AND B.PLANT_ID       = A.PLANT_ID
                       AND B.FACTORY_ID     = A.FACTORY_ID
                       AND B.OPERATION_ID   = A.OPERATION_ID
                       AND B.LINE_ID        = A.LINE_ID
                       AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                       AND B.MONTH          = A.WORK_MONTH;

                    INSERT INTO GT_SCP0049_LOSS
                                ( P_DATA_TABLE
                                , P_DATA_TYPE
                                , P_DIVISION_ID
                                , P_COMPANY_ID
                                , P_SITE_ID
                                , P_PLANT_ID
                                , P_FACTORY_ID
                                , P_LINE_ID
                                , P_ELECTRODE_TYPE
                                , P_OPERATION_ID
                                , P_ITEM_ID
                                , P_DAY_NAME
                                , P_UPDATE_ID )
                    SELECT 'T'            AS DATA_TABLE
                         , 'D'            AS DATA_TYPE
                         , B.DIVISION_ID
                         , B.COMPANY_ID
                         , B.SITE_ID
                         , B.PLANT_ID
                         , B.FACTORY_ID
                         , B.LINE_ID
                         , B.ELECTRODE_TYPE
                         , B.OPERATION_ID
                         , B.ITEM_ID                            AS ITEM_ID
                         , TO_CHAR(B.START_TIME, 'YYYYMMDD')    AS DAY_NAME
                         , A.UPDATE_ID
                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS A
                         , SCM_MST_TACT_TIME_EXCEPT_SN B
                     WHERE B.COMPANY_ID     = A.COMPANY_ID
                       AND B.DIVISION_ID    = A.DIVISION_ID
                       AND B.SITE_ID        = A.SITE_ID
                       AND B.PLANT_ID       = A.PLANT_ID
                       AND B.FACTORY_ID     = A.FACTORY_ID
                       AND B.OPERATION_ID   = A.OPERATION_ID
                       AND B.LINE_ID        = A.LINE_ID
                       AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                       AND TO_CHAR(B.START_TIME, 'YYYYMM') = A.WORK_MONTH;

                    /* AS-IS EXEC [dbo].[PR_SCP_CAPA_HIST_DATASET] @SCP0049_LOSS 대응 */
                    DELETE FROM GT_SCP0049_DS;

                    INSERT INTO GT_SCP0049_DS
                                ( P_DIVISION_ID
                                , P_COMPANY_ID
                                , P_SITE_ID
                                , P_PLANT_ID
                                , P_FACTORY_ID
                                , P_LINE_ID
                                , P_OPERATION_ID
                                , P_ELECTRODE_TYPE
                                , P_ITEM_ID
                                , P_LOSS_CODE
                                , P_DATA_TABLE
                                , P_DATA_TYPE
                                , P_DAY_NAME
                                , P_DAY_QTY
                                , P_LANE_QTY
                                , P_CONFIRM_FLAG
                                , P_UPDATE_ID )
                    SELECT P_DIVISION_ID
                         , P_COMPANY_ID
                         , P_SITE_ID
                         , P_PLANT_ID
                         , P_FACTORY_ID
                         , P_LINE_ID
                         , P_OPERATION_ID
                         , P_ELECTRODE_TYPE
                         , P_ITEM_ID
                         , P_LOSS_CODE
                         , P_DATA_TABLE
                         , P_DATA_TYPE
                         , P_DAY_NAME
                         , P_DAY_QTY
                         , P_LANE_QTY
                         , P_CONFIRM_FLAG
                         , P_UPDATE_ID
                      FROM GT_SCP0049_LOSS;

                    P_CAPA_HIST_DATASET;

                    /* 데이터 추가/수정 */
                    UPDATE SCM_MST_TACT_TIME_SN A
                       SET (TACT_TIME, DAILY_CAPA, UPDATE_ID, UPDATE_TIME)
                             = ( SELECT CASE WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(A.DAILY_CAPA, 0) = 0 THEN 0
                                             WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / A.DAILY_CAPA * NVL(TO_NUMBER(B.LOSS_UTIL), 1)
                                             ELSE A.TACT_TIME END
                                      , TRUNC(CASE WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) = 0 THEN 0
                                                   WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) > 0 THEN ROUND(86400 / A.TACT_TIME * NVL(TO_NUMBER(B.LOSS_UTIL), 1), 0)
                                                   ELSE A.DAILY_CAPA END)
                                      , B.UPDATE_ID
                                      , SYSDATE
                                   FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS B
                                  WHERE B.COMPANY_ID     = A.COMPANY_ID
                                    AND B.DIVISION_ID    = A.DIVISION_ID
                                    AND B.SITE_ID        = A.SITE_ID
                                    AND B.PLANT_ID       = A.PLANT_ID
                                    AND B.FACTORY_ID     = A.FACTORY_ID
                                    AND B.OPERATION_ID   = A.OPERATION_ID
                                    AND B.LINE_ID        = A.LINE_ID
                                    AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                    AND B.WORK_MONTH     = A.MONTH )
                     WHERE EXISTS ( SELECT 1
                                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS C
                                     WHERE C.COMPANY_ID     = A.COMPANY_ID
                                       AND C.DIVISION_ID    = A.DIVISION_ID
                                       AND C.SITE_ID        = A.SITE_ID
                                       AND C.PLANT_ID       = A.PLANT_ID
                                       AND C.FACTORY_ID     = A.FACTORY_ID
                                       AND C.OPERATION_ID   = A.OPERATION_ID
                                       AND C.LINE_ID        = A.LINE_ID
                                       AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                       AND C.WORK_MONTH     = A.MONTH
                                  );

                    /* 데이터 저장 */
                    UPDATE SCM_MST_TACT_TIME_EXCEPT_SN A
                       SET (TACT_TIME, DAILY_CAPA, UPDATE_ID, UPDATE_TIME)
                             = ( SELECT CASE WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' AND NVL(A.DAILY_CAPA, 0) = 0 THEN 0
                                             WHEN B.TACT_DATA_TYPE = 'DAILY CAPA' THEN 86400 / A.DAILY_CAPA * NVL(TO_NUMBER(B.LOSS_UTIL), 1)
                                             ELSE A.TACT_TIME END
                                      , TRUNC(CASE WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) = 0 THEN 0
                                                   WHEN B.TACT_DATA_TYPE = 'TACT TIME' AND NVL(A.TACT_TIME, 0) > 0 THEN ROUND(86400 / A.TACT_TIME * NVL(TO_NUMBER(B.LOSS_UTIL), 1), 0)
                                                   ELSE A.DAILY_CAPA END)
                                      , B.UPDATE_ID
                                      , SYSDATE
                                   FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS B
                                  WHERE B.COMPANY_ID     = A.COMPANY_ID
                                    AND B.DIVISION_ID    = A.DIVISION_ID
                                    AND B.SITE_ID        = A.SITE_ID
                                    AND B.PLANT_ID       = A.PLANT_ID
                                    AND B.FACTORY_ID     = A.FACTORY_ID
                                    AND B.OPERATION_ID   = A.OPERATION_ID
                                    AND B.LINE_ID        = A.LINE_ID
                                    AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                    AND B.WORK_MONTH     = TO_CHAR(A.START_TIME, 'YYYYMM') )
                     WHERE EXISTS ( SELECT 1
                                      FROM GT_SCP0049_SAVE_LOSS_UTIL_LOSS C
                                     WHERE C.COMPANY_ID     = A.COMPANY_ID
                                       AND C.DIVISION_ID    = A.DIVISION_ID
                                       AND C.SITE_ID        = A.SITE_ID
                                       AND C.PLANT_ID       = A.PLANT_ID
                                       AND C.FACTORY_ID     = A.FACTORY_ID
                                       AND C.OPERATION_ID   = A.OPERATION_ID
                                       AND C.LINE_ID        = A.LINE_ID
                                       AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                       AND C.WORK_MONTH     = TO_CHAR(A.START_TIME, 'YYYYMM')
                                  );

                END IF;

                /* #################################################### */
                /* SCM_MASTER_MANAGER_M_SN	CONFIRM 저장					*/
                /* #################################################### */
                V_LOG_ERROR := 'CONFIRM';

                UPDATE SCM_MASTER_MANAGER_M_SN A
                   SET (CONFIRM_FLAG, CONFIRM_ID, CONFIRM_TIME, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT IA.FINISH
                                  , IA.CREATED_BY
                                  , SYSDATE
                                  , IA.CREATED_BY
                                  , SYSDATE
                               FROM ( SELECT DISTINCT
                                             B.DIVISION_ID
                                           , B.COMPANY_ID
                                           , B.SITE_ID
                                           , B.PLANT_ID
                                           , B.FACTORY_ID
                                           , B.LINE_ID
                                           , B.OPERATION_ID
                                           , B.ELECTRODE_TYPE
                                           , B.CREATED_BY
                                           , B.FINISH
                                           , B.DATA_TYPE_1
                                           , ( SELECT SEGMENT1
                                                 FROM SCM_SYS_LOOKUP_VALUE_SN C
                                                WHERE 1 = 1
                                                  AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                  AND C.ACTIVE_FLAG      = 'Y'
                                                  AND C.ATTRIBUTE1       = ( CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 'TACT TIME' ELSE B.DATA_TYPE_1 END )
                                                  --AND LV.ATTRIBUTE2 = T.DATA_TYPE2
                                             ) AS LOSS_CODE
                                        FROM GT_SCP0049_UPL_DATA B
                                       WHERE 1 = 1
                                         AND B.DATA_TYPE_1 IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD')
                                      UNION ALL
                                      SELECT DISTINCT
                                             D.DIVISION_ID
                                           , D.COMPANY_ID
                                           , D.SITE_ID
                                           , D.PLANT_ID
                                           , D.FACTORY_ID
                                           , D.LINE_ID
                                           , D.OPERATION_ID
                                           , D.ELECTRODE_TYPE
                                           , D.CREATED_BY
                                           , D.FINISH
                                           , D.DATA_TYPE_1
                                           , ( SELECT SEGMENT1
                                                 FROM SCM_SYS_LOOKUP_VALUE_SN E
                                                WHERE 1 = 1
                                                  AND E.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                  AND E.ACTIVE_FLAG      = 'Y'
                                                  AND E.ATTRIBUTE1       = D.DATA_TYPE_1
                                                  AND E.ATTRIBUTE2       = D.DATA_TYPE_2
                                             ) AS LOSS_CODE
                                        FROM GT_SCP0049_UPL_DATA D
                                       WHERE 1 = 1
                                         AND D.DATA_TYPE_1 NOT IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD') ) IA
                              WHERE IA.COMPANY_ID     = A.COMPANY_ID
                                AND IA.DIVISION_ID    = A.DIVISION_ID
                                AND IA.SITE_ID        = A.SITE_ID
                                AND IA.PLANT_ID       = A.PLANT_ID
                                AND IA.FACTORY_ID     = A.FACTORY_ID
                                AND IA.OPERATION_ID   = A.OPERATION_ID
                                AND IA.LINE_ID        = A.LINE_ID
                                AND IA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND IA.LOSS_CODE      = A.LOSS_CODE )
                 WHERE EXISTS ( SELECT 1
                                  FROM ( SELECT DISTINCT
                                                F.DIVISION_ID
                                              , F.COMPANY_ID
                                              , F.SITE_ID
                                              , F.PLANT_ID
                                              , F.FACTORY_ID
                                              , F.LINE_ID
                                              , F.OPERATION_ID
                                              , F.ELECTRODE_TYPE
                                              , ( SELECT SEGMENT1
                                                    FROM SCM_SYS_LOOKUP_VALUE_SN G
                                                   WHERE 1 = 1
                                                     AND G.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                     AND G.ACTIVE_FLAG      = 'Y'
                                                     AND G.ATTRIBUTE1       = ( CASE WHEN F.DATA_TYPE_1 = 'DAILY CAPA' THEN 'TACT TIME' ELSE F.DATA_TYPE_1 END )
                                                ) AS LOSS_CODE
                                           FROM GT_SCP0049_UPL_DATA F
                                          WHERE 1 = 1
                                            AND F.DATA_TYPE_1 IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD')
                                         UNION ALL
                                         SELECT DISTINCT
                                                H.DIVISION_ID
                                              , H.COMPANY_ID
                                              , H.SITE_ID
                                              , H.PLANT_ID
                                              , H.FACTORY_ID
                                              , H.LINE_ID
                                              , H.OPERATION_ID
                                              , H.ELECTRODE_TYPE
                                              , ( SELECT SEGMENT1
                                                    FROM SCM_SYS_LOOKUP_VALUE_SN I
                                                   WHERE 1 = 1
                                                     AND I.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                     AND I.ACTIVE_FLAG      = 'Y'
                                                     AND I.ATTRIBUTE1       = H.DATA_TYPE_1
                                                     AND I.ATTRIBUTE2       = H.DATA_TYPE_2
                                                ) AS LOSS_CODE
                                           FROM GT_SCP0049_UPL_DATA H
                                          WHERE 1 = 1
                                            AND H.DATA_TYPE_1 NOT IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD') ) XA
                                 WHERE XA.COMPANY_ID     = A.COMPANY_ID
                                   AND XA.DIVISION_ID    = A.DIVISION_ID
                                   AND XA.SITE_ID        = A.SITE_ID
                                   AND XA.PLANT_ID       = A.PLANT_ID
                                   AND XA.FACTORY_ID     = A.FACTORY_ID
                                   AND XA.OPERATION_ID   = A.OPERATION_ID
                                   AND XA.LINE_ID        = A.LINE_ID
                                   AND XA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND XA.LOSS_CODE      = A.LOSS_CODE
                              );

                V_ROWCOUNT    := SQL%ROWCOUNT;
                V_LOG_TYPE    := 'INSERT';
                N_LOG_COUNT   := N_LOG_COUNT + 1;
                V_LOG_MESSAGE := '########## MERGE SCP0049 CAPA DATA END ##########';
                V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
                D_EVENT_DATE  := SYSDATE;
                P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

                /* AS-IS COMMIT TRANSACTION SCP0049_CAPA_UPLOAD */
                COMMIT;

            EXCEPTION   /* AS-IS BEGIN CATCH */
                WHEN OTHERS THEN
                    /* ROLLBACK 은 결과 커서 OPEN 앞에 둔다(뒤에 두면 커서가 닫힌다) */
                    ROLLBACK TO SAVEPOINT SP_SCP0049_CAPA_UPLOAD;

                    V_LOG_ERROR := V_LOG_ERROR || ' ::  ' || SQLERRM;
                    V_ERR       := V_LOG_ERROR;

                    /* AS-IS 는 ROLLBACK 뒤 SCM_SYS_LOG_BATCH 에 직접 적재(문장 단위 확정) */
                    /* PR_SCM_SYS_LOG_BATCH 가 자율 트랜잭션이므로 같은 결과가 된다      */
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, V_LOG_ERROR, NULL, SYSDATE, NULL
                                       , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;

            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## INSERT/UPDATE SCP0049 CAPA DATA END ##########';
            V_DESCRIPTION := TO_CHAR(P_MODE);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        END IF;

        V_LOG_TYPE    := 'INSERT';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## INSERT DATA END ##########';
        V_DESCRIPTION := TO_CHAR(P_MODE);
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        V_LOG_TYPE    := 'END';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        V_RESULT_EVENT := V_COUNT;

        /* 결과 커서 OPEN 은 반드시 RETURN 앞 */
        IF V_ERR IS NULL THEN
            OPEN O_RESULT_CURSOR FOR
            SELECT 'S'            AS RESULT_CODE
                 , V_RESULT_EVENT AS ERROR_CNT
              FROM DUAL;
        ELSE
            OPEN O_RESULT_CURSOR FOR
            SELECT '-1'  AS CODE
                 , V_ERR AS MSG
              FROM DUAL;
        END IF;

    END P_CAPA_EXCEL_UPLOAD;

/*==============================================================================================
     * Program ID   : PKG_SCP0049.P_CAPA_EXCEL_UPLOAD_DAY
     * Description  : CAPA 일별 엑셀 업로드 검증(모드 0) · 반영(모드 1 이상)
     * AS-IS        : SCP0049_CAPA_EXCEL_UPLOAD_DAY (MSSQL)
     *
     * AS-IS 주석 원문 보존
     * ---------------------------------------------------------------------------------------------
     * 2023.04.10	leejsthira2		신규 : CAPA 일별 엑셀 업로드
     * 2025.08.01   hrkim			PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 완성 공정 하드코딩 변경
     * 2025/10/15   hrkim		    [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 : JV 셀생산 Real Line 기준으로 Virtual Line Capa정보 동기화 저장
     * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     * ---------------------------------------------------------------------------------------------
     *
     * 인자 : 화면(서버) 호출 규약 5인자
     *   P_MODE          - 0 = 검증 · 1 이상 = 반영 (AS-IS @p_mode)
     *   P_SES_USER_ID   - 업로드 작성자 (AS-IS @p_created_by)
     *   P_MNU_ID        - 화면(메뉴) 식별자. AS-IS 가 쓰지 않으므로 본문에서 사용하지 않음
     *                     (프로그램 구분은 AS-IS 와 같이 'SCP0049' 고정)
     *   P_SHT_NM        - 업로드 시트 이름. AS-IS 가 쓰지 않으므로 본문에서 사용하지 않음
     *                     (월별 · 일별 프로시저가 시트 이름으로 갈리므로 'CAPA_DAY' 고정)
     *   O_RESULT_CURSOR - 결과 커서 1개 (정상 RESULT_CODE 'S' · 오류 CODE '-1' + MSG)
     *
     * 사용 GTT : GT_SCP0049_UPL_DATA(신규) · GT_SCP0049_UPL_VALID(신규)
     *            GT_SCP0049_UPL_LU_TACT_DAY(신규 · WORK_DATE 포함)
     *            GT_SCP0049(이력) · GT_SCP0049_DELETE(삭제) · GT_SCP0049_DS(이력 프로시저 인계용)
     *
     * 내부 프로시저 의존 : P_CAPA_HIST_DATASET · P_CAPA_LINE_ASSIGN_DELETE_DATASET (둘 다 인자 없음 · GT_SCP0049_DS 를 읽음)
     *            (AS-IS PR_SCP_CAPA_HIST_DATASET · PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET 흡수분 · P_SAVE_CAPA 와 같은 규약)
     *==============================================================================================*/
    PROCEDURE P_CAPA_EXCEL_UPLOAD_DAY
    (
        P_MODE           IN  NUMBER,
        P_SES_USER_ID    IN  VARCHAR2,
        P_MNU_ID         IN  VARCHAR2,
        P_SHT_NM         IN  VARCHAR2,
        O_RESULT_CURSOR  OUT SYS_REFCURSOR
    )
    IS
        V_PROGRAM_ID      VARCHAR2(40 CHAR)   := 'SCP0049';
        V_SHEET_NAME      VARCHAR2(40 CHAR)   := 'CAPA_DAY';
        V_CREATION_DATE   VARCHAR2(40 CHAR);
        V_COUNT           NUMBER(10);

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME    VARCHAR2(150 CHAR)  := 'SCP0049_CAPA_EXCEL_UPLOAD_DAY';
        V_LOG_TYPE        VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
        N_LOG_COUNT       NUMBER(10)          := 0;
        V_LOG_MESSAGE     VARCHAR2(1000 CHAR);
        V_DESCRIPTION     VARCHAR2(500 CHAR);
        D_EVENT_DATE      DATE;
        V_LOG_ERROR       VARCHAR2(1000 CHAR);

        V_STD_YYYYMMDD    VARCHAR2(8 CHAR);   /* 수정 가능 기준 날짜 설정 */
        V_STD_YYYYMM      VARCHAR2(6 CHAR);   /* 수정 가능 기준 날짜 설정 */
        V_STD_YYYY        VARCHAR2(4 CHAR);   /* 수정 가능 기준 날짜 설정 */

        V_CREATED_BY      VARCHAR2(150 CHAR);

        /* 수정 결과 카운트 */
        V_MOD_CNT         NUMBER(10)          := 0;

        /* AS-IS @@ROWCOUNT 재현 */
        V_ROWCOUNT        NUMBER(10)          := 0;

        /* 결과 커서 값 */
        V_ERR             VARCHAR2(4000 CHAR);
        V_RESULT_EVENT    NUMBER(10)          := 0;

        /* AS-IS 의 EXEC PR_SCM_SYS_LOG_BATCH 반복 호출 묶음 (PR_SCM_SYS_LOG_BATCH 는 자율 트랜잭션) */
        PROCEDURE P_LOG
        (
            P_LOG_TYPE     IN  VARCHAR2,
            P_LOG_MESSAGE  IN  VARCHAR2,
            P_DESC         IN  VARCHAR2
        )
        IS
        BEGIN
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, P_LOG_TYPE, N_LOG_COUNT, P_LOG_MESSAGE, P_DESC, D_EVENT_DATE);
        END P_LOG;

    BEGIN

        /* 기준 일자 설정 */
        V_STD_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');  /* 오늘 날짜 */
        V_STD_YYYYMM   := TO_CHAR(SYSDATE, 'YYYYMM');    /* 해당 월 */
        V_STD_YYYY     := TO_CHAR(SYSDATE, 'YYYY');      /* 해당 월 */

        /*------------------------------------------------------------------------------------------
         * [PJ20257329] Cell 완성 공정 하드 코딩 변경
         *   SCP Cell Final 공정 정보 - Cell Packaging/Assembly
         * AS-IS 테이블 변수 @SCP_CELL_FINAL_OPERATION 은 한 곳에서만 참조하므로 인라인 뷰로 흡수
         *------------------------------------------------------------------------------------------*/

        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        SELECT TO_CHAR(MAX(CREATION_DATE), 'YYYY-MM-DD HH24:MI:SS.FF3')
          INTO V_CREATION_DATE
          FROM SCM_ADM_EXCEL_UPLOAD
         WHERE PROGRAM_ID = V_PROGRAM_ID
           AND SHEET_NAME = V_SHEET_NAME
           AND CREATED_BY = P_SES_USER_ID;

        IF V_CREATION_DATE IS NULL THEN
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := 'Data Not Found [' || V_CREATION_DATE || ']';
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);
        END IF;

        /* 사용자 정보 설정 */
        V_CREATED_BY := P_SES_USER_ID;

        /* @p_mode = 0 이면 Validation */
        IF NVL(P_MODE, 0) = 0 THEN

            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = 'UPLOAD'
                 , MESSAGE_TEXT       = NULL
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID = V_PROGRAM_ID
               AND SHEET_NAME = V_SHEET_NAME
               AND CREATED_BY = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND NVL(UPLOAD_STATUS_CODE, 'X') != 'UPLOAD';

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## RESET Status = UPLOAD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ///////////////////////////// VALIDATION CHECK ///////////////////////// */

            /* ######################################################## */
            /* TITLE 처리												*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = '@TITLE'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID = V_PROGRAM_ID
               AND SHEET_NAME = V_SHEET_NAME
               AND CREATED_BY = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND (UPPER(ATTRIBUTE1) = 'DIV*' OR UPPER(ATTRIBUTE1) = 'DIV' OR UPPER(ATTRIBUTE1) = 'DIVISION');

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## TITLE Header Line ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /*------------------------------------------------------------------------------------------
             * AS-IS 원문 주석 보존 (블록 주석으로 막혀 있어 변환 대상 아님)
             * 버킷 영역 날짜값에 대한 validation -- ... 약 400개 컬럼에 대해서 조건 비교하는데 문제가 될수
             * 있으므로 일단 주석처리, 어차피 실저장때 날짜값에 대한 len 처리로 잘못 저장되지는 않음
             *   (막혀 있는 구간 : UPLOAD_STATUS_CODE = '@TITLE' 행의 ATTRIBUTE16 ~ ATTRIBUTE400 중
             *    값이 있고 길이가 8 이 아닌 칸이 있으면 'Invalid date value.' 로 ERROR 표시)
             *------------------------------------------------------------------------------------------*/
            /* #################################################### */
            /* 필수 값 NULL 값 체크									*/
            /* ATTRIBUTE6  : Line*									*/
            /* ATTRIBUTE7  : Operation*								*/
            /* ATTRIBUTE8  : Line Type*								*/
            /* ATTRIBUTE10 : Level 1*								*/
            /* ATTRIBUTE11 : Level 2*								*/
            /* ATTRIBUTE12 : Material*								*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = CASE WHEN TRIM(ATTRIBUTE6) IS NULL OR TRIM(ATTRIBUTE8) IS NULL THEN 'NULL LINE & TYPE Data.'
                                             WHEN TRIM(ATTRIBUTE7) IS NULL                            THEN 'NULL OPERATION Data.'
                                             WHEN TRIM(ATTRIBUTE10) IS NULL                           THEN 'NULL LEVEL 1 Data.'
                                             WHEN ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE11) IS NULL
                                                                                                      THEN 'NULL LEVEL 2(LOSS KEY) Data.'
                                             WHEN ATTRIBUTE10 IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE12) IS NULL
                                                                                                      THEN 'NULL ITEM Data.'
                                        END
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE PROGRAM_ID         = V_PROGRAM_ID
               AND SHEET_NAME         = V_SHEET_NAME
               AND CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND UPLOAD_STATUS_CODE = 'UPLOAD'
               AND (   TRIM(ATTRIBUTE6) IS NULL OR TRIM(ATTRIBUTE7) IS NULL OR TRIM(ATTRIBUTE8) IS NULL OR TRIM(ATTRIBUTE10) IS NULL
                    OR ( ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE11) IS NULL )
                    OR ( ATTRIBUTE10 IN     ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD') AND TRIM(ATTRIBUTE12) IS NULL )
                   );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## ERROR NULL Column Data ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LOSS 값 체크											*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Loss Type.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 NOT IN ('LINE ASSIGN', 'TACT TIME', 'DAILY CAPA', 'YIELD')
               AND NOT EXISTS ( SELECT 1
                                  FROM (SELECT SEGMENT1    AS LOSS_CODE
                                             , ATTRIBUTE1   AS LEVEL1
                                             , ATTRIBUTE2   AS LEVEL2
                                          FROM SCM_SYS_LOOKUP_VALUE_SN
                                         WHERE 1 = 1
                                           AND LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT') IA
                                 WHERE 1 = 1
                                   AND IA.LEVEL1 = A.ATTRIBUTE10
                                   AND IA.LEVEL2 = A.ATTRIBUTE11
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Loss Type ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LINE 체크												*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line & Line Type.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10       != 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line & Line Type. ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* LINE 체크		YIELD									*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line & Line Type. YIELD'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID = A.ATTRIBUTE6
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line & Line Type. YIELD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* OPERATION_ID 체크										*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line Operation.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10       != 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                                   AND B.OPERATION_ID   = A.ATTRIBUTE7
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line Operation ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* OPERATION_ID 체크		YIELD							*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Line Operation. YIELD'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'YIELD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_LINE_HIERARCHY_V_SN B
                                 WHERE 1 = 1
                                   AND B.LINE_ID      = A.ATTRIBUTE6
                                   AND B.OPERATION_ID = A.ATTRIBUTE7
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Line Operation YIELD ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* 필수 항목 기준으로 다른 Data Update 					*/
            /* AS-IS UPDATE ... FROM 2개 테이블 → 상관 서브쿼리 UPDATE	*/
            /* 계층 뷰가 같은 키로 여러 행이면 AS-IS 는 임의 1행을 쓰므로	*/
            /* ROWNUM = 1 로 같은 동작(ORA-01427 회피)을 재현			*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET (ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5)
                     = ( SELECT B.DIVISION_ID
                              , B.COMPANY_ID
                              , B.SITE_ID
                              , B.PLANT_ID
                              , B.FACTORY_ID
                           FROM SCM_LINE_HIERARCHY_V_SN B
                          WHERE B.LINE_ID        = A.ATTRIBUTE6
                            AND B.OPERATION_ID   = A.ATTRIBUTE7
                            AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                            AND ROWNUM           = 1 )
                 , LAST_UPDATED_BY  = V_CREATED_BY
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM SCM_LINE_HIERARCHY_V_SN C
                             WHERE C.LINE_ID        = A.ATTRIBUTE6
                               AND C.OPERATION_ID   = A.ATTRIBUTE7
                               AND C.ELECTRODE_TYPE = A.ATTRIBUTE8
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## LINE HIERACHY UPDATE ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* 권한 체크												*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Auth'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_MASTER_MANAGER_M_SN B
                                 WHERE 1 = 1
                                   AND B.DIVISION_ID    = A.ATTRIBUTE1
                                   AND B.COMPANY_ID     = A.ATTRIBUTE2
                                   AND B.SITE_ID        = A.ATTRIBUTE3
                                   AND B.PLANT_ID       = A.ATTRIBUTE4
                                   AND B.FACTORY_ID     = A.ATTRIBUTE5
                                   AND B.LINE_ID        = A.ATTRIBUTE6
                                   AND B.OPERATION_ID   = A.ATTRIBUTE7
                                   AND B.ELECTRODE_TYPE = A.ATTRIBUTE8
                                   AND B.LOSS_CODE      = ( SELECT SEGMENT1
                                                              FROM SCM_SYS_LOOKUP_VALUE_SN C
                                                             WHERE 1 = 1
                                                               AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                               AND C.ACTIVE_FLAG      = 'Y'
                                                               AND C.ATTRIBUTE1       = CASE WHEN A.ATTRIBUTE10 = 'DAILY CAPA' THEN 'TACT TIME' ELSE A.ATTRIBUTE10 END
                                                               AND C.ATTRIBUTE2       = CASE WHEN A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD' ) THEN '-'
                                                                                             ELSE A.ATTRIBUTE11
                                                                                        END
                                                          )
                                   AND (B.USER_ID_1 = V_CREATED_BY OR B.USER_ID_2 = V_CREATED_BY OR B.USER_ID_3 = V_CREATED_BY OR B.USER_ID_4 = V_CREATED_BY OR B.USER_ID_5 = V_CREATED_BY
                                          OR B.USER_ID_6 = V_CREATED_BY OR B.USER_ID_7 = V_CREATED_BY OR B.USER_ID_8 = V_CREATED_BY OR B.USER_ID_9 = V_CREATED_BY OR B.USER_ID_10 = V_CREATED_BY
                                       )
                                UNION ALL
                                SELECT 1
                                  /* 2026.09.30 AJS 수정 (START) */
                                --FROM TB_FX_USERGROUPINFO
                               --WHERE USERID = V_CREATED_BY
                                 --AND USEYN  = 'Y'
                                 --AND GROUPID = 'SCM PI Admin'
                                  FROM SCM_ADM_USER_GR_MPG_M
                                 WHERE USER_ID = V_CREATED_BY
                                   AND USE_YN  = 'Y'
                                   AND USER_GR_ID = 'SCM PI Admin'
                                  /* 2026.09.30 AJS 수정 (END) */
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Auth ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID 체크											*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND NOT EXISTS ( SELECT 1
                                  FROM SCM_ITEM_M_SN B
                                 WHERE 1 = 1
                                   AND B.DIVISION_ID = A.ATTRIBUTE1
                                   AND B.COMPANY_ID  = A.ATTRIBUTE2
                                   AND B.SITE_ID     = A.ATTRIBUTE3
                                   AND B.ITEM_ID     = A.ATTRIBUTE12
                                   AND B.ACTIVE_FLAG = 'Y'
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID - OPERATION 체크								*/
            /* AS-IS UPDATE ... FROM 2개 테이블 → EXISTS 로 변환		*/
            /* MSSQL SUBSTRING 은 범위를 넘으면 빈 문자를 주고			*/
            /* 빈 문자 != 'E2000' 이 참이 되므로 NVL(...,' ') 로 맞춘다	*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item - Operation'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND A.ATTRIBUTE7 NOT LIKE 'F%'
               AND EXISTS ( SELECT 1
                              FROM SCM_ITEM_M_SN B
                             WHERE B.DIVISION_ID = A.ATTRIBUTE1
                               AND B.COMPANY_ID  = A.ATTRIBUTE2
                               AND B.SITE_ID     = A.ATTRIBUTE3
                               AND B.ITEM_ID     = A.ATTRIBUTE12
                               AND B.ACTIVE_FLAG = 'Y'
                               AND B.FLOW_ID                          != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID,  1, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID,  6, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 11, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 16, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                               AND NVL(SUBSTR(B.FLOW_ID, 12, 5), ' ') != A.ATTRIBUTE7 -- OPERATION_ID
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item - Operation ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM_ID - OPERATION (FORMATION) 체크					*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item - Operation (FROMATION)'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10 IN ( 'LINE ASSIGN','TACT TIME', 'DAILY CAPA', 'YIELD' )
               AND A.ATTRIBUTE7 LIKE 'F%'
               AND EXISTS ( SELECT 1
                              FROM SCM_ITEM_M_SN B
                             WHERE B.DIVISION_ID = A.ATTRIBUTE1
                               AND B.COMPANY_ID  = A.ATTRIBUTE2
                               AND B.SITE_ID     = A.ATTRIBUTE3
                               AND B.ITEM_ID     = A.ATTRIBUTE12
                               AND B.ACTIVE_FLAG = 'Y'
                               -- [PJ20257329] 변경전 AND (B.FLOW_ID NOT IN ('A3000','A9000') OR B.FORMATION_FLOW_ID IS NULL)
                               AND ( B.FLOW_ID NOT IN ( SELECT SEGMENT1
                                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                         WHERE 1 = 1
                                                           AND LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                                           AND SEGMENT3    = 'A'  -- 공정그룹(Cell)
                                                           AND ATTRIBUTE1  = 'Y'  -- Final Operation
                                                       )
                                     OR B.FORMATION_FLOW_ID IS NULL )            -- [PJ20257329] Cell 완성 공정 하드 코딩 변경
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item - Operation (FORMATION) ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* #################################################### */
            /* ITEM , LANE QTY 체크 - E2000 공정만 체크				*/
            /* #################################################### */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Invalid Item. Lane Qty'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND A.ATTRIBUTE10        = 'LINE ASSIGN'
               AND A.ATTRIBUTE7         = 'E2000'
               AND NOT EXISTS ( SELECT 1
                                  FROM (SELECT B.COMPANY_ID
                                             , B.DIVISION_ID
                                             , B.SITE_ID
                                             , B.PLANT_ID
                                             , B.FACTORY_ID
                                             , B.ITEM_ID
                                             , C.LINE_ID
                                             , C.ELECTRODE_TYPE
                                             , C.OPERATION_ID
                                             , B.PROD_VERSION_TYPE
                                             , B.LANE_QTY
                                          FROM SCM_ITEM_LANE_M_SN B
                                             , SCM_LINE_M_SN C
                                         WHERE B.ACTIVE_FLAG       = 'Y'
                                           AND C.ACTIVE_FLAG       = 'Y'
                                           AND B.COMPANY_ID        = C.COMPANY_ID
                                           AND B.DIVISION_ID       = C.DIVISION_ID
                                           AND B.SITE_ID           = C.SITE_ID
                                           AND B.PLANT_ID          = C.PLANT_ID
                                           AND B.FACTORY_ID        = C.FACTORY_ID
                                           AND B.PROD_VERSION_TYPE = C.PROD_VERSION_TYPE
                                           AND C.OPERATION_ID      = 'E2000'  ) IA
                                 WHERE IA.DIVISION_ID     = A.ATTRIBUTE1
                                   AND IA.COMPANY_ID      = A.ATTRIBUTE2
                                   AND IA.SITE_ID         = A.ATTRIBUTE3
                                   AND IA.LINE_ID         = A.ATTRIBUTE6
                                   AND IA.OPERATION_ID    = A.ATTRIBUTE7
                                   AND IA.ELECTRODE_TYPE  = A.ATTRIBUTE8
                                   AND IA.ITEM_ID         = A.ATTRIBUTE12
                                   AND TRUNC(IA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(A.ATTRIBUTE13), '0'))), 0)
                              );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Invalid Item. Lane Qty ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ######################################################## */
            /* 중복 값 체크(LOSS) 체크									*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM ( SELECT PROGRAM_ID
                                          , SHEET_NAME
                                          , CREATION_DATE
                                          , ATTRIBUTE1   AS DIVISION_ID
                                          , ATTRIBUTE2   AS COMPANY_ID
                                          , ATTRIBUTE3   AS SITE_ID
                                          , ATTRIBUTE4   AS PLANT_ID
                                          , ATTRIBUTE5   AS FACTORY_ID
                                          , ATTRIBUTE6   AS LINE_ID
                                          , ATTRIBUTE7   AS OPERATION_ID
                                          , ATTRIBUTE8   AS ELECTRODE_TYPE
                                          , ATTRIBUTE10  AS DATA_TYPE_1
                                          , ATTRIBUTE11  AS DATA_TYPE_2
                                       FROM SCM_ADM_EXCEL_UPLOAD
                                      WHERE PROGRAM_ID = V_PROGRAM_ID
                                        AND SHEET_NAME = V_SHEET_NAME
                                        AND CREATED_BY = V_CREATED_BY
                                        AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                        AND UPLOAD_STATUS_CODE = 'UPLOAD'
                                        AND ATTRIBUTE10 IN ('No-Load','No-Run','Not-Available','Performance(%)','Quality(%)')
                                      GROUP BY PROGRAM_ID
                                             , SHEET_NAME
                                             , CREATION_DATE
                                             , ATTRIBUTE1
                                             , ATTRIBUTE2
                                             , ATTRIBUTE3
                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE8
                                             , ATTRIBUTE10
                                             , ATTRIBUTE11
                                     HAVING COUNT(1) > 1 ) IA
                             WHERE 1 = 1
                               AND IA.DIVISION_ID    = A.ATTRIBUTE1
                               AND IA.COMPANY_ID     = A.ATTRIBUTE2
                               AND IA.SITE_ID        = A.ATTRIBUTE3
                               AND IA.PLANT_ID       = A.ATTRIBUTE4
                               AND IA.FACTORY_ID     = A.ATTRIBUTE5
                               AND IA.LINE_ID        = A.ATTRIBUTE6
                               AND IA.OPERATION_ID   = A.ATTRIBUTE7
                               AND IA.ELECTRODE_TYPE = A.ATTRIBUTE8
                               AND IA.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND IA.DATA_TYPE_2    = A.ATTRIBUTE11
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Duplication Data. ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ######################################################## */
            /* 중복 값 체크(LINE ASSIGN)									*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Item Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM ( SELECT PROGRAM_ID
                                          , SHEET_NAME
                                          , CREATION_DATE
                                          , ATTRIBUTE1   AS DIVISION_ID
                                          , ATTRIBUTE2   AS COMPANY_ID
                                          , ATTRIBUTE3   AS SITE_ID
                                          , ATTRIBUTE4   AS PLANT_ID
                                          , ATTRIBUTE5   AS FACTORY_ID
                                          , ATTRIBUTE6   AS LINE_ID
                                          , ATTRIBUTE7   AS OPERATION_ID
                                          , ATTRIBUTE8   AS ELECTRODE_TYPE
                                          , ATTRIBUTE10  AS DATA_TYPE_1
                                          , ATTRIBUTE12  AS ITEM_ID
                                       FROM SCM_ADM_EXCEL_UPLOAD
                                      WHERE PROGRAM_ID = V_PROGRAM_ID
                                        AND SHEET_NAME = V_SHEET_NAME
                                        AND CREATED_BY = V_CREATED_BY
                                        AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                        AND UPLOAD_STATUS_CODE = 'UPLOAD'
                                        AND ATTRIBUTE10 = 'LINE ASSIGN'
                                      GROUP BY PROGRAM_ID
                                             , SHEET_NAME
                                             , CREATION_DATE
                                             , ATTRIBUTE1
                                             , ATTRIBUTE2
                                             , ATTRIBUTE3
                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE8
                                             , ATTRIBUTE10
                                             , ATTRIBUTE12
                                     HAVING COUNT(1) > 1 ) IA
                             WHERE 1 = 1
                               AND IA.DIVISION_ID    = A.ATTRIBUTE1
                               AND IA.COMPANY_ID     = A.ATTRIBUTE2
                               AND IA.SITE_ID        = A.ATTRIBUTE3
                               AND IA.PLANT_ID       = A.ATTRIBUTE4
                               AND IA.FACTORY_ID     = A.ATTRIBUTE5
                               AND IA.LINE_ID        = A.ATTRIBUTE6
                               AND IA.OPERATION_ID   = A.ATTRIBUTE7
                               AND IA.ELECTRODE_TYPE = A.ATTRIBUTE8
                               AND IA.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND IA.ITEM_ID        = A.ATTRIBUTE12
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Duplication Item Data. Assign ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ######################################################## */
            /* 중복 값 체크('TACT TIME','DAILY CAPA')					*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Item Data - Capa'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM ( SELECT PROGRAM_ID
                                          , SHEET_NAME
                                          , CREATION_DATE
                                          , ATTRIBUTE1   AS DIVISION_ID
                                          , ATTRIBUTE2   AS COMPANY_ID
                                          , ATTRIBUTE3   AS SITE_ID
                                          , ATTRIBUTE4   AS PLANT_ID
                                          , ATTRIBUTE5   AS FACTORY_ID
                                          , ATTRIBUTE6   AS LINE_ID
                                          , ATTRIBUTE7   AS OPERATION_ID
                                          , ATTRIBUTE8   AS ELECTRODE_TYPE
                                          , ATTRIBUTE10  AS DATA_TYPE_1
                                          , ATTRIBUTE12  AS ITEM_ID
                                       FROM SCM_ADM_EXCEL_UPLOAD
                                      WHERE PROGRAM_ID = V_PROGRAM_ID
                                        AND SHEET_NAME = V_SHEET_NAME
                                        AND CREATED_BY = V_CREATED_BY
                                        AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                        AND UPLOAD_STATUS_CODE = 'UPLOAD'
                                        AND ATTRIBUTE10 IN ('TACT TIME','DAILY CAPA')
                                      GROUP BY PROGRAM_ID
                                             , SHEET_NAME
                                             , CREATION_DATE
                                             , ATTRIBUTE1
                                             , ATTRIBUTE2
                                             , ATTRIBUTE3
                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE8
                                             , ATTRIBUTE10
                                             , ATTRIBUTE12
                                     HAVING COUNT(1) > 1 ) IA
                             WHERE 1 = 1
                               AND IA.DIVISION_ID    = A.ATTRIBUTE1
                               AND IA.COMPANY_ID     = A.ATTRIBUTE2
                               AND IA.SITE_ID        = A.ATTRIBUTE3
                               AND IA.PLANT_ID       = A.ATTRIBUTE4
                               AND IA.FACTORY_ID     = A.ATTRIBUTE5
                               AND IA.LINE_ID        = A.ATTRIBUTE6
                               AND IA.OPERATION_ID   = A.ATTRIBUTE7
                               AND IA.ELECTRODE_TYPE = A.ATTRIBUTE8
                               AND IA.DATA_TYPE_1    = A.ATTRIBUTE10
                               AND IA.ITEM_ID        = A.ATTRIBUTE12
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Duplication Item Data - Capa ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ######################################################## */
            /* 중복 값 체크('YIEDL')										*/
            /* ######################################################## */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Item Data - Yield'
                 , LAST_UPDATED_BY    = V_CREATED_BY
                 , LAST_UPDATE_DATE   = SYSDATE
             WHERE A.PROGRAM_ID         = V_PROGRAM_ID
               AND A.SHEET_NAME         = V_SHEET_NAME
               AND A.CREATED_BY         = V_CREATED_BY
               AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
               AND A.UPLOAD_STATUS_CODE = 'UPLOAD'
               AND EXISTS ( SELECT 1
                              FROM ( SELECT PROGRAM_ID
                                          , SHEET_NAME
                                          , CREATION_DATE
                                          , ATTRIBUTE1   AS DIVISION_ID
                                          , ATTRIBUTE2   AS COMPANY_ID
                                          , ATTRIBUTE3   AS SITE_ID
                                          , ATTRIBUTE4   AS PLANT_ID
                                          , ATTRIBUTE5   AS FACTORY_ID
                                          , ATTRIBUTE6   AS LINE_ID
                                          , ATTRIBUTE7   AS OPERATION_ID
                                          , ATTRIBUTE10  AS DATA_TYPE_1
                                          , ATTRIBUTE12  AS ITEM_ID
                                       FROM SCM_ADM_EXCEL_UPLOAD
                                      WHERE PROGRAM_ID = V_PROGRAM_ID
                                        AND SHEET_NAME = V_SHEET_NAME
                                        AND CREATED_BY = V_CREATED_BY
                                        AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
                                        AND UPLOAD_STATUS_CODE = 'UPLOAD'
                                        AND ATTRIBUTE10 = 'YIELD'
                                      GROUP BY PROGRAM_ID
                                             , SHEET_NAME
                                             , CREATION_DATE
                                             , ATTRIBUTE1
                                             , ATTRIBUTE2
                                             , ATTRIBUTE3
                                             , ATTRIBUTE4
                                             , ATTRIBUTE5
                                             , ATTRIBUTE6
                                             , ATTRIBUTE7
                                             , ATTRIBUTE10
                                             , ATTRIBUTE12
                                     HAVING COUNT(1) > 1 ) IA
                             WHERE 1 = 1
                               AND IA.DIVISION_ID  = A.ATTRIBUTE1
                               AND IA.COMPANY_ID   = A.ATTRIBUTE2
                               AND IA.SITE_ID      = A.ATTRIBUTE3
                               AND IA.PLANT_ID     = A.ATTRIBUTE4
                               AND IA.FACTORY_ID   = A.ATTRIBUTE5
                               AND IA.LINE_ID      = A.ATTRIBUTE6
                               AND IA.OPERATION_ID = A.ATTRIBUTE7
                               AND IA.DATA_TYPE_1  = A.ATTRIBUTE10
                               AND IA.ITEM_ID      = A.ATTRIBUTE12
                          );

            V_ROWCOUNT    := SQL%ROWCOUNT;
            V_LOG_TYPE    := 'UPDATE';
            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## Duplication Item Data - Yield ##########';
            V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

            /* ################################################################ */
            /* CONFIRM 중복 값 체크(LINE ASSIGN,TACT TIME,DAILY CAPA,YIELD) 제외	*/
            /* ################################################################ */
            UPDATE SCM_ADM_EXCEL_UPLOAD A
               SET UPLOAD_STATUS_CODE = 'ERROR'
                 , MESSAGE_TEXT       = 'Duplication Finish Data.'
                 , LAST_UPDATED_BY    = V_CREATED_BY
