                                                , ATTRIBUTE186, ATTRIBUTE187, ATTRIBUTE188, ATTRIBUTE189, ATTRIBUTE190
                                                , ATTRIBUTE191, ATTRIBUTE192, ATTRIBUTE193, ATTRIBUTE194, ATTRIBUTE195
                                                , ATTRIBUTE196, ATTRIBUTE197, ATTRIBUTE198, ATTRIBUTE199, ATTRIBUTE200 ) ) ) XA
                 WHERE 1 = 1
                   AND IA.COLUMN_NAME = XA.COLUMN_NAME
                   AND TRIM(IA.YYYYMMDD) IS NOT NULL
                   AND TRIM(XA.VALUE) IS NOT NULL;

                /*------------------ Start [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 --------------
                 * ESS 가상 라인 동기화 저장 대상 추가
                 * AS-IS 일별 프로시저의 조인 조건은 월별과 달리 VIRTUAL_LINE_YN = 'Y' 가 없다(원문 그대로)
                 *------------------------------------------------------------------------------------------*/
                INSERT INTO GT_SCP0049_UPL_DATA
                            ( DIVISION_ID
                            , COMPANY_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , LINE_ID
                            , OPERATION_ID
                            , ELECTRODE_TYPE
                            , ATTRIBUTE9
                            , DATA_TYPE_1
                            , DATA_TYPE_2
                            , ITEM_ID
                            , LANE_QTY
                            , FINISH
                            , UOM
                            , YYYYMMDD
                            , QTY
                            , CREATED_BY )
                SELECT B.DIVISION_ID
                     , B.COMPANY_ID
                     , B.SITE_ID
                     , B.PLANT_ID
                     , B.FACTORY_ID
                     , B.LINE_ID
                     , B.OPERATION_ID
                     , B.ELECTRODE_TYPE
                     , A.ATTRIBUTE9
                     , A.DATA_TYPE_1
                     , A.DATA_TYPE_2
                     , A.ITEM_ID
                     , A.LANE_QTY
                     , A.FINISH
                     , A.UOM
                     , A.YYYYMMDD
                     , A.QTY
                     , A.CREATED_BY
                  FROM GT_SCP0049_UPL_DATA A   -- 가상 Line validation 처리하여 모두 real line data임
                     , SCM_MST_LINE_SN B
                 WHERE 1 = 1
                   AND B.LINK_LINE_ID   = A.LINE_ID
                   AND B.OPERATION_ID   = A.OPERATION_ID
                   AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                   AND B.ACTIVE_FLAG    = 'Y';
                /*------------------ End [PJ2025F254] [LGES] JV법인 ESS 혼용 생산 시스템 개선 ----------------*/

                /* #################################################### */
                /* 이력 저장				 								*/
                /* #################################################### */
                V_LOG_ERROR := 'CAPA HIST';

                DELETE FROM GT_SCP0049;
                DELETE FROM GT_SCP0049_DELETE;

                INSERT INTO GT_SCP0049
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_UPDATE_ID )
                SELECT DIVISION_ID
                     , COMPANY_ID
                     , SITE_ID
                     , PLANT_ID
                     , FACTORY_ID
                     , LINE_ID
                     , OPERATION_ID
                     , ELECTRODE_TYPE
                     , ITEM_ID
                     , CASE WHEN DATA_TYPE_1 = 'LINE ASSIGN' THEN 'LA'
                            WHEN DATA_TYPE_1 IN ('DAILY CAPA','TACT TIME') THEN 'T'
                            WHEN DATA_TYPE_1 = 'YIELD' THEN 'Y'
                       END        AS DATA_TABLE
                     , 'M'        AS DATA_TYPE  -- MONTH DATA 만 존재 함
                     , YYYYMMDD   AS DAY_NAME
                     , QTY        AS DAY_QTY
                     , CREATED_BY AS UPDATE_ID
                  FROM GT_SCP0049_UPL_DATA
                 WHERE DATA_TYPE_1 IN ( 'LINE ASSIGN','DAILY CAPA','TACT TIME','YIELD')
                   AND LENGTH(RTRIM(YYYYMMDD)) = 8;

                /* 이력 저장 */
                /* AS-IS EXEC [dbo].[PR_SCP_CAPA_HIST_DATASET] @SCP0049_HIST 대응 */
                /* 테이블 파라미터는 전달용 GTT(GT_SCP0049_DS)로 인계한다 */
                DELETE FROM GT_SCP0049_DS;

                INSERT INTO GT_SCP0049_DS
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049;

                P_CAPA_HIST_DATASET;

                V_LOG_ERROR := 'LINE ASSIGN DELETE';

                /* LINE ASSIGN 삭제(TACT TIME,YIELD 삭제 동기화) */
                INSERT INTO GT_SCP0049_DELETE
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049
                 WHERE P_DATA_TABLE = 'LA'
                   AND NVL(TRUNC(TO_NUMBER(P_DAY_QTY)), 0) = 9;

                /* LINE ASSIGN 데이터 삭제 */
                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 = 'LINE ASSIGN'
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID    = A.FACTORY_ID
                                   AND B.P_LINE_ID       = A.LINE_ID
                                   AND B.P_OPERATION_ID  = A.OPERATION_ID
                                   AND B.P_ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND B.P_ITEM_ID       = A.ITEM_ID
                                   AND B.P_DAY_NAME      = A.YYYYMMDD
                              );

                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 IN ('TACT TIME','DAILY CAPA')
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID    = A.FACTORY_ID
                                   AND B.P_LINE_ID       = A.LINE_ID
                                   AND B.P_OPERATION_ID  = A.OPERATION_ID
                                   AND B.P_ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND B.P_ITEM_ID       = A.ITEM_ID
                                   AND B.P_DAY_NAME      = A.YYYYMMDD
                              );

                DELETE FROM GT_SCP0049_UPL_DATA A
                 WHERE A.DATA_TYPE_1 = 'YIELD'
                   AND EXISTS ( SELECT 1
                                  FROM GT_SCP0049_DELETE B
                                 WHERE B.P_FACTORY_ID   = A.FACTORY_ID
                                   AND B.P_LINE_ID      = A.LINE_ID
                                   AND B.P_OPERATION_ID = A.OPERATION_ID
                                   AND B.P_ITEM_ID      = A.ITEM_ID
                                   AND B.P_DAY_NAME     = A.YYYYMMDD
                              );

                /* AS-IS EXEC [dbo].[PR_SCP_CAPA_LINE_ASSIGN_DELETE_DATASET] @SCP0049_DELETE 대응 */
                DELETE FROM GT_SCP0049_DS;

                INSERT INTO GT_SCP0049_DS
                            ( P_DIVISION_ID
                            , P_COMPANY_ID
                            , P_SITE_ID
                            , P_PLANT_ID
                            , P_FACTORY_ID
                            , P_LINE_ID
                            , P_OPERATION_ID
                            , P_ELECTRODE_TYPE
                            , P_ITEM_ID
                            , P_LOSS_CODE
                            , P_DATA_TABLE
                            , P_DATA_TYPE
                            , P_DAY_NAME
                            , P_DAY_QTY
                            , P_LANE_QTY
                            , P_CONFIRM_FLAG
                            , P_UPDATE_ID )
                SELECT P_DIVISION_ID
                     , P_COMPANY_ID
                     , P_SITE_ID
                     , P_PLANT_ID
                     , P_FACTORY_ID
                     , P_LINE_ID
                     , P_OPERATION_ID
                     , P_ELECTRODE_TYPE
                     , P_ITEM_ID
                     , P_LOSS_CODE
                     , P_DATA_TABLE
                     , P_DATA_TYPE
                     , P_DAY_NAME
                     , P_DAY_QTY
                     , P_LANE_QTY
                     , P_CONFIRM_FLAG
                     , P_UPDATE_ID
                  FROM GT_SCP0049_DELETE;

                P_CAPA_LINE_ASSIGN_DELETE_DATASET;

                -- #################################################### --
                -- SCM_WORK_CALENDAR_M_SN		 						--
                -- 월별 입력	(PM 은 일별 입력한다)					--
                -- QTY 는 0 보다 크거나 같은(>=) 값 입력				--
                -- #################################################### --
                V_LOG_ERROR := 'LOSS DAY';

                UPDATE SCM_WORK_CALENDAR_M_SN A
                   SET (TIME_TERM, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_NUMBER(B.QTY)
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = TO_CHAR(A.WORK_DATE, 'YYYYMMDD')
                                AND ( SELECT SEGMENT1
                                        FROM SCM_SYS_LOOKUP_VALUE_SN C
                                       WHERE 1 = 1
                                         AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                         AND C.ACTIVE_FLAG      = 'Y'
                                         AND C.ATTRIBUTE1       = B.DATA_TYPE_1
                                         AND C.ATTRIBUTE2       = B.DATA_TYPE_2 ) = A.LOSS_CODE
                                AND ( B.DATA_TYPE_1 = 'No-Load'
                                   OR B.DATA_TYPE_1 = 'Not-Available'
                                   OR ( B.DATA_TYPE_1 = 'No-Run' AND B.DATA_TYPE_2 = 'PM' ) )
                                   --AND DATA_TYPE_1 IN ( 'No-Run', 'Performance(%)','Quality(%)')
                                   --AND DATA_TYPE_2 <> 'PM'    -- PM 은 일별 입력한다.
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 8    -- day
                                AND B.YYYYMMDD >= V_STD_YYYYMMDD
                                AND TO_NUMBER(B.QTY) >= 0.0 )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA D
                                 WHERE D.COMPANY_ID     = A.COMPANY_ID
                                   AND D.DIVISION_ID    = A.DIVISION_ID
                                   AND D.SITE_ID        = A.SITE_ID
                                   AND D.PLANT_ID       = A.PLANT_ID
                                   AND D.FACTORY_ID     = A.FACTORY_ID
                                   AND D.OPERATION_ID   = A.OPERATION_ID
                                   AND D.LINE_ID        = A.LINE_ID
                                   AND D.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND D.YYYYMMDD       = TO_CHAR(A.WORK_DATE, 'YYYYMMDD')
                                   AND ( SELECT SEGMENT1
                                           FROM SCM_SYS_LOOKUP_VALUE_SN E
                                          WHERE 1 = 1
                                            AND E.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                            AND E.ACTIVE_FLAG      = 'Y'
                                            AND E.ATTRIBUTE1       = D.DATA_TYPE_1
                                            AND E.ATTRIBUTE2       = D.DATA_TYPE_2 ) = A.LOSS_CODE
                                   AND ( D.DATA_TYPE_1 = 'No-Load'
                                      OR D.DATA_TYPE_1 = 'Not-Available'
                                      OR ( D.DATA_TYPE_1 = 'No-Run' AND D.DATA_TYPE_2 = 'PM' ) )
                                   AND LENGTH(RTRIM(D.YYYYMMDD)) = 8
                                   AND D.YYYYMMDD >= V_STD_YYYYMMDD
                                   AND TO_NUMBER(D.QTY) >= 0.0
                              );

                INSERT INTO SCM_WORK_CALENDAR_M_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , WORK_DATE
                            , LOSS_CODE
                            , TIME_TERM
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , IA.LOSS_CODE
                     , IA.QTY
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT A.DIVISION_ID
                              , A.COMPANY_ID
                              , A.SITE_ID
                              , A.PLANT_ID
                              , A.FACTORY_ID
                              , A.LINE_ID
                              , A.OPERATION_ID
                              , A.ELECTRODE_TYPE
                              , A.YYYYMMDD
                              , A.CREATED_BY
                              , TO_NUMBER(A.QTY) AS QTY
                              , ( SELECT SEGMENT1
                                    FROM SCM_SYS_LOOKUP_VALUE_SN B
                                   WHERE 1 = 1
                                     AND B.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                     AND B.ACTIVE_FLAG      = 'Y'
                                     AND B.ATTRIBUTE1       = A.DATA_TYPE_1
                                     AND B.ATTRIBUTE2       = A.DATA_TYPE_2 ) AS LOSS_CODE
                           FROM GT_SCP0049_UPL_DATA A
                          WHERE 1 = 1
                            AND ( A.DATA_TYPE_1 = 'No-Load'
                               OR A.DATA_TYPE_1 = 'Not-Available'
                               OR ( A.DATA_TYPE_1 = 'No-Run' AND A.DATA_TYPE_2 = 'PM' ) )
                            AND LENGTH(RTRIM(A.YYYYMMDD)) = 8    -- day
                            AND A.YYYYMMDD >= V_STD_YYYYMMDD
                            AND TO_NUMBER(A.QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_WORK_CALENDAR_M_SN C
                                     WHERE C.COMPANY_ID     = IA.COMPANY_ID
                                       AND C.DIVISION_ID    = IA.DIVISION_ID
                                       AND C.SITE_ID        = IA.SITE_ID
                                       AND C.PLANT_ID       = IA.PLANT_ID
                                       AND C.FACTORY_ID     = IA.FACTORY_ID
                                       AND C.OPERATION_ID   = IA.OPERATION_ID
                                       AND C.LINE_ID        = IA.LINE_ID
                                       AND C.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND TO_CHAR(C.WORK_DATE, 'YYYYMMDD') = IA.YYYYMMDD
                                       AND C.LOSS_CODE      = IA.LOSS_CODE
                                  );

                -- #################################################### --
                -- SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN					--
                -- LANE QTY 정보 UPDATE									--
                -- #################################################### --
                V_LOG_ERROR := 'LANE QTY DAY UPDATE';

                UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
                   SET (LANE_QTY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT NVL(CASE WHEN TRIM(B.LANE_QTY) IS NULL THEN 0.0 ELSE TO_NUMBER(B.LANE_QTY) END, 0)
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.ITEM_ID        = A.ITEM_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                AND B.DATA_TYPE_1    = 'LINE ASSIGN'
                                AND EXISTS ( SELECT 1
                                               FROM (SELECT C.COMPANY_ID, C.DIVISION_ID, C.SITE_ID, C.PLANT_ID, C.FACTORY_ID
                                                          , C.ITEM_ID, D.LINE_ID, D.ELECTRODE_TYPE, D.OPERATION_ID, C.PROD_VERSION_TYPE, C.LANE_QTY
                                                       FROM SCM_ITEM_LANE_M_SN C
                                                          , SCM_LINE_M_SN D
                                                      WHERE C.ACTIVE_FLAG       = 'Y'
                                                        AND D.ACTIVE_FLAG       = 'Y'
                                                        AND C.COMPANY_ID        = D.COMPANY_ID
                                                        AND C.DIVISION_ID       = D.DIVISION_ID
                                                        AND C.SITE_ID           = D.SITE_ID
                                                        AND C.PLANT_ID          = D.PLANT_ID
                                                        AND C.FACTORY_ID        = D.FACTORY_ID
                                                        AND C.PROD_VERSION_TYPE = D.PROD_VERSION_TYPE
                                                        AND D.OPERATION_ID      = 'E2000') SA
                                              WHERE SA.DIVISION_ID     = B.DIVISION_ID
                                                AND SA.COMPANY_ID      = B.COMPANY_ID
                                                AND SA.SITE_ID         = B.SITE_ID
                                                AND SA.LINE_ID         = B.LINE_ID
                                                AND SA.OPERATION_ID    = B.OPERATION_ID
                                                AND SA.ELECTRODE_TYPE  = B.ELECTRODE_TYPE
                                                AND SA.ITEM_ID         = B.ITEM_ID
                                                AND TRUNC(SA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(B.LANE_QTY), '0'))), 0)
                                           ) )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA E
                                 WHERE E.COMPANY_ID     = A.COMPANY_ID
                                   AND E.DIVISION_ID    = A.DIVISION_ID
                                   AND E.SITE_ID        = A.SITE_ID
                                   AND E.PLANT_ID       = A.PLANT_ID
                                   AND E.FACTORY_ID     = A.FACTORY_ID
                                   AND E.ITEM_ID        = A.ITEM_ID
                                   AND E.OPERATION_ID   = A.OPERATION_ID
                                   AND E.LINE_ID        = A.LINE_ID
                                   AND E.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND E.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                   AND E.DATA_TYPE_1    = 'LINE ASSIGN'
                                   AND EXISTS ( SELECT 1
                                                  FROM (SELECT F.COMPANY_ID, F.DIVISION_ID, F.SITE_ID, F.PLANT_ID, F.FACTORY_ID
                                                             , F.ITEM_ID, G.LINE_ID, G.ELECTRODE_TYPE, G.OPERATION_ID, F.PROD_VERSION_TYPE, F.LANE_QTY
                                                          FROM SCM_ITEM_LANE_M_SN F
                                                             , SCM_LINE_M_SN G
                                                         WHERE F.ACTIVE_FLAG       = 'Y'
                                                           AND G.ACTIVE_FLAG       = 'Y'
                                                           AND F.COMPANY_ID        = G.COMPANY_ID
                                                           AND F.DIVISION_ID       = G.DIVISION_ID
                                                           AND F.SITE_ID           = G.SITE_ID
                                                           AND F.PLANT_ID          = G.PLANT_ID
                                                           AND F.FACTORY_ID        = G.FACTORY_ID
                                                           AND F.PROD_VERSION_TYPE = G.PROD_VERSION_TYPE
                                                           AND G.OPERATION_ID      = 'E2000') XA
                                                 WHERE XA.DIVISION_ID     = E.DIVISION_ID
                                                   AND XA.COMPANY_ID      = E.COMPANY_ID
                                                   AND XA.SITE_ID         = E.SITE_ID
                                                   AND XA.LINE_ID         = E.LINE_ID
                                                   AND XA.OPERATION_ID    = E.OPERATION_ID
                                                   AND XA.ELECTRODE_TYPE  = E.ELECTRODE_TYPE
                                                   AND XA.ITEM_ID         = E.ITEM_ID
                                                   AND TRUNC(XA.LANE_QTY) = NVL(TRUNC(TO_NUMBER(NVL(TRIM(E.LANE_QTY), '0'))), 0)
                                              )
                              );

                -- #################################################### --
                -- SCM_ITEM_LINE_ASSIGN_EXCEPT_M  				  	    --
                -- 기준 일(현재일) 보다 크거나 같은(>=) 값 입력			--
                -- QTY 는 0 보다 크거나 같은(>=) 값 입력				--
                -- LINE ASSIGN 은 LANE QTY 때문에 OPERATION 분리하여 수정한다.--
                -- #################################################### --
                V_LOG_ERROR := 'LINE ASSIGN DAY';

                /* LANE QTY 가 존재하는 공정(E2000, E3000, E4000)								*/
                /* 기준 날짜 비교는 AS-IS 가 8자리 일자를 6자리 기준월과 대조하므로 원문 그대로 둔다	*/
                UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
                   SET (PRIORITY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_CHAR(TRUNC(TO_NUMBER(B.QTY)))
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.ITEM_ID        = A.ITEM_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                AND B.DATA_TYPE_1    = 'LINE ASSIGN'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 8           -- day
                                AND B.YYYYMMDD >= V_STD_YYYYMM              -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) > 0.0
                                AND B.OPERATION_ID = 'E2000' )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID     = A.COMPANY_ID
                                   AND C.DIVISION_ID    = A.DIVISION_ID
                                   AND C.SITE_ID        = A.SITE_ID
                                   AND C.PLANT_ID       = A.PLANT_ID
                                   AND C.FACTORY_ID     = A.FACTORY_ID
                                   AND C.ITEM_ID        = A.ITEM_ID
                                   AND C.OPERATION_ID   = A.OPERATION_ID
                                   AND C.LINE_ID        = A.LINE_ID
                                   AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND C.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                   AND C.DATA_TYPE_1    = 'LINE ASSIGN'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 8
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) > 0.0
                                   AND C.OPERATION_ID = 'E2000'
                              );

                INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , START_TIME
                            , END_TIME
                            , LANE_QTY
                            , PRIORITY
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , IA.LANE_QTY
                     , TO_CHAR(IA.QTY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , NVL(CASE WHEN TRIM(LANE_QTY) IS NULL THEN 0.0 ELSE TO_NUMBER(LANE_QTY) END, 0) AS LANE_QTY
                              , TRUNC(TO_NUMBER(QTY))  AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'LINE ASSIGN'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 8         -- day
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) > 0.0
                            AND OPERATION_ID = 'E2000' ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN B
                                     WHERE B.COMPANY_ID     = IA.COMPANY_ID
                                       AND B.DIVISION_ID    = IA.DIVISION_ID
                                       AND B.SITE_ID        = IA.SITE_ID
                                       AND B.PLANT_ID       = IA.PLANT_ID
                                       AND B.FACTORY_ID     = IA.FACTORY_ID
                                       AND B.ITEM_ID        = IA.ITEM_ID
                                       AND B.OPERATION_ID   = IA.OPERATION_ID
                                       AND B.LINE_ID        = IA.LINE_ID
                                       AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND TO_CHAR(B.START_TIME, 'YYYYMMDD') = IA.YYYYMMDD
                                  );

                V_LOG_ERROR := 'LINE ASSIGN DAY LQ';

                /* LANE QTY 가 존재하지않는 공정 */
                UPDATE SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN A
                   SET (PRIORITY, LANE_QTY, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_CHAR(TRUNC(TO_NUMBER(B.QTY)))
                                  , 0
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID     = A.COMPANY_ID
                                AND B.DIVISION_ID    = A.DIVISION_ID
                                AND B.SITE_ID        = A.SITE_ID
                                AND B.PLANT_ID       = A.PLANT_ID
                                AND B.FACTORY_ID     = A.FACTORY_ID
                                AND B.ITEM_ID        = A.ITEM_ID
                                AND B.OPERATION_ID   = A.OPERATION_ID
                                AND B.LINE_ID        = A.LINE_ID
                                AND B.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND B.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                AND B.DATA_TYPE_1    = 'LINE ASSIGN'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 8           -- day
                                AND B.YYYYMMDD >= V_STD_YYYYMM              -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) > 0.0
                                AND B.OPERATION_ID NOT IN ('E2000') )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID     = A.COMPANY_ID
                                   AND C.DIVISION_ID    = A.DIVISION_ID
                                   AND C.SITE_ID        = A.SITE_ID
                                   AND C.PLANT_ID       = A.PLANT_ID
                                   AND C.FACTORY_ID     = A.FACTORY_ID
                                   AND C.ITEM_ID        = A.ITEM_ID
                                   AND C.OPERATION_ID   = A.OPERATION_ID
                                   AND C.LINE_ID        = A.LINE_ID
                                   AND C.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND C.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                   AND C.DATA_TYPE_1    = 'LINE ASSIGN'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 8
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) > 0.0
                                   AND C.OPERATION_ID NOT IN ('E2000')
                              );

                INSERT INTO SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , START_TIME
                            , END_TIME
                            , LANE_QTY
                            , PRIORITY
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , IA.LANE_QTY
                     , TO_CHAR(IA.QTY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , 0                      AS LANE_QTY
                              , TRUNC(TO_NUMBER(QTY))  AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'LINE ASSIGN'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 8         -- day
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) > 0.0
                            AND OPERATION_ID NOT IN ('E2000') ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_ITEM_LINE_ASSIGN_EXCEPT_SN B
                                     WHERE B.COMPANY_ID     = IA.COMPANY_ID
                                       AND B.DIVISION_ID    = IA.DIVISION_ID
                                       AND B.SITE_ID        = IA.SITE_ID
                                       AND B.PLANT_ID       = IA.PLANT_ID
                                       AND B.FACTORY_ID     = IA.FACTORY_ID
                                       AND B.ITEM_ID        = IA.ITEM_ID
                                       AND B.OPERATION_ID   = IA.OPERATION_ID
                                       AND B.LINE_ID        = IA.LINE_ID
                                       AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND TO_CHAR(B.START_TIME, 'YYYYMMDD') = IA.YYYYMMDD
                                  );

                -- #################################################### --
                -- SCM_TACT_TIME_EXCEPT_M								--
                -- 기준 일 보다 크거나 같은(>=) 값 입력					--
                -- QTY 는 0 보다 크거나 같은(>=) 값 입력				--
                -- #################################################### --
                V_LOG_ERROR := 'TACT TIME DAY';

                INSERT INTO GT_SCP0049_UPL_LU_TACT_DAY
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , WORK_MONTH
                            , WORK_DATE
                            , LOSS_UTIL )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , IA.WORK_MONTH
                     , IA.WORK_DATE
                      --, ROUND(EXP(SUM(ROUND(LOG(1-ISNULL(L.LOSS_RATE,0)),4))),4) AS LOSS_UTIL
                     , TO_CHAR(1 - ROUND(SUM(NVL(B.LOSS_RATE, 0)), 4))  AS UTIL -- No Run 로스 차감
                  FROM ( SELECT DISTINCT
                                COMPANY_ID
                              , DIVISION_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , OPERATION_ID
                              , LINE_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD                AS WORK_DATE
                              , SUBSTR(YYYYMMDD, 1, 6)  AS WORK_MONTH -- YYYYMM
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                            AND LENGTH(RTRIM(YYYYMMDD)) = 8         -- day
                            AND YYYYMMDD >= V_STD_YYYYMM            -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) >= 0.0 ) IA
                     , SCM_LOSS_M_SN B                              -- LOSS UTIL 값 조회
                     , (SELECT SEGMENT1   AS LOSS_CODE
                             , ATTRIBUTE1 AS LV1
                             , ATTRIBUTE2 AS LV2
                          FROM SCM_SYS_LOOKUP_VALUE_SN
                         WHERE LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                           AND ATTRIBUTE5       = 'Y'
                       ) XA
                 WHERE B.COMPANY_ID     = IA.COMPANY_ID
                   AND B.DIVISION_ID    = IA.DIVISION_ID
                   AND B.SITE_ID        = IA.SITE_ID
                   AND B.PLANT_ID       = IA.PLANT_ID
                   AND B.FACTORY_ID     = IA.FACTORY_ID
                   AND B.OPERATION_ID   = IA.OPERATION_ID
                   AND B.LINE_ID        = IA.LINE_ID
                   AND B.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                   AND B.WORK_MONTH     = IA.WORK_MONTH
                   AND B.LOSS_CODE      = XA.LOSS_CODE
                 GROUP BY IA.COMPANY_ID
                        , IA.DIVISION_ID
                        , IA.SITE_ID
                        , IA.PLANT_ID
                        , IA.FACTORY_ID
                        , IA.OPERATION_ID
                        , IA.LINE_ID
                        , IA.ELECTRODE_TYPE
                        , IA.WORK_MONTH
                        , IA.WORK_DATE;

                UPDATE SCM_MST_TACT_TIME_EXCEPT_SN A
                   SET (TACT_TIME, DAILY_CAPA, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT IA.QTY_TACT
                                  , TRUNC(IA.QTY_DAILY)
                                  , IA.CREATED_BY
                                  , SYSDATE
                               FROM ( SELECT B.DIVISION_ID
                                           , B.COMPANY_ID
                                           , B.SITE_ID
                                           , B.PLANT_ID
                                           , B.FACTORY_ID
                                           , B.LINE_ID
                                           , B.OPERATION_ID
                                           , B.ELECTRODE_TYPE
                                           , B.YYYYMMDD
                                           , B.CREATED_BY
                                             --, CONVERT(NUMERIC(20,10),T.QTY )	QTY
                                           , CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                                  WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1)
                                                  ELSE TO_NUMBER(B.QTY) END AS QTY_TACT
                                           , CASE WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                                  WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) > 0 THEN ROUND(86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1), 0)
                                                  ELSE TO_NUMBER(B.QTY) END AS QTY_DAILY
                                           , B.ITEM_ID
                                           , B.DATA_TYPE_1
                                        FROM GT_SCP0049_UPL_DATA B
                                           , GT_SCP0049_UPL_LU_TACT_DAY C
                                       WHERE B.COMPANY_ID     = C.COMPANY_ID(+)
                                         AND B.DIVISION_ID    = C.DIVISION_ID(+)
                                         AND B.SITE_ID        = C.SITE_ID(+)
                                         AND B.PLANT_ID       = C.PLANT_ID(+)
                                         AND B.FACTORY_ID     = C.FACTORY_ID(+)
                                         AND B.OPERATION_ID   = C.OPERATION_ID(+)
                                         AND B.LINE_ID        = C.LINE_ID(+)
                                         AND B.ELECTRODE_TYPE = C.ELECTRODE_TYPE(+)
                                         AND B.YYYYMMDD       = C.WORK_DATE(+)
                                         AND B.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                                         AND LENGTH(RTRIM(B.YYYYMMDD)) = 8    -- day
                                         AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                                         AND TO_NUMBER(B.QTY) >= 0.0 ) IA
                              WHERE IA.COMPANY_ID     = A.COMPANY_ID
                                AND IA.DIVISION_ID    = A.DIVISION_ID
                                AND IA.SITE_ID        = A.SITE_ID
                                AND IA.PLANT_ID       = A.PLANT_ID
                                AND IA.FACTORY_ID     = A.FACTORY_ID
                                AND IA.ITEM_ID        = A.ITEM_ID
                                AND IA.OPERATION_ID   = A.OPERATION_ID
                                AND IA.LINE_ID        = A.LINE_ID
                                AND IA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND IA.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD') )
                 WHERE EXISTS ( SELECT 1
                                  FROM ( SELECT D.DIVISION_ID
                                              , D.COMPANY_ID
                                              , D.SITE_ID
                                              , D.PLANT_ID
                                              , D.FACTORY_ID
                                              , D.LINE_ID
                                              , D.OPERATION_ID
                                              , D.ELECTRODE_TYPE
                                              , D.YYYYMMDD
                                              , D.ITEM_ID
                                           FROM GT_SCP0049_UPL_DATA D
                                              , GT_SCP0049_UPL_LU_TACT_DAY E
                                          WHERE D.COMPANY_ID     = E.COMPANY_ID(+)
                                            AND D.DIVISION_ID    = E.DIVISION_ID(+)
                                            AND D.SITE_ID        = E.SITE_ID(+)
                                            AND D.PLANT_ID       = E.PLANT_ID(+)
                                            AND D.FACTORY_ID     = E.FACTORY_ID(+)
                                            AND D.OPERATION_ID   = E.OPERATION_ID(+)
                                            AND D.LINE_ID        = E.LINE_ID(+)
                                            AND D.ELECTRODE_TYPE = E.ELECTRODE_TYPE(+)
                                            AND D.YYYYMMDD       = E.WORK_DATE(+)
                                            AND D.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                                            AND LENGTH(RTRIM(D.YYYYMMDD)) = 8
                                            AND D.YYYYMMDD >= V_STD_YYYYMM
                                            AND TO_NUMBER(D.QTY) >= 0.0 ) XA
                                 WHERE XA.COMPANY_ID     = A.COMPANY_ID
                                   AND XA.DIVISION_ID    = A.DIVISION_ID
                                   AND XA.SITE_ID        = A.SITE_ID
                                   AND XA.PLANT_ID       = A.PLANT_ID
                                   AND XA.FACTORY_ID     = A.FACTORY_ID
                                   AND XA.ITEM_ID        = A.ITEM_ID
                                   AND XA.OPERATION_ID   = A.OPERATION_ID
                                   AND XA.LINE_ID        = A.LINE_ID
                                   AND XA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND XA.YYYYMMDD       = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                              );

                INSERT INTO SCM_MST_TACT_TIME_EXCEPT_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , ELECTRODE_TYPE
                            , START_TIME
                            , END_TIME
                            , TACT_TIME
                            , DAILY_CAPA
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , IA.ELECTRODE_TYPE
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , IA.QTY_TACT
                     , TRUNC(IA.QTY_DAILY)
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT B.DIVISION_ID
                              , B.COMPANY_ID
                              , B.SITE_ID
                              , B.PLANT_ID
                              , B.FACTORY_ID
                              , B.LINE_ID
                              , B.OPERATION_ID
                              , B.ELECTRODE_TYPE
                              , B.YYYYMMDD
                              , B.CREATED_BY
                              , CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                     WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1)
                                     ELSE TO_NUMBER(B.QTY) END AS QTY_TACT
                              , CASE WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) = 0 THEN 0
                                     WHEN B.DATA_TYPE_1 = 'TACT TIME' AND NVL(TO_NUMBER(B.QTY), 0) > 0 THEN ROUND(86400 / TO_NUMBER(B.QTY) * NVL(TO_NUMBER(C.LOSS_UTIL), 1), 0)
                                     ELSE TO_NUMBER(B.QTY) END AS QTY_DAILY
                              , B.ITEM_ID
                              , B.DATA_TYPE_1
                           FROM GT_SCP0049_UPL_DATA B
                              , GT_SCP0049_UPL_LU_TACT_DAY C
                          WHERE B.COMPANY_ID     = C.COMPANY_ID(+)
                            AND B.DIVISION_ID    = C.DIVISION_ID(+)
                            AND B.SITE_ID        = C.SITE_ID(+)
                            AND B.PLANT_ID       = C.PLANT_ID(+)
                            AND B.FACTORY_ID     = C.FACTORY_ID(+)
                            AND B.OPERATION_ID   = C.OPERATION_ID(+)
                            AND B.LINE_ID        = C.LINE_ID(+)
                            AND B.ELECTRODE_TYPE = C.ELECTRODE_TYPE(+)
                            AND B.YYYYMMDD       = C.WORK_DATE(+)
                            AND B.DATA_TYPE_1 IN ( 'DAILY CAPA', 'TACT TIME')
                            AND LENGTH(RTRIM(B.YYYYMMDD)) = 8    -- day
                            AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                            AND TO_NUMBER(B.QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_TACT_TIME_EXCEPT_SN D
                                     WHERE D.COMPANY_ID     = IA.COMPANY_ID
                                       AND D.DIVISION_ID    = IA.DIVISION_ID
                                       AND D.SITE_ID        = IA.SITE_ID
                                       AND D.PLANT_ID       = IA.PLANT_ID
                                       AND D.FACTORY_ID     = IA.FACTORY_ID
                                       AND D.ITEM_ID        = IA.ITEM_ID
                                       AND D.OPERATION_ID   = IA.OPERATION_ID
                                       AND D.LINE_ID        = IA.LINE_ID
                                       AND D.ELECTRODE_TYPE = IA.ELECTRODE_TYPE
                                       AND TO_CHAR(D.START_TIME, 'YYYYMMDD') = IA.YYYYMMDD
                                  );

                -- #################################################### --
                -- SCM_YIELD_EXCEPT_M
                -- 기준 일(현재 일) 보다 크거나 같은(>=) 값 입력
                -- QTY 는 0 보다 크거나 같은(>=) 값 입력
                -- #################################################### --
                V_LOG_ERROR := 'YIELD DAY';

                UPDATE SCM_MST_YIELD_EXCEPT_SN A
                   SET (YIELD, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT TO_NUMBER(B.QTY) / 100
                                  , B.CREATED_BY
                                  , SYSDATE
                               FROM GT_SCP0049_UPL_DATA B
                              WHERE B.COMPANY_ID   = A.COMPANY_ID
                                AND B.DIVISION_ID  = A.DIVISION_ID
                                AND B.SITE_ID      = A.SITE_ID
                                AND B.PLANT_ID     = A.PLANT_ID
                                AND B.FACTORY_ID   = A.FACTORY_ID
                                AND B.ITEM_ID      = A.ITEM_ID
                                AND B.OPERATION_ID = A.OPERATION_ID
                                AND B.LINE_ID      = A.LINE_ID
                                AND B.YYYYMMDD     = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                AND B.DATA_TYPE_1  = 'YIELD'
                                AND LENGTH(RTRIM(B.YYYYMMDD)) = 8    -- day
                                AND B.YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                                AND TO_NUMBER(B.QTY) >= 0.0 )
                 WHERE EXISTS ( SELECT 1
                                  FROM GT_SCP0049_UPL_DATA C
                                 WHERE C.COMPANY_ID   = A.COMPANY_ID
                                   AND C.DIVISION_ID  = A.DIVISION_ID
                                   AND C.SITE_ID      = A.SITE_ID
                                   AND C.PLANT_ID     = A.PLANT_ID
                                   AND C.FACTORY_ID   = A.FACTORY_ID
                                   AND C.ITEM_ID      = A.ITEM_ID
                                   AND C.OPERATION_ID = A.OPERATION_ID
                                   AND C.LINE_ID      = A.LINE_ID
                                   AND C.YYYYMMDD     = TO_CHAR(A.START_TIME, 'YYYYMMDD')
                                   AND C.DATA_TYPE_1  = 'YIELD'
                                   AND LENGTH(RTRIM(C.YYYYMMDD)) = 8
                                   AND C.YYYYMMDD >= V_STD_YYYYMM
                                   AND TO_NUMBER(C.QTY) >= 0.0
                              );

                INSERT INTO SCM_MST_YIELD_EXCEPT_SN
                            ( COMPANY_ID
                            , DIVISION_ID
                            , SITE_ID
                            , PLANT_ID
                            , FACTORY_ID
                            , ITEM_ID
                            , OPERATION_ID
                            , LINE_ID
                            , START_TIME
                            , END_TIME
                            , YIELD
                            , INSERT_ID
                            , INSERT_TIME
                            , UPDATE_ID
                            , UPDATE_TIME )
                SELECT IA.COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.SITE_ID
                     , IA.PLANT_ID
                     , IA.FACTORY_ID
                     , IA.ITEM_ID
                     , IA.OPERATION_ID
                     , IA.LINE_ID
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , TO_DATE(IA.YYYYMMDD, 'YYYYMMDD')
                     , IA.QTY / 100
                     , IA.CREATED_BY
                     , SYSDATE
                     , IA.CREATED_BY
                     , SYSDATE
                  FROM ( SELECT DIVISION_ID
                              , COMPANY_ID
                              , SITE_ID
                              , PLANT_ID
                              , FACTORY_ID
                              , LINE_ID
                              , OPERATION_ID
                              , ELECTRODE_TYPE
                              , YYYYMMDD
                              , CREATED_BY
                              , TO_NUMBER(QTY) AS QTY
                              , ITEM_ID
                           FROM GT_SCP0049_UPL_DATA
                          WHERE 1 = 1
                            AND DATA_TYPE_1 = 'YIELD'
                            AND LENGTH(RTRIM(YYYYMMDD)) = 8    -- day
                            AND YYYYMMDD >= V_STD_YYYYMM       -- 수정 가능 기준 날짜
                            AND TO_NUMBER(QTY) >= 0.0 ) IA
                 WHERE NOT EXISTS ( SELECT 1
                                      FROM SCM_MST_YIELD_EXCEPT_SN B
                                     WHERE B.COMPANY_ID   = IA.COMPANY_ID
                                       AND B.DIVISION_ID  = IA.DIVISION_ID
                                       AND B.SITE_ID      = IA.SITE_ID
                                       AND B.PLANT_ID     = IA.PLANT_ID
                                       AND B.FACTORY_ID   = IA.FACTORY_ID
                                       AND B.ITEM_ID      = IA.ITEM_ID
                                       AND B.OPERATION_ID = IA.OPERATION_ID
                                       AND B.LINE_ID      = IA.LINE_ID
                                       AND TO_CHAR(B.START_TIME, 'YYYYMMDD') = IA.YYYYMMDD
                                  );

                /*------------------------------------------------------------------------------------------
                 * AS-IS 원문 주석 (블록 주석으로 막혀 있는 구간이라 변환 대상에서 제외)
                 * ------------------- loss 관련 처리 : 월단위는 tact 계산에 쓰이는 loss 가 변경되기 때문에
                 * 그 변경된 loss 기준으로 tact/capa 를 재계산해주는데, 일단위는 변경된 loss 가 tact/capa 에
                 * 영향을 주지 않으므로 재계산하지 않도록 막음.. leejsthira2 -----------------------------
                 *   (막혀 있는 구간 : No-Run 월 LOSS UTIL 산출 → 이력 저장 → SCM_MST_TACT_TIME_SN ·
                 *    SCM_MST_TACT_TIME_EXCEPT_SN 재계산. 월별 프로시저 P_CAPA_EXCEL_UPLOAD_DAY 에 같은 구간이 있음)
                 *------------------------------------------------------------------------------------------*/

                /* #################################################### */
                /* SCM_MASTER_MANAGER_M_SN	CONFIRM 저장					*/
                /* #################################################### */
                V_LOG_ERROR := 'CONFIRM';

                UPDATE SCM_MASTER_MANAGER_M_SN A
                   SET (CONFIRM_FLAG, CONFIRM_ID, CONFIRM_TIME, UPDATE_ID, UPDATE_TIME)
                         = ( SELECT IA.FINISH
                                  , IA.CREATED_BY
                                  , SYSDATE
                                  , IA.CREATED_BY
                                  , SYSDATE
                               FROM ( SELECT DISTINCT
                                             B.DIVISION_ID
                                           , B.COMPANY_ID
                                           , B.SITE_ID
                                           , B.PLANT_ID
                                           , B.FACTORY_ID
                                           , B.LINE_ID
                                           , B.OPERATION_ID
                                           , B.ELECTRODE_TYPE
                                           , B.CREATED_BY
                                           , B.FINISH
                                           , B.DATA_TYPE_1
                                           , ( SELECT SEGMENT1
                                                 FROM SCM_SYS_LOOKUP_VALUE_SN C
                                                WHERE 1 = 1
                                                  AND C.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                  AND C.ACTIVE_FLAG      = 'Y'
                                                  AND C.ATTRIBUTE1       = ( CASE WHEN B.DATA_TYPE_1 = 'DAILY CAPA' THEN 'TACT TIME' ELSE B.DATA_TYPE_1 END )
                                                  --AND LV.ATTRIBUTE2 = T.DATA_TYPE2
                                             ) AS LOSS_CODE
                                        FROM GT_SCP0049_UPL_DATA B
                                       WHERE 1 = 1
                                         AND B.DATA_TYPE_1 IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD')
                                      UNION ALL
                                      SELECT DISTINCT
                                             D.DIVISION_ID
                                           , D.COMPANY_ID
                                           , D.SITE_ID
                                           , D.PLANT_ID
                                           , D.FACTORY_ID
                                           , D.LINE_ID
                                           , D.OPERATION_ID
                                           , D.ELECTRODE_TYPE
                                           , D.CREATED_BY
                                           , D.FINISH
                                           , D.DATA_TYPE_1
                                           , ( SELECT SEGMENT1
                                                 FROM SCM_SYS_LOOKUP_VALUE_SN E
                                                WHERE 1 = 1
                                                  AND E.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                  AND E.ACTIVE_FLAG      = 'Y'
                                                  AND E.ATTRIBUTE1       = D.DATA_TYPE_1
                                                  AND E.ATTRIBUTE2       = D.DATA_TYPE_2
                                             ) AS LOSS_CODE
                                        FROM GT_SCP0049_UPL_DATA D
                                       WHERE 1 = 1
                                         AND D.DATA_TYPE_1 NOT IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD') ) IA
                              WHERE IA.COMPANY_ID     = A.COMPANY_ID
                                AND IA.DIVISION_ID    = A.DIVISION_ID
                                AND IA.SITE_ID        = A.SITE_ID
                                AND IA.PLANT_ID       = A.PLANT_ID
                                AND IA.FACTORY_ID     = A.FACTORY_ID
                                AND IA.OPERATION_ID   = A.OPERATION_ID
                                AND IA.LINE_ID        = A.LINE_ID
                                AND IA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                AND IA.LOSS_CODE      = A.LOSS_CODE )
                 WHERE EXISTS ( SELECT 1
                                  FROM ( SELECT DISTINCT
                                                F.DIVISION_ID
                                              , F.COMPANY_ID
                                              , F.SITE_ID
                                              , F.PLANT_ID
                                              , F.FACTORY_ID
                                              , F.LINE_ID
                                              , F.OPERATION_ID
                                              , F.ELECTRODE_TYPE
                                              , ( SELECT SEGMENT1
                                                    FROM SCM_SYS_LOOKUP_VALUE_SN G
                                                   WHERE 1 = 1
                                                     AND G.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                     AND G.ACTIVE_FLAG      = 'Y'
                                                     AND G.ATTRIBUTE1       = ( CASE WHEN F.DATA_TYPE_1 = 'DAILY CAPA' THEN 'TACT TIME' ELSE F.DATA_TYPE_1 END )
                                                ) AS LOSS_CODE
                                           FROM GT_SCP0049_UPL_DATA F
                                          WHERE 1 = 1
                                            AND F.DATA_TYPE_1 IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD')
                                         UNION ALL
                                         SELECT DISTINCT
                                                H.DIVISION_ID
                                              , H.COMPANY_ID
                                              , H.SITE_ID
                                              , H.PLANT_ID
                                              , H.FACTORY_ID
                                              , H.LINE_ID
                                              , H.OPERATION_ID
                                              , H.ELECTRODE_TYPE
                                              , ( SELECT SEGMENT1
                                                    FROM SCM_SYS_LOOKUP_VALUE_SN I
                                                   WHERE 1 = 1
                                                     AND I.LOOKUP_TYPE_CODE = 'CAPA_UI_LOSS_TYPE_DEFINIT'
                                                     AND I.ACTIVE_FLAG      = 'Y'
                                                     AND I.ATTRIBUTE1       = H.DATA_TYPE_1
                                                     AND I.ATTRIBUTE2       = H.DATA_TYPE_2
                                                ) AS LOSS_CODE
                                           FROM GT_SCP0049_UPL_DATA H
                                          WHERE 1 = 1
                                            AND H.DATA_TYPE_1 NOT IN ('LINE ASSIGN','TACT TIME','DAILY CAPA','YIELD') ) XA
                                 WHERE XA.COMPANY_ID     = A.COMPANY_ID
                                   AND XA.DIVISION_ID    = A.DIVISION_ID
                                   AND XA.SITE_ID        = A.SITE_ID
                                   AND XA.PLANT_ID       = A.PLANT_ID
                                   AND XA.FACTORY_ID     = A.FACTORY_ID
                                   AND XA.OPERATION_ID   = A.OPERATION_ID
                                   AND XA.LINE_ID        = A.LINE_ID
                                   AND XA.ELECTRODE_TYPE = A.ELECTRODE_TYPE
                                   AND XA.LOSS_CODE      = A.LOSS_CODE
                              );

                V_ROWCOUNT    := SQL%ROWCOUNT;
                V_LOG_TYPE    := 'INSERT';
                N_LOG_COUNT   := N_LOG_COUNT + 1;
                V_LOG_MESSAGE := '########## MERGE SCP0049 CAPA DATA END ##########';
                V_DESCRIPTION := TO_CHAR(V_ROWCOUNT);
                D_EVENT_DATE  := SYSDATE;
                P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

                /* AS-IS COMMIT TRANSACTION SCP0049_CAPA_UPLOAD */
                COMMIT;

            EXCEPTION   /* AS-IS BEGIN CATCH */
                WHEN OTHERS THEN
                    /* ROLLBACK 은 결과 커서 OPEN 앞에 둔다(뒤에 두면 커서가 닫힌다) */
                    ROLLBACK TO SAVEPOINT SP_SCP0049_CAPA_UPLOAD;

                    V_LOG_ERROR := V_LOG_ERROR || ' ::  ' || SQLERRM;
                    V_ERR       := V_LOG_ERROR;

                    /* AS-IS 는 ROLLBACK 뒤 SCM_SYS_LOG_BATCH 에 직접 적재(문장 단위 확정) */
                    /* PR_SCM_SYS_LOG_BATCH 가 자율 트랜잭션이므로 같은 결과가 된다      */
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', NULL, V_LOG_ERROR, NULL, SYSDATE, NULL
                                       , TO_CHAR(SQLCODE), SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
            END;

            N_LOG_COUNT   := N_LOG_COUNT + 1;
            V_LOG_MESSAGE := '########## INSERT/UPDATE SCP0049 CAPA DATA END ##########';
            V_DESCRIPTION := TO_CHAR(P_MODE);
            D_EVENT_DATE  := SYSDATE;
            P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        END IF;

        V_LOG_TYPE    := 'INSERT';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## INSERT DATA END ##########';
        V_DESCRIPTION := TO_CHAR(P_MODE);
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        V_LOG_TYPE    := 'END';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        P_LOG(V_LOG_TYPE, V_LOG_MESSAGE, V_DESCRIPTION);

        V_RESULT_EVENT := V_COUNT;

        /* 결과 커서 OPEN 은 반드시 RETURN 앞 */
        IF V_ERR IS NULL THEN
            OPEN O_RESULT_CURSOR FOR
            SELECT 'S'            AS RESULT_CODE
                 , V_RESULT_EVENT AS ERROR_CNT
              FROM DUAL;
        ELSE
            OPEN O_RESULT_CURSOR FOR
            SELECT '-1'  AS CODE
                 , V_ERR AS MSG
              FROM DUAL;
        END IF;

    END P_CAPA_EXCEL_UPLOAD_DAY;

/*
     * Program ID   : SCP0049_CAPA_LIMITS_VALID
     * Description  : CAPA Limits Validation
     * Program History
     *===========================================================================================================
     *   Date       In Charge   Description
     *===========================================================================================================
     * 2026.09.01   SYngSn      [E20260629-000313] capa ui  Tacttime  기준 mIN MAX 설정 건
     * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */
    PROCEDURE P_CAPA_LIMITS_VALID
    (
        P_MODE          IN  NUMBER
      , P_SES_USER_ID   IN  VARCHAR2
      , P_MNU_ID        IN  VARCHAR2
      , P_SHT_NM        IN  VARCHAR2
      , O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    IS

        -- 기본 변수 설정
        V_PROGRAM_ID        VARCHAR2(40 CHAR)  := 'SCP0049';
        V_SHEET_NAME        VARCHAR2(40 CHAR)  := 'CAPA_LIMITS';
        V_CREATION_DATE     VARCHAR2(40 CHAR);
        V_COUNT             NUMBER(10);

        -- LOG 용 변수 설정
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0049_CAPA_LIMITS_VALID';
        V_LOG_TYPE          VARCHAR2(30 CHAR);
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

    BEGIN

        -- [시작 로그 기록]
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        -- 최근 업로드 생성 일자 조회
        SELECT TO_CHAR(MAX(CREATION_DATE), 'YYYY-MM-DD HH24:MI:SS.FF3')
          INTO V_CREATION_DATE
          FROM SCM_ADM_EXCEL_UPLOAD
         WHERE PROGRAM_ID = V_PROGRAM_ID
           AND SHEET_NAME = V_SHEET_NAME
           AND CREATED_BY = P_SES_USER_ID;

        -- 업로드 데이터가 없는 경우 종료 처리
        IF V_CREATION_DATE IS NULL THEN
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := 'Data Not Found [' || NVL(V_CREATION_DATE, '') || ']';
            D_EVENT_DATE  := SYSDATE;

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            /* 결과 커서는 RETURN 앞에서 열어야 화면에서 커서를 받을 수 있다 */
            OPEN O_RESULT_CURSOR FOR
                SELECT NULL AS RESULT_CODE
                  FROM DUAL
                 WHERE 1 = 2;

            RETURN;
        END IF;

        -- Validation 및 결과 Update
        /* AS-IS 는 CTE 를 만들어 그 CTE 를 UPDATE 하는데 Oracle 에는 같은 형태가 없고
           WITH 도 쓰지 않으므로, 판정 결과를 GTT 에 담아 업로드 원장을 갱신한다 */
        DELETE FROM GT_SCP0049_LIMITS_VALID;

        INSERT INTO GT_SCP0049_LIMITS_VALID
             (
               UPLOAD_ID
             , IS_EXCEEDED
             )
        SELECT A.UPLOAD_ID

               -- IS_EXCEEDED 동적 메세지 산출 로직
             , CASE
                   WHEN NVL(IA.MAX_TACT_TIME, 0) = 0 THEN 'SUCCESS' --'N/A: Average Tact Time is 0'
                   WHEN NVL(ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2), 0) = 0 THEN 'SUCCESS' --'NO TOLERANCE_PERCENT_LOOKUP: Tolerance value missing'
                   WHEN ROUND(TO_NUMBER(A.ATTRIBUTE14 DEFAULT NULL ON CONVERSION ERROR), 2) IS NULL THEN 'ERROR: Invalid Tact Time format'

                   -- 화면 표기와 동일하게 소수점 2자리(DECIMAL)로 정제된 값으로 범위 비교
                   WHEN ROUND(TO_NUMBER(A.ATTRIBUTE14 DEFAULT NULL ON CONVERSION ERROR), 2)
                        < CASE
                              WHEN B.ATTRIBUTE1 = 'TACT TIME'  THEN ROUND(IA.MIN_TACT_TIME  * (1.0 - ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                              WHEN B.ATTRIBUTE1 = 'DAILY CAPA' THEN ROUND(IA.MIN_DAILY_CAPA * (1.0 - ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                          END
                     OR ROUND(TO_NUMBER(A.ATTRIBUTE14 DEFAULT NULL ON CONVERSION ERROR), 2)
                        > CASE
                              WHEN B.ATTRIBUTE1 = 'TACT TIME'  THEN ROUND(IA.MAX_TACT_TIME  * (1.0 + ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                              WHEN B.ATTRIBUTE1 = 'DAILY CAPA' THEN ROUND(IA.MAX_DAILY_CAPA * (1.0 + ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                          END
                   THEN 'Out of range '
                        -- 오차율 (%)
                        --+ CONVERT(VARCHAR, CAST(ROUND(((CA1.INPUT_TACT_TIME - B.AVG_TACT_TIME) / B.AVG_TACT_TIME) * 100, 1) AS DECIMAL(18, 1))) + '% '
                        -- Allowed range: 조건 판정에 사용된 하한/상한값 표기
                        || '(Allowed: '
                        || TRIM(TO_CHAR(CASE
                                            WHEN B.ATTRIBUTE1 = 'TACT TIME'  THEN ROUND(IA.MIN_TACT_TIME  * (1.0 - ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                                            WHEN B.ATTRIBUTE1 = 'DAILY CAPA' THEN ROUND(IA.MIN_DAILY_CAPA * (1.0 - ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                                        END, 'FM99999999999999990.00'))
                        || '-'
                        || TRIM(TO_CHAR(CASE
                                            WHEN B.ATTRIBUTE1 = 'TACT TIME'  THEN ROUND(IA.MAX_TACT_TIME  * (1.0 + ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                                            WHEN B.ATTRIBUTE1 = 'DAILY CAPA' THEN ROUND(IA.MAX_DAILY_CAPA * (1.0 + ROUND(TO_NUMBER(B.ATTRIBUTE3 DEFAULT NULL ON CONVERSION ERROR), 2) / 100.0), 2)
                                        END, 'FM99999999999999990.00'))
                        || ')'

                   ELSE 'SUCCESS'
               END                                          AS IS_EXCEEDED

          FROM SCM_ADM_EXCEL_UPLOAD A

               -- LOOKUP 테이블: 허용 오차율(%) Lookup 조인
             , SCM_ADM_LOOKUP_VALUE_FP_SN B

               -- IA 인라인 뷰: 조건별 TACT_TIME 집계
             , (
                SELECT COMPANY_ID
                     , SITE_ID
                     , OPERATION_ID
                     , MIN(TACT_TIME)   AS MIN_TACT_TIME
                     , MAX(TACT_TIME)   AS MAX_TACT_TIME
                     , MIN(DAILY_CAPA)  AS MIN_DAILY_CAPA
                     , MAX(DAILY_CAPA)  AS MAX_DAILY_CAPA
                  FROM SCM_MST_TACT_TIME_SN
                 WHERE 1 = 1
                   --AND TACT_TIME <> 0
                   AND MONTH >= TO_CHAR(SYSDATE, 'YYYYMM') --이번달 이후만 집계
                 GROUP BY COMPANY_ID
                        , SITE_ID
                        , OPERATION_ID
                   --HAVING COUNT(LINE_ID) > 10 --표본 값이 몇개는 있어야 하지 않나?
               ) IA

         WHERE IA.COMPANY_ID(+)         = A.ATTRIBUTE2
           AND IA.SITE_ID(+)            = A.ATTRIBUTE3
           AND IA.OPERATION_ID(+)       = A.ATTRIBUTE7
           AND B.LOOKUP_TYPE_CODE(+)    = 'CAPA_UI_CAPA_DEFINIT'
           AND B.SEGMENT2(+)            = A.ATTRIBUTE4  -- PLANT_ID
           AND B.SEGMENT3(+)            = A.ATTRIBUTE7  -- OPERATION_ID

               -- 대상 변수 조건
           AND A.PROGRAM_ID             = V_PROGRAM_ID
           AND A.SHEET_NAME             = V_SHEET_NAME
           AND A.CREATED_BY             = P_SES_USER_ID
           AND TO_CHAR(A.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
           AND A.UPLOAD_STATUS_CODE     = 'UPLOAD';

        -- SUCCESS가 아닌 대상 건에 대해 MESSAGE_TEXT 업데이트 및 STATUS를 ERROR로 변경
        UPDATE SCM_ADM_EXCEL_UPLOAD A
           SET A.UPLOAD_STATUS_CODE = (
                                       SELECT CASE WHEN B.IS_EXCEEDED <> 'SUCCESS' THEN 'ERROR' ELSE B.IS_EXCEEDED END
                                         FROM GT_SCP0049_LIMITS_VALID B
                                        WHERE B.UPLOAD_ID = A.UPLOAD_ID
                                      )
             , A.MESSAGE_TEXT       = (
                                       SELECT B.IS_EXCEEDED
                                         FROM GT_SCP0049_LIMITS_VALID B
                                        WHERE B.UPLOAD_ID = A.UPLOAD_ID
                                      )
         WHERE EXISTS (
                       SELECT 1
                         FROM GT_SCP0049_LIMITS_VALID B
                        WHERE B.UPLOAD_ID = A.UPLOAD_ID
                      );

        V_LOG_TYPE    := 'UPDATE';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## SUCCESS ##########';
        V_DESCRIPTION := TO_CHAR(SQL%ROWCOUNT);
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        -- ERROR 건수 확인
        SELECT COUNT(1)
          INTO V_COUNT
          FROM SCM_ADM_EXCEL_UPLOAD
         WHERE PROGRAM_ID         = V_PROGRAM_ID
           AND SHEET_NAME         = V_SHEET_NAME
           AND CREATED_BY         = P_SES_USER_ID
           AND TO_CHAR(CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS.FF3') = V_CREATION_DATE
           AND UPLOAD_STATUS_CODE = 'ERROR';

        -- [종료 로그 기록]
        V_LOG_TYPE    := 'END';
        N_LOG_COUNT   := N_LOG_COUNT + 1;
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := 'Error Count: ' || TO_CHAR(V_COUNT);
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* AS-IS 는 결과셋을 내지 않는다 — 화면 경로가 커서를 받으므로 빈 결과를 연다 */
        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS RESULT_CODE
              FROM DUAL
             WHERE 1 = 2;

    END P_CAPA_LIMITS_VALID;

END PKG_SCP0049;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0049
-- ##### END PACKAGE BODY PKG_SCP0049

-- ##### START PACKAGE BODY PKG_SCP0055
CREATE OR REPLACE PACKAGE BODY PKG_SCP0055
IS
    /*
     * Program ID   : PKG_SCP0055
     * Description  : SCP0055 Shipment(Allo) Report 화면 — 팀별 출하 계획 · 실적 조회, 메모 조회 · 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.26   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     * 2026.10.07   ZIONEX       화면 실측 검증 — 메모 저장 여러 줄(^ 이음) 처리
     */

/****************************************************************************************************/
/* Program ID  : P_SCP0055_GET_SHIPMENT_ALLO_PLAN                                                   */
/* Description : 팀별 출하 계획 · 실적 조회                                                         */
/****************************************************************************************************/
PROCEDURE P_SCP0055_GET_SHIPMENT_ALLO_PLAN
(
    P_FROM_YYYYMMDD         IN  CLOB
  , P_TO_YYYYMMDD           IN  CLOB
  , P_DIVISION_ID           IN  CLOB
  , P_BIZ_TYPE              IN  CLOB
  , P_ITEM_ID               IN  CLOB
  , P_CELL_TYPE_GR          IN  CLOB
  , P_PLAN_START_YYYYMMDD   IN  CLOB
  , P_FROMSITE              IN  CLOB
  , P_TEAM_ID               IN  CLOB
  , P_NICKNAME              IN  CLOB
  , P_PROGRAM_ID            IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , P_SHEET_NAME            IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , P_USER_ID               IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , P_FCST_YN               IN  CLOB
  , O_RC1                   OUT SYS_REFCURSOR
  , O_RC2                   OUT SYS_REFCURSOR
  , O_RC3                   OUT SYS_REFCURSOR
  , O_RC4                   OUT SYS_REFCURSOR
  , O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
IS
    /* 원문이 조회조건을 NVARCHAR(8)·NVARCHAR(30)·NVARCHAR(3)·NVARCHAR(2) 로 받아 그 길이에서 자른다 */
    V_FROM_YYYYMMDD_IN      VARCHAR2(8 CHAR)    := TO_CHAR(SUBSTR(P_FROM_YYYYMMDD,       1, 8));
    V_TO_YYYYMMDD_IN        VARCHAR2(8 CHAR)    := TO_CHAR(SUBSTR(P_TO_YYYYMMDD,         1, 8));
    V_DIVISION_ID           VARCHAR2(30 CHAR)   := TO_CHAR(SUBSTR(P_DIVISION_ID,         1, 30));
    V_BIZ_TYPE              VARCHAR2(30 CHAR)   := TO_CHAR(SUBSTR(P_BIZ_TYPE,            1, 30));
    V_ITEM_ID               VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID,             1, 4000));
    V_CELL_TYPE_GR          VARCHAR2(3 CHAR)    := TO_CHAR(SUBSTR(P_CELL_TYPE_GR,        1, 3));
    V_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR)    := TO_CHAR(SUBSTR(P_PLAN_START_YYYYMMDD, 1, 8));
    V_FROMSITE              VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_FROMSITE,            1, 4000));
    V_TEAM_ID               VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_TEAM_ID,             1, 4000));
    V_NICKNAME              VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_NICKNAME,            1, 4000));
    V_FCST_YN               VARCHAR2(2 CHAR)    := TO_CHAR(SUBSTR(P_FCST_YN,             1, 2));

    /* 계획 · 실적 기간 */
    V_FROM_YYYYMMDD         VARCHAR2(8 CHAR)    := '';
    V_TO_YYYYMMDD           VARCHAR2(8 CHAR)    := '';
    V_FROM_RESULT           VARCHAR2(8 CHAR)    := '';
    V_TO_RESULT             VARCHAR2(8 CHAR)    := '';

    V_PLAN_TYPE             VARCHAR2(8 CHAR);
    V_SEQ                   VARCHAR2(8 CHAR);
BEGIN

    /* 시작 시 임시 자료를 비운다 (TRUNCATE 는 암묵 커밋이라 쓰지 않는다) */
    DELETE FROM GT_SCP0055_PLAN;
    DELETE FROM GT_SCP0055_PLAN_TOTAL;
    DELETE FROM GT_SCP0055_RESULT;
    DELETE FROM GT_SCP0055_RESULT_TOTAL;

    /* 계획 시작일 · 조회 기간의 주 시작일 */
    BEGIN
        SELECT BASIS_START_DATE
          INTO V_FROM_YYYYMMDD
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_FROM_YYYYMMDD := '';
    END;

    BEGIN
        SELECT BASIS_START_DATE
          INTO V_FROM_RESULT
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_FROM_YYYYMMDD_IN;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_FROM_RESULT := '';
    END;

    BEGIN
        SELECT BASIS_START_DATE
          INTO V_TO_RESULT
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_TO_YYYYMMDD_IN;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN V_TO_RESULT := '';
    END;

    /* ★원문이 네 갈래로 적었으나 둘째 갈래가 첫째의 반대라 셋째 · 넷째에는 닿지 않는다.
          원문 그대로 옮긴다 */
    IF V_FROM_YYYYMMDD > V_FROM_RESULT
    THEN
        /* 실적 보여줌 */
        V_TO_YYYYMMDD := V_TO_YYYYMMDD_IN;
        V_TO_RESULT   := V_FROM_YYYYMMDD;
    ELSIF V_FROM_YYYYMMDD <= V_FROM_RESULT
    THEN
        /* 실적 없음 */
        V_TO_YYYYMMDD := V_TO_YYYYMMDD_IN;
        V_FROM_RESULT := TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'),  6), 'YYYYMMDD');
        V_TO_RESULT   := TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
    ELSIF V_FROM_YYYYMMDD > V_TO_RESULT
    THEN
        V_FROM_YYYYMMDD := TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
        V_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), -6), 'YYYYMMDD');
        V_FROM_RESULT   := V_FROM_YYYYMMDD_IN;
        V_TO_RESULT     := V_TO_YYYYMMDD_IN;
    ELSIF V_FROM_YYYYMMDD = V_TO_RESULT
    THEN
        V_TO_YYYYMMDD := V_FROM_YYYYMMDD;
        V_FROM_RESULT := V_FROM_YYYYMMDD_IN;
        V_TO_RESULT   := V_TO_YYYYMMDD_IN;
    END IF;

    /* ★원문이 품목 · 출발사이트를 따옴표로 이은 문자로 만들어 두고 쓰지 않는다. 옮기지 않았다
          (@ARR_ITEM_ID · @ARR_FROMSITE) */

    /* 최신 PLAN TYPE, SEQ 조회
       ##################################################################################
       -- 20220413 요청사항
       PR까지만 진행된 경우엔 PR의 amend
       MA까지 진행된경우엔 MA의 amend값
       FN이 진행되어도 MA의 amend값 */
    BEGIN
        SELECT IA.CODE
             , IA.PLAN_SEQ
          INTO V_PLAN_TYPE
             , V_SEQ
          FROM (SELECT PLAN_TYPE                    AS CODE
                     , MAX(PLAN_SEQ)                AS PLAN_SEQ
                     , MAX(PLAN_TYPE_ORDER)         AS PLAN_TYPE_ORDER
                  FROM SCP_PLAN_VERSION_V
                 WHERE DIVISION_ID         = V_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND PLAN_TYPE IN ('PR', 'MA')
                 GROUP BY PLAN_TYPE) IA
         WHERE IA.PLAN_TYPE_ORDER = (SELECT MAX(XA.PLAN_TYPE_ORDER)
                                       FROM (SELECT MAX(PLAN_TYPE_ORDER) AS PLAN_TYPE_ORDER
                                               FROM SCP_PLAN_VERSION_V
                                              WHERE DIVISION_ID         = V_DIVISION_ID
                                                AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                                                AND PLAN_TYPE IN ('PR', 'MA')
                                              GROUP BY PLAN_TYPE) XA);
    EXCEPTION
        WHEN NO_DATA_FOUND THEN NULL;   /* 원문도 값을 못 찾으면 그대로 둔다 */
    END;

    /* ##################################################################################
       -- 20220425 요청사항
       P_FCST_YN = Y => FN
       P_FCST_YN = N => PR, MA */
    IF V_FCST_YN = 'Y'
    THEN
        BEGIN
            SELECT IA.CODE
                 , IA.PLAN_SEQ
              INTO V_PLAN_TYPE
                 , V_SEQ
              FROM (SELECT PLAN_TYPE                AS CODE
                         , MAX(PLAN_SEQ)            AS PLAN_SEQ
                         , MAX(PLAN_TYPE_ORDER)     AS PLAN_TYPE_ORDER
                      FROM SCP_PLAN_VERSION_V
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND PLAN_TYPE IN ('PR', 'MA', 'FN')
                     GROUP BY PLAN_TYPE) IA
             WHERE IA.PLAN_TYPE_ORDER = (SELECT MAX(XA.PLAN_TYPE_ORDER)
                                           FROM (SELECT MAX(PLAN_TYPE_ORDER) AS PLAN_TYPE_ORDER
                                                   FROM SCP_PLAN_VERSION_V
                                                  WHERE DIVISION_ID         = V_DIVISION_ID
                                                    AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                                                    AND PLAN_TYPE IN ('PR', 'MA', 'FN')
                                                  GROUP BY PLAN_TYPE) XA);
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;
    END IF;

    /* 계획 (Shipment Plan FG) */
    INSERT INTO GT_SCP0055_PLAN
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM )
    SELECT IA.DIVISION_ID
         , IA.SITE_ID
         , IA.SITE_NAME
         , IA.EXTRA_SPEC
         , IA.NICK_NAME
         , IA.DEPT_ID
         , IA.DEPT_NAME
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                              AS QTY
         , 'FG'                                                     AS PLAN_FROM
      FROM (SELECT A.DIVISION_ID
                 , A.FROM_SITE                                      AS SITE_ID
                 , NVL((SELECT XA.SITE_DESCRIPTION
                          FROM SCM_MST_SITE XA
                         WHERE XA.SCM_SITE_ID = A.FROM_SITE
                           AND ROWNUM         = 1), '/')             AS SITE_NAME
                 , (SELECT NVL(XB.SCP_EXTRA_SPEC, '-')
                      FROM SCM_MST_ITEM_SN XB
                     WHERE XB.DIVISION_ID = A.DIVISION_ID
                       AND XB.ITEM_ID     = A.ITEM_ID
                       AND ROWNUM         = 1)                       AS EXTRA_SPEC
                 , (SELECT NVL(XC.NICK_NAME, '-')
                      FROM SCM_MST_ITEM_SN XC
                     WHERE XC.ITEM_ID = A.ITEM_ID
                       AND ROWNUM     = 1)                           AS NICK_NAME
                 , D.DEPT_ID
                 , E.DEPT_NAME_KO                                    AS DEPT_NAME
                 , A.YYYYMMDD
                 , A.QTY
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.BIZ_TYPE
                 , A.ITEM_ID
              FROM SCP_ANL_SHIPMENT_PLAN_FG A
                 , SCP_MST_FINAL_ITEM       B
                 , SCM_MST_SITE_ITEM        C
                 , SCM_MST_SSO_USER_INFO    D
                 , SCM_MST_SSO_DEPT_INFO    E
             WHERE B.DIVISION_ID          = A.DIVISION_ID
               AND B.OPERATION_GROUP_ID   = A.BIZ_TYPE
               AND B.ITEM_ID              = A.ITEM_ID
               AND C.DIVISION_ID          = A.DIVISION_ID
               AND C.SCM_SITE_ID          = A.TO_SITE
               AND C.PROJECT_CODE         = A.PROJECT_CODE
               AND C.ITEM_ID              = A.ITEM_ID
               AND C.VALID_YN             = 'Y'
               /* ★원문은 소유자 목록의 첫 사람을 잘라 쓴다. MSSQL SUBSTRING 시작이 0 이라
                     쉼표 앞까지만 잘리므로 Oracle 은 시작 1 · 길이를 하나 줄여 맞춘다 */
               /* ★원문은 소유자 목록의 첫 사람을 잘라 쓴다. MSSQL SUBSTRING 시작이 0 이라
                     쉼표 앞까지만 잘리므로 Oracle 은 시작 1 · 길이를 하나 줄여 맞춘다.
                     AS-IS 는 대소문자를 가리지 않는다. 소유자와 사용자 번호가 대소문자만 다른 행이
                     4,256건 있어 양쪽을 대문자로 맞춘다 */
               AND UPPER(D.USER_ID(+))    = UPPER(SUBSTR(C.OWNER, 1, CASE WHEN INSTR(C.OWNER, ',') = 0
                                                                          THEN LENGTH(C.OWNER)
                                                                          ELSE INSTR(C.OWNER, ',') - 1
                                                                     END))
               AND E.DEPT_ID(+)           = D.DEPT_ID
               AND A.YYYYMMDD            >= V_FROM_YYYYMMDD
               AND A.YYYYMMDD            <= V_TO_YYYYMMDD
               AND A.DIVISION_ID          = V_DIVISION_ID
               AND A.BIZ_TYPE             = V_BIZ_TYPE
               AND (TRIM(V_FROMSITE) IS NULL
                OR  UPPER(V_FROMSITE) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
                OR  A.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE)
                                      FROM TABLE(STRING_SPLIT(V_FROMSITE, ','))))
               AND (TRIM(V_TEAM_ID) IS NULL
                OR  UPPER(V_TEAM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  D.DEPT_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_TEAM_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR  UPPER(V_ITEM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  A.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND (TRIM(V_CELL_TYPE_GR) IS NULL
                OR  UPPER(V_CELL_TYPE_GR) = 'ALL'                    /* 조회조건 ALL 은 조건 없음 */
                OR  B.CELL_TYPE_GROUP_CODE IN (SELECT UPPER(COLUMN_VALUE)
                                                 FROM TABLE(STRING_SPLIT(V_CELL_TYPE_GR, ','))))
               AND A.MEASURE              = 'SHIP_PLAN_AMEND'
               AND A.PLAN_START_YYYYMMDD  = V_PLAN_START_YYYYMMDD
               /* 파티션 키(가상 컬럼)로 훑는 범위를 줄인다. 값은 계획 시작일과 같다 */
               AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
               AND A.PLAN_TYPE            = V_PLAN_TYPE
               AND A.SEQ                  = TO_NUMBER(V_SEQ)
               AND A.QTY                  > 0) IA
     GROUP BY IA.DIVISION_ID
            , IA.PLAN_START_YYYYMMDD
            , IA.PLAN_TYPE
            , IA.SEQ
            , IA.BIZ_TYPE
            , IA.SITE_ID
            , IA.ITEM_ID
            , IA.DEPT_ID
            , IA.DEPT_NAME
            , IA.YYYYMMDD
            , IA.SITE_NAME
            , IA.EXTRA_SPEC
            , IA.NICK_NAME;

    /* 계획 (Shipment Plan Semi) */
    INSERT INTO GT_SCP0055_PLAN
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM )
    SELECT IA.DIVISION_ID
         , IA.SITE_ID
         , IA.SITE_NAME
         , IA.EXTRA_SPEC
         , IA.NICK_NAME
         , IA.DEPT_ID
         , IA.DEPT_NAME
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                              AS QTY
         , 'SEMI'                                                   AS PLAN_FROM
      FROM (SELECT A.DIVISION_ID
                 , A.FROM_SITE                                      AS SITE_ID
                 , NVL((SELECT XA.SITE_DESCRIPTION
                          FROM SCM_MST_SITE XA
                         WHERE XA.SCM_SITE_ID = A.FROM_SITE
                           AND ROWNUM         = 1), '/')             AS SITE_NAME
                 , (SELECT NVL(XB.SCP_EXTRA_SPEC, '-')
                      FROM SCM_MST_ITEM_SN XB
                     WHERE XB.DIVISION_ID = A.DIVISION_ID
                       AND XB.ITEM_ID     = A.ITEM_ID
                       AND ROWNUM         = 1)                       AS EXTRA_SPEC
                 , (SELECT NVL(XC.NICK_NAME, '-')
                      FROM SCM_MST_ITEM_SN XC
                     WHERE XC.ITEM_ID = A.ITEM_ID
                       AND ROWNUM     = 1)                           AS NICK_NAME
                 , C.ATTRIBUTE1                                      AS DEPT_ID
                 , C.ATTRIBUTE2                                      AS DEPT_NAME
                 , A.YYYYMMDD
                 , A.QTY
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.OPERATION_GROUP
                 , A.ITEM_ID
              FROM SCP_ANL_SHIPMENT_PLAN_SEMI A
                 , SCP_MST_FINAL_ITEM         B
                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
             WHERE B.DIVISION_ID          = A.DIVISION_ID
               AND B.OPERATION_GROUP_ID   = A.OPERATION_GROUP
               AND B.ITEM_ID              = A.ITEM_ID
               AND C.SEGMENT1(+)          = A.FROM_SITE
               AND C.SEGMENT2(+)          = A.TO_SITE
               AND C.SEGMENT3(+)          = A.ITEM_ID
               AND C.LOOKUP_TYPE(+)       = 'SHIPMENT_REPORT_LOOKUP'
               AND A.YYYYMMDD            >= V_FROM_YYYYMMDD
               AND A.YYYYMMDD            <= V_TO_YYYYMMDD
               AND A.DIVISION_ID          = V_DIVISION_ID
               AND A.OPERATION_GROUP      = V_BIZ_TYPE
               AND (TRIM(V_FROMSITE) IS NULL
                OR  UPPER(V_FROMSITE) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
                OR  A.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE)
                                      FROM TABLE(STRING_SPLIT(V_FROMSITE, ','))))
               AND (TRIM(V_TEAM_ID) IS NULL
                OR  UPPER(V_TEAM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  C.ATTRIBUTE1 IN (SELECT UPPER(COLUMN_VALUE)
                                       FROM TABLE(STRING_SPLIT(V_TEAM_ID, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR  UPPER(V_ITEM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  A.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND (TRIM(V_CELL_TYPE_GR) IS NULL
                OR  UPPER(V_CELL_TYPE_GR) = 'ALL'                    /* 조회조건 ALL 은 조건 없음 */
                OR  B.CELL_TYPE_GROUP_CODE IN (SELECT UPPER(COLUMN_VALUE)
                                                 FROM TABLE(STRING_SPLIT(V_CELL_TYPE_GR, ','))))
               AND A.MEASURE              = 'SHIP_PLAN_AMEND'
               AND A.PLAN_START_YYYYMMDD  = V_PLAN_START_YYYYMMDD
               /* 파티션 키(가상 컬럼)로 훑는 범위를 줄인다 */
               AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
               AND A.PLAN_TYPE            = V_PLAN_TYPE
               AND A.SEQ                  = TO_NUMBER(V_SEQ)
               AND A.QTY                  > 0) IA
     GROUP BY IA.DIVISION_ID
            , IA.PLAN_START_YYYYMMDD
            , IA.PLAN_TYPE
            , IA.SEQ
            , IA.OPERATION_GROUP
            , IA.SITE_ID
            , IA.ITEM_ID
            , IA.DEPT_ID
            , IA.DEPT_NAME
            , IA.YYYYMMDD
            , IA.SITE_NAME
            , IA.EXTRA_SPEC
            , IA.NICK_NAME;

    /* 계획 합계 */
    INSERT INTO GT_SCP0055_PLAN_TOTAL
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM )
    SELECT A.DIVISION_ID
         , A.SITE_ID
         , A.SITE_NAME
         , A.EXTRA_SPEC
         , A.NICK_NAME
         , A.DEPT_ID
         , A.DEPT_NAME
         , A.YYYYMMDD
         , SUM(A.QTY)                                               AS QTY
         , 'PLAN_TOTAL'                                             AS PLAN_FROM
      FROM GT_SCP0055_PLAN A
     WHERE (TRIM(V_NICKNAME) IS NULL
        OR  UPPER(V_NICKNAME) = 'ALL'                               /* 조회조건 ALL 은 조건 없음 */
        OR  A.NICK_NAME IN (SELECT UPPER(COLUMN_VALUE)
                              FROM TABLE(STRING_SPLIT(V_NICKNAME, ','))))
     GROUP BY A.DIVISION_ID
            , A.NICK_NAME
            , A.SITE_ID
            , A.SITE_NAME
            , A.EXTRA_SPEC
            , A.DEPT_ID
            , A.DEPT_NAME
            , A.YYYYMMDD;

    /* 팀별 출하 실적 (ERP) — 확정번호가 있는 것
       ★원문은 소유자 찾는 스칼라 조회를 조인 조건에 두었다. Oracle 은 외부 조인 조건에
         조회문을 쓸 수 없어(ORA-01799) 담당 · 팀 이름을 스칼라 조회로 바꿔 인라인 조회에 두었다.
         담당 원장은 사용자 번호가, 팀 원장은 팀 번호가 하나뿐임을 실측해 값이 갈리지 않는다 */
    INSERT INTO GT_SCP0055_RESULT
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM, CONFIRM_ID )
    SELECT IA.DIVISION_ID
         , IA.SITE_ID
         , IA.SITE_NAME
         , IA.EXTRA_SPEC
         , IA.NICK_NAME
         , NVL(IA.SUI_DEPT_ID, IA.LMD_ATTRIBUTE1)                   AS DEPT_ID
         , NVL(NVL(IA.SDI_DEPT_NAME_KO, IA.LMD_ATTRIBUTE2), IA.SMS_SITE_DESCRIPTION) AS DEPT_NAME
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                              AS QTY
         , 'RESULT_CE'                                              AS PLAN_FROM
         , IA.CONFIRM_ID
      FROM (SELECT A.DIVISION_ID
                 , B.FROM_SITE                                      AS SITE_ID
                 , NVL((SELECT XA.SITE_DESCRIPTION
                          FROM SCM_MST_SITE XA
                         WHERE XA.SCM_SITE_ID = B.FROM_SITE
                           AND ROWNUM         = 1), '/')             AS SITE_NAME
                 , (SELECT NVL(XB.SCP_EXTRA_SPEC, '-')
                      FROM SCM_MST_ITEM_SN XB
                     WHERE XB.DIVISION_ID = A.DIVISION_ID
                       AND XB.ITEM_ID     = A.ITEM_ID
                       AND ROWNUM         = 1)                       AS EXTRA_SPEC
                 , (SELECT NVL(XC.NICK_NAME, '-')
                      FROM SCM_MST_ITEM_SN XC
                     WHERE XC.ITEM_ID = A.ITEM_ID
                       AND ROWNUM     = 1)                           AS NICK_NAME
                 /* 담당 팀 — 도착 사이트의 품목 소유자로 찾는다 */
                 , (SELECT XD.DEPT_ID
                      FROM SCM_MST_SSO_USER_INFO XD
                     WHERE UPPER(XD.USER_ID) = (SELECT UPPER(XE.OWNER)
                                           FROM (SELECT XF.OWNER
                                                   FROM SCM_MST_SITE_ITEM XF
                                                  WHERE XF.DIVISION_ID = A.DIVISION_ID
                                                    AND XF.SCM_SITE_ID = NVL(C3.SEGMENT4, B.TO_SITE)
                                                    AND XF.ITEM_ID     = A.ITEM_ID
                                                    AND XF.VALID_YN    = 'Y'
                                                  /* ★원문은 소유자를 한 행만 고르고 차례를 정하지 않았다.
                                                        차례를 정하면 값 없는 소유자가 뒤로 밀려 원문과 갈리므로
                                                        원문처럼 정하지 않고 둔다 (재현 대상 아님) */
                                                  ) XE
                                          WHERE ROWNUM = 1)) AS SUI_DEPT_ID
                 , (SELECT XG.DEPT_NAME_KO
                      FROM SCM_MST_SSO_DEPT_INFO XG
                     WHERE XG.DEPT_ID  = (SELECT XH.DEPT_ID
                                            FROM SCM_MST_SSO_USER_INFO XH
                                           WHERE UPPER(XH.USER_ID) = (SELECT UPPER(XI.OWNER)
                                                                 FROM (SELECT XJ.OWNER
                                                                         FROM SCM_MST_SITE_ITEM XJ
                                                                        WHERE XJ.DIVISION_ID = A.DIVISION_ID
                                                                          AND XJ.SCM_SITE_ID = NVL(C3.SEGMENT4, B.TO_SITE)
                                                                          AND XJ.ITEM_ID     = A.ITEM_ID
                                                                          AND XJ.VALID_YN    = 'Y'
                                                                        ) XI
                                                                WHERE ROWNUM = 1))
                       AND XG.VALID_YN = 'Y') AS SDI_DEPT_NAME_KO
                 , C4.ATTRIBUTE1                                     AS LMD_ATTRIBUTE1
                 , C4.ATTRIBUTE2                                     AS LMD_ATTRIBUTE2
                 , D.SITE_DESCRIPTION                                AS SMS_SITE_DESCRIPTION
                 , A.EXFACTORY_DATE                                  AS YYYYMMDD
                 , A.EXFACTORY_QTY                                   AS QTY
                 , A.CONFIRM_ID
                 , A.ITEM_ID
              FROM SCM_DNM_EXFACTORY_RESULT      A
                 , SSP_ANL_SHIP_CONFIRM          B
                 , SCP_MST_FINAL_ITEM            C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL  C2
                 , SCM_ADM_LOOKUP_MASTER_DETAIL  C3
                 , SCM_ADM_LOOKUP_MASTER_DETAIL  C4
                 , SCM_MST_SITE                  D
             WHERE B.DIVISION_ID       = A.DIVISION_ID
               AND B.CONFIRM_ID        = A.CONFIRM_ID
               AND C.ITEM_ID           = A.ITEM_ID
               AND C.DIVISION_ID       = A.DIVISION_ID
               /* 룩업에 등록된 공정만 */
               AND C2.LOOKUP_TYPE      = 'ERP_SSP_TYPE'
               AND C2.VALID_YN         = 'Y'
               AND C2.SEGMENT1         = A.SSP_TYPE
               /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
               AND C3.LOOKUP_TYPE(+)   = 'SHIP_RESULT_TO_SITE_MAPPING'
               AND C3.SEGMENT1(+)      = A.DIVISION_ID
               AND C3.SEGMENT2(+)      = A.SOLDTO_CODE
               AND C3.SEGMENT3(+)      = A.SHIPTO_CODE
               AND C4.SEGMENT1(+)      = A.FROM_SCM_SITE_ID
               AND C4.SEGMENT2(+)      = NVL(C3.SEGMENT4, B.TO_SITE)
               AND C4.SEGMENT3(+)      = A.ITEM_ID
               AND C4.LOOKUP_TYPE(+)   = 'SHIPMENT_REPORT_LOOKUP'
               AND D.DIVISION_ID(+)    = A.DIVISION_ID
               AND D.SCM_SITE_ID(+)    = B.TO_SITE
               AND D.OSP_YN(+)         = 'Y'
               AND D.VALID_YN(+)       = 'Y'
               /* D90: DO삭제 , D10:DO생성 */
               AND NVL(A.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
               AND A.CONFIRM_ID LIKE 'C%'
               AND A.DIVISION_ID       = V_DIVISION_ID
               AND C.OPERATION_GROUP   = V_BIZ_TYPE
               AND (TRIM(V_FROMSITE) IS NULL
                OR  UPPER(V_FROMSITE) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
                OR  B.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE)
                                      FROM TABLE(STRING_SPLIT(V_FROMSITE, ','))))
               AND (TRIM(V_CELL_TYPE_GR) IS NULL
                OR  UPPER(V_CELL_TYPE_GR) = 'ALL'                    /* 조회조건 ALL 은 조건 없음 */
                OR  C.CELL_TYPE_GROUP_CODE IN (SELECT UPPER(COLUMN_VALUE)
                                                 FROM TABLE(STRING_SPLIT(V_CELL_TYPE_GR, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR  UPPER(V_ITEM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  A.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND A.EXFACTORY_DATE   >= V_FROM_RESULT
               AND A.EXFACTORY_DATE    < V_TO_RESULT) IA
     /* 팀 조건은 담당 · 룩업 둘 중 하나만 맞아도 통과한다(원문과 같다) */
     WHERE (TRIM(V_TEAM_ID) IS NULL
        OR  UPPER(V_TEAM_ID) = 'ALL'                                 /* 조회조건 ALL 은 조건 없음 */
        OR  IA.SUI_DEPT_ID IN (SELECT UPPER(COLUMN_VALUE)
                                 FROM TABLE(STRING_SPLIT(V_TEAM_ID, ',')))
        OR  IA.LMD_ATTRIBUTE1 IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_TEAM_ID, ','))))
     GROUP BY IA.DIVISION_ID
            , IA.SITE_ID
            , IA.ITEM_ID
            , NVL(IA.SUI_DEPT_ID, IA.LMD_ATTRIBUTE1)
            , IA.SDI_DEPT_NAME_KO
            , IA.LMD_ATTRIBUTE2
            , IA.SMS_SITE_DESCRIPTION
            , IA.YYYYMMDD
            , IA.CONFIRM_ID
            , IA.SITE_NAME
            , IA.EXTRA_SPEC
            , IA.NICK_NAME;

    /* 팀별 출하 실적 (ERP) — 확정번호가 없는 것 */
    INSERT INTO GT_SCP0055_RESULT
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM, CONFIRM_ID )
    SELECT IA.DIVISION_ID
         , IA.SITE_ID
         , IA.SITE_NAME
         , IA.EXTRA_SPEC
         , IA.NICK_NAME
         , NVL(IA.SUI_DEPT_ID, IA.LMD_ATTRIBUTE1)                   AS DEPT_ID
         , NVL(NVL(IA.SDI_DEPT_NAME_KO, IA.LMD_ATTRIBUTE2), IA.SMS_SITE_DESCRIPTION) AS DEPT_NAME
         , IA.YYYYMMDD
         , SUM(IA.QTY)                                              AS QTY
         , 'RESULT_CN'                                              AS PLAN_FROM
         , NULL                                                     AS CONFIRM_ID
      FROM (SELECT A.DIVISION_ID
                 , A.FROM_SCM_SITE_ID                               AS SITE_ID
                 , NVL((SELECT XA.SITE_DESCRIPTION
                          FROM SCM_MST_SITE XA
                         WHERE XA.SCM_SITE_ID = A.FROM_SCM_SITE_ID
                           AND ROWNUM         = 1), '/')             AS SITE_NAME
                 , (SELECT NVL(XB.SCP_EXTRA_SPEC, '-')
                      FROM SCM_MST_ITEM_SN XB
                     WHERE XB.DIVISION_ID = A.DIVISION_ID
                       AND XB.ITEM_ID     = A.ITEM_ID
                       AND ROWNUM         = 1)                       AS EXTRA_SPEC
                 , (SELECT NVL(XC.NICK_NAME, '-')
                      FROM SCM_MST_ITEM_SN XC
                     WHERE XC.ITEM_ID = A.ITEM_ID
                       AND ROWNUM     = 1)                           AS NICK_NAME
                 , (SELECT XD.DEPT_ID
                      FROM SCM_MST_SSO_USER_INFO XD
                     WHERE UPPER(XD.USER_ID) = (SELECT UPPER(XE.OWNER)
                                           FROM (SELECT XF.OWNER
                                                   FROM SCM_MST_SITE_ITEM XF
                                                  WHERE XF.DIVISION_ID = A.DIVISION_ID
                                                    AND XF.SCM_SITE_ID = NVL(C3.SEGMENT4, A.TO_SCM_SITE_ID)
                                                    AND XF.ITEM_ID     = A.ITEM_ID
                                                    AND XF.VALID_YN    = 'Y'
                                                  ) XE
                                          WHERE ROWNUM = 1)) AS SUI_DEPT_ID
                 , (SELECT XG.DEPT_NAME_KO
                      FROM SCM_MST_SSO_DEPT_INFO XG
                     WHERE XG.DEPT_ID  = (SELECT XH.DEPT_ID
                                            FROM SCM_MST_SSO_USER_INFO XH
                                           WHERE UPPER(XH.USER_ID) = (SELECT UPPER(XI.OWNER)
                                                                 FROM (SELECT XJ.OWNER
                                                                         FROM SCM_MST_SITE_ITEM XJ
                                                                        WHERE XJ.DIVISION_ID = A.DIVISION_ID
                                                                          AND XJ.SCM_SITE_ID = NVL(C3.SEGMENT4, A.TO_SCM_SITE_ID)
                                                                          AND XJ.ITEM_ID     = A.ITEM_ID
                                                                          AND XJ.VALID_YN    = 'Y'
                                                                        ) XI
                                                                WHERE ROWNUM = 1))
                       AND XG.VALID_YN = 'Y') AS SDI_DEPT_NAME_KO
                 , C4.ATTRIBUTE1                                     AS LMD_ATTRIBUTE1
                 , C4.ATTRIBUTE2                                     AS LMD_ATTRIBUTE2
                 , D.SITE_DESCRIPTION                                AS SMS_SITE_DESCRIPTION
                 , A.EXFACTORY_DATE                                  AS YYYYMMDD
                 , A.EXFACTORY_QTY                                   AS QTY
                 , A.ITEM_ID
              FROM SCM_DNM_EXFACTORY_RESULT      A
                 , SCP_MST_FINAL_ITEM            C
                 , SCM_MST_SITE                  C1
                 , SCM_ADM_LOOKUP_MASTER_DETAIL  C3
                 , SCM_ADM_LOOKUP_MASTER_DETAIL  C4
                 , SCM_MST_SITE                  D
             /* SCP 대상 ITEM만 */
             WHERE C.ITEM_ID           = A.ITEM_ID
               AND C.DIVISION_ID       = A.DIVISION_ID
               AND C1.SCM_SITE_ID      = A.FROM_SCM_SITE_ID
               AND C1.DIVISION_ID      = A.DIVISION_ID
               /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
               AND C3.LOOKUP_TYPE(+)   = 'SHIP_RESULT_TO_SITE_MAPPING'
               AND C3.SEGMENT1(+)      = A.DIVISION_ID
               AND C3.SEGMENT2(+)      = A.SOLDTO_CODE
               AND C3.SEGMENT3(+)      = A.SHIPTO_CODE
               AND C4.SEGMENT1(+)      = A.FROM_SCM_SITE_ID
               AND C4.SEGMENT2(+)      = NVL(C3.SEGMENT4, A.TO_SCM_SITE_ID)
               AND C4.SEGMENT3(+)      = A.ITEM_ID
               AND C4.LOOKUP_TYPE(+)   = 'SHIPMENT_REPORT_LOOKUP'
               AND D.DIVISION_ID(+)    = A.DIVISION_ID
               AND D.SCM_SITE_ID(+)    = A.FROM_SCM_SITE_ID
               AND D.OSP_YN(+)         = 'Y'
               AND D.VALID_YN(+)       = 'Y'
               /* D90: DO삭제 , D10:DO생성 */
               AND NVL(A.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
               AND NVL(A.CONFIRM_ID, '@') NOT LIKE 'C%'
               /* 상품창고제외 */
               AND A.STORAGE_ID NOT IN ('6000', '799A')
               /* 사외 창고 제외 LOOKUP 관리 */
               AND A.STORAGE_ID NOT IN (SELECT SEGMENT1
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                         WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                           AND VALID_YN    = 'Y')
               /* ERP오더타입 제외 LOOKUP 관리 */
               AND A.ORDER_TYPE_CODE NOT IN (SELECT SEGMENT1
                                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                              WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_ERP_ORDER_TYPE'
                                                AND VALID_YN    = 'Y')
               AND A.DIVISION_ID       = V_DIVISION_ID
               AND C.OPERATION_GROUP   = V_BIZ_TYPE
               AND (TRIM(V_FROMSITE) IS NULL
                OR  UPPER(V_FROMSITE) = 'ALL'                        /* 조회조건 ALL 은 조건 없음 */
                OR  A.FROM_SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE)
                                             FROM TABLE(STRING_SPLIT(V_FROMSITE, ','))))
               AND (TRIM(V_CELL_TYPE_GR) IS NULL
                OR  UPPER(V_CELL_TYPE_GR) = 'ALL'                    /* 조회조건 ALL 은 조건 없음 */
                OR  C.CELL_TYPE_GROUP_CODE IN (SELECT UPPER(COLUMN_VALUE)
                                                 FROM TABLE(STRING_SPLIT(V_CELL_TYPE_GR, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR  UPPER(V_ITEM_ID) = 'ALL'                         /* 조회조건 ALL 은 조건 없음 */
                OR  A.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND A.EXFACTORY_DATE   >= V_FROM_RESULT
               AND A.EXFACTORY_DATE    < V_TO_RESULT) IA
     WHERE (TRIM(V_TEAM_ID) IS NULL
        OR  UPPER(V_TEAM_ID) = 'ALL'                                 /* 조회조건 ALL 은 조건 없음 */
        OR  IA.SUI_DEPT_ID IN (SELECT UPPER(COLUMN_VALUE)
                                 FROM TABLE(STRING_SPLIT(V_TEAM_ID, ',')))
        OR  IA.LMD_ATTRIBUTE1 IN (SELECT UPPER(COLUMN_VALUE)
                                    FROM TABLE(STRING_SPLIT(V_TEAM_ID, ','))))
     GROUP BY IA.DIVISION_ID
            , IA.SITE_ID
            , IA.ITEM_ID
            , NVL(IA.SUI_DEPT_ID, IA.LMD_ATTRIBUTE1)
            , IA.SDI_DEPT_NAME_KO
            , IA.LMD_ATTRIBUTE2
            , IA.SMS_SITE_DESCRIPTION
            , IA.YYYYMMDD
            , IA.SITE_NAME
            , IA.EXTRA_SPEC
            , IA.NICK_NAME;

    /* 실적 합계 */
    INSERT INTO GT_SCP0055_RESULT_TOTAL
                ( DIVISION_ID, SITE_ID, SITE_NAME, EXTRA_SPEC, NICK_NAME
                , DEPT_ID, DEPT_NAME, YYYYMMDD, QTY, PLAN_FROM )
    SELECT A.DIVISION_ID
         , A.SITE_ID
         , A.SITE_NAME
         , A.EXTRA_SPEC
         , A.NICK_NAME
         , A.DEPT_ID
         , A.DEPT_NAME
         , A.YYYYMMDD
         , SUM(A.QTY)                                               AS QTY
         , 'RESULT_TOTAL'                                           AS PLAN_FROM
      FROM GT_SCP0055_RESULT A
     WHERE (TRIM(V_NICKNAME) IS NULL
        OR  UPPER(V_NICKNAME) = 'ALL'                               /* 조회조건 ALL 은 조건 없음 */
        OR  A.NICK_NAME IN (SELECT UPPER(COLUMN_VALUE)
                              FROM TABLE(STRING_SPLIT(V_NICKNAME, ','))))
     GROUP BY A.DIVISION_ID
            , A.NICK_NAME
            , A.SITE_ID
            , A.SITE_NAME
            , A.EXTRA_SPEC
            , A.DEPT_ID
            , A.DEPT_NAME
            , A.YYYYMMDD;

    /* 출력 결과 1 : 계획 데이터 */
    OPEN O_RC1 FOR
        SELECT DIVISION_ID
             , SITE_ID
             , SITE_NAME
             , EXTRA_SPEC
             , NICK_NAME
             , DEPT_ID
             , DEPT_NAME
             , YYYYMMDD
             , QTY
             , PLAN_FROM
          FROM GT_SCP0055_PLAN_TOTAL
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 묶은 열쇠 순서와 같게 고정 */
         ORDER BY FN_ASIS_SORT_KEY(DIVISION_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(NICK_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(SITE_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(SITE_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(EXTRA_SPEC)  NULLS FIRST
                , FN_ASIS_SORT_KEY(DEPT_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(DEPT_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(YYYYMMDD)    NULLS FIRST;

    /* 출력 결과 2 : 그리드 생성용 데이터 */
    OPEN O_RC2 FOR
        SELECT IA.DIVISION_ID
             , IA.SITE_ID
             , IA.SITE_NAME
             , IA.EXTRA_SPEC
             , IA.NICK_NAME
             , IA.DEPT_ID
             , IA.DEPT_NAME
          FROM (SELECT DISTINCT DIVISION_ID
                     , SITE_ID
                     , SITE_NAME
                     , EXTRA_SPEC
                     , NICK_NAME
                     , DEPT_ID
                     , DEPT_NAME
                  FROM GT_SCP0055_PLAN_TOTAL
                UNION ALL
                SELECT DISTINCT DIVISION_ID
                     , SITE_ID
                     , SITE_NAME
                     , EXTRA_SPEC
                     , NICK_NAME
                     , DEPT_ID
                     , DEPT_NAME
                  FROM GT_SCP0055_RESULT_TOTAL) IA
         /* 원문은 두 벌을 이어 붙인 뒤 DISTINCT 한다. 순서가 정해져 있지 않아 열쇠 순서로 고정 */
         GROUP BY IA.DIVISION_ID
                , IA.SITE_ID
                , IA.SITE_NAME
                , IA.EXTRA_SPEC
                , IA.NICK_NAME
                , IA.DEPT_ID
                , IA.DEPT_NAME
         ORDER BY FN_ASIS_SORT_KEY(IA.DIVISION_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(IA.SITE_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(IA.EXTRA_SPEC)  NULLS FIRST
                , FN_ASIS_SORT_KEY(IA.NICK_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(IA.DEPT_ID)     NULLS FIRST;

    /* 출력 결과 3 : 실적 데이터 */
    OPEN O_RC3 FOR
        SELECT DIVISION_ID
             , SITE_ID
             , SITE_NAME
             , EXTRA_SPEC
             , NICK_NAME
             , DEPT_ID
             , DEPT_NAME
             , YYYYMMDD
             , QTY
             , PLAN_FROM
          FROM GT_SCP0055_RESULT_TOTAL
         /* 원문에 정렬이 없어 화면 순서가 흔들린다 — 묶은 열쇠 순서와 같게 고정 */
         ORDER BY FN_ASIS_SORT_KEY(DIVISION_ID) NULLS FIRST
                , FN_ASIS_SORT_KEY(NICK_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(SITE_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(SITE_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(EXTRA_SPEC)  NULLS FIRST
                , FN_ASIS_SORT_KEY(DEPT_ID)     NULLS FIRST
                , FN_ASIS_SORT_KEY(DEPT_NAME)   NULLS FIRST
                , FN_ASIS_SORT_KEY(YYYYMMDD)    NULLS FIRST;

    /* 출력 결과 4 : 검색 Plan Type, Seq */
    OPEN O_RC4 FOR
        SELECT V_PLAN_TYPE  AS V_PLAN_TYPE
             , V_SEQ        AS V_SEQ
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0055_GET_SHIPMENT_ALLO_PLAN;

/****************************************************************************************************/
/* Program ID  : P_SCP0055_GET_SHIPMENT_ALLO_NOTE                                                   */
/* Description : 메모 조회                                                                          */
/****************************************************************************************************/
PROCEDURE P_SCP0055_GET_SHIPMENT_ALLO_NOTE
(
    P_SITE_ID               IN  CLOB
  , P_DEPT_ID               IN  CLOB
  , P_NICK_NAME             IN  CLOB
  , P_PLAN_DATE             IN  CLOB
  , P_GAP_DATE              IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 (조건은 늘 'ALL') */
  , P_USER_ID               IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , O_RC1                   OUT SYS_REFCURSOR
  , O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
IS
    V_SITE_ID               VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_SITE_ID,   1, 4000));
    V_DEPT_ID               VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DEPT_ID,   1, 4000));
    V_NICK_NAME             VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_NICK_NAME, 1, 4000));
    /* 원문이 계획일자를 NVARCHAR(8) 로 받아 8자에서 자른다 */
    V_PLAN_DATE             VARCHAR2(8 CHAR)    := TO_CHAR(SUBSTR(P_PLAN_DATE, 1, 8));
BEGIN

    OPEN O_RC1 FOR
        SELECT NOTE
          FROM SCM_SHIP_ALLO_REPORT
         WHERE SITE_ID   = V_SITE_ID
           AND DEPT_ID   = V_DEPT_ID
           AND NICK_NAME = V_NICK_NAME
           AND PLAN_DATE = V_PLAN_DATE
           AND GAP_DATE  = 'ALL'
           AND VALID     = 'Y';

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

END P_SCP0055_GET_SHIPMENT_ALLO_NOTE;

/****************************************************************************************************/
/* Program ID  : P_SCP0055_SAVE_SHIPMENT_ALLO_PLAN                                                  */
/* Description : 메모 저장 — 기존 행을 사용 안 함으로 두고 새 행을 넣는다                          */
/****************************************************************************************************/
PROCEDURE P_SCP0055_SAVE_SHIPMENT_ALLO_PLAN
(
    P_SITE_ID               IN  CLOB
  , P_NICK_NAME             IN  CLOB
  , P_DEPT_ID               IN  CLOB
  , P_PLAN_DATE             IN  CLOB
  , P_GAP_DATE              IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 (늘 'ALL' 로 넣는다) */
  , P_NOTE                  IN  CLOB
  , P_PROGRAM_ID            IN  CLOB      /* 원문도 받기만 하고 쓰지 않는다 */
  , P_USER_ID               IN  CLOB
  , O_RC1                   OUT SYS_REFCURSOR
  , O_RESULT_CURSOR         OUT SYS_REFCURSOR
)
IS
    /* 화면이 고친 줄 여러 건을 한 번에 보낸다(칸마다 ^ 로 이음) — 옛 화면은 줄마다 한 번씩 불렀다. */ /* AJS 20261007 화면검증 */
    /* 줄마다 나눠 원문과 같은 처리를 되풀이한다. 원래 선언(첫 값 바로 대입)은 아래 주석으로 남긴다 */  /* AJS 20261007 화면검증 */
    /* V_SITE_ID   VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_SITE_ID,   1, 4000)); */
    /* V_NICK_NAME VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_NICK_NAME, 1, 4000)); */
    /* V_DEPT_ID   VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_DEPT_ID,   1, 4000)); */
    /* V_PLAN_DATE VARCHAR2(8 CHAR)    := TO_CHAR(SUBSTR(P_PLAN_DATE, 1, 8));    */
    /* V_NOTE      VARCHAR2(4000 CHAR) := TO_CHAR(SUBSTR(P_NOTE,      1, 4000)); */
    /* V_USER_ID   VARCHAR2(30 CHAR)   := TO_CHAR(SUBSTR(P_USER_ID,   1, 30));   */
    C_DELIMITER             CONSTANT VARCHAR2(1 CHAR) := '^';                                        /* AJS 20261007 화면검증 */
    N_MAX_LOOP_CNT          NUMBER(10) := 0;                                                         /* AJS 20261007 화면검증 */
    N_LOOP_CNT              NUMBER(10) := 0;                                                         /* AJS 20261007 화면검증 */
    V_SITE_ID               VARCHAR2(4000 CHAR);                                                     /* AJS 20261007 화면검증 */
    V_NICK_NAME             VARCHAR2(4000 CHAR);                                                     /* AJS 20261007 화면검증 */
    V_DEPT_ID               VARCHAR2(4000 CHAR);                                                     /* AJS 20261007 화면검증 */
    /* 원문이 계획일자를 NVARCHAR(8) 로 받아 8자에서 자른다 */                                                        /* AJS 20261007 화면검증 */
    V_PLAN_DATE             VARCHAR2(8 CHAR);                                                        /* AJS 20261007 화면검증 */
    V_NOTE                  VARCHAR2(4000 CHAR);                                                     /* AJS 20261007 화면검증 */
    /* 원문이 사용자를 NVARCHAR(30) 으로 받아 30자에서 자른다 */                                                      /* AJS 20261007 화면검증 */
    V_USER_ID               VARCHAR2(30 CHAR);                                                       /* AJS 20261007 화면검증 */

    /* ★원장 열쇠에 최초등록일시가 들어 있다. AS-IS 는 1,000분의 1초까지 남아 같은 초에 두 번
          저장해도 열쇠가 갈리지만, 기준 데이터베이스는 초까지만 남아 열쇠가 겹쳐 저장이 막힌다.
          이미 있는 최종 시각보다 한 초 뒤를 확보해 원문과 같이 저장이 되게 한다 */
    V_LAST_INSDTTM          DATE;
    V_INSDTTM               DATE;

    V_SQLERRM               VARCHAR2(4000 CHAR);
BEGIN

    IF P_SITE_ID IS NOT NULL                                                                         /* AJS 20261007 화면검증 */
    THEN                                                                                             /* AJS 20261007 화면검증 */
        N_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_SITE_ID, C_DELIMITER));                        /* AJS 20261007 화면검증 */
    END IF;                                                                                          /* AJS 20261007 화면검증 */
                                                                                                     /* AJS 20261007 화면검증 */
    WHILE N_LOOP_CNT < N_MAX_LOOP_CNT                                                                /* AJS 20261007 화면검증 */
    LOOP                                                                                             /* AJS 20261007 화면검증 */
                                                                                                     /* AJS 20261007 화면검증 */
    N_LOOP_CNT  := N_LOOP_CNT + 1;                                                                   /* AJS 20261007 화면검증 */
    V_SITE_ID   := SUBSTR(SCM_ARR_SPL_VAL(P_SITE_ID,   C_DELIMITER, N_LOOP_CNT), 1, 4000);           /* AJS 20261007 화면검증 */
    V_NICK_NAME := SUBSTR(SCM_ARR_SPL_VAL(P_NICK_NAME, C_DELIMITER, N_LOOP_CNT), 1, 4000);           /* AJS 20261007 화면검증 */
    V_DEPT_ID   := SUBSTR(SCM_ARR_SPL_VAL(P_DEPT_ID,   C_DELIMITER, N_LOOP_CNT), 1, 4000);           /* AJS 20261007 화면검증 */
    V_PLAN_DATE := SUBSTR(SCM_ARR_SPL_VAL(P_PLAN_DATE, C_DELIMITER, N_LOOP_CNT), 1, 8);              /* AJS 20261007 화면검증 */
    V_NOTE      := SUBSTR(SCM_ARR_SPL_VAL(P_NOTE,      C_DELIMITER, N_LOOP_CNT), 1, 4000);           /* AJS 20261007 화면검증 */
    V_USER_ID   := SUBSTR(SCM_ARR_SPL_VAL(P_USER_ID,   C_DELIMITER, N_LOOP_CNT), 1, 30);             /* AJS 20261007 화면검증 */

    SELECT NVL(MAX(INSDTTM), SYSDATE - 1)
      INTO V_LAST_INSDTTM
      FROM SCM_SHIP_ALLO_REPORT
     WHERE SITE_ID   = V_SITE_ID
       AND NICK_NAME = V_NICK_NAME
       AND DEPT_ID   = V_DEPT_ID
       AND PLAN_DATE = V_PLAN_DATE
       AND GAP_DATE  = 'ALL';

    V_INSDTTM := GREATEST(SYSDATE, V_LAST_INSDTTM + (1 / 86400));

    /* 기존 정보 백업 */
    UPDATE SCM_SHIP_ALLO_REPORT
       SET VALID     = 'N'
         , UPDDTTM   = SYSDATE
         , UPDUSER   = V_USER_ID
     WHERE SITE_ID   = V_SITE_ID
       AND NICK_NAME = V_NICK_NAME
       AND DEPT_ID   = V_DEPT_ID
       AND PLAN_DATE = V_PLAN_DATE
       AND GAP_DATE  = 'ALL';

    /* 신규 정보 생성 */
    INSERT INTO SCM_SHIP_ALLO_REPORT
                (
                  SITE_ID
                , NICK_NAME
                , DEPT_ID
                , PLAN_DATE
                , GAP_DATE
                , NOTE
                , VALID
                , INSDTTM
                , INSUSER
                )
         VALUES (
                  V_SITE_ID
                , V_NICK_NAME
                , V_DEPT_ID
                , V_PLAN_DATE
                , 'ALL'
                , V_NOTE
                , 'Y'
                , V_INSDTTM
                , V_USER_ID
                );

    END LOOP;                                                                                        /* AJS 20261007 화면검증 */

    COMMIT;

    OPEN O_RC1 FOR
        SELECT 'S'              AS RESULT_CODE
             /* , 1    AS RESULT_CNT */
             , N_MAX_LOOP_CNT   AS RESULT_CNT                                                    /* AJS 20261007 화면검증 */
          FROM DUAL;

    OPEN O_RESULT_CURSOR FOR
        SELECT '0'          AS RESULT_CODE
             , 'SUCCESS'    AS RESULT_MESSAGE
          FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        V_SQLERRM := SQLERRM;

        ROLLBACK;

        OPEN O_RC1 FOR
            SELECT 'F'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_CNT
              FROM DUAL;

        OPEN O_RESULT_CURSOR FOR
            SELECT '1'                          AS RESULT_CODE
                 , SUBSTR(V_SQLERRM, 1, 4000)   AS RESULT_MESSAGE
              FROM DUAL;

END P_SCP0055_SAVE_SHIPMENT_ALLO_PLAN;

END PKG_SCP0055;
/
SHOW ERRORS PACKAGE BODY PKG_SCP0055
-- ##### END PACKAGE BODY PKG_SCP0055

-- ##### START PACKAGE BODY PKG_SCP0098
CREATE OR REPLACE PACKAGE BODY PKG_SCP0098 IS

/*==================================================================================================
 * Program ID   : [SCP0098_COPY_MONTH_WEEK]
 * Description  : 전 주차 & 전 월 카테고리 정보 복사
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2024/04/01   LJS			    init
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *==================================================================================================*/
    PROCEDURE P_COPY_MONTH_WEEK (
        P_USER_ID       IN  VARCHAR2 DEFAULT '-'
      , P_DAY_TYPE      IN  VARCHAR2 DEFAULT '-'
      , P_DEBUG_MODE    IN  VARCHAR2 DEFAULT '-'
      , O_RC            OUT SYS_REFCURSOR
      , O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    IS
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0098_COPY_MONTH_WEEK';
        V_LOG_TYPE          VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

        /* 예외처리 변수 설정 */
        V_ERR_CODE          NUMBER(10);
        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);

        /* 실행시간 확인용 */
        V_START_TIME        DATE := SYSDATE;
        V_EXEC_TIME         VARCHAR2(10 CHAR) := '';
        V_EXEC_SEC          NUMBER(10) := 0;

        V_USERID            VARCHAR2(4000 CHAR);
        V_TYPE              VARCHAR2(4000 CHAR);
        V_DEBUG             VARCHAR2(4000 CHAR);

        V_CURWEEK           VARCHAR2(24 CHAR);  /* 금주 */
        V_BEFWEEK           VARCHAR2(24 CHAR);  /* 전주 */
        V_CURMONTH          VARCHAR2(24 CHAR);  /* 금월 */
        V_BEFMONTH          VARCHAR2(24 CHAR);  /* 전월 */
    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_USERID := P_USER_ID;
        V_TYPE   := P_DAY_TYPE;
        V_DEBUG  := P_DEBUG_MODE;

        BEGIN
            SELECT ISO_YYYYWW
              INTO V_CURWEEK
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND ROWNUM = 1
            ;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_CURWEEK := NULL;
        END;

        BEGIN
            SELECT ISO_YYYYWW
              INTO V_BEFWEEK
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE - 7, 'YYYYMMDD')
               AND ROWNUM = 1
            ;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_BEFWEEK := NULL;
        END;

        BEGIN
            SELECT BASIS_YYYYMM
              INTO V_CURMONTH
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE, 'YYYYMMDD')
               AND ROWNUM = 1
            ;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_CURMONTH := NULL;
        END;

        BEGIN
            SELECT BASIS_YYYYMM
              INTO V_BEFMONTH
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD = TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMMDD')
               AND ROWNUM = 1
            ;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_BEFMONTH := NULL;
        END;

        IF V_TYPE = 'WEEK' THEN

            /* 주 복사(실제는 일단위) : 전주 -> 당주 */
            /* AS-IS MERGE 를 UPDATE + INSERT 로 나눈 것 (온라인 SQL 은 MERGE 를 쓰지 않는다) */
            UPDATE SCP_MST_CAPA_WORK A
               SET ( A.VALUE
                   , A.LAST_UPDATED_BY
                   , A.LAST_UPDATE_DATE )
                   = ( SELECT SA.VALUE
                            , 'COPY_WEEK_' || V_USERID
                            , SYSDATE
                         FROM SCP_MST_CAPA_WORK SA
                            , SCM_SYS_CALENDAR_M SB
                        WHERE SA.YYYYMMDD     = SB.BASIS_YYYYMMDD
                          AND SA.DIVISION_ID  = A.DIVISION_ID
                          AND SA.PLANT_ID     = A.PLANT_ID
                          AND SA.FACTORY_ID   = A.FACTORY_ID
                          AND SA.OPERATION_ID = A.OPERATION_ID
                          AND SA.LINE_ID      = A.LINE_ID
                          AND SA.MEASURE      = A.MEASURE
                          AND TO_CHAR(SB.BASIS_DATE + 7, 'YYYYMMDD') = A.YYYYMMDD
                          AND SB.ISO_YYYYWW   = V_BEFWEEK
                          AND SA.MEASURE      IN ( 'DAILY_CAPA', 'LOAD_RATE', 'NO_WORK', 'RAMP_UP' ) )
             WHERE EXISTS ( SELECT 1
                              FROM SCP_MST_CAPA_WORK SA
                                 , SCM_SYS_CALENDAR_M SB
                             WHERE SA.YYYYMMDD     = SB.BASIS_YYYYMMDD
                               AND SA.DIVISION_ID  = A.DIVISION_ID
                               AND SA.PLANT_ID     = A.PLANT_ID
                               AND SA.FACTORY_ID   = A.FACTORY_ID
                               AND SA.OPERATION_ID = A.OPERATION_ID
                               AND SA.LINE_ID      = A.LINE_ID
                               AND SA.MEASURE      = A.MEASURE
                               AND TO_CHAR(SB.BASIS_DATE + 7, 'YYYYMMDD') = A.YYYYMMDD
                               AND SB.ISO_YYYYWW   = V_BEFWEEK
                               AND SA.MEASURE      IN ( 'DAILY_CAPA', 'LOAD_RATE', 'NO_WORK', 'RAMP_UP' ) )
            ;

            INSERT INTO SCP_MST_CAPA_WORK
                 ( DIVISION_ID, PLANT_ID, FACTORY_ID, OPERATION_ID, LINE_ID
                 , MEASURE, YYYYMMDD, VALUE
                 , CREATED_BY, CREATION_DATE
                 , LAST_UPDATED_BY, LAST_UPDATE_DATE
                 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                 , PROD_READY_RATE
                 )
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.MEASURE
                 , TO_CHAR(B.BASIS_DATE + 7, 'YYYYMMDD') AS YYYYMMDD
                 , A.VALUE
                 , 'COPY_WEEK_' || V_USERID              AS CREATED_BY
                 , SYSDATE                               AS CREATION_DATE
                 , 'COPY_WEEK_' || V_USERID              AS LAST_UPDATED_BY
                 , SYSDATE                               AS LAST_UPDATE_DATE
                 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
                 , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
                 , A.PROD_READY_RATE
              FROM SCP_MST_CAPA_WORK A
                 , SCM_SYS_CALENDAR_M B
             WHERE A.YYYYMMDD   = B.BASIS_YYYYMMDD
               AND NOT EXISTS ( SELECT 1
                                  FROM SCP_MST_CAPA_WORK SA
                                 WHERE SA.DIVISION_ID  = A.DIVISION_ID
                                   AND SA.PLANT_ID     = A.PLANT_ID
                                   AND SA.FACTORY_ID   = A.FACTORY_ID
                                   AND SA.OPERATION_ID = A.OPERATION_ID
                                   AND SA.LINE_ID      = A.LINE_ID
                                   AND SA.MEASURE      = A.MEASURE
                                   AND SA.YYYYMMDD     = TO_CHAR(B.BASIS_DATE + 7, 'YYYYMMDD') )
               AND B.ISO_YYYYWW = V_BEFWEEK
               AND A.MEASURE    IN ( 'DAILY_CAPA', 'LOAD_RATE', 'NO_WORK', 'RAMP_UP' )
            ;

        ELSE /* @v_type = 'MONTH' */

            /* 월복사 : 전월->당월 */
            UPDATE SCP_MST_CAPA A
               SET ( A.VALUE
                   , A.LAST_UPDATED_BY
                   , A.LAST_UPDATE_DATE )
                   = ( SELECT SA.VALUE
                            , 'COPY_MONTH_' || V_USERID
                            , SYSDATE
                         FROM SCP_MST_CAPA SA
                        WHERE SA.DIVISION_ID  = A.DIVISION_ID
                          AND SA.PLANT_ID     = A.PLANT_ID
                          AND SA.FACTORY_ID   = A.FACTORY_ID
                          AND SA.OPERATION_ID = A.OPERATION_ID
                          AND SA.LINE_ID      = A.LINE_ID
                          AND SA.ITEM_ID      = A.ITEM_ID
                          AND SA.YYYYMM       = V_BEFMONTH
                          AND A.YYYYMM        = V_CURMONTH )
             WHERE EXISTS ( SELECT 1
                              FROM SCP_MST_CAPA SA
                             WHERE SA.DIVISION_ID  = A.DIVISION_ID
                               AND SA.PLANT_ID     = A.PLANT_ID
                               AND SA.FACTORY_ID   = A.FACTORY_ID
                               AND SA.OPERATION_ID = A.OPERATION_ID
                               AND SA.LINE_ID      = A.LINE_ID
                               AND SA.ITEM_ID      = A.ITEM_ID
                               AND SA.YYYYMM       = V_BEFMONTH
                               AND A.YYYYMM        = V_CURMONTH )
            ;

            INSERT INTO SCP_MST_CAPA
                 ( DIVISION_ID, PLANT_ID, FACTORY_ID, OPERATION_ID
                 , LINE_ID, ITEM_ID
                 , YYYYMM, VALUE
                 , CREATED_BY, CREATION_DATE
                 , LAST_UPDATED_BY, LAST_UPDATE_DATE
                 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                 )
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.FACTORY_ID
                 , A.OPERATION_ID
                 , A.LINE_ID
                 , A.ITEM_ID
                 , V_CURMONTH                             AS YYYYMM
                 , A.VALUE
                 , 'COPY_MONTH_' || V_USERID              AS CREATED_BY     /* user_id */
                 , SYSDATE                                AS CREATION_DATE
                 , 'COPY_MONTH_' || V_USERID              AS LAST_UPDATED_BY /* user_id */
                 , SYSDATE                                AS LAST_UPDATE_DATE
                 , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
                 , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
              FROM SCP_MST_CAPA A
             WHERE NOT EXISTS ( SELECT 1
                                  FROM SCP_MST_CAPA SA
                                 WHERE SA.DIVISION_ID  = A.DIVISION_ID
                                   AND SA.PLANT_ID     = A.PLANT_ID
                                   AND SA.FACTORY_ID   = A.FACTORY_ID
                                   AND SA.OPERATION_ID = A.OPERATION_ID
                                   AND SA.LINE_ID      = A.LINE_ID
                                   AND SA.ITEM_ID      = A.ITEM_ID
                                   AND SA.YYYYMM       = V_CURMONTH )
               AND A.YYYYMM = V_BEFMONTH
            ;

        END IF;

        /* 임시 운영반영시에 주석처리 할것. */
        V_EXEC_SEC  := ROUND((SYSDATE - V_START_TIME) * 86400);
        V_EXEC_TIME := LPAD(TO_CHAR(TRUNC(V_EXEC_SEC / 60)), 2, '0') || ':' || LPAD(TO_CHAR(MOD(V_EXEC_SEC, 60)), 2, '0');

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '[' || V_EXEC_TIME || ']';
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC FOR
            SELECT 'S' AS RESULT_CODE
                 , 1   AS RESULT_CNT
              FROM DUAL
        ;

        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS ERR_CODE
                 , NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 0
        ;

    EXCEPTION
        WHEN OTHERS THEN
            /* AS-IS 는 CATCH 에서 입력 데이타 롤백을 주석으로 막아 두었다. 같은 동작으로 둔다. */
            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            INSERT INTO SCM_SYS_LOG_BATCH ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL, SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME )
            ;

            OPEN O_RC FOR
                SELECT 'S' AS RESULT_CODE
                     , 1   AS RESULT_CNT
                  FROM DUAL
                 WHERE 1 = 0
            ;

            /* 에러 메시지, 에러 데이터  반환 */
            OPEN O_RESULT_CURSOR FOR
                SELECT V_ERR_CODE    AS ERR_CODE
                     , V_ERR_MESSAGE AS ERR_MESSAGE
                  FROM DUAL
            ;
    END P_COPY_MONTH_WEEK;

/*==================================================================================================
 * Program ID   : SCP0098_GET_CAPA_MobilityIT
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/07/19   khj79          최초작성 - SCP0049_GET_CAPA 참조 => SCP0013 ,Production Plan Line 참조
 * 2020/08/21   khj79          최초작성 - SCP0049_GET_CAPA 참조 => Line Assign / Operation / LOCATION_GROUP_ROUTE
 * 2023/08/23   vadabi3        PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 PIVOT
 * 2023/09/06   vadabi3        PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 Version 2 - 조회 대상 개선
 * 2023/12/07   vadabi3        PJ20230691R  LGES SCM 역량 강화 위한 SCP 개선과제 속도개선
 * 2023/02/06   vadabi3        E20240207-001060 소형 CAPA 엑셀 다운로드 및 Plant 검색조건 수정 - plant site 조건 검색 미적용 수정
 * 2024/04/01   leejsthira2    오창, 월요일 조건으로 무조건 생산준비율 반영
 * 2025/08/01   hrkim		   PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 완성 공정 하드코딩 변경
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          [속도2차] 생산준비율 반영 갱신을 행별 공장 집계 대신 값 조회로 · 월 칸(M_) 행별 하위질의를 한 번 집계해 붙임
 *==================================================================================================*/
    PROCEDURE P_GET_CAPA_MOBILITYIT (
        P_TODAY_YYYYMMDD    IN  VARCHAR2
      , P_FROM_YYYYMMDD     IN  VARCHAR2
      , P_TO_YYYYMMDD       IN  VARCHAR2
      , P_DIVISION_ID       IN  VARCHAR2
      , P_PLANT_ID          IN  VARCHAR2
      , P_LINE_ID           IN  VARCHAR2
      , P_OPERATION_ID      IN  VARCHAR2
      , P_MODEL_ID          IN  VARCHAR2
      , P_ITEM_ID           IN  VARCHAR2
      , P_NICK_NAME         IN  VARCHAR2
      , P_BUCKET            IN  VARCHAR2
      , P_USER_ID           IN  VARCHAR2
      , P_DEBUG_MODE        IN  VARCHAR2
      , O_RC                OUT SYS_REFCURSOR
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        /* Declare */
        V_PROGRAM_ID            VARCHAR2(400 CHAR) := 'SCP0098';
        V_SHEET_NAME            VARCHAR2(600 CHAR) := 'CAPA_SMALL';
        V_TODAY_YYYYMM          VARCHAR2(6 CHAR);
        V_PLANT_ID              VARCHAR2(4000 CHAR);

        /* 날짜 조건용 변수 설정 */
        V_START_MONTH           VARCHAR2(6 CHAR);   /* 시작 월(현재월 +1 년) */
        V_END_MONTH             VARCHAR2(6 CHAR);   /* 마지막 월 */

        V_TODAY_YYYYMM_FIRSTDAY VARCHAR2(8 CHAR);

        /* 쿼리 실행용 변수 */
        V_MEXEC                 CLOB;
        V_MQRY_FIELD            CLOB;   /* 피벗 칸 목록 (D_) */
        V_MQRY_FIELD_LAST       CLOB;   /* 최종 표기 변환 (D_) */
        V_MQRY_FIELD_PRODREADY  CLOB;   /* 월 칸 (M_) */
        V_PIVOT_AGG             CLOB;   /* 피벗 집계식 (D_) */
        V_OEE_PIVOT             CLOB;   /* 월 칸 집계식 (M_) */ /* AJS 20261007 속도 */

        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        /* GTT 초기화 (TRUNCATE 금지) */
        DELETE FROM GT_SCP0098_ITEM_LIST;
        DELETE FROM GT_SCP0098_ITEM_LIST_YYYYMM;
        DELETE FROM GT_SCP0098_STD_LINE_DATA;
        DELETE FROM GT_SCP0098_STD_ITEM_DATA;
        DELETE FROM GT_SCP0098_TARGET_MEASURE;
        DELETE FROM GT_SCP0098_LINE_MEASURE;
        DELETE FROM GT_SCP0098_LINE_MEAS_DIST;
        DELETE FROM GT_SCP0098_ITEM_MEASURE;
        DELETE FROM GT_SCP0098_PROD_READY_RATE;
        DELETE FROM GT_SCP0098_MEAS_WORK;
        DELETE FROM GT_SCP0098_DAILYCAPA_DAY;
        DELETE FROM GT_SCP0098_ITEM_LIST_TERM;
        DELETE FROM GT_SCP0098_MEAS_CAPA;
        DELETE FROM GT_SCP0098_MEAS_CAPA_NOWORK;
        DELETE FROM GT_SCP0098_OEE_TERM;
        DELETE FROM GT_SCP0098_CAPA_YMD;
        DELETE FROM GT_SCP0098_CAPA_YMD_CALC;

        V_TODAY_YYYYMM := SUBSTR(P_TODAY_YYYYMMDD, 1, 6);

        /* IF @p_plant_id = 'ALL' SET @p_plant_id = null; */
        IF P_PLANT_ID = 'ALL' THEN
            V_PLANT_ID := NULL;
        ELSE
            V_PLANT_ID := P_PLANT_ID;
        END IF;

        /* 조회 날짜 설정 */
        V_START_MONTH := SUBSTR(P_FROM_YYYYMMDD, 1, 6); /* 현재일 */
        V_END_MONTH   := SUBSTR(P_TO_YYYYMMDD  , 1, 6); /* 조회일자가 기준을 넘을 경우 Y+1 으로 조회 */

        V_TODAY_YYYYMM_FIRSTDAY := V_TODAY_YYYYMM || '01';

        /* #TMP_SCP0098_ITEM_LIST_ALL) LOCATION_GROUP_ROUTE */
        /* [PJ20257329] 2025.08.01 Cell 완성 공정 하드코딩 변경 — 테이블 변수 대신 IN 서브쿼리로 옮겼다 */
        INSERT INTO GT_SCP0098_ITEM_LIST
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , ITEM_CLASS
             )
        SELECT DISTINCT
               IA.DIVISION_ID
             , IA.COMPANY_ID
             , IA.SITE_ID
             , IA.PLANT_ID
             , IA.OPERATION_GROUP_ID
             , IA.FACTORY_ID
             , IA.OPERATION_ID
             , IA.LINE_ID
             , XA.ITEM_ID
             , ( SELECT MAX(SA.ITEM_CLASS)
                   FROM SCM_ITEM_M_SN SA
                  WHERE SA.COMPANY_ID  = XA.COMPANY_ID
                    AND SA.DIVISION_ID = XA.DIVISION_ID
                    AND SA.SITE_ID     = XA.SITE_ID
                    AND SA.ITEM_ID     = XA.ITEM_ID
                    AND SA.ITEM_CLASS  = 'ES1901'
                    AND SA.ACTIVE_FLAG = 'Y'
                    AND XA.PRIORITY    NOT IN ('0', '9') ) AS ITEM_CLASS
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , OPERATION_GROUP_ID
                      , FACTORY_ID
                      , OPERATION_ID
                      , LINE_ID
                   FROM SCM_LINE_HIERARCHY_V_SN
                  WHERE OPERATION_ID IN ( SELECT SEGMENT1
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                             AND SEGMENT3    = 'A'   /* 공정그룹(Cell) */
                                             AND ATTRIBUTE1  = 'Y' ) /* Final Operation */
                    AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')) ) )
                    AND ( TRIM(V_PLANT_ID)    IS NULL OR PLANT_ID || '-' || OPERATION_GROUP_ID IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(V_PLANT_ID, ',')) ) )
                    AND ( TRIM(P_LINE_ID)     IS NULL OR LINE_ID  IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_LINE_ID, ',')) ) )
               ) IA
             , ( SELECT SA.COMPANY_ID
                      , SA.DIVISION_ID
                      , SA.SITE_ID
                      , SA.PLANT_ID
                      , SA.FACTORY_ID
                      , SA.LINE_ID
                      , SA.OPERATION_ID
                      , SA.ITEM_ID
                      , SA.PRIORITY
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN SA
                  WHERE SA.MONTH   >= V_START_MONTH
                    AND SA.MONTH   <= V_END_MONTH
                    AND SA.ITEM_ID NOT LIKE 'AJR%'
                    AND SA.ITEM_ID IS NOT NULL
                    AND ( TRIM(P_ITEM_ID) IS NULL OR SA.ITEM_ID IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) ) )
               ) XA
         WHERE IA.DIVISION_ID  = XA.DIVISION_ID(+)
           AND IA.SITE_ID      = XA.SITE_ID(+)
           AND IA.PLANT_ID     = XA.PLANT_ID(+)
           AND IA.FACTORY_ID   = XA.FACTORY_ID(+)
           AND IA.LINE_ID      = XA.LINE_ID(+)
           AND IA.OPERATION_ID = XA.OPERATION_ID(+)
        ;

        /* #TMP_SCP0098_ITEM_LIST_YYYYMM */
        INSERT INTO GT_SCP0098_ITEM_LIST_YYYYMM
             ( DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             )
        SELECT A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , B.MONTH AS YYYYMM
          FROM SCM_MST_ITEM_LINE_ASSIGN_SN B
             , GT_SCP0098_ITEM_LIST A
         WHERE A.COMPANY_ID   = B.COMPANY_ID
           AND A.DIVISION_ID  = B.DIVISION_ID
           AND A.SITE_ID      = B.SITE_ID
           AND A.PLANT_ID     = B.PLANT_ID
           AND A.FACTORY_ID   = B.FACTORY_ID
           AND A.OPERATION_ID = B.OPERATION_ID
           AND A.LINE_ID      = B.LINE_ID
           AND A.ITEM_ID      = B.ITEM_ID
           AND B.MONTH        >= V_START_MONTH
           AND B.MONTH        <= V_END_MONTH
        ;

        /* #TMP_SCP0098_STD_LINE_DATA) Line List */
        INSERT INTO GT_SCP0098_STD_LINE_DATA
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , SITE_NAME
             , FACTORY_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP_NAME
             , LINE_NAME
             , OPERATION_NAME
             )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , NVL(B.SITE_NAME      , '-') AS SITE_NAME
             , NVL(B.FACTORY_NAME   , '-') AS FACTORY_NAME
             , B.OPERATION_GROUP_ID
             , NVL(B.OPERATION_GROUP, '-') AS OPERATION_GROUP_NAME
             , NVL(B.LINE_NAME      , '-') AS LINE_NAME
             , NVL(B.OPERATION_NAME , '-') AS OPERATION_NAME
          FROM GT_SCP0098_ITEM_LIST A
             , SCM_LINE_HIERARCHY_V_SN B
         WHERE A.COMPANY_ID   = B.COMPANY_ID(+)
           AND A.DIVISION_ID  = B.DIVISION_ID(+)
           AND A.SITE_ID      = B.SITE_ID(+)
           AND A.PLANT_ID     = B.PLANT_ID(+)
           AND A.FACTORY_ID   = B.FACTORY_ID(+)
           AND A.OPERATION_ID = B.OPERATION_ID(+)
           AND A.LINE_ID      = B.LINE_ID(+)
        ;

        /* #TMP_SCP0098_STD_ITEM_DATA) Item List */
        INSERT INTO GT_SCP0098_STD_ITEM_DATA
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , SITE_NAME
             , FACTORY_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP_NAME
             , LINE_NAME
             , OPERATION_NAME
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT A.DIVISION_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , NVL(B.SITE_NAME      , '-') AS SITE_NAME
             , NVL(B.FACTORY_NAME   , '-') AS FACTORY_NAME
             , B.OPERATION_GROUP_ID
             , NVL(B.OPERATION_GROUP, '-') AS OPERATION_GROUP_NAME
             , NVL(B.LINE_NAME      , '-') AS LINE_NAME
             , NVL(B.OPERATION_NAME , '-') AS OPERATION_NAME
             , A.ITEM_ID
             , NVL(FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID), '-') AS ITEM_NAME
          FROM GT_SCP0098_ITEM_LIST A
             , SCM_LINE_HIERARCHY_V_SN B
         WHERE A.COMPANY_ID   = B.COMPANY_ID(+)
           AND A.DIVISION_ID  = B.DIVISION_ID(+)
           AND A.SITE_ID      = B.SITE_ID(+)
           AND A.PLANT_ID     = B.PLANT_ID(+)
           AND A.FACTORY_ID   = B.FACTORY_ID(+)
           AND A.OPERATION_ID = B.OPERATION_ID(+)
           AND A.LINE_ID      = B.LINE_ID(+)
        ;

        /* #TARGET_MEASURES */
        INSERT INTO GT_SCP0098_TARGET_MEASURE
             ( MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             )
        SELECT IA.MEASURE_UI
             , IA.MEASURE_NAME
             , SUBSTR(IA.MEASURE_UI, 1, INSTR(IA.MEASURE_UI, '_') - 1)                              AS MEASURE_DB
             , SUBSTR(IA.MEASURE_UI, INSTR(IA.MEASURE_UI, '_') + 1, LENGTH(RTRIM(IA.MEASURE_UI)))   AS COL_DIV
             , IA.SORT_ORDER_NO
          FROM ( /* user별 설정한 조회 대상 measure */
                 SELECT UM.COLUMN_NAME       AS MEASURE_UI
                      , M.COLUMN_LABEL_NAME  AS MEASURE_NAME
                      , UM.SORT_ORDER_NO
                   FROM SCM_MST_TITLESET_USER UM
                      , SCM_MST_SHEET_MEASURE M
                  WHERE M.COLUMN_NAME = UM.COLUMN_NAME
                    AND M.PROGRAM_ID  = V_PROGRAM_ID
                    AND M.SHEET_NAME  = V_SHEET_NAME
                    AND M.VALID_YN    = 'Y'
                    AND UM.USER_ID    = P_USER_ID
                    AND UM.PROGRAM_ID = V_PROGRAM_ID
                    AND UM.SHEET_NAME = V_SHEET_NAME

                 UNION ALL
                 /* user별 설정한 measure정보가 없을 경우 default measure를 보여준다. */
                 SELECT M.COLUMN_NAME        AS MEASURE_UI
                      , M.COLUMN_LABEL_NAME  AS MEASURE_NAME
                      , M.SORT_ORDER_NO
                   FROM SCM_MST_SHEET_MEASURE M
                  WHERE M.PROGRAM_ID   = V_PROGRAM_ID
                    AND M.SHEET_NAME   = V_SHEET_NAME
                    AND M.VALID_YN     = 'Y'
                    AND M.DEFAULT_FLAG = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCM_MST_TITLESET_USER SA
                                          , SCM_MST_SHEET_MEASURE SB
                                      WHERE SB.COLUMN_NAME = SA.COLUMN_NAME
                                        AND SB.PROGRAM_ID  = V_PROGRAM_ID
                                        AND SB.SHEET_NAME  = V_SHEET_NAME
                                        AND SB.VALID_YN    = 'Y'
                                        AND SA.USER_ID     = P_USER_ID
                                        AND SA.PROGRAM_ID  = V_PROGRAM_ID
                                        AND SA.SHEET_NAME  = V_SHEET_NAME )
               ) IA
        ;

        /* #TMP_LIST)
           1) Line / Measure Cross = NO work, Ramp up, Load Rate
           2) ITEM / Measure Cross = Daily Capa                    */
        INSERT INTO GT_SCP0098_LINE_MEASURE
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , SITE_NAME
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , FACTORY_NAME
             , OPERATION_ID
             , OPERATION_NAME
             , LINE_ID
             , LINE_NAME
             , MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT T.DIVISION_ID
             , T.COMPANY_ID
             , T.SITE_ID AS SCM_SITE
             , T.SITE_NAME
             , T.PLANT_ID
             , T.OPERATION_GROUP_ID
             , T.FACTORY_ID
             , T.FACTORY_NAME
             , T.OPERATION_ID
             , T.OPERATION_NAME
             , T.LINE_ID
             , T.LINE_NAME
             , M.MEASURE_UI
             , M.MEASURE_NAME
             , M.MEASURE_DB
             , M.COL_DIV
             , M.SORT_ORDER_NO
             , '/' AS ITEM_ID
             , '-' AS ITEM_NAME
          FROM GT_SCP0098_STD_LINE_DATA T
             , GT_SCP0098_TARGET_MEASURE M
         WHERE M.MEASURE_UI != 'DAILY_CAPA'
        ;

        INSERT INTO GT_SCP0098_LINE_MEAS_DIST
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_GROUP_ID
             , OPERATION_ID
             , LINE_ID
             , MEASURE_UI
             , SITE_NAME
             , FACTORY_NAME
             , LINE_NAME
             , OPERATION_NAME
             , MEASURE_NAME
             , SORT_ORDER_NO
             )
        SELECT A.DIVISION_ID
             , A.COMPANY_ID
             , A.SCM_SITE
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_GROUP_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.MEASURE_UI
             , MAX(A.SITE_NAME)      AS SITE_NAME
             , MAX(A.FACTORY_NAME)   AS FACTORY_NAME
             , MAX(A.LINE_NAME)      AS LINE_NAME
             , MAX(A.OPERATION_NAME) AS OPERATION_NAME
             , MAX(A.MEASURE_NAME)   AS MEASURE_NAME
             , MAX(A.SORT_ORDER_NO)  AS SORT_ORDER_NO
          FROM GT_SCP0098_LINE_MEASURE A
        GROUP BY A.DIVISION_ID
               , A.COMPANY_ID
               , A.SCM_SITE
               , A.PLANT_ID
               , A.FACTORY_ID
               , A.OPERATION_GROUP_ID
               , A.OPERATION_ID
               , A.LINE_ID
               , A.MEASURE_UI
        ;

        INSERT INTO GT_SCP0098_ITEM_MEASURE
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , SITE_NAME
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , FACTORY_NAME
             , OPERATION_ID
             , OPERATION_NAME
             , LINE_ID
             , LINE_NAME
             , MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT T.DIVISION_ID
             , T.COMPANY_ID
             , T.SITE_ID AS SCM_SITE
             , T.SITE_NAME
             , T.PLANT_ID
             , T.OPERATION_GROUP_ID
             , T.FACTORY_ID
             , T.FACTORY_NAME
             , T.OPERATION_ID
             , T.OPERATION_NAME
             , T.LINE_ID
             , T.LINE_NAME
             , M.MEASURE_UI
             , M.MEASURE_NAME
             , M.MEASURE_DB
             , M.COL_DIV
             , M.SORT_ORDER_NO
             , T.ITEM_ID            AS ITEM_ID
             , NVL(T.ITEM_NAME,'-') AS ITEM_NAME
          FROM GT_SCP0098_STD_ITEM_DATA T
             , GT_SCP0098_TARGET_MEASURE M
         WHERE M.MEASURE_UI = 'DAILY_CAPA'
           AND ( TRIM(P_NICK_NAME) IS NULL OR T.ITEM_NAME IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_NICK_NAME, ',')) ) )
        ;

        /********************************************************************************
        * PROD_READY_RATE
        1, PROD_READY_RATE 변경 가능성 없음으로 추정
        2, TODAY 기준으로 생산준비율 조회
        3, 추후 기간별 생산준비율 관리가 필요할 시 개선 필요
        ********************************************************************************/
        INSERT INTO GT_SCP0098_PROD_READY_RATE
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , PROD_READY_RATE
             )
        SELECT DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , CASE WHEN PROD_READY_RATE IS NOT NULL THEN CAST(PROD_READY_RATE AS NUMBER(10,3))
                    ELSE PROD_READY_RATE
               END AS PROD_READY_RATE
          FROM SCP_MST_CAPA_WORK
         WHERE MEASURE  = 'NO_WORK'
           AND YYYYMMDD = V_TODAY_YYYYMM_FIRSTDAY
        ;

        /********************************************************************************
        * #TMP_MEASURE_CAPA_WORK = ( LINE + NO_WORK, LOAD_RATE, RAMP_UP)
        ********************************************************************************/
        INSERT INTO GT_SCP0098_MEAS_WORK
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , BASIS_YYYYMMDD
             , MEASURE
             , VALUE
             )
        SELECT W.DIVISION_ID
             , W.PLANT_ID
             , W.FACTORY_ID
             , W.OPERATION_ID
             , W.LINE_ID
             , 'D_' || W.YYYYMMDD AS BASIS_YYYYMMDD
             , W.MEASURE
             , CASE WHEN W.VALUE IS NOT NULL AND W.MEASURE = 'LOAD_RATE' THEN CAST(W.VALUE AS NUMBER(13,3))
                    WHEN W.VALUE IS NOT NULL AND W.MEASURE = 'RAMP_UP'   THEN CAST(W.VALUE AS NUMBER(13,3))
                    ELSE W.VALUE
               END AS VALUE
          FROM SCP_MST_CAPA_WORK W
             , GT_SCP0098_STD_LINE_DATA D
         WHERE W.DIVISION_ID  = D.DIVISION_ID
           AND W.PLANT_ID     = D.PLANT_ID
           AND W.FACTORY_ID   = D.FACTORY_ID
           AND W.OPERATION_ID = D.OPERATION_ID
           AND W.LINE_ID      = D.LINE_ID
           AND W.YYYYMMDD     >= P_FROM_YYYYMMDD
           AND W.YYYYMMDD     <= P_TO_YYYYMMDD
        ;

        /********************************************************************************
        *#TMP_DAILYCAPA_DAY
        ********************************************************************************/
        INSERT INTO GT_SCP0098_DAILYCAPA_DAY
             ( BASIS_YYYYMMDD
             , MEASURE
             , YYYYMMDD
             )
        SELECT 'D_' || BASIS_YYYYMMDD          AS BASIS_YYYYMMDD
             , 'DAILY_CAPA'                    AS MEASURE
             , SUBSTR(BASIS_YYYYMMDD, 1, 6)    AS YYYYMMDD
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
           AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD
        ;

        /********************************************************************************
        * #TMP_SCP0098_ITEM_LIST_YYYYMM_TERM
        ********************************************************************************/
        INSERT INTO GT_SCP0098_ITEM_LIST_TERM
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             )
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.FACTORY_ID
             , IA.OPERATION_ID
             , IA.LINE_ID
             , IA.ITEM_ID
             , XA.YYYYMMDD AS YYYYMM
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , OPERATION_ID
                      , LINE_ID
                      , ITEM_ID
                   FROM GT_SCP0098_ITEM_LIST_YYYYMM ) IA
             , ( SELECT DISTINCT YYYYMMDD
                   FROM GT_SCP0098_DAILYCAPA_DAY ) XA
        ;

        /********************************************************************************
        * #TMP_MEASURE_CAPA
        ********************************************************************************/
        INSERT INTO GT_SCP0098_MEAS_CAPA
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             , BASIS_YYYYMM
             , VALUE
             )
        SELECT B.DIVISION_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.OPERATION_ID
             , B.LINE_ID
             , B.ITEM_ID
             , NVL(W.YYYYMM, B.YYYYMM)          AS YYYYMM
             , 'M_' || NVL(W.YYYYMM, B.YYYYMM)  AS BASIS_YYYYMM
             , CASE WHEN W.VALUE IS NOT NULL
                    THEN CAST(NVL(W.VALUE, 0) AS NUMBER(13,0))
                    ELSE W.VALUE
               END AS VALUE
          FROM GT_SCP0098_ITEM_LIST_TERM B
             , SCP_MST_CAPA W
         WHERE W.DIVISION_ID(+)  = B.DIVISION_ID
           AND W.PLANT_ID(+)     = B.PLANT_ID
           AND W.FACTORY_ID(+)   = B.FACTORY_ID
           AND W.OPERATION_ID(+) = B.OPERATION_ID
           AND W.LINE_ID(+)      = B.LINE_ID
           AND W.ITEM_ID(+)      = B.ITEM_ID
           AND W.YYYYMM(+)       = B.YYYYMM
           AND B.YYYYMM          >= V_START_MONTH
           AND B.YYYYMM          <= V_END_MONTH
        ;

        /********************************************************************************
        * NO WORK + Next Day
        ********************************************************************************/
        INSERT INTO GT_SCP0098_MEAS_CAPA_NOWORK
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , BASIS_YYYYMMDD
             , MEASURE
             , VALUE
             , BASIS_YYYYMMDD_NEXT
             )
        SELECT DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , BASIS_YYYYMMDD
             , MEASURE
             , VALUE
             , 'D_' || TO_CHAR(TO_DATE(SUBSTR(BASIS_YYYYMMDD, 3, 8), 'YYYYMMDD') + 1, 'YYYYMMDD') AS BASIS_YYYYMMDD_NEXT
          FROM GT_SCP0098_MEAS_WORK
         WHERE MEASURE = 'NO_WORK'
           AND VALUE   = 1
        ;

        /********************************************************************************
        * OEE = Capa/일
        ********************************************************************************/
        INSERT INTO GT_SCP0098_OEE_TERM
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             , VALUE
             )
        SELECT B.DIVISION_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.OPERATION_ID
             , B.LINE_ID
             , B.ITEM_ID
             , B.YYYYMM
             , W.VALUE
          FROM GT_SCP0098_ITEM_LIST_TERM B
             , SCP_MST_CAPA W
         WHERE W.DIVISION_ID(+)  = B.DIVISION_ID
           AND W.PLANT_ID(+)     = B.PLANT_ID
           AND W.FACTORY_ID(+)   = B.FACTORY_ID
           AND W.OPERATION_ID(+) = B.OPERATION_ID
           AND W.LINE_ID(+)      = B.LINE_ID
           AND W.ITEM_ID(+)      = B.ITEM_ID
           AND W.YYYYMM(+)       = B.YYYYMM
           AND B.YYYYMM          >= V_START_MONTH
           AND B.YYYYMM          <= V_END_MONTH
        ;

        /********************************************************************************
        * Daily Cala Value Calc
        ********************************************************************************/
        INSERT INTO GT_SCP0098_CAPA_YMD
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , VALUE
             , MEASURE
             , BASIS_YYYYMMDD
             )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.VALUE
             , IA.MEASURE
             , IA.BASIS_YYYYMMDD
          FROM GT_SCP0098_MEAS_CAPA A
             , GT_SCP0098_DAILYCAPA_DAY IA
         WHERE A.YYYYMM = IA.YYYYMMDD
        ;

        UPDATE GT_SCP0098_CAPA_YMD A
           SET A.NO_WORK = ( SELECT MAX(CA.VALUE)
                               FROM GT_SCP0098_MEAS_WORK CA
                              WHERE CA.DIVISION_ID    = A.DIVISION_ID
                                AND CA.PLANT_ID       = A.PLANT_ID
                                AND CA.FACTORY_ID     = A.FACTORY_ID
                                AND CA.OPERATION_ID   = A.OPERATION_ID
                                AND CA.LINE_ID        = A.LINE_ID
                                AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                                AND CA.MEASURE        = 'NO_WORK' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0098_MEAS_WORK CA
                         WHERE CA.DIVISION_ID    = A.DIVISION_ID
                           AND CA.PLANT_ID       = A.PLANT_ID
                           AND CA.FACTORY_ID     = A.FACTORY_ID
                           AND CA.OPERATION_ID   = A.OPERATION_ID
                           AND CA.LINE_ID        = A.LINE_ID
                           AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                           AND CA.MEASURE        = 'NO_WORK' )
        ;

        UPDATE GT_SCP0098_CAPA_YMD A
           SET A.LOAD_RATE = ( SELECT MAX(CA.VALUE)
                                 FROM GT_SCP0098_MEAS_WORK CA
                                WHERE CA.DIVISION_ID    = A.DIVISION_ID
                                  AND CA.PLANT_ID       = A.PLANT_ID
                                  AND CA.FACTORY_ID     = A.FACTORY_ID
                                  AND CA.OPERATION_ID   = A.OPERATION_ID
                                  AND CA.LINE_ID        = A.LINE_ID
                                  AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                                  AND CA.MEASURE        = 'LOAD_RATE' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0098_MEAS_WORK CA
                         WHERE CA.DIVISION_ID    = A.DIVISION_ID
                           AND CA.PLANT_ID       = A.PLANT_ID
                           AND CA.FACTORY_ID     = A.FACTORY_ID
                           AND CA.OPERATION_ID   = A.OPERATION_ID
                           AND CA.LINE_ID        = A.LINE_ID
                           AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                           AND CA.MEASURE        = 'LOAD_RATE' )
        ;

        UPDATE GT_SCP0098_CAPA_YMD A
           SET A.RAMP_UP = ( SELECT MAX(CA.VALUE)
                               FROM GT_SCP0098_MEAS_WORK CA
                              WHERE CA.DIVISION_ID    = A.DIVISION_ID
                                AND CA.PLANT_ID       = A.PLANT_ID
                                AND CA.FACTORY_ID     = A.FACTORY_ID
                                AND CA.OPERATION_ID   = A.OPERATION_ID
                                AND CA.LINE_ID        = A.LINE_ID
                                AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                                AND CA.MEASURE        = 'RAMP_UP' )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0098_MEAS_WORK CA
                         WHERE CA.DIVISION_ID    = A.DIVISION_ID
                           AND CA.PLANT_ID       = A.PLANT_ID
                           AND CA.FACTORY_ID     = A.FACTORY_ID
                           AND CA.OPERATION_ID   = A.OPERATION_ID
                           AND CA.LINE_ID        = A.LINE_ID
                           AND CA.BASIS_YYYYMMDD = A.BASIS_YYYYMMDD
                           AND CA.MEASURE        = 'RAMP_UP' )
        ;

        /* PROD_RATE 기간으로 관리 안함 +  변경 가능성 없음 */
        UPDATE GT_SCP0098_CAPA_YMD A
           SET A.PROD_RATE = ( SELECT MAX(CA.PROD_READY_RATE)
                                 FROM GT_SCP0098_PROD_READY_RATE CA
                                WHERE CA.DIVISION_ID  = A.DIVISION_ID
                                  AND CA.PLANT_ID     = A.PLANT_ID
                                  AND CA.FACTORY_ID   = A.FACTORY_ID
                                  AND CA.OPERATION_ID = A.OPERATION_ID
                                  AND CA.LINE_ID      = A.LINE_ID )
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0098_PROD_READY_RATE CA
                         WHERE CA.DIVISION_ID  = A.DIVISION_ID
                           AND CA.PLANT_ID     = A.PLANT_ID
                           AND CA.FACTORY_ID   = A.FACTORY_ID
                           AND CA.OPERATION_ID = A.OPERATION_ID
                           AND CA.LINE_ID      = A.LINE_ID )
        ;

        /* NO_WORK_NEXTDAY */
        UPDATE GT_SCP0098_CAPA_YMD A
           SET A.NO_WORK_NEXTDAY = 1
         WHERE EXISTS ( SELECT 1
                          FROM GT_SCP0098_MEAS_CAPA_NOWORK CA
                         WHERE CA.DIVISION_ID         = A.DIVISION_ID
                           AND CA.PLANT_ID            = A.PLANT_ID
                           AND CA.FACTORY_ID          = A.FACTORY_ID
                           AND CA.OPERATION_ID        = A.OPERATION_ID
                           AND CA.LINE_ID             = A.LINE_ID
                           AND CA.BASIS_YYYYMMDD_NEXT = A.BASIS_YYYYMMDD )
        ;

        /* 오창, 월요일 조건으로 무조건 생산준비율 반영... 20240401 */
--        UPDATE GT_SCP0098_CAPA_YMD A
--           SET A.VALUE_CALC = ( SELECT CASE WHEN A.NO_WORK = 1 THEN 0
--                                            WHEN A.NO_WORK_NEXTDAY = 1 THEN NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1) * NVL(A.PROD_RATE / 100, 1)
--                                            WHEN SB.SITE_ID = 'A001' AND SA.DAYOFWEEK = 'MON' THEN NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1) * NVL(A.PROD_RATE / 100, 1)
--                                            ELSE NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1)
--                                       END
--                                  FROM SCM_SYS_CALENDAR_M SA
--                                     , ( SELECT FACTORY_ID
--                                              , MAX(SITE_ID) AS SITE_ID
--                                           FROM SCM_MST_FACTORY_SN
--                                         GROUP BY FACTORY_ID ) SB
--                                 WHERE SUBSTR(A.BASIS_YYYYMMDD, -8) = SA.BASIS_YYYYMMDD
--                                   AND A.FACTORY_ID                 = SB.FACTORY_ID )
--         WHERE EXISTS ( SELECT 1
--                          FROM SCM_SYS_CALENDAR_M SA
--                             , ( SELECT FACTORY_ID
--                                      , MAX(SITE_ID) AS SITE_ID
--                                   FROM SCM_MST_FACTORY_SN
--                                 GROUP BY FACTORY_ID ) SB
--                         WHERE SUBSTR(A.BASIS_YYYYMMDD, -8) = SA.BASIS_YYYYMMDD
--                           AND A.FACTORY_ID                 = SB.FACTORY_ID )
--        ;
        UPDATE GT_SCP0098_CAPA_YMD A /* AJS 20261007 속도 */
           SET A.VALUE_CALC = CASE WHEN A.NO_WORK = 1 THEN 0 /* AJS 20261007 속도 */
                                   WHEN A.NO_WORK_NEXTDAY = 1 THEN NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1) * NVL(A.PROD_RATE / 100, 1) /* AJS 20261007 속도 */
                                   WHEN ( SELECT MAX(SB.SITE_ID) /* AJS 20261007 속도 */
                                            FROM SCM_MST_FACTORY_SN SB /* AJS 20261007 속도 */
                                           WHERE SB.FACTORY_ID = A.FACTORY_ID ) = 'A001' /* AJS 20261007 속도 */
                                    AND ( SELECT SA.DAYOFWEEK /* AJS 20261007 속도 */
                                            FROM SCM_SYS_CALENDAR_M SA /* AJS 20261007 속도 */
                                           WHERE SA.BASIS_YYYYMMDD = SUBSTR(A.BASIS_YYYYMMDD, -8) ) = 'MON' /* AJS 20261007 속도 */
                                   THEN NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1) * NVL(A.PROD_RATE / 100, 1) /* AJS 20261007 속도 */
                                   ELSE NVL(A.VALUE, 0) * NVL(A.LOAD_RATE / 100, 1) * NVL(A.RAMP_UP, 1) /* AJS 20261007 속도 */
                              END /* AJS 20261007 속도 */
         WHERE EXISTS ( SELECT 1 /* AJS 20261007 속도 */
                          FROM SCM_SYS_CALENDAR_M SA /* AJS 20261007 속도 */
                         WHERE SA.BASIS_YYYYMMDD = SUBSTR(A.BASIS_YYYYMMDD, -8) ) /* AJS 20261007 속도 */
           AND EXISTS ( SELECT 1 /* AJS 20261007 속도 */
                          FROM SCM_MST_FACTORY_SN SB /* AJS 20261007 속도 */
                         WHERE SB.FACTORY_ID = A.FACTORY_ID ) /* AJS 20261007 속도 */
        ; /* AJS 20261007 속도 */

        INSERT INTO GT_SCP0098_CAPA_YMD_CALC
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , VALUE
             , MEASURE
             , BASIS_YYYYMMDD
             )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.VALUE_CALC AS VALUE
             , A.MEASURE
             , A.BASIS_YYYYMMDD
          FROM GT_SCP0098_CAPA_YMD A
        ;

        /* PIVOIT Column 처리
           ★ 동적 SQL 로 남기는 유일한 자리 : 조회 기간에 따라 일자 · 월 칸 이름이 달라지는 피벗이라
             정적 SQL 로 옮길 수 없다. 나머지는 모두 정적 SQL 이다.
             AS-IS 가 같은 목록을 네 번 훑는 것을 한 번으로 합쳤다. */
        V_MQRY_FIELD           := NULL;
        V_MQRY_FIELD_LAST      := NULL;
        V_MQRY_FIELD_PRODREADY := NULL;
        V_PIVOT_AGG            := NULL;
        V_OEE_PIVOT            := NULL; /* AJS 20261007 속도 */

        FOR C1 IN ( SELECT YYYYMMDD
                      FROM ( SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                                  , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                               FROM SCM_SYS_CALENDAR_M A
                              WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM
                                  , A.MONTH_NAME
                           ) IA
                     WHERE YYYYMMDD LIKE 'M_%'
                  ORDER BY SORT_ORDER_NO )
        LOOP
--            V_MQRY_FIELD_PRODREADY := V_MQRY_FIELD_PRODREADY
--                                   || '     , CASE WHEN MEASURE_UI = ''DAILY_CAPA'''                       || CHR(10)
--                                   || '            THEN ( SELECT MAX(VALUE)'                                || CHR(10)
--                                   || '                     FROM GT_SCP0098_OEE_TERM'                       || CHR(10)
--                                   || '                    WHERE DIVISION_ID  = A.DIVISION_ID'              || CHR(10)
--                                   || '                      AND PLANT_ID     = A.PLANT_ID'                 || CHR(10)
--                                   || '                      AND FACTORY_ID   = A.FACTORY_ID'               || CHR(10)
--                                   || '                      AND OPERATION_ID = A.OPERATION_ID'             || CHR(10)
--                                   || '                      AND LINE_ID      = A.LINE_ID'                  || CHR(10)
--                                   || '                      AND ITEM_ID      = A.ITEM_ID'                  || CHR(10)
--                                   || '                      AND YYYYMM       = ''' || SUBSTR(C1.YYYYMMDD, 3) || ''' )' || CHR(10)
--                                   || '            ELSE NULL'                                               || CHR(10)
--                                   || '       END AS ' || C1.YYYYMMDD                                       || CHR(10);
            V_MQRY_FIELD_PRODREADY := V_MQRY_FIELD_PRODREADY /* AJS 20261007 속도 */
                                   || '     , CASE WHEN MEASURE_UI = ''DAILY_CAPA'''                       || CHR(10) /* AJS 20261007 속도 */
                                   || '            THEN XA.OEE_' || C1.YYYYMMDD                             || CHR(10) /* AJS 20261007 속도 */
                                   || '            ELSE NULL'                                               || CHR(10) /* AJS 20261007 속도 */
                                   || '       END AS ' || C1.YYYYMMDD                                       || CHR(10); /* AJS 20261007 속도 */

            V_OEE_PIVOT := V_OEE_PIVOT /* AJS 20261007 속도 */
                        || '              , MAX(CASE WHEN YYYYMM = ''' || SUBSTR(C1.YYYYMMDD, 3) || ''' THEN VALUE END) AS OEE_' || C1.YYYYMMDD || CHR(10); /* AJS 20261007 속도 */
        END LOOP;

        FOR C2 IN ( SELECT YYYYMMDD
                      FROM ( SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                                  , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                               FROM SCM_SYS_CALENDAR_M A
                              WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMMDD
                           ) IA
                     WHERE YYYYMMDD LIKE 'D_%'
                  ORDER BY SORT_ORDER_NO )
        LOOP
            V_MQRY_FIELD := V_MQRY_FIELD || '     , ' || C2.YYYYMMDD || CHR(10);

            V_PIVOT_AGG  := V_PIVOT_AGG
                         || '     , MAX(CASE WHEN A.BASIS_YYYYMMDD = ''' || C2.YYYYMMDD || ''' THEN A.VALUE END) AS ' || C2.YYYYMMDD || CHR(10);

            V_MQRY_FIELD_LAST := V_MQRY_FIELD_LAST
                              || '     , CASE WHEN MEASURE_UI = ''NO_WORK'' AND ' || C2.YYYYMMDD || ' = 1  THEN ''Y'''  || CHR(10)
                              || '            WHEN MEASURE_UI = ''NO_WORK'' AND ' || C2.YYYYMMDD || ' != 1 THEN ''''' || CHR(10)
                              || '            ELSE TO_CHAR(' || C2.YYYYMMDD || ', ''FM99999999990.000'')'   || CHR(10)
                              || '       END AS ' || C2.YYYYMMDD                                            || CHR(10);
        END LOOP;

        V_MEXEC := 'SELECT DIVISION_ID'                                              || CHR(10)
                || '     , PLANT_ID'                                                 || CHR(10)
                || '     , FACTORY_ID'                                               || CHR(10)
                || '     , OPERATION_ID'                                             || CHR(10)
                || '     , LINE_ID'                                                  || CHR(10)
                || '     , MEASURE_UI'                                               || CHR(10)
                || '     , ITEM_ID'                                                  || CHR(10)
                || '     , ITEM_NAME'                                                || CHR(10)
                || '     , FACTORY_NAME'                                             || CHR(10)
                || '     , LINE_NAME'                                                || CHR(10)
                || '     , MEASURE_NAME'                                             || CHR(10)
                || '     , SORT_ORDER_NO'                                            || CHR(10)
                || V_MQRY_FIELD_PRODREADY
                || V_MQRY_FIELD_LAST
                || '     , PRODUCT_READY'                                            || CHR(10)
                || '  FROM ( SELECT DATA.DIVISION_ID'                                || CHR(10)
                || '              , DATA.PLANT_ID'                                   || CHR(10)
                || '              , DATA.FACTORY_ID'                                 || CHR(10)
                || '              , DATA.OPERATION_ID'                               || CHR(10)
                || '              , DATA.LINE_ID'                                    || CHR(10)
                || '              , DATA.MEASURE_UI'                                 || CHR(10)
                || '              , DATA.ITEM_ID'                                    || CHR(10)
                || '              , DATA.ITEM_NAME'                                  || CHR(10)
                || '              , DATA.FACTORY_NAME'                               || CHR(10)
                || '              , DATA.LINE_NAME'                                  || CHR(10)
                || '              , DATA.MEASURE_NAME'                               || CHR(10)
                || '              , DATA.SORT_ORDER_NO'                              || CHR(10)
                || REPLACE(V_MQRY_FIELD, '     , ', '              , DATA.')
                || '              , ( SELECT MAX(PROD_READY_RATE)'                   || CHR(10)
                || '                    FROM GT_SCP0098_PROD_READY_RATE'             || CHR(10)
                || '                   WHERE DIVISION_ID  = DATA.DIVISION_ID'        || CHR(10)
                || '                     AND PLANT_ID     = DATA.PLANT_ID'           || CHR(10)
                || '                     AND FACTORY_ID   = DATA.FACTORY_ID'         || CHR(10)
                || '                     AND OPERATION_ID = DATA.OPERATION_ID'       || CHR(10)
                || '                     AND LINE_ID      = DATA.LINE_ID ) AS PRODUCT_READY' || CHR(10)
                || '           FROM ( SELECT A.DIVISION_ID'                          || CHR(10)
                || '                       , A.PLANT_ID'                             || CHR(10)
                || '                       , A.FACTORY_ID'                           || CHR(10)
                || '                       , A.OPERATION_ID'                         || CHR(10)
                || '                       , A.LINE_ID'                              || CHR(10)
                || '                       , A.MEASURE   AS MEASURE_UI'              || CHR(10)
                || '                       , A.ITEM_ID   AS ITEM_ID'                 || CHR(10)
                || '                       , L.ITEM_NAME AS ITEM_NAME'               || CHR(10)
                || '                       , L.FACTORY_NAME'                         || CHR(10)
                || '                       , L.LINE_NAME'                            || CHR(10)
                || '                       , L.MEASURE_NAME'                         || CHR(10)
                || '                       , L.SORT_ORDER_NO'                        || CHR(10)
                || REPLACE(V_PIVOT_AGG, '     , ', '                       , ')
                || '                    FROM GT_SCP0098_CAPA_YMD_CALC A'             || CHR(10)
                || '                       , GT_SCP0098_ITEM_MEASURE L'              || CHR(10)
                || '                   WHERE A.DIVISION_ID  = L.DIVISION_ID'         || CHR(10)
                || '                     AND A.PLANT_ID     = L.PLANT_ID'            || CHR(10)
                || '                     AND A.FACTORY_ID   = L.FACTORY_ID'          || CHR(10)
                || '                     AND A.OPERATION_ID = L.OPERATION_ID'        || CHR(10)
                || '                     AND A.LINE_ID      = L.LINE_ID'             || CHR(10)
                || '                     AND A.ITEM_ID      = L.ITEM_ID'             || CHR(10)
                || '                     AND A.MEASURE      = L.MEASURE_UI'          || CHR(10)
                || '                 GROUP BY A.DIVISION_ID'                         || CHR(10)
                || '                        , A.PLANT_ID'                            || CHR(10)
                || '                        , A.FACTORY_ID'                          || CHR(10)
                || '                        , A.OPERATION_ID'                        || CHR(10)
                || '                        , A.LINE_ID'                             || CHR(10)
                || '                        , A.MEASURE'                             || CHR(10)
                || '                        , A.ITEM_ID'                             || CHR(10)
                || '                        , L.ITEM_NAME'                           || CHR(10)
                || '                        , L.FACTORY_NAME'                        || CHR(10)
                || '                        , L.LINE_NAME'                           || CHR(10)
                || '                        , L.MEASURE_NAME'                        || CHR(10)
                || '                        , L.SORT_ORDER_NO'                       || CHR(10)
                || '                  UNION ALL'                                     || CHR(10)
                || '                  SELECT A.DIVISION_ID'                          || CHR(10)
                || '                       , A.PLANT_ID'                             || CHR(10)
                || '                       , A.FACTORY_ID'                           || CHR(10)
                || '                       , A.OPERATION_ID'                         || CHR(10)
                || '                       , A.LINE_ID'                              || CHR(10)
                || '                       , A.MEASURE AS MEASURE_UI'                || CHR(10)
                || '                       , '' ''     AS ITEM_ID'                   || CHR(10)
                || '                       , '' ''     AS ITEM_NAME'                  || CHR(10)
                || '                       , L.FACTORY_NAME'                         || CHR(10)
                || '                       , L.LINE_NAME'                            || CHR(10)
                || '                       , L.MEASURE_NAME'                         || CHR(10)
                || '                       , L.SORT_ORDER_NO'                        || CHR(10)
                || REPLACE(V_PIVOT_AGG, '     , ', '                       , ')
                || '                    FROM GT_SCP0098_MEAS_WORK A'                 || CHR(10)
                || '                       , GT_SCP0098_LINE_MEAS_DIST L'            || CHR(10)
                || '                   WHERE A.DIVISION_ID  = L.DIVISION_ID'         || CHR(10)
                || '                     AND A.PLANT_ID     = L.PLANT_ID'            || CHR(10)
                || '                     AND A.FACTORY_ID   = L.FACTORY_ID'          || CHR(10)
                || '                     AND A.OPERATION_ID = L.OPERATION_ID'        || CHR(10)
                || '                     AND A.LINE_ID      = L.LINE_ID'             || CHR(10)
                || '                     AND A.MEASURE      = L.MEASURE_UI'          || CHR(10)
                || '                     AND A.MEASURE      != ''DAILY_CAPA'''       || CHR(10)
                || '                 GROUP BY A.DIVISION_ID'                         || CHR(10)
                || '                        , A.PLANT_ID'                            || CHR(10)
                || '                        , A.FACTORY_ID'                          || CHR(10)
                || '                        , A.OPERATION_ID'                        || CHR(10)
                || '                        , A.LINE_ID'                             || CHR(10)
                || '                        , A.MEASURE'                             || CHR(10)
                || '                        , L.FACTORY_NAME'                        || CHR(10)
                || '                        , L.LINE_NAME'                           || CHR(10)
                || '                        , L.MEASURE_NAME'                        || CHR(10)
                || '                        , L.SORT_ORDER_NO'                       || CHR(10)
                || '                ) DATA'                                          || CHR(10)
                || '       ) A'                                                      || CHR(10)
                || '     , ( SELECT DIVISION_ID  AS OT_DIVISION_ID'                  || CHR(10) /* AJS 20261007 속도 */
                || '              , PLANT_ID     AS OT_PLANT_ID'                     || CHR(10) /* AJS 20261007 속도 */
                || '              , FACTORY_ID   AS OT_FACTORY_ID'                   || CHR(10) /* AJS 20261007 속도 */
                || '              , OPERATION_ID AS OT_OPERATION_ID'                 || CHR(10) /* AJS 20261007 속도 */
                || '              , LINE_ID      AS OT_LINE_ID'                      || CHR(10) /* AJS 20261007 속도 */
                || '              , ITEM_ID      AS OT_ITEM_ID'                      || CHR(10) /* AJS 20261007 속도 */
                || V_OEE_PIVOT /* AJS 20261007 속도 */
                || '           FROM GT_SCP0098_OEE_TERM'                             || CHR(10) /* AJS 20261007 속도 */
                || '          GROUP BY DIVISION_ID'                                  || CHR(10) /* AJS 20261007 속도 */
                || '                 , PLANT_ID'                                     || CHR(10) /* AJS 20261007 속도 */
                || '                 , FACTORY_ID'                                   || CHR(10) /* AJS 20261007 속도 */
                || '                 , OPERATION_ID'                                 || CHR(10) /* AJS 20261007 속도 */
                || '                 , LINE_ID'                                      || CHR(10) /* AJS 20261007 속도 */
                || '                 , ITEM_ID ) XA'                                 || CHR(10) /* AJS 20261007 속도 */
                || ' WHERE XA.OT_DIVISION_ID(+)  = A.DIVISION_ID'                    || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_PLANT_ID(+)     = A.PLANT_ID'                       || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_FACTORY_ID(+)   = A.FACTORY_ID'                     || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_OPERATION_ID(+) = A.OPERATION_ID'                   || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_LINE_ID(+)      = A.LINE_ID'                        || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_ITEM_ID(+)      = A.ITEM_ID'                        || CHR(10) /* AJS 20261007 속도 */
                || 'ORDER BY DIVISION_ID'                                            || CHR(10)
                || '       , PLANT_ID'                                               || CHR(10)
                || '       , FACTORY_ID'                                             || CHR(10)
                || '       , OPERATION_ID'                                           || CHR(10)
                || '       , LINE_ID'                                                || CHR(10)
                || '       , SORT_ORDER_NO'                                          || CHR(10)
                || '       , ITEM_ID'                                                || CHR(10)
        ;

        OPEN O_RC FOR V_MEXEC;

        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 0
        ;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MESSAGE := SQLERRM;

            OPEN O_RC FOR
                SELECT NULL AS DUMMY
                  FROM DUAL
                 WHERE 1 = 0
            ;

            OPEN O_RESULT_CURSOR FOR
                SELECT V_ERR_MESSAGE AS ERR_MESSAGE
                  FROM DUAL
            ;
    END P_GET_CAPA_MOBILITYIT;

/*==================================================================================================
 * Program ID   : SCP0098_GET_CAPA_MobilityIT_LINE
 * Description  :
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/07/19   khj79          최초작성 - SCP0049_GET_CAPA 참조 => SCP0013 ,Production Plan Line 참조
 * 2020/08/21   khj79          최초작성 - SCP0049_GET_CAPA 참조 => Line Assign / Operation / LOCATION_GROUP_ROUTE
 * 2020/08/23   vadabi3        최초작성 - SCP0049_GET_CAPA 참조 => PIVOT
 * 2020/09/06   vadabi3        Version 2 - 조회 대상 개선
 * 2025/08/01   hrkim		   PJ20257329 최적화 Planning Input Constraint UI 개발 및 Master Validation 확산 : Cell 완성 공정 하드코딩 변경
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          [속도2차] 품목 목록 적재 시 라인 계층 인라인 뷰 병합 방지(NO_MERGE) · 월 칸(M_) 행별 하위질의를 한 번 집계해 붙임
 *==================================================================================================*/
    PROCEDURE P_GET_CAPA_MOBILITYIT_LINE (
        P_TODAY_YYYYMMDD    IN  VARCHAR2
      , P_FROM_YYYYMMDD     IN  VARCHAR2
      , P_TO_YYYYMMDD       IN  VARCHAR2
      , P_DIVISION_ID       IN  VARCHAR2
      , P_PLANT_ID          IN  VARCHAR2
      , P_LINE_ID           IN  VARCHAR2
      , P_OPERATION_ID      IN  VARCHAR2
      , P_MODEL_ID          IN  VARCHAR2
      , P_ITEM_ID           IN  VARCHAR2
      , P_NICK_NAME         IN  VARCHAR2
      , P_BUCKET            IN  VARCHAR2
      , P_USER_ID           IN  VARCHAR2
      , P_DEBUG_MODE        IN  VARCHAR2
      , O_RC                OUT SYS_REFCURSOR
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        /* Declare */
        V_PROGRAM_ID            VARCHAR2(400 CHAR) := 'SCP0098';
        V_SHEET_NAME            VARCHAR2(600 CHAR) := 'CAPA_SMALL';
        V_TODAY_YYYYMM          VARCHAR2(6 CHAR);

        /* 날짜 조건용 변수 설정 */
        V_START_MONTH           VARCHAR2(6 CHAR);   /* 시작 월(현재월 +1 년) */
        V_END_MONTH             VARCHAR2(6 CHAR);   /* 마지막 월 */

        V_TODAY_YYYYMM_FIRSTDAY VARCHAR2(8 CHAR);

        /* 쿼리 실행용 변수 */
        V_MEXEC                 CLOB;
        V_MQRY_FIELD            CLOB;   /* 피벗 칸 목록 (D_) */
        V_MQRY_FIELD_LAST       CLOB;   /* 최종 표기 변환 (D_) */
        V_MQRY_FIELD_PRODREADY  CLOB;   /* 월 칸 (M_) */
        V_PIVOT_AGG             CLOB;   /* 피벗 집계식 (D_) */
        V_OEE_PIVOT             CLOB;   /* 월 칸 집계식 (M_) */ /* AJS 20261007 속도 */

        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        /* GTT 초기화 (TRUNCATE 금지) */
        DELETE FROM GT_SCP0098_ITEM_LIST;
        DELETE FROM GT_SCP0098_ITEM_LIST_YYYYMM;
        DELETE FROM GT_SCP0098_STD_LINE_DATA;
        DELETE FROM GT_SCP0098_STD_ITEM_DATA;
        DELETE FROM GT_SCP0098_TARGET_MEASURE;
        DELETE FROM GT_SCP0098_LINE_MEASURE;
        DELETE FROM GT_SCP0098_LINE_MEAS_DIST;
        DELETE FROM GT_SCP0098_ITEM_MEASURE;
        DELETE FROM GT_SCP0098_PROD_READY_RATE;
        DELETE FROM GT_SCP0098_MEAS_WORK;
        DELETE FROM GT_SCP0098_DAILYCAPA_DAY;
        DELETE FROM GT_SCP0098_ITEM_LIST_TERM;
        DELETE FROM GT_SCP0098_MEAS_CAPA;
        DELETE FROM GT_SCP0098_MEAS_CAPA_NOWORK;
        DELETE FROM GT_SCP0098_OEE_TERM;
        DELETE FROM GT_SCP0098_CAPA_YMD;
        DELETE FROM GT_SCP0098_CAPA_YMD_CALC;

        V_TODAY_YYYYMM := SUBSTR(P_TODAY_YYYYMMDD, 1, 6);

        /* 조회 날짜 설정 */
        V_START_MONTH := SUBSTR(P_FROM_YYYYMMDD, 1, 6); /* 현재일 */
        V_END_MONTH   := SUBSTR(P_TO_YYYYMMDD  , 1, 6); /* 조회일자가 기준을 넘을 경우 Y+1 으로 조회 */

        V_TODAY_YYYYMM_FIRSTDAY := V_TODAY_YYYYMM || '01';

        /* #TMP_SCP0098_ITEM_LIST_ALL) LOCATION_GROUP_ROUTE */
        /* [PJ20257329] 2025.08.01 Cell 완성 공정 하드코딩 변경 — 테이블 변수 대신 IN 서브쿼리로 옮겼다 */
        /* ★ PRIORITY 조건이 조인절이 아니라 WHERE 에 있어 품목 배정이 없는 라인은 제외된다(AS-IS 그대로) */
        INSERT INTO GT_SCP0098_ITEM_LIST
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , ITEM_CLASS
             )
--        SELECT DISTINCT
        SELECT /*+ NO_MERGE(IA) */ DISTINCT /* AJS 20261007 속도 */
               IA.DIVISION_ID
             , IA.COMPANY_ID
             , IA.SITE_ID
             , IA.PLANT_ID
             , IA.OPERATION_GROUP_ID
             , IA.FACTORY_ID
             , IA.OPERATION_ID
             , IA.LINE_ID
             , XA.ITEM_ID
             , ( SELECT MAX(SA.ITEM_CLASS)
                   FROM SCM_ITEM_M_SN SA
                  WHERE SA.COMPANY_ID  = XA.COMPANY_ID
                    AND SA.DIVISION_ID = XA.DIVISION_ID
                    AND SA.SITE_ID     = XA.SITE_ID
                    AND SA.ITEM_ID     = XA.ITEM_ID
                    AND SA.ITEM_CLASS  = 'ES1901'
                    AND SA.ACTIVE_FLAG = 'Y' ) AS ITEM_CLASS
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , COMPANY_ID
                      , SITE_ID
                      , PLANT_ID
                      , OPERATION_GROUP_ID
                      , FACTORY_ID
                      , OPERATION_ID
                      , LINE_ID
                   FROM SCM_LINE_HIERARCHY_V_SN
                  WHERE OPERATION_ID IN ( SELECT SEGMENT1
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE = 'SCP_PLAN_OPERATION'
                                             AND SEGMENT3    = 'A'   /* 공정그룹(Cell) */
                                             AND ATTRIBUTE1  = 'Y' ) /* Final Operation */
                    AND ( TRIM(P_DIVISION_ID) IS NULL OR DIVISION_ID IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')) ) )
                    AND ( TRIM(P_PLANT_ID)    IS NULL OR PLANT_ID    IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_PLANT_ID, ',')) ) )
                    AND ( TRIM(P_LINE_ID)     IS NULL OR LINE_ID     IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_LINE_ID, ',')) ) )
               ) IA
             , ( SELECT SA.COMPANY_ID
                      , SA.DIVISION_ID
                      , SA.SITE_ID
                      , SA.PLANT_ID
                      , SA.FACTORY_ID
                      , SA.LINE_ID
                      , SA.OPERATION_ID
                      , SA.ITEM_ID
                      , SA.PRIORITY
                   FROM SCM_MST_ITEM_LINE_ASSIGN_SN SA
                  WHERE SA.MONTH   >= V_START_MONTH
                    AND SA.MONTH   <= V_END_MONTH
                    AND SA.ITEM_ID NOT LIKE 'AJR%'
                    AND SA.ITEM_ID IS NOT NULL
                    AND ( TRIM(P_ITEM_ID) IS NULL OR SA.ITEM_ID IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) ) )
               ) XA
         WHERE IA.DIVISION_ID  = XA.DIVISION_ID(+)
           AND IA.SITE_ID      = XA.SITE_ID(+)
           AND IA.PLANT_ID     = XA.PLANT_ID(+)
           AND IA.FACTORY_ID   = XA.FACTORY_ID(+)
           AND IA.LINE_ID      = XA.LINE_ID(+)
           AND IA.OPERATION_ID = XA.OPERATION_ID(+)
           AND XA.PRIORITY     NOT IN ('0', '9')
        ;

        /* #TMP_SCP0098_ITEM_LIST_YYYYMM */
        INSERT INTO GT_SCP0098_ITEM_LIST_YYYYMM
             ( DIVISION_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             )
        SELECT A.DIVISION_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , B.MONTH AS YYYYMM
          FROM GT_SCP0098_ITEM_LIST A
             , SCM_MST_ITEM_LINE_ASSIGN_SN B
         WHERE A.COMPANY_ID   = B.COMPANY_ID
           AND A.DIVISION_ID  = B.DIVISION_ID
           AND A.SITE_ID      = B.SITE_ID
           AND A.PLANT_ID     = B.PLANT_ID
           AND A.FACTORY_ID   = B.FACTORY_ID
           AND A.OPERATION_ID = B.OPERATION_ID
           AND A.LINE_ID      = B.LINE_ID
           AND A.ITEM_ID      = B.ITEM_ID
           AND B.MONTH        >= V_START_MONTH
           AND B.MONTH        <= V_END_MONTH
        ;

        /* #TMP_SCP0098_STD_LINE_DATA) Line List */
        INSERT INTO GT_SCP0098_STD_LINE_DATA
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , SITE_NAME
             , FACTORY_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP_NAME
             , LINE_NAME
             , OPERATION_NAME
             )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , NVL(B.SITE_NAME      , '-') AS SITE_NAME
             , NVL(B.FACTORY_NAME   , '-') AS FACTORY_NAME
             , B.OPERATION_GROUP_ID
             , NVL(B.OPERATION_GROUP, '-') AS OPERATION_GROUP_NAME
             , NVL(B.LINE_NAME      , '-') AS LINE_NAME
             , NVL(B.OPERATION_NAME , '-') AS OPERATION_NAME
          FROM GT_SCP0098_ITEM_LIST A
             , SCM_LINE_HIERARCHY_V_SN B
         WHERE A.COMPANY_ID   = B.COMPANY_ID(+)
           AND A.DIVISION_ID  = B.DIVISION_ID(+)
           AND A.SITE_ID      = B.SITE_ID(+)
           AND A.PLANT_ID     = B.PLANT_ID(+)
           AND A.FACTORY_ID   = B.FACTORY_ID(+)
           AND A.OPERATION_ID = B.OPERATION_ID(+)
           AND A.LINE_ID      = B.LINE_ID(+)
        ;

        /* #TMP_SCP0098_STD_ITEM_DATA) Item List */
        INSERT INTO GT_SCP0098_STD_ITEM_DATA
             ( DIVISION_ID
             , COMPANY_ID
             , SITE_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , SITE_NAME
             , FACTORY_NAME
             , OPERATION_GROUP_ID
             , OPERATION_GROUP_NAME
             , LINE_NAME
             , OPERATION_NAME
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT A.DIVISION_ID
             , A.COMPANY_ID
             , A.SITE_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , NVL(B.SITE_NAME      , '-') AS SITE_NAME
             , NVL(B.FACTORY_NAME   , '-') AS FACTORY_NAME
             , B.OPERATION_GROUP_ID
             , NVL(B.OPERATION_GROUP, '-') AS OPERATION_GROUP_NAME
             , NVL(B.LINE_NAME      , '-') AS LINE_NAME
             , NVL(B.OPERATION_NAME , '-') AS OPERATION_NAME
             , A.ITEM_ID
             , NVL(FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID), '-') AS ITEM_NAME
          FROM GT_SCP0098_ITEM_LIST A
             , SCM_LINE_HIERARCHY_V_SN B
         WHERE A.COMPANY_ID   = B.COMPANY_ID(+)
           AND A.DIVISION_ID  = B.DIVISION_ID(+)
           AND A.SITE_ID      = B.SITE_ID(+)
           AND A.PLANT_ID     = B.PLANT_ID(+)
           AND A.FACTORY_ID   = B.FACTORY_ID(+)
           AND A.OPERATION_ID = B.OPERATION_ID(+)
           AND A.LINE_ID      = B.LINE_ID(+)
        ;

        /* #TARGET_MEASURES */
        INSERT INTO GT_SCP0098_TARGET_MEASURE
             ( MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             )
        SELECT IA.MEASURE_UI
             , IA.MEASURE_NAME
             , SUBSTR(IA.MEASURE_UI, 1, INSTR(IA.MEASURE_UI, '_') - 1)                              AS MEASURE_DB
             , SUBSTR(IA.MEASURE_UI, INSTR(IA.MEASURE_UI, '_') + 1, LENGTH(RTRIM(IA.MEASURE_UI)))   AS COL_DIV
             , IA.SORT_ORDER_NO
          FROM ( /* user별 설정한 조회 대상 measure */
                 SELECT UM.COLUMN_NAME       AS MEASURE_UI
                      , M.COLUMN_LABEL_NAME  AS MEASURE_NAME
                      , UM.SORT_ORDER_NO
                   FROM SCM_MST_TITLESET_USER UM
                      , SCM_MST_SHEET_MEASURE M
                  WHERE M.COLUMN_NAME = UM.COLUMN_NAME
                    AND M.PROGRAM_ID  = V_PROGRAM_ID
                    AND M.SHEET_NAME  = V_SHEET_NAME
                    AND M.VALID_YN    = 'Y'
                    AND UM.USER_ID    = P_USER_ID
                    AND UM.PROGRAM_ID = V_PROGRAM_ID
                    AND UM.SHEET_NAME = V_SHEET_NAME

                 UNION ALL
                 /* user별 설정한 measure정보가 없을 경우 default measure를 보여준다. */
                 SELECT M.COLUMN_NAME        AS MEASURE_UI
                      , M.COLUMN_LABEL_NAME  AS MEASURE_NAME
                      , M.SORT_ORDER_NO
                   FROM SCM_MST_SHEET_MEASURE M
                  WHERE M.PROGRAM_ID   = V_PROGRAM_ID
                    AND M.SHEET_NAME   = V_SHEET_NAME
                    AND M.VALID_YN     = 'Y'
                    AND M.DEFAULT_FLAG = 'Y'
                    AND NOT EXISTS ( SELECT 1
                                       FROM SCM_MST_TITLESET_USER SA
                                          , SCM_MST_SHEET_MEASURE SB
                                      WHERE SB.COLUMN_NAME = SA.COLUMN_NAME
                                        AND SB.PROGRAM_ID  = V_PROGRAM_ID
                                        AND SB.SHEET_NAME  = V_SHEET_NAME
                                        AND SB.VALID_YN    = 'Y'
                                        AND SA.USER_ID     = P_USER_ID
                                        AND SA.PROGRAM_ID  = V_PROGRAM_ID
                                        AND SA.SHEET_NAME  = V_SHEET_NAME )
               ) IA
        ;

        /* #TMP_LIST)
           1) Line / Measure Cross = NO work, Ramp up, Load Rate
           2) ITEM / Measure Cross = Daily Capa                    */
        INSERT INTO GT_SCP0098_LINE_MEASURE
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , SITE_NAME
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , FACTORY_NAME
             , OPERATION_ID
             , OPERATION_NAME
             , LINE_ID
             , LINE_NAME
             , MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT T.DIVISION_ID
             , T.COMPANY_ID
             , T.SITE_ID AS SCM_SITE
             , T.SITE_NAME
             , T.PLANT_ID
             , T.OPERATION_GROUP_ID
             , T.FACTORY_ID
             , T.FACTORY_NAME
             , T.OPERATION_ID
             , T.OPERATION_NAME
             , T.LINE_ID
             , T.LINE_NAME
             , M.MEASURE_UI
             , M.MEASURE_NAME
             , M.MEASURE_DB
             , M.COL_DIV
             , M.SORT_ORDER_NO
             , '/' AS ITEM_ID
             , '-' AS ITEM_NAME
          FROM GT_SCP0098_STD_LINE_DATA T
             , GT_SCP0098_TARGET_MEASURE M
         WHERE M.MEASURE_UI != 'DAILY_CAPA'
        ;

        INSERT INTO GT_SCP0098_LINE_MEAS_DIST
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_GROUP_ID
             , OPERATION_ID
             , LINE_ID
             , MEASURE_UI
             , SITE_NAME
             , FACTORY_NAME
             , LINE_NAME
             , OPERATION_NAME
             , MEASURE_NAME
             , SORT_ORDER_NO
             )
        SELECT A.DIVISION_ID
             , A.COMPANY_ID
             , A.SCM_SITE
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_GROUP_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.MEASURE_UI
             , MAX(A.SITE_NAME)      AS SITE_NAME
             , MAX(A.FACTORY_NAME)   AS FACTORY_NAME
             , MAX(A.LINE_NAME)      AS LINE_NAME
             , MAX(A.OPERATION_NAME) AS OPERATION_NAME
             , MAX(A.MEASURE_NAME)   AS MEASURE_NAME
             , MAX(A.SORT_ORDER_NO)  AS SORT_ORDER_NO
          FROM GT_SCP0098_LINE_MEASURE A
        GROUP BY A.DIVISION_ID
               , A.COMPANY_ID
               , A.SCM_SITE
               , A.PLANT_ID
               , A.FACTORY_ID
               , A.OPERATION_GROUP_ID
               , A.OPERATION_ID
               , A.LINE_ID
               , A.MEASURE_UI
        ;

        INSERT INTO GT_SCP0098_ITEM_MEASURE
             ( DIVISION_ID
             , COMPANY_ID
             , SCM_SITE
             , SITE_NAME
             , PLANT_ID
             , OPERATION_GROUP_ID
             , FACTORY_ID
             , FACTORY_NAME
             , OPERATION_ID
             , OPERATION_NAME
             , LINE_ID
             , LINE_NAME
             , MEASURE_UI
             , MEASURE_NAME
             , MEASURE_DB
             , COL_DIV
             , SORT_ORDER_NO
             , ITEM_ID
             , ITEM_NAME
             )
        SELECT T.DIVISION_ID
             , T.COMPANY_ID
             , T.SITE_ID AS SCM_SITE
             , T.SITE_NAME
             , T.PLANT_ID
             , T.OPERATION_GROUP_ID
             , T.FACTORY_ID
             , T.FACTORY_NAME
             , T.OPERATION_ID
             , T.OPERATION_NAME
             , T.LINE_ID
             , T.LINE_NAME
             , M.MEASURE_UI
             , M.MEASURE_NAME
             , M.MEASURE_DB
             , M.COL_DIV
             , M.SORT_ORDER_NO
             , T.ITEM_ID   AS ITEM_ID
             , T.ITEM_NAME AS ITEM_NAME
          FROM GT_SCP0098_STD_ITEM_DATA T
             , GT_SCP0098_TARGET_MEASURE M
         WHERE M.MEASURE_UI = 'DAILY_CAPA'
           AND ( TRIM(P_NICK_NAME) IS NULL OR T.ITEM_NAME IN ( SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_NICK_NAME, ',')) ) )
        ;

        /********************************************************************************
        * PROD_READY_RATE
        1, PROD_READY_RATE 변경 가능성 없음으로 추정
        2, TODAY 기준으로 생산준비율 조회
        3, 추후 기간별 생산준비율 관리가 필요할 시 개선 필요
        ********************************************************************************/
        INSERT INTO GT_SCP0098_PROD_READY_RATE
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , PROD_READY_RATE
             )
        SELECT DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , PROD_READY_RATE
          FROM SCP_MST_CAPA_WORK
         WHERE MEASURE  = 'NO_WORK'
           AND YYYYMMDD = V_TODAY_YYYYMM_FIRSTDAY
        ;

        /********************************************************************************
        * #TMP_MEASURE_CAPA_WORK = ( LINE + NO_WORK, LOAD_RATE, RAMP_UP)
        ********************************************************************************/
        INSERT INTO GT_SCP0098_MEAS_WORK
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , BASIS_YYYYMMDD
             , MEASURE
             , VALUE
             )
        SELECT W.DIVISION_ID
             , W.PLANT_ID
             , W.FACTORY_ID
             , W.OPERATION_ID
             , W.LINE_ID
             , 'D_' || W.YYYYMMDD AS BASIS_YYYYMMDD
             , W.MEASURE
             , CAST(NVL(W.VALUE, 0) AS NUMBER(13,2)) AS VALUE
          FROM SCP_MST_CAPA_WORK W
             , GT_SCP0098_STD_LINE_DATA D
         WHERE W.DIVISION_ID  = D.DIVISION_ID
           AND W.PLANT_ID     = D.PLANT_ID
           AND W.FACTORY_ID   = D.FACTORY_ID
           AND W.OPERATION_ID = D.OPERATION_ID
           AND W.LINE_ID      = D.LINE_ID
           AND W.YYYYMMDD     >= P_FROM_YYYYMMDD
           AND W.YYYYMMDD     <= P_TO_YYYYMMDD
        ;

        /********************************************************************************
        *#TMP_DAILYCAPA_DAY
        ********************************************************************************/
        INSERT INTO GT_SCP0098_DAILYCAPA_DAY
             ( BASIS_YYYYMMDD
             , MEASURE
             , YYYYMMDD
             )
        SELECT 'D_' || BASIS_YYYYMMDD          AS BASIS_YYYYMMDD
             , 'DAILY_CAPA'                    AS MEASURE
             , SUBSTR(BASIS_YYYYMMDD, 1, 6)    AS YYYYMMDD
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
           AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD
        ;

        /********************************************************************************
        * #TMP_SCP0098_ITEM_LIST_YYYYMM_TERM
        ********************************************************************************/
        INSERT INTO GT_SCP0098_ITEM_LIST_TERM
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             )
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.FACTORY_ID
             , IA.OPERATION_ID
             , IA.LINE_ID
             , IA.ITEM_ID
             , XA.YYYYMMDD AS YYYYMM
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , PLANT_ID
                      , FACTORY_ID
                      , OPERATION_ID
                      , LINE_ID
                      , ITEM_ID
                   FROM GT_SCP0098_ITEM_LIST_YYYYMM ) IA
             , ( SELECT DISTINCT YYYYMMDD
                   FROM GT_SCP0098_DAILYCAPA_DAY ) XA
        ;

        /********************************************************************************
        * #TMP_MEASURE_CAPA
        ********************************************************************************/
        INSERT INTO GT_SCP0098_MEAS_CAPA
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             , BASIS_YYYYMM
             , VALUE
             )
        SELECT B.DIVISION_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.OPERATION_ID
             , B.LINE_ID
             , B.ITEM_ID
             , NVL(W.YYYYMM, B.YYYYMM)          AS YYYYMM
             , 'M_' || NVL(W.YYYYMM, B.YYYYMM)  AS BASIS_YYYYMM
             , CAST(NVL(W.VALUE, 0) AS NUMBER(13,0)) AS VALUE
          FROM GT_SCP0098_ITEM_LIST_TERM B
             , SCP_MST_CAPA W
         WHERE W.DIVISION_ID(+)  = B.DIVISION_ID
           AND W.PLANT_ID(+)     = B.PLANT_ID
           AND W.FACTORY_ID(+)   = B.FACTORY_ID
           AND W.OPERATION_ID(+) = B.OPERATION_ID
           AND W.LINE_ID(+)      = B.LINE_ID
           AND W.ITEM_ID(+)      = B.ITEM_ID
           AND W.YYYYMM(+)       = B.YYYYMM
           AND B.YYYYMM          >= V_START_MONTH
           AND B.YYYYMM          <= V_END_MONTH
        ;

        /********************************************************************************
        * OEE = Capa/일
        ********************************************************************************/
        INSERT INTO GT_SCP0098_OEE_TERM
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , YYYYMM
             , VALUE
             )
        SELECT B.DIVISION_ID
             , B.PLANT_ID
             , B.FACTORY_ID
             , B.OPERATION_ID
             , B.LINE_ID
             , B.ITEM_ID
             , B.YYYYMM
             , NVL(W.VALUE, 0) AS VALUE
          FROM GT_SCP0098_ITEM_LIST_TERM B
             , SCP_MST_CAPA W
         WHERE W.DIVISION_ID(+)  = B.DIVISION_ID
           AND W.PLANT_ID(+)     = B.PLANT_ID
           AND W.FACTORY_ID(+)   = B.FACTORY_ID
           AND W.OPERATION_ID(+) = B.OPERATION_ID
           AND W.LINE_ID(+)      = B.LINE_ID
           AND W.ITEM_ID(+)      = B.ITEM_ID
           AND W.YYYYMM(+)       = B.YYYYMM
           AND B.YYYYMM          >= V_START_MONTH
           AND B.YYYYMM          <= V_END_MONTH
        ;

        /********************************************************************************
        * Daily Cala Value Calc
        ********************************************************************************/
        INSERT INTO GT_SCP0098_CAPA_YMD
             ( DIVISION_ID
             , PLANT_ID
             , FACTORY_ID
             , OPERATION_ID
             , LINE_ID
             , ITEM_ID
             , VALUE
             , MEASURE
             , BASIS_YYYYMMDD
             )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.FACTORY_ID
             , A.OPERATION_ID
             , A.LINE_ID
             , A.ITEM_ID
             , A.VALUE
             , IA.MEASURE
             , IA.BASIS_YYYYMMDD
          FROM GT_SCP0098_MEAS_CAPA A
             , GT_SCP0098_DAILYCAPA_DAY IA
         WHERE A.YYYYMM = IA.YYYYMMDD
        ;

        /* PIVOIT Column 처리
           ★ 동적 SQL 로 남기는 유일한 자리 : 조회 기간에 따라 일자 · 월 칸 이름이 달라지는 피벗이라
             정적 SQL 로 옮길 수 없다. 나머지는 모두 정적 SQL 이다. */
        V_MQRY_FIELD           := NULL;
        V_MQRY_FIELD_LAST      := NULL;
        V_MQRY_FIELD_PRODREADY := NULL;
        V_PIVOT_AGG            := NULL;
        V_OEE_PIVOT            := NULL; /* AJS 20261007 속도 */

        FOR C1 IN ( SELECT YYYYMMDD
                      FROM ( SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                                  , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                               FROM SCM_SYS_CALENDAR_M A
                              WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM
                                  , A.MONTH_NAME
                           ) IA
                     WHERE YYYYMMDD LIKE 'M_%'
                  ORDER BY SORT_ORDER_NO )
        LOOP
--            V_MQRY_FIELD_PRODREADY := V_MQRY_FIELD_PRODREADY
--                                   || '     , CASE WHEN MEASURE_UI = ''DAILY_CAPA'''                       || CHR(10)
--                                   || '            THEN NVL( ( SELECT MAX(VALUE)'                           || CHR(10)
--                                   || '                          FROM GT_SCP0098_OEE_TERM'                  || CHR(10)
--                                   || '                         WHERE DIVISION_ID  = A.DIVISION_ID'         || CHR(10)
--                                   || '                           AND PLANT_ID     = A.PLANT_ID'            || CHR(10)
--                                   || '                           AND FACTORY_ID   = A.FACTORY_ID'          || CHR(10)
--                                   || '                           AND OPERATION_ID = A.OPERATION_ID'        || CHR(10)
--                                   || '                           AND LINE_ID      = A.LINE_ID'             || CHR(10)
--                                   || '                           AND ITEM_ID      = A.ITEM_ID'             || CHR(10)
--                                   || '                           AND YYYYMM       = ''' || SUBSTR(C1.YYYYMMDD, 3) || ''' ), 0)' || CHR(10)
--                                   || '            ELSE NULL'                                               || CHR(10)
--                                   || '       END AS ' || C1.YYYYMMDD                                       || CHR(10);
            V_MQRY_FIELD_PRODREADY := V_MQRY_FIELD_PRODREADY /* AJS 20261007 속도 */
                                   || '     , CASE WHEN MEASURE_UI = ''DAILY_CAPA'''                       || CHR(10) /* AJS 20261007 속도 */
                                   || '            THEN NVL(XA.OEE_' || C1.YYYYMMDD || ', 0)'               || CHR(10) /* AJS 20261007 속도 */
                                   || '            ELSE NULL'                                               || CHR(10) /* AJS 20261007 속도 */
                                   || '       END AS ' || C1.YYYYMMDD                                       || CHR(10); /* AJS 20261007 속도 */

            V_OEE_PIVOT := V_OEE_PIVOT /* AJS 20261007 속도 */
                        || '              , MAX(CASE WHEN YYYYMM = ''' || SUBSTR(C1.YYYYMMDD, 3) || ''' THEN VALUE END) AS OEE_' || C1.YYYYMMDD || CHR(10); /* AJS 20261007 속도 */
        END LOOP;

        FOR C2 IN ( SELECT YYYYMMDD
                      FROM ( SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                                  , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                               FROM SCM_SYS_CALENDAR_M A
                              WHERE A.BASIS_YYYYMMDD >= P_FROM_YYYYMMDD
                                AND A.BASIS_YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMMDD
                           ) IA
                     WHERE YYYYMMDD LIKE 'D_%'
                  ORDER BY SORT_ORDER_NO )
        LOOP
            V_MQRY_FIELD := V_MQRY_FIELD || '     , ' || C2.YYYYMMDD || CHR(10);

            V_PIVOT_AGG  := V_PIVOT_AGG
                         || '     , MAX(CASE WHEN A.BASIS_YYYYMMDD = ''' || C2.YYYYMMDD || ''' THEN A.VALUE END) AS ' || C2.YYYYMMDD || CHR(10);

            V_MQRY_FIELD_LAST := V_MQRY_FIELD_LAST
                              || '     , CASE WHEN MEASURE_UI = ''NO_WORK''   AND ' || C2.YYYYMMDD || ' = 1  THEN ''Y'''  || CHR(10)
                              || '            WHEN MEASURE_UI = ''NO_WORK''   AND ' || C2.YYYYMMDD || ' != 1 THEN '''''   || CHR(10)
                              || '            WHEN MEASURE_UI = ''LOAD_RATE'' THEN NVL(TO_CHAR(' || C2.YYYYMMDD || ', ''FM999999999999990.00''), ''100'')' || CHR(10)
                              || '            WHEN MEASURE_UI = ''RAMP_UP''   THEN NVL(TO_CHAR(' || C2.YYYYMMDD || ', ''FM999999999999990.00''), ''1'')'   || CHR(10)
                              || '            ELSE TO_CHAR(' || C2.YYYYMMDD || ', ''FM999999999999990.00'')'  || CHR(10)
                              || '       END AS ' || C2.YYYYMMDD                                            || CHR(10);
        END LOOP;

        V_MEXEC := 'SELECT DIVISION_ID'                                              || CHR(10)
                || '     , PLANT_ID'                                                 || CHR(10)
                || '     , FACTORY_ID'                                               || CHR(10)
                || '     , OPERATION_ID'                                             || CHR(10)
                || '     , LINE_ID'                                                  || CHR(10)
                || '     , MEASURE_UI'                                               || CHR(10)
                || '     , ITEM_ID'                                                  || CHR(10)
                || '     , ITEM_NAME'                                                || CHR(10)
                || '     , FACTORY_NAME'                                             || CHR(10)
                || '     , LINE_NAME'                                                || CHR(10)
                || '     , MEASURE_NAME'                                             || CHR(10)
                || '     , SORT_ORDER_NO'                                            || CHR(10)
                || V_MQRY_FIELD_PRODREADY
                || V_MQRY_FIELD_LAST
                || '     , NVL(PRODUCT_READY, 100) AS PRODUCT_READY'                 || CHR(10)
                || '  FROM ( SELECT DATA.DIVISION_ID'                                || CHR(10)
                || '              , DATA.PLANT_ID'                                   || CHR(10)
                || '              , DATA.FACTORY_ID'                                 || CHR(10)
                || '              , DATA.OPERATION_ID'                               || CHR(10)
                || '              , DATA.LINE_ID'                                    || CHR(10)
                || '              , DATA.MEASURE_UI'                                 || CHR(10)
                || '              , DATA.ITEM_ID'                                    || CHR(10)
                || '              , DATA.ITEM_NAME'                                  || CHR(10)
                || '              , DATA.FACTORY_NAME'                               || CHR(10)
                || '              , DATA.LINE_NAME'                                  || CHR(10)
                || '              , DATA.MEASURE_NAME'                               || CHR(10)
                || '              , DATA.SORT_ORDER_NO'                              || CHR(10)
                || REPLACE(V_MQRY_FIELD, '     , ', '              , DATA.')
                || '              , ( SELECT MAX(PROD_READY_RATE)'                   || CHR(10)
                || '                    FROM GT_SCP0098_PROD_READY_RATE'             || CHR(10)
                || '                   WHERE DIVISION_ID  = DATA.DIVISION_ID'        || CHR(10)
                || '                     AND PLANT_ID     = DATA.PLANT_ID'           || CHR(10)
                || '                     AND FACTORY_ID   = DATA.FACTORY_ID'         || CHR(10)
                || '                     AND OPERATION_ID = DATA.OPERATION_ID'       || CHR(10)
                || '                     AND LINE_ID      = DATA.LINE_ID ) AS PRODUCT_READY' || CHR(10)
                || '           FROM ( SELECT A.DIVISION_ID'                          || CHR(10)
                || '                       , A.PLANT_ID'                             || CHR(10)
                || '                       , A.FACTORY_ID'                           || CHR(10)
                || '                       , A.OPERATION_ID'                         || CHR(10)
                || '                       , A.LINE_ID'                              || CHR(10)
                || '                       , A.MEASURE   AS MEASURE_UI'              || CHR(10)
                || '                       , A.ITEM_ID   AS ITEM_ID'                 || CHR(10)
                || '                       , L.ITEM_NAME AS ITEM_NAME'               || CHR(10)
                || '                       , L.FACTORY_NAME'                         || CHR(10)
                || '                       , L.LINE_NAME'                            || CHR(10)
                || '                       , L.MEASURE_NAME'                         || CHR(10)
                || '                       , L.SORT_ORDER_NO'                        || CHR(10)
                || REPLACE(V_PIVOT_AGG, '     , ', '                       , ')
                || '                    FROM GT_SCP0098_CAPA_YMD A'                  || CHR(10)
                || '                       , GT_SCP0098_ITEM_MEASURE L'              || CHR(10)
                || '                   WHERE A.DIVISION_ID  = L.DIVISION_ID'         || CHR(10)
                || '                     AND A.PLANT_ID     = L.PLANT_ID'            || CHR(10)
                || '                     AND A.FACTORY_ID   = L.FACTORY_ID'          || CHR(10)
                || '                     AND A.OPERATION_ID = L.OPERATION_ID'        || CHR(10)
                || '                     AND A.LINE_ID      = L.LINE_ID'             || CHR(10)
                || '                     AND A.ITEM_ID      = L.ITEM_ID'             || CHR(10)
                || '                     AND A.MEASURE      = L.MEASURE_UI'          || CHR(10)
                || '                 GROUP BY A.DIVISION_ID'                         || CHR(10)
                || '                        , A.PLANT_ID'                            || CHR(10)
                || '                        , A.FACTORY_ID'                          || CHR(10)
                || '                        , A.OPERATION_ID'                        || CHR(10)
                || '                        , A.LINE_ID'                             || CHR(10)
                || '                        , A.MEASURE'                             || CHR(10)
                || '                        , A.ITEM_ID'                             || CHR(10)
                || '                        , L.ITEM_NAME'                           || CHR(10)
                || '                        , L.FACTORY_NAME'                        || CHR(10)
                || '                        , L.LINE_NAME'                           || CHR(10)
                || '                        , L.MEASURE_NAME'                        || CHR(10)
                || '                        , L.SORT_ORDER_NO'                       || CHR(10)
                || '                  UNION ALL'                                     || CHR(10)
                || '                  SELECT A.DIVISION_ID'                          || CHR(10)
                || '                       , A.PLANT_ID'                             || CHR(10)
                || '                       , A.FACTORY_ID'                           || CHR(10)
                || '                       , A.OPERATION_ID'                         || CHR(10)
                || '                       , A.LINE_ID'                              || CHR(10)
                || '                       , A.MEASURE AS MEASURE_UI'                || CHR(10)
                || '                       , '' ''     AS ITEM_ID'                   || CHR(10)
                || '                       , '' ''     AS ITEM_NAME'                  || CHR(10)
                || '                       , L.FACTORY_NAME'                         || CHR(10)
                || '                       , L.LINE_NAME'                            || CHR(10)
                || '                       , L.MEASURE_NAME'                         || CHR(10)
                || '                       , L.SORT_ORDER_NO'                        || CHR(10)
                || REPLACE(V_PIVOT_AGG, '     , ', '                       , ')
                || '                    FROM GT_SCP0098_MEAS_WORK A'                 || CHR(10)
                || '                       , GT_SCP0098_LINE_MEAS_DIST L'            || CHR(10)
                || '                   WHERE A.DIVISION_ID  = L.DIVISION_ID'         || CHR(10)
                || '                     AND A.PLANT_ID     = L.PLANT_ID'            || CHR(10)
                || '                     AND A.FACTORY_ID   = L.FACTORY_ID'          || CHR(10)
                || '                     AND A.OPERATION_ID = L.OPERATION_ID'        || CHR(10)
                || '                     AND A.LINE_ID      = L.LINE_ID'             || CHR(10)
                || '                     AND A.MEASURE      = L.MEASURE_UI'          || CHR(10)
                || '                     AND A.MEASURE      != ''DAILY_CAPA'''       || CHR(10)
                || '                 GROUP BY A.DIVISION_ID'                         || CHR(10)
                || '                        , A.PLANT_ID'                            || CHR(10)
                || '                        , A.FACTORY_ID'                          || CHR(10)
                || '                        , A.OPERATION_ID'                        || CHR(10)
                || '                        , A.LINE_ID'                             || CHR(10)
                || '                        , A.MEASURE'                             || CHR(10)
                || '                        , L.FACTORY_NAME'                        || CHR(10)
                || '                        , L.LINE_NAME'                           || CHR(10)
                || '                        , L.MEASURE_NAME'                        || CHR(10)
                || '                        , L.SORT_ORDER_NO'                       || CHR(10)
                || '                ) DATA'                                          || CHR(10)
                || '       ) A'                                                      || CHR(10)
                || '     , ( SELECT DIVISION_ID  AS OT_DIVISION_ID'                  || CHR(10) /* AJS 20261007 속도 */
                || '              , PLANT_ID     AS OT_PLANT_ID'                     || CHR(10) /* AJS 20261007 속도 */
                || '              , FACTORY_ID   AS OT_FACTORY_ID'                   || CHR(10) /* AJS 20261007 속도 */
                || '              , OPERATION_ID AS OT_OPERATION_ID'                 || CHR(10) /* AJS 20261007 속도 */
                || '              , LINE_ID      AS OT_LINE_ID'                      || CHR(10) /* AJS 20261007 속도 */
                || '              , ITEM_ID      AS OT_ITEM_ID'                      || CHR(10) /* AJS 20261007 속도 */
                || V_OEE_PIVOT /* AJS 20261007 속도 */
                || '           FROM GT_SCP0098_OEE_TERM'                             || CHR(10) /* AJS 20261007 속도 */
                || '          GROUP BY DIVISION_ID'                                  || CHR(10) /* AJS 20261007 속도 */
                || '                 , PLANT_ID'                                     || CHR(10) /* AJS 20261007 속도 */
                || '                 , FACTORY_ID'                                   || CHR(10) /* AJS 20261007 속도 */
                || '                 , OPERATION_ID'                                 || CHR(10) /* AJS 20261007 속도 */
                || '                 , LINE_ID'                                      || CHR(10) /* AJS 20261007 속도 */
                || '                 , ITEM_ID ) XA'                                 || CHR(10) /* AJS 20261007 속도 */
                || ' WHERE XA.OT_DIVISION_ID(+)  = A.DIVISION_ID'                    || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_PLANT_ID(+)     = A.PLANT_ID'                       || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_FACTORY_ID(+)   = A.FACTORY_ID'                     || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_OPERATION_ID(+) = A.OPERATION_ID'                   || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_LINE_ID(+)      = A.LINE_ID'                        || CHR(10) /* AJS 20261007 속도 */
                || '   AND XA.OT_ITEM_ID(+)      = A.ITEM_ID'                        || CHR(10) /* AJS 20261007 속도 */
                || 'ORDER BY DIVISION_ID'                                            || CHR(10)
                || '       , PLANT_ID'                                               || CHR(10)
                || '       , FACTORY_ID'                                             || CHR(10)
                || '       , OPERATION_ID'                                           || CHR(10)
                || '       , LINE_ID'                                                || CHR(10)
                || '       , SORT_ORDER_NO'                                          || CHR(10)
                || '       , ITEM_ID'                                                || CHR(10)
        ;

        OPEN O_RC FOR V_MEXEC;

        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 0
        ;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MESSAGE := SQLERRM;

            OPEN O_RC FOR
                SELECT NULL AS DUMMY
                  FROM DUAL
                 WHERE 1 = 0
            ;

            OPEN O_RESULT_CURSOR FOR
                SELECT V_ERR_MESSAGE AS ERR_MESSAGE
                  FROM DUAL
            ;
    END P_GET_CAPA_MOBILITYIT_LINE;

/*==================================================================================================
 * Program ID   : SCP0098_SAVE_SCP_CAPA
 * Description  : SCP CAPA SAVE
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2023/08/25   vadabi3      최초작성
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *==================================================================================================*/
    PROCEDURE P_SAVE_SCP_CAPA (
        P_ACTIVE_FLAG   IN  VARCHAR2
      , P_DIVISION_ID   IN  VARCHAR2
      , P_PLANT_ID      IN  VARCHAR2
      , P_FACTORY_ID    IN  VARCHAR2
      , P_OPERATION_ID  IN  VARCHAR2
      , P_LINE_ID       IN  VARCHAR2
      , P_ITEM_ID       IN  VARCHAR2
      , P_YYYYMM        IN  VARCHAR2
      , P_VALUE         IN  VARCHAR2
      , P_USER_ID       IN  VARCHAR2
      , O_RC            OUT SYS_REFCURSOR
      , O_RESULT_CURSOR OUT SYS_REFCURSOR
    )
    IS
        /* 변수 선언 */
        V_MAX_LOOP_CNT      NUMBER(10) := 0;
        V_MST_LOOP_CNT      NUMBER(10) := 0;
        V_DELIMITER         VARCHAR2(1 CHAR);

        /* 변수 설정 */
        V_DIVISION_ID       VARCHAR2(4000 CHAR);
        V_PLANT_ID          VARCHAR2(4000 CHAR);
        V_FACTORY_ID        VARCHAR2(4000 CHAR);
        V_OPERATION_ID      VARCHAR2(4000 CHAR);
        V_LINE_ID           VARCHAR2(4000 CHAR);
        V_ITEM_ID           VARCHAR2(4000 CHAR);
        V_YYYYMM            VARCHAR2(4000 CHAR);
        V_VALUE             VARCHAR2(4000 CHAR);
        V_UPD_CNT           NUMBER(10) := 0;
        /* AS-IS 는 결과의 @@ROWCOUNT 를 WHILE 루프를 빠져나온 뒤에 읽어 언제나 0 을 돌려준다. 같은 값으로 맞춘다. */
        V_UPDATE_ROW        NUMBER(10) := 0;

        /* Start Log */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0098_SAVE_SCP_CAPA';
        V_LOG_TYPE          VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);
    BEGIN

        V_DELIMITER    := '^';
        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER));

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := P_USER_ID || ' : ' || P_ITEM_ID;
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_MAX_LOOP_CNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;
            V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_DIVISION_ID , V_DELIMITER, V_MST_LOOP_CNT);
            V_PLANT_ID     := SCM_ARR_SPL_VAL(P_PLANT_ID    , V_DELIMITER, V_MST_LOOP_CNT);
            V_FACTORY_ID   := SCM_ARR_SPL_VAL(P_FACTORY_ID  , V_DELIMITER, V_MST_LOOP_CNT);
            V_OPERATION_ID := SCM_ARR_SPL_VAL(P_OPERATION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_LINE_ID      := SCM_ARR_SPL_VAL(P_LINE_ID     , V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID      := SCM_ARR_SPL_VAL(P_ITEM_ID     , V_DELIMITER, V_MST_LOOP_CNT);
            V_YYYYMM       := SCM_ARR_SPL_VAL(P_YYYYMM      , V_DELIMITER, V_MST_LOOP_CNT);
            V_VALUE        := SCM_ARR_SPL_VAL(P_VALUE       , V_DELIMITER, V_MST_LOOP_CNT);

            /* AS-IS MERGE 를 UPDATE + INSERT 로 나눈 것 (온라인 SQL 은 MERGE 를 쓰지 않는다) */
            UPDATE SCP_MST_CAPA
               SET VALUE            = TO_NUMBER(V_VALUE)
                 , LAST_UPDATED_BY  = P_USER_ID
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE DIVISION_ID  = V_DIVISION_ID
               AND PLANT_ID     = V_PLANT_ID
               AND FACTORY_ID   = V_FACTORY_ID
               AND OPERATION_ID = V_OPERATION_ID
               AND LINE_ID      = V_LINE_ID
               AND ITEM_ID      = V_ITEM_ID
               AND YYYYMM       = V_YYYYMM
            ;

            V_UPD_CNT := SQL%ROWCOUNT;

            IF V_UPD_CNT = 0 THEN

                INSERT INTO SCP_MST_CAPA
                     ( DIVISION_ID
                     , PLANT_ID
                     , FACTORY_ID
                     , OPERATION_ID
                     , LINE_ID
                     , ITEM_ID
                     , YYYYMM
                     , VALUE
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     )
                VALUES
                     ( V_DIVISION_ID
                     , V_PLANT_ID
                     , V_FACTORY_ID
                     , V_OPERATION_ID
                     , V_LINE_ID
                     , V_ITEM_ID
                     , V_YYYYMM
                     , TO_NUMBER(V_VALUE)
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     )
                ;

                V_UPD_CNT := SQL%ROWCOUNT;

            END IF;

        END LOOP;

        /* Finish Log */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := P_USER_ID || ' : ' || P_VALUE;
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        /* 결과 코드 반환 */
        OPEN O_RC FOR
            SELECT 'S'          AS RESULT_CODE
                 , V_UPDATE_ROW AS UPDATE_ROW
              FROM DUAL
        ;

        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 0
        ;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MESSAGE := SQLERRM;

            /* Error Log */
            INSERT INTO SCM_SYS_LOG_BATCH ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, P_USER_ID || P_VALUE, SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME )
            ;

            /* AS-IS 는 CATCH 에서 ROLLBACK 없이 COMMIT WORK 를 한다. 같은 동작으로 둔다. */
            COMMIT;

            OPEN O_RC FOR
                SELECT 'S' AS RESULT_CODE
                     , 0   AS UPDATE_ROW
                  FROM DUAL
                 WHERE 1 = 0
            ;

            OPEN O_RESULT_CURSOR FOR
                SELECT V_ERR_MESSAGE AS ERR_MESSAGE
                  FROM DUAL
            ;
    END P_SAVE_SCP_CAPA;

/*==================================================================================================
 * Program ID   : SCP0098_SAVE_SCP_CAPA_PRODUCT_RATE
 * Description  : SCP CAPA SAVE
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2023/08/25   vadabi3      최초작성
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *==================================================================================================*/
    PROCEDURE P_SAVE_SCP_CAPA_PRODUCT_RATE (
        P_ACTIVE_FLAG     IN  VARCHAR2
      , P_DIVISION_ID     IN  VARCHAR2
      , P_PLANT_ID        IN  VARCHAR2
      , P_FACTORY_ID      IN  VARCHAR2
      , P_OPERATION_ID    IN  VARCHAR2
      , P_LINE_ID         IN  VARCHAR2
      , P_START_YYYYMMDD  IN  VARCHAR2
      , P_END_YYYYMMDD    IN  VARCHAR2
      , P_PRODUCT_RATE    IN  VARCHAR2
      , P_USER_ID         IN  VARCHAR2
      , O_RC              OUT SYS_REFCURSOR
      , O_RESULT_CURSOR   OUT SYS_REFCURSOR
    )
    IS
        /* 변수 선언 */
        V_MAX_LOOP_CNT      NUMBER(10) := 0;
        V_MST_LOOP_CNT      NUMBER(10) := 0;
        V_DELIMITER         VARCHAR2(1 CHAR);

        /* 변수 설정 */
        V_DIVISION_ID       VARCHAR2(4000 CHAR);
        V_PLANT_ID          VARCHAR2(4000 CHAR);
        V_FACTORY_ID        VARCHAR2(4000 CHAR);
        V_OPERATION_ID      VARCHAR2(4000 CHAR);
        V_LINE_ID           VARCHAR2(4000 CHAR);
        V_YYYYMMDD          VARCHAR2(4000 CHAR);
        V_PRODUCT_RATE      VARCHAR2(4000 CHAR);
        V_UPD_CNT           NUMBER(10) := 0;
        /* AS-IS 는 결과의 @@ROWCOUNT 를 WHILE 루프를 빠져나온 뒤에 읽어 언제나 0 을 돌려준다. 같은 값으로 맞춘다. */
        V_UPDATE_ROW        NUMBER(10) := 0;

        /* Start Log */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SCP0098_SAVE_SCP_CAPA_PRODUCT_RATE';
        V_LOG_TYPE          VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER(10) := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;

        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);
    BEGIN

        V_DELIMITER    := '^';
        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER));

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := P_USER_ID || ' : ' || P_START_YYYYMMDD || ' : ' || P_END_YYYYMMDD || ' : ' || P_LINE_ID;
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_MAX_LOOP_CNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        /* TODAY 해당월의 1일 부터 업데이트 구간 */
        V_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMM') || '01';

        WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;
            V_DIVISION_ID  := SCM_ARR_SPL_VAL(P_DIVISION_ID , V_DELIMITER, V_MST_LOOP_CNT);
            V_PLANT_ID     := SCM_ARR_SPL_VAL(P_PLANT_ID    , V_DELIMITER, V_MST_LOOP_CNT);
            V_FACTORY_ID   := SCM_ARR_SPL_VAL(P_FACTORY_ID  , V_DELIMITER, V_MST_LOOP_CNT);
            V_OPERATION_ID := SCM_ARR_SPL_VAL(P_OPERATION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_LINE_ID      := SCM_ARR_SPL_VAL(P_LINE_ID     , V_DELIMITER, V_MST_LOOP_CNT);
            V_PRODUCT_RATE := SCM_ARR_SPL_VAL(P_PRODUCT_RATE, V_DELIMITER, V_MST_LOOP_CNT);

            /* AS-IS MERGE 를 UPDATE + INSERT 로 나눈 것 (온라인 SQL 은 MERGE 를 쓰지 않는다) */
            /* AS-IS 와 같이 MEASURE 조건이 없어 기준일 이후의 모든 측정값 행이 함께 갱신된다 */
            UPDATE SCP_MST_CAPA_WORK
               SET PROD_READY_RATE  = TO_NUMBER(V_PRODUCT_RATE)
                 , LAST_UPDATED_BY  = P_USER_ID
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE DIVISION_ID  = V_DIVISION_ID
               AND PLANT_ID     = V_PLANT_ID
               AND FACTORY_ID   = V_FACTORY_ID
               AND OPERATION_ID = V_OPERATION_ID
               AND LINE_ID      = V_LINE_ID
               AND YYYYMMDD     >= V_YYYYMMDD
             /*AND YYYYMMDD     LIKE '%01' */
            ;

            V_UPD_CNT := SQL%ROWCOUNT;

            IF V_UPD_CNT = 0 THEN

                INSERT INTO SCP_MST_CAPA_WORK
                     ( DIVISION_ID
                     , PLANT_ID
                     , FACTORY_ID
                     , OPERATION_ID
                     , LINE_ID
                     , MEASURE
                     , YYYYMMDD
                     , PROD_READY_RATE
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     )
                VALUES
                     ( V_DIVISION_ID
                     , V_PLANT_ID
                     , V_FACTORY_ID
                     , V_OPERATION_ID
                     , V_LINE_ID
                     , 'NO_WORK'
                     , P_START_YYYYMMDD
                     , TO_NUMBER(V_PRODUCT_RATE)
                     , P_USER_ID
                     , SYSDATE
                     , P_USER_ID
                     , SYSDATE
                     )
                ;

                V_UPD_CNT := SQL%ROWCOUNT;

            END IF;

        END LOOP;

        /* Finish Log */
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := P_USER_ID || ' : ' || P_PRODUCT_RATE;
        D_EVENT_DATE  := SYSDATE;

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        /* 결과 코드 반환 */
        OPEN O_RC FOR
            SELECT 'S'          AS RESULT_CODE
                 , V_UPDATE_ROW AS UPDATE_ROW
              FROM DUAL
        ;

        OPEN O_RESULT_CURSOR FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 0
        ;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MESSAGE := SQLERRM;

            /* Error Log */
            INSERT INTO SCM_SYS_LOG_BATCH ( PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION, EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY )
            VALUES ( V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, P_USER_ID || P_PRODUCT_RATE, SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME )
            ;

            /* AS-IS 는 CATCH 에서 ROLLBACK 없이 COMMIT WORK 를 한다. 같은 동작으로 둔다. */
            COMMIT;

            OPEN O_RC FOR
                SELECT 'S' AS RESULT_CODE
                     , 0   AS UPDATE_ROW
                  FROM DUAL
                 WHERE 1 = 0
            ;

            OPEN O_RESULT_CURSOR FOR
                SELECT V_ERR_MESSAGE AS ERR_MESSAGE
                  FROM DUAL
            ;
    END P_SAVE_SCP_CAPA_PRODUCT_RATE;

