--                 , SUM(TO_BOH_QTY)              AS TO_BOH_QTY
--                 , MAX(CELL_CF)                 AS CELL_CF
--              FROM GT_SCP0100_RAW
--             GROUP BY YYYYPW
--                    , DIVISION_ID
--                    , PLAN_TYPE
--                    , CELL_GROUP
--                    , OPERATION_GROUP
--                    , PRODUCT_LEVEL1
--                    , MEASURE;
--  2026.10.07 AJS (END)

            INSERT INTO GT_SCP0100_RAW_CELL_CF
            (
                DIVISION_ID
              , PLAN_TYPE
              , CELL_GROUP
              , OPERATION_GROUP
              , PRODUCT_LEVEL1
              , MEASURE
            )
            SELECT DIVISION_ID
                 , PLAN_TYPE                    /* E20260708-000926 */
                 , CELL_GROUP
                 , OPERATION_GROUP
                 , PRODUCT_LEVEL1
                 , MEASURE
              FROM GT_SCP0100_RAW
             GROUP BY DIVISION_ID
                    , PLAN_TYPE
                    , CELL_GROUP
                    , OPERATION_GROUP
