              , OPERATION_GROUP
              , PRODUCT_LEVEL2
              , MEASURE
            )
            SELECT DIVISION_ID
                 , PLAN_TYPE                    /* E20260708-000926 */
                 , CELL_GROUP
                 , OPERATION_GROUP
