                 , MEASURE
              FROM GT_SCP0100_RAW
             GROUP BY DIVISION_ID
                    , PLAN_TYPE
                    , CELL_GROUP
                    , OPERATION_GROUP
                    , PRODUCT_LEVEL2
                    , MEASURE;

            /* 연월별 수량 칸 */
            FOR R IN ( SELECT YYYYPW_NAME
