                        ORDER BY SORT_ORDER_NO
                     )
            LOOP
                DBMS_LOB.APPEND(V_QTY_COLS, TO_CLOB(
--  2026.10.07 AJS (START) 칸별 스칼라 하위질의 -> 수량 집계 한 번 바깥 조인 + CASE
--                    CHR(10) || '     , ( SELECT SA.QTY' || CHR(10)
