-- My Work
PROCEDURE P_SDM1010_GET_POP_MY_WORK (
    P_DIVISION_ID               IN VARCHAR2
  , P_DPJT_KEY                  IN VARCHAR2
  , P_SES_USER_ID               IN VARCHAR2
  , O_CURSOR                    OUT SYS_REFCURSOR
  , O_RESULT_CURSOR             OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : PKG_SDM1010.P_SDM1010_GET_POP_MY_WORK
 * Description  : Organization List
 * Parameter    : 
 * Program History
 *====================================================================================================
 *   Date       In Charge      Description
 *====================================================================================================
 * 2026.08.06   KTJ         최초 작성
 *                          프로젝트 등록
 * ---------------------------------------------------------------------------------------------------
 * 
 * ---------------------------------------------------------------------------------------------------
 */

    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100  CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
    n_log_count         PLS_INTEGER := 0;
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := $$PLSQL_UNIT;


BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    END IF;

    OPEN O_CURSOR FOR
        SELECT PJM.DPJT_KEY, PJM.DPJT_CODE, PJM.DPJT_SEQ
             , PJM.DIVISION_ID, DIV.DIVISION_ID DIVISION_NAME
             , PJM.DPJT_CLASS, PCL.DPJT_CLASS_NAME
             , PJM.END_CUSTOMER, NVL(EDC.END_CUSTOMER_NAME, PJM.END_CUSTOMER) END_CUSTOMER_NAME
             , PJM.DPJT_NAME
             --
             , TO_DATE('20260701', 'YYYYMMDD') AS SAMPLE_A_DATE
             , TO_DATE('20261001', 'YYYYMMDD') AS SAMPLE_B_DATE
             , TO_DATE('20260104', 'YYYYMMDD') AS SAMPLE_C_DATE
             , TO_DATE('20260402', 'YYYYMMDD') AS SAMPLE_D_DATE
             --
             , PJM.SOP_DATE
             , PJM.SOP_PLANT_ID, NVL(PLT.SOP_PLANT_NAME, PJM.SOP_PLANT_ID) AS SOP_PLANT_NAME
          FROM SCM_MGR.SPMS_PROJECT_MST PJM
         INNER JOIN
               SCM_MGR.SCM_MST_DIVISION DIV
            ON 0 = 0
           AND PJM.DIVISION_ID = DIV.DIVISION_ID
         INNER JOIN
               (
                    SELECT LKD.SEGMENT1 AS DPJT_CLASS_ID
                         , LKD.SEGMENT2 AS DPJT_CLASS_NAME
                      FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER LKM
                     INNER JOIN
                           SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL LKD
                        ON 0 = 0
                       AND LKM.LOOKUP_TYPE = LKD.LOOKUP_TYPE
                       AND LKD.VALID_YN = 'Y'
                     WHERE 0 = 0
                       AND LKM.LOOKUP_TYPE = 'SPMS_DPJT_CLASS'
                       AND LKM.VALID_YN = 'Y'
               ) PCL
            ON 0 = 0
           AND PJM.DPJT_CLASS = PCL.DPJT_CLASS_ID
          LEFT OUTER JOIN
               (
                    SELECT DISTINCT
                           SIT.DIVISION_ID, SIT.END_CUSTOMER, SIT.END_CUSTOMER END_CUSTOMER_NAME
                      FROM SCM_MGR.SCM_MST_SITE SIT
                     WHERE 0 = 0
               ) EDC
            ON 0 = 0
           AND PJM.DIVISION_ID  = EDC.DIVISION_ID
           AND PJM.END_CUSTOMER = EDC.END_CUSTOMER
          LEFT OUTER JOIN
               (
                    SELECT DISTINCT
                           SIT.DIVISION_ID, SIT.PLANT_ID SOP_PLANT_ID, SIT.PLANT_ID SOP_PLANT_NAME
                      FROM SCM_MGR.SCM_MST_PLANT_SN SIT
                     WHERE 0 = 0
                     /*
                    SELECT DISTINCT
                           SIT.DIVISION_ID, SIT.SCM_SITE_ID SOP_PLANT_ID, SIT.SCM_SITE_ID SOP_PLANT_NAME
                      FROM SCM_MGR.SCM_MST_SITE SIT
                     WHERE 0 = 0
                       AND SIT.SITE_TYPE = 'PLANT'
                       */
               ) PLT
            ON 0 = 0
           AND PJM.DIVISION_ID  = PLT.DIVISION_ID
           AND PJM.SOP_PLANT_ID = PLT.SOP_PLANT_ID
         WHERE 0 = 0
           --
           --AND PJM.DIVISION_ID  = P_DIVISION_ID
           AND PJM.DPJT_KEY     = P_DPJT_KEY
        ;
    
    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := JSON_OBJECT(
            'P_DIVISION_ID'                 VALUE P_DIVISION_ID
          , 'P_DPJT_KEY'                    VALUE P_DPJT_KEY
          , 'P_SES_USER_ID'                 VALUE P_SES_USER_ID
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', n_log_count, 'EXCEPTION', '', SYSDATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END P_SDM1010_GET_POP_MY_WORK;

-- 조회구간 정보 (Default 값)
PROCEDURE P_SDM1010_GET_PERIOD (
    P_FR_BUCKET                 IN VARCHAR2         -- From 일자 계산 기준 Bucket 값 - D(Day) / W(Week) / PW(Partial Week) / M(Month) / Y(Year)
  , P_FR_DATE_VAL               IN VARCHAR2         -- From 일자 계산 값 - 음수 가능
  , P_FR_BUCKET_TYPE            IN VARCHAR2         -- From 일자 지정 기준 - S : Bucket 시작일 / E : Bucket 종료일 / C : 해당일
  , P_TO_BUCKET                 IN VARCHAR2         -- to   일자 계산 기준 Bucket 값
  , P_TO_DATE_VAL               IN VARCHAR2         -- to   일자 계산 값
  , P_TO_BUCKET_TYPE            IN VARCHAR2         -- to   일자 지정 기준 - S : Bucket 시작일 / E : Bucket 종료일 / C : 해당일 / X : From 일자만 반환
  , P_SES_USER_ID               IN VARCHAR2
  , O_CURSOR                    OUT SYS_REFCURSOR
  , O_RESULT_CURSOR             OUT SYS_REFCURSOR
)
AS
/*
 * Program ID   : PKG_SDM1010.P_SDM1010_GET_PERIOD
 * Description  : 날짜 구간 값 반환 : 조회조건 Default 값
 * Parameter    : 
 * Program History
 *====================================================================================================
 *   Date       In Charge      Description
 *====================================================================================================
 * 2026.08.12   KTJ         최초 작성
 *                          프로젝트 등록
 * ---------------------------------------------------------------------------------------------------
 * 
 * ---------------------------------------------------------------------------------------------------
 */

    V_PROC_INPUT        VARCHAR2(4000 CHAR);
    V_BACKTRACE         VARCHAR2(4000 CHAR);
    V_SQL_CODE          VARCHAR2(100  CHAR);
    V_SQL_ERRMSG        VARCHAR2(1000 CHAR);
    n_log_count         PLS_INTEGER := 0;
    V_PROGRAM_NAME      VARCHAR2(150 CHAR) := $$PLSQL_UNIT;

    D_TODAY             DATE := TRUNC(SYSDATE);
    D_FR_BASE           DATE;
    D_TO_BASE           DATE;
    N_FR_DATE_VAL       INTEGER := TO_NUMBER(P_FR_DATE_VAL);
    N_TO_DATE_VAL       INTEGER := TO_NUMBER(P_TO_DATE_VAL);
    D_FR_DATE           DATE;
    D_TO_DATE           DATE;

BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1)(2);
    END IF;
    
    -- Calendar 참고 : SCM_SYS_CALENDAR_M - Week 관련 해당 테이블 참조 필요
    
    -- 1. 구간 시작일자 산정
    IF    UPPER(P_FR_BUCKET) IN ('D', 'DAY') THEN
        D_FR_BASE := D_TODAY + N_FR_DATE_VAL;
        D_FR_DATE := D_FR_BASE;
    ELSIF UPPER(P_FR_BUCKET) IN ('W', 'WK', 'WEEK') THEN
        D_FR_BASE := D_TODAY + ( N_FR_DATE_VAL * 7 );
        -- 시작일 기준
        IF    UPPER(P_FR_BUCKET_TYPE) IN ('S', 'START') THEN
            D_FR_DATE := TRUNC(D_FR_BASE, 'IW');    -- 월요일 기준
            --D_FR_DATE := TRUNC(D_FR_BASE, 'D');     -- 일요일 기준
        -- 종료일 기준
        ELSIF UPPER(P_FR_BUCKET_TYPE) IN ('E', 'END') THEN
            D_FR_DATE := TRUNC(D_FR_BASE, 'IW') + 6;    -- 월요일 기준
            --D_FR_DATE := TRUNC(D_FR_BASE, 'D') + 6;     -- 일요일 기준
        ELSE
            D_FR_DATE := D_FR_BASE;
        END IF;
    ELSIF UPPER(P_FR_BUCKET) IN ('M', 'MON', 'MONTH') THEN
        D_FR_DATE := ADD_MONTHS(D_TODAY, N_FR_DATE_VAL);
        -- 시작일 기준
        IF    UPPER(P_FR_BUCKET_TYPE) IN ('S', 'START') THEN
            D_FR_DATE := TRUNC(D_FR_DATE, 'MONTH');
        -- 종료일 기준
        ELSIF UPPER(P_FR_BUCKET_TYPE) IN ('E', 'END') THEN
            D_FR_DATE := LAST_DAY(D_FR_DATE);
        ELSE
            D_FR_DATE := D_FR_BASE;
        END IF;
    END IF;
    
    -- 2. 구간 종료일자 산정
    IF    UPPER(P_FR_BUCKET) IN ('D', 'DAY') THEN
        D_TO_BASE := D_TODAY + N_TO_DATE_VAL;
        D_TO_DATE := D_TO_BASE;
    ELSIF UPPER(P_FR_BUCKET) IN ('W', 'WK', 'WEEK') THEN
        D_TO_BASE := D_TODAY + ( N_TO_DATE_VAL * 7 );
        -- 시작일 기준
        IF    UPPER(P_TO_BUCKET_TYPE) IN ('S', 'START') THEN
            D_TO_DATE := TRUNC(D_TO_BASE, 'IW');    -- 월요일 기준
            --D_TO_DATE := TRUNC(D_TO_BASE, 'D');     -- 일요일 기준
        -- 종료일 기준
        ELSIF UPPER(P_TO_BUCKET_TYPE) IN ('E', 'END') THEN
            D_TO_DATE := TRUNC(D_TO_BASE, 'IW') + 6;    -- 월요일 기준
            --D_TO_DATE := TRUNC(D_TO_BASE, 'D') + 6;     -- 일요일 기준
        ELSE
            D_TO_DATE := D_TO_BASE;
        END IF;
    ELSIF UPPER(P_TO_BUCKET) IN ('M', 'MON', 'MONTH') THEN
        D_TO_DATE := ADD_MONTHS(D_TODAY, N_TO_DATE_VAL);
        -- 시작일 기준
        IF    UPPER(P_TO_BUCKET_TYPE) IN ('S', 'START') THEN
            D_TO_DATE := TRUNC(D_TO_DATE, 'MONTH');
        -- 종료일 기준
        ELSIF UPPER(P_TO_BUCKET_TYPE) IN ('E', 'END') THEN
            D_TO_DATE := LAST_DAY(D_TO_DATE);
        ELSE
            D_TO_DATE := D_TO_BASE;
        END IF;
    END IF;
    
    IF P_TO_BUCKET_TYPE = 'X' THEN
        OPEN O_CURSOR FOR
            SELECT D_FR_DATE AS DATE_FR
                 , TO_CHAR(D_FR_DATE, 'YYYYMMDD') AS YMD_FR
              FROM DUAL
             WHERE 0 = 0
            ;
    ELSE
        OPEN O_CURSOR FOR
            SELECT D_FR_DATE AS DATE_FR
                 , TO_CHAR(D_FR_DATE, 'YYYYMMDD') AS YMD_FR
                 , D_TO_DATE DATE_TO
                 , TO_CHAR(D_TO_DATE, 'YYYYMMDD') AS YMD_TO
              FROM DUAL
             WHERE 0 = 0
            ;
    END IF;
    
    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;

        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := JSON_OBJECT(
            'P_FR_BUCKET'                   VALUE P_FR_BUCKET
          , 'P_FR_DATE_VAL'                 VALUE P_FR_DATE_VAL
          , 'P_FR_BUCKET_TYPE'              VALUE P_FR_BUCKET_TYPE
          , 'P_TO_BUCKET'                   VALUE P_TO_BUCKET
          , 'P_TO_DATE_VAL'                 VALUE P_TO_DATE_VAL
          , 'P_TO_BUCKET_TYPE'              VALUE P_TO_BUCKET_TYPE
          , 'P_SES_USER_ID'                 VALUE P_SES_USER_ID
        );
        V_BACKTRACE := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'ERROR', n_log_count, 'EXCEPTION', '', SYSDATE, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE); END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END P_SDM1010_GET_PERIOD;

END PKG_SDM1010;
/
SHOW ERRORS PACKAGE BODY PKG_SDM1010
-- ##### END PACKAGE BODY PKG_SDM1010

-- ##### START PACKAGE BODY PKG_SSP0012
CREATE OR REPLACE PACKAGE BODY PKG_SSP0012
IS
    /*
     * Program ID   : PKG_SSP0012
     * Description  : SSP0012 Shipment Plan Detail 화면 - 출하계획 확정 상세
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.25   ZIONEX         [PJ202650304] MSSQL -> Oracle 전환
     * 2026.10.06   AJS            [속도] P_SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL 확정번호별 마지막 이력을 조회 기간 확정번호만 한 번 읽어 계산 · 행마다 부르는 함수 5곳 스칼라 서브쿼리 캐시
     * 2026.10.07   AJS            P_SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL 조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
     *
     * [전환 공통 규칙]
     * - AS-IS 는 문자열을 이어 붙여 만든 동적 SQL 한 문장을 임시 테이블에 담고 그 임시 테이블을 다시 읽는다.
     *   칸 구성이 고정이고 조건만 갈리므로 정적 SQL 한 문장으로 옮겼다(임시 테이블도 필요 없다).
     *   AS-IS FN_GET_IN_STR 은 IN 절 리터럴을 만드는 함수라 Oracle 로 옮기지 않고 토큰 분리 조건으로 바꿨다.
     * - 사용자 TB_FX_User -> SCM_ADM_USER_M (UserID -> USER_ID · UserName -> USER_NM · UserName_E -> USER_ENG_NM · UseYN -> USE_YN)
     * - 이름 + '(' + ID + ')' 결합은 MSSQL 에서 한쪽이 NULL 이면 전체가 NULL 이 되므로 NVL2 로 같은 결과를 만들었다.
     * - AS-IS TOP 1 은 ORDER BY 가 없어 어느 줄이 뽑힐지 정해지지 않는다. ROWNUM = 1 로 옮겼다.
     * - AS-IS ISNULL(NULLIF(x, ''), '-') 는 값이 없거나 빈 값이면 하이픈이다. 이관 공백을 함께 잡도록 TRIM 을 썼다.
     * - 공용 함수 FN_GET_SSP_MKT_OWNER_NAME 은 언어를 대소문자로 가리므로 넘길 때 대문자로 맞춘다.
     *   ★같은 함수가 담당자 아이디도 대소문자로 가려 원장에 대문자로 든 담당자(58명 · 4,319행)의 이름을
     *   되돌리지 못한다. 공용 함수를 고칠 사항이라 이 화면에서는 원문 그대로 두었다(담당자 전달).
     */

    /* ==============================================================================================
       내부 : 결과 커서 (성공)
       ============================================================================================== */
    PROCEDURE P_OPEN_SUCCESS
    (
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;
    END P_OPEN_SUCCESS;

    /* ==============================================================================================
       내부 : 결과 커서 (오류)
       ============================================================================================== */
    PROCEDURE P_OPEN_ERROR
    (
        P_MESSAGE           IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1'      AS CODE
                 , P_MESSAGE AS MSG
              FROM DUAL;
    END P_OPEN_ERROR;

    /* ==============================================================================================
       내부 : 오류 이력 기록
       ============================================================================================== */
    PROCEDURE P_WRITE_ERROR_LOG
    (
        P_PROGRAM_NAME      IN  VARCHAR2,
        P_MESSAGE           IN  VARCHAR2
    )
    IS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        INSERT INTO SCM_SYS_LOG_BATCH
        (
            PROGRAM_NAME
          , LOG_TYPE
          , LOG_COUNT
          , LOG_MESSAGE
          , DESCRIPTION
          , EVENT_DATE
          , CREATION_DATE
          , CREATED_BY
          , LAST_UPDATE_DATE
          , LAST_UPDATED_BY
        )
        VALUES
        (
            P_PROGRAM_NAME
          , 'ERROR'
          , NULL
          , SUBSTR(P_MESSAGE, 1, 1000)
          , NULL
          , SYSDATE
          , SYSDATE
          , P_PROGRAM_NAME
          , SYSDATE
          , P_PROGRAM_NAME
        );

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
    END P_WRITE_ERROR_LOG;

    /* ==============================================================================================
       SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL
       ============================================================================================== */
    PROCEDURE P_SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL
    (
        P_DIVISION_ID       IN  CLOB
      , P_FROM_SITE         IN  CLOB
      , P_ITEM_ID           IN  CLOB
      , P_FROM_YYYYMMDD     IN  VARCHAR2
      , P_TO_YYYYMMDD       IN  VARCHAR2
      , P_SOLD_TO_PARTY     IN  VARCHAR2
      , P_SHIP_TO_PARTY     IN  VARCHAR2
      , P_DEBUG_MODE        IN  VARCHAR2
      , P_LANGUAGE          IN  VARCHAR2
      , O_RC1               OUT SYS_REFCURSOR
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        V_DIVISION_ID       VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_DIVISION_ID, 1, 32767));
        V_FROM_SITE         VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_FROM_SITE, 1, 32767));
        V_ITEM_ID           VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID, 1, 32767));
    BEGIN
        OPEN O_RC1 FOR
            SELECT IA.DIVISION_ID
                 , IA.PLAN_START_YYYYMMDD
                 , IA.PLAN_TYPE
                 , IA.SEQ
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.FROM_SITE_DESCRIPTION
                 , IA.TO_SITE_DESCRIPTION
                 , IA.TO_SITE
                 , IA.YYYYMMDD
                 , IA.BOD_ID
                 , IA.BIZ_TYPE
                 , IA.BIZ_TYPE_NAME
                 , IA.PROJECT_CODE
                 , IA.PROJECT_NAME
                 , IA.NICK_NAME
                 , IA.SOLDTO_DESCRIPTION
                 , IA.SHIPTO_DESCRIPTION
                 , IA.LT_DAY
                 , IA.ETD
                 , IA.ETA
                 , IA.INCOTERMS
                 , IA.TRANSPORT_MODE
                 , IA.PLAN_DATE
--                 , IA.EXPECTED_SHIPPING_DATE     AS "Expected_Shipping_Date"    /* 화면 칸 설정 이름을 그대로 쓴다 */   --  2026.10.08 AJS
                 , IA.EXPECTED_SHIPPING_DATE     AS "EXPECTED_SHIPPING_DATE"    /* 화면 칸 설정 이름을 그대로 쓴다 */   --  2026.10.08 AJS
                 , IA.CONFIRM_FLAG
                 , IA.PLAN_QTY
                 , IA.CONFIRM_QTY
                 , IA.FCST_TYPE
                 , IA.CONFIRM_ID
                 , IA.ERP_SO_NO
                 , IA.LAST_UPDATED_BY
                 , IA.LAST_UPDATE_DATE
                 , IA.CHANGE_REQ_NO
                 , IA.D_PORT_NAME
                 , IA.D_COUNTRY
                 , IA.D_PORT_CODE
                 , IA.A_PORT_NAME
                 , IA.A_COUNTRY
                 , IA.A_PORT_CODE
                 , IA.DAYS_MON
                 , IA.DAYS_TUE
                 , IA.DAYS_WED
                 , IA.DAYS_THU
                 , IA.DAYS_FRI
                 , IA.DAYS_SAT
                 , IA.DAYS_SUN
                 , IA.LT_DEPARTURE_INLAND
                 , IA.LT_WAIT_SHIPPING
                 , IA.LT_VOYAGE
                 , IA.LT_LAY_OFF_CLEARANCE
                 , IA.LT_ARRIVAL_INLAND
                 , IA.LT_SUM
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.MTK_OWNER
                 , IA.LT_TYPE
                 , IA.BUILDING
                 , IA.CUST_REQUIREMENT
                 , IA.REMARKS
              FROM (SELECT A.DIVISION_ID
                         , A.PLAN_START_YYYYMMDD
                         , A.PLAN_TYPE
                         , MAX(A.SEQ)                                       AS SEQ
                         , A.ITEM_ID
                         , A.FROM_SITE
                         , MAX(NVL(B.SITE_DESCRIPTION, '/'))                AS FROM_SITE_DESCRIPTION
                         , MAX(NVL(C.SITE_DESCRIPTION, '/'))                AS TO_SITE_DESCRIPTION
                         , A.TO_SITE
                         , A.YYYYMMDD
                         , A.BOD_ID
                         , A.BIZ_TYPE
                         , (SELECT X.SEGMENT2
                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL X
                             WHERE X.VALID_YN    = 'Y'
                               AND X.LOOKUP_TYPE = 'BIZ_TYPE'
                               AND X.SEGMENT1    = A.BIZ_TYPE
                               AND ROWNUM        = 1)                       AS BIZ_TYPE_NAME
                         , A.PROJECT_CODE
                         , MAX(NVL(CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE
                                        ELSE D.PROJECT_NAME
                                   END, '-'))                               AS PROJECT_NAME
                         , (SELECT NVL(X.NICK_NAME, '-')
                              FROM SCM_MST_ITEM_SN X
                             WHERE X.ITEM_ID = A.ITEM_ID
                               AND ROWNUM    = 1)                           AS NICK_NAME
--                         , NVL(NULLIF(TRIM(FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION')), ''), '-') AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
                         , NVL(NULLIF(TRIM((SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') FROM DUAL)), ''), '-') AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
--                         , NVL(NULLIF(TRIM(FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION')), ''), '-') AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , NVL(NULLIF(TRIM((SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') FROM DUAL)), ''), '-') AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , E.LT_TOTAL                                       AS LT_DAY
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')                                     AS ETD
--                         , TO_CHAR(TO_DATE(FN_GET_SSP_ETA_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA    --  2026.10.06 AJS
                         , TO_CHAR(TO_DATE((SELECT FN_GET_SSP_ETA_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) FROM DUAL), 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA    --  2026.10.06 AJS
                         /* 20201223 incoterms 변경 작업 modify KIMYONGHO */
                         , E.SSP_INCOTERMS                                  AS INCOTERMS
                         , E.TRANSPORT_MODE
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')                                     AS PLAN_DATE
                         , CASE WHEN E.TRANSPORT_MODE = 'TRK' THEN '-'
--                                ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                                ELSE TO_CHAR(TO_DATE((SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) FROM DUAL), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                           END                                              AS EXPECTED_SHIPPING_DATE
                         , CASE WHEN A.CHANGE_TYPE = 'P' THEN 'N' ELSE 'Y' END                                        AS CONFIRM_FLAG
                         , SUM(A.PLANNED_QTY)                               AS PLAN_QTY
                         , SUM(A.QTY)                                       AS CONFIRM_QTY
                         , A.FCST_TYPE
                         , CASE WHEN SUBSTR(A.CONFIRM_ID, 1, 1) = 'P' THEN '/' ELSE A.CONFIRM_ID END                  AS CONFIRM_ID
                         , F.ERP_SO_NO
                         , CASE WHEN H.USER_NM IS NULL THEN A.LAST_UPDATED_BY
                                ELSE NVL2(G.LAST_UPDATED_BY
                                        , (CASE WHEN UPPER(P_LANGUAGE) = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END) || '(' || G.LAST_UPDATED_BY || ')'
                                        , NULL)
                           END                                              AS LAST_UPDATED_BY
                         , CASE WHEN G.LAST_UPDATE_DATE IS NULL THEN A.LAST_UPDATE_DATE
                                ELSE G.LAST_UPDATE_DATE
                           END                                              AS LAST_UPDATE_DATE
                         , G.CHANGE_REQ_NO
                         , IB.D_PORT_NAME
                         , E.D_COUNTRY
                         , E.D_PORT_CODE
                         , IB.A_PORT_NAME
                         , E.A_COUNTRY
                         , E.A_PORT_CODE
                         , E.DAYS_MON
                         , E.DAYS_TUE
                         , E.DAYS_WED
                         , E.DAYS_THU
                         , E.DAYS_FRI
                         , E.DAYS_SAT
                         , E.DAYS_SUN
                         , E.LT_DEPARTURE_INLAND
                         , E.LT_WAIT_SHIPPING
                         , E.LT_VOYAGE
                         , E.LT_LAY_OFF_CLEARANCE
                         , E.LT_ARRIVAL_INLAND
                         , NVL(E.LT_DEPARTURE_INLAND, 0) + NVL(E.LT_WAIT_SHIPPING, 0) + NVL(E.LT_VOYAGE, 0)
                             + NVL(E.LT_LAY_OFF_CLEARANCE, 0) + NVL(E.LT_ARRIVAL_INLAND, 0)                           AS LT_SUM
                         , A.ORIGIN_FROM_DIVISION_ID
--                         , FN_GET_SSP_MKT_OWNER_NAME(IC.OWNER, ',', UPPER(P_LANGUAGE))    /* 공용 함수는 언어를 대소문자로 가린다 */                                       AS MTK_OWNER    --  2026.10.06 AJS
                         , (SELECT FN_GET_SSP_MKT_OWNER_NAME(IC.OWNER, ',', UPPER(P_LANGUAGE)) FROM DUAL)    /* 공용 함수는 언어를 대소문자로 가린다 */                                       AS MTK_OWNER    --  2026.10.06 AJS
                         , E.LT_TYPE
                         , A.REMARKS2                                       AS BUILDING
                         , A.REMARKS3                                       AS CUST_REQUIREMENT
                         , A.REMARKS
                      FROM SSP_ANL_SHIP_CONFIRM         A
                         , SCM_MST_SITE                 B
                         , SCM_MST_SITE                 C
                         , SCM_MST_PROJECT              D
                         , SCP_MST_BOD_N_V              E
                         , SSP_ANL_SHIP_CONFIRM         F
                         -- 2026.10.06 AJS 확정번호별 마지막 이력을 이력 테이블 한 번 읽기로 계산 (START)
--                         , (SELECT X.CONFIRM_ID                    /* 확정번호별 마지막 이력 */
--                                 , X.LAST_UPDATED_BY
--                                 , X.LAST_UPDATE_DATE
--                                 , X.CHANGE_REQ_NO
--                              FROM SSP_ANL_SHIP_CONFIRM_H X
--                             WHERE X.HISTORY_SEQ = (SELECT MAX(Y.HISTORY_SEQ)
--                                                      FROM SSP_ANL_SHIP_CONFIRM_H Y
--                                                     WHERE Y.CONFIRM_ID = X.CONFIRM_ID))         G
                         , (SELECT X.CONFIRM_ID                    /* 확정번호별 마지막 이력 — HISTORY_SEQ 는 PK(중복 없음)라 확정번호마다 마지막 한 줄 */
                                 , MAX(X.LAST_UPDATED_BY)  KEEP (DENSE_RANK LAST ORDER BY X.HISTORY_SEQ)  AS LAST_UPDATED_BY
                                 , MAX(X.LAST_UPDATE_DATE) KEEP (DENSE_RANK LAST ORDER BY X.HISTORY_SEQ)  AS LAST_UPDATE_DATE
                                 , MAX(X.CHANGE_REQ_NO)    KEEP (DENSE_RANK LAST ORDER BY X.HISTORY_SEQ)  AS CHANGE_REQ_NO
                              FROM SSP_ANL_SHIP_CONFIRM_H X
                             WHERE X.CONFIRM_ID IN (SELECT SA.CONFIRM_ID      /* 이 조회 기간의 확정번호만 — G 는 A 와 확정번호로만 이어진다 */
                                                      FROM SSP_ANL_SHIP_CONFIRM SA
                                                     WHERE SA.YYYYMMDD >= P_FROM_YYYYMMDD
                                                       AND SA.YYYYMMDD <= P_TO_YYYYMMDD
                                                       AND SA.QTY       > 0)
                             GROUP BY X.CONFIRM_ID)                                                   G
                         -- 2026.10.06 AJS 확정번호별 마지막 이력을 이력 테이블 한 번 읽기로 계산 (END)
                         , SCM_ADM_USER_M               H
                         , SCP_MST_DISTRIBUTION_ROUTE   IB
                         , SCM_MST_SITE_ITEM            IC
                     WHERE B.SCM_SITE_ID          = A.FROM_SITE
                       /* 20220420 SMS 가상디비젼관련 추가 — 81, 81_UC 에 같은 SCM_SITE_ID 가 있어 사업부도 견준다 */
                       AND B.DIVISION_ID          = A.DIVISION_ID
                       AND C.SCM_SITE_ID          = A.TO_SITE
                       AND C.DIVISION_ID          = A.DIVISION_ID
                       AND D.PROJECT_CODE(+)      = A.PROJECT_CODE
                       AND D.DIVISION_ID(+)       = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND E.DIVISION_ID          = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND E.BOD_ID               = A.BOD_ID
                       AND F.CONFIRM_ID(+)        = A.CONFIRM_ID
                       AND F.ERP_STATUS(+)       <> 'B'
                       AND G.CONFIRM_ID(+)        = A.CONFIRM_ID
                       AND H.USER_ID(+)           = G.LAST_UPDATED_BY
                       AND H.USE_YN(+)            = 'Y'
                       AND IB.ROUTE_ID            = E.ROUTE_ID
                       AND IC.DIVISION_ID(+)      = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND IC.SCM_SITE_ID(+)      = A.TO_SITE
                       AND IC.ITEM_ID(+)          = A.ITEM_ID
                       AND IC.PROJECT_CODE(+)     = A.PROJECT_CODE
                       AND A.YYYYMMDD            >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD            <= P_TO_YYYYMMDD
                       AND A.QTY                  > 0                       /* OR A.PLANNED_QTY > 0 */
                       AND (TRIM(V_DIVISION_ID) IS NULL
                        OR  UPPER(V_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                        OR  UPPER(A.DIVISION_ID) IN (SELECT UPPER(COLUMN_VALUE)
                                                       FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
                       AND (TRIM(V_FROM_SITE) IS NULL
                        OR  UPPER(V_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                        OR  UPPER(A.FROM_SITE) IN (SELECT UPPER(COLUMN_VALUE)
                                                     FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
                       AND (TRIM(V_ITEM_ID) IS NULL
                        OR  UPPER(V_ITEM_ID) = 'ALL'  /* 조회조건 ALL 은 조건 없음 */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR  UPPER(A.ITEM_ID) IN (SELECT UPPER(COLUMN_VALUE)
--                                                 FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
                        OR  EXISTS (SELECT 1
                                      FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SB
                                     WHERE SB.COLUMN_VALUE IS NOT NULL
                                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(SB.COLUMN_VALUE) || '%'
                                            OR EXISTS (SELECT 1
                                                         FROM SCM_MST_ITEM_SN XG
                                                        WHERE XG.ITEM_ID = A.ITEM_ID
                                                          AND UPPER(XG.NICK_NAME) LIKE '%' || UPPER(SB.COLUMN_VALUE) || '%'))))
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                     GROUP BY A.DIVISION_ID
                            , A.PLAN_START_YYYYMMDD
                            , A.PLAN_TYPE
                            , A.ITEM_ID
                            , A.FROM_SITE
                            , A.TO_SITE
                            , A.YYYYMMDD
                            , A.BOD_ID
                            , A.PROJECT_CODE
                            , A.BIZ_TYPE
                            , E.LT_TOTAL
                            , E.SSP_INCOTERMS
                            , E.TRANSPORT_MODE
                            , E.LT_DEPARTURE_INLAND
                            , E.LT_WAIT_SHIPPING
                            , A.FCST_TYPE
                            , CASE WHEN SUBSTR(A.CONFIRM_ID, 1, 1) = 'P' THEN '/' ELSE A.CONFIRM_ID END
                            , F.ERP_SO_NO
                            , H.USER_NM
                            , H.USER_ENG_NM
                            , A.LAST_UPDATED_BY
                            , G.LAST_UPDATED_BY
                            , A.LAST_UPDATE_DATE
                            , G.LAST_UPDATE_DATE
                            , CASE WHEN A.CHANGE_TYPE = 'P' THEN 'N' ELSE 'Y' END
                            , G.CHANGE_REQ_NO
                            , IB.D_PORT_NAME
                            , E.D_COUNTRY
                            , E.D_PORT_CODE
                            , IB.A_PORT_NAME
                            , E.A_COUNTRY
                            , E.A_PORT_CODE
                            , E.DAYS_MON
                            , E.DAYS_TUE
                            , E.DAYS_WED
                            , E.DAYS_THU
                            , E.DAYS_FRI
                            , E.DAYS_SAT
                            , E.DAYS_SUN
                            , E.LT_VOYAGE
                            , E.LT_LAY_OFF_CLEARANCE
                            , E.LT_ARRIVAL_INLAND
                            , A.ORIGIN_FROM_DIVISION_ID
                            , A.ORIGIN_TO_DIVISION_ID
                            , IC.OWNER
                            , E.LT_TYPE
                            , A.REMARKS2
                            , A.REMARKS3
                            , A.REMARKS
                            , A.CONFIRM_ID) IA
             WHERE (TRIM(P_SOLD_TO_PARTY) IS NULL
                OR  UPPER(IA.SOLDTO_DESCRIPTION) LIKE '%' || UPPER(TRIM(P_SOLD_TO_PARTY)) || '%')
               AND (TRIM(P_SHIP_TO_PARTY) IS NULL
                OR  UPPER(IA.SHIPTO_DESCRIPTION) LIKE '%' || UPPER(TRIM(P_SHIP_TO_PARTY)) || '%')
             ORDER BY IA.DIVISION_ID
                    , IA.FROM_SITE
                    , IA.ITEM_ID
                    , IA.TO_SITE
                    , IA.YYYYMMDD
                    /* AS-IS 는 정렬 값이 같으면 앞 단계에서 줄을 세운 순서를 따른다 */
                    , IA.PROJECT_CODE
                    , IA.BOD_ID
                    , IA.CONFIRM_ID;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0012_GET_SHIPMENT_PLAN_CONFIRM_DETAIL;

END PKG_SSP0012;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0012
-- ##### END PACKAGE BODY PKG_SSP0012

-- ##### START PACKAGE BODY PKG_SSP0015
CREATE OR REPLACE PACKAGE BODY PKG_SSP0015
IS

    /* ============================================================
       P_SSP0015_GET_ERP_SO_NO_CNT
       AS-IS SSP0015_GET_ERP_SO_NO_CNT
       ============================================================ */
    PROCEDURE P_SSP0015_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_ERP_SO_NO             IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_ERP_SO_NO_CNT
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT COUNT(*) AS CNT
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE DIVISION_ID = P_DIVISION_ID
           AND ERP_SO_NO   = P_ERP_SO_NO
           AND QTY        <> 0;

    END P_SSP0015_GET_ERP_SO_NO_CNT;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_STATUS
       AS-IS SSP0015_GET_SHIPMENT_STATUS - 결과셋 3벌
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_CONFIRM_ID            IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR,
        O_RC3                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_STATUS
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2020/07/15   khj79          ERP_STATUS 가 'C' 인 경우 수정 못하도록 추가
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (String_Split -> FN_STRING_SPLIT)
         * 2026.10.06   AJS            조회 속도 개선 : 확정 ID 목록으로 기본키 조회(분리 함수 건수 추정으로 확정 원장 전체 읽기 3회 반복 제거)
         *
         ex) EXEC PKG_SSP0015.P_SSP0015_GET_SHIPMENT_STATUS('40^40', 'C20181001068349^C20181005074232', ...)
         */
    BEGIN

        OPEN O_RC1 FOR
--      SELECT CONFIRM_ID   --  2026.10.06 AJS
        SELECT /*+ INDEX(SSP_ANL_SHIP_CONFIRM PK_SSP_ANL_SHIP_CONFIRM) */ CONFIRM_ID   /* 확정 ID 기본키 조회 */   --  2026.10.06 AJS
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND SHIPMENT_STATUS != 'C';

        OPEN O_RC2 FOR
--      SELECT CONFIRM_ID   --  2026.10.06 AJS
        SELECT /*+ INDEX(SSP_ANL_SHIP_CONFIRM PK_SSP_ANL_SHIP_CONFIRM) */ CONFIRM_ID   /* 확정 ID 기본키 조회 */   --  2026.10.06 AJS
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND QTY = 0;

        OPEN O_RC3 FOR
--      SELECT CONFIRM_ID   --  2026.10.06 AJS
        SELECT /*+ INDEX(SSP_ANL_SHIP_CONFIRM PK_SSP_ANL_SHIP_CONFIRM) */ CONFIRM_ID   /* 확정 ID 기본키 조회 */   --  2026.10.06 AJS
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND ERP_STATUS = 'C';

    END P_SSP0015_GET_SHIPMENT_STATUS;


    /* ============================================================
       P_SSP0015_GET_SCS_STOCK
       AS-IS SSP0015_GET_SCS_STOCK
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SCS_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   @ PKG_SSP0015.P_SSP0015_GET_SCS_STOCK
         * Description  @ MES Stock
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021-10-20   KIMYONGHO		신규추가
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         * 2026.10.07   AJS             조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_CUTOFF_DATE   VARCHAR2(8 CHAR);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* AS-IS : CONVERT(CHAR(8), DATEADD(DD, -2, ...), 112) - 계획기준일 -2일 */
        V_CUTOFF_DATE := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');

        OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.CUTOFF_DATE
             , A.SCM_SITE_ID                        AS PLANT_ID
             , B.SITE_DESCRIPTION                   AS PLANT_NAME
             , A.ITEM_ID                            AS MODEL_ID
             , TO_CHAR(TO_DATE(A.STOCK_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS PROD_DATE
             , '-'                                  AS HOLD_YN
             , A.STOCK_QTY                          AS QTY
             , A.LAST_UPDATE_DATE
          FROM SCM_DNM_SCS_STOCK A
             , SCM_MST_SITE B
             , SSP_MST_MODEL_USER M
         WHERE A.DIVISION_ID   = B.DIVISION_ID
           AND A.SCM_SITE_ID   = B.SCM_SITE_ID
           AND M.DIVISION_ID(+) = A.DIVISION_ID
           AND M.FROM_SITE(+)   = A.SCM_SITE_ID
           AND M.ITEM_ID(+)     = A.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           AND A.DIVISION_ID   = '40'
           AND A.CUTOFF_DATE   = V_CUTOFF_DATE
           AND A.CELL_PACK     = 'P'
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         ORDER BY A.SCM_SITE_ID
             , A.ITEM_ID;

    END P_SSP0015_GET_SCS_STOCK;


    /* ============================================================
       P_SSP0015_GET_BLOCK_STOCK
       AS-IS SSP0015_GET_BLOCK_STOCK - 결과셋 2벌(본문 · 상세)
       ※ AS-IS 는 두 결과셋의 SELECT 문이 완전히 같다. 조회조건만 P_SEARCH_YN 으로 갈린다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_BLOCK_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_SEARCH_YN             IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2 DEFAULT 'N',
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_BLOCK_STOCK
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/03/05   AYJ 			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/06/17	AYJ				조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			    조회 조건 추가(p_delegateeChk)
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         * 2026.10.07   AJS             조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_BASE_YYYYMMDD VARCHAR2(8 CHAR);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* AS-IS : convert(varchar(8), convert(datetime, @p_plan_start_yyyymmdd) +1, 112) */
        V_BASE_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD');

        IF P_SEARCH_YN != 'Y' THEN

            /* 1. 셀 더블클릭 */
            OPEN O_RC1 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                   /* MSSQL 은 UserName 이 NULL 이면 결합 결과도 NULL 이다 - 판정을 유지한다 */
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                 , TB_FX_USER U
--             WHERE A.LAST_UPDATED_BY = U.USERID(+)
--               AND U.USEYN(+)        = 'Y'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 , SCM_ADM_USER_M U
                 , SSP_MST_MODEL_USER M
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)       = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.FROM_SITE           = P_FROM_SITE
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               AND A.ITEM_ID             = P_ITEM_ID
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

            /* Block Stock Detail - AS-IS 는 위와 같은 문장이다 */
            OPEN O_RC2 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                 , TB_FX_USER U
--             WHERE A.LAST_UPDATED_BY = U.USERID(+)
--               AND U.USEYN(+)        = 'Y'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 , SCM_ADM_USER_M U
                 , SSP_MST_MODEL_USER M
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)       = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.FROM_SITE           = P_FROM_SITE
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               AND A.ITEM_ID             = P_ITEM_ID
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

        ELSE

            /* 2. btnSearch */
            OPEN O_RC1 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                 , TB_FX_USER U
--             WHERE A.LAST_UPDATED_BY = U.USERID(+)
--               AND U.USEYN(+)        = 'Y'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 , SCM_ADM_USER_M U
                 , SSP_MST_MODEL_USER M
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)       = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                     OR  UPPER(P_FROM_SITE) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                     OR  UPPER(P_ITEM_ID) = 'ALL'     /* 조회조건 ALL 은 조건 없음 */
--                   OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
               /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

            OPEN O_RC2 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                 , TB_FX_USER U
--             WHERE A.LAST_UPDATED_BY = U.USERID(+)
--               AND U.USEYN(+)        = 'Y'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 , SCM_ADM_USER_M U
                 , SSP_MST_MODEL_USER M
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)       = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                     OR  UPPER(P_FROM_SITE) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                     OR  UPPER(P_ITEM_ID) = 'ALL'     /* 조회조건 ALL 은 조건 없음 */
--                   OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
--                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

        END IF;

    END P_SSP0015_GET_BLOCK_STOCK;


    /* ============================================================
       P_SSP0015_GET_WH_STOCK
       AS-IS SSP0015_GET_WH_STOCK - 결과셋 2벌(본문 · 상세)
       ============================================================ */
    PROCEDURE P_SSP0015_GET_WH_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_PLAN_SEQ              IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_SEARCH_YN             IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_WH_STOCK
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/03/05   AYJ			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/06/17	AYJ			조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			조회 조건 추가(p_delegateeChk)
         * 2026.09.16   AJS         MSSQL -> Oracle 전환
         * 2026.10.07   AJS         조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        IF P_SEARCH_YN != 'Y' THEN

            /* 1. 셀 더블클릭 - W/H Stock */
            OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE          AS CAPA_GRADE
                 , A.SOC
                 , SUM(A.STOCK_QTY)          AS STOCK_QTY
                 , SUM(A.AVAILABLE_QTY)      AS AVAILABLE_QTY
                 , SUM(A.NON_QC_QTY)         AS UNDECIDED_QTY
                 , SUM(A.ALLOCATION_QTY)     AS ALLOCATION_QTY
                 , SUM(A.BLOCK_QTY)          AS HOLD_QTY
                 , SUM(A.PACKING_QTY)        AS PACKING_QTY
                 , SUM(A.MOVING_QTY)         AS MOVING_QTY
                 , SUM(A.RCVLOC_QTY)         AS RECEIVING_QTY
                 , SUM(A.EXPIRATION_QTY)     AS EXPIRATION_QTY
                 , SUM(A.LONG_QTY)           AS LONG_TERM_QTY
              FROM SSP_ANL_OWMS_STOCK_C A
                 , SCM_MST_SLOC B
                 , SSP_MST_MODEL_USER M
             WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
               AND B.STORAGE_ID(+)  = A.STORAGE_ID
               AND B.PLANT_ID(+)    = A.PLANT_ID
               AND M.DIVISION_ID(+) = A.DIVISION_ID
               AND M.FROM_SITE(+)   = A.FROM_SITE
               AND M.ITEM_ID(+)     = A.ITEM_ID
               AND M.VALID_YN(+)    = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_PLAN_SEQ
               AND A.FROM_SITE           = P_FROM_SITE
               AND A.ITEM_ID             = P_ITEM_ID
             GROUP BY A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC
                 , A.PLANT_ID
                 , A.DIVISION_ID
                 , A.STORAGE_ID
                 , B.STORAGE_DESCRIPTION
             ORDER BY A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC;

            /* 1. 셀 더블클릭 - W/H Stock Detail */
            OPEN O_RC2 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , A.GRADE
                         , A.CAPACITY_GRADE     AS CAPA_GRADE
                         , A.SOC
                         , A.LOT_ID
                         , A.PALLET_ID
                         , A.STOCK_QTY
                         , A.AVAILABLE_QTY
                         , A.NON_QC_QTY         AS UNDECIDED_QTY
                         , A.ALLOCATION_QTY
                         , A.BLOCK_QTY          AS HOLD_QTY
                         , A.PACKING_QTY
                         , A.MOVING_QTY
                         , A.RCVLOC_QTY         AS RECEIVING_QTY
                         , A.EXPIRATION_QTY
                         , A.LONG_QTY           AS LONG_TERM_QTY
                         , A.PLANT_ID
                         , A.PACKING_STATUS
                         , A.STOCK_STATUS
                         , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                         , A.CUSTOMER_CODE
                         , A.CUSTOMER_NAME
                         , CASE WHEN REGEXP_LIKE(A.LOT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.LOT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                           END AS LOT_ISSUE_DATE
                      FROM SSP_ANL_OWMS_STOCK_C A
                         , SCM_MST_SLOC B
                         , SSP_MST_MODEL_USER M
                     WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND B.STORAGE_ID(+)  = A.STORAGE_ID
                       AND B.PLANT_ID(+)    = A.PLANT_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.FROM_SITE
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID         = P_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = P_PLAN_TYPE
                       AND A.SEQ                 = P_PLAN_SEQ
                       AND A.FROM_SITE           = P_FROM_SITE
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                   ) IA
             ORDER BY IA.DIVISION_ID
                 , IA.PLANT_ID
                 , IA.STORAGE_ID
                 , IA.ITEM_ID
                 , IA.GRADE
                 , IA.CAPA_GRADE
                 , IA.SOC
                 , IA.LOT_ID
                 , IA.PALLET_ID;

        ELSE

            /* 2. btnSearch - W/H Stock */
            OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE          AS CAPA_GRADE
                 , A.SOC
                 , SUM(A.STOCK_QTY)          AS STOCK_QTY
                 , SUM(A.AVAILABLE_QTY)      AS AVAILABLE_QTY
                 , SUM(A.NON_QC_QTY)         AS UNDECIDED_QTY
                 , SUM(A.ALLOCATION_QTY)     AS ALLOCATION_QTY
                 , SUM(A.BLOCK_QTY)          AS HOLD_QTY
                 , SUM(A.PACKING_QTY)        AS PACKING_QTY
                 , SUM(A.MOVING_QTY)         AS MOVING_QTY
                 , SUM(A.RCVLOC_QTY)         AS RECEIVING_QTY
                 , SUM(A.EXPIRATION_QTY)     AS EXPIRATION_QTY
                 , SUM(A.LONG_QTY)           AS LONG_TERM_QTY
              FROM SSP_ANL_OWMS_STOCK_C A
                 , SCM_MST_SLOC B
                 , SSP_MST_MODEL_USER M
             WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
               AND B.STORAGE_ID(+)  = A.STORAGE_ID
               AND B.PLANT_ID(+)    = A.PLANT_ID
               AND M.DIVISION_ID(+) = A.DIVISION_ID
               AND M.FROM_SITE(+)   = A.FROM_SITE
               AND M.ITEM_ID(+)     = A.ITEM_ID
               AND M.VALID_YN(+)    = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_PLAN_SEQ
               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                     OR  UPPER(P_FROM_SITE) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                     OR  UPPER(P_ITEM_ID) = 'ALL'     /* 조회조건 ALL 은 조건 없음 */
--                   OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                     OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
               /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             GROUP BY A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC
                 , A.PLANT_ID
                 , A.DIVISION_ID
                 , A.STORAGE_ID
                 , B.STORAGE_DESCRIPTION
             ORDER BY A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC;

            /* 2. btnSearch - W/H Stock Detail */
            OPEN O_RC2 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , A.GRADE
                         , A.CAPACITY_GRADE     AS CAPA_GRADE
                         , A.SOC
                         , A.LOT_ID
                         , A.PALLET_ID
                         , A.STOCK_QTY
                         , A.AVAILABLE_QTY
                         , A.NON_QC_QTY         AS UNDECIDED_QTY
                         , A.ALLOCATION_QTY
                         , A.BLOCK_QTY          AS HOLD_QTY
                         , A.PACKING_QTY
                         , A.MOVING_QTY
                         , A.RCVLOC_QTY         AS RECEIVING_QTY
                         , A.EXPIRATION_QTY
                         , A.LONG_QTY           AS LONG_TERM_QTY
                         , A.PLANT_ID
                         , A.PACKING_STATUS
                         , A.STOCK_STATUS
                         , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                         , A.CUSTOMER_CODE
                         , A.CUSTOMER_NAME
                         , CASE WHEN REGEXP_LIKE(A.LOT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.LOT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                           END AS LOT_ISSUE_DATE
                      FROM SSP_ANL_OWMS_STOCK_C A
                         , SCM_MST_SLOC B
                         , SSP_MST_MODEL_USER M
                     WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND B.STORAGE_ID(+)  = A.STORAGE_ID
                       AND B.PLANT_ID(+)    = A.PLANT_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.FROM_SITE
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID         = P_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = P_PLAN_TYPE
                       AND A.SEQ                 = P_PLAN_SEQ
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                       /* 체크박스 체크 여부 조회 끝 */
                   ) IA
             ORDER BY IA.DIVISION_ID
                 , IA.PLANT_ID
                 , IA.STORAGE_ID
                 , IA.ITEM_ID
                 , IA.GRADE
                 , IA.CAPA_GRADE
                 , IA.SOC
                 , IA.LOT_ID
                 , IA.PALLET_ID;

        END IF;

    END P_SSP0015_GET_WH_STOCK;


    /* ============================================================
       P_SSP0015_GET_MES_STOCK
       AS-IS SSP0015_GET_MES_STOCK
       ※ AS-IS SUBSTRING(LOT_ID, 0, 9) 는 8자다. Oracle SUBSTR(x,0,9) 는 9자라
          SUBSTR(LOT_ID, 1, 8) 로 옮긴다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_MES_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_LOT_ID                IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   @ PKG_SSP0015.P_SSP0015_GET_MES_STOCK
         * Description  @ MES Stock
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/10/24   AYJ				MES Stock 시트 조회
         * 2019/01/06   KIMYHONGHO		[]MES Sotck 시트 운영 신규 적용
         * 2020/01/20   KIMYHONGHO		[C20200115-000414] MES Stock Detail 화면 개선 요청건
         * 2020/03/18   KIMYONGHO		[C20200303-000163] LONGTERM_HOLD_YN 컬럼 추가
         * 2021/07/26	KIMYONGHO       C20210708-000537 : [SCM PI팀] 재고 정합성 관련 GMES 불량 수량 GSCM 전송 요청
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         * 2026.10.07   AJS             조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        OPEN O_RC1 FOR
        SELECT XA.ROW_NO AS "ROWNUM"   /* AS-IS 칸 이름이 ROWNUM 이라 그대로 내보낸다(Oracle 예약어라 인용부호) */
             , XA.DIVISION_ID
             , XA.FROM_SITE
             , XA.ITEM_ID
             , XA.NICK_NAME
             , XA.LOT_ID
             , XA.YYYYMMDD_LOT_ID_APPLIED_LT
             , XA.MES_CHANGE_STATUS
             , XA.LOT_TYPE
             , XA.LOT_QTY_MES
             , XA.LOT_QTY_MES_NG
             , XA.LOT_QTY_FCS
             , XA.FCS_SPECIAL_QTY
             , XA.OWMS_STOCK_QTY
             , XA.LOT_QTY_TOT
             , XA.AVAILABLE_YN
             , XA.MES_HOLD_YN
             , XA.QMS_HOLD_YN
             , XA.FCS_HOLD_YN
             , XA.LONGTERM_HOLD_YN
             , XA.JUDG_VLD_DATE
             , XA.MES_HOLD_RELEASE
             , XA.QMS_HOLD_RELEASE
             , XA.USER_MOD_RELEASE_DATE
             , XA.REMARKS
             , XA.LAST_UPDATED_BY
             , XA.LAST_UPDATE_DATE
          FROM (
                SELECT ROW_NUMBER() OVER (PARTITION BY IA.DIVISION_ID, IA.FROM_SITE, IA.ITEM_ID, IA.LOT_ID
                                              /* AS-IS MSSQL 은 내림차순에서 값 없음을 뒤에 둔다 — 대표 행 선택이 뒤집히지 않게 NULLS LAST */
                                              ORDER BY IA.LOT_TYPE DESC NULLS LAST, IA.MES_CHANGE_STATUS DESC NULLS LAST) AS ROW_NO
                     , IA.DIVISION_ID
                     , IA.FROM_SITE
                     , IA.ITEM_ID
                     , IA.NICK_NAME
                     , IA.LOT_ID
                     , IA.YYYYMMDD_LOT_ID_APPLIED_LT
                     , IA.MES_CHANGE_STATUS
                     , IA.LOT_TYPE
                     , IA.LOT_QTY_MES
                       /* C20210708-000537 */
                     , IA.LOT_QTY_MES_NG
                     , IA.LOT_QTY_FCS
                     , IA.FCS_SPECIAL_QTY
                     , IA.OWMS_STOCK_QTY
                     , IA.LOT_QTY_TOT
                     , IA.AVAILABLE_YN
                     , IA.MES_HOLD_YN
                     , IA.QMS_HOLD_YN
                     , IA.FCS_HOLD_YN
                     , IA.LONGTERM_HOLD_YN
                     , IA.JUDG_VLD_DATE
                     , IA.MES_HOLD_RELEASE
                     , IA.QMS_HOLD_RELEASE
                     , IA.USER_MOD_RELEASE_DATE
                     , IA.REMARKS
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                  FROM (
                        SELECT X.DIVISION_ID
                             , X.FROM_SITE
                             , X.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
                             , X.LOT_ID                             AS LOT_ID
                             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD_LOT_ID_APPLIED_LT, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD_LOT_ID_APPLIED_LT, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS YYYYMMDD_LOT_ID_APPLIED_LT
                             , X.CHANGE_STATUS                      AS MES_CHANGE_STATUS
                             , X.LOT_TYPE
                             , X.LOT_QTY_MES
                               /* C20210708-000537 */
                               /* ATTRIBUTE4 는 VARCHAR2 다. AS-IS 는 UNION 타입 우선순위로 정수가 되므로 숫자로 맞춘다.
                                  원장 칸이라 이관 채움값이 섞여도 조회가 끊기지 않게 방어 변환을 둔다. */
                             , NVL(TO_NUMBER(X.ATTRIBUTE4 DEFAULT NULL ON CONVERSION ERROR), 0) AS LOT_QTY_MES_NG   /* 불량수량 */
                             , X.LOT_QTY_FCS
                             , X.FCS_SPECIAL_QTY
                             , X.OWMS_STOCK_QTY
                             , X.LOT_QTY_TOT                        AS LOT_QTY_TOT
                             , X.AVAILABLE_YN
                             , X.MES_HOLD_YN
                             , X.QMS_HOLD_YN
                             , X.FCS_HOLD_YN
                             , X.LONGTERM_HOLD_YN
                             , CASE WHEN REGEXP_LIKE(X.JUDG_VLD_DATE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.JUDG_VLD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS JUDG_VLD_DATE
                             , CASE WHEN REGEXP_LIKE(X.MES_HOLD_RELEASE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.MES_HOLD_RELEASE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS MES_HOLD_RELEASE
                             , CASE WHEN REGEXP_LIKE(X.QMS_HOLD_RELEASE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.QMS_HOLD_RELEASE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS QMS_HOLD_RELEASE
                             , CASE WHEN REGEXP_LIKE(X.USER_MOD_RELEASE_DATE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.USER_MOD_RELEASE_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS USER_MOD_RELEASE_DATE
                             , X.REMARKS
                             /* 2026.09.30 AJS 수정 (START) */
--                             , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                                    ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || X.LAST_UPDATED_BY || ')'
--                             , TB_FX_USER U
--                         WHERE X.LAST_UPDATED_BY = U.USERID(+)
--                           AND U.USEYN(+)        = 'Y'
                             , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                                    ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || X.LAST_UPDATED_BY || ')'
                               END                                  AS LAST_UPDATED_BY
                             , X.LAST_UPDATE_DATE
                          FROM SSP_ANL_MES_FCS_STOCK_40_C X
                             , SCM_ADM_USER_M U
                             , SSP_MST_MODEL_USER M
                         WHERE X.LAST_UPDATED_BY = U.USER_ID(+)
                           AND U.USE_YN(+)       = 'Y'
                             /* 2026.09.30 AJS 수정 (END) */
                           AND M.DIVISION_ID(+)  = X.DIVISION_ID
                           AND M.FROM_SITE(+)    = X.FROM_SITE
                           AND M.ITEM_ID(+)      = X.ITEM_ID
                           AND M.VALID_YN(+)     = 'Y'
                           AND X.DIVISION_ID         = P_DIVISION_ID
                           AND X.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND X.PLAN_TYPE           = 'SP'
                           AND X.SEQ                 = 1
                           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                 OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                 OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                               OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                 OR X.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                           AND ((P_LOT_ID IS NULL OR P_LOT_ID = '')
                                 OR X.LOT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))
                           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' @ 체크박스 선택 안한 상태) */
                           AND ((P_NONCHK = 'Y' AND 1 = 1)
                                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                   UNION
                                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                    FROM SSP_MST_DELEGATE
                                                   WHERE VALID_YN = 'Y'
                                                     AND DELEGATEE_ID = P_USER_ID
                                                   GROUP BY USER_ID)
                                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                        /* [C20200115-000414] OWMS 조회 부분 추가 */
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.FROM_SITE
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                             , SUBSTR(A.LOT_ID, 1, 8)   AS LOT_ID
                             , NULL                     AS YYYYMMDD_LOT_ID_APPLIED_LT
                             , NULL                     AS MES_CHANGE_STATUS
                             , NULL                     AS LOT_TYPE
                             , 0                        AS LOT_QTY_MES
                               /* C20210708-000537 */
                             , 0                        AS LOT_QTY_MES_NG
                             , 0                        AS LOT_QTY_FCS
                             , 0                        AS FCS_SPECIAL_QTY
                             , SUM(A.STOCK_QTY)         AS OWMS_STOCK_QTY
                             , 0                        AS LOT_QTY_TOT
                             , '-'                      AS AVAILABLE_YN
                             , '-'                      AS MES_HOLD_YN
                             , '-'                      AS QMS_HOLD_YN
                             , '-'                      AS FCS_HOLD_YN
                             , '-'                      AS LONGTERM_HOLD_YN
                             , NULL                     AS JUDG_VLD_DATE
                             , NULL                     AS MES_HOLD_RELEASE
                             , NULL                     AS QMS_HOLD_RELEASE
                             , NULL                     AS USER_MOD_RELEASE_DATE
                             , NULL                     AS REMARKS
                             , NULL                     AS LAST_UPDATED_BY
                             , NULL                     AS LAST_UPDATE_DATE
                          FROM SSP_ANL_OWMS_STOCK_C A
                             , SCM_MST_SLOC B
                             , SSP_MST_MODEL_USER M
                         WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                           AND B.STORAGE_ID(+)  = A.STORAGE_ID
                           AND B.PLANT_ID(+)    = A.PLANT_ID
                           AND M.DIVISION_ID(+) = A.DIVISION_ID
                           AND M.FROM_SITE(+)   = A.FROM_SITE
                           AND M.ITEM_ID(+)     = A.ITEM_ID
                           AND M.VALID_YN(+)    = 'Y'
                           AND A.DIVISION_ID         = P_DIVISION_ID
                           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                 OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                 OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                           AND ((P_LOT_ID IS NULL OR P_LOT_ID = '')
                                 OR A.LOT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))
                           AND ((P_NONCHK = 'Y' AND 1 = 1)
                                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                   UNION
                                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                    FROM SSP_MST_DELEGATE
                                                   WHERE VALID_YN = 'Y'
                                                     AND DELEGATEE_ID = P_USER_ID
                                                   GROUP BY USER_ID)
                                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                         GROUP BY A.DIVISION_ID
                             , A.ORIGIN_FROM_DIVISION_ID
                             , A.FROM_SITE
                             , A.ITEM_ID
                             , SUBSTR(A.LOT_ID, 1, 8)
                       ) IA
               ) XA
         WHERE XA.ROW_NO = 1
         ORDER BY XA.DIVISION_ID
             , XA.ITEM_ID
             , XA.LOT_ID
             , XA.MES_CHANGE_STATUS DESC;

    END P_SSP0015_GET_MES_STOCK;


    /* ============================================================
       P_SSP0015_GET_STOCK_LOCATION_DETAIL
       AS-IS SSP0015_GET_STOCK_LOCATION_DETAIL
       ※ AS-IS 의 @MST_LOCATION 테이블변수는 채우기만 하고 조인이 전부 주석 처리돼 있어
          결과에 영향을 주지 않는다. 옮기지 않는다.
       ※ SCM_DNM_STOCK_V.CUTOFF_DATE 는 Oracle 에서 DATE 다. 암시적 형변환을 막기 위해
          비교값을 TO_DATE 로 맞추고, 결과 칸은 AS-IS 표기(YYYYMMDD)로 돌려준다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_STOCK_LOCATION_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_DBL_FLAG              IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_PROGRAM_ID            IN  VARCHAR2 DEFAULT 'SSP0015',
        P_SHEET_NAME            IN  VARCHAR2 DEFAULT 'Stock Location Detail',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'T',
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_STOCK_LOCATION_DETAIL
         * Description  : 소형 외주 Packer
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021-09-28   KIMYONGHO	    최초작성
         * 2024-10-01   KHJ             NERP_SSP
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         * 2026.10.07   AJS             조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_A010              VARCHAR2(10 CHAR);   /* NERP 매핑코드 */
        V_BOH_YYYYMMDD      VARCHAR2(8 CHAR);
        V_STOCK_YYYYMMDD    VARCHAR2(8 CHAR);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_A010 := FN_GET_LOOKUP_VALUE('SSP0015_GET_STOCK_LOCATION_DETAIL', 'A010');   /* A010 */

        V_BOH_YYYYMMDD   := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 3, 'YYYYMMDD');   /* FROM -3일 */

        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.COMPANY_ID
                         , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD')   AS CUTOFF_DATE
                         , A.SCM_SITE_ID                        AS FROM_SITE
                         , A.PLANT_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                         , A.STOCK_TYPE
                         , A.STORAGE_ID
                         , NVL(B.STORAGE_DESCRIPTION,
                               (SELECT MIN(SA.STORAGE_DESCRIPTION)
                                  FROM SCM_MST_SLOC SA
                                 WHERE SA.PLANT_ID   = A.PLANT_ID
                                   AND SA.STORAGE_ID = A.STORAGE_ID
                                   AND SA.VALID_YN   = 'Y')) AS STORAGE_DESCRIPTION
                         , NVL(A.SCM_QTY, 0)                    AS TOTAL_QTY
                         , NVL(A.SSP_QTY, 0)                    AS AVAILABLE_QTY
                         , A.DEFECT_QTY
                         , A.MOVING_QTY
                         , A.QTY_UOM
                         , NVL(A.WIPHOLD_YN, 'N')               AS WIPHOLD_YN
                         , A.HOLDING_DATE
                         , A.AVAILABLE_DATE
                         , A.OUTSOURCING_FLAG
                         , A.OUTSOURCING_FACTORY
                      FROM SCM_DNM_STOCK_V A
                         , SCM_MST_SLOC B
                         , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME
                              FROM SCM_MST_ITEM_SN
                             WHERE DIVISION_ID = P_DIVISION_ID
                               AND ACTIVE_FLAG = 'Y'
                               AND SCP_OPERATION_GROUP = 'P'   /* CELL/PACK 구분 */
                           ) C
                         , SSP_MST_MODEL_USER M
                     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
                       AND A.PLANT_ID      = B.PLANT_ID(+)
                       AND A.STORAGE_ID    = B.STORAGE_ID(+)
                       AND A.DIVISION_ID   = C.DIVISION_ID
                       AND A.ITEM_ID       = C.ITEM_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.SCM_SITE_ID
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND A.COMPANY_ID  = P_COMPANY_ID
                       AND A.SCM_SITE_ID = P_FROM_SITE
                       AND A.ITEM_ID     = P_ITEM_ID
                       AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                       AND A.ORG_CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD') + 1 /* AJS 20261007 속도 : 원장 마감일 조건(뷰 마감일 + 1 과 같은 값) */
                       AND A.CUTOFF_DATE > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')   /* 현재일 - 3 */
                       AND A.STOCK_TYPE  = 'INVENTORY'
                       AND A.PLANT_ID    = V_A010   /* 'A010' */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) IA
             ORDER BY IA.COMPANY_ID
                 , IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PLANT_ID
                 , IA.ITEM_ID
                 , IA.STOCK_TYPE
                 , IA.STORAGE_ID;

        ELSE

            OPEN O_RC1 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.COMPANY_ID
                         , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD')   AS CUTOFF_DATE
                         , A.SCM_SITE_ID                        AS FROM_SITE
                         , A.PLANT_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                         , A.STOCK_TYPE
                         , A.STORAGE_ID
                         , NVL(B.STORAGE_DESCRIPTION,
                               (SELECT MIN(SA.STORAGE_DESCRIPTION)
                                  FROM SCM_MST_SLOC SA
                                 WHERE SA.PLANT_ID   = A.PLANT_ID
                                   AND SA.STORAGE_ID = A.STORAGE_ID
                                   AND SA.VALID_YN   = 'Y')) AS STORAGE_DESCRIPTION
                         , NVL(A.SCM_QTY, 0)                    AS TOTAL_QTY
                         , NVL(A.SSP_QTY, 0)                    AS AVAILABLE_QTY
                         , A.DEFECT_QTY
                         , A.MOVING_QTY
                         , A.QTY_UOM
                         , NVL(A.WIPHOLD_YN, 'N')               AS WIPHOLD_YN
                         , A.HOLDING_DATE
                         , A.AVAILABLE_DATE
                         , A.OUTSOURCING_FLAG
                         , A.OUTSOURCING_FACTORY
                      FROM SCM_DNM_STOCK_V A
                         , SCM_MST_SLOC B
                         , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME
                              FROM SCM_MST_ITEM_SN
                             WHERE DIVISION_ID = P_DIVISION_ID
                               AND ACTIVE_FLAG = 'Y'
                               AND SCP_OPERATION_GROUP = 'P'   /* CELL/PACK 구분 */
                           ) C
                         , SSP_MST_MODEL_USER M
                     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
                       AND A.PLANT_ID      = B.PLANT_ID(+)
                       AND A.STORAGE_ID    = B.STORAGE_ID(+)
                       AND A.DIVISION_ID   = C.DIVISION_ID
                       AND A.ITEM_ID       = C.ITEM_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.SCM_SITE_ID
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND A.COMPANY_ID  = P_COMPANY_ID
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                       AND A.ORG_CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD') + 1 /* AJS 20261007 속도 : 원장 마감일 조건(뷰 마감일 + 1 과 같은 값) */
                       AND A.CUTOFF_DATE > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')   /* 현재일 - 3 */
                       AND A.STOCK_TYPE  = 'INVENTORY'
                       AND A.PLANT_ID    = V_A010   /* 'A010' */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) IA
             ORDER BY IA.COMPANY_ID
                 , IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PLANT_ID
                 , IA.ITEM_ID
                 , IA.STOCK_TYPE
                 , IA.STORAGE_ID;

        END IF;

    END P_SSP0015_GET_STOCK_LOCATION_DETAIL;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
       AS-IS SSP0015_GET_SHIPMENT_PSI_COMMENTS - 결과셋 2벌(NOTE · Prod Qty)
       ※ AS-IS 는 FN_GET_IN_STR 로 IN 리스트를 만들어 EXEC 로 돌린다.
          선택조건 조립뿐이라 정적 SQL 로 옮겼다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
         * Description  : Shipment Plan Confrim COMMENTS LOAD
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/08/09   MCTHEJ		   [CSR ID:4061695] SSP 시스템 개선 요청건(Shipment Plan)
         * 2023/08/03   jilee          AS BEFORE_QTY, AS GAP 조건 변경
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         *
         ex) EXEC PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_COMMENTS('40','20190811','','','20190809','20191031', ...)
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* Note Load */
        OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.FROM_SITE                                                              AS SITE
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')        AS FROM_SITE_NM
             , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN B.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
             , A.ITEM_ID
             , SUBSTR(A.YYYYMMDD, 1, 4) || '-' || SUBSTR(A.YYYYMMDD, 5, 2) || '-' || SUBSTR(A.YYYYMMDD, 7, 2) AS YYYYMMDD
             , CEIL(NVL(SUM(A.USER_ADD_QTY), 0))                                        AS USER_ADD_QTY
             , NVL(SUM(B.QTY), 0)                                                       AS QTY
             , CEIL(NVL(SUM(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR)), 0)) AS BEFORE_QTY
             , NVL(SUM(B.QTY), 0) - CEIL(NVL(SUM(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR)), 0)) AS GAP
             , NVL(A.COMMENTS, '')                                                      AS COMMENTS
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
          FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT A
             , SSP_ANL_SHIP_PLAN_40 B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.FROM_SITE   = B.FROM_SITE
           AND A.ITEM_ID     = B.ITEM_ID
           AND A.YYYYMMDD    = B.YYYYMMDD
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.MEASURE             = 'WH_IN'
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                 OR  UPPER(P_DIVISION_ID) = 'ALL'     /* 조회조건 ALL 은 조건 없음 */
                 OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
         GROUP BY A.DIVISION_ID
             , B.ORIGIN_FROM_DIVISION_ID
             , A.FROM_SITE
             , A.ITEM_ID
             , A.YYYYMMDD
             , A.COMMENTS
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE;

        /* Prod Qty Load */
        OPEN O_RC2 FOR
        SELECT DIVISION_ID
             , FROM_SITE                                                                AS SITE
             , ITEM_ID
             , SUBSTR(YYYYMMDD, 1, 4) || '-' || SUBSTR(YYYYMMDD, 5, 2) || '-' || SUBSTR(YYYYMMDD, 7, 2) AS YYYYMMDD
             , NVL(ATTRIBUTE3, '')                                                      AS PRODUCT_QTY
          FROM SSP_ANL_SHIP_PLAN_40
         WHERE 1 = 1
           /* AS-IS : (ATTRIBUTE3 IS NOT NULL OR ATTRIBUTE3 != '') - 뒷항은 Oracle 에서 늘 거짓이라 앞항만 남긴다 */
           AND ATTRIBUTE3 IS NOT NULL
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND MEASURE             = 'PROD_PLAN'
           AND YYYYMMDD >= P_FROM_YYYYMMDD
           AND YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                 OR  UPPER(P_DIVISION_ID) = 'ALL'     /* 조회조건 ALL 은 조건 없음 */
                 OR DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
         GROUP BY DIVISION_ID
             , FROM_SITE
             , ITEM_ID
             , YYYYMMDD
             , ATTRIBUTE3;

    END P_SSP0015_GET_SHIPMENT_PSI_COMMENTS;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_RESULT
       AS-IS SSP0015_GET_SHIPMENT_RESULT
       ※ AS-IS WITH 절 5벌은 각각 1회만 참조하므로 인라인 뷰로 펼쳤다(온라인 SQL WITH 금지).
       ※ STUFF(... FOR XML PATH('')) 는 LISTAGG 로 옮겼다. AS-IS 는 정렬이 없으나
          LISTAGG 는 WITHIN GROUP 이 필수라 DEPT_NAME_KO 로 정렬한다.
       ※ AS-IS 의 CASE WHEN DIVISION_ID = '4O' 는 알파벳 O 다(숫자 0 아님).
          결과 동일성을 위해 원형을 그대로 둔다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_RESULT
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_TYPE                  IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_REAL_FLAG             IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_RESULT
         * Description  : Shipment Shipment Result
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/09/26   AYJ			[CSR ID:4037234] 출하계획 대비 실적 Report 개발
         * 2019/12/04   juhlee      [C20191205-000132]  OWMS 출하실적에 반품 내용 적용
         * 2020/01/21   juhlee      [C20200121-000352]  ESS Packer출하 적용
         * 2020/02/12   KIMYONGHO   [C20200218-000135]  SHIP_TYPE 컬럼추가 및 FROM_STIE, TO_SITE Display 변경
         * 2020.05.06	KIMYONGHO   [C20200403-000062] [GSCM PI] SSP 출하 실적 집계 중 사외 창고 제외 로직 추가 건
         * 2020.09.18	KIMYONGHO   ERP_ORDER_TYPE 주석 처리 Request by 김광희 책임
         * 2021.02.17	KIMYONGHO   실적 조회시 TRNSPORT_MODE, INCOTERMS, ERP_SO_NO, ETA_DATE, ETD_DATE ERP 실적 기준으로 조회
         * 2021.04.05   KIMYONGHO   [C20210330-000402] Shipment Plan화면의 실적 조회시 Sales site Mapping 안되는건 전수 표시
         * 2021.05.03   SSP Pjt.    SSP_SHIP_RESULT_EXCEPT_ERP_ORDER_TYPE LOOKUP적용
         * 2021.11.15   KIMYONGHO   Confirm Data Plan Date 기준 조회 처리
         * 2024.10.18   SSP         소형 Team 컬럼 추가
         * 2024.10.29   KHJ         NERP_SSP
         * 2026.09.16   AJS         MSSQL -> Oracle 전환 (WITH -> 인라인 뷰, XML PATH -> LISTAGG)
         * 2026.10.07   AJS         조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        OPEN O_RC1 FOR
        SELECT X.DIVISION_ID
             , B.COMPANY_ID    AS COMPANY_ID
             , C.SEGMENT2      AS TYPE
             , X.ERP_SO_NO
             , X.CONFIRM_ID
             , X.ITEM_ID
             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.FROM_SITE), X.FROM_SITE) AS FROM_SITE
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.TO_SITE), X.TO_SITE)     AS TO_SITE
             , X.TEAM
             , X.END_CUSTOMER
             , X.QTY
             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS YYYYMMDD
             , X.TRANSPORT_MODE
             , X.INCOTERMS
             , CASE WHEN REGEXP_LIKE(X.ETD_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD_DATE
             , CASE WHEN REGEXP_LIKE(X.ETA_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA_DATE
             , X.SHIP_TYPE
          FROM (
                /* CONFIRM_ID, 날짜동일한 기준으로 계획정보의 FROM, TO SITE기준으로 실적 집계 */
                SELECT IA.DIVISION_ID     AS DIVISION_ID
                     , 'E'                AS TYPE
                     , IA.ERP_SO_NO       AS ERP_SO_NO
                     , IA.CONFIRM_ID      AS CONFIRM_ID
                     , IA.ITEM_ID         AS ITEM_ID
                     , IA.FROM_SITE       AS FROM_SITE
                     , IA.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , IA.TEAM            AS TEAM
                     , SUM(IA.RESULT_QTY) AS QTY
                     , IA.YYYYMMDD        AS YYYYMMDD
                     , IA.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , IA.INCOTERMS       AS INCOTERMS
                     , IA.ETD_DATE        AS ETD_DATE
                     , IA.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        /* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                        SELECT E.DIVISION_ID          AS DIVISION_ID
                             , E.CONFIRM_ID           AS CONFIRM_ID
                             , E.ORDER_NO             AS ERP_SO_NO
                             , E.EXFACTORY_DATE       AS YYYYMMDD
                             , E.TRANSPORT_MODE       AS TRANSPORT_MODE
                             , E.INCOTERMS            AS INCOTERMS
                             , E.ETA_DATE             AS ETA_DATE
                             , E.ETD_DATE             AS ETD_DATE
                             , E.FROM_SCM_SITE_ID     AS FROM_SITE
                             , E.TO_SCM_SITE_ID       AS TO_SITE
                             , E.ITEM_ID              AS ITEM_ID
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     , TB_FX_USER SB
--                                   AND SB.USERID IN (SELECT OWNER
                                     , SCM_ADM_USER_M SB
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   AND SB.USER_ID IN (SELECT OWNER
                                     /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID  = E.DIVISION_ID
                                                        AND SCM_SITE_ID  = E.TO_SCM_SITE_ID
                                                        AND ITEM_ID      = E.ITEM_ID
                                                        AND PROJECT_CODE = (SELECT MIN(SC.PROJECT_CODE)
                                                                              FROM SSP_ANL_SHIP_CONFIRM SC
                                                                             WHERE SC.CONFIRM_ID = E.CONFIRM_ID)
                                                        AND VALID_YN     = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                             , SUM(E.EXFACTORY_QTY)   AS RESULT_QTY
                          FROM SCM_DNM_EXFACTORY_RESULT E
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L
                         WHERE L.LOOKUP_TYPE = 'ERP_SSP_TYPE'   /* LOOKUP에 등록된 공정만 */
                           AND L.VALID_YN    = 'Y'
                           AND L.SEGMENT1    = E.SSP_TYPE
                           AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')   /* D90: DO삭제 , D10:DO생성 */
                           AND E.CONFIRM_ID LIKE 'C%'
                           AND E.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY E.DIVISION_ID
                             , E.CONFIRM_ID
                             , E.ORDER_NO
                             , E.EXFACTORY_DATE
                             , E.TRANSPORT_MODE
                             , E.INCOTERMS
                             , E.ETA_DATE
                             , E.ETD_DATE
                             , E.FROM_SCM_SITE_ID
                             , E.TO_SCM_SITE_ID
                             , E.ITEM_ID
                       ) IA
                 GROUP BY IA.DIVISION_ID
                     , IA.ERP_SO_NO
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.ITEM_ID
                     , IA.TRANSPORT_MODE
                     , IA.INCOTERMS
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.YYYYMMDD
                     , IA.CONFIRM_ID
                     , IA.TEAM
                UNION ALL
                /* CONFIRM_ID 없는 실적 */
                SELECT XB.DIVISION_ID     AS DIVISION_ID
                     , 'E'                AS TYPE
                     , XB.ERP_SO_NO       AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XB.ITEM_ID         AS ITEM_ID
                     , XB.FROM_SITE       AS FROM_SITE
                     , XB.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XB.TEAM            AS TEAM
                     , XB.QTY             AS QTY
                     , XB.YYYYMMDD        AS YYYYMMDD
                     , XB.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XB.INCOTERMS       AS INCOTERMS
                     , XB.ETD_DATE        AS ETD_DATE
                     , XB.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        SELECT E.DIVISION_ID          AS DIVISION_ID
                             , '-'                    AS CONFIRM_ID
                             , E.ORDER_NO             AS ERP_SO_NO
                             , E.FROM_SCM_SITE_ID     AS FROM_SITE
                             , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID) AS TO_SITE
                             , E.ITEM_ID              AS ITEM_ID
                             , E.EXFACTORY_DATE       AS YYYYMMDD
                             , E.TRANSPORT_MODE       AS TRANSPORT_MODE
                             , E.INCOTERMS            AS INCOTERMS
                             , E.ETA_DATE             AS ETA_DATE
                             , E.ETD_DATE             AS ETD_DATE
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     , TB_FX_USER SB
--                                   AND SB.USERID IN (SELECT OWNER
                                     , SCM_ADM_USER_M SB
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   AND SB.USER_ID IN (SELECT OWNER
                                     /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID = E.DIVISION_ID
                                                        AND SCM_SITE_ID = E.TO_SCM_SITE_ID
                                                        AND ITEM_ID     = E.ITEM_ID
                                                        AND VALID_YN    = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                             , SUM(E.EXFACTORY_QTY)   AS QTY
                          FROM SCM_DNM_EXFACTORY_RESULT E
                             , SCP_MST_FINAL_ITEM F
                             , SCM_MST_SITE S
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L3
                         WHERE F.ITEM_ID     = E.ITEM_ID       /* SCP 대상 ITEM만 */
                           AND F.DIVISION_ID = E.DIVISION_ID
                           AND S.SCM_SITE_ID = E.FROM_SCM_SITE_ID
                           AND S.DIVISION_ID = E.DIVISION_ID
                           AND L.LOOKUP_TYPE = 'ERP_ORDER_TYPE'   /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                           AND L.VALID_YN    = 'Y'
                           AND L.SEGMENT1    = E.ORDER_TYPE_CODE
                           AND L3.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'   /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                           AND L3.SEGMENT1(+)    = E.DIVISION_ID
                           AND L3.SEGMENT2(+)    = E.SOLDTO_CODE
                           AND L3.SEGMENT3(+)    = E.SHIPTO_CODE
                           AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')   /* D90: DO삭제 , D10:DO생성 */
                           AND NVL(E.CONFIRM_ID, '-') NOT LIKE 'C%'
                           AND E.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND E.STORAGE_ID NOT IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_RESULT', 'PRODUCT_STORAGE')))   /* 상품창고제외 */
                           /* [C20200403-000062] 사외 창고 제외 LOOKUP 관리 */
                           AND NOT EXISTS (SELECT 1
                                             FROM SCM_ADM_LOOKUP_MASTER_DETAIL SB
                                            WHERE SB.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                              AND SB.VALID_YN    = 'Y'
                                              AND SB.SEGMENT1    = E.STORAGE_ID)
                         GROUP BY E.DIVISION_ID
                             , E.ORDER_NO
                             , E.FROM_SCM_SITE_ID
                             , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)
                             , E.ITEM_ID
                             , E.EXFACTORY_DATE
                             , E.TRANSPORT_MODE
                             , E.INCOTERMS
                             , E.ETA_DATE
                             , E.ETD_DATE
                             , E.TO_SCM_SITE_ID
                       ) XB
                UNION ALL
                /* SSP출하계획 ( confirm된 계획) */
                SELECT XC.DIVISION_ID     AS DIVISION_ID
                     , 'P'                AS TYPE
                     , XC.ERP_SO_NO       AS ERP_SO_NO
                     , XC.CONFIRM_ID      AS CONFIRM_ID
                     , XC.ITEM_ID         AS ITEM_ID
                     , XC.FROM_SITE       AS FROM_SITE
                     , XC.TO_SITE         AS TO_SITE
                     , XC.END_CUSTOMER    AS END_CUSTOMER
                     , '-'                AS TEAM
                     , XC.QTY             AS QTY
                     , XC.YYYYMMDD        AS YYYYMMDD
                     , XC.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XC.INCOTERMS       AS INCOTERMS
                     , XC.ETD_DATE        AS ETD_DATE
                     , XC.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        /* Current Version */
                        SELECT C.DIVISION_ID     AS DIVISION_ID
                             , C.ERP_SO_NO       AS ERP_SO_NO
                             , C.CONFIRM_ID      AS CONFIRM_ID
                             , C.ITEM_ID         AS ITEM_ID
                             , C.FROM_SITE       AS FROM_SITE
                             , C.TO_SITE         AS TO_SITE
                               /* AS-IS 원형 유지 : '4O' 는 알파벳 O 다 */
                             , CASE WHEN C.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , C.QTY             AS QTY
                             , C.YYYYMMDD        AS YYYYMMDD
                             , C.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , C.INCOTERMS       AS INCOTERMS
                             , C.ETD_DATE        AS ETD_DATE
                             , C.ETA_DATE        AS ETA_DATE
                          FROM SSP_ANL_SHIP_CONFIRM C
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE SI.DIVISION_ID(+)  = C.DIVISION_ID
                           AND SI.ITEM_ID(+)      = C.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = C.TO_SITE
                           AND SI.PROJECT_CODE(+) = C.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = C.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = C.TO_SITE
                           AND C.CHANGE_TYPE = 'C'
                           AND C.QTY > 0
                           AND C.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND C.CONFIRM_ID LIKE 'C%'
                           AND P_REAL_FLAG = 'Y'
                        UNION ALL
                        /* OLD Version */
                        SELECT D.DIVISION_ID     AS DIVISION_ID
                             , D.ERP_SO_NO       AS ERP_SO_NO
                             , D.CONFIRM_ID      AS CONFIRM_ID
                             , D.ITEM_ID         AS ITEM_ID
                             , D.FROM_SITE       AS FROM_SITE
                             , D.TO_SITE         AS TO_SITE
                             , CASE WHEN D.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , D.SHIPMENT_CONFIRM_QTY AS QTY
                             , D.YYYYMMDD        AS YYYYMMDD
                             , D.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , D.INCOTERMS       AS INCOTERMS
                             , D.ETD             AS ETD_DATE
                             , D.ETA             AS ETA_DATE
                          FROM SSP_ANL_SHIP_PLAN_ALL D
                             , SCM_MST_SITE MS
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE D.DIVISION_ID = MS.DIVISION_ID
                           AND D.FROM_SITE   = MS.SCM_SITE_ID
                           AND MS.SITE_TYPE  = 'PLANT'
                           AND D.DIVISION_ID = '40'
                           AND MS.OPERATION_GROUP = 'A'
                           AND SI.DIVISION_ID(+)  = D.DIVISION_ID
                           AND SI.ITEM_ID(+)      = D.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = D.TO_SITE
                           AND SI.PROJECT_CODE(+) = D.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = D.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = D.TO_SITE
                           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND D.SHIPMENT_STATUS     = 'C'
                           AND D.SHIPMENT_CONFIRM_QTY > 0
                           AND D.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'N'
                       ) XC
                UNION ALL
                /* OWMS 실적 */
                SELECT XD.DIVISION_ID     AS DIVISION_ID
                     , 'O'                AS TYPE
                     , NULL               AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XD.ITEM_ID         AS ITEM_ID
                     , XD.FROM_SITE       AS FROM_SITE
                     , XD.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XD.TEAM            AS TEAM
                     , XD.QTY             AS QTY
                     , XD.YYYYMMDD        AS YYYYMMDD
                     , NULL               AS TRANSPORT_MODE
                     , NULL               AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , XD.SHIP_TYPE       AS SHIP_TYPE
                  FROM (
                        SELECT A.DIVISION_ID      AS DIVISION_ID
                             , A.ITEM_ID          AS ITEM_ID
                             , A.FROM_SITE        AS FROM_SITE
                             , CASE WHEN A.TO_SITE = '-' THEN A.CUSTOMER_CODE ELSE A.TO_SITE END AS TO_SITE
                             , SUM(A.LOT_QTY)     AS QTY
                             , A.PLANT_ISSUE_DATE AS YYYYMMDD
                             , A.SHIP_TYPE        AS SHIP_TYPE
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     , TB_FX_USER SB
--                                   AND SB.USERID IN (SELECT OWNER
                                     , SCM_ADM_USER_M SB
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   AND SB.USER_ID IN (SELECT OWNER
                                     /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID = A.DIVISION_ID
                                                        AND SCM_SITE_ID = A.TO_SITE
                                                        AND ITEM_ID     = A.ITEM_ID
                                                        AND VALID_YN    = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                          FROM SSP_DNM_SHIP_RESULT_OWMS A
                         WHERE A.PLANT_ISSUE_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY A.DIVISION_ID
                             , A.ITEM_ID
                             , A.FROM_SITE
                             , CASE WHEN A.TO_SITE = '-' THEN A.CUSTOMER_CODE ELSE A.TO_SITE END
                             , A.PLANT_ISSUE_DATE
                             , A.SHIP_TYPE
                             , A.TO_SITE
                       ) XD
                UNION ALL
                /* OWMS 반품실적 */
                SELECT XE.DIVISION_ID     AS DIVISION_ID
                     , 'R'                AS TYPE
                     , NULL               AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XE.ITEM_ID         AS ITEM_ID
                     , XE.FROM_SITE       AS FROM_SITE
                     , XE.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , '-'                AS TEAM
                     , XE.QTY             AS QTY
                     , XE.YYYYMMDD        AS YYYYMMDD
                     , NULL               AS TRANSPORT_MODE
                     , NULL               AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , XE.SHIP_TYPE       AS SHIP_TYPE
                  FROM (
                        SELECT B.DIVISION_ID      AS DIVISION_ID
                             , B.ITEM_ID          AS ITEM_ID
                             , B.FROM_SITE        AS FROM_SITE
                             , '*'                AS TO_SITE
                             , SUM(B.RECIEPT_QTY) AS QTY
                             , B.RECIEPT_DATE     AS YYYYMMDD
                             , NULL               AS SHIP_TYPE
                          FROM SSP_DNM_SHIP_RETURN_OWMS B
                         WHERE B.RECIEPT_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY B.DIVISION_ID
                             , B.ITEM_ID
                             , B.FROM_SITE
                             , B.RECIEPT_DATE
                       ) XE
               ) X
             , SCM_MST_SITE B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
             , SSP_MST_MODEL_USER M
         WHERE B.DIVISION_ID = X.DIVISION_ID
           AND B.SCM_SITE_ID = X.FROM_SITE
           AND B.OPERATION_GROUP <> 'E'
           AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE'   /* LOOKUP에 등록된 공정만 */
           AND C.SEGMENT1    = X.TYPE
           AND C.VALID_YN    = 'Y'
           AND M.DIVISION_ID(+) = X.DIVISION_ID
           AND M.FROM_SITE(+)   = X.FROM_SITE
           AND M.ITEM_ID(+)     = X.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           AND X.DIVISION_ID = P_DIVISION_ID
           AND ((P_COMPANY_ID IS NULL OR P_COMPANY_ID = '') OR B.COMPANY_ID = P_COMPANY_ID)
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR X.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_TYPE IS NULL OR P_TYPE = '')
                 OR X.TYPE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_TYPE, ','))))
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         ORDER BY X.DIVISION_ID
             , X.FROM_SITE
             , X.YYYYMMDD
             , X.ITEM_ID
             , X.TO_SITE
             , C.DISPLAY_SEQ
             , X.CONFIRM_ID;

    END P_SSP0015_GET_SHIPMENT_RESULT;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_RESULT_PACKER
       AS-IS SSP0015_GET_SHIPMENT_RESULT_PACKER
       ※ AS-IS WITH 절 3벌은 각각 1회만 참조하므로 인라인 뷰로 펼쳤다.
       ※ AS-IS 의 CASE WHEN DIVISION_ID = '4O' 는 알파벳 O 다. 원형 유지.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_RESULT_PACKER
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_TYPE                  IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_REAL_FLAG             IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_RESULT_PACKER
         * Description  : Shipment Shipment Result
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021/10/05   KIMYONGHO		신규추가
         * 2021/11/26   SMS		        Ship to 추가
         * 2026.09.16   AJS             MSSQL -> Oracle 전환 (WITH -> 인라인 뷰)
         * 2026.10.07   AJS             조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        OPEN O_RC1 FOR
        SELECT X.DIVISION_ID
             , B.COMPANY_ID    AS COMPANY_ID
             , C.SEGMENT2      AS TYPE
             , X.ERP_SO_NO
             , X.CONFIRM_ID
             , X.ITEM_ID
             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.FROM_SITE), X.FROM_SITE) AS FROM_SITE
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.TO_SITE), X.TO_SITE)     AS TO_SITE
             , X.END_CUSTOMER
             , X.QTY
             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS YYYYMMDD
             , X.TRANSPORT_MODE
             , X.INCOTERMS
             , CASE WHEN REGEXP_LIKE(X.ETD_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD_DATE
             , CASE WHEN REGEXP_LIKE(X.ETA_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA_DATE
             , X.SHIP_TYPE
               /* 20211126  SMS  추가 Ship to, Shipto description */
             , X.SHIP_TO
             , D.SHIPTO_DESCRIPTION
          FROM (
                /* SCS 출하실적에서 CONFIRM_ID 존재 */
                SELECT IA.DIVISION_ID     AS DIVISION_ID
                     , 'S'                AS TYPE
                     , IA.ERP_SO_NO       AS ERP_SO_NO
                     , IA.CONFIRM_ID      AS CONFIRM_ID
                     , IA.ITEM_ID         AS ITEM_ID
                     , IA.FROM_SITE       AS FROM_SITE
                     , IA.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , SUM(IA.RESULT_QTY) AS QTY
                     , IA.YYYYMMDD        AS YYYYMMDD
                     , IA.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , IA.INCOTERMS       AS INCOTERMS
                     , IA.ETD_DATE        AS ETD_DATE
                     , IA.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , IA.SHIP_TO         AS SHIP_TO
                  FROM (
                        SELECT E.DIVISION_ID      AS DIVISION_ID
                             , E.ATTRIBUTE5       AS CONFIRM_ID
                             , C.ERP_SO_NO        AS ERP_SO_NO
                             , E.SHIP_DATE        AS YYYYMMDD
                             , C.TRANSPORT_MODE   AS TRANSPORT_MODE
                             , C.INCOTERMS        AS INCOTERMS
                             , C.ETA_DATE         AS ETA_DATE
                             , C.ETD_DATE         AS ETD_DATE
                             , E.SCM_SITE_ID      AS FROM_SITE
                             , E.TO_SITE          AS TO_SITE
                             , E.ITEM_ID          AS ITEM_ID
                               /* 20211126  SMS  추가  Ship to */
                             , E.ATTRIBUTE4       AS SHIP_TO
                             , SUM(E.SHIP_QTY)    AS RESULT_QTY
                          FROM SCM_DNM_SCS_SHIP_RESULT E
                             , SSP_ANL_SHIP_CONFIRM C
                         WHERE E.DIVISION_ID = C.DIVISION_ID(+)
                           AND E.ATTRIBUTE5  = C.CONFIRM_ID(+)
                           AND E.SHIP_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY E.DIVISION_ID
                             , E.ATTRIBUTE5
                             , C.ERP_SO_NO
                             , E.SHIP_DATE
                             , C.TRANSPORT_MODE
                             , C.INCOTERMS
                             , C.ETA_DATE
                             , C.ETD_DATE
                             , E.SCM_SITE_ID
                             , E.TO_SITE
                             , E.ITEM_ID
                             , E.ATTRIBUTE4
                       ) IA
                 GROUP BY IA.DIVISION_ID
                     , IA.ERP_SO_NO
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.ITEM_ID
                     , IA.TRANSPORT_MODE
                     , IA.INCOTERMS
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.YYYYMMDD
                     , IA.CONFIRM_ID
                     , IA.SHIP_TO
                UNION ALL
                /* SCS 출하실적에서 CONFIRM_ID 없는 실적 */
                SELECT XB.DIVISION_ID     AS DIVISION_ID
                     , 'S'                AS TYPE
                     , XB.ERP_SO_NO       AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XB.ITEM_ID         AS ITEM_ID
                     , XB.FROM_SITE       AS FROM_SITE
                     , XB.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XB.RESULT_QTY      AS QTY
                     , XB.YYYYMMDD        AS YYYYMMDD
                     , XB.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XB.INCOTERMS       AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , XB.SHIP_TO         AS SHIP_TO
                  FROM (
                        SELECT E.DIVISION_ID      AS DIVISION_ID
                             , E.ATTRIBUTE5       AS CONFIRM_ID
                             , '-'                AS ERP_SO_NO
                             , E.SHIP_DATE        AS YYYYMMDD
                             , '-'                AS TRANSPORT_MODE
                             , '-'                AS INCOTERMS
                             , '-'                AS ETA_DATE
                             , '-'                AS ETD_DATE
                             , E.SCM_SITE_ID      AS FROM_SITE
                             , E.TO_SITE          AS TO_SITE
                             , E.ITEM_ID          AS ITEM_ID
                             , E.ATTRIBUTE4       AS SHIP_TO
                             , SUM(E.SHIP_QTY)    AS RESULT_QTY
                          FROM SCM_DNM_SCS_SHIP_RESULT E
                         WHERE E.SHIP_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND NVL(E.ATTRIBUTE5, '-') = '-'
                         GROUP BY E.DIVISION_ID
                             , E.ATTRIBUTE5
                             , E.SHIP_DATE
                             , E.ITEM_ID
                             , E.SCM_SITE_ID
                             , E.TO_SITE
                             , E.ATTRIBUTE4
                       ) XB
                UNION ALL
                /* SSP출하계획 ( confirm된 계획) */
                SELECT XC.DIVISION_ID     AS DIVISION_ID
                     , 'P'                AS TYPE
                     , XC.ERP_SO_NO       AS ERP_SO_NO
                     , XC.CONFIRM_ID      AS CONFIRM_ID
                     , XC.ITEM_ID         AS ITEM_ID
                     , XC.FROM_SITE       AS FROM_SITE
                     , XC.TO_SITE         AS TO_SITE
                     , XC.END_CUSTOMER    AS END_CUSTOMER
                     , XC.QTY             AS QTY
                     , XC.YYYYMMDD        AS YYYYMMDD
                     , XC.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XC.INCOTERMS       AS INCOTERMS
                     , XC.ETD_DATE        AS ETD_DATE
                     , XC.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , XC.SHIP_TO         AS SHIP_TO
                  FROM (
                        /* Current Version */
                        SELECT C.DIVISION_ID     AS DIVISION_ID
                             , C.ERP_SO_NO       AS ERP_SO_NO
                             , C.CONFIRM_ID      AS CONFIRM_ID
                             , C.ITEM_ID         AS ITEM_ID
                             , C.FROM_SITE       AS FROM_SITE
                             , C.TO_SITE         AS TO_SITE
                             , CASE WHEN C.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , C.QTY             AS QTY
                             , C.YYYYMMDD        AS YYYYMMDD
                             , C.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , C.INCOTERMS       AS INCOTERMS
                             , C.ETD_DATE        AS ETD_DATE
                             , C.ETA_DATE        AS ETA_DATE
                             , C.TO_SITE_SHIPTO_CODE AS SHIP_TO
                          FROM SSP_ANL_SHIP_CONFIRM C
                             , SCM_MST_SITE MS
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE C.DIVISION_ID = MS.DIVISION_ID
                           AND C.FROM_SITE   = MS.SCM_SITE_ID
                           AND MS.SITE_TYPE  = 'PLANT'
                           AND C.DIVISION_ID = '40'
                           AND MS.OPERATION_GROUP = 'P'
                           AND SI.DIVISION_ID(+)  = C.DIVISION_ID
                           AND SI.ITEM_ID(+)      = C.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = C.TO_SITE
                           AND SI.PROJECT_CODE(+) = C.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = C.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = C.TO_SITE
                           AND TS.VALID_YN(+)     = 'Y'   /* NERP 추가 */
                           AND C.CHANGE_TYPE = 'C'
                           AND C.QTY > 0
                           AND C.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'Y'
                        UNION ALL
                        /* OLD Version */
                        SELECT D.DIVISION_ID     AS DIVISION_ID
                             , NULL              AS ERP_SO_NO
                             , D.CONFIRM_ID      AS CONFIRM_ID
                             , D.ITEM_ID         AS ITEM_ID
                             , D.FROM_SITE       AS FROM_SITE
                             , V.TO_SITE         AS TO_SITE
                             , CASE WHEN D.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , D.QTY             AS QTY
                             , D.YYYYMMDD        AS YYYYMMDD
                             , V.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , V.INCOTERMS       AS INCOTERMS
                             , D.ETD_DATE        AS ETD_DATE
                             , D.ETA_DATE        AS ETA_DATE
                             , D.SHIPTO_CODE     AS SHIP_TO
                          FROM SSP_ANL_SHIP_PLAN_P D
                             , SCP_MST_BOD_N_V V
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE D.BOD_ID = V.BOD_ID
                           AND SI.DIVISION_ID(+)  = D.DIVISION_ID
                           AND SI.ITEM_ID(+)      = D.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = V.TO_SITE
                           AND SI.PROJECT_CODE(+) = D.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = D.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = V.TO_SITE
                           AND TS.VALID_YN(+)     = 'Y'   /* NERP 추가 */
                           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND D.MEASURE      = 'SHIP_CONFIRM'
                           AND D.CONFIRM_FLAG = 'Y'
                           AND D.QTY > 0
                           AND D.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'N'
                       ) XC
               ) X
             , SCM_MST_SITE B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
             , SSP_MST_MODEL_USER M
               /* 20211126  SMS  추가  Shipto Description */
             , (SELECT DIVISION_ID, SHIPTO_CODE, MAX(SHIPTO_DESCRIPTION) AS SHIPTO_DESCRIPTION
                  FROM SCM_MST_CUSTOMER
                 WHERE DIVISION_ID = '40'
                 GROUP BY DIVISION_ID, SHIPTO_CODE) D
         WHERE B.DIVISION_ID = X.DIVISION_ID
           AND B.SCM_SITE_ID = X.FROM_SITE
           AND B.OPERATION_GROUP <> 'E'
           AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE_PACKER'   /* LOOKUP에 등록된 공정만 */
           AND C.SEGMENT1    = X.TYPE
           AND C.VALID_YN    = 'Y'
           AND M.DIVISION_ID(+) = X.DIVISION_ID
           AND M.FROM_SITE(+)   = X.FROM_SITE
           AND M.ITEM_ID(+)     = X.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           AND X.DIVISION_ID = D.DIVISION_ID(+)
           AND X.SHIP_TO     = D.SHIPTO_CODE(+)
           AND X.DIVISION_ID = P_DIVISION_ID
           AND ((P_COMPANY_ID IS NULL OR P_COMPANY_ID = '') OR B.COMPANY_ID = P_COMPANY_ID)
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR X.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_TYPE IS NULL OR P_TYPE = '')
                 OR X.TYPE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_TYPE, ','))))
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         ORDER BY X.DIVISION_ID
             , X.FROM_SITE
             , X.YYYYMMDD
             , X.ITEM_ID
             , X.TO_SITE
             , C.DISPLAY_SEQ
             , X.CONFIRM_ID;

    END P_SSP0015_GET_SHIPMENT_RESULT_PACKER;


    /* ============================================================
       P_SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING
       AS-IS SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING
       ※ 오류 시 되돌리기를 커서 OPEN 앞에 둔다(ROLLBACK 이 뒤에 오면 커서가 닫힌다).
       ============================================================ */
    PROCEDURE P_SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING
    (
        P_CHANGE_REQUEST_NO     IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING
         * Description  : Shipment Plan Change 작성중 삭제
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME      VARCHAR2(150 CHAR) := 'SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING';
        V_LOG_TYPE          VARCHAR2(30 CHAR);
        N_LOG_COUNT         NUMBER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000 CHAR);
        V_DESCRIPTION       VARCHAR2(500 CHAR);
        D_EVENT_DATE        DATE;
        V_LAST_UPDATE_DATE  DATE := SYSDATE;
        V_ERR_CODE          NUMBER;
        V_ERR_MESSAGE       VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_DEL_DRAFT;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := V_LAST_UPDATE_DATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
           SET VALID_YN         = 'N'
             , LAST_UPDATED_BY  = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
           SET VALID_YN         = 'N'
             , LAST_UPDATED_BY  = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_DEL_DRAFT;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE FROM DUAL;
            OPEN O_RC2 FOR SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_DELETE_SHIPMENT_REQUEST_DRAFTING;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
       AS-IS SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
       ※ AS-IS 는 문자열을 조립해 EXEC 로 돌리지만 만드는 것은 선택조건뿐이다.
          날짜 칸을 만드는 피벗이 아니므로 정적 SQL 로 옮겼다.
       ※ P_REAL_FLAG 갈래에 따라 결과셋의 칸 구성이 다르다(AS-IS 동일).
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_REQUESTOR             IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_SEARCH_YN             IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2 DEFAULT 'N',
        P_REAL_FLAG             IN  VARCHAR2 DEFAULT 'N',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'T',
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/03/11   AYJ 			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/05/09   AYJ 			MyModel 체크여부에 따른 조회조건 분기처리
         * 2019/05/20	AYJ				[CSR ID:3994743] REQUESTOR 컬럼 추가
         * 2019/06/17	AYJ			    조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			    조회 조건 추가(p_delegateeChk)
         * 2019/12/17	KIMYONGHO		[C20191216-000311] Expected Shipping Date 컬럼 추가
         * 2020/09/21   KIMYONHHO      SSP INCOTERMS 변경 작업
         * 2021/02/04   KIMYONGHO	    ETA_DATE 조회 시 항차를 고려한 LT 적용되도록 함수 적용 FN_GET_SSP_ETA_DATE
         * 2021/10/05   SHINMYUNGSU	    SSP_ANL_SHIP_CONFIRM 의 Attribute3,6 항목 추가
         * 2021/10/12   KIMYONGHO	    [C20211001-000241] Confirm 복사하여 신규 생성 기능 추가
         * 2023/09/21   jilee          G182-P (Group='P',OSP='N')조회 추가
         * 2024/09/03   SSP            Team 컬럼 추가
         * 2024/10/01   KHJ            NERP_SSP
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ERP_SO_NO
                         , A.SHIPMENT_STATUS
                         , A.PROJECT_CODE
                         , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME
                         , A.FCST_TYPE
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , A.BEFORE_QTY                      AS BEFORE_QTY
                         , TRUNC(A.QTY)                      AS SHIPMENT_CONFIRM_QTY
                         , A.REMARKS
                         , A.REMARKS2
                         , A.REMARKS3
                         , A.FROM_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                         , A.TO_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                         , A.TO_SITE_SOLDTO_CODE
                         , A.TO_SITE_SHIPTO_CODE
                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                         , A.BOD_ID
                         , B.SSP_INCOTERMS                   AS INCOTERMS
                         , B.TRANSPORT_MODE
                         , B.LT_TOTAL                        AS LT_DAY
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                         , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                                ELSE (SELECT CASE WHEN REGEXP_LIKE(SA.V, '^[0-9]{8}$')
                                                  THEN TO_CHAR(TO_DATE(SA.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                        FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) AS V FROM DUAL) SA)
                           END                               AS EXPECTED_SHIPPING_DATE
                         , A.CONFIRM_ID
                         /* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                         , CASE WHEN U.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                           END                               AS UPDATED_BY
                         , CASE WHEN U.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                         /* 2026.09.30 AJS 수정 (END) */
                         , A.ERP_STATUS
                         , A.CHANGE_TYPE
                           /* AS-IS 는 UNION 반대편이 '-' 라 문자로 쓰인다. Oracle 은 NUMBER 라 문자로 맞춘다. */
                         , TO_CHAR(A.ROUTE_ID)               AS NEW_ROUTE_ID
                         , A.BOD_ID                          AS NEW_BOD_ID
                         , B.SSP_INCOTERMS                   AS NEW_INCOTERMS
                         , A.D_COUNTRY                       AS NEW_D_COUNTRY
                         , A.D_PORT_CODE                     AS NEW_D_PORT_CODE
                         , A.A_COUNTRY                       AS NEW_A_COUNTRY
                         , A.A_PORT_CODE                     AS NEW_A_PORT_CODE
                         , TO_CHAR(A.CUSTOMER_LT)            AS NEW_CUSTOMER_LT
                         , A.TO_COUNTRY                      AS NEW_TO_COUNTRY
                         , A.TO_CITY                         AS NEW_TO_CITY
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETA
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETD
                         , TO_CHAR(B.LT_TOTAL)               AS NEW_LT_DAY
                         , B.TRANSPORT_MODE                  AS NEW_TRANSPORT_MODE
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_SHIPMENT_DATE
                         , 'N'                               AS EDIT_REMARKS
                         , 'N'                               AS EDIT_MAIN
                         , NVL(A.CHECK_NEED_YN, 'N')         AS CHECK_NEED_YN
                         , NVL(CASE WHEN A.DIVISION_ID = '40'
                                    THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE != '-'
                                              THEN A.PROJECT_CODE ELSE G.PROJECT_CODE END
                                    WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                    THEN G.PROJECT_CODE
                                    ELSE F.END_CUSTOMER END, '/') AS END_CUSTOMER
                         , A.ELECTRODE_YN
                         , A.ELECTRODE_TYPE
                         , A.ORIGIN_FROM_DIVISION_ID
                         , A.ORIGIN_TO_DIVISION_ID
                         , H.CHANGE_REQ_NO
                         /* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                         /* 2026.09.30 AJS 수정 (END) */
                           END                               AS MODEL_USER
                         , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
                         , (SELECT NVL(MIN(SA.DEPT_NAME_KO), '-')
                              FROM SCM_MST_SSO_DEPT_INFO SA
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER SB
--                               AND SB.USERID  = SI.OWNER)    AS TEAM
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                                 , SCM_ADM_USER_M SB
                             WHERE SA.DEPT_ID = SB.DEPT_ID(+)
                               AND SB.USER_ID = SI.OWNER)    AS TEAM
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
                                 /* 2026.09.30 AJS 수정 (END) */
                           END                               AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , ''                                AS CHANGE_REASON_DETAIL
                           /* [C20211001-000241] Confirm 복사하여 신규 생성 기능 추가 */
                         , NVL(A.ATTRIBUTE10, '-')           AS ATTRIBUTE10
                           /* 2021/10/05 SHINMYUNGSU 열람 항목추가 */
                         , NVL(A.ATTRIBUTE3, '-')            AS ATTRIBUTE3
                         , NVL(A.ATTRIBUTE6, '-')            AS ATTRIBUTE6
                      FROM SSP_ANL_SHIP_CONFIRM A
                         , SCM_MST_SITE MS
                         , SCP_MST_BOD_N_V B
                         /* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U
                         , SCM_ADM_USER_M U
                         /* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE F
                         , (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                              FROM (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                      FROM SCM_MST_SITE_ITEM)
                             WHERE NUM = 1) G
                         , (SELECT CONFIRM_ID, CHANGE_REQ_NO
                              FROM (SELECT CONFIRM_ID, CHANGE_REQ_NO
                                         , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC) AS NUM
                                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                     WHERE VALID_YN = 'Y')
                             WHERE NUM = 1) H
                         , SSP_MST_MODEL_USER MU
                         /* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U2
--                         , TB_FX_USER U3
                         , SCM_ADM_USER_M U2
                         , SCM_ADM_USER_M U3
                         /* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE_ITEM SI
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ T1
                     WHERE A.DIVISION_ID = MS.DIVISION_ID
                       AND A.FROM_SITE   = MS.SCM_SITE_ID
                       AND MS.SITE_TYPE  = 'PLANT'
                       AND A.DIVISION_ID = '40'
                       AND (MS.OPERATION_GROUP = 'A' OR MS.OSP_YN = 'N')
                       AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END = B.DIVISION_ID
                       AND A.BOD_ID      = B.BOD_ID
                       /* 2026.09.30 AJS 수정 (START) */
--                       AND A.LAST_UPDATED_BY = U.USERID(+)
--                       AND U.USEYN(+)        = 'Y'
                       AND A.LAST_UPDATED_BY = U.USER_ID(+)
                       AND U.USE_YN(+)       = 'Y'
                       /* 2026.09.30 AJS 수정 (END) */
                       AND F.DIVISION_ID(+)  = A.ORIGIN_TO_DIVISION_ID
                       AND F.SCM_SITE_ID(+)  = A.TO_SITE
                       AND F.VALID_YN(+)     = 'Y'
                       AND G.DIVISION_ID(+)  = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND G.SCM_SITE_ID(+)  = A.TO_SITE
                       AND G.ITEM_ID(+)      = A.ITEM_ID
                       AND H.CONFIRM_ID(+)   = A.CONFIRM_ID
                       AND MU.DIVISION_ID(+) = A.ORIGIN_FROM_DIVISION_ID
                       AND MU.FROM_SITE(+)   = A.FROM_SITE
                       AND MU.ITEM_ID(+)     = A.ITEM_ID
                       AND MU.VALID_YN(+)    = 'Y'
                       /* 2026.09.30 AJS 수정 (START) */
--                       AND MU.USER_ID        = U2.USERID(+)
--                       AND U2.USEYN(+)       = 'Y'
--                       AND A.REQUESTOR       = U3.USERID(+)
--                       AND U3.USEYN(+)       = 'Y'
                       AND MU.USER_ID        = U2.USER_ID(+)
                       AND U2.USE_YN(+)      = 'Y'
                       AND A.REQUESTOR       = U3.USER_ID(+)
                       AND U3.USE_YN(+)      = 'Y'
                       /* 2026.09.30 AJS 수정 (END) */
                       AND SI.DIVISION_ID(+)  = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND SI.SCM_SITE_ID(+)  = A.TO_SITE
                       AND SI.ITEM_ID(+)      = A.ITEM_ID
                       AND SI.PROJECT_CODE(+) = A.PROJECT_CODE
                       AND H.CHANGE_REQ_NO    = T1.CHANGE_REQ_NO(+)
                       /* Search 버튼으로 조회(체크박스 체크 여부에 따라 조회) */
                       AND (P_SEARCH_YN != 'Y'
                             OR ((P_NONCHK = 'Y' AND 1 = 1)
                                  OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                     UNION
                                                    SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                      FROM SSP_MST_DELEGATE
                                                     WHERE VALID_YN = 'Y'
                                                       AND DELEGATEE_ID = P_USER_ID
                                                     GROUP BY USER_ID)
                                  OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                  OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                       AND A.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD <= P_TO_YYYYMMDD
                       AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                             OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                             /* 2026.09.30 AJS 수정 (START) */
--                             OR A.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                  FROM TB_FX_USER SA
--                                                 WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                    OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             OR A.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                  FROM SCM_ADM_USER_M SA
                                                 WHERE SA.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                    OR SA.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             /* 2026.09.30 AJS 수정 (END) */
                       AND A.SHIPMENT_STATUS IS NOT NULL
                       AND A.QTY > 0
                       AND A.CHANGE_TYPE <> 'N'
                       AND A.BIZ_TYPE    <> 'E'
                    UNION ALL
                    SELECT T.DIVISION_ID
                         , T.ERP_SO_NO
                         , T.SHIPMENT_STATUS
                         , T.PROJECT_CODE
                         , T.PROJECT_NAME
                         , T.FCST_TYPE
                         , T.ITEM_ID
                         , T.NICK_NAME
                         , CASE WHEN REGEXP_LIKE(T.SHIPMENT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(T.SHIPMENT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , 0                                 AS BEFORE_QTY
                         , T.QTY                             AS SHIPMENT_CONFIRM_QTY
                         , T.REMARKS
                         , T.REMARKS2
                         , T.REMARKS3
                         , T.FROM_SITE
                         , T.FROM_SITE_DESCRIPTION
                         , T.TO_SITE
                         , T.TO_SITE_DESCRIPTION
                         , T.TO_SITE_SOLDTO_CODE
                         , T.TO_SITE_SHIPTO_CODE
                         , T.SOLDTO_DESCRIPTION
                         , T.SHIPTO_DESCRIPTION
                         , T.BOD_ID
                         , T.INCOTERMS
                         , T.TRANSPORT_MODE
                         , T.LT_TOTAL                        AS LT_DAY
                         , T.ETD
                         , T.ETA
                         , T.EXPECTED_SHIPPING_DATE
                         , T.CONFIRM_ID
                         , T.LAST_UPDATED_BY                 AS UPDATED_BY
                         , T.LAST_UPDATE_DATE                AS UPDATED_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
                         , '-'                               AS NEW_ROUTE_ID
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
                         , '-'                               AS NEW_CUSTOMER_LT
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
                         , '-'                               AS NEW_LT_DAY
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , '-'                               AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , '-'                               AS CHANGE_REQ_NO
                         , '-'                               AS MODEL_USER
                         , TO_CLOB('-')                      AS MTK_OWNER
                         , '-'                               AS TEAM
                         , '-'                               AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                         , '-'                               AS ATTRIBUTE10
                         , '-'                               AS ATTRIBUTE3
                         , '-'                               AS ATTRIBUTE6
                      FROM (
                            SELECT TT0.DIVISION_ID
                                 , NULL                       AS ERP_SO_NO
                                 , 'P'                        AS SHIPMENT_STATUS
                                 , TT0.ITEM_ID
                                 , FN_GET_ITEM_NICKNAME(TT0.DIVISION_ID, TT0.ITEM_ID) AS NICK_NAME
                                 , TT0.DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID
                                 , TT0.DIVISION_ID            AS ORIGIN_TO_DIVISION_ID
                                 , TT0.PLANT_SITE_ID          AS FROM_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT0.PLANT_SITE_ID), '-') AS FROM_SITE_DESCRIPTION
                                 , TT0.SCM_SITE_ID            AS TO_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT0.SCM_SITE_ID), '-')   AS TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , FN_GET_PROJECT_NAME(TT0.DIVISION_ID, TT0.PROJECT_CODE) AS PROJECT_NAME
                                 , '-'                        AS REQUESTOR
                                 , TT0.QTY
                                 , TT0.YYYYMMDD               AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT0.INCOTERMS
                                 , TT0.TRANSPORT_MODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SOLDTO_CODE')        AS TO_SITE_SOLDTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SHIPTO_CODE')        AS TO_SITE_SHIPTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                                 , '-'                        AS REMARKS2
                                 , '-'                        AS REMARKS
                                 , '-'                        AS CHANGE_REQ_NO
                                 , '-'                        AS REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , (SELECT CASE WHEN REGEXP_LIKE(SA.V, '^[0-9]{8}$')
                                                THEN TO_CHAR(TO_DATE(SA.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                      FROM (SELECT FN_GET_SSP_ETA_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SA) AS ETA
                                 , CASE WHEN TT0.TRANSPORT_MODE = 'TRK' THEN '-'
                                        ELSE (SELECT CASE WHEN REGEXP_LIKE(SB.V, '^[0-9]{8}$')
                                                          THEN TO_CHAR(TO_DATE(SB.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                                FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SB)
                                   END                        AS EXPECTED_SHIPPING_DATE
                                 , TT1.LT_TOTAL
                                 , TT0.LAST_UPDATED_BY
                                 , TT0.LAST_UPDATE_DATE
                                 , '-'                        AS CONFIRM_ID
                                 , TT0.FCST_TYPE
                                 , CASE WHEN NVL(TT2.SHIP_FROZEN, 0) > 0
                                        THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + NVL(TT2.SHIP_FROZEN, 0), 'YYYYMMDD')
                                        ELSE P_PLAN_START_YYYYMMDD END AS FROZEN_YYYYMMDD
                              FROM DM_PLN_SHIPMENT_REQ TT0
                                 , SCP_MST_BOD_N_V TT1
                                 , SCM_MST_SITE TT2
                                 , SSP_MST_MODEL_USER MU
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER U2
                                 , SCM_ADM_USER_M U2
                                 /* 2026.09.30 AJS 수정 (END) */
                             WHERE TT0.DIVISION_ID = TT1.DIVISION_ID
                               AND TT0.BOD_ID      = TT1.BOD_ID
                               AND TT0.DIVISION_ID = TT2.DIVISION_ID
                               AND TT0.PLANT_SITE_ID = TT2.SCM_SITE_ID
                               AND TT2.SITE_TYPE   = 'PLANT'
                               AND TT2.VALID_YN    = 'Y'
                               AND MU.DIVISION_ID(+) = TT0.DIVISION_ID
                               AND MU.FROM_SITE(+)   = TT0.PLANT_SITE_ID
                               AND MU.ITEM_ID(+)     = TT0.ITEM_ID
                               AND MU.VALID_YN(+)    = 'Y'
                               /* 2026.09.30 AJS 수정 (START) */
--                               AND MU.USER_ID        = U2.USERID(+)
--                               AND U2.USEYN(+)       = 'Y'
                               AND MU.USER_ID        = U2.USER_ID(+)
                               AND U2.USE_YN(+)      = 'Y'
                               /* 2026.09.30 AJS 수정 (END) */
                               AND TT0.DIVISION_ID   = P_DIVISION_ID
                               AND (P_SEARCH_YN != 'Y'
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                             UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN = 'Y'
                                                               AND DELEGATEE_ID = P_USER_ID
                                                             GROUP BY USER_ID)
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                           ) T
                     WHERE 1 = 1
                       AND T.SHIPMENT_DATE >= T.FROZEN_YYYYMMDD
                       AND T.SHIPMENT_DATE >= P_FROM_YYYYMMDD
                       AND T.SHIPMENT_DATE <= P_TO_YYYYMMDD
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR T.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR T.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR T.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                             /* 2026.09.30 AJS 수정 (START) */
--                             OR T.LAST_UPDATED_BY IN (SELECT DISTINCT SA.USERID
--                                                        FROM TB_FX_USER SA
--                                                       WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                          OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             OR T.LAST_UPDATED_BY IN (SELECT DISTINCT SA.USER_ID
                                                        FROM SCM_ADM_USER_M SA
                                                       WHERE SA.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                          OR SA.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             /* 2026.09.30 AJS 수정 (END) */
                   ) AA
             ORDER BY AA.DIVISION_ID
                 , AA.SHIPMENT_STATUS
                 , AA.SHIPMENT_DATE
                 , AA.ITEM_ID
                 , AA.ERP_SO_NO DESC
                 , AA.FROM_SITE
                 , AA.TO_SITE
                 , AA.PROJECT_CODE
                 , AA.FCST_TYPE;

        ELSE

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT T0.DIVISION_ID
                         , T0.ERP_SO_NO
                         , T0.SHIPMENT_STATUS
                         , T0.PROJECT_CODE
                         , T0.PROJECT_NAME
                         , T0.FCST_TYPE
                         , T0.ITEM_ID
                         , T0.NICK_NAME
                         , T0.SHIPMENT_DATE
                         , T0.SHIPMENT_CONFIRM_QTY
                         , T0.REMARKS
                         , T0.REMARKS2
                         , T0.REMARKS3
                         , T0.FROM_SITE
                         , T0.FROM_SITE_DESCRIPTION
                         , T0.TO_SITE
                         , T0.TO_SITE_DESCRIPTION
                         , T0.TO_SITE_SOLDTO_CODE
                         , T0.TO_SITE_SHIPTO_CODE
                         , T0.SOLDTO_DESCRIPTION
                         , T0.SHIPTO_DESCRIPTION
                         , T0.BOD_ID
                         , T0.INCOTERMS
                         , T0.TRANSPORT_MODE
                         , T0.LT_DAY
                         , T0.ETD
                         , T0.ETA
                         , T0.EXPECTED_SHIPPING_DATE
                         , T0.CONFIRM_ID
                         , T0.UPDATED_BY
                         , T0.UPDATED_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
                         , '-'                               AS NEW_ROUTE_ID
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
                         , '-'                               AS NEW_CUSTOMER_LT
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
                         , '-'                               AS NEW_LT_DAY
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , T0.END_CUSTOMER                   AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , T0.CHANGE_REQ_NO                  AS CHANGE_REQ_NO
                         , T0.MODEL_USER                     AS MODEL_USER
                         , T0.MTK_OWNER                      AS MTK_OWNER
                         , T0.REQUESTOR                      AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                         , '-'                               AS ATTRIBUTE10
                         , T0.ATTRIBUTE3
                         , T0.ATTRIBUTE6
                      FROM (
                            SELECT TT0.DIVISION_ID
                                 , TT0.ERP_SO_NO
                                 , TT0.SHIPMENT_STATUS
                                 , TT0.ITEM_ID
                                 , TT0.NICK_NAME
                                 , TT0.ORIGIN_FROM_DIVISION_ID
                                 , TT0.ORIGIN_TO_DIVISION_ID
                                 , TT0.FROM_SITE
                                 , TT0.FROM_SITE_DESCRIPTION
                                 , TT0.TO_SITE
                                 , TT0.TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , TT0.PROJECT_NAME
                                 , TT0.REQUESTOR
                                 , TT0.SHIPMENT_CONFIRM_QTY
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT0.INCOTERMS
                                 , TT0.TRANSPORT_MODE
                                 , TT0.TO_SITE_SOLDTO_CODE
                                 , TT0.TO_SITE_SHIPTO_CODE
                                 , TT0.SOLDTO_DESCRIPTION
                                 , TT0.SHIPTO_DESCRIPTION
                                 , TT0.REMARKS2
                                 , TT0.REMARKS
                                 , TT0.CHANGE_REQ_NO
                                 , TT0.REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.ETD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , CASE WHEN REGEXP_LIKE(TT0.ETA, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETA, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                                 , TT0.EXPECTED_SHIPPING_DATE
                                 , TT0.LT_DAY                AS LT_DAY
                                 , TT0.UPDATED_BY            AS UPDATED_BY
                                 , TT0.UPDATED_DATE          AS UPDATED_DATE
                                 , TT0.CONFIRM_ID            AS CONFIRM_ID
                                 , TT0.FCST_TYPE
                                 , TT0.END_CUSTOMER
                                 , TT0.MTK_OWNER
                                 , TT0.MODEL_USER
                                   /* 2021/10/05 SHINMYUNGSU 열람 항목추가 */
                                 , '-'                       AS ATTRIBUTE3
                                 , '-'                       AS ATTRIBUTE6
                              FROM SSP_ANL_SHIP_PLAN_ALL TT0
                                 , SSP_MST_MODEL_USER MU
                             WHERE MU.DIVISION_ID(+) = TT0.ORIGIN_FROM_DIVISION_ID
                               AND MU.FROM_SITE(+)   = TT0.FROM_SITE
                               AND MU.ITEM_ID(+)     = TT0.ITEM_ID
                               AND MU.VALID_YN(+)    = 'Y'
                               AND TT0.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND TT0.DIVISION_ID         = P_DIVISION_ID
                               AND TT0.SHIPMENT_CONFIRM_QTY > 0
                               AND TT0.OPERATION_GROUP     <> 'E'
                               AND TT0.YYYYMMDD >= P_FROM_YYYYMMDD
                               AND TT0.YYYYMMDD <= P_TO_YYYYMMDD
                               AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                                     OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT0.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                     OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                                   OR TT0.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                     OR TT0.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                     OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                               AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                            FROM TB_FX_USER SA
--                                                           WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                              OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                            FROM SCM_ADM_USER_M SA
                                                           WHERE SA.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                              OR SA.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     /* 2026.09.30 AJS 수정 (END) */
                               AND (P_SEARCH_YN != 'Y'
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                             UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN = 'Y'
                                                               AND DELEGATEE_ID = P_USER_ID
                                                             GROUP BY USER_ID)
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                           ) T0
                   ) AA
             ORDER BY AA.DIVISION_ID
                 , AA.SHIPMENT_STATUS
                 , AA.SHIPMENT_DATE
                 , AA.ITEM_ID
                 , AA.ERP_SO_NO DESC
                 , AA.FROM_SITE
                 , AA.TO_SITE
                 , AA.PROJECT_CODE
                 , AA.FCST_TYPE;

        END IF;

    END P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL;


    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_PSI
       AS-IS SSP0015_SAVE_SHIPMENT_PSI
       ※ '^' 로 이어 붙인 여러 행을 SCM_ARR_SPL_VAL 로 잘라 한 행씩 처리한다(AS-IS 동일).
       ※ 저장 시작에 SAVEPOINT 를 두어 중간 오류 시 앞 행 저장분까지 되돌린다.
       ※ AS-IS 의 @debug_mode PRINT 구간은 옮기지 않는다.
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_PSI
    (
        P_ACTIVE_FLAG           IN  VARCHAR2,
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_YYYYMMDD              IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_MEASURE               IN  VARCHAR2,
        P_QTY                   IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_PSI
         * Description  : Shipment PSI 수량 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := '[SSP0015_SAVE_SHIPMENT_PSI]';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;

        V_DELIMITER             VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT          PLS_INTEGER := 0;
        V_MST_LOOP_CNT          PLS_INTEGER := 0;

        V_ACTIVE_FLAG           VARCHAR2(4000 CHAR);
        V_DIVISION_ID           VARCHAR2(4000 CHAR);
        V_FROM_SITE             VARCHAR2(4000 CHAR);
        V_ITEM_ID               VARCHAR2(4000 CHAR);
        V_PLAN_START_YYYYMMDD   VARCHAR2(4000 CHAR);
        V_YYYYMMDD              VARCHAR2(4000 CHAR);
        V_PLAN_TYPE             VARCHAR2(4000 CHAR);
        V_SEQ                   VARCHAR2(4000 CHAR);
        V_MEASURE               VARCHAR2(4000 CHAR);
        V_QTY                   VARCHAR2(4000 CHAR);
        V_LAST_UPDATED_BY       VARCHAR2(150 CHAR) := P_USER_ID;
        V_LAST_UPDATE_DATE      DATE := SYSDATE;

        V_COMMENTS_CNT          PLS_INTEGER := 0;
        V_OLD_QTY               NUMBER;
        V_ERR_CODE              NUMBER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_PSI;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 프로시저 LOOP 길이를 판단 */
        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG         := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,         V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID         := SCM_ARR_SPL_VAL(P_DIVISION_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE           := SCM_ARR_SPL_VAL(P_FROM_SITE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID             := SCM_ARR_SPL_VAL(P_ITEM_ID,             V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_START_YYYYMMDD := SCM_ARR_SPL_VAL(P_PLAN_START_YYYYMMDD, V_DELIMITER, V_MST_LOOP_CNT);
            V_YYYYMMDD            := SCM_ARR_SPL_VAL(P_YYYYMMDD,            V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_TYPE           := SCM_ARR_SPL_VAL(P_PLAN_TYPE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_SEQ                 := SCM_ARR_SPL_VAL(P_SEQ,                 V_DELIMITER, V_MST_LOOP_CNT);
            V_MEASURE             := SCM_ARR_SPL_VAL(P_MEASURE,             V_DELIMITER, V_MST_LOOP_CNT);
            V_QTY                 := SCM_ARR_SPL_VAL(P_QTY,                 V_DELIMITER, V_MST_LOOP_CNT);

            /* 데이터 저장 - 수정 */
            IF V_ACTIVE_FLAG = 'M' OR V_ACTIVE_FLAG = 'I' THEN

                V_OLD_QTY := NULL;

                BEGIN
                    SELECT QTY
                      INTO V_OLD_QTY
                      FROM SSP_ANL_SHIP_PLAN_40
                     WHERE DIVISION_ID         = V_DIVISION_ID
                       AND FROM_SITE           = V_FROM_SITE
                       AND ITEM_ID             = V_ITEM_ID
                       AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND YYYYMMDD            = V_YYYYMMDD
                       AND PLAN_TYPE           = V_PLAN_TYPE
                       AND SEQ                 = V_SEQ
                       AND MEASURE             = V_MEASURE
                       AND ROWNUM              = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_OLD_QTY := NULL;
                END;

                /*//COMMENTS 변경 내용 저장 Start*/
                SELECT COUNT(*)
                  INTO V_COMMENTS_CNT
                  FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
                 WHERE 1 = 1
                   AND DIVISION_ID = V_DIVISION_ID
                   AND FROM_SITE   = V_FROM_SITE
                   AND ITEM_ID     = V_ITEM_ID
                   AND YYYYMMDD    = V_YYYYMMDD;

                IF V_COMMENTS_CNT > 0 THEN
                    /*//COMMENTS UPDATE*/
                    UPDATE SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
                       SET COMMENTS         = NULL
                         , USER_ADD_QTY     = V_QTY
                         , LAST_UPDATED_BY  = P_USER_ID
                         , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                         , ATTRIBUTE1       = V_OLD_QTY
                     WHERE 1 = 1
                       AND DIVISION_ID = V_DIVISION_ID
                       AND FROM_SITE   = V_FROM_SITE
                       AND ITEM_ID     = V_ITEM_ID
                       AND YYYYMMDD    = V_YYYYMMDD;
                ELSE
                    /*//COMMENTS INSERT*/
                    INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
                           (DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
                          , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                          , ATTRIBUTE1)
                    VALUES (V_DIVISION_ID, V_FROM_SITE, V_ITEM_ID, V_YYYYMMDD, V_QTY
                          , NULL, V_LAST_UPDATE_DATE, P_USER_ID, V_LAST_UPDATE_DATE
                          , V_OLD_QTY);
                END IF;

                /*//HISTORY INSERT*/
                INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_CMT_H
                       (HISTORY_SEQ
                      , DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
                      , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                      , HISTORY_CREATION_DATE, ATTRIBUTE1)
                SELECT SEQ1_SSP_ANL_SHIP_PLAN_40_WH_IN_CMT_H.NEXTVAL
                      , DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
                      , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                      , SYSDATE, ATTRIBUTE1
                  FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
                 WHERE 1 = 1
                   AND DIVISION_ID = V_DIVISION_ID
                   AND FROM_SITE   = V_FROM_SITE
                   AND ITEM_ID     = V_ITEM_ID
                   AND YYYYMMDD    = V_YYYYMMDD;
                /*//COMMENTS 내용 저장 End*/

                UPDATE SSP_ANL_SHIP_PLAN_40
                   SET QTY              = V_QTY
                     , LAST_UPDATED_BY  = V_LAST_UPDATED_BY
                     , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                 WHERE DIVISION_ID         = V_DIVISION_ID
                   AND FROM_SITE           = V_FROM_SITE
                   AND ITEM_ID             = V_ITEM_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND YYYYMMDD            = V_YYYYMMDD
                   AND PLAN_TYPE           = V_PLAN_TYPE
                   AND SEQ                 = V_SEQ
                   AND MEASURE             = V_MEASURE;

                /* EXEC PR_SSP_ANL_SHIP_UPDATE_BOH_VAL_40 - AS-IS 주석 처리 상태 유지 */

                INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_H
                       (HISTORY_SEQ
                      , DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                      , ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                      , YYYYMMDD, BOD_ID, QTY, ROUTE_ID
                      , INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                      , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE
                      , ETA_DATE, CONFIRM_FLAG, CONFIRM_ID, CREATED_BY
                      , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ELECTRODE_YN
                      , ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, HISTORY_CREATION_DATE)
                SELECT SEQ1_SSP_ANL_SHIP_PLAN_40_WH_IN_H.NEXTVAL
                      , DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                      , ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                      , YYYYMMDD, BOD_ID, QTY, ROUTE_ID
                      , INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                      , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE
                      , ETA_DATE, CONFIRM_FLAG, CONFIRM_ID, CREATED_BY
                      , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ELECTRODE_YN
                      , ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, SYSDATE
                  FROM SSP_ANL_SHIP_PLAN_40
                 WHERE DIVISION_ID         = V_DIVISION_ID
                   AND FROM_SITE           = V_FROM_SITE
                   AND ITEM_ID             = V_ITEM_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND YYYYMMDD            = V_YYYYMMDD
                   AND PLAN_TYPE           = V_PLAN_TYPE
                   AND SEQ                 = V_SEQ
                   AND MEASURE             = V_MEASURE;

            END IF;

        END LOOP;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE, V_MST_LOOP_CNT AS RESULT_CNT FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_PSI;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE, 0 AS RESULT_CNT FROM DUAL;
            OPEN O_RC2 FOR SELECT V_ERR_CODE AS ERR_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_SAVE_SHIPMENT_PSI;


    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_PSI_COMMENTS
       AS-IS SSP0015_SAVE_SHIPMENT_PSI_COMMENTS
       ※ 오류 시 되돌리기를 커서 OPEN 앞에 둔다.
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_PSI_COMMENTS
    (
        P_CHANGE_FLAG           IN  VARCHAR2,
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_YYYYMMDD              IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_MEASURE               IN  VARCHAR2,
        P_QTY                   IN  VARCHAR2,
        P_PRODQTY               IN  VARCHAR2,
        P_COMMENTS              IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_PSI_COMMENTS
         * Description  : Shipment PSI Comments 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := '[SSP0015_SAVE_SHIPMENT_PSI_COMMENTS]';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;

        V_LAST_UPDATE_DATE      DATE := SYSDATE;
        V_COMMENTS_CNT          PLS_INTEGER := 0;
        V_OLD_QTY               NUMBER;
        V_ERR_CODE              NUMBER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_PSI_CMT;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        IF P_CHANGE_FLAG = 'Y' THEN

            V_OLD_QTY := NULL;

            BEGIN
                SELECT QTY
                  INTO V_OLD_QTY
                  FROM SSP_ANL_SHIP_PLAN_40
                 WHERE DIVISION_ID         = P_DIVISION_ID
                   AND FROM_SITE           = P_FROM_SITE
                   AND ITEM_ID             = P_ITEM_ID
                   AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND YYYYMMDD            = P_YYYYMMDD
                   AND PLAN_TYPE           = P_PLAN_TYPE
                   AND SEQ                 = P_SEQ
                   AND MEASURE             = P_MEASURE
                   AND ROWNUM              = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_OLD_QTY := NULL;
            END;

            /*//PSI 변경 내용 저장 Start*/
            /* [C20200506-000210] USER_ADD_QTY 추가 - Change Qty + Prod Qty로 변경. Change Qty 음수 가능 */
            UPDATE SSP_ANL_SHIP_PLAN_40
               SET QTY              = CEIL(TO_NUMBER(P_QTY)) + CEIL(TO_NUMBER(P_PRODQTY))
                 , LAST_UPDATED_BY  = P_USER_ID
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
             WHERE 1 = 1
               AND DIVISION_ID         = P_DIVISION_ID
               AND FROM_SITE           = P_FROM_SITE
               AND ITEM_ID             = P_ITEM_ID
               AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND YYYYMMDD            = P_YYYYMMDD
               AND PLAN_TYPE           = P_PLAN_TYPE
               AND SEQ                 = P_SEQ
               AND MEASURE             = P_MEASURE;

            /* [C20200506-000210] USER_ADD_QTY 추가 */
            INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_H
                   (HISTORY_SEQ
                  , DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                  , ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, USER_ADD_QTY, BOD_ID, QTY, ROUTE_ID
                  , INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE
                  , ETA_DATE, CONFIRM_FLAG, CONFIRM_ID, CREATED_BY
                  , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ELECTRODE_YN
                  , ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, HISTORY_CREATION_DATE)
            SELECT SEQ1_SSP_ANL_SHIP_PLAN_40_WH_IN_H.NEXTVAL
                  , DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                  , ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, P_QTY, BOD_ID, QTY, ROUTE_ID
                  , INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE
                  , ETA_DATE, CONFIRM_FLAG, CONFIRM_ID, CREATED_BY
                  , CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ELECTRODE_YN
                  , ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, SYSDATE
              FROM SSP_ANL_SHIP_PLAN_40
             WHERE 1 = 1
               AND DIVISION_ID         = P_DIVISION_ID
               AND FROM_SITE           = P_FROM_SITE
               AND ITEM_ID             = P_ITEM_ID
               AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND YYYYMMDD            = P_YYYYMMDD
               AND PLAN_TYPE           = P_PLAN_TYPE
               AND SEQ                 = P_SEQ
               AND MEASURE             = P_MEASURE;
            /*//PSI 변경 내용 저장 End*/

        END IF;

        SELECT COUNT(*)
          INTO V_COMMENTS_CNT
          FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
         WHERE 1 = 1
           AND DIVISION_ID = P_DIVISION_ID
           AND FROM_SITE   = P_FROM_SITE
           AND ITEM_ID     = P_ITEM_ID
           AND YYYYMMDD    = P_YYYYMMDD;

        /*//COMMENTS 변경 내용 저장 Start*/
        IF V_COMMENTS_CNT > 0 THEN
            /*//COMMENTS UPDATE*/
            UPDATE SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
               SET COMMENTS         = P_COMMENTS
                 , USER_ADD_QTY     = P_QTY
                 , LAST_UPDATED_BY  = P_USER_ID
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                 , ATTRIBUTE1       = V_OLD_QTY
             WHERE 1 = 1
               AND DIVISION_ID = P_DIVISION_ID
               AND FROM_SITE   = P_FROM_SITE
               AND ITEM_ID     = P_ITEM_ID
               AND YYYYMMDD    = P_YYYYMMDD;
        ELSE
            /*//COMMENTS INSERT*/
            INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
                   (DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
                  , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                  , ATTRIBUTE1)
            VALUES (P_DIVISION_ID, P_FROM_SITE, P_ITEM_ID, P_YYYYMMDD, P_QTY
                  , P_COMMENTS, V_LAST_UPDATE_DATE, P_USER_ID, V_LAST_UPDATE_DATE
                  , V_OLD_QTY);
        END IF;

        /*//HISTORY INSERT*/
        INSERT INTO SSP_ANL_SHIP_PLAN_40_WH_IN_CMT_H
               (HISTORY_SEQ
              , DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
              , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
              , HISTORY_CREATION_DATE, ATTRIBUTE1)
        SELECT SEQ1_SSP_ANL_SHIP_PLAN_40_WH_IN_CMT_H.NEXTVAL
              , DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, USER_ADD_QTY
              , COMMENTS, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
              , SYSDATE, ATTRIBUTE1
          FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT
         WHERE 1 = 1
           AND DIVISION_ID = P_DIVISION_ID
           AND FROM_SITE   = P_FROM_SITE
           AND ITEM_ID     = P_ITEM_ID
           AND YYYYMMDD    = P_YYYYMMDD;
        /*//COMMENTS 내용 저장 End*/

        COMMIT;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_PSI_CMT;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE FROM DUAL;
            OPEN O_RC2 FOR SELECT V_ERR_CODE AS ERR_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_SAVE_SHIPMENT_PSI_COMMENTS;


    /* ============================================================
       P_SSP0015_SAVE_BLOCK_STOCK_DATA
       AS-IS SSP0015_SAVE_BLOCK_STOCK_DATA
       ※ AS-IS 의 「단일 ROW 일때」 ELSE 갈래는 WHILE 안의 IF @mst_loop_cnt > 0 에 달려 있어
          도달할 수 없다(루프 안에서는 항상 1 이상). 옮기지 않는다.
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_BLOCK_STOCK_DATA
    (
        P_ACTIVE_FLAG           IN  VARCHAR2,
        P_HOLD_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_HOLD_YYYYMMDD         IN  VARCHAR2,
        P_RELEASE_YYYYMMDD      IN  VARCHAR2,
        P_HOLD_QTY              IN  VARCHAR2,
        P_REMARKS               IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_BLOCK_STOCK_DATA
         * Description  : Block Stock 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SSP0015_SAVE_BLOCK STOCK_DATA';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;

        V_DELIMITER             VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT          PLS_INTEGER := 0;
        V_MST_LOOP_CNT          PLS_INTEGER := 0;

        V_ACTIVE_FLAG           VARCHAR2(4000 CHAR);
        V_HOLD_ID               VARCHAR2(4000 CHAR);
        V_PLAN_START_YYYYMMDD   VARCHAR2(4000 CHAR);
        V_PLAN_TYPE             VARCHAR2(4000 CHAR);
        V_SEQ                   VARCHAR2(4000 CHAR);
        V_DIVISION_ID           VARCHAR2(4000 CHAR);
        V_FROM_SITE             VARCHAR2(4000 CHAR);
        V_ITEM_ID               VARCHAR2(4000 CHAR);
        V_HOLD_YYYYMMDD         VARCHAR2(4000 CHAR);
        V_RELEASE_YYYYMMDD      VARCHAR2(4000 CHAR);
        V_HOLD_QTY              VARCHAR2(4000 CHAR);
        V_REMARKS               VARCHAR2(4000 CHAR);
        V_USER_ID               VARCHAR2(4000 CHAR);
        V_EXISTS                PLS_INTEGER;
        V_ERR_CODE              NUMBER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_BLOCK;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        /* 프로시저 LOOP 길이를 판단 */
        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG         := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,         V_DELIMITER, V_MST_LOOP_CNT);
            V_HOLD_ID             := SCM_ARR_SPL_VAL(P_HOLD_ID,             V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_START_YYYYMMDD := SCM_ARR_SPL_VAL(P_PLAN_START_YYYYMMDD, V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_TYPE           := SCM_ARR_SPL_VAL(P_PLAN_TYPE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_SEQ                 := SCM_ARR_SPL_VAL(P_SEQ,                 V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID         := SCM_ARR_SPL_VAL(P_DIVISION_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE           := SCM_ARR_SPL_VAL(P_FROM_SITE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID             := SCM_ARR_SPL_VAL(P_ITEM_ID,             V_DELIMITER, V_MST_LOOP_CNT);
            V_HOLD_YYYYMMDD       := SCM_ARR_SPL_VAL(P_HOLD_YYYYMMDD,       V_DELIMITER, V_MST_LOOP_CNT);
            V_RELEASE_YYYYMMDD    := SCM_ARR_SPL_VAL(P_RELEASE_YYYYMMDD,    V_DELIMITER, V_MST_LOOP_CNT);
            V_HOLD_YYYYMMDD    := CASE WHEN REGEXP_LIKE(V_HOLD_YYYYMMDD, '^[0-9]{4}[-/.][0-9]{2}[-/.][0-9]{2}')
                                  THEN SUBSTR(REPLACE(REPLACE(REPLACE(V_HOLD_YYYYMMDD, '-'), '/'), '.'), 1, 8)
                                  ELSE V_HOLD_YYYYMMDD END;   -- 2026.09.22 AJS
            V_RELEASE_YYYYMMDD := CASE WHEN REGEXP_LIKE(V_RELEASE_YYYYMMDD, '^[0-9]{4}[-/.][0-9]{2}[-/.][0-9]{2}')
                                  THEN SUBSTR(REPLACE(REPLACE(REPLACE(V_RELEASE_YYYYMMDD, '-'), '/'), '.'), 1, 8)
                                  ELSE V_RELEASE_YYYYMMDD END;   -- 2026.09.22 AJS
            V_HOLD_QTY            := SCM_ARR_SPL_VAL(P_HOLD_QTY,            V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS             := SCM_ARR_SPL_VAL(P_REMARKS,             V_DELIMITER, V_MST_LOOP_CNT);
            V_USER_ID             := SCM_ARR_SPL_VAL(P_USER_ID,             V_DELIMITER, V_MST_LOOP_CNT);

            /* SSP_ANL_HOLD_STOCK SAVE LOGIC */
            V_EXISTS := 0;

            BEGIN
                SELECT 1
                  INTO V_EXISTS
                  FROM SSP_ANL_HOLD_STOCK
                 WHERE HOLD_ID             = V_HOLD_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND PLAN_TYPE           = V_PLAN_TYPE
                   AND SEQ                 = V_SEQ
                   AND ROWNUM              = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_EXISTS := 0;
            END;

            IF V_EXISTS = 1 THEN

                UPDATE SSP_ANL_HOLD_STOCK
                   SET RELEASE_YYYYMMDD  = V_RELEASE_YYYYMMDD
                     , HOLD_QTY          = V_HOLD_QTY
                     , REMARKS           = V_REMARKS
                     , LAST_UPDATED_BY   = V_USER_ID
                     , LAST_UPDATE_DATE  = SYSDATE
                 WHERE HOLD_ID             = V_HOLD_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND PLAN_TYPE           = V_PLAN_TYPE
                   AND SEQ                 = V_SEQ;

            ELSE

                INSERT INTO SSP_ANL_HOLD_STOCK
                       (HOLD_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , DIVISION_ID
                      , FROM_SITE
                      , ITEM_ID
                      , HOLD_YYYYMMDD
                      , RELEASE_YYYYMMDD
                      , HOLD_QTY
                      , REMARKS
                      , ORIGIN_FROM_DIVISION_ID
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE)
                VALUES ('H' || TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('0000' || TO_CHAR(SEQ1_SSP_ANL_HOLD_ID.NEXTVAL), -6)
                      , V_PLAN_START_YYYYMMDD
                      , V_PLAN_TYPE
                      , V_SEQ
                      , V_DIVISION_ID
                      , V_FROM_SITE
                      , V_ITEM_ID
                      , V_HOLD_YYYYMMDD
                      , V_RELEASE_YYYYMMDD
                      , V_HOLD_QTY
                      , V_REMARKS
                      , V_DIVISION_ID   /* origin_from_division_id */
                      , V_USER_ID
                      , SYSDATE
                      , V_USER_ID
                      , SYSDATE);

            END IF;

        END LOOP;

        /* EXEC PR_SSP_ANL_SHIP_UPDATE_BOH_VAL_40 - AS-IS 주석 처리 상태 유지 */

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE, V_MAX_LOOP_CNT AS RESULT_CNT FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_BLOCK;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE, 0 AS RESULT_CNT FROM DUAL;
            OPEN O_RC2 FOR SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_SAVE_BLOCK_STOCK_DATA;


    /* ============================================================
       P_SSP0015_SAVE_MES_STOCK
       AS-IS SSP0015_SAVE_MES_STOCK
       ※ #TMP_SSP_ANL_MES_FCS_STOCK_40_C_TEMP -> GT_SSP0015_MES_STOCK_UPD
       ※ AS-IS 의 MERGE 2벌은 WHEN MATCHED THEN UPDATE 뿐이라
          상관 UPDATE ... WHERE EXISTS 로 옮겼다(온라인 SQL MERGE 금지 · ORA-01779 회피).
       ※ 두 번째 갱신의 ITEM_ID 조건은 AS-IS 가 루프 마지막 값 하나만 쓴다.
          결과 동일성을 위해 원형을 유지한다(V_ITEM_ID 는 루프 종료 후 마지막 값).
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_MES_STOCK
    (
        P_ACTIVE_FLAG              IN  VARCHAR2,
        P_DIVISION_ID              IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD      IN  VARCHAR2,
        P_PLAN_TYPE                IN  VARCHAR2,
        P_SEQ                      IN  VARCHAR2,
        P_FROM_SITE                IN  VARCHAR2,
        P_ITEM_ID                  IN  VARCHAR2,
        P_LOT_ID                   IN  VARCHAR2,
        P_USER_MOD_RELEASE_DATE    IN  VARCHAR2,
        P_REMARKS                  IN  VARCHAR2,
        P_USER_ID                  IN  VARCHAR2,
        O_RC1                      OUT SYS_REFCURSOR,
        O_RC2                      OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_MES_STOCK
         * Description  : MES Stock 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'SSP0015_SAVE_MES_STOCK';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;

        V_DELIMITER             VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT          PLS_INTEGER := 0;
        V_MST_LOOP_CNT          PLS_INTEGER := 0;

        V_ACTIVE_FLAG           VARCHAR2(4000 CHAR);
        V_DIVISION_ID           VARCHAR2(4000 CHAR);
        V_PLAN_START_YYYYMMDD   VARCHAR2(4000 CHAR);
        V_PLAN_TYPE             VARCHAR2(4000 CHAR);
        V_SEQ                   VARCHAR2(4000 CHAR);
        V_FROM_SITE             VARCHAR2(4000 CHAR);
        V_ITEM_ID               VARCHAR2(4000 CHAR);
        V_LOT_ID                VARCHAR2(4000 CHAR);
        V_USER_MOD_RELEASE_DATE VARCHAR2(4000 CHAR);
        V_REMARKS               VARCHAR2(4000 CHAR);
        V_USER_ID               VARCHAR2(4000 CHAR);
        V_ERR_CODE              NUMBER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_MES;

        /* GTT 초기화 - TRUNCATE 금지(암묵적 커밋으로 롤백이 깨진다) */
        DELETE FROM GT_SSP0015_MES_STOCK_UPD;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        /* 프로시저 LOOP 길이를 판단 */
        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG           := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,           V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID           := SCM_ARR_SPL_VAL(P_DIVISION_ID,           V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_START_YYYYMMDD   := SCM_ARR_SPL_VAL(P_PLAN_START_YYYYMMDD,   V_DELIMITER, V_MST_LOOP_CNT);
            V_PLAN_TYPE             := SCM_ARR_SPL_VAL(P_PLAN_TYPE,             V_DELIMITER, V_MST_LOOP_CNT);
            V_SEQ                   := SCM_ARR_SPL_VAL(P_SEQ,                   V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE             := SCM_ARR_SPL_VAL(P_FROM_SITE,             V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID               := SCM_ARR_SPL_VAL(P_ITEM_ID,               V_DELIMITER, V_MST_LOOP_CNT);
            V_LOT_ID                := SCM_ARR_SPL_VAL(P_LOT_ID,                V_DELIMITER, V_MST_LOOP_CNT);
            V_USER_MOD_RELEASE_DATE := SCM_ARR_SPL_VAL(P_USER_MOD_RELEASE_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS               := SCM_ARR_SPL_VAL(P_REMARKS,               V_DELIMITER, V_MST_LOOP_CNT);
            V_USER_ID               := SCM_ARR_SPL_VAL(P_USER_ID,               V_DELIMITER, V_MST_LOOP_CNT);

            /* UPDATE 대상 TEMP 테이블 만들기 */
            INSERT INTO GT_SSP0015_MES_STOCK_UPD
                   (ACTIVE_FLAG, DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ
                  , FROM_SITE, ITEM_ID, LOT_ID, USER_MOD_RELEASE_DATE, REMARKS, USER_ID)
            VALUES (V_ACTIVE_FLAG, V_DIVISION_ID, V_PLAN_START_YYYYMMDD, V_PLAN_TYPE, V_SEQ
                  , V_FROM_SITE, V_ITEM_ID, V_LOT_ID, REPLACE(V_USER_MOD_RELEASE_DATE, '-', ''), V_REMARKS, V_USER_ID);

        END LOOP;

        /* 1) SSP_ANL_MES_FCS_STOCK_40_C 갱신 (AS-IS MERGE 1번째) */
        UPDATE SSP_ANL_MES_FCS_STOCK_40_C A
           SET (A.USER_MOD_RELEASE_DATE, A.REMARKS, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE)
               = (SELECT MAX(B.USER_MOD_RELEASE_DATE), MAX(B.REMARKS), MAX(B.USER_ID), SYSDATE
                    FROM GT_SSP0015_MES_STOCK_UPD B
                   WHERE B.DIVISION_ID         = A.DIVISION_ID
                     AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                     AND B.PLAN_TYPE           = A.PLAN_TYPE
                     AND B.SEQ                 = TO_CHAR(A.SEQ)
                     AND B.ITEM_ID             = A.ITEM_ID
                     AND B.LOT_ID              = A.LOT_ID
                     AND B.FROM_SITE           = A.FROM_SITE)
         WHERE A.CHANGE_STATUS <> 'D'
           AND EXISTS (SELECT 1
                         FROM GT_SSP0015_MES_STOCK_UPD B
                        WHERE B.DIVISION_ID         = A.DIVISION_ID
                          AND B.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
                          AND B.PLAN_TYPE           = A.PLAN_TYPE
                          AND B.SEQ                 = TO_CHAR(A.SEQ)
                          AND B.ITEM_ID             = A.ITEM_ID
                          AND B.LOT_ID              = A.LOT_ID
                          AND B.FROM_SITE           = A.FROM_SITE);

        /* SSP_ANL_MES_FCS_STOCK_40_C 테이블 UPDATE 완료 후 초기화 */
        V_MST_LOOP_CNT := 0;

        /* 2) SSP_ANL_SHIP_PLAN_40 의 MES_FCS_RELEASE 수량 재집계 (AS-IS MERGE 2번째) */
        UPDATE SSP_ANL_SHIP_PLAN_40 A
           SET (A.QTY, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE)
               = (SELECT NVL(SUM(B.LOT_QTY_TOT), 0), MAX(C.USER_ID), SYSDATE
                    FROM GT_SSP0015_MES_STOCK_UPD C
                       , SSP_ANL_MES_FCS_STOCK_40_C B
                   WHERE A.DIVISION_ID         = C.DIVISION_ID
                     AND A.PLAN_START_YYYYMMDD = C.PLAN_START_YYYYMMDD
                     AND A.PLAN_TYPE           = C.PLAN_TYPE
                     AND TO_CHAR(A.SEQ)        = C.SEQ
                     AND A.FROM_SITE           = C.FROM_SITE
                     AND A.ITEM_ID             = C.ITEM_ID
                     AND B.DIVISION_ID(+)         = A.DIVISION_ID
                     AND B.PLAN_START_YYYYMMDD(+) = A.PLAN_START_YYYYMMDD
                     AND B.PLAN_TYPE(+)           = A.PLAN_TYPE
                     AND B.SEQ(+)                 = A.SEQ
                     AND B.LOT_ID(+)              = C.LOT_ID
                     AND B.FROM_SITE(+)           = A.FROM_SITE
                     AND B.ITEM_ID(+)             = A.ITEM_ID
                     AND A.YYYYMMDD = (CASE WHEN NVL(B.USER_MOD_RELEASE_DATE, '-') <> '29991231'
                                             AND NVL(B.USER_MOD_RELEASE_DATE, '-') <> '-'
                                            THEN B.USER_MOD_RELEASE_DATE
                                            WHEN NVL(B.USER_MOD_RELEASE_DATE, '-') = '29991231'
                                             AND NVL(B.QMS_HOLD_RELEASE, '-') > NVL(B.MES_HOLD_RELEASE, '-')
                                            THEN B.QMS_HOLD_RELEASE
                                            ELSE B.MES_HOLD_RELEASE END))
         WHERE A.MEASURE     = 'MES_FCS_RELEASE'
           AND A.DIVISION_ID = '40'
           AND A.PLAN_TYPE   = 'SP'
           /* AS-IS 원형 유지 : 루프 마지막 ITEM_ID 값 하나만 조건으로 쓴다 */
           AND (V_ITEM_ID IS NOT NULL AND V_ITEM_ID <> '-')
           AND A.ITEM_ID = V_ITEM_ID
           AND EXISTS (SELECT 1
                         FROM GT_SSP0015_MES_STOCK_UPD C
                        WHERE A.DIVISION_ID         = C.DIVISION_ID
                          AND A.PLAN_START_YYYYMMDD = C.PLAN_START_YYYYMMDD
                          AND A.PLAN_TYPE           = C.PLAN_TYPE
                          AND TO_CHAR(A.SEQ)        = C.SEQ
                          AND A.FROM_SITE           = C.FROM_SITE
                          AND A.ITEM_ID             = C.ITEM_ID);

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, NULL, NULL, NULL, NULL);

        DELETE FROM GT_SSP0015_MES_STOCK_UPD;

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE, V_MAX_LOOP_CNT AS RESULT_CNT FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_MES;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE, 0 AS RESULT_CNT FROM DUAL;
            OPEN O_RC2 FOR SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_SAVE_MES_STOCK;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
       AS-IS SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
       ※ 과거 버전 조회라 계산하지 않고 SSP_ANL_SHIP_PLAN_P 스냅샷을 그대로 읽는다.
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
          OPEN 커서 FOR 문자열 로 두고 조립 문자열은 CLOB 로 둔다.
          (CNS 전환가이드 8항 Dynamic SQL 금지의 예외 - 2항 결과 동일성을 우선한 자리)
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
         * Description  : Shipment PSI (Packer) - 과거 버전
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020/11/10   KIMYONGHO      SSP0015_GET_SHIPMENT_PSI 복사 신규추가
         * 2022/02/21   SMS            SHIP_FROZEN 추가 (scm_mst_site(ship_frozen))
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_CNT_USR_MEASURE   PLS_INTEGER := 0;
        V_CUTOFF_DATE       VARCHAR2(8 CHAR);
        V_MQRY_SUM          CLOB := EMPTY_CLOB();
        V_MEXEC             CLOB;
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_PK_ROWDATA;
        DELETE FROM GT_SSP0015_PK_RESULT;
        DELETE FROM GT_SSP0015_PK_RESULT_PIVOT;
        DELETE FROM GT_SSP0015_PK_WH_STOCK;
        DELETE FROM GT_SSP0015_PK_ERP_STOCK;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        V_CUTOFF_DATE := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');

        /* //4. WH_STOCK - SCS 재고 */
        INSERT INTO GT_SSP0015_PK_WH_STOCK
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , 'WH_STOCK'
             , A.STOCK_DATE
             , SUM(NVL(A.STOCK_QTY, 0))
          FROM SCM_DNM_SCS_STOCK A
         WHERE 1 = 1
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.CUTOFF_DATE = V_CUTOFF_DATE
           AND A.CELL_PACK   = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.STOCK_DATE;

        /* //ERP 재고 데이터 */
        INSERT INTO GT_SSP0015_PK_ERP_STOCK
               (DIVISION_ID, PLANT_ID, ITEM_ID, BOH_TYPE, YYYYMMDD, QTY)
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.ITEM_ID
             , 'ERP'
             , IA.CUTOFF_DATE
             , SUM(IA.SCM_QTY)
          FROM (
                SELECT DISTINCT
                       A.DIVISION_ID
                     , A.COMPANY_ID
                     , A.ITEM_ID
                     , A.SCM_QTY
                     , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
                     , A.PLANT_ID
                     , A.STOCK_TYPE
                  FROM SCM_DNM_STOCK_V A
                 WHERE 1 = 1
                   AND A.DIVISION_ID = '40'
                   AND A.COMPANY_ID  = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER_PAST', 'ESOC')   /* C100 */
                   AND A.CUTOFF_DATE = TO_DATE(TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), 'YYYYMMDD')
                   AND A.ORG_CUTOFF_DATE = TO_DATE(TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), 'YYYYMMDD') + 1 /* AJS 20261007 속도 : 원장 마감일 조건(뷰 마감일 + 1 과 같은 값) */
                   AND A.PLANT_ID    = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER_PAST', 'A010')   /* A010 */
                   AND A.STOCK_TYPE  = 'INVENTORY'
               ) IA
         WHERE IA.STOCK_TYPE = 'INVENTORY'
         GROUP BY IA.DIVISION_ID
             , IA.COMPANY_ID
             , IA.ITEM_ID
             , IA.CUTOFF_DATE
             , IA.PLANT_ID
             , IA.STOCK_TYPE;

        /* //TMP_ROWDATA - 과거 버전은 SSP_ANL_SHIP_PLAN_P 스냅샷을 그대로 읽는다 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.MEASURE
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_PLAN_P A
         WHERE A.DIVISION_ID         = P_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND A.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE')   /* PACK FP = PROD_PLAN */
         GROUP BY A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.MEASURE
             , A.YYYYMMDD;

        /* //TMP_RESULT_TABLE */
        INSERT INTO GT_SSP0015_PK_RESULT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY, SEQ)
        SELECT DISTINCT
               X.DIVISION_ID
             , X.ITEM_ID
             , X.FROM_SITE
             , X.MEASURE
             , X.YYYYMMDD
             , NVL(R.QTY, 0)
             , X.SEQ
          FROM (
                SELECT T.DIVISION_ID
                     , T.ITEM_ID
                     , NVL(T.FROM_SITE, '/')    AS FROM_SITE
                     , T.QTY
                     , TT1.COLUMN_NAME          AS MEASURE
                     , TT1.COLUMN_LABEL_NAME    AS MEASURE_NAME
                     , TT1.ATTRIBUTE3           AS BACK_COLOR
                     , TT1.SORT_ORDER_NO        AS SEQ
                     , T.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA T
                     , SCM_MST_SHEET_MEASURE TT1
                     , SCM_MST_TITLESET_USER T3
                 WHERE TT1.PROGRAM_ID = P_PROGRAM_ID
                   AND TT1.SHEET_NAME = P_SHEET_NAME
                   AND T3.PROGRAM_ID(+)  = TT1.PROGRAM_ID
                   AND T3.SHEET_NAME(+)  = TT1.SHEET_NAME
                   AND T3.COLUMN_NAME(+) = TT1.COLUMN_NAME
                   AND T3.USER_ID(+)     = P_USER_ID
               ) X
             , GT_SSP0015_PK_ROWDATA R
         WHERE R.DIVISION_ID(+) = X.DIVISION_ID
           AND R.ITEM_ID(+)     = X.ITEM_ID
           AND R.MEASURE(+)     = X.MEASURE
           AND R.YYYYMMDD(+)    = X.YYYYMMDD
           AND R.FROM_SITE(+)   = X.FROM_SITE
           AND X.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE');   /* PACK FP = PROD_PLAN */

        /* //PIVOT 대상 */
        INSERT INTO GT_SSP0015_PK_RESULT_PIVOT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ)
        SELECT DISTINCT
               T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , 'D_' || T0.YYYYMMDD
             , T1.BASIS_YYYYMM
             , SUBSTR(T1.BASIS_YYYYMM, -4) || T1.ISO_WEEK
             , T0.QTY
             , T0.SEQ
          FROM GT_SSP0015_PK_RESULT T0
             , SCM_SYS_CALENDAR_M T1
         WHERE T0.YYYYMMDD = T1.BASIS_YYYYMMDD(+);

        /* PIVOT 대상 날짜문자열 생성 */
        DBMS_LOB.CREATETEMPORARY(V_MQRY_SUM, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMM = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.ISO_WEEK = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMMDD = SUBSTR(''' || C.YYYYMMDD || ''', -10) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            END IF;
        END LOOP;

        V_MEXEC := 'SELECT DISTINCT TTT.* FROM ( ' || CHR(10)
                || '  SELECT T0.DIVISION_ID' || CHR(10)
                || '       , T0.ITEM_ID' || CHR(10)
                || '       , NVL(IT.NICK_NAME, ''-'')      AS NICK_NAME' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN ''SCS'' WHEN T0.MEASURE = ''BALANCE'' THEN ''ERP'' ELSE '' '' END) AS TYPE' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN NVL(T5.QTY, 0)' || CHR(10)
                || '               WHEN T0.MEASURE = ''BALANCE''  THEN NVL(T6.QTY, 0)' || CHR(10)
                || '          ELSE NULL END)               AS FIGURE' || CHR(10)
                || '       , NVL(T0.FROM_SITE, ''/'')      AS FROM_SITE' || CHR(10)
                || '       , NVL(T4.SITE_DESCRIPTION, ''/'') AS FROM_SITE_NM' || CHR(10)
                || '       , T0.MEASURE                    AS MEASURE' || CHR(10)
                || '       , T2.ATTRIBUTE1                 AS PSI_NAME' || CHR(10)
                || '       , T0.SEQ' || CHR(10)
                || '       , CASE WHEN NVL(T4.SHIP_FROZEN, 0) - 1 > 0 THEN T4.SHIP_FROZEN - 1 ELSE 0 END AS SHIP_FROZEN' || CHR(10)
                || V_MQRY_SUM
                || '    FROM GT_SSP0015_PK_RESULT_PIVOT T0' || CHR(10)
                || '       , SCM_MST_SHEET_MEASURE T2' || CHR(10)
                || '       , SCM_MST_TITLESET_USER T3' || CHR(10)
                || '       , SCM_MST_SITE T4' || CHR(10)
                || '       , GT_SSP0015_PK_WH_STOCK T5' || CHR(10)
                || '       , GT_SSP0015_PK_ERP_STOCK T6' || CHR(10)
                || '       , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME FROM SCM_MST_ITEM_SN' || CHR(10)
                || '           WHERE DIVISION_ID = ''' || P_DIVISION_ID || '''' || CHR(10)
                || '             AND ACTIVE_FLAG = ''Y''' || CHR(10)
                || '             AND SCP_OPERATION_GROUP = ''P'') IT' || CHR(10)
                || '       , SSP_MST_MODEL_USER TT3' || CHR(10)
                || '   WHERE T0.MEASURE = T2.COLUMN_NAME' || CHR(10)
                || '     AND T2.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '     AND T2.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '     AND T3.PROGRAM_ID(+)  = T2.PROGRAM_ID' || CHR(10)
                || '     AND T3.SHEET_NAME(+)  = T2.SHEET_NAME' || CHR(10)
                || '     AND T3.COLUMN_NAME(+) = T2.COLUMN_NAME' || CHR(10)
                || '     AND T3.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                || '     AND T0.DIVISION_ID = T4.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T4.SCM_SITE_ID(+)' || CHR(10)
                || '     AND T4.VALID_YN(+) = ''Y''' || CHR(10)
                || '     AND T0.DIVISION_ID = T5.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T5.FROM_SITE(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T5.ITEM_ID(+)' || CHR(10)
                || '     AND T5.YYYYMMDD(+) = ''' || V_CUTOFF_DATE || '''' || CHR(10)
                || '     AND T5.MEASURE(+)  = ''WH_STOCK''' || CHR(10)
                || '     AND T0.DIVISION_ID = T6.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T6.ITEM_ID(+)' || CHR(10)
                || '     AND T0.DIVISION_ID = IT.DIVISION_ID' || CHR(10)
                || '     AND T0.ITEM_ID     = IT.ITEM_ID' || CHR(10)
                || '     AND TT3.DIVISION_ID(+) = T0.DIVISION_ID' || CHR(10)
                || '     AND TT3.FROM_SITE(+)   = T0.FROM_SITE' || CHR(10)
                || '     AND TT3.ITEM_ID(+)     = T0.ITEM_ID' || CHR(10)
                || '     AND TT3.VALID_YN(+)    = ''Y''' || CHR(10)
                || '     AND T2.VALID_YN = ''Y''' || CHR(10)
                /* 체크박스 체크 여부 조회 */
                || '     AND ((''' || P_NONCHK || ''' = ''Y'' AND 1 = 1)' || CHR(10)
                || '           OR TT3.USER_ID IN (SELECT CASE WHEN ''' || P_MYMODELCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END FROM DUAL' || CHR(10)
                || '                               UNION' || CHR(10)
                || '                              SELECT CASE WHEN ''' || P_DELEGATEECHK || ''' = ''Y'' THEN USER_ID ELSE ''X'' END' || CHR(10)
                || '                                FROM SSP_MST_DELEGATE WHERE VALID_YN = ''Y'' AND DELEGATEE_ID = ''' || P_USER_ID || ''' GROUP BY USER_ID)' || CHR(10)
                || '           OR TT3.PART_LEADER = CASE WHEN ''' || P_PARTLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END' || CHR(10)
                || '           OR TT3.TEAM_LEADER = CASE WHEN ''' || P_TEAMLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END)' || CHR(10);

        IF P_FROM_SITE IS NOT NULL THEN
            V_MEXEC := V_MEXEC
                || '     AND T0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(''' || P_FROM_SITE || ''', '','')))' || CHR(10);
        END IF;

        V_MEXEC := V_MEXEC
                || '     AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                || '           OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SA' || CHR(10)
                || '                       WHERE SA.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '                         AND SA.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '                         AND SA.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                || '                         AND SA.COLUMN_NAME = T2.COLUMN_NAME))' || CHR(10)
                || '     AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T2.DEFAULT_FLAG = ''Y'')' || CHR(10)
                || '           OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                || '   GROUP BY T0.DIVISION_ID, T0.ITEM_ID, IT.NICK_NAME, T0.FROM_SITE, T4.SITE_DESCRIPTION' || CHR(10)
                || '          , T0.MEASURE, T0.SEQ, T2.ATTRIBUTE1, T5.QTY, T6.QTY, T4.SHIP_FROZEN' || CHR(10)
                || ') TTT' || CHR(10)
                || ' ORDER BY TTT.DIVISION_ID, TTT.ITEM_ID, TTT.FROM_SITE DESC, TTT.SEQ ASC';

        OPEN O_RC1 FOR V_MEXEC;

        DBMS_LOB.FREETEMPORARY(V_MQRY_SUM);

    END P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_PACKER
       AS-IS SSP0015_GET_SHIPMENT_PSI_PACKER
       ※ #TEMP 9벌 -> GT_SSP0015_PK_* 9벌
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_PACKER
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_PACKER
         * Description  : Shipment PSI (Packer)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020/11/10   KIMYONGHO      SSP0015_GET_SHIPMENT_PSI 복사 신규추가
         * 2022/02/21   SMS            @v_confirm_date 일자 scm_mst_site(ship_frozen)로 설정
         * 2023/09/19   jilee          G182-P (Group='P',OSP='N')인 사이트 화면에서 제외
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_CNT_USR_MEASURE       PLS_INTEGER := 0;
        V_CUTOFF_DATE           VARCHAR2(8 CHAR);
        V_BOH_YYYYMMDD          VARCHAR2(8 CHAR);
        V_PLAN_CUTOFF_DATE_TIME DATE;
        V_MQRY_SUM              CLOB := EMPTY_CLOB();
        V_MEXEC                 CLOB;
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_PK_SHIP_REQ;
        DELETE FROM GT_SSP0015_PK_PACK_RTF;
        DELETE FROM GT_SSP0015_PK_SHIP_CONFIRM;
        DELETE FROM GT_SSP0015_PK_PROD_PLAN;
        DELETE FROM GT_SSP0015_PK_WH_STOCK;
        DELETE FROM GT_SSP0015_PK_ERP_STOCK;
        DELETE FROM GT_SSP0015_PK_ROWDATA;
        DELETE FROM GT_SSP0015_PK_RESULT;
        DELETE FROM GT_SSP0015_PK_RESULT_PIVOT;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        V_CUTOFF_DATE  := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');
        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* AS-IS : datepart(DW, ...) = 2 는 월요일. Oracle 은 NLS 에 좌우되지 않도록 TO_CHAR(,'D','NLS_DATE_LANGUAGE=AMERICAN') 대신
           고정 기준일과의 차로 요일을 구한다(1900-01-01 은 월요일). */
        IF MOD(TRUNC(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')) - TO_DATE('19000101', 'YYYYMMDD'), 7) = 0 THEN
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 15:30:00', 'YYYYMMDD HH24:MI:SS');
        ELSE
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 07:15:00', 'YYYYMMDD HH24:MI:SS');
        END IF;

        /* //SHIP_REQ Measure 추가 */
        INSERT INTO GT_SSP0015_PK_SHIP_REQ
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'SHIP_REQ'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.YYYYMMDD;

        /* //PACK_RTF Measure 추가 */
        INSERT INTO GT_SSP0015_PK_PACK_RTF
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'PACK_RTF'
             , A.ATTRIBUTE3
             , SUM(TO_NUMBER(A.ATTRIBUTE4 DEFAULT NULL ON CONVERSION ERROR))
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND A.ATTRIBUTE2 <> 'N'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.ATTRIBUTE3, A.ATTRIBUTE4;

        /* //SHIP_CONFIRM Measure 추가 */
        INSERT INTO GT_SSP0015_PK_SHIP_CONFIRM
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , 'SHIP_CONFIRM'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_CONFIRM A
             , SCM_MST_SITE S
         WHERE S.DIVISION_ID = A.DIVISION_ID
           AND S.SCM_SITE_ID = A.FROM_SITE
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND A.BIZ_TYPE  = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           /* jilee 230919 */
           AND S.OSP_YN = 'Y'
         GROUP BY A.DIVISION_ID, A.ITEM_ID, A.FROM_SITE, A.YYYYMMDD
        UNION ALL
        /* 20220221 SMS @v_confirm_date 일자 scm_mst_site(ship_frozen)로 설정 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'SHIP_CONFIRM'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
             , SCM_MST_SITE FS
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = FS.DIVISION_ID
           AND B.FROM_SITE   = FS.SCM_SITE_ID
           AND FS.VALID_YN   = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + NVL(FS.SHIP_FROZEN, 0), 'YYYYMMDD')
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.YYYYMMDD;

        /* //PROD_PLAN Measure 추가 */
        INSERT INTO GT_SSP0015_PK_PROD_PLAN
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.PACK_MODEL_CODE
             , A.SCM_SITE_ID
             , 'PROD_PLAN'
             , A.PROD_DATE
             , NVL(A.PROD_QTY, 0)
          FROM SCM_DNM_SCS_PROD_PLAN A
             , (SELECT DIVISION_ID, MAX(CUTOFF_DATE) AS CUTOFF_DATE, PACK_MODEL_CODE, SCM_SITE_ID, PROD_DATE
                  FROM SCM_DNM_SCS_PROD_PLAN
                 GROUP BY DIVISION_ID, PACK_MODEL_CODE, SCM_SITE_ID, PROD_DATE) B
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.CUTOFF_DATE     = B.CUTOFF_DATE
           AND A.PACK_MODEL_CODE = B.PACK_MODEL_CODE
           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
           AND A.PROD_DATE       = B.PROD_DATE
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.PROD_DATE >= P_FROM_YYYYMMDD
           AND A.PROD_DATE <= P_TO_YYYYMMDD
           AND NVL(A.PROD_QTY, 0) > 0
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.PACK_MODEL_CODE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.PACK_MODEL_CODE IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))));

        /* //WH_STOCK Measure 추가 */
        INSERT INTO GT_SSP0015_PK_WH_STOCK
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , 'WH_STOCK'
             , A.STOCK_DATE
             , SUM(NVL(A.STOCK_QTY, 0))
          FROM SCM_DNM_SCS_STOCK A
         WHERE 1 = 1
           AND A.DIVISION_ID      = P_DIVISION_ID
           AND A.CUTOFF_DATE      = V_CUTOFF_DATE
           AND A.LAST_UPDATE_DATE <= V_PLAN_CUTOFF_DATE_TIME
           AND A.CELL_PACK        = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                 OR  UPPER(P_ITEM_ID) = 'ALL'         /* 조회조건 ALL 은 조건 없음 */
--               OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                 OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR  UPPER(P_FROM_SITE) = 'ALL'       /* 조회조건 ALL 은 조건 없음 */
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.STOCK_DATE;

        /* //ERP 재고 데이터 */
        INSERT INTO GT_SSP0015_PK_ERP_STOCK
               (DIVISION_ID, PLANT_ID, ITEM_ID, BOH_TYPE, YYYYMMDD, QTY)
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.ITEM_ID
             , 'ERP'
             , IA.CUTOFF_DATE
             , SUM(IA.SCM_QTY)
          FROM (
                SELECT DISTINCT
                       A.DIVISION_ID
                     , A.COMPANY_ID
                     , A.ITEM_ID
                     , A.SCM_QTY
                     , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
                     , A.PLANT_ID
                     , A.STOCK_TYPE
                  FROM SCM_DNM_STOCK_V A
                 WHERE 1 = 1
                   AND A.DIVISION_ID = '40'
                   AND A.COMPANY_ID  = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER', 'ESOC')   /* C100 */
                   AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                   AND A.ORG_CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD') + 1 /* AJS 20261007 속도 : 원장 마감일 조건(뷰 마감일 + 1 과 같은 값) */
                   AND A.PLANT_ID    = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER', 'A010')   /* A010 */
                   AND A.STOCK_TYPE  = 'INVENTORY'
               ) IA
         WHERE IA.STOCK_TYPE = 'INVENTORY'
         GROUP BY IA.DIVISION_ID, IA.COMPANY_ID, IA.ITEM_ID, IA.CUTOFF_DATE, IA.PLANT_ID, IA.STOCK_TYPE;

        /* //TMP_ROWDATA */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
          FROM (
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_SHIP_REQ
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_PACK_RTF
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_SHIP_CONFIRM
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_PROD_PLAN
               ) T0
         GROUP BY T0.DIVISION_ID, T0.ITEM_ID, T0.FROM_SITE, T0.MEASURE, T0.YYYYMMDD;

        /* //4. WH_STOCK - 전일 WH_STOCK + PROD_PLAN - SHIP_CONFIRM 누적 + SCS 재고 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , 'WH_STOCK'
             , T0.YYYYMMDD
             , (SELECT NVL(SUM(CASE WHEN TT0.MEASURE = 'SHIP_CONFIRM' THEN -1 * NVL(TT0.QTY, 0)
                                    WHEN TT0.MEASURE = 'PROD_PLAN'    THEN      NVL(TT0.QTY, 0)
                                    ELSE 0 END), 0)
                  FROM GT_SSP0015_PK_ROWDATA TT0
                 WHERE 1 = 1
                   AND TT0.DIVISION_ID = T0.DIVISION_ID
                   AND TT0.FROM_SITE   = T0.FROM_SITE
                   AND TT0.ITEM_ID     = T0.ITEM_ID
                   AND TT0.MEASURE IN ('SHIP_CONFIRM', 'PROD_PLAN')
                   AND TT0.YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND TT0.YYYYMMDD <= T0.YYYYMMDD)
               + NVL(T1.QTY, 0)
          FROM (
                /* Deduplication */
                SELECT R.DIVISION_ID
                     , R.FROM_SITE
                     , R.ITEM_ID
                     , C.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA R
                     , (SELECT BASIS_YYYYMMDD AS YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M
                         WHERE BASIS_YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                           AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD) C
                 WHERE C.YYYYMMDD(+) >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                 GROUP BY R.DIVISION_ID, R.FROM_SITE, R.ITEM_ID, C.YYYYMMDD
               ) T0
             , (SELECT A.DIVISION_ID, A.ITEM_ID, A.FROM_SITE, A.QTY
                  FROM GT_SSP0015_PK_WH_STOCK A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD    = V_CUTOFF_DATE
                   AND A.MEASURE     = 'WH_STOCK'
                   AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                         OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                       OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                         OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                   AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                         OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                         OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))) T1
         WHERE T0.DIVISION_ID = T1.DIVISION_ID(+)
           AND T0.FROM_SITE   = T1.FROM_SITE(+)
           AND T0.ITEM_ID     = T1.ITEM_ID(+)
           AND T0.YYYYMMDD   <= P_TO_YYYYMMDD;

        /* //BALANCE Measure 추가 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT DIVISION_ID
             , ITEM_ID
             , FROM_SITE
             , 'BALANCE'
             , YYYYMMDD
             , NVL(SUM(CASE WHEN MEASURE = 'SHIP_CONFIRM' THEN -1 * NVL(QTY, 0)
                            WHEN MEASURE = 'WH_STOCK'     THEN      NVL(QTY, 0)
                            ELSE 0 END), 0)
          FROM GT_SSP0015_PK_ROWDATA
         WHERE 1 = 1
           AND MEASURE IN ('SHIP_CONFIRM', 'WH_STOCK', 'PROD_PLAN')
           AND YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD;

        /* //TMP_RESULT_TABLE */
        INSERT INTO GT_SSP0015_PK_RESULT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY, SEQ)
        SELECT DISTINCT
               X.DIVISION_ID
             , X.ITEM_ID
             , X.FROM_SITE
             , X.MEASURE
             , X.YYYYMMDD
             , NVL(R.QTY, 0)
             , X.SEQ
          FROM (
                SELECT T.DIVISION_ID
                     , T.ITEM_ID
                     , NVL(T.FROM_SITE, '/')    AS FROM_SITE
                     , T.QTY
                     , TT1.COLUMN_NAME          AS MEASURE
                     , TT1.COLUMN_LABEL_NAME    AS MEASURE_NAME
                     , TT1.ATTRIBUTE3           AS BACK_COLOR
                     , TT1.SORT_ORDER_NO        AS SEQ
                     , T.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA T
                     , SCM_MST_SHEET_MEASURE TT1
                     , SCM_MST_TITLESET_USER T3
                 WHERE TT1.PROGRAM_ID = P_PROGRAM_ID
                   AND TT1.SHEET_NAME = P_SHEET_NAME
                   AND T3.PROGRAM_ID(+)  = TT1.PROGRAM_ID
                   AND T3.SHEET_NAME(+)  = TT1.SHEET_NAME
                   AND T3.COLUMN_NAME(+) = TT1.COLUMN_NAME
                   AND T3.USER_ID(+)     = P_USER_ID
               ) X
             , GT_SSP0015_PK_ROWDATA R
         WHERE R.DIVISION_ID(+) = X.DIVISION_ID
           AND R.ITEM_ID(+)     = X.ITEM_ID
           AND R.MEASURE(+)     = X.MEASURE
           AND R.YYYYMMDD(+)    = X.YYYYMMDD
           AND R.FROM_SITE(+)   = X.FROM_SITE
           AND X.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE');

        /* //PIVOT 대상 */
        INSERT INTO GT_SSP0015_PK_RESULT_PIVOT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ)
        SELECT DISTINCT
               T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , 'D_' || T0.YYYYMMDD
             , T1.BASIS_YYYYMM
             , SUBSTR(T1.BASIS_YYYYMM, -4) || T1.ISO_WEEK
             , T0.QTY
             , T0.SEQ
          FROM GT_SSP0015_PK_RESULT T0
             , SCM_SYS_CALENDAR_M T1
         WHERE T0.YYYYMMDD = T1.BASIS_YYYYMMDD(+);

        /* PIVOT 대상 날짜문자열 생성 */
        DBMS_LOB.CREATETEMPORARY(V_MQRY_SUM, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMM = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.ISO_WEEK = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMMDD = SUBSTR(''' || C.YYYYMMDD || ''', -10) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            END IF;
        END LOOP;

        V_MEXEC := 'SELECT DISTINCT TTT.* FROM ( ' || CHR(10)
                || '  SELECT T0.DIVISION_ID' || CHR(10)
                || '       , T0.ITEM_ID' || CHR(10)
                || '       , NVL(IT.NICK_NAME, ''-'')      AS NICK_NAME' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN ''SCS'' WHEN T0.MEASURE = ''BALANCE'' THEN ''ERP'' ELSE '' '' END) AS TYPE' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN NVL(T5.QTY, 0)' || CHR(10)
                || '               WHEN T0.MEASURE = ''BALANCE''  THEN NVL(T6.QTY, 0)' || CHR(10)
                || '          ELSE NULL END)               AS FIGURE' || CHR(10)
                || '       , NVL(T0.FROM_SITE, ''/'')      AS FROM_SITE' || CHR(10)
                || '       , NVL(T4.SITE_DESCRIPTION, ''/'') AS FROM_SITE_NM' || CHR(10)
                || '       , T0.MEASURE                    AS MEASURE' || CHR(10)
                || '       , T2.ATTRIBUTE1                 AS PSI_NAME' || CHR(10)
                || '       , T0.SEQ' || CHR(10)
                || '       , CASE WHEN NVL(T4.SHIP_FROZEN, 0) - 1 > 0 THEN T4.SHIP_FROZEN - 1 ELSE 0 END AS SHIP_FROZEN' || CHR(10)
                || V_MQRY_SUM
                || '    FROM GT_SSP0015_PK_RESULT_PIVOT T0' || CHR(10)
                || '       , SCM_MST_SHEET_MEASURE T2' || CHR(10)
                || '       , SCM_MST_TITLESET_USER T3' || CHR(10)
                || '       , SCM_MST_SITE T4' || CHR(10)
                || '       , GT_SSP0015_PK_WH_STOCK T5' || CHR(10)
                || '       , GT_SSP0015_PK_ERP_STOCK T6' || CHR(10)
                || '       , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME FROM SCM_MST_ITEM_SN' || CHR(10)
                || '           WHERE DIVISION_ID = ''' || P_DIVISION_ID || '''' || CHR(10)
                || '             AND ACTIVE_FLAG = ''Y''' || CHR(10)
                || '             AND SCP_OPERATION_GROUP = ''P'') IT' || CHR(10)
                || '       , SSP_MST_MODEL_USER TT3' || CHR(10)
                || '   WHERE T0.MEASURE = T2.COLUMN_NAME' || CHR(10)
                || '     AND T2.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '     AND T2.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '     AND T3.PROGRAM_ID(+)  = T2.PROGRAM_ID' || CHR(10)
                || '     AND T3.SHEET_NAME(+)  = T2.SHEET_NAME' || CHR(10)
                || '     AND T3.COLUMN_NAME(+) = T2.COLUMN_NAME' || CHR(10)
                || '     AND T3.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                || '     AND T0.DIVISION_ID = T4.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T4.SCM_SITE_ID(+)' || CHR(10)
                || '     AND T4.VALID_YN(+) = ''Y''' || CHR(10)
                || '     AND T0.DIVISION_ID = T5.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T5.FROM_SITE(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T5.ITEM_ID(+)' || CHR(10)
                || '     AND T5.YYYYMMDD(+) = ''' || V_CUTOFF_DATE || '''' || CHR(10)
                || '     AND T5.MEASURE(+)  = ''WH_STOCK''' || CHR(10)
                || '     AND T0.DIVISION_ID = T6.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T6.ITEM_ID(+)' || CHR(10)
                || '     AND T0.DIVISION_ID = IT.DIVISION_ID' || CHR(10)
                || '     AND T0.ITEM_ID     = IT.ITEM_ID' || CHR(10)
                || '     AND TT3.DIVISION_ID(+) = T0.DIVISION_ID' || CHR(10)
                || '     AND TT3.FROM_SITE(+)   = T0.FROM_SITE' || CHR(10)
                || '     AND TT3.ITEM_ID(+)     = T0.ITEM_ID' || CHR(10)
                || '     AND TT3.VALID_YN(+)    = ''Y''' || CHR(10)
                || '     AND T2.VALID_YN = ''Y''' || CHR(10)
                || '     AND ((''' || P_NONCHK || ''' = ''Y'' AND 1 = 1)' || CHR(10)
                || '           OR TT3.USER_ID IN (SELECT CASE WHEN ''' || P_MYMODELCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END FROM DUAL' || CHR(10)
                || '                               UNION' || CHR(10)
                || '                              SELECT CASE WHEN ''' || P_DELEGATEECHK || ''' = ''Y'' THEN USER_ID ELSE ''X'' END' || CHR(10)
                || '                                FROM SSP_MST_DELEGATE WHERE VALID_YN = ''Y'' AND DELEGATEE_ID = ''' || P_USER_ID || ''' GROUP BY USER_ID)' || CHR(10)
                || '           OR TT3.PART_LEADER = CASE WHEN ''' || P_PARTLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END' || CHR(10)
                || '           OR TT3.TEAM_LEADER = CASE WHEN ''' || P_TEAMLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END)' || CHR(10);

        IF P_FROM_SITE IS NOT NULL THEN
            V_MEXEC := V_MEXEC
                || '     AND T0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(''' || P_FROM_SITE || ''', '','')))' || CHR(10);
        END IF;

        V_MEXEC := V_MEXEC
                || '     AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                || '           OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SA' || CHR(10)
                || '                       WHERE SA.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '                         AND SA.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '                         AND SA.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                || '                         AND SA.COLUMN_NAME = T2.COLUMN_NAME))' || CHR(10)
                || '     AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T2.DEFAULT_FLAG = ''Y'')' || CHR(10)
                || '           OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                || '   GROUP BY T0.DIVISION_ID, T0.ITEM_ID, IT.NICK_NAME, T0.FROM_SITE, T4.SITE_DESCRIPTION' || CHR(10)
                || '          , T0.MEASURE, T0.SEQ, T2.ATTRIBUTE1, T5.QTY, T6.QTY, T4.SHIP_FROZEN' || CHR(10)
                || ') TTT' || CHR(10)
                || ' ORDER BY TTT.DIVISION_ID, TTT.FROM_SITE DESC, TTT.ITEM_ID, TTT.SEQ ASC';

        OPEN O_RC1 FOR V_MEXEC;

        DBMS_LOB.FREETEMPORARY(V_MQRY_SUM);

    END P_SSP0015_GET_SHIPMENT_PSI_PACKER;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI
       AS-IS SSP0015_GET_SHIPMENT_PSI - 화면 본체
       ※ #Tmp_RowData -> GT_SSP0015_ROWDATA
       ※ #TblDynamicTitlest_SSP0015 는 SCM_MST_TITLESET_USER 를 같은 조건으로 다시 읽는 것과
          결과가 같아 GTT 를 두지 않고 원본 테이블을 직접 참조한다.
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
          AS-IS 는 SUM 피벗(수치)과 MAX 피벗(LOT 문자)을 UNION ALL 로 합친다. 형태를 유지한다.
       ※ NOTE · Prod Qty 는 AS-IS 가 SSP0015_GET_SHIPMENT_PSI_COMMENTS 를 호출해 결과셋 2벌을 덧붙인다.
          O_RC2 · O_RC3 로 같은 벌 수를 맞춘다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR,
        O_RC3                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/03/05   AYJ            Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/05/16   AYJ            [CSR:] MST_MEASURE DEFAULT_FLAG='N', 유져 셋팅 없을 시 화면에 노출되지 않도록 수정
         * 2019/06/17   AYJ            조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/05   MCTHEJ         [CSR ID:4045693] measure 'LOT'의 문자값에 대한 PIVOT 처리 추가
         * 2019/08/09   MCTHEJ         [CSR ID:4061695] SSP 시스템 개선 요청건(Shipment Plan) - NOTE 추가
         * 2019/08/28   AYJ            조회 조건 추가(p_delegateeChk)
         * 2019/12/17   KIMYONGHO      BOH 조정 (이름 변경 및 추가) EX) TOTAL -> oWMS
         * 2020/09/23   KIMYONGHO      WH_STOCK BOH 수량에서 CHANGE_STATUS 'Delete' 제외 ('D')
         * 2020/10/22   KIMYONGHO      POUCH_WH_IN_DAY LOOKUP에 해당하는 내용은 L/T = LOOKUP의 SEGMENT2 값 적용
         * 2021/11/01   KIMYONGHO      @p_real_flag 구분 조회
         * 2022/11/14   jilee          DM_PLN_SHIPMENT_REQ -> SITE_TYPE ='SALES' 주석처리
         * 2023/09/21   jilee          G182-P (Group='P',OSP='N')조회 추가
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         * 2026.10.07   AJS            속도 2차 : 출하 확정 구간 함수 DUAL 캐시 · HOLD 재고 한 번 집계 외부조인
         *                             · 빈 칸 0 채우기 DISTINCT 뷰 유지(NO_MERGE) · 결과 문장 재고 뷰 조건 밀어넣기 차단(NO_PUSH_PRED)
         *                             · 결과 문장 확정 버전 EXISTS 필터 고정(NO_UNNEST) · 사이트 설명 함수 DUAL 캐시
         * 2026.10.08   AJS            조회조건 Model/Nickname : 'ALL'(대소문자 무시 · 앞뒤 공백 무시) 은 조건 없음 (품목 목록 만들기 전에 판정 · 메모·생산수량 조회에도 판정 후 값 전달)
         */
        V_PLAN_VERSION_DATE     VARCHAR2(8 CHAR);
        V_REAL_FLAG             VARCHAR2(1 CHAR);
        V_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR) := P_PLAN_START_YYYYMMDD;
        V_CNT_USR_MEASURE       PLS_INTEGER := 0;
        V_PLAN_TYPE             VARCHAR2(30 CHAR) := 'SP';
        V_SEQ                   PLS_INTEGER := 1;
        V_FROM_SITE             VARCHAR2(4000 CHAR);
        V_DIVISION_ID           VARCHAR2(4000 CHAR);
        V_ITEM_ID               VARCHAR2(4000 CHAR);
        V_DATA_START_YYYYMMDD   VARCHAR2(8 CHAR);
        V_DATA_END_YYYYMMDD     VARCHAR2(8 CHAR);
        V_MQUERY                CLOB := EMPTY_CLOB();   /* SUM 피벗 칸 */
        V_MQUERY1               CLOB := EMPTY_CLOB();   /* MAX 피벗 칸(LOT) */
        V_MEXEC                 CLOB;
        V_LT_SUB                VARCHAR2(4000 CHAR);
        V_YIELD_SUB             VARCHAR2(4000 CHAR);
        V_LTYN_SUB              VARCHAR2(4000 CHAR);
        V_FIGURE_EXP            VARCHAR2(4000 CHAR);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
/*      IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_ROWDATA;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        BEGIN
            SELECT PLAN_START_YYYYMMDD
              INTO V_PLAN_VERSION_DATE
              FROM (SELECT PLAN_START_YYYYMMDD
                      FROM SSP_PLAN_VERSION_V
                     WHERE DIVISION_ID = '40'
                     GROUP BY PLAN_START_YYYYMMDD
                     ORDER BY PLAN_START_YYYYMMDD DESC)
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_PLAN_VERSION_DATE := NULL;
        END;

        IF V_PLAN_VERSION_DATE = V_PLAN_START_YYYYMMDD THEN
            V_REAL_FLAG := 'Y';
        ELSE
            V_REAL_FLAG := 'N';
        END IF;

        V_DIVISION_ID := P_DIVISION_ID;
/*      V_ITEM_ID     := P_ITEM_ID; */
        V_ITEM_ID     := CASE WHEN TRIM(P_ITEM_ID) IS NULL OR UPPER(TRIM(P_ITEM_ID)) = 'ALL' THEN NULL ELSE P_ITEM_ID END;   /* AJS 20261008 Model/Nickname : 조회조건 ALL 은 조건 없음 */
        V_FROM_SITE   := P_FROM_SITE;

        /* AS-IS : IF LEN(@p_from_site) > 6 SET @p_from_site = ''; */
        IF LENGTH(RTRIM(NVL(V_FROM_SITE, ''))) > 6 THEN
            V_FROM_SITE := '';
        END IF;

        /* DATA 생성 시작 일자 (당일) · 마지막 일자 12주(84일) */
        V_DATA_START_YYYYMMDD := V_PLAN_START_YYYYMMDD;
        V_DATA_END_YYYYMMDD   := TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 84, 'YYYYMMDD');

        /* -------------1------------ 기준 원장 적재 */
        INSERT INTO GT_SSP0015_ROWDATA
               (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
              , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
              , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
              , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
              , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.ITEM_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.MEASURE
             , A.YYYYMMDD
             , A.BOD_ID
             , A.QTY
             , A.ROUTE_ID
             , A.INCOTERMS
             , A.TRANSPORT_MODE
             , A.BIZ_TYPE
             , A.PROJECT_CODE
             , A.FCST_TYPE
             , A.FCST_ETD_DATE
             , A.FCST_ETA_DATE
             , A.ETD_DATE
             , A.ETA_DATE
             , A.CONFIRM_ID
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE10
          FROM SSP_ANL_SHIP_PLAN_40 A
             , SSP_MST_MODEL_USER TT3
         WHERE TT3.DIVISION_ID(+) = A.DIVISION_ID
           AND TT3.FROM_SITE(+)   = A.FROM_SITE
           AND TT3.ITEM_ID(+)     = A.ITEM_ID
           AND TT3.VALID_YN(+)    = 'Y'
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND A.PLAN_TYPE           = P_PLAN_TYPE
           AND A.SEQ                 = P_SEQ
--         AND (V_ITEM_ID IS NULL OR A.ITEM_ID = V_ITEM_ID)   --  2026.10.07 AJS
           AND (V_ITEM_ID IS NULL OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
           AND (V_FROM_SITE IS NULL
                 AND A.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                 OR A.FROM_SITE = V_FROM_SITE)
           AND ((V_REAL_FLAG = 'Y' AND A.MEASURE NOT IN ('SHIP_REQ', 'SHIP_CONFIRM', 'WH_STOCK', 'BALANCE'))
                 OR (V_REAL_FLAG = 'N' AND A.MEASURE IN ('BALANCE', 'INCO_WIP', 'INSP_WIP', 'LOT', 'MES_FCS_HOLD'
                                                       , 'MES_FCS_RELEASE', 'POSTP_PLAN', 'PROD_DATE', 'PROD_PLAN'
                                                       , 'SHIP_CONFIRM', 'SHIP_REQ', 'WH_IN', 'WH_STOCK')))
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND EXISTS (SELECT 1
                         FROM (SELECT Z.DIVISION_ID, Z.SEQ, Z.ITEM_ID, Z.FROM_SITE, SUM(Z.QTY) AS QTY
                                 FROM SSP_ANL_SHIP_PLAN_40 Z
                                WHERE Z.DIVISION_ID         = P_DIVISION_ID
                                  AND Z.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                GROUP BY Z.DIVISION_ID, Z.SEQ, Z.ITEM_ID, Z.FROM_SITE) B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.SEQ         = B.SEQ
                          AND A.ITEM_ID     = B.ITEM_ID
                          AND A.FROM_SITE   = B.FROM_SITE
                          AND B.QTY        <> 0)
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                     UNION
                                    SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                      FROM SSP_MST_DELEGATE
                                     WHERE VALID_YN = 'Y'
                                       AND DELEGATEE_ID = P_USER_ID
                                     GROUP BY USER_ID)
                 OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END);

        IF V_REAL_FLAG = 'Y' THEN

            /* -------------2------------ [S]SHIP_REQ : MKT 담당자가 출하요청한 수량 */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
                  , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
            SELECT R.DIVISION_ID
                 , V_PLAN_START_YYYYMMDD
                 , V_PLAN_TYPE
                 , V_SEQ
                 , R.ITEM_ID
                 , R.FROM_SITE
                 , R.TO_SITE
                 , 'SHIP_REQ'
                 , R.YYYYMMDD
                 , R.BOD_ID
                 , SUM(R.QTY)
                   /* AS-IS ISNULL(S.ROUTE_ID,'-') - 적재 칸이 숫자라 '-' 는 넣을 수 없다. NULL 그대로 둔다. */
                 , S.ROUTE_ID
                 , NVL(S.SSP_INCOTERMS, R.INCOTERMS)
                 , R.TRANSPORT_MODE
                 , R.BIZ_TYPE
                 , R.PROJECT_CODE
                 , R.FCST_TYPE
                 , R.FCST_ETD_DATE
                 , R.FCST_ETA_DATE
                 , R.ETD_DATE
                 , R.ETA_DATE
                 , R.CONFIRM_ID
                 , R.DIVISION_ID
                 , R.DIVISION_ID
                 , NULL   /* ATTRIBUTE1 - PROD_DATE */
                 , R.CREATED_BY   /* ATTRIBUTE2 - REQUESTOR */
                 , NULL, NULL, NULL, NULL, NULL
              FROM (
                    SELECT R.DIVISION_ID
                         , R.ITEM_ID
                         , R.PLANT_SITE_ID  AS FROM_SITE
                         , R.SCM_SITE_ID    AS TO_SITE
                         , R.MEASURE
                         , R.YYYYMMDD
                         , R.BOD_ID
                         , R.QTY
                         , R.INCOTERMS
                         , R.TRANSPORT_MODE
                         , CASE WHEN INSTR(R.PLANT_SITE_ID, '-') = 0 THEN 'A'
                                ELSE SUBSTR(R.PLANT_SITE_ID, INSTR(R.PLANT_SITE_ID, '-') + 1, 1) END AS BIZ_TYPE
                         , R.PROJECT_CODE
                         , R.FCST_TYPE
                         , R.YYYYMMDD       AS FCST_ETD_DATE
                         , NULL             AS FCST_ETA_DATE
                         , R.YYYYMMDD       AS ETD_DATE
                         , NULL             AS ETA_DATE
                         , R.ATTRIBUTE10    AS CONFIRM_ID
                         , R.CREATED_BY
                      FROM DM_PLN_SHIPMENT_REQ R
                         , SSP_MST_MODEL_USER TT3
                     WHERE TT3.DIVISION_ID(+) = R.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = R.PLANT_SITE_ID
                       AND TT3.ITEM_ID(+)     = R.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND R.DIVISION_ID = V_DIVISION_ID
--                     AND (V_ITEM_ID IS NULL OR R.ITEM_ID = V_ITEM_ID)   --  2026.10.07 AJS
                       AND (V_ITEM_ID IS NULL OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND R.MEASURE     = 'SHIP_REQ'
                       AND (V_FROM_SITE IS NULL
                             AND R.PLANT_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR R.PLANT_SITE_ID = V_FROM_SITE)
                       AND R.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND R.YYYYMMDD <= P_TO_YYYYMMDD
                       AND R.QTY > 0
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
                                                   AND DELEGATEE_ID = P_USER_ID
                                                 GROUP BY USER_ID)
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) R
                   /* AS-IS 의 ON S.INCOTERMS <> S.SSP_INCOTERMS 는 외부조인 대상 자체에 대한 조건이라
                      (+) 표기로는 ORA-01416 이 난다. 인라인 뷰로 먼저 걸러 같은 결과를 만든다. */
                 , (SELECT DIVISION_ID, FROM_SITE, BOD_ID, ROUTE_ID, SSP_INCOTERMS
                      FROM SCP_MST_BOD_N_V
                     WHERE INCOTERMS <> SSP_INCOTERMS) S
             WHERE S.DIVISION_ID(+)  = R.DIVISION_ID
               AND S.FROM_SITE(+)    = R.FROM_SITE
               AND S.BOD_ID(+)       = R.BOD_ID
               AND R.DIVISION_ID = V_DIVISION_ID
               AND R.MEASURE     = 'SHIP_REQ'
               AND (V_FROM_SITE IS NULL
                     AND R.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                     OR R.FROM_SITE = V_FROM_SITE)
               AND R.YYYYMMDD >= V_DATA_START_YYYYMMDD
               AND R.YYYYMMDD <= P_TO_YYYYMMDD
             GROUP BY R.DIVISION_ID
                 , R.ITEM_ID
                 , R.FROM_SITE
                 , R.TO_SITE
                 , R.YYYYMMDD
                 , R.BOD_ID
                   /* AS-IS ISNULL(S.ROUTE_ID,'-') - 적재 칸이 숫자라 '-' 는 넣을 수 없다. NULL 그대로 둔다. */
                 , S.ROUTE_ID
                 , NVL(S.SSP_INCOTERMS, R.INCOTERMS)
                 , R.TRANSPORT_MODE
                 , R.BIZ_TYPE
                 , R.PROJECT_CODE
                 , R.FCST_TYPE
                 , R.FCST_ETD_DATE
                 , R.FCST_ETA_DATE
                 , R.ETD_DATE
                 , R.ETA_DATE
                 , R.CONFIRM_ID
                 , R.CREATED_BY;

            /* -------------3------------ [S]SHIP_CONFIRM : 출하 확정 수량 */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
                  , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
            SELECT A.DIVISION_ID
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.BOD_ID
                 , SUM(A.QTY)
                 , A.ROUTE_ID
                 , A.INCOTERMS
                 , A.TRANSPORT_MODE
                 , A.BIZ_TYPE
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , A.FCST_ETD_DATE
                 , MAX(A.FCST_ETA_DATE)
                 , A.ETD_DATE
                 , MAX(A.ETA_DATE)
                 , MAX(A.CONFIRM_ID)
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID
                 , NULL
                 , MAX(A.ATTRIBUTE2)
                 , NULL, NULL, NULL, NULL, NULL
              FROM (
                    SELECT C.DIVISION_ID                        AS DIVISION_ID
                         , V_PLAN_START_YYYYMMDD                AS PLAN_START_YYYYMMDD
                         , V_PLAN_TYPE                          AS PLAN_TYPE
                         , V_SEQ                                AS SEQ
                         , C.ITEM_ID                            AS ITEM_ID
                         , C.FROM_SITE                          AS FROM_SITE
                         , C.TO_SITE                            AS TO_SITE
                         , 'SHIP_CONFIRM'                       AS MEASURE
                         , C.YYYYMMDD                           AS YYYYMMDD
                         , C.BOD_ID                             AS BOD_ID
                         , C.QTY                                AS QTY
                         , C.ROUTE_ID                           AS ROUTE_ID
                         , NVL(S.SSP_INCOTERMS, C.INCOTERMS)    AS INCOTERMS
                         , C.TRANSPORT_MODE                     AS TRANSPORT_MODE
                         , C.BIZ_TYPE                           AS BIZ_TYPE
                         , C.PROJECT_CODE                       AS PROJECT_CODE
                         , C.FCST_TYPE                          AS FCST_TYPE
                         , C.FCST_ETD_DATE                      AS FCST_ETD_DATE
                         , C.FCST_ETA_DATE                      AS FCST_ETA_DATE
                         , C.ETD_DATE                           AS ETD_DATE
                         , C.ETA_DATE                           AS ETA_DATE
                         , C.CONFIRM_ID                         AS CONFIRM_ID
                         , C.DIVISION_ID                        AS ORIGIN_FROM_DIVISION_ID
                         , C.DIVISION_ID                        AS ORIGIN_TO_DIVISION_ID
                         , C.REQUESTOR                          AS ATTRIBUTE2
                      FROM SSP_ANL_SHIP_CONFIRM C
                         , (SELECT DIVISION_ID, FROM_SITE, BOD_ID, SSP_INCOTERMS
                              FROM SCP_MST_BOD_N_V
                             WHERE INCOTERMS <> SSP_INCOTERMS) S
                         , SSP_MST_MODEL_USER TT3
                     WHERE S.DIVISION_ID(+)  = C.DIVISION_ID
                       AND S.FROM_SITE(+)    = C.FROM_SITE
                       AND S.BOD_ID(+)       = C.BOD_ID
                       AND TT3.DIVISION_ID(+) = C.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = C.FROM_SITE
                       AND TT3.ITEM_ID(+)     = C.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND (V_FROM_SITE IS NULL
                             AND C.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR C.FROM_SITE = V_FROM_SITE)
--                     AND (V_ITEM_ID IS NULL OR C.ITEM_ID = V_ITEM_ID)   --  2026.10.07 AJS
                       AND (V_ITEM_ID IS NULL OR C.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND C.CHANGE_TYPE = 'C'
                       AND C.BIZ_TYPE   <> 'E'   /* 전극제외 */
                       AND C.QTY > 0
                       AND C.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND C.YYYYMMDD <= P_TO_YYYYMMDD
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
                                                   AND DELEGATEE_ID = P_USER_ID
                                                 GROUP BY USER_ID)
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                    UNION ALL
                    SELECT R.DIVISION_ID
                         , V_PLAN_START_YYYYMMDD
                         , V_PLAN_TYPE
                         , V_SEQ
                         , R.ITEM_ID
                         , R.PLANT_SITE_ID
                         , R.SCM_SITE_ID
                         , 'SHIP_CONFIRM'
                         , R.YYYYMMDD
                         , R.BOD_ID
                         , R.QTY
                         , S.ROUTE_ID
                         , R.INCOTERMS
                         , R.TRANSPORT_MODE
                         , CASE WHEN INSTR(R.PLANT_SITE_ID, '-') = 0 THEN 'A'
                                ELSE SUBSTR(R.PLANT_SITE_ID, INSTR(R.PLANT_SITE_ID, '-') + 1, 1) END
                         , R.PROJECT_CODE
                         , R.FCST_TYPE
                         , R.YYYYMMDD
                         , NULL
                         , R.YYYYMMDD
                         , NULL
                         , R.ATTRIBUTE10
                         , R.DIVISION_ID
                         , R.DIVISION_ID
                         , NULL
                      FROM DM_PLN_SHIPMENT_REQ R
                         , SCP_MST_BOD_N_V S
                         , SSP_MST_MODEL_USER TT3
                     WHERE S.DIVISION_ID = R.DIVISION_ID
                       AND S.FROM_SITE   = R.PLANT_SITE_ID
                       AND S.BOD_ID      = R.BOD_ID
                       AND TT3.DIVISION_ID(+) = R.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = R.PLANT_SITE_ID
                       AND TT3.ITEM_ID(+)     = R.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND R.DIVISION_ID = V_DIVISION_ID
--                     AND (V_ITEM_ID IS NULL OR R.ITEM_ID = V_ITEM_ID)   --  2026.10.07 AJS
                       AND (V_ITEM_ID IS NULL OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND R.MEASURE     = 'SHIP_REQ'
                       AND (V_FROM_SITE IS NULL
                             AND R.PLANT_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR R.PLANT_SITE_ID = V_FROM_SITE)
/* 2026.10.07 AJS 속도 2차 (START) : 출하 확정 구간 함수를 행마다 부르지 않고 사업부 · 사이트별 한 번 (DUAL 캐시) */
--                     AND R.YYYYMMDD > (CASE WHEN NVL(FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID), 0) = 0
--                                            THEN V_PLAN_START_YYYYMMDD
--                                            ELSE TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
--                                                         + FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID) - 1, 'YYYYMMDD') END)
                       AND R.YYYYMMDD > (CASE WHEN NVL((SELECT FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID) FROM DUAL), 0) = 0 /* AJS 20261007 속도 */
                                              THEN V_PLAN_START_YYYYMMDD /* AJS 20261007 속도 */
                                              ELSE TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') /* AJS 20261007 속도 */
                                                           + (SELECT FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID) FROM DUAL) - 1, 'YYYYMMDD') END) /* AJS 20261007 속도 */
/* 2026.10.07 AJS 속도 2차 (END) */
                       AND R.YYYYMMDD <= P_TO_YYYYMMDD
                       AND R.QTY > 0
                       AND R.ATTRIBUTE10 IS NULL
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
                                                   AND DELEGATEE_ID = P_USER_ID
                                                 GROUP BY USER_ID)
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) A
             WHERE 1 = 1
             GROUP BY A.DIVISION_ID
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.BOD_ID
                 , A.ROUTE_ID
                 , A.INCOTERMS
                 , A.TRANSPORT_MODE
                 , A.BIZ_TYPE
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , A.FCST_ETD_DATE
                 , A.ETD_DATE
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID;

            /* -------------4------------ [I]WH_STOCK */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
            SELECT Z.DIVISION_ID
                 , Z.PLAN_START_YYYYMMDD
                 , Z.PLAN_TYPE
                 , Z.SEQ
                 , Z.ITEM_ID
                 , Z.FROM_SITE
                 , '-'
                 , 'WH_STOCK'
                 , Z.YYYYMMDD
                 , '-'
                   /* 전일 WH_IN , 전일 SHIP_CONFIRM 누적 */
                 , (CASE WHEN V_PLAN_START_YYYYMMDD < Z.YYYYMMDD
                         THEN (SELECT NVL(SUM(CASE X.MEASURE WHEN 'SHIP_CONFIRM'    THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'POSTP_PLAN'      THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'MES_FCS_HOLD'    THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'WH_IN'           THEN      NVL(X.QTY, 0)
                                                             WHEN 'MES_FCS_RELEASE' THEN      NVL(X.QTY, 0)
                                                        ELSE 0.0 END), 0)
                                 FROM GT_SSP0015_ROWDATA X
                                WHERE 1 = 1
                                  AND X.DIVISION_ID         = Z.DIVISION_ID
                                  AND X.PLAN_START_YYYYMMDD = Z.PLAN_START_YYYYMMDD
                                  AND X.PLAN_TYPE           = Z.PLAN_TYPE
                                  AND X.SEQ                 = Z.SEQ
                                  AND X.ITEM_ID             = Z.ITEM_ID
                                  AND X.FROM_SITE           = Z.FROM_SITE
                                  AND X.MEASURE IN ('SHIP_CONFIRM', 'WH_IN', 'POSTP_PLAN', 'MES_FCS_HOLD', 'MES_FCS_RELEASE')
                                  AND X.YYYYMMDD >= V_DATA_START_YYYYMMDD
                                  AND X.YYYYMMDD  < Z.YYYYMMDD)
                         ELSE 0 END)
                   /* 당일 OWMS 재고 */
                   + NVL(BOH.QTY, 0)
                   /* 2020.09.09 KBK : POUCH_WH_IN_DAY 처리 */
                   - (CASE WHEN V_PLAN_START_YYYYMMDD <= Z.YYYYMMDD
                           THEN CASE WHEN NVL(B.SEGMENT3, '/') = 'P' THEN NVL(B.WH_IN_QTY2, 0) ELSE 0 END
                           ELSE 0 END)
                   /* HOLD 재고 제외 */
/* 2026.10.07 AJS 속도 2차 (START) : HOLD 재고를 행마다 다시 읽지 않고 한 번 집계해 외부조인 (아래 IA) */
--                 - NVL((SELECT SUM(H.HOLD_QTY)
--                          FROM SSP_ANL_HOLD_STOCK H
--                             , SCM_SYS_CALENDAR_M C
--                         WHERE H.DIVISION_ID         = V_DIVISION_ID
--                           AND H.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
--                           AND H.PLAN_TYPE           = V_PLAN_TYPE
--                           AND H.SEQ                 = V_SEQ
--                           AND C.BASIS_YYYYMMDD >= H.HOLD_YYYYMMDD
--                           AND C.BASIS_YYYYMMDD <= H.RELEASE_YYYYMMDD
--                           AND C.BASIS_YYYYMMDD >= V_DATA_START_YYYYMMDD
--                           AND C.BASIS_YYYYMMDD  < V_DATA_END_YYYYMMDD
--                           AND H.DIVISION_ID = Z.DIVISION_ID
--                           AND H.FROM_SITE   = Z.FROM_SITE
--                           AND H.ITEM_ID     = Z.ITEM_ID
--                           AND C.BASIS_YYYYMMDD = Z.YYYYMMDD
--                         GROUP BY H.DIVISION_ID, H.FROM_SITE, H.ITEM_ID, C.BASIS_YYYYMMDD), 0) AS QTY
                   - NVL(IA.HOLD_QTY, 0) AS QTY /* AJS 20261007 속도 */
/* 2026.10.07 AJS 속도 2차 (END) */
                 , '/'
                 , '-'
                 , '/'
                 , '/'
                 , '-'
                 , Z.DIVISION_ID
                 , Z.DIVISION_ID
              FROM (
                    SELECT DISTINCT
                           P.DIVISION_ID
                         , P.PLAN_START_YYYYMMDD
                         , P.PLAN_TYPE
                         , P.SEQ
                         , P.ITEM_ID
                         , P.FROM_SITE
                         , P.YYYYMMDD
                      FROM GT_SSP0015_ROWDATA P
                     WHERE 1 = 1
                       AND P.DIVISION_ID         = V_DIVISION_ID
                       AND P.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND P.PLAN_TYPE           = V_PLAN_TYPE
                       AND P.SEQ                 = V_SEQ
                       AND P.MEASURE IN ('SHIP_CONFIRM', 'WH_IN', 'POSTP_PLAN', 'MES_FCS_HOLD', 'MES_FCS_RELEASE')
                       AND P.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND P.YYYYMMDD <= P_TO_YYYYMMDD
                   ) Z
                 , (SELECT XA.DIVISION_ID
                         , XA.PLAN_START_YYYYMMDD
                         , XA.PLAN_TYPE
                         , XA.SEQ
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , SUM(XA.QTY) AS QTY
                      FROM (
                            SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                                 , (CASE WHEN NVL(C.SEGMENT3, '/') = 'P' THEN SUM(A.LOT_QTY_MES) ELSE 0 END) AS QTY
                              FROM SSP_ANL_MES_FCS_STOCK_40_C A
                                 , SCP_MST_FINAL_ITEM B
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
                             WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                               AND B.ITEM_ID(+)     = A.ITEM_ID
                               AND C.LOOKUP_TYPE(+) = 'CELL_TYPE_CODE'
                               AND C.VALID_YN(+)    = 'Y'
                               AND C.SEGMENT1(+)    = B.CELL_TYPE_GROUP_CODE
                               AND A.DIVISION_ID         = V_DIVISION_ID
                               AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND A.PLAN_TYPE           = V_PLAN_TYPE
                               AND A.SEQ                 = V_SEQ
                               AND A.AVAILABLE_YN       <> 'N'
                               AND NVL(A.CHANGE_STATUS, '-') <> 'D'
                             GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID, C.SEGMENT3
                            UNION ALL
                            SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                                 , SUM(A.AVAILABLE_QTY) AS QTY
                              FROM SSP_ANL_OWMS_STOCK_C A
                             WHERE 1 = 1
                               AND A.DIVISION_ID         = V_DIVISION_ID
                               AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND A.PLAN_TYPE           = V_PLAN_TYPE
                               AND A.SEQ                 = V_SEQ
                             GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                            UNION ALL
                            /* STORAGE ID : B100(TCO Ass.BS D/F), R100(TCO Ass.SW D/F) 외주 재고 */
                            SELECT T.DIVISION_ID, T.PLAN_START_YYYYMMDD, T.PLAN_TYPE, T.SEQ, T.SCM_SITE_ID, T.ITEM_ID
                                 , ROUND(SUM(T.QTY), 0) AS QTY
                              FROM SSP_ANL_TCO_STOCK_C T
                             WHERE 1 = 1
                               AND T.DIVISION_ID         = V_DIVISION_ID
                               AND T.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND T.PLAN_TYPE           = V_PLAN_TYPE
                               AND T.SEQ                 = V_SEQ
                             GROUP BY T.DIVISION_ID, T.PLAN_START_YYYYMMDD, T.PLAN_TYPE, T.SEQ, T.ITEM_ID, T.SCM_SITE_ID
                           ) XA
                     GROUP BY XA.DIVISION_ID, XA.PLAN_START_YYYYMMDD, XA.PLAN_TYPE, XA.SEQ, XA.FROM_SITE, XA.ITEM_ID) BOH
                 , (SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.ITEM_ID, A.FROM_SITE
                         , SUM(A.QTY) AS WH_IN_QTY2, C.SEGMENT3
                      FROM GT_SSP0015_ROWDATA A
                         , SCP_MST_FINAL_ITEM B
                         , SCM_ADM_LOOKUP_MASTER_DETAIL C
                         , SCM_ADM_LOOKUP_MASTER_DETAIL D
                     WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                       AND B.ITEM_ID(+)     = A.ITEM_ID
                       AND C.LOOKUP_TYPE = 'CELL_TYPE_CODE'
                       AND C.VALID_YN    = 'Y'
                       AND C.SEGMENT3    = 'P'
                       AND C.SEGMENT1    = B.CELL_TYPE_GROUP_CODE
                       AND D.LOOKUP_TYPE = 'POUCH_WH_IN_DAY'
                       AND D.SEGMENT1    = SUBSTR(A.ITEM_ID, 1, 3)
                       AND D.VALID_YN    = 'Y'
                       AND A.DIVISION_ID         = V_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = V_PLAN_TYPE
                       AND A.SEQ                 = V_SEQ
                       AND A.MEASURE  = 'WH_IN'
                       AND A.YYYYMMDD > V_DATA_START_YYYYMMDD
                       AND A.YYYYMMDD <= TO_CHAR(TO_DATE(V_DATA_START_YYYYMMDD, 'YYYYMMDD')
                                                 + TO_NUMBER(D.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR), 'YYYYMMDD')
                       AND V_REAL_FLAG = 'Y'
                     GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.ITEM_ID, A.FROM_SITE, C.SEGMENT3) B
/* 2026.10.07 AJS 속도 2차 (START) : HOLD 재고 사업부 · 사이트 · 품목 · 일자별 한 번 집계 */
                 , (SELECT /*+ INDEX_SS(H PK_SSP_ANL_HOLD_STOCK_C) */ /* AJS 20261007 속도 */
                           H.DIVISION_ID /* AJS 20261007 속도 */
                         , H.FROM_SITE /* AJS 20261007 속도 */
                         , H.ITEM_ID /* AJS 20261007 속도 */
                         , C.BASIS_YYYYMMDD /* AJS 20261007 속도 */
                         , SUM(H.HOLD_QTY) AS HOLD_QTY /* AJS 20261007 속도 */
                      FROM SSP_ANL_HOLD_STOCK H /* AJS 20261007 속도 */
                         , SCM_SYS_CALENDAR_M C /* AJS 20261007 속도 */
                     WHERE C.BASIS_YYYYMMDD >= H.HOLD_YYYYMMDD /* AJS 20261007 속도 */
                       AND C.BASIS_YYYYMMDD <= H.RELEASE_YYYYMMDD /* AJS 20261007 속도 */
                       AND H.DIVISION_ID         = V_DIVISION_ID /* AJS 20261007 속도 */
                       AND H.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD /* AJS 20261007 속도 */
                       AND H.PLAN_TYPE           = V_PLAN_TYPE /* AJS 20261007 속도 */
                       AND H.SEQ                 = V_SEQ /* AJS 20261007 속도 */
                       AND C.BASIS_YYYYMMDD >= V_DATA_START_YYYYMMDD /* AJS 20261007 속도 */
                       AND C.BASIS_YYYYMMDD  < V_DATA_END_YYYYMMDD /* AJS 20261007 속도 */
                     GROUP BY H.DIVISION_ID, H.FROM_SITE, H.ITEM_ID, C.BASIS_YYYYMMDD) IA /* AJS 20261007 속도 */
/* 2026.10.07 AJS 속도 2차 (END) */
             WHERE Z.DIVISION_ID         = BOH.DIVISION_ID(+)
               AND Z.PLAN_START_YYYYMMDD = BOH.PLAN_START_YYYYMMDD(+)
               AND Z.PLAN_TYPE           = BOH.PLAN_TYPE(+)
               AND Z.SEQ                 = BOH.SEQ(+)
               AND Z.ITEM_ID             = BOH.ITEM_ID(+)
               AND Z.FROM_SITE           = BOH.FROM_SITE(+)
               AND Z.DIVISION_ID         = B.DIVISION_ID(+)
               AND Z.PLAN_START_YYYYMMDD = B.PLAN_START_YYYYMMDD(+)
               AND Z.PLAN_TYPE           = B.PLAN_TYPE(+)
               AND Z.SEQ                 = B.SEQ(+)
               AND Z.ITEM_ID             = B.ITEM_ID(+)
--             AND Z.FROM_SITE           = B.FROM_SITE(+);
               AND Z.FROM_SITE           = B.FROM_SITE(+) /* AJS 20261007 속도 */
               AND Z.DIVISION_ID         = IA.DIVISION_ID(+) /* AJS 20261007 속도 */
               AND Z.FROM_SITE           = IA.FROM_SITE(+) /* AJS 20261007 속도 */
               AND Z.ITEM_ID             = IA.ITEM_ID(+) /* AJS 20261007 속도 */
               AND Z.YYYYMMDD            = IA.BASIS_YYYYMMDD(+); /* AJS 20261007 속도 */

            /* -------------5------------ [I]BALANCE : 당일 WH_STOCK - 당일 SHIP_CONFIRM - 당일 POSTP_PLAN */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
            SELECT B.DIVISION_ID
                 , B.PLAN_START_YYYYMMDD
                 , B.PLAN_TYPE
                 , B.SEQ
                 , B.ITEM_ID
                 , B.FROM_SITE
                 , B.TO_SITE
                 , 'BALANCE'
                 , B.YYYYMMDD
                 , B.BOD_ID
                 , B.QTY - (SELECT SUM(C.QTY)
                              FROM GT_SSP0015_ROWDATA C
                             WHERE 1 = 1
                               AND B.DIVISION_ID         = C.DIVISION_ID
                               AND B.PLAN_START_YYYYMMDD = C.PLAN_START_YYYYMMDD
                               AND B.PLAN_TYPE           = C.PLAN_TYPE
                               AND B.SEQ                 = C.SEQ
                               AND B.ITEM_ID             = C.ITEM_ID
                               AND B.FROM_SITE           = C.FROM_SITE
                               AND B.YYYYMMDD            = C.YYYYMMDD
                               AND C.MEASURE IN ('SHIP_CONFIRM', 'POSTP_PLAN')
                             GROUP BY C.DIVISION_ID, C.PLAN_START_YYYYMMDD, C.PLAN_TYPE, C.SEQ
                                    , C.ITEM_ID, C.FROM_SITE, C.YYYYMMDD) AS QTY
                 , B.INCOTERMS
                 , B.TRANSPORT_MODE
                 , B.PROJECT_CODE
                 , B.FCST_TYPE
                 , '-'
                 , B.DIVISION_ID
                 , B.DIVISION_ID
              FROM GT_SSP0015_ROWDATA B
             WHERE 1 = 1
               AND B.DIVISION_ID         = V_DIVISION_ID
               AND B.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND B.PLAN_TYPE           = V_PLAN_TYPE
               AND B.SEQ                 = V_SEQ
               AND B.MEASURE = 'WH_STOCK';

        END IF;

        /* 빈 칸(측정항목 x 날짜) 을 0 으로 채운다 */
        INSERT INTO GT_SSP0015_ROWDATA
               (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
              , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
              , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
        SELECT SUB.DIVISION_ID
             , SUB.PLAN_START_YYYYMMDD
             , SUB.PLAN_TYPE
             , SUB.SEQ
             , SUB.ITEM_ID
             , SUB.FROM_SITE
             , SUB.TO_SITE
             , SUB.MEASURE
             , SUB.YYYYMMDD
             , SUB.BOD_ID
             , 0
             , SUB.INCOTERMS
             , SUB.TRANSPORT_MODE
             , SUB.PROJECT_CODE
             , SUB.FCST_TYPE
             , SUB.CONFIRM_ID
             , SUB.DIVISION_ID
             , SUB.DIVISION_ID
          FROM (
                SELECT B.DIVISION_ID
                     , B.PLAN_START_YYYYMMDD
                     , B.PLAN_TYPE
                     , B.SEQ
                     , B.ITEM_ID
                     , B.FROM_SITE
                     , '-'          AS TO_SITE
                     , C.MEASURE    AS MEASURE
                     , A.YYYYMMDD
                     , '-'          AS BOD_ID
                     , '-'          AS INCOTERMS
                     , '-'          AS TRANSPORT_MODE
                     , '-'          AS PROJECT_CODE
                     , '-'          AS FCST_TYPE
                     , '-'          AS CONFIRM_ID
                  FROM (SELECT C.BASIS_YYYYMMDD AS YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M C
                         WHERE 1 = 1
                           AND C.BASIS_YYYYMMDD >= V_DATA_START_YYYYMMDD
                           AND C.BASIS_YYYYMMDD <= P_TO_YYYYMMDD) A
--                   , (SELECT DISTINCT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE
                     , (SELECT /*+ NO_MERGE */ DISTINCT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE /* AJS 20261007 속도 */
                          FROM GT_SSP0015_ROWDATA) B
                     , (SELECT COLUMN_NAME AS MEASURE
                          FROM SCM_MST_SHEET_MEASURE
                         WHERE 1 = 1
                           AND PROGRAM_ID = P_PROGRAM_ID
                           AND SHEET_NAME = P_SHEET_NAME
                           AND VALID_YN   = 'Y') C
               ) SUB
         WHERE 1 = 1
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0015_ROWDATA Z
                            WHERE 1 = 1
                              AND Z.DIVISION_ID         = SUB.DIVISION_ID
                              AND Z.PLAN_START_YYYYMMDD = SUB.PLAN_START_YYYYMMDD
                              AND Z.PLAN_TYPE           = SUB.PLAN_TYPE
                              AND Z.SEQ                 = SUB.SEQ
                              AND Z.ITEM_ID             = SUB.ITEM_ID
                              AND Z.FROM_SITE           = SUB.FROM_SITE
                              AND Z.MEASURE             = SUB.MEASURE
                              AND Z.YYYYMMDD            = SUB.YYYYMMDD);

        /* PIVOT 대상 날짜문자열 생성 (AS-IS 는 수치 SUM 피벗과 LOT 문자 MAX 피벗 두 벌을 UNION ALL 한다) */
        DBMS_LOB.CREATETEMPORARY(V_MQUERY, TRUE);
        DBMS_LOB.CREATETEMPORARY(V_MQUERY1, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            /* 수치 SUM 피벗 - 결과는 문자로 돌려준다(AS-IS CONVERT(NVARCHAR(100), ...)) */
            DBMS_LOB.APPEND(V_MQUERY,
                ', TO_CHAR(TRUNC(SUM(CASE WHEN A.PIVOT_KEY = ''' || C.YYYYMMDD || ''' THEN NVL(A.QTY_NUM, 0) ELSE 0 END))) AS ' || C.YYYYMMDD || CHR(10));
            /* LOT 문자 MAX 피벗 */
            DBMS_LOB.APPEND(V_MQUERY1,
                ', MAX(CASE WHEN A.PIVOT_KEY = ''' || C.YYYYMMDD || ''' THEN A.QTY_STR END) AS ' || C.YYYYMMDD || CHR(10));
        END LOOP;

        /* LT_DAY · YEILD · LT_UPDATE_YN 스칼라 서브쿼리 */
        V_LT_SUB := '(SELECT NVL(TO_CHAR(CASE WHEN XB.SEGMENT2 IS NULL THEN XA.LT_FORMATION + NVL(XA.ATTRIBUTE1, 0)'
                 || ' ELSE TO_NUMBER(XB.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) END), '' '')'
                 || ' FROM SSP_ANL_FORMATION_C XA, SCM_ADM_LOOKUP_MASTER_DETAIL XB'
                 || ' WHERE XB.LOOKUP_TYPE(+) = ''POUCH_WH_IN_DAY'' AND XB.VALID_YN(+) = ''Y'''
                 || ' AND XB.SEGMENT1(+) = SUBSTR(XA.ITEM_ID, 1, 3) AND XB.SEGMENT3(+) = ''-'''
                 || ' AND XB.SEGMENT4(+) = ''-'' AND XB.SEGMENT5(+) = ''-'''
                 || ' AND XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                 || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
                 || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1)';

        V_YIELD_SUB := '(SELECT NVL(TO_CHAR(ROUND(XA.SSP_MODIFY_YIELD * 100, 2)), '' '')'
                    || ' FROM SSP_ANL_FORMATION_C XA'
                    || ' WHERE XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                    || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
                    || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1)';

        V_LTYN_SUB := '(SELECT NVL(MIN(XA.ATTRIBUTE2), '' '')'
                   || ' FROM SSP_ANL_FORMATION_C XA'
                   || ' WHERE XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                   || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
                   || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''')';

        V_FIGURE_EXP := 'TO_CHAR(CEIL(CASE WHEN A.MEASURE = ''MES_FCS_HOLD''    THEN NVL(W.TOTAL_QTY, 0)'
                     || ' WHEN A.MEASURE = ''MES_FCS_RELEASE'' THEN NVL(X.HOLD_QTY, 0)'
                     || ' WHEN A.MEASURE = ''WH_STOCK''        THEN NVL(Y.MES_QTY, 0)'
                     || ' WHEN A.MEASURE = ''BALANCE''         THEN NVL(Y.FCS_QTY, 0)'
                     || ' ELSE 0 END), ''FM999,999,999,999,990'')';

        DECLARE
            V_SEL_HEAD  CLOB;
            V_FROM_PART CLOB;
            V_JOIN_PART CLOB;
            V_GRP_PART  CLOB;
        BEGIN

--          V_SEL_HEAD := ' SELECT A.DIVISION_ID' || CHR(10)
            V_SEL_HEAD := ' SELECT /*+ NO_PUSH_PRED(W) */ A.DIVISION_ID' || CHR(10) /* AJS 20261007 속도 */
                       || '      , A.FROM_SITE' || CHR(10)
--                     || '      , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_NM' || CHR(10)
                       || '      , NVL((SELECT FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE) FROM DUAL), ''-'') AS FROM_SITE_NM' || CHR(10) /* AJS 20261007 속도 */
                       || '      , A.PLAN_START_YYYYMMDD' || CHR(10)
                       || '      , A.PLAN_TYPE' || CHR(10)
                       || '      , A.ITEM_ID' || CHR(10)
                       || '      , NVL(A.SHIP_FROZEN, 0) AS SHIP_FROZEN' || CHR(10)
                       || '      , A.SEQ' || CHR(10)
                       || '      , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME' || CHR(10)
                       || '      , A.MEASURE' || CHR(10)
                       || '      , A.MEASURE_NAME' || CHR(10)
                       || '      , A.USER_SORT_ORDER_NO' || CHR(10)
                       || '      , A.PSI_NAME' || CHR(10)
                       || '      , A.FROM_YYYYMMDD' || CHR(10)
                       || '      , A.TO_YYYYMMDD' || CHR(10)
                       || '      , ' || V_LT_SUB || ' AS LT_DAY' || CHR(10)
                       || '      , ' || V_YIELD_SUB || ' AS YEILD' || CHR(10)
                       || '      , ' || V_LTYN_SUB || ' AS LT_UPDATE_YN' || CHR(10)
                       || '      , (CASE WHEN A.MEASURE = ''MES_FCS_HOLD'' THEN ''oWMS'' WHEN A.MEASURE = ''MES_FCS_RELEASE'' THEN ''Hold'''
                       || '              WHEN A.MEASURE = ''WH_STOCK'' THEN ''MES'' WHEN A.MEASURE = ''BALANCE'' THEN ''FCS'' ELSE '' '' END) AS TYPE' || CHR(10)
                       || '      , ' || V_FIGURE_EXP || ' AS FIGURE' || CHR(10);

            V_FROM_PART := '   FROM (SELECT T3.DIVISION_ID, T3.PLAN_START_YYYYMMDD, T3.PLAN_TYPE, T3.FROM_SITE' || CHR(10)
                        || '              , T3.ITEM_ID, T3.SEQ, T3.SHIP_FROZEN, T3.PIVOT_KEY' || CHR(10)
                        || '              , CASE WHEN T0.COLUMN_NAME = ''PROD_DATE''' || CHR(10)
                        || '                     THEN TO_NUMBER(T3.QTY_STR DEFAULT NULL ON CONVERSION ERROR)' || CHR(10)
                        || '                     ELSE T3.QTY_NUM END AS QTY_NUM' || CHR(10)
                        || '              , CASE WHEN T0.COLUMN_NAME = ''LOT'' THEN T3.QTY_STR' || CHR(10)
                        || '                     ELSE TO_CHAR(T3.QTY_NUM) END AS QTY_STR' || CHR(10)
                        || '              , T0.COLUMN_NAME       AS MEASURE' || CHR(10)
                        || '              , T0.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                        || '              , T0.ATTRIBUTE1        AS PSI_NAME' || CHR(10)
                        || '              , NVL(T1.SORT_ORDER_NO, T0.SORT_ORDER_NO) AS USER_SORT_ORDER_NO' || CHR(10)
                        || '              , ''' || P_FROM_YYYYMMDD || ''' AS FROM_YYYYMMDD' || CHR(10)
                        || '              , ''' || P_TO_YYYYMMDD || ''' AS TO_YYYYMMDD' || CHR(10)
                        || '           FROM SCM_MST_SHEET_MEASURE T0' || CHR(10)
                        || '              , SCM_MST_TITLESET_USER T1' || CHR(10)
                        || '              , (SELECT TT0.DIVISION_ID, TT0.PLAN_START_YYYYMMDD, TT0.PLAN_TYPE, TT0.FROM_SITE' || CHR(10)
                        || '                      , TT0.ITEM_ID, ''D_'' || TT0.YYYYMMDD AS PIVOT_KEY, TT0.MEASURE AS MEASURE_KEY' || CHR(10)
                        || '                      , SUM(TT0.QTY) AS QTY_NUM, MAX(TT0.ATTRIBUTE1) AS QTY_STR' || CHR(10)
                        || '                      , MAX(TT0.SEQ) AS SEQ, TT2.SHIP_FROZEN' || CHR(10)
                        || '                   FROM GT_SSP0015_ROWDATA TT0, SCM_MST_SITE TT2' || CHR(10)
                        || '                  WHERE (CASE WHEN TT0.DIVISION_ID = ''EE'' THEN TT0.ORIGIN_FROM_DIVISION_ID ELSE TT0.DIVISION_ID END) = TT2.DIVISION_ID(+)' || CHR(10)
                        || '                    AND TT0.FROM_SITE = TT2.SCM_SITE_ID(+)' || CHR(10)
                        || '                    AND TT2.VALID_YN(+) = ''Y''' || CHR(10)
                        || '                    AND TT0.YYYYMMDD >= ''' || P_FROM_YYYYMMDD || '''' || CHR(10)
                        || '                    AND TT0.YYYYMMDD <= ''' || P_TO_YYYYMMDD || '''' || CHR(10)
--                      || '                    AND EXISTS (SELECT 1 FROM (SELECT DIVISION_ID, MAX(PLAN_SEQ) AS PLAN_SEQ' || CHR(10)
                        || '                    AND EXISTS (SELECT /*+ NO_UNNEST */ 1 FROM (SELECT DIVISION_ID, MAX(PLAN_SEQ) AS PLAN_SEQ' || CHR(10) /* AJS 20261007 속도 */
                        || '                                                 FROM SSP_PLAN_VERSION_V' || CHR(10)
                        || '                                                WHERE PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '                                                  AND CONFIRM_FLAG = ''Y''' || CHR(10)
                        || '                                                  AND PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '                                                GROUP BY DIVISION_ID) SA' || CHR(10)
                        || '                                 WHERE SA.DIVISION_ID = TT0.DIVISION_ID AND SA.PLAN_SEQ = TT0.SEQ)' || CHR(10)
                        || '                  GROUP BY TT0.DIVISION_ID, TT0.PLAN_START_YYYYMMDD, TT0.PLAN_TYPE, TT0.FROM_SITE' || CHR(10)
                        || '                         , TT0.ITEM_ID, TT0.YYYYMMDD, TT2.SHIP_FROZEN, TT0.MEASURE) T3' || CHR(10)
                        || '          WHERE T1.PROGRAM_ID(+)  = T0.PROGRAM_ID' || CHR(10)
                        || '            AND T1.SHEET_NAME(+)  = T0.SHEET_NAME' || CHR(10)
                        || '            AND T1.COLUMN_NAME(+) = T0.COLUMN_NAME' || CHR(10)
                        || '            AND T1.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                        || '            AND T0.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                        || '            AND T0.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                        || '            AND T0.VALID_YN   = ''Y''' || CHR(10)
                        || '            AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                        || '                  OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SB' || CHR(10)
                        || '                              WHERE SB.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                        || '                                AND SB.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                        || '                                AND SB.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                        || '                                AND SB.COLUMN_NAME = T0.COLUMN_NAME))' || CHR(10)
                        || '            AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T0.DEFAULT_FLAG = ''Y'')' || CHR(10)
                        || '                  OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                        || '            AND T0.COLUMN_NAME = T3.MEASURE_KEY' || CHR(10);

            V_JOIN_PART := '        ) A' || CHR(10)
                        || '      , (SELECT S.DIVISION_ID, S.PLAN_START_YYYYMMDD, S.PLAN_TYPE, S.SEQ, S.FROM_SITE, S.ITEM_ID, SUM(S.QTY) AS TOTAL_QTY' || CHR(10)
                        || '           FROM SSP_ANL_WH_STOCK_V S' || CHR(10)
                        || '          WHERE S.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND S.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND S.DIVISION_ID = ''' || V_DIVISION_ID || '''' || CHR(10)
                        || '            AND S.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '          GROUP BY S.DIVISION_ID, S.PLAN_START_YYYYMMDD, S.PLAN_TYPE, S.SEQ, S.FROM_SITE, S.ITEM_ID) W' || CHR(10)
                        || '      , (SELECT K.DIVISION_ID, K.FROM_SITE, K.ITEM_ID, SUM(K.HOLD_QTY) AS HOLD_QTY' || CHR(10)
                        || '           FROM SSP_ANL_HOLD_STOCK K' || CHR(10)
                        || '          WHERE K.HOLD_YYYYMMDD <= ''' || TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') || '''' || CHR(10)
                        || '            AND K.RELEASE_YYYYMMDD >= ''' || TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') || '''' || CHR(10)
                        || '            AND K.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND K.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND K.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '          GROUP BY K.DIVISION_ID, K.FROM_SITE, K.ITEM_ID) X' || CHR(10)
                        || '      , (SELECT M.DIVISION_ID, M.PLAN_START_YYYYMMDD, M.PLAN_TYPE, M.SEQ, M.FROM_SITE, M.ITEM_ID' || CHR(10)
                        || '              , SUM(M.LOT_QTY_MES) AS MES_QTY, SUM(M.LOT_QTY_FCS) AS FCS_QTY' || CHR(10)
                        || '           FROM SSP_ANL_MES_FCS_STOCK_40_C M' || CHR(10)
                        || '          WHERE M.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND M.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND M.DIVISION_ID = ''' || V_DIVISION_ID || '''' || CHR(10)
                        || '            AND M.AVAILABLE_YN <> ''N''' || CHR(10)
                        || '            AND M.CHANGE_STATUS <> ''D''' || CHR(10)
                        || '            AND M.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '            AND M.AVAILABLE_YN = ''Y''' || CHR(10)
                        || '          GROUP BY M.DIVISION_ID, M.PLAN_START_YYYYMMDD, M.PLAN_TYPE, M.SEQ, M.FROM_SITE, M.ITEM_ID) Y' || CHR(10)
                        || '  WHERE A.DIVISION_ID = W.DIVISION_ID(+) AND A.PLAN_START_YYYYMMDD = W.PLAN_START_YYYYMMDD(+)' || CHR(10)
                        || '    AND A.FROM_SITE = W.FROM_SITE(+) AND A.ITEM_ID = W.ITEM_ID(+)' || CHR(10)
                        || '    AND A.DIVISION_ID = X.DIVISION_ID(+) AND A.FROM_SITE = X.FROM_SITE(+) AND A.ITEM_ID = X.ITEM_ID(+)' || CHR(10)
                        || '    AND A.DIVISION_ID = Y.DIVISION_ID(+) AND A.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD(+)' || CHR(10)
                        || '    AND A.FROM_SITE = Y.FROM_SITE(+) AND A.ITEM_ID = Y.ITEM_ID(+)' || CHR(10);

            V_GRP_PART := '  GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.ITEM_ID' || CHR(10)
                       || '         , A.SHIP_FROZEN, A.SEQ, A.MEASURE, A.MEASURE_NAME, A.USER_SORT_ORDER_NO, A.PSI_NAME' || CHR(10)
                       || '         , A.FROM_YYYYMMDD, A.TO_YYYYMMDD, W.TOTAL_QTY, X.HOLD_QTY, Y.MES_QTY, Y.FCS_QTY' || CHR(10);

            V_MEXEC := 'SELECT * FROM (' || CHR(10)
                    || V_SEL_HEAD || V_MQUERY || V_FROM_PART
                    || '            AND T3.MEASURE_KEY != ''LOT''' || CHR(10)
                    || V_JOIN_PART || V_GRP_PART
                    || ' UNION ALL' || CHR(10)
                    || V_SEL_HEAD || V_MQUERY1 || V_FROM_PART
                    || '            AND T3.MEASURE_KEY = ''LOT''' || CHR(10)
                    || V_JOIN_PART || V_GRP_PART
                    || ') TTTT ORDER BY DIVISION_ID, FROM_SITE, ITEM_ID, USER_SORT_ORDER_NO';

        END;

        OPEN O_RC1 FOR V_MEXEC;

        /* NOTE, Prod_Qty Load */
/*      P_SSP0015_GET_SHIPMENT_PSI_COMMENTS(V_DIVISION_ID, V_PLAN_START_YYYYMMDD, V_FROM_SITE, P_ITEM_ID */
        P_SSP0015_GET_SHIPMENT_PSI_COMMENTS(V_DIVISION_ID, V_PLAN_START_YYYYMMDD, V_FROM_SITE, V_ITEM_ID   /* AJS 20261008 Model/Nickname : ALL 판정 후 값(ALL 이면 빈 값) */
                                          , P_FROM_YYYYMMDD, P_TO_YYYYMMDD, O_RC2, O_RC3);

        DBMS_LOB.FREETEMPORARY(V_MQUERY);
        DBMS_LOB.FREETEMPORARY(V_MQUERY1);

    END P_SSP0015_GET_SHIPMENT_PSI;

    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40
       AS-IS SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40
       ※ '^' 로 이어 붙인 여러 행을 SCM_ARR_SPL_VAL 로 잘라 한 행씩 처리한다(AS-IS 동일).
       ※ 행 구분(ACTIVE_FLAG) : 'I' = 신규 출하확정 생성, 'I' 가 아닌 값(M·D) = 기존 출하확정 수정(AS-IS 동일, 삭제 갈래 없음).
       ※ AS-IS #TblDynamic_SSP0015_40_STD → GT_SSP0015_40_STD(ON COMMIT PRESERVE ROWS, 시작 시 DELETE).
       ※ 저장 시작에 SAVEPOINT 를 두어 BOD 없음('X')·오류('F') 시 앞 행 저장분까지 되돌린다.
          (AS-IS 는 트랜잭션이 없어 앞 행 저장분이 남고, 오류 시 CATCH 에서 COMMIT 한다)
       ※ AS-IS 가 부르는 하위 프로시저 3개는 Oracle 에 없다(2026.09.17 기준) — 호출 자리를 주석으로 남긴다.
          PR_DM_SSP_CONFIRM_SYNC · PR_SSP_ANL_SHIP_CONFIRM_HIST · PR_SSP_MAIL_SEND_ADJUST_MST
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40
    (
        P_ACTIVE_FLAG           IN  VARCHAR2,
        P_DIVISION_ID           IN  VARCHAR2,
        P_CONFIRM_ID            IN  VARCHAR2,
        P_SHIPMENT_QTY          IN  VARCHAR2,
        P_SHIPMENT_DATE         IN  VARCHAR2,
        P_NEW_BOD_ID            IN  VARCHAR2,
        P_NEW_ROUTE_ID          IN  VARCHAR2,
        P_NEW_ETD_DATE          IN  VARCHAR2,
        P_NEW_ETA_DATE          IN  VARCHAR2,
        P_NEW_INCOTERMS         IN  VARCHAR2,
        P_NEW_TRANSPORT_MODE    IN  VARCHAR2,
        P_NEW_D_CONTRY          IN  VARCHAR2,
        P_NEW_D_PORT_CODE       IN  VARCHAR2,
        P_NEW_A_COUNTRY         IN  VARCHAR2,
        P_NEW_A_PORT_CODE       IN  VARCHAR2,
        P_NEW_CUSTOMER_LT       IN  VARCHAR2,
        P_NEW_TO_COUNTRY        IN  VARCHAR2,
        P_NEW_TO_CITY           IN  VARCHAR2,
        P_REMARKS               IN  VARCHAR2,
        P_REMARKS2              IN  VARCHAR2,
        P_REMARKS3              IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_CHECK_NEED_YN         IN  VARCHAR2,
        P_EDIT_MAIN             IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40
         * Description  : Shipment Request Confirm 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/03/12   AYJ            Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/04/30   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REQUESTOR 컬럼 제거
         * 2019/05/07   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REMARKS3 컬럼 추가
         * 2019/05/30   mcTheJ         [PJ20189106] 전지.GSCM 고도화 이행  CHANGE_REASON 추가로 인한 메일 SEND 수정
         * 2019/09/04   AYJ            etd:shipdate, eta:etd+lt_day로 셋팅
         * 2019/10/29   ayj            FCST_ETA_DATE, ETA_DATE 저장 값 수정(출발일 기준 항차를 고려한 ETA_DATE 계산)
         * 2019/11/26   KIMYONGHO      메일 전송 변경 JOB.SCM_SSP_ADJUST_MAIL_SEND_BATCH -> PR_SSP_MAIL_SEND_ADJUST_MST
         * 2020/06/23   khj79          ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정
         * 2021/01/07   KIMYONGHO      [C20201223-000448] MKT FCST - SSP Sync
         * 2021/01/12   KIMYONGHO      [C20201223-000448] MKT FCST - SSP Sync 운영이관 검증 단계에서 처리 지연 현상으로 END LOG 이후 호출로 조정함.
         * 2021/11/15   KIMYONGHO      PR_SSP_ANL_SHIP_UPDATE_BOH_VAL_40 제외 처리
         * 2024/06/10   jilee          Plan 하단 신규 건 Change Req 정보 입력
         * 2024/10/01   KHJ            NERP_SSP
         * 2026.09.17   AJS            MSSQL -> Oracle 전환
         */
        V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40';
        V_LOG_TYPE                  VARCHAR2(30 CHAR);
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
        V_DESCRIPTION               VARCHAR2(500 CHAR);
        D_EVENT_DATE                DATE;

        V_DELIMITER                 VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT              PLS_INTEGER := 0;
        V_MST_LOOP_CNT              PLS_INTEGER := 0;

        V_ACTIVE_FLAG               VARCHAR2(4000 CHAR);
        V_DIVISION_ID               VARCHAR2(4000 CHAR);
        V_CONFIRM_ID                VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY              VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE             VARCHAR2(4000 CHAR);
        V_BOD_SHIPMENT_DATE         VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID                VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS             VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY              VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY             VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY            VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY               VARCHAR2(4000 CHAR);
        V_REMARKS                   VARCHAR2(4000 CHAR);
        V_REMARKS2                  VARCHAR2(4000 CHAR);
        V_REMARKS3                  VARCHAR2(4000 CHAR);
        V_CHECK_NEED_YN             VARCHAR2(4000 CHAR);
        V_EDIT_MAIN                 VARCHAR2(4000 CHAR);
        V_CREATE_DATE               DATE := SYSDATE;
        V_BEFORE_QTY                NUMBER;         /* AS-IS INT */
        V_QTY                       NUMBER;         /* AS-IS INT */

        N_DIVISION_ID               SSP_ANL_SHIP_CONFIRM.DIVISION_ID%TYPE;
        N_ITEM_ID                   SSP_ANL_SHIP_CONFIRM.ITEM_ID%TYPE;
        N_FROM_SITE                 SSP_ANL_SHIP_CONFIRM.FROM_SITE%TYPE;
        N_TO_SITE                   SSP_ANL_SHIP_CONFIRM.TO_SITE%TYPE;
        N_YYYYMMDD                  SSP_ANL_SHIP_CONFIRM.YYYYMMDD%TYPE;
        N_BOD_ID                    SSP_ANL_SHIP_CONFIRM.BOD_ID%TYPE;
        N_PROJECT_CODE              SSP_ANL_SHIP_CONFIRM.PROJECT_CODE%TYPE;
        N_FCST_TYPE                 SSP_ANL_SHIP_CONFIRM.FCST_TYPE%TYPE;
        N_INCOTERMS                 SSP_ANL_SHIP_CONFIRM.INCOTERMS%TYPE;
        N_TRANSPORT_MODE            SSP_ANL_SHIP_CONFIRM.TRANSPORT_MODE%TYPE;
        N_CONFIRM_ID                SSP_ANL_SHIP_CONFIRM.CONFIRM_ID%TYPE;
        V_PLAN_START_YYYYMMDD       VARCHAR2(4000 CHAR);
        V_SEQ                       NUMBER;
        V_CHK                       PLS_INTEGER := 0;
        V_CHK_REQ                   PLS_INTEGER := 0;

        N_ORI_DIVISION_ID           SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.DIVISION_ID%TYPE;
        N_ORI_ITEM_ID               SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.ITEM_ID%TYPE;
        N_ORI_FROM_SITE             SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.FROM_SITE%TYPE;
        N_ORI_TO_SITE               SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.TO_SITE%TYPE;
        N_ORI_YYYYMMDD              SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.YYYYMMDD%TYPE;
        N_ORI_BOD_ID                SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.BOD_ID%TYPE;
        N_ORI_PROJECT_CODE          SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.PROJECT_CODE%TYPE;
        N_ORI_FCST_TYPE             SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.FCST_TYPE%TYPE;
        N_ORI_INCOTERMS             SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.INCOTERMS%TYPE;
        N_ORI_TRANSPORT_MODE        SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.TRANSPORT_MODE%TYPE;
        N_ORI_CONFIRM_ID            SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.CONFIRM_ID%TYPE;
        V_CHANGE_REQ_NO             SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE.CHANGE_REQ_NO%TYPE;

        V_DIVISION_ID_TEMP          SCP_MST_BOD_N_V.DIVISION_ID%TYPE;
        V_NEW_BOD_ID_TEMP           SCP_MST_BOD_N_V.BOD_ID%TYPE;
        V_FROM_SITE_TEMP            SCP_MST_BOD_N_V.FROM_SITE%TYPE;
        V_TO_SITE_TEMP              SCP_MST_BOD_N_V.TO_SITE%TYPE;
        V_ITEM_ID_TEMP              SSP_ANL_SHIP_CONFIRM.ITEM_ID%TYPE;
        V_NEW_INCOTERMS_TEMP        SCP_MST_BOD_N_V.SSP_INCOTERMS%TYPE;
        V_NEW_TRANSPORT_MODE_TEMP   SCP_MST_BOD_N_V.TRANSPORT_MODE%TYPE;
        V_NEW_ROUTE_ID_TEMP         SCP_MST_BOD_N_V.ROUTE_ID%TYPE;
        V_NEW_D_CONTRY_TEMP         SCP_MST_BOD_N_V.D_COUNTRY%TYPE;
        V_NEW_D_PORT_CODE_TEMP      SCP_MST_BOD_N_V.D_PORT_CODE%TYPE;
        V_NEW_A_COUNTRY_TEMP        SCP_MST_BOD_N_V.A_COUNTRY%TYPE;
        V_NEW_A_PORT_CODE_TEMP      SCP_MST_BOD_N_V.A_PORT_CODE%TYPE;
        V_NEW_CUSTOMER_LT_TEMP      SCP_MST_BOD_N_V.LT_TOTAL%TYPE;
        V_NEW_TO_COUNTRY_TEMP       SCP_MST_BOD_N_V.TO_COUNTRY%TYPE;
        V_NEW_TO_CITY_TEMP          SCP_MST_BOD_N_V.TO_CITY%TYPE;

        V_NEW_CONFIRM_ID            VARCHAR2(4000 CHAR);
        V_INFSEQNO                  VARCHAR2(14 CHAR);
        V_LAST_CONFIRM_DATE         VARCHAR2(8 CHAR);
        V_TMP_FN_TIME_ZONE          VARCHAR2(8 CHAR);

        V_MAX_REQ_NO                VARCHAR2(40 CHAR);
        V_USER_DEPT_ID              VARCHAR2(50 CHAR);

        V_ELECTRODE_YN              SSP_ANL_SHIP_CONFIRM.ELECTRODE_YN%TYPE;
        V_ELECTRODE_TYPE            SSP_ANL_SHIP_CONFIRM.ELECTRODE_TYPE%TYPE;
        V_ORIGIN_FROM_DIVISION_ID   SSP_ANL_SHIP_CONFIRM.ORIGIN_FROM_DIVISION_ID%TYPE;
        V_ORIGION_TO_DIVISION_ID    SSP_ANL_SHIP_CONFIRM.ORIGIN_TO_DIVISION_ID%TYPE;

        /*//메일관련 변수////////////////////////////////*/
        V_GRP_CHANGE_REQ            VARCHAR2(20 CHAR);
        V_MAIL_FLAG                 PLS_INTEGER := 0;
        V_MAIL_CHK                  PLS_INTEGER := 0;

        V_ERR_CODE                  NUMBER;
        V_ERR_MESSAGE               VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_CONFIRM_40;

        V_GRP_CHANGE_REQ := 'G' || TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF3');

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        DELETE FROM GT_SSP0015_40_STD;

        /* SSP_ANL_SHIP_PLAN_40 의 데이터 생성 시점이 달라 최신 생성 날짜를 조회한다. */
        INSERT INTO GT_SSP0015_40_STD         /* 기준 데이터 저장 */
               (DIVISION_ID
              , FROM_SITE
              , PLAN_START_YYYYMMDD
              , COMPANY_ID)
        SELECT DISTINCT
               IA.DIVISION_ID
             , IA.FROM_SITE
             , IA.PLAN_START_YYYYMMDD
             , B.COMPANY_ID
          FROM (SELECT SP.DIVISION_ID
                     , SP.FROM_SITE
                     , SP.PLAN_START_YYYYMMDD
                     , RANK() OVER(PARTITION BY SP.FROM_SITE ORDER BY SP.PLAN_START_YYYYMMDD DESC) AS RNK
                  FROM SSP_ANL_SHIP_PLAN_40 SP
                 WHERE SP.DIVISION_ID          = '40'
                   AND SP.PLAN_START_YYYYMMDD >= TO_CHAR(SYSDATE - 3, 'YYYYMMDD')  /* 전일 */
                   AND SP.PLAN_START_YYYYMMDD <= TO_CHAR(SYSDATE, 'YYYYMMDD')      /* 당일 */
                   AND SP.QTY                  > 0) IA
             , SCM_MST_SITE B
         WHERE B.DIVISION_ID = IA.DIVISION_ID
           AND B.SCM_SITE_ID = IA.FROM_SITE
           AND IA.RNK        = 1;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            /* @mst_loop_cnt 1증가 */
            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG        := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,        V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID        := SCM_ARR_SPL_VAL(P_DIVISION_ID,        V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID         := SCM_ARR_SPL_VAL(P_CONFIRM_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY       := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY,       V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE      := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID         := SCM_ARR_SPL_VAL(P_NEW_BOD_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE       := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE       := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID       := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS      := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY       := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE    := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY      := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE    := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT    := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY     := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY,     V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY        := SCM_ARR_SPL_VAL(P_NEW_TO_CITY,        V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS            := SCM_ARR_SPL_VAL(P_REMARKS,            V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2           := SCM_ARR_SPL_VAL(P_REMARKS2,           V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3           := SCM_ARR_SPL_VAL(P_REMARKS3,           V_DELIMITER, V_MST_LOOP_CNT);
            V_CHECK_NEED_YN      := SCM_ARR_SPL_VAL(P_CHECK_NEED_YN,      V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN          := SCM_ARR_SPL_VAL(P_EDIT_MAIN,          V_DELIMITER, V_MST_LOOP_CNT);

            /* 출하확정 행이 없으면 앞 행 값 유지(AS-IS 변수 대입 SELECT 동일) */
            BEGIN
                SELECT FROM_SITE
                     , TO_SITE
                     , ITEM_ID
                  INTO V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_ITEM_ID_TEMP
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            /* AS-IS 는 BOD 적용일 비교에 변환 전 출하일('YYYY-MM-DD HH:MI:SS.FFF')을 그대로 쓴다.
               AS-IS 정렬 규칙(Latin1_General_CI_AS)은 하이픈을 무시하므로 하이픈만 뺀 값으로 비교한다.
               (결과 : 적용 시작일 <= 출하일, 적용 종료일 > 출하일 — 종료일 당일 출하는 BOD 없음) */
            V_BOD_SHIPMENT_DATE := REPLACE(V_SHIPMENT_DATE, '-', '');

            /* BOD 가 없으면 앞 행 값 유지(AS-IS 변수 대입 SELECT TOP 1 동일) */
            BEGIN
                SELECT XA.DIVISION_ID
                     , XA.BOD_ID
                     , XA.FROM_SITE
                     , XA.TO_SITE
                     , XA.SSP_INCOTERMS
                     , XA.TRANSPORT_MODE
                     , XA.ROUTE_ID
                     , XA.D_COUNTRY
                     , XA.D_PORT_CODE
                     , XA.A_COUNTRY
                     , XA.A_PORT_CODE
                     , XA.LT_TOTAL
                     , XA.TO_COUNTRY
                     , XA.TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT
                                       B.DIVISION_ID
                                     , B.BOD_ID
                                     , B.FROM_SITE
                                     , B.TO_SITE
                                     , B.SSP_INCOTERMS
                                     , B.TRANSPORT_MODE
                                     , B.ROUTE_ID
                                     , B.D_COUNTRY
                                     , B.D_PORT_CODE
                                     , B.A_COUNTRY
                                     , B.A_PORT_CODE
                                     , B.LT_TOTAL
                                     , B.LT_TOTAL_ORIGIN
                                     , B.TO_COUNTRY
                                     , B.TO_CITY
                                     , B.PRIORITY
                                     , B.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V B
                                 WHERE B.BOD_VALID_YN        = 'Y'
                                   AND B.DIVISION_ID         = V_DIVISION_ID
                                   AND B.FROM_SITE           = V_FROM_SITE_TEMP
                                   AND B.TO_SITE             = V_TO_SITE_TEMP
                                   AND UPPER(B.TRANSPORT_MODE) = UPPER(V_NEW_TRANSPORT_MODE)
                                   AND UPPER(B.SSP_INCOTERMS)  = UPPER(V_NEW_INCOTERMS)
                                   AND B.FROM_YYYYMMDD      <= V_BOD_SHIPMENT_DATE
                                   AND B.TO_YYYYMMDD        >= V_BOD_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT
                                       DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID     = V_ITEM_ID_TEMP) IB
                         WHERE IB.DIVISION_ID = IA.DIVISION_ID
                           AND IB.BOD_ID      = IA.BOD_ID
                         ORDER BY IA.PRIORITY NULLS FIRST
                                , IA.BOD_ID) XA
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            IF (   V_DIVISION_ID_TEMP        IS NULL
                OR V_NEW_BOD_ID_TEMP         IS NULL
                OR V_FROM_SITE_TEMP          IS NULL
                OR V_TO_SITE_TEMP            IS NULL
                OR V_NEW_INCOTERMS_TEMP      IS NULL
                OR V_NEW_TRANSPORT_MODE_TEMP IS NULL
                OR V_NEW_ROUTE_ID_TEMP       IS NULL
                OR V_NEW_D_CONTRY_TEMP       IS NULL
                OR V_NEW_D_PORT_CODE_TEMP    IS NULL
                OR V_NEW_A_COUNTRY_TEMP      IS NULL
                OR V_NEW_A_PORT_CODE_TEMP    IS NULL
                OR V_NEW_CUSTOMER_LT_TEMP    IS NULL
                OR V_NEW_TO_COUNTRY_TEMP     IS NULL
                OR V_NEW_TO_CITY_TEMP        IS NULL
               ) THEN

                /* 앞 행 저장분까지 되돌린 뒤 결과 반환 */
                ROLLBACK TO SP_SSP0015_SAVE_CONFIRM_40;

                V_LOG_TYPE    := 'FIND';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                V_DESCRIPTION := '';
                D_EVENT_DATE  := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, 0, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                OPEN O_RC1 FOR SELECT 'X' AS RESULT_CODE, NULL AS "Request_no" FROM DUAL;
                OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

                RETURN;

            END IF;

            IF V_ACTIVE_FLAG <> 'I' THEN

                V_QTY        := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT TRUNC(QTY)                 /* AS-IS INT 변수 대입(소수 절삭) */
                         , TRUNC(BEFORE_QTY)
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                /* AS-IS CEILING('') = 0 */
                IF V_QTY <> NVL(CEIL(TO_NUMBER(V_SHIPMENT_QTY)), 0) THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := NULL;
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산*/
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(SUBSTR(V_DIVISION_ID, 1, 30), V_NEW_BOD_ID_TEMP, SUBSTR(V_SHIPMENT_DATE, 1, 8));

                IF V_EDIT_MAIN = 'Y' THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* 2020.06.23 ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정 */
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET YYYYMMDD         = V_SHIPMENT_DATE
                     , QTY              = CEIL(TO_NUMBER(V_SHIPMENT_QTY))
                     , BEFORE_QTY       = V_BEFORE_QTY
                     , BOD_ID           = V_NEW_BOD_ID_TEMP
                     , ROUTE_ID         = V_NEW_ROUTE_ID_TEMP
                     , INCOTERMS        = V_NEW_INCOTERMS_TEMP
                     , D_COUNTRY        = V_NEW_D_CONTRY_TEMP
                     , D_PORT_CODE      = V_NEW_D_PORT_CODE_TEMP
                     , A_COUNTRY        = V_NEW_A_COUNTRY_TEMP
                     , A_PORT_CODE      = V_NEW_A_PORT_CODE_TEMP
                     , TO_COUNTRY       = V_NEW_TO_COUNTRY_TEMP
                     , TO_CITY          = V_NEW_TO_CITY_TEMP
                     , TRANSPORT_MODE   = V_NEW_TRANSPORT_MODE_TEMP
                     , ETD_DATE         = V_SHIPMENT_DATE          /* @v_new_etd_date */
                     , ETA_DATE         = V_NEW_ETA_DATE
                     , FCST_ETD_DATE    = V_SHIPMENT_DATE          /* @v_new_etd_date */
                     , FCST_ETA_DATE    = V_NEW_ETA_DATE
                     , CUSTOMER_LT      = V_NEW_CUSTOMER_LT_TEMP
                     , REMARKS          = V_REMARKS
                     , REMARKS2         = V_REMARKS2
                     , REMARKS3         = V_REMARKS3
                     , CHECK_NEED_YN    = V_CHECK_NEED_YN
                     , LAST_UPDATED_BY  = P_USER_ID
                     , LAST_UPDATE_DATE = V_CREATE_DATE
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;

            /*2020-07-24 KIMYONGHO 신규생성 기능 추가*/
            IF V_ACTIVE_FLAG = 'I' THEN

                V_INFSEQNO := TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_XIF_ERP_IFSEQNO.NEXTVAL), -6);

                /* 확정구간 마지막 일자( 현재일 기준 + 9 = PLANS_START_YYYYMMDD + 10) */
                V_LAST_CONFIRM_DATE := TO_CHAR(SYSDATE + 9, 'YYYYMMDD');

                V_DESCRIPTION := '';
                V_LOG_TYPE    := 'HIST';
                D_EVENT_DATE  := SYSDATE;
                PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                /* NEW CONFIRM 생성 CHECK 확인========================================================================================== */
                V_TMP_FN_TIME_ZONE := TO_CHAR(FN_MULTY_TIME(NULL), 'YYYYMMDD');
                V_NEW_CONFIRM_ID   := 'C' || V_TMP_FN_TIME_ZONE || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL), -6);

                SELECT MAX(PLAN_START_YYYYMMDD)
                     , MAX(PLAN_SEQ)
                  INTO V_PLAN_START_YYYYMMDD
                     , V_SEQ
                  FROM SSP_PLAN_VERSION_V
                 WHERE PLAN_TYPE           = 'SP'
                   AND CONFIRM_FLAG        = 'Y'
                   AND DIVISION_ID         = V_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = (SELECT MAX(PLAN_START_YYYYMMDD)
                                                FROM SSP_PLAN_VERSION_V
                                               WHERE PLAN_TYPE    = 'SP'
                                                 AND CONFIRM_FLAG = 'Y'
                                                 AND DIVISION_ID  = V_DIVISION_ID);

                V_QTY        := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT TRUNC(QTY)                 /* AS-IS INT 변수 대입(소수 절삭) */
                         , TRUNC(BEFORE_QTY)
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                /* AS-IS 는 INT 와 문자열 비교로 수량을 정수로 바꾼다 — 정수가 아니면 AS-IS 처럼 오류 */
                IF V_SHIPMENT_QTY IS NOT NULL
                   AND NOT REGEXP_LIKE(V_SHIPMENT_QTY, '^[[:space:]]*[-+]?[0-9]+[[:space:]]*$') THEN
                    RAISE_APPLICATION_ERROR(-20245, 'Conversion failed when converting the nvarchar value ''' || V_SHIPMENT_QTY || ''' to data type int.');
                END IF;

                IF V_QTY <> NVL(TO_NUMBER(V_SHIPMENT_QTY), 0) THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := NULL;
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산*/
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(SUBSTR(V_DIVISION_ID, 1, 30), V_NEW_BOD_ID_TEMP, SUBSTR(V_SHIPMENT_DATE, 1, 8));

                IF V_EDIT_MAIN = 'Y' THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* -------------------------------------------------------------------------------------------------------------
                   1. SHIP_CONFIRM 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM
                   신규 건만 생성
                   ------------------------------------------------------------------------------------------------------------- */
                INSERT INTO SSP_ANL_SHIP_CONFIRM
                       (CONFIRM_ID
                      , SHIPMENT_STATUS
                      , DIVISION_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , PLANNED_QTY
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , CHANGE_TYPE
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REQUESTOR
                      , BEFORE_QTY
                      , CHECK_NEED_YN
                      , PACKAGE_TYPE_CODE
                      , FACTORY_ID
                      , ELECTRODE_TYPE
                      , PACKAGE_QTY
                      , DOM_EXP
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , ATTRIBUTE10)
                SELECT V_NEW_CONFIRM_ID
                     , 'C'
                     , A.DIVISION_ID
                     , V_PLAN_START_YYYYMMDD
                     , 'SP'
                     , V_SEQ
                     , A.ITEM_ID
                     , A.FROM_SITE
                     , A.TO_SITE
                     , V_SHIPMENT_DATE
                     , 0
                     , TO_NUMBER(V_SHIPMENT_QTY)
                     , V_NEW_BOD_ID_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , A.BIZ_TYPE
                     , A.PROJECT_CODE
                     , A.FCST_TYPE
                     , V_SHIPMENT_DATE
                     , V_NEW_ETA_DATE
                     , V_SHIPMENT_DATE
                     , V_NEW_ETA_DATE
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                     , A.FROM_SITE_TYPE
                     , A.FROM_SITE_PLANT_ID
                     , A.FROM_SITE_VENDOR_ID
                     , A.FROM_SITE_SOLDTO_CODE
                     , A.FROM_SITE_SHIPTO_CODE
                     , A.FROM_SITE_COMPANY_ID
                     , A.TO_SITE_TYPE
                     , A.TO_SITE_PLANT_ID
                     , A.TO_SITE_VENDOR_ID
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , A.TO_SITE_COMPANY_ID
                     , 'C'
                     , P_USER_ID
                     , V_CREATE_DATE
                     , P_USER_ID
                     , V_CREATE_DATE
                     , A.ELECTRODE_YN
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , P_USER_ID
                     , 0
                     , 'Y'
                     , A.PACKAGE_TYPE_CODE
                     , A.FACTORY_ID
                     , A.ELECTRODE_TYPE
                     , CEIL(CASE WHEN B.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.BOX_PER_CUT, 1)
                                 WHEN B.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELCRATE_PER_CUT, 1)
                                 WHEN B.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELRACK_PER_CUT, 1)
                                 ELSE NULL
                            END) AS PACKAGE_QTY
                     , A.DOM_EXP
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , NULL
                  FROM SSP_ANL_SHIP_CONFIRM A
                     , SSP_MST_SITE_ITEM_EE_V B
                 WHERE CASE WHEN A.BIZ_TYPE = 'E' THEN B.DIVISION_ID(+) ELSE B.ASSY_DIVISION_ID(+) END = A.DIVISION_ID
                   AND CASE WHEN A.BIZ_TYPE = 'E' THEN B.SCM_SITE_ID(+) ELSE B.ASSY_SCM_SITE_ID(+) END = A.FROM_SITE
                   AND B.ITEM_ID(+) = A.ITEM_ID
                   AND A.CONFIRM_ID = V_CONFIRM_ID;

                /* -------------------------------------------------------------------------------------------------------------
                   2. SHIP_CONFIRM HISTORY 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM_H
                   신규 건만 생성
                   ------------------------------------------------------------------------------------------------------------- */
                INSERT INTO SSP_ANL_SHIP_CONFIRM_H
                       (HISTORY_SEQ
                      , CONFIRM_ID
                      , CHANGE_TYPE
                      , SHIPMENT_STATUS
                      , DIVISION_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , PLANNED_QTY
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , CHANGE_REQ_NO
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , HISTORY_CREATION_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , BEFORE_QTY
                      , REMARKS
                      , CHECK_NEED_YN)
                SELECT SEQ1_SSP_ANL_SHIP_CONFIRM_H.NEXTVAL   /* HISTORY_SEQ */
                     , CONFIRM_ID
                     , CHANGE_TYPE
                     , SHIPMENT_STATUS
                     , DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , SEQ
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , PLANNED_QTY
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , NULL              /* CHANGE_REQ_NO */
                     , NULL              /* ERP_SO_NO */
                     , NULL              /* ERP_SO_ITEM_NO */
                     , NULL              /* ERP_DO_NO */
                     , NULL              /* ERP_STATUS */
                     , P_USER_ID         /* CREATED_BY */
                     , V_CREATE_DATE     /* CREATION_DATE */
                     , P_USER_ID         /* LAST_UPDATED_BY */
                     , V_CREATE_DATE     /* LAST_UPDATE_DATE */
                     , V_CREATE_DATE     /* HISTORY_CREATION_DATE */
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , BEFORE_QTY
                     , REMARKS
                     , CHECK_NEED_YN
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE 1 = 1
                   AND CONFIRM_ID = V_NEW_CONFIRM_ID;

                INSERT INTO XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
                       (IFSEQNO
                      , CONFIRM_ID
                      , SHIPMENT_STATUS
                      , LAST_CONFIRM_DATE
                      , VERSION_TYPE
                      , SALES_COMPANY_ID
                      , DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , OPERATION_GROUP
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , INCOTERMS2
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , BUILDING
                      , REMARK
                      , CUSTOMER_REQ
                      , CHANGE_CODE
                      , CHANGE_CODE_NAME
                      , REQUESTOR
                      , TRANSFER_FLAG
                      , TRANSFER_DATE
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ATTRIBUTE1
                      , ATTRIBUTE2
                      , ATTRIBUTE3
                      , ATTRIBUTE4
                      , ATTRIBUTE5
                      , ATTRIBUTE6
                      , ATTRIBUTE7
                      , ATTRIBUTE8
                      , ATTRIBUTE9
                      , ATTRIBUTE10
                      /*----------------------------------------------------------------------------------------
                          2020.06.30 : KBK
                          I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                      ------------------------------------------------------------------------------------------*/
                      , PACKAGE_TYPE
                      , FACTORY_ID
                      , PACKAGE_QTY
                      , DOM_EXP
                      , ERP_ATTR1
                      , ERP_ATTR2
                      , ERP_ATTR3
                      , ERP_ATTR4
                      , ERP_ATTR5)
                SELECT IA.IFSEQNO
                     , IA.CONFIRM_ID
                     , IA.SHIPMENT_STATUS
                     , IA.LAST_CONFIRM_DATE
                     , IA.VERSION_TYPE
                     , NVL(E.NEW_VALUE1, IA.SALES_COMPANY_ID)         AS SALES_COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.ITEM_ID
                     , NVL(F.NEW_VALUE1, IA.FROM_SITE)                AS FROM_SITE
                     , NVL(G.NEW_VALUE1, IA.TO_SITE)                  AS TO_SITE
                     , IA.YYYYMMDD
                     , IA.QTY
                     , IA.BOD_ID
                     , IA.ROUTE_ID
                     , IA.OPERATION_GROUP
                     , IA.BIZ_TYPE
                     , IA.PROJECT_CODE
                     , IA.FCST_TYPE
                     , IA.FCST_ETD_DATE
                     , IA.FCST_ETA_DATE
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.INCOTERMS
                     , IA.INCOTERMS2
                     , IA.TRANSPORT_MODE
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.CUSTOMER_LT
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                     , IA.FROM_SITE_TYPE
                     , NVL(H.NEW_VALUE1, IA.FROM_SITE_PLANT_ID)       AS FROM_SITE_PLANT_ID
                     , NVL(I.NEW_VALUE1, IA.FROM_SITE_VENDOR_ID)      AS FROM_SITE_VENDOR_ID
                     , NVL(J.NEW_VALUE1, IA.FROM_SITE_SOLDTO_CODE)    AS FROM_SITE_SOLDTO_CODE
                     , NVL(K.NEW_VALUE1, IA.FROM_SITE_SHIPTO_CODE)    AS FROM_SITE_SHIPTO_CODE
                     , NVL(L.NEW_VALUE1, IA.FROM_SITE_COMPANY_ID)     AS FROM_SITE_COMPANY_ID
                     , IA.TO_SITE_TYPE
                     , NVL(M.NEW_VALUE1, IA.TO_SITE_PLANT_ID)         AS TO_SITE_PLANT_ID
                     , NVL(N.NEW_VALUE1, IA.TO_SITE_VENDOR_ID)        AS TO_SITE_VENDOR_ID
                     , NVL(O.NEW_VALUE1, IA.TO_SITE_SOLDTO_CODE)      AS TO_SITE_SOLDTO_CODE
                     , NVL(P.NEW_VALUE1, IA.TO_SITE_SHIPTO_CODE)      AS TO_SITE_SHIPTO_CODE
                     , NVL(Q.NEW_VALUE1, IA.TO_SITE_COMPANY_ID)       AS TO_SITE_COMPANY_ID
                     , IA.BUILDING
                     , IA.REMARK
                     , IA.CUSTOMER_REQ
                     , IA.CHANGE_CODE
                     , IA.CHANGE_CODE_NAME
                     , IA.REQUESTOR
                     , IA.TRANSFER_FLAG
                     , IA.TRANSFER_DATE
                     , IA.CREATED_BY
                     , IA.CREATION_DATE
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                     , IA.ATTRIBUTE1
                     , IA.ATTRIBUTE2
                     , IA.ATTRIBUTE3
                     , IA.ATTRIBUTE4
                     , IA.ATTRIBUTE5
                     , IA.ATTRIBUTE6
                     , IA.ATTRIBUTE7
                     , IA.ATTRIBUTE8
                     , IA.ATTRIBUTE9
                     , IA.ATTRIBUTE10
                     /*----------------------------------------------------------------------------------------
                         2020.06.30 : KBK
                         I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                     ------------------------------------------------------------------------------------------*/
                     , IA.PACKAGE_TYPE_CODE
                     , IA.FACTORY_ID
                     , IA.PACKAGE_QTY
                     , IA.DOM_EXP
                     , NULL                  AS ERP_ATTR1
                     , NULL                  AS ERP_ATTR2
                     , NULL                  AS ERP_ATTR3
                     , IA.TO_SITE_PLANT_ID   AS ERP_ATTR4   /* ERP_ATTR4-- NERP에서 원본 정보 참고용 (2025-04-23) */
                     , NULL                  AS ERP_ATTR5
                  FROM (SELECT IB.IFSEQNO
                             , IB.CONFIRM_ID
                             , IB.SHIPMENT_STATUS
                             , IB.LAST_CONFIRM_DATE
                             , IB.VERSION_TYPE
                             , IB.SALES_COMPANY_ID
                             , IB.DIVISION_ID
                             , IB.ITEM_ID
                             , IB.FROM_SITE
                             , IB.TO_SITE
                             , IB.YYYYMMDD
                             , IB.QTY
                             , IB.BOD_ID
                             , IB.ROUTE_ID
                             , IB.OPERATION_GROUP
                             , IB.BIZ_TYPE
                             , IB.PROJECT_CODE
                             , IB.FCST_TYPE
                             , IB.FCST_ETD_DATE
                             , IB.FCST_ETA_DATE
                             , IB.ETD_DATE
                             , IB.ETA_DATE
                             , IB.INCOTERMS
                             , IB.INCOTERMS2
                             , IB.TRANSPORT_MODE
                             , IB.D_COUNTRY
                             , IB.D_PORT_CODE
                             , IB.A_COUNTRY
                             , IB.A_PORT_CODE
                             , IB.CUSTOMER_LT
                             , IB.TO_COUNTRY
                             , IB.TO_CITY
                             , IB.FROM_SITE_TYPE
                             , IB.FROM_SITE_PLANT_ID
                             , IB.FROM_SITE_VENDOR_ID
                             , IB.FROM_SITE_SOLDTO_CODE
                             , IB.FROM_SITE_SHIPTO_CODE
                             , IB.FROM_SITE_COMPANY_ID
                             , IB.TO_SITE_TYPE
                             , IB.TO_SITE_PLANT_ID
                             , IB.TO_SITE_VENDOR_ID
                             , IB.TO_SITE_SOLDTO_CODE
                             , IB.TO_SITE_SHIPTO_CODE
                             , IB.TO_SITE_COMPANY_ID
                             , IB.BUILDING
                             , IB.REMARK
                             , IB.CUSTOMER_REQ
                             , IB.CHANGE_CODE
                             , IB.CHANGE_CODE_NAME
                             , IB.REQUESTOR
                             , IB.TRANSFER_FLAG
                             , IB.TRANSFER_DATE
                             , IB.CREATED_BY
                             , IB.CREATION_DATE
                             , IB.LAST_UPDATED_BY
                             , IB.LAST_UPDATE_DATE
                             , IB.ATTRIBUTE1
                             , IB.ATTRIBUTE2
                             , IB.ATTRIBUTE3
                             , IB.ATTRIBUTE4
                             , IB.ATTRIBUTE5
                             , IB.ATTRIBUTE6
                             , IB.ATTRIBUTE7
                             , IB.ATTRIBUTE8
                             , IB.ATTRIBUTE9
                             , IB.ATTRIBUTE10
                             /*----------------------------------------------------------------------------------------
                                 2020.06.30 : KBK
                                 I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                             ------------------------------------------------------------------------------------------*/
                             , D.PACKAGE_TYPE_CODE
                             , D.FACTORY_ID
                             , CEIL(CASE WHEN D.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(IB.QTY * NVL(D.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(D.BOX_PER_CUT, 1)
                                         WHEN D.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(IB.QTY * NVL(D.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(D.STEELCRATE_PER_CUT, 1)
                                         WHEN D.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(IB.QTY * NVL(D.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(D.STEELRACK_PER_CUT, 1)
                                         ELSE NVL(IB.QTY, 0)
                                    END)                  AS PACKAGE_QTY
                             , D.DOM_EXP_TYPE             AS DOM_EXP
                          FROM (SELECT V_INFSEQNO                 AS IFSEQNO               /* IFSEQNO */
                                     , A.CONFIRM_ID
                                     , 'A'                        AS SHIPMENT_STATUS       /* I_PLGB  A: 확정 */
                                     , V_LAST_CONFIRM_DATE        AS LAST_CONFIRM_DATE     /* I_DATE  확정구간 마지막 일자 */
                                     , 'B'                        AS VERSION_TYPE          /* B:NEW/A:OLD */
                                     , NVL(C.ATTRIBUTE2, B.ATTRIBUTE2) AS SALES_COMPANY_ID
                                     , CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END AS DIVISION_ID
                                     , A.ITEM_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.YYYYMMDD
                                     , A.QTY
                                     , A.BOD_ID
                                     , A.ROUTE_ID
                                     , A.BIZ_TYPE                 AS OPERATION_GROUP
                                     , A.BIZ_TYPE
                                     , CASE WHEN TRIM(A.PROJECT_CODE) IS NULL OR A.PROJECT_CODE = '-' THEN 'TBD' ELSE A.PROJECT_CODE END AS PROJECT_CODE
                                     , A.FCST_TYPE
                                     , A.FCST_ETD_DATE
                                     , A.FCST_ETA_DATE
                                     , A.ETD_DATE
                                     , A.ETA_DATE
                                     , A.INCOTERMS
                                     , NULL                       AS INCOTERMS2
                                     , A.TRANSPORT_MODE
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.CUSTOMER_LT
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.FROM_SITE_TYPE
                                     , A.FROM_SITE_PLANT_ID
                                     , A.FROM_SITE_VENDOR_ID
                                     , A.FROM_SITE_SOLDTO_CODE
                                     , A.FROM_SITE_SHIPTO_CODE
                                     , A.FROM_SITE_COMPANY_ID
                                     , A.TO_SITE_TYPE
                                     , A.TO_SITE_PLANT_ID
                                     , A.TO_SITE_VENDOR_ID
                                     , A.TO_SITE_SOLDTO_CODE
                                     , A.TO_SITE_SHIPTO_CODE
                                     , A.TO_SITE_COMPANY_ID
                                     , A.REMARKS2                 AS BUILDING
                                     , A.REMARKS                  AS REMARK
                                     , A.REMARKS3                 AS CUSTOMER_REQ
                                     , NULL                       AS CHANGE_CODE
                                     , NULL                       AS CHANGE_CODE_NAME
                                     , A.REQUESTOR
                                     , 'N'                        AS TRANSFER_FLAG
                                     , SYSDATE                    AS TRANSFER_DATE
                                     , A.LAST_UPDATED_BY          AS CREATED_BY
                                     , SYSDATE                    AS CREATION_DATE
                                     , A.LAST_UPDATED_BY
                                     , SYSDATE                    AS LAST_UPDATE_DATE
                                     , NULL                       AS ATTRIBUTE1
                                     , NULL                       AS ATTRIBUTE2
                                     , NULL                       AS ATTRIBUTE3
                                     , NULL                       AS ATTRIBUTE4
                                     , NULL                       AS ATTRIBUTE5
                                     , NULL                       AS ATTRIBUTE6
                                     , NULL                       AS ATTRIBUTE7
                                     , NULL                       AS ATTRIBUTE8
                                     , NULL                       AS ATTRIBUTE9
                                     , A.ELECTRODE_YN             AS ATTRIBUTE10
                                  FROM SSP_ANL_SHIP_CONFIRM A
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL B
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL C
                                 WHERE B.SEGMENT1(+)    = A.FROM_SITE_COMPANY_ID
                                   AND B.SEGMENT3(+)    = A.FROM_SITE
                                   AND B.SEGMENT4(+)    = A.TO_SITE_COMPANY_ID
                                   AND B.SEGMENT5(+)    = A.TO_SITE
                                   AND C.SEGMENT1(+)    = A.FROM_SITE_COMPANY_ID
                                   AND C.SEGMENT3(+)    = A.FROM_SITE
                                   AND C.SEGMENT4(+)    = A.TO_SITE_COMPANY_ID
                                   AND C.ATTRIBUTE1(+)  = A.TO_SITE
                                   AND B.LOOKUP_TYPE(+) = 'CELL_SHIP_FROM_TO'
                                   AND B.VALID_YN(+)    = 'Y'
                                   AND C.LOOKUP_TYPE(+) = 'ELECTRODE_SHIP_FROM_TO'
                                   AND C.VALID_YN(+)    = 'Y'
                                   AND NVL(A.QTY, 0)   <> 0                  /* 0은IF 제외 */
                                   AND A.CONFIRM_ID     = V_NEW_CONFIRM_ID) IB
                             , SSP_MST_SITE_ITEM_EE_V D
                         WHERE CASE WHEN IB.BIZ_TYPE = 'E' THEN D.DIVISION_ID(+) ELSE D.ASSY_DIVISION_ID(+) END = IB.DIVISION_ID
                           AND CASE WHEN IB.BIZ_TYPE = 'E' THEN D.SCM_SITE_ID(+) ELSE D.ASSY_SCM_SITE_ID(+) END = IB.FROM_SITE
                           AND D.ITEM_ID(+) = IB.ITEM_ID) IA
                     , NERP_CONV_MASTER E
                     , NERP_CONV_MASTER F
                     , NERP_CONV_MASTER G
                     , NERP_CONV_MASTER H
                     , NERP_CONV_MASTER I
                     , NERP_CONV_MASTER J
                     , NERP_CONV_MASTER K
                     , NERP_CONV_MASTER L
                     , NERP_CONV_MASTER M
                     , NERP_CONV_MASTER N
                     , NERP_CONV_MASTER O
                     , NERP_CONV_MASTER P
                     , NERP_CONV_MASTER Q
                 WHERE E.OLD_VALUE1(+) = IA.SALES_COMPANY_ID
                   AND F.OLD_VALUE1(+) = IA.FROM_SITE
                   AND G.OLD_VALUE1(+) = IA.TO_SITE
                   AND H.OLD_VALUE1(+) = IA.FROM_SITE_PLANT_ID
                   AND I.OLD_VALUE1(+) = IA.FROM_SITE_VENDOR_ID
                   AND J.OLD_VALUE1(+) = IA.FROM_SITE_SOLDTO_CODE
                   AND K.OLD_VALUE1(+) = IA.FROM_SITE_SHIPTO_CODE
                   AND L.OLD_VALUE1(+) = IA.FROM_SITE_COMPANY_ID
                   AND M.OLD_VALUE1(+) = IA.TO_SITE_PLANT_ID
                   AND N.OLD_VALUE1(+) = IA.TO_SITE_VENDOR_ID
                   AND O.OLD_VALUE1(+) = IA.TO_SITE_SOLDTO_CODE
                   AND P.OLD_VALUE1(+) = IA.TO_SITE_SHIPTO_CODE
                   AND Q.OLD_VALUE1(+) = IA.TO_SITE_COMPANY_ID
                   AND E.CODETYPE(+)   = 'COMPANY_ID'
                   AND F.CODETYPE(+)   = 'SCP_SITE_ID'
                   AND G.CODETYPE(+)   = 'SCP_SITE_ID'
                   AND H.CODETYPE(+)   = 'PLANT_ID'
                   AND I.CODETYPE(+)   = 'VENDOR_ID'
                   AND J.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND K.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND L.CODETYPE(+)   = 'COMPANY_ID'
                   AND M.CODETYPE(+)   = 'PLANT_ID'
                   AND N.CODETYPE(+)   = 'VENDOR_ID'
                   AND O.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND P.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND Q.CODETYPE(+)   = 'COMPANY_ID';

                /* MKT FCST - SSP Sync 신규 생성 건 대상
                   ※ PR_DM_SSP_CONFIRM_SYNC 는 Oracle 미이관(2026.09.17) — 이관 후 아래 호출 연결
                   PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, V_NEW_CONFIRM_ID); */

                V_CONFIRM_ID := V_NEW_CONFIRM_ID;

                /* 240610 jilee 신규 건 Change Req 정보 입력 */
                IF V_CHK_REQ = 0 THEN

                    V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6);

                    /* 사용자 행이 없으면 앞 값 유지 · 여러 행이면 AS-IS 처럼 한 값 */
                    BEGIN
                        SELECT DEPT_ID
                          INTO V_USER_DEPT_ID
                          /* 2026.09.30 AJS 수정 (START) */
--                          FROM TB_FX_USER
--                         WHERE UPPER(USERID) = UPPER(P_USER_ID)
                          FROM SCM_ADM_USER_M
                         WHERE UPPER(USER_ID) = UPPER(P_USER_ID)
                          /* 2026.09.30 AJS 수정 (END) */
                           AND ROWNUM        = 1;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;

                    BEGIN
                        SELECT ELECTRODE_YN
                             , ELECTRODE_TYPE
                             , ORIGIN_FROM_DIVISION_ID
                             , ORIGIN_TO_DIVISION_ID
                          INTO V_ELECTRODE_YN
                             , V_ELECTRODE_TYPE
                             , V_ORIGIN_FROM_DIVISION_ID
                             , V_ORIGION_TO_DIVISION_ID
                          FROM SSP_ANL_SHIP_CONFIRM
                         WHERE CONFIRM_ID = V_CONFIRM_ID;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                           (CHANGE_REQ_NO
                          , CHANGE_TYPE
                          , CHANGE_REQ_STATUS
                          , DIVISION_ID
                          , FROM_SITE
                          , REQUEST_TITLE
                          , REQUEST_USER
                          , REQUEST_DEPT
                          , REQUEST_TIME
                          , APPROVAL_USER
                          , APPROVAL_DEPT
                          , APPROVAL_TIME
                          , CHANGE_REASON_CODE
                          , CHANGE_REASON_DETAIL
                          , REJECT_REASON
                          , VALID_YN
                          , CREATED_BY
                          , CREATION_DATE
                          , LAST_UPDATED_BY
                          , LAST_UPDATE_DATE
                          , ELECTRODE_YN
                          , ELECTRODE_TYPE
                          , ORIGIN_FROM_DIVISION_ID
                          , ORIGIN_TO_DIVISION_ID)
                    VALUES (V_MAX_REQ_NO
                          , 'A'
                          , 'A'
                          , V_DIVISION_ID
                          , V_FROM_SITE_TEMP
                          , 'New Adjustment'
                          , P_USER_ID
                          , V_USER_DEPT_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , V_USER_DEPT_ID
                          , V_CREATE_DATE
                          , 'T07'
                          , 'T07'
                          , NULL
                          , 'Y'
                          , P_USER_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , V_CREATE_DATE
                          , V_ELECTRODE_YN
                          , V_ELECTRODE_TYPE
                          , V_ORIGIN_FROM_DIVISION_ID
                          , V_ORIGION_TO_DIVISION_ID);

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK_REQ := 1;

                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := NULL;
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅*/
                IF     RTRIM(V_SHIPMENT_DATE) IS NOT NULL
                   AND LENGTH(RTRIM(V_SHIPMENT_DATE)) = 8
                   AND RTRIM(V_NEW_CUSTOMER_LT) IS NOT NULL
                   AND LENGTH(RTRIM(V_NEW_CUSTOMER_LT)) > 0 THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산
                   ※ AS-IS 는 여기서만 전체 인자 @p_division_id 를 넘긴다(함수 인자 NVARCHAR(30) 로 잘림) */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(SUBSTR(P_DIVISION_ID, 1, 30), V_NEW_BOD_ID_TEMP, SUBSTR(V_SHIPMENT_DATE, 1, 8));

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                       (CHANGE_REQ_NO
                      , CONFIRM_ID
                      , NEW_YN
                      , DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , NEW_YYYYMMDD
                      , NEW_QTY
                      , NEW_BOD_ID
                      , NEW_ROUTE_ID
                      , NEW_ETD_DATE
                      , NEW_ETA_DATE
                      , NEW_INCOTERMS
                      , NEW_TRANSPORT_MODE
                      , NEW_D_COUNTRY
                      , NEW_D_PORT_CODE
                      , NEW_A_COUNTRY
                      , NEW_A_PORT_CODE
                      , NEW_CUSTOMER_LT
                      , NEW_TO_COUNTRY
                      , NEW_TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , VALID_YN
                      , ATTRIBUTE1
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , REQUESTOR
                      , ATTRIBUTE2)
                SELECT V_MAX_REQ_NO                   AS CHANGE_REQ_NO
                     , CONFIRM_ID
                     , 'Y'                            AS NEW_YN
                     , DIVISION_ID
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , V_SHIPMENT_DATE                AS NEW_YYYYMMDD
                     , TO_NUMBER(V_SHIPMENT_QTY)      AS NEW_QTY
                     , V_NEW_BOD_ID_TEMP              AS NEW_BOD_ID
                     , V_NEW_ROUTE_ID_TEMP            AS NEW_ROUTE_ID
                     , V_NEW_ETD_DATE                 AS NEW_ETD_DATE
                     , V_NEW_ETA_DATE                 AS NEW_ETA_DATE
                     , V_NEW_INCOTERMS                AS NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE           AS NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY                 AS NEW_D_COUNTRY
                     , V_NEW_D_PORT_CODE_TEMP         AS NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY_TEMP           AS NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE_TEMP         AS NEW_A_PORT_CODE
                     , V_NEW_CUSTOMER_LT_TEMP         AS NEW_CUSTOMER_LT
                     , V_NEW_TO_COUNTRY_TEMP          AS NEW_TO_COUNTRY
                     , V_NEW_TO_CITY_TEMP             AS NEW_TO_CITY
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , ERP_SO_NO
                     , ERP_SO_ITEM_NO
                     , ERP_DO_NO
                     , ERP_STATUS
                     , 'Y'
                     , 'N'
                     , P_USER_ID                      AS CREATED_BY
                     , V_CREATE_DATE
                     , P_USER_ID                      AS LAST_UPDATED_BY
                     , V_CREATE_DATE
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , REQUESTOR
                     , 'A'
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF; /* @v_active_flag = 'I' END */

            IF V_EDIT_MAIN = 'Y' THEN

                BEGIN
                    SELECT DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE
                         , YYYYMMDD
                         , BOD_ID
                         , PROJECT_CODE
                         , FCST_TYPE
                         , INCOTERMS
                         , TRANSPORT_MODE
                         , CONFIRM_ID
                      INTO N_DIVISION_ID
                         , N_ITEM_ID
                         , N_FROM_SITE
                         , N_TO_SITE
                         , N_YYYYMMDD
                         , N_BOD_ID
                         , N_PROJECT_CODE
                         , N_FCST_TYPE
                         , N_INCOTERMS
                         , N_TRANSPORT_MODE
                         , N_CONFIRM_ID
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                /* SSP_ANL_SHIP_PLAN_40 의 데이터 생성 시점이 달라 최신 생성 날짜를 조회한다. */
                SELECT MAX(PLAN_START_YYYYMMDD)
                  INTO V_PLAN_START_YYYYMMDD
                  FROM GT_SSP0015_40_STD
                 WHERE 1 = 1
                   AND DIVISION_ID = N_DIVISION_ID
                   AND FROM_SITE   = N_FROM_SITE;

                V_SEQ := 1;

                /* 220905 jilee FromSite 제외하고 다시 조회 */
                IF V_PLAN_START_YYYYMMDD IS NULL THEN

                    SELECT MAX(PLAN_START_YYYYMMDD)
                      INTO V_PLAN_START_YYYYMMDD
                      FROM GT_SSP0015_40_STD
                     WHERE COMPANY_ID IN (SELECT COMPANY_ID
                                            FROM SCM_MST_SITE
                                           WHERE 1 = 1
                                             AND DIVISION_ID = N_DIVISION_ID
                                             AND SCM_SITE_ID = N_FROM_SITE)
                       AND DIVISION_ID = N_DIVISION_ID;

                    V_SEQ := 1;

                END IF;

                /* SSP_ANL_SHIP_PLAN_40 MEASURE SHIP_CONFIRM 이 있을 경우 Delete, Insert
                   ※ AS-IS 는 건수(COUNT) 확인 후 삭제 — 삭제 대상이 없으면 0건 삭제와 같으므로 바로 삭제한다. */
                DELETE FROM SSP_ANL_SHIP_PLAN_40
                 WHERE PLAN_TYPE           = 'SP'
                   AND MEASURE             = 'SHIP_CONFIRM'
                   AND CONFIRM_FLAG        = 'Y'
                   AND DIVISION_ID         = N_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND SEQ                 = V_SEQ
                   AND ITEM_ID             = N_ITEM_ID
                   AND FROM_SITE           = N_FROM_SITE
                   AND TO_SITE             = N_TO_SITE
                   AND YYYYMMDD            = N_YYYYMMDD;

                /* 변경요청 상세가 없으면 앞 값 유지(AS-IS 변수 대입 SELECT TOP 1 동일)
                   ※ 수정일시 동률(Oracle DATE 는 밀리초 절삭)은 요청번호 역순으로 고정 */
                BEGIN
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.FROM_SITE
                         , XA.TO_SITE
                         , XA.YYYYMMDD
                         , XA.BOD_ID
                         , XA.PROJECT_CODE
                         , XA.FCST_TYPE
                         , XA.INCOTERMS
                         , XA.TRANSPORT_MODE
                         , XA.CONFIRM_ID
                         , XA.CHANGE_REQ_NO
                      INTO N_ORI_DIVISION_ID
                         , N_ORI_ITEM_ID
                         , N_ORI_FROM_SITE
                         , N_ORI_TO_SITE
                         , N_ORI_YYYYMMDD
                         , N_ORI_BOD_ID
                         , N_ORI_PROJECT_CODE
                         , N_ORI_FCST_TYPE
                         , N_ORI_INCOTERMS
                         , N_ORI_TRANSPORT_MODE
                         , N_ORI_CONFIRM_ID
                         , V_CHANGE_REQ_NO
                      FROM (SELECT DIVISION_ID
                                 , ITEM_ID
                                 , FROM_SITE
                                 , TO_SITE
                                 , YYYYMMDD
                                 , BOD_ID
                                 , PROJECT_CODE
                                 , FCST_TYPE
                                 , INCOTERMS
                                 , TRANSPORT_MODE
                                 , CONFIRM_ID
                                 , CHANGE_REQ_NO
                              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                             WHERE VALID_YN   = 'Y'
                               AND CONFIRM_ID = V_CONFIRM_ID
                             ORDER BY LAST_UPDATE_DATE DESC
                                    , CHANGE_REQ_NO DESC) XA
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                V_CHK := 0;

                SELECT COUNT(*)
                  INTO V_CHK
                  FROM SSP_ANL_SHIP_PLAN_40
                 WHERE PLAN_TYPE           = 'SP'
                   AND MEASURE             = 'SHIP_CONFIRM'
                   AND CONFIRM_FLAG        = 'Y'       /* Confrim ID가 없는건 삭제하지 않음 */
                   AND DIVISION_ID         = N_ORI_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND SEQ                 = V_SEQ
                   AND ITEM_ID             = N_ORI_ITEM_ID
                   AND FROM_SITE           = N_ORI_FROM_SITE
                   AND TO_SITE             = N_ORI_TO_SITE
                   AND YYYYMMDD            = N_ORI_YYYYMMDD
                   AND ROWNUM              = 1;

                IF V_CHK > 0 AND N_YYYYMMDD <> N_ORI_YYYYMMDD THEN

                    DELETE FROM SSP_ANL_SHIP_PLAN_40
                     WHERE PLAN_TYPE           = 'SP'
                       AND MEASURE             = 'SHIP_CONFIRM'
                       AND CONFIRM_FLAG        = 'Y'   /* Confrim ID가 없는건 삭제하지 않음 */
                       AND DIVISION_ID         = N_ORI_DIVISION_ID
                       AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND SEQ                 = V_SEQ
                       AND ITEM_ID             = N_ORI_ITEM_ID
                       AND FROM_SITE           = N_ORI_FROM_SITE
                       AND TO_SITE             = N_ORI_TO_SITE
                       AND YYYYMMDD            = N_ORI_YYYYMMDD;

                    /* AS-IS 의 CONFIRM_ID IN (같은 테이블 같은 조건) 은 같은 조건의 직접 조회와 같다 */
                    INSERT INTO SSP_ANL_SHIP_PLAN_40
                           (DIVISION_ID
                          , PLAN_START_YYYYMMDD
                          , PLAN_TYPE
                          , SEQ
                          , ITEM_ID
                          , FROM_SITE
                          , TO_SITE
                          , MEASURE
                          , YYYYMMDD
                          , BOD_ID
                          , QTY
                          , ROUTE_ID
                          , INCOTERMS
                          , TRANSPORT_MODE
                          , BIZ_TYPE
                          , PROJECT_CODE
                          , FCST_TYPE
                          , FCST_ETD_DATE
                          , FCST_ETA_DATE
                          , ETD_DATE
                          , ETA_DATE
                          , CONFIRM_FLAG
                          , CONFIRM_ID
                          , CREATED_BY
                          , CREATION_DATE
                          , LAST_UPDATED_BY
                          , LAST_UPDATE_DATE
                          , ELECTRODE_YN
                          , ELECTRODE_TYPE
                          , ORIGIN_FROM_DIVISION_ID
                          , ORIGIN_TO_DIVISION_ID)
                    SELECT DIVISION_ID
                         , V_PLAN_START_YYYYMMDD      AS PLAN_START_YYYYMMDD
                         , PLAN_TYPE
                         , V_SEQ                      AS SEQ
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE
                         , 'SHIP_CONFIRM'             AS MEASURE
                         , YYYYMMDD
                         , BOD_ID
                         , QTY
                         , ROUTE_ID
                         , INCOTERMS
                         , TRANSPORT_MODE
                         , BIZ_TYPE
                         , PROJECT_CODE
                         , FCST_TYPE
                         , FCST_ETD_DATE
                         , FCST_ETA_DATE
                         , ETD_DATE
                         , ETA_DATE
                         , 'Y'                        AS CONFIRM_FLAG
                         , CONFIRM_ID
                         , P_USER_ID                  AS CREATED_BY
                         , V_CREATE_DATE              AS CREATION_DATE
                         , P_USER_ID                  AS LAST_UPDATED_BY
                         , V_CREATE_DATE              AS LAST_UPDATE_DATE
                         , ELECTRODE_YN
                         , ELECTRODE_TYPE
                         , ORIGIN_FROM_DIVISION_ID
                         , ORIGIN_TO_DIVISION_ID
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CHANGE_TYPE = 'C'
                       AND DIVISION_ID = N_ORI_DIVISION_ID
                       AND ITEM_ID     = N_ORI_ITEM_ID
                       AND FROM_SITE   = N_ORI_FROM_SITE
                       AND TO_SITE     = N_ORI_TO_SITE
                       AND YYYYMMDD    = N_ORI_YYYYMMDD;

                END IF;

                /* MEASURE SHIP_CONFIRM INSERT */
                INSERT INTO SSP_ANL_SHIP_PLAN_40
                       (DIVISION_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , MEASURE
                      , YYYYMMDD
                      , BOD_ID
                      , QTY
                      , ROUTE_ID
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , CONFIRM_FLAG
                      , CONFIRM_ID
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID)
                SELECT DIVISION_ID
                     , V_PLAN_START_YYYYMMDD          AS PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , V_SEQ                          AS SEQ
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , 'SHIP_CONFIRM'                 AS MEASURE
                     , YYYYMMDD
                     , BOD_ID
                     , QTY
                     , ROUTE_ID
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , 'Y'                            AS CONFIRM_FLAG
                     , CONFIRM_ID
                     , P_USER_ID                      AS CREATED_BY
                     , V_CREATE_DATE                  AS CREATION_DATE
                     , P_USER_ID                      AS LAST_UPDATED_BY
                     , V_CREATE_DATE                  AS LAST_UPDATE_DATE
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CHANGE_TYPE = 'C'
                   AND DIVISION_ID = N_DIVISION_ID
                   AND ITEM_ID     = N_ITEM_ID
                   AND FROM_SITE   = N_FROM_SITE
                   AND TO_SITE     = N_TO_SITE
                   AND YYYYMMDD    = V_SHIPMENT_DATE;

                /* EXEC PR_SSP_ANL_SHIP_UPDATE_BOH_VAL_40 - AS-IS 주석 처리 상태 유지 */

            END IF;

            IF LENGTH(RTRIM(V_CHANGE_REQ_NO)) > 0 THEN

                /* 이력저장
                   ※ PR_SSP_ANL_SHIP_CONFIRM_HIST 는 Oracle 미이관(2026.09.17) — 이관 후 아래 호출 연결
                   PR_SSP_ANL_SHIP_CONFIRM_HIST(V_CHANGE_REQ_NO, P_USER_ID, ''); */

                SELECT COUNT(*)
                  INTO V_MAIL_CHK
                  FROM SSP_MST_SEND_MAIL_REQ
                 WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO;

                IF V_MAIL_CHK = 0 THEN

                    /* 메일전송 */
                    INSERT INTO SSP_MST_SEND_MAIL_REQ
                           (CHANGE_REQ_NO
                          , TRANSFER_FLAG
                          , GRP_CHANGE_REQ)
                    VALUES (V_CHANGE_REQ_NO
                          , 'N'
                          , V_GRP_CHANGE_REQ);

                    V_MAIL_FLAG := 1;

                END IF;

            END IF;

        END LOOP; /* end of while loop */

        IF V_MAIL_FLAG = 1 THEN
            /* ※ PR_SSP_MAIL_SEND_ADJUST_MST 는 Oracle 미이관(2026.09.17) — 이관 후 아래 호출 연결
               PR_SSP_MAIL_SEND_ADJUST_MST(V_GRP_CHANGE_REQ); */
            NULL;
        END IF;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* [C20201223-000448] MKT FCST - SSP Sync
           ※ PR_DM_SSP_CONFIRM_SYNC 는 Oracle 미이관(2026.09.17) — 이관 후 아래 호출 연결
           PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, P_CONFIRM_ID); */

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S' AS RESULT_CODE, V_MAX_LOOP_CNT AS RESULT_CNT, V_CHANGE_REQ_NO AS CHANGE_REQ_NO FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_CODE, NULL AS ERR_MESSAGE FROM DUAL WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_CONFIRM_40;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME
                  , LOG_TYPE
                  , LOG_COUNT
                  , LOG_MESSAGE
                  , DESCRIPTION
                  , EVENT_DATE
                  , CREATION_DATE
                  , CREATED_BY
                  , LAST_UPDATE_DATE
                  , LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME
                  , 'END'
                  , NULL
                  , V_ERR_MESSAGE
                  , NULL
                  , SYSDATE
                  , SYSDATE
                  , V_PROGRAM_NAME
                  , SYSDATE
                  , V_PROGRAM_NAME);
            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE, '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;
            OPEN O_RC2 FOR SELECT V_ERR_CODE AS ERR_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;

    END P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_40;

    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER
       AS-IS SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER
       ※ '^' 로 이어 붙인 여러 행을 SCM_ARR_SPL_VAL 로 잘라 한 행씩 처리한다(AS-IS 동일).
       ※ 행 구분(ACTIVE_FLAG) : 'I' = 신규 출하확정 생성, 'I' 가 아닌 값 = 기존 출하확정 수정(AS-IS 동일).
       ※ Packer 는 BOD ITEM 을 사이트 접미사(PACKER_ITEM_ID_SUFFIX)로 12번째 자리를 바꿔 맞춘다(AS-IS 동일).
          품목 길이가 12 미만이면 원래 품목을 쓴다(AS-IS STUFF 가 NULL 을 돌려주는 자리).
       ※ 저장 시작에 SAVEPOINT 를 두어 BOD 없음('X')·오류('F') 시 앞 행 저장분까지 되돌린다.
          (AS-IS 는 트랜잭션이 없어 앞 행 저장분이 남고, 오류 시 CATCH 에서 COMMIT 한다)
       ※ AS-IS 가 부르는 이력 프로시저는 Oracle 에 없다(2026.09.22 기준) — 호출 자리를 주석으로 남긴다.
          PR_SSP_ANL_SHIP_CONFIRM_HIST
       ※ AS-IS 에서 이미 주석 처리된 호출(PR_DM_SSP_CONFIRM_SYNC · PR_SSP_MAIL_SEND_ADJUST_MST)은 주석 그대로 둔다.
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER
    (
        P_ACTIVE_FLAG           IN  VARCHAR2,
        P_DIVISION_ID           IN  VARCHAR2,
        P_CONFIRM_ID            IN  VARCHAR2,
        P_SHIPMENT_QTY          IN  VARCHAR2,
        P_SHIPMENT_DATE         IN  VARCHAR2,
        P_NEW_BOD_ID            IN  VARCHAR2,
        P_NEW_ROUTE_ID          IN  VARCHAR2,
        P_NEW_ETD_DATE          IN  VARCHAR2,
        P_NEW_ETA_DATE          IN  VARCHAR2,
        P_NEW_INCOTERMS         IN  VARCHAR2,
        P_NEW_TRANSPORT_MODE    IN  VARCHAR2,
        P_NEW_D_CONTRY          IN  VARCHAR2,
        P_NEW_D_PORT_CODE       IN  VARCHAR2,
        P_NEW_A_COUNTRY         IN  VARCHAR2,
        P_NEW_A_PORT_CODE       IN  VARCHAR2,
        P_NEW_CUSTOMER_LT       IN  VARCHAR2,
        P_NEW_TO_COUNTRY        IN  VARCHAR2,
        P_NEW_TO_CITY           IN  VARCHAR2,
        P_REMARKS               IN  VARCHAR2,
        P_REMARKS2              IN  VARCHAR2,
        P_REMARKS3              IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_CHECK_NEED_YN         IN  VARCHAR2,
        P_EDIT_MAIN             IN  VARCHAR2,
        P_SHIPTO_CODE           IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER
         * Description  : Shipment Request Confirm 저장
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021/09/22   KIMYONGHO		최초작성
         * 2022/01/04   KIMYONGHO	    ITEM 코드 11자리까지 동일하면 유효한 BOD ITEM
         * 2024/10/01   KHJ             NERP_SSP
         * 2026.09.22                   MSSQL -> Oracle 변환
         */
        V_RECV_ACTIVE_FLAG          VARCHAR2(4000 CHAR);
        V_ACTIVE_FLAG               VARCHAR2(4000 CHAR);
        V_DIVISION_ID               VARCHAR2(4000 CHAR);
        V_CONFIRM_ID                VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY              VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE             VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID                VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS             VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY              VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY             VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY            VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY               VARCHAR2(4000 CHAR);
        V_CREATE_DATE               DATE;
        V_BEFORE_QTY                NUMBER;
        V_QTY                       NUMBER;
        V_REMARKS                   VARCHAR2(4000 CHAR);
        V_REMARKS2                  VARCHAR2(4000 CHAR);
        V_REMARKS3                  VARCHAR2(4000 CHAR);
        V_CHECK_NEED_YN             VARCHAR2(4000 CHAR);

        V_PLAN_START_YYYYMMDD       VARCHAR2(4000 CHAR);
        V_SEQ                       VARCHAR2(4000 CHAR);
        V_EDIT_MAIN                 VARCHAR2(4000 CHAR);
        V_SHIPTO_CODE               VARCHAR2(4000 CHAR);

        N_ORI_DIVISION_ID           VARCHAR2(4000 CHAR);
        N_ORI_ITEM_ID               VARCHAR2(4000 CHAR);
        N_ORI_FROM_SITE             VARCHAR2(4000 CHAR);
        N_ORI_TO_SITE               VARCHAR2(4000 CHAR);
        N_ORI_YYYYMMDD              VARCHAR2(4000 CHAR);
        N_ORI_BOD_ID                VARCHAR2(4000 CHAR);
        N_ORI_PROJECT_CODE          VARCHAR2(4000 CHAR);
        N_ORI_FCST_TYPE             VARCHAR2(4000 CHAR);
        N_ORI_INCOTERMS             VARCHAR2(4000 CHAR);
        N_ORI_TRANSPORT_MODE        VARCHAR2(4000 CHAR);
        N_ORI_CONFIRM_ID            VARCHAR2(4000 CHAR);
        V_CHANGE_REQ_NO             VARCHAR2(4000 CHAR);

        V_DIVISION_ID_TEMP          VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000 CHAR);
        V_FROM_SITE_TEMP            VARCHAR2(4000 CHAR);
        V_TO_SITE_TEMP              VARCHAR2(4000 CHAR);
        V_ITEM_ID_TEMP              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000 CHAR);

        V_IF_GROUP_NO               VARCHAR2(50 CHAR) := TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISS');

        V_NEW_CONFIRM_ID            VARCHAR2(4000 CHAR);
        V_INFSEQNO                  VARCHAR2(20 CHAR);
        V_LAST_CONFIRM_DATE         VARCHAR2(8 CHAR);

        /* //메일관련 변수//////////////////////////////// */
        V_GRP_CHANGE_REQ            VARCHAR2(20 CHAR);
        V_MAIL_FLAG                 NUMBER := 0;
        V_MAIL_CHK                  NUMBER := 0;

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER';
        V_LOG_TYPE                  VARCHAR2(30 CHAR);
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
        V_DESCRIPTION               VARCHAR2(500 CHAR);
        D_EVENT_DATE                DATE;

        V_DELIMITER                 VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;

        V_BOD_NOT_FOUND             VARCHAR2(1 CHAR) := 'N';
        V_ERR_CODE                  NUMBER;
        V_ERR_MESSAGE               VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_CONF_PK;

        V_RECV_ACTIVE_FLAG := P_ACTIVE_FLAG;
        V_CREATE_DATE      := SYSDATE;
        V_GRP_CHANGE_REQ   := 'G' || TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF2');

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER));

        WHILE LENGTH(RTRIM(V_RECV_ACTIVE_FLAG)) > 0
          AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            /* V_MST_LOOP_CNT 1증가 */
            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG        := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,        V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID        := SCM_ARR_SPL_VAL(P_DIVISION_ID,        V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID         := SCM_ARR_SPL_VAL(P_CONFIRM_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY       := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY,       V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE      := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID         := SCM_ARR_SPL_VAL(P_NEW_BOD_ID,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE       := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE       := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID       := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS      := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY       := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY,       V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE    := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY      := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE    := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT    := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT,    V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY     := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY,     V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY        := SCM_ARR_SPL_VAL(P_NEW_TO_CITY,        V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS            := SCM_ARR_SPL_VAL(P_REMARKS,            V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2           := SCM_ARR_SPL_VAL(P_REMARKS2,           V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3           := SCM_ARR_SPL_VAL(P_REMARKS3,           V_DELIMITER, V_MST_LOOP_CNT);
            V_CHECK_NEED_YN      := SCM_ARR_SPL_VAL(P_CHECK_NEED_YN,      V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN          := SCM_ARR_SPL_VAL(P_EDIT_MAIN,          V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPTO_CODE        := SCM_ARR_SPL_VAL(P_SHIPTO_CODE,        V_DELIMITER, V_MST_LOOP_CNT);

            BEGIN
                SELECT FROM_SITE
                     , TO_SITE
                     , ITEM_ID
                  INTO V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_ITEM_ID_TEMP
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            BEGIN
                SELECT IA.DIVISION_ID
                     , IA.BOD_ID
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.SSP_INCOTERMS
                     , IA.TRANSPORT_MODE
                     , IA.ROUTE_ID
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.LT_TOTAL
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT A.DIVISION_ID
                             , A.BOD_ID
                             , A.FROM_SITE
                             , A.TO_SITE
                             , A.SSP_INCOTERMS
                             , A.TRANSPORT_MODE
                             , A.ROUTE_ID
                             , A.D_COUNTRY
                             , A.D_PORT_CODE
                             , A.A_COUNTRY
                             , A.A_PORT_CODE
                             , A.LT_TOTAL
                             , A.TO_COUNTRY
                             , A.TO_CITY
                          FROM (SELECT DISTINCT XA.DIVISION_ID
                                     , XA.BOD_ID
                                     , XA.FROM_SITE
                                     , XA.TO_SITE
                                     , XA.SSP_INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.ROUTE_ID
                                     , XA.D_COUNTRY
                                     , XA.D_PORT_CODE
                                     , XA.A_COUNTRY
                                     , XA.A_PORT_CODE
                                     , XA.LT_TOTAL
                                     , XA.LT_TOTAL_ORIGIN
                                     , XA.TO_COUNTRY
                                     , XA.TO_CITY
                                     , XA.PRIORITY
                                     , XA.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V XA
                                 WHERE XA.DIVISION_ID    = V_DIVISION_ID
                                   AND XA.FROM_SITE      = V_FROM_SITE_TEMP
                                   AND XA.TO_SITE        = V_TO_SITE_TEMP
                                   AND XA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND XA.SSP_INCOTERMS  = V_NEW_INCOTERMS
                                   AND XA.BOD_VALID_YN   = 'Y'
                                   AND XA.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND XA.TO_YYYYMMDD   >= V_SHIPMENT_DATE
                               ) A
                             , (SELECT DISTINCT SA.DIVISION_ID
                                     , SB.FROM_SITE
                                     , CASE WHEN TRIM(SC.PACKER_ITEM_ID_SUFFIX) IS NULL
                                            THEN SA.ITEM_ID
                                            ELSE NVL(CASE WHEN LENGTH(SA.ITEM_ID) >= 12
                                                          THEN SUBSTR(SA.ITEM_ID, 1, 11) || SC.PACKER_ITEM_ID_SUFFIX || SUBSTR(SA.ITEM_ID, 13)
                                                     END, SA.ITEM_ID)
                                       END AS ITEM_ID
                                     , SA.BOD_ID
                                  FROM SCP_MST_BOD_ITEM SA
                                     , SCP_MST_BOD_N_V SB
                                     , SCM_MST_SITE SC
                                 WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                   AND SA.BOD_ID      = SB.BOD_ID
                                   AND SC.DIVISION_ID = SB.DIVISION_ID
                                   AND SC.SCM_SITE_ID = SB.FROM_SITE
                                   AND SC.OSP_YN      = 'Y'
                                   AND SA.DIVISION_ID = V_DIVISION_ID
                                   AND CASE WHEN TRIM(SC.PACKER_ITEM_ID_SUFFIX) IS NULL
                                            THEN SA.ITEM_ID
                                            ELSE NVL(CASE WHEN LENGTH(SA.ITEM_ID) >= 12
                                                          THEN SUBSTR(SA.ITEM_ID, 1, 11) || SC.PACKER_ITEM_ID_SUFFIX || SUBSTR(SA.ITEM_ID, 13)
                                                     END, SA.ITEM_ID)
                                       END = V_ITEM_ID_TEMP
                               ) B
                         WHERE B.DIVISION_ID    = A.DIVISION_ID
                           AND B.BOD_ID         = A.BOD_ID
                           AND A.DIVISION_ID    = V_DIVISION_ID
                           AND A.FROM_SITE      = V_FROM_SITE_TEMP
                           AND A.TO_SITE        = V_TO_SITE_TEMP
                           AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND A.SSP_INCOTERMS  = V_NEW_INCOTERMS
                           AND A.BOD_VALID_YN   = 'Y'
                         ORDER BY A.PRIORITY
                       ) IA
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;   /* AS-IS TOP 1 이 0 행이면 앞 행 값이 그대로 남는다 */
            END;

            IF (   V_DIVISION_ID_TEMP        IS NULL
                OR V_NEW_BOD_ID_TEMP         IS NULL
                OR V_FROM_SITE_TEMP          IS NULL
                OR V_TO_SITE_TEMP            IS NULL
                OR V_NEW_INCOTERMS_TEMP      IS NULL
                OR V_NEW_TRANSPORT_MODE_TEMP IS NULL
                OR V_NEW_ROUTE_ID_TEMP       IS NULL
                OR V_NEW_D_CONTRY_TEMP       IS NULL
                OR V_NEW_D_PORT_CODE_TEMP    IS NULL
                OR V_NEW_A_COUNTRY_TEMP      IS NULL
                OR V_NEW_A_PORT_CODE_TEMP    IS NULL
                OR V_NEW_CUSTOMER_LT_TEMP    IS NULL
                OR V_NEW_TO_COUNTRY_TEMP     IS NULL
                OR V_NEW_TO_CITY_TEMP        IS NULL
               )
            THEN
                V_BOD_NOT_FOUND := 'Y';
                EXIT;
            END IF;

            IF V_ACTIVE_FLAG <> 'I'
            THEN

                V_QTY        := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT QTY
                         , BEFORE_QTY
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                IF V_QTY <> NVL(CEIL(TO_NUMBER(V_SHIPMENT_QTY)), 0)
                THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL
                THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL
                THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                IF V_EDIT_MAIN = 'Y'
                THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* 2020.06.23 ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정 */
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET YYYYMMDD             = V_SHIPMENT_DATE
                     , QTY                  = CEIL(TO_NUMBER(V_SHIPMENT_QTY))
                     , BEFORE_QTY           = V_BEFORE_QTY
                     , BOD_ID               = V_NEW_BOD_ID_TEMP
                     , ROUTE_ID             = TO_NUMBER(V_NEW_ROUTE_ID_TEMP)
                     , INCOTERMS            = V_NEW_INCOTERMS_TEMP
                     , D_COUNTRY            = V_NEW_D_CONTRY_TEMP
                     , D_PORT_CODE          = V_NEW_D_PORT_CODE_TEMP
                     , A_COUNTRY            = V_NEW_A_COUNTRY_TEMP
                     , A_PORT_CODE          = V_NEW_A_PORT_CODE_TEMP
                     , TO_COUNTRY           = V_NEW_TO_COUNTRY_TEMP
                     , TO_CITY              = V_NEW_TO_CITY_TEMP
                     , TRANSPORT_MODE       = V_NEW_TRANSPORT_MODE_TEMP
                     , ETD_DATE             = V_SHIPMENT_DATE            /* V_NEW_ETD_DATE */
                     , ETA_DATE             = V_NEW_ETA_DATE
                     , FCST_ETD_DATE        = V_SHIPMENT_DATE            /* V_NEW_ETD_DATE */
                     , FCST_ETA_DATE        = V_NEW_ETA_DATE
                     , CUSTOMER_LT          = TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , REMARKS              = V_REMARKS
                     , REMARKS2             = V_REMARKS2
                     , REMARKS3             = V_REMARKS3
                     , TO_SITE_SHIPTO_CODE  = V_SHIPTO_CODE
                     , CHECK_NEED_YN        = V_CHECK_NEED_YN
                     , LAST_UPDATED_BY      = P_USER_ID
                     , LAST_UPDATE_DATE     = V_CREATE_DATE
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;

            /* 2020-07-24 KIMYONGHO 신규생성 기능 추가 */
            IF V_ACTIVE_FLAG = 'I'
            THEN

                V_INFSEQNO := TO_CHAR(SYSDATE, 'YYMMDD') || FN_ZERO_LPAD(TO_CHAR(SEQ1_XIF_SCS.NEXTVAL), 10);

                /* 확정구간 마지막 일자( 현재일 기준 + 9 = PLANS_START_YYYYMMDD + 10) */
                V_LAST_CONFIRM_DATE := TO_CHAR(SYSDATE + 9, 'YYYYMMDD');
                V_DESCRIPTION       := '';
                D_EVENT_DATE        := SYSDATE;
                PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                /* NEW CONFIRM 생성 CHECK 확인 */
                V_NEW_CONFIRM_ID := 'R' || TO_CHAR(SYSDATE, 'YYYYMMDD')
                                        || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_PACKER_REQ_ID.NEXTVAL), -6);

                BEGIN
                    SELECT MAX(PLAN_START_YYYYMMDD)
                         , MAX(PLAN_SEQ)
                      INTO V_PLAN_START_YYYYMMDD
                         , V_SEQ
                      FROM SSP_PLAN_VERSION_V
                     WHERE PLAN_TYPE           = 'SP'
                       AND DIVISION_ID         = V_DIVISION_ID
                       AND CONFIRM_FLAG        = 'Y'
                       AND PLAN_START_YYYYMMDD = (SELECT MAX(PLAN_START_YYYYMMDD)
                                                    FROM SSP_PLAN_VERSION_V
                                                   WHERE DIVISION_ID  = V_DIVISION_ID
                                                     AND PLAN_TYPE    = 'SP'
                                                     AND CONFIRM_FLAG = 'Y');
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                V_QTY        := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT QTY
                         , BEFORE_QTY
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                IF V_QTY <> NVL(TO_NUMBER(V_SHIPMENT_QTY), 0)
                THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL
                THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL
                THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                IF V_EDIT_MAIN = 'Y'
                THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* -------------------------------------------------------------------------------------------------------------
                   1. SHIP_CONFIRM 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM
                   신규 건만 생성
                   ------------------------------------------------------------------------------------------------------------- */
                INSERT INTO SSP_ANL_SHIP_CONFIRM
                       (CONFIRM_ID
                      , SHIPMENT_STATUS
                      , DIVISION_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , PLANNED_QTY
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , CHANGE_TYPE
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REQUESTOR
                      , BEFORE_QTY
                      , CHECK_NEED_YN
                      , PACKAGE_TYPE_CODE
                      , FACTORY_ID
                      , ELECTRODE_TYPE
                      , PACKAGE_QTY
                      , DOM_EXP
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , ATTRIBUTE10
                       )
                SELECT V_NEW_CONFIRM_ID
                     , 'C'
                     , A.DIVISION_ID
                     , V_PLAN_START_YYYYMMDD
                     , 'SP'
                     , V_SEQ
                     , A.ITEM_ID
                     , A.FROM_SITE
                     , A.TO_SITE
                     , V_SHIPMENT_DATE
                     , 0
                     , TO_NUMBER(V_SHIPMENT_QTY)
                     , V_NEW_BOD_ID_TEMP
                     , TO_NUMBER(V_NEW_ROUTE_ID_TEMP)
                     , A.BIZ_TYPE
                     , A.PROJECT_CODE
                     , A.FCST_TYPE
                     , V_SHIPMENT_DATE
                     , V_NEW_ETA_DATE
                     , V_SHIPMENT_DATE
                     , V_NEW_ETA_DATE
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                     , A.FROM_SITE_TYPE
                     , A.FROM_SITE_PLANT_ID
                     , A.FROM_SITE_VENDOR_ID
                     , A.FROM_SITE_SOLDTO_CODE
                     , A.FROM_SITE_SHIPTO_CODE
                     , A.FROM_SITE_COMPANY_ID
                     , A.TO_SITE_TYPE
                     , A.TO_SITE_PLANT_ID
                     , A.TO_SITE_VENDOR_ID
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , A.TO_SITE_COMPANY_ID
                     , 'C'
                     , P_USER_ID
                     , V_CREATE_DATE
                     , P_USER_ID
                     , V_CREATE_DATE
                     , A.ELECTRODE_YN
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , P_USER_ID
                     , 0
                     , 'Y'
                     , A.PACKAGE_TYPE_CODE
                     , A.FACTORY_ID
                     , A.ELECTRODE_TYPE
                     , CEIL(CASE WHEN B.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.BOX_PER_CUT, 1)
                                 WHEN B.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELCRATE_PER_CUT, 1)
                                 WHEN B.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(TO_NUMBER(V_SHIPMENT_QTY) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELRACK_PER_CUT, 1)
                            END)
                     , A.DOM_EXP
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , NULL
                  FROM SSP_ANL_SHIP_CONFIRM A
                     , SSP_MST_SITE_ITEM_EE_V B
                 WHERE A.DIVISION_ID = (CASE WHEN A.BIZ_TYPE = 'E' THEN B.DIVISION_ID(+) ELSE B.ASSY_DIVISION_ID(+) END)
                   AND A.FROM_SITE   = (CASE WHEN A.BIZ_TYPE = 'E' THEN B.SCM_SITE_ID(+) ELSE B.ASSY_SCM_SITE_ID(+) END)
                   AND A.ITEM_ID     = B.ITEM_ID(+)
                   AND A.CONFIRM_ID  = V_CONFIRM_ID;

                /* -------------------------------------------------------------------------------------------------------------
                   2. SHIP_CONFIRM HISTORY 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM_H
                   신규 건만 생성
                   ------------------------------------------------------------------------------------------------------------- */
                INSERT INTO SSP_ANL_SHIP_CONFIRM_H
                       (HISTORY_SEQ
                      , CONFIRM_ID
                      , CHANGE_TYPE
                      , SHIPMENT_STATUS
                      , DIVISION_ID
                      , PLAN_START_YYYYMMDD
                      , PLAN_TYPE
                      , SEQ
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , PLANNED_QTY
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , CHANGE_REQ_NO
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , HISTORY_CREATION_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , BEFORE_QTY
                      , REMARKS
                      , CHECK_NEED_YN)
                SELECT SEQ1_SSP_ANL_SHIP_CONFIRM_H.NEXTVAL   /* HISTORY_SEQ */
                     , CONFIRM_ID
                     , CHANGE_TYPE
                     , SHIPMENT_STATUS
                     , DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , SEQ
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , PLANNED_QTY
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , NULL              /* CHANGE_REQ_NO */
                     , NULL              /* ERP_SO_NO */
                     , NULL              /* ERP_SO_ITEM_NO */
                     , NULL              /* ERP_DO_NO */
                     , NULL              /* ERP_STATUS */
                     , P_USER_ID         /* CREATED_BY */
                     , V_CREATE_DATE     /* CREATION_DATE */
                     , P_USER_ID         /* LAST_UPDATED_BY */
                     , V_CREATE_DATE     /* LAST_UPDATE_DATE */
                     , V_CREATE_DATE     /* HISTORY_CREATION_DATE */
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , BEFORE_QTY
                     , REMARKS
                     , CHECK_NEED_YN
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE 1 = 1
                   AND CONFIRM_ID = V_NEW_CONFIRM_ID;

                /* ERP전송 Table(XIF_ERP_PACK_SHIP_PLAN_S_SN) Insert */
                INSERT INTO XIF_ERP_PACK_SHIP_PLAN_S_SN
                       (IF_SEQ
                      , IF_TYPE
                      , IF_ID
                      , IF_INS_DATE
                      , IF_FLAG
                      , IF_SND_DATE
                      , IFSEQNO
                      , PACKER_CODE
                      , DIVISION_ID
                      , PACK_MODEL_CODE
                      , NICK_NAME
                      , SSP_CNFM
                      , SOLD_TO
                      , SALES_SITE
                      , SHIP_TO
                      , TRANSPORT_MODE
                      , INCOTERMS
                      , SHIP_PLAN_DATE
                      , SHIP_PLAN_QTY
                      , "COMMENT"
                      , ORDER_TYPE_DETAIL
                        /*  20211125 */
                      , ATTRIBUTE1
                      , ATTRIBUTE2
                      , ATTRIBUTE3
                      , ATTRIBUTE4
                      , ATTRIBUTE5
                      , ATTRIBUTE6
                      , ATTRIBUTE7
                      , ATTRIBUTE8
                      , ATTRIBUTE9
                      , ATTRIBUTE10
                       )
                SELECT 'OERP' || TO_CHAR(SYSDATE, 'YYMMDD') || FN_ZERO_LPAD(TO_CHAR(SEQ1_XIF_SCS.NEXTVAL), 10) AS IF_SEQ
                     , 'I'
                     , 'OSCM_OERP_PACK_SHIP_PLAN'
                     , SYSDATE
                     , 'N'
                     , NULL
                     , V_INFSEQNO
                     , NVL(X1.NEW_VALUE1, A.FROM_SITE)             AS FROM_SITE
                     , A.DIVISION_ID
                     , A.ITEM_ID
                     , A.NICK_NAME
                     , A.CONFIRM_ID
                     , NVL(X3.NEW_VALUE1, A.TO_SITE_SOLDTO_CODE)   AS TO_SITE_SOLDTO_CODE
                     , NVL(X2.NEW_VALUE1, A.TO_SITE)               AS TO_SITE
                     , NVL(X4.NEW_VALUE1, A.TO_SITE_SHIPTO_CODE)   AS TO_SITE_SHIPTO_CODE
                     , A.TRANSPORT_MODE
                     , A.INCOTERMS
                     , A.YYYYMMDD
                     , A.QTY
                     , A.REMARK
                     , A.ORDER_TYPE_DETAIL
                     , NULL              /* ATTRIBUTE1 */
                     , NULL              /* ATTRIBUTE2 */
                     , A.ATTR_03         /* Model PIC */
                     , A.ATTR_04         /* MTK_OWNER */
                     , NULL              /* ATTRIBUTE5 */
                     , NULL              /* ATTRIBUTE6 */
                     , NULL              /* ATTRIBUTE7 */
                     , NULL              /* ATTRIBUTE8 */
                     , NULL              /* ATTRIBUTE9 */
                     , NULL              /* ATTRIBUTE10 */
                  FROM (SELECT IA.FROM_SITE
                             , IA.DIVISION_ID
                             , IA.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(IA.DIVISION_ID, IA.ITEM_ID) AS NICK_NAME
                             , IA.CONFIRM_ID
                             , IA.TO_SITE_SOLDTO_CODE
                             , IA.TO_SITE
                             , IA.TO_SITE_SHIPTO_CODE
                             , IA.TRANSPORT_MODE
                             , IA.INCOTERMS
                             , IA.YYYYMMDD
                             , IA.QTY
                             , IA.REMARK
                             , IA.ORDER_TYPE_DETAIL
                             , IA.ATTR_03        /* Model PIC */
                             , IA.ATTR_04        /* MTK_OWNER */
                          FROM (SELECT   /* NEW */
                                       XA.CONFIRM_ID
                                     , 'B'               AS VERSION_TYPE   /* B:NEW/A:OLD */
                                     , XA.DIVISION_ID
                                     , XA.ITEM_ID
                                     , XA.FROM_SITE
                                     , XA.TO_SITE
                                     , XA.YYYYMMDD       AS YYYYMMDD
                                     , XA.YYYYMMDD       AS YYYYMMDD_LAST
                                     , NVL(XA.QTY, 0)    AS QTY
                                     , XA.BOD_ID         AS BOD_ID
                                     , XA.TRANSPORT_MODE
                                     , XA.INCOTERMS
                                     , XA.ROUTE_ID       AS ROUTE_ID
                                     , 'P'               AS OPERATION_GROUP
                                     , XA.BIZ_TYPE
                                     , XA.PROJECT_CODE
                                     , NVL(XD.SEGMENT2, XA.FCST_TYPE) AS ORDER_TYPE_DETAIL
                                     , XA.TO_SITE_SOLDTO_CODE
                                     , XA.TO_SITE_SHIPTO_CODE
                                       /* ERP I/F 추가(BUILDING, REMARK, CUSTOMER_REQ, CHANGE_CODE, CHANGE_CODE_NAME, REQUESTOR ) */
                                     , XA.REMARKS        AS BUILDING
                                     , XA.REMARKS2       AS REMARK
                                     , XA.REMARKS3       AS CUSTOMER_REQ
                                     , NULL              AS CHANGE_CODE
                                       /* 20211125 */
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     , CASE WHEN XC.USERNAME IS NULL THEN NULL
--                                            ELSE XC.USERNAME || '(' || XB.USER_ID || ')'
                                     , CASE WHEN XC.USER_NM IS NULL THEN NULL
                                            ELSE XC.USER_NM || '(' || XB.USER_ID || ')'
                                     /* 2026.09.30 AJS 수정 (END) */
                                       END                                        AS ATTR_03   /* Model PIC */
                                     , FN_GET_SSP_MKT_OWNER_NAME(XE.OWNER, '', 'KO') AS ATTR_04   /* MTK_OWNER */
                                  FROM SSP_ANL_SHIP_CONFIRM XA
                                     , SCM_MST_SITE_ITEM XE
                                     , SSP_MST_MODEL_USER XB
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     , TB_FX_USER XC
                                     , SCM_ADM_USER_M XC
                                     /* 2026.09.30 AJS 수정 (END) */
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL XD
                                 WHERE XE.DIVISION_ID(+)  = XA.DIVISION_ID
                                   AND XE.SCM_SITE_ID(+)  = XA.TO_SITE
                                   AND XE.ITEM_ID(+)      = XA.ITEM_ID
                                   AND XE.PROJECT_CODE(+) = XA.PROJECT_CODE
                                   AND XB.DIVISION_ID(+)  = XA.DIVISION_ID
                                   AND XB.FROM_SITE(+)    = XA.FROM_SITE
                                   AND XB.ITEM_ID(+)      = XA.ITEM_ID
                                   AND XB.VALID_YN(+)     = 'Y'
                                   /* 2026.09.30 AJS 수정 (START) */
--                                   AND XC.USERID(+)       = XB.USER_ID
--                                   AND XC.USEYN(+)        = 'Y'
                                   AND XC.USER_ID(+)      = XB.USER_ID
                                   AND XC.USE_YN(+)       = 'Y'
                                   /* 2026.09.30 AJS 수정 (END) */
                                   AND XD.LOOKUP_TYPE(+)  = 'SALES_TYPE_CODE'
                                   AND XD.VALID_YN(+)     = 'Y'
                                   AND XD.SEGMENT1(+)     = XA.FCST_TYPE
                                   AND XA.CONFIRM_ID      = V_NEW_CONFIRM_ID
                                   AND NVL(XA.QTY, 0)    <> 0   /* 신규생성경우 0은 제외 */
                               ) IA
                             , SCM_MST_SITE IB
                             , SCM_MST_SITE IC
                         WHERE IB.DIVISION_ID(+) = IA.DIVISION_ID
                           AND IB.SCM_SITE_ID(+) = IA.FROM_SITE
                           AND IB.VALID_YN(+)    = 'Y'
                           AND IC.DIVISION_ID(+) = IA.DIVISION_ID
                           AND IC.SCM_SITE_ID(+) = IA.TO_SITE
                           AND IC.VALID_YN(+)    = 'Y'
                       ) A
                     , NERP_CONV_MASTER X1
                     , NERP_CONV_MASTER X2
                     , NERP_CONV_MASTER X3
                     , NERP_CONV_MASTER X4
                 WHERE X1.CODETYPE(+)   = 'SCP_SITE_ID'
                   AND X1.OLD_VALUE1(+) = A.FROM_SITE
                   AND X2.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND X2.OLD_VALUE1(+) = A.TO_SITE
                   AND X3.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND X3.OLD_VALUE1(+) = A.TO_SITE_SOLDTO_CODE
                   AND X4.CODETYPE(+)   = 'END_CUSTOMER_ID'
                   AND X4.OLD_VALUE1(+) = A.TO_SITE_SHIPTO_CODE;

                INSERT INTO XIF_SCS_PACK_SHIP_PLAN_S_SN
                       (IF_SEQ
                      , IF_TYPE
                      , IF_ID
                      , IF_INS_DATE
                      , IF_FLAG
                      , PACKER_CODE
                      , DIVISION_ID
                      , PLAN_VERSION
                      , PACK_MODEL_CODE
                      , NICK_NAME
                      , TARGET_ORDER
                      , SSP_CNFM
                      , SALES_SITE
                      , SHIP_TO
                      , SHIP_TO_NAME
                      , TRANSPORT_MODE
                      , INCOTERMS
                      , SHIP_PLAN_DATE
                      , SHIP_PLAN_QTY
                      , "COMMENT"
                      , ATTR_01
                      , ATTR_02
                      , ATTR_03
                      , ATTR_04
                      , ATTR_05
                      , ATTR_06
                      , ATTR_07
                      , ATTR_08
                      , ATTR_09
                      , ATTR_10
                      , ORDER_TYPE_DETAIL
                       )
                SELECT 'OSCM' || TO_CHAR(SYSDATE, 'YYMMDD') || FN_ZERO_LPAD(TO_CHAR(SEQ1_XIF_SCS.NEXTVAL), 10) AS IF_SEQ
                     , 'I'                                 AS IF_TYPE
                     , 'OSCM_OSCS_SCS_PACK_SHIP_PLAN'       AS IF_ID
                     , SYSDATE                              AS IF_INS_DATE
                     , 'N'                                  AS IF_FLAG
                     , NVL(X1.NEW_VALUE1, A.PACKER_CODE)    AS PACKER_CODE
                     , A.DIVISION_ID
                     , A.PLAN_VERSION
                     , A.PACK_MODEL_CODE
                     , A.NICK_NAME
                     , 'O'                                  AS TARGET_ORDER
                     , A.SSP_CNFM
                     , A.SALES_SITE
                     , A.SHIP_TO
                     , A.SHIP_TO_NAME
                     , A.TRANSPORT_MODE
                     , A.INCOTERMS
                     , A.SHIP_PLAN_DATE
                     , A.SHIP_PLAN_QTY
                       /* 20211102  SMS  수정 */
                     , A."COMMENT"
                     , A.ATTR_01
                     , NULL                                 AS ATTR_02
                       /* 20211102  SMS  수정 */
                     , A.ATTR_03                            /* Model PIC */
                     , A.ATTR_04                            /* MTK_OWNER */
                     , NULL                                 AS ATTR_05
                     , NULL                                 AS ATTR_06
                     , NULL                                 AS ATTR_07
                     , NULL                                 AS ATTR_08
                     , NULL                                 AS ATTR_09
                     , A.ATTR_10
                     , A.FCST_TYPE                          /* ORDER_TYPE_DETAIL */
                  FROM (SELECT XA.FROM_SITE                              AS PACKER_CODE
                             , XA.DIVISION_ID                            AS DIVISION_ID
                             , TO_CHAR(SYSDATE, 'YYYYMMDD')              AS PLAN_VERSION
                             , XA.ITEM_ID                                AS PACK_MODEL_CODE
                             , FN_GET_ITEM_NICKNAME(XA.DIVISION_ID, XA.ITEM_ID) AS NICK_NAME
                             , XA.CONFIRM_ID                             AS SSP_CNFM
                             , XA.TO_SITE                                AS SALES_SITE
                             , XA.TO_SITE_SHIPTO_CODE                    AS SHIP_TO
                             , FN_GET_SITE_CUSTOMER_INFO(XA.DIVISION_ID, XA.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIP_TO_NAME
                             , XA.TRANSPORT_MODE                         AS TRANSPORT_MODE
                             , XA.INCOTERMS                              AS INCOTERMS
                             , XA.YYYYMMDD                               AS SHIP_PLAN_DATE
                             , XA.QTY                                    AS SHIP_PLAN_QTY
                               /* 20211102  SMS  수정 */
                             , XA.REMARKS                                AS "COMMENT"
                             , XA.DIVISION_ID || '_' || V_PLAN_START_YYYYMMDD || '_' || V_IF_GROUP_NO AS ATTR_01
                               /* 20211102  SMS  수정 */
                             /* 2026.09.30 AJS 수정 (START) */
--                             , CASE WHEN XC.USERNAME IS NULL THEN NULL
--                                    ELSE XC.USERNAME || '(' || XB.USER_ID || ')'
                             , CASE WHEN XC.USER_NM IS NULL THEN NULL
                                    ELSE XC.USER_NM || '(' || XB.USER_ID || ')'
                             /* 2026.09.30 AJS 수정 (END) */
                               END                                       AS ATTR_03   /* Model PIC */
                             , FN_GET_SSP_MKT_OWNER_NAME(XE.OWNER, '', 'KO') AS ATTR_04   /* MTK_OWNER */
                             , XA.CONFIRM_ID                             AS ATTR_10
                               /* 20211102  SMS  수정 */
                             , NVL(XD.SEGMENT2, XA.FCST_TYPE)            AS FCST_TYPE   /* ORDER_TYPE_DETAIL */
                          FROM SSP_ANL_SHIP_CONFIRM XA
                             , (SELECT SA.DIVISION_ID
                                     , SA.PROJECT_CODE
                                     , SA.SCM_SITE_ID
                                     , SA.ITEM_ID
                                  FROM (SELECT DIVISION_ID
                                             , PROJECT_CODE
                                             , SCM_SITE_ID
                                             , ITEM_ID
                                             , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                          FROM SCM_MST_SITE_ITEM
                                       ) SA
                                 WHERE SA.NUM = 1
                               ) XG
                             , SCM_MST_SITE_ITEM XE
                             , SSP_MST_MODEL_USER XB
                             /* 2026.09.30 AJS 수정 (START) */
--                             , TB_FX_USER XC
                             , SCM_ADM_USER_M XC
                             /* 2026.09.30 AJS 수정 (END) */
                             , SCM_ADM_LOOKUP_MASTER_DETAIL XD
                         WHERE XG.DIVISION_ID(+)  = (CASE WHEN XA.DIVISION_ID = 'EE' THEN XA.ORIGIN_TO_DIVISION_ID ELSE XA.DIVISION_ID END)
                           AND XG.SCM_SITE_ID(+)  = XA.TO_SITE
                           AND XG.ITEM_ID(+)      = XA.ITEM_ID
                           AND XE.DIVISION_ID(+)  = XA.DIVISION_ID
                           AND XE.SCM_SITE_ID(+)  = XA.TO_SITE
                           AND XE.ITEM_ID(+)      = XA.ITEM_ID
                           AND XE.PROJECT_CODE(+) = XG.PROJECT_CODE
                           AND XB.DIVISION_ID(+)  = XA.DIVISION_ID
                           AND XB.FROM_SITE(+)    = XA.FROM_SITE
                           AND XB.ITEM_ID(+)      = XA.ITEM_ID
                           AND XB.VALID_YN(+)     = 'Y'
                           /* 2026.09.30 AJS 수정 (START) */
--                           AND XC.USERID(+)       = XB.USER_ID
--                           AND XC.USEYN(+)        = 'Y'
                           AND XC.USER_ID(+)      = XB.USER_ID
                           AND XC.USE_YN(+)       = 'Y'
                           /* 2026.09.30 AJS 수정 (END) */
                           AND XD.LOOKUP_TYPE(+)  = 'SALES_TYPE_CODE'
                           AND XD.VALID_YN(+)     = 'Y'
                           AND XD.SEGMENT1(+)     = XA.FCST_TYPE
                           AND XA.CONFIRM_ID      = V_NEW_CONFIRM_ID
                           AND NVL(XA.QTY, 0)    <> 0   /* 신규생성경우 0은 제외 */
                       ) A
                     , NERP_CONV_MASTER X1
                 WHERE X1.CODETYPE(+)   = 'SCP_SITE_ID'
                   AND X1.OLD_VALUE1(+) = A.PACKER_CODE;

                /* MKT FCST - SSP Sync 신규 생성 건 대상 */
                /* PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, V_NEW_CONFIRM_ID); */
                /* V_CONFIRM_ID := V_NEW_CONFIRM_ID; */

            END IF;

            IF V_EDIT_MAIN = 'Y'
            THEN

                BEGIN
                    SELECT IA.DIVISION_ID
                         , IA.ITEM_ID
                         , IA.FROM_SITE
                         , IA.TO_SITE
                         , IA.YYYYMMDD
                         , IA.BOD_ID
                         , IA.PROJECT_CODE
                         , IA.FCST_TYPE
                         , IA.INCOTERMS
                         , IA.TRANSPORT_MODE
                         , IA.CONFIRM_ID
                         , IA.CHANGE_REQ_NO
                      INTO N_ORI_DIVISION_ID
                         , N_ORI_ITEM_ID
                         , N_ORI_FROM_SITE
                         , N_ORI_TO_SITE
                         , N_ORI_YYYYMMDD
                         , N_ORI_BOD_ID
                         , N_ORI_PROJECT_CODE
                         , N_ORI_FCST_TYPE
                         , N_ORI_INCOTERMS
                         , N_ORI_TRANSPORT_MODE
                         , N_ORI_CONFIRM_ID
                         , V_CHANGE_REQ_NO
                      FROM (SELECT DIVISION_ID
                                 , ITEM_ID
                                 , FROM_SITE
                                 , TO_SITE
                                 , YYYYMMDD
                                 , BOD_ID
                                 , PROJECT_CODE
                                 , FCST_TYPE
                                 , INCOTERMS
                                 , TRANSPORT_MODE
                                 , CONFIRM_ID
                                 , CHANGE_REQ_NO
                              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                             WHERE CONFIRM_ID = V_CONFIRM_ID
                               AND VALID_YN   = 'Y'
                             ORDER BY LAST_UPDATE_DATE DESC
                           ) IA
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

            END IF;

            IF LENGTH(RTRIM(V_CHANGE_REQ_NO)) > 0
            THEN

                /* 이력저장 */
                /* PR_SSP_ANL_SHIP_CONFIRM_HIST 는 Oracle 미이관(2026.09.22 기준) */
                /* PR_SSP_ANL_SHIP_CONFIRM_HIST(V_CHANGE_REQ_NO, P_USER_ID, ''); */

                SELECT COUNT(*)
                  INTO V_MAIL_CHK
                  FROM SSP_MST_SEND_MAIL_REQ
                 WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO;

                IF V_MAIL_CHK = 0
                THEN

                    /* 메일전송 */
                    INSERT INTO SSP_MST_SEND_MAIL_REQ
                           (CHANGE_REQ_NO
                          , TRANSFER_FLAG
                          , GRP_CHANGE_REQ)
                    VALUES (V_CHANGE_REQ_NO
                          , 'N'
                          , V_GRP_CHANGE_REQ);

                    V_MAIL_FLAG := 1;

                END IF;

            END IF;

        END LOOP;

        IF V_BOD_NOT_FOUND = 'Y'
        THEN

            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := '';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            COMMIT;

            OPEN O_RC1 FOR SELECT 'X'  AS RESULT_CODE
                                , NULL AS "Request_no"
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                             FROM DUAL
                            WHERE 1 = 0;

            RETURN;

        END IF;

        /* IF V_MAIL_FLAG = 1 THEN */
        /*     PR_SSP_MAIL_SEND_ADJUST_MST(V_GRP_CHANGE_REQ); */
        /* END IF; */

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S'                       AS RESULT_CODE
                            , V_MAX_LOOP_CNT            AS RESULT_CNT
                            , NVL(V_CHANGE_REQ_NO, '')  AS CHANGE_REQ_NO
                         FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                         FROM DUAL
                        WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_CONF_PK;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE
                                , '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                             FROM DUAL
                            WHERE 1 = 0;

    END P_SSP0015_SAVE_SHIPMENT_REQUEST_CONFIRM_PACKER;

    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING
       AS-IS SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING
       ※ '^' 로 이어 붙인 여러 행을 SCM_ARR_SPL_VAL 로 잘라 한 행씩 처리한다(AS-IS 동일).
       ※ BOD 조회(SELECT TOP 1 … ORDER BY PRIORITY)는 인라인 뷰 + ROWNUM 으로 옮긴다.
          0 행이면 AS-IS 처럼 앞 행 값이 남는다(AS-IS 는 루프마다 초기화하지 않는다).
       ※ 저장 시작에 SAVEPOINT 를 두어 오류('F') 시 앞 행 저장분까지 되돌린다.
          (AS-IS 는 트랜잭션이 없어 앞 행 저장분이 남고, 오류 시 CATCH 에서 COMMIT 한다)
       ※ AS-IS 가 부르는 ERP 전송 프로시저는 Oracle 에 없다(2026.09.22 기준) — 호출 자리를 주석으로 남긴다.
          PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING
    (
        P_ACTIVE_FLAG               IN  VARCHAR2,
        P_DIVISION_ID               IN  VARCHAR2,
        P_CONFIRM_ID                IN  VARCHAR2,
        P_SHIPMENT_QTY              IN  VARCHAR2,
        P_SHIPMENT_DATE             IN  VARCHAR2,
        P_FROM_SITE                 IN  VARCHAR2,
        P_NEW_BOD_ID                IN  VARCHAR2,
        P_NEW_ROUTE_ID              IN  VARCHAR2,
        P_NEW_ETD_DATE              IN  VARCHAR2,
        P_NEW_ETA_DATE              IN  VARCHAR2,
        P_NEW_INCOTERMS             IN  VARCHAR2,
        P_NEW_TRANSPORT_MODE        IN  VARCHAR2,
        P_NEW_D_CONTRY              IN  VARCHAR2,
        P_NEW_D_PORT_CODE           IN  VARCHAR2,
        P_NEW_A_COUNTRY             IN  VARCHAR2,
        P_NEW_A_PORT_CODE           IN  VARCHAR2,
        P_NEW_CUSTOMER_LT           IN  VARCHAR2,
        P_NEW_TO_COUNTRY            IN  VARCHAR2,
        P_NEW_TO_CITY               IN  VARCHAR2,
        P_EDIT_MAIN                 IN  VARCHAR2,
        P_EDIT_REMARK               IN  VARCHAR2,
        P_USER_ID                   IN  VARCHAR2,
        P_USER_DEPT_ID              IN  VARCHAR2,
        P_ELECTRODE_YN              IN  VARCHAR2 DEFAULT '',
        P_ELECTRODE_TYPE            IN  VARCHAR2 DEFAULT '',
        P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2 DEFAULT '',
        P_ORIGION_TO_DIVISION_ID    IN  VARCHAR2 DEFAULT '',
        P_REMARKS                   IN  VARCHAR2,
        P_REMARKS2                  IN  VARCHAR2,
        P_REMARKS3                  IN  VARCHAR2,
        P_CHANGE_REASON_CODE        IN  VARCHAR2,
        P_CHANGE_REASON_DETAIL      IN  VARCHAR2,
        P_TITLE                     IN  VARCHAR2,
        P_PROGRAM_ID                IN  VARCHAR2,
        P_SHIPTO_CODE               IN  VARCHAR2,
        O_RC1                       OUT SYS_REFCURSOR,
        O_RC2                       OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING
         * Description  : Shipment Plan Change 작성중 저장
         * 호출         : SSP0015
         * 관련 Table   : SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
         * 관련 프로시저 : PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN - ERP 관련 Table)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2019/04/03   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REMARKS, REMARKS 컬럼 추가
         * 2019/04/30   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REQUESTOR 컬럼 변경
         * 2019/05/07   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REMARKS3 컬럼 추가
         * 2019/05/15   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  CHAGE_REASON_CODE, CHAGE_REASON_DETAIL PARAM추가
         * 2019/05/28   mcTheJ         [PJ20189106] 전지.GSCM 고도화 이행  CHANGE_TITLE 수정
         * 2019/05/29   mcTheJ         [PJ20189106] 전지.GSCM 고도화 이행  CHANGE_REASON 추가로 인한 CS코드에서 반복 호출(단. SONo의 경우 통으로 Parameter 넘김)
         * 2019/09/04   AYJ            etd:shipdate, eta:etd+lt_day로 셋팅
         * 2019/10/29   ayj            FCST_ETA_DATE, ETA_DATE 저장 값 수정(출발일 기준 항차를 고려한 ETA_DATE 계산)
         * 2020-02-26   KIMYONGHO      [C20200224-000318]출하변경사유 코드 변경   R01 - > T07
         * 2020-07-08   KBK            [C20200630-000480] : Shipment Plan (IT& Mobile) 화면에서 SSP Planner 가 Data를 수정 할경우 Change reason / reason detail Tap을 화면상에 보여주지 않고, Data상으로 T07: 외부 요인으로 Default 설정 필요.
         * 2021/09/02   KIMYONGHO      SCP_MST_BOD_v -> SCP_MST_BOD_N_V 변경
         * 2024/05/08   jilee          PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH  'C' 변경요청, 저장시 ATTRIBUTE2 'A' 추가
         * 2026.09.22                  MSSQL -> Oracle 변환
         */
        V_RECV_ACTIVE_FLAG          VARCHAR2(4000 CHAR);
        V_MAX_REQ_NO                VARCHAR2(40 CHAR);
        V_ACTIVE_FLAG               VARCHAR2(4000 CHAR);
        V_DIVISION_ID               VARCHAR2(4000 CHAR);
        V_CONFIRM_ID                VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY              VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE             VARCHAR2(4000 CHAR);
        V_FROM_SITE                 VARCHAR2(4000 CHAR);
        V_TO_SITE                   VARCHAR2(4000 CHAR);
        V_ITEM_ID                   VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID                VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS             VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY              VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY             VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY            VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY               VARCHAR2(4000 CHAR);
        V_EDIT_MAIN                 VARCHAR2(4000 CHAR);
        V_EDIT_REMARK               VARCHAR2(4000 CHAR);
        V_CREATE_DATE               DATE;
        V_CHK                       NUMBER := 0;
        V_TITLE                     VARCHAR2(4000 CHAR);
        V_ELECTRODE_YN              VARCHAR2(4000 CHAR);
        V_ELECTRODE_TYPE            VARCHAR2(4000 CHAR);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000 CHAR);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000 CHAR);
        V_REMARKS                   VARCHAR2(4000 CHAR);
        V_REMARKS2                  VARCHAR2(4000 CHAR);
        V_REMARKS3                  VARCHAR2(4000 CHAR);
        V_CHANGE_REASON_CODE        VARCHAR2(4000 CHAR);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000 CHAR);

        V_DIVISION_ID_TEMP          VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000 CHAR);
        V_FROM_SITE_TEMP            VARCHAR2(4000 CHAR);
        V_TO_SITE_TEMP              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000 CHAR);

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING';
        V_LOG_TYPE                  VARCHAR2(30 CHAR);
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
        V_DESCRIPTION               VARCHAR2(500 CHAR);
        D_EVENT_DATE                DATE;

        V_DELIMITER                 VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;

        V_BOD_NOT_FOUND             VARCHAR2(1 CHAR) := 'N';
        V_ERR_CODE                  NUMBER;
        V_ERR_MESSAGE               VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_DRAFT;

        V_RECV_ACTIVE_FLAG := P_ACTIVE_FLAG;
        V_CREATE_DATE      := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER));

        WHILE LENGTH(RTRIM(V_RECV_ACTIVE_FLAG)) > 0
          AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG             := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,             V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID             := SCM_ARR_SPL_VAL(P_DIVISION_ID,             V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID              := SCM_ARR_SPL_VAL(P_CONFIRM_ID,              V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY            := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY,            V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE           := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE               := SCM_ARR_SPL_VAL(P_FROM_SITE,               V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID              := SCM_ARR_SPL_VAL(P_NEW_BOD_ID,              V_DELIMITER, V_MST_LOOP_CNT);
            V_TITLE                   := 'Change on ' || SCM_ARR_SPL_VAL(P_TITLE,   V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE            := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE            := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID            := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS           := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS,           V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE      := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY            := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE         := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY           := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY,           V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE         := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT         := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY          := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY,          V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY             := SCM_ARR_SPL_VAL(P_NEW_TO_CITY,             V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN               := SCM_ARR_SPL_VAL(P_EDIT_MAIN,               V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_REMARK             := SCM_ARR_SPL_VAL(P_EDIT_REMARK,             V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_YN            := SCM_ARR_SPL_VAL(P_ELECTRODE_YN,            V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_TYPE          := SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE,          V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGIN_FROM_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGIN_FROM_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGION_TO_DIVISION_ID  := SCM_ARR_SPL_VAL(P_ORIGION_TO_DIVISION_ID,  V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS                 := SCM_ARR_SPL_VAL(P_REMARKS,                 V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2                := SCM_ARR_SPL_VAL(P_REMARKS2,                V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3                := SCM_ARR_SPL_VAL(P_REMARKS3,                V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE      := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL    := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL,    V_DELIMITER, V_MST_LOOP_CNT);

            IF V_CHANGE_REASON_CODE IS NULL
            THEN
                V_CHANGE_REASON_CODE := 'T07';
            END IF;

            IF V_CHANGE_REASON_DETAIL IS NULL
            THEN
                V_CHANGE_REASON_DETAIL := NULL;
            END IF;

            BEGIN
                SELECT TO_SITE
                     , ITEM_ID
                  INTO V_TO_SITE
                     , V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            BEGIN
                SELECT IA.DIVISION_ID
                     , IA.BOD_ID
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.SSP_INCOTERMS
                     , IA.TRANSPORT_MODE
                     , IA.ROUTE_ID
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.LT_TOTAL
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT A.DIVISION_ID
                             , A.BOD_ID
                             , A.FROM_SITE
                             , A.TO_SITE
                             , A.SSP_INCOTERMS
                             , A.TRANSPORT_MODE
                             , A.ROUTE_ID
                             , A.D_COUNTRY
                             , A.D_PORT_CODE
                             , A.A_COUNTRY
                             , A.A_PORT_CODE
                             , A.LT_TOTAL
                             , A.TO_COUNTRY
                             , A.TO_CITY
                          FROM (SELECT DISTINCT XA.DIVISION_ID
                                     , XA.BOD_ID
                                     , XA.FROM_SITE
                                     , XA.TO_SITE
                                     , XA.SSP_INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.ROUTE_ID
                                     , XA.D_COUNTRY
                                     , XA.D_PORT_CODE
                                     , XA.A_COUNTRY
                                     , XA.A_PORT_CODE
                                     , XA.LT_TOTAL
                                     , XA.LT_TOTAL_ORIGIN
                                     , XA.TO_COUNTRY
                                     , XA.TO_CITY
                                     , XA.PRIORITY
                                     , XA.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V XA
                                 WHERE XA.DIVISION_ID    = V_DIVISION_ID
                                   AND XA.FROM_SITE      = V_FROM_SITE
                                   AND XA.TO_SITE        = V_TO_SITE
                                   AND XA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND XA.SSP_INCOTERMS  = V_NEW_INCOTERMS
                                   AND XA.BOD_VALID_YN   = 'Y'
                                   AND XA.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND XA.TO_YYYYMMDD   >= V_SHIPMENT_DATE
                               ) A
                             , (SELECT DISTINCT SA.DIVISION_ID
                                     , SA.ITEM_ID
                                     , SA.BOD_ID
                                  FROM SCP_MST_BOD_ITEM SA
                                 WHERE SA.DIVISION_ID = V_DIVISION_ID
                                   AND SA.ITEM_ID     = V_ITEM_ID
                               ) B
                         WHERE B.DIVISION_ID    = A.DIVISION_ID
                           AND B.BOD_ID         = A.BOD_ID
                           AND A.DIVISION_ID    = V_DIVISION_ID
                           AND A.FROM_SITE      = V_FROM_SITE
                           AND A.TO_SITE        = V_TO_SITE
                           AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND A.SSP_INCOTERMS  = V_NEW_INCOTERMS
                           AND A.BOD_VALID_YN   = 'Y'
                         ORDER BY A.PRIORITY
                       ) IA
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;   /* AS-IS TOP 1 이 0 행이면 앞 행 값이 그대로 남는다 */
            END;

            IF (   V_DIVISION_ID_TEMP        IS NULL
                OR V_NEW_BOD_ID_TEMP         IS NULL
                OR V_FROM_SITE_TEMP          IS NULL
                OR V_TO_SITE_TEMP            IS NULL
                OR V_NEW_INCOTERMS_TEMP      IS NULL
                OR V_NEW_TRANSPORT_MODE_TEMP IS NULL
                OR V_NEW_ROUTE_ID_TEMP       IS NULL
                OR V_NEW_D_CONTRY_TEMP       IS NULL
                OR V_NEW_D_PORT_CODE_TEMP    IS NULL
                OR V_NEW_A_COUNTRY_TEMP      IS NULL
                OR V_NEW_A_PORT_CODE_TEMP    IS NULL
                OR V_NEW_CUSTOMER_LT_TEMP    IS NULL
                OR V_NEW_TO_COUNTRY_TEMP     IS NULL
                OR V_NEW_TO_CITY_TEMP        IS NULL
               )
            THEN
                V_BOD_NOT_FOUND := 'Y';
                EXIT;
            END IF;

            IF V_EDIT_MAIN = 'Y'
            THEN

                IF V_CHK = 0
                THEN

                    V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD')
                                        || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                           (CHANGE_REQ_NO
                          , CHANGE_TYPE
                          , CHANGE_REQ_STATUS
                          , DIVISION_ID
                          , FROM_SITE
                          , REQUEST_TITLE
                          , REQUEST_USER
                          , REQUEST_DEPT
                          , REQUEST_TIME
                          , APPROVAL_USER
                          , APPROVAL_DEPT
                          , APPROVAL_TIME
                          , CHANGE_REASON_CODE
                          , CHANGE_REASON_DETAIL
                          , REJECT_REASON
                          , VALID_YN
                          , CREATED_BY
                          , CREATION_DATE
                          , LAST_UPDATED_BY
                          , LAST_UPDATE_DATE
                          , ELECTRODE_YN
                          , ELECTRODE_TYPE
                          , ORIGIN_FROM_DIVISION_ID
                          , ORIGIN_TO_DIVISION_ID
                           )
                    VALUES (V_MAX_REQ_NO
                          , 'A'
                          , 'A'
                          , V_DIVISION_ID
                          , V_FROM_SITE
                          , V_TITLE
                          , P_USER_ID
                          , P_USER_DEPT_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , P_USER_DEPT_ID
                          , V_CREATE_DATE
                            /* [C20200630-000480] : Shipment Plan (IT& Mobile) 화면에서 SSP Planner 가 Data를 수정 할경우 Change reason / reason detail Tap을 화면상에 보여주지 않고, Data상으로 T07: 외부 요인으로 Default 설정 필요. */
                            /* 요청에 따라 CHANGE_REASON_CODE, CHANGE_REASON_DETAIL 을 Default 'T07' 로 설정 */
                          , 'T07'
                          , 'T07'
                          , NULL
                          , 'Y'
                          , P_USER_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , V_CREATE_DATE
                          , V_ELECTRODE_YN
                          , V_ELECTRODE_TYPE
                          , V_ORIGIN_FROM_DIVISION_ID
                          , V_ORIGION_TO_DIVISION_ID
                           );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                IF V_SHIPMENT_QTY IS NULL
                THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL
                THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF V_SHIPMENT_DATE   IS NOT NULL
                   AND LENGTH(RTRIM(V_SHIPMENT_DATE)) = 8
                   AND V_NEW_CUSTOMER_LT IS NOT NULL
                   AND LENGTH(RTRIM(V_NEW_CUSTOMER_LT)) > 0
                THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                       (CHANGE_REQ_NO
                      , CONFIRM_ID
                      , NEW_YN
                      , DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , NEW_YYYYMMDD
                      , NEW_QTY
                      , NEW_BOD_ID
                      , NEW_ROUTE_ID
                      , NEW_ETD_DATE
                      , NEW_ETA_DATE
                      , NEW_INCOTERMS
                      , NEW_TRANSPORT_MODE
                      , NEW_D_COUNTRY
                      , NEW_D_PORT_CODE
                      , NEW_A_COUNTRY
                      , NEW_A_PORT_CODE
                      , NEW_CUSTOMER_LT
                      , NEW_TO_COUNTRY
                      , NEW_TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , VALID_YN
                      , ATTRIBUTE1
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , REQUESTOR
                      , ATTRIBUTE2
                       )
                SELECT V_MAX_REQ_NO
                     , CONFIRM_ID
                     , 'N'
                     , DIVISION_ID
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , V_SHIPMENT_DATE
                     , TO_NUMBER(V_SHIPMENT_QTY)
                     , V_NEW_BOD_ID_TEMP
                     , TO_NUMBER(V_NEW_ROUTE_ID_TEMP)
                     , V_NEW_ETD_DATE
                     , V_NEW_ETA_DATE
                     , V_NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , ERP_SO_NO
                     , ERP_SO_ITEM_NO
                     , ERP_DO_NO
                     , ERP_STATUS
                     , 'Y'
                     , 'N'
                     , P_USER_ID
                     , V_CREATE_DATE
                     , P_USER_ID
                     , V_CREATE_DATE
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , REQUESTOR
                     , 'A'
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;  /* V_EDIT_MAIN = 'Y' End */

        END LOOP;    /* While End */

        IF V_BOD_NOT_FOUND = 'Y'
        THEN

            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := '';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            COMMIT;

            OPEN O_RC1 FOR SELECT 'X'  AS RESULT_CODE
                                , NULL AS REQUEST_NO
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                             FROM DUAL
                            WHERE 1 = 0;

            RETURN;

        END IF;

        /* ERP전송 Table(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN) Insert */
        /* 출하확정변경시 ERP 전송 이터 테이블 저장 B: 변경확정 */
        /* PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH 는 Oracle 미이관(2026.09.22 기준) */
        /* PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH('C', V_MAX_REQ_NO); */

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S'          AS RESULT_CODE
                            , V_MAX_REQ_NO AS REQUEST_NO
                         FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                         FROM DUAL
                        WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_DRAFT;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE
                             FROM DUAL;

    END P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING;

    /* ============================================================
       P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER
       AS-IS SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER
       ※ '^' 로 이어 붙인 여러 행을 SCM_ARR_SPL_VAL 로 잘라 한 행씩 처리한다(AS-IS 동일).
       ※ BOD 조회(SELECT TOP 1 … ORDER BY PRIORITY)는 인라인 뷰 + ROWNUM 으로 옮긴다.
          0 행이면 AS-IS 처럼 앞 행 값이 남는다(AS-IS 는 루프마다 초기화하지 않는다).
       ※ 저장 시작에 SAVEPOINT 를 두어 오류('F') 시 앞 행 저장분까지 되돌린다.
          (AS-IS 는 트랜잭션이 없어 앞 행 저장분이 남고, 오류 시 CATCH 에서 COMMIT 한다)
       ※ AS-IS 가 부르는 ERP 전송 프로시저는 Oracle 에 없다(2026.09.22 기준) — 호출 자리를 주석으로 남긴다.
          PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_PACKER
       ※ Packer 는 BOD ITEM 을 사이트 접미사(PACKER_ITEM_ID_SUFFIX)로 12번째 자리를 바꿔 맞춘다(AS-IS 동일).
          품목 길이가 12 미만이면 원래 품목을 쓴다(AS-IS STUFF 가 NULL 을 돌려주는 자리).
       ============================================================ */
    PROCEDURE P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER
    (
        P_ACTIVE_FLAG               IN  VARCHAR2,
        P_DIVISION_ID               IN  VARCHAR2,
        P_CONFIRM_ID                IN  VARCHAR2,
        P_SHIPMENT_QTY              IN  VARCHAR2,
        P_SHIPMENT_DATE             IN  VARCHAR2,
        P_FROM_SITE                 IN  VARCHAR2,
        P_NEW_BOD_ID                IN  VARCHAR2,
        P_NEW_ROUTE_ID              IN  VARCHAR2,
        P_NEW_ETD_DATE              IN  VARCHAR2,
        P_NEW_ETA_DATE              IN  VARCHAR2,
        P_NEW_INCOTERMS             IN  VARCHAR2,
        P_NEW_TRANSPORT_MODE        IN  VARCHAR2,
        P_NEW_D_CONTRY              IN  VARCHAR2,
        P_NEW_D_PORT_CODE           IN  VARCHAR2,
        P_NEW_A_COUNTRY             IN  VARCHAR2,
        P_NEW_A_PORT_CODE           IN  VARCHAR2,
        P_NEW_CUSTOMER_LT           IN  VARCHAR2,
        P_NEW_TO_COUNTRY            IN  VARCHAR2,
        P_NEW_TO_CITY               IN  VARCHAR2,
        P_EDIT_MAIN                 IN  VARCHAR2,
        P_EDIT_REMARK               IN  VARCHAR2,
        P_USER_ID                   IN  VARCHAR2,
        P_USER_DEPT_ID              IN  VARCHAR2,
        P_ELECTRODE_YN              IN  VARCHAR2 DEFAULT '',
        P_ELECTRODE_TYPE            IN  VARCHAR2 DEFAULT '',
        P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2 DEFAULT '',
        P_ORIGION_TO_DIVISION_ID    IN  VARCHAR2 DEFAULT '',
        P_REMARKS                   IN  VARCHAR2,
        P_REMARKS2                  IN  VARCHAR2,
        P_REMARKS3                  IN  VARCHAR2,
        P_CHANGE_REASON_CODE        IN  VARCHAR2,
        P_CHANGE_REASON_DETAIL      IN  VARCHAR2,
        P_TITLE                     IN  VARCHAR2,
        P_PROGRAM_ID                IN  VARCHAR2,
        P_SHIPTO_CODE               IN  VARCHAR2,
        O_RC1                       OUT SYS_REFCURSOR,
        O_RC2                       OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER
         * Description  : Shipment Plan Change 작성중 저장
         * 호출         : SSP0015
         * 관련 Table   : SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
         * 관련 프로시저 : PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN - ERP 관련 Table)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2021/09/22   KIMYONGHO      최초작성
         * 2022/01/04   KIMYONGHO      ITEM 코드 11자리까지 동일하면 유효한 BOD ITEM
         * 2026.09.22                  MSSQL -> Oracle 변환
         */
        V_RECV_ACTIVE_FLAG          VARCHAR2(4000 CHAR);
        V_MAX_REQ_NO                VARCHAR2(40 CHAR);
        V_ACTIVE_FLAG               VARCHAR2(4000 CHAR);
        V_DIVISION_ID               VARCHAR2(4000 CHAR);
        V_CONFIRM_ID                VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY              VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE             VARCHAR2(4000 CHAR);
        V_FROM_SITE                 VARCHAR2(4000 CHAR);
        V_TO_SITE                   VARCHAR2(4000 CHAR);
        V_ITEM_ID                   VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID                VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE              VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS             VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY              VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY             VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE           VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY            VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY               VARCHAR2(4000 CHAR);
        V_EDIT_MAIN                 VARCHAR2(4000 CHAR);
        V_EDIT_REMARK               VARCHAR2(4000 CHAR);
        V_CREATE_DATE               DATE;
        V_CHK                       NUMBER := 0;
        V_TITLE                     VARCHAR2(4000 CHAR);
        V_ELECTRODE_YN              VARCHAR2(4000 CHAR);
        V_ELECTRODE_TYPE            VARCHAR2(4000 CHAR);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000 CHAR);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000 CHAR);
        V_REMARKS                   VARCHAR2(4000 CHAR);
        V_REMARKS2                  VARCHAR2(4000 CHAR);
        V_REMARKS3                  VARCHAR2(4000 CHAR);
        V_CHANGE_REASON_CODE        VARCHAR2(4000 CHAR);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000 CHAR);
        V_SHIPTO_CODE               VARCHAR2(4000 CHAR);

        V_DIVISION_ID_TEMP          VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000 CHAR);
        V_FROM_SITE_TEMP            VARCHAR2(4000 CHAR);
        V_TO_SITE_TEMP              VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000 CHAR);

        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER';
        V_LOG_TYPE                  VARCHAR2(30 CHAR);
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
        V_DESCRIPTION               VARCHAR2(500 CHAR);
        D_EVENT_DATE                DATE;

        V_DELIMITER                 VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;

        V_BOD_NOT_FOUND             VARCHAR2(1 CHAR) := 'N';
        V_ERR_CODE                  NUMBER;
        V_ERR_MESSAGE               VARCHAR2(4000 CHAR);
    BEGIN

        SAVEPOINT SP_SSP0015_SAVE_DRAFT_PK;

        V_RECV_ACTIVE_FLAG := P_ACTIVE_FLAG;
        V_CREATE_DATE      := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER));

        WHILE LENGTH(RTRIM(V_RECV_ACTIVE_FLAG)) > 0
          AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT
        LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG             := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,             V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID             := SCM_ARR_SPL_VAL(P_DIVISION_ID,             V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID              := SCM_ARR_SPL_VAL(P_CONFIRM_ID,              V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY            := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY,            V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE           := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE,           V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE               := SCM_ARR_SPL_VAL(P_FROM_SITE,               V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID              := SCM_ARR_SPL_VAL(P_NEW_BOD_ID,              V_DELIMITER, V_MST_LOOP_CNT);
            V_TITLE                   := 'Change on ' || SCM_ARR_SPL_VAL(P_TITLE,   V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE            := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE            := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID            := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS           := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS,           V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE      := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY            := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY,            V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE         := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY           := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY,           V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE         := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT         := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT,         V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY          := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY,          V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY             := SCM_ARR_SPL_VAL(P_NEW_TO_CITY,             V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN               := SCM_ARR_SPL_VAL(P_EDIT_MAIN,               V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_REMARK             := SCM_ARR_SPL_VAL(P_EDIT_REMARK,             V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_YN            := SCM_ARR_SPL_VAL(P_ELECTRODE_YN,            V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_TYPE          := SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE,          V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGIN_FROM_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGIN_FROM_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGION_TO_DIVISION_ID  := SCM_ARR_SPL_VAL(P_ORIGION_TO_DIVISION_ID,  V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS                 := SCM_ARR_SPL_VAL(P_REMARKS,                 V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2                := SCM_ARR_SPL_VAL(P_REMARKS2,                V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3                := SCM_ARR_SPL_VAL(P_REMARKS3,                V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE      := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE,      V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL    := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL,    V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPTO_CODE             := SCM_ARR_SPL_VAL(P_SHIPTO_CODE,             V_DELIMITER, V_MST_LOOP_CNT);

            IF V_CHANGE_REASON_CODE IS NULL
            THEN
                V_CHANGE_REASON_CODE := 'T07';
            END IF;

            IF V_CHANGE_REASON_DETAIL IS NULL
            THEN
                V_CHANGE_REASON_DETAIL := NULL;
            END IF;

            BEGIN
                SELECT TO_SITE
                     , ITEM_ID
                  INTO V_TO_SITE
                     , V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            BEGIN
                SELECT IA.DIVISION_ID
                     , IA.BOD_ID
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.SSP_INCOTERMS
                     , IA.TRANSPORT_MODE
                     , IA.ROUTE_ID
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.LT_TOTAL
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT A.DIVISION_ID
                             , A.BOD_ID
                             , A.FROM_SITE
                             , A.TO_SITE
                             , A.SSP_INCOTERMS
                             , A.TRANSPORT_MODE
                             , A.ROUTE_ID
                             , A.D_COUNTRY
                             , A.D_PORT_CODE
                             , A.A_COUNTRY
                             , A.A_PORT_CODE
                             , A.LT_TOTAL
                             , A.TO_COUNTRY
                             , A.TO_CITY
                          FROM (SELECT DISTINCT XA.DIVISION_ID
                                     , XA.BOD_ID
                                     , XA.FROM_SITE
                                     , XA.TO_SITE
                                     , XA.SSP_INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.ROUTE_ID
                                     , XA.D_COUNTRY
                                     , XA.D_PORT_CODE
                                     , XA.A_COUNTRY
                                     , XA.A_PORT_CODE
                                     , XA.LT_TOTAL
                                     , XA.LT_TOTAL_ORIGIN
                                     , XA.TO_COUNTRY
                                     , XA.TO_CITY
                                     , XA.PRIORITY
                                     , XA.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V XA
                                 WHERE XA.DIVISION_ID    = V_DIVISION_ID
                                   AND XA.FROM_SITE      = V_FROM_SITE
                                   AND XA.TO_SITE        = V_TO_SITE
                                   AND XA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND XA.SSP_INCOTERMS  = V_NEW_INCOTERMS
                                   AND XA.BOD_VALID_YN   = 'Y'
                                   AND XA.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND XA.TO_YYYYMMDD   >= V_SHIPMENT_DATE
                               ) A
                             , (SELECT DISTINCT SA.DIVISION_ID
                                     , SB.FROM_SITE
                                     , CASE WHEN TRIM(SC.PACKER_ITEM_ID_SUFFIX) IS NULL
                                            THEN SA.ITEM_ID
                                            ELSE NVL(CASE WHEN LENGTH(SA.ITEM_ID) >= 12
                                                          THEN SUBSTR(SA.ITEM_ID, 1, 11) || SC.PACKER_ITEM_ID_SUFFIX || SUBSTR(SA.ITEM_ID, 13)
                                                     END, SA.ITEM_ID)
                                       END AS ITEM_ID
                                     , SA.BOD_ID
                                  FROM SCP_MST_BOD_ITEM SA
                                     , SCP_MST_BOD_N_V SB
                                     , SCM_MST_SITE SC
                                 WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                   AND SA.BOD_ID      = SB.BOD_ID
                                   AND SC.DIVISION_ID = SB.DIVISION_ID
                                   AND SC.SCM_SITE_ID = SB.FROM_SITE
                                   AND SC.OSP_YN      = 'Y'
                                   AND SA.DIVISION_ID = V_DIVISION_ID
                                   AND CASE WHEN TRIM(SC.PACKER_ITEM_ID_SUFFIX) IS NULL
                                            THEN SA.ITEM_ID
                                            ELSE NVL(CASE WHEN LENGTH(SA.ITEM_ID) >= 12
                                                          THEN SUBSTR(SA.ITEM_ID, 1, 11) || SC.PACKER_ITEM_ID_SUFFIX || SUBSTR(SA.ITEM_ID, 13)
                                                     END, SA.ITEM_ID)
                                       END = V_ITEM_ID
                               ) B
                         WHERE B.DIVISION_ID    = A.DIVISION_ID
                           AND B.BOD_ID         = A.BOD_ID
                           AND A.DIVISION_ID    = V_DIVISION_ID
                           AND A.FROM_SITE      = V_FROM_SITE
                           AND A.TO_SITE        = V_TO_SITE
                           AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND A.SSP_INCOTERMS  = V_NEW_INCOTERMS
                           AND A.BOD_VALID_YN   = 'Y'
                         ORDER BY A.PRIORITY
                       ) IA
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;   /* AS-IS TOP 1 이 0 행이면 앞 행 값이 그대로 남는다 */
            END;

            IF (   V_DIVISION_ID_TEMP        IS NULL
                OR V_NEW_BOD_ID_TEMP         IS NULL
                OR V_FROM_SITE_TEMP          IS NULL
                OR V_TO_SITE_TEMP            IS NULL
                OR V_NEW_INCOTERMS_TEMP      IS NULL
                OR V_NEW_TRANSPORT_MODE_TEMP IS NULL
                OR V_NEW_ROUTE_ID_TEMP       IS NULL
                OR V_NEW_D_CONTRY_TEMP       IS NULL
                OR V_NEW_D_PORT_CODE_TEMP    IS NULL
                OR V_NEW_A_COUNTRY_TEMP      IS NULL
                OR V_NEW_A_PORT_CODE_TEMP    IS NULL
                OR V_NEW_CUSTOMER_LT_TEMP    IS NULL
                OR V_NEW_TO_COUNTRY_TEMP     IS NULL
                OR V_NEW_TO_CITY_TEMP        IS NULL
               )
            THEN
                V_BOD_NOT_FOUND := 'Y';
                EXIT;
            END IF;

            IF V_EDIT_MAIN = 'Y'
            THEN

                IF V_CHK = 0
                THEN

                    V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD')
                                        || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                           (CHANGE_REQ_NO
                          , CHANGE_TYPE
                          , CHANGE_REQ_STATUS
                          , DIVISION_ID
                          , FROM_SITE
                          , REQUEST_TITLE
                          , REQUEST_USER
                          , REQUEST_DEPT
                          , REQUEST_TIME
                          , APPROVAL_USER
                          , APPROVAL_DEPT
                          , APPROVAL_TIME
                          , CHANGE_REASON_CODE
                          , CHANGE_REASON_DETAIL
                          , REJECT_REASON
                          , VALID_YN
                          , CREATED_BY
                          , CREATION_DATE
                          , LAST_UPDATED_BY
                          , LAST_UPDATE_DATE
                          , ELECTRODE_YN
                          , ELECTRODE_TYPE
                          , ORIGIN_FROM_DIVISION_ID
                          , ORIGIN_TO_DIVISION_ID
                           )
                    VALUES (V_MAX_REQ_NO
                          , 'A'
                          , 'A'
                          , V_DIVISION_ID
                          , V_FROM_SITE
                          , V_TITLE
                          , P_USER_ID
                          , P_USER_DEPT_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , P_USER_DEPT_ID
                          , V_CREATE_DATE
                            /* [C20200630-000480] : Shipment Plan (IT& Mobile) 화면에서 SSP Planner 가 Data를 수정 할경우 Change reason / reason detail Tap을 화면상에 보여주지 않고, Data상으로 T07: 외부 요인으로 Default 설정 필요. */
                            /* 요청에 따라 CHANGE_REASON_CODE, CHANGE_REASON_DETAIL 을 Default 'T07' 로 설정 */
                          , 'T07'
                          , 'T07'
                          , NULL
                          , 'Y'
                          , P_USER_ID
                          , V_CREATE_DATE
                          , P_USER_ID
                          , V_CREATE_DATE
                          , V_ELECTRODE_YN
                          , V_ELECTRODE_TYPE
                          , V_ORIGIN_FROM_DIVISION_ID
                          , V_ORIGION_TO_DIVISION_ID
                           );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                IF V_SHIPMENT_QTY IS NULL
                THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL
                THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF V_SHIPMENT_DATE   IS NOT NULL
                   AND LENGTH(RTRIM(V_SHIPMENT_DATE)) = 8
                   AND V_NEW_CUSTOMER_LT IS NOT NULL
                   AND LENGTH(RTRIM(V_NEW_CUSTOMER_LT)) > 0
                THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                       (CHANGE_REQ_NO
                      , CONFIRM_ID
                      , NEW_YN
                      , DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , NEW_YYYYMMDD
                      , NEW_QTY
                      , NEW_BOD_ID
                      , NEW_ROUTE_ID
                      , NEW_ETD_DATE
                      , NEW_ETA_DATE
                      , NEW_INCOTERMS
                      , NEW_TRANSPORT_MODE
                      , NEW_D_COUNTRY
                      , NEW_D_PORT_CODE
                      , NEW_A_COUNTRY
                      , NEW_A_PORT_CODE
                      , NEW_CUSTOMER_LT
                      , NEW_TO_COUNTRY
                      , NEW_TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , VALID_YN
                      , ATTRIBUTE1
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , REQUESTOR
                       )
                SELECT V_MAX_REQ_NO
                     , CONFIRM_ID
                     , 'N'
                     , DIVISION_ID
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , V_SHIPMENT_DATE
                     , TO_NUMBER(V_SHIPMENT_QTY)
                     , V_NEW_BOD_ID_TEMP
                     , TO_NUMBER(V_NEW_ROUTE_ID_TEMP)
                     , V_NEW_ETD_DATE
                     , V_NEW_ETA_DATE
                     , V_NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , V_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , ERP_SO_NO
                     , ERP_SO_ITEM_NO
                     , ERP_DO_NO
                     , ERP_STATUS
                     , 'Y'
                     , 'N'
                     , P_USER_ID
                     , V_CREATE_DATE
                     , P_USER_ID
                     , V_CREATE_DATE
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , REQUESTOR
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;  /* V_EDIT_MAIN = 'Y' End */

        END LOOP;    /* While End */

        IF V_BOD_NOT_FOUND = 'Y'
        THEN

            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := '';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            COMMIT;

            OPEN O_RC1 FOR SELECT 'X'  AS RESULT_CODE
                                , NULL AS REQUEST_NO
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                             FROM DUAL
                            WHERE 1 = 0;

            RETURN;

        END IF;

        /* ERP전송 Table(XIF_ERP_PACK_SHIP_PLAN_S_SN) Insert */
        /* 출하확정변경시 ERP 전송 이터 테이블 저장 B: 변경확정 */
        /* PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_PACKER 는 Oracle 미이관(2026.09.22 기준) */
        /* PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_PACKER('B', V_MAX_REQ_NO); */

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        COMMIT;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR SELECT 'S'          AS RESULT_CODE
                            , V_MAX_REQ_NO AS REQUEST_NO
                         FROM DUAL;
        OPEN O_RC2 FOR SELECT NULL AS ERR_MESSAGE
                         FROM DUAL
                        WHERE 1 = 0;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_CODE    := SQLCODE;
            V_ERR_MESSAGE := SQLERRM;

            ROLLBACK TO SP_SSP0015_SAVE_DRAFT_PK;

            INSERT INTO SCM_SYS_LOG_BATCH
                   (PROGRAM_NAME, LOG_TYPE, LOG_COUNT, LOG_MESSAGE, DESCRIPTION
                  , EVENT_DATE, CREATION_DATE, CREATED_BY, LAST_UPDATE_DATE, LAST_UPDATED_BY)
            VALUES (V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL
                  , SYSDATE, SYSDATE, V_PROGRAM_NAME, SYSDATE, V_PROGRAM_NAME);
            COMMIT;

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR SELECT 'F' AS RESULT_CODE
                             FROM DUAL;
            OPEN O_RC2 FOR SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MESSAGE AS ERR_MESSAGE
                             FROM DUAL;

    END P_SSP0015_SAVE_SHIPMENT_REQUEST_DRAFTING_PACKER;

    /* ============================================================
       P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL_PACKER
       AS-IS SSP0015_GET_SHIPMENT_CONFIRM_DETAIL_PACKER
       ※ AS-IS 는 문자열을 조립해 EXEC 로 실행하지만 결과는 고정 조회다.
          조립되는 조건 갈래가 정해져 있으므로 정적 SQL 로 옮긴다.
       ※ P_REAL_FLAG 값에 따라 결과 칸 구성이 다르다(AS-IS 동일).
          'Y' : 출하확정(SSP_ANL_SHIP_CONFIRM) + 요청(SSP_ANL_SHIP_REQ_P) — 68 칸
          그 외 : 계획(SSP_ANL_SHIP_PLAN_P) 요청분 + 확정분 — 63 칸
       ※ AS-IS FN_GET_IN_STR 로 만든 IN 목록은 FN_STRING_SPLIT 로 옮긴다.
       ※ 숫자 칸(NEW_ROUTE_ID · NEW_CUSTOMER_LT · NEW_LT_DAY)은 AS-IS 에서 UNION ALL 이 숫자로 통일되어
          반대편 '-' 가 0 으로 바뀐다. 같은 값이 되게 숫자로 두고 반대편을 0 으로 맞춘다.
       ※ 고객 조인은 뒤 공백을 떼고 맞춘다 — 출하확정 원장 TO_SITE_SHIPTO_CODE 에 뒤 공백이 있고
          (2026.09.22 기준 사업부 40 에 40건) AS-IS 는 뒤 공백을 무시해 이어지지만 Oracle 은 끊긴다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL_PACKER
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_REQUESTOR             IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_SEARCH_YN             IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2 DEFAULT 'N',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'T',
        P_REAL_FLAG             IN  VARCHAR2 DEFAULT 'N',
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL_PACKER
         * Description  :
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020-11-13   KIMYONGHO 	   신규추가
         * 2024-10-01   KHJ            NERP_SSP
         * 2026.09.22                  MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         * 2026.10.07                  AJS 조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
         */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 먼저 고른다
           조회 문장 안에서 분리 함수를 행마다 부르지 않도록 문장 밖에서 한 번 판정 · 입력 코드 자체도 담아 기존 정확일치 품목 유지 · 닉네임 출처 = SCM_MST_ITEM_SN */
        IF P_ITEM_ID IS NOT NULL AND UPPER(P_ITEM_ID) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT SA.COLUMN_VALUE AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE) AS ITEM_ID
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT XA.ITEM_ID
                      FROM SCM_MST_ITEM_SN XA
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SC
                     WHERE SC.COLUMN_VALUE IS NOT NULL
                       AND (   UPPER(XA.ITEM_ID)   LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%'
                            OR UPPER(XA.NICK_NAME) LIKE '%' || UPPER(SC.COLUMN_VALUE) || '%')) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ERP_SO_NO
                         , A.SHIPMENT_STATUS
                         , F.SOLDTO_CUSTOMER                 AS PROJECT_CODE
                         , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, F.SOLDTO_CUSTOMER) AS PROJECT_NAME
                         , A.FCST_TYPE
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , A.BEFORE_QTY                      AS BEFORE_QTY
                         , TRUNC(A.QTY)                      AS SHIPMENT_CONFIRM_QTY
                         , A.REMARKS
                         , A.REMARKS2
                         , A.REMARKS3
                         , A.FROM_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                         , A.TO_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                         , A.TO_SITE_SOLDTO_CODE
                         , A.TO_SITE_SHIPTO_CODE
                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                         , TC.SHIPTO_DESCRIPTION             AS SHIPTO_DESCRIPTION
                         , A.BOD_ID
                         , B.SSP_INCOTERMS                   AS INCOTERMS
                         , B.TRANSPORT_MODE
                         , B.LT_TOTAL                        AS LT_DAY
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                         , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                                ELSE (SELECT CASE WHEN REGEXP_LIKE(SA.V, '^[0-9]{8}$')
                                                  THEN TO_CHAR(TO_DATE(SA.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                        FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) AS V FROM DUAL) SA)
                           END                               AS EXPECTED_SHIPPING_DATE
                         , A.CONFIRM_ID
                         /* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
--                         , CASE WHEN U.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                           END                               AS UPDATED_BY
                         , CASE WHEN U.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                         /* 2026.09.30 AJS 수정 (END) */
                         , CASE WHEN NVL(TE.ATTRIBUTE5, '-') = '-' THEN '-' ELSE 'C' END AS ERP_STATUS
                         , A.CHANGE_TYPE
                           /* AS-IS 는 UNION ALL 이 숫자로 통일되어 반대편 '-' 가 0 으로 바뀐다. 같은 값이 되게 숫자로 둔다. */
                         , A.ROUTE_ID                        AS NEW_ROUTE_ID
                         , A.BOD_ID                          AS NEW_BOD_ID
                         , B.SSP_INCOTERMS                   AS NEW_INCOTERMS
                         , A.D_COUNTRY                       AS NEW_D_COUNTRY
                         , A.D_PORT_CODE                     AS NEW_D_PORT_CODE
                         , A.A_COUNTRY                       AS NEW_A_COUNTRY
                         , A.A_PORT_CODE                     AS NEW_A_PORT_CODE
                         , A.CUSTOMER_LT                     AS NEW_CUSTOMER_LT
                         , A.TO_COUNTRY                      AS NEW_TO_COUNTRY
                         , A.TO_CITY                         AS NEW_TO_CITY
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETA
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETD
                         , B.LT_TOTAL                        AS NEW_LT_DAY
                         , B.TRANSPORT_MODE                  AS NEW_TRANSPORT_MODE
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_SHIPMENT_DATE
                         , 'N'                               AS EDIT_REMARKS
                         , 'N'                               AS EDIT_MAIN
                         , NVL(A.CHECK_NEED_YN, 'N')         AS CHECK_NEED_YN
                         , NVL(CASE WHEN A.DIVISION_ID = '40'
                                    THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE != '-' THEN A.PROJECT_CODE ELSE G.PROJECT_CODE END
                                    WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                    THEN G.PROJECT_CODE
                                    ELSE F.END_CUSTOMER
                               END, '/')                     AS END_CUSTOMER
                         , A.ELECTRODE_YN
                         , A.ELECTRODE_TYPE
                         , A.ORIGIN_FROM_DIVISION_ID
                         , A.ORIGIN_TO_DIVISION_ID
                         , H.CHANGE_REQ_NO
                         /* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                           END                               AS MODEL_USER
                         , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
                         /* 2026.09.30 AJS 수정 (END) */
                           END                               AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , NULL                              AS CHANGE_REASON_DETAIL
                         , TT1.ATTRIBUTE3                    AS RTF3
                         , TT1.ATTRIBUTE4                    AS RTF4
                         , TT1.ATTRIBUTE5                    AS RTF5
                         , TT1.ATTRIBUTE6                    AS RTF6
                         , A.ATTRIBUTE10                     AS ATTRIBUTE10
                      FROM SSP_ANL_SHIP_CONFIRM A
                         , SCM_MST_SITE MS
                         , SCP_MST_BOD_N_V B
                         , SCM_MST_SITE_CUSTOMER TD
                         , SCM_MST_CUSTOMER TC
                         , SCM_DNM_SCS_SHIP_RESULT TE
                         /* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U
                         , SCM_ADM_USER_M U
                         /* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE F
                         , (SELECT IA.DIVISION_ID
                                 , IA.PROJECT_CODE
                                 , IA.SCM_SITE_ID
                                 , IA.ITEM_ID
                              FROM (SELECT DIVISION_ID
                                         , PROJECT_CODE
                                         , SCM_SITE_ID
                                         , ITEM_ID
                                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                      FROM SCM_MST_SITE_ITEM
                                   ) IA
                             WHERE IA.NUM = 1
                           ) G
                         , (SELECT XA.CONFIRM_ID
                                 , XA.CHANGE_REQ_NO
                              FROM (SELECT CONFIRM_ID
                                         , CHANGE_REQ_NO
                                         , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC) AS NUM
                                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                     WHERE VALID_YN = 'Y'
                                   ) XA
                             WHERE XA.NUM = 1
                           ) H
                         , SSP_MST_MODEL_USER MU
                         /* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U2
--                         , TB_FX_USER U3
                         , SCM_ADM_USER_M U2
                         , SCM_ADM_USER_M U3
                         /* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE_ITEM SI
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ T1
                         , SSP_ANL_SHIP_REQ_P TT1
                     WHERE MS.DIVISION_ID       = A.DIVISION_ID
                       AND MS.SCM_SITE_ID       = A.FROM_SITE
                       AND MS.SITE_TYPE         = 'PLANT'
                       AND MS.OPERATION_GROUP   = 'P'
                       AND MS.OSP_YN            = 'Y'
                       AND B.DIVISION_ID        = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND B.BOD_ID             = A.BOD_ID
                       AND TD.DIVISION_ID(+)    = A.DIVISION_ID
                       AND TD.SCM_SITE_ID(+)    = A.TO_SITE
                       AND RTRIM(TD.SHIPTO_CODE(+)) = RTRIM(A.TO_SITE_SHIPTO_CODE)
                       AND TD.VALID_YN(+)       = 'Y'
                       AND TD.REP_YN(+)         = 'Y'
                       AND TC.DIVISION_ID(+)    = A.DIVISION_ID
                       AND TC.SOLDTO_CODE(+)    = TD.SOLDTO_CODE
                       AND TC.SHIPTO_CODE(+)    = RTRIM(A.TO_SITE_SHIPTO_CODE)
                       AND TC.VALID_YN(+)       = 'Y'
                       AND TE.DIVISION_ID(+)    = A.DIVISION_ID
                       AND TE.SCM_SITE_ID(+)    = A.FROM_SITE
                       AND TE.PACK_MODEL_CODE(+) = A.ITEM_ID
                       AND TE.ATTRIBUTE5(+)     = A.CONFIRM_ID
                       /* 2026.09.30 AJS 수정 (START) */
--                       AND U.USERID(+)          = A.LAST_UPDATED_BY
--                       AND U.USEYN(+)           = 'Y'
                       AND U.USER_ID(+)         = A.LAST_UPDATED_BY
                       AND U.USE_YN(+)          = 'Y'
                       /* 2026.09.30 AJS 수정 (END) */
                       AND F.DIVISION_ID(+)     = A.ORIGIN_TO_DIVISION_ID
                       AND F.SCM_SITE_ID(+)     = A.TO_SITE
                       AND F.VALID_YN(+)        = 'Y'
                       AND G.DIVISION_ID(+)     = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND G.SCM_SITE_ID(+)     = A.TO_SITE
                       AND G.ITEM_ID(+)         = A.ITEM_ID
                       AND H.CONFIRM_ID(+)      = A.CONFIRM_ID
                       AND MU.DIVISION_ID(+)    = A.ORIGIN_FROM_DIVISION_ID
                       AND MU.FROM_SITE(+)      = A.FROM_SITE
                       AND MU.ITEM_ID(+)        = A.ITEM_ID
                       AND MU.VALID_YN(+)       = 'Y'
                       /* 2026.09.30 AJS 수정 (START) */
--                       AND U2.USERID(+)         = MU.USER_ID
--                       AND U2.USEYN(+)          = 'Y'
--                       AND U3.USERID(+)         = A.REQUESTOR
--                       AND U3.USEYN(+)          = 'Y'
                       AND U2.USER_ID(+)        = MU.USER_ID
                       AND U2.USE_YN(+)         = 'Y'
                       AND U3.USER_ID(+)        = A.REQUESTOR
                       AND U3.USE_YN(+)         = 'Y'
                       /* 2026.09.30 AJS 수정 (END) */
                       AND SI.DIVISION_ID(+)    = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND SI.SCM_SITE_ID(+)    = A.TO_SITE
                       AND SI.ITEM_ID(+)        = A.ITEM_ID
                       AND SI.PROJECT_CODE(+)   = G.PROJECT_CODE
                       AND T1.CHANGE_REQ_NO(+)  = H.CHANGE_REQ_NO
                       AND TT1.DIVISION_ID(+)   = A.DIVISION_ID
                       AND TT1.REQUEST_ID(+)    = A.CONFIRM_ID
                       AND A.DIVISION_ID        = '40'
                       AND (P_SEARCH_YN != 'Y'
                             OR ((P_NONCHK = 'Y' AND 1 = 1)
                                  OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                    UNION
                                                    SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                      FROM SSP_MST_DELEGATE
                                                     WHERE VALID_YN    = 'Y'
                                                       AND DELEGATEE_ID = P_USER_ID
                                                     GROUP BY USER_ID)
                                  OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                  OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                       AND A.YYYYMMDD          >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD          <= P_TO_YYYYMMDD
                       AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                             OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                             OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                           OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                             OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                             OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                             /* 2026.09.30 AJS 수정 (START) */
--                             OR A.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                  FROM TB_FX_USER SA
--                                                 WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                    OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             OR A.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                  FROM SCM_ADM_USER_M SA
                                                 WHERE SA.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                    OR SA.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                             /* 2026.09.30 AJS 수정 (END) */
                       AND A.SHIPMENT_STATUS IS NOT NULL
                       AND A.QTY                > 0
                       AND A.CHANGE_TYPE       != 'N'
                       AND A.BIZ_TYPE          != 'E'
                    UNION ALL
                    SELECT T.DIVISION_ID
                         , T.ERP_SO_NO
                         , T.SHIPMENT_STATUS
                         , T.PROJECT_CODE
                         , T.PROJECT_NAME
                         , T.FCST_TYPE
                         , T.ITEM_ID
                         , T.NICK_NAME
                         , CASE WHEN REGEXP_LIKE(T.SHIPMENT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(T.SHIPMENT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , 0                                 AS BEFORE_QTY
                         , T.QTY
                         , T.REMARKS
                         , T.REMARKS2
                         , T.REMARKS3
                         , T.FROM_SITE
                         , T.FROM_SITE_DESCRIPTION
                         , T.TO_SITE
                         , T.TO_SITE_DESCRIPTION
                         , T.TO_SITE_SOLDTO_CODE
                         , T.TO_SITE_SHIPTO_CODE
                         , T.SOLDTO_DESCRIPTION
                         , T.SHIPTO_DESCRIPTION
                         , T.BOD_ID
                         , T.INCOTERMS
                         , T.TRANSPORT_MODE
                         , T.LT_TOTAL
                         , T.ETD_DATE
                         , T.ETA_DATE
                         , T.EXPECTED_SHIPPING_DATE
                         , T.CONFIRM_ID
                         , T.LAST_UPDATED_BY
                         , T.LAST_UPDATE_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
                         , 0                                 AS NEW_ROUTE_ID
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
                         , 0                                 AS NEW_CUSTOMER_LT
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
                         , 0                                 AS NEW_LT_DAY
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , T.PROJECT_CODE                    AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , '-'                               AS CHANGE_REQ_NO
                         , '-'                               AS MODEL_USER
                         , T.MTK_OWNER
                         , T.REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                         , T.RTF3
                         , T.RTF4
                         , T.RTF5
                         , T.RTF6
                         , '-'                               AS ATTRIBUTE10
                      FROM (SELECT TT0.DIVISION_ID
                                 , NULL                      AS ERP_SO_NO
                                 , 'P'                       AS SHIPMENT_STATUS
                                 , F.SOLDTO_CUSTOMER          AS PROJECT_CODE
                                 , TT0.ITEM_ID                AS ITEM_ID
                                 , FN_GET_ITEM_NICKNAME(TT0.DIVISION_ID, TT0.ITEM_ID) AS NICK_NAME
                                 , TT0.DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID
                                 , TT0.DIVISION_ID            AS ORIGIN_TO_DIVISION_ID
                                 , TT1.FROM_SITE              AS FROM_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT1.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                                 , TT1.TO_SITE                AS TO_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT1.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                                 , FN_GET_PROJECT_NAME(TT0.DIVISION_ID, F.SOLDTO_CUSTOMER) AS PROJECT_NAME
                                 , TT0.LAST_UPDATED_BY        AS REQUESTOR
                                 , TT0.QTY
                                 , TT0.YYYYMMDD               AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT1.INCOTERMS
                                 , TT1.TRANSPORT_MODE
                                 , TD.SOLDTO_CODE             AS TO_SITE_SOLDTO_CODE
                                 , TT0.SHIPTO_CODE            AS TO_SITE_SHIPTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT1.FROM_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                                 , TC.SHIPTO_DESCRIPTION      AS SHIPTO_DESCRIPTION
                                 , '-'                        AS REMARKS2
                                 , '-'                        AS REMARKS
                                 , '-'                        AS CHANGE_REQ_NO
                                 , '-'                        AS REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD_DATE
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD') + NVL(TT1.LT_TOTAL, 0), 'YYYY-MM-DD') END AS ETA_DATE
                                 , CASE WHEN TT1.TRANSPORT_MODE = 'TRK' THEN '-'
                                        ELSE (SELECT CASE WHEN REGEXP_LIKE(SB.V, '^[0-9]{8}$')
                                                          THEN TO_CHAR(TO_DATE(SB.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                                FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SB)
                                   END                        AS EXPECTED_SHIPPING_DATE
                                 , TT1.LT_TOTAL
                                 , TT0.LAST_UPDATED_BY
                                 , TT0.LAST_UPDATE_DATE
                                 , '-'                        AS CONFIRM_ID
                                 , TT0.FCST_TYPE              AS FCST_TYPE
                                 , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
                                 , CASE WHEN NVL(TT2.SHIP_FROZEN, 0) > 0
                                        THEN CASE WHEN REGEXP_LIKE(P_PLAN_START_YYYYMMDD, '^[0-9]{8}$')
                                                  THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + NVL(TT2.SHIP_FROZEN, 0), 'YYYYMMDD') END
                                        ELSE P_PLAN_START_YYYYMMDD
                                   END                        AS FROZEN_YYYYMMDD
                                 , TT0.ATTRIBUTE3             AS RTF3
                                 , TT0.ATTRIBUTE4             AS RTF4
                                 , TT0.ATTRIBUTE5             AS RTF5
                                 , TT0.ATTRIBUTE6             AS RTF6
                              FROM SSP_ANL_SHIP_REQ_P TT0
                                 , SCP_MST_BOD_N_V TT1
                                 , SCM_MST_SITE TT2
                                 , SCM_MST_SITE_CUSTOMER TD
                                 , SCM_MST_CUSTOMER TC
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER U3
                                 , SCM_ADM_USER_M U3
                                 /* 2026.09.30 AJS 수정 (END) */
                                 , SCM_MST_SITE F
                                 , SSP_MST_MODEL_USER MU
                                 , SCM_MST_SITE_ITEM SI
                             WHERE TT1.DIVISION_ID      = TT0.DIVISION_ID
                               AND TT1.BOD_ID           = TT0.BOD_ID
                               AND TT2.DIVISION_ID      = TT0.DIVISION_ID
                               AND TT2.SCM_SITE_ID      = TT1.FROM_SITE
                               AND TT2.SITE_TYPE        = 'PLANT'
                               AND TT2.VALID_YN         = 'Y'
                               AND TD.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND TD.SCM_SITE_ID(+)    = TT1.TO_SITE
                               AND RTRIM(TD.SHIPTO_CODE(+)) = RTRIM(TT0.SHIPTO_CODE)
                               AND TD.VALID_YN(+)       = 'Y'
                               AND TD.REP_YN(+)         = 'Y'
                               AND TC.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND TC.SOLDTO_CODE(+)    = TD.SOLDTO_CODE
                               AND TC.SHIPTO_CODE(+)    = RTRIM(TT0.SHIPTO_CODE)
                               AND TC.VALID_YN(+)       = 'Y'
                               /* 2026.09.30 AJS 수정 (START) */
--                               AND U3.USERID(+)         = TT0.LAST_UPDATED_BY
--                               AND U3.USEYN(+)          = 'Y'
                               AND U3.USER_ID(+)        = TT0.LAST_UPDATED_BY
                               AND U3.USE_YN(+)         = 'Y'
                               /* 2026.09.30 AJS 수정 (END) */
                               AND F.DIVISION_ID(+)     = TT0.DIVISION_ID
                               AND F.SCM_SITE_ID(+)     = TT1.TO_SITE
                               AND F.VALID_YN(+)        = 'Y'
                               AND MU.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND MU.FROM_SITE(+)      = TT1.FROM_SITE
                               AND MU.ITEM_ID(+)        = TT0.ITEM_ID
                               AND MU.VALID_YN(+)       = 'Y'
                               AND SI.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND SI.SCM_SITE_ID(+)    = TT1.TO_SITE
                               AND SI.ITEM_ID(+)        = TT0.ITEM_ID
                               AND SI.PROJECT_CODE(+)   = F.SOLDTO_CUSTOMER
                               AND TT0.DIVISION_ID      = P_DIVISION_ID
                               AND TT1.BOD_TYPE         = 'SALES'
                               AND TT0.QTY              > 0
                               AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                                     OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT0.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                     OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                                   OR TT0.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                     OR TT0.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                     OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT1.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                               AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     OR TT0.LAST_UPDATED_BY IN (SELECT DISTINCT SC.USERID
--                                                                  FROM TB_FX_USER SC
--                                                                 WHERE SC.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                                    OR SC.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     OR TT0.LAST_UPDATED_BY IN (SELECT DISTINCT SC.USER_ID
                                                                  FROM SCM_ADM_USER_M SC
                                                                 WHERE SC.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                                    OR SC.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     /* 2026.09.30 AJS 수정 (END) */
                               AND (P_SEARCH_YN != 'Y'
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                            UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN     = 'Y'
                                                               AND DELEGATEE_ID = P_USER_ID
                                                             GROUP BY USER_ID)
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                           ) T
                     WHERE T.SHIPMENT_DATE >= T.FROZEN_YYYYMMDD
                       AND T.SHIPMENT_DATE <= P_TO_YYYYMMDD
                   ) AA
             ORDER BY AA.DIVISION_ID
                    , AA.SHIPMENT_DATE
                    , AA.SHIPMENT_STATUS
                    , AA.FROM_SITE
                    , AA.ITEM_ID
                    , AA.ERP_SO_NO DESC
                    , AA.TO_SITE
                    , AA.PROJECT_CODE
                    , AA.FCST_TYPE;

        ELSE

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT T0.DIVISION_ID
                         , T0.ERP_SO_NO
                         , T0.SHIPMENT_STATUS
                         , T0.PROJECT_CODE
                         , T0.PROJECT_NAME
                         , T0.FCST_TYPE
                         , T0.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(T0.DIVISION_ID, T0.ITEM_ID) AS NICK_NAME
                         , T0.SHIPMENT_DATE
                         , T0.SHIPMENT_CONFIRM_QTY
                         , T0.REMARKS
                         , T0.REMARKS2
                         , T0.REMARKS3
                         , T0.FROM_SITE
                         , T0.FROM_SITE_DESCRIPTION
                         , T0.TO_SITE
                         , T0.TO_SITE_DESCRIPTION
                         , T0.TO_SITE_SOLDTO_CODE
                         , T0.TO_SITE_SHIPTO_CODE
                         , T0.SOLDTO_DESCRIPTION
                         , T0.SHIPTO_DESCRIPTION
                         , T0.BOD_ID
                         , T0.INCOTERMS
                         , T0.TRANSPORT_MODE
                         , T0.LT_DAY
                         , T0.ETD
                         , T0.ETA
                         , T0.EXPECTED_SHIPPING_DATE
                         , T0.CONFIRM_ID
                         , T0.UPDATED_BY
                         , T0.UPDATED_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
                         , '-'                               AS NEW_ROUTE_ID
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
                         , '-'                               AS NEW_CUSTOMER_LT
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
                         , '-'                               AS NEW_LT_DAY
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , T0.END_CUSTOMER                   AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , T0.CHANGE_REQ_NO                  AS CHANGE_REQ_NO
                         , T0.MODEL_USER                     AS MODEL_USER
                         , T0.MTK_OWNER                      AS MTK_OWNER
                         , T0.REQUESTOR                      AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                      FROM (SELECT TT0.DIVISION_ID
                                 , '-'                       AS ERP_SO_NO
                                 , 'P'                       AS SHIPMENT_STATUS
                                 , TT0.ITEM_ID               AS ITEM_ID
                                 , '-'                       AS NICK_NAME
                                 , TT4.FROM_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT4.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                                 , TT4.TO_SITE               AS TO_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT4.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , '-'                       AS PROJECT_NAME
                                 , TT0.REQUESTOR             AS REQUESTOR
                                 , TT0.QTY                   AS SHIPMENT_CONFIRM_QTY
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT4.SSP_INCOTERMS         AS INCOTERMS
                                 , TT4.TRANSPORT_MODE        AS TRANSPORT_MODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SOLDTO_CODE')        AS TO_SITE_SOLDTO_CODE
                                 , TT0.SHIPTO_CODE           AS TO_SITE_SHIPTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                                 , '-'                       AS REMARKS2
                                 , '-'                       AS REMARKS
                                 , '-'                       AS CHANGE_REQ_NO
                                 , '-'                       AS REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.ETD_DATE, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , CASE WHEN REGEXP_LIKE(TT0.ETA_DATE, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                                 , CASE WHEN TT4.TRANSPORT_MODE = 'TRK' THEN '-'
                                        ELSE (SELECT CASE WHEN REGEXP_LIKE(SD.V, '^[0-9]{8}$')
                                                          THEN TO_CHAR(TO_DATE(SD.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                                FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SD)
                                   END                       AS EXPECTED_SHIPPING_DATE
                                 , TT4.LT_TOTAL              AS LT_DAY
                                 , TT1.LAST_UPDATED_BY       AS UPDATED_BY
                                 , TO_CHAR(TT1.LAST_UPDATE_DATE, 'YYYY-MM-DD') AS UPDATED_DATE
                                 , TT1.REQUEST_ID            AS CONFIRM_ID
                                 , TT0.FCST_TYPE             AS FCST_TYPE
                                 , TT2.SOLDTO_CUSTOMER       AS END_CUSTOMER
                                 , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NULL THEN NULL
--                                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NULL THEN NULL
                                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                                 /* 2026.09.30 AJS 수정 (END) */
                                   END                       AS MODEL_USER
                              FROM SSP_ANL_SHIP_PLAN_P TT0
                                 , SSP_ANL_SHIP_REQ_P TT1
                                 , SCP_MST_BOD_N_V TT4
                                 , SCM_MST_SITE TT2
                                 , SSP_MST_MODEL_USER MU
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER U2
                                 , SCM_ADM_USER_M U2
                                 /* 2026.09.30 AJS 수정 (END) */
                                 , SCM_MST_SITE_ITEM SI
                             WHERE TT1.DIVISION_ID(+)   = TT0.DIVISION_ID
                               AND TT1.ITEM_ID(+)       = TT0.ITEM_ID
                               AND TT1.REQUEST_ID(+)    = TT0.REQUEST_ID
                               AND TT4.DIVISION_ID(+)   = TT0.DIVISION_ID
                               AND TT4.BOD_ID(+)        = TT0.BOD_ID
                               AND TT2.DIVISION_ID(+)   = TT1.DIVISION_ID
                               AND TT2.SCM_SITE_ID(+)   = TT4.TO_SITE
                               AND MU.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND MU.FROM_SITE(+)      = TT4.FROM_SITE
                               AND MU.ITEM_ID(+)        = TT0.ITEM_ID
                               AND MU.VALID_YN(+)       = 'Y'
                               /* 2026.09.30 AJS 수정 (START) */
--                               AND U2.USERID(+)         = MU.USER_ID
--                               AND U2.USEYN(+)          = 'Y'
                               AND U2.USER_ID(+)        = MU.USER_ID
                               AND U2.USE_YN(+)         = 'Y'
                               /* 2026.09.30 AJS 수정 (END) */
                               AND SI.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND SI.SCM_SITE_ID(+)    = TT4.TO_SITE
                               AND SI.ITEM_ID(+)        = TT0.ITEM_ID
                               AND SI.PROJECT_CODE(+)   = TT0.PROJECT_CODE
                               AND TT0.DIVISION_ID            = P_DIVISION_ID
                               AND TT0.PLAN_START_YYYYMMDD    = P_PLAN_START_YYYYMMDD
                               AND TT0.MEASURE                = 'SHIP_REQ'
                               AND NVL(TT0.CONFIRM_FLAG, 'N') = 'N'
                               AND TT0.QTY                    > 0
                               AND TT0.YYYYMMDD              >= P_FROM_YYYYMMDD
                               AND TT0.YYYYMMDD              <= P_TO_YYYYMMDD
                               AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                                     OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT0.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                     OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                                   OR TT0.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                     OR TT0.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                     OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT4.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                               AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SE.USERID
--                                                            FROM TB_FX_USER SE
--                                                           WHERE SE.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                              OR SE.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SE.USER_ID
                                                            FROM SCM_ADM_USER_M SE
                                                           WHERE SE.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                              OR SE.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     /* 2026.09.30 AJS 수정 (END) */
                               AND (P_SEARCH_YN != 'Y'
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                            UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN     = 'Y'
                                                               AND DELEGATEE_ID = P_USER_ID
                                                             GROUP BY USER_ID)
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                            UNION ALL
                            SELECT TT0.DIVISION_ID
                                 , '-'                       AS ERP_SO_NO
                                 , 'C'                       AS SHIPMENT_STATUS
                                 , TT0.ITEM_ID               AS ITEM_ID
                                 , '-'                       AS NICK_NAME
                                 , TT4.FROM_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT0.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                                 , TT4.TO_SITE               AS TO_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT4.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , '-'                       AS PROJECT_NAME
                                 , TT0.REQUESTOR             AS REQUESTOR
                                 , TT0.QTY                   AS SHIPMENT_CONFIRM_QTY
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT4.SSP_INCOTERMS         AS INCOTERMS
                                 , TT4.TRANSPORT_MODE        AS TRANSPORT_MODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SOLDTO_CODE')        AS TO_SITE_SOLDTO_CODE
                                 , TT0.SHIPTO_CODE           AS TO_SITE_SHIPTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT4.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                                 , '-'                       AS REMARKS2
                                 , '-'                       AS REMARKS
                                 , '-'                       AS CHANGE_REQ_NO
                                 , '-'                       AS REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.ETD_DATE, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , CASE WHEN REGEXP_LIKE(TT0.ETA_DATE, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                                 , CASE WHEN TT4.TRANSPORT_MODE = 'TRK' THEN '-'
                                        ELSE (SELECT CASE WHEN REGEXP_LIKE(SF.V, '^[0-9]{8}$')
                                                          THEN TO_CHAR(TO_DATE(SF.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                                FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SF)
                                   END                       AS EXPECTED_SHIPPING_DATE
                                 , TT4.LT_TOTAL              AS LT_DAY
                                 , TT1.LAST_UPDATED_BY       AS UPDATED_BY
                                 , TO_CHAR(TT1.LAST_UPDATE_DATE, 'YYYY-MM-DD') AS UPDATED_DATE
                                 , TT0.CONFIRM_ID
                                 , TT0.FCST_TYPE             AS FCST_TYPE
                                 , TT2.SOLDTO_CUSTOMER       AS END_CUSTOMER
                                 , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NULL THEN NULL
--                                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NULL THEN NULL
                                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                                 /* 2026.09.30 AJS 수정 (END) */
                                   END                       AS MODEL_USER
                              FROM SSP_ANL_SHIP_PLAN_P TT0
                                 , SSP_ANL_SHIP_REQ_P TT1
                                 , SCP_MST_BOD_N_V TT4
                                 , SCM_MST_SITE TT2
                                 , SSP_MST_MODEL_USER MU
                                 /* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER U2
                                 , SCM_ADM_USER_M U2
                                 /* 2026.09.30 AJS 수정 (END) */
                                 , SCM_MST_SITE_ITEM SI
                             WHERE TT1.DIVISION_ID(+)   = TT0.DIVISION_ID
                               AND TT1.ITEM_ID(+)       = TT0.ITEM_ID
                               AND TT1.CONFIRM_ID(+)    = TT0.REQUEST_ID
                               AND TT4.DIVISION_ID(+)   = TT0.DIVISION_ID
                               AND TT4.BOD_ID(+)        = TT0.BOD_ID
                               AND TT2.DIVISION_ID(+)   = TT1.DIVISION_ID
                               AND TT2.SCM_SITE_ID(+)   = TT4.TO_SITE
                               AND MU.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND MU.FROM_SITE(+)      = TT4.FROM_SITE
                               AND MU.ITEM_ID(+)        = TT0.ITEM_ID
                               AND MU.VALID_YN(+)       = 'Y'
                               /* 2026.09.30 AJS 수정 (START) */
--                               AND U2.USERID(+)         = MU.USER_ID
--                               AND U2.USEYN(+)          = 'Y'
                               AND U2.USER_ID(+)        = MU.USER_ID
                               AND U2.USE_YN(+)         = 'Y'
                               /* 2026.09.30 AJS 수정 (END) */
                               AND SI.DIVISION_ID(+)    = TT0.DIVISION_ID
                               AND SI.SCM_SITE_ID(+)    = TT4.TO_SITE
                               AND SI.ITEM_ID(+)        = TT0.ITEM_ID
                               AND SI.PROJECT_CODE(+)   = TT0.PROJECT_CODE
                               AND TT0.DIVISION_ID            = P_DIVISION_ID
                               AND TT0.PLAN_START_YYYYMMDD    = P_PLAN_START_YYYYMMDD
                               AND TT0.MEASURE                = 'SHIP_CONFIRM'
                               AND NVL(TT0.CONFIRM_FLAG, 'N') = 'Y'
                               AND TT0.QTY                    > 0
                               AND TT0.YYYYMMDD              >= P_FROM_YYYYMMDD
                               AND TT0.YYYYMMDD              <= P_TO_YYYYMMDD
                               AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                                     OR  UPPER(P_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT0.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                                     OR  UPPER(P_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
--                                   OR TT0.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                     OR TT0.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   --  2026.10.07 AJS
                               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                     OR  UPPER(P_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                     OR TT4.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                               AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
                                     /* 2026.09.30 AJS 수정 (START) */
--                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SG.USERID
--                                                            FROM TB_FX_USER SG
--                                                           WHERE SG.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
--                                                              OR SG.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SG.USER_ID
                                                            FROM SCM_ADM_USER_M SG
                                                           WHERE SG.USER_NM IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
                                                              OR SG.USER_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
                                     /* 2026.09.30 AJS 수정 (END) */
                               AND (P_SEARCH_YN != 'Y'
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                            UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN     = 'Y'
                                                               AND DELEGATEE_ID = P_USER_ID
                                                             GROUP BY USER_ID)
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                           ) T0
                   ) AA
             ORDER BY AA.DIVISION_ID
                    , AA.SHIPMENT_DATE
                    , AA.SHIPMENT_STATUS
                    , AA.FROM_SITE
                    , AA.ITEM_ID
                    , AA.ERP_SO_NO DESC
                    , AA.TO_SITE
                    , AA.PROJECT_CODE
                    , AA.FCST_TYPE;

        END IF;

    END P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL_PACKER;

END PKG_SSP0015;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0015
-- ##### END PACKAGE BODY PKG_SSP0015

-- ##### START PACKAGE BODY PKG_SSP0019
CREATE OR REPLACE PACKAGE BODY PKG_SSP0019
IS
    /*
     * Program ID   : PKG_SSP0019
     * Description  : SSP0019 Shipment Change History 화면 - 출하계획 변경 이력 조회
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.26   ZIONEX         [PJ202650304] MSSQL -> Oracle 전환
     * 2026.10.07   AJS            P_SSP0019_GET_SHIPMENT_CHANGE_HISTORY 조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
     * 2026.10.08   AJS            P_SSP0019_GET_SHIPMENT_CHANGE_HISTORY Model/Nickname 품목 목록 비교 MEMBER OF → IN (SELECT COLUMN_VALUE FROM TABLE(목록)) 2자리 (결과 동일 · 후보가 많을 때 행마다 목록 전체 비교 방지)
     *
     * [전환 공통 규칙]
     * - ★AS-IS 는 조회문 전체를 문자열로 이어 붙여 실행한다(조회조건에 따라 IN 절만 붙인다).
     *   조건마다 붙이고 빼는 것뿐이라 정적 조회문 한 문장으로 옮겼다.
     * - AS-IS WITH 절(CONFIRM_LIST)은 한 번만 참조해 인라인 뷰로 옮겼다.
     * - AS-IS 가 조회조건을 `FN_GET_IN_STR` 로 `'A','B'` 꼴로 만들어 IN 절에 넣던 것은
     *   STRING_SPLIT 로 나눠 견주도록 옮겼다.
     * - AS-IS TOP 1 은 ROWNUM 으로, ISNULL 은 NVL 로, 문자 이어붙이기는 || 로 옮겼다.
     * - ★빈 값과 값 없음을 함께 견주는 자리(`ISNULL(A,'') <> ISNULL(B,'')`)는 DECODE 로 옮겼다.
     *   Oracle 은 빈 문자가 값 없음이라 NVL 로는 AS-IS 와 같아지지 않는다.
     * - ★품목 팝업은 공용(SCM0002)을 그대로 쓴다. 이 패키지에 넣지 않는다(03 등록문 참고).
     */

    C_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'SSP0019_GET_SHIPMENT_CHANGE_HISTORY';

    /* ==============================================================================================
       내부 : 결과 커서 (정상)
       ============================================================================================== */
    PROCEDURE P_OPEN_SUCCESS
    (
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;
    END P_OPEN_SUCCESS;

    /* ==============================================================================================
       내부 : 결과 커서 (오류)
       ============================================================================================== */
    PROCEDURE P_OPEN_ERROR
    (
        P_MESSAGE           IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1'      AS CODE
                 , P_MESSAGE AS MSG
              FROM DUAL;
    END P_OPEN_ERROR;

    /* ==============================================================================================
       내부 : 오류 이력 기록
       ============================================================================================== */
    PROCEDURE P_WRITE_ERROR_LOG
    (
        P_PROGRAM_NAME      IN  VARCHAR2,
        P_MESSAGE           IN  VARCHAR2
    )
    IS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        INSERT INTO SCM_SYS_LOG_BATCH
        (
            PROGRAM_NAME
          , LOG_TYPE
          , LOG_COUNT
          , LOG_MESSAGE
          , DESCRIPTION
          , EVENT_DATE
          , CREATION_DATE
          , CREATED_BY
          , LAST_UPDATE_DATE
          , LAST_UPDATED_BY
        )
        VALUES
        (
            P_PROGRAM_NAME
          , 'ERROR'
          , NULL
          , SUBSTR(P_MESSAGE, 1, 1000)
          , NULL
          , SYSDATE
          , SYSDATE
          , P_PROGRAM_NAME
          , SYSDATE
          , P_PROGRAM_NAME
        );

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
    END P_WRITE_ERROR_LOG;

    /* ==============================================================================================
       SSP0019_GET_SHIPMENT_CHANGE_HISTORY
       ============================================================================================== */
    PROCEDURE P_SSP0019_GET_SHIPMENT_CHANGE_HISTORY
    (
        P_DIVISION_ID       IN  CLOB
      , P_FROM_SITE         IN  CLOB
      , P_TO_SITE           IN  CLOB
      , P_INCOTERMS         IN  CLOB
      , P_FROM_YYYYMMDD     IN  VARCHAR2
      , P_TO_YYYYMMDD       IN  VARCHAR2
      , P_ITEM_ID           IN  CLOB
      , P_SONO              IN  CLOB
      , P_TRANS_MODE        IN  CLOB
      , P_CONFIRM_ID        IN  CLOB
      , P_LANGUAGE          IN  VARCHAR2
      , P_DEBUG_MODE        IN  VARCHAR2
      , O_RC1               OUT SYS_REFCURSOR
      , O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
        V_DIVISION_ID       VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_DIVISION_ID, 1, 32767));
        V_FROM_SITE         VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_FROM_SITE, 1, 32767));
        V_TO_SITE           VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_TO_SITE, 1, 32767));
        V_INCOTERMS         VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_INCOTERMS, 1, 32767));
        V_ITEM_ID           VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_ITEM_ID, 1, 32767));
        V_SONO              VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_SONO, 1, 32767));
        V_TRANS_MODE        VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_TRANS_MODE, 1, 32767));
        V_CONFIRM_ID        VARCHAR2(32767 CHAR) := TO_CHAR(SUBSTR(P_CONFIRM_ID, 1, 32767));
        V_FROM_YYYYMMDD     VARCHAR2(32 CHAR)    := TRIM(P_FROM_YYYYMMDD);
        V_TO_YYYYMMDD       VARCHAR2(32 CHAR)    := TRIM(P_TO_YYYYMMDD);
        V_LANGUAGE          VARCHAR2(32 CHAR)    := UPPER(TRIM(P_LANGUAGE));
        V_ITEM_TAB          T_STR_TAB            := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력 값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 조회 기간 확정 이력 품목 + 입력 값 자체(기존 정확일치 결과가 빠지지 않게) */
        IF TRIM(V_ITEM_ID) IS NOT NULL AND UPPER(V_ITEM_ID) <> 'ALL' THEN
            SELECT DISTINCT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT XA.ITEM_ID
                      FROM SSP_ANL_SHIP_CONFIRM_H XA
                     WHERE XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                    UNION
                    SELECT XB.COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) XB) IA
                 , TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SA
             WHERE SA.COLUMN_VALUE IS NOT NULL
               AND IA.ITEM_ID IS NOT NULL
               AND (   UPPER(IA.ITEM_ID) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'
                    OR EXISTS (SELECT 1
                                 FROM SCM_MST_ITEM_SN XC
                                WHERE XC.ITEM_ID = IA.ITEM_ID
                                  AND UPPER(XC.NICK_NAME) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'));
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.FROM_SITE
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID
                                             ELSE A.DIVISION_ID
                                        END, A.ITEM_ID)                 AS NICK_NAME
                 , A.TO_SITE
                 , NVL(CASE WHEN A.DIVISION_ID = '40'
                            THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-'
                                      THEN A.PROJECT_CODE
                                      ELSE I.PROJECT_CODE
                                 END
                            WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                            THEN I.PROJECT_CODE
                            ELSE J.END_CUSTOMER
                       END, '/')                                        AS END_CUSTOMER
                 , A.CONFIRM_ID
                 , A.H_SEQ                                              AS SEQ
                 , A.SHIPMENT_DATE
                 , A.QTY
                 , A.TRANSPORT_MODE
                 , A.INCOTERMS
                 , A.CUSTOMER_LT
                 , A.ERP_SO_NO
                 , A.TYPE
                 , A.CHANGE_TYPE
                 , A.CHANGE_REASON_CODE
                 , A.CHANGE_REASON_DETAIL
                 /* ★AS-IS 는 이어붙이기에 값 없음이 섞이면 결과 전체가 값 없음이다.
                      Oracle 은 값 없음을 빈 값으로 보므로 이름이 없을 때를 따로 가른다. */
                 , CASE WHEN A.REQUEST_USER IS NULL THEN ''
/* 2026.09.30 AJS 수정 (START) */
--                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN B.USERNAME
--                                  ELSE B.USERNAME_E
                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN B.USER_NM
                                  ELSE B.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END IS NULL THEN NULL
/* 2026.09.30 AJS 수정 (START) */
--                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN B.USERNAME
--                                  ELSE B.USERNAME_E
                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN B.USER_NM
                                  ELSE B.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END || '(' || A.REQUEST_USER || ')'
                   END                                                  AS REQUESTOR
                 , CASE WHEN V_LANGUAGE = 'KO' THEN C.DEPT_NAME_KO
                        ELSE C.DEPT_NAME_EN
                   END                                                  AS REQUESTOR_DEPT_NAME
                 , A.REQUEST_TIME                                       AS REQUEST_DATE
                 , CASE WHEN A.APPROVAL_USER IS NULL THEN ''
/* 2026.09.30 AJS 수정 (START) */
--                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN D.USERNAME
--                                  ELSE D.USERNAME_E
                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN D.USER_NM
                                  ELSE D.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END IS NULL THEN NULL
/* 2026.09.30 AJS 수정 (START) */
--                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN D.USERNAME
--                                  ELSE D.USERNAME_E
                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN D.USER_NM
                                  ELSE D.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END || '(' || A.APPROVAL_USER || ')'
                   END                                                  AS APPROVAL
                 , CASE WHEN V_LANGUAGE = 'KO' THEN F.DEPT_NAME_KO
                        ELSE F.DEPT_NAME_EN
                   END                                                  AS APPROVAL_DEPT_NAME
                 , A.APPROVAL_TIME                                      AS APPROVAL_DATE
                 , A.CHANGE_REQ_NO                                      AS REQUEST_NO
                 , A.REMARKS2                                           AS BUILDING
                 , A.REMARKS                                            AS REMARKS
                 , CASE WHEN A.REQUESTOR IS NULL THEN ''
/* 2026.09.30 AJS 수정 (START) */
--                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN E.USERNAME
--                                  ELSE E.USERNAME_E
                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM
                                  ELSE E.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END IS NULL THEN NULL
/* 2026.09.30 AJS 수정 (START) */
--                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN E.USERNAME
--                                  ELSE E.USERNAME_E
                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM
                                  ELSE E.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END || '(' || A.REQUESTOR || ')'
                   END                                                  AS SHIPMENT_REQUESTOR
                 , A.REMARKS3                                           AS CUSTOMER_REQUIRMENT
                 , (SELECT XA.SOLDTO_DESCRIPTION
                      FROM (SELECT NVL(XB.SOLDTO_DESCRIPTION, '-')      AS SOLDTO_DESCRIPTION
                              FROM SCM_MST_CUSTOMER      XB
                                 , SCM_MST_SITE_CUSTOMER XC
                             /* ★AS-IS 문자 비교는 뒤 공백을 무시한다(도착지 코드 뒤 공백 4행) */
                             WHERE XC.DIVISION_ID   = XB.DIVISION_ID
                               AND RTRIM(XC.SOLDTO_CODE) = RTRIM(XB.SOLDTO_CODE)
                               AND RTRIM(XC.SHIPTO_CODE) = RTRIM(XB.SHIPTO_CODE)
                               AND XC.REP_YN        = 'Y'
                               AND XB.DIVISION_ID   = A.DIVISION_ID
                               AND XC.SCM_SITE_ID   = A.TO_SITE) XA
                     WHERE ROWNUM = 1)                                  AS SOLD_TO_PARTY
                 , (SELECT XA.SHIPTO_DESCRIPTION
                      FROM (SELECT NVL(XB.SHIPTO_DESCRIPTION, '-')      AS SHIPTO_DESCRIPTION
                              FROM SCM_MST_CUSTOMER      XB
                                 , SCM_MST_SITE_CUSTOMER XC
                             /* ★AS-IS 문자 비교는 뒤 공백을 무시한다(도착지 코드 뒤 공백 4행) */
                             WHERE XC.DIVISION_ID   = XB.DIVISION_ID
                               AND RTRIM(XC.SOLDTO_CODE) = RTRIM(XB.SOLDTO_CODE)
                               AND RTRIM(XC.SHIPTO_CODE) = RTRIM(XB.SHIPTO_CODE)
                               AND XC.REP_YN        = 'Y'
                               AND XB.DIVISION_ID   = A.DIVISION_ID
                               AND XC.SCM_SITE_ID   = A.TO_SITE) XA
                     WHERE ROWNUM = 1)                                  AS SHIP_TO_PARTY
                 , CASE WHEN G.USER_ID IS NULL THEN ''
/* 2026.09.30 AJS 수정 (START) */
--                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN H.USERNAME
--                                  ELSE H.USERNAME_E
                        WHEN CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM
                                  ELSE H.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END IS NULL THEN NULL
/* 2026.09.30 AJS 수정 (START) */
--                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN H.USERNAME
--                                  ELSE H.USERNAME_E
                        ELSE CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM
                                  ELSE H.USER_ENG_NM
/* 2026.09.30 AJS 수정 (END) */
                             END || '(' || G.USER_ID || ')'
                   END                                                  AS MODEL_PIC
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE
                        ELSE FN_GET_PROJECT_NAME(A.DIVISION_ID, A.PROJECT_CODE)
                   END                                                  AS PROJECT_NAME
                 , A.FCST_TYPE
                 , FN_GET_SSP_MKT_OWNER_NAME(I.OWNER, ',', V_LANGUAGE)  AS MTK_OWNER
                 , A.LAST_UPDATE_DATE
                 , CASE WHEN A.H_SEQ = 1 THEN NULL
                        ELSE TO_DATE(A.BEFORE_SHIPMENT_DATE, 'YYYYMMDD')
                   END                                                  AS BEFORE_SHIPMENT_DATE
                 , CASE WHEN A.H_SEQ = 1 THEN NULL
                        ELSE NVL(A.BEFORE_QTY, 0)
                   END                                                  AS BEFORE_QTY
                 , CASE WHEN A.H_SEQ = 1 THEN NULL
                        ELSE A.BEFORE_TRANSPORT_MODE
                   END                                                  AS BEFORE_TRANSPORT_MODE
                 , CASE WHEN A.H_SEQ = 1 THEN NULL
                        ELSE A.BEFORE_INCOTERMS
                   END                                                  AS BEFORE_INCOTERMS
                 /* ★빈 값과 값 없음을 함께 견주는 자리 — DECODE 는 값 없음끼리도 같게 본다 */
                 , CASE WHEN DECODE(A.BEFORE_SHIPMENT_DATE, A.NEW_YYYYMMDD, 0, 1) = 1 THEN 'Y'
                        ELSE 'N'
                   END                                                  AS SHIPMENT_DATE_CHANGE
                 , CASE WHEN A.BEFORE_SHIPMENT_DATE IS NULL THEN '-'
                        WHEN A.NEW_YYYYMMDD         IS NULL THEN '-'
                        ELSE CASE WHEN DECODE(A.BEFORE_SHIPMENT_DATE, A.NEW_YYYYMMDD, 0, 1) = 1
                                  THEN TO_CHAR(TO_DATE(A.NEW_YYYYMMDD, 'YYYYMMDD') - TO_DATE(A.BEFORE_SHIPMENT_DATE, 'YYYYMMDD'))
                                  ELSE '-'
                             END
                   END                                                  AS VARIABLE_DATE
                 , CASE WHEN NVL(A.BEFORE_QTY, 0) <> NVL(A.NEW_QTY, 0) THEN 'Y'
                        ELSE 'N'
                   END                                                  AS QTY_CHANGE
                 , ABS(NVL(A.BEFORE_QTY, 0) - NVL(A.NEW_QTY, 0))        AS VARIABLE_QTY
                 , CASE WHEN DECODE(A.BEFORE_TRANSPORT_MODE, A.NEW_TRANSPORT_MODE, 0, 1) = 1 THEN 'Y'
                        ELSE 'N'
                   END                                                  AS TRANS_MODE_CHANGE
                 , CASE WHEN A.BEFORE_SHIPMENT_DATE   = A.NEW_YYYYMMDD
                         AND A.BEFORE_QTY             = A.NEW_QTY
                         AND A.BEFORE_TRANSPORT_MODE  = A.NEW_TRANSPORT_MODE THEN 'Y'
                        ELSE 'N'
                   END                                                  AS REMARKS_CHANGE
                 , A.LAST_SEQ
              FROM (SELECT IA.DIVISION_ID
                         , IA.ORIGIN_FROM_DIVISION_ID
                         , IA.ORIGIN_TO_DIVISION_ID
                         , IA.FROM_SITE
                         , IA.ITEM_ID
                         , IA.TO_SITE
                         , IA.CONFIRM_ID
                         , ROW_NUMBER() OVER (PARTITION BY IA.H_CONFIRM_ID ORDER BY IA.HISTORY_SEQ) AS H_SEQ
                         , IA.YYYYMMDD
                         , TO_DATE(IA.H_YYYYMMDD, 'YYYYMMDD')           AS SHIPMENT_DATE
                         , NVL(IA.H_QTY, 0)                             AS QTY
                         , IA.H_TRANSPORT_MODE                          AS TRANSPORT_MODE
                         , IA.H_INCOTERMS                               AS INCOTERMS
                         , IA.CUSTOMER_LT
                         , IA.H_ERP_SO_NO                               AS ERP_SO_NO
                         , CASE WHEN IA.CHANGE_REQ_NO IS NULL THEN 'New'
                                ELSE CASE WHEN IA.NEW_YN = 'Y' THEN 'New'
                                          ELSE 'Change'
                                     END
                           END                                          AS TYPE
                         , CASE WHEN NVL(IA.REQ_CHANGE_TYPE, 'System Create') = 'A' THEN 'Adjustment'
                                WHEN NVL(IA.REQ_CHANGE_TYPE, 'System Create') IN ('N', 'C', 'P') THEN 'Change Request'
                                ELSE 'System Create'
                           END                                          AS CHANGE_TYPE
                         , IA.CHANGE_REASON_CODE
                         , IA.CHANGE_REASON_DETAIL
                         , IA.REQUEST_USER
                         , IA.REQUEST_DEPT
                         , IA.REQUEST_TIME
                         , IA.APPROVAL_USER
                         , IA.APPROVAL_DEPT
                         , IA.APPROVAL_TIME
                         , IA.CHANGE_REQ_NO
                         , IA.REMARKS2
                         , IA.REMARKS
                         , IA.REQUESTOR
                         , IA.REMARKS3
                         , IA.PROJECT_CODE
                         , IA.FCST_TYPE
                         , NVL(IA.APPROVAL_TIME, IA.CREATION_DATE)      AS LAST_UPDATE_DATE
                         , IA.DE_YYYYMMDD                               AS BEFORE_SHIPMENT_DATE
                         , IA.DE_QTY                                    AS BEFORE_QTY
                         , IA.DE_TRANSPORT_MODE                         AS BEFORE_TRANSPORT_MODE
                         , IA.DE_INCOTERMS                              AS BEFORE_INCOTERMS
                         , IA.NEW_YYYYMMDD
                         , IA.NEW_QTY
                         , IA.NEW_TRANSPORT_MODE
                         , CASE WHEN IA.HISTORY_SEQ = IA.MAX_SEQ THEN 'C'
                                ELSE 'H'
                           END                                          AS LAST_SEQ
                      FROM (SELECT A.DIVISION_ID
                                 , A.ORIGIN_FROM_DIVISION_ID
                                 , A.ORIGIN_TO_DIVISION_ID
                                 , A.FROM_SITE
                                 , A.ITEM_ID
                                 , A.TO_SITE
                                 , A.CONFIRM_ID
                                 , A.PROJECT_CODE
                                 , A.FCST_TYPE
                                 , A.REQUESTOR
                                 , A.CREATION_DATE
                                 , B.YYYYMMDD
                                 , B.MAX_SEQ
                                 , C.CONFIRM_ID                         AS H_CONFIRM_ID
                                 , C.HISTORY_SEQ
                                 , C.YYYYMMDD                           AS H_YYYYMMDD
                                 , C.QTY                                AS H_QTY
                                 , C.TRANSPORT_MODE                     AS H_TRANSPORT_MODE
                                 , C.INCOTERMS                          AS H_INCOTERMS
                                 , C.CUSTOMER_LT
                                 , C.ERP_SO_NO                          AS H_ERP_SO_NO
                                 , C.CHANGE_REQ_NO
                                 , C.REMARKS
                                 , C.REMARKS2
                                 , C.REMARKS3
                                 , D.CHANGE_TYPE                        AS REQ_CHANGE_TYPE
                                 , D.CHANGE_REASON_CODE
                                 , D.CHANGE_REASON_DETAIL
                                 , D.REQUEST_USER
                                 , D.REQUEST_DEPT
                                 , D.REQUEST_TIME
                                 , D.APPROVAL_USER
                                 , D.APPROVAL_DEPT
                                 , D.APPROVAL_TIME
                                 , E.NEW_YN
                                 , E.YYYYMMDD                           AS DE_YYYYMMDD
                                 , E.QTY                                AS DE_QTY
                                 , E.TRANSPORT_MODE                     AS DE_TRANSPORT_MODE
                                 , E.INCOTERMS                          AS DE_INCOTERMS
                                 , E.NEW_YYYYMMDD
                                 , E.NEW_QTY
                                 , E.NEW_TRANSPORT_MODE
                              FROM SSP_ANL_SHIP_CONFIRM               A
                                 , (SELECT IB.DIVISION_ID
                                         , IB.CONFIRM_ID
                                         , MAX(IB.SUBMAX_SEQ)           AS MAX_SEQ
                                         , IB.YYYYMMDD
                                      FROM (SELECT XA.DIVISION_ID
                                                 , XA.CONFIRM_ID
                                                 , MAX(XA.HISTORY_SEQ)  AS SUBMAX_SEQ
                                                 , XA.YYYYMMDD
                                              FROM SSP_ANL_SHIP_CONFIRM_H XA
                                             WHERE XA.YYYYMMDD >= V_FROM_YYYYMMDD
                                               AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                                               AND (TRIM(V_DIVISION_ID) IS NULL
                                                OR  UPPER(V_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                                OR  XA.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                                         FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
                                               AND (TRIM(V_FROM_SITE) IS NULL
                                                OR  UPPER(V_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                                OR  XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                                       FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
                                               AND (TRIM(V_TO_SITE) IS NULL
                                                OR  UPPER(V_TO_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                                OR  XA.TO_SITE IN (SELECT COLUMN_VALUE
                                                                     FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
                                               AND (TRIM(V_INCOTERMS) IS NULL
                                                OR  UPPER(V_INCOTERMS) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                                OR  XA.INCOTERMS IN (SELECT COLUMN_VALUE
                                                                       FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
                                               AND (TRIM(V_ITEM_ID) IS NULL
                                                OR  UPPER(V_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                              OR  XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                                   FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
/*                                              OR  XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                                OR  XA.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                                               AND (TRIM(V_TRANS_MODE) IS NULL
                                                OR  XA.TRANSPORT_MODE IN (SELECT COLUMN_VALUE
                                                                            FROM TABLE(STRING_SPLIT(V_TRANS_MODE, ','))))
                                               AND (TRIM(V_SONO) IS NULL
                                                OR  XA.ERP_SO_NO IN (SELECT COLUMN_VALUE
                                                                       FROM TABLE(STRING_SPLIT(V_SONO, ','))))
                                               /* [C20210722-000075] 조회 조건 추가 */
                                               AND (TRIM(V_CONFIRM_ID) IS NULL
                                                OR  XA.CONFIRM_ID IN (SELECT COLUMN_VALUE
                                                                        FROM TABLE(STRING_SPLIT(V_CONFIRM_ID, ','))))
                                             GROUP BY XA.DIVISION_ID
                                                    , XA.CONFIRM_ID
                                                    , XA.YYYYMMDD) IB
                                         /* ★AS-IS 는 회차 최대값을 상관 조회로 견준다.
                                              이력 원장(105만 행)에 확정번호 인덱스가 없어 묶음마다 전체를 훑는다.
                                              확정번호별 최대 회차를 한 번에 구해 견주도록 바꿨다(171초 -> 아래 7항). */
                                       , (SELECT XB.CONFIRM_ID
                                               , MAX(XB.HISTORY_SEQ)    AS ALL_MAX_SEQ
                                            FROM SSP_ANL_SHIP_CONFIRM_H XB
                                           GROUP BY XB.CONFIRM_ID) IC
                                     WHERE IC.CONFIRM_ID  = IB.CONFIRM_ID
                                       AND IB.SUBMAX_SEQ  = IC.ALL_MAX_SEQ
                                     GROUP BY IB.DIVISION_ID
                                            , IB.CONFIRM_ID
                                            , IB.YYYYMMDD) B
                                 , SSP_ANL_SHIP_CONFIRM_H              C
                                 , SSP_ANL_SHIP_CONFIRM_CHG_REQ        D
                                 , SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE     E
                             WHERE B.DIVISION_ID          = A.DIVISION_ID
                               AND B.CONFIRM_ID           = A.CONFIRM_ID
                               AND C.DIVISION_ID          = A.DIVISION_ID
                               AND C.CONFIRM_ID           = A.CONFIRM_ID
                               AND D.CHANGE_REQ_NO(+)     = C.CHANGE_REQ_NO
                               AND D.CHANGE_REQ_STATUS(+) = 'A'
                               AND D.VALID_YN(+)          = 'Y'
                               AND E.CHANGE_REQ_NO(+)     = C.CHANGE_REQ_NO
                               AND E.CONFIRM_ID(+)        = C.CONFIRM_ID
                               AND E.VALID_YN(+)          = 'Y'
                               AND A.CHANGE_TYPE          = 'C'
                               AND (TRIM(V_DIVISION_ID) IS NULL
                                OR  UPPER(V_DIVISION_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                OR  A.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
                               AND (TRIM(V_FROM_SITE) IS NULL
                                OR  UPPER(V_FROM_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                OR  A.FROM_SITE IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
                               AND (TRIM(V_TO_SITE) IS NULL
                                OR  UPPER(V_TO_SITE) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                OR  A.TO_SITE IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
                               AND (TRIM(V_INCOTERMS) IS NULL
                                OR  UPPER(V_INCOTERMS) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
                                OR  A.INCOTERMS IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
                               AND (TRIM(V_ITEM_ID) IS NULL
                                OR  UPPER(V_ITEM_ID) = 'ALL' /* 조회조건 ALL 은 조건 없음 */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                              OR  A.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                  FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
/*                              OR  A.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                OR  A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                               AND (TRIM(V_TRANS_MODE) IS NULL
                                OR  A.TRANSPORT_MODE IN (SELECT COLUMN_VALUE
                                                           FROM TABLE(STRING_SPLIT(V_TRANS_MODE, ','))))
                               AND (TRIM(V_SONO) IS NULL
                                OR  A.ERP_SO_NO IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(STRING_SPLIT(V_SONO, ','))))) IA) A
/* 2026.09.30 AJS 수정 (START) */
--                 , TB_FX_USER              B
                 , SCM_ADM_USER_M          B
/* 2026.09.30 AJS 수정 (END) */
                 , SCM_MST_SSO_DEPT_INFO   C
/* 2026.09.30 AJS 수정 (START) */
--                 , TB_FX_USER              D
--                 , TB_FX_USER              E
                 , SCM_ADM_USER_M          D
                 , SCM_ADM_USER_M          E
/* 2026.09.30 AJS 수정 (END) */
                 , SCM_MST_SSO_DEPT_INFO   F
                 , SSP_MST_MODEL_USER      G
/* 2026.09.30 AJS 수정 (START) */
--                 , TB_FX_USER              H
                 , SCM_ADM_USER_M          H
/* 2026.09.30 AJS 수정 (END) */
                 , SCM_MST_SITE_ITEM       I
                 , SCM_MST_SITE            J
/* 2026.09.30 AJS 수정 (START) */
--             WHERE B.USERID(+)        = A.REQUEST_USER
--               AND B.USEYN(+)         = 'Y'
             WHERE B.USER_ID(+)       = A.REQUEST_USER
               AND B.USE_YN(+)        = 'Y'
/* 2026.09.30 AJS 수정 (END) */
               AND C.DEPT_ID(+)       = A.REQUEST_DEPT
/* 2026.09.30 AJS 수정 (START) */
--               AND D.USERID(+)        = A.APPROVAL_USER
--               AND D.USEYN(+)         = 'Y'
--               AND E.USERID(+)        = A.REQUESTOR
--               AND E.USEYN(+)         = 'Y'
               AND D.USER_ID(+)       = A.APPROVAL_USER
               AND D.USE_YN(+)        = 'Y'
               AND E.USER_ID(+)       = A.REQUESTOR
               AND E.USE_YN(+)        = 'Y'
/* 2026.09.30 AJS 수정 (END) */
               AND F.DEPT_ID(+)       = A.APPROVAL_DEPT
               AND G.DIVISION_ID(+)   = A.DIVISION_ID
               AND G.FROM_SITE(+)     = A.FROM_SITE
               AND G.ITEM_ID(+)       = A.ITEM_ID
               AND G.VALID_YN(+)      = 'Y'
/* 2026.09.30 AJS 수정 (START) */
--               AND H.USERID(+)        = G.USER_ID
--               AND H.USEYN(+)         = 'Y'
               AND H.USER_ID(+)       = G.USER_ID
               AND H.USE_YN(+)        = 'Y'
/* 2026.09.30 AJS 수정 (END) */
               AND I.DIVISION_ID(+)   = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID
                                             ELSE A.DIVISION_ID
                                        END
               AND I.SCM_SITE_ID(+)   = A.TO_SITE
               AND I.ITEM_ID(+)       = A.ITEM_ID
               AND I.PROJECT_CODE(+)  = A.PROJECT_CODE
               AND J.DIVISION_ID(+)   = A.ORIGIN_TO_DIVISION_ID
               AND J.SCM_SITE_ID(+)   = A.TO_SITE
               /* AS-IS : 회차가 1이고 수량이 0인 행은 뺀다 */
               AND A.H_SEQ = CASE WHEN A.H_SEQ = 1 AND A.QTY = 0 THEN 0
                                  ELSE A.H_SEQ
                             END
             /* ★AS-IS 정렬 순서로 맞춘다(FN_ASIS_SORT_KEY).
                  하이픈을 빼고 견주며 구두점이 숫자·문자보다 앞이고 대소문자를 가리지 않는다.
                  이 화면은 출발사이트(밑줄·하이픈 섞임)와 최종고객(대소문자 섞임)에서 갈린다. */
             ORDER BY FN_ASIS_SORT_KEY(A.DIVISION_ID) NULLS FIRST
                    , FN_ASIS_SORT_KEY(A.FROM_SITE) NULLS FIRST
                    , FN_ASIS_SORT_KEY(A.ITEM_ID) NULLS FIRST
                    , FN_ASIS_SORT_KEY(NVL(CASE WHEN A.DIVISION_ID = '40'
                                                THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-'
                                                          THEN A.PROJECT_CODE
                                                          ELSE I.PROJECT_CODE
                                                     END
                                                WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                                THEN I.PROJECT_CODE
                                                ELSE J.END_CUSTOMER
                                           END, '/')) NULLS FIRST
                    , FN_ASIS_SORT_KEY(A.YYYYMMDD) NULLS FIRST
                    , FN_ASIS_SORT_KEY(A.CONFIRM_ID) NULLS FIRST
                    , A.H_SEQ DESC
                    , A.SHIPMENT_DATE;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG(C_PROGRAM_NAME, SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0019_GET_SHIPMENT_CHANGE_HISTORY;

END PKG_SSP0019;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0019
-- ##### END PACKAGE BODY PKG_SSP0019

-- ##### START PACKAGE BODY PKG_SSP0021
CREATE OR REPLACE PACKAGE BODY PKG_SSP0021
IS
/*
 * Program ID   : PKG_SSP0021
 * Description  : SSP0021 Shipment Plan 화면 프로시저 패키지
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */

    PROCEDURE P_SSP0021_GET_SHIPMENT_DIVISION
    (
        PARAM1                  IN  VARCHAR2
       ,PARAM2                  IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_DIVISION
 * Description  : DIVISION , COMPANY 정보
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/07/15   khj79          DIVISION , COMPANY 정보
 * 2024/10/01   KHJ            NERP_SSP
 * 2026/03/19   강주용         [E20260206-001938] VP 권한 확장
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        /* NERP 매핑코드 */
        V_G480          VARCHAR2(20);
        V_G670          VARCHAR2(20);
        V_G450          VARCHAR2(20);
        V_G630          VARCHAR2(20);
        V_AUTH_TYPE     VARCHAR2(100) := 'D';
    BEGIN

        V_G480 := FN_GET_LOOKUP_VALUE('SSP0021_GET_SHIPMENT_DIVISION', 'G480');
        V_G670 := FN_GET_LOOKUP_VALUE('SSP0021_GET_SHIPMENT_DIVISION', 'G670');
        V_G450 := FN_GET_LOOKUP_VALUE('SSP0021_GET_SHIPMENT_DIVISION', 'G450');
        V_G630 := FN_GET_LOOKUP_VALUE('SSP0021_GET_SHIPMENT_DIVISION', 'G630');

        IF (PARAM1 = 'JV Planner') THEN
            V_AUTH_TYPE := 'J';
        END IF;

        /* START [E20260206-001938] VP 권한 확장 */
        /* AS-IS 의 임시테이블 #returnTable 은 인라인 뷰로 대체 */
        OPEN O_RC1 FOR
            SELECT IA.CODE
                 , MAX(IA.NAME) AS NAME
                 , MAX(IA.ATTRIBUTE1) AS ATTRIBUTE1
              FROM (/* 일반권한 */
                    SELECT A.DIVISION_ID AS CODE
                         , A.DIVISION_ID || ' ' || MIN(A.DIVISION_NAME) AS NAME
                         , 1 AS ATTRIBUTE1                                  /* [E20260206-001938] VP 권한 확장 */
                      FROM SCM_MST_DIVISION A
                     /* 2026.09.30 AJS 수정 (START) */
--                     WHERE A.DIVISION_ID IN (SELECT XA.CODE
--                                               FROM TB_FX_USERGROUPAUTHEXTENTION XA
--                                              WHERE XA.GROUPID = PARAM1
--                                                AND XA.USERID = PARAM2
--                                                AND XA.AUTHTYPE = V_AUTH_TYPE)
                     WHERE A.DIVISION_ID IN (SELECT XA.UNIT_ID
                                               FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XA
                                              /* WHERE XA.USER_GR_ID = PARAM1 */
                                              WHERE (XA.USER_GR_ID = PARAM1 OR (PARAM1 IS NULL AND XA.USER_GR_ID IN (SELECT SA.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M SA WHERE SA.USER_ID = PARAM2 AND SA.USE_YN = 'Y')))   /* AJS 20261007 화면검증 */
                                                AND XA.USER_ID = PARAM2
                                                AND XA.UNIT_TP_CD = V_AUTH_TYPE)
                     /* 2026.09.30 AJS 수정 (END) */
                       AND A.DIVISION_ID <> '40'
                       AND A.ATTRIBUTE3 <> 'EE'
                       AND A.DIVISION_ID NOT IN ('81_UC')                   /* 포함하지 않을 DIVISION 지정, 조건은 알아서 변경할것 */
                     GROUP BY A.DIVISION_ID
                    UNION /* VP 추가 권한 */
                    SELECT A.DIVISION_ID AS CODE
                         , A.DIVISION_ID || ' ' || MIN(A.DIVISION_NAME) AS NAME
                         , 0 AS ATTRIBUTE1
                      FROM SCM_MST_DIVISION A
                     WHERE A.DIVISION_ID IN (SELECT XA.DIVISION_ID
                                               FROM SCM_MST_SITE XA
                                                  , SCM_MST_SITE XB
                                                  /* 2026.09.30 AJS 수정 (START) */
--                                                  , TB_FX_USERGROUPAUTHEXTENTION XC
                                                  , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XC
                                                  /* 2026.09.30 AJS 수정 (END) */
                                              WHERE XA.ATTRIBUTE9 = XB.SCM_SITE_ID
                                                /* 2026.09.30 AJS 수정 (START) */
--                                                AND XB.DIVISION_ID = XC.CODE
                                                AND XB.DIVISION_ID = XC.UNIT_ID
                                                /* 2026.09.30 AJS 수정 (END) */
                                                AND XB.SITE_TYPE = 'PLANT'
                                                /* 2026.09.30 AJS 수정 (START) */
--                                                AND XC.AUTHTYPE = V_AUTH_TYPE
--                                                AND XC.GROUPID = PARAM1
--                                                AND XC.USERID = PARAM2
                                                AND XC.UNIT_TP_CD = V_AUTH_TYPE
                                                /* AND XC.USER_GR_ID = PARAM1 */
                                                AND (XC.USER_GR_ID = PARAM1 OR (PARAM1 IS NULL AND XC.USER_GR_ID IN (SELECT SB.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M SB WHERE SB.USER_ID = PARAM2 AND SB.USE_YN = 'Y')))   /* AJS 20261007 화면검증 */
                                                AND XC.USER_ID = PARAM2
                                                /* 2026.09.30 AJS 수정 (END) */
                                                AND XB.DIVISION_ID NOT IN ('81_UC')  /* 포함하지 않을 DIVISION 지정, 조건은 알아서 변경할것 */
                                                AND XB.DIVISION_ID <> '40')
                       AND A.DIVISION_ID NOT IN ('81_UC')                   /* 포함하지 않을 DIVISION 지정, 조건은 알아서 변경할것 */
                       AND A.DIVISION_ID <> '40'
                       AND A.ATTRIBUTE3 <> 'EE'
                     GROUP BY A.DIVISION_ID) IA
             GROUP BY IA.CODE
             ORDER BY CODE ASC;

        /* 일반 권한 */
        OPEN O_RC2 FOR
            SELECT IA.CODE
                 , IA.NAME
                 , IA.DIVISION_ID
              FROM (SELECT A.COMPANY_ID AS CODE
                         , B.SEGMENT2 AS NAME
                         , A.DIVISION_ID
                      FROM SCM_MST_SITE A
                         , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     WHERE A.COMPANY_ID = B.SEGMENT1
                       AND B.LOOKUP_TYPE = 'COMPANY_DESC'
                       AND A.SITE_TYPE = 'PLANT'
                       /* AND S.COMPANY_ID NOT IN ('G480','G670') -- 포함하지 않을 COMPANY 지정, 조건은 알아서 변경할것 */
                       AND (A.COMPANY_ID <> V_G480
                        AND A.COMPANY_ID <> V_G670
                        /* AND S.COMPANY_ID != @v_G450 */
                        /* AND S.COMPANY_ID != @v_G630 */
                           )                                                /* 표시하고자 하는 COMPANY 지정 */
                       /* START [E20260206-001938] VP 권한 확장 */
                       AND A.DIVISION_ID IN (SELECT XA.DIVISION_ID
                                               FROM SCM_MST_DIVISION XA
                                              /* 2026.09.30 AJS 수정 (START) */
--                                              WHERE XA.DIVISION_ID IN (SELECT XB.CODE
--                                                                         FROM TB_FX_USERGROUPAUTHEXTENTION XB
--                                                                        WHERE XB.GROUPID = PARAM1
--                                                                          AND XB.USERID = PARAM2
--                                                                          AND XB.AUTHTYPE = V_AUTH_TYPE)
                                              WHERE XA.DIVISION_ID IN (SELECT XB.UNIT_ID
                                                                         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XB
                                                                        /* WHERE XB.USER_GR_ID = PARAM1 */
                                                                        WHERE (XB.USER_GR_ID = PARAM1 OR (PARAM1 IS NULL AND XB.USER_GR_ID IN (SELECT SC.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M SC WHERE SC.USER_ID = PARAM2 AND SC.USE_YN = 'Y')))   /* AJS 20261007 화면검증 */
                                                                          AND XB.USER_ID = PARAM2
                                                                          AND XB.UNIT_TP_CD = V_AUTH_TYPE)
                                              /* 2026.09.30 AJS 수정 (END) */
                                                AND XA.DIVISION_ID <> '40'
                                                AND XA.ATTRIBUTE3 <> 'EE'
                                                AND XA.DIVISION_ID NOT IN ('81_UC'))
                     GROUP BY A.COMPANY_ID, B.SEGMENT2, A.DIVISION_ID
                    UNION /* VP 추가 권한 */
                    SELECT A.COMPANY_ID AS CODE
                         , B.SEGMENT2 AS NAME
                         , A.DIVISION_ID
                      FROM SCM_MST_SITE A
                         , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     WHERE A.COMPANY_ID = B.SEGMENT1
                       AND B.LOOKUP_TYPE = 'COMPANY_DESC'
                       AND A.SITE_TYPE = 'PLANT'
                       AND (A.COMPANY_ID <> V_G480
                        AND A.COMPANY_ID <> V_G670)
                       AND A.ATTRIBUTE9 IN (SELECT XA.SCM_SITE_ID
                                              FROM SCM_MST_SITE XA
                                                 /* 2026.09.30 AJS 수정 (START) */
--                                                 , TB_FX_USERGROUPAUTHEXTENTION XB
--                                             WHERE XA.DIVISION_ID = XB.CODE
                                                 , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XB
                                             WHERE XA.DIVISION_ID = XB.UNIT_ID
                                                 /* 2026.09.30 AJS 수정 (END) */
                                               AND XA.SITE_TYPE = 'PLANT'
                                               /* 2026.09.30 AJS 수정 (START) */
--                                               AND XB.AUTHTYPE = V_AUTH_TYPE
--                                               AND XB.GROUPID = PARAM1
--                                               AND XB.USERID = PARAM2
                                               AND XB.UNIT_TP_CD = V_AUTH_TYPE
                                               /* AND XB.USER_GR_ID = PARAM1 */
                                               AND (XB.USER_GR_ID = PARAM1 OR (PARAM1 IS NULL AND XB.USER_GR_ID IN (SELECT SD.USER_GR_ID FROM SCM_ADM_USER_GR_MPG_M SD WHERE SD.USER_ID = PARAM2 AND SD.USE_YN = 'Y')))   /* AJS 20261007 화면검증 */
                                               AND XB.USER_ID = PARAM2
                                               /* 2026.09.30 AJS 수정 (END) */
                                               AND XA.DIVISION_ID NOT IN ('81_UC')  /* 포함하지 않을 DIVISION 지정, 조건은 알아서 변경할것 */
                                               AND XA.DIVISION_ID <> '40'
                                               AND XA.COMPANY_ID <> 'MI00')
                     GROUP BY A.COMPANY_ID, B.SEGMENT2, A.DIVISION_ID) IA
             GROUP BY IA.CODE, IA.NAME, IA.DIVISION_ID;
        /* END [E20260206-001938] VP 권한 확장 */

    END P_SSP0021_GET_SHIPMENT_DIVISION;

    PROCEDURE P_SSP0021_GET_SHIPMENT_FROM_SITE
    (
        PARAM1                  IN  VARCHAR2
       ,PARAM2                  IN  VARCHAR2
       ,PARAM3                  IN  VARCHAR2
       ,PARAM4                  IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_FROM_SITE
 * Description  : Company에 따른 From_Site Load
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/08/23   mcTheJ         신규작성
 * 2026/03/17   강주용         E20260206-001938 VP 권한 확장
 * 2026/09/03   강주용         [E20260831-000063] VILD_YN 적용
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_AUTH_TYPE     VARCHAR2(100) := 'D';
    BEGIN

        IF (PARAM1 = 'JV Planner') THEN
            V_AUTH_TYPE := 'J';
        END IF;

        /* AS-IS 의 테이블 변수 @exception_company 는 NOT EXISTS 서브쿼리로 대체 */
        /* [NERP]COMPANY 예외적용--NERP (IT20250117A) */
        OPEN O_RC1 FOR
            SELECT IA.CODE
                 , IA.NAME
              FROM (SELECT A.SCM_SITE_ID AS CODE
                         , A.SITE_DESCRIPTION AS NAME
                      FROM SCM_MST_SITE A
                     WHERE A.SITE_TYPE = 'PLANT'
                       AND A.OPERATION_GROUP <> 'E'
                       AND (TRIM(PARAM1) IS NULL OR A.DIVISION_ID = PARAM1)
                       AND (TRIM(PARAM2) IS NULL OR A.COMPANY_ID = PARAM2)
                       AND NOT EXISTS (SELECT 1                             /* [NERP]COMPANY 예외적용--NERP (IT20250117A) */
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                        WHERE XA.LOOKUP_TYPE = 'SSP_UI_EXCEPT_COMPANY'
                                          AND UPPER(XA.VALID_YN) = 'Y'
                                          AND PARAM2 = XA.SEGMENT1)
                       /* START CSR */
                       /* 2026.09.30 AJS 수정 (START) */
--                       AND A.DIVISION_ID IN (SELECT XA.CODE
--                                               FROM TB_FX_USERGROUPAUTHEXTENTION XA
--                                              WHERE XA.GROUPID = PARAM3
--                                                AND XA.USERID = PARAM4
--                                                AND XA.AUTHTYPE = V_AUTH_TYPE)
                       AND A.DIVISION_ID IN (SELECT XA.UNIT_ID
                                               FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XA
                                              WHERE XA.USER_GR_ID = PARAM3
                                                AND XA.USER_ID = PARAM4
                                                AND XA.UNIT_TP_CD = V_AUTH_TYPE)
                       /* 2026.09.30 AJS 수정 (END) */
                       /* START [E20260831-000063] VILD_YN 적용 */
                       AND A.VALID_YN = 'Y'
                       /* END [E20260831-000063] VILD_YN 적용 */
                    UNION ALL
                    SELECT A.SCM_SITE_ID AS CODE
                         , A.SITE_DESCRIPTION AS NAME
                      FROM SCM_MST_SITE A
                     WHERE A.SITE_TYPE = 'PLANT'
                       AND A.OPERATION_GROUP <> 'E'
                       AND (TRIM(PARAM1) IS NULL OR A.DIVISION_ID = PARAM1)
                       AND (TRIM(PARAM2) IS NULL OR A.COMPANY_ID = PARAM2)
                       AND NOT EXISTS (SELECT 1                             /* [NERP]COMPANY 예외적용--NERP (IT20250117A) */
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                        WHERE XA.LOOKUP_TYPE = 'SSP_UI_EXCEPT_COMPANY'
                                          AND UPPER(XA.VALID_YN) = 'Y'
                                          AND PARAM2 = XA.SEGMENT1)
                       AND A.ATTRIBUTE9 IN (SELECT XA.SCM_SITE_ID
                                              FROM SCM_MST_SITE XA
                                                 /* 2026.09.30 AJS 수정 (START) */
--                                                 , TB_FX_USERGROUPAUTHEXTENTION XB
--                                             WHERE XA.DIVISION_ID = XB.CODE
                                                 , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XB
                                             WHERE XA.DIVISION_ID = XB.UNIT_ID
                                                 /* 2026.09.30 AJS 수정 (END) */
                                               AND XA.SITE_TYPE = 'PLANT'
                                               /* 2026.09.30 AJS 수정 (START) */
--                                               AND XB.AUTHTYPE = V_AUTH_TYPE
--                                               AND XB.GROUPID = PARAM3
--                                               AND XB.USERID = PARAM4)
                                               AND XB.UNIT_TP_CD = V_AUTH_TYPE
                                               AND XB.USER_GR_ID = PARAM3
                                               AND XB.USER_ID = PARAM4)
                                               /* 2026.09.30 AJS 수정 (END) */
                       /* START [E20260831-000063] VILD_YN 적용 */
                       AND A.VALID_YN = 'Y'
                       /* END [E20260831-000063] VILD_YN 적용 */
                       ) IA
             GROUP BY IA.CODE, IA.NAME;

    END P_SSP0021_GET_SHIPMENT_FROM_SITE;

    PROCEDURE P_SSP0021_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_CONFIRM_ID            IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
       ,O_RC3                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_STATUS
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2020/07/15   khj79          ERP_STATUS 가 'C' 인 경우 수정 못하도록 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND SHIPMENT_STATUS <> 'C';

        OPEN O_RC2 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND QTY = 0;

        OPEN O_RC3 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND ERP_STATUS = 'C';

    END P_SSP0021_GET_SHIPMENT_STATUS;

    PROCEDURE P_SSP0021_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_ERP_SO_NO             IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_ERP_SO_NO_CNT
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT COUNT(*) AS CNT
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID = P_DIVISION_ID
               AND ERP_SO_NO = P_ERP_SO_NO
               AND QTY <> 0;

    END P_SSP0021_GET_ERP_SO_NO_CNT;

    PROCEDURE P_SSP0021_GET_HOLD_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_PLAN_TYPE             IN  VARCHAR2
       ,P_SEQ                   IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_SEARCH_YN             IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_HOLD_STOCK
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/03/05   AYJ            Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/06/17   AYJ            조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
 * 2019/08/28   AYJ            조회 조건 추가(p_delegateeChk)
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_PLAN_START_YYYYMMDD   VARCHAR2(8);
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_PLAN_START_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');

        /* 1. 셀 더블클릭 - BLOCK_STOCK */
        IF P_SEARCH_YN = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.HOLD_ID
                     , A.DIVISION_ID
                     , A.FROM_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD') AS HOLD_YYYYMMDD
                     , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                     , A.HOLD_QTY
                     , A.REMARKS
                     /* AS-IS 는 문자 결합에 NULL 이 섞이면 전체가 NULL — 같은 결과가 되게 분기 */
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) IS NULL THEN NULL
--                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                  FROM SSP_ANL_HOLD_STOCK A
                     /* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER B
                     , SCM_ADM_USER_M B
                     /* 2026.09.30 AJS 수정 (END) */
                     , SSP_MST_MODEL_USER C
                 /* 2026.09.30 AJS 수정 (START) */
--                 WHERE B.USERID(+) = A.LAST_UPDATED_BY
--                   AND B.USEYN(+) = 'Y'
                 WHERE B.USER_ID(+) = A.LAST_UPDATED_BY
                   AND B.USE_YN(+) = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
                   AND C.DIVISION_ID(+) = A.DIVISION_ID
                   AND C.FROM_SITE(+) = A.FROM_SITE
                   AND C.ITEM_ID(+) = A.ITEM_ID
                   AND C.VALID_YN(+) = 'Y'
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND A.FROM_SITE = P_FROM_SITE
                   AND A.HOLD_YYYYMMDD <= V_PLAN_START_YYYYMMDD
                   AND A.RELEASE_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                   AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND A.PLAN_TYPE = P_PLAN_TYPE
                   AND A.SEQ = P_SEQ
--                 AND A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                   /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                   AND A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
                 GROUP BY A.HOLD_ID
                        , A.ITEM_ID
                        , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID)
                        , A.DIVISION_ID
                        , A.FROM_SITE
                        , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                        , A.HOLD_YYYYMMDD
                        , A.RELEASE_YYYYMMDD
                        , A.HOLD_QTY
                        , A.REMARKS
                        , A.LAST_UPDATE_DATE
                        , A.LAST_UPDATED_BY
                        /* 2026.09.30 AJS 수정 (START) */
--                        , B.USERNAME
--                        , B.USERNAME_E
                        , B.USER_NM
                        , B.USER_ENG_NM
                        /* 2026.09.30 AJS 수정 (END) */
                 ORDER BY A.HOLD_ID;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT A.HOLD_ID
                     , A.DIVISION_ID
                     , A.FROM_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD') AS HOLD_YYYYMMDD
                     , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                     , A.HOLD_QTY
                     , A.REMARKS
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) IS NULL THEN NULL
--                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                  FROM SSP_ANL_HOLD_STOCK A
                     /* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER B
                     , SCM_ADM_USER_M B
                     /* 2026.09.30 AJS 수정 (END) */
                     , SSP_MST_MODEL_USER C
                 /* 2026.09.30 AJS 수정 (START) */
--                 WHERE B.USERID(+) = A.LAST_UPDATED_BY
--                   AND B.USEYN(+) = 'Y'
                 WHERE B.USER_ID(+) = A.LAST_UPDATED_BY
                   AND B.USE_YN(+) = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
                   AND C.DIVISION_ID(+) = A.DIVISION_ID
                   AND C.FROM_SITE(+) = A.FROM_SITE
                   AND C.ITEM_ID(+) = A.ITEM_ID
                   AND C.VALID_YN(+) = 'Y'
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND A.HOLD_YYYYMMDD <= V_PLAN_START_YYYYMMDD
                   AND A.RELEASE_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                   AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND A.PLAN_TYPE = P_PLAN_TYPE
                   AND A.SEQ = P_SEQ
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR A.ITEM_ID IN (SELECT COLUMN_VALUE
--                                     FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                    /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB) */
                    OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                     FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                 GROUP BY A.HOLD_ID
                        , A.ITEM_ID
                        , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID)
                        , A.DIVISION_ID
                        , A.FROM_SITE
                        , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                        , A.HOLD_YYYYMMDD
                        , A.RELEASE_YYYYMMDD
                        , A.HOLD_QTY
                        , A.REMARKS
                        , A.LAST_UPDATE_DATE
                        , A.LAST_UPDATED_BY
                        /* 2026.09.30 AJS 수정 (START) */
--                        , B.USERNAME
--                        , B.USERNAME_E
                        , B.USER_NM
                        , B.USER_ENG_NM
                        /* 2026.09.30 AJS 수정 (END) */
                 ORDER BY A.HOLD_ID;

        END IF;

    END P_SSP0021_GET_HOLD_STOCK;

    PROCEDURE P_SSP0021_GET_MES_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_MES_STOCK
 * Description  : Shipment PSI(Small)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/09/15   mcTheJ         Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/09/16   mcTheJ         QMS_MES_Hold Case 수정
 * 2019/09/16   mcTheJ         TOTAL의 합은 RAW DATA의 SUM() -> ROW SUM이 아님
 * 2019/10/28   AYJ            컬럼명 변경 : AVAILABLE_STOCK - > OQC_COMPLETE, 컬럼 추가 : AVAILABLE_STOCK
 * 2022/02/16   SSP Pjt.       SSP_DNM_MES_STOCK_81_82 -> SSP_DNM_GMES_STOCK_81_82
 * 2023/09/01   jilee          반제품->제품 코드 변환 작업
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.ITEM_ID
                     , IA.NICK_NAME
                     , SUM(IA.OQC_INSP_REQUEST) AS OQC_INSP_REQUEST
                     , SUM(IA.BEFORE_OQC) AS BEFORE_OQC
                     , SUM(IA.OQC_NG) AS OQC_NG
                     , SUM(IA.QMS_MES_HOLD) AS QMS_MES_HOLD
                     , SUM(IA.OQC_COMPLETE) AS OQC_COMPLETE
                     /* (SUM(OQC_Insp_Request) + SUM(Before_OQC) + SUM(OQC_NG) + SUM(QMS_MES_Hold) + SUM(Available_Stock)) AS TOTAL */
                     , SUM(NVL(IA.TOTAL, 0)) AS TOTAL
                     , (SUM(NVL(IA.TOTAL, 0)) - SUM(IA.OQC_NG) - SUM(IA.QMS_MES_HOLD)) AS AVAILABLE_STOCK
                  FROM (SELECT ATTRIBUTE5 AS ITEM_ID                            /* jilee 230901 */
                             , PRJT_NAME AS NICK_NAME
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'Inspection Request' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_INSP_REQUEST
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT IS NULL THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS BEFORE_OQC
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , CASE WHEN AVAILABLE_YN = 'Y' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_COMPLETE
                             , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82
                         WHERE DIVISION_ID = P_DIVISION_ID
                           AND COMPANY_ID = P_COMPANY_ID
                           AND YYYYMMDD = P_PLAN_START_YYYYMMDD
--                         AND ATTRIBUTE5 = P_ITEM_ID                           /* jilee 23091 */   --  2026.10.07 AJS
--                           AND ATTRIBUTE5 MEMBER OF V_ITEM_TAB                           /* jilee 23091 */   --  2026.10.07 AJS
                           AND ATTRIBUTE5 = P_ITEM_ID                           /* jilee 23091 */   /* AJS 20261008 Model/Nickname */
                           /* AND ITEM_ID = @p_item_id */
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR FROM_SITE IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                         GROUP BY ATTRIBUTE5, ITEM_ID, PRJT_NAME, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) IA
                 GROUP BY IA.ITEM_ID, IA.NICK_NAME;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT IA.ITEM_ID
                     , IA.NICK_NAME
                     , SUM(IA.OQC_INSP_REQUEST) AS OQC_INSP_REQUEST
                     , SUM(IA.BEFORE_OQC) AS BEFORE_OQC
                     , SUM(IA.OQC_NG) AS OQC_NG
                     , SUM(IA.QMS_MES_HOLD) AS QMS_MES_HOLD
                     , SUM(IA.OQC_COMPLETE) AS OQC_COMPLETE
                     , SUM(NVL(IA.TOTAL, 0)) AS TOTAL
                     , (SUM(NVL(IA.TOTAL, 0)) - SUM(IA.OQC_NG) - SUM(IA.QMS_MES_HOLD)) AS AVAILABLE_STOCK
                  FROM (SELECT ATTRIBUTE5 AS ITEM_ID                            /* jilee 230901 */
                             , PRJT_NAME AS NICK_NAME
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'Inspection Request' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_INSP_REQUEST
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT IS NULL THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS BEFORE_OQC
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , CASE WHEN AVAILABLE_YN = 'Y' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_COMPLETE
                             , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82
                         WHERE DIVISION_ID = P_DIVISION_ID
                           AND COMPANY_ID = P_COMPANY_ID
                           AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR FROM_SITE IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           /* jilee 230901 */
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR ATTRIBUTE5 IN (SELECT COLUMN_VALUE
--                                              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR ATTRIBUTE5 MEMBER OF V_ITEM_TAB) */
                            OR ATTRIBUTE5 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                           /* AND ((@p_item_id IS NULL OR @p_item_id ='')	OR ITEM_ID IN (SELECT token FROM dbo.String_Split(@p_item_id, ','))) */
                         GROUP BY ATTRIBUTE5, ITEM_ID, PRJT_NAME, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) IA
                 GROUP BY IA.ITEM_ID, IA.NICK_NAME;

        END IF;

    END P_SSP0021_GET_MES_STOCK;

    PROCEDURE P_SSP0021_GET_MES_STOCK_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_BOX_ID                IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_MES_STOCK_DETAIL
 * Description  : Shipment PSI(Small)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/09/15   mcTheJ         Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/28   AYJ            검색조건 추가 : BOXID
 * 2022/02/16   SSP Pjt.       SSP_DNM_MES_STOCK_81_82 -> SSP_DNM_GMES_STOCK_81_82
 * 2023/09/01   jilee          반제품->제품 코드 변환 작업
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT BOXID
                     , ATTRIBUTE5 AS PRODID                                     /* jilee 0901 */
                     , PRJT_NAME
                     , AVAILABLE_YN
                     , OQC_INSP_RESULT
                     , LOTID
                     , NVL(LOT_QTY, 0) AS LOT_QTY
                     , CASE WHEN PROD_VALID_DATE = '-' OR PROD_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(PROD_VALID_DATE), 'YYYY-MM-DD') END AS PROD_VALID_DATE
                     , CASE WHEN EXP_INSP_VALID_DATE = '-' OR EXP_INSP_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(EXP_INSP_VALID_DATE), 'YYYY-MM-DD') END AS EXP_INSP_VALID_DATE
                     , MES_HOLD_YN
                     , QMS_HOLD_YN
                     , CASE WHEN MES_HOLD_RELEASE = '-' OR MES_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(MES_HOLD_RELEASE), 'YYYY-MM-DD') END AS MES_UNHOLD_SCHD_DATE
                     , CASE WHEN QMS_HOLD_RELEASE = '-' OR QMS_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(QMS_HOLD_RELEASE), 'YYYY-MM-DD') END AS QMS_UNHOLD_SCHD_DATE
                  FROM SSP_DNM_GMES_STOCK_81_82
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND COMPANY_ID = P_COMPANY_ID
                   AND YYYYMMDD = P_PLAN_START_YYYYMMDD
--                 AND ATTRIBUTE5 = P_ITEM_ID                                   /* jilee 0901 */   --  2026.10.07 AJS
--                   AND ATTRIBUTE5 MEMBER OF V_ITEM_TAB                                   /* jilee 0901 */   --  2026.10.07 AJS
                   AND ATTRIBUTE5 = P_ITEM_ID                                   /* jilee 0901 */   /* AJS 20261008 Model/Nickname */
                   /* AND ITEM_ID = @p_item_id */
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR FROM_SITE IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))));

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT BOXID
                     , ATTRIBUTE5 AS PRODID                                     /* jilee 0901 */
                     , PRJT_NAME
                     , AVAILABLE_YN
                     , OQC_INSP_RESULT
                     , LOTID
                     , NVL(LOT_QTY, 0) AS LOT_QTY
                     , CASE WHEN PROD_VALID_DATE = '-' OR PROD_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(PROD_VALID_DATE), 'YYYY-MM-DD') END AS PROD_VALID_DATE
                     , CASE WHEN EXP_INSP_VALID_DATE = '-' OR EXP_INSP_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(EXP_INSP_VALID_DATE), 'YYYY-MM-DD') END AS EXP_INSP_VALID_DATE
                     , MES_HOLD_YN
                     , QMS_HOLD_YN
                     , CASE WHEN MES_HOLD_RELEASE = '-' OR MES_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(MES_HOLD_RELEASE), 'YYYY-MM-DD') END AS MES_UNHOLD_SCHD_DATE
                     , CASE WHEN QMS_HOLD_RELEASE = '-' OR QMS_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(QMS_HOLD_RELEASE), 'YYYY-MM-DD') END AS QMS_UNHOLD_SCHD_DATE
                  FROM SSP_DNM_GMES_STOCK_81_82
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND COMPANY_ID = P_COMPANY_ID
                   AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR FROM_SITE IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR ATTRIBUTE5 IN (SELECT COLUMN_VALUE
--                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                    /* OR ATTRIBUTE5 MEMBER OF V_ITEM_TAB) */
                    OR ATTRIBUTE5 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                   AND (TRIM(P_BOX_ID) IS NULL
                    OR BOXID IN (SELECT COLUMN_VALUE
                                   FROM TABLE(STRING_SPLIT(P_BOX_ID, ','))));

        END IF;

    END P_SSP0021_GET_MES_STOCK_DETAIL;

    PROCEDURE P_SSP0021_GET_OWMS_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_OWMS_DETAIL
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/09/10   mcTheJ         Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2022.04.23   SSP Pjt.       C20220419-000607 / SSP~oWMS 사외창고 재고 I/F개선 요청
 * 2026.09.10   강주용         [E20260910-001263] Shipment Plan(Auto & ESS) 화면 하단 oWMS Detail 확인 요청
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_BOH_YYYYMMDD      VARCHAR2(8);
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                             , A.GRADE
                             , A.CAPACITY_GRADE AS CAPA_GRADE
                             , A.SOC
                             , A.LOT_ID
                             , A.PALLET_ID
                             , A.STOCK_QTY
                             , A.AVAILABLE_QTY
                             , A.NON_QC_QTY AS UNDECIDED_QTY
                             , A.ALLOCATION_QTY
                             , A.BLOCK_QTY AS HOLD_QTY
                             , A.PACKING_QTY
                             , A.MOVING_QTY
                             , A.RCVLOC_QTY AS RECEIVING_QTY
                             , A.EXPIRATION_QTY
                             , A.LONG_QTY AS LONG_TERM_QTY
                             , A.PLANT_ID
                             , A.PACKING_STATUS
                             , A.STOCK_STATUS
                             , A.STORAGE_ID || ' ' || C.STORAGE_DESCRIPTION AS STORAGE_ID
                             , A.CUSTOMER_CODE
                             , A.CUSTOMER_NAME
                             /* START [E20260910-001263] Shipment Plan(Auto & ESS) 화면 하단 oWMS Detail 확인 요청 */
                             /* 원본,convert(nvarchar, convert(datetime,a.LOT_DATE,112), 23)  LOT_ISSUE_DATE */
                             , NVL(TO_CHAR(TO_DATE(A.LOT_DATE DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.LOT_DATE) AS LOT_ISSUE_DATE
                             /* END [E20260910-001263] Shipment Plan(Auto & ESS) 화면 하단 oWMS Detail 확인 요청 */
                          FROM SSP_ANL_OWMS_STOCK_C2 A
                             , SCM_ADM_LOOKUP_MASTER_DETAIL B
                             , SCM_MST_SLOC C
                             , SSP_MST_MODEL_USER D
                         WHERE B.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'              /* C20220419-000607 */
                           AND B.VALID_YN = 'Y'
                           AND B.ATTRIBUTE1 = 'Y'
                           AND B.SEGMENT1 = A.STOCK_STATUS
                           AND C.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END)
                           AND C.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.PLANT_ID(+) = A.PLANT_ID
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.FROM_SITE(+) = A.FROM_SITE
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND D.VALID_YN(+) = 'Y'
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND A.FROM_SITE = P_FROM_SITE
--                         AND A.ITEM_ID = P_ITEM_ID) IA   --  2026.10.07 AJS
                           /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB) IA   --  2026.10.07 AJS */
                           AND A.ITEM_ID = P_ITEM_ID) IA   /* AJS 20261008 Model/Nickname */
                 ORDER BY IA.DIVISION_ID, IA.PLANT_ID, IA.STORAGE_ID, IA.ITEM_ID, IA.GRADE, IA.CAPA_GRADE, IA.SOC, IA.LOT_ID, IA.PALLET_ID;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                             , A.GRADE
                             , A.CAPACITY_GRADE AS CAPA_GRADE
                             , A.SOC
                             , A.LOT_ID
                             , A.PALLET_ID
                             , A.STOCK_QTY
                             , A.AVAILABLE_QTY
                             , A.NON_QC_QTY AS UNDECIDED_QTY
                             , A.ALLOCATION_QTY
                             , A.BLOCK_QTY AS HOLD_QTY
                             , A.PACKING_QTY
                             , A.MOVING_QTY
                             , A.RCVLOC_QTY AS RECEIVING_QTY
                             , A.EXPIRATION_QTY
                             , A.LONG_QTY AS LONG_TERM_QTY
                             , A.PLANT_ID
                             , A.PACKING_STATUS
                             , A.STOCK_STATUS
                             , A.STORAGE_ID || ' ' || C.STORAGE_DESCRIPTION AS STORAGE_ID
                             , A.CUSTOMER_CODE
                             , A.CUSTOMER_NAME
                             /* START [E20260910-001263] Shipment Plan(Auto & ESS) 화면 하단 oWMS Detail 확인 요청 */
                             /* 원본,convert(nvarchar, convert(datetime,a.LOT_DATE,112), 23)  LOT_ISSUE_DATE */
                             , NVL(TO_CHAR(TO_DATE(A.LOT_DATE DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD'), A.LOT_DATE) AS LOT_ISSUE_DATE
                             /* END [E20260910-001263] Shipment Plan(Auto & ESS) 화면 하단 oWMS Detail 확인 요청 */
                          FROM SSP_ANL_OWMS_STOCK_C2 A
                             , SCM_ADM_LOOKUP_MASTER_DETAIL B
                             , SCM_MST_SLOC C
                             , SSP_MST_MODEL_USER D
                         WHERE B.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'              /* C20220419-000607 */
                           AND B.VALID_YN = 'Y'
                           AND B.ATTRIBUTE1 = 'Y'
                           AND B.SEGMENT1 = A.STOCK_STATUS
                           AND C.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END)
                           AND C.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.PLANT_ID(+) = A.PLANT_ID
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.FROM_SITE(+) = A.FROM_SITE
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND D.VALID_YN(+) = 'Y'
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR A.ITEM_ID IN (SELECT COLUMN_VALUE
--                                             FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)) IA */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB)))) IA   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                 ORDER BY IA.DIVISION_ID, IA.PLANT_ID, IA.STORAGE_ID, IA.ITEM_ID, IA.GRADE, IA.CAPA_GRADE, IA.SOC, IA.LOT_ID, IA.PALLET_ID;

        END IF;

    END P_SSP0021_GET_OWMS_DETAIL;

    PROCEDURE P_SSP0021_GET_STOCK_LOCATION_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_STOCK_LOCATION_DETAIL
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/09/06   mcThej         Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/14   mcThej         Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT - NICK NAME 추가
 * 2019/10/15   juhlee         Pack 생산 창고 추가 CMA_BMA . 2019.10.15 (requested by 김광희)
 * 2020/01/29   KIMYONGHO      [C20200121-000352]  ESS Packer출하 적용
                                - [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V)
 * 2021/05/27   KIMYONGHO      A/S PLANT ERP 재고 반영  수정
 * 2021/06/01   SSP Pjt.       AS ERP 재고 적용
 * 2021/06/14   SSP Pjt.       화면속도개선(SCM_DNM_STOCK_V -> SSP_DNM_STOCK_C)
 * 2023/09/11   jilee          반제품->제품코드 변환 작업
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_BOH_YYYYMMDD      VARCHAR2(8);
        V_STOCK_YYYYMMDD    VARCHAR2(8);
        V_BOH_DATE          DATE;
        V_STOCK_DATE        DATE;
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 3, 'YYYYMMDD'); /* FROM -3일 */

        /* 재고 테이블의 CUTOFF_DATE 는 날짜 형이라 값 쪽을 날짜로 맞춘다(칸에는 함수 미사용) */
        V_BOH_DATE := TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD');
        V_STOCK_DATE := TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD');

        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             /* jilee 230911 */
                             , NVL(A.ATTRIBUTE1, A.ITEM_ID) AS ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , NVL(B.STORAGE_DESCRIPTION, (SELECT SA.STORAGE_DESCRIPTION
                                                             FROM SCM_MST_SLOC SA
                                                            WHERE SA.PLANT_ID = A.PLANT_ID
                                                              AND SA.STORAGE_ID = A.STORAGE_ID
                                                              AND SA.VALID_YN = 'Y'
                                                              AND ROWNUM = 1)) AS STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_STOCK_C A                                /* SCM_DNM_STOCK_V */
                             , SCM_MST_SLOC B
                             , (SELECT XA.DIVISION_ID
                                     , XA.SCM_SITE_ID
                                     , XA.PLANT_ID
                                     , XA.STORAGE_ID
                                     , XA.LOCATION_CODE
                                  FROM SSP_MST_LOCATION_V XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                                   AND XA.PLANT_ID = XB.PLANT_ID
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.VALID_YN = 'Y'
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                 GROUP BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.PLANT_ID, XA.STORAGE_ID, XA.LOCATION_CODE
                                UNION ALL
                                SELECT DISTINCT XA.SEGMENT1 AS DIVISION_ID
                                     , XA.SEGMENT2 AS SCM_SITE_ID
                                     , XA.SEGMENT3 AS PLANT_ID
                                     , XA.SEGMENT4 AS STORAGE_ID
                                     , 'AS' AS LOCATION_CODE
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.SEGMENT1 = XB.DIVISION_ID
                                   AND XA.SEGMENT2 = XB.SCM_SITE_ID
                                   AND XA.SEGMENT3 = XB.PLANT_ID
                                   AND XA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                                   AND XA.VALID_YN = 'Y'
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.SEGMENT1 = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) C
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = C.DIVISION_ID
                           AND A.STORAGE_ID = C.STORAGE_ID
                           AND A.PLANT_ID = C.PLANT_ID
                           AND A.SCM_SITE_ID = C.SCM_SITE_ID
                           AND C.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.SCM_SITE_ID = P_FROM_SITE
--                         AND (A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                           /* AND (A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                           AND (A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
--                          OR A.ATTRIBUTE1 = P_ITEM_ID)   --  2026.10.07 AJS
                            /* OR A.ATTRIBUTE1 MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ATTRIBUTE1 = P_ITEM_ID)   /* AJS 20261008 Model/Nickname */
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE                 /* 현재일 - 3 */
                           AND A.STOCK_TYPE = 'INVENTORY'
                        /* [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V) */
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , B.STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_ESS_PACKER_STOCK_V A
                             , SCM_MST_SLOC B
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.SCM_SITE_ID = P_FROM_SITE
--                         AND A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                           /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                           AND A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE) IA            /* 현재일 - 3 */
                 ORDER BY IA.COMPANY_ID, IA.DIVISION_ID, IA.FROM_SITE, IA.PLANT_ID, IA.ITEM_ID, IA.STOCK_TYPE, IA.STORAGE_ID;

        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             /* jilee 230911 */
                             , NVL(A.ATTRIBUTE1, A.ITEM_ID) AS ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , NVL(B.STORAGE_DESCRIPTION, (SELECT SA.STORAGE_DESCRIPTION
                                                             FROM SCM_MST_SLOC SA
                                                            WHERE SA.PLANT_ID = A.PLANT_ID
                                                              AND SA.STORAGE_ID = A.STORAGE_ID
                                                              AND SA.VALID_YN = 'Y'
                                                              AND ROWNUM = 1)) AS STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_STOCK_C A                                /* SCM_DNM_STOCK_V */
                             , SCM_MST_SLOC B
                             , (SELECT XA.DIVISION_ID
                                     , XA.SCM_SITE_ID
                                     , XA.PLANT_ID
                                     , XA.STORAGE_ID
                                     , XA.LOCATION_CODE
                                  FROM SSP_MST_LOCATION_V XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                                   AND XA.PLANT_ID = XB.PLANT_ID
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.VALID_YN = 'Y'
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                 GROUP BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.PLANT_ID, XA.STORAGE_ID, XA.LOCATION_CODE
                                UNION ALL
                                SELECT DISTINCT XA.SEGMENT1 AS DIVISION_ID
                                     , XA.SEGMENT2 AS SCM_SITE_ID
                                     , XA.SEGMENT3 AS PLANT_ID
                                     , XA.SEGMENT4 AS STORAGE_ID
                                     , 'AS' AS LOCATION_CODE
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.SEGMENT1 = XB.DIVISION_ID
                                   AND XA.SEGMENT2 = XB.SCM_SITE_ID
                                   AND XA.SEGMENT3 = XB.PLANT_ID
                                   AND XA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                                   AND XA.VALID_YN = 'Y'
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.SEGMENT1 = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) C
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = C.DIVISION_ID
                           AND A.STORAGE_ID = C.STORAGE_ID
                           AND A.PLANT_ID = C.PLANT_ID
                           AND A.SCM_SITE_ID = C.SCM_SITE_ID
                           AND C.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR A.ITEM_ID IN (SELECT COLUMN_VALUE
--                                             FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')))
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR A.ATTRIBUTE1 IN (SELECT COLUMN_VALUE
--                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR A.ATTRIBUTE1 MEMBER OF V_ITEM_TAB) */
                            OR A.ATTRIBUTE1 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE                 /* 현재일 - 3 */
                           AND A.STOCK_TYPE = 'INVENTORY'
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , B.STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_ESS_PACKER_STOCK_V A
                             , SCM_MST_SLOC B
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR A.ITEM_ID IN (SELECT COLUMN_VALUE
--                                             FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB) */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE) IA            /* 현재일 - 3 */
                 ORDER BY IA.COMPANY_ID, IA.DIVISION_ID, IA.FROM_SITE, IA.PLANT_ID, IA.ITEM_ID, IA.STOCK_TYPE, IA.STORAGE_ID;

        END IF;

    END P_SSP0021_GET_STOCK_LOCATION_DETAIL;

    PROCEDURE P_SSP0021_GET_SHIPMENT_RESULT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_TYPE                  IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_MYMODELCHK            IN  VARCHAR2
       ,P_PARTLEADERCHK         IN  VARCHAR2
       ,P_TEAMLEADERCHK         IN  VARCHAR2
       ,P_DELEGATEECHK          IN  VARCHAR2
       ,P_NONCHK                IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_RESULT
 * Description  : Shipment Shipment Result
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/09/26   AYJ            [CSR ID:4037234] 출하계획 대비 실적 Report 개발
 * 2019/12/04   juhlee         [C20191205-000132]  OWMS 출하실적에 반품 내용 적용 ( SSP_DNM_SHIP_RESULT_OWMS_V)
 * 2020/01/21   juhlee         [C20200121-000352]  ESS Packer출하 적용
                                - [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> 'Y' 조건제외)
 * 2020/02/12   KIMYONGHO      [C20200218-000135]  SHIP_TYPE 컬럼추가 및  FROM_STIE, TO_SITE Display 변경 CDOE - > Discription
 * 2020.05.06   KIMYONGHO      [C20200403-000062] [GSCM PI] SSP 출하 실적 집계 중 사외 창고 제외 로직 추가 건
 * 2020.09.15   KIMYONGHO      PLAN_SSP 조회시 AND 조건 일부 변경
 * 2020.09.18   KIMYONGHO      ERP_ORDER_TYPE 주석 처리 Request by 김광희 책임
 * 2021.02.17   KIMYONGHO      실적 조회시 TRNSPORT_MODE, INCOTERMS, ERP_SO_NO, ETA_DATE, ETD_DATE ERP 실적 기준으로 조회 Request by 김광희 책임
 * 2021.04.05   KIMYONGHO      [C20210330-000402] Shipment Plan화면의 실적 조회시 Sales site Mapping 안되는건에 대해서도 전수 표시 요청
 * 2021.05.03   SSP Pjt.       ERP_ORDER_TYPE 주석 처리 해제 Request by 김광희 책임
 * 2021.11.15   KIMYONGHO      Confirm Data Plan Date 기준 조회 처리
 * 2024.06.27   jilee          PrjCode, FP BOM 1Level Child Qty 조회 컬럼 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 같은 조건을 실적 원장 6곳에도 먼저 적용(후보 1,000건 이하 MEMBER OF · 초과 IN(TABLE))
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_ITEM_SMALL_YN         VARCHAR2(1) := 'N';   /* AJS 20261008 Model/Nickname : 후보 1,000건 이하면 Y — 실적 원장 단계 MEMBER OF(인덱스 단계에서 거름) */
        V_ITEM_BIG_YN           VARCHAR2(1) := 'N';   /* AJS 20261008 Model/Nickname : 후보 1,000건 초과면 Y — 실적 원장 단계 IN(TABLE) */
        V_ITEM_BIG_TAB          T_STR_TAB := T_STR_TAB();   /* AJS 20261008 Model/Nickname : 후보가 많을 때만 후보 목록 */
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* AJS 20261008 Model/Nickname : 후보 수에 따라 실적 원장 단계 비교 방식 선택(결과 동일) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
            IF V_ITEM_TAB.COUNT <= 1000 THEN   /* AJS 20261008 Model/Nickname */
                V_ITEM_SMALL_YN := 'Y';   /* AJS 20261008 Model/Nickname */
            ELSE   /* AJS 20261008 Model/Nickname */
                V_ITEM_BIG_YN := 'Y';   /* AJS 20261008 Model/Nickname */
                V_ITEM_BIG_TAB := V_ITEM_TAB;   /* AJS 20261008 Model/Nickname */
            END IF;   /* AJS 20261008 Model/Nickname */
        END IF;   /* AJS 20261008 Model/Nickname */

        OPEN O_RC1 FOR
            SELECT IA.DIVISION_ID
                 , B.COMPANY_ID AS COMPANY_ID
                 , C.SEGMENT2 AS TYPE
                 , IA.ERP_SO_NO
                 , IA.CONFIRM_ID
                 , IA.PROJECT_CODE
                 , IA.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(IA.DIVISION_ID, IA.ITEM_ID) AS NICK_NAME
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.FROM_SITE), IA.FROM_SITE) AS FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.TO_SITE), IA.TO_SITE) AS TO_SITE
                 , IA.END_CUSTOMER
                 , IA.QTY
                 , IA.CHILD_QTY
                 , TO_CHAR(TO_DATE(IA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS YYYYMMDD
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , TO_CHAR(TO_DATE(IA.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD_DATE
                 , TO_CHAR(TO_DATE(IA.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA_DATE
                 , IA.SHIP_TYPE
              FROM (/* CONFIRM_ID ,날짜동일한 기준으로 계획정보의 FROM, TO SITE기준으로 실적 집계 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , XA.CONFIRM_ID AS CONFIRM_ID
                         , XA.PROJECT_CODE AS PROJECT_CODE
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , CASE WHEN P_DIVISION_ID = '82' THEN MAX(XA.RESULT_QTY) ELSE SUM(XA.RESULT_QTY) END AS QTY
                         , CASE WHEN P_DIVISION_ID = '82' THEN MAX(XA.RESULT_QTY * XB.CHILD_QTY) ELSE SUM(XA.RESULT_QTY * XB.CHILD_QTY) END AS CHILD_QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ORDER_NO AS ERP_SO_NO
                                 , SA.EXFACTORY_DATE AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETA_DATE AS ETA_DATE
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , SA.TO_SCM_SITE_ID AS TO_SITE
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.PROJECT_CODE AS PROJECT_CODE
                                 , SUM(SA.EXFACTORY_QTY) AS RESULT_QTY
                              FROM SCM_DNM_EXFACTORY_RESULT SA
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SB
                                 , SCM_MST_SITE SC
                                 , SCM_MST_ITEM_SN SD
                             WHERE SB.LOOKUP_TYPE = 'ERP_SSP_TYPE'              /* LOOKUP에 등록된 공정만 */
                               AND SB.VALID_YN = 'Y'
                               AND SB.SEGMENT1 = SA.SSP_TYPE
                               AND SA.FROM_SCM_SITE_ID = SC.SCM_SITE_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SC.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SD.ITEM_ID
                               AND SA.DIVISION_ID = SD.DIVISION_ID
                               AND SC.COMPANY_ID = SD.COMPANY_ID
                               AND SD.ITEM_TYPE NOT IN ('Q', 'R')
                               AND NVL(SA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND SA.CONFIRM_ID LIKE 'C%'
                               AND SA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.CONFIRM_ID
                                    , SA.ORDER_NO
                                    , SA.EXFACTORY_DATE
                                    , SA.TRANSPORT_MODE
                                    , SA.INCOTERMS
                                    , SA.ETA_DATE
                                    , SA.ETD_DATE
                                    , SA.FROM_SCM_SITE_ID
                                    , SA.TO_SCM_SITE_ID
                                    , SA.PROJECT_CODE
                                    , SA.ITEM_ID) XA
                         , (/* FP BOM 1Level Child Qty */
                            SELECT SA.DIVISION_ID
                                 , SA.MODEL_ID
                                 , SA.CHILD_QTY
                              FROM SCM_MODEL_COMP_TEMP_SN SA
                                 , SCM_ITEM_M_SN SB
                                 , SCM_ITEM_CLASS_M_SN SC
                             WHERE SA.CHILD_COMPANY_ID = SB.COMPANY_ID
                               AND SA.CHILD_DIVISION_ID = SB.DIVISION_ID
                               AND SA.CHILD_SITE_ID = SB.SITE_ID
                               AND SA.CHILD_ITEM_ID = SB.ITEM_ID
                               AND SB.ITEM_CLASS = SC.CLASS_ID
                               AND SC.USE_FLAG = 'Y'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.ALT_PRIORITY = 'Y'
                               AND NVL(SB.ITEM_TYPE, 'H') IN ('P', 'Q', 'H')
                               AND SB.FLOW_ID LIKE 'P%'
                               /* AND (CT.MODEL_ID LIKE 'EH%' OR CT.MODEL_ID LIKE 'EM%' OR CT.MODEL_ID LIKE 'EP%' ) */
                               AND (SA.CHILD_ITEM_ID LIKE 'EH%' OR SA.CHILD_ITEM_ID LIKE 'EM%' OR SA.CHILD_ITEM_ID LIKE 'EP%')) XB
                     WHERE XB.DIVISION_ID(+) = XA.DIVISION_ID
                       AND XB.MODEL_ID(+) = XA.ITEM_ID
                     GROUP BY XA.DIVISION_ID
                            , XA.ERP_SO_NO
                            , XA.FROM_SITE
                            , XA.TO_SITE
                            , XA.PROJECT_CODE
                            , XA.ITEM_ID
                            , XA.TRANSPORT_MODE
                            , XA.INCOTERMS
                            , XA.ETD_DATE
                            , XA.ETA_DATE
                            , XA.YYYYMMDD
                            , XA.CONFIRM_ID
                            , XB.CHILD_QTY
                    UNION ALL
                    /* CONFIRM_ID 없는 실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , XA.PROJECT_CODE AS PROJECT_CODE
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , XA.QTY * XB.CHILD_QTY AS CHILD_QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , '-' AS CONFIRM_ID
                                 , SA.ORDER_NO AS ERP_SO_NO
                                 , SA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , NVL(SG.SEGMENT4, SA.TO_SCM_SITE_ID) AS TO_SITE
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.EXFACTORY_DATE AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETA_DATE AS ETA_DATE
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SA.PROJECT_CODE AS PROJECT_CODE
                                 , SUM(SA.EXFACTORY_QTY) AS QTY
                              FROM SCM_DNM_EXFACTORY_RESULT SA
                                 , SCM_MST_SITE SB
                                 , SCM_MST_ITEM_SN SC
                                 , SCP_MST_FINAL_ITEM SD
                                 , SCM_MST_SITE SE
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SF
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SG
                             WHERE SA.FROM_SCM_SITE_ID = SB.SCM_SITE_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SC.ITEM_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SB.COMPANY_ID = SC.COMPANY_ID
                               AND SC.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SD.ITEM_ID = SA.ITEM_ID                      /* SCP 대상 ITEM만 */
                               AND SD.DIVISION_ID = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID = SA.FROM_SCM_SITE_ID
                               AND SE.DIVISION_ID = SA.DIVISION_ID
                               AND SF.LOOKUP_TYPE = 'ERP_ORDER_TYPE'            /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                               AND SF.VALID_YN = 'Y'
                               AND SF.SEGMENT1 = SA.ORDER_TYPE_CODE
                               AND SG.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'    /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                               AND SG.SEGMENT1(+) = SA.DIVISION_ID
                               AND SG.SEGMENT2(+) = SA.SOLDTO_CODE
                               AND SG.SEGMENT3(+) = SA.SHIPTO_CODE
                               AND NVL(SA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND (SA.CONFIRM_ID IS NULL OR SA.CONFIRM_ID NOT LIKE 'C%')
                               AND SA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               AND SA.STORAGE_ID NOT IN ('6000', '799A')        /* 상품창고제외 */
                               AND NOT EXISTS (SELECT 1
                                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SH
                                                WHERE SH.SEGMENT1 = SA.STORAGE_ID
                                                  AND SH.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                                  AND SH.VALID_YN = 'Y')        /* 사외 창고 제외 LOOKUP 관리 */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ORDER_NO
                                    , SA.FROM_SCM_SITE_ID
                                    , NVL(SG.SEGMENT4, SA.TO_SCM_SITE_ID)
                                    , SA.PROJECT_CODE
                                    , SA.ITEM_ID
                                    , SA.EXFACTORY_DATE
                                    , SA.TRANSPORT_MODE
                                    , SA.INCOTERMS
                                    , SA.ETA_DATE
                                    , SA.ETD_DATE
                                    , SA.FROM_SCM_SITE_ID
                                    , SA.TO_SCM_SITE_ID) XA
                         , (/* FP BOM 1Level Child Qty */
                            SELECT SA.DIVISION_ID
                                 , SA.MODEL_ID
                                 , SA.CHILD_QTY
                              FROM SCM_MODEL_COMP_TEMP_SN SA
                                 , SCM_ITEM_M_SN SB
                                 , SCM_ITEM_CLASS_M_SN SC
                             WHERE SA.CHILD_COMPANY_ID = SB.COMPANY_ID
                               AND SA.CHILD_DIVISION_ID = SB.DIVISION_ID
                               AND SA.CHILD_SITE_ID = SB.SITE_ID
                               AND SA.CHILD_ITEM_ID = SB.ITEM_ID
                               AND SB.ITEM_CLASS = SC.CLASS_ID
                               AND SC.USE_FLAG = 'Y'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.ALT_PRIORITY = 'Y'
                               AND NVL(SB.ITEM_TYPE, 'H') IN ('P', 'Q', 'H')
                               AND SB.FLOW_ID LIKE 'P%'
                               AND (SA.CHILD_ITEM_ID LIKE 'EH%' OR SA.CHILD_ITEM_ID LIKE 'EM%' OR SA.CHILD_ITEM_ID LIKE 'EP%')) XB
                     WHERE XB.DIVISION_ID(+) = XA.DIVISION_ID
                       AND XB.MODEL_ID(+) = XA.ITEM_ID
                    UNION ALL
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'P' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , XA.CONFIRM_ID AS CONFIRM_ID
                         , NULL AS PROJECT_CODE
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , XA.END_CUSTOMER AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , NULL AS CHILD_QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* SSP출하계획 ( confirm된 계획) - Current Version */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ERP_SO_NO AS ERP_SO_NO
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , SA.TO_SITE AS TO_SITE
                                 , CASE WHEN SA.DIVISION_ID = '4O' THEN NVL(SD.PROJECT_CODE, '/')
                                        ELSE NVL(SE.END_CUSTOMER, '-')
                                   END AS END_CUSTOMER
                                 , SA.QTY AS QTY
                                 , SA.YYYYMMDD AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SA.ETA_DATE AS ETA_DATE
                              FROM SSP_ANL_SHIP_CONFIRM SA
                                 , SCM_MST_SITE SB
                                 , SCM_MST_ITEM_SN SC
                                 , SCM_MST_SITE_ITEM SD
                                 , SCM_MST_SITE SE
                             WHERE SA.FROM_SITE = SB.SCM_SITE_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SC.ITEM_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SB.COMPANY_ID = SC.COMPANY_ID
                               AND SC.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SD.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SD.ITEM_ID(+) = SA.ITEM_ID
                               AND SD.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SD.PROJECT_CODE(+) = SA.PROJECT_CODE
                               AND SE.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SA.CHANGE_TYPE = 'C'
                               AND SA.QTY > 0
                               AND P_REAL_FLAG = 'Y'
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               /* 2020.09.15 KIMYONGHO   PLAN_SSP 조회시 AND 조건 일부 변경 */
                               /* ERP 출하 구간과 SSP 출하계획일 구간 미스매치로 일부 데이터 누락될수있음. */
                               /* AND   YYYYMMDD BETWEEN  @p_from_yyyymmdd  AND @p_to_yyyymmdd */
                            UNION ALL
                            /* SSP출하계획 ( confirm된 계획) - OLD Version */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ERP_SO_NO AS ERP_SO_NO
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , SA.TO_SITE AS TO_SITE
                                 , CASE WHEN SA.DIVISION_ID = '4O' THEN NVL(SD.PROJECT_CODE, '/')
                                        ELSE NVL(SE.END_CUSTOMER, '-')
                                   END AS END_CUSTOMER
                                 , SA.SHIPMENT_CONFIRM_QTY AS QTY
                                 , SA.YYYYMMDD AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETD AS ETD_DATE
                                 , SA.ETA AS ETA_DATE
                              FROM SSP_ANL_SHIP_PLAN_ALL SA
                                 , SCM_MST_ITEM_SN SB
                                 , SCM_MST_SITE SC
                                 , SCM_MST_SITE_ITEM SD
                                 , SCM_MST_SITE SE
                             WHERE SA.ITEM_ID = SB.ITEM_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.COMPANY_ID = SB.COMPANY_ID
                               AND SB.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SA.FROM_SITE = SC.SCM_SITE_ID
                               AND SC.SITE_TYPE = 'PLANT'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SC.OPERATION_GROUP <> 'E'
                               AND SD.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SD.ITEM_ID(+) = SA.ITEM_ID
                               AND SD.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SD.PROJECT_CODE(+) = SA.PROJECT_CODE
                               AND SE.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND SA.SHIPMENT_STATUS = 'C'
                               AND SA.SHIPMENT_CONFIRM_QTY > 0
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               AND P_REAL_FLAG = 'N') XA
                     WHERE XA.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                    UNION ALL
                    /* OWMS 실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'O' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , NULL AS PROJECT_CODE
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , NULL AS CHILD_QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , XA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하실적 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , CASE WHEN SA.TO_SITE = '-' THEN SA.CUSTOMER_CODE ELSE SA.TO_SITE END AS TO_SITE
                                 , SUM(SA.LOT_QTY) AS QTY
                                 , SA.PLANT_ISSUE_DATE AS YYYYMMDD
                                 , SA.SHIP_TYPE AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RESULT_OWMS SA
                             WHERE SA.PLANT_ISSUE_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ITEM_ID
                                    , SA.FROM_SITE
                                    , CASE WHEN SA.TO_SITE = '-' THEN SA.CUSTOMER_CODE ELSE SA.TO_SITE END
                                    , SA.PLANT_ISSUE_DATE
                                    , SA.SHIP_TYPE) XA
                    UNION ALL
                    /* OWMS 반품실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'R' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , NULL AS PROJECT_CODE
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , NULL AS CHILD_QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , XA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하 반품 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , '*' AS TO_SITE
                                 , SUM(SA.RECIEPT_QTY) AS QTY
                                 , SA.RECIEPT_DATE AS YYYYMMDD
                                 , NULL AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RETURN_OWMS SA
                             WHERE SA.RECIEPT_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ITEM_ID
                                    , SA.FROM_SITE
                                    , SA.RECIEPT_DATE) XA) IA
                 , SCM_MST_SITE B
                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
                 , SSP_MST_MODEL_USER D
             WHERE B.DIVISION_ID = IA.DIVISION_ID
               AND B.SCM_SITE_ID = IA.FROM_SITE
               AND B.OPERATION_GROUP <> 'E'
               AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE'                   /* LOOKUP에 등록된 공정만 */
               AND C.SEGMENT1 = IA.TYPE
               AND C.VALID_YN = 'Y'
               AND D.DIVISION_ID(+) = IA.DIVISION_ID
               AND D.FROM_SITE(+) = IA.FROM_SITE
               AND D.ITEM_ID(+) = IA.ITEM_ID
               AND D.VALID_YN(+) = 'Y'
               AND IA.DIVISION_ID = P_DIVISION_ID
               AND (TRIM(P_COMPANY_ID) IS NULL
                OR B.COMPANY_ID = P_COMPANY_ID)
               AND (TRIM(P_FROM_SITE) IS NULL
                OR IA.FROM_SITE IN (SELECT COLUMN_VALUE
                                      FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
               AND (TRIM(P_ITEM_ID) IS NULL
                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--              OR IA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                /* OR IA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                OR IA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
               AND (TRIM(P_TYPE) IS NULL
                OR IA.TYPE IN (SELECT COLUMN_VALUE
                                 FROM TABLE(STRING_SPLIT(P_TYPE, ','))))
               /* 체크박스 체크 여부 조회 시작(@p_nonChk = 'Y' : 체크박스 선택 안한 상태) */
               AND (P_NONCHK = 'Y'
                OR D.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                   FROM DUAL
                                  UNION
                                 SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN XA.USER_ID ELSE 'X' END
                                   FROM SSP_MST_DELEGATE XA
                                  WHERE XA.VALID_YN = 'Y'
                                    AND XA.DELEGATEE_ID = P_USER_ID
                                  GROUP BY XA.USER_ID)
                OR D.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                OR D.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             ORDER BY IA.DIVISION_ID, IA.FROM_SITE, IA.YYYYMMDD, IA.ITEM_ID, IA.TO_SITE, C.DISPLAY_SEQ, IA.CONFIRM_ID;

    END P_SSP0021_GET_SHIPMENT_RESULT;

    PROCEDURE P_SSP0021_GET_SHIPMENT_PLAN
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_PLAN
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2019/08/30   mcThej         Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/14   mcThej         Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT - ERP_QTY (ssp->scp), 속도 수정
 * 2019/10/15   juhlee         Pack 생산 창고 추가 CMA_BMA . 2019.10.15 (requested by 김광희)
 * 2019/10/15   mcThej         MES 추가
 * 2019/10/17   juhlee         Pack 생산 창고 추가 CMA_BMA BOH수량에 추가  (requested by 김광희)
 * 2019/10/28   mcThej         BOH = BOH + MES_TOTAL - (MES_OQC_NG + MES_QMS/MES_HOLD)
 * 2020/01/21   juhlee         [C20200121-000352]  ESS Packer출하 적용
                                - [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V)
                                - [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN = 'N' 조건제외)
                                - [C20200121-000352]-3 : Production Plan Measure에 Paker생산계획 추가(SCP_ANL_PRODUCTION_PLAN 의 PROD_PLAN_AMEND measure)
 * 2020/02/13   KIMYONGHO      CONTAINER Measure 수식 변경 , MAIN SHEET 조회 시 TO_SITE 구별 할수 없어 SUM -> MAX 로 변경
 * 2020/03/17   juhlee         BOH 수량에 CMA_BMA 제외 (requested by 김광희)
 * 2021/06/01   SSP Pjt.       AS ERP 재고 적용
 * 2021/06/14   SSP Pjt.       화면속도개선(SCM_DNM_STOCK_V -> SSP_DNM_STOCK_C)
 * 2022/02/16   SSP Pjt.       SSP_DNM_MES_STOCK_81_82 -> SSP_DNM_GMES_STOCK_81_82
 * 2022.04.23   SSP Pjt.       C20220419-000607 / SSP~oWMS 사외창고 재고 I/F개선 요청
 * 2023/09/01   jilee          반제품->제품 코드 변환 작업
 * 2024/02/19   jilee          SSP - NEW FP Ship Avaliable 신규 I/F 반영
 * 2024/05/10   hsbang         확정구간 조회 일수(CONFIRM_DAY)를 펑션 FN_GET_ANL_SHIP_FROZEN_DAY_CNT] 에서 가져오도록 반영
 * 2024/10/01   KHJ            NERP_SSP
 * 2026/07/13   강주용         [E20260629-000020] SSP 출하 계획 변경 FP 생산기반 수행시 발생, 조회 UI 수정
 * 2026/08/13   강주용         [E20260811-000692] ESMI AZ 링크 2호기 생산계획 받아오지 못하는 현상 처리
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 - 입고예정(PROD_PLAN) 도착일 함수를 인자 조합마다 1회 호출(결과 동일)
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_FROM_YYYYMMDD         VARCHAR2(8);
        V_TO_YYYYMMDD           VARCHAR2(8);
        V_BOH_YYYYMMDD          VARCHAR2(8);
        V_STOCK_YYYYMMDD        VARCHAR2(8);
        V_BOH_DATE              DATE;
        V_STOCK_DATE            DATE;
        V_CNT_USR_MEASURE       NUMBER := 0;
        V_APP_TYPE              VARCHAR2(8) := 'SSP';
        V_QRY_SUM               CLOB;
        V_EXEC                  CLOB;
        /* FP 자동생성 대상 계산용 */
        V_TMP_WH_STOCK          NUMBER;
        V_TMP_SP_QTY            NUMBER;
        V_TMP_FP_QTY            NUMBER;
        V_TMP_CFM_QTY           NUMBER;
        V_FROZEN_YYYYMMDD       VARCHAR2(8);
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_FROM_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');
        V_TO_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_TO_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');
        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');    /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 3, 'YYYYMMDD');  /* FROM -3일 */

        /* 재고 테이블의 CUTOFF_DATE 는 날짜 형이라 값 쪽을 날짜로 맞춘다(칸에는 함수 미사용) */
        V_BOH_DATE := TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD');
        V_STOCK_DATE := TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD');

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID;

        /********************************************************************************
        * 임시테이블만들기
        ********************************************************************************/
        DELETE FROM GT_0021_BOH_STORAGE;
        DELETE FROM GT_0021_BOH;
        DELETE FROM GT_0021_ROWDATA;
        DELETE FROM GT_0021_RESULT;
        DELETE FROM GT_0021_PIVOT;
        DELETE FROM GT_0021_PIVOT_OLD;
        DELETE FROM GT_0021_TITLESET;

        INSERT INTO GT_0021_TITLESET
        (
            COLUMN_NAME
        )
        SELECT COLUMN_NAME
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID;

        /********************************************************************************/

        /*--//////////////////////////////////////////////////////////////////////////////--*/
        /*--//1. BOH																	//--*/
        /*--//////////////////////////////////////////////////////////////////////////////--*/
        INSERT INTO GT_0021_BOH_STORAGE
        (
            DIVISION_ID
          , FROM_SITE
          , ITEM_ID
          , YYYYMMDD
          , BOH_TYPE
          , BOH_QTY
          , SEQ
        )
        SELECT IA.DIVISION_ID
             , IA.FROM_SITE
             , NVL(C.APPLIED_MODEL, IA.ITEM_ID) AS ITEM_ID
             , IA.YYYYMMDD
             , IA.BOH_TYPE AS BOH_TYPE
             , SUM(IA.BOH_QTY) AS BOH_QTY
             , IA.SEQ
          FROM (/* MES 기준 BOH : 5S */
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , XA.BOH_TYPE
                     , XA.YYYYMMDD
                     , SUM(XA.BOH_QTY) AS BOH_QTY
                     , XA.SEQ
                  FROM (SELECT SA.DIVISION_ID
                             , SA.FROM_SITE
                             , SA.ITEM_ID
                             , 'BOH' AS BOH_TYPE
                             , SA.YYYYMMDD
                             , NVL(SUM(SA.TOTAL) - (SUM(SA.OQC_NG) + SUM(SA.QMS_MES_HOLD)), 0) AS BOH_QTY
                             , 5 AS SEQ
                          FROM (SELECT DIVISION_ID
                                     , FROM_SITE
                                     , ITEM_ID
                                     , V_BOH_YYYYMMDD AS YYYYMMDD
                                     , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                                     , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                                     , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                                  FROM SSP_DNM_GMES_STOCK_81_82
                                 WHERE DIVISION_ID = P_DIVISION_ID
                                   AND COMPANY_ID = P_COMPANY_ID
                                   AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR FROM_SITE IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                  OR ITEM_ID IN (SELECT COLUMN_VALUE
--                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                    /* OR ITEM_ID MEMBER OF V_ITEM_TAB) */
                                    OR ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                   FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                                 GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) SA
                         GROUP BY SA.DIVISION_ID, SA.FROM_SITE, SA.ITEM_ID, SA.YYYYMMDD
                        UNION ALL
                        SELECT SA.DIVISION_ID
                             , SA.FROM_SITE
                             , SA.ITEM_ID
                             , 'BOH' AS BOH_TYPE
                             , SA.CUTOFF_DATE AS YYYYMMDD
                             , SUM(SA.AVAILABLE_QTY) AS BOH_QTY
                             , 5 AS SEQ                                         /* MEASURE 위치와 동일하게 */
                          FROM SSP_ANL_OWMS_STOCK_C2 SA
                             , SCM_ADM_LOOKUP_MASTER_DETAIL SB
                         WHERE SB.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'             /* C20220419-000607 */
                           AND SB.VALID_YN = 'Y'
                           AND SB.ATTRIBUTE1 = 'Y'
                           AND SB.SEGMENT1 = SA.STOCK_STATUS
                           AND SA.DIVISION_ID = P_DIVISION_ID
                           AND SA.COMPANY_ID = P_COMPANY_ID
                           AND SA.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                         GROUP BY SA.DIVISION_ID, SA.FROM_SITE, SA.ITEM_ID, SA.CUTOFF_DATE) XA
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.BOH_TYPE, XA.YYYYMMDD, XA.SEQ
                UNION ALL
                /* ERP 재고 : 6S */
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'ERP' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , XA.SCM_QTY AS BOH_QTY
                     , 6 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM (SELECT SA.DIVISION_ID
                             , SA.COMPANY_ID
                             , SA.SCM_SITE_ID
                             , SA.ITEM_ID
                             , SA.SSP_QTY
                             , SA.SCM_QTY
                             , SA.CUTOFF_DATE
                             , SA.SITE_ID
                             , SA.STORAGE_ID
                             , SA.PLANT_ID
                             , SA.OPERATION_ID
                             , SA.STOCK_TYPE
                          FROM SSP_DNM_STOCK_C SA                               /* SCM_DNM_STOCK_V */
                         WHERE SA.DIVISION_ID = P_DIVISION_ID
                           AND SA.COMPANY_ID = P_COMPANY_ID
                           AND SA.CUTOFF_DATE > V_STOCK_DATE                    /* 현재일 - 3 */
                           AND SA.CUTOFF_DATE = V_BOH_DATE
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA
                            /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) XA */
                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))) XA   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                     , (SELECT SA.DIVISION_ID
                             , SA.STORAGE_ID
                             , SA.SCM_SITE_ID
                             , SA.LOCATION_CODE
                             , SA.PLANT_ID
                             , SB.COMPANY_ID
                             , SA.VALID_YN
                          FROM SSP_MST_LOCATION_V SA
                             , SCM_MST_SITE SB
                         WHERE SA.DIVISION_ID = SB.DIVISION_ID
                           AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                           AND SA.PLANT_ID = SB.PLANT_ID
                           AND SB.DIVISION_ID = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND SB.VALID_YN = 'Y'
                           AND SB.SITE_TYPE = 'PLANT'
                           AND SA.VALID_YN = 'Y'
                           AND SA.DIVISION_ID = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND SA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                         GROUP BY SA.DIVISION_ID, SA.STORAGE_ID, SA.SCM_SITE_ID, SA.LOCATION_CODE, SA.PLANT_ID, SB.COMPANY_ID, SA.VALID_YN
                        UNION ALL
                        SELECT DISTINCT SA.SEGMENT1 AS DIVISION_ID
                             , SA.SEGMENT4 AS STORAGE_ID
                             , SA.SEGMENT2 AS SCM_SITE_ID
                             , 'AS' AS LOCATION_CODE
                             , SA.SEGMENT3 AS PLANT_ID
                             , SB.COMPANY_ID
                             , SA.VALID_YN
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                             , SCM_MST_SITE SB
                         WHERE SA.SEGMENT1 = SB.DIVISION_ID
                           AND SA.SEGMENT2 = SB.SCM_SITE_ID
                           AND SA.SEGMENT3 = SB.PLANT_ID
                           AND SA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                           AND SA.VALID_YN = 'Y'
                           AND SB.DIVISION_ID = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND SB.VALID_YN = 'Y'
                           AND SB.SITE_TYPE = 'PLANT'
                           AND SA.SEGMENT1 = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) XB
                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                   AND XA.STORAGE_ID = XB.STORAGE_ID
                   AND XA.PLANT_ID = XB.PLANT_ID
                   AND XA.COMPANY_ID = XB.COMPANY_ID
                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                   AND XB.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                   AND XA.STOCK_TYPE = 'INVENTORY'
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                UNION ALL
                /* oWMS 재고 : 7S */
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , 'oWMS' AS BOH_TYPE
                     , XA.CUTOFF_DATE AS YYYYMMDD
                     , SUM(XA.STOCK_QTY) AS BOH_QTY
                     , 7 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM SSP_ANL_OWMS_STOCK_C2 XA
                     , SCM_ADM_LOOKUP_MASTER_DETAIL XB
                 WHERE XB.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'                     /* C20220419-000607 */
                   AND XB.VALID_YN = 'Y'
                   AND XB.ATTRIBUTE1 = 'Y'
                   AND XB.SEGMENT1 = XA.STOCK_STATUS
                   AND XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE = V_BOH_YYYYMMDD
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                          FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.CUTOFF_DATE
                UNION ALL
                /* MES 재고 : 8S */
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , 'MES' AS BOH_TYPE
                     , XA.YYYYMMDD
                     , NVL(SUM(XA.TOTAL) - (SUM(XA.OQC_NG) + SUM(XA.QMS_MES_HOLD)), 0) AS BOH_QTY
                     , 8 AS SEQ
                  FROM (SELECT DIVISION_ID
                             , FROM_SITE
                             , ITEM_ID
                             , V_BOH_YYYYMMDD AS YYYYMMDD
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82
                         WHERE DIVISION_ID = P_DIVISION_ID
                           AND COMPANY_ID = P_COMPANY_ID
                           AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR FROM_SITE IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR ITEM_ID IN (SELECT COLUMN_VALUE
--                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR ITEM_ID MEMBER OF V_ITEM_TAB) */
                            OR ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                           FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) XA
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.YYYYMMDD
                UNION ALL
                /* ESS PACKER 재고 - BOH MEASURE */
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'BOH' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , NVL(XA.SSP_QTY, 0) AS BOH_QTY
                     , 5 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM SSP_DNM_ESS_PACKER_STOCK_V XA
                 WHERE XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE > V_STOCK_DATE                            /* 현재일 - 3 */
                   AND XA.CUTOFF_DATE = V_BOH_DATE
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                UNION ALL
                /* ESS PACKER 재고 - ERP MEASURE */
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'ERP' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , NVL(XA.SSP_QTY, 0) AS BOH_QTY
                     , 6 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM SSP_DNM_ESS_PACKER_STOCK_V XA
                 WHERE XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE > V_STOCK_DATE                            /* 현재일 - 3 */
                   AND XA.CUTOFF_DATE = V_BOH_DATE
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                  OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)) IA */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))) IA   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
             , SCM_MST_SITE B
             , SCM_MST_ITEM_SN C
         WHERE B.DIVISION_ID = IA.DIVISION_ID
           AND B.SCM_SITE_ID = IA.FROM_SITE
           AND C.DIVISION_ID(+) = IA.DIVISION_ID
           AND C.COMPANY_ID(+) = P_COMPANY_ID
           AND C.SITE_ID(+) = B.SITE_ID
           AND C.ITEM_ID(+) = IA.ITEM_ID
           AND C.ITEM_CLASS(+) IN ('ES1901', 'ES2001', 'ES2002', 'ES2003', 'ES2004')
         GROUP BY IA.DIVISION_ID, IA.FROM_SITE, C.APPLIED_MODEL, IA.ITEM_ID, IA.YYYYMMDD, IA.BOH_TYPE, IA.SEQ;

        INSERT INTO GT_0021_BOH
        (
            DIVISION_ID
          , FROM_SITE
          , ITEM_ID
          , YYYYMMDD
          , BOH_TYPE
          , BOH_QTY
          , SEQ
        )
        SELECT DIVISION_ID
             , FROM_SITE
             , ITEM_ID
             , YYYYMMDD
             , BOH_TYPE AS BOH_TYPE
             , SUM(BOH_QTY) AS BOH_QTY
             , SEQ
          FROM GT_0021_BOH_STORAGE
         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, BOH_TYPE, SEQ;
        /*--//END BOH : 5S//--*/

        IF P_REAL_FLAG = 'Y' THEN

            INSERT INTO GT_0021_ROWDATA
            (
                DIVISION_ID
              , ITEM_ID
              , FROM_SITE
              , MEASURE
              , SEQ
              , YYYYMMDD
              , QTY
              , CONFIRM_DAY
            )
            SELECT IA.DIVISION_ID
                 , NVL(C.APPLIED_MODEL, IA.ITEM_ID) AS ITEM_ID
                 , IA.FROM_SITE
                 , IA.MEASURE
                 , IA.SEQ
                 , IA.YYYYMMDD
                 , SUM(IA.QTY) AS QTY
                 /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
                 , CASE WHEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, V_FROM_YYYYMMDD) - 1 > 0
                             THEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, V_FROM_YYYYMMDD) - 1
                        ELSE 0
                   END AS CONFIRM_DAY
              FROM (/* SHIP_REQ : 1S */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.PLANT_SITE_ID AS FROM_SITE
                         , 'SHIP_REQ' AS MEASURE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.QTY AS QTY
                         , 1 AS SEQ
                      FROM DM_PLN_SHIPMENT_REQ XA
                         , SCM_MST_SITE XB
                     WHERE XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.PLANT_SITE_ID = XB.SCM_SITE_ID
                       AND XB.COMPANY_ID = P_COMPANY_ID
                       AND XB.SITE_TYPE = 'PLANT'
                       AND XB.VALID_YN = 'Y'
                       AND XA.MEASURE = 'SHIP_REQ'                              /* 확정 후 수정할 것 */
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND XA.QTY > 0
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                       AND NOT EXISTS (SELECT 1
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                        WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                          AND SA.VALID_YN = 'Y'
                                          AND SA.SEGMENT1 = XA.DIVISION_ID
                                          AND SA.SEGMENT2 = XA.PLANT_SITE_ID
                                          AND SA.SEGMENT4 = XA.ITEM_ID)
                    UNION ALL
                    /* SHIP_PLAN : 2S */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.MEASURE AS MEASURE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NVL(SUM(XA.QTY), 0) AS QTY
                         , XA.SEQ AS SEQ
                      FROM (SELECT SA.DIVISION_ID
                                 , SA.ITEM_ID
                                 , SA.FROM_SITE
                                 , 'SHIP_PLAN' AS MEASURE
                                 , SA.YYYYMMDD
                                 , SA.QTY
                                 , 2 AS SEQ
                              FROM SSP_ANL_SHIP_CONFIRM SA
                             WHERE SA.CHANGE_TYPE = 'C'
                               AND SA.BIZ_TYPE <> 'E'
                               AND SA.QTY > 0
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                               AND SA.YYYYMMDD >= V_FROM_YYYYMMDD
                               AND SA.YYYYMMDD <= V_TO_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                              OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                            UNION ALL
                            SELECT SA.DIVISION_ID
                                 , SA.ITEM_ID
                                 , SA.FROM_SITE
                                 , SA.MEASURE
                                 , SA.YYYYMMDD
                                 , SA.QTY
                                 , SA.SEQ
                              FROM (SELECT SB.DIVISION_ID AS DIVISION_ID
                                         , SB.ITEM_ID AS ITEM_ID
                                         , SB.PLANT_SITE_ID AS FROM_SITE
                                         , 'SHIP_PLAN' AS MEASURE
                                         , SB.YYYYMMDD AS YYYYMMDD
                                         , SB.QTY AS QTY
                                         , 2 AS SEQ
                                         /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
                                         , CASE WHEN NVL(SC.SHIP_FROZEN, 0) > 0
                                                     THEN TO_CHAR(TO_DATE(P_FROM_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, SC.DIVISION_ID, SC.SCM_SITE_ID, P_FROM_YYYYMMDD), 'YYYYMMDD')
                                                ELSE P_FROM_YYYYMMDD
                                           END AS FROZEN_YYYYMMDD               /* Ship Frozen구간 다음일자 */
                                      FROM DM_PLN_SHIPMENT_REQ SB
                                         , SCM_MST_SITE SC
                                     WHERE SC.DIVISION_ID = P_DIVISION_ID
                                       AND SB.PLANT_SITE_ID = SC.SCM_SITE_ID
                                       AND SC.COMPANY_ID = P_COMPANY_ID
                                       AND SC.SITE_TYPE = 'PLANT'
                                       AND SC.VALID_YN = 'Y'
                                       AND SB.DIVISION_ID = P_DIVISION_ID       /* 변수 */
                                       AND SB.MEASURE = 'SHIP_REQ'              /* 확정 후 수정할 것 */
                                       AND SB.YYYYMMDD >= V_FROM_YYYYMMDD
                                       AND SB.YYYYMMDD <= V_TO_YYYYMMDD
                                       AND SB.QTY > 0
                                       AND (TRIM(P_FROM_SITE) IS NULL
                                        OR SB.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                       AND (TRIM(P_ITEM_ID) IS NULL
                                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                      OR SB.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                        /* OR SB.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                        OR SB.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                                       AND NOT EXISTS (SELECT 1
                                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL SD
                                                        WHERE SD.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                                          AND SD.VALID_YN = 'Y'
                                                          AND SD.SEGMENT1 = SB.DIVISION_ID
                                                          AND SD.SEGMENT2 = SB.PLANT_SITE_ID
                                                          AND SD.SEGMENT4 = SB.ITEM_ID)) SA
                             WHERE SA.YYYYMMDD >= SA.FROZEN_YYYYMMDD) XA
                     GROUP BY XA.DIVISION_ID, XA.ITEM_ID, XA.FROM_SITE, XA.MEASURE, XA.YYYYMMDD, XA.SEQ
                    UNION ALL
                    /* PROD_PLAN : 7S (FP 생산계획) */
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.SCM_SITE_ID AS FROM_SITE
                         , 'PROD_PLAN' AS MEASURE
                         , XA.PLAN_DATE AS YYYYMMDD
                         , XA.PLAN_QTY AS QTY
                         , 7 AS SEQ
                      FROM SSP_DNM_FP_PLAN_FROZEN XA                            /* SCM_DNM_PLAN_FROZEN_V */
                     WHERE XA.OPERATION_ID IN ('P5500', 'P9500', 'F5300', 'F5500', 'F5600', 'F6000', 'PL500')
                       AND XA.PLAN_QTY > 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_DATE >= V_FROM_YYYYMMDD
                       AND XA.PLAN_DATE <= V_TO_YYYYMMDD
                       AND XA.SITE_ID IN (SELECT DISTINCT SA.SITE_ID
                                            FROM SCM_MST_SITE SA
                                           WHERE SA.DIVISION_ID = P_DIVISION_ID
                                             AND SA.COMPANY_ID = P_COMPANY_ID
                                             AND SA.SITE_TYPE = 'PLANT'
                                             AND SA.VALID_YN = 'Y')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                    UNION ALL
                    /* PROD_PLAN : 7S (ESS Packer 생산계획) */
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.SCM_SITE_ID AS FROM_SITE
                         , 'PROD_PLAN' AS MEASURE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.QTY AS QTY
                         , 7 AS SEQ
                      FROM SCP_ANL_PRODUCTION_PLAN XA
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                              FROM (SELECT SB.DIVISION_ID
                                         , SB.PLAN_START_YYYYMMDD
                                         , SB.PLAN_TYPE
                                         , SB.PLAN_SEQ AS SEQ
                                      FROM SCP_PLAN_VERSION_V SB
                                     WHERE SB.DIVISION_ID = '82'                /* ESS(82)만 적용 */
                                       AND SB.PLAN_CYCLE = 'WEEKLY'
                                       AND SB.PLAN_TYPE NOT IN ('TE', 'TM')
                                     ORDER BY SB.PLAN_START_YYYYMMDD DESC, SB.PLAN_TYPE_ORDER DESC, SB.PLAN_SEQ DESC) SA
                             WHERE ROWNUM = 1) XB
                         , SCM_MST_SITE XC
                     WHERE XB.DIVISION_ID = XA.DIVISION_ID
                       AND XB.PLAN_START_YYYYMMDD = XA.PLAN_START_YYYYMMDD
                       AND XB.PLAN_TYPE = XA.PLAN_TYPE
                       AND XB.SEQ = XA.SEQ
                       AND XC.DIVISION_ID = XA.DIVISION_ID
                       AND XC.SCM_SITE_ID = XA.SCM_SITE_ID
                       AND XC.SITE_TYPE = 'PLANT'
                       AND XC.OSP_YN = 'Y'
                       AND XC.VALID_YN = 'Y'
                       AND XA.DIVISION_ID = '82'                                /* ESS(82)만 적용 */
                       AND XC.COMPANY_ID = P_COMPANY_ID
                       AND XA.MEASURE = 'PROD_PLAN_AMEND'
                       AND XA.QTY > 0
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                       AND NOT EXISTS (SELECT 1
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                        WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                          AND SA.VALID_YN = 'Y'
                                          AND SA.SEGMENT1 = XA.DIVISION_ID
                                          AND SA.SEGMENT2 = XA.SCM_SITE_ID
                                          AND SA.SEGMENT4 = XA.ITEM_ID)
                    UNION ALL
                    /* PROD_PLAN : 7S (창고 입고예정) */
                    -- 2026.10.06 AJS 입고예정 도착일 함수를 인자 조합마다 1회 호출 (START)
--                    SELECT XA.DIVISION_ID
--                         , XA.ITEM_ID
--                         , XA.FROM_SITE
--                         , XA.MEASURE
--                         , XA.YYYYMMDD
--                         , XA.QTY
--                         , XA.SEQ
--                      FROM (SELECT SA.DIVISION_ID AS DIVISION_ID
--                                 , SA.ITEM_ID AS ITEM_ID
--                                 , SA.SCM_SITE_ID AS FROM_SITE
--                                 , 'PROD_PLAN' AS MEASURE
--                                 , FN_GET_SSP_ETA_DATE(SA.DIVISION_ID, SA.BOD_ID, SA.YYYYMMDD) AS YYYYMMDD
--                                 , SA.QTY AS QTY
--                                 , 7 AS SEQ
--                              FROM DM_PLN_SHIPMENT_REQ SA
--                                 , SCM_MST_SITE SB
--                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
--                               AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
--                               AND SB.OPERATION_GROUP = 'W'
--                               AND SB.SITE_TYPE = 'PLANT'
--                               AND SB.VALID_YN = 'Y'
--                               AND SA.DIVISION_ID IN (SELECT TOKEN
--                                                        FROM TABLE(UF_FX_STRING_SPLIT(P_DIVISION_ID, ',')))
--                               AND SB.COMPANY_ID = P_COMPANY_ID
--                               AND SA.QTY > 0
--                               AND (TRIM(P_FROM_SITE) IS NULL
--                                OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
--                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
--                               AND (TRIM(P_ITEM_ID) IS NULL
--                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA
--                     WHERE XA.YYYYMMDD >= V_FROM_YYYYMMDD
--                       AND XA.YYYYMMDD < V_TO_YYYYMMDD
                    /* 확정 이후 입고예정(창고 PROD_PLAN) : 출하일 -> 도착일 함수가 행마다 2 번(>= · <) 불려
                       한 번 조회에 17 만 블록을 읽었다(82 HQ00). 함수 인자(사업부 · BOD · 출하일) 조합마다 1 번만 부르도록
                       인자 목록(SC, 중복 제거) -> 함수값(XB) 을 먼저 만들고 원 행(XA)에 붙인다.
                       - XB 는 XA 와 같은 조건으로 만든 인자 목록이므로 XA 의 모든 행이 XB 와 한 행씩 이어진다
                       - BOD 는 빈 값도 같은 값으로 잇는다(DECODE) - 원래 함수 호출과 같은 결과
                       - 함수값 조건(>= 시작일 · < 종료일)은 원래와 같다 */
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.FROM_SITE
                         , XA.MEASURE
                         , XB.ETA_YYYYMMDD AS YYYYMMDD
                         , XA.QTY
                         , XA.SEQ
                      FROM (SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.SCM_SITE_ID AS FROM_SITE
                                 , 'PROD_PLAN' AS MEASURE
                                 , SA.BOD_ID
                                 , SA.YYYYMMDD AS SHIP_YYYYMMDD
                                 , SA.QTY AS QTY
                                 , 7 AS SEQ
                              FROM DM_PLN_SHIPMENT_REQ SA
                                 , SCM_MST_SITE SB
                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                               AND SB.OPERATION_GROUP = 'W'
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SB.VALID_YN = 'Y'
                               AND SA.DIVISION_ID IN (SELECT TOKEN
                                                        FROM TABLE(UF_FX_STRING_SPLIT(P_DIVISION_ID, ',')))
                               AND SB.COMPANY_ID = P_COMPANY_ID
                               AND SA.QTY > 0
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                              OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) XA */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))) XA   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                         , (SELECT /*+ NO_MERGE */
                                   SC.DIVISION_ID
                                 , SC.BOD_ID
                                 , SC.YYYYMMDD
                                 , MAX(FN_GET_SSP_ETA_DATE(SC.DIVISION_ID, SC.BOD_ID, SC.YYYYMMDD)) AS ETA_YYYYMMDD
                              FROM (SELECT /*+ NO_MERGE */
                                           DISTINCT
                                           SA.DIVISION_ID
                                         , SA.BOD_ID
                                         , SA.YYYYMMDD
                                      FROM DM_PLN_SHIPMENT_REQ SA
                                         , SCM_MST_SITE SB
                                     WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                       AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                                       AND SB.OPERATION_GROUP = 'W'
                                       AND SB.SITE_TYPE = 'PLANT'
                                       AND SB.VALID_YN = 'Y'
                                       AND SA.DIVISION_ID IN (SELECT TOKEN
                                                                FROM TABLE(UF_FX_STRING_SPLIT(P_DIVISION_ID, ',')))
                                       AND SB.COMPANY_ID = P_COMPANY_ID
                                       AND SA.QTY > 0
                                       AND (TRIM(P_FROM_SITE) IS NULL
                                        OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                       AND (TRIM(P_ITEM_ID) IS NULL
                                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                      OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) SC
                                        /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) SC */
                                        OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                          FROM TABLE(V_ITEM_TAB)))) SC   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                             GROUP BY SC.DIVISION_ID
                                    , SC.BOD_ID
                                    , SC.YYYYMMDD) XB
                     WHERE XB.DIVISION_ID = XA.DIVISION_ID
                       AND XB.YYYYMMDD = XA.SHIP_YYYYMMDD
                       AND DECODE(XB.BOD_ID, XA.BOD_ID, 1, 0) = 1
                       AND XB.ETA_YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XB.ETA_YYYYMMDD < V_TO_YYYYMMDD
                    -- 2026.10.06 AJS 입고예정 도착일 함수를 인자 조합마다 1회 호출 (END)
                       AND NOT EXISTS (SELECT 1
                                         FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                        WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                          AND SA.VALID_YN = 'Y'
                                          AND SA.SEGMENT1 = XA.DIVISION_ID
                                          AND SA.SEGMENT2 = XA.FROM_SITE
                                          AND SA.SEGMENT4 = XA.ITEM_ID)
                    UNION ALL
                    /* SHIP_AVAL : 3S */
                    SELECT XA.DIVISION_ID
                         , XA.MODEL_ID AS ITEM_ID
                         , XA.FROM_SITE_ID AS FROM_SITE
                         , 'SHIP_AVAL' AS MEASURE
                         , XA.PLAN_DATE AS YYYYMMDD
                         , XA.OUT_QTY AS QTY
                         , 3 AS SEQ
                      FROM SSP_DNM_FP_AMEND_SHIPAVAL XA
                     WHERE XA.OUT_QTY >= 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_DATE >= V_FROM_YYYYMMDD
                       AND XA.PLAN_DATE <= V_TO_YYYYMMDD
                       AND XA.SITE_ID IN (SELECT DISTINCT SA.SITE_ID
                                            FROM SCM_MST_SITE SA
                                           WHERE SA.DIVISION_ID = P_DIVISION_ID
                                             AND SA.COMPANY_ID = P_COMPANY_ID
                                             AND SA.SITE_TYPE = 'PLANT'
                                             AND SA.VALID_YN = 'Y')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE_ID IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.MODEL_ID IN (SELECT COLUMN_VALUE
--                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA
                        /* OR XA.MODEL_ID MEMBER OF V_ITEM_TAB)) IA */
                        OR XA.MODEL_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                           FROM TABLE(V_ITEM_TAB)))) IA   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
             , SCM_MST_SITE B
             , SCM_MST_ITEM_SN C
         WHERE B.DIVISION_ID = P_DIVISION_ID
           AND B.COMPANY_ID = P_COMPANY_ID
           AND IA.FROM_SITE = B.SCM_SITE_ID
           AND B.SITE_TYPE = 'PLANT'
           AND B.VALID_YN = 'Y'
           AND B.COMPANY_ID = C.COMPANY_ID
           AND IA.DIVISION_ID = C.DIVISION_ID
           AND B.SITE_ID = C.SITE_ID
           AND IA.ITEM_ID = C.ITEM_ID
           AND C.ITEM_TYPE IN ('P', 'H')
         GROUP BY IA.DIVISION_ID, IA.FROM_SITE, C.APPLIED_MODEL, IA.ITEM_ID, IA.YYYYMMDD, IA.MEASURE, IA.SEQ, B.SHIP_FROZEN;

            /*--//2. MEASURE x 날짜 전개//--*/
            INSERT INTO GT_0021_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , NVL(B.QTY, 0) AS QTY
              FROM (SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , XA.CONFIRM_DAY
                         , XB.COLUMN_NAME AS MEASURE
                         , XB.SORT_ORDER_NO AS SEQ
                         , XC.YYYYMMDD
                      FROM GT_0021_ROWDATA XA
                         , SCM_MST_SHEET_MEASURE XB
                         , (SELECT SA.BASIS_YYYYMMDD AS YYYYMMDD
                                 , SA.ISO_WEEK
                              FROM SCM_SYS_CALENDAR_M SA
                             WHERE SA.BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
                               AND SA.BASIS_YYYYMMDD <= V_TO_YYYYMMDD) XC
                     WHERE XB.PROGRAM_ID(+) = P_PROGRAM_ID
                       AND XB.SHEET_NAME(+) = P_SHEET_NAME
                       AND XC.YYYYMMDD(+) >= V_FROM_YYYYMMDD
                       AND XC.YYYYMMDD(+) <= V_TO_YYYYMMDD
                     GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XB.COLUMN_NAME, XB.COLUMN_LABEL_NAME, XB.SORT_ORDER_NO, XC.YYYYMMDD, XA.CONFIRM_DAY) IA
                 , GT_0021_ROWDATA B
                 , GT_0021_BOH C
             WHERE IA.DIVISION_ID = B.DIVISION_ID(+)
               AND IA.FROM_SITE = B.FROM_SITE(+)
               AND IA.ITEM_ID = B.ITEM_ID(+)
               AND IA.MEASURE = B.MEASURE(+)
               AND IA.YYYYMMDD = B.YYYYMMDD(+)
               AND IA.DIVISION_ID = C.DIVISION_ID(+)
               AND IA.FROM_SITE = C.FROM_SITE(+)
               AND IA.ITEM_ID = C.ITEM_ID(+)
               AND IA.SEQ = C.SEQ(+)
               AND IA.MEASURE IN ('SHIP_REQ', 'SHIP_PLAN', 'PROD_PLAN', 'SHIP_AVAL');   /* jilee */

            /*--//3. INTN_MOVEMENT(5S) · CONTAINER(6S)//--*/
            INSERT INTO GT_0021_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , LOT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , IA.QTY
                 , IA.LOT_YN
              FROM (SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , 'INTN_MOVEMENT' AS MEASURE
                         , 5 AS SEQ
                         , XA.CONFIRM_DAY
                         , XA.YYYYMMDD
                         , SUM(NVL(XB.QTY, 0)) AS QTY
                         , NULL AS LOT_YN
                      FROM GT_0021_RESULT XA
                         , (SELECT SA.DIVISION_ID
                                 , SB.SCM_SITE_ID AS FROM_SITE
                                 , SA.ITEM_ID
                                 , TO_CHAR(SA.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , NVL(SA.QTY, 0) AS QTY
                              FROM SCM_DNM_CELL_INHOUSE_PLAN_SN SA
                                 , SCM_MST_SITE SB
                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.PLANT_ID = SB.PLANT_ID
                               AND SB.COMPANY_ID = P_COMPANY_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SB.VALID_YN = 'Y'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.COMPANY_ID = P_COMPANY_ID
                               AND SA.CATEGORY = 'MOVING'
                               AND SA.PLAN_DATE >= TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD')
                               AND SA.PLAN_DATE <= TO_DATE(SUBSTR(REPLACE(P_TO_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD')
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                              OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                               AND SA.QTY > 0) XB
                     WHERE XA.DIVISION_ID = XB.DIVISION_ID(+)
                       AND XA.FROM_SITE = XB.FROM_SITE(+)
                       AND XA.ITEM_ID = XB.ITEM_ID(+)
                       AND XA.YYYYMMDD = XB.YYYYMMDD(+)
                       AND XA.MEASURE = 'SHIP_PLAN'
                     GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.YYYYMMDD, XA.MEASURE, XA.SEQ, XA.CONFIRM_DAY
                    UNION ALL
                    SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , 'CONTAINER' AS MEASURE
                         , 6 AS SEQ
                         , XA.CONFIRM_DAY
                         , XA.YYYYMMDD
                         , CASE WHEN NVL(MAX(XB.LOT_SIZE), 0) = 0 THEN 0
                                ELSE CEIL(MAX(NVL(XA.QTY, 0)) / NVL(MAX(XB.LOT_SIZE), 0))
                           END AS QTY
                         , CASE WHEN XB.LOT_SIZE IS NULL THEN 'N' ELSE 'Y' END AS LOT_YN
                      FROM GT_0021_RESULT XA
                         /* 외부조인 조건에 서브쿼리를 두면 바깥 행까지 사라지므로 운송수단 판정을 인라인 뷰 안으로 옮긴다 */
                         , (SELECT SA.DIVISION_ID
                                 , SA.ITEM_ID
                                 , SA.FROM_SITE
                                 , SA.LOT_SIZE
                              FROM SCP_MST_SHIPMENT_LOT_SIZE SA
                             WHERE SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.VALID_YN = 'Y'
                               AND SA.TRANSPORT_MODE = (CASE WHEN SA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                                                     FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0021_GET_SHIPMENT_PLAN', 'G382_Transport')))
                                                                  THEN 'TRK'
                                                             ELSE 'SEA'
                                                        END)) XB
                     WHERE XB.ITEM_ID(+) = XA.ITEM_ID
                       AND XB.FROM_SITE(+) = XA.FROM_SITE
                       AND XA.MEASURE = 'SHIP_PLAN'
                     GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.YYYYMMDD, XA.CONFIRM_DAY, XB.LOT_SIZE) IA;

            /*--//4. WH_STOCK : 8S//--*/
            INSERT INTO GT_0021_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , 'WH_STOCK' AS MEASURE
                 , 8 AS SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'SHIP_PLAN' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'PROD_PLAN' THEN NVL(SA.QTY, 0)
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0021_RESULT SA
                     WHERE SA.DIVISION_ID = IA.DIVISION_ID
                       AND SA.FROM_SITE = IA.FROM_SITE
                       AND SA.ITEM_ID = IA.ITEM_ID
                       AND SA.MEASURE IN ('SHIP_PLAN', 'PROD_PLAN', 'INTN_MOVEMENT')
                       AND SA.YYYYMMDD < IA.YYYYMMDD)
                   + NVL(B.BOH_QTY, 0) AS QTY
              FROM (SELECT DIVISION_ID
                         , FROM_SITE
                         , ITEM_ID
                         , YYYYMMDD
                         , CONFIRM_DAY
                      FROM GT_0021_RESULT
                     GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, CONFIRM_DAY) IA
                 , (SELECT SA.DIVISION_ID
                         , SA.FROM_SITE
                         , SA.ITEM_ID
                         , TO_CHAR(TO_DATE(SA.YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') AS YYYYMMDD
                         , SA.BOH_QTY AS BOH_QTY
                      FROM GT_0021_BOH SA
                     WHERE SA.BOH_TYPE = 'BOH'
                       AND SA.YYYYMMDD = V_BOH_YYYYMMDD) B
             WHERE IA.DIVISION_ID = B.DIVISION_ID(+)
               AND IA.FROM_SITE = B.FROM_SITE(+)
               AND IA.ITEM_ID = B.ITEM_ID(+)
               AND NOT EXISTS (SELECT 1
                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                  AND SA.VALID_YN = 'Y'
                                  AND SA.SEGMENT1 = IA.DIVISION_ID
                                  AND SA.SEGMENT2 = IA.FROM_SITE
                                  AND SA.SEGMENT4 = IA.ITEM_ID);

            /*--//5. BALANCE : 9S//--*/
            INSERT INTO GT_0021_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
            )
            SELECT DIVISION_ID
                 , FROM_SITE
                 , ITEM_ID
                 , 'BALANCE' AS MEASURE
                 , 9 AS SEQ
                 , CONFIRM_DAY
                 , YYYYMMDD
                 , NVL(SUM(CASE WHEN MEASURE = 'SHIP_PLAN' THEN -1 * NVL(QTY, 0)
                                WHEN MEASURE = 'WH_STOCK' THEN NVL(QTY, 0)
                                ELSE 0
                           END), 0) AS QTY
              FROM GT_0021_RESULT A
             WHERE MEASURE IN ('SHIP_PLAN', 'WH_STOCK')
               AND NOT EXISTS (SELECT 1
                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                  AND SA.VALID_YN = 'Y'
                                  AND SA.SEGMENT1 = A.DIVISION_ID
                                  AND SA.SEGMENT2 = A.FROM_SITE
                                  AND SA.SEGMENT4 = A.ITEM_ID)
             GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, CONFIRM_DAY;

            /*--//6. SHIP_AVAL_GAP : 4S//--*/
            INSERT INTO GT_0021_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , 'SHIP_AVAL_GAP' AS MEASURE
                 , 4 AS SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'SHIP_PLAN' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'SHIP_AVAL' THEN NVL(SA.QTY, 0)
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0021_RESULT SA
                     WHERE SA.DIVISION_ID = IA.DIVISION_ID
                       AND SA.FROM_SITE = IA.FROM_SITE
                       AND SA.ITEM_ID = IA.ITEM_ID
                       AND SA.MEASURE IN ('SHIP_PLAN', 'SHIP_AVAL')
                       AND SA.YYYYMMDD <= IA.YYYYMMDD) AS QTY
              FROM (SELECT DIVISION_ID
                         , FROM_SITE
                         , ITEM_ID
                         , YYYYMMDD
                         , CONFIRM_DAY
                      FROM GT_0021_RESULT
                     GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD, CONFIRM_DAY) IA
             WHERE NOT EXISTS (SELECT 1
                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                WHERE SA.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                                  AND SA.VALID_YN = 'Y'
                                  AND SA.SEGMENT1 = IA.DIVISION_ID
                                  AND SA.SEGMENT2 = IA.FROM_SITE
                                  AND SA.SEGMENT4 = IA.ITEM_ID);

            /*--//7. FP 자동생성 대상 계산 [E20260629-000020]//--*/
            FOR R IN (SELECT SP.DIVISION_ID
                           , SP.FROM_SITE
                           , SP.ITEM_ID
                           , SP.YYYYMMDD
                           , NVL(SP.QTY, 0) AS CF_QTY                           /* CONFIRM QTY */
                           , NVL(PP.QTY, 0) AS PP_QTY                           /* PRDN PLAN QTY */
                           , NVL(MV.QTY, 0) AS MV_QTY                           /* INTN_MOVEMENT QTY */
                           , NVL(L.LOT_SIZE, 0) AS LOT_SIZE
                           , T.ATTRIBUTE1 AS RATE
                           , SP.CONFIRM_DAY
                        FROM GT_0021_RESULT SP                                  /* CONFIRM */
                           , GT_0021_RESULT PP                                  /* PROD PLAN */
                           , GT_0021_RESULT MV                                  /* INTN_MOVEMENT */
                           , SCM_ADM_LOOKUP_MASTER_DETAIL T                     /* FP 자동생성 대상 */
                           , SCP_MST_BOD_N_V B
                           , SCP_MST_SHIPMENT_LOT_SIZE L
                       WHERE SP.DIVISION_ID = PP.DIVISION_ID(+)
                         AND SP.ITEM_ID = PP.ITEM_ID(+)
                         AND SP.FROM_SITE = PP.FROM_SITE(+)
                         AND SP.YYYYMMDD = PP.YYYYMMDD(+)
                         AND PP.MEASURE(+) = 'PROD_PLAN'
                         AND SP.DIVISION_ID = MV.DIVISION_ID(+)
                         AND SP.ITEM_ID = MV.ITEM_ID(+)
                         AND SP.FROM_SITE = MV.FROM_SITE(+)
                         AND SP.YYYYMMDD = MV.YYYYMMDD(+)
                         /* 원문은 이 조건이 PP 를 가리킨다 — 형태 보존 */
                         AND PP.MEASURE(+) = 'INTN_MOVEMENT'
                         AND T.LOOKUP_TYPE = 'FP_AUTO_SHIP_FROM_TO'
                         AND T.VALID_YN = 'Y'
                         AND T.SEGMENT1 = SP.DIVISION_ID
                         AND T.SEGMENT2 = SP.FROM_SITE
                         AND T.SEGMENT4 = SP.ITEM_ID
                         AND B.DIVISION_ID(+) = T.SEGMENT1                      /* DIVISION_ID */
                         AND B.BOD_ID(+) = T.SEGMENT5                           /* BOD_ID */
                         AND L.DIVISION_ID(+) = SP.DIVISION_ID
                         AND L.FROM_SITE(+) = SP.FROM_SITE
                         AND L.TO_SITE(+) = T.SEGMENT3                          /* TO_SITE */
                         AND L.ITEM_ID(+) = SP.ITEM_ID
                         AND L.TRANSPORT_MODE(+) = B.TRANSPORT_MODE
                         AND L.VALID_YN(+) = 'Y'
                         AND SP.MEASURE = 'SHIP_PLAN'
                       ORDER BY SP.DIVISION_ID
                              , SP.FROM_SITE
                              , SP.ITEM_ID
                              , SP.YYYYMMDD) LOOP

                V_TMP_CFM_QTY := 0;
                V_TMP_WH_STOCK := 0;
                V_TMP_SP_QTY := 0;
                V_TMP_FP_QTY := 0;

                IF V_FROM_YYYYMMDD = R.YYYYMMDD THEN

                    BEGIN
                        SELECT NVL(BOH_QTY, 0)
                          INTO V_TMP_WH_STOCK
                          FROM GT_0021_BOH
                         WHERE BOH_TYPE = 'BOH'
                           AND YYYYMMDD = V_BOH_YYYYMMDD
                           AND DIVISION_ID = R.DIVISION_ID
                           AND FROM_SITE = R.FROM_SITE
                           AND ITEM_ID = R.ITEM_ID;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            V_TMP_WH_STOCK := 0;                                /* 원문도 대상이 없으면 0 을 유지한다 */
                    END;

                ELSE

                    SELECT NVL(SUM(C.QTY), 0)
                      INTO V_TMP_WH_STOCK
                      FROM GT_0021_RESULT C
                     WHERE C.DIVISION_ID = R.DIVISION_ID
                       AND C.YYYYMMDD = TO_CHAR(TO_DATE(R.YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                       AND C.ITEM_ID = R.ITEM_ID
                       AND C.FROM_SITE = R.FROM_SITE
                       AND C.MEASURE = 'WH_STOCK';

                END IF;

                V_FROZEN_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, R.DIVISION_ID, R.FROM_SITE, P_PLAN_START_YYYYMMDD) - 1, 'YYYYMMDD');

                /* 원문의 CONVERT(INT, x) 는 절삭이므로 TRUNC 로 옮긴다 */
                V_TMP_SP_QTY := CASE WHEN V_FROZEN_YYYYMMDD >= R.YYYYMMDD THEN (CASE WHEN R.CF_QTY <> 0 THEN R.CF_QTY ELSE 0 END)   /* 컴펌 */
                                     WHEN NVL(R.LOT_SIZE, 0) = 0 THEN TRUNC(V_TMP_WH_STOCK + (R.PP_QTY * ((100 - R.RATE) / 100.0)))  /* LOT SIZE가 없는경우 전부 계획으로 잡는다. */
                                     WHEN TRUNC((V_TMP_WH_STOCK + (R.PP_QTY * ((100 - R.RATE) / 100.0))) / R.LOT_SIZE) * R.LOT_SIZE < R.LOT_SIZE THEN 0   /* LOT SIZE보다 작은경우 */
                                     ELSE TRUNC((V_TMP_WH_STOCK + (R.PP_QTY * ((100 - R.RATE) / 100.0))) / R.LOT_SIZE) * R.LOT_SIZE
                                END;
                V_TMP_FP_QTY := NVL(R.PP_QTY, 0);
                V_TMP_CFM_QTY := CASE WHEN NVL(R.CF_QTY, 0) <> 0 THEN R.CF_QTY ELSE 0 END;  /* 컴펌 수량 */

                UPDATE GT_0021_RESULT C
                   SET C.QTY = V_TMP_SP_QTY
                 WHERE C.DIVISION_ID = R.DIVISION_ID
                   AND C.ITEM_ID = R.ITEM_ID
                   AND C.FROM_SITE = R.FROM_SITE
                   AND C.YYYYMMDD = R.YYYYMMDD
                   AND C.MEASURE = 'SHIP_PLAN';

                /* 원문의 MERGE — 온라인 SQL 에서는 쓰지 않으므로 UPDATE 후 없으면 INSERT 로 나눈다 */
                UPDATE GT_0021_RESULT C
                   SET C.QTY = C.QTY - V_TMP_CFM_QTY
                 WHERE C.DIVISION_ID = R.DIVISION_ID
                   AND C.ITEM_ID = R.ITEM_ID
                   AND C.FROM_SITE = R.FROM_SITE
                   AND C.MEASURE = 'WH_STOCK'
                   AND C.YYYYMMDD = R.YYYYMMDD;

                IF SQL%ROWCOUNT = 0 THEN

                    INSERT INTO GT_0021_RESULT
                    (
                        DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , MEASURE
                      , YYYYMMDD
                      , SEQ
                      , QTY
                      , CONFIRM_DAY
                    )
                    VALUES
                    (
                        R.DIVISION_ID
                      , R.ITEM_ID
                      , R.FROM_SITE
                      , 'WH_STOCK'
                      , R.YYYYMMDD
                      , 8
                      , V_TMP_WH_STOCK + V_TMP_FP_QTY - (CASE WHEN V_TMP_CFM_QTY <> 0 THEN V_TMP_CFM_QTY ELSE V_TMP_SP_QTY END) - R.MV_QTY
                      , R.CONFIRM_DAY
                    );

                END IF;

            END LOOP;

            INSERT INTO GT_0021_PIVOT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , LOT_YN
            )
            SELECT A.DIVISION_ID
                 , A.FROM_SITE
                 , A.ITEM_ID
                 , A.MEASURE
                 , A.SEQ
                 , A.CONFIRM_DAY
                 , 'D_' || A.YYYYMMDD AS YYYYMMDD
                 , B.BASIS_YYYYMM AS YYYYMM
                 , SUBSTR(B.BASIS_YYYYMM, -4) || B.ISO_WEEK AS ISO_WEEK
                 , A.QTY
                 , A.LOT_YN
              FROM GT_0021_RESULT A
                 , SCM_SYS_CALENDAR_M B
             WHERE A.YYYYMMDD = B.BASIS_YYYYMMDD;

            /*PIVOIT처리*******************************************************************************/
            /* PIVOIT 대상 날짜문자열 생성 */
            V_QRY_SUM := '';

            FOR R IN (SELECT IA.YYYYMMDD
                        FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                                   , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                              UNION ALL
                              SELECT 'M_' || A.BASIS_YYYYMM AS YYYYMMDD
                                   , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                              UNION ALL
                              SELECT 'D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                                   , A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMMDD) IA
                       ORDER BY IA.SORT_ORDER_NO) LOOP

                IF INSTR(R.YYYYMMDD, 'M_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'W_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'D_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) END) AS ' || R.YYYYMMDD || CHR(10);
                END IF;

            END LOOP;
            /*--//END PIVOT//--*/

            /*--//8. RESULT //--*/
            /* 측정값 칸은 화면 설정에 따라 개수가 달라져 정적 SQL 로 쓸 수 없다(피벗 전용 동적 SQL) */
            V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
                   || ', A.FROM_SITE' || CHR(10)
                   || ', NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_DESCRIPTION' || CHR(10)
                   || ', A.ITEM_ID' || CHR(10)
                   || ', (SELECT NVL(SA.NICK_NAME, ''-'') FROM SCM_MST_ITEM_SN SA WHERE SA.ITEM_ID = A.ITEM_ID AND ROWNUM = 1) AS NICK_NAME' || CHR(10)
                   || ', CASE WHEN B.BOH_TYPE IS NULL THEN' || CHR(10)
                   || '       CASE A.SEQ WHEN 5 THEN ''BOH''' || CHR(10)
                   || '                  WHEN 6 THEN ''ERP''' || CHR(10)
                   || '                  WHEN 7 THEN ''oWMS''' || CHR(10)
                   || '                  WHEN 8 THEN ''MES''' || CHR(10)
                   || '       ELSE NULL END' || CHR(10)
                   || '  ELSE B.BOH_TYPE END AS BOH_TYPE' || CHR(10)
                   || ', CASE WHEN (A.SEQ = 1 OR A.SEQ = 2 OR A.SEQ = 3 OR A.SEQ = 4 OR A.SEQ = 9) THEN NULL' || CHR(10)
                   || '  ELSE NVL(B.BOH_QTY, 0) END AS BOH_QTY' || CHR(10)
                   || ', CASE A.MEASURE WHEN ''SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL_GAP'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''BALANCE'' THEN ''I'' END AS PSI' || CHR(10)
                   || ', A.MEASURE' || CHR(10)
                   || ', C.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                   || ', A.SEQ' || CHR(10)
                   || ', TO_CHAR(TO_DATE(:B_FROM_YYYYMMDD1, ''YYYYMMDD'') + NVL(A.CONFIRM_DAY, 0), ''YYYYMMDD'') AS CONFIRM_DAY' || CHR(10)
                   || ', C.ATTRIBUTE3 AS BACK_COLOR' || CHR(10)
                   || ', A.LOT_YN' || CHR(10)
                   || V_QRY_SUM
                   || '  FROM GT_0021_PIVOT A' || CHR(10)
                   || '     , GT_0021_BOH B' || CHR(10)
                   || '     , SCM_MST_SHEET_MEASURE C' || CHR(10)
                   || '     , SCM_MST_TITLESET_USER D' || CHR(10)
                   || ' WHERE A.DIVISION_ID = B.DIVISION_ID(+)' || CHR(10)
                   || '   AND A.FROM_SITE = B.FROM_SITE(+)' || CHR(10)
                   || '   AND A.ITEM_ID = B.ITEM_ID(+)' || CHR(10)
                   || '   AND A.SEQ = B.SEQ(+)' || CHR(10)
                   || '   AND A.MEASURE = C.COLUMN_NAME' || CHR(10)
                   || '   AND C.PROGRAM_ID = :B_PROGRAM_ID1' || CHR(10)
                   || '   AND C.SHEET_NAME = :B_SHEET_NAME1' || CHR(10)
                   || '   AND D.PROGRAM_ID(+) = C.PROGRAM_ID' || CHR(10)
                   || '   AND D.SHEET_NAME(+) = C.SHEET_NAME' || CHR(10)
                   || '   AND D.COLUMN_NAME(+) = C.COLUMN_NAME' || CHR(10)
                   || '   AND D.USER_ID(+) = :B_USER_ID1' || CHR(10)
                   || '   AND C.VALID_YN = ''Y''' || CHR(10)
                   || '   AND (:B_CNT1 = 0' || CHR(10)
                   || '    OR EXISTS (SELECT 1' || CHR(10)
                   || '                 FROM GT_0021_TITLESET SA' || CHR(10)
                   || '                WHERE SA.COLUMN_NAME = C.COLUMN_NAME))' || CHR(10)
                   || '   AND ((:B_CNT2 = 0 AND C.DEFAULT_FLAG = ''Y'')' || CHR(10)
                   || '    OR (:B_CNT3 <> 0))' || CHR(10)
                   || ' GROUP BY A.DIVISION_ID, A.FROM_SITE, A.ITEM_ID, B.BOH_TYPE, B.BOH_QTY, A.MEASURE, C.COLUMN_LABEL_NAME, A.SEQ, A.CONFIRM_DAY, C.ATTRIBUTE3, A.LOT_YN' || CHR(10)
                   || ' ORDER BY A.DIVISION_ID, A.FROM_SITE, A.ITEM_ID, A.SEQ, A.MEASURE';

            OPEN O_RC1 FOR V_EXEC USING P_FROM_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE;
            /*--//END RESULT//--*/

        ELSE

            /*PIVOIT처리*******************************************************************************/
            /* PIVOIT 대상 날짜문자열 생성 */
            V_QRY_SUM := '';

            FOR R IN (SELECT IA.YYYYMMDD
                        FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                                   , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                              UNION ALL
                              SELECT 'M_' || A.BASIS_YYYYMM AS YYYYMMDD
                                   , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                              UNION ALL
                              SELECT 'D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                                   , A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMMDD) IA
                       ORDER BY IA.SORT_ORDER_NO) LOOP

                IF INSTR(R.YYYYMMDD, 'M_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN A.QTY END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'W_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN A.QTY END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'D_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN A.QTY END) AS ' || R.YYYYMMDD || CHR(10);
                END IF;

            END LOOP;
            /*--//END PIVOT//--*/

            INSERT INTO GT_0021_PIVOT_OLD
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , MEASURE
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , LOT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.YYYYMMDD
                 , IA.YYYYMM
                 , IA.ISO_WEEK
                 , NVL(IA.QTY, 0) AS QTY
                 , IA.LOT_YN
              FROM (SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , NVL(XD.APPLIED_MODEL, XA.ITEM_ID) AS ITEM_ID
                         , XA.MEASURE
                         , SUM(CAST(XA.QTY AS NUMBER(10))) AS QTY
                         , NULL AS LOT_YN
                         , 'D_' || XA.YYYYMMDD AS YYYYMMDD
                         , XB.BASIS_YYYYMM AS YYYYMM
                         , SUBSTR(XB.BASIS_YYYYMM, -4) || XB.ISO_WEEK AS ISO_WEEK
                      FROM SSP_ANL_SHIP_PLAN_C XA
                         , SCM_SYS_CALENDAR_M XB
                         , SCM_MST_SITE XC
                         , SCM_MST_ITEM_SN XD
                     WHERE XA.YYYYMMDD = XB.BASIS_YYYYMMDD
                       /* 2020-03-23 modify by KIMYONGHO 과거 PLAN 조회 시 필요없음 */
                       AND XC.DIVISION_ID = XA.DIVISION_ID
                       AND XC.SCM_SITE_ID = XA.FROM_SITE
                       AND XD.DIVISION_ID(+) = XA.DIVISION_ID
                       AND XD.COMPANY_ID(+) = P_COMPANY_ID
                       AND XD.SITE_ID(+) = XC.SITE_ID
                       AND XD.ITEM_ID(+) = XA.ITEM_ID
                       AND XD.ITEM_CLASS(+) IN ('ES1901', 'ES2001', 'ES2002', 'ES2003', 'ES2004')
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND XA.YYYYMMDD >= SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8)
                       AND XA.YYYYMMDD <= SUBSTR(REPLACE(P_TO_YYYYMMDD, '-', ''), 1, 8)
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                     GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XD.APPLIED_MODEL, XA.ITEM_ID, XA.MEASURE, XA.YYYYMMDD, XB.BASIS_YYYYMM, XB.ISO_WEEK
                    UNION ALL
                    SELECT XA.DIVISION_ID
                         , XA.FROM_SITE_ID AS FROM_SITE
                         , XA.MODEL_ID AS ITEM_ID
                         , 'SHIP_AVAL' AS MEASURE
                         , XA.OUT_QTY AS QTY
                         , NULL AS LOT_YN
                         , 'D_' || XA.PLAN_DATE AS YYYYMMDD
                         , XB.BASIS_YYYYMM AS YYYYMM
                         , SUBSTR(XB.BASIS_YYYYMM, -4) || XB.ISO_WEEK AS ISO_WEEK
                      FROM SSP_DNM_FP_AMEND_SHIPAVAL XA
                         , SCM_SYS_CALENDAR_M XB
                     WHERE XA.PLAN_DATE = XB.BASIS_YYYYMMDD
                       AND XA.OUT_QTY >= 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_DATE >= V_FROM_YYYYMMDD
                       AND XA.PLAN_DATE <= V_TO_YYYYMMDD
                       AND XA.SITE_ID IN (SELECT DISTINCT SA.SITE_ID
                                            FROM SCM_MST_SITE SA
                                           WHERE SA.DIVISION_ID = P_DIVISION_ID
                                             AND SA.COMPANY_ID = P_COMPANY_ID
                                             AND SA.SITE_TYPE = 'PLANT'
                                             AND SA.VALID_YN = 'Y')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE_ID IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                      OR XA.MODEL_ID IN (SELECT COLUMN_VALUE
--                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA;
                        /* OR XA.MODEL_ID MEMBER OF V_ITEM_TAB)) IA; */
                        OR XA.MODEL_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                           FROM TABLE(V_ITEM_TAB)))) IA;   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */

            /*--//RESULT (과거 PLAN)//--*/
            V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
                   || ', A.FROM_SITE' || CHR(10)
                   || ', NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_DESCRIPTION' || CHR(10)
                   || ', (SELECT NVL(SA.NICK_NAME, ''-'') FROM SCM_MST_ITEM_SN SA WHERE SA.ITEM_ID = A.ITEM_ID AND ROWNUM = 1) AS NICK_NAME' || CHR(10)
                   || ', A.ITEM_ID' || CHR(10)
                   || ', CASE WHEN C.BOH_TYPE IS NULL THEN' || CHR(10)
                   || '       CASE B.SORT_ORDER_NO WHEN 5 THEN ''BOH''' || CHR(10)
                   || '                            WHEN 6 THEN ''ERP''' || CHR(10)
                   || '                            WHEN 7 THEN ''oWMS''' || CHR(10)
                   || '                            WHEN 8 THEN ''MES''' || CHR(10)
                   || '       ELSE NULL END' || CHR(10)
                   || '  ELSE C.BOH_TYPE END AS BOH_TYPE' || CHR(10)
                   || ', CASE WHEN (B.SORT_ORDER_NO = 1 OR B.SORT_ORDER_NO = 2 OR B.SORT_ORDER_NO = 3 OR B.SORT_ORDER_NO = 4 OR B.SORT_ORDER_NO = 9) THEN NULL' || CHR(10)
                   || '  ELSE NVL(C.BOH_QTY, 0) END AS BOH_QTY' || CHR(10)
                   || ', CASE A.MEASURE WHEN ''SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''BALANCE'' THEN ''I'' END AS PSI' || CHR(10)
                   || ', A.MEASURE' || CHR(10)
                   || ', B.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                   || ', B.SORT_ORDER_NO' || CHR(10)
                   || ', TO_CHAR(TO_DATE(:B_FROM_YYYYMMDD1, ''YYYYMMDD'') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE1, A.DIVISION_ID, A.FROM_SITE, :B_FROM_YYYYMMDD2) - 1, ''YYYYMMDD'') AS CONFIRM_DAY' || CHR(10)
                   || ', B.ATTRIBUTE3 AS BACK_COLOR' || CHR(10)
                   || ', A.LOT_YN' || CHR(10)
                   || V_QRY_SUM
                   || '  FROM GT_0021_PIVOT_OLD A' || CHR(10)
                   || '     , SCM_MST_SHEET_MEASURE B' || CHR(10)
                   || '     , GT_0021_BOH C' || CHR(10)
                   || '     , SCM_MST_SITE D' || CHR(10)
                   || '     , SCM_MST_TITLESET_USER E' || CHR(10)
                   || ' WHERE A.MEASURE = B.COLUMN_NAME' || CHR(10)
                   || '   AND B.PROGRAM_ID = :B_PROGRAM_ID1' || CHR(10)
                   || '   AND B.SHEET_NAME = :B_SHEET_NAME1' || CHR(10)
                   || '   AND A.DIVISION_ID = C.DIVISION_ID(+)' || CHR(10)
                   || '   AND A.FROM_SITE = C.FROM_SITE(+)' || CHR(10)
                   || '   AND A.ITEM_ID = C.ITEM_ID(+)' || CHR(10)
                   || '   AND B.SORT_ORDER_NO = C.SEQ(+)' || CHR(10)
                   || '   AND A.DIVISION_ID = :B_DIVISION_ID1' || CHR(10)
                   || '   AND D.COMPANY_ID = :B_COMPANY_ID1' || CHR(10)
                   || '   AND A.FROM_SITE = D.SCM_SITE_ID' || CHR(10)
                   || '   AND D.SITE_TYPE = ''PLANT''' || CHR(10)
                   || '   AND D.VALID_YN = ''Y''' || CHR(10)
                   || '   AND E.PROGRAM_ID(+) = B.PROGRAM_ID' || CHR(10)
                   || '   AND E.SHEET_NAME(+) = B.SHEET_NAME' || CHR(10)
                   || '   AND E.COLUMN_NAME(+) = B.COLUMN_NAME' || CHR(10)
                   || '   AND E.USER_ID(+) = :B_USER_ID1' || CHR(10)
                   || '   AND B.VALID_YN = ''Y''' || CHR(10)
                   || '   AND (:B_CNT1 = 0' || CHR(10)
                   || '    OR EXISTS (SELECT 1' || CHR(10)
                   || '                 FROM GT_0021_TITLESET SA' || CHR(10)
                   || '                WHERE SA.COLUMN_NAME = B.COLUMN_NAME))' || CHR(10)
                   || '   AND ((:B_CNT2 = 0 AND B.DEFAULT_FLAG = ''Y'')' || CHR(10)
                   || '    OR (:B_CNT3 <> 0))' || CHR(10);

/*            IF TRIM(P_ITEM_ID) IS NOT NULL THEN */
            IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
--              V_EXEC := V_EXEC || '   AND A.ITEM_ID = :B_ITEM_ID1' || CHR(10);   --  2026.10.07 AJS
/*                V_EXEC := V_EXEC || '   AND A.ITEM_ID MEMBER OF :B_ITEM_TAB1' || CHR(10);   --  2026.10.07 AJS */
                V_EXEC := V_EXEC || '   AND A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(:B_ITEM_TAB1))' || CHR(10);   /* AJS 20261008 Model/Nickname */
            END IF;

            V_EXEC := V_EXEC
                   || ' GROUP BY A.DIVISION_ID, A.FROM_SITE, A.ITEM_ID, A.MEASURE, B.COLUMN_LABEL_NAME, B.SORT_ORDER_NO, C.BOH_TYPE, C.BOH_QTY, D.SHIP_FROZEN, B.ATTRIBUTE3, A.LOT_YN' || CHR(10)
                   || ' ORDER BY A.DIVISION_ID, A.FROM_SITE, A.ITEM_ID, B.SORT_ORDER_NO';

/*            IF TRIM(P_ITEM_ID) IS NOT NULL THEN */
            IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
--              OPEN O_RC1 FOR V_EXEC USING P_FROM_YYYYMMDD, V_APP_TYPE, P_FROM_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_COMPANY_ID, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, P_ITEM_ID;   --  2026.10.07 AJS
                OPEN O_RC1 FOR V_EXEC USING P_FROM_YYYYMMDD, V_APP_TYPE, P_FROM_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_COMPANY_ID, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_ITEM_TAB;   --  2026.10.07 AJS
            ELSE
                OPEN O_RC1 FOR V_EXEC USING P_FROM_YYYYMMDD, V_APP_TYPE, P_FROM_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_COMPANY_ID, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE;
            END IF;

        END IF;

    END P_SSP0021_GET_SHIPMENT_PLAN;
    PROCEDURE P_SSP0021_GET_SHIPMENT_PLAN_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_REQUESTOR             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_GET_SHIPMENT_PLAN_DETAIL
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/06   mcThej			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/11/14   ayj				CHANGE_REASON_CODE, CHANGE_REASON_DETAIL SELECT 값 수정
 * 2019/12/17	KIMYONGHO		[C20191216-000311] Expected Shipping Date 컬럼 추가
 * 2020/01/21   juhlee          [C20200121-000352]  ESS Packer출하 적용
 * 2020/02/10   KIMYONGHO       Shipmnet Status 조회 시 공통코드 타입으로 조회
 * 2020/03/12   KIMYONGHO       [C20200226-000471] Shipment Detail 탭 Project code 표시
 * 2020/03/26   KIMYONGHO       [C20200326-000217] Shipment Detail 탭 Team, Project Name 표시
 * 2021/02/04   KIMYONGHO	    ETA_DATE 조회 시 항차를 고려한 LT 적용(FN_GET_SSP_ETA_DATE)
 * 2021/10/18   KIMYONGHO	    [C20211001-000241][SCM PI팀] Shipment Plan (Auto ESS) 기능 개선 의건
 * 2022/12/19   jilee    	    오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영)
 * 2024/05/10   hsbang          확정구간 조회 일수(CONFIRM_DAY)를 FN_GET_ANL_SHIP_FROZEN_DAY_CNT 에서 조회
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 - 마케팅 담당자 이름 함수 결과를 같은 담당자끼리 재사용(결과 동일)
 * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭(P_DBL_FLAG=Y) 상세는 입력 코드 정확일치
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_APP_TYPE          VARCHAR2(8) := 'SSP';
        V_DBL_FROM          VARCHAR2(8);
        V_DBL_TO            VARCHAR2(8);
    BEGIN

        /* 2026.10.07 AJS Model/Nickname 검색 (START) : 입력값(쉼표 구분)이 코드 또는 닉네임에 부분일치하는 품목을 먼저 고른다
           대상 품목 = 해당 사업부 품목 원장(코드 · 닉네임) + 입력값 그대로(기존 정확일치 유지) */
/*        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN */
        IF P_DBL_FLAG = 'Y' THEN   /* AJS 20261008 Model/Nickname : 더블클릭 상세는 넘겨받은 행의 코드만(정확일치) */
            SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
              BULK COLLECT INTO V_ITEM_TAB   /* AJS 20261008 Model/Nickname */
              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))   /* AJS 20261008 Model/Nickname */
             WHERE COLUMN_VALUE IS NOT NULL;   /* AJS 20261008 Model/Nickname */
        ELSIF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
            SELECT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT COLUMN_VALUE
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))
                     WHERE COLUMN_VALUE IS NOT NULL) IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 더블클릭이면 단일 일자, 아니면 기간 */
        IF P_DBL_FLAG = 'Y' THEN
            V_DBL_FROM := P_FROM_YYYYMMDD;
            V_DBL_TO := P_FROM_YYYYMMDD;
        ELSE
            V_DBL_FROM := P_FROM_YYYYMMDD;
            V_DBL_TO := P_TO_YYYYMMDD;
        END IF;

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.SHIPMENT_STATUS
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , A.FROM_SITE
                     , A.TO_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION
                     , NVL(A.PROJECT_CODE, '/') AS PROJECT_CODE
                     , NVL(FN_GET_PROJECT_NAME(A.DIVISION_ID, A.PROJECT_CODE), '-') AS PROJECT_NAME
                     , NVL(CASE WHEN A.DIVISION_ID = '40' THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-' THEN A.PROJECT_CODE ELSE E.PROJECT_CODE END
                                WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40' THEN E.PROJECT_CODE
                                ELSE D.END_CUSTOMER
                           END, NVL(L.END_CUSTOMER, '-')) AS END_CUSTOMER
--                     , CASE WHEN K.OWNER IS NOT NULL THEN TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(K.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                     , CASE WHEN K.OWNER IS NOT NULL THEN TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(K.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
--                            ELSE TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(L.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                            ELSE TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(L.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
                       END AS MTK_OWNER
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN I.USERNAME ELSE I.USERNAME_E END) IS NULL THEN NULL
--                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN I.USERNAME ELSE I.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS REQUESTOR
                     , CAST(A.QTY AS NUMBER(10)) AS SHIPMENT_CONFIRM_QTY
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                     , B.TRANSPORT_MODE
                     , A.REMARKS2
                     , A.REMARKS
                     , '-' AS CHANGE_REASON_CODE
                     , NULL AS CHANGE_REASON_DETAIL
                     , A.REMARKS3
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                     /* 20201223 incoterms 변경 작업 modify KIMYONGHO */
                     , B.SSP_INCOTERMS AS INCOTERMS
                     , B.LT_TOTAL AS LT_DAY
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                     , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                            ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')
                       END AS EXPECTED_SHIPPING_DATE
                     , A.FCST_TYPE
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END) IS NULL THEN NULL
--                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS UPDATED_BY
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN C.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                     , CASE WHEN C.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                     /* 2026.09.30 AJS 수정 (END) */
                     , F.CHANGE_REQ_NO
                     /* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN H.USERNAME ELSE H.USERNAME_E END) IS NULL THEN NULL
--                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN H.USERNAME ELSE H.USERNAME_E END) || '(' || G.USER_ID || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END) || '(' || G.USER_ID || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS MODEL_USER
                     , A.CONFIRM_ID
                     , B.LT_TOTAL AS NEW_LT_DAY
                     , B.TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                     , A.ERP_STATUS
                     , A.CHANGE_TYPE
                     , A.NEW_ROUTE_ID
                     , A.NEW_BOD_ID
                     , A.NEW_INCOTERMS
                     , A.NEW_D_COUNTRY
                     , A.NEW_D_PORT_CODE
                     , A.NEW_A_COUNTRY
                     , A.NEW_A_PORT_CODE
                     , A.NEW_CUSTOMER_LT
                     , A.NEW_TO_COUNTRY
                     , A.NEW_TO_CITY
                     , A.NEW_ETA
                     , A.NEW_ETD
                     , A.NEW_SHIPMENT_DATE
                     , A.EDIT_REMARKS
                     , A.EDIT_MAIN
                     , A.CHECK_NEED_YN
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     /* 20211117	SMS	수정 */
                     , NVL(E.DEPT_NAME_KO, NVL(L.DEPT_NAME_KO, '-')) AS TEAM
                     , A.ATTRIBUTE10
                     /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                     , B.A_COUNTRY
                     , B.A_PORT_CODE
                     , J.A_PORT_NAME
                     , P.COUNTRY_NAME
                     , Q.CITY_NAME
                     , O.SHIPTO_REGION_NAME
                     , O.SHIPTO_CITY_NAME
                  FROM (SELECT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.SHIPMENT_STATUS AS SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.PROJECT_CODE
                             , XA.REQUESTOR
                             , XA.QTY
                             , XA.YYYYMMDD
                             , XA.BOD_ID
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.CONFIRM_ID
                             , XA.FCST_TYPE
                             , XA.ERP_STATUS
                             , XA.CHANGE_TYPE
                             , TO_CHAR(XA.ROUTE_ID) AS NEW_ROUTE_ID
                             , XA.BOD_ID AS NEW_BOD_ID
                             , XA.INCOTERMS AS NEW_INCOTERMS
                             , XA.D_COUNTRY AS NEW_D_COUNTRY
                             , XA.D_PORT_CODE AS NEW_D_PORT_CODE
                             , XA.A_COUNTRY AS NEW_A_COUNTRY
                             , XA.A_PORT_CODE AS NEW_A_PORT_CODE
                             , TO_CHAR(XA.CUSTOMER_LT) AS NEW_CUSTOMER_LT
                             , XA.TO_COUNTRY AS NEW_TO_COUNTRY
                             , XA.TO_CITY AS NEW_TO_CITY
                             , TO_CHAR(TO_DATE(XA.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                             , TO_CHAR(TO_DATE(XA.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                             , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                             , 'N' AS EDIT_REMARKS
                             , 'N' AS EDIT_MAIN
                             , NVL(XA.CHECK_NEED_YN, 'N') AS CHECK_NEED_YN
                             , XA.ELECTRODE_YN
                             , XA.ELECTRODE_TYPE
                             , XA.ATTRIBUTE10
                          FROM SSP_ANL_SHIP_CONFIRM XA
                             , SCM_MST_ITEM_SN XB
                         WHERE XA.ITEM_ID = XB.ITEM_ID
                           AND XA.DIVISION_ID = XB.DIVISION_ID
                           AND XA.FROM_SITE_COMPANY_ID = XB.COMPANY_ID
                           AND XB.ITEM_TYPE NOT IN ('Q', 'R')
                           AND XA.CHANGE_TYPE = 'C'
                           AND XA.DIVISION_ID = P_DIVISION_ID
                           AND XA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                           AND XA.BIZ_TYPE <> 'E'
                           AND XA.YYYYMMDD >= V_DBL_FROM
                           AND XA.YYYYMMDD <= V_DBL_TO
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                          OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                            /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                            OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           /* 원문은 조회조건 값을 그대로 IN 절에 넣어 값으로 찾지 못한다 — 값 비교로 바로잡음 */
                           AND (P_DBL_FLAG = 'Y'
                            OR TRIM(P_REQUESTOR) IS NULL
                            /* 2026.09.30 AJS 수정 (START) */
--                            OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                  FROM TB_FX_USER SA
--                                                 WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                            OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                  FROM SCM_ADM_USER_M SA
                                                 WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
                            /* 2026.09.30 AJS 수정 (END) */
                                                                         FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                    /* 2026.09.30 AJS 수정 (START) */
--                                                    OR SA.USERID IN (SELECT COLUMN_VALUE
                                                    OR SA.USER_ID IN (SELECT COLUMN_VALUE
                                                    /* 2026.09.30 AJS 수정 (END) */
                                                                       FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))
                        UNION ALL
                        SELECT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.PROJECT_CODE
                             , XA.REQUESTOR
                             , XA.QTY
                             , XA.YYYYMMDD
                             , XA.BOD_ID
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.CONFIRM_ID
                             , XA.FCST_TYPE
                             , '-' AS ERP_STATUS
                             , '-' AS CHANGE_TYPE
                             , '-' AS NEW_ROUTE_ID
                             , '-' AS NEW_BOD_ID
                             , '-' AS NEW_INCOTERMS
                             , '-' AS NEW_D_COUNTRY
                             , '-' AS NEW_D_PORT_CODE
                             , '-' AS NEW_A_COUNTRY
                             , '-' AS NEW_A_PORT_CODE
                             , '-' AS NEW_CUSTOMER_LT
                             , '-' AS NEW_TO_COUNTRY
                             , '-' AS NEW_TO_CITY
                             , '-' AS NEW_ETA
                             , '-' AS NEW_ETD
                             , '-' AS NEW_SHIPMENT_DATE
                             , '-' AS EDIT_REMARKS
                             , '-' AS EDIT_MAIN
                             , '-' AS CHECK_NEED_YN
                             , '-' AS ELECTRODE_YN
                             , '-' AS ELECTRODE_TYPE
                             , '-' AS ATTRIBUTE10
                          FROM (SELECT SA.DIVISION_ID
                                     , '-' AS ERP_SO_NO
                                     , 'P' AS SHIPMENT_STATUS
                                     , SA.ITEM_ID
                                     , SA.DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
                                     , SA.DIVISION_ID AS ORIGIN_TO_DIVISION_ID
                                     , SA.PLANT_SITE_ID AS FROM_SITE
                                     , SA.SCM_SITE_ID AS TO_SITE
                                     , SA.PROJECT_CODE
                                     , '-' AS REQUESTOR
                                     , SA.QTY
                                     , SA.YYYYMMDD
                                     , SA.BOD_ID
                                     , '-' AS REMARKS2
                                     , '-' AS REMARKS
                                     , '-' AS CHANGE_REQ_NO
                                     , '-' AS REMARKS3
                                     , SA.YYYYMMDD AS ETD_DATE
                                     /* 2021/02/04 KIMYONGHO ETA_DATE 조회 시 항차를 고려한 LT 적용 FN_GET_SSP_ETA_DATE */
                                     , FN_GET_SSP_ETA_DATE(SA.DIVISION_ID, SA.BOD_ID, SA.YYYYMMDD) AS ETA_DATE
                                     , SA.LAST_UPDATED_BY
                                     , SA.LAST_UPDATE_DATE
                                     , '-' AS CONFIRM_ID
                                     , SA.FCST_TYPE
                                     , CASE WHEN NVL(SC.SHIP_FROZEN, 0) > 0
                                            THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, SC.DIVISION_ID, SC.SCM_SITE_ID, P_PLAN_START_YYYYMMDD), 'YYYYMMDD')
                                            ELSE P_PLAN_START_YYYYMMDD
                                       END AS FROZEN_YYYYMMDD
                                  FROM DM_PLN_SHIPMENT_REQ SA
                                     , SCP_MST_BOD_N_V SB
                                     , SCM_MST_SITE SC
                                 WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                   AND SA.BOD_ID = SB.BOD_ID
                                   AND SA.DIVISION_ID = SC.DIVISION_ID
                                   AND SA.PLANT_SITE_ID = SC.SCM_SITE_ID
                                   AND SC.SITE_TYPE = 'PLANT'
                                   /* [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN = 'N' 조건제외) */
                                   /* AND tt2.osp_yn = 'N' */
                                   AND SC.VALID_YN = 'Y'
                                   AND SA.DIVISION_ID = P_DIVISION_ID
                                   AND SC.COMPANY_ID = P_COMPANY_ID
                                   AND SA.YYYYMMDD >= V_DBL_FROM
                                   AND SA.YYYYMMDD <= V_DBL_TO
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                  OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                    /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                    OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR SA.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) XA
                         WHERE XA.YYYYMMDD >= XA.FROZEN_YYYYMMDD) A
                     , SCP_MST_BOD_N_V B
                     /* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER C
                     , SCM_ADM_USER_M C
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE D
                     , (SELECT SA.DIVISION_ID
                             , SA.PROJECT_CODE
                             , SA.SCM_SITE_ID
                             , SA.ITEM_ID
                             , SA.DEPT_NAME_KO
                          FROM (SELECT XA.DIVISION_ID
                                     , XA.PROJECT_CODE
                                     , XA.SCM_SITE_ID
                                     , XA.ITEM_ID
                                     , XC.DEPT_NAME_KO
                                     , ROW_NUMBER() OVER (PARTITION BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.ITEM_ID ORDER BY XA.PROJECT_CODE) AS NUM
                                  FROM SCM_MST_SITE_ITEM XA
                                     /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--                                     , SCM_MST_SITE XB
                                     , SCM_MST_SSO_DEPT_INFO XC
--                                 WHERE XB.SCM_SITE_ID(+) = XA.SCM_SITE_ID
--                                   AND XB.DEPT_ID = XC.DEPT_ID(+)) SA
                                 WHERE XA.DEPT_ID = XC.DEPT_ID(+)) SA
                                     /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
                         WHERE SA.NUM = 1) E
                     , (SELECT SA.CONFIRM_ID
                             , SA.CHANGE_REQ_NO
                          FROM (SELECT XA.CONFIRM_ID
                                     , XA.CHANGE_REQ_NO
                                     , ROW_NUMBER() OVER (PARTITION BY XA.CONFIRM_ID ORDER BY XA.CHANGE_REQ_NO DESC) AS NUM
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE XA
                                 WHERE XA.VALID_YN = 'Y') SA
                         WHERE SA.NUM = 1) F
                     , SSP_MST_MODEL_USER G
                     /* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER H
--                     , TB_FX_USER I
                     , SCM_ADM_USER_M H
                     , SCM_ADM_USER_M I
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCP_MST_DISTRIBUTION_ROUTE J
                     , SCM_MST_SITE_ITEM K
                     , (SELECT IB.PLANT_ID
                             , IB.DIVISION_ID
                             , IB.PROJECT_CODE
                             , IB.SCM_SITE_ID
                             , IB.ITEM_ID
                             , SB.DEPT_ID
                             , NVL(SC.DEPT_NAME_KO, '-') AS DEPT_NAME_KO
                             , IB.OWNER AS OWNER
                             , IB.END_CUSTOMER
                             , IB.TO_SITE_DESCRIPTION
                          FROM (SELECT SA.SEGMENT2 AS PLANT_ID
                                     , SB.DIVISION_ID
                                     , SB.PROJECT_CODE
                                     , SB.SCM_SITE_ID
                                     , SB.ITEM_ID
                                     , SB.OWNER
                                     , NVL(SC.END_CUSTOMER, '-') AS END_CUSTOMER
                                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(SA.SEGMENT3, SA.SEGMENT2), '-') AS TO_SITE_DESCRIPTION
                                     , TRIM(REGEXP_SUBSTR(SB.OWNER, '[^,]+', 1, 1)) AS FIRST_OWNER
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                     , SCM_MST_SITE_ITEM SB
                                     , SCM_MST_SITE SC
                                 WHERE SA.LOOKUP_TYPE = 'AS_SITE_PLANT'
                                   AND SA.SEGMENT1 = SB.SCM_SITE_ID
                                   AND SB.DIVISION_ID = SC.DIVISION_ID(+)
                                   AND SB.SCM_SITE_ID = SC.SCM_SITE_ID(+)) IB
                             , SCM_MST_SSO_USER_INFO SB
                             , SCM_MST_SSO_DEPT_INFO SC
                         WHERE IB.FIRST_OWNER = SB.USER_ID(+)
                           AND SB.DEPT_ID = SC.DEPT_ID(+)) L
                     , SSP_ANL_SHIP_CONFIRM_CHG_REQ M
                     , SCM_MST_CUSTOMER O
                     , SCM_MST_COUNTRY P
                     , SCM_MST_CITY Q
                     , SCM_MST_SITE_CUSTOMER R
                 WHERE (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = B.DIVISION_ID
                   AND A.BOD_ID = B.BOD_ID
                   /* 2026.09.30 AJS 수정 (START) */
--                   AND A.LAST_UPDATED_BY = C.USERID(+)
--                   AND C.USEYN(+) = 'Y'
                   AND A.LAST_UPDATED_BY = C.USER_ID(+)
                   AND C.USE_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND D.SCM_SITE_ID = A.TO_SITE
                   /* NERP 적용시 GERP COMPANY_ID에 해당하는 것은 제외 필요함 */
                   AND D.VALID_YN = 'Y'
                   AND D.DIVISION_ID = A.DIVISION_ID
                   AND E.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END)
                   AND E.SCM_SITE_ID(+) = A.TO_SITE
                   AND E.ITEM_ID(+) = A.ITEM_ID
                   AND F.CONFIRM_ID(+) = A.CONFIRM_ID
                   AND G.DIVISION_ID(+) = A.ORIGIN_FROM_DIVISION_ID
                   AND G.FROM_SITE(+) = A.FROM_SITE
                   AND G.ITEM_ID(+) = A.ITEM_ID
                   AND G.VALID_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (START) */
--                   AND G.USER_ID = H.USERID(+)
--                   AND H.USEYN(+) = 'Y'
--                   AND A.REQUESTOR = I.USERID(+)
--                   AND I.USEYN(+) = 'Y'
                   AND G.USER_ID = H.USER_ID(+)
                   AND H.USE_YN(+) = 'Y'
                   AND A.REQUESTOR = I.USER_ID(+)
                   AND I.USE_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND J.ROUTE_ID(+) = B.ROUTE_ID
                   AND K.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END)
                   AND K.SCM_SITE_ID(+) = A.TO_SITE
                   AND K.ITEM_ID(+) = A.ITEM_ID
                   AND K.PROJECT_CODE(+) = A.PROJECT_CODE
                   /* 20211117	SMS	추가 */
                   AND A.DIVISION_ID = L.DIVISION_ID(+)
                   AND A.PROJECT_CODE = L.PROJECT_CODE(+)
                   AND A.TO_SITE = L.PLANT_ID(+)
                   AND A.ITEM_ID = L.ITEM_ID(+)
                   AND F.CHANGE_REQ_NO = M.CHANGE_REQ_NO(+)
                   /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                   AND D.DIVISION_ID = R.DIVISION_ID(+)
                   AND D.SCM_SITE_ID = R.SCM_SITE_ID(+)
                   AND R.REP_YN(+) = 'Y'
                   AND R.VALID_YN(+) = 'Y'
                   AND R.DIVISION_ID = O.DIVISION_ID(+)
                   AND R.SOLDTO_CODE = O.SOLDTO_CODE(+)
                   AND R.SHIPTO_CODE = O.SHIPTO_CODE(+)
                   AND D.COUNTRY = P.COUNTRY(+)
                   AND D.COUNTRY = Q.COUNTRY(+)
                   AND D.CITY = Q.CITY(+)
                   AND A.SHIPMENT_STATUS IS NOT NULL
                   AND A.QTY > 0
                 ORDER BY A.DIVISION_ID, A.SHIPMENT_STATUS, A.YYYYMMDD, A.ITEM_ID, A.ERP_SO_NO DESC, A.FROM_SITE, A.TO_SITE, A.PROJECT_CODE, A.FCST_TYPE;

        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ERP_SO_NO
                             , A.SHIPMENT_STATUS
                             , A.PROJECT_CODE
                             , A.PROJECT_NAME
                             , A.FCST_TYPE
                             , A.ITEM_ID
                             , A.NICK_NAME
                             , A.SHIPMENT_DATE
                             , A.SHIPMENT_CONFIRM_QTY
                             , A.REMARKS
                             , A.REMARKS2
                             , A.REMARKS3
                             , A.FROM_SITE
                             , A.FROM_SITE_DESCRIPTION
                             , A.TO_SITE
                             , A.TO_SITE_DESCRIPTION
                             , A.TO_SITE_SOLDTO_CODE
                             , A.TO_SITE_SHIPTO_CODE
                             , A.SOLDTO_DESCRIPTION
                             , A.SHIPTO_DESCRIPTION
                             , A.BOD_ID
                             , A.INCOTERMS
                             , A.TRANSPORT_MODE
                             , A.LT_DAY
                             , A.ETD
                             , A.ETA
                             , A.EXPECTED_SHIPPING_DATE
                             , A.CONFIRM_ID
                             , A.UPDATED_BY
                             , A.UPDATED_DATE
                             , '-' AS ERP_STATUS
                             , '-' AS CHANGE_TYPE
                             , '-' AS NEW_ROUTE_ID
                             , '-' AS NEW_BOD_ID
                             , '-' AS NEW_INCOTERMS
                             , '-' AS NEW_D_COUNTRY
                             , '-' AS NEW_D_PORT_CODE
                             , '-' AS NEW_A_COUNTRY
                             , '-' AS NEW_A_PORT_CODE
                             , '-' AS NEW_CUSTOMER_LT
                             , '-' AS NEW_TO_COUNTRY
                             , '-' AS NEW_TO_CITY
                             , '-' AS NEW_ETA
                             , '-' AS NEW_ETD
                             , '-' AS NEW_LT_DAY
                             , '-' AS NEW_TRANSPORT_MODE
                             , '-' AS NEW_SHIPMENT_DATE
                             , '-' AS EDIT_REMARKS
                             , '-' AS EDIT_MAIN
                             , '-' AS CHECK_NEED_YN
                             /* 20211118	SMS	수정 */
                             , CASE WHEN A.END_CUSTOMER IS NOT NULL AND A.END_CUSTOMER <> '-' THEN A.END_CUSTOMER ELSE NVL(B.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , '-' AS ELECTRODE_YN
                             , '-' AS ELECTRODE_TYPE
                             , '-' AS ORIGIN_FROM_DIVISION_ID
                             , '-' AS ORIGIN_TO_DIVISION_ID
                             , A.CHANGE_REQ_NO AS CHANGE_REQ_NO
                             , A.MODEL_USER AS MODEL_USER
                             /* 20211118	SMS	수정 */
                             , CASE WHEN A.MTK_OWNER IS NOT NULL AND A.MTK_OWNER <> '-' THEN A.MTK_OWNER
--                                    ELSE TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(B.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                                    ELSE TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(B.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
                               END AS MTK_OWNER
                             , A.REQUESTOR AS REQUESTOR
                             , '-' AS CHANGE_REASON_CODE
                             , '-' AS CHANGE_REASON_DETAIL
                             /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                             , F.A_COUNTRY
                             , F.A_PORT_CODE
                             , G.A_PORT_NAME
                             , H.COUNTRY_NAME
                             , I.CITY_NAME
                             , J.SHIPTO_REGION_NAME
                             , J.SHIPTO_CITY_NAME
                          FROM (SELECT XA.DIVISION_ID
                                     , XA.ERP_SO_NO
                                     , XA.SHIPMENT_STATUS
                                     , XA.ITEM_ID
                                     , XA.NICK_NAME
                                     , XA.ORIGIN_FROM_DIVISION_ID
                                     , XA.ORIGIN_TO_DIVISION_ID
                                     , XA.FROM_SITE
                                     , XA.FROM_SITE_DESCRIPTION
                                     , XA.TO_SITE
                                     , XA.TO_SITE_DESCRIPTION
                                     , XA.PROJECT_CODE
                                     , XA.PROJECT_NAME
                                     , XA.REQUESTOR
                                     , XA.SHIPMENT_CONFIRM_QTY
                                     , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                                     , XA.BOD_ID
                                     , XA.INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.TO_SITE_SOLDTO_CODE
                                     , XA.TO_SITE_SHIPTO_CODE
                                     , XA.SOLDTO_DESCRIPTION
                                     , XA.SHIPTO_DESCRIPTION
                                     , XA.REMARKS2
                                     , XA.REMARKS
                                     , XA.CHANGE_REQ_NO
                                     , XA.REMARKS3
                                     , TO_CHAR(TO_DATE(XA.ETD, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                                     , TO_CHAR(TO_DATE(XA.ETA, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                                     , XA.EXPECTED_SHIPPING_DATE
                                     , XA.LT_DAY AS LT_DAY
                                     , XA.UPDATED_BY AS UPDATED_BY
                                     , XA.UPDATED_DATE AS UPDATED_DATE
                                     , XA.CONFIRM_ID AS CONFIRM_ID
                                     , XA.FCST_TYPE
                                     , XA.END_CUSTOMER
                                     , XA.MTK_OWNER
                                     , XA.MODEL_USER
                                  FROM SSP_ANL_SHIP_PLAN_ALL XA
                                     , SCM_MST_ITEM_SN XB
                                     , SSP_MST_MODEL_USER XC
                                 WHERE XA.ITEM_ID = XB.ITEM_ID
                                   AND XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.COMPANY_ID = XB.COMPANY_ID
                                   AND XB.ITEM_TYPE NOT IN ('Q', 'R')
                                   AND XC.DIVISION_ID(+) = XA.ORIGIN_FROM_DIVISION_ID
                                   AND XC.FROM_SITE(+) = XA.FROM_SITE
                                   AND XC.ITEM_ID(+) = XA.ITEM_ID
                                   AND XC.VALID_YN(+) = 'Y'
                                   AND XA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XA.COMPANY_ID = P_COMPANY_ID
                                   AND XA.SHIPMENT_CONFIRM_QTY > 0
                                   AND XA.OPERATION_GROUP <> 'E'
                                   AND XA.YYYYMMDD >= V_DBL_FROM
                                   AND XA.YYYYMMDD <= V_DBL_TO
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                                  OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB) */
                                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                          FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                   /* 원문은 조회조건 값을 그대로 IN 절에 넣어 값으로 찾지 못한다 — 값 비교로 바로잡음 */
                                   AND (P_DBL_FLAG = 'Y'
                                    OR TRIM(P_REQUESTOR) IS NULL
                                    /* 2026.09.30 AJS 수정 (START) */
--                                    OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                          FROM TB_FX_USER SA
--                                                         WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                                    OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                          FROM SCM_ADM_USER_M SA
                                                         WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
                                    /* 2026.09.30 AJS 수정 (END) */
                                                                                 FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                            /* 2026.09.30 AJS 수정 (START) */
--                                                            OR SA.USERID IN (SELECT COLUMN_VALUE
                                                            OR SA.USER_ID IN (SELECT COLUMN_VALUE
                                                            /* 2026.09.30 AJS 수정 (END) */
                                                                               FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))) A
                             , (SELECT IB.PLANT_ID
                                     , IB.DIVISION_ID
                                     , IB.PROJECT_CODE
                                     , IB.SCM_SITE_ID
                                     , IB.ITEM_ID
                                     , NVL(SC.DEPT_NAME_KO, '-') AS DEPT_NAME_KO
                                     , IB.OWNER AS OWNER
                                     , IB.END_CUSTOMER
                                     , IB.TO_SITE_DESCRIPTION
                                  FROM (SELECT SA.SEGMENT2 AS PLANT_ID
                                             , SB.DIVISION_ID
                                             , SB.PROJECT_CODE
                                             , SB.SCM_SITE_ID
                                             , SB.ITEM_ID
                                             , SB.OWNER
                                             , NVL(SC.END_CUSTOMER, '-') AS END_CUSTOMER
                                             , NVL(FN_GET_SCM_SITE_DESCRIPTION(SA.SEGMENT3, SA.SEGMENT2), '-') AS TO_SITE_DESCRIPTION
                                             , TRIM(REGEXP_SUBSTR(SB.OWNER, '[^,]+', 1, 1)) AS FIRST_OWNER
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                             , SCM_MST_SITE_ITEM SB
                                             , SCM_MST_SITE SC
                                         WHERE SA.LOOKUP_TYPE = 'AS_SITE_PLANT'
                                           AND SA.SEGMENT1 = SB.SCM_SITE_ID
                                           AND SB.DIVISION_ID = SC.DIVISION_ID(+)
                                           AND SB.SCM_SITE_ID = SC.SCM_SITE_ID(+)) IB
                                     , SCM_MST_SSO_USER_INFO SB
                                     , SCM_MST_SSO_DEPT_INFO SC
                                 WHERE IB.FIRST_OWNER = SB.USER_ID(+)
                                   AND SB.DEPT_ID = SC.DEPT_ID(+)) B
                             , SCM_MST_SITE E
                             , SCP_MST_BOD_N_V F
                             , SCP_MST_DISTRIBUTION_ROUTE G
                             , SCM_MST_COUNTRY H
                             , SCM_MST_CITY I
                             , SCM_MST_CUSTOMER J
                             , SCM_MST_SITE_CUSTOMER K
                         WHERE A.DIVISION_ID = B.DIVISION_ID(+)
                           AND A.PROJECT_CODE = B.PROJECT_CODE(+)
                           AND A.TO_SITE_DESCRIPTION = B.TO_SITE_DESCRIPTION(+)
                           AND A.ITEM_ID = B.ITEM_ID(+)
                           /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                           AND E.DIVISION_ID(+) = A.DIVISION_ID
                           AND E.SCM_SITE_ID(+) = A.TO_SITE
                           AND E.VALID_YN(+) = 'Y'
                           AND (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = F.DIVISION_ID(+)
                           AND A.BOD_ID = F.BOD_ID(+)
                           AND G.ROUTE_ID(+) = F.ROUTE_ID
                           AND E.DIVISION_ID = K.DIVISION_ID(+)
                           AND E.SCM_SITE_ID = K.SCM_SITE_ID(+)
                           AND K.REP_YN(+) = 'Y'
                           AND K.VALID_YN(+) = 'Y'
                           AND K.DIVISION_ID = J.DIVISION_ID(+)
                           AND K.SOLDTO_CODE = J.SOLDTO_CODE(+)
                           AND K.SHIPTO_CODE = J.SHIPTO_CODE(+)
                           AND E.COUNTRY = H.COUNTRY(+)
                           AND E.COUNTRY = I.COUNTRY(+)
                           AND E.CITY = I.CITY(+)) IA
                 ORDER BY IA.DIVISION_ID, IA.SHIPMENT_STATUS, IA.SHIPMENT_DATE, IA.ITEM_ID, IA.ERP_SO_NO DESC, IA.FROM_SITE, IA.TO_SITE, IA.PROJECT_CODE, IA.FCST_TYPE;

        END IF;

    END P_SSP0021_GET_SHIPMENT_PLAN_DETAIL;
    PROCEDURE P_SSP0021_DELETE_SHIPMENT_REQUEST_DRAFTING
    (
        P_CHANGE_REQUEST_NO     IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_DELETE_SHIPMENT_REQUEST_DRAFTING
 * Description  : Shipment Plan Change 작성중 삭제
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_LAST_UPDATE_DATE  DATE;
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150) := 'PKG_SSP0021.P_SSP0021_DELETE_SHIPMENT_REQUEST_DRAFTING';
        V_LOG_TYPE          VARCHAR2(30);                                       /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000);
        V_DESCRIPTION       VARCHAR2(500);
        D_EVENT_DATE        DATE;
        V_ERR_MSG           VARCHAR2(4000);
        V_ERR_CODE          NUMBER;
    BEGIN

        V_LAST_UPDATE_DATE := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := V_LAST_UPDATE_DATE;                                     /* [dbo].[FN_MULTY_TIME](@p_time_zone); */
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0021_DELETE_SHIPMENT_REQUEST_DRAFTING;

    PROCEDURE P_SSP0021_SAVE_SHIPMENT_REQUEST_DRAFTING
    (
        P_ACTIVE_FLAG               IN  VARCHAR2
       ,P_DIVISION_ID               IN  VARCHAR2
       ,P_CONFIRM_ID                IN  VARCHAR2
       ,P_SHIPMENT_QTY              IN  VARCHAR2
       ,P_SHIPMENT_DATE             IN  VARCHAR2
       ,P_FROM_SITE                 IN  VARCHAR2
       ,P_NEW_BOD_ID                IN  VARCHAR2
       ,P_NEW_ROUTE_ID              IN  VARCHAR2
       ,P_NEW_ETD_DATE              IN  VARCHAR2
       ,P_NEW_ETA_DATE              IN  VARCHAR2
       ,P_NEW_INCOTERMS             IN  VARCHAR2
       ,P_NEW_TRANSPORT_MODE        IN  VARCHAR2
       ,P_NEW_D_CONTRY              IN  VARCHAR2
       ,P_NEW_D_PORT_CODE           IN  VARCHAR2
       ,P_NEW_A_COUNTRY             IN  VARCHAR2
       ,P_NEW_A_PORT_CODE           IN  VARCHAR2
       ,P_NEW_CUSTOMER_LT           IN  VARCHAR2
       ,P_NEW_TO_COUNTRY            IN  VARCHAR2
       ,P_NEW_TO_CITY               IN  VARCHAR2
       ,P_EDIT_MAIN                 IN  VARCHAR2
       ,P_EDIT_REMARK               IN  VARCHAR2
       ,P_USER_ID                   IN  VARCHAR2
       ,P_USER_DEPT_ID              IN  VARCHAR2
       ,P_ELECTRODE_YN              IN  VARCHAR2
       ,P_ELECTRODE_TYPE            IN  VARCHAR2
       ,P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2
       ,P_ORIGION_TO_DIVISION_ID    IN  VARCHAR2
       ,P_REMARKS                   IN  VARCHAR2
       ,P_REMARKS2                  IN  VARCHAR2
       ,P_REMARKS3                  IN  VARCHAR2
       ,P_CHANGE_REASON_CODE        IN  VARCHAR2
       ,P_CHANGE_REASON_DETAIL      IN  VARCHAR2
       ,P_TITLE                     IN  VARCHAR2
       ,P_PROGRAM_ID                IN  VARCHAR2
       ,O_RC1                       OUT SYS_REFCURSOR
       ,O_RC2                       OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_SAVE_SHIPMENT_REQUEST_DRAFTING
 * Description  : Shipment Plan Change 작성중 저장
 * 호출			: SSP0021
 * 관련 Table	: SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
 * 관련 프로시저 : PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN - ERP 관련 Table)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2019/04/03	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REMARKS, REMARKS 컬럼 추가
 * 2019/04/30	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REQUESTOR 컬럼 변경
 * 2019/05/07	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REMARKS3 컬럼 추가
 * 2019/05/15	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  CHAGE_REASON_CODE, CHAGE_REASON_DETAIL PARAM추가
 * 2019/05/28	mcTheJ			[PJ20189106] 전지.GSCM 고도화 이행  CHANGE_TITLE 수정
 * 2019/05/29	mcTheJ			[PJ20189106] 전지.GSCM 고도화 이행  CHANGE_REASON 추가로 인한 CS코드에서 반복 호출(단. SONo의 경우 통으로 Parameter 넘김)
 * 2019/09/04	AYJ				etd:shipdate, eta:etd+lt_day로 셋팅
 * 2019/10/29	ayj				FCST_ETA_DATE, ETA_DATE 저장 값 수정(출발일 기준 항차를 고려한 ETA_DATE 계산)
 * 2020-02-26   KIMYONGHO           [C20200224-000318]출하변경사유 코드 변경   R01 - > T07
 * 2021/09/02   KIMYONGHO      SCP_MST_BOD_v -> SCP_MST_BOD_N_V 변경
 * 2021/10/18   KIMYONGHO	   [C20211001-000241][SCM PI팀] Shipment Plan (Auto ESS) 기능 개선 의건
 * 2024/05/08   jilee          PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH  'C' 변경요청
 * 2024/05/22	hsbang			SSP_ANL_SHIP_CONFIRM_CHG_REQ_de A.ATTRIBUTE2(status_detail) 입력
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_MAX_REQ_NO                VARCHAR2(40);
        V_ACTIVE_FLAG               VARCHAR2(4000);
        V_DIVISION_ID               VARCHAR2(4000);
        V_CONFIRM_ID                VARCHAR2(4000);
        V_SHIPMENT_QTY              VARCHAR2(4000);
        V_SHIPMENT_DATE             VARCHAR2(4000);
        V_FROM_SITE                 VARCHAR2(4000);
        V_TO_SITE                   VARCHAR2(4000);
        V_ITEM_ID                   VARCHAR2(4000);
        V_NEW_BOD_ID                VARCHAR2(4000);
        V_NEW_ETD_DATE              VARCHAR2(4000);
        V_NEW_ETA_DATE              VARCHAR2(4000);
        V_NEW_ROUTE_ID              VARCHAR2(4000);
        V_NEW_INCOTERMS             VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000);
        V_NEW_D_CONTRY              VARCHAR2(4000);
        V_NEW_D_PORT_CODE           VARCHAR2(4000);
        V_NEW_A_COUNTRY             VARCHAR2(4000);
        V_NEW_A_PORT_CODE           VARCHAR2(4000);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000);
        V_NEW_TO_COUNTRY            VARCHAR2(4000);
        V_NEW_TO_CITY               VARCHAR2(4000);
        V_EDIT_MAIN                 VARCHAR2(4000);
        V_EDIT_REMARK               VARCHAR2(4000);
        V_CREATE_DATE               DATE;
        V_CHK                       NUMBER := 0;
        V_TITLE                     VARCHAR2(4000);
        V_ELECTRODE_YN              VARCHAR2(4000);
        V_ELECTRODE_TYPE            VARCHAR2(4000);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000);
        V_REMARKS                   VARCHAR2(4000);
        V_REMARKS2                  VARCHAR2(4000);
        V_REMARKS3                  VARCHAR2(4000);
        V_CHANGE_REASON_CODE        VARCHAR2(4000);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000);
        V_DIVISION_ID_TEMP          VARCHAR2(4000);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000);
        V_FROM_SITE_TEMP            VARCHAR2(4000);
        V_TO_SITE_TEMP              VARCHAR2(4000);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150) := P_PROGRAM_ID || '-' || P_TITLE;
        V_LOG_TYPE                  VARCHAR2(30);                               /* START/END/ERROR/... */
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000);
        V_DESCRIPTION               VARCHAR2(500);
        D_EVENT_DATE                DATE;
        V_DELIMITER                 VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;
        V_ERR_MSG                   VARCHAR2(4000);
        V_ERR_CODE                  NUMBER;
    BEGIN

        V_CREATE_DATE := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 로그 저장이 확정을 동반하므로 되돌림 지점은 그 뒤에 잡는다 */
        SAVEPOINT SP_SAVE_DRAFT;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE := SCM_ARR_SPL_VAL(P_FROM_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID := SCM_ARR_SPL_VAL(P_NEW_BOD_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_TITLE := 'Change on ' || SCM_ARR_SPL_VAL(P_TITLE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY := SCM_ARR_SPL_VAL(P_NEW_TO_CITY, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN := SCM_ARR_SPL_VAL(P_EDIT_MAIN, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_REMARK := SCM_ARR_SPL_VAL(P_EDIT_REMARK, V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_YN := SCM_ARR_SPL_VAL(P_ELECTRODE_YN, V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_TYPE := SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGIN_FROM_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGIN_FROM_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGION_TO_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGION_TO_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS := SCM_ARR_SPL_VAL(P_REMARKS, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2 := SCM_ARR_SPL_VAL(P_REMARKS2, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3 := SCM_ARR_SPL_VAL(P_REMARKS3, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL, V_DELIMITER, V_MST_LOOP_CNT);

            IF V_CHANGE_REASON_CODE IS NULL THEN
                V_CHANGE_REASON_CODE := 'T07';
            END IF;

            IF V_CHANGE_REASON_DETAIL IS NULL THEN
                V_CHANGE_REASON_DETAIL := NULL;
            END IF;

            BEGIN
                SELECT TO_SITE
                     , ITEM_ID
                  INTO V_TO_SITE
                     , V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_TO_SITE := NULL;
                    V_ITEM_ID := NULL;
            END;

            /* 원문 TOP 1 + ORDER BY PRIORITY 는 첫 행만 받는다 */
            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID = V_DIVISION_ID
                                   AND A.FROM_SITE = V_FROM_SITE
                                   AND A.TO_SITE = V_TO_SITE
                                   AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND A.SSP_INCOTERMS = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID = V_ITEM_ID) XA
                         WHERE IA.DIVISION_ID = XA.DIVISION_ID
                           AND IA.BOD_ID = XA.BOD_ID
                           AND IA.DIVISION_ID = V_DIVISION_ID
                           AND IA.FROM_SITE = V_FROM_SITE
                           AND IA.TO_SITE = V_TO_SITE
                           AND IA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND IA.SSP_INCOTERMS = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;                                                       /* 원문도 대상이 없으면 앞 값을 그대로 둔다 */
            END;

            /* 기준정보(BOD) 필수값 검사 — 하나라도 비면 저장하지 않고 'X' 반환 */
            IF ((V_DIVISION_ID_TEMP IS NULL)
                OR (V_NEW_BOD_ID_TEMP IS NULL)
                OR (V_FROM_SITE_TEMP IS NULL)
                OR (V_TO_SITE_TEMP IS NULL)
                OR (V_NEW_INCOTERMS_TEMP IS NULL)
                OR (V_NEW_TRANSPORT_MODE_TEMP IS NULL)
                OR (V_NEW_ROUTE_ID_TEMP IS NULL)
                OR (V_NEW_D_CONTRY_TEMP IS NULL)
                OR (V_NEW_D_PORT_CODE_TEMP IS NULL)
                OR (V_NEW_A_COUNTRY_TEMP IS NULL)
                OR (V_NEW_A_PORT_CODE_TEMP IS NULL)
                OR (V_NEW_CUSTOMER_LT_TEMP IS NULL)
                OR (V_NEW_TO_COUNTRY_TEMP IS NULL)
                OR (V_NEW_TO_CITY_TEMP IS NULL)
               ) THEN

                /* 결과 커서를 RETURN 앞에서 연다 */
                OPEN O_RC1 FOR
                    SELECT 'X' AS RESULT_CODE
                         , NULL AS REQUEST_NO
                      FROM DUAL;

                OPEN O_RC2 FOR
                    SELECT NULL AS ERROR_MESSAGE
                      FROM DUAL
                     WHERE 1 = 2;

                V_LOG_TYPE := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                V_DESCRIPTION := '';
                D_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                RETURN;

            END IF;

            IF V_EDIT_MAIN = 'Y' THEN

                IF V_CHK = 0 THEN

                    SELECT 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6)
                      INTO V_MAX_REQ_NO
                      FROM DUAL;

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO
                      , CHANGE_TYPE
                      , CHANGE_REQ_STATUS
                      , DIVISION_ID
                      , FROM_SITE
                      , REQUEST_TITLE
                      , REQUEST_USER
                      , REQUEST_DEPT
                      , REQUEST_TIME
                      , APPROVAL_USER
                      , APPROVAL_DEPT
                      , APPROVAL_TIME
                      , CHANGE_REASON_CODE
                      , CHANGE_REASON_DETAIL
                      , REJECT_REASON
                      , VALID_YN
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO
                      , 'A'
                      , 'A'
                      , V_DIVISION_ID
                      , V_FROM_SITE
                      , V_TITLE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , V_CREATE_DATE
                      , V_CHANGE_REASON_CODE
                      , V_CHANGE_REASON_DETAIL
                      , NULL
                      , 'Y'
                      , P_USER_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , V_CREATE_DATE
                      , V_ELECTRODE_YN
                      , V_ELECTRODE_TYPE
                      , V_ORIGIN_FROM_DIVISION_ID
                      , V_ORIGION_TO_DIVISION_ID
                    );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                /* SET @v_new_eta_date = REPLACE(SUBSTRING(@v_new_eta_date,1,10),'-','') */
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF V_SHIPMENT_DATE IS NOT NULL AND LENGTH(V_SHIPMENT_DATE) = 8
                   AND V_NEW_CUSTOMER_LT IS NOT NULL AND LENGTH(V_NEW_CUSTOMER_LT) > 0 THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 — 원문은 묶음 파라미터를 그대로 넘긴다 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                (
                    CHANGE_REQ_NO
                  , CONFIRM_ID
                  , NEW_YN
                  , DIVISION_ID
                  , ITEM_ID
                  , FROM_SITE
                  , TO_SITE
                  , YYYYMMDD
                  , QTY
                  , BOD_ID
                  , ROUTE_ID
                  , BIZ_TYPE
                  , PROJECT_CODE
                  , FCST_TYPE
                  , FCST_ETD_DATE
                  , FCST_ETA_DATE
                  , ETD_DATE
                  , ETA_DATE
                  , INCOTERMS
                  , TRANSPORT_MODE
                  , D_COUNTRY
                  , D_PORT_CODE
                  , A_COUNTRY
                  , A_PORT_CODE
                  , CUSTOMER_LT
                  , TO_COUNTRY
                  , TO_CITY
                  , NEW_YYYYMMDD
                  , NEW_QTY
                  , NEW_BOD_ID
                  , NEW_ROUTE_ID
                  , NEW_ETD_DATE
                  , NEW_ETA_DATE
                  , NEW_INCOTERMS
                  , NEW_TRANSPORT_MODE
                  , NEW_D_COUNTRY
                  , NEW_D_PORT_CODE
                  , NEW_A_COUNTRY
                  , NEW_A_PORT_CODE
                  , NEW_CUSTOMER_LT
                  , NEW_TO_COUNTRY
                  , NEW_TO_CITY
                  , FROM_SITE_TYPE
                  , FROM_SITE_PLANT_ID
                  , FROM_SITE_VENDOR_ID
                  , FROM_SITE_SOLDTO_CODE
                  , FROM_SITE_SHIPTO_CODE
                  , FROM_SITE_COMPANY_ID
                  , TO_SITE_TYPE
                  , TO_SITE_PLANT_ID
                  , TO_SITE_VENDOR_ID
                  , TO_SITE_SOLDTO_CODE
                  , TO_SITE_SHIPTO_CODE
                  , TO_SITE_COMPANY_ID
                  , ERP_SO_NO
                  , ERP_SO_ITEM_NO
                  , ERP_DO_NO
                  , ERP_STATUS
                  , VALID_YN
                  , ATTRIBUTE1
                  , ATTRIBUTE2
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                  , ELECTRODE_YN
                  , ELECTRODE_TYPE
                  , ORIGIN_FROM_DIVISION_ID
                  , ORIGIN_TO_DIVISION_ID
                  , REMARKS
                  , REMARKS2
                  , REMARKS3
                  , REQUESTOR
                )
                SELECT V_MAX_REQ_NO                                             AS CHANGE_REQ_NO
                     , CONFIRM_ID
                     , 'N'                                                      AS NEW_YN
                     , DIVISION_ID
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , V_SHIPMENT_DATE                                          AS NEW_YYYYMMDD
                     , TO_NUMBER(V_SHIPMENT_QTY)                                AS NEW_QTY
                     , V_NEW_BOD_ID_TEMP                                        AS NEW_BOD_ID
                     , TO_NUMBER(V_NEW_ROUTE_ID_TEMP)                           AS NEW_ROUTE_ID
                     , V_NEW_ETD_DATE                                           AS NEW_ETD_DATE
                     , V_NEW_ETA_DATE                                           AS NEW_ETA_DATE
                     , V_NEW_INCOTERMS_TEMP                                     AS NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE_TEMP                                AS NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY_TEMP                                      AS NEW_D_COUNTRY
                     , V_NEW_D_PORT_CODE_TEMP                                   AS NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY_TEMP                                     AS NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE_TEMP                                   AS NEW_A_PORT_CODE
                     , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)                        AS NEW_CUSTOMER_LT
                     , V_NEW_TO_COUNTRY_TEMP                                    AS NEW_TO_COUNTRY
                     , V_NEW_TO_CITY                                            AS NEW_TO_CITY   /* 원문도 기준정보 값이 아니라 화면 입력값을 넣는다 */
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , ERP_SO_NO
                     , ERP_SO_ITEM_NO
                     , ERP_DO_NO
                     , ERP_STATUS
                     , 'Y'
                     , 'N'
                     , 'A'
                     , P_USER_ID                                                AS CREATED_BY
                     , V_CREATE_DATE
                     , P_USER_ID                                                AS LAST_UPDATED_BY
                     , V_CREATE_DATE                                            /* [dbo].[FN_MULTY_TIME](@p_time_zone) LAST_UPDATE_DATE */
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , REQUESTOR
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;                                                             /* @v_edit_main = 'Y'	End */

        END LOOP;                                                               /* While					End */

        /* ERP전송 Table(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN) Insert */
        /* 출하확정변경시 ERP 전송 이터 테이블 저장 C: 변경요청 */
        PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH('C', V_MAX_REQ_NO);

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_REQ_NO AS REQUEST_NO
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            BEGIN
                ROLLBACK TO SP_SAVE_DRAFT;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;                                                       /* 되돌림 지점을 잡기 전에 난 오류 */
            END;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS REQUEST_NO
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0021_SAVE_SHIPMENT_REQUEST_DRAFTING;

    PROCEDURE P_SSP0021_SAVE_SHIPMENT_REQUEST_CONFIRM
    (
        P_ACTIVE_FLAG               IN  VARCHAR2
       ,P_DIVISION_ID               IN  VARCHAR2
       ,P_CONFIRM_ID                IN  VARCHAR2
       ,P_SHIPMENT_QTY              IN  VARCHAR2
       ,P_SHIPMENT_DATE             IN  VARCHAR2
       ,P_NEW_BOD_ID                IN  VARCHAR2
       ,P_NEW_ROUTE_ID              IN  VARCHAR2
       ,P_NEW_ETD_DATE              IN  VARCHAR2
       ,P_NEW_ETA_DATE              IN  VARCHAR2
       ,P_NEW_INCOTERMS             IN  VARCHAR2
       ,P_NEW_TRANSPORT_MODE        IN  VARCHAR2
       ,P_NEW_D_CONTRY              IN  VARCHAR2
       ,P_NEW_D_PORT_CODE           IN  VARCHAR2
       ,P_NEW_A_COUNTRY             IN  VARCHAR2
       ,P_NEW_A_PORT_CODE           IN  VARCHAR2
       ,P_NEW_CUSTOMER_LT           IN  VARCHAR2
       ,P_NEW_TO_COUNTRY            IN  VARCHAR2
       ,P_NEW_TO_CITY               IN  VARCHAR2
       ,P_REMARKS                   IN  VARCHAR2
       ,P_REMARKS2                  IN  VARCHAR2
       ,P_REMARKS3                  IN  VARCHAR2
       ,P_USER_ID                   IN  VARCHAR2
       ,P_CHECK_NEED_YN             IN  VARCHAR2
       ,P_EDIT_MAIN                 IN  VARCHAR2
       ,O_RC1                       OUT SYS_REFCURSOR
       ,O_RC2                       OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0021_SAVE_SHIPMENT_REQUEST_CONFIRM
 * Description  : Shipment Request Confirm 저장
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2018/11/16   hwyoon         변경등록 후 메일 전송
 * 2019/03/14   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REMARKS2 컬럼 추가
 * 2019/04/30   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REQUESTOR 컬럼 제거
 * 2019/05/07   AYJ            [PJ20189106] 전지.GSCM 고도화 이행  REMARKS3 컬럼 추가
 * 2019/05/30   mcTheJ         [PJ20189106] 전지.GSCM 고도화 이행  CHANGE_REASON 추가로 인한 메일 SEND 수정
 * 2019/10/02   ayj            PLAN TB 미사용으로 인한 주석
 * 2019/10/29   ayj            FCST_ETA_DATE, ETA_DATE 저장 값 수정(출발일 기준 항차를 고려한 ETA_DATE 계산)
 * 2019/11/26   KIMYONGHO      메일 전송 변경 JOB.SCM_SSP_ADJUST_MAIL_SEND_BATCH -> PR_SSP_MAIL_SEND_ADJUST_MST
 * 2020/06/23   khj79          ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정
 * 2021/01/07   KIMYONGHO      [C20201223-000448] MKT FCST - SSP Sync
 * 2021/01/12   KIMYONGHO      [C20201223-000448] MKT FCST - SSP Sync 운영이관 검증 단계에서 처리 지연 현상으로 END LOG 이후 호출로 조정함.
 * 2021/01/12   KIMYONGHO      SCS I/F 추가
 * 2021/09/02   KIMYONGHO      SCP_MST_BOD_v -> SCP_MST_BOD_N_V 변경
 * 2021/10/18   KIMYONGHO      [C20211001-000241][SCM PI팀] Shipment Plan (Auto ESS) 기능 개선 의건
 * 2024/02/23   jilee          폴란드 WA 법인 변경건 전체 내역 송부
 * 2024/06/10   jilee          Plan 하단 신규 건 Change Req 정보 입력
 * 2024/10/01   KHJ            NERP_SSP
 * 2025/08/18   chkim.68       [E20250821-001308] -- to_company_id를 from_site에 따라 to_company_id가 다르게 적용되는 예외를 적용 (scm_site_company_exception)
                                FN_GET_SSP_SITE_INFO -> [FN_GET_SSP_SITE_INFO_EXCEPTION]
                                   SSP_SITE_INFO를 이용하여 scm_site_company를 획득하도록 공통화
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_ACTIVE_FLAG               VARCHAR2(4000);
        V_DIVISION_ID               VARCHAR2(4000);
        V_CONFIRM_ID                VARCHAR2(4000);
        V_SHIPMENT_QTY              VARCHAR2(4000);
        V_SHIPMENT_DATE             VARCHAR2(4000);
        V_NEW_BOD_ID                VARCHAR2(4000);
        V_NEW_ETD_DATE              VARCHAR2(4000);
        V_NEW_ETA_DATE              VARCHAR2(4000);
        V_NEW_ROUTE_ID              VARCHAR2(4000);
        V_NEW_INCOTERMS             VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000);
        V_NEW_D_CONTRY              VARCHAR2(4000);
        V_NEW_D_PORT_CODE           VARCHAR2(4000);
        V_NEW_A_COUNTRY             VARCHAR2(4000);
        V_NEW_A_PORT_CODE           VARCHAR2(4000);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000);
        V_NEW_TO_COUNTRY            VARCHAR2(4000);
        V_NEW_TO_CITY               VARCHAR2(4000);
        V_CREATE_DATE               DATE;
        V_BEFORE_QTY                NUMBER;
        V_QTY                       NUMBER;
        V_REMARKS                   VARCHAR2(4000);
        V_REMARKS2                  VARCHAR2(4000);
        V_REMARKS3                  VARCHAR2(4000);
        V_CHECK_NEED_YN             VARCHAR2(4000);
        V_PLAN_START_YYYYMMDD       VARCHAR2(4000);
        V_SEQ                       VARCHAR2(4000);
        V_EDIT_MAIN                 VARCHAR2(4000);
        V_CHANGE_REQ_NO             VARCHAR2(4000);
        V_DIVISION_ID_TEMP          VARCHAR2(4000);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000);
        V_FROM_SITE_TEMP            VARCHAR2(4000);
        V_TO_SITE_TEMP              VARCHAR2(4000);
        V_ITEM_ID_TEMP              VARCHAR2(4000);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000);
        V_NEW_CONFIRM_ID            VARCHAR2(4000);
        V_INFSEQNO                  VARCHAR2(14);
        V_LAST_CONFIRM_DATE         VARCHAR2(8);
        V_CHK_REQ                   NUMBER := 0;
        V_MAX_REQ_NO                VARCHAR2(40);
        V_USER_DEPT_ID              VARCHAR2(50);
        V_ELECTRODE_YN              VARCHAR2(4000);
        V_ELECTRODE_TYPE            VARCHAR2(4000);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000);
        V_GRP_CHANGE_REQ            VARCHAR2(20);
        V_MAIL_FLAG                 NUMBER := 0;
        V_MAIL_CHK                  NUMBER := 0;
        V_TMP_FN_TIME_ZONE          VARCHAR2(8);
        V_TMP_SEQ_CONFIRM           VARCHAR2(20);
        V_WA_COMPANY_ID             VARCHAR2(100);
        V_CFM_COMPANY_ID            VARCHAR2(100);
        V_DELIMITER                 VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150) := 'PKG_SSP0021.P_SSP0021_SAVE_SHIPMENT_REQUEST_CONFIRM';
        V_LOG_TYPE                  VARCHAR2(30);                               /* START/END/ERROR/... */
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000);
        V_DESCRIPTION               VARCHAR2(500);
        D_EVENT_DATE                DATE;
        V_ERR_MSG                   VARCHAR2(4000);
        V_ERR_CODE                  NUMBER;
    BEGIN

        V_CREATE_DATE := SYSDATE;
        V_GRP_CHANGE_REQ := 'G' || TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF3');

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 로그 프로시저가 자체 COMMIT 을 하므로 되돌림 지점은 그 뒤에 잡는다 */
        SAVEPOINT SP_SAVE_CONFIRM;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID := SCM_ARR_SPL_VAL(P_NEW_BOD_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY := SCM_ARR_SPL_VAL(P_NEW_TO_CITY, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS := SCM_ARR_SPL_VAL(P_REMARKS, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2 := SCM_ARR_SPL_VAL(P_REMARKS2, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3 := SCM_ARR_SPL_VAL(P_REMARKS3, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHECK_NEED_YN := SCM_ARR_SPL_VAL(P_CHECK_NEED_YN, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN := SCM_ARR_SPL_VAL(P_EDIT_MAIN, V_DELIMITER, V_MST_LOOP_CNT);

            BEGIN
                SELECT FROM_SITE
                     , TO_SITE
                     , ITEM_ID
                  INTO V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_ITEM_ID_TEMP
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;                                                       /* 원문도 대상이 없으면 앞 값을 그대로 둔다 */
            END;

            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID = V_DIVISION_ID
                                   AND A.FROM_SITE = V_FROM_SITE_TEMP
                                   AND A.TO_SITE = V_TO_SITE_TEMP
                                   AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND A.SSP_INCOTERMS = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID = V_ITEM_ID_TEMP) XA
                         WHERE IA.DIVISION_ID = XA.DIVISION_ID
                           AND IA.BOD_ID = XA.BOD_ID
                           AND IA.DIVISION_ID = V_DIVISION_ID
                           AND IA.FROM_SITE = V_FROM_SITE_TEMP
                           AND IA.TO_SITE = V_TO_SITE_TEMP
                           AND IA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND IA.SSP_INCOTERMS = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;                                                       /* 원문도 대상이 없으면 앞 값을 그대로 둔다 */
            END;

            /* 기준정보(BOD) 필수값 검사 — 하나라도 비면 저장하지 않고 'X' 반환 */
            IF ((V_DIVISION_ID_TEMP IS NULL)
                OR (V_NEW_BOD_ID_TEMP IS NULL)
                OR (V_FROM_SITE_TEMP IS NULL)
                OR (V_TO_SITE_TEMP IS NULL)
                OR (V_NEW_INCOTERMS_TEMP IS NULL)
                OR (V_NEW_TRANSPORT_MODE_TEMP IS NULL)
                OR (V_NEW_ROUTE_ID_TEMP IS NULL)
                OR (V_NEW_D_CONTRY_TEMP IS NULL)
                OR (V_NEW_D_PORT_CODE_TEMP IS NULL)
                OR (V_NEW_A_COUNTRY_TEMP IS NULL)
                OR (V_NEW_A_PORT_CODE_TEMP IS NULL)
                OR (V_NEW_CUSTOMER_LT_TEMP IS NULL)
                OR (V_NEW_TO_COUNTRY_TEMP IS NULL)
                OR (V_NEW_TO_CITY_TEMP IS NULL)
               ) THEN

                /* 결과 커서를 RETURN 앞에서 연다 */
                OPEN O_RC1 FOR
                    SELECT 'X' AS RESULT_CODE
                         , NULL AS RESULT_CNT
                         , NULL AS CHANGE_REQ_NO
                      FROM DUAL;

                OPEN O_RC2 FOR
                    SELECT NULL AS ERR_MESSAGE
                      FROM DUAL
                     WHERE 1 = 2;

                V_LOG_TYPE := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                V_DESCRIPTION := '';
                D_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                RETURN;

            END IF;

            /*--//기존 확정 건 수정//--*/
            IF V_ACTIVE_FLAG <> 'I' THEN

                V_QTY := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT QTY
                         , BEFORE_QTY
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                IF V_QTY <> TO_NUMBER(V_SHIPMENT_QTY) THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                IF V_EDIT_MAIN = 'Y' THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* 2020.06.23 ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정 */
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET YYYYMMDD = V_SHIPMENT_DATE
                     , QTY = TO_NUMBER(V_SHIPMENT_QTY)
                     , BEFORE_QTY = V_BEFORE_QTY
                     , BOD_ID = V_NEW_BOD_ID_TEMP
                     , ROUTE_ID = V_NEW_ROUTE_ID_TEMP
                     , INCOTERMS = V_NEW_INCOTERMS_TEMP
                     , D_COUNTRY = V_NEW_D_CONTRY_TEMP
                     , D_PORT_CODE = V_NEW_D_PORT_CODE_TEMP
                     , A_COUNTRY = V_NEW_A_COUNTRY_TEMP
                     , A_PORT_CODE = V_NEW_A_PORT_CODE_TEMP
                     , TO_COUNTRY = V_NEW_TO_COUNTRY_TEMP
                     , TO_CITY = V_NEW_TO_CITY_TEMP
                     , TRANSPORT_MODE = V_NEW_TRANSPORT_MODE_TEMP
                     , ETD_DATE = V_SHIPMENT_DATE                               /* V_NEW_ETD_DATE */
                     , ETA_DATE = V_NEW_ETA_DATE
                     , FCST_ETD_DATE = V_SHIPMENT_DATE                          /* V_NEW_ETD_DATE */
                     , FCST_ETA_DATE = V_NEW_ETA_DATE
                     , CUSTOMER_LT = TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , REMARKS = V_REMARKS
                     , REMARKS2 = V_REMARKS2
                     , REMARKS3 = V_REMARKS3
                     , CHECK_NEED_YN = V_CHECK_NEED_YN
                     , LAST_UPDATED_BY = P_USER_ID
                     , LAST_UPDATE_DATE = V_CREATE_DATE
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

                IF V_EDIT_MAIN = 'Y' THEN

                    BEGIN
                        SELECT CHANGE_REQ_NO
                          INTO V_CHANGE_REQ_NO
                          FROM (SELECT A.CHANGE_REQ_NO
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE A
                                 WHERE A.CONFIRM_ID = V_CONFIRM_ID
                                   AND A.VALID_YN = 'Y'
                                 ORDER BY A.LAST_UPDATE_DATE DESC)
                         WHERE ROWNUM = 1;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;

                END IF;

                IF LENGTH(RTRIM(V_CHANGE_REQ_NO)) > 0 THEN

                    PR_SSP_ANL_SHIP_CONFIRM_HIST(V_CHANGE_REQ_NO, P_USER_ID, '');

                    IF V_DIVISION_ID = '82' THEN
                        PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_SCS('B', V_CHANGE_REQ_NO);
                    END IF;

                    SELECT COUNT(*)
                      INTO V_MAIL_CHK
                      FROM SSP_MST_SEND_MAIL_REQ
                     WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO;

                    IF V_MAIL_CHK = 0 THEN

                        INSERT INTO SSP_MST_SEND_MAIL_REQ
                        (
                            CHANGE_REQ_NO
                          , TRANSFER_FLAG
                          , GRP_CHANGE_REQ
                        )
                        VALUES
                        (
                            V_CHANGE_REQ_NO
                          , 'N'
                          , V_GRP_CHANGE_REQ
                        );

                        V_MAIL_FLAG := 1;

                    END IF;

                END IF;

            END IF;

            IF V_MAIL_FLAG = 1 THEN
                PR_SSP_MAIL_SEND_ADJUST_MST(V_GRP_CHANGE_REQ);
            END IF;

            /* 2020-07-24 KIMYONGHO 신규생성 기능 추가 */
            IF V_ACTIVE_FLAG = 'I' THEN

                SELECT TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_XIF_ERP_IFSEQNO.NEXTVAL), -6)
                  INTO V_INFSEQNO
                  FROM DUAL;

                V_LAST_CONFIRM_DATE := TO_CHAR(SYSDATE + 9, 'YYYYMMDD');

                V_DESCRIPTION := '';
                D_EVENT_DATE := SYSDATE;                                        /* FN_MULTY_TIME(P_TIME_ZONE) */
                PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                V_TMP_FN_TIME_ZONE := TO_CHAR(FN_MULTY_TIME(NULL), 'YYYYMMDD');
                V_TMP_SEQ_CONFIRM := TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL);
                V_NEW_CONFIRM_ID := 'C' || V_TMP_FN_TIME_ZONE || SUBSTR('000000' || V_TMP_SEQ_CONFIRM, -6);

                SELECT MAX(PLAN_START_YYYYMMDD)
                     , MAX(PLAN_SEQ)
                  INTO V_PLAN_START_YYYYMMDD
                     , V_SEQ
                  FROM SSP_PLAN_VERSION_V
                 WHERE PLAN_TYPE = 'SP'
                   AND DIVISION_ID = V_DIVISION_ID
                   AND CONFIRM_FLAG = 'Y'
                   AND PLAN_START_YYYYMMDD = (SELECT MAX(SA.PLAN_START_YYYYMMDD)
                                                FROM SSP_PLAN_VERSION_V SA
                                               WHERE SA.DIVISION_ID = V_DIVISION_ID
                                                 AND SA.PLAN_TYPE = 'SP'
                                                 AND SA.CONFIRM_FLAG = 'Y');

                IF V_PLAN_START_YYYYMMDD IS NULL THEN
                    V_PLAN_START_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');
                    V_SEQ := 1;
                END IF;

                V_QTY := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT QTY
                         , BEFORE_QTY
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                IF V_QTY <> TO_NUMBER(V_SHIPMENT_QTY) * 1 THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                IF V_EDIT_MAIN = 'Y' THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                INSERT INTO SSP_ANL_SHIP_CONFIRM
                (
                    CONFIRM_ID
                  , SHIPMENT_STATUS
                  , DIVISION_ID
                  , PLAN_START_YYYYMMDD
                  , PLAN_TYPE
                  , SEQ
