                  , ATTRIBUTE7
                  , ATTRIBUTE8
                  , ATTRIBUTE9
                  , ATTRIBUTE10
                  /*----------------------------------------------------------------------------------------
                      2020.06.30 : KBK
                      I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                  ------------------------------------------------------------------------------------------*/
                  , PACKAGE_TYPE
                  , FACTORY_ID
                  , PACKAGE_QTY
                  , DOM_EXP
                  , ERP_ATTR1
                  , ERP_ATTR2
                  , ERP_ATTR3
                  , ERP_ATTR4
                  , ERP_ATTR5
                )
                SELECT IA.IFSEQNO
                     , IA.CONFIRM_ID
                     , IA.SHIPMENT_STATUS
                     , IA.LAST_CONFIRM_DATE
                     , IA.VERSION_TYPE
                     , NVL(C.NEW_VALUE1, IA.SALES_COMPANY_ID) AS SALES_COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.ITEM_ID
                     , NVL(D.NEW_VALUE1, IA.FROM_SITE) AS FROM_SITE
                     , NVL(E.NEW_VALUE1, IA.TO_SITE) AS TO_SITE
                     , IA.YYYYMMDD
                     , IA.QTY
                     , IA.BOD_ID
                     , IA.ROUTE_ID
                     , IA.OPERATION_GROUP
                     , IA.BIZ_TYPE
                     , IA.PROJECT_CODE
                     , IA.FCST_TYPE
                     , IA.FCST_ETD_DATE
                     , IA.FCST_ETA_DATE
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.INCOTERMS
                     , IA.INCOTERMS2
                     , IA.TRANSPORT_MODE
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.CUSTOMER_LT
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                     , IA.FROM_SITE_TYPE
                     , NVL(F.NEW_VALUE1, IA.FROM_SITE_PLANT_ID) AS FROM_SITE_PLANT_ID
                     , NVL(G.NEW_VALUE1, IA.FROM_SITE_VENDOR_ID) AS FROM_SITE_VENDOR_ID
                     , NVL(H.NEW_VALUE1, IA.FROM_SITE_SOLDTO_CODE) AS FROM_SITE_SOLDTO_CODE
                     , NVL(I.NEW_VALUE1, IA.FROM_SITE_SHIPTO_CODE) AS FROM_SITE_SHIPTO_CODE
                     , NVL(J.NEW_VALUE1, IA.FROM_SITE_COMPANY_ID) AS FROM_SITE_COMPANY_ID
                     , IA.TO_SITE_TYPE
                     , NVL(K.NEW_VALUE1, IA.TO_SITE_PLANT_ID) AS TO_SITE_PLANT_ID
                     , NVL(L.NEW_VALUE1, IA.TO_SITE_VENDOR_ID) AS TO_SITE_VENDOR_ID
                     , NVL(M.NEW_VALUE1, IA.TO_SITE_SOLDTO_CODE) AS TO_SITE_SOLDTO_CODE
                     , NVL(N.NEW_VALUE1, IA.TO_SITE_SHIPTO_CODE) AS TO_SITE_SHIPTO_CODE
                     , NVL(O.NEW_VALUE1, IA.TO_SITE_COMPANY_ID) AS TO_SITE_COMPANY_ID
                     , IA.BUILDING
                     , IA.REMARK
                     , IA.CUSTOMER_REQ
                     , IA.CHANGE_CODE
                     , IA.CHANGE_CODE_NAME
                     , IA.REQUESTOR
                     , IA.TRANSFER_FLAG
                     , IA.TRANSFER_DATE
                     , IA.CREATED_BY
                     , IA.CREATION_DATE
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                     , IA.ATTRIBUTE1
                     , IA.ATTRIBUTE2
                     , IA.ATTRIBUTE3
                     , IA.ATTRIBUTE4
                     , IA.ATTRIBUTE5
                     , IA.ATTRIBUTE6
                     , IA.ATTRIBUTE7
                     , IA.ATTRIBUTE8
                     , IA.ATTRIBUTE9
                     , IA.ATTRIBUTE10
                     /*----------------------------------------------------------------------------------------
                         2020.06.30 : KBK
                         I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                     ------------------------------------------------------------------------------------------*/
                     , IA.PACKAGE_TYPE_CODE
                     , IA.FACTORY_ID
                     , IA.PACKAGE_QTY
                     , IA.DOM_EXP
                     , NULL AS ERP_ATTR1
                     , NULL AS ERP_ATTR2
                     , NULL AS ERP_ATTR3
                     , IA.TO_SITE_PLANT_ID AS ERP_ATTR4                         /* NERP에서 원본 정보 참고용 (2025-04-23) */
                     , NULL AS ERP_ATTR5
                  FROM (SELECT XA.IFSEQNO
                             , XA.CONFIRM_ID
                             , XA.SHIPMENT_STATUS
                             , XA.LAST_CONFIRM_DATE
                             , XA.VERSION_TYPE
                             , XA.SALES_COMPANY_ID
                             , XB.ATTRIBUTE3 AS DIVISION_ID
                             , XA.ITEM_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.YYYYMMDD
                             , XA.QTY
                             , XA.BOD_ID
                             , XA.ROUTE_ID
                             , XA.OPERATION_GROUP
                             , XA.BIZ_TYPE
                             , XA.PROJECT_CODE
                             , XA.FCST_TYPE
                             , XA.FCST_ETD_DATE
                             , XA.FCST_ETA_DATE
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.INCOTERMS
                             , XA.INCOTERMS2
                             , XA.TRANSPORT_MODE
                             , XA.D_COUNTRY
                             , XA.D_PORT_CODE
                             , XA.A_COUNTRY
                             , XA.A_PORT_CODE
                             , XA.CUSTOMER_LT
                             , XA.TO_COUNTRY
                             , XA.TO_CITY
                             , XA.FROM_SITE_TYPE
                             , XA.FROM_SITE_PLANT_ID
                             , XA.FROM_SITE_VENDOR_ID
                             , XA.FROM_SITE_SOLDTO_CODE
                             , XA.FROM_SITE_SHIPTO_CODE
                             , XA.FROM_SITE_COMPANY_ID
                             , XA.TO_SITE_TYPE
                             , XA.TO_SITE_PLANT_ID
                             , XA.TO_SITE_VENDOR_ID
                             , XA.TO_SITE_SOLDTO_CODE
                             , XA.TO_SITE_SHIPTO_CODE
                             , XA.TO_SITE_COMPANY_ID
                             , XA.BUILDING
                             , XA.REMARK
                             , XA.CUSTOMER_REQ
                             , XA.CHANGE_CODE
                             , XA.CHANGE_CODE_NAME
                             , XA.REQUESTOR
                             , XA.TRANSFER_FLAG
                             , XA.TRANSFER_DATE
                             , XA.CREATED_BY
                             , XA.CREATION_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.ATTRIBUTE1
                             , XA.ATTRIBUTE2
                             , XA.ATTRIBUTE3
                             , XA.ATTRIBUTE4
                             , XA.ATTRIBUTE5
                             , XA.ATTRIBUTE6
                             , XA.ATTRIBUTE7
                             , XA.ATTRIBUTE8
                             , XA.ATTRIBUTE9
                             , XA.ATTRIBUTE10
                             /*----------------------------------------------------------------------------------------
                                 2020.06.30 : KBK
                                 I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                             ------------------------------------------------------------------------------------------*/
                             , XC.PACKAGE_TYPE_CODE
                             , XC.FACTORY_ID
                             , CEIL(CASE WHEN XC.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(XA.QTY * NVL(XC.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(XC.BOX_PER_CUT, 1)
                                         WHEN XC.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(XA.QTY * NVL(XC.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(XC.STEELCRATE_PER_CUT, 1)
                                         WHEN XC.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(XA.QTY * NVL(XC.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(XC.STEELRACK_PER_CUT, 1)
                                    ELSE NVL(XA.QTY, 0) END) AS PACKAGE_QTY
                             , XC.DOM_EXP_TYPE AS DOM_EXP
                          FROM (SELECT V_INFSEQNO AS IFSEQNO                    /* IFSEQNO */
                                     , SA.CONFIRM_ID
                                     , 'A' AS SHIPMENT_STATUS                   /* I_PLGB  A: 확정 */
                                     , V_LAST_CONFIRM_DATE AS LAST_CONFIRM_DATE /* I_DATE  확정구간 마지막 일자 */
                                     , 'B' AS VERSION_TYPE                      /* B:NEW/A:OLD */
                                     , NVL(SC.ATTRIBUTE2, SB.ATTRIBUTE2) AS SALES_COMPANY_ID
                                     , CASE WHEN SA.DIVISION_ID = 'EE' THEN SA.ORIGIN_FROM_DIVISION_ID ELSE SA.DIVISION_ID END AS DIVISION_ID
                                     , SA.ITEM_ID AS ITEM_ID
                                     , SA.FROM_SITE
                                     , SA.TO_SITE
                                     , SA.YYYYMMDD
                                     , SA.QTY
                                     , SA.BOD_ID
                                     , SA.ROUTE_ID
                                     , SA.BIZ_TYPE AS OPERATION_GROUP
                                     , SA.BIZ_TYPE
                                     , CASE WHEN SA.PROJECT_CODE IS NULL OR SA.PROJECT_CODE = '-' THEN 'TBD' ELSE SA.PROJECT_CODE END AS PROJECT_CODE
                                     , SA.FCST_TYPE
                                     , SA.FCST_ETD_DATE
                                     , SA.FCST_ETA_DATE
                                     , SA.ETD_DATE
                                     , SA.ETA_DATE
                                     , SA.INCOTERMS AS INCOTERMS
                                     , NULL AS INCOTERMS2
                                     , SA.TRANSPORT_MODE
                                     , SA.D_COUNTRY
                                     , SA.D_PORT_CODE
                                     , SA.A_COUNTRY
                                     , SA.A_PORT_CODE
                                     , SA.CUSTOMER_LT
                                     , SA.TO_COUNTRY
                                     , SA.TO_CITY
                                     , SA.FROM_SITE_TYPE
                                     , SA.FROM_SITE_PLANT_ID
                                     , SA.FROM_SITE_VENDOR_ID
                                     , SA.FROM_SITE_SOLDTO_CODE
                                     , SA.FROM_SITE_SHIPTO_CODE
                                     , SA.FROM_SITE_COMPANY_ID
                                     , SA.TO_SITE_TYPE
                                     , SA.TO_SITE_PLANT_ID
                                     , SA.TO_SITE_VENDOR_ID
                                     , SA.TO_SITE_SOLDTO_CODE
                                     , SA.TO_SITE_SHIPTO_CODE
                                     , SA.TO_SITE_COMPANY_ID
                                     , NULL AS BUILDING
                                     , NULL AS REMARK
                                     , NULL AS CUSTOMER_REQ
                                     , NULL AS CHANGE_CODE
                                     , NULL AS CHANGE_CODE_NAME
                                     , SA.REQUESTOR AS REQUESTOR
                                     , 'N' AS TRANSFER_FLAG
                                     , SYSDATE AS TRANSFER_DATE
                                     , SA.LAST_UPDATED_BY AS CREATED_BY
                                     , SYSDATE AS CREATION_DATE
                                     , SA.LAST_UPDATED_BY AS LAST_UPDATED_BY
                                     , SYSDATE AS LAST_UPDATE_DATE
                                     , NULL AS ATTRIBUTE1
                                     , NULL AS ATTRIBUTE2
                                     , NULL AS ATTRIBUTE3
                                     , NULL AS ATTRIBUTE4
                                     , NULL AS ATTRIBUTE5
                                     , NULL AS ATTRIBUTE6
                                     , NULL AS ATTRIBUTE7
                                     , NULL AS ATTRIBUTE8
                                     , NULL AS ATTRIBUTE9
                                     , SA.ELECTRODE_YN AS ATTRIBUTE10
                                  FROM SSP_ANL_SHIP_CONFIRM SA
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL SB
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL SC
                                 WHERE SB.LOOKUP_TYPE(+) = 'CELL_SHIP_FROM_TO'
                                   AND SB.VALID_YN(+) = 'Y'
                                   AND SB.SEGMENT1(+) = SA.FROM_SITE_COMPANY_ID
                                   AND SB.SEGMENT3(+) = SA.FROM_SITE
                                   AND SB.SEGMENT4(+) = SA.TO_SITE_COMPANY_ID
                                   AND SB.SEGMENT5(+) = SA.TO_SITE
                                   AND SC.LOOKUP_TYPE(+) = 'ELECTRODE_SHIP_FROM_TO'
                                   AND SC.VALID_YN(+) = 'Y'
                                   AND SC.SEGMENT1(+) = SA.FROM_SITE_COMPANY_ID
                                   AND SC.SEGMENT3(+) = SA.FROM_SITE
                                   AND SC.SEGMENT4(+) = SA.TO_SITE_COMPANY_ID
                                   AND SC.ATTRIBUTE1(+) = SA.TO_SITE
                                   AND SA.CONFIRM_ID = V_NEW_CONFIRM_ID
                                   AND NVL(SA.QTY, 0) <> 0) XA                  /* 0은IF 제외 */
                             , SCM_MST_DIVISION XB
                             , SSP_MST_SITE_ITEM_EE_V XC
                         WHERE XA.DIVISION_ID = XB.DIVISION_ID
                           AND XA.DIVISION_ID = (CASE WHEN XA.BIZ_TYPE = 'E' THEN XC.DIVISION_ID(+) ELSE XC.ASSY_DIVISION_ID(+) END)
                           AND XA.FROM_SITE = (CASE WHEN XA.BIZ_TYPE = 'E' THEN XC.SCM_SITE_ID(+) ELSE XC.ASSY_SCM_SITE_ID(+) END)
                           AND XA.ITEM_ID = XC.ITEM_ID(+)) IA
                     , NERP_CONV_MASTER C
                     , NERP_CONV_MASTER D
                     , NERP_CONV_MASTER E
                     , NERP_CONV_MASTER F
                     , NERP_CONV_MASTER G
                     , NERP_CONV_MASTER H
                     , NERP_CONV_MASTER I
                     , NERP_CONV_MASTER J
                     , NERP_CONV_MASTER K
                     , NERP_CONV_MASTER L
                     , NERP_CONV_MASTER M
                     , NERP_CONV_MASTER N
                     , NERP_CONV_MASTER O
                 WHERE C.CODETYPE(+) = 'COMPANY_ID'
                   AND IA.SALES_COMPANY_ID = C.OLD_VALUE1(+)
                   AND D.CODETYPE(+) = 'SCP_SITE_ID'
                   AND IA.FROM_SITE = D.OLD_VALUE1(+)
                   AND E.CODETYPE(+) = 'SCP_SITE_ID'
                   AND IA.TO_SITE = E.OLD_VALUE1(+)
                   AND F.CODETYPE(+) = 'PLANT_ID'
                   AND IA.FROM_SITE_PLANT_ID = F.OLD_VALUE1(+)
                   AND G.CODETYPE(+) = 'VENDOR_ID'
                   AND IA.FROM_SITE_VENDOR_ID = G.OLD_VALUE1(+)
                   AND H.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.FROM_SITE_SOLDTO_CODE = H.OLD_VALUE1(+)
                   AND I.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.FROM_SITE_SHIPTO_CODE = I.OLD_VALUE1(+)
                   AND J.CODETYPE(+) = 'COMPANY_ID'
                   AND IA.FROM_SITE_COMPANY_ID = J.OLD_VALUE1(+)
                   AND K.CODETYPE(+) = 'PLANT_ID'
                   AND IA.TO_SITE_PLANT_ID = K.OLD_VALUE1(+)
                   AND L.CODETYPE(+) = 'VENDOR_ID'
                   AND IA.TO_SITE_VENDOR_ID = L.OLD_VALUE1(+)
                   AND M.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.TO_SITE_SOLDTO_CODE = M.OLD_VALUE1(+)
                   AND N.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.TO_SITE_SHIPTO_CODE = N.OLD_VALUE1(+)
                   AND O.CODETYPE(+) = 'COMPANY_ID'
                   AND IA.TO_SITE_COMPANY_ID = O.OLD_VALUE1(+);

                PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, V_NEW_CONFIRM_ID);

                IF V_CHK_REQ = 0 THEN

                    SELECT 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6)
                      INTO V_MAX_REQ_NO
                      FROM DUAL;

                    BEGIN
                        SELECT DEPT_ID
                          INTO V_USER_DEPT_ID
                          /* 2026.09.30 AJS 수정 (START) */
--                          FROM TB_FX_USER
--                         WHERE USERID = P_USER_ID;
                          FROM SCM_ADM_USER_M
                         WHERE USER_ID = P_USER_ID;
                          /* 2026.09.30 AJS 수정 (END) */
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;

                    BEGIN
                        SELECT ELECTRODE_YN
                             , ELECTRODE_TYPE
                             , ORIGIN_FROM_DIVISION_ID
                             , ORIGIN_TO_DIVISION_ID
                          INTO V_ELECTRODE_YN
                             , V_ELECTRODE_TYPE
                             , V_ORIGIN_FROM_DIVISION_ID
                             , V_ORIGION_TO_DIVISION_ID
                          FROM SSP_ANL_SHIP_CONFIRM
                         WHERE CONFIRM_ID = V_NEW_CONFIRM_ID;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            NULL;
                    END;

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO
                      , CHANGE_TYPE
                      , CHANGE_REQ_STATUS
                      , DIVISION_ID
                      , FROM_SITE
                      , REQUEST_TITLE
                      , REQUEST_USER
                      , REQUEST_DEPT
                      , REQUEST_TIME
                      , APPROVAL_USER
                      , APPROVAL_DEPT
                      , APPROVAL_TIME
                      , CHANGE_REASON_CODE
                      , CHANGE_REASON_DETAIL
                      , REJECT_REASON
                      , VALID_YN
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO
                      , 'A'
                      , 'A'
                      , V_DIVISION_ID
                      , V_FROM_SITE_TEMP
                      , NULL
                      , P_USER_ID
                      , V_USER_DEPT_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , V_USER_DEPT_ID
                      , V_CREATE_DATE
                      , NULL
                      , NULL
                      , NULL
                      , 'Y'
                      , P_USER_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , V_CREATE_DATE
                      , V_ELECTRODE_YN
                      , V_ELECTRODE_TYPE
                      , V_ORIGIN_FROM_DIVISION_ID
                      , V_ORIGION_TO_DIVISION_ID
                    );

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                    (
                        CHANGE_REQ_NO
                      , CONFIRM_ID
                      , NEW_YN
                      , DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , YYYYMMDD
                      , QTY
                      , BOD_ID
                      , ROUTE_ID
                      , BIZ_TYPE
                      , PROJECT_CODE
                      , FCST_TYPE
                      , FCST_ETD_DATE
                      , FCST_ETA_DATE
                      , ETD_DATE
                      , ETA_DATE
                      , INCOTERMS
                      , TRANSPORT_MODE
                      , D_COUNTRY
                      , D_PORT_CODE
                      , A_COUNTRY
                      , A_PORT_CODE
                      , CUSTOMER_LT
                      , TO_COUNTRY
                      , TO_CITY
                      , NEW_YYYYMMDD
                      , NEW_QTY
                      , NEW_BOD_ID
                      , NEW_ROUTE_ID
                      , NEW_ETD_DATE
                      , NEW_ETA_DATE
                      , NEW_INCOTERMS
                      , NEW_TRANSPORT_MODE
                      , NEW_D_COUNTRY
                      , NEW_D_PORT_CODE
                      , NEW_A_COUNTRY
                      , NEW_A_PORT_CODE
                      , NEW_CUSTOMER_LT
                      , NEW_TO_COUNTRY
                      , NEW_TO_CITY
                      , FROM_SITE_TYPE
                      , FROM_SITE_PLANT_ID
                      , FROM_SITE_VENDOR_ID
                      , FROM_SITE_SOLDTO_CODE
                      , FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID
                      , TO_SITE_TYPE
                      , TO_SITE_PLANT_ID
                      , TO_SITE_VENDOR_ID
                      , TO_SITE_SOLDTO_CODE
                      , TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID
                      , ERP_SO_NO
                      , ERP_SO_ITEM_NO
                      , ERP_DO_NO
                      , ERP_STATUS
                      , VALID_YN
                      , ATTRIBUTE1
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                      , REMARKS
                      , REMARKS2
                      , REMARKS3
                      , REQUESTOR
                      , ATTRIBUTE2
                    )
                    SELECT V_MAX_REQ_NO AS CHANGE_REQ_NO
                         , CONFIRM_ID
                         , 'Y' AS NEW_YN
                         , DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE
                         , YYYYMMDD
                         , QTY
                         , BOD_ID
                         , ROUTE_ID
                         , BIZ_TYPE
                         , PROJECT_CODE
                         , FCST_TYPE
                         , FCST_ETD_DATE
                         , FCST_ETA_DATE
                         , ETD_DATE
                         , ETA_DATE
                         , INCOTERMS
                         , TRANSPORT_MODE
                         , D_COUNTRY
                         , D_PORT_CODE
                         , A_COUNTRY
                         , A_PORT_CODE
                         , CUSTOMER_LT
                         , TO_COUNTRY
                         , TO_CITY
                         , V_SHIPMENT_DATE AS NEW_YYYYMMDD
                         , TO_NUMBER(V_SHIPMENT_QTY) AS NEW_QTY
                         , V_NEW_BOD_ID_TEMP AS NEW_BOD_ID
                         , V_NEW_ROUTE_ID_TEMP AS NEW_ROUTE_ID
                         , V_NEW_ETD_DATE AS NEW_ETD_DATE
                         , V_NEW_ETA_DATE AS NEW_ETA_DATE
                         , V_NEW_INCOTERMS AS NEW_INCOTERMS
                         , V_NEW_TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                         , V_NEW_D_CONTRY AS NEW_D_COUNTRY
                         , V_NEW_D_PORT_CODE_TEMP AS NEW_D_PORT_CODE
                         , V_NEW_A_COUNTRY_TEMP AS NEW_A_COUNTRY
                         , V_NEW_A_PORT_CODE_TEMP AS NEW_A_PORT_CODE
                         , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP) AS NEW_CUSTOMER_LT
                         , V_NEW_TO_COUNTRY_TEMP AS NEW_TO_COUNTRY
                         , V_NEW_TO_CITY_TEMP AS NEW_TO_CITY
                         , FROM_SITE_TYPE
                         , FROM_SITE_PLANT_ID
                         , FROM_SITE_VENDOR_ID
                         , FROM_SITE_SOLDTO_CODE
                         , FROM_SITE_SHIPTO_CODE
                         , FROM_SITE_COMPANY_ID
                         , TO_SITE_TYPE
                         , TO_SITE_PLANT_ID
                         , TO_SITE_VENDOR_ID
                         , TO_SITE_SOLDTO_CODE
                         , TO_SITE_SHIPTO_CODE
                         , TO_SITE_COMPANY_ID
                         , ERP_SO_NO
                         , ERP_SO_ITEM_NO
                         , ERP_DO_NO
                         , ERP_STATUS
                         , 'Y'
                         , 'N'
                         , P_USER_ID AS CREATED_BY
                         , V_CREATE_DATE
                         , P_USER_ID AS LAST_UPDATED_BY
                         , V_CREATE_DATE
                         , ELECTRODE_YN
                         , ELECTRODE_TYPE
                         , ORIGIN_FROM_DIVISION_ID
                         , ORIGIN_TO_DIVISION_ID
                         , V_REMARKS
                         , V_REMARKS2
                         , V_REMARKS3
                         , REQUESTOR
                         , 'A'
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_NEW_CONFIRM_ID;

                END IF;

            END IF;                                                             /* V_ACTIVE_FLAG = 'I' END */

        END LOOP;                                                               /* end of while loop */

        IF LENGTH(RTRIM(V_CONFIRM_ID)) > 0 THEN

            BEGIN
                SELECT SEGMENT1                                                 /* company id */
                  INTO V_WA_COMPANY_ID
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'SSP_PLN_FP_SHIP_TARGET_WA'
                   AND VALID_YN = 'Y';
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_WA_COMPANY_ID := NULL;
            END;

            BEGIN
                SELECT FROM_SITE_COMPANY_ID
                  INTO V_CFM_COMPANY_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_CFM_COMPANY_ID := NULL;
            END;

            IF V_WA_COMPANY_ID = V_CFM_COMPANY_ID THEN
                PR_SSP_PLN_FP_SHIP_TARGET_WA;
            END IF;

        END IF;

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_LOOP_CNT AS RESULT_CNT
                 , NVL(V_CHANGE_REQ_NO, '') AS CHANGE_REQ_NO
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

        PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, P_CONFIRM_ID);

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            BEGIN
                ROLLBACK TO SP_SAVE_CONFIRM;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;                                                       /* 되돌림 지점을 잡기 전에 난 오류 */
            END;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS RESULT_CNT
                     , NULL AS CHANGE_REQ_NO
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERR_MESSAGE
                  FROM DUAL;

    END P_SSP0021_SAVE_SHIPMENT_REQUEST_CONFIRM;

END PKG_SSP0021;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0021
-- ##### END PACKAGE BODY PKG_SSP0021

-- ##### START PACKAGE BODY PKG_SSP0023_CHK
CREATE OR REPLACE PACKAGE BODY PKG_SSP0023_CHK
IS
/*
 * Program ID   : PKG_SSP0023_CHK
 * Description  : SSP0023 Shipment Plan(Electrode) 화면 프로시저 패키지
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */

    PROCEDURE P_SSP0023_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
       ,P_END_YYYYMMDD          IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/****************************************************************************************************
* Program ID  : SSP0023_GET_SHEET_CALENDAR_3SPAN
* Description : SSP 칼렌더 생성위한 프로시저
* Usage       : exec SSP0023_GET_SHEET_CALENDAR_3SPAN
* Parameter   : @p_start_yyyymmdd='2017-12-25'
*               @p_end_yyyymmdd='20180130'
*--------------------------------------------------------------------------------------------------
* Date        In Charge    Description
*--------------------------------------------------------------------------------------------------
* 2020/05/20  khj79       [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선
* 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
****************************************************************************************************/
    BEGIN

        OPEN O_RC1 FOR
            SELECT 'Z_D_' || A.BASIS_YYYYMMDD AS COLUMN_NAME
                 , A.CALENDAR_DAY AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , A.DAYOFWEEK AS DAY_CODE
                 , 'Z_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
            UNION ALL
            SELECT 'Z_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS COLUMN_NAME
                 , A.WEEK_NAME AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'Z_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.ISO_WEEK
                    , A.WEEK_NAME
                    , A.MONTH_NAME
                    , A.BASIS_START_DATE
            UNION ALL
            SELECT 'Z_M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                 , A.MONTH_NAME AS COLUMN_LABEL_NAME
                 , A.MONTH_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'Z_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.MONTH_NAME
            UNION ALL
            SELECT 'X_D_' || A.BASIS_YYYYMMDD AS COLUMN_NAME
                 , A.CALENDAR_DAY AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , A.DAYOFWEEK AS DAY_CODE
                 , 'X_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
            UNION ALL
            SELECT 'X_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS COLUMN_NAME
                 , A.WEEK_NAME AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'X_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.ISO_WEEK
                    , A.WEEK_NAME
                    , A.MONTH_NAME
                    , A.BASIS_START_DATE
            UNION ALL
            SELECT 'X_M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                 , A.MONTH_NAME AS COLUMN_LABEL_NAME
                 , A.MONTH_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'X_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.MONTH_NAME
            UNION ALL
            SELECT 'Y_D_' || A.BASIS_YYYYMMDD AS COLUMN_NAME
                 , A.CALENDAR_DAY AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , A.DAYOFWEEK AS DAY_CODE
                 , 'Y_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
            UNION ALL
            SELECT 'Y_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS COLUMN_NAME
                 , A.WEEK_NAME AS COLUMN_LABEL_NAME
                 , A.WEEK_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'Y_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.ISO_WEEK
                    , A.WEEK_NAME
                    , A.MONTH_NAME
                    , A.BASIS_START_DATE
            UNION ALL
            SELECT 'Y_M_' || A.BASIS_YYYYMM AS COLUMN_NAME
                 , A.MONTH_NAME AS COLUMN_LABEL_NAME
                 , A.MONTH_NAME AS SMALL_CLASS_LABEL_NAME
                 , A.MONTH_NAME AS LARGE_CLASS_LABEL_NAME
                 , NULL AS DAY_CODE
                 , 'Y_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY A.BASIS_YYYYMM
                    , A.MONTH_NAME
             ORDER BY SORT_ORDER_NO;

    END P_SSP0023_GET_SHEET_CALENDAR_3SPAN;

    PROCEDURE P_SSP0023_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_CONFIRM_ID            IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
       ,O_RC3                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0023_GET_SHIPMENT_STATUS
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/05/20   kh79           [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선
  ex) EXEC SSP0023_GET_SHIPMENT_STATUS @p_division_id='40^40^40^40', @p_confirm_id='C20181001068349^C20181005074232^C20181001068367^C20181008076327'
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND SHIPMENT_STATUS <> 'C';

        OPEN O_RC2 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND QTY = 0;

        OPEN O_RC3 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND ERP_STATUS = 'C';

    END P_SSP0023_GET_SHIPMENT_STATUS;

    PROCEDURE P_SSP0023_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_ERP_SO_NO             IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0023_GET_ERP_SO_NO_CNT
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/05/20   kh79           [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선
 * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT COUNT(*) AS CNT
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID = P_DIVISION_ID
               AND ERP_SO_NO = P_ERP_SO_NO
               AND QTY <> 0;

    END P_SSP0023_GET_ERP_SO_NO_CNT;

    PROCEDURE P_SSP0023_DELETE_SHIPMENT_REQUEST_DRAFTING
    (
        P_CHANGE_REQUEST_NO     IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0023_DELETE_SHIPMENT_REQUEST_DRAFTING
 * Description  : Shipment Plan Change 작성중 삭제
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/05/20   kh79           [PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_LAST_UPDATE_DATE  DATE;
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150) := 'PKG_SSP0023_CHK.P_SSP0023_DELETE_SHIPMENT_REQUEST_DRAFTING';
        V_LOG_TYPE          VARCHAR2(30);                                       /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000);
        V_DESCRIPTION       VARCHAR2(500);
        D_EVENT_DATE        DATE;
        V_ERR_MSG           VARCHAR2(4000);
        V_ERR_CODE          NUMBER;
    BEGIN

        V_LAST_UPDATE_DATE := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := V_LAST_UPDATE_DATE;                                     /* [dbo].[FN_MULTY_TIME](@p_time_zone); */
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0023_DELETE_SHIPMENT_REQUEST_DRAFTING;

    PROCEDURE P_SSP0023_GET_SHIPMENT_PLAN
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_MODEL_ID              IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_NICK_NAME             IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_NON_CHK               IN  VARCHAR2
       ,P_MY_MODEL_CHK          IN  VARCHAR2
       ,P_DELEGATEE_CHK         IN  VARCHAR2
       ,P_PART_LEADER_CHK       IN  VARCHAR2
       ,P_TEAM_LEADER_CHK       IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_GET_SHIPMENT_PLAN
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode)
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-04-28   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선  최초 작성
 * 2024/05/10   hsbang          확정구간 조회 일수(CONFIRM_DAY)를 펑션 FN_GET_ANL_SHIP_FROZEN_DAY_CNT] 에서 가져오도록 반영
 * 2025/12/11   chkim.68        E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_FROM_YYYYMMDD         VARCHAR2(8);
        V_TO_YYYYMMDD           VARCHAR2(8);
        V_CNT_USR_MEASURE       NUMBER := 0;
        V_APP_TYPE              VARCHAR2(8) := 'SSP';
        V_FROZEN_YYYYMMDD       VARCHAR2(8);
        V_PLAN_END_YYYYMMDD     VARCHAR2(8);
        V_RESULT_START_YYYYMMDD VARCHAR2(8);
        V_RESULT_END_YYYYMMDD   VARCHAR2(8);
        V_QRY_SUM               CLOB;
        V_EXEC                  CLOB;
    BEGIN

        V_FROM_YYYYMMDD := P_FROM_YYYYMMDD;
        V_TO_YYYYMMDD := P_TO_YYYYMMDD;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID;

        /* Cutoff 용 이전 version */
        V_FROZEN_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* 계획 구간 Start End 일자 (plan_start_yyyymmdd-1 ~ 8주) */
        V_PLAN_END_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 56, 'YYYYMMDD');

        /* 실적구간 Start End 일자 (plan_start_yyyymmdd-1의 전주월요일  ~ 계획구간 start일자-1) */
        /* 원문은 여러 행이 나오면 마지막 값을 대입하므로 MAX 로 옮긴다(달력 한 주의 월요일은 1건) */
        SELECT MAX(A.BASIS_YYYYMMDD)
          INTO V_RESULT_START_YYYYMMDD
          FROM SCM_SYS_CALENDAR_M A
         WHERE A.ISO_YYYYWW = (SELECT MIN(ISO_YYYYWW)
                                 FROM SCM_SYS_CALENDAR_M
                                WHERE BASIS_YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 7, 'YYYYMMDD')
                                  AND BASIS_YYYYMMDD <= P_PLAN_START_YYYYMMDD)
           AND A.DAYOFWEEK = 'MON';

        V_RESULT_END_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /********************************************************************************
        * 임시테이블만들기
        ********************************************************************************/
        DELETE FROM GT_0023_TITLESET;
        DELETE FROM GT_0023_BOH_CUTOFF;
        DELETE FROM GT_0023_PLAN_ITEM;
        DELETE FROM GT_0023_ROWDATA;
        DELETE FROM GT_0023_SIM;
        DELETE FROM GT_0023_CONFIRM;
        DELETE FROM GT_0023_RESULT;
        DELETE FROM GT_0023_PIVOT;

        /* 사용자 MEASURE 설정 정보 */
        INSERT INTO GT_0023_TITLESET
        (
            COLUMN_NAME
        )
        SELECT COLUMN_NAME
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID;

        /* CUTOFF DATA */
        INSERT INTO GT_0023_BOH_CUTOFF
        (
            COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , SCM_SITE_ID
          , MODEL_ID
          , ITEM_ID
          , TOT_BOH_QTY
          , JR_BOH_QTY
          , PC_BOH_QTY
          , TOT_BOH_QTY_PCM
          , JR_BOH_QTY_PCM
          , PC_BOH_QTY_PCM
          , TOT_BOH_QTY_CELL
          , JR_BOH_QTY_CELL
          , PC_BOH_QTY_CELL
          , CUTOFF_DATE
        )
        SELECT A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , A.SCM_SITE_ID
             , A.MODEL_ID
             , A.ITEM_ID
             , NVL(A.TOT_BOH_QTY, 0) AS TOT_BOH_QTY
             , NVL(A.JR_BOH_QTY, 0) AS JR_BOH_QTY
             , NVL(A.PC_BOH_QTY, 0) AS PC_BOH_QTY
             , NVL(A.TOT_BOH_QTY_TO_PCM, 0) AS TOT_BOH_QTY_PCM
             , NVL(A.JR_BOH_QTY_TO_PCM, 0) AS JR_BOH_QTY_PCM
             , NVL(A.PC_BOH_QTY_TO_PCM, 0) AS PC_BOH_QTY_PCM
             , NVL(A.TOT_BOH_QTY_TO_CELL, 0) AS TOT_BOH_QTY_CELL
             , NVL(A.JR_BOH_QTY_TO_CELL, 0) AS JR_BOH_QTY_CELL
             , NVL(A.PC_BOH_QTY_TO_CELL, 0) AS PC_BOH_QTY_CELL
             , A.CUTOFF_DATE
          FROM SSP_ANL_BOH_CUTOFF_EE A
         WHERE A.MEASURE_TYPE = 'P'
           AND A.CUTOFF_DATE = P_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.COMPANY_ID = P_COMPANY_ID
           AND (TRIM(P_ITEM_ID) IS NULL
            OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                               FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
           AND (TRIM(P_MODEL_ID) IS NULL
            OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))));

        /* 조회 기준 데이터 */
        INSERT INTO GT_0023_PLAN_ITEM
        (
            COMPANY_ID
          , DIVISION_ID
          , PLANT_ID
          , SCM_SITE_ID
          , MODEL_ID
          , ITEM_ID
        )
        SELECT DISTINCT A.COMPANY_ID
             , A.DIVISION_ID
             , A.PLANT_ID
             , A.SCM_SITE_ID
             , A.MODEL_ID
             , A.ITEM_ID
          FROM SSP_ANL_SHIP_PLAN_EE A
             , SSP_MST_MODEL_USER B
         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
           AND B.FROM_SITE(+) = A.SCM_SITE_ID
           AND B.ITEM_ID(+) = A.ITEM_ID
           AND B.VALID_YN(+) = 'Y'
           AND A.MEASURE_TYPE = 'P'
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.COMPANY_ID = P_COMPANY_ID
           AND (P_NON_CHK = 'Y'
            OR B.USER_ID IN (SELECT CASE WHEN P_MY_MODEL_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                               FROM DUAL
                             UNION
                             SELECT CASE WHEN P_DELEGATEE_CHK = 'Y' THEN SA.USER_ID ELSE 'X' END
                               FROM SSP_MST_DELEGATE SA
                              WHERE SA.VALID_YN = 'Y'
                                AND SA.DELEGATEE_ID = P_USER_ID
                              GROUP BY SA.USER_ID)
            OR B.PART_LEADER = CASE WHEN P_PART_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
            OR B.TEAM_LEADER = CASE WHEN P_TEAM_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END);

        IF P_REAL_FLAG = 'Y' THEN                                               /* 현재 기준 조회 */

            /*--////////////////////////////////////////////////////////////////////////////////--*/
            /*--//2. DATA ROW DATA															//--*/
            /*--////////////////////////////////////////////////////////////////////////////////--*/
            INSERT INTO GT_0023_ROWDATA
            (
                DIVISION_ID
              , PLANT_ID
              , COMPANY_ID
              , SCM_SITE_ID
              , ELECTRODE_POST_OPER_LT
              , ELECTRODE_TYPE
              , MODEL_ID
              , ITEM_ID
              , FROM_SITE
              , BOD_ID
              , MEASURE
              , YYYYMMDD
              , SEQ
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
              , LAST_UPDATED_BY
              , LAST_UPDATE_DATE
            )
            SELECT XA.DIVISION_ID
                 , XA.PLANT_ID
                 , XA.COMPANY_ID
                 , XA.SCM_SITE_ID
                 , XA.ELECTRODE_POST_OPER_LT
                 , XA.ELECTRODE_TYPE
                 , XA.MODEL_ID
                 , XA.ITEM_ID
                 , XA.FROM_SITE
                 , XA.BOD_ID
                 , XA.MEASURE
                 , XA.YYYYMMDD
                 , XA.SEQ
                 , SUM(CAST(XA.QTY AS NUMBER(30, 3))) AS QTY                    /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                 , SUM(XA.QTY_TO_PCM) AS QTY_TO_PCM
                 , SUM(XA.QTY_TO_CELL) AS QTY_TO_CELL
                 , XA.LAST_UPDATED_BY
                 , XA.LAST_UPDATE_DATE
              FROM (/* P_SHIP_REQ_ETD Measure 추가 */
                    SELECT A.DIVISION_ID AS DIVISION_ID
                         , A.PLANT_ID AS PLANT_ID
                         , A.COMPANY_ID AS COMPANY_ID
                         , A.SCM_SITE_ID AS SCM_SITE_ID
                         , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                         , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                         , A.MODEL_ID AS MODEL_ID
                         , B.ITEM_ID AS ITEM_ID
                         , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                         , NVL(B.BOD_ID, '-') AS BOD_ID
                         , 'P_SHIP_REQ_ETD' AS MEASURE
                         , B.ETD_DATE AS YYYYMMDD
                         , 3 AS SEQ
                         , NVL(B.QTY, 0) AS QTY
                         , NVL(B.QTY_TO_PCM, 0) AS QTY_TO_PCM
                         , NVL(B.QTY_TO_CELL, 0) AS QTY_TO_CELL
                         , B.LAST_UPDATED_BY AS LAST_UPDATED_BY
                         , B.LAST_UPDATE_DATE AS LAST_UPDATE_DATE
                      FROM GT_0023_PLAN_ITEM A
                         , SSP_ANL_SHIP_REQ_EE B
                         , SSP_MST_SITE_ITEM_EE_V C
                     WHERE B.FROM_DIVISION_ID = A.DIVISION_ID
                       AND B.FROM_SITE = A.SCM_SITE_ID
                       AND B.ITEM_ID = A.ITEM_ID
                       AND C.DIVISION_ID = A.DIVISION_ID
                       AND C.SCM_SITE_ID = A.SCM_SITE_ID
                       AND C.ITEM_ID = A.ITEM_ID
                       AND C.DIVISION_ID = P_DIVISION_ID
                       AND C.COMPANY_ID = P_COMPANY_ID
                       AND B.ETD_DATE >= P_FROM_YYYYMMDD
                       AND B.ETD_DATE <= P_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                       AND (TRIM(P_MODEL_ID) IS NULL
                        OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                       AND (TRIM(P_NICK_NAME) IS NULL
                        OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                     FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                    UNION ALL
                    /* C_SCP_PROD_PLAN,P_SCP_SHIP_PLAN_ETD,P_SHIP_PLAN_SIMU_ETD',C_FP_NPC_ASSY_PLAN,C_FP_COATER_PLAN Measure 추가 */
                    SELECT B.DIVISION_ID
                         , B.PLANT_ID AS PLANT_ID
                         , B.COMPANY_ID AS COMPANY_ID
                         , B.SCM_SITE_ID AS SCM_SITE_ID
                         , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                         , NVL(B.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                         , B.MODEL_ID AS MODEL_ID
                         , B.ITEM_ID AS ITEM_ID
                         , NVL(B.SCM_SITE_ID, '-') AS FROM_SITE
                         , NVL(B.BOD_ID, '-') AS BOD_ID
                         , B.MEASURE AS MEASURE
                         , B.YYYYMMDD AS YYYYMMDD
                         , CASE WHEN B.MEASURE = 'P_SCP_PROD_PLAN' THEN 1
                                WHEN B.MEASURE = 'P_SCP_SHIP_PLAN_ETD' THEN 2
                                WHEN B.MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN 4
                                WHEN B.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN 6
                                WHEN B.MEASURE = 'P_FP_COATER_PLAN' THEN 7
                           END AS SEQ
                         , NVL(B.QTY, 0) AS QTY
                         , NVL(B.QTY_TO_PCM, 0) AS QTY_TO_PCM
                         , NVL(B.QTY_TO_CELL, 0) AS QTY_TO_CELL
                         , '-' AS LAST_UPDATED_BY
                         , B.LAST_UPDATE_DATE AS LAST_UPDATE_DATE
                      FROM GT_0023_PLAN_ITEM A
                         , SSP_ANL_SHIP_PLAN_EE B
                         , SSP_MST_SITE_ITEM_EE_V C
                     WHERE B.DIVISION_ID = A.DIVISION_ID
                       AND B.ITEM_ID = A.ITEM_ID
                       AND B.SCM_SITE_ID = A.SCM_SITE_ID
                       AND B.COMPANY_ID = A.COMPANY_ID
                       AND C.DIVISION_ID = B.DIVISION_ID
                       AND C.ITEM_ID = B.ITEM_ID
                       AND C.SCM_SITE_ID = B.SCM_SITE_ID
                       AND B.MEASURE_TYPE = 'P'
                       AND B.DIVISION_ID = P_DIVISION_ID
                       AND B.COMPANY_ID = P_COMPANY_ID
                       AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND B.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND B.YYYYMMDD <= P_TO_YYYYMMDD
                       AND B.MEASURE IN ('P_SCP_PROD_PLAN', 'P_SCP_SHIP_PLAN_ETD', 'P_SHIP_PLAN_SIMU_ETD', 'P_FP_NPC_ASSY_PLAN', 'P_FP_COATER_PLAN')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR B.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR B.ITEM_ID IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                       AND (TRIM(P_MODEL_ID) IS NULL
                        OR B.MODEL_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                       AND (TRIM(P_NICK_NAME) IS NULL
                        OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                     FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                    UNION ALL
                    /* C_FP_COATER_POST_PLAN Measure 추가 */
                    /* ELECTRODE_POST_OPER_LT 더한 날짜가 조회 된다. */
                    SELECT B.DIVISION_ID
                         , B.PLANT_ID AS PLANT_ID
                         , B.COMPANY_ID AS COMPANY_ID
                         , B.SCM_SITE_ID AS SCM_SITE_ID
                         , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                         , NVL(B.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                         , B.MODEL_ID AS MODEL_ID
                         , B.ITEM_ID AS ITEM_ID
                         , NVL(B.SCM_SITE_ID, '-') AS FROM_SITE
                         , NVL(B.BOD_ID, '-') AS BOD_ID
                         , B.MEASURE AS MEASURE
                         , TO_CHAR(TO_DATE(B.YYYYMMDD, 'YYYYMMDD') + TRUNC(TO_NUMBER(NVL(C.ELECTRODE_POST_OPER_LT, '0'))), 'YYYYMMDD') AS YYYYMMDD
                         , 8 AS SEQ
                         , NVL(B.QTY, 0) AS QTY
                         , NVL(B.QTY_TO_PCM, 0) AS QTY_TO_PCM
                         , NVL(B.QTY_TO_CELL, 0) AS QTY_TO_CELL
                         , '-' AS LAST_UPDATED_BY
                         , B.LAST_UPDATE_DATE AS LAST_UPDATE_DATE
                      FROM GT_0023_PLAN_ITEM A
                         , SSP_ANL_SHIP_PLAN_EE B
                         , SSP_MST_SITE_ITEM_EE_V C
                     WHERE B.DIVISION_ID = A.DIVISION_ID
                       AND B.ITEM_ID = A.ITEM_ID
                       AND B.SCM_SITE_ID = A.SCM_SITE_ID
                       AND B.COMPANY_ID = A.COMPANY_ID
                       AND C.DIVISION_ID = B.DIVISION_ID
                       AND C.ITEM_ID = B.ITEM_ID
                       AND C.SCM_SITE_ID = B.SCM_SITE_ID
                       AND B.MEASURE_TYPE = 'P'
                       AND B.DIVISION_ID = P_DIVISION_ID
                       AND B.COMPANY_ID = P_COMPANY_ID
                       AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND B.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND B.YYYYMMDD <= P_TO_YYYYMMDD
                       AND B.MEASURE = 'P_FP_COATER_POST_PLAN'
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR B.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR B.ITEM_ID IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                       AND (TRIM(P_MODEL_ID) IS NULL
                        OR B.MODEL_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                       AND (TRIM(P_NICK_NAME) IS NULL
                        OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                     FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                    UNION ALL
                    /* P_INTRANSIT_ETA Measure 추가 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , IA.PLANT_ID AS PLANT_ID
                         , IA.COMPANY_ID AS COMPANY_ID
                         , IA.SCM_SITE_ID AS SCM_SITE_ID
                         , IA.ELECTRODE_POST_OPER_LT AS ELECTRODE_POST_OPER_LT
                         , IA.ELECTRODE_TYPE AS ELECTRODE_TYPE
                         , IA.MODEL_ID AS MODEL_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.BOD_ID AS BOD_ID
                         , 'P_INTRANSIT_ETA' AS MEASURE
                         , IA.YYYYMMDD AS YYYYMMDD
                         , 9 AS SEQ
                         , SUM(CAST(IA.QTY AS NUMBER(30, 3))) AS QTY            /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                         , SUM(IA.QTY_TO_PCM) AS QTY_TO_PCM
                         , SUM(IA.QTY_TO_CELL) AS QTY_TO_CELL
                         , '-'
                         , NULL
                      FROM (SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.YYYYMMDD AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , '-' AS ETD_DATE
                                 , '-' AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , (SELECT SA.DIVISION_ID
                                         , SA.COMPANY_ID
                                         , SA.PLANT_ID
                                         , SA.SCM_SITE_ID
                                         , XB.ITEM_ID
                                         , XB.INTRANSIT_QTY AS QTY
                                         , CASE WHEN TO_CHAR(XB.ETA_DATE, 'YYYYMMDD') < P_PLAN_START_YYYYMMDD THEN P_PLAN_START_YYYYMMDD
                                                ELSE TO_CHAR(XB.ETA_DATE, 'YYYYMMDD')
                                           END AS YYYYMMDD
                                      FROM GT_0023_INTRANSIT_CHK XB
                                         , SCP_MST_FINAL_ITEM XC
                                         , SCM_ADM_LOOKUP_MASTER_DETAIL XD      /* SEGMENT3:E_DIVISION_ID ,SEGMENT4 : E_PLANT_ID , ATTRIBUTE4 : E SCM_SITE_ID */
                                         , SCM_MST_SITE SA
                                     WHERE XC.DIVISION_ID = XB.DIVISION_ID
                                       AND XC.ITEM_ID = XB.ITEM_ID
                                       AND XC.OPERATION_GROUP = 'E'
                                       AND XD.LOOKUP_TYPE = 'ELECTRODE_ASSY_PLANT_MAPPING'
                                       AND XD.SEGMENT1 = XB.DIVISION_ID         /* 조립 DIVISION */
                                       AND XD.SEGMENT2 = XB.PLANT_ID            /* 조립 PLANT_ID */
                                       AND SA.DIVISION_ID = XD.SEGMENT3
                                       AND SA.PLANT_ID = XD.SEGMENT4
                                       AND SA.OPERATION_GROUP = 'E') B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.DIVISION_ID = A.DIVISION_ID
                               AND B.SCM_SITE_ID = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               AND B.YYYYMMDD >= V_RESULT_START_YYYYMMDD
                               AND B.YYYYMMDD <= V_RESULT_END_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                            UNION ALL
                            /* 출하 확정( @v_cutoff_plan_start_yyyymmdd ~ 전체 ) */
                            SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.YYYYMMDD AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , B.ETD_DATE AS ETD_DATE
                                 , B.ETA_DATE AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , (SELECT SA.DIVISION_ID
                                         , SA.COMPANY_ID
                                         , SA.PLANT_ID
                                         , SA.SCM_SITE_ID
                                         , XB.ITEM_ID
                                         , XB.QTY AS QTY
                                         , XB.ETA_DATE AS YYYYMMDD
                                         , XB.ETA_DATE
                                         , XB.ETD_DATE
                                      FROM SSP_ANL_SHIP_CONFIRM XB
                                         , SCM_ADM_LOOKUP_MASTER_DETAIL XD      /* SEGMENT3:E_DIVISION_ID ,SEGMENT4 : E_PLANT_ID , ATTRIBUTE4 : E SCM_SITE_ID */
                                         , SCM_MST_SITE SA
                                     WHERE XD.LOOKUP_TYPE = 'ELECTRODE_ASSY_PLANT_MAPPING'
                                       AND XD.SEGMENT1 = XB.DIVISION_ID         /* 조립 DIVISION */
                                       AND XD.ATTRIBUTE1 = XB.TO_SITE
                                       AND SA.DIVISION_ID = XD.SEGMENT3
                                       AND SA.PLANT_ID = XD.SEGMENT4
                                       AND SA.OPERATION_GROUP = 'E'
                                       AND XB.CHANGE_TYPE = 'C'
                                       AND XB.ETA_DATE >= P_PLAN_START_YYYYMMDD
                                       AND XB.ETA_DATE <= V_PLAN_END_YYYYMMDD) B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.DIVISION_ID = A.DIVISION_ID
                               AND B.SCM_SITE_ID = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                            UNION ALL
                            /* 출하요청 ( 확정구간 이후 ~ ) */
                            SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.ETD_DATE AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , B.ETD_DATE AS ETD_DATE
                                 , B.ETA_DATE AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , (SELECT SA.DIVISION_ID
                                         , SA.COMPANY_ID
                                         , SA.PLANT_ID
                                         , SA.SCM_SITE_ID
                                         , XB.ITEM_ID
                                         , XB.QTY AS QTY
                                         , XB.ETA_DATE AS YYYYMMDD
                                         , XB.FROM_SITE
                                         , XB.ETA_DATE
                                         , XB.ETD_DATE
                                      FROM SSP_ANL_SHIP_REQ_EE XB
                                         , SCM_ADM_LOOKUP_MASTER_DETAIL XD      /* SEGMENT3:E_DIVISION_ID ,SEGMENT4 : E_PLANT_ID , ATTRIBUTE4 : E SCM_SITE_ID */
                                         , SCM_MST_SITE SA
                                     WHERE XD.LOOKUP_TYPE = 'ELECTRODE_ASSY_PLANT_MAPPING'
                                       AND XD.SEGMENT1 = XB.TO_DIVISION_ID      /* 조립 DIVISION */
                                       AND XD.SEGMENT2 = XB.TO_PLANT_ID         /* 조립 PLANT_ID */
                                       AND XD.ATTRIBUTE1 = XB.TO_SITE
                                       AND SA.DIVISION_ID = XD.SEGMENT3
                                       AND SA.PLANT_ID = XD.SEGMENT4
                                       AND SA.OPERATION_GROUP = 'E'
                                       AND XB.ETA_DATE >= P_PLAN_START_YYYYMMDD  /* 시작일 부터 데이터를 조회(데이터 건수 줄이기 위해) */
                                       AND XB.ETA_DATE < V_PLAN_END_YYYYMMDD
                                       AND XB.CONFIRM_FLAG <> 'Y') B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.DIVISION_ID = A.DIVISION_ID
                               AND B.SCM_SITE_ID = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               /*확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16*/
                               AND B.ETA_DATE >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, A.DIVISION_ID, A.SCM_SITE_ID, P_PLAN_START_YYYYMMDD), 'YYYYMMDD')     /* cut off 시작 일부터 조회 */
                               AND B.ETA_DATE < V_PLAN_END_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))) IA
                     GROUP BY IA.COMPANY_ID
                            , IA.DIVISION_ID
                            , IA.PLANT_ID
                            , IA.SCM_SITE_ID
                            , IA.MODEL_ID
                            , IA.ITEM_ID
                            , IA.YYYYMMDD
                            , IA.FROM_SITE
                            , IA.BOD_ID
                            , IA.ETD_DATE
                            , IA.ETA_DATE
                            , IA.ELECTRODE_TYPE
                            , IA.ELECTRODE_POST_OPER_LT
                    UNION ALL
                    /* P_SHIP_CONFIRM_ETD Measure 추가 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , IA.PLANT_ID AS PLANT_ID
                         , IA.COMPANY_ID AS COMPANY_ID
                         , IA.SCM_SITE_ID AS SCM_SITE_ID
                         , IA.ELECTRODE_POST_OPER_LT AS ELECTRODE_POST_OPER_LT
                         , IA.ELECTRODE_TYPE AS ELECTRODE_TYPE
                         , IA.MODEL_ID AS MODEL_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.BOD_ID AS BOD_ID
                         , 'P_SHIP_CONFIRM_ETD' AS MEASURE
                         , IA.YYYYMMDD AS YYYYMMDD
                         , 5 AS SEQ
                         , SUM(CAST(IA.QTY AS NUMBER(30, 3))) AS QTY            /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                         , SUM(IA.QTY_TO_PCM) AS QTY_TO_PCM
                         , SUM(IA.QTY_TO_CELL) AS QTY_TO_CELL
                         , '-'
                         , NULL
                      FROM (SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.YYYYMMDD AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , '-' AS ETD_DATE
                                 , '-' AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , SSP_DNM_SHIP_RESULT_OWMS_V B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.DIVISION_ID = A.DIVISION_ID
                               AND B.FROM_SITE = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               AND B.YYYYMMDD >= V_RESULT_START_YYYYMMDD
                               AND B.YYYYMMDD <= V_RESULT_END_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                            UNION ALL
                            /* 출하 확정( @v_plan_start_yyyymmdd ~ 전체 ) */
                            SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(A.SCM_SITE_ID, '/') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.YYYYMMDD AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , B.ETD_DATE AS ETD_DATE
                                 , B.ETA_DATE AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , SSP_ANL_SHIP_CONFIRM B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.DIVISION_ID = A.DIVISION_ID
                               AND B.FROM_SITE = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND B.CHANGE_TYPE = 'C'
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               AND B.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                               AND B.YYYYMMDD <= V_PLAN_END_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                            UNION ALL
                            /* 출하요청 ( 확정구간 이후 ~ ) */
                            SELECT A.DIVISION_ID AS DIVISION_ID
                                 , A.PLANT_ID AS PLANT_ID
                                 , A.COMPANY_ID AS COMPANY_ID
                                 , A.SCM_SITE_ID AS SCM_SITE_ID
                                 , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                                 , NVL(C.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                                 , A.MODEL_ID AS MODEL_ID
                                 , A.ITEM_ID AS ITEM_ID
                                 , NVL(B.FROM_SITE, '-') AS FROM_SITE
                                 , '-' AS BOD_ID
                                 , B.ETD_DATE AS YYYYMMDD
                                 , B.QTY AS QTY
                                 , B.QTY * NVL(C.CONVERT_TO_PCM, 1) AS QTY_TO_PCM
                                 , B.QTY * NVL(C.CONVERT_TO_CELL, 1) AS QTY_TO_CELL
                                 , '-' AS LAST_UPDATED_BY
                                 , NULL AS LAST_UPDATE_DATE
                                 , B.ETD_DATE AS ETD_DATE
                                 , B.ETA_DATE AS ETA_DATE
                              FROM GT_0023_PLAN_ITEM A
                                 , SSP_ANL_SHIP_REQ_EE B
                                 , SSP_MST_SITE_ITEM_EE_V C
                             WHERE B.FROM_DIVISION_ID = A.DIVISION_ID
                               AND B.FROM_SITE = A.SCM_SITE_ID
                               AND B.ITEM_ID = A.ITEM_ID
                               AND C.DIVISION_ID = A.DIVISION_ID
                               AND C.SCM_SITE_ID = A.SCM_SITE_ID
                               AND C.ITEM_ID = A.ITEM_ID
                               AND A.DIVISION_ID = P_DIVISION_ID
                               AND A.COMPANY_ID = P_COMPANY_ID
                               /*확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16*/
                               AND B.ETD_DATE >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, A.DIVISION_ID, A.SCM_SITE_ID, P_PLAN_START_YYYYMMDD), 'YYYYMMDD')
                               AND B.ETD_DATE < V_PLAN_END_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR B.FROM_SITE IN (SELECT COLUMN_VALUE
                                                     FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                               AND (TRIM(P_MODEL_ID) IS NULL
                                OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                               AND (TRIM(P_NICK_NAME) IS NULL
                                OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                             FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))) IA
                     GROUP BY IA.COMPANY_ID
                            , IA.DIVISION_ID
                            , IA.PLANT_ID
                            , IA.SCM_SITE_ID
                            , IA.MODEL_ID
                            , IA.ITEM_ID
                            , IA.YYYYMMDD
                            , IA.FROM_SITE
                            , IA.BOD_ID
                            , IA.ETD_DATE
                            , IA.ETA_DATE
                            , IA.ELECTRODE_TYPE
                            , IA.ELECTRODE_POST_OPER_LT) XA
             GROUP BY XA.DIVISION_ID
                    , XA.PLANT_ID
                    , XA.COMPANY_ID
                    , XA.SCM_SITE_ID
                    , XA.ELECTRODE_POST_OPER_LT
                    , XA.ELECTRODE_TYPE
                    , XA.MODEL_ID
                    , XA.ITEM_ID
                    , XA.FROM_SITE
                    , XA.BOD_ID
                    , XA.MEASURE
                    , XA.SEQ
                    , XA.YYYYMMDD
                    , XA.LAST_UPDATED_BY
                    , XA.LAST_UPDATE_DATE;

            /*-------------------------------------------------------------------------------------------------------------
            --[R_INV_SHIP_REQ] Inventory(Ship Req) 계산
            -- R_INV_SHIP_REQ(당일) = BOH - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_ETD(당일) + P_SHIP_REQ_ETA(당일)
            -- R_INV_SHIP_REQ(익일) = P_INV_SHIP_REQ(당일) + P_FP_COATER_PLAN(당일) - P_FP_NPC_ASSY_PLAN(익일) - P_SHIP_PLAN_ETD(익일) + P_SHIP_REQ_ETA(익일)
            -------------------------------------------------------------------------------------------------------------*/
            INSERT INTO GT_0023_SIM
            (
                COMPANY_ID
              , DIVISION_ID
              , PLANT_ID
              , SCM_SITE_ID
              , MODEL_ID
              , ITEM_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
            )
            SELECT COMPANY_ID
                 , DIVISION_ID
                 , PLANT_ID
                 , SCM_SITE_ID
                 , MODEL_ID
                 , ITEM_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , QTY_TO_PCM
                 , QTY_TO_CELL
              FROM GT_0023_ROWDATA
             WHERE MEASURE IN ('P_INTRANSIT_ETA', 'P_FP_NPC_ASSY_PLAN', 'P_SHIP_PLAN_SIMU_ETD', 'P_FP_COATER_PLAN');

            /* P_INV_SIM(익일) = P_INV_SIM(전일) +  P_FP_COATER_PLAN(전일) +  P_INTRANSIT_ETA(당일) - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_SIMU_ETD(당일) */
            INSERT INTO GT_0023_ROWDATA
            (
                DIVISION_ID
              , PLANT_ID
              , COMPANY_ID
              , SCM_SITE_ID
              , ELECTRODE_POST_OPER_LT
              , ELECTRODE_TYPE
              , MODEL_ID
              , ITEM_ID
              , FROM_SITE
              , BOD_ID
              , MEASURE
              , YYYYMMDD
              , SEQ
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
            )
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.COMPANY_ID
                 , A.SCM_SITE_ID
                 , A.ELECTRODE_POST_OPER_LT
                 , A.ELECTRODE_TYPE
                 , A.MODEL_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID AS FROM_SITE
                 , '-' AS BOD_ID
                 , 'P_INV_SIM' AS MEASURE
                 , A.YYYYMMDD
                 , 10
                 /* P_INV_SIM(전일) */
                 , NVL(B.QTY, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* C_INTRANSIT_ETA(당일) - C_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_SIMU_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(SA.QTY, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
                 /* P_INV_SIM(전일) */
                 , NVL(B.QTY_TO_PCM, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY_TO_PCM), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* P_INTRANSIT_ETA(당일) - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_SIMU_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY_TO_PCM, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY_TO_PCM, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(SA.QTY_TO_PCM, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
                 /* P_INV_SIM(전일) */
                 , NVL(B.QTY_TO_CELL, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY_TO_CELL), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* C_INTRANSIT_ETA(당일) - C_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_SIMU_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY_TO_CELL, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY_TO_CELL, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(SA.QTY_TO_CELL, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_SIM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
              FROM (SELECT DISTINCT XA.COMPANY_ID
                         , XA.DIVISION_ID
                         , XA.PLANT_ID
                         , XA.SCM_SITE_ID
                         , XA.ELECTRODE_POST_OPER_LT
                         , XA.ELECTRODE_TYPE
                         , XA.MODEL_ID
                         , XA.ITEM_ID
                         , XB.YYYYMMDD
                      FROM GT_0023_ROWDATA XA
                         , (SELECT BASIS_YYYYMMDD AS YYYYMMDD
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
                               AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD) XB
                     WHERE XA.COMPANY_ID = P_COMPANY_ID
                       AND XB.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND XB.YYYYMMDD < P_TO_YYYYMMDD) A
                 , (SELECT XA.COMPANY_ID
                         , XA.DIVISION_ID
                         , XA.PLANT_ID
                         , XA.SCM_SITE_ID
                         , XA.MODEL_ID
                         , XA.ITEM_ID
                         , SUM(CAST(XA.QTY AS NUMBER(30, 3))) AS QTY            /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                         , SUM(XA.QTY_TO_PCM) AS QTY_TO_PCM
                         , SUM(XA.QTY_TO_CELL) AS QTY_TO_CELL
                      FROM (/* BOH */
                            SELECT COMPANY_ID
                                 , DIVISION_ID
                                 , PLANT_ID
                                 , SCM_SITE_ID
                                 , MODEL_ID
                                 , ITEM_ID
                                 , TOT_BOH_QTY AS QTY
                                 , TOT_BOH_QTY_PCM AS QTY_TO_PCM
                                 , TOT_BOH_QTY_CELL AS QTY_TO_CELL
                              FROM GT_0023_BOH_CUTOFF
                             WHERE CUTOFF_DATE = P_PLAN_START_YYYYMMDD
                               AND COMPANY_ID = P_COMPANY_ID
                            UNION ALL
                            /* + C_INTRANSIT_ETA(당일) - C_FP_NPC_ASSY_PLAN(당일) - P_SHIP_PLAN_SIMU_ETD(당일) */
                            SELECT COMPANY_ID
                                 , DIVISION_ID
                                 , PLANT_ID
                                 , SCM_SITE_ID
                                 , MODEL_ID
                                 , ITEM_ID
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(QTY, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY_TO_PCM, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY_TO_PCM, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(QTY_TO_PCM, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY_TO_PCM
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY_TO_CELL, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY_TO_CELL, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_PLAN_SIMU_ETD' THEN NVL(QTY_TO_CELL, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY_TO_CELL
                              FROM GT_0023_SIM
                             WHERE YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND MEASURE <> 'P_FP_COATER_PLAN'
                               AND COMPANY_ID = P_COMPANY_ID
                             GROUP BY COMPANY_ID
                                    , DIVISION_ID
                                    , PLANT_ID
                                    , SCM_SITE_ID
                                    , MODEL_ID
                                    , ITEM_ID) XA
                     GROUP BY XA.COMPANY_ID
                            , XA.DIVISION_ID
                            , XA.PLANT_ID
                            , XA.SCM_SITE_ID
                            , XA.MODEL_ID
                            , XA.ITEM_ID) B
             WHERE A.COMPANY_ID = B.COMPANY_ID(+)
               AND A.DIVISION_ID = B.DIVISION_ID(+)
               AND A.PLANT_ID = B.PLANT_ID(+)
               AND A.SCM_SITE_ID = B.SCM_SITE_ID(+)
               AND A.MODEL_ID = B.MODEL_ID(+)
               AND A.ITEM_ID = B.ITEM_ID(+);

            INSERT INTO GT_0023_CONFIRM
            (
                COMPANY_ID
              , DIVISION_ID
              , PLANT_ID
              , SCM_SITE_ID
              , MODEL_ID
              , ITEM_ID
              , MEASURE
              , YYYYMMDD
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
            )
            SELECT COMPANY_ID
                 , DIVISION_ID
                 , PLANT_ID
                 , SCM_SITE_ID
                 , MODEL_ID
                 , ITEM_ID
                 , MEASURE
                 , YYYYMMDD
                 , QTY
                 , QTY_TO_PCM
                 , QTY_TO_CELL
              FROM GT_0023_ROWDATA
             WHERE MEASURE IN ('P_INTRANSIT_ETA', 'P_FP_NPC_ASSY_PLAN', 'P_SHIP_CONFIRM_ETD', 'P_FP_COATER_PLAN');

            /* P_INV_CONFIRM(익일) = P_INV_CONFIRM(전일) + P_FP_COATER_PLAN(전일) + P_INTRANSIT_ETA(당일) - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_CONFIRM_ETD(당일) */
            INSERT INTO GT_0023_ROWDATA
            (
                DIVISION_ID
              , PLANT_ID
              , COMPANY_ID
              , SCM_SITE_ID
              , ELECTRODE_POST_OPER_LT
              , ELECTRODE_TYPE
              , MODEL_ID
              , ITEM_ID
              , FROM_SITE
              , BOD_ID
              , MEASURE
              , YYYYMMDD
              , SEQ
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
            )
            /* FROM_SITE 는 SCM_SITE_ID 동일하다 */
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.COMPANY_ID
                 , A.SCM_SITE_ID
                 , A.ELECTRODE_POST_OPER_LT
                 , A.ELECTRODE_TYPE
                 , A.MODEL_ID
                 , A.ITEM_ID
                 , A.SCM_SITE_ID AS FROM_SITE
                 , '-' AS BOD_ID
                 , 'P_INV_CONFIRM' AS MEASURE
                 , A.YYYYMMDD
                 , 11
                 /* P_INV_CONFIRM(전일) */
                 , NVL(B.QTY, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* C_INTRANSIT_ETA(당일) - C_FP_NPC_ASSY_PLAN(당일) - P_SHIP_CONFIRM_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(SA.QTY, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
                 /* P_INV_CONFIRM(전일) */
                 , NVL(B.QTY_TO_PCM, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY_TO_PCM), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* C_INTRANSIT_ETA(당일) - C_FP_NPC_ASSY_PLAN(당일) - P_SHIP_CONFIRM_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY_TO_PCM, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY_TO_PCM, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(SA.QTY_TO_PCM, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
                 /* P_INV_CONFIRM(전일) */
                 , NVL(B.QTY_TO_CELL, 0)
                 /* + C_FP_COATER_PLAN(전일) */
                 + (SELECT NVL(SUM(SA.QTY_TO_CELL), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE = 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < A.YYYYMMDD)
                 /* P_INTRANSIT_ETA(당일) - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_CONFIRM_ETD(당일) */
                 + (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'P_INTRANSIT_ETA' THEN NVL(SA.QTY_TO_CELL, 0)
                                        WHEN SA.MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(SA.QTY_TO_CELL, 0) * -1
                                        WHEN SA.MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(SA.QTY_TO_CELL, 0) * -1
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0023_CONFIRM SA
                     WHERE SA.COMPANY_ID = A.COMPANY_ID
                       AND SA.DIVISION_ID = A.DIVISION_ID
                       AND SA.PLANT_ID = A.PLANT_ID
                       AND SA.SCM_SITE_ID = A.SCM_SITE_ID
                       AND SA.MODEL_ID = A.MODEL_ID
                       AND SA.ITEM_ID = A.ITEM_ID
                       AND SA.MEASURE <> 'P_FP_COATER_PLAN'
                       AND SA.YYYYMMDD > P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= A.YYYYMMDD)
              FROM (SELECT DISTINCT XA.COMPANY_ID
                         , XA.DIVISION_ID
                         , XA.PLANT_ID
                         , XA.SCM_SITE_ID
                         , XA.ELECTRODE_POST_OPER_LT
                         , XA.ELECTRODE_TYPE
                         , XA.MODEL_ID
                         , XA.ITEM_ID
                         , XB.YYYYMMDD
                      FROM GT_0023_ROWDATA XA
                         , (SELECT BASIS_YYYYMMDD AS YYYYMMDD
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD >= P_PLAN_START_YYYYMMDD
                               AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD) XB
                     WHERE XA.COMPANY_ID = P_COMPANY_ID
                       AND XB.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND XB.YYYYMMDD <= P_TO_YYYYMMDD) A
                 , (SELECT XA.COMPANY_ID
                         , XA.DIVISION_ID
                         , XA.PLANT_ID
                         , XA.SCM_SITE_ID
                         , XA.MODEL_ID
                         , XA.ITEM_ID
                         , SUM(CAST(XA.QTY AS NUMBER(30, 3))) AS QTY            /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                         , SUM(XA.QTY_TO_PCM) AS QTY_TO_PCM
                         , SUM(XA.QTY_TO_CELL) AS QTY_TO_CELL
                      FROM (/* BOH */
                            SELECT COMPANY_ID
                                 , DIVISION_ID
                                 , PLANT_ID
                                 , SCM_SITE_ID
                                 , MODEL_ID
                                 , ITEM_ID
                                 , TOT_BOH_QTY AS QTY
                                 , TOT_BOH_QTY_PCM AS QTY_TO_PCM
                                 , TOT_BOH_QTY_CELL AS QTY_TO_CELL
                              FROM GT_0023_BOH_CUTOFF
                             WHERE CUTOFF_DATE = P_PLAN_START_YYYYMMDD
                               AND COMPANY_ID = P_COMPANY_ID
                            UNION ALL
                            /* + P_INTRANSIT_ETA(당일) - P_FP_NPC_ASSY_PLAN(당일) - P_SHIP_CONFIRM_ETD(당일) */
                            SELECT COMPANY_ID
                                 , DIVISION_ID
                                 , PLANT_ID
                                 , SCM_SITE_ID
                                 , MODEL_ID
                                 , ITEM_ID
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(QTY, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY_TO_PCM, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY_TO_PCM, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(QTY_TO_PCM, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY_TO_PCM
                                 , NVL(SUM(CASE WHEN MEASURE = 'P_INTRANSIT_ETA' THEN NVL(QTY_TO_CELL, 0)
                                                WHEN MEASURE = 'P_FP_NPC_ASSY_PLAN' THEN NVL(QTY_TO_CELL, 0) * -1
                                                WHEN MEASURE = 'P_SHIP_CONFIRM_ETD' THEN NVL(QTY_TO_CELL, 0) * -1
                                                ELSE 0
                                           END), 0) AS QTY_TO_CELL
                              FROM GT_0023_CONFIRM
                             WHERE YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND MEASURE <> 'P_FP_COATER_PLAN'
                               AND COMPANY_ID = P_COMPANY_ID
                             GROUP BY COMPANY_ID
                                    , DIVISION_ID
                                    , PLANT_ID
                                    , SCM_SITE_ID
                                    , MODEL_ID
                                    , ITEM_ID) XA
                     GROUP BY XA.COMPANY_ID
                            , XA.DIVISION_ID
                            , XA.PLANT_ID
                            , XA.SCM_SITE_ID
                            , XA.MODEL_ID
                            , XA.ITEM_ID) B
             WHERE A.COMPANY_ID = B.COMPANY_ID(+)
               AND A.DIVISION_ID = B.DIVISION_ID(+)
               AND A.PLANT_ID = B.PLANT_ID(+)
               AND A.SCM_SITE_ID = B.SCM_SITE_ID(+)
               AND A.MODEL_ID = B.MODEL_ID(+)
               AND A.ITEM_ID = B.ITEM_ID(+);

        ELSE

            /* 과거 기준 조회 */
            INSERT INTO GT_0023_ROWDATA
            (
                DIVISION_ID
              , PLANT_ID
              , COMPANY_ID
              , SCM_SITE_ID
              , ELECTRODE_POST_OPER_LT
              , ELECTRODE_TYPE
              , MODEL_ID
              , ITEM_ID
              , FROM_SITE
              , MEASURE
              , YYYYMMDD
              , SEQ
              , QTY
              , QTY_TO_PCM
              , QTY_TO_CELL
            )
            SELECT XA.DIVISION_ID
                 , XA.PLANT_ID
                 , XA.COMPANY_ID
                 , XA.SCM_SITE_ID
                 , XA.ELECTRODE_POST_OPER_LT
                 , XA.ELECTRODE_TYPE
                 , XA.MODEL_ID
                 , XA.ITEM_ID
                 , XA.FROM_SITE
                 , XA.MEASURE
                 , XA.YYYYMMDD
                 , XA.SEQ
                 , SUM(XA.QTY) AS QTY
                 , SUM(XA.QTY_TO_PCM) AS QTY_TO_PCM
                 , SUM(XA.QTY_TO_CELL) AS QTY_TO_CELL
              FROM (SELECT A.DIVISION_ID AS DIVISION_ID
                         , A.PLANT_ID AS PLANT_ID
                         , A.COMPANY_ID AS COMPANY_ID
                         , A.SCM_SITE_ID AS SCM_SITE_ID
                         , NVL(C.ELECTRODE_POST_OPER_LT, '-') AS ELECTRODE_POST_OPER_LT
                         , NVL(B.ELECTRODE_TYPE, '-') AS ELECTRODE_TYPE
                         , A.MODEL_ID AS MODEL_ID
                         , A.ITEM_ID AS ITEM_ID
                         , A.SCM_SITE_ID AS FROM_SITE
                         , B.MEASURE AS MEASURE
                         , B.YYYYMMDD AS YYYYMMDD
                         , 1 AS SEQ
                         , NVL(B.QTY, 0) AS QTY
                         , NVL(B.QTY_TO_PCM, 0) AS QTY_TO_PCM
                         , NVL(B.QTY_TO_CELL, 0) AS QTY_TO_CELL
                      FROM GT_0023_PLAN_ITEM A
                         , SSP_ANL_SHIP_PLAN_EE B
                         , SSP_MST_SITE_ITEM_EE_V C
                     WHERE A.COMPANY_ID = B.COMPANY_ID
                       AND A.DIVISION_ID = B.DIVISION_ID
                       AND A.PLANT_ID = B.PLANT_ID
                       AND A.SCM_SITE_ID = B.SCM_SITE_ID
                       AND A.MODEL_ID = B.MODEL_ID
                       AND A.ITEM_ID = B.ITEM_ID
                       AND C.DIVISION_ID = A.DIVISION_ID
                       AND C.ITEM_ID = A.ITEM_ID
                       AND C.SCM_SITE_ID = A.SCM_SITE_ID
                       AND B.MEASURE_TYPE = 'P'
                       AND B.DIVISION_ID = P_DIVISION_ID
                       AND B.COMPANY_ID = P_COMPANY_ID
                       AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND B.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND B.YYYYMMDD <= P_TO_YYYYMMDD
                       AND B.MEASURE IN ('P_SCP_PROD_PLAN', 'P_SCP_SHIP_PLAN_ETD', 'P_SHIP_REQ_ETD', 'P_SHIP_PLAN_SIMU_ETD'
                                       , 'P_SHIP_CONFIRM_ETD', 'P_FP_NPC_ASSY_PLAN', 'P_FP_COATER_PLAN', 'P_FP_COATER_POST_PLAN', 'P_INTRANSIT_ETA'
                                       , 'P_INV_SIM', 'P_INV_CONFIRM')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                       AND (TRIM(P_MODEL_ID) IS NULL
                        OR A.MODEL_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                       AND (TRIM(P_NICK_NAME) IS NULL
                        OR C.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                     FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))) XA
             GROUP BY XA.DIVISION_ID
                    , XA.PLANT_ID
                    , XA.COMPANY_ID
                    , XA.SCM_SITE_ID
                    , XA.ELECTRODE_POST_OPER_LT
                    , XA.ELECTRODE_TYPE
                    , XA.MODEL_ID
                    , XA.ITEM_ID
                    , XA.FROM_SITE
                    , XA.MEASURE
                    , XA.SEQ
                    , XA.YYYYMMDD;

        END IF;

        /*--////////////////////////////////////////////////////////////////////////////////--*/
        /*--//3. 해당 ITEM별 MEASURE 및 날짜 생성											//--*/
        /*--////////////////////////////////////////////////////////////////////////////////--*/
        /* 현재기준과 과거기준은 원자료 조인 키가 다르다(과거기준에는 MODEL_ID 조인이 없다) */
        IF P_REAL_FLAG = 'Y' THEN

        INSERT INTO GT_0023_RESULT
        (
            DIVISION_ID
          , PLANT_ID
          , SCM_SITE_ID
          , ELECTRODE_POST_OPER_LT
          , ELECTRODE_TYPE
          , MODEL_ID
          , ITEM_ID
          , FROM_SITE
          , MEASURE
          , SEQ
          , YYYYMMDD
          , QTY
          , QTY_TO_PCM
          , QTY_TO_CELL
          , TOT_BOH_QTY
          , JR_BOH_QTY
          , PC_BOH_QTY
          , TOT_BOH_QTY_PCM
          , JR_BOH_QTY_PCM
          , PC_BOH_QTY_PCM
          , TOT_BOH_QTY_CELL
          , JR_BOH_QTY_CELL
          , PC_BOH_QTY_CELL
        )
        SELECT XA.DIVISION_ID
             , XA.PLANT_ID
             , XA.SCM_SITE_ID
             , XA.ELECTRODE_POST_OPER_LT
             , XA.ELECTRODE_TYPE
             , XA.MODEL_ID
             , XA.ITEM_ID
             , XA.FROM_SITE
             , XA.MEASURE
             , XA.SEQ
             , XA.YYYYMMDD
             , NVL(XA.QTY, 0) AS QTY
             , NVL(XA.QTY_TO_PCM, 0) AS QTY_TO_PCM
             , NVL(XA.QTY_TO_CELL, 0) AS QTY_TO_CELL
             , NVL(XA.TOT_BOH_QTY, 0) AS TOT_BOH_QTY
             , NVL(XA.JR_BOH_QTY, 0) AS JR_BOH_QTY
             , NVL(XA.PC_BOH_QTY, 0) AS PC_BOH_QTY
             , NVL(XA.TOT_BOH_QTY_PCM, 0) AS TOT_BOH_QTY_PCM
             , NVL(XA.JR_BOH_QTY_PCM, 0) AS JR_BOH_QTY_PCM
             , NVL(XA.PC_BOH_QTY_PCM, 0) AS PC_BOH_QTY_PCM
             , NVL(XA.TOT_BOH_QTY_CELL, 0) AS TOT_BOH_QTY_CELL
             , NVL(XA.JR_BOH_QTY_CELL, 0) AS JR_BOH_QTY_CELL
             , NVL(XA.PC_BOH_QTY_CELL, 0) AS PC_BOH_QTY_CELL
          FROM (SELECT DISTINCT IA.DIVISION_ID
                     , IA.PLANT_ID
                     , IA.SCM_SITE_ID
                     , IA.ELECTRODE_POST_OPER_LT
                     , IA.ELECTRODE_TYPE
                     , IA.MODEL_ID
                     , IA.ITEM_ID
                     , B.FROM_SITE
                     , IA.MEASURE
                     , IA.SEQ
                     , B.YYYYMMDD
                     , B.QTY
                     , B.QTY_TO_PCM
                     , B.QTY_TO_CELL
                     , C.TOT_BOH_QTY
                     , C.JR_BOH_QTY
                     , C.PC_BOH_QTY
                     , C.TOT_BOH_QTY_PCM
                     , C.JR_BOH_QTY_PCM
                     , C.PC_BOH_QTY_PCM
                     , C.TOT_BOH_QTY_CELL
                     , C.JR_BOH_QTY_CELL
                     , C.PC_BOH_QTY_CELL
                  FROM (SELECT DISTINCT A.DIVISION_ID
                             , A.PLANT_ID
                             , A.SCM_SITE_ID
                             , A.ELECTRODE_POST_OPER_LT
                             , A.ELECTRODE_TYPE
                             , A.MODEL_ID
                             , A.ITEM_ID
                             , SA.COLUMN_NAME AS MEASURE
                             , SA.SORT_ORDER_NO AS SEQ
                             , A.YYYYMMDD
                          FROM GT_0023_ROWDATA A
                             , SCM_MST_SHEET_MEASURE SA
                         WHERE SA.PROGRAM_ID(+) = P_PROGRAM_ID
                           AND SA.SHEET_NAME(+) = P_SHEET_NAME) IA
                     , GT_0023_ROWDATA B
                     , GT_0023_BOH_CUTOFF C
                 WHERE B.DIVISION_ID(+) = IA.DIVISION_ID
                   AND B.PLANT_ID(+) = IA.PLANT_ID
                   AND B.SCM_SITE_ID(+) = IA.SCM_SITE_ID
                   AND B.ELECTRODE_TYPE(+) = IA.ELECTRODE_TYPE
                   AND B.MODEL_ID(+) = IA.MODEL_ID
                   AND B.ITEM_ID(+) = IA.ITEM_ID
                   AND B.MEASURE(+) = IA.MEASURE
                   AND B.YYYYMMDD(+) = IA.YYYYMMDD
                   AND C.DIVISION_ID(+) = IA.DIVISION_ID
                   AND C.ITEM_ID(+) = IA.ITEM_ID) XA;

        ELSE

        INSERT INTO GT_0023_RESULT
        (
            DIVISION_ID
          , PLANT_ID
          , SCM_SITE_ID
          , ELECTRODE_POST_OPER_LT
          , ELECTRODE_TYPE
          , MODEL_ID
          , ITEM_ID
          , FROM_SITE
          , MEASURE
          , SEQ
          , YYYYMMDD
          , QTY
          , QTY_TO_PCM
          , QTY_TO_CELL
          , TOT_BOH_QTY
          , JR_BOH_QTY
          , PC_BOH_QTY
          , TOT_BOH_QTY_PCM
          , JR_BOH_QTY_PCM
          , PC_BOH_QTY_PCM
          , TOT_BOH_QTY_CELL
          , JR_BOH_QTY_CELL
          , PC_BOH_QTY_CELL
        )
        SELECT XA.DIVISION_ID
             , XA.PLANT_ID
             , XA.SCM_SITE_ID
             , XA.ELECTRODE_POST_OPER_LT
             , XA.ELECTRODE_TYPE
             , XA.MODEL_ID
             , XA.ITEM_ID
             , XA.FROM_SITE
             , XA.MEASURE
             , XA.SEQ
             , XA.YYYYMMDD
             , NVL(XA.QTY, 0) AS QTY
             , NVL(XA.QTY_TO_PCM, 0) AS QTY_TO_PCM
             , NVL(XA.QTY_TO_CELL, 0) AS QTY_TO_CELL
             , NVL(XA.TOT_BOH_QTY, 0) AS TOT_BOH_QTY
             , NVL(XA.JR_BOH_QTY, 0) AS JR_BOH_QTY
             , NVL(XA.PC_BOH_QTY, 0) AS PC_BOH_QTY
             , NVL(XA.TOT_BOH_QTY_PCM, 0) AS TOT_BOH_QTY_PCM
             , NVL(XA.JR_BOH_QTY_PCM, 0) AS JR_BOH_QTY_PCM
             , NVL(XA.PC_BOH_QTY_PCM, 0) AS PC_BOH_QTY_PCM
             , NVL(XA.TOT_BOH_QTY_CELL, 0) AS TOT_BOH_QTY_CELL
             , NVL(XA.JR_BOH_QTY_CELL, 0) AS JR_BOH_QTY_CELL
             , NVL(XA.PC_BOH_QTY_CELL, 0) AS PC_BOH_QTY_CELL
          FROM (SELECT DISTINCT IA.DIVISION_ID
                     , IA.PLANT_ID
                     , IA.SCM_SITE_ID
                     , IA.ELECTRODE_POST_OPER_LT
                     , IA.ELECTRODE_TYPE
                     , IA.MODEL_ID
                     , IA.ITEM_ID
                     , B.FROM_SITE
                     , IA.MEASURE
                     , IA.SEQ
                     , B.YYYYMMDD
                     , B.QTY
                     , B.QTY_TO_PCM
                     , B.QTY_TO_CELL
                     , C.TOT_BOH_QTY
                     , C.JR_BOH_QTY
                     , C.PC_BOH_QTY
                     , C.TOT_BOH_QTY_PCM
                     , C.JR_BOH_QTY_PCM
                     , C.PC_BOH_QTY_PCM
                     , C.TOT_BOH_QTY_CELL
                     , C.JR_BOH_QTY_CELL
                     , C.PC_BOH_QTY_CELL
                  FROM (SELECT DISTINCT A.DIVISION_ID
                             , A.PLANT_ID
                             , A.SCM_SITE_ID
                             , A.ELECTRODE_POST_OPER_LT
                             , A.ELECTRODE_TYPE
                             , A.MODEL_ID
                             , A.ITEM_ID
                             , SA.COLUMN_NAME AS MEASURE
                             , SA.SORT_ORDER_NO AS SEQ
                             , A.YYYYMMDD
                          FROM GT_0023_ROWDATA A
                             , SCM_MST_SHEET_MEASURE SA
                         WHERE SA.PROGRAM_ID(+) = P_PROGRAM_ID
                           AND SA.SHEET_NAME(+) = P_SHEET_NAME) IA
                     , GT_0023_ROWDATA B
                     , GT_0023_BOH_CUTOFF C
                 WHERE B.DIVISION_ID(+) = IA.DIVISION_ID
                   AND B.PLANT_ID(+) = IA.PLANT_ID
                   AND B.SCM_SITE_ID(+) = IA.SCM_SITE_ID
                   AND B.ELECTRODE_TYPE(+) = IA.ELECTRODE_TYPE
                   AND B.ITEM_ID(+) = IA.ITEM_ID
                   AND B.MEASURE(+) = IA.MEASURE
                   AND B.YYYYMMDD(+) = IA.YYYYMMDD
                   AND C.DIVISION_ID(+) = IA.DIVISION_ID
                   AND C.ITEM_ID(+) = IA.ITEM_ID) XA;

        END IF;

        /*--////////////////////////////////////////////////////////////////////////////////--*/
        /*--//5. PIVOT				 													//--*/
        /*--////////////////////////////////////////////////////////////////////////////////--*/
        INSERT INTO GT_0023_PIVOT
        (
            DIVISION_ID
          , PLANT_ID
          , SCM_SITE_ID
          , ELECTRODE_POST_OPER_LT
          , ELECTRODE_TYPE
          , MODEL_ID
          , ITEM_ID
          , FROM_SITE
          , MEASURE
          , SEQ
          , YYYYMMDD
          , YYYYMM
          , ISO_WEEK
          , QTY
          , QTY_TO_PCM
          , QTY_TO_CELL
          , TOT_BOH_QTY
          , JR_BOH_QTY
          , PC_BOH_QTY
          , TOT_BOH_QTY_PCM
          , JR_BOH_QTY_PCM
          , PC_BOH_QTY_PCM
          , TOT_BOH_QTY_CELL
          , JR_BOH_QTY_CELL
          , PC_BOH_QTY_CELL
        )
        SELECT A.DIVISION_ID
             , A.PLANT_ID
             , A.SCM_SITE_ID
             , A.ELECTRODE_POST_OPER_LT
             , A.ELECTRODE_TYPE
             , A.MODEL_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.MEASURE
             , A.SEQ
             , 'D_' || A.YYYYMMDD AS YYYYMMDD
             , B.BASIS_YYYYMM AS YYYYMM
             , SUBSTR(B.BASIS_YYYYMM, -4) || B.ISO_WEEK AS ISO_WEEK
             , A.QTY AS QTY
             , A.QTY_TO_PCM AS QTY_TO_PCM
             , A.QTY_TO_CELL AS QTY_TO_CELL
             , A.TOT_BOH_QTY AS TOT_BOH_QTY
             , A.JR_BOH_QTY AS JR_BOH_QTY
             , A.PC_BOH_QTY AS PC_BOH_QTY
             , A.TOT_BOH_QTY_PCM AS TOT_BOH_QTY_PCM
             , A.JR_BOH_QTY_PCM AS JR_BOH_QTY_PCM
             , A.PC_BOH_QTY_PCM AS PC_BOH_QTY_PCM
             , A.TOT_BOH_QTY_CELL AS TOT_BOH_QTY_CELL
             , A.JR_BOH_QTY_CELL AS JR_BOH_QTY_CELL
             , A.PC_BOH_QTY_CELL AS PC_BOH_QTY_CELL
          FROM GT_0023_RESULT A
             , SCM_SYS_CALENDAR_M B
         WHERE A.YYYYMMDD = B.BASIS_YYYYMMDD(+);

        /*PIVOIT처리*******************************************************************************/
        /* PIVOIT 대상 날짜문자열 생성 */
        V_QRY_SUM := '';

        FOR R IN (SELECT IA.YYYYMMDD
                    FROM (SELECT 'X_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                               , 'X_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                          UNION ALL
                          SELECT 'X_M_' || A.BASIS_YYYYMM AS YYYYMMDD
                               , 'X_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                          UNION ALL
                          SELECT 'X_D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                               , 'X_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMMDD
                          UNION ALL
                          SELECT 'Y_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                               , 'Y_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                          UNION ALL
                          SELECT 'Y_M_' || A.BASIS_YYYYMM AS YYYYMMDD
                               , 'Y_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                          UNION ALL
                          SELECT 'Y_D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                               , 'Y_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMMDD
                          UNION ALL
                          SELECT 'Z_W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                               , 'Z_' || A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                          UNION ALL
                          SELECT 'Z_M_' || A.BASIS_YYYYMM AS YYYYMMDD
                               , 'Z_' || MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                          UNION ALL
                          SELECT 'Z_D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                               , 'Z_' || A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                            FROM SCM_SYS_CALENDAR_M A
                           WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                           GROUP BY A.BASIS_YYYYMMDD) IA
                   ORDER BY IA.SORT_ORDER_NO) LOOP

            /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
            IF INSTR(R.YYYYMMDD, 'X_M_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'X_W_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'X_D_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMMDD = ''' || SUBSTR(R.YYYYMMDD, -10) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Y_M_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY_TO_CELL, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Y_W_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY_TO_CELL, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Y_D_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMMDD = ''' || SUBSTR(R.YYYYMMDD, -10) || ''' THEN CAST(NVL(A.QTY_TO_CELL, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Z_M_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY_TO_PCM, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Z_W_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY_TO_PCM, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            ELSIF INSTR(R.YYYYMMDD, 'Z_D_') = 1 THEN
                V_QRY_SUM := V_QRY_SUM || ', CAST(SUM(CASE WHEN A.YYYYMMDD = ''' || SUBSTR(R.YYYYMMDD, -10) || ''' THEN CAST(NVL(A.QTY_TO_PCM, 0) AS NUMBER(30, 3)) ELSE 0 END) AS NUMBER(30, 3)) AS ' || R.YYYYMMDD || CHR(10);
            END IF;

        END LOOP;
        /*--//END PIVOT//--*/

        /*--////////////////////////////////////////////////////////////////////////////////--*/
        /*--//6. RESULT				 													//--*/
        /*--////////////////////////////////////////////////////////////////////////////////--*/
        /* 측정값 칸은 화면 설정에 따라 개수가 달라져 정적 SQL 로 쓸 수 없다(피벗 전용 동적 SQL) */
        V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
               || ', A.PLANT_ID' || CHR(10)
               || ', NVL(A.SCM_SITE_ID, ''/'') AS SCM_SITE_ID' || CHR(10)
               || ', A.ELECTRODE_POST_OPER_LT' || CHR(10)
               || ', A.ELECTRODE_TYPE' || CHR(10)
               || ', A.MODEL_ID' || CHR(10)
               || ', A.ITEM_ID' || CHR(10)
               || ', NVL(B.SCM_SITE_ID, ''/'') AS FROM_SITE' || CHR(10)
               || ', RANK() OVER(PARTITION BY A.DIVISION_ID, B.SCM_SITE_ID ORDER BY A.DIVISION_ID, A.MODEL_ID, A.ITEM_ID, B.SCM_SITE_ID, A.ELECTRODE_TYPE) AS GUBUN_NUM' || CHR(10)
               || ', ''-'' AS TEMPCOLUMN' || CHR(10)
               || ', CASE A.MEASURE WHEN ''P_SCP_PROD_PLAN'' THEN ''S''' || CHR(10)
               || '                 WHEN ''P_SCP_SHIP_PLAN_ETD'' THEN ''S''' || CHR(10)
               || '                 WHEN ''P_SHIP_REQ_ETD'' THEN ''S''' || CHR(10)
               || '                 WHEN ''P_SHIP_PLAN_SIMU_ETD'' THEN ''S''' || CHR(10)
               || '                 WHEN ''P_SHIP_CONFIRM_ETD'' THEN ''S''' || CHR(10)
               || '                 WHEN ''P_FP_NPC_ASSY_PLAN'' THEN ''P''' || CHR(10)
               || '                 WHEN ''P_FP_COATER_PLAN'' THEN ''P''' || CHR(10)
               || '                 WHEN ''P_FP_COATER_POST_PLAN'' THEN ''P''' || CHR(10)
               || '                 WHEN ''P_INTRANSIT_ETA'' THEN ''I''' || CHR(10)
               || '                 WHEN ''P_INV_SIM'' THEN ''I''' || CHR(10)
               || '                 WHEN ''P_INV_CONFIRM'' THEN ''I'' END AS PSI_NAME' || CHR(10)
               /* AS-IS 는 ISNULL(CONVERT(NVARCHAR(50),CEILING(x)),'0'*1000)/1000 로 괄호가 어긋나 문자/정수 나눗셈이 된다 -- 2026.09.23 AJS */
               || ', CEIL(NVL(A.TOT_BOH_QTY, 0) * 1000) / 1000 AS TOT_BOH_QTY' || CHR(10)
               || ', CEIL(NVL(A.JR_BOH_QTY, 0) * 1000) / 1000 AS JR_BOH_QTY' || CHR(10)
               || ', CEIL(NVL(A.PC_BOH_QTY, 0) * 1000) / 1000 AS PC_BOH_QTY' || CHR(10)
               || ', CEIL(NVL(A.TOT_BOH_QTY_PCM, 0) * 1000) / 1000 AS TOT_BOH_QTY_PCM' || CHR(10)
               || ', CEIL(NVL(A.JR_BOH_QTY_PCM, 0) * 1000) / 1000 AS JR_BOH_QTY_PCM' || CHR(10)
               || ', CEIL(NVL(A.PC_BOH_QTY_PCM, 0) * 1000) / 1000 AS PC_BOH_QTY_PCM' || CHR(10)
               || ', CEIL(NVL(A.TOT_BOH_QTY_CELL, 0) * 1000) / 1000 AS TOT_BOH_QTY_CELL' || CHR(10)
               || ', CEIL(NVL(A.JR_BOH_QTY_CELL, 0) * 1000) / 1000 AS JR_BOH_QTY_CELL' || CHR(10)
               || ', CEIL(NVL(A.PC_BOH_QTY_CELL, 0) * 1000) / 1000 AS PC_BOH_QTY_CELL' || CHR(10)
               || ', (SELECT NVL(SA.NICK_NAME, ''-'') FROM SCM_MST_ITEM_SN SA WHERE SA.ITEM_ID = A.ITEM_ID AND ROWNUM = 1) AS NICK_NAME';

        /* 과거기준 조회에만 ELECTRODE_TYPE 칸이 한 번 더 있다(AS-IS 동일) */
        IF P_REAL_FLAG <> 'Y' THEN
            V_EXEC := V_EXEC || CHR(10) || ', NVL(A.ELECTRODE_TYPE, ''-'') AS ELECTRODE_TYPE';
        END IF;

        V_EXEC := V_EXEC || CHR(10)
               || ', A.MEASURE' || CHR(10)
               || ', C.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
               || ', A.SEQ' || CHR(10)
               || ', TO_CHAR(TO_DATE(:B_FROZEN_YYYYMMDD, ''YYYYMMDD'') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE, A.DIVISION_ID, A.SCM_SITE_ID, :B_PLAN_START1), ''YYYYMMDD'') AS CONFIRM_DAY' || CHR(10)
               || ', C.ATTRIBUTE3 AS BACK_COLOR' || CHR(10)
               || V_QRY_SUM
               || '  FROM GT_0023_PIVOT A' || CHR(10)
               || '     , GT_0023_PLAN_ITEM B' || CHR(10)
               || '     , SCM_MST_SHEET_MEASURE C' || CHR(10)
               || '     , SCM_MST_TITLESET_USER D' || CHR(10)
               || ' WHERE B.DIVISION_ID = A.DIVISION_ID' || CHR(10)
               || '   AND B.PLANT_ID = A.PLANT_ID' || CHR(10)
               || '   AND B.SCM_SITE_ID = A.SCM_SITE_ID' || CHR(10)
               || '   AND B.MODEL_ID = A.MODEL_ID' || CHR(10)
               || '   AND B.ITEM_ID = A.ITEM_ID' || CHR(10)
               || '   AND A.MEASURE = C.COLUMN_NAME' || CHR(10)
               || '   AND C.PROGRAM_ID = :B_PROGRAM_ID1' || CHR(10)
               || '   AND C.SHEET_NAME = :B_SHEET_NAME1' || CHR(10)
               || '   AND D.PROGRAM_ID(+) = C.PROGRAM_ID' || CHR(10)
               || '   AND D.SHEET_NAME(+) = C.SHEET_NAME' || CHR(10)
               || '   AND D.COLUMN_NAME(+) = C.COLUMN_NAME' || CHR(10)
               || '   AND D.USER_ID(+) = :B_USER_ID1' || CHR(10)
               || '   AND C.VALID_YN = ''Y''' || CHR(10)
               || '   AND (:B_CNT1 = 0' || CHR(10)
               || '    OR EXISTS (SELECT 1' || CHR(10)
               || '                 FROM GT_0023_TITLESET SA' || CHR(10)
               || '                WHERE SA.COLUMN_NAME = C.COLUMN_NAME))' || CHR(10)
               || '   AND ((:B_CNT2 = 0 AND C.DEFAULT_FLAG = ''Y'')' || CHR(10)
               || '    OR (:B_CNT3 <> 0))' || CHR(10)
               || ' GROUP BY A.DIVISION_ID, A.PLANT_ID, A.SCM_SITE_ID, A.ELECTRODE_POST_OPER_LT, A.ELECTRODE_TYPE, A.MODEL_ID, A.ITEM_ID, B.SCM_SITE_ID' || CHR(10)
               || '        , A.TOT_BOH_QTY, A.PC_BOH_QTY, A.JR_BOH_QTY, A.TOT_BOH_QTY_PCM, A.PC_BOH_QTY_PCM, A.JR_BOH_QTY_PCM' || CHR(10)
               || '        , A.TOT_BOH_QTY_CELL, A.PC_BOH_QTY_CELL, A.JR_BOH_QTY_CELL, A.MEASURE, C.COLUMN_LABEL_NAME, A.SEQ, C.ATTRIBUTE3' || CHR(10)
               || ' ORDER BY A.DIVISION_ID, A.PLANT_ID, A.MODEL_ID, A.ITEM_ID, A.SEQ, B.SCM_SITE_ID ASC';

        OPEN O_RC1 FOR V_EXEC USING V_FROZEN_YYYYMMDD, V_APP_TYPE, P_PLAN_START_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE;

    END P_SSP0023_GET_SHIPMENT_PLAN;

    PROCEDURE P_SSP0023_GET_SHIPMENT_PLAN_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_MODEL_ID              IN  VARCHAR2
       ,P_NICK_NAME             IN  VARCHAR2
       ,P_REQUESTOR             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_NON_CHK               IN  VARCHAR2
       ,P_MY_MODEL_CHK          IN  VARCHAR2
       ,P_DELEGATEE_CHK         IN  VARCHAR2
       ,P_PART_LEADER_CHK       IN  VARCHAR2
       ,P_TEAM_LEADER_CHK       IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_GET_SHIPMENT_PLAN_DETAIL
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode) DETAIL
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-05-08   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선  최초 작성
 * 2020-09-21   KIMYONGHO		SSP INCOTERMS 변경 작업
 * 2021/09/02   KIMYONGHO      SCP_MST_BOD_N_V -> SCP_MST_BOD_N_V 변경
 * 2024/05/10   hsbang          확정구간 조회 일수(CONFIRM_DAY)를 펑션 FN_GET_ANL_SHIP_FROZEN_DAY_CNT] 에서 가져오도록 반영
 * 2025/12/11   chkim.68        E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_APP_TYPE              VARCHAR2(8) := 'SSP';
    BEGIN

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.SHIPMENT_STATUS
                     , A.ITEM_ID
                     , A.ITEM_ID_NICK_NAME
                     , A.MODEL_ID
                     , A.MODEL_ID_NICK_NAME
                     , (SELECT SA.DAYOFWEEK_NAME
                          FROM SCM_SYS_CALENDAR_M SA
                         WHERE SA.BASIS_YYYYMMDD = A.YYYYMMDD) AS DAYOFWEEK_NAME
                     /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , CAST(A.SHIPPING_PLAN_QTY AS NUMBER(30, 3)) AS SHIPPING_PLAN_QTY
                     , CAST(NVL(A.QTY, 0) AS NUMBER(30, 3)) AS SHIPMENT_CONFIRM_QTY
                     , CAST((A.SHIPPING_PLAN_QTY - NVL(A.QTY, 0)) AS NUMBER(30, 3)) AS GAP
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                     , ROW_NUMBER() OVER(PARTITION BY A.DIVISION_ID, A.ERP_SO_NO, A.SHIPMENT_STATUS, A.CELL_TYPE, A.YYYYMMDD, A.ITEM_ID, A.MODEL_ID, A.FROM_SITE, A.TO_SITE
                                             ORDER BY A.DIVISION_ID, A.SHIPMENT_STATUS, A.ERP_SO_NO DESC, A.CELL_TYPE, A.YYYYMMDD, A.ITEM_ID, A.FROM_SITE, A.TO_SITE) AS MERGE_NUM
                     , A.DOM_EXP_TYPE AS DOM_EXP
                     , A.FACTORY_ID AS FACTORY_ID
                     , A.FACTORY_ID AS FACTORY_NAME
                     , A.CONFIRM_QTY_PANCAKE
                     , A.CONFIRM_QTY_JR
                     , A.CONFIRM_QTY_CELL
                     , A.CONFIRM_QTY_ROLL_LENGTH
                     , A.PACKAGE_TYPE_CODE AS PACKAGE_TYPE
                     /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , CEIL(CASE WHEN A.PACKAGE_TYPE_CODE = 'BX' THEN A.CONFIRM_QTY_ROLL_LENGTH * NVL(A.BOX_PER_CUT, 1)
                                 WHEN A.PACKAGE_TYPE_CODE = 'SC' THEN A.CONFIRM_QTY_ROLL_LENGTH * NVL(A.STEELCRATE_PER_CUT, 1)
                                 WHEN A.PACKAGE_TYPE_CODE = 'SR' THEN A.CONFIRM_QTY_ROLL_LENGTH * NVL(A.STEELRACK_PER_CUT, 1)
                            ELSE NVL(A.QTY, 0) END * 1000) / 1000 AS PACKAGE_QTY
                     , A.ELECTRODE_POST_OPER AS ELECTRODE_POST_OPER
                     , A.FROM_SITE AS FROM_SITE
                     , A.TO_SITE AS TO_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION
/* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN P_LANGUAGE = 'KO' THEN F.USERNAME ELSE F.USERNAME_E END || '(' || A.REQUESTOR || ')' AS REQUESTOR
                     , CASE WHEN P_LANGUAGE = 'KO' THEN F.USER_NM ELSE F.USER_ENG_NM END || '(' || A.REQUESTOR || ')' AS REQUESTOR
/* 2026.09.30 AJS 수정 (END) */
                     , B.TRANSPORT_MODE
                     , A.REMARKS2
                     , A.REMARKS
                     , '-' AS CHANGE_REASON_CODE
                     , NULL AS CHANGE_REASON_DETAIL
                     , A.REMARKS3
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                     /* 2020-09-21   KIMYONGHO		SSP INCOTERMS 변경 작업 */
                     , B.SSP_INCOTERMS AS INCOTERMS
                     , B.LT_TOTAL AS LT_DAY
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                     , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                            ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')
                       END AS EXPECTED_SHIPPING_DATE
/* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN P_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END || '(' || A.LAST_UPDATED_BY || ')' AS UPDATED_BY
--                     , CASE WHEN C.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                     , CASE WHEN P_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END || '(' || A.LAST_UPDATED_BY || ')' AS UPDATED_BY
                     , CASE WHEN C.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
/* 2026.09.30 AJS 수정 (END) */
                     , D.CHANGE_REQ_NO
/* 2026.09.30 AJS 수정 (START) */
--                     , CASE WHEN P_LANGUAGE = 'KO' THEN G.USERNAME ELSE G.USERNAME_E END || '(' || E.USER_ID || ')' AS MODEL_USER
                     , CASE WHEN P_LANGUAGE = 'KO' THEN G.USER_NM ELSE G.USER_ENG_NM END || '(' || E.USER_ID || ')' AS MODEL_USER
/* 2026.09.30 AJS 수정 (END) */
                     , A.CONFIRM_ID
                     , B.LT_TOTAL AS NEW_LT_DAY
                     , B.TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                     , A.ERP_STATUS
                     , A.CHANGE_TYPE
                     , A.NEW_ROUTE_ID
                     , A.NEW_BOD_ID
                     , A.NEW_INCOTERMS
                     , A.NEW_D_COUNTRY
                     , A.NEW_D_PORT_CODE
                     , A.NEW_A_COUNTRY
                     , A.NEW_A_PORT_CODE
                     , A.NEW_CUSTOMER_LT
                     , A.NEW_TO_COUNTRY
                     , A.NEW_TO_CITY
                     , A.NEW_ETA
                     , A.NEW_ETD
                     , A.NEW_SHIPMENT_DATE
                     , A.EDIT_REMARKS
                     , A.EDIT_MAIN
                     , A.CHECK_NEED_YN
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     , A.CELL_TYPE
                     , A.ATTRIBUTE10
                  FROM (SELECT DISTINCT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.REQUESTOR
                             , XA.QTY
                             , XB.ITEM_ID_NICK_NAME
                             , XB.MODEL_ID
                             , XB.MODEL_ID_NICK_NAME
                             , NVL(XA.ELECTRODE_TYPE, XB.ELECTRODE_TYPE) AS ELECTRODE_TYPE
                             , NVL(XA.DOM_EXP, XB.DOM_EXP_TYPE) AS DOM_EXP_TYPE
                             /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                             , CAST(XA.QTY * NVL(XB.CONVERT_TO_PCM, 1) AS NUMBER(30, 3)) AS CONFIRM_QTY_PANCAKE
                             , CAST(XA.QTY * NVL(XB.CONVERT_TO_JRM, 1) AS NUMBER(30, 3)) AS CONFIRM_QTY_JR
                             , CAST(XA.QTY * NVL(XB.CONVERT_TO_CELL, 1) AS NUMBER(30, 3)) AS CONFIRM_QTY_CELL
                             , CEIL(XA.QTY * 1000) / 1000 * NVL(XB.CONVERT_TO_PC_ROLL_LENGTH, 1) AS CONFIRM_QTY_ROLL_LENGTH
                             , NVL(XA.PACKAGE_TYPE_CODE, XB.PACKAGE_TYPE_CODE) AS PACKAGE_TYPE_CODE
                             , XB.BOX_PER_CUT
                             , XB.STEELCRATE_PER_CUT
                             , XB.STEELRACK_PER_CUT
                             , XB.ELECTRODE_POST_OPER
                             , XB.CELL_TYPE
                             , XA.YYYYMMDD
                             , XA.BOD_ID
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.CONFIRM_ID
                             , XA.ERP_STATUS
                             , XA.CHANGE_TYPE
                             , TO_CHAR(XA.ROUTE_ID) AS NEW_ROUTE_ID
                             , XA.BOD_ID AS NEW_BOD_ID
                             , XA.INCOTERMS AS NEW_INCOTERMS
                             , XA.D_COUNTRY AS NEW_D_COUNTRY
                             , XA.D_PORT_CODE AS NEW_D_PORT_CODE
                             , XA.A_COUNTRY AS NEW_A_COUNTRY
                             , XA.A_PORT_CODE AS NEW_A_PORT_CODE
                             , TO_CHAR(XA.CUSTOMER_LT) AS NEW_CUSTOMER_LT
                             , XA.TO_COUNTRY AS NEW_TO_COUNTRY
                             , XA.TO_CITY AS NEW_TO_CITY
                             , TO_CHAR(TO_DATE(XA.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                             , TO_CHAR(TO_DATE(XA.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                             , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                             , 'N' AS EDIT_REMARKS
                             , 'N' AS EDIT_MAIN
                             , NVL(XA.CHECK_NEED_YN, 'N') AS CHECK_NEED_YN
                             , XA.ELECTRODE_YN
                             , NVL(XA.FACTORY_ID, XB.FACTORY_ID) AS FACTORY_ID
                             , NVL(XC.QTY, 0) AS SHIPPING_PLAN_QTY
                             , XA.ATTRIBUTE10
                          FROM SSP_ANL_SHIP_CONFIRM XA
                             , SSP_MST_SITE_ITEM_EE_V XB
                             , SSP_ANL_SHIP_PLAN_EE XC
                         WHERE XB.DIVISION_ID = XA.DIVISION_ID
                           AND XB.SCM_SITE_ID = XA.FROM_SITE
                           AND XB.ITEM_ID = XA.ITEM_ID
                           AND XC.MEASURE(+) = 'P_SHIP_PLAN_SIMU_ETD'
                           AND XC.PLAN_START_YYYYMMDD(+) = P_PLAN_START_YYYYMMDD
                           AND XC.DIVISION_ID(+) = XB.DIVISION_ID
                           AND XC.SCM_SITE_ID(+) = XB.SCM_SITE_ID
                           AND XC.ITEM_ID(+) = XB.ITEM_ID
                           AND XC.YYYYMMDD(+) = XA.YYYYMMDD
                           AND XA.CHANGE_TYPE = 'C'
                           AND XA.DIVISION_ID = P_DIVISION_ID
                           AND XA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                           AND (P_NON_CHK = 'Y'
                            OR EXISTS (SELECT 1
                                         FROM SSP_MST_MODEL_USER SA
                                        WHERE SA.DIVISION_ID = XA.DIVISION_ID
                                          AND SA.FROM_SITE = XA.FROM_SITE
                                          AND SA.ITEM_ID = XA.ITEM_ID
                                          AND SA.VALID_YN = 'Y'
                                          AND (SA.USER_ID IN (SELECT CASE WHEN P_MY_MODEL_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                                                FROM DUAL
                                                              UNION
                                                              SELECT CASE WHEN P_DELEGATEE_CHK = 'Y' THEN SB.USER_ID ELSE 'X' END
                                                                FROM SSP_MST_DELEGATE SB
                                                               WHERE SB.VALID_YN = 'Y'
                                                                 AND SB.DELEGATEE_ID = P_USER_ID
                                                               GROUP BY SB.USER_ID)
                                           OR SA.PART_LEADER = CASE WHEN P_PART_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                           OR SA.TEAM_LEADER = CASE WHEN P_TEAM_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END)))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                           AND (TRIM(P_MODEL_ID) IS NULL
                            OR XB.MODEL_ID IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                           AND (TRIM(P_NICK_NAME) IS NULL
                            OR XB.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                          FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                           AND ((P_DBL_FLAG = 'Y'
                            AND XA.YYYYMMDD = P_FROM_YYYYMMDD)
                            OR (P_DBL_FLAG <> 'Y'
                            AND XA.YYYYMMDD >= P_FROM_YYYYMMDD
                            AND XA.YYYYMMDD <= P_TO_YYYYMMDD
                            AND (TRIM(P_REQUESTOR) IS NULL
/* 2026.09.30 AJS 수정 (START) */
--                             OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                   FROM TB_FX_USER SA
--                                                  WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                             OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                   FROM SCM_ADM_USER_M SA
                                                  WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
/* 2026.09.30 AJS 수정 (END) */
                                                                          FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                 UNION ALL
/* 2026.09.30 AJS 수정 (START) */
--                                                 SELECT DISTINCT SA.USERID
--                                                   FROM TB_FX_USER SA
--                                                  WHERE SA.USERID IN (SELECT COLUMN_VALUE
                                                 SELECT DISTINCT SA.USER_ID
                                                   FROM SCM_ADM_USER_M SA
                                                  WHERE SA.USER_ID IN (SELECT COLUMN_VALUE
/* 2026.09.30 AJS 수정 (END) */
                                                                        FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))))
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                        UNION ALL
                        SELECT IA.DIVISION_ID
                             , IA.ERP_SO_NO
                             , IA.SHIPMENT_STATUS
                             , IA.ITEM_ID
                             , IA.ORIGIN_FROM_DIVISION_ID
                             , IA.ORIGIN_TO_DIVISION_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.REQUESTOR
                             , IA.QTY
                             , IA.ITEM_ID_NICK_NAME
                             , IA.MODEL_ID
                             , IA.MODEL_ID_NICK_NAME
                             , IA.ELECTRODE_TYPE
                             , IA.DOM_EXP_TYPE
                             , IA.CONFIRM_QTY_PANCAKE
                             , IA.CONFIRM_QTY_JR
                             , IA.CONFIRM_QTY_CELL
                             , IA.CONFIRM_QTY_ROLL_LENGTH
                             , IA.PACKAGE_TYPE_CODE
                             , IA.BOX_PER_CUT
                             , IA.STEELCRATE_PER_CUT
                             , IA.STEELRACK_PER_CUT
                             , IA.ELECTRODE_POST_OPER
                             , IA.CELL_TYPE
                             , IA.YYYYMMDD
                             , IA.BOD_ID
                             , IA.REMARKS2
                             , IA.REMARKS
                             , IA.CHANGE_REQ_NO
                             , IA.REMARKS3
                             , IA.ETD_DATE
                             , IA.ETA_DATE
                             , IA.LAST_UPDATED_BY
                             , IA.LAST_UPDATE_DATE
                             , IA.CONFIRM_ID
                             , '-' AS ERP_STATUS
                             , '-' AS CHANGE_TYPE
                             , '-' AS NEW_ROUTE_ID
                             , '-' AS NEW_BOD_ID
                             , '-' AS NEW_INCOTERMS
                             , '-' AS NEW_D_COUNTRY
                             , '-' AS NEW_D_PORT_CODE
                             , '-' AS NEW_A_COUNTRY
                             , '-' AS NEW_A_PORT_CODE
                             , '-' AS NEW_CUSTOMER_LT
                             , '-' AS NEW_TO_COUNTRY
                             , '-' AS NEW_TO_CITY
                             , '-' AS NEW_ETA
                             , '-' AS NEW_ETD
                             , '-' AS NEW_SHIPMENT_DATE
                             , '-' AS EDIT_REMARKS
                             , '-' AS EDIT_MAIN
                             , '-' AS CHECK_NEED_YN
                             , '-' AS ELECTRODE_YN
                             , IA.FACTORY_ID
                             , IA.SHIPPING_PLAN_QTY
                             , NULL AS ATTRIBUTE10
                          FROM (SELECT XA.FROM_DIVISION_ID AS DIVISION_ID
                                     , '-' AS ERP_SO_NO
                                     , 'P' AS SHIPMENT_STATUS
                                     , XA.ITEM_ID
                                     , XA.FROM_DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
                                     , XA.TO_DIVISION_ID AS ORIGIN_TO_DIVISION_ID
                                     , XA.FROM_SITE AS FROM_SITE
                                     , XA.TO_SITE AS TO_SITE
                                     , XA.LAST_UPDATED_BY AS REQUESTOR
                                     , XA.QTY
                                     , XA.ETD_DATE AS YYYYMMDD
                                     , XA.BOD_ID
                                     , '-' AS REMARKS2
                                     , '-' AS REMARKS
                                     , '-' AS CHANGE_REQ_NO
                                     , '-' AS REMARKS3
                                     , XA.ETD_DATE AS ETD_DATE
                                     , XA.ETA_DATE AS ETA_DATE
                                     , XA.LAST_UPDATED_BY
                                     , XA.LAST_UPDATE_DATE
                                     , '-' AS CONFIRM_ID
                                     , TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, XA.FROM_DIVISION_ID, XA.FROM_SITE, P_PLAN_START_YYYYMMDD), 'YYYYMMDD') AS FROZEN_YYYYMMDD
                                     , XC.FACTORY_ID
                                     , XC.ITEM_ID_NICK_NAME
                                     , XC.MODEL_ID
                                     , XC.MODEL_ID_NICK_NAME
                                     , XC.ELECTRODE_TYPE
                                     , XC.DOM_EXP_TYPE
                                     , TRUNC(XA.QTY * NVL(XC.CONVERT_TO_PCM, 1)) AS CONFIRM_QTY_PANCAKE
                                     , TRUNC(XA.QTY * NVL(XC.CONVERT_TO_JRM, 1)) AS CONFIRM_QTY_JR
                                     , TRUNC(XA.QTY * NVL(XC.CONVERT_TO_CELL, 1)) AS CONFIRM_QTY_CELL
                                     , CEIL(XA.QTY * NVL(XC.CONVERT_TO_PC_ROLL_LENGTH, 1)) AS CONFIRM_QTY_ROLL_LENGTH
                                     , XC.PACKAGE_TYPE_CODE AS PACKAGE_TYPE_CODE
                                     , XC.BOX_PER_CUT
                                     , XC.STEELCRATE_PER_CUT
                                     , XC.STEELRACK_PER_CUT
                                     , XC.ELECTRODE_POST_OPER
                                     , XC.CELL_TYPE
                                     , NVL(XD.QTY, 0) AS SHIPPING_PLAN_QTY
                                  FROM SSP_ANL_SHIP_REQ_EE XA
                                     , SCP_MST_BOD_N_V XB
                                     , SSP_MST_SITE_ITEM_EE_V XC
                                     , SSP_ANL_SHIP_PLAN_EE XD
                                 WHERE XA.FROM_DIVISION_ID = XB.DIVISION_ID
                                   AND XA.BOD_ID = XB.BOD_ID
                                   AND XC.DIVISION_ID = XA.FROM_DIVISION_ID
                                   AND XC.SCM_SITE_ID = XA.FROM_SITE
                                   AND XC.ITEM_ID = XA.ITEM_ID
                                   AND XD.MEASURE(+) = 'P_SHIP_PLAN_SIMU_ETD'
                                   AND XD.PLAN_START_YYYYMMDD(+) = P_PLAN_START_YYYYMMDD
                                   AND XD.DIVISION_ID(+) = XC.DIVISION_ID
                                   AND XD.SCM_SITE_ID(+) = XC.SCM_SITE_ID
                                   AND XD.ITEM_ID(+) = XC.ITEM_ID
                                   AND XD.YYYYMMDD(+) = XA.ETD_DATE
                                   AND XA.FROM_DIVISION_ID = P_DIVISION_ID
                                   AND XA.FROM_COMPANY_ID = P_COMPANY_ID
                                   AND (P_NON_CHK = 'Y'
                                    OR EXISTS (SELECT 1
                                                 FROM SSP_MST_MODEL_USER SA
                                                WHERE SA.DIVISION_ID = XA.FROM_DIVISION_ID
                                                  AND SA.FROM_SITE = XA.FROM_SITE
                                                  AND SA.ITEM_ID = XA.ITEM_ID
                                                  AND SA.VALID_YN = 'Y'
                                                  AND (SA.USER_ID IN (SELECT CASE WHEN P_MY_MODEL_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                                                        FROM DUAL
                                                                      UNION
                                                                      SELECT CASE WHEN P_DELEGATEE_CHK = 'Y' THEN SB.USER_ID ELSE 'X' END
                                                                        FROM SSP_MST_DELEGATE SB
                                                                       WHERE SB.VALID_YN = 'Y'
                                                                         AND SB.DELEGATEE_ID = P_USER_ID
                                                                       GROUP BY SB.USER_ID)
                                                   OR SA.PART_LEADER = CASE WHEN P_PART_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                                   OR SA.TEAM_LEADER = CASE WHEN P_TEAM_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END)))
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                                   AND (TRIM(P_MODEL_ID) IS NULL
                                    OR XA.MODEL_ID IN (SELECT COLUMN_VALUE
                                                         FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                                   AND (TRIM(P_NICK_NAME) IS NULL
                                    OR XC.ITEM_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                                  FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                                   AND ((P_DBL_FLAG = 'Y'
                                    AND XA.ETD_DATE = P_FROM_YYYYMMDD)
                                    OR (P_DBL_FLAG <> 'Y'
                                    AND XA.ETD_DATE >= P_FROM_YYYYMMDD
                                    AND XA.ETD_DATE <= P_TO_YYYYMMDD))
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                          FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) IA
                         WHERE IA.YYYYMMDD >= IA.FROZEN_YYYYMMDD) A
                     , SCP_MST_BOD_N_V B
/* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER C
                     , SCM_ADM_USER_M C
/* 2026.09.30 AJS 수정 (END) */
                     , (SELECT IA.CONFIRM_ID
                             , IA.CHANGE_REQ_NO
                          FROM (SELECT SA.CONFIRM_ID
                                     , SA.CHANGE_REQ_NO
                                     , ROW_NUMBER() OVER(PARTITION BY SA.CONFIRM_ID ORDER BY SA.CHANGE_REQ_NO DESC) AS NUM
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE SA
                                 WHERE SA.VALID_YN = 'Y') IA
                         WHERE IA.NUM = 1) D
                     , SSP_MST_MODEL_USER E
/* 2026.09.30 AJS 수정 (START) */
--                     , TB_FX_USER G
--                     , TB_FX_USER F
                     , SCM_ADM_USER_M G
                     , SCM_ADM_USER_M F
/* 2026.09.30 AJS 수정 (END) */
                     , SSP_ANL_SHIP_CONFIRM_CHG_REQ H
                 WHERE (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = B.DIVISION_ID
                   AND A.BOD_ID = B.BOD_ID
/* 2026.09.30 AJS 수정 (START) */
--                   AND A.LAST_UPDATED_BY = C.USERID(+)
--                   AND C.USEYN(+) = 'Y'
                   AND A.LAST_UPDATED_BY = C.USER_ID(+)
                   AND C.USE_YN(+) = 'Y'
/* 2026.09.30 AJS 수정 (END) */
                   AND D.CONFIRM_ID(+) = A.CONFIRM_ID
                   AND E.DIVISION_ID(+) = A.ORIGIN_FROM_DIVISION_ID
                   AND E.FROM_SITE(+) = A.FROM_SITE
                   AND E.ITEM_ID(+) = A.ITEM_ID
                   AND E.VALID_YN(+) = 'Y'
/* 2026.09.30 AJS 수정 (START) */
--                   AND E.USER_ID = G.USERID(+)
--                   AND G.USEYN(+) = 'Y'
--                   AND A.REQUESTOR = F.USERID(+)
--                   AND F.USEYN(+) = 'Y'
                   AND E.USER_ID = G.USER_ID(+)
                   AND G.USE_YN(+) = 'Y'
                   AND A.REQUESTOR = F.USER_ID(+)
                   AND F.USE_YN(+) = 'Y'
/* 2026.09.30 AJS 수정 (END) */
                   AND D.CHANGE_REQ_NO = H.CHANGE_REQ_NO(+)
                   AND A.SHIPMENT_STATUS IS NOT NULL
                   AND A.QTY > 0
                 ORDER BY A.DIVISION_ID, A.YYYYMMDD, A.ITEM_ID, A.FROM_SITE, A.TO_SITE, A.ERP_SO_NO DESC;

        ELSE

            /* 과거기준 조회 */
            /* AS-IS 는 권한 조인에 존재하지 않는 별칭(C)을 써 NON_CHK <> 'Y' 경로가 SQL 오류로 끝난다 -- 2026.09.23 AJS */
            /* AS-IS 는 PLAN_START_YYYYMMDD · YYYYMMDD 조건에 따옴표가 빠져 숫자 비교가 된다 -- 2026.09.23 AJS */
            OPEN O_RC1 FOR
                SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.SHIPMENT_STATUS
                     , A.PROJECT_CODE
                     , A.PROJECT_NAME
                     , A.FCST_TYPE
                     , A.ITEM_ID
                     , A.NICK_NAME
                     , A.MODEL_ID
                     , A.MODEL_ID_NICK_NAME AS ITEM_ID_NICK_NAME
                     , A.SHIPMENT_DATE
                     , A.SHIPPING_PLAN_QTY
                     , A.SHIPMENT_CONFIRM_QTY
                     , A.REMARKS
                     , A.REMARKS2
                     , A.REMARKS3
                     , A.FROM_SITE
                     , A.FROM_SITE_DESCRIPTION
                     , A.TO_SITE
                     , A.TO_SITE_DESCRIPTION
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , A.SOLDTO_DESCRIPTION
                     , A.SHIPTO_DESCRIPTION
                     , A.BOD_ID
                     , A.INCOTERMS
                     , A.TRANSPORT_MODE
                     , A.LT_DAY
                     , A.ETD
                     , A.ETA
                     , A.EXPECTED_SHIPPING_DATE
                     , A.CONFIRM_ID
                     , A.UPDATED_BY
                     , A.UPDATED_DATE
                     , '-' AS ERP_STATUS
                     , '-' AS CHANGE_TYPE
                     , '-' AS NEW_ROUTE_ID
                     , '-' AS NEW_BOD_ID
                     , '-' AS NEW_INCOTERMS
                     , '-' AS NEW_D_COUNTRY
                     , '-' AS NEW_D_PORT_CODE
                     , '-' AS NEW_A_COUNTRY
                     , '-' AS NEW_A_PORT_CODE
                     , '-' AS NEW_CUSTOMER_LT
                     , '-' AS NEW_TO_COUNTRY
                     , '-' AS NEW_TO_CITY
                     , '-' AS NEW_ETA
                     , '-' AS NEW_ETD
                     , '-' AS NEW_LT_DAY
                     , '-' AS NEW_TRANSPORT_MODE
                     , '-' AS NEW_SHIPMENT_DATE
                     , '-' AS EDIT_REMARKS
                     , '-' AS EDIT_MAIN
                     , '-' AS CHECK_NEED_YN
                     , A.END_CUSTOMER AS END_CUSTOMER
                     , '-' AS ELECTRODE_YN
                     , '-' AS ELECTRODE_TYPE
                     , '-' AS ORIGIN_FROM_DIVISION_ID
                     , '-' AS ORIGIN_TO_DIVISION_ID
                     , A.CHANGE_REQ_NO AS CHANGE_REQ_NO
                     , A.MODEL_USER AS MODEL_USER
                     , A.MTK_OWNER AS MTK_OWNER
                     , A.REQUESTOR AS REQUESTOR
                     , A.CHANGE_REASON_CODE
                     , A.CHANGE_REASON_DETAIL
                     , A.DOM_EXP AS DOM_EXP
                     , A.DAYOFWEEK_NAME AS DAYOFWEEK_NAME
                     , A.GAP AS GAP
                     , A.CONFIRM_QTY_ROLL_LENGTH
                     , A.PACKAGE_TYPE
                     , A.PACKAGE_QTY
                     , A.ELECTRODE_POST_OPER
                     , A.CONFIRM_QTY_PANCAKE
                     , A.CONFIRM_QTY_JR
                     , A.CONFIRM_QTY_CELL
                     , A.CELL_TYPE
                     , A.FACTORY_ID
                     , ROW_NUMBER() OVER(PARTITION BY A.DIVISION_ID, A.ERP_SO_NO, A.SHIPMENT_STATUS, A.CELL_TYPE, A.SHIPMENT_DATE, A.ITEM_ID, A.MODEL_ID, A.FROM_SITE, A.TO_SITE
                                             ORDER BY A.DIVISION_ID, A.SHIPMENT_STATUS, A.ERP_SO_NO DESC, A.CELL_TYPE, A.SHIPMENT_DATE, A.ITEM_ID, A.FROM_SITE, A.TO_SITE) AS MERGE_NUM
                  FROM (SELECT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.NICK_NAME
                             , XA.MODEL_ID
                             , XA.MODEL_ID_NICK_NAME
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.FROM_SITE_DESCRIPTION
                             , XA.TO_SITE
                             , XA.TO_SITE_DESCRIPTION
                             , XA.PROJECT_CODE
                             , XA.PROJECT_NAME
                             , XA.REQUESTOR
                             , XA.SHIPMENT_CONFIRM_QTY
                             , XA.SHIPPING_PLAN_QTY
                             , TRUNC(XA.SHIPPING_PLAN_QTY - NVL(XA.SHIPMENT_CONFIRM_QTY, 0)) AS GAP
                             , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                             , XA.BOD_ID
                             , XA.INCOTERMS
                             , XA.TRANSPORT_MODE
                             , XA.TO_SITE_SOLDTO_CODE
                             , XA.TO_SITE_SHIPTO_CODE
                             , XA.SOLDTO_DESCRIPTION
                             , XA.SHIPTO_DESCRIPTION
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , TO_CHAR(TO_DATE(XA.ETD, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                             , TO_CHAR(TO_DATE(XA.ETA, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                             , XA.EXPECTED_SHIPPING_DATE
                             , XA.LT_DAY AS LT_DAY
                             , XA.UPDATED_BY AS UPDATED_BY
                             , XA.UPDATED_DATE AS UPDATED_DATE
                             , XA.CONFIRM_ID AS CONFIRM_ID
                             , XA.FCST_TYPE
                             , XA.END_CUSTOMER
                             , XA.MTK_OWNER
                             , XA.MODEL_USER
                             , XA.DOM_EXP
                             , XA.DAYOFWEEK_NAME
                             , XA.CONFIRM_QTY_ROLL_LENGTH
                             , XA.PACKAGE_TYPE
                             , XA.PACKAGE_QTY
                             , XA.ELECTRODE_POST_OPER
                             , XA.CONFIRM_QTY_PANCAKE
                             , XA.CONFIRM_QTY_JR
                             , XA.CONFIRM_QTY_CELL
                             , XA.CELL_TYPE
                             , XA.CHANGE_REASON_CODE
                             , XA.CHANGE_REASON_DETAIL
                             , XA.FACTORY_ID
                          FROM SSP_ANL_SHIP_PLAN_ALL XA
                         WHERE XA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND XA.DIVISION_ID = P_DIVISION_ID
                           AND XA.COMPANY_ID = P_COMPANY_ID
                           AND XA.SHIPMENT_CONFIRM_QTY > 0
                           AND XA.OPERATION_GROUP = 'E'
                           AND XA.YYYYMMDD >= P_FROM_YYYYMMDD
                           AND XA.YYYYMMDD <= P_TO_YYYYMMDD
                           AND (P_NON_CHK = 'Y'
                            OR EXISTS (SELECT 1
                                         FROM SSP_MST_MODEL_USER SA
                                        WHERE SA.DIVISION_ID = XA.DIVISION_ID
                                          AND SA.FROM_SITE = XA.FROM_SITE
                                          AND SA.ITEM_ID = XA.ITEM_ID
                                          AND SA.VALID_YN = 'Y'
                                          AND (SA.USER_ID IN (SELECT CASE WHEN P_MY_MODEL_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                                                FROM DUAL
                                                              UNION
                                                              SELECT CASE WHEN P_DELEGATEE_CHK = 'Y' THEN SB.USER_ID ELSE 'X' END
                                                                FROM SSP_MST_DELEGATE SB
                                                               WHERE SB.VALID_YN = 'Y'
                                                                 AND SB.DELEGATEE_ID = P_USER_ID
                                                               GROUP BY SB.USER_ID)
                                           OR SA.PART_LEADER = CASE WHEN P_PART_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                           OR SA.TEAM_LEADER = CASE WHEN P_TEAM_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END)))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR XA.ITEM_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_MODEL_ID) IS NULL
                            OR XA.MODEL_ID IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_MODEL_ID, ','))))
                           AND (TRIM(P_NICK_NAME) IS NULL
                            OR XA.MODEL_ID_NICK_NAME IN (SELECT COLUMN_VALUE
                                                           FROM TABLE(STRING_SPLIT(P_NICK_NAME, ','))))
                           AND ((P_DBL_FLAG = 'Y'
                            AND XA.YYYYMMDD = P_FROM_YYYYMMDD)
                            OR (P_DBL_FLAG <> 'Y'
                            AND XA.YYYYMMDD >= P_FROM_YYYYMMDD
                            AND XA.YYYYMMDD <= P_TO_YYYYMMDD
                            AND (TRIM(P_REQUESTOR) IS NULL
/* 2026.09.30 AJS 수정 (START) */
--                             OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
--                                                   FROM TB_FX_USER SA
--                                                  WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                             OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                   FROM SCM_ADM_USER_M SA
                                                  WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
/* 2026.09.30 AJS 수정 (END) */
                                                                          FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                 UNION ALL
/* 2026.09.30 AJS 수정 (START) */
--                                                 SELECT DISTINCT SA.USERID
--                                                   FROM TB_FX_USER SA
--                                                  WHERE SA.USERID IN (SELECT COLUMN_VALUE
                                                 SELECT DISTINCT SA.USER_ID
                                                   FROM SCM_ADM_USER_M SA
                                                  WHERE SA.USER_ID IN (SELECT COLUMN_VALUE
/* 2026.09.30 AJS 수정 (END) */
                                                                        FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))))) A
                 ORDER BY A.DIVISION_ID, A.SHIPMENT_STATUS, A.SHIPMENT_DATE, A.ITEM_ID, A.ERP_SO_NO DESC, A.FROM_SITE, A.TO_SITE, A.PROJECT_CODE, A.FCST_TYPE;

        END IF;

    END P_SSP0023_GET_SHIPMENT_PLAN_DETAIL;

    PROCEDURE P_SSP0023_GET_SHIPMENT_PLAN_DETAIL_EXCEL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_MODEL_ID              IN  VARCHAR2
       ,P_NICK_NAME             IN  VARCHAR2
       ,P_REQUESTOR             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_NON_CHK               IN  VARCHAR2
       ,P_MY_MODEL_CHK          IN  VARCHAR2
       ,P_DELEGATEE_CHK         IN  VARCHAR2
       ,P_PART_LEADER_CHK       IN  VARCHAR2
       ,P_TEAM_LEADER_CHK       IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_GET_SHIPMENT_PLAN_DETAIL_EXCEL
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode) DETAIL
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-07-29   KIMYONGHO		신규추가
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT A.COMPANY_ID AS COMPANY_ID
                 , A.DIVISION_ID AS DIVISION_ID
                 , A.SCM_SITE_ID AS FROM_SITE
                 , A.ITEM_ID AS ITEM_ID
                 , A.YYYYMMDD AS YYYYMMDD
                 , NVL(B.QTY, 0) AS QTY
                 , NULL AS "Comment"                                            /* 예약어라 이름을 그대로 유지한다 */
              FROM (SELECT XB.COMPANY_ID
                         , XB.DIVISION_ID
                         , XB.PLANT_ID
                         , XB.SCM_SITE_ID
                         , XB.MODEL_ID
                         , XB.ITEM_ID
                         , XA.YYYYMMDD
                      FROM SSP_MST_SHIP_CALENDAR XA
                         , SSP_ANL_SHIP_PLAN_EE XB
                     WHERE XB.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND XB.COMPANY_ID = P_COMPANY_ID
                       AND XB.DIVISION_ID = P_DIVISION_ID
                       AND XB.SCM_SITE_ID IS NOT NULL                           /* AS-IS 의 LIKE '%' 조건 */
                       AND XB.MODEL_ID IS NOT NULL                              /* AS-IS 의 LIKE '%' 조건 */
                       AND XB.MEASURE = 'P_SHIP_PLAN_SIMU_ETD'
                       AND XB.COMPANY_ID = XA.COMPANY_ID
                       AND XB.DIVISION_ID = XA.DIVISION_ID
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR XB.ITEM_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= P_TO_YYYYMMDD
                     GROUP BY XB.COMPANY_ID
                            , XB.DIVISION_ID
                            , XB.PLANT_ID
                            , XB.SCM_SITE_ID
                            , XB.MODEL_ID
                            , XB.ITEM_ID
                            , XA.YYYYMMDD) A
                 , SSP_ANL_SHIP_PLAN_EE B
             WHERE B.PLAN_START_YYYYMMDD(+) = P_PLAN_START_YYYYMMDD
               AND B.COMPANY_ID(+) = P_COMPANY_ID
               AND B.DIVISION_ID(+) = P_DIVISION_ID
               AND B.MEASURE(+) = 'P_SHIP_PLAN_SIMU_ETD'
               AND B.QTY(+) > 0
               AND A.COMPANY_ID = B.COMPANY_ID(+)
               AND A.DIVISION_ID = B.DIVISION_ID(+)
               AND A.PLANT_ID = B.PLANT_ID(+)
               AND A.SCM_SITE_ID = B.SCM_SITE_ID(+)
               AND A.MODEL_ID = B.MODEL_ID(+)
               AND A.ITEM_ID = B.ITEM_ID(+)
               AND A.YYYYMMDD = B.YYYYMMDD(+)
             ORDER BY A.ITEM_ID, A.YYYYMMDD;

    END P_SSP0023_GET_SHIPMENT_PLAN_DETAIL_EXCEL;

    PROCEDURE P_SSP0023_GET_SHIPMENT_PLAN_RESULT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_TYPE                  IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_MYMODELCHK            IN  VARCHAR2
       ,P_PARTLEADERCHK         IN  VARCHAR2
       ,P_TEAMLEADERCHK         IN  VARCHAR2
       ,P_DELEGATEECHK          IN  VARCHAR2
       ,P_NONCHK                IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_GET_SHIPMENT_PLAN_RESULT
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode)
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-06-05   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선  최초 작성
 * 2020.09.18	KIMYONGHO		ERP_ORDER_TYPE 주석 처리 Request by 김광희 책임
 * 2021.02.17	KIMYONGHO		실적 조회시 TRNSPORT_MODE, INCOTERMS, ERP_SO_NO, ETA_DATE, ETD_DATE ERP 실적 기준으로 조회 Request by 김광희 책임
 * 2021.04.05   KIMYONGHO       [C20210330-000402] Shipment Plan화면의 실적 조회시 Sales site Mapping 안되는건에 대해서도 전수 표시 요청
 * 2021.05.03   SSP Pjt.        SSP_SHIP_RESULT_EXCEPT_ERP_ORDER_TYPE LOOKUP적용
 * 2021.11.15   KIMYONGHO       Confirm Data Plan Date 기준 조회 처리
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , B.COMPANY_ID AS COMPANY_ID
                 , C.SEGMENT2 AS TYPE
                 , A.ERP_SO_NO
                 , A.CONFIRM_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                 , E.MODEL_ID
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), A.FROM_SITE) AS FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), A.TO_SITE) AS TO_SITE
                 , A.END_CUSTOMER
                 , A.QTY
                 , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS YYYYMMDD
                 , A.TRANSPORT_MODE
                 , A.INCOTERMS
                 , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD_DATE
                 , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA_DATE
                 , A.SHIP_TYPE
              FROM (/* CONFIRM_ID ,날짜동일한 기준으로 계획정보의 FROM, TO SITE기준으로 실적 집계 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , IA.ERP_SO_NO AS ERP_SO_NO
                         , IA.CONFIRM_ID AS CONFIRM_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , SUM(IA.RESULT_QTY) AS QTY
                         , IA.YYYYMMDD AS YYYYMMDD
                         , IA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , IA.INCOTERMS AS INCOTERMS
                         , IA.ETD_DATE AS ETD_DATE
                         , IA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                            SELECT XA.DIVISION_ID AS DIVISION_ID
                                 , XA.CONFIRM_ID AS CONFIRM_ID
                                 , XA.ORDER_NO AS ERP_SO_NO
                                 , XA.EXFACTORY_DATE AS YYYYMMDD
                                 , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , XA.INCOTERMS AS INCOTERMS
                                 , XA.ETA_DATE AS ETA_DATE
                                 , XA.ETD_DATE AS ETD_DATE
                                 , XA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , XA.TO_SCM_SITE_ID AS TO_SITE
                                 , XA.ITEM_ID AS ITEM_ID
                                 , SUM(XA.EXFACTORY_QTY) AS RESULT_QTY
                              FROM SCM_DNM_EXFACTORY_RESULT XA
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL XB
                             WHERE XB.LOOKUP_TYPE = 'ERP_SSP_TYPE'              /* LOOKUP에 등록된 공정만 */
                               AND XB.VALID_YN = 'Y'
                               AND XB.SEGMENT1 = XA.SSP_TYPE
                               AND NVL(XA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND XA.CONFIRM_ID LIKE 'C%'
                               AND XA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY XA.DIVISION_ID
                                    , XA.CONFIRM_ID
                                    , XA.ORDER_NO
                                    , XA.EXFACTORY_DATE
                                    , XA.TRANSPORT_MODE
                                    , XA.INCOTERMS
                                    , XA.ETA_DATE
                                    , XA.ETD_DATE
                                    , XA.FROM_SCM_SITE_ID
                                    , XA.TO_SCM_SITE_ID
                                    , XA.ITEM_ID) IA
                     GROUP BY IA.DIVISION_ID
                            , IA.ERP_SO_NO
                            , IA.FROM_SITE
                            , IA.TO_SITE
                            , IA.ITEM_ID
                            , IA.TRANSPORT_MODE
                            , IA.INCOTERMS
                            , IA.ETD_DATE
                            , IA.ETA_DATE
                            , IA.YYYYMMDD
                            , IA.CONFIRM_ID
                    UNION ALL
                    /* CONFIRM_ID 없는 실적 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , IA.ERP_SO_NO AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , IA.QTY AS QTY
                         , IA.YYYYMMDD AS YYYYMMDD
                         , IA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , IA.INCOTERMS AS INCOTERMS
                         , IA.ETD_DATE AS ETD_DATE
                         , IA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
                            SELECT XA.DIVISION_ID AS DIVISION_ID
                                 , '-' AS CONFIRM_ID
                                 , XA.ORDER_NO AS ERP_SO_NO
                                 , XA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , NVL(XE.SEGMENT4, XA.TO_SCM_SITE_ID) AS TO_SITE
                                 , XA.ITEM_ID AS ITEM_ID
                                 , XA.EXFACTORY_DATE AS YYYYMMDD
                                 , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , XA.INCOTERMS AS INCOTERMS
                                 , XA.ETA_DATE AS ETA_DATE
                                 , XA.ETD_DATE AS ETD_DATE
                                 , SUM(XA.EXFACTORY_QTY) AS QTY
                              FROM SCM_DNM_EXFACTORY_RESULT XA
                                 , SCP_MST_FINAL_ITEM XB                        /* SCP 대상 ITEM만 */
                                 , SCM_MST_SITE XC
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL XD
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL XE
                             WHERE XB.ITEM_ID = XA.ITEM_ID
                               AND XB.DIVISION_ID = XA.DIVISION_ID
                               AND XC.SCM_SITE_ID = XA.FROM_SCM_SITE_ID
                               AND XC.DIVISION_ID = XA.DIVISION_ID
                               /* 2020.09.18 김광희 책임 요청으로 주석처리 */
                               /* 2021.04.15 김광희 책임 요청으로 주석해제 */
                               AND XD.LOOKUP_TYPE = 'ERP_ORDER_TYPE'            /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                               AND XD.VALID_YN = 'Y'
                               AND XD.SEGMENT1 = XA.ORDER_TYPE_CODE
                               AND XE.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'    /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                               AND XE.SEGMENT1(+) = XA.DIVISION_ID
                               AND XE.SEGMENT2(+) = XA.SOLDTO_CODE
                               AND XE.SEGMENT3(+) = XA.SHIPTO_CODE
                               AND NVL(XA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND NVL(XA.CONFIRM_ID, '-') NOT LIKE 'C%'
                               AND XA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND XA.STORAGE_ID NOT IN ('6000', '799A')        /* 상품창고제외 */
                               /* [C20200403-000062] 사외 창고 제외 LOOKUP 관리 */
                               AND NOT EXISTS (SELECT 1
                                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                                WHERE SA.SEGMENT1 = XA.STORAGE_ID
                                                  AND SA.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                                  AND SA.VALID_YN = 'Y')
                             GROUP BY XA.DIVISION_ID
                                    , XA.ORDER_NO
                                    , XA.FROM_SCM_SITE_ID
                                    , NVL(XE.SEGMENT4, XA.TO_SCM_SITE_ID)
                                    , XA.ITEM_ID
                                    , XA.EXFACTORY_DATE
                                    , XA.TRANSPORT_MODE
                                    , XA.INCOTERMS
                                    , XA.ETA_DATE
                                    , XA.ETD_DATE) IA
                    UNION ALL
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , 'P' AS TYPE
                         , IA.ERP_SO_NO AS ERP_SO_NO
                         , IA.CONFIRM_ID AS CONFIRM_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.TO_SITE AS TO_SITE
                         , IA.END_CUSTOMER AS END_CUSTOMER
                         , IA.QTY AS QTY
                         , IA.YYYYMMDD AS YYYYMMDD
                         , IA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , IA.INCOTERMS AS INCOTERMS
                         , IA.ETD_DATE AS ETD_DATE
                         , IA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* SSP출하계획 ( confirm된 계획) - Current Version */
                            SELECT XA.DIVISION_ID AS DIVISION_ID
                                 , XA.ERP_SO_NO AS ERP_SO_NO
                                 , XA.CONFIRM_ID AS CONFIRM_ID
                                 , XA.ITEM_ID AS ITEM_ID
                                 , XA.FROM_SITE AS FROM_SITE
                                 , XA.TO_SITE AS TO_SITE
                                 , CASE WHEN XA.DIVISION_ID = '4O' THEN NVL(XB.PROJECT_CODE, '/')
                                        ELSE NVL(XC.END_CUSTOMER, '-')
                                   END AS END_CUSTOMER
                                 , XA.QTY AS QTY
                                 , XA.YYYYMMDD AS YYYYMMDD
                                 , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , XA.INCOTERMS AS INCOTERMS
                                 , XA.ETD_DATE AS ETD_DATE
                                 , XA.ETA_DATE AS ETA_DATE
                                 , NULL AS SHIP_TYPE
                              FROM SSP_ANL_SHIP_CONFIRM XA
                                 , SCM_MST_SITE_ITEM XB
                                 , SCM_MST_SITE XC
                             WHERE XB.DIVISION_ID(+) = XA.DIVISION_ID
                               AND XB.ITEM_ID(+) = XA.ITEM_ID
                               AND XB.SCM_SITE_ID(+) = XA.TO_SITE
                               AND XB.PROJECT_CODE(+) = XA.PROJECT_CODE
                               AND XC.DIVISION_ID(+) = XA.DIVISION_ID
                               AND XC.SCM_SITE_ID(+) = XA.TO_SITE
                               AND XA.CHANGE_TYPE = 'C'
                               AND XA.QTY > 0
                               AND XA.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD) IA
                    UNION ALL
                    /* OWMS 실적 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , 'O' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , IA.QTY AS QTY
                         , IA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , IA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하실적 */
                            SELECT DIVISION_ID AS DIVISION_ID
                                 , ITEM_ID AS ITEM_ID
                                 , FROM_SITE AS FROM_SITE
                                 , CASE WHEN TO_SITE = '-' THEN CUSTOMER_CODE ELSE TO_SITE END AS TO_SITE
                                 , SUM(LOT_QTY) AS QTY
                                 , PLANT_ISSUE_DATE AS YYYYMMDD
                                 , SHIP_TYPE AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RESULT_OWMS
                             WHERE PLANT_ISSUE_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY DIVISION_ID
                                    , ITEM_ID
                                    , FROM_SITE
                                    , CASE WHEN TO_SITE = '-' THEN CUSTOMER_CODE ELSE TO_SITE END
                                    , PLANT_ISSUE_DATE
                                    , SHIP_TYPE) IA
                    UNION ALL
                    /* OWMS 반품실적 */
                    SELECT IA.DIVISION_ID AS DIVISION_ID
                         , 'R' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , IA.ITEM_ID AS ITEM_ID
                         , IA.FROM_SITE AS FROM_SITE
                         , IA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , IA.QTY AS QTY
                         , IA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , IA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하 반품 */
                            SELECT DIVISION_ID AS DIVISION_ID
                                 , ITEM_ID AS ITEM_ID
                                 , FROM_SITE AS FROM_SITE
                                 , '*' AS TO_SITE
                                 , SUM(RECIEPT_QTY) AS QTY
                                 , RECIEPT_DATE AS YYYYMMDD
                                 , NULL AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RETURN_OWMS
                             WHERE RECIEPT_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY DIVISION_ID
                                    , ITEM_ID
                                    , FROM_SITE
                                    , RECIEPT_DATE) IA) A
                 , SCM_MST_SITE B
                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
                 , SSP_MST_MODEL_USER D
                 , SSP_MST_SITE_ITEM_EE_V E
             WHERE B.DIVISION_ID = A.DIVISION_ID
               AND B.SCM_SITE_ID = A.FROM_SITE
               AND B.OPERATION_GROUP = 'E'
               AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE'                   /* LOOKUP에 등록된 공정만 */
               AND C.SEGMENT1 = A.TYPE
               AND C.VALID_YN = 'Y'
               AND D.DIVISION_ID(+) = A.DIVISION_ID
               AND D.FROM_SITE(+) = A.FROM_SITE
               AND D.ITEM_ID(+) = A.ITEM_ID
               AND D.VALID_YN(+) = 'Y'
               AND E.DIVISION_ID = A.DIVISION_ID
               AND E.SCM_SITE_ID = A.FROM_SITE
               AND E.ITEM_ID = A.ITEM_ID
               AND A.DIVISION_ID = P_DIVISION_ID
               AND (TRIM(P_COMPANY_ID) IS NULL
                OR B.COMPANY_ID = P_COMPANY_ID)
               AND (TRIM(P_FROM_SITE) IS NULL
                OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
               AND (TRIM(P_ITEM_ID) IS NULL
                OR A.ITEM_ID IN (SELECT COLUMN_VALUE
                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))
               AND (TRIM(P_TYPE) IS NULL
                OR A.TYPE IN (SELECT COLUMN_VALUE
                                FROM TABLE(STRING_SPLIT(P_TYPE, ','))))
               /* 체크박스 체크 여부 조회 시작(@p_nonChk = 'Y' : 체크박스 선택 안한 상태) */
               AND (P_NONCHK = 'Y'
                OR D.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                   FROM DUAL
                                 UNION
                                 SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN SA.USER_ID ELSE 'X' END
                                   FROM SSP_MST_DELEGATE SA
                                  WHERE SA.VALID_YN = 'Y'
                                    AND SA.DELEGATEE_ID = P_USER_ID
                                  GROUP BY SA.USER_ID)
                OR D.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                OR D.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             ORDER BY A.DIVISION_ID, A.FROM_SITE, A.YYYYMMDD, A.ITEM_ID, A.TO_SITE, C.DISPLAY_SEQ, A.CONFIRM_ID;

    END P_SSP0023_GET_SHIPMENT_PLAN_RESULT;

    PROCEDURE P_SSP0023_GET_SHIPMENT_PLAN_STOCK_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_NICK_NAME             IN  VARCHAR2
       ,P_LOT_ID                IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_MY_MODEL_CHK          IN  VARCHAR2
       ,P_DELEGATEE_CHK         IN  VARCHAR2
       ,P_PART_LEADER_CHK       IN  VARCHAR2
       ,P_TEAM_LEADER_CHK       IN  VARCHAR2
       ,P_NON_CHK               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_GET_SHIPMENT_PLAN_STOCK_DETAIL
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode) STOCK DETAIL
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-06-03   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선  최초 작성
 * 2020-06-30   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선 - operation_id ,iWMS Qty, IWMS Hold YN 추가 ,
								storage_id 변경 (변경 전 : SL.STORAGE_DESCRIPTION + ''('' + SC.STORAGE_ID+'')''	AS STORAGE_ID	)
 * 2020-07-09   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선 - NICK_NAME 조회 조건 추가
 * 2020-07-21   juhlee   		Pallet id 추가
 * 2020-07-21   KIMYONGHO   		'ELECTRODE_SHIP_STORAGE'  재고 집계 제외 대상 추가
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , B.MODEL_ID
                 , A.ITEM_ID
                 , B.ITEM_ID_NICK_NAME AS NICK_NAME
                 , A.VERSION
                 , CAST(B.LANE AS NUMBER(5, 2)) AS LANE
                 , A.LOT_ID
                 , A.PALLET_ID
                 , A.STORAGE_ID AS STORAGE_ID
                 , A.OPERATION_ID AS OPERATION_ID
                 , D.SEGMENT2 AS CHANGE_STATUS
                 , A.FROM_SITE
                 /* FLOOR - > CEILING 으로 변경 KIMYONGHO 2020-09-03 */
                 , CEIL(A.IWMS_QTY) AS IWMS_QTY_UOM
                 , CEIL(A.IWMS_QTY * NVL(B.CONVERT_TO_PCM, 1)) AS IWMS_QTY_PCM
                 , CEIL(A.GMES_QTY) AS GMES_QTY_UOM
                 , CEIL(A.GMES_QTY * NVL(B.CONVERT_TO_PCM, 1)) AS GMES_QTY_PCM
                 , CEIL(A.OWMS_QTY) AS OWMS_QTY_UOM
                 , CEIL(A.OWMS_QTY * NVL(B.CONVERT_TO_PCM, 1)) AS OWMS_QTY_PCM
                 , CEIL(A.TOT_QTY) AS TOTAL_QTY_UOM
                 , CEIL(A.TOT_QTY * NVL(B.CONVERT_TO_PCM, 1)) AS TOTAL_QTY_PCM
                 , A.AVAILABLE_YN
                 , A.IWMS_HOLD_YN
                 , A.QMS_HOLD_YN
                 , A.GMES_HOLD_YN AS MES_HOLD_YN
                 , A.OWMS_HOLD_YN
                 , A.EXPIRATION_DATE
                 , A.PACKAGE_TYPE AS PACKAGE_TYPE_CODE
              FROM SSP_ANL_STOCK_EE_C A
                 , SSP_MST_SITE_ITEM_EE_V B
                 , SCM_MST_SLOC C
                 , SCM_ADM_LOOKUP_MASTER_DETAIL D
             WHERE B.DIVISION_ID(+) = A.DIVISION_ID
               AND B.SCM_SITE_ID(+) = A.FROM_SITE
               AND B.ITEM_ID(+) = A.ITEM_ID
               AND C.PLANT_ID(+) = A.PLANT_ID
               AND C.STORAGE_ID(+) = A.STORAGE_ID
               AND C.DIVISION_ID(+) = A.DIVISION_ID
               AND D.LOOKUP_TYPE = 'MES_CHANGE_STATUS'
               AND D.VALID_YN = 'Y'
               AND D.SEGMENT1 = A.CHANGE_STATUS
               AND A.TYPE = 'E'
               AND (P_NON_CHK = 'Y'
                OR EXISTS (SELECT 1
                             FROM SSP_MST_MODEL_USER SA
                            WHERE SA.DIVISION_ID = A.DIVISION_ID
                              AND SA.FROM_SITE = A.FROM_SITE
                              AND SA.ITEM_ID = A.ITEM_ID
                              AND SA.VALID_YN = 'Y'
                              AND (SA.USER_ID IN (SELECT CASE WHEN P_MY_MODEL_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                                    FROM DUAL
                                                  UNION
                                                  SELECT CASE WHEN P_DELEGATEE_CHK = 'Y' THEN SB.USER_ID ELSE 'X' END
                                                    FROM SSP_MST_DELEGATE SB
                                                   WHERE SB.VALID_YN = 'Y'
                                                     AND SB.DELEGATEE_ID = P_USER_ID
                                                   GROUP BY SB.USER_ID)
                               OR SA.PART_LEADER = CASE WHEN P_PART_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END
                               OR SA.TEAM_LEADER = CASE WHEN P_TEAM_LEADER_CHK = 'Y' THEN P_USER_ID ELSE 'X' END)))
               AND (TRIM(P_PLAN_START_YYYYMMDD) IS NULL
                OR A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD)
               AND (TRIM(P_DIVISION_ID) IS NULL
                OR A.DIVISION_ID = P_DIVISION_ID)
               AND (TRIM(P_COMPANY_ID) IS NULL
                OR A.COMPANY_ID = P_COMPANY_ID)
               AND (TRIM(P_FROM_SITE) IS NULL
                OR A.FROM_SITE = P_FROM_SITE)
               AND (TRIM(P_ITEM_ID) IS NULL
                OR A.ITEM_ID = P_ITEM_ID)
               AND (TRIM(P_NICK_NAME) IS NULL
                OR B.ITEM_ID_NICK_NAME = P_NICK_NAME)
               AND (TRIM(P_LOT_ID) IS NULL
                OR A.LOT_ID = P_LOT_ID)
             ORDER BY A.PLANT_ID, B.MODEL_ID, A.ITEM_ID, A.LOT_ID;

    END P_SSP0023_GET_SHIPMENT_PLAN_STOCK_DETAIL;

    PROCEDURE P_SSP0023_SAVE_SHIPMENT_PLAN_SIMU
    (
        P_ACTIVE_FLAG           IN  VARCHAR2
       ,P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_PLANT_ID              IN  VARCHAR2
       ,P_SCM_SITE_ID           IN  VARCHAR2
       ,P_MODEL_ID              IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_NPC_ITEM_ID           IN  VARCHAR2
       ,P_YYYYMMDD              IN  VARCHAR2
       ,P_QTY                   IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_MEASURE               IN  VARCHAR2
       ,P_LAST_UPDATED_BY       IN  VARCHAR2
       ,P_ELECTRODE_TYPE        IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * PROGRAM ID   : SSP0023_SAVE_SHIPMENT_PLAN_SIMU
 * DESCRIPTION  : 전극 SHIPMENT PLAN(Electrode) - SIMULATION 저장
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE		DESCRIPTION
 *===================================================================================================
 * 2020-04-28   khj79			[PJ20199555] 공급 대응력 향상을 위한 자재재공 수급 점검 체계 개선  최초 작성
 * 2020-06-29   khj79			SSP_ANL_SHIP_PLAN_SIMU_EE 저장 시 사용자 입력 값 저장 되도록 수정
 * 2026.09.23   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_ACTIVE_FLAG           VARCHAR2(4000);
        V_DIVISION_ID           VARCHAR2(4000);
        V_COMPANY_ID            VARCHAR2(4000);
        V_PLANT_ID              VARCHAR2(4000);
        V_SCM_SITE_ID           VARCHAR2(4000);
        V_MODEL_ID              VARCHAR2(4000);
        V_ITEM_ID               VARCHAR2(4000);
        V_NPC_ITEM_ID           VARCHAR2(4000);
        V_YYYYMMDD              VARCHAR2(4000);
        V_QTY                   VARCHAR2(4000);
        V_PLAN_START_YYYYMMDD   VARCHAR2(4000);
        V_MEASURE               VARCHAR2(4000);
        V_LAST_UPDATED_BY       VARCHAR2(4000);
        V_ELECTRODE_TYPE        VARCHAR2(4000);
        V_DELIMITER             VARCHAR2(1) := '^';
        MAX_LOOP_CNT            NUMBER := 0;
        MST_LOOP_CNT            NUMBER := 0;
        /* SIMULATION 저장 용 변수 설정 */
        N_SIMU_SEQ              NUMBER;
        /* QTY_TO_PCM, QTY_TO_CELL 용 변수 설정 */
        V_QTY_TO_PCM            NUMBER;
        V_QTY_TO_CELL           NUMBER;
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME          VARCHAR2(150) := 'PKG_SSP0023_CHK.P_SSP0023_SAVE_SHIPMENT_PLAN_SIMU';
        V_LOG_TYPE              VARCHAR2(30);                                   /* START/END/ERROR/... */
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000);
        V_DESCRIPTION           VARCHAR2(500);
        D_EVENT_DATE            DATE;
        /* 예외처리 변수 설정 */
        V_ERR_MSG               VARCHAR2(4000);
        V_ERR_CODE              NUMBER;
    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 로그 프로시저가 자체 COMMIT 을 하므로 되돌림 지점은 그 뒤에 잡는다 */
        SAVEPOINT SP_SAVE_SIMU;

        /* 프로시저 LOOP 길이를 판단 */
        MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        MST_LOOP_CNT := 0;

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND MST_LOOP_CNT < MAX_LOOP_CNT LOOP

            /* MST_LOOP_CNT 1증가 */
            MST_LOOP_CNT := MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, MST_LOOP_CNT);
            V_COMPANY_ID := SCM_ARR_SPL_VAL(P_COMPANY_ID, V_DELIMITER, MST_LOOP_CNT);
            V_PLANT_ID := SCM_ARR_SPL_VAL(P_PLANT_ID, V_DELIMITER, MST_LOOP_CNT);
            V_SCM_SITE_ID := SCM_ARR_SPL_VAL(P_SCM_SITE_ID, V_DELIMITER, MST_LOOP_CNT);
            V_MODEL_ID := SCM_ARR_SPL_VAL(P_MODEL_ID, V_DELIMITER, MST_LOOP_CNT);
            V_ITEM_ID := SCM_ARR_SPL_VAL(P_ITEM_ID, V_DELIMITER, MST_LOOP_CNT);
            V_YYYYMMDD := SCM_ARR_SPL_VAL(P_YYYYMMDD, V_DELIMITER, MST_LOOP_CNT);
            V_QTY := SCM_ARR_SPL_VAL(P_QTY, V_DELIMITER, MST_LOOP_CNT);
            V_PLAN_START_YYYYMMDD := SCM_ARR_SPL_VAL(P_PLAN_START_YYYYMMDD, V_DELIMITER, MST_LOOP_CNT);
            V_MEASURE := SCM_ARR_SPL_VAL(P_MEASURE, V_DELIMITER, MST_LOOP_CNT);
            V_LAST_UPDATED_BY := SCM_ARR_SPL_VAL(P_LAST_UPDATED_BY, V_DELIMITER, MST_LOOP_CNT);
            V_ELECTRODE_TYPE := SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE, V_DELIMITER, MST_LOOP_CNT);

            /*// QTY_TO_PCM , QTY_TO_CELL 구하기 */
            /* AS-IS 는 대상 행이 없으면 앞 행에서 구한 값이 그대로 남는다 */
            BEGIN
                SELECT NVL(TO_NUMBER(V_QTY) * NVL(A.CONVERT_TO_PCM, 1), 0)
                     , NVL(TO_NUMBER(V_QTY) * NVL(A.CONVERT_TO_CELL, 1), 0)
                  INTO V_QTY_TO_PCM
                     , V_QTY_TO_CELL
                  FROM SSP_MST_SITE_ITEM_EE_V A
                 WHERE A.DIVISION_ID = V_DIVISION_ID
                   AND A.SCM_SITE_ID = V_SCM_SITE_ID
                   AND A.ITEM_ID = V_ITEM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            /* 데이터 저장 */
            IF MST_LOOP_CNT > 0 THEN

                /*// SIMULATION 저장 */
                N_SIMU_SEQ := SEQ1_SSP_ANL_SHIP_PLAN_SIMU_EE.NEXTVAL;

                INSERT INTO SSP_ANL_SHIP_PLAN_SIMU_EE
                (
                    SEQ
                  , COMPANY_ID
                  , DIVISION_ID
                  , PLANT_ID
                  , SCM_SITE_ID
                  , MODEL_ID
                  , ITEM_ID
                  , NPC_ITEM_ID
                  , YYYYMMDD
                  , QTY
                  , QTY_TO_CELL
                  , PLAN_START_YYYYMMDD
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                )
                SELECT N_SIMU_SEQ
                     , COMPANY_ID
                     , DIVISION_ID
                     , PLANT_ID
                     , SCM_SITE_ID
                     , MODEL_ID
                     , ITEM_ID
                     , NPC_ITEM_ID
                     , YYYYMMDD
                     , TO_NUMBER(V_QTY)
                     , V_QTY_TO_CELL
                     , PLAN_START_YYYYMMDD
                     , V_LAST_UPDATED_BY
                     , SYSDATE
                     , V_LAST_UPDATED_BY
                     , SYSDATE
                  FROM SSP_ANL_SHIP_PLAN_EE
                 WHERE PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND COMPANY_ID = V_COMPANY_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND PLANT_ID = V_PLANT_ID
                   AND SCM_SITE_ID = V_SCM_SITE_ID
                   AND MODEL_ID = V_MODEL_ID
                   AND ITEM_ID = V_ITEM_ID
                   AND MEASURE = V_MEASURE
                   AND YYYYMMDD = V_YYYYMMDD;

                /* 원문 MERGE 는 온라인 SQL 금지라 UPDATE 후 건수로 INSERT 를 가른다 */
                UPDATE SSP_ANL_SHIP_PLAN_EE
                   SET QTY = TO_NUMBER(V_QTY)
                     , QTY_TO_PCM = V_QTY_TO_PCM
                     , QTY_TO_CELL = V_QTY_TO_CELL
                     , LAST_UPDATED_BY = V_LAST_UPDATED_BY
                     , LAST_UPDATE_DATE = SYSDATE
                 WHERE PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND COMPANY_ID = V_COMPANY_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND PLANT_ID = V_PLANT_ID
                   AND SCM_SITE_ID = V_SCM_SITE_ID
                   AND MODEL_ID = V_MODEL_ID
                   AND ITEM_ID = V_ITEM_ID
                   AND MEASURE = V_MEASURE
                   AND YYYYMMDD = V_YYYYMMDD;

                IF SQL%ROWCOUNT = 0 THEN

                    INSERT INTO SSP_ANL_SHIP_PLAN_EE
                    (
                        PLAN_START_YYYYMMDD
                      , COMPANY_ID
                      , DIVISION_ID
                      , PLANT_ID
                      , SCM_SITE_ID
                      , MODEL_ID
                      , ITEM_ID
                      , NPC_ITEM_ID
                      , MEASURE_TYPE
                      , MEASURE
                      , YYYYMMDD
                      , QTY
                      , QTY_TO_PCM
                      , QTY_TO_CELL
                      , FROM_DIVISION_ID
                      , FROM_SITE
                      , TO_DIVISION_ID
                      , TO_SITE
                      , BOD_ID
                      , ELECTRODE_TYPE
                      , ETD_DATE
                      , ETA_DATE
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                    )
                    VALUES
                    (
                        V_PLAN_START_YYYYMMDD
                      , V_COMPANY_ID
                      , V_DIVISION_ID
                      , V_PLANT_ID
                      , V_SCM_SITE_ID
                      , V_MODEL_ID
                      , V_ITEM_ID
                      , NULL
                      , 'P'
                      , V_MEASURE
                      , V_YYYYMMDD
                      , TO_NUMBER(V_QTY)
                      , V_QTY_TO_PCM
                      , V_QTY_TO_CELL
                      , '-'
                      , '-'
                      , '-'
                      , '-'
                      , '-'
                      , V_ELECTRODE_TYPE
                      , '-'
                      , '-'
                      , V_LAST_UPDATED_BY
                      , SYSDATE
                      , V_LAST_UPDATED_BY
                      , SYSDATE
                    );

                END IF;

            END IF;                                                             /* END OF STMT. IF( @mst_loop_cnt > 0 ) */

        END LOOP;                                                               /* END OF STMT. WHILE LEN(@recv_active_flag) > 0 AND @mst_loop_cnt < @max_loop_cnt */

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , MAX_LOOP_CNT AS RESULT_CNT
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            /* 입력 데이타 롤백 처리 — 커서를 열기 전에 되돌린다 */
            ROLLBACK TO SP_SAVE_SIMU;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS RESULT_CNT
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERR_MESSAGE
                  FROM DUAL;

    END P_SSP0023_SAVE_SHIPMENT_PLAN_SIMU;

END PKG_SSP0023_CHK;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0023_CHK
-- ##### END PACKAGE BODY PKG_SSP0023_CHK

-- ##### START PACKAGE BODY PKG_SSP0045
CREATE OR REPLACE PACKAGE BODY PKG_SSP0045
IS
/*
 * Program ID   : PKG_SSP0045
 * Description  : SSP0045 Shipment Request SEMI
 * Program History
 *===================================================================================================
 * Date         In Charge       Description
 *===================================================================================================
 * 2026.09.29   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 : 본표 행 적재의 약칭 묶음(I)을 이번 조회 임시 테이블 품목으로 한정(결과 동일)
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          조회조건 ALL : 공장 사이트 · 품목 조건에 ALL 을 조건 없음으로 받음
 * 2026.10.08   AJS          조회조건 Model ALL : 대소문자 · 앞뒤 공백 무시, 후보 목록(V_ITEM_TAB)을 만들지 않고 조건 없음으로 받음
 *
 * 전환 기준
 *   1. AS-IS 임시 테이블 12개는 미리 만들어 둔 GT_SSP0045_* 로 옮기고 프로시저 시작에 DELETE 로 비운다.
 *   2. 피벗 칸 수가 조회 기간에 따라 달라지므로 본표 조회의 마지막 조립만 동적 SQL 을 쓴다.
 *   3. AS-IS 가 CTE(WITH)로 적던 구간은 인라인 뷰로 바꾼다.
 *   4. 정렬은 AS-IS 순서를 내는 공용 함수 FN_ASIS_SORT_KEY 를 쓴다.
 *   5. 원본 MSSQL 주석은 내용을 그대로 두고 블록 주석으로만 옮긴다.
 *   6. MSSQL 이 문자 날짜를 날짜로 바꿔 견주던 자리는 TO_DATE 로 형을 맞춘다.
 */

    /*******************************************************************************
     * P_SSP0045_GET_SHEET_CALENDAR_3SPAN
     *   AS-IS SCP0009_GET_SHEET_CALENDAR_3SPAN
     *   본표 날짜 머리글(일 · 주 · 월 세 단)
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_SHEET_CALENDAR_3SPAN
    (
        P_START_YYYYMMDD        IN  VARCHAR2
      , P_END_YYYYMMDD          IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
    BEGIN

        OPEN O_RC1 FOR
            SELECT 'D_'||BASIS_YYYYMMDD                       AS COLUMN_NAME
                 , CALENDAR_DAY                               AS COLUMN_LABEL_NAME
                 , WEEK_NAME                                  AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , DAYOFWEEK                                  AS DAY_CODE
                 , BASIS_YYYYMMDD||'31'                       AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             UNION ALL
            SELECT 'W_'||BASIS_YYYYMM||ISO_WEEK               AS COLUMN_NAME
                 , WEEK_NAME                                  AS COLUMN_LABEL_NAME
                 , WEEK_NAME                                  AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , NULL                                       AS DAY_CODE
                 , BASIS_START_DATE||'21'                     AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY BASIS_YYYYMM
                    , ISO_WEEK
                    , WEEK_NAME
                    , MONTH_NAME
                    , BASIS_START_DATE
             UNION ALL
            SELECT 'M_'||BASIS_YYYYMM                         AS COLUMN_NAME
                 , MONTH_NAME                                 AS COLUMN_LABEL_NAME
                 , MONTH_NAME                                 AS SMALL_CLASS_LABEL_NAME
                 , MONTH_NAME                                 AS LARGE_CLASS_LABEL_NAME
                 , NULL                                       AS DAY_CODE
                 , MIN(BASIS_START_DATE)||'01'                AS SORT_ORDER_NO
              FROM SCM_SYS_CALENDAR_M
             WHERE BASIS_YYYYMMDD >= P_START_YYYYMMDD
               AND BASIS_YYYYMMDD <= P_END_YYYYMMDD
             GROUP BY BASIS_YYYYMM
                    , MONTH_NAME
             ORDER BY SORT_ORDER_NO;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS COLUMN_NAME FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_SHEET_CALENDAR_3SPAN;

    /*******************************************************************************
     * P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE
     *   AS-IS SCM0002_GET_BODITEM_FOR_PRJROUTE_POPUP
     *   BOD 선택 팝업 — 품목 하나가 실려 있는 운송 경로 목록
     *
     * ★AS-IS 화면은 이 팝업을 공용 화면(SCM0002)으로 띄우면서 부모 화면 이름을 함께 넘긴다.
     *   TO-BE 기능 등록이 이 화면 이름(P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE)으로 되어 있어 이 패키지에 둔다.
     * ★P_PROGRAM_ID 는 AS-IS 도 선언만 하고 본문에서 쓰지 않는다(호출 이력 구분용).
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
        V_TO_SITE_TYPE          VARCHAR2(30 CHAR) := 'PLANT';
    BEGIN

        OPEN O_RC1 FOR
            SELECT DISTINCT
                   A.DIVISION_ID
                 , B.FROM_SITE
                 , SF.DIVISION_ID                             AS FROM_DIVISION_ID
                 , SF.SITE_TYPE                               AS FROM_SITE_TYPE
                 , SF.SITE_DESCRIPTION                        AS FROM_SITE_NAME
                 , B.TO_SITE
                 , ST.DIVISION_ID                             AS TO_DIVISION_ID
                 , ST.SITE_TYPE                               AS TO_SITE_TYPE
                 , ST.SITE_DESCRIPTION                        AS TO_SITE_NAME
                 , A.ITEM_ID
                 , A.PRIORITY
                 , A.BOD_ID
                 , B.INCOTERMS
                 , C.TRANSPORT_MODE
                 /* BOD 2단계 개발 */
                 /* ,(SELECT v.lt_total FROM scp_mst_bod_v v WHERE v.division_id = b.division_id  and v.bod_id = b.bod_id ) AS lead_time */
                 , (SELECT SA.LT_TOTAL
                      FROM SCP_MST_BOD_N_V SA
                     WHERE SA.DIVISION_ID = B.DIVISION_ID
                       AND SA.BOD_ID      = B.BOD_ID)          AS LEAD_TIME
                 , A.VALID_YN                                 AS BOD_ITEM_VALID
                 , C.ROUTE_ID
                 , C.DAYS_MON
                 , C.DAYS_TUE
                 , C.DAYS_WED
                 , C.DAYS_THU
                 , C.DAYS_FRI
                 , C.DAYS_SAT
                 , C.DAYS_SUN
                 /* Ship Frozen구간 다음일자 */
                 , TO_CHAR(TO_DATE(P_FROM_YYYYMMDD, 'YYYYMMDD') + NVL(FS.SHIP_FROZEN, 0), 'YYYYMMDD') AS FROZEN_YYYYMMDD
                 , TO_DATE(B.ATTRIBUTE2, 'YYYYMMDD')          AS BOD_FROM_YYYYMMDD    /* BOD 2단계 개발 */
                 , TO_DATE(B.ATTRIBUTE3, 'YYYYMMDD')          AS BOD_TO_YYYYMMDD      /* BOD 2단계 개발 */
              FROM SCP_MST_BOD_ITEM              A
                 , SCP_MST_BOD                   B
                 , SCM_MST_SITE                  SF
                 , SCM_MST_SITE                  ST
                 , SCP_MST_DISTRIBUTION_ROUTE    C
                 , SCM_MST_SITE                  FS
             WHERE A.BOD_ID            = B.BOD_ID
               AND SF.SCM_SITE_ID      = B.FROM_SITE
               AND ST.SCM_SITE_ID      = B.TO_SITE
               AND B.ROUTE_ID          = C.ROUTE_ID
               AND FS.DIVISION_ID      = A.DIVISION_ID
               AND FS.SCM_SITE_ID      = B.FROM_SITE
               AND SF.SITE_TYPE        = 'PLANT'
               AND SF.OPERATION_GROUP  = P_OPERATION_GROUP
               AND ST.SITE_TYPE        = V_TO_SITE_TYPE
               AND FS.SITE_TYPE        = 'PLANT'
               AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
               AND FS.OSP_YN           = 'N'
               AND FS.VALID_YN         = 'Y'
               AND B.INCOTERMS         = 'DAP'                 /* Semi 용 DAP 적용 */
               AND SF.PLANT_ID        <> ST.PLANT_ID           /* 동일 Plant 제외(A040-A -> A040-P 등) */
               AND A.DIVISION_ID       = P_DIVISION_ID
               AND A.ITEM_ID           = P_ITEM_ID
             ORDER BY BOD_ITEM_VALID DESC
                    , FN_ASIS_SORT_KEY(DIVISION_ID) NULLS FIRST
                    , FN_ASIS_SORT_KEY(FROM_SITE) NULLS FIRST
                    , FN_ASIS_SORT_KEY(TO_SITE) NULLS FIRST
                    , PRIORITY
                    , FN_ASIS_SORT_KEY(TRANSPORT_MODE) NULLS FIRST;

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_BOD_ITEM_PRJ_ROUTE;

    /*******************************************************************************
     * P_SSP0045_GET_SHIPMENT_REQUEST
     *   AS-IS SSP0045_GET_SHIPMENT_REQUEST
     *   Shipment Request 본표 (측정값 9 종 × 일 · 주 · 월 피벗)
     *
     * 측정값
     *   1 SCP_PLAN   SCP 출하계획      2 SHIP_PLAN 출하계획        3 SHIP_REQ  출하지시
     *   4 CUST_PLAN  고객 출하계획     5 CUST_REQ  고객 출하지시   6 INTN_MOVEMENT 사내 이동
     *   7 INSP_PLAN  특성 계획         8 WH_BOH_PLAN 창고 기초재고(계획)
     *   9 WH_BOH_REQ 창고 기초재고(지시)
     *
     * ★소형(40) 사업부는 사내 이동 · 특성 계획 · 재고를 SSP_ANL_SHIP_PLAN_40 에서 읽는다
     *   (AS-IS [C20201016-000147]).
     * ★피벗 칸 수가 조회 기간에 따라 달라지므로 마지막 조립만 동적 SQL 을 쓴다.
     *******************************************************************************/
    PROCEDURE P_SSP0045_GET_SHIPMENT_REQUEST
    (
        P_DIVISION_ID           IN  VARCHAR2
      , P_OPERATION_GROUP       IN  VARCHAR2
      , P_SCM_SITE_ID           IN  VARCHAR2
      , P_ITEM_ID               IN  VARCHAR2
      , P_FROM_YYYYMMDD         IN  VARCHAR2
      , P_TO_YYYYMMDD           IN  VARCHAR2
      , P_PROGRAM_ID            IN  VARCHAR2
      , P_SHEET_NAME            IN  VARCHAR2
      , P_USER_ID               IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG                   VARCHAR2(4000 CHAR);
        V_STOCK_YYYYMMDD            VARCHAR2(8 CHAR);
        V_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR);
        V_CUTOFF_START_YYYYMMDD     VARCHAR2(8 CHAR);
        V_SCP_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
        V_SCP_PLAN_TYPE             VARCHAR2(10 CHAR);
        V_SCP_SEQ                   NUMBER;
        V_APP_TYPE                  VARCHAR2(8 CHAR) := 'SSP';
        V_BASE_MONDAY_YYYYMMDD      VARCHAR2(8 CHAR);
        V_PIVOT                     CLOB;
        V_SQL                       CLOB;
        V_ITEM_TAB                  T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN

        V_PLAN_START_YYYYMMDD   := TO_CHAR(SYSDATE, 'YYYYMMDD');
        V_CUTOFF_START_YYYYMMDD := TO_CHAR(SYSDATE - 1, 'YYYYMMDD');
        V_STOCK_YYYYMMDD        := TO_CHAR(TO_DATE(P_FROM_YYYYMMDD, 'YYYYMMDD') - 3, 'YYYYMMDD');   /* FROM -3일 */

        /* SCP 계획 기준 주의 월요일에서 4주 앞 */
        V_BASE_MONDAY_YYYYMMDD  := TO_CHAR(FN_NEXT_DAY(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD'), 'MON') - 28, 'YYYYMMDD');

        /* 임시 테이블 비우기 (ON COMMIT PRESERVE ROWS 라 앞 호출 자료가 남는다) */
        DELETE FROM GT_SSP0045_SHIPMENT_PLAN_FG;
        DELETE FROM GT_SSP0045_PLAN;
        DELETE FROM GT_SSP0045_PLAN_ERP_RESULT;
        DELETE FROM GT_SSP0045_SHIP_REQ;
        DELETE FROM GT_SSP0045_SHIP_REQ_OWMS;
        DELETE FROM GT_SSP0045_FILTER;
        DELETE FROM GT_SSP0045_40_STD;
        DELETE FROM GT_SSP0045_SHIP_ROW;
        DELETE FROM GT_SSP0045_STOCK;
        DELETE FROM GT_SSP0045_CAL_QTY;
        DELETE FROM GT_SSP0045_REQUESTOR;
        DELETE FROM GT_SSP0045_SHIP_PIVOT;

        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        /* 입력값(쉼표 구분 · 빈 값 제외)이 품목 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목을 문장 밖에서 한 번 고른다
           대상 = 사업부 품목 원장(SCM_MST_ITEM_SN) 품목 + 입력값 그대로(기존 정확일치로 나오던 품목 유지) */
        /* IF TRIM(P_ITEM_ID) IS NOT NULL THEN */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname : ALL 은 후보 목록을 만들지 않고 조건 없음 */
            SELECT DISTINCT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM ( SELECT A.ITEM_ID
                       FROM SCM_MST_ITEM_SN                      A
                          , TABLE(STRING_SPLIT(P_ITEM_ID, ','))   SA
                      WHERE SA.COLUMN_VALUE IS NOT NULL
                        AND A.DIVISION_ID   = P_DIVISION_ID
                        AND (    UPPER(A.ITEM_ID)   LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%'
                              OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(SA.COLUMN_VALUE) || '%' )
                     UNION ALL
                     SELECT UPPER(SB.COLUMN_VALUE)
                       FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))   SB
                      WHERE SB.COLUMN_VALUE IS NOT NULL
                   )  IA;
        END IF;
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 최신 FN 계획 판 */
        BEGIN
            SELECT PLAN_START_YYYYMMDD
                 , PLAN_TYPE
                 , PLAN_SEQ
              INTO V_SCP_PLAN_START_YYYYMMDD
                 , V_SCP_PLAN_TYPE
                 , V_SCP_SEQ
              FROM ( SELECT PLAN_START_YYYYMMDD
                          , PLAN_TYPE
                          , PLAN_SEQ
                       FROM SCP_PLAN_VERSION_V
                      WHERE DIVISION_ID = P_DIVISION_ID
                        AND PLAN_CYCLE  = 'WEEKLY'
                        AND PLAN_TYPE   = 'FN'
                      ORDER BY PLAN_START_YYYYMMDD DESC
                             , PLAN_TYPE_ORDER DESC
                             , PLAN_SEQ DESC )  IA
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_SCP_PLAN_START_YYYYMMDD := NULL;
        END;

        /*---------------------------------------------
         * 0. SCP 출하계획(FG) 기준 자료
         *   ★AS-IS 는 B 를 LEFT JOIN 으로 적었으나 WHERE 에 B.DIVISION_ID IS NOT NULL 이 있어
         *     결과가 내부 조인과 같다. 조인 조건을 옮길 수 있도록 내부 조인으로 적는다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIPMENT_PLAN_FG
        ( DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
        , ITEM_ID, TO_SITE, INCOTERMS, FROM_SITE, BOD_ID, TRANSPORT_MODE, MEASURE, YYYYMMDD, QTY )
        SELECT DIVISION_ID
             , PLAN_START_YYYYMMDD            /* plan주의 월요일 */
             , PLAN_TYPE
             , MAX(SEQ)                                       AS SEQ
             , MAX(OPERATION_GROUP)                           AS BIZ_TYPE
             , NVL(NULLIF(RTRIM(PROJECT_CODE),''), '/')                         AS PROJECT_CODE
             , FCST_TYPE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , TRANSPORT_MODE
             , MEASURE
             , YYYYMMDD
             , SUM(QTY)                                       AS QTY
          FROM ( SELECT B.DIVISION_ID
                      , B.PLAN_START_YYYYMMDD
                      , B.PLAN_TYPE
                      , B.SEQ
                      , B.OPERATION_GROUP
                      , A.PROJECT_CODE
                      , A.FCST_TYPE
                      , B.ITEM_ID
                      , B.TO_SITE
                      /* 2020.09.18  KBK  법인간 거래 - 실제 매출 Incoterms 적용 */
                      , NVL(C.SSP_INCOTERMS, B.INCOTERMS)     AS INCOTERMS
                      , B.FROM_SITE
                      , B.BOD_ID
                      , B.TRANSPORT_MODE
                      , B.MEASURE
                      , B.YYYYMMDD
                      , A.ALLOCATION_QTY                      AS QTY
                   FROM SCP_PLN_SHIPMENT_PLAN_PEGGING  A
                      , SCP_PLN_SHIPMENT_PLAN          B
                      , SCP_MST_BOD_N_V                C
                  WHERE A.DIVISION_ID           = B.DIVISION_ID
                    AND A.PLAN_START_YYYYMMDD   = B.PLAN_START_YYYYMMDD
                    AND A.PLAN_TYPE             = B.PLAN_TYPE
                    AND A.SEQ                   = B.SEQ
                    AND A.ORDER_ID              = B.ORDER_ID
                    AND C.DIVISION_ID(+)        = B.DIVISION_ID
                    AND C.BOD_ID(+)             = B.BOD_ID
                    AND B.MEASURE               = 'SHIP_PLAN'
                    AND B.SEMI_YN               = 'N'
                    AND B.OPERATION_GROUP       = (CASE WHEN P_DIVISION_ID = '40' THEN 'A' ELSE B.OPERATION_GROUP END)
                    AND A.DIVISION_ID           = P_DIVISION_ID
                    AND A.PLAN_START_YYYYMMDD  >= V_BASE_MONDAY_YYYYMMDD
                    AND A.PLAN_TYPE             = 'FN'
                    AND B.YYYYMMDD             >= P_FROM_YYYYMMDD
                    AND B.YYYYMMDD             <= P_TO_YYYYMMDD
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR B.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR B.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR B.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
               )  XA
         GROUP BY DIVISION_ID
                , PLAN_START_YYYYMMDD
                , PLAN_TYPE
                , NVL(PROJECT_CODE, '/')
                , FCST_TYPE
                , ITEM_ID
                , TO_SITE
                , INCOTERMS
                , FROM_SITE
                , TRANSPORT_MODE
                , BOD_ID
                , MEASURE
                , YYYYMMDD;

        /*---------------------------------------------
         * 1. SCP Plan : SCP(Weekly) plant향 Shipment Plan
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , TR_MODE
             , INCOTERMS
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , PROJECT_CODE
             , FCST_TYPE
             , SEQ
          FROM ( SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , BOD.TRANSPORT_MODE                    AS TR_MODE
                      , BOD.INCOTERMS                         AS INCOTERMS
                      , BOD.BOD_ID                            AS BOD_ID     /* BOD 2단계 개발 */
                      , 'SCP_PLAN'                            AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 1                                     AS SEQ
                      , TO_DATE(SP.YYYYMMDD, 'YYYYMMDD') - TO_DATE(PV.PLAN_START_YYYYMMDD, 'YYYYMMDD')   AS DAY_GAP
                      , CASE WHEN V_SCP_PLAN_START_YYYYMMDD = PV.PLAN_START_YYYYMMDD THEN 0 ELSE 1 END   AS FLAG
                   FROM SCP_ANL_SHIPMENT_PLAN_SEMI   SP
                      , ( SELECT DIVISION_ID
                               , PLAN_START_YYYYMMDD
                               , PLAN_TYPE
                               , PLAN_SEQ
                               , PLAN_ID
                               , MODELING_ID
                               , SORT_SEQ
                               , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID
                                                    ORDER BY PLAN_START_YYYYMMDD DESC, SORT_SEQ ASC, PLAN_SEQ DESC) AS ROW_NUM
                            FROM ( SELECT DIVISION_ID
                                        , PLAN_START_YYYYMMDD
                                        , PLAN_TYPE
                                        , PLAN_SEQ
                                        , PLAN_ID
                                        , MODELING_ID
                                        , CASE WHEN PLAN_TYPE = 'PR' THEN 4
                                               WHEN PLAN_TYPE = 'MA' THEN 3
                                               WHEN PLAN_TYPE = 'SE' THEN 2
                                               WHEN PLAN_TYPE = 'FN' THEN 1
                                               ELSE 9
                                          END                                   AS SORT_SEQ
                                     FROM SCP_PLAN_VERSION_V
                                    WHERE DIVISION_ID          = P_DIVISION_ID
                                      AND PLAN_CYCLE           = 'WEEKLY'
                                      /* 191219 FN만 조회 */
                                      AND PLAN_TYPE            = 'FN'
                                      AND PLAN_START_YYYYMMDD >= V_BASE_MONDAY_YYYYMMDD
                                 )  SA
                        )  PV
                      , SCP_MST_BOD_N_V                BOD     /* BOD 2 단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
                      , SCM_MST_SITE                   FS
                      , SCM_MST_SITE                   TS
                  WHERE SP.DIVISION_ID          = PV.DIVISION_ID
                    AND SP.PLAN_START_YYYYMMDD  = PV.PLAN_START_YYYYMMDD
                    AND SP.PLAN_TYPE            = PV.PLAN_TYPE
                    AND SP.SEQ                  = PV.PLAN_SEQ
                    AND SP.DIVISION_ID          = BOD.DIVISION_ID
                    AND SP.BOD_ID               = BOD.BOD_ID
                    AND FS.DIVISION_ID          = SP.DIVISION_ID
                    AND FS.SCM_SITE_ID          = SP.FROM_SITE
                    AND TS.DIVISION_ID          = SP.DIVISION_ID
                    AND TS.SCM_SITE_ID          = SP.TO_SITE
                    AND SP.MEASURE              = 'SHIP_PLAN_AMEND'
                    AND SP.QTY                  > 0
                    AND SP.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND SP.YYYYMMDD            >= P_FROM_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND FS.VALID_YN             = 'Y'
                    AND TS.VALID_YN             = 'Y'
                    AND FS.PLANT_ID            <> TS.PLANT_ID
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                 UNION ALL
                 /* AS(Warranty Service) 적용 */
                 SELECT Y.DIVISION_ID
                      , Y.ITEM_ID
                      , Z.FROM_SITE
                      , Z.TO_SITE
                      , Z.TRANSPORT_MODE                      AS TR_MODE
                      , Z.INCOTERMS
                      , Z.BOD_ID
                      , 'SCP_PLAN'                            AS MEASURE
                      , Y.YYYYMMDD
                      , Y.QTY
                      , Y.PROJECT_CODE
                      , Y.FCST_TYPE
                      , 1                                     AS SEQ
                      , TO_DATE(Y.YYYYMMDD, 'YYYYMMDD') - TO_DATE(Y.PLAN_START_YYYYMMDD, 'YYYYMMDD')     AS DAY_GAP
                      , CASE WHEN V_SCP_PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD THEN 0 ELSE 1 END    AS FLAG
                   FROM ( SELECT X.DIVISION_ID
                               , X.ITEM_ID
                               , X.FROM_SITE
                               , X.TO_SITE
                               , X.PROJECT_CODE
                               , X.FCST_TYPE
                               , ( SELECT BOD_ID
                                     FROM ( SELECT BOD_ID
                                              FROM SCP_MST_BOD_N_V
                                             WHERE DIVISION_ID     = X.DIVISION_ID
                                               AND FROM_SITE       = X.FROM_SITE
                                               AND TO_SITE         = X.TO_SITE
                                               AND INCOTERMS       = X.INCOTERMS
                                               AND TRANSPORT_MODE  = X.TRANSPORT_MODE
                                               AND X.YYYYMMDD      BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD
                                               AND BOD_VALID_YN    = 'Y'
                                             ORDER BY PRIORITY )  SA
                                    WHERE ROWNUM = 1 )         AS BOD_ID   /* new bod for plant type */
                               , X.YYYYMMDD
                               , X.QTY
                               , X.PLAN_START_YYYYMMDD
                            FROM ( SELECT SP.DIVISION_ID
                                        , SP.ITEM_ID
                                        , SP.FROM_SITE
                                        , SP.PROJECT_CODE
                                        , SP.FCST_TYPE
                                        , L.SEGMENT2                        AS TO_SITE
                                        , BOD.TRANSPORT_MODE                AS TRANSPORT_MODE
                                        , BOD.INCOTERMS                     AS INCOTERMS
                                        , CASE WHEN BOD.SEGMENT3 = 'A' THEN SP.YYYYMMDD
                                               ELSE TO_CHAR(TO_DATE(SP.YYYYMMDD, 'YYYYMMDD') + BOD.BEFORE_LT, 'YYYYMMDD')
                                          END                               AS YYYYMMDD
                                        , SP.QTY
                                        , 1                                 AS SEQ
                                        , SP.PLAN_START_YYYYMMDD
                                     FROM GT_SSP0045_SHIPMENT_PLAN_FG       SP
                                        , SCP_MST_BOD_N_V                   BOD
                                        , SCM_MST_SITE                      FS
                                        , SCM_ADM_LOOKUP_MASTER_DETAIL      L
                                        , SCM_MST_SITE                      TS
                                    WHERE SP.DIVISION_ID       = BOD.DIVISION_ID
                                      AND SP.BOD_ID            = BOD.BOD_ID
                                      AND FS.DIVISION_ID       = SP.DIVISION_ID
                                      AND FS.SCM_SITE_ID       = SP.FROM_SITE
                                      AND L.SEGMENT1           = SP.TO_SITE
                                      AND L.SEGMENT3           = SP.DIVISION_ID
                                      AND TS.DIVISION_ID       = SP.DIVISION_ID
                                      AND TS.SCM_SITE_ID       = L.SEGMENT2
                                      AND FS.VALID_YN          = 'Y'
                                      AND FS.SITE_TYPE         = 'PLANT'
                                      AND FS.OPERATION_GROUP   = 'P'
                                      AND L.LOOKUP_TYPE        = 'AS_SITE_PLANT'
                                      AND L.VALID_YN           = 'Y'
                                      AND TS.SITE_TYPE         = 'PLANT'
                                      AND TS.OPERATION_GROUP   = 'W'
                                      AND TS.VALID_YN          = 'Y'
                                      AND VALIDATE_CONVERSION(SP.YYYYMMDD AS DATE, 'YYYYMMDD') = 1
                                 )  X
                        )  Y
                      , SCP_MST_BOD_N_V                Z
                  WHERE Y.BOD_ID = Z.BOD_ID
               )  AA
         WHERE ( AA.FLAG = 0 OR ( AA.FLAG = 1 AND AA.DAY_GAP < 7 ) );

        /*---------------------------------------------
         * 2. Ship Plan : SSP(Daily) Plant향 Shipment Plan
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT SSP.DIVISION_ID
             , SSP.ITEM_ID
             , SSP.FROM_SITE
             , SSP.TO_SITE
             , BOD.TRANSPORT_MODE                             AS TR_MODE
             , BOD.INCOTERMS                                  AS INCOTERMS
             , BOD.BOD_ID                                     AS BOD_ID      /* BOD 2단계 개발 */
             , 'SHIP_PLAN'                                    AS MEASURE
             , SSP.YYYYMMDD
             , SSP.QTY
             , SSP.PROJECT_CODE
             , SSP.FCST_TYPE
             , 2                                              AS SEQ
          FROM SSP_ANL_SHIP_CONFIRM        SSP
             , SCP_MST_BOD_N_V             BOD                /* BOD 2 단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
             , SCM_MST_SITE                TS
             , SCM_MST_SITE                FS
         WHERE SSP.DIVISION_ID       = BOD.DIVISION_ID
           AND SSP.BOD_ID            = BOD.BOD_ID
           AND TS.DIVISION_ID        = SSP.DIVISION_ID
           AND TS.SCM_SITE_ID        = SSP.TO_SITE
           AND FS.DIVISION_ID        = SSP.DIVISION_ID
           AND FS.SCM_SITE_ID        = SSP.FROM_SITE
           AND TS.SITE_TYPE          = 'PLANT'
           AND TS.VALID_YN           = 'Y'
           AND FS.VALID_YN           = 'Y'
           AND TS.PLANT_ID          <> FS.PLANT_ID
           AND SSP.DIVISION_ID       = P_DIVISION_ID
           AND SSP.QTY               > 0
           AND SSP.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
           AND SSP.YYYYMMDD         <= P_TO_YYYYMMDD
           AND SSP.BIZ_TYPE          = P_OPERATION_GROUP
           AND SSP.CHANGE_TYPE       = 'C'
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR SSP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR SSP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 2-1. ERP 출하실적
         *   ★AS-IS 가 CTE 두 벌(RESULT_ERP_C_EXIST · RESULT_ERP_C_NON)로 적던 구간을 인라인 뷰로 옮긴다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_PLAN_ERP_RESULT
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE                                    AS FROM_SITE
             , A.TO_SITE                                      AS TO_SITE
             , B.TR_MODE                                      AS TR_MODE
             , B.INCOTERMS                                    AS INCOTERMS
             , B.BOD_ID                                       AS BOD_ID
             , 'SHIP_PLAN'                                    AS MEASURE
             , A.YYYYMMDD                                     AS YYYYMMDD
             , A.QTY                                          AS QTY
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.FCST_TYPE                                    AS FCST_TYPE
             , 2                                              AS SEQ
          FROM ( /* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                 SELECT E.DIVISION_ID                         AS DIVISION_ID
                      , E.ITEM_ID                             AS ITEM_ID
                      , E.FROM_SCM_SITE_ID                    AS FROM_SITE
                      , E.TO_SCM_SITE_ID                      AS TO_SITE
                      , E.TRANSPORT_MODE                      AS TRANSPORT_MODE
                      /* E.INCOTERMS 대신 INCOTERMS는 DAP로 통일 */
                      , 'DAP'                                 AS INCOTERMS
                      , P.BOD_ID                              AS BOD_ID
                      , E.EXFACTORY_DATE                      AS YYYYMMDD
                      , SUM(E.EXFACTORY_QTY)                  AS QTY
                      , P.PROJECT_CODE                        AS PROJECT_CODE
                      , P.FCST_TYPE                           AS FCST_TYPE
                   FROM SCM_DNM_EXFACTORY_RESULT       E
                      , SCM_MST_SITE                   TS
                      , SCM_MST_SITE                   FS
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L
                      , SSP_ANL_SHIP_CONFIRM           P
                  WHERE E.DIVISION_ID          = TS.DIVISION_ID
                    AND E.TO_SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND E.DIVISION_ID          = FS.DIVISION_ID
                    AND E.FROM_SCM_SITE_ID     = FS.SCM_SITE_ID
                    AND L.SEGMENT1             = E.SSP_TYPE
                    AND P.DIVISION_ID          = E.DIVISION_ID
                    AND P.CONFIRM_ID           = E.CONFIRM_ID
                    AND TS.SITE_TYPE           = 'PLANT'
                    AND TS.VALID_YN            = 'Y'
                    AND TS.OPERATION_GROUP    <> 'E'
                    AND FS.VALID_YN            = 'Y'
                    AND FS.OPERATION_GROUP    <> 'E'
                    AND L.LOOKUP_TYPE          = 'ERP_SSP_TYPE'    /* LOOKUP에 등록된 공정만 */
                    AND L.VALID_YN             = 'Y'
                    AND P.YYYYMMDD             BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    /* D90: DO삭제 , D10:DO생성 */
                    AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
                    AND E.CONFIRM_ID           LIKE 'C%'
                    AND E.EXFACTORY_DATE       BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR E.FROM_SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR E.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR E.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  GROUP BY E.DIVISION_ID
                         , E.CONFIRM_ID
                         , E.ORDER_NO
                         , E.EXFACTORY_DATE
                         , E.TRANSPORT_MODE
                         , E.INCOTERMS
                         , P.BOD_ID
                         , P.FCST_TYPE
                         , P.PROJECT_CODE
                         , E.ETA_DATE
                         , E.ETD_DATE
                         , E.FROM_SCM_SITE_ID
                         , E.TO_SCM_SITE_ID
                         , E.ITEM_ID
                 UNION ALL
                 /* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
                 SELECT E.DIVISION_ID                         AS DIVISION_ID
                      , E.ITEM_ID                             AS ITEM_ID
                      , E.FROM_SCM_SITE_ID                    AS FROM_SITE
                      , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)    AS TO_SITE
                      , E.TRANSPORT_MODE                      AS TRANSPORT_MODE
                      /* E.INCOTERMS 대신 INCOTERMS는 DAP로 통일 */
                      , 'DAP'                                 AS INCOTERMS
                      , V.BOD_ID                              AS BOD_ID
                      , E.EXFACTORY_DATE                      AS YYYYMMDD
                      , SUM(E.EXFACTORY_QTY)                  AS QTY
                      , E.PROJECT_CODE                        AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                   FROM SCM_DNM_EXFACTORY_RESULT       E
                      , SCM_MST_SITE                   TS
                      , SCM_MST_SITE                   FS
                      , SCP_MST_BOD_N_V                V
                      , SCP_MST_FINAL_ITEM             F
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L
                      , SCM_ADM_LOOKUP_MASTER_DETAIL   L3
                  WHERE E.DIVISION_ID          = TS.DIVISION_ID
                    AND E.TO_SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND E.DIVISION_ID          = FS.DIVISION_ID
                    AND E.FROM_SCM_SITE_ID     = FS.SCM_SITE_ID
                    AND V.DIVISION_ID          = E.DIVISION_ID
                    AND V.FROM_SITE            = E.FROM_SCM_SITE_ID
                    AND V.TO_SITE              = E.TO_SCM_SITE_ID
                    AND V.INCOTERMS            = E.INCOTERMS
                    AND V.TRANSPORT_MODE       = E.TRANSPORT_MODE
                    AND V.FROM_YYYYMMDD       >= E.EXFACTORY_DATE
                    AND V.TO_YYYYMMDD         <= E.EXFACTORY_DATE
                    AND F.ITEM_ID              = E.ITEM_ID     /* SCP 대상 ITEM만 */
                    AND F.DIVISION_ID          = E.DIVISION_ID
                    AND L.SEGMENT1             = E.ORDER_TYPE_CODE
                    AND L3.SEGMENT1(+)         = E.DIVISION_ID
                    AND L3.SEGMENT2(+)         = E.SOLDTO_CODE
                    AND L3.SEGMENT3(+)         = E.SHIPTO_CODE
                    /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                    AND L3.LOOKUP_TYPE(+)      = 'SHIP_RESULT_TO_SITE_MAPPING'
                    AND TS.SITE_TYPE           = 'PLANT'
                    AND TS.VALID_YN            = 'Y'
                    AND TS.OPERATION_GROUP    <> 'E'
                    AND FS.VALID_YN            = 'Y'
                    AND FS.OPERATION_GROUP    <> 'E'
                    /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                    AND L.LOOKUP_TYPE          = 'ERP_ORDER_TYPE'
                    AND L.VALID_YN             = 'Y'
                    /* D90: DO삭제 , D10:DO생성 */
                    AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')
                    AND E.EXFACTORY_DATE       BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
                    /* 상품창고제외 */
                    AND E.STORAGE_ID NOT IN (SELECT COLUMN_VALUE
                                               FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0045_GET_SHIPMENT_REQUEST', 'PRODUCT_STORAGE')))
                    /* 사외 창고 제외 LOOKUP 관리 */
                    AND NOT EXISTS (SELECT 1
                                      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                     WHERE LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                       AND VALID_YN    = 'Y'
                                       AND SEGMENT1    = E.STORAGE_ID)
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR E.FROM_SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR E.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR E.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  GROUP BY E.DIVISION_ID
                         , E.ORDER_NO
                         , E.FROM_SCM_SITE_ID
                         , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)
                         , E.ITEM_ID
                         , E.EXFACTORY_DATE
                         , E.TRANSPORT_MODE
                         , E.INCOTERMS
                         , V.BOD_ID
                         , E.PROJECT_CODE
                         , E.ETA_DATE
                         , E.ETD_DATE
               )  A
             , ( SELECT DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , MAX(TR_MODE)                          AS TR_MODE
                      , MAX(INCOTERMS)                        AS INCOTERMS
                      , MAX(BOD_ID)                           AS BOD_ID
                      , MAX(PROJECT_CODE)                     AS PROJECT_CODE
                      , MAX(FCST_TYPE)                        AS FCST_TYPE
                   FROM GT_SSP0045_PLAN
                  GROUP BY DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE )  B
         WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
           AND A.FROM_SITE     = B.FROM_SITE(+)
           AND A.TO_SITE       = B.TO_SITE(+)
           AND A.ITEM_ID       = B.ITEM_ID(+);

        /*---------------------------------------------
         * 3. Ship Req : 출하 요청(Plant향 Ship Req)
         *               DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ'
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_REQ
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, RN, FROZEN_YYYYMMDD )
        SELECT R.DIVISION_ID
             , R.ITEM_ID
             , R.PLANT_SITE_ID                                AS FROM_SITE
             , R.SCM_SITE_ID                                  AS TO_SITE
             , R.TRANSPORT_MODE                               AS TR_MODE
             , R.INCOTERMS                                    AS INCOTERMS
             , R.BOD_ID                                       AS BOD_ID      /* BOD 2단계 개발 */
             , 'SHIP_REQ'                                     AS MEASURE
             , R.YYYYMMDD
             , R.QTY
             , R.PROJECT_CODE
             , R.FCST_TYPE
             , 3                                              AS SEQ
             , R.LAST_UPDATED_BY
             , RANK() OVER (PARTITION BY R.DIVISION_ID, R.ITEM_ID, R.PLANT_SITE_ID, R.SCM_SITE_ID
                                       , R.TRANSPORT_MODE, R.INCOTERMS
                            ORDER BY R.LAST_UPDATE_DATE DESC) AS RN
             /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]) */
             /* Ship Frozen구간 다음일자 */
             , TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                       + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, R.DIVISION_ID, R.PLANT_SITE_ID, V_PLAN_START_YYYYMMDD)
                       , 'YYYYMMDD')                          AS FROZEN_YYYYMMDD
          FROM DM_PLN_SHIPMENT_REQ         R
             , SCM_MST_SITE                FS
             , SCM_MST_SITE                TS
         WHERE R.DIVISION_ID       = FS.DIVISION_ID
           AND R.PLANT_SITE_ID     = FS.SCM_SITE_ID
           AND R.DIVISION_ID       = TS.DIVISION_ID
           AND R.SCM_SITE_ID       = TS.SCM_SITE_ID
           AND FS.SITE_TYPE        = 'PLANT'
           AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
           /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
           AND FS.VALID_YN         = 'Y'
           AND TS.SITE_TYPE        = 'PLANT'
           AND TS.VALID_YN         = 'Y'
           AND TS.PLANT_ID        <> FS.PLANT_ID
           AND R.DIVISION_ID       = P_DIVISION_ID
           AND R.MEASURE           = 'SHIP_REQ'               /* 확정 후 수정할 것 */
           AND R.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
           AND R.YYYYMMDD         <= P_TO_YYYYMMDD
           AND R.QTY               > 0
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR R.PLANT_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR R.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 3-1. OWMS 출하실적
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_REQ_OWMS
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE
        , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ, LAST_UPDATED_BY, RN, FROZEN_YYYYMMDD )
        SELECT O.DIVISION_ID
             , O.ITEM_ID
             , O.FROM_SITE
             , O.TO_SITE
             , R.TR_MODE
             , R.INCOTERMS
             , R.BOD_ID
             , 'SHIP_REQ'                                     AS MEASURE
             , O.YYYYMMDD
             , O.QTY
             , R.PROJECT_CODE
             , R.FCST_TYPE
             , 3                                              AS SEQ
             , '-'                                            AS LAST_UPDATED_BY
             , '-'                                            AS RN
             /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
             /* Ship Frozen구간 다음일자 */
             , TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                       + FN_GET_ANL_SHIP_FROZEN_DAY_CNT('SSP', MS.DIVISION_ID, MS.SCM_SITE_ID, V_PLAN_START_YYYYMMDD)
                       , 'YYYYMMDD')                          AS FROZEN_YYYYMMDD
          FROM SSP_DNM_SHIP_RESULT_OWMS_V   O
             , SCM_MST_SITE                 MS
             , SCM_ADM_LOOKUP_MASTER_DETAIL L
             , SCM_MST_SITE                 FS
             , SCM_MST_SITE                 TS
             , ( SELECT DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                      , TO_SITE
                      , MAX(TR_MODE)                          AS TR_MODE
                      , MAX(INCOTERMS)                        AS INCOTERMS
                      , MAX(BOD_ID)                           AS BOD_ID
                      , MAX(PROJECT_CODE)                     AS PROJECT_CODE
                      , MAX(FCST_TYPE)                        AS FCST_TYPE
                   FROM GT_SSP0045_SHIP_REQ
                  GROUP BY DIVISION_ID
                         , ITEM_ID
                         , FROM_SITE
                         , TO_SITE )  R
         WHERE MS.DIVISION_ID      = O.DIVISION_ID
           AND MS.SCM_SITE_ID      = O.FROM_SITE
           AND O.DIVISION_ID       = FS.DIVISION_ID
           AND O.FROM_SITE         = FS.SCM_SITE_ID
           AND O.DIVISION_ID       = TS.DIVISION_ID
           AND O.TO_SITE           = TS.SCM_SITE_ID
           AND R.DIVISION_ID(+)    = O.DIVISION_ID
           AND R.FROM_SITE(+)      = O.FROM_SITE
           AND R.TO_SITE(+)        = O.TO_SITE
           AND R.ITEM_ID(+)        = O.ITEM_ID
           AND MS.OPERATION_GROUP <> 'E'
           AND L.LOOKUP_TYPE       = 'SSP_SHIPMENT_RESULT_TYPE'   /* LOOKUP에 등록된 공정만 */
           AND L.SEGMENT1          = 'O'
           AND L.VALID_YN          = 'Y'
           AND FS.SITE_TYPE        = 'PLANT'
           AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
           AND FS.VALID_YN         = 'Y'
           AND TS.SITE_TYPE        = 'PLANT'
           AND TS.OPERATION_GROUP <> 'E'
           AND TS.VALID_YN         = 'Y'
           AND O.YYYYMMDD          BETWEEN P_FROM_YYYYMMDD AND V_CUTOFF_START_YYYYMMDD
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR O.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR O.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR O.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 3-2. 필터
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_FILTER
        ( DIVISION_ID, ITEM_ID, FROM_SITE )
        SELECT DISTINCT
               DIVISION_ID
             , ITEM_ID
             , FROM_SITE
          FROM ( SELECT DISTINCT
                        DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                   FROM GT_SSP0045_PLAN
                  UNION
                 SELECT DISTINCT
                        DIVISION_ID
                      , ITEM_ID
                      , FROM_SITE
                   FROM GT_SSP0045_SHIP_REQ )  A;

        /*---------------------------------------------
         * 3-3. [C20201016-000147] : 소형(40) 사업부 조회를 위한 기준 테이블 생성
         *      SSP_ANL_SHIP_PLAN_40 의 데이터 생성 시점이 달라 최신 생성 날짜를 조회한다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_40_STD
        ( DIVISION_ID, FROM_SITE, PLAN_START_YYYYMMDD )
        SELECT DISTINCT
               DIVISION_ID
             , FROM_SITE
             , PLAN_START_YYYYMMDD
          FROM ( SELECT SP.DIVISION_ID
                      , SP.FROM_SITE
                      , SP.PLAN_START_YYYYMMDD
                      , RANK() OVER (PARTITION BY SP.FROM_SITE ORDER BY SP.PLAN_START_YYYYMMDD DESC)  AS RANK_NO
                   FROM GT_SSP0045_FILTER         X1
                      , SSP_ANL_SHIP_PLAN_40      SP
                  WHERE X1.DIVISION_ID       = SP.DIVISION_ID
                    AND X1.FROM_SITE         = SP.FROM_SITE
                    AND X1.ITEM_ID           = SP.ITEM_ID
                    AND SP.DIVISION_ID       = P_DIVISION_ID
                    AND SP.PLAN_START_YYYYMMDD >= TO_CHAR(SYSDATE - 1, 'YYYYMMDD')      /* 전일 */
                    AND SP.PLAN_START_YYYYMMDD <= TO_CHAR(SYSDATE, 'YYYYMMDD')          /* 당일 */
                    AND SP.MEASURE           IN ('POSTP_PLAN', 'WH_IN', 'WH_STOCK')
                    AND SP.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD         <= P_TO_YYYYMMDD
                    AND SP.QTY               > 0
                    AND SP.DIVISION_ID       = '40'
               )  A
         WHERE RANK_NO = 1;

        /*---------------------------------------------
         * 4. ROW DATA 생성
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT TOT.DIVISION_ID
             , TOT.ITEM_ID
             , MAX(NVL(I.NICK_NAME, ' '))                     AS NICK_NAME
             , TOT.FROM_SITE
             , TOT.TO_SITE
             , TOT.TR_MODE
             , TOT.INCOTERMS
             , TOT.BOD_ID                                     AS BOD_ID      /* BOD 2단계 개발 */
             , TO_CHAR(MAX(NVL(BOD.LT_TOTAL, 0)))             AS LT_DAY
             , TOT.MEASURE
             , TOT.YYYYMMDD
             /* ★AS-IS 는 이 UNION ALL 에 소수 자리가 0 인 특성계획 수량(NUMERIC(38,0))이 섞여 있어
                MSSQL 이 묶음 전체의 소수 자리를 0 으로 정한다. 그 결과 모든 갈래의 수량이
                행 단위로 반올림된 뒤 합산된다(실측 : 24043.41192 -> 24043 · 48086.82336 -> 48087).
                TO-BE 의 NUMBER 에는 그 제약이 없으므로 같은 값을 내려면 반올림을 그대로 둔다 */
             , SUM(ROUND(TOT.QTY, 0))                         AS QTY
             , TOT.PROJECT_CODE
             , TOT.FCST_TYPE
             , TOT.SEQ
          FROM ( /* 1.SCP PLAN & 2.SHIP PLAN 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ
                   FROM GT_SSP0045_PLAN_ERP_RESULT
                  UNION ALL
                 /* 1.SCP PLAN & 2.SHIP PLAN 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ
                   FROM GT_SSP0045_PLAN
                  UNION ALL
                 /* 2.SHIP PLAN 추가 - Ship Frozen 이후 구간은 Ship Req의 수량을 더해준다. */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , 'SHIP_PLAN'                           AS MEASURE
                      , YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 2                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ
                  WHERE YYYYMMDD >= FROZEN_YYYYMMDD
                  UNION ALL
                 /* 3.SHIP REQ 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 3                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ_OWMS
                  UNION ALL
                 /* 3.SHIP REQ 추가 */
                 SELECT DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
                      , MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE
                      , 3                                     AS SEQ
                   FROM GT_SSP0045_SHIP_REQ
                  UNION ALL
                 /*---------------------------------------------
                  * 4. Customer Plan : SSP(Daily) From Plant 기준 Sales향 Shipment Plan
                  *---------------------------------------------*/
                 SELECT SSP.DIVISION_ID
                      , SSP.ITEM_ID
                      , SSP.FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'CUST_PLAN'                           AS MEASURE
                      , SSP.YYYYMMDD
                      , SSP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 4                                     AS SEQ
                   FROM SSP_ANL_SHIP_CONFIRM      SSP
                      , SCP_MST_BOD_N_V           BOD         /* BOD 2단계 개발 : scp_mst_bod_v -> scp_mst_bod_n_v */
                      , SCM_MST_SITE              TS
                      , GT_SSP0045_FILTER         F
                  WHERE SSP.DIVISION_ID     = BOD.DIVISION_ID
                    AND SSP.BOD_ID          = BOD.BOD_ID
                    AND SSP.DIVISION_ID     = TS.DIVISION_ID
                    AND SSP.TO_SITE         = TS.SCM_SITE_ID
                    AND SSP.DIVISION_ID     = F.DIVISION_ID
                    AND SSP.ITEM_ID         = F.ITEM_ID
                    AND SSP.FROM_SITE       = F.FROM_SITE
                    AND TS.SITE_TYPE        = 'SALES'
                    AND TS.VALID_YN         = 'Y'
                    AND SSP.DIVISION_ID     = P_DIVISION_ID
                    AND SSP.QTY             > 0
                    AND SSP.YYYYMMDD       >= V_PLAN_START_YYYYMMDD
                    AND SSP.YYYYMMDD       <= P_TO_YYYYMMDD
                    AND SSP.BIZ_TYPE        = P_OPERATION_GROUP
                    AND SSP.CHANGE_TYPE     = 'C'
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SSP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SSP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SSP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 5. Customer Req : 출하 요청(From Plant 기준 Sales향 Ship Req)
                  *                   DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ'
                  *---------------------------------------------*/
                 SELECT R.DIVISION_ID
                      , R.ITEM_ID
                      , R.PLANT_SITE_ID                       AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'CUST_REQ'                            AS MEASURE
                      , R.YYYYMMDD
                      , R.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 5                                     AS SEQ
                   FROM DM_PLN_SHIPMENT_REQ       R
                      , SCM_MST_SITE              FS
                      , SCM_MST_SITE              TS
                      , GT_SSP0045_FILTER         F
                  WHERE R.DIVISION_ID       = FS.DIVISION_ID
                    AND R.PLANT_SITE_ID     = FS.SCM_SITE_ID
                    AND R.DIVISION_ID       = TS.DIVISION_ID
                    AND R.SCM_SITE_ID       = TS.SCM_SITE_ID
                    AND R.DIVISION_ID       = F.DIVISION_ID
                    AND R.ITEM_ID           = F.ITEM_ID
                    AND R.PLANT_SITE_ID     = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND TS.SITE_TYPE        = 'SALES'
                    AND TS.VALID_YN         = 'Y'
                    AND R.DIVISION_ID       = P_DIVISION_ID
                    AND R.MEASURE           = 'SHIP_REQ'
                    AND R.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                    AND R.YYYYMMDD         <= P_TO_YYYYMMDD
                    AND R.QTY               > 0
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR R.PLANT_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR R.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR R.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 6. Internal movement
                  *---------------------------------------------*/
                 SELECT P.DIVISION_ID
                      , P.ITEM_ID
                      , FS.SCM_SITE_ID                        AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INTN_MOVEMENT'                       AS MEASURE
                      , TO_CHAR(P.PLAN_DATE, 'YYYYMMDD')      AS YYYYMMDD
                      , P.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 6                                     AS SEQ
                   FROM SCM_DNM_CELL_INHOUSE_PLAN_SN   P
                      , SCM_MST_SITE                   FS
                      , GT_SSP0045_FILTER              F
                  WHERE P.DIVISION_ID       = FS.DIVISION_ID
                    AND P.PLANT_ID          = FS.PLANT_ID
                    AND P.DIVISION_ID       = F.DIVISION_ID
                    AND P.ITEM_ID           = F.ITEM_ID
                    AND FS.SCM_SITE_ID      = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND P.DIVISION_ID       = P_DIVISION_ID
                    AND P.CATEGORY          = 'MOVING'
                    AND P.PLAN_DATE        >= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                    AND P.PLAN_DATE        <= TO_DATE(P_TO_YYYYMMDD, 'YYYYMMDD')
                    AND P.QTY               > 0
                    AND P.DIVISION_ID      <> '40'            /* [C20201016-000147] : 소형(40) 제외,KHJ79 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR FS.SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR P.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR P.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /* [C20201016-000147] : 소형(40) 사업부 추가, KHJ79 */
                 SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , SP.TRANSPORT_MODE                     AS TR_MODE
                      , SP.INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INTN_MOVEMENT'                       AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 6                                     AS SEQ
                   FROM SSP_ANL_SHIP_PLAN_40        SP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                      , GT_SSP0045_40_STD           ST
                  WHERE SP.DIVISION_ID          = FS.DIVISION_ID
                    AND SP.FROM_SITE            = FS.SCM_SITE_ID
                    AND SP.DIVISION_ID          = F.DIVISION_ID
                    AND SP.ITEM_ID              = F.ITEM_ID
                    AND SP.FROM_SITE            = F.FROM_SITE
                    AND ST.DIVISION_ID          = SP.DIVISION_ID
                    AND ST.FROM_SITE            = SP.FROM_SITE
                    AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
                    AND FS.SITE_TYPE            = 'PLANT'
                    /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
                    AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND FS.VALID_YN             = 'Y'
                    AND SP.MEASURE              = 'POSTP_PLAN'
                    AND SP.DIVISION_ID          = P_DIVISION_ID
                    AND SP.YYYYMMDD            >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND SP.QTY                  > 0
                    AND SP.DIVISION_ID          = '40'        /* 소형(40) 인 경우만 조회 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /*---------------------------------------------
                  * 7. Inspection plan : FP 특성계획
                  *---------------------------------------------*/
                 SELECT FP.DIVISION_ID
                      , FP.ITEM_ID
                      , FP.SCM_SITE_ID                        AS FROM_SITE
                      , '-'                                   AS TO_SITE
                      , '-'                                   AS TR_MODE
                      , '-'                                   AS INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INSP_PLAN'                           AS MEASURE
                      , TO_CHAR(FP.PLAN_DATE, 'YYYYMMDD')     AS YYYYMMDD
                      , FP.PLAN_QTY                           AS QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 7                                     AS SEQ
                   FROM SCM_DNM_PLAN_FROZEN_V       FP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                  WHERE FP.DIVISION_ID      = FS.DIVISION_ID
                    AND FP.SCM_SITE_ID      = FS.SCM_SITE_ID
                    AND FP.DIVISION_ID      = F.DIVISION_ID
                    AND FP.ITEM_ID          = F.ITEM_ID
                    AND FP.SCM_SITE_ID      = F.FROM_SITE
                    AND FS.SITE_TYPE        = 'PLANT'
                    AND FS.OPERATION_GROUP  = P_OPERATION_GROUP
                    /* 2021.10.21 : W/S AS 수정 , OSP_YN 조건 제거 */
                    AND FS.VALID_YN         = 'Y'
                    AND FP.DIVISION_ID      = P_DIVISION_ID
                    AND FP.PLAN_DATE       >= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                    AND FP.PLAN_DATE       <= TO_DATE(P_TO_YYYYMMDD, 'YYYYMMDD')
                    AND FP.PLAN_QTY         > 0
                    AND FP.PLAN_IN_QTY      > 0
                    /* (참고) division_id <> '40' 일때는 'F6000' 데이터만 존재하므로 operation_id 조건에'F5300', 'F5500', 'F5600' 도 포함시켜도 상관없음 */
                    AND FP.OPERATION_ID IN (SELECT SEGMENT1
                                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                             WHERE LOOKUP_TYPE = 'OPERATION_CHAR'
                                               AND VALID_YN    = 'Y')
                    AND FP.DIVISION_ID     <> '40'            /* C20201016-000147 : 소형(40) 제외,KHJ79 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR FP.SCM_SITE_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR FP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR FP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                  UNION ALL
                 /* [C20201016-000147] : 소형(40) 사업부 추가, KHJ79 */
                 SELECT SP.DIVISION_ID
                      , SP.ITEM_ID
                      , SP.FROM_SITE
                      , SP.TO_SITE
                      , SP.TRANSPORT_MODE                     AS TR_MODE
                      , SP.INCOTERMS
                      , '-'                                   AS BOD_ID      /* BOD 2단계 개발 */
                      , 'INSP_PLAN'                           AS MEASURE
                      , SP.YYYYMMDD
                      , SP.QTY
                      , '-'                                   AS PROJECT_CODE
                      , '-'                                   AS FCST_TYPE
                      , 7                                     AS SEQ
                   FROM SSP_ANL_SHIP_PLAN_40        SP
                      , SCM_MST_SITE                FS
                      , GT_SSP0045_FILTER           F
                      , GT_SSP0045_40_STD           ST
                  WHERE SP.DIVISION_ID          = FS.DIVISION_ID
                    AND SP.FROM_SITE            = FS.SCM_SITE_ID
                    AND SP.DIVISION_ID          = F.DIVISION_ID
                    AND SP.ITEM_ID              = F.ITEM_ID
                    AND SP.FROM_SITE            = F.FROM_SITE
                    AND ST.DIVISION_ID          = SP.DIVISION_ID
                    AND ST.FROM_SITE            = SP.FROM_SITE
                    AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
                    AND FS.SITE_TYPE            = 'PLANT'
                    /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
                    AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
                    AND FS.VALID_YN             = 'Y'
                    AND SP.MEASURE              = 'WH_IN'
                    AND SP.DIVISION_ID          = P_DIVISION_ID
                    AND SP.YYYYMMDD            >= V_PLAN_START_YYYYMMDD
                    AND SP.YYYYMMDD            <= P_TO_YYYYMMDD
                    AND SP.QTY                  > 0
                    AND SP.DIVISION_ID          = '40'        /* 소형(40) 인 경우만 조회 */
                    AND ( TRIM(P_SCM_SITE_ID) IS NULL
                          OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                    AND ( TRIM(P_ITEM_ID) IS NULL
--                        OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                          OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                          OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
               )  TOT
             , SCP_MST_BOD_N_V         BOD           /* BOD 2단계 개발 : FROM , TO 조건 추가 */
             -- 2026.10.06 AJS 약칭 묶음을 이번 조회 품목으로 한정 (결과 동일) (START)
--             , ( SELECT ITEM_ID
--                      , MAX(NICK_NAME)                        AS NICK_NAME
--                   FROM SCM_MST_ITEM_SN
--                  WHERE NICK_NAME IS NOT NULL
--                  GROUP BY ITEM_ID )  I
             , ( SELECT ITEM_ID
                      , MAX(NICK_NAME)                        AS NICK_NAME
                   FROM SCM_MST_ITEM_SN
                  WHERE NICK_NAME IS NOT NULL
                    AND ITEM_ID IN (SELECT XA.ITEM_ID
                                      FROM GT_SSP0045_PLAN_ERP_RESULT XA
                                     UNION ALL
                                    SELECT XB.ITEM_ID
                                      FROM GT_SSP0045_PLAN XB
                                     UNION ALL
                                    SELECT XC.ITEM_ID
                                      FROM GT_SSP0045_SHIP_REQ XC
                                     UNION ALL
                                    SELECT XD.ITEM_ID
                                      FROM GT_SSP0045_SHIP_REQ_OWMS XD
                                     UNION ALL
                                    SELECT XE.ITEM_ID
                                      FROM GT_SSP0045_FILTER XE)
                  GROUP BY ITEM_ID )  I
             -- 2026.10.06 AJS 약칭 묶음을 이번 조회 품목으로 한정 (결과 동일) (END)
         WHERE TOT.DIVISION_ID   = BOD.DIVISION_ID(+)
           AND TOT.BOD_ID        = BOD.BOD_ID(+)
           AND TOT.ITEM_ID       = I.ITEM_ID(+)
         GROUP BY TOT.DIVISION_ID
                , TOT.ITEM_ID
                , TOT.FROM_SITE
                , TOT.TO_SITE
                , TOT.TR_MODE
                , TOT.INCOTERMS
                , TOT.MEASURE
                , TOT.YYYYMMDD
                , TOT.PROJECT_CODE
                , TOT.FCST_TYPE
                , TOT.SEQ
                , TOT.BOD_ID;                                  /* BOD 2단계 개발 */

        /* LT DAY 삭제 */
        UPDATE GT_SSP0045_SHIP_ROW
           SET LT_DAY = '-'
         WHERE MEASURE IN ('CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN');

        /*---------------------------------------------
         * 5. STOCK INV
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_STOCK
        ( DIVISION_ID, ITEM_ID, FROM_SITE, YYYYMMDD, QTY )
        SELECT INV.DIVISION_ID
             , INV.ITEM_ID
             , INV.SCM_SITE_ID                                AS FROM_SITE
             , V_PLAN_START_YYYYMMDD                          AS YYYYMMDD
             , INV.SSP_QTY                                    AS QTY         /* SSP용 dbo.SSP_DNM_STOCK_C */
          FROM SSP_DNM_STOCK_C        INV
             , ( SELECT DIVISION_ID
                      , SITE_ID
                      , MAX(CUTOFF_DATE)                      AS MAX_CUTOFF_DATE
                   FROM SSP_DNM_STOCK_C
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    /* ★AS-IS 는 문자끼리 견주나 TO-BE 의 CUTOFF_DATE 는 날짜 칸이라 형을 맞춘다 */
                    AND CUTOFF_DATE  > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')       /* 현재일 - 3 */
                    AND CUTOFF_DATE <= TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')  /* 변수 : 현재일 */
                  GROUP BY DIVISION_ID
                         , SITE_ID )  MS
             , ( SELECT DIVISION_ID
                      , SCM_SITE_ID
                      , OPERATION_GROUP
                      , SITE_TYPE
                   FROM SCM_MST_SITE
                  WHERE DIVISION_ID      = P_DIVISION_ID
                    AND SITE_TYPE        = 'PLANT'
                    AND OPERATION_GROUP  = P_OPERATION_GROUP                 /* Cell Plant Site */
                    AND VALID_YN         = 'Y' )  B
             , ( SELECT DISTINCT
                        A.STORAGE_ID
                      , A.LOCATION_CODE
                      , A.SCM_SITE_ID
                      , A.DIVISION_ID
                      , A.OPERATION_ID
                   FROM SCM_MST_LOCATION   A
                      , SCM_MST_SITE       SB
                  WHERE A.SCM_SITE_ID      = SB.SCM_SITE_ID
                    AND SB.DIVISION_ID     = P_DIVISION_ID
                    AND SB.VALID_YN        = 'Y'
                    AND SB.OPERATION_GROUP = P_OPERATION_GROUP               /* Cell Plant Site */
                    AND A.DIVISION_ID      = P_DIVISION_ID
                    AND A.VALID_YN         = 'Y'
                    /* 2019.10.31 BOH(STOCK_V) 조회 시 FORMATION_CHECK_PACKAGING 재고 포함 */
                    /* Cell 특성완료 이후 창고 */
                    AND A.LOCATION_CODE IN ('CELL_OWMS', 'FORMATION_CHECK_PACKAGING')
                    AND ( A.STORAGE_ID IS NOT NULL OR A.OPERATION_ID IS NOT NULL ) )  C
         WHERE INV.DIVISION_ID   = MS.DIVISION_ID
           AND INV.SITE_ID       = MS.SITE_ID
           AND INV.CUTOFF_DATE   = MS.MAX_CUTOFF_DATE
           AND INV.DIVISION_ID   = B.DIVISION_ID
           AND INV.SCM_SITE_ID   = B.SCM_SITE_ID
           AND INV.DIVISION_ID   = C.DIVISION_ID
           AND INV.SCM_SITE_ID   = C.SCM_SITE_ID
           AND ( INV.STORAGE_ID  = C.STORAGE_ID OR INV.OPERATION_ID = C.OPERATION_ID )
           AND INV.CUTOFF_DATE   > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')
           AND P_DIVISION_ID    <> '40'                       /* [C20201016-000147] : 소형(40) 사업부 제외 ,khj79 */
         UNION ALL
        /* [C20201016-000147] : 소형(40) 사업부 추가, khj79 */
        SELECT SP.DIVISION_ID
             , SP.ITEM_ID
             , SP.FROM_SITE
             , SP.YYYYMMDD
             , SP.QTY
          FROM SSP_ANL_SHIP_PLAN_40        SP
             , SCM_MST_SITE                FS
             , GT_SSP0045_FILTER           F
             , GT_SSP0045_40_STD           ST
         WHERE SP.DIVISION_ID          = FS.DIVISION_ID
           AND SP.FROM_SITE            = FS.SCM_SITE_ID
           AND SP.DIVISION_ID          = F.DIVISION_ID
           AND SP.ITEM_ID              = F.ITEM_ID
           AND SP.FROM_SITE            = F.FROM_SITE
           AND ST.DIVISION_ID          = SP.DIVISION_ID
           AND ST.FROM_SITE            = SP.FROM_SITE
           AND ST.PLAN_START_YYYYMMDD  = SP.PLAN_START_YYYYMMDD
           AND FS.SITE_TYPE            = 'PLANT'
           /* 2021.10.21 : W/S AS 수정 , OPERATION_GROUP 파라미터 처리 및 OSP_YN 조건 제거 */
           AND FS.OPERATION_GROUP      = P_OPERATION_GROUP
           AND FS.VALID_YN             = 'Y'
           AND SP.MEASURE              = 'WH_STOCK'
           AND SP.DIVISION_ID          = P_DIVISION_ID
           AND SP.YYYYMMDD             = V_PLAN_START_YYYYMMDD
           AND SP.QTY                  > 0
           AND SP.DIVISION_ID          = '40'                 /* 소형(40) 인 경우만 조회 */
           AND ( TRIM(P_SCM_SITE_ID) IS NULL
                 OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR SP.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
           AND ( TRIM(P_ITEM_ID) IS NULL
--               OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                 OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--               OR SP.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) );   --  2026.10.07 AJS
                 OR SP.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) );   --  2026.10.07 AJS

        /*---------------------------------------------
         * 6. 일자별 BOH 계산
         *   ★AS-IS 가 CTE 세 벌(Z · QTY · BOH)로 적던 구간을 인라인 뷰로 옮긴다.
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_CAL_QTY
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, YYYYMMDD, PLAN_QTY, REQ_QTY )
        SELECT Z.DIVISION_ID
             , Z.ITEM_ID
             , Z.NICK_NAME
             , Z.FROM_SITE
             , Z.YYYYMMDD
             , ( SELECT NVL(SUM(X.PLAN_QTY), 0)
                   FROM ( SELECT DIVISION_ID
                               , ITEM_ID
                               , FROM_SITE
                               , YYYYMMDD
                               , NVL(SUM(CASE WHEN MEASURE = 'SHIP_PLAN'     THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'CUST_PLAN'     THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INSP_PLAN'     THEN NVL(QTY, 0)
                                              ELSE 0.0
                                         END), 0)                            AS PLAN_QTY
                            FROM GT_SSP0045_SHIP_ROW
                           WHERE MEASURE IN ('SHIP_PLAN', 'SHIP_REQ', 'CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
                             AND YYYYMMDD >= V_PLAN_START_YYYYMMDD
                             AND YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY DIVISION_ID
                                  , ITEM_ID
                                  , FROM_SITE
                                  , YYYYMMDD )  X
                  WHERE X.DIVISION_ID = Z.DIVISION_ID
                    AND X.ITEM_ID     = Z.ITEM_ID
                    AND X.FROM_SITE   = Z.FROM_SITE
                    AND X.YYYYMMDD    < Z.YYYYMMDD ) + NVL(BOH.QTY, 0)       AS PLAN_QTY
             , ( SELECT NVL(SUM(X.REQ_QTY), 0)
                   FROM ( SELECT DIVISION_ID
                               , ITEM_ID
                               , FROM_SITE
                               , YYYYMMDD
                               , NVL(SUM(CASE WHEN MEASURE = 'SHIP_REQ'      THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'CUST_REQ'      THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(QTY, 0)
                                              WHEN MEASURE = 'INSP_PLAN'     THEN NVL(QTY, 0)
                                              ELSE 0.0
                                         END), 0)                            AS REQ_QTY
                            FROM GT_SSP0045_SHIP_ROW
                           WHERE MEASURE IN ('SHIP_PLAN', 'SHIP_REQ', 'CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
                             AND YYYYMMDD >= V_PLAN_START_YYYYMMDD
                             AND YYYYMMDD <= P_TO_YYYYMMDD
                           GROUP BY DIVISION_ID
                                  , ITEM_ID
                                  , FROM_SITE
                                  , YYYYMMDD )  X
                  WHERE X.DIVISION_ID = Z.DIVISION_ID
                    AND X.ITEM_ID     = Z.ITEM_ID
                    AND X.FROM_SITE   = Z.FROM_SITE
                    AND X.YYYYMMDD    < Z.YYYYMMDD ) + NVL(BOH.QTY, 0)       AS REQ_QTY
          FROM ( SELECT DISTINCT
                        R.DIVISION_ID
                      , R.ITEM_ID
                      , R.NICK_NAME
                      , R.FROM_SITE
                      , O.BASIS_YYYYMMDD                      AS YYYYMMDD
                   FROM SCM_SYS_CALENDAR_M    O
                      , ( SELECT DISTINCT
                                 DIVISION_ID
                               , ITEM_ID
                               , NICK_NAME
                               , FROM_SITE
                            FROM GT_SSP0045_SHIP_ROW )  R
                  WHERE O.BASIS_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                    AND O.BASIS_YYYYMMDD <= P_TO_YYYYMMDD )  Z
             , ( SELECT V.DIVISION_ID
                      , V.ITEM_ID
                      , V.FROM_SITE
                      , SUM(V.QTY)                            AS QTY
                   FROM ( SELECT INV.DIVISION_ID
                               , INV.ITEM_ID
                               , INV.FROM_SITE
                               , INV.YYYYMMDD
                               , INV.QTY                                     /* SSP용 */
                            FROM GT_SSP0045_STOCK      INV                   /* 20200401 속도개선. TEMP Table 사용. */
                               , SCP_MST_FINAL_ITEM    FI
                           WHERE INV.DIVISION_ID    = FI.DIVISION_ID
                             AND INV.ITEM_ID        = FI.ITEM_ID
                             AND FI.OPERATION_GROUP = P_OPERATION_GROUP
                             AND ( TRIM(P_SCM_SITE_ID) IS NULL
                                   OR UPPER(P_SCM_SITE_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                                   OR INV.FROM_SITE IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_SCM_SITE_ID, ','))) )
                             AND ( TRIM(P_ITEM_ID) IS NULL
--                                 OR UPPER(P_ITEM_ID) = 'ALL'   /* 2026.10.08 AJS 조회조건 ALL */
                                   OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                 OR INV.ITEM_ID IN (SELECT UPPER(COLUMN_VALUE) FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))) )   --  2026.10.07 AJS
                                   OR INV.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(V_ITEM_TAB)) )   --  2026.10.07 AJS
                        )  V
                  GROUP BY V.DIVISION_ID
                         , V.ITEM_ID
                         , V.FROM_SITE )  BOH
         WHERE Z.DIVISION_ID = BOH.DIVISION_ID(+)
           AND Z.ITEM_ID     = BOH.ITEM_ID(+)
           AND Z.FROM_SITE   = BOH.FROM_SITE(+);

        /*---------------------------------------------
         * 8. W/H BOH(Plan) : Cell Plant의 Cell 재고
         *    일자별 BOH 계산  : BOH(D+1) = BOH(D) - Ship Plan(D) - Customer Plan(D) - Internal movement(D) + Inspection Plan(D)
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , 'WH_BOH_PLAN'                                  AS MEASURE
             , YYYYMMDD
             , NVL(PLAN_QTY, 0)                               AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , 8                                              AS SEQ
          FROM GT_SSP0045_CAL_QTY;

        /*---------------------------------------------
         * 9. W/H BOH(Req) : Cell Plant의 Cell 재고
         *    일자별 BOH 계산  : BOH(D+1) = BOH(D) - Ship Req(D) - Customer Req(D) - Internal movement(D) + Inspection Plan(D)
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DIVISION_ID
             , ITEM_ID
             , NICK_NAME
             , FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , 'WH_BOH_REQ'                                   AS MEASURE
             , YYYYMMDD
             , NVL(REQ_QTY, 0)                                AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , 9                                              AS SEQ
          FROM GT_SSP0045_CAL_QTY;

        /*---------------------------------------------
         * 10. Requestor
         *     2020.01.03  Requestor 조회 시 Last Updated By 가 scp_batch인 것은 제외
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_REQUESTOR
        ( DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID, MEASURE, LAST_UPDATED_BY )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , A.BOD_ID                                       /* BOD 2단계 개발 */
             , A.MEASURE
             , A.LAST_UPDATED_BY
          FROM GT_SSP0045_SHIP_REQ    A
         WHERE A.RN = (SELECT NVL(MIN(B.RN), 1)
                         FROM GT_SSP0045_SHIP_REQ B
                        WHERE B.DIVISION_ID     = A.DIVISION_ID
                          AND B.ITEM_ID         = A.ITEM_ID
                          AND B.FROM_SITE       = A.FROM_SITE
                          AND B.TO_SITE         = A.TO_SITE
                          AND B.TR_MODE         = A.TR_MODE
                          AND B.INCOTERMS       = A.INCOTERMS
                          AND B.MEASURE         = A.MEASURE
                          AND B.LAST_UPDATED_BY <> 'scp_batch');

        /*---------------------------------------------
         * 11. UI용 Measure 추가
         *     MEASURE : SCP_PLAN, SHIP_PLAN, SHIP_REQ
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , A.BOD_ID                                       /* BOD 2단계 개발 */
             , A.LT_DAY
             , M.COLUMN_NAME                                  AS MEASURE
             , O.BASIS_YYYYMMDD
             , NULL                                           AS QTY
             , A.PROJECT_CODE                                 AS PROJECT_CODE
             , A.FCST_TYPE                                    AS FCST_TYPE
             , M.SORT_ORDER_NO                                AS SEQ
          FROM GT_SSP0045_SHIP_ROW        A
             , SCM_SYS_CALENDAR_M         O
             , SCM_MST_SHEET_MEASURE      M
         WHERE O.BASIS_YYYYMMDD  = V_PLAN_START_YYYYMMDD
           AND M.PROGRAM_ID      = P_PROGRAM_ID
           AND M.SHEET_NAME      = P_SHEET_NAME
           AND M.COLUMN_NAME     IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND A.MEASURE         IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0045_SHIP_ROW B
                            WHERE B.DIVISION_ID  = A.DIVISION_ID
                              AND B.ITEM_ID      = A.ITEM_ID
                              AND B.FROM_SITE    = A.FROM_SITE
                              AND B.TO_SITE      = A.TO_SITE
                              AND B.TR_MODE      = A.TR_MODE
                              AND B.INCOTERMS    = A.INCOTERMS
                              AND B.BOD_ID       = A.BOD_ID                  /* BOD 2단계 개발 */
                              AND B.PROJECT_CODE = A.PROJECT_CODE
                              AND B.FCST_TYPE    = A.FCST_TYPE
                              AND B.MEASURE      = M.COLUMN_NAME
                              AND B.YYYYMMDD     = O.BASIS_YYYYMMDD);

        /* MEASURE : CUST_PLAN, CUST_REQ, INTN_MOVEMENT, INSP_PLAN */
        INSERT INTO GT_SSP0045_SHIP_ROW
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT DISTINCT
               A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , '-'                                            AS TO_SITE
             , '-'                                            AS TR_MODE
             , '/'                                            AS INCOTERMS
             , '-'                                            AS BOD_ID      /* BOD 2단계 개발 */
             , '-'                                            AS LT_DAY
             , M.COLUMN_NAME                                  AS MEASURE
             , O.BASIS_YYYYMMDD
             , NULL                                           AS QTY
             , '/'                                            AS PROJECT_CODE
             , '/'                                            AS FCST_TYPE
             , M.SORT_ORDER_NO                                AS SEQ
          FROM GT_SSP0045_SHIP_ROW        A
             , SCM_SYS_CALENDAR_M         O
             , SCM_MST_SHEET_MEASURE      M
         WHERE O.BASIS_YYYYMMDD  = V_PLAN_START_YYYYMMDD
           AND M.PROGRAM_ID      = P_PROGRAM_ID
           AND M.SHEET_NAME      = P_SHEET_NAME
           AND M.COLUMN_NAME     IN ('CUST_PLAN', 'CUST_REQ', 'INTN_MOVEMENT', 'INSP_PLAN')
           AND A.MEASURE         IN ('SCP_PLAN', 'SHIP_PLAN', 'SHIP_REQ')
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0045_SHIP_ROW B
                            WHERE B.DIVISION_ID  = A.DIVISION_ID
                              AND B.ITEM_ID      = A.ITEM_ID
                              AND B.FROM_SITE    = A.FROM_SITE
                              AND B.TO_SITE      = '-'
                              AND B.TR_MODE      = '-'
                              AND B.INCOTERMS    = '/'
                              AND B.BOD_ID       = '-'                       /* BOD 2단계 개발 */
                              AND B.MEASURE      = M.COLUMN_NAME
                              AND B.YYYYMMDD     = O.BASIS_YYYYMMDD);

        /*---------------------------------------------
         * 12. PIVOT용 Data정리
         *---------------------------------------------*/
        INSERT INTO GT_SSP0045_SHIP_PIVOT
        ( DIVISION_ID, ITEM_ID, NICK_NAME, FROM_SITE, TO_SITE, TR_MODE, INCOTERMS, BOD_ID
        , LT_DAY, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, PROJECT_CODE, FCST_TYPE, SEQ )
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.NICK_NAME
             , A.FROM_SITE
             , A.TO_SITE
             , A.TR_MODE
             , A.INCOTERMS
             , NVL(NULLIF(RTRIM(A.BOD_ID),''), '/')                             AS BOD_ID      /* BOD 2단계 개발 */
             , A.LT_DAY
             , A.MEASURE
             , 'D_'||A.YYYYMMDD                               AS YYYYMMDD
             , O.BASIS_YYYYMM                                 AS YYYYMM
             , SUBSTR(O.BASIS_YYYYMM, -4)||O.ISO_WEEK         AS ISO_WEEK
             , A.QTY
             , A.PROJECT_CODE
             , A.FCST_TYPE
             , A.SEQ
          FROM GT_SSP0045_SHIP_ROW     A
             , SCM_SYS_CALENDAR_M      O
         WHERE A.YYYYMMDD = O.BASIS_YYYYMMDD;

        /*---------------------------------------------
         * 13. PIVOIT처리
         *     피벗 대상 날짜 칸 만들기 — 칸 수가 기간에 따라 달라지므로 이 부분만 동적 SQL
         *---------------------------------------------*/
        DBMS_LOB.CREATETEMPORARY(V_PIVOT, TRUE);
        FOR C IN ( SELECT YYYYMMDD
                     FROM ( SELECT 'W_'||BASIS_YYYYMM||ISO_WEEK          AS YYYYMMDD
                                 , BASIS_START_DATE||'21'                AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMM
                                    , ISO_WEEK
                                    , BASIS_START_DATE
                             UNION ALL
                            SELECT 'M_'||BASIS_YYYYMM                    AS YYYYMMDD
                                 , MIN(BASIS_START_DATE)||'01'           AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMM
                                    , MONTH_NAME
                             UNION ALL
                            SELECT 'D_'||BASIS_YYYYMMDD                  AS YYYYMMDD
                                 , BASIS_YYYYMMDD||'31'                  AS SORT_ORDER_NO
                              FROM SCM_SYS_CALENDAR_M
                             WHERE BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                             GROUP BY BASIS_YYYYMMDD
                          )  IA
                    ORDER BY SORT_ORDER_NO )
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.YYYYMM = '''||SUBSTR(C.YYYYMMDD, -6)
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.ISO_WEEK = '''||SUBSTR(C.YYYYMMDD, -6)
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_PIVOT, ', SUM(CASE WHEN P.YYYYMMDD = '''||C.YYYYMMDD
                                || ''' THEN P.QTY END) AS '||C.YYYYMMDD||CHR(10));
            END IF;
        END LOOP;

        DBMS_LOB.CREATETEMPORARY(V_SQL, TRUE);
        DBMS_LOB.APPEND(V_SQL,
             'SELECT P.DIVISION_ID'||CHR(10)
          || '     , P.ITEM_ID'||CHR(10)
          || '     , NVL(NULLIF(P.NICK_NAME, '' ''), '' '') AS NICK_NAME'||CHR(10)
          || '     , P.FROM_SITE'||CHR(10)
          || '     , P.TO_SITE'||CHR(10)
          || '     , P.TR_MODE'||CHR(10)
          || '     , P.INCOTERMS'||CHR(10)
          || '     , P.BOD_ID'||CHR(10)                                      /* BOD 2단계 개발 */
          /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
          || '     , TO_CHAR(TO_DATE(:B_PLAN_START1, ''YYYYMMDD'')'||CHR(10)
          || '               + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE1, P.DIVISION_ID, P.FROM_SITE, :B_PLAN_START2)'||CHR(10)
          || '               , ''YYYYMMDD'') AS BOD_FROM_YYYYMMDD'||CHR(10)
          || '     , :B_TO_YYYYMMDD AS BOD_TO_YYYYMMDD'||CHR(10)             /* BOD 2단계 개발 */
          || '     , P.LT_DAY'||CHR(10)
          /* ★AS-IS 는 이어붙이는 값 하나라도 없으면 문장 전체가 빈 값이 된다. 그 동작을 맞춘다 */
          /* 2026.09.30 AJS 수정 (START) */
--          || '     , CASE WHEN C.USERNAME IS NULL OR C.USERID IS NULL THEN NULL'||CHR(10)
--          || '            ELSE C.USERNAME||''(''||C.USERID||'')'' END AS LAST_UPDATED_BY'||CHR(10)
          || '     , CASE WHEN C.USER_NM IS NULL OR C.USER_ID IS NULL THEN NULL'||CHR(10)
          || '            ELSE C.USER_NM||''(''||C.USER_ID||'')'' END AS LAST_UPDATED_BY'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '     , P.SEQ'||CHR(10)
          || '     , P.PROJECT_CODE'||CHR(10)
          || '     , P.FCST_TYPE'||CHR(10)
          || '     , TO_CHAR(TO_DATE(:B_PLAN_START3, ''YYYYMMDD'')'||CHR(10)
          || '               + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(:B_APP_TYPE2, P.DIVISION_ID, P.FROM_SITE, :B_PLAN_START4)'||CHR(10)
          || '               , ''YYYYMMDD'') AS FROZEN_YYYYMMDD'||CHR(10)
          || '     , M.ATTRIBUTE3 AS MEASURE_COLOR'||CHR(10)
          /* [C20201016-000147] : 소형(40) 사업부 추가 - 소형인 경우 MEASURE 명 변경 */
          || '     , CASE WHEN P.DIVISION_ID = ''40'' AND P.MEASURE = ''INSP_PLAN''     THEN ''WH in Plan'''||CHR(10)
          || '            WHEN P.DIVISION_ID = ''40'' AND P.MEASURE = ''INTN_MOVEMENT'' THEN ''Post Process Plan'''||CHR(10)
          || '            ELSE M.COLUMN_LABEL_NAME END AS MEASURE_LABEL'||CHR(10)
          || '     , P.MEASURE'||CHR(10));
        DBMS_LOB.APPEND(V_SQL, V_PIVOT);
        DBMS_LOB.APPEND(V_SQL,
             '  FROM GT_SSP0045_SHIP_PIVOT   P'||CHR(10)
          || '     , GT_SSP0045_REQUESTOR    R'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '     , TB_FX_USER              C'||CHR(10)
          || '     , SCM_ADM_USER_M          C'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '     , SCP_MST_BOD_N_V         B'||CHR(10)                     /* BOD 2단계 개발 : FROM , TO 추가 */
          || '     , SCM_MST_SHEET_MEASURE   M'||CHR(10)
          || '     , SCM_MST_SITE            S'||CHR(10)
          || ' WHERE R.DIVISION_ID(+)   = P.DIVISION_ID'||CHR(10)
          || '   AND R.ITEM_ID(+)       = P.ITEM_ID'||CHR(10)
          || '   AND R.FROM_SITE(+)     = P.FROM_SITE'||CHR(10)
          || '   AND R.TO_SITE(+)       = P.TO_SITE'||CHR(10)
          || '   AND R.TR_MODE(+)       = P.TR_MODE'||CHR(10)
          || '   AND R.INCOTERMS(+)     = P.INCOTERMS'||CHR(10)
          || '   AND R.BOD_ID(+)        = P.BOD_ID'||CHR(10)                 /* BOD 2단계 개발 */
          || '   AND R.MEASURE(+)       = P.MEASURE'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '   AND R.LAST_UPDATED_BY  = C.USERID(+)'||CHR(10)
          || '   AND R.LAST_UPDATED_BY  = C.USER_ID(+)'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '   AND P.BOD_ID           = B.BOD_ID(+)'||CHR(10)
          || '   AND M.COLUMN_NAME      = P.MEASURE'||CHR(10)
          || '   AND S.SCM_SITE_ID      = P.FROM_SITE'||CHR(10)
          || '   AND M.PROGRAM_ID       = :B_PGM'||CHR(10)
          || '   AND M.SHEET_NAME       = :B_SHT'||CHR(10)
          || '   AND S.DIVISION_ID      = :B_DIV'||CHR(10)
          || '   AND S.OPERATION_GROUP  = :B_OPGRP'||CHR(10)
          || '   AND S.SITE_TYPE        = ''PLANT'''||CHR(10)
          || '   AND S.VALID_YN         = ''Y'''||CHR(10)
          || ' GROUP BY P.DIVISION_ID, P.ITEM_ID, P.NICK_NAME, P.FROM_SITE, P.TO_SITE, P.TR_MODE, P.INCOTERMS'||CHR(10)
          /* 2026.09.30 AJS 수정 (START) */
--          || '        , P.LT_DAY, P.MEASURE, P.PROJECT_CODE, P.FCST_TYPE, P.SEQ, C.USERID, C.USERNAME'||CHR(10)
          || '        , P.LT_DAY, P.MEASURE, P.PROJECT_CODE, P.FCST_TYPE, P.SEQ, C.USER_ID, C.USER_NM'||CHR(10)
          /* 2026.09.30 AJS 수정 (END) */
          || '        , M.COLUMN_LABEL_NAME, S.SHIP_FROZEN, M.ATTRIBUTE3'||CHR(10)
          || '        , P.BOD_ID, B.TO_YYYYMMDD'||CHR(10)                    /* BOD 2단계 개발 */
          || ' ORDER BY FN_ASIS_SORT_KEY(P.DIVISION_ID) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.ITEM_ID) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.FROM_SITE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.TO_SITE) DESC NULLS LAST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.TR_MODE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.PROJECT_CODE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.FCST_TYPE) NULLS FIRST'||CHR(10)
          || '        , FN_ASIS_SORT_KEY(P.BOD_ID) NULLS FIRST'||CHR(10)
          || '        , P.SEQ'||CHR(10));

        /* DEBUG QRY 출력 */
        IF DEBUG_MODE = 'T' THEN
            FOR I IN 0 .. TRUNC((DBMS_LOB.GETLENGTH(V_SQL) - 1) / 3000) LOOP
                DBMS_OUTPUT.PUT_LINE(DBMS_LOB.SUBSTR(V_SQL, 3000, I * 3000 + 1));
            END LOOP;
        END IF;

        OPEN O_RC1 FOR V_SQL
          USING V_PLAN_START_YYYYMMDD, V_APP_TYPE, V_PLAN_START_YYYYMMDD
              , P_TO_YYYYMMDD
              , V_PLAN_START_YYYYMMDD, V_APP_TYPE, V_PLAN_START_YYYYMMDD
              , P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_OPERATION_GROUP;

        DBMS_LOB.FREETEMPORARY(V_PIVOT);
        DBMS_LOB.FREETEMPORARY(V_SQL);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            V_ERR_MSG := SQLERRM;
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR SELECT NULL AS DIVISION_ID FROM DUAL WHERE 1 = 0;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_GET_SHIPMENT_REQUEST;

    /*******************************************************************************
     * P_SSP0045_SAVE_SHIPMENT_REQUEST
     *   AS-IS SSP0045_SAVE_SHIPMENT_REQUEST
     *   Shipment Request 입력
     *
     * ★AS-IS 는 삭제 기능이 없어 Active Flag 를 'I' 또는 'M' 으로 보고 입력 · 수정만 한다.
     * ★AS-IS CATCH 는 오류를 기록한 뒤 바깥 트랜잭션을 확정(COMMIT)하고 결과 코드로 알린다.
     *   TO-BE 는 저장 시작에 SAVEPOINT 를 두고 오류 때 그 지점까지만 되돌린다.
     *******************************************************************************/
    PROCEDURE P_SSP0045_SAVE_SHIPMENT_REQUEST
    (
        P_ACTIVE_FLAG           IN  CLOB
      , P_DIVISION_ID           IN  CLOB
      , P_FROM_SITE             IN  CLOB
      , P_ITEM_ID               IN  CLOB
      , P_INCOTERMS             IN  CLOB
      , P_TRANSPORT_MODE        IN  CLOB
      , P_TO_SITE               IN  CLOB
      , P_BOD_ID                IN  CLOB
      , P_MEASURE               IN  CLOB
      , P_YYYYMMDD              IN  CLOB
      , P_QTY                   IN  CLOB
      , P_PROJECT_CODE          IN  CLOB
      , P_FCST_TYPE             IN  CLOB
      , P_CREATED_BY            IN  VARCHAR2
      , DEBUG_MODE              IN  VARCHAR2
      , O_RC1                   OUT SYS_REFCURSOR
      , O_RESULT_CURSOR         OUT SYS_REFCURSOR
    )
    IS
        V_ERR_MSG               VARCHAR2(4000 CHAR);
        V_DELIMITER             VARCHAR2(1 CHAR) := '^';
        V_MAX_LOOP_CNT          PLS_INTEGER := 0;
        V_MST_LOOP_CNT          PLS_INTEGER := 0;
        V_CNT_NO_BOD            PLS_INTEGER := 0;
        V_STR_NO_BOD            VARCHAR2(150 CHAR);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PKG_SSP0045.P_SSP0045_SAVE_SHIPMENT_REQUEST';
        V_LOG_TYPE              VARCHAR2(30 CHAR);
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
        V_DESCRIPTION           VARCHAR2(500 CHAR);
        D_EVENT_DATE            DATE;
        /* 예외처리 변수 설정 */
        V_ERR_CODE              PLS_INTEGER;
        V_ERR_MESSAGE           VARCHAR2(4000 CHAR);
        V_SQL_CODE              VARCHAR2(30 CHAR);
        E_NO_BOD                EXCEPTION;
    BEGIN

        SAVEPOINT SP_SSP0045_SAVE;

        DELETE FROM GT_SSP0045_SAVE_REQ;

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 프로시저 LOOP 길이를 판단 */
        V_MAX_LOOP_CNT := TO_NUMBER(SCM_ARR_SPL_CNT(P_ITEM_ID, V_DELIMITER));

        /*** 1. 신규건 MEASURE별 입력데이터 정리   *****/
        WHILE LENGTH(RTRIM(P_DIVISION_ID)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            INSERT INTO GT_SSP0045_SAVE_REQ
            ( ACTIVE_FLAG, DIVISION_ID, FROM_SITE, ITEM_ID, INCOTERMS, TRANSPORT_MODE, TO_SITE
            , BOD_ID, MEASURE, YYYYMMDD, QTY, PROJECT_CODE, FCST_TYPE )
            SELECT SCM_ARR_SPL_VAL(P_ACTIVE_FLAG,     V_DELIMITER, V_MST_LOOP_CNT)   AS ACTIVE_FLAG
                 , SCM_ARR_SPL_VAL(P_DIVISION_ID,     V_DELIMITER, V_MST_LOOP_CNT)   AS DIVISION_ID
                 , SCM_ARR_SPL_VAL(P_FROM_SITE,       V_DELIMITER, V_MST_LOOP_CNT)   AS FROM_SITE
                 , SCM_ARR_SPL_VAL(P_ITEM_ID,         V_DELIMITER, V_MST_LOOP_CNT)   AS ITEM_ID
                 , SCM_ARR_SPL_VAL(P_INCOTERMS,       V_DELIMITER, V_MST_LOOP_CNT)   AS INCOTERMS
                 , SCM_ARR_SPL_VAL(P_TRANSPORT_MODE,  V_DELIMITER, V_MST_LOOP_CNT)   AS TRANSPORT_MODE
                 , SCM_ARR_SPL_VAL(P_TO_SITE,         V_DELIMITER, V_MST_LOOP_CNT)   AS TO_SITE
                 , SCM_ARR_SPL_VAL(P_BOD_ID,          V_DELIMITER, V_MST_LOOP_CNT)   AS BOD_ID
                 , 'SHIP_REQ'                                                        AS MEASURE
                 , SCM_ARR_SPL_VAL(P_YYYYMMDD,        V_DELIMITER, V_MST_LOOP_CNT)   AS YYYYMMDD
                 , SCM_ARR_SPL_VAL(P_QTY,             V_DELIMITER, V_MST_LOOP_CNT)   AS QTY
                 , SCM_ARR_SPL_VAL(P_PROJECT_CODE,    V_DELIMITER, V_MST_LOOP_CNT)   AS PROJECT_CODE
                 , SCM_ARR_SPL_VAL(P_FCST_TYPE,       V_DELIMITER, V_MST_LOOP_CNT)   AS FCST_TYPE
              FROM DUAL;

        END LOOP;

        /* BOD 2단계 개발 : BOD ID 를 변경하지 못하도록 주석 처리 함 */

        /* BOD CHECK */
        SELECT COUNT(*)
          INTO V_CNT_NO_BOD
          FROM GT_SSP0045_SAVE_REQ
         WHERE ACTIVE_FLAG = 'M'
           AND TRIM(BOD_ID) IS NULL;

        IF V_CNT_NO_BOD > 0 THEN

            SELECT NO_BOD
              INTO V_STR_NO_BOD
              /* ★AS-IS 는 이어붙이는 값 하나라도 없으면 문구 전체가 빈 값이 된다. 그 동작을 맞춘다 */
              FROM ( SELECT CASE WHEN DIVISION_ID IS NULL OR FROM_SITE IS NULL OR TO_SITE IS NULL
                                       OR INCOTERMS IS NULL OR TRANSPORT_MODE IS NULL THEN NULL
                                  ELSE DIVISION_ID||'/'||FROM_SITE||'/'||TO_SITE||'/'||INCOTERMS||'/'||TRANSPORT_MODE
                             END                                                       AS NO_BOD
                       FROM GT_SSP0045_SAVE_REQ
                      WHERE ACTIVE_FLAG = 'M'
                        AND TRIM(BOD_ID) IS NULL )  IA
             WHERE ROWNUM = 1;

            V_ERR_CODE    := 99111;
            V_ERR_MESSAGE := 'Div, From Site, To Site 에 해당되는 BOD(Trans mode, Incoterms) 정보가 유효하지 않습니다. '||V_STR_NO_BOD;
            RAISE E_NO_BOD;                                    /* 예외발생 */

        END IF;

        D_EVENT_DATE := SYSDATE;

        /* 수정 */
        /* 삭제기능은 없으므로 Active Flag는 'I' 또는 'M'으로 가정하고 입력/수정만 진행 */
        UPDATE DM_PLN_SHIPMENT_REQ A
           SET ( A.QTY, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE )
               = ( SELECT TO_NUMBER(B.QTY)
                        , P_CREATED_BY
                        , D_EVENT_DATE
                     FROM GT_SSP0045_SAVE_REQ B
                    WHERE A.DIVISION_ID     = B.DIVISION_ID
                      AND A.SCM_SITE_ID     = B.TO_SITE
                      AND A.ITEM_ID         = B.ITEM_ID
                      AND A.INCOTERMS       = B.INCOTERMS
                      AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                      AND A.MEASURE         = B.MEASURE
                      AND A.PLANT_SITE_ID   = B.FROM_SITE
                      AND A.YYYYMMDD        = B.YYYYMMDD
                      AND A.BOD_ID          = B.BOD_ID         /* BOD 2단계 개발 : 추가 */
                      AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                      AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END) )
         WHERE EXISTS (SELECT 1
                         FROM GT_SSP0045_SAVE_REQ B
                        WHERE A.DIVISION_ID     = B.DIVISION_ID
                          AND A.SCM_SITE_ID     = B.TO_SITE
                          AND A.ITEM_ID         = B.ITEM_ID
                          AND A.INCOTERMS       = B.INCOTERMS
                          AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                          AND A.MEASURE         = B.MEASURE
                          AND A.PLANT_SITE_ID   = B.FROM_SITE
                          AND A.YYYYMMDD        = B.YYYYMMDD
                          AND A.BOD_ID          = B.BOD_ID     /* BOD 2단계 개발 : 추가 */
                          AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                          AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END));

        INSERT INTO DM_PLN_SHIPMENT_REQ
        ( DIVISION_ID,    PROJECT_CODE,   SCM_SITE_ID,        ITEM_ID,            FCST_TYPE
        , INCOTERMS,      TRANSPORT_MODE, MEASURE,            PLANT_SITE_ID,      YYYYMMDD,           QTY
        , BOD_ID,         SITE_TYPE,      CREATED_BY,         CREATION_DATE,      LAST_UPDATED_BY,    LAST_UPDATE_DATE )
        SELECT B.DIVISION_ID
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.TO_SITE
             , B.ITEM_ID
             , B.FCST_TYPE                                    AS FCST_TYPE
             , B.INCOTERMS
             , B.TRANSPORT_MODE
             , B.MEASURE
             , B.FROM_SITE
             , B.YYYYMMDD
             , TO_NUMBER(B.QTY)
             , B.BOD_ID
             , 'PLANT'
             , P_CREATED_BY
             , D_EVENT_DATE
             , P_CREATED_BY
             , D_EVENT_DATE
          FROM GT_SSP0045_SAVE_REQ B
         WHERE NOT EXISTS (SELECT 1
                             FROM DM_PLN_SHIPMENT_REQ A
                            WHERE A.DIVISION_ID     = B.DIVISION_ID
                              AND A.SCM_SITE_ID     = B.TO_SITE
                              AND A.ITEM_ID         = B.ITEM_ID
                              AND A.INCOTERMS       = B.INCOTERMS
                              AND A.TRANSPORT_MODE  = B.TRANSPORT_MODE
                              AND A.MEASURE         = B.MEASURE
                              AND A.PLANT_SITE_ID   = B.FROM_SITE
                              AND A.YYYYMMDD        = B.YYYYMMDD
                              AND A.BOD_ID          = B.BOD_ID /* BOD 2단계 개발 : 추가 */
                              AND A.PROJECT_CODE    = (CASE WHEN B.PROJECT_CODE IS NULL OR B.PROJECT_CODE = '/' THEN '/' ELSE B.PROJECT_CODE END)
                              AND A.FCST_TYPE       = (CASE WHEN B.FCST_TYPE IS NULL OR B.FCST_TYPE = '/' THEN '/' ELSE B.FCST_TYPE END));

        /* History */
        INSERT INTO DM_PLN_SHIPMENT_REQ_H
        ( DIVISION_ID,    PROJECT_CODE,   SCM_SITE_ID,        ITEM_ID,            FCST_TYPE
        , INCOTERMS,      TRANSPORT_MODE, MEASURE,            PLANT_SITE_ID,      YYYYMMDD,           QTY
        , BOD_ID,         SITE_TYPE,      CREATED_BY,         CREATION_DATE,      LAST_UPDATED_BY,    LAST_UPDATE_DATE )
        SELECT B.DIVISION_ID
             , B.PROJECT_CODE                                 AS PROJECT_CODE
             , B.TO_SITE
             , B.ITEM_ID
             , B.FCST_TYPE                                    AS FCST_TYPE
             , B.INCOTERMS
             , B.TRANSPORT_MODE
             , B.MEASURE
             , B.FROM_SITE
             , B.YYYYMMDD
             , TO_NUMBER(B.QTY)
             , B.BOD_ID
             , 'PLANT'
             , P_CREATED_BY
             , D_EVENT_DATE
             , P_CREATED_BY
             , D_EVENT_DATE
          FROM GT_SSP0045_SAVE_REQ B;

        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE, NULL AS MSG FROM DUAL;

        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := NULL;
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        OPEN O_RESULT_CURSOR FOR
            SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    EXCEPTION
        WHEN E_NO_BOD THEN
            ROLLBACK TO SP_SSP0045_SAVE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MESSAGE, NULL, SYSDATE);
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR
                    SELECT 'N' AS RESULT_CODE, V_ERR_MESSAGE AS ERR_MESSAGE FROM DUAL;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MESSAGE AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

        WHEN OTHERS THEN
            V_ERR_MSG  := SQLERRM;
            V_SQL_CODE := TO_CHAR(SQLCODE);
            ROLLBACK TO SP_SSP0045_SAVE;
            PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'ERROR', NULL, V_ERR_MSG, NULL, SYSDATE);
            IF O_RC1%ISOPEN = FALSE THEN
                OPEN O_RC1 FOR
                    SELECT 'F' AS RESULT_CODE, '['||V_SQL_CODE||']'||V_ERR_MSG AS ERR_MESSAGE FROM DUAL;
            END IF;
            OPEN O_RESULT_CURSOR FOR
                SELECT '-1' AS CODE, V_ERR_MSG AS MSG, TO_CHAR(0) AS EVENT FROM DUAL;

    END P_SSP0045_SAVE_SHIPMENT_REQUEST;

END PKG_SSP0045;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0045
-- ##### END PACKAGE BODY PKG_SSP0045

-- ##### START PACKAGE BODY PKG_SSP0060
CREATE OR REPLACE PACKAGE BODY           "PKG_SSP0060" 
IS

    /* 2026.10.07 AJS Model/Nickname 검색 (START) */
    FUNCTION FN_SSP0060_ITEM_TAB
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
    )
    RETURN T_STR_TAB
    IS
/*
 * Program ID   : FN_SSP0060_ITEM_TAB
 * Description  : 조회조건 Model 대상 품목 목록 - 입력값(쉼표 구분, 빈 값 제외) 중 하나라도
 *                품목 코드 또는 닉네임에 부분일치(대소문자 무시)하는 품목 + 입력값 그대로(기존 정확일치 유지)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : Model 'ALL' 은 후보 목록을 만들지 않음(조건 없음)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();
    BEGIN

/*        IF TRIM(P_ITEM_ID) IS NOT NULL THEN */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
            SELECT DISTINCT IA.ITEM_ID
              BULK COLLECT INTO V_ITEM_TAB
              FROM (SELECT A.ITEM_ID
                      FROM SCM_MST_ITEM_SN A
                         , TABLE(STRING_SPLIT(P_ITEM_ID, ',')) B
                     WHERE B.COLUMN_VALUE IS NOT NULL
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND (   UPPER(A.ITEM_ID) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%'
                            OR UPPER(A.NICK_NAME) LIKE '%' || UPPER(B.COLUMN_VALUE) || '%')
                    UNION
                    SELECT SA.COLUMN_VALUE                                      /* 입력값 그대로 : 품목 원장에 없는 코드의 기존 정확일치 유지 */
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SA
                     WHERE SA.COLUMN_VALUE IS NOT NULL
                    UNION
                    SELECT UPPER(SB.COLUMN_VALUE)                               /* 입력값 대문자 : 소문자 입력의 정확일치 */
                      FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')) SB
                     WHERE SB.COLUMN_VALUE IS NOT NULL) IA;
        END IF;

        RETURN V_ITEM_TAB;

    END FN_SSP0060_ITEM_TAB;
    /* 2026.10.07 AJS Model/Nickname 검색 (END) */
    PROCEDURE P_SSP0060_GET_SHIPMENT_DIVISION
    (
        PARAM1                  IN  VARCHAR2
       ,PARAM2                  IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_DIVISION
 * Description  : DIVISION , COMPANY 정보
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/07/15   khj79          DIVISION , COMPANY 정보
 * 2024/10/01   KHJ            NERP_SSP
 * 2026/01/29   강주용		   E20260128-001165 ESS 사업부 추가
 * 2026/04/07   강주용		   [E20260206-001938] VP 권한 확장
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        /* NERP 매핑코드 */
        V_G480          VARCHAR2(20);
        V_G670          VARCHAR2(20);
        V_G450          VARCHAR2(20);
        V_G630          VARCHAR2(20);
        V_AUTH_TYPE     VARCHAR2(100) := 'D';
    BEGIN

        V_G480 := FN_GET_LOOKUP_VALUE('SSP0060_GET_SHIPMENT_DIVISION', 'G480');
        V_G670 := FN_GET_LOOKUP_VALUE('SSP0060_GET_SHIPMENT_DIVISION', 'G670');
        V_G450 := FN_GET_LOOKUP_VALUE('SSP0060_GET_SHIPMENT_DIVISION', 'G450');
        V_G630 := FN_GET_LOOKUP_VALUE('SSP0060_GET_SHIPMENT_DIVISION', 'G630');

        IF (PARAM1 = 'JV Planner') THEN
            V_AUTH_TYPE := 'J';
        END IF;

        /* START [E20260206-001938] VP 권한 확장 */
        OPEN O_RC1 FOR
            SELECT IA.CODE
                 , MAX(IA.NAME) AS NAME
                 , MAX(IA.ATTRIBUTE1) AS ATTRIBUTE1
              FROM (/* 일반권한 */
                    SELECT A.DIVISION_ID AS CODE
                         , A.DIVISION_ID || ' ' || MIN(A.DIVISION_NAME) AS NAME
                         , 1 AS ATTRIBUTE1                                  /* [E20260206-001938] VP 권한 확장 */
                      FROM SCM_MST_DIVISION A
                     /* 2026.09.30 AJS 수정 (START) */
                   --WHERE A.DIVISION_ID IN (SELECT XA.CODE
                                             --FROM TB_FX_USERGROUPAUTHEXTENTION XA
                                            --WHERE XA.GROUPID = PARAM1
                                              --AND XA.USERID = PARAM2
                                              --AND XA.AUTHTYPE = V_AUTH_TYPE)
                     WHERE A.DIVISION_ID IN (SELECT XA.UNIT_ID
                                               FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XA
                                              WHERE XA.USER_ID = PARAM2
                                                AND XA.UNIT_TP_CD = V_AUTH_TYPE)
                     /* 2026.09.30 AJS 수정 (END) */
                       AND A.DIVISION_ID <> '40'
                       AND A.ATTRIBUTE3 <> 'EE'
                       /* START E20260128-001165 ESS 사업부 추가 */
                       /* AND DIVISION_ID in ('81','81_UC') -- 표시하고자 하는 DIVISION 지정 */
                       AND A.DIVISION_ID IN ('81', '81_UC', '82')           /* 표시하고자 하는 DIVISION 지정 */
                       /* END E20260128-001165 ESS 사업부 추가 */
                     GROUP BY A.DIVISION_ID
                    UNION /* VP 추가 권한 */
                    SELECT A.DIVISION_ID AS CODE
                         , A.DIVISION_ID || ' ' || MIN(A.DIVISION_NAME) AS NAME
                         , 0 AS ATTRIBUTE1
                      FROM SCM_MST_DIVISION A
                     WHERE A.DIVISION_ID IN (SELECT XA.DIVISION_ID
                                               FROM SCM_MST_SITE XA
                                                  , SCM_MST_SITE XB
                                                  /* 2026.09.30 AJS 수정 (START) */
                                                --, TB_FX_USERGROUPAUTHEXTENTION XC
                                                  , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XC
                                                  /* 2026.09.30 AJS 수정 (END) */
                                              WHERE XA.ATTRIBUTE9 = XB.SCM_SITE_ID
                                                /* 2026.09.30 AJS 수정 (START) */
                                              --AND XB.DIVISION_ID = XC.CODE
                                                AND XB.DIVISION_ID = XC.UNIT_ID
                                                /* 2026.09.30 AJS 수정 (END) */
                                                AND XB.SITE_TYPE = 'PLANT'
                                                /* 2026.09.30 AJS 수정 (START) */
                                              --AND XC.AUTHTYPE = V_AUTH_TYPE
                                              --AND XC.GROUPID = PARAM1
                                              --AND XC.USERID = PARAM2)
                                                AND XC.UNIT_TP_CD = V_AUTH_TYPE
                                                AND XC.USER_ID = PARAM2)
                                                /* 2026.09.30 AJS 수정 (END) */
                       AND A.DIVISION_ID IN ('81', '81_UC', '82')           /* 표시하고자 하는 DIVISION 지정 */
                       AND A.DIVISION_ID <> '40'
                       AND A.ATTRIBUTE3 <> 'EE'
                     GROUP BY A.DIVISION_ID) IA
             GROUP BY IA.CODE
             ORDER BY CODE ASC;

        /* 일반 권한 */
        OPEN O_RC2 FOR
            SELECT IA.CODE
                 , IA.NAME
                 , IA.DIVISION_ID
              FROM (SELECT A.COMPANY_ID AS CODE
                         , B.SEGMENT2 AS NAME
                         , A.DIVISION_ID
                      FROM SCM_MST_SITE A
                         , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     WHERE A.COMPANY_ID = B.SEGMENT1
                       AND B.LOOKUP_TYPE = 'COMPANY_DESC'
                       AND A.SITE_TYPE = 'PLANT'
                       AND (A.COMPANY_ID = V_G480
                        OR A.COMPANY_ID = V_G670)                           /* 표시하고자 하는 COMPANY 지정 */
                       /* START [E20260206-001938] VP 권한 확장 */
                       AND A.DIVISION_ID IN (SELECT XA.DIVISION_ID
                                               FROM SCM_MST_DIVISION XA
                                              /* 2026.09.30 AJS 수정 (START) */
                                            --WHERE XA.DIVISION_ID IN (SELECT XB.CODE
                                                                       --FROM TB_FX_USERGROUPAUTHEXTENTION XB
                                                                      --WHERE XB.GROUPID = PARAM1
                                                                        --AND XB.USERID = PARAM2
                                                                        --AND XB.AUTHTYPE = V_AUTH_TYPE)
                                              WHERE XA.DIVISION_ID IN (SELECT XB.UNIT_ID
                                                                         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XB
                                                                        WHERE XB.USER_ID = PARAM2
                                                                          AND XB.UNIT_TP_CD = V_AUTH_TYPE)
                                              /* 2026.09.30 AJS 수정 (END) */
                                                AND XA.DIVISION_ID <> '40'
                                                AND XA.ATTRIBUTE3 <> 'EE'
                                                AND XA.DIVISION_ID IN ('81', '81_UC', '82'))
                     GROUP BY A.COMPANY_ID, B.SEGMENT2, A.DIVISION_ID
                    UNION /* VP 추가 권한 */
                    SELECT A.COMPANY_ID AS CODE
                         , B.SEGMENT2 AS NAME
                         , A.DIVISION_ID
                      FROM SCM_MST_SITE A
                         , SCM_ADM_LOOKUP_MASTER_DETAIL B
                     WHERE A.COMPANY_ID = B.SEGMENT1
                       AND B.LOOKUP_TYPE = 'COMPANY_DESC'
                       AND A.SITE_TYPE = 'PLANT'
                       AND (A.COMPANY_ID = V_G480
                        OR A.COMPANY_ID = V_G670)
                       AND A.ATTRIBUTE9 IN (SELECT XA.SCM_SITE_ID
                                              FROM SCM_MST_SITE XA
                                                 /* 2026.09.30 AJS 수정 (START) */
                                               --, TB_FX_USERGROUPAUTHEXTENTION XB
                                           --WHERE XA.DIVISION_ID = XB.CODE
                                                 , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M XB
                                             WHERE XA.DIVISION_ID = XB.UNIT_ID
                                                 /* 2026.09.30 AJS 수정 (END) */
                                               AND XA.SITE_TYPE = 'PLANT'
                                               /* 2026.09.30 AJS 수정 (START) */
                                             --AND XB.AUTHTYPE = V_AUTH_TYPE
                                             --AND XB.GROUPID = PARAM1
                                             --AND XB.USERID = PARAM2)
                                               AND XB.UNIT_TP_CD = V_AUTH_TYPE
                                               AND XB.USER_ID = PARAM2)
                                               /* 2026.09.30 AJS 수정 (END) */
                     GROUP BY A.COMPANY_ID, B.SEGMENT2, A.DIVISION_ID) IA
             GROUP BY IA.CODE, IA.NAME, IA.DIVISION_ID;
        /* END [E20260206-001938] VP 권한 확장 */

    END P_SSP0060_GET_SHIPMENT_DIVISION;

    PROCEDURE P_SSP0060_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_CONFIRM_ID            IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
       ,O_RC3                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_STATUS
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2020/07/15   khj79          ERP_STATUS 가 'C' 인 경우 수정 못하도록 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND SHIPMENT_STATUS <> 'C';

        OPEN O_RC2 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND QTY = 0;

        OPEN O_RC3 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_DIVISION_ID, '^')))
               AND CONFIRM_ID IN (SELECT COLUMN_VALUE
                                    FROM TABLE(STRING_SPLIT(P_CONFIRM_ID, '^')))
               AND ERP_STATUS = 'C';

    END P_SSP0060_GET_SHIPMENT_STATUS;

    PROCEDURE P_SSP0060_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_ERP_SO_NO             IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_ERP_SO_NO_CNT
 * Description  : Shipment Change Request
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
    BEGIN

        OPEN O_RC1 FOR
            SELECT COUNT(*) AS CNT
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID = P_DIVISION_ID
               AND ERP_SO_NO = P_ERP_SO_NO
               AND QTY <> 0;

    END P_SSP0060_GET_ERP_SO_NO_CNT;

    PROCEDURE P_SSP0060_GET_SHIPMENT_PSI_COMMENTS
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_PSI_COMMENTS
 * Description  : Shipment Plan Confrim COMMENTS LOAD
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024/06/11   hsbang		   SSP 시스템 개선 요청건(Shipment Plan)
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        OPEN O_RC1 FOR
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.YYYYMMDD
                 , IA.QTY
                 , IA.NOEDIT_QTY
                 , 'Input Qty(Min) : ' || REPLACE(TO_CHAR(IA.NOEDIT_QTY, 'FM999,999,999,999,990.00'), '.00', '') AS NOTE
              FROM (SELECT A.DIVISION_ID
                         , A.FROM_SITE
                         , A.ITEM_ID
                         , A.TO_SITE
                         , A.TRANSPORT_MODE
                         , A.INCOTERMS
                         , A.FCST_TYPE
                         , A.YYYYMMDD
                         , SUM(A.QTY) AS QTY
                         , SUM(CASE WHEN A.SHIPMENT_STATUS IS NULL OR A.SHIPMENT_STATUS <> 'C' OR A.ERP_STATUS = 'C' THEN A.QTY ELSE 0 END) AS NOEDIT_QTY
                      FROM SSP_ANL_SHIP_CONFIRM A
                     WHERE A.CHANGE_TYPE = 'C'
                       AND A.BIZ_TYPE <> 'E'
                       AND A.QTY > 0
                       /* AND (T0.SHIPMENT_STATUS != 'C' OR T0.ERP_STATUS = 'C') --입력 불가(DO 발행수량) */
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND A.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                       /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
                       AND A.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND A.YYYYMMDD <= P_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                             FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                           FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                         FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                     GROUP BY A.DIVISION_ID
                            , A.FROM_SITE
                            , A.ITEM_ID
                            , A.TO_SITE
                            , A.TRANSPORT_MODE
                            , A.INCOTERMS
                            , A.FCST_TYPE
                            , A.YYYYMMDD) IA;

    END P_SSP0060_GET_SHIPMENT_PSI_COMMENTS;
    PROCEDURE P_SSP0060_GET_HOLD_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_PLAN_TYPE             IN  VARCHAR2
       ,P_SEQ                   IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_SEARCH_YN             IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_HOLD_STOCK
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/03/05   AYJ 			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/06/17	AYJ				조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
 * 2019/08/28	AYJ			    조회 조건 추가(p_delegateeChk)
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_PLAN_START_YYYYMMDD   VARCHAR2(8);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_PLAN_START_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');

        /* 1. 셀 더블클릭 - BLOCK_STOCK */
        IF P_SEARCH_YN = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.HOLD_ID
                     , A.DIVISION_ID
                     , A.FROM_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD') AS HOLD_YYYYMMDD
                     , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                     , A.HOLD_QTY
                     , A.REMARKS
                     /* AS-IS 는 문자 결합에 NULL 이 섞이면 전체가 NULL — 같은 결과가 되게 분기 */
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) IS NULL THEN NULL
                          --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                  FROM SSP_ANL_HOLD_STOCK A
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER B
                     , SCM_ADM_USER_M B
                     /* 2026.09.30 AJS 수정 (END) */
                     , SSP_MST_MODEL_USER C
                     , SCP_MST_FINAL_ITEM D
                 /* 2026.09.30 AJS 수정 (START) */
               --WHERE B.USERID(+) = A.LAST_UPDATED_BY
                 --AND B.USEYN(+) = 'Y'
                 WHERE B.USER_ID(+) = A.LAST_UPDATED_BY
                   AND B.USE_YN(+) = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
                   AND C.DIVISION_ID(+) = A.DIVISION_ID
                   AND C.FROM_SITE(+) = A.FROM_SITE
                   AND C.ITEM_ID(+) = A.ITEM_ID
                   AND C.VALID_YN(+) = 'Y'
                   AND D.DIVISION_ID(+) = A.DIVISION_ID
                   AND D.ITEM_ID(+) = A.ITEM_ID
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND A.FROM_SITE = P_FROM_SITE
                   AND A.HOLD_YYYYMMDD <= V_PLAN_START_YYYYMMDD
                   AND A.RELEASE_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                   AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND A.PLAN_TYPE = P_PLAN_TYPE
                   AND A.SEQ = P_SEQ
--                   AND A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                   /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                   AND A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
                   AND D.GROUP_CODE1 = P_PRODUCT_LEVEL1
                 GROUP BY A.HOLD_ID
                        , A.ITEM_ID
                        , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID)
                        , A.DIVISION_ID
                        , A.FROM_SITE
                        , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                        , A.HOLD_YYYYMMDD
                        , A.RELEASE_YYYYMMDD
                        , A.HOLD_QTY
                        , A.REMARKS
                        , A.LAST_UPDATE_DATE
                        , A.LAST_UPDATED_BY
                        /* 2026.09.30 AJS 수정 (START) */
                      --, B.USERNAME
                      --, B.USERNAME_E
                        , B.USER_NM
                        , B.USER_ENG_NM
                        /* 2026.09.30 AJS 수정 (END) */
                 ORDER BY A.HOLD_ID;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT A.HOLD_ID
                     , A.DIVISION_ID
                     , A.FROM_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD') AS HOLD_YYYYMMDD
                     , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                     , A.HOLD_QTY
                     , A.REMARKS
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) IS NULL THEN NULL
                          --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USERNAME ELSE B.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN B.USER_NM ELSE B.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                  FROM SSP_ANL_HOLD_STOCK A
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER B
                     , SCM_ADM_USER_M B
                     /* 2026.09.30 AJS 수정 (END) */
                     , SSP_MST_MODEL_USER C
                     , SCP_MST_FINAL_ITEM D
                 /* 2026.09.30 AJS 수정 (START) */
               --WHERE B.USERID(+) = A.LAST_UPDATED_BY
                 --AND B.USEYN(+) = 'Y'
                 WHERE B.USER_ID(+) = A.LAST_UPDATED_BY
                   AND B.USE_YN(+) = 'Y'
                 /* 2026.09.30 AJS 수정 (END) */
                   AND C.DIVISION_ID(+) = A.DIVISION_ID
                   AND C.FROM_SITE(+) = A.FROM_SITE
                   AND C.ITEM_ID(+) = A.ITEM_ID
                   AND C.VALID_YN(+) = 'Y'
                   AND D.DIVISION_ID(+) = A.DIVISION_ID
                   AND D.ITEM_ID(+) = A.ITEM_ID
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND A.HOLD_YYYYMMDD <= V_PLAN_START_YYYYMMDD
                   AND A.RELEASE_YYYYMMDD >= V_PLAN_START_YYYYMMDD
                   AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND A.PLAN_TYPE = P_PLAN_TYPE
                   AND A.SEQ = P_SEQ
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                    OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                       FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                    /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                    OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                     FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                   AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                    OR D.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
                 GROUP BY A.HOLD_ID
                        , A.ITEM_ID
                        , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID)
                        , A.DIVISION_ID
                        , A.FROM_SITE
                        , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                        , A.HOLD_YYYYMMDD
                        , A.RELEASE_YYYYMMDD
                        , A.HOLD_QTY
                        , A.REMARKS
                        , A.LAST_UPDATE_DATE
                        , A.LAST_UPDATED_BY
                        /* 2026.09.30 AJS 수정 (START) */
                      --, B.USERNAME
                      --, B.USERNAME_E
                        , B.USER_NM
                        , B.USER_ENG_NM
                        /* 2026.09.30 AJS 수정 (END) */
                 ORDER BY A.HOLD_ID;

        END IF;

    END P_SSP0060_GET_HOLD_STOCK;

    PROCEDURE P_SSP0060_GET_MES_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_MES_STOCK
 * Description  : Shipment PSI(Small)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/15   mcTheJ			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/09/16   mcTheJ			QMS_MES_Hold Case 수정
 * 2019/09/16   mcTheJ			TOTAL의 합은 RAW DATA의 SUM() -> ROW SUM이 아님
 * 2019/10/28	AYJ				컬럼명 변경 : AVAILABLE_STOCK - > OQC_COMPLETE, 컬럼 추가 : AVAILABLE_STOCK
 * 2022/02/16   SSP Pjt.        SSP_DNM_MES_STOCK_81_82 -> SSP_DNM_GMES_STOCK_81_82
 * 2023/09/01   jilee           반제품->제품 코드 변환 작업
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.ITEM_ID
                     , IA.NICK_NAME
                     , SUM(IA.OQC_INSP_REQUEST) AS OQC_INSP_REQUEST
                     , SUM(IA.BEFORE_OQC) AS BEFORE_OQC
                     , SUM(IA.OQC_NG) AS OQC_NG
                     , SUM(IA.QMS_MES_HOLD) AS QMS_MES_HOLD
                     , SUM(IA.OQC_COMPLETE) AS OQC_COMPLETE
                     /* (SUM(OQC_Insp_Request) + SUM(Before_OQC) + SUM(OQC_NG) + SUM(QMS_MES_Hold) + SUM(Available_Stock)) AS TOTAL */
                     , SUM(NVL(IA.TOTAL, 0)) AS TOTAL
                     , (SUM(NVL(IA.TOTAL, 0)) - SUM(IA.OQC_NG) - SUM(IA.QMS_MES_HOLD)) AS AVAILABLE_STOCK
                  FROM (SELECT A.ATTRIBUTE5 AS ITEM_ID                          /* jilee 230901 */
                             , A.PRJT_NAME AS NICK_NAME
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT = 'Inspection Request' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_INSP_REQUEST
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT IS NULL THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS BEFORE_OQC
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT = 'N' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND (A.QMS_HOLD_YN = 'Y' OR A.MES_HOLD_YN = 'Y') THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , CASE WHEN A.AVAILABLE_YN = 'Y' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_COMPLETE
                             , SUM(NVL(A.LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82 A
                             , SCP_MST_FINAL_ITEM B
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.YYYYMMDD = P_PLAN_START_YYYYMMDD
--                           AND A.ATTRIBUTE5 = P_ITEM_ID                         /* jilee 23091 */   --  2026.10.07 AJS
--                           AND A.ATTRIBUTE5 MEMBER OF V_ITEM_TAB  /* jilee 23091 */   --  2026.10.07 AJS
                           AND A.ATTRIBUTE5 = P_ITEM_ID                         /* jilee 23091 */   /* AJS 20261008 Model/Nickname */
                           AND B.GROUP_CODE1 = P_PRODUCT_LEVEL1
                           /* AND ITEM_ID = @p_item_id */
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                         GROUP BY A.ATTRIBUTE5, A.ITEM_ID, A.PRJT_NAME, A.AVAILABLE_YN, A.OQC_INSP_RESULT, A.MES_HOLD_YN, A.QMS_HOLD_YN) IA
                 GROUP BY IA.ITEM_ID, IA.NICK_NAME;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT IA.ITEM_ID
                     , IA.NICK_NAME
                     , SUM(IA.OQC_INSP_REQUEST) AS OQC_INSP_REQUEST
                     , SUM(IA.BEFORE_OQC) AS BEFORE_OQC
                     , SUM(IA.OQC_NG) AS OQC_NG
                     , SUM(IA.QMS_MES_HOLD) AS QMS_MES_HOLD
                     , SUM(IA.OQC_COMPLETE) AS OQC_COMPLETE
                     , SUM(NVL(IA.TOTAL, 0)) AS TOTAL
                     , (SUM(NVL(IA.TOTAL, 0)) - SUM(IA.OQC_NG) - SUM(IA.QMS_MES_HOLD)) AS AVAILABLE_STOCK
                  FROM (SELECT A.ATTRIBUTE5 AS ITEM_ID                          /* jilee 230901 */
                             , A.PRJT_NAME AS NICK_NAME
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT = 'Inspection Request' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_INSP_REQUEST
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT IS NULL THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS BEFORE_OQC
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND A.OQC_INSP_RESULT = 'N' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN A.AVAILABLE_YN = 'N' AND (A.QMS_HOLD_YN = 'Y' OR A.MES_HOLD_YN = 'Y') THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , CASE WHEN A.AVAILABLE_YN = 'Y' THEN SUM(NVL(A.LOT_QTY, 0)) ELSE 0 END AS OQC_COMPLETE
                             , SUM(NVL(A.LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82 A
                             , SCP_MST_FINAL_ITEM B
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           /* jilee 230901 */
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR A.ATTRIBUTE5 IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR A.ATTRIBUTE5 MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ATTRIBUTE5 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                           AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                            OR B.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
                           /* AND ((@p_item_id IS NULL OR @p_item_id ='')	OR ITEM_ID IN (SELECT token FROM dbo.String_Split(@p_item_id, ','))) */
                         GROUP BY A.ATTRIBUTE5, A.ITEM_ID, A.PRJT_NAME, A.AVAILABLE_YN, A.OQC_INSP_RESULT, A.MES_HOLD_YN, A.QMS_HOLD_YN) IA
                 GROUP BY IA.ITEM_ID, IA.NICK_NAME;

        END IF;

    END P_SSP0060_GET_MES_STOCK;

    PROCEDURE P_SSP0060_GET_MES_STOCK_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_BOX_ID                IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_MES_STOCK_DETAIL
 * Description  : Shipment PSI(Small)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/15   mcTheJ			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/28	AYJ				검색조건 추가 : BOXID
 * 2022/02/16   SSP Pjt.        SSP_DNM_MES_STOCK_81_82 -> SSP_DNM_GMES_STOCK_81_82
 * 2023/09/01   jilee           반제품->제품 코드 변환 작업
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.BOXID
                     , A.ATTRIBUTE5 AS PRODID                                   /* jilee 0901 */
                     , A.PRJT_NAME
                     , A.AVAILABLE_YN
                     , A.OQC_INSP_RESULT
                     , A.LOTID
                     , NVL(A.LOT_QTY, 0) AS LOT_QTY
                     , CASE WHEN A.PROD_VALID_DATE = '-' OR A.PROD_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PROD_VALID_DATE), 'YYYY-MM-DD') END AS PROD_VALID_DATE
                     , CASE WHEN A.EXP_INSP_VALID_DATE = '-' OR A.EXP_INSP_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.EXP_INSP_VALID_DATE), 'YYYY-MM-DD') END AS EXP_INSP_VALID_DATE
                     , A.MES_HOLD_YN
                     , A.QMS_HOLD_YN
                     , CASE WHEN A.MES_HOLD_RELEASE = '-' OR A.MES_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.MES_HOLD_RELEASE), 'YYYY-MM-DD') END AS MES_UNHOLD_SCHD_DATE
                     , CASE WHEN A.QMS_HOLD_RELEASE = '-' OR A.QMS_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.QMS_HOLD_RELEASE), 'YYYY-MM-DD') END AS QMS_UNHOLD_SCHD_DATE
                  FROM SSP_DNM_GMES_STOCK_81_82 A
                     , SCP_MST_FINAL_ITEM B
                 WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                   AND B.ITEM_ID(+) = A.ITEM_ID
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND A.COMPANY_ID = P_COMPANY_ID
                   AND A.YYYYMMDD = P_PLAN_START_YYYYMMDD
--                   AND A.ATTRIBUTE5 = P_ITEM_ID                                 /* jilee 0901 */   --  2026.10.07 AJS
--                   AND A.ATTRIBUTE5 MEMBER OF V_ITEM_TAB  /* jilee 0901 */   --  2026.10.07 AJS
                   AND A.ATTRIBUTE5 = P_ITEM_ID                                 /* jilee 0901 */   /* AJS 20261008 Model/Nickname */
                   AND B.GROUP_CODE1 = P_PRODUCT_LEVEL1
                   /* AND ITEM_ID = @p_item_id */
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))));

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT A.BOXID
                     , A.ATTRIBUTE5 AS PRODID                                   /* jilee 0901 */
                     , A.PRJT_NAME
                     , A.AVAILABLE_YN
                     , A.OQC_INSP_RESULT
                     , A.LOTID
                     , NVL(A.LOT_QTY, 0) AS LOT_QTY
                     , CASE WHEN A.PROD_VALID_DATE = '-' OR A.PROD_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.PROD_VALID_DATE), 'YYYY-MM-DD') END AS PROD_VALID_DATE
                     , CASE WHEN A.EXP_INSP_VALID_DATE = '-' OR A.EXP_INSP_VALID_DATE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.EXP_INSP_VALID_DATE), 'YYYY-MM-DD') END AS EXP_INSP_VALID_DATE
                     , A.MES_HOLD_YN
                     , A.QMS_HOLD_YN
                     , CASE WHEN A.MES_HOLD_RELEASE = '-' OR A.MES_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.MES_HOLD_RELEASE), 'YYYY-MM-DD') END AS MES_UNHOLD_SCHD_DATE
                     , CASE WHEN A.QMS_HOLD_RELEASE = '-' OR A.QMS_HOLD_RELEASE IS NULL THEN NULL ELSE TO_CHAR(FN_CHAR_TO_DATE(A.QMS_HOLD_RELEASE), 'YYYY-MM-DD') END AS QMS_UNHOLD_SCHD_DATE
                  FROM SSP_DNM_GMES_STOCK_81_82 A
                     , SCP_MST_FINAL_ITEM B
                 WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                   AND B.ITEM_ID(+) = A.ITEM_ID
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND A.COMPANY_ID = P_COMPANY_ID
                   AND A.YYYYMMDD = P_PLAN_START_YYYYMMDD
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   /* jilee 0901 */
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                    OR A.ATTRIBUTE5 IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                          FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                    /* OR A.ATTRIBUTE5 MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                    OR A.ATTRIBUTE5 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                        FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                   /* AND ((@p_item_id IS NULL OR @p_item_id ='')	OR ITEM_ID IN (SELECT token FROM dbo.String_Split(@p_item_id, ','))) */
                   AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                    OR B.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                           FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
                   AND (TRIM(P_BOX_ID) IS NULL
                    OR A.BOXID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(P_BOX_ID, ','))));

        END IF;

    END P_SSP0060_GET_MES_STOCK_DETAIL;
    PROCEDURE P_SSP0060_GET_OWMS_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0015_GET_WH_STOCK
 * Description  : Shipment PSI(Small)
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/10   mcTheJ			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
 * 2022.04.23   SSP Pjt.        C20220419-000607 / SSP~oWMS 사외창고 재고 I/F개선 요청
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_BOH_YYYYMMDD      VARCHAR2(8);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */

        /* 더블클릭 - W/H Stock Detail */
        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                             , A.GRADE
                             , A.CAPACITY_GRADE AS CAPA_GRADE
                             , A.SOC
                             , A.LOT_ID
                             , A.PALLET_ID
                             , A.STOCK_QTY
                             , A.AVAILABLE_QTY
                             , A.NON_QC_QTY AS UNDECIDED_QTY
                             , A.ALLOCATION_QTY
                             , A.BLOCK_QTY AS HOLD_QTY
                             , A.PACKING_QTY
                             , A.MOVING_QTY
                             , A.RCVLOC_QTY AS RECEIVING_QTY
                             , A.EXPIRATION_QTY
                             , A.LONG_QTY AS LONG_TERM_QTY
                             , A.PLANT_ID
                             , A.PACKING_STATUS
                             , A.STOCK_STATUS
                             , A.STORAGE_ID || ' ' || C.STORAGE_DESCRIPTION AS STORAGE_ID
                             , A.CUSTOMER_CODE
                             , A.CUSTOMER_NAME
                             , TO_CHAR(TO_DATE(A.LOT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS LOT_ISSUE_DATE
                          FROM SSP_ANL_OWMS_STOCK_C2 A
                             , SCM_ADM_LOOKUP_MASTER_DETAIL B
                             , SCM_MST_SLOC C
                             , SSP_MST_MODEL_USER D
                             , SCP_MST_FINAL_ITEM E
                         WHERE B.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'              /* C20220419-000607 */
                           AND B.VALID_YN = 'Y'
                           AND B.ATTRIBUTE1 = 'Y'
                           AND B.SEGMENT1 = A.STOCK_STATUS
                           AND C.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END)
                           AND C.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.PLANT_ID(+) = A.PLANT_ID
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.FROM_SITE(+) = A.FROM_SITE
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND D.VALID_YN(+) = 'Y'
                           AND E.DIVISION_ID(+) = A.DIVISION_ID
                           AND E.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND A.FROM_SITE = P_FROM_SITE
--                           AND A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                           /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                           AND A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
                           AND E.GROUP_CODE1 = P_PRODUCT_LEVEL1) IA
                 ORDER BY IA.DIVISION_ID, IA.PLANT_ID, IA.STORAGE_ID, IA.ITEM_ID, IA.GRADE, IA.CAPA_GRADE, IA.SOC, IA.LOT_ID, IA.PALLET_ID;

        /* 2. btnSearch */
        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                             , A.GRADE
                             , A.CAPACITY_GRADE AS CAPA_GRADE
                             , A.SOC
                             , A.LOT_ID
                             , A.PALLET_ID
                             , A.STOCK_QTY
                             , A.AVAILABLE_QTY
                             , A.NON_QC_QTY AS UNDECIDED_QTY
                             , A.ALLOCATION_QTY
                             , A.BLOCK_QTY AS HOLD_QTY
                             , A.PACKING_QTY
                             , A.MOVING_QTY
                             , A.RCVLOC_QTY AS RECEIVING_QTY
                             , A.EXPIRATION_QTY
                             , A.LONG_QTY AS LONG_TERM_QTY
                             , A.PLANT_ID
                             , A.PACKING_STATUS
                             , A.STOCK_STATUS
                             , A.STORAGE_ID || ' ' || C.STORAGE_DESCRIPTION AS STORAGE_ID
                             , A.CUSTOMER_CODE
                             , A.CUSTOMER_NAME
                             /* ,convert(nvarchar, convert(datetime,a.LOT_DATE,112), 23)  LOT_ISSUE_DATE */
                             , CASE WHEN TO_DATE(A.LOT_DATE DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD') IS NOT NULL
                                    THEN TO_CHAR(TO_DATE(A.LOT_DATE DEFAULT NULL ON CONVERSION ERROR, 'YYYYMMDD'), 'YYYY-MM-DD')
                                    ELSE A.LOT_DATE
                               END AS LOT_ISSUE_DATE
                          FROM SSP_ANL_OWMS_STOCK_C2 A
                             , SCM_ADM_LOOKUP_MASTER_DETAIL B
                             , SCM_MST_SLOC C
                             , SSP_MST_MODEL_USER D
                             , SCP_MST_FINAL_ITEM E
                         WHERE B.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'              /* C20220419-000607 */
                           AND B.VALID_YN = 'Y'
                           AND B.ATTRIBUTE1 = 'Y'
                           AND B.SEGMENT1 = A.STOCK_STATUS
                           AND C.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END)
                           AND C.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.PLANT_ID(+) = A.PLANT_ID
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.FROM_SITE(+) = A.FROM_SITE
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND D.VALID_YN(+) = 'Y'
                           AND E.DIVISION_ID(+) = A.DIVISION_ID
                           AND E.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.FROM_SITE IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                               FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                           AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                            OR E.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))) IA
                 ORDER BY IA.DIVISION_ID, IA.PLANT_ID, IA.STORAGE_ID, IA.ITEM_ID, IA.GRADE, IA.CAPA_GRADE, IA.SOC, IA.LOT_ID, IA.PALLET_ID;

        END IF;

    END P_SSP0060_GET_OWMS_DETAIL;

    PROCEDURE P_SSP0060_GET_STOCK_LOCATION_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_PLAN
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/06   mcThej			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/14   mcThej			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT - NICK NAME 추가
 * 2019/10/15   juhlee          Pack 생산 창고 추가 CMA_BMA . 2019.10.15 (requested by 김광희)
 * 2020/01/29   KIMYONGHO       [C20200121-000352]  ESS Packer출하 적용
                                 - [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V)
 * 2021/05/27   KIMYONGHO	    A/S PLANT ERP 재고 반영  수정
 * 2021/06/01   SSP Pjt.        AS ERP 재고 적용
 * 2021/06/14   SSP Pjt.        화면속도개선(SCM_DNM_STOCK_V -> SSP_DNM_STOCK_C)
 * 2023/09/11   jilee           반제품->제품코드 변환 작업
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭 상세는 정확일치(원래 = 비교)
 */
        V_BOH_YYYYMMDD      VARCHAR2(8);
        V_STOCK_YYYYMMDD    VARCHAR2(8);
        V_BOH_DATE          DATE;
        V_STOCK_DATE        DATE;
        V_PRODUCT_LEVEL1    VARCHAR2(4000);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_PLAN_START_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 3, 'YYYYMMDD'); /* FROM -3일 */

        /* 재고 테이블의 CUTOFF_DATE 는 날짜 형이라 값 쪽을 날짜로 맞춘다(칸에는 함수 미사용) */
        V_BOH_DATE := TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD');
        V_STOCK_DATE := TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD');

        V_PRODUCT_LEVEL1 := P_PRODUCT_LEVEL1;

        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             /* jilee 230911 */
                             , NVL(A.ATTRIBUTE1, A.ITEM_ID) AS ITEM_ID
                             /* ,STOCK.ITEM_ID */
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , NVL(B.STORAGE_DESCRIPTION, (SELECT SA.STORAGE_DESCRIPTION
                                                             FROM SCM_MST_SLOC SA
                                                            WHERE SA.PLANT_ID = A.PLANT_ID
                                                              AND SA.STORAGE_ID = A.STORAGE_ID
                                                              AND SA.VALID_YN = 'Y'
                                                              AND ROWNUM = 1)) AS STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_STOCK_C A                                /* SCM_DNM_STOCK_V */
                             , SCM_MST_SLOC B
                             , (SELECT XA.DIVISION_ID
                                     , XA.SCM_SITE_ID
                                     , XA.PLANT_ID
                                     , XA.STORAGE_ID
                                     , XA.LOCATION_CODE
                                  FROM SSP_MST_LOCATION_V XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                                   AND XA.PLANT_ID = XB.PLANT_ID
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.VALID_YN = 'Y'
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                 GROUP BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.PLANT_ID, XA.STORAGE_ID, XA.LOCATION_CODE
                                UNION ALL
                                SELECT DISTINCT XA.SEGMENT1 AS DIVISION_ID
                                     , XA.SEGMENT2 AS SCM_SITE_ID
                                     , XA.SEGMENT3 AS PLANT_ID
                                     , XA.SEGMENT4 AS STORAGE_ID
                                     , 'AS' AS LOCATION_CODE
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.SEGMENT1 = XB.DIVISION_ID
                                   AND XA.SEGMENT2 = XB.SCM_SITE_ID
                                   AND XA.SEGMENT3 = XB.PLANT_ID
                                   AND XA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                                   AND XA.VALID_YN = 'Y'
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.SEGMENT1 = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) C
                             , SCP_MST_FINAL_ITEM D
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = C.DIVISION_ID
                           AND A.STORAGE_ID = C.STORAGE_ID
                           AND A.PLANT_ID = C.PLANT_ID
                           AND A.SCM_SITE_ID = C.SCM_SITE_ID
                           AND C.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.SCM_SITE_ID = P_FROM_SITE
                           /* jilee */
--                           AND (A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                           /* AND (A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                           AND (A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
--                            OR A.ATTRIBUTE1 = P_ITEM_ID)   --  2026.10.07 AJS
                            /* OR A.ATTRIBUTE1 MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ATTRIBUTE1 = P_ITEM_ID)   /* AJS 20261008 Model/Nickname */
                           AND D.GROUP_CODE1 = V_PRODUCT_LEVEL1
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE                 /* 현재일 - 3 */
                           AND A.STOCK_TYPE = 'INVENTORY'
                        /* [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V) */
                        /* SSP_DNM_ESS_PACKER_STOCK_V  ESS(82) PACKER STOCK,  STORAGE_ID : 6000(구미 People works), E400(남경 People works) */
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , B.STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_ESS_PACKER_STOCK_V A
                             , SCM_MST_SLOC B
                             , SCP_MST_FINAL_ITEM C
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.DIVISION_ID(+) = A.DIVISION_ID
                           AND C.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND A.SCM_SITE_ID = P_FROM_SITE
--                           AND A.ITEM_ID = P_ITEM_ID   --  2026.10.07 AJS
                           /* AND A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                           AND A.ITEM_ID = P_ITEM_ID   /* AJS 20261008 Model/Nickname */
                           AND C.GROUP_CODE1 = V_PRODUCT_LEVEL1
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE) IA             /* 현재일 - 3 */
                 ORDER BY IA.COMPANY_ID, IA.DIVISION_ID, IA.FROM_SITE, IA.PLANT_ID, IA.ITEM_ID, IA.STOCK_TYPE, IA.STORAGE_ID;

        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             /* jilee 230911 */
                             , NVL(A.ATTRIBUTE1, A.ITEM_ID) AS ITEM_ID
                             /* ,STOCK.ITEM_ID */
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , NVL(B.STORAGE_DESCRIPTION, (SELECT SA.STORAGE_DESCRIPTION
                                                             FROM SCM_MST_SLOC SA
                                                            WHERE SA.PLANT_ID = A.PLANT_ID
                                                              AND SA.STORAGE_ID = A.STORAGE_ID
                                                              AND SA.VALID_YN = 'Y'
                                                              AND ROWNUM = 1)) AS STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_STOCK_C A                                /* SCM_DNM_STOCK_V */
                             , SCM_MST_SLOC B
                             , (SELECT XA.DIVISION_ID
                                     , XA.SCM_SITE_ID
                                     , XA.PLANT_ID
                                     , XA.STORAGE_ID
                                     , XA.LOCATION_CODE
                                  FROM SSP_MST_LOCATION_V XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                                   AND XA.PLANT_ID = XB.PLANT_ID
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.VALID_YN = 'Y'
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                 GROUP BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.PLANT_ID, XA.STORAGE_ID, XA.LOCATION_CODE
                                UNION ALL
                                SELECT DISTINCT XA.SEGMENT1 AS DIVISION_ID
                                     , XA.SEGMENT2 AS SCM_SITE_ID
                                     , XA.SEGMENT3 AS PLANT_ID
                                     , XA.SEGMENT4 AS STORAGE_ID
                                     , 'AS' AS LOCATION_CODE
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL XA
                                     , SCM_MST_SITE XB
                                 WHERE XA.SEGMENT1 = XB.DIVISION_ID
                                   AND XA.SEGMENT2 = XB.SCM_SITE_ID
                                   AND XA.SEGMENT3 = XB.PLANT_ID
                                   AND XA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                                   AND XA.VALID_YN = 'Y'
                                   AND XB.DIVISION_ID = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND XB.VALID_YN = 'Y'
                                   AND XB.SITE_TYPE = 'PLANT'
                                   AND XA.SEGMENT1 = P_DIVISION_ID
                                   AND XB.COMPANY_ID = P_COMPANY_ID
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                         FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) C
                             , SCP_MST_FINAL_ITEM D
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND A.DIVISION_ID = C.DIVISION_ID
                           AND A.STORAGE_ID = C.STORAGE_ID
                           AND A.PLANT_ID = C.PLANT_ID
                           AND A.SCM_SITE_ID = C.SCM_SITE_ID
                           AND C.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                           AND D.DIVISION_ID(+) = A.DIVISION_ID
                           AND D.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           /* jilee */
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                               FROM TABLE(STRING_SPLIT(P_ITEM_ID, ',')))   --  2026.10.07 AJS
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB   --  2026.10.07 AJS */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB))   /* AJS 20261008 Model/Nickname */
--                            OR A.ATTRIBUTE1 IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                  FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR A.ATTRIBUTE1 MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ATTRIBUTE1 IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                           AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                            OR D.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE                 /* 현재일 - 3 */
                           AND A.STOCK_TYPE = 'INVENTORY'
                        /* [C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V) */
                        /* SSP_DNM_ESS_PACKER_STOCK_V  ESS(82) PACKER STOCK,  STORAGE_ID : 6000(구미 People works), E400(남경 People works) */
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.COMPANY_ID
                             , A.CUTOFF_DATE AS CUTOFF_DATE
                             , A.SCM_SITE_ID AS FROM_SITE
                             , A.PLANT_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.STOCK_TYPE
                             , A.STORAGE_ID
                             , B.STORAGE_DESCRIPTION
                             , NVL(A.SCM_QTY, 0) AS TOTAL_QTY
                             , NVL(A.SSP_QTY, 0) AS AVAILABLE_QTY
                             , A.DEFECT_QTY
                             , A.MOVING_QTY
                             , A.QTY_UOM
                             , NVL(A.WIPHOLD_YN, 'N') AS WIPHOLD_YN
                             , A.HOLDING_DATE
                             , A.AVAILABLE_DATE
                             , A.OUTSOURCING_FLAG
                             , A.OUTSOURCING_FACTORY
                          FROM SSP_DNM_ESS_PACKER_STOCK_V A
                             , SCM_MST_SLOC B
                             , SCP_MST_FINAL_ITEM C
                         WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                           AND B.PLANT_ID(+) = A.PLANT_ID
                           AND B.STORAGE_ID(+) = A.STORAGE_ID
                           AND C.DIVISION_ID(+) = A.DIVISION_ID
                           AND C.ITEM_ID(+) = A.ITEM_ID
                           AND A.DIVISION_ID = P_DIVISION_ID
                           AND A.COMPANY_ID = P_COMPANY_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR A.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                               FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                             FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                           AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                            OR C.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                   FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
                           AND A.CUTOFF_DATE = V_BOH_DATE
                           AND A.CUTOFF_DATE > V_STOCK_DATE) IA             /* 현재일 - 3 */
                 ORDER BY IA.COMPANY_ID, IA.DIVISION_ID, IA.FROM_SITE, IA.PLANT_ID, IA.ITEM_ID, IA.STOCK_TYPE, IA.STORAGE_ID;

        END IF;

    END P_SSP0060_GET_STOCK_LOCATION_DETAIL;
    PROCEDURE P_SSP0060_GET_SHIPMENT_RESULT
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_TYPE                  IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_MYMODELCHK            IN  VARCHAR2
       ,P_PARTLEADERCHK         IN  VARCHAR2
       ,P_TEAMLEADERCHK         IN  VARCHAR2
       ,P_DELEGATEECHK          IN  VARCHAR2
       ,P_NONCHK                IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_RESULT
 * Description  : Shipment Shipment Result
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/26   AYJ			[CSR ID:4037234] 출하계획 대비 실적 Report 개발
 * 2019/12/04   juhlee      [C20191205-000132]  OWMS 출하실적에 반품 내용 적용 ( SSP_DNM_SHIP_RESULT_OWMS_V)
 * 2020/01/21   juhlee          [C20200121-000352]  ESS Packer출하 적용
								 - [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> 'Y' 조건제외)
 * 2020/02/12   KIMYONGHO   [C20200218-000135]  SHIP_TYPE 컬럼추가 및  FROM_STIE, TO_SITE Display 변경 CDOE - > Discription
 * 2020.05.06	KIMYONGHO   [C20200403-000062] [GSCM PI] SSP 출하 실적 집계 중 사외 창고 제외 로직 추가 건
 * 2020.09.15	KIMYONGHO   PLAN_SSP 조회시 AND 조건 일부 변경
 * 2020.09.18	KIMYONGHO   ERP_ORDER_TYPE 주석 처리 Request by 김광희 책임
 * 2021.02.17	KIMYONGHO   실적 조회시 TRNSPORT_MODE, INCOTERMS, ERP_SO_NO, ETA_DATE, ETD_DATE ERP 실적 기준으로 조회 Request by 김광희 책임
 * 2021.04.05   KIMYONGHO   [C20210330-000402] Shipment Plan화면의 실적 조회시 Sales site Mapping 안되는건에 대해서도 전수 표시 요청
 * 2021.05.03   SSP Pjt.    ERP_ORDER_TYPE 주석 처리 해제 Request by 김광희 책임
 * 2021.11.15   KIMYONGHO   Confirm Data Plan Date 기준 조회 처리
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 같은 조건을 실적 원장 6곳에도 먼저 적용(후보 1,000건 이하 MEMBER OF · 초과 IN(TABLE))
 */
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
        V_ITEM_SMALL_YN         VARCHAR2(1) := 'N';   /* AJS 20261008 Model/Nickname : 후보 1,000건 이하면 Y — 실적 원장 단계 MEMBER OF(인덱스 단계에서 거름) */
        V_ITEM_BIG_YN           VARCHAR2(1) := 'N';   /* AJS 20261008 Model/Nickname : 후보 1,000건 초과면 Y — 실적 원장 단계 IN(TABLE) */
        V_ITEM_BIG_TAB          T_STR_TAB := T_STR_TAB();   /* AJS 20261008 Model/Nickname : 후보가 많을 때만 후보 목록 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* AJS 20261008 Model/Nickname : 후보 수에 따라 실적 원장 단계 비교 방식 선택(결과 동일) */
        IF TRIM(P_ITEM_ID) IS NOT NULL AND UPPER(TRIM(P_ITEM_ID)) <> 'ALL' THEN   /* AJS 20261008 Model/Nickname */
            IF V_ITEM_TAB.COUNT <= 1000 THEN   /* AJS 20261008 Model/Nickname */
                V_ITEM_SMALL_YN := 'Y';   /* AJS 20261008 Model/Nickname */
            ELSE   /* AJS 20261008 Model/Nickname */
                V_ITEM_BIG_YN := 'Y';   /* AJS 20261008 Model/Nickname */
                V_ITEM_BIG_TAB := V_ITEM_TAB;   /* AJS 20261008 Model/Nickname */
            END IF;   /* AJS 20261008 Model/Nickname */
        END IF;   /* AJS 20261008 Model/Nickname */

        OPEN O_RC1 FOR
            SELECT IA.DIVISION_ID
                 , B.COMPANY_ID AS COMPANY_ID
                 , C.SEGMENT2 AS TYPE
                 , IA.ERP_SO_NO
                 , IA.CONFIRM_ID
                 , IA.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(IA.DIVISION_ID, IA.ITEM_ID) AS NICK_NAME
                 /* ,      X.FROM_SITE */
                 /* ,      X.TO_SITE */
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.FROM_SITE), IA.FROM_SITE) AS FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(IA.DIVISION_ID, IA.TO_SITE), IA.TO_SITE) AS TO_SITE
                 , IA.END_CUSTOMER
                 , IA.QTY
                 , TO_CHAR(TO_DATE(IA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS YYYYMMDD
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , TO_CHAR(TO_DATE(IA.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD_DATE
                 , TO_CHAR(TO_DATE(IA.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA_DATE
                 , IA.SHIP_TYPE
              FROM (/* CONFIRM_ID ,날짜동일한 기준으로 계획정보의 FROM, TO SITE기준으로 실적 집계 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , XA.CONFIRM_ID AS CONFIRM_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , SUM(XA.RESULT_QTY) AS QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ORDER_NO AS ERP_SO_NO
                                 , SA.EXFACTORY_DATE AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETA_DATE AS ETA_DATE
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , SA.TO_SCM_SITE_ID AS TO_SITE
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SUM(SA.EXFACTORY_QTY) AS RESULT_QTY
                              FROM SCM_DNM_EXFACTORY_RESULT SA
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SB
                                 , SCM_MST_SITE SC
                                 , SCM_MST_ITEM_SN SD
                             WHERE SB.LOOKUP_TYPE = 'ERP_SSP_TYPE'              /* LOOKUP에 등록된 공정만 */
                               AND SB.VALID_YN = 'Y'
                               AND SB.SEGMENT1 = SA.SSP_TYPE
                               AND SA.FROM_SCM_SITE_ID = SC.SCM_SITE_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SC.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SD.ITEM_ID
                               AND SA.DIVISION_ID = SD.DIVISION_ID
                               AND SC.COMPANY_ID = SD.COMPANY_ID
                               AND SD.ITEM_TYPE NOT IN ('Q', 'R')
                               AND NVL(SA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND SA.CONFIRM_ID LIKE 'C%'
                               AND SA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.CONFIRM_ID
                                    , SA.ORDER_NO
                                    , SA.EXFACTORY_DATE
                                    , SA.TRANSPORT_MODE
                                    , SA.INCOTERMS
                                    , SA.ETA_DATE
                                    , SA.ETD_DATE
                                    , SA.FROM_SCM_SITE_ID
                                    , SA.TO_SCM_SITE_ID
                                    , SA.ITEM_ID) XA
                     GROUP BY XA.DIVISION_ID
                            , XA.ERP_SO_NO
                            , XA.FROM_SITE
                            , XA.TO_SITE
                            , XA.ITEM_ID
                            , XA.TRANSPORT_MODE
                            , XA.INCOTERMS
                            , XA.ETD_DATE
                            , XA.ETA_DATE
                            , XA.YYYYMMDD
                            , XA.CONFIRM_ID
                    UNION ALL
                    /* CONFIRM_ID 없는 실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'E' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , '-' AS CONFIRM_ID
                                 , SA.ORDER_NO AS ERP_SO_NO
                                 , SA.FROM_SCM_SITE_ID AS FROM_SITE
                                 , NVL(SG.SEGMENT4, SA.TO_SCM_SITE_ID) AS TO_SITE
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.EXFACTORY_DATE AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETA_DATE AS ETA_DATE
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SUM(SA.EXFACTORY_QTY) AS QTY
                              FROM SCM_DNM_EXFACTORY_RESULT SA
                                 , SCM_MST_SITE SB
                                 , SCM_MST_ITEM_SN SC
                                 , SCP_MST_FINAL_ITEM SD
                                 , SCM_MST_SITE SE
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SF
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL SG
                             WHERE SA.FROM_SCM_SITE_ID = SB.SCM_SITE_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SC.ITEM_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SB.COMPANY_ID = SC.COMPANY_ID
                               AND SC.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SD.ITEM_ID = SA.ITEM_ID                      /* SCP 대상 ITEM만 */
                               AND SD.DIVISION_ID = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID = SA.FROM_SCM_SITE_ID
                               AND SE.DIVISION_ID = SA.DIVISION_ID
                               /* AND ISNULL(FS.OSP_YN,'N') <> 'Y' --- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN <> 'Y' 조건제외) */
                               /* 2020.09.18 김광희 책임 요청으로 주석처리 */
                               /* 2021.04.15 김광희 책임 요청으로 주석해제 */
                               AND SF.LOOKUP_TYPE = 'ERP_ORDER_TYPE'            /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                               AND SF.VALID_YN = 'Y'
                               AND SF.SEGMENT1 = SA.ORDER_TYPE_CODE
                               AND SG.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'    /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                               AND SG.SEGMENT1(+) = SA.DIVISION_ID
                               AND SG.SEGMENT2(+) = SA.SOLDTO_CODE
                               AND SG.SEGMENT3(+) = SA.SHIPTO_CODE
                               AND NVL(SA.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')    /* D90: DO삭제 , D10:DO생성 */
                               AND (SA.CONFIRM_ID IS NULL OR SA.CONFIRM_ID NOT LIKE 'C%')
                               AND SA.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               /* [C20210330-000402] */
                               /* AND   E.FROM_SCM_SITE_ID IS NOT NULL */
                               /* AND   E.TO_SCM_SITE_ID IS NOT NULL */
                               AND SA.STORAGE_ID NOT IN ('6000', '799A')        /* 상품창고제외 */
                               /* [C20200403-000062] */
                               AND NOT EXISTS (SELECT 1
                                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SH
                                                WHERE SH.SEGMENT1 = SA.STORAGE_ID
                                                  AND SH.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                                  AND SH.VALID_YN = 'Y')        /* 사외 창고 제외 LOOKUP 관리 */
                               /* AND   E.ORDER_TYPE_CODE  IN ('ZEF','ZEFC','ZEML','ZEMM','ZEX','ZFD','ZFR','ZKB','ZMM','ZOR','ZFDC','ZKM') -- 해당 ORDER_TYPE만 대상으로 함 */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ORDER_NO
                                    , SA.FROM_SCM_SITE_ID
                                    , NVL(SG.SEGMENT4, SA.TO_SCM_SITE_ID)
                                    , SA.ITEM_ID
                                    , SA.EXFACTORY_DATE
                                    , SA.TRANSPORT_MODE
                                    , SA.INCOTERMS
                                    , SA.ETA_DATE
                                    , SA.ETD_DATE
                                    , SA.FROM_SCM_SITE_ID
                                    , SA.TO_SCM_SITE_ID) XA
                    UNION ALL
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'P' AS TYPE
                         , XA.ERP_SO_NO AS ERP_SO_NO
                         , XA.CONFIRM_ID AS CONFIRM_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , XA.END_CUSTOMER AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.ETD_DATE AS ETD_DATE
                         , XA.ETA_DATE AS ETA_DATE
                         , NULL AS SHIP_TYPE
                      FROM (/* SSP출하계획 ( confirm된 계획) - Current Version */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ERP_SO_NO AS ERP_SO_NO
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , SA.TO_SITE AS TO_SITE
                                 , CASE WHEN SA.DIVISION_ID = '4O' THEN NVL(SD.PROJECT_CODE, '/')
                                        ELSE NVL(SE.END_CUSTOMER, '-')
                                   END AS END_CUSTOMER
                                 , SA.QTY AS QTY
                                 , SA.YYYYMMDD AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETD_DATE AS ETD_DATE
                                 , SA.ETA_DATE AS ETA_DATE
                              FROM SSP_ANL_SHIP_CONFIRM SA
                                 , SCM_MST_SITE SB
                                 , SCM_MST_ITEM_SN SC
                                 , SCM_MST_SITE_ITEM SD
                                 , SCM_MST_SITE SE
                             WHERE SA.FROM_SITE = SB.SCM_SITE_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SA.ITEM_ID = SC.ITEM_ID
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SB.COMPANY_ID = SC.COMPANY_ID
                               AND SC.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SD.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SD.ITEM_ID(+) = SA.ITEM_ID
                               AND SD.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SD.PROJECT_CODE(+) = SA.PROJECT_CODE
                               AND SE.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SA.CHANGE_TYPE = 'C'
                               AND SA.QTY > 0
                               AND P_REAL_FLAG = 'Y'
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               /* 2020.09.15 KIMYONGHO   PLAN_SSP 조회시 AND 조건 일부 변경 */
                               /* ERP 출하 구간과 SSP 출하계획일 구간 미스매치로 일부 데이터 누락될수있음. */
                               /* AND   YYYYMMDD BETWEEN  @p_from_yyyymmdd  AND @p_to_yyyymmdd */
                            UNION ALL
                            /* SSP출하계획 ( confirm된 계획) - OLD Version */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ERP_SO_NO AS ERP_SO_NO
                                 , SA.CONFIRM_ID AS CONFIRM_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , SA.TO_SITE AS TO_SITE
                                 , CASE WHEN SA.DIVISION_ID = '4O' THEN NVL(SD.PROJECT_CODE, '/')
                                        ELSE NVL(SE.END_CUSTOMER, '-')
                                   END AS END_CUSTOMER
                                 , SA.SHIPMENT_CONFIRM_QTY AS QTY
                                 , SA.YYYYMMDD AS YYYYMMDD
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.ETD AS ETD_DATE
                                 , SA.ETA AS ETA_DATE
                              FROM SSP_ANL_SHIP_PLAN_ALL SA
                                 , SCM_MST_ITEM_SN SB
                                 , SCM_MST_SITE SC
                                 , SCM_MST_SITE_ITEM SD
                                 , SCM_MST_SITE SE
                             WHERE SA.ITEM_ID = SB.ITEM_ID
                               AND SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.COMPANY_ID = SB.COMPANY_ID
                               AND SB.ITEM_TYPE NOT IN ('Q', 'R')
                               AND SA.DIVISION_ID = SC.DIVISION_ID
                               AND SA.FROM_SITE = SC.SCM_SITE_ID
                               AND SC.SITE_TYPE = 'PLANT'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SC.OPERATION_GROUP <> 'E'
                               AND SD.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SD.ITEM_ID(+) = SA.ITEM_ID
                               AND SD.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SD.PROJECT_CODE(+) = SA.PROJECT_CODE
                               AND SE.DIVISION_ID(+) = SA.DIVISION_ID
                               AND SE.SCM_SITE_ID(+) = SA.TO_SITE
                               AND SA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND SA.SHIPMENT_STATUS = 'C'
                               AND SA.SHIPMENT_CONFIRM_QTY > 0
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                               AND P_REAL_FLAG = 'N') XA
                     WHERE XA.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                    UNION ALL
                    /* OWMS 실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'O' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , XA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하실적 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , CASE WHEN SA.TO_SITE = '-' THEN SA.CUSTOMER_CODE ELSE SA.TO_SITE END AS TO_SITE
                                 , SUM(SA.LOT_QTY) AS QTY
                                 , SA.PLANT_ISSUE_DATE AS YYYYMMDD
                                 , SA.SHIP_TYPE AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RESULT_OWMS SA
                             WHERE SA.PLANT_ISSUE_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ITEM_ID
                                    , SA.FROM_SITE
                                    , CASE WHEN SA.TO_SITE = '-' THEN SA.CUSTOMER_CODE ELSE SA.TO_SITE END
                                    , SA.PLANT_ISSUE_DATE
                                    , SA.SHIP_TYPE) XA
                    UNION ALL
                    /* OWMS 반품실적 */
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , 'R' AS TYPE
                         , NULL AS ERP_SO_NO
                         , NULL AS CONFIRM_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.TO_SITE AS TO_SITE
                         , NULL AS END_CUSTOMER
                         , XA.QTY AS QTY
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NULL AS TRANSPORT_MODE
                         , NULL AS INCOTERMS
                         , NULL AS ETD_DATE
                         , NULL AS ETA_DATE
                         , XA.SHIP_TYPE AS SHIP_TYPE
                      FROM (/* owms 출하 반품 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , '*' AS TO_SITE
                                 , SUM(SA.RECIEPT_QTY) AS QTY
                                 , SA.RECIEPT_DATE AS YYYYMMDD
                                 , NULL AS SHIP_TYPE
                              FROM SSP_DNM_SHIP_RETURN_OWMS SA
                             WHERE SA.RECIEPT_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                               AND (V_ITEM_SMALL_YN = 'N'   /* AJS 20261008 Model/Nickname : 바깥 Model 조건을 실적 원장 단계에서 먼저 적용(결과 동일) — 후보가 적을 때 */
                                OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   /* AJS 20261008 Model/Nickname */
                               AND (V_ITEM_BIG_YN = 'N'   /* AJS 20261008 Model/Nickname : 후보가 많을 때 */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                    FROM TABLE(V_ITEM_BIG_TAB)))   /* AJS 20261008 Model/Nickname */
                             GROUP BY SA.DIVISION_ID
                                    , SA.ITEM_ID
                                    , SA.FROM_SITE
                                    , SA.RECIEPT_DATE) XA) IA
                 , SCM_MST_SITE B
                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
                 , SSP_MST_MODEL_USER D
                 , SCP_MST_FINAL_ITEM E
             WHERE B.DIVISION_ID = IA.DIVISION_ID
               AND B.SCM_SITE_ID = IA.FROM_SITE
               AND B.OPERATION_GROUP <> 'E'
               AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE'                   /* LOOKUP에 등록된 공정만 */
               AND C.SEGMENT1 = IA.TYPE
               AND C.VALID_YN = 'Y'
               AND D.DIVISION_ID(+) = IA.DIVISION_ID
               AND D.FROM_SITE(+) = IA.FROM_SITE
               AND D.ITEM_ID(+) = IA.ITEM_ID
               AND D.VALID_YN(+) = 'Y'
               AND E.DIVISION_ID(+) = IA.DIVISION_ID
               AND E.ITEM_ID(+) = IA.ITEM_ID
               AND IA.DIVISION_ID = P_DIVISION_ID
               AND (TRIM(P_COMPANY_ID) IS NULL
                OR B.COMPANY_ID = P_COMPANY_ID)
               AND (TRIM(P_FROM_SITE) IS NULL
                OR IA.FROM_SITE IN (SELECT COLUMN_VALUE
                                      FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
               AND (TRIM(P_ITEM_ID) IS NULL
                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                OR IA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                /* OR IA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                OR IA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
               AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                OR E.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
               AND (TRIM(P_TYPE) IS NULL
                OR IA.TYPE IN (SELECT COLUMN_VALUE
                                 FROM TABLE(STRING_SPLIT(P_TYPE, ','))))
               /* 체크박스 체크 여부 조회 시작(@p_nonChk = 'Y' : 체크박스 선택 안한 상태) */
               AND (P_NONCHK = 'Y'
                OR D.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                   FROM DUAL
                                  UNION
                                 SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN XA.USER_ID ELSE 'X' END
                                   FROM SSP_MST_DELEGATE XA
                                  WHERE XA.VALID_YN = 'Y'
                                    AND XA.DELEGATEE_ID = P_USER_ID
                                  GROUP BY XA.USER_ID)
                OR D.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                OR D.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             ORDER BY IA.DIVISION_ID, IA.FROM_SITE, IA.YYYYMMDD, IA.ITEM_ID, IA.TO_SITE, C.DISPLAY_SEQ, IA.CONFIRM_ID;

    END P_SSP0060_GET_SHIPMENT_RESULT;

    PROCEDURE P_SSP0060_GET_SHIPMENT_REQUEST_CONFIRM_DRAFTING
    (
        P_CHANGE_REQUEST_NO     IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_REQUEST_CONFIRM_DRAFTING
 * Description  : Shipment Change Request 확정
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024/06/19   hsbang         Initial Release
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_CHANGE_REQUEST_NO     VARCHAR2(40);
    BEGIN

        IF (LENGTH(RTRIM(P_CHANGE_REQUEST_NO)) > 0) THEN

            V_CHANGE_REQUEST_NO := P_CHANGE_REQUEST_NO;

        ELSE

            BEGIN
                SELECT CHANGE_REQ_NO
                  INTO V_CHANGE_REQUEST_NO
                  FROM (SELECT IA.CHANGE_REQ_NO
                          FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ IA
                         WHERE IA.CHANGE_TYPE = 'C'
                           AND IA.CHANGE_REQ_STATUS = 'Q'
                           AND IA.VALID_YN = 'N'
                           AND IA.REQUEST_USER = P_USER_ID
                         ORDER BY IA.CHANGE_REQ_NO DESC)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_CHANGE_REQUEST_NO := NULL;
            END;

        END IF;

        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ERP_SO_NO
                 , A.PROJECT_CODE
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE FN_GET_PROJECT_NAME(A.DIVISION_ID, A.PROJECT_CODE) END AS PROJECT_NAME
                 /* , D.PROJECT_NAME */
                 , A.FCST_TYPE
                 , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                 , D.GROUP_CODE1 AS PRODUCT_LEVEL1
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                 , A.TO_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION
                 , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                 , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                 /* , B.INCOTERMS */
                 , B.SSP_INCOTERMS AS INCOTERMS                                 /* 20201223 INCOTERMS 변경 작업 MODIFY KIMYONGHO */
                 , B.TRANSPORT_MODE
                 , CASE WHEN A.YYYYMMDD IS NULL THEN NULL ELSE TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                 , A.QTY AS SHIPMENT_CONFIRM_QTY
                 , A.BOD_ID
                 , A.ROUTE_ID
                 , B.LT_TOTAL AS LT_DAY
                 , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                 , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                 , A.NEW_BOD_ID
                 , A.NEW_ROUTE_ID
                 , A.NEW_D_COUNTRY
                 , A.NEW_D_PORT_CODE
                 , A.NEW_A_COUNTRY
                 , A.NEW_A_PORT_CODE
                 , A.NEW_TO_COUNTRY
                 , A.NEW_TO_CITY
                 , A.NEW_CUSTOMER_LT AS NEW_LT_DAY
                 , TO_CHAR(TO_DATE(A.NEW_ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                 , TO_CHAR(TO_DATE(A.NEW_ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                 , A.NEW_INCOTERMS AS NEW_INCOTERMS
                 , A.NEW_TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                 , A.ELECTRODE_YN
                 , A.ELECTRODE_TYPE
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID
                 , CASE WHEN A.NEW_YYYYMMDD IS NULL THEN NULL ELSE TO_CHAR(TO_DATE(A.NEW_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_SHIPMENT_DATE
                 , A.NEW_QTY AS NEW_SHIPMENT_CONFIRM_QTY
                 , NVL(A.NEW_QTY, 0) - NVL(A.QTY, 0) AS DIFF_QTY
                 , A.CONFIRM_ID
                 , A.CHANGE_REQ_NO
                 , A.NEW_YN
                 , (CASE WHEN C.CONFIRM_ID IS NOT NULL THEN 'Y' ELSE 'N' END) AS NEW_BASE_CONFIRM_YN
                 , 'N' AS EDIT_REMARKS
                 , 'N' AS EDIT_MAIN
                 , A.REMARKS
                 , A.REMARKS2
                 , A.REMARKS3
                 , (CASE WHEN C.CONFIRM_ID IS NULL THEN 'M' ELSE 'I' END) AS ACT_FLAG      /* 추가: 'I', 수정: 'M' */
                 /**** 20211018   SHINMYUNGSU   항목추가   ******************************************/
                 , A.ERP_ATTR1 AS ERP_ATTR1
                 , A.ERP_ATTR2 AS ERP_ATTR2
                 , A.ERP_ATTR3 AS ERP_ATTR3
                 /**** 20240416   HSBANG   항목추가   ******************************************/
                 , A.ATTRIBUTE2 AS STATUS_DETAIL
                 , A.ATTRIBUTE3 AS REJECT_REASON
                 , A.ATTRIBUTE4 AS CHANGE_REASON_CODE
                 , A.ATTRIBUTE5 AS CHANGE_REASON_DETAIL
                 /***********************************************************************************/
              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE A
                 , SCP_MST_BOD_N_V B
                 , (SELECT XA.CONFIRM_ID
                         , XA.DIVISION_ID
                         , CASE WHEN (XA.SHIPMENT_STATUS <> 'P' AND XA.CHANGE_TYPE = 'P' AND XA.ATTRIBUTE1 IS NOT NULL) THEN XA.ATTRIBUTE1 ELSE XA.CONFIRM_ID END AS MATCH_CONFIRM_ID
                      FROM SSP_ANL_SHIP_CONFIRM XA) C
                 , SCP_MST_FINAL_ITEM D
             WHERE (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = B.DIVISION_ID
               AND A.BOD_ID = B.BOD_ID
               AND C.DIVISION_ID(+) = A.DIVISION_ID
               AND C.MATCH_CONFIRM_ID(+) = A.CONFIRM_ID
               AND D.DIVISION_ID(+) = A.DIVISION_ID
               AND D.ITEM_ID(+) = A.ITEM_ID
               AND A.CHANGE_REQ_NO = V_CHANGE_REQUEST_NO
             ORDER BY NEW_SHIPMENT_DATE;

        OPEN O_RC2 FOR
            SELECT A.CHANGE_REQ_NO
                 , A.CHANGE_REQ_STATUS
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , A.REQUEST_TITLE
                 /* ,REQUEST_USER */
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN P_LANGUAGE = 'KO' THEN D.USERNAME ELSE D.USERNAME_E END AS REQUEST_USER
                 , CASE WHEN P_LANGUAGE = 'KO' THEN D.USER_NM ELSE D.USER_ENG_NM END AS REQUEST_USER
                 /* 2026.09.30 AJS 수정 (END) */
                 /* ,REQUEST_DEPT */
                 , CASE WHEN P_LANGUAGE = 'KO' THEN C.DEPT_NAME_KO
                        WHEN P_LANGUAGE = 'EN' THEN C.DEPT_NAME_EN
                        WHEN P_LANGUAGE = 'CN' THEN C.DEPT_NAME_CN
                        ELSE C.DEPT_NAME_KO
                   END AS REQUEST_DEPT
                 , A.REQUEST_TIME
                 /* ,APPROVAL_USER */
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN P_LANGUAGE = 'KO' THEN E.USERNAME ELSE E.USERNAME_E END AS APPROVAL_USER
                 , CASE WHEN P_LANGUAGE = 'KO' THEN E.USER_NM ELSE E.USER_ENG_NM END AS APPROVAL_USER
                 /* 2026.09.30 AJS 수정 (END) */
                 /* ,APPROVAL_DEPT */
                 , CASE WHEN P_LANGUAGE = 'KO' THEN B.DEPT_NAME_KO
                        WHEN P_LANGUAGE = 'EN' THEN B.DEPT_NAME_EN
                        WHEN P_LANGUAGE = 'CN' THEN B.DEPT_NAME_CN
                        ELSE B.DEPT_NAME_KO
                   END AS APPROVAL_DEPT_NAME
                 , A.APPROVAL_TIME
                 , CASE WHEN P_LANGUAGE = 'KO' THEN F.SEGMENT2 ELSE F.SEGMENT3 END AS CHANGE_REASON_CODE
                 /* ,CHANGE_REASON_CODE */
                 , A.CHANGE_REASON_DETAIL
                 , A.REJECT_REASON
              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ A
                 , SCM_MST_SSO_DEPT_INFO B
                 , SCM_MST_SSO_DEPT_INFO C
                 /* 2026.09.30 AJS 수정 (START) */
               --, TB_FX_USER D
               --, TB_FX_USER E
                 , SCM_ADM_USER_M D
                 , SCM_ADM_USER_M E
                 /* 2026.09.30 AJS 수정 (END) */
                 , SCM_ADM_LOOKUP_MASTER_DETAIL F
             WHERE A.APPROVAL_DEPT = B.DEPT_ID(+)
               AND A.REQUEST_DEPT = C.DEPT_ID(+)
               /* 2026.09.30 AJS 수정 (START) */
             --AND A.REQUEST_USER = D.USERID(+)
             --AND A.APPROVAL_USER = E.USERID(+)
               AND A.REQUEST_USER = D.USER_ID(+)
               AND A.APPROVAL_USER = E.USER_ID(+)
               /* 2026.09.30 AJS 수정 (END) */
               AND A.CHANGE_REASON_CODE = F.SEGMENT1(+)
               AND F.LOOKUP_TYPE(+) = 'CHANGE_REASON_CODE'
               AND F.VALID_YN(+) = 'Y'
               AND A.CHANGE_REQ_NO = V_CHANGE_REQUEST_NO;

    END P_SSP0060_GET_SHIPMENT_REQUEST_CONFIRM_DRAFTING;

    PROCEDURE P_SSP0060_GET_SHIPMENT_PLAN
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_PLAN
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/06   mcThej			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/10/15   juhlee          Pack 생산 창고 추가 CMA_BMA
 * 2020/01/29   KIMYONGHO       [C20200121-000352]  ESS Packer출하 적용
 * 2021/06/14   SSP Pjt.        화면속도개선(SCM_DNM_STOCK_V -> SSP_DNM_STOCK_C)
 * 2023/09/11   jilee           반제품->제품코드 변환 작업
 * 2024.05.16   hsbang          확정구간 조회 일수 펑션 수정(FN_GET_ANL_SHIP_FROZEN_DAY_CNT)
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026/08/11   [E20260811-000692] ESMI AZ 링크 2호기 생산계획 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 - 입고예정(PROD_PLAN) 도착일 함수를 인자 조합마다 1회 호출(결과 동일)
 * 2026.10.07   AJS          화면검증 — 사용자 측정값 설정은 측정값 행(M)만(칸 설정 행 C 제외)
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음
 */
        V_FROM_YYYYMMDD         VARCHAR2(8);
        V_TO_YYYYMMDD           VARCHAR2(8);
        V_BOH_YYYYMMDD          VARCHAR2(8);
        V_STOCK_YYYYMMDD        VARCHAR2(8);
        V_BOH_DATE              DATE;
        V_STOCK_DATE            DATE;
        V_CNT_USR_MEASURE       NUMBER := 0;
        V_APP_TYPE              VARCHAR2(8) := 'SSP';
        V_QRY_SUM               CLOB;
        V_EXEC                  CLOB;
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        V_FROM_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');
        V_TO_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_TO_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD'), 'YYYYMMDD');
        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 1, 'YYYYMMDD');    /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(SUBSTR(REPLACE(P_FROM_YYYYMMDD, '-', ''), 1, 8), 'YYYYMMDD') - 3, 'YYYYMMDD');  /* FROM -3일 */
        V_BOH_DATE := TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD');
        V_STOCK_DATE := TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD');

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID
           AND USER_INQUIRY_COLUMN_TYPE_CODE = 'M';                      /* AJS 20261007 화면검증 */

        /********************************************************************************
        * 임시테이블만들기
        ********************************************************************************/
        DELETE FROM GT_0060_BOH_STORAGE;
        DELETE FROM GT_0060_BOH;
        DELETE FROM GT_0060_SHIP_RESULT;
        DELETE FROM GT_0060_ROWDATA;
        DELETE FROM GT_0060_RESULT;
        DELETE FROM GT_0060_RESULT_DTL;
        DELETE FROM GT_0060_PIVOT;
        DELETE FROM GT_0060_PIVOT_OLD;
        DELETE FROM GT_0060_TITLESET;

        INSERT INTO GT_0060_TITLESET
        (
            COLUMN_NAME
        )
        SELECT COLUMN_NAME
          FROM SCM_MST_TITLESET_USER
         WHERE PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID = P_USER_ID
           AND USER_INQUIRY_COLUMN_TYPE_CODE = 'M';                      /* AJS 20261007 화면검증 */

        /********************************************************************************/

        /*--//////////////////////////////////////////////////////////////////////////////--*/
        /*--//1. BOH																	//--*/
        /*--//////////////////////////////////////////////////////////////////////////////--*/
        INSERT INTO GT_0060_BOH_STORAGE
        (
            DIVISION_ID
          , FROM_SITE
          , ITEM_ID
          , PRODUCT_LEVEL1
          , TO_SITE
          , TRANSPORT_MODE
          , INCOTERMS
          , FCST_TYPE
          , YYYYMMDD
          , BOH_TYPE
          , BOH_QTY
          , SEQ
        )
        SELECT IA.DIVISION_ID
             , IA.FROM_SITE
             , NVL(C.APPLIED_MODEL, IA.ITEM_ID) AS ITEM_ID
             , CASE WHEN D.GROUP_CODE1 IS NULL THEN '-' ELSE D.GROUP_CODE1 END AS PRODUCT_LEVEL1
             , '' AS TO_SITE
             , '' AS TRANSPORT_MODE
             , '' AS INCOTERMS
             , '' AS FCST_TYPE
             , IA.YYYYMMDD
             , IA.BOH_TYPE AS BOH_TYPE
             , SUM(IA.BOH_QTY) AS BOH_QTY
             , IA.SEQ
          FROM (/*//BOH : 5s==================================================================================================================================*/
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , XA.BOH_TYPE
                     , XA.YYYYMMDD
                     , SUM(XA.BOH_QTY) AS BOH_QTY
                     , XA.SEQ
                  FROM (/* MES TOTAL - (OQC_NG + QMS/MES_HOLD) */
                        SELECT SA.DIVISION_ID
                             , SA.FROM_SITE
                             , SA.ITEM_ID
                             , 'BOH' AS BOH_TYPE
                             , SA.YYYYMMDD
                             , NVL(SUM(SA.TOTAL) - (SUM(SA.OQC_NG) + SUM(SA.QMS_MES_HOLD)), 0) AS BOH_QTY
                             , 11 AS SEQ
                          FROM (SELECT DIVISION_ID
                                     , FROM_SITE
                                     , ITEM_ID
                                     , V_BOH_YYYYMMDD AS YYYYMMDD
                                     , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                                     , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                                     , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                                  FROM SSP_DNM_GMES_STOCK_81_82
                                 WHERE DIVISION_ID = P_DIVISION_ID
                                   AND COMPANY_ID = P_COMPANY_ID
                                   AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR FROM_SITE IN (SELECT COLUMN_VALUE
                                                       FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                    OR ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                     FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                    /* OR ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                                    OR ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                   FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                                 GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) SA
                         GROUP BY SA.DIVISION_ID, SA.FROM_SITE, SA.ITEM_ID, SA.YYYYMMDD
                        UNION ALL
                        /* OWMS */
                        SELECT SA.DIVISION_ID
                             , SA.FROM_SITE
                             , SA.ITEM_ID
                             , 'BOH' AS BOH_TYPE
                             , SA.CUTOFF_DATE AS YYYYMMDD
                             , SUM(SA.AVAILABLE_QTY) AS BOH_QTY
                             , 11 AS SEQ                                        /* MEASURE 위치와 동일하게 */
                          FROM SSP_ANL_OWMS_STOCK_C2 SA
                             , SCM_ADM_LOOKUP_MASTER_DETAIL SB
                         WHERE SB.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'             /* C20220419-000607 */
                           AND SB.VALID_YN = 'Y'
                           AND SB.ATTRIBUTE1 = 'Y'
                           AND SB.SEGMENT1 = SA.STOCK_STATUS
                           AND SA.DIVISION_ID = P_DIVISION_ID
                           AND SA.COMPANY_ID = P_COMPANY_ID
                           AND SA.CUTOFF_DATE = V_BOH_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                         GROUP BY SA.DIVISION_ID, SA.FROM_SITE, SA.ITEM_ID, SA.CUTOFF_DATE) XA
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.BOH_TYPE, XA.YYYYMMDD, XA.SEQ
                UNION ALL
                /*//ERP : 3S==================================================================================================================================*/
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'ERP' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , XA.SCM_QTY AS BOH_QTY
                     , 9 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM (SELECT SA.DIVISION_ID
                             , SA.COMPANY_ID
                             , SA.SCM_SITE_ID
                             , SA.ITEM_ID
                             , SA.SSP_QTY
                             , SA.SCM_QTY
                             , SA.CUTOFF_DATE
                             , SA.SITE_ID
                             , SA.STORAGE_ID
                             , SA.PLANT_ID
                             , SA.OPERATION_ID
                             , SA.STOCK_TYPE
                          FROM SSP_DNM_STOCK_C SA                               /* SCM_DNM_STOCK_V */
                         WHERE SA.DIVISION_ID = P_DIVISION_ID
                           AND SA.COMPANY_ID = P_COMPANY_ID
                           AND SA.CUTOFF_DATE > V_STOCK_DATE                    /* 현재일 - 3 */
                           AND SA.CUTOFF_DATE = V_BOH_DATE
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA   --  2026.10.07 AJS
                            /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) XA   --  2026.10.07 AJS */
                            OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))) XA   /* AJS 20261008 Model/Nickname */
                     , (SELECT SA.DIVISION_ID
                             , SA.STORAGE_ID
                             , SA.SCM_SITE_ID
                             , SA.LOCATION_CODE
                             , SA.PLANT_ID
                             , SB.COMPANY_ID
                             , SA.VALID_YN
                          FROM SSP_MST_LOCATION_V SA
                             , SCM_MST_SITE SB
                         WHERE SA.DIVISION_ID = SB.DIVISION_ID
                           AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                           AND SA.PLANT_ID = SB.PLANT_ID
                           AND SB.DIVISION_ID = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND SB.VALID_YN = 'Y'
                           AND SB.SITE_TYPE = 'PLANT'
                           AND SA.VALID_YN = 'Y'
                           AND SA.DIVISION_ID = P_DIVISION_ID
                           AND SA.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA')
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                         GROUP BY SA.DIVISION_ID, SA.STORAGE_ID, SA.SCM_SITE_ID, SA.LOCATION_CODE, SA.PLANT_ID, SB.COMPANY_ID, SA.VALID_YN
                        UNION ALL
                        SELECT DISTINCT SA.SEGMENT1 AS DIVISION_ID
                             , SA.SEGMENT4 AS STORAGE_ID
                             , SA.SEGMENT2 AS SCM_SITE_ID
                             , 'AS' AS LOCATION_CODE
                             , SA.SEGMENT3 AS PLANT_ID
                             , SB.COMPANY_ID
                             , SA.VALID_YN
                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                             , SCM_MST_SITE SB
                         WHERE SA.SEGMENT1 = SB.DIVISION_ID
                           AND SA.SEGMENT2 = SB.SCM_SITE_ID
                           AND SA.SEGMENT3 = SB.PLANT_ID
                           AND SA.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC'
                           AND SA.VALID_YN = 'Y'
                           AND SB.DIVISION_ID = P_DIVISION_ID
                           AND SB.COMPANY_ID = P_COMPANY_ID
                           AND SB.VALID_YN = 'Y'
                           AND SB.SITE_TYPE = 'PLANT'
                           AND SA.SEGMENT1 = P_DIVISION_ID
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR SA.SEGMENT2 IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) XB
                 WHERE XA.DIVISION_ID = XB.DIVISION_ID
                   AND XA.STORAGE_ID = XB.STORAGE_ID
                   AND XA.PLANT_ID = XB.PLANT_ID
                   AND XA.COMPANY_ID = XB.COMPANY_ID
                   AND XA.SCM_SITE_ID = XB.SCM_SITE_ID
                   AND XB.LOCATION_CODE IN ('PACK_OWMS', 'CELL_OWMS', 'FORMATION_CHECK_PACKAGING', 'CMA_BMA', 'AS')
                   AND XA.STOCK_TYPE = 'INVENTORY'
                UNION ALL
                /*//oWMS : ==================================================================================================================================*/
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , 'oWMS' AS BOH_TYPE
                     , XA.CUTOFF_DATE AS YYYYMMDD
                     /* , SUM(W.STOCK_QTY)			AS BOH_QTY */
                     , SUM(XA.AVAILABLE_QTY) AS BOH_QTY
                     , 7 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM SSP_ANL_OWMS_STOCK_C2 XA
                     , SCM_ADM_LOOKUP_MASTER_DETAIL XB
                 WHERE XB.LOOKUP_TYPE = 'OWMS_STOCK_STATUS'                     /* C20220419-000607 */
                   AND XB.VALID_YN = 'Y'
                   AND XB.ATTRIBUTE1 = 'Y'
                   AND XB.SEGMENT1 = XA.STOCK_STATUS
                   AND XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE = V_BOH_YYYYMMDD
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                          FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.CUTOFF_DATE
                UNION ALL
                /*//MES : 0S==================================================================================================================================*/
                SELECT XA.DIVISION_ID
                     , XA.FROM_SITE
                     , XA.ITEM_ID
                     , 'MES' AS BOH_TYPE
                     , XA.YYYYMMDD
                     , NVL(SUM(XA.TOTAL) - (SUM(XA.OQC_NG) + SUM(XA.QMS_MES_HOLD)), 0) AS BOH_QTY
                     , 8 AS SEQ
                  FROM (SELECT DIVISION_ID
                             , FROM_SITE
                             , ITEM_ID
                             , V_BOH_YYYYMMDD AS YYYYMMDD
                             , CASE WHEN AVAILABLE_YN = 'N' AND OQC_INSP_RESULT = 'N' THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS OQC_NG
                             , CASE WHEN AVAILABLE_YN = 'N' AND (QMS_HOLD_YN = 'Y' OR MES_HOLD_YN = 'Y') THEN SUM(NVL(LOT_QTY, 0)) ELSE 0 END AS QMS_MES_HOLD
                             , SUM(NVL(LOT_QTY, 0)) AS TOTAL
                          FROM SSP_DNM_GMES_STOCK_81_82
                         WHERE DIVISION_ID = P_DIVISION_ID
                           AND COMPANY_ID = P_COMPANY_ID
                           AND YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR FROM_SITE IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                             FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                           FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, AVAILABLE_YN, OQC_INSP_RESULT, MES_HOLD_YN, QMS_HOLD_YN) XA
                 GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.ITEM_ID, XA.YYYYMMDD
                /*------------------------------------------------------------------------------------------------------------------------------------*/
                /*[C20200121-000352]-1 : ESS Packer 재고 적용(SSP_DNM_ESS_PACKER_STOCK_V) */
                UNION ALL /* ESS PACKER 재고 -BOH MEASURE */
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'BOH' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , NVL(XA.SSP_QTY, 0) AS BOH_QTY
                     , 11 AS SEQ                                                /* MEASURE 위치와 동일하게 */
                  FROM SSP_DNM_ESS_PACKER_STOCK_V XA
                 WHERE XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE > V_STOCK_DATE                            /* 현재일 - 3 */
                   AND XA.CUTOFF_DATE = V_BOH_DATE
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                UNION ALL /* ESS PACKER 재고 -ERP MEASURE */
                SELECT XA.DIVISION_ID AS DIVISION_ID
                     , XA.SCM_SITE_ID AS FROM_SITE
                     , XA.ITEM_ID AS ITEM_ID
                     , 'ERP' AS BOH_TYPE
                     , TO_CHAR(XA.CUTOFF_DATE, 'YYYYMMDD') AS YYYYMMDD
                     , NVL(XA.SSP_QTY, 0) AS BOH_QTY
                     , 9 AS SEQ                                                 /* MEASURE 위치와 동일하게 */
                  FROM SSP_DNM_ESS_PACKER_STOCK_V XA
                 WHERE XA.DIVISION_ID = P_DIVISION_ID
                   AND XA.COMPANY_ID = P_COMPANY_ID
                   AND XA.CUTOFF_DATE > V_STOCK_DATE                            /* 현재일 - 3 */
                   AND XA.CUTOFF_DATE = V_BOH_DATE
                   AND (TRIM(P_FROM_SITE) IS NULL
                    OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                   AND (TRIM(P_ITEM_ID) IS NULL
                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA   --  2026.10.07 AJS
                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)) IA   --  2026.10.07 AJS */
                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                      FROM TABLE(V_ITEM_TAB)))) IA   /* AJS 20261008 Model/Nickname */
             , SCM_MST_SITE B
             , SCM_MST_ITEM_SN C
             , SCP_MST_FINAL_ITEM D
         WHERE B.DIVISION_ID = IA.DIVISION_ID
           AND B.SCM_SITE_ID = IA.FROM_SITE
           AND C.DIVISION_ID(+) = IA.DIVISION_ID
           AND C.COMPANY_ID(+) = P_COMPANY_ID
           AND C.SITE_ID(+) = B.SITE_ID
           AND C.ITEM_ID(+) = IA.ITEM_ID
           AND C.ITEM_CLASS(+) IN ('ES1901', 'ES2001', 'ES2002', 'ES2003', 'ES2004')
           AND D.DIVISION_ID(+) = IA.DIVISION_ID
           AND D.ITEM_ID(+) = IA.ITEM_ID
           AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
            OR D.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                   FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
         GROUP BY IA.DIVISION_ID, IA.FROM_SITE, C.APPLIED_MODEL, IA.ITEM_ID, D.GROUP_CODE1
                , IA.YYYYMMDD, IA.BOH_TYPE, IA.SEQ;

        INSERT INTO GT_0060_BOH
        (
            DIVISION_ID
          , FROM_SITE
          , ITEM_ID
          , PRODUCT_LEVEL1
          , TO_SITE
          , TRANSPORT_MODE
          , INCOTERMS
          , FCST_TYPE
          , YYYYMMDD
          , BOH_TYPE
          , BOH_QTY
          , SEQ
        )
        SELECT DIVISION_ID
             , FROM_SITE
             , ITEM_ID
             , PRODUCT_LEVEL1
             , '' AS TO_SITE
             , '' AS TRANSPORT_MODE
             , '' AS INCOTERMS
             , '' AS FCST_TYPE
             , YYYYMMDD
             , BOH_TYPE AS BOH_TYPE
             , SUM(BOH_QTY) AS BOH_QTY
             , SEQ
          FROM GT_0060_BOH_STORAGE
         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, PRODUCT_LEVEL1, YYYYMMDD, BOH_TYPE, SEQ;
        /*--//END BOH : 5S//--*/
        IF P_REAL_FLAG = 'Y' THEN

            /*--//////////////////////////////////////////////////////////////////////////////--*/
            /*--//2. DATA ROW DATE															//--*/
            /*--//////////////////////////////////////////////////////////////////////////////--*/
            /* ERP 출하실적 */
            INSERT INTO GT_0060_SHIP_RESULT
            (
                DIVISION_ID
              , CONFIRM_ID
              , ERP_SO_NO
              , YYYYMMDD
              , TRANSPORT_MODE
              , INCOTERMS
              , ETA_DATE
              , ETD_DATE
              , FROM_SITE
              , TO_SITE
              , ITEM_ID
              , RESULT_QTY
            )
            /* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
            SELECT A.DIVISION_ID AS DIVISION_ID
                 , A.CONFIRM_ID AS CONFIRM_ID
                 , A.ORDER_NO AS ERP_SO_NO
                 , A.EXFACTORY_DATE AS YYYYMMDD
                 , A.TRANSPORT_MODE AS TRANSPORT_MODE
                 , A.INCOTERMS AS INCOTERMS
                 , A.ETA_DATE AS ETA_DATE
                 , A.ETD_DATE AS ETD_DATE
                 , A.FROM_SCM_SITE_ID AS FROM_SITE
                 , A.TO_SCM_SITE_ID AS TO_SITE
                 , A.ITEM_ID AS ITEM_ID
                 , SUM(A.EXFACTORY_QTY) AS RESULT_QTY
              FROM SCM_DNM_EXFACTORY_RESULT A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
                 , SCM_MST_SITE C
                 , SCM_MST_ITEM_SN D
             WHERE B.LOOKUP_TYPE = 'ERP_SSP_TYPE'                               /* LOOKUP에 등록된 공정만 */
               AND B.VALID_YN = 'Y'
               AND B.SEGMENT1 = A.SSP_TYPE
               AND A.FROM_SCM_SITE_ID = C.SCM_SITE_ID
               AND A.DIVISION_ID = C.DIVISION_ID
               AND C.SITE_TYPE = 'PLANT'
               AND A.ITEM_ID = D.ITEM_ID
               AND A.DIVISION_ID = D.DIVISION_ID
               AND C.COMPANY_ID = D.COMPANY_ID
               AND D.ITEM_TYPE NOT IN ('Q', 'R')
               AND NVL(A.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')         /* D90: DO삭제 , D10:DO생성 */
               AND A.CONFIRM_ID LIKE 'C%'
               AND A.DIVISION_ID = P_DIVISION_ID
               AND A.COMPANY_ID = P_COMPANY_ID
               AND (TRIM(P_FROM_SITE) IS NULL
                OR A.FROM_SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
               AND (TRIM(P_ITEM_ID) IS NULL
                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                 FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
               /* AND   (E.EXFACTORY_DATE >= @p_plan_start_yyyymmdd  AND E.EXFACTORY_DATE < @v_to_yyyymmdd) */
               AND (A.EXFACTORY_DATE >= V_FROM_YYYYMMDD AND A.EXFACTORY_DATE < P_PLAN_START_YYYYMMDD)
               AND A.ATTRIBUTE2 <> 'E'
             GROUP BY A.DIVISION_ID
                    , A.CONFIRM_ID
                    , A.ORDER_NO
                    , A.EXFACTORY_DATE
                    , A.TRANSPORT_MODE
                    , A.INCOTERMS
                    , A.ETA_DATE
                    , A.ETD_DATE
                    , A.FROM_SCM_SITE_ID
                    , A.TO_SCM_SITE_ID
                    , A.ITEM_ID
            UNION ALL
            /* ERP 출하실적에서 CONFIRM_ID 없는 실적 */
            /* AS-IS 는 이 갈래의 칸 순서가 위 갈래와 달라 값이 서로 다른 칸으로 들어간다 — 칸 이름에 맞춰 바로잡음 */
            SELECT A.DIVISION_ID AS DIVISION_ID
                 , '-' AS CONFIRM_ID
                 , A.ORDER_NO AS ERP_SO_NO
                 , A.EXFACTORY_DATE AS YYYYMMDD
                 , A.TRANSPORT_MODE AS TRANSPORT_MODE
                 , A.INCOTERMS AS INCOTERMS
                 , A.ETA_DATE AS ETA_DATE
                 , A.ETD_DATE AS ETD_DATE
                 , A.FROM_SCM_SITE_ID AS FROM_SITE
                 , NVL(G.SEGMENT4, A.TO_SCM_SITE_ID) AS TO_SITE
                 , A.ITEM_ID AS ITEM_ID
                 , SUM(A.EXFACTORY_QTY) AS RESULT_QTY
              FROM SCM_DNM_EXFACTORY_RESULT A
                 , SCM_MST_SITE B
                 , SCM_MST_ITEM_SN C
                 , SCP_MST_FINAL_ITEM D
                 , SCM_MST_SITE E
                 , SCM_ADM_LOOKUP_MASTER_DETAIL F
                 , SCM_ADM_LOOKUP_MASTER_DETAIL G
             WHERE A.FROM_SCM_SITE_ID = B.SCM_SITE_ID
               AND A.DIVISION_ID = B.DIVISION_ID
               AND B.SITE_TYPE = 'PLANT'
               AND A.ITEM_ID = C.ITEM_ID
               AND A.DIVISION_ID = C.DIVISION_ID
               AND B.COMPANY_ID = C.COMPANY_ID
               AND C.ITEM_TYPE NOT IN ('Q', 'R')
               AND D.ITEM_ID = A.ITEM_ID                                        /* SCP 대상 ITEM만 */
               AND D.DIVISION_ID = A.DIVISION_ID
               AND E.SCM_SITE_ID = A.FROM_SCM_SITE_ID
               AND E.DIVISION_ID = A.DIVISION_ID
               AND F.LOOKUP_TYPE = 'ERP_ORDER_TYPE'
               AND F.VALID_YN = 'Y'
               AND F.SEGMENT1 = A.ORDER_TYPE_CODE
               AND G.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'             /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
               AND G.SEGMENT1(+) = A.DIVISION_ID
               AND G.SEGMENT2(+) = A.SOLDTO_CODE
               AND G.SEGMENT3(+) = A.SHIPTO_CODE
               AND NVL(A.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')         /* D90: DO삭제 , D10:DO생성 */
               AND (A.CONFIRM_ID IS NULL OR A.CONFIRM_ID NOT LIKE 'C%')
               AND (A.EXFACTORY_DATE >= V_FROM_YYYYMMDD AND A.EXFACTORY_DATE < P_PLAN_START_YYYYMMDD)
               AND A.STORAGE_ID NOT IN ('6000', '799A')                         /* 상품창고제외 */
               AND NOT EXISTS (SELECT 1
                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                WHERE SA.SEGMENT1 = A.STORAGE_ID
                                  AND SA.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                  AND SA.VALID_YN = 'Y')                        /* 사외 창고 제외 LOOKUP 관리 */
               AND A.DIVISION_ID = P_DIVISION_ID
               AND A.COMPANY_ID = P_COMPANY_ID
               AND (TRIM(P_FROM_SITE) IS NULL
                OR A.FROM_SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                            FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
               AND (TRIM(P_ITEM_ID) IS NULL
                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                OR A.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                   FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                /* OR A.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                OR A.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                 FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
               AND A.ATTRIBUTE2 <> 'E'
             GROUP BY A.DIVISION_ID
                    , A.ORDER_NO
                    , A.FROM_SCM_SITE_ID
                    , NVL(G.SEGMENT4, A.TO_SCM_SITE_ID)
                    , A.ITEM_ID
                    , A.EXFACTORY_DATE
                    , A.TRANSPORT_MODE
                    , A.INCOTERMS
                    , A.ETA_DATE
                    , A.ETD_DATE
                    , A.TO_SCM_SITE_ID;

            INSERT INTO GT_0060_ROWDATA
            (
                DIVISION_ID
              , ITEM_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , YYYYMMDD
              , QTY
              , CONFIRM_DAY
            )
            SELECT IA.DIVISION_ID
                 , NVL(C.APPLIED_MODEL, IA.ITEM_ID) AS ITEM_ID
                 , IA.FROM_SITE
                 , CASE WHEN D.GROUP_CODE1 IS NULL THEN '-' ELSE D.GROUP_CODE1 END AS PRODUCT_LEVEL1
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.SEQ
                 , IA.YYYYMMDD
                 , SUM(IA.QTY) AS QTY
                 /* 확정구간 조회 일수 펑션 수정([FN_GET_SSP_ANL_SHIP_FROZEN -> FN_GET_ANL_SHIP_FROZEN_DAY_CNT]), HSBANG, 2024.05.16 */
                 , CASE WHEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, P_PLAN_START_YYYYMMDD) - 1 > 0
                        THEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, P_PLAN_START_YYYYMMDD) - 1
                        ELSE 0
                   END AS CONFIRM_DAY
              FROM (/*--//2-1. Ship Req : 출하 요청(Plant향 Ship Req)  DM_PLN_SHIPMENT_REQ / MEASURE = 'SHIP_REQ' //--*/
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.PLANT_SITE_ID AS FROM_SITE
                         , 'SHIP_REQ' AS MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , CASE WHEN XA.YYYYMMDD < P_PLAN_START_YYYYMMDD THEN (CASE WHEN XA.QTY = 0 THEN NULL ELSE NVL(XA.QTY, 0) END)
                                ELSE NVL(XA.QTY, 0)
                           END AS QTY
                         , 1 AS SEQ
                      FROM DM_PLN_SHIPMENT_REQ XA
                         , SCM_MST_SITE XB
                     WHERE XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.PLANT_SITE_ID = XB.SCM_SITE_ID
                       AND XB.COMPANY_ID = P_COMPANY_ID
                       AND XB.SITE_TYPE = 'PLANT'
                       AND XB.VALID_YN = 'Y'
                       AND XA.MEASURE = 'SHIP_REQ'                              /* 확정 후 수정할 것 */
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND XA.QTY > 0
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                    /*--//2-2. Ship Plan : 출하 계획(Plant향 Ship Req) //--*/
                    UNION ALL
                    SELECT XA.DIVISION_ID AS DIVISION_ID
                         , XA.ITEM_ID AS ITEM_ID
                         , XA.FROM_SITE AS FROM_SITE
                         , XA.MEASURE AS MEASURE
                         , XA.TO_SITE AS TO_SITE
                         , XA.TRANSPORT_MODE AS TRANSPORT_MODE
                         , XA.INCOTERMS AS INCOTERMS
                         , XA.FCST_TYPE AS FCST_TYPE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , NVL(SUM(XA.QTY), 0) AS QTY
                         , XA.SEQ AS SEQ
                      FROM (/*//2) Ship Plan : SSP(Daily) Plant향 Shipment Plan */
                            SELECT SA.DIVISION_ID
                                 , SA.ITEM_ID
                                 , SA.FROM_SITE
                                 , 'SHIP_PLAN' AS MEASURE
                                 , SA.TO_SITE AS TO_SITE
                                 , SA.TRANSPORT_MODE AS TRANSPORT_MODE
                                 , SA.INCOTERMS AS INCOTERMS
                                 , SA.FCST_TYPE AS FCST_TYPE
                                 , SA.YYYYMMDD
                                 , SA.QTY
                                 , 2 AS SEQ
                              FROM SSP_ANL_SHIP_CONFIRM SA
                             WHERE SA.CHANGE_TYPE = 'C'
                               AND SA.BIZ_TYPE <> 'E'
                               AND SA.QTY > 0
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                               /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
                               AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                               AND SA.YYYYMMDD <= V_TO_YYYYMMDD
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                            UNION ALL
                            /* ERP 실적 */
                            SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.FROM_SITE AS FROM_SITE
                                 , 'SHIP_PLAN' AS MEASURE
                                 , '' AS TO_SITE
                                 , '' AS TRANSPORT_MODE
                                 , '' AS INCOTERMS
                                 , '' AS FCST_TYPE
                                 , SA.YYYYMMDD AS YYYYMMDD
                                 , SA.RESULT_QTY AS QTY
                                 , 2 AS SEQ
                              FROM GT_0060_SHIP_RESULT SA
                            UNION ALL
                            /* 확정구간 이후 Ship Req 수량 합 */
                            SELECT SA.DIVISION_ID
                                 , SA.ITEM_ID
                                 , SA.FROM_SITE
                                 , SA.MEASURE
                                 , '' AS TO_SITE
                                 , '' AS TRANSPORT_MODE
                                 , '' AS INCOTERMS
                                 , '' AS FCST_TYPE
                                 , SA.YYYYMMDD
                                 , SA.QTY
                                 , SA.SEQ
                              FROM (SELECT SB.DIVISION_ID AS DIVISION_ID
                                         , SB.ITEM_ID AS ITEM_ID
                                         , SB.PLANT_SITE_ID AS FROM_SITE
                                         , 'SHIP_PLAN' AS MEASURE
                                         , SB.YYYYMMDD AS YYYYMMDD
                                         , SB.QTY AS QTY
                                         , 2 AS SEQ
                                         /* 확정구간 조회 일수 펑션 수정, HSBANG, 2024.05.16 */
                                         , CASE WHEN NVL(SC.SHIP_FROZEN, 0) > 0
                                                THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, SC.DIVISION_ID, SC.SCM_SITE_ID, P_PLAN_START_YYYYMMDD), 'YYYYMMDD')
                                                ELSE P_PLAN_START_YYYYMMDD
                                           END AS FROZEN_YYYYMMDD               /* Ship Frozen구간 다음일자 */
                                      FROM DM_PLN_SHIPMENT_REQ SB
                                         , SCM_MST_SITE SC
                                     WHERE SC.DIVISION_ID = P_DIVISION_ID
                                       AND SB.PLANT_SITE_ID = SC.SCM_SITE_ID
                                       AND SC.COMPANY_ID = P_COMPANY_ID
                                       AND SC.SITE_TYPE = 'PLANT'
                                       AND SC.VALID_YN = 'Y'
                                       AND SB.DIVISION_ID = P_DIVISION_ID
                                       AND SB.MEASURE = 'SHIP_REQ'              /* 확정 후 수정할 것 */
                                       AND SB.YYYYMMDD >= V_FROM_YYYYMMDD
                                       AND SB.YYYYMMDD <= V_TO_YYYYMMDD
                                       AND SB.QTY > 0
                                       AND (TRIM(P_FROM_SITE) IS NULL
                                        OR SB.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                       AND (TRIM(P_ITEM_ID) IS NULL
                                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                        OR SB.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) SA   --  2026.10.07 AJS
                                        /* OR SB.ITEM_ID MEMBER OF V_ITEM_TAB)) SA   --  2026.10.07 AJS */
                                        OR SB.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                          FROM TABLE(V_ITEM_TAB)))) SA   /* AJS 20261008 Model/Nickname */
                             WHERE SA.YYYYMMDD >= SA.FROZEN_YYYYMMDD) XA
                     GROUP BY XA.DIVISION_ID, XA.ITEM_ID, XA.FROM_SITE
                            , XA.TO_SITE, XA.TRANSPORT_MODE, XA.INCOTERMS, XA.FCST_TYPE
                            , XA.MEASURE, XA.YYYYMMDD, XA.SEQ
                    /*--//2-4. PROD_PLAN : 생산 계획 //--*/
                    UNION ALL
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.SCM_SITE_ID AS FROM_SITE
                         , 'PROD_PLAN' AS MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.PLAN_DATE AS YYYYMMDD
                         , XA.PLAN_QTY AS QTY
                         , 9 AS SEQ
                      FROM SSP_DNM_FP_PLAN_FROZEN XA                            /* SCM_DNM_PLAN_FROZEN_V */
                     WHERE /* START [E20260811-000692] ESMI AZ 링크 2호기 생산계획 받아오지 못하는 현상 처리 */
                           /* 원본 AND T0.OPERATION_ID IN ('P5500', 'P9500', 'F5300', 'F5500', 'F5600', 'F6000') */
                           XA.OPERATION_ID IN ('P5500', 'P9500', 'F5300', 'F5500', 'F5600', 'F6000', 'PL500')
                           /* END [E20260811-000692] */
                       AND XA.PLAN_QTY > 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_DATE >= V_FROM_YYYYMMDD
                       AND XA.PLAN_DATE <= V_TO_YYYYMMDD
                       AND XA.SITE_ID IN (SELECT DISTINCT SA.SITE_ID
                                            FROM SCM_MST_SITE SA
                                           WHERE SA.DIVISION_ID = P_DIVISION_ID
                                             AND SA.COMPANY_ID = P_COMPANY_ID
                                             AND SA.SITE_TYPE = 'PLANT'
                                             AND SA.VALID_YN = 'Y')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                    UNION ALL
                    /* [C20200121-000352]-3 : Production Plan Measure에 Paker생산계획 추가 */
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.SCM_SITE_ID AS FROM_SITE
                         , 'PROD_PLAN' AS MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.YYYYMMDD AS YYYYMMDD
                         , XA.QTY AS QTY
                         , 9 AS SEQ
                      FROM SCP_ANL_PRODUCTION_PLAN XA
                         , (SELECT SA.DIVISION_ID
                                 , SA.PLAN_START_YYYYMMDD
                                 , SA.PLAN_TYPE
                                 , SA.SEQ
                              FROM (SELECT SB.DIVISION_ID
                                         , SB.PLAN_START_YYYYMMDD
                                         , SB.PLAN_TYPE
                                         , SB.PLAN_SEQ AS SEQ
                                      FROM SCP_PLAN_VERSION_V SB
                                     WHERE SB.DIVISION_ID = '82'                /* ESS(82)만 적용 */
                                       AND SB.PLAN_CYCLE = 'WEEKLY'
                                       AND SB.PLAN_TYPE NOT IN ('TE', 'TM')
                                     ORDER BY SB.PLAN_START_YYYYMMDD DESC, SB.PLAN_TYPE_ORDER DESC, SB.PLAN_SEQ DESC) SA
                             WHERE ROWNUM = 1) XB
                         , SCM_MST_SITE XC
                     WHERE XB.DIVISION_ID = XA.DIVISION_ID
                       AND XB.PLAN_START_YYYYMMDD = XA.PLAN_START_YYYYMMDD
                       AND XB.PLAN_TYPE = XA.PLAN_TYPE
                       AND XB.SEQ = XA.SEQ
                       AND XC.DIVISION_ID = XA.DIVISION_ID
                       AND XC.SCM_SITE_ID = XA.SCM_SITE_ID
                       AND XC.SITE_TYPE = 'PLANT'
                       AND XC.OSP_YN = 'Y'
                       AND XC.VALID_YN = 'Y'
                       AND XA.DIVISION_ID = '82'                                /* ESS(82)만 적용 */
                       AND XC.COMPANY_ID = P_COMPANY_ID
                       AND XA.MEASURE = 'PROD_PLAN_AMEND'
                       AND XA.QTY > 0
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                    UNION ALL
                    -- 2026.10.06 AJS 입고예정 도착일 함수를 인자 조합마다 1회 호출 (START)
--                    SELECT XA.DIVISION_ID
--                         , XA.ITEM_ID
--                         , XA.FROM_SITE
--                         , XA.MEASURE
--                         , '' AS TO_SITE
--                         , '' AS TRANSPORT_MODE
--                         , '' AS INCOTERMS
--                         , '' AS FCST_TYPE
--                         , XA.YYYYMMDD
--                         , XA.QTY
--                         , XA.SEQ
--                      FROM (SELECT SA.DIVISION_ID AS DIVISION_ID
--                                 , SA.ITEM_ID AS ITEM_ID
--                                 , SA.SCM_SITE_ID AS FROM_SITE
--                                 , 'PROD_PLAN' AS MEASURE
--                                 , FN_GET_SSP_ETA_DATE(SA.DIVISION_ID, SA.BOD_ID, SA.YYYYMMDD) AS YYYYMMDD
--                                 , SA.QTY AS QTY
--                                 , 9 AS SEQ
--                              FROM DM_PLN_SHIPMENT_REQ SA
--                                 , SCM_MST_SITE SB
--                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
--                               AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
--                               AND SB.OPERATION_GROUP = 'W'
--                               AND SB.SITE_TYPE = 'PLANT'
--                               AND SB.VALID_YN = 'Y'
--                               AND SA.DIVISION_ID IN (SELECT COLUMN_VALUE
--                                                        FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')))
--                               AND SB.COMPANY_ID = P_COMPANY_ID
--                               AND SA.QTY > 0
--                               AND (TRIM(P_FROM_SITE) IS NULL
--                                OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
--                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
--                               AND (TRIM(P_ITEM_ID) IS NULL
--                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE
--                                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA
--                     WHERE XA.YYYYMMDD >= V_FROM_YYYYMMDD
--                       AND XA.YYYYMMDD < V_TO_YYYYMMDD
                    /* 확정 이후 입고예정(창고 PROD_PLAN) : 출하일 -> 도착일 함수가 행마다 2 번(>= · <) 불려
                       한 번 조회에 17 만 블록을 읽었다(82 HQ00). 함수 인자(사업부 · BOD · 출하일) 조합마다 1 번만 부르도록
                       인자 목록(SC, 중복 제거) -> 함수값(XB) 을 먼저 만들고 원 행(XA)에 붙인다.
                       - XB 는 XA 와 같은 조건으로 만든 인자 목록이므로 XA 의 모든 행이 XB 와 한 행씩 이어진다
                       - BOD 는 빈 값도 같은 값으로 잇는다(DECODE) - 원래 함수 호출과 같은 결과
                       - 함수값 조건(>= 시작일 · < 종료일)은 원래와 같다 */
                    SELECT XA.DIVISION_ID
                         , XA.ITEM_ID
                         , XA.FROM_SITE
                         , XA.MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XB.ETA_YYYYMMDD AS YYYYMMDD
                         , XA.QTY
                         , XA.SEQ
                      FROM (SELECT SA.DIVISION_ID AS DIVISION_ID
                                 , SA.ITEM_ID AS ITEM_ID
                                 , SA.SCM_SITE_ID AS FROM_SITE
                                 , 'PROD_PLAN' AS MEASURE
                                 , SA.BOD_ID
                                 , SA.YYYYMMDD AS SHIP_YYYYMMDD
                                 , SA.QTY AS QTY
                                 , 9 AS SEQ
                              FROM DM_PLN_SHIPMENT_REQ SA
                                 , SCM_MST_SITE SB
                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                               AND SB.OPERATION_GROUP = 'W'
                               AND SB.SITE_TYPE = 'PLANT'
                               AND SB.VALID_YN = 'Y'
                               AND SA.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')))
                               AND SB.COMPANY_ID = P_COMPANY_ID
                               AND SA.QTY > 0
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) XA   --  2026.10.07 AJS
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) XA   --  2026.10.07 AJS */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))) XA   /* AJS 20261008 Model/Nickname */
                         , (SELECT /*+ NO_MERGE */
                                   SC.DIVISION_ID
                                 , SC.BOD_ID
                                 , SC.YYYYMMDD
                                 , MAX(FN_GET_SSP_ETA_DATE(SC.DIVISION_ID, SC.BOD_ID, SC.YYYYMMDD)) AS ETA_YYYYMMDD
                              FROM (SELECT /*+ NO_MERGE */
                                           DISTINCT
                                           SA.DIVISION_ID
                                         , SA.BOD_ID
                                         , SA.YYYYMMDD
                                      FROM DM_PLN_SHIPMENT_REQ SA
                                         , SCM_MST_SITE SB
                                     WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                       AND SA.SCM_SITE_ID = SB.SCM_SITE_ID
                                       AND SB.OPERATION_GROUP = 'W'
                                       AND SB.SITE_TYPE = 'PLANT'
                                       AND SB.VALID_YN = 'Y'
                                       AND SA.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                                FROM TABLE(STRING_SPLIT(P_DIVISION_ID, ',')))
                                       AND SB.COMPANY_ID = P_COMPANY_ID
                                       AND SA.QTY > 0
                                       AND (TRIM(P_FROM_SITE) IS NULL
                                        OR SA.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                                FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                       AND (TRIM(P_ITEM_ID) IS NULL
                                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                        OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) SC   --  2026.10.07 AJS
                                        /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)) SC   --  2026.10.07 AJS */
                                        OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                          FROM TABLE(V_ITEM_TAB)))) SC   /* AJS 20261008 Model/Nickname */
                             GROUP BY SC.DIVISION_ID
                                    , SC.BOD_ID
                                    , SC.YYYYMMDD) XB
                     WHERE XB.DIVISION_ID = XA.DIVISION_ID
                       AND XB.YYYYMMDD = XA.SHIP_YYYYMMDD
                       AND DECODE(XB.BOD_ID, XA.BOD_ID, 1, 0) = 1
                       AND XB.ETA_YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XB.ETA_YYYYMMDD < V_TO_YYYYMMDD
                    -- 2026.10.06 AJS 입고예정 도착일 함수를 인자 조합마다 1회 호출 (END)
                    UNION ALL
                    SELECT XA.DIVISION_ID
                         , XA.MODEL_ID AS ITEM_ID
                         , XA.FROM_SITE_ID AS FROM_SITE
                         , 'SHIP_AVAL' AS MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.PLAN_DATE AS YYYYMMDD
                         , XA.OUT_QTY AS QTY
                         , 5 AS SEQ
                      FROM SSP_DNM_FP_AMEND_SHIPAVAL XA
                     WHERE XA.OUT_QTY >= 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_DATE >= V_FROM_YYYYMMDD
                       AND XA.PLAN_DATE <= V_TO_YYYYMMDD
                       AND XA.SITE_ID IN (SELECT DISTINCT SA.SITE_ID
                                            FROM SCM_MST_SITE SA
                                           WHERE SA.DIVISION_ID = P_DIVISION_ID
                                             AND SA.COMPANY_ID = P_COMPANY_ID
                                             AND SA.SITE_TYPE = 'PLANT'
                                             AND SA.VALID_YN = 'Y')
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE_ID IN (SELECT COLUMN_VALUE
                                                 FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.MODEL_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                             FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))) IA   --  2026.10.07 AJS
                        /* OR XA.MODEL_ID MEMBER OF V_ITEM_TAB)) IA   --  2026.10.07 AJS */
                        OR XA.MODEL_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                           FROM TABLE(V_ITEM_TAB)))) IA   /* AJS 20261008 Model/Nickname */
                 , SCM_MST_SITE B
                 , SCM_MST_ITEM_SN C
                 , SCP_MST_FINAL_ITEM D
             WHERE B.DIVISION_ID = P_DIVISION_ID
               AND B.COMPANY_ID = P_COMPANY_ID
               AND IA.FROM_SITE = B.SCM_SITE_ID
               AND B.SITE_TYPE = 'PLANT'
               AND B.VALID_YN = 'Y'
               AND B.COMPANY_ID = C.COMPANY_ID
               AND IA.DIVISION_ID = C.DIVISION_ID
               AND B.SITE_ID = C.SITE_ID
               AND IA.ITEM_ID = C.ITEM_ID
               AND C.ITEM_TYPE IN ('P', 'H')
               AND D.DIVISION_ID(+) = IA.DIVISION_ID
               AND D.ITEM_ID(+) = IA.ITEM_ID
               AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                OR D.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
             /* jilee 230901 */
             GROUP BY IA.DIVISION_ID, IA.FROM_SITE, D.GROUP_CODE1, C.APPLIED_MODEL, IA.ITEM_ID
                    , IA.TO_SITE, IA.TRANSPORT_MODE, IA.INCOTERMS, IA.FCST_TYPE
                    , IA.YYYYMMDD, IA.MEASURE, IA.SEQ, B.SHIP_FROZEN;

            UPDATE GT_0060_ROWDATA
               SET PRODUCT_LEVEL1 = '-'
             WHERE PRODUCT_LEVEL1 IS NULL;
            /*--//3. 해당 ITEM별 MEASURE 및 날짜 생성 //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , PRODUCT_LEVEL1
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.PRODUCT_LEVEL1
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , NVL(B.QTY, 0) AS QTY
                 , NULL AS EDIT_YN
              FROM (SELECT DISTINCT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , XA.PRODUCT_LEVEL1
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.CONFIRM_DAY
                         , XB.COLUMN_NAME AS MEASURE
                         , XB.SORT_ORDER_NO AS SEQ
                         , XC.BASIS_YYYYMMDD AS YYYYMMDD
                      FROM GT_0060_ROWDATA XA
                         , SCM_MST_SHEET_MEASURE XB
                         , SCM_SYS_CALENDAR_M XC
                     WHERE XB.PROGRAM_ID(+) = P_PROGRAM_ID
                       AND XB.SHEET_NAME(+) = P_SHEET_NAME
                       AND XC.BASIS_YYYYMMDD(+) >= V_FROM_YYYYMMDD
                       AND XC.BASIS_YYYYMMDD(+) <= V_TO_YYYYMMDD) IA
                 , GT_0060_ROWDATA B
             WHERE IA.DIVISION_ID = B.DIVISION_ID(+)
               AND IA.FROM_SITE = B.FROM_SITE(+)
               AND IA.ITEM_ID = B.ITEM_ID(+)
               AND IA.MEASURE = B.MEASURE(+)
               AND IA.YYYYMMDD = B.YYYYMMDD(+)
               AND IA.MEASURE IN ('SHIP_REQ', 'SHIP_PLAN', 'PROD_PLAN', 'SHIP_AVAL');   /* jilee */

            /*--//2-3. Shipment PLAN Detail DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT_DTL
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , LOT_YN
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , CASE WHEN B.GROUP_CODE1 IS NULL THEN '-' ELSE B.GROUP_CODE1 END AS PRODUCT_LEVEL1
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.SEQ
                 , CASE WHEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, P_PLAN_START_YYYYMMDD) - 1 > 0
                        THEN FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, IA.DIVISION_ID, IA.FROM_SITE, P_PLAN_START_YYYYMMDD) - 1
                        ELSE 0
                   END AS CONFIRM_DAY
                 , IA.YYYYMMDD
                 , SUM(IA.QTY) AS QTY
                 , MAX(IA.LOT_SIZE) AS LOT_YN
                 , CASE WHEN SUM(IA.EDIT_CNT) > 0 AND SUM(IA.EDIT_CNT) = SUM(IA.TOT_CNT) THEN 'Y'
                        /* WHEN M.EDIT_CNT > 0 AND M.EDIT_CNT != M.TOT_CNT THEN CAST(NOEDIT_QTY AS VARCHAR) */
                        WHEN SUM(IA.NOEDIT_QTY) > 0 THEN TO_CHAR(SUM(IA.NOEDIT_QTY))
                        ELSE 'N'
                   END AS EDIT_YN
              FROM (SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , 'SHIP_PLAN_DETAIL' AS MEASURE
                         , XA.TO_SITE
                         , XA.TRANSPORT_MODE
                         , XA.INCOTERMS
                         , XA.FCST_TYPE
                         , 3 AS SEQ
                         , XA.YYYYMMDD
                         , SUM(CASE WHEN XA.SHIPMENT_STATUS = 'C' AND (XA.ERP_STATUS IS NULL OR XA.ERP_STATUS <> 'C') THEN 1 ELSE 0 END) AS EDIT_CNT
                         , COUNT(*) AS TOT_CNT
                         , SUM(XA.QTY) AS QTY
                         , SUM(CASE WHEN XA.SHIPMENT_STATUS IS NULL OR XA.SHIPMENT_STATUS <> 'C' OR XA.ERP_STATUS = 'C' THEN XA.QTY ELSE 0 END) AS NOEDIT_QTY
                         , MAX(XC.LOT_SIZE) AS LOT_SIZE
                      FROM SSP_ANL_SHIP_CONFIRM XA
                         , SCM_MST_SITE XB
                         , SCP_MST_SHIPMENT_LOT_SIZE XC
                     WHERE XB.DIVISION_ID(+) = P_DIVISION_ID
                       AND XA.FROM_SITE = XB.SCM_SITE_ID(+)
                       AND XB.COMPANY_ID(+) = P_COMPANY_ID
                       AND XB.SITE_TYPE(+) = 'PLANT'
                       AND XB.VALID_YN(+) = 'Y'
                       AND XC.DIVISION_ID(+) = P_DIVISION_ID
                       AND XC.ITEM_ID(+) = XA.ITEM_ID
                       AND XC.FROM_SITE(+) = XA.FROM_SITE
                       AND XC.TO_SITE(+) = XA.TO_SITE
                       AND XC.TRANSPORT_MODE(+) = XA.TRANSPORT_MODE
                       AND XC.VALID_YN(+) = 'Y'
                       AND XC.SPLIT_YN(+) = 'Y'
                       AND XA.CHANGE_TYPE = 'C'
                       AND XA.BIZ_TYPE <> 'E'
                       AND XA.QTY > 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                       /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
                       AND XA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                     GROUP BY XA.DIVISION_ID
                            , XA.FROM_SITE
                            , XA.ITEM_ID
                            , XA.TO_SITE
                            , XA.TRANSPORT_MODE
                            , XA.INCOTERMS
                            , XA.FCST_TYPE
                            , XA.YYYYMMDD
                    UNION ALL
                    /* 과거구간 조회 */
                    SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , 'SHIP_PLAN_DETAIL' AS MEASURE
                         , XA.TO_SITE
                         , XA.TRANSPORT_MODE
                         , XA.INCOTERMS
                         , XA.FCST_TYPE
                         , 3 AS SEQ
                         , XA.YYYYMMDD
                         , 0 AS EDIT_CNT
                         , COUNT(*) AS TOT_CNT
                         , SUM(XA.QTY) AS QTY
                         , 0 AS NOEDIT_QTY
                         , MAX(XC.LOT_SIZE) AS LOT_SIZE
                      FROM SSP_ANL_SHIP_PLAN_C XA
                         , SCM_MST_SITE XB
                         , SCP_MST_SHIPMENT_LOT_SIZE XC
                     WHERE XB.DIVISION_ID(+) = P_DIVISION_ID
                       AND XA.FROM_SITE = XB.SCM_SITE_ID(+)
                       AND XB.COMPANY_ID(+) = P_COMPANY_ID
                       AND XB.SITE_TYPE(+) = 'PLANT'
                       AND XB.VALID_YN(+) = 'Y'
                       AND XC.DIVISION_ID(+) = P_DIVISION_ID
                       AND XC.ITEM_ID(+) = XA.ITEM_ID
                       AND XC.FROM_SITE(+) = XA.FROM_SITE
                       AND XC.TO_SITE(+) = XA.TO_SITE
                       AND XC.TRANSPORT_MODE(+) = XA.TRANSPORT_MODE
                       AND XC.VALID_YN(+) = 'Y'
                       AND XC.SPLIT_YN(+) = 'Y'
                       AND XA.BIZ_TYPE <> 'E'
                       AND XA.QTY > 0
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.MEASURE = 'SHIP_PLAN'
                       AND XA.PLAN_START_YYYYMMDD = XA.YYYYMMDD
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD < P_PLAN_START_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                     GROUP BY XA.DIVISION_ID
                            , XA.FROM_SITE
                            , XA.ITEM_ID
                            , XA.TO_SITE
                            , XA.TRANSPORT_MODE
                            , XA.INCOTERMS
                            , XA.FCST_TYPE
                            , XA.YYYYMMDD
                    UNION ALL
                    SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , 'SHIP_RESULT' AS MEASURE
                         , XA.TO_SITE
                         , XA.TRANSPORT_MODE
                         , XA.INCOTERMS
                         , NULL AS FCST_TYPE
                         , 4 AS SEQ
                         , XA.YYYYMMDD
                         , 0 AS EDIT_CNT
                         , COUNT(*) AS TOT_CNT
                         , SUM(XA.RESULT_QTY) AS QTY
                         , 0 AS NOEDIT_QTY
                         , 0 AS LOT_SIZE
                      FROM GT_0060_SHIP_RESULT XA
                     GROUP BY XA.DIVISION_ID
                            , XA.FROM_SITE
                            , XA.ITEM_ID
                            , XA.TO_SITE
                            , XA.TRANSPORT_MODE
                            , XA.INCOTERMS
                            , XA.YYYYMMDD) IA
                 , SCP_MST_FINAL_ITEM B
             WHERE B.DIVISION_ID(+) = IA.DIVISION_ID
               AND B.ITEM_ID(+) = IA.ITEM_ID
               AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                OR B.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))))
             GROUP BY IA.DIVISION_ID
                    , IA.FROM_SITE
                    , B.GROUP_CODE1
                    , IA.ITEM_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.TRANSPORT_MODE
                    , IA.INCOTERMS
                    , IA.FCST_TYPE
                    , IA.SEQ
                    , IA.YYYYMMDD;

            /*--//2-4. INTN_MOVEMENT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , LOT_YN
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PRODUCT_LEVEL1
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , IA.QTY
                 , IA.LOT_YN
                 , IA.EDIT_YN
              FROM (SELECT A.DIVISION_ID
                         , A.FROM_SITE
                         , A.PRODUCT_LEVEL1
                         , A.ITEM_ID
                         , 'INTN_MOVEMENT' AS MEASURE
                         , A.TO_SITE
                         , A.TRANSPORT_MODE
                         , A.INCOTERMS
                         , A.FCST_TYPE
                         , 7 AS SEQ
                         , A.CONFIRM_DAY
                         , A.YYYYMMDD
                         , SUM(NVL(B.QTY, 0)) AS QTY
                         , NULL AS LOT_YN
                         , NULL AS EDIT_YN
                      FROM GT_0060_RESULT A
                         , (SELECT SA.DIVISION_ID
                                 , SB.SCM_SITE_ID AS FROM_SITE
                                 , SA.ITEM_ID
                                 , TO_CHAR(SA.PLAN_DATE, 'YYYYMMDD') AS YYYYMMDD
                                 , NVL(SA.QTY, 0) AS QTY
                              FROM SCM_DNM_CELL_INHOUSE_PLAN_SN SA
                                 , SCM_MST_SITE SB
                             WHERE SA.DIVISION_ID = SB.DIVISION_ID
                               AND SA.PLANT_ID = SB.PLANT_ID
                               AND SB.COMPANY_ID = P_COMPANY_ID
                               AND SB.SITE_TYPE = 'PLANT'
                               /* AND fs.osp_yn = 'N'  -- [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN = 'N' 조건제외) */
                               AND SB.VALID_YN = 'Y'
                               AND SA.DIVISION_ID = P_DIVISION_ID
                               AND SA.COMPANY_ID = P_COMPANY_ID
                               AND SA.CATEGORY = 'MOVING'
                               AND SA.PLAN_DATE >= TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD')
                               AND SA.PLAN_DATE <= TO_DATE(V_TO_YYYYMMDD, 'YYYYMMDD')
                               AND (TRIM(P_FROM_SITE) IS NULL
                                OR SB.SCM_SITE_ID IN (SELECT COLUMN_VALUE
                                                        FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                               AND (TRIM(P_ITEM_ID) IS NULL
                                OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                    FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                                OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                  FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                               AND SA.QTY > 0) B
                     WHERE A.DIVISION_ID = B.DIVISION_ID(+)
                       AND A.FROM_SITE = B.FROM_SITE(+)
                       AND A.ITEM_ID = B.ITEM_ID(+)
                       AND A.YYYYMMDD = B.YYYYMMDD(+)
                       AND A.MEASURE = 'SHIP_PLAN'
                     GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, A.ITEM_ID
                            , A.TO_SITE, A.TRANSPORT_MODE, A.INCOTERMS, A.FCST_TYPE
                            , A.YYYYMMDD, A.MEASURE, A.SEQ, A.CONFIRM_DAY
                    /*//CONTAINER */
                    UNION ALL
                    SELECT A.DIVISION_ID
                         , A.FROM_SITE
                         , A.PRODUCT_LEVEL1
                         , A.ITEM_ID
                         , 'CONTAINER' AS MEASURE
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , 8 AS SEQ
                         , A.CONFIRM_DAY
                         , A.YYYYMMDD
                         , CASE WHEN NVL(MAX(B.LOT_SIZE), 0) = 0 THEN 0 ELSE CEIL(MAX(NVL(A.QTY, 0)) / NVL(MAX(B.LOT_SIZE), 0)) END AS QTY
                         , NULL AS LOT_YN
                         , NULL AS EDIT_YN
                      FROM GT_0060_RESULT_DTL A
                         , SCP_MST_SHIPMENT_LOT_SIZE B
                     WHERE B.DIVISION_ID(+) = P_DIVISION_ID
                       AND B.ITEM_ID(+) = A.ITEM_ID
                       AND B.FROM_SITE(+) = A.FROM_SITE
                       /* AND B.TO_SITE = A.TO_SITE */
                       /* AND B.TRANSPORT_MODE = A.TRANSPORT_MODE */
                       AND B.VALID_YN(+) = 'Y'
                       AND B.SPLIT_YN(+) = 'Y'
                       AND A.MEASURE = 'SHIP_PLAN_DETAIL'
                     GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, A.ITEM_ID
                            , A.YYYYMMDD, A.CONFIRM_DAY) IA;

            /* CONTAINER 빈 칸 채우기 */
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , ITEM_ID
              , PRODUCT_LEVEL1
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , LOT_YN
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.ITEM_ID
                 , IA.PRODUCT_LEVEL1
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , NVL(B.QTY, 0) AS QTY
                 , NULL AS LOT_YN
                 , NULL AS EDIT_YN
              FROM (SELECT DISTINCT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , XA.PRODUCT_LEVEL1
                         , '' AS TO_SITE
                         , '' AS TRANSPORT_MODE
                         , '' AS INCOTERMS
                         , '' AS FCST_TYPE
                         , XA.CONFIRM_DAY
                         , XB.COLUMN_NAME AS MEASURE
                         , XB.SORT_ORDER_NO AS SEQ
                         , XC.BASIS_YYYYMMDD AS YYYYMMDD
                      FROM GT_0060_ROWDATA XA
                         , SCM_MST_SHEET_MEASURE XB
                         , SCM_SYS_CALENDAR_M XC
                     WHERE XB.PROGRAM_ID(+) = P_PROGRAM_ID
                       AND XB.SHEET_NAME(+) = P_SHEET_NAME
                       AND XC.BASIS_YYYYMMDD(+) >= V_FROM_YYYYMMDD
                       AND XC.BASIS_YYYYMMDD(+) <= V_TO_YYYYMMDD) IA
                 , GT_0060_ROWDATA B
                 , GT_0060_RESULT C
             WHERE IA.DIVISION_ID = B.DIVISION_ID(+)
               AND IA.FROM_SITE = B.FROM_SITE(+)
               AND IA.ITEM_ID = B.ITEM_ID(+)
               AND IA.MEASURE = B.MEASURE(+)
               AND IA.YYYYMMDD = B.YYYYMMDD(+)
               AND IA.DIVISION_ID = C.DIVISION_ID(+)
               AND IA.FROM_SITE = C.FROM_SITE(+)
               AND IA.ITEM_ID = C.ITEM_ID(+)
               AND IA.MEASURE = C.MEASURE(+)
               AND IA.YYYYMMDD = C.YYYYMMDD(+)
               AND IA.MEASURE IN ('CONTAINER')
               AND NVL(C.QTY, 0) = 0;

            /*--//4-1. WH_STOCK DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PRODUCT_LEVEL1
                 , IA.ITEM_ID
                 , 'WH_STOCK' AS MEASURE
                 , '' AS TO_SITE
                 , '' AS TRANSPORT_MODE
                 , '' AS INCOTERMS
                 , '' AS FCST_TYPE
                 , 10 AS SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'SHIP_PLAN' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'INTN_MOVEMENT' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'PROD_PLAN' THEN NVL(SA.QTY, 0)
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0060_RESULT SA
                     WHERE SA.DIVISION_ID = IA.DIVISION_ID
                       AND SA.FROM_SITE = IA.FROM_SITE
                       AND SA.ITEM_ID = IA.ITEM_ID
                       AND SA.MEASURE IN ('SHIP_PLAN', 'PROD_PLAN', 'INTN_MOVEMENT')
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD < IA.YYYYMMDD) + NVL(B.BOH_QTY, 0) AS QTY
                 , NULL AS EDIT_YN
              FROM (SELECT DIVISION_ID
                         , FROM_SITE
                         , PRODUCT_LEVEL1
                         , ITEM_ID
                         , YYYYMMDD
                         , CONFIRM_DAY
                      FROM GT_0060_RESULT
                     GROUP BY DIVISION_ID, FROM_SITE, PRODUCT_LEVEL1, ITEM_ID, YYYYMMDD, CONFIRM_DAY) IA
                 , (SELECT DIVISION_ID
                         , FROM_SITE
                         , ITEM_ID
                         , TO_CHAR(TO_DATE(YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') AS YYYYMMDD
                         , BOH_QTY AS BOH_QTY
                      FROM GT_0060_BOH
                     WHERE BOH_TYPE = 'BOH'
                       AND YYYYMMDD = V_BOH_YYYYMMDD) B
             WHERE IA.DIVISION_ID = B.DIVISION_ID(+)
               AND IA.FROM_SITE = B.FROM_SITE(+)
               AND IA.ITEM_ID = B.ITEM_ID(+);

            /*--//4-2. BALANCE DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , EDIT_YN
            )
            /* 당일 Balance = (당일 Warehouse Stock) - (당일 Shipment Plan) */
            SELECT DIVISION_ID
                 , FROM_SITE
                 , PRODUCT_LEVEL1
                 , ITEM_ID
                 , 'BALANCE' AS MEASURE
                 , TO_SITE
                 , TRANSPORT_MODE
                 , INCOTERMS
                 , FCST_TYPE
                 , 11 AS SEQ
                 , CONFIRM_DAY
                 , YYYYMMDD
                 , NVL(SUM(CASE WHEN MEASURE = 'SHIP_PLAN' THEN -1 * NVL(QTY, 0)
                                WHEN MEASURE = 'WH_STOCK' THEN NVL(QTY, 0)
                                ELSE 0
                           END), 0) AS QTY
                 , NULL AS EDIT_YN
              FROM GT_0060_RESULT
             WHERE MEASURE IN ('SHIP_PLAN', 'WH_STOCK')
             GROUP BY DIVISION_ID, FROM_SITE, PRODUCT_LEVEL1, ITEM_ID
                    , TO_SITE, TRANSPORT_MODE, INCOTERMS, FCST_TYPE
                    , YYYYMMDD, CONFIRM_DAY;

            /*--//4-3. SHIP AVALIABLE GAP DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , EDIT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PRODUCT_LEVEL1
                 , IA.ITEM_ID
                 , 'SHIP_AVAL_GAP' AS MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , 6 AS SEQ
                 , IA.CONFIRM_DAY
                 , IA.YYYYMMDD
                 , (SELECT NVL(SUM(CASE WHEN SA.MEASURE = 'SHIP_PLAN' THEN -1 * NVL(SA.QTY, 0)
                                        WHEN SA.MEASURE = 'SHIP_AVAL' THEN NVL(SA.QTY, 0)
                                        ELSE 0.0
                                   END), 0)
                      FROM GT_0060_RESULT SA
                     WHERE SA.DIVISION_ID = IA.DIVISION_ID
                       AND SA.FROM_SITE = IA.FROM_SITE
                       AND SA.ITEM_ID = IA.ITEM_ID
                       AND SA.MEASURE IN ('SHIP_PLAN', 'SHIP_AVAL')
                       AND SA.YYYYMMDD >= P_PLAN_START_YYYYMMDD
                       AND SA.YYYYMMDD <= IA.YYYYMMDD) AS QTY
                 , NULL AS EDIT_YN
              FROM (SELECT DIVISION_ID
                         , FROM_SITE
                         , PRODUCT_LEVEL1
                         , ITEM_ID
                         , TO_SITE
                         , TRANSPORT_MODE
                         , INCOTERMS
                         , FCST_TYPE
                         , YYYYMMDD
                         , CONFIRM_DAY
                      FROM GT_0060_RESULT
                     GROUP BY DIVISION_ID, FROM_SITE, PRODUCT_LEVEL1, ITEM_ID
                            , TO_SITE, TRANSPORT_MODE, INCOTERMS, FCST_TYPE
                            , YYYYMMDD, CONFIRM_DAY) IA;

            /*--//4-4. Total PSI DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , EDIT_YN
            )
            SELECT DIVISION_ID
                 , FROM_SITE
                 , PRODUCT_LEVEL1
                 , NULL AS ITEM_ID
                 , CASE MEASURE WHEN 'SHIP_REQ' THEN 'TOT_SHIP_REQ'
                                WHEN 'SHIP_PLAN' THEN 'TOT_SHIP_PLAN'
                                WHEN 'SHIP_AVAL' THEN 'TOT_SHIP_AVAL'
                                WHEN 'SHIP_AVAL_GAP' THEN 'TOT_SHIP_AVAL_GAP'
                                WHEN 'INTN_MOVEMENT' THEN 'TOT_INTN_MOVEMENT'
                                WHEN 'CONTAINER' THEN 'TOT_CONTAINER'
                                WHEN 'PROD_PLAN' THEN 'TOT_PROD_PLAN'
                                WHEN 'WH_STOCK' THEN 'TOT_WH_STOCK'
                                WHEN 'BALANCE' THEN 'TOT_BALANCE'
                   END AS MEASURE
                 , NULL AS TO_SITE
                 , NULL AS TRANSPORT_MODE
                 , NULL AS INCOTERMS
                 , NULL AS FCST_TYPE
                 , CASE MEASURE WHEN 'SHIP_REQ' THEN 12
                                WHEN 'SHIP_PLAN' THEN 13
                                WHEN 'SHIP_AVAL' THEN 14
                                WHEN 'SHIP_AVAL_GAP' THEN 15
                                WHEN 'INTN_MOVEMENT' THEN 16
                                WHEN 'CONTAINER' THEN 17
                                WHEN 'PROD_PLAN' THEN 18
                                WHEN 'WH_STOCK' THEN 19
                                WHEN 'BALANCE' THEN 20
                   END AS SEQ
                 , NULL AS CONFIRM_DAY
                 , YYYYMMDD
                 , SUM(QTY) AS QTY
                 , NULL AS EDIT_YN
              FROM GT_0060_RESULT
             WHERE YYYYMMDD >= P_PLAN_START_YYYYMMDD
             GROUP BY DIVISION_ID
                    , FROM_SITE
                    , PRODUCT_LEVEL1
                    , MEASURE
                    , YYYYMMDD;

            /*--//4-4. Shipment PLAN Detail DATA INSERT //--*/
            INSERT INTO GT_0060_RESULT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , QTY
              , LOT_YN
              , EDIT_YN
            )
            SELECT DIVISION_ID
                 , FROM_SITE
                 , PRODUCT_LEVEL1
                 , ITEM_ID
                 , MEASURE
                 , TO_SITE
                 , TRANSPORT_MODE
                 , INCOTERMS
                 , FCST_TYPE
                 , SEQ
                 , CONFIRM_DAY
                 , YYYYMMDD
                 , QTY
                 , LOT_YN
                 , EDIT_YN
              FROM GT_0060_RESULT_DTL;

            /*--//5. PIVOT //--*/
            INSERT INTO GT_0060_PIVOT
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , SEQ
              , CONFIRM_DAY
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , LOT_YN
              , EDIT_YN
            )
            SELECT A.DIVISION_ID
                 , A.FROM_SITE
                 , A.PRODUCT_LEVEL1
                 , A.ITEM_ID
                 , A.MEASURE
                 , A.TO_SITE
                 , A.TRANSPORT_MODE
                 , A.INCOTERMS
                 , A.FCST_TYPE
                 , A.SEQ
                 , A.CONFIRM_DAY
                 , 'D_' || A.YYYYMMDD AS YYYYMMDD
                 , B.BASIS_YYYYMM AS YYYYMM
                 , SUBSTR(B.BASIS_YYYYMM, -4) || B.ISO_WEEK AS ISO_WEEK
                 , A.QTY
                 , A.LOT_YN
                 , A.EDIT_YN
              FROM GT_0060_RESULT A
                 , SCM_SYS_CALENDAR_M B
             WHERE A.YYYYMMDD = B.BASIS_YYYYMMDD;
            /*PIVOIT처리*******************************************************************************/
            /* PIVOIT 대상 날짜문자열 생성 */
            V_QRY_SUM := '';

            FOR R IN (SELECT IA.YYYYMMDD
                        FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                                   , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                              UNION ALL
                              SELECT 'M_' || A.BASIS_YYYYMM AS YYYYMMDD
                                   , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                              UNION ALL
                              SELECT 'D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                                   , A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMMDD) IA
                       ORDER BY IA.SORT_ORDER_NO) LOOP

                IF INSTR(R.YYYYMMDD, 'M_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) ELSE 0 END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'W_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) ELSE 0 END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'D_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN CAST(NVL(A.QTY, 0) AS NUMBER(20, 10)) ELSE 0 END) AS ' || R.YYYYMMDD
                                           || ', MAX(CASE WHEN A.YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN NVL(A.EDIT_YN, ''-'') ELSE ''-'' END) AS EDIT_YN_' || SUBSTR(R.YYYYMMDD, 3) || CHR(10);
                END IF;

            END LOOP;
            /*--//END PIVOT//--*/

            /*--//6. RESULT //--*/
            V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
                   || ', A.FROM_SITE' || CHR(10)
                   || ', NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_DESCRIPTION' || CHR(10)
                   || ', A.PRODUCT_LEVEL1' || CHR(10)
                   || ', A.ITEM_ID' || CHR(10)
                   || ', (SELECT NVL(SA.NICK_NAME, ''-'') FROM SCM_MST_ITEM_SN SA WHERE SA.ITEM_ID = A.ITEM_ID AND ROWNUM = 1) AS NICK_NAME' || CHR(10)
                   || ', CASE WHEN B.BOH_TYPE IS NULL THEN' || CHR(10)
                   || '       CASE A.SEQ WHEN 11 THEN ''BOH''' || CHR(10)
                   || '                  WHEN 9 THEN ''ERP''' || CHR(10)
                   || '                  WHEN 7 THEN ''oWMS''' || CHR(10)
                   || '                  WHEN 8 THEN ''MES''' || CHR(10)
                   || '       ELSE NULL END' || CHR(10)
                   || '  ELSE B.BOH_TYPE END AS BOH_TYPE' || CHR(10)
                   || ', CASE WHEN (A.SEQ IN (7, 8, 9, 11)) THEN NVL(B.BOH_QTY, 0)' || CHR(10)
                   || '  ELSE NULL END AS BOH_QTY' || CHR(10)
                   || ', CASE A.MEASURE WHEN ''SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN_DETAIL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_RESULT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL_GAP'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''BALANCE'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_AVAL_GAP'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''TOT_WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''TOT_BALANCE'' THEN ''I'' END AS PSI' || CHR(10)
                   || ', A.MEASURE' || CHR(10)
                   || ', C.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                   || ', A.TO_SITE' || CHR(10)
                   || ', A.TRANSPORT_MODE' || CHR(10)
                   || ', A.INCOTERMS' || CHR(10)
                   || ', A.FCST_TYPE' || CHR(10)
                   || ', CASE WHEN A.SEQ < 12 THEN 1 ELSE 2 END AS ORD_SEQ' || CHR(10)
                   || ', A.SEQ' || CHR(10)
                   || ', TO_CHAR(TO_DATE(:B_PLAN_START1, ''YYYYMMDD'') + NVL(A.CONFIRM_DAY, 0), ''YYYYMMDD'') AS CONFIRM_DAY' || CHR(10)
                   || ', C.ATTRIBUTE3 AS BACK_COLOR' || CHR(10)
                   || ', A.LOT_YN' || CHR(10)
                   || V_QRY_SUM
                   || '  FROM GT_0060_PIVOT A' || CHR(10)
                   || '     , GT_0060_BOH B' || CHR(10)
                   || '     , SCM_MST_SHEET_MEASURE C' || CHR(10)
                   || '     , SCM_MST_TITLESET_USER D' || CHR(10)
                   || ' WHERE A.DIVISION_ID = B.DIVISION_ID(+)' || CHR(10)
                   || '   AND A.FROM_SITE = B.FROM_SITE(+)' || CHR(10)
                   || '   AND A.ITEM_ID = B.ITEM_ID(+)' || CHR(10)
                   || '   AND A.SEQ = B.SEQ(+)' || CHR(10)
                   || '   AND A.MEASURE = C.COLUMN_NAME' || CHR(10)
                   || '   AND C.PROGRAM_ID = :B_PROGRAM_ID1' || CHR(10)
                   || '   AND C.SHEET_NAME = :B_SHEET_NAME1' || CHR(10)
                   || '   AND D.PROGRAM_ID(+) = C.PROGRAM_ID' || CHR(10)
                   || '   AND D.SHEET_NAME(+) = C.SHEET_NAME' || CHR(10)
                   || '   AND D.COLUMN_NAME(+) = C.COLUMN_NAME' || CHR(10)
                   || '   AND D.USER_ID(+) = :B_USER_ID1' || CHR(10)
                   || '   AND C.VALID_YN = ''Y''' || CHR(10)
                   || '   AND (:B_CNT1 = 0' || CHR(10)
                   || '    OR EXISTS (SELECT 1' || CHR(10)
                   || '                 FROM GT_0060_TITLESET SA' || CHR(10)
                   || '                WHERE SA.COLUMN_NAME = C.COLUMN_NAME))' || CHR(10)
                   || '   AND ((:B_CNT2 = 0 AND C.DEFAULT_FLAG = ''Y'')' || CHR(10)
                   || '    OR (:B_CNT3 <> 0))' || CHR(10)
                   || ' GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, A.ITEM_ID, B.BOH_TYPE, B.BOH_QTY' || CHR(10)
                   || '        , A.MEASURE, C.COLUMN_LABEL_NAME, A.TO_SITE, A.TRANSPORT_MODE, A.INCOTERMS, A.FCST_TYPE, A.SEQ, A.CONFIRM_DAY, C.ATTRIBUTE3, A.LOT_YN' || CHR(10)
                   || ' ORDER BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, (CASE WHEN A.SEQ < 12 THEN 1 ELSE 2 END), A.ITEM_ID, A.SEQ, A.MEASURE, A.TO_SITE, A.TRANSPORT_MODE, A.INCOTERMS, A.FCST_TYPE';

            OPEN O_RC1 FOR V_EXEC USING P_PLAN_START_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_USER_ID, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE;
            /*--//END RESULT//--*/

        ELSE

            /*PIVOIT처리*******************************************************************************/
            /* PIVOIT 대상 날짜문자열 생성 */
            V_QRY_SUM := '';

            FOR R IN (SELECT IA.YYYYMMDD
                        FROM (SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                                   , A.BASIS_START_DATE || '21' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                              UNION ALL
                              SELECT 'M_' || A.BASIS_YYYYMM AS YYYYMMDD
                                   , MIN(A.BASIS_START_DATE) || '01' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                              UNION ALL
                              SELECT 'D_' || A.BASIS_YYYYMMDD AS YYYYMMDD
                                   , A.BASIS_YYYYMMDD || '31' AS SORT_ORDER_NO
                                FROM SCM_SYS_CALENDAR_M A
                               WHERE A.BASIS_YYYYMMDD BETWEEN V_FROM_YYYYMMDD AND V_TO_YYYYMMDD
                               GROUP BY A.BASIS_YYYYMMDD) IA
                       ORDER BY IA.SORT_ORDER_NO) LOOP

                IF INSTR(R.YYYYMMDD, 'M_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMM = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN A.QTY ELSE 0 END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'W_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.ISO_WEEK = ''' || SUBSTR(R.YYYYMMDD, -6) || ''' THEN A.QTY ELSE 0 END) AS ' || R.YYYYMMDD || CHR(10);
                ELSIF INSTR(R.YYYYMMDD, 'D_') = 1 THEN
                    V_QRY_SUM := V_QRY_SUM || ', SUM(CASE WHEN A.YYYYMMDD = ''' || R.YYYYMMDD || ''' THEN A.QTY ELSE 0 END) AS ' || R.YYYYMMDD || CHR(10);
                END IF;

            END LOOP;
            /*--//END PIVOT//--*/

            INSERT INTO GT_0060_PIVOT_OLD
            (
                DIVISION_ID
              , FROM_SITE
              , PRODUCT_LEVEL1
              , ITEM_ID
              , MEASURE
              , TO_SITE
              , TRANSPORT_MODE
              , INCOTERMS
              , FCST_TYPE
              , YYYYMMDD
              , YYYYMM
              , ISO_WEEK
              , QTY
              , LOT_YN
            )
            SELECT IA.DIVISION_ID
                 , IA.FROM_SITE
                 , CASE WHEN B.GROUP_CODE1 IS NULL THEN '-' ELSE B.GROUP_CODE1 END AS PRODUCT_LEVEL1
                 , IA.ITEM_ID
                 , IA.MEASURE
                 , IA.TO_SITE
                 , IA.TRANSPORT_MODE
                 , IA.INCOTERMS
                 , IA.FCST_TYPE
                 , IA.YYYYMMDD
                 , IA.YYYYMM
                 , IA.ISO_WEEK
                 , CASE WHEN IA.MEASURE IN ('SHIP_PLAN', 'SHIP_PLAN_DETAIL', 'SHIP_RESULT') THEN NVL(IA.QTY, 0)
                        ELSE (CASE WHEN IA.QTY = 0 THEN NULL ELSE IA.QTY END)
                   END AS QTY
                 , IA.LOT_YN
              FROM (SELECT XA.DIVISION_ID
                         , XA.FROM_SITE
                         , NVL(XD.APPLIED_MODEL, XA.ITEM_ID) AS ITEM_ID
                         , XA.MEASURE
                         , CASE WHEN XA.MEASURE = 'SHIP_PLAN' AND XA.TO_SITE <> '-' THEN XA.TO_SITE ELSE '' END AS TO_SITE
                         , CASE WHEN XA.MEASURE = 'SHIP_PLAN' AND XA.TRANSPORT_MODE <> '-' THEN XA.TRANSPORT_MODE ELSE '' END AS TRANSPORT_MODE
                         , CASE WHEN XA.MEASURE = 'SHIP_PLAN' AND XA.INCOTERMS <> '-' THEN XA.INCOTERMS ELSE '' END AS INCOTERMS
                         , CASE WHEN XA.MEASURE = 'SHIP_PLAN' AND XA.FCST_TYPE <> '-' THEN XA.FCST_TYPE ELSE '' END AS FCST_TYPE
                         , SUM(CAST(XA.QTY AS NUMBER(10))) AS QTY
                         , NULL AS LOT_YN
                         , 'D_' || XA.YYYYMMDD AS YYYYMMDD
                         , XB.BASIS_YYYYMM AS YYYYMM
                         , SUBSTR(XB.BASIS_YYYYMM, -4) || XB.ISO_WEEK AS ISO_WEEK
                      FROM SSP_ANL_SHIP_PLAN_C XA
                         , SCM_SYS_CALENDAR_M XB
                         , SCM_MST_SITE XC
                         , SCM_MST_ITEM_SN XD
                         , SCP_MST_FINAL_ITEM XE
                     WHERE XA.YYYYMMDD = XB.BASIS_YYYYMMDD
                       AND XC.DIVISION_ID = XA.DIVISION_ID
                       AND XC.SCM_SITE_ID = XA.FROM_SITE
                       AND XD.DIVISION_ID(+) = XA.DIVISION_ID
                       AND XD.COMPANY_ID(+) = P_COMPANY_ID
                       AND XD.SITE_ID(+) = XC.SITE_ID
                       AND XD.ITEM_ID(+) = XA.ITEM_ID
                       AND XD.ITEM_CLASS(+) IN ('ES1901', 'ES2001', 'ES2002', 'ES2003', 'ES2004')
                       AND XE.DIVISION_ID(+) = XA.DIVISION_ID
                       AND XE.ITEM_ID(+) = XA.ITEM_ID
                       AND XA.DIVISION_ID = P_DIVISION_ID
                       AND XA.COMPANY_ID = P_COMPANY_ID
                       AND XA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND XA.YYYYMMDD >= V_FROM_YYYYMMDD
                       AND XA.YYYYMMDD <= V_TO_YYYYMMDD
                       AND (TRIM(P_FROM_SITE) IS NULL
                        OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                       AND (TRIM(P_ITEM_ID) IS NULL
                        OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                            FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                        /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                        OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                          FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                     /* jilee 230901 */
                     GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XD.APPLIED_MODEL, XA.ITEM_ID, XA.MEASURE, XA.TO_SITE, XA.TRANSPORT_MODE, XA.INCOTERMS, XA.FCST_TYPE, XA.YYYYMMDD, XB.BASIS_YYYYMM, XB.ISO_WEEK) IA
                 , SCP_MST_FINAL_ITEM B
             WHERE B.DIVISION_ID(+) = IA.DIVISION_ID
               AND B.ITEM_ID(+) = IA.ITEM_ID
               AND (TRIM(P_PRODUCT_LEVEL1) IS NULL
                OR B.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_PRODUCT_LEVEL1, ','))));

            /* 중복되는 특정 아이템 지우기 */
            DELETE FROM GT_0060_PIVOT_OLD
             WHERE ITEM_ID IN (SELECT ITEM_ID
                                 FROM GT_0060_PIVOT_OLD
                                WHERE MEASURE = 'SHIP_PLAN'
                                  AND TO_SITE IS NOT NULL
                                GROUP BY ITEM_ID
                               HAVING COUNT(ITEM_ID) > 1)
               AND MEASURE = 'SHIP_PLAN'
               AND QTY = 0
               AND TO_SITE IS NULL;

            /* 2024/11/11 jilee 과거이력 보완 작업 */
            DELETE FROM GT_0060_PIVOT_OLD
             WHERE ITEM_ID IN (SELECT IA.ITEM_ID
                                 FROM (SELECT XA.ITEM_ID
                                         FROM GT_0060_PIVOT_OLD XA
                                        WHERE XA.MEASURE = 'SHIP_PLAN'
                                        GROUP BY XA.DIVISION_ID, XA.FROM_SITE, XA.PRODUCT_LEVEL1, XA.ITEM_ID, XA.MEASURE
                                               , XA.TO_SITE, XA.TRANSPORT_MODE, XA.INCOTERMS, XA.FCST_TYPE, XA.LOT_YN) IA
                                GROUP BY IA.ITEM_ID
                               HAVING COUNT(IA.ITEM_ID) > 1)
               AND MEASURE = 'SHIP_PLAN'
               AND QTY = 0
               AND TRANSPORT_MODE IS NULL
               AND INCOTERMS IS NULL
               AND FCST_TYPE IS NULL;

            V_EXEC := 'SELECT A.DIVISION_ID' || CHR(10)
                   || ', A.FROM_SITE' || CHR(10)
                   || ', NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_DESCRIPTION' || CHR(10)
                   || ', A.PRODUCT_LEVEL1' || CHR(10)
                   || ', (SELECT NVL(SA.NICK_NAME, ''-'') FROM SCM_MST_ITEM_SN SA WHERE SA.ITEM_ID = A.ITEM_ID AND ROWNUM = 1) AS NICK_NAME' || CHR(10)
                   || ', A.ITEM_ID' || CHR(10)
                   || ', CASE WHEN C.BOH_TYPE IS NULL THEN' || CHR(10)
                   || '       CASE B.SORT_ORDER_NO WHEN 11 THEN ''BOH''' || CHR(10)
                   || '                            WHEN 9 THEN ''ERP''' || CHR(10)
                   || '                            WHEN 7 THEN ''oWMS''' || CHR(10)
                   || '                            WHEN 8 THEN ''MES''' || CHR(10)
                   || '       ELSE NULL END' || CHR(10)
                   || '  ELSE C.BOH_TYPE END AS BOH_TYPE' || CHR(10)
                   || ', CASE WHEN (B.SORT_ORDER_NO = 1 OR B.SORT_ORDER_NO = 2 OR B.SORT_ORDER_NO = 3 OR B.SORT_ORDER_NO = 4) THEN NULL' || CHR(10)
                   || '  ELSE NVL(C.BOH_QTY, 0) END AS BOH_QTY' || CHR(10)
                   || ', CASE A.MEASURE WHEN ''SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_PLAN_DETAIL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_RESULT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''BALANCE'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_REQ'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_PLAN'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_SHIP_AVAL'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_INTN_MOVEMENT'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_CONTAINER'' THEN ''S''' || CHR(10)
                   || '                 WHEN ''TOT_PROD_PLAN'' THEN ''P''' || CHR(10)
                   || '                 WHEN ''TOT_WH_STOCK'' THEN ''I''' || CHR(10)
                   || '                 WHEN ''TOT_BALANCE'' THEN ''I'' END AS PSI' || CHR(10)
                   || ', A.MEASURE' || CHR(10)
                   || ', B.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                   || ', A.TO_SITE' || CHR(10)
                   || ', A.TRANSPORT_MODE' || CHR(10)
                   || ', A.INCOTERMS' || CHR(10)
                   || ', A.FCST_TYPE' || CHR(10)
                   || ', 1 AS ORD_SEQ' || CHR(10)
                   || ', B.SORT_ORDER_NO AS SEQ' || CHR(10)
                   || ', TO_CHAR(TO_DATE(:B_PLAN_START1, ''YYYYMMDD'') - 1 + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(''SSP'', A.DIVISION_ID, A.FROM_SITE, :B_PLAN_START2), ''YYYYMMDD'') AS CONFIRM_DAY' || CHR(10)
                   || ', B.ATTRIBUTE3 AS BACK_COLOR' || CHR(10)
                   || ', A.LOT_YN' || CHR(10)
                   || V_QRY_SUM
                   || '  FROM GT_0060_PIVOT_OLD A' || CHR(10)
                   || '     , SCM_MST_SHEET_MEASURE B' || CHR(10)
                   || '     , GT_0060_BOH C' || CHR(10)
                   || '     , SCM_MST_SITE D' || CHR(10)
                   || '     , SCM_MST_TITLESET_USER E' || CHR(10)
                   || ' WHERE A.MEASURE = B.COLUMN_NAME' || CHR(10)
                   || '   AND B.PROGRAM_ID = :B_PROGRAM_ID1' || CHR(10)
                   || '   AND B.SHEET_NAME = :B_SHEET_NAME1' || CHR(10)
                   || '   AND A.DIVISION_ID = C.DIVISION_ID(+)' || CHR(10)
                   || '   AND A.FROM_SITE = C.FROM_SITE(+)' || CHR(10)
                   || '   AND A.ITEM_ID = C.ITEM_ID(+)' || CHR(10)
                   || '   AND B.SORT_ORDER_NO = C.SEQ(+)' || CHR(10)
                   || '   AND A.DIVISION_ID = :B_DIVISION_ID1' || CHR(10)
                   || '   AND D.COMPANY_ID = :B_COMPANY_ID1' || CHR(10)
                   || '   AND A.FROM_SITE = D.SCM_SITE_ID' || CHR(10)
                   || '   AND D.SITE_TYPE = ''PLANT''' || CHR(10)
                   || '   AND D.VALID_YN = ''Y''' || CHR(10)
                   || '   AND E.PROGRAM_ID(+) = B.PROGRAM_ID' || CHR(10)
                   || '   AND E.SHEET_NAME(+) = B.SHEET_NAME' || CHR(10)
                   || '   AND E.COLUMN_NAME(+) = B.COLUMN_NAME' || CHR(10)
                   || '   AND E.USER_ID(+) = :B_USER_ID1' || CHR(10)
                   || '   AND B.VALID_YN = ''Y''' || CHR(10)
                   || '   AND (:B_CNT1 = 0' || CHR(10)
                   || '    OR EXISTS (SELECT 1' || CHR(10)
                   || '                 FROM GT_0060_TITLESET SA' || CHR(10)
                   || '                WHERE SA.COLUMN_NAME = B.COLUMN_NAME))' || CHR(10)
                   || '   AND ((:B_CNT2 = 0 AND B.DEFAULT_FLAG = ''Y'')' || CHR(10)
                   || '    OR (:B_CNT3 <> 0))' || CHR(10)
--                   || '   AND (:B_ITEM_ID1 IS NULL OR A.ITEM_ID = :B_ITEM_ID2)' || CHR(10)   --  2026.10.07 AJS
                /* || '   AND (:B_ITEM_ID1 IS NULL OR A.ITEM_ID MEMBER OF :B_ITEM_TAB)' || CHR(10)   --  2026.10.07 AJS */
                   || '   AND (:B_ITEM_ID1 IS NULL OR UPPER(TRIM(:B_ITEM_ID2)) = ''ALL'' OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(:B_ITEM_TAB)))' || CHR(10)   /* AJS 20261008 Model/Nickname */
                   || ' GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, A.ITEM_ID, A.MEASURE, B.COLUMN_LABEL_NAME' || CHR(10)
                   || '        , A.TO_SITE, A.TRANSPORT_MODE, A.INCOTERMS, A.FCST_TYPE, B.SORT_ORDER_NO, C.BOH_TYPE, C.BOH_QTY, D.SHIP_FROZEN, B.ATTRIBUTE3, A.LOT_YN' || CHR(10)
                   || ' ORDER BY A.DIVISION_ID, A.FROM_SITE, A.PRODUCT_LEVEL1, A.ITEM_ID, A.TO_SITE, A.TRANSPORT_MODE, A.INCOTERMS, A.FCST_TYPE, B.SORT_ORDER_NO';

            OPEN O_RC1 FOR V_EXEC USING P_PLAN_START_YYYYMMDD, P_PLAN_START_YYYYMMDD, P_PROGRAM_ID, P_SHEET_NAME, P_DIVISION_ID, P_COMPANY_ID, P_USER_ID
--                                      , V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, P_ITEM_ID, P_ITEM_ID;   --  2026.10.07 AJS
                                   /* , V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, P_ITEM_ID, V_ITEM_TAB;   --  2026.10.07 AJS */
                                      , V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, V_CNT_USR_MEASURE, P_ITEM_ID, P_ITEM_ID, V_ITEM_TAB;   /* AJS 20261008 Model/Nickname */

        END IF;

        /* NOTE Load */
        P_SSP0060_GET_SHIPMENT_PSI_COMMENTS(P_DIVISION_ID, P_COMPANY_ID, P_PLAN_START_YYYYMMDD, P_FROM_SITE, P_ITEM_ID, P_FROM_YYYYMMDD, P_TO_YYYYMMDD, O_RC2);

    END P_SSP0060_GET_SHIPMENT_PLAN;
    PROCEDURE P_SSP0060_GET_SHIPMENT_PLAN_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_PRODUCT_LEVEL1        IN  VARCHAR2
       ,P_REQUESTOR             IN  VARCHAR2
       ,P_TO_SITE               IN  VARCHAR2
       ,P_TRANSPORT_MODE        IN  VARCHAR2
       ,P_INCOTERMS             IN  VARCHAR2
       ,P_FCST_TYPE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_FROM_YYYYMMDD         IN  VARCHAR2
       ,P_TO_YYYYMMDD           IN  VARCHAR2
       ,P_DBL_FLAG              IN  VARCHAR2
       ,P_REAL_FLAG             IN  VARCHAR2
       ,P_LANGUAGE              IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,P_SHEET_NAME            IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_GET_SHIPMENT_PLAN_DETAIL
 * Description  : 자동차 Shipment Plan
 * Program History
 *===================================================================================================
 *   Date       In Charge		Description
 *===================================================================================================
 * 2019/09/06   mcThej			Initial Release [PJ20189106} 전지.GSCM 고도화 이행 PROJECT
 * 2019/11/14   ayj				CHANGE_REASON_CODE, CHANGE_REASON_DETAIL SELECT 값 수정
 * 2019/12/17	KIMYONGHO		[C20191216-000311] Expected Shipping Date 컬럼 추가
 * 2020/01/21   juhlee          [C20200121-000352]  ESS Packer출하 적용
 * 2020/02/10   KIMYONGHO       Shipmnet Status 조회 시 공통코드 타입으로 조회
 * 2020/03/12   KIMYONGHO       [C20200226-000471] Shipment Detail 탭 Project code 표시
 * 2020/03/26   KIMYONGHO       [C20200326-000217] Shipment Detail 탭 Team, Project Name 표시
 * 2021/02/04   KIMYONGHO	    ETA_DATE 조회 시 항차를 고려한 LT 적용(FN_GET_SSP_ETA_DATE)
 * 2021/10/18   KIMYONGHO	    [C20211001-000241][SCM PI팀] Shipment Plan (Auto ESS) 기능 개선 의건
 * 2022/12/19   jilee    	    오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영)
 * 2024/05/10   hsbang          확정구간 조회 일수(CONFIRM_DAY)를 FN_GET_ANL_SHIP_FROZEN_DAY_CNT 에서 조회
 * 2024.06.12   hsbang		파라미터 @p_product_level1 추가
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 * 2026.10.06   AJS          조회 속도 개선 - 마케팅 담당자 이름 함수 결과를 같은 담당자끼리 재사용(결과 동일)
 * 2026.10.07   AJS          화면검증 — 출하 예정일 결과 칸 이름을 칸 설정(Expected_Shipping_Date)과 같게
 * 2026.10.07   AJS          조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
 * 2026.10.08   AJS          Model/Nickname 후속 : 후보 목록 비교 MEMBER OF → IN(TABLE) · Model 'ALL' 은 조건 없음 · 더블클릭(P_DBL_FLAG=Y) 상세는 입력 코드 정확일치
 */
        V_APP_TYPE          VARCHAR2(8) := 'SSP';
        V_PRODUCT_LEVEL1    VARCHAR2(4000);
        V_DBL_FROM          VARCHAR2(8);
        V_DBL_TO            VARCHAR2(8);
        V_ITEM_TAB              T_STR_TAB := T_STR_TAB();   /* 2026.10.07 AJS Model/Nickname 검색 : 코드 또는 닉네임이 부분일치하는 품목 */
    BEGIN
        /* 2026.10.07 AJS Model/Nickname 검색 (START) */
/*        V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID); */
        IF P_DBL_FLAG = 'Y' THEN   /* AJS 20261008 Model/Nickname : 더블클릭 상세는 넘겨받은 행의 코드만(정확일치) */
            SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
              BULK COLLECT INTO V_ITEM_TAB   /* AJS 20261008 Model/Nickname */
              FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))   /* AJS 20261008 Model/Nickname */
             WHERE COLUMN_VALUE IS NOT NULL;   /* AJS 20261008 Model/Nickname */
        ELSE   /* AJS 20261008 Model/Nickname */
            V_ITEM_TAB := FN_SSP0060_ITEM_TAB(P_DIVISION_ID, P_ITEM_ID);   /* AJS 20261008 Model/Nickname */
        END IF;   /* AJS 20261008 Model/Nickname */
        /* 2026.10.07 AJS Model/Nickname 검색 (END) */

        /* 원문은 '-' 하나만 들어오면 조건을 끈다 */
        IF TRIM(P_PRODUCT_LEVEL1) = '-' THEN
            V_PRODUCT_LEVEL1 := NULL;
        ELSE
            V_PRODUCT_LEVEL1 := P_PRODUCT_LEVEL1;
        END IF;

        /* 더블클릭이면 단일 일자, 아니면 기간 */
        IF P_DBL_FLAG = 'Y' THEN
            V_DBL_FROM := P_FROM_YYYYMMDD;
            V_DBL_TO := P_FROM_YYYYMMDD;
        ELSE
            V_DBL_FROM := P_FROM_YYYYMMDD;
            V_DBL_TO := P_TO_YYYYMMDD;
        END IF;

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
                SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.ERP_DO_NO
                     , A.SHIPMENT_STATUS
                     , N.GROUP_CODE1 AS PRODUCT_LEVEL1
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.ITEM_ID) AS NICK_NAME
                     , A.FROM_SITE
                     , A.TO_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION
                     , NVL(A.PROJECT_CODE, '/') AS PROJECT_CODE
                     , NVL(FN_GET_PROJECT_NAME(A.DIVISION_ID, A.PROJECT_CODE), '-') AS PROJECT_NAME
                     , NVL(CASE WHEN A.DIVISION_ID = '40' THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-' THEN A.PROJECT_CODE ELSE E.PROJECT_CODE END
                                WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40' THEN E.PROJECT_CODE
                                ELSE D.END_CUSTOMER
                           END, NVL(L.END_CUSTOMER, '-')) AS END_CUSTOMER
--                     , CASE WHEN K.OWNER IS NOT NULL THEN TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(K.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                     , CASE WHEN K.OWNER IS NOT NULL THEN TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(K.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
--                            ELSE TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(L.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                            ELSE TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(L.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
                       END AS MTK_OWNER
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN I.USERNAME ELSE I.USERNAME_E END) IS NULL THEN NULL
                          --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN I.USERNAME ELSE I.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS REQUESTOR
                     , CAST(A.QTY AS NUMBER(10)) AS SHIPMENT_CONFIRM_QTY
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                     , B.TRANSPORT_MODE
                     , A.REMARKS2
                     , A.REMARKS
                     , '-' AS CHANGE_REASON_CODE
                     , NULL AS CHANGE_REASON_DETAIL
                     , A.REMARKS3
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                     , FN_GET_SITE_CUSTOMER_INFO((CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END), A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                     /* 20201223 incoterms 변경 작업 modify KIMYONGHO */
                     , B.SSP_INCOTERMS AS INCOTERMS
                     , B.LT_TOTAL AS LT_DAY
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                     , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                            ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')
--                       END AS "Expected_Shipping_Date"                         /* AJS 20261007 화면검증 */   --  2026.10.08 AJS
                       END AS "EXPECTED_SHIPPING_DATE"                         /* AJS 20261007 화면검증 */   --  2026.10.08 AJS
                    /* END AS EXPECTED_SHIPPING_DATE */
                     , A.FCST_TYPE
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END) IS NULL THEN NULL
                          --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN C.USERNAME ELSE C.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN C.USER_NM ELSE C.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS UPDATED_BY
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN C.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                     , CASE WHEN C.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                     /* 2026.09.30 AJS 수정 (END) */
                     , F.CHANGE_REQ_NO
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN H.USERNAME ELSE H.USERNAME_E END) IS NULL THEN NULL
                          --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN H.USERNAME ELSE H.USERNAME_E END) || '(' || G.USER_ID || ')'
                     , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END) IS NULL THEN NULL
                            ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END) || '(' || G.USER_ID || ')'
                     /* 2026.09.30 AJS 수정 (END) */
                       END AS MODEL_USER
                     , A.CONFIRM_ID
                     , B.LT_TOTAL AS NEW_LT_DAY
                     , B.TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                     , A.ERP_STATUS
                     , A.CHANGE_TYPE
                     , A.NEW_ROUTE_ID
                     , A.NEW_BOD_ID
                     , A.NEW_INCOTERMS
                     , A.NEW_D_COUNTRY
                     , A.NEW_D_PORT_CODE
                     , A.NEW_A_COUNTRY
                     , A.NEW_A_PORT_CODE
                     , A.NEW_CUSTOMER_LT
                     , A.NEW_TO_COUNTRY
                     , A.NEW_TO_CITY
                     , A.NEW_ETA
                     , A.NEW_ETD
                     , A.NEW_SHIPMENT_DATE
                     , A.EDIT_REMARKS
                     , A.EDIT_MAIN
                     , A.CHECK_NEED_YN
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     /* 20211117	SMS	수정 */
                     , NVL(E.DEPT_NAME_KO, NVL(L.DEPT_NAME_KO, '-')) AS TEAM
                     , A.ATTRIBUTE10
                     /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                     , B.A_COUNTRY
                     , B.A_PORT_CODE
                     , J.A_PORT_NAME
                     , P.COUNTRY_NAME
                     , Q.CITY_NAME
                     , O.SHIPTO_REGION_NAME
                     , O.SHIPTO_CITY_NAME
                  FROM (SELECT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.ERP_DO_NO
                             , XA.SHIPMENT_STATUS AS SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.PROJECT_CODE
                             , XA.REQUESTOR
                             , XA.QTY
                             , XA.YYYYMMDD
                             , XA.BOD_ID
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.CONFIRM_ID
                             , XA.FCST_TYPE
                             , XA.ERP_STATUS
                             , XA.CHANGE_TYPE
                             , TO_CHAR(XA.ROUTE_ID) AS NEW_ROUTE_ID
                             , XA.BOD_ID AS NEW_BOD_ID
                             , XA.INCOTERMS AS NEW_INCOTERMS
                             , XA.D_COUNTRY AS NEW_D_COUNTRY
                             , XA.D_PORT_CODE AS NEW_D_PORT_CODE
                             , XA.A_COUNTRY AS NEW_A_COUNTRY
                             , XA.A_PORT_CODE AS NEW_A_PORT_CODE
                             , TO_CHAR(XA.CUSTOMER_LT) AS NEW_CUSTOMER_LT
                             , XA.TO_COUNTRY AS NEW_TO_COUNTRY
                             , XA.TO_CITY AS NEW_TO_CITY
                             , TO_CHAR(TO_DATE(XA.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                             , TO_CHAR(TO_DATE(XA.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                             , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                             , 'N' AS EDIT_REMARKS
                             , 'N' AS EDIT_MAIN
                             , NVL(XA.CHECK_NEED_YN, 'N') AS CHECK_NEED_YN
                             , XA.ELECTRODE_YN
                             , XA.ELECTRODE_TYPE
                             , XA.ATTRIBUTE10
                          FROM SSP_ANL_SHIP_CONFIRM XA
                             , SCM_MST_ITEM_SN XB
                             , SCP_MST_FINAL_ITEM XC
                         WHERE XA.ITEM_ID = XB.ITEM_ID
                           AND XA.DIVISION_ID = XB.DIVISION_ID
                           AND XA.FROM_SITE_COMPANY_ID = XB.COMPANY_ID
                           AND XB.ITEM_TYPE NOT IN ('Q', 'R')
                           AND XC.DIVISION_ID(+) = XA.DIVISION_ID
                           AND XC.ITEM_ID(+) = XA.ITEM_ID
                           AND XA.CHANGE_TYPE = 'C'
                           AND XA.DIVISION_ID = P_DIVISION_ID
                           AND XA.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                           AND XA.BIZ_TYPE <> 'E'
                           AND XA.YYYYMMDD >= V_DBL_FROM
                           AND XA.YYYYMMDD <= V_DBL_TO
                           AND (TRIM(P_ITEM_ID) IS NULL
                            OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                            OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                            /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                            OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                              FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                           AND (TRIM(V_PRODUCT_LEVEL1) IS NULL
                            OR XC.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                    FROM TABLE(STRING_SPLIT(V_PRODUCT_LEVEL1, ','))))
                           AND (TRIM(P_FROM_SITE) IS NULL
                            OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                  FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                           /* 원문은 조회조건 값을 그대로 IN 절에 넣어 값으로 찾지 못한다 — 값 비교로 바로잡음 */
                           AND (P_DBL_FLAG = 'Y'
                            OR TRIM(P_REQUESTOR) IS NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
                                                --FROM TB_FX_USER SA
                                               --WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                            OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                  FROM SCM_ADM_USER_M SA
                                                 WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
                            /* 2026.09.30 AJS 수정 (END) */
                                                                         FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                    /* 2026.09.30 AJS 수정 (START) */
                                                  --OR SA.USERID IN (SELECT COLUMN_VALUE
                                                    OR SA.USER_ID IN (SELECT COLUMN_VALUE
                                                    /* 2026.09.30 AJS 수정 (END) */
                                                                       FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))
                        UNION ALL
                        SELECT XA.DIVISION_ID
                             , XA.ERP_SO_NO
                             , XA.ERP_DO_NO
                             , XA.SHIPMENT_STATUS
                             , XA.ITEM_ID
                             , XA.ORIGIN_FROM_DIVISION_ID
                             , XA.ORIGIN_TO_DIVISION_ID
                             , XA.FROM_SITE
                             , XA.TO_SITE
                             , XA.PROJECT_CODE
                             , XA.REQUESTOR
                             , XA.QTY
                             , XA.YYYYMMDD
                             , XA.BOD_ID
                             , XA.REMARKS2
                             , XA.REMARKS
                             , XA.CHANGE_REQ_NO
                             , XA.REMARKS3
                             , XA.ETD_DATE
                             , XA.ETA_DATE
                             , XA.LAST_UPDATED_BY
                             , XA.LAST_UPDATE_DATE
                             , XA.CONFIRM_ID
                             , XA.FCST_TYPE
                             , '-' AS ERP_STATUS
                             , '-' AS CHANGE_TYPE
                             , '-' AS NEW_ROUTE_ID
                             , '-' AS NEW_BOD_ID
                             , '-' AS NEW_INCOTERMS
                             , '-' AS NEW_D_COUNTRY
                             , '-' AS NEW_D_PORT_CODE
                             , '-' AS NEW_A_COUNTRY
                             , '-' AS NEW_A_PORT_CODE
                             , '-' AS NEW_CUSTOMER_LT
                             , '-' AS NEW_TO_COUNTRY
                             , '-' AS NEW_TO_CITY
                             , '-' AS NEW_ETA
                             , '-' AS NEW_ETD
                             , '-' AS NEW_SHIPMENT_DATE
                             , '-' AS EDIT_REMARKS
                             , '-' AS EDIT_MAIN
                             , '-' AS CHECK_NEED_YN
                             , '-' AS ELECTRODE_YN
                             , '-' AS ELECTRODE_TYPE
                             , '-' AS ATTRIBUTE10
                          FROM (SELECT SA.DIVISION_ID
                                     , '-' AS ERP_SO_NO
                                     , '-' AS ERP_DO_NO
                                     , 'P' AS SHIPMENT_STATUS
                                     , SA.ITEM_ID
                                     , SA.DIVISION_ID AS ORIGIN_FROM_DIVISION_ID
                                     , SA.DIVISION_ID AS ORIGIN_TO_DIVISION_ID
                                     , SA.PLANT_SITE_ID AS FROM_SITE
                                     , SA.SCM_SITE_ID AS TO_SITE
                                     , SA.PROJECT_CODE
                                     , '-' AS REQUESTOR
                                     , SA.QTY
                                     , SA.YYYYMMDD
                                     , SA.BOD_ID
                                     , '-' AS REMARKS2
                                     , '-' AS REMARKS
                                     , '-' AS CHANGE_REQ_NO
                                     , '-' AS REMARKS3
                                     , SA.YYYYMMDD AS ETD_DATE
                                     /* 2021/02/04 KIMYONGHO ETA_DATE 조회 시 항차를 고려한 LT 적용 FN_GET_SSP_ETA_DATE */
                                     , FN_GET_SSP_ETA_DATE(SA.DIVISION_ID, SA.BOD_ID, SA.YYYYMMDD) AS ETA_DATE
                                     , SA.LAST_UPDATED_BY
                                     , SA.LAST_UPDATE_DATE
                                     , '-' AS CONFIRM_ID
                                     , SA.FCST_TYPE
                                     , CASE WHEN NVL(SC.SHIP_FROZEN, 0) > 0
                                            THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + FN_GET_ANL_SHIP_FROZEN_DAY_CNT(V_APP_TYPE, SC.DIVISION_ID, SC.SCM_SITE_ID, P_PLAN_START_YYYYMMDD), 'YYYYMMDD')
                                            ELSE P_PLAN_START_YYYYMMDD
                                       END AS FROZEN_YYYYMMDD
                                  FROM DM_PLN_SHIPMENT_REQ SA
                                     , SCP_MST_BOD_N_V SB
                                     , SCM_MST_SITE SC
                                     , SCP_MST_FINAL_ITEM SD
                                 WHERE SA.DIVISION_ID = SB.DIVISION_ID
                                   AND SA.BOD_ID = SB.BOD_ID
                                   AND SA.DIVISION_ID = SC.DIVISION_ID
                                   AND SA.PLANT_SITE_ID = SC.SCM_SITE_ID
                                   AND SC.SITE_TYPE = 'PLANT'
                                   /* [C20200121-000352]-2 : FROM_SITE PACKER포함(OSP_YN = 'N' 조건제외) */
                                   /* AND tt2.osp_yn = 'N' */
                                   AND SC.VALID_YN = 'Y'
                                   AND SD.DIVISION_ID(+) = SA.DIVISION_ID
                                   AND SD.ITEM_ID(+) = SA.ITEM_ID
                                   AND SA.DIVISION_ID = P_DIVISION_ID
                                   AND SC.COMPANY_ID = P_COMPANY_ID
                                   AND SA.YYYYMMDD >= V_DBL_FROM
                                   AND SA.YYYYMMDD <= V_DBL_TO
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                    OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                    /* OR SA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                                    OR SA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                                   AND (TRIM(V_PRODUCT_LEVEL1) IS NULL
                                    OR SD.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(V_PRODUCT_LEVEL1, ','))))
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR SA.PLANT_SITE_ID IN (SELECT COLUMN_VALUE
                                                              FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))) XA
                         WHERE XA.YYYYMMDD >= XA.FROZEN_YYYYMMDD) A
                     , SCP_MST_BOD_N_V B
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER C
                     , SCM_ADM_USER_M C
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE D
                     , (SELECT SA.DIVISION_ID
                             , SA.PROJECT_CODE
                             , SA.SCM_SITE_ID
                             , SA.ITEM_ID
                             , SA.DEPT_NAME_KO
                          FROM (SELECT XA.DIVISION_ID
                                     , XA.PROJECT_CODE
                                     , XA.SCM_SITE_ID
                                     , XA.ITEM_ID
                                     , XC.DEPT_NAME_KO
                                     , ROW_NUMBER() OVER (PARTITION BY XA.DIVISION_ID, XA.SCM_SITE_ID, XA.ITEM_ID ORDER BY XA.PROJECT_CODE) AS NUM
                                  FROM SCM_MST_SITE_ITEM XA
                                     /* 부서 축을 아이템 원장으로 변경 (START) 2026.09.29 AJS */
--                                     , SCM_MST_SITE XB
                                     , SCM_MST_SSO_DEPT_INFO XC
--                                 WHERE XB.SCM_SITE_ID(+) = XA.SCM_SITE_ID
--                                   AND XB.DEPT_ID = XC.DEPT_ID(+)) SA
                                 WHERE XA.DEPT_ID = XC.DEPT_ID(+)) SA
                                     /* 부서 축을 아이템 원장으로 변경 (END) 2026.09.29 AJS */
                         WHERE SA.NUM = 1) E
                     , (SELECT SA.CONFIRM_ID
                             , SA.CHANGE_REQ_NO
                          FROM (SELECT XA.CONFIRM_ID
                                     , XA.CHANGE_REQ_NO
                                     , ROW_NUMBER() OVER (PARTITION BY XA.CONFIRM_ID ORDER BY XA.CHANGE_REQ_NO DESC) AS NUM
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE XA
                                 WHERE XA.VALID_YN = 'Y') SA
                         WHERE SA.NUM = 1) F
                     , SSP_MST_MODEL_USER G
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER H
                   --, TB_FX_USER I
                     , SCM_ADM_USER_M H
                     , SCM_ADM_USER_M I
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCP_MST_DISTRIBUTION_ROUTE J
                     , SCM_MST_SITE_ITEM K
                     , (SELECT IB.PLANT_ID
                             , IB.DIVISION_ID
                             , IB.PROJECT_CODE
                             , IB.SCM_SITE_ID
                             , IB.ITEM_ID
                             , SB.DEPT_ID
                             , NVL(SC.DEPT_NAME_KO, '-') AS DEPT_NAME_KO
                             , IB.OWNER AS OWNER
                             , IB.END_CUSTOMER
                             , IB.TO_SITE_DESCRIPTION
                          FROM (SELECT SA.SEGMENT2 AS PLANT_ID
                                     , SB.DIVISION_ID
                                     , SB.PROJECT_CODE
                                     , SB.SCM_SITE_ID
                                     , SB.ITEM_ID
                                     , SB.OWNER
                                     , NVL(SC.END_CUSTOMER, '-') AS END_CUSTOMER
                                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(SA.SEGMENT3, SA.SEGMENT2), '-') AS TO_SITE_DESCRIPTION
                                     , TRIM(REGEXP_SUBSTR(SB.OWNER, '[^,]+', 1, 1)) AS FIRST_OWNER
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                     , SCM_MST_SITE_ITEM SB
                                     , SCM_MST_SITE SC
                                 WHERE SA.LOOKUP_TYPE = 'AS_SITE_PLANT'
                                   AND SA.SEGMENT1 = SB.SCM_SITE_ID
                                   AND SB.DIVISION_ID = SC.DIVISION_ID(+)
                                   AND SB.SCM_SITE_ID = SC.SCM_SITE_ID(+)) IB
                             , SCM_MST_SSO_USER_INFO SB
                             , SCM_MST_SSO_DEPT_INFO SC
                         WHERE IB.FIRST_OWNER = SB.USER_ID(+)
                           AND SB.DEPT_ID = SC.DEPT_ID(+)) L
                     , SSP_ANL_SHIP_CONFIRM_CHG_REQ M
                     , SCP_MST_FINAL_ITEM N
                     , SCM_MST_CUSTOMER O
                     , SCM_MST_COUNTRY P
                     , SCM_MST_CITY Q
                     , SCM_MST_SITE_CUSTOMER R
                 WHERE (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = B.DIVISION_ID
                   AND A.BOD_ID = B.BOD_ID
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND A.LAST_UPDATED_BY = C.USERID(+)
                 --AND C.USEYN(+) = 'Y'
                   AND A.LAST_UPDATED_BY = C.USER_ID(+)
                   AND C.USE_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND D.SCM_SITE_ID = A.TO_SITE
                   /* NERP 적용시 GERP COMPANY_ID에 해당하는 것은 제외 필요함 */
                   AND D.VALID_YN = 'Y'
                   AND D.DIVISION_ID <> '40'
                   AND E.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END)
                   AND E.SCM_SITE_ID(+) = A.TO_SITE
                   AND E.ITEM_ID(+) = A.ITEM_ID
                   AND F.CONFIRM_ID(+) = A.CONFIRM_ID
                   AND G.DIVISION_ID(+) = A.ORIGIN_FROM_DIVISION_ID
                   AND G.FROM_SITE(+) = A.FROM_SITE
                   AND G.ITEM_ID(+) = A.ITEM_ID
                   AND G.VALID_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND G.USER_ID = H.USERID(+)
                 --AND H.USEYN(+) = 'Y'
                 --AND A.REQUESTOR = I.USERID(+)
                 --AND I.USEYN(+) = 'Y'
                   AND G.USER_ID = H.USER_ID(+)
                   AND H.USE_YN(+) = 'Y'
                   AND A.REQUESTOR = I.USER_ID(+)
                   AND I.USE_YN(+) = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND J.ROUTE_ID(+) = B.ROUTE_ID
                   AND K.DIVISION_ID(+) = (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END)
                   AND K.SCM_SITE_ID(+) = A.TO_SITE
                   AND K.ITEM_ID(+) = A.ITEM_ID
                   AND K.PROJECT_CODE(+) = A.PROJECT_CODE
                   /* 20211117	SMS	추가 */
                   AND A.DIVISION_ID = L.DIVISION_ID(+)
                   AND A.PROJECT_CODE = L.PROJECT_CODE(+)
                   AND A.TO_SITE = L.PLANT_ID(+)
                   AND A.ITEM_ID = L.ITEM_ID(+)
                   AND F.CHANGE_REQ_NO = M.CHANGE_REQ_NO(+)
                   AND N.DIVISION_ID(+) = A.DIVISION_ID
                   AND N.ITEM_ID(+) = A.ITEM_ID
                   /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                   AND D.DIVISION_ID = R.DIVISION_ID(+)
                   AND D.SCM_SITE_ID = R.SCM_SITE_ID(+)
                   AND R.REP_YN(+) = 'Y'
                   AND R.VALID_YN(+) = 'Y'
                   AND R.DIVISION_ID = O.DIVISION_ID(+)
                   AND R.SOLDTO_CODE = O.SOLDTO_CODE(+)
                   AND R.SHIPTO_CODE = O.SHIPTO_CODE(+)
                   AND D.COUNTRY = P.COUNTRY(+)
                   AND D.COUNTRY = Q.COUNTRY(+)
                   AND D.CITY = Q.CITY(+)
                   AND A.SHIPMENT_STATUS IS NOT NULL
                   AND A.QTY > 0
                   AND (TRIM(P_TO_SITE) IS NULL
                    OR A.TO_SITE IN (SELECT COLUMN_VALUE
                                       FROM TABLE(STRING_SPLIT(P_TO_SITE, ','))))
                   AND (TRIM(P_TRANSPORT_MODE) IS NULL
                    OR B.TRANSPORT_MODE IN (SELECT COLUMN_VALUE
                                              FROM TABLE(STRING_SPLIT(P_TRANSPORT_MODE, ','))))
                   AND (TRIM(P_INCOTERMS) IS NULL
                    OR B.SSP_INCOTERMS IN (SELECT COLUMN_VALUE
                                             FROM TABLE(STRING_SPLIT(P_INCOTERMS, ','))))
                   AND (TRIM(P_FCST_TYPE) IS NULL
                    OR A.FCST_TYPE IN (SELECT COLUMN_VALUE
                                         FROM TABLE(STRING_SPLIT(P_FCST_TYPE, ','))))
                 ORDER BY A.DIVISION_ID, A.SHIPMENT_STATUS, A.YYYYMMDD, A.ITEM_ID, A.ERP_SO_NO DESC, A.ERP_DO_NO DESC, A.FROM_SITE, A.TO_SITE, A.PROJECT_CODE, A.FCST_TYPE;

        ELSE

            OPEN O_RC1 FOR
                SELECT IA.*
                  FROM (SELECT A.DIVISION_ID
                             , A.ERP_SO_NO
                             , '-' AS ERP_DO_NO
                             , A.SHIPMENT_STATUS
                             , C.GROUP_CODE1 AS PRODUCT_LEVEL1
                             , A.PROJECT_CODE
                             , A.PROJECT_NAME
                             , A.FCST_TYPE
                             , A.ITEM_ID
                             , A.NICK_NAME
                             , A.SHIPMENT_DATE
                             , A.SHIPMENT_CONFIRM_QTY
                             , A.REMARKS
                             , A.REMARKS2
                             , A.REMARKS3
                             , A.FROM_SITE
                             , A.FROM_SITE_DESCRIPTION
                             , A.TO_SITE
                             , A.TO_SITE_DESCRIPTION
                             , A.TO_SITE_SOLDTO_CODE
                             , A.TO_SITE_SHIPTO_CODE
                             , A.SOLDTO_DESCRIPTION
                             , A.SHIPTO_DESCRIPTION
                             , A.BOD_ID
                             , A.INCOTERMS
                             , A.TRANSPORT_MODE
                             , A.LT_DAY
                             , A.ETD
                             , A.ETA
--                             , A.EXPECTED_SHIPPING_DATE AS "Expected_Shipping_Date"    /* AJS 20261007 화면검증 */   --  2026.10.08 AJS
                             , A.EXPECTED_SHIPPING_DATE AS "EXPECTED_SHIPPING_DATE"    /* AJS 20261007 화면검증 */   --  2026.10.08 AJS
                             /* , A.EXPECTED_SHIPPING_DATE */
                             , A.CONFIRM_ID
                             , A.UPDATED_BY
                             , A.UPDATED_DATE
                             , '-' AS ERP_STATUS
                             , '-' AS CHANGE_TYPE
                             , '-' AS NEW_ROUTE_ID
                             , '-' AS NEW_BOD_ID
                             , '-' AS NEW_INCOTERMS
                             , '-' AS NEW_D_COUNTRY
                             , '-' AS NEW_D_PORT_CODE
                             , '-' AS NEW_A_COUNTRY
                             , '-' AS NEW_A_PORT_CODE
                             , '-' AS NEW_CUSTOMER_LT
                             , '-' AS NEW_TO_COUNTRY
                             , '-' AS NEW_TO_CITY
                             , '-' AS NEW_ETA
                             , '-' AS NEW_ETD
                             , '-' AS NEW_LT_DAY
                             , '-' AS NEW_TRANSPORT_MODE
                             , '-' AS NEW_SHIPMENT_DATE
                             , '-' AS EDIT_REMARKS
                             , '-' AS EDIT_MAIN
                             , '-' AS CHECK_NEED_YN
                             /* 20211118	SMS	수정 */
                             , CASE WHEN A.END_CUSTOMER IS NOT NULL AND A.END_CUSTOMER <> '-' THEN A.END_CUSTOMER ELSE NVL(B.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , '-' AS ELECTRODE_YN
                             , '-' AS ELECTRODE_TYPE
                             , '-' AS ORIGIN_FROM_DIVISION_ID
                             , '-' AS ORIGIN_TO_DIVISION_ID
                             , A.CHANGE_REQ_NO AS CHANGE_REQ_NO
                             , A.MODEL_USER AS MODEL_USER
                             /* 20211118	SMS	수정 */
                             , CASE WHEN A.MTK_OWNER IS NOT NULL AND A.MTK_OWNER <> '-' THEN A.MTK_OWNER
--                                    ELSE TO_CHAR(FN_GET_SSP_MKT_OWNER_NAME(B.OWNER, ',', P_LANGUAGE))  --  2026.10.06 AJS
                                    ELSE TO_CHAR((SELECT FN_GET_SSP_MKT_OWNER_NAME(B.OWNER, ',', P_LANGUAGE) FROM DUAL))  --  2026.10.06 AJS
                               END AS MTK_OWNER
                             , A.REQUESTOR AS REQUESTOR
                             , '-' AS CHANGE_REASON_CODE
                             , '-' AS CHANGE_REASON_DETAIL
                             /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                             , F.A_COUNTRY
                             , F.A_PORT_CODE
                             , G.A_PORT_NAME
                             , H.COUNTRY_NAME
                             , I.CITY_NAME
                             , J.SHIPTO_REGION_NAME
                             , J.SHIPTO_CITY_NAME
                          FROM (SELECT XA.DIVISION_ID
                                     , XA.ERP_SO_NO
                                     , XA.SHIPMENT_STATUS
                                     , XA.ITEM_ID
                                     , XA.NICK_NAME
                                     , XA.ORIGIN_FROM_DIVISION_ID
                                     , XA.ORIGIN_TO_DIVISION_ID
                                     , XA.FROM_SITE
                                     , XA.FROM_SITE_DESCRIPTION
                                     , XA.TO_SITE
                                     , XA.TO_SITE_DESCRIPTION
                                     , XA.PROJECT_CODE
                                     , XA.PROJECT_NAME
                                     , XA.REQUESTOR
                                     , XA.SHIPMENT_CONFIRM_QTY
                                     , TO_CHAR(TO_DATE(XA.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                                     , XA.BOD_ID
                                     , XA.INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.TO_SITE_SOLDTO_CODE
                                     , XA.TO_SITE_SHIPTO_CODE
                                     , XA.SOLDTO_DESCRIPTION
                                     , XA.SHIPTO_DESCRIPTION
                                     , XA.REMARKS2
                                     , XA.REMARKS
                                     , XA.CHANGE_REQ_NO
                                     , XA.REMARKS3
                                     , TO_CHAR(TO_DATE(XA.ETD, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                                     , TO_CHAR(TO_DATE(XA.ETA, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                                     , XA.EXPECTED_SHIPPING_DATE
                                     , XA.LT_DAY AS LT_DAY
                                     , XA.UPDATED_BY AS UPDATED_BY
                                     , XA.UPDATED_DATE AS UPDATED_DATE
                                     , XA.CONFIRM_ID AS CONFIRM_ID
                                     , XA.FCST_TYPE
                                     , XA.END_CUSTOMER
                                     , XA.MTK_OWNER
                                     , XA.MODEL_USER
                                  FROM SSP_ANL_SHIP_PLAN_ALL XA
                                     , SCM_MST_ITEM_SN XB
                                     , SSP_MST_MODEL_USER XC
                                     , SCP_MST_FINAL_ITEM XD
                                 WHERE XA.ITEM_ID = XB.ITEM_ID
                                   AND XA.DIVISION_ID = XB.DIVISION_ID
                                   AND XA.COMPANY_ID = XB.COMPANY_ID
                                   AND XB.ITEM_TYPE NOT IN ('Q', 'R')
                                   AND XC.DIVISION_ID(+) = XA.ORIGIN_FROM_DIVISION_ID
                                   AND XC.FROM_SITE(+) = XA.FROM_SITE
                                   AND XC.ITEM_ID(+) = XA.ITEM_ID
                                   AND XC.VALID_YN(+) = 'Y'
                                   AND XD.DIVISION_ID(+) = XA.DIVISION_ID
                                   AND XD.ITEM_ID(+) = XA.ITEM_ID
                                   AND XA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                   AND XA.DIVISION_ID = P_DIVISION_ID
                                   AND XA.COMPANY_ID = P_COMPANY_ID
                                   AND XA.SHIPMENT_CONFIRM_QTY > 0
                                   AND XA.OPERATION_GROUP <> 'E'
                                   AND XA.YYYYMMDD >= V_DBL_FROM
                                   AND XA.YYYYMMDD <= V_DBL_TO
                                   AND (TRIM(P_ITEM_ID) IS NULL
                                    OR UPPER(TRIM(P_ITEM_ID)) = 'ALL'   /* AJS 20261008 Model/Nickname */
--                                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   --  2026.10.07 AJS
--                                                        FROM TABLE(STRING_SPLIT(P_ITEM_ID, ','))))   --  2026.10.07 AJS
                                    /* OR XA.ITEM_ID MEMBER OF V_ITEM_TAB)   --  2026.10.07 AJS */
                                    OR XA.ITEM_ID IN (SELECT COLUMN_VALUE   /* AJS 20261008 Model/Nickname */
                                                      FROM TABLE(V_ITEM_TAB)))   /* AJS 20261008 Model/Nickname */
                                   AND (TRIM(V_PRODUCT_LEVEL1) IS NULL
                                    OR XD.GROUP_CODE1 IN (SELECT COLUMN_VALUE
                                                            FROM TABLE(STRING_SPLIT(V_PRODUCT_LEVEL1, ','))))
                                   AND (TRIM(P_FROM_SITE) IS NULL
                                    OR XA.FROM_SITE IN (SELECT COLUMN_VALUE
                                                          FROM TABLE(STRING_SPLIT(P_FROM_SITE, ','))))
                                   /* 원문은 조회조건 값을 그대로 IN 절에 넣어 값으로 찾지 못한다 — 값 비교로 바로잡음 */
                                   AND (P_DBL_FLAG = 'Y'
                                    OR TRIM(P_REQUESTOR) IS NULL
                                    /* 2026.09.30 AJS 수정 (START) */
                                  --OR XA.REQUESTOR IN (SELECT DISTINCT SA.USERID
                                                        --FROM TB_FX_USER SA
                                                       --WHERE SA.USERNAME IN (SELECT COLUMN_VALUE
                                    OR XA.REQUESTOR IN (SELECT DISTINCT SA.USER_ID
                                                          FROM SCM_ADM_USER_M SA
                                                         WHERE SA.USER_NM IN (SELECT COLUMN_VALUE
                                    /* 2026.09.30 AJS 수정 (END) */
                                                                                 FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))
                                                            /* 2026.09.30 AJS 수정 (START) */
                                                          --OR SA.USERID IN (SELECT COLUMN_VALUE
                                                            OR SA.USER_ID IN (SELECT COLUMN_VALUE
                                                            /* 2026.09.30 AJS 수정 (END) */
                                                                               FROM TABLE(STRING_SPLIT(P_REQUESTOR, ',')))))) A
                             , (SELECT IB.PLANT_ID
                                     , IB.DIVISION_ID
                                     , IB.PROJECT_CODE
                                     , IB.SCM_SITE_ID
                                     , IB.ITEM_ID
                                     , NVL(SC.DEPT_NAME_KO, '-') AS DEPT_NAME_KO
                                     , IB.OWNER AS OWNER
                                     , IB.END_CUSTOMER
                                     , IB.TO_SITE_DESCRIPTION
                                  FROM (SELECT SA.SEGMENT2 AS PLANT_ID
                                             , SB.DIVISION_ID
                                             , SB.PROJECT_CODE
                                             , SB.SCM_SITE_ID
                                             , SB.ITEM_ID
                                             , SB.OWNER
                                             , NVL(SC.END_CUSTOMER, '-') AS END_CUSTOMER
                                             , NVL(FN_GET_SCM_SITE_DESCRIPTION(SA.SEGMENT3, SA.SEGMENT2), '-') AS TO_SITE_DESCRIPTION
                                             , TRIM(REGEXP_SUBSTR(SB.OWNER, '[^,]+', 1, 1)) AS FIRST_OWNER
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                                             , SCM_MST_SITE_ITEM SB
                                             , SCM_MST_SITE SC
                                         WHERE SA.LOOKUP_TYPE = 'AS_SITE_PLANT'
                                           AND SA.SEGMENT1 = SB.SCM_SITE_ID
                                           AND SB.DIVISION_ID = SC.DIVISION_ID(+)
                                           AND SB.SCM_SITE_ID = SC.SCM_SITE_ID(+)) IB
                                     , SCM_MST_SSO_USER_INFO SB
                                     , SCM_MST_SSO_DEPT_INFO SC
                                 WHERE IB.FIRST_OWNER = SB.USER_ID(+)
                                   AND SB.DEPT_ID = SC.DEPT_ID(+)) B
                             , SCP_MST_FINAL_ITEM C
                             , SCM_MST_SITE E
                             , SCP_MST_BOD_N_V F
                             , SCP_MST_DISTRIBUTION_ROUTE G
                             , SCM_MST_COUNTRY H
                             , SCM_MST_CITY I
                             , SCM_MST_CUSTOMER J
                             , SCM_MST_SITE_CUSTOMER K
                         WHERE A.DIVISION_ID = B.DIVISION_ID(+)
                           AND A.PROJECT_CODE = B.PROJECT_CODE(+)
                           AND A.TO_SITE_DESCRIPTION = B.TO_SITE_DESCRIPTION(+)
                           AND A.ITEM_ID = B.ITEM_ID(+)
                           AND C.DIVISION_ID(+) = A.DIVISION_ID
                           AND C.ITEM_ID(+) = A.ITEM_ID
                           /* 221219 jilee 오창 출하 물류 R&R 관련 F.Destination 정보 활용 방안 (요청자:임화영) */
                           AND E.DIVISION_ID(+) = A.DIVISION_ID
                           AND E.SCM_SITE_ID(+) = A.TO_SITE
                           AND E.VALID_YN(+) = 'Y'
                           AND (CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END) = F.DIVISION_ID(+)
                           AND A.BOD_ID = F.BOD_ID(+)
                           AND G.ROUTE_ID(+) = F.ROUTE_ID
                           AND E.DIVISION_ID = K.DIVISION_ID(+)
                           AND E.SCM_SITE_ID = K.SCM_SITE_ID(+)
                           AND K.REP_YN(+) = 'Y'
                           AND K.VALID_YN(+) = 'Y'
                           AND K.DIVISION_ID = J.DIVISION_ID(+)
                           AND K.SOLDTO_CODE = J.SOLDTO_CODE(+)
                           AND K.SHIPTO_CODE = J.SHIPTO_CODE(+)
                           AND E.COUNTRY = H.COUNTRY(+)
                           AND E.COUNTRY = I.COUNTRY(+)
                           AND E.CITY = I.CITY(+)) IA
                 WHERE (TRIM(P_TO_SITE) IS NULL
                    OR IA.TO_SITE IN (SELECT COLUMN_VALUE
                                        FROM TABLE(STRING_SPLIT(P_TO_SITE, ','))))
                   AND (TRIM(P_TRANSPORT_MODE) IS NULL
                    OR IA.TRANSPORT_MODE IN (SELECT COLUMN_VALUE
                                               FROM TABLE(STRING_SPLIT(P_TRANSPORT_MODE, ','))))
                   AND (TRIM(P_INCOTERMS) IS NULL
                    OR IA.INCOTERMS IN (SELECT COLUMN_VALUE
                                          FROM TABLE(STRING_SPLIT(P_INCOTERMS, ','))))
                   AND (TRIM(P_FCST_TYPE) IS NULL
                    OR IA.FCST_TYPE IN (SELECT COLUMN_VALUE
                                          FROM TABLE(STRING_SPLIT(P_FCST_TYPE, ','))))
                 ORDER BY IA.DIVISION_ID, IA.SHIPMENT_STATUS, IA.SHIPMENT_DATE, IA.ITEM_ID, IA.ERP_SO_NO DESC, IA.FROM_SITE, IA.TO_SITE, IA.PROJECT_CODE, IA.FCST_TYPE;

        END IF;

    END P_SSP0060_GET_SHIPMENT_PLAN_DETAIL;
    PROCEDURE P_SSP0060_DELETE_SHIPMENT_REQUEST_DRAFTING
    (
        P_CHANGE_REQUEST_NO     IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_DELETE_SHIPMENT_REQUEST_DRAFTING
 * Description  : Shipment Plan Change 작성중 삭제
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_LAST_UPDATE_DATE  DATE;
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME      VARCHAR2(150) := 'PKG_SSP0060.P_SSP0060_DELETE_SHIPMENT_REQUEST_DRAFTING';
        V_LOG_TYPE          VARCHAR2(30);                                       /* START/END/ERROR/... */
        N_LOG_COUNT         NUMBER := 0;
        V_LOG_MESSAGE       VARCHAR2(1000);
        V_DESCRIPTION       VARCHAR2(500);
        D_EVENT_DATE        DATE;
        V_ERR_MSG           VARCHAR2(4000);
        V_ERR_CODE          NUMBER;
    BEGIN

        V_LAST_UPDATE_DATE := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := V_LAST_UPDATE_DATE;                                     /* [dbo].[FN_MULTY_TIME](@p_time_zone); */
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
           SET VALID_YN = 'N'
             , LAST_UPDATED_BY = P_USER_ID
             , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
         WHERE CHANGE_REQ_NO = P_CHANGE_REQUEST_NO;

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0060_DELETE_SHIPMENT_REQUEST_DRAFTING;

    PROCEDURE P_SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING_MAIN
    (
        P_ACTIVE_FLAG           IN  VARCHAR2
       ,P_DIVISION_ID           IN  VARCHAR2
       ,P_CHANGE_REQ_NO         IN  VARCHAR2
       ,P_CONFIRM_ID            IN  VARCHAR2
       ,P_SHIPMENT_QTY          IN  VARCHAR2
       ,P_SHIPMENT_DATE         IN  VARCHAR2
       ,P_NEW_YYYYMMDD          IN  VARCHAR2
       ,P_NEW_QTY               IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_CHANGE_REASON_CODE    IN  VARCHAR2
       ,P_CHANGE_REASON_DETAIL  IN  VARCHAR2
       ,P_TITLE                 IN  VARCHAR2
       ,P_PROGRAM_ID            IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING_MAIN
 * Description  : Shipment Plan Change 작성중 저장
 * 호출			: SSP0060
 * 관련 Table	: SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2019/05/15	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  CHAGE_REASON_CODE, CHAGE_REASON_DETAIL PARAM추가
 * 2024/05/22	hsbang			SSP_ANL_SHIP_CONFIRM_CHG_REQ_de A.ATTRIBUTE2(status_detail) 입력
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_MAX_REQ_NO            VARCHAR2(40);
        V_ACTIVE_FLAG           VARCHAR2(4000);
        V_DIVISION_ID           VARCHAR2(4000);
        V_CONFIRM_ID            VARCHAR2(4000);
        V_SHIPMENT_QTY          VARCHAR2(4000);
        V_SHIPMENT_DATE         VARCHAR2(4000);
        V_NEW_YYYYMMDD          VARCHAR2(4000);
        V_NEW_QTY               VARCHAR2(4000);
        V_CHANGE_REASON_CODE    VARCHAR2(4000);
        V_CHANGE_REASON_DETAIL  VARCHAR2(4000);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME          VARCHAR2(150) := P_PROGRAM_ID || '-' || P_TITLE;
        V_LOG_TYPE              VARCHAR2(30);                                   /* START/END/ERROR/... */
        N_LOG_COUNT             NUMBER := 0;
        V_LOG_MESSAGE           VARCHAR2(1000);
        V_DESCRIPTION           VARCHAR2(500);
        D_EVENT_DATE            DATE;
        V_DELIMITER             VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT          NUMBER := 0;
        V_MST_LOOP_CNT          NUMBER := 0;
        V_ERR_MSG               VARCHAR2(4000);
        V_ERR_CODE              NUMBER;
    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            /* SET @v_change_req_no = dbo.SCM_ARR_SPL_VAL( @p_change_req_no, @v_delimiter, @mst_loop_cnt ); */
            V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_QTY := SCM_ARR_SPL_VAL(P_NEW_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_YYYYMMDD := SCM_ARR_SPL_VAL(P_NEW_YYYYMMDD, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL, V_DELIMITER, V_MST_LOOP_CNT);

            /* 날짜 칸은 8자리로 맞춘다 */
            IF TRIM(V_NEW_YYYYMMDD) IS NOT NULL THEN
                V_NEW_YYYYMMDD := SUBSTR(REPLACE(V_NEW_YYYYMMDD, '-', ''), 1, 8);
            END IF;

            IF TRIM(V_CHANGE_REASON_CODE) IS NULL THEN
                V_CHANGE_REASON_CODE := NULL;
            END IF;

            IF TRIM(V_CHANGE_REASON_DETAIL) IS NULL THEN
                V_CHANGE_REASON_DETAIL := NULL;
            END IF;

            IF TRIM(V_SHIPMENT_QTY) IS NULL THEN
                V_SHIPMENT_QTY := NULL;
            END IF;

            IF TRIM(V_SHIPMENT_DATE) IS NULL THEN
                V_SHIPMENT_DATE := '';
            END IF;

            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
               SET CHANGE_REASON_CODE = V_CHANGE_REASON_CODE
                 , CHANGE_REASON_DETAIL = V_CHANGE_REASON_DETAIL
             WHERE CHANGE_REQ_NO = P_CHANGE_REQ_NO;

            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
               SET NEW_YYYYMMDD = V_NEW_YYYYMMDD
                 , NEW_QTY = TO_NUMBER(V_NEW_QTY)
                 , VALID_YN = 'Y'
                 , ATTRIBUTE4 = V_CHANGE_REASON_CODE
                 , ATTRIBUTE5 = V_CHANGE_REASON_DETAIL
                 , LAST_UPDATED_BY = P_USER_ID
                 , LAST_UPDATE_DATE = SYSDATE
             WHERE CHANGE_REQ_NO = P_CHANGE_REQ_NO
               AND CONFIRM_ID = V_CONFIRM_ID
               AND (YYYYMMDD <> V_NEW_YYYYMMDD
                OR NVL(QTY, 0) <> NVL(TO_NUMBER(V_NEW_QTY), 0));

        END LOOP;        /* While End */

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_REQ_NO AS REQUEST_NO
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS REQUEST_NO
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING_MAIN;
    PROCEDURE P_SSP0060_SAVE_SHIPMENT_PLAN
    (
        P_ACTIVE_FLAG           IN  VARCHAR2
       ,P_DIVISION_ID           IN  VARCHAR2
       ,P_COMPANY_ID            IN  VARCHAR2
       ,P_FROM_SITE             IN  VARCHAR2
       ,P_ITEM_ID               IN  VARCHAR2
       ,P_TO_SITE               IN  VARCHAR2
       ,P_TRANSPORT_MODE        IN  VARCHAR2
       ,P_INCOTERMS             IN  VARCHAR2
       ,P_FCST_TYPE             IN  VARCHAR2
       ,P_PLAN_START_YYYYMMDD   IN  VARCHAR2
       ,P_YYYYMMDD              IN  VARCHAR2
       ,P_SHIPMENT_QTY          IN  VARCHAR2
       ,P_USER_ID               IN  VARCHAR2
       ,P_USER_DEPT_ID          IN  VARCHAR2
       ,DEBUG_MODE              IN  VARCHAR2
       ,O_RC1                   OUT SYS_REFCURSOR
       ,O_RC2                   OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : [SSP0060_SAVE_SHIPMENT_PLAN]
 * Description  : Shipment PLAN 수정
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2024/06/05   hsbang		   Initial Release
 * 2025/08/18   chkim.68       [E20250821-001308] -- to_company_id를 from_site에 따라 to_company_id가 다르게 적용되는 예외를 적용 (scm_site_company_exception)
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
							FN_GET_SSP_SITE_INFO -> [FN_GET_SSP_SITE_INFO_EXCEPTION]
							   SSP_SITE_INFO를 이용하여 scm_site_company를 획득하도록 공통화
 */
        V_MAX_REQ_NO                VARCHAR2(40);
        V_ACTIVE_FLAG               VARCHAR2(4000);
        V_DIVISION_ID               VARCHAR2(4000) := P_DIVISION_ID;
        V_CONFIRM_ID                VARCHAR2(4000);
        V_YYYYMMDD                  VARCHAR2(4000);
        V_SHIPMENT_QTY              NUMBER := 0;
        V_NEW_SHIPMENT_QTY          NUMBER;
        V_OLD_SHIPMENT_QTY          NUMBER := 0;
        V_FROM_SITE                 VARCHAR2(4000);
        V_TO_SITE                   VARCHAR2(4000);
        V_PROJECT_CODE              VARCHAR2(4000);
        V_ITEM_ID                   VARCHAR2(4000);
        V_BOD_ID                    VARCHAR2(4000);
        V_ETD_DATE                  VARCHAR2(4000);
        V_ETA_DATE                  VARCHAR2(4000);
        V_ROUTE_ID                  VARCHAR2(4000);
        V_TRANSPORT_MODE            VARCHAR2(4000);
        V_INCOTERMS                 VARCHAR2(4000);
        V_FCST_TYPE                 VARCHAR2(4000);
        V_D_CONTRY                  VARCHAR2(4000);
        V_D_PORT_CODE               VARCHAR2(4000);
        V_A_COUNTRY                 VARCHAR2(4000);
        V_A_PORT_CODE               VARCHAR2(4000);
        V_CUSTOMER_LT               VARCHAR2(4000) := '0';
        V_TO_COUNTRY                VARCHAR2(4000);
        V_TO_CITY                   VARCHAR2(4000);
        V_CREATE_DATE               DATE := SYSDATE;
        V_CHK                       NUMBER := 0;
        V_TITLE                     VARCHAR2(4000);
        V_ELECTRODE_YN              VARCHAR2(4000);
        V_ELECTRODE_TYPE            VARCHAR2(4000);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000);
        V_REMARKS                   VARCHAR2(4000);
        V_REMARKS2                  VARCHAR2(4000);
        V_REMARKS3                  VARCHAR2(4000);
        V_CHANGE_REASON_CODE        VARCHAR2(4000);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000);
        V_ORIGIN_TO_DIVISION_ID     VARCHAR2(4000);
        V_FROM_SITE_TYPE            VARCHAR2(4000);
        V_FROM_SITE_PLANT_ID        VARCHAR2(4000);
        V_FROM_SITE_VENDOR_ID       VARCHAR2(4000);
        V_FROM_SITE_COMPANY_ID      VARCHAR2(4000);
        V_FROM_SITE_SOLDTO_CODE     VARCHAR2(4000);
        V_FROM_SITE_SHIPTO_CODE     VARCHAR2(4000);
        V_TO_SITE_TYPE              VARCHAR2(4000);
        V_TO_SITE_PLANT_ID          VARCHAR2(4000);
        V_TO_SITE_VENDOR_ID         VARCHAR2(4000);
        V_TO_SITE_COMPANY_ID        VARCHAR2(4000);
        V_TO_SITE_SOLDTO_CODE       VARCHAR2(4000);
        V_TO_SITE_SHIPTO_CODE       VARCHAR2(4000);
        V_OPERATION_GROUP           VARCHAR2(4000);
        V_PACKAGE_TYPE_CODE         VARCHAR2(4000);
        V_PACKAGE_QTY               NUMBER := 0;
        V_DIVISION_ID_TEMP          VARCHAR2(4000);
        V_CONFIRM_ID_TEMP           VARCHAR2(4000);
        V_BOD_ID_TEMP               VARCHAR2(4000);
        V_FROM_SITE_TEMP            VARCHAR2(4000);
        V_TO_SITE_TEMP              VARCHAR2(4000);
        V_INCOTERMS_TEMP            VARCHAR2(4000);
        V_TRANSPORT_MODE_TEMP       VARCHAR2(4000);
        V_ROUTE_ID_TEMP             VARCHAR2(4000);
        V_D_CONTRY_TEMP             VARCHAR2(4000);
        V_D_PORT_CODE_TEMP          VARCHAR2(4000);
        V_A_COUNTRY_TEMP            VARCHAR2(4000);
        V_A_PORT_CODE_TEMP          VARCHAR2(4000);
        V_CUSTOMER_LT_TEMP          VARCHAR2(4000);
        V_TO_COUNTRY_TEMP           VARCHAR2(4000);
        V_TO_CITY_TEMP              VARCHAR2(4000);
        V_SHIPMENT_QTY_TEMP         NUMBER;
        V_LOT_SIZE                  NUMBER := 0;
        V_TMP_DIVISION_ID           VARCHAR2(100);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150) := 'PKG_SSP0060.P_SSP0060_SAVE_SHIPMENT_PLAN';
        V_LOG_TYPE                  VARCHAR2(30);                               /* START/END/ERROR/... */
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000);
        V_DESCRIPTION               VARCHAR2(500);
        D_EVENT_DATE                DATE;
        V_DELIMITER                 VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;
        V_ERR_MSG                   VARCHAR2(4000);
        V_ERR_CODE                  NUMBER;

        /* 수정 가능한 확정 건 (감량은 역순, 증량은 정순) */
        CURSOR CUR_M_DESC IS
            SELECT CONFIRM_ID
                 , QTY
                 , BOD_ID
                 , ROUTE_ID
                 , TO_CHAR(TO_DATE(ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                 , TO_CHAR(TO_DATE(ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                 , D_COUNTRY
                 , D_PORT_CODE
                 , A_COUNTRY
                 , A_PORT_CODE
                 , CUSTOMER_LT
                 , TO_COUNTRY
                 , TO_CITY
                 , ELECTRODE_YN
                 , ELECTRODE_TYPE
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , REMARKS
                 , REMARKS2
                 , REMARKS3
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE CHANGE_TYPE = 'C'
               AND BIZ_TYPE <> 'E'
               AND (SHIPMENT_STATUS IS NOT NULL AND SHIPMENT_STATUS = 'C' AND ERP_STATUS IS NULL OR ERP_STATUS <> 'C')
               AND QTY > 0
               AND DIVISION_ID = P_DIVISION_ID
               AND FROM_SITE_COMPANY_ID = P_COMPANY_ID
               /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
               AND YYYYMMDD = V_YYYYMMDD
               AND (TRIM(V_FROM_SITE) IS NULL
                OR FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND (TRIM(V_TO_SITE) IS NULL
                OR TO_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
               AND (TRIM(V_TRANSPORT_MODE) IS NULL
                OR TRANSPORT_MODE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TRANSPORT_MODE, ','))))
               AND (TRIM(V_INCOTERMS) IS NULL
                OR INCOTERMS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
               AND (TRIM(V_FCST_TYPE) IS NULL
                OR FCST_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FCST_TYPE, ','))))
             /* S/O 발행하지 않은 계획부터 감량한다. S/O 번호가 높은 것 먼저 감량, 모두 S/O 발행되었을 경우, CONFIRM ID 번호가 높은 것 먼저 감량 */
             ORDER BY (CASE WHEN ERP_SO_NO IS NULL THEN 0 ELSE 1 END)
                    , ERP_SO_NO DESC NULLS LAST
                    , CONFIRM_ID DESC;

        CURSOR CUR_M_ASC IS
            SELECT CONFIRM_ID
                 , QTY
                 , BOD_ID
                 , ROUTE_ID
                 , TO_CHAR(TO_DATE(ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                 , TO_CHAR(TO_DATE(ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                 , D_COUNTRY
                 , D_PORT_CODE
                 , A_COUNTRY
                 , A_PORT_CODE
                 , CUSTOMER_LT
                 , TO_COUNTRY
                 , TO_CITY
                 , ELECTRODE_YN
                 , ELECTRODE_TYPE
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , REMARKS
                 , REMARKS2
                 , REMARKS3
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE CHANGE_TYPE = 'C'
               AND BIZ_TYPE <> 'E'
               AND (SHIPMENT_STATUS IS NOT NULL AND SHIPMENT_STATUS = 'C' AND ERP_STATUS IS NULL OR ERP_STATUS <> 'C')
               AND QTY > 0
               AND DIVISION_ID = P_DIVISION_ID
               AND FROM_SITE_COMPANY_ID = P_COMPANY_ID
               AND YYYYMMDD = V_YYYYMMDD
               AND (TRIM(V_FROM_SITE) IS NULL
                OR FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND (TRIM(V_TO_SITE) IS NULL
                OR TO_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
               AND (TRIM(V_TRANSPORT_MODE) IS NULL
                OR TRANSPORT_MODE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TRANSPORT_MODE, ','))))
               AND (TRIM(V_INCOTERMS) IS NULL
                OR INCOTERMS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
               AND (TRIM(V_FCST_TYPE) IS NULL
                OR FCST_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FCST_TYPE, ','))))
             /* S/O 발행하지 않은 계획부터 감량한다. S/O 번호가 낮은 것 먼저 감량, 모두 S/O 발행되었을 경우, CONFIRM ID 번호가 낮은것 먼저 감량 */
             ORDER BY (CASE WHEN ERP_SO_NO IS NULL THEN 0 ELSE 1 END)
                    , ERP_SO_NO ASC
                    , CONFIRM_ID ASC;

        R_CUR   CUR_M_DESC%ROWTYPE;
    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 저장 중 오류가 나면 이 프로시저가 만든 것만 되돌린다 */
        /* 로그 프로시저가 커밋하므로 그 뒤에 잡는다 */
        SAVEPOINT SP_SSP0060_SAVE_PLAN;

        V_TITLE := 'Change on Shipment Plan Qty';

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            /* SET @v_division_id = dbo.SCM_ARR_SPL_VAL( @p_division_id, @v_delimiter, @mst_loop_cnt ); */
            V_FROM_SITE := SCM_ARR_SPL_VAL(P_FROM_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID := SCM_ARR_SPL_VAL(P_ITEM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_TO_SITE := SCM_ARR_SPL_VAL(P_TO_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_INCOTERMS := SCM_ARR_SPL_VAL(P_INCOTERMS, V_DELIMITER, V_MST_LOOP_CNT);
            V_FCST_TYPE := SCM_ARR_SPL_VAL(P_FCST_TYPE, V_DELIMITER, V_MST_LOOP_CNT);
            /* SET @v_plan_start_yyyymmdd = dbo.SCM_ARR_SPL_VAL( @p_plan_start_yyyymmdd, @v_delimiter, @mst_loop_cnt ); */
            V_YYYYMMDD := SCM_ARR_SPL_VAL(P_YYYYMMDD, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_SHIPMENT_QTY := TO_NUMBER(SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT));

            /* 날짜 칸은 8자리로 맞춘다 */
            IF TRIM(V_YYYYMMDD) IS NOT NULL THEN
                V_YYYYMMDD := SUBSTR(REPLACE(V_YYYYMMDD, '-', ''), 1, 8);
            END IF;

            /* 기존 shipment_qty */
            SELECT NVL(SUM(QTY), 0)
                 , MAX(CONFIRM_ID)
              INTO V_OLD_SHIPMENT_QTY
                 , V_CONFIRM_ID_TEMP
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE CHANGE_TYPE = 'C'
               AND BIZ_TYPE <> 'E'
               /* AND (SHIPMENT_STATUS IS NOT NULL AND T0.SHIPMENT_STATUS = 'C' AND T0.ERP_STATUS IS NULL OR T0.ERP_STATUS != 'C') */
               AND QTY > 0
               AND DIVISION_ID = P_DIVISION_ID
               AND FROM_SITE_COMPANY_ID = P_COMPANY_ID
               /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
               AND YYYYMMDD = V_YYYYMMDD
               AND (TRIM(V_FROM_SITE) IS NULL
                OR FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
               AND (TRIM(V_ITEM_ID) IS NULL
                OR ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
               AND (TRIM(V_TO_SITE) IS NULL
                OR TO_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
               AND (TRIM(V_TRANSPORT_MODE) IS NULL
                OR TRANSPORT_MODE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TRANSPORT_MODE, ','))))
               AND (TRIM(V_INCOTERMS) IS NULL
                OR INCOTERMS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
               AND (TRIM(V_FCST_TYPE) IS NULL
                OR FCST_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FCST_TYPE, ','))));

            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , TO_CHAR(ROUTE_ID)
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , TO_CHAR(LT_TOTAL)
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_INCOTERMS_TEMP
                     , V_TRANSPORT_MODE_TEMP
                     , V_ROUTE_ID_TEMP
                     , V_D_CONTRY_TEMP
                     , V_D_PORT_CODE_TEMP
                     , V_A_COUNTRY_TEMP
                     , V_A_PORT_CODE_TEMP
                     , V_CUSTOMER_LT_TEMP
                     , V_TO_COUNTRY_TEMP
                     , V_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT XA.DIVISION_ID
                                     , XA.BOD_ID
                                     , XA.FROM_SITE
                                     , XA.TO_SITE
                                     , XA.SSP_INCOTERMS
                                     , XA.TRANSPORT_MODE
                                     , XA.ROUTE_ID
                                     , XA.D_COUNTRY
                                     , XA.D_PORT_CODE
                                     , XA.A_COUNTRY
                                     , XA.A_PORT_CODE
                                     , XA.LT_TOTAL
                                     , XA.LT_TOTAL_ORIGIN
                                     , XA.TO_COUNTRY
                                     , XA.TO_CITY
                                     , XA.PRIORITY
                                     , XA.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V XA
                                     , (SELECT DISTINCT SA.DIVISION_ID
                                             , SA.ITEM_ID
                                             , SA.BOD_ID
                                          FROM SCP_MST_BOD_ITEM SA
                                         WHERE SA.DIVISION_ID = V_DIVISION_ID
                                           AND SA.ITEM_ID = V_ITEM_ID) XB
                                 WHERE XB.DIVISION_ID = XA.DIVISION_ID
                                   AND XB.BOD_ID = XA.BOD_ID
                                   AND XA.DIVISION_ID = V_DIVISION_ID
                                   AND XA.FROM_SITE = V_FROM_SITE
                                   AND XA.TO_SITE = V_TO_SITE
                                   AND XA.TRANSPORT_MODE = V_TRANSPORT_MODE
                                   AND XA.SSP_INCOTERMS = V_INCOTERMS
                                   AND XA.BOD_VALID_YN = 'Y'
                                   AND XA.FROM_YYYYMMDD <= V_YYYYMMDD
                                   AND XA.TO_YYYYMMDD >= V_YYYYMMDD) IA
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_DIVISION_ID_TEMP := NULL;
                    V_BOD_ID_TEMP := NULL;
                    V_FROM_SITE_TEMP := NULL;
                    V_TO_SITE_TEMP := NULL;
                    V_INCOTERMS_TEMP := NULL;
                    V_TRANSPORT_MODE_TEMP := NULL;
                    V_ROUTE_ID_TEMP := NULL;
                    V_D_CONTRY_TEMP := NULL;
                    V_D_PORT_CODE_TEMP := NULL;
                    V_A_COUNTRY_TEMP := NULL;
                    V_A_PORT_CODE_TEMP := NULL;
                    V_CUSTOMER_LT_TEMP := NULL;
                    V_TO_COUNTRY_TEMP := NULL;
                    V_TO_CITY_TEMP := NULL;
            END;

            IF (TRIM(V_DIVISION_ID_TEMP) IS NULL
             OR TRIM(V_BOD_ID_TEMP) IS NULL
             OR TRIM(V_FROM_SITE_TEMP) IS NULL
             OR TRIM(V_TO_SITE_TEMP) IS NULL
             OR TRIM(V_INCOTERMS_TEMP) IS NULL
             OR TRIM(V_TRANSPORT_MODE_TEMP) IS NULL
             OR TRIM(V_ROUTE_ID_TEMP) IS NULL
             OR TRIM(V_D_CONTRY_TEMP) IS NULL
             OR TRIM(V_D_PORT_CODE_TEMP) IS NULL
             OR TRIM(V_A_COUNTRY_TEMP) IS NULL
             OR TRIM(V_A_PORT_CODE_TEMP) IS NULL
             OR TRIM(V_CUSTOMER_LT_TEMP) IS NULL
             OR TRIM(V_TO_COUNTRY_TEMP) IS NULL
             OR TRIM(V_TO_CITY_TEMP) IS NULL) THEN

                V_LOG_TYPE := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                V_DESCRIPTION := '';
                D_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                OPEN O_RC1 FOR
                    SELECT 'X' AS RESULT_CODE
                         , NULL AS RESULT_CNT
                      FROM DUAL;

                OPEN O_RC2 FOR
                    SELECT NULL AS ERROR_MESSAGE
                      FROM DUAL
                     WHERE 1 = 2;

                RETURN;

            END IF;

            /*1) 감량 시
                 1. d/o 발행 수량 이상으로만 변경 가능하다
                 2. S/O 발행하지 않은 계획부터 감량한다. S/O 번호가 높은 것 먼저 감량
                 3. 모두 S/O 발행되었을 경우, CONFIRM ID 번호가 높은 것 먼저 감량
                 */
            IF (V_OLD_SHIPMENT_QTY > V_NEW_SHIPMENT_QTY) THEN

                V_SHIPMENT_QTY_TEMP := V_OLD_SHIPMENT_QTY - V_NEW_SHIPMENT_QTY;

                IF V_CHK = 0 THEN

                    V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO,              CHANGE_TYPE,                CHANGE_REQ_STATUS,          DIVISION_ID,
                        FROM_SITE,                  REQUEST_TITLE,              REQUEST_USER,               REQUEST_DEPT,
                        REQUEST_TIME,               APPROVAL_USER,              APPROVAL_DEPT,              APPROVAL_TIME,
                        CHANGE_REASON_CODE,         CHANGE_REASON_DETAIL,       REJECT_REASON,              VALID_YN,
                        CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                        ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO,               'C',                        'Q',                        V_DIVISION_ID,
                        V_FROM_SITE,                V_TITLE,                    P_USER_ID,                  P_USER_DEPT_ID,
                        V_CREATE_DATE,              P_USER_ID,                  P_USER_DEPT_ID,             V_CREATE_DATE,
                        V_CHANGE_REASON_CODE,       V_CHANGE_REASON_DETAIL,     NULL,                       'N',
                        P_USER_ID,                  V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE,
                        V_ELECTRODE_YN,             V_ELECTRODE_TYPE,           V_ORIGIN_FROM_DIVISION_ID,  V_ORIGION_TO_DIVISION_ID
                    );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                OPEN CUR_M_DESC;

                LOOP

                    FETCH CUR_M_DESC INTO R_CUR;
                    EXIT WHEN CUR_M_DESC%NOTFOUND;

                    IF (V_SHIPMENT_QTY_TEMP = 0) THEN
                        EXIT;
                    END IF;

                    V_CONFIRM_ID := R_CUR.CONFIRM_ID;
                    V_SHIPMENT_QTY := R_CUR.QTY;
                    V_CUSTOMER_LT := TO_CHAR(R_CUR.CUSTOMER_LT);
                    V_ETD_DATE := R_CUR.NEW_ETA;
                    V_REMARKS := R_CUR.REMARKS;
                    V_REMARKS2 := R_CUR.REMARKS2;
                    V_REMARKS3 := R_CUR.REMARKS3;

                    IF (V_SHIPMENT_QTY <= V_SHIPMENT_QTY_TEMP) THEN
                        V_SHIPMENT_QTY_TEMP := V_SHIPMENT_QTY_TEMP - V_SHIPMENT_QTY;
                        V_SHIPMENT_QTY := 0;                                    /* 새로입력 */
                    ELSE
                        V_SHIPMENT_QTY := V_SHIPMENT_QTY - V_SHIPMENT_QTY_TEMP;
                        V_SHIPMENT_QTY_TEMP := 0;
                    END IF;

                    V_ETD_DATE := REPLACE(SUBSTR(V_ETD_DATE, 1, 10), '-', '');

                    /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                    IF TRIM(V_YYYYMMDD) IS NOT NULL AND LENGTH(RTRIM(V_YYYYMMDD)) = 8 AND TRIM(V_CUSTOMER_LT) IS NOT NULL THEN
                        V_ETD_DATE := V_YYYYMMDD;
                    END IF;

                    /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                    V_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_BOD_ID_TEMP, V_YYYYMMDD);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                    (
                        CHANGE_REQ_NO,              CONFIRM_ID,                 NEW_YN,                     DIVISION_ID,
                        ITEM_ID,                    FROM_SITE,                  TO_SITE,                    YYYYMMDD,
                        QTY,                        BOD_ID,                     ROUTE_ID,                   BIZ_TYPE,
                        PROJECT_CODE,               FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE,
                        ETD_DATE,                   ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE,
                        D_COUNTRY,                  D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE,
                        CUSTOMER_LT,                TO_COUNTRY,                 TO_CITY,                    NEW_YYYYMMDD,
                        NEW_QTY,                    NEW_BOD_ID,                 NEW_ROUTE_ID,               NEW_ETD_DATE,
                        NEW_ETA_DATE,               NEW_INCOTERMS,              NEW_TRANSPORT_MODE,         NEW_D_COUNTRY,
                        NEW_D_PORT_CODE,            NEW_A_COUNTRY,              NEW_A_PORT_CODE,            NEW_CUSTOMER_LT,
                        NEW_TO_COUNTRY,             NEW_TO_CITY,                FROM_SITE_TYPE,             FROM_SITE_PLANT_ID,
                        FROM_SITE_VENDOR_ID,        FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID,
                        TO_SITE_TYPE,               TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE,
                        TO_SITE_SHIPTO_CODE,        TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO,
                        ERP_DO_NO,                  ERP_STATUS,                 VALID_YN,                   ATTRIBUTE1,
                        ATTRIBUTE2,
                        CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                        ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID,
                        REMARKS,                    REMARKS2,                   REMARKS3,                   REQUESTOR
                    )
                    SELECT V_MAX_REQ_NO,            CONFIRM_ID,                 'N',                        DIVISION_ID
                         , ITEM_ID,                 FROM_SITE,                  TO_SITE,                    YYYYMMDD
                         , QTY,                     BOD_ID,                     ROUTE_ID,                   BIZ_TYPE
                         , PROJECT_CODE,            FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE
                         , ETD_DATE,                ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE
                         , D_COUNTRY,               D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE
                         , CUSTOMER_LT,             TO_COUNTRY,                 TO_CITY,                    V_YYYYMMDD
                         , V_SHIPMENT_QTY,          V_BOD_ID_TEMP,              TO_NUMBER(V_ROUTE_ID_TEMP), V_ETD_DATE
                         , V_ETA_DATE,              V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP,      V_D_CONTRY_TEMP
                         , V_D_PORT_CODE_TEMP,      V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP,         TO_NUMBER(V_CUSTOMER_LT_TEMP)
                         , V_TO_COUNTRY_TEMP,       V_TO_CITY_TEMP,             FROM_SITE_TYPE,             FROM_SITE_PLANT_ID
                         , FROM_SITE_VENDOR_ID,     FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID
                         , TO_SITE_TYPE,            TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE
                         , TO_SITE_SHIPTO_CODE,     TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO
                         , ERP_DO_NO,               ERP_STATUS,                 'N',                        'N'
                         , 'A'
                         , P_USER_ID,               V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE
                         , ELECTRODE_YN,            ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID
                         , V_REMARKS,               V_REMARKS2,                 V_REMARKS3,                 P_USER_ID
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;

                END LOOP;

                CLOSE CUR_M_DESC;

            /* 2) 증량인 경우 : 수량 입력 시, SHIPMENT LOT SIZE 만큼 쪼개서 CONFIRM ID 발행 */
            ELSIF (V_OLD_SHIPMENT_QTY < V_NEW_SHIPMENT_QTY) THEN

                V_SHIPMENT_QTY_TEMP := V_NEW_SHIPMENT_QTY - V_OLD_SHIPMENT_QTY;     /* 증가수량 */

                IF V_CHK = 0 THEN

                    V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO,              CHANGE_TYPE,                CHANGE_REQ_STATUS,          DIVISION_ID,
                        FROM_SITE,                  REQUEST_TITLE,              REQUEST_USER,               REQUEST_DEPT,
                        REQUEST_TIME,               APPROVAL_USER,              APPROVAL_DEPT,              APPROVAL_TIME,
                        CHANGE_REASON_CODE,         CHANGE_REASON_DETAIL,       REJECT_REASON,              VALID_YN,
                        CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                        ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO,               'C',                        'Q',                        V_DIVISION_ID,
                        V_FROM_SITE,                V_TITLE,                    P_USER_ID,                  P_USER_DEPT_ID,
                        V_CREATE_DATE,              P_USER_ID,                  P_USER_DEPT_ID,             V_CREATE_DATE,
                        V_CHANGE_REASON_CODE,       V_CHANGE_REASON_DETAIL,     NULL,                       'N',
                        P_USER_ID,                  V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE,
                        V_ELECTRODE_YN,             V_ELECTRODE_TYPE,           V_ORIGIN_FROM_DIVISION_ID,  V_ORIGION_TO_DIVISION_ID
                    );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                V_ETD_DATE := REPLACE(SUBSTR(V_ETD_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF TRIM(V_YYYYMMDD) IS NOT NULL AND LENGTH(RTRIM(V_YYYYMMDD)) = 8 AND TRIM(V_CUSTOMER_LT) IS NOT NULL THEN
                    V_ETD_DATE := V_YYYYMMDD;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_BOD_ID_TEMP, V_YYYYMMDD);

                BEGIN
                    SELECT DIVISION_ID
                         , OPERATION_GROUP
                      INTO V_ORIGIN_FROM_DIVISION_ID
                         , V_OPERATION_GROUP
                      FROM SCM_MST_SITE
                     WHERE SCM_SITE_ID = V_FROM_SITE
                       AND DIVISION_ID = V_DIVISION_ID
                       AND VALID_YN = 'Y'
                       AND ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_ORIGIN_FROM_DIVISION_ID := NULL;
                        V_OPERATION_GROUP := NULL;
                END;

                BEGIN
                    SELECT PROJECT_CODE
                      INTO V_PROJECT_CODE
                      FROM SCM_MST_SITE_ITEM
                     WHERE DIVISION_ID = V_DIVISION_ID
                       AND SCM_SITE_ID = V_TO_SITE
                       AND ITEM_ID = V_ITEM_ID
                       AND ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_PROJECT_CODE := NULL;
                END;

                BEGIN
                    SELECT PACKAGE_TYPE_CODE
                         , CEIL(CASE WHEN PACKAGE_TYPE_CODE = 'BX' THEN CEIL(V_SHIPMENT_QTY_TEMP * CAST(NVL(CONVERT_TO_PC_ROLL_LENGTH, 1) AS NUMBER(20, 10))) * NVL(BOX_PER_CUT, 1)
                                     WHEN PACKAGE_TYPE_CODE = 'SC' THEN CEIL(V_SHIPMENT_QTY_TEMP * CAST(NVL(CONVERT_TO_PC_ROLL_LENGTH, 1) AS NUMBER(20, 10))) * NVL(STEELCRATE_PER_CUT, 1)
                                     WHEN PACKAGE_TYPE_CODE = 'SR' THEN CEIL(V_SHIPMENT_QTY_TEMP * CAST(NVL(CONVERT_TO_PC_ROLL_LENGTH, 1) AS NUMBER(20, 10))) * NVL(STEELRACK_PER_CUT, 1)
                                     ELSE NULL
                                END)
                      INTO V_PACKAGE_TYPE_CODE
                         , V_PACKAGE_QTY
                      FROM SSP_MST_SITE_ITEM_EE_V
                     WHERE DIVISION_ID = V_DIVISION_ID
                       AND SCM_SITE_ID = V_FROM_SITE
                       AND ITEM_ID = V_ITEM_ID
                       AND ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_PACKAGE_TYPE_CODE := NULL;
                        V_PACKAGE_QTY := NULL;
                END;

                IF V_OPERATION_GROUP <> 'E' THEN
                    V_ELECTRODE_YN := 'N';
                    V_ORIGIN_TO_DIVISION_ID := V_ORIGIN_FROM_DIVISION_ID;
                ELSE
                    V_ELECTRODE_YN := 'Y';

                    BEGIN
                        SELECT DIVISION_ID
                          INTO V_ORIGIN_TO_DIVISION_ID
                          FROM SCM_MST_SITE
                         WHERE SCM_SITE_ID = V_TO_SITE
                           AND VALID_YN = 'Y'
                           AND ROWNUM = 1;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            V_ORIGIN_TO_DIVISION_ID := NULL;
                    END;

                END IF;

                /* [E20250821-001308] begin 대체코드 */
                V_TMP_DIVISION_ID := V_ORIGIN_FROM_DIVISION_ID;
                V_FROM_SITE_TYPE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SITE_TYPE');
                V_FROM_SITE_PLANT_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'PLANT_ID');
                V_FROM_SITE_VENDOR_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'VENDOR_ID');
                V_FROM_SITE_COMPANY_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'COMPANY_ID');
                V_FROM_SITE_SOLDTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SOLDTO_CODE');
                V_FROM_SITE_SHIPTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SHIPTO_CODE');

                V_TMP_DIVISION_ID := CASE WHEN V_DIVISION_ID = 'EE' THEN V_ORIGIN_FROM_DIVISION_ID ELSE V_ORIGIN_TO_DIVISION_ID END;
                V_TO_SITE_TYPE := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'SITE_TYPE');
                V_TO_SITE_PLANT_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'PLANT_ID');
                V_TO_SITE_VENDOR_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'VENDOR_ID');
                V_TO_SITE_COMPANY_ID := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'COMPANY_ID');
                V_TO_SITE_SOLDTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SOLDTO_CODE');
                V_TO_SITE_SHIPTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SHIPTO_CODE');
                /* [E20250821-001308] end 대체코드 */

                BEGIN
                    SELECT LOT_SIZE
                      INTO V_LOT_SIZE
                      FROM SCP_MST_SHIPMENT_LOT_SIZE
                     WHERE DIVISION_ID = V_DIVISION_ID
                       AND FROM_SITE = V_FROM_SITE
                       AND TO_SITE = V_TO_SITE
                       AND ITEM_ID = V_ITEM_ID
                       AND TRANSPORT_MODE = V_TRANSPORT_MODE_TEMP
                       AND VALID_YN = 'Y'
                       AND SPLIT_YN = 'Y'                                       /* 분할대상인것만 분할(2018.12.18) */
                       AND ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_LOT_SIZE := NULL;
                END;

                IF (NVL(V_LOT_SIZE, 0) > 0) THEN                                /* 분할 대상인 경우 */

                    /* 1) 수량입력 가능한 Confirm ID 순으로 Lot Size 만큼 수량 보정 */
                    OPEN CUR_M_ASC;

                    LOOP

                        FETCH CUR_M_ASC INTO R_CUR;
                        EXIT WHEN CUR_M_ASC%NOTFOUND;

                        IF (V_SHIPMENT_QTY_TEMP = 0) THEN
                            EXIT;
                        END IF;

                        V_CONFIRM_ID := R_CUR.CONFIRM_ID;
                        V_SHIPMENT_QTY := R_CUR.QTY;
                        V_CUSTOMER_LT := TO_CHAR(R_CUR.CUSTOMER_LT);
                        V_ETD_DATE := R_CUR.NEW_ETA;
                        V_REMARKS := R_CUR.REMARKS;
                        V_REMARKS2 := R_CUR.REMARKS2;
                        V_REMARKS3 := R_CUR.REMARKS3;

                        IF (V_SHIPMENT_QTY_TEMP >= V_LOT_SIZE - V_SHIPMENT_QTY) THEN    /* @v_shipment_qty_temp(10) , (Lot Size:1050 - Qty : 950) : 100 */
                            V_SHIPMENT_QTY_TEMP := V_SHIPMENT_QTY_TEMP - (V_LOT_SIZE - V_SHIPMENT_QTY);
                            V_SHIPMENT_QTY := V_LOT_SIZE;
                        ELSE
                            V_SHIPMENT_QTY := V_SHIPMENT_QTY + V_SHIPMENT_QTY_TEMP;
                            V_SHIPMENT_QTY_TEMP := 0;
                        END IF;

                        V_ETD_DATE := REPLACE(SUBSTR(V_ETD_DATE, 1, 10), '-', '');

                        /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                        IF TRIM(V_YYYYMMDD) IS NOT NULL AND LENGTH(RTRIM(V_YYYYMMDD)) = 8 AND TRIM(V_CUSTOMER_LT) IS NOT NULL THEN
                            V_ETD_DATE := V_YYYYMMDD;
                        END IF;

                        /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                        V_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_BOD_ID_TEMP, V_YYYYMMDD);

                        INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                        (
                            CHANGE_REQ_NO,              CONFIRM_ID,                 NEW_YN,                     DIVISION_ID,
                            ITEM_ID,                    FROM_SITE,                  TO_SITE,                    YYYYMMDD,
                            QTY,                        BOD_ID,                     ROUTE_ID,                   BIZ_TYPE,
                            PROJECT_CODE,               FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE,
                            ETD_DATE,                   ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE,
                            D_COUNTRY,                  D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE,
                            CUSTOMER_LT,                TO_COUNTRY,                 TO_CITY,                    NEW_YYYYMMDD,
                            NEW_QTY,                    NEW_BOD_ID,                 NEW_ROUTE_ID,               NEW_ETD_DATE,
                            NEW_ETA_DATE,               NEW_INCOTERMS,              NEW_TRANSPORT_MODE,         NEW_D_COUNTRY,
                            NEW_D_PORT_CODE,            NEW_A_COUNTRY,              NEW_A_PORT_CODE,            NEW_CUSTOMER_LT,
                            NEW_TO_COUNTRY,             NEW_TO_CITY,                FROM_SITE_TYPE,             FROM_SITE_PLANT_ID,
                            FROM_SITE_VENDOR_ID,        FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID,
                            TO_SITE_TYPE,               TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE,
                            TO_SITE_SHIPTO_CODE,        TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO,
                            ERP_DO_NO,                  ERP_STATUS,                 VALID_YN,                   ATTRIBUTE1,
                            ATTRIBUTE2,
                            CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                            ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID,
                            REMARKS,                    REMARKS2,                   REMARKS3,                   REQUESTOR
                        )
                        SELECT V_MAX_REQ_NO,            CONFIRM_ID,                 'N',                        DIVISION_ID
                             , ITEM_ID,                 FROM_SITE,                  TO_SITE,                    YYYYMMDD
                             , QTY,                     BOD_ID,                     ROUTE_ID,                   BIZ_TYPE
                             , PROJECT_CODE,            FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE
                             , ETD_DATE,                ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE
                             , D_COUNTRY,               D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE
                             , CUSTOMER_LT,             TO_COUNTRY,                 TO_CITY,                    V_YYYYMMDD
                             , V_SHIPMENT_QTY,          V_BOD_ID_TEMP,              TO_NUMBER(V_ROUTE_ID_TEMP), V_ETD_DATE
                             , V_ETA_DATE,              V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP,      V_D_CONTRY_TEMP
                             , V_D_PORT_CODE_TEMP,      V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP,         TO_NUMBER(V_CUSTOMER_LT_TEMP)
                             , V_TO_COUNTRY_TEMP,       V_TO_CITY_TEMP,             FROM_SITE_TYPE,             FROM_SITE_PLANT_ID
                             , FROM_SITE_VENDOR_ID,     FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID
                             , TO_SITE_TYPE,            TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE
                             , TO_SITE_SHIPTO_CODE,     TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO
                             , ERP_DO_NO,               ERP_STATUS,                 'N',                        'N'
                             , 'A'
                             , P_USER_ID,               V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE
                             , ELECTRODE_YN,            ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID
                             , V_REMARKS,               V_REMARKS2,                 V_REMARKS3,                 P_USER_ID
                          FROM SSP_ANL_SHIP_CONFIRM
                         WHERE CONFIRM_ID = V_CONFIRM_ID;

                    END LOOP;

                    CLOSE CUR_M_ASC;

                    /* 2) 기존 Confrim ID에 모두 입력후 입력할 수량이 남은 경우 LOT SIZE 만큼 분활하여 신규 생성 */
                    IF (V_SHIPMENT_QTY_TEMP > 0) THEN

                        INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                        (
                            CHANGE_REQ_NO,              CONFIRM_ID,                 NEW_YN,                     DIVISION_ID,
                            ITEM_ID,                    FROM_SITE,                  TO_SITE,                    YYYYMMDD,
                            QTY,                        BOD_ID,                     ROUTE_ID,                   BIZ_TYPE,
                            PROJECT_CODE,               FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE,
                            ETD_DATE,                   ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE,
                            D_COUNTRY,                  D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE,
                            CUSTOMER_LT,                TO_COUNTRY,                 TO_CITY,                    NEW_YYYYMMDD,
                            NEW_QTY,                    NEW_BOD_ID,                 NEW_ROUTE_ID,               NEW_ETD_DATE,
                            NEW_ETA_DATE,               NEW_INCOTERMS,              NEW_TRANSPORT_MODE,         NEW_D_COUNTRY,
                            NEW_D_PORT_CODE,            NEW_A_COUNTRY,              NEW_A_PORT_CODE,            NEW_CUSTOMER_LT,
                            NEW_TO_COUNTRY,             NEW_TO_CITY,                FROM_SITE_TYPE,             FROM_SITE_PLANT_ID,
                            FROM_SITE_VENDOR_ID,        FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID,
                            TO_SITE_TYPE,               TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE,
                            TO_SITE_SHIPTO_CODE,        TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO,
                            ERP_DO_NO,                  ERP_STATUS,                 VALID_YN,                   ATTRIBUTE1,
                            ATTRIBUTE2,
                            CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                            ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID,
                            REMARKS,                    REMARKS2,                   REMARKS3,                   REQUESTOR
                        )
                        SELECT V_MAX_REQ_NO
                             , 'C' || TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL), -6)
                             , 'N',                     V_DIVISION_ID
                             , V_ITEM_ID,               V_FROM_SITE,                V_TO_SITE,                  V_YYYYMMDD
                             , 0,                       V_BOD_ID_TEMP,              TO_NUMBER(V_ROUTE_ID_TEMP), V_OPERATION_GROUP
                             , V_PROJECT_CODE,          V_FCST_TYPE,                V_YYYYMMDD,                 V_ETA_DATE
                             , V_YYYYMMDD,              V_ETA_DATE,                 V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP
                             , V_D_CONTRY_TEMP,         V_D_PORT_CODE_TEMP,         V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP
                             , TO_NUMBER(V_CUSTOMER_LT_TEMP), V_TO_COUNTRY_TEMP,    V_TO_CITY_TEMP,             V_YYYYMMDD
                             , CASE WHEN V_SHIPMENT_QTY_TEMP <= NVL(A.LOT_SIZE, V_SHIPMENT_QTY_TEMP) THEN V_SHIPMENT_QTY_TEMP
                                    ELSE CASE WHEN V_SHIPMENT_QTY_TEMP / (NVL(A.LOT_SIZE, V_SHIPMENT_QTY_TEMP) * B.SEQ) >= 1 THEN NVL(A.LOT_SIZE, V_SHIPMENT_QTY_TEMP)
                                              ELSE MOD(V_SHIPMENT_QTY_TEMP, (NVL(A.LOT_SIZE, V_SHIPMENT_QTY_TEMP) * (B.SEQ - 1)))
                                         END
                               END
                             , V_BOD_ID_TEMP,           TO_NUMBER(V_ROUTE_ID_TEMP), V_ETD_DATE
                             , V_ETA_DATE,              V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP,      V_D_CONTRY_TEMP
                             , V_D_PORT_CODE_TEMP,      V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP,         TO_NUMBER(V_CUSTOMER_LT_TEMP)
                             , V_TO_COUNTRY_TEMP,       V_TO_CITY_TEMP,             V_FROM_SITE_TYPE,           V_FROM_SITE_PLANT_ID
                             , V_FROM_SITE_VENDOR_ID,   V_FROM_SITE_SOLDTO_CODE,    V_FROM_SITE_SHIPTO_CODE,    V_FROM_SITE_COMPANY_ID
                             , V_TO_SITE_TYPE,          V_TO_SITE_PLANT_ID,         V_TO_SITE_VENDOR_ID,        V_TO_SITE_SOLDTO_CODE
                             , V_TO_SITE_SHIPTO_CODE,   V_TO_SITE_COMPANY_ID,       NULL,                       NULL
                             , V_PACKAGE_TYPE_CODE,     NULL,                       'N',                        'N'
                             , 'A'
                             , P_USER_ID,               V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE
                             , V_ELECTRODE_YN,          V_ELECTRODE_TYPE,           V_ORIGIN_FROM_DIVISION_ID,  V_ORIGIN_TO_DIVISION_ID
                             , V_REMARKS,               V_REMARKS2,                 V_REMARKS3,                 P_USER_ID
                          FROM SCP_MST_SHIPMENT_LOT_SIZE A
                             , SSP_MST_PARTIAL_SEQ B                            /* LOT SIZE별 행 생성을 위한 기초테이블 */
                         WHERE A.DIVISION_ID(+) = V_DIVISION_ID
                           AND A.FROM_SITE(+) = V_FROM_SITE
                           AND A.TO_SITE(+) = V_TO_SITE
                           AND A.ITEM_ID(+) = V_ITEM_ID
                           AND A.TRANSPORT_MODE(+) = V_TRANSPORT_MODE_TEMP
                           AND A.VALID_YN(+) = 'Y'
                           AND A.SPLIT_YN(+) = 'Y'                              /* 분할대상인것만 분할(2018.12.18) */
                           AND B.SEQ <= CEIL(V_SHIPMENT_QTY_TEMP / NVL(A.LOT_SIZE, V_SHIPMENT_QTY_TEMP));

                    END IF;

                ELSE    /* 분할 대상이 아닌 경우 */

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                    (
                        CHANGE_REQ_NO,              CONFIRM_ID,                 NEW_YN,                     DIVISION_ID,
                        ITEM_ID,                    FROM_SITE,                  TO_SITE,                    YYYYMMDD,
                        QTY,                        BOD_ID,                     ROUTE_ID,                   BIZ_TYPE,
                        PROJECT_CODE,               FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE,
                        ETD_DATE,                   ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE,
                        D_COUNTRY,                  D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE,
                        CUSTOMER_LT,                TO_COUNTRY,                 TO_CITY,                    NEW_YYYYMMDD,
                        NEW_QTY,                    NEW_BOD_ID,                 NEW_ROUTE_ID,               NEW_ETD_DATE,
                        NEW_ETA_DATE,               NEW_INCOTERMS,              NEW_TRANSPORT_MODE,         NEW_D_COUNTRY,
                        NEW_D_PORT_CODE,            NEW_A_COUNTRY,              NEW_A_PORT_CODE,            NEW_CUSTOMER_LT,
                        NEW_TO_COUNTRY,             NEW_TO_CITY,                FROM_SITE_TYPE,             FROM_SITE_PLANT_ID,
                        FROM_SITE_VENDOR_ID,        FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID,
                        TO_SITE_TYPE,               TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE,
                        TO_SITE_SHIPTO_CODE,        TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO,
                        ERP_DO_NO,                  ERP_STATUS,                 VALID_YN,                   ATTRIBUTE1,
                        ATTRIBUTE2,
                        CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                        ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID,
                        REMARKS,                    REMARKS2,                   REMARKS3,                   REQUESTOR
                    )
                    SELECT V_MAX_REQ_NO
                         , 'C' || TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL), -6)
                         , 'N',                     V_DIVISION_ID
                         , V_ITEM_ID,               V_FROM_SITE,                V_TO_SITE,                  V_YYYYMMDD
                         , 0,                       V_BOD_ID_TEMP,              TO_NUMBER(V_ROUTE_ID_TEMP), V_OPERATION_GROUP
                         , V_PROJECT_CODE,          V_FCST_TYPE,                V_YYYYMMDD,                 V_ETA_DATE
                         , V_YYYYMMDD,              V_ETA_DATE,                 V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP
                         , V_D_CONTRY_TEMP,         V_D_PORT_CODE_TEMP,         V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP
                         , TO_NUMBER(V_CUSTOMER_LT_TEMP), V_TO_COUNTRY_TEMP,    V_TO_CITY_TEMP,             V_YYYYMMDD
                         , V_SHIPMENT_QTY_TEMP
                         , V_BOD_ID_TEMP,           TO_NUMBER(V_ROUTE_ID_TEMP), V_ETD_DATE
                         , V_ETA_DATE,              V_INCOTERMS_TEMP,           V_TRANSPORT_MODE_TEMP,      V_D_CONTRY_TEMP
                         , V_D_PORT_CODE_TEMP,      V_A_COUNTRY_TEMP,           V_A_PORT_CODE_TEMP,         TO_NUMBER(V_CUSTOMER_LT_TEMP)
                         , V_TO_COUNTRY_TEMP,       V_TO_CITY_TEMP,             V_FROM_SITE_TYPE,           V_FROM_SITE_PLANT_ID
                         , V_FROM_SITE_VENDOR_ID,   V_FROM_SITE_SOLDTO_CODE,    V_FROM_SITE_SHIPTO_CODE,    V_FROM_SITE_COMPANY_ID
                         , V_TO_SITE_TYPE,          V_TO_SITE_PLANT_ID,         V_TO_SITE_VENDOR_ID,        V_TO_SITE_SOLDTO_CODE
                         , V_TO_SITE_SHIPTO_CODE,   V_TO_SITE_COMPANY_ID,       NULL,                       NULL
                         , V_PACKAGE_TYPE_CODE,     NULL,                       'N',                        'N'
                         , 'A'
                         , P_USER_ID,               V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE
                         , V_ELECTRODE_YN,          V_ELECTRODE_TYPE,           V_ORIGIN_FROM_DIVISION_ID,  V_ORIGIN_TO_DIVISION_ID
                         , V_REMARKS,               V_REMARKS2,                 V_REMARKS3,                 P_USER_ID
                      FROM DUAL;

                END IF;

            END IF;

            /* 감량또는 증량 제외한 Confirm ID 외 수정가능한 Confirm 데이터를 SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE 테이블에 입력 */
            IF (V_OLD_SHIPMENT_QTY <> V_NEW_SHIPMENT_QTY) THEN

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                (
                    CHANGE_REQ_NO,              CONFIRM_ID,                 NEW_YN,                     DIVISION_ID,
                    ITEM_ID,                    FROM_SITE,                  TO_SITE,                    YYYYMMDD,
                    QTY,                        BOD_ID,                     ROUTE_ID,                   BIZ_TYPE,
                    PROJECT_CODE,               FCST_TYPE,                  FCST_ETD_DATE,              FCST_ETA_DATE,
                    ETD_DATE,                   ETA_DATE,                   INCOTERMS,                  TRANSPORT_MODE,
                    D_COUNTRY,                  D_PORT_CODE,                A_COUNTRY,                  A_PORT_CODE,
                    CUSTOMER_LT,                TO_COUNTRY,                 TO_CITY,                    NEW_YYYYMMDD,
                    NEW_QTY,                    NEW_BOD_ID,                 NEW_ROUTE_ID,               NEW_ETD_DATE,
                    NEW_ETA_DATE,               NEW_INCOTERMS,              NEW_TRANSPORT_MODE,         NEW_D_COUNTRY,
                    NEW_D_PORT_CODE,            NEW_A_COUNTRY,              NEW_A_PORT_CODE,            NEW_CUSTOMER_LT,
                    NEW_TO_COUNTRY,             NEW_TO_CITY,                FROM_SITE_TYPE,             FROM_SITE_PLANT_ID,
                    FROM_SITE_VENDOR_ID,        FROM_SITE_SOLDTO_CODE,      FROM_SITE_SHIPTO_CODE,      FROM_SITE_COMPANY_ID,
                    TO_SITE_TYPE,               TO_SITE_PLANT_ID,           TO_SITE_VENDOR_ID,          TO_SITE_SOLDTO_CODE,
                    TO_SITE_SHIPTO_CODE,        TO_SITE_COMPANY_ID,         ERP_SO_NO,                  ERP_SO_ITEM_NO,
                    ERP_DO_NO,                  ERP_STATUS,                 VALID_YN,                   ATTRIBUTE1,
                    ATTRIBUTE2,
                    CREATED_BY,                 CREATION_DATE,              LAST_UPDATED_BY,            LAST_UPDATE_DATE,
                    ELECTRODE_YN,               ELECTRODE_TYPE,             ORIGIN_FROM_DIVISION_ID,    ORIGIN_TO_DIVISION_ID,
                    REMARKS,                    REMARKS2,                   REMARKS3,                   REQUESTOR
                )
                SELECT V_MAX_REQ_NO,            A.CONFIRM_ID
                     , 'N',                     A.DIVISION_ID
                     , A.ITEM_ID,               A.FROM_SITE,                A.TO_SITE,                  A.YYYYMMDD
                     , A.QTY,                   A.BOD_ID,                   A.ROUTE_ID,                 A.BIZ_TYPE
                     , A.PROJECT_CODE,          A.FCST_TYPE,                A.FCST_ETD_DATE,            A.FCST_ETA_DATE
                     , A.ETD_DATE,              A.ETA_DATE,                 A.INCOTERMS,                A.TRANSPORT_MODE
                     , A.D_COUNTRY,             A.D_PORT_CODE,              A.A_COUNTRY,                A.A_PORT_CODE
                     , A.CUSTOMER_LT,           A.TO_COUNTRY,               A.TO_CITY,                  A.YYYYMMDD
                     , A.QTY,                   A.BOD_ID,                   A.ROUTE_ID,                 A.ETD_DATE
                     , A.ETD_DATE,              A.INCOTERMS,                A.TRANSPORT_MODE,           A.D_COUNTRY
                     , A.D_PORT_CODE,           A.A_COUNTRY,                A.A_PORT_CODE,              A.CUSTOMER_LT
                     , A.TO_COUNTRY,            A.TO_CITY,                  A.FROM_SITE_TYPE,           A.FROM_SITE_PLANT_ID
                     , A.FROM_SITE_VENDOR_ID,   A.FROM_SITE_SOLDTO_CODE,    A.FROM_SITE_SHIPTO_CODE,    A.FROM_SITE_COMPANY_ID
                     , A.TO_SITE_TYPE,          A.TO_SITE_PLANT_ID,         A.TO_SITE_VENDOR_ID,        A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE,   A.TO_SITE_COMPANY_ID,       A.ERP_SO_NO,                A.ERP_SO_ITEM_NO
                     , A.ERP_DO_NO,             A.ERP_STATUS,               'N',                        'N'
                     , 'A'
                     , P_USER_ID,               V_CREATE_DATE,              P_USER_ID,                  V_CREATE_DATE
                     , A.ELECTRODE_YN,          A.ELECTRODE_TYPE,           A.ORIGIN_FROM_DIVISION_ID,  A.ORIGIN_TO_DIVISION_ID
                     , V_REMARKS,               V_REMARKS2,                 V_REMARKS3,                 P_USER_ID
                  FROM SSP_ANL_SHIP_CONFIRM A
                 WHERE A.CHANGE_TYPE = 'C'
                   AND A.BIZ_TYPE <> 'E'
                   AND (A.SHIPMENT_STATUS IS NOT NULL AND A.SHIPMENT_STATUS = 'C' AND A.ERP_STATUS IS NULL OR A.ERP_STATUS <> 'C')
                   AND A.QTY > 0
                   AND A.DIVISION_ID = P_DIVISION_ID
                   AND A.FROM_SITE_COMPANY_ID = P_COMPANY_ID
                   /* AND T0.PLAN_START_YYYYMMDD = @p_plan_start_yyyymmdd */
                   AND A.YYYYMMDD = V_YYYYMMDD
                   AND (TRIM(V_FROM_SITE) IS NULL
                    OR A.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
                   AND (TRIM(V_ITEM_ID) IS NULL
                    OR A.ITEM_ID IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
                   AND (TRIM(V_TO_SITE) IS NULL
                    OR A.TO_SITE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
                   AND (TRIM(V_TRANSPORT_MODE) IS NULL
                    OR A.TRANSPORT_MODE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_TRANSPORT_MODE, ','))))
                   AND (TRIM(V_INCOTERMS) IS NULL
                    OR A.INCOTERMS IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_INCOTERMS, ','))))
                   AND (TRIM(V_FCST_TYPE) IS NULL
                    OR A.FCST_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(STRING_SPLIT(V_FCST_TYPE, ','))))
                   AND NOT EXISTS (SELECT 1
                                     FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE SA
                                    WHERE SA.CHANGE_REQ_NO = V_MAX_REQ_NO
                                      AND SA.CONFIRM_ID = A.CONFIRM_ID);

            END IF;

        END LOOP;
        /* EXEC PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH 'C', @v_max_req_no; */

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_LOOP_CNT AS RESULT_CNT
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            IF CUR_M_DESC%ISOPEN THEN
                CLOSE CUR_M_DESC;
            END IF;

            IF CUR_M_ASC%ISOPEN THEN
                CLOSE CUR_M_ASC;
            END IF;

            /* 되돌리기는 결과 커서를 열기 전에 한다 */
            ROLLBACK TO SP_SSP0060_SAVE_PLAN;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS RESULT_CNT
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0060_SAVE_SHIPMENT_PLAN;
    /* 원문의 같은 문장이 네 군데에 되풀이되어 있어 하나로 모은다 — 조건·식은 원문 그대로 */
    PROCEDURE P_SSP0060_GET_PACKAGE_INFO
    (
        P_DIVISION_ID       IN  VARCHAR2
       ,P_FROM_SITE         IN  VARCHAR2
       ,P_ITEM_ID           IN  VARCHAR2
       ,P_OPERATION_GROUP   IN  VARCHAR2
       ,P_SHIPMENT_QTY      IN  NUMBER
       ,P_PACKAGE_TYPE_CODE OUT VARCHAR2
       ,P_PACKAGE_QTY       OUT NUMBER
    )
    IS
    BEGIN

        IF P_OPERATION_GROUP = 'E' THEN

            BEGIN
                SELECT PACKAGE_TYPE_CODE
                     , CEIL(CASE WHEN PACKAGE_TYPE_CODE = 'BX' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(BOX_PER_CUT, 1)
                                 WHEN PACKAGE_TYPE_CODE = 'SC' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(STEELCRATE_PER_CUT, 1)
                                 WHEN PACKAGE_TYPE_CODE = 'SR' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(STEELRACK_PER_CUT, 1)
                                 ELSE NULL
                            END)
                  INTO P_PACKAGE_TYPE_CODE
                     , P_PACKAGE_QTY
                  FROM SSP_MST_SITE_ITEM_EE_V
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND SCM_SITE_ID = P_FROM_SITE
                   AND ITEM_ID = P_ITEM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
                WHEN TOO_MANY_ROWS THEN
                    NULL;
            END;

        ELSE

            BEGIN
                SELECT PACKAGE_TYPE_CODE
                     , CEIL(CASE WHEN PACKAGE_TYPE_CODE = 'BX' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(BOX_PER_CUT, 1)
                                 WHEN PACKAGE_TYPE_CODE = 'SC' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(STEELCRATE_PER_CUT, 1)
                                 WHEN PACKAGE_TYPE_CODE = 'SR' THEN CEIL(P_SHIPMENT_QTY * NVL(CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(STEELRACK_PER_CUT, 1)
                                 ELSE NULL
                            END)
                  INTO P_PACKAGE_TYPE_CODE
                     , P_PACKAGE_QTY
                  FROM SSP_MST_SITE_ITEM_EE_V
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND ASSY_DIVISION_ID = P_FROM_SITE                           /* 원문 그대로 : FROM_SITE 를 ASSY_DIVISION_ID 와 맞댄다 */
                   AND ASSY_SCM_SITE_ID = P_ITEM_ID;                            /* 원문 그대로 : ITEM_ID 를 ASSY_SCM_SITE_ID 와 맞댄다 */
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
                WHEN TOO_MANY_ROWS THEN
                    NULL;
            END;

        END IF;

    END P_SSP0060_GET_PACKAGE_INFO;

    /* 원문의 같은 INSERT 가 두 군데에 되풀이되어 있어 하나로 모은다 — 칸과 값은 원문 그대로 */
