    (
        P_CONFIRM_ID        IN  VARCHAR2
       ,P_USER_ID           IN  VARCHAR2
       ,P_CREATE_DATE       IN  DATE
    )
    IS
    BEGIN

        INSERT INTO SSP_ANL_SHIP_CONFIRM_H
        (
            HISTORY_SEQ
          , CONFIRM_ID
          , CHANGE_TYPE
          , SHIPMENT_STATUS
          , DIVISION_ID
          , PLAN_START_YYYYMMDD
          , PLAN_TYPE
          , SEQ
          , ITEM_ID
          , FROM_SITE
          , TO_SITE
          , YYYYMMDD
          , PLANNED_QTY
          , QTY
          , BOD_ID
          , ROUTE_ID
          , BIZ_TYPE
          , PROJECT_CODE
          , FCST_TYPE
          , FCST_ETD_DATE
          , FCST_ETA_DATE
          , ETD_DATE
          , ETA_DATE
          , INCOTERMS
          , TRANSPORT_MODE
          , D_COUNTRY
          , D_PORT_CODE
          , A_COUNTRY
          , A_PORT_CODE
          , CUSTOMER_LT
          , TO_COUNTRY
          , TO_CITY
          , FROM_SITE_TYPE
          , FROM_SITE_PLANT_ID
          , FROM_SITE_VENDOR_ID
          , FROM_SITE_SOLDTO_CODE
          , FROM_SITE_SHIPTO_CODE
          , FROM_SITE_COMPANY_ID
          , TO_SITE_TYPE
          , TO_SITE_PLANT_ID
          , TO_SITE_VENDOR_ID
          , TO_SITE_SOLDTO_CODE
          , TO_SITE_SHIPTO_CODE
          , TO_SITE_COMPANY_ID
          , CHANGE_REQ_NO
          , ERP_SO_NO
          , ERP_SO_ITEM_NO
          , ERP_DO_NO
          , ERP_STATUS
          , CREATED_BY
          , CREATION_DATE
          , LAST_UPDATED_BY
          , LAST_UPDATE_DATE
          , HISTORY_CREATION_DATE
          , ELECTRODE_YN
          , ELECTRODE_TYPE
          , ORIGIN_FROM_DIVISION_ID
          , ORIGIN_TO_DIVISION_ID
          , BEFORE_QTY
          , REMARKS
          , CHECK_NEED_YN
        )
        SELECT SEQ1_SSP_ANL_SHIP_CONFIRM_H.NEXTVAL                              /* HISTORY_SEQ */
             , CONFIRM_ID
             , CHANGE_TYPE
             , SHIPMENT_STATUS
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , YYYYMMDD
             , PLANNED_QTY
             , QTY
             , BOD_ID
             , ROUTE_ID
             , BIZ_TYPE
             , PROJECT_CODE
             , FCST_TYPE
             , FCST_ETD_DATE
             , FCST_ETA_DATE
             , ETD_DATE
             , ETA_DATE
             , INCOTERMS
             , TRANSPORT_MODE
             , D_COUNTRY
             , D_PORT_CODE
             , A_COUNTRY
             , A_PORT_CODE
             , CUSTOMER_LT
             , TO_COUNTRY
             , TO_CITY
             , FROM_SITE_TYPE
             , FROM_SITE_PLANT_ID
             , FROM_SITE_VENDOR_ID
             , FROM_SITE_SOLDTO_CODE
             , FROM_SITE_SHIPTO_CODE
             , FROM_SITE_COMPANY_ID
             , TO_SITE_TYPE
             , TO_SITE_PLANT_ID
             , TO_SITE_VENDOR_ID
             , TO_SITE_SOLDTO_CODE
             , TO_SITE_SHIPTO_CODE
             , TO_SITE_COMPANY_ID
             , NULL                                                             /* CHANGE_REQ_NO */
             , NULL                                                             /* ERP_SO_NO */
             , NULL                                                             /* ERP_SO_ITEM_NO */
             , NULL                                                             /* ERP_DO_NO */
             , NULL                                                             /* ERP_STATUS */
             , P_USER_ID                                                        /* CREATED_BY */
             , P_CREATE_DATE                                                    /* CREATION_DATE */
             , P_USER_ID                                                        /* LAST_UPDATED_BY */
             , P_CREATE_DATE                                                    /* LAST_UPDATE_DATE */
             , P_CREATE_DATE                                                    /* HISTORY_CREATION_DATE */
             , ELECTRODE_YN
             , ELECTRODE_TYPE
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , BEFORE_QTY
             , REMARKS
             , CHECK_NEED_YN
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE CONFIRM_ID = P_CONFIRM_ID;

    END P_SSP0060_INS_CONFIRM_HIST;
    PROCEDURE P_SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING
    (
        P_ACTIVE_FLAG               IN  VARCHAR2
       ,P_DIVISION_ID               IN  VARCHAR2
       ,P_CONFIRM_ID                IN  VARCHAR2
       ,P_SHIPMENT_QTY              IN  VARCHAR2
       ,P_SHIPMENT_DATE             IN  VARCHAR2
       ,P_FROM_SITE                 IN  VARCHAR2
       ,P_NEW_BOD_ID                IN  VARCHAR2
       ,P_NEW_ROUTE_ID              IN  VARCHAR2
       ,P_NEW_ETD_DATE              IN  VARCHAR2
       ,P_NEW_ETA_DATE              IN  VARCHAR2
       ,P_NEW_INCOTERMS             IN  VARCHAR2
       ,P_NEW_TRANSPORT_MODE        IN  VARCHAR2
       ,P_NEW_D_CONTRY              IN  VARCHAR2
       ,P_NEW_D_PORT_CODE           IN  VARCHAR2
       ,P_NEW_A_COUNTRY             IN  VARCHAR2
       ,P_NEW_A_PORT_CODE           IN  VARCHAR2
       ,P_NEW_CUSTOMER_LT           IN  VARCHAR2
       ,P_NEW_TO_COUNTRY            IN  VARCHAR2
       ,P_NEW_TO_CITY               IN  VARCHAR2
       ,P_EDIT_MAIN                 IN  VARCHAR2
       ,P_EDIT_REMARK               IN  VARCHAR2
       ,P_USER_ID                   IN  VARCHAR2
       ,P_USER_DEPT_ID              IN  VARCHAR2
       ,P_ELECTRODE_YN              IN  VARCHAR2
       ,P_ELECTRODE_TYPE            IN  VARCHAR2
       ,P_ORIGIN_FROM_DIVISION_ID   IN  VARCHAR2
       ,P_ORIGION_TO_DIVISION_ID    IN  VARCHAR2
       ,P_REMARKS                   IN  VARCHAR2
       ,P_REMARKS2                  IN  VARCHAR2
       ,P_REMARKS3                  IN  VARCHAR2
       ,P_CHANGE_REASON_CODE        IN  VARCHAR2
       ,P_CHANGE_REASON_DETAIL      IN  VARCHAR2
       ,P_TITLE                     IN  VARCHAR2
       ,P_PROGRAM_ID                IN  VARCHAR2
       ,O_RC1                       OUT SYS_REFCURSOR
       ,O_RC2                       OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING
 * Description  : Shipment Plan Change 작성중 저장
 * 호출			: SSP0060
 * 관련 Table	: SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
 * 관련 프로시저 : PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN - ERP 관련 Table)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018/10/10   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
 * 2019/04/03	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REMARKS, REMARKS 컬럼 추가
 * 2019/04/30	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REQUESTOR 컬럼 변경
 * 2019/05/07	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  REMARKS3 컬럼 추가
 * 2019/05/15	AYJ				[PJ20189106] 전지.GSCM 고도화 이행  CHAGE_REASON_CODE, CHAGE_REASON_DETAIL PARAM추가
 * 2019/05/28	mcTheJ			[PJ20189106] 전지.GSCM 고도화 이행  CHANGE_TITLE 수정
 * 2019/05/29	mcTheJ			[PJ20189106] 전지.GSCM 고도화 이행  CHANGE_REASON 추가로 인한 CS코드에서 반복 호출(단. SONo의 경우 통으로 Parameter 넘김)
 * 2019/09/04	AYJ				etd:shipdate, eta:etd+lt_day로 셋팅
 * 2019/10/29	ayj				FCST_ETA_DATE, ETA_DATE 저장 값 수정(출발일 기준 항차를 고려한 ETA_DATE 계산)
 * 2020-02-26   KIMYONGHO           [C20200224-000318]출하변경사유 코드 변경   R01 - > T07
 * 2021/09/02   KIMYONGHO      SCP_MST_BOD_v -> SCP_MST_BOD_N_V 변경
 * 2021/10/18   KIMYONGHO	   [C20211001-000241][SCM PI팀] Shipment Plan (Auto ESS) 기능 개선 의건
 * 2024/05/08   jilee          PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH  'C' 변경요청
 * 2024/05/22	hsbang			SSP_ANL_SHIP_CONFIRM_CHG_REQ_de A.ATTRIBUTE2(status_detail) 입력
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_MAX_REQ_NO                VARCHAR2(40);
        V_ACTIVE_FLAG               VARCHAR2(4000);
        V_DIVISION_ID               VARCHAR2(4000);
        V_CONFIRM_ID                VARCHAR2(4000);
        V_SHIPMENT_QTY              VARCHAR2(4000);
        V_SHIPMENT_DATE             VARCHAR2(4000);
        V_FROM_SITE                 VARCHAR2(4000);
        V_TO_SITE                   VARCHAR2(4000);
        V_ITEM_ID                   VARCHAR2(4000);
        V_NEW_BOD_ID                VARCHAR2(4000);
        V_NEW_ETD_DATE              VARCHAR2(4000);
        V_NEW_ETA_DATE              VARCHAR2(4000);
        V_NEW_ROUTE_ID              VARCHAR2(4000);
        V_NEW_INCOTERMS             VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000);
        V_NEW_D_CONTRY              VARCHAR2(4000);
        V_NEW_D_PORT_CODE           VARCHAR2(4000);
        V_NEW_A_COUNTRY             VARCHAR2(4000);
        V_NEW_A_PORT_CODE           VARCHAR2(4000);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000);
        V_NEW_TO_COUNTRY            VARCHAR2(4000);
        V_NEW_TO_CITY               VARCHAR2(4000);
        V_EDIT_MAIN                 VARCHAR2(4000);
        V_EDIT_REMARK               VARCHAR2(4000);
        V_CREATE_DATE               DATE;
        V_CHK                       NUMBER := 0;
        V_TITLE                     VARCHAR2(4000);
        V_ELECTRODE_YN              VARCHAR2(4000);
        V_ELECTRODE_TYPE            VARCHAR2(4000);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000);
        V_ORIGION_TO_DIVISION_ID    VARCHAR2(4000);
        V_REMARKS                   VARCHAR2(4000);
        V_REMARKS2                  VARCHAR2(4000);
        V_REMARKS3                  VARCHAR2(4000);
        V_CHANGE_REASON_CODE        VARCHAR2(4000);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000);
        V_DIVISION_ID_TEMP          VARCHAR2(4000);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000);
        V_FROM_SITE_TEMP            VARCHAR2(4000);
        V_TO_SITE_TEMP              VARCHAR2(4000);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000);
        V_NEW_D_CONTRY_TEMP         VARCHAR2(4000);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150) := P_PROGRAM_ID || '-' || P_TITLE;
        V_LOG_TYPE                  VARCHAR2(30);                               /* START/END/ERROR/... */
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000);
        V_DESCRIPTION               VARCHAR2(500);
        D_EVENT_DATE                DATE;
        V_DELIMITER                 VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;
        V_ERR_MSG                   VARCHAR2(4000);
        V_ERR_CODE                  NUMBER;
    BEGIN

        V_CREATE_DATE := SYSDATE;

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 로그 저장이 확정을 동반하므로 되돌림 지점은 그 뒤에 잡는다 */
        SAVEPOINT SP_SAVE_DRAFT;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE := SCM_ARR_SPL_VAL(P_FROM_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID := SCM_ARR_SPL_VAL(P_NEW_BOD_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_TITLE := 'Change on ' || SCM_ARR_SPL_VAL(P_TITLE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_CONTRY := SCM_ARR_SPL_VAL(P_NEW_D_CONTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY := SCM_ARR_SPL_VAL(P_NEW_TO_CITY, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN := SCM_ARR_SPL_VAL(P_EDIT_MAIN, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_REMARK := SCM_ARR_SPL_VAL(P_EDIT_REMARK, V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_YN := SCM_ARR_SPL_VAL(P_ELECTRODE_YN, V_DELIMITER, V_MST_LOOP_CNT);
            V_ELECTRODE_TYPE := SCM_ARR_SPL_VAL(P_ELECTRODE_TYPE, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGIN_FROM_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGIN_FROM_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_ORIGION_TO_DIVISION_ID := SCM_ARR_SPL_VAL(P_ORIGION_TO_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS := SCM_ARR_SPL_VAL(P_REMARKS, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2 := SCM_ARR_SPL_VAL(P_REMARKS2, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3 := SCM_ARR_SPL_VAL(P_REMARKS3, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL, V_DELIMITER, V_MST_LOOP_CNT);

            IF V_CHANGE_REASON_CODE IS NULL THEN
                V_CHANGE_REASON_CODE := 'T07';
            END IF;

            IF V_CHANGE_REASON_DETAIL IS NULL THEN
                V_CHANGE_REASON_DETAIL := NULL;
            END IF;

            BEGIN
                SELECT TO_SITE
                     , ITEM_ID
                  INTO V_TO_SITE
                     , V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_TO_SITE := NULL;
                    V_ITEM_ID := NULL;
            END;

            /* 원문 TOP 1 + ORDER BY PRIORITY 는 첫 행만 받는다 */
            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_CONTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID = V_DIVISION_ID
                                   AND A.FROM_SITE = V_FROM_SITE
                                   AND A.TO_SITE = V_TO_SITE
                                   AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND A.SSP_INCOTERMS = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID = V_ITEM_ID) XA
                         WHERE IA.DIVISION_ID = XA.DIVISION_ID
                           AND IA.BOD_ID = XA.BOD_ID
                           AND IA.DIVISION_ID = V_DIVISION_ID
                           AND IA.FROM_SITE = V_FROM_SITE
                           AND IA.TO_SITE = V_TO_SITE
                           AND IA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND IA.SSP_INCOTERMS = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;                                                       /* 원문도 대상이 없으면 앞 값을 그대로 둔다 */
            END;

            /* 기준정보가 없어 임시 주석처리(2024.06.14)
            IF ( (  @v_division_id_temp			= '' or @v_division_id_temp IS NULL				)
                OR (@v_new_bod_id_temp			= '' or @v_new_bod_id_temp IS NULL				)
                ...
                )
                BEGIN
                    SELECT 'X' AS result_code, NULL AS Request_no;
                    RETURN;
                END
            */

            IF V_EDIT_MAIN = 'Y' THEN

                IF V_CHK = 0 THEN

                    SELECT 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL), -6)
                      INTO V_MAX_REQ_NO
                      FROM DUAL;

                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO
                      , CHANGE_TYPE
                      , CHANGE_REQ_STATUS
                      , DIVISION_ID
                      , FROM_SITE
                      , REQUEST_TITLE
                      , REQUEST_USER
                      , REQUEST_DEPT
                      , REQUEST_TIME
                      , APPROVAL_USER
                      , APPROVAL_DEPT
                      , APPROVAL_TIME
                      , CHANGE_REASON_CODE
                      , CHANGE_REASON_DETAIL
                      , REJECT_REASON
                      , VALID_YN
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO
                      , 'A'
                      , 'A'
                      , V_DIVISION_ID
                      , V_FROM_SITE
                      , V_TITLE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , V_CREATE_DATE
                      , V_CHANGE_REASON_CODE
                      , V_CHANGE_REASON_DETAIL
                      , NULL
                      , 'Y'
                      , P_USER_ID
                      , V_CREATE_DATE
                      , P_USER_ID
                      , V_CREATE_DATE
                      , V_ELECTRODE_YN
                      , V_ELECTRODE_TYPE
                      , V_ORIGIN_FROM_DIVISION_ID
                      , V_ORIGION_TO_DIVISION_ID
                    );

                    /* Request_No값 각기(단일) 생성 */
                    V_CHK := 1;

                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                /* SET @v_new_eta_date = REPLACE(SUBSTRING(@v_new_eta_date,1,10),'-','') */
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF V_SHIPMENT_DATE IS NOT NULL AND LENGTH(V_SHIPMENT_DATE) = 8
                   AND V_NEW_CUSTOMER_LT IS NOT NULL AND LENGTH(V_NEW_CUSTOMER_LT) > 0 THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 — 원문은 묶음 파라미터를 그대로 넘긴다 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(P_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                (
                    CHANGE_REQ_NO
                  , CONFIRM_ID
                  , NEW_YN
                  , DIVISION_ID
                  , ITEM_ID
                  , FROM_SITE
                  , TO_SITE
                  , YYYYMMDD
                  , QTY
                  , BOD_ID
                  , ROUTE_ID
                  , BIZ_TYPE
                  , PROJECT_CODE
                  , FCST_TYPE
                  , FCST_ETD_DATE
                  , FCST_ETA_DATE
                  , ETD_DATE
                  , ETA_DATE
                  , INCOTERMS
                  , TRANSPORT_MODE
                  , D_COUNTRY
                  , D_PORT_CODE
                  , A_COUNTRY
                  , A_PORT_CODE
                  , CUSTOMER_LT
                  , TO_COUNTRY
                  , TO_CITY
                  , NEW_YYYYMMDD
                  , NEW_QTY
                  , NEW_BOD_ID
                  , NEW_ROUTE_ID
                  , NEW_ETD_DATE
                  , NEW_ETA_DATE
                  , NEW_INCOTERMS
                  , NEW_TRANSPORT_MODE
                  , NEW_D_COUNTRY
                  , NEW_D_PORT_CODE
                  , NEW_A_COUNTRY
                  , NEW_A_PORT_CODE
                  , NEW_CUSTOMER_LT
                  , NEW_TO_COUNTRY
                  , NEW_TO_CITY
                  , FROM_SITE_TYPE
                  , FROM_SITE_PLANT_ID
                  , FROM_SITE_VENDOR_ID
                  , FROM_SITE_SOLDTO_CODE
                  , FROM_SITE_SHIPTO_CODE
                  , FROM_SITE_COMPANY_ID
                  , TO_SITE_TYPE
                  , TO_SITE_PLANT_ID
                  , TO_SITE_VENDOR_ID
                  , TO_SITE_SOLDTO_CODE
                  , TO_SITE_SHIPTO_CODE
                  , TO_SITE_COMPANY_ID
                  , ERP_SO_NO
                  , ERP_SO_ITEM_NO
                  , ERP_DO_NO
                  , ERP_STATUS
                  , VALID_YN
                  , ATTRIBUTE1
                  , ATTRIBUTE2
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                  , ELECTRODE_YN
                  , ELECTRODE_TYPE
                  , ORIGIN_FROM_DIVISION_ID
                  , ORIGIN_TO_DIVISION_ID
                  , REMARKS
                  , REMARKS2
                  , REMARKS3
                  , REQUESTOR
                )
                SELECT V_MAX_REQ_NO                                             AS CHANGE_REQ_NO
                     , CONFIRM_ID
                     , 'N'                                                      AS NEW_YN
                     , DIVISION_ID
                     , ITEM_ID
                     , FROM_SITE
                     , TO_SITE
                     , YYYYMMDD
                     , QTY
                     , BOD_ID
                     , ROUTE_ID
                     , BIZ_TYPE
                     , PROJECT_CODE
                     , FCST_TYPE
                     , FCST_ETD_DATE
                     , FCST_ETA_DATE
                     , ETD_DATE
                     , ETA_DATE
                     , INCOTERMS
                     , TRANSPORT_MODE
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , CUSTOMER_LT
                     , TO_COUNTRY
                     , TO_CITY
                     , V_SHIPMENT_DATE                                          AS NEW_YYYYMMDD
                     , TO_NUMBER(V_SHIPMENT_QTY)                                AS NEW_QTY
                     , V_NEW_BOD_ID_TEMP                                        AS NEW_BOD_ID
                     , TO_NUMBER(V_NEW_ROUTE_ID_TEMP)                           AS NEW_ROUTE_ID
                     , V_NEW_ETD_DATE                                           AS NEW_ETD_DATE
                     , V_NEW_ETA_DATE                                           AS NEW_ETA_DATE
                     , V_NEW_INCOTERMS_TEMP                                     AS NEW_INCOTERMS
                     , V_NEW_TRANSPORT_MODE_TEMP                                AS NEW_TRANSPORT_MODE
                     , V_NEW_D_CONTRY_TEMP                                      AS NEW_D_COUNTRY
                     , V_NEW_D_PORT_CODE_TEMP                                   AS NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY_TEMP                                     AS NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE_TEMP                                   AS NEW_A_PORT_CODE
                     , TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)                        AS NEW_CUSTOMER_LT
                     , V_NEW_TO_COUNTRY_TEMP                                    AS NEW_TO_COUNTRY
                     , V_NEW_TO_CITY                                            AS NEW_TO_CITY   /* 원문도 기준정보 값이 아니라 화면 입력값을 넣는다 */
                     , FROM_SITE_TYPE
                     , FROM_SITE_PLANT_ID
                     , FROM_SITE_VENDOR_ID
                     , FROM_SITE_SOLDTO_CODE
                     , FROM_SITE_SHIPTO_CODE
                     , FROM_SITE_COMPANY_ID
                     , TO_SITE_TYPE
                     , TO_SITE_PLANT_ID
                     , TO_SITE_VENDOR_ID
                     , TO_SITE_SOLDTO_CODE
                     , TO_SITE_SHIPTO_CODE
                     , TO_SITE_COMPANY_ID
                     , ERP_SO_NO
                     , ERP_SO_ITEM_NO
                     , ERP_DO_NO
                     , ERP_STATUS
                     , 'Y'
                     , 'N'
                     , 'A'
                     , P_USER_ID                                                AS CREATED_BY
                     , V_CREATE_DATE
                     , P_USER_ID                                                AS LAST_UPDATED_BY
                     , V_CREATE_DATE                                            /* [dbo].[FN_MULTY_TIME](@p_time_zone) LAST_UPDATE_DATE */
                     , ELECTRODE_YN
                     , ELECTRODE_TYPE
                     , ORIGIN_FROM_DIVISION_ID
                     , ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , REQUESTOR
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

            END IF;                                                             /* @v_edit_main = 'Y'	End */

        END LOOP;                                                               /* While					End */

        /* ERP전송 Table(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN) Insert */
        /* 출하확정변경시 ERP 전송 이터 테이블 저장 C: 변경요청 */
        PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH('C', V_MAX_REQ_NO);

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_REQ_NO AS REQUEST_NO
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERROR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            BEGIN
                ROLLBACK TO SP_SAVE_DRAFT;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;                                                       /* 되돌림 지점을 잡기 전에 난 오류 */
            END;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS REQUEST_NO
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERROR_MESSAGE
                  FROM DUAL;

    END P_SSP0060_SAVE_SHIPMENT_REQUEST_DRAFTING;
    PROCEDURE P_SSP0060_SAVE_SHIPMENT_REQUEST_CONFIRM
    (
        P_ACTIVE_FLAG               IN  VARCHAR2
       ,P_DIVISION_ID               IN  VARCHAR2
       ,P_CHANGE_REQUEST_NO         IN  VARCHAR2
       ,P_CONFIRM_ID                IN  VARCHAR2
       ,P_PRODUCT_LEVEL1            IN  VARCHAR2
       ,P_ITEM_ID                   IN  VARCHAR2
       ,P_NICK_NAME                 IN  VARCHAR2
       ,P_FROM_SITE                 IN  VARCHAR2
       ,P_TO_SITE                   IN  VARCHAR2
       ,P_PROJECT_CODE              IN  VARCHAR2
       ,P_PROJECT_NAME              IN  VARCHAR2
       ,P_FCST_TYPE                 IN  VARCHAR2
       ,P_ETD                       IN  VARCHAR2
       ,P_ETA                       IN  VARCHAR2
       ,P_SHIPMENT_QTY              IN  VARCHAR2
       ,P_SHIPMENT_DATE             IN  VARCHAR2
       ,P_NEW_BOD_ID                IN  VARCHAR2
       ,P_NEW_ROUTE_ID              IN  VARCHAR2
       ,P_NEW_ETD_DATE              IN  VARCHAR2
       ,P_NEW_ETA_DATE              IN  VARCHAR2
       ,P_NEW_INCOTERMS             IN  VARCHAR2
       ,P_NEW_TRANSPORT_MODE        IN  VARCHAR2
       ,P_NEW_D_COUNTRY             IN  VARCHAR2
       ,P_NEW_D_PORT_CODE           IN  VARCHAR2
       ,P_NEW_A_COUNTRY             IN  VARCHAR2
       ,P_NEW_A_PORT_CODE           IN  VARCHAR2
       ,P_NEW_CUSTOMER_LT           IN  VARCHAR2
       ,P_NEW_TO_COUNTRY            IN  VARCHAR2
       ,P_NEW_TO_CITY               IN  VARCHAR2
       ,P_REMARKS                   IN  VARCHAR2
       ,P_REMARKS2                  IN  VARCHAR2
       ,P_REMARKS3                  IN  VARCHAR2
       ,P_CHECK_NEED_YN             IN  VARCHAR2
       ,P_USER_ID                   IN  VARCHAR2
       ,P_EDIT_MAIN                 IN  VARCHAR2
       ,P_CHANGE_REASON_CODE        IN  VARCHAR2
       ,P_CHANGE_REASON_DETAIL      IN  VARCHAR2
       ,P_TOP_FLAG                  IN  VARCHAR2
       ,O_RC1                       OUT SYS_REFCURSOR
       ,O_RC2                       OUT SYS_REFCURSOR
    )
    IS
/*
 * Program ID   : SSP0060_SAVE_SHIPMENT_REQUEST_CONFIRM
 * Description  : Shipment Plan Change 확정 저장
 * 호출			: SSP0060
 * 관련 Table	: SSP_ANL_SHIP_CONFIRM, SSP_ANL_SHIP_CONFIRM_H, SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE, XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2020/07/24   KIMYONGHO      신규생성 기능 추가
 * 2024/11/05   jilee           신규 confirm 생성시 ifseq 10개 단위 묶어 처리
 * 2025/08/18   chkim.68       [E20250821-001308] -- to_company_id를 from_site에 따라 to_company_id가 다르게 적용되는 예외를 적용 (scm_site_company_exception)
							FN_GET_SSP_SITE_INFO -> [FN_GET_SSP_SITE_INFO_EXCEPTION]
							   SSP_SITE_INFO를 이용하여 scm_site_company를 획득하도록 공통화
 * 2026/03/25	강주용			[E20260326-001508] 비정상로그이력 수정
 * 2026.09.22   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 */
        V_ACTIVE_FLAG               VARCHAR2(4000);
        V_DIVISION_ID               VARCHAR2(4000);
        V_CHANGE_REQUEST_NO         VARCHAR2(4000);
        V_CONFIRM_ID                VARCHAR2(4000);
        V_PRODUCT_LEVEL1            VARCHAR2(4000);
        V_ITEM_ID                   VARCHAR2(4000);
        V_NICK_NAME                 VARCHAR2(4000);
        V_FROM_SITE                 VARCHAR2(4000);
        V_TO_SITE                   VARCHAR2(4000);
        V_PROJECT_CODE              VARCHAR2(4000);
        V_PROJECT_NAME              VARCHAR2(4000);
        V_FCST_TYPE                 VARCHAR2(4000);
        V_ETD                       VARCHAR2(4000);
        V_ETA                       VARCHAR2(4000);
        V_SHIPMENT_QTY              VARCHAR2(4000);
        V_SHIPMENT_DATE             VARCHAR2(4000);
        V_NEW_BOD_ID                VARCHAR2(4000);
        V_NEW_ETD_DATE              VARCHAR2(4000);
        V_NEW_ETA_DATE              VARCHAR2(4000);
        V_NEW_ROUTE_ID              VARCHAR2(4000);
        V_NEW_INCOTERMS             VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE        VARCHAR2(4000);
        V_NEW_D_COUNTRY             VARCHAR2(4000);
        V_NEW_D_PORT_CODE           VARCHAR2(4000);
        V_NEW_A_COUNTRY             VARCHAR2(4000);
        V_NEW_A_PORT_CODE           VARCHAR2(4000);
        V_NEW_CUSTOMER_LT           VARCHAR2(4000);
        V_NEW_TO_COUNTRY            VARCHAR2(4000);
        V_NEW_TO_CITY               VARCHAR2(4000);
        V_CREATE_DATE               DATE;
        V_BEFORE_QTY                NUMBER(20, 10);
        V_QTY                       NUMBER(20, 10);
        V_REMARKS                   VARCHAR2(4000);
        V_REMARKS2                  VARCHAR2(4000);
        V_REMARKS3                  VARCHAR2(4000);
        V_CHECK_NEED_YN             VARCHAR2(4000);
        V_PLAN_START_YYYYMMDD       VARCHAR2(4000);
        V_SEQ                       VARCHAR2(4000);
        V_EDIT_MAIN                 VARCHAR2(4000);
        V_CHANGE_REASON_CODE        VARCHAR2(4000);
        V_CHANGE_REASON_DETAIL      VARCHAR2(4000);
        V_ELECTRODE_YN              VARCHAR2(4000);
        V_ELECTRODE_TYPE            VARCHAR2(4000);
        V_ORIGIN_FROM_DIVISION_ID   VARCHAR2(4000);
        V_ORIGIN_TO_DIVISION_ID     VARCHAR2(4000);
        V_CHANGE_REQ_NO             VARCHAR2(4000);
        V_FROM_SITE_TYPE            VARCHAR2(4000);
        V_FROM_SITE_PLANT_ID        VARCHAR2(4000);
        V_FROM_SITE_VENDOR_ID       VARCHAR2(4000);
        V_FROM_SITE_COMPANY_ID      VARCHAR2(4000);
        V_FROM_SITE_SOLDTO_CODE     VARCHAR2(4000);
        V_FROM_SITE_SHIPTO_CODE     VARCHAR2(4000);
        V_TO_SITE_TYPE              VARCHAR2(4000);
        V_TO_SITE_PLANT_ID          VARCHAR2(4000);
        V_TO_SITE_VENDOR_ID         VARCHAR2(4000);
        V_TO_SITE_COMPANY_ID        VARCHAR2(4000);
        V_TO_SITE_SOLDTO_CODE       VARCHAR2(4000);
        V_TO_SITE_SHIPTO_CODE       VARCHAR2(4000);
        V_OPERATION_GROUP           VARCHAR2(4000);
        V_PACKAGE_TYPE_CODE         VARCHAR2(4000);
        V_PACKAGE_QTY               NUMBER(20, 10) := 0;
        V_DIVISION_ID_TEMP          VARCHAR2(4000);
        V_NEW_BOD_ID_TEMP           VARCHAR2(4000);
        V_FROM_SITE_TEMP            VARCHAR2(4000);
        V_TO_SITE_TEMP              VARCHAR2(4000);
        V_NEW_INCOTERMS_TEMP        VARCHAR2(4000);
        V_NEW_TRANSPORT_MODE_TEMP   VARCHAR2(4000);
        V_NEW_ROUTE_ID_TEMP         VARCHAR2(4000);
        V_NEW_D_COUNTRY_TEMP        VARCHAR2(4000);
        V_NEW_D_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_A_COUNTRY_TEMP        VARCHAR2(4000);
        V_NEW_A_PORT_CODE_TEMP      VARCHAR2(4000);
        V_NEW_CUSTOMER_LT_TEMP      VARCHAR2(4000);
        V_NEW_TO_COUNTRY_TEMP       VARCHAR2(4000);
        V_NEW_TO_CITY_TEMP          VARCHAR2(4000);
        V_NEW_CONFIRM_ID            VARCHAR2(4000);
        V_INFSEQNO                  VARCHAR2(14);
        V_LAST_CONFIRM_DATE         VARCHAR2(8);
        V_TOP_FLAG                  VARCHAR2(4000);
        V_TMP_DIVISION_ID           VARCHAR2(100);
        V_TMP_FN_TIME_ZONE          VARCHAR2(8);
        V_TMP_SEQ_CONFIRM           VARCHAR2(20);
        V_CFM_CNT                   NUMBER := 0;
        V_WA_COMPANY_ID             VARCHAR2(4000);
        V_CFM_COMPANY_ID            VARCHAR2(4000);
        /* //메일관련 변수//////////////////////////////// */
        V_GRP_CHANGE_REQ            VARCHAR2(20);
        V_MAIL_FLAG                 NUMBER := 0;
        V_MAIL_CHK                  NUMBER := 0;
        V_COMPANY_ID                VARCHAR2(50);
        /* LOG 용 변수 설정 */
        V_PROGRAM_NAME              VARCHAR2(150) := 'SSP0060_SAVE_SHIPMENT_REQUEST_CONFIRM';
        V_LOG_TYPE                  VARCHAR2(30);                               /* START/END/ERROR/... */
        N_LOG_COUNT                 NUMBER := 0;
        V_LOG_MESSAGE               VARCHAR2(1000);
        V_DESCRIPTION               VARCHAR2(500);
        D_EVENT_DATE                DATE;
        V_DELIMITER                 VARCHAR2(1) := '^';
        V_MAX_LOOP_CNT              NUMBER := 0;
        V_MST_LOOP_CNT              NUMBER := 0;
        /* START [E20260326-001508] 비정상로그이력 수정 */
        V_TABLE_ID                  VARCHAR2(150) := 'SSP_ANL_SHIP_CONFIRM';
        V_BATCH_USER                VARCHAR2(150) := 'ssp_batch';
        /* END [E20260326-001508] 비정상로그이력 수정 */
        V_ERR_MSG                   VARCHAR2(4000);
        V_ERR_CODE                  NUMBER;
    BEGIN

        V_CREATE_DATE := SYSDATE;
        V_GRP_CHANGE_REQ := 'G' || TO_CHAR(SYSTIMESTAMP, 'YYYYMMDDHH24MISSFF3');   /* 원문 CONVERT(VARCHAR(23),…,21) 은 밀리초 세 자리 */

        /* 시작 LOG */
        V_LOG_TYPE := 'START';
        V_LOG_MESSAGE := '########## Start of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* 로그 저장이 확정을 동반하므로 되돌림 지점은 그 뒤에 잡는다 */
        SAVEPOINT SP_SAVE_CONFIRM;

        V_MAX_LOOP_CNT := SCM_ARR_SPL_CNT(P_ACTIVE_FLAG, V_DELIMITER);

        WHILE LENGTH(RTRIM(P_ACTIVE_FLAG)) > 0 AND V_MST_LOOP_CNT < V_MAX_LOOP_CNT LOOP

            /* @mst_loop_cnt 1증가 */
            V_MST_LOOP_CNT := V_MST_LOOP_CNT + 1;

            /* 각 컬럼들에 대한 스플릿처리로직 스타트 */
            V_ACTIVE_FLAG := SCM_ARR_SPL_VAL(P_ACTIVE_FLAG, V_DELIMITER, V_MST_LOOP_CNT);
            V_DIVISION_ID := SCM_ARR_SPL_VAL(P_DIVISION_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REQUEST_NO := SCM_ARR_SPL_VAL(P_CHANGE_REQUEST_NO, V_DELIMITER, V_MST_LOOP_CNT);
            V_CONFIRM_ID := SCM_ARR_SPL_VAL(P_CONFIRM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_PRODUCT_LEVEL1 := SCM_ARR_SPL_VAL(P_PRODUCT_LEVEL1, V_DELIMITER, V_MST_LOOP_CNT);
            V_ITEM_ID := SCM_ARR_SPL_VAL(P_ITEM_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NICK_NAME := SCM_ARR_SPL_VAL(P_NICK_NAME, V_DELIMITER, V_MST_LOOP_CNT);
            V_FROM_SITE := SCM_ARR_SPL_VAL(P_FROM_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_TO_SITE := SCM_ARR_SPL_VAL(P_TO_SITE, V_DELIMITER, V_MST_LOOP_CNT);
            V_PROJECT_CODE := SCM_ARR_SPL_VAL(P_PROJECT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_PROJECT_NAME := SCM_ARR_SPL_VAL(P_PROJECT_NAME, V_DELIMITER, V_MST_LOOP_CNT);
            V_FCST_TYPE := SCM_ARR_SPL_VAL(P_FCST_TYPE, V_DELIMITER, V_MST_LOOP_CNT);
            V_ETD := SCM_ARR_SPL_VAL(P_ETD, V_DELIMITER, V_MST_LOOP_CNT);
            V_ETA := SCM_ARR_SPL_VAL(P_ETA, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_QTY := SCM_ARR_SPL_VAL(P_SHIPMENT_QTY, V_DELIMITER, V_MST_LOOP_CNT);
            V_SHIPMENT_DATE := SCM_ARR_SPL_VAL(P_SHIPMENT_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_BOD_ID := SCM_ARR_SPL_VAL(P_NEW_BOD_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ROUTE_ID := SCM_ARR_SPL_VAL(P_NEW_ROUTE_ID, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETD_DATE := SCM_ARR_SPL_VAL(P_NEW_ETD_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_ETA_DATE := SCM_ARR_SPL_VAL(P_NEW_ETA_DATE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_INCOTERMS := SCM_ARR_SPL_VAL(P_NEW_INCOTERMS, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TRANSPORT_MODE := SCM_ARR_SPL_VAL(P_NEW_TRANSPORT_MODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_D_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_D_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_D_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_A_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_A_PORT_CODE := SCM_ARR_SPL_VAL(P_NEW_A_PORT_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_CUSTOMER_LT := SCM_ARR_SPL_VAL(P_NEW_CUSTOMER_LT, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_COUNTRY := SCM_ARR_SPL_VAL(P_NEW_TO_COUNTRY, V_DELIMITER, V_MST_LOOP_CNT);
            V_NEW_TO_CITY := SCM_ARR_SPL_VAL(P_NEW_TO_CITY, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS := SCM_ARR_SPL_VAL(P_REMARKS, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS2 := SCM_ARR_SPL_VAL(P_REMARKS2, V_DELIMITER, V_MST_LOOP_CNT);
            V_REMARKS3 := SCM_ARR_SPL_VAL(P_REMARKS3, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHECK_NEED_YN := SCM_ARR_SPL_VAL(P_CHECK_NEED_YN, V_DELIMITER, V_MST_LOOP_CNT);
            V_EDIT_MAIN := SCM_ARR_SPL_VAL(P_EDIT_MAIN, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_CODE := SCM_ARR_SPL_VAL(P_CHANGE_REASON_CODE, V_DELIMITER, V_MST_LOOP_CNT);
            V_CHANGE_REASON_DETAIL := SCM_ARR_SPL_VAL(P_CHANGE_REASON_DETAIL, V_DELIMITER, V_MST_LOOP_CNT);
            V_TOP_FLAG := SCM_ARR_SPL_VAL(P_TOP_FLAG, V_DELIMITER, V_MST_LOOP_CNT);

            /* 원문 TOP 1 + ORDER BY PRIORITY 는 첫 행만 받는다 */
            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID_TEMP
                     , V_NEW_BOD_ID_TEMP
                     , V_FROM_SITE_TEMP
                     , V_TO_SITE_TEMP
                     , V_NEW_INCOTERMS_TEMP
                     , V_NEW_TRANSPORT_MODE_TEMP
                     , V_NEW_ROUTE_ID_TEMP
                     , V_NEW_D_COUNTRY_TEMP
                     , V_NEW_D_PORT_CODE_TEMP
                     , V_NEW_A_COUNTRY_TEMP
                     , V_NEW_A_PORT_CODE_TEMP
                     , V_NEW_CUSTOMER_LT_TEMP
                     , V_NEW_TO_COUNTRY_TEMP
                     , V_NEW_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID = V_DIVISION_ID
                                   AND A.FROM_SITE = V_FROM_SITE
                                   AND A.TO_SITE = V_TO_SITE
                                   AND A.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                                   AND A.SSP_INCOTERMS = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID = V_ITEM_ID) XA
                         WHERE IA.DIVISION_ID = XA.DIVISION_ID
                           AND IA.BOD_ID = XA.BOD_ID
                           AND IA.DIVISION_ID = V_DIVISION_ID
                           AND IA.FROM_SITE = V_FROM_SITE
                           AND IA.TO_SITE = V_TO_SITE
                           AND IA.TRANSPORT_MODE = V_NEW_TRANSPORT_MODE
                           AND IA.SSP_INCOTERMS = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;                                                       /* 원문도 대상이 없으면 앞 값을 그대로 둔다 */
            END;

            IF (V_DIVISION_ID_TEMP IS NULL
             OR V_NEW_BOD_ID_TEMP IS NULL
             OR V_FROM_SITE_TEMP IS NULL
             OR V_TO_SITE_TEMP IS NULL
             OR V_NEW_INCOTERMS_TEMP IS NULL
             OR V_NEW_TRANSPORT_MODE_TEMP IS NULL
             OR V_NEW_ROUTE_ID_TEMP IS NULL
             OR V_NEW_D_COUNTRY_TEMP IS NULL
             OR V_NEW_D_PORT_CODE_TEMP IS NULL
             OR V_NEW_A_COUNTRY_TEMP IS NULL
             OR V_NEW_A_PORT_CODE_TEMP IS NULL
             OR V_NEW_CUSTOMER_LT_TEMP IS NULL
             OR V_NEW_TO_COUNTRY_TEMP IS NULL
             OR V_NEW_TO_CITY_TEMP IS NULL) THEN

                OPEN O_RC1 FOR
                    SELECT 'X' AS RESULT_CODE
                         , NULL AS RESULT_CNT
                         , NULL AS CHANGE_REQ_NO
                      FROM DUAL;

                OPEN O_RC2 FOR
                    SELECT NULL AS ERR_MESSAGE
                      FROM DUAL
                     WHERE 1 = 2;

                V_LOG_TYPE := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                V_DESCRIPTION := '';
                D_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                RETURN;

            END IF;

            /* 변경 사유 입력 */
            IF LENGTH(RTRIM(V_CHANGE_REQUEST_NO)) > 0 THEN

                UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                   SET ATTRIBUTE4 = V_CHANGE_REASON_CODE
                     , ATTRIBUTE5 = V_CHANGE_REASON_DETAIL
                     , LAST_UPDATED_BY = P_USER_ID
                     , LAST_UPDATE_DATE = V_CREATE_DATE
                 WHERE CHANGE_REQ_NO = V_CHANGE_REQUEST_NO
                   AND CONFIRM_ID = V_CONFIRM_ID;

            END IF;

            IF V_ACTIVE_FLAG <> 'I' THEN

                V_QTY := 0;
                V_BEFORE_QTY := 0;

                BEGIN
                    SELECT QTY
                         , BEFORE_QTY
                      INTO V_QTY
                         , V_BEFORE_QTY
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

                IF V_QTY <> TO_NUMBER(V_SHIPMENT_QTY) THEN
                    V_BEFORE_QTY := V_QTY;
                END IF;

                IF V_SHIPMENT_QTY IS NULL THEN
                    V_SHIPMENT_QTY := NULL;
                END IF;

                IF V_SHIPMENT_DATE IS NULL THEN
                    V_SHIPMENT_DATE := '';
                END IF;

                V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');
                /* SET @v_new_eta_date = REPLACE(SUBSTRING(@v_new_eta_date,1,10),'-','') */

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

                IF V_EDIT_MAIN = 'Y' THEN
                    V_CHECK_NEED_YN := 'Y';
                END IF;

                /* 2020.06.23 ETD_DATE, FCST_ETD_DATE 를 YYYYMMDD 와 같은 날짜로 변경 되도록 수정 */
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET YYYYMMDD = V_SHIPMENT_DATE
                     , QTY = TO_NUMBER(V_SHIPMENT_QTY)
                     , BEFORE_QTY = V_BEFORE_QTY
                     , BOD_ID = V_NEW_BOD_ID_TEMP
                     , ROUTE_ID = TO_NUMBER(V_NEW_ROUTE_ID_TEMP)
                     , INCOTERMS = V_NEW_INCOTERMS_TEMP
                     , D_COUNTRY = V_NEW_D_COUNTRY_TEMP
                     , D_PORT_CODE = V_NEW_D_PORT_CODE_TEMP
                     , A_COUNTRY = V_NEW_A_COUNTRY_TEMP
                     , A_PORT_CODE = V_NEW_A_PORT_CODE_TEMP
                     , TO_COUNTRY = V_NEW_TO_COUNTRY_TEMP
                     , TO_CITY = V_NEW_TO_CITY_TEMP
                     , TRANSPORT_MODE = V_NEW_TRANSPORT_MODE_TEMP
                     , ETD_DATE = V_SHIPMENT_DATE                               /* @v_new_etd_date */
                     , ETA_DATE = V_NEW_ETA_DATE
                     , FCST_ETD_DATE = V_SHIPMENT_DATE                          /* @v_new_etd_date */
                     , FCST_ETA_DATE = V_NEW_ETA_DATE
                     , CUSTOMER_LT = TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP)
                     , REMARKS = V_REMARKS
                     , REMARKS2 = V_REMARKS2
                     , REMARKS3 = V_REMARKS3
                     , CHECK_NEED_YN = V_CHECK_NEED_YN
                     , LAST_UPDATED_BY = P_USER_ID
                     , LAST_UPDATE_DATE = V_CREATE_DATE
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

                /* 해당 안되어 주석 처리 */
                /* IF @v_edit_main = 'Y' */
                BEGIN
                    SELECT CHANGE_REQ_NO
                      INTO V_CHANGE_REQ_NO
                      FROM (SELECT CHANGE_REQ_NO
                              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                             WHERE CONFIRM_ID = V_CONFIRM_ID
                                   /* 조건 해제 */
                                   /* AND A.VALID_YN = 'Y' */
                             ORDER BY LAST_UPDATE_DATE DESC)
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_CHANGE_REQ_NO := NULL;
                END;

                IF LENGTH(RTRIM(V_CHANGE_REQ_NO)) > 0 THEN

                    /* 이력저장 */
                    PR_SSP_ANL_SHIP_CONFIRM_HIST(V_CHANGE_REQ_NO, P_USER_ID, '');

                    /* SCS I/F */
                    IF V_DIVISION_ID = '82' THEN
                        PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_SCS('B', V_CHANGE_REQ_NO);
                    END IF;

                    SELECT COUNT(*)
                      INTO V_MAIL_CHK
                      FROM SSP_MST_SEND_MAIL_REQ
                     WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO;

                    IF V_MAIL_CHK = 0 THEN

                        /* 메일전송 */
                        INSERT INTO SSP_MST_SEND_MAIL_REQ
                        (
                            CHANGE_REQ_NO
                          , TRANSFER_FLAG
                          , GRP_CHANGE_REQ
                        )
                        VALUES
                        (
                            V_CHANGE_REQ_NO
                          , 'N'
                          , V_GRP_CHANGE_REQ
                        );

                        V_MAIL_FLAG := 1;

                    END IF;

                END IF;

            END IF;

            IF V_MAIL_FLAG = 1 THEN
                PR_SSP_MAIL_SEND_ADJUST_MST(V_GRP_CHANGE_REQ);
            END IF;

            /* 2020-07-24 KIMYONGHO 신규생성 기능 추가 */

            /* 확정구간 마지막 일자( 현재일 기준 + 9 = PLANS_START_YYYYMMDD + 10) */
            V_LAST_CONFIRM_DATE := TO_CHAR(SYSDATE + 9, 'YYYYMMDD');

            /* NEW CONFIRM 생성 CHECK 확인========================================================================================== */
            SELECT TO_CHAR(FN_MULTY_TIME(NULL), 'YYYYMMDD')
                 , TO_CHAR(SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL)
              INTO V_TMP_FN_TIME_ZONE
                 , V_TMP_SEQ_CONFIRM
              FROM DUAL;

            V_NEW_CONFIRM_ID := 'C' || V_TMP_FN_TIME_ZONE || SUBSTR('000000' || V_TMP_SEQ_CONFIRM, -6);
            /* //==================================================================================================================== */

            SELECT MAX(PLAN_START_YYYYMMDD)
                 , MAX(PLAN_SEQ)
              INTO V_PLAN_START_YYYYMMDD
                 , V_SEQ
              FROM SSP_PLAN_VERSION_V
             WHERE PLAN_TYPE = 'SP'
               AND DIVISION_ID = V_DIVISION_ID
               AND CONFIRM_FLAG = 'Y'
               AND PLAN_START_YYYYMMDD = (SELECT MAX(PLAN_START_YYYYMMDD)
                                            FROM SSP_PLAN_VERSION_V
                                           WHERE DIVISION_ID = V_DIVISION_ID
                                             AND PLAN_TYPE = 'SP'
                                             AND CONFIRM_FLAG = 'Y');

            IF V_PLAN_START_YYYYMMDD IS NULL THEN
                V_PLAN_START_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');
                V_SEQ := 1;
            END IF;

            V_QTY := 0;
            V_BEFORE_QTY := 0;

            BEGIN
                SELECT QTY
                     , BEFORE_QTY
                  INTO V_QTY
                     , V_BEFORE_QTY
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            IF V_QTY <> TO_NUMBER(V_SHIPMENT_QTY) THEN
                V_BEFORE_QTY := V_QTY;
            END IF;

            IF V_SHIPMENT_QTY IS NULL THEN
                V_SHIPMENT_QTY := NULL;
            END IF;

            IF V_SHIPMENT_DATE IS NULL THEN
                V_SHIPMENT_DATE := '';
            END IF;

            V_NEW_ETD_DATE := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
            V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

            /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
            V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID_TEMP, V_SHIPMENT_DATE);

            IF V_EDIT_MAIN = 'Y' THEN
                V_CHECK_NEED_YN := 'Y';
            END IF;

            BEGIN
                SELECT DIVISION_ID
                     , OPERATION_GROUP
                  INTO V_ORIGIN_FROM_DIVISION_ID
                     , V_OPERATION_GROUP
                  FROM SCM_MST_SITE
                 WHERE SCM_SITE_ID = V_FROM_SITE
                   AND DIVISION_ID = V_DIVISION_ID
                   AND VALID_YN = 'Y';
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    NULL;
            END;

            IF V_PROJECT_CODE = '-' THEN
                V_PROJECT_CODE := '';
            END IF;

            IF V_OPERATION_GROUP <> 'E' THEN

                V_ELECTRODE_YN := 'N';
                /* SET @v_origin_to_division_id = @v_origin_from_division_id ; */

                BEGIN
                    SELECT DIVISION_ID
                      INTO V_ORIGIN_TO_DIVISION_ID
                      FROM (SELECT DIVISION_ID
                              FROM SCM_MST_SITE
                             WHERE SCM_SITE_ID = V_TO_SITE
                               AND VALID_YN = 'Y')
                                                                                /* AND   SITE_TYPE  = 'PLANT' */
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

            ELSE

                V_ELECTRODE_YN := 'Y';

                BEGIN
                    SELECT DIVISION_ID
                      INTO V_ORIGIN_TO_DIVISION_ID
                      FROM (SELECT DIVISION_ID
                              FROM SCM_MST_SITE
                             WHERE SCM_SITE_ID = V_TO_SITE
                               AND VALID_YN = 'Y')
                                                                                /* AND   SITE_TYPE  = 'PLANT' */
                     WHERE ROWNUM = 1;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        NULL;
                END;

            END IF;

            /* [E20250821-001308] begin 대체코드 */
            V_TMP_DIVISION_ID := V_ORIGIN_FROM_DIVISION_ID;
            V_FROM_SITE_TYPE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SITE_TYPE');
            V_FROM_SITE_PLANT_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'PLANT_ID');
            V_FROM_SITE_VENDOR_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'VENDOR_ID');
            V_FROM_SITE_COMPANY_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'COMPANY_ID');
            V_FROM_SITE_SOLDTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SOLDTO_CODE');
            V_FROM_SITE_SHIPTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SHIPTO_CODE');

            V_TMP_DIVISION_ID := CASE WHEN V_DIVISION_ID = 'EE' THEN V_ORIGIN_FROM_DIVISION_ID ELSE V_ORIGIN_TO_DIVISION_ID END;
            V_TO_SITE_TYPE := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'SITE_TYPE');
            V_TO_SITE_PLANT_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'PLANT_ID');
            V_TO_SITE_VENDOR_ID := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'VENDOR_ID');
            V_TO_SITE_COMPANY_ID := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'COMPANY_ID');
            V_TO_SITE_SOLDTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SOLDTO_CODE');
            V_TO_SITE_SHIPTO_CODE := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SHIPTO_CODE');
            /* [E20250821-001308] end 대체코드 */

            -------------------------------------------------------------------------------------------------------------
            -- 1. SHIP_CONFIRM 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM
            -- 신규 건만 생성
            -------------------------------------------------------------------------------------------------------------
            IF V_CHANGE_REQUEST_NO IS NULL THEN                  /* Shipment Plan Detail에서 저장 후 SSP_ANL_SHIP_CONFIRM_CHG_REQ 생성되지 않았다면 */

                IF V_ACTIVE_FLAG = 'I' THEN

                    P_SSP0060_GET_PACKAGE_INFO(V_DIVISION_ID, V_FROM_SITE, V_ITEM_ID, V_OPERATION_GROUP, TO_NUMBER(V_SHIPMENT_QTY), V_PACKAGE_TYPE_CODE, V_PACKAGE_QTY);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM
                    (
                        CONFIRM_ID, CHANGE_TYPE, SHIPMENT_STATUS, DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE
                      , SEQ, ITEM_ID, FROM_SITE, TO_SITE, YYYYMMDD, PLANNED_QTY
                      , QTY, BOD_ID, ROUTE_ID, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
                      , FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, INCOTERMS, TRANSPORT_MODE
                      , D_COUNTRY, D_PORT_CODE, A_COUNTRY, A_PORT_CODE, CUSTOMER_LT, TO_COUNTRY
                      , TO_CITY, FROM_SITE_TYPE, FROM_SITE_PLANT_ID, FROM_SITE_VENDOR_ID, FROM_SITE_SOLDTO_CODE, FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID, TO_SITE_TYPE, TO_SITE_PLANT_ID, TO_SITE_VENDOR_ID, TO_SITE_SOLDTO_CODE, TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID, CHANGE_REQ_NO, ERP_SO_NO, ERP_SO_ITEM_NO, ERP_DO_NO, ERP_STATUS
                      , ELECTRODE_YN, ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, PACKAGE_TYPE_CODE, FACTORY_ID
                      , REQUESTOR, BEFORE_QTY, REMARKS, REMARKS2, REMARKS3, CHECK_NEED_YN
                      , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, PACKAGE_QTY, DOM_EXP
                    )
                    VALUES
                    (
                        V_NEW_CONFIRM_ID, 'C', 'C', V_DIVISION_ID, V_PLAN_START_YYYYMMDD, 'SP'
                      , TO_NUMBER(V_SEQ), V_ITEM_ID, V_FROM_SITE, V_TO_SITE, V_SHIPMENT_DATE, TO_NUMBER(V_SHIPMENT_QTY)
                      , TO_NUMBER(V_SHIPMENT_QTY), V_NEW_BOD_ID_TEMP, TO_NUMBER(V_NEW_ROUTE_ID_TEMP), V_OPERATION_GROUP, V_PROJECT_CODE, V_FCST_TYPE
                      , V_SHIPMENT_DATE, V_NEW_ETA_DATE, V_SHIPMENT_DATE, V_NEW_ETA_DATE, V_NEW_INCOTERMS_TEMP, V_NEW_TRANSPORT_MODE_TEMP
                      , V_NEW_D_COUNTRY_TEMP, V_NEW_D_PORT_CODE_TEMP, V_NEW_A_COUNTRY_TEMP, V_NEW_A_PORT_CODE_TEMP, TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP), V_NEW_TO_COUNTRY_TEMP
                      , V_NEW_TO_CITY_TEMP, V_FROM_SITE_TYPE, V_FROM_SITE_PLANT_ID, V_FROM_SITE_VENDOR_ID, V_FROM_SITE_SOLDTO_CODE, V_FROM_SITE_SHIPTO_CODE
                      , V_FROM_SITE_COMPANY_ID, V_TO_SITE_TYPE, V_TO_SITE_PLANT_ID, V_TO_SITE_VENDOR_ID, V_TO_SITE_SOLDTO_CODE, V_TO_SITE_SHIPTO_CODE
                      , V_TO_SITE_COMPANY_ID, V_CHANGE_REQ_NO, NULL, NULL, V_PACKAGE_TYPE_CODE, NULL
                      , V_ELECTRODE_YN, V_ELECTRODE_TYPE, V_ORIGIN_FROM_DIVISION_ID, V_ORIGIN_TO_DIVISION_ID, NULL, NULL
                      , P_USER_ID, V_BEFORE_QTY, V_REMARKS, V_REMARKS2, V_REMARKS3, V_CHECK_NEED_YN
                      , P_USER_ID, V_CREATE_DATE, P_USER_ID, V_CREATE_DATE, V_PACKAGE_QTY, NULL
                    );

                ELSE

                    V_NEW_CONFIRM_ID := V_CONFIRM_ID;

                END IF;

            ELSE                                                                /* Shipment Plan 메인화면에서 저장 후 SSP_ANL_SHIP_CONFIRM_CHG_REQ 생성되었다면, */

                V_NEW_CONFIRM_ID := V_CONFIRM_ID;

                SELECT COUNT(*)
                  INTO V_CFM_CNT
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

                IF V_CFM_CNT = 0 THEN                                           /* 기존에 CONFIRM_ID가 존재하면 새로운 CONFIRM_ID로 입력 */

                    P_SSP0060_GET_PACKAGE_INFO(V_DIVISION_ID, V_FROM_SITE, V_ITEM_ID, V_OPERATION_GROUP, TO_NUMBER(V_SHIPMENT_QTY), V_PACKAGE_TYPE_CODE, V_PACKAGE_QTY);

                    INSERT INTO SSP_ANL_SHIP_CONFIRM
                    (
                        CONFIRM_ID, CHANGE_TYPE, SHIPMENT_STATUS, DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE
                      , SEQ, ITEM_ID, FROM_SITE, TO_SITE, YYYYMMDD, PLANNED_QTY
                      , QTY, BOD_ID, ROUTE_ID, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
                      , FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, INCOTERMS, TRANSPORT_MODE
                      , D_COUNTRY, D_PORT_CODE, A_COUNTRY, A_PORT_CODE, CUSTOMER_LT, TO_COUNTRY
                      , TO_CITY, FROM_SITE_TYPE, FROM_SITE_PLANT_ID, FROM_SITE_VENDOR_ID, FROM_SITE_SOLDTO_CODE, FROM_SITE_SHIPTO_CODE
                      , FROM_SITE_COMPANY_ID, TO_SITE_TYPE, TO_SITE_PLANT_ID, TO_SITE_VENDOR_ID, TO_SITE_SOLDTO_CODE, TO_SITE_SHIPTO_CODE
                      , TO_SITE_COMPANY_ID, CHANGE_REQ_NO, ERP_SO_NO, ERP_SO_ITEM_NO, ERP_DO_NO, ERP_STATUS
                      , ELECTRODE_YN, ELECTRODE_TYPE, ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID, PACKAGE_TYPE_CODE, FACTORY_ID
                      , REQUESTOR, BEFORE_QTY, REMARKS, REMARKS2, REMARKS3, CHECK_NEED_YN
                      , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, PACKAGE_QTY, DOM_EXP
                    )
                    VALUES
                    (
                        V_NEW_CONFIRM_ID, 'C', 'C', V_DIVISION_ID, V_PLAN_START_YYYYMMDD, 'SP'
                      , TO_NUMBER(V_SEQ), V_ITEM_ID, V_FROM_SITE, V_TO_SITE, V_SHIPMENT_DATE, TO_NUMBER(V_SHIPMENT_QTY)
                      , TO_NUMBER(V_SHIPMENT_QTY), V_NEW_BOD_ID_TEMP, TO_NUMBER(V_NEW_ROUTE_ID_TEMP), V_OPERATION_GROUP, V_PROJECT_CODE, V_FCST_TYPE
                      , V_SHIPMENT_DATE, V_NEW_ETA_DATE, V_SHIPMENT_DATE, V_NEW_ETA_DATE, V_NEW_INCOTERMS_TEMP, V_NEW_TRANSPORT_MODE_TEMP
                      , V_NEW_D_COUNTRY_TEMP, V_NEW_D_PORT_CODE_TEMP, V_NEW_A_COUNTRY_TEMP, V_NEW_A_PORT_CODE_TEMP, TO_NUMBER(V_NEW_CUSTOMER_LT_TEMP), V_NEW_TO_COUNTRY_TEMP
                      , V_NEW_TO_CITY_TEMP, V_FROM_SITE_TYPE, V_FROM_SITE_PLANT_ID, V_FROM_SITE_VENDOR_ID, V_FROM_SITE_SOLDTO_CODE, V_FROM_SITE_SHIPTO_CODE
                      , V_FROM_SITE_COMPANY_ID, V_TO_SITE_TYPE, V_TO_SITE_PLANT_ID, V_TO_SITE_VENDOR_ID, V_TO_SITE_SOLDTO_CODE, V_TO_SITE_SHIPTO_CODE
                      , V_TO_SITE_COMPANY_ID, V_CHANGE_REQ_NO, NULL, NULL, V_PACKAGE_TYPE_CODE, NULL
                      , V_ELECTRODE_YN, V_ELECTRODE_TYPE, V_ORIGIN_FROM_DIVISION_ID, V_ORIGIN_TO_DIVISION_ID, NULL, NULL
                      , P_USER_ID, V_BEFORE_QTY, V_REMARKS, V_REMARKS2, V_REMARKS3, V_CHECK_NEED_YN
                      , P_USER_ID, V_CREATE_DATE, P_USER_ID, V_CREATE_DATE, V_PACKAGE_QTY, NULL
                    );

                END IF;

            END IF;

            -------------------------------------------------------------------------------------------------------------
            -- 2. SHIP_CONFIRM HISTORY 입력 : 출하확정 SSP_ANL_SHIP_CONFIRM_H
            -- 신규 건만 생성
            -------------------------------------------------------------------------------------------------------------
            /* 하단 화면과 중복 사용으로 인해 플래그 구분 */
            IF V_TOP_FLAG = 'Y' THEN
                P_SSP0060_INS_CONFIRM_HIST(V_NEW_CONFIRM_ID, P_USER_ID, V_CREATE_DATE);
            END IF;

            IF V_ACTIVE_FLAG = 'I' THEN

                P_SSP0060_INS_CONFIRM_HIST(V_NEW_CONFIRM_ID, P_USER_ID, V_CREATE_DATE);

                /* 241105 jilee ifseqno 10개단위 처리 */
                IF MOD(V_MST_LOOP_CNT, 10) = 1 THEN
                    SELECT TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_XIF_ERP_IFSEQNO.NEXTVAL), -6)
                      INTO V_INFSEQNO
                      FROM DUAL;
                END IF;

                IF V_INFSEQNO IS NULL THEN
                    SELECT TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(SEQ1_XIF_ERP_IFSEQNO.NEXTVAL), -6)
                      INTO V_INFSEQNO
                      FROM DUAL;
                END IF;

                INSERT INTO XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
                (
                    IFSEQNO, CONFIRM_ID, SHIPMENT_STATUS, LAST_CONFIRM_DATE, VERSION_TYPE, SALES_COMPANY_ID
                  , DIVISION_ID, ITEM_ID, FROM_SITE, TO_SITE, YYYYMMDD, QTY
                  , BOD_ID, ROUTE_ID, OPERATION_GROUP, BIZ_TYPE, PROJECT_CODE, FCST_TYPE
                  , FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, INCOTERMS, INCOTERMS2
                  , TRANSPORT_MODE, D_COUNTRY, D_PORT_CODE, A_COUNTRY, A_PORT_CODE, CUSTOMER_LT
                  , TO_COUNTRY, TO_CITY, FROM_SITE_TYPE, FROM_SITE_PLANT_ID, FROM_SITE_VENDOR_ID, FROM_SITE_SOLDTO_CODE
                  , FROM_SITE_SHIPTO_CODE, FROM_SITE_COMPANY_ID, TO_SITE_TYPE, TO_SITE_PLANT_ID, TO_SITE_VENDOR_ID, TO_SITE_SOLDTO_CODE
                  , TO_SITE_SHIPTO_CODE, TO_SITE_COMPANY_ID, BUILDING, REMARK, CUSTOMER_REQ, CHANGE_CODE
                  , CHANGE_CODE_NAME, REQUESTOR, TRANSFER_FLAG, TRANSFER_DATE, CREATED_BY, CREATION_DATE
                  , LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
                  , ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                    /*----------------------------------------------------------------------------------------
                        2020.06.30 : KBK
                        I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                    ------------------------------------------------------------------------------------------*/
                  , PACKAGE_TYPE, FACTORY_ID, PACKAGE_QTY, DOM_EXP, ERP_ATTR1, ERP_ATTR2
                  , ERP_ATTR3, ERP_ATTR4, ERP_ATTR5
                )
                SELECT IA.IFSEQNO
                     , IA.CONFIRM_ID
                     , IA.SHIPMENT_STATUS
                     , IA.LAST_CONFIRM_DATE
                     , IA.VERSION_TYPE
                     , NVL(F.NEW_VALUE1, IA.SALES_COMPANY_ID)                   AS SALES_COMPANY_ID
                     , IA.DIVISION_ID
                     , IA.ITEM_ID
                     , NVL(G.NEW_VALUE1, IA.FROM_SITE)                          AS FROM_SITE
                     , NVL(H.NEW_VALUE1, IA.TO_SITE)                            AS TO_SITE
                     , IA.YYYYMMDD
                     , IA.QTY
                     , IA.BOD_ID
                     , IA.ROUTE_ID
                     , IA.OPERATION_GROUP
                     , IA.BIZ_TYPE
                     , IA.PROJECT_CODE
                     , IA.FCST_TYPE
                     , IA.FCST_ETD_DATE
                     , IA.FCST_ETA_DATE
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.INCOTERMS
                     , IA.INCOTERMS2
                     , IA.TRANSPORT_MODE
                     , IA.D_COUNTRY
                     , IA.D_PORT_CODE
                     , IA.A_COUNTRY
                     , IA.A_PORT_CODE
                     , IA.CUSTOMER_LT
                     , IA.TO_COUNTRY
                     , IA.TO_CITY
                     , IA.FROM_SITE_TYPE
                     , NVL(I.NEW_VALUE1, IA.FROM_SITE_PLANT_ID)                 AS FROM_SITE_PLANT_ID
                     , NVL(J.NEW_VALUE1, IA.FROM_SITE_VENDOR_ID)                AS FROM_SITE_VENDOR_ID
                     , NVL(K.NEW_VALUE1, IA.FROM_SITE_SOLDTO_CODE)              AS FROM_SITE_SOLDTO_CODE
                     , NVL(L.NEW_VALUE1, IA.FROM_SITE_SHIPTO_CODE)              AS FROM_SITE_SHIPTO_CODE
                     , NVL(M.NEW_VALUE1, IA.FROM_SITE_COMPANY_ID)               AS FROM_SITE_COMPANY_ID
                     , IA.TO_SITE_TYPE
                     , NVL(N.NEW_VALUE1, IA.TO_SITE_PLANT_ID)                   AS TO_SITE_PLANT_ID
                     , NVL(O.NEW_VALUE1, IA.TO_SITE_VENDOR_ID)                  AS TO_SITE_VENDOR_ID
                     , NVL(P.NEW_VALUE1, IA.TO_SITE_SOLDTO_CODE)                AS TO_SITE_SOLDTO_CODE
                     , NVL(Q.NEW_VALUE1, IA.TO_SITE_SHIPTO_CODE)                AS TO_SITE_SHIPTO_CODE
                     , NVL(R.NEW_VALUE1, IA.TO_SITE_COMPANY_ID)                 AS TO_SITE_COMPANY_ID
                     , IA.BUILDING
                     , IA.REMARK
                     , IA.CUSTOMER_REQ
                     , IA.CHANGE_CODE
                     , IA.CHANGE_CODE_NAME
                     , IA.REQUESTOR
                     , IA.TRANSFER_FLAG
                     , IA.TRANSFER_DATE
                     , IA.CREATED_BY
                     , IA.CREATION_DATE
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                     , IA.ATTRIBUTE1
                     , IA.ATTRIBUTE2
                     , IA.ATTRIBUTE3
                     , IA.ATTRIBUTE4
                     , IA.ATTRIBUTE5
                     , IA.ATTRIBUTE6
                     , IA.ATTRIBUTE7
                     , IA.ATTRIBUTE8
                     , IA.ATTRIBUTE9
                     , IA.ATTRIBUTE10
                     , IA.PACKAGE_TYPE_CODE
                     , IA.FACTORY_ID
                     , IA.PACKAGE_QTY
                     , IA.DOM_EXP
                     , NULL                                                     AS ERP_ATTR1
                     , NULL                                                     AS ERP_ATTR2
                     , NULL                                                     AS ERP_ATTR3
                     , IA.TO_SITE_PLANT_ID                                      AS ERP_ATTR4   /* ERP_ATTR4-- NERP에서 원본 정보 참고용 (2025-04-23) */
                     , NULL                                                     AS ERP_ATTR5
                  FROM (SELECT SA.IFSEQNO
                             , SA.CONFIRM_ID
                             , SA.SHIPMENT_STATUS
                             , SA.LAST_CONFIRM_DATE
                             , SA.VERSION_TYPE
                             , SA.SALES_COMPANY_ID
                             , D.ATTRIBUTE3                                     AS DIVISION_ID
                             , SA.ITEM_ID
                             , SA.FROM_SITE
                             , SA.TO_SITE
                             , SA.YYYYMMDD
                             , SA.QTY
                             , SA.BOD_ID
                             , SA.ROUTE_ID
                             , SA.OPERATION_GROUP
                             , SA.BIZ_TYPE
                             , SA.PROJECT_CODE
                             , SA.FCST_TYPE
                             , SA.FCST_ETD_DATE
                             , SA.FCST_ETA_DATE
                             , SA.ETD_DATE
                             , SA.ETA_DATE
                             , SA.INCOTERMS
                             , SA.INCOTERMS2
                             , SA.TRANSPORT_MODE
                             , SA.D_COUNTRY
                             , SA.D_PORT_CODE
                             , SA.A_COUNTRY
                             , SA.A_PORT_CODE
                             , SA.CUSTOMER_LT
                             , SA.TO_COUNTRY
                             , SA.TO_CITY
                             , SA.FROM_SITE_TYPE
                             , SA.FROM_SITE_PLANT_ID
                             , SA.FROM_SITE_VENDOR_ID
                             , SA.FROM_SITE_SOLDTO_CODE
                             , SA.FROM_SITE_SHIPTO_CODE
                             , SA.FROM_SITE_COMPANY_ID
                             , SA.TO_SITE_TYPE
                             , SA.TO_SITE_PLANT_ID
                             , SA.TO_SITE_VENDOR_ID
                             , SA.TO_SITE_SOLDTO_CODE
                             , SA.TO_SITE_SHIPTO_CODE
                             , SA.TO_SITE_COMPANY_ID
                             , SA.BUILDING
                             , SA.REMARK
                             , SA.CUSTOMER_REQ
                             , SA.CHANGE_CODE
                             , SA.CHANGE_CODE_NAME
                             , SA.REQUESTOR
                             , SA.TRANSFER_FLAG
                             , SA.TRANSFER_DATE
                             , SA.CREATED_BY
                             , SA.CREATION_DATE
                             , SA.LAST_UPDATED_BY
                             , SA.LAST_UPDATE_DATE
                             , SA.ATTRIBUTE1
                             , SA.ATTRIBUTE2
                             , SA.ATTRIBUTE3
                             , SA.ATTRIBUTE4
                             , SA.ATTRIBUTE5
                             , SA.ATTRIBUTE6
                             , SA.ATTRIBUTE7
                             , SA.ATTRIBUTE8
                             , SA.ATTRIBUTE9
                             , SA.ATTRIBUTE10
                            /*----------------------------------------------------------------------------------------
                                2020.06.30 : KBK
                                I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                            ------------------------------------------------------------------------------------------*/
                             , E.PACKAGE_TYPE_CODE
                             , E.FACTORY_ID
                             , CEIL(CASE WHEN E.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(SA.QTY * NVL(E.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(E.BOX_PER_CUT, 1)
                                         WHEN E.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(SA.QTY * NVL(E.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(E.STEELCRATE_PER_CUT, 1)
                                         WHEN E.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(SA.QTY * NVL(E.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(E.STEELRACK_PER_CUT, 1)
                                         ELSE NVL(SA.QTY, 0)
                                    END)                                        AS PACKAGE_QTY
                             , E.DOM_EXP_TYPE                                   AS DOM_EXP
                          FROM (SELECT V_INFSEQNO                                AS IFSEQNO
                                     , A.CONFIRM_ID
                                     , 'A'                                       AS SHIPMENT_STATUS   /* I_PLGB  A: 확정 */
                                     , V_LAST_CONFIRM_DATE                       AS LAST_CONFIRM_DATE /* I_DATE  확정구간 마지막 일자 */
                                     , 'B'                                       AS VERSION_TYPE      /* B:NEW/A:OLD */
                                     , NVL(C.ATTRIBUTE2, B.ATTRIBUTE2)            AS SALES_COMPANY_ID
                                     , CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END   AS DIVISION_ID
                                     , A.ITEM_ID                                 AS ITEM_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.YYYYMMDD
                                     , A.QTY
                                     , A.BOD_ID
                                     , A.ROUTE_ID
                                     , A.BIZ_TYPE                                AS OPERATION_GROUP
                                     , A.BIZ_TYPE
                                     , CASE WHEN TRIM(A.PROJECT_CODE) IS NULL OR TRIM(A.PROJECT_CODE) = '-' THEN 'TBD' ELSE A.PROJECT_CODE END   AS PROJECT_CODE
                                     , A.FCST_TYPE
                                     , A.FCST_ETD_DATE
                                     , A.FCST_ETA_DATE
                                     , A.ETD_DATE
                                     , A.ETA_DATE
                                     , A.INCOTERMS                               AS INCOTERMS
                                     , NULL                                      AS INCOTERMS2
                                     , A.TRANSPORT_MODE
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.CUSTOMER_LT
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.FROM_SITE_TYPE
                                     , A.FROM_SITE_PLANT_ID
                                     , A.FROM_SITE_VENDOR_ID
                                     , A.FROM_SITE_SOLDTO_CODE
                                     , A.FROM_SITE_SHIPTO_CODE
                                     , A.FROM_SITE_COMPANY_ID
                                     , A.TO_SITE_TYPE
                                     , A.TO_SITE_PLANT_ID
                                     , A.TO_SITE_VENDOR_ID
                                     , A.TO_SITE_SOLDTO_CODE
                                     , A.TO_SITE_SHIPTO_CODE
                                     , A.TO_SITE_COMPANY_ID
                                     , NULL                                      AS BUILDING
                                     , NULL                                      AS REMARK
                                     , NULL                                      AS CUSTOMER_REQ
                                     , NULL                                      AS CHANGE_CODE
                                     , NULL                                      AS CHANGE_CODE_NAME
                                     , A.REQUESTOR                               AS REQUESTOR
                                     , 'N'                                       AS TRANSFER_FLAG
                                     , SYSDATE                                   AS TRANSFER_DATE
                                     , A.LAST_UPDATED_BY                         AS CREATED_BY
                                     , SYSDATE                                   AS CREATION_DATE
                                     , A.LAST_UPDATED_BY                         AS LAST_UPDATED_BY
                                     , SYSDATE                                   AS LAST_UPDATE_DATE
                                     , NULL                                      AS ATTRIBUTE1
                                     , NULL                                      AS ATTRIBUTE2
                                     , NULL                                      AS ATTRIBUTE3
                                     , NULL                                      AS ATTRIBUTE4
                                     , NULL                                      AS ATTRIBUTE5
                                     , NULL                                      AS ATTRIBUTE6
                                     , NULL                                      AS ATTRIBUTE7
                                     , NULL                                      AS ATTRIBUTE8
                                     , NULL                                      AS ATTRIBUTE9
                                     , A.ELECTRODE_YN                            AS ATTRIBUTE10
                                  FROM SSP_ANL_SHIP_CONFIRM A
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL B
                                     , SCM_ADM_LOOKUP_MASTER_DETAIL C
                                 WHERE B.LOOKUP_TYPE(+) = 'CELL_SHIP_FROM_TO'
                                   AND B.VALID_YN(+) = 'Y'
                                   AND B.SEGMENT1(+) = A.FROM_SITE_COMPANY_ID
                                   AND B.SEGMENT3(+) = A.FROM_SITE
                                   AND B.SEGMENT4(+) = A.TO_SITE_COMPANY_ID
                                   AND B.SEGMENT5(+) = A.TO_SITE
                                   AND C.LOOKUP_TYPE(+) = 'ELECTRODE_SHIP_FROM_TO'
                                   AND C.VALID_YN(+) = 'Y'
                                   AND C.SEGMENT1(+) = A.FROM_SITE_COMPANY_ID
                                   AND C.SEGMENT3(+) = A.FROM_SITE
                                   AND C.SEGMENT4(+) = A.TO_SITE_COMPANY_ID
                                   AND C.ATTRIBUTE1(+) = A.TO_SITE
                                   AND A.CONFIRM_ID = V_NEW_CONFIRM_ID
                                   AND NVL(A.QTY, 0) <> 0                       /* 0은IF 제외 */
                               ) SA
                             , SCM_MST_DIVISION D
                             , SSP_MST_SITE_ITEM_EE_V E
                         WHERE SA.DIVISION_ID = D.DIVISION_ID
                           AND SA.DIVISION_ID = (CASE WHEN SA.BIZ_TYPE = 'E' THEN E.DIVISION_ID(+) ELSE E.ASSY_DIVISION_ID(+) END)
                           AND SA.FROM_SITE = (CASE WHEN SA.BIZ_TYPE = 'E' THEN E.SCM_SITE_ID(+) ELSE E.ASSY_SCM_SITE_ID(+) END)
                           AND SA.ITEM_ID = E.ITEM_ID(+)
                       ) IA
                     , NERP_CONV_MASTER F
                     , NERP_CONV_MASTER G
                     , NERP_CONV_MASTER H
                     , NERP_CONV_MASTER I
                     , NERP_CONV_MASTER J
                     , NERP_CONV_MASTER K
                     , NERP_CONV_MASTER L
                     , NERP_CONV_MASTER M
                     , NERP_CONV_MASTER N
                     , NERP_CONV_MASTER O
                     , NERP_CONV_MASTER P
                     , NERP_CONV_MASTER Q
                     , NERP_CONV_MASTER R
                 WHERE IA.SALES_COMPANY_ID = F.OLD_VALUE1(+)
                   AND F.CODETYPE(+) = 'COMPANY_ID'
                   AND IA.FROM_SITE = G.OLD_VALUE1(+)
                   AND G.CODETYPE(+) = 'SCP_SITE_ID'
                   AND IA.TO_SITE = H.OLD_VALUE1(+)
                   AND H.CODETYPE(+) = 'SCP_SITE_ID'
                   AND IA.FROM_SITE_PLANT_ID = I.OLD_VALUE1(+)
                   AND I.CODETYPE(+) = 'PLANT_ID'
                   AND IA.FROM_SITE_VENDOR_ID = J.OLD_VALUE1(+)
                   AND J.CODETYPE(+) = 'VENDOR_ID'
                   AND IA.FROM_SITE_SOLDTO_CODE = K.OLD_VALUE1(+)
                   AND K.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.FROM_SITE_SHIPTO_CODE = L.OLD_VALUE1(+)
                   AND L.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.FROM_SITE_COMPANY_ID = M.OLD_VALUE1(+)
                   AND M.CODETYPE(+) = 'COMPANY_ID'
                   AND IA.TO_SITE_PLANT_ID = N.OLD_VALUE1(+)
                   AND N.CODETYPE(+) = 'PLANT_ID'
                   AND IA.TO_SITE_VENDOR_ID = O.OLD_VALUE1(+)
                   AND O.CODETYPE(+) = 'VENDOR_ID'
                   AND IA.TO_SITE_SOLDTO_CODE = P.OLD_VALUE1(+)
                   AND P.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.TO_SITE_SHIPTO_CODE = Q.OLD_VALUE1(+)
                   AND Q.CODETYPE(+) = 'END_CUSTOMER_ID'
                   AND IA.TO_SITE_COMPANY_ID = R.OLD_VALUE1(+)
                   AND R.CODETYPE(+) = 'COMPANY_ID';

                /* MKT FCST - SSP Sync 신규 생성 건 대상 */
                PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, V_NEW_CONFIRM_ID);

            END IF;

        END LOOP;                                                               /* end of while loop */

        /* START [E20260326-001508] 비정상로그이력 수정 */
        V_LOG_TYPE := 'TXN';                                                    /* ▶ 로그타입 */
        N_LOG_COUNT := SQL%ROWCOUNT;
        V_LOG_MESSAGE := 'INSERT INTO ' || V_TABLE_ID;
        V_DESCRIPTION := 'Process Complete...' || ':' || TO_CHAR(D_EVENT_DATE, 'YYYYMMDD');
        D_EVENT_DATE := SYSDATE;

        PR_SCP_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_BATCH_USER);
        /* END [E20260326-001508] 비정상로그이력 수정 */

        V_LOG_TYPE := 'END';
        V_LOG_MESSAGE := '########## END of procedure ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        /* [C20201223-000448] MKT FCST - SSP Sync */
        PR_DM_SSP_CONFIRM_SYNC(P_DIVISION_ID, P_CONFIRM_ID);

        /* 240223 jilee 폴란드 WA 법인 변경건 전체 내역 송부 */
        IF LENGTH(RTRIM(V_CONFIRM_ID)) > 0 THEN

            BEGIN
                SELECT SEGMENT1                                                 /* company id */
                  INTO V_WA_COMPANY_ID
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'SSP_PLN_FP_SHIP_TARGET_WA'
                   AND VALID_YN = 'Y';
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_WA_COMPANY_ID := NULL;
            END;

            BEGIN
                SELECT FROM_SITE_COMPANY_ID
                  INTO V_CFM_COMPANY_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_CFM_COMPANY_ID := NULL;
            END;

            IF V_WA_COMPANY_ID = V_CFM_COMPANY_ID THEN
                PR_SSP_PLN_FP_SHIP_TARGET_WA;
            END IF;

        END IF;

        /* 결과코드, 결과 카운트 반환 */
        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , V_MAX_LOOP_CNT AS RESULT_CNT
                 , NVL(V_CHANGE_REQ_NO, '') AS CHANGE_REQ_NO
              FROM DUAL;

        OPEN O_RC2 FOR
            SELECT NULL AS ERR_MESSAGE
              FROM DUAL
             WHERE 1 = 2;

    EXCEPTION
        WHEN OTHERS THEN

            V_ERR_MSG := SQLERRM;
            V_ERR_CODE := SQLCODE;

            BEGIN
                ROLLBACK TO SP_SAVE_CONFIRM;
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;                                                       /* 되돌림 지점을 잡기 전에 난 오류 */
            END;

            INSERT INTO SCM_SYS_LOG_BATCH
            (
                PROGRAM_NAME
              , LOG_TYPE
              , LOG_COUNT
              , LOG_MESSAGE
              , DESCRIPTION
              , EVENT_DATE
              , CREATION_DATE
              , CREATED_BY
              , LAST_UPDATE_DATE
              , LAST_UPDATED_BY
            )
            VALUES
            (
                V_PROGRAM_NAME
              , 'ERROR'
              , NULL
              , V_ERR_MSG
              , NULL
              , SYSDATE
              , SYSDATE
              , V_PROGRAM_NAME
              , SYSDATE
              , V_PROGRAM_NAME
            );

            /* error코드, errror 메시지 반환 */
            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS RESULT_CNT
                     , NULL AS CHANGE_REQ_NO
                  FROM DUAL;

            OPEN O_RC2 FOR
                SELECT '[' || TO_CHAR(V_ERR_CODE) || ']' || V_ERR_MSG AS ERR_MESSAGE
                  FROM DUAL;

    END P_SSP0060_SAVE_SHIPMENT_REQUEST_CONFIRM;

END PKG_SSP0060;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0060
-- ##### END PACKAGE BODY PKG_SSP0060

-- ##### START PACKAGE BODY PKG_SSP0200
CREATE OR REPLACE PACKAGE BODY PKG_SSP0200
IS
    /*
     * Program ID   : PKG_SSP0200
     * Description  : SSP0200 Shipment Change Request 화면 - 출하 확정 변경 요청 조회 / 작성 / 완료 / 취소
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2026.09.21                  AS-IS 프로시저 11 건 패키지 전환
     * 2026.10.06   AJS          조회 2 건(P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST · _N) 속도 개선
     *
     * [전환 공통 규칙]
     * - AS-IS 동적 SQL(문자열 조립 후 EXEC)은 칸 구성이 고정이고 조건만 갈리므로 정적 SQL + 선택 조건으로 옮겼다.
     *   AS-IS FN_GET_IN_STR 은 IN 절 리터럴을 만드는 함수라 Oracle 로 옮기지 않고 토큰 분리 조건으로 바꿨다.
     * - 사용자 TB_FX_User -> SCM_ADM_USER_M (UserID -> USER_ID · UserName -> USER_NM · UserName_E -> USER_ENG_NM)
     * - 이름 + '(' + ID + ')' 결합은 MSSQL 에서 이름이 NULL 이면 전체가 NULL 이 되므로 NVL2 로 같은 결과를 만들었다.
     * - 이관 공백(MSSQL NULL/'' 가 Oracle 공백 한 칸) 대상 칸은 TRIM 비교로 AS-IS 판정을 재현한다.
     * - MSSQL 정렬은 하이픈을 무시하고 오름차순 NULL 이 앞이므로 TRANSLATE + NULLS FIRST 로 맞췄다.
     * - 저장 계열의 '^' 구분 문자열 분리 규칙은 AS-IS SCM_ARR_SPL_CNT · SCM_ARR_SPL_VAL 과 같다.
     */

    C_DELIMITER         CONSTANT VARCHAR2(1 CHAR) := '^';

    TYPE T_TOKEN_TAB IS TABLE OF VARCHAR2(32767 CHAR) INDEX BY PLS_INTEGER;
    TYPE T_FOUND_TAB IS TABLE OF VARCHAR2(1 CHAR) INDEX BY PLS_INTEGER;

    /* ==============================================================================================
       내부 : 구분자 개수 + 1 (AS-IS SCM_ARR_SPL_CNT 와 같은 값 · CLOB 대응)
       ============================================================================================== */
    FUNCTION F_SPL_CNT
    (
        P_TEXT              IN  CLOB
    )
    RETURN PLS_INTEGER
    IS
        V_CNT               PLS_INTEGER := 1;
        V_POS               PLS_INTEGER;
    BEGIN
        IF P_TEXT IS NULL THEN
            RETURN V_CNT;
        END IF;

        V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, 1, 1);

        WHILE V_POS > 0 LOOP
            V_CNT := V_CNT + 1;
            V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, V_POS + 1, 1);
        END LOOP;

        RETURN V_CNT;
    END F_SPL_CNT;

    /* ==============================================================================================
       내부 : 앞뒤 공백을 뺀 마지막 글자 위치 (없으면 0)
       ============================================================================================== */
    FUNCTION F_LAST_NON_SPACE
    (
        P_TEXT              IN  CLOB
    )
    RETURN PLS_INTEGER
    IS
        V_POS               PLS_INTEGER;
    BEGIN
        V_POS := NVL(DBMS_LOB.GETLENGTH(P_TEXT), 0);

        WHILE V_POS > 0
          AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_POS) = ' ' LOOP
            V_POS := V_POS - 1;
        END LOOP;

        RETURN V_POS;
    END F_LAST_NON_SPACE;

    /* ==============================================================================================
       내부 : 구분 문자열을 순서대로 한 번에 분리 (AS-IS SCM_ARR_SPL_VAL 과 같은 규칙 · CLOB 대응)
              O_FOUND = 'N' 자리는 AS-IS 가 NULL 을 되돌리는 자리
       ============================================================================================== */
    PROCEDURE P_SPL_ARR
    (
        P_TEXT              IN  CLOB,
        P_CNT               IN  PLS_INTEGER,
        O_TOKEN             OUT T_TOKEN_TAB,
        O_FOUND             OUT T_FOUND_TAB
    )
    IS
        V_END               PLS_INTEGER;
        V_OFF               PLS_INTEGER := 1;
        V_POS               PLS_INTEGER;
        V_WORD              VARCHAR2(32767 CHAR);
    BEGIN
        V_END := F_LAST_NON_SPACE(P_TEXT);

        WHILE V_OFF <= V_END
          AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_OFF) = ' ' LOOP
            V_OFF := V_OFF + 1;
        END LOOP;

        FOR I IN 1 .. P_CNT LOOP
            IF P_TEXT IS NULL
            OR V_OFF > V_END + 1 THEN
                O_TOKEN(I) := NULL;
                O_FOUND(I) := 'N';
            ELSE
                V_POS := DBMS_LOB.INSTR(P_TEXT, C_DELIMITER, V_OFF, 1);

                IF V_POS = 0
                OR V_POS > V_END THEN
                    V_POS := V_END + 1;
                END IF;

                IF V_POS > V_OFF THEN
                    V_WORD := TRIM(DBMS_LOB.SUBSTR(P_TEXT, V_POS - V_OFF, V_OFF));
                ELSE
                    V_WORD := NULL;
                END IF;

                O_TOKEN(I) := V_WORD;
                O_FOUND(I) := 'Y';

                V_OFF := V_OFF + NVL(LENGTH(V_WORD), 0) + 1;

                WHILE V_OFF <= V_END
                  AND DBMS_LOB.SUBSTR(P_TEXT, 1, V_OFF) = ' ' LOOP
                    V_OFF := V_OFF + 1;
                END LOOP;
            END IF;
        END LOOP;
    END P_SPL_ARR;

    /* ==============================================================================================
       내부 : 결과 커서 (성공)
       ============================================================================================== */
    PROCEDURE P_OPEN_SUCCESS
    (
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '0'       AS CODE
                 , 'SUCCESS' AS MSG
              FROM DUAL;
    END P_OPEN_SUCCESS;

    /* ==============================================================================================
       내부 : 결과 커서 (오류)
       ============================================================================================== */
    PROCEDURE P_OPEN_ERROR
    (
        P_MESSAGE           IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    BEGIN
        OPEN O_RESULT_CURSOR FOR
            SELECT '-1'      AS CODE
                 , P_MESSAGE AS MSG
              FROM DUAL;
    END P_OPEN_ERROR;

    /* ==============================================================================================
       내부 : 오류 이력 기록 (AS-IS CATCH 의 scm_sys_log_batch INSERT)
              AS-IS 는 CATCH 안에서 바깥 트랜잭션을 확정하지만 Oracle 은 자치 트랜잭션으로 기록만 남긴다
       ============================================================================================== */
    PROCEDURE P_WRITE_ERROR_LOG
    (
        P_PROGRAM_NAME      IN  VARCHAR2,
        P_MESSAGE           IN  VARCHAR2
    )
    IS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        INSERT INTO SCM_SYS_LOG_BATCH
        (
            PROGRAM_NAME
          , LOG_TYPE
          , LOG_COUNT
          , LOG_MESSAGE
          , DESCRIPTION
          , EVENT_DATE
          , CREATION_DATE
          , CREATED_BY
          , LAST_UPDATE_DATE
          , LAST_UPDATED_BY
        )
        VALUES
        (
            P_PROGRAM_NAME
          , 'ERROR'
          , NULL
          , SUBSTR(P_MESSAGE, 1, 1000)
          , NULL
          , SYSDATE
          , SYSDATE
          , P_PROGRAM_NAME
          , SYSDATE
          , P_PROGRAM_NAME
        );

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
    END P_WRITE_ERROR_LOG;

    /* ==============================================================================================
       SSP0200_GET_SHIPMENT_CHANGE_REQUEST
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST
    (
        P_DIVISION_ID       IN  CLOB,
        P_FROM_SITE         IN  CLOB,
        P_ERP_SO_NO         IN  CLOB,
        P_ITEM_ID           IN  CLOB,
        P_FROM_YYYYMMDD     IN  VARCHAR2,
        P_TO_YYYYMMDD       IN  VARCHAR2,
        P_STATUS            IN  CLOB,
        P_CHANGE_TYPE       IN  VARCHAR2,
        P_LANGUAGE          IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        P_TO_SITE           IN  CLOB,
        P_CONFIRM_ID        IN  CLOB,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_SHIPMENT_CHANGE_REQUEST
     * Description  : Shipment Change Request
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/25   KIMYONGHO      최초작성
     * 2021/10/18   SHINMYUNGSU    SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
     * 2021/11/11   SHINMYUNGSU    조회조건 CONFIRM_ID 추가
     * 2024/10/01   KHJ            NERP_SSP
     * 2025/12/11   chkim.68       E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 동적 SQL(EXEC) -> 정적 SQL + 선택 조건 (칸 구성은 고정이고 조건만 갈린다)
     *                             - 선택 조건은 AS-IS FN_GET_IN_STR 과 같이 쉼표로 자르고 앞뒤 공백을 뺀 값으로 비교
     *                               (값이 없으면 조건 없음 · 줄바꿈은 쉼표로 바꾼 뒤 자른다)
     *                             - 이관 공백 대상 칸(SHIPMENT_STATUS · CHANGE_TYPE · ITEM_TYPE)은 TRIM 비교
     *                             - 조회 기간은 AS-IS 가 따옴표 없이 이어 붙여 숫자로 비교하지만
     *                               자리 수가 8 로 같아 문자 비교와 결과가 같다
     *                             - 이름 + ( + ID + ) 결합은 이름이 없으면 전체가 없는 값 (AS-IS 와 같음)
     * 2026.10.06   AJS          조회 속도 개선 - 행마다 부르는 함수를 스칼라 서브쿼리로 감싸 같은 값 재호출 방지 · 시장 담당자 이름(FN_GET_SSP_MKT_OWNER_NAME)을 인라인 뷰 한 번 조회로 대체
     * 2026.10.07   AJS            조회조건 Model/Nickname : 코드 또는 닉네임 부분일치·대소문자 무시
     */
        V_LANGUAGE          VARCHAR2(10 CHAR) := NVL(P_LANGUAGE, 'KO');
        V_DIVISION_YN       VARCHAR2(1 CHAR);
        V_FROM_SITE_YN      VARCHAR2(1 CHAR);
        V_ITEM_YN           VARCHAR2(1 CHAR);
        V_TO_SITE_YN        VARCHAR2(1 CHAR);
        V_ERP_SO_NO_YN      VARCHAR2(1 CHAR);
        V_CONFIRM_YN        VARCHAR2(1 CHAR);
        V_DIVISION_ID       VARCHAR2(32767 CHAR);
        V_FROM_SITE         VARCHAR2(32767 CHAR);
        V_ITEM_ID           VARCHAR2(32767 CHAR);
        V_TO_SITE           VARCHAR2(32767 CHAR);
        V_ERP_SO_NO         VARCHAR2(32767 CHAR);
        V_CONFIRM_ID        VARCHAR2(32767 CHAR);
    BEGIN
        /* AS-IS FN_GET_IN_STR : 줄바꿈을 쉼표로 바꾸고 빈 값이면 조건 없음 */
        V_DIVISION_ID := REPLACE(REPLACE(TO_CHAR(P_DIVISION_ID), CHR(13), ''), CHR(10), ',');
        V_FROM_SITE   := REPLACE(REPLACE(TO_CHAR(P_FROM_SITE), CHR(13), ''), CHR(10), ',');
        V_ITEM_ID     := REPLACE(REPLACE(TO_CHAR(P_ITEM_ID), CHR(13), ''), CHR(10), ',');
        V_TO_SITE     := REPLACE(REPLACE(TO_CHAR(P_TO_SITE), CHR(13), ''), CHR(10), ',');
        V_ERP_SO_NO   := REPLACE(REPLACE(TO_CHAR(P_ERP_SO_NO), CHR(13), ''), CHR(10), ',');
        V_CONFIRM_ID  := REPLACE(REPLACE(TO_CHAR(P_CONFIRM_ID), CHR(13), ''), CHR(10), ',');

        V_DIVISION_YN  := CASE WHEN V_DIVISION_ID IS NULL
             OR UPPER(TRIM(V_DIVISION_ID)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;
        V_FROM_SITE_YN := CASE WHEN V_FROM_SITE   IS NULL
             OR UPPER(TRIM(V_FROM_SITE)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;
        V_ITEM_YN      := CASE WHEN V_ITEM_ID     IS NULL
             OR UPPER(TRIM(V_ITEM_ID)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;
        V_TO_SITE_YN   := CASE WHEN V_TO_SITE     IS NULL
             OR UPPER(TRIM(V_TO_SITE)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;
        V_ERP_SO_NO_YN := CASE WHEN V_ERP_SO_NO   IS NULL
             OR UPPER(TRIM(V_ERP_SO_NO)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;
        V_CONFIRM_YN   := CASE WHEN V_CONFIRM_ID  IS NULL
             OR UPPER(TRIM(V_CONFIRM_ID)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;

        OPEN O_RC1 FOR
            SELECT SA.DIVISION_ID
                 , SA.ERP_SO_NO
                 , SA.SHIPMENT_STATUS
                 , SA.PROJECT_CODE
                 , SA.PROJECT_NAME
                 , SA.FCST_TYPE
                 , SA.ITEM_ID
                 , SA.NICK_NAME
                 , SA.SHIPMENT_DATE
                 , SA.BEFORE_QTY
                 , SA.SHIPMENT_CONFIRM_QTY
                 , SA.REMARKS
                 , SA.REMARKS2
                 , SA.REMARKS3
                 , SA.FROM_SITE
                 , SA.OPERATION_GROUP
                 , SA.FROM_SITE_DESCRIPTION
                 , SA.TO_SITE
                 , SA.TO_SITE_DESCRIPTION
                 , SA.TO_SITE_SOLDTO_CODE
                 , SA.TO_SITE_SHIPTO_CODE
                 , SA.SOLDTO_DESCRIPTION
                 , SA.SHIPTO_DESCRIPTION
                 , SA.BOD_ID
                 , SA.INCOTERMS
                 , SA.TRANSPORT_MODE
                 , SA.LT_DAY
                 , SA.ETD
                 , SA.ETA
                 , SA.EXPECTED_SHIPPING_DATE
                 , SA.CONFIRM_ID
                 , SA.UPDATED_BY
                 , SA.UPDATED_DATE
                 , SA.ERP_STATUS
                 , SA.CHANGE_TYPE
                 , SA.NEW_ROUTE_ID
                 , SA.NEW_BOD_ID
                 , SA.NEW_INCOTERMS
                 , SA.NEW_D_COUNTRY
                 , SA.NEW_D_PORT_CODE
                 , SA.NEW_A_COUNTRY
                 , SA.NEW_A_PORT_CODE
                 , SA.NEW_CUSTOMER_LT
                 , SA.NEW_TO_COUNTRY
                 , SA.NEW_TO_CITY
                 , SA.NEW_ETA
                 , SA.NEW_ETD
                 , SA.NEW_LT_DAY
                 , SA.NEW_TRANSPORT_MODE
                 , SA.NEW_SHIPMENT_DATE
                 , SA.EDIT_REMARKS
                 , SA.EDIT_MAIN
                 , SA.CHECK_NEED_YN
                 , SA.END_CUSTOMER
                 , SA.ELECTRODE_YN
                 , SA.ELECTRODE_TYPE
                 , SA.ORIGIN_FROM_DIVISION_ID
                 , SA.ORIGIN_TO_DIVISION_ID
                 , SA.CHANGE_REQ_NO
                 , SA.MODEL_USER
                 , SA.MTK_OWNER
                 , SA.REQUESTOR
                 , SA.CHANGE_REASON_CODE
                 , SA.CHANGE_REASON_DETAIL
                 , SA.ATTRIBUTE10
                 , SA.REQUEST_DATE
                 , SA.ERP_ATTR1
                 , SA.ERP_ATTR2
                 , SA.ERP_ATTR3
              FROM (SELECT A.DIVISION_ID
                         , A.ERP_SO_NO
                         , A.SHIPMENT_STATUS
                         , A.PROJECT_CODE
--                         , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME    --  2026.10.06 AJS
                         , (SELECT FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) FROM DUAL) AS PROJECT_NAME    --  2026.10.06 AJS
                         , A.FCST_TYPE
                         , A.ITEM_ID
--                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME    --  2026.10.06 AJS
                         , (SELECT FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) FROM DUAL) AS NICK_NAME    --  2026.10.06 AJS
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                         , A.BEFORE_QTY
                         , ROUND(A.QTY, 3) AS SHIPMENT_CONFIRM_QTY                  /* E20250922-000093 출하계획 소수점 입력 */
                         , A.REMARKS
                         , A.REMARKS2
                         , A.REMARKS3
                         , A.FROM_SITE
                         , L.OPERATION_GROUP                                        /* E20250922-000093 출하계획 소수점 입력 */
--                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , NVL((SELECT FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE) FROM DUAL), '-') AS FROM_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , A.TO_SITE
--                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , NVL((SELECT FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE) FROM DUAL), '-') AS TO_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , A.TO_SITE_SOLDTO_CODE
                         , A.TO_SITE_SHIPTO_CODE
--                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
                         , (SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') FROM DUAL) AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
--                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , (SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') FROM DUAL) AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , A.BOD_ID
                         , D.SSP_INCOTERMS AS INCOTERMS
                         , D.TRANSPORT_MODE
                         , D.LT_TOTAL AS LT_DAY
                         , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                         , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                         , CASE WHEN D.TRANSPORT_MODE = 'TRK' THEN '-'
--                                ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                                ELSE TO_CHAR(TO_DATE((SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) FROM DUAL), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                           END AS EXPECTED_SHIPPING_DATE
                         , A.CONFIRM_ID
                         , CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM ELSE E.USER_ENG_NM END
                           || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM ELSE E.USER_ENG_NM END, '(' || A.LAST_UPDATED_BY || ')', NULL) AS UPDATED_BY
                         , CASE WHEN E.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                         , A.ERP_STATUS
                         , A.CHANGE_TYPE
                         , A.ROUTE_ID AS NEW_ROUTE_ID
                         , A.BOD_ID AS NEW_BOD_ID
                         , D.SSP_INCOTERMS AS NEW_INCOTERMS
                         , A.D_COUNTRY AS NEW_D_COUNTRY
                         , A.D_PORT_CODE AS NEW_D_PORT_CODE
                         , A.A_COUNTRY AS NEW_A_COUNTRY
                         , A.A_PORT_CODE AS NEW_A_PORT_CODE
                         , A.CUSTOMER_LT AS NEW_CUSTOMER_LT
                         , A.TO_COUNTRY AS NEW_TO_COUNTRY
                         , A.TO_CITY AS NEW_TO_CITY
                         , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                         , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                         , D.LT_TOTAL AS NEW_LT_DAY
                         , D.TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                         , 'N' AS EDIT_REMARKS
                         , 'N' AS EDIT_MAIN
                         , NVL(A.CHECK_NEED_YN, 'N') AS CHECK_NEED_YN
                         , NVL(CASE WHEN A.DIVISION_ID = '40' THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-' THEN A.PROJECT_CODE ELSE IA.PROJECT_CODE END
                                    WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40' THEN IA.PROJECT_CODE
                                    ELSE F.END_CUSTOMER
                               END, '/') AS END_CUSTOMER
                         , A.ELECTRODE_YN
                         , A.ELECTRODE_TYPE
                         , A.ORIGIN_FROM_DIVISION_ID
                         , A.ORIGIN_TO_DIVISION_ID
                         , XA.CHANGE_REQ_NO
                         , CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END
                           || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END, '(' || G.USER_ID || ')', NULL) AS MODEL_USER
--                         , FN_GET_SSP_MKT_OWNER_NAME(J.OWNER, ',', V_LANGUAGE) AS MTK_OWNER    --  2026.10.06 AJS
                         , TO_CLOB(CASE WHEN V_LANGUAGE = 'KO' THEN IB.OWNER_NAME_KO ELSE IB.OWNER_NAME_EN END) AS MTK_OWNER    --  2026.10.06 AJS
                         , CASE WHEN A.LAST_UPDATED_BY = 'ssp_batch' THEN 'System'
                                ELSE CASE WHEN V_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END
                                     || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END, '(' || A.LAST_UPDATED_BY || ')', NULL)
                           END AS REQUESTOR
                         , '-' AS CHANGE_REASON_CODE
                         , NULL AS CHANGE_REASON_DETAIL                             /* AS-IS 는 빈 문자 */
                         , A.ATTRIBUTE10
                         , A.LAST_UPDATE_DATE AS REQUEST_DATE
                         , A.ERP_ATTR1                                              /* 20211018 SHINMYUNGSU 열람항목추가 */
                         , A.ERP_ATTR2
                         , A.ERP_ATTR3
                      FROM SSP_ANL_SHIP_CONFIRM           A
                         , SCM_MST_ITEM_SN                B
                         , SCM_MST_SITE                   C
                         , SCP_MST_BOD_N_V                D
                         , SCM_ADM_USER_M                 E
                         , SCM_MST_SITE                   F
                         , (SELECT DIVISION_ID
                                 , PROJECT_CODE
                                 , SCM_SITE_ID
                                 , ITEM_ID
                              FROM (SELECT DIVISION_ID
                                         , PROJECT_CODE
                                         , SCM_SITE_ID
                                         , ITEM_ID
                                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                      FROM SCM_MST_SITE_ITEM)
                             WHERE NUM = 1)              IA
                         , (SELECT CONFIRM_ID
                                 , CHANGE_REQ_NO
                              FROM (SELECT CONFIRM_ID
                                         , CHANGE_REQ_NO
                                         , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC) AS NUM
                                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                     WHERE VALID_YN = 'Y')
                             WHERE NUM = 1)              XA
                         , SSP_MST_MODEL_USER             G
                         , SCM_ADM_USER_M                 H
                         , SCM_ADM_USER_M                 I
                         , SCM_MST_SITE_ITEM              J
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ   K
                         , SCP_MST_FINAL_ITEM_V           L
-- 2026.10.06 AJS 시장 담당자 이름을 한 번에 구하는 인라인 뷰 (START)
                         , (SELECT XB.OWNER
                                 , LISTAGG(CASE WHEN XB.TOKEN_NO = 1 AND XB.TOKEN_CNT >= 3 THEN LTRIM(XB.NAME_KO) ELSE XB.NAME_KO END, ',') WITHIN GROUP (ORDER BY XB.TOKEN_NO) AS OWNER_NAME_KO
                                 , LISTAGG(CASE WHEN XB.TOKEN_NO = 1 AND XB.TOKEN_CNT >= 3 THEN LTRIM(XB.NAME_EN) ELSE XB.NAME_EN END, ',') WITHIN GROUP (ORDER BY XB.TOKEN_NO) AS OWNER_NAME_EN
                              FROM (SELECT XC.OWNER
                                         , XC.TOKEN_NO
                                         , XC.TOKEN_CNT
                                         , NVL2(M.USER_ID, M.USER_NAME || '(' || M.USER_ID || ')', '(' || XC.TOKEN || ')') AS NAME_KO
                                         , NVL2(M.USER_ID, M.USER_NAME_EN || '(' || M.USER_ID || ')', '(' || XC.TOKEN || ')') AS NAME_EN
                                      FROM (SELECT XD.OWNER
                                                 , XE.TOKEN_NO
                                                 , XD.TOKEN_CNT
                                                 , TRIM(SUBSTR(',' || XD.OWNER || ','
                                                             , INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO) + 1
                                                             , INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO + 1) - INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO) - 1)) AS TOKEN
                                              FROM (SELECT DISTINCT OWNER
                                                         , LENGTH(OWNER) - NVL(LENGTH(REPLACE(OWNER, ',')), 0) + 1 AS TOKEN_CNT
                                                      FROM SCM_MST_SITE_ITEM
                                                     WHERE TRIM(OWNER) IS NOT NULL) XD
                                                 , (SELECT LEVEL AS TOKEN_NO
                                                      FROM DUAL
                                                   CONNECT BY LEVEL <= 101) XE
                                             WHERE XE.TOKEN_NO <= XD.TOKEN_CNT) XC
                                         , SCM_MST_SSO_USER_INFO M
                                     WHERE UPPER(M.USER_ID(+)) = UPPER(XC.TOKEN)) XB
                             GROUP BY XB.OWNER)          IB
-- 2026.10.06 AJS 시장 담당자 이름을 한 번에 구하는 인라인 뷰 (END)
                     WHERE B.ITEM_ID             = A.ITEM_ID
                       AND B.DIVISION_ID         = A.DIVISION_ID
                       AND B.COMPANY_ID          = A.FROM_SITE_COMPANY_ID
                       AND TRIM(B.ITEM_TYPE)     NOT IN ('R')                       /* 2025-05-15 Q인 경우도 화면에서 조회되어야 함 */
                       AND C.DIVISION_ID         = A.DIVISION_ID
                       AND C.SCM_SITE_ID         = A.FROM_SITE
                       AND C.SITE_TYPE           = 'PLANT'
                       AND D.DIVISION_ID         = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND D.BOD_ID              = A.BOD_ID
                       AND E.USER_ID(+)          = A.LAST_UPDATED_BY
                       AND E.USE_YN(+)           = 'Y'
                       AND F.DIVISION_ID(+)      = A.ORIGIN_TO_DIVISION_ID
                       AND F.SCM_SITE_ID(+)      = A.TO_SITE
                       AND F.VALID_YN(+)         = 'Y'
                       AND IA.DIVISION_ID(+)     = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND IA.SCM_SITE_ID(+)     = A.TO_SITE
                       AND IA.ITEM_ID(+)         = A.ITEM_ID
                       AND XA.CONFIRM_ID(+)      = A.CONFIRM_ID
                       AND G.DIVISION_ID(+)      = A.ORIGIN_FROM_DIVISION_ID
                       AND G.FROM_SITE(+)        = A.FROM_SITE
                       AND G.ITEM_ID(+)          = A.ITEM_ID
                       AND G.VALID_YN(+)         = 'Y'
                       AND H.USER_ID(+)          = G.USER_ID
                       AND H.USE_YN(+)           = 'Y'
                       AND I.USER_ID(+)          = A.LAST_UPDATED_BY
                       AND I.USE_YN(+)           = 'Y'
                       AND J.DIVISION_ID(+)      = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND J.SCM_SITE_ID(+)      = A.TO_SITE
                       AND J.ITEM_ID(+)          = A.ITEM_ID
                       AND J.PROJECT_CODE(+)     = A.PROJECT_CODE
                       AND K.CHANGE_REQ_NO(+)    = XA.CHANGE_REQ_NO
                       AND IB.OWNER(+)           = J.OWNER    --  2026.10.06 AJS
                       AND L.ITEM_ID(+)          = A.ITEM_ID                        /* E20250922-000093 출하계획 소수점 입력 */
                       AND A.YYYYMMDD           >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD           <= P_TO_YYYYMMDD
                       AND (V_DIVISION_YN = 'N'
                        OR  A.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
/* 2026.10.07 AJS Model/Nickname 검색 (START) */
--                       AND (V_ITEM_YN = 'N'
--                        OR  UPPER(A.ITEM_ID) IN (SELECT UPPER(COLUMN_VALUE)
--                                                   FROM TABLE(STRING_SPLIT(V_ITEM_ID, ','))))
                       AND (V_ITEM_YN = 'N'
                        OR  EXISTS (SELECT 1
                                      FROM TABLE(STRING_SPLIT(V_ITEM_ID, ',')) SB
                                     WHERE SB.COLUMN_VALUE IS NOT NULL
                                       AND (UPPER(A.ITEM_ID) LIKE '%' || UPPER(TRIM(SB.COLUMN_VALUE)) || '%'
                                         OR UPPER(B.NICK_NAME) LIKE '%' || UPPER(TRIM(SB.COLUMN_VALUE)) || '%')))
/* 2026.10.07 AJS Model/Nickname 검색 (END) */
                       AND (V_FROM_SITE_YN = 'N'
                        OR  UPPER(A.FROM_SITE) IN (SELECT UPPER(COLUMN_VALUE)
                                                     FROM TABLE(STRING_SPLIT(V_FROM_SITE, ','))))
                       AND (V_TO_SITE_YN = 'N'
                        OR  UPPER(A.TO_SITE) IN (SELECT UPPER(COLUMN_VALUE)
                                                   FROM TABLE(STRING_SPLIT(V_TO_SITE, ','))))
                       AND (V_ERP_SO_NO_YN = 'N'
                        OR  UPPER(A.ERP_SO_NO) IN (SELECT UPPER(COLUMN_VALUE)
                                                     FROM TABLE(STRING_SPLIT(V_ERP_SO_NO, ','))))
                       AND TRIM(A.SHIPMENT_STATUS) IS NOT NULL
                       AND A.QTY                 > 0
                       AND TRIM(A.CHANGE_TYPE)   <> 'N'
                       AND A.CONFIRM_ID          LIKE 'C%'
                       AND (V_CONFIRM_YN = 'N'
                        OR  UPPER(A.CONFIRM_ID) IN (SELECT UPPER(COLUMN_VALUE)
                                                      FROM TABLE(STRING_SPLIT(V_CONFIRM_ID, ','))))) SA
             ORDER BY SA.DIVISION_ID NULLS FIRST
                    , SA.SHIPMENT_STATUS NULLS FIRST
                    , SA.SHIPMENT_DATE NULLS FIRST
                    , UPPER(TRANSLATE(SA.ITEM_ID, '_-', '/')) NULLS FIRST
                    , SA.ITEM_ID NULLS FIRST
                    , SA.ERP_SO_NO DESC NULLS LAST
                    , UPPER(TRANSLATE(SA.FROM_SITE, '_-', '/')) NULLS FIRST
                    , SA.FROM_SITE NULLS FIRST
                    , UPPER(TRANSLATE(SA.TO_SITE, '_-', '/')) NULLS FIRST
                    , SA.TO_SITE NULLS FIRST
                    , UPPER(TRANSLATE(SA.PROJECT_CODE, '_-', '/')) NULLS FIRST
                    , SA.PROJECT_CODE NULLS FIRST
                    , UPPER(TRANSLATE(SA.FCST_TYPE, '_-', '/')) NULLS FIRST
                    , SA.FCST_TYPE NULLS FIRST;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_SHIPMENT_CHANGE_REQUEST', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST;

    /* ==============================================================================================
       SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N
    (
        P_DIVISION_ID       IN  CLOB,
        P_FROM_SITE         IN  CLOB,
        P_ERP_SO_NO         IN  CLOB,
        P_ITEM_ID           IN  CLOB,
        P_FROM_YYYYMMDD     IN  VARCHAR2,
        P_TO_YYYYMMDD       IN  VARCHAR2,
        P_STATUS            IN  CLOB,
        P_CHANGE_TYPE       IN  VARCHAR2,
        P_LANGUAGE          IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        P_TO_SITE           IN  CLOB,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N
     * Description  : Shipment Change Request
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/25   KIMYONGHO      최초작성
     * 2021/10/18   SHINMYUNGSU    SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
     * 2025/12/11   chkim.68       E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 동적 SQL(EXEC) -> 정적 SQL + 선택 조건
     *                             - AS-IS 에서 모델 · 출발지 조건은 주석이라 사업부 조건만 살아 있다
     *                             - 요청자 이름은 REQUESTOR 칸 기준 (변경 요청 조회는 최종변경자 기준)
     * 2026.10.06   AJS          조회 속도 개선 - 행마다 부르는 함수를 스칼라 서브쿼리로 감싸 같은 값 재호출 방지 · 시장 담당자 이름(FN_GET_SSP_MKT_OWNER_NAME)을 인라인 뷰 한 번 조회로 대체
     */
        V_LANGUAGE          VARCHAR2(10 CHAR) := NVL(P_LANGUAGE, 'KO');
        V_DIVISION_YN       VARCHAR2(1 CHAR);
        V_DIVISION_ID       VARCHAR2(32767 CHAR);
    BEGIN
        V_DIVISION_ID := REPLACE(REPLACE(TO_CHAR(P_DIVISION_ID), CHR(13), ''), CHR(10), ',');
        V_DIVISION_YN := CASE WHEN V_DIVISION_ID IS NULL
             OR UPPER(TRIM(V_DIVISION_ID)) = 'ALL'   /* 조회조건 ALL 은 조건 없음 */
             THEN 'N' ELSE 'Y' END;

        OPEN O_RC1 FOR
            SELECT SA.DIVISION_ID
                 , SA.ERP_SO_NO
                 , SA.SHIPMENT_STATUS
                 , SA.PROJECT_CODE
                 , SA.PROJECT_NAME
                 , SA.FCST_TYPE
                 , SA.ITEM_ID
                 , SA.NICK_NAME
                 , SA.SHIPMENT_DATE
                 , SA.BEFORE_QTY
                 , SA.SHIPMENT_CONFIRM_QTY
                 , SA.REMARKS
                 , SA.REMARKS2
                 , SA.REMARKS3
                 , SA.FROM_SITE
                 , SA.FROM_SITE_DESCRIPTION
                 , SA.TO_SITE
                 , SA.TO_SITE_DESCRIPTION
                 , SA.TO_SITE_SOLDTO_CODE
                 , SA.TO_SITE_SHIPTO_CODE
                 , SA.SOLDTO_DESCRIPTION
                 , SA.SHIPTO_DESCRIPTION
                 , SA.BOD_ID
                 , SA.INCOTERMS
                 , SA.TRANSPORT_MODE
                 , SA.LT_DAY
                 , SA.ETD
                 , SA.ETA
                 , SA.EXPECTED_SHIPPING_DATE
                 , SA.CONFIRM_ID
                 , SA.UPDATED_BY
                 , SA.UPDATED_DATE
                 , SA.ERP_STATUS
                 , SA.CHANGE_TYPE
                 , SA.NEW_ROUTE_ID
                 , SA.NEW_BOD_ID
                 , SA.NEW_INCOTERMS
                 , SA.NEW_D_COUNTRY
                 , SA.NEW_D_PORT_CODE
                 , SA.NEW_A_COUNTRY
                 , SA.NEW_A_PORT_CODE
                 , SA.NEW_CUSTOMER_LT
                 , SA.NEW_TO_COUNTRY
                 , SA.NEW_TO_CITY
                 , SA.NEW_ETA
                 , SA.NEW_ETD
                 , SA.NEW_LT_DAY
                 , SA.NEW_TRANSPORT_MODE
                 , SA.NEW_SHIPMENT_DATE
                 , SA.EDIT_REMARKS
                 , SA.EDIT_MAIN
                 , SA.CHECK_NEED_YN
                 , SA.END_CUSTOMER
                 , SA.ELECTRODE_YN
                 , SA.ELECTRODE_TYPE
                 , SA.ORIGIN_FROM_DIVISION_ID
                 , SA.ORIGIN_TO_DIVISION_ID
                 , SA.CHANGE_REQ_NO
                 , SA.MODEL_USER
                 , SA.MTK_OWNER
                 , SA.REQUESTOR
                 , SA.CHANGE_REASON_CODE
                 , SA.CHANGE_REASON_DETAIL
                 , SA.ATTRIBUTE10
                 , SA.ERP_ATTR1
                 , SA.ERP_ATTR2
                 , SA.ERP_ATTR3
              FROM (SELECT A.DIVISION_ID
                         , A.ERP_SO_NO
                         , A.SHIPMENT_STATUS
                         , A.PROJECT_CODE
--                         , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME    --  2026.10.06 AJS
                         , (SELECT FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) FROM DUAL) AS PROJECT_NAME    --  2026.10.06 AJS
                         , A.FCST_TYPE
                         , A.ITEM_ID
--                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME    --  2026.10.06 AJS
                         , (SELECT FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) FROM DUAL) AS NICK_NAME    --  2026.10.06 AJS
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                         , A.BEFORE_QTY
                         , ROUND(A.QTY, 3) AS SHIPMENT_CONFIRM_QTY                  /* E20250922-000093 출하계획 소수점 입력 */
                         , A.REMARKS
                         , A.REMARKS2
                         , A.REMARKS3
                         , A.FROM_SITE
--                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , NVL((SELECT FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE) FROM DUAL), '-') AS FROM_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , A.TO_SITE
--                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , NVL((SELECT FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE) FROM DUAL), '-') AS TO_SITE_DESCRIPTION    --  2026.10.06 AJS
                         , A.TO_SITE_SOLDTO_CODE
                         , A.TO_SITE_SHIPTO_CODE
--                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
                         , (SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') FROM DUAL) AS SOLDTO_DESCRIPTION    --  2026.10.06 AJS
--                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , (SELECT FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') FROM DUAL) AS SHIPTO_DESCRIPTION    --  2026.10.06 AJS
                         , A.BOD_ID
                         , D.SSP_INCOTERMS AS INCOTERMS
                         , D.TRANSPORT_MODE
                         , D.LT_TOTAL AS LT_DAY
                         , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                         , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                         , CASE WHEN D.TRANSPORT_MODE = 'TRK' THEN '-'
--                                ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                                ELSE TO_CHAR(TO_DATE((SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) FROM DUAL), 'YYYYMMDD'), 'YYYY-MM-DD')    --  2026.10.06 AJS
                           END AS EXPECTED_SHIPPING_DATE
                         , A.CONFIRM_ID
                         , CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM ELSE E.USER_ENG_NM END
                           || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN E.USER_NM ELSE E.USER_ENG_NM END, '(' || A.LAST_UPDATED_BY || ')', NULL) AS UPDATED_BY
                         , CASE WHEN E.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE ELSE NULL END AS UPDATED_DATE
                         , A.ERP_STATUS
                         , A.CHANGE_TYPE
                         , A.ROUTE_ID AS NEW_ROUTE_ID
                         , A.BOD_ID AS NEW_BOD_ID
                         , D.SSP_INCOTERMS AS NEW_INCOTERMS
                         , A.D_COUNTRY AS NEW_D_COUNTRY
                         , A.D_PORT_CODE AS NEW_D_PORT_CODE
                         , A.A_COUNTRY AS NEW_A_COUNTRY
                         , A.A_PORT_CODE AS NEW_A_PORT_CODE
                         , A.CUSTOMER_LT AS NEW_CUSTOMER_LT
                         , A.TO_COUNTRY AS NEW_TO_COUNTRY
                         , A.TO_CITY AS NEW_TO_CITY
                         , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                         , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                         , D.LT_TOTAL AS NEW_LT_DAY
                         , D.TRANSPORT_MODE AS NEW_TRANSPORT_MODE
                         , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                         , 'N' AS EDIT_REMARKS
                         , 'N' AS EDIT_MAIN
                         , NVL(A.CHECK_NEED_YN, 'N') AS CHECK_NEED_YN
                         , NVL(CASE WHEN A.DIVISION_ID = '40' THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE <> '-' THEN A.PROJECT_CODE ELSE IA.PROJECT_CODE END
                                    WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40' THEN IA.PROJECT_CODE
                                    ELSE F.END_CUSTOMER
                               END, '/') AS END_CUSTOMER
                         , A.ELECTRODE_YN
                         , A.ELECTRODE_TYPE
                         , A.ORIGIN_FROM_DIVISION_ID
                         , A.ORIGIN_TO_DIVISION_ID
                         , XA.CHANGE_REQ_NO
                         , CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END
                           || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN H.USER_NM ELSE H.USER_ENG_NM END, '(' || G.USER_ID || ')', NULL) AS MODEL_USER
--                         , FN_GET_SSP_MKT_OWNER_NAME(J.OWNER, ',', V_LANGUAGE) AS MTK_OWNER    --  2026.10.06 AJS
                         , TO_CLOB(CASE WHEN V_LANGUAGE = 'KO' THEN IB.OWNER_NAME_KO ELSE IB.OWNER_NAME_EN END) AS MTK_OWNER    --  2026.10.06 AJS
                         , CASE WHEN V_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END
                           || NVL2(CASE WHEN V_LANGUAGE = 'KO' THEN I.USER_NM ELSE I.USER_ENG_NM END, '(' || A.REQUESTOR || ')', NULL) AS REQUESTOR
                         , '-' AS CHANGE_REASON_CODE
                         , NULL AS CHANGE_REASON_DETAIL                             /* AS-IS 는 빈 문자 */
                         , A.ATTRIBUTE10
                         , A.ERP_ATTR1                                              /* 20211018 SHINMYUNGSU 열람항목추가 */
                         , A.ERP_ATTR2
                         , A.ERP_ATTR3
                      FROM SSP_ANL_SHIP_CONFIRM           A
                         , SCM_MST_SITE                   C
                         , SCP_MST_BOD_N_V                D
                         , SCM_ADM_USER_M                 E
                         , SCM_MST_SITE                   F
                         , (SELECT DIVISION_ID
                                 , PROJECT_CODE
                                 , SCM_SITE_ID
                                 , ITEM_ID
                              FROM (SELECT DIVISION_ID
                                         , PROJECT_CODE
                                         , SCM_SITE_ID
                                         , ITEM_ID
                                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                      FROM SCM_MST_SITE_ITEM)
                             WHERE NUM = 1)              IA
                         , (SELECT CONFIRM_ID
                                 , CHANGE_REQ_NO
                              FROM (SELECT CONFIRM_ID
                                         , CHANGE_REQ_NO
                                         , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC) AS NUM
                                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                     WHERE VALID_YN = 'Y')
                             WHERE NUM = 1)              XA
                         , SSP_MST_MODEL_USER             G
                         , SCM_ADM_USER_M                 H
                         , SCM_ADM_USER_M                 I
                         , SCM_MST_SITE_ITEM              J
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ   K
-- 2026.10.06 AJS 시장 담당자 이름을 한 번에 구하는 인라인 뷰 (START)
                         , (SELECT XB.OWNER
                                 , LISTAGG(CASE WHEN XB.TOKEN_NO = 1 AND XB.TOKEN_CNT >= 3 THEN LTRIM(XB.NAME_KO) ELSE XB.NAME_KO END, ',') WITHIN GROUP (ORDER BY XB.TOKEN_NO) AS OWNER_NAME_KO
                                 , LISTAGG(CASE WHEN XB.TOKEN_NO = 1 AND XB.TOKEN_CNT >= 3 THEN LTRIM(XB.NAME_EN) ELSE XB.NAME_EN END, ',') WITHIN GROUP (ORDER BY XB.TOKEN_NO) AS OWNER_NAME_EN
                              FROM (SELECT XC.OWNER
                                         , XC.TOKEN_NO
                                         , XC.TOKEN_CNT
                                         , NVL2(M.USER_ID, M.USER_NAME || '(' || M.USER_ID || ')', '(' || XC.TOKEN || ')') AS NAME_KO
                                         , NVL2(M.USER_ID, M.USER_NAME_EN || '(' || M.USER_ID || ')', '(' || XC.TOKEN || ')') AS NAME_EN
                                      FROM (SELECT XD.OWNER
                                                 , XE.TOKEN_NO
                                                 , XD.TOKEN_CNT
                                                 , TRIM(SUBSTR(',' || XD.OWNER || ','
                                                             , INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO) + 1
                                                             , INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO + 1) - INSTR(',' || XD.OWNER || ',', ',', 1, XE.TOKEN_NO) - 1)) AS TOKEN
                                              FROM (SELECT DISTINCT OWNER
                                                         , LENGTH(OWNER) - NVL(LENGTH(REPLACE(OWNER, ',')), 0) + 1 AS TOKEN_CNT
                                                      FROM SCM_MST_SITE_ITEM
                                                     WHERE TRIM(OWNER) IS NOT NULL) XD
                                                 , (SELECT LEVEL AS TOKEN_NO
                                                      FROM DUAL
                                                   CONNECT BY LEVEL <= 101) XE
                                             WHERE XE.TOKEN_NO <= XD.TOKEN_CNT) XC
                                         , SCM_MST_SSO_USER_INFO M
                                     WHERE UPPER(M.USER_ID(+)) = UPPER(XC.TOKEN)) XB
                             GROUP BY XB.OWNER)          IB
-- 2026.10.06 AJS 시장 담당자 이름을 한 번에 구하는 인라인 뷰 (END)
                     WHERE C.DIVISION_ID         = A.DIVISION_ID
                       AND C.SCM_SITE_ID         = A.FROM_SITE
                       AND C.SITE_TYPE           = 'PLANT'
                       AND D.DIVISION_ID         = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND D.BOD_ID              = A.BOD_ID
                       AND E.USER_ID(+)          = A.LAST_UPDATED_BY
                       AND E.USE_YN(+)           = 'Y'
                       AND F.DIVISION_ID(+)      = A.ORIGIN_TO_DIVISION_ID
                       AND F.SCM_SITE_ID(+)      = A.TO_SITE
                       AND F.VALID_YN(+)         = 'Y'
                       AND IA.DIVISION_ID(+)     = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND IA.SCM_SITE_ID(+)     = A.TO_SITE
                       AND IA.ITEM_ID(+)         = A.ITEM_ID
                       AND XA.CONFIRM_ID(+)      = A.CONFIRM_ID
                       AND G.DIVISION_ID(+)      = A.ORIGIN_FROM_DIVISION_ID
                       AND G.FROM_SITE(+)        = A.FROM_SITE
                       AND G.ITEM_ID(+)          = A.ITEM_ID
                       AND G.VALID_YN(+)         = 'Y'
                       AND H.USER_ID(+)          = G.USER_ID
                       AND H.USE_YN(+)           = 'Y'
                       AND I.USER_ID(+)          = A.REQUESTOR
                       AND I.USE_YN(+)           = 'Y'
                       AND J.DIVISION_ID(+)      = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND J.SCM_SITE_ID(+)      = A.TO_SITE
                       AND J.ITEM_ID(+)          = A.ITEM_ID
                       AND J.PROJECT_CODE(+)     = A.PROJECT_CODE
                       AND K.CHANGE_REQ_NO(+)    = XA.CHANGE_REQ_NO
                       AND IB.OWNER(+)           = J.OWNER    --  2026.10.06 AJS
                       AND A.YYYYMMDD           >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD           <= P_TO_YYYYMMDD
                       AND (V_DIVISION_YN = 'N'
                        OR  A.DIVISION_ID IN (SELECT COLUMN_VALUE
                                                FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ','))))
                       AND TRIM(A.SHIPMENT_STATUS) IS NOT NULL
                       AND A.QTY                 > 0
                       AND A.CHANGE_TYPE         = 'N'
                       AND A.SHIPMENT_STATUS     = 'C'
                       AND A.CONFIRM_ID          LIKE 'C%') SA
             ORDER BY SA.DIVISION_ID NULLS FIRST
                    , SA.SHIPMENT_STATUS NULLS FIRST
                    , SA.SHIPMENT_DATE NULLS FIRST
                    , UPPER(TRANSLATE(SA.ITEM_ID, '_-', '/')) NULLS FIRST
                    , SA.ITEM_ID NULLS FIRST
                    , SA.ERP_SO_NO DESC NULLS LAST
                    , UPPER(TRANSLATE(SA.FROM_SITE, '_-', '/')) NULLS FIRST
                    , SA.FROM_SITE NULLS FIRST
                    , UPPER(TRANSLATE(SA.TO_SITE, '_-', '/')) NULLS FIRST
                    , SA.TO_SITE NULLS FIRST
                    , UPPER(TRANSLATE(SA.PROJECT_CODE, '_-', '/')) NULLS FIRST
                    , SA.PROJECT_CODE NULLS FIRST
                    , UPPER(TRANSLATE(SA.FCST_TYPE, '_-', '/')) NULLS FIRST
                    , SA.FCST_TYPE NULLS FIRST;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N;

    /* ==============================================================================================
       SSP0200_GET_SHIPMENT_REQUEST_DRAFTING
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_SHIPMENT_REQUEST_DRAFTING
    (
        P_DIVISION_ID       IN  CLOB,
        P_FROM_SITE         IN  CLOB,
        P_TO_SITE           IN  CLOB,
        P_ERP_SO_NO         IN  CLOB,
        P_ITEM_ID           IN  CLOB,
        P_BOD_ID            IN  CLOB,
        P_INCOTERMS         IN  CLOB,
        P_TRANSPORT_MODE    IN  CLOB,
        P_PROJECT_CODE      IN  CLOB,
        P_FCST_TYPE         IN  CLOB,
        P_CONFIRM_ID        IN  CLOB,
        P_FROM_YYYYMMDD     IN  VARCHAR2,
        P_TO_YYYYMMDD       IN  VARCHAR2,
        P_CHANGE_REQUEST_NO IN  VARCHAR2,
        P_REQUEST_USER_ID   IN  VARCHAR2,
        P_REQUEST_STATUS    IN  VARCHAR2,
        P_LANGUAGE          IN  VARCHAR2,
        P_CHANGE_TYPE       IN  VARCHAR2,
        P_DEBUG_MODE        IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RC2               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_SHIPMENT_REQUEST_DRAFTING
     * Description  : Shipment Change Request 작성중
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/26  KIMYONGHO       최초작성
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 임시 테이블(#Tmp)은 결과 커서와 담당자 조회 두 곳에서만 읽으므로
     *                               같은 인라인 뷰를 두 번 두어 임시 테이블 없이 옮겼다
     *                             - 임시 테이블 INSERT 의 정렬을 결과 커서의 정렬로 옮겼다
     *                             - 담당자 조회 TOP 1 -> ROWNUM = 1 (AS-IS 도 정렬이 없어 임의 1 행)
     *                             - AS-IS 조회 기간 · 요청 번호 · 상태 조건은 주석이라 살아 있지 않다
     */
        V_LANGUAGE          VARCHAR2(10 CHAR) := NVL(P_LANGUAGE, 'KO');
    BEGIN
        OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.ERP_SO_NO
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE
                        ELSE FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE)
                   END AS PROJECT_NAME
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                 , A.TO_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-') AS TO_SITE_DESCRIPTION
                 , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                 , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                 , B.SSP_INCOTERMS AS INCOTERMS                                     /* 2020/09/21 KIMYONGHO SSP INCOTERMS 변경 작업 */
                 , CASE WHEN A.NEW_YN = 'Y' THEN '-' ELSE B.TRANSPORT_MODE END AS TRANSPORT_MODE
                 , CASE WHEN A.NEW_YN = 'Y' THEN '-'
                        ELSE CASE WHEN A.YYYYMMDD IS NULL THEN NULL
                                  ELSE TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')
                             END
                   END AS SHIPMENT_DATE
                 , CASE WHEN A.NEW_YN = 'Y' THEN 0 ELSE A.QTY END AS SHIPMENT_CONFIRM_QTY
                 , A.BOD_ID
                 , CASE WHEN A.NEW_YN = 'Y' THEN 0 ELSE B.LT_TOTAL END AS LT_DAY
                 , CASE WHEN A.NEW_YN = 'Y' THEN '-' ELSE TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                 , CASE WHEN A.NEW_YN = 'Y' THEN '-' ELSE TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                 , A.ROUTE_ID
                 , A.NEW_ROUTE_ID
                 , A.NEW_BOD_ID
                 , A.NEW_CUSTOMER_LT AS NEW_LT_DAY
                 , A.NEW_D_COUNTRY
                 , A.NEW_D_PORT_CODE
                 , A.NEW_A_COUNTRY
                 , A.NEW_A_PORT_CODE
                 , A.NEW_TO_COUNTRY
                 , A.NEW_TO_CITY
                 , TO_CHAR(TO_DATE(A.NEW_ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                 , TO_CHAR(TO_DATE(A.NEW_ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                 , A.NEW_INCOTERMS
                 , A.NEW_TRANSPORT_MODE
                 , CASE WHEN A.NEW_YYYYMMDD IS NULL THEN NULL
                        ELSE TO_CHAR(TO_DATE(A.NEW_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')
                   END AS NEW_SHIPMENT_DATE
                 , A.NEW_QTY AS NEW_SHIPMENT_CONFIRM_QTY
                 , A.CONFIRM_ID
                 , A.CHANGE_REQ_NO
                 , A.NEW_YN
                 , C.CONFIRM_ID AS PLAN_CONFIRM_ID
                 , A.ELECTRODE_YN
                 , A.ELECTRODE_TYPE
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID
                 , CASE WHEN C.CONFIRM_ID IS NOT NULL THEN 'Y' ELSE 'N' END AS NEW_BASE_CONFIRM_YN
                 , A.REMARKS
                 , A.REMARKS2
                 , A.REMARKS3
                 , A.REQUESTOR
              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE  A
                 , SCP_MST_BOD_N_V                  B
                 , SSP_ANL_SHIP_CONFIRM             C
             WHERE B.DIVISION_ID     = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
               AND B.BOD_ID          = A.BOD_ID
               AND C.CONFIRM_ID      = A.CONFIRM_ID
               AND C.SHIPMENT_STATUS = 'D'
               AND C.CHANGE_REQ_NO   = A.CHANGE_REQ_NO
               AND A.LAST_UPDATED_BY = P_REQUEST_USER_ID
               AND A.VALID_YN        = 'Y'
               AND A.ATTRIBUTE1      = 'Y'
             ORDER BY CASE WHEN A.NEW_YYYYMMDD IS NULL THEN NULL
                           ELSE TO_CHAR(TO_DATE(A.NEW_YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD')
                      END NULLS FIRST;

        OPEN O_RC2 FOR
            SELECT SA.USER_ID
                 , SA.USER_NAME
                 , SA.USER_NAME_EN
                 , SA.DEPT_ID
                 , SA.DEPT_NAME_KO
                 , SA.DEPT_NAME_EN
              FROM (SELECT A.USER_ID
                         , B.USER_NAME
                         , B.USER_NAME_EN
                         , B.DEPT_ID
                         , C.DEPT_NAME_KO
                         , C.DEPT_NAME_EN
                      FROM SSP_MST_MODEL_USER      A
                         , SCM_MST_SSO_USER_INFO   B
                         , SCM_MST_SSO_DEPT_INFO   C
                         , (SELECT DISTINCT IA.DIVISION_ID
                                 , IA.FROM_SITE
                                 , IA.ITEM_ID
                              FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE  IA
                                 , SCP_MST_BOD_N_V                  XA
                                 , SSP_ANL_SHIP_CONFIRM             SA
                             WHERE XA.DIVISION_ID     = CASE WHEN IA.DIVISION_ID = 'EE' THEN IA.ORIGIN_FROM_DIVISION_ID ELSE IA.DIVISION_ID END
                               AND XA.BOD_ID          = IA.BOD_ID
                               AND SA.CONFIRM_ID      = IA.CONFIRM_ID
                               AND SA.SHIPMENT_STATUS = 'D'
                               AND SA.CHANGE_REQ_NO   = IA.CHANGE_REQ_NO
                               AND IA.LAST_UPDATED_BY = P_REQUEST_USER_ID
                               AND IA.VALID_YN        = 'Y'
                               AND IA.ATTRIBUTE1      = 'Y') DE
                     WHERE B.USER_ID       = A.USER_ID
                       AND C.DEPT_ID(+)    = B.DEPT_ID
                       AND DE.DIVISION_ID  = A.DIVISION_ID
                       AND DE.FROM_SITE    = A.FROM_SITE
                       AND DE.ITEM_ID      = A.ITEM_ID
                       AND A.VALID_YN      = 'Y') SA
             WHERE ROWNUM = 1;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_SHIPMENT_REQUEST_DRAFTING', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_SHIPMENT_REQUEST_DRAFTING;

    /* ==============================================================================================
       SSP0200_GET_CHANGE_REQ_NO
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_CHANGE_REQ_NO
    (
        P_USER_ID           IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_CHANGE_REQ_NO
     * Description  : Shipment Change Request
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/25   KIMYONGHO      최초작성
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 채번 자리 맞춤 RIGHT(000000 + 순번, 6) -> SUBSTR(..., -6)
     *                               (순번이 6 자리를 넘으면 뒤 6 자리를 쓰는 AS-IS 동작과 같다)
     */
        V_SEQ               NUMBER;
    BEGIN
        SELECT SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL
          INTO V_SEQ
          FROM DUAL;

        OPEN O_RC1 FOR
            SELECT 'S' AS RESULT_CODE
                 , 'R' || TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(V_SEQ), -6) AS CHANGE_REQ_NO
              FROM DUAL;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_CHANGE_REQ_NO', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_CHANGE_REQ_NO;

    /* ==============================================================================================
       SSP0200_GET_SHIPMENT_STATUS
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID       IN  CLOB,
        P_CONFIRM_ID        IN  CLOB,
        O_RC1               OUT SYS_REFCURSOR,
        O_RC2               OUT SYS_REFCURSOR,
        O_RC3               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_SHIPMENT_STATUS
     * Description  : Shipment Change Request
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/21   KIMYONGHO      최초작성
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 결과 3 벌(확정 아님 · 수량 0 · ERP 전송 완료)을 커서 3 개로 되돌린다
     *                             - 이관 공백 대상 칸(SHIPMENT_STATUS)은 TRIM 비교
     */
        V_DIVISION_ID       VARCHAR2(32767 CHAR) := TO_CHAR(P_DIVISION_ID);
        V_CONFIRM_ID        VARCHAR2(32767 CHAR) := TO_CHAR(P_CONFIRM_ID);
    BEGIN
        OPEN O_RC1 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_DIVISION_ID, '^')))
               AND CONFIRM_ID  IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_CONFIRM_ID, '^')))
               AND TRIM(SHIPMENT_STATUS) <> 'C';

        OPEN O_RC2 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_DIVISION_ID, '^')))
               AND CONFIRM_ID  IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_CONFIRM_ID, '^')))
               AND QTY = 0;

        OPEN O_RC3 FOR
            SELECT CONFIRM_ID
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_DIVISION_ID, '^')))
               AND CONFIRM_ID  IN (SELECT COLUMN_VALUE
                                     FROM TABLE(STRING_SPLIT(V_CONFIRM_ID, '^')))
               AND ERP_STATUS = 'C';

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_SHIPMENT_STATUS', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_SHIPMENT_STATUS;

    /* ==============================================================================================
       SSP0200_GET_ERP_SO_NO_CNT
       ============================================================================================== */
    PROCEDURE P_SSP0200_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID       IN  VARCHAR2,
        P_ERP_SO_NO         IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_GET_ERP_SO_NO_CNT
     * Description  : Shipment Change Request
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/05/25   KIMYONGHO      최초작성
     * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     */
    BEGIN
        OPEN O_RC1 FOR
            SELECT COUNT(*) AS CNT
              FROM SSP_ANL_SHIP_CONFIRM
             WHERE DIVISION_ID = P_DIVISION_ID
               AND ERP_SO_NO   = P_ERP_SO_NO
               AND QTY        <> 0;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            P_WRITE_ERROR_LOG('SSP0200_GET_ERP_SO_NO_CNT', SQLERRM);
            P_OPEN_ERROR(SUBSTR(SQLERRM, 1, 4000), O_RESULT_CURSOR);
    END P_SSP0200_GET_ERP_SO_NO_CNT;

    /* ==============================================================================================
       SSP0200_SAVE_SHIPMENT_REQUEST_DRAFTING
       ============================================================================================== */
    PROCEDURE P_SSP0200_SAVE_SHIPMENT_REQUEST_DRAFTING
    (
        P_ACTIVE_FLAG               IN  CLOB,
        P_CHANGE_TYPE               IN  VARCHAR2,
        P_DIVISION_ID               IN  CLOB,
        P_CONFIRM_ID                IN  CLOB,
        P_SHIPMENT_QTY              IN  CLOB,
        P_SHIPMENT_DATE             IN  CLOB,
        P_FROM_SITE                 IN  CLOB,
        P_NEW_BOD_ID                IN  CLOB,
        P_NEW_ROUTE_ID              IN  CLOB,
        P_NEW_ETD_DATE              IN  CLOB,
        P_NEW_ETA_DATE              IN  CLOB,
        P_NEW_INCOTERMS             IN  CLOB,
        P_NEW_TRANSPORT_MODE        IN  CLOB,
        P_NEW_D_CONTRY              IN  CLOB,
        P_NEW_D_PORT_CODE           IN  CLOB,
        P_NEW_A_COUNTRY             IN  CLOB,
        P_NEW_A_PORT_CODE           IN  CLOB,
        P_NEW_CUSTOMER_LT           IN  CLOB,
        P_NEW_TO_COUNTRY            IN  CLOB,
        P_NEW_TO_CITY               IN  CLOB,
        P_EDIT_MAIN                 IN  CLOB,
        P_EDIT_REMARK               IN  CLOB,
        P_USER_ID                   IN  VARCHAR2,
        P_USER_DEPT_ID              IN  VARCHAR2,
        P_ELECTRODE_YN              IN  CLOB,
        P_ELECTRODE_TYPE            IN  CLOB,
        P_ORIGIN_FROM_DIVISION_ID   IN  CLOB,
        P_ORIGION_TO_DIVISION_ID    IN  CLOB,
        P_REMARKS                   IN  CLOB,
        P_REMARKS2                  IN  CLOB,
        P_REMARKS3                  IN  CLOB,
        P_CHANGE_REQ_NO             IN  VARCHAR2,
        P_CHANGE_REASON_CODE        IN  CLOB,
        P_CHANGE_REASON_DETAIL      IN  CLOB,
        P_TITLE                     IN  CLOB,
        P_PROGRAM_ID                IN  VARCHAR2,
        P_ERP_ATTR1                 IN  CLOB,
        P_ERP_ATTR2                 IN  CLOB,
        P_ERP_ATTR3                 IN  CLOB,
        O_RC1                       OUT SYS_REFCURSOR,
        O_RESULT_CURSOR             OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_SAVE_SHIPMENT_REQUEST_DRAFTING
     * Description  : Shipment Plan Change 작성중 저장
     * 호출         : SSP0200
     * 관련 Table   : SSP_ANL_SHIP_CONFIRM_CHG_REQ, SSP_ANL_SHIP_CONFIRM_CHG_REQ_de
     * 관련 프로시저 : PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN - ERP 관련 Table)
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021-05-21  KIMYONGHO       최초작성
     * 2021/10/18  SHINMYUNGSU     SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
     * 2024/05/07  hsbang          테이블 SSP_ANL_SHIP_CONFIRM_CHG_REQ_de에 STATUS_DETAIL 입력(hsbang, 20240507)
     * 2026/05/11  강주용          E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - MERGE 는 온라인 SQL 에서 쓰지 않으므로 UPDATE 후 바뀐 행이 없으면 INSERT 로 나눴다
     *                             - 경로 조회 TOP 1 + ORDER BY PRIORITY -> 인라인 뷰 정렬 후 ROWNUM = 1
     *                             - 저장 시작에 SAVEPOINT 를 두어 중간 오류에서 앞 행 저장분을 되돌린다
     *                             - 되돌리기는 결과 커서를 열기 전에 수행한다
     *                             - AS-IS 는 오류 처리에서 바깥 트랜잭션을 확정(COMMIT WORK)하지만
     *                               되돌아가지 않는 저장이 남으므로 옮기지 않았다
     *                             - AS-IS substring(값, 0, CHARINDEX(구분자, 값)) 은 첫 구분자 앞 값이므로
     *                               SUBSTR(값, 1, INSTR(값, 구분자) - 1) 로 옮겼다
     */
        V_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'SSP0200_SAVE_SHIPMENT_REQUEST_DRAFTING';
        V_MAX_LOOP_CNT      PLS_INTEGER;
        V_TOK_ACTIVE_FLAG   T_TOKEN_TAB;
        V_TOK_DIVISION_ID   T_TOKEN_TAB;
        V_TOK_CONFIRM_ID    T_TOKEN_TAB;
        V_TOK_SHIPMENT_QTY  T_TOKEN_TAB;
        V_TOK_SHIPMENT_DATE T_TOKEN_TAB;
        V_TOK_FROM_SITE     T_TOKEN_TAB;
        V_TOK_NEW_BOD_ID    T_TOKEN_TAB;
        V_TOK_TITLE         T_TOKEN_TAB;
        V_TOK_NEW_ETD       T_TOKEN_TAB;
        V_TOK_NEW_ETA       T_TOKEN_TAB;
        V_TOK_NEW_ROUTE_ID  T_TOKEN_TAB;
        V_TOK_NEW_INCOTERMS T_TOKEN_TAB;
        V_TOK_NEW_TRANS     T_TOKEN_TAB;
        V_TOK_NEW_D_CONTRY  T_TOKEN_TAB;
        V_TOK_NEW_D_PORT    T_TOKEN_TAB;
        V_TOK_NEW_A_COUNTRY T_TOKEN_TAB;
        V_TOK_NEW_A_PORT    T_TOKEN_TAB;
        V_TOK_NEW_LT        T_TOKEN_TAB;
        V_TOK_NEW_TO_COUNTRY T_TOKEN_TAB;
        V_TOK_NEW_TO_CITY   T_TOKEN_TAB;
        V_TOK_EDIT_MAIN     T_TOKEN_TAB;
        V_TOK_EDIT_REMARK   T_TOKEN_TAB;
        V_TOK_ELECTRODE_YN  T_TOKEN_TAB;
        V_TOK_ELECTRODE_TP  T_TOKEN_TAB;
        V_TOK_ORG_FROM_DIV  T_TOKEN_TAB;
        V_TOK_ORG_TO_DIV    T_TOKEN_TAB;
        V_TOK_REMARKS       T_TOKEN_TAB;
        V_TOK_REMARKS2      T_TOKEN_TAB;
        V_TOK_REMARKS3      T_TOKEN_TAB;
        V_TOK_REASON_CODE   T_TOKEN_TAB;
        V_TOK_REASON_DETAIL T_TOKEN_TAB;
        V_TOK_ERP_ATTR1     T_TOKEN_TAB;
        V_TOK_ERP_ATTR2     T_TOKEN_TAB;
        V_TOK_ERP_ATTR3     T_TOKEN_TAB;
        V_FOUND             T_FOUND_TAB;

        V_ACTIVE_FLAG       VARCHAR2(4000 CHAR);
        V_DIVISION_ID       VARCHAR2(4000 CHAR);
        V_CONFIRM_ID        VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY      VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE     VARCHAR2(4000 CHAR);
        V_FROM_SITE         VARCHAR2(4000 CHAR);
        V_TO_SITE           VARCHAR2(4000 CHAR);
        V_ITEM_ID           VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID        VARCHAR2(4000 CHAR);
        V_TITLE             VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE      VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE      VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID      VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS     VARCHAR2(4000 CHAR);
        V_NEW_TRANS_MODE    VARCHAR2(4000 CHAR);
        V_EDIT_MAIN         VARCHAR2(4000 CHAR);
        V_REMARKS           VARCHAR2(4000 CHAR);
        V_REMARKS2          VARCHAR2(4000 CHAR);
        V_REMARKS3          VARCHAR2(4000 CHAR);
        V_REASON_CODE       VARCHAR2(4000 CHAR);
        V_REASON_DETAIL     VARCHAR2(4000 CHAR);
        V_ERP_ATTR1         VARCHAR2(4000 CHAR);
        V_ERP_ATTR2         VARCHAR2(4000 CHAR);
        V_ERP_ATTR3         VARCHAR2(4000 CHAR);
        V_USER_ID_TEMP      VARCHAR2(4000 CHAR);

        V_DIV_TEMP          VARCHAR2(4000 CHAR);
        V_BOD_TEMP          VARCHAR2(4000 CHAR);
        V_FROM_TEMP         VARCHAR2(4000 CHAR);
        V_TO_TEMP           VARCHAR2(4000 CHAR);
        V_INCOTERMS_TEMP    VARCHAR2(4000 CHAR);
        V_TRANS_TEMP        VARCHAR2(4000 CHAR);
        V_ROUTE_TEMP        VARCHAR2(4000 CHAR);
        V_D_CONTRY_TEMP     VARCHAR2(4000 CHAR);
        V_D_PORT_TEMP       VARCHAR2(4000 CHAR);
        V_A_COUNTRY_TEMP    VARCHAR2(4000 CHAR);
        V_A_PORT_TEMP       VARCHAR2(4000 CHAR);
        V_CUSTOMER_LT_TEMP  VARCHAR2(4000 CHAR);
        V_TO_COUNTRY_TEMP   VARCHAR2(4000 CHAR);
        V_TO_CITY_TEMP      VARCHAR2(4000 CHAR);

        V_SOLDTO_CODE       VARCHAR2(4000 CHAR);
        V_SHIPTO_CODE       VARCHAR2(4000 CHAR);
        V_MAX_REQ_NO        VARCHAR2(40 CHAR);
        V_CHG_REQ_CHK       PLS_INTEGER := 0;
        V_SEQ               NUMBER;
        V_CREATE_DATE       DATE := SYSDATE;
        V_EVENT_DATE        DATE;
        V_REASON_ID         VARCHAR2(30 CHAR);
        V_RESULT_CODE       VARCHAR2(1 CHAR) := 'S';
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        SAVEPOINT SP_SSP0200_SAVE_DRAFT;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', V_EVENT_DATE);

        SELECT COUNT(*)
          INTO V_CHG_REQ_CHK
          FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ
         WHERE CHANGE_REQ_NO = P_CHANGE_REQ_NO;

        IF V_CHG_REQ_CHK = 0 THEN
            SELECT SEQ1_SSP_ANL_SHIP_CHG_REQ_NO.NEXTVAL
              INTO V_SEQ
              FROM DUAL;

            V_MAX_REQ_NO := 'R' || TO_CHAR(V_CREATE_DATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(V_SEQ), -6);
        END IF;

        IF P_CHANGE_REQ_NO IS NOT NULL THEN
            V_MAX_REQ_NO := P_CHANGE_REQ_NO;
        END IF;

        V_MAX_LOOP_CNT := F_SPL_CNT(P_ACTIVE_FLAG);

        P_SPL_ARR(P_ACTIVE_FLAG,             V_MAX_LOOP_CNT, V_TOK_ACTIVE_FLAG,    V_FOUND);
        P_SPL_ARR(P_DIVISION_ID,             V_MAX_LOOP_CNT, V_TOK_DIVISION_ID,    V_FOUND);
        P_SPL_ARR(P_CONFIRM_ID,              V_MAX_LOOP_CNT, V_TOK_CONFIRM_ID,     V_FOUND);
        P_SPL_ARR(P_SHIPMENT_QTY,            V_MAX_LOOP_CNT, V_TOK_SHIPMENT_QTY,   V_FOUND);
        P_SPL_ARR(P_SHIPMENT_DATE,           V_MAX_LOOP_CNT, V_TOK_SHIPMENT_DATE,  V_FOUND);
        P_SPL_ARR(P_FROM_SITE,               V_MAX_LOOP_CNT, V_TOK_FROM_SITE,      V_FOUND);
        P_SPL_ARR(P_NEW_BOD_ID,              V_MAX_LOOP_CNT, V_TOK_NEW_BOD_ID,     V_FOUND);
        P_SPL_ARR(P_TITLE,                   V_MAX_LOOP_CNT, V_TOK_TITLE,          V_FOUND);
        P_SPL_ARR(P_NEW_ETD_DATE,            V_MAX_LOOP_CNT, V_TOK_NEW_ETD,        V_FOUND);
        P_SPL_ARR(P_NEW_ETA_DATE,            V_MAX_LOOP_CNT, V_TOK_NEW_ETA,        V_FOUND);
        P_SPL_ARR(P_NEW_ROUTE_ID,            V_MAX_LOOP_CNT, V_TOK_NEW_ROUTE_ID,   V_FOUND);
        P_SPL_ARR(P_NEW_INCOTERMS,           V_MAX_LOOP_CNT, V_TOK_NEW_INCOTERMS,  V_FOUND);
        P_SPL_ARR(P_NEW_TRANSPORT_MODE,      V_MAX_LOOP_CNT, V_TOK_NEW_TRANS,      V_FOUND);
        P_SPL_ARR(P_NEW_D_CONTRY,            V_MAX_LOOP_CNT, V_TOK_NEW_D_CONTRY,   V_FOUND);
        P_SPL_ARR(P_NEW_D_PORT_CODE,         V_MAX_LOOP_CNT, V_TOK_NEW_D_PORT,     V_FOUND);
        P_SPL_ARR(P_NEW_A_COUNTRY,           V_MAX_LOOP_CNT, V_TOK_NEW_A_COUNTRY,  V_FOUND);
        P_SPL_ARR(P_NEW_A_PORT_CODE,         V_MAX_LOOP_CNT, V_TOK_NEW_A_PORT,     V_FOUND);
        P_SPL_ARR(P_NEW_CUSTOMER_LT,         V_MAX_LOOP_CNT, V_TOK_NEW_LT,         V_FOUND);
        P_SPL_ARR(P_NEW_TO_COUNTRY,          V_MAX_LOOP_CNT, V_TOK_NEW_TO_COUNTRY, V_FOUND);
        P_SPL_ARR(P_NEW_TO_CITY,             V_MAX_LOOP_CNT, V_TOK_NEW_TO_CITY,    V_FOUND);
        P_SPL_ARR(P_EDIT_MAIN,               V_MAX_LOOP_CNT, V_TOK_EDIT_MAIN,      V_FOUND);
        P_SPL_ARR(P_EDIT_REMARK,             V_MAX_LOOP_CNT, V_TOK_EDIT_REMARK,    V_FOUND);
        P_SPL_ARR(P_ELECTRODE_YN,            V_MAX_LOOP_CNT, V_TOK_ELECTRODE_YN,   V_FOUND);
        P_SPL_ARR(P_ELECTRODE_TYPE,          V_MAX_LOOP_CNT, V_TOK_ELECTRODE_TP,   V_FOUND);
        P_SPL_ARR(P_ORIGIN_FROM_DIVISION_ID, V_MAX_LOOP_CNT, V_TOK_ORG_FROM_DIV,   V_FOUND);
        P_SPL_ARR(P_ORIGION_TO_DIVISION_ID,  V_MAX_LOOP_CNT, V_TOK_ORG_TO_DIV,     V_FOUND);
        P_SPL_ARR(P_REMARKS,                 V_MAX_LOOP_CNT, V_TOK_REMARKS,        V_FOUND);
        P_SPL_ARR(P_REMARKS2,                V_MAX_LOOP_CNT, V_TOK_REMARKS2,       V_FOUND);
        P_SPL_ARR(P_REMARKS3,                V_MAX_LOOP_CNT, V_TOK_REMARKS3,       V_FOUND);
        P_SPL_ARR(P_CHANGE_REASON_CODE,      V_MAX_LOOP_CNT, V_TOK_REASON_CODE,    V_FOUND);
        P_SPL_ARR(P_CHANGE_REASON_DETAIL,    V_MAX_LOOP_CNT, V_TOK_REASON_DETAIL,  V_FOUND);
        P_SPL_ARR(P_ERP_ATTR1,               V_MAX_LOOP_CNT, V_TOK_ERP_ATTR1,      V_FOUND);
        P_SPL_ARR(P_ERP_ATTR2,               V_MAX_LOOP_CNT, V_TOK_ERP_ATTR2,      V_FOUND);
        P_SPL_ARR(P_ERP_ATTR3,               V_MAX_LOOP_CNT, V_TOK_ERP_ATTR3,      V_FOUND);

        FOR I IN 1 .. V_MAX_LOOP_CNT LOOP
            V_ACTIVE_FLAG    := V_TOK_ACTIVE_FLAG(I);
            V_DIVISION_ID    := V_TOK_DIVISION_ID(I);
            V_CONFIRM_ID     := V_TOK_CONFIRM_ID(I);
            V_SHIPMENT_QTY   := V_TOK_SHIPMENT_QTY(I);
            V_SHIPMENT_DATE  := V_TOK_SHIPMENT_DATE(I);
            V_FROM_SITE      := V_TOK_FROM_SITE(I);
            V_NEW_BOD_ID     := V_TOK_NEW_BOD_ID(I);
            V_TITLE          := 'Change on ' || V_TOK_TITLE(I);
            V_NEW_ETD_DATE   := V_TOK_NEW_ETD(I);
            V_NEW_ETA_DATE   := V_TOK_NEW_ETA(I);
            V_NEW_ROUTE_ID   := V_TOK_NEW_ROUTE_ID(I);
            V_NEW_INCOTERMS  := V_TOK_NEW_INCOTERMS(I);
            V_NEW_TRANS_MODE := V_TOK_NEW_TRANS(I);
            V_EDIT_MAIN      := V_TOK_EDIT_MAIN(I);
            V_REMARKS        := V_TOK_REMARKS(I);
            V_REMARKS2       := V_TOK_REMARKS2(I);
            V_REMARKS3       := V_TOK_REMARKS3(I);
            V_REASON_CODE    := V_TOK_REASON_CODE(I);
            V_REASON_DETAIL  := V_TOK_REASON_DETAIL(I);
            V_ERP_ATTR1      := V_TOK_ERP_ATTR1(I);
            V_ERP_ATTR2      := V_TOK_ERP_ATTR2(I);
            V_ERP_ATTR3      := V_TOK_ERP_ATTR3(I);

            /* 요청에 따라 CHANGE_REASON_CODE, CHANGE_REASON_DETAIL 을 Default T07 로 설정 */
            IF V_REASON_CODE IS NULL THEN
                V_REASON_CODE := 'T07';
            END IF;

            IF V_REASON_DETAIL IS NULL THEN
                V_REASON_DETAIL := 'T07';
            END IF;

            BEGIN
                SELECT TO_SITE
                     , ITEM_ID
                  INTO V_TO_SITE
                     , V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_TO_SITE := NULL;
                    V_ITEM_ID := NULL;
            END;

            IF V_ACTIVE_FLAG = 'I' THEN
                BEGIN
                    SELECT REQUESTOR
                      INTO V_USER_ID_TEMP
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_USER_ID_TEMP := NULL;
                END;

                IF V_USER_ID_TEMP <> P_USER_ID THEN
                    CONTINUE;
                END IF;
            END IF;

            /* E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지 */
            V_SOLDTO_CODE := FN_GET_SSP_SITE_INFO(V_DIVISION_ID, V_TO_SITE, 'SOLDTO_CODE');
            V_SHIPTO_CODE := FN_GET_SSP_SITE_INFO(V_DIVISION_ID, V_TO_SITE, 'SHIPTO_CODE');

            IF V_CONFIRM_ID IS NOT NULL THEN
                IF V_SOLDTO_CODE IS NULL
                OR V_SHIPTO_CODE IS NULL THEN
                    IF V_SOLDTO_CODE IS NULL THEN
                        V_REASON_ID := 'no soldto code';
                    ELSE
                        V_REASON_ID := 'no shipto code';
                    END IF;

                    V_EVENT_DATE := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0,
                                         '########## ' || V_DIVISION_ID || ' ' || V_TO_SITE
                                         || V_SHIPTO_CODE || ' ' || V_SOLDTO_CODE || ' ' || ' Error END of procedure ##########',
                                         '', V_EVENT_DATE);

                    OPEN O_RC1 FOR
                        SELECT 'X'           AS RESULT_CODE
                             , V_REASON_ID   AS REASON_ID
                             , V_DIVISION_ID AS DIVISION_ID
                             , V_TO_SITE     AS TO_SITE
                          FROM DUAL;

                    P_OPEN_SUCCESS(O_RESULT_CURSOR);

                    RETURN;
                END IF;
            END IF;

            V_DIV_TEMP         := NULL;
            V_BOD_TEMP         := NULL;
            V_FROM_TEMP        := NULL;
            V_TO_TEMP          := NULL;
            V_INCOTERMS_TEMP   := NULL;
            V_TRANS_TEMP       := NULL;
            V_ROUTE_TEMP       := NULL;
            V_D_CONTRY_TEMP    := NULL;
            V_D_PORT_TEMP      := NULL;
            V_A_COUNTRY_TEMP   := NULL;
            V_A_PORT_TEMP      := NULL;
            V_CUSTOMER_LT_TEMP := NULL;
            V_TO_COUNTRY_TEMP  := NULL;
            V_TO_CITY_TEMP     := NULL;

            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIV_TEMP
                     , V_BOD_TEMP
                     , V_FROM_TEMP
                     , V_TO_TEMP
                     , V_INCOTERMS_TEMP
                     , V_TRANS_TEMP
                     , V_ROUTE_TEMP
                     , V_D_CONTRY_TEMP
                     , V_D_PORT_TEMP
                     , V_A_COUNTRY_TEMP
                     , V_A_PORT_TEMP
                     , V_CUSTOMER_LT_TEMP
                     , V_TO_COUNTRY_TEMP
                     , V_TO_CITY_TEMP
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID    = V_DIVISION_ID
                                   AND A.FROM_SITE      = V_FROM_SITE
                                   AND A.TO_SITE        = V_TO_SITE
                                   AND A.TRANSPORT_MODE = V_NEW_TRANS_MODE
                                   AND A.SSP_INCOTERMS  = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN   = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD   >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID     = V_ITEM_ID) XA
                         WHERE XA.DIVISION_ID     = IA.DIVISION_ID
                           AND XA.BOD_ID          = IA.BOD_ID
                           AND IA.DIVISION_ID     = V_DIVISION_ID
                           AND IA.FROM_SITE       = V_FROM_SITE
                           AND IA.TO_SITE         = V_TO_SITE
                           AND IA.TRANSPORT_MODE  = V_NEW_TRANS_MODE
                           AND IA.SSP_INCOTERMS   = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN    = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_DIV_TEMP := NULL;
            END;

            IF V_DIV_TEMP         IS NULL
            OR V_BOD_TEMP         IS NULL
            OR V_FROM_TEMP        IS NULL
            OR V_TO_TEMP          IS NULL
            OR V_INCOTERMS_TEMP   IS NULL
            OR V_TRANS_TEMP       IS NULL
            OR V_ROUTE_TEMP       IS NULL
            OR V_D_CONTRY_TEMP    IS NULL
            OR V_D_PORT_TEMP      IS NULL
            OR V_A_COUNTRY_TEMP   IS NULL
            OR V_A_PORT_TEMP      IS NULL
            OR V_CUSTOMER_LT_TEMP IS NULL
            OR V_TO_COUNTRY_TEMP  IS NULL
            OR V_TO_CITY_TEMP     IS NULL THEN
                V_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

                OPEN O_RC1 FOR
                    SELECT 'X'  AS RESULT_CODE
                         , NULL AS REQUEST_NO
                      FROM DUAL;

                P_OPEN_SUCCESS(O_RESULT_CURSOR);

                RETURN;
            END IF;

            IF V_EDIT_MAIN IN ('Y', 'N') THEN
                /* AS-IS MERGE : 있으면 고치고 없으면 넣는다 */
                UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
                   SET CHANGE_REQ_STATUS    = 'D'
                     , REQUEST_TITLE        = V_TITLE
                     , APPROVAL_USER        = P_USER_ID
                     , APPROVAL_DEPT        = P_USER_DEPT_ID
                     , CHANGE_REASON_CODE   = V_REASON_CODE
                     , CHANGE_REASON_DETAIL = V_REASON_DETAIL
                     , LAST_UPDATED_BY      = P_USER_ID
                     , LAST_UPDATE_DATE     = V_EVENT_DATE
                     , REQUEST_TIME         = V_EVENT_DATE
                 WHERE CHANGE_REQ_NO        = V_MAX_REQ_NO;

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                    (
                        CHANGE_REQ_NO
                      , CHANGE_REQ_STATUS
                      , DIVISION_ID
                      , FROM_SITE
                      , REQUEST_TITLE
                      , REQUEST_USER
                      , REQUEST_DEPT
                      , REQUEST_TIME
                      , APPROVAL_USER
                      , APPROVAL_DEPT
                      , APPROVAL_TIME
                      , CHANGE_REASON_CODE
                      , CHANGE_REASON_DETAIL
                      , REJECT_REASON
                      , VALID_YN
                      , CHANGE_TYPE
                      , CREATED_BY
                      , CREATION_DATE
                      , LAST_UPDATED_BY
                      , LAST_UPDATE_DATE
                      , ELECTRODE_YN
                      , ELECTRODE_TYPE
                      , ORIGIN_FROM_DIVISION_ID
                      , ORIGIN_TO_DIVISION_ID
                    )
                    VALUES
                    (
                        V_MAX_REQ_NO
                      , 'D'
                      , V_DIVISION_ID
                      , V_FROM_SITE
                      , V_TITLE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , V_EVENT_DATE
                      , P_USER_ID
                      , P_USER_DEPT_ID
                      , NULL
                      , V_REASON_CODE
                      , V_REASON_DETAIL
                      , NULL
                      , 'Y'
                      , P_CHANGE_TYPE
                      , P_USER_ID
                      , V_EVENT_DATE
                      , P_USER_ID
                      , V_EVENT_DATE
                      , SUBSTR(TO_CHAR(P_ELECTRODE_YN), 1, INSTR(TO_CHAR(P_ELECTRODE_YN), C_DELIMITER) - 1)
                      , SUBSTR(TO_CHAR(P_ELECTRODE_TYPE), 1, INSTR(TO_CHAR(P_ELECTRODE_TYPE), C_DELIMITER) - 1)
                      , SUBSTR(TO_CHAR(P_ORIGIN_FROM_DIVISION_ID), 1, INSTR(TO_CHAR(P_ORIGIN_FROM_DIVISION_ID), C_DELIMITER) - 1)
                      , SUBSTR(TO_CHAR(P_ORIGION_TO_DIVISION_ID), 1, INSTR(TO_CHAR(P_ORIGION_TO_DIVISION_ID), C_DELIMITER) - 1)
                    );
                END IF;

                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_NEW_ETD_DATE, 1, 10), '-', '');
                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');

                /* 2019.09.04 etd:shipdate, eta:etd+lt_day로 셋팅 */
                IF V_SHIPMENT_DATE IS NOT NULL
               AND LENGTH(V_SHIPMENT_DATE) = 8
               AND V_TOK_NEW_LT(I) IS NOT NULL THEN
                    V_NEW_ETD_DATE := V_SHIPMENT_DATE;
                END IF;

                /* 2019.10.29 출발일 기준 항차를 고려한 ETA_DATE 계산 */
                V_NEW_ETA_DATE := FN_GET_SSP_ETA_DATE(TO_CHAR(P_DIVISION_ID), V_BOD_TEMP, V_SHIPMENT_DATE);

                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                (
                    CHANGE_REQ_NO
                  , CONFIRM_ID
                  , NEW_YN
                  , DIVISION_ID
                  , ITEM_ID
                  , FROM_SITE
                  , TO_SITE
                  , YYYYMMDD
                  , QTY
                  , BOD_ID
                  , ROUTE_ID
                  , BIZ_TYPE
                  , PROJECT_CODE
                  , FCST_TYPE
                  , FCST_ETD_DATE
                  , FCST_ETA_DATE
                  , ETD_DATE
                  , ETA_DATE
                  , INCOTERMS
                  , TRANSPORT_MODE
                  , D_COUNTRY
                  , D_PORT_CODE
                  , A_COUNTRY
                  , A_PORT_CODE
                  , CUSTOMER_LT
                  , TO_COUNTRY
                  , TO_CITY
                  , NEW_YYYYMMDD
                  , NEW_QTY
                  , NEW_BOD_ID
                  , NEW_ROUTE_ID
                  , NEW_ETD_DATE
                  , NEW_ETA_DATE
                  , NEW_INCOTERMS
                  , NEW_TRANSPORT_MODE
                  , NEW_D_COUNTRY
                  , NEW_D_PORT_CODE
                  , NEW_A_COUNTRY
                  , NEW_A_PORT_CODE
                  , NEW_CUSTOMER_LT
                  , NEW_TO_COUNTRY
                  , NEW_TO_CITY
                  , FROM_SITE_TYPE
                  , FROM_SITE_PLANT_ID
                  , FROM_SITE_VENDOR_ID
                  , FROM_SITE_SOLDTO_CODE
                  , FROM_SITE_SHIPTO_CODE
                  , FROM_SITE_COMPANY_ID
                  , TO_SITE_TYPE
                  , TO_SITE_PLANT_ID
                  , TO_SITE_VENDOR_ID
                  , TO_SITE_SOLDTO_CODE
                  , TO_SITE_SHIPTO_CODE
                  , TO_SITE_COMPANY_ID
                  , ERP_SO_NO
                  , ERP_SO_ITEM_NO
                  , ERP_DO_NO
                  , ERP_STATUS
                  , VALID_YN
                  , ATTRIBUTE1
                  , ATTRIBUTE2
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                  , ELECTRODE_YN
                  , ELECTRODE_TYPE
                  , ORIGIN_FROM_DIVISION_ID
                  , ORIGIN_TO_DIVISION_ID
                  , REMARKS
                  , REMARKS2
                  , REMARKS3
                  , REQUESTOR
                  /*----------------------------------------------------------------------------------------
                      2020.06.30 : KBK
                      I/F 추가요청으로 인하여 컬럼 추가 전극에서만 사용. DDL 표준을 맞추기 위하여 추가함
                  ------------------------------------------------------------------------------------------*/
                  , PACKAGE_TYPE
                  , FACTORY_ID
                  , PACKAGE_QTY
                  , DOM_EXP
                  , ERP_ATTR1
                  , ERP_ATTR2
                  , ERP_ATTR3
                  , ERP_ATTR4
                  , ERP_ATTR5
                )
                SELECT V_MAX_REQ_NO
                     , A.CONFIRM_ID
                     , CASE WHEN P_CHANGE_TYPE = 'N' THEN 'Y' ELSE 'N' END
                     , A.DIVISION_ID
                     , A.ITEM_ID
                     , A.FROM_SITE
                     , A.TO_SITE
                     , A.YYYYMMDD
                     , A.QTY
                     , A.BOD_ID
                     , A.ROUTE_ID
                     , A.BIZ_TYPE
                     , A.PROJECT_CODE
                     , A.FCST_TYPE
                     , A.FCST_ETD_DATE
                     , A.FCST_ETA_DATE
                     , A.ETD_DATE
                     , A.ETA_DATE
                     , A.INCOTERMS
                     , A.TRANSPORT_MODE
                     , A.D_COUNTRY
                     , A.D_PORT_CODE
                     , A.A_COUNTRY
                     , A.A_PORT_CODE
                     , A.CUSTOMER_LT
                     , A.TO_COUNTRY
                     , A.TO_CITY
                     , V_SHIPMENT_DATE
                     , NVL(TO_NUMBER(V_SHIPMENT_QTY), 0)
                     , V_BOD_TEMP
                     , V_ROUTE_TEMP
                     , V_NEW_ETD_DATE
                     , V_NEW_ETA_DATE
                     , V_INCOTERMS_TEMP
                     , V_TRANS_TEMP
                     , V_D_CONTRY_TEMP
                     , V_D_PORT_TEMP
                     , V_TOK_NEW_A_COUNTRY(I)                                       /* AS-IS 도 이 칸만 조회값이 아닌 화면값 */
                     , V_A_PORT_TEMP
                     , V_CUSTOMER_LT_TEMP
                     , V_TO_COUNTRY_TEMP
                     , V_TOK_NEW_TO_CITY(I)                                         /* AS-IS 도 이 칸만 조회값이 아닌 화면값 */
                     , A.FROM_SITE_TYPE
                     , A.FROM_SITE_PLANT_ID
                     , A.FROM_SITE_VENDOR_ID
                     , A.FROM_SITE_SOLDTO_CODE
                     , A.FROM_SITE_SHIPTO_CODE
                     , A.FROM_SITE_COMPANY_ID
                     , A.TO_SITE_TYPE
                     , A.TO_SITE_PLANT_ID
                     , A.TO_SITE_VENDOR_ID
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , A.TO_SITE_COMPANY_ID
                     , A.ERP_SO_NO
                     , A.ERP_SO_ITEM_NO
                     , A.ERP_DO_NO
                     , A.ERP_STATUS
                     , 'Y'
                     , 'Y'
                     , 'D'                                                          /* STATUS_DETAIL에 Drafting 입력(hsbang, 20240507) */
                     , P_USER_ID
                     , V_CREATE_DATE
                     , P_USER_ID
                     , V_CREATE_DATE
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , V_REMARKS
                     , V_REMARKS2
                     , V_REMARKS3
                     , A.REQUESTOR
                     , A.PACKAGE_TYPE_CODE
                     , A.FACTORY_ID
                     , CASE WHEN A.ELECTRODE_YN = 'N' THEN NVL(TO_NUMBER(V_SHIPMENT_QTY), 0)
                            ELSE CEIL(CASE WHEN B.PACKAGE_TYPE_CODE = 'BX' THEN CEIL(NVL(TO_NUMBER(V_SHIPMENT_QTY), 0) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.BOX_PER_CUT, 1)
                                           WHEN B.PACKAGE_TYPE_CODE = 'SC' THEN CEIL(NVL(TO_NUMBER(V_SHIPMENT_QTY), 0) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELCRATE_PER_CUT, 1)
                                           WHEN B.PACKAGE_TYPE_CODE = 'SR' THEN CEIL(NVL(TO_NUMBER(V_SHIPMENT_QTY), 0) * NVL(B.CONVERT_TO_PC_ROLL_LENGTH, 1)) * NVL(B.STEELRACK_PER_CUT, 1)
                                      ELSE NULL END)
                       END
                     , B.DOM_EXP_TYPE
                     , V_ERP_ATTR1                                                  /* 20211018 SHINMYUNGSU 항목추가 */
                     , V_ERP_ATTR2
                     , V_ERP_ATTR3
                     , A.ERP_ATTR4
                     , A.ERP_ATTR5
                  FROM SSP_ANL_SHIP_CONFIRM      A
                     , SSP_MST_SITE_ITEM_EE_V    B
                 WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                   AND B.SCM_SITE_ID(+) = A.FROM_SITE
                   AND B.ITEM_ID(+)     = A.ITEM_ID
                   AND A.CONFIRM_ID     = V_CONFIRM_ID;
            END IF;

            /* ROUTE_ID 변경 시 ETA_DATE 반영하기 위하여 결재와 별개로 Confirm UPDATE */
            IF V_ROUTE_TEMP <> V_NEW_ROUTE_ID THEN
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET ROUTE_ID   = V_ROUTE_TEMP
                     , ETA_DATE   = V_NEW_ETA_DATE
                 WHERE CONFIRM_ID = V_CONFIRM_ID;

                /* ETA 변경에 대해서 MKT_FSCST 동기화를 위해 호출 */
                PR_DM_SSP_CONFIRM_SYNC(V_DIVISION_ID, V_CONFIRM_ID);
            END IF;

            UPDATE SSP_ANL_SHIP_CONFIRM
               SET SHIPMENT_STATUS  = 'D'
                 , CHANGE_REQ_NO    = V_MAX_REQ_NO
                 , LAST_UPDATED_BY  = P_USER_ID
                 , LAST_UPDATE_DATE = V_EVENT_DATE
             WHERE CONFIRM_ID       = V_CONFIRM_ID;

            IF V_ACTIVE_FLAG = 'I' THEN
                /* 신규 대상 건 FLAG ATTRIBUTE10 초기화 */
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET ATTRIBUTE10  = NULL
                 WHERE CONFIRM_ID   = V_CONFIRM_ID;
            ELSE
                /* ERP전송 Table(XIF_ERP_SHIP_PLAN_CONFIRM_S_SN) Insert */
                /* 출하확정변경시 ERP 전송 이터 테이블 저장 C: 변경요청 */
                PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_NEW('C', V_MAX_REQ_NO, V_CONFIRM_ID);
            END IF;
        END LOOP;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

        OPEN O_RC1 FOR
            SELECT V_RESULT_CODE AS RESULT_CODE
                 , V_MAX_REQ_NO  AS REQUEST_NO
              FROM DUAL;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            ROLLBACK TO SP_SSP0200_SAVE_DRAFT;

            P_WRITE_ERROR_LOG(V_PROGRAM_NAME, V_ERR);

            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                     , NULL AS REQUEST_NO
                  FROM DUAL;

            P_OPEN_ERROR(V_ERR, O_RESULT_CURSOR);
    END P_SSP0200_SAVE_SHIPMENT_REQUEST_DRAFTING;

    /* ==============================================================================================
       SSP0200_SAVE_SHIPMENT_CONFIRM_NEW
       ============================================================================================== */
    PROCEDURE P_SSP0200_SAVE_SHIPMENT_CONFIRM_NEW
    (
        P_ACTIVE_FLAG       IN  CLOB,
        P_DIVISION_ID       IN  CLOB,
        P_FROM_SITE         IN  CLOB,
        P_TO_SITE           IN  CLOB,
        P_PROJECT_CODE40    IN  CLOB,
        P_PROJECT_CODE      IN  CLOB,
        P_FCST_TYPE         IN  CLOB,
        P_ITEM_ID           IN  CLOB,
        P_SHIPMENT_DATE     IN  CLOB,
        P_SHIPMENT_QTY      IN  CLOB,
        P_INCOTERMS         IN  CLOB,
        P_TRANSPORT_MODE    IN  CLOB,
        P_LT                IN  CLOB,
        P_ETD               IN  CLOB,
        P_ETA               IN  CLOB,
        P_ROUTE_ID          IN  CLOB,
        P_BOD_ID            IN  CLOB,
        P_D_COUNTRY         IN  CLOB,
        P_D_PORT_CODE       IN  CLOB,
        P_A_CONUNTRY        IN  CLOB,
        P_A_PORT_CODE       IN  CLOB,
        P_TO_COUNTRY        IN  CLOB,
        P_TO_CITY           IN  CLOB,
        P_REMARKS           IN  CLOB,
        P_REMARKS2          IN  CLOB,
        P_REMARKS3          IN  CLOB,
        P_USER_ID           IN  VARCHAR2,
        P_TIME_ZONE         IN  VARCHAR2,
        P_ERP_ATTR1         IN  CLOB,
        P_ERP_ATTR2         IN  CLOB,
        P_ERP_ATTR3         IN  CLOB,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_SAVE_SHIPMENT_CONFIRM_NEW
     * Description  : Shipment Request NEW 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     * 2021/06/07   KIMYONGHO      신규추가
     * 2021/10/18   SHINMYUNGSU    SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
     * 2023/02/06   jilee          PR_DM_SSP_CONFIRM_SYNC 동기화 추가
     * 2023/05/08   jilee          @v_plan_start_yyyymmdd 누락시 현재 날짜로 삽입
     * 2025/08/18   chkim.68       [E20250821-001308] to_company_id를 from_site에 따라 다르게 적용하는 예외를 적용
     * 2026/05/11   강주용         E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 경로 조회 TOP 1 + ORDER BY PRIORITY -> 인라인 뷰 정렬 후 ROWNUM = 1
     *                             - 모델이 없는 행(N)은 AS-IS 가 결과를 한 벌 더 되돌리므로
     *                               되돌림값에 N 을 남겨 화면이 첫 결과에서 읽는 값과 맞췄다
     *                             - 저장 시작에 SAVEPOINT · 되돌리기는 결과 커서를 열기 전에 수행
     *                             - 판가 확인 기간은 AS-IS 와 같이 당주 월요일부터 12 주 뒤 월요일까지
     */
        V_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'SSP0200_SAVE_SHIPMENT_CONFIRM_NEW';
        V_MAX_LOOP_CNT      PLS_INTEGER;
        V_TOK_ACTIVE_FLAG   T_TOKEN_TAB;
        V_TOK_DIVISION_ID   T_TOKEN_TAB;
        V_TOK_FROM_SITE     T_TOKEN_TAB;
        V_TOK_TO_SITE       T_TOKEN_TAB;
        V_TOK_PROJECT40     T_TOKEN_TAB;
        V_TOK_PROJECT       T_TOKEN_TAB;
        V_TOK_FCST_TYPE     T_TOKEN_TAB;
        V_TOK_ITEM_ID       T_TOKEN_TAB;
        V_TOK_SHIP_DATE     T_TOKEN_TAB;
        V_TOK_SHIP_QTY      T_TOKEN_TAB;
        V_TOK_INCOTERMS     T_TOKEN_TAB;
        V_TOK_TRANS_MODE    T_TOKEN_TAB;
        V_TOK_LT            T_TOKEN_TAB;
        V_TOK_ETD           T_TOKEN_TAB;
        V_TOK_ETA           T_TOKEN_TAB;
        V_TOK_ROUTE_ID      T_TOKEN_TAB;
        V_TOK_BOD_ID        T_TOKEN_TAB;
        V_TOK_D_COUNTRY     T_TOKEN_TAB;
        V_TOK_D_PORT        T_TOKEN_TAB;
        V_TOK_A_COUNTRY     T_TOKEN_TAB;
        V_TOK_A_PORT        T_TOKEN_TAB;
        V_TOK_TO_COUNTRY    T_TOKEN_TAB;
        V_TOK_TO_CITY       T_TOKEN_TAB;
        V_TOK_REMARKS       T_TOKEN_TAB;
        V_TOK_REMARKS2      T_TOKEN_TAB;
        V_TOK_REMARKS3      T_TOKEN_TAB;
        V_TOK_ERP_ATTR1     T_TOKEN_TAB;
        V_TOK_ERP_ATTR2     T_TOKEN_TAB;
        V_TOK_ERP_ATTR3     T_TOKEN_TAB;
        V_FOUND             T_FOUND_TAB;

        V_ACTIVE_FLAG       VARCHAR2(4000 CHAR);
        V_DIVISION_ID       VARCHAR2(4000 CHAR);
        V_FROM_SITE         VARCHAR2(4000 CHAR);
        V_TO_SITE           VARCHAR2(4000 CHAR);
        V_PROJECT_CODE_40   VARCHAR2(4000 CHAR);
        V_PROJECT_CODE      VARCHAR2(4000 CHAR);
        V_FCST_TYPE         VARCHAR2(4000 CHAR);
        V_ITEM_ID           VARCHAR2(4000 CHAR);
        V_SHIPMENT_DATE     VARCHAR2(4000 CHAR);
        V_SHIPMENT_QTY      VARCHAR2(4000 CHAR);
        V_NEW_INCOTERMS     VARCHAR2(4000 CHAR);
        V_NEW_TRANS_MODE    VARCHAR2(4000 CHAR);
        V_NEW_CUSTOMER_LT   VARCHAR2(4000 CHAR);
        V_NEW_ETD_DATE      VARCHAR2(4000 CHAR);
        V_NEW_ETA_DATE      VARCHAR2(4000 CHAR);
        V_NEW_ROUTE_ID      VARCHAR2(4000 CHAR);
        V_NEW_BOD_ID        VARCHAR2(4000 CHAR);
        V_NEW_D_CONTRY      VARCHAR2(4000 CHAR);
        V_NEW_D_PORT_CODE   VARCHAR2(4000 CHAR);
        V_NEW_A_COUNTRY     VARCHAR2(4000 CHAR);
        V_NEW_A_PORT_CODE   VARCHAR2(4000 CHAR);
        V_NEW_TO_COUNTRY    VARCHAR2(4000 CHAR);
        V_NEW_TO_CITY       VARCHAR2(4000 CHAR);
        V_REMARKS           VARCHAR2(4000 CHAR);
        V_REMARKS2          VARCHAR2(4000 CHAR);
        V_REMARKS3          VARCHAR2(4000 CHAR);
        V_ERP_ATTR1         VARCHAR2(4000 CHAR);
        V_ERP_ATTR2         VARCHAR2(4000 CHAR);
        V_ERP_ATTR3         VARCHAR2(4000 CHAR);

        V_DIVISION_ID_OR    VARCHAR2(4000 CHAR);
        V_TO_SITE_OR        VARCHAR2(4000 CHAR);

        V_OPERATION_GROUP   VARCHAR2(4000 CHAR);
        V_ELECTRODE_YN      VARCHAR2(4000 CHAR);
        V_ORIGIN_FROM_DIV   VARCHAR2(4000 CHAR);
        V_ORIGIN_TO_DIV     VARCHAR2(4000 CHAR);

        V_FROM_SITE_TYPE    VARCHAR2(4000 CHAR);
        V_FROM_SITE_PLANT   VARCHAR2(4000 CHAR);
        V_FROM_SITE_VENDOR  VARCHAR2(4000 CHAR);
        V_FROM_SITE_COMPANY VARCHAR2(4000 CHAR);
        V_FROM_SITE_SOLDTO  VARCHAR2(4000 CHAR);
        V_FROM_SITE_SHIPTO  VARCHAR2(4000 CHAR);
        V_TO_SITE_TYPE      VARCHAR2(4000 CHAR);
        V_TO_SITE_PLANT     VARCHAR2(4000 CHAR);
        V_TO_SITE_VENDOR    VARCHAR2(4000 CHAR);
        V_TO_SITE_COMPANY   VARCHAR2(4000 CHAR);
        V_TO_SITE_SOLDTO    VARCHAR2(4000 CHAR);
        V_TO_SITE_SHIPTO    VARCHAR2(4000 CHAR);
        V_TMP_DIVISION_ID   VARCHAR2(4000 CHAR);

        V_CNT_ITEM_ID       PLS_INTEGER := 0;
        V_VAL_CODE          PLS_INTEGER := 0;
        V_PRJ_CNT           PLS_INTEGER := 0;
        V_PRICE_CHECK_CNT   PLS_INTEGER := 0;
        V_MKT_FCST_CHK_CNT  PLS_INTEGER := 0;
        V_PLAN_START        VARCHAR2(8 CHAR);
        V_SEQ_PLAN          VARCHAR2(4000 CHAR);
        V_SEQ               NUMBER;
        V_NEW_CONFIRM_ID    VARCHAR2(4000 CHAR);
        V_TMP_TIME_ZONE     VARCHAR2(8 CHAR);
        V_ETA               VARCHAR2(8 CHAR);
        V_ETD               VARCHAR2(8 CHAR);
        V_LAST_UPDATE_DATE  DATE;
        V_EVENT_DATE        DATE;
        V_REASON_ID         VARCHAR2(30 CHAR);
        V_RESULT_CODE       VARCHAR2(1 CHAR) := 'S';
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        SAVEPOINT SP_SSP0200_SAVE_NEW;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', V_EVENT_DATE);

        V_MAX_LOOP_CNT := F_SPL_CNT(P_ACTIVE_FLAG);

        P_SPL_ARR(P_ACTIVE_FLAG,    V_MAX_LOOP_CNT, V_TOK_ACTIVE_FLAG, V_FOUND);
        P_SPL_ARR(P_DIVISION_ID,    V_MAX_LOOP_CNT, V_TOK_DIVISION_ID, V_FOUND);
        P_SPL_ARR(P_FROM_SITE,      V_MAX_LOOP_CNT, V_TOK_FROM_SITE,   V_FOUND);
        P_SPL_ARR(P_TO_SITE,        V_MAX_LOOP_CNT, V_TOK_TO_SITE,     V_FOUND);
        P_SPL_ARR(P_PROJECT_CODE40, V_MAX_LOOP_CNT, V_TOK_PROJECT40,   V_FOUND);
        P_SPL_ARR(P_PROJECT_CODE,   V_MAX_LOOP_CNT, V_TOK_PROJECT,     V_FOUND);
        P_SPL_ARR(P_FCST_TYPE,      V_MAX_LOOP_CNT, V_TOK_FCST_TYPE,   V_FOUND);
        P_SPL_ARR(P_ITEM_ID,        V_MAX_LOOP_CNT, V_TOK_ITEM_ID,     V_FOUND);
        P_SPL_ARR(P_SHIPMENT_DATE,  V_MAX_LOOP_CNT, V_TOK_SHIP_DATE,   V_FOUND);
        P_SPL_ARR(P_SHIPMENT_QTY,   V_MAX_LOOP_CNT, V_TOK_SHIP_QTY,    V_FOUND);
        P_SPL_ARR(P_INCOTERMS,      V_MAX_LOOP_CNT, V_TOK_INCOTERMS,   V_FOUND);
        P_SPL_ARR(P_TRANSPORT_MODE, V_MAX_LOOP_CNT, V_TOK_TRANS_MODE,  V_FOUND);
        P_SPL_ARR(P_LT,             V_MAX_LOOP_CNT, V_TOK_LT,          V_FOUND);
        P_SPL_ARR(P_ETD,            V_MAX_LOOP_CNT, V_TOK_ETD,         V_FOUND);
        P_SPL_ARR(P_ETA,            V_MAX_LOOP_CNT, V_TOK_ETA,         V_FOUND);
        P_SPL_ARR(P_ROUTE_ID,       V_MAX_LOOP_CNT, V_TOK_ROUTE_ID,    V_FOUND);
        P_SPL_ARR(P_BOD_ID,         V_MAX_LOOP_CNT, V_TOK_BOD_ID,      V_FOUND);
        P_SPL_ARR(P_D_COUNTRY,      V_MAX_LOOP_CNT, V_TOK_D_COUNTRY,   V_FOUND);
        P_SPL_ARR(P_D_PORT_CODE,    V_MAX_LOOP_CNT, V_TOK_D_PORT,      V_FOUND);
        P_SPL_ARR(P_A_CONUNTRY,     V_MAX_LOOP_CNT, V_TOK_A_COUNTRY,   V_FOUND);
        P_SPL_ARR(P_A_PORT_CODE,    V_MAX_LOOP_CNT, V_TOK_A_PORT,      V_FOUND);
        P_SPL_ARR(P_TO_COUNTRY,     V_MAX_LOOP_CNT, V_TOK_TO_COUNTRY,  V_FOUND);
        P_SPL_ARR(P_TO_CITY,        V_MAX_LOOP_CNT, V_TOK_TO_CITY,     V_FOUND);
        P_SPL_ARR(P_REMARKS,        V_MAX_LOOP_CNT, V_TOK_REMARKS,     V_FOUND);
        P_SPL_ARR(P_REMARKS2,       V_MAX_LOOP_CNT, V_TOK_REMARKS2,    V_FOUND);
        P_SPL_ARR(P_REMARKS3,       V_MAX_LOOP_CNT, V_TOK_REMARKS3,    V_FOUND);
        P_SPL_ARR(P_ERP_ATTR1,      V_MAX_LOOP_CNT, V_TOK_ERP_ATTR1,   V_FOUND);
        P_SPL_ARR(P_ERP_ATTR2,      V_MAX_LOOP_CNT, V_TOK_ERP_ATTR2,   V_FOUND);
        P_SPL_ARR(P_ERP_ATTR3,      V_MAX_LOOP_CNT, V_TOK_ERP_ATTR3,   V_FOUND);

        FOR I IN 1 .. V_MAX_LOOP_CNT LOOP
            V_ACTIVE_FLAG     := V_TOK_ACTIVE_FLAG(I);
            V_DIVISION_ID     := V_TOK_DIVISION_ID(I);
            V_FROM_SITE       := V_TOK_FROM_SITE(I);
            V_TO_SITE         := V_TOK_TO_SITE(I);
            V_PROJECT_CODE_40 := V_TOK_PROJECT40(I);
            V_PROJECT_CODE    := V_TOK_PROJECT(I);
            V_FCST_TYPE       := V_TOK_FCST_TYPE(I);
            V_ITEM_ID         := V_TOK_ITEM_ID(I);
            V_SHIPMENT_DATE   := V_TOK_SHIP_DATE(I);
            V_SHIPMENT_QTY    := V_TOK_SHIP_QTY(I);
            V_NEW_INCOTERMS   := V_TOK_INCOTERMS(I);
            V_NEW_TRANS_MODE  := V_TOK_TRANS_MODE(I);
            V_NEW_CUSTOMER_LT := V_TOK_LT(I);
            V_NEW_ETD_DATE    := V_TOK_ETD(I);
            V_NEW_ETA_DATE    := V_TOK_ETA(I);
            V_NEW_ROUTE_ID    := V_TOK_ROUTE_ID(I);
            V_NEW_BOD_ID      := V_TOK_BOD_ID(I);
            V_NEW_D_CONTRY    := V_TOK_D_COUNTRY(I);
            V_NEW_D_PORT_CODE := V_TOK_D_PORT(I);
            V_NEW_A_COUNTRY   := V_TOK_A_COUNTRY(I);
            V_NEW_A_PORT_CODE := V_TOK_A_PORT(I);
            V_NEW_TO_COUNTRY  := V_TOK_TO_COUNTRY(I);
            V_NEW_TO_CITY     := V_TOK_TO_CITY(I);
            V_REMARKS         := V_TOK_REMARKS(I);
            V_REMARKS2        := V_TOK_REMARKS2(I);
            V_REMARKS3        := V_TOK_REMARKS3(I);
            V_ERP_ATTR1       := V_TOK_ERP_ATTR1(I);
            V_ERP_ATTR2       := V_TOK_ERP_ATTR2(I);
            V_ERP_ATTR3       := V_TOK_ERP_ATTR3(I);

            V_DIVISION_ID_OR  := V_DIVISION_ID;
            V_TO_SITE_OR      := V_TO_SITE;

            BEGIN
                SELECT DIVISION_ID
                     , BOD_ID
                     , FROM_SITE
                     , TO_SITE
                     , SSP_INCOTERMS
                     , TRANSPORT_MODE
                     , ROUTE_ID
                     , D_COUNTRY
                     , D_PORT_CODE
                     , A_COUNTRY
                     , A_PORT_CODE
                     , LT_TOTAL
                     , TO_COUNTRY
                     , TO_CITY
                  INTO V_DIVISION_ID
                     , V_NEW_BOD_ID
                     , V_FROM_SITE
                     , V_TO_SITE
                     , V_NEW_INCOTERMS
                     , V_NEW_TRANS_MODE
                     , V_NEW_ROUTE_ID
                     , V_NEW_D_CONTRY
                     , V_NEW_D_PORT_CODE
                     , V_NEW_A_COUNTRY
                     , V_NEW_A_PORT_CODE
                     , V_NEW_CUSTOMER_LT
                     , V_NEW_TO_COUNTRY
                     , V_NEW_TO_CITY
                  FROM (SELECT IA.DIVISION_ID
                             , IA.BOD_ID
                             , IA.FROM_SITE
                             , IA.TO_SITE
                             , IA.SSP_INCOTERMS
                             , IA.TRANSPORT_MODE
                             , IA.ROUTE_ID
                             , IA.D_COUNTRY
                             , IA.D_PORT_CODE
                             , IA.A_COUNTRY
                             , IA.A_PORT_CODE
                             , IA.LT_TOTAL
                             , IA.TO_COUNTRY
                             , IA.TO_CITY
                          FROM (SELECT DISTINCT A.DIVISION_ID
                                     , A.BOD_ID
                                     , A.FROM_SITE
                                     , A.TO_SITE
                                     , A.SSP_INCOTERMS
                                     , A.TRANSPORT_MODE
                                     , A.ROUTE_ID
                                     , A.D_COUNTRY
                                     , A.D_PORT_CODE
                                     , A.A_COUNTRY
                                     , A.A_PORT_CODE
                                     , A.LT_TOTAL
                                     , A.LT_TOTAL_ORIGIN
                                     , A.TO_COUNTRY
                                     , A.TO_CITY
                                     , A.PRIORITY
                                     , A.BOD_VALID_YN
                                  FROM SCP_MST_BOD_N_V A
                                 WHERE A.DIVISION_ID    = V_DIVISION_ID
                                   AND A.FROM_SITE      = V_FROM_SITE
                                   AND A.TO_SITE        = V_TO_SITE
                                   AND A.TRANSPORT_MODE = V_NEW_TRANS_MODE
                                   AND A.SSP_INCOTERMS  = V_NEW_INCOTERMS
                                   AND A.BOD_VALID_YN   = 'Y'
                                   AND A.FROM_YYYYMMDD <= V_SHIPMENT_DATE
                                   AND A.TO_YYYYMMDD   >= V_SHIPMENT_DATE) IA
                             , (SELECT DISTINCT DIVISION_ID
                                     , ITEM_ID
                                     , BOD_ID
                                  FROM SCP_MST_BOD_ITEM
                                 WHERE DIVISION_ID = V_DIVISION_ID
                                   AND ITEM_ID     = V_ITEM_ID) XA
                         WHERE XA.DIVISION_ID    = IA.DIVISION_ID
                           AND XA.BOD_ID         = IA.BOD_ID
                           AND IA.DIVISION_ID    = V_DIVISION_ID
                           AND IA.FROM_SITE      = V_FROM_SITE
                           AND IA.TO_SITE        = V_TO_SITE
                           AND IA.TRANSPORT_MODE = V_NEW_TRANS_MODE
                           AND IA.SSP_INCOTERMS  = V_NEW_INCOTERMS
                           AND IA.BOD_VALID_YN   = 'Y'
                         ORDER BY IA.PRIORITY)
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_NEW_BOD_ID := NULL;
            END;

            IF V_DIVISION_ID     IS NULL
            OR V_NEW_BOD_ID      IS NULL
            OR V_FROM_SITE       IS NULL
            OR V_TO_SITE         IS NULL
            OR V_NEW_INCOTERMS   IS NULL
            OR V_NEW_TRANS_MODE  IS NULL
            OR V_NEW_ROUTE_ID    IS NULL
            OR V_NEW_D_CONTRY    IS NULL
            OR V_NEW_D_PORT_CODE IS NULL
            OR V_NEW_A_COUNTRY   IS NULL
            OR V_NEW_A_PORT_CODE IS NULL
            OR V_NEW_CUSTOMER_LT IS NULL
            OR V_NEW_TO_COUNTRY  IS NULL
            OR V_NEW_TO_CITY     IS NULL THEN
                V_EVENT_DATE := SYSDATE;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

                OPEN O_RC1 FOR
                    SELECT 'X' AS RESULT_CODE
                      FROM DUAL;

                P_OPEN_SUCCESS(O_RESULT_CURSOR);

                RETURN;
            END IF;

            BEGIN
                SELECT DIVISION_ID
                     , OPERATION_GROUP
                  INTO V_ORIGIN_FROM_DIV
                     , V_OPERATION_GROUP
                  FROM SCM_MST_SITE
                 WHERE SCM_SITE_ID = V_FROM_SITE
                   AND DIVISION_ID = V_DIVISION_ID
                   AND VALID_YN    = 'Y';
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_ORIGIN_FROM_DIV := NULL;
                    V_OPERATION_GROUP := NULL;
                WHEN TOO_MANY_ROWS THEN
                    V_ORIGIN_FROM_DIV := NULL;
                    V_OPERATION_GROUP := NULL;
            END;

            IF V_PROJECT_CODE = '-' THEN
                V_PROJECT_CODE := NULL;
            END IF;

            IF V_OPERATION_GROUP <> 'E'
            OR V_OPERATION_GROUP IS NULL THEN
                V_ELECTRODE_YN  := 'N';
                V_ORIGIN_TO_DIV := V_ORIGIN_FROM_DIV;
            ELSE
                V_ELECTRODE_YN := 'Y';

                BEGIN
                    SELECT DIVISION_ID
                      INTO V_ORIGIN_TO_DIV
                      FROM SCM_MST_SITE
                     WHERE SCM_SITE_ID = V_TO_SITE
                       AND VALID_YN    = 'Y';
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_ORIGIN_TO_DIV := NULL;
                    WHEN TOO_MANY_ROWS THEN
                        V_ORIGIN_TO_DIV := NULL;
                END;
            END IF;

            SELECT NVL(COUNT(*), 0)
              INTO V_CNT_ITEM_ID
              FROM (SELECT DISTINCT B.DIVISION_ID
                      FROM SCM_MST_SITE_ITEM  A
                         , SCM_MST_DIVISION   B
                         , SCM_MST_SITE       C
                         , SCM_MST_ITEM_SN    D
                         , SCM_MST_PROJECT    E
                     WHERE B.DIVISION_ID    = A.DIVISION_ID
                       AND C.DIVISION_ID    = A.DIVISION_ID
                       AND C.SCM_SITE_ID    = A.SCM_SITE_ID
                       AND D.DIVISION_ID    = A.DIVISION_ID
                       AND D.ITEM_ID        = A.ITEM_ID
                       AND E.DIVISION_ID(+) = A.DIVISION_ID
                       AND E.PROJECT_CODE(+)= A.PROJECT_CODE
                       AND CASE WHEN V_DIVISION_ID = 'ALL' THEN 'ALL' ELSE A.DIVISION_ID END
                           IN (SELECT COLUMN_VALUE
                                 FROM TABLE(STRING_SPLIT(V_DIVISION_ID, ',')))
                       AND A.PROJECT_CODE LIKE '%' || V_PROJECT_CODE || '%'
                       AND (A.ITEM_ID   LIKE '%' || V_ITEM_ID || '%'
                         OR D.ITEM_NAME LIKE '%' || V_ITEM_ID || '%'
                         OR D.NICK_NAME LIKE '%' || V_ITEM_ID || '%'));

            /* VALIDATION 체크 - 1:해당 MODEL 있음 / 0:해당 MODEL 없음 */
            IF V_CNT_ITEM_ID > 0 THEN
                V_VAL_CODE := 1;
            ELSE
                V_VAL_CODE := 0;
            END IF;

            IF V_VAL_CODE = 1 THEN
                V_EVENT_DATE    := SYSDATE;
                V_TMP_TIME_ZONE := TO_CHAR(FN_MULTY_TIME(P_TIME_ZONE), 'YYYYMMDD');

                SELECT SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL
                  INTO V_SEQ
                  FROM DUAL;

                V_NEW_CONFIRM_ID := 'C' || V_TMP_TIME_ZONE || SUBSTR('000000' || TO_CHAR(V_SEQ), -6);

                SELECT NVL(MAX(PLAN_START_YYYYMMDD), TO_CHAR(SYSDATE, 'YYYYMMDD'))
                     , NVL(MAX(PLAN_SEQ), '1')
                  INTO V_PLAN_START
                     , V_SEQ_PLAN
                  FROM SSP_PLAN_VERSION_V
                 WHERE PLAN_TYPE    = 'SP'
                   AND DIVISION_ID  = V_DIVISION_ID
                   AND CONFIRM_FLAG = 'Y'
                   AND PLAN_START_YYYYMMDD = (SELECT MAX(PLAN_START_YYYYMMDD)
                                                FROM SSP_PLAN_VERSION_V
                                               WHERE DIVISION_ID  = V_DIVISION_ID
                                                 AND PLAN_TYPE    = 'SP'
                                                 AND CONFIRM_FLAG = 'Y');

                /* [E20250821-001308] TO_COMPANY_ID 를 FROM_SITE 에 따라 다르게 적용하는 예외를 적용 */
                V_TMP_DIVISION_ID   := V_ORIGIN_FROM_DIV;
                V_FROM_SITE_TYPE    := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SITE_TYPE');
                V_FROM_SITE_PLANT   := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'PLANT_ID');
                V_FROM_SITE_VENDOR  := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'VENDOR_ID');
                V_FROM_SITE_COMPANY := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'COMPANY_ID');
                V_FROM_SITE_SOLDTO  := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SOLDTO_CODE');
                V_FROM_SITE_SHIPTO  := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_FROM_SITE, 'SHIPTO_CODE');

                V_TMP_DIVISION_ID   := CASE WHEN V_DIVISION_ID = 'EE' THEN V_ORIGIN_FROM_DIV ELSE V_ORIGIN_TO_DIV END;
                V_TO_SITE_TYPE      := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'SITE_TYPE');
                V_TO_SITE_PLANT     := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'PLANT_ID');
                V_TO_SITE_VENDOR    := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'VENDOR_ID');
                V_TO_SITE_COMPANY   := FN_GET_SSP_SITE_INFO_EXCEPTION(V_TMP_DIVISION_ID, V_FROM_SITE, V_TO_SITE, 'COMPANY_ID');
                V_TO_SITE_SOLDTO    := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SOLDTO_CODE');
                V_TO_SITE_SHIPTO    := FN_GET_SSP_SITE_INFO(V_TMP_DIVISION_ID, V_TO_SITE, 'SHIPTO_CODE');

                /* E20260514-001358 TO_ shipto / soldto 없는 경우 출하 금지 */
                IF V_TO_SITE_SOLDTO IS NULL
                OR V_TO_SITE_SHIPTO IS NULL THEN
                    IF V_TO_SITE_SOLDTO IS NULL THEN
                        V_REASON_ID := 'no soldto code';
                    ELSE
                        V_REASON_ID := 'no shipto code';
                    END IF;

                    V_EVENT_DATE := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0,
                                         '########## ' || V_DIVISION_ID_OR || ' ' || V_TO_SITE_OR
                                         || V_TO_SITE_SHIPTO || ' ' || V_TO_SITE_SOLDTO || ' ' || ' Error END of procedure ##########',
                                         '', V_EVENT_DATE);

                    OPEN O_RC1 FOR
                        SELECT 'X'              AS RESULT_CODE
                             , V_REASON_ID      AS REASON_ID
                             , V_DIVISION_ID_OR AS DIVISION_ID
                             , V_TO_SITE_OR     AS TO_SITE
                          FROM DUAL;

                    P_OPEN_SUCCESS(O_RESULT_CURSOR);

                    RETURN;
                END IF;

                /* mkt owner select */
                IF V_DIVISION_ID = '40' THEN
                    SELECT COUNT(PROJECT_CODE)
                      INTO V_PRJ_CNT
                      FROM SCM_MST_SITE_ITEM
                     WHERE DIVISION_ID  = V_DIVISION_ID
                       AND SCM_SITE_ID  = V_TO_SITE
                       AND ITEM_ID      = V_ITEM_ID
                       AND PROJECT_CODE = V_PROJECT_CODE_40;

                    IF V_PRJ_CNT = 0 THEN
                        BEGIN
                            SELECT PROJECT_CODE
                              INTO V_PROJECT_CODE
                              FROM SCM_MST_SITE_ITEM
                             WHERE DIVISION_ID = V_DIVISION_ID
                               AND SCM_SITE_ID = V_TO_SITE
                               AND ITEM_ID     = V_ITEM_ID
                               AND ROWNUM      = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN
                                NULL;
                        END;
                    END IF;
                END IF;

                /*
                판가 입력 정보 조회
                52주 구간 전부에 입력이 안되어있으면 신규 생성 불가
                현재 SSP는 내/외수를 구분하지 않기 때문에 DOM_EXP 타입을 DOM 로 강제로 설정 후 처리하였음(한개로 처리하기 위해서)
                */
                SELECT COUNT(*)
                  INTO V_PRICE_CHECK_CNT
                  FROM (SELECT DISTINCT A.DIVISION_ID
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.PLANT_SITE_ID
                             , A.ITEM_ID
                             , A.MEASURE
                             , 'DOM' AS DOM_EXP
                             , A.FCST_TYPE
                             , A.INCOTERMS
                             , COUNT(*) AS CNT
                          FROM SCM_MST_FUTURE_PRICE  A
                             , SCM_SYS_CALENDAR_M    B
                             , (SELECT MIN(BASIS_START_DATE) AS BASIS_START_DATE
                                     , MAX(BASIS_END_DATE)   AS BASIS_END_DATE
                                  FROM SCM_SYS_CALENDAR_M
                                 WHERE BASIS_YYYYMMDD BETWEEN TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')                    /* 당주 월요일부터 */
                                                          AND TO_CHAR(TO_DATE(TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD'), 'YYYYMMDD') + 84, 'YYYYMMDD')) IA   /* 12주후 월요일까지 */
                         WHERE B.BASIS_YYYYMMDD = A.YYYYMMDD
                           AND B.DAYOFWEEK      = 'MON'
                           AND A.DIVISION_ID    = V_DIVISION_ID
                           AND A.PROJECT_CODE   = CASE WHEN V_DIVISION_ID = '40' THEN V_PROJECT_CODE_40 ELSE V_PROJECT_CODE END
                           AND A.SCM_SITE_ID    = V_TO_SITE
                           AND A.ITEM_ID        = V_ITEM_ID
                           AND A.FCST_TYPE      = V_FCST_TYPE
                           AND A.INCOTERMS      = V_NEW_INCOTERMS
                           AND A.MEASURE        = 'KRW'
                           AND A.FCST_TYPE NOT IN (SELECT SEGMENT2
                                                     FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                                    WHERE LOOKUP_TYPE = 'MKT_FCST_VALIDATION_PRICE'
                                                      AND SEGMENT1    = 'FCST_TYPE'
                                                      AND VALID_YN    = 'Y')
                           AND A.YYYYMMDD BETWEEN IA.BASIS_START_DATE AND IA.BASIS_END_DATE
                         GROUP BY A.DIVISION_ID
                                , A.PROJECT_CODE
                                , A.SCM_SITE_ID
                                , A.PLANT_SITE_ID
                                , A.ITEM_ID
                                , A.MEASURE
                                , A.DOM_EXP
                                , A.FCST_TYPE
                                , A.INCOTERMS
                        HAVING COUNT(*) = 13);

                IF V_PRICE_CHECK_CNT > 1 THEN
                    V_PRICE_CHECK_CNT := 1;
                END IF;

                /* 해당 LOOKUP 등록 정보는 판가입력 정보를 Check 하지 않음 */
                SELECT COUNT(*)
                  INTO V_MKT_FCST_CHK_CNT
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'MKT_FCST_VALIDATION_PRICE'
                   AND SEGMENT1    = 'FCST_TYPE'
                   AND VALID_YN    = 'Y'
                   AND SEGMENT2    = V_FCST_TYPE;

                /* 법인간 거래이면 판가입력 정보를 Check 하지 않음 */
                IF (V_FROM_SITE_TYPE = 'B' AND V_TO_SITE_TYPE = 'B')
                OR (V_FROM_SITE_TYPE = 'B' AND V_TO_SITE_TYPE = 'C')
                OR (V_FROM_SITE_TYPE = 'C' AND V_TO_SITE_TYPE = 'C')
                OR (V_FROM_SITE_TYPE = 'C' AND V_TO_SITE_TYPE = 'B') THEN
                    V_PRICE_CHECK_CNT := 1;
                END IF;

                /* 판가 정보없고, 법인간 거래가 아니거나, LOOKUP에 등록된 FCST_TYPE이 아니면 RETURN */
                IF V_PRICE_CHECK_CNT = 1 THEN
                    V_PRICE_CHECK_CNT := 1;
                ELSIF V_MKT_FCST_CHK_CNT = 1 THEN
                    V_PRICE_CHECK_CNT := 1;
                ELSE
                    V_EVENT_DATE := SYSDATE;
                    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

                    OPEN O_RC1 FOR
                        SELECT 'F' AS RESULT_CODE
                          FROM DUAL;

                    P_OPEN_SUCCESS(O_RESULT_CURSOR);

                    RETURN;
                END IF;

                V_SHIPMENT_DATE := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');
                V_NEW_ETD_DATE  := REPLACE(SUBSTR(V_SHIPMENT_DATE, 1, 10), '-', '');
                V_ETA           := FN_GET_SSP_ETA_DATE(V_DIVISION_ID, V_NEW_BOD_ID, V_SHIPMENT_DATE);
                V_ETD           := FN_GET_SSP_ETD_DATE(V_DIVISION_ID, V_NEW_BOD_ID, V_SHIPMENT_DATE);

                V_LAST_UPDATE_DATE := SYSDATE;

                IF V_PROJECT_CODE IS NULL THEN
                    V_PROJECT_CODE := '-';
                END IF;

                INSERT INTO SSP_ANL_SHIP_CONFIRM
                (
                    CONFIRM_ID
                  , SHIPMENT_STATUS
                  , DIVISION_ID
                  , PLAN_START_YYYYMMDD
                  , PLAN_TYPE
                  , SEQ
                  , ITEM_ID
                  , FROM_SITE
                  , TO_SITE
                  , YYYYMMDD
                  , PLANNED_QTY
                  , QTY
                  , BOD_ID
                  , ROUTE_ID
                  , BIZ_TYPE
                  , PROJECT_CODE
                  , FCST_TYPE
                  , FCST_ETD_DATE
                  , FCST_ETA_DATE
                  , ETD_DATE
                  , ETA_DATE
                  , INCOTERMS
                  , TRANSPORT_MODE
                  , D_COUNTRY
                  , D_PORT_CODE
                  , A_COUNTRY
                  , A_PORT_CODE
                  , CUSTOMER_LT
                  , TO_COUNTRY
                  , TO_CITY
                  , FROM_SITE_TYPE
                  , FROM_SITE_PLANT_ID
                  , FROM_SITE_VENDOR_ID
                  , FROM_SITE_SOLDTO_CODE
                  , FROM_SITE_SHIPTO_CODE
                  , FROM_SITE_COMPANY_ID
                  , TO_SITE_TYPE
                  , TO_SITE_PLANT_ID
                  , TO_SITE_VENDOR_ID
                  , TO_SITE_SOLDTO_CODE
                  , TO_SITE_SHIPTO_CODE
                  , TO_SITE_COMPANY_ID
                  , CHANGE_TYPE
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                  , REMARKS
                  , REMARKS2
                  , REMARKS3
                  , ELECTRODE_YN
                  , ORIGIN_FROM_DIVISION_ID
                  , ORIGIN_TO_DIVISION_ID
                  , BEFORE_QTY
                  , CHECK_NEED_YN
                  , REQUESTOR
                  , ATTRIBUTE10
                  , ERP_ATTR1                                                       /* 20211018 SHINMYUNGSU 항목추가 */
                  , ERP_ATTR2
                  , ERP_ATTR3
                )
                VALUES
                (
                    V_NEW_CONFIRM_ID
                  , 'C'
                  , V_DIVISION_ID
                  , V_PLAN_START
                  , 'SP'
                  , V_SEQ_PLAN
                  , V_ITEM_ID
                  , V_FROM_SITE
                  , V_TO_SITE
                  , V_SHIPMENT_DATE
                  , 0
                  , TO_NUMBER(V_SHIPMENT_QTY)
                  , V_NEW_BOD_ID
                  , V_NEW_ROUTE_ID
                  , V_OPERATION_GROUP
                  , CASE WHEN V_DIVISION_ID = '40' THEN V_PROJECT_CODE_40 ELSE V_PROJECT_CODE END
                  , V_FCST_TYPE
                  , V_NEW_ETD_DATE
                  , V_ETA
                  , V_NEW_ETD_DATE
                  , V_ETA
                  , V_NEW_INCOTERMS
                  , V_NEW_TRANS_MODE
                  , V_NEW_D_CONTRY
                  , V_NEW_D_PORT_CODE
                  , V_NEW_A_COUNTRY
                  , V_NEW_A_PORT_CODE
                  , V_NEW_CUSTOMER_LT
                  , V_NEW_TO_COUNTRY
                  , V_NEW_TO_CITY
                  , V_FROM_SITE_TYPE
                  , V_FROM_SITE_PLANT
                  , V_FROM_SITE_VENDOR
                  , V_FROM_SITE_SOLDTO
                  , V_FROM_SITE_SHIPTO
                  , V_FROM_SITE_COMPANY
                  , V_TO_SITE_TYPE
                  , V_TO_SITE_PLANT
                  , V_TO_SITE_VENDOR
                  , V_TO_SITE_SOLDTO
                  , V_TO_SITE_SHIPTO
                  , V_TO_SITE_COMPANY
                  , 'N'
                  , P_USER_ID
                  , V_LAST_UPDATE_DATE
                  , P_USER_ID
                  , V_LAST_UPDATE_DATE
                  , V_REMARKS
                  , V_REMARKS2
                  , V_REMARKS3
                  , V_ELECTRODE_YN
                  , V_ORIGIN_FROM_DIV
                  , V_ORIGIN_TO_DIV
                  , 0
                  , 'Y'
                  , P_USER_ID
                  , 'I'
                  , V_ERP_ATTR1
                  , V_ERP_ATTR2
                  , V_ERP_ATTR3
                );

                /* 230226 jilee DM Confirm 동기화 추가 */
                PR_DM_SSP_CONFIRM_SYNC(V_DIVISION_ID, V_NEW_CONFIRM_ID);
            ELSIF V_VAL_CODE = 0 THEN
                V_RESULT_CODE := 'N';
            END IF;
        END LOOP;

        OPEN O_RC1 FOR
            SELECT V_RESULT_CODE    AS RESULT_CODE
                 , V_NEW_CONFIRM_ID AS CONFRIMID
              FROM DUAL;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########',
                             'Confrim_ID : ' || V_NEW_CONFIRM_ID || ' / Time Zone : ' || V_TMP_TIME_ZONE || ' / Seq : ' || TO_CHAR(V_SEQ),
                             V_EVENT_DATE);

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            ROLLBACK TO SP_SSP0200_SAVE_NEW;                                        /* 입력 데이타 롤백 처리 */

            P_WRITE_ERROR_LOG(V_PROGRAM_NAME, V_ERR);

            OPEN O_RC1 FOR
                SELECT 'F'  AS RESULT_CODE
                     , NULL AS CONFRIMID
                  FROM DUAL;

            P_OPEN_ERROR(V_ERR, O_RESULT_CURSOR);
    END P_SSP0200_SAVE_SHIPMENT_CONFIRM_NEW;

    /* ==============================================================================================
       SSP0200_SAVE_SHIPMENT_REQUEST_COMPLETE
       ============================================================================================== */
    PROCEDURE P_SSP0200_SAVE_SHIPMENT_REQUEST_COMPLETE
    (
        P_DIVISION_ID               IN  CLOB,
        P_FROM_SITE                 IN  CLOB,
        P_TITLE                     IN  VARCHAR2,
        P_REQUEST_ID                IN  VARCHAR2,
        P_REQUEST_DEPT_ID           IN  VARCHAR2,
        P_APPROVAL_ID               IN  VARCHAR2,
        P_APPROVAL_DEPT_ID          IN  VARCHAR2,
        P_CHANGE_REASON             IN  VARCHAR2,
        P_REASON_DETAIL             IN  VARCHAR2,
        P_LAST_UPDATED_BY           IN  VARCHAR2,
        P_MAIN_CONFIRM_ID           IN  CLOB,
        P_CONFIRM_ID                IN  CLOB,
        P_NEW_CONFIRM_ID            IN  CLOB,
        P_NEW_BOD_ID                IN  CLOB,
        P_NEW_ROUTE_ID              IN  CLOB,
        P_NEW_INCOTERMS             IN  CLOB,
        P_NEW_D_CONTRY              IN  CLOB,
        P_NEW_D_PORT_CODE           IN  CLOB,
        P_NEW_A_COUNTRY             IN  CLOB,
        P_NEW_A_PORT_CODE           IN  CLOB,
        P_NEW_TO_COUNTRY            IN  CLOB,
        P_NEW_TO_CITY               IN  CLOB,
        P_NEW_LT_DAY                IN  CLOB,
        P_CHANGE_STATUS             IN  VARCHAR2,
        P_NEW_ETD_DATE              IN  CLOB,
        P_NEW_ETA_DATE              IN  CLOB,
        P_NEW_TRANSPORT_MODE        IN  CLOB,
        P_SHIP_STATUS               IN  VARCHAR2,
        P_CHANGE_REQ_NO             IN  CLOB,
        P_NEW_SHIP_DATE             IN  CLOB,
        P_NEW_QTY                   IN  CLOB,
        P_NEW_YN                    IN  CLOB,
        P_TIME_ZONE                 IN  VARCHAR2,
        P_IF_SEND_FLAG              IN  VARCHAR2,
        P_CHANGE_TYPE               IN  VARCHAR2,
        P_PLAN_CONFIRM_ID           IN  CLOB,
        P_ELECTRODE_YN              IN  CLOB,
        P_ELECTRODE_TYPE            IN  CLOB,
        P_ORIGIN_FROM_DIVISION_ID   IN  CLOB,
        P_ORIGION_TO_DIVISION_ID    IN  CLOB,
        P_REMARKS                   IN  CLOB,
        P_REMARKS2                  IN  CLOB,
        P_REMARKS3                  IN  CLOB,
        P_REQUESTOR                 IN  VARCHAR2,
        P_AUTH                      IN  VARCHAR2,
        O_RC1                       OUT SYS_REFCURSOR,
        O_RESULT_CURSOR             OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_SAVE_SHIPMENT_REQUEST_COMPLETE
     * Description  : Shipment Change Request 작성중 저장
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2021/06/03   KIMYONGHO      최초작성
     * 2024/05/08   hsbang         SSP_ANL_SHIP_CONFIRM_CHG_REQ Status Insert(hsbang, 2024.05.08)
     * 2024/05/09   jilee          Unauthorized 부분 주석
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - MERGE 는 온라인 SQL 에서 쓰지 않으므로 UPDATE 후 바뀐 행이 없으면 INSERT 로 나눴다
     *                             - THROW 60001 -> RAISE_APPLICATION_ERROR(-20001) · 같은 번호는 이력을 남기지 않는다
     *                             - AS-IS 는 갱신을 확정(COMMIT)한 뒤 메일을 보내지만 확정은 호출한 쪽에 맡기고
     *                               순서만 같게 두었다
     *                             - 승인 권한 확인(Unauthorized) 구간은 AS-IS 에서 주석이라 옮기지 않았다
     */
        V_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'SSP0200_SAVE_SHIPMENT_REQUEST_COMPLETE';
        V_MAX_LOOP_CNT      PLS_INTEGER;
        V_TOK_MAIN_CONFIRM  T_TOKEN_TAB;
        V_TOK_DIVISION_ID   T_TOKEN_TAB;
        V_TOK_FROM_SITE     T_TOKEN_TAB;
        V_TOK_CHANGE_REQ    T_TOKEN_TAB;
        V_FOUND             T_FOUND_TAB;

        V_MAIN_CONFIRM_ID   VARCHAR2(4000 CHAR);
        V_DIVISION_ID       VARCHAR2(4000 CHAR);
        V_FROM_SITE         VARCHAR2(4000 CHAR);
        V_CHANGE_REQ_NO     VARCHAR2(4000 CHAR);
        V_ITEM_ID           VARCHAR2(4000 CHAR);
        V_MODEL_PIC         VARCHAR2(4000 CHAR);
        V_MODEL_PIC_TEMP    VARCHAR2(4000 CHAR);
        V_MODEL_PIC_TEMP2   VARCHAR2(4000 CHAR);
        V_ITEM_ID_TEMP      VARCHAR2(4000 CHAR);
        V_ITEM_ID_TEMP2     VARCHAR2(4000 CHAR);
        V_DEFAULT_GROUP_ID  VARCHAR2(4000 CHAR);
        V_MY_MODEL_CHK      PLS_INTEGER := 0;
        V_CHK               PLS_INTEGER := 0;
        V_SEQ               NUMBER;
        V_NEW_CONFIRM_ID    VARCHAR2(4000 CHAR) := TO_CHAR(P_NEW_CONFIRM_ID);
        V_LAST_UPDATE_DATE  DATE := SYSDATE;
        V_EVENT_DATE        DATE;
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        SAVEPOINT SP_SSP0200_SAVE_COMPLETE;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', V_EVENT_DATE);

        /* AS-IS 사용자 표의 기본 권한 그룹 -> 사용자 · 그룹 연결 표 (2026.09.22 실측 교정)
           사용자 표에 권한 그룹 칸이 없고 한 사람이 여러 그룹에 들 수 있어 1 행만 읽는다 */
        BEGIN
            SELECT USER_GR_ID
              INTO V_DEFAULT_GROUP_ID
              FROM SCM_ADM_USER_GR_MPG_M
             WHERE USER_ID = P_APPROVAL_ID
               AND USE_YN  = 'Y'
               AND ROWNUM  = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_DEFAULT_GROUP_ID := NULL;
        END;

        V_MAX_LOOP_CNT := F_SPL_CNT(P_MAIN_CONFIRM_ID);

        P_SPL_ARR(P_MAIN_CONFIRM_ID, V_MAX_LOOP_CNT, V_TOK_MAIN_CONFIRM, V_FOUND);
        P_SPL_ARR(P_DIVISION_ID,     V_MAX_LOOP_CNT, V_TOK_DIVISION_ID,  V_FOUND);
        P_SPL_ARR(P_FROM_SITE,       V_MAX_LOOP_CNT, V_TOK_FROM_SITE,    V_FOUND);
        P_SPL_ARR(P_CHANGE_REQ_NO,   V_MAX_LOOP_CNT, V_TOK_CHANGE_REQ,   V_FOUND);

        /* 다중 변경 시 동일 PIC · 동일 모델만 변경 가능 · 자가 승인 제한 확인 */
        FOR I IN 1 .. V_MAX_LOOP_CNT LOOP
            V_MAIN_CONFIRM_ID := V_TOK_MAIN_CONFIRM(I);
            V_DIVISION_ID     := V_TOK_DIVISION_ID(I);
            V_FROM_SITE       := V_TOK_FROM_SITE(I);
            V_ITEM_ID         := NULL;

            BEGIN
                SELECT ITEM_ID
                  INTO V_ITEM_ID
                  FROM SSP_ANL_SHIP_CONFIRM
                 WHERE CONFIRM_ID = V_MAIN_CONFIRM_ID;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_ITEM_ID := NULL;
            END;

            BEGIN
                SELECT USER_ID
                  INTO V_MODEL_PIC
                  FROM SSP_MST_MODEL_USER
                 WHERE ITEM_ID   = V_ITEM_ID
                   AND FROM_SITE = V_FROM_SITE;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN
                    V_MODEL_PIC := NULL;
                WHEN TOO_MANY_ROWS THEN
                    V_MODEL_PIC := NULL;
            END;

            V_MODEL_PIC_TEMP := V_MODEL_PIC;
            V_ITEM_ID_TEMP   := V_ITEM_ID;

            IF V_MODEL_PIC_TEMP <> V_MODEL_PIC_TEMP2 THEN
                RAISE_APPLICATION_ERROR(-20001, 'UnModelPic');                      /* ERROR 발생 시켜 UI에서 사용함 */
            END IF;

            IF V_ITEM_ID_TEMP <> V_ITEM_ID_TEMP2 THEN
                RAISE_APPLICATION_ERROR(-20001, 'UnModelItem');                     /* ERROR 발생 시켜 UI에서 사용함 */
            END IF;

            V_MODEL_PIC_TEMP2 := V_MODEL_PIC_TEMP;
            V_ITEM_ID_TEMP2   := V_ITEM_ID_TEMP;

            /* 자가 승인 제한 건 반영 - MY MODEL 확인 */
            SELECT V_MY_MODEL_CHK + COUNT(*)
              INTO V_MY_MODEL_CHK
              FROM SSP_MST_MODEL_USER      A
                 , SCM_MST_SSO_USER_INFO   B
                 , SCM_MST_SSO_DEPT_INFO   C
             WHERE B.USER_ID    = A.USER_ID
               AND C.DEPT_ID(+) = B.DEPT_ID
               AND A.DIVISION_ID = V_DIVISION_ID
               AND A.FROM_SITE   = V_FROM_SITE
               AND A.ITEM_ID     = V_ITEM_ID
               AND A.VALID_YN    = 'Y'
               AND A.USER_ID     = P_APPROVAL_ID;
        END LOOP;

        FOR I IN 1 .. V_MAX_LOOP_CNT LOOP
            V_MAIN_CONFIRM_ID := V_TOK_MAIN_CONFIRM(I);
            V_DIVISION_ID     := V_TOK_DIVISION_ID(I);
            V_FROM_SITE       := V_TOK_FROM_SITE(I);
            V_CHANGE_REQ_NO   := V_TOK_CHANGE_REQ(I);

            IF P_CHANGE_TYPE = 'P' THEN
                V_CHK := 0;

                BEGIN
                    SELECT CASE WHEN ATTRIBUTE1 IS NULL THEN 0 ELSE 1 END
                      INTO V_CHK
                      FROM SSP_ANL_SHIP_CONFIRM
                     WHERE CONFIRM_ID = V_MAIN_CONFIRM_ID;
                EXCEPTION
                    WHEN NO_DATA_FOUND THEN
                        V_CHK := 0;
                END;

                IF V_CHK = 0 THEN
                    SELECT SEQ1_SSP_ANL_SHIP_CONFIRM_ID.NEXTVAL
                      INTO V_SEQ
                      FROM DUAL;

                    V_NEW_CONFIRM_ID := 'C' || TO_CHAR(SYSDATE, 'YYYYMMDD') || SUBSTR('000000' || TO_CHAR(V_SEQ), -6);

                    UPDATE SSP_ANL_SHIP_CONFIRM
                       SET SHIPMENT_STATUS  = P_SHIP_STATUS
                         , CHANGE_REQ_NO    = V_CHANGE_REQ_NO
                         , ATTRIBUTE1       = V_NEW_CONFIRM_ID
                         , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                         , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                     WHERE CONFIRM_ID       = V_MAIN_CONFIRM_ID;
                ELSE
                    UPDATE SSP_ANL_SHIP_CONFIRM
                       SET SHIPMENT_STATUS  = P_SHIP_STATUS
                         , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                         , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                     WHERE CONFIRM_ID       = V_MAIN_CONFIRM_ID;
                END IF;
            ELSE
                UPDATE SSP_ANL_SHIP_CONFIRM
                   SET SHIPMENT_STATUS  = P_SHIP_STATUS
                     , CHANGE_REQ_NO    = V_CHANGE_REQ_NO
                     , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                     , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
                 WHERE CONFIRM_ID       = V_MAIN_CONFIRM_ID;
            END IF;

            /* SSP_ANL_SHIP_CONFIRM_CHG_REQ Status Insert(hsbang, 2024.05.08) */
            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
               SET ATTRIBUTE2       = P_CHANGE_STATUS
                 , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
             WHERE CHANGE_REQ_NO    = V_CHANGE_REQ_NO
               AND CONFIRM_ID       = V_MAIN_CONFIRM_ID;

            /* Shipment Request Info Insert(SSP_ANL_SHIP_CONFIRM_CHG_REQ) */
            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
               SET CHANGE_REQ_STATUS    = P_CHANGE_STATUS
                 , REQUEST_TITLE        = P_TITLE
                 , APPROVAL_USER        = P_APPROVAL_ID
                 , APPROVAL_DEPT        = P_APPROVAL_DEPT_ID
                 , CHANGE_REASON_CODE   = P_CHANGE_REASON
                 , CHANGE_REASON_DETAIL = P_REASON_DETAIL
                 , LAST_UPDATED_BY      = P_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE     = V_LAST_UPDATE_DATE
                 , REQUEST_TIME         = V_LAST_UPDATE_DATE
             WHERE CHANGE_REQ_NO        = V_CHANGE_REQ_NO;

            IF SQL%ROWCOUNT = 0 THEN
                INSERT INTO SSP_ANL_SHIP_CONFIRM_CHG_REQ
                (
                    CHANGE_REQ_NO
                  , CHANGE_REQ_STATUS
                  , DIVISION_ID
                  , FROM_SITE
                  , REQUEST_TITLE
                  , REQUEST_USER
                  , REQUEST_DEPT
                  , REQUEST_TIME
                  , APPROVAL_USER
                  , APPROVAL_DEPT
                  , APPROVAL_TIME
                  , CHANGE_REASON_CODE
                  , CHANGE_REASON_DETAIL
                  , REJECT_REASON
                  , VALID_YN
                  , CHANGE_TYPE
                  , CREATED_BY
                  , CREATION_DATE
                  , LAST_UPDATED_BY
                  , LAST_UPDATE_DATE
                  , ELECTRODE_YN
                  , ELECTRODE_TYPE
                  , ORIGIN_FROM_DIVISION_ID
                  , ORIGIN_TO_DIVISION_ID
                )
                VALUES
                (
                    V_CHANGE_REQ_NO
                  , P_SHIP_STATUS
                  , TO_CHAR(P_DIVISION_ID)
                  , TO_CHAR(P_FROM_SITE)
                  , P_TITLE
                  , P_REQUEST_ID
                  , P_REQUEST_DEPT_ID
                  , V_LAST_UPDATE_DATE
                  , P_APPROVAL_ID
                  , P_APPROVAL_DEPT_ID
                  , NULL
                  , P_CHANGE_REASON
                  , P_REASON_DETAIL
                  , NULL
                  , 'Y'
                  , P_CHANGE_TYPE
                  , P_LAST_UPDATED_BY
                  , V_LAST_UPDATE_DATE
                  , P_LAST_UPDATED_BY
                  , V_LAST_UPDATE_DATE
                  , SUBSTR(TO_CHAR(P_ELECTRODE_YN), 1, INSTR(TO_CHAR(P_ELECTRODE_YN), C_DELIMITER) - 1)
                  , SUBSTR(TO_CHAR(P_ELECTRODE_TYPE), 1, INSTR(TO_CHAR(P_ELECTRODE_TYPE), C_DELIMITER) - 1)
                  , SUBSTR(TO_CHAR(P_ORIGIN_FROM_DIVISION_ID), 1, INSTR(TO_CHAR(P_ORIGIN_FROM_DIVISION_ID), C_DELIMITER) - 1)
                  , SUBSTR(TO_CHAR(P_ORIGION_TO_DIVISION_ID), 1, INSTR(TO_CHAR(P_ORIGION_TO_DIVISION_ID), C_DELIMITER) - 1)
                );
            END IF;
        END LOOP;

        IF P_CHANGE_STATUS = 'Q' THEN
            /* 메일 발송 */
            SCM_SSP_MAIL_SEND(V_CHANGE_REQ_NO, P_CHANGE_STATUS);
        END IF;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

        OPEN O_RC1 FOR
            SELECT 'S'             AS RESULT_CODE
                 , V_CHANGE_REQ_NO AS REQUEST_NO
              FROM DUAL;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            ROLLBACK TO SP_SSP0200_SAVE_COMPLETE;                                   /* 입력 데이타 롤백 처리 */

            IF SQLCODE <> -20001 THEN                                               /* 자가 승인 제한건은 ERROR 로그 처리 안함 */
                P_WRITE_ERROR_LOG(V_PROGRAM_NAME, V_ERR);
            END IF;

            OPEN O_RC1 FOR
                SELECT 'F'  AS RESULT_CODE
                     , NULL AS REQUEST_NO
                  FROM DUAL;

            P_OPEN_ERROR(V_ERR, O_RESULT_CURSOR);
    END P_SSP0200_SAVE_SHIPMENT_REQUEST_COMPLETE;

    /* ==============================================================================================
       SSP0200_DELETE_SHIPMENT_REQUEST_DRAFTING
       ============================================================================================== */
    PROCEDURE P_SSP0200_DELETE_SHIPMENT_REQUEST_DRAFTING
    (
        P_CONFIRM_ID        IN  CLOB,
        P_CHANGE_REQUEST_NO IN  CLOB,
        P_DEL_FLAG          IN  VARCHAR2,
        P_LAST_UPDATED_BY   IN  VARCHAR2,
        P_TIME_ZONE         IN  VARCHAR2,
        P_IF_SEND_FLAG      IN  VARCHAR2,
        P_CHANGE_TYPE       IN  VARCHAR2,
        O_RC1               OUT SYS_REFCURSOR,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : SSP0200_DELETE_SHIPMENT_REQUEST_DRAFTING
     * Description  : Shipment Plan Change 작성중 삭제
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018/10/10   KIMYONGHO      최초작성
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - 되돌림값은 마지막 요청 번호 기준으로 확정 원장에 남은 행이 없으면 X
     *                             - 저장 시작에 SAVEPOINT · 되돌리기는 결과 커서를 열기 전에 수행
     */
        V_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'SSP0200_DELETE_SHIPMENT_REQUEST_DRAFTING';
        V_MAX_LOOP_CNT      PLS_INTEGER;
        V_TOK_CHANGE_REQ    T_TOKEN_TAB;
        V_TOK_CONFIRM_ID    T_TOKEN_TAB;
        V_FOUND             T_FOUND_TAB;
        V_CHANGE_REQ_NO     VARCHAR2(4000 CHAR);
        V_CONFIRM_ID        VARCHAR2(4000 CHAR);
        V_LAST_UPDATE_DATE  DATE := SYSDATE;
        V_EVENT_DATE        DATE;
        V_CNT               PLS_INTEGER := 0;
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        SAVEPOINT SP_SSP0200_DELETE_DRAFT;

        V_EVENT_DATE := V_LAST_UPDATE_DATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'START', 0, '########## Start of procedure ##########', '', V_EVENT_DATE);

        V_MAX_LOOP_CNT := F_SPL_CNT(P_CHANGE_REQUEST_NO);

        P_SPL_ARR(P_CHANGE_REQUEST_NO, V_MAX_LOOP_CNT, V_TOK_CHANGE_REQ, V_FOUND);
        P_SPL_ARR(P_CONFIRM_ID,        V_MAX_LOOP_CNT, V_TOK_CONFIRM_ID, V_FOUND);

        FOR I IN 1 .. V_MAX_LOOP_CNT LOOP
            V_CHANGE_REQ_NO := V_TOK_CHANGE_REQ(I);
            V_CONFIRM_ID    := V_TOK_CONFIRM_ID(I);

            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ
               SET VALID_YN         = 'N'
                 , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
             WHERE CHANGE_REQ_NO    = V_CHANGE_REQ_NO;

            UPDATE SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
               SET VALID_YN         = 'N'
                 , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
             WHERE CHANGE_REQ_NO    = V_CHANGE_REQ_NO;

            UPDATE SSP_ANL_SHIP_CONFIRM
               SET SHIPMENT_STATUS  = 'C'
                 , CHANGE_REQ_NO    = NULL
                 , ATTRIBUTE1       = NULL
                 , LAST_UPDATED_BY  = P_LAST_UPDATED_BY
                 , LAST_UPDATE_DATE = V_LAST_UPDATE_DATE
             WHERE CONFIRM_ID IN (SELECT CONFIRM_ID
                                    FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                   WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO);

            DELETE FROM SSP_ANL_SHIP_CONFIRM
             WHERE CONFIRM_ID IN (SELECT CONFIRM_ID
                                    FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                   WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO)
               AND CHANGE_TYPE = 'N';

            IF P_DEL_FLAG = 'D'
           AND P_IF_SEND_FLAG = 'Y' THEN
                PR_SSP_ANL_SHIP_CONFIRM_CHG_BATCH_NEW('D', V_CHANGE_REQ_NO, V_CONFIRM_ID);
            END IF;
        END LOOP;

        V_EVENT_DATE := SYSDATE;
        PR_SCM_SYS_LOG_BATCH_CALL_TRAN(V_PROGRAM_NAME, 'END', 0, '########## END of procedure ##########', '', V_EVENT_DATE);

        SELECT COUNT(*)
          INTO V_CNT
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE CONFIRM_ID IN (SELECT CONFIRM_ID
                                FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                               WHERE CHANGE_REQ_NO = V_CHANGE_REQ_NO);

        IF V_CNT < 1 THEN                                                           /* 데이터가 존재하지 않는경우 */
            OPEN O_RC1 FOR
                SELECT 'X' AS RESULT_CODE
                  FROM DUAL;
        ELSE
            OPEN O_RC1 FOR
                SELECT 'S' AS RESULT_CODE
                  FROM DUAL;
        END IF;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            ROLLBACK TO SP_SSP0200_DELETE_DRAFT;

            P_WRITE_ERROR_LOG(V_PROGRAM_NAME, V_ERR);

            OPEN O_RC1 FOR
                SELECT 'F' AS RESULT_CODE
                  FROM DUAL;

            P_OPEN_ERROR(V_ERR, O_RESULT_CURSOR);
    END P_SSP0200_DELETE_SHIPMENT_REQUEST_DRAFTING;

    /* ==============================================================================================
       PR_SSP_XIF_ERP_UI_SHIP_PLAN_IFSEQ_MERGE
       ============================================================================================== */
    PROCEDURE P_SSP0200_ERP_IFSEQ_MERGE
    (
        P_CHANGE_REQUEST_NO IN  VARCHAR2,
        P_STATUS            IN  VARCHAR2,
        O_RESULT_CURSOR     OUT SYS_REFCURSOR
    )
    IS
    /*
     * Program ID   : PR_SSP_XIF_ERP_UI_SHIP_PLAN_IFSEQ_MERGE
     * Description  : IFSEQ Number Merge후 UI SHIP PLAN 전송
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2024/04/29   jilee          IFSEQ Number Merge후 UI SHIP PLAN 전송
     * 2026.09.21                  [MSSQL -> Oracle 전환]
     *                             - TOP 1 + ORDER BY -> 인라인 뷰 정렬 후 ROWNUM = 1
     *                             - AS-IS 반복문은 주석이라 한 번만 수행한다
     */
        V_PROGRAM_NAME      CONSTANT VARCHAR2(150 CHAR) := 'PR_SSP_XIF_ERP_UI_SHIP_PLAN_IFSEQ_MERGE';
        V_IFSEQNO           VARCHAR2(14 CHAR);
        V_ERR               VARCHAR2(4000 CHAR);
    BEGIN
        /* 전송대상 IFSEQNO, LAST_CONFIRM_DATE, SHIPMENT_STATUS 조회 */
        BEGIN
            SELECT IFSEQNO
              INTO V_IFSEQNO
              FROM (SELECT IFSEQNO
                         , LAST_CONFIRM_DATE
                         , SHIPMENT_STATUS
                      FROM XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
                     WHERE TRANSFER_FLAG IN ('P', 'N')
                       AND ATTRIBUTE1     = P_CHANGE_REQUEST_NO
                     GROUP BY IFSEQNO
                            , LAST_CONFIRM_DATE
                            , SHIPMENT_STATUS
                     ORDER BY IFSEQNO DESC
                            , LAST_CONFIRM_DATE
                            , SHIPMENT_STATUS)
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_IFSEQNO := NULL;
        END;

        IF P_STATUS = 'C' THEN
            UPDATE XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
               SET IFSEQNO         = V_IFSEQNO
             WHERE ATTRIBUTE1      = P_CHANGE_REQUEST_NO
               AND SHIPMENT_STATUS = 'C'
               AND TRANSFER_FLAG  IN ('P', 'N');
        ELSE
            UPDATE XIF_ERP_SHIP_PLAN_CONFIRM_S_SN
               SET IFSEQNO         = V_IFSEQNO
             WHERE ATTRIBUTE1      = P_CHANGE_REQUEST_NO
               AND TRANSFER_FLAG  IN ('P', 'N');
        END IF;

        P_OPEN_SUCCESS(O_RESULT_CURSOR);
    EXCEPTION
        WHEN OTHERS THEN
            V_ERR := SUBSTR(SQLERRM, 1, 4000);

            P_WRITE_ERROR_LOG(V_PROGRAM_NAME, V_ERR);
            P_OPEN_ERROR(V_ERR, O_RESULT_CURSOR);
    END P_SSP0200_ERP_IFSEQ_MERGE;

END PKG_SSP0200;
/
SHOW ERRORS PACKAGE BODY PKG_SSP0200
-- ##### END PACKAGE BODY PKG_SSP0200

-- ##### START PACKAGE BODY PKG_SYS0010
CREATE OR REPLACE PACKAGE BODY PKG_SYS0010 
AS

	PROCEDURE P_SYS0010_GET_LOOKUP_MASTER (
      P_LOOKUP_TYPE   IN  VARCHAR2
    , P_LOOKUP_GROUP  IN  VARCHAR2
    , P_VALID_YN      IN  VARCHAR2
    , O_RC1           OUT SYS_REFCURSOR
    , O_RESULT_CURSOR OUT SYS_REFCURSOR
	)
/*
 * Program ID   : P_SYS0010_GET_LOOKUP_MASTER
 * Description  : Lookup Master 조회(AS-IS : SCM0003_GET_LOOKUP_MASTER)
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2017/12/14   byunghunjung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.04.13   park.choyi     [PJ20264226] NextSCM Pilot 화면 및 메뉴 개발
 */

IS
		--V_ERR_MSG 	VARCHAR2(4000);

	BEGIN
    OPEN O_RC1 FOR
        SELECT
              LOOKUP_TYPE AS LOOKUP_TYPE_KEY
            , LOOKUP_TYPE
            , DESCRIPTION
            , LOOKUP_GROUP
            , VALID_YN
            , SEGMENT1
            , SEGMENT2
            , SEGMENT3
            , SEGMENT4
            , SEGMENT5
            , ATTRIBUTE1
            , ATTRIBUTE2
            , ATTRIBUTE3
            , ATTRIBUTE4
            , ATTRIBUTE5
            , ATTRIBUTE6
            , ATTRIBUTE7
            , ATTRIBUTE8
            , ATTRIBUTE9
            , ATTRIBUTE10
            , ATTRIBUTE11
            , ATTRIBUTE12
            , ATTRIBUTE13
            , ATTRIBUTE14
            , ATTRIBUTE15
            , CREATED_BY
            , CREATION_DATE
            , LAST_UPDATED_BY
            , LAST_UPDATE_DATE
--        FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER
        FROM SCM_ADM_LOOKUP_MASTER                                                                          -- 2026.09.17 AJS
        WHERE (TRIM(P_LOOKUP_TYPE)  IS NULL OR UPPER(LOOKUP_TYPE)  LIKE '%' || UPPER(TRIM(P_LOOKUP_TYPE)) || '%')
--          AND (TRIM(P_LOOKUP_GROUP) IS NULL OR LOOKUP_GROUP = TRIM(P_LOOKUP_GROUP))
--          AND (TRIM(P_VALID_YN)     IS NULL OR VALID_YN     = TRIM(P_VALID_YN))
          AND (TRIM(P_LOOKUP_GROUP) IS NULL OR LOOKUP_GROUP = UPPER(TRIM(P_LOOKUP_GROUP)))                  -- 2026.09.17 AJS
          AND (TRIM(P_VALID_YN)     IS NULL OR VALID_YN     = UPPER(TRIM(P_VALID_YN)))                      -- 2026.09.17 AJS
--        ORDER BY LOOKUP_TYPE;
        -- 2026.09.17 AJS AS-IS 정렬 기준 (START)
        ORDER BY UPPER(REPLACE(REPLACE(LOOKUP_TYPE, '-', ''), '_', '/' || CHR(127)))
               , LENGTH(LOOKUP_TYPE)
               , LOOKUP_TYPE;
        -- 2026.09.17 AJS AS-IS 정렬 기준 (END)

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'SUCCESS' AS MSG, '0' AS EVENT
        FROM DUAL;

		EXCEPTION
		    WHEN OTHERS THEN
		        ROLLBACK;
		        RAISE_APPLICATION_ERROR(-20001,
		        '[' || $$PLSQL_UNIT || '] SQLCODE=' || TO_CHAR(SQLCODE) ||
		        ' / SQLERRM=' || SQLERRM ||
		        ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
		        ' / PARAMS=' || '-' );

	END P_SYS0010_GET_LOOKUP_MASTER;

  PROCEDURE P_SYS0010_GET_LOOKUP_MASTER_DETAIL (
      P_LOOKUP_TYPE   IN  VARCHAR2
    , O_RC1           OUT SYS_REFCURSOR
    , O_RESULT_CURSOR OUT SYS_REFCURSOR
  )
/*
 * Program ID   : P_SYS0010_GET_LOOKUP_MASTER_DETAIL
 * Description  : Lookup Value 조회(AS-IS : SCM0003_GET_LOOKUP_MASTER_DETAIL)
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2017/12/14   byunghunjung   Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2021/05/26   khj79          [PJ20209642] LGES Digital SCM Level.3 달성을 위한 개선 - 공유잠금 해제 옵션 추가
 * 2026.04.21   park.choyi     [PJ20264226] NextSCM Pilot 화면 및 메뉴 개발
 */

IS
    --V_ERR_MSG   VARCHAR2(4000);

  BEGIN
    OPEN O_RC1 FOR
        SELECT
              LOOKUP_TYPE
            , DESCRIPTION
            , DISPLAY_SEQ
            , VALID_YN
            , SEGMENT1
            , SEGMENT2
            , SEGMENT3
            , SEGMENT4
            , SEGMENT5
            , ATTRIBUTE1
            , ATTRIBUTE2
            , ATTRIBUTE3
            , ATTRIBUTE4
            , ATTRIBUTE5
            , ATTRIBUTE6
            , ATTRIBUTE7
            , ATTRIBUTE8
            , ATTRIBUTE9
            , ATTRIBUTE10
            , ATTRIBUTE11
            , ATTRIBUTE12
            , ATTRIBUTE13
            , ATTRIBUTE14
            , ATTRIBUTE15
            , CREATED_BY
            , CREATION_DATE
            , LAST_UPDATED_BY
            , LAST_UPDATE_DATE
--        FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL
        FROM SCM_ADM_LOOKUP_MASTER_DETAIL                                                                   -- 2026.09.17 AJS
        WHERE (TRIM(P_LOOKUP_TYPE)  IS NULL OR LOOKUP_TYPE = TRIM(P_LOOKUP_TYPE) )
--        ORDER BY DISPLAY_SEQ;
        -- 2026.09.17 AJS AS-IS 정렬 기준(표시순서 빈 값 먼저) (START)
        ORDER BY DISPLAY_SEQ NULLS FIRST
               , SEGMENT1
               , SEGMENT2
               , SEGMENT3
               , SEGMENT4
               , SEGMENT5;
        -- 2026.09.17 AJS AS-IS 정렬 기준(표시순서 빈 값 먼저) (END)

    OPEN O_RESULT_CURSOR FOR
        SELECT '0' AS CODE, 'SUCCESS' AS MSG, '0' AS EVENT
        FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE_APPLICATION_ERROR(-20001,
            '[' || $$PLSQL_UNIT || '] SQLCODE=' || TO_CHAR(SQLCODE) ||
            ' / SQLERRM=' || SQLERRM ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || '-' );

  END P_SYS0010_GET_LOOKUP_MASTER_DETAIL;

  PROCEDURE P_SYS0010_SAVE_LOOKUP_MASTER (
      P_DATA         IN CLOB
    , P_USER_ID      IN  VARCHAR2
    , O_RESULT_CURSOR    OUT SYS_REFCURSOR
  )
/*
 * Program ID   : P_SYS0010_SAVE_LOOKUP_MASTER
 * Description  : Lookup Type 등록, 수정(AS-IS : SCM0003_SAVE_LOOKUP_MASTER)
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2017/12/07   byunghunjung	Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2019/01/29	hwyoon			[PS02199094B] GSCM(DM/SCP) SM운영/유지보수 LTRIM, RTRIM 적용
 * 2026.04.21   park.choyi     [PJ20264226] NextSCM Pilot 화면 및 메뉴 개발
 * 2026.06.23	byunmj0223		MultiRow 등록, 수정을 위하여 LOOP문 적용
 */
  IS
      V_ACTIVE_FLAG      VARCHAR2(1);
      V_LOOKUP_TYPE_KEY  VARCHAR2(200);
      V_LOOKUP_TYPE      VARCHAR2(200);
      V_DESCRIPTION      VARCHAR2(1000);
      V_LOOKUP_GROUP     VARCHAR2(200);
      V_VALID_YN         VARCHAR2(2);
      V_SEGMENT1         VARCHAR2(100);
      V_SEGMENT2         VARCHAR2(100);
      V_SEGMENT3         VARCHAR2(100);
      V_SEGMENT4         VARCHAR2(100);
      V_SEGMENT5         VARCHAR2(100);
--      V_ATTRIBUTE1       VARCHAR2(100);
      V_ATTRIBUTE1       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE2       VARCHAR2(100);
      V_ATTRIBUTE2       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE3       VARCHAR2(100);
      V_ATTRIBUTE3       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE4       VARCHAR2(100);
      V_ATTRIBUTE4       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE5       VARCHAR2(100);
      V_ATTRIBUTE5       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE6       VARCHAR2(100);
      V_ATTRIBUTE6       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE7       VARCHAR2(100);
      V_ATTRIBUTE7       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE8       VARCHAR2(100);
      V_ATTRIBUTE8       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE9       VARCHAR2(100);
      V_ATTRIBUTE9       VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE10      VARCHAR2(100);
      V_ATTRIBUTE10      VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE11      VARCHAR2(100);
      V_ATTRIBUTE11      VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE12      VARCHAR2(100);
      V_ATTRIBUTE12      VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE13      VARCHAR2(100);
      V_ATTRIBUTE13      VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE14      VARCHAR2(100);
      V_ATTRIBUTE14      VARCHAR2(150);   -- 2026.09.17 AJS
--      V_ATTRIBUTE15      VARCHAR2(100);
      V_ATTRIBUTE15      VARCHAR2(150);   -- 2026.09.17 AJS
      --V_CREATED_BY       VARCHAR2(300);
      --V_CREATION_DATE    DATE;
      --V_LAST_UPDATED_BY  VARCHAR2(300);
      --V_CREATION_DATE_STR VARCHAR2(30);

      V_PROGRAM_NAME     VARCHAR2(150) := 'SCM0003_SAVE_LOOKUP_MASTER';
      V_LOG_TYPE         VARCHAR2(30);
      N_LOG_COUNT        NUMBER := 0;
      V_LOG_MESSAGE      VARCHAR2(1000);
      V_LOG_DESC         VARCHAR2(500);
      D_EVENT_DATE       DATE;


      V_RESULT_CURSOR    SYS_REFCURSOR;
      V_CODE           VARCHAR2(10);
      V_MSG            VARCHAR2(4000);
      V_EVENT          VARCHAR2(100);



  BEGIN
      -- 2026.09.17 AJS 저장 시작 지점 · 이력 1회 기록 (START)
      SAVEPOINT SP_SYS0010_SAVE_M;

      P_SYS0010_SAVE_LOOKUP_MASTER_HIST(P_DATA, P_USER_ID, V_RESULT_CURSOR);

      FETCH V_RESULT_CURSOR INTO V_CODE, V_MSG, V_EVENT;
      CLOSE V_RESULT_CURSOR;
      -- 2026.09.17 AJS 저장 시작 지점 · 이력 1회 기록 (END)

      -- JSON -> 변수 매핑
	  FOR JT IN (
	      SELECT
	            JT.CRUD_TYPE AS V_ACTIVE_FLAG
	          , JT.LOOKUP_TYPE_KEY AS V_LOOKUP_TYPE_KEY
	          , JT.LOOKUP_TYPE AS V_LOOKUP_TYPE
	          , JT.DESCRIPTION AS V_DESCRIPTION
	          , JT.LOOKUP_GROUP AS V_LOOKUP_GROUP
	          , JT.VALID_YN AS V_VALID_YN
	          , NVL(TRIM(JT.SEGMENT1), '/') AS V_SEGMENT1
	          , NVL(TRIM(JT.SEGMENT2), '/') AS V_SEGMENT2
	          , NVL(TRIM(JT.SEGMENT3), '/') AS V_SEGMENT3
	          , NVL(TRIM(JT.SEGMENT4), '/') AS V_SEGMENT4
	          , NVL(TRIM(JT.SEGMENT5), '/') AS V_SEGMENT5
	          , JT.ATTRIBUTE1 AS V_ATTRIBUTE1
	          , JT.ATTRIBUTE2 AS V_ATTRIBUTE2
	          , JT.ATTRIBUTE3 AS V_ATTRIBUTE3
	          , JT.ATTRIBUTE4 AS V_ATTRIBUTE4
	          , JT.ATTRIBUTE5 AS V_ATTRIBUTE5
	          , JT.ATTRIBUTE6 AS V_ATTRIBUTE6
	          , JT.ATTRIBUTE7 AS V_ATTRIBUTE7
	          , JT.ATTRIBUTE8 AS V_ATTRIBUTE8
	          , JT.ATTRIBUTE9 AS V_ATTRIBUTE9
	          , JT.ATTRIBUTE10 AS V_ATTRIBUTE10
	          , JT.ATTRIBUTE11 AS V_ATTRIBUTE11
	          , JT.ATTRIBUTE12 AS V_ATTRIBUTE12
	          , JT.ATTRIBUTE13 AS V_ATTRIBUTE13
	          , JT.ATTRIBUTE14 AS V_ATTRIBUTE14
	          , JT.ATTRIBUTE15 AS V_ATTRIBUTE15	          
	      FROM JSON_TABLE(
	          P_DATA
	        , '$[*]'
	          -- 2026.09.17 AJS 입력 칸 길이·오류 처리 (START)
--	          COLUMNS (
--	                CRUD_TYPE          VARCHAR2(1)    PATH '$.CRUD_TYPE'
--	              , LOOKUP_TYPE_KEY    VARCHAR2(200)  PATH '$.LOOKUP_TYPE_KEY'
--	              , LOOKUP_TYPE        VARCHAR2(200)  PATH '$.LOOKUP_TYPE'
--	              , DESCRIPTION        VARCHAR2(1000) PATH '$.DESCRIPTION' NULL ON EMPTY NULL ON ERROR
--	              , LOOKUP_GROUP       VARCHAR2(200)  PATH '$.LOOKUP_GROUP'
--	              , VALID_YN           VARCHAR2(2)    PATH '$.VALID_YN'
--	              , SEGMENT1           VARCHAR2(100)  PATH '$.SEGMENT1' NULL ON EMPTY NULL ON ERROR
--	              , SEGMENT2           VARCHAR2(100)  PATH '$.SEGMENT2' NULL ON EMPTY NULL ON ERROR
--	              , SEGMENT3           VARCHAR2(100)  PATH '$.SEGMENT3' NULL ON EMPTY NULL ON ERROR
--	              , SEGMENT4           VARCHAR2(100)  PATH '$.SEGMENT4' NULL ON EMPTY NULL ON ERROR
--	              , SEGMENT5           VARCHAR2(100)  PATH '$.SEGMENT5' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE1         VARCHAR2(100)  PATH '$.ATTRIBUTE1' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE2         VARCHAR2(100)  PATH '$.ATTRIBUTE2' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE3         VARCHAR2(100)  PATH '$.ATTRIBUTE3' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE4         VARCHAR2(100)  PATH '$.ATTRIBUTE4' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE5         VARCHAR2(100)  PATH '$.ATTRIBUTE5' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE6         VARCHAR2(100)  PATH '$.ATTRIBUTE6' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE7         VARCHAR2(100)  PATH '$.ATTRIBUTE7' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE8         VARCHAR2(100)  PATH '$.ATTRIBUTE8' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE9         VARCHAR2(100)  PATH '$.ATTRIBUTE9' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE10        VARCHAR2(100)  PATH '$.ATTRIBUTE10' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE11        VARCHAR2(100)  PATH '$.ATTRIBUTE11' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE12        VARCHAR2(100)  PATH '$.ATTRIBUTE12' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE13        VARCHAR2(100)  PATH '$.ATTRIBUTE13' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE14        VARCHAR2(100)  PATH '$.ATTRIBUTE14' NULL ON EMPTY NULL ON ERROR
--	              , ATTRIBUTE15        VARCHAR2(100)  PATH '$.ATTRIBUTE15' NULL ON EMPTY NULL ON ERROR
--	              --, CREATED_BY         VARCHAR2(300)  PATH '$.CREATED_BY' NULL ON EMPTY NULL ON ERROR
--	              --, CREATION_DATE_STR  VARCHAR2(30)   PATH '$.CREATION_DATE' NULL ON EMPTY NULL ON ERROR
--	              --, LAST_UPDATED_BY    VARCHAR2(300)  PATH '$.LAST_UPDATED_BY' NULL ON EMPTY NULL ON ERROR
--	          )
	          COLUMNS (
	                CRUD_TYPE          VARCHAR2(1)    PATH '$.CRUD_TYPE'
	              , LOOKUP_TYPE_KEY    VARCHAR2(200)  PATH '$.LOOKUP_TYPE_KEY'
	              , LOOKUP_TYPE        VARCHAR2(200)  PATH '$.LOOKUP_TYPE'
	              , DESCRIPTION        VARCHAR2(1000) PATH '$.DESCRIPTION' NULL ON EMPTY ERROR ON ERROR
	              , LOOKUP_GROUP       VARCHAR2(200)  PATH '$.LOOKUP_GROUP'
	              , VALID_YN           VARCHAR2(2)    PATH '$.VALID_YN'
	              , SEGMENT1           VARCHAR2(100)  PATH '$.SEGMENT1' NULL ON EMPTY ERROR ON ERROR
	              , SEGMENT2           VARCHAR2(100)  PATH '$.SEGMENT2' NULL ON EMPTY ERROR ON ERROR
	              , SEGMENT3           VARCHAR2(100)  PATH '$.SEGMENT3' NULL ON EMPTY ERROR ON ERROR
	              , SEGMENT4           VARCHAR2(100)  PATH '$.SEGMENT4' NULL ON EMPTY ERROR ON ERROR
	              , SEGMENT5           VARCHAR2(100)  PATH '$.SEGMENT5' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE1         VARCHAR2(150)  PATH '$.ATTRIBUTE1' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE2         VARCHAR2(150)  PATH '$.ATTRIBUTE2' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE3         VARCHAR2(150)  PATH '$.ATTRIBUTE3' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE4         VARCHAR2(150)  PATH '$.ATTRIBUTE4' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE5         VARCHAR2(150)  PATH '$.ATTRIBUTE5' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE6         VARCHAR2(150)  PATH '$.ATTRIBUTE6' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE7         VARCHAR2(150)  PATH '$.ATTRIBUTE7' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE8         VARCHAR2(150)  PATH '$.ATTRIBUTE8' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE9         VARCHAR2(150)  PATH '$.ATTRIBUTE9' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE10        VARCHAR2(150)  PATH '$.ATTRIBUTE10' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE11        VARCHAR2(150)  PATH '$.ATTRIBUTE11' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE12        VARCHAR2(150)  PATH '$.ATTRIBUTE12' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE13        VARCHAR2(150)  PATH '$.ATTRIBUTE13' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE14        VARCHAR2(150)  PATH '$.ATTRIBUTE14' NULL ON EMPTY ERROR ON ERROR
	              , ATTRIBUTE15        VARCHAR2(150)  PATH '$.ATTRIBUTE15' NULL ON EMPTY ERROR ON ERROR
	              --, CREATED_BY         VARCHAR2(300)  PATH '$.CREATED_BY' NULL ON EMPTY NULL ON ERROR
	              --, CREATION_DATE_STR  VARCHAR2(30)   PATH '$.CREATION_DATE' NULL ON EMPTY NULL ON ERROR
	              --, LAST_UPDATED_BY    VARCHAR2(300)  PATH '$.LAST_UPDATED_BY' NULL ON EMPTY NULL ON ERROR
	          )
	          -- 2026.09.17 AJS 입력 칸 길이·오류 처리 (END)
	      ) JT
	  ) LOOP

	  V_ACTIVE_FLAG := NVL(TRIM(JT.V_ACTIVE_FLAG), '');	  
      V_LOOKUP_TYPE_KEY := NVL(TRIM(JT.V_LOOKUP_TYPE_KEY), '');
      V_LOOKUP_TYPE     := NVL(TRIM(JT.V_LOOKUP_TYPE), '');
	  V_DESCRIPTION		:= NVL(TRIM(JT.V_DESCRIPTION), '');
	  V_LOOKUP_GROUP	:= NVL(TRIM(JT.V_LOOKUP_GROUP), '');
	  V_VALID_YN		:= NVL(TRIM(JT.V_VALID_YN), '');
      V_SEGMENT1        := NVL(TRIM(JT.V_SEGMENT1), '');
      V_SEGMENT2        := NVL(TRIM(JT.V_SEGMENT2), '');
      V_SEGMENT3        := NVL(TRIM(JT.V_SEGMENT3), '');
      V_SEGMENT4        := NVL(TRIM(JT.V_SEGMENT4), '');
      V_SEGMENT5        := NVL(TRIM(JT.V_SEGMENT5), '');
	  V_ATTRIBUTE1      := NVL(TRIM(JT.V_ATTRIBUTE1), ''); 
	  V_ATTRIBUTE2      := NVL(TRIM(JT.V_ATTRIBUTE2), '');
	  V_ATTRIBUTE3      := NVL(TRIM(JT.V_ATTRIBUTE3), '');
	  V_ATTRIBUTE4      := NVL(TRIM(JT.V_ATTRIBUTE4), '');
	  V_ATTRIBUTE5      := NVL(TRIM(JT.V_ATTRIBUTE5), '');
	  V_ATTRIBUTE6      := NVL(TRIM(JT.V_ATTRIBUTE6), '');
	  V_ATTRIBUTE7      := NVL(TRIM(JT.V_ATTRIBUTE7), '');
	  V_ATTRIBUTE8      := NVL(TRIM(JT.V_ATTRIBUTE8), '');
	  V_ATTRIBUTE9      := NVL(TRIM(JT.V_ATTRIBUTE9), '');
	  V_ATTRIBUTE10      := NVL(TRIM(JT.V_ATTRIBUTE10), '');
	  V_ATTRIBUTE11      := NVL(TRIM(JT.V_ATTRIBUTE11), '');
	  V_ATTRIBUTE12      := NVL(TRIM(JT.V_ATTRIBUTE12), '');
	  V_ATTRIBUTE13      := NVL(TRIM(JT.V_ATTRIBUTE13), '');
	  V_ATTRIBUTE14      := NVL(TRIM(JT.V_ATTRIBUTE14), '');
	  V_ATTRIBUTE15      := NVL(TRIM(JT.V_ATTRIBUTE15), '');

      /*
      IF V_CREATION_DATE_STR IS NOT NULL THEN
          V_CREATION_DATE := TO_DATE(V_CREATION_DATE_STR, 'YYYY-MM-DD HH24:MI:SS');
      ELSE
          V_CREATION_DATE := SYSDATE;
      END IF;
      */
      V_LOG_TYPE    := 'START';
      V_LOG_MESSAGE := '########## Start of procedure ##########';
      V_LOG_DESC    := '';
      D_EVENT_DATE  := SYSDATE;

      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESC, D_EVENT_DATE);

      -- 2026.09.17 AJS 행마다 전체 이력 재기록 제거 (START)
--      P_SYS0010_SAVE_LOOKUP_MASTER_HIST(P_DATA, P_USER_ID, V_RESULT_CURSOR );
--
--      -- 결과 커서 읽기
--      FETCH V_RESULT_CURSOR INTO V_CODE, V_MSG, V_EVENT;
--      CLOSE V_RESULT_CURSOR;
--
--      DBMS_OUTPUT.PUT_LINE('CODE=' || V_CODE || ', MSG=' || V_MSG || ', EVENT=' || V_EVENT);
      -- 2026.09.17 AJS 행마다 전체 이력 재기록 제거 (END)

      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESC, D_EVENT_DATE);

      IF V_ACTIVE_FLAG = 'I' THEN
          INSERT INTO SCM_ADM_LOOKUP_MASTER (
                LOOKUP_TYPE
              , DESCRIPTION
              , LOOKUP_GROUP
              , VALID_YN
              , SEGMENT1
              , SEGMENT2
              , SEGMENT3
              , SEGMENT4
              , SEGMENT5
              , CREATED_BY
              , CREATION_DATE
              , LAST_UPDATED_BY
              , LAST_UPDATE_DATE
              , ATTRIBUTE1
              , ATTRIBUTE2
              , ATTRIBUTE3
              , ATTRIBUTE4
              , ATTRIBUTE5
              , ATTRIBUTE6
              , ATTRIBUTE7
              , ATTRIBUTE8
              , ATTRIBUTE9
              , ATTRIBUTE10
              , ATTRIBUTE11
              , ATTRIBUTE12
              , ATTRIBUTE13
              , ATTRIBUTE14
              , ATTRIBUTE15
          ) VALUES (
                V_LOOKUP_TYPE
              , V_DESCRIPTION
              , V_LOOKUP_GROUP
              , V_VALID_YN
              , V_SEGMENT1
              , V_SEGMENT2
              , V_SEGMENT3
              , V_SEGMENT4
              , V_SEGMENT5
              , P_USER_ID
              , SYSDATE
              , P_USER_ID
              , SYSDATE
              , V_ATTRIBUTE1
              , V_ATTRIBUTE2
              , V_ATTRIBUTE3
              , V_ATTRIBUTE4
              , V_ATTRIBUTE5
              , V_ATTRIBUTE6
              , V_ATTRIBUTE7
              , V_ATTRIBUTE8
              , V_ATTRIBUTE9
              , V_ATTRIBUTE10
              , V_ATTRIBUTE11
              , V_ATTRIBUTE12
              , V_ATTRIBUTE13
              , V_ATTRIBUTE14
              , V_ATTRIBUTE15
          );
      
      ELSIF V_ACTIVE_FLAG = 'D' THEN
          /* 삭제 — 기존에는 'D' 가 아래 ELSE 의 UPDATE 로 흘러가 행이 지워지지 않았다.
             키는 UPDATE 와 동일하게 V_LOOKUP_TYPE_KEY(조회 SP 가 내려준 원본 이름)를 쓴다. */
          DELETE FROM SCM_ADM_LOOKUP_MASTER
          	WHERE LOOKUP_TYPE = V_LOOKUP_TYPE_KEY;

          DELETE FROM SCM_ADM_LOOKUP_MASTER_DETAIL
       		WHERE LOOKUP_TYPE = V_LOOKUP_TYPE_KEY;
          
          N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;
          
      ELSE
          UPDATE SCM_ADM_LOOKUP_MASTER
             SET LOOKUP_TYPE      = V_LOOKUP_TYPE
               , DESCRIPTION      = V_DESCRIPTION
               , LOOKUP_GROUP     = V_LOOKUP_GROUP
               , VALID_YN         = V_VALID_YN
               , SEGMENT1         = V_SEGMENT1
               , SEGMENT2         = V_SEGMENT2
               , SEGMENT3         = V_SEGMENT3
               , SEGMENT4         = V_SEGMENT4
               , SEGMENT5         = V_SEGMENT5
               , LAST_UPDATED_BY  = P_USER_ID
               , LAST_UPDATE_DATE = SYSDATE
               , ATTRIBUTE1       = V_ATTRIBUTE1
               , ATTRIBUTE2       = V_ATTRIBUTE2
               , ATTRIBUTE3       = V_ATTRIBUTE3
               , ATTRIBUTE4       = V_ATTRIBUTE4
               , ATTRIBUTE5       = V_ATTRIBUTE5
               , ATTRIBUTE6       = V_ATTRIBUTE6
               , ATTRIBUTE7       = V_ATTRIBUTE7
               , ATTRIBUTE8       = V_ATTRIBUTE8
               , ATTRIBUTE9       = V_ATTRIBUTE9
               , ATTRIBUTE10      = V_ATTRIBUTE10
               , ATTRIBUTE11      = V_ATTRIBUTE11
               , ATTRIBUTE12      = V_ATTRIBUTE12
               , ATTRIBUTE13      = V_ATTRIBUTE13
               , ATTRIBUTE14      = V_ATTRIBUTE14
               , ATTRIBUTE15      = V_ATTRIBUTE15
           WHERE LOOKUP_TYPE = V_LOOKUP_TYPE_KEY;

           N_LOG_COUNT := N_LOG_COUNT + SQL%ROWCOUNT;

          IF V_LOOKUP_TYPE_KEY <> V_LOOKUP_TYPE THEN
              UPDATE SCM_ADM_LOOKUP_MASTER_DETAIL
                 SET LOOKUP_TYPE = V_LOOKUP_TYPE
               WHERE LOOKUP_TYPE = V_LOOKUP_TYPE_KEY;
          END IF;
      END IF;
  	END LOOP;    

  	COMMIT;

  	V_LOG_TYPE    := 'END';
  	V_LOG_MESSAGE := '########## END of procedure ##########';
  	V_LOG_DESC    := '';
  	D_EVENT_DATE  := SYSDATE;

  	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESC, D_EVENT_DATE);

    OPEN O_RESULT_CURSOR FOR
         SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(N_LOG_COUNT) AS EVENT FROM DUAL;

  EXCEPTION
      WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SQLERRM;
        V_LOG_DESC    := TO_CHAR(SQLCODE);
        D_EVENT_DATE  := SYSDATE;

        -- 2026.09.17 AJS 오류 시 저장분 되돌리기 (START)
        BEGIN
            ROLLBACK TO SAVEPOINT SP_SYS0010_SAVE_M;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
        -- 2026.09.17 AJS 오류 시 저장분 되돌리기 (END)

        PR_SCM_SYS_LOG_BATCH(
            V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_LOG_DESC, D_EVENT_DATE
        );

        RAISE_APPLICATION_ERROR(-20001,
        '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_LOG_DESC ||
        ' / SQLERRM=' || V_LOG_MESSAGE ||
        ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
        ' / PARAMS=' || '-' );

  END P_SYS0010_SAVE_LOOKUP_MASTER;

  PROCEDURE P_SYS0010_SAVE_LOOKUP_MASTER_HIST (
      P_DATA         IN CLOB
    , P_USER_ID      IN  VARCHAR2
    , O_RESULT_CURSOR    OUT SYS_REFCURSOR
  )
/*
 * Program ID   : P_SYS0010_SAVE_LOOKUP_MASTER_HIST
 * Description  : Lookup Type History(AS-IS : PR_SCM_ADM_LOOKUP_MASTER_HIST)
 * Program History
 *===========================================================================================================
 *   Date       In Charge      Description
 *===========================================================================================================
 * 2017.12.15   byunghunjung      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.04.21   park.choyi     [PJ20264226] NextSCM Pilot 화면 및 메뉴 개발
 * 2026.06.23	byunmj0223		MultiRow 등록, 수정을 위하여 LOOP문 적용
 */
  IS
--      V_LOOKUP_TYPE        NVARCHAR2(200);
      V_LOOKUP_TYPE        VARCHAR2(200);   -- 2026.09.17 AJS
--      V_DESCRIPTION        NVARCHAR2(1000);
      V_DESCRIPTION        VARCHAR2(1000);   -- 2026.09.17 AJS
--      V_LOOKUP_GROUP       NVARCHAR2(200);
      V_LOOKUP_GROUP       VARCHAR2(200);   -- 2026.09.17 AJS
