PROCEDURE P_SYS0013_GET_PARAMETERS
(
    P_DQ_ID           IN  VARCHAR2,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : [DMF0006_GET_CUSTOMERMODELMAPPING]                                                           */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2018/03/12  SeungJae.Hwnag       Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2026.03.18  jcnam       [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/*                                                                                                  */
/****************************************************************************************************/
AS
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
BEGIN

    OPEN O_RC1 FOR
    SELECT DQ_ID
         , PARAMETER_ID
         , PARAMETER_TYPE
         , OPERATION_ID
         , VALID_YN
         , REP_YN
         , CREATED_BY
         , CREATION_DATE
         , LAST_UPDATED_BY
         , LAST_UPDATE_DATE
         , NVL(ATTRIBUTE1, '0') AS SEQNO,
   NVL(ATTRIBUTE2, '') AS DEFAULT_VALUE

    FROM   SCM_ADM_DQ_PARAMETER A
    WHERE  DQ_ID = P_DQ_ID
    ORDER BY TO_NUMBER(NVL(ATTRIBUTE1, '0')), LAST_UPDATE_DATE;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := JSON_OBJECT(
            'P_DQ_ID' VALUE P_DQ_ID
        );
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, 'ERROR', N_LOG_COUNT, 'EXCEPTION',
                '', SYSDATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END P_SYS0013_GET_PARAMETERS;

PROCEDURE P_SYS0013_GET_QUERY_LIST_COMMON
(
    P_NICKNAME        IN  VARCHAR2,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
)
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/* 2018/03/12  SeungJae.Hwnag      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2026.03.18  jcnam       [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/*                                                                                                  */
/****************************************************************************************************/
AS
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
BEGIN

    IF P_NICKNAME = 'COLTYPES' THEN

        OPEN O_RC1 FOR
        SELECT 'System.String' AS CODE, 'String' AS NAME FROM DUAL
        UNION ALL
        SELECT 'System.Int' AS CODE, 'Int' AS NAME FROM DUAL
        UNION ALL
        SELECT 'System.Date' AS CODE, 'Date' AS NAME FROM DUAL;

    ELSIF P_NICKNAME = 'COMBO' THEN

        OPEN O_RC1 FOR
        SELECT 'DIVISION_ID' AS CODE, 'DIVISION_ID' AS NAME FROM DUAL
        UNION ALL
        SELECT 'SCM_SITE_ID' AS CODE, 'SCM_SITE_ID' AS NAME FROM DUAL;

    ELSIF P_NICKNAME = 'AGGREGATE' THEN

        OPEN O_RC1 FOR
        --SELECT 'GROUP' AS CODE, 'GROUP' AS NAME FROM DUAL
        --UNION ALL
        SELECT 'SUM' AS CODE, 'SUM' AS NAME FROM DUAL
        UNION ALL
        SELECT 'MAX' AS CODE, 'MAX' AS NAME FROM DUAL
        UNION ALL
        SELECT 'MIN' AS CODE, 'MIN' AS NAME FROM DUAL
        UNION ALL
        SELECT 'COUNT' AS CODE, 'COUNT' AS NAME FROM DUAL;

    ELSIF P_NICKNAME = 'OPORATOR' THEN

        OPEN O_RC1 FOR
        SELECT '=' AS CODE, '=' AS NAME FROM DUAL
        UNION ALL
        SELECT 'IN' AS CODE, 'IN' AS NAME FROM DUAL
        UNION ALL
        SELECT 'LIKE' AS CODE, 'LIKE' AS NAME FROM DUAL
        UNION ALL
        SELECT '>' AS CODE, '>' AS NAME FROM DUAL
        UNION ALL
        SELECT '<' AS CODE, '<' AS NAME FROM DUAL;

    ELSIF P_NICKNAME = 'ROLES' THEN

        OPEN O_RC1 FOR
        SELECT  USER_GR_ID AS CODE,
                USER_GR_NM AS NAME
        FROM   SCM_ADM_USER_GR_M
        WHERE  USE_YN = 'Y';

    ELSIF P_NICKNAME = 'BIZ_TYPE' THEN

        OPEN O_RC1 FOR
        SELECT SEGMENT1 AS CODE
             , SEGMENT2 AS NAME
        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
        WHERE  LOOKUP_TYPE = 'BIZ_TYPE_BPMS'
        ORDER BY DISPLAY_SEQ;

    ELSIF P_NICKNAME = 'ITEM_TYPE_CODE' THEN

        OPEN O_RC1 FOR
        SELECT SEGMENT1 AS CODE
             , SEGMENT2 AS NAME
        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
        WHERE  VALID_YN     = 'Y'
        AND    LOOKUP_TYPE  = 'ITEM_TYPE_CODE'
        ORDER BY DISPLAY_SEQ;

    ELSIF P_NICKNAME = 'INCOTERMS' THEN

        OPEN O_RC1 FOR
        SELECT SEGMENT1 AS CODE
             , SEGMENT2 AS NAME
        FROM   SCM_ADM_LOOKUP_MASTER_DETAIL
        WHERE  VALID_YN     = 'Y'
        AND    LOOKUP_TYPE  = 'INCOTERMS'
        ORDER BY DISPLAY_SEQ;

    ELSE

        OPEN O_RC1 FOR
        SELECT NULL AS CODE, NULL AS NAME FROM DUAL WHERE 1 = 0;

    END IF;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_PROC_INPUT := JSON_OBJECT(
            'P_NICKNAME' VALUE P_NICKNAME
        );
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, 'ERROR', N_LOG_COUNT, 'EXCEPTION',
                '', SYSDATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        RAISE_APPLICATION_ERROR(-20001,
            '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
            ' / SQLERRM=' || V_SQL_ERRMSG ||
            ' / BACKTRACE=' || V_BACKTRACE ||
            ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;

END P_SYS0013_GET_QUERY_LIST_COMMON;


PROCEDURE P_SYS0013_GET_QUERY_LIST
(
    P_DQ_NAME            IN VARCHAR2,
    P_DESCRIPTION        IN VARCHAR2,
    P_ROLE               IN VARCHAR2,
    P_USER_ID         IN VARCHAR2, -- For EditYn
    P_MNU_ID          IN VARCHAR2, -- For EditYn
    O_RC1                OUT SYS_REFCURSOR,
    O_RESULT_CURSOR      OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : [DMF0006_GET_CUSTOMERMODELMAPPING]                                                           */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                              */
/*--------------------------------------------------------------------------------------------------*/
/* 2018/03/12  SeungJae.Hwnag      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2026.03.17   jcnam        [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/****************************************************************************************************/
IS
    -- [SYS0013_GET_QUERY_LIST] '','','DM/SCP'
    -- EXEC SYS0013_GET_QUERY_LIST @p_dq_id='33', @p_dq_name='', @p_role=''

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── 메인 조회 결과 반환 (O_RC1) ── */
    OPEN O_RC1 FOR
    WITH SPLIT_DESCRIPTION AS (
        SELECT TRIM(REGEXP_SUBSTR(P_DESCRIPTION, '[^,]+', 1, LEVEL)) AS TOKEN
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(P_DESCRIPTION, '[^,]+', 1, LEVEL) IS NOT NULL
    ),
    SPLIT_DQ_NAME AS (
        SELECT TRIM(REGEXP_SUBSTR(P_DQ_NAME, '[^,]+', 1, LEVEL)) AS TOKEN
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(P_DQ_NAME, '[^,]+', 1, LEVEL) IS NOT NULL
    ),
    SPLIT_ROLE AS (
        SELECT TRIM(REGEXP_SUBSTR(P_ROLE, '[^,]+', 1, LEVEL)) AS TOKEN
        FROM DUAL
        CONNECT BY REGEXP_SUBSTR(P_ROLE, '[^,]+', 1, LEVEL) IS NOT NULL
    ),
    TMPDQ AS (
        SELECT
             A.DQ_ID
            ,A.DIVISION_ID
            ,A.DQ_NAME
            ,A.DESCRIPTION
            ,A.DQ_TEXT
            ,A.VALID_YN
            ,A.ADMIN_ONLY_YN
            ,A.CREATED_BY
            ,A.CREATION_DATE
            ,A.LAST_UPDATED_BY
            ,A.LAST_UPDATE_DATE
            ,'ALL,' || NVL(
                (SELECT LISTAGG(B.GROUP_ID, ',') WITHIN GROUP (ORDER BY B.GROUP_ID)
                 FROM SCM_ADM_DQ_USER_GROUP B
                 LEFT JOIN SCM_ADM_USER_GR_M C
                   ON B.GROUP_ID = C.USER_GR_ID
                  AND C.USE_YN = 'Y'
                 WHERE B.VALID_YN = 'Y'
                   AND B.DQ_ID = A.DQ_ID
                ), '') AS GROUP_ID
            ,NVL(
                (SELECT LISTAGG(C.USER_GR_NM, ',') WITHIN GROUP (ORDER BY C.USER_GR_NM)
                 FROM SCM_ADM_DQ_USER_GROUP B
                 LEFT JOIN SCM_ADM_USER_GR_M C
                   ON B.GROUP_ID = C.USER_GR_ID
                  AND C.USE_YN = 'Y'
                 WHERE B.VALID_YN = 'Y'
                   AND B.DQ_ID = A.DQ_ID
                ), 'ALL') AS GROUP_NAME
            , NVL((SELECT MAX(T2A.EDIT_YN) FROM SCM_ADM_USER_MNU_EDIT_AUTH_V T2A
                    WHERE T2A.USER_ID=P_USER_ID AND T2A.MNU_ID=P_MNU_ID AND T2A.UNIT_TP_CD='D'
                      AND (A.DIVISION_ID=T2A.UNIT_ID OR A.DIVISION_ID='/')), 'N') AS EDIT_YN
        FROM SCM_ADM_DQ_LIST A
        WHERE EXISTS (
            SELECT 1 FROM SCM_ADM_USER_MNU_EDIT_AUTH_V T2
            WHERE T2.USER_ID=P_USER_ID AND T2.MNU_ID=P_MNU_ID AND T2.UNIT_TP_CD='D'
              AND (A.DIVISION_ID=T2.UNIT_ID OR A.DIVISION_ID='/')
        )
        AND (P_DQ_NAME IS NULL OR EXISTS (SELECT 1 FROM SPLIT_DQ_NAME P WHERE UPPER(A.DQ_NAME) LIKE UPPER(P.TOKEN) || '%'))
        AND (P_DESCRIPTION IS NULL OR EXISTS (SELECT 1 FROM SPLIT_DESCRIPTION P WHERE UPPER(A.DESCRIPTION) LIKE UPPER(P.TOKEN) || '%'))
    )
    SELECT
         DQ_ID
        ,DIVISION_ID
        ,DQ_NAME
        ,DESCRIPTION
        ,DQ_TEXT
        ,VALID_YN
        ,ADMIN_ONLY_YN
        ,CREATED_BY
        ,CREATION_DATE
        ,LAST_UPDATED_BY
        ,LAST_UPDATE_DATE
        ,GROUP_ID
        ,GROUP_NAME
        ,EDIT_YN
    FROM TMPDQ
    WHERE 1 = 1
      AND (P_ROLE IS NULL OR EXISTS (SELECT 1 FROM SPLIT_ROLE P WHERE GROUP_ID LIKE '%' || P.TOKEN || '%'))
     ORDER BY TO_NUMBER(DQ_ID);

    /* ── 프로시저 처리 결과 반환 (O_RESULT_CURSOR) — 조회 성공 ── */
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        -- 1) 트랜잭션이 있으면 ROLLBACK
        ROLLBACK;

        -- 2) 에러 정보 캡처
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DQ_NAME' VALUE P_DQ_NAME,
            'P_DESCRIPTION'   VALUE P_DESCRIPTION,
            'P_ROLE'    VALUE P_ROLE,
            'P_USER_ID'   VALUE P_USER_ID,
            'P_MNU_ID'   VALUE P_MNU_ID
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        -- 3) 에러 로그 기록
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        -- 4) 에러 전파 (O_RESULT_CURSOR 미오픈)
        RAISE_APPLICATION_ERROR(-20001,
          '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;
END P_SYS0013_GET_QUERY_LIST;

PROCEDURE P_SYS0013_GET_COLUMNS
(
    P_DQ_ID              IN VARCHAR2,
    --P_DQ_NAME            IN VARCHAR2,
    --P_ROLE               IN VARCHAR2,
    O_RC1                OUT SYS_REFCURSOR,
    O_RESULT_CURSOR      OUT SYS_REFCURSOR
)
/****************************************************************************************************/
/* Program ID  : [DMF0006_GET_CUSTOMERMODELMAPPING]                                                           */
/* Description : Procedure 작성 가이드                                                              */
/* Usage       : Procedure 작성 시 참조하세요!                                                      */
/* Parameter   :                                                                                    */
/*                                                                                                  */
/*--------------------------------------------------------------------------------------------------*/
/* Date        In Charge    Description                                                             */
/*--------------------------------------------------------------------------------------------------*/
/*2018/03/12  SeungJae.Hwnag     Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트 */
/* 2026.03.18   jcnam        [PJ20264226] NextSCM Pilot 설계 및 개발                                  */
/*                                                                                                  */
/****************************************************************************************************/
IS
    -- [] '2','',''
    -- EXEC SYS0013_GET_COLUMNS @p_dq_id='27'

    /* ── EXCEPTION 블록 필수 변수 ── */
    V_PROC_INPUT    VARCHAR2(4000 CHAR);
    V_BACKTRACE     VARCHAR2(4000 CHAR);
    V_SQL_CODE      VARCHAR2(100 CHAR);
    V_SQL_ERRMSG    VARCHAR2(1000 CHAR);
    V_LOG_TYPE      VARCHAR2(100 CHAR);
    V_LOG_MESSAGE   VARCHAR2(4000 CHAR);
    V_DESCRIPTION   VARCHAR2(4000 CHAR);
    N_LOG_COUNT     PLS_INTEGER := 0;
    D_EVENT_DATE    DATE := SYSDATE;

BEGIN

    /* ── 시작 로그 ── */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

    /* ── 메인 조회 결과 반환 (O_RC1) ── */
    OPEN O_RC1 FOR
    SELECT A.DQ_ID
          ,A.COLUMN_NAME
          ,A.VALUE_YN
          ,A.VALUE_TYPE
          ,A.VALID_YN
          ,A.CREATED_BY
          ,A.CREATION_DATE
          ,A.LAST_UPDATED_BY
          ,A.LAST_UPDATE_DATE
          ,NVL(A.ATTRIBUTE1, '0') AS SEQNO
          ,A.ATTRIBUTE2 AS AGGREGATE   -- AGGREGATE(SUM/MAX/MIN/COUNT)=ATTRIBUTE2 (2026-06-26)
    FROM SCM_ADM_DQ_COLUMN A
    WHERE A.VALID_YN = 'Y'
      AND A.DQ_ID = P_DQ_ID
    ORDER BY TO_NUMBER(NVL(A.ATTRIBUTE1, '0')), A.LAST_UPDATE_DATE;
    /*
    WHERE
    CASE WHEN @p_dq_id = '' THEN ''
            ELSE A.[DQ_ID]
    END IN (
            Select * from dbo.UF_FX_String_SplitForIN (@p_dq_id,',') as P Where
            (CASE WHEN @p_dq_id = '' THEN '' ELSE A.[DQ_ID] END) = P.data
            )
    AND
    Exists (Select * from dbo.UF_FX_String_Split (@p_dq_name,',') as P Where A.DQ_NAME LIKE P.token +'%')
    */

    /* ── 프로시저 처리 결과 반환 (O_RESULT_CURSOR) — 조회 성공 ── */
    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1 = 2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

    /* ── 종료 로그 ── */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN SCM_MGR.PR_SCM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE); END;

EXCEPTION
    WHEN OTHERS THEN
        -- 1) 트랜잭션이 있으면 ROLLBACK
        ROLLBACK;

        -- 2) 에러 정보 캡처
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := 'EXCEPTION';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        V_SQL_CODE    := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG  := SQLERRM;
        V_PROC_INPUT  := JSON_OBJECT(
            'P_DQ_ID' VALUE P_DQ_ID
        );
        V_BACKTRACE   := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;

        -- 3) 에러 로그 기록
        BEGIN
            SCM_MGR.PR_SCM_SYS_LOG_BATCH(
                $$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE,
                V_DESCRIPTION, D_EVENT_DATE, V_PROC_INPUT,
                V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE
            );
        END;

        -- 4) 에러 전파 (O_RESULT_CURSOR 미오픈)
        RAISE_APPLICATION_ERROR(-20001,
          '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
          ' / SQLERRM=' || V_SQL_ERRMSG ||
          ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
          ' / PARAMS=' || V_PROC_INPUT
        );
        RAISE;
END P_SYS0013_GET_COLUMNS;



  PROCEDURE P_SYS0013_SAVE_QUERY_LIST
  (
    P_DATA          IN  CLOB,
    P_USER_ID       IN  VARCHAR2,
    O_RC1           OUT SYS_REFCURSOR,
    O_RC2           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
  )
  AS
    V_SQL_CODE    VARCHAR2(100 CHAR);
    V_SQL_ERRMSG  VARCHAR2(1000 CHAR);
    V_BACKTRACE   VARCHAR2(4000 CHAR);
    V_NEW_DQ_ID   NUMBER;
    V_AFFECTED    NUMBER := 0;
    V_USER        VARCHAR2(600 CHAR) := NVL(P_USER_ID, 'admin');
  	V_INDEX       NUMBER := 0;
  	V_NEW_DQ_ID_LIST  VARCHAR2(4000 CHAR);
  BEGIN
    FOR rec IN (
      SELECT *
        FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
            CRUD_TYPE       VARCHAR2(10)   PATH '$.CRUD_TYPE',
            DQ_ID           NUMBER         PATH '$.DQ_ID',
            DIVISION_ID     VARCHAR2(50)   PATH '$.DIVISION_ID',
            DQ_NAME         VARCHAR2(2000) PATH '$.DQ_NAME',
            DESCRIPTION     VARCHAR2(4000) PATH '$.DESCRIPTION',
            DQ_TEXT         CLOB           PATH '$.DQ_TEXT',
            VALID_YN        VARCHAR2(4)    PATH '$.VALID_YN',
            ADMIN_ONLY_YN   VARCHAR2(4)    PATH '$.ADMIN_ONLY_YN'
        ))
    ) LOOP
      IF rec.CRUD_TYPE = 'I' THEN
        SELECT NVL(MAX(DQ_ID), 0) + 1 INTO V_NEW_DQ_ID FROM SCM_ADM_DQ_LIST;
        INSERT INTO SCM_ADM_DQ_LIST (
          DQ_ID, DIVISION_ID, DQ_NAME, DESCRIPTION, DQ_TEXT,
          VALID_YN, ADMIN_ONLY_YN,
          CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
        ) VALUES (
          V_NEW_DQ_ID,
          NVL(NULLIF(RTRIM(rec.DIVISION_ID),''), '/'),
          NVL(rec.DQ_NAME, ''),
          NVL(rec.DESCRIPTION, ''),
          rec.DQ_TEXT,
          NVL(rec.VALID_YN, 'Y'),
          NVL(rec.ADMIN_ONLY_YN, 'N'),
          V_USER, SYSDATE, V_USER, SYSDATE
        );
        V_AFFECTED := V_AFFECTED + 1;

		IF V_INDEX = 0 THEN
			V_NEW_DQ_ID_LIST := TO_CHAR(V_NEW_DQ_ID);
		ELSE
			V_NEW_DQ_ID_LIST := ',' || TO_CHAR(V_NEW_DQ_ID);
		END IF;

   		V_INDEX := V_INDEX + 1;
      ELSIF rec.CRUD_TYPE = 'M' THEN
        UPDATE SCM_ADM_DQ_LIST
           SET DIVISION_ID      = NVL(rec.DIVISION_ID, DIVISION_ID),
               DQ_NAME          = NVL(rec.DQ_NAME, DQ_NAME),
               DESCRIPTION      = NVL(rec.DESCRIPTION, DESCRIPTION),
               DQ_TEXT          = NVL(rec.DQ_TEXT, DQ_TEXT),
               VALID_YN         = NVL(rec.VALID_YN, VALID_YN),
               ADMIN_ONLY_YN    = NVL(rec.ADMIN_ONLY_YN, ADMIN_ONLY_YN),
               LAST_UPDATED_BY  = V_USER,
               LAST_UPDATE_DATE = SYSDATE
         WHERE DQ_ID = rec.DQ_ID;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      ELSIF rec.CRUD_TYPE = 'D' THEN
        DELETE FROM SCM_ADM_DQ_LIST WHERE DQ_ID = rec.DQ_ID;
   		-- 굳이 아래 P_SYS0013_SAVE_COLUMNS, P_SYS0013_SAVE_PARAMETERS 프로시저에서 개별로 삭제하는 것이 아니라
   		-- 마스터성 SCM_ADM_DQ_LIST 테이블의 데이터가 지워지는 시점에 같이 지울 수 있도록 처리.
   		DELETE FROM SCM_ADM_DQ_COLUMN WHERE DQ_ID = rec.DQ_ID;
   		DELETE FROM SCM_ADM_DQ_PARAMETER WHERE DQ_ID = rec.DQ_ID;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      END IF;
    END LOOP;



    OPEN O_RC1 FOR
      SELECT V_AFFECTED AS AFFECTED FROM DUAL;
    OPEN O_RC2 FOR
      SELECT LISTAGG(V_NEW_DQ_ID_LIST, ',') AS DQ_ID FROM DUAL;
    OPEN O_RESULT_CURSOR FOR
      SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1=2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      V_SQL_CODE   := TO_CHAR(SQLCODE);
      V_SQL_ERRMSG := SQLERRM;
      V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      RAISE_APPLICATION_ERROR(-20001,
        '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
        ' / SQLERRM=' || V_SQL_ERRMSG ||
        ' / BACKTRACE=' || V_BACKTRACE);
  END P_SYS0013_SAVE_QUERY_LIST;


  PROCEDURE P_SYS0013_SAVE_COLUMNS
  (
    P_DATA          IN  CLOB,
    P_USER_ID       IN  VARCHAR2,
    O_RC1           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
  )
  AS
    V_SQL_CODE    VARCHAR2(100 CHAR);
    V_SQL_ERRMSG  VARCHAR2(1000 CHAR);
    V_BACKTRACE   VARCHAR2(4000 CHAR);
    V_AFFECTED    NUMBER := 0;
    V_USER        VARCHAR2(600 CHAR) := NVL(P_USER_ID, 'admin');
  BEGIN
    FOR rec IN (
      SELECT *
        FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
            CRUD_TYPE       VARCHAR2(10)   PATH '$.CRUD_TYPE',
            DQ_ID           NUMBER         PATH '$.DQ_ID',
            COLUMN_NAME     VARCHAR2(200)  PATH '$.COLUMN_NAME',
            VALUE_YN        VARCHAR2(4)    PATH '$.VALUE_YN',
            VALUE_TYPE      VARCHAR2(200)  PATH '$.VALUE_TYPE',
            VALID_YN        VARCHAR2(4)    PATH '$.VALID_YN',
            SEQNO           VARCHAR2(20)   PATH '$.SEQNO',
            AGGREGATE       VARCHAR2(20)   PATH '$.AGGREGATE'
        ))
    ) LOOP
      IF rec.CRUD_TYPE = 'I' THEN
        INSERT INTO SCM_ADM_DQ_COLUMN (
          DQ_ID, COLUMN_NAME, VALUE_YN, VALUE_TYPE, VALID_YN,
          CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2
        ) VALUES (
          rec.DQ_ID, rec.COLUMN_NAME,
          NVL(rec.VALUE_YN, 'Y'), NVL(rec.VALUE_TYPE, 'System.String'), NVL(rec.VALID_YN, 'Y'),
          V_USER, SYSDATE, V_USER, SYSDATE, NVL(rec.SEQNO, '0'), rec.AGGREGATE
        );
        V_AFFECTED := V_AFFECTED + 1;
      ELSIF rec.CRUD_TYPE = 'M' THEN
        UPDATE SCM_ADM_DQ_COLUMN
           SET VALUE_YN         = NVL(rec.VALUE_YN, VALUE_YN),
               VALUE_TYPE       = NVL(rec.VALUE_TYPE, VALUE_TYPE),
               VALID_YN         = NVL(rec.VALID_YN, VALID_YN),
               ATTRIBUTE1       = NVL(rec.SEQNO, ATTRIBUTE1),
               ATTRIBUTE2       = NVL(rec.AGGREGATE, ATTRIBUTE2),
               LAST_UPDATED_BY  = V_USER,
               LAST_UPDATE_DATE = SYSDATE
         WHERE DQ_ID = rec.DQ_ID AND COLUMN_NAME = rec.COLUMN_NAME;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      ELSIF rec.CRUD_TYPE = 'D' THEN
        DELETE FROM SCM_ADM_DQ_COLUMN WHERE DQ_ID = rec.DQ_ID AND COLUMN_NAME = rec.COLUMN_NAME;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      END IF;
    END LOOP;

    OPEN O_RC1 FOR SELECT V_AFFECTED AS AFFECTED FROM DUAL;
    OPEN O_RESULT_CURSOR FOR
      SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1=2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      V_SQL_CODE   := TO_CHAR(SQLCODE);
      V_SQL_ERRMSG := SQLERRM;
      V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      RAISE_APPLICATION_ERROR(-20001,
        '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
        ' / SQLERRM=' || V_SQL_ERRMSG ||
        ' / BACKTRACE=' || V_BACKTRACE);
  END P_SYS0013_SAVE_COLUMNS;

  PROCEDURE P_SYS0013_SAVE_PARAMETERS
  (
    P_DATA          IN  CLOB,
    P_USER_ID       IN  VARCHAR2,
    O_RC1           OUT SYS_REFCURSOR,
    O_RESULT_CURSOR OUT SYS_REFCURSOR
  )
  AS
    V_SQL_CODE    VARCHAR2(100 CHAR);
    V_SQL_ERRMSG  VARCHAR2(1000 CHAR);
    V_BACKTRACE   VARCHAR2(4000 CHAR);
    V_AFFECTED    NUMBER := 0;
    V_USER        VARCHAR2(600 CHAR) := NVL(P_USER_ID, 'admin');
  BEGIN
    FOR rec IN (
      SELECT *
        FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
            CRUD_TYPE       VARCHAR2(10)   PATH '$.CRUD_TYPE',
            DQ_ID           NUMBER         PATH '$.DQ_ID',
            PARAMETER_ID    VARCHAR2(200)  PATH '$.PARAMETER_ID',
            PARAMETER_TYPE  VARCHAR2(50)   PATH '$.PARAMETER_TYPE',
            OPERATION_ID    VARCHAR2(10)   PATH '$.OPERATION_ID',
            VALID_YN        VARCHAR2(4)    PATH '$.VALID_YN',
            REP_YN          VARCHAR2(4)    PATH '$.REP_YN',
            SEQNO           VARCHAR2(20)   PATH '$.SEQNO',
            DEFAULT_VALUE   VARCHAR2(600)  PATH '$.DEFAULT_VALUE'
        ))
    ) LOOP
      IF rec.CRUD_TYPE = 'I' THEN
        INSERT INTO SCM_ADM_DQ_PARAMETER (
          DQ_ID, PARAMETER_ID, PARAMETER_TYPE, OPERATION_ID,
          VALID_YN, REP_YN,
          CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE,
          ATTRIBUTE1, ATTRIBUTE2
        ) VALUES (
          rec.DQ_ID, rec.PARAMETER_ID,
          NVL(rec.PARAMETER_TYPE, 'Parameter'),
          rec.OPERATION_ID,
          NVL(rec.VALID_YN, 'Y'),
          NVL(rec.REP_YN, 'N'),
          V_USER, SYSDATE, V_USER, SYSDATE,
          NVL(rec.SEQNO, '0'),
          rec.DEFAULT_VALUE
        );
        V_AFFECTED := V_AFFECTED + 1;
      ELSIF rec.CRUD_TYPE = 'M' THEN
        UPDATE SCM_ADM_DQ_PARAMETER
           SET PARAMETER_TYPE   = NVL(rec.PARAMETER_TYPE, PARAMETER_TYPE),
               OPERATION_ID     = NVL(rec.OPERATION_ID, OPERATION_ID),
               VALID_YN         = NVL(rec.VALID_YN, VALID_YN),
               REP_YN           = NVL(rec.REP_YN, REP_YN),
               ATTRIBUTE1       = NVL(rec.SEQNO, ATTRIBUTE1),
               ATTRIBUTE2       = NVL(rec.DEFAULT_VALUE, ATTRIBUTE2),
               LAST_UPDATED_BY  = V_USER,
               LAST_UPDATE_DATE = SYSDATE
         WHERE DQ_ID = rec.DQ_ID AND PARAMETER_ID = rec.PARAMETER_ID;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      ELSIF rec.CRUD_TYPE = 'D' THEN
        DELETE FROM SCM_ADM_DQ_PARAMETER
         WHERE DQ_ID = rec.DQ_ID AND PARAMETER_ID = rec.PARAMETER_ID;
        V_AFFECTED := V_AFFECTED + SQL%ROWCOUNT;
      END IF;
    END LOOP;

    OPEN O_RC1 FOR SELECT V_AFFECTED AS AFFECTED FROM DUAL;
    OPEN O_RESULT_CURSOR FOR
      SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1=2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      V_SQL_CODE   := TO_CHAR(SQLCODE);
      V_SQL_ERRMSG := SQLERRM;
      V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      RAISE_APPLICATION_ERROR(-20001,
        '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
        ' / SQLERRM=' || V_SQL_ERRMSG ||
        ' / BACKTRACE=' || V_BACKTRACE);
  END P_SYS0013_SAVE_PARAMETERS;


  -- ▼▼▼ 추가 (2026-07-15) — 사내 PKG_SYS0013 원문 1:1 ▼▼▼
  -- ==========================================================================
  -- [2026-07-09 D2] SQL 사전검증 — DBMS_SQL PARSE + DESCRIBE (실행 없음, side-effect 0)
  --   AS-IS SCM0005 팝업 Confirm('SELECT TOP 0' 시험실행 → 컬럼 역추출)의 Oracle 등가 구현
  -- ==========================================================================

  PROCEDURE P_SYS0013_VALIDATE_QUERY
  (
    P_SQL_TEXT        IN  CLOB,
    O_RC1             OUT SYS_REFCURSOR,
    O_RESULT_CURSOR   OUT SYS_REFCURSOR
  )
  AS
    V_SQL_CODE    VARCHAR2(100 CHAR);
    V_SQL_ERRMSG  VARCHAR2(1000 CHAR);
    V_CURSOR_ID   INTEGER;
    V_COL_CNT     INTEGER;
    V_DESC_TAB    DBMS_SQL.DESC_TAB2;
    V_FIRST_WORD  VARCHAR2(30 CHAR);
    V_TYPE_NM     VARCHAR2(30 CHAR);
    V_LIST        SYS.ODCIVARCHAR2LIST := SYS.ODCIVARCHAR2LIST();
  BEGIN
    -- SELECT 전용 가드 (DML/DDL 검증 차단)
    V_FIRST_WORD := UPPER(REGEXP_SUBSTR(DBMS_LOB.SUBSTR(P_SQL_TEXT, 100, 1), '[A-Za-z]+', 1, 1));
    IF V_FIRST_WORD NOT IN ('SELECT', 'WITH') THEN
      RAISE_APPLICATION_ERROR(-20001, '[' || $$PLSQL_UNIT || '] SELECT/WITH 구문만 검증할 수 있습니다. (첫 키워드=' || NVL(V_FIRST_WORD, 'NULL') || ')');
    END IF;

    V_CURSOR_ID := DBMS_SQL.OPEN_CURSOR;
    BEGIN
      DBMS_SQL.PARSE(V_CURSOR_ID, P_SQL_TEXT, DBMS_SQL.NATIVE);   -- PARSE 만 수행, EXECUTE 없음
      DBMS_SQL.DESCRIBE_COLUMNS2(V_CURSOR_ID, V_COL_CNT, V_DESC_TAB);
      DBMS_SQL.CLOSE_CURSOR(V_CURSOR_ID);
    EXCEPTION
      WHEN OTHERS THEN
        IF DBMS_SQL.IS_OPEN(V_CURSOR_ID) THEN
          DBMS_SQL.CLOSE_CURSOR(V_CURSOR_ID);
        END IF;
        RAISE;
    END;

    -- 컬럼 타입 → AS-IS System.* 표기 (SCM_ADM_DQ_COLUMN.VALUE_TYPE 계약)
    FOR i IN 1 .. V_COL_CNT LOOP
      V_TYPE_NM := CASE
                     WHEN V_DESC_TAB(i).COL_TYPE IN (2, 100, 101) THEN 'System.Int'      -- NUMBER/BINARY_FLOAT/DOUBLE
                     WHEN V_DESC_TAB(i).COL_TYPE IN (12, 180, 181, 231) THEN 'System.Date' -- DATE/TIMESTAMP 계열
                     ELSE 'System.String'                                                 -- VARCHAR2/CHAR/CLOB 외
                   END;
      V_LIST.EXTEND;
      V_LIST(V_LIST.COUNT) := V_DESC_TAB(i).COL_NAME || '^' || V_TYPE_NM;
    END LOOP;

    OPEN O_RC1 FOR
      SELECT SUBSTR(COLUMN_VALUE, 1, INSTR(COLUMN_VALUE, '^') - 1) AS COLUMN_NAME
           , SUBSTR(COLUMN_VALUE, INSTR(COLUMN_VALUE, '^') + 1)   AS VALUE_TYPE
           , ROWNUM                                               AS SEQNO
        FROM TABLE(V_LIST);

    OPEN O_RESULT_CURSOR FOR
      SELECT '0' AS CODE, 'SUCCESS' AS MSG, CASE WHEN 1=2 THEN '-' ELSE NULL END AS EVENT FROM DUAL;

  EXCEPTION
    WHEN OTHERS THEN
      V_SQL_CODE   := TO_CHAR(SQLCODE);
      V_SQL_ERRMSG := SQLERRM;
      RAISE_APPLICATION_ERROR(-20001,
        '[' || $$PLSQL_UNIT || '] SQLCODE=' || V_SQL_CODE ||
        ' / SQLERRM=' || V_SQL_ERRMSG ||
        ' / SQL(500)=' || DBMS_LOB.SUBSTR(P_SQL_TEXT, 500, 1));
  END P_SYS0013_VALIDATE_QUERY;
  -- ▲▲▲ 추가 끝 ▲▲▲

END PKG_SYS0013;
/
SHOW ERRORS PACKAGE BODY PKG_SYS0013
-- ##### END PACKAGE BODY PKG_SYS0013

-- ##### START PACKAGE BODY PKG_SYS0014
CREATE OR REPLACE PACKAGE BODY         "PKG_SYS0014" 
AS
	PROCEDURE P_SYS0014_GET_DIVISION_DATA (
		P_TEXT     IN      VARCHAR2
	    , O_CURSOR        OUT SYS_REFCURSOR
    	, O_RESULT_CURSOR OUT SYS_REFCURSOR
	) IS

/*
 * Program ID   : P_SYS0014_GET_DIVISION_DATA
 * Description  : P_SYS0014_GET_DIVISION_DATA
 */

	BEGIN
    OPEN O_CURSOR FOR
	    SELECT DIVISION_ID AS CODE, DIVISION_NAME AS NAME
	    FROM SCM_MST_DIVISION
	    WHERE VALID_YN = 'Y'
	    AND (
	    	P_TEXT IS NULL
	    	OR 
	    	DIVISION_ID LIKE '%' || P_TEXT || '%'
	    	OR
	    	DIVISION_NAME LIKE '%' || P_TEXT || '%'
	    )
	    ORDER BY DIVISION_ID;

    OPEN O_RESULT_CURSOR FOR
      SELECT '0' AS CODE, 'SUCCESS' AS MSG, '0' AS EVENT FROM DUAL;

    EXCEPTION
        WHEN OTHERS THEN
            RAISE_APPLICATION_ERROR(-20001,
            '[' || $$PLSQL_UNIT || '] SQLCODE=' || TO_CHAR(SQLCODE) ||
            ' / SQLERRM=' || SQLERRM ||
            ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE ||
            ' / PARAMS=' || '-' );

	END P_SYS0014_GET_DIVISION_DATA;
    -- [2026-09-15 UIPKG] standalone P_SYS0014_GET_AUTH_LIST_M 취합
PROCEDURE P_SYS0014_GET_AUTH_LIST_M (
    P_USER_GR_ID     IN  VARCHAR2,
    P_USER_ID        IN  VARCHAR2,
    P_UNIT_TP_CD     IN  VARCHAR2,
    O_RC1            OUT SYS_REFCURSOR,
    O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
AS
BEGIN
    -- AS-IS SCM0005 FindData_Division (UP_FX_GetUserGroupAuthExtentionList): 그룹 조건부 AuthType
    --   비 JV 그룹 → AuthType='D' (부문권한, JV_PLANT 빈값) / 'JV Planner' 그룹 → AuthType='J' (DIVISION + JV_PLANT)
    --   * 컬럼 추가 없이 J 데이터는 TB_FX_USERGROUPAUTHEXTENTION.JV_PLANT_ID(기존 컬럼) JOIN 으로 동시 출력
    -- 표시: Name(UNIT_ID) + JV Plant(JV_PLANT_ID). 저장용 UPPR_UNIT_ID/EDIT_YN/USE_YN 동반.
    OPEN O_RC1 FOR
    SELECT A.UNIT_ID,
           D.DIVISION_NAME AS UNIT_NM,
           CAST(NULL AS VARCHAR2(4000)) AS JV_PLANT_ID,
           A.UPPR_UNIT_ID, A.EDIT_YN, A.USE_YN
      FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M A
      LEFT JOIN SCM_MGR.SCM_MST_DIVISION D ON D.DIVISION_ID = A.UNIT_ID
     WHERE A.USER_GR_ID = P_USER_GR_ID
       AND A.USER_ID    = P_USER_ID
       AND A.UNIT_TP_CD = P_UNIT_TP_CD
       AND P_USER_GR_ID <> 'JV Planner'
    UNION ALL
    SELECT DISTINCT
           B.UNIT_ID,
           D.DIVISION_NAME AS UNIT_NM,
--           B.JV_PLANT_ID,								--*[2026.09.11] POJ 원본
           CAST(NULL AS VARCHAR2(4000)) AS JV_PLANT_ID,	--*[2026.09.11] POJ : 신재욱책임님 확인내용(JV Planner는 미사용 롤이라 따로 관리하지 않아도 됨.)
           '-' AS UPPR_UNIT_ID, 'Y' AS EDIT_YN, 'Y' AS USE_YN
--      FROM SCM_MGR.TB_FX_USERGROUPAUTHEXTENTION B		--*[2026.09.11] POJ 원본 (AS-IS 테이블명)
      FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M B	--*[2026.09.11] POJ : TO-BE에서 사용하는 테이블정보로 변경
      LEFT JOIN SCM_MGR.SCM_MST_DIVISION D ON D.DIVISION_ID = B.UNIT_ID
     WHERE B.UNIT_TP_CD = 'D'		--*[2026.09.11] POJ : AS-IS JV Planner의 경우 'J'로 값을 관리했지만 미사용 롤이라 'D'로만 관리
       AND B.USER_GR_ID  = P_USER_GR_ID
       AND B.USER_ID   = P_USER_ID
       AND P_USER_GR_ID = 'JV Planner'
     ORDER BY 1;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        DECLARE V_ERR VARCHAR2(4000) := SUBSTR(SQLERRM, 1, 4000);
        BEGIN
            OPEN O_RC1 FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1=0;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
        END;
END P_SYS0014_GET_AUTH_LIST_M;

    -- [2026-09-15 UIPKG] standalone P_SYS0014_GET_GROUP_LIST_M 취합
PROCEDURE P_SYS0014_GET_GROUP_LIST_M (
    P_SEARCH         IN  VARCHAR2,
    O_RC1            OUT SYS_REFCURSOR,
    O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN O_RC1 FOR
    SELECT USER_GR_ID, USER_GR_NM, USE_YN
      FROM SCM_MGR.SCM_ADM_USER_GR_M
     WHERE P_SEARCH IS NULL OR P_SEARCH = ''
        OR UPPER(USER_GR_ID) LIKE '%' || UPPER(P_SEARCH) || '%'
        OR UPPER(USER_GR_NM) LIKE '%' || UPPER(P_SEARCH) || '%'
     ORDER BY USER_GR_ID;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        DECLARE V_ERR VARCHAR2(4000) := SUBSTR(SQLERRM, 1, 4000);
        BEGIN
            OPEN O_RC1 FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1=0;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
        END;
END P_SYS0014_GET_GROUP_LIST_M;

    -- [2026-09-15 UIPKG] standalone P_SYS0014_GET_USER_BY_GROUP_M 취합
PROCEDURE P_SYS0014_GET_USER_BY_GROUP_M (
    P_USER_GR_ID     IN  VARCHAR2,
    O_RC1            OUT SYS_REFCURSOR,
    O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
AS
BEGIN
    -- UserInfo 컬럼 (2026-06-26 조정): UserID/UserName/EnglishName/Email/Dept_Name/UseYN + 감사 4종 (Dept_ID 제외)
    OPEN O_RC1 FOR
    SELECT M.USER_ID,
           NVL(U.USER_NM, M.USER_ID)         AS USER_NM,
           U.USER_ENG_NM,
           U.USER_EML,
           (SELECT D.DEPT_NAME_KO FROM SCM_MGR.SCM_MST_SSO_DEPT_INFO D WHERE D.DEPT_ID = U.DEPT_ID) AS DEPT_NM,
           M.USE_YN,
           M.CREATED_BY,
           TO_CHAR(M.CREATION_DATE, 'YYYY-MM-DD HH24:MI:SS')    AS CREATION_DATE,
           M.LAST_UPDATED_BY,
           TO_CHAR(M.LAST_UPDATE_DATE, 'YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE
      FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M M
      LEFT JOIN SCM_MGR.SCM_ADM_USER_M U ON U.USER_ID = M.USER_ID
     WHERE M.USER_GR_ID = P_USER_GR_ID
     ORDER BY M.USER_ID;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        DECLARE V_ERR VARCHAR2(4000) := SUBSTR(SQLERRM, 1, 4000);
        BEGIN
            OPEN O_RC1 FOR SELECT NULL AS DUMMY FROM DUAL WHERE 1=0;
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG FROM DUAL;
        END;
END P_SYS0014_GET_USER_BY_GROUP_M;

    -- [2026-09-15 UIPKG] standalone P_SYS0014_SAVE_GROUP_USER_M 취합
PROCEDURE P_SYS0014_SAVE_GROUP_USER_M (
    P_SES_USER_ID    IN  VARCHAR2,
    P_DATA           IN  CLOB,
    O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
AS
    V_CNT NUMBER := 0;
BEGIN
    -- ============================================================
    -- main sheet (SCM_ADM_USER_GR_M) - Group CRUD
    -- ============================================================
    INSERT INTO SCM_MGR.SCM_ADM_USER_GR_M (USER_GR_ID, USER_GR_NM, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    SELECT V_USER_GR_ID, V_USER_GR_NM, NVL(V_USE_YN,'Y'), P_SES_USER_ID, SYSDATE, P_SES_USER_ID, SYSDATE
      FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
          V_SHT_NM      VARCHAR2(30)  PATH '$.SHT_NM',
          V_CRUD_TYPE   VARCHAR2(1)   PATH '$.CRUD_TYPE',
          V_USER_GR_ID  VARCHAR2(50)  PATH '$.USER_GR_ID',
          V_USER_GR_NM  VARCHAR2(100) PATH '$.USER_GR_NM',
          V_USE_YN      VARCHAR2(1)   PATH '$.USE_YN'
      ))
     WHERE V_SHT_NM='GroupInfo' AND V_CRUD_TYPE='I';
    V_CNT := V_CNT + SQL%ROWCOUNT;

    MERGE INTO SCM_MGR.SCM_ADM_USER_GR_M T
    USING (
        SELECT V_USER_GR_ID AS USER_GR_ID, V_USER_GR_NM AS USER_GR_NM, V_USE_YN AS USE_YN
          FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
              V_SHT_NM     VARCHAR2(30)  PATH '$.SHT_NM',
              V_CRUD_TYPE  VARCHAR2(1)   PATH '$.CRUD_TYPE',
              V_USER_GR_ID VARCHAR2(50)  PATH '$.USER_GR_ID',
              V_USER_GR_NM VARCHAR2(100) PATH '$.USER_GR_NM',
              V_USE_YN     VARCHAR2(1)   PATH '$.USE_YN'
          ))
         WHERE V_SHT_NM='GroupInfo' AND V_CRUD_TYPE='M'
    ) S ON (T.USER_GR_ID = S.USER_GR_ID)
    WHEN MATCHED THEN UPDATE SET T.USER_GR_NM=S.USER_GR_NM, T.USE_YN=NVL(S.USE_YN,'Y'),
                                  T.LAST_UPDATED_BY=P_SES_USER_ID, T.LAST_UPDATE_DATE=SYSDATE;
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- Group DELETE (cascade — userInfo + unit_auth 도 삭제)
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
     WHERE USER_GR_ID IN (
         SELECT V_USER_GR_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID'
         )) WHERE V_SHT_NM='GroupInfo' AND V_CRUD_TYPE='D'
     );
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M
     WHERE USER_GR_ID IN (
         SELECT V_USER_GR_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID'
         )) WHERE V_SHT_NM='GroupInfo' AND V_CRUD_TYPE='D'
     );
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_M
     WHERE USER_GR_ID IN (
         SELECT V_USER_GR_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID'
         )) WHERE V_SHT_NM='GroupInfo' AND V_CRUD_TYPE='D'
     );
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- ============================================================
    -- userInfo sheet (SCM_ADM_USER_GR_MPG_M) - User-Group mapping CRUD
    -- ============================================================
    INSERT INTO SCM_MGR.SCM_ADM_USER_GR_MPG_M (USER_GR_ID, USER_ID, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    SELECT V_USER_GR_ID, V_USER_ID, NVL(V_USE_YN,'Y'), P_SES_USER_ID, SYSDATE, P_SES_USER_ID, SYSDATE
      FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
          V_SHT_NM      VARCHAR2(30) PATH '$.SHT_NM',
          V_CRUD_TYPE   VARCHAR2(1)  PATH '$.CRUD_TYPE',
          V_USER_GR_ID  VARCHAR2(50) PATH '$.USER_GR_ID',
          V_USER_ID     VARCHAR2(50) PATH '$.USER_ID',
          V_USE_YN      VARCHAR2(1)  PATH '$.USE_YN'
      ))
     WHERE V_SHT_NM='UserInfo' AND V_CRUD_TYPE='I';
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- userInfo UPDATE (USE_YN toggle)
    MERGE INTO SCM_MGR.SCM_ADM_USER_GR_MPG_M T
    USING (
        SELECT V_USER_GR_ID AS USER_GR_ID, V_USER_ID AS USER_ID, V_USE_YN AS USE_YN
          FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
              V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
              V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
              V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID',
              V_USER_ID    VARCHAR2(50) PATH '$.USER_ID',
              V_USE_YN     VARCHAR2(1)  PATH '$.USE_YN'
          )) WHERE V_SHT_NM='UserInfo' AND V_CRUD_TYPE='M'
    ) S ON (T.USER_GR_ID = S.USER_GR_ID AND T.USER_ID = S.USER_ID)
    WHEN MATCHED THEN UPDATE SET T.USE_YN=NVL(S.USE_YN,'Y'),
                                  T.LAST_UPDATED_BY=P_SES_USER_ID, T.LAST_UPDATE_DATE=SYSDATE;
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- userInfo DELETE
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T
     WHERE (T.USER_GR_ID, T.USER_ID) IN (
         SELECT V_USER_GR_ID, V_USER_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID',
             V_USER_ID    VARCHAR2(50) PATH '$.USER_ID'
         )) WHERE V_SHT_NM='UserInfo' AND V_CRUD_TYPE='D'
     );
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_MPG_M T
     WHERE (T.USER_GR_ID, T.USER_ID) IN (
         SELECT V_USER_GR_ID, V_USER_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID',
             V_USER_ID    VARCHAR2(50) PATH '$.USER_ID'
         )) WHERE V_SHT_NM='UserInfo' AND V_CRUD_TYPE='D'
     );
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- ============================================================
    -- division/plant/customer sheets (SCM_ADM_USER_GR_UNIT_AUTH_MPG_M)
    -- UNIT_TP_CD: D / P / C (FE 가 SHT_NM 따라 매핑하여 payload 에 V_UNIT_TP_CD 직접 전송)
    -- ============================================================
    INSERT INTO SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M
        (USER_GR_ID, USER_ID, UNIT_TP_CD, UNIT_ID, UPPR_UNIT_ID, EDIT_YN, USE_YN,
         CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    SELECT V_USER_GR_ID, V_USER_ID, V_UNIT_TP_CD, V_UNIT_ID, NVL(NULLIF(RTRIM(V_UPPR_UNIT_ID),''), '/'), NVL(V_EDIT_YN,'Y'), NVL(V_USE_YN,'Y'),
           P_SES_USER_ID, SYSDATE, P_SES_USER_ID, SYSDATE
      FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
          V_SHT_NM       VARCHAR2(30) PATH '$.SHT_NM',
          V_CRUD_TYPE    VARCHAR2(1)  PATH '$.CRUD_TYPE',
          V_USER_GR_ID   VARCHAR2(50) PATH '$.USER_GR_ID',
          V_USER_ID      VARCHAR2(50) PATH '$.USER_ID',
          V_UNIT_TP_CD   VARCHAR2(10) PATH '$.UNIT_TP_CD',
          V_UNIT_ID      VARCHAR2(50) PATH '$.UNIT_ID',
          V_UPPR_UNIT_ID VARCHAR2(50) PATH '$.UPPR_UNIT_ID',
          V_EDIT_YN      VARCHAR2(1)  PATH '$.EDIT_YN',
          V_USE_YN       VARCHAR2(1)  PATH '$.USE_YN'
      ))
     WHERE V_SHT_NM='Division' AND V_CRUD_TYPE='I';
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- unit_auth UPDATE (EDIT_YN/USE_YN toggle)
    MERGE INTO SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T
    USING (
        SELECT V_USER_GR_ID AS USER_GR_ID, V_USER_ID AS USER_ID, V_UNIT_TP_CD AS UNIT_TP_CD,
               V_UNIT_ID AS UNIT_ID, V_EDIT_YN AS EDIT_YN, V_USE_YN AS USE_YN
          FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
              V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
              V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
              V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID',
              V_USER_ID    VARCHAR2(50) PATH '$.USER_ID',
              V_UNIT_TP_CD VARCHAR2(10) PATH '$.UNIT_TP_CD',
              V_UNIT_ID    VARCHAR2(50) PATH '$.UNIT_ID',
              V_EDIT_YN    VARCHAR2(1)  PATH '$.EDIT_YN',
              V_USE_YN     VARCHAR2(1)  PATH '$.USE_YN'
          )) WHERE V_SHT_NM='Division' AND V_CRUD_TYPE='M'
    ) S ON (T.USER_GR_ID=S.USER_GR_ID AND T.USER_ID=S.USER_ID AND T.UNIT_TP_CD=S.UNIT_TP_CD AND T.UNIT_ID=S.UNIT_ID)
    WHEN MATCHED THEN UPDATE SET T.EDIT_YN=NVL(S.EDIT_YN,'Y'), T.USE_YN=NVL(S.USE_YN,'Y'),
                                  T.LAST_UPDATED_BY=P_SES_USER_ID, T.LAST_UPDATE_DATE=SYSDATE;
    V_CNT := V_CNT + SQL%ROWCOUNT;

    -- unit_auth DELETE
    DELETE FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M T
     WHERE (T.USER_GR_ID, T.USER_ID, T.UNIT_TP_CD, T.UNIT_ID) IN (
         SELECT V_USER_GR_ID, V_USER_ID, V_UNIT_TP_CD, V_UNIT_ID FROM JSON_TABLE(P_DATA, '$[*]' COLUMNS (
             V_SHT_NM     VARCHAR2(30) PATH '$.SHT_NM',
             V_CRUD_TYPE  VARCHAR2(1)  PATH '$.CRUD_TYPE',
             V_USER_GR_ID VARCHAR2(50) PATH '$.USER_GR_ID',
             V_USER_ID    VARCHAR2(50) PATH '$.USER_ID',
             V_UNIT_TP_CD VARCHAR2(10) PATH '$.UNIT_TP_CD',
             V_UNIT_ID    VARCHAR2(50) PATH '$.UNIT_ID'
         )) WHERE V_SHT_NM='Division' AND V_CRUD_TYPE='D'
     );
    V_CNT := V_CNT + SQL%ROWCOUNT;

    COMMIT;

    OPEN O_RESULT_CURSOR FOR
    SELECT '0' AS CODE, 'SUCCESS' AS MSG, TO_CHAR(V_CNT) AS EVENT FROM DUAL;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        DECLARE V_ERR VARCHAR2(4000) := SUBSTR(SQLERRM, 1, 4000);
        BEGIN
            OPEN O_RESULT_CURSOR FOR SELECT '-1' AS CODE, V_ERR AS MSG, '0' AS EVENT FROM DUAL;
        END;
END P_SYS0014_SAVE_GROUP_USER_M;

END PKG_SYS0014;
/
SHOW ERRORS PACKAGE BODY PKG_SYS0014
-- ##### END PACKAGE BODY PKG_SYS0014

-- ##### START PACKAGE BODY PKG_ZTMP_S015J
CREATE OR REPLACE PACKAGE BODY PKG_ZTMP_S015J
IS
    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
       AS-IS SSP0015_GET_SHIPMENT_PSI_COMMENTS - 결과셋 2벌(NOTE · Prod Qty)
       ※ AS-IS 는 FN_GET_IN_STR 로 IN 리스트를 만들어 EXEC 로 돌린다.
          선택조건 조립뿐이라 정적 SQL 로 옮겼다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_COMMENTS
         * Description  : Shipment Plan Confrim COMMENTS LOAD
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/08/09   MCTHEJ		   [CSR ID:4061695] SSP 시스템 개선 요청건(Shipment Plan)
         * 2023/08/03   jilee          AS BEFORE_QTY, AS GAP 조건 변경
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         *
         ex) EXEC PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_COMMENTS('40','20190811','','','20190809','20191031', ...)
         */
    BEGIN

        /* Note Load */
        OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.FROM_SITE                                                              AS SITE
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')        AS FROM_SITE_NM
             , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN B.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
             , A.ITEM_ID
             , SUBSTR(A.YYYYMMDD, 1, 4) || '-' || SUBSTR(A.YYYYMMDD, 5, 2) || '-' || SUBSTR(A.YYYYMMDD, 7, 2) AS YYYYMMDD
             , CEIL(NVL(SUM(A.USER_ADD_QTY), 0))                                        AS USER_ADD_QTY
             , NVL(SUM(B.QTY), 0)                                                       AS QTY
--             , CEIL(NVL(SUM(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR)), 0)) AS BEFORE_QTY
             , CEIL(NVL(SUM(ROUND(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR))), 0)) AS BEFORE_QTY   -- 2026.09.17 AJS
--             , NVL(SUM(B.QTY), 0) - CEIL(NVL(SUM(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR)), 0)) AS GAP
             , NVL(SUM(B.QTY), 0) - CEIL(NVL(SUM(ROUND(TO_NUMBER(A.ATTRIBUTE1 DEFAULT NULL ON CONVERSION ERROR))), 0)) AS GAP   -- 2026.09.17 AJS
             , NVL(A.COMMENTS, '')                                                      AS COMMENTS
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE
          FROM SSP_ANL_SHIP_PLAN_40_WH_IN_CMT A
             , SSP_ANL_SHIP_PLAN_40 B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.FROM_SITE   = B.FROM_SITE
           AND A.ITEM_ID     = B.ITEM_ID
           AND A.YYYYMMDD    = B.YYYYMMDD
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.MEASURE             = 'WH_IN'
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                 OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
         GROUP BY A.DIVISION_ID
             , B.ORIGIN_FROM_DIVISION_ID
             , A.FROM_SITE
             , A.ITEM_ID
             , A.YYYYMMDD
             , A.COMMENTS
             , A.LAST_UPDATED_BY
             , A.LAST_UPDATE_DATE;

        /* Prod Qty Load */
        OPEN O_RC2 FOR
        SELECT DIVISION_ID
             , FROM_SITE                                                                AS SITE
             , ITEM_ID
             , SUBSTR(YYYYMMDD, 1, 4) || '-' || SUBSTR(YYYYMMDD, 5, 2) || '-' || SUBSTR(YYYYMMDD, 7, 2) AS YYYYMMDD
             , NVL(ATTRIBUTE3, '')                                                      AS PRODUCT_QTY
          FROM SSP_ANL_SHIP_PLAN_40
         WHERE 1 = 1
           /* AS-IS : (ATTRIBUTE3 IS NOT NULL OR ATTRIBUTE3 != '') - 뒷항은 Oracle 에서 늘 거짓이라 앞항만 남긴다 */
           AND ATTRIBUTE3 IS NOT NULL
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND MEASURE             = 'PROD_PLAN'
           AND YYYYMMDD >= P_FROM_YYYYMMDD
           AND YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                 OR DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
         GROUP BY DIVISION_ID
             , FROM_SITE
             , ITEM_ID
             , YYYYMMDD
             , ATTRIBUTE3;

    END P_SSP0015_GET_SHIPMENT_PSI_COMMENTS;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI
       AS-IS SSP0015_GET_SHIPMENT_PSI - 화면 본체
       ※ #Tmp_RowData -> GT_SSP0015_ROWDATA
       ※ #TblDynamicTitlest_SSP0015 는 SCM_MST_TITLESET_USER 를 같은 조건으로 다시 읽는 것과
          결과가 같아 GTT 를 두지 않고 원본 테이블을 직접 참조한다.
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
          AS-IS 는 SUM 피벗(수치)과 MAX 피벗(LOT 문자)을 UNION ALL 로 합친다. 형태를 유지한다.
       ※ NOTE · Prod Qty 는 AS-IS 가 SSP0015_GET_SHIPMENT_PSI_COMMENTS 를 호출해 결과셋 2벌을 덧붙인다.
          O_RC2 · O_RC3 로 같은 벌 수를 맞춘다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR,
        O_RC3                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/03/05   AYJ            Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/05/16   AYJ            [CSR:] MST_MEASURE DEFAULT_FLAG='N', 유져 셋팅 없을 시 화면에 노출되지 않도록 수정
         * 2019/06/17   AYJ            조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/05   MCTHEJ         [CSR ID:4045693] measure 'LOT'의 문자값에 대한 PIVOT 처리 추가
         * 2019/08/09   MCTHEJ         [CSR ID:4061695] SSP 시스템 개선 요청건(Shipment Plan) - NOTE 추가
         * 2019/08/28   AYJ            조회 조건 추가(p_delegateeChk)
         * 2019/12/17   KIMYONGHO      BOH 조정 (이름 변경 및 추가) EX) TOTAL -> oWMS
         * 2020/09/23   KIMYONGHO      WH_STOCK BOH 수량에서 CHANGE_STATUS 'Delete' 제외 ('D')
         * 2020/10/22   KIMYONGHO      POUCH_WH_IN_DAY LOOKUP에 해당하는 내용은 L/T = LOOKUP의 SEGMENT2 값 적용
         * 2021/11/01   KIMYONGHO      @p_real_flag 구분 조회
         * 2022/11/14   jilee          DM_PLN_SHIPMENT_REQ -> SITE_TYPE ='SALES' 주석처리
         * 2023/09/21   jilee          G182-P (Group='P',OSP='N')조회 추가
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_PLAN_VERSION_DATE     VARCHAR2(8 CHAR);
        V_REAL_FLAG             VARCHAR2(1 CHAR);
        V_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR) := P_PLAN_START_YYYYMMDD;
        V_CNT_USR_MEASURE       PLS_INTEGER := 0;
        V_PLAN_TYPE             VARCHAR2(30 CHAR) := 'SP';
        V_SEQ                   PLS_INTEGER := 1;
        V_FROM_SITE             VARCHAR2(4000 CHAR);
        V_DIVISION_ID           VARCHAR2(4000 CHAR);
        V_ITEM_ID               VARCHAR2(4000 CHAR);
        V_DATA_START_YYYYMMDD   VARCHAR2(8 CHAR);
        V_DATA_END_YYYYMMDD     VARCHAR2(8 CHAR);
        V_MQUERY                CLOB := EMPTY_CLOB();   /* SUM 피벗 칸 */
        V_MQUERY1               CLOB := EMPTY_CLOB();   /* MAX 피벗 칸(LOT) */
        V_MEXEC                 CLOB;
        V_LT_SUB                VARCHAR2(4000 CHAR);
        V_YIELD_SUB             VARCHAR2(4000 CHAR);
        V_LTYN_SUB              VARCHAR2(4000 CHAR);
        V_FIGURE_EXP            VARCHAR2(4000 CHAR);
    BEGIN

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_ROWDATA;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        BEGIN
            SELECT PLAN_START_YYYYMMDD
              INTO V_PLAN_VERSION_DATE
              FROM (SELECT PLAN_START_YYYYMMDD
                      FROM SSP_PLAN_VERSION_V
                     WHERE DIVISION_ID = '40'
                     GROUP BY PLAN_START_YYYYMMDD
                     ORDER BY PLAN_START_YYYYMMDD DESC)
             WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                V_PLAN_VERSION_DATE := NULL;
        END;

        IF V_PLAN_VERSION_DATE = V_PLAN_START_YYYYMMDD THEN
            V_REAL_FLAG := 'Y';
        ELSE
            V_REAL_FLAG := 'N';
        END IF;

        V_DIVISION_ID := P_DIVISION_ID;
--        V_ITEM_ID     := P_ITEM_ID;
        /* AS-IS 는 대소문자 무시 · 뒤공백 무시 비교 */   -- 2026.09.17 AJS
        V_ITEM_ID     := UPPER(RTRIM(P_ITEM_ID));   -- 2026.09.17 AJS
        V_FROM_SITE   := P_FROM_SITE;

        /* AS-IS : IF LEN(@p_from_site) > 6 SET @p_from_site = ''; */
        IF LENGTH(RTRIM(NVL(V_FROM_SITE, ''))) > 6 THEN
            V_FROM_SITE := '';
        END IF;

        /* DATA 생성 시작 일자 (당일) · 마지막 일자 12주(84일) */
        V_DATA_START_YYYYMMDD := V_PLAN_START_YYYYMMDD;
        V_DATA_END_YYYYMMDD   := TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 84, 'YYYYMMDD');

        /* -------------1------------ 기준 원장 적재 */
        INSERT INTO GT_SSP0015_ROWDATA
               (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
              , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
              , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
              , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
              , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
        SELECT A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.ITEM_ID
             , A.FROM_SITE
             , A.TO_SITE
             , A.MEASURE
             , A.YYYYMMDD
             , A.BOD_ID
             , A.QTY
             , A.ROUTE_ID
             , A.INCOTERMS
             , A.TRANSPORT_MODE
             , A.BIZ_TYPE
             , A.PROJECT_CODE
             , A.FCST_TYPE
             , A.FCST_ETD_DATE
             , A.FCST_ETA_DATE
             , A.ETD_DATE
             , A.ETA_DATE
             , A.CONFIRM_ID
             , A.ORIGIN_FROM_DIVISION_ID
             , A.ORIGIN_TO_DIVISION_ID
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE10
          FROM SSP_ANL_SHIP_PLAN_40 A
             , SSP_MST_MODEL_USER TT3
         WHERE TT3.DIVISION_ID(+) = A.DIVISION_ID
           AND TT3.FROM_SITE(+)   = A.FROM_SITE
           AND TT3.ITEM_ID(+)     = A.ITEM_ID
           AND TT3.VALID_YN(+)    = 'Y'
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
           AND A.PLAN_TYPE           = P_PLAN_TYPE
--           AND A.SEQ                 = P_SEQ
           AND A.SEQ                 = TO_NUMBER(P_SEQ)   -- 2026.09.17 AJS
           AND (V_ITEM_ID IS NULL OR A.ITEM_ID = V_ITEM_ID)
           AND (V_FROM_SITE IS NULL
                 AND A.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                 OR A.FROM_SITE = V_FROM_SITE)
           AND ((V_REAL_FLAG = 'Y' AND A.MEASURE NOT IN ('SHIP_REQ', 'SHIP_CONFIRM', 'WH_STOCK', 'BALANCE'))
                 OR (V_REAL_FLAG = 'N' AND A.MEASURE IN ('BALANCE', 'INCO_WIP', 'INSP_WIP', 'LOT', 'MES_FCS_HOLD'
                                                       , 'MES_FCS_RELEASE', 'POSTP_PLAN', 'PROD_DATE', 'PROD_PLAN'
                                                       , 'SHIP_CONFIRM', 'SHIP_REQ', 'WH_IN', 'WH_STOCK')))
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND EXISTS (SELECT 1
                         FROM (SELECT Z.DIVISION_ID, Z.SEQ, Z.ITEM_ID, Z.FROM_SITE, SUM(Z.QTY) AS QTY
                                 FROM SSP_ANL_SHIP_PLAN_40 Z
                                WHERE Z.DIVISION_ID         = P_DIVISION_ID
                                  AND Z.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                                GROUP BY Z.DIVISION_ID, Z.SEQ, Z.ITEM_ID, Z.FROM_SITE) B
                        WHERE A.DIVISION_ID = B.DIVISION_ID
                          AND A.SEQ         = B.SEQ
                          AND A.ITEM_ID     = B.ITEM_ID
                          AND A.FROM_SITE   = B.FROM_SITE
                          AND B.QTY        <> 0)
           AND ((P_NONCHK = 'Y' AND 1 = 1)
--                 OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                 OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                     UNION
                                    SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                      FROM SSP_MST_DELEGATE
                                     WHERE VALID_YN = 'Y'
--                                       AND DELEGATEE_ID = P_USER_ID
                                       AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                     GROUP BY USER_ID)
--                 OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                 OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END);
                 OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END);   -- 2026.09.17 AJS

        IF V_REAL_FLAG = 'Y' THEN

            /* -------------2------------ [S]SHIP_REQ : MKT 담당자가 출하요청한 수량 */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
                  , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
            SELECT R.DIVISION_ID
                 , V_PLAN_START_YYYYMMDD
                 , V_PLAN_TYPE
                 , V_SEQ
                 , R.ITEM_ID
                 , R.FROM_SITE
                 , R.TO_SITE
                 , 'SHIP_REQ'
                 , R.YYYYMMDD
                 , R.BOD_ID
                 , SUM(R.QTY)
                   /* AS-IS ISNULL(S.ROUTE_ID,'-') - 적재 칸이 숫자라 '-' 는 넣을 수 없다. NULL 그대로 둔다. */
                 , S.ROUTE_ID
                 , NVL(S.SSP_INCOTERMS, R.INCOTERMS)
                 , R.TRANSPORT_MODE
                 , R.BIZ_TYPE
                 , R.PROJECT_CODE
                 , R.FCST_TYPE
                 , R.FCST_ETD_DATE
                 , R.FCST_ETA_DATE
                 , R.ETD_DATE
                 , R.ETA_DATE
                 , R.CONFIRM_ID
                 , R.DIVISION_ID
                 , R.DIVISION_ID
                 , NULL   /* ATTRIBUTE1 - PROD_DATE */
                 , R.CREATED_BY   /* ATTRIBUTE2 - REQUESTOR */
                 , NULL, NULL, NULL, NULL, NULL
              FROM (
                    SELECT R.DIVISION_ID
                         , R.ITEM_ID
                         , R.PLANT_SITE_ID  AS FROM_SITE
                         , R.SCM_SITE_ID    AS TO_SITE
                         , R.MEASURE
                         , R.YYYYMMDD
                         , R.BOD_ID
                         , R.QTY
                         , R.INCOTERMS
                         , R.TRANSPORT_MODE
                         , CASE WHEN INSTR(R.PLANT_SITE_ID, '-') = 0 THEN 'A'
                                ELSE SUBSTR(R.PLANT_SITE_ID, INSTR(R.PLANT_SITE_ID, '-') + 1, 1) END AS BIZ_TYPE
                         , R.PROJECT_CODE
                         , R.FCST_TYPE
                         , R.YYYYMMDD       AS FCST_ETD_DATE
                         , NULL             AS FCST_ETA_DATE
                         , R.YYYYMMDD       AS ETD_DATE
                         , NULL             AS ETA_DATE
                         , R.ATTRIBUTE10    AS CONFIRM_ID
                         , R.CREATED_BY
                      FROM DM_PLN_SHIPMENT_REQ R
                         , SSP_MST_MODEL_USER TT3
                     WHERE TT3.DIVISION_ID(+) = R.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = R.PLANT_SITE_ID
                       AND TT3.ITEM_ID(+)     = R.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND R.DIVISION_ID = V_DIVISION_ID
                       AND (V_ITEM_ID IS NULL OR R.ITEM_ID = V_ITEM_ID)
                       AND R.MEASURE     = 'SHIP_REQ'
                       AND (V_FROM_SITE IS NULL
                             AND R.PLANT_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR R.PLANT_SITE_ID = V_FROM_SITE)
                       AND R.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND R.YYYYMMDD <= P_TO_YYYYMMDD
                       AND R.QTY > 0
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
--                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
--                                                   AND DELEGATEE_ID = P_USER_ID
                                                   AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                 GROUP BY USER_ID)
--                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END)   -- 2026.09.17 AJS
                   ) R
                   /* AS-IS 의 ON S.INCOTERMS <> S.SSP_INCOTERMS 는 외부조인 대상 자체에 대한 조건이라
                      (+) 표기로는 ORA-01416 이 난다. 인라인 뷰로 먼저 걸러 같은 결과를 만든다. */
                 , (SELECT DIVISION_ID, FROM_SITE, BOD_ID, ROUTE_ID, SSP_INCOTERMS
                      FROM SCP_MST_BOD_N_V
                     WHERE INCOTERMS <> SSP_INCOTERMS) S
             WHERE S.DIVISION_ID(+)  = R.DIVISION_ID
               AND S.FROM_SITE(+)    = R.FROM_SITE
               AND S.BOD_ID(+)       = R.BOD_ID
               AND R.DIVISION_ID = V_DIVISION_ID
               AND R.MEASURE     = 'SHIP_REQ'
               AND (V_FROM_SITE IS NULL
                     AND R.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                     OR R.FROM_SITE = V_FROM_SITE)
               AND R.YYYYMMDD >= V_DATA_START_YYYYMMDD
               AND R.YYYYMMDD <= P_TO_YYYYMMDD
             GROUP BY R.DIVISION_ID
                 , R.ITEM_ID
                 , R.FROM_SITE
                 , R.TO_SITE
                 , R.YYYYMMDD
                 , R.BOD_ID
                   /* AS-IS ISNULL(S.ROUTE_ID,'-') - 적재 칸이 숫자라 '-' 는 넣을 수 없다. NULL 그대로 둔다. */
                 , S.ROUTE_ID
                 , NVL(S.SSP_INCOTERMS, R.INCOTERMS)
                 , R.TRANSPORT_MODE
                 , R.BIZ_TYPE
                 , R.PROJECT_CODE
                 , R.FCST_TYPE
                 , R.FCST_ETD_DATE
                 , R.FCST_ETA_DATE
                 , R.ETD_DATE
                 , R.ETA_DATE
                 , R.CONFIRM_ID
                 , R.CREATED_BY;

            /* -------------3------------ [S]SHIP_CONFIRM : 출하 확정 수량 */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, ROUTE_ID, INCOTERMS, TRANSPORT_MODE, BIZ_TYPE, PROJECT_CODE
                  , FCST_TYPE, FCST_ETD_DATE, FCST_ETA_DATE, ETD_DATE, ETA_DATE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID
                  , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE10)
            SELECT A.DIVISION_ID
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.BOD_ID
                 , SUM(A.QTY)
                 , A.ROUTE_ID
                 , A.INCOTERMS
                 , A.TRANSPORT_MODE
                 , A.BIZ_TYPE
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , A.FCST_ETD_DATE
                 , MAX(A.FCST_ETA_DATE)
                 , A.ETD_DATE
                 , MAX(A.ETA_DATE)
                 , MAX(A.CONFIRM_ID)
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID
                 , NULL
                 , MAX(A.ATTRIBUTE2)
                 , NULL, NULL, NULL, NULL, NULL
              FROM (
                    SELECT C.DIVISION_ID                        AS DIVISION_ID
                         , V_PLAN_START_YYYYMMDD                AS PLAN_START_YYYYMMDD
                         , V_PLAN_TYPE                          AS PLAN_TYPE
                         , V_SEQ                                AS SEQ
                         , C.ITEM_ID                            AS ITEM_ID
                         , C.FROM_SITE                          AS FROM_SITE
                         , C.TO_SITE                            AS TO_SITE
                         , 'SHIP_CONFIRM'                       AS MEASURE
                         , C.YYYYMMDD                           AS YYYYMMDD
                         , C.BOD_ID                             AS BOD_ID
                         , C.QTY                                AS QTY
                         , C.ROUTE_ID                           AS ROUTE_ID
                         , NVL(S.SSP_INCOTERMS, C.INCOTERMS)    AS INCOTERMS
                         , C.TRANSPORT_MODE                     AS TRANSPORT_MODE
                         , C.BIZ_TYPE                           AS BIZ_TYPE
                         , C.PROJECT_CODE                       AS PROJECT_CODE
                         , C.FCST_TYPE                          AS FCST_TYPE
                         , C.FCST_ETD_DATE                      AS FCST_ETD_DATE
                         , C.FCST_ETA_DATE                      AS FCST_ETA_DATE
                         , C.ETD_DATE                           AS ETD_DATE
                         , C.ETA_DATE                           AS ETA_DATE
                         , C.CONFIRM_ID                         AS CONFIRM_ID
                         , C.DIVISION_ID                        AS ORIGIN_FROM_DIVISION_ID
                         , C.DIVISION_ID                        AS ORIGIN_TO_DIVISION_ID
                         , C.REQUESTOR                          AS ATTRIBUTE2
                      FROM SSP_ANL_SHIP_CONFIRM C
                         , (SELECT DIVISION_ID, FROM_SITE, BOD_ID, SSP_INCOTERMS
                              FROM SCP_MST_BOD_N_V
                             WHERE INCOTERMS <> SSP_INCOTERMS) S
                         , SSP_MST_MODEL_USER TT3
                     WHERE S.DIVISION_ID(+)  = C.DIVISION_ID
                       AND S.FROM_SITE(+)    = C.FROM_SITE
                       AND S.BOD_ID(+)       = C.BOD_ID
                       AND TT3.DIVISION_ID(+) = C.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = C.FROM_SITE
                       AND TT3.ITEM_ID(+)     = C.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND (V_FROM_SITE IS NULL
                             AND C.FROM_SITE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR C.FROM_SITE = V_FROM_SITE)
--                       AND (V_ITEM_ID IS NULL OR C.ITEM_ID = V_ITEM_ID)
                       AND (V_ITEM_ID IS NULL OR UPPER(C.ITEM_ID) = V_ITEM_ID)   -- 2026.09.17 AJS
                       AND C.CHANGE_TYPE = 'C'
                       AND C.BIZ_TYPE   <> 'E'   /* 전극제외 */
                       AND C.QTY > 0
                       AND C.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND C.YYYYMMDD <= P_TO_YYYYMMDD
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
--                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
--                                                   AND DELEGATEE_ID = P_USER_ID
                                                   AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                 GROUP BY USER_ID)
--                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END)   -- 2026.09.17 AJS
                    UNION ALL
                    SELECT R.DIVISION_ID
                         , V_PLAN_START_YYYYMMDD
                         , V_PLAN_TYPE
                         , V_SEQ
                         , R.ITEM_ID
                         , R.PLANT_SITE_ID
                         , R.SCM_SITE_ID
                         , 'SHIP_CONFIRM'
                         , R.YYYYMMDD
                         , R.BOD_ID
                         , R.QTY
                         , S.ROUTE_ID
                         , R.INCOTERMS
                         , R.TRANSPORT_MODE
                         , CASE WHEN INSTR(R.PLANT_SITE_ID, '-') = 0 THEN 'A'
                                ELSE SUBSTR(R.PLANT_SITE_ID, INSTR(R.PLANT_SITE_ID, '-') + 1, 1) END
                         , R.PROJECT_CODE
                         , R.FCST_TYPE
                         , R.YYYYMMDD
                         , NULL
                         , R.YYYYMMDD
                         , NULL
                         , R.ATTRIBUTE10
                         , R.DIVISION_ID
                         , R.DIVISION_ID
                         , NULL
                      FROM DM_PLN_SHIPMENT_REQ R
                         , SCP_MST_BOD_N_V S
                         , SSP_MST_MODEL_USER TT3
                     WHERE S.DIVISION_ID = R.DIVISION_ID
                       AND S.FROM_SITE   = R.PLANT_SITE_ID
                       AND S.BOD_ID      = R.BOD_ID
                       AND TT3.DIVISION_ID(+) = R.DIVISION_ID
                       AND TT3.FROM_SITE(+)   = R.PLANT_SITE_ID
                       AND TT3.ITEM_ID(+)     = R.ITEM_ID
                       AND TT3.VALID_YN(+)    = 'Y'
                       AND R.DIVISION_ID = V_DIVISION_ID
                       AND (V_ITEM_ID IS NULL OR R.ITEM_ID = V_ITEM_ID)
                       AND R.MEASURE     = 'SHIP_REQ'
                       AND (V_FROM_SITE IS NULL
                             AND R.PLANT_SITE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI', 'A010A_G182A_G182P')))
                             OR R.PLANT_SITE_ID = V_FROM_SITE)
                       AND R.YYYYMMDD > (CASE WHEN NVL(FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID), 0) = 0
                                              THEN V_PLAN_START_YYYYMMDD
                                              ELSE TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD')
                                                           + FN_GET_SSP_ANL_SHIP_FROZEN(R.DIVISION_ID, R.PLANT_SITE_ID) - 1, 'YYYYMMDD') END)
                       AND R.YYYYMMDD <= P_TO_YYYYMMDD
                       AND R.QTY > 0
                       AND R.ATTRIBUTE10 IS NULL
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
--                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                             OR TT3.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                 UNION
                                                SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                  FROM SSP_MST_DELEGATE
                                                 WHERE VALID_YN = 'Y'
--                                                   AND DELEGATEE_ID = P_USER_ID
                                                   AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                 GROUP BY USER_ID)
--                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR TT3.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                             OR TT3.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END)   -- 2026.09.17 AJS
                   ) A
             WHERE 1 = 1
             GROUP BY A.DIVISION_ID
                 , A.PLAN_START_YYYYMMDD
                 , A.PLAN_TYPE
                 , A.SEQ
                 , A.ITEM_ID
                 , A.FROM_SITE
                 , A.TO_SITE
                 , A.MEASURE
                 , A.YYYYMMDD
                 , A.BOD_ID
                 , A.ROUTE_ID
                 , A.INCOTERMS
                 , A.TRANSPORT_MODE
                 , A.BIZ_TYPE
                 , A.PROJECT_CODE
                 , A.FCST_TYPE
                 , A.FCST_ETD_DATE
                 , A.ETD_DATE
                 , A.ORIGIN_FROM_DIVISION_ID
                 , A.ORIGIN_TO_DIVISION_ID;

            /* -------------4------------ [I]WH_STOCK */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
            SELECT Z.DIVISION_ID
                 , Z.PLAN_START_YYYYMMDD
                 , Z.PLAN_TYPE
                 , Z.SEQ
                 , Z.ITEM_ID
                 , Z.FROM_SITE
                 , '-'
                 , 'WH_STOCK'
                 , Z.YYYYMMDD
                 , '-'
                   /* 전일 WH_IN , 전일 SHIP_CONFIRM 누적 */
                 , (CASE WHEN V_PLAN_START_YYYYMMDD < Z.YYYYMMDD
                         THEN (SELECT NVL(SUM(CASE X.MEASURE WHEN 'SHIP_CONFIRM'    THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'POSTP_PLAN'      THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'MES_FCS_HOLD'    THEN -1 * NVL(X.QTY, 0)
                                                             WHEN 'WH_IN'           THEN      NVL(X.QTY, 0)
                                                             WHEN 'MES_FCS_RELEASE' THEN      NVL(X.QTY, 0)
                                                        ELSE 0.0 END), 0)
                                 FROM GT_SSP0015_ROWDATA X
                                WHERE 1 = 1
                                  AND X.DIVISION_ID         = Z.DIVISION_ID
                                  AND X.PLAN_START_YYYYMMDD = Z.PLAN_START_YYYYMMDD
                                  AND X.PLAN_TYPE           = Z.PLAN_TYPE
                                  AND X.SEQ                 = Z.SEQ
                                  AND X.ITEM_ID             = Z.ITEM_ID
                                  AND X.FROM_SITE           = Z.FROM_SITE
                                  AND X.MEASURE IN ('SHIP_CONFIRM', 'WH_IN', 'POSTP_PLAN', 'MES_FCS_HOLD', 'MES_FCS_RELEASE')
                                  AND X.YYYYMMDD >= V_DATA_START_YYYYMMDD
                                  AND X.YYYYMMDD  < Z.YYYYMMDD)
                         ELSE 0 END)
                   /* 당일 OWMS 재고 */
                   + NVL(BOH.QTY, 0)
                   /* 2020.09.09 KBK : POUCH_WH_IN_DAY 처리 */
                   - (CASE WHEN V_PLAN_START_YYYYMMDD <= Z.YYYYMMDD
                           THEN CASE WHEN NVL(B.SEGMENT3, '/') = 'P' THEN NVL(B.WH_IN_QTY2, 0) ELSE 0 END
                           ELSE 0 END)
                   /* HOLD 재고 제외 */
                   - NVL((SELECT SUM(H.HOLD_QTY)
                            FROM SSP_ANL_HOLD_STOCK H
                               , SCM_SYS_CALENDAR_M C
                           WHERE H.DIVISION_ID         = V_DIVISION_ID
                             AND H.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                             AND H.PLAN_TYPE           = V_PLAN_TYPE
                             AND H.SEQ                 = V_SEQ
                             AND C.BASIS_YYYYMMDD >= H.HOLD_YYYYMMDD
                             AND C.BASIS_YYYYMMDD <= H.RELEASE_YYYYMMDD
                             AND C.BASIS_YYYYMMDD >= V_DATA_START_YYYYMMDD
                             AND C.BASIS_YYYYMMDD  < V_DATA_END_YYYYMMDD
                             AND H.DIVISION_ID = Z.DIVISION_ID
                             AND H.FROM_SITE   = Z.FROM_SITE
                             AND H.ITEM_ID     = Z.ITEM_ID
                             AND C.BASIS_YYYYMMDD = Z.YYYYMMDD
                           GROUP BY H.DIVISION_ID, H.FROM_SITE, H.ITEM_ID, C.BASIS_YYYYMMDD), 0) AS QTY
                 , '/'
                 , '-'
                 , '/'
                 , '/'
                 , '-'
                 , Z.DIVISION_ID
                 , Z.DIVISION_ID
              FROM (
                    SELECT DISTINCT
                           P.DIVISION_ID
                         , P.PLAN_START_YYYYMMDD
                         , P.PLAN_TYPE
                         , P.SEQ
                         , P.ITEM_ID
                         , P.FROM_SITE
                         , P.YYYYMMDD
                      FROM GT_SSP0015_ROWDATA P
                     WHERE 1 = 1
                       AND P.DIVISION_ID         = V_DIVISION_ID
                       AND P.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND P.PLAN_TYPE           = V_PLAN_TYPE
                       AND P.SEQ                 = V_SEQ
                       AND P.MEASURE IN ('SHIP_CONFIRM', 'WH_IN', 'POSTP_PLAN', 'MES_FCS_HOLD', 'MES_FCS_RELEASE')
                       AND P.YYYYMMDD >= V_DATA_START_YYYYMMDD
                       AND P.YYYYMMDD <= P_TO_YYYYMMDD
                   ) Z
                 , (SELECT XA.DIVISION_ID
                         , XA.PLAN_START_YYYYMMDD
                         , XA.PLAN_TYPE
                         , XA.SEQ
                         , XA.FROM_SITE
                         , XA.ITEM_ID
                         , SUM(XA.QTY) AS QTY
                      FROM (
                            SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                                 , (CASE WHEN NVL(C.SEGMENT3, '/') = 'P' THEN SUM(A.LOT_QTY_MES) ELSE 0 END) AS QTY
                              FROM SSP_ANL_MES_FCS_STOCK_40_C A
                                 , SCP_MST_FINAL_ITEM B
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL C
                             WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                               AND B.ITEM_ID(+)     = A.ITEM_ID
                               AND C.LOOKUP_TYPE(+) = 'CELL_TYPE_CODE'
                               AND C.VALID_YN(+)    = 'Y'
                               AND C.SEGMENT1(+)    = B.CELL_TYPE_GROUP_CODE
                               AND A.DIVISION_ID         = V_DIVISION_ID
                               AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND A.PLAN_TYPE           = V_PLAN_TYPE
                               AND A.SEQ                 = V_SEQ
                               AND A.AVAILABLE_YN       <> 'N'
                               AND NVL(A.CHANGE_STATUS, '-') <> 'D'
                             GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID, C.SEGMENT3
                            UNION ALL
                            SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                                 , SUM(A.AVAILABLE_QTY) AS QTY
                              FROM SSP_ANL_OWMS_STOCK_C A
                             WHERE 1 = 1
                               AND A.DIVISION_ID         = V_DIVISION_ID
                               AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND A.PLAN_TYPE           = V_PLAN_TYPE
                               AND A.SEQ                 = V_SEQ
                             GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.FROM_SITE, A.ITEM_ID
                            UNION ALL
                            /* STORAGE ID : B100(TCO Ass.BS D/F), R100(TCO Ass.SW D/F) 외주 재고 */
                            SELECT T.DIVISION_ID, T.PLAN_START_YYYYMMDD, T.PLAN_TYPE, T.SEQ, T.SCM_SITE_ID, T.ITEM_ID
                                 , ROUND(SUM(T.QTY), 0) AS QTY
                              FROM SSP_ANL_TCO_STOCK_C T
                             WHERE 1 = 1
                               AND T.DIVISION_ID         = V_DIVISION_ID
                               AND T.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                               AND T.PLAN_TYPE           = V_PLAN_TYPE
                               AND T.SEQ                 = V_SEQ
                             GROUP BY T.DIVISION_ID, T.PLAN_START_YYYYMMDD, T.PLAN_TYPE, T.SEQ, T.ITEM_ID, T.SCM_SITE_ID
                           ) XA
                     GROUP BY XA.DIVISION_ID, XA.PLAN_START_YYYYMMDD, XA.PLAN_TYPE, XA.SEQ, XA.FROM_SITE, XA.ITEM_ID) BOH
                 , (SELECT A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.ITEM_ID, A.FROM_SITE
                         , SUM(A.QTY) AS WH_IN_QTY2, C.SEGMENT3
                      FROM GT_SSP0015_ROWDATA A
                         , SCP_MST_FINAL_ITEM B
                         , SCM_ADM_LOOKUP_MASTER_DETAIL C
                         , SCM_ADM_LOOKUP_MASTER_DETAIL D
                     WHERE B.DIVISION_ID(+) = A.DIVISION_ID
                       AND B.ITEM_ID(+)     = A.ITEM_ID
                       AND C.LOOKUP_TYPE = 'CELL_TYPE_CODE'
                       AND C.VALID_YN    = 'Y'
                       AND C.SEGMENT3    = 'P'
                       AND C.SEGMENT1    = B.CELL_TYPE_GROUP_CODE
                       AND D.LOOKUP_TYPE = 'POUCH_WH_IN_DAY'
                       AND D.SEGMENT1    = SUBSTR(A.ITEM_ID, 1, 3)
                       AND D.VALID_YN    = 'Y'
                       AND A.DIVISION_ID         = V_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = V_PLAN_TYPE
                       AND A.SEQ                 = V_SEQ
                       AND A.MEASURE  = 'WH_IN'
                       AND A.YYYYMMDD > V_DATA_START_YYYYMMDD
                       AND A.YYYYMMDD <= TO_CHAR(TO_DATE(V_DATA_START_YYYYMMDD, 'YYYYMMDD')
                                                 + TO_NUMBER(D.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR), 'YYYYMMDD')
                       AND V_REAL_FLAG = 'Y'
                     GROUP BY A.DIVISION_ID, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.SEQ, A.ITEM_ID, A.FROM_SITE, C.SEGMENT3) B
             WHERE Z.DIVISION_ID         = BOH.DIVISION_ID(+)
               AND Z.PLAN_START_YYYYMMDD = BOH.PLAN_START_YYYYMMDD(+)
               AND Z.PLAN_TYPE           = BOH.PLAN_TYPE(+)
               AND Z.SEQ                 = BOH.SEQ(+)
               AND Z.ITEM_ID             = BOH.ITEM_ID(+)
               AND Z.FROM_SITE           = BOH.FROM_SITE(+)
               AND Z.DIVISION_ID         = B.DIVISION_ID(+)
               AND Z.PLAN_START_YYYYMMDD = B.PLAN_START_YYYYMMDD(+)
               AND Z.PLAN_TYPE           = B.PLAN_TYPE(+)
               AND Z.SEQ                 = B.SEQ(+)
               AND Z.ITEM_ID             = B.ITEM_ID(+)
               AND Z.FROM_SITE           = B.FROM_SITE(+);

            /* -------------5------------ [I]BALANCE : 당일 WH_STOCK - 당일 SHIP_CONFIRM - 당일 POSTP_PLAN */
            INSERT INTO GT_SSP0015_ROWDATA
                   (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
                  , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
                  , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
            SELECT B.DIVISION_ID
                 , B.PLAN_START_YYYYMMDD
                 , B.PLAN_TYPE
                 , B.SEQ
                 , B.ITEM_ID
                 , B.FROM_SITE
                 , B.TO_SITE
                 , 'BALANCE'
                 , B.YYYYMMDD
                 , B.BOD_ID
                 , B.QTY - (SELECT SUM(C.QTY)
                              FROM GT_SSP0015_ROWDATA C
                             WHERE 1 = 1
                               AND B.DIVISION_ID         = C.DIVISION_ID
                               AND B.PLAN_START_YYYYMMDD = C.PLAN_START_YYYYMMDD
                               AND B.PLAN_TYPE           = C.PLAN_TYPE
                               AND B.SEQ                 = C.SEQ
                               AND B.ITEM_ID             = C.ITEM_ID
                               AND B.FROM_SITE           = C.FROM_SITE
                               AND B.YYYYMMDD            = C.YYYYMMDD
                               AND C.MEASURE IN ('SHIP_CONFIRM', 'POSTP_PLAN')
                             GROUP BY C.DIVISION_ID, C.PLAN_START_YYYYMMDD, C.PLAN_TYPE, C.SEQ
                                    , C.ITEM_ID, C.FROM_SITE, C.YYYYMMDD) AS QTY
                 , B.INCOTERMS
                 , B.TRANSPORT_MODE
                 , B.PROJECT_CODE
                 , B.FCST_TYPE
                 , '-'
                 , B.DIVISION_ID
                 , B.DIVISION_ID
              FROM GT_SSP0015_ROWDATA B
             WHERE 1 = 1
               AND B.DIVISION_ID         = V_DIVISION_ID
               AND B.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND B.PLAN_TYPE           = V_PLAN_TYPE
               AND B.SEQ                 = V_SEQ
               AND B.MEASURE = 'WH_STOCK';

        END IF;

        /* 빈 칸(측정항목 x 날짜) 을 0 으로 채운다 */
        INSERT INTO GT_SSP0015_ROWDATA
               (DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE, TO_SITE, MEASURE
              , YYYYMMDD, BOD_ID, QTY, INCOTERMS, TRANSPORT_MODE, PROJECT_CODE, FCST_TYPE, CONFIRM_ID
              , ORIGIN_FROM_DIVISION_ID, ORIGIN_TO_DIVISION_ID)
        SELECT SUB.DIVISION_ID
             , SUB.PLAN_START_YYYYMMDD
             , SUB.PLAN_TYPE
             , SUB.SEQ
             , SUB.ITEM_ID
             , SUB.FROM_SITE
             , SUB.TO_SITE
             , SUB.MEASURE
             , SUB.YYYYMMDD
             , SUB.BOD_ID
             , 0
             , SUB.INCOTERMS
             , SUB.TRANSPORT_MODE
             , SUB.PROJECT_CODE
             , SUB.FCST_TYPE
             , SUB.CONFIRM_ID
             , SUB.DIVISION_ID
             , SUB.DIVISION_ID
          FROM (
                SELECT B.DIVISION_ID
                     , B.PLAN_START_YYYYMMDD
                     , B.PLAN_TYPE
                     , B.SEQ
                     , B.ITEM_ID
                     , B.FROM_SITE
                     , '-'          AS TO_SITE
                     , C.MEASURE    AS MEASURE
                     , A.YYYYMMDD
                     , '-'          AS BOD_ID
                     , '-'          AS INCOTERMS
                     , '-'          AS TRANSPORT_MODE
                     , '-'          AS PROJECT_CODE
                     , '-'          AS FCST_TYPE
                     , '-'          AS CONFIRM_ID
                  FROM (SELECT C.BASIS_YYYYMMDD AS YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M C
                         WHERE 1 = 1
                           AND C.BASIS_YYYYMMDD >= V_DATA_START_YYYYMMDD
                           AND C.BASIS_YYYYMMDD <= P_TO_YYYYMMDD) A
                     , (SELECT DISTINCT DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, ITEM_ID, FROM_SITE
                          FROM GT_SSP0015_ROWDATA) B
                     , (SELECT COLUMN_NAME AS MEASURE
                          FROM SCM_MST_SHEET_MEASURE
                         WHERE 1 = 1
                           AND PROGRAM_ID = P_PROGRAM_ID
                           AND SHEET_NAME = P_SHEET_NAME
                           AND VALID_YN   = 'Y') C
               ) SUB
         WHERE 1 = 1
           AND NOT EXISTS (SELECT 1
                             FROM GT_SSP0015_ROWDATA Z
                            WHERE 1 = 1
                              AND Z.DIVISION_ID         = SUB.DIVISION_ID
                              AND Z.PLAN_START_YYYYMMDD = SUB.PLAN_START_YYYYMMDD
                              AND Z.PLAN_TYPE           = SUB.PLAN_TYPE
                              AND Z.SEQ                 = SUB.SEQ
                              AND Z.ITEM_ID             = SUB.ITEM_ID
                              AND Z.FROM_SITE           = SUB.FROM_SITE
                              AND Z.MEASURE             = SUB.MEASURE
                              AND Z.YYYYMMDD            = SUB.YYYYMMDD);

        /* PIVOT 대상 날짜문자열 생성 (AS-IS 는 수치 SUM 피벗과 LOT 문자 MAX 피벗 두 벌을 UNION ALL 한다) */
        DBMS_LOB.CREATETEMPORARY(V_MQUERY, TRUE);
        DBMS_LOB.CREATETEMPORARY(V_MQUERY1, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            /* 수치 SUM 피벗 - 결과는 문자로 돌려준다(AS-IS CONVERT(NVARCHAR(100), ...)) */
            DBMS_LOB.APPEND(V_MQUERY,
--                ', TO_CHAR(TRUNC(SUM(CASE WHEN A.PIVOT_KEY = ''' || C.YYYYMMDD || ''' THEN NVL(A.QTY_NUM, 0) ELSE 0 END))) AS ' || C.YYYYMMDD || CHR(10));
                ', TO_CHAR(SUM(CASE WHEN A.PIVOT_KEY = ''' || C.YYYYMMDD || ''' THEN TRUNC(A.QTY_NUM) END)) AS ' || C.YYYYMMDD || CHR(10));   -- 2026.09.17 AJS
            /* LOT 문자 MAX 피벗 */
            DBMS_LOB.APPEND(V_MQUERY1,
                ', MAX(CASE WHEN A.PIVOT_KEY = ''' || C.YYYYMMDD || ''' THEN A.QTY_STR END) AS ' || C.YYYYMMDD || CHR(10));
        END LOOP;

        /* LT_DAY · YEILD · LT_UPDATE_YN 스칼라 서브쿼리 */
--        V_LT_SUB := '(SELECT NVL(TO_CHAR(CASE WHEN XB.SEGMENT2 IS NULL THEN XA.LT_FORMATION + NVL(XA.ATTRIBUTE1, 0)'
        V_LT_SUB := 'NVL((SELECT TO_CHAR(CASE WHEN TRIM(XB.SEGMENT2) IS NULL THEN XA.LT_FORMATION + NVL(XA.ATTRIBUTE1, 0)'   -- 2026.09.17 AJS
--                 || ' ELSE TO_NUMBER(XB.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) END), '' '')'
                 || ' ELSE TRUNC(TO_NUMBER(XB.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR)) END)'   -- 2026.09.17 AJS
                 || ' FROM SSP_ANL_FORMATION_C XA, SCM_ADM_LOOKUP_MASTER_DETAIL XB'
                 || ' WHERE XB.LOOKUP_TYPE(+) = ''POUCH_WH_IN_DAY'' AND XB.VALID_YN(+) = ''Y'''
                 || ' AND XB.SEGMENT1(+) = SUBSTR(XA.ITEM_ID, 1, 3) AND XB.SEGMENT3(+) = ''-'''
                 || ' AND XB.SEGMENT4(+) = ''-'' AND XB.SEGMENT5(+) = ''-'''
                 || ' AND XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                 || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
--                 || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1)';
                 || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1), '' '')';   -- 2026.09.17 AJS

--        V_YIELD_SUB := '(SELECT NVL(TO_CHAR(ROUND(XA.SSP_MODIFY_YIELD * 100, 2)), '' '')'
        V_YIELD_SUB := 'NVL((SELECT TO_CHAR(ROUND(XA.SSP_MODIFY_YIELD * 100, 2), ''FM990.00'')'   -- 2026.09.17 AJS
                    || ' FROM SSP_ANL_FORMATION_C XA'
                    || ' WHERE XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                    || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
--                    || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1)';
                    || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''' AND ROWNUM = 1), '' '')';   -- 2026.09.17 AJS

        V_LTYN_SUB := '(SELECT NVL(MIN(XA.ATTRIBUTE2), '' '')'
                   || ' FROM SSP_ANL_FORMATION_C XA'
                   || ' WHERE XA.DIVISION_ID = A.DIVISION_ID AND XA.PLANT_SITE_ID = A.FROM_SITE AND XA.ITEM_ID = A.ITEM_ID'
                   || ' AND XA.PLAN_START_YYYYMMDD = ''' || P_PLAN_START_YYYYMMDD || ''''
                   || ' AND XA.PLAN_TYPE = ''' || P_PLAN_TYPE || ''' AND XA.SEQ = ''' || P_SEQ || ''')';

--        V_FIGURE_EXP := 'TO_CHAR(CEIL(CASE WHEN A.MEASURE = ''MES_FCS_HOLD''    THEN NVL(W.TOTAL_QTY, 0)'
        /* AS-IS : 네 측정항목 외에는 0 -> REPLACE(...,0,' ') 로 공백 한 칸 */   -- 2026.09.17 AJS
        V_FIGURE_EXP := 'CASE WHEN A.MEASURE IN (''MES_FCS_HOLD'', ''MES_FCS_RELEASE'', ''WH_STOCK'', ''BALANCE'')'   -- 2026.09.17 AJS
                     || ' THEN TO_CHAR(CEIL(CASE WHEN A.MEASURE = ''MES_FCS_HOLD''    THEN NVL(W.TOTAL_QTY, 0)'   -- 2026.09.17 AJS
                     || ' WHEN A.MEASURE = ''MES_FCS_RELEASE'' THEN NVL(X.HOLD_QTY, 0)'
                     || ' WHEN A.MEASURE = ''WH_STOCK''        THEN NVL(Y.MES_QTY, 0)'
                     || ' WHEN A.MEASURE = ''BALANCE''         THEN NVL(Y.FCS_QTY, 0)'
--                     || ' ELSE 0 END), ''FM999,999,999,999,990'')';
                     || ' ELSE 0 END), ''FM999,999,999,999,990'') ELSE '' '' END';   -- 2026.09.17 AJS

        DECLARE
            V_SEL_HEAD  CLOB;
            V_FROM_PART CLOB;
            V_JOIN_PART CLOB;
            V_GRP_PART  CLOB;
        BEGIN

            V_SEL_HEAD := ' SELECT A.DIVISION_ID' || CHR(10)
                       || '      , A.FROM_SITE' || CHR(10)
                       || '      , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), ''-'') AS FROM_SITE_NM' || CHR(10)
                       || '      , A.PLAN_START_YYYYMMDD' || CHR(10)
                       || '      , A.PLAN_TYPE' || CHR(10)
                       || '      , A.ITEM_ID' || CHR(10)
                       || '      , NVL(A.SHIP_FROZEN, 0) AS SHIP_FROZEN' || CHR(10)
                       || '      , A.SEQ' || CHR(10)
                       || '      , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME' || CHR(10)
                       || '      , A.MEASURE' || CHR(10)
                       || '      , A.MEASURE_NAME' || CHR(10)
                       || '      , A.USER_SORT_ORDER_NO' || CHR(10)
                       || '      , A.PSI_NAME' || CHR(10)
                       || '      , A.FROM_YYYYMMDD' || CHR(10)
                       || '      , A.TO_YYYYMMDD' || CHR(10)
                       || '      , ' || V_LT_SUB || ' AS LT_DAY' || CHR(10)
                       || '      , ' || V_YIELD_SUB || ' AS YEILD' || CHR(10)
                       || '      , ' || V_LTYN_SUB || ' AS LT_UPDATE_YN' || CHR(10)
                       || '      , (CASE WHEN A.MEASURE = ''MES_FCS_HOLD'' THEN ''oWMS'' WHEN A.MEASURE = ''MES_FCS_RELEASE'' THEN ''Hold'''
                       || '              WHEN A.MEASURE = ''WH_STOCK'' THEN ''MES'' WHEN A.MEASURE = ''BALANCE'' THEN ''FCS'' ELSE '' '' END) AS TYPE' || CHR(10)
                       || '      , ' || V_FIGURE_EXP || ' AS FIGURE' || CHR(10);

            V_FROM_PART := '   FROM (SELECT T3.DIVISION_ID, T3.PLAN_START_YYYYMMDD, T3.PLAN_TYPE, T3.FROM_SITE' || CHR(10)
                        || '              , T3.ITEM_ID, T3.SEQ, T3.SHIP_FROZEN, T3.PIVOT_KEY' || CHR(10)
                        || '              , CASE WHEN T0.COLUMN_NAME = ''PROD_DATE''' || CHR(10)
                        || '                     THEN TO_NUMBER(T3.QTY_STR DEFAULT NULL ON CONVERSION ERROR)' || CHR(10)
                        || '                     ELSE T3.QTY_NUM END AS QTY_NUM' || CHR(10)
                        || '              , CASE WHEN T0.COLUMN_NAME = ''LOT'' THEN T3.QTY_STR' || CHR(10)
                        || '                     ELSE TO_CHAR(T3.QTY_NUM) END AS QTY_STR' || CHR(10)
                        || '              , T0.COLUMN_NAME       AS MEASURE' || CHR(10)
                        || '              , T0.COLUMN_LABEL_NAME AS MEASURE_NAME' || CHR(10)
                        || '              , T0.ATTRIBUTE1        AS PSI_NAME' || CHR(10)
                        || '              , NVL(T1.SORT_ORDER_NO, T0.SORT_ORDER_NO) AS USER_SORT_ORDER_NO' || CHR(10)
                        || '              , ''' || P_FROM_YYYYMMDD || ''' AS FROM_YYYYMMDD' || CHR(10)
                        || '              , ''' || P_TO_YYYYMMDD || ''' AS TO_YYYYMMDD' || CHR(10)
                        || '           FROM SCM_MST_SHEET_MEASURE T0' || CHR(10)
                        || '              , SCM_MST_TITLESET_USER T1' || CHR(10)
                        || '              , (SELECT TT0.DIVISION_ID, TT0.PLAN_START_YYYYMMDD, TT0.PLAN_TYPE, TT0.FROM_SITE' || CHR(10)
                        || '                      , TT0.ITEM_ID, ''D_'' || TT0.YYYYMMDD AS PIVOT_KEY, TT0.MEASURE AS MEASURE_KEY' || CHR(10)
                        || '                      , SUM(TT0.QTY) AS QTY_NUM, MAX(TT0.ATTRIBUTE1) AS QTY_STR' || CHR(10)
                        || '                      , MAX(TT0.SEQ) AS SEQ, TT2.SHIP_FROZEN' || CHR(10)
                        || '                   FROM GT_SSP0015_ROWDATA TT0, SCM_MST_SITE TT2' || CHR(10)
                        || '                  WHERE (CASE WHEN TT0.DIVISION_ID = ''EE'' THEN TT0.ORIGIN_FROM_DIVISION_ID ELSE TT0.DIVISION_ID END) = TT2.DIVISION_ID(+)' || CHR(10)
                        || '                    AND TT0.FROM_SITE = TT2.SCM_SITE_ID(+)' || CHR(10)
                        || '                    AND TT2.VALID_YN(+) = ''Y''' || CHR(10)
                        || '                    AND TT0.YYYYMMDD >= ''' || P_FROM_YYYYMMDD || '''' || CHR(10)
                        || '                    AND TT0.YYYYMMDD <= ''' || P_TO_YYYYMMDD || '''' || CHR(10)
                        || '                    AND EXISTS (SELECT 1 FROM (SELECT DIVISION_ID, MAX(PLAN_SEQ) AS PLAN_SEQ' || CHR(10)
                        || '                                                 FROM SSP_PLAN_VERSION_V' || CHR(10)
                        || '                                                WHERE PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '                                                  AND CONFIRM_FLAG = ''Y''' || CHR(10)
                        || '                                                  AND PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '                                                GROUP BY DIVISION_ID) SA' || CHR(10)
                        || '                                 WHERE SA.DIVISION_ID = TT0.DIVISION_ID AND SA.PLAN_SEQ = TT0.SEQ)' || CHR(10)
                        || '                  GROUP BY TT0.DIVISION_ID, TT0.PLAN_START_YYYYMMDD, TT0.PLAN_TYPE, TT0.FROM_SITE' || CHR(10)
                        || '                         , TT0.ITEM_ID, TT0.YYYYMMDD, TT2.SHIP_FROZEN, TT0.MEASURE) T3' || CHR(10)
                        || '          WHERE T1.PROGRAM_ID(+)  = T0.PROGRAM_ID' || CHR(10)
                        || '            AND T1.SHEET_NAME(+)  = T0.SHEET_NAME' || CHR(10)
                        || '            AND T1.COLUMN_NAME(+) = T0.COLUMN_NAME' || CHR(10)
                        || '            AND T1.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                        || '            AND T0.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                        || '            AND T0.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                        || '            AND T0.VALID_YN   = ''Y''' || CHR(10)
                        || '            AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                        || '                  OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SB' || CHR(10)
                        || '                              WHERE SB.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                        || '                                AND SB.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                        || '                                AND SB.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                        || '                                AND SB.COLUMN_NAME = T0.COLUMN_NAME))' || CHR(10)
                        || '            AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T0.DEFAULT_FLAG = ''Y'')' || CHR(10)
                        || '                  OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                        || '            AND T0.COLUMN_NAME = T3.MEASURE_KEY' || CHR(10);

            V_JOIN_PART := '        ) A' || CHR(10)
                        || '      , (SELECT S.DIVISION_ID, S.PLAN_START_YYYYMMDD, S.PLAN_TYPE, S.SEQ, S.FROM_SITE, S.ITEM_ID, SUM(S.QTY) AS TOTAL_QTY' || CHR(10)
                        || '           FROM SSP_ANL_WH_STOCK_V S' || CHR(10)
                        || '          WHERE S.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND S.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND S.DIVISION_ID = ''' || V_DIVISION_ID || '''' || CHR(10)
                        || '            AND S.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '          GROUP BY S.DIVISION_ID, S.PLAN_START_YYYYMMDD, S.PLAN_TYPE, S.SEQ, S.FROM_SITE, S.ITEM_ID) W' || CHR(10)
                        || '      , (SELECT K.DIVISION_ID, K.FROM_SITE, K.ITEM_ID, SUM(K.HOLD_QTY) AS HOLD_QTY' || CHR(10)
                        || '           FROM SSP_ANL_HOLD_STOCK K' || CHR(10)
                        || '          WHERE K.HOLD_YYYYMMDD <= ''' || TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') || '''' || CHR(10)
                        || '            AND K.RELEASE_YYYYMMDD >= ''' || TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD') || '''' || CHR(10)
                        || '            AND K.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND K.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND K.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '          GROUP BY K.DIVISION_ID, K.FROM_SITE, K.ITEM_ID) X' || CHR(10)
                        || '      , (SELECT M.DIVISION_ID, M.PLAN_START_YYYYMMDD, M.PLAN_TYPE, M.SEQ, M.FROM_SITE, M.ITEM_ID' || CHR(10)
                        || '              , SUM(M.LOT_QTY_MES) AS MES_QTY, SUM(M.LOT_QTY_FCS) AS FCS_QTY' || CHR(10)
                        || '           FROM SSP_ANL_MES_FCS_STOCK_40_C M' || CHR(10)
                        || '          WHERE M.PLAN_START_YYYYMMDD = ''' || V_PLAN_START_YYYYMMDD || '''' || CHR(10)
                        || '            AND M.PLAN_TYPE = ''' || P_PLAN_TYPE || '''' || CHR(10)
                        || '            AND M.DIVISION_ID = ''' || V_DIVISION_ID || '''' || CHR(10)
                        || '            AND M.AVAILABLE_YN <> ''N''' || CHR(10)
                        || '            AND M.CHANGE_STATUS <> ''D''' || CHR(10)
                        || '            AND M.SEQ = ''' || P_SEQ || '''' || CHR(10)
                        || '            AND M.AVAILABLE_YN = ''Y''' || CHR(10)
                        || '          GROUP BY M.DIVISION_ID, M.PLAN_START_YYYYMMDD, M.PLAN_TYPE, M.SEQ, M.FROM_SITE, M.ITEM_ID) Y' || CHR(10)
                        || '  WHERE A.DIVISION_ID = W.DIVISION_ID(+) AND A.PLAN_START_YYYYMMDD = W.PLAN_START_YYYYMMDD(+)' || CHR(10)
                        || '    AND A.FROM_SITE = W.FROM_SITE(+) AND A.ITEM_ID = W.ITEM_ID(+)' || CHR(10)
                        || '    AND A.DIVISION_ID = X.DIVISION_ID(+) AND A.FROM_SITE = X.FROM_SITE(+) AND A.ITEM_ID = X.ITEM_ID(+)' || CHR(10)
                        || '    AND A.DIVISION_ID = Y.DIVISION_ID(+) AND A.PLAN_START_YYYYMMDD = Y.PLAN_START_YYYYMMDD(+)' || CHR(10)
                        || '    AND A.FROM_SITE = Y.FROM_SITE(+) AND A.ITEM_ID = Y.ITEM_ID(+)' || CHR(10);

            V_GRP_PART := '  GROUP BY A.DIVISION_ID, A.FROM_SITE, A.PLAN_START_YYYYMMDD, A.PLAN_TYPE, A.ITEM_ID' || CHR(10)
                       || '         , A.SHIP_FROZEN, A.SEQ, A.MEASURE, A.MEASURE_NAME, A.USER_SORT_ORDER_NO, A.PSI_NAME' || CHR(10)
                       || '         , A.FROM_YYYYMMDD, A.TO_YYYYMMDD, W.TOTAL_QTY, X.HOLD_QTY, Y.MES_QTY, Y.FCS_QTY' || CHR(10);

            V_MEXEC := 'SELECT * FROM (' || CHR(10)
                    || V_SEL_HEAD || V_MQUERY || V_FROM_PART
                    || '            AND T3.MEASURE_KEY != ''LOT''' || CHR(10)
                    || V_JOIN_PART || V_GRP_PART
                    || ' UNION ALL' || CHR(10)
                    || V_SEL_HEAD || V_MQUERY1 || V_FROM_PART
                    || '            AND T3.MEASURE_KEY = ''LOT''' || CHR(10)
                    || V_JOIN_PART || V_GRP_PART
                    || ') TTTT ORDER BY DIVISION_ID, FROM_SITE, ITEM_ID, USER_SORT_ORDER_NO';

        END;

        OPEN O_RC1 FOR V_MEXEC;

        /* NOTE, Prod_Qty Load */
        P_SSP0015_GET_SHIPMENT_PSI_COMMENTS(V_DIVISION_ID, V_PLAN_START_YYYYMMDD, V_FROM_SITE, P_ITEM_ID
                                          , P_FROM_YYYYMMDD, P_TO_YYYYMMDD, O_RC2, O_RC3);

        DBMS_LOB.FREETEMPORARY(V_MQUERY);
        DBMS_LOB.FREETEMPORARY(V_MQUERY1);

    END P_SSP0015_GET_SHIPMENT_PSI;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_PACKER
       AS-IS SSP0015_GET_SHIPMENT_PSI_PACKER
       ※ #TEMP 9벌 -> GT_SSP0015_PK_* 9벌
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_PACKER
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_PACKER
         * Description  : Shipment PSI (Packer)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020/11/10   KIMYONGHO      SSP0015_GET_SHIPMENT_PSI 복사 신규추가
         * 2022/02/21   SMS            @v_confirm_date 일자 scm_mst_site(ship_frozen)로 설정
         * 2023/09/19   jilee          G182-P (Group='P',OSP='N')인 사이트 화면에서 제외
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_CNT_USR_MEASURE       PLS_INTEGER := 0;
        V_CUTOFF_DATE           VARCHAR2(8 CHAR);
        V_BOH_YYYYMMDD          VARCHAR2(8 CHAR);
        V_PLAN_CUTOFF_DATE_TIME DATE;
        V_MQRY_SUM              CLOB := EMPTY_CLOB();
        V_MEXEC                 CLOB;
    BEGIN

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_PK_SHIP_REQ;
        DELETE FROM GT_SSP0015_PK_PACK_RTF;
        DELETE FROM GT_SSP0015_PK_SHIP_CONFIRM;
        DELETE FROM GT_SSP0015_PK_PROD_PLAN;
        DELETE FROM GT_SSP0015_PK_WH_STOCK;
        DELETE FROM GT_SSP0015_PK_ERP_STOCK;
        DELETE FROM GT_SSP0015_PK_ROWDATA;
        DELETE FROM GT_SSP0015_PK_RESULT;
        DELETE FROM GT_SSP0015_PK_RESULT_PIVOT;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        V_CUTOFF_DATE  := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');
        V_BOH_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');

        /* AS-IS : datepart(DW, ...) = 2 는 월요일. Oracle 은 NLS 에 좌우되지 않도록 TO_CHAR(,'D','NLS_DATE_LANGUAGE=AMERICAN') 대신
           고정 기준일과의 차로 요일을 구한다(1900-01-01 은 월요일). */
        IF MOD(TRUNC(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')) - TO_DATE('19000101', 'YYYYMMDD'), 7) = 0 THEN
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 15:30:00', 'YYYYMMDD HH24:MI:SS');
        ELSE
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 07:15:00', 'YYYYMMDD HH24:MI:SS');
        END IF;

        /* //SHIP_REQ Measure 추가 */
        INSERT INTO GT_SSP0015_PK_SHIP_REQ
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'SHIP_REQ'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.YYYYMMDD;

        /* //PACK_RTF Measure 추가 */
        INSERT INTO GT_SSP0015_PK_PACK_RTF
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'PACK_RTF'
             , A.ATTRIBUTE3
--             , SUM(TO_NUMBER(A.ATTRIBUTE4 DEFAULT NULL ON CONVERSION ERROR))
             , SUM(ROUND(TO_NUMBER(A.ATTRIBUTE4 DEFAULT NULL ON CONVERSION ERROR)))   -- 2026.09.17 AJS
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND A.ATTRIBUTE2 <> 'N'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.ATTRIBUTE3, A.ATTRIBUTE4;

        /* //SHIP_CONFIRM Measure 추가 */
        INSERT INTO GT_SSP0015_PK_SHIP_CONFIRM
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , 'SHIP_CONFIRM'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_CONFIRM A
             , SCM_MST_SITE S
         WHERE S.DIVISION_ID = A.DIVISION_ID
           AND S.SCM_SITE_ID = A.FROM_SITE
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND A.BIZ_TYPE  = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           /* jilee 230919 */
           AND S.OSP_YN = 'Y'
         GROUP BY A.DIVISION_ID, A.ITEM_ID, A.FROM_SITE, A.YYYYMMDD
        UNION ALL
        /* 20220221 SMS @v_confirm_date 일자 scm_mst_site(ship_frozen)로 설정 */
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , B.FROM_SITE
             , 'SHIP_CONFIRM'
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_REQ_P A
             , SCP_MST_BOD_N_V B
             , SCM_MST_SITE FS
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.BOD_ID      = B.BOD_ID
           AND A.DIVISION_ID = FS.DIVISION_ID
           AND B.FROM_SITE   = FS.SCM_SITE_ID
           AND FS.VALID_YN   = 'Y'
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + NVL(FS.SHIP_FROZEN, 0), 'YYYYMMDD')
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR B.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.ITEM_ID, B.FROM_SITE, A.YYYYMMDD;

        /* //PROD_PLAN Measure 추가 */
        INSERT INTO GT_SSP0015_PK_PROD_PLAN
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.PACK_MODEL_CODE
             , A.SCM_SITE_ID
             , 'PROD_PLAN'
             , A.PROD_DATE
             , NVL(A.PROD_QTY, 0)
          FROM SCM_DNM_SCS_PROD_PLAN A
             , (SELECT DIVISION_ID, MAX(CUTOFF_DATE) AS CUTOFF_DATE, PACK_MODEL_CODE, SCM_SITE_ID, PROD_DATE
                  FROM SCM_DNM_SCS_PROD_PLAN
                 GROUP BY DIVISION_ID, PACK_MODEL_CODE, SCM_SITE_ID, PROD_DATE) B
         WHERE A.DIVISION_ID     = B.DIVISION_ID
           AND A.CUTOFF_DATE     = B.CUTOFF_DATE
           AND A.PACK_MODEL_CODE = B.PACK_MODEL_CODE
           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
           AND A.PROD_DATE       = B.PROD_DATE
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.PROD_DATE >= P_FROM_YYYYMMDD
           AND A.PROD_DATE <= P_TO_YYYYMMDD
           AND NVL(A.PROD_QTY, 0) > 0
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.PACK_MODEL_CODE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.PACK_MODEL_CODE IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))));

        /* //WH_STOCK Measure 추가 */
        INSERT INTO GT_SSP0015_PK_WH_STOCK
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , 'WH_STOCK'
             , A.STOCK_DATE
             , SUM(NVL(A.STOCK_QTY, 0))
          FROM SCM_DNM_SCS_STOCK A
         WHERE 1 = 1
           AND A.DIVISION_ID      = P_DIVISION_ID
           AND A.CUTOFF_DATE      = V_CUTOFF_DATE
           AND A.LAST_UPDATE_DATE <= V_PLAN_CUTOFF_DATE_TIME
           AND A.CELL_PACK        = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.STOCK_DATE;

        /* //ERP 재고 데이터 */
        INSERT INTO GT_SSP0015_PK_ERP_STOCK
               (DIVISION_ID, PLANT_ID, ITEM_ID, BOH_TYPE, YYYYMMDD, QTY)
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.ITEM_ID
             , 'ERP'
             , IA.CUTOFF_DATE
             , SUM(IA.SCM_QTY)
          FROM (
                SELECT DISTINCT
                       A.DIVISION_ID
                     , A.COMPANY_ID
                     , A.ITEM_ID
                     , A.SCM_QTY
                     , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
                     , A.PLANT_ID
                     , A.STOCK_TYPE
                  FROM SCM_DNM_STOCK_V A
                 WHERE 1 = 1
                   AND A.DIVISION_ID = '40'
                   AND A.COMPANY_ID  = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER', 'ESOC')   /* C100 */
                   AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                   AND A.PLANT_ID    = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER', 'A010')   /* A010 */
                   AND A.STOCK_TYPE  = 'INVENTORY'
               ) IA
         WHERE IA.STOCK_TYPE = 'INVENTORY'
         GROUP BY IA.DIVISION_ID, IA.COMPANY_ID, IA.ITEM_ID, IA.CUTOFF_DATE, IA.PLANT_ID, IA.STOCK_TYPE;

        /* //TMP_ROWDATA */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
          FROM (
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_SHIP_REQ
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_PACK_RTF
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_SHIP_CONFIRM
                UNION
                SELECT DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY FROM GT_SSP0015_PK_PROD_PLAN
               ) T0
         GROUP BY T0.DIVISION_ID, T0.ITEM_ID, T0.FROM_SITE, T0.MEASURE, T0.YYYYMMDD;

        /* //4. WH_STOCK - 전일 WH_STOCK + PROD_PLAN - SHIP_CONFIRM 누적 + SCS 재고 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , 'WH_STOCK'
             , T0.YYYYMMDD
             , (SELECT NVL(SUM(CASE WHEN TT0.MEASURE = 'SHIP_CONFIRM' THEN -1 * NVL(TT0.QTY, 0)
                                    WHEN TT0.MEASURE = 'PROD_PLAN'    THEN      NVL(TT0.QTY, 0)
                                    ELSE 0 END), 0)
                  FROM GT_SSP0015_PK_ROWDATA TT0
                 WHERE 1 = 1
                   AND TT0.DIVISION_ID = T0.DIVISION_ID
                   AND TT0.FROM_SITE   = T0.FROM_SITE
                   AND TT0.ITEM_ID     = T0.ITEM_ID
                   AND TT0.MEASURE IN ('SHIP_CONFIRM', 'PROD_PLAN')
                   AND TT0.YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND TT0.YYYYMMDD <= T0.YYYYMMDD)
               + NVL(T1.QTY, 0)
          FROM (
                /* Deduplication */
                SELECT R.DIVISION_ID
                     , R.FROM_SITE
                     , R.ITEM_ID
                     , C.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA R
                     , (SELECT BASIS_YYYYMMDD AS YYYYMMDD
                          FROM SCM_SYS_CALENDAR_M
                         WHERE BASIS_YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                           AND BASIS_YYYYMMDD <= P_TO_YYYYMMDD) C
                 WHERE C.YYYYMMDD(+) >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                 GROUP BY R.DIVISION_ID, R.FROM_SITE, R.ITEM_ID, C.YYYYMMDD
               ) T0
             , (SELECT A.DIVISION_ID, A.ITEM_ID, A.FROM_SITE, A.QTY
                  FROM GT_SSP0015_PK_WH_STOCK A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD    = V_CUTOFF_DATE
                   AND A.MEASURE     = 'WH_STOCK'
                   AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                         OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                         OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                   AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                         OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))) T1
         WHERE T0.DIVISION_ID = T1.DIVISION_ID(+)
           AND T0.FROM_SITE   = T1.FROM_SITE(+)
           AND T0.ITEM_ID     = T1.ITEM_ID(+)
           AND T0.YYYYMMDD   <= P_TO_YYYYMMDD;

        /* //BALANCE Measure 추가 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT DIVISION_ID
             , ITEM_ID
             , FROM_SITE
             , 'BALANCE'
             , YYYYMMDD
             , NVL(SUM(CASE WHEN MEASURE = 'SHIP_CONFIRM' THEN -1 * NVL(QTY, 0)
                            WHEN MEASURE = 'WH_STOCK'     THEN      NVL(QTY, 0)
                            ELSE 0 END), 0)
          FROM GT_SSP0015_PK_ROWDATA
         WHERE 1 = 1
           AND MEASURE IN ('SHIP_CONFIRM', 'WH_STOCK', 'PROD_PLAN')
           AND YYYYMMDD >= TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
         GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID, YYYYMMDD;

        /* //TMP_RESULT_TABLE */
        INSERT INTO GT_SSP0015_PK_RESULT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY, SEQ)
        SELECT DISTINCT
               X.DIVISION_ID
             , X.ITEM_ID
             , X.FROM_SITE
             , X.MEASURE
             , X.YYYYMMDD
             , NVL(R.QTY, 0)
             , X.SEQ
          FROM (
                SELECT T.DIVISION_ID
                     , T.ITEM_ID
                     , NVL(T.FROM_SITE, '/')    AS FROM_SITE
                     , T.QTY
                     , TT1.COLUMN_NAME          AS MEASURE
                     , TT1.COLUMN_LABEL_NAME    AS MEASURE_NAME
                     , TT1.ATTRIBUTE3           AS BACK_COLOR
                     , TT1.SORT_ORDER_NO        AS SEQ
                     , T.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA T
                     , SCM_MST_SHEET_MEASURE TT1
                     , SCM_MST_TITLESET_USER T3
                 WHERE TT1.PROGRAM_ID = P_PROGRAM_ID
                   AND TT1.SHEET_NAME = P_SHEET_NAME
                   AND T3.PROGRAM_ID(+)  = TT1.PROGRAM_ID
                   AND T3.SHEET_NAME(+)  = TT1.SHEET_NAME
                   AND T3.COLUMN_NAME(+) = TT1.COLUMN_NAME
                   AND T3.USER_ID(+)     = P_USER_ID
               ) X
             , GT_SSP0015_PK_ROWDATA R
         WHERE R.DIVISION_ID(+) = X.DIVISION_ID
           AND R.ITEM_ID(+)     = X.ITEM_ID
           AND R.MEASURE(+)     = X.MEASURE
           AND R.YYYYMMDD(+)    = X.YYYYMMDD
           AND R.FROM_SITE(+)   = X.FROM_SITE
           AND X.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE');

        /* //PIVOT 대상 */
        INSERT INTO GT_SSP0015_PK_RESULT_PIVOT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ)
        SELECT DISTINCT
               T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , 'D_' || T0.YYYYMMDD
             , T1.BASIS_YYYYMM
             , SUBSTR(T1.BASIS_YYYYMM, -4) || T1.ISO_WEEK
             , T0.QTY
             , T0.SEQ
          FROM GT_SSP0015_PK_RESULT T0
             , SCM_SYS_CALENDAR_M T1
         WHERE T0.YYYYMMDD = T1.BASIS_YYYYMMDD(+);

        /* PIVOT 대상 날짜문자열 생성 */
        DBMS_LOB.CREATETEMPORARY(V_MQRY_SUM, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMM = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.ISO_WEEK = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMMDD = SUBSTR(''' || C.YYYYMMDD || ''', -10) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            END IF;
        END LOOP;

        V_MEXEC := 'SELECT DISTINCT TTT.* FROM ( ' || CHR(10)
                || '  SELECT T0.DIVISION_ID' || CHR(10)
                || '       , T0.ITEM_ID' || CHR(10)
                || '       , NVL(IT.NICK_NAME, ''-'')      AS NICK_NAME' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN ''SCS'' WHEN T0.MEASURE = ''BALANCE'' THEN ''ERP'' ELSE '' '' END) AS TYPE' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN NVL(T5.QTY, 0)' || CHR(10)
                || '               WHEN T0.MEASURE = ''BALANCE''  THEN NVL(T6.QTY, 0)' || CHR(10)
                || '          ELSE NULL END)               AS FIGURE' || CHR(10)
                || '       , NVL(T0.FROM_SITE, ''-'')      AS FROM_SITE' || CHR(10)
                || '       , NVL(T4.SITE_DESCRIPTION, ''/'') AS FROM_SITE_NM' || CHR(10)
                || '       , T0.MEASURE                    AS MEASURE' || CHR(10)
                || '       , T2.ATTRIBUTE1                 AS PSI_NAME' || CHR(10)
                || '       , T0.SEQ' || CHR(10)
                || '       , CASE WHEN NVL(T4.SHIP_FROZEN, 0) - 1 > 0 THEN T4.SHIP_FROZEN - 1 ELSE 0 END AS SHIP_FROZEN' || CHR(10)
                || V_MQRY_SUM
                || '    FROM GT_SSP0015_PK_RESULT_PIVOT T0' || CHR(10)
                || '       , SCM_MST_SHEET_MEASURE T2' || CHR(10)
                || '       , SCM_MST_TITLESET_USER T3' || CHR(10)
                || '       , SCM_MST_SITE T4' || CHR(10)
                || '       , GT_SSP0015_PK_WH_STOCK T5' || CHR(10)
                || '       , GT_SSP0015_PK_ERP_STOCK T6' || CHR(10)
                || '       , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME FROM SCM_MST_ITEM_SN' || CHR(10)
                || '           WHERE DIVISION_ID = ''' || P_DIVISION_ID || '''' || CHR(10)
                || '             AND ACTIVE_FLAG = ''Y''' || CHR(10)
                || '             AND SCP_OPERATION_GROUP = ''P'') IT' || CHR(10)
                || '       , SSP_MST_MODEL_USER TT3' || CHR(10)
                || '   WHERE T0.MEASURE = T2.COLUMN_NAME' || CHR(10)
                || '     AND T2.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '     AND T2.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '     AND T3.PROGRAM_ID(+)  = T2.PROGRAM_ID' || CHR(10)
                || '     AND T3.SHEET_NAME(+)  = T2.SHEET_NAME' || CHR(10)
                || '     AND T3.COLUMN_NAME(+) = T2.COLUMN_NAME' || CHR(10)
                || '     AND T3.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                || '     AND T0.DIVISION_ID = T4.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T4.SCM_SITE_ID(+)' || CHR(10)
                || '     AND T4.VALID_YN(+) = ''Y''' || CHR(10)
                || '     AND T0.DIVISION_ID = T5.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T5.FROM_SITE(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T5.ITEM_ID(+)' || CHR(10)
                || '     AND T5.YYYYMMDD(+) = ''' || V_CUTOFF_DATE || '''' || CHR(10)
                || '     AND T5.MEASURE(+)  = ''WH_STOCK''' || CHR(10)
                || '     AND T0.DIVISION_ID = T6.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T6.ITEM_ID(+)' || CHR(10)
                || '     AND T0.DIVISION_ID = IT.DIVISION_ID' || CHR(10)
                || '     AND T0.ITEM_ID     = IT.ITEM_ID' || CHR(10)
                || '     AND TT3.DIVISION_ID(+) = T0.DIVISION_ID' || CHR(10)
                || '     AND TT3.FROM_SITE(+)   = T0.FROM_SITE' || CHR(10)
                || '     AND TT3.ITEM_ID(+)     = T0.ITEM_ID' || CHR(10)
                || '     AND TT3.VALID_YN(+)    = ''Y''' || CHR(10)
                || '     AND T2.VALID_YN = ''Y''' || CHR(10)
                || '     AND ((''' || P_NONCHK || ''' = ''Y'' AND 1 = 1)' || CHR(10)
--                || '           OR TT3.USER_ID IN (SELECT CASE WHEN ''' || P_MYMODELCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END FROM DUAL' || CHR(10)
                || '           OR TT3.USER_ID IN (SELECT CASE WHEN ''' || P_MYMODELCHK || ''' = ''Y'' THEN ''' || LOWER(P_USER_ID) || ''' ELSE ''X'' END FROM DUAL' || CHR(10)   -- 2026.09.17 AJS
                || '                               UNION' || CHR(10)
                || '                              SELECT CASE WHEN ''' || P_DELEGATEECHK || ''' = ''Y'' THEN USER_ID ELSE ''X'' END' || CHR(10)
--                || '                                FROM SSP_MST_DELEGATE WHERE VALID_YN = ''Y'' AND DELEGATEE_ID = ''' || P_USER_ID || ''' GROUP BY USER_ID)' || CHR(10)
                || '                                FROM SSP_MST_DELEGATE WHERE VALID_YN = ''Y'' AND DELEGATEE_ID = ''' || LOWER(P_USER_ID) || ''' GROUP BY USER_ID)' || CHR(10)   -- 2026.09.17 AJS
--                || '           OR TT3.PART_LEADER = CASE WHEN ''' || P_PARTLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END' || CHR(10)
                || '           OR TT3.PART_LEADER = CASE WHEN ''' || P_PARTLEADERCHK || ''' = ''Y'' THEN ''' || LOWER(P_USER_ID) || ''' ELSE ''X'' END' || CHR(10)   -- 2026.09.17 AJS
--                || '           OR TT3.TEAM_LEADER = CASE WHEN ''' || P_TEAMLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END)' || CHR(10);
                || '           OR TT3.TEAM_LEADER = CASE WHEN ''' || P_TEAMLEADERCHK || ''' = ''Y'' THEN ''' || LOWER(P_USER_ID) || ''' ELSE ''X'' END)' || CHR(10);   -- 2026.09.17 AJS

        IF P_FROM_SITE IS NOT NULL THEN
            V_MEXEC := V_MEXEC
                || '     AND T0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(''' || P_FROM_SITE || ''', '','')))' || CHR(10);
        END IF;

        V_MEXEC := V_MEXEC
                || '     AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                || '           OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SA' || CHR(10)
                || '                       WHERE SA.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '                         AND SA.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '                         AND SA.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                || '                         AND SA.COLUMN_NAME = T2.COLUMN_NAME))' || CHR(10)
                || '     AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T2.DEFAULT_FLAG = ''Y'')' || CHR(10)
                || '           OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                || '   GROUP BY T0.DIVISION_ID, T0.ITEM_ID, IT.NICK_NAME, T0.FROM_SITE, T4.SITE_DESCRIPTION' || CHR(10)
                || '          , T0.MEASURE, T0.SEQ, T2.ATTRIBUTE1, T5.QTY, T6.QTY, T4.SHIP_FROZEN' || CHR(10)
                || ') TTT' || CHR(10)
                || ' ORDER BY TTT.DIVISION_ID, TTT.FROM_SITE DESC, TTT.ITEM_ID, TTT.SEQ ASC';

        OPEN O_RC1 FOR V_MEXEC;

        DBMS_LOB.FREETEMPORARY(V_MQRY_SUM);

    END P_SSP0015_GET_SHIPMENT_PSI_PACKER;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
       AS-IS SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
       ※ 과거 버전 조회라 계산하지 않고 SSP_ANL_SHIP_PLAN_P 스냅샷을 그대로 읽는다.
       ※ 마지막 피벗은 조회기간만큼 날짜 칸을 만들므로 정적 SQL 로 옮길 수 없다.
          OPEN 커서 FOR 문자열 로 두고 조립 문자열은 CLOB 로 둔다.
          (CNS 전환가이드 8항 Dynamic SQL 금지의 예외 - 2항 결과 동일성을 우선한 자리)
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PROGRAM_ID            IN  VARCHAR2,
        P_SHEET_NAME            IN  VARCHAR2,
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_SEQ                   IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST
         * Description  : Shipment PSI (Packer) - 과거 버전
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2020/11/10   KIMYONGHO      SSP0015_GET_SHIPMENT_PSI 복사 신규추가
         * 2022/02/21   SMS            SHIP_FROZEN 추가 (scm_mst_site(ship_frozen))
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
        V_CNT_USR_MEASURE   PLS_INTEGER := 0;
        V_CUTOFF_DATE       VARCHAR2(8 CHAR);
        V_PLAN_CUTOFF_DATE_TIME DATE;   -- 2026.09.17 AJS
        V_MQRY_SUM          CLOB := EMPTY_CLOB();
        V_MEXEC             CLOB;
    BEGIN

        /* GTT 초기화 - TRUNCATE 금지 */
        DELETE FROM GT_SSP0015_PK_ROWDATA;
        DELETE FROM GT_SSP0015_PK_RESULT;
        DELETE FROM GT_SSP0015_PK_RESULT_PIVOT;
        DELETE FROM GT_SSP0015_PK_WH_STOCK;
        DELETE FROM GT_SSP0015_PK_ERP_STOCK;

        SELECT COUNT(*)
          INTO V_CNT_USR_MEASURE
          FROM SCM_MST_TITLESET_USER
         WHERE 1 = 1
           AND PROGRAM_ID = P_PROGRAM_ID
           AND SHEET_NAME = P_SHEET_NAME
           AND USER_ID    = P_USER_ID;

        V_CUTOFF_DATE := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');

        /* AS-IS : datepart(DW, 기준일) = 2(월요일, DATEFIRST 7) 이면 15:30, 아니면 07:15 - 1900-01-01 은 월요일 */   -- 2026.09.17 AJS
        IF MOD(TRUNC(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')) - TO_DATE('19000101', 'YYYYMMDD'), 7) = 0 THEN   -- 2026.09.17 AJS
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 15:30:00', 'YYYYMMDD HH24:MI:SS');   -- 2026.09.17 AJS
        ELSE   -- 2026.09.17 AJS
            V_PLAN_CUTOFF_DATE_TIME := TO_DATE(P_PLAN_START_YYYYMMDD || ' 07:15:00', 'YYYYMMDD HH24:MI:SS');   -- 2026.09.17 AJS
        END IF;   -- 2026.09.17 AJS

        /* //4. WH_STOCK - SCS 재고 */
        INSERT INTO GT_SSP0015_PK_WH_STOCK
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.SCM_SITE_ID
             , 'WH_STOCK'
             , A.STOCK_DATE
             , SUM(NVL(A.STOCK_QTY, 0))
          FROM SCM_DNM_SCS_STOCK A
         WHERE 1 = 1
           AND A.DIVISION_ID = P_DIVISION_ID
--           AND A.CUTOFF_DATE = V_CUTOFF_DATE
           AND A.CUTOFF_DATE = V_CUTOFF_DATE   -- 2026.09.17 AJS
           AND A.LAST_UPDATE_DATE <= V_PLAN_CUTOFF_DATE_TIME   -- 2026.09.17 AJS
           AND A.CELL_PACK   = 'P'
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                 OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
         GROUP BY A.DIVISION_ID
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.STOCK_DATE;

        /* //ERP 재고 데이터 */
        INSERT INTO GT_SSP0015_PK_ERP_STOCK
               (DIVISION_ID, PLANT_ID, ITEM_ID, BOH_TYPE, YYYYMMDD, QTY)
        SELECT IA.DIVISION_ID
             , IA.PLANT_ID
             , IA.ITEM_ID
             , 'ERP'
             , IA.CUTOFF_DATE
             , SUM(IA.SCM_QTY)
          FROM (
                SELECT DISTINCT
                       A.DIVISION_ID
                     , A.COMPANY_ID
                     , A.ITEM_ID
                     , A.SCM_QTY
                     , TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD') AS CUTOFF_DATE
                     , A.PLANT_ID
                     , A.STOCK_TYPE
                  FROM SCM_DNM_STOCK_V A
                 WHERE 1 = 1
                   AND A.DIVISION_ID = '40'
                   AND A.COMPANY_ID  = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER_PAST', 'ESOC')   /* C100 */
--                   AND A.CUTOFF_DATE = TO_DATE(TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), 'YYYYMMDD')
                   AND A.CUTOFF_DATE = TO_DATE(V_CUTOFF_DATE, 'YYYYMMDD')   -- 2026.09.17 AJS
                   AND A.PLANT_ID    = FN_GET_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_PSI_PACKER_PAST', 'A010')   /* A010 */
                   AND A.STOCK_TYPE  = 'INVENTORY'
               ) IA
         WHERE IA.STOCK_TYPE = 'INVENTORY'
         GROUP BY IA.DIVISION_ID
             , IA.COMPANY_ID
             , IA.ITEM_ID
             , IA.CUTOFF_DATE
             , IA.PLANT_ID
             , IA.STOCK_TYPE;

        /* //TMP_ROWDATA - 과거 버전은 SSP_ANL_SHIP_PLAN_P 스냅샷을 그대로 읽는다 */
        INSERT INTO GT_SSP0015_PK_ROWDATA
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.MEASURE
             , A.YYYYMMDD
             , SUM(A.QTY)
          FROM SSP_ANL_SHIP_PLAN_P A
         WHERE A.DIVISION_ID         = P_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.YYYYMMDD >= P_FROM_YYYYMMDD
           AND A.YYYYMMDD <= P_TO_YYYYMMDD
--           AND A.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE')   /* PACK FP = PROD_PLAN */
           AND A.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE')   /* PACK FP = PROD_PLAN */   -- 2026.09.17 AJS
           AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')   -- 2026.09.17 AJS
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')   -- 2026.09.17 AJS
                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))   -- 2026.09.17 AJS
         GROUP BY A.DIVISION_ID
             , A.ITEM_ID
             , A.FROM_SITE
             , A.MEASURE
             , A.YYYYMMDD;

        /* //TMP_RESULT_TABLE */
        INSERT INTO GT_SSP0015_PK_RESULT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, QTY, SEQ)
        SELECT DISTINCT
               X.DIVISION_ID
             , X.ITEM_ID
             , X.FROM_SITE
             , X.MEASURE
             , X.YYYYMMDD
             , NVL(R.QTY, 0)
             , X.SEQ
          FROM (
                SELECT T.DIVISION_ID
                     , T.ITEM_ID
                     , NVL(T.FROM_SITE, '/')    AS FROM_SITE
                     , T.QTY
                     , TT1.COLUMN_NAME          AS MEASURE
                     , TT1.COLUMN_LABEL_NAME    AS MEASURE_NAME
                     , TT1.ATTRIBUTE3           AS BACK_COLOR
                     , TT1.SORT_ORDER_NO        AS SEQ
                     , T.YYYYMMDD
                  FROM GT_SSP0015_PK_ROWDATA T
                     , SCM_MST_SHEET_MEASURE TT1
                     , SCM_MST_TITLESET_USER T3
                 WHERE TT1.PROGRAM_ID = P_PROGRAM_ID
                   AND TT1.SHEET_NAME = P_SHEET_NAME
                   AND T3.PROGRAM_ID(+)  = TT1.PROGRAM_ID
                   AND T3.SHEET_NAME(+)  = TT1.SHEET_NAME
                   AND T3.COLUMN_NAME(+) = TT1.COLUMN_NAME
                   AND T3.USER_ID(+)     = P_USER_ID
               ) X
             , GT_SSP0015_PK_ROWDATA R
         WHERE R.DIVISION_ID(+) = X.DIVISION_ID
           AND R.ITEM_ID(+)     = X.ITEM_ID
           AND R.MEASURE(+)     = X.MEASURE
           AND R.YYYYMMDD(+)    = X.YYYYMMDD
           AND R.FROM_SITE(+)   = X.FROM_SITE
           AND X.MEASURE IN ('SHIP_REQ', 'SHIP_CONFIRM', 'PACK_RTF', 'PROD_PLAN', 'WH_STOCK', 'BALANCE');   /* PACK FP = PROD_PLAN */

        /* //PIVOT 대상 */
        INSERT INTO GT_SSP0015_PK_RESULT_PIVOT
               (DIVISION_ID, ITEM_ID, FROM_SITE, MEASURE, YYYYMMDD, YYYYMM, ISO_WEEK, QTY, SEQ)
        SELECT DISTINCT
               T0.DIVISION_ID
             , T0.ITEM_ID
             , T0.FROM_SITE
             , T0.MEASURE
             , 'D_' || T0.YYYYMMDD
             , T1.BASIS_YYYYMM
             , SUBSTR(T1.BASIS_YYYYMM, -4) || T1.ISO_WEEK
             , T0.QTY
             , T0.SEQ
          FROM GT_SSP0015_PK_RESULT T0
             , SCM_SYS_CALENDAR_M T1
         WHERE T0.YYYYMMDD = T1.BASIS_YYYYMMDD(+);

        /* PIVOT 대상 날짜문자열 생성 */
        DBMS_LOB.CREATETEMPORARY(V_MQRY_SUM, TRUE);

        FOR C IN (
            SELECT IA.YYYYMMDD
              FROM (
                    SELECT 'W_' || A.BASIS_YYYYMM || A.ISO_WEEK AS YYYYMMDD
                         , A.BASIS_START_DATE || '21'           AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.ISO_WEEK, A.BASIS_START_DATE
                    UNION ALL
                    SELECT 'M_' || A.BASIS_YYYYMM                AS YYYYMMDD
                         , MIN(A.BASIS_START_DATE) || '01'       AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMM, A.MONTH_NAME
                    UNION ALL
                    SELECT 'D_' || A.BASIS_YYYYMMDD              AS YYYYMMDD
                         , A.BASIS_YYYYMMDD || '31'              AS SORT_ORDER_NO
                      FROM SCM_SYS_CALENDAR_M A
                     WHERE A.BASIS_YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                     GROUP BY A.BASIS_YYYYMMDD
                   ) IA
             ORDER BY IA.SORT_ORDER_NO)
        LOOP
            IF SUBSTR(C.YYYYMMDD, 1, 2) = 'M_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMM = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSIF SUBSTR(C.YYYYMMDD, 1, 2) = 'W_' THEN
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.ISO_WEEK = SUBSTR(''' || C.YYYYMMDD || ''', -6) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            ELSE
                DBMS_LOB.APPEND(V_MQRY_SUM, ', CEIL(SUM(CASE WHEN T0.YYYYMMDD = SUBSTR(''' || C.YYYYMMDD || ''', -10) THEN NVL(T0.QTY, 0) ELSE 0 END)) AS ' || C.YYYYMMDD || CHR(10));
            END IF;
        END LOOP;

        V_MEXEC := 'SELECT DISTINCT TTT.* FROM ( ' || CHR(10)
                || '  SELECT T0.DIVISION_ID' || CHR(10)
                || '       , T0.ITEM_ID' || CHR(10)
                || '       , NVL(IT.NICK_NAME, ''-'')      AS NICK_NAME' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN ''SCS'' WHEN T0.MEASURE = ''BALANCE'' THEN ''ERP'' ELSE '' '' END) AS TYPE' || CHR(10)
                || '       , (CASE WHEN T0.MEASURE = ''WH_STOCK'' THEN NVL(T5.QTY, 0)' || CHR(10)
                || '               WHEN T0.MEASURE = ''BALANCE''  THEN NVL(T6.QTY, 0)' || CHR(10)
                || '          ELSE NULL END)               AS FIGURE' || CHR(10)
                || '       , NVL(T0.FROM_SITE, ''-'')      AS FROM_SITE' || CHR(10)
                || '       , NVL(T4.SITE_DESCRIPTION, ''/'') AS FROM_SITE_NM' || CHR(10)
                || '       , T0.MEASURE                    AS MEASURE' || CHR(10)
                || '       , T2.ATTRIBUTE1                 AS PSI_NAME' || CHR(10)
                || '       , T0.SEQ' || CHR(10)
                || '       , CASE WHEN NVL(T4.SHIP_FROZEN, 0) - 1 > 0 THEN T4.SHIP_FROZEN - 1 ELSE 0 END AS SHIP_FROZEN' || CHR(10)
                || V_MQRY_SUM
                || '    FROM GT_SSP0015_PK_RESULT_PIVOT T0' || CHR(10)
                || '       , SCM_MST_SHEET_MEASURE T2' || CHR(10)
                || '       , SCM_MST_TITLESET_USER T3' || CHR(10)
                || '       , SCM_MST_SITE T4' || CHR(10)
                || '       , GT_SSP0015_PK_WH_STOCK T5' || CHR(10)
                || '       , GT_SSP0015_PK_ERP_STOCK T6' || CHR(10)
                || '       , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME FROM SCM_MST_ITEM_SN' || CHR(10)
                || '           WHERE DIVISION_ID = ''' || P_DIVISION_ID || '''' || CHR(10)
                || '             AND ACTIVE_FLAG = ''Y''' || CHR(10)
                || '             AND SCP_OPERATION_GROUP = ''P'') IT' || CHR(10)
--                || '       , SSP_MST_MODEL_USER TT3' || CHR(10)
                || '   WHERE T0.MEASURE = T2.COLUMN_NAME' || CHR(10)
                || '     AND T2.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '     AND T2.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '     AND T3.PROGRAM_ID(+)  = T2.PROGRAM_ID' || CHR(10)
                || '     AND T3.SHEET_NAME(+)  = T2.SHEET_NAME' || CHR(10)
                || '     AND T3.COLUMN_NAME(+) = T2.COLUMN_NAME' || CHR(10)
                || '     AND T3.USER_ID(+)     = ''' || P_USER_ID || '''' || CHR(10)
                || '     AND T0.DIVISION_ID = T4.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T4.SCM_SITE_ID(+)' || CHR(10)
                || '     AND T4.VALID_YN(+) = ''Y''' || CHR(10)
                || '     AND T0.DIVISION_ID = T5.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.FROM_SITE   = T5.FROM_SITE(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T5.ITEM_ID(+)' || CHR(10)
                || '     AND T5.YYYYMMDD(+) = ''' || V_CUTOFF_DATE || '''' || CHR(10)
                || '     AND T5.MEASURE(+)  = ''WH_STOCK''' || CHR(10)
                || '     AND T0.DIVISION_ID = T6.DIVISION_ID(+)' || CHR(10)
                || '     AND T0.ITEM_ID     = T6.ITEM_ID(+)' || CHR(10)
                || '     AND T0.DIVISION_ID = IT.DIVISION_ID' || CHR(10)
                || '     AND T0.ITEM_ID     = IT.ITEM_ID' || CHR(10)
--                || '     AND TT3.DIVISION_ID(+) = T0.DIVISION_ID' || CHR(10)
--                || '     AND TT3.FROM_SITE(+)   = T0.FROM_SITE' || CHR(10)
--                || '     AND TT3.ITEM_ID(+)     = T0.ITEM_ID' || CHR(10)
--                || '     AND TT3.VALID_YN(+)    = ''Y''' || CHR(10)
--                || '     AND T2.VALID_YN = ''Y''' || CHR(10)
                || '     AND T2.VALID_YN = ''Y''' || CHR(10);   -- 2026.09.17 AJS
--                /* 체크박스 체크 여부 조회 */
--                || '     AND ((''' || P_NONCHK || ''' = ''Y'' AND 1 = 1)' || CHR(10)
--                || '           OR TT3.USER_ID IN (SELECT CASE WHEN ''' || P_MYMODELCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END FROM DUAL' || CHR(10)
--                || '                               UNION' || CHR(10)
--                || '                              SELECT CASE WHEN ''' || P_DELEGATEECHK || ''' = ''Y'' THEN USER_ID ELSE ''X'' END' || CHR(10)
--                || '                                FROM SSP_MST_DELEGATE WHERE VALID_YN = ''Y'' AND DELEGATEE_ID = ''' || P_USER_ID || ''' GROUP BY USER_ID)' || CHR(10)
--                || '           OR TT3.PART_LEADER = CASE WHEN ''' || P_PARTLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END' || CHR(10)
--                || '           OR TT3.TEAM_LEADER = CASE WHEN ''' || P_TEAMLEADERCHK || ''' = ''Y'' THEN ''' || P_USER_ID || ''' ELSE ''X'' END)' || CHR(10);

        IF P_FROM_SITE IS NOT NULL THEN
            V_MEXEC := V_MEXEC
                || '     AND T0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(''' || P_FROM_SITE || ''', '','')))' || CHR(10);
        END IF;

        V_MEXEC := V_MEXEC
                || '     AND (' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0' || CHR(10)
                || '           OR EXISTS (SELECT 1 FROM SCM_MST_TITLESET_USER SA' || CHR(10)
                || '                       WHERE SA.PROGRAM_ID = ''' || P_PROGRAM_ID || '''' || CHR(10)
                || '                         AND SA.SHEET_NAME = ''' || P_SHEET_NAME || '''' || CHR(10)
                || '                         AND SA.USER_ID    = ''' || P_USER_ID || '''' || CHR(10)
                || '                         AND SA.COLUMN_NAME = T2.COLUMN_NAME))' || CHR(10)
                || '     AND ((' || TO_CHAR(V_CNT_USR_MEASURE) || ' = 0 AND T2.DEFAULT_FLAG = ''Y'')' || CHR(10)
                || '           OR (' || TO_CHAR(V_CNT_USR_MEASURE) || ' != 0))' || CHR(10)
                || '   GROUP BY T0.DIVISION_ID, T0.ITEM_ID, IT.NICK_NAME, T0.FROM_SITE, T4.SITE_DESCRIPTION' || CHR(10)
                || '          , T0.MEASURE, T0.SEQ, T2.ATTRIBUTE1, T5.QTY, T6.QTY, T4.SHIP_FROZEN' || CHR(10)
                || ') TTT' || CHR(10)
                || ' ORDER BY TTT.DIVISION_ID, TTT.ITEM_ID, TTT.FROM_SITE DESC, TTT.SEQ ASC';

        OPEN O_RC1 FOR V_MEXEC;

        DBMS_LOB.FREETEMPORARY(V_MQRY_SUM);

    END P_SSP0015_GET_SHIPMENT_PSI_PACKER_PAST;


    /* ============================================================
       P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
       AS-IS SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
       ※ AS-IS 는 문자열을 조립해 EXEC 로 돌리지만 만드는 것은 선택조건뿐이다.
          날짜 칸을 만드는 피벗이 아니므로 정적 SQL 로 옮겼다.
       ※ P_REAL_FLAG 갈래에 따라 결과셋의 칸 구성이 다르다(AS-IS 동일).
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_REQUESTOR             IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_SEARCH_YN             IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2 DEFAULT 'N',
        P_REAL_FLAG             IN  VARCHAR2 DEFAULT 'N',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'T',
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2019/03/11   AYJ 			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/05/09   AYJ 			MyModel 체크여부에 따른 조회조건 분기처리
         * 2019/05/20	AYJ				[CSR ID:3994743] REQUESTOR 컬럼 추가
         * 2019/06/17	AYJ			    조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			    조회 조건 추가(p_delegateeChk)
         * 2019/12/17	KIMYONGHO		[C20191216-000311] Expected Shipping Date 컬럼 추가
         * 2020/09/21   KIMYONHHO      SSP INCOTERMS 변경 작업
         * 2021/02/04   KIMYONGHO	    ETA_DATE 조회 시 항차를 고려한 LT 적용되도록 함수 적용 FN_GET_SSP_ETA_DATE
         * 2021/10/05   SHINMYUNGSU	    SSP_ANL_SHIP_CONFIRM 의 Attribute3,6 항목 추가
         * 2021/10/12   KIMYONGHO	    [C20211001-000241] Confirm 복사하여 신규 생성 기능 추가
         * 2023/09/21   jilee          G182-P (Group='P',OSP='N')조회 추가
         * 2024/09/03   SSP            Team 컬럼 추가
         * 2024/10/01   KHJ            NERP_SSP
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         */
    BEGIN

        IF P_REAL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ERP_SO_NO
                         , A.SHIPMENT_STATUS
                         , A.PROJECT_CODE
                         , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME
                         , A.FCST_TYPE
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , A.BEFORE_QTY                      AS BEFORE_QTY
                         , TRUNC(A.QTY)                      AS SHIPMENT_CONFIRM_QTY
                         , A.REMARKS
                         , A.REMARKS2
                         , A.REMARKS3
                         , A.FROM_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                         , A.TO_SITE
                         , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                         , A.TO_SITE_SOLDTO_CODE
                         , A.TO_SITE_SHIPTO_CODE
                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                         , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                         , A.BOD_ID
                         , B.SSP_INCOTERMS                   AS INCOTERMS
                         , B.TRANSPORT_MODE
                         , B.LT_TOTAL                        AS LT_DAY
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                         , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                                ELSE (SELECT CASE WHEN REGEXP_LIKE(SA.V, '^[0-9]{8}$')
                                                  THEN TO_CHAR(TO_DATE(SA.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                        FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD) AS V FROM DUAL) SA)
                           END                               AS EXPECTED_SHIPPING_DATE
                         , A.CONFIRM_ID
/* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
/* 2026.09.30 AJS 수정 (END) */
                           END                               AS UPDATED_BY
/* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN U.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                         , CASE WHEN U.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
/* 2026.09.30 AJS 수정 (END) */
                         , A.ERP_STATUS
                         , A.CHANGE_TYPE
                           /* AS-IS 는 UNION 반대편이 '-' 라 문자로 쓰인다. Oracle 은 NUMBER 라 문자로 맞춘다. */
                         , TO_CHAR(A.ROUTE_ID)               AS NEW_ROUTE_ID
                         , A.BOD_ID                          AS NEW_BOD_ID
                         , B.SSP_INCOTERMS                   AS NEW_INCOTERMS
                         , A.D_COUNTRY                       AS NEW_D_COUNTRY
                         , A.D_PORT_CODE                     AS NEW_D_PORT_CODE
                         , A.A_COUNTRY                       AS NEW_A_COUNTRY
                         , A.A_PORT_CODE                     AS NEW_A_PORT_CODE
                         , TO_CHAR(A.CUSTOMER_LT)            AS NEW_CUSTOMER_LT
                         , A.TO_COUNTRY                      AS NEW_TO_COUNTRY
                         , A.TO_CITY                         AS NEW_TO_CITY
                         , CASE WHEN REGEXP_LIKE(A.ETA_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETA
                         , CASE WHEN REGEXP_LIKE(A.ETD_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_ETD
                         , TO_CHAR(B.LT_TOTAL)               AS NEW_LT_DAY
                         , B.TRANSPORT_MODE                  AS NEW_TRANSPORT_MODE
                         , CASE WHEN REGEXP_LIKE(A.YYYYMMDD, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS NEW_SHIPMENT_DATE
                         , 'N'                               AS EDIT_REMARKS
                         , 'N'                               AS EDIT_MAIN
                         , NVL(A.CHECK_NEED_YN, 'N')         AS CHECK_NEED_YN
                         , NVL(CASE WHEN A.DIVISION_ID = '40'
                                    THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE != '-'
                                              THEN A.PROJECT_CODE ELSE G.PROJECT_CODE END
                                    WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                    THEN G.PROJECT_CODE
                                    ELSE F.END_CUSTOMER END, '/') AS END_CUSTOMER
                         , A.ELECTRODE_YN
                         , A.ELECTRODE_TYPE
                         , A.ORIGIN_FROM_DIVISION_ID
                         , A.ORIGIN_TO_DIVISION_ID
                         , H.CHANGE_REQ_NO
/* 2026.09.30 AJS 수정 (START) */
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
/* 2026.09.30 AJS 수정 (END) */
                           END                               AS MODEL_USER
                         , FN_GET_SSP_MKT_OWNER_NAME(SI.OWNER, ',', P_LANGUAGE) AS MTK_OWNER
--                         , (SELECT NVL(MIN(SA.DEPT_NAME_KO), '-')
                         , (SELECT CASE WHEN COUNT(*) = 0 THEN NULL ELSE NVL(MIN(SA.DEPT_NAME_KO), '-') END   -- 2026.09.17 AJS
                              FROM SCM_MST_SSO_DEPT_INFO SA
/* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER SB
                                 , SCM_ADM_USER_M SB
/* 2026.09.30 AJS 수정 (END) */
                             WHERE SA.DEPT_ID = SB.DEPT_ID(+)
--                               AND SB.USERID  = SI.OWNER)    AS TEAM
/* 2026.09.30 AJS 수정 (START) */
--                               AND UPPER(SB.USERID) = UPPER(SI.OWNER)) AS TEAM   -- 2026.09.17 AJS
--                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) IS NULL THEN NULL
--                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USERNAME ELSE U3.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                               AND UPPER(SB.USER_ID) = UPPER(SI.OWNER)) AS TEAM  -- 2026.09.17 AJS
                         , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) IS NULL THEN NULL
                                ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
/* 2026.09.30 AJS 수정 (END) */
                           END                               AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , ''                                AS CHANGE_REASON_DETAIL
                           /* [C20211001-000241] Confirm 복사하여 신규 생성 기능 추가 */
                         , NVL(A.ATTRIBUTE10, '-')           AS ATTRIBUTE10
                           /* 2021/10/05 SHINMYUNGSU 열람 항목추가 */
                         , NVL(A.ATTRIBUTE3, '-')            AS ATTRIBUTE3
                         , NVL(A.ATTRIBUTE6, '-')            AS ATTRIBUTE6
                      FROM SSP_ANL_SHIP_CONFIRM A
                         , SCM_MST_SITE MS
                         , SCP_MST_BOD_N_V B
/* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U
                         , SCM_ADM_USER_M U
/* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE F
                         , (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                              FROM (SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                                         , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY PROJECT_CODE) AS NUM
                                      FROM SCM_MST_SITE_ITEM)
                             WHERE NUM = 1) G
                         , (SELECT CONFIRM_ID, CHANGE_REQ_NO
                              FROM (SELECT CONFIRM_ID, CHANGE_REQ_NO
                                         , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC) AS NUM
                                      FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                     WHERE VALID_YN = 'Y')
                             WHERE NUM = 1) H
                         , SSP_MST_MODEL_USER MU
/* 2026.09.30 AJS 수정 (START) */
--                         , TB_FX_USER U2
--                         , TB_FX_USER U3
                         , SCM_ADM_USER_M U2
                         , SCM_ADM_USER_M U3
/* 2026.09.30 AJS 수정 (END) */
                         , SCM_MST_SITE_ITEM SI
                         , SSP_ANL_SHIP_CONFIRM_CHG_REQ T1
                     WHERE A.DIVISION_ID = MS.DIVISION_ID
                       AND A.FROM_SITE   = MS.SCM_SITE_ID
                       AND MS.SITE_TYPE  = 'PLANT'
                       AND A.DIVISION_ID = '40'
                       AND (MS.OPERATION_GROUP = 'A' OR MS.OSP_YN = 'N')
                       AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END = B.DIVISION_ID
                       AND A.BOD_ID      = B.BOD_ID
--                       AND A.LAST_UPDATED_BY = U.USERID(+)
/* 2026.09.30 AJS 수정 (START) */
--                       AND UPPER(A.LAST_UPDATED_BY) = UPPER(U.USERID(+))   -- 2026.09.17 AJS
--                       AND U.USEYN(+)        = 'Y'
                       AND UPPER(A.LAST_UPDATED_BY) = UPPER(U.USER_ID(+))  -- 2026.09.17 AJS
                       AND U.USE_YN(+)       = 'Y'
/* 2026.09.30 AJS 수정 (END) */
                       AND F.DIVISION_ID(+)  = A.ORIGIN_TO_DIVISION_ID
                       AND F.SCM_SITE_ID(+)  = A.TO_SITE
                       AND F.VALID_YN(+)     = 'Y'
                       AND G.DIVISION_ID(+)  = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND G.SCM_SITE_ID(+)  = A.TO_SITE
                       AND G.ITEM_ID(+)      = A.ITEM_ID
                       AND H.CONFIRM_ID(+)   = A.CONFIRM_ID
                       AND MU.DIVISION_ID(+) = A.ORIGIN_FROM_DIVISION_ID
                       AND MU.FROM_SITE(+)   = A.FROM_SITE
                       AND MU.ITEM_ID(+)     = A.ITEM_ID
                       AND MU.VALID_YN(+)    = 'Y'
--                       AND MU.USER_ID        = U2.USERID(+)
/* 2026.09.30 AJS 수정 (START) */
--                       AND UPPER(MU.USER_ID)  = UPPER(U2.USERID(+))   -- 2026.09.17 AJS
--                       AND U2.USEYN(+)       = 'Y'
                       AND UPPER(MU.USER_ID)  = UPPER(U2.USER_ID(+))  -- 2026.09.17 AJS
                       AND U2.USE_YN(+)      = 'Y'
/* 2026.09.30 AJS 수정 (END) */
--                       AND A.REQUESTOR       = U3.USERID(+)
/* 2026.09.30 AJS 수정 (START) */
--                       AND UPPER(A.REQUESTOR) = UPPER(U3.USERID(+))   -- 2026.09.17 AJS
--                       AND U3.USEYN(+)       = 'Y'
                       AND UPPER(A.REQUESTOR) = UPPER(U3.USER_ID(+))  -- 2026.09.17 AJS
                       AND U3.USE_YN(+)      = 'Y'
/* 2026.09.30 AJS 수정 (END) */
                       AND SI.DIVISION_ID(+)  = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END
                       AND SI.SCM_SITE_ID(+)  = A.TO_SITE
                       AND SI.ITEM_ID(+)      = A.ITEM_ID
                       AND SI.PROJECT_CODE(+) = A.PROJECT_CODE
                       AND H.CHANGE_REQ_NO    = T1.CHANGE_REQ_NO(+)
                       /* Search 버튼으로 조회(체크박스 체크 여부에 따라 조회) */
--                       AND (P_SEARCH_YN != 'Y'
                       AND (NVL(P_SEARCH_YN, 'N') != 'Y'   -- 2026.09.17 AJS
                             OR ((P_NONCHK = 'Y' AND 1 = 1)
--                                  OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                  OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                     UNION
                                                    SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                      FROM SSP_MST_DELEGATE
                                                     WHERE VALID_YN = 'Y'
--                                                       AND DELEGATEE_ID = P_USER_ID
                                                       AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                     GROUP BY USER_ID)
--                                  OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                  OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                                  OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                                  OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END))   -- 2026.09.17 AJS
                       AND A.YYYYMMDD >= P_FROM_YYYYMMDD
                       AND A.YYYYMMDD <= P_TO_YYYYMMDD
                       AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                             OR A.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                             OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                             OR UPPER(A.ITEM_ID) IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
--                             OR A.REQUESTOR IN (SELECT DISTINCT SA.USERID
/* 2026.09.30 AJS 수정 (START) */
--                             OR UPPER(A.REQUESTOR) IN (SELECT DISTINCT UPPER(SA.USERID)   -- 2026.09.17 AJS
--                                                  FROM TB_FX_USER SA
                             OR UPPER(A.REQUESTOR) IN (SELECT DISTINCT UPPER(SA.USER_ID)  -- 2026.09.17 AJS
                                                  FROM SCM_ADM_USER_M SA
/* 2026.09.30 AJS 수정 (END) */
--                                                 WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
/* 2026.09.30 AJS 수정 (START) */
--                                                 WHERE UPPER(SA.USERNAME) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))   -- 2026.09.17 AJS
                                                 WHERE UPPER(SA.USER_NM) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))    -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
--                                                    OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
/* 2026.09.30 AJS 수정 (START) */
--                                                    OR UPPER(SA.USERID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))   -- 2026.09.17 AJS
                                                    OR UPPER(SA.USER_ID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))  -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
                       AND A.SHIPMENT_STATUS IS NOT NULL
                       AND A.QTY > 0
                       AND A.CHANGE_TYPE <> 'N'
                       AND A.BIZ_TYPE    <> 'E'
                    UNION ALL
                    SELECT T.DIVISION_ID
                         , T.ERP_SO_NO
                         , T.SHIPMENT_STATUS
                         , T.PROJECT_CODE
                         , T.PROJECT_NAME
                         , T.FCST_TYPE
                         , T.ITEM_ID
                         , T.NICK_NAME
                         , CASE WHEN REGEXP_LIKE(T.SHIPMENT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(T.SHIPMENT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                         , 0                                 AS BEFORE_QTY
                         , T.QTY                             AS SHIPMENT_CONFIRM_QTY
                         , T.REMARKS
                         , T.REMARKS2
                         , T.REMARKS3
                         , T.FROM_SITE
                         , T.FROM_SITE_DESCRIPTION
                         , T.TO_SITE
                         , T.TO_SITE_DESCRIPTION
                         , T.TO_SITE_SOLDTO_CODE
                         , T.TO_SITE_SHIPTO_CODE
                         , T.SOLDTO_DESCRIPTION
                         , T.SHIPTO_DESCRIPTION
                         , T.BOD_ID
                         , T.INCOTERMS
                         , T.TRANSPORT_MODE
                         , T.LT_TOTAL                        AS LT_DAY
                         , T.ETD
                         , T.ETA
                         , T.EXPECTED_SHIPPING_DATE
                         , T.CONFIRM_ID
                         , T.LAST_UPDATED_BY                 AS UPDATED_BY
                         , T.LAST_UPDATE_DATE                AS UPDATED_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
--                         , '-'                               AS NEW_ROUTE_ID
                         , '0'                               AS NEW_ROUTE_ID   -- 2026.09.17 AJS
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
--                         , '-'                               AS NEW_CUSTOMER_LT
                         , '0'                               AS NEW_CUSTOMER_LT   -- 2026.09.17 AJS
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
--                         , '-'                               AS NEW_LT_DAY
                         , '0'                               AS NEW_LT_DAY   -- 2026.09.17 AJS
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , '-'                               AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , '-'                               AS CHANGE_REQ_NO
                         , '-'                               AS MODEL_USER
                         , TO_CLOB('-')                      AS MTK_OWNER
                         , '-'                               AS TEAM
                         , '-'                               AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                         , '-'                               AS ATTRIBUTE10
                         , '-'                               AS ATTRIBUTE3
                         , '-'                               AS ATTRIBUTE6
                      FROM (
                            SELECT TT0.DIVISION_ID
                                 , NULL                       AS ERP_SO_NO
                                 , 'P'                        AS SHIPMENT_STATUS
                                 , TT0.ITEM_ID
                                 , FN_GET_ITEM_NICKNAME(TT0.DIVISION_ID, TT0.ITEM_ID) AS NICK_NAME
                                 , TT0.DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID
                                 , TT0.DIVISION_ID            AS ORIGIN_TO_DIVISION_ID
                                 , TT0.PLANT_SITE_ID          AS FROM_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT0.PLANT_SITE_ID), '-') AS FROM_SITE_DESCRIPTION
                                 , TT0.SCM_SITE_ID            AS TO_SITE
                                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(TT0.DIVISION_ID, TT0.SCM_SITE_ID), '-')   AS TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , FN_GET_PROJECT_NAME(TT0.DIVISION_ID, TT0.PROJECT_CODE) AS PROJECT_NAME
                                 , '-'                        AS REQUESTOR
                                 , TT0.QTY
                                 , TT0.YYYYMMDD               AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT0.INCOTERMS
                                 , TT0.TRANSPORT_MODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SOLDTO_CODE')        AS TO_SITE_SOLDTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SHIPTO_CODE')        AS TO_SITE_SHIPTO_CODE
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                                 , FN_GET_SITE_CUSTOMER_INFO(TT0.DIVISION_ID, TT0.SCM_SITE_ID, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                                 , '-'                        AS REMARKS2
                                 , '-'                        AS REMARKS
                                 , '-'                        AS CHANGE_REQ_NO
                                 , '-'                        AS REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , (SELECT CASE WHEN REGEXP_LIKE(SA.V, '^[0-9]{8}$')
                                                THEN TO_CHAR(TO_DATE(SA.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                      FROM (SELECT FN_GET_SSP_ETA_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SA) AS ETA
                                 , CASE WHEN TT0.TRANSPORT_MODE = 'TRK' THEN '-'
                                        ELSE (SELECT CASE WHEN REGEXP_LIKE(SB.V, '^[0-9]{8}$')
                                                          THEN TO_CHAR(TO_DATE(SB.V, 'YYYYMMDD'), 'YYYY-MM-DD') END
                                                FROM (SELECT FN_GET_SSP_EXPECTED_SHIP_DATE(TT0.DIVISION_ID, TT0.BOD_ID, TT0.YYYYMMDD) AS V FROM DUAL) SB)
                                   END                        AS EXPECTED_SHIPPING_DATE
                                 , TT1.LT_TOTAL
                                 , TT0.LAST_UPDATED_BY
                                 , TT0.LAST_UPDATE_DATE
                                 , '-'                        AS CONFIRM_ID
                                 , TT0.FCST_TYPE
                                 , CASE WHEN NVL(TT2.SHIP_FROZEN, 0) > 0
                                        THEN TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + NVL(TT2.SHIP_FROZEN, 0), 'YYYYMMDD')
                                        ELSE P_PLAN_START_YYYYMMDD END AS FROZEN_YYYYMMDD
                              FROM DM_PLN_SHIPMENT_REQ TT0
                                 , SCP_MST_BOD_N_V TT1
                                 , SCM_MST_SITE TT2
                                 , SSP_MST_MODEL_USER MU
/* 2026.09.30 AJS 수정 (START) */
--                                 , TB_FX_USER U2
                                 , SCM_ADM_USER_M U2
/* 2026.09.30 AJS 수정 (END) */
                             WHERE TT0.DIVISION_ID = TT1.DIVISION_ID
                               AND TT0.BOD_ID      = TT1.BOD_ID
                               AND TT0.DIVISION_ID = TT2.DIVISION_ID
                               AND TT0.PLANT_SITE_ID = TT2.SCM_SITE_ID
                               AND TT2.SITE_TYPE   = 'PLANT'
                               AND TT2.VALID_YN    = 'Y'
                               AND MU.DIVISION_ID(+) = TT0.DIVISION_ID
                               AND MU.FROM_SITE(+)   = TT0.PLANT_SITE_ID
                               AND MU.ITEM_ID(+)     = TT0.ITEM_ID
                               AND MU.VALID_YN(+)    = 'Y'
--                               AND MU.USER_ID        = U2.USERID(+)
/* 2026.09.30 AJS 수정 (START) */
--                               AND UPPER(MU.USER_ID) = UPPER(U2.USERID(+))   -- 2026.09.17 AJS
--                               AND U2.USEYN(+)       = 'Y'
                               AND UPPER(MU.USER_ID) = UPPER(U2.USER_ID(+))  -- 2026.09.17 AJS
                               AND U2.USE_YN(+)      = 'Y'
/* 2026.09.30 AJS 수정 (END) */
                               AND TT0.DIVISION_ID   = P_DIVISION_ID
--                               AND (P_SEARCH_YN != 'Y'
                               AND (NVL(P_SEARCH_YN, 'N') != 'Y'   -- 2026.09.17 AJS
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
--                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                             UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN = 'Y'
--                                                               AND DELEGATEE_ID = P_USER_ID
                                                               AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                             GROUP BY USER_ID)
--                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END))   -- 2026.09.17 AJS
                           ) T
                     WHERE 1 = 1
                       AND T.SHIPMENT_DATE >= T.FROZEN_YYYYMMDD
                       AND T.SHIPMENT_DATE >= P_FROM_YYYYMMDD
                       AND T.SHIPMENT_DATE <= P_TO_YYYYMMDD
                       AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                             OR T.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                             OR UPPER(T.ITEM_ID) IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                       AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                             OR T.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
--                             OR T.LAST_UPDATED_BY IN (SELECT DISTINCT SA.USERID
/* 2026.09.30 AJS 수정 (START) */
--                             OR UPPER(T.LAST_UPDATED_BY) IN (SELECT DISTINCT UPPER(SA.USERID)   -- 2026.09.17 AJS
--                                                        FROM TB_FX_USER SA
                             OR UPPER(T.LAST_UPDATED_BY) IN (SELECT DISTINCT UPPER(SA.USER_ID)  -- 2026.09.17 AJS
                                                        FROM SCM_ADM_USER_M SA
/* 2026.09.30 AJS 수정 (END) */
--                                                       WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
/* 2026.09.30 AJS 수정 (START) */
--                                                       WHERE UPPER(SA.USERNAME) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))   -- 2026.09.17 AJS
                                                       WHERE UPPER(SA.USER_NM) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))    -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
--                                                          OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
/* 2026.09.30 AJS 수정 (START) */
--                                                          OR UPPER(SA.USERID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))   -- 2026.09.17 AJS
                                                          OR UPPER(SA.USER_ID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))  -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
                   ) AA
--             ORDER BY AA.DIVISION_ID
             ORDER BY AA.DIVISION_ID NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.SHIPMENT_STATUS
                 , AA.SHIPMENT_STATUS NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.SHIPMENT_DATE
                 , AA.SHIPMENT_DATE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.ITEM_ID
                 , AA.ITEM_ID NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.ERP_SO_NO DESC
                 , AA.ERP_SO_NO DESC NULLS LAST   -- 2026.09.17 AJS
--                 , AA.FROM_SITE
                 , AA.FROM_SITE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.TO_SITE
                 , AA.TO_SITE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.PROJECT_CODE
                 , AA.PROJECT_CODE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.FCST_TYPE;
                 , AA.FCST_TYPE NULLS FIRST;   -- 2026.09.17 AJS

        ELSE

            OPEN O_RC1 FOR
            SELECT AA.*
              FROM (
                    SELECT T0.DIVISION_ID
                         , T0.ERP_SO_NO
                         , T0.SHIPMENT_STATUS
                         , T0.PROJECT_CODE
                         , T0.PROJECT_NAME
                         , T0.FCST_TYPE
                         , T0.ITEM_ID
                         , T0.NICK_NAME
                         , T0.SHIPMENT_DATE
                         , T0.SHIPMENT_CONFIRM_QTY
                         , T0.REMARKS
                         , T0.REMARKS2
                         , T0.REMARKS3
                         , T0.FROM_SITE
                         , T0.FROM_SITE_DESCRIPTION
                         , T0.TO_SITE
                         , T0.TO_SITE_DESCRIPTION
                         , T0.TO_SITE_SOLDTO_CODE
                         , T0.TO_SITE_SHIPTO_CODE
                         , T0.SOLDTO_DESCRIPTION
                         , T0.SHIPTO_DESCRIPTION
                         , T0.BOD_ID
                         , T0.INCOTERMS
                         , T0.TRANSPORT_MODE
                         , T0.LT_DAY
                         , T0.ETD
                         , T0.ETA
                         , T0.EXPECTED_SHIPPING_DATE
                         , T0.CONFIRM_ID
                         , T0.UPDATED_BY
                         , T0.UPDATED_DATE
                         , '-'                               AS ERP_STATUS
                         , '-'                               AS CHANGE_TYPE
                         , '-'                               AS NEW_ROUTE_ID
                         , '-'                               AS NEW_BOD_ID
                         , '-'                               AS NEW_INCOTERMS
                         , '-'                               AS NEW_D_COUNTRY
                         , '-'                               AS NEW_D_PORT_CODE
                         , '-'                               AS NEW_A_COUNTRY
                         , '-'                               AS NEW_A_PORT_CODE
                         , '-'                               AS NEW_CUSTOMER_LT
                         , '-'                               AS NEW_TO_COUNTRY
                         , '-'                               AS NEW_TO_CITY
                         , '-'                               AS NEW_ETA
                         , '-'                               AS NEW_ETD
                         , '-'                               AS NEW_LT_DAY
                         , '-'                               AS NEW_TRANSPORT_MODE
                         , '-'                               AS NEW_SHIPMENT_DATE
                         , '-'                               AS EDIT_REMARKS
                         , '-'                               AS EDIT_MAIN
                         , '-'                               AS CHECK_NEED_YN
                         , T0.END_CUSTOMER                   AS END_CUSTOMER
                         , '-'                               AS ELECTRODE_YN
                         , '-'                               AS ELECTRODE_TYPE
                         , '-'                               AS ORIGIN_FROM_DIVISION_ID
                         , '-'                               AS ORIGIN_TO_DIVISION_ID
                         , T0.CHANGE_REQ_NO                  AS CHANGE_REQ_NO
                         , T0.MODEL_USER                     AS MODEL_USER
                         , T0.MTK_OWNER                      AS MTK_OWNER
                         , T0.REQUESTOR                      AS REQUESTOR
                         , '-'                               AS CHANGE_REASON_CODE
                         , '-'                               AS CHANGE_REASON_DETAIL
                         , '-'                               AS ATTRIBUTE10
                         , T0.ATTRIBUTE3
                         , T0.ATTRIBUTE6
                      FROM (
                            SELECT TT0.DIVISION_ID
                                 , TT0.ERP_SO_NO
                                 , TT0.SHIPMENT_STATUS
                                 , TT0.ITEM_ID
                                 , TT0.NICK_NAME
                                 , TT0.ORIGIN_FROM_DIVISION_ID
                                 , TT0.ORIGIN_TO_DIVISION_ID
                                 , TT0.FROM_SITE
                                 , TT0.FROM_SITE_DESCRIPTION
                                 , TT0.TO_SITE
                                 , TT0.TO_SITE_DESCRIPTION
                                 , TT0.PROJECT_CODE
                                 , TT0.PROJECT_NAME
                                 , TT0.REQUESTOR
                                 , TT0.SHIPMENT_CONFIRM_QTY
                                 , CASE WHEN REGEXP_LIKE(TT0.YYYYMMDD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS SHIPMENT_DATE
                                 , TT0.BOD_ID
                                 , TT0.INCOTERMS
                                 , TT0.TRANSPORT_MODE
                                 , TT0.TO_SITE_SOLDTO_CODE
                                 , TT0.TO_SITE_SHIPTO_CODE
                                 , TT0.SOLDTO_DESCRIPTION
                                 , TT0.SHIPTO_DESCRIPTION
                                 , TT0.REMARKS2
                                 , TT0.REMARKS
                                 , TT0.CHANGE_REQ_NO
                                 , TT0.REMARKS3
                                 , CASE WHEN REGEXP_LIKE(TT0.ETD, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD
                                 , CASE WHEN REGEXP_LIKE(TT0.ETA, '^[0-9]{8}$')
                                        THEN TO_CHAR(TO_DATE(TT0.ETA, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA
                                 , TT0.EXPECTED_SHIPPING_DATE
                                 , TT0.LT_DAY                AS LT_DAY
                                 , TT0.UPDATED_BY            AS UPDATED_BY
                                 , TT0.UPDATED_DATE          AS UPDATED_DATE
                                 , TT0.CONFIRM_ID            AS CONFIRM_ID
                                 , TT0.FCST_TYPE
                                 , TT0.END_CUSTOMER
                                 , TT0.MTK_OWNER
                                 , TT0.MODEL_USER
                                   /* 2021/10/05 SHINMYUNGSU 열람 항목추가 */
                                 , '-'                       AS ATTRIBUTE3
                                 , '-'                       AS ATTRIBUTE6
                              FROM SSP_ANL_SHIP_PLAN_ALL TT0
                                 , SSP_MST_MODEL_USER MU
                             WHERE MU.DIVISION_ID(+) = TT0.ORIGIN_FROM_DIVISION_ID
                               AND MU.FROM_SITE(+)   = TT0.FROM_SITE
                               AND MU.ITEM_ID(+)     = TT0.ITEM_ID
                               AND MU.VALID_YN(+)    = 'Y'
                               AND TT0.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                               AND TT0.DIVISION_ID         = P_DIVISION_ID
                               AND TT0.SHIPMENT_CONFIRM_QTY > 0
                               AND TT0.OPERATION_GROUP     <> 'E'
                               AND TT0.YYYYMMDD >= P_FROM_YYYYMMDD
                               AND TT0.YYYYMMDD <= P_TO_YYYYMMDD
                               AND ((P_DIVISION_ID IS NULL OR P_DIVISION_ID = '')
                                     OR TT0.DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, ','))))
                               AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
--                                     OR TT0.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                                     OR UPPER(TT0.ITEM_ID) IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                               AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                                     OR TT0.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                               AND ((P_REQUESTOR IS NULL OR P_REQUESTOR = '')
--                                     OR TT0.REQUESTOR IN (SELECT DISTINCT SA.USERID
/* 2026.09.30 AJS 수정 (START) */
--                                     OR UPPER(TT0.REQUESTOR) IN (SELECT DISTINCT UPPER(SA.USERID)   -- 2026.09.17 AJS
--                                                            FROM TB_FX_USER SA
                                     OR UPPER(TT0.REQUESTOR) IN (SELECT DISTINCT UPPER(SA.USER_ID)  -- 2026.09.17 AJS
                                                            FROM SCM_ADM_USER_M SA
/* 2026.09.30 AJS 수정 (END) */
--                                                           WHERE SA.USERNAME IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))
/* 2026.09.30 AJS 수정 (START) */
--                                                           WHERE UPPER(SA.USERNAME) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))   -- 2026.09.17 AJS
                                                           WHERE UPPER(SA.USER_NM) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))    -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
--                                                              OR SA.USERID   IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))
/* 2026.09.30 AJS 수정 (START) */
--                                                              OR UPPER(SA.USERID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))   -- 2026.09.17 AJS
                                                              OR UPPER(SA.USER_ID) IN (SELECT UPPER(REGEXP_REPLACE(TOKEN, '^N?''(.*)''$', '')) FROM TABLE(FN_STRING_SPLIT(P_REQUESTOR, ',')))))  -- 2026.09.17 AJS
/* 2026.09.30 AJS 수정 (END) */
--                               AND (P_SEARCH_YN != 'Y'
                               AND (NVL(P_SEARCH_YN, 'N') != 'Y'   -- 2026.09.17 AJS
                                     OR ((P_NONCHK = 'Y' AND 1 = 1)
--                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                          OR MU.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END FROM DUAL   -- 2026.09.17 AJS
                                                             UNION
                                                            SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                              FROM SSP_MST_DELEGATE
                                                             WHERE VALID_YN = 'Y'
--                                                               AND DELEGATEE_ID = P_USER_ID
                                                               AND DELEGATEE_ID = LOWER(P_USER_ID)   -- 2026.09.17 AJS
                                                             GROUP BY USER_ID)
--                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                          OR MU.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END   -- 2026.09.17 AJS
--                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END))
                                          OR MU.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN LOWER(P_USER_ID) ELSE 'X' END))   -- 2026.09.17 AJS
                           ) T0
                   ) AA
--             ORDER BY AA.DIVISION_ID
             ORDER BY AA.DIVISION_ID NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.SHIPMENT_STATUS
                 , AA.SHIPMENT_STATUS NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.SHIPMENT_DATE
                 , AA.SHIPMENT_DATE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.ITEM_ID
                 , AA.ITEM_ID NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.ERP_SO_NO DESC
                 , AA.ERP_SO_NO DESC NULLS LAST   -- 2026.09.17 AJS
--                 , AA.FROM_SITE
                 , AA.FROM_SITE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.TO_SITE
                 , AA.TO_SITE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.PROJECT_CODE
                 , AA.PROJECT_CODE NULLS FIRST   -- 2026.09.17 AJS
--                 , AA.FCST_TYPE;
                 , AA.FCST_TYPE NULLS FIRST;   -- 2026.09.17 AJS

        END IF;

    END P_SSP0015_GET_SHIPMENT_CONFIRM_DETAIL;

END PKG_ZTMP_S015J;
/
SHOW ERRORS PACKAGE BODY PKG_ZTMP_S015J
-- ##### END PACKAGE BODY PKG_ZTMP_S015J

-- ##### START PACKAGE BODY PKG_ZTMP_S015K
CREATE OR REPLACE PACKAGE BODY PKG_ZTMP_S015K
IS
    /* ============================================================
       P_SSP0015_GET_SHIPMENT_RESULT
       AS-IS SSP0015_GET_SHIPMENT_RESULT
       ※ AS-IS WITH 절 5벌은 각각 1회만 참조하므로 인라인 뷰로 펼쳤다(온라인 SQL WITH 금지).
       ※ STUFF(... FOR XML PATH('')) 는 LISTAGG 로 옮겼다. AS-IS 는 정렬이 없으나
          LISTAGG 는 WITHIN GROUP 이 필수라 DEPT_NAME_KO 로 정렬한다.
       ※ AS-IS 의 CASE WHEN DIVISION_ID = '4O' 는 알파벳 O 다(숫자 0 아님).
          결과 동일성을 위해 원형을 그대로 둔다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_RESULT
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_TYPE                  IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_REAL_FLAG             IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_RESULT
         * Description  : Shipment Shipment Result
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/09/26   AYJ			[CSR ID:4037234] 출하계획 대비 실적 Report 개발
         * 2019/12/04   juhlee      [C20191205-000132]  OWMS 출하실적에 반품 내용 적용
         * 2020/01/21   juhlee      [C20200121-000352]  ESS Packer출하 적용
         * 2020/02/12   KIMYONGHO   [C20200218-000135]  SHIP_TYPE 컬럼추가 및 FROM_STIE, TO_SITE Display 변경
         * 2020.05.06	KIMYONGHO   [C20200403-000062] [GSCM PI] SSP 출하 실적 집계 중 사외 창고 제외 로직 추가 건
         * 2020.09.18	KIMYONGHO   ERP_ORDER_TYPE 주석 처리 Request by 김광희 책임
         * 2021.02.17	KIMYONGHO   실적 조회시 TRNSPORT_MODE, INCOTERMS, ERP_SO_NO, ETA_DATE, ETD_DATE ERP 실적 기준으로 조회
         * 2021.04.05   KIMYONGHO   [C20210330-000402] Shipment Plan화면의 실적 조회시 Sales site Mapping 안되는건 전수 표시
         * 2021.05.03   SSP Pjt.    SSP_SHIP_RESULT_EXCEPT_ERP_ORDER_TYPE LOOKUP적용
         * 2021.11.15   KIMYONGHO   Confirm Data Plan Date 기준 조회 처리
         * 2024.10.18   SSP         소형 Team 컬럼 추가
         * 2024.10.29   KHJ         NERP_SSP
         * 2026.09.16   AJS         MSSQL -> Oracle 전환 (WITH -> 인라인 뷰, XML PATH -> LISTAGG)
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT X.DIVISION_ID
             , B.COMPANY_ID    AS COMPANY_ID
             , C.SEGMENT2      AS TYPE
             , X.ERP_SO_NO
             , X.CONFIRM_ID
             , X.ITEM_ID
             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.FROM_SITE), X.FROM_SITE) AS FROM_SITE
             --, NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.TO_SITE), X.TO_SITE)     AS TO_SITE
             , NVL((SELECT MAX(SA.SITE_DESCRIPTION)   /* MSSQL 함수는 사이트 코드 대소문자 무시 */   -- 2026.09.17 AJS
                     FROM SCM_MST_SITE SA   -- 2026.09.17 AJS
                    WHERE UPPER(SA.SCM_SITE_ID) = UPPER(X.TO_SITE)), X.TO_SITE)     AS TO_SITE   -- 2026.09.17 AJS
             , X.TEAM
             , X.END_CUSTOMER
             , X.QTY
             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS YYYYMMDD
             , X.TRANSPORT_MODE
             , X.INCOTERMS
             , CASE WHEN REGEXP_LIKE(X.ETD_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD_DATE
             , CASE WHEN REGEXP_LIKE(X.ETA_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA_DATE
             , X.SHIP_TYPE
          FROM (
                /* CONFIRM_ID, 날짜동일한 기준으로 계획정보의 FROM, TO SITE기준으로 실적 집계 */
                SELECT IA.DIVISION_ID     AS DIVISION_ID
                     , 'E'                AS TYPE
                     , IA.ERP_SO_NO       AS ERP_SO_NO
                     , IA.CONFIRM_ID      AS CONFIRM_ID
                     , IA.ITEM_ID         AS ITEM_ID
                     , IA.FROM_SITE       AS FROM_SITE
                     , IA.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , IA.TEAM            AS TEAM
                     , SUM(IA.RESULT_QTY) AS QTY
                     , IA.YYYYMMDD        AS YYYYMMDD
                     , IA.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , IA.INCOTERMS       AS INCOTERMS
                     , IA.ETD_DATE        AS ETD_DATE
                     , IA.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        /* ERP 출하실적에서 CONFIRM_ID 존재, SSP_TYPE 대상 */
                        SELECT E.DIVISION_ID          AS DIVISION_ID
                             , E.CONFIRM_ID           AS CONFIRM_ID
                             , E.ORDER_NO             AS ERP_SO_NO
                             , E.EXFACTORY_DATE       AS YYYYMMDD
                             , E.TRANSPORT_MODE       AS TRANSPORT_MODE
                             , E.INCOTERMS            AS INCOTERMS
                             --, E.ETA_DATE             AS ETA_DATE
                             --, E.ETD_DATE             AS ETD_DATE
                             , NVL(E.ETA_DATE, '19000101') AS ETA_DATE   /* AS-IS '' -> 1900-01-01 */   -- 2026.09.17 AJS
                             , NVL(E.ETD_DATE, '19000101') AS ETD_DATE   -- 2026.09.17 AJS
                             , E.FROM_SCM_SITE_ID     AS FROM_SITE
                             , E.TO_SCM_SITE_ID       AS TO_SITE
                             , E.ITEM_ID              AS ITEM_ID
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
                                   --, TB_FX_USER SB
                                     , SCM_ADM_USER_M SB
                                     /* 2026.09.30 AJS 수정 (END) */
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   --AND SB.USERID IN (SELECT OWNER
                                   /* 2026.09.30 AJS 수정 (START) */
                                 --AND UPPER(SB.USERID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   AND UPPER(SB.USER_ID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID  = E.DIVISION_ID
                                                        AND SCM_SITE_ID  = E.TO_SCM_SITE_ID
                                                        AND ITEM_ID      = E.ITEM_ID
                                                        AND PROJECT_CODE = (SELECT MIN(SC.PROJECT_CODE)
                                                                              FROM SSP_ANL_SHIP_CONFIRM SC
                                                                             WHERE SC.CONFIRM_ID = E.CONFIRM_ID)
                                                        AND VALID_YN     = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                             , SUM(E.EXFACTORY_QTY)   AS RESULT_QTY
                          FROM SCM_DNM_EXFACTORY_RESULT E
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L
                         WHERE L.LOOKUP_TYPE = 'ERP_SSP_TYPE'   /* LOOKUP에 등록된 공정만 */
                           AND L.VALID_YN    = 'Y'
                           AND L.SEGMENT1    = E.SSP_TYPE
                           AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')   /* D90: DO삭제 , D10:DO생성 */
                           AND E.CONFIRM_ID LIKE 'C%'
                           AND E.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY E.DIVISION_ID
                             , E.CONFIRM_ID
                             , E.ORDER_NO
                             , E.EXFACTORY_DATE
                             , E.TRANSPORT_MODE
                             , E.INCOTERMS
                             , E.ETA_DATE
                             , E.ETD_DATE
                             , E.FROM_SCM_SITE_ID
                             , E.TO_SCM_SITE_ID
                             , E.ITEM_ID
                       ) IA
                 GROUP BY IA.DIVISION_ID
                     , IA.ERP_SO_NO
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.ITEM_ID
                     , IA.TRANSPORT_MODE
                     , IA.INCOTERMS
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.YYYYMMDD
                     , IA.CONFIRM_ID
                     , IA.TEAM
                UNION ALL
                /* CONFIRM_ID 없는 실적 */
                SELECT XB.DIVISION_ID     AS DIVISION_ID
                     , 'E'                AS TYPE
                     , XB.ERP_SO_NO       AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XB.ITEM_ID         AS ITEM_ID
                     , XB.FROM_SITE       AS FROM_SITE
                     , XB.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XB.TEAM            AS TEAM
                     , XB.QTY             AS QTY
                     , XB.YYYYMMDD        AS YYYYMMDD
                     , XB.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XB.INCOTERMS       AS INCOTERMS
                     , XB.ETD_DATE        AS ETD_DATE
                     , XB.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        SELECT E.DIVISION_ID          AS DIVISION_ID
                             , '-'                    AS CONFIRM_ID
                             , E.ORDER_NO             AS ERP_SO_NO
                             , E.FROM_SCM_SITE_ID     AS FROM_SITE
                             , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID) AS TO_SITE
                             , E.ITEM_ID              AS ITEM_ID
                             , E.EXFACTORY_DATE       AS YYYYMMDD
                             , E.TRANSPORT_MODE       AS TRANSPORT_MODE
                             , E.INCOTERMS            AS INCOTERMS
                             --, E.ETA_DATE             AS ETA_DATE
                             --, E.ETD_DATE             AS ETD_DATE
                             , NVL(E.ETA_DATE, '19000101') AS ETA_DATE   /* AS-IS '' -> 1900-01-01 */   -- 2026.09.17 AJS
                             , NVL(E.ETD_DATE, '19000101') AS ETD_DATE   -- 2026.09.17 AJS
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
                                   --, TB_FX_USER SB
                                     , SCM_ADM_USER_M SB
                                     /* 2026.09.30 AJS 수정 (END) */
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   --AND SB.USERID IN (SELECT OWNER
                                   /* 2026.09.30 AJS 수정 (START) */
                                 --AND UPPER(SB.USERID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   AND UPPER(SB.USER_ID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID = E.DIVISION_ID
                                                        AND SCM_SITE_ID = E.TO_SCM_SITE_ID
                                                        AND ITEM_ID     = E.ITEM_ID
                                                        AND VALID_YN    = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                             , SUM(E.EXFACTORY_QTY)   AS QTY
                          FROM SCM_DNM_EXFACTORY_RESULT E
                             , SCP_MST_FINAL_ITEM F
                             , SCM_MST_SITE S
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L
                             , SCM_ADM_LOOKUP_MASTER_DETAIL L3
                         WHERE F.ITEM_ID     = E.ITEM_ID       /* SCP 대상 ITEM만 */
                           AND F.DIVISION_ID = E.DIVISION_ID
                           AND S.SCM_SITE_ID = E.FROM_SCM_SITE_ID
                           AND S.DIVISION_ID = E.DIVISION_ID
                           AND L.LOOKUP_TYPE = 'ERP_ORDER_TYPE'   /* LOOKUP에 등록된 ORDER_TYPE만 대상으로 함 */
                           AND L.VALID_YN    = 'Y'
                           AND L.SEGMENT1    = E.ORDER_TYPE_CODE
                           AND L3.LOOKUP_TYPE(+) = 'SHIP_RESULT_TO_SITE_MAPPING'   /* SOLDTO, SHIPTO 과 MAPPING되는 TO_SITE */
                           AND L3.SEGMENT1(+)    = E.DIVISION_ID
                           AND L3.SEGMENT2(+)    = E.SOLDTO_CODE
                           AND L3.SEGMENT3(+)    = E.SHIPTO_CODE
                           AND NVL(E.EXFACTORY_STATUS, 'D90') NOT IN ('D90', 'D10')   /* D90: DO삭제 , D10:DO생성 */
                           AND NVL(E.CONFIRM_ID, '-') NOT LIKE 'C%'
                           AND E.EXFACTORY_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND E.STORAGE_ID NOT IN (SELECT COLUMN_VALUE
                                                      FROM TABLE(FN_LIST_LOOKUP_VALUE('SSP0015_GET_SHIPMENT_RESULT', 'PRODUCT_STORAGE')))   /* 상품창고제외 */
                           /* [C20200403-000062] 사외 창고 제외 LOOKUP 관리 */
                           AND NOT EXISTS (SELECT 1
                                             FROM SCM_ADM_LOOKUP_MASTER_DETAIL SB
                                            WHERE SB.LOOKUP_TYPE = 'SSP_SHIP_RESULT_EXCEPT_STORAGE'
                                              AND SB.VALID_YN    = 'Y'
                                              AND SB.SEGMENT1    = E.STORAGE_ID)
                         GROUP BY E.DIVISION_ID
                             , E.ORDER_NO
                             , E.FROM_SCM_SITE_ID
                             , NVL(L3.SEGMENT4, E.TO_SCM_SITE_ID)
                             , E.ITEM_ID
                             , E.EXFACTORY_DATE
                             , E.TRANSPORT_MODE
                             , E.INCOTERMS
                             , E.ETA_DATE
                             , E.ETD_DATE
                             , E.TO_SCM_SITE_ID
                       ) XB
                UNION ALL
                /* SSP출하계획 ( confirm된 계획) */
                SELECT XC.DIVISION_ID     AS DIVISION_ID
                     , 'P'                AS TYPE
                     , XC.ERP_SO_NO       AS ERP_SO_NO
                     , XC.CONFIRM_ID      AS CONFIRM_ID
                     , XC.ITEM_ID         AS ITEM_ID
                     , XC.FROM_SITE       AS FROM_SITE
                     , XC.TO_SITE         AS TO_SITE
                     , XC.END_CUSTOMER    AS END_CUSTOMER
                     , '-'                AS TEAM
                     , XC.QTY             AS QTY
                     , XC.YYYYMMDD        AS YYYYMMDD
                     , XC.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XC.INCOTERMS       AS INCOTERMS
                     , XC.ETD_DATE        AS ETD_DATE
                     , XC.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                  FROM (
                        /* Current Version */
                        SELECT C.DIVISION_ID     AS DIVISION_ID
                             , C.ERP_SO_NO       AS ERP_SO_NO
                             , C.CONFIRM_ID      AS CONFIRM_ID
                             , C.ITEM_ID         AS ITEM_ID
                             , C.FROM_SITE       AS FROM_SITE
                             , C.TO_SITE         AS TO_SITE
                               /* AS-IS 원형 유지 : '4O' 는 알파벳 O 다 */
                             , CASE WHEN C.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , C.QTY             AS QTY
                             , C.YYYYMMDD        AS YYYYMMDD
                             , C.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , C.INCOTERMS       AS INCOTERMS
                             , C.ETD_DATE        AS ETD_DATE
                             , C.ETA_DATE        AS ETA_DATE
                          FROM SSP_ANL_SHIP_CONFIRM C
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE SI.DIVISION_ID(+)  = C.DIVISION_ID
                           AND SI.ITEM_ID(+)      = C.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = C.TO_SITE
                           AND SI.PROJECT_CODE(+) = C.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = C.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = C.TO_SITE
                           AND C.CHANGE_TYPE = 'C'
                           AND C.QTY > 0
                           AND C.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND C.CONFIRM_ID LIKE 'C%'
                           AND P_REAL_FLAG = 'Y'
                        UNION ALL
                        /* OLD Version */
                        SELECT D.DIVISION_ID     AS DIVISION_ID
                             , D.ERP_SO_NO       AS ERP_SO_NO
                             , D.CONFIRM_ID      AS CONFIRM_ID
                             , D.ITEM_ID         AS ITEM_ID
                             , D.FROM_SITE       AS FROM_SITE
                             , D.TO_SITE         AS TO_SITE
                             , CASE WHEN D.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , D.SHIPMENT_CONFIRM_QTY AS QTY
                             , D.YYYYMMDD        AS YYYYMMDD
                             , D.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , D.INCOTERMS       AS INCOTERMS
                             , D.ETD             AS ETD_DATE
                             , D.ETA             AS ETA_DATE
                          FROM SSP_ANL_SHIP_PLAN_ALL D
                             , SCM_MST_SITE MS
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE D.DIVISION_ID = MS.DIVISION_ID
                           AND D.FROM_SITE   = MS.SCM_SITE_ID
                           AND MS.SITE_TYPE  = 'PLANT'
                           AND D.DIVISION_ID = '40'
                           AND MS.OPERATION_GROUP = 'A'
                           AND SI.DIVISION_ID(+)  = D.DIVISION_ID
                           AND SI.ITEM_ID(+)      = D.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = D.TO_SITE
                           AND SI.PROJECT_CODE(+) = D.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = D.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = D.TO_SITE
                           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND D.SHIPMENT_STATUS     = 'C'
                           AND D.SHIPMENT_CONFIRM_QTY > 0
                           AND D.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'N'
                       ) XC
                UNION ALL
                /* OWMS 실적 */
                SELECT XD.DIVISION_ID     AS DIVISION_ID
                     , 'O'                AS TYPE
                     , NULL               AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XD.ITEM_ID         AS ITEM_ID
                     , XD.FROM_SITE       AS FROM_SITE
                     , XD.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XD.TEAM            AS TEAM
                     , XD.QTY             AS QTY
                     , XD.YYYYMMDD        AS YYYYMMDD
                     , NULL               AS TRANSPORT_MODE
                     , NULL               AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , XD.SHIP_TYPE       AS SHIP_TYPE
                  FROM (
                        SELECT A.DIVISION_ID      AS DIVISION_ID
                             , A.ITEM_ID          AS ITEM_ID
                             , A.FROM_SITE        AS FROM_SITE
                             , CASE WHEN A.TO_SITE = '-' THEN A.CUSTOMER_CODE ELSE A.TO_SITE END AS TO_SITE
                             , SUM(A.LOT_QTY)     AS QTY
                             , A.PLANT_ISSUE_DATE AS YYYYMMDD
                             , A.SHIP_TYPE        AS SHIP_TYPE
                             , (SELECT LISTAGG(NVL(SA.DEPT_NAME_KO, '-'), ',' ON OVERFLOW TRUNCATE)
                                       WITHIN GROUP (ORDER BY SA.DEPT_NAME_KO)
                                  FROM SCM_MST_SSO_DEPT_INFO SA
                                     /* 2026.09.30 AJS 수정 (START) */
                                   --, TB_FX_USER SB
                                     , SCM_ADM_USER_M SB
                                     /* 2026.09.30 AJS 수정 (END) */
                                 WHERE SA.DEPT_ID = SB.DEPT_ID
                                   --AND SB.USERID IN (SELECT OWNER
                                   /* 2026.09.30 AJS 수정 (START) */
                                 --AND UPPER(SB.USERID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   AND UPPER(SB.USER_ID) IN (SELECT UPPER(OWNER)   -- 2026.09.17 AJS
                                   /* 2026.09.30 AJS 수정 (END) */
                                                       FROM SCM_MST_SITE_ITEM
                                                      WHERE 1 = 1
                                                        AND DIVISION_ID = A.DIVISION_ID
                                                        AND SCM_SITE_ID = A.TO_SITE
                                                        AND ITEM_ID     = A.ITEM_ID
                                                        AND VALID_YN    = 'Y'
                                                        AND OWNER IS NOT NULL)) AS TEAM
                          FROM SSP_DNM_SHIP_RESULT_OWMS A
                         WHERE A.PLANT_ISSUE_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY A.DIVISION_ID
                             , A.ITEM_ID
                             , A.FROM_SITE
                             , CASE WHEN A.TO_SITE = '-' THEN A.CUSTOMER_CODE ELSE A.TO_SITE END
                             , A.PLANT_ISSUE_DATE
                             , A.SHIP_TYPE
                             , A.TO_SITE
                       ) XD
                UNION ALL
                /* OWMS 반품실적 */
                SELECT XE.DIVISION_ID     AS DIVISION_ID
                     , 'R'                AS TYPE
                     , NULL               AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XE.ITEM_ID         AS ITEM_ID
                     , XE.FROM_SITE       AS FROM_SITE
                     , XE.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , '-'                AS TEAM
                     , XE.QTY             AS QTY
                     , XE.YYYYMMDD        AS YYYYMMDD
                     , NULL               AS TRANSPORT_MODE
                     , NULL               AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , XE.SHIP_TYPE       AS SHIP_TYPE
                  FROM (
                        SELECT B.DIVISION_ID      AS DIVISION_ID
                             , B.ITEM_ID          AS ITEM_ID
                             , B.FROM_SITE        AS FROM_SITE
                             , '*'                AS TO_SITE
                             , SUM(B.RECIEPT_QTY) AS QTY
                             , B.RECIEPT_DATE     AS YYYYMMDD
                             , NULL               AS SHIP_TYPE
                          FROM SSP_DNM_SHIP_RETURN_OWMS B
                         WHERE B.RECIEPT_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY B.DIVISION_ID
                             , B.ITEM_ID
                             , B.FROM_SITE
                             , B.RECIEPT_DATE
                       ) XE
               ) X
             , SCM_MST_SITE B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
             , SSP_MST_MODEL_USER M
         WHERE B.DIVISION_ID = X.DIVISION_ID
           AND B.SCM_SITE_ID = X.FROM_SITE
           AND B.OPERATION_GROUP <> 'E'
           AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE'   /* LOOKUP에 등록된 공정만 */
           AND C.SEGMENT1    = X.TYPE
           AND C.VALID_YN    = 'Y'
           AND M.DIVISION_ID(+) = X.DIVISION_ID
           AND M.FROM_SITE(+)   = X.FROM_SITE
           AND M.ITEM_ID(+)     = X.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           AND X.DIVISION_ID = P_DIVISION_ID
           --AND ((P_COMPANY_ID IS NULL OR P_COMPANY_ID = '') OR B.COMPANY_ID = P_COMPANY_ID)
           AND ((TRIM(P_COMPANY_ID) IS NULL) OR B.COMPANY_ID = P_COMPANY_ID)   -- 2026.09.17 AJS
           --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
           AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
           AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                 --OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR X.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           --AND ((P_TYPE IS NULL OR P_TYPE = '')
           AND ((TRIM(P_TYPE) IS NULL)   -- 2026.09.17 AJS
                 OR X.TYPE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_TYPE, ','))))
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         --ORDER BY X.DIVISION_ID
             --, X.FROM_SITE
             --, X.YYYYMMDD
             --, X.ITEM_ID
             --, X.TO_SITE
             --, C.DISPLAY_SEQ
             --, X.CONFIRM_ID;
         ORDER BY X.DIVISION_ID NULLS FIRST   /* MSSQL 오름차순 NULL 앞 */   -- 2026.09.17 AJS
             , X.FROM_SITE NULLS FIRST   -- 2026.09.17 AJS
             , X.YYYYMMDD NULLS FIRST   -- 2026.09.17 AJS
             , X.ITEM_ID NULLS FIRST   -- 2026.09.17 AJS
             , X.TO_SITE NULLS FIRST   -- 2026.09.17 AJS
             , C.DISPLAY_SEQ NULLS FIRST   -- 2026.09.17 AJS
             , X.CONFIRM_ID NULLS FIRST;   -- 2026.09.17 AJS

    END P_SSP0015_GET_SHIPMENT_RESULT;

    /* ============================================================
       P_SSP0015_GET_SHIPMENT_RESULT_PACKER
       AS-IS SSP0015_GET_SHIPMENT_RESULT_PACKER
       ※ AS-IS WITH 절 3벌은 각각 1회만 참조하므로 인라인 뷰로 펼쳤다.
       ※ AS-IS 의 CASE WHEN DIVISION_ID = '4O' 는 알파벳 O 다. 원형 유지.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_RESULT_PACKER
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_TYPE                  IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_REAL_FLAG             IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_RESULT_PACKER
         * Description  : Shipment Shipment Result
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021/10/05   KIMYONGHO		신규추가
         * 2021/11/26   SMS		        Ship to 추가
         * 2026.09.16   AJS             MSSQL -> Oracle 전환 (WITH -> 인라인 뷰)
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT X.DIVISION_ID
             , B.COMPANY_ID    AS COMPANY_ID
             , C.SEGMENT2      AS TYPE
             , X.ERP_SO_NO
             , X.CONFIRM_ID
             , X.ITEM_ID
             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
             , NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.FROM_SITE), X.FROM_SITE) AS FROM_SITE
             --, NVL(FN_GET_SCM_SITE_DESCRIPTION(X.DIVISION_ID, X.TO_SITE), X.TO_SITE)     AS TO_SITE
             , NVL((SELECT MAX(SA.SITE_DESCRIPTION)   /* MSSQL 함수는 사이트 코드 대소문자 무시 */   -- 2026.09.17 AJS
                     FROM SCM_MST_SITE SA   -- 2026.09.17 AJS
                    WHERE UPPER(SA.SCM_SITE_ID) = UPPER(X.TO_SITE)), X.TO_SITE)     AS TO_SITE   -- 2026.09.17 AJS
             , X.END_CUSTOMER
             , X.QTY
             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') END AS YYYYMMDD
             , X.TRANSPORT_MODE
             , X.INCOTERMS
             , CASE WHEN REGEXP_LIKE(X.ETD_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETD_DATE
             , CASE WHEN REGEXP_LIKE(X.ETA_DATE, '^[0-9]{8}$')
                    THEN TO_CHAR(TO_DATE(X.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') END AS ETA_DATE
             , X.SHIP_TYPE
               /* 20211126  SMS  추가 Ship to, Shipto description */
             , X.SHIP_TO
             --, D.SHIPTO_DESCRIPTION
             , XF.SHIPTO_DESCRIPTION   -- 2026.09.17 AJS
          FROM (
                /* SCS 출하실적에서 CONFIRM_ID 존재 */
                SELECT IA.DIVISION_ID     AS DIVISION_ID
                     , 'S'                AS TYPE
                     , IA.ERP_SO_NO       AS ERP_SO_NO
                     , IA.CONFIRM_ID      AS CONFIRM_ID
                     , IA.ITEM_ID         AS ITEM_ID
                     , IA.FROM_SITE       AS FROM_SITE
                     , IA.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , SUM(IA.RESULT_QTY) AS QTY
                     , IA.YYYYMMDD        AS YYYYMMDD
                     , IA.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , IA.INCOTERMS       AS INCOTERMS
                     , IA.ETD_DATE        AS ETD_DATE
                     , IA.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , IA.SHIP_TO         AS SHIP_TO
                  FROM (
                        SELECT E.DIVISION_ID      AS DIVISION_ID
                             , E.ATTRIBUTE5       AS CONFIRM_ID
                             , C.ERP_SO_NO        AS ERP_SO_NO
                             , E.SHIP_DATE        AS YYYYMMDD
                             , C.TRANSPORT_MODE   AS TRANSPORT_MODE
                             , C.INCOTERMS        AS INCOTERMS
                             , C.ETA_DATE         AS ETA_DATE
                             , C.ETD_DATE         AS ETD_DATE
                             , E.SCM_SITE_ID      AS FROM_SITE
                             , E.TO_SITE          AS TO_SITE
                             , E.ITEM_ID          AS ITEM_ID
                               /* 20211126  SMS  추가  Ship to */
                             , E.ATTRIBUTE4       AS SHIP_TO
                             , SUM(E.SHIP_QTY)    AS RESULT_QTY
                          FROM SCM_DNM_SCS_SHIP_RESULT E
                             , SSP_ANL_SHIP_CONFIRM C
                         WHERE E.DIVISION_ID = C.DIVISION_ID(+)
                           AND E.ATTRIBUTE5  = C.CONFIRM_ID(+)
                           AND E.SHIP_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                         GROUP BY E.DIVISION_ID
                             , E.ATTRIBUTE5
                             , C.ERP_SO_NO
                             , E.SHIP_DATE
                             , C.TRANSPORT_MODE
                             , C.INCOTERMS
                             , C.ETA_DATE
                             , C.ETD_DATE
                             , E.SCM_SITE_ID
                             , E.TO_SITE
                             , E.ITEM_ID
                             , E.ATTRIBUTE4
                       ) IA
                 GROUP BY IA.DIVISION_ID
                     , IA.ERP_SO_NO
                     , IA.FROM_SITE
                     , IA.TO_SITE
                     , IA.ITEM_ID
                     , IA.TRANSPORT_MODE
                     , IA.INCOTERMS
                     , IA.ETD_DATE
                     , IA.ETA_DATE
                     , IA.YYYYMMDD
                     , IA.CONFIRM_ID
                     , IA.SHIP_TO
                UNION ALL
                /* SCS 출하실적에서 CONFIRM_ID 없는 실적 */
                SELECT XB.DIVISION_ID     AS DIVISION_ID
                     , 'S'                AS TYPE
                     , XB.ERP_SO_NO       AS ERP_SO_NO
                     , NULL               AS CONFIRM_ID
                     , XB.ITEM_ID         AS ITEM_ID
                     , XB.FROM_SITE       AS FROM_SITE
                     , XB.TO_SITE         AS TO_SITE
                     , NULL               AS END_CUSTOMER
                     , XB.RESULT_QTY      AS QTY
                     , XB.YYYYMMDD        AS YYYYMMDD
                     , XB.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XB.INCOTERMS       AS INCOTERMS
                     , NULL               AS ETD_DATE
                     , NULL               AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , XB.SHIP_TO         AS SHIP_TO
                  FROM (
                        SELECT E.DIVISION_ID      AS DIVISION_ID
                             , E.ATTRIBUTE5       AS CONFIRM_ID
                             , '-'                AS ERP_SO_NO
                             , E.SHIP_DATE        AS YYYYMMDD
                             , '-'                AS TRANSPORT_MODE
                             , '-'                AS INCOTERMS
                             , '-'                AS ETA_DATE
                             , '-'                AS ETD_DATE
                             , E.SCM_SITE_ID      AS FROM_SITE
                             , E.TO_SITE          AS TO_SITE
                             , E.ITEM_ID          AS ITEM_ID
                             , E.ATTRIBUTE4       AS SHIP_TO
                             , SUM(E.SHIP_QTY)    AS RESULT_QTY
                          FROM SCM_DNM_SCS_SHIP_RESULT E
                         WHERE E.SHIP_DATE BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND NVL(E.ATTRIBUTE5, '-') = '-'
                         GROUP BY E.DIVISION_ID
                             , E.ATTRIBUTE5
                             , E.SHIP_DATE
                             , E.ITEM_ID
                             , E.SCM_SITE_ID
                             , E.TO_SITE
                             , E.ATTRIBUTE4
                       ) XB
                UNION ALL
                /* SSP출하계획 ( confirm된 계획) */
                SELECT XC.DIVISION_ID     AS DIVISION_ID
                     , 'P'                AS TYPE
                     , XC.ERP_SO_NO       AS ERP_SO_NO
                     , XC.CONFIRM_ID      AS CONFIRM_ID
                     , XC.ITEM_ID         AS ITEM_ID
                     , XC.FROM_SITE       AS FROM_SITE
                     , XC.TO_SITE         AS TO_SITE
                     , XC.END_CUSTOMER    AS END_CUSTOMER
                     , XC.QTY             AS QTY
                     , XC.YYYYMMDD        AS YYYYMMDD
                     , XC.TRANSPORT_MODE  AS TRANSPORT_MODE
                     , XC.INCOTERMS       AS INCOTERMS
                     , XC.ETD_DATE        AS ETD_DATE
                     , XC.ETA_DATE        AS ETA_DATE
                     , NULL               AS SHIP_TYPE
                     , XC.SHIP_TO         AS SHIP_TO
                  FROM (
                        /* Current Version */
                        SELECT C.DIVISION_ID     AS DIVISION_ID
                             , C.ERP_SO_NO       AS ERP_SO_NO
                             , C.CONFIRM_ID      AS CONFIRM_ID
                             , C.ITEM_ID         AS ITEM_ID
                             , C.FROM_SITE       AS FROM_SITE
                             , C.TO_SITE         AS TO_SITE
                             , CASE WHEN C.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , C.QTY             AS QTY
                             , C.YYYYMMDD        AS YYYYMMDD
                             , C.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , C.INCOTERMS       AS INCOTERMS
                             , C.ETD_DATE        AS ETD_DATE
                             , C.ETA_DATE        AS ETA_DATE
                             , C.TO_SITE_SHIPTO_CODE AS SHIP_TO
                          FROM SSP_ANL_SHIP_CONFIRM C
                             , SCM_MST_SITE MS
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE C.DIVISION_ID = MS.DIVISION_ID
                           AND C.FROM_SITE   = MS.SCM_SITE_ID
                           AND MS.SITE_TYPE  = 'PLANT'
                           AND C.DIVISION_ID = '40'
                           AND MS.OPERATION_GROUP = 'P'
                           AND SI.DIVISION_ID(+)  = C.DIVISION_ID
                           AND SI.ITEM_ID(+)      = C.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = C.TO_SITE
                           AND SI.PROJECT_CODE(+) = C.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = C.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = C.TO_SITE
                           AND TS.VALID_YN(+)     = 'Y'   /* NERP 추가 */
                           AND C.CHANGE_TYPE = 'C'
                           AND C.QTY > 0
                           AND C.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'Y'
                        UNION ALL
                        /* OLD Version */
                        SELECT D.DIVISION_ID     AS DIVISION_ID
                             , NULL              AS ERP_SO_NO
                             , D.CONFIRM_ID      AS CONFIRM_ID
                             , D.ITEM_ID         AS ITEM_ID
                             , D.FROM_SITE       AS FROM_SITE
                             , V.TO_SITE         AS TO_SITE
                             , CASE WHEN D.DIVISION_ID = '4O' THEN NVL(SI.PROJECT_CODE, '/')
                                    ELSE NVL(TS.END_CUSTOMER, '-') END AS END_CUSTOMER
                             , D.QTY             AS QTY
                             , D.YYYYMMDD        AS YYYYMMDD
                             , V.TRANSPORT_MODE  AS TRANSPORT_MODE
                             , V.INCOTERMS       AS INCOTERMS
                             , D.ETD_DATE        AS ETD_DATE
                             , D.ETA_DATE        AS ETA_DATE
                             , D.SHIPTO_CODE     AS SHIP_TO
                          FROM SSP_ANL_SHIP_PLAN_P D
                             , SCP_MST_BOD_N_V V
                             , SCM_MST_SITE_ITEM SI
                             , SCM_MST_SITE TS
                         WHERE D.BOD_ID = V.BOD_ID
                           AND SI.DIVISION_ID(+)  = D.DIVISION_ID
                           AND SI.ITEM_ID(+)      = D.ITEM_ID
                           AND SI.SCM_SITE_ID(+)  = V.TO_SITE
                           AND SI.PROJECT_CODE(+) = D.PROJECT_CODE
                           AND TS.DIVISION_ID(+)  = D.DIVISION_ID
                           AND TS.SCM_SITE_ID(+)  = V.TO_SITE
                           AND TS.VALID_YN(+)     = 'Y'   /* NERP 추가 */
                           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND D.MEASURE      = 'SHIP_CONFIRM'
                           AND D.CONFIRM_FLAG = 'Y'
                           AND D.QTY > 0
                           AND D.YYYYMMDD BETWEEN P_FROM_YYYYMMDD AND P_TO_YYYYMMDD
                           AND P_REAL_FLAG = 'N'
                       ) XC
               ) X
             , SCM_MST_SITE B
             , SCM_ADM_LOOKUP_MASTER_DETAIL C
             , SSP_MST_MODEL_USER M
               /* 20211126  SMS  추가  Shipto Description */
             --, (SELECT DIVISION_ID, SHIPTO_CODE, MAX(SHIPTO_DESCRIPTION) AS SHIPTO_DESCRIPTION
                  --FROM SCM_MST_CUSTOMER
                 --WHERE DIVISION_ID = '40'
                 --GROUP BY DIVISION_ID, SHIPTO_CODE) D
             , (SELECT DIVISION_ID, UPPER(RTRIM(SHIPTO_CODE)) AS SHIPTO_CODE, MAX(SHIPTO_DESCRIPTION) AS SHIPTO_DESCRIPTION   -- 2026.09.17 AJS
                  FROM SCM_MST_CUSTOMER   -- 2026.09.17 AJS
                 WHERE DIVISION_ID = '40'   -- 2026.09.17 AJS
                 GROUP BY DIVISION_ID, UPPER(RTRIM(SHIPTO_CODE))) XF   -- 2026.09.17 AJS
         WHERE B.DIVISION_ID = X.DIVISION_ID
           AND B.SCM_SITE_ID = X.FROM_SITE
           AND B.OPERATION_GROUP <> 'E'
           AND C.LOOKUP_TYPE = 'SSP_SHIPMENT_RESULT_TYPE_PACKER'   /* LOOKUP에 등록된 공정만 */
           AND C.SEGMENT1    = X.TYPE
           AND C.VALID_YN    = 'Y'
           AND M.DIVISION_ID(+) = X.DIVISION_ID
           AND M.FROM_SITE(+)   = X.FROM_SITE
           AND M.ITEM_ID(+)     = X.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           --AND X.DIVISION_ID = D.DIVISION_ID(+)
           --AND X.SHIP_TO     = D.SHIPTO_CODE(+)
           AND X.DIVISION_ID = XF.DIVISION_ID(+)   -- 2026.09.17 AJS
           AND UPPER(RTRIM(X.SHIP_TO)) = XF.SHIPTO_CODE(+)   -- 2026.09.17 AJS
           AND X.DIVISION_ID = P_DIVISION_ID
           --AND ((P_COMPANY_ID IS NULL OR P_COMPANY_ID = '') OR B.COMPANY_ID = P_COMPANY_ID)
           AND ((TRIM(P_COMPANY_ID) IS NULL) OR B.COMPANY_ID = P_COMPANY_ID)   -- 2026.09.17 AJS
           --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
           AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
           AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                 --OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR X.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           --AND ((P_TYPE IS NULL OR P_TYPE = '')
           AND ((TRIM(P_TYPE) IS NULL)   -- 2026.09.17 AJS
                 OR X.TYPE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_TYPE, ','))))
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         --ORDER BY X.DIVISION_ID
             --, X.FROM_SITE
             --, X.YYYYMMDD
             --, X.ITEM_ID
             --, X.TO_SITE
             --, C.DISPLAY_SEQ
             --, X.CONFIRM_ID;
         ORDER BY X.DIVISION_ID NULLS FIRST   /* MSSQL 오름차순 NULL 앞 */   -- 2026.09.17 AJS
             , X.FROM_SITE NULLS FIRST   -- 2026.09.17 AJS
             , X.YYYYMMDD NULLS FIRST   -- 2026.09.17 AJS
             , X.ITEM_ID NULLS FIRST   -- 2026.09.17 AJS
             , X.TO_SITE NULLS FIRST   -- 2026.09.17 AJS
             , C.DISPLAY_SEQ NULLS FIRST   -- 2026.09.17 AJS
             , X.CONFIRM_ID NULLS FIRST;   -- 2026.09.17 AJS

    END P_SSP0015_GET_SHIPMENT_RESULT_PACKER;

    /* ============================================================
       P_SSP0015_GET_BLOCK_STOCK
       AS-IS SSP0015_GET_BLOCK_STOCK - 결과셋 2벌(본문 · 상세)
       ※ AS-IS 는 두 결과셋의 SELECT 문이 완전히 같다. 조회조건만 P_SEARCH_YN 으로 갈린다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_BLOCK_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_SEQ                   IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_SEARCH_YN             IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2 DEFAULT 'N',
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_BLOCK_STOCK
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/03/05   AYJ 			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/06/17	AYJ				조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			    조회 조건 추가(p_delegateeChk)
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         */
        V_BASE_YYYYMMDD VARCHAR2(8 CHAR);
    BEGIN

        /* AS-IS : convert(varchar(8), convert(datetime, @p_plan_start_yyyymmdd) +1, 112) */
        V_BASE_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 1, 'YYYYMMDD');

        IF P_SEARCH_YN != 'Y' THEN

            /* 1. 셀 더블클릭 */
            OPEN O_RC1 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                   /* MSSQL 은 UserName 이 NULL 이면 결합 결과도 NULL 이다 - 판정을 유지한다 */
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 /* 2026.09.30 AJS 수정 (START) */
               --, TB_FX_USER U
                 , SCM_ADM_USER_M U
                 /* 2026.09.30 AJS 수정 (END) */
                 , SSP_MST_MODEL_USER M
             /* 2026.09.30 AJS 수정 (START) */
           --WHERE A.LAST_UPDATED_BY = U.USERID(+)
             --AND U.USEYN(+)        = 'Y'
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)        = 'Y'
             /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.FROM_SITE           = P_FROM_SITE
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               --AND A.ITEM_ID             = P_ITEM_ID
               AND A.ITEM_ID             = UPPER(P_ITEM_ID)   -- 2026.09.17 AJS
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

            /* Block Stock Detail - AS-IS 는 위와 같은 문장이다 */
            OPEN O_RC2 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 /* 2026.09.30 AJS 수정 (START) */
               --, TB_FX_USER U
                 , SCM_ADM_USER_M U
                 /* 2026.09.30 AJS 수정 (END) */
                 , SSP_MST_MODEL_USER M
             /* 2026.09.30 AJS 수정 (START) */
           --WHERE A.LAST_UPDATED_BY = U.USERID(+)
             --AND U.USEYN(+)        = 'Y'
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)        = 'Y'
             /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.FROM_SITE           = P_FROM_SITE
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               --AND A.ITEM_ID             = P_ITEM_ID
               AND A.ITEM_ID             = UPPER(P_ITEM_ID)   -- 2026.09.17 AJS
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

        ELSE

            /* 2. btnSearch */
            OPEN O_RC1 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 /* 2026.09.30 AJS 수정 (START) */
               --, TB_FX_USER U
                 , SCM_ADM_USER_M U
                 /* 2026.09.30 AJS 수정 (END) */
                 , SSP_MST_MODEL_USER M
             /* 2026.09.30 AJS 수정 (START) */
           --WHERE A.LAST_UPDATED_BY = U.USERID(+)
             --AND U.USEYN(+)        = 'Y'
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)        = 'Y'
             /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
               AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
               AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                     --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                     OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
               /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

            OPEN O_RC2 FOR
            SELECT A.HOLD_ID
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_NM
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , TO_CHAR(FN_CHAR_TO_DATE(A.HOLD_YYYYMMDD), 'YYYY-MM-DD')    AS HOLD_YYYYMMDD
                 , TO_CHAR(FN_CHAR_TO_DATE(A.RELEASE_YYYYMMDD), 'YYYY-MM-DD') AS RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END AS LAST_UPDATED_BY
                 , A.LAST_UPDATE_DATE
              FROM SSP_ANL_HOLD_STOCK A
                 /* 2026.09.30 AJS 수정 (START) */
               --, TB_FX_USER U
                 , SCM_ADM_USER_M U
                 /* 2026.09.30 AJS 수정 (END) */
                 , SSP_MST_MODEL_USER M
             /* 2026.09.30 AJS 수정 (START) */
           --WHERE A.LAST_UPDATED_BY = U.USERID(+)
             --AND U.USEYN(+)        = 'Y'
             WHERE A.LAST_UPDATED_BY = U.USER_ID(+)
               AND U.USE_YN(+)        = 'Y'
             /* 2026.09.30 AJS 수정 (END) */
               AND M.DIVISION_ID(+)  = A.DIVISION_ID
               AND M.FROM_SITE(+)    = A.FROM_SITE
               AND M.ITEM_ID(+)      = A.ITEM_ID
               AND M.VALID_YN(+)     = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
               AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               AND A.HOLD_YYYYMMDD      <= V_BASE_YYYYMMDD
               AND A.RELEASE_YYYYMMDD   >= V_BASE_YYYYMMDD
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_SEQ
               --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
               AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                     --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                     OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
             GROUP BY A.HOLD_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.DIVISION_ID
                 , A.FROM_SITE
                 , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-')
                 , A.HOLD_YYYYMMDD
                 , A.RELEASE_YYYYMMDD
                 , A.HOLD_QTY
                 , A.REMARKS
                 , A.LAST_UPDATE_DATE
                 /* 2026.09.30 AJS 수정 (START) */
               --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                      --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                 , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                        ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                 /* 2026.09.30 AJS 수정 (END) */
                   END
             ORDER BY A.HOLD_ID;

        END IF;

    END P_SSP0015_GET_BLOCK_STOCK;

    /* ============================================================
       P_SSP0015_GET_WH_STOCK
       AS-IS SSP0015_GET_WH_STOCK - 결과셋 2벌(본문 · 상세)
       ============================================================ */
    PROCEDURE P_SSP0015_GET_WH_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_PLAN_TYPE             IN  VARCHAR2,
        P_PLAN_SEQ              IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2 DEFAULT 'N',
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_SEARCH_YN             IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_WH_STOCK
         * Description  : Shipment PSI(Small)
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/03/05   AYJ			Initial Release [PJ20189106] 전지.GSCM 고도화 이행 PROJECT
         * 2019/06/17	AYJ			조회 조건 추가(p_partLeaderChk, p_teamLeaderChk)
         * 2019/08/28	AYJ			조회 조건 추가(p_delegateeChk)
         * 2026.09.16   AJS         MSSQL -> Oracle 전환
         */
    BEGIN

        IF P_SEARCH_YN != 'Y' THEN

            /* 1. 셀 더블클릭 - W/H Stock */
            OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE          AS CAPA_GRADE
                 , A.SOC
                 , SUM(A.STOCK_QTY)          AS STOCK_QTY
                 , SUM(A.AVAILABLE_QTY)      AS AVAILABLE_QTY
                 , SUM(A.NON_QC_QTY)         AS UNDECIDED_QTY
                 , SUM(A.ALLOCATION_QTY)     AS ALLOCATION_QTY
                 , SUM(A.BLOCK_QTY)          AS HOLD_QTY
                 , SUM(A.PACKING_QTY)        AS PACKING_QTY
                 , SUM(A.MOVING_QTY)         AS MOVING_QTY
                 , SUM(A.RCVLOC_QTY)         AS RECEIVING_QTY
                 , SUM(A.EXPIRATION_QTY)     AS EXPIRATION_QTY
                 , SUM(A.LONG_QTY)           AS LONG_TERM_QTY
              FROM SSP_ANL_OWMS_STOCK_C A
                 , SCM_MST_SLOC B
                 , SSP_MST_MODEL_USER M
             WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
               AND B.STORAGE_ID(+)  = A.STORAGE_ID
               AND B.PLANT_ID(+)    = A.PLANT_ID
               AND M.DIVISION_ID(+) = A.DIVISION_ID
               AND M.FROM_SITE(+)   = A.FROM_SITE
               AND M.ITEM_ID(+)     = A.ITEM_ID
               AND M.VALID_YN(+)    = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_PLAN_SEQ
               AND A.FROM_SITE           = P_FROM_SITE
               --AND A.ITEM_ID             = P_ITEM_ID
               AND A.ITEM_ID             = UPPER(P_ITEM_ID)   -- 2026.09.17 AJS
             GROUP BY A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC
                 , A.PLANT_ID
                 , A.DIVISION_ID
                 , A.STORAGE_ID
                 , B.STORAGE_DESCRIPTION
             ORDER BY A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC;

            /* 1. 셀 더블클릭 - W/H Stock Detail */
            OPEN O_RC2 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , A.GRADE
                         , A.CAPACITY_GRADE     AS CAPA_GRADE
                         , A.SOC
                         , A.LOT_ID
                         , A.PALLET_ID
                         , A.STOCK_QTY
                         , A.AVAILABLE_QTY
                         , A.NON_QC_QTY         AS UNDECIDED_QTY
                         , A.ALLOCATION_QTY
                         --, A.BLOCK_QTY          AS HOLD_QTY
                         , A.BLOCK_QTY          AS "Hold_Qty"   /* AS-IS 칸 이름 Hold_Qty 유지 */   -- 2026.09.17 AJS
                         , A.PACKING_QTY
                         , A.MOVING_QTY
                         , A.RCVLOC_QTY         AS RECEIVING_QTY
                         , A.EXPIRATION_QTY
                         , A.LONG_QTY           AS LONG_TERM_QTY
                         , A.PLANT_ID
                         , A.PACKING_STATUS
                         , A.STOCK_STATUS
                         , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                         , A.CUSTOMER_CODE
                         , A.CUSTOMER_NAME
                         , CASE WHEN REGEXP_LIKE(A.LOT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.LOT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                           END AS LOT_ISSUE_DATE
                      FROM SSP_ANL_OWMS_STOCK_C A
                         , SCM_MST_SLOC B
                         , SSP_MST_MODEL_USER M
                     WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND B.STORAGE_ID(+)  = A.STORAGE_ID
                       AND B.PLANT_ID(+)    = A.PLANT_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.FROM_SITE
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID         = P_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = P_PLAN_TYPE
                       AND A.SEQ                 = P_PLAN_SEQ
                       AND A.FROM_SITE           = P_FROM_SITE
                       --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                       AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                             --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                             OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                   ) IA
             ORDER BY IA.DIVISION_ID
                 , IA.PLANT_ID
                 , IA.STORAGE_ID
                 , IA.ITEM_ID
                 , IA.GRADE
                 , IA.CAPA_GRADE
                 , IA.SOC
                 , IA.LOT_ID
                 , IA.PALLET_ID;

        ELSE

            /* 2. btnSearch - W/H Stock */
            OPEN O_RC1 FOR
            SELECT A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                 , A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE          AS CAPA_GRADE
                 , A.SOC
                 , SUM(A.STOCK_QTY)          AS STOCK_QTY
                 , SUM(A.AVAILABLE_QTY)      AS AVAILABLE_QTY
                 , SUM(A.NON_QC_QTY)         AS UNDECIDED_QTY
                 , SUM(A.ALLOCATION_QTY)     AS ALLOCATION_QTY
                 , SUM(A.BLOCK_QTY)          AS HOLD_QTY
                 , SUM(A.PACKING_QTY)        AS PACKING_QTY
                 , SUM(A.MOVING_QTY)         AS MOVING_QTY
                 , SUM(A.RCVLOC_QTY)         AS RECEIVING_QTY
                 , SUM(A.EXPIRATION_QTY)     AS EXPIRATION_QTY
                 , SUM(A.LONG_QTY)           AS LONG_TERM_QTY
              FROM SSP_ANL_OWMS_STOCK_C A
                 , SCM_MST_SLOC B
                 , SSP_MST_MODEL_USER M
             WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
               AND B.STORAGE_ID(+)  = A.STORAGE_ID
               AND B.PLANT_ID(+)    = A.PLANT_ID
               AND M.DIVISION_ID(+) = A.DIVISION_ID
               AND M.FROM_SITE(+)   = A.FROM_SITE
               AND M.ITEM_ID(+)     = A.ITEM_ID
               AND M.VALID_YN(+)    = 'Y'
               AND A.DIVISION_ID         = P_DIVISION_ID
               AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
               AND A.PLAN_TYPE           = P_PLAN_TYPE
               AND A.SEQ                 = P_PLAN_SEQ
               --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
               AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                     OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
               --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
               AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                     --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                     OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
               /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
               AND ((P_NONCHK = 'Y' AND 1 = 1)
                     OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                       UNION
                                      SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                        FROM SSP_MST_DELEGATE
                                       WHERE VALID_YN = 'Y'
                                         AND DELEGATEE_ID = P_USER_ID
                                       GROUP BY USER_ID)
                     OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                     OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
               /* 체크박스 체크 여부 조회 끝 */
             GROUP BY A.ITEM_ID
                 , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID)
                 , A.STOCK_STATUS
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC
                 , A.PLANT_ID
                 , A.DIVISION_ID
                 , A.STORAGE_ID
                 , B.STORAGE_DESCRIPTION
             ORDER BY A.DIVISION_ID
                 , A.PLANT_ID
                 , A.STORAGE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , A.CAPACITY_GRADE
                 , A.SOC;

            /* 2. btnSearch - W/H Stock Detail */
            OPEN O_RC2 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                         , A.GRADE
                         , A.CAPACITY_GRADE     AS CAPA_GRADE
                         , A.SOC
                         , A.LOT_ID
                         , A.PALLET_ID
                         , A.STOCK_QTY
                         , A.AVAILABLE_QTY
                         , A.NON_QC_QTY         AS UNDECIDED_QTY
                         , A.ALLOCATION_QTY
                         --, A.BLOCK_QTY          AS HOLD_QTY
                         , A.BLOCK_QTY          AS "Hold_Qty"   /* AS-IS 칸 이름 Hold_Qty 유지 */   -- 2026.09.17 AJS
                         , A.PACKING_QTY
                         , A.MOVING_QTY
                         , A.RCVLOC_QTY         AS RECEIVING_QTY
                         , A.EXPIRATION_QTY
                         , A.LONG_QTY           AS LONG_TERM_QTY
                         , A.PLANT_ID
                         , A.PACKING_STATUS
                         , A.STOCK_STATUS
                         , A.STORAGE_ID || ' ' || B.STORAGE_DESCRIPTION AS STORAGE_ID
                         , A.CUSTOMER_CODE
                         , A.CUSTOMER_NAME
                         , CASE WHEN REGEXP_LIKE(A.LOT_DATE, '^[0-9]{8}$')
                                THEN TO_CHAR(TO_DATE(A.LOT_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                           END AS LOT_ISSUE_DATE
                      FROM SSP_ANL_OWMS_STOCK_C A
                         , SCM_MST_SLOC B
                         , SSP_MST_MODEL_USER M
                     WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                       AND B.STORAGE_ID(+)  = A.STORAGE_ID
                       AND B.PLANT_ID(+)    = A.PLANT_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.FROM_SITE
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID         = P_DIVISION_ID
                       AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                       AND A.PLAN_TYPE           = P_PLAN_TYPE
                       AND A.SEQ                 = P_PLAN_SEQ
                       --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                       AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                             OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                       --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                       AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                             --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                             OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                       /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                       /* 체크박스 체크 여부 조회 끝 */
                   ) IA
             ORDER BY IA.DIVISION_ID
                 , IA.PLANT_ID
                 , IA.STORAGE_ID
                 , IA.ITEM_ID
                 , IA.GRADE
                 , IA.CAPA_GRADE
                 , IA.SOC
                 , IA.LOT_ID
                 , IA.PALLET_ID;

        END IF;

    END P_SSP0015_GET_WH_STOCK;

    /* ============================================================
       P_SSP0015_GET_MES_STOCK
       AS-IS SSP0015_GET_MES_STOCK
       ※ AS-IS SUBSTRING(LOT_ID, 0, 9) 는 8자다. Oracle SUBSTR(x,0,9) 는 9자라
          SUBSTR(LOT_ID, 1, 8) 로 옮긴다.
       ============================================================ */
    PROCEDURE P_SSP0015_GET_MES_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_LOT_ID                IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   @ PKG_SSP0015.P_SSP0015_GET_MES_STOCK
         * Description  @ MES Stock
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2019/10/24   AYJ				MES Stock 시트 조회
         * 2019/01/06   KIMYHONGHO		[]MES Sotck 시트 운영 신규 적용
         * 2020/01/20   KIMYHONGHO		[C20200115-000414] MES Stock Detail 화면 개선 요청건
         * 2020/03/18   KIMYONGHO		[C20200303-000163] LONGTERM_HOLD_YN 컬럼 추가
         * 2021/07/26	KIMYONGHO       C20210708-000537 : [SCM PI팀] 재고 정합성 관련 GMES 불량 수량 GSCM 전송 요청
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT XA.ROW_NO AS "ROWNUM"   /* AS-IS 칸 이름이 ROWNUM 이라 그대로 내보낸다(Oracle 예약어라 인용부호) */
             , XA.DIVISION_ID
             , XA.FROM_SITE
             , XA.ITEM_ID
             , XA.NICK_NAME
             , XA.LOT_ID
             , XA.YYYYMMDD_LOT_ID_APPLIED_LT
             , XA.MES_CHANGE_STATUS
             , XA.LOT_TYPE
             , XA.LOT_QTY_MES
             , XA.LOT_QTY_MES_NG
             , XA.LOT_QTY_FCS
             , XA.FCS_SPECIAL_QTY
             , XA.OWMS_STOCK_QTY
             , XA.LOT_QTY_TOT
             , XA.AVAILABLE_YN
             , XA.MES_HOLD_YN
             , XA.QMS_HOLD_YN
             , XA.FCS_HOLD_YN
             , XA.LONGTERM_HOLD_YN
             , XA.JUDG_VLD_DATE
             , XA.MES_HOLD_RELEASE
             , XA.QMS_HOLD_RELEASE
             , XA.USER_MOD_RELEASE_DATE
             , XA.REMARKS
             , XA.LAST_UPDATED_BY
             , XA.LAST_UPDATE_DATE
          FROM (
                SELECT ROW_NUMBER() OVER (PARTITION BY IA.DIVISION_ID, IA.FROM_SITE, IA.ITEM_ID, IA.LOT_ID
                                              --ORDER BY IA.LOT_TYPE DESC, IA.MES_CHANGE_STATUS DESC) AS ROW_NO
                                              ORDER BY IA.LOT_TYPE DESC NULLS LAST, IA.MES_CHANGE_STATUS DESC NULLS LAST) AS ROW_NO   /* MSSQL 내림차순 NULL 뒤 */   -- 2026.09.17 AJS
                     , IA.DIVISION_ID
                     , IA.FROM_SITE
                     , IA.ITEM_ID
                     , IA.NICK_NAME
                     , IA.LOT_ID
                     , IA.YYYYMMDD_LOT_ID_APPLIED_LT
                     , IA.MES_CHANGE_STATUS
                     , IA.LOT_TYPE
                     , IA.LOT_QTY_MES
                       /* C20210708-000537 */
                     , IA.LOT_QTY_MES_NG
                     , IA.LOT_QTY_FCS
                     , IA.FCS_SPECIAL_QTY
                     , IA.OWMS_STOCK_QTY
                     , IA.LOT_QTY_TOT
                     , IA.AVAILABLE_YN
                     , IA.MES_HOLD_YN
                     , IA.QMS_HOLD_YN
                     , IA.FCS_HOLD_YN
                     , IA.LONGTERM_HOLD_YN
                     , IA.JUDG_VLD_DATE
                     , IA.MES_HOLD_RELEASE
                     , IA.QMS_HOLD_RELEASE
                     , IA.USER_MOD_RELEASE_DATE
                     , IA.REMARKS
                     , IA.LAST_UPDATED_BY
                     , IA.LAST_UPDATE_DATE
                  FROM (
                        SELECT X.DIVISION_ID
                             , X.FROM_SITE
                             , X.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(X.DIVISION_ID, X.ITEM_ID) AS NICK_NAME
                             , X.LOT_ID                             AS LOT_ID
                             , CASE WHEN REGEXP_LIKE(X.YYYYMMDD_LOT_ID_APPLIED_LT, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.YYYYMMDD_LOT_ID_APPLIED_LT, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS YYYYMMDD_LOT_ID_APPLIED_LT
                             , X.CHANGE_STATUS                      AS MES_CHANGE_STATUS
                             , X.LOT_TYPE
                             , X.LOT_QTY_MES
                               /* C20210708-000537 */
                               /* ATTRIBUTE4 는 VARCHAR2 다. AS-IS 는 UNION 타입 우선순위로 정수가 되므로 숫자로 맞춘다.
                                  원장 칸이라 이관 채움값이 섞여도 조회가 끊기지 않게 방어 변환을 둔다. */
                             , NVL(TO_NUMBER(X.ATTRIBUTE4 DEFAULT NULL ON CONVERSION ERROR), 0) AS LOT_QTY_MES_NG   /* 불량수량 */
                             , X.LOT_QTY_FCS
                             , X.FCS_SPECIAL_QTY
                             , X.OWMS_STOCK_QTY
                             , X.LOT_QTY_TOT                        AS LOT_QTY_TOT
                             , X.AVAILABLE_YN
                             , X.MES_HOLD_YN
                             , X.QMS_HOLD_YN
                             , X.FCS_HOLD_YN
                             , X.LONGTERM_HOLD_YN
                             , CASE WHEN REGEXP_LIKE(X.JUDG_VLD_DATE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.JUDG_VLD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS JUDG_VLD_DATE
                             , CASE WHEN REGEXP_LIKE(X.MES_HOLD_RELEASE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.MES_HOLD_RELEASE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS MES_HOLD_RELEASE
                             , CASE WHEN REGEXP_LIKE(X.QMS_HOLD_RELEASE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.QMS_HOLD_RELEASE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS QMS_HOLD_RELEASE
                             , CASE WHEN REGEXP_LIKE(X.USER_MOD_RELEASE_DATE, '^[0-9]{8}$')
                                    THEN TO_CHAR(TO_DATE(X.USER_MOD_RELEASE_DATE, 'YYYYMMDD'), 'YYYY-MM-DD')
                               END                                  AS USER_MOD_RELEASE_DATE
                             , X.REMARKS
                             /* 2026.09.30 AJS 수정 (START) */
                           --, CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) IS NULL THEN NULL
                                  --ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || X.LAST_UPDATED_BY || ')'
                             , CASE WHEN (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NULL THEN NULL
                                    ELSE (CASE WHEN P_LANGUAGE = 'KO' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || X.LAST_UPDATED_BY || ')'
                             /* 2026.09.30 AJS 수정 (END) */
                               END                                  AS LAST_UPDATED_BY
                             , X.LAST_UPDATE_DATE
                          FROM SSP_ANL_MES_FCS_STOCK_40_C X
                             /* 2026.09.30 AJS 수정 (START) */
                           --, TB_FX_USER U
                             , SCM_ADM_USER_M U
                             /* 2026.09.30 AJS 수정 (END) */
                             , SSP_MST_MODEL_USER M
                         /* 2026.09.30 AJS 수정 (START) */
                       --WHERE X.LAST_UPDATED_BY = U.USERID(+)
                         --AND U.USEYN(+)        = 'Y'
                         WHERE X.LAST_UPDATED_BY = U.USER_ID(+)
                           AND U.USE_YN(+)        = 'Y'
                         /* 2026.09.30 AJS 수정 (END) */
                           AND M.DIVISION_ID(+)  = X.DIVISION_ID
                           AND M.FROM_SITE(+)    = X.FROM_SITE
                           AND M.ITEM_ID(+)      = X.ITEM_ID
                           AND M.VALID_YN(+)     = 'Y'
                           AND X.DIVISION_ID         = P_DIVISION_ID
                           AND X.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND X.PLAN_TYPE           = 'SP'
                           AND X.SEQ                 = 1
                           --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                           AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                                 OR X.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                           --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                           AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                                 --OR X.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                                 OR X.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                           --AND ((P_LOT_ID IS NULL OR P_LOT_ID = '')
                           AND ((TRIM(P_LOT_ID) IS NULL)   -- 2026.09.17 AJS
                                 --OR X.LOT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))
                                 OR X.LOT_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))   -- 2026.09.17 AJS
                           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' @ 체크박스 선택 안한 상태) */
                           AND ((P_NONCHK = 'Y' AND 1 = 1)
                                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                   UNION
                                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                    FROM SSP_MST_DELEGATE
                                                   WHERE VALID_YN = 'Y'
                                                     AND DELEGATEE_ID = P_USER_ID
                                                   GROUP BY USER_ID)
                                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                        /* [C20200115-000414] OWMS 조회 부분 추가 */
                        UNION ALL
                        SELECT A.DIVISION_ID
                             , A.FROM_SITE
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                             , SUBSTR(A.LOT_ID, 1, 8)   AS LOT_ID
                             , NULL                     AS YYYYMMDD_LOT_ID_APPLIED_LT
                             , NULL                     AS MES_CHANGE_STATUS
                             , NULL                     AS LOT_TYPE
                             , 0                        AS LOT_QTY_MES
                               /* C20210708-000537 */
                             , 0                        AS LOT_QTY_MES_NG
                             , 0                        AS LOT_QTY_FCS
                             , 0                        AS FCS_SPECIAL_QTY
                             , SUM(A.STOCK_QTY)         AS OWMS_STOCK_QTY
                             , 0                        AS LOT_QTY_TOT
                             , '-'                      AS AVAILABLE_YN
                             , '-'                      AS MES_HOLD_YN
                             , '-'                      AS QMS_HOLD_YN
                             , '-'                      AS FCS_HOLD_YN
                             , '-'                      AS LONGTERM_HOLD_YN
                             , NULL                     AS JUDG_VLD_DATE
                             , NULL                     AS MES_HOLD_RELEASE
                             , NULL                     AS QMS_HOLD_RELEASE
                             , NULL                     AS USER_MOD_RELEASE_DATE
                             , NULL                     AS REMARKS
                             , NULL                     AS LAST_UPDATED_BY
                             , NULL                     AS LAST_UPDATE_DATE
                          FROM SSP_ANL_OWMS_STOCK_C A
                             , SCM_MST_SLOC B
                             , SSP_MST_MODEL_USER M
                         WHERE B.DIVISION_ID(+) = CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END
                           AND B.STORAGE_ID(+)  = A.STORAGE_ID
                           AND B.PLANT_ID(+)    = A.PLANT_ID
                           AND M.DIVISION_ID(+) = A.DIVISION_ID
                           AND M.FROM_SITE(+)   = A.FROM_SITE
                           AND M.ITEM_ID(+)     = A.ITEM_ID
                           AND M.VALID_YN(+)    = 'Y'
                           AND A.DIVISION_ID         = P_DIVISION_ID
                           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
                           AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                                 OR A.FROM_SITE IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
                           --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                           AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                                 --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                           --AND ((P_LOT_ID IS NULL OR P_LOT_ID = '')
                           AND ((TRIM(P_LOT_ID) IS NULL)   -- 2026.09.17 AJS
                                 --OR A.LOT_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))
                                 OR A.LOT_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_LOT_ID, ','))))   -- 2026.09.17 AJS
                           AND ((P_NONCHK = 'Y' AND 1 = 1)
                                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                                   UNION
                                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                    FROM SSP_MST_DELEGATE
                                                   WHERE VALID_YN = 'Y'
                                                     AND DELEGATEE_ID = P_USER_ID
                                                   GROUP BY USER_ID)
                                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                         GROUP BY A.DIVISION_ID
                             , A.ORIGIN_FROM_DIVISION_ID
                             , A.FROM_SITE
                             , A.ITEM_ID
                             , SUBSTR(A.LOT_ID, 1, 8)
                       ) IA
               ) XA
         WHERE XA.ROW_NO = 1
         ORDER BY XA.DIVISION_ID
             , XA.ITEM_ID
             , XA.LOT_ID
             --, XA.MES_CHANGE_STATUS DESC;
             , XA.MES_CHANGE_STATUS DESC NULLS LAST;   -- 2026.09.17 AJS

    END P_SSP0015_GET_MES_STOCK;

    /* ============================================================
       P_SSP0015_GET_SCS_STOCK
       AS-IS SSP0015_GET_SCS_STOCK
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SCS_STOCK
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   @ PKG_SSP0015.P_SSP0015_GET_SCS_STOCK
         * Description  @ MES Stock
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021-10-20   KIMYONGHO		신규추가
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         */
        V_CUTOFF_DATE   VARCHAR2(8 CHAR);
    BEGIN

        /* AS-IS : CONVERT(CHAR(8), DATEADD(DD, -2, ...), 112) - 계획기준일 -2일 */
        V_CUTOFF_DATE := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 2, 'YYYYMMDD');

        OPEN O_RC1 FOR
        SELECT A.DIVISION_ID
             , A.CUTOFF_DATE
             , A.SCM_SITE_ID                        AS PLANT_ID
             , B.SITE_DESCRIPTION                   AS PLANT_NAME
             , A.ITEM_ID                            AS MODEL_ID
             , TO_CHAR(TO_DATE(A.STOCK_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS PROD_DATE
             , '-'                                  AS HOLD_YN
             , A.STOCK_QTY                          AS QTY
             , A.LAST_UPDATE_DATE
          FROM SCM_DNM_SCS_STOCK A
             , SCM_MST_SITE B
             , SSP_MST_MODEL_USER M
         WHERE A.DIVISION_ID   = B.DIVISION_ID
           AND A.SCM_SITE_ID   = B.SCM_SITE_ID
           AND M.DIVISION_ID(+) = A.DIVISION_ID
           AND M.FROM_SITE(+)   = A.SCM_SITE_ID
           AND M.ITEM_ID(+)     = A.ITEM_ID
           AND M.VALID_YN(+)    = 'Y'
           AND A.DIVISION_ID   = '40'
           AND A.CUTOFF_DATE   = V_CUTOFF_DATE
           AND A.CELL_PACK     = 'P'
           --AND ((P_FROM_SITE IS NULL OR P_FROM_SITE = '')
           AND ((TRIM(P_FROM_SITE) IS NULL)   -- 2026.09.17 AJS
                 OR A.SCM_SITE_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_FROM_SITE, ','))))
           --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
           AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                 --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                 OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
           /* 체크박스 체크 여부 조회 시작(P_NONCHK = 'Y' : 체크박스 선택 안한 상태) */
           AND ((P_NONCHK = 'Y' AND 1 = 1)
                 OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                   UNION
                                  SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                    FROM SSP_MST_DELEGATE
                                   WHERE VALID_YN = 'Y'
                                     AND DELEGATEE_ID = P_USER_ID
                                   GROUP BY USER_ID)
                 OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                 OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
           /* 체크박스 체크 여부 조회 끝 */
         ORDER BY A.SCM_SITE_ID
             , A.ITEM_ID;

    END P_SSP0015_GET_SCS_STOCK;

    /* ============================================================
       P_SSP0015_GET_STOCK_LOCATION_DETAIL
       AS-IS SSP0015_GET_STOCK_LOCATION_DETAIL
       ※ AS-IS 의 @MST_LOCATION 테이블변수는 채우기만 하고 조인이 전부 주석 처리돼 있어
          결과에 영향을 주지 않는다. 옮기지 않는다.
       ※ SCM_DNM_STOCK_V.CUTOFF_DATE 는 Oracle 에서 DATE 다. 암시적 형변환을 막기 위해
          --비교값을 TO_DATE 로 맞추고, 결과 칸은 AS-IS 표기(YYYYMMDD)로 돌려준다.
          비교값을 TO_DATE 로 맞추고, 결과 칸은 AS-IS 와 같이 날짜형 그대로 돌려준다.   -- 2026.09.17 AJS
       ============================================================ */
    PROCEDURE P_SSP0015_GET_STOCK_LOCATION_DETAIL
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_COMPANY_ID            IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_PLAN_START_YYYYMMDD   IN  VARCHAR2,
        P_DBL_FLAG              IN  VARCHAR2,
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_PROGRAM_ID            IN  VARCHAR2 DEFAULT 'SSP0015',
        P_SHEET_NAME            IN  VARCHAR2 DEFAULT 'Stock Location Detail',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'T',
        P_USER_ID               IN  VARCHAR2,
        P_MYMODELCHK            IN  VARCHAR2,
        P_PARTLEADERCHK         IN  VARCHAR2,
        P_TEAMLEADERCHK         IN  VARCHAR2,
        P_DELEGATEECHK          IN  VARCHAR2,
        P_NONCHK                IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_STOCK_LOCATION_DETAIL
         * Description  : 소형 외주 Packer
         * Program History
         *===================================================================================================
         *   Date       In Charge		Description
         *===================================================================================================
         * 2021-09-28   KIMYONGHO	    최초작성
         * 2024-10-01   KHJ             NERP_SSP
         * 2026.09.16   AJS             MSSQL -> Oracle 전환
         */
        V_A010              VARCHAR2(10 CHAR);   /* NERP 매핑코드 */
        V_BOH_YYYYMMDD      VARCHAR2(8 CHAR);
        V_STOCK_YYYYMMDD    VARCHAR2(8 CHAR);
    BEGIN

        V_A010 := FN_GET_LOOKUP_VALUE('SSP0015_GET_STOCK_LOCATION_DETAIL', 'A010');   /* A010 */

        V_BOH_YYYYMMDD   := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD');   /* FROM -1일 */
        V_STOCK_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') - 3, 'YYYYMMDD');   /* FROM -3일 */

        IF P_DBL_FLAG = 'Y' THEN

            OPEN O_RC1 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.COMPANY_ID
                         --, TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD')   AS CUTOFF_DATE
                         , A.CUTOFF_DATE                        AS CUTOFF_DATE   /* AS-IS 는 datetime 그대로 */   -- 2026.09.17 AJS
                         , A.SCM_SITE_ID                        AS FROM_SITE
                         , A.PLANT_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                         , A.STOCK_TYPE
                         , A.STORAGE_ID
                         , NVL(B.STORAGE_DESCRIPTION,
                               (SELECT MIN(SA.STORAGE_DESCRIPTION)
                                  FROM SCM_MST_SLOC SA
                                 WHERE SA.PLANT_ID   = A.PLANT_ID
                                   AND SA.STORAGE_ID = A.STORAGE_ID
                                   AND SA.VALID_YN   = 'Y')) AS STORAGE_DESCRIPTION
                         , NVL(A.SCM_QTY, 0)                    AS TOTAL_QTY
                         , NVL(A.SSP_QTY, 0)                    AS AVAILABLE_QTY
                         , A.DEFECT_QTY
                         , A.MOVING_QTY
                         , A.QTY_UOM
                         , NVL(A.WIPHOLD_YN, 'N')               AS WIPHOLD_YN
                         , A.HOLDING_DATE
                         , A.AVAILABLE_DATE
                         , A.OUTSOURCING_FLAG
                         , A.OUTSOURCING_FACTORY
                      FROM SCM_DNM_STOCK_V A
                         , SCM_MST_SLOC B
                         , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME
                              FROM SCM_MST_ITEM_SN
                             WHERE DIVISION_ID = P_DIVISION_ID
                               AND ACTIVE_FLAG = 'Y'
                               AND SCP_OPERATION_GROUP = 'P'   /* CELL/PACK 구분 */
                           ) C
                         , SSP_MST_MODEL_USER M
                     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
                       AND A.PLANT_ID      = B.PLANT_ID(+)
                       AND A.STORAGE_ID    = B.STORAGE_ID(+)
                       AND A.DIVISION_ID   = C.DIVISION_ID
                       AND A.ITEM_ID       = C.ITEM_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.SCM_SITE_ID
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND A.COMPANY_ID  = P_COMPANY_ID
                       AND A.SCM_SITE_ID = P_FROM_SITE
                       AND A.ITEM_ID     = P_ITEM_ID
                       AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                       AND A.CUTOFF_DATE > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')   /* 현재일 - 3 */
                       AND A.STOCK_TYPE  = 'INVENTORY'
                       AND A.PLANT_ID    = V_A010   /* 'A010' */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) IA
             ORDER BY IA.COMPANY_ID
                 , IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PLANT_ID
                 , IA.ITEM_ID
                 , IA.STOCK_TYPE
                 , IA.STORAGE_ID;

        ELSE

            OPEN O_RC1 FOR
            SELECT IA.*
              FROM (
                    SELECT A.DIVISION_ID
                         , A.COMPANY_ID
                         --, TO_CHAR(A.CUTOFF_DATE, 'YYYYMMDD')   AS CUTOFF_DATE
                         , A.CUTOFF_DATE                        AS CUTOFF_DATE   /* AS-IS 는 datetime 그대로 */   -- 2026.09.17 AJS
                         , A.SCM_SITE_ID                        AS FROM_SITE
                         , A.PLANT_ID
                         , A.ITEM_ID
                         , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                         , A.STOCK_TYPE
                         , A.STORAGE_ID
                         , NVL(B.STORAGE_DESCRIPTION,
                               (SELECT MIN(SA.STORAGE_DESCRIPTION)
                                  FROM SCM_MST_SLOC SA
                                 WHERE SA.PLANT_ID   = A.PLANT_ID
                                   AND SA.STORAGE_ID = A.STORAGE_ID
                                   AND SA.VALID_YN   = 'Y')) AS STORAGE_DESCRIPTION
                         , NVL(A.SCM_QTY, 0)                    AS TOTAL_QTY
                         , NVL(A.SSP_QTY, 0)                    AS AVAILABLE_QTY
                         , A.DEFECT_QTY
                         , A.MOVING_QTY
                         , A.QTY_UOM
                         , NVL(A.WIPHOLD_YN, 'N')               AS WIPHOLD_YN
                         , A.HOLDING_DATE
                         , A.AVAILABLE_DATE
                         , A.OUTSOURCING_FLAG
                         , A.OUTSOURCING_FACTORY
                      FROM SCM_DNM_STOCK_V A
                         , SCM_MST_SLOC B
                         , (SELECT DISTINCT DIVISION_ID, ITEM_ID, NICK_NAME
                              FROM SCM_MST_ITEM_SN
                             WHERE DIVISION_ID = P_DIVISION_ID
                               AND ACTIVE_FLAG = 'Y'
                               AND SCP_OPERATION_GROUP = 'P'   /* CELL/PACK 구분 */
                           ) C
                         , SSP_MST_MODEL_USER M
                     WHERE A.DIVISION_ID   = B.DIVISION_ID(+)
                       AND A.PLANT_ID      = B.PLANT_ID(+)
                       AND A.STORAGE_ID    = B.STORAGE_ID(+)
                       AND A.DIVISION_ID   = C.DIVISION_ID
                       AND A.ITEM_ID       = C.ITEM_ID
                       AND M.DIVISION_ID(+) = A.DIVISION_ID
                       AND M.FROM_SITE(+)   = A.SCM_SITE_ID
                       AND M.ITEM_ID(+)     = A.ITEM_ID
                       AND M.VALID_YN(+)    = 'Y'
                       AND A.DIVISION_ID = P_DIVISION_ID
                       AND A.COMPANY_ID  = P_COMPANY_ID
                       --AND ((P_ITEM_ID IS NULL OR P_ITEM_ID = '')
                       AND ((TRIM(P_ITEM_ID) IS NULL)   -- 2026.09.17 AJS
                             --OR A.ITEM_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))
                             OR A.ITEM_ID IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_ITEM_ID, ','))))   -- 2026.09.17 AJS
                       AND A.CUTOFF_DATE = TO_DATE(V_BOH_YYYYMMDD, 'YYYYMMDD')
                       AND A.CUTOFF_DATE > TO_DATE(V_STOCK_YYYYMMDD, 'YYYYMMDD')   /* 현재일 - 3 */
                       AND A.STOCK_TYPE  = 'INVENTORY'
                       AND A.PLANT_ID    = V_A010   /* 'A010' */
                       AND ((P_NONCHK = 'Y' AND 1 = 1)
                             OR M.USER_ID IN (SELECT CASE WHEN P_MYMODELCHK = 'Y' THEN P_USER_ID ELSE 'X' END FROM DUAL
                                               UNION
                                              SELECT CASE WHEN P_DELEGATEECHK = 'Y' THEN USER_ID ELSE 'X' END
                                                FROM SSP_MST_DELEGATE
                                               WHERE VALID_YN = 'Y'
                                                 AND DELEGATEE_ID = P_USER_ID
                                               GROUP BY USER_ID)
                             OR M.PART_LEADER = CASE WHEN P_PARTLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END
                             OR M.TEAM_LEADER = CASE WHEN P_TEAMLEADERCHK = 'Y' THEN P_USER_ID ELSE 'X' END)
                   ) IA
             ORDER BY IA.COMPANY_ID
                 , IA.DIVISION_ID
                 , IA.FROM_SITE
                 , IA.PLANT_ID
                 , IA.ITEM_ID
                 , IA.STOCK_TYPE
                 , IA.STORAGE_ID;

        END IF;

    END P_SSP0015_GET_STOCK_LOCATION_DETAIL;

    /* ============================================================
       P_SSP0015_GET_ERP_SO_NO_CNT
       AS-IS SSP0015_GET_ERP_SO_NO_CNT
       ============================================================ */
    PROCEDURE P_SSP0015_GET_ERP_SO_NO_CNT
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_ERP_SO_NO             IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_ERP_SO_NO_CNT
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2024/06/04   jilee          UI 수량 표기 안되는 정보에 대한 제외 처리
         * 2026.09.16   AJS            MSSQL -> Oracle 전환
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT COUNT(*) AS CNT
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE DIVISION_ID = P_DIVISION_ID
           AND ERP_SO_NO   = P_ERP_SO_NO
           AND QTY        <> 0;

    END P_SSP0015_GET_ERP_SO_NO_CNT;

    /* ============================================================
       P_SSP0015_GET_SHIPMENT_STATUS
       AS-IS SSP0015_GET_SHIPMENT_STATUS - 결과셋 3벌
       ============================================================ */
    PROCEDURE P_SSP0015_GET_SHIPMENT_STATUS
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_CONFIRM_ID            IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR,
        O_RC2                   OUT SYS_REFCURSOR,
        O_RC3                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : PKG_SSP0015.P_SSP0015_GET_SHIPMENT_STATUS
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2018/10/12   ygkim          Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
         * 2020/07/15   khj79          ERP_STATUS 가 'C' 인 경우 수정 못하도록 추가
         * 2026.09.16   AJS            MSSQL -> Oracle 전환 (String_Split -> FN_STRING_SPLIT)
         *
         ex) EXEC PKG_SSP0015.P_SSP0015_GET_SHIPMENT_STATUS('40^40', 'C20181001068349^C20181005074232', ...)
         */
    BEGIN

        OPEN O_RC1 FOR
        SELECT CONFIRM_ID
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           --AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND CONFIRM_ID  IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))   -- 2026.09.17 AJS
           AND SHIPMENT_STATUS != 'C';

        OPEN O_RC2 FOR
        SELECT CONFIRM_ID
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           --AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND CONFIRM_ID  IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))   -- 2026.09.17 AJS
           AND QTY = 0;

        OPEN O_RC3 FOR
        SELECT CONFIRM_ID
          FROM SSP_ANL_SHIP_CONFIRM
         WHERE 1 = 1
           AND DIVISION_ID IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_DIVISION_ID, '^')))
           --AND CONFIRM_ID  IN (SELECT TOKEN FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))
           AND CONFIRM_ID  IN (SELECT UPPER(TOKEN) FROM TABLE(FN_STRING_SPLIT(P_CONFIRM_ID, '^')))   -- 2026.09.17 AJS
           AND ERP_STATUS = 'C';

    END P_SSP0015_GET_SHIPMENT_STATUS;

END PKG_ZTMP_S015K;
/
SHOW ERRORS PACKAGE BODY PKG_ZTMP_S015K
-- ##### END PACKAGE BODY PKG_ZTMP_S015K

-- ##### START PACKAGE BODY PKG_ZTMP_S200B
CREATE OR REPLACE PACKAGE BODY PKG_ZTMP_S200B
IS
    FUNCTION FN_MKT_OWNER_FIX
(
    P_OWNER     IN VARCHAR2,
    P_DELIM     IN VARCHAR2,
    P_LANGUAGE  IN VARCHAR2
)
RETURN CLOB
IS
    /*
     * Program ID   : FN_GET_SSP_MKT_OWNER_NAME
     * Description  : PROJECT OWNER
     *
     *
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2018.11.01   juhlee     Initial Release [PJ20182279] 전지본부 출하계획 시스템 구축 프로젝트
     * 2026.03.06   jcnam          [PJ20264226] NextSCM Pilot 설계 및 개발
     * 2026.09.17   AJS            AS-IS 결과 일치 보정 (대소문자 무시 조회 · 미존재 처리 · NULL 전파 · 인덱스 조회)
     */
    V_OWNER     VARCHAR2(32767) := P_OWNER;
    V_DELIM     VARCHAR2(1)     := SUBSTR(P_DELIM, 1, 1);          /* AS-IS @p_delim VARCHAR(1) */
    /* AS-IS @p_language NVARCHAR(2) : 앞 2자만, 대소문자·뒤 공백 무시 비교 */
    V_KO_YN     VARCHAR2(1)     := CASE WHEN UPPER(RTRIM(SUBSTR(P_LANGUAGE, 1, 2))) = 'KO' THEN 'Y' ELSE 'N' END;
    V_RESTR     VARCHAR2(32767);                                   /* AS-IS @ReStr = '' */
    V_NULL_YN   VARCHAR2(1)     := 'N';                            /* AS-IS @ReStr 가 NULL 이 됨 (NULL + 문자 = NULL) */
    V_USERNAME  VARCHAR2(4000);                                    /* AS-IS @UserName (조회 실패 시 앞 값 유지) */
    V_UNAME_YN  VARCHAR2(1)     := 'N';                            /* AS-IS @UserName 이 한 번이라도 채워졌는지 */
    V_NAME      VARCHAR2(4000);
    V_CNT       PLS_INTEGER;
    V_POS       PLS_INTEGER;

    /* AS-IS : SELECT @x = USER_NAME + '(' + USER_ID + ')' FROM SCM_MST_SSO_USER_INFO WHERE USER_ID = @id (대소문자 무시) */
    PROCEDURE P_FIND(P_ID IN VARCHAR2)
    IS
    BEGIN
        SELECT MAX(CASE WHEN V_KO_YN = 'Y' THEN USER_NAME ELSE USER_NAME_EN END || '(' || USER_ID || ')')
             , COUNT(*)
          INTO V_NAME
             , V_CNT
          FROM SCM_MST_SSO_USER_INFO
         WHERE UPPER(USER_ID) = UPPER(P_ID);
    END P_FIND;

BEGIN

    V_POS := INSTR(V_OWNER, V_DELIM);

    IF V_POS <> 0 THEN

        WHILE V_POS > 0 LOOP

            P_FIND(TRIM(SUBSTR(V_OWNER, 1, V_POS - 1)));

            IF V_CNT > 0 THEN
                V_USERNAME := V_NAME;
                V_UNAME_YN := 'Y';
            END IF;

            /* AS-IS : SET @ReStr = LTRIM(RTRIM(@ReStr)) + @UserName + ',' */
            IF V_UNAME_YN = 'N' THEN
                V_NULL_YN := 'Y';
            ELSE
                V_RESTR := TRIM(V_RESTR) || V_USERNAME || ',';
            END IF;

            /* AS-IS : SUBSTRING(@p_owner, @FoundIdx + 1, LEN(@p_owner) - @FoundIdx) - LEN 은 뒤 공백 제외 */
            V_OWNER := SUBSTR(V_OWNER, V_POS + 1, LENGTH(RTRIM(V_OWNER)) - V_POS);
            V_POS   := NVL(INSTR(V_OWNER, V_DELIM), 0);

        END LOOP;

        P_FIND(TRIM(V_OWNER));

        IF V_CNT > 0 THEN
            V_RESTR := V_RESTR || V_NAME;
        END IF;

    ELSE

        P_FIND(TRIM(V_OWNER));

        IF V_CNT > 0 THEN
            V_RESTR := V_NAME;
        END IF;

    END IF;

    IF V_NULL_YN = 'Y' THEN
        RETURN NULL;
    END IF;

    RETURN TO_CLOB(V_RESTR);

END FN_MKT_OWNER_FIX;

    /* ==== P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST / SSP0200_GET_SHIPMENT_CHANGE_REQUEST ==== */
    /* ============================================================
       ※ AS-IS 는 FN_GET_IN_STR 로 IN 리스트를 만들어 EXEC 로 돌린다.
          선택조건 조립뿐이라 정적 SQL 로 옮겼다.
       ※ IN 리스트는 FN_GET_IN_STR 규칙을 그대로 옮긴 내부 함수(FN_IN_LIST)로 나눈다.
          (줄바꿈 → 쉼표, 조각 앞뒤 공백 제거, 조각 100자 절삭, 1,000조각 한도,
           AS-IS FN_SCM_SPLIT 의 「조각 번호 위치부터 구분자 탐색」 규칙 포함)
       ※ MSSQL 정렬(Latin1_General_CI_AS) : 비교는 대소문자 무시, 정렬은 대소문자·하이픈 무시
          · 밑줄은 글자·숫자보다 앞 → 조건·조인·정렬에 UPPER / TRANSLATE 반영
       ============================================================ */
    PROCEDURE P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ERP_SO_NO             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_STATUS                IN  VARCHAR2,
        P_CHANGE_TYPE           IN  VARCHAR2 DEFAULT 'C',
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_TO_SITE               IN  VARCHAR2 DEFAULT NULL,
        P_CONFIRM_ID            IN  VARCHAR2,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : SSP0200_GET_SHIPMENT_CHANGE_REQUEST
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2021/05/25   KIMYONGHO      최초작성
         * 2021/10/18   SHINMYUNGSU	   SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
         * 2021/11/11   SHINMYUNGSU    조회조건 CONFIRM_ID 추가
         * 2024/10/01   KHJ            NERP_SSP
         * 2025/12/11   chkim.68       E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
         * 2026.09.17   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         *
         ex) PKG_SSP0200.P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST('40', '', '', '', '20260801', '20260831', '', 'C', 'KO', 'F', '', '', :RC)
         */
        V_DIV_TAB       T_STR_TAB;
        V_FROM_TAB      T_STR_TAB;
        V_ITEM_TAB      T_STR_TAB;
        V_TO_TAB        T_STR_TAB;
        V_SO_TAB        T_STR_TAB;
        V_CONFIRM_TAB   T_STR_TAB;

        V_DIV_CNT       PLS_INTEGER;
        V_FROM_CNT      PLS_INTEGER;
        V_ITEM_CNT      PLS_INTEGER;
        V_TO_CNT        PLS_INTEGER;
        V_SO_CNT        PLS_INTEGER;
        V_CONFIRM_CNT   PLS_INTEGER;

        V_LANG_KO       VARCHAR2(1);
        V_OWNER_LANG    VARCHAR2(2);
        V_RUN_YN        VARCHAR2(1);

        /* AS-IS FN_GET_IN_STR 대응 : 결과 조각을 대문자로 담는다(조각 0개 = 조건 없음) */
        FUNCTION FN_IN_LIST(P_STR IN VARCHAR2) RETURN T_STR_TAB
        IS
            V_LIST      VARCHAR2(32767);
            V_TAB       T_STR_TAB := T_STR_TAB();
            V_NODE      PLS_INTEGER := 1;
            V_START     PLS_INTEGER;
            V_END       PLS_INTEGER;
        BEGIN
            /* AS-IS : IF @p_csv_text_list = '' RETURN('') - MSSQL 비교는 뒤 공백 무시 */
            IF TRIM(P_STR) IS NULL THEN
                RETURN V_TAB;
            END IF;

            V_LIST := REPLACE(REPLACE(P_STR, CHR(13), ''), CHR(10), ',');

            /* AS-IS FN_SCM_SPLIT : 빈 문자열이면 조각 없음 */
            IF V_LIST IS NULL THEN
                RETURN V_TAB;
            END IF;

            WHILE V_NODE <= 1000 LOOP
                IF V_NODE = 1 THEN
                    V_START := 1;
                ELSE
                    /* AS-IS FN_SCM_SPLIT : CHARINDEX(구분자, 문자열, 조각번호) = 0 이면 끝 */
                    EXIT WHEN INSTR(V_LIST, ',', V_NODE) = 0;
                    V_START := INSTR(V_LIST, ',', 1, V_NODE - 1);
                    EXIT WHEN V_START = 0;
                    V_START := V_START + 1;
                END IF;

                V_END := INSTR(V_LIST, ',', V_START);
                IF V_END = 0 THEN
                    V_END := LENGTH(V_LIST) + 1;
                END IF;

                /* 빈 조각은 AS-IS '' → Oracle NULL (어느 값과도 같지 않음 - AS-IS 와 결과 동일) */
                V_TAB.EXTEND;
                V_TAB(V_TAB.COUNT) := UPPER(SUBSTR(TRIM(SUBSTR(V_LIST, V_START, V_END - V_START)), 1, 100));
                V_NODE := V_NODE + 1;
            END LOOP;

            RETURN V_TAB;
        END FN_IN_LIST;

    BEGIN

        /* IN 조건으로 데이터를 가져옴 */
        V_DIV_TAB     := FN_IN_LIST(P_DIVISION_ID);
        V_FROM_TAB    := FN_IN_LIST(P_FROM_SITE);
        V_ITEM_TAB    := FN_IN_LIST(P_ITEM_ID);
        V_TO_TAB      := FN_IN_LIST(P_TO_SITE);
        V_SO_TAB      := FN_IN_LIST(P_ERP_SO_NO);
        /* 20211111 SHINMYUNGSU  추가 */
        V_CONFIRM_TAB := FN_IN_LIST(P_CONFIRM_ID);

        V_DIV_CNT     := V_DIV_TAB.COUNT;
        V_FROM_CNT    := V_FROM_TAB.COUNT;
        V_ITEM_CNT    := V_ITEM_TAB.COUNT;
        V_TO_CNT      := V_TO_TAB.COUNT;
        V_SO_CNT      := V_SO_TAB.COUNT;
        V_CONFIRM_CNT := V_CONFIRM_TAB.COUNT;

        /* AS-IS : CASE WHEN '<@p_language>' = 'KO' (대소문자·뒤 공백 무시) */
        V_LANG_KO    := CASE WHEN UPPER(RTRIM(P_LANGUAGE)) = 'KO' THEN 'Y' ELSE 'N' END;
        /* AS-IS FN_GET_SSP_MKT_OWNER_NAME 의 @p_language 는 NVARCHAR(2) - 앞 2자만, 대소문자 무시 */
        V_OWNER_LANG := UPPER(SUBSTR(P_LANGUAGE, 1, 2));
        /* AS-IS : 기간이 NULL 이면 조립 문장 전체가 NULL 이 되어 결과 없음 */
        V_RUN_YN     := CASE WHEN P_FROM_YYYYMMDD IS NULL OR P_TO_YYYYMMDD IS NULL THEN 'N' ELSE 'Y' END;

        OPEN O_RC1 FOR
        SELECT AA.*
          FROM (SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.SHIPMENT_STATUS
                     , A.PROJECT_CODE
                     , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME
                     , A.FCST_TYPE
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                     , A.BEFORE_QTY
                     , ROUND(A.QTY, 3)                   AS SHIPMENT_CONFIRM_QTY    /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , A.REMARKS
                     , A.REMARKS2
                     , A.REMARKS3
                     , A.FROM_SITE
                     , SMF.OPERATION_GROUP                                          /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                     , A.TO_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                     , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                     , A.BOD_ID
                     , B.SSP_INCOTERMS                   AS INCOTERMS
                     , B.TRANSPORT_MODE
                     , B.LT_TOTAL                        AS LT_DAY
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                     , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                            ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')
                       END                               AS "Expected_Shipping_Date"
                     , A.CONFIRM_ID
                       /* AS-IS : 이름 + '(' + ID + ')' - 어느 한쪽이 NULL 이면 NULL */
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USERNAME ELSE U.USERNAME_E END) IS NOT NULL
                     , CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NOT NULL
                     /* 2026.09.30 AJS 수정 (END) */
                             AND A.LAST_UPDATED_BY IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS UPDATED_BY
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN U.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                     , CASE WHEN U.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                     /* 2026.09.30 AJS 수정 (END) */
                     , A.ERP_STATUS
                     , A.CHANGE_TYPE
                     , A.ROUTE_ID                        AS NEW_ROUTE_ID
                     , A.BOD_ID                          AS NEW_BOD_ID
                     , B.SSP_INCOTERMS                   AS NEW_INCOTERMS
                     , A.D_COUNTRY                       AS NEW_D_COUNTRY
                     , A.D_PORT_CODE                     AS NEW_D_PORT_CODE
                     , A.A_COUNTRY                       AS NEW_A_COUNTRY
                     , A.A_PORT_CODE                     AS NEW_A_PORT_CODE
                     , A.CUSTOMER_LT                     AS NEW_CUSTOMER_LT
                     , A.TO_COUNTRY                      AS NEW_TO_COUNTRY
                     , A.TO_CITY                         AS NEW_TO_CITY
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                     , B.LT_TOTAL                        AS NEW_LT_DAY
                     , B.TRANSPORT_MODE                  AS NEW_TRANSPORT_MODE
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                     , 'N'                               AS EDIT_REMARKS
                     , 'N'                               AS EDIT_MAIN
                     , NVL(A.CHECK_NEED_YN, 'N')         AS CHECK_NEED_YN
                     , NVL(CASE WHEN A.DIVISION_ID = '40'
                                THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE != '-'
                                          THEN A.PROJECT_CODE ELSE G.PROJECT_CODE END
                                WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                THEN G.PROJECT_CODE
                                ELSE F.END_CUSTOMER END, '/') AS END_CUSTOMER
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , H.CHANGE_REQ_NO
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NOT NULL
                     , CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NOT NULL
                     /* 2026.09.30 AJS 수정 (END) */
                             AND MU.USER_ID IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS MODEL_USER
                       /* 같은 담당자 반복 호출은 스칼라 서브쿼리 캐시로 줄인다 */
                     , (SELECT PKG_ZTMP_S200B.FN_MKT_OWNER_FIX(SI.OWNER, ',', V_OWNER_LANG) FROM DUAL) AS MTK_OWNER
                       /* AS-IS : a.LAST_UPDATED_BY = 'ssp_batch' (대소문자·뒤 공백 무시) */
                     , CASE WHEN UPPER(RTRIM(A.LAST_UPDATED_BY)) = 'SSP_BATCH' THEN 'System'
                            /* 2026.09.30 AJS 수정 (START) */
                          --WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USERNAME ELSE U3.USERNAME_E END) IS NOT NULL
                            WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) IS NOT NULL
                            /* 2026.09.30 AJS 수정 (END) */
                             AND A.LAST_UPDATED_BY IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USERNAME ELSE U3.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS REQUESTOR
                     , '-'                               AS CHANGE_REASON_CODE
                     , ''                                AS CHANGE_REASON_DETAIL
                     , A.ATTRIBUTE10
                     , A.LAST_UPDATE_DATE                AS REQUEST_DATE
                       /**** 20211018   SHINMYUNGSU   열람항목추가   ******************************************************/
                     , A.ERP_ATTR1
                     , A.ERP_ATTR2
                     , A.ERP_ATTR3
                       /***********************************************************************************/
                  FROM SSP_ANL_SHIP_CONFIRM A
                     , SCM_MST_ITEM_SN T                /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , SCM_MST_SITE MS
                     , SCP_MST_BOD_N_V B
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER U
                     , SCM_ADM_USER_M U
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE F
                     , (SELECT XA.DIVISION_ID
                             , XA.PROJECT_CODE
                             , XA.SCM_SITE_ID
                             , XA.ITEM_ID_U
                          FROM (SELECT DIVISION_ID
                                     , PROJECT_CODE
                                     , SCM_SITE_ID
                                     , UPPER(ITEM_ID) AS ITEM_ID_U
                                       /* AS-IS 정렬 규칙(대소문자·하이픈 무시)으로 첫 PROJECT_CODE */
                                     , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, UPPER(ITEM_ID)
                                                              ORDER BY UPPER(TRANSLATE(PROJECT_CODE, '_-', '/')) NULLS FIRST
                                                                     , PROJECT_CODE NULLS FIRST) AS NUM
                                  FROM SCM_MST_SITE_ITEM) XA
                         WHERE XA.NUM = 1) G
                     , (SELECT IA.CONFIRM_ID
                             , IA.CHANGE_REQ_NO
                          FROM (SELECT CONFIRM_ID
                                     , CHANGE_REQ_NO
                                     , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC NULLS LAST) AS NUM
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                 WHERE VALID_YN = 'Y') IA
                         WHERE IA.NUM = 1) H
                     , SSP_MST_MODEL_USER MU
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER U2
                   --, TB_FX_USER U3
                     , SCM_ADM_USER_M U2
                     , SCM_ADM_USER_M U3
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE_ITEM SI
                     , SSP_ANL_SHIP_CONFIRM_CHG_REQ T1
                     , SCP_MST_FINAL_ITEM_V SMF         /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     /* NERP 적용시 GERP COMPANY_ID에 해당하는 것은 제외 필요함 */
                 WHERE UPPER(A.ITEM_ID)       = UPPER(T.ITEM_ID)      /* MSSQL 대소문자 무시 조인 */
                   AND A.DIVISION_ID          = T.DIVISION_ID
                   AND A.FROM_SITE_COMPANY_ID = T.COMPANY_ID
                   AND A.DIVISION_ID          = MS.DIVISION_ID
                   AND A.FROM_SITE            = MS.SCM_SITE_ID
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END = B.DIVISION_ID
                   AND A.BOD_ID               = B.BOD_ID
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND A.LAST_UPDATED_BY      = U.USERID(+)
                 --AND U.USEYN(+)             = 'Y'
                   AND A.LAST_UPDATED_BY      = U.USER_ID(+)
                   AND U.USE_YN(+)             = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND A.ORIGIN_TO_DIVISION_ID = F.DIVISION_ID(+)
                   AND A.TO_SITE              = F.SCM_SITE_ID(+)
                   AND F.VALID_YN(+)          = 'Y'
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END = G.DIVISION_ID(+)
                   AND A.TO_SITE              = G.SCM_SITE_ID(+)
                   AND UPPER(A.ITEM_ID)       = G.ITEM_ID_U(+)
                   AND A.CONFIRM_ID           = H.CONFIRM_ID(+)
                   AND A.ORIGIN_FROM_DIVISION_ID = MU.DIVISION_ID(+)
                   AND A.FROM_SITE            = MU.FROM_SITE(+)
                   AND UPPER(A.ITEM_ID)       = UPPER(MU.ITEM_ID(+))
                   AND MU.VALID_YN(+)         = 'Y'
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND MU.USER_ID             = U2.USERID(+)
                 --AND U2.USEYN(+)            = 'Y'
                 --AND A.LAST_UPDATED_BY      = U3.USERID(+)
                 --AND U3.USEYN(+)            = 'Y'
                   AND MU.USER_ID             = U2.USER_ID(+)
                   AND U2.USE_YN(+)            = 'Y'
                   AND A.LAST_UPDATED_BY      = U3.USER_ID(+)
                   AND U3.USE_YN(+)            = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END = SI.DIVISION_ID(+)
                   AND A.TO_SITE              = SI.SCM_SITE_ID(+)
                   AND UPPER(A.ITEM_ID)       = UPPER(SI.ITEM_ID(+))
                   AND UPPER(A.PROJECT_CODE)  = UPPER(SI.PROJECT_CODE(+))
                   AND H.CHANGE_REQ_NO        = T1.CHANGE_REQ_NO(+)
                   AND UPPER(A.ITEM_ID)       = UPPER(SMF.ITEM_ID(+))
                   /* --SET @mDqry = @mDQry + '		   AND T.ITEM_TYPE		NOT IN (''Q'',''R'')			 ' + char(10); */
                   AND T.ITEM_TYPE            <> 'R'                  /* 2025-05-15 'Q'인 경우도 화면에서 조회되어야 함 */
                   AND MS.SITE_TYPE           = 'PLANT'
                   AND A.SHIPMENT_STATUS IS NOT NULL                  /* AS-IS : shipment_status IS NOT NULL AND isnull(shipment_status,'') != '' */
                   AND A.QTY > 0
                   /* --SET @mDqry = @mDQry + ' 		  AND A.ATTRIBUTE10 <> N''I'' '+char(10); */
                   AND A.CHANGE_TYPE          <> 'N'
                   AND A.CONFIRM_ID LIKE 'C%'
                   AND V_RUN_YN               = 'Y'
                   AND A.YYYYMMDD            >= P_FROM_YYYYMMDD
                   AND A.YYYYMMDD            <= P_TO_YYYYMMDD
                   AND (V_DIV_CNT = 0
                        OR A.DIVISION_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_DIV_TAB) SA))
                   AND (V_ITEM_CNT = 0
                        OR UPPER(A.ITEM_ID) IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_ITEM_TAB) SA))
                   AND (V_FROM_CNT = 0
                        OR A.FROM_SITE IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_FROM_TAB) SA))
                   AND (V_TO_CNT = 0
                        OR UPPER(A.TO_SITE) IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_TO_TAB) SA))
                   AND (V_SO_CNT = 0
                        OR A.ERP_SO_NO IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_SO_TAB) SA))
                   /* 20211111 SHINMYUNGSU  추가   CONFIRM_ID 조회조건 추가 */
                   AND (V_CONFIRM_CNT = 0
                        OR A.CONFIRM_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_CONFIRM_TAB) SA))
                   /* --SET @mDqry = @mDQry + ' 	  AND a.CHANGE_TYPE = ''' + @p_change_type + '''	 ' + char(10); */
                   /* --SET @mDqry = @mDQry + ' 		  AND a.biz_type <> ''E''  '+char(10); */
               ) AA
         /* AS-IS 정렬 규칙(Latin1_General_CI_AS : 대소문자·하이픈 무시, 밑줄은 글자·숫자보다 앞) */
         ORDER BY UPPER(TRANSLATE(AA.DIVISION_ID, '_-', '/')) NULLS FIRST
             , AA.DIVISION_ID NULLS FIRST
             , UPPER(AA.SHIPMENT_STATUS) NULLS FIRST
             , AA.SHIPMENT_DATE NULLS FIRST
             , UPPER(TRANSLATE(AA.ITEM_ID, '_-', '/')) NULLS FIRST
             , AA.ITEM_ID NULLS FIRST
             , UPPER(TRANSLATE(AA.ERP_SO_NO, '_-', '/')) DESC NULLS LAST
             , AA.ERP_SO_NO DESC NULLS LAST
             , UPPER(TRANSLATE(AA.FROM_SITE, '_-', '/')) NULLS FIRST
             , AA.FROM_SITE NULLS FIRST
             , UPPER(TRANSLATE(AA.TO_SITE, '_-', '/')) NULLS FIRST
             , AA.TO_SITE NULLS FIRST
             , UPPER(TRANSLATE(AA.PROJECT_CODE, '_-', '/')) NULLS FIRST
             , AA.PROJECT_CODE NULLS FIRST
             , UPPER(TRANSLATE(AA.FCST_TYPE, '_-', '/')) NULLS FIRST
             , AA.FCST_TYPE NULLS FIRST;

    END P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST;

    /* ==== P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N / SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N ==== */
    /* ============================================================
       ※ AS-IS 는 FN_GET_IN_STR 로 IN 리스트를 만들어 EXEC 로 돌린다.
          선택조건 조립뿐이라 정적 SQL 로 옮겼다.
       ※ IN 리스트는 FN_GET_IN_STR 규칙을 그대로 옮긴 내부 함수(FN_IN_LIST)로 나눈다.
       ※ MSSQL 정렬(Latin1_General_CI_AS) : 비교는 대소문자 무시, 정렬은 대소문자·하이픈 무시
          · 밑줄은 글자·숫자보다 앞 → 조건·조인·정렬에 UPPER / TRANSLATE 반영
       ※ P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST 와의 차이(AS-IS 원문 그대로)
          · SCM_MST_ITEM_SN 조인 · SCP_MST_FINAL_ITEM_V 조인 · OPERATION_GROUP · REQUEST_DATE 칸 없음
          · REQUESTOR = A.REQUESTOR 의 사용자명(ssp_batch → System 치환 없음)
          · 조건 : CHANGE_TYPE = 'N' AND SHIPMENT_STATUS = 'C'
          · 사업부 외 선택조건(ITEM · FROM SITE · TO SITE · SO NO)은 AS-IS 에서 적용하지 않음
          · P_CONFIRM_ID 인자 없음
       ============================================================ */
    PROCEDURE P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N
    (
        P_DIVISION_ID           IN  VARCHAR2,
        P_FROM_SITE             IN  VARCHAR2,
        P_ERP_SO_NO             IN  VARCHAR2,
        P_ITEM_ID               IN  VARCHAR2,
        P_FROM_YYYYMMDD         IN  VARCHAR2,
        P_TO_YYYYMMDD           IN  VARCHAR2,
        P_STATUS                IN  VARCHAR2,
        P_CHANGE_TYPE           IN  VARCHAR2 DEFAULT 'C',
        P_LANGUAGE              IN  VARCHAR2 DEFAULT 'KO',
        P_DEBUG_MODE            IN  VARCHAR2 DEFAULT 'F',
        P_TO_SITE               IN  VARCHAR2 DEFAULT NULL,
        O_RC1                   OUT SYS_REFCURSOR
    )
    IS
        /*
         * Program ID   : SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N
         * Description  : Shipment Change Request
         * Program History
         *===================================================================================================
         *   Date       In Charge      Description
         *===================================================================================================
         * 2021/05/25   KIMYONGHO      최초작성
         * 2021/10/18   SHINMYUNGSU	   SSP_ANL_SHIP_CONFIRM의 ERP_ATTR1~3 항목 추가
         * 2025/12/11   chkim.68        E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능
         * 2026.09.17   AJS            MSSQL -> Oracle 전환 (동적 SQL -> 정적 SQL)
         *
         ex) PKG_SSP0200.P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N('40', '', '', '', '20260801', '20260831', '', 'C', 'KO', 'F', '', :RC)
         */
        V_DIV_TAB       T_STR_TAB;
        V_DIV_CNT       PLS_INTEGER;

        V_LANG_KO       VARCHAR2(1);
        V_OWNER_LANG    VARCHAR2(2);
        V_RUN_YN        VARCHAR2(1);

        /* AS-IS FN_GET_IN_STR 대응 : 결과 조각을 대문자로 담는다(조각 0개 = 조건 없음) */
        FUNCTION FN_IN_LIST(P_STR IN VARCHAR2) RETURN T_STR_TAB
        IS
            V_LIST      VARCHAR2(32767);
            V_TAB       T_STR_TAB := T_STR_TAB();
            V_NODE      PLS_INTEGER := 1;
            V_START     PLS_INTEGER;
            V_END       PLS_INTEGER;
        BEGIN
            /* AS-IS : IF @p_csv_text_list = '' RETURN('') - MSSQL 비교는 뒤 공백 무시 */
            IF TRIM(P_STR) IS NULL THEN
                RETURN V_TAB;
            END IF;

            V_LIST := REPLACE(REPLACE(P_STR, CHR(13), ''), CHR(10), ',');

            /* AS-IS FN_SCM_SPLIT : 빈 문자열이면 조각 없음 */
            IF V_LIST IS NULL THEN
                RETURN V_TAB;
            END IF;

            WHILE V_NODE <= 1000 LOOP
                IF V_NODE = 1 THEN
                    V_START := 1;
                ELSE
                    /* AS-IS FN_SCM_SPLIT : CHARINDEX(구분자, 문자열, 조각번호) = 0 이면 끝 */
                    EXIT WHEN INSTR(V_LIST, ',', V_NODE) = 0;
                    V_START := INSTR(V_LIST, ',', 1, V_NODE - 1);
                    EXIT WHEN V_START = 0;
                    V_START := V_START + 1;
                END IF;

                V_END := INSTR(V_LIST, ',', V_START);
                IF V_END = 0 THEN
                    V_END := LENGTH(V_LIST) + 1;
                END IF;

                /* 빈 조각은 AS-IS '' → Oracle NULL (어느 값과도 같지 않음 - AS-IS 와 결과 동일) */
                V_TAB.EXTEND;
                V_TAB(V_TAB.COUNT) := UPPER(SUBSTR(TRIM(SUBSTR(V_LIST, V_START, V_END - V_START)), 1, 100));
                V_NODE := V_NODE + 1;
            END LOOP;

            RETURN V_TAB;
        END FN_IN_LIST;

    BEGIN

        /* IN 조건으로 데이터를 가져옴 (AS-IS 는 FROM SITE · ITEM · TO SITE · SO NO 목록도 만들지만 조건에 쓰지 않는다) */
        V_DIV_TAB    := FN_IN_LIST(P_DIVISION_ID);
        V_DIV_CNT    := V_DIV_TAB.COUNT;

        /* AS-IS : CASE WHEN '<@p_language>' = 'KO' (대소문자·뒤 공백 무시) */
        V_LANG_KO    := CASE WHEN UPPER(RTRIM(P_LANGUAGE)) = 'KO' THEN 'Y' ELSE 'N' END;
        /* AS-IS FN_GET_SSP_MKT_OWNER_NAME 의 @p_language 는 NVARCHAR(2) - 앞 2자만, 대소문자 무시 */
        V_OWNER_LANG := UPPER(SUBSTR(P_LANGUAGE, 1, 2));
        /* AS-IS : 기간이 NULL 이면 조립 문장 전체가 NULL 이 되어 결과 없음 */
        V_RUN_YN     := CASE WHEN P_FROM_YYYYMMDD IS NULL OR P_TO_YYYYMMDD IS NULL THEN 'N' ELSE 'Y' END;

        OPEN O_RC1 FOR
        SELECT AA.*
          FROM (SELECT A.DIVISION_ID
                     , A.ERP_SO_NO
                     , A.SHIPMENT_STATUS
                     , A.PROJECT_CODE
                     , FN_GET_PROJECT_NAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.PROJECT_CODE) AS PROJECT_NAME
                     , A.FCST_TYPE
                     , A.ITEM_ID
                     , FN_GET_ITEM_NICKNAME(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.ITEM_ID) AS NICK_NAME
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS SHIPMENT_DATE
                     , A.BEFORE_QTY
                     , ROUND(A.QTY, 3)                   AS SHIPMENT_CONFIRM_QTY    /* E20250922-000093 SSP시스템의 전극출하를 위한 출하계획 소수점 입력 기능 */
                     , A.REMARKS
                     , A.REMARKS2
                     , A.REMARKS3
                     , A.FROM_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.FROM_SITE), '-') AS FROM_SITE_DESCRIPTION
                     , A.TO_SITE
                     , NVL(FN_GET_SCM_SITE_DESCRIPTION(A.DIVISION_ID, A.TO_SITE), '-')   AS TO_SITE_DESCRIPTION
                     , A.TO_SITE_SOLDTO_CODE
                     , A.TO_SITE_SHIPTO_CODE
                     , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SOLDTO_DESCRIPTION') AS SOLDTO_DESCRIPTION
                     , FN_GET_SITE_CUSTOMER_INFO(CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END, A.TO_SITE, 'SHIPTO_DESCRIPTION') AS SHIPTO_DESCRIPTION
                     , A.BOD_ID
                     , B.SSP_INCOTERMS                   AS INCOTERMS
                     , B.TRANSPORT_MODE
                     , B.LT_TOTAL                        AS LT_DAY
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETD
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ETA
                     , CASE WHEN B.TRANSPORT_MODE = 'TRK' THEN '-'
                            ELSE TO_CHAR(TO_DATE(FN_GET_SSP_EXPECTED_SHIP_DATE(A.DIVISION_ID, A.BOD_ID, A.YYYYMMDD), 'YYYYMMDD'), 'YYYY-MM-DD')
                       END                               AS "Expected_Shipping_Date"
                     , A.CONFIRM_ID
                       /* AS-IS : 이름 + '(' + ID + ')' - 어느 한쪽이 NULL 이면 NULL */
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USERNAME ELSE U.USERNAME_E END) IS NOT NULL
                     , CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USER_NM ELSE U.USER_ENG_NM END) IS NOT NULL
                     /* 2026.09.30 AJS 수정 (END) */
                             AND A.LAST_UPDATED_BY IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USERNAME ELSE U.USERNAME_E END) || '(' || A.LAST_UPDATED_BY || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U.USER_NM ELSE U.USER_ENG_NM END) || '(' || A.LAST_UPDATED_BY || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS UPDATED_BY
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN U.USERNAME IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                     , CASE WHEN U.USER_NM IS NOT NULL THEN A.LAST_UPDATE_DATE END AS UPDATED_DATE
                     /* 2026.09.30 AJS 수정 (END) */
                     , A.ERP_STATUS
                     , A.CHANGE_TYPE
                     , A.ROUTE_ID                        AS NEW_ROUTE_ID
                     , A.BOD_ID                          AS NEW_BOD_ID
                     , B.SSP_INCOTERMS                   AS NEW_INCOTERMS
                     , A.D_COUNTRY                       AS NEW_D_COUNTRY
                     , A.D_PORT_CODE                     AS NEW_D_PORT_CODE
                     , A.A_COUNTRY                       AS NEW_A_COUNTRY
                     , A.A_PORT_CODE                     AS NEW_A_PORT_CODE
                     , A.CUSTOMER_LT                     AS NEW_CUSTOMER_LT
                     , A.TO_COUNTRY                      AS NEW_TO_COUNTRY
                     , A.TO_CITY                         AS NEW_TO_CITY
                     , TO_CHAR(TO_DATE(A.ETA_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETA
                     , TO_CHAR(TO_DATE(A.ETD_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_ETD
                     , B.LT_TOTAL                        AS NEW_LT_DAY
                     , B.TRANSPORT_MODE                  AS NEW_TRANSPORT_MODE
                     , TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD'), 'YYYY-MM-DD') AS NEW_SHIPMENT_DATE
                     , 'N'                               AS EDIT_REMARKS
                     , 'N'                               AS EDIT_MAIN
                     , NVL(A.CHECK_NEED_YN, 'N')         AS CHECK_NEED_YN
                     , NVL(CASE WHEN A.DIVISION_ID = '40'
                                THEN CASE WHEN A.PROJECT_CODE IS NOT NULL AND A.PROJECT_CODE != '-'
                                          THEN A.PROJECT_CODE ELSE G.PROJECT_CODE END
                                WHEN A.DIVISION_ID = 'EE' AND A.ORIGIN_TO_DIVISION_ID = '40'
                                THEN G.PROJECT_CODE
                                ELSE F.END_CUSTOMER END, '/') AS END_CUSTOMER
                     , A.ELECTRODE_YN
                     , A.ELECTRODE_TYPE
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , H.CHANGE_REQ_NO
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USERNAME ELSE U2.USERNAME_E END) IS NOT NULL
                     , CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) IS NOT NULL
                     /* 2026.09.30 AJS 수정 (END) */
                             AND MU.USER_ID IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USERNAME ELSE U2.USERNAME_E END) || '(' || MU.USER_ID || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U2.USER_NM ELSE U2.USER_ENG_NM END) || '(' || MU.USER_ID || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS MODEL_USER
                       /* 같은 담당자 반복 호출은 스칼라 서브쿼리 캐시로 줄인다 */
                     , (SELECT PKG_ZTMP_S200B.FN_MKT_OWNER_FIX(SI.OWNER, ',', V_OWNER_LANG) FROM DUAL) AS MTK_OWNER
                     /* 2026.09.30 AJS 수정 (START) */
                   --, CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USERNAME ELSE U3.USERNAME_E END) IS NOT NULL
                     , CASE WHEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) IS NOT NULL
                     /* 2026.09.30 AJS 수정 (END) */
                             AND A.REQUESTOR IS NOT NULL
                            /* 2026.09.30 AJS 수정 (START) */
                          --THEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USERNAME ELSE U3.USERNAME_E END) || '(' || A.REQUESTOR || ')'
                            THEN (CASE WHEN V_LANG_KO = 'Y' THEN U3.USER_NM ELSE U3.USER_ENG_NM END) || '(' || A.REQUESTOR || ')'
                            /* 2026.09.30 AJS 수정 (END) */
                       END                               AS REQUESTOR
                     , '-'                               AS CHANGE_REASON_CODE
                     , ''                                AS CHANGE_REASON_DETAIL
                     , A.ATTRIBUTE10
                       /**** 20211018   SHINMYUNGSU   열람항목추가   ******************************************************/
                     , A.ERP_ATTR1
                     , A.ERP_ATTR2
                     , A.ERP_ATTR3
                       /***********************************************************************************/
                  FROM SSP_ANL_SHIP_CONFIRM A
                     , SCM_MST_SITE MS
                     , SCP_MST_BOD_N_V B
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER U
                     , SCM_ADM_USER_M U
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE F
                     , (SELECT XA.DIVISION_ID
                             , XA.PROJECT_CODE
                             , XA.SCM_SITE_ID
                             , XA.ITEM_ID_U
                          FROM (SELECT DIVISION_ID
                                     , PROJECT_CODE
                                     , SCM_SITE_ID
                                     , UPPER(ITEM_ID) AS ITEM_ID_U
                                       /* AS-IS 정렬 규칙(대소문자·하이픈 무시)으로 첫 PROJECT_CODE */
                                     , ROW_NUMBER() OVER (PARTITION BY DIVISION_ID, SCM_SITE_ID, UPPER(ITEM_ID)
                                                              ORDER BY UPPER(TRANSLATE(PROJECT_CODE, '_-', '/')) NULLS FIRST
                                                                     , PROJECT_CODE NULLS FIRST) AS NUM
                                  FROM SCM_MST_SITE_ITEM) XA
                         WHERE XA.NUM = 1) G
                     , (SELECT IA.CONFIRM_ID
                             , IA.CHANGE_REQ_NO
                          FROM (SELECT CONFIRM_ID
                                     , CHANGE_REQ_NO
                                     , ROW_NUMBER() OVER (PARTITION BY CONFIRM_ID ORDER BY CHANGE_REQ_NO DESC NULLS LAST) AS NUM
                                  FROM SSP_ANL_SHIP_CONFIRM_CHG_REQ_DE
                                 WHERE VALID_YN = 'Y') IA
                         WHERE IA.NUM = 1) H
                     , SSP_MST_MODEL_USER MU
                     /* 2026.09.30 AJS 수정 (START) */
                   --, TB_FX_USER U2
                   --, TB_FX_USER U3
                     , SCM_ADM_USER_M U2
                     , SCM_ADM_USER_M U3
                     /* 2026.09.30 AJS 수정 (END) */
                     , SCM_MST_SITE_ITEM SI
                     , SSP_ANL_SHIP_CONFIRM_CHG_REQ T1
                     /* NERP 적용시 GERP COMPANY_ID에 해당하는 것은 제외 필요함 */
                 WHERE A.DIVISION_ID          = MS.DIVISION_ID
                   AND A.FROM_SITE            = MS.SCM_SITE_ID
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_FROM_DIVISION_ID ELSE A.DIVISION_ID END = B.DIVISION_ID
                   AND A.BOD_ID               = B.BOD_ID
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND A.LAST_UPDATED_BY      = U.USERID(+)
                 --AND U.USEYN(+)             = 'Y'
                   AND A.LAST_UPDATED_BY      = U.USER_ID(+)
                   AND U.USE_YN(+)             = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND A.ORIGIN_TO_DIVISION_ID = F.DIVISION_ID(+)
                   AND A.TO_SITE              = F.SCM_SITE_ID(+)
                   AND F.VALID_YN(+)          = 'Y'
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END = G.DIVISION_ID(+)
                   AND A.TO_SITE              = G.SCM_SITE_ID(+)
                   AND UPPER(A.ITEM_ID)       = G.ITEM_ID_U(+)
                   AND A.CONFIRM_ID           = H.CONFIRM_ID(+)
                   AND A.ORIGIN_FROM_DIVISION_ID = MU.DIVISION_ID(+)
                   AND A.FROM_SITE            = MU.FROM_SITE(+)
                   AND UPPER(A.ITEM_ID)       = UPPER(MU.ITEM_ID(+))
                   AND MU.VALID_YN(+)         = 'Y'
                   /* 2026.09.30 AJS 수정 (START) */
                 --AND MU.USER_ID             = U2.USERID(+)
                 --AND U2.USEYN(+)            = 'Y'
                 --AND A.REQUESTOR            = U3.USERID(+)
                 --AND U3.USEYN(+)            = 'Y'
                   AND MU.USER_ID             = U2.USER_ID(+)
                   AND U2.USE_YN(+)            = 'Y'
                   AND A.REQUESTOR            = U3.USER_ID(+)
                   AND U3.USE_YN(+)            = 'Y'
                   /* 2026.09.30 AJS 수정 (END) */
                   AND CASE WHEN A.DIVISION_ID = 'EE' THEN A.ORIGIN_TO_DIVISION_ID ELSE A.DIVISION_ID END = SI.DIVISION_ID(+)
                   AND A.TO_SITE              = SI.SCM_SITE_ID(+)
                   AND UPPER(A.ITEM_ID)       = UPPER(SI.ITEM_ID(+))
                   AND UPPER(A.PROJECT_CODE)  = UPPER(SI.PROJECT_CODE(+))
                   AND H.CHANGE_REQ_NO        = T1.CHANGE_REQ_NO(+)
                   AND MS.SITE_TYPE           = 'PLANT'
                   AND A.SHIPMENT_STATUS IS NOT NULL                  /* AS-IS : shipment_status IS NOT NULL AND isnull(shipment_status,'') != '' */
                   AND A.QTY > 0
                   AND A.CHANGE_TYPE          = 'N'
                   AND A.SHIPMENT_STATUS      = 'C'
                   AND A.CONFIRM_ID LIKE 'C%'
                   /* --SET @mDqry = @mDQry + ' 	  AND a.CHANGE_TYPE = ''' + @p_change_type + '''	 ' + char(10); */
                   /* --SET @mDqry = @mDQry + ' 		  AND a.biz_type <> ''E''  '+char(10); */
                   AND V_RUN_YN               = 'Y'
                   AND A.YYYYMMDD            >= P_FROM_YYYYMMDD
                   AND A.YYYYMMDD            <= P_TO_YYYYMMDD
                   AND (V_DIV_CNT = 0
                        OR A.DIVISION_ID IN (SELECT SA.COLUMN_VALUE FROM TABLE(V_DIV_TAB) SA))
                   /* --IF ( @v_item_id     IS NOT NULL AND @v_item_id    != ''  ) SET @mDQry = @mDQry + ' 					AND  a.item_id       IN ('+ @v_item_id     +')'+char(10); */
                   /* --IF ( @v_from_site   IS NOT NULL AND @v_from_site    != '') SET @mDQry = @mDQry + ' 					AND  a.from_site     IN ('+ @v_from_site   +')'+char(10); */
               ) AA
         /* AS-IS 정렬 규칙(Latin1_General_CI_AS : 대소문자·하이픈 무시, 밑줄은 글자·숫자보다 앞) */
         ORDER BY UPPER(TRANSLATE(AA.DIVISION_ID, '_-', '/')) NULLS FIRST
             , AA.DIVISION_ID NULLS FIRST
             , UPPER(AA.SHIPMENT_STATUS) NULLS FIRST
             , AA.SHIPMENT_DATE NULLS FIRST
             , UPPER(TRANSLATE(AA.ITEM_ID, '_-', '/')) NULLS FIRST
             , AA.ITEM_ID NULLS FIRST
             , UPPER(TRANSLATE(AA.ERP_SO_NO, '_-', '/')) DESC NULLS LAST
             , AA.ERP_SO_NO DESC NULLS LAST
             , UPPER(TRANSLATE(AA.FROM_SITE, '_-', '/')) NULLS FIRST
             , AA.FROM_SITE NULLS FIRST
             , UPPER(TRANSLATE(AA.TO_SITE, '_-', '/')) NULLS FIRST
             , AA.TO_SITE NULLS FIRST
             , UPPER(TRANSLATE(AA.PROJECT_CODE, '_-', '/')) NULLS FIRST
             , AA.PROJECT_CODE NULLS FIRST
             , UPPER(TRANSLATE(AA.FCST_TYPE, '_-', '/')) NULLS FIRST
             , AA.FCST_TYPE NULLS FIRST;

    END P_SSP0200_GET_SHIPMENT_CHANGE_REQUEST_N;

END PKG_ZTMP_S200B;
/
SHOW ERRORS PACKAGE BODY PKG_ZTMP_S200B
-- ##### END PACKAGE BODY PKG_ZTMP_S200B

-- ##### START PROCEDURE PR_DM_ANL_KPI_SALES_ACCURACY
CREATE OR REPLACE PROCEDURE           "PR_DM_ANL_KPI_SALES_ACCURACY" 
/*
 * Program ID   : PR_DM_ANL_KPI_SALES_ACCURACY
 * Description  : KPI_SALES_ACCURACY (매출계획 적확도/전월 마지막에 짠 당월 RTF 대비 당월 실적 값의 비율)
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 2018. 09. 21    KHSONG      Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 20181213 add SUM(RESULT_QTY) < 0 THEN 0
 * 20181214 RTF 음수값 제외처리 (sp.qty >= 0)
 * 20190121        KHSONG      FCST 상관없이 실적을 구함.
 * 20191121 KHSONG 'RTF_SYS_RP' MEASURE 추가전송
 * 2020/09/09     P.C.I		[C20200909-000203] LOG 표준화 적용
 * 2022.04.05   HWI1993		GM JV 로직 적용
 * 2025.06.23	KANG.H.J	[PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *
 */
IS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PR_DM_ANL_KPI_SALES_ACCURACY';
    V_LOG_TYPE              VARCHAR2(30 CHAR);   /* START/END/ERROR/... */
    N_LOG_COUNT             NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;

    /* 변수 */
    V_YYYYMMDD              VARCHAR2(8 CHAR);
BEGIN


    V_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');

    /* 시작 LOG  (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;      /* <- 변수 재사용을 위하여 초기화해야함 */
    /* 시작 LOG  (END) */

    /* 트랜잭션 (START)  (원본 BEGIN TRANSACTION PR_DM_ANL_KPI_SALES_ACCURACY -> Oracle 평면 트랜잭션) */

    /*------------------------------------------------------------------------------------------*/
    BEGIN
    /*------------------------------------------------------------------------------------------*/

    /*---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎*/
    /*                                                                                                                                                   매출계획 적확도 (START)*/
    /*---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎*/
    BEGIN
        /* INSERT 수행전 당일중복값 삭제 */
        DELETE
          FROM DM_ANL_KPI_SALES_ACCURACY
         WHERE WORK_YYYYMMDD = V_YYYYMMDD;

        INSERT
          INTO DM_ANL_KPI_SALES_ACCURACY
             ( WORK_YYYYMMDD
             , DIVISION_ID
             , DEPT_ID
             , END_CUSTOMER
             , SCM_SITE_ID
             , PROJECT_CODE
             , ITEM_ID
             , FCST_TYPE
             , YYYYMM
             , RESULT_QTY
             , MEASURE
             , WEIGHT
             , KPI_RATE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        WITH SALESPLAN_ACCURACY AS
        (
            /* 금액은 KRW 기준? Currency를 쓰긴 어려우니... */
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.PROJECT_CODE
                 , A.ITEM_ID
                 , A.FCST_TYPE
                 , A.YYYYMMDD
                 , A.QTY PLAN_QTY
                 , 0 RESULT_QTY
                 , A.MEASURE
              FROM DM_PLN_SALES_PLAN_C A
                 , ( SELECT DIVISION_ID
                          , SUBSTR(YYYYMMDD, 1, 6) MONTHS
                          , MAX(VERSION_NO) VERSION_NO
                       FROM DM_MST_VERSION
                      WHERE VERSION_TYPE = 'SP_W'
                      GROUP BY DIVISION_ID, SUBSTR(YYYYMMDD, 1, 6)
                   ) B
             WHERE A.DIVISION_ID = B.DIVISION_ID
               AND A.VERSION_NO = B.VERSION_NO
               AND SUBSTR(A.YYYYMMDD, 1, 6) = SUBSTR(TO_CHAR(ADD_MONTHS(TO_DATE(B.MONTHS || '01', 'YYYYMMDD'), 1), 'YYYYMMDD'), 1, 6)
               AND A.MEASURE IN ('RTF', 'SalesAmt_KRW', 'RTF_SYS_RP')   /* 20191121 KHSONG 'RTF_SYS_RP' MEASURE 추가전송 */
               AND A.QTY >= 0   /* 20181214 RTF 음수값 제외처리 (sp.qty >= 0) */
        )
        , PLAN_AND_RESULT AS
        (
            SELECT *
              FROM SALESPLAN_ACCURACY

            UNION ALL

            /* FCST 상관없이 실적을 구함. 20190121 추가 */
            SELECT A.DIVISION_ID
                 , A.SCM_SITE_ID
                 , A.PROJECT_CODE
                 , A.ITEM_ID
                 , A.FCST_TYPE
                 , A.YYYYMMDD
                 , 0 PLAN_QTY
                 /*-------------------------------------------------------------------------------------------------------------------------------*/
                 /* [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가 (dm_pln_sales_plan_result에 CELL_PROD_SITE_ID가 추가됨에 따라 SUM 처리 필요) */
                 /* , A.QTY  RESULT_QTY */
                 , SUM(A.QTY) RESULT_QTY
                 /*-------------------------------------------------------------------------------------------------------------------------------*/
                 , A.MEASURE
              FROM DM_PLN_SALES_PLAN_RESULT A
                 , ( SELECT DISTINCT DIVISION_ID
                          , SUBSTR(YYYYMMDD, 1, 6) MONTHS
                       FROM SALESPLAN_ACCURACY
                   ) B
             WHERE A.DIVISION_ID = B.DIVISION_ID

               AND SUBSTR(A.YYYYMMDD, 1, 6) = B.MONTHS
               AND A.MEASURE IN ('RTF', 'SalesAmt_KRW', 'RTF_SYS_RP')   /* 20191121 KHSONG 'RTF_SYS_RP' MEASURE 추가전송 */
               /* AND A.QTY >= 0   20181214 RTF 음수값 제외처리 (sp.qty >= 0) */
               /* modified by ytchoi 181116 Data 검증이 용이하기 위해서 전주까지의 실적을 가지도록 함. */
               AND A.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
             /*-------------------------------------------------------------------------------------------------------------------------------*/
             /* [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가 (dm_pln_sales_plan_result에 CELL_PROD_SITE_ID가 추가됨에 따라 SUM 처리 필요) */
             GROUP BY A.DIVISION_ID
                    , A.SCM_SITE_ID
                    , A.PROJECT_CODE
                    , A.ITEM_ID
                    , A.FCST_TYPE
                    , A.YYYYMMDD
                    , A.MEASURE
             /*-------------------------------------------------------------------------------------------------------------------------------*/
        )
        /*		-- 실적은 FCST가 있는것 기준으로 값을 구함. 20190121 주석처리
        select  sp.[DIVISION_ID]
               ,sp.[SCM_SITE_ID]
               ,sp.[PROJECT_CODE]
               ,sp.[ITEM_ID]
               ,sp.[FCST_TYPE]
               ,sp.YYYYMMDD
               ,0       plan_qty
               ,sp.qty  result_qty
              ,[MEASURE]
          from dm_pln_sales_plan_result sp WITH(NOLOCK)
              ,(
           select distinct division_id, scm_site_id, project_code, item_id, fcst_type, SUBSTRING( yyyymmdd, 1,6 ) months
             from salesplan_accuracy
            ) target_key
         where sp.measure				in ( 'RTF' , 'SalesAmt_KRW' )
           and sp.DIVISION_ID			= target_key.DIVISION_ID
           and sp.SCM_SITE_ID			= target_key.scm_site_id
           and sp.PROJECT_CODE			= target_key.PROJECT_CODE
           and sp.ITEM_ID				= target_key.ITEM_ID
           and sp.fcst_type				= target_key.fcst_type
           and SUBSTRING(YYYYMMDD, 1,6) = target_key.months
           -- modified by ytchoi 181116 Data 검증이 용이하기 위해서 전주까지의 실적을 가지도록 함.
           and yyyymmdd                 < CONVERT(CHAR(8), DATEADD(DD, -7, dbo.FN_NEXT_DAY(GETDATE(), 'MON')), 112)
           )
        */
        SELECT V_YYYYMMDD
             , A.DIVISION_ID
--             , CASE WHEN A.DIVISION_ID = '40' THEN D.DEPT_ID ELSE B.DEPT_ID END DEPT_ID
             , C.DEPT_ID DEPT_ID                                                        -- 2026.09.03 AJS
             , CASE WHEN A.DIVISION_ID = '40' THEN NVL(C.PROJECT_CODE, '/') ELSE NVL(B.END_CUSTOMER, '-') END END_CUSTOMER
             , A.SCM_SITE_ID
             , A.PROJECT_CODE
             , A.ITEM_ID
             , A.FCST_TYPE
             , SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM
             , SUM(A.RESULT_QTY) RESULT_QTY
             , A.MEASURE
             , SUM(A.PLAN_QTY) WEIGHT
             /* , CASE WHEN SUM(PLAN_QTY) = 0 THEN 0 WHEN SUM(RESULT_QTY)/SUM(PLAN_QTY) > 1 THEN 1 ELSE SUM(RESULT_QTY)/SUM(PLAN_QTY) END KPI_RATE */
             /* 20181213 add SUM(RESULT_QTY) < 0 THEN 0 */
             , CASE WHEN SUM(A.PLAN_QTY) = 0 THEN 0
                    WHEN SUM(A.RESULT_QTY) < 0 THEN 0
                    WHEN ABS(SUM(A.RESULT_QTY) - SUM(A.PLAN_QTY)) / SUM(A.PLAN_QTY) > 1 THEN 1
                    ELSE 1 - ABS(SUM(A.RESULT_QTY) - SUM(A.PLAN_QTY)) / SUM(A.PLAN_QTY)
               END KPI_RATE
             , 'KPI_SALES_ACCURACY'   /* CREATED_BY */
             , SYSDATE
             , 'KPI_SALES_ACCURACY'   /* LAST_UPDATED_BY */
             , SYSDATE
             , NULL   /* ATTRIBUTE1 */
             , NULL   /* ATTRIBUTE2 */
             , NULL   /* ATTRIBUTE3 */
             , NULL   /* ATTRIBUTE4 */
             , NULL   /* ATTRIBUTE5 */
             , NULL   /* ATTRIBUTE6 */
             , NULL   /* ATTRIBUTE7 */
             , NULL   /* ATTRIBUTE8 */
             , NULL   /* ATTRIBUTE9 */
             , NULL   /* ATTRIBUTE10 */
          FROM PLAN_AND_RESULT A
             , SCM_MST_SITE B
             , SCM_MST_SITE_ITEM C
--             , SCM_MST_SSO_USER_INFO D                                                                                                     -- 2026.09.06 AJS
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND B.VALID_YN = 'Y'
           AND A.DIVISION_ID = C.DIVISION_ID(+)
           AND A.PROJECT_CODE = C.PROJECT_CODE(+)
           AND A.SCM_SITE_ID = C.SCM_SITE_ID(+)
           AND A.ITEM_ID = C.ITEM_ID(+)
           AND C.VALID_YN(+) = 'Y'
--           AND SUBSTR(C.OWNER, 1, CASE WHEN INSTR(C.OWNER, ',') = 0 THEN LENGTH(C.OWNER) ELSE INSTR(C.OWNER, ',') - 1 END) = D.USER_ID(+)   -- 2026.09.06 AJS
           AND A.DIVISION_ID IN (SELECT DIVISION_ID FROM SCM_MST_DIVISION WHERE ATTRIBUTE3 IN ('40', '81', '82'))
         GROUP BY A.DIVISION_ID
--                , CASE WHEN A.DIVISION_ID = '40' THEN D.DEPT_ID ELSE B.DEPT_ID END
                , C.DEPT_ID                                                             -- 2026.09.03 AJS
                , CASE WHEN A.DIVISION_ID = '40' THEN NVL(C.PROJECT_CODE, '/') ELSE NVL(B.END_CUSTOMER, '-') END
                , A.SCM_SITE_ID
                , A.PROJECT_CODE
                , A.ITEM_ID
                , A.FCST_TYPE
                , SUBSTR(A.YYYYMMDD, 1, 6)
                , A.MEASURE
        ;

    END;
    /*---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎*/
    /*                                                                                                                                                   매출계획 적확도 (END)*/
    /*---------------------------------------------------------------------------------------------------------------------------------------------------------------------◎◎◎◎*/

    /* 트랜잭션 (COMMIT) */
        COMMIT;

    /*------------------------------------------------------------------------------------------*/
    EXCEPTION
    /*------------------------------------------------------------------------------------------*/
    WHEN OTHERS THEN
        /* 트랜잭션 (END)  (원본 ROLLBACK TRANSACTION PR_DM_ANL_KPI_SALES_ACCURACY) */
        ROLLBACK;

        /* ERROR LOG VALUE SAVE */
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        D_EVENT_DATE  := SYSDATE;

        DBMS_OUTPUT.PUT_LINE('[' || SQLCODE || ']' || SQLERRM);   /* 에러메시지 DISPLAY */

        /* [C20200909-000203] LOG 표준화 적용 */


        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                           , NULL
                           , SQLCODE, SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;

    /* 수행결과 성공여부 DISPLAY */
    IF V_LOG_MESSAGE IS NULL THEN
        DBMS_OUTPUT.PUT_LINE('success');
    END IF;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;
/
SHOW ERRORS PROCEDURE PR_DM_ANL_KPI_SALES_ACCURACY
-- ##### END PROCEDURE PR_DM_ANL_KPI_SALES_ACCURACY

-- ##### START PROCEDURE PR_DM_ANL_KPI_SUMMARY
CREATE OR REPLACE PROCEDURE           "PR_DM_ANL_KPI_SUMMARY" 

/*
 * PROGRAM ID   : PR_DM_ANL_KPI_SUMMARY
 * DESCRIPTION  : KPI SUMMARY
 * PROGRAM HISTORY
 *===================================================================================================
 *   DATE       IN CHARGE      DESCRIPTION
 *===================================================================================================
 * 2018. 08. 28    KHSONG      INITIAL RELEASE [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 20180919  KHSONG  테이블 컬럼수정
 * 20181127  KHSONG  DIVISION ID INPUT 조건추가
 * 2020/09/09     P.C.I  [C20200909-000203] LOG 표준화 적용
 * 2021/01/07	  kuni	 [C20201208-000161] 실적 수신처리 속도 개선의 건
 * 2021/11/25	kdw2819	 [C20211122-000148]SFA, CFA, SPA 관련 오류 수정 건
 * 2022.04.11   hwi1993     GM JV 작업
 *
 */
AS
/*
 * PROGRAM ID  : PR_DM_ANL_KPI_SUMMARY  (KPI SUMMARY)
 *   - 커서 CUR_KPI_SUMMARY -> FOR 루프
 *   - WITH cte INSERT -> INSERT ... SELECT FROM (inline view)
 *   - 분기: '40' = item OWNER->USER->DEPT / ELSE(81,82) = site DEPT + SCM_MST_PROJECT
 */
  V_PROGRAM_NAME   VARCHAR2(150 CHAR) := 'PR_DM_ANL_KPI_SUMMARY';
  V_LOG_TYPE       VARCHAR2(30 CHAR);
  N_LOG_COUNT      NUMBER := 0;
  V_LOG_MESSAGE    VARCHAR2(1000 CHAR);
  V_DESCRIPTION    VARCHAR2(500 CHAR);
  D_EVENT_DATE     DATE;
  V_DIVISION_ID    VARCHAR2(30 CHAR);
  V_YYYYMMDD       VARCHAR2(8 CHAR);
  V_TO_DATE        VARCHAR2(8 CHAR);
BEGIN
  V_TO_DATE  := TO_CHAR(ADD_MONTHS(SYSDATE,-6),'YYYYMMDD');
  V_YYYYMMDD := TO_CHAR(SYSDATE,'YYYYMMDD');

  /* 대상 DIVISION_ID */
  INSERT INTO GT_KPISUM_I_DIV (DIVISION_ID)
  SELECT DIVISION_ID FROM SCM_MST_DIVISION WHERE ATTRIBUTE3 IN ('40','81','82');

  /* LOG 작업 DIVISION_ID 표기 (FN_GET_PIVOT_STRING -> LISTAGG) */
  SELECT LISTAGG(DIVISION_ID, ',') WITHIN GROUP (ORDER BY DIVISION_ID)
    INTO V_DESCRIPTION FROM GT_KPISUM_I_DIV;

  /* 시작 LOG */
  V_LOG_TYPE := 'START';
  V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
  D_EVENT_DATE := SYSDATE;
  PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
  V_LOG_MESSAGE := NULL;

  BEGIN


    INSERT INTO GT_KPISUM_DATE_TEMP ( QTY, BB_BASIS_YYYYMMDD, DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, PARTIAL_WEEK_NAME, MEASURE )
    SELECT SUM(NVL(X.QTY,0)), MIN(Y.BB_BASIS_YYYYMMDD), X.DIVISION_ID, X.SCM_SITE_ID, X.PROJECT_CODE, X.ITEM_ID, X.FCST_TYPE
         , Z.CALENDAR_YYYY||'_'||Z.PARTIAL_WEEK_NAME, X.MEASURE
      FROM DM_PLN_MKT_FCST_C X
         , ( SELECT AA.DIVISION_ID, MAX(AA.VERSION_NO) VERSION_NO, BB.BASIS_YYYYMMDD AS BB_BASIS_YYYYMMDD
               FROM DM_MST_VERSION AA, SCM_SYS_CALENDAR_M BB, SCM_SYS_CALENDAR_M CC
              WHERE AA.VERSION_TYPE = 'MF_W'
                AND AA.YYYYMMDD >= V_TO_DATE
                AND AA.YYYYMMDD = CC.BASIS_YYYYMMDD
                AND BB.ISO_YYYYWW = CC.ISO_YYYYWW
              GROUP BY AA.DIVISION_ID, BB.BASIS_YYYYMMDD ) Y
         , SCM_SYS_CALENDAR_M Z
     WHERE 1=1
       AND X.DIVISION_ID = Y.DIVISION_ID
       AND X.VERSION_NO = Y.VERSION_NO
       AND X.YYYYMMDD = Z.BASIS_YYYYMMDD
       AND X.MEASURE IN ('MKT_FCST','CUST_FCST','RTF')
       AND X.VERSION_NO LIKE 'MF_W%'
     GROUP BY X.DIVISION_ID, X.SCM_SITE_ID, X.PROJECT_CODE, X.ITEM_ID, X.FCST_TYPE
         , Z.CALENDAR_YYYY||'_'||Z.PARTIAL_WEEK_NAME, X.MEASURE;


    DELETE FROM DM_ANL_KPI_SUMMARY WHERE WORK_YYYYMMDD = V_YYYYMMDD;

    /* DIVISION 별 루프 */
    FOR R IN ( SELECT DIVISION_ID FROM GT_KPISUM_I_DIV GROUP BY DIVISION_ID ) LOOP
      V_DIVISION_ID := R.DIVISION_ID;

      DELETE FROM GT_KPISUM_ITEM_SINGLE;
      INSERT INTO GT_KPISUM_ITEM_SINGLE ( DIVISION_ID, ITEM_ID, NICK_NAME )
      SELECT DIVISION_ID, ITEM_ID, NICK_NAME FROM DM_MST_ITEM_SINGLE_V
       WHERE DIVISION_ID = V_DIVISION_ID AND ACTIVE_FLAG = 'Y';

      IF V_DIVISION_ID = '40' THEN

    /* ===== SFA (40) measure=MKT_FCST ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, A.PROJECT_CODE AS END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'SFA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            , SCM_MST_SITE_ITEM E
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
--          , SCM_MST_SSO_USER_INFO G   -- 2026.09.06 AJS 원본
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
          AND A.DIVISION_ID = E.DIVISION_ID
          AND A.SCM_SITE_ID = E.SCM_SITE_ID
          AND A.PROJECT_CODE = E.PROJECT_CODE
          AND A.ITEM_ID = E.ITEM_ID
--        AND E.OWNER = G.USER_ID   -- 2026.09.06 AJS 원본
--        AND G.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          /* AND E.DEPT_ID = F.DEPT_ID */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'MKT_FCST'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'MKT_FCST'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'MKT_FCST'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'MKT_FCST'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'MKT_FCST'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'MKT_FCST'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'MKT_FCST'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'MKT_FCST'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'MKT_FCST'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'MKT_FCST'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'MKT_FCST'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'MKT_FCST'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
