         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

    /* ===== CFA (40) measure=CUST_FCST ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, A.PROJECT_CODE AS END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'CFA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            , SCM_MST_SITE_ITEM E
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
--          , SCM_MST_SSO_USER_INFO G   -- 2026.09.06 AJS 원본
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
          AND A.DIVISION_ID = E.DIVISION_ID
          AND A.SCM_SITE_ID = E.SCM_SITE_ID
          AND A.PROJECT_CODE = E.PROJECT_CODE
          AND A.ITEM_ID = E.ITEM_ID
--        AND E.OWNER = G.USER_ID   -- 2026.09.06 AJS 원본
--        AND G.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          /* AND E.DEPT_ID = F.DEPT_ID */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'CUST_FCST'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'CUST_FCST'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'CUST_FCST'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'CUST_FCST'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'CUST_FCST'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'CUST_FCST'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'CUST_FCST'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'CUST_FCST'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'CUST_FCST'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'CUST_FCST'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'CUST_FCST'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'CUST_FCST'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X12.ITEM_ID(+) = A.ITEM_ID
         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

    /* ===== SPA (40) measure=RTF ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, A.PROJECT_CODE AS END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'SPA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            , SCM_MST_SITE_ITEM E
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
--          , SCM_MST_SSO_USER_INFO G   -- 2026.09.06 AJS 원본
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
          AND A.DIVISION_ID = E.DIVISION_ID
          AND A.SCM_SITE_ID = E.SCM_SITE_ID
          AND A.PROJECT_CODE = E.PROJECT_CODE
          AND A.ITEM_ID = E.ITEM_ID
--        AND E.OWNER = G.USER_ID   -- 2026.09.06 AJS 원본
--        AND G.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          /* AND E.DEPT_ID = F.DEPT_ID */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'RTF'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'RTF'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'RTF'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'RTF'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'RTF'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'RTF'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'RTF'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'RTF'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'RTF'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'RTF'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'RTF'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'RTF'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X12.ITEM_ID(+) = A.ITEM_ID
         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

      ELSE

    /* ===== SFA (else) measure=MKT_FCST ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'SFA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
            , SCM_MST_PROJECT G
            , SCM_MST_SITE_ITEM E   -- 2026.09.06 AJS
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
--        AND D.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          AND A.DIVISION_ID = E.DIVISION_ID(+)   -- 2026.09.06 AJS
          AND A.SCM_SITE_ID = E.SCM_SITE_ID(+)   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = E.PROJECT_CODE(+)   -- 2026.09.06 AJS
          AND A.ITEM_ID = E.ITEM_ID(+)   -- 2026.09.06 AJS
          /* AND E.DEPT_ID = F.DEPT_ID(+) */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = G.PROJECT_CODE
          AND A.DIVISION_ID = G.DIVISION_ID
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'MKT_FCST'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'MKT_FCST'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'MKT_FCST'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'MKT_FCST'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'MKT_FCST'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'MKT_FCST'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'MKT_FCST'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'MKT_FCST'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'MKT_FCST'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'MKT_FCST'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'MKT_FCST'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'MKT_FCST'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X12.ITEM_ID(+) = A.ITEM_ID
         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

    /* ===== CFA (else) measure=CUST_FCST ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'CFA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
            , SCM_MST_PROJECT G
            , SCM_MST_SITE_ITEM E   -- 2026.09.06 AJS
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
--        AND D.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          AND A.DIVISION_ID = E.DIVISION_ID(+)   -- 2026.09.06 AJS
          AND A.SCM_SITE_ID = E.SCM_SITE_ID(+)   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = E.PROJECT_CODE(+)   -- 2026.09.06 AJS
          AND A.ITEM_ID = E.ITEM_ID(+)   -- 2026.09.06 AJS
          /* AND E.DEPT_ID = F.DEPT_ID(+) */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = G.PROJECT_CODE
          AND A.DIVISION_ID = G.DIVISION_ID
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'CUST_FCST'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'CUST_FCST'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'CUST_FCST'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'CUST_FCST'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'CUST_FCST'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'CUST_FCST'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'CUST_FCST'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'CUST_FCST'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'CUST_FCST'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'CUST_FCST'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'CUST_FCST'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'CUST_FCST'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X12.ITEM_ID(+) = A.ITEM_ID
         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

    /* ===== SPA (else) measure=RTF ===== */
    INSERT INTO DM_ANL_KPI_SUMMARY
      ( WORK_YYYYMMDD,DIVISION_ID,DEPT_ID,END_CUSTOMER,SCM_SITE_ID,PROJECT_CODE,ITEM_ID,FCST_TYPE,ISO_YYYYWW,PARTIAL_WEEK_NAME,YYYYMMDD,RESULT_QTY,MEASURE,WEIGHT,KPI_RATE
      ,W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
      ,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10 )
    SELECT V_YYYYMMDD, DIVISION_ID, DEPT_ID, NVL(NULLIF(RTRIM(END_CUSTOMER),''), '/'), SCM_SITE_ID, PROJECT_CODE, ITEM_ID, FCST_TYPE, ISO_YYYYWW, PARTIAL_WEEK_NAME, YYYYMMDD, RESULT_QTY, MEASURE
         , ( W1_BEFORE_VALUE+W2_BEFORE_VALUE+W3_BEFORE_VALUE+W4_BEFORE_VALUE+W5_BEFORE_VALUE+W6_BEFORE_VALUE+W7_BEFORE_VALUE+W8_BEFORE_VALUE+W9_BEFORE_VALUE+W10_BEFORE_VALUE+W11_BEFORE_VALUE+W12_BEFORE_VALUE )/12 WEIGHT
         , CASE WHEN W1_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W1_BEFORE_VALUE - RESULT_QTY)/W1_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W2_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W2_BEFORE_VALUE - RESULT_QTY)/W2_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W3_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W3_BEFORE_VALUE - RESULT_QTY)/W3_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W4_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W4_BEFORE_VALUE - RESULT_QTY)/W4_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W5_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W5_BEFORE_VALUE - RESULT_QTY)/W5_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W6_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W6_BEFORE_VALUE - RESULT_QTY)/W6_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W7_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W7_BEFORE_VALUE - RESULT_QTY)/W7_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W8_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W8_BEFORE_VALUE - RESULT_QTY)/W8_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W9_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W9_BEFORE_VALUE - RESULT_QTY)/W9_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W10_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W10_BEFORE_VALUE - RESULT_QTY)/W10_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W11_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W11_BEFORE_VALUE - RESULT_QTY)/W11_BEFORE_VALUE )) *1/12 ) END
               + CASE WHEN W12_BEFORE_VALUE = 0 THEN 0 WHEN ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE > 1 THEN 0 ELSE ( (1-( ABS(W12_BEFORE_VALUE - RESULT_QTY)/W12_BEFORE_VALUE )) *1/12 ) END KPI_RATE
         , W1_BEFORE_VALUE,W2_BEFORE_VALUE,W3_BEFORE_VALUE,W4_BEFORE_VALUE,W5_BEFORE_VALUE,W6_BEFORE_VALUE,W7_BEFORE_VALUE,W8_BEFORE_VALUE,W9_BEFORE_VALUE,W10_BEFORE_VALUE,W11_BEFORE_VALUE,W12_BEFORE_VALUE,W13_BEFORE_VALUE,W14_BEFORE_VALUE,W15_BEFORE_VALUE,W16_BEFORE_VALUE,W17_BEFORE_VALUE,W18_BEFORE_VALUE,W19_BEFORE_VALUE,W20_BEFORE_VALUE
         , CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE,ATTRIBUTE1,ATTRIBUTE2,ATTRIBUTE3,ATTRIBUTE4,ATTRIBUTE5,ATTRIBUTE6,ATTRIBUTE7,ATTRIBUTE8,ATTRIBUTE9,ATTRIBUTE10
      FROM (
      SELECT A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
            , SUM(A.RESULT_QTY) AS RESULT_QTY
            , MAX(A.MEASURE) AS MEASURE
            , SUM(NVL(X1.QTY,0)) AS W1_BEFORE_VALUE
            , SUM(NVL(X2.QTY,0)) AS W2_BEFORE_VALUE
            , SUM(NVL(X3.QTY,0)) AS W3_BEFORE_VALUE
            , SUM(NVL(X4.QTY,0)) AS W4_BEFORE_VALUE
            , SUM(NVL(X5.QTY,0)) AS W5_BEFORE_VALUE
            , SUM(NVL(X6.QTY,0)) AS W6_BEFORE_VALUE
            , SUM(NVL(X7.QTY,0)) AS W7_BEFORE_VALUE
            , SUM(NVL(X8.QTY,0)) AS W8_BEFORE_VALUE
            , SUM(NVL(X9.QTY,0)) AS W9_BEFORE_VALUE
            , SUM(NVL(X10.QTY,0)) AS W10_BEFORE_VALUE
            , SUM(NVL(X11.QTY,0)) AS W11_BEFORE_VALUE
            , SUM(NVL(X12.QTY,0)) AS W12_BEFORE_VALUE
            , NULL W13_BEFORE_VALUE, NULL W14_BEFORE_VALUE, NULL W15_BEFORE_VALUE, NULL W16_BEFORE_VALUE, NULL W17_BEFORE_VALUE
            , NULL W18_BEFORE_VALUE, NULL W19_BEFORE_VALUE, NULL W20_BEFORE_VALUE
            , 'SYSTEM' CREATED_BY, SYSDATE CREATION_DATE, 'SYSTEM' LAST_UPDATED_BY, SYSDATE LAST_UPDATE_DATE
            , NULL ATTRIBUTE1, NULL ATTRIBUTE2, NULL ATTRIBUTE3, NULL ATTRIBUTE4, NULL ATTRIBUTE5
            , NULL ATTRIBUTE6, NULL ATTRIBUTE7, NULL ATTRIBUTE8, NULL ATTRIBUTE9, NULL ATTRIBUTE10
        FROM (
            SELECT A.DIVISION_ID, E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, C.NICK_NAME, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY||'_'||B.PARTIAL_WEEK_NAME PARTIAL_WEEK_NAME   -- 2026.09.06 AJS
            , ( SELECT MIN(X.BASIS_YYYYMMDD) FROM SCM_SYS_CALENDAR_M X WHERE X.CALENDAR_YYYY = B.CALENDAR_YYYY AND X.PARTIAL_WEEK_NAME = B.PARTIAL_WEEK_NAME ) YYYYMMDD
            , SUM(A.QTY) RESULT_QTY
            , 'SPA' MEASURE
            , MIN(B.BASIS_YYYYMMDD) AS BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 0*7,'YYYYMMDD') AS B1_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 1*7,'YYYYMMDD') AS B2_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 2*7,'YYYYMMDD') AS B3_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 3*7,'YYYYMMDD') AS B4_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 4*7,'YYYYMMDD') AS B5_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 5*7,'YYYYMMDD') AS B6_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 6*7,'YYYYMMDD') AS B7_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 7*7,'YYYYMMDD') AS B8_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 8*7,'YYYYMMDD') AS B9_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 9*7,'YYYYMMDD') AS B10_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 10*7,'YYYYMMDD') AS B11_BASIS_YYYYMMDD
            , TO_CHAR(TO_DATE(MIN(B.BASIS_YYYYMMDD),'YYYYMMDD') - 11*7,'YYYYMMDD') AS B12_BASIS_YYYYMMDD
         FROM DM_PLN_MKT_FCST_RESULT A
            , SCM_SYS_CALENDAR_M B
            , GT_KPISUM_ITEM_SINGLE C
            , SCM_MST_SITE D
            /* , SCM_MST_SSO_DEPT_INFO F */   /* 참조처 없어짐 */   -- 2026.09.06 AJS
            , SCM_MST_PROJECT G
            , SCM_MST_SITE_ITEM E   -- 2026.09.06 AJS
        WHERE A.DIVISION_ID = V_DIVISION_ID
          AND A.YYYYMMDD >= V_TO_DATE
          AND A.YYYYMMDD = B.BASIS_YYYYMMDD
          AND A.MEASURE = 'RTF'
          AND A.SCM_SITE_ID <> '-'
          AND A.PROJECT_CODE <> 'N'
          AND A.ITEM_ID = C.ITEM_ID
          AND A.DIVISION_ID = C.DIVISION_ID
          AND A.DIVISION_ID = D.DIVISION_ID
          AND A.SCM_SITE_ID = D.SCM_SITE_ID
          AND D.VALID_YN = 'Y'
--        AND D.DEPT_ID = F.DEPT_ID   -- 2026.09.06 AJS 원본
          AND A.DIVISION_ID = E.DIVISION_ID(+)   -- 2026.09.06 AJS
          AND A.SCM_SITE_ID = E.SCM_SITE_ID(+)   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = E.PROJECT_CODE(+)   -- 2026.09.06 AJS
          AND A.ITEM_ID = E.ITEM_ID(+)   -- 2026.09.06 AJS
          /* AND E.DEPT_ID = F.DEPT_ID(+) */   /* 부서 마스터 경유 불필요 : 부서 코드를 아이템 원장에서 직접 사용 */   -- 2026.09.06 AJS
          AND A.PROJECT_CODE = G.PROJECT_CODE
          AND A.DIVISION_ID = G.DIVISION_ID
        GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.FCST_TYPE, B.ISO_YYYYWW, B.CALENDAR_YYYY, B.PARTIAL_WEEK_NAME
            , E.DEPT_ID, D.END_CUSTOMER, G.PROJECT_NAME, C.NICK_NAME   -- 2026.09.06 AJS
        ) A
           , GT_KPISUM_DATE_TEMP X1
           , GT_KPISUM_DATE_TEMP X2
           , GT_KPISUM_DATE_TEMP X3
           , GT_KPISUM_DATE_TEMP X4
           , GT_KPISUM_DATE_TEMP X5
           , GT_KPISUM_DATE_TEMP X6
           , GT_KPISUM_DATE_TEMP X7
           , GT_KPISUM_DATE_TEMP X8
           , GT_KPISUM_DATE_TEMP X9
           , GT_KPISUM_DATE_TEMP X10
           , GT_KPISUM_DATE_TEMP X11
           , GT_KPISUM_DATE_TEMP X12
       WHERE X1.MEASURE(+) = 'RTF'
         AND X1.DIVISION_ID(+) = A.DIVISION_ID
         AND X1.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X1.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X1.ITEM_ID(+) = A.ITEM_ID
         AND X1.FCST_TYPE(+) = A.FCST_TYPE
         AND X1.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X2.MEASURE(+) = 'RTF'
         AND X2.DIVISION_ID(+) = A.DIVISION_ID
         AND X2.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X2.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X2.ITEM_ID(+) = A.ITEM_ID
         AND X2.FCST_TYPE(+) = A.FCST_TYPE
         AND X2.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X3.MEASURE(+) = 'RTF'
         AND X3.DIVISION_ID(+) = A.DIVISION_ID
         AND X3.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X3.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X3.ITEM_ID(+) = A.ITEM_ID
         AND X3.FCST_TYPE(+) = A.FCST_TYPE
         AND X3.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X4.MEASURE(+) = 'RTF'
         AND X4.DIVISION_ID(+) = A.DIVISION_ID
         AND X4.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X4.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X4.ITEM_ID(+) = A.ITEM_ID
         AND X4.FCST_TYPE(+) = A.FCST_TYPE
         AND X4.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X5.MEASURE(+) = 'RTF'
         AND X5.DIVISION_ID(+) = A.DIVISION_ID
         AND X5.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X5.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X5.ITEM_ID(+) = A.ITEM_ID
         AND X5.FCST_TYPE(+) = A.FCST_TYPE
         AND X5.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X6.MEASURE(+) = 'RTF'
         AND X6.DIVISION_ID(+) = A.DIVISION_ID
         AND X6.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X6.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X6.ITEM_ID(+) = A.ITEM_ID
         AND X6.FCST_TYPE(+) = A.FCST_TYPE
         AND X6.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X7.MEASURE(+) = 'RTF'
         AND X7.DIVISION_ID(+) = A.DIVISION_ID
         AND X7.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X7.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X7.ITEM_ID(+) = A.ITEM_ID
         AND X7.FCST_TYPE(+) = A.FCST_TYPE
         AND X7.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X8.MEASURE(+) = 'RTF'
         AND X8.DIVISION_ID(+) = A.DIVISION_ID
         AND X8.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X8.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X8.ITEM_ID(+) = A.ITEM_ID
         AND X8.FCST_TYPE(+) = A.FCST_TYPE
         AND X8.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X9.MEASURE(+) = 'RTF'
         AND X9.DIVISION_ID(+) = A.DIVISION_ID
         AND X9.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X9.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X9.ITEM_ID(+) = A.ITEM_ID
         AND X9.FCST_TYPE(+) = A.FCST_TYPE
         AND X9.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X10.MEASURE(+) = 'RTF'
         AND X10.DIVISION_ID(+) = A.DIVISION_ID
         AND X10.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X10.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X10.ITEM_ID(+) = A.ITEM_ID
         AND X10.FCST_TYPE(+) = A.FCST_TYPE
         AND X10.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X11.MEASURE(+) = 'RTF'
         AND X11.DIVISION_ID(+) = A.DIVISION_ID
         AND X11.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X11.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X11.ITEM_ID(+) = A.ITEM_ID
         AND X11.FCST_TYPE(+) = A.FCST_TYPE
         AND X11.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
         AND X12.MEASURE(+) = 'RTF'
         AND X12.DIVISION_ID(+) = A.DIVISION_ID
         AND X12.SCM_SITE_ID(+) = A.SCM_SITE_ID
         AND X12.PROJECT_CODE(+) = A.PROJECT_CODE
         AND X12.ITEM_ID(+) = A.ITEM_ID
         AND X12.FCST_TYPE(+) = A.FCST_TYPE
         AND X12.PARTIAL_WEEK_NAME(+) = A.PARTIAL_WEEK_NAME
        GROUP BY A.DIVISION_ID, A.DEPT_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.NICK_NAME, A.FCST_TYPE, A.ISO_YYYYWW
            , A.PARTIAL_WEEK_NAME, A.YYYYMMDD, A.BASIS_YYYYMMDD
      )
     WHERE RESULT_QTY > 0;

      END IF;

    END LOOP;

    COMMIT;

  EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      V_LOG_TYPE := 'ERROR';
      V_LOG_MESSAGE := SUBSTR(SQLERRM,1,1000);
      V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
      D_EVENT_DATE := SYSDATE;
      PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
  END;

  /* 종료 LOG */
  V_LOG_TYPE := 'END';
  V_LOG_MESSAGE := '########## END OF PROCEDURE ##########';
  D_EVENT_DATE := SYSDATE;
  PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_ANL_KPI_SUMMARY;
/
SHOW ERRORS PROCEDURE PR_DM_ANL_KPI_SUMMARY
-- ##### END PROCEDURE PR_DM_ANL_KPI_SUMMARY

-- ##### START PROCEDURE PR_DM_ANL_MKT_PSI_DATA
CREATE OR REPLACE PROCEDURE           "PR_DM_ANL_MKT_PSI_DATA" 
/* ============================================================
 * Program ID   : PR_DM_ANL_MKT_PSI_DATA
 * Description  : 고객수요증감분석 데이터 기초값 생성 및 인터페이스 전송
 * 메인테이블
 *   DM_ANL_MKT_PSI
 *   DM_ANL_MKT_PSI_DETAIL
 *   XIF_DM_ANL_MKT_PSI_DW_S
 *   XIF_DM_ANL_MKT_PSI_DETAIL_DW_S
 * EXEC PR_DM_ANL_MKT_PSI_DATA
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2024.01.10    kcw3408        [개발요청] 고객수요증감분석_배치작업 신규(표준리포트/RPA팀 우혜라 요청)
 * 2024.02.08    kcw3408        XIF_DM_ANL_MKT_PSI_DETAIL_DW_S 테이블에 DEPT_NAME Sales Site Project Model 화면 ‘Team’칼럼 수정
 * 2024.06.19    kcw3408        Synonym 만들어서 변경  XIF_DM_ANL_MKT_PSI_DW_S_SN ,XIF_DM_ANL_MKT_PSI_DETAIL_DW_S_SN
 * 2024.10.16    KJJ            [PJ2024-50461] Team Mapping
 *                              => 운영과 개발이 내용이 달라서 운영의 스크립트로 작업
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
IS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := 'PR_DM_ANL_MKT_PSI_DATA';
    V_LOG_TYPE           VARCHAR2(30 CHAR);       /* START/END/ERROR/... */
    N_LOG_COUNT          NUMBER(10)         := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    N_DELETE_COUNT       NUMBER(10)         := 0;
    N_INSERT_COUNT       NUMBER(10)         := 0;
    V_CREATED_BY         VARCHAR2(150 CHAR) := 'SYS_PSI_DATA';

    V_0MONTH_TUESDAY     VARCHAR2(8 CHAR);        /* 당월의 첫번째 수요일이 포함된 주차의 MKT_FCST Cutoff */
    V_DELIMITER          VARCHAR2(1 CHAR);

    V_CNT                NUMBER(10)         := 0;
    V_CNT_PRE            NUMBER(10)         := 0;
    V_FROM_YYYYMMDD      VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD        VARCHAR2(8 CHAR);
    V_FROM_YYYYMMDD_R    VARCHAR2(8 CHAR);
    V_TO_YYYYMMDD_R      VARCHAR2(8 CHAR);
BEGIN

    BEGIN

        /* 시작 LOG */
        V_LOG_TYPE    := 'START';
        V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_CREATED_BY);

        DBMS_OUTPUT.PUT_LINE('A1--#TEMP_DATA ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /* 테이블중복제거 */
        DELETE FROM GT_DAMP_DATA;

        BEGIN
            V_FROM_YYYYMMDD := SUBSTR(TO_CHAR(ADD_MONTHS(SYSDATE, -12), 'YYYYMMDD'), 1, 6) || '01';
            /* V_TO_YYYYMMDD = 당월 말일 */
            V_TO_YYYYMMDD   := TO_CHAR(ADD_MONTHS(TO_DATE(SUBSTR(TO_CHAR(SYSDATE, 'YYYYMMDD'), 1, 6) || '01', 'YYYYMMDD'), 1) - 1, 'YYYYMMDD');
        END;

        BEGIN
            /* YYYYMM  13개월 가져오기 */
            DELETE FROM GT_DAMP_SCM_SYS_CALENDAR_M;

            INSERT
              INTO GT_DAMP_SCM_SYS_CALENDAR_M
                 ( YYYYMM )
            SELECT DISTINCT BASIS_YYYYMM AS YYYYMM
              FROM SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD >= V_FROM_YYYYMMDD
               AND A.BASIS_YYYYMMDD <= V_TO_YYYYMMDD;

            /* 실적구간 / 계획구간 구분 */
            SELECT NVL(MAX(A.YYYYMMDD), TO_CHAR(TO_DATE(V_FROM_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'))
                 , NVL(MAX(A.YYYYMMDD), V_TO_YYYYMMDD)
              INTO V_FROM_YYYYMMDD_R, V_TO_YYYYMMDD_R
              FROM DM_PLN_MKT_FCST_RESULT A
             WHERE 1 = 1
               AND A.DIVISION_ID LIKE '81%'
               AND A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST')
               AND A.YYYYMMDD >= V_FROM_YYYYMMDD
               AND A.YYYYMMDD <= V_TO_YYYYMMDD;
        END;

        /*
          대상추출(DM_ANL_MKT_PSI 에 없는건 추출(당월 ~ -12개월)
        */
        BEGIN
            INSERT
              INTO GT_DAMP_DATA
                 ( DIVISION_ID
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , YYYYMM
                 , MEASURE )
            SELECT A.DIVISION_ID
                 , A.END_CUSTOMER
                 , A.PROJECT_CODE
                 , B.YYYYMM
                 , C.MEASURE
              FROM (SELECT A.DIVISION_ID
                         , A.END_CUSTOMER
                         , A.PROJECT_CODE
                      FROM (SELECT A.DIVISION_ID
                                 , C.END_CUSTOMER
                                 , A.PROJECT_CODE
                              FROM DM_PLN_MKT_FCST_RESULT A
                                 , SCM_MST_SITE_ITEM B
                                 , SCM_MST_SITE C
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL D
                             WHERE B.DIVISION_ID  = A.DIVISION_ID
                               AND B.PROJECT_CODE = A.PROJECT_CODE
                               AND B.SCM_SITE_ID  = A.SCM_SITE_ID
                               AND B.ITEM_ID      = A.ITEM_ID
                               AND B.DIVISION_ID  = C.DIVISION_ID
                               AND B.SCM_SITE_ID  = C.SCM_SITE_ID
                               AND D.SEGMENT1     = A.FCST_TYPE
                               AND D.LOOKUP_TYPE  = 'SALES_TYPE_CODE'
                               AND A.DIVISION_ID LIKE '81%'
                               AND A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST')
                               AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                               AND A.YYYYMMDD <= V_TO_YYYYMMDD_R
                             GROUP BY A.DIVISION_ID
                                    , C.END_CUSTOMER
                                    , A.PROJECT_CODE
                            UNION ALL
                            SELECT A.DIVISION_ID
                                 , C.END_CUSTOMER
                                 , A.PROJECT_CODE
                              FROM DM_PLN_MKT_FCST A
                                 , SCM_MST_SITE_ITEM B
                                 , SCM_MST_SITE C
                                 , SCM_ADM_LOOKUP_MASTER_DETAIL D
                             WHERE B.DIVISION_ID  = A.DIVISION_ID
                               AND B.PROJECT_CODE = A.PROJECT_CODE
                               AND B.SCM_SITE_ID  = A.SCM_SITE_ID
                               AND B.ITEM_ID      = A.ITEM_ID
                               AND B.DIVISION_ID  = C.DIVISION_ID
                               AND B.SCM_SITE_ID  = C.SCM_SITE_ID
                               AND D.SEGMENT1     = A.FCST_TYPE
                               AND D.LOOKUP_TYPE  = 'SALES_TYPE_CODE'
                               AND A.DIVISION_ID LIKE '81%'
                               AND A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST')
                               AND A.YYYYMMDD >  V_FROM_YYYYMMDD_R
                               AND A.YYYYMMDD <= V_TO_YYYYMMDD
                             GROUP BY A.DIVISION_ID
                                    , C.END_CUSTOMER
                                    , A.PROJECT_CODE
                           ) A
                     GROUP BY A.DIVISION_ID
                            , A.END_CUSTOMER
                            , A.PROJECT_CODE
                   ) A
                 , GT_DAMP_SCM_SYS_CALENDAR_M B
                 , (SELECT 'AN_RESULT' AS MEASURE FROM DUAL UNION ALL
                    SELECT 'AN_LOGIC'  AS MEASURE FROM DUAL UNION ALL
                    SELECT 'DP_INIT'   AS MEASURE FROM DUAL UNION ALL
                    SELECT 'DP_RESULT' AS MEASURE FROM DUAL
                   ) C
                 , (SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.END_CUSTOMER
                         , A.YYYYMM
                      FROM DM_ANL_MKT_PSI A
                         , GT_DAMP_SCM_SYS_CALENDAR_M B
                     WHERE A.YYYYMM = B.YYYYMM
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER, A.YYYYMM
                   ) D
             WHERE A.DIVISION_ID  = D.DIVISION_ID(+)
               AND A.END_CUSTOMER = D.END_CUSTOMER(+)
               AND A.PROJECT_CODE = D.PROJECT_CODE(+)
               AND B.YYYYMM       = D.YYYYMM(+)
               AND D.YYYYMM IS NULL;
        END;

        DBMS_OUTPUT.PUT_LINE('A2--DM_ANL_MKT_PSI INSERT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /*
          DM_ANL_MKT_PSI 저장
        */
        BEGIN
            INSERT
              INTO DM_ANL_MKT_PSI
                 ( DIVISION_ID
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , YYYYMM
                 , CUST_FCST_M
                 , MEASURE
                 , P_VALUE
                 , S_VALUE
                 , I_VALUE
                 , V_VALUE
                 , M_VALUE
                 , MKT_FCST_M
                 , CUST_FCST_M_CELL
                 , P_VALUE_CELL
                 , S_VALUE_CELL
                 , I_VALUE_CELL
                 , V_VALUE_CELL
                 , M_VALUE_CELL
                 , MKT_FCST_M_CELL
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , CP_VALUE
                 , CP_VALUE_CELL )
            SELECT A.DIVISION_ID
                 , A.END_CUSTOMER
                 , A.PROJECT_CODE
                 , A.YYYYMM
                 , 0 AS CUST_FCST_M
                 , A.MEASURE
                 , 0 AS P_VALUE
                 , 0 AS S_VALUE
                 , 0 AS I_VALUE
                 , 0 AS V_VALUE
                 , 0 AS M_VALUE
                 , 0 AS MKT_FCST_M
                 , 0 AS CUST_FCST_M_CELL
                 , 0 AS P_VALUE_CELL
                 , 0 AS S_VALUE_CELL
                 , 0 AS I_VALUE_CELL
                 , 0 AS V_VALUE_CELL
                 , 0 AS M_VALUE_CELL
                 , 0 AS MKT_FCST_M_CELL
                 , 'BATCH SYSTEM' AS CREATED_BY
                 , SYSDATE AS CREATION_DATE
                 , 'BATCH SYSTEM' AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , 0 AS CP_VALUE
                 , 0 AS CP_VALUE_CELL
              FROM GT_DAMP_DATA A;
        END;

        DBMS_OUTPUT.PUT_LINE('A3-- PROJECT TRANSLATOR ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /*
           환산자 추출
        */
        BEGIN
            DELETE FROM GT_DAMP_PROJECT_TRANSLATOR;

            INSERT
              INTO GT_DAMP_PROJECT_TRANSLATOR
                 ( DIVISION_ID
                 , PROJECT_CODE
                 , ITEM_ID
                 , BIZ_TYPE
                 , TRANSLATOR )
            SELECT A.DIVISION_ID
                 , A.PROJECT_CODE
                 , A.ITEM_ID
                 , A.BIZ_TYPE
                 , B.CELL_CF AS TRANSLATOR
              FROM (SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.ITEM_ID
                         , CASE WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AP' THEN 'PACK'
                                WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AM' THEN 'MODULE'
                                WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AC' THEN 'CELL'
                           END BIZ_TYPE
                         , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.PROJECT_CODE ORDER BY A.DIVISION_ID, A.PROJECT_CODE, SUBSTR(A.ITEM_ID, 2, 1) DESC) AS RNK
                      FROM (SELECT A.DIVISION_ID
                                 , A.PROJECT_CODE
                                 , B.ITEM_ID
                              FROM (SELECT DISTINCT DIVISION_ID, PROJECT_CODE
                                      FROM DM_ANL_MKT_PSI_DETAIL
                                   ) A
                                 , (SELECT A.DIVISION_ID, A.PROJECT_CODE, A.ITEM_ID
                                      FROM SCM_MST_SITE_ITEM A
                                         , DM_MST_ITEM_SINGLE_V B
                                     WHERE A.DIVISION_ID = B.DIVISION_ID
                                       AND A.ITEM_ID     = B.ITEM_ID
                                       AND A.DIVISION_ID LIKE '81%'
                                       AND A.VALID_YN = 'Y'
                                       AND B.ITEM_TYPE = 'P'
                                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.ITEM_ID
                                   ) B
                             WHERE A.DIVISION_ID  = B.DIVISION_ID
                               AND A.PROJECT_CODE = B.PROJECT_CODE
                           ) A
                   ) A
                 , SCP_MST_FINAL_ITEM B
             WHERE A.ITEM_ID     = B.ITEM_ID
               AND A.DIVISION_ID = B.DIVISION_ID
               AND A.RNK = 1;
        END;

        DBMS_OUTPUT.PUT_LINE('A4-- DM_ANL_MKT_PSI UPDATE(DM_ANL_MKT_PSI_DETAIL SUM) ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /*
           DM_ANL_MKT_PSI_DETAIL 입력값 반영
        */
        BEGIN
            MERGE INTO DM_ANL_MKT_PSI A
            USING (SELECT A.DIVISION_ID
                        , A.END_CUSTOMER
                        , A.PROJECT_CODE
                        , A.YYYYMM
                        , A.CUST_FCST_M
                        , A.MEASURE
                        , NVL(CEIL(A.P_VALUE), 0) AS P_VALUE
                        , NVL(CEIL(A.S_VALUE), 0) AS S_VALUE
                        , NVL(CEIL(A.I_VALUE), 0) AS I_VALUE
                        , NVL(CEIL(A.V_VALUE), 0) AS V_VALUE
                        , NVL(CEIL(A.M_VALUE), 0) AS M_VALUE
                        , CASE WHEN A.MEASURE = 'DP_RESULT'
                               THEN NVL(CEIL(A.MKT_FCST_M), 0)
                               ELSE NVL(CEIL(A.CUST_FCST_M - (CEIL(A.P_VALUE) + CEIL(A.S_VALUE) + CEIL(A.I_VALUE) + CEIL(A.V_VALUE) + CEIL(A.M_VALUE) + CEIL(A.CP_VALUE))), 0)
                          END  AS  MKT_FCST_M
                        , A.CUST_FCST_M * NVL(B.TRANSLATOR, 0) AS CUST_FCST_M_CELL
                        , NVL(CEIL(A.P_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS P_VALUE_CELL
                        , NVL(CEIL(A.S_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS S_VALUE_CELL
                        , NVL(CEIL(A.I_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS I_VALUE_CELL
                        , NVL(CEIL(A.V_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS V_VALUE_CELL
                        , NVL(CEIL(A.M_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS M_VALUE_CELL
                        , CASE WHEN A.MEASURE = 'DP_RESULT'
                               THEN NVL(CEIL(A.MKT_FCST_M * NVL(B.TRANSLATOR, 0)), 0)
                               ELSE NVL(CEIL(CEIL(A.CUST_FCST_M - (CEIL(A.P_VALUE) + CEIL(A.S_VALUE) + CEIL(A.I_VALUE) + CEIL(A.V_VALUE) + CEIL(A.M_VALUE) + CEIL(A.CP_VALUE))) * NVL(B.TRANSLATOR, 0)), 0)
                          END  AS  MKT_FCST_M_CELL
                        , NVL(CEIL(A.CP_VALUE), 0)  AS CP_VALUE
                        , NVL(CEIL(A.CP_VALUE * NVL(B.TRANSLATOR, 0)), 0) AS CP_VALUE_CELL
                     FROM (SELECT DIVISION_ID
                                , END_CUSTOMER
                                , PROJECT_CODE
                                , YYYYMM
                                , CUST_FCST_M
                                , MEASURE
                                , MKT_FCST_M
                                , NVL(SUM(CASE WHEN QTYCD3 = 'PRODUCT'     THEN QTY END), 0) AS P_VALUE
                                , NVL(SUM(CASE WHEN QTYCD3 = 'SALES'       THEN QTY END), 0) AS S_VALUE
                                , NVL(SUM(CASE WHEN QTYCD3 = 'INVENTORY'   THEN QTY END), 0) AS I_VALUE
                                , NVL(SUM(CASE WHEN QTYCD3 = 'VPA'         THEN QTY END), 0) AS V_VALUE
                                , NVL(SUM(CASE WHEN QTYCD3 = 'MODELMIX'    THEN QTY END), 0) AS M_VALUE
                                , NVL(SUM(CASE WHEN QTYCD3 = 'SUPPLYISSUE' THEN QTY END), 0) AS CP_VALUE
                             FROM DM_ANL_MKT_PSI_DETAIL
                            WHERE 1 = 1
                              AND YYYYMM >= SUBSTR(V_FROM_YYYYMMDD, 1, 6)
                            GROUP BY DIVISION_ID
                                , END_CUSTOMER
                                , PROJECT_CODE
                                , YYYYMM
                                , CUST_FCST_M
                                , MEASURE
                                , MKT_FCST_M
                          ) A
                        , GT_DAMP_PROJECT_TRANSLATOR B
                    WHERE B.DIVISION_ID  = A.DIVISION_ID
                      AND B.PROJECT_CODE = A.PROJECT_CODE
                  ) B
            ON ( B.DIVISION_ID  = A.DIVISION_ID
             AND B.PROJECT_CODE = A.PROJECT_CODE
             AND B.END_CUSTOMER = A.END_CUSTOMER
             AND B.YYYYMM       = A.YYYYMM
             AND B.MEASURE      = A.MEASURE )
            WHEN MATCHED THEN UPDATE SET
                  A.P_VALUE       = B.P_VALUE
                , A.S_VALUE       = B.S_VALUE
                , A.I_VALUE       = B.I_VALUE
                , A.V_VALUE       = B.V_VALUE
                , A.M_VALUE       = B.M_VALUE
                , A.CP_VALUE      = B.CP_VALUE
                , A.P_VALUE_CELL  = B.P_VALUE_CELL
                , A.S_VALUE_CELL  = B.S_VALUE_CELL
                , A.I_VALUE_CELL  = B.I_VALUE_CELL
                , A.V_VALUE_CELL  = B.V_VALUE_CELL
                , A.M_VALUE_CELL  = B.M_VALUE_CELL
                , A.CP_VALUE_CELL = B.CP_VALUE_CELL
                , A.MKT_FCST_M    = B.MKT_FCST_M
                , A.CUST_FCST_M   = B.CUST_FCST_M
                , A.LAST_UPDATED_BY  = 'BATCH SYSTEM'
                , A.LAST_UPDATE_DATE = SYSDATE
             WHERE (A.P_VALUE + A.S_VALUE + A.I_VALUE + A.V_VALUE + A.M_VALUE + A.CP_VALUE) = 0
               AND (A.P_VALUE + A.S_VALUE + A.I_VALUE + A.V_VALUE + A.M_VALUE + A.CP_VALUE) <> (B.P_VALUE + B.S_VALUE + B.I_VALUE + B.V_VALUE + B.M_VALUE + B.CP_VALUE);
        END;

        DBMS_OUTPUT.PUT_LINE('A5--DP_RESULT(Demand Plan (final)) ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /*
           DP_RESULT(Demand Plan (final)) ⓓMKT.FCST (DP) 에 MKTFCST 화면에 월 MKT FCST[R+P] Measure실적과 동일하게 관리
        */
        BEGIN

            /* SCM_MST_SITE 대상건만 추출 */
            BEGIN
                DELETE FROM GT_DAMP_SCM_MST_SITE;

                INSERT
                  INTO GT_DAMP_SCM_MST_SITE
                     ( DIVISION_ID
                     , SCM_SITE_ID
                     , END_CUSTOMER )
                SELECT DIVISION_ID
                     , SCM_SITE_ID
                     , END_CUSTOMER
                  FROM SCM_MST_SITE
                 WHERE DIVISION_ID LIKE '81%';
            END;

            MERGE INTO DM_ANL_MKT_PSI A
            USING (SELECT A.DIVISION_ID
                        , C.END_CUSTOMER
                        , A.PROJECT_CODE
                        , SUBSTR(A.YYYYMMDD, 1, 6) AS YYYYMM
                        , NVL(CEIL(SUM(A.QTY)), 0) AS A_QTY
                     FROM DM_PLN_MKT_FCST_RESULT A
                        , SCM_MST_SITE_ITEM B
                        , GT_DAMP_SCM_MST_SITE C
                        , SCM_ADM_LOOKUP_MASTER_DETAIL D
                    WHERE B.DIVISION_ID  = A.DIVISION_ID
                      AND B.PROJECT_CODE = A.PROJECT_CODE
                      AND B.SCM_SITE_ID  = A.SCM_SITE_ID
                      AND B.ITEM_ID      = A.ITEM_ID
                      AND B.DIVISION_ID  = C.DIVISION_ID
                      AND B.SCM_SITE_ID  = C.SCM_SITE_ID
                      AND D.SEGMENT1     = A.FCST_TYPE
                      AND D.LOOKUP_TYPE  = 'SALES_TYPE_CODE'
                      AND A.DIVISION_ID LIKE '81%'
                      AND A.MEASURE = 'RTF_SYS_RP'
                      AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                      AND SUBSTR(A.YYYYMMDD, 1, 6) <= TO_CHAR(ADD_MONTHS(TO_DATE(V_TO_YYYYMMDD, 'YYYYMMDD'), -1), 'YYYYMM')
                    GROUP BY A.DIVISION_ID
                        , C.END_CUSTOMER
                        , A.PROJECT_CODE
                        , SUBSTR(A.YYYYMMDD, 1, 6)
                  ) B
            ON ( B.DIVISION_ID  = A.DIVISION_ID
             AND B.PROJECT_CODE = A.PROJECT_CODE
             AND B.END_CUSTOMER = A.END_CUSTOMER
             AND B.YYYYMM       = A.YYYYMM
             AND A.MEASURE      = 'DP_RESULT' )
            WHEN MATCHED THEN UPDATE SET
                  A.MKT_FCST_M       = B.A_QTY
                , A.LAST_UPDATED_BY  = 'BATCH SYSTEM'
                , A.LAST_UPDATE_DATE = SYSDATE
             WHERE A.MKT_FCST_M <> B.A_QTY;

        END;

        /*
           CUST_FCST_M 작업
        */
        BEGIN
            DELETE FROM GT_DAMP_EDI_END_CUSTOMER;

            INSERT
              INTO GT_DAMP_EDI_END_CUSTOMER
                 ( DIVISION_ID
                 , END_CUSTOMER
                 , SCM_SITE_ID
                 , FROM_WEEK
                 , FROM_DAY
                 , TO_WEEK
                 , TO_DAY
                 , ACTIVE )
            SELECT A.DIVISION_ID AS DIVISION_ID
                 , A.END_CUSTOMER AS END_CUSTOMER
                 , NVL(NULLIF(RTRIM(B.SEGMENT4),''), '/') AS SCM_SITE_ID
                 , (CASE WHEN NVL(B.SEGMENT5, 'OFF') = 'OFF' THEN
                                      '-52'
                            ELSE NVL(B.ATTRIBUTE1, '-1')  END) AS FROM_WEEK
                 , NVL(B.ATTRIBUTE2, 'TUE') AS FROM_DAY
                 , NVL(B.ATTRIBUTE3, '0') AS TO_WEEK
                 , NVL(B.ATTRIBUTE4, 'MON') AS TO_DAY
                 , NVL(B.SEGMENT5, 'OFF') AS ACTIVE
              FROM SCM_MST_SITE A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL B
             WHERE B.LOOKUP_TYPE(+) = 'EDI_END_CUSTOMER'
               AND A.DIVISION_ID = B.SEGMENT1(+)
               AND A.END_CUSTOMER = B.SEGMENT2(+)
               AND B.VALID_YN(+) = 'Y'
               AND RTRIM(A.END_CUSTOMER) IS NOT NULL
             GROUP BY A.DIVISION_ID, A.END_CUSTOMER, B.SEGMENT4, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.SEGMENT5;

            MERGE INTO DM_ANL_MKT_PSI A
            USING (SELECT A.DIVISION_ID
                        , A.END_CUSTOMER
                        , A.PROJECT_CODE
                        , A.YYYYMM
                        , NVL(SUM(B.QTY), 0) AS QTY
                     FROM (SELECT B.YYYYMM, A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE
                             FROM (SELECT A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE
                                     FROM DM_PLN_MKT_FCST A
                                        , SCM_MST_SITE B
                                    WHERE A.DIVISION_ID = B.DIVISION_ID
                                      AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                      AND B.VALID_YN = 'Y'
                                      AND B.END_CUSTOMER IS NOT NULL
                                      AND A.DIVISION_ID LIKE '81%'
                                      AND RTRIM(A.PROJECT_CODE) IS NOT NULL
                                      AND A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST')
                                      AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                                      AND A.YYYYMMDD <= V_TO_YYYYMMDD
                                    GROUP BY A.DIVISION_ID, B.END_CUSTOMER, A.PROJECT_CODE
                                  ) A , GT_DAMP_SCM_SYS_CALENDAR_M B
                          ) A
                        , (
                           /*                            *  ① SCM_MST_SITE C 아우터조인 ON절이 CASE식(RTRIM(CASE...C.END_CUSTOMER...) IS NOT NULL)에 C(널생성측) 참조 → (+)불가(ORA-30563 부류) */
                           SELECT A.DIVISION_ID, A.PROJECT_CODE, C.END_CUSTOMER, SUBSTR(A.YYYYMMDD, 1, 6) YYYYMM, SUM(A.QTY) QTY
                             FROM DM_PLN_MKT_FCST_RESULT A
                                  INNER JOIN
                                  SCM_MST_SITE_ITEM B
                                    ON A.DIVISION_ID = B.DIVISION_ID
                                   AND A.PROJECT_CODE = B.PROJECT_CODE
                                   AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                   AND A.ITEM_ID = B.ITEM_ID
                                   LEFT OUTER JOIN SCM_MST_SITE C
                                       ON A.DIVISION_ID = C.DIVISION_ID
                                      AND A.SCM_SITE_ID = C.SCM_SITE_ID
                                      AND C.SITE_TYPE = 'SALES'
                                      AND C.VALID_YN = 'Y'
                                      AND RTRIM(CASE WHEN A.DIVISION_ID = '40' THEN NVL(C.END_CUSTOMER, '-')
                                                     ELSE REPLACE(C.END_CUSTOMER, '-', '') END) IS NOT NULL
                                   LEFT OUTER JOIN GT_DAMP_EDI_END_CUSTOMER D
                                       ON D.DIVISION_ID = A.DIVISION_ID
                                      AND D.END_CUSTOMER = C.END_CUSTOMER
                                      AND D.SCM_SITE_ID = A.SCM_SITE_ID
                                   LEFT OUTER JOIN GT_DAMP_EDI_END_CUSTOMER E
                                       ON A.DIVISION_ID = E.DIVISION_ID
                                      AND E.END_CUSTOMER = C.END_CUSTOMER
                                      AND E.SCM_SITE_ID = NVL(D.SCM_SITE_ID, '/')
                                   WHERE 1 = 1
                                   AND A.QTY <> 0
                                   AND A.MEASURE IN ('CUST_FCST_EDI', 'CUST_FCST')
                                   AND NVL(A.ATTRIBUTE9, '99999999') >= (SELECT BASIS_YYYYMMDD
                                                       FROM (SELECT RANK() OVER(ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK
                                                                           , A.BASIS_YYYYMMDD
                                                               FROM SCM_SYS_CALENDAR_M A
                                                               WHERE BASIS_YYYYMMDD <= (CASE WHEN TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=AMERICAN') = 'MON' THEN
                                                                                               TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
                                                                                        ELSE TO_CHAR(SYSDATE, 'YYYYMMDD') END)
                                                               AND DAYOFWEEK = E.FROM_DAY) A
                                                       WHERE A.RK = E.FROM_WEEK)
                                   AND NVL(A.ATTRIBUTE9, '19999999') <= (SELECT BASIS_YYYYMMDD
                                                       FROM (SELECT (CASE WHEN DAYOFWEEK = 'SUN' THEN RANK() OVER(ORDER BY BASIS_YYYYMMDD) - 2
                                                                          ELSE RANK() OVER(ORDER BY BASIS_YYYYMMDD) - 1 END) AS RK
                                                                           , A.BASIS_YYYYMMDD
                                                               FROM SCM_SYS_CALENDAR_M A
                                                               WHERE BASIS_YYYYMMDD >= (CASE WHEN TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=AMERICAN') = 'MON' THEN
                                                                                               TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
                                                                                        ELSE TO_CHAR(SYSDATE, 'YYYYMMDD') END)
                                                               AND DAYOFWEEK = E.TO_DAY) A
                                                       WHERE A.RK = E.TO_WEEK)
                                   AND A.YYYYMMDD >= V_FROM_YYYYMMDD
                                   AND A.YYYYMMDD <= V_TO_YYYYMMDD
                                   AND A.DIVISION_ID LIKE '81%'
                                   GROUP BY A.DIVISION_ID, A.PROJECT_CODE, C.END_CUSTOMER, SUBSTR(A.YYYYMMDD, 1, 6)
                          ) B
                    WHERE A.DIVISION_ID  = B.DIVISION_ID(+)
                      AND A.END_CUSTOMER = B.END_CUSTOMER(+)
                      AND A.PROJECT_CODE = B.PROJECT_CODE(+)
                      AND A.YYYYMM       = B.YYYYMM(+)
                    GROUP BY A.DIVISION_ID, A.END_CUSTOMER, A.PROJECT_CODE, A.YYYYMM
                  ) B
            ON ( B.DIVISION_ID  = A.DIVISION_ID
             AND B.PROJECT_CODE = A.PROJECT_CODE
             AND B.END_CUSTOMER = A.END_CUSTOMER
             AND B.YYYYMM       = A.YYYYMM )
            WHEN MATCHED THEN UPDATE SET
                  A.CUST_FCST_M      = B.QTY
                , A.LAST_UPDATED_BY  = 'BATCH SYSTEM'
                , A.LAST_UPDATE_DATE = SYSDATE
             WHERE A.CUST_FCST_M <> B.QTY;

        END;

        DBMS_OUTPUT.PUT_LINE('A6-- DM_ANL_MKT_PSI_DETAIL INSERT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /*
           DM_ANL_MKT_PSI_DETAIL 키 생성
        */
        BEGIN
            INSERT
              INTO DM_ANL_MKT_PSI_DETAIL
                 ( DIVISION_ID
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , YYYYMM
                 , CUST_FCST_M
                 , MEASURE
                 , QTYCD1
                 , QTYCD2
                 , QTYCD3
                 , SEQ
                 , QTY
                 , MKT_FCST_M
                 , "DESC"
                 , INPUT_LIMIT
                 , CUST_FCST_M_CELL
                 , QTY_CELL
                 , MKT_FCST_M_CELL
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE )
            SELECT A.DIVISION_ID
                 , A.END_CUSTOMER
                 , A.PROJECT_CODE
                 , A.YYYYMM
                 , NVL(A.CUST_FCST_M, 0)
                 , A.MEASURE
                 , ' ' AS QTYCD1
                 , ' ' AS QTYCD2
                 , ' ' AS QTYCD3
                 , 1  AS SEQ
                 , 0  AS QTY
                 , NVL(A.MKT_FCST_M, 0)
                 , '' AS "DESC"
                 , '' AS INPUT_LIMIT
                 , NVL(A.CUST_FCST_M_CELL, 0)
                 , 0  AS QTY_CELL
                 , NVL(A.MKT_FCST_M_CELL, 0)
                 , 'BATCH SYSTEM' AS CREATED_BY
                 , SYSDATE AS CREATION_DATE
                 , 'BATCH SYSTEM' AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
              FROM DM_ANL_MKT_PSI A
                 , GT_DAMP_SCM_SYS_CALENDAR_M B
                 , (SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.END_CUSTOMER
                         , A.YYYYMM
                         , A.MEASURE
                      FROM DM_ANL_MKT_PSI_DETAIL A
                         , GT_DAMP_SCM_SYS_CALENDAR_M B
                     WHERE A.YYYYMM = B.YYYYMM
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER, A.YYYYMM, A.MEASURE
                   ) C
             WHERE A.YYYYMM       = B.YYYYMM
               AND A.DIVISION_ID  = C.DIVISION_ID(+)
               AND A.END_CUSTOMER = C.END_CUSTOMER(+)
               AND A.PROJECT_CODE = C.PROJECT_CODE(+)
               AND A.YYYYMM       = C.YYYYMM(+)
               AND A.MEASURE      = C.MEASURE(+)
               AND A.MEASURE IN ('DP_INIT', 'DP_RESULT')
               AND C.YYYYMM IS NULL;
        END;

        DBMS_OUTPUT.PUT_LINE('A7-- PROJECT_DEPT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        BEGIN
            /*
             2024.02.08    kcw3408        XIF_DM_ANL_MKT_PSI_DETAIL_DW_S 테이블에 DEPT_NAME Sales Site Project Model 화면 ‘Team’칼럼 수정
            */
            DELETE FROM GT_DAMP_PROJECT_DEPT;

            INSERT
              INTO GT_DAMP_PROJECT_DEPT
                 ( DIVISION_ID
                 , PROJECT_CODE
                 , END_CUSTOMER
                 , ITEM_ID
                 , DEPT_ID
                 , DEPT_NAME_KO )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER, A.ITEM_ID, A.DEPT_ID, A.DEPT_NAME_KO
              FROM (SELECT DISTINCT
                           A.DIVISION_ID
                         , A.PROJECT_CODE
                         , B.END_CUSTOMER
                         , A.ITEM_ID
                         /* [PJ2024-50461] Team Mapping ------------------------------------ */
                         /*, B.DEPT_ID
                         , C.DEPT_NAME_KO
                         */
--                         , C.DEPT_ID
--                         , C.DEPT_NAME_KO
                         , A.DEPT_ID                                        -- 2026.09.03 AJS
                         , D.DEPT_NAME_KO                                   -- 2026.09.03 AJS
                         /* [PJ2024-50461] Team Mapping ------------------------------------ */
                         , RANK() OVER ( PARTITION BY A.DIVISION_ID, A.PROJECT_CODE, A.ITEM_ID, B.END_CUSTOMER ORDER BY A.SCM_SITE_ID) AS SEQ
                      FROM SCM_MST_SITE_ITEM A
                         , SCM_MST_SITE B
                         /* [PJ2024-50461] Team Mapping ------------------------------------
                         JOIN SCM_MST_SSO_DEPT_INFO C
                             ON  B.DEPT_ID = C.DEPT_ID
                         */
                         , (SELECT A.USER_ID, A.USER_NAME, A.USER_NAME_EN, A.DEPT_ID, B.DEPT_NAME_KO
                              FROM SCM_MST_SSO_USER_INFO A
                                 , SCM_MST_SSO_DEPT_INFO B
                             WHERE A.DEPT_ID = B.DEPT_ID
                           ) C
                         , SCM_MST_SSO_DEPT_INFO D                          -- 2026.09.03 AJS
                     WHERE A.DIVISION_ID  = B.DIVISION_ID
                       AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                       AND B.VALID_YN = 'Y'
                       AND UPPER(C.USER_ID(+)) = UPPER(FN_SCM_SPLIT(A.OWNER, 1, ','))
                       AND A.DEPT_ID = D.DEPT_ID(+)                         -- 2026.09.03 AJS
                       /* [PJ2024-50461] Team Mapping ------------------------------------ */
                       AND A.DIVISION_ID LIKE '81%'
                   ) A
             WHERE A.SEQ = 1;

        END;

        DBMS_OUTPUT.PUT_LINE('A8-- DP, CF 값 송출 기준 변경 ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        /* DP, CF값 송출 기준 변경(ITEM_TYPE이 'P', FCST_TYPE이 'MASS')----------------------------START */
        BEGIN
            DELETE FROM GT_DAMP_DM_MST_ITEM_SINGLE_V;

            INSERT
              INTO GT_DAMP_DM_MST_ITEM_SINGLE_V
                 ( DIVISION_ID
                 , ITEM_ID
                 , PROJECT_CODE )
            SELECT A.DIVISION_ID, A.ITEM_ID, B.PROJECT_CODE
              FROM DM_MST_ITEM_SINGLE_V A
                 , SCM_MST_PROJECT_ITEM B
             WHERE A.DIVISION_ID = B.DIVISION_ID
               AND A.ITEM_ID     = B.ITEM_ID
               AND A.DIVISION_ID LIKE '81%'
               AND B.VALID_YN = 'Y'
               AND A.ITEM_TYPE = 'P'
             GROUP BY A.DIVISION_ID, A.ITEM_ID, B.PROJECT_CODE;

        END;

        DBMS_OUTPUT.PUT_LINE('A9-- XIF_DM_ANL_MKT_PSI_DW_S INSERT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        BEGIN /* I/F 테이블 INSERT */
            /* **중요 -> 운영 반영시 DB명 변경 (운영:LGCE_INF, 개발:LGCE_INFDEV) --Synonym 만들어서 변경(kcw3408) XIF_DM_ANL_MKT_PSI_DW_S_SN */
            BEGIN /* I/F 테이블 해당 PROJECT 삭제 */
                DELETE
                  FROM XIF_DM_ANL_MKT_PSI_DW_S_SN;
            END;

            INSERT
              INTO XIF_DM_ANL_MKT_PSI_DW_S_SN
                 ( DIVISION_ID
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , YYYYMM
                 , CUST_FCST_M
                 , MEASURE
                 , P_VALUE
                 , S_VALUE
                 , I_VALUE
                 , V_VALUE
                 , M_VALUE
                 , MKT_FCST_M
                 , "DESC"
                 , INPUT_LIMIT
                 , CUST_FCST_M_CELL
                 , P_VALUE_CELL
                 , S_VALUE_CELL
                 , I_VALUE_CELL
                 , V_VALUE_CELL
                 , M_VALUE_CELL
                 , MKT_FCST_M_CELL
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , CP_VALUE
                 , CP_VALUE_CELL )
            SELECT DIVISION_ID
                 , END_CUSTOMER
                 , PROJECT_CODE
                 , YYYYMM
                 , CUST_FCST_M
                 , MEASURE
                 , P_VALUE
                 , S_VALUE
                 , I_VALUE
                 , V_VALUE
                 , M_VALUE
                 , MKT_FCST_M
                 , "DESC"
                 , INPUT_LIMIT
                 , CUST_FCST_M_CELL
                 , P_VALUE_CELL
                 , S_VALUE_CELL
                 , I_VALUE_CELL
                 , V_VALUE_CELL
                 , M_VALUE_CELL
                 , MKT_FCST_M_CELL
                 , CREATED_BY
                 , SYSDATE
                 , LAST_UPDATED_BY
                 , SYSDATE
                 , CP_VALUE
                 , CP_VALUE_CELL
              FROM DM_ANL_MKT_PSI
             WHERE YYYYMM IN (SELECT YYYYMM FROM GT_DAMP_SCM_SYS_CALENDAR_M);
        END;

        DBMS_OUTPUT.PUT_LINE('A10-- XIF_DM_ANL_MKT_PSI_DETAIL_DW_S INSERT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        BEGIN /* I/F 테이블 INSERT */
            /* **중요 -> 운영 반영시 DB명 변경 (운영:LGCE_INF, 개발:LGCE_INFDEV)--Synonym 만들어서 변경(kcw3408) XIF_DM_ANL_MKT_PSI_DW_S_SN */
            BEGIN /* I/F 테이블 해당 PROJECT 삭제 */
                DELETE
                  FROM XIF_DM_ANL_MKT_PSI_DETAIL_DW_S_SN;
            END;

            BEGIN

                INSERT
                  INTO XIF_DM_ANL_MKT_PSI_DETAIL_DW_S_SN
                     ( DIVISION_ID
                     , DEPT_ID
                     , DEPT_NAME_KO
                     , PROJECT_NAME
                     , PROJECT_CODE
                     , ITEM_ID
                     , END_CUSTOMER
                     , YYYYMM
                     , CUST_FCST_M
                     , MEASURE
                     , QTYCD1
                     , QTYCD2
                     , QTYCD3
                     , SEQ
                     , QTY
                     , MKT_FCST_M
                     , "DESC"
                     , INPUT_LIMIT
                     , CUST_FCST_M_CELL
                     , QTY_CELL
                     , MKT_FCST_M_CELL
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE )
                SELECT A.DIVISION_ID
                     , NVL(NULLIF(RTRIM(C.DEPT_ID),''), '/')
                     , NVL(C.DEPT_NAME_KO, ' ')
                     , SUBSTR(NVL(E.PROJECT_NAME, '-'), 1, 100)
                     , A.PROJECT_CODE
                     , NVL(NULLIF(RTRIM(B.ITEM_ID),''), '/')
                     , A.END_CUSTOMER
                     , A.YYYYMM
                     , A.CUST_FCST_M
                     , A.MEASURE
                     , A.QTYCD1
                     , A.QTYCD2
                     , A.QTYCD3
                     , A.SEQ
                     , A.QTY
                     , A.MKT_FCST_M
                     , A."DESC"
                     , A.INPUT_LIMIT
                     , A.CUST_FCST_M * NVL(D.TRANSLATOR, 0) /* A.CUST_FCST_M_CELL */
                     , A.QTY * NVL(D.TRANSLATOR, 0) /* A.QTY_CELL */
                     , A.MKT_FCST_M * NVL(D.TRANSLATOR, 0) /* A.MKT_FCST_M_CELL */
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , A.LAST_UPDATED_BY
                     , A.LAST_UPDATE_DATE
                  FROM DM_ANL_MKT_PSI_DETAIL A
                  LEFT OUTER JOIN GT_DAMP_DM_MST_ITEM_SINGLE_V B
                  ON A.DIVISION_ID = B.DIVISION_ID
                  AND A.PROJECT_CODE = B.PROJECT_CODE
                  LEFT OUTER JOIN GT_DAMP_PROJECT_DEPT C
                  ON A.DIVISION_ID = C.DIVISION_ID
                  AND A.PROJECT_CODE = C.PROJECT_CODE
                  AND A.END_CUSTOMER = C.END_CUSTOMER
                  AND B.ITEM_ID      = C.ITEM_ID
                  LEFT OUTER JOIN GT_DAMP_PROJECT_TRANSLATOR D
                  ON A.DIVISION_ID = D.DIVISION_ID
                 AND A.PROJECT_CODE = D.PROJECT_CODE
                  LEFT OUTER JOIN SCM_MST_PROJECT E
                  ON A.DIVISION_ID = E.DIVISION_ID
                  AND A.PROJECT_CODE = E.PROJECT_CODE
                 WHERE A.YYYYMM IN (SELECT YYYYMM FROM GT_DAMP_SCM_SYS_CALENDAR_M);

            END;
        END;

        DBMS_OUTPUT.PUT_LINE('A11-- COMMIT ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                ,V_LOG_TYPE
                ,N_LOG_COUNT
                ,V_LOG_MESSAGE
                ,V_DESCRIPTION
                ,D_EVENT_DATE
                ,NULL
                ,SQLCODE
                ,SQLERRM
                ,DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

            DBMS_OUTPUT.PUT_LINE('A12-- ERROR ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS') || V_LOG_MESSAGE);

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
        ,V_LOG_TYPE
        ,N_LOG_COUNT
        ,V_LOG_MESSAGE
        ,V_DESCRIPTION
        ,D_EVENT_DATE);

    DBMS_OUTPUT.PUT_LINE('A13-- END ' || TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS'));

END;
/
SHOW ERRORS PROCEDURE PR_DM_ANL_MKT_PSI_DATA
-- ##### END PROCEDURE PR_DM_ANL_MKT_PSI_DATA

-- ##### START PROCEDURE PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE
CREATE OR REPLACE PROCEDURE           "PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE" 
/*=====================================================================================================================================================
 * Program ID   : PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE
 * Description  : MKT FCST 화면에서 저장 시 호출하는 프로시져로, Sales Plan AMT Create ( Local/KRW )
 * Program History
 *=====================================================================================================================================================
 *	  Date		In Charge		Description
 *=====================================================================================================================================================
 * 2017.02.05	DWOK/KHSONG		Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.08.08					SALES_PLAN_CUTOFF  주석처리
 * 2018.08.16					DMF0003_SAVE_MKT_FCST 저장시 호출되는 프로시져
 * 2020.02.13	HWI1993 		자동차사업부 SALES AMT 메저를 RTF_SCP 기준으로 생성
 * 2020.03.09	KHSONG 			TMM_FCST ADD
 * 2020.05.07	KHSONG 			C20200507-000035 (소형사업부 RTF 관련 Measure 숨기기)
 * 2020.08.06	hwi1993			[C20200803-000105] MKT FCST 금액 Measure 추가 개발 요청의 건
 * 2020.09.09	P.C.I			[C20200909-000203] LOG 표준화 적용
 * 2020.12.08	P.C.I			[C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용
 * 2024.12.10	KJJ				[PJ2024-50611] Catch Up 메저 삭제 금지
 * 2025.01.21	JSSBAE			[E20250122-000837]_Sales Plan 화면 MKT FCST AMT. 개선요청
 * 2025.02.11	KANG.H.J		[PJ2025-50017] 소형 매출계획 동기화 개선 - SALES_PLAN에 SCM_FCST MEASURE 추가
 * 2025.06.10	KANG.H.J		[PJ2025-50017] [PJ2025-50188] 임시테이블 DROP 처리
 * 2025.09.03	JSSBAE			[E20250826-000546]_Sales Plan 계획구간 일부 매출 데이터 누락
 * 2025.09.15	JSSBAE			[E20250915-000105]_GSCM 시스템 DP 입력 오류
 * 2025.10.16	PARK.CHOYI		속도개선
 * 2025.10.31	JSSBAE			[E20251021-000634]_FCST&PRICE MGMT SALES PLAN 데이터 동기화 속도개선
 * 2026.07.06	ZIONEX			[PJ202650304] NextSCM Migration
 * 2026.09.30	admin			[E20260930-DMF0082-81SP] 81 사업부 분기 추가 (DMF0082 81 저장 실시간 동기화 — 40 분기·공통부 무수정)
 *===================================================================================================================================================*/
AS
	/*================================================================================================================================================= */
	/* 스플릿관련 변수 (START) */
	/*================================================================================================================================================= */
	V_RECV_DIVISION_ID	VARCHAR2(4000 CHAR);
	V_DELIMITER			VARCHAR2(1 CHAR);
	N_MAX_LOOP_CNT		PLS_INTEGER := 0;
	N_MST_LOOP_CNT		PLS_INTEGER := 0;
	V_DIVISION_ID		VARCHAR2(4000 CHAR);
	V_CREATED_BY		VARCHAR2(4000 CHAR);
	/*================================================================================================================================================= */
	/* 스플릿관련 변수 (END) */
	/*================================================================================================================================================= */
	/* [E20250915-000105]_당주 월요일 변수를 받아 처리한다. */
	V_THIS_WEEK_MON		VARCHAR2(8 CHAR);
	/*================================================================================================================================================= */
	/* LOG 용 변수 설정 */
	/*================================================================================================================================================= */
	V_PROGRAM_NAME		VARCHAR2(150 CHAR) := 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE';
	V_LOG_TYPE			VARCHAR2(30 CHAR);		/* START/END/ERROR/... */
	N_LOG_COUNT			PLS_INTEGER := 0;
	V_LOG_MESSAGE		VARCHAR2(1000 CHAR);
	V_DESCRIPTION		VARCHAR2(500 CHAR);
	D_EVENT_DATE		DATE;
	V_INT_COUNT			PLS_INTEGER;			/* 원본 @v_int_count (본문 중간 DECLARE -> 선언부로 이동) */

	V_PROC_INPUT		VARCHAR2(4000 CHAR);
	V_SQL_CODE			VARCHAR2(100 CHAR);
	V_SQL_ERRMSG		VARCHAR2(1000 CHAR);
	V_BACKTRACE			VARCHAR2(4000 CHAR);
BEGIN
	/*================================================================================================================================================= */

	/*   원본 MSSQL 은 프로시저 시작 시 #temp 를 DROP + CREATE 로 재생성. Oracle 은 세션 GTT(ON COMMIT PRESERVE ROWS) 를 */


	/*================================================================================================================================================= */
	DELETE FROM GT_PRMF_T2_MKT_FCST;
	DELETE FROM GT_PRMF_T2_PRICE;
	DELETE FROM GT_PRMF_RESULTS_KEY;
	DELETE FROM GT_PRMF_SALES_PLAN_TEMP;
	DELETE FROM GT_PRMF_SALES_PLAN_TEMP_KEY;

	/*================================================================================================================================================= */
	/* 스플릿관련 변수 (START) */
	/*================================================================================================================================================= */
	V_RECV_DIVISION_ID	:= NULL;
	V_DELIMITER			:= '^';		/* 데이터 구분자 */
	/* 원본 : SET @v_created_by = ISNULL((SELECT MAX(v_created_by) FROM #results GROUP BY v_division_id),'SYSTEM') */
	BEGIN
		SELECT NVL(MAX(V_CREATED_BY), 'SYSTEM') INTO V_CREATED_BY
		  FROM GT_PRDM_RESULTS
		 GROUP BY V_DIVISION_ID;
	EXCEPTION
		WHEN NO_DATA_FOUND THEN
			V_CREATED_BY := 'SYSTEM';
	END;
	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	/* [E20250915-000105]_당주 월요일 변수를 받아 처리한다. */
	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	V_THIS_WEEK_MON := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');
	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	/* [PJ2025-50017] 소형 매출계획 동기화 개선 */
	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	SELECT MAX(V_DIVISION_ID) INTO V_DIVISION_ID FROM GT_PRDM_RESULTS;
	/*================================================================================================================================================= */
	/* 스플릿관련 변수 (END) */
	/*================================================================================================================================================= */

	/*================================================================================================================================================= */
	/* 시작 LOG  (START) */
	/*================================================================================================================================================= */
	V_LOG_TYPE		:= 'START';
	V_LOG_MESSAGE	:= '########## Start of procedure ##########';
	V_DESCRIPTION	:= '';
	D_EVENT_DATE	:= SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
	V_LOG_MESSAGE	:= NULL;		/*-- <- 변수 재사용을 위하여 초기화해야함 --*/
	/*================================================================================================================================================= */
	/* 시작 LOG  (END) */
	/*================================================================================================================================================= */

	DBMS_OUTPUT.PUT_LINE('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE : A00A--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

	/* [PJ2025-50017] 40 사업부는 DM_PLN_CFM_MKT_DEMAND_PLAN, DM_PLN_CFM_SELLING_PRICE 기반 데이터 생성 */
	/* [PJ2025-50017] 40 외 사업부는 DM_PLN_MKT_FCST, SCM_MST_FUTURE_PRICE 기반 데이터 생성. (단 CELL_PROD_SITE_ID는 '-'로 처리) START */
	IF (V_DIVISION_ID = '40') THEN

		SELECT COUNT(*) INTO N_LOG_COUNT
		  FROM GT_PRDM_RESULTS;

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS 데이터 로그생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		V_LOG_TYPE		:= 'ING';	/*[C20200909-000203] LOG 표준화 적용 */
		V_LOG_MESSAGE	:= 'step-01-INSERT #RESULTS';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS 데이터 로그생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS_KEY 데이터 생성 (START) */
		/* #RESULTS 에 들어오는 데이터는 MKT_FCST, SCM_FCST, LOC 메져이므로 MEASURE를 제외한 Sales Plan 테이블을 동기화 하기 위한 MIN, MAX YYYYMMDD 기준의 데이터만 필요 함 */
		/* AS-IS : 데이터를 가져올때 YYYYMMDD에 대한 기준이 없음, Measure 조건도 없음, 그러다보니 Join 중복데이터가 발생 함 */
		/* TO-BE : Measure, YYYYMMDD 를 제외한 Key 값 기준으로 #RESULTS_KEY 임시테이블 생성( MIN, MAX YYYYMMDD ) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_RESULTS_KEY
		( V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
		, V_MIN_YYYYMMDD, V_MAX_YYYYMMDD )
		SELECT A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP, A.V_FCST_TYPE, A.V_INCOTERMS, A.V_PLANT_SITE_ID
			 , D_MIN.BASIS_START_DATE
			 , D_MAX.BASIS_END_DATE
		  FROM ( SELECT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
					  , MIN(V_YYYYMMDD) AS MIN_DATE
					  , MAX(V_YYYYMMDD) AS MAX_DATE
				   FROM GT_PRDM_RESULTS
				  GROUP BY V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID ) A
		  JOIN SCM_SYS_CALENDAR_M D_MIN ON D_MIN.BASIS_YYYYMMDD = A.MIN_DATE
		  JOIN SCM_SYS_CALENDAR_M D_MAX ON D_MAX.BASIS_YYYYMMDD = A.MAX_DATE;
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS_KEY 데이터 생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS_KEY 데이터 로그생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		V_LOG_TYPE		:= 'ING';	/*[C20200909-000203] LOG 표준화 적용 */
		V_LOG_MESSAGE	:= 'step-01-01-INSERT #RESULTS_KEY';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#RESULTS_KEY 데이터 로그생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		DBMS_OUTPUT.PUT_LINE('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE : A00C--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* DM_PLN_CFM_MKT_DEMAND_PLAN과 받아온 MKT FCST 정보를 JOIN하여 TEMP TABLE 생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_T2_MKT_FCST
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, BASIS_START_DATE )	/* [E20250915-000105]_당주 월요일 변수를 신규 생성 */
		SELECT A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP, A.V_FCST_TYPE, A.V_INCOTERMS, C.MEASURE, A.V_PLANT_SITE_ID, C.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , C.YYYYMMDD, C.QTY, V_CREATED_BY, SYSDATE
			 , D.BASIS_START_DATE	/* [E20250915-000105]_당주 월요일 변수를 신규 생성 */
		  FROM GT_PRMF_RESULTS_KEY A	/*#results A --[E20251021-000634]_#RESULTS_KEY 테이블로 변경 */
		  JOIN DM_PLN_CFM_MKT_DEMAND_PLAN C
			ON A.V_DIVISION_ID		= C.DIVISION_ID
		   AND A.V_PROJECT_CODE		= C.PROJECT_CODE
		   AND A.V_SCM_SITE_ID		= C.SCM_SITE_ID
		   AND A.V_ITEM_ID			= C.ITEM_ID
		   AND A.V_DOM_EXP			= C.DOM_EXP
		   AND A.V_FCST_TYPE		= C.FCST_TYPE
		   AND A.V_INCOTERMS		= C.INCOTERMS
		   AND A.V_PLANT_SITE_ID	= CASE WHEN A.V_DIVISION_ID = '81' THEN C.PLANT_SITE_ID ELSE A.V_PLANT_SITE_ID END
		   /*AND A.V_CELL_PROD_SITE_ID = C.CELL_PROD_SITE_ID	-- [PJ2025-50017] 중요(results에 V_CELL_PROD_SITE_ID 없음) */
		   /*AND C.QTY > 0 */
		  JOIN SCM_SYS_CALENDAR_M D
			ON D.BASIS_YYYYMMDD = C.YYYYMMDD
		 WHERE C.MEASURE IN ('MKT_FCST', 'SCM_FCST', 'RTF_SYS_RP')	/*[E20251021-000634]_필수 Measure 조건 추가 */
		   AND C.YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD	/*[E20251021-000634]_MIN, MAX YYYYMMDD 조건 추가 */
		   AND D.BASIS_YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD	/*[E20251021-000634]_MIN, MAX YYYYMMDD 조건 추가 */
		   AND C.QTY <> 0;	/*[E20251021-000634]_ 0 제외 */

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#T2_MKT_FCST 데이터 로그생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		V_LOG_MESSAGE	:= 'step-01-02-INSERT #T2_MKT_FCST  ';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#T2_MKT_FCST 데이터 로그생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* DM_PLN_CFM_MKT_DEMAND_PLAN과 받아온 정보를 JOIN하여 TEMP TABLE 생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		DBMS_OUTPUT.PUT_LINE('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE : A00D--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* DM_PLN_CFM_SELLING_PRICE과 받아온 정보를 JOIN하여 TEMP TABLE 생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */


		INSERT INTO GT_PRMF_T2_PRICE	/*#TEMP_PRICE -- [E20251021-000634]_#T2_MKT_FCST (최종) 테이블로 변경 */
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, CURRENCY, MEASURE, YYYYMMDD, PRICE, CREATED_BY, CREATION_DATE )
		SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
			 , CURRENCY, MEASURE, YYYYMMDD, PRICE, CREATED_BY, CREATION_DATE
		  FROM ( SELECT A.V_DIVISION_ID AS DIVISION_ID, A.V_PROJECT_CODE AS PROJECT_CODE, A.V_SCM_SITE_ID AS SCM_SITE_ID, A.V_ITEM_ID AS ITEM_ID, A.V_DOM_EXP AS DOM_EXP, A.V_FCST_TYPE AS FCST_TYPE, A.V_INCOTERMS AS INCOTERMS, A.V_PLANT_SITE_ID AS PLANT_SITE_ID, C.CELL_PROD_SITE_ID AS CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
					  , C.CURRENCY, C.MEASURE, C.YYYYMMDD, C.PRICE, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE
					  , ROW_NUMBER() OVER (
							PARTITION BY A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP
								   , A.V_FCST_TYPE, A.V_INCOTERMS, NVL(TRIM(A.V_PLANT_SITE_ID), '-'), NVL(TRIM(C.CELL_PROD_SITE_ID), '-')
								   , C.MEASURE, C.YYYYMMDD
							ORDER BY C.PRICE DESC ) AS RN
			   FROM GT_PRMF_RESULTS_KEY A	/*#results A -- [E20251021-000634]_#RESULTS_KEY 테이블로 변경 */
			   JOIN DM_PLN_CFM_SELLING_PRICE C
				 ON A.V_DIVISION_ID		= C.DIVISION_ID
				AND A.V_PROJECT_CODE	= C.PROJECT_CODE
				AND A.V_SCM_SITE_ID		= C.SCM_SITE_ID
				AND A.V_ITEM_ID			= C.ITEM_ID
				AND A.V_DOM_EXP			= C.DOM_EXP
				AND A.V_FCST_TYPE		= C.FCST_TYPE
				AND A.V_INCOTERMS		= C.INCOTERMS
				AND A.V_PLANT_SITE_ID	= CASE WHEN A.V_DIVISION_ID = '81' THEN C.PLANT_SITE_ID ELSE A.V_PLANT_SITE_ID END
				/*AND A.V_CELL_PROD_SITE_ID = C.CELL_PROD_SITE_ID		-- [PJ2025-50017] 중요(results에 V_CELL_PROD_SITE_ID 없음) */
			  WHERE C.PRICE > 0
				AND C.YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD )	/* [E20251021-000634]_MIN, MAX YYYYMMDD 조건 추가 */
		 WHERE RN = 1;
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* DM_PLN_CFM_SELLING_PRICE과 받아온 정보를 JOIN하여 TEMP TABLE 생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_T2_PRICE 데이터 로그생성 (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		V_LOG_MESSAGE	:= 'step-01-03-INSERT #T2_PRICE  ';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20251021-000634]_#T2_MKT_FCST 데이터 로그생성 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		DBMS_OUTPUT.PUT_LINE('PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE : A00E--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
	/*[E20260930-DMF0082-81SP] 81 사업부 — DMF0082 81 저장 실시간 Sales Plan 동기화 (AS-IS [PJ2025-50017] 예고분 "40 외 사업부는
	   DM_PLN_MKT_FCST, SCM_MST_FUTURE_PRICE 기반 데이터 생성 (CELL_PROD_SITE_ID '-')" 구현 — AS-IS 코드는 40 분기만 존재).
	   원천 = 배치 PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW 비-40 분기와 동일 (81 Sales Plan 을 지금 만드는 경로와 값 일치):
	     MKT_FCST·SCM_FCST = DM_PLN_MKT_FCST (CELL_PROD '-') · RTF_SYS_RP = DM_PLN_CFM_MKT_DEMAND_PLAN (CELL_PROD 실값 — 81 Sales Plan
	     RTF/SalesAmt 는 셀생산지를 가진다, 사내 실측 5,648행 = CFM 동수) · 판가 = SCM_MST_FUTURE_PRICE (셀생산지 컬럼 없음).
	   배치는 RTF 금액 조인에서 CELL_PROD 를 빼므로(LOCAL_KRW L411~442), 판가 행을 T2 에 실재하는 셀생산지별로 복제해
	   아래 공통부(CELL_PROD 포함 조인)와 등가로 만든다. 81 PLANT 는 키 일치(40 블록 CASE '81' 의도와 동일).
	   40 분기·공통부 무수정. */
	ELSIF (SUBSTR(V_DIVISION_ID, 1, 2) = '81') THEN

		SELECT COUNT(*) INTO N_LOG_COUNT
		  FROM GT_PRDM_RESULTS;

		INSERT INTO GT_PRMF_RESULTS_KEY
		( V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
		, V_MIN_YYYYMMDD, V_MAX_YYYYMMDD )
		SELECT A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP, A.V_FCST_TYPE, A.V_INCOTERMS, A.V_PLANT_SITE_ID
			 , D_MIN.BASIS_START_DATE
			 , D_MAX.BASIS_END_DATE
		  FROM ( SELECT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
					  , MIN(V_YYYYMMDD) AS MIN_DATE
					  , MAX(V_YYYYMMDD) AS MAX_DATE
				   FROM GT_PRDM_RESULTS
				  GROUP BY V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID ) A
		  JOIN SCM_SYS_CALENDAR_M D_MIN ON D_MIN.BASIS_YYYYMMDD = A.MIN_DATE
		  JOIN SCM_SYS_CALENDAR_M D_MAX ON D_MAX.BASIS_YYYYMMDD = A.MAX_DATE;

		INSERT INTO GT_PRMF_T2_MKT_FCST
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
		, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, BASIS_START_DATE )
		SELECT A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP, A.V_FCST_TYPE, A.V_INCOTERMS, C.MEASURE, A.V_PLANT_SITE_ID, '-'
			 , C.YYYYMMDD, C.QTY, V_CREATED_BY, SYSDATE
			 , D.BASIS_START_DATE
		  FROM GT_PRMF_RESULTS_KEY A
		  JOIN DM_PLN_MKT_FCST C
			ON A.V_DIVISION_ID		= C.DIVISION_ID
		   AND A.V_PROJECT_CODE		= C.PROJECT_CODE
		   AND A.V_SCM_SITE_ID		= C.SCM_SITE_ID
		   AND A.V_ITEM_ID			= C.ITEM_ID
		   AND A.V_DOM_EXP			= C.DOM_EXP
		   AND A.V_FCST_TYPE		= C.FCST_TYPE
		   AND A.V_INCOTERMS		= C.INCOTERMS
		   AND A.V_PLANT_SITE_ID	= C.PLANT_SITE_ID
		  JOIN SCM_SYS_CALENDAR_M D
			ON D.BASIS_YYYYMMDD = C.YYYYMMDD
		 WHERE C.MEASURE IN ('MKT_FCST', 'SCM_FCST')
		   AND C.YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD
		   AND C.QTY <> 0
		UNION ALL
		SELECT A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP, A.V_FCST_TYPE, A.V_INCOTERMS, C.MEASURE, A.V_PLANT_SITE_ID, NVL(NULLIF(RTRIM(C.CELL_PROD_SITE_ID),''), '/')
			 , C.YYYYMMDD, C.QTY, V_CREATED_BY, SYSDATE
			 , D.BASIS_START_DATE
		  FROM GT_PRMF_RESULTS_KEY A
		  JOIN DM_PLN_CFM_MKT_DEMAND_PLAN C
			ON A.V_DIVISION_ID		= C.DIVISION_ID
		   AND A.V_PROJECT_CODE		= C.PROJECT_CODE
		   AND A.V_SCM_SITE_ID		= C.SCM_SITE_ID
		   AND A.V_ITEM_ID			= C.ITEM_ID
		   AND A.V_DOM_EXP			= C.DOM_EXP
		   AND A.V_FCST_TYPE		= C.FCST_TYPE
		   AND A.V_INCOTERMS		= C.INCOTERMS
		   AND A.V_PLANT_SITE_ID	= C.PLANT_SITE_ID
		  JOIN SCM_SYS_CALENDAR_M D
			ON D.BASIS_YYYYMMDD = C.YYYYMMDD
		 WHERE C.MEASURE = 'RTF_SYS_RP'
		   AND C.YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD
		   AND C.QTY <> 0;

		N_LOG_COUNT := SQL%ROWCOUNT;
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-01-02-INSERT #T2_MKT_FCST (81)';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

		INSERT INTO GT_PRMF_T2_PRICE
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
		, CURRENCY, MEASURE, YYYYMMDD, PRICE, CREATED_BY, CREATION_DATE )
		SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
			 , CURRENCY, MEASURE, YYYYMMDD, PRICE, CREATED_BY, CREATION_DATE
		  FROM ( SELECT A.V_DIVISION_ID AS DIVISION_ID, A.V_PROJECT_CODE AS PROJECT_CODE, A.V_SCM_SITE_ID AS SCM_SITE_ID, A.V_ITEM_ID AS ITEM_ID, A.V_DOM_EXP AS DOM_EXP, A.V_FCST_TYPE AS FCST_TYPE, A.V_INCOTERMS AS INCOTERMS, A.V_PLANT_SITE_ID AS PLANT_SITE_ID, CP.CELL_PROD_SITE_ID AS CELL_PROD_SITE_ID
					  , C.CURRENCY, C.MEASURE, C.YYYYMMDD, C.PRICE, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE
					  , ROW_NUMBER() OVER (
							PARTITION BY A.V_DIVISION_ID, A.V_PROJECT_CODE, A.V_SCM_SITE_ID, A.V_ITEM_ID, A.V_DOM_EXP
								   , A.V_FCST_TYPE, A.V_INCOTERMS, NVL(TRIM(A.V_PLANT_SITE_ID), '-'), NVL(TRIM(CP.CELL_PROD_SITE_ID), '-')
								   , C.MEASURE, C.YYYYMMDD
							ORDER BY C.PRICE DESC ) AS RN
				   FROM GT_PRMF_RESULTS_KEY A
				   JOIN SCM_MST_FUTURE_PRICE C
					 ON A.V_DIVISION_ID		= C.DIVISION_ID
					AND A.V_PROJECT_CODE	= C.PROJECT_CODE
					AND A.V_SCM_SITE_ID		= C.SCM_SITE_ID
					AND A.V_ITEM_ID			= C.ITEM_ID
					AND A.V_DOM_EXP			= C.DOM_EXP
					AND A.V_FCST_TYPE		= C.FCST_TYPE
					AND A.V_INCOTERMS		= C.INCOTERMS
					AND A.V_PLANT_SITE_ID	= C.PLANT_SITE_ID
				   JOIN ( SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
							FROM GT_PRMF_T2_MKT_FCST ) CP	/* 셀생산지별 판가 복제 — 배치 RTF 금액 조인의 CELL_PROD 무시와 등가 */
					 ON CP.DIVISION_ID		= A.V_DIVISION_ID
					AND CP.PROJECT_CODE		= A.V_PROJECT_CODE
					AND CP.SCM_SITE_ID		= A.V_SCM_SITE_ID
					AND CP.ITEM_ID			= A.V_ITEM_ID
					AND CP.DOM_EXP			= A.V_DOM_EXP
					AND CP.FCST_TYPE		= A.V_FCST_TYPE
					AND CP.INCOTERMS		= A.V_INCOTERMS
					AND CP.PLANT_SITE_ID	= A.V_PLANT_SITE_ID
				  WHERE C.PRICE > 0
					AND C.MEASURE IN ('KRW', 'LOC', 'USD')
					AND C.YYYYMMDD BETWEEN A.V_MIN_YYYYMMDD AND A.V_MAX_YYYYMMDD )
		 WHERE RN = 1;

		N_LOG_COUNT := SQL%ROWCOUNT;
		V_LOG_MESSAGE	:= 'step-01-03-INSERT #T2_PRICE (81)';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
	END IF;

	/*------------------------------------------------------------------------------------------------------------------------------------------------- */

	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	BEGIN
		/* 확인용 */
		/*SELECT '#results' */
		/*SELECT * FROM #results */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* MULTI & SINGLE ROW (START) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A001--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
		/*================================================================================================================================================= */
		/* DM_PLN_SALES_PLAN용 TEMP TABLE 생성 */
		/*   원본 : SELECT ... INTO #SALES_PLAN_TEMP FROM DM_PLN_SALES_PLAN WHERE DIVISION_ID='x' (0행, 구조 확보 목적) */
		/*          -> Oracle 은 GT_PRMF_SALES_PLAN_TEMP 를 사전 정의(구조 = DM_PLN_SALES_PLAN 서브셋)하므로 별도 구조확보 불필요. */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A002--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*================================================================================================================================================= */
		/* Temp 테이블에 저장  (START) */
		/*================================================================================================================================================= */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* MKT FCST 값을 UPDATE 함. */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS, W.MEASURE, W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , W.YYYYMMDD, SI.CURRENCY, W.QTY
			 , NVL(W.CREATED_BY, 'SYSTEM')
			 , W.CREATION_DATE	/*,w.LAST_UPDATED_BY --[2018-03-15][수정]--,w.LAST_UPDATE_DATE--[2018-03-15][수정] */
			 , V_CREATED_BY		/*[2018-03-15][수정][입력받은 매개변수로 처리] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE IN ('MKT_FCST','CUST_FCST' ,'TMM_FCST', 'SCM_FCST', 'RTF_SYS_RP') ) W	/*[E20251021-000634]_ 'CUST_FCST' ,'TMM_FCST' 삭제, 'RTF_SYS_RP' 추가 */
		  /*LEFT OUTER JOIN #T2_PRICE SI WITH(NOLOCK) -- [E20250915-000105]_테이블 변경 GROUP BY한 데이터를 기준으로 가져옴 */
		  LEFT OUTER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE IN ('LOC') ) SI	/* #TEMP_DISTINCT_PRICE SI WITH(NOLOCK) --[E20251021-000634]_중복데이터가 제거되었으므로 #T2_PRICE 로 변경. LOC Measure 조건 추가 */
				 ON ( 1 = 1
				AND W.DIVISION_ID		= SI.DIVISION_ID
				AND W.PROJECT_CODE		= SI.PROJECT_CODE
				AND W.SCM_SITE_ID		= SI.SCM_SITE_ID
				AND W.ITEM_ID			= SI.ITEM_ID
				AND W.DOM_EXP			= SI.DOM_EXP
				AND W.FCST_TYPE			= SI.FCST_TYPE
				AND W.INCOTERMS			= SI.INCOTERMS
				AND W.PLANT_SITE_ID		= SI.PLANT_SITE_ID
				AND W.CELL_PROD_SITE_ID	= SI.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
				/*AND W.YYYYMMDD		= SI.YYYYMMDD */
				AND W.BASIS_START_DATE	= SI.YYYYMMDD	/*[E20251021-000634]_MIN, MAX 가 적용된 YYYYMMDD 조건 추가 */
				 );

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-01-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02- INSERT #SALES_PLAN_TEMP MKT_FCST, SCM_FCST, RTF_SYS_RP  저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-01-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A003--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* KRW 값을 계산 */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS, 'SalesAmt_KRW' AS MEASURE, W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , W.YYYYMMDD, FP.CURRENCY	/*,cast( STR( w.QTY * isnull (FP.PRICE , 1) , 20, 5 ) as numeric) */
			 , ROUND(W.QTY * NVL(FP.PRICE, 0), 5)	/* 원본 CAST(STR(W.QTY*ISNULL(FP.PRICE,0),20,5) AS NUMERIC(30,10)) : STR(x,20,5)=소수5자리 반올림 -> ROUND(x,5) */
			 /*,w.CREATED_BY --[2018-03-15][수정] --,w.CREATION_DATE --[2018-03-15][수정] --,w.LAST_UPDATED_BY --[2018-03-15][수정] --,w.LAST_UPDATE_DATE--[2018-03-15][수정] */
			 , V_CREATED_BY		/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , 'SYSTEM'			/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE = 'RTF_SYS_RP' ) W
		  INNER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE = 'KRW' ) FP
				 ON (	FP.DIVISION_ID		= W.DIVISION_ID
				AND	FP.PROJECT_CODE			= W.PROJECT_CODE
				AND	FP.SCM_SITE_ID			= W.SCM_SITE_ID
				AND	FP.ITEM_ID				= W.ITEM_ID
				AND	FP.DOM_EXP				= W.DOM_EXP
				AND	FP.FCST_TYPE			= W.FCST_TYPE
				AND	FP.INCOTERMS			= W.INCOTERMS
				AND	FP.PLANT_SITE_ID		= W.PLANT_SITE_ID
				AND	FP.CELL_PROD_SITE_ID	= W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
				AND	FP.YYYYMMDD				= W.BASIS_START_DATE
				)
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* Sales Plan을 Unsync 하고 한번이라도 수정한 건에 대해서는 삭제 하지 않음. */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		 WHERE ( SELECT COUNT(1)
				   FROM SCM_MST_SITE_ITEM A
					  , DM_PLN_SALES_PLAN B
				  WHERE A.SALES_PLAN_ADJUST_YN = 'N'
					AND A.ITEM_ID		= B.ITEM_ID
					AND A.DIVISION_ID	= B.DIVISION_ID
					AND A.PROJECT_CODE	= B.PROJECT_CODE
					AND A.SCM_SITE_ID	= B.SCM_SITE_ID
					AND B.LAST_UPDATED_BY NOT IN ( 'SYSTEM','CUTOFF' )
					AND B.YYYYMMDD		>= V_THIS_WEEK_MON
					AND A.DIVISION_ID	= W.DIVISION_ID
					AND A.PROJECT_CODE	= W.PROJECT_CODE
					AND A.SCM_SITE_ID	= W.SCM_SITE_ID
					AND A.ITEM_ID		= W.ITEM_ID ) = 0;

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-01-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-01 - Insert #SALES_PLAN_TEMP SalesAmt_KRW 저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-01-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A004--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* LOC 값을 계산 */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS, 'SalesAmt_LOC' AS MEASURE, W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , W.YYYYMMDD, FP.CURRENCY	/*,cast( STR( w.QTY * isnull (FP.PRICE , 1) , 20, 5 ) as numeric) */
			 , ROUND(W.QTY * NVL(FP.PRICE, 0), 5)	/* 원본 CAST(STR(...,20,5) AS NUMERIC(30,10)) -> ROUND(x,5) */
			 /*,w.CREATED_BY --[2018-03-15][수정] --,w.CREATION_DATE --[2018-03-15][수정] --,w.LAST_UPDATED_BY --[2018-03-15][수정]	--,w.LAST_UPDATE_DATE --[2018-03-15][수정] */
			 , V_CREATED_BY		/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , 'SYSTEM'			/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE = 'RTF_SYS_RP' ) W
		  INNER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE = 'LOC' ) FP
				 ON ( FP.DIVISION_ID		= W.DIVISION_ID
				AND	FP.PROJECT_CODE			= W.PROJECT_CODE
				AND	FP.SCM_SITE_ID			= W.SCM_SITE_ID
				AND	FP.ITEM_ID				= W.ITEM_ID
				AND	FP.DOM_EXP				= W.DOM_EXP
				AND	FP.FCST_TYPE			= W.FCST_TYPE
				AND	FP.INCOTERMS			= W.INCOTERMS
				AND	FP.PLANT_SITE_ID		= W.PLANT_SITE_ID
				AND	FP.CELL_PROD_SITE_ID	= W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
				AND	FP.YYYYMMDD				= W.BASIS_START_DATE
				)
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* Sales Plan을 Unsync 하고 한번이라도 수정한 건에 대해서는 삭제 하지 않음. */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		 WHERE ( SELECT COUNT(1)
				   FROM SCM_MST_SITE_ITEM A
					  , DM_PLN_SALES_PLAN B
				  WHERE A.SALES_PLAN_ADJUST_YN = 'N'
					AND A.ITEM_ID		= B.ITEM_ID
					AND A.DIVISION_ID	= B.DIVISION_ID
					AND A.PROJECT_CODE	= B.PROJECT_CODE
					AND A.SCM_SITE_ID	= B.SCM_SITE_ID
					AND B.LAST_UPDATED_BY NOT IN ( 'SYSTEM','CUTOFF' )
					AND B.YYYYMMDD		>= V_THIS_WEEK_MON
					AND A.DIVISION_ID	= W.DIVISION_ID
					AND A.PROJECT_CODE	= W.PROJECT_CODE
					AND A.SCM_SITE_ID	= W.SCM_SITE_ID
					AND A.ITEM_ID		= W.ITEM_ID ) = 0;

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-02-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-02 - Insert #SALES_PLAN_TEMP SalesAmt_LOC 저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-02-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A005--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS, 'SalesAmt_USD' AS MEASURE, W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , W.YYYYMMDD, FP.CURRENCY	/*,cast( STR( w.QTY * isnull (FP.PRICE , 1) , 20, 5 ) as numeric) */
			 , ROUND(W.QTY * NVL(FP.PRICE, 0), 5)	/* 원본 CAST(STR(...,20,5) AS NUMERIC(30,10)) -> ROUND(x,5) */
			 /*,w.CREATED_BY --[2018-03-15][수정] --,w.CREATION_DATE --[2018-03-15][수정] --,w.LAST_UPDATED_BY --[2018-03-15][수정]	--,w.LAST_UPDATE_DATE --[2018-03-15][수정] */
			 , V_CREATED_BY		/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , 'SYSTEM'			/*[2018-03-15][수정] */
			 , SYSDATE			/*[2018-03-15][수정] */
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE = 'RTF_SYS_RP' ) W
		  INNER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE = 'USD' ) FP
				 ON ( FP.DIVISION_ID		= W.DIVISION_ID
				AND	FP.PROJECT_CODE			= W.PROJECT_CODE
				AND	FP.SCM_SITE_ID			= W.SCM_SITE_ID
				AND	FP.ITEM_ID				= W.ITEM_ID
				AND	FP.DOM_EXP				= W.DOM_EXP
				AND	FP.FCST_TYPE			= W.FCST_TYPE
				AND	FP.INCOTERMS			= W.INCOTERMS
				AND	FP.PLANT_SITE_ID		= W.PLANT_SITE_ID
				AND	FP.CELL_PROD_SITE_ID	= W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
				AND	FP.YYYYMMDD				= W.BASIS_START_DATE
				)
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* Sales Plan을 Unsync 하고 한번이라도 수정한 건에 대해서는 삭제 하지 않음. */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		 WHERE ( SELECT COUNT(1)
				   FROM SCM_MST_SITE_ITEM A
					  , DM_PLN_SALES_PLAN B
				  WHERE A.SALES_PLAN_ADJUST_YN = 'N'
					AND A.ITEM_ID		= B.ITEM_ID
					AND A.DIVISION_ID	= B.DIVISION_ID
					AND A.PROJECT_CODE	= B.PROJECT_CODE
					AND A.SCM_SITE_ID	= B.SCM_SITE_ID
					AND B.LAST_UPDATED_BY NOT IN ( 'SYSTEM','CUTOFF' )
					AND B.YYYYMMDD		>= V_THIS_WEEK_MON
					AND A.DIVISION_ID	= W.DIVISION_ID
					AND A.PROJECT_CODE	= W.PROJECT_CODE
					AND A.SCM_SITE_ID	= W.SCM_SITE_ID
					AND A.ITEM_ID		= W.ITEM_ID ) = 0;

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-03-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-03 - Insert #SALES_PLAN_TEMP SalesAmt_USD 저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-03-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A006--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS
			 , 'MKT_AMT_LOC' AS MEASURE
			 , W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , W.YYYYMMDD, FP.CURRENCY
			 , ROUND(W.QTY * NVL(FP.PRICE, 0), 5) AS QTY	/* 원본 CAST(STR(...,20,5) AS NUMERIC(30,10)) -> ROUND(x,5) */
			 , V_CREATED_BY, SYSDATE, 'SYSTEM', SYSDATE
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE = 'MKT_FCST' ) W
		  INNER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE = 'LOC' ) FP
				 ON ( FP.DIVISION_ID		= W.DIVISION_ID
				AND	FP.PROJECT_CODE			= W.PROJECT_CODE
				AND	FP.SCM_SITE_ID			= W.SCM_SITE_ID
				AND	FP.ITEM_ID				= W.ITEM_ID
				AND	FP.DOM_EXP				= W.DOM_EXP
				AND	FP.FCST_TYPE			= W.FCST_TYPE
				AND	FP.INCOTERMS			= W.INCOTERMS
				AND	FP.PLANT_SITE_ID		= W.PLANT_SITE_ID
				AND	FP.CELL_PROD_SITE_ID	= W.CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
				AND	FP.YYYYMMDD				= W.BASIS_START_DATE
				);

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-04-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-04 - Insert #SALES_PLAN_TEMP MKT_AMT_LOC 저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-04-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A007--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		INSERT INTO GT_PRMF_SALES_PLAN_TEMP
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY
		, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS
			 , 'MKT_AMT_KRW' AS MEASURE
			 , W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID
			 , W.YYYYMMDD, FP.CURRENCY
			 , ROUND(W.QTY * NVL(FP.PRICE, 0), 5) AS QTY	/* 원본 CAST(STR(...,20,5) AS NUMERIC(30,10)) -> ROUND(x,5) */
			 , V_CREATED_BY, SYSDATE, 'SYSTEM', SYSDATE
			 , NULL, NULL, NULL, NULL, NULL
			 , NULL, NULL, NULL, NULL, NULL
		  FROM ( SELECT * FROM GT_PRMF_T2_MKT_FCST WHERE MEASURE = 'MKT_FCST' ) W
		  INNER JOIN ( SELECT * FROM GT_PRMF_T2_PRICE WHERE MEASURE = 'KRW' ) FP
				 ON ( FP.DIVISION_ID		= W.DIVISION_ID
				AND	FP.PROJECT_CODE			= W.PROJECT_CODE
				AND	FP.SCM_SITE_ID			= W.SCM_SITE_ID
				AND	FP.ITEM_ID				= W.ITEM_ID
				AND	FP.DOM_EXP				= W.DOM_EXP
				AND	FP.FCST_TYPE			= W.FCST_TYPE
				AND	FP.INCOTERMS			= W.INCOTERMS
				AND	FP.PLANT_SITE_ID		= W.PLANT_SITE_ID
				AND	FP.CELL_PROD_SITE_ID	= W.CELL_PROD_SITE_ID
				AND	FP.YYYYMMDD				= W.BASIS_START_DATE
				);

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-05-LOG  (START) -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-05 - Insert #SALES_PLAN_TEMP MKT_AMT_KRW 저장';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-05-LOG (END)  -- [E20250915-000105]_로그추가 */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A008--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* [E20250915-000105]_나눠서 저장하도록 수정 (END) */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		SELECT COUNT(1) INTO V_INT_COUNT FROM GT_PRMF_SALES_PLAN_TEMP;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-06-LOG  (START) */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-02-06 - INSERT #SALES_PLAN_TEMP END';
		N_LOG_COUNT		:= V_INT_COUNT;
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-02-06-LOG (END) */
		/*================================================================================================================================================= */
		/*================================================================================================================================================= */
		/* 테이블의 중복제거 (START) */
		/*================================================================================================================================================= */
		BEGIN
			/*------------------------------------------------------------------------------------------------------------------------------------------------- */
			/*[E20251021-000634]_#SALES_PLAN_TEMP_KEY 테이블, 데이터 생성 (START) */
			/*------------------------------------------------------------------------------------------------------------------------------------------------- */
			INSERT INTO GT_PRMF_SALES_PLAN_TEMP_KEY
			( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
			, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
			, V_MIN_YYYYMMDD, V_MAX_YYYYMMDD )
			SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
				 , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
				 , MIN(YYYYMMDD) AS V_MIN_YYYYMMDD
				 , MAX(YYYYMMDD) AS V_MAX_YYYYMMDD	/* YYYYMMDD 를 제외한 Key 값 기준의 MIN, MAX YYYYMMDD 테이블 생성 */
			  FROM GT_PRMF_SALES_PLAN_TEMP
			 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
					, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID;

			DELETE FROM DM_PLN_SALES_PLAN A
			 WHERE EXISTS ( SELECT 1
							  FROM GT_PRMF_SALES_PLAN_TEMP_KEY C	/* #SALES_PLAN_TEMP B WITH(NOLOCK) -- [E20251021-000634]_YYYYMMDD 는 MIN, MAX YYYYMMDD 적용 */
							 WHERE A.DIVISION_ID		= C.DIVISION_ID
							   AND A.PROJECT_CODE		= C.PROJECT_CODE
							   AND A.SCM_SITE_ID		= C.SCM_SITE_ID
							   AND A.ITEM_ID			= C.ITEM_ID
							   AND A.DOM_EXP			= C.DOM_EXP
							   AND A.FCST_TYPE			= C.FCST_TYPE
							   AND A.INCOTERMS			= C.INCOTERMS
							   AND A.MEASURE			= C.MEASURE
							   AND A.PLANT_SITE_ID		= C.PLANT_SITE_ID
							   AND A.CELL_PROD_SITE_ID	= C.CELL_PROD_SITE_ID
							   AND A.YYYYMMDD BETWEEN C.V_MIN_YYYYMMDD AND C.V_MAX_YYYYMMDD );	/* [E20251021-000634]_누락되는 YYYYMMDD가 존재할 수 있으므로 MIN, MAX YYYYMMDD 기간의 데이터를 모두 삭제 */
			/*------------------------------------------------------------------------------------------------------------------------------------------------- */
			/*[E20251021-000634]_#SALES_PLAN_TEMP_KEY 테이블, 데이터 생성 (END) */
			/*------------------------------------------------------------------------------------------------------------------------------------------------- */
			N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */

			/*================================================================================================================================================= */
			/* 저장진행중 STEP-03-LOG  (START) */
			/*================================================================================================================================================= */
			V_LOG_TYPE		:= 'ING';
			V_LOG_MESSAGE	:= 'step-03- DELETE DM_PLN_SALES_PLAN';
			V_DESCRIPTION	:= '';
			D_EVENT_DATE	:= SYSDATE;
			PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
			V_LOG_MESSAGE	:= NULL;
			/*================================================================================================================================================= */
			/* 저장진행중 STEP-03-LOG (END) */
			/*================================================================================================================================================= */
		END;
		/*================================================================================================================================================= */
		/* 테이블의 중복제거 (END) */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A009--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

		/*================================================================================================================================================= */
		/* TEMP TABLE -> SALES PLAN TABLE에 데이터 적재  (START) */
		/*================================================================================================================================================= */
		INSERT INTO DM_PLN_SALES_PLAN
		( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
		, YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
		, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
		, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
		SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID	/* [PJ2025-50017] CELL_PROD_SITE_ID 추가 */
			 , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
			 , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
			 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
		  FROM ( SELECT T.*
					  , ROW_NUMBER() OVER (
							PARTITION BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
								   , MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
							ORDER BY CREATION_DATE DESC NULLS LAST ) AS RN
				   FROM GT_PRMF_SALES_PLAN_TEMP T )
		 WHERE RN = 1;

		N_LOG_COUNT := SQL%ROWCOUNT;	/* [E20250915-000105]_ROW_COUNT 확인 */
		/*================================================================================================================================================= */
		/* TEMP TABLE -> SALES PLAN TABLE에 데이터 적재  (END) */
		/*================================================================================================================================================= */
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-04-LOG  (START) */
		/*================================================================================================================================================= */
		V_LOG_TYPE		:= 'ING';
		V_LOG_MESSAGE	:= 'step-04- Insert dm_pln_sales_plan ';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
		V_LOG_MESSAGE	:= NULL;
		/*================================================================================================================================================= */
		/* 저장진행중 STEP-04-LOG  (END) */
		/*================================================================================================================================================= */
		DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' : A009--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */
		/* MULTI & SINGLE ROW END */
		/*------------------------------------------------------------------------------------------------------------------------------------------------- */

	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	/* 트랜잭션 (END) / 예외 처리 */

	/*   원본은 명시 COMMIT 없음(호출자 DMF0003_SAVE_MKT_FCST 트랜잭션에 합류) -> 본 프로시저 성공 COMMIT 없음. 오류 시 ROLLBACK(원본 XACT_ABORT ON 등가). */
	/*------------------------------------------------------------------------------------------------------------------------------------------------- */
	EXCEPTION
		WHEN OTHERS THEN
			ROLLBACK;
			V_LOG_TYPE		:= 'ERROR';
			V_LOG_MESSAGE	:= 'EXCEPTION';
			V_DESCRIPTION	:= '';
			D_EVENT_DATE	:= SYSDATE;
			V_SQL_CODE		:= TO_CHAR(SQLCODE);
			V_SQL_ERRMSG	:= SQLERRM;
			V_PROC_INPUT	:= 'NO_PARAM';
			V_BACKTRACE		:= DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
			DBMS_OUTPUT.PUT_LINE('[' || V_SQL_CODE || ']' || V_SQL_ERRMSG);	/*-- 에러메시지 DISPLAY --*/
			PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
							   , V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
			RAISE_APPLICATION_ERROR(-20001
  , '[' || V_PROGRAM_NAME || '] SQLCODE=' || V_SQL_CODE ||
				' / SQLERRM=' || V_SQL_ERRMSG ||
				' / BACKTRACE=' || V_BACKTRACE);
	END;

	/*================================================================================================================================================= */
	/* 종료 LOG  (START) */
	/*   원본 : IF @v_log_message IS NULL (정상 종료 시에만 END 로그). 오류 시엔 위 RAISE 로 이미 프로시저를 벗어남. */
	/*================================================================================================================================================= */
	IF V_LOG_MESSAGE IS NULL THEN
		V_LOG_TYPE		:= 'END';
		V_LOG_MESSAGE	:= '########## END of procedure ##########';
		V_DESCRIPTION	:= '';
		D_EVENT_DATE	:= SYSDATE;
		PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
	END IF;
	/*================================================================================================================================================= */
	/* 종료 LOG  (END) */
	/*================================================================================================================================================= */


END;
/
SHOW ERRORS PROCEDURE PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE
-- ##### END PROCEDURE PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE

-- ##### START PROCEDURE PR_DM_CUST_ITEM_MAPPING
CREATE OR REPLACE PROCEDURE           "PR_DM_CUST_ITEM_MAPPING" (P_ACCEPT_FLAG VARCHAR2 /* 업무구분(EDI, RPA) */

                                                    )
/*
    * Program ID  : PR_DM_CUST_ITEM_MAPPING
    * Description  : N:N Model Mapping 데이터 기초값 생성
    * 테이블
      DM_CUST_ITEM_MAPPING_M
      DM_CUST_ITEM_MAPPING_DTL_N
      DM_CUST_ITEM_MAPPING_DTL_H
    * Program History
    *===================================================================================================
    *   Date       In Charge      Description
    *===================================================================================================
    2024.04.18    kcw3408        N:N Model Mapping_배치작업 신규
    2024.12.19    KANG.H.J       N:N Model Mapping_RPA/EXCEL 로직 삭제
    2026.03.22    김준규           [PJ20264226] NextSCM Pilot 설계 및 개발
    2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
    */
    /*
    PR_DM_CUST_ITEM_MAPPING('EDI');    --EDI(PR_DM_DNM_EDI_CALLOFF CALL)
    PR_DM_CUST_ITEM_MAPPING('RPA');    --RPA/ECEL(PR_DM_PLN_CUST_FCST_TO_MKT_FCST,PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40 CALL)
    PR_DM_CUST_ITEM_MAPPING('EXCEL');  --RPA/EXCEL 수기입력건
    */
    /* ------------------------------------------------------------------------------------------------------------------------------- */
 AS

    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_LOG_TYPE         VARCHAR2(30 CHAR);
    N_LOG_COUNT        INTEGER := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;
    N_DELETE_COUNT     INTEGER := 0;
    N_INSERT_COUNT     INTEGER := 0;
    V_CREATED_BY       VARCHAR2(150 CHAR) := 'SYS_BATCH_DATA';
    V_0MONTH_TUESDAY   VARCHAR2(08 CHAR);
    V_DELIMITER        VARCHAR2(1 CHAR);
    V_ACCEPT_FLAG      VARCHAR2(10 CHAR);
    V_CNT              INTEGER := 0;
    V_FROM_YYYYMMDD    VARCHAR2(08 CHAR);
    V_DELETE_YYYYMMDD  VARCHAR2(08 CHAR);
    V_VALID_START_DATE VARCHAR2(08 CHAR);
    V_VALID_END_DATE   VARCHAR2(08 CHAR);
    V_IN_PARA_DATA     CLOB;
    V_STEP             VARCHAR2(4000 CHAR) := NULL;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := JSON_OBJECT('p_accept_flag' VALUE P_ACCEPT_FLAG);


    DELETE FROM GT_DCIM_DM_DNM_EDI_CALLOFF_ITE;
    DELETE FROM GT_DCIM_DM_CUST_ITEM_MAPPING_D;


    /* LOG 용 변수 설정 */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := 'PR_DM_CUST_ITEM_MAPPING: ' || P_ACCEPT_FLAG;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_DM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, V_CREATED_BY);

    BEGIN
        /* 오윤종 PI 요청으로 셋팅함 */
        V_FROM_YYYYMMDD   := '20240101';
        V_DELETE_YYYYMMDD := TO_CHAR(ADD_MONTHS(SYSDATE, -12), 'YYYYMMDD');
        /* v_from_yyyymmdd := TO_CHAR(TO_CHAR(ADD_MONTHS(SYSDATE, - 12), 'YYYYMMDD') || '1201', 'YYYYMMDD') */
        V_VALID_START_DATE := TO_CHAR(SYSDATE, 'YYYYMMDD');
        V_VALID_END_DATE   := '20991231';
        V_ACCEPT_FLAG      := P_ACCEPT_FLAG;
    END;

    DBMS_OUTPUT.PUT_LINE('A1--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3') || P_ACCEPT_FLAG);

    IF V_ACCEPT_FLAG = 'EDI'
    /*
              대상추출(DM_CUST_ITEM_MAPPING_M 에 없는건 추출 _EDI
            */
     THEN
        /* 테이블중복제거 */
        /* 임시확인용테이블 중복제거 */
        INSERT
        INTO GT_DCIM_DM_DNM_EDI_CALLOFF_ITE
            SELECT A.DIVISION_ID
                  ,A.SENDER_CODE
                  ,A.SENDER_NAME
                  ,NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ') UNLOADING_POINT
                  ,NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ') CUSTOMER_PLANT
                  ,NVL(RTRIM(LTRIM(A.CUST_MATERIAL_CODE)), ' ') CUST_MATERIAL_CODE
                  ,A.SHIPTO_CODE
                  ,A.SOLDTO_CODE
                  ,A.ITEM_ID
                  ,A.SCM_SITE_ID
                  ,A.EDI_INCOTERMS
                  ,A.PROJECT_CODE
                  ,NVL(B.END_CUSTOMER, ' ') END_CUSTOMER
                  ,CASE A.ERP_FCST_TYPE
                       WHEN 'M' THEN
                        'MPS'
                       WHEN 'S' THEN
                        'SMC'
                       ELSE
                        'MPS'
                   END AS FCST_TYPE
                  ,'E' AS DOM_EXP
            FROM   DM_DNM_EDI_CALLOFF_ITEM A
            LEFT   OUTER JOIN SCM_MST_SITE B
            ON     A.DIVISION_ID = B.DIVISION_ID
            AND    A.SCM_SITE_ID = B.SCM_SITE_ID
            AND    B.SITE_TYPE = 'SALES'
            /* AND B.VALID_YN        = 'Y' */
            WHERE  A.CREATE_DATE >= V_FROM_YYYYMMDD
            AND    A.STATUS_CODE = 'S'
            AND    A.ERP_STATUS IS NULL
            AND    A.SENDER_NAME <> 'LUCID'
            GROUP  BY A.DIVISION_ID
                     ,A.SENDER_CODE
                     ,A.SENDER_NAME
                     ,A.UNLOADING_POINT
                     ,A.CUSTOMER_PLANT
                     ,A.CUST_MATERIAL_CODE
                     ,A.SHIPTO_CODE
                     ,A.SOLDTO_CODE
                     ,A.ITEM_ID
                     ,A.SCM_SITE_ID
                     ,A.STATUS_CODE
                     ,A.SSPM_STATUS
                     ,A.EDI_INCOTERMS
                     ,A.PROJECT_CODE
                     ,B.END_CUSTOMER
                     ,A.SALES_PLANT_SITE_STATUS
                     ,A.ERP_STATUS
                     ,A.ERP_FCST_TYPE;

        INSERT INTO DM_CUST_ITEM_MAPPING_M
            (DIVISION_ID
            ,DATA_TYPE_CODE
            ,END_CUSTOMER
            ,SCM_SITE_ID
            ,PROJECT_CODE
            ,FCST_TYPE
            ,INCOTERMS
            ,DOM_EXP
            ,ITEM_ID
            ,ACTIVE_YN
            ,UNLOADING_POINT
            ,CUSTOMER_PLANT
            ,SOLDTO_CODE
            ,SHIPTO_CODE
            ,CUSTOMER_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)
            SELECT T1.DIVISION_ID
                  ,T1.DATA_TYPE_CODE
                  ,T1.END_CUSTOMER
                  ,T1.SCM_SITE_ID
                  ,T1.PROJECT_CODE
                  ,T1.FCST_TYPE
                  ,T1.INCOTERMS
                  ,T1.DOM_EXP
                  ,T1.ITEM_ID
                  ,T1.ACTIVE_YN
                  ,T1.UNLOADING_POINT
                  ,T1.CUSTOMER_PLANT
                  ,T1.SOLDTO_CODE
                  ,T1.SHIPTO_CODE
                  ,T1.CUST_MATERIAL_CODE
                  ,'BATCH SYSTEM' AS CREATED_BY
                  ,SYSTIMESTAMP CREATION_DATE
                  ,'BATCH SYSTEM' AS LAST_UPDATED_BY
                  ,SYSTIMESTAMP LAST_UPDATE_DATE
            FROM   (SELECT DISTINCT A.DIVISION_ID
                                   ,'EDI' AS DATA_TYPE_CODE
                                   ,NVL(A.END_CUSTOMER, '/') END_CUSTOMER
                                   ,A.SCM_SITE_ID
                                   ,A.PROJECT_CODE
                                   ,A.FCST_TYPE
                                   ,A.EDI_INCOTERMS INCOTERMS
                                   ,A.DOM_EXP
                                   ,A.ITEM_ID
                                   ,'Y' AS ACTIVE_YN
                                   ,A.UNLOADING_POINT
                                   ,A.CUSTOMER_PLANT
                                   ,A.SOLDTO_CODE
                                   ,A.SHIPTO_CODE
                                   ,A.CUST_MATERIAL_CODE
                                   ,ROW_NUMBER() OVER(PARTITION BY A.DIVISION_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.FCST_TYPE, A.EDI_INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.UNLOADING_POINT, A.CUSTOMER_PLANT, A.CUST_MATERIAL_CODE ORDER BY A.UNLOADING_POINT, A.CUSTOMER_PLANT, A.CUST_MATERIAL_CODE) NUM
                    FROM   GT_DCIM_DM_DNM_EDI_CALLOFF_ITE A) T1
            LEFT   OUTER JOIN DM_CUST_ITEM_MAPPING_M T2
            ON     T1.DIVISION_ID = T2.DIVISION_ID
            AND    T1.DATA_TYPE_CODE = T2.DATA_TYPE_CODE
            AND    T1.END_CUSTOMER = T2.END_CUSTOMER
            AND    T1.SCM_SITE_ID = T2.SCM_SITE_ID
            AND    T1.PROJECT_CODE = T2.PROJECT_CODE
            AND    T1.FCST_TYPE = T2.FCST_TYPE
            AND    T1.INCOTERMS = T2.INCOTERMS
            AND    T1.DOM_EXP = T2.DOM_EXP
            AND    T1.ITEM_ID = T2.ITEM_ID
                  /* JSSBAE */
            AND    (RTRIM(LTRIM(T1.UNLOADING_POINT)) = RTRIM(LTRIM(T2.UNLOADING_POINT)) OR
                  (RTRIM(LTRIM(T1.UNLOADING_POINT)) IS NULL AND RTRIM(LTRIM(T2.UNLOADING_POINT)) IS NULL))
            AND    (RTRIM(LTRIM(T1.CUSTOMER_PLANT)) = RTRIM(LTRIM(T2.CUSTOMER_PLANT)) OR
                  (RTRIM(LTRIM(T1.CUSTOMER_PLANT)) IS NULL AND RTRIM(LTRIM(T2.CUSTOMER_PLANT)) IS NULL))
            AND    (RTRIM(LTRIM(T1.CUST_MATERIAL_CODE)) = RTRIM(LTRIM(T2.CUSTOMER_ITEM_ID)) OR
                  (RTRIM(LTRIM(T1.CUST_MATERIAL_CODE)) IS NULL AND RTRIM(LTRIM(T2.CUSTOMER_ITEM_ID)) IS NULL))
            WHERE  T2.DIVISION_ID IS NULL
            AND    T1.NUM = 1;
    END IF;

    DBMS_OUTPUT.PUT_LINE('A2--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    /*
      대상추출(DM_CUST_ITEM_MAPPING_M 에 없는건 추출 _EXCEL,RPA
    */
    /*
    IF v_accept_flag = 'RPA'

        -- 테이블중복제거
        -- 임시확인용테이블 중복제거
        SELECT DISTINCT
               A.DIVISION_ID
             , CASE WHEN A.CREATED_BY LIKE '%robot'
                    THEN 'RPA'
                    ELSE 'EXCEL'
               END AS DATA_TYPE_CODE
            , '' AS UNLOADING_POINT
            , '' AS CUSTOMER_PLANT
            , '' AS CUST_MATERIAL_CODE
            , K.SHIPTO_CODE
            , K.SOLDTO_CODE
            , A.ITEM_ID
            , A.SCM_SITE_ID
            , A.INCOTERMS
            , A.PROJECT_CODE
            , B.END_CUSTOMER
            , A.FCST_TYPE
            , A.DOM_EXP
            INTO #TEMP_DM_PLN_CUSTOMER_PSI
            FROM DM_PLN_CUSTOMER_PSI A
               LEFT OUTER JOIN SCM_MST_SITE B
                 ON A.DIVISION_ID = B.DIVISION_ID
                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                AND B.SITE_TYPE    = 'SALES'
                AND B.VALID_YN      = 'Y'
                 LEFT OUTER JOIN SCM_MST_SITE_CUSTOMER K
                ON B.DIVISION_ID = K.DIVISION_ID
               AND B.SCM_SITE_ID = K.SCM_SITE_ID
               AND K.REP_YN = 'Y'
            WHERE A.YYYYMMDD >= v_from_yyyymmdd
            AND A.MEASURE_GROUP = 'CUST_FCST'
            AND A.MEASURE IN ('Customer FCST');
            --AND REPLACE(TO_CHAR(A.CREATION_DATE, 'YYYYMMDD'), '-', '')  >= v_from_yyyymmdd

       INSERT INTO DM_CUST_ITEM_MAPPING_M (
             DIVISION_ID
            ,DATA_TYPE_CODE
            ,END_CUSTOMER
            ,SCM_SITE_ID
            ,PROJECT_CODE
            ,FCST_TYPE
            ,INCOTERMS
            ,DOM_EXP
            ,ITEM_ID
            ,ACTIVE_YN
            ,UNLOADING_POINT
            ,CUSTOMER_PLANT
            ,SOLDTO_CODE
            ,SHIPTO_CODE
            ,CUSTOMER_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE
            )
       SELECT T1.DIVISION_ID
            , T1.DATA_TYPE_CODE
            , T1.END_CUSTOMER
            , T1.SCM_SITE_ID
            , T1.PROJECT_CODE
            , T1.FCST_TYPE
            , T1.INCOTERMS
            , T1.DOM_EXP
            , T1.ITEM_ID
            , T1.ACTIVE_YN
            , T1.UNLOADING_POINT
            , T1.CUSTOMER_PLANT
            , T1.SOLDTO_CODE
            , T1.SHIPTO_CODE
            , T1.CUSTOMER_ITEM_ID
            ,'BATCH SYSTEM' AS CREATED_BY
            ,SYSTIMESTAMP CREATION_DATE
            ,'BATCH SYSTEM' AS LAST_UPDATED_BY
            ,SYSTIMESTAMP LAST_UPDATE_DATE
        FROM
            (SELECT DISTINCT
                    A.DIVISION_ID
                  , A.DATA_TYPE_CODE
                  , A.END_CUSTOMER
                  , A.SCM_SITE_ID
                  , A.PROJECT_CODE
                  , A.FCST_TYPE
                  , A.INCOTERMS
                  , A.DOM_EXP
                  , A.ITEM_ID
                  , 'Y' AS ACTIVE_YN
                  , A.UNLOADING_POINT
                  , A.CUSTOMER_PLANT
                  , A.SOLDTO_CODE
                  , A.SHIPTO_CODE
                  , A.CUST_MATERIAL_CODE CUSTOMER_ITEM_ID
                  , ROW_NUMBER() OVER (
                    PARTITION BY A.DATA_TYPE_CODE,A.DIVISION_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID
                               ,A.UNLOADING_POINT,A.CUSTOMER_PLANT,A.CUST_MATERIAL_CODE
                   ORDER BY A.UNLOADING_POINT,A.CUSTOMER_PLANT,A.CUST_MATERIAL_CODE) NUM
               FROM #TEMP_DM_PLN_CUSTOMER_PSI A
            ) T1
            LEFT OUTER JOIN
            DM_CUST_ITEM_MAPPING_M(T2);
                ON T1.DIVISION_ID = T2.DIVISION_ID
               AND T1.DATA_TYPE_CODE = T2.DATA_TYPE_CODE
               AND T1.END_CUSTOMER = T2.END_CUSTOMER
               AND T1.SCM_SITE_ID = T2.SCM_SITE_ID
               AND T1.PROJECT_CODE = T2.PROJECT_CODE
               AND T1.FCST_TYPE = T2.FCST_TYPE
               AND T1.INCOTERMS = T2.INCOTERMS
               AND T1.DOM_EXP = T2.DOM_EXP
               AND T1.ITEM_ID = T2.ITEM_ID
               --JSSBAE
         WHERE T2.DIVISION_ID IS NULL
           AND T1.NUM  = 1
    */
    /* 수기 입력건 1회성 작업 */
    /*
    IF v_accept_flag = 'EXCEL'

        -- 테이블중복제거
        -- 임시확인용테이블 중복제거
        SELECT DISTINCT
               A.DIVISION_ID
             , CASE WHEN A.CREATED_BY LIKE '%robot'
                    THEN 'RPA'
                    ELSE 'EXCEL'
               END AS DATA_TYPE_CODE
            , '' AS UNLOADING_POINT
            , '' AS CUSTOMER_PLANT
            , '' AS CUST_MATERIAL_CODE
            , K.SHIPTO_CODE
            , K.SOLDTO_CODE
            , A.ITEM_ID
            , A.SCM_SITE_ID
            , A.INCOTERMS
            , A.PROJECT_CODE
            , B.END_CUSTOMER
            , A.FCST_TYPE
            , A.DOM_EXP
            INTO #TEMP_DM_PLN_CUST_FCST_H
            FROM DM_PLN_CUST_FCST_H A
               LEFT OUTER JOIN SCM_MST_SITE B
                 ON A.DIVISION_ID = B.DIVISION_ID
                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                AND B.SITE_TYPE    = 'SALES'
                AND B.VALID_YN      = 'Y'
                 LEFT OUTER JOIN SCM_MST_SITE_CUSTOMER K
                ON B.DIVISION_ID = K.DIVISION_ID
               AND B.SCM_SITE_ID = K.SCM_SITE_ID
               AND K.REP_YN = 'Y'
            WHERE A.YYYYMMDD >= v_from_yyyymmdd
            AND A.MEASURE IN ('Customer FCST');
            --AND REPLACE(TO_CHAR(A.CREATION_DATE, 'YYYYMMDD'), '-', '')  >= v_from_yyyymmdd

       INSERT INTO DM_CUST_ITEM_MAPPING_M (
             DIVISION_ID
            ,DATA_TYPE_CODE
            ,END_CUSTOMER
            ,SCM_SITE_ID
            ,PROJECT_CODE
            ,FCST_TYPE
            ,INCOTERMS
            ,DOM_EXP
            ,ITEM_ID
            ,ACTIVE_YN
            ,UNLOADING_POINT
            ,CUSTOMER_PLANT
            ,SOLDTO_CODE
            ,SHIPTO_CODE
            ,CUSTOMER_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE
            )
       SELECT T1.DIVISION_ID
            , T1.DATA_TYPE_CODE
            , T1.END_CUSTOMER
            , T1.SCM_SITE_ID
            , T1.PROJECT_CODE
            , T1.FCST_TYPE
            , T1.INCOTERMS
            , T1.DOM_EXP
            , T1.ITEM_ID
            , T1.ACTIVE_YN
            , T1.UNLOADING_POINT
            , T1.CUSTOMER_PLANT
            , T1.SOLDTO_CODE
            , T1.SHIPTO_CODE
            , T1.CUSTOMER_ITEM_ID
            ,'BATCH SYSTEM' AS CREATED_BY
            ,SYSTIMESTAMP CREATION_DATE
            ,'BATCH SYSTEM' AS LAST_UPDATED_BY
            ,SYSTIMESTAMP LAST_UPDATE_DATE
        FROM
            (SELECT DISTINCT
                    A.DIVISION_ID
                  , A.DATA_TYPE_CODE
                  , A.END_CUSTOMER
                  , A.SCM_SITE_ID
                  , A.PROJECT_CODE
                  , A.FCST_TYPE
                  , A.INCOTERMS
                  , A.DOM_EXP
                  , A.ITEM_ID
                  , 'Y' AS ACTIVE_YN
                  , A.UNLOADING_POINT
                  , A.CUSTOMER_PLANT
                  , A.SOLDTO_CODE
                  , A.SHIPTO_CODE
                  , A.CUST_MATERIAL_CODE CUSTOMER_ITEM_ID
                  , ROW_NUMBER() OVER (
                    PARTITION BY A.DATA_TYPE_CODE,A.DIVISION_ID, A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID
                               ,A.UNLOADING_POINT,A.CUSTOMER_PLANT,A.CUST_MATERIAL_CODE
                   ORDER BY A.UNLOADING_POINT,A.CUSTOMER_PLANT,A.CUST_MATERIAL_CODE) NUM
               FROM #TEMP_DM_PLN_CUST_FCST_H A
            ) T1
            LEFT OUTER JOIN
            DM_CUST_ITEM_MAPPING_M(T2);
                ON T1.DIVISION_ID = T2.DIVISION_ID
               AND T1.DATA_TYPE_CODE = T2.DATA_TYPE_CODE
               AND T1.END_CUSTOMER = T2.END_CUSTOMER
               AND T1.SCM_SITE_ID = T2.SCM_SITE_ID
               AND T1.PROJECT_CODE = T2.PROJECT_CODE
               AND T1.FCST_TYPE = T2.FCST_TYPE
               AND T1.INCOTERMS = T2.INCOTERMS
               AND T1.DOM_EXP = T2.DOM_EXP
               AND T1.ITEM_ID = T2.ITEM_ID
         WHERE T2.DIVISION_ID IS NULL
           AND T1.NUM  = 1
    */
    DBMS_OUTPUT.PUT_LINE('A3--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));
    IF V_ACCEPT_FLAG = 'EDI'
    /*
              대상추출(DM_CUST_ITEM_MAPPING_DTL_N 에 없는건 초기 적재
            */
     THEN
        /* 테이블중복제거 */
        /* 임시확인용테이블 중복제거 */
        INSERT
        INTO GT_DCIM_DM_CUST_ITEM_MAPPING_D
            SELECT T1.DIVISION_ID
                  ,T1.DATA_TYPE_CODE
                  ,NVL(T1.END_CUSTOMER, ' ') END_CUSTOMER
                  ,T1.SCM_SITE_ID
                  ,T1.PROJECT_CODE
                  ,T1.FCST_TYPE
                  ,T1.INCOTERMS
                  ,T1.DOM_EXP
                  ,T1.ITEM_ID
                  ,T1.UNLOADING_POINT
                  ,T1.CUSTOMER_PLANT
                  ,T1.CUSTOMER_ITEM_ID
                  ,T1.ACTIVE_YN
                  ,T1.SOLDTO_CODE
                  ,T1.SHIPTO_CODE
                  ,V_VALID_START_DATE VALID_START_DATE
                  ,V_VALID_END_DATE VALID_END_DATE
                  ,T1.ITEM_ID MAPPING_ITEM_ID
                  ,'BATCH SYSTEM' AS CREATED_BY
                  ,SYSTIMESTAMP CREATION_DATE
                  ,'BATCH SYSTEM' AS LAST_UPDATED_BY
                  ,SYSTIMESTAMP LAST_UPDATE_DATE
            FROM   DM_CUST_ITEM_MAPPING_M T1
            LEFT   OUTER JOIN DM_CUST_ITEM_MAPPING_DTL_N T2
            ON     T1.DIVISION_ID = T2.DIVISION_ID
            AND    T1.DATA_TYPE_CODE = T2.DATA_TYPE_CODE
            AND    T1.END_CUSTOMER = T2.END_CUSTOMER
            AND    T1.SCM_SITE_ID = T2.SCM_SITE_ID
            AND    T1.PROJECT_CODE = T2.PROJECT_CODE
            AND    T1.FCST_TYPE = T2.FCST_TYPE
            AND    T1.INCOTERMS = T2.INCOTERMS
            AND    T1.DOM_EXP = T2.DOM_EXP
            AND    T1.ITEM_ID = T2.ITEM_ID
            AND    (RTRIM(LTRIM(T1.UNLOADING_POINT)) = RTRIM(LTRIM(T2.UNLOADING_POINT)) OR
                  (RTRIM(LTRIM(T1.UNLOADING_POINT)) IS NULL AND RTRIM(LTRIM(T2.UNLOADING_POINT)) IS NULL))
            AND    (RTRIM(LTRIM(T1.CUSTOMER_PLANT)) = RTRIM(LTRIM(T2.CUSTOMER_PLANT)) OR
                  (RTRIM(LTRIM(T1.CUSTOMER_PLANT)) IS NULL AND RTRIM(LTRIM(T2.CUSTOMER_PLANT)) IS NULL))
            AND    (RTRIM(LTRIM(T1.CUSTOMER_ITEM_ID)) = RTRIM(LTRIM(T2.CUSTOMER_ITEM_ID)) OR
                  (RTRIM(LTRIM(T1.CUSTOMER_ITEM_ID)) IS NULL AND RTRIM(LTRIM(T2.CUSTOMER_ITEM_ID)) IS NULL))
            WHERE  T2.DIVISION_ID IS NULL
            AND    T1.ACTIVE_YN = 'Y';

        INSERT INTO DM_CUST_ITEM_MAPPING_DTL_N
            (DIVISION_ID
            ,DATA_TYPE_CODE
            ,END_CUSTOMER
            ,SCM_SITE_ID
            ,PROJECT_CODE
            ,FCST_TYPE
            ,INCOTERMS
            ,DOM_EXP
            ,ITEM_ID
            ,UNLOADING_POINT
            ,CUSTOMER_PLANT
            ,CUSTOMER_ITEM_ID
            ,VALID_START_DATE
            ,VALID_END_DATE
            ,MAPPING_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)
            SELECT T1.DIVISION_ID
                  ,T1.DATA_TYPE_CODE
                  ,T1.END_CUSTOMER
                  ,T1.SCM_SITE_ID
                  ,T1.PROJECT_CODE
                  ,T1.FCST_TYPE
                  ,T1.INCOTERMS
                  ,T1.DOM_EXP
                  ,T1.ITEM_ID
                  ,T1.UNLOADING_POINT
                  ,T1.CUSTOMER_PLANT
                  ,T1.CUSTOMER_ITEM_ID
                  ,T1.VALID_START_DATE
                  ,T1.VALID_END_DATE
                  ,T1.MAPPING_ITEM_ID
                  ,T1.CREATED_BY
                  ,T1.CREATION_DATE
                  ,T1.LAST_UPDATED_BY
                  ,T1.LAST_UPDATE_DATE
            FROM   GT_DCIM_DM_CUST_ITEM_MAPPING_D T1;
    END IF;

    IF V_ACCEPT_FLAG = 'EDI'
    /*
              대상추출(DM_CUST_ITEM_MAPPING_DTL_N 에 없는건 초기 적재
            */
     THEN
        INSERT INTO DM_CUST_ITEM_MAPPING_DTL_H
            (DIVISION_ID
            ,DATA_TYPE_CODE
            ,END_CUSTOMER
            ,SCM_SITE_ID
            ,PROJECT_CODE
            ,FCST_TYPE
            ,INCOTERMS
            ,DOM_EXP
            ,ITEM_ID
            ,UNLOADING_POINT
            ,CUSTOMER_PLANT
            ,CUSTOMER_ITEM_ID
            ,ACTIVE_YN
            ,SOLDTO_CODE
            ,SHIPTO_CODE
            ,VALID_START_DATE
            ,VALID_END_DATE
            ,MAPPING_ITEM_ID
            ,CREATED_BY
            ,CREATION_DATE
            ,LAST_UPDATED_BY
            ,LAST_UPDATE_DATE)
            SELECT T1.DIVISION_ID
                  ,T1.DATA_TYPE_CODE
                  ,T1.END_CUSTOMER
                  ,T1.SCM_SITE_ID
                  ,T1.PROJECT_CODE
                  ,T1.FCST_TYPE
                  ,T1.INCOTERMS
                  ,T1.DOM_EXP
                  ,T1.ITEM_ID
                  ,T1.UNLOADING_POINT
                  ,T1.CUSTOMER_PLANT
                  ,T1.CUSTOMER_ITEM_ID
                  ,T1.ACTIVE_YN
                  ,T1.SOLDTO_CODE
                  ,T1.SHIPTO_CODE
                  ,T1.VALID_START_DATE
                  ,T1.VALID_END_DATE
                  ,T1.MAPPING_ITEM_ID
                  ,T1.CREATED_BY
                  ,T1.CREATION_DATE
                  ,T1.LAST_UPDATED_BY
                  ,T1.LAST_UPDATE_DATE
            FROM   GT_DCIM_DM_CUST_ITEM_MAPPING_D T1;
        /* 1년전 데이타 삭제 */
        DELETE FROM DM_CUST_ITEM_MAPPING_DTL_H
        WHERE  1 = 1
        AND    TO_CHAR(CREATION_DATE, 'YYYYMMDD') <= V_DELETE_YYYYMMDD
        AND    TO_CHAR(LAST_UPDATE_DATE, 'YYYYMMDD') <= V_DELETE_YYYYMMDD;
    END IF;

    DBMS_OUTPUT.PUT_LINE('A4--' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));


EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;
/
SHOW ERRORS PROCEDURE PR_DM_CUST_ITEM_MAPPING
-- ##### END PROCEDURE PR_DM_CUST_ITEM_MAPPING

-- ##### START PROCEDURE PR_DM_DNM_CREATE_C_WS_RTF
CREATE OR REPLACE PROCEDURE           "PR_DM_DNM_CREATE_C_WS_RTF" 
(
      P_DIVISION_ID   IN  VARCHAR2
    , P_VERSION_NO    IN  VARCHAR2
)
/* ==============================================================================================================================================
 * PROGRAM ID   : PR_DM_DNM_CREATE_C_WS_RTF
 * DESCRIPTION  : W/S 의 Sales Site 의 RTF 를 생성 ( Shipment Plan 참조 )
 * PROGRAM HISTORY
 *==============================================================================================================================================
 *   DATE       IN CHARGE      DESCRIPTION
 *==============================================================================================================================================
 * 2021.11.09   hwi1993     [PJ20209643]    INITIAL RELEASE
 * 2021.11.16   HWI1993     룩업에 VALID 조건 추가
 * 2022.01.06   hwi1993     기존 데이터 삭제시 created_by 대신 last_updated_by로 변경
 * 2022.04.05   HWI1993     GM JV 작업
 * 2022.04.12   Hwi1993     확정구간의 ETA 와 미확정구간의 RTF 가 겹쳐서 발생하는 오류 수정
 * 2022.08.30   HWI1993     AS INV PK 오류 수정 ( DISTINCT 추가 )
 * 2022.11.04   HWI1993     [C20220916-000290] [SCM PI] DM 시스템의 AS RTF 정확도 향상을 위한 기능변경 건
 * 2022.11.22   HWI1993     [C20220916-000290] 오류 수정 재배포
 * 2024.02.19   JSSBAE      [E20240214-000835]_[영업마케팅 PI팀] 81번사업부 AS Inv 생성 로직 변경 요청
 * 2024.03.15   JSSBAE      [E20240226-000021]_52주구간 AS INV VIEW 확보
 * 2024.09.26   JSSBAE      [E20240926-001366]_[공급 SCM PI팀] AS 관련 메저 생성 시 SCPSSP RTF간 우선순위 지정(SCP RTF 우선시)
 *                          PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE에서 기 생성된 RTF_SCP와 SSP_RTF가 겹치는 현상이 발생하여 수정
 * 2024.10.21   JSSBAE      [E20241007-000267]_[공급 SCM PI팀] AS 관련 메저 생성 시 SSP 기존 로직 제거
 *                          81, 81_JV들만 제거하고 다른 사업부는 현행과 동일하게 유지한다.
 * 2024.12.01   KANG_H.J    [PJ2024-50611] BPS 매출(RTF_SYS_RP Measrue) 전송 시 전 사업부 FROM_SITE_ID 추가
 * 2025.01.13   P.C.I       [E20250113-000270]_[공급/생산 SCM PI팀] 운송중 재고 AS RTF 산출시 적용 요청
 * 2025.01.31   JSSBAE      [E20250120-000036]_[공급/생산 SCM PI팀] AS Inv -> RTF 생성로직 개선 (재고 기반 RTF 산출)
 * 2025.02.05   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN 동기화
 * 2025.04.08   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025.09.09   JSSBAE      [E20250909-000795]_Kangoo 모델 AS INV REQ 값 이상[RTF 미산출)
 * 2026.02.12   JSSBAE      [E20260212-001318]_MKT FCST Waterfall - RTF 조회 불가 현상
 * 2026.03.27   JSSBAE      [E20260327-001732]_[긴급] MKT FCST Watefall cut-off(자동차)_AS 물동 관련 오류 수정
 * 2026.05.26   JSSBAE      [E20260402-001736]_AS 관련 기능 개선 건
 * 2026.09.18   AJS         40·82 PLANT_SITE_ID, 81·82 END_CUSTOMER 빈값 채움값 ' '·'' → '-' 통일(14자리)
 *==============================================================================================================================================
 *   USAGE : EXEC PR_DM_DNM_CREATE_C_WS_RTF '82'
 *----------------------------------------------------------------------------------------------------------------------------------------------
 *     - ATTRIBUTE10 <> '' -> IS NOT NULL, V_INV_QTY 는 원본 INT(정수절단) -> TRUNC 적용
 *============================================================================================================================================== */
IS

    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_DNM_CREATE_C_WS_RTF';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    N_DELETE_COUNT        NUMBER := 0;
    N_INSERT_COUNT        NUMBER := 0;
    V_CREATED_BY          VARCHAR2(150 CHAR) := 'SYSTEM_WS';

    V_START_YYYYMMDD      VARCHAR2(8 CHAR);
    V_SHIP_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_CUTOFF_TYPE         VARCHAR2(50 CHAR);
    V_CUTOFF_YYYYMMDD     VARCHAR2(8 CHAR);


    I                     NUMBER;
    CNT                   NUMBER;
    SUB_I                 NUMBER;
    SUB_CNT               NUMBER;
    V_ALLOC_I             NUMBER;
    V_ALLOC_CNT           NUMBER;
    V_YYYYMMDD            VARCHAR2(8 CHAR);
    V_INV                 NUMBER(20,10);
    V_RTF                 NUMBER(20,10);
    V_SSP_RTF             NUMBER(20,10);
    V_MKT_FCST            NUMBER(20,10);
    V_MKT_FCST_NET        NUMBER(20,10);
    V_SCM_SITE_ID         VARCHAR2(30 CHAR);
    V_PROJECT_CODE        VARCHAR2(50 CHAR);
    V_ITEM_ID             VARCHAR2(50 CHAR);
    V_ALLOC_SUM_RTF       NUMBER(20,10);
    V_ALLOC_RTF           NUMBER(20,10);

    I_SUB                 NUMBER;
    CNT_SUB               NUMBER;
    V_DIVISION_ID         VARCHAR2(30 CHAR);
    V_DOM_EXP             VARCHAR2(3 CHAR);
    V_FCST_TYPE           VARCHAR2(20 CHAR);
    V_INCOTERMS           VARCHAR2(10 CHAR);
    V_PLANT_SITE_ID       VARCHAR2(30 CHAR);
    V_INV_QTY             NUMBER;

    V_SITE_SEQ            NUMBER;
    V_DATE                VARCHAR2(8 CHAR);
    V_MAX_DATE            VARCHAR2(8 CHAR);
    V_FROM_SITE           VARCHAR2(30 CHAR);
    V_FROM_PLANT          VARCHAR2(30 CHAR);

    V_SUM_REQ_QTY         NUMBER(30,10);
    V_REQ_QTY             NUMBER(30,10);
    V_REM_QTY             NUMBER(30,10);
    I_RCV                 NUMBER;
    CNT_RCV               NUMBER;
    V_INV_ADJ_QTY         NUMBER(30,10);
    V_KEY_VAL             NUMBER;

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / @P_VERSION_NO: ' || P_VERSION_NO;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        /* 당주 월요일 */
        V_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        BEGIN
            SELECT VERSION_TYPE
                 , YYYYMMDD
              INTO V_CUTOFF_TYPE
                 , V_CUTOFF_YYYYMMDD
              FROM DM_MST_VERSION A
             WHERE A.DIVISION_ID = P_DIVISION_ID
               AND A.VERSION_NO  = P_VERSION_NO;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN NULL;
        END;

        V_SHIP_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_SSP;
        DELETE FROM GT_PRDM_END_RTF_RAW;
        DELETE FROM GT_PRDM_AS_INV;
        DELETE FROM GT_PRDM_END_RTF_LOOP;
        DELETE FROM GT_PRDM_AS_LOOP;
        DELETE FROM GT_PRDM_RTF;
        DELETE FROM GT_PRDM_RCV;
        DELETE FROM GT_PRDM_RTF_SITE;

        /* --------------------------------------------------------------------------------------- */
        /* 1. 기존 RTF 계열 삭제 ( 고객향 / AS Plant향 ) */
        /* --------------------------------------------------------------------------------------- */
        /* 고객향 */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE A.DIVISION_ID     = P_DIVISION_ID
           AND A.VERSION_NO      = P_VERSION_NO
           AND A.LAST_UPDATED_BY = V_CREATED_BY
           AND A.YYYYMMDD       >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* AS Plant향 */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID     = P_DIVISION_ID
           AND A.VERSION_NO      = P_VERSION_NO
           AND A.LAST_UPDATED_BY = V_CREATED_BY
           AND A.YYYYMMDD       >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 : 고객향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 : AS Plant향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_SSP ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
            , INCOTERMS, MEASURE, PLANT_SITE_ID, AS_SITE, ETA_YYYYMMDD, SHIP_YYYYMMDD, QTY, GUBUN, AS_FROM_PLANT )
        SELECT T0.DIVISION_ID
             , T0.PROJECT_CODE
             , T0.TO_SITE
             , T0.ITEM_ID
             , 'E'
             , T0.FCST_TYPE
             , T1.INCOTERMS
             , 'SSP_RTF'
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1
             , T0.ETA_DATE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
             , 'CONFIRM'
             , T3.SEGMENT2
          FROM SSP_ANL_SHIP_CONFIRM T0
          JOIN SCP_MST_BOD_N_V T1 ON T0.DIVISION_ID = T1.DIVISION_ID AND T0.BOD_ID = T1.BOD_ID
          JOIN SCP_MST_DISTRIBUTION_ROUTE T2 ON T2.ROUTE_ID = T1.ROUTE_ID
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T3 ON T0.FROM_SITE = T3.SEGMENT2 AND T3.LOOKUP_TYPE = 'AS_SITE_PLANT' AND T3.SEGMENT2 <> '-' AND T3.SEGMENT3 = P_DIVISION_ID AND T3.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T4 ON T0.TO_SITE = T4.SCM_SITE_ID AND T0.DIVISION_ID = T4.DIVISION_ID AND T4.SITE_TYPE = 'SALES'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T5 ON T0.FCST_TYPE = T5.SEGMENT1 AND T5.LOOKUP_TYPE = 'SALES_TYPE_CODE2' AND T5.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T6 ON T0.FROM_SITE = T6.SCM_SITE_ID AND T0.DIVISION_ID = T6.DIVISION_ID
         WHERE 1 = 1
           AND ( T0.YYYYMMDD BETWEEN V_SHIP_START_YYYYMMDD AND CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + T6.SHIP_FROZEN, 'YYYYMMDD') END
                 OR ( T0.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
                      AND T0.ETA_DATE >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD') )
               )
           AND T0.QTY <> 0
           AND T0.DIVISION_ID = P_DIVISION_ID
           AND T0.FCST_TYPE <> '-'
           AND T0.SHIPMENT_STATUS = 'C'
           AND T0.CHANGE_TYPE = 'C'
           AND T0.ETA_DATE IS NOT NULL
         GROUP BY T0.DIVISION_ID, T0.PROJECT_CODE, T0.TO_SITE, T0.ITEM_ID, T0.FCST_TYPE, T1.INCOTERMS
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1, T0.ETA_DATE, T0.YYYYMMDD, T3.SEGMENT2;

        /* 소형 DOM_EXP 보정 1 ( YYYYMMDD 포함 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST_C A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS
            AND B.YYYYMMDD     = A.ETA_YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP;

        /* 동일 일자 값 없는 건 : YYYYMMDD 제외 재보정 ( DOM_EXP='E' 인 건만 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST_C A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.VERSION_NO  = P_VERSION_NO
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP WHERE A.DOM_EXP = 'E';

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 RTF / MKT FCST -> GT_PRDM_END_RTF_RAW */
        /* [E20241007-000267] 81 사업부는 SSP RTF 미사용. 82/40 만 SSP 구간 생성. */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN
            INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD
                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY)
                 , A.AS_SITE, A.AS_FROM_PLANT
              FROM GT_PRDM_SSP A
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
        END IF;

        /* 고객향 MKT FCST INSERT */
        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, MF_QTY, RTF_QTY, FROM_SITE, AS_PLANT )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, 'MKT_FCST', A.PLANT_SITE_ID, A.YYYYMMDD
             , SUM(A.QTY), SUM(A.QTY), 0, C.SEGMENT1, A.ATTRIBUTE10
          FROM DM_PLN_MKT_FCST_C A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID
                             AND A.ATTRIBUTE10 = B.SCM_SITE_ID
                             AND B.OPERATION_GROUP = 'W'
                             AND B.SITE_TYPE = 'PLANT'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SCM_SITE_ID = C.SEGMENT2 AND B.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('MKT_FCST')
           AND A.YYYYMMDD >= V_START_YYYYMMDD
           AND A.ATTRIBUTE10 IS NOT NULL  /* 원본 ATTRIBUTE10 <> '' */
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.ATTRIBUTE10, C.SEGMENT1
        HAVING SUM(A.QTY) <> 0;  /* [E20260327-001732] QTY 0 제외 */

        /* #RAW 에 LT 추가 */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                  FROM ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                              , ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                           FROM SCP_MST_BOD_V
                          WHERE DIVISION_ID = P_DIVISION_ID
                            AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD )
                 WHERE PRT = 1 ) B
        ON ( A.AS_PLANT = B.FROM_SITE AND A.SCM_SITE_ID = B.TO_SITE AND A.INCOTERMS = B.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.LT_DAYS = B.LT_TOTAL;

        /* SEQ ( DENSE_RANK by YYYYMMDD ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SEQ = B.SEQ;

        /* MF_SEQ ( MKT_FCST 한정 DENSE_RANK by YYYYMMDD,QTY ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD, QTY ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE MEASURE = 'MKT_FCST' ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.MF_SEQ = B.SEQ;

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 SITE 재고 루프 ( SEQ 0부터 ROW_NUMBER 채번 ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_END_RTF_LOOP ( SCM_SITE_ID, PROJECT_CODE, ITEM_ID, SEQ )
        SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
             , ROW_NUMBER() OVER ( ORDER BY SCM_SITE_ID, PROJECT_CODE, ITEM_ID ) - 1
          FROM ( SELECT DISTINCT SCM_SITE_ID, PROJECT_CODE, ITEM_ID FROM GT_PRDM_END_RTF_RAW );

        SELECT 0, MAX(SEQ) INTO I, CNT FROM GT_PRDM_END_RTF_LOOP;
        V_SCM_SITE_ID  := NULL;
        V_PROJECT_CODE := NULL;
        V_ITEM_ID      := NULL;

        WHILE I <= CNT LOOP

            SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
              INTO V_SCM_SITE_ID, V_PROJECT_CODE, V_ITEM_ID
              FROM GT_PRDM_END_RTF_LOOP
             WHERE SEQ = I;

            SELECT 1, NVL(MAX(A.SEQ), 0), 0, 0, 0, 0, 0, NULL
              INTO SUB_I, SUB_CNT, V_INV, V_RTF, V_SSP_RTF, V_MKT_FCST, V_MKT_FCST_NET, V_YYYYMMDD
              FROM GT_PRDM_END_RTF_RAW A
             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
               AND A.PROJECT_CODE = V_PROJECT_CODE
               AND A.ITEM_ID      = V_ITEM_ID
               AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST');

            WHILE ( SUB_I <= SUB_CNT ) LOOP

                SELECT SUM(CASE WHEN A.MEASURE = 'SSP_RTF' THEN A.QTY ELSE 0 END)
                     , SUM(CASE WHEN A.MEASURE = 'MKT_FCST' THEN A.QTY ELSE 0 END)
                     , MAX(A.YYYYMMDD)
                  INTO V_SSP_RTF, V_MKT_FCST, V_YYYYMMDD
                  FROM GT_PRDM_END_RTF_RAW A
                 WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                   AND A.PROJECT_CODE = V_PROJECT_CODE
                   AND A.ITEM_ID      = V_ITEM_ID
                   AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST')
                   AND A.SEQ = SUB_I;

                /* 당일의 기초재고 및 요청총량 계산 */
                V_INV          := V_INV + NVL(V_SSP_RTF, 0);
                V_MKT_FCST_NET := V_MKT_FCST_NET + NVL(V_MKT_FCST, 0);

                IF V_INV >= V_MKT_FCST_NET THEN
                    V_INV          := V_INV - V_MKT_FCST_NET;
                    V_RTF          := V_MKT_FCST_NET;
                    V_MKT_FCST_NET := 0;
                ELSE
                    V_RTF          := V_INV;
                    V_MKT_FCST_NET := V_MKT_FCST_NET - V_INV;
                    V_INV          := 0;
                END IF;

                IF ( V_RTF > 0 ) THEN

                    SELECT 0, 0, MIN(A.SEQ)
                      INTO V_ALLOC_SUM_RTF, V_ALLOC_RTF, V_ALLOC_I
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                       AND A.PROJECT_CODE = V_PROJECT_CODE
                       AND A.ITEM_ID      = V_ITEM_ID
                       AND A.MEASURE IN ('MKT_FCST')
                       AND A.SEQ <= SUB_I
                       AND A.RTF_QTY < A.MF_QTY;

                    /* 하나씩 풀면서 V_RTF 숫자에 도달할때까지 넣어준다. */
                    WHILE ( V_ALLOC_SUM_RTF < V_RTF ) LOOP

                        V_ALLOC_RTF := 0;

                        BEGIN
                            SELECT CASE WHEN A.QTY - NVL(A.RTF_QTY, 0) < V_RTF - V_ALLOC_SUM_RTF THEN A.QTY - NVL(A.RTF_QTY, 0)
                                        ELSE V_RTF - V_ALLOC_SUM_RTF END
                              INTO V_ALLOC_RTF
                              FROM GT_PRDM_END_RTF_RAW A
                             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                               AND A.PROJECT_CODE = V_PROJECT_CODE
                               AND A.ITEM_ID      = V_ITEM_ID
                               AND A.MEASURE IN ('MKT_FCST')
                               AND A.SEQ = V_ALLOC_I
                               AND ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN EXIT;
                        END;

                        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF', PLANT_SITE_ID, V_YYYYMMDD
                             , V_ALLOC_RTF, FROM_SITE, AS_PLANT
                          FROM GT_PRDM_END_RTF_RAW A
                         WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                           AND A.PROJECT_CODE = V_PROJECT_CODE
                           AND A.ITEM_ID      = V_ITEM_ID
                           AND A.MEASURE IN ('MKT_FCST')
                           AND A.SEQ = V_ALLOC_I;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = NVL(RTF_QTY, 0) + V_ALLOC_RTF
                         WHERE SCM_SITE_ID  = V_SCM_SITE_ID
                           AND PROJECT_CODE = V_PROJECT_CODE
                           AND ITEM_ID      = V_ITEM_ID
                           AND MEASURE IN ('MKT_FCST')
                           AND SEQ = V_ALLOC_I;

                        V_ALLOC_SUM_RTF := V_ALLOC_SUM_RTF + V_ALLOC_RTF;
                        V_ALLOC_I       := V_ALLOC_I + 1;
                    END LOOP;

                END IF;

                SUB_I := SUB_I + 1;
            END LOOP;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240926-001366] SCP RTF 우선 : 겹치는 SSP RTF 제거 */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_END_RTF_RAW R
         WHERE EXISTS ( SELECT 1
                          FROM DM_PLN_MKT_FCST_C M
                         WHERE M.DIVISION_ID     = R.DIVISION_ID
                           AND M.VERSION_NO      = P_VERSION_NO
                           AND M.CUTOFF_TYPE     = V_CUTOFF_TYPE
                           AND M.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
                           AND M.PROJECT_CODE    = R.PROJECT_CODE
                           AND M.SCM_SITE_ID     = R.SCM_SITE_ID
                           AND M.ITEM_ID         = R.ITEM_ID
                           AND M.DOM_EXP         = R.DOM_EXP
                           AND M.FCST_TYPE       = R.FCST_TYPE
                           AND M.INCOTERMS       = R.INCOTERMS
                           AND M.PLANT_SITE_ID   = R.PLANT_SITE_ID
                           AND M.YYYYMMDD        = R.YYYYMMDD
                           AND M.MEASURE IN ('RTF', 'RTF_SCP', 'RTF_SYS_RP', 'RTF_PR') );

        /* --------------------------------------------------------------------------------------- */
        /* 계산된 RTF / 소형 동기화 INSERT ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

            /* [PJ2025-50017] 소형 동기화 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, END_CUSTOMER
                , SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, '-', A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에 SHIPMENT_PLAN 생성 ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

            /* [PJ2025-50017] 소형 동기화 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                , PROJECT_CODE, END_CUSTOMER
                , SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), '-', A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), '-', A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에서 SHIPMENT_PLAN 이용 AS_INV 재계산 -> GT_PRDM_AS_INV */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD, A.PLANT_SITE_ID, A.QTY
          FROM DM_PLN_MKT_FCST_C A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.OPERATION_GROUP = 'W' AND B.SITE_TYPE = 'SALES'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE IN ('AS_In_Plan', 'AS_SHIP_PLAN')
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        /* 기존 AS_INV 메저 보유행에 SITE_SEQ=1 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  FROM DM_PLN_MKT_FCST_C
                 WHERE YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND MEASURE = 'AS_INV'
                   AND DIVISION_ID = P_DIVISION_ID
                   AND VERSION_NO  = P_VERSION_NO ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* 한 SITE,ITEM 에 SITE_SEQ=1 여러개면 조정( NULL ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT KEY_VAL
                  FROM ( SELECT KEY_VAL
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL ) AS SUB_SEQ
                           FROM GT_PRDM_AS_INV
                          WHERE SITE_SEQ = 1 )
                 WHERE SUB_SEQ <> 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = NULL;

        /* SITE_SEQ 없는 SITE 조정 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT C.KEY_VAL
                  FROM ( SELECT KEY_VAL, DIVISION_ID, SCM_SITE_ID, ITEM_ID
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL DESC ) AS ROW_NUM
                           FROM GT_PRDM_AS_INV ) C
                  JOIN ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS SITE_SEQ
                           FROM GT_PRDM_AS_INV
                          GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) D
                    ON C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID
                 WHERE D.SITE_SEQ IS NULL
                   AND C.ROW_NUM = 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240214-000835] 기초재고 추가 ( 81 / 그 외 분기 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID = '81' THEN

            /* 81 : AS_STORAGE_YN='Y' 인 행의 재고만 사용, MKT FCST 기준 데이터로 생성 */
            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SEQ
                 , A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일(당주 월요일 -1). DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.FROM_SITE AS SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ
                       FROM ( SELECT DIVISION_ID, FROM_SITE, ITEM_ID, MIN(SEQ) AS MIN_SEQ
                                FROM GT_PRDM_END_RTF_RAW
                               GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID ) A
                       JOIN GT_PRDM_END_RTF_RAW B ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_SITE = B.FROM_SITE AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SEQ
                      UNION ALL
                      SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ, A.AS_PLANT;

        ELSE

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SITE_SEQ, A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일. DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2 AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ, A.AS_PLANT;

        END IF;

        /* AS_PLANT 일괄 업데이트 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT SEGMENT3, SEGMENT1, MAX(SEGMENT2) AS SEGMENT2
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'AS_SITE_PLANT' AND VALID_YN = 'Y'
                 GROUP BY SEGMENT3, SEGMENT1 ) B
        ON ( A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 )
        WHEN MATCHED THEN UPDATE SET A.AS_PLANT = B.SEGMENT2;

        /* --------------------------------------------------------------------------------------- */
        /* AS PLANT 기준 모델 적재 -> GT_PRDM_AS_LOOP ( SEQ 1부터 연속채번 ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + B.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , C.SEGMENT2 AS FROM_PLANT
                   FROM GT_PRDM_AS_INV A
                   JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_PLANT = B.SCM_SITE_ID
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                  WHERE A.SITE_SEQ = 1 ) X;

        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ( SELECT NVL(MAX(SEQ), 0) FROM GT_PRDM_AS_LOOP ) + ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , B.SEGMENT2 AS FROM_PLANT
                   FROM DM_PLN_MKT_FCST_C A
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y'
                   JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND B.SEGMENT2 = C.SCM_SITE_ID
                   LEFT OUTER JOIN GT_PRDM_AS_LOOP E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID AND A.ITEM_ID = E.ITEM_ID
                   JOIN ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, C.SEGMENT2
                            FROM GT_PRDM_AS_INV A
                            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                         ) F ON A.DIVISION_ID = F.DIVISION_ID AND A.SCM_SITE_ID = F.SCM_SITE_ID AND A.ITEM_ID = F.ITEM_ID
                  WHERE A.DIVISION_ID = P_DIVISION_ID
                    AND A.VERSION_NO  = P_VERSION_NO
                    AND A.YYYYMMDD >= V_SHIP_START_YYYYMMDD
                    AND E.DIVISION_ID IS NULL ) X;

        /* --------------------------------------------------------------------------------------- */
        /* #T_AS_INV 일자별 재고 생성 루프 ( 첫 AS_LOOP WHILE ) */
        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID
              INTO V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID
              FROM GT_PRDM_AS_LOOP
             WHERE SEQ = I;

            BEGIN
                SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  INTO V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
                  FROM ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                           FROM GT_PRDM_AS_INV
                          WHERE DIVISION_ID = V_DIVISION_ID
                            AND SCM_SITE_ID = V_SCM_SITE_ID
                            AND ITEM_ID = V_ITEM_ID
                            AND SITE_SEQ = 1 )
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
            SELECT DISTINCT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, 'AS_Inv', A.BASIS_YYYYMMDD, V_PLANT_SITE_ID
                 , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_INV') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )
                 , B.SITE_SEQ
              FROM SCM_SYS_CALENDAR_M A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.BASIS_YYYYMMDD = B.YYYYMMDD
                                              AND B.DIVISION_ID = V_DIVISION_ID
                                              AND B.SCM_SITE_ID = V_SCM_SITE_ID
                                              AND B.ITEM_ID = V_ITEM_ID
             WHERE A.BASIS_YYYYMMDD BETWEEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                                        AND TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + 7*16, 'YYYYMMDD');

            /* 기초재고 일자 중복행 삭제 ( 나중에 넣은 데이터 ) */
            DELETE FROM GT_PRDM_AS_INV A
             WHERE A.YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
               AND A.AS_PLANT IS NULL;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240226-000021] 54주 보완 : SITE_SEQ 없는 AS_Inv 최초일자에 SITE_SEQ=1 */
        /* --------------------------------------------------------------------------------------- */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MIN(YYYYMMDD) AS YYYYMMDD
                  FROM GT_PRDM_AS_INV C
                 WHERE SITE_SEQ IS NULL
                   AND MEASURE = 'AS_Inv'
                   AND NOT EXISTS ( SELECT 1 FROM GT_PRDM_AS_INV D
                                     WHERE D.MEASURE = 'AS_Inv' AND D.SITE_SEQ = 1
                                       AND C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID )
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD      = B.YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1 WHERE A.MEASURE = 'AS_Inv';

        /* --------------------------------------------------------------------------------------- */
        /* 받는 Site 들에 RTF 생성 ( SSP 확정구간 이후 ) : MKT FCST 취합 -> GT_PRDM_RTF */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_RTF ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_PLANT, ETD_DATE, SITE_SEQ )
        SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.MEASURE, B.YYYYMMDD, B.PLANT_SITE_ID, B.QTY
             , A.FROM_SITE, TO_CHAR(TO_DATE(B.YYYYMMDD, 'YYYYMMDD') - A.LT_TOTAL, 'YYYYMMDD')
             , ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, A.FROM_SITE, B.ITEM_ID, B.YYYYMMDD ORDER BY B.SCM_SITE_ID )
          FROM ( SELECT A.SEGMENT2 AS FROM_SITE, B.TO_SITE, B.LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, B.FROM_SITE, B.TO_SITE ORDER BY B.PRIORITY ) AS BOD_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                   JOIN SCP_MST_BOD_N_V B ON A.SEGMENT2 = B.FROM_SITE AND B.DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.FROM_YYYYMMDD AND B.TO_YYYYMMDD
                   JOIN SCM_MST_SITE C ON B.TO_SITE = C.SCM_SITE_ID AND C.SITE_TYPE = 'SALES' AND C.VALID_YN = 'Y' AND C.DIVISION_ID = P_DIVISION_ID
                  WHERE A.LOOKUP_TYPE = 'AS_SITE_PLANT' AND A.SEGMENT3 = P_DIVISION_ID AND A.VALID_YN = 'Y' ) A
          JOIN DM_PLN_MKT_FCST_C B ON A.TO_SITE = B.SCM_SITE_ID AND B.MEASURE = 'MKT_FCST' AND B.YYYYMMDD >= V_START_YYYYMMDD
                                  AND A.FROM_SITE = B.ATTRIBUTE10 AND B.DIVISION_ID = P_DIVISION_ID AND B.VERSION_NO = P_VERSION_NO
          JOIN SCM_MST_SITE C ON A.FROM_SITE = C.SCM_SITE_ID AND C.DIVISION_ID = P_DIVISION_ID
         WHERE A.BOD_SEQ = 1
           AND B.YYYYMMDD > CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END
           AND B.QTY <> 0;

        UPDATE GT_PRDM_RTF A
           SET A.ALLOC_SCD_RTF = CASE WHEN A.YYYYMMDD > NVL( ( SELECT MAX(YYYYMMDD)
                                                                 FROM GT_PRDM_END_RTF_RAW E
                                                                WHERE E.MEASURE IN ('RTF', 'SSP_RTF')
                                                                  AND E.DIVISION_ID = A.DIVISION_ID
                                                                  AND E.SCM_SITE_ID = A.SCM_SITE_ID ), '19000101' )
                                      THEN 'Y' ELSE 'N' END;


        INSERT INTO GT_PRDM_RTF_SITE ( FROM_SITE, SCM_SITE_ID, MAX_YMD )
        SELECT A.FROM_SITE, A.SCM_SITE_ID
             , CASE WHEN NVL(D.MAX_YMD, '19000101') > CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                                                           ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
                    THEN D.MAX_YMD
                    ELSE CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                              ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
               END
          FROM ( SELECT DISTINCT FROM_SITE, SCM_SITE_ID, AS_PLANT FROM GT_PRDM_END_RTF_RAW ) A
          JOIN SCM_MST_SITE B ON A.AS_PLANT = B.SCM_SITE_ID AND B.DIVISION_ID = P_DIVISION_ID
          JOIN ( SELECT FROM_SITE, TO_SITE, LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                   FROM SCP_MST_BOD_N_V
                  WHERE DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD ) C
            ON A.AS_PLANT = C.FROM_SITE AND A.SCM_SITE_ID = C.TO_SITE AND C.PRT = 1
          LEFT OUTER JOIN ( SELECT FROM_SITE, SCM_SITE_ID, MAX(YYYYMMDD) AS MAX_YMD
                              FROM GT_PRDM_END_RTF_RAW
                             WHERE MEASURE = 'RTF'
                             GROUP BY FROM_SITE, SCM_SITE_ID ) D
            ON A.FROM_SITE = D.FROM_SITE AND A.SCM_SITE_ID = D.SCM_SITE_ID;

        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, SCM_SITE_ID, MAX(MAX_YMD) AS MAX_YMD
                  FROM GT_PRDM_RTF_SITE
                 GROUP BY FROM_SITE, SCM_SITE_ID ) B
        ON ( A.SCM_SITE_ID = B.SCM_SITE_ID AND A.FROM_SITE = B.FROM_SITE )
        WHEN MATCHED THEN UPDATE SET A.SCD_ALLOC_START_DATE = B.MAX_YMD;

        UPDATE GT_PRDM_END_RTF_RAW
           SET LT_YYYYMMDD = TO_CHAR(TO_DATE(YYYYMMDD, 'YYYYMMDD') - NVL(LT_DAYS, 0), 'YYYYMMDD')
         WHERE MEASURE = 'MKT_FCST';

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT A.DIVISION_ID, A.FROM_PLANT, A.SCM_SITE_ID, A.ITEM_ID, TRUNC(NVL(B.QTY, 0)), A.CALC_START_DATE
                 , 0
                 , TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + 7*82, 'YYYYMMDD')
                 , 0, 0
              INTO V_DIVISION_ID, V_FROM_PLANT, V_FROM_SITE, V_ITEM_ID, V_INV_QTY, V_DATE
                 , V_SUM_REQ_QTY
                 , V_MAX_DATE
                 , V_INV_ADJ_QTY, V_SUM_REQ_QTY
              FROM GT_PRDM_AS_LOOP A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                   AND B.YYYYMMDD = TO_CHAR(TO_DATE(A.CALC_START_DATE, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND B.MEASURE = 'AS_INV'
             WHERE A.SEQ = I;

            WHILE ( V_DATE <= V_MAX_DATE ) LOOP


                SELECT V_INV_QTY + NVL(SUM(QTY), 0)
                  INTO V_INV_QTY
                  FROM GT_PRDM_AS_INV
                 WHERE MEASURE = 'AS_In_Plan'
                   AND DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE;
                V_INV_QTY := TRUNC(V_INV_QTY);

                SELECT NVL(SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), 0)
                  INTO V_SUM_REQ_QTY
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE AS_PLANT = V_FROM_PLANT
                   AND ITEM_ID = V_ITEM_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND LT_YYYYMMDD <= V_DATE
                   AND MEASURE = 'MKT_FCST'
                   AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                /* 재고보다 요청수량이 적으면 요청만큼 생성 */
                IF ( V_SUM_REQ_QTY <= V_INV_QTY ) THEN

                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), A.PLANT_SITE_ID, SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), NULL, A.AS_PLANT, 'Y'
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0)
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                         , A.PLANT_SITE_ID, A.AS_PLANT, TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD');

                    UPDATE GT_PRDM_END_RTF_RAW A
                       SET RTF_QTY = MF_QTY
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    V_INV_QTY := TRUNC(V_INV_QTY - V_SUM_REQ_QTY);

                ELSE  /* 재고가 적으면 배분 */

                    DELETE FROM GT_PRDM_RCV;

                    INSERT INTO GT_PRDM_RCV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_SITE, ETD_DATE, SITE_SEQ, RTF_RAW_KEY_VAL )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), PLANT_SITE_ID
                         , NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)
                         , AS_PLANT, V_DATE
                         , ROW_NUMBER() OVER ( ORDER BY A.YYYYMMDD, A.SCM_SITE_ID )
                         , KEY_VAL
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    SELECT 1, COUNT(*) INTO I_RCV, CNT_RCV FROM GT_PRDM_RCV;

                    WHILE ( I_RCV <= CNT_RCV AND V_INV_QTY > 0 ) LOOP

                        SELECT QTY, RTF_RAW_KEY_VAL INTO V_REQ_QTY, V_KEY_VAL
                          FROM GT_PRDM_RCV
                         WHERE SITE_SEQ = I_RCV;

                        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                             , A.YYYYMMDD, A.PLANT_SITE_ID
                             , SUM( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END )
                             , A.SITE_SEQ, A.FROM_SITE, 'Y'
                          FROM GT_PRDM_RCV A
                         WHERE SITE_SEQ = I_RCV
                         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                             , A.YYYYMMDD, A.PLANT_SITE_ID, A.SITE_SEQ, A.FROM_SITE;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = RTF_QTY + CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END
                         WHERE KEY_VAL = V_KEY_VAL;

                        V_INV_QTY := TRUNC( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_INV_QTY - V_REQ_QTY ELSE 0 END );

                        I_RCV := I_RCV + 1;
                    END LOOP;

                END IF;

                /* Inv Insert / Update */
                UPDATE GT_PRDM_AS_INV
                   SET QTY = V_INV_QTY
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE
                   AND MEASURE = 'AS_Inv';

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'AS_Inv', V_DATE, A.PLANT_SITE_ID
                         , V_INV_QTY, 1
                      FROM GT_PRDM_AS_INV A
                     WHERE A.DIVISION_ID = V_DIVISION_ID
                       AND A.SCM_SITE_ID = V_FROM_SITE
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.MEASURE = 'AS_Inv'
                       AND A.SITE_SEQ = 1
                       AND ROWNUM = 1;
                END IF;

                V_DATE := TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD');

            END LOOP;

            I := I + 1;
        END LOOP;


        DELETE FROM GT_PRDM_AS_INV WHERE YYYYMMDD < V_START_YYYYMMDD;

        /* --------------------------------------------------------------------------------------- */
        /* 결과 INSERT : DM_PLN_MKT_FCST_C ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_MKT_FCST_C A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_MKT_FCST_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', '', '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_MKT_FCST_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, P_VERSION_NO AS VERSION_NO, V_CUTOFF_TYPE AS CUTOFF_TYPE, V_CUTOFF_YYYYMMDD AS CUTOFF_YYYYMMDD
                      , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID, A.YYYYMMDD
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID, A.YYYYMMDD
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, '' AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_MKT_FCST_C B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND NVL(A.PROJECT_CODE, '@') = NVL(B.PROJECT_CODE, '@')
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND NVL(A.DOM_EXP, '@') = NVL(B.DOM_EXP, '@')
           AND NVL(A.FCST_TYPE, '@') = NVL(B.FCST_TYPE, '@')
           AND NVL(A.INCOTERMS, '@') = NVL(B.INCOTERMS, '@')
           AND A.MEASURE = B.MEASURE
           AND NVL(A.PLANT_SITE_ID, '@') = NVL(B.PLANT_SITE_ID, '@')
           AND A.YYYYMMDD = B.YYYYMMDD
           AND B.VERSION_NO = P_VERSION_NO
           AND B.CUTOFF_TYPE = V_CUTOFF_TYPE
           AND B.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
         WHERE B.DIVISION_ID IS NULL;

        /* --------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] 결과 INSERT : DM_PLN_CFM_MKT_DEMAND_PLAN_C ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.VERSION_NO  = P_VERSION_NO
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, P_VERSION_NO, V_CUTOFF_TYPE, V_CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, '-', A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, '-', A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', NULL, '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN_C
            ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
            , PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD
             , A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.FROM_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, P_VERSION_NO AS VERSION_NO, V_CUTOFF_TYPE AS CUTOFF_TYPE, V_CUTOFF_YYYYMMDD AS CUTOFF_YYYYMMDD
                      , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , '-' AS FROM_SITE_ID, A.YYYYMMDD
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, NULL AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_CFM_MKT_DEMAND_PLAN_C B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND NVL(A.PROJECT_CODE, '@') = NVL( CASE WHEN B.DIVISION_ID = '40' THEN B.END_CUSTOMER ELSE B.PROJECT_CODE END, '@')
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND NVL(A.DOM_EXP, '@') = NVL(B.DOM_EXP, '@')
           AND NVL(A.FCST_TYPE, '@') = NVL(B.FCST_TYPE, '@')
           AND NVL(A.INCOTERMS, '@') = NVL(B.INCOTERMS, '@')
           AND A.MEASURE = B.MEASURE
           AND NVL(A.PLANT_SITE_ID, '@') = NVL(B.PLANT_SITE_ID, '@')
           AND A.YYYYMMDD = B.YYYYMMDD
           AND B.VERSION_NO = P_VERSION_NO
           AND B.CUTOFF_TYPE = V_CUTOFF_TYPE
           AND B.CUTOFF_YYYYMMDD = V_CUTOFF_YYYYMMDD
         WHERE B.DIVISION_ID IS NULL;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / @P_VERSION_NO: ' || P_VERSION_NO
                             || '/ ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                , V_DESCRIPTION, TO_CHAR(SQLCODE), SUBSTR(SQLERRM, 1, 1000), SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 1000));
    END;


    IF V_LOG_TYPE IS NULL OR V_LOG_TYPE <> 'ERROR' THEN
        V_LOG_TYPE    := 'END';
        V_LOG_MESSAGE := '########## END OF PROCEDURE ##########';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END IF;

END PR_DM_DNM_CREATE_C_WS_RTF;
/
SHOW ERRORS PROCEDURE PR_DM_DNM_CREATE_C_WS_RTF
-- ##### END PROCEDURE PR_DM_DNM_CREATE_C_WS_RTF

-- ##### START PROCEDURE PR_DM_DNM_CREATE_WS_RTF
CREATE OR REPLACE PROCEDURE           "PR_DM_DNM_CREATE_WS_RTF" 
(
    P_DIVISION_ID   IN  VARCHAR2  /* 사업부 확장에 대비해서 사업부별로 호출하도록 한다. */
)
/* ==============================================================================================================================================
 * PROGRAM ID   : PR_DM_DNM_CREATE_WS_RTF
 * DESCRIPTION  : W/S 의 Sales Site 의 RTF 를 생성 ( Shipment Plan 참조 )
 * PROGRAM HISTORY
 *==============================================================================================================================================
 *   DATE       IN CHARGE      DESCRIPTION
 *==============================================================================================================================================
 * 2021.09.27   hwi1993     [PJ20209643]    INITIAL RELEASE
 * 2021.11.04   HWI1993     운영 적용후 보완
 * 2021.11.16   HWI1993     룩업에 VALID 조건 추가
 * 2021.12.23   HWI1993     FCST TYPE 조건 변경
 * 2022.01.21   HWI1993     C20220118-000097 MKT FSCT에 RTF 미조회 건 - 고객향 RTF 메저에 ATTR10 에 FROM_PLANT 추가함( MKT FCST 화면에서 조회용 )
 * 2022.04.05   HWI1993     GM JV 작업
 * 2022.04.12   Hwi1993     확정구간의 ETA 와 미확정구간의 RTF 가 겹쳐서 발생하는 오류 수정
 * 2022.08.30   Hwi1993     PK 오류 수정
 * 2022.11.04   HWI1993     [C20220916-000290] [SCM PI] DM 시스템의 AS RTF 정확도 향상을 위한 기능변경 건
 * 2022.11.22   HWI1993     [C20220916-000290] 오류 수정 재배포
 * 2024.02.19   JSSBAE      [E20240214-000835]_[영업마케팅 PI팀] 81번사업부 AS Inv 생성 로직 변경 요청
 * 2024.03.15   JSSBAE      [E20240226-000021]_52주구간 AS INV VIEW 확보
 * 2024.09.26   JSSBAE      [E20240926-001366]_[공급 SCM PI팀] AS 관련 메저 생성 시 SCPSSP RTF간 우선순위 지정(SCP RTF 우선시)
 *                          PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE에서 기 생성된 RTF_SCP와 SSP_RTF가 겹치는 현상이 발생하여 수정
 * 2024.10.21   JSSBAE      [E20241007-000267]_[공급 SCM PI팀] AS 관련 메저 생성 시 SSP 기존 로직 제거
 *                          82 사업부는 현행과 동일한 개념으로 진행, 81 사업부는 SSP 개념을 모두 제거한 부분으로 수정
 * 2024.12.01   KANG.H.J    [PJ2024-50611] BPS 매출(RTF_SYS_RP Measrue) 전송 시 전 사업부 FROM_SITE_ID 추가
 * 2025.01.13   P.C.I       [E20250113-000270]_[공급/생산 SCM PI팀] 운송중 재고 AS RTF 산출시 적용 요청
 * 2025.01.31   JSSBAE      [E20250120-000036]_[공급/생산 SCM PI팀] AS Inv -> RTF 생성로직 개선 (재고 기반 RTF 산출)
 * 2025.02.05   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_CFM_MKT_DEMAND_PLAN 동기화
 * 2025.04.08   KANG.H.J    오류 대응 - DM_PLN_CFM_MKT_DEMAND_PLAN PROJECT_CODE 조인시 사업부별 조건처리
 * 2025.04.08   KANG.H.J    [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025.09.09   JSSBAE      [E20250909-000795]_Kangoo 모델 AS INV REQ 값 이상[RTF 미산출)
 * 2026.05.26   JSSBAE      [E20260402-001736]_AS 관련 기능 개선 건
 * 2026.09.18   AJS         40·82 PLANT_SITE_ID, 81·82 END_CUSTOMER 빈값 채움값 ' '·'' → '-' 통일(14자리)
 *==============================================================================================================================================
 *   USAGE : EXEC PR_DM_DNM_CREATE_WS_RTF '82'
 *----------------------------------------------------------------------------------------------------------------------------------------------
 *     - PLANT_SITE_ID/END_CUSTOMER(NOT NULL) : ''->' '(공백), CELL_PROD_SITE_ID '-', ATTRIBUTE10 <> '' -> IS NOT NULL
 *============================================================================================================================================== */
IS

    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_DNM_CREATE_WS_RTF';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    N_DELETE_COUNT        NUMBER := 0;
    N_INSERT_COUNT        NUMBER := 0;
    V_CREATED_BY          VARCHAR2(150 CHAR) := 'SYSTEM_WS';

    V_START_YYYYMMDD      VARCHAR2(8 CHAR);  /* 당주 월요일 */
    V_SHIP_START_YYYYMMDD VARCHAR2(8 CHAR);


    I                     NUMBER;
    CNT                   NUMBER;
    SUB_I                 NUMBER;
    SUB_CNT               NUMBER;
    V_ALLOC_I             NUMBER;
    V_ALLOC_CNT           NUMBER;
    V_YYYYMMDD            VARCHAR2(8 CHAR);
    V_INV                 NUMBER(20,10);
    V_RTF                 NUMBER(20,10);
    V_SSP_RTF             NUMBER(20,10);
    V_MKT_FCST            NUMBER(20,10);
    V_MKT_FCST_NET        NUMBER(20,10);
    V_SCM_SITE_ID         VARCHAR2(30 CHAR);
    V_PROJECT_CODE        VARCHAR2(50 CHAR);
    V_ITEM_ID             VARCHAR2(50 CHAR);
    V_ALLOC_SUM_RTF       NUMBER(20,10);
    V_ALLOC_RTF           NUMBER(20,10);

    I_SUB                 NUMBER;
    CNT_SUB               NUMBER;
    V_DIVISION_ID         VARCHAR2(30 CHAR);
    V_DOM_EXP             VARCHAR2(3 CHAR);
    V_FCST_TYPE           VARCHAR2(20 CHAR);
    V_INCOTERMS           VARCHAR2(10 CHAR);
    V_PLANT_SITE_ID       VARCHAR2(30 CHAR);
    V_INV_QTY             NUMBER;

    V_SITE_SEQ            NUMBER;
    V_DATE                VARCHAR2(8 CHAR);
    V_MAX_DATE            VARCHAR2(8 CHAR);
    V_FROM_SITE           VARCHAR2(30 CHAR);
    V_FROM_PLANT          VARCHAR2(30 CHAR);

    V_SUM_REQ_QTY         NUMBER(30,10);
    V_REQ_QTY             NUMBER(30,10);
    V_REM_QTY             NUMBER(30,10);
    I_RCV                 NUMBER;
    CNT_RCV               NUMBER;
    V_INV_ADJ_QTY         NUMBER(30,10);
    V_KEY_VAL             NUMBER;

BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## START OF PROCEDURE ##########';
    V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        /* 당주 월요일 */
        V_START_YYYYMMDD      := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');
        V_SHIP_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');

        /* --------------------------------------------------------------------------------------- */

        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_SSP;
        DELETE FROM GT_PRDM_END_RTF_RAW;
        DELETE FROM GT_PRDM_AS_INV;
        DELETE FROM GT_PRDM_END_RTF_LOOP;
        DELETE FROM GT_PRDM_AS_LOOP;
        DELETE FROM GT_PRDM_RTF;
        DELETE FROM GT_PRDM_RCV;
        DELETE FROM GT_PRDM_RTF_SITE;

        /* --------------------------------------------------------------------------------------- */
        /* 1. 기존 RTF 계열 삭제 ( 고객향 / AS Plant향 ) */
        /* rtf 계열 메저에는 attr10 이 없으므로 생성자(CREATED_BY)를 이용해서 삭제한다. */
        /* --------------------------------------------------------------------------------------- */
        /* 고객향 */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');  /* [PJ2025-50017] RTF_PR 신규 추가 */

        /* AS Plant향 */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 매출계획 동기화 : 고객향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* [PJ2025-50017] 소형 매출계획 동기화 : AS Plant향 */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE EXISTS ( SELECT 1
                          FROM SCM_MST_SITE B
                         WHERE A.DIVISION_ID     = B.DIVISION_ID
                           AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                           AND B.OPERATION_GROUP = 'W'
                           AND B.SITE_TYPE       = 'SALES' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.CREATED_BY  = V_CREATED_BY
           AND A.YYYYMMDD   >= V_START_YYYYMMDD
           AND A.MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'AS_SHIP_PLAN', 'RTF_PR');

        /* --------------------------------------------------------------------------------------- */
        /* Ship Confirm -> GT_PRDM_SSP  ( 최종 RTF 가 아니라서 SSP_RTF 로 넣는다. ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_SSP ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
            , INCOTERMS, MEASURE, PLANT_SITE_ID, AS_SITE, ETA_YYYYMMDD, SHIP_YYYYMMDD, QTY, GUBUN, AS_FROM_PLANT )
        SELECT T0.DIVISION_ID
             , T0.PROJECT_CODE
             , T0.TO_SITE
             , T0.ITEM_ID
             , 'E'
             , T0.FCST_TYPE
             , T1.INCOTERMS
             , 'SSP_RTF'
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1
             , T0.ETA_DATE
             , T0.YYYYMMDD
             , SUM(T0.QTY)
             , 'CONFIRM'
             , T3.SEGMENT2
          FROM SSP_ANL_SHIP_CONFIRM T0
          JOIN SCP_MST_BOD_N_V T1 ON T0.DIVISION_ID = T1.DIVISION_ID AND T0.BOD_ID = T1.BOD_ID
          JOIN SCP_MST_DISTRIBUTION_ROUTE T2 ON T2.ROUTE_ID = T1.ROUTE_ID
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T3 ON T0.FROM_SITE = T3.SEGMENT2 AND T3.LOOKUP_TYPE = 'AS_SITE_PLANT' AND T3.SEGMENT2 <> '-' AND T3.SEGMENT3 = P_DIVISION_ID AND T3.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T4 ON T0.TO_SITE = T4.SCM_SITE_ID AND T0.DIVISION_ID = T4.DIVISION_ID AND T4.SITE_TYPE = 'SALES'
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL T5 ON T0.FCST_TYPE = T5.SEGMENT1 AND T5.LOOKUP_TYPE = 'SALES_TYPE_CODE2' AND T5.VALID_YN = 'Y'
          JOIN SCM_MST_SITE T6 ON T0.FROM_SITE = T6.SCM_SITE_ID AND T0.DIVISION_ID = T6.DIVISION_ID
         WHERE 1 = 1
           /* [E20250120-000036] 81 사업부인 경우 SHIP_FROZEN 미적용 */
           AND ( T0.YYYYMMDD BETWEEN V_SHIP_START_YYYYMMDD AND CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + T6.SHIP_FROZEN, 'YYYYMMDD') END
                 OR ( T0.YYYYMMDD < TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
                      AND T0.ETA_DATE >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD') )
               )
           AND T0.QTY <> 0
           AND T0.DIVISION_ID = P_DIVISION_ID
           AND T0.FCST_TYPE <> '-'  /* MKT_FCST 없는 경우 */
           AND T0.SHIPMENT_STATUS = 'C'
           AND T0.CHANGE_TYPE = 'C'
           AND T0.ETA_DATE IS NOT NULL
         GROUP BY T0.DIVISION_ID, T0.PROJECT_CODE, T0.TO_SITE, T0.ITEM_ID, T0.FCST_TYPE, T1.INCOTERMS
             , CASE WHEN T0.DIVISION_ID LIKE '81%' THEN T0.FROM_SITE_PLANT_ID ELSE '' END
             , T3.SEGMENT1, T0.ETA_DATE, T0.YYYYMMDD, T3.SEGMENT2;

        /* 소형 DOM_EXP 보정 1 ( 키 + YYYYMMDD 일치 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS, A.YYYYMMDD ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS
            AND B.YYYYMMDD     = A.ETA_YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP;

        /* 동일 일자 값 없는 건 : YYYYMMDD 제외 재보정 ( DOM_EXP='E' 인 건만 ) */
        MERGE INTO GT_PRDM_SSP A
        USING ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS
                     , MAX(A.DOM_EXP) AS DOM_EXP
                  FROM DM_PLN_MKT_FCST A
                 WHERE A.DIVISION_ID = P_DIVISION_ID
                   AND A.YYYYMMDD BETWEEN V_START_YYYYMMDD AND TO_CHAR(ADD_MONTHS(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD'), 3), 'YYYYMMDD')
                   AND A.MEASURE IN ('RTF_SCP', 'MKT_FCST')
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.FCST_TYPE, A.INCOTERMS ) B
        ON (    B.DIVISION_ID  = A.DIVISION_ID
            AND B.PROJECT_CODE = A.PROJECT_CODE
            AND B.SCM_SITE_ID  = A.SCM_SITE_ID
            AND B.ITEM_ID      = A.ITEM_ID
            AND B.FCST_TYPE    = A.FCST_TYPE
            AND B.INCOTERMS    = A.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.DOM_EXP = B.DOM_EXP WHERE A.DOM_EXP = 'E';

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 RTF / MKT FCST -> GT_PRDM_END_RTF_RAW */
        /* [E20241007-000267] 81 사업부는 SSP RTF 미사용. 82/40 만 SSP 구간 생성. */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN
            /* 고객향 RTF INSERT ( FROM SSP, FROM AS SITE ) */
            INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD
                 , A.FCST_TYPE, A.INCOTERMS, 'SSP_RTF', CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY)
                 , A.AS_SITE, A.AS_FROM_PLANT
              FROM GT_PRDM_SSP A
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 , A.FCST_TYPE, A.INCOTERMS, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.ETA_YYYYMMDD, A.AS_SITE, A.AS_FROM_PLANT;
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
        END IF;

        /* 고객향 MKT FCST INSERT */
        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, MF_QTY, RTF_QTY, FROM_SITE, AS_PLANT )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, 'MKT_FCST', A.PLANT_SITE_ID, A.YYYYMMDD
             , SUM(A.QTY), SUM(A.QTY), 0, C.SEGMENT1, A.ATTRIBUTE10
          FROM DM_PLN_MKT_FCST A
          /* AS PLANT 정보 */
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID
                             AND A.ATTRIBUTE10 = B.SCM_SITE_ID
                             AND B.OPERATION_GROUP = 'W'
                             AND B.SITE_TYPE = 'PLANT'
          /* AS SITE 로 변환 */
          JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SCM_SITE_ID = C.SEGMENT2 AND B.DIVISION_ID = C.SEGMENT3 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE IN ('MKT_FCST')
           AND A.YYYYMMDD >= V_START_YYYYMMDD
           AND A.ATTRIBUTE10 IS NOT NULL  /* 원본 ATTRIBUTE10 <> '' */
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, A.ATTRIBUTE10, C.SEGMENT1
        HAVING SUM(A.QTY) <> 0;  /* 20231124 [SM] 수량0제외 */

        /* #RAW 에 LT 추가 */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                  FROM ( SELECT FROM_SITE, TO_SITE, INCOTERMS, LT_TOTAL
                              , ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                           FROM SCP_MST_BOD_V
                          WHERE DIVISION_ID = P_DIVISION_ID
                            AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD )
                 WHERE PRT = 1 ) B
        ON ( A.AS_PLANT = B.FROM_SITE AND A.SCM_SITE_ID = B.TO_SITE AND A.INCOTERMS = B.INCOTERMS )
        WHEN MATCHED THEN UPDATE SET A.LT_DAYS = B.LT_TOTAL;

        /* SEQ ( DENSE_RANK by YYYYMMDD ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SEQ = B.SEQ;

        /* MF_SEQ ( MKT_FCST 한정 DENSE_RANK by YYYYMMDD,QTY ) */
        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT KEY_VAL
                     , DENSE_RANK() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID ORDER BY YYYYMMDD, QTY ) AS SEQ
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE MEASURE = 'MKT_FCST' ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.MF_SEQ = B.SEQ;

        /* --------------------------------------------------------------------------------------- */
        /* 고객향 SITE 재고 루프 ( 도착 SSP RTF 를 입고로 보고 MKT FCST 발생일에 재고가 있으면 RTF 생성 ) */

        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_END_RTF_LOOP ( SCM_SITE_ID, PROJECT_CODE, ITEM_ID, SEQ )
        SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
             , ROW_NUMBER() OVER ( ORDER BY SCM_SITE_ID, PROJECT_CODE, ITEM_ID ) - 1
          FROM ( SELECT DISTINCT SCM_SITE_ID, PROJECT_CODE, ITEM_ID FROM GT_PRDM_END_RTF_RAW );

        SELECT 0, MAX(SEQ) INTO I, CNT FROM GT_PRDM_END_RTF_LOOP;
        V_SCM_SITE_ID  := NULL;
        V_PROJECT_CODE := NULL;
        V_ITEM_ID      := NULL;

        /* 할당단위별 루프 */
        WHILE I <= CNT LOOP

            SELECT SCM_SITE_ID, PROJECT_CODE, ITEM_ID
              INTO V_SCM_SITE_ID, V_PROJECT_CODE, V_ITEM_ID
              FROM GT_PRDM_END_RTF_LOOP
             WHERE SEQ = I;

            SELECT 1, NVL(MAX(A.SEQ), 0), 0, 0, 0, 0, 0, NULL
              INTO SUB_I, SUB_CNT, V_INV, V_RTF, V_SSP_RTF, V_MKT_FCST, V_MKT_FCST_NET, V_YYYYMMDD
              FROM GT_PRDM_END_RTF_RAW A
             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
               AND A.PROJECT_CODE = V_PROJECT_CODE
               AND A.ITEM_ID      = V_ITEM_ID
               AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST');

            /* 단위 내에서 일자별(순번별) 루프 */
            WHILE ( SUB_I <= SUB_CNT ) LOOP

                SELECT SUM(CASE WHEN A.MEASURE = 'SSP_RTF' THEN A.QTY ELSE 0 END)
                     , SUM(CASE WHEN A.MEASURE = 'MKT_FCST' THEN A.QTY ELSE 0 END)
                     , MAX(A.YYYYMMDD)
                  INTO V_SSP_RTF, V_MKT_FCST, V_YYYYMMDD
                  FROM GT_PRDM_END_RTF_RAW A
                 WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                   AND A.PROJECT_CODE = V_PROJECT_CODE
                   AND A.ITEM_ID      = V_ITEM_ID
                   AND A.MEASURE IN ('SSP_RTF', 'MKT_FCST')
                   AND A.SEQ = SUB_I;

                /* 당일의 기초재고 및 요청총량 계산 */
                V_INV          := V_INV + NVL(V_SSP_RTF, 0);
                V_MKT_FCST_NET := V_MKT_FCST_NET + NVL(V_MKT_FCST, 0);

                /* 당일에 풀 수 있는 수량 및 재고 정리 */
                IF V_INV >= V_MKT_FCST_NET THEN
                    V_INV          := V_INV - V_MKT_FCST_NET;
                    V_RTF          := V_MKT_FCST_NET;
                    V_MKT_FCST_NET := 0;
                ELSE
                    V_RTF          := V_INV;
                    V_MKT_FCST_NET := V_MKT_FCST_NET - V_INV;
                    V_INV          := 0;
                END IF;

                IF ( V_RTF > 0 ) THEN

                    SELECT 0, 0, MIN(A.SEQ)
                      INTO V_ALLOC_SUM_RTF, V_ALLOC_RTF, V_ALLOC_I
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                       AND A.PROJECT_CODE = V_PROJECT_CODE
                       AND A.ITEM_ID      = V_ITEM_ID
                       AND A.MEASURE IN ('MKT_FCST')
                       AND A.SEQ <= SUB_I
                       AND A.RTF_QTY < A.MF_QTY;

                    /* 하나씩 풀면서 V_RTF 숫자에 도달할때까지 넣어준다. */
                    WHILE ( V_ALLOC_SUM_RTF < V_RTF ) LOOP

                        V_ALLOC_RTF := 0;

                        BEGIN
                            SELECT CASE WHEN A.QTY - NVL(A.RTF_QTY, 0) < V_RTF - V_ALLOC_SUM_RTF THEN A.QTY - NVL(A.RTF_QTY, 0)
                                        ELSE V_RTF - V_ALLOC_SUM_RTF END
                              INTO V_ALLOC_RTF
                              FROM GT_PRDM_END_RTF_RAW A
                             WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                               AND A.PROJECT_CODE = V_PROJECT_CODE
                               AND A.ITEM_ID      = V_ITEM_ID
                               AND A.MEASURE IN ('MKT_FCST')
                               AND A.SEQ = V_ALLOC_I
                               AND ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN EXIT;
                        END;

                        INSERT INTO GT_PRDM_END_RTF_RAW ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, FROM_SITE, AS_PLANT )
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF', PLANT_SITE_ID, V_YYYYMMDD
                             , V_ALLOC_RTF, FROM_SITE, AS_PLANT
                          FROM GT_PRDM_END_RTF_RAW A
                         WHERE A.SCM_SITE_ID  = V_SCM_SITE_ID
                           AND A.PROJECT_CODE = V_PROJECT_CODE
                           AND A.ITEM_ID      = V_ITEM_ID
                           AND A.MEASURE IN ('MKT_FCST')
                           AND A.SEQ = V_ALLOC_I;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = NVL(RTF_QTY, 0) + V_ALLOC_RTF
                         WHERE SCM_SITE_ID  = V_SCM_SITE_ID
                           AND PROJECT_CODE = V_PROJECT_CODE
                           AND ITEM_ID      = V_ITEM_ID
                           AND MEASURE IN ('MKT_FCST')
                           AND SEQ = V_ALLOC_I;

                        V_ALLOC_SUM_RTF := V_ALLOC_SUM_RTF + V_ALLOC_RTF;
                        V_ALLOC_I       := V_ALLOC_I + 1;
                    END LOOP;

                END IF;

                SUB_I := SUB_I + 1;
            END LOOP;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240926-001366] SCP RTF 우선 : DM_PLN_MKT_FCST 에 이미 RTF 계열 있는 키는 GT 에서 제거 */
        /* ( SSP RTF 와 SCP RTF 가 중복되는 경우 SCP RTF 로 보여지도록 겹치는 SSP RTF 는 무시 ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM GT_PRDM_END_RTF_RAW R
         WHERE EXISTS ( SELECT 1
                          FROM DM_PLN_MKT_FCST M
                         WHERE M.DIVISION_ID   = R.DIVISION_ID
                           AND M.PROJECT_CODE  = R.PROJECT_CODE
                           AND M.SCM_SITE_ID   = R.SCM_SITE_ID
                           AND M.ITEM_ID       = R.ITEM_ID
                           AND M.DOM_EXP       = R.DOM_EXP
                           AND M.FCST_TYPE     = R.FCST_TYPE
                           AND M.INCOTERMS     = R.INCOTERMS
                           AND M.PLANT_SITE_ID = R.PLANT_SITE_ID
                           AND M.YYYYMMDD      = R.YYYYMMDD
                           AND M.MEASURE IN ('RTF', 'RTF_SCP', 'RTF_SYS_RP', 'RTF_PR') );

        /* --------------------------------------------------------------------------------------- */
        /* 계산된 RTF / 소형 동기화 INSERT ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            /* 계산된 RTF INSERT */
            INSERT INTO DM_PLN_MKT_FCST
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1  /* [PJ2025-50017] RTF_PR 신규 추가 */
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

            /* [PJ2025-50017] 소형 매출계획 동기화 : 계산된 RTF INSERT ( END_CUSTOMER : 40 만 PROJECT_CODE, 그외 NOT NULL 공백 ) */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
                ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, A.PLANT_SITE_ID, '-', A.YYYYMMDD  /* CELL_PROD_SITE_ID '-' : AS 모델은 SCP 무관 RTF */
                 , SUM(A.QTY)
                 , V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', A.AS_PLANT
              FROM GT_PRDM_END_RTF_RAW A
              JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                     UNION ALL SELECT 'RTF_SCP' FROM DUAL
                     UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                     UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
             WHERE A.MEASURE = 'RTF'
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                 , A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD, B.MEASURE, A.AS_PLANT;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에 SHIPMENT_PLAN 생성 ( 82, 40 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID IN ('82', '40') THEN

            INSERT INTO DM_PLN_MKT_FCST
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', '', '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

            /* [PJ2025-50017] 소형 매출계획 동기화 : AS SITE( PLANT )에 SHIPMENT_PLAN 생성 */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
                ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
                , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
            SELECT A.DIVISION_ID, A.PROJECT_CODE
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
                 , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
                 -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                 , A.AS_SITE, A.ITEM_ID, MAX(A.DOM_EXP)
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END), '-', A.SHIP_YYYYMMDD
                 , MAX(A.FCST_TYPE), MAX(A.INCOTERMS), 'AS_SHIP_PLAN', MAX(CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END), '-', A.SHIP_YYYYMMDD
                 -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                 , SUM(A.QTY), V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
                 , '', NULL, '', '', ''
                 , '', '', '', '', ''
              FROM GT_PRDM_SSP A
             WHERE A.SHIP_YYYYMMDD >= V_START_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.AS_SITE, A.ITEM_ID, A.SHIP_YYYYMMDD;

        END IF;

        /* --------------------------------------------------------------------------------------- */
        /* AS SITE( PLANT )에서 SHIPMENT_PLAN 이용 AS_INV 재계산 -> GT_PRDM_AS_INV */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD, A.PLANT_SITE_ID, A.QTY
          FROM DM_PLN_MKT_FCST A
          JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.OPERATION_GROUP = 'W' AND B.SITE_TYPE = 'SALES'
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE IN ('AS_In_Plan', 'AS_SHIP_PLAN')
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        /* 기존 AS_INV 메저 보유행에 SITE_SEQ=1 */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  FROM DM_PLN_MKT_FCST
                 WHERE YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND MEASURE = 'AS_INV'
                   AND DIVISION_ID = P_DIVISION_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* 한 SITE,ITEM 에 SITE_SEQ=1 여러개면 조정( 2번째부터 NULL ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT KEY_VAL
                  FROM ( SELECT KEY_VAL
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL ) AS SUB_SEQ
                           FROM GT_PRDM_AS_INV
                          WHERE SITE_SEQ = 1 )
                 WHERE SUB_SEQ <> 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = NULL;

        /* SITE_SEQ 없는 SITE 조정 ( KEY_VAL DESC 최종 1행 ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT C.KEY_VAL
                  FROM ( SELECT KEY_VAL, DIVISION_ID, SCM_SITE_ID, ITEM_ID
                              , ROW_NUMBER() OVER ( PARTITION BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ORDER BY KEY_VAL DESC ) AS ROW_NUM
                           FROM GT_PRDM_AS_INV ) C
                  JOIN ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS SITE_SEQ
                           FROM GT_PRDM_AS_INV
                          GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) D
                    ON C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID
                 WHERE D.SITE_SEQ IS NULL
                   AND C.ROW_NUM = 1 ) B
        ON ( A.KEY_VAL = B.KEY_VAL )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1;

        /* --------------------------------------------------------------------------------------- */
        /* [E20240214-000835] 기초재고 추가 ( 81 / 그 외 분기 ) */
        /* --------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID = '81' THEN

            /* [E20250120-000036] 81 : AS_STORAGE_YN='Y' 재고만, MKT FCST 기준 데이터로 생성 */
            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SEQ
                 , A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'  /* AS_STORAGE_YN */
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일(당주 월요일 -1). DATE 컬럼 = DATE 로 비교(원본 CONVERT(NVARCHAR(10),..,120)). */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] NERP 운송중 VMI 재고 제외분 -> INTRANSIT Inventory 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                         ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2  /* STORAGE_ID */
                        AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y' AND B.SEGMENT5 = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SCP RESULT_DATE = 일요일. RESULT_DATE 문자열 컬럼 = YYYYMMDD 비교. */
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              /* [E20250120-000036] 81, 81_JV 는 AS_IN_PLAN 부재해도 생성 : MKT FCST 기준 + AS_INV 기준 UNION */
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.FROM_SITE AS SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ
                       FROM ( SELECT DIVISION_ID, FROM_SITE, ITEM_ID, MIN(SEQ) AS MIN_SEQ
                                FROM GT_PRDM_END_RTF_RAW
                               GROUP BY DIVISION_ID, FROM_SITE, ITEM_ID ) A
                       JOIN GT_PRDM_END_RTF_RAW B ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_SITE = B.FROM_SITE AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SEQ
                      UNION ALL
                      SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SEQ, A.AS_PLANT;

        ELSE

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, AS_PLANT )
            SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, 'AS_Inv'
                 , TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD'), B.PLANT_SITE_ID
                 , SUM(A.QTY)
                 , B.SITE_SEQ, A.AS_PLANT
              FROM ( SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(SCM_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SSP_DNM_STOCK_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.STORAGE_ID AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      /* [E20260402-001736] SSP CUTOFF_DATE = 일요일. DATE 컬럼 = DATE 로 비교. */
                      WHERE A.CUTOFF_DATE = TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1
                        AND A.STOCK_TYPE = 'INVENTORY'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2
                     UNION ALL
                     /* [E20250113-000270] 운송중(INTRANSIT) 재고 적용 */
                     SELECT A.DIVISION_ID, C.SEGMENT1 AS AS_SITE, A.ITEM_ID, SUM(DELIVERY_QTY) AS QTY, C.SEGMENT2 AS AS_PLANT
                       FROM SCM_DNM_INTRANSIT_C A
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON B.SEGMENT1 = A.DIVISION_ID AND B.SEGMENT3 = A.PLANT_ID AND B.SEGMENT4 = A.ATTRIBUTE2 AND B.LOOKUP_TYPE = 'SSP_AS_DIV_SLOC' AND B.VALID_YN = 'Y'
                       JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.SEGMENT1 = C.SEGMENT3 AND B.SEGMENT2 = C.SEGMENT2 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                      WHERE A.RESULT_DATE = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                        AND A.RESULT_TYPE = 'I'
                      GROUP BY A.DIVISION_ID, C.SEGMENT1, A.ITEM_ID, C.SEGMENT2 ) A
              JOIN ( SELECT DISTINCT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ
                       FROM ( SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, MIN(SITE_SEQ) AS MIN_SEQ
                                FROM GT_PRDM_AS_INV
                               GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID ) A
                       JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.MIN_SEQ = B.SITE_SEQ
                    ) B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_SITE = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
             GROUP BY B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.PLANT_SITE_ID, B.SITE_SEQ, A.AS_PLANT;

        END IF;

        /* AS_PLANT 일괄 업데이트 ( ORA-30926 회피 위해 SEGMENT3/SEGMENT1 GROUP BY 로 유일화 ) */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT SEGMENT3, SEGMENT1, MAX(SEGMENT2) AS SEGMENT2
                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                 WHERE LOOKUP_TYPE = 'AS_SITE_PLANT' AND VALID_YN = 'Y'
                 GROUP BY SEGMENT3, SEGMENT1 ) B
        ON ( A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 )
        WHEN MATCHED THEN UPDATE SET A.AS_PLANT = B.SEGMENT2;

        /* --------------------------------------------------------------------------------------- */
        /* AS PLANT 기준 모델 적재 -> GT_PRDM_AS_LOOP ( SEQ 1부터 연속채번, 원본 IDENTITY(1,1) ) */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      /* [E20250120-000036] 81 사업부는 SHIP_FROZEN 미적용 */
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + B.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , C.SEGMENT2 AS FROM_PLANT
                   FROM GT_PRDM_AS_INV A
                   JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.AS_PLANT = B.SCM_SITE_ID
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                  WHERE A.SITE_SEQ = 1 ) X;

        INSERT INTO GT_PRDM_AS_LOOP ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, CALC_START_DATE, FROM_PLANT, SEQ )
        SELECT X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID, X.CALC_START_DATE, X.FROM_PLANT
             , ( SELECT NVL(MAX(SEQ), 0) FROM GT_PRDM_AS_LOOP ) + ROW_NUMBER() OVER ( ORDER BY X.DIVISION_ID, X.SCM_SITE_ID, X.ITEM_ID )
          FROM ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                      , CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END AS CALC_START_DATE
                      , B.SEGMENT2 AS FROM_PLANT
                   FROM DM_PLN_MKT_FCST A
                   JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1 AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y'
                   JOIN SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND B.SEGMENT2 = C.SCM_SITE_ID
                   LEFT OUTER JOIN GT_PRDM_AS_LOOP E ON A.DIVISION_ID = E.DIVISION_ID AND A.SCM_SITE_ID = E.SCM_SITE_ID AND A.ITEM_ID = E.ITEM_ID
                   JOIN ( SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, C.SEGMENT2
                            FROM GT_PRDM_AS_INV A
                            JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON A.DIVISION_ID = C.SEGMENT3 AND A.SCM_SITE_ID = C.SEGMENT1 AND C.LOOKUP_TYPE = 'AS_SITE_PLANT' AND C.VALID_YN = 'Y'
                         ) F ON A.DIVISION_ID = F.DIVISION_ID AND A.SCM_SITE_ID = F.SCM_SITE_ID AND A.ITEM_ID = F.ITEM_ID
                  WHERE A.DIVISION_ID = P_DIVISION_ID
                    AND A.YYYYMMDD >= V_SHIP_START_YYYYMMDD
                    AND E.DIVISION_ID IS NULL ) X;

        /* --------------------------------------------------------------------------------------- */
        /* #T_AS_INV 일자별 재고 생성 루프 ( 첫 AS_LOOP WHILE ) */
        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID
              INTO V_DIVISION_ID, V_SCM_SITE_ID, V_ITEM_ID
              FROM GT_PRDM_AS_LOOP
             WHERE SEQ = I;


            BEGIN
                SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                  INTO V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, V_PLANT_SITE_ID
                  FROM ( SELECT PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                           FROM GT_PRDM_AS_INV
                          WHERE DIVISION_ID = V_DIVISION_ID
                            AND SCM_SITE_ID = V_SCM_SITE_ID
                            AND ITEM_ID = V_ITEM_ID
                            AND SITE_SEQ = 1 )
                 WHERE ROWNUM = 1;
            EXCEPTION
                WHEN NO_DATA_FOUND THEN NULL;
            END;

            INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
            SELECT DISTINCT V_DIVISION_ID, V_PROJECT_CODE, V_SCM_SITE_ID, V_ITEM_ID, V_DOM_EXP, V_FCST_TYPE, V_INCOTERMS, 'AS_Inv', A.BASIS_YYYYMMDD, V_PLANT_SITE_ID
                 , SUM( CASE WHEN B.MEASURE IN ('AS_In_Plan', 'AS_INV') THEN NVL(B.QTY, 0) ELSE NVL(-B.QTY, 0) END ) OVER ( ORDER BY A.BASIS_YYYYMMDD )
                 , B.SITE_SEQ
              FROM SCM_SYS_CALENDAR_M A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.BASIS_YYYYMMDD = B.YYYYMMDD
                                              AND B.DIVISION_ID = V_DIVISION_ID
                                              AND B.SCM_SITE_ID = V_SCM_SITE_ID
                                              AND B.ITEM_ID = V_ITEM_ID
             WHERE A.BASIS_YYYYMMDD BETWEEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
                                        AND TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + 7*16, 'YYYYMMDD');

            /* 기초재고 일자 중복행 삭제 ( 나중에 넣은 데이터 ) */
            DELETE FROM GT_PRDM_AS_INV A
             WHERE A.YYYYMMDD = TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') - 1, 'YYYYMMDD')
               AND A.AS_PLANT IS NULL;

            I := I + 1;
        END LOOP;

        /* --------------------------------------------------------------------------------------- */
        /* [E20250909-000795][E20240226-000021] 54주 보완 : SITE_SEQ 없는 AS_Inv 최초일자에 SITE_SEQ=1 */
        /* --------------------------------------------------------------------------------------- */
        MERGE INTO GT_PRDM_AS_INV A
        USING ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MIN(YYYYMMDD) AS YYYYMMDD
                  FROM GT_PRDM_AS_INV C
                 WHERE SITE_SEQ IS NULL
                   AND MEASURE = 'AS_Inv'
                   AND NOT EXISTS ( SELECT 1 FROM GT_PRDM_AS_INV D
                                     WHERE D.MEASURE = 'AS_Inv' AND D.SITE_SEQ = 1
                                       AND C.DIVISION_ID = D.DIVISION_ID AND C.SCM_SITE_ID = D.SCM_SITE_ID AND C.ITEM_ID = D.ITEM_ID )
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID ) B
        ON (    A.DIVISION_ID   = B.DIVISION_ID
            AND A.PROJECT_CODE  = B.PROJECT_CODE
            AND A.SCM_SITE_ID   = B.SCM_SITE_ID
            AND A.ITEM_ID       = B.ITEM_ID
            AND A.DOM_EXP       = B.DOM_EXP
            AND A.FCST_TYPE     = B.FCST_TYPE
            AND A.INCOTERMS     = B.INCOTERMS
            AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
            AND A.YYYYMMDD      = B.YYYYMMDD )
        WHEN MATCHED THEN UPDATE SET A.SITE_SEQ = 1 WHERE A.MEASURE = 'AS_Inv';

        /* --------------------------------------------------------------------------------------- */
        /* 받는 Site 들에 RTF 생성 ( SSP 확정구간 이후 ) : MKT FCST 취합 -> GT_PRDM_RTF */
        /* --------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM_RTF ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_PLANT, ETD_DATE, SITE_SEQ )
        SELECT B.DIVISION_ID, B.PROJECT_CODE, B.SCM_SITE_ID, B.ITEM_ID, B.DOM_EXP, B.FCST_TYPE, B.INCOTERMS, B.MEASURE, B.YYYYMMDD, B.PLANT_SITE_ID, B.QTY
             , A.FROM_SITE, TO_CHAR(TO_DATE(B.YYYYMMDD, 'YYYYMMDD') - A.LT_TOTAL, 'YYYYMMDD')
             , ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, A.FROM_SITE, B.ITEM_ID, B.YYYYMMDD ORDER BY B.SCM_SITE_ID )
          FROM ( SELECT A.SEGMENT2 AS FROM_SITE, B.TO_SITE, B.LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY B.DIVISION_ID, B.FROM_SITE, B.TO_SITE ORDER BY B.PRIORITY ) AS BOD_SEQ
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL A
                   JOIN SCP_MST_BOD_N_V B ON A.SEGMENT2 = B.FROM_SITE AND B.DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN B.FROM_YYYYMMDD AND B.TO_YYYYMMDD
                   JOIN SCM_MST_SITE C ON B.TO_SITE = C.SCM_SITE_ID AND C.SITE_TYPE = 'SALES' AND C.VALID_YN = 'Y' AND C.DIVISION_ID = P_DIVISION_ID
                  WHERE A.LOOKUP_TYPE = 'AS_SITE_PLANT' AND A.SEGMENT3 = P_DIVISION_ID AND A.VALID_YN = 'Y' ) A
          JOIN DM_PLN_MKT_FCST B ON A.TO_SITE = B.SCM_SITE_ID AND B.MEASURE = 'MKT_FCST' AND B.YYYYMMDD >= V_START_YYYYMMDD
                                AND A.FROM_SITE = B.ATTRIBUTE10 AND B.DIVISION_ID = P_DIVISION_ID
          JOIN SCM_MST_SITE C ON A.FROM_SITE = C.SCM_SITE_ID AND C.DIVISION_ID = P_DIVISION_ID
         WHERE A.BOD_SEQ = 1
           /* [E20250120-000036] 81 사업부는 SHIP_FROZEN 미적용 */
           AND B.YYYYMMDD > CASE WHEN P_DIVISION_ID LIKE '81%' THEN V_SHIP_START_YYYYMMDD ELSE TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + C.SHIP_FROZEN, 'YYYYMMDD') END
           AND B.QTY <> 0;

        UPDATE GT_PRDM_RTF A
           SET A.ALLOC_SCD_RTF = CASE WHEN A.YYYYMMDD > NVL( ( SELECT MAX(YYYYMMDD)
                                                                 FROM GT_PRDM_END_RTF_RAW E
                                                                WHERE E.MEASURE IN ('RTF', 'SSP_RTF')
                                                                  AND E.DIVISION_ID = A.DIVISION_ID
                                                                  AND E.SCM_SITE_ID = A.SCM_SITE_ID ), '19000101' )
                                      THEN 'Y' ELSE 'N' END;


        /* MAX[ 출발지의 확정구간 + 도착지 BOD LT 적용일자, 도착지의 SSP_RTF ] */
        INSERT INTO GT_PRDM_RTF_SITE ( FROM_SITE, SCM_SITE_ID, MAX_YMD )
        SELECT A.FROM_SITE, A.SCM_SITE_ID
             , CASE WHEN NVL(D.MAX_YMD, '19000101') > CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                                                           ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
                    THEN D.MAX_YMD
                    ELSE CASE WHEN P_DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(C.LT_TOTAL, 0), 'YYYYMMDD')
                              ELSE TO_CHAR(TO_DATE(V_START_YYYYMMDD, 'YYYYMMDD') + NVL(B.SHIP_FROZEN, 0) + NVL(C.LT_TOTAL, 0), 'YYYYMMDD') END
               END
          FROM ( SELECT DISTINCT FROM_SITE, SCM_SITE_ID, AS_PLANT FROM GT_PRDM_END_RTF_RAW ) A
          JOIN SCM_MST_SITE B ON A.AS_PLANT = B.SCM_SITE_ID AND B.DIVISION_ID = P_DIVISION_ID
          JOIN ( SELECT FROM_SITE, TO_SITE, LT_TOTAL, ROW_NUMBER() OVER ( PARTITION BY FROM_SITE, TO_SITE, INCOTERMS ORDER BY PRIORITY ) AS PRT
                   FROM SCP_MST_BOD_N_V
                  WHERE DIVISION_ID = P_DIVISION_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_YYYYMMDD AND TO_YYYYMMDD ) C
            ON A.AS_PLANT = C.FROM_SITE AND A.SCM_SITE_ID = C.TO_SITE AND C.PRT = 1
          LEFT OUTER JOIN ( SELECT FROM_SITE, SCM_SITE_ID, MAX(YYYYMMDD) AS MAX_YMD
                              FROM GT_PRDM_END_RTF_RAW
                             WHERE MEASURE = 'RTF'
                             GROUP BY FROM_SITE, SCM_SITE_ID ) D
            ON A.FROM_SITE = D.FROM_SITE AND A.SCM_SITE_ID = D.SCM_SITE_ID;

        MERGE INTO GT_PRDM_END_RTF_RAW A
        USING ( SELECT FROM_SITE, SCM_SITE_ID, MAX(MAX_YMD) AS MAX_YMD
                  FROM GT_PRDM_RTF_SITE
                 GROUP BY FROM_SITE, SCM_SITE_ID ) B
        ON ( A.SCM_SITE_ID = B.SCM_SITE_ID AND A.FROM_SITE = B.FROM_SITE )
        WHEN MATCHED THEN UPDATE SET A.SCD_ALLOC_START_DATE = B.MAX_YMD;

        UPDATE GT_PRDM_END_RTF_RAW
           SET LT_YYYYMMDD = TO_CHAR(TO_DATE(YYYYMMDD, 'YYYYMMDD') - NVL(LT_DAYS, 0), 'YYYYMMDD')
         WHERE MEASURE = 'MKT_FCST';

        /* --------------------------------------------------------------------------------------- */


        /* --------------------------------------------------------------------------------------- */
        SELECT 1, COUNT(*) INTO I, CNT FROM GT_PRDM_AS_LOOP;

        WHILE ( I <= CNT ) LOOP

            SELECT A.DIVISION_ID, A.FROM_PLANT, A.SCM_SITE_ID, A.ITEM_ID, TRUNC(NVL(B.QTY, 0)), A.CALC_START_DATE
                 , 0
                 , TO_CHAR(TO_DATE(V_SHIP_START_YYYYMMDD, 'YYYYMMDD') + 7*82, 'YYYYMMDD')  /* [E20250909-000795] 54 -> 82 */
                 , 0, 0
              INTO V_DIVISION_ID, V_FROM_PLANT, V_FROM_SITE, V_ITEM_ID, V_INV_QTY, V_DATE
                 , V_SUM_REQ_QTY
                 , V_MAX_DATE
                 , V_INV_ADJ_QTY, V_SUM_REQ_QTY
              FROM GT_PRDM_AS_LOOP A
              LEFT OUTER JOIN GT_PRDM_AS_INV B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                   AND B.YYYYMMDD = TO_CHAR(TO_DATE(A.CALC_START_DATE, 'YYYYMMDD') - 1, 'YYYYMMDD')
                   AND B.MEASURE = 'AS_INV'
             WHERE A.SEQ = I;

            /* 비축용 사이트 기준 일자별 나눠주기 */
            WHILE ( V_DATE <= V_MAX_DATE ) LOOP

                /* 재고는 V_DATE 전날 재고이므로 당일 입고 감안 */
                SELECT V_INV_QTY + NVL(SUM(QTY), 0)
                  INTO V_INV_QTY
                  FROM GT_PRDM_AS_INV
                 WHERE MEASURE = 'AS_In_Plan'
                   AND DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE;
                V_INV_QTY := TRUNC(V_INV_QTY);

                SELECT NVL(SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), 0)
                  INTO V_SUM_REQ_QTY
                  FROM GT_PRDM_END_RTF_RAW
                 WHERE AS_PLANT = V_FROM_PLANT
                   AND ITEM_ID = V_ITEM_ID
                   AND DIVISION_ID = V_DIVISION_ID
                   AND LT_YYYYMMDD <= V_DATE
                   AND MEASURE = 'MKT_FCST'
                   AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                /* 재고보다 요청수량이 적으면 요청만큼 생성 */
                IF ( V_SUM_REQ_QTY <= V_INV_QTY ) THEN

                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), A.PLANT_SITE_ID, SUM(NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)), NULL, A.AS_PLANT, 'Y'
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0)
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                         , A.PLANT_SITE_ID, A.AS_PLANT, TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD');

                    UPDATE GT_PRDM_END_RTF_RAW A
                       SET RTF_QTY = MF_QTY
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    V_INV_QTY := TRUNC(V_INV_QTY - V_SUM_REQ_QTY);

                ELSE  /* 재고가 적으면 배분 */

                    DELETE FROM GT_PRDM_RCV;

                    INSERT INTO GT_PRDM_RCV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, FROM_SITE, ETD_DATE, SITE_SEQ, RTF_RAW_KEY_VAL )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
                         , TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + NVL(LT_DAYS, 0), 'YYYYMMDD'), PLANT_SITE_ID
                         , NVL(MF_QTY, 0) - NVL(RTF_QTY, 0)
                         , AS_PLANT, V_DATE
                         , ROW_NUMBER() OVER ( ORDER BY A.YYYYMMDD, A.SCM_SITE_ID )
                         , KEY_VAL
                      FROM GT_PRDM_END_RTF_RAW A
                     WHERE A.AS_PLANT = V_FROM_PLANT
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.DIVISION_ID = V_DIVISION_ID
                       AND LT_YYYYMMDD <= V_DATE
                       AND MEASURE = 'MKT_FCST'
                       AND NVL(MF_QTY, 0) > NVL(RTF_QTY, 0);

                    SELECT 1, COUNT(*) INTO I_RCV, CNT_RCV FROM GT_PRDM_RCV;

                    WHILE ( I_RCV <= CNT_RCV AND V_INV_QTY > 0 ) LOOP

                        SELECT QTY, RTF_RAW_KEY_VAL INTO V_REQ_QTY, V_KEY_VAL
                          FROM GT_PRDM_RCV
                         WHERE SITE_SEQ = I_RCV;

                        /* 할당 가능한 수량이면 할당하고 다음 SITE 로 */
                        INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ, FROM_SITE, ADD_YN )
                        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SCP'
                             , A.YYYYMMDD, A.PLANT_SITE_ID
                             , SUM( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END )
                             , A.SITE_SEQ, A.FROM_SITE, 'Y'
                          FROM GT_PRDM_RCV A
                         WHERE SITE_SEQ = I_RCV
                         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                             , A.YYYYMMDD, A.PLANT_SITE_ID, A.SITE_SEQ, A.FROM_SITE;

                        UPDATE GT_PRDM_END_RTF_RAW
                           SET RTF_QTY = RTF_QTY + CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_REQ_QTY ELSE V_INV_QTY END
                         WHERE KEY_VAL = V_KEY_VAL;

                        V_INV_QTY := TRUNC( CASE WHEN V_REQ_QTY <= V_INV_QTY THEN V_INV_QTY - V_REQ_QTY ELSE 0 END );

                        I_RCV := I_RCV + 1;
                    END LOOP;

                END IF;

                /* Inv Insert / Update */
                UPDATE GT_PRDM_AS_INV
                   SET QTY = V_INV_QTY
                 WHERE DIVISION_ID = V_DIVISION_ID
                   AND SCM_SITE_ID = V_FROM_SITE
                   AND ITEM_ID = V_ITEM_ID
                   AND YYYYMMDD = V_DATE
                   AND MEASURE = 'AS_Inv';

                IF SQL%ROWCOUNT = 0 THEN
                    INSERT INTO GT_PRDM_AS_INV ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD, PLANT_SITE_ID, QTY, SITE_SEQ )
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'AS_Inv', V_DATE, A.PLANT_SITE_ID
                         , V_INV_QTY, 1
                      FROM GT_PRDM_AS_INV A
                     WHERE A.DIVISION_ID = V_DIVISION_ID
                       AND A.SCM_SITE_ID = V_FROM_SITE
                       AND A.ITEM_ID = V_ITEM_ID
                       AND A.MEASURE = 'AS_Inv'
                       AND A.SITE_SEQ = 1
                       AND ROWNUM = 1;
                END IF;

                V_DATE := TO_CHAR(TO_DATE(V_DATE, 'YYYYMMDD') + 1, 'YYYYMMDD');

            END LOOP;

            I := I + 1;
        END LOOP;


        DELETE FROM GT_PRDM_AS_INV WHERE YYYYMMDD < V_START_YYYYMMDD;

        /* --------------------------------------------------------------------------------------- */
        /* 결과 INSERT : DM_PLN_MKT_FCST ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_MKT_FCST A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', '', '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID, A.YYYYMMDD
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID, A.YYYYMMDD
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, '' AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_MKT_FCST B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND A.PROJECT_CODE = B.PROJECT_CODE
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND A.DOM_EXP = B.DOM_EXP
           AND A.FCST_TYPE = B.FCST_TYPE
           AND A.INCOTERMS = B.INCOTERMS
           AND A.MEASURE = B.MEASURE
           AND A.YYYYMMDD = B.YYYYMMDD
           AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
         WHERE B.DIVISION_ID IS NULL;

        /* --------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] 결과 INSERT : DM_PLN_CFM_MKT_DEMAND_PLAN ( AS_Inv + 8주 이후 RTF ) */
        /* --------------------------------------------------------------------------------------- */
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE EXISTS ( SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                         WHERE A.DIVISION_ID = B.SEGMENT3 AND A.SCM_SITE_ID = B.SEGMENT1
                           AND B.LOOKUP_TYPE = 'AS_SITE_PLANT' AND B.VALID_YN = 'Y' )
           AND A.DIVISION_ID = P_DIVISION_ID
           AND A.MEASURE = 'AS_Inv'
           AND A.YYYYMMDD >= V_START_YYYYMMDD;

        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
            ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END
             -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, '-', A.YYYYMMDD
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, '-', A.YYYYMMDD
             -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
             , A.QTY, V_CREATED_BY, SYSDATE, V_CREATED_BY, SYSDATE
             , '', NULL, '', '', ''
             , '', '', '', '', ''
          FROM GT_PRDM_AS_INV A
         WHERE MEASURE = 'AS_Inv';


        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
            ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP
            , FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
            , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
            , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
            , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
             , A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.YYYYMMDD
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
             , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
          FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE
                      -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (START)
--                      , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                      , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE '/' END AS END_CUSTOMER
                      -- 2026.09.18 AJS END_CUSTOMER 빈값 채움값 '-' 로 통일 (END)
                      , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END AS PLANT_SITE_ID
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END AS PLANT_SITE_ID
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
                      , '-' AS CELL_PROD_SITE_ID, A.YYYYMMDD
                      , SUM(A.QTY) AS QTY, V_CREATED_BY AS CREATED_BY, SYSDATE AS CREATION_DATE, V_CREATED_BY AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , '' AS ATTRIBUTE1, NULL AS ATTRIBUTE2, '' AS ATTRIBUTE3, '' AS ATTRIBUTE4, '' AS ATTRIBUTE5
                      , '' AS ATTRIBUTE6, '' AS ATTRIBUTE7, '' AS ATTRIBUTE8, '' AS ATTRIBUTE9, A.FROM_SITE AS ATTRIBUTE10
                   FROM GT_PRDM_AS_INV A
                   JOIN ( SELECT 'RTF' AS MEASURE FROM DUAL
                          UNION ALL SELECT 'RTF_SCP' FROM DUAL
                          UNION ALL SELECT 'RTF_SYS_RP' FROM DUAL
                          UNION ALL SELECT 'RTF_PR' FROM DUAL ) B ON 1 = 1
                  WHERE A.ADD_YN = 'Y' AND A.MEASURE = 'RTF_SCP'
                  GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (START)
--                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE ' ' END, A.YYYYMMDD, A.FROM_SITE ) A
                      , A.FCST_TYPE, A.INCOTERMS, B.MEASURE, CASE WHEN A.DIVISION_ID LIKE '81%' THEN A.PLANT_SITE_ID ELSE '/' END, A.YYYYMMDD, A.FROM_SITE ) A
                      -- 2026.09.18 AJS PLANT_SITE_ID 빈값 채움값 '-' 로 통일 (END)
          LEFT OUTER JOIN DM_PLN_CFM_MKT_DEMAND_PLAN B
            ON A.DIVISION_ID = B.DIVISION_ID
           AND A.PROJECT_CODE = ( CASE WHEN B.DIVISION_ID = '40' THEN B.END_CUSTOMER ELSE B.PROJECT_CODE END )
           AND A.SCM_SITE_ID = B.SCM_SITE_ID
           AND A.ITEM_ID = B.ITEM_ID
           AND A.DOM_EXP = B.DOM_EXP
           AND A.FCST_TYPE = B.FCST_TYPE
           AND A.INCOTERMS = B.INCOTERMS
           AND A.MEASURE = B.MEASURE
           AND A.YYYYMMDD = B.YYYYMMDD
           AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
         WHERE B.DIVISION_ID IS NULL;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := '@P_DIVISION_ID: ' || P_DIVISION_ID || ' / ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                , V_DESCRIPTION, TO_CHAR(SQLCODE), SUBSTR(SQLERRM, 1, 1000), SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 1000));
            RAISE;
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END OF PROCEDURE ##########';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_DM_DNM_CREATE_WS_RTF;
/
SHOW ERRORS PROCEDURE PR_DM_DNM_CREATE_WS_RTF
-- ##### END PROCEDURE PR_DM_DNM_CREATE_WS_RTF

-- ##### START PROCEDURE PR_DM_DNM_EDI_CALLOFF_DATA
CREATE OR REPLACE PROCEDURE           "PR_DM_DNM_EDI_CALLOFF_DATA" 
/*=====================================================================================================================================================
 * Program ID  : PR_DM_DNM_EDI_CALLOFF_DATA
 * Description  : BMW / AUDI등 EDI 정보 ERP I/F -> GSCM EDI_CALLOFF 신규 INSERT
 *                    XIF_ERP_EDI_CALLOFF_HEAD_R    -> DM_DNM_EDI_CALLOFF_HEAD
 *                    XIF_ERP_EDI_CALLOFF_PARTNER_R -> DM_DNM_EDI_CALLOFF_PARTNER
 *                    XIF_ERP_EDI_CALLOFF_ITEM_R    -> DM_DNM_EDI_CALLOFF_ITEM
 * Program History
 *=====================================================================================================================================================
 *   Date       In Charge      Description
 *=====================================================================================================================================================
 * 배포시 주의사항 : 개발기 -> LGCE_INF , 운영기 -> LGCE_INF
 *=====================================================================================================================================================
 * 2023.05.03   kdmcc14     EDI과제
 * 2023.12.13   chano0612   [PARTNER_TYPE 다중으로 인한 오류 처리]
 * 2024.06.27   JSSBAE      [E20240610-000320]_SCM DM EDI(Cust FCST) 관련 문의사항 (예외로직적용: 앞뒤 공백값, NULL값 공백으로 치환해서 비교 처리)
 * 2024.08.30   JSSBAE      [E20240807-000723]_GSCM EDI내 고객사 파트넘버 문의
 * 2024.12.26   KANG.H.J    [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 * 2025.06.19   김준규        IT20250117A NERP 오펀차수별 Mapping Code적용
 * 2025.09.16 JSSBAE        [E20250910-000974]_NN Mapping Master 컬럼 추가 요청
 * 2026-03-23   김준규        [PJ20264226] NextSCM Pilot 설계 및 개발
 * 2026.07.06   ZIONEX   [PJ202650304] NextSCM Migration
 *===================================================================================================================================================*/
IS

    V_BATCH_USER          VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME        VARCHAR2(200 CHAR) := $$PLSQL_UNIT;
    V_BATCH_CHK_MSG       VARCHAR2(150 CHAR) := NULL;
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           INTEGER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;
    V_IFSEQNO             VARCHAR2(30 CHAR);
    V_IFSEQNO_X           VARCHAR2(30 CHAR);
    V_FETCH_STATUS        INTEGER := 0;
    V_NEW_INSERT_COUNT    INTEGER := 0;
    V_IN_PARA_DATA        CLOB;
    V_STEP                VARCHAR2(4000 CHAR) := NULL;
    V_TMP_COUNT           INTEGER := 0;
    V_DIVISION_ID         VARCHAR2(30 CHAR);
    V_DIVISION_ID_UC      VARCHAR2(30 CHAR);
    V_NERP_ROLLIN_STAGE   VARCHAR2(30 CHAR);
    V_NERP_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_I                   INTEGER := 1;
    V_CNT                 INTEGER := 0;
    V_CNT_1               INTEGER := 0;
    V_CNT_2               INTEGER := 0;
    V_CNT_3               INTEGER := 0;
BEGIN

    IF UTL_CALL_STACK.SUBPROGRAM(1).COUNT > 1 THEN
        V_PROGRAM_NAME := $$PLSQL_UNIT || '.' || UTL_CALL_STACK.SUBPROGRAM(1) (2);
    END IF;

    V_IN_PARA_DATA := NULL;

    /* LOG 용 변수 설정 */

    V_DIVISION_ID    := '81';
    V_DIVISION_ID_UC := '81_UC';

    /* --------------------------------------------------------------------- */
    /* 2025.06.19 김준규 IT20250117A NERP 오펀차수별 Mapping Code적용 Start */
    /* --------------------------------------------------------------------- */
    SELECT LMD.SEGMENT1, LMD.SEGMENT2
      INTO V_NERP_ROLLIN_STAGE, V_NERP_START_YYYYMMDD
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL LMD
      JOIN SCM_ADM_LOOKUP_MASTER ALM
        ON ALM.LOOKUP_TYPE = LMD.LOOKUP_TYPE
       AND ALM.LOOKUP_TYPE = 'NERP_ROLLIN_STAGE'
     WHERE ALM.VALID_YN = 'Y'
       AND LMD.VALID_YN = 'Y'
     FETCH FIRST 1 ROWS ONLY;
    /* --------------------------------------------------------------------- */
    /* 2025.06.19 김준규 IT20250117A NERP 오펀차수별 Mapping Code적용 End */
    /* --------------------------------------------------------------------- */
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := NULL;
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* ◇◇◇◇◇ BEGIN TRY (Oracle: EXCEPTION 블록으로 대체) ◇◇◇◇◇ */

    /* IF TABLE의 신규 수신받은 건이 있을때만 처리 */
    SELECT (SELECT COUNT(1) FROM XIF_ERP_EDI_CALLOFF_HEAD_R_SN WHERE NVL(TRANSACTION_FLAG, 'N') IN ('P', 'N')) +
           (SELECT COUNT(1) FROM XIF_ERP_EDI_CALLOFF_ITEM_R_SN WHERE NVL(TRANSACTION_FLAG, 'N') IN ('P', 'N')) +
           (SELECT COUNT(1) FROM XIF_ERP_EDI_CALLOFF_PARTNER_R_SN WHERE NVL(TRANSACTION_FLAG, 'N') IN ('P', 'N'))
      INTO V_TMP_COUNT
      FROM DUAL;
    IF V_TMP_COUNT > 0 THEN

        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_ERP_EDI_CALLOFF_HEAD_R_SN
           SET TRANSACTION_FLAG = 'P'
         WHERE NVL(TRANSACTION_FLAG, 'N') = 'N'
           /* 2025.06.19 김준규 IT20250117A NERP 오펀차수별 Mapping Code적용 Start */
           /* OLD 코드는 반영이 되지 않게 처리 */
           AND NOT EXISTS (SELECT 1
                             FROM NERP_CONV_MASTER NCM
                            WHERE NCM.CODETYPE = 'COMPANY_ID'
                              AND NCM.OLD_VALUE1 = XIF_ERP_EDI_CALLOFF_HEAD_R_SN.COMPANY_ID
                              AND NCM.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE)
           /* 2025.06.19 김준규 IT20250117A NERP 오펀차수별 Mapping Code적용 End */
        ;

        DBMS_OUTPUT.PUT_LINE('CUR_EDI_CALL_OFF_HEAD start' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */

        /* CUR_EDI_CALL_OFF_HEAD CURSOR FOR */

        FOR REC_HEAD IN (SELECT IFSEQNO FROM XIF_ERP_EDI_CALLOFF_HEAD_R_SN WHERE TRANSACTION_FLAG = 'P' GROUP BY IFSEQNO ORDER BY IFSEQNO ASC) LOOP
            V_IFSEQNO := REC_HEAD.IFSEQNO;


            MERGE INTO DM_DNM_EDI_CALLOFF_HEAD A
            USING (
                   SELECT IFSEQNO
                        , SOLDTO_CODE
                        , COMPANY_ID
                        , MESSAGE_REFERENCE
                        , MESSAGE_TYPE
                        , DOC_IDENTIFINER
                        , EDI_INTERCHANGE_NO
                        , DOC_ISSUE_DATE
                        , RDD_TYPE
                        , COMPANY_NAME
                        , SOLDTO_NAME
                        , EDI_IF_SEQ
                        , TRANSACTION_FLAG
                        , CREATE_USER_ID
                        , CREATE_DATE
                        , CREATE_TIME
                        , UPDATE_USER_ID
                        , UPDATE_DATE
                        , UPDATE_TIME
                        , TRANSFER_CREATE_USER_ID
                        , TRANSFER_CREATE_DATE
                        , TRANSFER_CREATE_TIME
                        , TRANSFER_UPDATE_USER_ID
                        , TRANSFER_UPDATE_DATE
                        , TRANSFER_UPDATE_TIME
                        , DOC_STATUS
                        , (CASE
                               WHEN IFSEQNO LIKE '1%' THEN
                                'G'
                               ELSE
                                'D'
                           END || SENDER_CODE) SENDER_CODE
                        , SENDER_NAME
                        , CASE
                              WHEN REGEXP_LIKE(ATTRIBUTE1, '^\d+$') THEN
                               TO_NUMBER(ATTRIBUTE1)
                              ELSE
                               0
                          END AS TT_CNT
                        , CASE
                              WHEN REGEXP_LIKE(ATTRIBUTE2, '^\d+$') THEN
                               TO_NUMBER(ATTRIBUTE2)
                              ELSE
                               0
                          END AS SENDER_CNT
                     FROM XIF_ERP_EDI_CALLOFF_HEAD_R_SN
                    WHERE IFSEQNO = V_IFSEQNO
                      AND TRANSACTION_FLAG = 'P'
                    GROUP BY IFSEQNO
                           , SOLDTO_CODE
                           , COMPANY_ID
                           , MESSAGE_REFERENCE
                           , MESSAGE_TYPE
                           , DOC_IDENTIFINER
                           , EDI_INTERCHANGE_NO
                           , DOC_ISSUE_DATE
                           , RDD_TYPE
                           , COMPANY_NAME
                           , SOLDTO_NAME
                           , EDI_IF_SEQ
                           , TRANSACTION_FLAG
                           , CREATE_USER_ID
                           , CREATE_DATE
                           , CREATE_TIME
                           , UPDATE_USER_ID
                           , UPDATE_DATE
                           , UPDATE_TIME
                           , TRANSFER_CREATE_USER_ID
                           , TRANSFER_CREATE_DATE
                           , TRANSFER_CREATE_TIME
                           , TRANSFER_UPDATE_USER_ID
                           , TRANSFER_UPDATE_DATE
                           , TRANSFER_UPDATE_TIME
                           , DOC_STATUS
                           , (CASE
                                  WHEN IFSEQNO LIKE '1%' THEN
                                   'G'
                                  ELSE
                                   'D'
                              END || SENDER_CODE)
                           , SENDER_NAME
                           , CASE
                                 WHEN REGEXP_LIKE(ATTRIBUTE1, '^\d+$') THEN
                                  TO_NUMBER(ATTRIBUTE1)
                                 ELSE
                                  0
                             END
                           , CASE
                                 WHEN REGEXP_LIKE(ATTRIBUTE2, '^\d+$') THEN
                                  TO_NUMBER(ATTRIBUTE2)
                                 ELSE
                                  0
                             END) B
            ON (A.SOLDTO_CODE = B.SOLDTO_CODE AND A.COMPANY_ID = B.COMPANY_ID AND (A.MESSAGE_REFERENCE = B.MESSAGE_REFERENCE OR (A.MESSAGE_REFERENCE IS NULL AND B.MESSAGE_REFERENCE IS NULL)) AND (A.MESSAGE_TYPE = B.MESSAGE_TYPE OR (A.MESSAGE_TYPE IS NULL AND B.MESSAGE_TYPE IS NULL)) AND (A.DOC_IDENTIFINER = B.DOC_IDENTIFINER OR (A.DOC_IDENTIFINER IS NULL AND B.DOC_IDENTIFINER IS NULL)))
            WHEN MATCHED THEN
                UPDATE
                   SET A.EDI_INTERCHANGE_NO = B.EDI_INTERCHANGE_NO
                     , A.DOC_ISSUE_DATE     = B.DOC_ISSUE_DATE
                     , A.RDD_TYPE           = B.RDD_TYPE
                     , A.COMPANY_NAME       = B.COMPANY_NAME
                     , A.SOLDTO_NAME        = B.SOLDTO_NAME
                     , A.EDI_IF_SEQ         = B.EDI_IF_SEQ
                     , A.TRANSACTION_FLAG   = B.TRANSACTION_FLAG
                     , A.CREATE_USER_ID     = B.CREATE_USER_ID
                     , A.CREATE_DATE        = B.CREATE_DATE
                     , A.CREATE_TIME        = B.CREATE_TIME
                     , A.UPDATE_USER_ID     = B.UPDATE_USER_ID
                     , A.UPDATE_DATE        = B.UPDATE_DATE
                     , A.UPDATE_TIME        = B.UPDATE_TIME
                     , A.VALID_YN           = 'Y'
                     , A.LAST_UPDATED_BY    = V_BATCH_USER
                     , A.LAST_UPDATE_DATE   = SYSDATE
                     , A.ATTRIBUTE6         = B.DOC_STATUS
                     , A.SENDER_CODE        = B.SENDER_CODE
                     , A.SENDER_NAME        = B.SENDER_NAME
                     , A.TT_CNT             = B.TT_CNT
                     , A.SENDER_CNT         = B.SENDER_CNT
            WHEN NOT MATCHED THEN
                INSERT ( SOLDTO_CODE
                       , COMPANY_ID
                       , MESSAGE_REFERENCE
                       , MESSAGE_TYPE
                       , DOC_IDENTIFINER
                       , EDI_INTERCHANGE_NO
                       , DOC_ISSUE_DATE
                       , RDD_TYPE
                       , COMPANY_NAME
                       , SOLDTO_NAME
                       , EDI_IF_SEQ
                       , TRANSACTION_FLAG
                       , CREATE_USER_ID
                       , CREATE_DATE
                       , CREATE_TIME
                       , UPDATE_USER_ID
                       , UPDATE_DATE
                       , UPDATE_TIME
                       , VALID_YN
                       , CREATED_BY
                       , CREATION_DATE
                       , LAST_UPDATED_BY
                       , LAST_UPDATE_DATE
                       , ATTRIBUTE6
                       , SENDER_CODE
                       , SENDER_NAME
                       , TT_CNT
                       , SENDER_CNT )
                VALUES ( NVL(NULLIF(RTRIM(B.SOLDTO_CODE),''), '/')
                       , NVL(NULLIF(RTRIM(B.COMPANY_ID),''), '/')
                       , NVL(NULLIF(RTRIM(B.MESSAGE_REFERENCE),''), '/')
                       , NVL(NULLIF(RTRIM(B.MESSAGE_TYPE),''), '/')
                       , NVL(NULLIF(RTRIM(B.DOC_IDENTIFINER),''), '/')
                       , B.EDI_INTERCHANGE_NO
                       , B.DOC_ISSUE_DATE
                       , B.RDD_TYPE
                       , B.COMPANY_NAME
                       , B.SOLDTO_NAME
                       , B.EDI_IF_SEQ
                       , B.TRANSACTION_FLAG
                       , B.CREATE_USER_ID
                       , B.CREATE_DATE
                       , B.CREATE_TIME
                       , B.UPDATE_USER_ID
                       , B.UPDATE_DATE
                       , B.UPDATE_TIME
                       , 'Y'
                       , V_BATCH_USER
                       , SYSDATE
                       , V_BATCH_USER
                       , SYSDATE
                       , B.DOC_STATUS
                       , B.SENDER_CODE
                       , B.SENDER_NAME
                       , B.TT_CNT
                       , B.SENDER_CNT );

            /* 처리 한 row 마킹 */
            UPDATE XIF_ERP_EDI_CALLOFF_HEAD_R_SN
               SET TRANSACTION_FLAG = 'Y'
             WHERE TRANSACTION_FLAG = 'P'
               AND IFSEQNO = V_IFSEQNO;

        END LOOP;

        DBMS_OUTPUT.PUT_LINE('CUR_EDI_CALL_OFF_HEAD end' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* ---------------------------------------------------------------- */
        /* EDI_CALLOFF_HEAD (END) */
        /* ---------------------------------------------------------------- */
        /* ---------------------------------------------------------------- */
        /* EDI_CALLOFF_PARTNER (START) */
        /* ---------------------------------------------------------------- */
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_ERP_EDI_CALLOFF_PARTNER_R_SN
           SET TRANSACTION_FLAG = 'P'
         WHERE NVL(TRANSACTION_FLAG, 'N') = 'N'
           /* 2025.06.16   김준규   NERP) 오펀차수별 적용 대응 Start */
           /* OLD 코드는 반영이 되지 않게 처리 */
           AND NOT EXISTS (SELECT 1
                             FROM NERP_CONV_MASTER NCM
                            WHERE NCM.CODETYPE = 'COMPANY_ID'
                              AND NCM.OLD_VALUE1 = XIF_ERP_EDI_CALLOFF_PARTNER_R_SN.COMPANY_ID
                              AND NCM.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE)
           /* 2025.06.16   김준규   NERP) 오펀차수별 적용 대응 End */
        ;

        DBMS_OUTPUT.PUT_LINE('CUR_EDI_CALL_OFF_PARTNER start ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */

        /* CUR_EDI_CALL_OFF_PARTNER CURSOR FOR */

        FOR REC_PARTNER IN (SELECT IFSEQNO FROM XIF_ERP_EDI_CALLOFF_PARTNER_R_SN WHERE TRANSACTION_FLAG = 'P' GROUP BY IFSEQNO ORDER BY IFSEQNO ASC) LOOP
            V_IFSEQNO := REC_PARTNER.IFSEQNO;


            MERGE INTO DM_DNM_EDI_CALLOFF_PARTNER A
            USING (
                   SELECT IFSEQNO
                        , SOLDTO_CODE
                        , COMPANY_ID
                        , MESSAGE_REFERENCE
                        , MESSAGE_TYPE
                        , DOC_IDENTIFINER
                        , SHIPTO_CODE
                        , PARTNER_TYPE
                        , SHIPTO_SEQ
                        , COMPANY_NAME
                        , SHIPTO_NAME1
                        , SHIPTO_NAME2
                        , CITY_NAME
                        , POSTAL_CODE
                        , COUNTRY
                        , SHIPTO_DUNS_NO
                        , EDI_IF_SEQ
                        , TRANSACTION_FLAG
                        , SHIP_FROM_PLANT
                        , CREATE_USER_ID
                        , CREATE_DATE
                        , CREATE_TIME
                        , UPDATE_USER_ID
                        , UPDATE_DATE
                        , UPDATE_TIME
                        , TRANSFER_CREATE_USER_ID
                        , TRANSFER_CREATE_DATE
                        , TRANSFER_CREATE_TIME
                        , TRANSFER_UPDATE_USER_ID
                        , TRANSFER_UPDATE_DATE
                        , TRANSFER_UPDATE_TIME
                        , DOC_STATUS
                        , (CASE
                               WHEN IFSEQNO LIKE '1%' THEN
                                'G'
                               ELSE
                                'D'
                           END || SENDER_CODE) SENDER_CODE
                        , SENDER_NAME
                        , CASE
                              WHEN REGEXP_LIKE(ATTRIBUTE1, '^\d+$') THEN
                               TO_NUMBER(ATTRIBUTE1)
                              ELSE
                               0
                          END AS TT_CNT
                        , CASE
                              WHEN REGEXP_LIKE(ATTRIBUTE2, '^\d+$') THEN
                               TO_NUMBER(ATTRIBUTE2)
                              ELSE
                               0
                          END AS SENDER_CNT
                     FROM XIF_ERP_EDI_CALLOFF_PARTNER_R_SN
                    WHERE IFSEQNO = V_IFSEQNO
                      AND TRANSACTION_FLAG = 'P'
                    GROUP BY IFSEQNO
                           , SOLDTO_CODE
                           , COMPANY_ID
                           , MESSAGE_REFERENCE
                           , MESSAGE_TYPE
                           , DOC_IDENTIFINER
                           , SHIPTO_CODE
                           , PARTNER_TYPE
                           , SHIPTO_SEQ
                           , COMPANY_NAME
                           , SHIPTO_NAME1
                           , SHIPTO_NAME2
                           , CITY_NAME
                           , POSTAL_CODE
                           , COUNTRY
                           , SHIPTO_DUNS_NO
                           , EDI_IF_SEQ
                           , TRANSACTION_FLAG
                           , SHIP_FROM_PLANT
                           , CREATE_USER_ID
                           , CREATE_DATE
                           , CREATE_TIME
                           , UPDATE_USER_ID
                           , UPDATE_DATE
                           , UPDATE_TIME
                           , TRANSFER_CREATE_USER_ID
                           , TRANSFER_CREATE_DATE
                           , TRANSFER_CREATE_TIME
                           , TRANSFER_UPDATE_USER_ID
                           , TRANSFER_UPDATE_DATE
                           , TRANSFER_UPDATE_TIME
                           , DOC_STATUS
                           , (CASE
                                  WHEN IFSEQNO LIKE '1%' THEN
                                   'G'
                                  ELSE
                                   'D'
                              END || SENDER_CODE)
                           , SENDER_NAME
                           , CASE
                                 WHEN REGEXP_LIKE(ATTRIBUTE1, '^\d+$') THEN
                                  TO_NUMBER(ATTRIBUTE1)
                                 ELSE
                                  0
                             END
                           , CASE
                                 WHEN REGEXP_LIKE(ATTRIBUTE2, '^\d+$') THEN
                                  TO_NUMBER(ATTRIBUTE2)
                                 ELSE
                                  0
                             END
                  ) B
            ON (A.SOLDTO_CODE = B.SOLDTO_CODE AND A.COMPANY_ID = B.COMPANY_ID AND (A.MESSAGE_REFERENCE = B.MESSAGE_REFERENCE OR (A.MESSAGE_REFERENCE IS NULL AND B.MESSAGE_REFERENCE IS NULL)) AND (A.MESSAGE_TYPE = B.MESSAGE_TYPE OR (A.MESSAGE_TYPE IS NULL AND B.MESSAGE_TYPE IS NULL)) AND (A.DOC_IDENTIFINER = B.DOC_IDENTIFINER OR (A.DOC_IDENTIFINER IS NULL AND B.DOC_IDENTIFINER IS NULL)) AND (A.SHIPTO_CODE = B.SHIPTO_CODE OR (A.SHIPTO_CODE IS NULL AND B.SHIPTO_CODE IS NULL)) AND (A.PARTNER_TYPE = B.PARTNER_TYPE OR (A.PARTNER_TYPE IS NULL AND B.PARTNER_TYPE IS NULL)) AND (A.SHIPTO_SEQ = B.SHIPTO_SEQ OR (A.SHIPTO_SEQ IS NULL AND B.SHIPTO_SEQ IS NULL)))
            WHEN MATCHED THEN
                UPDATE
                   SET A.COMPANY_NAME     = B.COMPANY_NAME
                     , A.SHIPTO_NAME1     = B.SHIPTO_NAME1
                     , A.SHIPTO_NAME2     = B.SHIPTO_NAME2
                     , A.CITY_NAME        = B.CITY_NAME
                     , A.POSTAL_CODE      = B.POSTAL_CODE
                     , A.COUNTRY          = B.COUNTRY
                     , A.SHIPTO_DUNS_NO   = B.SHIPTO_DUNS_NO
                     , A.EDI_IF_SEQ       = B.EDI_IF_SEQ
                     , A.TRANSACTION_FLAG = B.TRANSACTION_FLAG
                     , A.SHIP_FROM_PLANT  = B.SHIP_FROM_PLANT
                     , A.CREATE_USER_ID   = B.CREATE_USER_ID
                     , A.CREATE_DATE      = B.CREATE_DATE
                     , A.CREATE_TIME      = B.CREATE_TIME
                     , A.UPDATE_USER_ID   = B.UPDATE_USER_ID
                     , A.UPDATE_DATE      = B.UPDATE_DATE
                     , A.UPDATE_TIME      = B.UPDATE_TIME
                     , A.VALID_YN         = 'Y'
                     , A.LAST_UPDATED_BY  = V_BATCH_USER
                     , A.LAST_UPDATE_DATE = SYSDATE
                     , A.ATTRIBUTE6       = B.DOC_STATUS
                     , A.SENDER_CODE      = B.SENDER_CODE
                     , A.SENDER_NAME      = B.SENDER_NAME
                     , A.TT_CNT           = B.TT_CNT
                     , A.SENDER_CNT       = B.SENDER_CNT
            WHEN NOT MATCHED THEN
                INSERT ( SOLDTO_CODE
                       , COMPANY_ID
                       , MESSAGE_REFERENCE
                       , MESSAGE_TYPE
                       , DOC_IDENTIFINER
                       , SHIPTO_CODE
                       , PARTNER_TYPE
                       , SHIPTO_SEQ
                       , COMPANY_NAME
                       , SHIPTO_NAME1
                       , SHIPTO_NAME2
                       , CITY_NAME
                       , POSTAL_CODE
                       , COUNTRY
                       , SHIPTO_DUNS_NO
                       , EDI_IF_SEQ
                       , TRANSACTION_FLAG
                       , SHIP_FROM_PLANT
                       , CREATE_USER_ID
                       , CREATE_DATE
                       , CREATE_TIME
                       , UPDATE_USER_ID
                       , UPDATE_DATE
                       , UPDATE_TIME
                       , VALID_YN
                       , CREATED_BY
                       , CREATION_DATE
                       , LAST_UPDATED_BY
                       , LAST_UPDATE_DATE
                       , ATTRIBUTE6
                       , SENDER_CODE
                       , SENDER_NAME
                       , TT_CNT
                       , SENDER_CNT )
                VALUES ( B.SOLDTO_CODE
                       , B.COMPANY_ID
                       , NVL(NULLIF(RTRIM(B.MESSAGE_REFERENCE),''), '/')
                       , B.MESSAGE_TYPE
                       , NVL(NULLIF(RTRIM(B.DOC_IDENTIFINER),''), '/')
                       , B.SHIPTO_CODE
                       , B.PARTNER_TYPE
                       , B.SHIPTO_SEQ
                       , B.COMPANY_NAME
                       , B.SHIPTO_NAME1
                       , B.SHIPTO_NAME2
                       , B.CITY_NAME
                       , B.POSTAL_CODE
                       , B.COUNTRY
                       , B.SHIPTO_DUNS_NO
                       , B.EDI_IF_SEQ
                       , B.TRANSACTION_FLAG
                       , B.SHIP_FROM_PLANT
                       , B.CREATE_USER_ID
                       , B.CREATE_DATE
                       , B.CREATE_TIME
                       , B.UPDATE_USER_ID
                       , B.UPDATE_DATE
                       , B.UPDATE_TIME
                       , 'Y'
                       , V_BATCH_USER
                       , SYSDATE
                       , V_BATCH_USER
                       , SYSDATE
                       , B.DOC_STATUS
                       , B.SENDER_CODE
                       , B.SENDER_NAME
                       , B.TT_CNT
                       , B.SENDER_CNT );

            /* 처리 한 row 마킹 */
            UPDATE XIF_ERP_EDI_CALLOFF_PARTNER_R_SN
               SET TRANSACTION_FLAG = 'Y'
             WHERE TRANSACTION_FLAG = 'P'
               AND IFSEQNO = V_IFSEQNO;

        END LOOP;

        DBMS_OUTPUT.PUT_LINE('CUR_EDI_CALL_OFF_PARTNER end ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* ---------------------------------------------------------------- */
        /* EDI_CALLOFF_ITEM (START) */
        /* ---------------------------------------------------------------- */
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_ERP_EDI_CALLOFF_ITEM_R_SN
           SET TRANSACTION_FLAG = 'P'
         WHERE NVL(TRANSACTION_FLAG, 'N') = 'N'
           /* 2025.06.16   김준규   NERP) 오펀차수별 적용 대응 Start */
           /* OLD 코드는 반영이 되지 않게 처리 */
           AND NOT EXISTS (SELECT 1
                             FROM NERP_CONV_MASTER NCM
                            WHERE NCM.CODETYPE = 'COMPANY_ID'
                              AND NCM.OLD_VALUE1 = XIF_ERP_EDI_CALLOFF_ITEM_R_SN.COMPANY_ID
                              AND NCM.ATTRIBUTE5 <= V_NERP_ROLLIN_STAGE)
           /* 2025.06.16   김준규   NERP) 오펀차수별 적용 대응 End */
        ;

        DBMS_OUTPUT.PUT_LINE('XIF_ERP_EDI_CALLOFF_ITEM_R_SN start ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

        /* 테이블중복제거 */
        /* 임시확인용테이블 중복제거 */

        EXECUTE IMMEDIATE 'TRUNCATE TABLE GT_DDECD_EDI_NEW_ALL';

        INSERT
          INTO GT_DDECD_EDI_NEW_ALL
             ( NUM, IFSEQNO )
        SELECT ROW_NUMBER() OVER(ORDER BY (SELECT 1 FROM DUAL)) NUM, IFSEQNO
          FROM XIF_ERP_EDI_CALLOFF_ITEM_R_SN
         WHERE TRANSACTION_FLAG = 'P'
         GROUP BY IFSEQNO
         ORDER BY IFSEQNO ASC;

        SELECT COUNT(*) INTO V_CNT FROM GT_DDECD_EDI_NEW_ALL;
        DBMS_OUTPUT.PUT_LINE(V_CNT);
        /* ◇◇◇◇◇ */
        WHILE (V_I <= V_CNT) LOOP
            DBMS_OUTPUT.PUT_LINE(V_I);
            /* 신규 IFSEQNO */
            SELECT IFSEQNO INTO V_IFSEQNO FROM GT_DDECD_EDI_NEW_ALL WHERE NUM = V_I;
            DBMS_OUTPUT.PUT_LINE('IFSEQNO : ' || V_IFSEQNO);
            INSERT INTO DM_DNM_EDI_CALLOFF_ITEM
                       ( EDI_IF_SEQ
                       , SUB_NO
                       , YYYYMMDD
                       , DIVISION_ID
                       , SOLDTO_CODE
                       , COMPANY_ID
                       , MESSAGE_REFERENCE
                       , MESSAGE_TYPE
                       , DOC_IDENTIFINER
                       , SHIPTO_CODE
                       , PARTNER_TYPE
                       , SHIPTO_SEQ
                       , SHIP_TO_ITEM_SEQ
                       , ITEM_ID
                       , CUSTOMER_PLANT
                       , UNLOADING_POINT
                       , SCHEDULING_TYPE
                       , RDD_START
                       , QTY
                       , UOM
                       , RDD_END
                       , CUSTOMER_PO_NO
                       , CUSTOMER_CALL_OFF_NO
                       , CUSTOMER_CALL_OFF_DATE
                       , PREVIOUS_CALL_OFF_NO
                       , PREVIOUS_CALL_OFF_DATE
                       , COMPANY_NAME
                       , SHIPTO_NAME1
                       , SHIPTO_NAME2
                       , TRANSACTION_FLAG
                       , ERP_FCST_TYPE
                       , CREATE_USER_ID
                       , CREATE_DATE
                       , CREATE_TIME
                       , UPDATE_USER_ID
                       , UPDATE_DATE
                       , UPDATE_TIME
                       , VALID_YN
                       , CREATED_BY
                       , CREATION_DATE
                       , LAST_UPDATED_BY
                       , LAST_UPDATE_DATE
                       , IFSEQNO
                       , SOLDTO_CODE_W
                       , MESSAGE_TYPE_W
                       , RDD_START_W
                       , DOC_STATUS
                       , PROJECT_CODE
                       , SCM_SITE_ID
                       , SALES_PLANT_SITE_ID
                       , EDI_INCOTERMS
                       , STATUS_CODE
                       , BOM_STATUS
                       , SALES_SITE_STATUS
                       , SSPM_STATUS
                       , PROJECT_STATUS
                       , ITEM_STATUS
                       , SALES_PLANT_SITE_STATUS
                       , INCOTERMS_STATUS
                       , CUST_MATERIAL_CODE
                       , SENDER_CODE
                       , SENDER_NAME
                       , TT_CNT
                       , SENDER_CNT
                       , ERP_STATUS
                       , BASIS_YYYYMMDD
                       , DC_LEVEL /* [E20250910-000974]_NN Mapping Master 컬럼 추가 요청 */
                       )
                SELECT EDI_IF_SEQ
                     , ROW_NUMBER() OVER(PARTITION BY EDI_IF_SEQ ORDER BY RDD_START) SUB_NO
                     , CASE
                           WHEN SUBSTR(RDD_START, 7, 2) = '00' THEN
                            TO_CHAR(LAST_DAY(SUBSTR(RDD_START, 1, 6) || '01'), 'YYYYMMDD')
                           ELSE
                            NVL(RDD_START, NULL) /* RDD_START가 년/월까지만 정의된 경우 월초로 데이터 변환 */
                       END AS YYYYMMDD
                     , B.SEGMENT2 DIVISION_ID /* EDI는 모두 81로 넘어옴 ==> 법인코드별로 JV 법인 구분 기능 */
                     , NVL(A.SOLDTO_CODE, NULL) SOLDTO_CODE
                     , NVL(COMPANY_ID, NULL) COMPANY_ID
                     , NVL(MESSAGE_REFERENCE, NULL) MESSAGE_REFERENCE
                     , MESSAGE_TYPE
                     , NVL(DOC_IDENTIFINER, NULL) DOC_IDENTIFINER
                     , NVL(A.SHIPTO_CODE, NULL) SHIPTO_CODE
                     , PARTNER_TYPE
                     , SHIPTO_SEQ
                     , SHIP_TO_ITEM_SEQ
                     , NVL(LTRIM(RTRIM(ITEM_ID)), NULL) ITEM_ID
                     , NVL(LTRIM(RTRIM(CUSTOMER_PLANT)), NULL) CUSTOMER_PLANT
                     , NVL(LTRIM(RTRIM(UNLOADING_POINT)), NULL) UNLOADING_POINT
                     , SCHEDULING_TYPE
                     , RDD_START
                     , QTY
                     , UOM
                     , RDD_END
                     , CUSTOMER_PO_NO
                     , CUSTOMER_CALL_OFF_NO
                     , CUSTOMER_CALL_OFF_DATE
                     , PREVIOUS_CALL_OFF_NO
                     , PREVIOUS_CALL_OFF_DATE
                     , COMPANY_NAME
                     , SHIPTO_NAME1
                     , SHIPTO_NAME2
                     , TRANSACTION_FLAG
                     , ERP_FCST_TYPE
                     , CREATE_USER_ID
                     , CREATE_DATE
                     , CREATE_TIME
                     , UPDATE_USER_ID
                     , UPDATE_DATE
                     , UPDATE_TIME
                     , 'Y' AS VALID_YN
                     , V_BATCH_USER
                     , SYSDATE
                     , V_BATCH_USER
                     , SYSDATE
                     , V_IFSEQNO IFSEQNO
                     , A.SOLDTO_CODE
                     , MESSAGE_TYPE
                     , CASE
                           WHEN SUBSTR(RDD_START, 7, 2) = '00' THEN
                            RDD_START
                           ELSE
                            NULL
                       END AS RDD_START_W
                     , NVL(A.DOC_STATUS, NULL) DOC_STATUS
                     , NULL AS PROJECT_CODE
                     , NULL AS SCM_SITE_ID
                     , NULL AS SALES_PLANT_SITE_ID
                     , NULL AS EDI_INCOTERMS
                     , 'U' AS STATUS_CODE
                     , 'S' AS BOM_STATUS /* BOM_STATUS는 체크 제외함. */
                     , 'E' AS SALES_SITE_STATUS
                     , 'E' AS SSPM_STATUS
                     , 'E' AS PROJECT_STATUS
                     , 'E' AS ITEM_STATUS
                     , 'E' AS SALES_PLANT_SITE_STATUS
                     , 'E' AS INCOTERMS_STATUS
                     , NVL(LTRIM(RTRIM(CUST_MATERIAL_CODE)), NULL) CUST_MATERIAL_CODE
                     , (CASE
                            WHEN IFSEQNO LIKE '1%' THEN
                             'G'
                            ELSE
                             'D'
                        END || SENDER_CODE) SENDER_CODE
                     , SENDER_NAME
                     , CASE
                           WHEN REGEXP_LIKE(A.ATTRIBUTE1, '^\d+$') THEN
                            TO_NUMBER(A.ATTRIBUTE1)
                           ELSE
                            0
                       END TT_CNT
                     , CASE
                           WHEN REGEXP_LIKE(A.ATTRIBUTE2, '^\d+$') THEN
                            TO_NUMBER(A.ATTRIBUTE2)
                           ELSE
                            0
                       END SENDER_CNT
                     , CASE
                           WHEN (RDD_START IS NULL OR LENGTH(RDD_START) <> 8 OR SOLDTO_CODE IS NULL OR SHIPTO_CODE IS NULL OR ITEM_ID IS NULL) THEN
                            'E'
                           ELSE
                            'S'
                       END AS ERP_STATUS
                     , CASE
                           WHEN SUBSTR(RDD_START, 7, 2) = '00' THEN
                            TO_CHAR(LAST_DAY(SUBSTR(RDD_START, 1, 6) || '01'), 'YYYYMMDD')
                           ELSE
                            NVL(RDD_START, NULL)
                       END AS BASIS_YYYYMMDD
                     , A.ATTRIBUTE3 /* [E20250910-000974]_ERP에서 ATTRIBUTE3에 DC_LEVEL 정보를 넣어 주기로함 */
                  FROM XIF_ERP_EDI_CALLOFF_ITEM_R_SN A
                 INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B /* [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 start */
                    ON B.LOOKUP_TYPE = 'DM_EDI_COMPANY_DIVISION_MAPPING'
                   AND A.COMPANY_ID = B.SEGMENT1
                   AND B.VALID_YN = 'Y'
                 WHERE IFSEQNO = V_IFSEQNO
                   AND TRANSACTION_FLAG = 'P';
            DBMS_OUTPUT.PUT_LINE('END');
            /* 처리 한 row 마킹 */
            UPDATE XIF_ERP_EDI_CALLOFF_ITEM_R_SN
               SET TRANSACTION_FLAG = 'Y'
             WHERE TRANSACTION_FLAG = 'P'
               AND IFSEQNO = V_IFSEQNO;

            V_I := V_I + 1;

        END LOOP;

        /* 처리결과건수 로그변수에 입력 */
        SELECT COUNT(*)
          INTO V_TMP_COUNT
          FROM DM_DNM_EDI_CALLOFF_ITEM
         WHERE 1 = 1
           AND IFSEQNO IN (SELECT IFSEQNO FROM GT_DDECD_EDI_NEW_ALL);
        V_NEW_INSERT_COUNT := V_NEW_INSERT_COUNT + V_TMP_COUNT;

    END IF;
    /* ◇◇◇◇◇ IF TABLE의 정보가 존재하는경우 수행 (END) ◇◇◇◇◇ */

    COMMIT;


    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'EDI New INSERT INTO Count : ' || TO_CHAR(V_NEW_INSERT_COUNT);
    D_EVENT_DATE  := SYSTIMESTAMP;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    DBMS_OUTPUT.PUT_LINE('end ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            ,'ERROR'
                            ,0
                            ,SQLERRM
                            ,NULL
                            ,SYSDATE
                            ,P_IN_PARA_DATA  => V_IN_PARA_DATA
                            ,P_SQL_ERR_CODE  => SQLCODE
                            ,P_SQL_ERR_MSG   => SQLERRM
                            ,P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
        RAISE_APPLICATION_ERROR(-20001
                               ,'[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' ||
                                DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;
/
SHOW ERRORS PROCEDURE PR_DM_DNM_EDI_CALLOFF_DATA
-- ##### END PROCEDURE PR_DM_DNM_EDI_CALLOFF_DATA

-- ##### START PROCEDURE PR_DM_DNM_EDI_CALLOFF_MKT_FCST
CREATE OR REPLACE PROCEDURE           "PR_DM_DNM_EDI_CALLOFF_MKT_FCST" 
/*
 * Program ID  : PR_DM_DNM_EDI_CALLOFF_MKT_FCST
 * Description  : GSCM COMPLETED EDI 정보 -> MKT_FCST INSERT(CUST_FCST_EDI MEASURE)
 *                  DM_DNM_EDI_CALLOFF_ITEM -> DM_PLN_MKT_FCST
 * Program History
 *===================================================================================================
 *   Date       In Charge      Description
 *===================================================================================================
 * 배포시 주의사항 : 개발기 -> LGCE_INFDEV , 운영기 -> LGCE_INF
 *===================================================================================================
   20230503 kdmcc14      [EDI과제] PROJECT EDI_CALLOFF DATA -> MKT FCST MEASURE 생성
   20231006 chutoc730    [EDI과제] CUST_MATERIAL_CODE NOT LIKE '9j1%' 예외 분기 추가
   20231101 chutoc730    [EDI과제] MEASURE(SCHEDULING_TYPE) 별 오류 합 수정
   20231116 chutoc730    [EDI과제] Porsche/Audi/DRX Audi_DE_SHM / Porsche_DE_SHM 예외 로직 추가 / 추후 제외 소급 적용 룰 추가
   20231205 chutoc730    [EDI과제] 유통기간내 고객수요를 합산 로직을 기간내 MAX(IF_SEQ) 조건으로 합산 / 그룹조건에 CUSTOMER_PLANT를 추가하고 CUST_MATERIAL_CODE 를 제거 수정.
   20231206 chutoc730    MKT FCST[Auto] 화면 관련하여 발주처 예외처리.
   20240105 chutoc730    기존데이터 삭제 기준 날짜 변경 금주월요일~계획구간에서 당일~계획구간.
   20240116 chutoc730    END_CUSTOMER 추가 및 기준 하드코딩 LOOKUP(DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER) 에 데이터화.
   20240424 kcw3408      SENDER_NAME 30--> 200 으로 수정
   20240429 kcw3408      N:N Model Mapping_적재 추가(집계 시점에 Cust Item/Unloading Point/Plant 고려,Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음)
   20240626 JSSBAE       [E20240620-001488]_SCM DM 고객수요분석- Cust Plant NULL인 데이터 처리로직 개선
   20240626 JSSBAE       [E20240610-000320]_SCM DM EDI(Cust FCST) 관련 문의사항 (예외로직적용: 앞뒤 공백값, NULL값 공백으로 치환해서 비교 처리)
   20240703 JSSBAE       [E20240701-000472]_[공급 SCM PI팀] ERP EDI Master화면 업데이트 범위 개선
   20241204 JSSBAE       [E20241126-000426]_Cust.FCST(P+P) Measure 로직 수정
   20241216 KANG.H.J     [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 */
AS
    V_BATCH_USER         VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME       VARCHAR2(150 CHAR) := $$PLSQL_UNIT;
    V_BATCH_CHK_MSG      VARCHAR2(150 CHAR) := ' [DM]SOLDTO_CODE 없이 들어와서 계속해서 에러를 발생시켜서 TRANSFER_FLAG 를 변경함.';
    V_LOG_TYPE           VARCHAR2(30 CHAR);
    N_LOG_COUNT          INTEGER := 0;
    V_LOG_MESSAGE        VARCHAR2(1000 CHAR);
    V_DESCRIPTION        VARCHAR2(500 CHAR);
    D_EVENT_DATE         DATE;
    V_IFSEQNO_INSERT     VARCHAR2(30 CHAR);
    V_SOLDTO_CODE        VARCHAR2(10 CHAR);
    V_SHIPTO_CODE        VARCHAR2(10 CHAR);
    V_UNLOADING_POINT    VARCHAR2(35 CHAR);
    V_CUSTOMER_PLANT     VARCHAR2(8 CHAR);
    V_SCHEDULING_TYPE    VARCHAR2(6 CHAR);
    V_PROJECT_CODE       VARCHAR2(100 CHAR);
    V_SCM_SITE_ID        VARCHAR2(100 CHAR);
    V_CUST_MATERIAL_CODE VARCHAR2(70 CHAR);
    V_ITEM_ID            VARCHAR2(100 CHAR);
    V_END_CUSTOMER       VARCHAR2(35 CHAR);
    V_SENDER_NAME        VARCHAR2(200 CHAR);
    V_CREATE_DATE        VARCHAR2(16 CHAR);
    V_CREATE_TIME        VARCHAR2(10 CHAR);
    V_0WEEK_MONDAY       VARCHAR2(8 CHAR);
    V_1WEEK_MONDAY       VARCHAR2(8 CHAR);
    V_TODAY              VARCHAR2(8 CHAR);
    V_HOUR               VARCHAR2(2 CHAR);
    V_YYYYMMDD           VARCHAR2(8 CHAR);
    V_DATEADDTODAY       DATE;
    V_I                  INTEGER := 1;
    V_CNT                INTEGER := 0;
    V_J                  INTEGER := 1;
    V_CNT_ORG            INTEGER := 0;
    V_FROM_YYYYMMDD      VARCHAR2(4000 CHAR);
    V_CUST_FCST_I        INTEGER;
    V_CUST_FCST_CNT      INTEGER;
    V_CUST_FCST_DIVISION VARCHAR2(30 CHAR);
    V_IN_PARA_DATA       VARCHAR2(4000 CHAR);
BEGIN

    /* LOG 용 변수 설정 */
    V_HOUR := NULL;


    DELETE FROM GT_DDECM_DM_CUST_MODEL_MAPPING;
    DELETE FROM GT_DDECM_CUST_FCST_DIVISION;
    DELETE FROM GT_DDECM_MKT_ORG_DATA;

    /* 시작 LOG */
    V_LOG_TYPE     := 'START';
    V_LOG_MESSAGE  := '########## Start of procedure ##########';
    V_DESCRIPTION  := NULL;
    D_EVENT_DATE   := SYSDATE;
    D_EVENT_DATE   := SYSDATE;
    V_DATEADDTODAY := SYSDATE;
    V_TODAY        := TO_CHAR(V_DATEADDTODAY, 'YYYYMMDD');

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_0WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'MON') + (-7), 'YYYYMMDD');     /* W0월요일 */
    V_1WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'MON') + (-7 + 7), 'YYYYMMDD'); /* W1월요일 */
    /* 현재시간 */
    V_HOUR := SUBSTR(TO_CHAR(V_DATEADDTODAY, 'HH24:MI:SS'), 1, 2);

    DBMS_OUTPUT.PUT_LINE(V_1WEEK_MONDAY);

    /* 오늘 기준 52W 전까지 조회함 */
    V_FROM_YYYYMMDD := TO_CHAR(TRUNC(SYSDATE, 'IW') - (52 * 7), 'YYYYMMDD');
    /* PSA 데이터 조회일자 */
    BEGIN
        /* 다음주 일요일을 날짜기준으로 삼는데. (단 오늘이 일요일이면 오늘부터 기준을 삼음) */
        SELECT CASE
                   WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY, 'D')) = 1 THEN TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'SUN') + (-7), 'YYYYMMDD')
                   ELSE TO_CHAR(FN_NEXT_DAY(V_DATEADDTODAY, 'SUN') + 0, 'YYYYMMDD')
               END
          INTO V_YYYYMMDD
          FROM DUAL;
    END;

    BEGIN

        /* 예외 Sales Site 관리 테이블중복제거 / 임시확인용 Sales Site 관리 테이블 중복제거 */
        DELETE FROM GT_DDECM_EDI_MGM_SALES_SITE;

        /* 테이블중복제거 / 임시확인용테이블 중복제거 */
        DELETE FROM GT_DDECM_EDI_END_CUSTOMER;

        /* EDI END_CUSTOMER별 기간 설정 */
        BEGIN
            /* EDI_END_CUSTOMER Lookup의 Active = 'Off'이면 CREATE_DATE -52주부터, 'On'이면 Lookup 기간 사용 */
            INSERT INTO GT_DDECM_EDI_END_CUSTOMER
                (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, FROM_WEEK, FROM_DAY, TO_WEEK, TO_DAY, ACTIVE)
            SELECT A.DIVISION_ID                                          AS DIVISION_ID
                 , A.END_CUSTOMER                                         AS END_CUSTOMER
                 , NVL(NULLIF(RTRIM(B.SEGMENT4),''), '/')                                   AS SCM_SITE_ID
                 , CASE WHEN NVL(B.SEGMENT5, 'On') = 'On' THEN NVL(B.ATTRIBUTE1, '-1')
                        ELSE '-52'
                   END                                                    AS FROM_WEEK
                 , NVL(B.ATTRIBUTE2, 'TUE')                               AS FROM_DAY
                 , NVL(B.ATTRIBUTE3, '0')                                 AS TO_WEEK
                 , NVL(B.ATTRIBUTE4, 'MON')                               AS TO_DAY
                 , NVL(B.SEGMENT5, 'On')                                  AS ACTIVE
              FROM SCM_MST_SITE A
              LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                ON  B.LOOKUP_TYPE  = 'EDI_END_CUSTOMER'
                AND A.DIVISION_ID  = B.SEGMENT1
                AND A.END_CUSTOMER = B.SEGMENT2
                AND B.VALID_YN     = 'Y'
             WHERE A.END_CUSTOMER IS NOT NULL
             GROUP BY A.DIVISION_ID, A.END_CUSTOMER, B.SEGMENT4, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.SEGMENT5;
        END;

        BEGIN
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_ALL;

            /* EDI STATUS_CODE가 SUCCESS인 DATA */
            BEGIN
                /* DIVISION_ID, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, ITEM_ID, SCHEDULING_TYPE 기준으로 DATA 추출 */
                /* EDI물동 기준이 되는 IFSEQNO 추출함. */
                INSERT INTO GT_DDECM_EDI_ALL
                    (NUM, DIVISION_ID, IFSEQNO, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, CUSTOMER_PLANT, SCHEDULING_TYPE
                    , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, ERP_FCST_TYPE, CREATE_DATE, CREATE_TIME, MESSAGE_TYPE, END_CUSTOMER, SENDER_NAME, YYYYMMDD)
                SELECT ROW_NUMBER() OVER (ORDER BY A.IFSEQNO)             AS NUM   /* 해당 칼럼이 필요한가?? */
                     , A.DIVISION_ID
                     , A.IFSEQNO
                     , A.SOLDTO_CODE
                     , A.SHIPTO_CODE
                     , A.UNLOADING_POINT
                     , A.CUSTOMER_PLANT
                     , A.SCHEDULING_TYPE
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.ERP_FCST_TYPE
                     , A.CREATE_DATE
                     , A.CREATE_TIME
                     , A.MESSAGE_TYPE
                     , A.END_CUSTOMER
                     , A.SENDER_NAME
                     , A.YYYYMMDD
                  FROM (
                        SELECT ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCHEDULING_TYPE, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                                                             , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                                  ORDER BY A.CREATE_DATE DESC, A.IFSEQNO DESC)     AS RNK
                             , A.DIVISION_ID
                             , A.IFSEQNO
                             , A.SOLDTO_CODE
                             , A.SHIPTO_CODE
                             , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                             , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                             , A.SCHEDULING_TYPE
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END           AS ERP_FCST_TYPE
                             , A.CREATE_DATE
                             , A.CREATE_TIME
                             , A.MESSAGE_TYPE
                             , B.END_CUSTOMER
                             , A.SENDER_NAME
                             , A.YYYYMMDD
                          FROM DM_DNM_EDI_CALLOFF_ITEM A
                          LEFT OUTER JOIN SCM_MST_SITE B
                            ON  A.DIVISION_ID = B.DIVISION_ID
                            AND A.SCM_SITE_ID = B.SCM_SITE_ID
                            AND B.SITE_TYPE   = 'SALES'
                            AND B.VALID_YN    = 'Y'
                            AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                          LEFT OUTER JOIN LATERAL (SELECT C1.*
                                         FROM GT_DDECM_EDI_END_CUSTOMER C1
                                        WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                          AND C1.END_CUSTOMER = B.END_CUSTOMER
                                          AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                       FROM GT_DDECM_EDI_END_CUSTOMER X99
                                                                      WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                        AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                        AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                         WHERE 1 = 1
                           AND A.CREATE_DATE >= V_FROM_YYYYMMDD    /* 52주 전부터가 유효한 데이터임. */
                           AND A.YYYYMMDD    >= V_TODAY            /* 당일 이후 */
/*
   [원본 보존] 아래 CALENDAR 기반 CREATE_DATE 시작/종료일 산출 블록은 원본 MSSQL에서 주석처리되어 비활성 상태임.
   AND A.CREATE_DATE >= (
       SELECT BASIS_YYYYMMDD   -- 시작일의 정의 (-1주 OR -52주의 날짜를 지정한 요일로 추출함)
       FROM (
             SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 2 THEN TO_CHAR(V_DATEADDTODAY-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(V_DATEADDTODAY-2,'YYYYMMDD') ELSE TO_CHAR(V_DATEADDTODAY,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.FROM_DAY   -- 사용자가 정의한 요일로 처리
            ) D
       WHERE D.RK = C.FROM_WEEK    -- FROM_WEEK는 -1 OR -52로만 존재함.
   )
   AND A.CREATE_DATE <= (
       SELECT BASIS_YYYYMMDD -- 종료일을 지정함 (0주(금주) OR -1주(차주)의 날짜를 지정한 요일로 추출함)
       FROM (
             SELECT (CASE WHEN DAYOFWEEK = 'SUN' THEN RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 2
                          ELSE RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 1 END) AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD >= (CASE WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 2 THEN TO_CHAR(V_DATEADDTODAY-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(V_DATEADDTODAY,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(V_DATEADDTODAY-2,'YYYYMMDD') ELSE TO_CHAR(V_DATEADDTODAY,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.TO_DAY
            ) D
       WHERE D.RK = C.TO_WEEK
   )
*/
                           AND A.STATUS_CODE = 'S'
                           AND EXISTS (
                                        SELECT 1
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                                         WHERE LUP.LOOKUP_TYPE = 'DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER'
                                           AND LUP.SEGMENT1    = A.DIVISION_ID
                                           AND LUP.SEGMENT2    = A.SENDER_NAME
                                           AND LUP.SEGMENT3    = B.END_CUSTOMER
                                           AND LUP.SEGMENT4    = A.SCHEDULING_TYPE
                                           AND A.MESSAGE_TYPE  = (CASE WHEN LUP.SEGMENT5 IN ('DELJIT', 'DELFOR') THEN LUP.SEGMENT5   /* DELJIT / DELFOR로 정의되어 있으면. 정의된 데이터만 추출함. */
                                                                       ELSE (                                                       /* 그렇지 않을 경우 이번주 일요일까지는 DELJIT / 그 이후로는 DELFOR 로 정의된 추출함. */
                                                                             CASE WHEN A.YYYYMMDD <= V_YYYYMMDD THEN 'DELJIT'
                                                                                  ELSE 'DELFOR'
                                                                             END)
                                                                  END)
                                           AND LUP.VALID_YN = 'Y'
                                           AND ((LENGTH(LUP.ATTRIBUTE2) < 8 AND LENGTH(LUP.ATTRIBUTE3) < 8) OR (A.YYYYMMDD BETWEEN LUP.ATTRIBUTE1 AND LUP.ATTRIBUTE2))  /* 유효날짜 체크함. */
                                      )
                         GROUP BY A.DIVISION_ID
                                , A.IFSEQNO
                                , A.SOLDTO_CODE
                                , A.SHIPTO_CODE
                                , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')
                                , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')
                                , A.SCHEDULING_TYPE
                                , A.PROJECT_CODE
                                , A.SCM_SITE_ID
                                , A.ITEM_ID
                                , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                , A.CREATE_DATE
                                , A.CREATE_TIME
                                , A.MESSAGE_TYPE
                                , B.END_CUSTOMER
                                , A.SENDER_NAME
                                , A.YYYYMMDD
                       ) A
                 WHERE RNK = 1
                   AND LENGTH(A.YYYYMMDD) = 8    /* 강현준 추가 ('444444' 가 추가되어 있음 */
                 ORDER BY A.IFSEQNO;
            END;

            /* 자료 추출(고객수요 N:N Mapping 적용) */
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_MKT_FCST;
            DELETE FROM GT_DDECM_EDI_MKT_FCST_ALL;

            /* 2024.04.29    kcw3408       고객수요 N:N Mapping  */
            BEGIN
                /* [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 START */
                INSERT INTO GT_DDECM_DM_CUST_MODEL_MAPPING
                    (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, ITEM_ID, MAPPING_ITEM_ID
                    , UNLOADING_POINT, CUSTOMER_PLANT, CUSTOMER_ITEM_ID, VALID_START_DATE, VALID_END_DATE)
                SELECT DISTINCT A.DIVISION_ID
                     /* , A.DATA_TYPE_CODE  -- MKT_FCST(CUST_FCST)는 롤인/롤아웃 구분없이 모두 생성하므로 DATA_TYPE_CODE 구분없이 처리함. */
                     , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                     , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                     , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), ' ') AS CUSTOMER_ITEM_ID
                     , MAX(A.VALID_START_DATE)                    AS VALID_START_DATE
                     , MAX(A.VALID_END_DATE)                      AS VALID_END_DATE
                  FROM DM_CUST_MODEL_MAPPING_M A
                 WHERE A.ACTIVE_YN = 'Y'
                 /* AND A.DATA_TYPE_CODE = 'SCM' */
                 GROUP BY A.DIVISION_ID
                     , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                     , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                     , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), ' '), NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), ' ')
                     , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), ' ');
                /* [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선 END */
            END;

            SELECT COUNT(*) INTO V_CNT FROM GT_DDECM_EDI_ALL;

            IF (V_CNT > 0) THEN

                INSERT INTO GT_DDECM_EDI_MKT_FCST_ALL
                    (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                    , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                    , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                    , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, CREATE_TIME, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                SELECT X1.EDI_IF_SEQ, X1.SUB_NO, X1.YYYYMMDD
                     , X1.DIVISION_ID, X1.SCM_SITE_ID, X1.ITEM_ID, X1.PROJECT_CODE
                     , CASE WHEN X1.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END                 AS ERP_FCST_TYPE
                     , X1.BASIS_YYYYMMDD, X1.QTY, X1.EDI_INCOTERMS, X1.SALES_PLANT_SITE_ID
                     , 'E'                                                                         AS DOM_EXP
                     , X1.COMPANY_ID, X1.SOLDTO_CODE, X1.SHIPTO_CODE
                     , X1.DOC_IDENTIFINER, X1.MESSAGE_TYPE
                     , NVL(RTRIM(LTRIM(X1.UNLOADING_POINT)), ' ')                                 AS UNLOADING_POINT
                     , NVL(RTRIM(LTRIM(X1.CUSTOMER_PLANT)), ' ')                                  AS CUSTOMER_PLANT
                     , X1.RDD_START, X1.RDD_END
                     , X1.IFSEQNO
                     , X1.SCHEDULING_TYPE
                     , CASE WHEN (X1.MESSAGE_TYPE = 'DELFOR' AND X1.SOLDTO_CODE = 'FR000064' AND X1.RDD_START <> X1.RDD_END AND X1.RDD_START >= V_1WEEK_MONDAY) THEN 'Periodic DELFOR'
                            ELSE NULL
                       END                                                                        AS DELFOR_TYPE
                     , X1.EDI_LT
                     , NVL(RTRIM(LTRIM(X1.CUST_MATERIAL_CODE)), ' ')                              AS CUST_MATERIAL_CODE
                     , X1.CREATE_DATE, X1.CREATE_TIME
                     , X1.SENDER_CODE, X1.SENDER_NAME
                     , X1.ATTRIBUTE10
                  FROM DM_DNM_EDI_CALLOFF_ITEM X1
                  INNER JOIN GT_DDECM_EDI_ALL X2
                    ON  X1.IFSEQNO         = X2.IFSEQNO
                    AND X1.SOLDTO_CODE     = X2.SOLDTO_CODE
                    AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                    AND X1.SCHEDULING_TYPE = X2.SCHEDULING_TYPE
                    AND X1.PROJECT_CODE    = X2.PROJECT_CODE
                    AND X1.SCM_SITE_ID     = X2.SCM_SITE_ID
                    AND X1.ITEM_ID         = X2.ITEM_ID
                    AND X1.SENDER_NAME     = X2.SENDER_NAME
                    AND X1.CREATE_DATE     = X2.CREATE_DATE
                    AND X1.CREATE_TIME     = X2.CREATE_TIME
                    AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                 WHERE 1 = 1
                   AND X1.STATUS_CODE = 'S'
                   AND TO_NUMBER(REPLACE(NVL(X1.QTY, '0'), ',', '')) <> 0
                   AND NVL(X1.EXCEPTION_FLAG, 'N') != 'Y';

            END IF;

            BEGIN

                BEGIN
                /*
                   2024.04.29    kcw3408       고객수요 N:N Mapping
                   전체 대생 추출후 N:N Model Mapping 작업
                    .집계 시점에 Cust Item/Unloading Point/Plant 반영
                    .Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음
                    . GT_DDECM_EDI_MKT_FCST: 최종 결과,insert 작업
                */
                    BEGIN
                        INSERT INTO GT_DDECM_EDI_MKT_FCST
                            (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                            , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                            , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                            , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                        SELECT X.EDI_IF_SEQ
                             , X.SUB_NO
                             , X.YYYYMMDD
                             , X.DIVISION_ID
                             , X.SCM_SITE_ID
                             , B.ITEM_ID
                             , X.PROJECT_CODE
                             , X.ERP_FCST_TYPE
                             , X.BASIS_YYYYMMDD
                             , X.QTY
                             , X.EDI_INCOTERMS
                             , X.SALES_PLANT_SITE_ID
                             , X.DOM_EXP
                             , X.COMPANY_ID
                             , X.SOLDTO_CODE
                             , X.SHIPTO_CODE
                             , X.DOC_IDENTIFINER
                             , X.MESSAGE_TYPE
                             , NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                             , NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                             , X.RDD_START
                             , X.RDD_END
                             , X.IFSEQNO
                             , X.SCHEDULING_TYPE
                             , X.DELFOR_TYPE
                             , X.EDI_LT
                             , NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') AS CUST_MATERIAL_CODE
                             , X.CREATE_DATE
                             , X.SENDER_CODE
                             , X.SENDER_NAME
                             , X.CHANGE_STATUS
                          FROM GT_DDECM_EDI_MKT_FCST_ALL X
                          JOIN GT_DDECM_DM_CUST_MODEL_MAPPING B
                            ON  X.DIVISION_ID   = B.DIVISION_ID
                            AND X.SCM_SITE_ID   = B.SCM_SITE_ID
                            AND X.PROJECT_CODE  = B.PROJECT_CODE
                            AND X.ERP_FCST_TYPE = B.FCST_TYPE
                            AND X.EDI_INCOTERMS = B.INCOTERMS
                            AND X.DOM_EXP       = B.DOM_EXP
                            AND X.ITEM_ID       = B.ITEM_ID
                            AND NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')   = NVL(RTRIM(LTRIM(B.UNLOADING_POINT)), ' ')
                            AND NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')    = NVL(RTRIM(LTRIM(B.CUSTOMER_PLANT)), ' ')
                            AND NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') = NVL(RTRIM(LTRIM(B.CUSTOMER_ITEM_ID)), ' ')
                         WHERE 1 = 1
                           AND X.BASIS_YYYYMMDD >= B.VALID_START_DATE
                           AND X.BASIS_YYYYMMDD <= B.VALID_END_DATE
                           AND B.ITEM_ID IS NOT NULL;
                    END;
                END;

                BEGIN
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI 및 하위 MEASURE 생성 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder')  /* CUST_fcst는 제외 */
                       AND YYYYMMDD >= V_TODAY
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ALL X
                                     WHERE DM_PLN_MKT_FCST.DIVISION_ID  = X.DIVISION_ID
                                       AND DM_PLN_MKT_FCST.DOM_EXP      = 'E'
                                       AND DM_PLN_MKT_FCST.ATTRIBUTE5   = X.SENDER_NAME
                                       AND X.BASIS_YYYYMMDD             >= V_TODAY   /* 금일 20240105 당주월요일이후 */
                                  );

                /* 날짜 중복데이터는 SUM한 값으로 입력 */
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4    /* SENDER_CODE 값 저장 */
                        , ATTRIBUTE5    /* SENDER_NAME 값 저장 */
                        , ATTRIBUTE6    /* IFSEQNO 값 저장 */
                        , ATTRIBUTE7    /* LEADTIME 적용전 ORIGINAL YYYYMMDD 값 저장 */
                        , ATTRIBUTE8    /* EDI_LT 값 저장 */
                        , ATTRIBUTE9    /* CREATE_DATE 값 저장 */
                        , ATTRIBUTE10)  /* 소급적용여부 */
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE                            AS FCST_TYPE
                         , A.EDI_INCOTERMS                            AS INCOTERMS
                         , 'CUST_FCST_EDI'                            AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                           AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))    AS QTY
                         , 'EDI'
                         , SYSDATE
                         , 'EDI'
                         , SYSDATE
                         , MAX(A.SENDER_CODE)                         AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                         AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                             AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                            AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                              AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                         AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                       AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(A.SALES_PLANT_SITE_ID, '-'), A.BASIS_YYYYMMDD;
                END;

                /* MEASURE별 SUM한 값으로 생성 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE
                         , A.EDI_INCOTERMS
                         , CASE WHEN A.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast'
                                WHEN A.SCHEDULING_TYPE = '10' THEN 'Immidiate'
                                WHEN A.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement'
                                WHEN A.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp'
                                WHEN A.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp'
                                WHEN A.SCHEDULING_TYPE = '3'  THEN 'Material_Temp'
                                WHEN A.SCHEDULING_TYPE = '83' THEN 'Backorder'
                           END                                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))
                         , 'EDI'
                         , SYSDATE
                         , 'EDI'
                         , SYSDATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , A.SCHEDULING_TYPE, NVL(A.SALES_PLANT_SITE_ID, '-'), A.BASIS_YYYYMMDD;
                END;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI 및 하위 MEASURE 생성 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* [E20241126-000426]_Cust.FCST(P+P) Measure 로직 수정 START */
                /* 프로시져를 호출하여, CUST_FCST 메져 데이터를 생성한다 */
                DELETE FROM GT_DDECM_CUST_FCST_DIVISION;

                INSERT INTO GT_DDECM_CUST_FCST_DIVISION (DIVISION_ID, SEQ)
                SELECT DIVISION_ID
                     , ROW_NUMBER() OVER (ORDER BY DIVISION_ID) - 1  AS SEQ
                  FROM (SELECT DISTINCT DIVISION_ID FROM GT_DDECM_EDI_MKT_FCST);

                SELECT NVL(MAX(SEQ), -1) INTO V_CUST_FCST_CNT FROM GT_DDECM_CUST_FCST_DIVISION;
                V_CUST_FCST_I        := 0;
                V_CUST_FCST_DIVISION := NULL;

                WHILE V_CUST_FCST_I <= V_CUST_FCST_CNT LOOP
                    SELECT DIVISION_ID INTO V_CUST_FCST_DIVISION
                      FROM GT_DDECM_CUST_FCST_DIVISION
                     WHERE SEQ = V_CUST_FCST_I;

                    /* DIVISION 단위로 생성 (CUST_FCST = CUST_FCST_EDI + RPA + EXCEL) */
                    PR_DM_PLN_MKT_FCST_MAKE_CUST_FCST(V_CUST_FCST_DIVISION);   /* > 81, 81_UC */
                    V_CUST_FCST_I := V_CUST_FCST_I + 1;
                END LOOP;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST_H
                        (DIVISION_ID, HISTORY_SEQ, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT B.DIVISION_ID
                         , SEQ1_DM_PLN_MKT_FCST_H.NEXTVAL   /* History Seqno */
                         , B.PROJECT_CODE
                         , B.SCM_SITE_ID
                         , B.ITEM_ID
                         , B.DOM_EXP
                         , FCST_TYPE
                         , INCOTERMS
                         , MEASURE
                         , PLANT_SITE_ID
                         , B.BASIS_YYYYMMDD
                         , TO_NUMBER(REPLACE(B.QTY, ',', ''))
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE
                         , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                      FROM DM_PLN_MKT_FCST A
                      INNER JOIN GT_DDECM_EDI_MKT_FCST B
                        ON  A.DIVISION_ID  = B.DIVISION_ID
                        AND A.PROJECT_CODE = B.PROJECT_CODE
                        AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                        AND A.ITEM_ID      = B.ITEM_ID
                        AND A.MEASURE      = CASE WHEN B.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast'
                                                  WHEN B.SCHEDULING_TYPE = '10' THEN 'Immidiate'
                                                  WHEN B.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement'
                                                  WHEN B.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '3'  THEN 'Material_Temp'
                                                  WHEN B.SCHEDULING_TYPE = '83' THEN 'Backorder'
                                             END
                        AND A.PLANT_SITE_ID = B.SALES_PLANT_SITE_ID
                        AND A.YYYYMMDD      = B.BASIS_YYYYMMDD
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST
                                     WHERE BASIS_YYYYMMDD >= V_TODAY   /* 금일 20240105 */
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) C
                        ON  A.DIVISION_ID     = C.DIVISION_ID
                        AND B.PROJECT_CODE    = C.PROJECT_CODE
                        AND B.SCM_SITE_ID     = C.SCM_SITE_ID
                        AND B.ITEM_ID         = C.ITEM_ID
                        AND B.DOM_EXP         = C.DOM_EXP
                        AND B.ERP_FCST_TYPE   = C.ERP_FCST_TYPE
                        AND B.UNLOADING_POINT = C.UNLOADING_POINT
                        AND B.CUSTOMER_PLANT  = C.CUSTOMER_PLANT
                        AND B.EDI_INCOTERMS   = C.EDI_INCOTERMS
                        AND NVL(B.SALES_PLANT_SITE_ID, ' ') = NVL(C.SALES_PLANT_SITE_ID, ' ')
                        AND B.CREATE_DATE     = C.CREATE_DATE
                        AND B.BASIS_YYYYMMDD  = C.BASIS_YYYYMMDD
                     WHERE 1 = 1
                       AND A.YYYYMMDD >= V_TODAY   /* 금일 20240105 W1월요일이후 */
                       AND A.MEASURE IN ('CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder');
                END;
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

            END;

        END;

        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        /* CUST_FCST_EDI[Org.] START */
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        BEGIN
            /* 테이블중복제거 / 임시확인용테이블 중복제거 */
            DELETE FROM GT_DDECM_EDI_END_CUSTOMER_ORG;

            /* EDI END_CUSTOMER별 기간 설정 */
            BEGIN
                /* EDI_END_CUSTOMER_ORG Lookup의 Active = 'Off'이면 CREATE_DATE -52주부터, 'On'이면 Lookup 기간 사용 */
                /* ORG Lookup의 Active가 'On'이면 Lookup기간중 EDI 데이터 미수신시 수량 0으로 변경 */
                INSERT INTO GT_DDECM_EDI_END_CUSTOMER_ORG
                    (DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, FROM_WEEK, FROM_DAY, TO_WEEK, TO_DAY, ACTIVE)
                SELECT A.DIVISION_ID                                       AS DIVISION_ID
                     , A.END_CUSTOMER                                      AS END_CUSTOMER
                     , NVL(NULLIF(RTRIM(B.SEGMENT4),''), '/')                                AS SCM_SITE_ID
                     , CASE WHEN NVL(B.SEGMENT5, 'On') = 'On' THEN NVL(B.ATTRIBUTE1, '-1')
                            ELSE '-52'
                       END                                                 AS FROM_WEEK
                     , NVL(B.ATTRIBUTE2, 'TUE')                            AS FROM_DAY
                     , NVL(B.ATTRIBUTE3, '0')                              AS TO_WEEK
                     , NVL(B.ATTRIBUTE4, 'MON')                            AS TO_DAY
                     , NVL(B.SEGMENT5, 'On')                               AS ACTIVE
                  FROM SCM_MST_SITE A
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B
                    ON  B.LOOKUP_TYPE  = 'EDI_END_CUSTOMER_ORG'
                    AND A.DIVISION_ID  = B.SEGMENT1
                    AND A.END_CUSTOMER = B.SEGMENT2
                    AND B.VALID_YN     = 'Y'
                 WHERE A.END_CUSTOMER IS NOT NULL
                 GROUP BY A.DIVISION_ID, A.END_CUSTOMER, B.SEGMENT4, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3, B.ATTRIBUTE4, B.SEGMENT5;
            END;

            BEGIN
                /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                DELETE FROM GT_DDECM_EDI_ORG_ALL;

                /* EDI STATUS_CODE가 SUCCESS인 DATA */
                BEGIN
                    /* SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, ITEM_ID, SCHEDULING 기준으로 DATA 추출 */
                    INSERT INTO GT_DDECM_EDI_ORG_ALL
                        (NUM, DIVISION_ID, IFSEQNO, SOLDTO_CODE, SHIPTO_CODE, UNLOADING_POINT, CUSTOMER_PLANT, SCHEDULING_TYPE
                        , PROJECT_CODE, SCM_SITE_ID, ITEM_ID, ERP_FCST_TYPE, CREATE_DATE, CREATE_TIME, MESSAGE_TYPE, END_CUSTOMER, SENDER_NAME, YYYYMMDD)
                    SELECT ROW_NUMBER() OVER (ORDER BY A.IFSEQNO)          AS NUM
                         , A.DIVISION_ID
                         , A.IFSEQNO
                         , A.SOLDTO_CODE
                         , A.SHIPTO_CODE
                         , A.UNLOADING_POINT
                         , A.CUSTOMER_PLANT
                         , A.SCHEDULING_TYPE
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.ERP_FCST_TYPE
                         , A.CREATE_DATE
                         , A.CREATE_TIME
                         , A.MESSAGE_TYPE
                         , A.END_CUSTOMER
                         , A.SENDER_NAME
                         , A.YYYYMMDD
                      FROM (
                            SELECT ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCHEDULING_TYPE, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                                                                 , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                                      ORDER BY A.CREATE_DATE DESC, A.IFSEQNO DESC)   AS RNK
                                 , A.DIVISION_ID
                                 , A.IFSEQNO
                                 , A.SOLDTO_CODE
                                 , A.SHIPTO_CODE
                                 , A.UNLOADING_POINT
                                 , A.CUSTOMER_PLANT
                                 , A.SCHEDULING_TYPE
                                 , A.PROJECT_CODE
                                 , A.SCM_SITE_ID
                                 , A.ITEM_ID
                                 , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END         AS ERP_FCST_TYPE
                                 , A.CREATE_DATE
                                 , A.CREATE_TIME
                                 , A.MESSAGE_TYPE
                                 , B.END_CUSTOMER
                                 , A.SENDER_NAME
                                 , A.YYYYMMDD
                              FROM DM_DNM_EDI_CALLOFF_ITEM A
                              LEFT OUTER JOIN SCM_MST_SITE B
                                ON  A.DIVISION_ID = B.DIVISION_ID
                                AND A.SCM_SITE_ID = B.SCM_SITE_ID
                                AND B.SITE_TYPE   = 'SALES'
                                AND B.VALID_YN    = 'Y'
                                AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                              LEFT OUTER JOIN LATERAL (SELECT C1.*
                                             FROM GT_DDECM_EDI_END_CUSTOMER_ORG C1
                                            WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                              AND C1.END_CUSTOMER = B.END_CUSTOMER
                                              AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                           FROM GT_DDECM_EDI_END_CUSTOMER_ORG X99
                                                                          WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                            AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                            AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                             WHERE 1 = 1
                               AND A.CREATE_DATE >= V_FROM_YYYYMMDD
                               AND A.YYYYMMDD    >= V_TODAY   /* 당일 이후 */
/*
   [원본 보존] 아래 CALENDAR 기반 CREATE_DATE 시작/종료일 산출 블록은 원본 MSSQL에서 주석처리되어 비활성 상태임.
   AND A.CREATE_DATE >= (
       SELECT BASIS_YYYYMMDD
       FROM (
             SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 2 THEN TO_CHAR(SYSDATE-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE-2,'YYYYMMDD') ELSE TO_CHAR(SYSDATE,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.FROM_DAY
            ) D
       WHERE D.RK = C.FROM_WEEK
   )
   AND A.CREATE_DATE <= (
       SELECT BASIS_YYYYMMDD
       FROM (
             SELECT (CASE WHEN DAYOFWEEK = 'SUN' THEN RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 2
                          ELSE RANK() OVER (ORDER BY BASIS_YYYYMMDD) - 1 END) AS RK, DT.BASIS_YYYYMMDD
             FROM   SCM_SYS_CALENDAR_M DT
             WHERE  BASIS_YYYYMMDD >= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 2 THEN TO_CHAR(SYSDATE-1,'YYYYMMDD')
                                            WHEN TO_NUMBER(TO_CHAR(SYSDATE,'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE-2,'YYYYMMDD') ELSE TO_CHAR(SYSDATE,'YYYYMMDD') END)
             AND    DAYOFWEEK = C.TO_DAY
            ) D
       WHERE D.RK = C.TO_WEEK
   )
*/
                               AND A.STATUS_CODE = 'S'
                               AND EXISTS (
                                            SELECT *
                                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL LUP
                                             WHERE LUP.LOOKUP_TYPE = 'DM_EDI_CALLOFF_MKT_FCST_END_CUSTOMER'
                                               AND LUP.SEGMENT1    = A.DIVISION_ID
                                               AND LUP.SEGMENT2    = A.SENDER_NAME
                                               AND LUP.SEGMENT3    = B.END_CUSTOMER
                                               AND LUP.SEGMENT4    = A.SCHEDULING_TYPE
                                               AND A.MESSAGE_TYPE  = CASE WHEN LUP.SEGMENT5 IN ('DELJIT', 'DELFOR') THEN LUP.SEGMENT5   /* DELJIT / DELFOR로 정의되어 있으면. 정의된 데이터만 추출함. */
                                                                          ELSE (CASE WHEN A.YYYYMMDD <= V_YYYYMMDD THEN 'DELJIT' ELSE 'DELFOR' END)
                                                                     END
                                               AND LUP.VALID_YN = 'Y'
                                               AND ((LENGTH(LUP.ATTRIBUTE2) < 8 AND LENGTH(LUP.ATTRIBUTE3) < 8) OR (A.YYYYMMDD BETWEEN LUP.ATTRIBUTE1 AND LUP.ATTRIBUTE2))
                                          )
                             GROUP BY A.DIVISION_ID
                                    , A.IFSEQNO
                                    , A.SOLDTO_CODE
                                    , A.SHIPTO_CODE
                                    , A.UNLOADING_POINT
                                    , A.CUSTOMER_PLANT
                                    , A.SCHEDULING_TYPE
                                    , A.PROJECT_CODE
                                    , A.SCM_SITE_ID
                                    , A.ITEM_ID
                                    , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END
                                    , A.CREATE_DATE
                                    , A.CREATE_TIME
                                    , A.MESSAGE_TYPE
                                    , B.END_CUSTOMER
                                    , A.SENDER_NAME
                                    , A.YYYYMMDD
                           ) A
                     WHERE RNK = 1
                       AND LENGTH(A.YYYYMMDD) = 8    /* 강현준 추가 ('444444' 가 추가되어 있음 */
                     ORDER BY A.IFSEQNO;
                END;

                /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                DELETE FROM GT_DDECM_EDI_MKT_FCST_ORG;

                /* 기존 로직: 전체 대상 추출 ,삭제를 위한 자료 추출(고객수요 N:N Mapping 적용전 전체) */
                DELETE FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL;

                SELECT COUNT(*) INTO V_CNT_ORG FROM GT_DDECM_EDI_ORG_ALL;

                IF V_CNT_ORG > 0 THEN

                    INSERT INTO GT_DDECM_EDI_MKT_FCST_ORG_ALL
                        (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                        , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                        , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                        , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, CREATE_TIME, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                    SELECT X1.EDI_IF_SEQ, X1.SUB_NO, X1.YYYYMMDD
                         , X1.DIVISION_ID, X1.SCM_SITE_ID, X1.ITEM_ID, X1.PROJECT_CODE
                         , CASE WHEN X1.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END              AS ERP_FCST_TYPE
                         , X1.BASIS_YYYYMMDD, X1.QTY, X1.EDI_INCOTERMS, X1.SALES_PLANT_SITE_ID
                         , 'E'                                                                     AS DOM_EXP
                         , X1.COMPANY_ID, X1.SOLDTO_CODE, X1.SHIPTO_CODE
                         , X1.DOC_IDENTIFINER, X1.MESSAGE_TYPE
                         , NVL(RTRIM(LTRIM(X1.UNLOADING_POINT)), ' ')                              AS UNLOADING_POINT
                         , NVL(RTRIM(LTRIM(X1.CUSTOMER_PLANT)), ' ')                               AS CUSTOMER_PLANT
                         , X1.RDD_START, X1.RDD_END
                         , X1.IFSEQNO
                         , X1.SCHEDULING_TYPE
                         , CASE WHEN (X1.MESSAGE_TYPE = 'DELFOR' AND X1.SOLDTO_CODE = 'FR000064' AND X1.RDD_START <> X1.RDD_END AND X1.RDD_START >= V_1WEEK_MONDAY) THEN 'Periodic DELFOR'
                                ELSE NULL
                           END                                                                    AS DELFOR_TYPE
                         , X1.EDI_LT
                         , NVL(RTRIM(LTRIM(X1.CUST_MATERIAL_CODE)), ' ')                           AS CUST_MATERIAL_CODE
                         , X1.CREATE_DATE
                         , X1.CREATE_TIME
                         , X1.SENDER_CODE
                         , X1.SENDER_NAME
                         , X1.ATTRIBUTE10
                      FROM DM_DNM_EDI_CALLOFF_ITEM X1
                      INNER JOIN GT_DDECM_EDI_ORG_ALL X2
                        ON  X1.IFSEQNO         = X2.IFSEQNO
                        AND X1.SOLDTO_CODE     = X2.SOLDTO_CODE
                        AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                        AND X1.SCHEDULING_TYPE = X2.SCHEDULING_TYPE
                        AND X1.PROJECT_CODE    = X2.PROJECT_CODE
                        AND X1.SCM_SITE_ID     = X2.SCM_SITE_ID
                        AND X1.ITEM_ID         = X2.ITEM_ID
                        AND X1.SENDER_NAME     = X2.SENDER_NAME
                        AND X1.CREATE_DATE     = X2.CREATE_DATE
                        AND X1.CREATE_TIME     = X2.CREATE_TIME
                        AND X1.SHIPTO_CODE     = X2.SHIPTO_CODE
                     WHERE 1 = 1
                       AND X1.STATUS_CODE = 'S'
                       AND TO_NUMBER(REPLACE(NVL(X1.QTY, '0'), ',', '')) <> 0
                       AND NVL(X1.EXCEPTION_FLAG, 'N') != 'Y';

                    /*
                       2024.04.29    kcw3408       고객수요 N:N Mapping
                       전체 대생 추출후 N:N Model Mapping 작업
                        .집계 시점에 Cust Item/Unloading Point/Plant 반영
                        .Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음
                        . GT_DDECM_EDI_MKT_FCST_ORG: 최종 결과,insert 작업
                    */
                    INSERT INTO GT_DDECM_EDI_MKT_FCST_ORG
                        (EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, ERP_FCST_TYPE
                        , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP, COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE
                        , DOC_IDENTIFINER, MESSAGE_TYPE, UNLOADING_POINT, CUSTOMER_PLANT, RDD_START, RDD_END, IFSEQNO
                        , SCHEDULING_TYPE, DELFOR_TYPE, EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, SENDER_CODE, SENDER_NAME, CHANGE_STATUS)
                    SELECT X.EDI_IF_SEQ
                         , X.SUB_NO
                         , X.YYYYMMDD
                         , X.DIVISION_ID
                         , X.SCM_SITE_ID
                         , B.ITEM_ID
                         , X.PROJECT_CODE
                         , X.ERP_FCST_TYPE
                         , X.BASIS_YYYYMMDD
                         , X.QTY
                         , X.EDI_INCOTERMS
                         , X.SALES_PLANT_SITE_ID
                         , X.DOM_EXP
                         , X.COMPANY_ID
                         , X.SOLDTO_CODE
                         , X.SHIPTO_CODE
                         , X.DOC_IDENTIFINER
                         , X.MESSAGE_TYPE
                         , NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')  AS UNLOADING_POINT
                         , NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')   AS CUSTOMER_PLANT
                         , X.RDD_START
                         , X.RDD_END
                         , X.IFSEQNO
                         , X.SCHEDULING_TYPE
                         , X.DELFOR_TYPE
                         , X.EDI_LT
                         , NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') AS CUST_MATERIAL_CODE
                         , X.CREATE_DATE
                         , X.SENDER_CODE
                         , X.SENDER_NAME
                         , X.CHANGE_STATUS
                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                      JOIN GT_DDECM_DM_CUST_MODEL_MAPPING B
                        ON  X.DIVISION_ID   = B.DIVISION_ID
                        AND X.SCM_SITE_ID   = B.SCM_SITE_ID
                        AND X.PROJECT_CODE  = B.PROJECT_CODE
                        AND X.ERP_FCST_TYPE = B.FCST_TYPE
                        AND X.EDI_INCOTERMS = B.INCOTERMS
                        AND X.DOM_EXP       = B.DOM_EXP
                        AND X.ITEM_ID       = B.ITEM_ID
                        AND NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), ' ')   = NVL(RTRIM(LTRIM(B.UNLOADING_POINT)), ' ')
                        AND NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')    = NVL(RTRIM(LTRIM(B.CUSTOMER_PLANT)), ' ')
                        AND NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') = NVL(RTRIM(LTRIM(B.CUSTOMER_ITEM_ID)), ' ')
                     WHERE 1 = 1
                       AND X.BASIS_YYYYMMDD >= B.VALID_START_DATE
                       AND X.BASIS_YYYYMMDD <= B.VALID_END_DATE
                       AND B.ITEM_ID IS NOT NULL;

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD < V_0WEEK_MONDAY   /* 당주월요일이전 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                     WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                       AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                       AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                       AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                       AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                       AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                       AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                       AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD >= V_0WEEK_MONDAY   /* 금주월요일이후 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG_ALL X
                                     WHERE DM_PLN_MKT_FCST.DIVISION_ID = X.DIVISION_ID
                                       AND DM_PLN_MKT_FCST.ATTRIBUTE5  = X.SENDER_NAME
                                       AND DM_PLN_MKT_FCST.DOM_EXP     = 'E'
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD < V_0WEEK_MONDAY   /* 당주월요일이전 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                     WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                       AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                       AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                       AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                       AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                       AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                       AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                       AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                  );

                    DELETE FROM DM_PLN_MKT_FCST
                     WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND YYYYMMDD >= V_0WEEK_MONDAY   /* 금주월요일이후 */
                       AND YYYYMMDD >= (
                                        SELECT MIN(X.BASIS_YYYYMMDD)
                                          FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                         WHERE DM_PLN_MKT_FCST.SCM_SITE_ID    = X.SCM_SITE_ID
                                           AND DM_PLN_MKT_FCST.ITEM_ID        = X.ITEM_ID
                                           AND DM_PLN_MKT_FCST.PROJECT_CODE   = X.PROJECT_CODE
                                           AND DM_PLN_MKT_FCST.FCST_TYPE      = X.ERP_FCST_TYPE
                                           AND DM_PLN_MKT_FCST.INCOTERMS      = X.EDI_INCOTERMS
                                           AND DM_PLN_MKT_FCST.PLANT_SITE_ID  = CASE WHEN X.DIVISION_ID = '81' THEN X.SALES_PLANT_SITE_ID ELSE DM_PLN_MKT_FCST.PLANT_SITE_ID END
                                           AND DM_PLN_MKT_FCST.DOM_EXP        = 'E'
                                           AND DM_PLN_MKT_FCST.DIVISION_ID    = X.DIVISION_ID
                                       )
                       AND EXISTS (
                                    SELECT X.PROJECT_CODE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG X
                                  );
                END IF;

                /* 날짜 중복데이터는 SUM한 값으로 입력 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                         , A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , 'CUST_FCST_EDI_ORG'                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                          AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))   AS QTY
                         , 'EDI'                                     AS CREATED_BY
                         , SYSDATE                                   AS CREATION_DATE
                         , 'EDI'                                     AS LAST_UPDATED_BY
                         , SYSDATE                                   AS LAST_UPDATE_DATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST_ORG A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE 1 = 1
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(A.SALES_PLANT_SITE_ID, '-'), A.BASIS_YYYYMMDD;
                END;

                /* MEASURE별 SUM한 값으로 생성 */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST
                        (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT A.DIVISION_ID
                         , A.PROJECT_CODE
                         , A.SCM_SITE_ID
                         , A.ITEM_ID
                         , A.DOM_EXP
                         , A.ERP_FCST_TYPE
                         , A.EDI_INCOTERMS
                         , CASE WHEN A.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '3'  THEN 'Material_Temp[Org.]'
                                WHEN A.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast[Org.]'
                                WHEN A.SCHEDULING_TYPE = '10' THEN 'Immidiate[Org.]'
                                WHEN A.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement[Org.]'
                                WHEN A.SCHEDULING_TYPE = '83' THEN 'Backorder[Org.]'
                           END                                       AS MEASURE
                         , NVL(NULLIF(RTRIM(A.SALES_PLANT_SITE_ID),''), '/')           AS PLANT_SITE_ID
                         , A.BASIS_YYYYMMDD                          AS YYYYMMDD
                         , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))   AS QTY
                         , 'EDI'                                     AS CREATED_BY
                         , SYSDATE                                   AS CREATION_DATE
                         , 'EDI'                                     AS LAST_UPDATED_BY
                         , SYSDATE                                   AS LAST_UPDATE_DATE
                         , MAX(A.SENDER_CODE)                        AS ATTRIBUTE4
                         , MAX(A.SENDER_NAME)                        AS ATTRIBUTE5
                         , MAX(A.IFSEQNO)                            AS ATTRIBUTE6
                         , MAX(A.YYYYMMDD)                           AS ATTRIBUTE7
                         , MAX(A.EDI_LT)                             AS ATTRIBUTE8
                         , MAX(A.CREATE_DATE)                        AS ATTRIBUTE9
                         , MAX(A.CHANGE_STATUS)                      AS ATTRIBUTE10
                      FROM GT_DDECM_EDI_MKT_FCST_ORG A
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE 1 = 1
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, SCHEDULING_TYPE, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) B
                        ON  A.DIVISION_ID     = B.DIVISION_ID
                        AND A.PROJECT_CODE    = B.PROJECT_CODE
                        AND A.SCM_SITE_ID     = B.SCM_SITE_ID
                        AND A.ITEM_ID         = B.ITEM_ID
                        AND A.SCHEDULING_TYPE = B.SCHEDULING_TYPE
                        AND A.DOM_EXP         = B.DOM_EXP
                        AND A.ERP_FCST_TYPE   = B.ERP_FCST_TYPE
                        AND A.UNLOADING_POINT = B.UNLOADING_POINT
                        AND A.CUSTOMER_PLANT  = B.CUSTOMER_PLANT
                        AND A.EDI_INCOTERMS   = B.EDI_INCOTERMS
                        AND NVL(A.SALES_PLANT_SITE_ID, ' ') = NVL(B.SALES_PLANT_SITE_ID, ' ')
                        AND A.CREATE_DATE     = B.CREATE_DATE
                        AND A.BASIS_YYYYMMDD  = B.BASIS_YYYYMMDD
                     WHERE 1 = 1
                     GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.SCHEDULING_TYPE, A.DOM_EXP, A.ERP_FCST_TYPE, A.EDI_INCOTERMS
                         , NVL(A.SALES_PLANT_SITE_ID, '-'), A.BASIS_YYYYMMDD;
                END;

                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* CUST_FCST_EDI_ORG 및 하위 MEASURE 생성 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (BEGIN) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                BEGIN
                    INSERT INTO DM_PLN_MKT_FCST_H
                        (DIVISION_ID, HISTORY_SEQ, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                    SELECT B.DIVISION_ID
                         , SEQ1_DM_PLN_MKT_FCST_H.NEXTVAL   /* History Seqno */
                         , B.PROJECT_CODE
                         , B.SCM_SITE_ID
                         , B.ITEM_ID
                         , B.DOM_EXP
                         , FCST_TYPE
                         , INCOTERMS
                         , MEASURE
                         , PLANT_SITE_ID
                         , B.BASIS_YYYYMMDD
                         , TO_NUMBER(REPLACE(B.QTY, ',', ''))
                         , CREATED_BY
                         , CREATION_DATE
                         , LAST_UPDATED_BY
                         , LAST_UPDATE_DATE
                         , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
                      FROM DM_PLN_MKT_FCST A
                      INNER JOIN GT_DDECM_EDI_MKT_FCST_ORG B
                        ON  A.DIVISION_ID  = B.DIVISION_ID
                        AND A.PROJECT_CODE = B.PROJECT_CODE
                        AND A.SCM_SITE_ID  = B.SCM_SITE_ID
                        AND A.ITEM_ID      = B.ITEM_ID
                        AND A.YYYYMMDD     = B.BASIS_YYYYMMDD
                      INNER JOIN (
                                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' ')  AS SALES_PLANT_SITE_ID
                                         , BASIS_YYYYMMDD, CREATE_DATE
                                      FROM GT_DDECM_EDI_MKT_FCST_ORG
                                     WHERE BASIS_YYYYMMDD >= V_0WEEK_MONDAY
                                     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, ERP_FCST_TYPE
                                         , UNLOADING_POINT, CUSTOMER_PLANT, EDI_INCOTERMS
                                         , NVL(SALES_PLANT_SITE_ID, ' '), BASIS_YYYYMMDD, CREATE_DATE
                                 ) C
                        ON  A.DIVISION_ID     = C.DIVISION_ID
                        AND B.PROJECT_CODE    = C.PROJECT_CODE
                        AND B.SCM_SITE_ID     = C.SCM_SITE_ID
                        AND B.ITEM_ID         = C.ITEM_ID
                        AND B.DOM_EXP         = C.DOM_EXP
                        AND B.ERP_FCST_TYPE   = C.ERP_FCST_TYPE
                        AND B.UNLOADING_POINT = C.UNLOADING_POINT
                        AND B.CUSTOMER_PLANT  = C.CUSTOMER_PLANT
                        AND B.EDI_INCOTERMS   = C.EDI_INCOTERMS
                        AND NVL(B.SALES_PLANT_SITE_ID, ' ') = NVL(C.SALES_PLANT_SITE_ID, ' ')
                        AND B.CREATE_DATE     = C.CREATE_DATE
                        AND B.BASIS_YYYYMMDD  = C.BASIS_YYYYMMDD
                     WHERE 1 = 1
                       AND A.MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]');
                END;
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
                /* History 기능 추가 (END) */
                /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

                /* EDI 데이터 LOOKUP FROM 기간 이후 데이터 미전송시 MKT_FCST 기존 수량을 전부 0으로 변경 START */
                BEGIN
                    /* 테이블중복제거 / 임시확인용테이블 중복제거 */
                    DELETE FROM GT_DDECM_MKT_ORG_DATA;

                    /* MKT_FCST 데이터 생성일 체크 */
                    BEGIN
                        /* LOOKUP적용 */
                        INSERT INTO GT_DDECM_MKT_ORG_DATA
                            (DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID)
                        SELECT A.DIVISION_ID
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , A.PLANT_SITE_ID
                          FROM (
                                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID
                                     , MAX(ATTRIBUTE6) AS IFSEQNO
                                     , MAX(ATTRIBUTE9) AS CREATE_DATE
                                  FROM DM_PLN_MKT_FCST
                                 WHERE MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                                   AND QTY <> 0
                                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, PLANT_SITE_ID
                               ) A
                          LEFT OUTER JOIN SCM_MST_SITE B
                            ON  A.DIVISION_ID = B.DIVISION_ID
                            AND A.SCM_SITE_ID = B.SCM_SITE_ID
                            AND B.SITE_TYPE   = 'SALES'
                            AND B.VALID_YN    = 'Y'
                            AND REPLACE(B.END_CUSTOMER, '-', '') IS NOT NULL
                          LEFT OUTER JOIN LATERAL (SELECT C1.*
                                         FROM GT_DDECM_EDI_END_CUSTOMER_ORG C1
                                        WHERE A.DIVISION_ID  = C1.DIVISION_ID
                                          AND C1.END_CUSTOMER = B.END_CUSTOMER
                                          AND C1.SCM_SITE_ID  = NVL((SELECT X99.SCM_SITE_ID
                                                                       FROM GT_DDECM_EDI_END_CUSTOMER_ORG X99
                                                                      WHERE X99.DIVISION_ID  = A.DIVISION_ID
                                                                        AND X99.END_CUSTOMER = B.END_CUSTOMER
                                                                        AND X99.SCM_SITE_ID  = A.SCM_SITE_ID), '/')) C ON (1 = 1)
                         WHERE A.CREATE_DATE < (
                                SELECT BASIS_YYYYMMDD
                                  FROM (
                                        SELECT RANK() OVER (ORDER BY BASIS_YYYYMMDD DESC) * -1 AS RK, DT.BASIS_YYYYMMDD
                                          FROM SCM_SYS_CALENDAR_M DT
                                         WHERE BASIS_YYYYMMDD <= (CASE WHEN TO_NUMBER(TO_CHAR(SYSDATE, 'D')) = 2 THEN TO_CHAR(SYSDATE - 1, 'YYYYMMDD')
                                                                       WHEN TO_NUMBER(TO_CHAR(SYSDATE, 'D')) = 3 THEN (CASE WHEN V_HOUR < '05' THEN TO_CHAR(SYSDATE - 2, 'YYYYMMDD') ELSE TO_CHAR(SYSDATE, 'YYYYMMDD') END)
                                                                       ELSE TO_CHAR(SYSDATE, 'YYYYMMDD')
                                                                  END)
                                           AND DAYOFWEEK = C.FROM_DAY
                                       ) D
                                 WHERE D.RK = C.FROM_WEEK
                              )
                           AND C.ACTIVE = 'On';
                    END;

                    UPDATE DM_PLN_MKT_FCST MK
                       SET QTY              = 0
                         , LAST_UPDATED_BY  = 'EDI'
                         , LAST_UPDATE_DATE = SYSDATE
                     WHERE EXISTS (
                                    SELECT 1
                                      FROM GT_DDECM_MKT_ORG_DATA ED
                                     WHERE MK.DIVISION_ID   = ED.DIVISION_ID
                                       AND MK.PROJECT_CODE  = ED.PROJECT_CODE
                                       AND MK.SCM_SITE_ID   = ED.SCM_SITE_ID
                                       AND MK.ITEM_ID       = ED.ITEM_ID
                                       AND MK.PLANT_SITE_ID = ED.PLANT_SITE_ID
                                  )
                       AND MK.MEASURE IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]')
                       AND MK.QTY <> 0;
                END;
                /* EDI 데이터 LOOKUP FROM 기간 이후 데이터 미전송시 MKT_FCST 기존 수량을 전부 0으로 변경 END */

            END;
        END;
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */
        /* CUST_FCST_EDI[Org.] END */
        /* ----------------------------------------------------------------------------------------------------------------------------------------------------------------- */

    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'CUST_FCST_EDI Insert';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                            , 'ERROR'
                            , 0
                            , SQLERRM
                            , NULL
                            , SYSDATE
                            , P_IN_PARA_DATA  => V_IN_PARA_DATA
                            , P_SQL_ERR_CODE  => SQLCODE
                            , P_SQL_ERR_MSG   => SQLERRM
                            , P_SQL_BACKTRACE => DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

        RAISE_APPLICATION_ERROR(-20001
                              , '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / BACKTRACE=' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE || ' / PARAMS=' || V_IN_PARA_DATA);
END;
/
SHOW ERRORS PROCEDURE PR_DM_DNM_EDI_CALLOFF_MKT_FCST
-- ##### END PROCEDURE PR_DM_DNM_EDI_CALLOFF_MKT_FCST

-- ##### START PROCEDURE PR_DM_PLN_CUST_FCST_RECORD
CREATE OR REPLACE PROCEDURE         "PR_DM_PLN_CUST_FCST_RECORD" 
( 
      P_DIVISION_ID   IN VARCHAR2   /* division_id 전달받음 */
    , P_ACCEPT_FLAG   IN VARCHAR2   /* 업무구분(EDI, RPA) */
)
/* ============================================================
 * Program ID   : PR_DM_PLN_CUST_FCST_RECORD
 * Description  : EDI, CUST_FCST 데이터 HISTORY에 저장
 * Program History
 *------------------------------------------------------------
 *   Date         In Charge     Description
 *------------------------------------------------------------
 * 2023.04.11    chano0612      EDI, CUST_FCST 데이터 HISTORY에 저장
 * 2024.03.18    kcw3408        아래 속도 개선(DBA 정기훈 부장)
 * 2024.04.30    kcw3408        N:N Model Mapping_적재 추가(집계 시점에 Cust Item/Unloading Point/Plant 고려,Valid Range 1~5에 포함되지 않는 구간은 Calloff 데이터를 집계하지 않음)
 * 2024.06.26    JSSBAE         [E20240620-001488]_SCM DM 고객수요분석- Cust Plant NULL인 데이터 처리로직 개선
 * 2025.01.20    KANG.H.J       [PJ2024-50647] 자동차사업부 고객 수요 분석 기능 개선
 * 2025.03.18    JSSBAE         [E20250313-001202]_Customer Forecast Upload 데이터 오류 수정
 * 2025.10.31    JSSBAE         [E20251016-001453]_ERP NN Mapping 데이터 반영 수행시간 단축 및 로그 보완
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 *------------------------------------------------------------
 * [아래1] 20240315
 *  1.쿼리수정 - IDX_DM_DNM_EDI_CALLOFF_ITEM_N01 힌트추가
 *    FROM  DM_DNM_EDI_CALLOFF_ITEM A WITH(NOLOCK, INDEX(IDX_DM_DNM_EDI_CALLOFF_ITEM_N01))
 *  2.DM_DNM_EDI_CALLOFF_ITEM 테이블에 IFSEQNO를 선두컬럼으로 하는 인덱스 추가 (IDX_DM_DNM_EDI_CALLOFF_ITEM_N02)
 *  3.DM_PLN_CUST_FCST_H 테이블에 EDI_IF_SEQ를 선두컬럼으로 하는 인덱스 추가 (IDX_DM_PLN_CUST_FCST_H_N01)
 *  4.DM_PLN_CUST_FCST_H에 LAST_UPDATE_DATE 선두컬럼으로 하는 인덱스 추가 및 조건절 수정 (IDX_DM_PLN_CUST_FCST_H_N02)
 *
 *    EXEC PR_DM_PLN_CUST_FCST_RECORD '81', 'EDI'
 *    EXEC PR_DM_PLN_CUST_FCST_RECORD '81_UC', 'EDI'
 *    EXEC PR_DM_PLN_CUST_FCST_RECORD '81', 'RPA'
 *    EXEC PR_DM_PLN_CUST_FCST_RECORD '40', 'RPA'
 * ============================================================ */
IS
    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME     VARCHAR2(150 CHAR) := 'PR_DM_PLN_CUST_FCST_RECORD';
    V_LOG_TYPE         VARCHAR2(30 CHAR);        /* START/END/ERROR/... */
    N_LOG_COUNT        NUMBER(10)         := 0;
    V_LOG_MESSAGE      VARCHAR2(1000 CHAR);
    V_DESCRIPTION      VARCHAR2(500 CHAR);
    D_EVENT_DATE       DATE;

    V_DIVISION_ID      VARCHAR2(30 CHAR);
    V_IFSEQNO_INSERT   VARCHAR2(30 CHAR);
    V_ACCEPT_FLAG      VARCHAR2(10 CHAR);

    V_0WEEK_MONDAY     VARCHAR2(8 CHAR);   /* W0 월요일 */
    V_1WEEK_MONDAY     VARCHAR2(8 CHAR);   /* W1 월요일 */

    V_FROM_DATE        VARCHAR2(8 CHAR);

    V_CNT              NUMBER(10) := 0;
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := 'Div: ' || P_DIVISION_ID || '_' || P_ACCEPT_FLAG;
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    V_LOG_MESSAGE := NULL;      /*-- 변수 재사용을 위하여 초기화해야함 --*/

    BEGIN

        V_FROM_DATE    := TO_CHAR(TRUNC(SYSDATE) - 1, 'YYYYMMDD');
        V_0WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(TRUNC(SYSDATE), 'MON') - 7, 'YYYYMMDD');   /* W0월요일 */
        V_1WEEK_MONDAY := TO_CHAR(FN_NEXT_DAY(TRUNC(SYSDATE), 'MON'), 'YYYYMMDD');

        V_DIVISION_ID  := P_DIVISION_ID;
        V_ACCEPT_FLAG  := P_ACCEPT_FLAG;

        /* ******************** EDI DATA 생성 START ******************** */
        IF V_ACCEPT_FLAG = 'EDI' THEN

            DBMS_OUTPUT.PUT_LINE('EDI_01:' || V_ACCEPT_FLAG || ' ' || TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24:MI:SS.FF3'));

            /* 테이블중복제거 (tempdb../dbo.. 이중 DROP 은 Oracle 대응없음 → GTT 시작 DELETE 초기화) */
            DELETE
              FROM GT_PRDM_EDI_ALL;

            /* EDI STATUS_CODE가 SUCCESS인 DATA */
            INSERT
              INTO GT_PRDM_EDI_ALL ( NUM, IFSEQNO )
            SELECT ROW_NUMBER() OVER(ORDER BY A.IFSEQNO) AS NUM
                 , A.IFSEQNO
              FROM DM_DNM_EDI_CALLOFF_ITEM         A
                 , SCM_ADM_LOOKUP_MASTER_DETAIL    B
             WHERE A.SENDER_CODE  = B.SEGMENT2(+)
               AND B.LOOKUP_TYPE(+) = 'EDI_SENDER_CODE'
               AND A.DIVISION_ID  = V_DIVISION_ID
               AND A.CREATE_DATE >= V_FROM_DATE
             GROUP BY A.IFSEQNO;

            DBMS_OUTPUT.PUT_LINE('EDI_02:' || V_ACCEPT_FLAG);

            SELECT COUNT(*)
              INTO V_CNT
              FROM GT_PRDM_EDI_ALL;
            DBMS_OUTPUT.PUT_LINE('EDI_04:' || V_CNT);

            IF V_CNT > 0 THEN

                /* 2024.03.19  kcw3408  DM 프로시저 속도개선: #TEMP_DM_MST_ITEM_SINGLE_V 테이블 변경 */
                DELETE
                  FROM GT_PRDM_DM_MST_ITEM_SINGLE_V;
                INSERT
                  INTO GT_PRDM_DM_MST_ITEM_SINGLE_V ( DIVISION_ID, ITEM_ID, ITEM_NAME, ITEM_TYPE )
                SELECT DISTINCT A.DIVISION_ID, A.ITEM_ID, A.ITEM_NAME, A.ITEM_TYPE
                  FROM (
                        SELECT T1.DIVISION_ID
                             , T1.ITEM_ID
                             , MAX(T1.ITEM_NAME)                                       AS ITEM_NAME   /* 해당 컬럼이 NULL인 경우가 잇으므로 하나로 통일 */
                             , CASE MIN( CASE WHEN T1.ITEM_TYPE = 'P' THEN 1           /* 타입이 사이트와 사업부, 법인에 따라 다양하게 존재 하므로 하나로 통일 */
                                              WHEN T1.ITEM_TYPE = 'H' THEN 2           /* 또한 가장 완성된 상태의 자재 타입을 판매한다고 가정, 해당 자재타입을 사용함 */
                                              WHEN T1.ITEM_TYPE = 'Q' THEN 3
                                              ELSE 4 END )
                                    WHEN 1 THEN 'P'
                                    WHEN 2 THEN 'H'
                                    WHEN 3 THEN 'Q'
                                    ELSE 'R'
                               END                                                    AS ITEM_TYPE
                          FROM SCM_MST_ITEM_SN T1
                         WHERE T1.DIVISION_ID = V_DIVISION_ID
                           AND T1.ACTIVE_FLAG = 'Y'
                         GROUP BY T1.DIVISION_ID, T1.ITEM_ID
                       ) A
                 WHERE A.DIVISION_ID = V_DIVISION_ID;

                DELETE
                  FROM GT_PRDM_SCM_MST_SITE;
                INSERT
--                  INTO GT_PRDM_SCM_MST_SITE ( DIVISION_ID, SCM_SITE_ID, END_CUSTOMER, SOLDTO_CUSTOMER, VMI_YN, DEPT_ID, COUNTRY, CITY )
--                SELECT DIVISION_ID, SCM_SITE_ID, END_CUSTOMER, SOLDTO_CUSTOMER, VMI_YN, DEPT_ID, COUNTRY, CITY
                  INTO GT_PRDM_SCM_MST_SITE ( DIVISION_ID, SCM_SITE_ID, END_CUSTOMER, SOLDTO_CUSTOMER, VMI_YN, COUNTRY, CITY )            -- 2026.09.03 AJS
                SELECT DIVISION_ID, SCM_SITE_ID, END_CUSTOMER, SOLDTO_CUSTOMER, VMI_YN, COUNTRY, CITY                                     -- 2026.09.03 AJS
                  FROM SCM_MST_SITE
                 WHERE SITE_TYPE = 'SALES'
                   AND VALID_YN = 'Y'
                   AND DIVISION_ID = V_DIVISION_ID;

                DELETE
                  FROM GT_PRDM_SCM_MST_SITE_ITEM;
                INSERT
--                  INTO GT_PRDM_SCM_MST_SITE_ITEM ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, CELL_PER_CAR, CELL_PER_MODULE, OWNER, ATTRIBUTE8 )
--                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, CELL_PER_CAR, CELL_PER_MODULE, OWNER, ATTRIBUTE8
                  INTO GT_PRDM_SCM_MST_SITE_ITEM ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, CELL_PER_CAR, CELL_PER_MODULE, OWNER, ATTRIBUTE8, DEPT_ID )   -- 2026.09.03 AJS
                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, CELL_PER_CAR, CELL_PER_MODULE, OWNER, ATTRIBUTE8, DEPT_ID                                 -- 2026.09.03 AJS
                  FROM SCM_MST_SITE_ITEM
                 WHERE VALID_YN = 'Y'
                   AND DIVISION_ID = V_DIVISION_ID;

                DELETE
                  FROM GT_PRDM_SCM_MST_PROJECT;
                INSERT
                  INTO GT_PRDM_SCM_MST_PROJECT ( DIVISION_ID, PROJECT_CODE, BIZ_TYPE, PROJECT_NAME, PROJECT_STATUS, PROJECT_OWNER )
                SELECT DIVISION_ID, PROJECT_CODE, BIZ_TYPE, PROJECT_NAME, PROJECT_STATUS, PROJECT_OWNER
                  FROM SCM_MST_PROJECT
                 WHERE DROP_YN = 'N'
                   AND DIVISION_ID = V_DIVISION_ID;

            END IF;

            /* [E20250313-001202]_Customer Forecast Upload 데이터 오류 수정 START
               한 SCM_SITE_ID기준으로 SOLDTO_CODE, SHIPTO_CODE가 다른건이 여러건 발생하여 MKT FCST와 동일한 형태로 수정 */
            DELETE
              FROM GT_PRDM_CUST_MODEL_MAP;
            INSERT
              INTO GT_PRDM_CUST_MODEL_MAP ( DIVISION_ID, END_CUSTOMER, SCM_SITE_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, ITEM_ID, MAPPING_ITEM_ID
                                          , UNLOADING_POINT, CUSTOMER_PLANT, CUSTOMER_ITEM_ID, VALID_START_DATE, VALID_END_DATE )
            SELECT DISTINCT
                   A.DIVISION_ID
                 , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                 , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                 , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), '/')
                 , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), '/')
                 , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), '/')
                 , MAX(A.VALID_START_DATE), MAX(A.VALID_END_DATE)
              FROM DM_CUST_MODEL_MAPPING_M A
             WHERE A.ACTIVE_YN = 'Y'
             GROUP BY A.DIVISION_ID
                 , A.END_CUSTOMER, A.SCM_SITE_ID, A.PROJECT_CODE
                 , A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.ITEM_ID, A.MAPPING_ITEM_ID
                 , NVL(RTRIM(LTRIM(A.UNLOADING_POINT)), '/')
                 , NVL(RTRIM(LTRIM(A.CUSTOMER_PLANT)), '/')
                 , NVL(RTRIM(LTRIM(A.CUSTOMER_ITEM_ID)), '/');
            /* [E20250313-001202]_Customer Forecast Upload 데이터 오류 수정 END */

            DBMS_OUTPUT.PUT_LINE('EDI_05:' || V_ACCEPT_FLAG);

            /* 테이블중복제거 (이중 DROP 무대응) */
            DELETE
              FROM GT_PRDM_EDI_CUST_FCST;
            DELETE
              FROM GT_PRDM_QTY_SUM;

            SELECT COUNT(*)
              INTO V_CNT
              FROM GT_PRDM_EDI_ALL;
            DBMS_OUTPUT.PUT_LINE('EDI_A:' || V_CNT);

            IF V_CNT > 0 THEN

                INSERT
                  INTO GT_PRDM_EDI_CUST_FCST (
                       EDI_IF_SEQ, SUB_NO, YYYYMMDD, DIVISION_ID, SCM_SITE_ID
                     , ITEM_ID, PROJECT_CODE
                     , ERP_FCST_TYPE
                     , BASIS_YYYYMMDD, QTY, EDI_INCOTERMS, SALES_PLANT_SITE_ID
                     , DOM_EXP
                     , COMPANY_ID, SOLDTO_CODE, SHIPTO_CODE, DOC_IDENTIFINER, MESSAGE_TYPE
                     , RDD_START, RDD_END, IFSEQNO, SCHEDULING_TYPE
                     , DELFOR_TYPE
                     , EDI_LT, CUST_MATERIAL_CODE, CREATE_DATE, SENDER_CODE, SENDER_NAME, CUSTOMER_PLANT, UNLOADING_POINT
                     , END_CUSTOMER
                     , NICK_NAME
                     , DEPT_NAME_KO
                     , TEAM_NAME_KO
                     , SOLDTO_CUSTOMER
                     , COUNTRY
                     , CITY, ITEM_NAME, ITEM_TYPE, OWNER, VMI_YN, BIZ_TYPE
                     , PROJECT_NAME, PROJECT_STATUS, PROJECT_OWNER
                     , CELL_PER_CAR, CELL_PER_MODULE
                     , MODULE_PER_CAR
                     , KWH_PER_CELL
                     , KWH_PER_MODULE
                     , KWH_PER_PACK )
                SELECT A.EDI_IF_SEQ, A.SUB_NO, A.YYYYMMDD, A.DIVISION_ID, A.SCM_SITE_ID
                     , A.ITEM_ID, A.PROJECT_CODE
                     , CASE WHEN A.ERP_FCST_TYPE = 'S' THEN 'SMC' ELSE 'MPS' END          AS ERP_FCST_TYPE
                     , A.BASIS_YYYYMMDD, A.QTY, A.EDI_INCOTERMS, A.SALES_PLANT_SITE_ID
                     , 'E'                                                                AS DOM_EXP
                     , A.COMPANY_ID, A.SOLDTO_CODE, A.SHIPTO_CODE, A.DOC_IDENTIFINER, A.MESSAGE_TYPE
                     , A.RDD_START, A.RDD_END, A.IFSEQNO, A.SCHEDULING_TYPE
                     , CASE WHEN A.MESSAGE_TYPE = 'DELFOR' AND A.SOLDTO_CODE = 'FR000064' AND A.RDD_START <> A.RDD_END AND A.RDD_START >= V_1WEEK_MONDAY THEN 'Periodic DELFOR'
                            ELSE ''
                       END                                                                AS DELFOR_TYPE
                     , A.EDI_LT, A.CUST_MATERIAL_CODE, A.CREATE_DATE, A.SENDER_CODE, A.SENDER_NAME, A.CUSTOMER_PLANT, A.UNLOADING_POINT
                     , C.END_CUSTOMER
                     , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID)                     AS NICK_NAME
                     , E.DEPT_NAME_KO                                                     AS DEPT_NAME_KO
                     , F.DEPT_NAME_KO                                                     AS TEAM_NAME_KO
                     , C.SOLDTO_CUSTOMER
                     , G.COUNTRY, G.CITY, H.ITEM_NAME, H.ITEM_TYPE, D.OWNER, C.VMI_YN, I.BIZ_TYPE
                     , I.PROJECT_NAME, I.PROJECT_STATUS, I.PROJECT_OWNER
                     , D.CELL_PER_CAR, D.CELL_PER_MODULE
                     , CASE WHEN D.CELL_PER_MODULE <> 0 THEN D.CELL_PER_CAR / D.CELL_PER_MODULE
                            ELSE 0
                       END                                                                AS MODULE_PER_CAR
                     , D.ATTRIBUTE8                                                       AS KWH_PER_CELL
                     , CASE WHEN (A.DIVISION_ID LIKE '81%' AND D.CELL_PER_MODULE > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''') THEN (D.CELL_PER_MODULE * D.ATTRIBUTE8)
                            ELSE NULL
                       END                                                                AS KWH_PER_MODULE
                     , CASE WHEN (A.DIVISION_ID LIKE '81%' AND D.CELL_PER_CAR > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''') THEN (D.CELL_PER_CAR * D.ATTRIBUTE8)
                            ELSE NULL
                       END                                                                AS KWH_PER_PACK
                  FROM ( /* 2024.04.29  kcw3408  고객수요 N:N Mapping. 전체 대상 추출후 N:N Model Mapping 작업. Valid Range 1~5 미포함 구간은 Calloff 미집계 */
                        SELECT X.EDI_IF_SEQ, X.SUB_NO, X.YYYYMMDD, X.DIVISION_ID, X.SCM_SITE_ID
                             , B.MAPPING_ITEM_ID AS ITEM_ID, X.PROJECT_CODE, X.ERP_FCST_TYPE
                             , X.BASIS_YYYYMMDD, X.QTY, X.EDI_INCOTERMS, X.SALES_PLANT_SITE_ID
                             , X.COMPANY_ID, X.SOLDTO_CODE, X.SHIPTO_CODE, X.DOC_IDENTIFINER, X.MESSAGE_TYPE
                             , X.RDD_START, X.RDD_END, X.IFSEQNO, X.SCHEDULING_TYPE
                             , X.EDI_LT
                             , NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') AS CUST_MATERIAL_CODE
                             , NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')     AS CUSTOMER_PLANT
                             , NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), '-')    AS UNLOADING_POINT
                             , X.CREATE_DATE
                             , X.SENDER_CODE, X.SENDER_NAME
                          FROM DM_DNM_EDI_CALLOFF_ITEM  X
                             , GT_PRDM_CUST_MODEL_MAP   B
                         WHERE X.DIVISION_ID    = B.DIVISION_ID
                           AND X.SCM_SITE_ID    = B.SCM_SITE_ID
                           AND X.PROJECT_CODE   = B.PROJECT_CODE
                           AND X.EDI_INCOTERMS  = B.INCOTERMS
                           AND X.ITEM_ID        = B.ITEM_ID
                           AND NVL(RTRIM(LTRIM(X.UNLOADING_POINT)), '/')    = NVL(RTRIM(LTRIM(B.UNLOADING_POINT)), '/')
                           AND NVL(RTRIM(LTRIM(X.CUSTOMER_PLANT)), ' ')     = NVL(RTRIM(LTRIM(B.CUSTOMER_PLANT)), ' ')
                           AND NVL(RTRIM(LTRIM(X.CUST_MATERIAL_CODE)), ' ') = NVL(RTRIM(LTRIM(B.CUSTOMER_ITEM_ID)), ' ')
                           AND X.BASIS_YYYYMMDD >= B.VALID_START_DATE
                           AND X.BASIS_YYYYMMDD <= B.VALID_END_DATE
                           AND B.MAPPING_ITEM_ID IS NOT NULL
                           AND X.DIVISION_ID = P_DIVISION_ID   /* [E20251016-001453] 실행하려는 사업부 데이터만 */
                       ) A
                     , GT_PRDM_SCM_MST_SITE            C
                     , GT_PRDM_SCM_MST_SITE_ITEM       D
                     , SCM_MST_SSO_DEPT_INFO           E
                     , SCM_MST_SSO_DEPT_INFO           F
                     , SCM_MST_CITY                    G
                     , GT_PRDM_DM_MST_ITEM_SINGLE_V    H
                     , GT_PRDM_SCM_MST_PROJECT         I
                 WHERE A.DIVISION_ID    = C.DIVISION_ID(+)
                   AND A.SCM_SITE_ID    = C.SCM_SITE_ID(+)
                   AND A.DIVISION_ID    = D.DIVISION_ID(+)
                   AND A.PROJECT_CODE   = D.PROJECT_CODE(+)
                   AND A.SCM_SITE_ID    = D.SCM_SITE_ID(+)
                   AND A.ITEM_ID        = D.ITEM_ID(+)
--                   AND C.DEPT_ID        = E.DEPT_ID(+)
                   AND D.DEPT_ID        = E.DEPT_ID(+)                      -- 2026.09.03 AJS
                   AND E.UPPER_DEPT_ID  = F.DEPT_ID(+)
                   AND C.COUNTRY        = G.COUNTRY(+)
                   AND C.CITY           = G.CITY(+)
                   AND A.DIVISION_ID    = H.DIVISION_ID(+)
                   AND A.ITEM_ID        = H.ITEM_ID(+)
                   AND A.DIVISION_ID    = I.DIVISION_ID(+)
                   AND A.PROJECT_CODE   = I.PROJECT_CODE(+);

                INSERT
                  INTO GT_PRDM_QTY_SUM (
                       IFSEQNO
                     , EDI_IF_SEQ
                     , CREATE_DATE
                     , DIVISION_ID
                     , PROJECT_CODE
                     , ERP_FCST_TYPE
                     , BASIS_YYYYMMDD
                     , SCM_SITE_ID
                     , ITEM_ID
                     , QTY
                     , EDI_INCOTERMS
                     , SALES_PLANT_SITE_ID
                     , DOM_EXP
                     , UNLOADING_POINT
                     , CUST_MATERIAL_CODE )
                SELECT IFSEQNO
                     , EDI_IF_SEQ
                     , CREATE_DATE
                     , DIVISION_ID
                     , PROJECT_CODE
                     , ERP_FCST_TYPE
                     , BASIS_YYYYMMDD
                     , SCM_SITE_ID
                     , ITEM_ID
                     , SUM(TO_NUMBER(REPLACE(QTY, ',', '')))                              AS QTY
                     , EDI_INCOTERMS
                     , SALES_PLANT_SITE_ID
                     , DOM_EXP
                     , UNLOADING_POINT
                     , CUST_MATERIAL_CODE
                  FROM GT_PRDM_EDI_CUST_FCST
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND SCHEDULING_TYPE <> '83'
                 GROUP BY IFSEQNO, EDI_IF_SEQ, CREATE_DATE, DIVISION_ID, PROJECT_CODE
                     , ERP_FCST_TYPE, BASIS_YYYYMMDD, SCM_SITE_ID, ITEM_ID
                     , EDI_INCOTERMS, SALES_PLANT_SITE_ID, DOM_EXP
                     , UNLOADING_POINT, CUST_MATERIAL_CODE;

                DELETE
                  FROM DM_PLN_CUST_FCST_H
                 WHERE EDI_IF_SEQ IN (SELECT DISTINCT X.EDI_IF_SEQ FROM GT_PRDM_EDI_CUST_FCST X);

                /* ------------------------------------------------------------------
                   날짜 중복데이터는 SUM한 값으로 입력
                   ------------------------------------------------------------------ */
                INSERT
                  INTO DM_PLN_CUST_FCST_H (
                       HISTORY_SEQ
                     , EDI_IF_SEQ, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
                     , INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                     , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                     , CREATE_DATE
                     , SENDER_CODE
                     , SENDER_NAME
                     , END_CUSTOMER
                     , CUSTOMER_PLANT
                     , UNLOADING_POINT
                     , NICK_NAME
                     , DEPT_NAME_KO
                     , TEAM_NAME_KO
                     , SOLDTO_CUSTOMER
                     , COUNTRY
                     , CITY
                     , ITEM_NAME
                     , ITEM_TYPE
                     , OWNER
                     , VMI_YN
                     , BIZ_TYPE
                     , PROJECT_NAME
                     , PROJECT_STATUS
                     , PROJECT_OWNER
                     , CELL_PER_CAR
                     , CELL_PER_MODULE
                     , MODULE_PER_CAR
                     , KWH_PER_CELL
                     , KWH_PER_MODULE
                     , KWH_PER_PACK
                     , SCHEDULING_TYPE
                     , CUST_MATERIAL_CODE )
                SELECT SEQ1_DM_PLN_CUST_FCST_H.NEXTVAL
                     , A.EDI_IF_SEQ, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE
                     , A.EDI_INCOTERMS, 'CUST_FCST_EDI', NVL(A.SALES_PLANT_SITE_ID, ' '), A.BASIS_YYYYMMDD, B.QTY
                     , 'EDI', SYSDATE, 'EDI', SYSDATE
                     , A.CREATE_DATE
                     , A.SENDER_CODE
                     , A.SENDER_NAME
                     , A.END_CUSTOMER
                     , A.CUSTOMER_PLANT
                     , A.UNLOADING_POINT
                     , A.NICK_NAME
                     , A.DEPT_NAME_KO
                     , A.TEAM_NAME_KO
                     , A.SOLDTO_CUSTOMER
                     , A.COUNTRY
                     , A.CITY
                     , A.ITEM_NAME
                     , A.ITEM_TYPE
                     , A.OWNER
                     , A.VMI_YN
                     , A.BIZ_TYPE
                     , A.PROJECT_NAME
                     , A.PROJECT_STATUS
                     , A.PROJECT_OWNER
                     , A.CELL_PER_CAR
                     , A.CELL_PER_MODULE
                     , A.MODULE_PER_CAR
                     , A.KWH_PER_CELL
                     , A.KWH_PER_MODULE
                     , A.KWH_PER_PACK
                     , A.SCHEDULING_TYPE
                     , A.CUST_MATERIAL_CODE
                  FROM GT_PRDM_EDI_CUST_FCST A
                     , GT_PRDM_QTY_SUM       B
                 WHERE A.IFSEQNO      = B.IFSEQNO
                   AND A.EDI_IF_SEQ   = B.EDI_IF_SEQ
                   AND A.CREATE_DATE  = B.CREATE_DATE
                   AND A.DIVISION_ID  = B.DIVISION_ID
                   AND NVL(A.PROJECT_CODE, ' ')       = NVL(B.PROJECT_CODE, ' ')
                   AND NVL(A.SCM_SITE_ID, ' ')        = NVL(B.SCM_SITE_ID, ' ')
                   AND NVL(A.ITEM_ID, ' ')            = NVL(B.ITEM_ID, ' ')
                   AND A.DOM_EXP              = B.DOM_EXP
                   AND A.ERP_FCST_TYPE        = B.ERP_FCST_TYPE
                   AND A.EDI_INCOTERMS        = B.EDI_INCOTERMS
                   AND A.SALES_PLANT_SITE_ID  = B.SALES_PLANT_SITE_ID
                   AND A.BASIS_YYYYMMDD       = B.BASIS_YYYYMMDD
                   AND NVL(A.UNLOADING_POINT, '/')    = NVL(B.UNLOADING_POINT, '/')
                   AND NVL(A.CUST_MATERIAL_CODE, ' ') = NVL(B.CUST_MATERIAL_CODE, ' ');

                /* ------------------------------------------------------------------
                   MEASURE별 SUM한 값으로 생성
                   Oracle: SEQ.NEXTVAL 은 GROUP BY/집계 SELECT 직접 사용 불가(ORA-02287) → 집계결과를 인라인뷰 Q 로 감싸고 바깥에서 채번
                   ------------------------------------------------------------------ */
                INSERT
                  INTO DM_PLN_CUST_FCST_H (
                       HISTORY_SEQ
                     , EDI_IF_SEQ, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , YYYYMMDD
                     , QTY
                     , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                     , CREATE_DATE
                     , SENDER_CODE
                     , SENDER_NAME
                     , END_CUSTOMER
                     , CUSTOMER_PLANT
                     , UNLOADING_POINT
                     , NICK_NAME
                     , DEPT_NAME_KO
                     , TEAM_NAME_KO
                     , SOLDTO_CUSTOMER
                     , COUNTRY
                     , CITY
                     , ITEM_NAME
                     , ITEM_TYPE
                     , OWNER
                     , VMI_YN
                     , BIZ_TYPE
                     , PROJECT_NAME
                     , PROJECT_STATUS
                     , PROJECT_OWNER
                     , CELL_PER_CAR
                     , CELL_PER_MODULE
                     , MODULE_PER_CAR
                     , KWH_PER_CELL
                     , KWH_PER_MODULE
                     , KWH_PER_PACK
                     , SCHEDULING_TYPE
                     , CUST_MATERIAL_CODE )
                SELECT SEQ1_DM_PLN_CUST_FCST_H.NEXTVAL
                     , Q.EDI_IF_SEQ, Q.DIVISION_ID, Q.PROJECT_CODE, Q.SCM_SITE_ID, Q.ITEM_ID, Q.DOM_EXP, Q.ERP_FCST_TYPE
                     , Q.EDI_INCOTERMS
                     , Q.MEASURE
                     , Q.PLANT_SITE_ID
                     , Q.BASIS_YYYYMMDD
                     , Q.QTY
                     , 'EDI', SYSDATE, 'EDI', SYSDATE
                     , Q.CREATE_DATE
                     , Q.SENDER_CODE
                     , Q.SENDER_NAME
                     , Q.END_CUSTOMER
                     , Q.CUSTOMER_PLANT
                     , Q.UNLOADING_POINT
                     , Q.NICK_NAME
                     , Q.DEPT_NAME_KO
                     , Q.TEAM_NAME_KO
                     , Q.SOLDTO_CUSTOMER
                     , Q.COUNTRY
                     , Q.CITY
                     , Q.ITEM_NAME
                     , Q.ITEM_TYPE
                     , Q.OWNER
                     , Q.VMI_YN
                     , Q.BIZ_TYPE
                     , Q.PROJECT_NAME
                     , Q.PROJECT_STATUS
                     , Q.PROJECT_OWNER
                     , Q.CELL_PER_CAR
                     , Q.CELL_PER_MODULE
                     , Q.MODULE_PER_CAR
                     , Q.KWH_PER_CELL
                     , Q.KWH_PER_MODULE
                     , Q.KWH_PER_PACK
                     , Q.SCHEDULING_TYPE
                     , Q.CUST_MATERIAL_CODE
                  FROM (
                        SELECT A.EDI_IF_SEQ, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE
                             , A.EDI_INCOTERMS
                             , CASE WHEN A.SCHEDULING_TYPE = '4'  THEN 'Planning_Forecast'
                                    WHEN A.SCHEDULING_TYPE = '10' THEN 'Immidiate'
                                    WHEN A.SCHEDULING_TYPE = '24' THEN 'Commercial_Agreement'
                                    WHEN A.SCHEDULING_TYPE = '1'  THEN 'Firm_Temp'
                                    WHEN A.SCHEDULING_TYPE = '2'  THEN 'Manumacturing_Material_Temp'
                                    WHEN A.SCHEDULING_TYPE = '3'  THEN 'Material_Temp'
                                    WHEN A.SCHEDULING_TYPE = '83' THEN 'Backorder'
                               END                                                          AS MEASURE
                             , NVL(A.SALES_PLANT_SITE_ID, ' ')                              AS PLANT_SITE_ID
                             , A.BASIS_YYYYMMDD                                             AS BASIS_YYYYMMDD
                             , SUM(TO_NUMBER(REPLACE(A.QTY, ',', '')))                      AS QTY
                             , A.CREATE_DATE
                             , A.SENDER_CODE
                             , A.SENDER_NAME
                             , A.END_CUSTOMER
                             , A.CUSTOMER_PLANT
                             , A.UNLOADING_POINT
                             , A.NICK_NAME
                             , A.DEPT_NAME_KO
                             , A.TEAM_NAME_KO
                             , A.SOLDTO_CUSTOMER
                             , A.COUNTRY
                             , A.CITY
                             , A.ITEM_NAME
                             , A.ITEM_TYPE
                             , A.OWNER
                             , A.VMI_YN
                             , A.BIZ_TYPE
                             , A.PROJECT_NAME
                             , A.PROJECT_STATUS
                             , A.PROJECT_OWNER
                             , A.CELL_PER_CAR
                             , A.CELL_PER_MODULE
                             , A.MODULE_PER_CAR
                             , A.KWH_PER_CELL
                             , A.KWH_PER_MODULE
                             , A.KWH_PER_PACK
                             , A.SCHEDULING_TYPE
                             , A.CUST_MATERIAL_CODE
                          FROM GT_PRDM_EDI_CUST_FCST A
                         WHERE A.SCHEDULING_TYPE IS NOT NULL   /* 20240507 임시 */
                         GROUP BY A.EDI_IF_SEQ, A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.ERP_FCST_TYPE
                             , A.EDI_INCOTERMS, A.SCHEDULING_TYPE, NVL(A.SALES_PLANT_SITE_ID, ' '), A.BASIS_YYYYMMDD, A.CREATE_DATE
                             , A.SENDER_CODE, A.SENDER_NAME, A.END_CUSTOMER, A.CUSTOMER_PLANT, A.UNLOADING_POINT
                             , A.NICK_NAME, A.DEPT_NAME_KO, A.TEAM_NAME_KO, A.SOLDTO_CUSTOMER, A.COUNTRY, A.CITY
                             , A.ITEM_NAME, A.ITEM_TYPE, A.OWNER, A.VMI_YN, A.BIZ_TYPE, A.PROJECT_NAME, A.PROJECT_STATUS, A.PROJECT_OWNER
                             , A.CELL_PER_CAR, A.CELL_PER_MODULE, A.MODULE_PER_CAR, A.KWH_PER_CELL, A.KWH_PER_MODULE, A.KWH_PER_PACK
                             , A.CUST_MATERIAL_CODE
                       ) Q;

            END IF;

        END IF;
        /* ******************** EDI DATA 생성 END ******************** */


        /* ******************** RPA DATA 생성 START ******************** */
        IF V_ACCEPT_FLAG = 'RPA' THEN

            DELETE
              FROM DM_PLN_CUST_FCST_H
             WHERE MEASURE IN ('CUST_FCST', 'Customer FCST')
               AND DIVISION_ID = V_DIVISION_ID
               AND LAST_UPDATE_DATE >= TO_DATE(V_FROM_DATE, 'YYYYMMDD');

            DBMS_OUTPUT.PUT_LINE('RPA_A: @v_division_id:' || V_DIVISION_ID || ', @v_accept_flag:' || V_ACCEPT_FLAG || ', @v_from_date:' || V_FROM_DATE);

            IF (V_DIVISION_ID = '40') THEN

                INSERT
                  INTO DM_PLN_CUST_FCST_H (
                       HISTORY_SEQ
                     , EDI_IF_SEQ
                     , DIVISION_ID
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , YYYYMMDD, QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , CREATE_DATE
                     , SENDER_CODE
                     , SENDER_NAME
                     , END_CUSTOMER
                     , CUSTOMER_PLANT
                     , UNLOADING_POINT
                     , NICK_NAME
                     , DEPT_NAME_KO
                     , TEAM_NAME_KO
                     , SOLDTO_CUSTOMER
                     , COUNTRY
                     , CITY
                     , ITEM_NAME
                     , ITEM_TYPE
                     , OWNER
                     , VMI_YN
                     , BIZ_TYPE
                     , PROJECT_NAME
                     , PROJECT_STATUS
                     , PROJECT_OWNER
                     , CELL_PER_CAR
                     , CELL_PER_MODULE
                     , MODULE_PER_CAR
                     , KWH_PER_CELL
                     , KWH_PER_MODULE
                     , KWH_PER_PACK
                     , SCHEDULING_TYPE )
                SELECT SEQ1_DM_PLN_CUST_FCST_H.NEXTVAL
                     , ' '                                                                AS EDI_IF_SEQ    /* [MSSQL '' → NOT NULL 컬럼: 공백 sentinel] */
                     , AA.DIVISION_ID
                     , ' '                                                                AS PROJECT_CODE
                     , AA.SCM_SITE_ID
                     , AA.ITEM_ID
                     , AA.DOM_EXP
                     , AA.FCST_TYPE
                     , AA.INCOTERMS
                     , AA.MEASURE
                     , AA.PLANT_SITE_ID
                     , AA.YYYYMMDD
                     , CASE WHEN AA.QTY IS NULL THEN NULL ELSE CAST(AA.QTY AS NUMBER(30, 10)) END       AS QTY
                     , AA.CREATED_BY
                     , AA.CREATION_DATE
                     , AA.LAST_UPDATED_BY
                     , AA.LAST_UPDATE_DATE
                     , AA.CREATE_DATE
                     , AA.SENDER_CODE
                     , AA.SENDER_NAME
                     , AA.END_CUSTOMER
                     , AA.CUSTOMER_PLANT
                     , AA.UNLOADING_POINT
                     , AA.NICK_NAME
                     , AA.DEPT_NAME_KO
                     , AA.TEAM_NAME_KO
                     , AA.SOLDTO_CUSTOMER
                     , AA.COUNTRY_NAME
                     , AA.CITY_NAME
                     , AA.ITEM_NAME
                     , AA.ITEM_TYPE
                     , AA.OWNER
                     , AA.VMI_YN
                     , AA.BIZ_TYPE_NAME
                     , AA.PROJECT_NAME
                     , AA.PROJECT_STATUS
                     , AA.PROJECT_OWNER
                     , NVL(AA.CELL_PER_CAR, 0)                                            AS CELL_PER_CAR
                     , NVL(AA.CELL_PER_MODULE, 0)                                         AS CELL_PER_MODULE
                     , NVL(AA.MODULE_PER_CAR, 0)                                          AS MODULE_PER_CAR
                     , 0                                                                  AS KWH_PER_CELL  /* 원본: ISNULL(CONVERT(NUMERIC(30,10),AA.KWH_PER_CELL),0) 주석처리→0 고정 */
                     , NVL(AA.KWH_PER_MODULE, 0)                                          AS KWH_PER_MODULE
                     , NVL(AA.KWH_PER_PACK, 0)                                            AS KWH_PER_PACK
                     , ' '                                                                AS SCHEDULING_TYPE
                  FROM (
                        SELECT DISTINCT A.DIVISION_ID
                             , ' '                    AS SENDER_CODE
                             , ' '                    AS SENDER_NAME
                             , A.YYYYMMDD
                             , ' '                    AS CUSTOMER_PLANT
                             , '-'                    AS UNLOADING_POINT
                             , ' '                    AS CUST_MATERIAL_CODE
                             , C.END_CUSTOMER
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.INCOTERMS
                             , A.FCST_TYPE
                             , A.DOM_EXP
                             , E.DEPT_NAME_KO         AS DEPT_NAME_KO
                             , F.DEPT_NAME_KO         AS TEAM_NAME_KO
                             , C.SOLDTO_CUSTOMER
                             , G.COUNTRY_NAME
                             , G.CITY_NAME
                             , H.ITEM_NAME
                             , H.ITEM_TYPE
                             , D.OWNER
                             , C.VMI_YN
                             , I.BIZ_TYPE_NAME
                             , A.PROJECT_CODE
                             , I.PROJECT_NAME
                             , I.PROJECT_STATUS
                             , I.PROJECT_OWNER
                             , A.PLANT_SITE_ID        AS PLANT_SITE_ID
                             , D.CELL_PER_CAR
                             , D.CELL_PER_MODULE
                             , CASE WHEN D.CELL_PER_MODULE <> 0 THEN D.CELL_PER_CAR / D.CELL_PER_MODULE ELSE 0 END AS MODULE_PER_CAR
                             , ' '                    AS SOLDTO_CODE
                             , ' '                    AS COMPANY_ID
                             , D.ATTRIBUTE8           AS KWH_PER_CELL
                             , CASE WHEN A.DIVISION_ID = V_DIVISION_ID AND D.CELL_PER_MODULE > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''' THEN (D.CELL_PER_MODULE * D.ATTRIBUTE8)
                                    ELSE NULL
                               END                    AS KWH_PER_MODULE
                             , CASE WHEN A.DIVISION_ID = V_DIVISION_ID AND D.CELL_PER_CAR > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''' THEN (D.CELL_PER_CAR * D.ATTRIBUTE8)
                                    ELSE NULL
                               END                    AS KWH_PER_PACK
                             , A.MEASURE
                             , A.QTY
                             , TO_CHAR(A.CREATION_DATE, 'YYYYMMDD') AS CREATE_DATE
                             , A.CREATED_BY
                             , A.CREATION_DATE
                             , A.LAST_UPDATED_BY
                             , A.LAST_UPDATE_DATE
                          FROM DM_PLN_MKT_FCST            A
                             , SCM_MST_SITE               C
                             , SCM_MST_SITE_ITEM          D
                             , SCM_MST_SSO_DEPT_INFO       E
                             , SCM_MST_SSO_DEPT_INFO       F
                             , SCM_MST_CITY               G
                             , DM_MST_ITEM_SINGLE_V       H
                             , SCM_MST_PROJECT            I
                         WHERE A.DIVISION_ID    = C.DIVISION_ID(+)
                           AND A.SCM_SITE_ID    = C.SCM_SITE_ID(+)
                           AND C.SITE_TYPE(+)   = 'SALES'
                           AND C.VALID_YN(+)    = 'Y'
                           AND A.DIVISION_ID    = D.DIVISION_ID(+)
                           AND A.SCM_SITE_ID    = D.SCM_SITE_ID(+)
                           AND A.ITEM_ID        = D.ITEM_ID(+)
--                           AND C.DEPT_ID        = E.DEPT_ID(+)
                           AND D.DEPT_ID        = E.DEPT_ID(+)              -- 2026.09.03 AJS
                           AND E.UPPER_DEPT_ID  = F.DEPT_ID(+)
                           AND C.COUNTRY        = G.COUNTRY(+)
                           AND C.CITY           = G.CITY(+)
                           AND A.DIVISION_ID    = H.DIVISION_ID(+)
                           AND A.ITEM_ID        = H.ITEM_ID(+)
                           AND A.DIVISION_ID    = I.DIVISION_ID(+)
                           AND A.MEASURE IN ('CUST_FCST', 'Customer FCST')   /* RPA는 CUST_FCST_EDI가 없기 때문인건지? */
                           AND A.DIVISION_ID = V_DIVISION_ID
                           AND TO_CHAR(A.LAST_UPDATE_DATE, 'YYYYMMDD') >= V_FROM_DATE
                       ) AA;

            ELSE

                INSERT
                  INTO DM_PLN_CUST_FCST_H (
                       HISTORY_SEQ
                     , EDI_IF_SEQ, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID, YYYYMMDD, QTY
                     , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                     , CREATE_DATE
                     , SENDER_CODE
                     , SENDER_NAME
                     , END_CUSTOMER
                     , CUSTOMER_PLANT
                     , UNLOADING_POINT
                     , NICK_NAME
                     , DEPT_NAME_KO
                     , TEAM_NAME_KO
                     , SOLDTO_CUSTOMER
                     , COUNTRY
                     , CITY
                     , ITEM_NAME
                     , ITEM_TYPE
                     , OWNER
                     , VMI_YN
                     , BIZ_TYPE
                     , PROJECT_NAME
                     , PROJECT_STATUS
                     , PROJECT_OWNER
                     , CELL_PER_CAR
                     , CELL_PER_MODULE
                     , MODULE_PER_CAR
                     , KWH_PER_CELL
                     , KWH_PER_MODULE
                     , KWH_PER_PACK )
                SELECT SEQ1_DM_PLN_CUST_FCST_H.NEXTVAL
                     , ' '                                                                AS EDI_IF_SEQ    /* [MSSQL '' → NOT NULL 컬럼: 공백 sentinel] */
                     , AA.DIVISION_ID
                     , AA.PROJECT_CODE
                     , AA.SCM_SITE_ID
                     , AA.ITEM_ID
                     , AA.DOM_EXP
                     , AA.FCST_TYPE
                     , AA.INCOTERMS
                     , AA.MEASURE
                     , AA.PLANT_SITE_ID
                     , AA.YYYYMMDD
                     , CASE WHEN AA.QTY IS NULL THEN NULL ELSE CAST(AA.QTY AS NUMBER(30, 10)) END       AS QTY
                     , AA.CREATED_BY
                     , AA.CREATION_DATE
                     , AA.LAST_UPDATED_BY
                     , AA.LAST_UPDATE_DATE
                     , AA.CREATE_DATE
                     , AA.SENDER_CODE
                     , AA.SENDER_NAME
                     , AA.END_CUSTOMER
                     , AA.CUSTOMER_PLANT
                     , AA.UNLOADING_POINT
                     , AA.NICK_NAME
                     , AA.DEPT_NAME_KO
                     , AA.TEAM_NAME_KO
                     , AA.SOLDTO_CUSTOMER
                     , AA.COUNTRY_NAME
                     , AA.CITY_NAME
                     , AA.ITEM_NAME
                     , AA.ITEM_TYPE
                     , AA.OWNER
                     , AA.VMI_YN
                     , AA.BIZ_TYPE_NAME
                     , AA.PROJECT_NAME
                     , AA.PROJECT_STATUS
                     , AA.PROJECT_OWNER
                     , CASE WHEN AA.CELL_PER_CAR    IS NULL THEN NULL ELSE CAST(AA.CELL_PER_CAR    AS NUMBER(30, 10)) END AS CELL_PER_CAR
                     , CASE WHEN AA.CELL_PER_MODULE IS NULL THEN NULL ELSE CAST(AA.CELL_PER_MODULE AS NUMBER(30, 10)) END AS CELL_PER_MODULE
                     , CASE WHEN AA.MODULE_PER_CAR  IS NULL THEN NULL ELSE CAST(AA.MODULE_PER_CAR  AS NUMBER(30, 10)) END AS MODULE_PER_CAR
                     , CASE WHEN AA.KWH_PER_CELL    IS NULL THEN NULL ELSE CAST(AA.KWH_PER_CELL    AS NUMBER(30, 10)) END AS KWH_PER_CELL
                     , CASE WHEN AA.KWH_PER_MODULE  IS NULL THEN NULL ELSE CAST(AA.KWH_PER_MODULE  AS NUMBER(30, 10)) END AS KWH_PER_MODULE
                     , CASE WHEN AA.KWH_PER_PACK    IS NULL THEN NULL ELSE CAST(AA.KWH_PER_PACK    AS NUMBER(30, 10)) END AS KWH_PER_PACK
                  FROM (
                        SELECT DISTINCT A.DIVISION_ID
                             , ' '                    AS SENDER_CODE
                             , ' '                    AS SENDER_NAME
                             , A.YYYYMMDD
                             , ' '                    AS CUSTOMER_PLANT
                             , ' '                    AS UNLOADING_POINT
                             , ' '                    AS CUST_MATERIAL_CODE
                             , C.END_CUSTOMER
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , FN_GET_ITEM_NICKNAME(A.DIVISION_ID, A.ITEM_ID) AS NICK_NAME
                             , A.INCOTERMS
                             , A.FCST_TYPE
                             , A.DOM_EXP
                             , E.DEPT_NAME_KO         AS DEPT_NAME_KO
                             , F.DEPT_NAME_KO         AS TEAM_NAME_KO
                             , C.SOLDTO_CUSTOMER
                             , G.COUNTRY_NAME
                             , G.CITY_NAME
                             , H.ITEM_NAME
                             , H.ITEM_TYPE
                             , D.OWNER
                             , C.VMI_YN
                             , I.BIZ_TYPE_NAME
                             , A.PROJECT_CODE
                             , I.PROJECT_NAME
                             , I.PROJECT_STATUS
                             , I.PROJECT_OWNER
                             , A.PLANT_SITE_ID        AS PLANT_SITE_ID
                             , D.CELL_PER_CAR
                             , D.CELL_PER_MODULE
                             , CASE WHEN D.CELL_PER_MODULE <> 0 THEN D.CELL_PER_CAR / D.CELL_PER_MODULE ELSE 0 END AS MODULE_PER_CAR
                             , ' '                    AS SOLDTO_CODE
                             , ' '                    AS COMPANY_ID
                             , D.ATTRIBUTE8           AS KWH_PER_CELL
                             , CASE WHEN A.DIVISION_ID = V_DIVISION_ID AND D.CELL_PER_MODULE > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''' THEN (D.CELL_PER_MODULE * D.ATTRIBUTE8)
                                    ELSE NULL
                               END                    AS KWH_PER_MODULE
                             , CASE WHEN A.DIVISION_ID = V_DIVISION_ID AND D.CELL_PER_CAR > 0 AND NVL(D.ATTRIBUTE8, '''') <> '''' THEN (D.CELL_PER_CAR * D.ATTRIBUTE8)
                                    ELSE NULL
                               END                    AS KWH_PER_PACK
                             , A.MEASURE
                             , A.QTY
                             , TO_CHAR(A.CREATION_DATE, 'YYYYMMDD') AS CREATE_DATE
                             , A.CREATED_BY
                             , A.CREATION_DATE
                             , A.LAST_UPDATED_BY
                             , A.LAST_UPDATE_DATE
                          FROM DM_PLN_MKT_FCST            A
                             , SCM_MST_SITE               C
                             , SCM_MST_SITE_ITEM          D
                             , SCM_MST_SSO_DEPT_INFO       E
                             , SCM_MST_SSO_DEPT_INFO       F
                             , SCM_MST_CITY               G
                             , DM_MST_ITEM_SINGLE_V       H
                             , SCM_MST_PROJECT            I
                         WHERE A.DIVISION_ID    = C.DIVISION_ID(+)
                           AND A.SCM_SITE_ID    = C.SCM_SITE_ID(+)
                           AND C.SITE_TYPE(+)   = 'SALES'
                           AND C.VALID_YN(+)    = 'Y'
                           AND A.DIVISION_ID    = D.DIVISION_ID(+)
                           AND A.PROJECT_CODE   = D.PROJECT_CODE(+)
                           AND A.SCM_SITE_ID    = D.SCM_SITE_ID(+)
                           AND A.ITEM_ID        = D.ITEM_ID(+)
--                           AND C.DEPT_ID        = E.DEPT_ID(+)
                           AND D.DEPT_ID        = E.DEPT_ID(+)              -- 2026.09.03 AJS
                           AND E.UPPER_DEPT_ID  = F.DEPT_ID(+)
                           AND C.COUNTRY        = G.COUNTRY(+)
                           AND C.CITY           = G.CITY(+)
                           AND A.DIVISION_ID    = H.DIVISION_ID(+)
                           AND A.ITEM_ID        = H.ITEM_ID(+)
                           AND A.DIVISION_ID    = I.DIVISION_ID(+)
                           AND A.PROJECT_CODE   = I.PROJECT_CODE(+)
                           AND A.MEASURE IN ('CUST_FCST', 'Customer FCST')   /* RPA는 CUST_FCST_EDI가 없기 때문인건지? */
                           AND A.DIVISION_ID = V_DIVISION_ID
                           AND TO_CHAR(A.LAST_UPDATE_DATE, 'YYYYMMDD') >= V_FROM_DATE
                       ) AA;

            END IF;

        END IF;
        /* ******************** RPA DATA 생성 END ******************** */

        COMMIT;   /* MSSQL 문장단위 autocommit 재현(성공경로 확정). GTT(ON COMMIT DELETE ROWS)는 소비 완료 후라 안전 */

    EXCEPTION
        WHEN OTHERS THEN

            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE (' || P_DIVISION_ID || '_' || P_ACCEPT_FLAG || ') : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;

            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                , V_LOG_TYPE
                , N_LOG_COUNT
                , V_LOG_MESSAGE
                , V_DESCRIPTION
                , D_EVENT_DATE
                , JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID, 'p_accept_flag' VALUE P_ACCEPT_FLAG RETURNING VARCHAR2(4000 CHAR))
                , SQLCODE
                , SQLERRM
                , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);


    END;

    /* 종료 LOG (EXCEPTION 바깥 = 정상·에러 모두 항상 기록) */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := V_FROM_DATE || '(' || P_DIVISION_ID || '_' || P_ACCEPT_FLAG || ')';
    D_EVENT_DATE  := SYSDATE;

    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_CUST_FCST_RECORD
-- ##### END PROCEDURE PR_DM_PLN_CUST_FCST_RECORD

-- ##### START PROCEDURE PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE
CREATE OR REPLACE PROCEDURE         "PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE" 

(   P_DIVISION_ID    IN  VARCHAR2
  , P_PLAN_ID        IN  VARCHAR2
  , O_RESULT_CURSOR  OUT SYS_REFCURSOR
)
/*=====================================================================================================================================================================
 * Program ID   : PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE
 * Description  : RTF 산출하는 프로시져
 *                방식 ① PLAN_ID가 들어오는경우: SCP 엔진 수행 후 SCP에서 호출
 *					   ② PLAN_ID가 NULL로 들어오는경우: 주1회 WEEKLY ROLLING 작업시 호출받은 경우임 (SP:PR_DM_PLN_MKT_FCST_WEEKLY_ROLLING)
 *                     ③ PLAN_ID가 CALL로 들어오는 경우: MKT FCST 화면에서 저장시 호출하는 경우MKT_FCST값 저장시 특정대상만 전달받으며 호출된 경우임 (SP:DMF0003_SAVE_MKT_FCST)
 * Program History
 *=====================================================================================================================================================================
 *   Date       In Charge		Description
 *=====================================================================================================================================================================
 * 2018.05.14   JunHee Jeen
				/ KHSONG		Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * -----------------------------------------------------------------------------------------------------------
 * 2018.06.07	KHSONG			Sales Plan AMT Create Procedure 호출추가
 * 2018.06.11	ytchoi			한주가 지나면 화면에서 과거 RTF P 를 보기 어렵기 때문에 당주 월요일 이후로만 계산 함
 * 2018.06.14	KHSONG			CUTOFF RTF MEASURE 정보변경 로직 추가
 * 2018.06.18	KHSONG			CUTOFF TABLE BALANCE 값 재계산 로직 추가
 * 2018.08.20	KHSONG			BALANCE 생성로직 CURSOR에서 테이블구조로 수정
 * 2018.08.23	KHSONG			VMI재고 확인후 RTF 생성 로직, VMI DIO 계산로직 보완
 * 2018.09.27	KHSONG			DIO,BALANCE CURSOR제거 로직반영
 * 2018.10.02	KHSONG			PROCEDURE 에서 대상 전달받아 처리되는 로직 추가반영
 * 2018.10.11	KHSONG			CUTOFF테이블작업 호출추가
 * 2018.11.08	KHSONG			소형 반품예정수량(RMA) fcst_type인 경우에 RTF를 MKT_FCST와 동일하게 생성 조건추가
 * 2018.12.20	KHSONG			연말특정일 제외조건 추가 -> 20190110 KHSONG 주석처리
 *				KHSONG			소형 RTF_SCP 사용하는 시점을 조건으로 추가 -> 20190110 KHSONG 주석처리
 * 2019.01.11	KHSONG			소형 'RTF_SCP' MEASURE 적용
 * 2019.02.21					실적없이 BALANCE만 남아있는 데이터 삭제하기위하여 'RTF','BALANCE' MEASURE 추가함
 * 2019.06.24	KHSONG			[CSR_ID:4016234]자동차전지 사업부 RTF(Manual 입력) 메져 추가건 적용
								운영데이터 원격 사용부분 이관전에 삭제필요
 * 2019.07.09	KHSONG			[CSR ID:4027463] RTF_System[R+P] Measure 추가 요청의 건
 * 2019.07.09	KHSONG			[CSR ID:4034895] 상품 매출에 대한 마케팅의 RTF[R+P] 수정 권한 요청 및 MKT FCST 기본값 삭제 요청 (자동차사업부)
 * 2019.08.09	KHSONG			[CSR ID:4059971] VMI-In Request 로직 변경
 * 2019.11.04	KHSONG			[CSR ID:4107133] VMI대상 RTF_SYS_RP MEASURE 생성로직 추가
 * 2020.03.03	HWI1993			[CSR ID:C20200302-000164] SCP SHIP PLAN 이 생성되면 SCP_SHIP_PLAN 을 DM_PLN_SHIPMENT_REQ 에 복사하도록 DMF0045_SCPSHIPPLAN_TO_SHIPREQ 호출 추가
 * 2020.03.27	HWI1993			운영동기화
 * 2020.04.16	KHSONG			C20200413-000593 ESS사업부 RTF Measure 추가
 * 2020.06.15	hwi1993			C20200518-000359 GSCM RMA값 표기 로직 수정 요청의 건
