    													SELECT   MAX(VERSION_NO)
    													FROM dbo.DM_MST_VERSION WITH(NOLOCK)
    													WHERE 1=1
    														AND VERSION_TYPE IN (CASE WHEN @c_division_id = '40' THEN 'SF_W' ELSE 'MF_W' END)
    														AND YYYYMMDD >= CONVERT(CHAR(8), DATEADD(DD, -7*1, dbo.FN_NEXT_DAY(GETDATE(), 'MON')), 112)    -- 당주 월요일부터
    														AND YYYYMMDD <= CONVERT(CHAR(8), DATEADD(DD, 0, dbo.FN_NEXT_DAY(getdate(), 'SUN')), 112)       -- 당주 일요일까지
    														AND DIVISION_ID		 = @c_division_id
    												)
    						) A
    						LEFT OUTER JOIN
    						(
    							SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID				--[PJ2025-50017] CELL_PROD_SITE_ID 추가
    							FROM DM_PLN_SALES_PLAN	WITH(NOLOCK)
    							WHERE DIVISION_ID = @c_division_id
    							AND   YYYYMMDD >= @c_plan_start_yyyymmdd
    							AND   MEASURE = 'RTF_SYS_RP'
    						) B
    						ON  A.DIVISION_ID	= B.DIVISION_ID
    						AND A.PROJECT_CODE	= B.PROJECT_CODE
    						AND A.SCM_SITE_ID	= B.SCM_SITE_ID
    						AND A.ITEM_ID		= B.ITEM_ID
    						AND A.DOM_EXP		= B.DOM_EXP
    						AND A.FCST_TYPE		= B.FCST_TYPE
    						AND A.INCOTERMS		= B.INCOTERMS
    						AND A.PLANT_SITE_ID	= B.PLANT_SITE_ID
    						AND A.CELL_PROD_SITE_ID	= B.CELL_PROD_SITE_ID		--[PJ2025-50017] CELL_PROD_SITE_ID 추가
    						WHERE B.DIVISION_ID IS NULL
    					) A
    					LEFT OUTER JOIN
    					(
    						SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID		--[PJ2025-50017] CELL_PROD_SITE_ID 추가
    						--FROM #T_SCP_PLN_RTF_ALLOCATION_V B WITH(NOLOCK)
    						-- [PJ2025-50188] 임시테이블 #T_SCP_PLN_RTF_ALLOCATION_V ==> #T_MF_RTF_ALLOCATION 이름변경
    						FROM #T_MF_RTF_ALLOCATION B WITH(NOLOCK)
    						WHERE DIVISION_ID		= @c_scp_division_id
    						AND ORIGIN_DIVISION_ID	= @c_division_id
    						AND PLAN_ID				= @c_plan_id
    						AND YYYYMMDD			>= @c_plan_start_yyyymmdd
    						AND ALLOCATION_QTY		!= 0
    					) B
    					ON  A.DIVISION_ID	= B.DIVISION_ID
    					AND A.PROJECT_CODE	= B.PROJECT_CODE
    					AND A.SCM_SITE_ID	= B.SALES_SITE_ID
    					AND A.ITEM_ID		= B.ITEM_ID
    					AND A.DOM_EXP		= B.DOM_EXP
    					AND A.FCST_TYPE		= B.FCST_TYPE
    					AND A.INCOTERMS		= B.INCOTERMS
    					AND A.PLANT_SITE_ID	= B.PLANT_SITE_ID
    					AND A.CELL_PROD_SITE_ID	= B.CELL_PROD_SITE_ID		--[PJ2025-50017] CELL_PROD_SITE_ID 추가
    					WHERE B.DIVISION_ID IS NULL
    				) A
    				INNER JOIN (
    							SELECT DISTINCT DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, CURRENCY, YYYYMMDD		--[PJ2025-50017] CELL_PROD_SITE_ID 추가
    							FROM DM_PLN_CFM_SELLING_PRICE	WITH(NOLOCK)
    							WHERE DIVISION_ID	= @c_scp_division_id
    							AND   YYYYMMDD		= @c_plan_start_yyyymmdd
    							AND   MEASURE		= 'LOC'
    				) B
    				ON  A.DIVISION_ID	= B.DIVISION_ID
    				AND A.PROJECT_CODE	= B.PROJECT_CODE
    				AND A.PROJECT_CODE	= B.END_CUSTOMER
    				AND A.SCM_SITE_ID	= B.SCM_SITE_ID
    				AND A.ITEM_ID		= B.ITEM_ID
    				AND A.DOM_EXP		= B.DOM_EXP
    				AND A.FCST_TYPE		= B.FCST_TYPE
    				AND A.INCOTERMS		= B.INCOTERMS
    				AND A.PLANT_SITE_ID	= B.PLANT_SITE_ID
    				AND A.CELL_PROD_SITE_ID	= B.CELL_PROD_SITE_ID		--[PJ2025-50017] CELL_PROD_SITE_ID 추가

    		END
    			--[PJ2025-50017] 소형 매출계획 동기화 개선 End
    		*/
    /* [PJ2025-50188] 2025.07.31 RTF 0 생성 로직 삭제, 필요시 PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW 에 추가하여 사용 End */
    /* [PJ2025-50188] 임시테이블 #T_MKT_FCST DROP 추가 */
    /* [PJ2025-50188] 임시테이블 #T_MKT_FCST ==> #T_MF_BALANCE_MKT_FCST 변경 */
    /* [PJ2025-50188] 임시테이블 #T_SCP_PLN_RTF_ALLOCATION_V DROP */
    /* IF OBJECT_ID (N'tempdb..#T_SCP_PLN_RTF_ALLOCATION_V', N'U') IS NOT NULL */
    /* DROP TABLE #T_SCP_PLN_RTF_ALLOCATION_V */
    /* [PJ2025-50188] 임시테이블 #T_SCP_PLN_RTF_ALLOCATION_V ==> #T_MF_RTF_ALLOCATION 이름변경 */
    /* 2020.3.3 */
    /* [C20200827-000351] SSP Shipment Req 프로시저 호출 제외 */
    /*
    			IF ISNUMERIC(@p_plan_id) > 0
    			BEGIN
    				EXEC DMF0045_SCPSHIPPLAN_TO_SHIPREQ @P_DIVISION_ID, @p_plan_id
    			END */
    /* 트랜잭션 (COMMIT) */
    /* COMMIT WORK; */
    /* 트랜잭션 (END) */
    /* ROLLBACK TRANSACTION MKT_FCST_QTY_BALANCE_CREATE; */
    /* ERROR LOG VALUE SAVE */
    /*-- 에러메시지 DISPLAY --*/
    /* [C20200909-000203] LOG 표준화 적용 */
    /* ROLLBACK TRANSACTION MKT_FCST_QTY_BALANCE_CREATE */
    /* ================================================================================================================ */

    /* ================================================================================================================ */
BEGIN
    V_PROC_INPUT := JSON_OBJECT('p_division_id' VALUE NVL(P_DIVISION_ID,'NULL'), 'p_plan_id' VALUE NVL(P_PLAN_ID,'NULL'));
    V_P_PLAN_ID  := P_PLAN_ID;

    /* ================================================================================================================ */

    /* ================================================================================================================ */
    /* GTT 초기화 : TRUNCATE 는 DDL 이라 암시 COMMIT 이 발생해 상위 트랜잭션의 ROLLBACK 을 무력화한다 -> DELETE 사용 */
    DELETE FROM GT_PRDM2_RESULTS;
    DELETE FROM GT_PRDM2_MST_ACCUM;
    DELETE FROM GT_PRDM2_MST;
    DELETE FROM GT_PRDM2_TEMPX;
    DELETE FROM GT_PRDM2_VMI_MST;
    DELETE FROM GT_PRDM2_VMI_MST_MAIN;
    DELETE FROM GT_PRDM2_VMI_TEMP1;
    DELETE FROM GT_PRDM2_VMI_TEMP2;
    DELETE FROM GT_PRDM2_VMI_TEMP_ALL;
    DELETE FROM GT_PRDM2_MKT_FCST_INSERT;
    DELETE FROM GT_PRDM2_CUTOFF;
    DELETE FROM GT_PRDM2_FP_STOCK_QTY;
    DELETE FROM GT_PRDM2_SSLVL;
    DELETE FROM GT_PRDM2_MF_BALANCE_MKT_FCST;
    DELETE FROM GT_PRDM2_RTF_EXCEPTION_ITEM;
    DELETE FROM GT_PRDM2_MF_RTF_ALLOCATION;
    DELETE FROM GT_PRDM2_CFM_DEMAND_INSERT;
    DELETE FROM GT_PRDM2_TEMP_SALES_PLAN_C;
    DELETE FROM GT_PRDM2_TEMP_MKT_FCST_C;

    /* ================================================================================================================ */
    /* 시작 LOG (START) */
    /* ================================================================================================================ */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########11';
    V_DESCRIPTION := 'p_division_id : ' || NVL(P_DIVISION_ID,'NULL') || ' / ' || 'p_plan_id : ' || NVL(P_PLAN_ID,'NULL');
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
    V_LOG_MESSAGE := NULL;

    /* ================================================================================================================ */
    /* 변수값 셋팅 */
    /* ================================================================================================================ */
    /* 당주월요일 (한주가 지나면 화면에서 과거 RTF P 를 보기 어렵기 때문에 당주 월요일 이후로만 계산 함) */
    V_PLAN_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD');
    C_PLAN_START_YYYYMMDD := V_PLAN_START_YYYYMMDD;
    C_DIVISION_ID         := P_DIVISION_ID;
    C_SCP_DIVISION_ID     := P_DIVISION_ID;

    IF V_P_PLAN_ID IS NULL THEN
        V_P_PLAN_ID    := '';
        V_BATCH_CALL_YN := 'Y';
    END IF;

    /* [C20200827-000094] 자동차 전극 RTF를 매출계획에 반영(SCP Division) */
    /* [E20241211-000856]_40사업부 전극 RTF 적용가능하도록 수정요청으로 EE로 들어오는 건에 대해 해결 방안을 수정한다. START */
    IF V_P_PLAN_ID <> 'CALL' THEN
        IF C_DIVISION_ID = 'EE' THEN
            /* [E20251111-000455]_40사업부 전극 MA RTF 미반영 요청 원소스 주석 후 데이터 처리 (START) */
            V_LOG_TYPE   := 'INVALID';
            V_DESCRIPTION := '[E20251111-000455]_EE는 반영하지 않으므로 프로시져 수행하지 않고 종료함';
            BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, '########## INVALID of procedure ##########', V_DESCRIPTION, SYSDATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            D_EVENT_DATE  := SYSDATE;
            BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
            OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'INVALID' AS MESSAGE FROM DUAL;
            RETURN;
            /* [E20251111-000455]_40사업부 전극 MA RTF 미반영 요청 원소스 주석 후 데이터 처리 (END) */
        ELSIF C_DIVISION_ID = 'EE_UC' THEN
            C_DIVISION_ID     := '81_UC';
            C_SCP_DIVISION_ID := 'EE_UC';
        ELSIF C_DIVISION_ID = 'EE_HM' THEN
            C_DIVISION_ID     := '81_HM';
            C_SCP_DIVISION_ID := 'EE_HM';
        ELSIF C_DIVISION_ID = 'EE_ST' THEN
            C_DIVISION_ID     := '81_ST';
            C_SCP_DIVISION_ID := 'EE_ST';
        ELSIF C_DIVISION_ID = 'EE_HD' THEN
            C_DIVISION_ID     := '81_HD';
            C_SCP_DIVISION_ID := 'EE_HD';
        ELSIF C_DIVISION_ID = 'EE_HG' THEN
            C_DIVISION_ID     := '81_HG';
            C_SCP_DIVISION_ID := 'EE_HG';
        END IF;

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [E20260331-000648]_당주 월요일이후, SALES PLAN CUTOFF 데이터가 존재하는 경우에만 수정한 RTF를 적용한다. (START) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        IF (P_DIVISION_ID = '40' OR SUBSTR(P_DIVISION_ID, 1, 2) = '81') THEN
            BEGIN
                SELECT CASE WHEN A.CNT > 0 THEN 'Y' ELSE 'N' END
                  INTO V_SP_CUTOFF_FLAG
                  FROM (SELECT COUNT(*) AS CNT
                          FROM DM_MST_VERSION
                         WHERE DIVISION_ID   = P_DIVISION_ID
                           AND VERSION_TYPE  = 'SP_W'
                           AND YYYYMMDD     >= V_PLAN_START_YYYYMMDD) A;
            EXCEPTION WHEN NO_DATA_FOUND THEN
                V_SP_CUTOFF_FLAG := 'N';
            END;
        ELSE
            V_SP_CUTOFF_FLAG := 'N';
        END IF;
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [E20260331-000648] (END) */
        /* ---------------------------------------------------------------------------------------------------------------- */
    END IF;

    /* ================================================================================================================ */
    /* 중장기 계획 주차 기간 */
    /* ================================================================================================================ */
    BEGIN
        SELECT TO_NUMBER(ATTRIBUTE1)
          INTO N_PLAN_WEEK_CNT
          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
         WHERE LOOKUP_TYPE = 'DM_LONG_PLAN_WEEK_CNT'
           AND VALID_YN    = 'Y'
           AND SEGMENT1    = C_DIVISION_ID
           AND ROWNUM      = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN
        N_PLAN_WEEK_CNT := 54;
    END;

    IF N_PLAN_WEEK_CNT IS NULL THEN
        N_PLAN_WEEK_CNT := 54;
    END IF;

    /* ================================================================================================================ */
    /* [PJ2025-50188] 40사업부는 SCM_FCST / 그외는 MKT_FCST. */
    /* ================================================================================================================ */
    IF P_DIVISION_ID = '40' THEN
        V_MEASURE := 'SCM_FCST';
    ELSE
        V_MEASURE := 'MKT_FCST';
    END IF;

    /* ================================================================================================================ */

    /* ================================================================================================================ */
    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := 'step - A001 ';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
    V_LOG_MESSAGE := NULL;

    /* ================================================================================================================ */
    /* 대상추출 */
    /* ================================================================================================================ */
    /* @p_plan_id = 'CALL'인 경우는 MKT FCST 화면에서 호출하는 경우 */
    /* ================================================================================================================ */
    IF V_P_PLAN_ID = 'CALL' THEN
        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A002 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* 화면에서 던져진 데이터를 TEMP 테이블에 넣는다 (START) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM2_RESULTS
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, VMI_YN, CELL_PROD_SITE_ID, FROM_SITE_ID )
        SELECT DISTINCT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, VMI_YN
             , CELL_PROD_SITE_ID, '-' AS FROM_SITE_ID
          FROM GT_PRDM_SEND_TARGET_DATA
         WHERE FCST_TYPE <> 'RMA';

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_RESULTS');
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* 화면에서 던져진 데이터를 TEMP 테이블에 넣는다 (END) */
        /* ---------------------------------------------------------------------------------------------------------------- */
    ELSE
        /* @p_plan_id = ''인 경우는 DAILY CUTOFF시에 호출하는 경우 */
        IF V_P_PLAN_ID IS NULL THEN
            BEGIN
                /* [E20261007-PERF] 뷰(SCP_PLN_RTF_ALLOCATION_V) 1회 평가로 MAX(PLAN_ID) 와 그 PLAN 의 MAX(PLAN_START_YYYYMMDD) 를 함께 구한다.
                   KEEP (DENSE_RANK LAST ORDER BY PLAN_ID) = "PLAN_ID 가 최대인 행들의 MAX(PLAN_START_YYYYMMDD)" 로 아래 재평가 질의와 동치.
                   (클라우드 10-07 실측 A001→A007 구간 뷰 4회 평가 → 2회) */
                SELECT NVL(MAX(PLAN_ID), '')
                     , NVL(MAX(PLAN_START_YYYYMMDD) KEEP (DENSE_RANK LAST ORDER BY PLAN_ID), '')
                  INTO V_MAX_PLAN_ID, V_MAX_PLAN_START_PRE
                  FROM SCP_PLN_RTF_ALLOCATION_V
                 WHERE DIVISION_ID = P_DIVISION_ID;
            EXCEPTION WHEN NO_DATA_FOUND THEN
                V_MAX_PLAN_ID        := '';
                V_MAX_PLAN_START_PRE := '';
            END;
            V_P_PLAN_ID             := V_MAX_PLAN_ID;
            V_MAX_PLAN_START_PRE_YN := 'Y';
        END IF;

        /* DIVISION_ID, PLAN_ID 값이 없으면 수행하지 않음 */
        DECLARE
            N_DIV_CNT  NUMBER;
        BEGIN
            SELECT COUNT(1)
              INTO N_DIV_CNT
              FROM SCM_MST_DIVISION
             WHERE DIVISION_ID = P_DIVISION_ID;
            IF N_DIV_CNT = 0 OR V_P_PLAN_ID IS NULL THEN
                V_LOG_TYPE    := 'INVALID';
                V_DESCRIPTION := 'p_division_id : ' || NVL(P_DIVISION_ID,'NULL') || ' / ' || 'p_plan_id : ' || NVL(P_PLAN_ID,'NULL');
                BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, '########## INVALID of procedure ##########', V_DESCRIPTION, SYSDATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
                V_LOG_TYPE    := 'END';
                V_LOG_MESSAGE := '########## END of procedure ##########';
                BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, SYSDATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
                OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'INVALID' AS MESSAGE FROM DUAL;
                RETURN;
            END IF;
        END;

        /* [C20210215-000212] SCP에서 계획을 수립하지 않는 주차는 마지막 계획수립 주차 RTF 적용 */
        IF V_MAX_PLAN_START_PRE_YN = 'Y' THEN
            /* [E20261007-PERF] 배치 경로(P_PLAN_ID NULL): 위 L1391 평가에서 확보한 값 사용 (V_P_PLAN_ID = MAX(PLAN_ID) 이므로 동치) */
            V_MAX_PLAN_START_YYYYMMDD := V_MAX_PLAN_START_PRE;
        ELSE
            BEGIN
                SELECT NVL(MAX(PLAN_START_YYYYMMDD), '')
                  INTO V_MAX_PLAN_START_YYYYMMDD
                  FROM SCP_PLN_RTF_ALLOCATION_V
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND PLAN_ID     = V_P_PLAN_ID;
            EXCEPTION WHEN NO_DATA_FOUND THEN
                V_MAX_PLAN_START_YYYYMMDD := '';
            END;
        END IF;

        BEGIN
            SELECT NVL(MAX(DM_RTF_YN), 'Y')
              INTO C_SCP_RTF_FLAG
              FROM SCP_PLN_INTERFACE_YN
             WHERE DIVISION_ID         = C_SCP_DIVISION_ID
               AND PLAN_START_YYYYMMDD = V_MAX_PLAN_START_YYYYMMDD;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            C_SCP_RTF_FLAG := 'Y';
        END;

        IF C_SCP_RTF_FLAG = 'N' THEN
            /* [C20210215-000212] SCP에서 계획을 수립하지 않는 주차는 마지막 계획수립 주차 RTF 적용 */
            BEGIN
                SELECT MAX(PLAN_ID)
                  INTO C_PLAN_ID
                  FROM SCM_MST_PLAN
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND PLAN_CYCLE  = 'WEEKLY'
                   AND PLAN_NAME   = (SELECT MAX(PLAN_START_YYYYMMDD)
                                        FROM SCP_PLN_INTERFACE_YN
                                       WHERE DIVISION_ID         = P_DIVISION_ID
                                         AND PLAN_START_YYYYMMDD < V_MAX_PLAN_START_YYYYMMDD
                                         AND DM_RTF_YN           = 'Y');
            EXCEPTION WHEN NO_DATA_FOUND THEN
                C_PLAN_ID := NULL;
            END;
            V_LOG_TYPE    := 'ING';
            V_LOG_MESSAGE := 'SCP에서 계획을 수립하지 않는 주차는 마지막 계획수립 주차 RTF 적용';
            V_DESCRIPTION := 'p_division_id : ' || NVL(P_DIVISION_ID,'NULL') || ' / ' || 'c_plan_id : ' || NVL(C_PLAN_ID,'NULL');
            D_EVENT_DATE  := SYSDATE;
            BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        ELSE
            C_PLAN_ID := V_P_PLAN_ID;
        END IF;

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [E20260331-000648]_사용자가 수정한 이력이 있는 데이터를 TEMP에 담는다. (START) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        IF V_SP_CUTOFF_FLAG = 'Y' THEN
            IF P_DIVISION_ID = '40' THEN
                /* 사용자가 변경하는 값은 해당 시점에 데이터가 변경되기때문에 변경때 변경되는 메져 3개는 당주 월요일 이후 수정건에 대한 내역 추출 */
                INSERT INTO GT_PRDM2_RTF_EXCEPTION_ITEM
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID )
                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
                  FROM DM_PLN_CFM_MKT_DEMAND_PLAN
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                   AND TO_CHAR(LAST_UPDATE_DATE, 'YYYYMMDD') >= V_PLAN_START_YYYYMMDD
                   AND MEASURE IN ('RTF_SYS_RP', 'RTF', 'RTF_SCP')
                   AND LAST_UPDATED_BY NOT IN ('SYSTEM','CUTOFF')
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID;

                /* RTF_PR메져는 SCP의 FINAL값을 반영하는 부분으로, 수정된 대상들을 가지고 조회한다. */
                INSERT INTO GT_PRDM2_RTF_EXCEPTION_ITEM
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID )
                SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                     , A.MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID
                  FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
                     , GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID       = B.DIVISION_ID
                   AND A.PROJECT_CODE      = B.PROJECT_CODE
                   AND A.SCM_SITE_ID       = B.SCM_SITE_ID
                   AND A.ITEM_ID           = B.ITEM_ID
                   AND A.DOM_EXP           = B.DOM_EXP
                   AND A.FCST_TYPE         = B.FCST_TYPE
                   AND A.INCOTERMS         = B.INCOTERMS
                   AND A.PLANT_SITE_ID     = B.PLANT_SITE_ID
                   AND A.CELL_PROD_SITE_ID = B.CELL_PROD_SITE_ID
                   AND A.MEASURE = 'RTF_PR'
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                        , A.MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID;
            ELSE
                INSERT INTO GT_PRDM2_RTF_EXCEPTION_ITEM
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID )
                SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
                     , MEASURE, PLANT_SITE_ID, '-' AS CELL_PROD_SITE_ID
                  FROM DM_PLN_MKT_FCST
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                   AND TO_CHAR(LAST_UPDATE_DATE, 'YYYYMMDD') >= V_PLAN_START_YYYYMMDD
                   AND MEASURE IN ('RTF_SYS_RP', 'RTF', 'RTF_SCP')
                   AND LAST_UPDATED_BY NOT IN ('SYSTEM','CUTOFF')
                 GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID;

                INSERT INTO GT_PRDM2_RTF_EXCEPTION_ITEM
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID )
                SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                     , A.MEASURE, A.PLANT_SITE_ID, '-' AS CELL_PROD_SITE_ID
                  FROM DM_PLN_MKT_FCST A
                     , GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID   = B.DIVISION_ID
                   AND A.PROJECT_CODE  = B.PROJECT_CODE
                   AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                   AND A.ITEM_ID       = B.ITEM_ID
                   AND A.DOM_EXP       = B.DOM_EXP
                   AND A.FCST_TYPE     = B.FCST_TYPE
                   AND A.INCOTERMS     = B.INCOTERMS
                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                   AND A.MEASURE = 'RTF_PR'
                 GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID;
            END IF;
            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_RTF_EXCEPTION_ITEM');
        END IF;
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [E20260331-000648]_사용자가 수정한 이력이 있는 데이터를 TEMP에 담는다. (END) */
        /* ---------------------------------------------------------------------------------------------------------------- */

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] DM_PLN_CFM_MKT_DEMAND_PLAN / DM_PLN_MKT_FCST => 임시 테이블에 담음 (START) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID = '40' THEN
            INSERT INTO GT_PRDM2_MF_BALANCE_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
            , CELL_PROD_SITE_ID, FROM_SITE_ID, MEASURE, YYYYMMDD, QTY )
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                 , CELL_PROD_SITE_ID, ATTRIBUTE2 AS FROM_SITE_ID, MEASURE, YYYYMMDD, QTY
              FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE DIVISION_ID = P_DIVISION_ID
               AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
               AND MEASURE IN ('MKT_FCST','SCM_FCST','VMI_In_Req','AS_In_Req','BALANCE','RTF_SYS_RP','RTF_SCP','RTF','VMI_Inv');
        ELSE
            INSERT INTO GT_PRDM2_MF_BALANCE_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
            , CELL_PROD_SITE_ID, FROM_SITE_ID, MEASURE, YYYYMMDD, QTY )
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                 , '-' AS CELL_PROD_SITE_ID, '-' AS FROM_SITE_ID, MEASURE, YYYYMMDD, QTY
              FROM DM_PLN_MKT_FCST
             WHERE DIVISION_ID = P_DIVISION_ID
               AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
               AND MEASURE IN ('MKT_FCST','SCM_FCST','VMI_In_Req','AS_In_Req','BALANCE','RTF_SYS_RP','RTF_SCP','RTF','VMI_Inv');
        END IF;
        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MF_BALANCE_MKT_FCST');

        /* [E20260331-000648]_사용자가 수정한 이력이 존재하는 데이터는 추가 작업을 진행하지 않는다. */
        DELETE FROM GT_PRDM2_MF_BALANCE_MKT_FCST A
         WHERE EXISTS
               (SELECT 1 FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID   = B.DIVISION_ID
                   AND A.PROJECT_CODE  = B.PROJECT_CODE
                   AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                   AND A.ITEM_ID       = B.ITEM_ID
                   AND A.DOM_EXP       = B.DOM_EXP
                   AND A.FCST_TYPE     = B.FCST_TYPE
                   AND A.INCOTERMS     = B.INCOTERMS
                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID);

        /* ================================================================================================================ */
        /* [PJ2025-50017] SCP_PLN_RTF_ALLOCATION_V => GT_PRDM2_MF_RTF_ALLOCATION 데이터 INSERT
           [E20261007-PERF] 원위치(END IF 뒤)에서 이동 — 아래 GT_PRDM2_RESULTS 적재의 UNION 분기가 이 GTT 를 재사용해 뷰 재평가를 생략한다. 조건·컬럼 원문 그대로. */
        /* ================================================================================================================ */
        INSERT INTO GT_PRDM2_MF_RTF_ALLOCATION
        ( MASTER_ID, PLAN_ID, OUT_VERSION_ID, DIVISION_ID, ORIGIN_DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, ENG_DEMAND_ID
        , ITEM_ID, PROJECT_CODE, SALES_SITE_ID, INCOTERMS, DOM_EXP, FCST_TYPE, DEMAND_TYPE, DUE_DATE, PLANT_SITE_ID, YYYYMMDD
        , ALLOCATION_QTY, DELIVERY_ORDER_ID, FROM_SITE, FROM_ITEM_ID, SCP_INCOTERMS, FROM_SITE_ID, CELL_PROD_SITE_ID )
        SELECT MASTER_ID, PLAN_ID, OUT_VERSION_ID, DIVISION_ID, ORIGIN_DIVISION_ID, PLAN_START_YYYYMMDD, PLAN_TYPE, SEQ, OPERATION_GROUP, ENG_DEMAND_ID
             , ITEM_ID, PROJECT_CODE, SALES_SITE_ID, INCOTERMS, DOM_EXP, FCST_TYPE, DEMAND_TYPE, DUE_DATE, PLANT_SITE_ID, YYYYMMDD
             , ALLOCATION_QTY, DELIVERY_ORDER_ID, FROM_SITE, FROM_ITEM_ID, SCP_INCOTERMS, FROM_SITE_ID, CELL_PROD_SITE_ID
          FROM SCP_PLN_RTF_ALLOCATION_V
         WHERE DIVISION_ID        = C_SCP_DIVISION_ID
           AND ORIGIN_DIVISION_ID = C_DIVISION_ID
           AND PLAN_ID            = C_PLAN_ID
           AND YYYYMMDD          >= C_PLAN_START_YYYYMMDD;

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MF_RTF_ALLOCATION');

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* DM_PLN_CFM_MKT_DEMAND_PLAN / DM_PLN_MKT_FCST 담은 데이터와, 전극으로 발생한 데이터를 임시 테이블에 담는다. */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM2_RESULTS
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, VMI_YN, CELL_PROD_SITE_ID, FROM_SITE_ID )
        SELECT DISTINCT DIVISION_ID
             , PROJECT_CODE, SCM_SITE_ID, ITEM_ID
             , DOM_EXP, FCST_TYPE, INCOTERMS
             , PLANT_SITE_ID, 'N' AS VMI_YN
             , CASE WHEN P_DIVISION_ID = '40' THEN CELL_PROD_SITE_ID ELSE '-' END AS CELL_PROD_SITE_ID
             , CASE WHEN P_DIVISION_ID = '40' THEN MAX(FROM_SITE_ID) ELSE '-' END AS FROM_SITE_ID
          FROM GT_PRDM2_MF_BALANCE_MKT_FCST
         WHERE YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')
           AND MEASURE IN (V_MEASURE, 'RTF', 'RTF_SCP', 'BALANCE', 'VMI_Inv')
           AND FCST_TYPE  <> 'RMA'
           AND DIVISION_ID = C_DIVISION_ID
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
        UNION
        /* [C20200827-000094] 자동차 전극 RTF를 매출계획에 반영 */
        SELECT ORIGIN_DIVISION_ID AS DIVISION_ID
             , PROJECT_CODE
             , SALES_SITE_ID
             , CASE WHEN FROM_ITEM_ID IS NULL THEN ITEM_ID ELSE FROM_ITEM_ID END AS ITEM_ID
             , DOM_EXP, FCST_TYPE, INCOTERMS
             , CASE WHEN ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE PLANT_SITE_ID END PLANT_SITE_ID
             , 'N' AS VMI_YN
             , CASE WHEN P_DIVISION_ID = '40' THEN CELL_PROD_SITE_ID ELSE '-' END AS CELL_PROD_SITE_ID
             , CASE WHEN P_DIVISION_ID = '40' THEN MAX(FROM_SITE_ID) ELSE '-' END AS FROM_SITE_ID
          FROM GT_PRDM2_MF_RTF_ALLOCATION   /* [E20261007-PERF] SCP_PLN_RTF_ALLOCATION_V → 위에서 같은 조건으로 적재한 GTT 재사용 (뷰 재평가 생략). WHERE 는 원문 유지 */
         WHERE DIVISION_ID      = C_SCP_DIVISION_ID
           AND ORIGIN_DIVISION_ID = C_DIVISION_ID
           AND PLAN_ID          = C_PLAN_ID
           AND YYYYMMDD        >= C_PLAN_START_YYYYMMDD
         GROUP BY ORIGIN_DIVISION_ID, PROJECT_CODE, SALES_SITE_ID
                , CASE WHEN FROM_ITEM_ID IS NULL THEN ITEM_ID ELSE FROM_ITEM_ID END
                , DOM_EXP, FCST_TYPE, INCOTERMS
                , CASE WHEN ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE PLANT_SITE_ID END
                , YYYYMMDD, CELL_PROD_SITE_ID;

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_RESULTS');

        /* [E20260331-000648]_사용자가 수정한 이력이 존재하는 데이터는 추가 작업을 진행하지 않는다. */
        DELETE FROM GT_PRDM2_RESULTS A
         WHERE EXISTS
               (SELECT 1 FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID   = B.DIVISION_ID
                   AND A.PROJECT_CODE  = B.PROJECT_CODE
                   AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                   AND A.ITEM_ID       = B.ITEM_ID
                   AND A.DOM_EXP       = B.DOM_EXP
                   AND A.FCST_TYPE     = B.FCST_TYPE
                   AND A.INCOTERMS     = B.INCOTERMS
                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID);
    END IF;

    /* ================================================================================================================ */
    /* [PJ2025-50017] SCP_PLN_RTF_ALLOCATION_V => GT_PRDM2_MF_RTF_ALLOCATION 데이터 INSERT
       [E20261007-PERF] 이 적재를 위 ELSE 분기(GT_PRDM2_RESULTS 적재 직전)로 이동. 화면 CALL 경로는 C_PLAN_ID 가 NULL 이라 원래도 0건 적재였음. */
    /* ================================================================================================================ */

    /* ================================================================================================================ */
    /* SCM_MST_SITE테이블의 VMI대상을 컬럼에 셋팅 */
    /* ================================================================================================================ */
    UPDATE GT_PRDM2_RESULTS
       SET VMI_YN = 'Y'
     WHERE EXISTS (SELECT 1
                     FROM SCM_MST_SITE C
                    WHERE GT_PRDM2_RESULTS.DIVISION_ID = C.DIVISION_ID
                      AND GT_PRDM2_RESULTS.DIVISION_ID IN (SELECT DIVISION_ID FROM SCM_MST_DIVISION WHERE ATTRIBUTE3 IN ('40','81','82'))
                      AND GT_PRDM2_RESULTS.SCM_SITE_ID = C.SCM_SITE_ID
                      AND C.VMI_YN = 'Y');


    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := 'step - A007 ';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
    V_LOG_MESSAGE := NULL;

    /* ================================================================================================================ */
    /* 화면에서 저장할때가 아닌경우 처리하는 로직 (DAILY CUTOFF / 엔진 완료 후 수행작업) */
    /* ================================================================================================================ */
    IF V_P_PLAN_ID <> 'CALL' THEN
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* MKT_FCST, RTF 대상 날짜및 값 추출 (START) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* RTF MEASURE MKT_FCST TABLE INSERT (START) */
        /* [C20200827-000094] 자동차 전극 RTF를 매출계획에 반영 */
        IF C_SCP_DIVISION_ID LIKE 'EE%' THEN
            /* ---------------------------------------------------------------------------------------------------------------- */
            /* 전극이고, RMA가 아닌 데이터에 대해서 특정 메져에 대해서 당주 월요일 이후 데이터 삭제 진행 (START) */
            /* ---------------------------------------------------------------------------------------------------------------- */
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'VMI_IN_PLAN', 'AS_IN_PLAN', 'RTF_PR', 'RTF')
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE  <> 'RMA'
               AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
               AND EXISTS (SELECT 1 ITEM_ID FROM SCM_MST_FINAL_ITEM_V
                            WHERE DM_PLN_MKT_FCST.DIVISION_ID = SCM_MST_FINAL_ITEM_V.DIVISION_ID
                              AND DM_PLN_MKT_FCST.ITEM_ID     = SCM_MST_FINAL_ITEM_V.ITEM_ID
                              AND SCM_MST_FINAL_ITEM_V.OPERATION_GROUP_ID = 'E')
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_MKT_FCST.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_MKT_FCST.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_MKT_FCST.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_MKT_FCST.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_MKT_FCST.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_MKT_FCST.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_MKT_FCST.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_MKT_FCST.MEASURE       = A.MEASURE
                                  AND DM_PLN_MKT_FCST.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'VMI_IN_PLAN', 'AS_IN_PLAN', 'RTF_PR', 'RTF')
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE  <> 'RMA'
               AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
               AND EXISTS (SELECT 1 ITEM_ID FROM SCM_MST_FINAL_ITEM_V
                            WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = SCM_MST_FINAL_ITEM_V.DIVISION_ID
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID     = SCM_MST_FINAL_ITEM_V.ITEM_ID
                              AND SCM_MST_FINAL_ITEM_V.OPERATION_GROUP_ID = 'E')
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.MEASURE       = A.MEASURE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND CASE WHEN DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = '40' THEN NVL(DM_PLN_CFM_MKT_DEMAND_PLAN.CELL_PROD_SITE_ID,'-') ELSE '-' END = NVL(A.CELL_PROD_SITE_ID,'/')
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);
        ELSE
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF', 'VMI_In_Plan', 'AS_In_Plan', 'RTF_PR')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE  <> 'RMA'
               AND NOT EXISTS (SELECT 1 ITEM_ID FROM SCM_MST_FINAL_ITEM_V
                                WHERE DM_PLN_MKT_FCST.DIVISION_ID = SCM_MST_FINAL_ITEM_V.DIVISION_ID
                                  AND DM_PLN_MKT_FCST.ITEM_ID     = SCM_MST_FINAL_ITEM_V.ITEM_ID
                                  AND DM_PLN_MKT_FCST.YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                                  AND SCM_MST_FINAL_ITEM_V.OPERATION_GROUP_ID = 'E'
                                  AND SCM_MST_FINAL_ITEM_V.DIVISION_ID LIKE '40%')
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_MKT_FCST.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_MKT_FCST.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_MKT_FCST.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_MKT_FCST.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_MKT_FCST.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_MKT_FCST.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_MKT_FCST.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_MKT_FCST.MEASURE       = A.MEASURE
                                  AND DM_PLN_MKT_FCST.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            /* [C20201208-000087] ESS 'RTF'(RTF_MKT) */
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE     IN ('RTF')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND DIVISION_ID = '82'
               AND FCST_TYPE  <> 'RMA';

            /* RMA 수정 C20200518-000359 */
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF_PR')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE   = 'RMA'
               AND DIVISION_ID = '40'
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_MKT_FCST.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_MKT_FCST.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_MKT_FCST.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_MKT_FCST.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_MKT_FCST.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_MKT_FCST.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_MKT_FCST.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_MKT_FCST.MEASURE       = A.MEASURE
                                  AND DM_PLN_MKT_FCST.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            IF P_DIVISION_ID LIKE '81%' THEN
                DELETE FROM DM_PLN_MKT_FCST
                 WHERE MEASURE IN ('SS_LVL', 'SS_GAP')
                   AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
                   AND DIVISION_ID = P_DIVISION_ID;
            END IF;

            DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE MEASURE IN ('RTF_SYS_RP','RTF_SCP','RTF','VMI_In_Plan','AS_In_Plan','RTF_PR')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE  <> 'RMA'
               AND NOT EXISTS (SELECT 1 ITEM_ID FROM SCM_MST_FINAL_ITEM_V
                                WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = SCM_MST_FINAL_ITEM_V.DIVISION_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID     = SCM_MST_FINAL_ITEM_V.ITEM_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                                  AND SCM_MST_FINAL_ITEM_V.OPERATION_GROUP_ID = 'E'
                                  AND SCM_MST_FINAL_ITEM_V.DIVISION_ID LIKE '40%')
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.MEASURE       = A.MEASURE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND CASE WHEN DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = '40' THEN NVL(DM_PLN_CFM_MKT_DEMAND_PLAN.CELL_PROD_SITE_ID,'-') ELSE '-' END = NVL(A.CELL_PROD_SITE_ID,'/')
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            /* [C20201208-000087] */
            DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE MEASURE     IN ('RTF')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND DIVISION_ID = '82'
               AND FCST_TYPE  <> 'RMA';

            /* RMA */
            DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE MEASURE IN ('RTF_SYS_RP', 'RTF_SCP', 'RTF_PR')
               AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
               AND DIVISION_ID = C_DIVISION_ID
               AND FCST_TYPE   = 'RMA'
               AND DIVISION_ID = '40'
               AND NOT EXISTS (SELECT 1
                                 FROM GT_PRDM2_RTF_EXCEPTION_ITEM A
                                WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID   = A.DIVISION_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE  = A.PROJECT_CODE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID   = A.SCM_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID       = A.ITEM_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP       = A.DOM_EXP
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE     = A.FCST_TYPE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS     = A.INCOTERMS
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.MEASURE       = A.MEASURE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID = A.PLANT_SITE_ID
                                  AND CASE WHEN DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = '40' THEN NVL(DM_PLN_CFM_MKT_DEMAND_PLAN.CELL_PROD_SITE_ID,'-') ELSE '-' END = NVL(A.CELL_PROD_SITE_ID,'/')
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            IF P_DIVISION_ID LIKE '81%' THEN
                DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
                 WHERE MEASURE IN ('SS_LVL', 'SS_GAP')
                   AND YYYYMMDD   >= C_PLAN_START_YYYYMMDD
                   AND DIVISION_ID = P_DIVISION_ID;
            END IF;
        END IF;


        /* ---------------------------------------------------------------------------------------------------------------- */
        /* GT_PRDM2_MKT_FCST_INSERT INSERT (from GT_PRDM2_MF_RTF_ALLOCATION INNER JOIN SCM_MST_SITE) */
        /* ---------------------------------------------------------------------------------------------------------------- */
        /* First part: from allocation view */
        /* [TUNING 2026-06-23] 본 job이 직전에 DM_PLN_MKT_FCST를 대량 변경 → 무거운 SELECT 전에 */

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'DM_PLN_MKT_FCST', NO_INVALIDATE => FALSE);

        INSERT INTO GT_PRDM2_MKT_FCST_INSERT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT A.ORIGIN_DIVISION_ID AS DIVISION_ID
             , A.PROJECT_CODE
             , A.SALES_SITE_ID AS SCM_SITE_ID
             , CASE WHEN A.FROM_ITEM_ID IS NULL THEN A.ITEM_ID ELSE A.FROM_ITEM_ID END AS ITEM_ID
             , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
             , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('82','40') THEN 'VMI_In_Plan'
                    WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan'
                    ELSE 'RTF_SCP' END MEASURE
             , CASE WHEN A.ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE A.PLANT_SITE_ID END PLANT_SITE_ID
             , A.YYYYMMDD
             , SUM(A.ALLOCATION_QTY) AS QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM GT_PRDM2_MF_RTF_ALLOCATION A
             , SCM_MST_SITE C
         WHERE A.ORIGIN_DIVISION_ID = C.DIVISION_ID
           AND A.SALES_SITE_ID      = C.SCM_SITE_ID
           AND A.DIVISION_ID        = C_SCP_DIVISION_ID
           AND A.ORIGIN_DIVISION_ID = C_DIVISION_ID
           AND A.PLAN_ID            = C_PLAN_ID
           AND A.YYYYMMDD          >= C_PLAN_START_YYYYMMDD
         GROUP BY A.ORIGIN_DIVISION_ID, A.PROJECT_CODE, A.SALES_SITE_ID
                , CASE WHEN A.FROM_ITEM_ID IS NULL THEN A.ITEM_ID ELSE A.FROM_ITEM_ID END
                , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('82','40') THEN 'VMI_In_Plan' WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan' ELSE 'RTF_SCP' END
                , CASE WHEN A.ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE A.PLANT_SITE_ID END
                , A.YYYYMMDD, C.VMI_YN, C.OPERATION_GROUP, A.DIVISION_ID
        UNION ALL
        /* Second part: from DM_PLN_MKT_FCST for commodity/electrode items (82 division only) */
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
             , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
             , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Plan'
                    WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan'
                    ELSE 'RTF_SCP' END MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , SUM(CASE WHEN C.VMI_YN = 'Y' AND A.MEASURE = 'VMI_In_Req' THEN A.QTY
                        WHEN C.OPERATION_GROUP = 'W' AND A.MEASURE = 'AS_In_Req' THEN A.QTY
                        WHEN C.VMI_YN <> 'Y' AND A.MEASURE = V_MEASURE THEN A.QTY
                        ELSE 0 END) AS QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_MKT_FCST A
             , DM_MST_ITEM_SINGLE_V B
             , SCM_MST_SITE C
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND A.ITEM_ID     = B.ITEM_ID
           AND A.DIVISION_ID = C.DIVISION_ID
           AND A.SCM_SITE_ID = C.SCM_SITE_ID
           AND A.DIVISION_ID = C_SCP_DIVISION_ID
           AND A.YYYYMMDD   >= C_PLAN_START_YYYYMMDD
           AND A.FCST_TYPE  <> 'RMA'
           AND A.MEASURE = CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Req'
                                WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                ELSE V_MEASURE END
           AND (B.ITEM_TYPE IN ('Q','R') OR (A.ITEM_ID IN (SELECT K.ITEM_ID FROM SCM_MST_ITEM_SN K WHERE K.DIVISION_ID = A.DIVISION_ID AND K.SCP_OPERATION_GROUP = 'E'))
               AND A.DIVISION_ID IN ('82'))
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Plan' WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan' ELSE 'RTF_SCP' END
                , A.PLANT_SITE_ID, A.YYYYMMDD;

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MKT_FCST_INSERT');

        /* [E20260331-000648] 사용자가 수정한 이력이 존재하는 데이터는 추가 작업을 진행하지 않는다. */
        DELETE FROM GT_PRDM2_MKT_FCST_INSERT A
         WHERE EXISTS
               (SELECT 1 FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID   = B.DIVISION_ID
                   AND A.PROJECT_CODE  = B.PROJECT_CODE
                   AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                   AND A.ITEM_ID       = B.ITEM_ID
                   AND A.DOM_EXP       = B.DOM_EXP
                   AND A.FCST_TYPE     = B.FCST_TYPE
                   AND A.INCOTERMS     = B.INCOTERMS
                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID);

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* GT_PRDM2_CFM_DEMAND_INSERT INSERT */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO GT_PRDM2_CFM_DEMAND_INSERT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, FROM_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE
             , A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, MAX(A.FROM_SITE_ID) AS FROM_SITE_ID
             , A.YYYYMMDD, SUM(A.QTY) AS QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM (
            SELECT A.ORIGIN_DIVISION_ID AS DIVISION_ID
                 , A.PROJECT_CODE, A.SALES_SITE_ID AS SCM_SITE_ID
                 , CASE WHEN A.FROM_ITEM_ID IS NULL THEN A.ITEM_ID ELSE A.FROM_ITEM_ID END AS ITEM_ID
                 , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                 , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('82','40') THEN 'VMI_In_Plan'
                        WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan'
                        ELSE 'RTF_SCP' END MEASURE
                 , CASE WHEN A.ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE A.PLANT_SITE_ID END PLANT_SITE_ID
                 , NVL(A.CELL_PROD_SITE_ID, '/') AS CELL_PROD_SITE_ID
                 , CASE WHEN (A.ORIGIN_DIVISION_ID IN ('40') AND NVL(A.CELL_PROD_SITE_ID,  '/') = '/') THEN A.FROM_SITE_ID ELSE NVL(A.CELL_PROD_SITE_ID,'/') END AS FROM_SITE_ID
                 , A.YYYYMMDD, SUM(A.ALLOCATION_QTY) AS QTY
              FROM GT_PRDM2_MF_RTF_ALLOCATION A
                 , SCM_MST_SITE C
             WHERE A.ORIGIN_DIVISION_ID = C.DIVISION_ID
               AND A.SALES_SITE_ID      = C.SCM_SITE_ID
               AND A.DIVISION_ID        = C_SCP_DIVISION_ID
               AND A.ORIGIN_DIVISION_ID = C_DIVISION_ID
               AND A.PLAN_ID            = C_PLAN_ID
               AND A.YYYYMMDD          >= C_PLAN_START_YYYYMMDD
             GROUP BY A.ORIGIN_DIVISION_ID, A.PROJECT_CODE, A.SALES_SITE_ID
                    , CASE WHEN A.FROM_ITEM_ID IS NULL THEN A.ITEM_ID ELSE A.FROM_ITEM_ID END
                    , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                    , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('82','40') THEN 'VMI_In_Plan' WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan' ELSE 'RTF_SCP' END
                    , CASE WHEN A.ORIGIN_DIVISION_ID IN ('82','40') THEN ' ' ELSE A.PLANT_SITE_ID END
                    , A.YYYYMMDD, C.VMI_YN, C.OPERATION_GROUP, A.DIVISION_ID, NVL(A.CELL_PROD_SITE_ID,'/'), A.FROM_SITE_ID
          ) A
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.YYYYMMDD
        UNION ALL
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
             , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
             , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Plan'
                    WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan'
                    ELSE 'RTF_SCP' END MEASURE
             , A.PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID
             , '-' AS FROM_SITE_ID
             , A.YYYYMMDD
             , SUM(CASE WHEN C.VMI_YN = 'Y' AND A.MEASURE = 'VMI_In_Req' THEN A.QTY
                        WHEN C.OPERATION_GROUP = 'W' AND A.MEASURE = 'AS_In_Req' THEN A.QTY
                        WHEN C.VMI_YN <> 'Y' AND A.MEASURE = V_MEASURE THEN A.QTY
                        ELSE 0 END) AS QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_MKT_FCST A
             , DM_MST_ITEM_SINGLE_V B
             , SCM_MST_SITE C
         WHERE A.DIVISION_ID = B.DIVISION_ID AND A.ITEM_ID = B.ITEM_ID
           AND A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID
           AND A.DIVISION_ID = C_SCP_DIVISION_ID
           AND A.YYYYMMDD   >= C_PLAN_START_YYYYMMDD
           AND A.FCST_TYPE  <> 'RMA'
           AND A.MEASURE = CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Req'
                                WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                ELSE V_MEASURE END
           AND (B.ITEM_TYPE IN ('Q','R') OR (A.ITEM_ID IN (SELECT K.ITEM_ID FROM SCM_MST_ITEM_SN K WHERE K.DIVISION_ID = A.DIVISION_ID AND K.SCP_OPERATION_GROUP = 'E'))
               AND A.DIVISION_ID IN ('82'))
         GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                , CASE WHEN C.VMI_YN = 'Y' AND A.DIVISION_ID IN ('40','82') THEN 'VMI_In_Plan' WHEN C.OPERATION_GROUP = 'W' THEN 'AS_In_Plan' ELSE 'RTF_SCP' END
                , A.PLANT_SITE_ID, A.YYYYMMDD;

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_CFM_DEMAND_INSERT');

        /* [E20260331-000648] */
        DELETE FROM GT_PRDM2_CFM_DEMAND_INSERT A
         WHERE EXISTS
               (SELECT 1 FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                 WHERE A.DIVISION_ID   = B.DIVISION_ID
                   AND A.PROJECT_CODE  = B.PROJECT_CODE
                   AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                   AND A.ITEM_ID       = B.ITEM_ID
                   AND A.DOM_EXP       = B.DOM_EXP
                   AND A.FCST_TYPE     = B.FCST_TYPE
                   AND A.INCOTERMS     = B.INCOTERMS
                   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID);

        /* UPDATE CELL_PROD_SITE_ID 기본값 '-' */
        UPDATE GT_PRDM2_CFM_DEMAND_INSERT
           SET CELL_PROD_SITE_ID = '-'
         WHERE DIVISION_ID = '40'
           AND CELL_PROD_SITE_ID IS NULL
           AND MEASURE IN ('RTF','RTF_SYS_RP','RTF_SCP','RTF_PR');

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [C20210323-000456] ESS 판매법인의 VMI_IN_PLAN 에 대해서 5영업일 뒤로 미뤄줌 */
        /* ---------------------------------------------------------------------------------------------------------------- */
        UPDATE GT_PRDM2_MKT_FCST_INSERT
           SET YYYYMMDD = FN_GET_BIZ_DAY(YYYYMMDD
                        , TO_NUMBER((SELECT SEGMENT2
                                       FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                      WHERE LOOKUP_TYPE = 'ESS_SALES_PLANT_LT'
                                        AND VALID_YN   = 'Y'
                                        AND SEGMENT1   = GT_PRDM2_MKT_FCST_INSERT.SCM_SITE_ID
                                        AND TO_NUMBER(SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) > 0
                                        AND ROWNUM = 1)))
         WHERE DIVISION_ID = '82'
           AND MEASURE     = 'VMI_In_Plan'
           AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE L.LOOKUP_TYPE = 'ESS_SALES_PLANT_LT'
                          AND L.VALID_YN   = 'Y'
                          AND L.SEGMENT1   = GT_PRDM2_MKT_FCST_INSERT.SCM_SITE_ID
                          AND TO_NUMBER(L.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) > 0);

        UPDATE GT_PRDM2_CFM_DEMAND_INSERT
           SET YYYYMMDD = FN_GET_BIZ_DAY(YYYYMMDD
                        , TO_NUMBER((SELECT SEGMENT2
                                       FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                      WHERE LOOKUP_TYPE = 'ESS_SALES_PLANT_LT'
                                        AND VALID_YN   = 'Y'
                                        AND SEGMENT1   = GT_PRDM2_CFM_DEMAND_INSERT.SCM_SITE_ID
                                        AND TO_NUMBER(SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) > 0
                                        AND ROWNUM = 1)))
         WHERE DIVISION_ID = '82'
           AND MEASURE     = 'VMI_In_Plan'
           AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL L
                        WHERE L.LOOKUP_TYPE = 'ESS_SALES_PLANT_LT'
                          AND L.VALID_YN   = 'Y'
                          AND L.SEGMENT1   = GT_PRDM2_CFM_DEMAND_INSERT.SCM_SITE_ID
                          AND TO_NUMBER(L.SEGMENT2 DEFAULT NULL ON CONVERSION ERROR) > 0);

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* SAFETY STOCK LEVEL, GAP 메저 처리 */
        /* ---------------------------------------------------------------------------------------------------------------- */
        IF P_DIVISION_ID LIKE '81%' THEN
            INSERT INTO GT_PRDM2_SSLVL
            ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, INCOTERMS, PLANT_SITE_ID, DOM_EXP )
            SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.INCOTERMS, A.PLANT_SITE_ID, A.DOM_EXP
              FROM (SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.INCOTERMS, A.PLANT_SITE_ID, A.DOM_EXP
                         , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                                              ORDER BY A.PROJECT_CODE, A.INCOTERMS, A.PLANT_SITE_ID, A.DOM_EXP) AS ROW_NUM
                      FROM (SELECT DISTINCT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.INCOTERMS, A.PLANT_SITE_ID, A.DOM_EXP
                               FROM DM_PLN_MKT_FCST A
                              WHERE A.YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                                AND A.MEASURE IN (V_MEASURE, 'RTF_SYS_RP', 'VMI_IN_REQ', 'AS_IN_REQ', 'BNP_IN')
                                AND A.DIVISION_ID = P_DIVISION_ID) A) A
             WHERE ROW_NUM = 1;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_SSLVL');

            BEGIN
                SELECT MAX(SEQ)
                  INTO N_STOCK_SEQ
                  FROM SCP_ANL_PSI_GLOBAL_V
                 WHERE DIVISION_ID         = P_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
                   AND PLAN_TYPE           = 'FN';
            EXCEPTION WHEN NO_DATA_FOUND THEN
                N_STOCK_SEQ := NULL;
            END;

            INSERT INTO GT_PRDM2_MKT_FCST_INSERT
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
            , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, 'MPS' AS FCST_TYPE, A.INCOTERMS, C.MEASURE, A.PLANT_SITE_ID, B.YYYYMMDD
                 , CASE WHEN C.MEASURE = 'SS_LVL' THEN B.SAFETY_STOCK ELSE B.GAP END AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_SSLVL A
                 , SCP_ANL_PSI_GLOBAL_V B
                 , (SELECT 'SS_LVL' AS MEASURE FROM DUAL
                    UNION ALL
                    SELECT 'SS_GAP' AS MEASURE FROM DUAL) C
             WHERE A.DIVISION_ID         = B.DIVISION_ID
               AND A.SCM_SITE_ID         = B.TO_SITE
               AND A.ITEM_ID             = B.ITEM_ID
               AND B.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND B.PLAN_TYPE           = 'FN'
               AND B.SEQ                 = N_STOCK_SEQ
               AND A.DIVISION_ID = P_DIVISION_ID;

            INSERT INTO GT_PRDM2_CFM_DEMAND_INSERT
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY
            , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, 'MPS' AS FCST_TYPE, A.INCOTERMS, C.MEASURE, A.PLANT_SITE_ID, '-' AS CELL_PROD_SITE_ID, B.YYYYMMDD
                 , CASE WHEN C.MEASURE = 'SS_LVL' THEN B.SAFETY_STOCK ELSE B.GAP END AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_SSLVL A
                 , SCP_ANL_PSI_GLOBAL_V B
                 , (SELECT 'SS_LVL' AS MEASURE FROM DUAL
                    UNION ALL
                    SELECT 'SS_GAP' AS MEASURE FROM DUAL) C
             WHERE A.DIVISION_ID         = B.DIVISION_ID
               AND A.SCM_SITE_ID         = B.TO_SITE
               AND A.ITEM_ID             = B.ITEM_ID
               AND B.PLAN_START_YYYYMMDD = V_PLAN_START_YYYYMMDD
               AND B.PLAN_TYPE           = 'FN'
               AND B.SEQ                 = N_STOCK_SEQ
               AND A.DIVISION_ID = P_DIVISION_ID;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MKT_FCST_INSERT');
            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_CFM_DEMAND_INSERT');
        END IF;


        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A010 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* INSERT INTO DM_PLN_MKT_FCST */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO DM_PLN_MKT_FCST
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_MKT_FCST_INSERT A
         WHERE MEASURE NOT IN ('VMI_IN_PLAN', 'AS_In_Plan')
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, SUM(QTY) AS QTY
             , MAX(CREATED_BY), MAX(CREATION_DATE), MAX(LAST_UPDATED_BY), MAX(LAST_UPDATE_DATE)
          FROM GT_PRDM2_MKT_FCST_INSERT
         WHERE MEASURE IN ('VMI_IN_PLAN', 'AS_In_Plan')
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SYS_RP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_MKT_FCST_INSERT A
         WHERE MEASURE = 'RTF_SCP'
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_PR' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_MKT_FCST_INSERT A
         WHERE MEASURE = 'RTF_SCP'
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_MKT_FCST_INSERT
         WHERE MEASURE = 'RTF_SCP'
           AND DIVISION_ID = '82';

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* RMA 처리 C20200518-000359 */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO DM_PLN_MKT_FCST
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
        , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SYS_RP' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_MKT_FCST A
         WHERE A.DIVISION_ID  = C_DIVISION_ID
           AND A.YYYYMMDD    >= C_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID  = '40'
           AND A.MEASURE      = V_MEASURE
           AND A.FCST_TYPE    = 'RMA'
           AND C_DIVISION_ID  = C_SCP_DIVISION_ID
           AND NOT EXISTS (SELECT 1
                             FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                            WHERE A.DIVISION_ID   = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND A.SCM_SITE_ID   = B.SCM_SITE_ID AND A.ITEM_ID      = B.ITEM_ID
                              AND A.DOM_EXP       = B.DOM_EXP     AND A.FCST_TYPE    = B.FCST_TYPE
                              AND 'RTF_SYS_RP'    = B.MEASURE      AND A.INCOTERMS   = B.INCOTERMS  /* [E20260812-001054] A.MEASURE = B.MEASURE -> 비교대상 명시 (AS-IS 운영 L1745-1746) [E20261006-ASISDELTA] */
                              AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.YYYYMMDD  >= V_PLAN_START_YYYYMMDD)
        UNION ALL
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_PR' AS MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
             , A.QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_MKT_FCST A
         WHERE A.DIVISION_ID  = C_DIVISION_ID
           AND A.YYYYMMDD    >= C_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID  = '40'
           AND A.MEASURE      = V_MEASURE
           AND A.FCST_TYPE    = 'RMA'
           AND C_DIVISION_ID  = C_SCP_DIVISION_ID
           AND NOT EXISTS (SELECT 1
                             FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                            WHERE A.DIVISION_ID   = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND A.SCM_SITE_ID   = B.SCM_SITE_ID AND A.ITEM_ID      = B.ITEM_ID
                              AND A.DOM_EXP       = B.DOM_EXP     AND A.FCST_TYPE    = B.FCST_TYPE
                              AND A.MEASURE       = B.MEASURE      AND A.INCOTERMS   = B.INCOTERMS
                              AND 'RTF_PR'        = B.MEASURE  /* [E20260812-001054] 비교대상 명시 — 원 조건 유지 + 추가 (AS-IS 운영 L1783-1784) [E20261006-ASISDELTA] */
                              AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.YYYYMMDD  >= V_PLAN_START_YYYYMMDD);

        /* ---------------------------------------------------------------------------------------------------------------- */
        /* [PJ2025-50017] INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN */
        /* ---------------------------------------------------------------------------------------------------------------- */
        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
        ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
        , ATTRIBUTE2, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT DIVISION_ID, PROJECT_CODE
             , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
             , CASE WHEN DIVISION_ID = '40' THEN FROM_SITE_ID ELSE NULL END AS ATTRIBUTE2
             , YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_CFM_DEMAND_INSERT A
         WHERE MEASURE NOT IN ('VMI_IN_PLAN', 'AS_In_Plan')
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE
             , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
             , CASE WHEN DIVISION_ID = '40' THEN MAX(FROM_SITE_ID) ELSE NULL END AS ATTRIBUTE2
             , YYYYMMDD, SUM(QTY) AS QTY, MAX(CREATED_BY), MAX(CREATION_DATE), MAX(LAST_UPDATED_BY), MAX(LAST_UPDATE_DATE)
          FROM GT_PRDM2_CFM_DEMAND_INSERT
         WHERE MEASURE IN ('VMI_IN_PLAN', 'AS_In_Plan')
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
        UNION ALL
        SELECT A.DIVISION_ID, A.PROJECT_CODE
             , CASE WHEN A.DIVISION_ID = '40' THEN A.PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
             , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SYS_RP' AS MEASURE, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID
             , CASE WHEN A.DIVISION_ID = '40' THEN A.FROM_SITE_ID ELSE NULL END AS ATTRIBUTE2
             , A.YYYYMMDD, A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
          FROM GT_PRDM2_CFM_DEMAND_INSERT A
         WHERE A.MEASURE = 'RTF_SCP'
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE
             , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_PR' AS MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
             , CASE WHEN DIVISION_ID = '40' THEN FROM_SITE_ID ELSE NULL END AS ATTRIBUTE2
             , YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
          FROM GT_PRDM2_CFM_DEMAND_INSERT A
         WHERE MEASURE = 'RTF_SCP';

        /* RMA 처리 (DM_PLN_CFM_MKT_DEMAND_PLAN) */
        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
        ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
        , CELL_PROD_SITE_ID, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_SYS_RP' AS MEASURE, A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID, A.YYYYMMDD, A.QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE A.DIVISION_ID  = C_DIVISION_ID
           AND A.YYYYMMDD    >= C_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID  = '40'
           AND A.MEASURE      = V_MEASURE
           AND A.FCST_TYPE    = 'RMA'
           AND C_DIVISION_ID  = C_SCP_DIVISION_ID
           AND NOT EXISTS (SELECT 1
                             FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                            WHERE A.DIVISION_ID   = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND A.SCM_SITE_ID   = B.SCM_SITE_ID AND A.ITEM_ID      = B.ITEM_ID
                              AND A.DOM_EXP       = B.DOM_EXP     AND A.FCST_TYPE    = B.FCST_TYPE
                              AND A.INCOTERMS     = B.INCOTERMS   AND A.MEASURE      = B.MEASURE
                              AND 'RTF_SYS_RP'    = B.MEASURE  /* [E20260812-001054] 비교대상 명시 — 원 조건 유지 + 추가 (AS-IS 운영 L1874-1875) [E20261006-ASISDELTA] */
                              AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                              AND CASE WHEN A.DIVISION_ID = '40' THEN NVL(A.CELL_PROD_SITE_ID,'-') ELSE '-' END = NVL(B.CELL_PROD_SITE_ID,'/'))
        UNION ALL
        SELECT A.DIVISION_ID, A.PROJECT_CODE, A.END_CUSTOMER, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'RTF_PR' AS MEASURE, A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID, A.YYYYMMDD, A.QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
         WHERE A.DIVISION_ID  = C_DIVISION_ID
           AND A.YYYYMMDD    >= C_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID  = '40'
           AND A.MEASURE      = V_MEASURE
           AND A.FCST_TYPE    = 'RMA'
           AND C_DIVISION_ID  = C_SCP_DIVISION_ID
           AND NOT EXISTS (SELECT 1
                             FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                            WHERE A.DIVISION_ID   = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND A.SCM_SITE_ID   = B.SCM_SITE_ID AND A.ITEM_ID      = B.ITEM_ID
                              AND A.DOM_EXP       = B.DOM_EXP     AND A.FCST_TYPE    = B.FCST_TYPE
                              AND A.INCOTERMS     = B.INCOTERMS   AND A.MEASURE      = B.MEASURE
                              AND 'RTF_PR'        = B.MEASURE  /* [E20260812-001054] 비교대상 명시 — 원 조건 유지 + 추가 (AS-IS 운영 L1912-1913) [E20261006-ASISDELTA] */
                              AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.YYYYMMDD   >= V_PLAN_START_YYYYMMDD
                              AND CASE WHEN A.DIVISION_ID = '40' THEN NVL(A.CELL_PROD_SITE_ID,'-') ELSE '-' END = NVL(B.CELL_PROD_SITE_ID,'/'));


        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A011 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;

        /* ================================================================================================================ */
        /* VMI재고 확인후 RTF 생성 로직 */
        /* [C20220224-000448] ESS 사업부 VMI 기능 자동차사업부 확산 전개 요청 (자동차 사업부 VMI_INV 생성하지 않음) */
        /* ================================================================================================================ */
        IF C_DIVISION_ID NOT LIKE '81%' THEN

            INSERT INTO GT_PRDM2_FP_STOCK_QTY
            ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, QTY )
            SELECT L.DIVISION_ID, L.SCM_SITE_ID, S.ITEM_ID, S.QTY
              FROM SCM_DNM_STOCK_SN S, SCM_MST_LOCATION L
             WHERE L.DIVISION_ID = S.DIVISION_ID
               AND L.STORAGE_ID  = S.STORAGE_ID
               AND TO_CHAR(S.CUTOFF_DATE, 'YYYYMMDD') = V_PLAN_START_YYYYMMDD
            UNION ALL
            SELECT L.DIVISION_ID, L.SCM_SITE_ID, S.ITEM_ID, S.QTY
              FROM SCM_DNM_STOCK_SALES S, SCM_MST_LOCATION L
             WHERE L.DIVISION_ID = S.DIVISION_ID
               AND L.STORAGE_ID  = S.STORAGE_ID
               AND L.PLANT_ID    = S.PLANT_ID
               AND S.DIVISION_ID = '82'
               AND S.RESULT_DATE = TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') - 1, 'YYYYMMDD');

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_FP_STOCK_QTY');


            IF P_DIVISION_ID = '40' THEN
                INSERT INTO GT_PRDM2_VMI_MST_MAIN
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID )
                SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, B.BASIS_YYYYMMDD AS YYYYMMDD
                     , CASE WHEN A.DIVISION_ID = '40' THEN
                                CASE WHEN B.BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD AND A.MEASURE IN ('Vmi_In_Plan')
                                     THEN NVL(C.QTY, 0) + NVL((SELECT SUM(S.QTY) FROM GT_PRDM2_FP_STOCK_QTY S
                                                                 WHERE S.SCM_SITE_ID = A.SCM_SITE_ID AND S.DIVISION_ID = A.DIVISION_ID
                                                                   AND S.ITEM_ID LIKE (CASE WHEN SUBSTR(A.ITEM_ID,1,2) = 'MP' THEN SUBSTR(A.ITEM_ID,1,11) ELSE A.ITEM_ID END) || '%'), 0)
                                     ELSE NVL(C.QTY, 0) END
                            ELSE
                                CASE WHEN B.BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD AND A.MEASURE IN ('Vmi_In_Plan')
                                     THEN NVL(C.QTY, 0) + NVL((SELECT SUM(S.QTY) FROM GT_PRDM2_FP_STOCK_QTY S
                                                                 WHERE S.SCM_SITE_ID = A.SCM_SITE_ID AND S.DIVISION_ID = A.DIVISION_ID AND S.ITEM_ID = A.ITEM_ID), 0)
                                     ELSE NVL(C.QTY, 0) END
                            END AS QTY
                     , A.CELL_PROD_SITE_ID, A.FROM_SITE_ID
                  FROM (SELECT DISTINCT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS
                                      , W.MEASURE, W.PLANT_SITE_ID, W.CELL_PROD_SITE_ID
                                      /* (START) 2026.10.01 AJS  END_CUSTOMER 를 조인에 쓰기 위해 추출 항목에 추가.
                                                                 조인 조건에 이 칸이 없어 기본키 인덱스가 셋째 칸에서 끊기고
                                                                 나머지 조건이 걸러내기로 넘어가 수행시간이 길어진다 */
                                      , W.END_CUSTOMER
                                      /* (END) */
                                      , W.ATTRIBUTE2 AS FROM_SITE_ID
                           FROM DM_PLN_CFM_MKT_DEMAND_PLAN W
                              , GT_PRDM2_RESULTS ST
                          WHERE W.DIVISION_ID       = ST.DIVISION_ID
                            AND W.PROJECT_CODE      = ST.PROJECT_CODE
                            AND W.SCM_SITE_ID       = ST.SCM_SITE_ID
                            AND W.ITEM_ID           = ST.ITEM_ID
                            AND W.DOM_EXP           = ST.DOM_EXP
                            AND W.FCST_TYPE         = ST.FCST_TYPE
                            AND W.INCOTERMS         = ST.INCOTERMS
                            AND W.PLANT_SITE_ID     = ST.PLANT_SITE_ID
                            AND W.CELL_PROD_SITE_ID = ST.CELL_PROD_SITE_ID
                            AND ST.VMI_YN           = 'Y'
                            AND W.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD
                            AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')) A

                 INNER JOIN SCM_SYS_CALENDAR_M B
                         ON B.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD
                        AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')
                  LEFT JOIN DM_PLN_CFM_MKT_DEMAND_PLAN C
                         ON A.DIVISION_ID       = C.DIVISION_ID
                        AND A.PROJECT_CODE      = C.PROJECT_CODE
                        AND A.SCM_SITE_ID       = C.SCM_SITE_ID
                        AND A.ITEM_ID           = C.ITEM_ID
                        AND A.DOM_EXP           = C.DOM_EXP
                        AND A.FCST_TYPE         = C.FCST_TYPE
                        AND A.INCOTERMS         = C.INCOTERMS
                        AND A.PLANT_SITE_ID     = C.PLANT_SITE_ID
                        AND A.MEASURE           = C.MEASURE
                        AND B.BASIS_YYYYMMDD    = C.YYYYMMDD
                        AND A.CELL_PROD_SITE_ID = C.CELL_PROD_SITE_ID
                        /* (START) 2026.10.01 AJS  기본키 인덱스를 끝까지 타도록 조인 조건 추가.
                                                   END_CUSTOMER 는 NOT NULL 이고 조인 열쇠당 한 값뿐이라 결과가 바뀌지 않는다
                                                   (40·81·82 전건 확인, 행수·수량합 동일) */
                        AND A.END_CUSTOMER      = C.END_CUSTOMER
                        /* (END) */
                 WHERE A.MEASURE IN (V_MEASURE, 'Vmi_In_Plan');
            ELSE
                INSERT INTO GT_PRDM2_VMI_MST_MAIN
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID )
                SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, B.BASIS_YYYYMMDD AS YYYYMMDD
                     , CASE WHEN A.DIVISION_ID = '40' THEN
                                CASE WHEN B.BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD AND A.MEASURE IN ('Vmi_In_Plan')
                                     THEN NVL(C.QTY, 0) + NVL((SELECT SUM(S.QTY) FROM GT_PRDM2_FP_STOCK_QTY S
                                                                 WHERE S.SCM_SITE_ID = A.SCM_SITE_ID AND S.DIVISION_ID = A.DIVISION_ID
                                                                   AND S.ITEM_ID LIKE (CASE WHEN SUBSTR(A.ITEM_ID,1,2) = 'MP' THEN SUBSTR(A.ITEM_ID,1,11) ELSE A.ITEM_ID END) || '%'), 0)
                                     ELSE NVL(C.QTY, 0) END
                            ELSE
                                CASE WHEN B.BASIS_YYYYMMDD = V_PLAN_START_YYYYMMDD AND A.MEASURE IN ('Vmi_In_Plan')
                                     THEN NVL(C.QTY, 0) + NVL((SELECT SUM(S.QTY) FROM GT_PRDM2_FP_STOCK_QTY S
                                                                 WHERE S.SCM_SITE_ID = A.SCM_SITE_ID AND S.DIVISION_ID = A.DIVISION_ID AND S.ITEM_ID = A.ITEM_ID), 0)
                                     ELSE NVL(C.QTY, 0) END
                            END AS QTY
                     , '-' AS CELL_PROD_SITE_ID, '-' AS FROM_SITE_ID
                  FROM (SELECT DISTINCT W.DIVISION_ID, W.PROJECT_CODE, W.SCM_SITE_ID, W.ITEM_ID, W.DOM_EXP, W.FCST_TYPE, W.INCOTERMS, W.MEASURE, W.PLANT_SITE_ID
                           FROM DM_PLN_MKT_FCST W
                              , GT_PRDM2_RESULTS ST
                          WHERE W.DIVISION_ID    = ST.DIVISION_ID
                            AND W.PROJECT_CODE   = ST.PROJECT_CODE
                            AND W.SCM_SITE_ID    = ST.SCM_SITE_ID
                            AND W.ITEM_ID        = ST.ITEM_ID
                            AND W.DOM_EXP        = ST.DOM_EXP
                            AND W.FCST_TYPE      = ST.FCST_TYPE
                            AND W.INCOTERMS      = ST.INCOTERMS
                            AND W.PLANT_SITE_ID  = ST.PLANT_SITE_ID
                            AND ST.VMI_YN        = 'Y'
                            AND W.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD
                            AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')) A

                 INNER JOIN SCM_SYS_CALENDAR_M B
                         ON B.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD
                        AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')
                  LEFT JOIN DM_PLN_MKT_FCST C
                         ON A.DIVISION_ID   = C.DIVISION_ID
                        AND A.PROJECT_CODE  = C.PROJECT_CODE
                        AND A.SCM_SITE_ID   = C.SCM_SITE_ID
                        AND A.ITEM_ID       = C.ITEM_ID
                        AND A.DOM_EXP       = C.DOM_EXP
                        AND A.FCST_TYPE     = C.FCST_TYPE
                        AND A.INCOTERMS     = C.INCOTERMS
                        AND A.PLANT_SITE_ID = C.PLANT_SITE_ID
                        AND A.MEASURE       = C.MEASURE
                        AND B.BASIS_YYYYMMDD = C.YYYYMMDD
                 WHERE A.MEASURE IN (V_MEASURE, 'Vmi_In_Plan');
            END IF;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_MST_MAIN');

            /* ---------------------------------------------------------------------------------------------------------------- */
            /* [C20220615-000414] VMI_In_Plan이 없고 기초재고가 있는 site/item에 Vmi_In_Plan 생성 */
            /* ---------------------------------------------------------------------------------------------------------------- */
            INSERT INTO GT_PRDM2_VMI_MST_MAIN
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MEASURE, YYYYMMDD, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID )
            SELECT AA.DIVISION_ID, AA.PROJECT_CODE, AA.SCM_SITE_ID, AA.ITEM_ID, AA.DOM_EXP, AA.FCST_TYPE, AA.INCOTERMS
                 , AA.PLANT_SITE_ID, 'Vmi_In_Plan' AS MEASURE, AA.YYYYMMDD
                 , CASE WHEN V_PLAN_START_YYYYMMDD = AA.YYYYMMDD THEN BB.QTY ELSE 0 END AS QTY
                 , AA.CELL_PROD_SITE_ID, AA.FROM_SITE_ID
              FROM GT_PRDM2_VMI_MST_MAIN AA
                 , (SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, SUM(A.QTY) AS QTY
                      FROM GT_PRDM2_FP_STOCK_QTY A
                         , (SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID
                              FROM GT_PRDM2_VMI_MST_MAIN
                             WHERE MEASURE = 'Vmi_In_Plan'
                             GROUP BY DIVISION_ID, SCM_SITE_ID, ITEM_ID) B
                     WHERE A.DIVISION_ID = B.DIVISION_ID(+) AND A.SCM_SITE_ID = B.SCM_SITE_ID(+) AND A.ITEM_ID = B.ITEM_ID(+)
                       AND B.DIVISION_ID IS NULL
                     GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID) BB
             WHERE AA.DIVISION_ID = BB.DIVISION_ID AND AA.SCM_SITE_ID = BB.SCM_SITE_ID AND AA.ITEM_ID = BB.ITEM_ID
               AND BB.QTY > 0;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_MST_MAIN');


            INSERT INTO GT_PRDM2_VMI_MST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY
                 , A.CELL_PROD_SITE_ID, A.FROM_SITE_ID
              FROM GT_PRDM2_VMI_MST_MAIN A
                 , GT_PRDM2_RESULTS S
             WHERE A.DIVISION_ID       = S.DIVISION_ID
               AND A.PROJECT_CODE      = S.PROJECT_CODE
               AND A.SCM_SITE_ID       = S.SCM_SITE_ID
               AND A.ITEM_ID           = S.ITEM_ID
               AND A.DOM_EXP           = S.DOM_EXP
               AND A.FCST_TYPE         = S.FCST_TYPE
               AND A.INCOTERMS         = S.INCOTERMS
               AND A.PLANT_SITE_ID     = S.PLANT_SITE_ID
               AND A.CELL_PROD_SITE_ID = S.CELL_PROD_SITE_ID
               AND S.VMI_YN            = 'Y';

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_MST');

            /* GT_PRDM2_VMI_TEMP1 (MKT_FCST accum) */
            INSERT INTO GT_PRDM2_VMI_TEMP1
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, ACCUM_SUM, LAST_ACCUM_SUM, CELL_PROD_SITE_ID, FROM_SITE_ID )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY
                 , SUM(A.QTY) OVER (PARTITION BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID ORDER BY A.YYYYMMDD) AS ACCUM_SUM
                 , SUM(A.QTY) OVER (PARTITION BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID ORDER BY A.YYYYMMDD) - A.QTY AS LAST_ACCUM_SUM
                 , A.CELL_PROD_SITE_ID, A.FROM_SITE_ID
              FROM GT_PRDM2_VMI_MST A
                 , GT_PRDM2_RESULTS S
             WHERE A.DIVISION_ID       = S.DIVISION_ID
               AND A.PROJECT_CODE      = S.PROJECT_CODE
               AND A.SCM_SITE_ID       = S.SCM_SITE_ID
               AND A.ITEM_ID           = S.ITEM_ID
               AND A.DOM_EXP           = S.DOM_EXP
               AND A.FCST_TYPE         = S.FCST_TYPE
               AND A.INCOTERMS         = S.INCOTERMS
               AND A.PLANT_SITE_ID     = S.PLANT_SITE_ID
               AND A.CELL_PROD_SITE_ID = S.CELL_PROD_SITE_ID
               AND S.VMI_YN            = 'Y'
             AND A.MEASURE  = V_MEASURE
               AND A.YYYYMMDD >= V_PLAN_START_YYYYMMDD;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_TEMP1');

            /* GT_PRDM2_VMI_TEMP2 (Vmi_In_Plan accum) */
            INSERT INTO GT_PRDM2_VMI_TEMP2
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY, ACCUM_SUM, LAST_ACCUM_SUM, CELL_PROD_SITE_ID, FROM_SITE_ID )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY
                 , SUM(A.QTY) OVER (PARTITION BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID ORDER BY A.YYYYMMDD) AS ACCUM_SUM
                 , SUM(A.QTY) OVER (PARTITION BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID ORDER BY A.YYYYMMDD) - A.QTY AS LAST_ACCUM_SUM
                 , A.CELL_PROD_SITE_ID, A.FROM_SITE_ID
              FROM GT_PRDM2_VMI_MST A
                 , GT_PRDM2_RESULTS S
             WHERE A.DIVISION_ID       = S.DIVISION_ID
               AND A.PROJECT_CODE      = S.PROJECT_CODE
               AND A.SCM_SITE_ID       = S.SCM_SITE_ID
               AND A.ITEM_ID           = S.ITEM_ID
               AND A.DOM_EXP           = S.DOM_EXP
               AND A.FCST_TYPE         = S.FCST_TYPE
               AND A.INCOTERMS         = S.INCOTERMS
               AND A.PLANT_SITE_ID     = S.PLANT_SITE_ID
               AND A.CELL_PROD_SITE_ID = S.CELL_PROD_SITE_ID
               AND S.VMI_YN            = 'Y'
             AND A.MEASURE  = 'Vmi_In_Plan'
               AND A.YYYYMMDD >= V_PLAN_START_YYYYMMDD;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_TEMP2');


            INSERT INTO GT_PRDM2_VMI_TEMP_ALL
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, YYYYMMDD, RTF_QTY, INV, CELL_PROD_SITE_ID, FROM_SITE_ID )
            SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.YYYYMMDD
                 , SUM(CASE WHEN NVL(A.ACCUM_SUM,0) > NVL(B.ACCUM_SUM,0) THEN NVL(B.ACCUM_SUM,0) ELSE NVL(A.ACCUM_SUM,0) END)
                 - SUM(CASE WHEN NVL(A.LAST_ACCUM_SUM,0) > NVL(B.LAST_ACCUM_SUM,0) THEN NVL(B.LAST_ACCUM_SUM,0) ELSE NVL(A.LAST_ACCUM_SUM,0) END) AS RTF_QTY
                 , SUM(NVL(B.ACCUM_SUM,0) - NVL(A.ACCUM_SUM,0)) AS INV
                 , B.CELL_PROD_SITE_ID, B.FROM_SITE_ID
              FROM GT_PRDM2_VMI_TEMP1 A, GT_PRDM2_VMI_TEMP2 B
             WHERE A.DIVISION_ID       = B.DIVISION_ID
               AND A.PROJECT_CODE      = B.PROJECT_CODE
               AND A.SCM_SITE_ID       = B.SCM_SITE_ID
               AND A.ITEM_ID           = B.ITEM_ID
               AND A.FCST_TYPE         = B.FCST_TYPE
               AND A.INCOTERMS         = B.INCOTERMS
               AND A.PLANT_SITE_ID     = B.PLANT_SITE_ID
               AND A.DOM_EXP           = B.DOM_EXP
               AND A.YYYYMMDD          = B.YYYYMMDD
               AND A.CELL_PROD_SITE_ID = B.CELL_PROD_SITE_ID
             GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.PLANT_SITE_ID, A.YYYYMMDD
                    , B.CELL_PROD_SITE_ID, B.FROM_SITE_ID
             ORDER BY A.YYYYMMDD;

            DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_VMI_TEMP_ALL');

            /* [E20260331-000648] */
            DELETE FROM GT_PRDM2_VMI_TEMP_ALL A
             WHERE EXISTS
                   (SELECT 1 FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                     WHERE A.DIVISION_ID   = B.DIVISION_ID
                       AND A.PROJECT_CODE  = B.PROJECT_CODE
                       AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                       AND A.ITEM_ID       = B.ITEM_ID
                       AND A.DOM_EXP       = B.DOM_EXP
                       AND A.FCST_TYPE     = B.FCST_TYPE
                       AND A.INCOTERMS     = B.INCOTERMS
                       AND A.PLANT_SITE_ID = B.PLANT_SITE_ID);

            /* DELETE VMI_Inv, RTF_SCP, RTF_SYS_RP, RTF_PR */
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE IN ('VMI_Inv','RTF_SCP','RTF_SYS_RP','RTF_PR')
               AND EXISTS (SELECT 1 FROM GT_PRDM2_RESULTS
                            WHERE DM_PLN_MKT_FCST.DIVISION_ID   = GT_PRDM2_RESULTS.DIVISION_ID
                              AND DM_PLN_MKT_FCST.PROJECT_CODE  = GT_PRDM2_RESULTS.PROJECT_CODE
                              AND DM_PLN_MKT_FCST.SCM_SITE_ID   = GT_PRDM2_RESULTS.SCM_SITE_ID
                              AND DM_PLN_MKT_FCST.ITEM_ID       = GT_PRDM2_RESULTS.ITEM_ID
                              AND DM_PLN_MKT_FCST.DOM_EXP       = GT_PRDM2_RESULTS.DOM_EXP
                              AND DM_PLN_MKT_FCST.FCST_TYPE     = GT_PRDM2_RESULTS.FCST_TYPE
                              AND DM_PLN_MKT_FCST.INCOTERMS     = GT_PRDM2_RESULTS.INCOTERMS
                              AND DM_PLN_MKT_FCST.PLANT_SITE_ID = GT_PRDM2_RESULTS.PLANT_SITE_ID
                              AND GT_PRDM2_RESULTS.VMI_YN        = 'Y'
                              AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            /* [C20201208-000087] RTF for 82 */
            DELETE FROM DM_PLN_MKT_FCST
             WHERE MEASURE     IN ('RTF')
               AND DIVISION_ID  = '82'
               AND EXISTS (SELECT 1 FROM GT_PRDM2_RESULTS
                            WHERE DM_PLN_MKT_FCST.DIVISION_ID   = GT_PRDM2_RESULTS.DIVISION_ID
                              AND DM_PLN_MKT_FCST.PROJECT_CODE  = GT_PRDM2_RESULTS.PROJECT_CODE
                              AND DM_PLN_MKT_FCST.SCM_SITE_ID   = GT_PRDM2_RESULTS.SCM_SITE_ID
                              AND DM_PLN_MKT_FCST.ITEM_ID       = GT_PRDM2_RESULTS.ITEM_ID
                              AND DM_PLN_MKT_FCST.DOM_EXP       = GT_PRDM2_RESULTS.DOM_EXP
                              AND DM_PLN_MKT_FCST.FCST_TYPE     = GT_PRDM2_RESULTS.FCST_TYPE
                              AND DM_PLN_MKT_FCST.INCOTERMS     = GT_PRDM2_RESULTS.INCOTERMS
                              AND DM_PLN_MKT_FCST.PLANT_SITE_ID = GT_PRDM2_RESULTS.PLANT_SITE_ID
                              AND GT_PRDM2_RESULTS.VMI_YN        = 'Y'
                              AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
             WHERE MEASURE IN ('VMI_Inv','RTF_SCP','RTF_SYS_RP','RTF_PR')
               AND EXISTS (SELECT 1 FROM GT_PRDM2_RESULTS
                            WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID   = GT_PRDM2_RESULTS.DIVISION_ID
                              AND CASE WHEN DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = '40'
                                       THEN DM_PLN_CFM_MKT_DEMAND_PLAN.END_CUSTOMER
                                       ELSE DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE END = GT_PRDM2_RESULTS.PROJECT_CODE
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID   = GT_PRDM2_RESULTS.SCM_SITE_ID
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID       = GT_PRDM2_RESULTS.ITEM_ID
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP       = GT_PRDM2_RESULTS.DOM_EXP
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE     = GT_PRDM2_RESULTS.FCST_TYPE
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS     = GT_PRDM2_RESULTS.INCOTERMS
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID = GT_PRDM2_RESULTS.PLANT_SITE_ID
                              AND GT_PRDM2_RESULTS.VMI_YN                   = 'Y'
                              AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

            /* INSERT VMI RTF values into DM_PLN_MKT_FCST */
            INSERT INTO DM_PLN_MKT_FCST
            ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
            , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SCP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, RTF_QTY AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL A
             WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SYS_RP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, RTF_QTY AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL
             WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_PR' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, RTF_QTY AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL
             WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_Inv' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, INV AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL
             WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND INV > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, RTF_QTY AS QTY
                 , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL
             WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0 AND DIVISION_ID = '82';

            /* INSERT VMI RTF values into DM_PLN_CFM_MKT_DEMAND_PLAN */
            INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
            ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID
            , CELL_PROD_SITE_ID, ATTRIBUTE2, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
            SELECT DIVISION_ID, PROJECT_CODE
                 , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                 , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SCP' AS MEASURE, PLANT_SITE_ID
                 , NVL(CELL_PROD_SITE_ID,'-') AS CELL_PROD_SITE_ID, FROM_SITE_ID AS ATTRIBUTE2
                 , YYYYMMDD, RTF_QTY AS QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL A WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE
                 , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                 , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SYS_RP' AS MEASURE, PLANT_SITE_ID
                 , NVL(NULLIF(RTRIM(CELL_PROD_SITE_ID),''), '/') AS CELL_PROD_SITE_ID, FROM_SITE_ID AS ATTRIBUTE2
                 , YYYYMMDD, RTF_QTY AS QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE
                 , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                 , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_PR' AS MEASURE, PLANT_SITE_ID
                 , NVL(NULLIF(RTRIM(CELL_PROD_SITE_ID),''), '/') AS CELL_PROD_SITE_ID, FROM_SITE_ID AS ATTRIBUTE2
                 , YYYYMMDD, RTF_QTY AS QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND RTF_QTY > 0
            UNION ALL
            SELECT DIVISION_ID, PROJECT_CODE
                 , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
                 , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_Inv' AS MEASURE, PLANT_SITE_ID
                 , '-' AS CELL_PROD_SITE_ID, '-' AS ATTRIBUTE2
                 , YYYYMMDD, INV AS QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE
              FROM GT_PRDM2_VMI_TEMP_ALL WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD AND INV > 0;

            /* ================================================================================================================ */
            /* AS 재고 처리 - EXEC PR_DM_DNM_CREATE_WS_RTF */
            /* ================================================================================================================ */
            /* MSSQL L2524 EXEC PR_DM_DNM_CREATE_WS_RTF @P_DIVISION_ID (활성문) */
            PR_DM_DNM_CREATE_WS_RTF(P_DIVISION_ID);

            /* ================================================================================================================ */
            /* VMI DIO 계산로직 (START) */
            /* ================================================================================================================ */
            IF P_DIVISION_ID = '40' THEN
                /* VMI_DIO DELETE (DM_PLN_CFM_MKT_DEMAND_PLAN) */
                DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
                 WHERE MEASURE = 'VMI_DIO'
                   AND EXISTS (SELECT 1 FROM GT_PRDM2_RESULTS
                                WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID       = GT_PRDM2_RESULTS.DIVISION_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE      = GT_PRDM2_RESULTS.PROJECT_CODE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID       = GT_PRDM2_RESULTS.SCM_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID           = GT_PRDM2_RESULTS.ITEM_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP           = GT_PRDM2_RESULTS.DOM_EXP
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE         = GT_PRDM2_RESULTS.FCST_TYPE
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS         = GT_PRDM2_RESULTS.INCOTERMS
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID     = GT_PRDM2_RESULTS.PLANT_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.CELL_PROD_SITE_ID = GT_PRDM2_RESULTS.CELL_PROD_SITE_ID
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.ATTRIBUTE2        = GT_PRDM2_RESULTS.FROM_SITE_ID
                                  AND GT_PRDM2_RESULTS.VMI_YN                       = 'Y'
                                  AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD         >= V_PLAN_START_YYYYMMDD);

                /* VMI_DIO INSERT (DM_PLN_CFM_MKT_DEMAND_PLAN) — scalar subquery with Case 42 date arithmetic */
                INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
                /* (START) 2026.10.01 AJS  AS-IS 는 원본 행의 ATTRIBUTE1~10 을 복사하나 전환 시 누락되어
                                           ATTRIBUTE2 가 빈값이 되고, 다음 수행의 삭제 조건
                                           (ATTRIBUTE2 = FROM_SITE_ID)에 걸리지 않아 중복 적재로 기본키 위반 */
--              ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY
--              , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
                ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY
                , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
                , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5
                , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10 )
                /* (END) */
                SELECT A.DIVISION_ID, A.PROJECT_CODE, A.PROJECT_CODE AS END_CUSTOMER
                     , A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'VMI_DIO' AS MEASURE
                     , A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.YYYYMMDD
                     , NVL((SELECT TO_DATE(ZZ2.MIN_YMD,'YYYYMMDD') - TO_DATE(A.YYYYMMDD,'YYYYMMDD')
                              FROM (SELECT MIN(YYYYMMDD) AS MIN_YMD
                                      FROM (SELECT YYYYMMDD
                                                 , SUM(QTY) OVER (PARTITION BY A.DIVISION_ID ORDER BY YYYYMMDD) AS ACCUM_SUM
                                              FROM DM_PLN_CFM_MKT_DEMAND_PLAN B
                                             WHERE A.DIVISION_ID       = B.DIVISION_ID
                                               AND A.PROJECT_CODE      = B.PROJECT_CODE
                                               AND A.END_CUSTOMER      = B.END_CUSTOMER
                                               AND A.SCM_SITE_ID       = B.SCM_SITE_ID
                                               AND A.ITEM_ID           = B.ITEM_ID
                                               AND A.DOM_EXP           = B.DOM_EXP
                                               AND A.FCST_TYPE         = B.FCST_TYPE
                                               AND A.INCOTERMS         = B.INCOTERMS
                                               AND A.PLANT_SITE_ID     = B.PLANT_SITE_ID
                                               AND A.CELL_PROD_SITE_ID = B.CELL_PROD_SITE_ID
                                               AND B.MEASURE           = 'RTF'
                                               AND B.YYYYMMDD          > A.YYYYMMDD) ZZ
                                     WHERE ZZ.ACCUM_SUM >= A.QTY) ZZ2), 999) AS QTY
                --     , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
                /* (START) 2026.10.01 AJS  ATTRIBUTE1~10 복사 추가 */
--                      , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE
                        , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE
                        , A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4, A.ATTRIBUTE5
                        , A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10
                /* (END) */
                  FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
                     , GT_PRDM2_RESULTS S
                 WHERE A.DIVISION_ID       = S.DIVISION_ID
                   AND A.PROJECT_CODE      = S.PROJECT_CODE
                   AND A.SCM_SITE_ID       = S.SCM_SITE_ID
                   AND A.ITEM_ID           = S.ITEM_ID
                   AND A.DOM_EXP           = S.DOM_EXP
                   AND A.FCST_TYPE         = S.FCST_TYPE
                   AND A.INCOTERMS         = S.INCOTERMS
                   AND A.PLANT_SITE_ID     = S.PLANT_SITE_ID
                   AND A.CELL_PROD_SITE_ID = S.CELL_PROD_SITE_ID
                   AND A.ATTRIBUTE2        = S.FROM_SITE_ID
                   AND S.VMI_YN            = 'Y'
                   AND A.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                   AND A.DIVISION_ID = C_DIVISION_ID
                   AND A.MEASURE     = 'VMI_Inv'
                   AND A.QTY        > 0
                   AND A.YYYYMMDD   >= V_PLAN_START_YYYYMMDD;
            ELSE
                /* VMI_DIO DELETE (DM_PLN_MKT_FCST) */
                DELETE FROM DM_PLN_MKT_FCST
                 WHERE MEASURE = 'VMI_DIO'
                   AND EXISTS (SELECT 1 FROM GT_PRDM2_RESULTS
                                WHERE DM_PLN_MKT_FCST.DIVISION_ID   = GT_PRDM2_RESULTS.DIVISION_ID
                                  AND DM_PLN_MKT_FCST.PROJECT_CODE  = GT_PRDM2_RESULTS.PROJECT_CODE
                                  AND DM_PLN_MKT_FCST.SCM_SITE_ID   = GT_PRDM2_RESULTS.SCM_SITE_ID
                                  AND DM_PLN_MKT_FCST.ITEM_ID       = GT_PRDM2_RESULTS.ITEM_ID
                                  AND DM_PLN_MKT_FCST.DOM_EXP       = GT_PRDM2_RESULTS.DOM_EXP
                                  AND DM_PLN_MKT_FCST.FCST_TYPE     = GT_PRDM2_RESULTS.FCST_TYPE
                                  AND DM_PLN_MKT_FCST.INCOTERMS     = GT_PRDM2_RESULTS.INCOTERMS
                                  AND DM_PLN_MKT_FCST.PLANT_SITE_ID = GT_PRDM2_RESULTS.PLANT_SITE_ID
                                  AND GT_PRDM2_RESULTS.VMI_YN        = 'Y'
                                  AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);

                /* VMI_DIO INSERT (DM_PLN_MKT_FCST) */
                INSERT INTO DM_PLN_MKT_FCST
                ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
                , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
                SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, 'VMI_DIO' AS MEASURE
                     , A.PLANT_SITE_ID, A.YYYYMMDD
                     , NVL((SELECT TO_DATE(ZZ2.MIN_YMD,'YYYYMMDD') - TO_DATE(A.YYYYMMDD,'YYYYMMDD')
                              FROM (SELECT MIN(YYYYMMDD) AS MIN_YMD
                                      FROM (SELECT YYYYMMDD
                                                 , SUM(QTY) OVER (PARTITION BY A.DIVISION_ID ORDER BY YYYYMMDD) AS ACCUM_SUM
                                              FROM DM_PLN_MKT_FCST B
                                             WHERE A.DIVISION_ID   = B.DIVISION_ID
                                               AND A.PROJECT_CODE  = B.PROJECT_CODE
                                               AND A.SCM_SITE_ID   = B.SCM_SITE_ID
                                               AND A.ITEM_ID       = B.ITEM_ID
                                               AND A.DOM_EXP       = B.DOM_EXP
                                               AND A.FCST_TYPE     = B.FCST_TYPE
                                               AND A.INCOTERMS     = B.INCOTERMS
                                               AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                                               AND B.MEASURE       = 'RTF'
                                               AND B.YYYYMMDD      > A.YYYYMMDD) ZZ
                                     WHERE ZZ.ACCUM_SUM >= A.QTY) ZZ2), 999) AS QTY
                     --, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
                       , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE 
                  FROM DM_PLN_MKT_FCST A
                     , GT_PRDM2_RESULTS S
                 WHERE A.DIVISION_ID   = S.DIVISION_ID
                   AND A.PROJECT_CODE  = S.PROJECT_CODE
                   AND A.SCM_SITE_ID   = S.SCM_SITE_ID
                   AND A.ITEM_ID       = S.ITEM_ID
                   AND A.DOM_EXP       = S.DOM_EXP
                   AND A.FCST_TYPE     = S.FCST_TYPE
                   AND A.INCOTERMS     = S.INCOTERMS
                   AND A.PLANT_SITE_ID = S.PLANT_SITE_ID
                   AND S.VMI_YN        = 'Y'
                   AND A.YYYYMMDD     >= V_PLAN_START_YYYYMMDD
                   AND A.DIVISION_ID = C_DIVISION_ID
                   AND A.MEASURE     = 'VMI_Inv'
                   AND A.QTY        > 0
                   AND A.YYYYMMDD   >= V_PLAN_START_YYYYMMDD;
            END IF;
            /* ================================================================================================================ */
            /* VMI DIO 계산로직 (END) */
            /* ================================================================================================================ */
        END IF;
        /* VMI재고 확인후 RTF 생성 로직 (END) */
    END IF;
    /* RTF, VMI DIO 관련 작업 (END) */

    /* ================================================================================================================ */
    /* MKT_FCST_QTY_BALANCE_CREATE (START) */
    /* ================================================================================================================ */


    DELETE FROM GT_PRDM2_MF_BALANCE_MKT_FCST WHERE DIVISION_ID = P_DIVISION_ID;

    IF P_DIVISION_ID = '40' THEN
        INSERT INTO GT_PRDM2_MF_BALANCE_MKT_FCST
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, FROM_SITE_ID, MEASURE, YYYYMMDD, QTY )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
             , CELL_PROD_SITE_ID, ATTRIBUTE2 AS FROM_SITE_ID, MEASURE, YYYYMMDD, QTY
          FROM DM_PLN_CFM_MKT_DEMAND_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID
           AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
           AND MEASURE IN ('MKT_FCST','SCM_FCST','VMI_In_Req','AS_In_Req','BALANCE','RTF_SYS_RP','RTF_SCP','RTF','VMI_Inv');
    ELSE
        INSERT INTO GT_PRDM2_MF_BALANCE_MKT_FCST
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, FROM_SITE_ID, MEASURE, YYYYMMDD, QTY )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID, '-' AS FROM_SITE_ID, MEASURE, YYYYMMDD, QTY
          FROM DM_PLN_MKT_FCST A
         WHERE DIVISION_ID = P_DIVISION_ID
           AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
           AND MEASURE IN ('MKT_FCST','SCM_FCST','VMI_In_Req','AS_In_Req','BALANCE','RTF_SYS_RP','RTF_SCP','RTF','VMI_Inv')
           AND NOT EXISTS (SELECT 1
                             FROM GT_PRDM2_RTF_EXCEPTION_ITEM B
                            WHERE A.DIVISION_ID   = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                              AND A.SCM_SITE_ID   = B.SCM_SITE_ID AND A.ITEM_ID      = B.ITEM_ID
                              AND A.DOM_EXP       = B.DOM_EXP     AND A.FCST_TYPE    = B.FCST_TYPE
                              AND A.INCOTERMS     = B.INCOTERMS   AND A.PLANT_SITE_ID = B.PLANT_SITE_ID
                              AND A.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);
    END IF;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MF_BALANCE_MKT_FCST');

    /* GT_PRDM2_MST INSERT */
    INSERT INTO GT_PRDM2_MST
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MEASURE, YYYYMMDD, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID )
    SELECT ZZ.DIVISION_ID, ZZ.PROJECT_CODE, ZZ.SCM_SITE_ID, ZZ.ITEM_ID, ZZ.DOM_EXP, ZZ.FCST_TYPE, ZZ.INCOTERMS, ZZ.PLANT_SITE_ID, ZZ.MEASURE, ZZ.YYYYMMDD
         , MAX(NVL(C.QTY, 0))
         , ZZ.CELL_PROD_SITE_ID, '-' AS FROM_SITE_ID
      FROM (
        SELECT TARGET_DATA.DIVISION_ID, TARGET_DATA.PROJECT_CODE, TARGET_DATA.SCM_SITE_ID, TARGET_DATA.ITEM_ID, TARGET_DATA.DOM_EXP
             , TARGET_DATA.FCST_TYPE, TARGET_DATA.INCOTERMS, TARGET_DATA.PLANT_SITE_ID, TARGET_DATA.CELL_PROD_SITE_ID, TARGET_DATA.FROM_SITE_ID
             , MEASURE.MEASURE, DS.YYYYMMDD
          FROM (SELECT DISTINCT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.FROM_SITE_ID
                  FROM GT_PRDM2_RESULTS A) TARGET_DATA
             , (SELECT 'MKT_FCST' AS MEASURE FROM DUAL UNION ALL SELECT 'RTF_SCP' AS MEASURE FROM DUAL) MEASURE
             , (SELECT C.BASIS_YYYYMMDD AS YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE C.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD
                   AND TO_CHAR(TO_DATE(V_PLAN_START_YYYYMMDD,'YYYYMMDD') + N_PLAN_WEEK_CNT * 7, 'YYYYMMDD')) DS
      ) ZZ
         , GT_PRDM2_MF_BALANCE_MKT_FCST C
     WHERE ZZ.DIVISION_ID       = C.DIVISION_ID(+)
        AND ZZ.PROJECT_CODE      = C.PROJECT_CODE(+)
        AND ZZ.SCM_SITE_ID       = C.SCM_SITE_ID(+)
        AND ZZ.ITEM_ID           = C.ITEM_ID(+)
        AND ZZ.DOM_EXP           = C.DOM_EXP(+)
        AND ZZ.FCST_TYPE         = C.FCST_TYPE(+)
        AND ZZ.INCOTERMS         = C.INCOTERMS(+)
        AND ZZ.PLANT_SITE_ID     = C.PLANT_SITE_ID(+)
        AND ZZ.MEASURE           = C.MEASURE(+)
        AND ZZ.YYYYMMDD          = C.YYYYMMDD(+)
        AND ZZ.CELL_PROD_SITE_ID = C.CELL_PROD_SITE_ID(+)
     GROUP BY ZZ.DIVISION_ID, ZZ.PROJECT_CODE, ZZ.SCM_SITE_ID, ZZ.ITEM_ID, ZZ.DOM_EXP, ZZ.FCST_TYPE, ZZ.INCOTERMS, ZZ.PLANT_SITE_ID, ZZ.MEASURE, ZZ.YYYYMMDD, ZZ.CELL_PROD_SITE_ID;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MST');


    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := 'step - A018 ';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
    V_LOG_MESSAGE := NULL;

    /* GT_PRDM2_MST_ACCUM INSERT */
    INSERT INTO GT_PRDM2_MST_ACCUM
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, YYYYMMDD, MEASURE, QTY, CELL_PROD_SITE_ID, FROM_SITE_ID, ACCUM_SUM )
    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, YYYYMMDD, MEASURE, QTY
         , CELL_PROD_SITE_ID, FROM_SITE_ID
         , SUM(QTY) OVER (PARTITION BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MEASURE, CELL_PROD_SITE_ID ORDER BY YYYYMMDD) AS ACCUM_SUM
      FROM GT_PRDM2_MST;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_MST_ACCUM');

    /* GT_PRDM2_TEMPX INSERT */
    INSERT INTO GT_PRDM2_TEMPX
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, MEASURE, YYYYMMDD, CELL_PROD_SITE_ID, FROM_SITE_ID, ACCUM_X )
    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, 'BALANCE' AS MEASURE, YYYYMMDD
         , CELL_PROD_SITE_ID, FROM_SITE_ID
         , SUM(CASE WHEN MEASURE = 'MKT_FCST' THEN 0 ELSE ACCUM_SUM END)
         - SUM(CASE WHEN MEASURE = 'MKT_FCST' THEN ACCUM_SUM ELSE 0 END) AS ACCUM_X
      FROM GT_PRDM2_MST_ACCUM
     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, FROM_SITE_ID;

    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_TEMPX');

    /* DELETE BALANCE from DM_PLN_MKT_FCST */
    DELETE FROM DM_PLN_MKT_FCST
     WHERE MEASURE = 'BALANCE'
       AND EXISTS (SELECT 1 FROM GT_PRDM2_TEMPX
                    WHERE DM_PLN_MKT_FCST.DIVISION_ID   = GT_PRDM2_TEMPX.DIVISION_ID
                      AND DM_PLN_MKT_FCST.PROJECT_CODE  = GT_PRDM2_TEMPX.PROJECT_CODE
                      AND DM_PLN_MKT_FCST.SCM_SITE_ID   = GT_PRDM2_TEMPX.SCM_SITE_ID
                      AND DM_PLN_MKT_FCST.ITEM_ID       = GT_PRDM2_TEMPX.ITEM_ID
                      AND DM_PLN_MKT_FCST.DOM_EXP       = GT_PRDM2_TEMPX.DOM_EXP
                      AND DM_PLN_MKT_FCST.FCST_TYPE     = GT_PRDM2_TEMPX.FCST_TYPE
                      AND DM_PLN_MKT_FCST.INCOTERMS     = GT_PRDM2_TEMPX.INCOTERMS
                      AND DM_PLN_MKT_FCST.PLANT_SITE_ID = GT_PRDM2_TEMPX.PLANT_SITE_ID
                      AND DM_PLN_MKT_FCST.YYYYMMDD     >= V_PLAN_START_YYYYMMDD);


    V_LOG_TYPE    := 'ING';
    V_LOG_MESSAGE := 'step - A019 ';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
    V_LOG_MESSAGE := NULL;

    /* INSERT BALANCE into DM_PLN_MKT_FCST */
    INSERT INTO DM_PLN_MKT_FCST
    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
    , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'BALANCE' AS MEASURE, PLANT_SITE_ID, YYYYMMDD
         , SUM(ACCUM_X) AS ACCUM_X
         , 'BALANCE_MAKE', SYSDATE, 'BALANCE_MAKE', SYSDATE
      FROM GT_PRDM2_TEMPX
     WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD
       AND ACCUM_X BETWEEN -9999999999 AND 9999999999
       AND ACCUM_X <> 0
     GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, YYYYMMDD;

    /* 40사업부 BALANCE → DM_PLN_CFM_MKT_DEMAND_PLAN */
    IF P_DIVISION_ID = '40' THEN
        DELETE FROM DM_PLN_CFM_MKT_DEMAND_PLAN
         WHERE MEASURE = 'BALANCE'
           AND EXISTS (SELECT 1 FROM GT_PRDM2_TEMPX
                        WHERE DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID   = GT_PRDM2_TEMPX.DIVISION_ID
                          AND CASE WHEN DM_PLN_CFM_MKT_DEMAND_PLAN.DIVISION_ID = '40'
                                   THEN DM_PLN_CFM_MKT_DEMAND_PLAN.END_CUSTOMER
                                   ELSE DM_PLN_CFM_MKT_DEMAND_PLAN.PROJECT_CODE END = GT_PRDM2_TEMPX.PROJECT_CODE
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.SCM_SITE_ID       = GT_PRDM2_TEMPX.SCM_SITE_ID
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.ITEM_ID           = GT_PRDM2_TEMPX.ITEM_ID
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.DOM_EXP           = GT_PRDM2_TEMPX.DOM_EXP
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.FCST_TYPE         = GT_PRDM2_TEMPX.FCST_TYPE
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.INCOTERMS         = GT_PRDM2_TEMPX.INCOTERMS
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.PLANT_SITE_ID     = GT_PRDM2_TEMPX.PLANT_SITE_ID
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                          AND DM_PLN_CFM_MKT_DEMAND_PLAN.CELL_PROD_SITE_ID = GT_PRDM2_TEMPX.CELL_PROD_SITE_ID);

        INSERT INTO DM_PLN_CFM_MKT_DEMAND_PLAN
        ( DIVISION_ID, PROJECT_CODE, END_CUSTOMER, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
        , YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE )
        SELECT DIVISION_ID, PROJECT_CODE
             , CASE WHEN DIVISION_ID = '40' THEN PROJECT_CODE ELSE ' ' END AS END_CUSTOMER
             , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'BALANCE' AS MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID
             , YYYYMMDD, ACCUM_X
             , 'BALANCE_MAKE', SYSDATE, 'BALANCE_MAKE', SYSDATE
          FROM GT_PRDM2_TEMPX
         WHERE YYYYMMDD >= V_PLAN_START_YYYYMMDD
           AND ACCUM_X BETWEEN -9999999999 AND 9999999999
           AND ACCUM_X <> 0;
    END IF;
    /* ================================================================================================================ */
    /* MKT_FCST_QTY_BALANCE_CREATE (END) */
    /* ================================================================================================================ */

    /* ================================================================================================================ */
    /* SALES_PLAN_AMT_CREATE_LOCAL_KRW 호출 (START) */
    /* ================================================================================================================ */
    IF V_P_PLAN_ID <> 'CALL' THEN
        /* MSSQL L3015 EXEC [dbo].[PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW] @c_division_id, 'SYSTEM' (활성문) */
        PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW(C_DIVISION_ID, 'SYSTEM');


        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A020 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;
    END IF;

    /* ================================================================================================================ */
    /* CUTOFF 관련작업 (batch_call_yn = 'N'인 경우만 — UI 호출) */
    /* ================================================================================================================ */
    IF V_P_PLAN_ID <> 'CALL' AND V_BATCH_CALL_YN = 'N' THEN

        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A021 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;

        /* Cutoff VERSION_NO insert */
        INSERT INTO GT_PRDM2_CUTOFF ( VERSION_NO )
        SELECT VERSION_NO
          FROM DM_MST_VERSION
         WHERE DIVISION_ID = C_DIVISION_ID
           AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD
           AND VERSION_TYPE IN ('MF_W', 'SF_W')
         ORDER BY VERSION_NO;

        DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_CUTOFF');

        /* CURSOR2_CUTOFF : CUTOFF VERSION_NO 별 RTF_SCP MEASURE 작업 호출 (MSSQL L3057~3113) */
        FOR R_CUTOFF IN CUR_CUTOFF LOOP
            C_VERSION_NO := R_CUTOFF.VERSION_NO;
            /* MSSQL L3084 EXEC [dbo].[PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE] @c_division_id, @c_VERSION_NO (활성문) */
            PR_DM_PLN_MKT_FCST_C_QTY_BALANCE_CREATE(C_DIVISION_ID, C_VERSION_NO);
        END LOOP;

        /* ================================================================================================================ */
        /* [E20250210-000219] SCP 엔진 재수행에 따른 Sales Plan Cutoff 재수행 자동화 */
        /* ================================================================================================================ */
        IF V_P_PLAN_ID IS NOT NULL AND V_P_PLAN_ID <> 'CALL' THEN
            BEGIN
                SELECT COUNT(*)
                  INTO N_SP_VERSION_CNT
                  FROM DM_MST_VERSION
                 WHERE DIVISION_ID  = C_DIVISION_ID
                   AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD
                   AND VERSION_TYPE = 'SP_W';
            EXCEPTION WHEN NO_DATA_FOUND THEN
                N_SP_VERSION_CNT := 0;
            END;

            IF N_SP_VERSION_CNT > 0 THEN
                BEGIN
                    SELECT COUNT(*)
                      INTO N_TIME_EXCLUDE_CNT
                      FROM SCM_MST_DIVISION A
                     WHERE A.ATTRIBUTE3 IN ('40','81','82')
                       AND A.DIVISION_ID NOT IN (
                               SELECT SEGMENT1
                                 FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                WHERE LOOKUP_TYPE = 'CUTOFF_EXCLUDE_TIME_DIVISION'
                                  AND SEGMENT1    = C_DIVISION_ID
                                  AND SEGMENT2 IN (SELECT DAYOFWEEK
                                                     FROM SCM_SYS_CALENDAR_M
                                                    WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE,'YYYYMMDD')
                                                      AND TO_NUMBER(TO_CHAR(SYSDATE,'HH24') || TO_CHAR(SYSDATE,'MI'))
                                                          BETWEEN TO_NUMBER(SEGMENT3) AND TO_NUMBER(SEGMENT4))
                                  AND VALID_YN = 'Y')
                       AND A.DIVISION_ID = C_DIVISION_ID;
                EXCEPTION WHEN NO_DATA_FOUND THEN
                    N_TIME_EXCLUDE_CNT := 0;
                END;

                IF N_TIME_EXCLUDE_CNT > 0 THEN
                    /* Sales Plan 비교 (GT_PRDM2_TEMP_SALES_PLAN_C vs GT_PRDM2_TEMP_MKT_FCST_C) */
                    INSERT INTO GT_PRDM2_TEMP_SALES_PLAN_C
                    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY
                      FROM DM_PLN_SALES_PLAN_C
                     WHERE DIVISION_ID = C_DIVISION_ID
                       AND VERSION_NO  = (SELECT MAX(VERSION_NO) FROM DM_MST_VERSION WHERE VERSION_TYPE = 'SP_W' AND DIVISION_ID = C_DIVISION_ID)
                       AND MEASURE     = 'RTF_SYS_RP'
                       AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD;

                    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_TEMP_SALES_PLAN_C');

                    INSERT INTO GT_PRDM2_TEMP_MKT_FCST_C
                    ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY )
                    SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY
                      FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C
                     WHERE DIVISION_ID = C_DIVISION_ID
                       AND VERSION_NO  = (SELECT MAX(VERSION_NO) FROM DM_MST_VERSION WHERE VERSION_TYPE = 'MF_W' AND DIVISION_ID = C_DIVISION_ID)
                       AND MEASURE     = 'RTF_SYS_RP'
                       AND YYYYMMDD   >= V_PLAN_START_YYYYMMDD;

                    DBMS_STATS.GATHER_TABLE_STATS(OWNNAME => 'SCM_MGR', TABNAME => 'GT_PRDM2_TEMP_MKT_FCST_C');


                    SELECT COUNT(*)
                      INTO N_DIFF_CNT
                      FROM (
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY
                          FROM GT_PRDM2_TEMP_SALES_PLAN_C
                      ) A
                      /* FULL OUTER JOIN → Oracle (+)는 완전 외부조인(FULL OUTER) 미지원 → H-3 ANSI JOIN 유지 */
                      FULL OUTER JOIN (
                        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CELL_PROD_SITE_ID, QTY
                          FROM GT_PRDM2_TEMP_MKT_FCST_C
                      ) B
                          ON A.DIVISION_ID       = B.DIVISION_ID
                         AND A.PROJECT_CODE      = B.PROJECT_CODE
                         AND A.SCM_SITE_ID       = B.SCM_SITE_ID
                         AND A.ITEM_ID           = B.ITEM_ID
                         AND A.DOM_EXP           = B.DOM_EXP
                         AND A.FCST_TYPE         = B.FCST_TYPE
                         AND A.INCOTERMS         = B.INCOTERMS
                         AND A.MEASURE           = B.MEASURE
                         AND A.PLANT_SITE_ID     = B.PLANT_SITE_ID
                         AND A.YYYYMMDD          = B.YYYYMMDD
                         AND A.CELL_PROD_SITE_ID = B.CELL_PROD_SITE_ID
                     WHERE ((A.QTY <> B.QTY) OR (A.DIVISION_ID IS NULL) OR (B.DIVISION_ID IS NULL));

                    IF N_DIFF_CNT > 0 THEN
                        /*                                        @c_division_id, @p_cutoff_yyyymmdd = '', @p_creation_type = 'IRREGULAR' (활성문)
                           2번째 인자 '' 는 Oracle 에서 NULL. 피호출측이 IF L_CUTOFF_YYYYMMDD IS NULL THEN SYSDATE 로 처리하므로 MSSQL 과 동일. */
                        PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE(C_DIVISION_ID, '', 'IRREGULAR');
                    END IF;
                END IF;
            END IF;
        END IF;


        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'step - A024 ';
        V_DESCRIPTION := '';
        D_EVENT_DATE  := SYSDATE;
        BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;
        V_LOG_MESSAGE := NULL;
    END IF;

    /* ================================================================================================================ */
    /* 종료 LOG (END) */
    /* ================================================================================================================ */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := 'p_division_id : ' || NVL(P_DIVISION_ID,'NULL') || ' / ' || 'p_plan_id : ' || NVL(P_PLAN_ID,'NULL');
    D_EVENT_DATE  := SYSDATE;
    BEGIN PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE, USER, V_PROC_INPUT, NULL, NULL, NULL); END;

    /* 트랜잭션 COMMIT 미신설: 원본은 COMMIT WORK;(비활성)로 호출자 위임 */
    OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, 'SUCCESS' AS MESSAGE FROM DUAL;

EXCEPTION
    WHEN OTHERS THEN
        /* 트랜잭션 ROLLBACK 미신설: 원본은 ROLLBACK(비활성)로 호출자 위임 */
        V_SQL_CODE   := TO_CHAR(SQLCODE);
        V_SQL_ERRMSG := SQLERRM;
        V_BACKTRACE  := DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        V_LOG_MESSAGE := SUBSTR(V_SQL_ERRMSG, 1, 1000);
        V_DESCRIPTION := SUBSTR(V_BACKTRACE, 1, 500);
        BEGIN
            PR_DM_SYS_LOG_BATCH($$PLSQL_UNIT, 'ERROR', N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, SYSDATE, USER, V_PROC_INPUT, V_SQL_CODE, V_SQL_ERRMSG, V_BACKTRACE);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;

        OPEN O_RESULT_CURSOR FOR SELECT '0' AS CODE, '[[[' || V_SQL_CODE || ']' || V_SQL_ERRMSG AS MESSAGE FROM DUAL;
END PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE
-- ##### END PROCEDURE PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE

-- ##### START PROCEDURE PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING
CREATE OR REPLACE PROCEDURE         "PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING" 
(
      P_DIVISION_ID              IN  VARCHAR2 DEFAULT NULL   /* 사용하지 않는 파라메터 */
)
/* =====================================================================================================================================================================
 * Program ID   : PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING
 * Description  : PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING
 * Program History
 *---------------------------------------------------------------------------------------------------------------------------------------------------------------------
 *   Date       In Charge   Description
 *---------------------------------------------------------------------------------------------------------------------------------------------------------------------
 * 2018.01.     DWOK        Initial Release PJ20170278 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *                          PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING
 * 2018.03.13   JHBAEK      1. DM_PLN_SALES_PLAN_RESULT 테이블 CURREYCY COLUMN KEY 추가
 *                          2. 프로시져 CUSTOMIZING (기존 DIVIDSION_ID CURSOR -> SCM_MST_DIVISION IN 조건)
 * 2018.04.27   ADD         EXEC PR_DM_ERP_MATERIAL_TO_DM_RESULT ->  20180706 KHSONG 오류발생으로 일단 주석처리함
 * 2018.07.27   KHSONG      소형 vmi 재고 및 입고 실적 정보 생성
 * 2018.08.01   KHSONG      Null Warning 발생으로 MAX(ATTRIBUTE2)~MAX(ATTRIBUTE10) 부분 주석처리함 / 1달전 1일부터의 조회조건 보완
 * 2018.08.16   KHSONG      DIVISION 입력로직 변경
 * 2018.08.20   ytchoi      indicator added
 * 2018.09.10   KHSONG      distinct -> top 1 으로 수정
 * 2018.09.11   KHSONG      대상테이블 변경 DM_DNM_SALES_RESULT -> DM_DNM_SALES_RESULT_IF
 * 2018.09.12   KHSONG      날짜조건 변수로 설정
 * 2018.10.15   KHSONG      자동차 dm_pln_mkt_fcst_result 에 VMI_In_Plan, VMI_In_Req 생성
 * 2018.10.19   KHSONG      프로시져 호출 (KPI관련)
 * 2018.11.07   ytchoi      ETC에 대해서는 project code를 통일
 * 2018.11.28   KHSONG      PR_DM_ANL_KPI_SUMMARY 프로시져 호출추가
 * 2019.07.25               CSR ID:4048421 KHSONG 실적생성시 RTF_SystemR+P MEASURE를 추가생성함
 * 2019.08.09   KHSONG      CSR ID:4059971 VMI-In Request 로직 변경 (ESS사업부 추가 / storage_id 1BYTE 대기창고 제외)
 * 2019.10.01   KHSONG      매월 1일인경우 전전월의 데이터부터 대상으로 해야하므로 날짜산출 로직수정
 * 2019.11.07   KYH         Company_id 추가
 * 2019.11.11   KHSONG      CSR ID:4103469 GSCM Sales Plan, Waterfall ETC 매출 설정 로직 추가의 건
 * 2019.11.14   KYH         Company_id 원복
 * 2020.01.16   hwi1993     Company_id 추가
 * 2020.04.06   KHSONG      C20200324-000209 VMI in Request 실적값 오류보정
 * 2020.04.16   KHSONG      C20200413-000593 ESS사업부 RTF Measure 추가
 * 2020.07.29   hwi1993     과제 - ESS 실적매핑 내부거래 예외 처리
 * 2020.08.06   hwi1993     [C20200803-000105] MKT FCST 금액 Measure 추가 개발 요청의 건
 * 2020.09.09   P.C.I       [C20200909-000203] LOG 표준화 적용
 * 2020.11.13   hwi1993     [C20201103-000114] ESS 판매법인 VMI biz MKT FCST 입력 시 VMI in req 자동산출 로직 적용
 * 2020.12.01   HWI1993     개발에서는 KPI 실행하지 않도록 처리
 * 2020.12.09   hwi1993     customer code 길이 4 예외처리에 B100 처리
 * 2020.12.17   hwi1993     [C20201217-000126] ESS 판매법인 VMI inventory 수신 프로세스 수정. 82 plant id 추가
 * 2020.12.22   hwi1993     [C20201222-000376] VMI Inv 메저 수량 표시
 * 2020.12.23   kuni        I/F 에 SSP NO 추가
 * 2021.01.20   P.C.I       [C20210120-000090] VMI_Inv 의 Incoterms 는 MKT_FCST에 마지막으로 등록된 순으로 적용
 * 2021.01.28   kuni        [C20210127-000390] ESS사업부 실적 반영 주기 변경의 건
 * 2021.02.09   P.C.I       [C20210225-000385] SO_NO, SO_QTY 추가(',' 로 구분)
 * 2021.07.02   HWI1993     [C20210629-000239] MKT FCST Amt. 추가의 건
 * 2021.07.07   hwi1993     [C20210618-000288] VMI in Req가 없는 VMI in plan 실적값 로직
 * 2021.07.13   HWI1993     [C20210713-000038] VMI in Plan 실적 로직 정비
 * 2021.09.06   SJHAN       [C20210831-000303] GSCM VMI in 수요 없는 실적 발생시 Sales Site Project Model 참조 로직 수정
 * 2021.09.08   SJHAN       [C20210908-000163] Vmi in Req 실적 구간 로직 수정
 * 2021.10.01   hwi1993     [과제] as plant 처리 추가
 * 2022.04.14   HWI1993     GM JV
 * 2022.10.17   HWI1993     [C20221004-000309] ERP 피킹실적 VMI In plan(R+P) 실적 반영 요청 건
 * 2022.11.22   KDW2819     [C20221118-000024] AS 입고 실적 집계를 위한 기능 변경 건
 * 2022.11.28   hwi1993     [C20221118-000024] 오류 수정 ( AS IN PLAN 실적 처리시 Division 조건 추가 )
 * 2022.12.07   hwi1993     [C20221207-000280] 원복 [C20221004-000309]
 * 2024.04.25   HMIN        [E20240415-000036] 사내간 거래 매출 실적 인식 신규개발/기능변경 (DM_EXCEPT_SALES_SITE_MAPPING 예외처리)
 * 2024.05.29   P.C.I       [PJ20228272] NERP 하드코딩 대응 및 개선
 * 2024.08.20   JSSBAE      [E20240806-000678] 소형사업부 매출실적 스케줄 - 월요일 13시 (룩업기반 일정)
 * 2025.02.13   JSSBAE      [E20250213-001224] N-ERP ZSDOMR5070 SCM 출하 실적 불일치
 * 2025.04.08   JSSBAE      [E20250404-001534] 지연 빌링 발생 시 수요계획 보정 기능 개발 요청
 * 2025.05.13   KANG.H.J    [PJ2025-50188] 환율반영한 SALES_AMT_KRW / MKT_AMT_KRW 생성
 * 2025.05.26   KANG.H.J    [PJ2025-50188] 환율 반영한 AMT 업데이트 기준일 정의 - 당월 1일 (V_START_YYYYMMDD_EXCHANGE)
 * 2025.06.23   KANG.H.J    [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2025.07.09   KANG.H.J    [PJ2025-50188] SALES_AMT_KRW / MKT_AMT_KRW 생성 보완 - 40 미포함시 DUP ERROR 보완
 * 2025.10.30   JSSBAE      [E20251029-000956] 실적 데이터 Project Code 값 Mapping 로직 보완
 * 2025.10.30   JSSBAE      [E20251029-000963] 매출실적 데이터 IF 로직 보완 (40 외 CELL_PROD_SITE_ID '-')
 * 2026.05.22   ZIONEX      [PJ202650304] NextSCM Migration
 * ===================================================================================================================================================================== */
IS
    V_PROGRAM_NAME            VARCHAR2(150 CHAR) := 'PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING';
    V_LOG_TYPE                VARCHAR2(30 CHAR);
    N_LOG_COUNT               INTEGER := 0;
    V_LOG_MESSAGE             VARCHAR2(1000 CHAR);
    V_DESCRIPTION             VARCHAR2(500 CHAR);
    D_EVENT_DATE              DATE;

    /* 날짜변수 (20180912 KHSONG 날짜조건 변수로 설정) */
    V_START_YYYYMM            VARCHAR2(6 CHAR);
    V_END_YYYYMM              VARCHAR2(6 CHAR);
    V_START_YYYYMMDD          VARCHAR2(8 CHAR);
    V_START_YYYYMMDD_EXCHANGE VARCHAR2(8 CHAR);   /* [PJ2025-50188] 환율 AMT 기준일 : 당월 1일 */
    V_END_YYYYMMDD            VARCHAR2(8 CHAR);

    N_UPDATE_CNT              INTEGER := 0;
    N_ROWCNT                  INTEGER := 0;
    N_CHK_CNT                 INTEGER := 0;
    V_VERSION                 VARCHAR2(20 CHAR);
    V_DEDUCTED_DIVISION_ID    VARCHAR2(30 CHAR);
    V_STATES                  VARCHAR2(50 CHAR);
BEGIN
    /* 날짜변수설정 : 매월 1일인 경우 전전월(-2)부터, 그 외 전월(-1)부터 대상 */
    V_START_YYYYMM            := TO_CHAR(ADD_MONTHS(SYSDATE, CASE WHEN TO_CHAR(SYSDATE,'DD') = '01' THEN -2 ELSE -1 END), 'YYYYMM');
    V_START_YYYYMMDD          := SUBSTR(TO_CHAR(ADD_MONTHS(SYSDATE, CASE WHEN TO_CHAR(SYSDATE,'DD') = '01' THEN -2 ELSE -1 END), 'YYYYMM'), 1, 6) || '01';
    V_START_YYYYMMDD_EXCHANGE := TO_CHAR(SYSDATE, 'YYYYMM') || '01';   /* [PJ2025-50188] 당월 1일 */
    V_END_YYYYMM              := TO_CHAR(SYSDATE, 'YYYYMM');
    V_END_YYYYMMDD            := TO_CHAR(SYSDATE, 'YYYYMMDD');

    /* 시작 LOG START */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;   /* 변수 재사용을 위하여 초기화 */


    DELETE FROM GT_MFSRM_I_DIVISION;
    DELETE FROM GT_MFSRM_TEMP_DM_RESULT;
    DELETE FROM GT_MFSRM_DM_RESULT;
    DELETE FROM GT_MFSRM_DM_RESULT_BEFORE;
    DELETE FROM GT_MFSRM_AS_TMPDATA;
    DELETE FROM GT_MFSRM_VMI_TMPDATA;
    DELETE FROM GT_MFSRM_VMI_RESULT;
    DELETE FROM GT_MFSRM_T_MF;
    DELETE FROM GT_MFSRM_DELAY_DAY;
    DELETE FROM GT_MFSRM_DEDUCTED_ITEM;

    /* --------------------------------------------------------------------------------------------------------------------------------------------- 20180816 DIVISION 입력조건 변경 */
    /* [E20240806-000678] 소형사업부 매출실적 스케줄 - 월요일 13시. 하드코딩 대신 룩업(RESULT_MAPPING_SCHEDULE)에서 현재시점 작동 DIVISION 추출 */
    /* [E20250404-001534] RESULT MODE 추가 (SEGMENT4 = 'RESULT'). #TEMP_DAYINFO(당일 요일) 은 SCM_SYS_CALENDAR_M 1행 조회로 인라인화 */
    INSERT INTO GT_MFSRM_I_DIVISION (DIVISION_ID)
    SELECT SEGMENT1 AS DIVISION_ID
      FROM SCM_ADM_LOOKUP_MASTER_DETAIL
     WHERE LOOKUP_TYPE = 'RESULT_MAPPING_SCHEDULE'
       AND (SEGMENT2 = 'ALL' OR SEGMENT2 IN (SELECT DAYOFWEEK FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE,'YYYYMMDD')))
       AND (CASE WHEN ATTRIBUTE1 IS NOT NULL
                  AND ATTRIBUTE1 IN (SELECT DAYOFWEEK FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE,'YYYYMMDD'))
                 THEN SEGMENT1 ELSE '1' END) = '1'
       AND SUBSTR(SEGMENT3,1,2) BETWEEN TO_CHAR(SYSDATE - 1/24,'HH24') AND TO_CHAR(SYSDATE,'HH24')
       AND VALID_YN = 'Y'
       AND SEGMENT4 = 'RESULT'
     GROUP BY SEGMENT1;
    N_UPDATE_CNT := SQL%ROWCOUNT;

    /* Log에 작업하는 Division_id 표기 (TAB_PIVOT_STRING + FN_GET_PIVOT_STRING -> LISTAGG) */
    SELECT LISTAGG(DIVISION_ID, ',') WITHIN GROUP (ORDER BY DIVISION_ID)
      INTO V_DESCRIPTION
      FROM GT_MFSRM_I_DIVISION;

    V_LOG_TYPE    := 'APPEND';
    V_LOG_MESSAGE := 'TARGET DIVISION';
    D_EVENT_DATE  := SYSDATE;
    N_LOG_COUNT   := N_UPDATE_CNT;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    BEGIN

        /* 20180911 KHSONG 대상테이블 변경 DM_DNM_SALES_RESULT -> DM_DNM_SALES_RESULT_IF */
        INSERT INTO GT_MFSRM_TEMP_DM_RESULT
        ( DIVISION_ID, COMPANY_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID, ORIGIN_ITEM_ID
        , DOM_EXP, INCOTERMS, MEASURE, CURRENCY, YYYYMMDD, FCST_TYPE, QTY, SOLDTO_CODE, SHIPTO_CODE, VALID_YN
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, INTERNAL_TYPE
        , ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY, FROM_COMPANY_ID, PLANT_ID )
        SELECT  A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.ORIGIN_ITEM_ID
              , A.DOM_EXP, A.INCOTERMS, B.MEASURE, A.CURRENCY, A.YYYYMMDD, A.FCST_TYPE
              , CASE WHEN B.MEASURE = 'SALES_RESULT_AMOUNT'     THEN SUM(A.SALES_AMOUNT_FOR)
                     WHEN B.MEASURE = 'SALES_RESULT_AMOUNT_KRW' THEN SUM(A.SALES_AMOUNT_SUM)
                     WHEN B.MEASURE = 'SALES_RESULT'            THEN SUM(A.SALES_QTY)
                END AS QTY
              , A.SOLDTO_CODE, A.SHIPTO_CODE, A.VALID_YN
              , MAX(A.CREATED_BY), MAX(A.CREATION_DATE), MAX(A.LAST_UPDATED_BY), MAX(A.LAST_UPDATE_DATE), MAX(A.ATTRIBUTE1)
              , A.INTERNAL_TYPE
              , SUM(CASE WHEN VALIDATE_CONVERSION(A.ATTRIBUTE3 AS NUMBER) = 1 THEN TO_NUMBER(A.ATTRIBUTE3) ELSE 0 END) AS ATTRIBUTE3
              , MAX(A.ATTRIBUTE4) AS ATTRIBUTE4
              , A.SO_NO, A.SO_QTY, A.FROM_COMPANY_ID, A.PLANT_ID
        FROM (
                /* 81% 사업부 ([E20251029-000963] 40 외 CELL_PROD_SITE_ID 는 '-') */
                SELECT  DIVISION_ID, COMPANY_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID, ORIGIN_ITEM_ID
                      , FN_SCM_SYS_NVL(FN_GET_LOOKUP_CODE_DESC('DISTRIBUTION_CHANNEL', DISTRIBUTION_CHANNEL), 'E') AS DOM_EXP
                      , INCOTERMS, SALES_AMOUNT_FOR, SALES_AMOUNT_SUM, SALES_QTY, CURRENCY
                      , SALES_POSTING_DATE AS YYYYMMDD, FCST_TYPE
                      , CUSTOMER_CODE AS SOLDTO_CODE, SHIPTO_CODE, 'Y' AS VALID_YN
                      , 'scm_batch' AS CREATED_BY, SYSDATE AS CREATION_DATE, 'scm_batch' AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , ATTRIBUTE1, INTERNAL_TYPE, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY
--                      , '-' AS FROM_COMPANY_ID, PLANT_ID
                      , '-' AS FROM_COMPANY_ID, '-' AS PLANT_ID          -- 2026.09.11 AJS
                  FROM DM_DNM_SALES_RESULT_IF
                 WHERE 1 = 1
                   AND DIVISION_ID LIKE '81%'
                   AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                   AND SALES_YYYYMM BETWEEN V_START_YYYYMM AND V_END_YYYYMM
                   AND ( CUSTOMER_CODE IS NOT NULL
                         OR (CUSTOMER_CODE IS NULL AND PROFIT_CENTER_ID = 'A40012' AND PARTNER_PROFIT_CENTER_ID = 'A50101') )
                UNION ALL

                SELECT  DIVISION_ID, COMPANY_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID, ORIGIN_ITEM_ID
                      , FN_SCM_SYS_NVL(FN_GET_LOOKUP_CODE_DESC('DISTRIBUTION_CHANNEL', DISTRIBUTION_CHANNEL), 'E') AS DOM_EXP
                      , INCOTERMS, SALES_AMOUNT_FOR, SALES_AMOUNT_SUM, SALES_QTY, CURRENCY
                      , SALES_POSTING_DATE AS YYYYMMDD, FCST_TYPE
                      , CUSTOMER_CODE AS SOLDTO_CODE, SHIPTO_CODE, 'Y' AS VALID_YN
                      , 'scm_batch' AS CREATED_BY, SYSDATE AS CREATION_DATE, 'scm_batch' AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , ATTRIBUTE1, INTERNAL_TYPE, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY
--                      , '-' AS FROM_COMPANY_ID, PLANT_ID
                      , '-' AS FROM_COMPANY_ID, '-' AS PLANT_ID          -- 2026.09.11 AJS
                  FROM DM_DNM_SALES_RESULT_IF
                 WHERE 1 = 1
                   AND DIVISION_ID = '82'
                   AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                   AND SALES_YYYYMM BETWEEN V_START_YYYYMM AND V_END_YYYYMM
                UNION ALL
                /* 40 사업부 (소형 예외 매핑 : 전력저장전지 공통/오창 전력저장 전지 -> Peopleworks, ETC 처리) */
                SELECT  X.DIVISION_ID, X.COMPANY_ID
                      , CASE WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN 'Peopleworks'
                             WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME NOT IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN ' '
                             ELSE PROJECT_CODE END AS PROJECT_CODE
                      , CASE WHEN CUSTOMER_CODE = 'G450' THEN 'N'
                             WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN 'Peopleworks_KR_KUM'
                             WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME NOT IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN ' '
                             ELSE SALES_SITE_ID END AS SALES_SITE_ID
                      , PLANT_SITE_ID
                      , CASE WHEN ( DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME NOT IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') )
                                   OR (COMPANY_ID = 'G180' AND CUSTOMER_CODE IN ('G450','G630'))
                             THEN
                                CASE (SELECT CELL_TYPE FROM DM_MST_ITEM_SINGLE_V V WHERE V.DIVISION_ID = '40' AND V.ITEM_ID = X.ITEM_ID)
                                     WHEN 'POUCH'                 THEN 'ETC_P'
                                     WHEN 'CYLINDRICAL'           THEN 'ETC_C'
                                     WHEN 'PRISMATIC'             THEN 'ETC_R'
                                     WHEN 'POLYMER'               THEN 'ETC_P'
                                     WHEN 'SPIN-TYPE CYLINDRICAL' THEN 'ETC_C'
                                     WHEN 'CCYLINDRICAL'          THEN 'ETC_C'
                                     ELSE 'ETC' END
                             ELSE ITEM_ID END AS ITEM_ID
                      , ORIGIN_ITEM_ID
                      , FN_SCM_SYS_NVL(FN_GET_LOOKUP_CODE_DESC('DISTRIBUTION_CHANNEL', DISTRIBUTION_CHANNEL), 'E') AS DOM_EXP
                      , CASE WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN 'EXW'
                             ELSE INCOTERMS END AS INCOTERMS
                      , SALES_AMOUNT_FOR, SALES_AMOUNT_SUM
                      , CASE WHEN DISTRIBUTION_CHANNEL = '70' AND PARTNER_PROFIT_CENTER_NAME NOT IN (u'\c804\b825\c800\c7a5\c804\c9c0 \acf5\d1b5', u'\c624\cc3d \c804\b825\c800\c7a5 \c804\c9c0') THEN 0 ELSE SALES_QTY END AS SALES_QTY
                      , CURRENCY, SALES_POSTING_DATE AS YYYYMMDD, FCST_TYPE
                      , CUSTOMER_CODE AS SOLDTO_CODE, SHIPTO_CODE, 'Y' AS VALID_YN
                      , 'scm_batch' AS CREATED_BY, SYSDATE AS CREATION_DATE, 'scm_batch' AS LAST_UPDATED_BY, SYSDATE AS LAST_UPDATE_DATE
                      , ATTRIBUTE1, INTERNAL_TYPE, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY
                      , FROM_COMPANY_ID, PLANT_ID
                  FROM DM_DNM_SALES_RESULT_IF X
                 WHERE 1 = 1
                   AND DIVISION_ID = '40'
                   AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                   AND SALES_YYYYMM BETWEEN V_START_YYYYMM AND V_END_YYYYMM
                   AND SALES_AMOUNT_SUM <> 0
                   AND SALES_GROUP NOT IN ('A10','A11')   /* 유상사급 수출공통 / 40 유상사급 제외 */
             ) A
           , ( SELECT 'SALES_RESULT' AS MEASURE FROM DUAL
               UNION SELECT 'SALES_RESULT_AMOUNT' FROM DUAL
               UNION SELECT 'SALES_RESULT_AMOUNT_KRW' FROM DUAL ) B
        WHERE 1 = 1
        GROUP BY A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.ORIGIN_ITEM_ID
               , A.DOM_EXP, A.INCOTERMS, A.CURRENCY, A.YYYYMMDD, A.FCST_TYPE, A.SOLDTO_CODE, A.SHIPTO_CODE, A.VALID_YN
               , B.MEASURE, A.INTERNAL_TYPE, A.SO_NO, A.SO_QTY, A.FROM_COMPANY_ID, A.PLANT_ID;

        /* step-2-A : SO_NO/SO_QTY 집계 -> #DM_DNM_SALES_RESULT (GT_MFSRM_DM_RESULT) */
        /* [E20250213-001224] STUFF(... FOR XML PATH('')) -> LISTAGG(... ON OVERFLOW TRUNCATE) 상관 서브쿼리 */
        INSERT INTO GT_MFSRM_DM_RESULT
        ( DIVISION_ID, COMPANY_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID, ORIGIN_ITEM_ID, DOM_EXP, INCOTERMS
        , MEASURE, CURRENCY, YYYYMMDD, FCST_TYPE, QTY, SOLDTO_CODE, SHIPTO_CODE, VALID_YN, CREATED_BY, CREATION_DATE
        , LAST_UPDATED_BY, LAST_UPDATE_DATE, INTERNAL_TYPE, ATTRIBUTE1, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY, FROM_COMPANY_ID, PLANT_ID )
        SELECT  A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID
              , A.ORIGIN_ITEM_ID, A.DOM_EXP, A.INCOTERMS, A.MEASURE, A.CURRENCY, A.YYYYMMDD, A.FCST_TYPE, SUM(A.QTY) AS QTY
              , A.SOLDTO_CODE, A.SHIPTO_CODE, A.VALID_YN
              , 'scm_batch', SYSDATE, 'scm_batch', SYSDATE
              , A.INTERNAL_TYPE, MAX(A.ATTRIBUTE1)
              , SUM(CASE WHEN VALIDATE_CONVERSION(A.ATTRIBUTE3 AS NUMBER) = 1 THEN A.ATTRIBUTE3 ELSE 0 END) AS ATTRIBUTE3
              , MAX(A.ATTRIBUTE4) AS ATTRIBUTE4
              , ( SELECT LISTAGG(B.SO_NO, ',' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY B.SO_NO)
                    FROM GT_MFSRM_TEMP_DM_RESULT B
                   WHERE A.DIVISION_ID = B.DIVISION_ID AND A.COMPANY_ID = B.COMPANY_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                     AND A.SALES_SITE_ID = B.SALES_SITE_ID AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                     AND A.ORIGIN_ITEM_ID = B.ORIGIN_ITEM_ID AND A.DOM_EXP = B.DOM_EXP AND A.INCOTERMS = B.INCOTERMS
                     AND A.CURRENCY = B.CURRENCY AND A.YYYYMMDD = B.YYYYMMDD AND A.FCST_TYPE = B.FCST_TYPE
                     AND A.SOLDTO_CODE = B.SOLDTO_CODE AND A.SHIPTO_CODE = B.SHIPTO_CODE AND A.VALID_YN = B.VALID_YN
                     AND A.MEASURE = B.MEASURE AND NVL(A.INTERNAL_TYPE,'~') = NVL(B.INTERNAL_TYPE,'~')
                     AND A.FROM_COMPANY_ID = B.FROM_COMPANY_ID ) AS SO_NO
              , ( SELECT LISTAGG(B.SO_QTY, ',' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY B.SO_QTY)
                    FROM GT_MFSRM_TEMP_DM_RESULT B
                   WHERE A.DIVISION_ID = B.DIVISION_ID AND A.COMPANY_ID = B.COMPANY_ID AND A.PROJECT_CODE = B.PROJECT_CODE
                     AND A.SALES_SITE_ID = B.SALES_SITE_ID AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.ITEM_ID = B.ITEM_ID
                     AND A.ORIGIN_ITEM_ID = B.ORIGIN_ITEM_ID AND A.DOM_EXP = B.DOM_EXP AND A.INCOTERMS = B.INCOTERMS
                     AND A.CURRENCY = B.CURRENCY AND A.YYYYMMDD = B.YYYYMMDD AND A.FCST_TYPE = B.FCST_TYPE
                     AND A.SOLDTO_CODE = B.SOLDTO_CODE AND A.SHIPTO_CODE = B.SHIPTO_CODE AND A.VALID_YN = B.VALID_YN
                     AND A.MEASURE = B.MEASURE AND NVL(A.INTERNAL_TYPE,'~') = NVL(B.INTERNAL_TYPE,'~')
                     AND A.FROM_COMPANY_ID = B.FROM_COMPANY_ID ) AS SO_QTY
              , A.FROM_COMPANY_ID, A.PLANT_ID
        FROM GT_MFSRM_TEMP_DM_RESULT A
        GROUP BY A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID
               , A.ORIGIN_ITEM_ID, A.DOM_EXP, A.INCOTERMS, A.MEASURE, A.CURRENCY, A.YYYYMMDD, A.FCST_TYPE
               , A.SOLDTO_CODE, A.SHIPTO_CODE, A.VALID_YN, A.INTERNAL_TYPE, A.FROM_COMPANY_ID, A.PLANT_ID;

        /* step-3 : RTF 실적 -> DM_PLN_MKT_FCST_RESULT */
        DELETE FROM DM_PLN_MKT_FCST_RESULT
         WHERE MEASURE = 'RTF'
           AND YYYYMMDD <  V_END_YYYYMMDD
           AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        /* #DM_DNM_SALES_RESULT_BEFORE : [E20240415-000036] 예외처리 룩업(DM_EXCEPT_SALES_SITE_MAPPING) 반영 */
        INSERT INTO GT_MFSRM_DM_RESULT_BEFORE
        ( DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD
        , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, INTERNAL_QTY, ATTRIBUTE3, ATTRIBUTE4
        , DM_ESS_RESULT_MAP, SO_NO, SO_QTY, FROM_COMPANY_ID, PLANT_ID )
        SELECT  A.DIVISION_ID, NVL(NULLIF(RTRIM(A.PROJECT_CODE),''), '/') AS PROJECT_CODE
              , NVL(CASE WHEN LENGTH(A.SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN A.SOLDTO_CODE = 'B100' THEN 'C100' ELSE A.SOLDTO_CODE END ELSE A.SALES_SITE_ID END, '/') AS SALES_SITE_ID
              , NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/') AS PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD
              , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN 0 ELSE A.QTY END) AS QTY
              , MAX(A.CREATED_BY), MAX(A.CREATION_DATE), MAX(A.LAST_UPDATED_BY), MAX(A.LAST_UPDATE_DATE), MAX(A.ATTRIBUTE1)
              , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN A.QTY ELSE 0 END) AS INTERNAL_QTY
              , SUM(A.ATTRIBUTE3), MAX(A.ATTRIBUTE4)
              , B.SEGMENT4 AS DM_ESS_RESULT_MAP, A.SO_NO, A.SO_QTY, A.FROM_COMPANY_ID, A.PLANT_ID
        FROM GT_MFSRM_DM_RESULT A
        LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.INTERNAL_TYPE = B.ATTRIBUTE1 AND B.LOOKUP_TYPE = 'DM_ESS_RESULT_MAP'
        LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON C.LOOKUP_TYPE = 'DM_EXCEPT_SALES_SITE_MAPPING' AND C.SEGMENT1 = A.DIVISION_ID AND C.SEGMENT2 = A.SOLDTO_CODE AND C.SEGMENT3 = A.SHIPTO_CODE
        WHERE A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
          AND A.MEASURE = 'SALES_RESULT'
          AND A.YYYYMMDD <  V_END_YYYYMMDD
          AND A.YYYYMMDD >= V_START_YYYYMMDD
          AND NVL(B.SEGMENT4, 'Y') <> 'N'
        GROUP BY A.DIVISION_ID, A.PROJECT_CODE
               , CASE WHEN LENGTH(A.SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN A.SOLDTO_CODE = 'B100' THEN 'C100' ELSE A.SOLDTO_CODE END ELSE A.SALES_SITE_ID END
               , A.PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD
               , B.SEGMENT4, A.SO_NO, A.SO_QTY, A.FROM_COMPANY_ID, A.PLANT_ID;

        INSERT INTO DM_PLN_MKT_FCST_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, YYYYMMDD
        , QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
        , SO_NO, SO_QTY, CELL_PROD_SITE_ID )
        SELECT  A.DIVISION_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP, NVL(A.FCST_TYPE,'MASS') AS FCST_TYPE
              , A.INCOTERMS, 'RTF' AS MEASURE, A.YYYYMMDD
              , SUM(CASE WHEN NVL(A.DM_ESS_RESULT_MAP,'X') = 'Y' THEN 0 ELSE A.QTY END) AS QTY
              , MAX(A.CREATED_BY), MAX(A.CREATION_DATE), MAX(A.LAST_UPDATED_BY), SYSDATE
              , MAX(A.ATTRIBUTE1)
              , SUM(CASE WHEN NVL(A.DM_ESS_RESULT_MAP,'X') = 'Y' THEN A.QTY ELSE 0 END) AS INTERNAL_QTY
              , SUM(A.ATTRIBUTE3), MAX(A.ATTRIBUTE4)
              , ( SELECT LISTAGG(B.SO_NO, ',' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY B.SO_NO)
                    FROM GT_MFSRM_DM_RESULT_BEFORE B
                   WHERE A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SALES_SITE_ID = B.SALES_SITE_ID
                     AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.DOM_EXP = B.DOM_EXP
                     AND NVL(A.FCST_TYPE,'MASS') = NVL(B.FCST_TYPE,'MASS') AND A.INCOTERMS = B.INCOTERMS AND A.YYYYMMDD = B.YYYYMMDD ) AS SO_NO
              , ( SELECT LISTAGG(B.SO_QTY, ',' ON OVERFLOW TRUNCATE) WITHIN GROUP (ORDER BY B.SO_QTY)
                    FROM GT_MFSRM_DM_RESULT_BEFORE B
                   WHERE A.DIVISION_ID = B.DIVISION_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.SALES_SITE_ID = B.SALES_SITE_ID
                     AND A.PLANT_SITE_ID = B.PLANT_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.DOM_EXP = B.DOM_EXP
                     AND NVL(A.FCST_TYPE,'MASS') = NVL(B.FCST_TYPE,'MASS') AND A.INCOTERMS = B.INCOTERMS AND A.YYYYMMDD = B.YYYYMMDD ) AS SO_QTY
              /* [PJ2025-50188] CELL_PROD_SITE_ID : 40 & FROM_COMPANY_ID 有 -> SCM_MST_SITE, 40 & FROM_COMPANY_ID 無 -> PLANT 기반, 그 외 '-' */
              , CASE WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NOT NULL AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN NVL(NULLIF(RTRIM(B.SCM_SITE_ID),''), '/')
                     WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NULL     AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN FN_SCM_SYS_NVL(FN_GET_SCM_SITE_ID_PLANT(A.PLANT_ID, FN_GET_ITEM_OPERATION_GROUP(A.DIVISION_ID, A.ITEM_ID)), '-')
                     ELSE '/' END AS CELL_PROD_SITE_ID
        FROM GT_MFSRM_DM_RESULT_BEFORE A
        LEFT OUTER JOIN ( SELECT DIVISION_ID, COMPANY_ID, SCM_SITE_ID FROM SCM_MST_SITE
                           WHERE SITE_TYPE = 'PLANT' AND OPERATION_GROUP = 'A' AND VALID_YN = 'Y' ) B
               ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_COMPANY_ID = B.COMPANY_ID
        LEFT OUTER JOIN ( SELECT DISTINCT ITEM_ID FROM SCM_ITEM_M_SN
                           WHERE DIVISION_ID = '40' AND FORECAST_INFO_BIZ_TYPE = 'CELL' AND ACTIVE_FLAG = 'Y' ) C
               ON A.ITEM_ID = C.ITEM_ID
        GROUP BY A.DIVISION_ID, A.PROJECT_CODE, A.SALES_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP, NVL(A.FCST_TYPE,'MASS')
               , A.INCOTERMS, A.YYYYMMDD
               , CASE WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NOT NULL AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN NVL(B.SCM_SITE_ID, '/')
                      WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NULL     AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN FN_SCM_SYS_NVL(FN_GET_SCM_SITE_ID_PLANT(A.PLANT_ID, FN_GET_ITEM_OPERATION_GROUP(A.DIVISION_ID, A.ITEM_ID)), '-')
                      ELSE '/' END;

        /* step-4 : [PJ2025-50188] 환율반영 SalesAmt_KRW / MKT_AMT_KRW -> DM_PLN_SALES_PLAN_RESULT */
        DELETE FROM DM_PLN_SALES_PLAN_RESULT
         WHERE MEASURE IN ('RTF','SalesAmt_LOC','SalesAmt_KRW','MKT_AMT_LOC','MKT_AMT_KRW','SalesAmt_KRW_ERP','MKT_AMT_KRW_ERP')
           AND YYYYMMDD <  V_END_YYYYMMDD
           AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_SALES_PLAN_RESULT
        ( DIVISION_ID, COMPANY_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
        , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, CELL_PROD_SITE_ID )
        SELECT  A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SCM_SITE_ID, NVL(NULLIF(RTRIM(A.PLANT_SITE_ID),''), '/') AS PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP
              , NVL(A.FCST_TYPE,'MASS') AS FCST_TYPE, A.INCOTERMS, A.MEASURE, A.YYYYMMDD, A.CURRENCY, A.QTY
              , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE, A.ATTRIBUTE1, A.INTERNAL_QTY
              , CASE WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NOT NULL AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN NVL(NULLIF(RTRIM(B.SCM_SITE_ID),''), '/')
                     WHEN (A.DIVISION_ID = '40' AND A.FROM_COMPANY_ID IS NULL     AND A.ITEM_ID = NVL(C.ITEM_ID,'~')) THEN FN_SCM_SYS_NVL(FN_GET_SCM_SITE_ID_PLANT(A.PLANT_ID, FN_GET_ITEM_OPERATION_GROUP(A.DIVISION_ID, A.ITEM_ID)), '-')
                     ELSE '/' END AS CELL_PROD_SITE_ID
        FROM (
                /* RTF / SalesAmt_LOC / SalesAmt_KRW */
                SELECT DIVISION_ID, COMPANY_ID, NVL(PROJECT_CODE,'/') AS PROJECT_CODE
                     , NVL(CASE WHEN LENGTH(SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN SOLDTO_CODE = 'B100' THEN 'C100' ELSE SOLDTO_CODE END ELSE SALES_SITE_ID END, '/') AS SCM_SITE_ID
                     , NVL(PLANT_SITE_ID,'/') AS PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
                     , CASE A.MEASURE WHEN 'SALES_RESULT' THEN 'RTF' WHEN 'SALES_RESULT_AMOUNT' THEN 'SalesAmt_LOC' WHEN 'SALES_RESULT_AMOUNT_KRW' THEN 'SalesAmt_KRW' ELSE A.MEASURE END AS MEASURE
                     , YYYYMMDD, CURRENCY
                     , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN 0 ELSE QTY END) AS QTY
                     , MAX(A.CREATED_BY) AS CREATED_BY, MAX(A.CREATION_DATE) AS CREATION_DATE, MAX(A.LAST_UPDATED_BY) AS LAST_UPDATED_BY
                     , MAX(A.ATTRIBUTE1) AS ATTRIBUTE1
                     , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN QTY ELSE 0 END) AS INTERNAL_QTY
                     , FROM_COMPANY_ID, PLANT_ID
                  FROM GT_MFSRM_DM_RESULT A
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.INTERNAL_TYPE = B.ATTRIBUTE1 AND B.LOOKUP_TYPE = 'DM_ESS_RESULT_MAP'
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON C.LOOKUP_TYPE = 'DM_EXCEPT_SALES_SITE_MAPPING' AND C.SEGMENT1 = A.DIVISION_ID AND C.SEGMENT2 = A.SOLDTO_CODE AND C.SEGMENT3 = A.SHIPTO_CODE
                 WHERE DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                   AND A.MEASURE IN ('SALES_RESULT','SALES_RESULT_AMOUNT','SALES_RESULT_AMOUNT_KRW')
                   AND YYYYMMDD <  V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
                   AND NVL(B.SEGMENT4, 'Y') <> 'N'
                 GROUP BY DIVISION_ID, COMPANY_ID, NVL(PROJECT_CODE,'/')
                        , NVL(CASE WHEN LENGTH(SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN SOLDTO_CODE = 'B100' THEN 'C100' ELSE SOLDTO_CODE END ELSE SALES_SITE_ID END, '/')
                        , NVL(PLANT_SITE_ID,'/'), ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, A.MEASURE, YYYYMMDD, CURRENCY, FROM_COMPANY_ID, PLANT_ID
                UNION ALL
                /* MKT_AMT_LOC / MKT_AMT_KRW */
                SELECT DIVISION_ID, COMPANY_ID, NVL(PROJECT_CODE,'/') AS PROJECT_CODE
                     , NVL(CASE WHEN LENGTH(SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN SOLDTO_CODE = 'B100' THEN 'C100' ELSE SOLDTO_CODE END ELSE SALES_SITE_ID END, '/') AS SCM_SITE_ID
                     , NVL(PLANT_SITE_ID,'/') AS PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS
                     , CASE A.MEASURE WHEN 'SALES_RESULT_AMOUNT' THEN 'MKT_AMT_LOC' WHEN 'SALES_RESULT_AMOUNT_KRW' THEN 'MKT_AMT_KRW' END AS MEASURE
                     , YYYYMMDD, CURRENCY
                     , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN 0 ELSE QTY END) AS QTY
                     , MAX(A.CREATED_BY) AS CREATED_BY, MAX(A.CREATION_DATE) AS CREATION_DATE, MAX(A.LAST_UPDATED_BY) AS LAST_UPDATED_BY
                     , MAX(A.ATTRIBUTE1) AS ATTRIBUTE1
                     , SUM(CASE WHEN NVL(B.SEGMENT4,'X') = 'Y' THEN QTY ELSE 0 END) AS INTERNAL_QTY
                     , FROM_COMPANY_ID, PLANT_ID
                  FROM GT_MFSRM_DM_RESULT A
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.INTERNAL_TYPE = B.ATTRIBUTE1 AND B.LOOKUP_TYPE = 'DM_ESS_RESULT_MAP'
                  LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON C.LOOKUP_TYPE = 'DM_EXCEPT_SALES_SITE_MAPPING' AND C.SEGMENT1 = A.DIVISION_ID AND C.SEGMENT2 = A.SOLDTO_CODE AND C.SEGMENT3 = A.SHIPTO_CODE
                 WHERE DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                   AND A.MEASURE IN ('SALES_RESULT_AMOUNT','SALES_RESULT_AMOUNT_KRW')
                   AND YYYYMMDD <  V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
                   AND NVL(B.SEGMENT4, 'Y') <> 'N'
                 GROUP BY DIVISION_ID, COMPANY_ID, NVL(PROJECT_CODE,'/')
                        , NVL(CASE WHEN LENGTH(SOLDTO_CODE) = 4 AND C.SEGMENT4 IS NULL THEN CASE WHEN SOLDTO_CODE = 'B100' THEN 'C100' ELSE SOLDTO_CODE END ELSE SALES_SITE_ID END, '/')
                        , NVL(PLANT_SITE_ID,'/'), ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, A.MEASURE, YYYYMMDD, CURRENCY, FROM_COMPANY_ID, PLANT_ID
             ) A
        LEFT OUTER JOIN ( SELECT DIVISION_ID, COMPANY_ID, SCM_SITE_ID FROM SCM_MST_SITE
                           WHERE SITE_TYPE = 'PLANT' AND OPERATION_GROUP = 'A' AND VALID_YN = 'Y' ) B
               ON A.DIVISION_ID = B.DIVISION_ID AND A.FROM_COMPANY_ID = B.COMPANY_ID
        LEFT OUTER JOIN ( SELECT DISTINCT ITEM_ID FROM SCM_ITEM_M_SN
                           WHERE DIVISION_ID = '40' AND FORECAST_INFO_BIZ_TYPE = 'CELL' AND ACTIVE_FLAG = 'Y' ) C
               ON A.ITEM_ID = C.ITEM_ID;

        /* [PJ2025-50188] ERP COPY (SalesAmt_KRW->SalesAmt_KRW_ERP / MKT_AMT_KRW->MKT_AMT_KRW_ERP) : 40 사업부, 1달전 1일 ~ 당일 */
        INSERT INTO DM_PLN_SALES_PLAN_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD
        , CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
        , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
        , COMPANY_ID, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE || '_ERP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD
--             , CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE
             , CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, SYSDATE
             , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
             , COMPANY_ID, CELL_PROD_SITE_ID
        FROM DM_PLN_SALES_PLAN_RESULT
        WHERE MEASURE IN ('SalesAmt_KRW','MKT_AMT_KRW')
          AND YYYYMMDD <  V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
          AND DIVISION_ID = '40'
          AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        /* [PJ2025-50188] 환율 재계산 SalesAmt_KRW / MKT_AMT_KRW : 당월 1일 ~ 당일 (40 사업부) */
        DELETE FROM DM_PLN_SALES_PLAN_RESULT
         WHERE MEASURE IN ('SalesAmt_KRW','MKT_AMT_KRW')
           AND YYYYMMDD >= V_START_YYYYMMDD_EXCHANGE
           AND YYYYMMDD <  V_END_YYYYMMDD
           AND DIVISION_ID = '40'
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_SALES_PLAN_RESULT
        ( DIVISION_ID, COMPANY_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
        , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, CELL_PROD_SITE_ID )
        SELECT A.DIVISION_ID, A.COMPANY_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.PLANT_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
             , C.MEASURE, A.YYYYMMDD, A.CURRENCY
             , A.QTY * B.EXCHANGE_PRICE AS QTY   /* A.QTY 는 (수량*단가) 이므로 환율만 반영 */
--             , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE, A.ATTRIBUTE1, A.ATTRIBUTE2, A.CELL_PROD_SITE_ID
               , A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE, A.ATTRIBUTE1, A.ATTRIBUTE2, A.CELL_PROD_SITE_ID
        FROM DM_PLN_SALES_PLAN_RESULT A
        INNER JOIN DM_MST_EXCHANGE_RATE B
           ON A.DIVISION_ID = B.DIVISION_ID
          AND SUBSTR(A.YYYYMMDD,1,6) || '01' = B.YYYYMMDD   /* EXCHANGE 는 월별 1일 데이터 */
          AND A.CURRENCY = B.UNIT_CURRENCY
          AND B.CURRENCY = 'KRW'
        INNER JOIN ( SELECT 'MKT_AMT_KRW' AS MEASURE FROM DUAL UNION ALL SELECT 'SalesAmt_KRW' FROM DUAL ) C ON 1 = 1
        WHERE A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
          AND A.DIVISION_ID = '40'
          AND A.MEASURE = 'SalesAmt_LOC'
          AND A.YYYYMMDD >= V_START_YYYYMMDD_EXCHANGE
          AND A.YYYYMMDD <  V_END_YYYYMMDD;

        /* step-4b : 20190725 CSR ID:4048421 RTF_SYS_RP (RTF System R+P) MEASURE 추가생성 */
        DELETE FROM DM_PLN_MKT_FCST_RESULT
         WHERE MEASURE = 'RTF_SYS_RP' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_MKT_FCST_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SYS_RP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             --, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY, CELL_PROD_SITE_ID
           , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, SYSDATE, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, SO_NO, SO_QTY, CELL_PROD_SITE_ID
        FROM DM_PLN_MKT_FCST_RESULT
        WHERE MEASURE = 'RTF' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
          AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        DELETE FROM DM_PLN_SALES_PLAN_RESULT
         WHERE MEASURE = 'RTF_SYS_RP' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_SALES_PLAN_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, COMPANY_ID, ATTRIBUTE2, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'RTF_SYS_RP' AS MEASURE, PLANT_SITE_ID, YYYYMMDD, CURRENCY, QTY
             --, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, NVL(COMPANY_ID, '-'), ATTRIBUTE2, CELL_PROD_SITE_ID
             , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, SYSDATE, NVL(NULLIF(RTRIM(COMPANY_ID),''), '/'), ATTRIBUTE2, CELL_PROD_SITE_ID
        FROM DM_PLN_SALES_PLAN_RESULT
        WHERE MEASURE = 'RTF' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
          AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        /* step-5 : AS 재고 및 입출고 실적 [PJ20209643] -> #AS_tmpData (GT_MFSRM_AS_TMPDATA) */
        INSERT INTO GT_MFSRM_AS_TMPDATA
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY )
        WITH AS_INV_DATA AS (
            SELECT MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP
                 , TO_CHAR(TO_DATE(S.CUTOFF_DATE,'YYYYMMDD')-1,'YYYYMMDD') AS YYYYMMDD, SUM(S.QTY) AS QTY
              FROM ( SELECT S.DIVISION_ID, S.STORAGE_ID, S.ITEM_ID, S.QTY, TO_CHAR(S.CUTOFF_DATE,'YYYYMMDD') AS CUTOFF_DATE, NULL AS PLANT_ID
                       FROM SCM_DNM_STOCK_SN S WHERE S.CUTOFF_DATE >= TO_DATE(V_START_YYYYMMDD,'YYYYMMDD')
                     UNION ALL   /* [C20201103-000114] */
                     SELECT S.DIVISION_ID, S.STORAGE_ID, S.ITEM_ID, S.QTY, S.RESULT_DATE, S.PLANT_ID
                       FROM SCM_DNM_STOCK_SALES S WHERE S.RESULT_DATE >= V_START_YYYYMMDD AND S.DIVISION_ID = '82'
                   ) S
                 , SCM_MST_LOCATION L, SCM_MST_SITE M, SCM_MST_SITE_ITEM SI
                 , ( SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP
                          , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID ORDER BY A.YYYYMMDD DESC) AS ROW_NUMS   /* [C20210120-000090] */
                       FROM DM_PLN_MKT_FCST A, SCM_MST_SITE B
                      WHERE A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                        AND A.QTY > 0 AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.OPERATION_GROUP = 'W'
                   ) MF
             WHERE L.DIVISION_ID = S.DIVISION_ID AND L.STORAGE_ID = S.STORAGE_ID
               AND L.PLANT_ID = CASE WHEN S.PLANT_ID IS NULL THEN L.PLANT_ID ELSE S.PLANT_ID END
               AND L.SCM_SITE_ID = M.SCM_SITE_ID AND L.VALID_YN = 'Y' AND M.SITE_TYPE = 'SALES' AND M.OPERATION_GROUP = 'W'
               AND M.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
               AND SI.ITEM_ID LIKE (CASE WHEN SUBSTR(S.ITEM_ID,1,2) = 'MP' THEN SUBSTR(S.ITEM_ID,1,11) ELSE S.ITEM_ID END) || '%'
               AND L.DIVISION_ID = SI.DIVISION_ID AND SI.VALID_YN = 'Y'
               AND L.DIVISION_ID = MF.DIVISION_ID AND L.SCM_SITE_ID = MF.SCM_SITE_ID AND SI.ITEM_ID = MF.ITEM_ID AND MF.ROW_NUMS = 1
               AND MF.PROJECT_CODE = SI.PROJECT_CODE AND MF.SCM_SITE_ID = SI.SCM_SITE_ID   /* added by ytchoi 180813 */
             GROUP BY MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP
                    , TO_CHAR(TO_DATE(S.CUTOFF_DATE,'YYYYMMDD')-1,'YYYYMMDD')
        )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'AS_Inv' AS MEASURE, ' ' AS PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID, YYYYMMDD, QTY   /* INV 는 CELL_PROD_SITE_ID 무관 '-' */
          FROM AS_INV_DATA
         WHERE QTY <> 0 AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD AND PROJECT_CODE NOT LIKE '%개발%';   /* [C20210831-000303] */

        /* AS_In_Plan / AS_In_Req [C20221118-000024] [E20251029-000956] PROJECT_CODE 보완 (SCM_DNM_EXFACTORY_RESULT -> SSP_ANL_SHIP_CONFIRM fallback, NULL 미적재) */
        INSERT INTO GT_MFSRM_AS_TMPDATA
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY )
        WITH CTE_DOM_T AS (
            SELECT DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID, CASE WHEN COUNT(DOM_EXP) > 1 THEN 'E' ELSE MAX(DOM_EXP) END AS DOM_EXP
              FROM ( SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.DOM_EXP
                       FROM DM_PLN_MKT_FCST A
                      INNER JOIN ( SELECT DIVISION_ID, SCM_SITE_ID FROM SCM_MST_SITE
                                    WHERE VALID_YN = 'Y' AND SITE_TYPE = 'SALES' AND OPERATION_GROUP = 'W' ) B
                            ON A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                           AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID
                           AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_END_YYYYMMDD,'YYYYMMDD'),'MON')-7,'YYYYMMDD')   /* 당주 월요일 이후 */
                      GROUP BY A.DIVISION_ID, A.ITEM_ID, A.PROJECT_CODE, A.DOM_EXP, A.SCM_SITE_ID ) C
             GROUP BY DIVISION_ID, ITEM_ID, PROJECT_CODE, SCM_SITE_ID
        ), CTE_AS_TEMP_DATA AS (
            SELECT T.DIVISION_ID, T.PROJECT_CODE, T.SCM_SITE_ID, T.ITEM_ID, T.DOM_EXP
                 , T.FCST_TYPE, T.INCOTERMS, T.PLANT_SITE_ID, T.YYYYMMDD, T.QTY, T.CONFIRM_ID, T.CELL_PROD_SITE_ID
              FROM ( SELECT A.DIVISION_ID
                          /* [E20251029-000956] PROJECT_CODE : 1.EXFACTORY 2.SHIP_CONFIRM fallback */
                          , CASE WHEN A.PROJECT_CODE IS NULL THEN D.PROJECT_CODE ELSE A.PROJECT_CODE END AS PROJECT_CODE
                          , C.SCM_SITE_ID AS SCM_SITE_ID, A.ITEM_ID, NVL(E.DOM_EXP,'E') AS DOM_EXP
                          , D.FCST_TYPE, A.INCOTERMS, A.PLANT_ID AS PLANT_SITE_ID, A.PLANT_ISSUE_DATE AS YYYYMMDD
                          , A.EXFACTORY_QTY AS QTY, A.CONFIRM_ID, CASE WHEN A.DIVISION_ID = '40' THEN A.FROM_SCM_SITE_ID ELSE '-' END AS CELL_PROD_SITE_ID
                       FROM SCM_DNM_EXFACTORY_RESULT A
                      INNER JOIN ( SELECT DIVISION_ID, SCM_SITE_ID FROM SCM_MST_SITE
                                    WHERE VALID_YN = 'Y' AND SITE_TYPE = 'SALES' AND OPERATION_GROUP = 'W' ) C
                            ON A.DIVISION_ID = C.DIVISION_ID AND A.TO_SCM_SITE_ID = C.SCM_SITE_ID
                           AND NVL(A.EXFACTORY_STATUS,'D90') NOT IN ('D90','D10')
                      INNER JOIN ( SELECT DIVISION_ID, CONFIRM_ID, FCST_TYPE, DOM_EXP, PROJECT_CODE FROM SSP_ANL_SHIP_CONFIRM ) D   /* [E20251029-000956] PROJECT_CODE 추가 */
                            ON A.DIVISION_ID = D.DIVISION_ID AND A.CONFIRM_ID = D.CONFIRM_ID
                      LEFT OUTER JOIN CTE_DOM_T E
                            ON A.DIVISION_ID = E.DIVISION_ID AND C.SCM_SITE_ID = E.SCM_SITE_ID
                           AND A.PROJECT_CODE = E.PROJECT_CODE AND A.ITEM_ID = E.ITEM_ID
                      WHERE A.EXFACTORY_DATE < V_END_YYYYMMDD AND A.EXFACTORY_DATE >= V_START_YYYYMMDD AND LENGTH(A.PLANT_ISSUE_DATE) > 0
                   ) T
             WHERE T.PROJECT_CODE IS NOT NULL   /* [E20251029-000956] PROJECT_CODE 처리 후에도 NULL 인 건은 미적재 */
        )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'AS_In_Plan' AS MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM CTE_AS_TEMP_DATA WHERE QTY <> 0
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'AS_In_Req' AS MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM CTE_AS_TEMP_DATA WHERE QTY <> 0
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD;

        DELETE FROM DM_PLN_MKT_FCST_RESULT
         WHERE MEASURE IN ('AS_Inv','AS_In_Plan','AS_In_Req') AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_MKT_FCST_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE, CELL_PROD_SITE_ID
        FROM GT_MFSRM_AS_TMPDATA
        WHERE DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);   /* 2022.11.28 */

        /* step-6 : 20180727 KHSONG 소형/ESS VMI 재고 및 입고 실적 -> #VMI_tmpData (GT_MFSRM_VMI_TMPDATA) */
        INSERT INTO GT_MFSRM_VMI_TMPDATA
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY )
        WITH VMI_INV_DATA AS (
            SELECT MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP
                 , TO_CHAR(TO_DATE(S.CUTOFF_DATE,'YYYYMMDD')-1,'YYYYMMDD') AS YYYYMMDD, SUM(S.QTY) AS QTY
              FROM ( SELECT S.DIVISION_ID, S.STORAGE_ID, S.ITEM_ID, S.QTY, TO_CHAR(S.CUTOFF_DATE,'YYYYMMDD') AS CUTOFF_DATE, NULL AS PLANT_ID
                       FROM SCM_DNM_STOCK_SN S WHERE S.CUTOFF_DATE >= TO_DATE(V_START_YYYYMMDD,'YYYYMMDD')
                     UNION ALL   /* [C20201103-000114] */
                     SELECT S.DIVISION_ID, S.STORAGE_ID, S.ITEM_ID, S.QTY, S.RESULT_DATE, S.PLANT_ID
                       FROM SCM_DNM_STOCK_SALES S WHERE S.RESULT_DATE >= V_START_YYYYMMDD AND S.DIVISION_ID = '82'
                   ) S
                 , SCM_MST_LOCATION L, SCM_MST_SITE M, SCM_MST_SITE_ITEM SI
                 , ( SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP
                          , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID ORDER BY A.YYYYMMDD DESC) AS ROW_NUMS
                       FROM DM_PLN_MKT_FCST A, SCM_MST_SITE B
                      WHERE A.DIVISION_ID IN ('40','82')   /* CSR ID:4059971 ESS 추가 */
                        AND A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                        AND A.QTY > 0 AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.VMI_YN = 'Y'
                   ) MF
             WHERE L.DIVISION_ID = S.DIVISION_ID AND L.STORAGE_ID = S.STORAGE_ID
               AND L.PLANT_ID = CASE WHEN S.PLANT_ID IS NULL THEN L.PLANT_ID ELSE S.PLANT_ID END
               AND L.SCM_SITE_ID = M.SCM_SITE_ID AND L.VALID_YN = 'Y' AND M.SITE_TYPE = 'SALES' AND M.VMI_YN = 'Y'
               AND M.DIVISION_ID IN ('40','82') AND M.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
               AND SI.ITEM_ID LIKE (CASE WHEN SUBSTR(S.ITEM_ID,1,2) = 'MP' THEN SUBSTR(S.ITEM_ID,1,11) ELSE S.ITEM_ID END) || '%'
               AND L.DIVISION_ID = SI.DIVISION_ID AND SI.VALID_YN = 'Y'
               AND L.DIVISION_ID = MF.DIVISION_ID AND L.SCM_SITE_ID = MF.SCM_SITE_ID AND SI.ITEM_ID = MF.ITEM_ID AND MF.ROW_NUMS = 1
               AND MF.PROJECT_CODE = SI.PROJECT_CODE AND MF.SCM_SITE_ID = SI.SCM_SITE_ID
             GROUP BY MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP
                    , TO_CHAR(TO_DATE(S.CUTOFF_DATE,'YYYYMMDD')-1,'YYYYMMDD')
        )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_Inv' AS MEASURE, ' ' AS PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID, YYYYMMDD, QTY
          FROM VMI_INV_DATA
         WHERE QTY <> 0 AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD AND PROJECT_CODE NOT LIKE '%개발%';

        /* VMI_In_Plan / VMI_In_Req (82 사업부, SCM_DNM_MAT_DOCUMENT, [PJ20228272] NERP 대응 룩업) */
        INSERT INTO GT_MFSRM_VMI_TMPDATA
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY )
        WITH VMI_WHIN_DATA AS (
            SELECT MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP, S.DOC_POSTING_DATE AS YYYYMMDD
                 , CASE WHEN S.STORAGE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_03')))
                         AND S.MOVEMENT_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','MOVEMENT_TYPE_01')))
                        THEN SUM(S.MAT_QTY) * -1 ELSE SUM(S.MAT_QTY) END AS QTY
                 , S.STORAGE_ID
              FROM SCM_DNM_MAT_DOCUMENT S
                 , SCM_MST_LOCATION L, SCM_MST_SITE M, SCM_MST_SITE_ITEM SI
                 , ( SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP
                          , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID ORDER BY A.YYYYMMDD) AS ROW_NUMS
                       FROM DM_PLN_MKT_FCST A, SCM_MST_SITE B
                      WHERE A.DIVISION_ID IN ('82') AND A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                        AND A.QTY > 0 AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.VMI_YN = 'Y'
                        AND A.MEASURE LIKE 'VMI%'
                        AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_END_YYYYMMDD,'YYYYMMDD'),'MON')-7,'YYYYMMDD')
                   ) MF
             WHERE 1 = 1 AND L.STORAGE_ID = S.STORAGE_ID
               AND S.STORAGE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_01')))
               AND S.MOVEMENT_TYPE = FN_GET_LOOKUP_VALUE_DESC('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_01', S.STORAGE_ID, 'NOT MATCH')
               AND S.INDICATOR = 'S'
               AND L.SCM_SITE_ID = M.SCM_SITE_ID AND L.VALID_YN = 'Y' AND M.SITE_TYPE = 'SALES' AND M.VMI_YN = 'Y'
               AND M.DIVISION_ID IN ('82') AND M.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
               AND SI.ITEM_ID LIKE (CASE WHEN SUBSTR(S.ITEM_ID,1,2) = 'MP' THEN SUBSTR(S.ITEM_ID,1,11) ELSE S.ITEM_ID END) || '%'
               AND L.DIVISION_ID = SI.DIVISION_ID AND SI.VALID_YN = 'Y'
               AND L.DIVISION_ID = MF.DIVISION_ID AND L.SCM_SITE_ID = MF.SCM_SITE_ID AND SI.ITEM_ID = MF.ITEM_ID AND MF.ROW_NUMS = 1
               AND MF.PROJECT_CODE = SI.PROJECT_CODE AND MF.SCM_SITE_ID = SI.SCM_SITE_ID
               AND S.ATTRIBUTE2 IS NULL   /* [C20210908-000163] */
             GROUP BY MF.DIVISION_ID, MF.SCM_SITE_ID, MF.ITEM_ID, MF.PROJECT_CODE, MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP, S.DOC_POSTING_DATE, S.STORAGE_ID, S.MOVEMENT_TYPE
        )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_In_Plan' AS MEASURE, ' ' AS PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM VMI_WHIN_DATA
         WHERE QTY <> 0 AND DIVISION_ID = '82' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_In_Req' AS MEASURE, ' ' AS PLANT_SITE_ID
             , '-' AS CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD, QTY
                   FROM VMI_WHIN_DATA
                  WHERE QTY <> 0 AND DIVISION_ID = '82' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD ) A
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, YYYYMMDD;

        /* step-7 : [C20210618-000288] 40 사업부 VMI (#T_MF, #VMI_RESULT). [PJ2025-50188] DM_PLN_CFM_MKT_DEMAND_PLAN 사용 */
        INSERT INTO GT_MFSRM_T_MF
        ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, CELL_PROD_SITE_ID, ROW_NUMS )
        SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.CELL_PROD_SITE_ID
             , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID ORDER BY A.YYYYMMDD)
        FROM DM_PLN_CFM_MKT_DEMAND_PLAN A
        JOIN SCM_MST_SITE B ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.VMI_YN = 'Y'
        WHERE A.DIVISION_ID IN ('40') AND A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
          AND A.QTY > 0 AND A.MEASURE LIKE 'VMI%'
          AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_END_YYYYMMDD,'YYYYMMDD'),'MON')-7,'YYYYMMDD');

        INSERT INTO GT_MFSRM_VMI_RESULT
        ( DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, YYYYMMDD, QTY, STORAGE_ID, CELL_PROD_SITE_ID )
        WITH VMI_WHIN_DATA_40 AS (
            SELECT NVL(MF.DIVISION_ID, SI.DIVISION_ID) AS DIVISION_ID
                 , NVL(MF.SCM_SITE_ID, SI.SCM_SITE_ID) AS SCM_SITE_ID
                 , NVL(MF.ITEM_ID, SI.ITEM_ID) AS ITEM_ID
                 , NVL(MF.PROJECT_CODE, SI.PROJECT_CODE) AS PROJECT_CODE
                 , MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP, S.DOC_POSTING_DATE AS YYYYMMDD
                 , CASE WHEN S.STORAGE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_03')))
                         AND S.MOVEMENT_TYPE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','MOVEMENT_TYPE_01')))
                        THEN SUM(S.MAT_QTY) * -1 ELSE SUM(S.MAT_QTY) END AS QTY
                 , S.STORAGE_ID
                 , NVL(MF.CELL_PROD_SITE_ID, '/') AS CELL_PROD_SITE_ID
              FROM SCM_DNM_MAT_DOCUMENT S
              JOIN SCM_MST_LOCATION L ON S.STORAGE_ID = L.STORAGE_ID AND L.VALID_YN = 'Y'
              JOIN SCM_MST_SITE M ON L.SCM_SITE_ID = M.SCM_SITE_ID AND M.SITE_TYPE = 'SALES' AND M.VMI_YN = 'Y' AND M.DIVISION_ID IN ('40')
                                 AND L.DIVISION_ID = M.DIVISION_ID AND M.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
              JOIN SCM_MST_SITE_ITEM SI ON L.DIVISION_ID = SI.DIVISION_ID AND SI.VALID_YN = 'Y' AND M.SCM_SITE_ID = SI.SCM_SITE_ID
                                       AND SI.ITEM_ID LIKE (CASE WHEN SUBSTR(S.ITEM_ID,1,2) = 'MP' THEN SUBSTR(S.ITEM_ID,1,11) ELSE S.ITEM_ID END) || '%'
              LEFT OUTER JOIN GT_MFSRM_T_MF MF ON MF.PROJECT_CODE = SI.PROJECT_CODE AND MF.SCM_SITE_ID = SI.SCM_SITE_ID AND SI.ITEM_ID = MF.ITEM_ID AND MF.ROW_NUMS = 1
                                              AND L.DIVISION_ID = MF.DIVISION_ID AND L.SCM_SITE_ID = MF.SCM_SITE_ID
             WHERE 1 = 1
               AND S.STORAGE_ID IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_01')))
               AND S.MOVEMENT_TYPE = FN_GET_LOOKUP_VALUE_DESC('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_01', S.STORAGE_ID, 'NOT MATCH')
               AND S.INDICATOR = 'S'
               AND S.DOC_POSTING_DATE >= V_START_YYYYMMDD
               AND NVL(MF.PROJECT_CODE, SI.PROJECT_CODE) NOT LIKE '%개발%'
               AND S.ATTRIBUTE2 IS NULL
             GROUP BY NVL(MF.DIVISION_ID, SI.DIVISION_ID), NVL(MF.SCM_SITE_ID, SI.SCM_SITE_ID), NVL(MF.ITEM_ID, SI.ITEM_ID), NVL(MF.PROJECT_CODE, SI.PROJECT_CODE)
                    , MF.FCST_TYPE, MF.INCOTERMS, MF.DOM_EXP, S.DOC_POSTING_DATE, S.STORAGE_ID, S.MOVEMENT_TYPE
                    , NVL(MF.CELL_PROD_SITE_ID, '/')
        )
        SELECT DIVISION_ID, SCM_SITE_ID, ITEM_ID, PROJECT_CODE, FCST_TYPE, INCOTERMS, DOM_EXP, YYYYMMDD, QTY, STORAGE_ID, CELL_PROD_SITE_ID
          FROM VMI_WHIN_DATA_40;

        /* FCST_TYPE NULL 보정 1) 동일 SITE 다른 MODEL 입출고 내역 (자기참조). UPDATE FROM JOIN -> MERGE */
        MERGE INTO GT_MFSRM_VMI_RESULT A
        USING ( SELECT SCM_SITE_ID, FCST_TYPE, INCOTERMS, DOM_EXP
                  FROM ( SELECT SCM_SITE_ID, FCST_TYPE, INCOTERMS, DOM_EXP
                              , ROW_NUMBER() OVER (PARTITION BY SCM_SITE_ID ORDER BY FCST_TYPE) RN
                           FROM ( SELECT DISTINCT SCM_SITE_ID, FCST_TYPE, INCOTERMS, DOM_EXP FROM GT_MFSRM_VMI_RESULT WHERE FCST_TYPE IS NOT NULL ) )
                 WHERE RN = 1 ) B
        ON (A.SCM_SITE_ID = B.SCM_SITE_ID)
        WHEN MATCHED THEN UPDATE SET A.FCST_TYPE = B.FCST_TYPE, A.INCOTERMS = B.INCOTERMS, A.DOM_EXP = B.DOM_EXP
             WHERE A.FCST_TYPE IS NULL;

        /* FCST_TYPE NULL 보정 2) DM_PLN_CFM_MKT_DEMAND_PLAN MKT_FCST 메저 참조 */
        MERGE INTO GT_MFSRM_VMI_RESULT A
        USING ( SELECT A2.DIVISION_ID, A2.SCM_SITE_ID, A2.ITEM_ID, A2.PROJECT_CODE, A2.FCST_TYPE, A2.INCOTERMS, A2.DOM_EXP
                  FROM ( SELECT A1.DIVISION_ID, A1.SCM_SITE_ID, A1.ITEM_ID, A1.PROJECT_CODE, A1.FCST_TYPE, A1.INCOTERMS, A1.DOM_EXP
                              , ROW_NUMBER() OVER (PARTITION BY A1.DIVISION_ID, A1.SCM_SITE_ID, A1.ITEM_ID ORDER BY A1.YYYYMMDD) ROW_NUMS
                           FROM DM_PLN_CFM_MKT_DEMAND_PLAN A1
                           JOIN SCM_MST_SITE B1 ON A1.DIVISION_ID = B1.DIVISION_ID AND A1.SCM_SITE_ID = B1.SCM_SITE_ID AND B1.VMI_YN = 'Y'
                          WHERE A1.DIVISION_ID IN ('40') AND A1.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                            AND A1.QTY > 0 AND A1.MEASURE LIKE 'MKT_FCST%'
                            AND A1.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_END_YYYYMMDD,'YYYYMMDD'),'MON')-7,'YYYYMMDD') ) A2
                 WHERE A2.ROW_NUMS = 1 ) B
        ON (A.PROJECT_CODE = B.PROJECT_CODE AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.ITEM_ID = B.ITEM_ID AND A.DIVISION_ID = B.DIVISION_ID)
        WHEN MATCHED THEN UPDATE SET A.FCST_TYPE = B.FCST_TYPE, A.INCOTERMS = B.INCOTERMS, A.DOM_EXP = B.DOM_EXP
             WHERE A.FCST_TYPE IS NULL;

        /* FCST_TYPE NULL 보정 3) 룩업 SITE별 기본값 (DM_VMI_RESULT_DEFAULT) */
        MERGE INTO GT_MFSRM_VMI_RESULT A
        USING ( SELECT SEGMENT1, SEGMENT2, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3
                  FROM ( SELECT B.SEGMENT1, B.SEGMENT2, B.ATTRIBUTE1, B.ATTRIBUTE2, B.ATTRIBUTE3
                              , ROW_NUMBER() OVER (PARTITION BY B.SEGMENT1, B.SEGMENT2 ORDER BY B.ATTRIBUTE1) RN
                           FROM SCM_ADM_LOOKUP_MASTER_DETAIL B
                           JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C ON B.ATTRIBUTE1 = C.SEGMENT1 AND C.LOOKUP_TYPE = 'SALES_TYPE_CODE'
                          WHERE B.LOOKUP_TYPE = 'DM_VMI_RESULT_DEFAULT' AND B.VALID_YN = 'Y' )
                 WHERE RN = 1 ) B
        ON (A.DIVISION_ID = B.SEGMENT1 AND A.SCM_SITE_ID = B.SEGMENT2)
        WHEN MATCHED THEN UPDATE SET A.FCST_TYPE = B.ATTRIBUTE1, A.INCOTERMS = B.ATTRIBUTE2, A.DOM_EXP = B.ATTRIBUTE3
             WHERE A.FCST_TYPE IS NULL;

        /* 처리할 수 없는 데이터(FCST_TYPE NULL)는 삭제 (mkt fcst insert 중 오류 방지) */
        DELETE FROM GT_MFSRM_VMI_RESULT WHERE FCST_TYPE IS NULL;

        INSERT INTO GT_MFSRM_VMI_TMPDATA
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_In_Plan' AS MEASURE, ' ' AS PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM GT_MFSRM_VMI_RESULT
         WHERE QTY <> 0 AND DIVISION_ID = '40' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, CELL_PROD_SITE_ID, YYYYMMDD
        UNION ALL
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, 'VMI_In_Req' AS MEASURE, ' ' AS PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, SUM(QTY)
          FROM ( SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, CELL_PROD_SITE_ID, YYYYMMDD, QTY
                   FROM GT_MFSRM_VMI_RESULT
                  WHERE QTY <> 0 AND DIVISION_ID = '40' AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD ) A
         GROUP BY DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, CELL_PROD_SITE_ID, YYYYMMDD;


        DELETE FROM DM_PLN_MKT_FCST_RESULT
         WHERE MEASURE IN ('VMI_Inv','VMI_In_Plan','VMI_In_Req') AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN ('40','82') AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);
        DELETE FROM DM_PLN_SALES_PLAN_RESULT
         WHERE MEASURE IN ('VMI_Inv','VMI_In_Plan','VMI_In_Req') AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID IN ('40','82') AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_MKT_FCST_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE, CELL_PROD_SITE_ID
        FROM GT_MFSRM_VMI_TMPDATA;

        INSERT INTO DM_PLN_SALES_PLAN_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, COMPANY_ID
        , YYYYMMDD, CURRENCY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, CELL_PROD_SITE_ID )
        SELECT DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, ' ' AS COMPANY_ID
             , YYYYMMDD, '-' AS CURRENCY, QTY, 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE, CELL_PROD_SITE_ID
        FROM GT_MFSRM_VMI_TMPDATA;

        /* step-8 : 20181015 KHSONG 자동차(81%) dm_pln_mkt_fcst_result VMI_In_Plan / VMI_In_Req 생성 */
        DELETE FROM DM_PLN_MKT_FCST_RESULT
         WHERE MEASURE IN ('VMI_In_Plan','VMI_In_Req') AND YYYYMMDD < V_END_YYYYMMDD AND YYYYMMDD >= V_START_YYYYMMDD
           AND DIVISION_ID LIKE '81%' AND DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION);

        INSERT INTO DM_PLN_MKT_FCST_RESULT
        ( DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE, PLANT_SITE_ID, YYYYMMDD, QTY
        , CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, CELL_PROD_SITE_ID )
        SELECT EXFACTORY.DIVISION_ID, TARGET_MKTFCST.PROJECT_CODE, TARGET_SITE.SCM_SITE_ID, EXFACTORY.ITEM_ID
             , TARGET_MKTFCST.DOM_EXP, TARGET_MKTFCST.FCST_TYPE, TARGET_MKTFCST.INCOTERMS, MEASURE_IN.MEASURE, TARGET_MKTFCST.PLANT_SITE_ID
             , EXFACTORY.ACTUAL_EXFACTORY_DATE AS YYYYMMDD, SUM(EXFACTORY.EXFACTORY_QTY) AS QTY
             , 'SYSTEM', SYSDATE, 'SYSTEM', SYSDATE, '-' AS CELL_PROD_SITE_ID
        FROM SCM_DNM_EXFACTORY_RESULT EXFACTORY
        INNER JOIN SCM_MST_SITE TARGET_SITE
           ON EXFACTORY.DIVISION_ID = TARGET_SITE.DIVISION_ID AND EXFACTORY.TO_SCM_SITE_ID = TARGET_SITE.SCM_SITE_ID
          AND TARGET_SITE.VMI_YN = 'Y' AND TARGET_SITE.VALID_YN = 'Y'
        INNER JOIN ( SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID, A.PROJECT_CODE, A.FCST_TYPE, A.INCOTERMS, A.DOM_EXP, A.PLANT_SITE_ID
                          , FN_GET_LOOKUP_VALUE_DESC('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','PLANT_ID_01', SUBSTR(A.PLANT_SITE_ID,1,4), 'OTHER') AS PLANT2   /* [PJ20228272] */
                          , ROW_NUMBER() OVER (PARTITION BY A.DIVISION_ID, A.SCM_SITE_ID, A.ITEM_ID
                                             , FN_GET_LOOKUP_VALUE_DESC('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','PLANT_ID_01', SUBSTR(A.PLANT_SITE_ID,1,4), 'OTHER') ORDER BY A.YYYYMMDD) AS ROW_NUMS
                       FROM DM_PLN_MKT_FCST A, SCM_MST_SITE B
                      WHERE A.DIVISION_ID LIKE '81%' AND A.DIVISION_ID IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                        AND A.QTY > 0 AND A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND B.VMI_YN = 'Y'
                        AND A.MEASURE LIKE 'VMI%'
                        AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(TO_DATE(V_END_YYYYMMDD,'YYYYMMDD'),'MON')-7,'YYYYMMDD') ) TARGET_MKTFCST
           ON EXFACTORY.DIVISION_ID = TARGET_MKTFCST.DIVISION_ID AND EXFACTORY.TO_SCM_SITE_ID = TARGET_MKTFCST.SCM_SITE_ID
          AND TARGET_MKTFCST.ROW_NUMS = 1 AND EXFACTORY.ITEM_ID = TARGET_MKTFCST.ITEM_ID
          AND EXFACTORY.ACTUAL_EXFACTORY_DATE < V_END_YYYYMMDD AND EXFACTORY.ACTUAL_EXFACTORY_DATE >= V_START_YYYYMMDD
          AND FN_GET_LOOKUP_VALUE_DESC('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','STORAGE_ID_02', EXFACTORY.STORAGE_ID, FN_GET_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','PLANT_ID_02')) = TARGET_MKTFCST.PLANT2
        , ( SELECT 'VMI_In_Plan' AS MEASURE FROM DUAL UNION ALL SELECT 'VMI_In_Req' FROM DUAL ) MEASURE_IN
        WHERE EXFACTORY.ORDER_TYPE_CODE IN (SELECT COLUMN_VALUE FROM TABLE(FN_LIST_LOOKUP_VALUE('PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING','ORDER_TYPE_CODE_01')))
        GROUP BY EXFACTORY.DIVISION_ID, TARGET_SITE.SCM_SITE_ID, EXFACTORY.ITEM_ID, TARGET_MKTFCST.PROJECT_CODE, TARGET_MKTFCST.FCST_TYPE
               , TARGET_MKTFCST.INCOTERMS, TARGET_MKTFCST.DOM_EXP, TARGET_MKTFCST.PLANT_SITE_ID, MEASURE_IN.MEASURE, EXFACTORY.ACTUAL_EXFACTORY_DATE;

        COMMIT;

        /* step-9 : [E20250404-001534] 지연 빌링 발생 시 수요계획 보정 (룩업 일정 기준 반복 처리) */
        INSERT INTO GT_MFSRM_DELAY_DAY (DIVISION_ID, STATES, SEQ)
        SELECT SEGMENT1, ATTRIBUTE1, ROW_NUMBER() OVER (ORDER BY SEGMENT1, ATTRIBUTE1)
          FROM ( SELECT SEGMENT1, ATTRIBUTE1
                   FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                  WHERE LOOKUP_TYPE = 'RESULT_MAPPING_SCHEDULE' AND VALID_YN = 'Y' AND SEGMENT4 = 'DELAY'
                    AND SEGMENT1 IN (SELECT DIVISION_ID FROM GT_MFSRM_I_DIVISION)
                    AND SUBSTR(SEGMENT3,1,2) BETWEEN TO_CHAR(SYSDATE - 1/24,'HH24') AND TO_CHAR(SYSDATE,'HH24')
                    AND SEGMENT2 = (SELECT DAYOFWEEK FROM SCM_SYS_CALENDAR_M WHERE BASIS_YYYYMMDD = TO_CHAR(SYSDATE,'YYYYMMDD'))
                  GROUP BY SEGMENT1, ATTRIBUTE1 );
        N_ROWCNT := SQL%ROWCOUNT;

        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := u'\c9c0\c5f0\be4c\b9c1 \d655\c778';
        V_DESCRIPTION := u'\c9c0\c5f0\be4c\b9c1 \b300\c0c1\d655\c778: ' || TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') || u'  \c0ac\c5c5\bd80: ' || V_DEDUCTED_DIVISION_ID || u' \c694\ccad\c0c1\d0dc: ' || V_STATES;
        D_EVENT_DATE  := SYSDATE;
        N_LOG_COUNT   := N_ROWCNT;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

        FOR REC IN (SELECT DIVISION_ID, STATES FROM GT_MFSRM_DELAY_DAY ORDER BY SEQ) LOOP
            V_DEDUCTED_DIVISION_ID := REC.DIVISION_ID;
            V_STATES               := REC.STATES;


            DELETE FROM GT_MFSRM_DEDUCTED_ITEM;
            INSERT INTO GT_MFSRM_DEDUCTED_ITEM (DIVISION_ID, SCM_SITE_ID, PROJECT_CODE, ITEM_ID)
            SELECT A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID
--            FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.OWNER, A.REAL_OWNER, B.DEPT_ID
--                     FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.OWNER, S.COLUMN_VALUE AS REAL_OWNER
--            FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.OWNER, A.REAL_OWNER, A.DEPT_ID                            -- 2026.09.03 AJS
--                     FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.OWNER, S.COLUMN_VALUE AS REAL_OWNER, A.DEPT_ID   -- 2026.09.03 AJS
--                              FROM SCM_MST_SITE_ITEM A, TABLE(STRING_SPLIT(A.OWNER, ',')) S
--                             WHERE A.VALID_YN = 'Y' AND A.OWNER IS NOT NULL ) A
--                     INNER JOIN SCM_MST_SSO_USER_INFO B ON A.REAL_OWNER = B.USER_ID
            FROM ( SELECT A.DIVISION_ID, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.OWNER, A.DEPT_ID                                            -- 2026.09.03 AJS · 2026.09.06 AJS
                     FROM SCM_MST_SITE_ITEM A                                                                                                    -- 2026.09.06 AJS
                     INNER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL C
--                             ON A.DIVISION_ID = V_DEDUCTED_DIVISION_ID AND A.ITEM_ID = C.SEGMENT2 AND B.DEPT_ID = C.SEGMENT3
                             ON A.DIVISION_ID = V_DEDUCTED_DIVISION_ID AND A.ITEM_ID = C.SEGMENT2 AND A.DEPT_ID = C.SEGMENT3                     -- 2026.09.03 AJS
                            AND C.LOOKUP_TYPE = 'DM_DELAY_BILLING_AUTO_DEDUCTED'
                    WHERE A.VALID_YN = 'Y'                                                                                                       -- 2026.09.06 AJS
                 ) A
            GROUP BY A.DIVISION_ID, A.SCM_SITE_ID, A.PROJECT_CODE, A.ITEM_ID;
            N_ROWCNT := SQL%ROWCOUNT;

            V_LOG_TYPE    := 'APPEND';
            V_LOG_MESSAGE := u'\c9c0\c5f0\be4c\b9c1\c218\d589\c2dc\c791';
            V_DESCRIPTION := u'\c9c0\c5f0\be4c\b9c1 \c218\d589 \c2dc\c791: ' || TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') || u'  \c0ac\c5c5\bd80: ' || V_DEDUCTED_DIVISION_ID || u' \c694\ccad\c0c1\d0dc: ' || V_STATES;
            D_EVENT_DATE  := SYSDATE;
            N_LOG_COUNT   := N_ROWCNT;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

            /* 13시 CUTOFF : MF_D 버전 생성 (화면 비노출, 버전 MF_D+날짜+V000 고정) */
            IF (V_STATES = 'STORAGE') THEN
                V_VERSION := 'MF_D_' || TO_CHAR(SYSDATE,'YYYYMMDD') || '_V000';

                DELETE FROM DM_PLN_MKT_FCST_RESULT_C
                 WHERE DIVISION_ID = V_DEDUCTED_DIVISION_ID AND VERSION_NO = V_VERSION;

                INSERT INTO DM_PLN_MKT_FCST_RESULT_C
                ( DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, MEASURE
                , PLANT_SITE_ID, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4
                , ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10, CELL_PROD_SITE_ID )
                SELECT A.DIVISION_ID, V_VERSION, 'MF_D', TO_CHAR(SYSDATE,'YYYYMMDD'), A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.MEASURE
                     --, A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4
                     , A.PLANT_SITE_ID, A.YYYYMMDD, A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, SYSDATE, A.ATTRIBUTE1, A.ATTRIBUTE2, A.ATTRIBUTE3, A.ATTRIBUTE4
                     , A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10, A.CELL_PROD_SITE_ID
                FROM DM_PLN_MKT_FCST_RESULT A
                INNER JOIN GT_MFSRM_DEDUCTED_ITEM B
                        ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
                WHERE A.MEASURE = 'RTF_SYS_RP'
                  AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON')-14,'YYYYMMDD')   /* 전주 월요일 */
                  AND A.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON')-7,'YYYYMMDD');   /* 당주 월요일 이전 */
                N_ROWCNT := SQL%ROWCOUNT;

                V_LOG_TYPE    := 'APPEND';
                V_LOG_MESSAGE := u'\c9c0\c5f0\be4c\b9c1 VERSION CUTOFF';
                V_DESCRIPTION := u'\c9c0\c5f0\be4c\b9c1 VERSION CUTOFF: ' || TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') || u'  \c0ac\c5c5\bd80: ' || V_DEDUCTED_DIVISION_ID || u' VERSION_NO: ' || V_VERSION;
                D_EVENT_DATE  := SYSDATE;
                N_LOG_COUNT   := N_ROWCNT;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            END IF;

            /* 23시 : 13시 대비 실적 변동 시 MKT FCST 차감 */
            IF (V_STATES = 'DEDUCTED') THEN
                V_LOG_TYPE    := 'APPEND';
                V_LOG_MESSAGE := u'\c9c0\c5f0\be4c\b9c1 \cc28\ac10\b85c\c9c1 \c2dc\c791';
                V_DESCRIPTION := u'\c9c0\c5f0\be4c\b9c1 \cc28\ac10\b85c\c9c1 \c2dc\c791: ' || TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') || u'  \c0ac\c5c5\bd80: ' || V_DEDUCTED_DIVISION_ID || u' \c694\ccad\c0c1\d0dc: ' || V_STATES;
                D_EVENT_DATE  := SYSDATE;
                N_LOG_COUNT   := N_ROWCNT;
                PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

                SELECT COUNT(1) INTO N_CHK_CNT
                  FROM DM_PLN_MKT_FCST_RESULT A
                  INNER JOIN GT_MFSRM_DEDUCTED_ITEM B
                          ON A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND A.PROJECT_CODE = B.PROJECT_CODE AND A.ITEM_ID = B.ITEM_ID
                 WHERE A.MEASURE = 'RTF_SYS_RP'
                   AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON')-14,'YYYYMMDD')
                   AND A.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE,'MON')-7,'YYYYMMDD');

                IF N_CHK_CNT > 0 THEN
                    PR_DM_PLN_MKT_FCST_DELAY_BILLING_AUTO_DEDUCTED(V_DEDUCTED_DIVISION_ID);
                END IF;
            END IF;
        END LOOP;

        V_LOG_TYPE    := 'APPEND';
        V_LOG_MESSAGE := u'\c9c0\c5f0\be4c\b9c1 \c218\d589\c885\b8cc';
        V_DESCRIPTION := u'\c9c0\c5f0\be4c\b9c1 \c218\d589\c885\b8cc: ' || TO_CHAR(SYSDATE,'YYYY-MM-DD HH24:MI:SS') || u'  \c0ac\c5c5\bd80: ' || V_DEDUCTED_DIVISION_ID || u' \c694\ccad\c0c1\d0dc: ' || V_STATES;
        D_EVENT_DATE  := SYSDATE;
        N_LOG_COUNT   := N_ROWCNT;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_DESCRIPTION := '';


        IF SYS_CONTEXT('USERENV','DB_NAME')  = 'OCGSCMP_P01' THEN
            EXECUTE IMMEDIATE 'BEGIN PR_DM_ANL_KPI_SALES_ACCURACY; END;';   /* 20181019 KPI_SALES_ACCURACY */
            EXECUTE IMMEDIATE 'BEGIN PR_DM_ANL_KPI_SUMMARY; END;';   /* 20181128 KHSONG */
        END IF;

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN

            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_BACKTRACE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME
                , V_LOG_TYPE
                , N_LOG_COUNT
                , V_LOG_MESSAGE
                , V_DESCRIPTION
                , D_EVENT_DATE
                , JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID RETURNING VARCHAR2(4000 CHAR))
                , SQLCODE
                , SQLERRM
                , DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;


    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING
-- ##### END PROCEDURE PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING

-- ##### START PROCEDURE PR_DM_PLN_MKT_FCST_TO_NET_DEMAND
CREATE OR REPLACE PROCEDURE           "PR_DM_PLN_MKT_FCST_TO_NET_DEMAND" 
(
    P_DIVISION_ID   IN VARCHAR2
)
/*=====================================================================================================================================================
 * Program ID   : PR_DM_PLN_MKT_FCST_TO_NET_DEMAND
 * Description  : MKT FCST 데이터를 NET_DEAND로 생성하는 프로시져. 생성된 데이터는 SCP 계획수립에 사용된다.
 * Program History
 *=====================================================================================================================================================
 *   Date		In Charge	Description
 *=====================================================================================================================================================
 * 2018.03.21	SongKH		Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2018.04.03	SongKH		전주 CutOff 데이터가 존재하지 않아도 당주 CutOff 데이터가 존재하면 DEMAND_TYPE='NF'로 생성되도록 수정
 * 2018.06.29 	KHSONG 		DUE_DATE를 FCST일자로 사용하는 로직 추가
 * 2018.07.16 	KHSONG 		DIVISION 조건 제거
 * 2018.07.20 	KHSONG 		DM_MST_ITEM_SINGLE_V.ACTIVE_FLAG = 'Y' 조건 추가
 * 2018.07.21 	KHSONG 		ESS RTF PLANT_SITE_ID를 ''으로 일괄적용
 * 2018.07.24 	KHSONG 		Site가 소형 VMI 일 경우 VMI_In_Req, VMI_In_Plan 으로 계산하도록 조건 추가
 * 2018.08.10 	KHSONG 		SCM_MST_SITE.VALID_YN = 'Y' 조건 추가
 * 2018.09.28 	KHSONG 		SCM_MST_SITE_ITEM.VALID_YN = 'Y' 조건 추가
 * 2018.11.07 	KHSONG 		소형 반품예정수량은 제외
 * 2018.11.12 	KHSONG 		DIV:81 인경우 DEMAND_PRIORITY를 일련번호+type 으로 수정
 * 2018.11.30 	KHSONG 		소형인경우 scm_mst_site_item.ATTRIBUTE7 Priority 를 저장 , DEMAND_PRIORITY 컬럼값에 고객 Priority(2자리) 추가
 * 2018.12.10 	KHSONG 		ESS인경우 DM_MST_SHIPMENT_PRIORITY.PRIORITY 값을 저장, DEMAND_PRIORITY 컬럼값에 고객 Priority(2자리) 추가
 * 2018.12.11 	KHSONG 		ESS 출하기준으로 DEMAND SEQ 설정
 * 2019.08.09 	KHSONG 		[CSR ID:4059971] VMI-In Request 로직 변경
 * 2019.08.30 	KHSONG 		[CSR ID:4074696] Demand 우선순위 개선의 건 (1차수정) ESS SORT 기준  [ 일련번호(4자리)+고객Priority(2자리)+demand type(1자리)] → 총 7자리
 * 2019.09.20 	KHSONG 		[CSR ID:4074696] Demand 우선순위 개선의 건 (2차수정) ESS SORT 기준  [ 고정값(1자리) + 고객Priority(2자리)+일련번호(4자리)+demand type(1자리) ] → 총 8자리
 * 2019.09.25 	KHSONG 		[CSR ID:4077124] ESS Shipment Priority 화면 변경요청 (월단위 → 주단위)
 * 2020.09.09   P.C.I		[C20200909-000203] LOG 표준화 적용
 * 2021.09.29	hwi1993		[PJ20209643] W/S 프로세스 - AS_In_Plan, Req 추가
 * 2021.11.04	HWI1993		[PJ20209643] W/S 프로세스 - AS 최종고객향 제거로직 추가
 * 2022.03.29   kdw2819     [C20220224-000448] ESS 사업부 VMI 기능 자동차사업부 확산 전개 요청 (VMI_IN_PLAN 으로 RTF 생성)
  *2022.04.05   hwi1993     GM JV 작업
 * 2023.01.17   chano0612	[E20230112-000310] GSCM 자동차사업부 시스템 상 MKT FCST 입력을 위한 기능변경 건 - 선박BIZ건
 * 2023.02.14	HEESUN		[E20230207-000127] SALES PLAN CUT OFF 시 데이터 중복으로 인한 CUT OFF 가 되지 않았던 케이스 해소
 * 2025.02.05	KANG.H.J	[PJ2025-50017] 소형 매출계획 동기화 개선
 * 2025.04.28	KANG.H.J	[PJ2025-50017] 소형 매출계획 동기화 개선 - NUMERIC(20,10)의 OVERFLOW 발생 - MEASURE 조건절 추가
 * 2025.05.07	KANG.H.J	[PJ2025-50188] 기준수요 (SCM_FCST 기반 NET_DEMAND 생성)
 * 2025.05.14	KANG.H.J	[PJ2025-50188] DM_PLN_NET_DEMAND 생성 기준을 가장 최근의 버젼을 기반으로 생성하도록 정의
 * 2025.05.29	KANG.H.J	[PJ2025-50188] #T_MKT_FCST$ 임시테이블 시작/끝 부분에 DROP 기능 추가
 * 2026.07.06   ZIONEX          [PJ202650304] NextSCM Migration
 * 2026.09.18   AJS             40·82 PLANT_SITE_ID 채움값 '-' 통일, ATTRIBUTE10 빈값 판정 MSSQL 과 동일 범위, #ROW_TABLE 커서 정렬(IDX_ROW_TABLE 키), PLANT_SITE_ID 첫 행 판정
 *===================================================================================================================================================*/
AS
    /* LOG */
    V_PROGRAM_NAME        VARCHAR2(150 CHAR) := 'PR_DM_PLN_MKT_FCST_TO_NET_DEMAND';
    V_LOG_TYPE            VARCHAR2(30 CHAR);
    N_LOG_COUNT           NUMBER := 0;
    V_LOG_MESSAGE         VARCHAR2(1000 CHAR);
    V_DESCRIPTION         VARCHAR2(500 CHAR);
    D_EVENT_DATE          DATE;

    /* 계산용 */
    V_MATCH_ROWS          NUMBER := 0;
    V_MAX_ROWS            NUMBER := 0;
    V_DEMAND_SORT_ROWS    NUMBER := 0;
    V_DEMAND_SORT_MAX     NUMBER := 0;
    V_DEMAND_MIN_YYYYMMDD VARCHAR2(8 CHAR);
    V_PRIORITY_COUNT      NUMBER := 0;
    V_ESS_COUNT           NUMBER := 1001;
    V_CF_COUNT            NUMBER := 1001;
    V_UF_COUNT            NUMBER := 2001;
    V_NF_COUNT            NUMBER := 3001;
    V_INST_COUNT          NUMBER := 0;
    V_DEMAND_TYPE         VARCHAR2(50 CHAR);
    V_DEMAND_TYPE2        VARCHAR2(50 CHAR);
    V_DEMAND_FLAG         VARCHAR2(50 CHAR) := 'CF';
    V_FL_PLANT_SITE_ID    VARCHAR2(120 CHAR);
    V_FL_DEMAND_TYPE      VARCHAR2(50 CHAR);
    V_FL_YYYYMMDD         VARCHAR2(8 CHAR);

    V_CALC_CF             NUMBER(20,10);
    V_CALC_UF             NUMBER(20,10);
    V_CALC_NF             NUMBER(20,10);
    V_INSERT_CALC         NUMBER(20,10);
    V_INSERT_CALC2        NUMBER(20,10);

    V_MAX_PLAN_ID         VARCHAR2(120 CHAR);
    V_YYYYMMDD            VARCHAR2(8 CHAR);

    /* [PJ2025-50188] 기준수요 */
    V_INPUT_VERSION1          VARCHAR2(50 CHAR);
    V_CUTOFF_VERSION_TYPE1    VARCHAR2(10 CHAR);
    V_MEASURE_FCST_TYPE1      VARCHAR2(10 CHAR);
    V_INPUT_VERSION2          VARCHAR2(50 CHAR);
    V_CUTOFF_VERSION_TYPE2    VARCHAR2(10 CHAR);
    V_MEASURE_FCST_TYPE2      VARCHAR2(10 CHAR);


    N_DIVISION_ID         VARCHAR2(120 CHAR);
    N_VERSION_NO          VARCHAR2(50 CHAR);
    N_CUTOFF_YYYYMMDD     VARCHAR2(8 CHAR);
    N_PROJECT_CODE        VARCHAR2(200 CHAR);
    N_SCM_SITE_ID         VARCHAR2(120 CHAR);
    N_ITEM_ID             VARCHAR2(200 CHAR);
    N_DOM_EXP             VARCHAR2(12 CHAR);
    N_FCST_TYPE           VARCHAR2(80 CHAR);
    N_INCOTERMS           VARCHAR2(40 CHAR);
    N_PLANT_SITE_ID       VARCHAR2(120 CHAR);
    N_CELL_PROD_SITE_ID   VARCHAR2(600 CHAR);
    N_YYYYMMDD            VARCHAR2(10 CHAR);
    N_QTY                 NUMBER(20,10);

    /* DEMAND_PRIORITY 산출 보조 */
    V_X4_PAD              VARCHAR2(150 CHAR);
    V_DEMAND_PRIORITY     VARCHAR2(40 CHAR);

    /* #ROW_TABLE 커서 (CURSOR2) */
    CURSOR CUR_ROW IS
        SELECT DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
             , FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY
          -- 2026.09.18 AJS #ROW_TABLE 커서 정렬 추가 - MSSQL CLUSTERED INDEX IDX_ROW_TABLE 키 순서 (START)
          --FROM GT_DM_NET_ROW_TABLE;
          FROM GT_DM_NET_ROW_TABLE
          ORDER BY DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID
                 , DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD;
          -- 2026.09.18 AJS #ROW_TABLE 커서 정렬 추가 (END)
BEGIN
    /* 수정가능 변수값 */
    V_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 1, 'YYYYMMDD');

    /* 시작 LOG (START) */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '@p_division_id : ' || P_DIVISION_ID || ' / ' || '전주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION1, 'NULL')
                     || ' / ' || '당주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION2, 'NULL') || ' / ' || '@MAX_PLAN_ID : ' || NVL(V_MAX_PLAN_ID, 'NULL');
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    /* 전주/당주 CUTOFF VERSION, PLAN_ID Validation */
    /* [PJ2025-50188] 전주 기준 VERSION_NO / CUTOFF_TYPE / MEASURE */
    BEGIN
        SELECT VERSION_NO, VERSION_TYPE
             , CASE WHEN VERSION_TYPE = 'MF_W' THEN 'MKT_FCST' WHEN VERSION_TYPE = 'SF_W' THEN 'SCM_FCST' ELSE '' END
          INTO V_INPUT_VERSION1, V_CUTOFF_VERSION_TYPE1, V_MEASURE_FCST_TYPE1
          FROM (
                SELECT VERSION_NO, VERSION_TYPE
                     , RANK() OVER (ORDER BY YYYYMMDD DESC, VER_CRE_SEQ DESC, VERSION_TYPE DESC) AS RN
                  FROM DM_MST_VERSION
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_TYPE IN ('MF_W', 'SF_W')
                   AND YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 2, 'YYYYMMDD')   /* 전주 월요일부터 */
                   AND YYYYMMDD <= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'SUN') - 7 * 1, 'YYYYMMDD')   /* 전주 일요일까지 */
               )
         WHERE RN = 1 AND ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
    END;

    /* [PJ2025-50188] 당주 기준 VERSION_NO / CUTOFF_TYPE / MEASURE */
    BEGIN
        SELECT VERSION_NO, VERSION_TYPE
             , CASE WHEN VERSION_TYPE = 'MF_W' THEN 'MKT_FCST' WHEN VERSION_TYPE = 'SF_W' THEN 'SCM_FCST' ELSE '' END
          INTO V_INPUT_VERSION2, V_CUTOFF_VERSION_TYPE2, V_MEASURE_FCST_TYPE2
          FROM (
                SELECT VERSION_NO, VERSION_TYPE
                     , RANK() OVER (ORDER BY YYYYMMDD DESC, VER_CRE_SEQ DESC, VERSION_TYPE DESC) AS RN
                  FROM DM_MST_VERSION
                 WHERE DIVISION_ID = P_DIVISION_ID
                   AND VERSION_TYPE IN ('MF_W', 'SF_W')
                   AND YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 1, 'YYYYMMDD')   /* 당주 월요일부터 */
                   AND YYYYMMDD <= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'SUN'), 'YYYYMMDD')   /* 당주 일요일까지 */
               )
         WHERE RN = 1 AND ROWNUM = 1;
    EXCEPTION WHEN NO_DATA_FOUND THEN NULL;
    END;

    SELECT MAX(PLAN_ID) INTO V_MAX_PLAN_ID
      FROM SCP_PLN_RTF_ALLOCATION_V
     WHERE DIVISION_ID = P_DIVISION_ID;

    /* 당주 CUTOFF VERSION 값이 없으면 수행하지 않음 (GOTO ERR_RTN) */
    IF V_INPUT_VERSION2 IS NULL THEN
        V_LOG_TYPE    := 'INVALID';
        V_DESCRIPTION := '@p_division_id : ' || P_DIVISION_ID || ' / ' || '전주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION1, 'NULL')
                         || ' / ' || '당주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION2, 'NULL') || ' / ' || '@MAX_PLAN_ID : ' || NVL(V_MAX_PLAN_ID, 'NULL');
        ROLLBACK;
        V_LOG_MESSAGE := '########## END of procedure ##########';
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        RETURN;
    END IF;


    BEGIN

        DELETE FROM GT_DM_NET_RTF_ALLOC;
        DELETE FROM GT_DM_NET_MKT_FCST;
        DELETE FROM GT_DM_NET_ROW_TABLE;
        DELETE FROM GT_DM_NET_TEMP1;
        DELETE FROM GT_DM_NET_TEMP2;
        DELETE FROM GT_DM_NET_TEMP3;
        DELETE FROM GT_DM_NET_TEMP4;
        DELETE FROM GT_DM_NET_TEMP5;

        /* #TMP_SCP_PLN_RTF_ALLOCATION */
        INSERT INTO GT_DM_NET_RTF_ALLOC
            (DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, ITEM_ID, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DOM_EXP, FCST_TYPE, DUE_DATE, ALLOCATION_QTY, PLAN_ID)
        SELECT DIVISION_ID, PROJECT_CODE, SALES_SITE_ID, ITEM_ID, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DOM_EXP, FCST_TYPE, DUE_DATE, ALLOCATION_QTY, PLAN_ID
          FROM SCP_PLN_RTF_ALLOCATION_V A
         WHERE A.DIVISION_ID = P_DIVISION_ID
           AND A.PLAN_ID     = V_MAX_PLAN_ID;

        /* 각 사업부별 공통정보 #T_MKT_FCST$ 적재 */
        IF (P_DIVISION_ID = '40') THEN
            INSERT INTO GT_DM_NET_MKT_FCST
                (DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, MEASURE, YYYYMMDD, QTY, ATTRIBUTE10)
            SELECT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD
                 , END_CUSTOMER  AS PROJECT_CODE
                 , SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, MEASURE, YYYYMMDD, QTY, ATTRIBUTE10
              FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C
             WHERE DIVISION_ID = P_DIVISION_ID
               AND VERSION_NO  IN (V_INPUT_VERSION1, V_INPUT_VERSION2)
               AND QTY         > 0
               AND YYYYMMDD    >= V_YYYYMMDD
               AND MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'AS_In_Req');
        ELSE
            INSERT INTO GT_DM_NET_MKT_FCST
                (DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, MEASURE, YYYYMMDD, QTY, ATTRIBUTE10)
            SELECT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID
                 , '-'  AS CELL_PROD_SITE_ID
                 , MEASURE, YYYYMMDD, QTY, ATTRIBUTE10
              FROM DM_PLN_MKT_FCST_C
             WHERE DIVISION_ID = P_DIVISION_ID
               AND VERSION_NO  IN (V_INPUT_VERSION1, V_INPUT_VERSION2)
               AND QTY         > 0
               AND YYYYMMDD    >= V_YYYYMMDD
               AND MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'AS_In_Req');
        END IF;

        /* 전주 마지막 WEEKLY CUTOFF -> #TEMP1 */
        INSERT INTO GT_DM_NET_TEMP1
            (DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMM, BATCH_RESULT, QTY, RTF, MKT_FCST, CF, UF, NF)
        WITH ALL_DATA AS (
            SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                 -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN ' ' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
                 , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN '/' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
                 -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (END)
                 , A.CELL_PROD_SITE_ID
                 , A.MEASURE
                 , SUBSTR(A.YYYYMMDD, 1, 6)   AS YYYYMM
                 , 'ING'                      AS BATCH_RESULT
                 , SUM(A.QTY)                 AS QTY
                 , 0 AS RTF, 0 AS MKT_FCST, 0 AS CF, 0 AS UF, 0 AS NF
              FROM GT_DM_NET_MKT_FCST       A
                 , DM_MST_ITEM_SINGLE_V     ITEM
                 , SCM_MST_SITE             ST
                 , SCM_MST_SITE_ITEM        STM
             WHERE 1 = 1
               AND A.DIVISION_ID  = ITEM.DIVISION_ID
               AND A.DIVISION_ID  = STM.DIVISION_ID
               AND A.PROJECT_CODE = STM.PROJECT_CODE
               AND A.SCM_SITE_ID  = STM.SCM_SITE_ID
               AND A.ITEM_ID      = STM.ITEM_ID
               AND STM.VALID_YN   = 'Y'
               AND A.ITEM_ID      = ITEM.ITEM_ID
               AND ITEM.ACTIVE_FLAG = 'Y'
               AND ST.VALID_YN    = 'Y'
               AND A.DIVISION_ID  = ST.DIVISION_ID
               AND A.SCM_SITE_ID  = ST.SCM_SITE_ID
               AND A.MEASURE      = CASE WHEN A.DIVISION_ID IN ('40', '82') AND ST.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                         WHEN ST.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                         ELSE V_MEASURE_FCST_TYPE1 END
               AND A.DIVISION_ID  = P_DIVISION_ID
               AND A.VERSION_NO   = V_INPUT_VERSION1
               AND A.QTY          > 0
               AND A.YYYYMMDD     >= V_YYYYMMDD
               -- 2026.09.18 AJS ATTRIBUTE10 빈값 판정 - MSSQL ISNULL(A.ATTRIBUTE10,'') = '' 와 같은 범위 (START)
--               AND A.ATTRIBUTE10  IS NULL
               AND (A.ATTRIBUTE10 IS NULL OR TRIM(A.ATTRIBUTE10) IS NULL OR A.ATTRIBUTE10 = '-')
               -- 2026.09.18 AJS ATTRIBUTE10 빈값 판정 (END)
               AND A.MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'AS_In_Req')
             GROUP BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP
                    , A.FCST_TYPE, A.INCOTERMS
                    -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (START)
--                    , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN ' ' ELSE A.PLANT_SITE_ID END
                    , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN '/' ELSE A.PLANT_SITE_ID END
                    -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (END)
                    , A.CELL_PROD_SITE_ID
                    , A.MEASURE, SUBSTR(A.YYYYMMDD, 1, 6)
            UNION ALL
            SELECT A.DIVISION_ID
                 , V_INPUT_VERSION1                        AS VERSION_NO
                 , V_CUTOFF_VERSION_TYPE1                  AS CUTOFF_TYPE
                 , SUBSTR(V_INPUT_VERSION1, 6, 8)          AS CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE, A.SALES_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
                 -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (START)
--                 , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN ' ' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
                 , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN '/' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
                 -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (END)
                 , A.CELL_PROD_SITE_ID
                 , CASE WHEN A.DIVISION_ID IN ('40', '82') AND ST.VMI_YN = 'Y' THEN 'VMI_IN_PLAN'
                        WHEN ST.OPERATION_GROUP = 'W' THEN 'AS_IN_PLAN'
                        ELSE 'RTF' END                     AS MEASURE
                 , SUBSTR(A.DUE_DATE, 1, 6)                AS YYYYMM
                 , 'ING'                                   AS BATCH_RESULT
                 , SUM(A.ALLOCATION_QTY)                   AS QTY
                 , 0 AS RTF, 0 AS MKT_FCST, 0 AS CF, 0 AS UF, 0 AS NF
              FROM GT_DM_NET_RTF_ALLOC      A
                 , DM_MST_ITEM_SINGLE_V     ITEM
                 , SCM_MST_SITE             ST
                 , SCM_MST_SITE_ITEM        STM
             WHERE 1 = 1
               AND A.DIVISION_ID   = STM.DIVISION_ID
               AND A.PROJECT_CODE  = STM.PROJECT_CODE
               AND A.SALES_SITE_ID = STM.SCM_SITE_ID
               AND A.ITEM_ID       = STM.ITEM_ID
               AND STM.VALID_YN    = 'Y'
               AND A.DIVISION_ID   = ITEM.DIVISION_ID
               AND A.ITEM_ID       = ITEM.ITEM_ID
               AND ITEM.ACTIVE_FLAG = 'Y'
               AND ST.VALID_YN     = 'Y'
               AND A.PLAN_ID       = V_MAX_PLAN_ID
               AND A.DIVISION_ID   = ST.DIVISION_ID
               AND A.SALES_SITE_ID = ST.SCM_SITE_ID
               AND A.ALLOCATION_QTY > 0
               AND A.DUE_DATE      >= V_YYYYMMDD
             GROUP BY A.DIVISION_ID, A.SALES_SITE_ID, A.PROJECT_CODE, A.ITEM_ID, A.INCOTERMS
                    -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (START)
--                    , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN ' ' ELSE A.PLANT_SITE_ID END
                    , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN '/' ELSE A.PLANT_SITE_ID END
                    -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (END)
                    , A.CELL_PROD_SITE_ID
                    , A.DOM_EXP, A.FCST_TYPE, SUBSTR(A.DUE_DATE, 1, 6), ST.VMI_YN, ST.OPERATION_GROUP
        )
        SELECT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMM, BATCH_RESULT
             , SUM(CASE WHEN MEASURE IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END)
             , SUM(CASE WHEN MEASURE NOT IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END)   AS RTF
             , SUM(CASE WHEN MEASURE IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END)       AS MKT_FCST
             , SUM(CASE WHEN MEASURE NOT IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END)   AS CF
             , SUM(CASE WHEN MEASURE IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END)
               - SUM(CASE WHEN MEASURE NOT IN (V_MEASURE_FCST_TYPE1, 'VMI_In_Req', 'AS_In_Req') THEN QTY ELSE 0 END) AS UF
             , 0   AS NF
          FROM ALL_DATA
         WHERE 1 = 1
           AND BATCH_RESULT = 'ING'
           AND FCST_TYPE   <> 'RMA'
         GROUP BY DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP
                , FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMM, BATCH_RESULT;

        /* 당주 WEEKLY CUTOFF -> #TEMP2 */
        INSERT INTO GT_DM_NET_TEMP2
            (DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY)
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_TYPE, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS
             -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (START)
--             , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN ' ' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
             , CASE WHEN A.DIVISION_ID IN ('82', '40') THEN '/' ELSE A.PLANT_SITE_ID END   AS PLANT_SITE_ID
             -- 2026.09.18 AJS 40·82 PLANT_SITE_ID 이관 채움값 '-' 로 통일 (END)
             , A.CELL_PROD_SITE_ID, A.YYYYMMDD, A.QTY
          FROM GT_DM_NET_MKT_FCST     A
             , DM_MST_ITEM_SINGLE_V   ITEM
             , SCM_MST_SITE           ST
             , SCM_MST_SITE_ITEM      STM
         WHERE 1 = 1
           AND A.DIVISION_ID  = STM.DIVISION_ID
           AND A.PROJECT_CODE = STM.PROJECT_CODE
           AND A.SCM_SITE_ID  = STM.SCM_SITE_ID
           AND A.ITEM_ID      = STM.ITEM_ID
           AND STM.VALID_YN   = 'Y'
           AND A.DIVISION_ID  = ITEM.DIVISION_ID
           AND A.ITEM_ID      = ITEM.ITEM_ID
           AND ITEM.ACTIVE_FLAG = 'Y'
           AND ST.VALID_YN    = 'Y'
           AND A.DIVISION_ID  = ST.DIVISION_ID
           AND A.SCM_SITE_ID  = ST.SCM_SITE_ID
           AND A.MEASURE      = CASE WHEN A.DIVISION_ID IN ('40', '82') AND ST.VMI_YN = 'Y' THEN 'VMI_In_Req'
                                     WHEN ST.OPERATION_GROUP = 'W' THEN 'AS_In_Req'
                                     ELSE V_MEASURE_FCST_TYPE2 END
           AND A.DIVISION_ID  = P_DIVISION_ID
           AND A.VERSION_NO   = V_INPUT_VERSION2
           AND A.QTY          > 0
           AND A.YYYYMMDD     >= V_YYYYMMDD
           AND A.MEASURE IN ('MKT_FCST', 'SCM_FCST', 'VMI_In_Req', 'AS_In_Req')
           -- 2026.09.18 AJS ATTRIBUTE10 빈값 판정 - MSSQL ISNULL(A.ATTRIBUTE10,'') = '' 와 같은 범위 (START)
--           AND A.ATTRIBUTE10  IS NULL;
           AND (A.ATTRIBUTE10 IS NULL OR TRIM(A.ATTRIBUTE10) IS NULL OR A.ATTRIBUTE10 = '-');
           -- 2026.09.18 AJS ATTRIBUTE10 빈값 판정 (END)

        /* AS 최종 고객향 제거 */
        DELETE FROM GT_DM_NET_TEMP1 A
         WHERE EXISTS (SELECT 1 FROM SCM_MST_SITE B WHERE A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND NVL(B.OPERATION_GROUP, 'X') <> 'W')
           AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL C WHERE A.FCST_TYPE = C.SEGMENT1 AND C.LOOKUP_TYPE = 'SALES_TYPE_CODE' AND C.ATTRIBUTE2 = 'Y');
        DELETE FROM GT_DM_NET_TEMP2 A
         WHERE EXISTS (SELECT 1 FROM SCM_MST_SITE B WHERE A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND NVL(B.OPERATION_GROUP, 'X') <> 'W')
           AND EXISTS (SELECT 1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL C WHERE A.FCST_TYPE = C.SEGMENT1 AND C.LOOKUP_TYPE = 'SALES_TYPE_CODE' AND C.ATTRIBUTE2 = 'Y');

        /* 선박biz사업부 NET DEMAND 제거 [E20230112-000310] */
        DELETE FROM GT_DM_NET_TEMP1 A
         WHERE EXISTS (SELECT 1 FROM SCM_MST_SITE B WHERE A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND NVL(B.OPERATION_GROUP, 'X') <> 'W')
           AND A.DIVISION_ID IN (SELECT SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y')
           AND A.SCM_SITE_ID IN (SELECT SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y');
        DELETE FROM GT_DM_NET_TEMP2 A
         WHERE EXISTS (SELECT 1 FROM SCM_MST_SITE B WHERE A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND NVL(B.OPERATION_GROUP, 'X') <> 'W')
           AND A.DIVISION_ID IN (SELECT SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y')
           AND A.SCM_SITE_ID IN (SELECT SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y');

        /* [E20230207-000127] 82 ETC 중복 해소 */
        DELETE FROM GT_DM_NET_TEMP1 A WHERE A.DIVISION_ID = '82' AND A.FCST_TYPE = 'ETC';
        DELETE FROM GT_DM_NET_TEMP2 A WHERE A.DIVISION_ID = '82' AND A.FCST_TYPE = 'ETC';

        /* CURSOR_1 : #TEMP1 */
        FOR C1 IN (
            SELECT DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMM, BATCH_RESULT
              FROM GT_DM_NET_TEMP1
             WHERE 1 = 1 AND BATCH_RESULT = 'ING'
             ORDER BY DIVISION_ID, VERSION_NO, CUTOFF_TYPE, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMM, BATCH_RESULT
        ) LOOP
            /* 계산용 변수값 저장 */
            SELECT NVL(SUM(CF), 0), NVL(SUM(UF), 0), NVL(SUM(NF), 0)
              INTO V_CALC_CF, V_CALC_UF, V_CALC_NF
              FROM GT_DM_NET_TEMP1
             WHERE DIVISION_ID = C1.DIVISION_ID AND VERSION_NO = C1.VERSION_NO AND CUTOFF_TYPE = C1.CUTOFF_TYPE AND CUTOFF_YYYYMMDD = C1.CUTOFF_YYYYMMDD
               AND PROJECT_CODE = C1.PROJECT_CODE AND SCM_SITE_ID = C1.SCM_SITE_ID AND ITEM_ID = C1.ITEM_ID AND DOM_EXP = C1.DOM_EXP
               AND FCST_TYPE = C1.FCST_TYPE AND INCOTERMS = C1.INCOTERMS AND PLANT_SITE_ID = C1.PLANT_SITE_ID AND CELL_PROD_SITE_ID = C1.CELL_PROD_SITE_ID
               AND YYYYMM = C1.YYYYMM;

            /* 당주의 해당월 mkt_fcst 수량파악 (#ROW_TABLE) */
            DELETE FROM GT_DM_NET_ROW_TABLE;
            INSERT INTO GT_DM_NET_ROW_TABLE
                (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, YYYYMMDD, QTY, ROW_COUNT)
            SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID
                 -- 2026.09.18 AJS ROW_COUNT 정렬키 - IDX_ROW_TABLE 키 순서 (START)
--                 , A.CELL_PROD_SITE_ID, A.YYYYMMDD, A.QTY, ROW_NUMBER() OVER (ORDER BY A.DIVISION_ID) AS ROW_COUNT
                 , A.CELL_PROD_SITE_ID, A.YYYYMMDD, A.QTY, ROW_NUMBER() OVER (ORDER BY A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID
                                                         , A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.YYYYMMDD) AS ROW_COUNT
                 -- 2026.09.18 AJS ROW_COUNT 정렬키 (END)
              FROM GT_DM_NET_TEMP2 A
             WHERE 1 = 1
               AND A.DIVISION_ID  = C1.DIVISION_ID
               AND A.PROJECT_CODE = C1.PROJECT_CODE
               AND A.SCM_SITE_ID  = C1.SCM_SITE_ID
               AND A.ITEM_ID      = C1.ITEM_ID
               AND A.DOM_EXP      = C1.DOM_EXP
               AND A.FCST_TYPE    = C1.FCST_TYPE
               AND A.INCOTERMS    = C1.INCOTERMS
               AND A.PLANT_SITE_ID = C1.PLANT_SITE_ID
               AND A.CELL_PROD_SITE_ID = C1.CELL_PROD_SITE_ID
               AND SUBSTR(A.YYYYMMDD, 1, 6) = C1.YYYYMM;


            DELETE FROM GT_DM_NET_TEMP2 T
             WHERE 1 = 1
               AND T.DIVISION_ID  = C1.DIVISION_ID
               AND T.PROJECT_CODE = C1.PROJECT_CODE
               AND T.SCM_SITE_ID  = C1.SCM_SITE_ID
               AND T.ITEM_ID      = C1.ITEM_ID
               AND T.DOM_EXP      = C1.DOM_EXP
               AND T.FCST_TYPE    = C1.FCST_TYPE
               AND T.INCOTERMS    = C1.INCOTERMS
               AND T.PLANT_SITE_ID = C1.PLANT_SITE_ID
               AND T.CELL_PROD_SITE_ID = C1.CELL_PROD_SITE_ID
               AND SUBSTR(T.YYYYMMDD, 1, 6) = C1.YYYYMM;

            /* CURSOR_2 : #ROW_TABLE */
            V_MATCH_ROWS := 1;
            SELECT NVL(MAX(ROW_COUNT), 0) INTO V_MAX_ROWS FROM GT_DM_NET_ROW_TABLE;

            OPEN CUR_ROW;
            LOOP
                FETCH CUR_ROW INTO N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, N_YYYYMMDD, N_QTY;
                EXIT WHEN CUR_ROW%NOTFOUND;
                EXIT WHEN NOT (V_MATCH_ROWS <= V_MAX_ROWS AND SUBSTR(N_YYYYMMDD, 1, 6) = C1.YYYYMM);

                V_DEMAND_TYPE  := '';
                V_DEMAND_TYPE2 := NULL;

                IF V_CALC_CF > 0 THEN
                    V_DEMAND_FLAG := 'CF';
                ELSIF V_CALC_UF > 0 THEN
                    V_DEMAND_FLAG := 'UF';
                ELSIF V_CALC_NF > 0 THEN
                    V_DEMAND_FLAG := 'NF';
                ELSIF N_QTY > 0 THEN
                    V_DEMAND_FLAG := 'NF';
                    V_CALC_NF     := N_QTY;
                END IF;

                /* CF */
                IF V_DEMAND_FLAG = 'CF' AND V_CALC_CF > 0 THEN
                    IF V_CALC_CF < N_QTY THEN
                        V_INSERT_CALC  := V_CALC_CF;
                        V_DEMAND_TYPE  := 'CF';
                        V_INSERT_CALC2 := N_QTY - V_CALC_CF;
                        IF V_CALC_UF > 0 AND V_CALC_UF >= V_INSERT_CALC2 THEN
                            V_DEMAND_TYPE2 := 'UF';
                        ELSE
                            V_DEMAND_TYPE2 := 'NF';
                        END IF;
                        N_QTY := 0;
                    ELSE
                        V_DEMAND_TYPE := 'CF';
                        V_INSERT_CALC := N_QTY;
                        N_QTY := 0;
                    END IF;

                    IF V_DEMAND_TYPE = 'CF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        V_DEMAND_TYPE := '';
                        V_CALC_CF := V_CALC_CF - V_INSERT_CALC;
                    END IF;

                    IF V_DEMAND_TYPE2 = 'UF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE2, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC2, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        V_CALC_UF := V_CALC_UF - V_INSERT_CALC2;
                    END IF;

                    IF V_DEMAND_TYPE2 = 'NF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE2, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC2, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        V_CALC_NF := V_CALC_NF - V_INSERT_CALC2;
                    END IF;

                    IF V_CALC_CF = 0 THEN
                        V_DEMAND_FLAG := '';
                    END IF;
                    IF V_CALC_CF < 0 THEN
                        V_CALC_CF := 0;
                    END IF;
                END IF;

                /* UF */
                IF V_DEMAND_FLAG = 'UF' AND V_DEMAND_TYPE2 IS NULL AND V_CALC_UF > 0 THEN
                    IF V_CALC_UF < N_QTY THEN
                        V_DEMAND_TYPE2 := 'NF';
                        V_INSERT_CALC  := V_CALC_UF;
                        V_DEMAND_TYPE  := 'UF';
                        V_INSERT_CALC2 := N_QTY - V_CALC_UF;
                        V_CALC_NF := V_CALC_NF - V_INSERT_CALC2;
                        V_CALC_UF := 0;
                        V_DEMAND_FLAG := 'NF';
                    ELSE
                        V_DEMAND_TYPE := 'UF';
                        V_INSERT_CALC := N_QTY;
                    END IF;

                    IF V_DEMAND_TYPE = 'UF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        V_DEMAND_TYPE := '';
                    END IF;

                    IF V_DEMAND_TYPE2 = 'NF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE2, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC2, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                    END IF;

                    IF V_CALC_UF = 0 THEN
                        V_DEMAND_FLAG := '';
                    END IF;
                    V_CALC_UF := V_CALC_UF - N_QTY;
                    IF V_CALC_UF < 0 THEN
                        V_CALC_UF := 0;
                    END IF;
                END IF;

                /* NF */
                IF V_DEMAND_FLAG = 'NF' AND V_DEMAND_TYPE2 IS NULL AND V_CALC_NF > 0 THEN
                    V_DEMAND_TYPE := 'NF';
                    V_INSERT_CALC := N_QTY;
                    IF V_CALC_NF < N_QTY THEN
                        V_DEMAND_TYPE2 := 'NF';
                        V_INSERT_CALC  := V_CALC_UF;
                        V_DEMAND_TYPE  := 'UF';
                        V_INSERT_CALC2 := N_QTY;
                        V_CALC_NF := V_CALC_NF - V_INSERT_CALC2;
                        V_CALC_NF := 0;
                    END IF;

                    IF V_DEMAND_TYPE = 'NF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                        V_DEMAND_TYPE := '';
                    END IF;

                    IF V_DEMAND_TYPE2 = 'NF' THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, V_DEMAND_TYPE2, N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_INSERT_CALC2, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                    END IF;
                END IF;

                V_MATCH_ROWS := V_MATCH_ROWS + 1;

                /* CF 잔량이 있으나 당주 데이터가 끝난 경우 잔여 NF 생성 */
                IF V_MAX_ROWS < V_MATCH_ROWS AND V_CALC_CF > 0 THEN
                    IF N_QTY > 0 THEN
                        V_PRIORITY_COUNT := V_PRIORITY_COUNT + 1;
                        INSERT INTO GT_DM_NET_TEMP3
                            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
                        VALUES (N_DIVISION_ID, N_VERSION_NO, N_CUTOFF_YYYYMMDD, N_PROJECT_CODE, N_SCM_SITE_ID, N_ITEM_ID, N_DOM_EXP, N_FCST_TYPE, N_INCOTERMS, N_PLANT_SITE_ID, N_CELL_PROD_SITE_ID, 'NF', N_YYYYMMDD, TO_CHAR(V_PRIORITY_COUNT), V_CALC_CF, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
                    END IF;
                    V_CALC_CF := 0;
                END IF;
            END LOOP;
            CLOSE CUR_ROW;
        END LOOP;
        /* CURSOR_1 CLOSE */

        /* 전주 CutOff 없어도 당주 CutOff 있으면 DEMAND_TYPE='NF' 생성 */
        INSERT INTO GT_DM_NET_TEMP3
            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
        SELECT DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID
             , 'NF', YYYYMMDD, QTY, 'dm_batch', SYSDATE, 'dm_batch', SYSDATE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL
          FROM GT_DM_NET_TEMP2;

        /* customer_LT 적용 -> #TEMP4 */
        INSERT INTO GT_DM_NET_TEMP4
            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
        SELECT A.DIVISION_ID, A.VERSION_NO, A.CUTOFF_YYYYMMDD, A.PROJECT_CODE, A.SCM_SITE_ID, A.ITEM_ID, A.DOM_EXP, A.FCST_TYPE, A.INCOTERMS, A.PLANT_SITE_ID, A.CELL_PROD_SITE_ID, A.DEMAND_TYPE
             , CASE
                   WHEN A.DIVISION_ID IN (SELECT DIVISION_ID FROM SCM_MST_DIVISION WHERE ATTRIBUTE3 IN ('40', '81')) THEN
                        TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD')
                                - NVL((SELECT MAX(LT_TOTAL) FROM SCP_MST_BOD_V BOD WHERE BOD.DIVISION_ID = A.DIVISION_ID AND BOD.FROM_SITE = A.PLANT_SITE_ID AND BOD.TO_SITE = A.SCM_SITE_ID AND BOD.INCOTERMS = A.INCOTERMS), 0)
                                , 'YYYYMMDD')
                   WHEN A.DIVISION_ID = '82' THEN
                        TO_CHAR(TO_DATE(A.YYYYMMDD, 'YYYYMMDD') - NVL(BOD_V.LT_TOTAL, 0), 'YYYYMMDD')
                   ELSE A.YYYYMMDD
               END   AS YYYYMMDD
             , A.DEMAND_PRIORITY
             , A.QTY, A.CREATED_BY, A.CREATION_DATE, A.LAST_UPDATED_BY, A.LAST_UPDATE_DATE
             , A.YYYYMMDD   AS ATTRIBUTE1
             , CASE
                   WHEN A.DIVISION_ID IN (SELECT DIVISION_ID FROM SCM_MST_DIVISION WHERE ATTRIBUTE3 IN ('40', '81')) THEN
                        TO_CHAR(NVL((SELECT MAX(LT_TOTAL) FROM SCP_MST_BOD_V BOD WHERE BOD.DIVISION_ID = A.DIVISION_ID AND BOD.FROM_SITE = A.PLANT_SITE_ID AND BOD.TO_SITE = A.SCM_SITE_ID AND BOD.INCOTERMS = A.INCOTERMS), 0))
                   WHEN A.DIVISION_ID = '82' THEN
                        TO_CHAR(NVL(BOD_V.LT_TOTAL, 0))
               END   AS ATTRIBUTE2
             , CASE WHEN A.DEMAND_TYPE = 'CF' THEN '1' WHEN A.DEMAND_TYPE = 'UF' THEN '2' WHEN A.DEMAND_TYPE = 'NF' THEN '3' ELSE '0' END   AS ATTRIBUTE3
             , NVL(
                   CASE
                       WHEN A.DIVISION_ID = '40' THEN
                            (SELECT ATTRIBUTE7 FROM SCM_MST_SITE_ITEM M WHERE 1 = 1 AND M.DIVISION_ID = A.DIVISION_ID AND M.PROJECT_CODE = A.PROJECT_CODE AND M.SCM_SITE_ID = A.SCM_SITE_ID AND M.ITEM_ID = A.ITEM_ID AND ROWNUM = 1)
                       WHEN A.DIVISION_ID = '82' THEN
                            TO_CHAR((SELECT PRIORITY FROM DM_MST_SHIPMENT_PRIORITY P
                              WHERE 1 = 1 AND P.DIVISION_ID = A.DIVISION_ID AND P.PROJECT_CODE = A.PROJECT_CODE AND P.ITEM_ID = A.ITEM_ID AND P.SCM_SITE_ID = A.SCM_SITE_ID
                                AND P.YYYYMMDD = TO_CHAR(FN_NEXT_DAY(TO_DATE(A.YYYYMMDD, 'YYYYMMDD') - NVL(BOD_V.LT_TOTAL, 0), 'MON') - 7, 'YYYYMMDD')
                                AND ROWNUM = 1))
                       ELSE '' END
                 , '99')   AS ATTRIBUTE4
             , A.ATTRIBUTE5, A.ATTRIBUTE6, A.ATTRIBUTE7, A.ATTRIBUTE8, A.ATTRIBUTE9, A.ATTRIBUTE10

          FROM GT_DM_NET_TEMP3 A
             , (
                    SELECT DIVISION_ID, TO_SITE, INCOTERMS, PRIORITY, LT_TOTAL
                         , ROW_NUMBER() OVER (PARTITION BY TO_SITE, INCOTERMS ORDER BY PRIORITY ASC, LT_TOTAL ASC) AS SEQ
                      FROM SCP_MST_BOD_V B
               ) BOD_V
         WHERE A.DIVISION_ID = BOD_V.DIVISION_ID(+)
           AND A.SCM_SITE_ID = BOD_V.TO_SITE(+)
           AND A.INCOTERMS   = BOD_V.INCOTERMS(+)
           AND BOD_V.SEQ(+)  = 1;

        /* CURSOR_3 : #TEMP4 -> #TEMP5 */
        SELECT COUNT(*)        INTO V_DEMAND_SORT_MAX     FROM GT_DM_NET_TEMP4;
        SELECT MIN(ATTRIBUTE1) INTO V_DEMAND_MIN_YYYYMMDD FROM GT_DM_NET_TEMP4;
        -- 2026.09.18 AJS PLANT_SITE_ID 첫 행 판정 - 초기값 NULL 로 첫 행 진입 보장 (START)
--        V_FL_PLANT_SITE_ID := ' ';
        -- 2026.09.18 AJS PLANT_SITE_ID 첫 행 판정 (END)

        FOR C3 IN (
            SELECT DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10
              FROM GT_DM_NET_TEMP4
             ORDER BY CASE WHEN P_DIVISION_ID = '82' THEN ATTRIBUTE4 END
                    , CASE WHEN P_DIVISION_ID = '82' THEN YYYYMMDD END
                    , CASE WHEN P_DIVISION_ID <> '82' THEN PLANT_SITE_ID END
                    , CASE WHEN P_DIVISION_ID <> '82' THEN CELL_PROD_SITE_ID END
                    , CASE WHEN P_DIVISION_ID <> '82' THEN ATTRIBUTE3 END
                    , CASE WHEN P_DIVISION_ID <> '82' THEN YYYYMMDD END
        ) LOOP
            IF C3.DIVISION_ID = '82' THEN
                IF V_FL_YYYYMMDD IS NULL THEN
                    V_FL_YYYYMMDD := C3.YYYYMMDD;
                END IF;
                IF V_FL_YYYYMMDD <> NVL(C3.YYYYMMDD, ' ') THEN
                    V_ESS_COUNT := V_ESS_COUNT + 1;
                    V_FL_YYYYMMDD := C3.YYYYMMDD;
                END IF;
                V_INST_COUNT := V_ESS_COUNT;
            ELSE
                -- 2026.09.18 AJS PLANT_SITE_ID 첫 행 판정 (START)
--                IF V_FL_PLANT_SITE_ID <> NVL(C3.PLANT_SITE_ID, ' ') THEN
                IF V_FL_PLANT_SITE_ID IS NULL OR V_FL_PLANT_SITE_ID <> NVL(C3.PLANT_SITE_ID, ' ') THEN
                -- 2026.09.18 AJS PLANT_SITE_ID 첫 행 판정 (END)
                    V_FL_PLANT_SITE_ID := C3.PLANT_SITE_ID;
                    V_FL_DEMAND_TYPE   := C3.DEMAND_TYPE;
                    V_FL_YYYYMMDD      := C3.YYYYMMDD;
                    V_CF_COUNT := 1001;
                    V_UF_COUNT := 2001;
                    V_NF_COUNT := 3001;
                END IF;
                IF V_FL_DEMAND_TYPE = NVL(C3.DEMAND_TYPE, ' ') THEN
                    IF V_FL_DEMAND_TYPE = 'CF' THEN
                        IF V_FL_YYYYMMDD <> NVL(C3.YYYYMMDD, ' ') THEN
                            V_CF_COUNT := V_CF_COUNT + 1;
                            V_FL_YYYYMMDD := C3.YYYYMMDD;
                        END IF;
                        V_INST_COUNT := V_CF_COUNT;
                    END IF;
                    IF V_FL_DEMAND_TYPE = 'UF' THEN
                        IF V_FL_YYYYMMDD <> NVL(C3.YYYYMMDD, ' ') THEN
                            V_UF_COUNT := V_UF_COUNT + 1;
                            V_FL_YYYYMMDD := C3.YYYYMMDD;
                        END IF;
                        V_INST_COUNT := V_UF_COUNT;
                    END IF;
                    IF V_FL_DEMAND_TYPE = 'NF' THEN
                        IF V_FL_YYYYMMDD <> NVL(C3.YYYYMMDD, ' ') THEN
                            V_NF_COUNT := V_NF_COUNT + 1;
                            V_FL_YYYYMMDD := C3.YYYYMMDD;
                        END IF;
                        V_INST_COUNT := V_NF_COUNT;
                    END IF;
                ELSE
                    V_FL_DEMAND_TYPE := C3.DEMAND_TYPE;
                    V_FL_YYYYMMDD    := C3.YYYYMMDD;
                    IF V_FL_DEMAND_TYPE = 'CF' THEN
                        V_CF_COUNT := 1001;
                        V_INST_COUNT := V_CF_COUNT;
                    END IF;
                    IF V_FL_DEMAND_TYPE = 'UF' THEN
                        V_UF_COUNT := 2001;
                        V_INST_COUNT := V_UF_COUNT;
                    END IF;
                    IF V_FL_DEMAND_TYPE = 'NF' THEN
                        V_NF_COUNT := 3001;
                        V_INST_COUNT := V_NF_COUNT;
                    END IF;
                END IF;
            END IF;

            /* DEMAND_PRIORITY 산출 */
            V_X4_PAD := CASE WHEN 2 - LENGTH(C3.ATTRIBUTE4) < 0 THEN NULL
                             ELSE SUBSTR('00', 1, 2 - LENGTH(C3.ATTRIBUTE4)) || C3.ATTRIBUTE4 END;
            V_DEMAND_PRIORITY := CASE
                WHEN C3.DIVISION_ID LIKE '81%' THEN TO_CHAR(TO_DATE(C3.ATTRIBUTE1, 'YYYYMMDD') - TO_DATE(V_DEMAND_MIN_YYYYMMDD, 'YYYYMMDD') + 1) || C3.ATTRIBUTE3
                WHEN C3.DIVISION_ID = '40' THEN V_X4_PAD || TO_CHAR(V_INST_COUNT)
                WHEN C3.DIVISION_ID = '82' THEN '1' || V_X4_PAD || TO_CHAR(V_INST_COUNT) || C3.ATTRIBUTE3
                ELSE TO_CHAR(V_INST_COUNT)
            END;

            INSERT INTO GT_DM_NET_TEMP5
                (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
            VALUES (C3.DIVISION_ID, C3.VERSION_NO, C3.CUTOFF_YYYYMMDD, C3.PROJECT_CODE, C3.SCM_SITE_ID, C3.ITEM_ID, C3.DOM_EXP, C3.FCST_TYPE, C3.INCOTERMS, C3.PLANT_SITE_ID, C3.CELL_PROD_SITE_ID, C3.DEMAND_TYPE, C3.YYYYMMDD
                  , V_DEMAND_PRIORITY
                  , C3.QTY, C3.CREATED_BY, C3.CREATION_DATE, C3.LAST_UPDATED_BY, C3.LAST_UPDATE_DATE, C3.ATTRIBUTE1, C3.ATTRIBUTE2, C3.ATTRIBUTE3
                  , V_X4_PAD
                  , C3.ATTRIBUTE5, C3.ATTRIBUTE6, C3.ATTRIBUTE7, C3.ATTRIBUTE8, C3.ATTRIBUTE9, C3.ATTRIBUTE10);
        END LOOP;
        /* CURSOR_3 CLOSE */

        /* 선박biz사업부 NET DEMAND 제거 [E20230112-000310] */
        DELETE FROM GT_DM_NET_TEMP5 A
         WHERE EXISTS (SELECT 1 FROM SCM_MST_SITE B WHERE A.DIVISION_ID = B.DIVISION_ID AND A.SCM_SITE_ID = B.SCM_SITE_ID AND NVL(B.OPERATION_GROUP, 'X') <> 'W')
           AND A.DIVISION_ID IN (SELECT SEGMENT1 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y')
           AND A.SCM_SITE_ID IN (SELECT SEGMENT2 FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = 'DM_NET_DEMAND_EXCEPTION' AND VALID_YN = 'Y');

        /* DM_PLN_NET_DEMAND insert전 중복제거, insert */
        DELETE FROM DM_PLN_NET_DEMAND D
         WHERE EXISTS (
                SELECT 1 FROM GT_DM_NET_TEMP5 B
                 WHERE D.VERSION_NO        = B.VERSION_NO
                   AND D.CUTOFF_YYYYMMDD   = B.CUTOFF_YYYYMMDD
                   AND D.DIVISION_ID       = B.DIVISION_ID
                   AND B.DIVISION_ID       = P_DIVISION_ID);

        INSERT INTO DM_PLN_NET_DEMAND
            (DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD, DEMAND_PRIORITY, QTY, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8, ATTRIBUTE9, ATTRIBUTE10)
        SELECT DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD
             , MAX(DEMAND_PRIORITY)   AS DEMAND_PRIORITY
             , SUM(QTY)               AS QTY
             , MAX(CREATED_BY)
             , MAX(CREATION_DATE)
             , MAX(LAST_UPDATED_BY)
             , SYSDATE
             , MAX(ATTRIBUTE1), MAX(ATTRIBUTE2), MAX(ATTRIBUTE3), MAX(ATTRIBUTE4), MAX(ATTRIBUTE5)
             , MAX(ATTRIBUTE6), MAX(ATTRIBUTE7), MAX(ATTRIBUTE8), MAX(ATTRIBUTE9), MAX(ATTRIBUTE10)
          FROM GT_DM_NET_TEMP5
         GROUP BY DIVISION_ID, VERSION_NO, CUTOFF_YYYYMMDD, PROJECT_CODE, SCM_SITE_ID, ITEM_ID, DOM_EXP, FCST_TYPE, INCOTERMS, PLANT_SITE_ID, CELL_PROD_SITE_ID, DEMAND_TYPE, YYYYMMDD;

        /* 트랜잭션 COMMIT */
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '@p_division_id : ' || P_DIVISION_ID || ' / ' || '전주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION1, 'NULL')
                     || ' / ' || '당주CUTOFF VERSION : ' || NVL(V_INPUT_VERSION2, 'NULL') || ' / ' || '@MAX_PLAN_ID : ' || NVL(V_MAX_PLAN_ID, 'NULL')
                     || ' / ' || '@CF_count : ' || TO_CHAR(V_CF_COUNT) || ' / ' || '@UF_count : ' || TO_CHAR(V_UF_COUNT)
                     || ' / ' || '@NF_count : ' || TO_CHAR(V_NF_COUNT) || ' / ' || '@ESS_count : ' || TO_CHAR(V_ESS_COUNT);
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
END PR_DM_PLN_MKT_FCST_TO_NET_DEMAND;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_MKT_FCST_TO_NET_DEMAND
-- ##### END PROCEDURE PR_DM_PLN_MKT_FCST_TO_NET_DEMAND

-- ##### START PROCEDURE PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE
CREATE OR REPLACE PROCEDURE           "PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE" 
(   P_DIVISION_ID       IN VARCHAR2                       /* DIVISION_ID */
  , P_CUTOFF_YYYYMMDD   IN VARCHAR2                       /* Sales Plan Cutoff 날짜 */
  , P_CREATION_TYPE     IN VARCHAR2 DEFAULT 'REGULAR'     /* [E20250529-001289] 생성 유형(메일 문구 구분) */
)
/*==============================================================================================================================
 * Program ID   : PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE
 * Description  : 매주 목,금요일에 Sales Plan Weekly cutoff 수행(81 : 목 00시, 40,82 : 금 00시)
 * Program History
 *==============================================================================================================================
 *   Date       In Charge   Description
 *==============================================================================================================================
 * 2020-07-01   P.C.I        [PJ20200138] Sales Plan Waterfall cut-off 주기 변경 - MKT_FCST_C/SALES_PLAN_C 분리(Weekly Cutoff Sales Price Version No 조회 (40,81 : 화요일 /82 : SP Version과 동일))
 * 2020-07-22   P.C.I        [PJ20200138] Sales Plan Weekly Cutoff 생성시 Sales Price, Exchange Rate Cutoff 동시 생성
 * 2020-07-27   P.C.I        [PJ20200138] Sales Plan Weekly Cutoff 생성시 실적은 MKT Fcst가 Cutoff 되는 시점의 화요일 Cutoff 실적을 사용하도록 로직 수정
 * 2020-07-31   HWI1993      과제 - ESS 실적매핑시 내부거래등 제거로직 적용에 따른 RESULT.ATTRIBUTE2 추가(확인) - 변경사항 없음.
 * 2020-09-09   P.C.I        [C20200909-000203] LOG 표준화 적용
 * 2020-12-08   P.C.I        [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용
 * 2021-02-05   KUNI         [C20210204-000387] (82)ESS사업부_SALES PLAN WATERFALL에 ETC매출 포함(LOOKUP)
 * 2021-07-02   HWI1993      [C20210629-000239] [SCM PI팀] MKT FCST Amt. 추가의 건
 * 2022-04-07   hwi1993      GM JV 작업
 * 2023-01-17   chano0612    [E20230112-000310] GSCM 자동차사업부 시스템 상 MKT FCST 입력을 위한 기능변경 건 - 선박BIZ건
 * 2023-03-11   chano0612    [E20230309-000241]자동차사업부 GSCM내 선박 고객사 RTF 미부여의 건
 * 2024-04-03   KCW3408      Sales Plan 관련 자동사업부 기타 매출 추가(LOOKUP_TYPE:DM_SALES_PLAN_WATERFALL_SP_W_ADD)
 * 2024-05-28   HMIN         [E20240508-000695] Corvus/Siemens사 자동차사업부 RTF 산출 시 동기화 반영 요청
 *                           룩업(DM_NET_DEMAND_EXCEPTION)에 등록된 SITE대상으로 82번 사업부에 RTF정보를 81번 RTF 정보로 반영 처리
 * 2024-10-30   JSSAE        [E20241024-001084]_MKT FCST ↔ Sales Plan 실적 차이 발생 개선 요청 件
 * 2024-11-15   KJJ          [PJ2024-50611] 소형사업부 Sales Plan 기타매출 입력 추가
 * 2024-11-15   KANG.H.J     [PJ2024-50611] 소형 매출 프로세스 개선
 * 2024-11-29   KANG.H.J     [PJ2024-50611] FROM_SITE_ID가 추가된 'DM_PLN_RTF_ALLOCATION_C' 테이블 Sales Plan Cutoff(전 사업부대상)
 * 2024-12-03   KJJ          [PJ2024-50611] 소형사업부 Sales Plan Catch Up 컷오프 추가
 * 2024-12-17   KJJ          [PJ2024-50611] 기타매출, Catch Up 테이블 분리
 * 2025-03-18   KANG.H.J     [PJ2025-50017] 소형 매출계획 동기화 개선
 * 2025-04-08   KANG.H.J     [PJ2025-50017] 소형 매출계획 동기화 개선 - DM_PLN_RTF_ALLOCATION 삭제처리
 * 2025-04-23   KANG.H.J     [PJ2025-50017] 소형 매출계획 동기화 개선 - MF_W / SF_W 를 LOOKUP 기준에서 조치함. / SCM_FCST 추가
 * 2025-04-28   KANG.H.J     [PJ2025-50017] 소형 매출계획 동기화 개선 - BPS 전송용 FROM_SITE_ID(ATTRIBUTE2 연계) (40사업부/CELL_PROD_SITE_ID='-'일 때만 생성)
 * 2025-05-02   KANG.H.J     [PJ2025-50017] 소형 매출계획 동기화 개선 - #T_PRICE의 CELL_PROD_SITE_ID 기준을 MKT_DEMAND_PLAN_C로 기준 변경
 * 2025-05-07   KANG.H.J     [PJ2025-50188] 기준수요처레에 따른 CUTOFF_TYPE 버젼 생성 구분처리
 * 2025-05-29   KANG.H.J     [PJ2025-50188] 임시테이블 #T3_MKT_FCST / #T3_PRICE DROP 추가, 임시테이블 #T3_MKT_FCST ==> #T_SP_C_BALANCE_MKT_FCST / #T3_PRICE ==> #T_SP_C_BALANCE_PRICE 변경
 * 2025-06-05   KANG.H.J     [PJ2025-50188] EXCEPTION_DEMAND의 CELL_PROD_SITE_ID 수정
 * 2025-06-05   JSSBAE       [E20250529-001289]_DM 장애 대응 개선을 위한 시스템 개선
 * 2025-06-13   KANG.H.J     [PJ2025-50188] SALES_AMT (3종) ATTRIBUTE2 (FROM_SITE_ID) 누락 개선
 * 2025-06-18   KANG.H.J     [PJ2025-50188] ON절에서 WHERE 절로 이동
 * 2025-06-18   KANG.H.J     [PJ2025-50188] 40사업부는 CELL_PROD_SITE_ID까지 PRICE 비교 / 81,82사업부는 CELL_PROD_SITE_ID를 '-'로 치환하여 PRICE 비교
 * 2025.06.23   KANG.H.J     [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2025.07.23   JSSBAE       [PJ2025-50188]_소형 매출계획 동기화 개선 고도화 [Sales Price Cutoff 개선]
 * 2026.07.08   JSSBAE       [E20260630-000725]_[요청] SCM Sales Plan Waterfall 내 판가 반영 및 매출금액 산출 로직 오류 점검 요청
 * 2026.07.06   ZIONEX       [PJ202650304] NextSCM Migration
 *
 * EXEC PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE  @p_division_id='81', @p_cutoff_yyyymmdd = '20240401'
 * --PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE '81', '20230314'
 *==============================================================================================================================*/
IS
    /* LOG 용 변수 */
    V_PROGRAM_NAME          VARCHAR2(150 CHAR) := 'PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE';
    V_LOG_TYPE              VARCHAR2(30 CHAR);
    N_LOG_COUNT             NUMBER := 0;
    V_LOG_MESSAGE           VARCHAR2(1000 CHAR);
    V_DESCRIPTION           VARCHAR2(500 CHAR);
    D_EVENT_DATE            DATE;
    C_MF_VERSION            VARCHAR2(100 CHAR);
    V_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    V_CUTOFF_VERSION_TYPE   VARCHAR2(10 CHAR);
    C_MF_RESULT_VERSION     VARCHAR2(100 CHAR);
    C_SP_RESULT_VERSION     VARCHAR2(100 CHAR);
    C_VER_TYPE              VARCHAR2(10 CHAR)   := 'SP_W';
    V_CREATED_BY            VARCHAR2(1000 CHAR) := 'system';
    V_COUNT                 NUMBER := 0;
    S_COUNT                 NUMBER := 0;
    V_CNT                   NUMBER := 0;
    V_I                     NUMBER := 0;
    V_SITE_ID               VARCHAR2(100 CHAR);
    V_VER_RETURN_NO         VARCHAR2(100 CHAR);
    V_OK_DESCRIPTION        VARCHAR2(1200 CHAR);
    S_BLOCK_MODEL           VARCHAR2(4000 CHAR);
    /* 3. 81번 선박사업부 82번 매출 매핑용(원본 본문 중간 DECLARE -> 선언부로 이관) */
    C_MF_VERSION_81         VARCHAR2(100 CHAR);
    C_SP_VERSION_81         VARCHAR2(100 CHAR);
    P_CUTOFF_YYYYMMDD_81    VARCHAR2(8 CHAR);

    L_CUTOFF_YYYYMMDD       VARCHAR2(8 CHAR);
BEGIN

    DELETE
      FROM GT_DPSPCQB_SP_C_BALANCE_MKT_FCST;
    DELETE
      FROM GT_DPSPCQB_SP_C_BALANCE_PRICE;
    DELETE
      FROM GT_DPSPCQB_SALES_PLAN;
    DELETE
      FROM GT_DPSPCQB_SALES_ETC_PLAN;
    DELETE
      FROM GT_DPSPCQB_AFTER_RTF_81;

    L_CUTOFF_YYYYMMDD := P_CUTOFF_YYYYMMDD;

    DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A001: DIVISION_ID: ' || P_DIVISION_ID || ' / CUTOFF_YYYYMMDD: ' || L_CUTOFF_YYYYMMDD);

    /*=========================================================================================================== */
    /* 변수값 셋팅 */
    /*=========================================================================================================== */
    IF L_CUTOFF_YYYYMMDD IS NULL THEN
        L_CUTOFF_YYYYMMDD := TO_CHAR(SYSDATE, 'YYYYMMDD');
    END IF;

    V_PLAN_START_YYYYMMDD := TO_CHAR(FN_NEXT_DAY(TO_DATE(L_CUTOFF_YYYYMMDD, 'YYYYMMDD'), 'MON') - 7, 'YYYYMMDD');   /* 월요일 */

    /*=========================================================================================================== */
    /* 시작 LOG (START) */
    /*=========================================================================================================== */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '@p_division_id : ' || RTRIM(LTRIM(P_DIVISION_ID));
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    /* [C20210204-000387] / 2024-04-03 Sales Plan 자동사업부 기타 매출(DM_SALES_PLAN_WATERFALL_SP_W_ADD) */
    IF (P_DIVISION_ID = '82' OR P_DIVISION_ID LIKE '81%') THEN
        S_BLOCK_MODEL := '';
        BEGIN
            SELECT NVL(LOOKUP_TYPE, ' ')
              INTO S_BLOCK_MODEL
              FROM (SELECT LOOKUP_TYPE
                       FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                      WHERE LOOKUP_TYPE  = 'DM_SALES_PLAN_WATERFALL_SP_W_ADD'
                        AND SEGMENT1     = P_DIVISION_ID
                        AND VALID_YN     = 'Y'
                        AND SEGMENT1    IS NOT NULL
                        AND SEGMENT2    IS NOT NULL
                        AND SEGMENT3    IS NOT NULL )
             WHERE ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            S_BLOCK_MODEL := '';
        END;

        IF S_BLOCK_MODEL IS NULL THEN
            V_LOG_TYPE    := 'INVALID';
            DBMS_OUTPUT.PUT_LINE('MODEL : ' || S_BLOCK_MODEL || CHR(10) || 'DM_SALES_PLAN_WATERFALL_SP_W_ADD IS NOT');
            V_DESCRIPTION := 'MODEL : ' || S_BLOCK_MODEL || CHR(10) || 'DM_SALES_PLAN_WATERFALL_SP_W_ADD IS NOT';

            V_LOG_MESSAGE := '########## END of procedure ##########';
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            RETURN;
        END IF;
    END IF;

    /*------------------------------------------------------------------------------------------ */
    BEGIN
    /*------------------------------------------------------------------------------------------ */
        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A002: DIVISION_ID: ' || P_DIVISION_ID || ' / CUTOFF_YYYYMMDD: ' || L_CUTOFF_YYYYMMDD);

        /* MKT FCST -> SALES PLAN 동기화 진행 */
        PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW(P_DIVISION_ID, 'SYSTEM');

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A003: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* Cutoff Version 생성 */
        PR_DM_PLN_VERSION_CREATE( P_DIVISION_ID
                                , 'SALES_PLAN WEEKLY CUTOFF'
                                , C_VER_TYPE
                                , V_CREATED_BY
                                , V_VER_RETURN_NO
                                , V_OK_DESCRIPTION );

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A004: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* [PJ2025-50188] VERSION_TYPE 구분 (가장 최근 버젼, SF_W가 MF_W보다 우선) */
        BEGIN
            SELECT VERSION_TYPE
              INTO V_CUTOFF_VERSION_TYPE
              FROM (SELECT VERSION_TYPE
                          , RANK() OVER (ORDER BY YYYYMMDD DESC, VER_CRE_SEQ DESC, VERSION_TYPE DESC) AS RN
                       FROM DM_MST_VERSION
                      WHERE DIVISION_ID  = P_DIVISION_ID
                        AND VERSION_TYPE IN ('MF_W', 'SF_W')
                        AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD )
             WHERE RN = 1 AND ROWNUM = 1;
        EXCEPTION WHEN NO_DATA_FOUND THEN
            V_CUTOFF_VERSION_TYPE := NULL;
        END;

        SELECT MAX(VERSION_NO)
          INTO C_MF_VERSION      /* 40=SF_W / 그 외=MF_W 기반 VERSION */
          FROM DM_MST_VERSION
         WHERE DIVISION_ID   = P_DIVISION_ID
           AND YYYYMMDD     >= V_PLAN_START_YYYYMMDD
           AND VERSION_TYPE  = V_CUTOFF_VERSION_TYPE;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A005: DIVISION_ID: ' || P_DIVISION_ID || ' / MF_W버전: ' || C_MF_VERSION);

        SELECT MAX(VERSION_NO)
          INTO C_MF_RESULT_VERSION      /* 실적 연계 VERSION은 MF_W 한정 */
          FROM DM_MST_VERSION
         WHERE DIVISION_ID   = P_DIVISION_ID
           AND YYYYMMDD     >= V_PLAN_START_YYYYMMDD
           AND VERSION_TYPE  = 'MF_W';

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A006: DIVISION_ID: ' || P_DIVISION_ID || ' / 실적버전: ' || C_MF_VERSION);

        /* [PJ20200138] Sales Plan Result Daily Cutoff Version */
        SELECT MIN(VERSION_NO)
          INTO C_SP_RESULT_VERSION
          FROM DM_MST_VERSION
         WHERE DIVISION_ID   = P_DIVISION_ID
           AND YYYYMMDD      = SUBSTR(C_MF_RESULT_VERSION, 6, 8)   /* [PJ2025-50188] 실적 연계 MF_W 한정 */
           AND VERSION_TYPE  = 'SP_D';

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A007: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_D버전: ' || C_SP_RESULT_VERSION);


        V_LOG_TYPE    := 'ING';
        V_LOG_MESSAGE := 'SALES_PLAN WEEKLY CUTOFF';
        V_DESCRIPTION := '@p_division_id : ' || RTRIM(LTRIM(P_DIVISION_ID)) || ' / ' || '@v_ver_return_no : ' || RTRIM(LTRIM(V_VER_RETURN_NO)) || ' / ' || '@c_MF_version : ' || RTRIM(LTRIM(C_MF_VERSION))
                      || ' / ' || '@c_MF_result_version : ' || RTRIM(LTRIM(C_MF_RESULT_VERSION));
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
        V_LOG_MESSAGE := NULL;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A008: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_D버전: ' || C_SP_RESULT_VERSION);

        /* [PJ20200138] Sales Price / Exchange Rate Cutoff 동시 생성 */
        /* SALES PRICE CUTOFF (금액) */
        PR_SCM_MST_FUTURE_PRICE_CUTOFF(P_DIVISION_ID, C_VER_TYPE, V_CREATED_BY, V_VER_RETURN_NO, C_MF_RESULT_VERSION);
        /* EXCHANGE CUTOFF (환율) */
        PR_DM_MST_EXCHANGE_RATE_CUTOFF(P_DIVISION_ID, C_VER_TYPE, V_CREATED_BY, V_VER_RETURN_NO);

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A009: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /*=========================================================================================================== */
        /* 1. DM_PLN_SALES_PLAN_C CUTOFF */
        /*=========================================================================================================== */
        /* [PJ2025-50017] 40 = DM_PLN_CFM_MKT_DEMAND_PLAN_C 기반 / 81,82 = DM_PLN_MKT_FCST_C + DM_PLN_CFM_MKT_DEMAND_PLAN_C 기반 */
        IF (P_DIVISION_ID = '40') THEN
            /* DM_PLN_CFM_MKT_DEMAND_PLAN_C -> GT_DPSPCQB_SP_C_BALANCE_MKT_FCST */
            INSERT
              INTO GT_DPSPCQB_SP_C_BALANCE_MKT_FCST
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
              FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = C_MF_VERSION
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD;

            /* [PJ2025-50188] RTF_SCP 는 RTF_SYS_RP 기반 COPY 필요 -> 기존 RTF_SCP 삭제 */
            DELETE
              FROM GT_DPSPCQB_SP_C_BALANCE_MKT_FCST
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = C_MF_VERSION
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD
               AND MEASURE      = 'RTF_SCP';

            /* RTF_SYS_RP -> RTF_SCP 로 복제 */
            INSERT
              INTO GT_DPSPCQB_SP_C_BALANCE_MKT_FCST
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , 'RTF_SCP' AS MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
              FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = C_MF_VERSION
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD
               AND MEASURE      = 'RTF_SYS_RP';

            /* DM_PLN_CFM_SELLING_PRICE_C -> GT_DPSPCQB_SP_C_BALANCE_PRICE */
            INSERT
              INTO GT_DPSPCQB_SP_C_BALANCE_PRICE
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , ITEM_ID
                 , YYYYMMDD
                 , CURRENCY
                 , MEASURE
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , PRICE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , ITEM_ID
                 , YYYYMMDD
                 , CURRENCY
                 , MEASURE
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , PRICE
                 , CREATED_BY
                 , CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
              FROM DM_PLN_CFM_SELLING_PRICE_C
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = V_VER_RETURN_NO
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD;

            DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A011: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);
        ELSE
            DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A012: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);


            INSERT
              INTO GT_DPSPCQB_SP_C_BALANCE_MKT_FCST
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , '-' AS CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
              FROM DM_PLN_MKT_FCST_C
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = C_MF_VERSION
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD
               AND MEASURE NOT IN ('RTF','RTF_SYS_RP','RTF_SCP','RTF_PR','SalesAmt_LOC','SalesAmt_KRW','SalesAmt_USD','VMI_IN_PLAN','AS_IN_PLAN')
            UNION
            SELECT DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , YYYYMMDD
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
              FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C
             WHERE DIVISION_ID  = P_DIVISION_ID
               AND VERSION_NO   = C_MF_VERSION
               AND YYYYMMDD    >= V_PLAN_START_YYYYMMDD
               AND MEASURE IN ('RTF','RTF_SYS_RP','RTF_SCP','RTF_PR','SalesAmt_LOC','SalesAmt_KRW','SalesAmt_USD','VMI_IN_PLAN','AS_IN_PLAN');

            /* SCM_MST_FUTURE_PRICE_C -> GT_DPSPCQB_SP_C_BALANCE_PRICE */
            INSERT
              INTO GT_DPSPCQB_SP_C_BALANCE_PRICE
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , PLANT_SITE_ID
                 , CELL_PROD_SITE_ID
                 , ITEM_ID
                 , YYYYMMDD
                 , CURRENCY
                 , MEASURE
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , PRICE
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10 )
            SELECT DISTINCT A.DIVISION_ID
                 , A.VERSION_NO
                 , A.CUTOFF_TYPE
                 , A.CUTOFF_YYYYMMDD
                 , A.PROJECT_CODE
                 , A.SCM_SITE_ID
                 , A.PLANT_SITE_ID
                 , '-' AS CELL_PROD_SITE_ID
                 , A.ITEM_ID
                 , A.YYYYMMDD
                 , A.CURRENCY
                 , A.MEASURE
                 , A.DOM_EXP
                 , A.FCST_TYPE
                 , A.INCOTERMS
                 , A.PRICE
                 , A.CREATED_BY
                 , A.CREATION_DATE
                 , V_CREATED_BY AS LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , A.ATTRIBUTE1
                 , A.ATTRIBUTE2
                 , A.ATTRIBUTE3
                 , A.ATTRIBUTE4
                 , A.ATTRIBUTE5
                 , A.ATTRIBUTE6
                 , A.ATTRIBUTE7
                 , A.ATTRIBUTE8
                 , A.ATTRIBUTE9
                 , A.ATTRIBUTE10
              FROM SCM_MST_FUTURE_PRICE_C A
             WHERE A.DIVISION_ID  = P_DIVISION_ID
               AND A.VERSION_NO   = V_VER_RETURN_NO
               AND A.YYYYMMDD    >= V_PLAN_START_YYYYMMDD;
        END IF;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A013: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /*=========================================================================================================== */
        /* QTY measure 생성 */
        /*=========================================================================================================== */
        INSERT
          INTO GT_DPSPCQB_SALES_PLAN
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , CELL_PROD_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , NVL(IA.CURRENCY, ' ') AS CURRENCY
             , A.QTY
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
          FROM GT_DPSPCQB_SP_C_BALANCE_MKT_FCST A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'LOC'
           AND A.DIVISION_ID       = P_DIVISION_ID
           AND A.VERSION_NO        = C_MF_VERSION
           AND A.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
           AND A.MEASURE    IN ('MKT_FCST','SCM_FCST','CUST_FCST','TMM_FCST','RTF_SCP','RTF_SYS_RP','RTF','RTF_PR')
           AND A.ITEM_ID    IN (SELECT ITEM_ID
                                   FROM SCM_MST_ITEM_SN
                                  GROUP BY ITEM_ID );

        /*=========================================================================================================== */
        /* AMT measure 생성 (SalesAmt_KRW / LOC / USD, MKT_AMT_KRW / LOC) */
        /*=========================================================================================================== */
        INSERT
          INTO GT_DPSPCQB_SALES_PLAN
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , CELL_PROD_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )

        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , 'SalesAmt_KRW' AS MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , IA.CURRENCY
             , ROUND(A.QTY * NVL(IA.PRICE, 0), 5)
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , NULL
             , A.ATTRIBUTE2
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
          FROM GT_DPSPCQB_SALES_PLAN A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'KRW'
           AND A.DIVISION_ID       = P_DIVISION_ID
           /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
           AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
           AND A.MEASURE           = 'RTF_SYS_RP'

        UNION ALL

        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , 'SalesAmt_LOC' AS MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , IA.CURRENCY
             , ROUND(A.QTY * NVL(IA.PRICE, 0), 5)
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , NULL
             , A.ATTRIBUTE2
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
          FROM GT_DPSPCQB_SALES_PLAN A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'LOC'
           AND A.DIVISION_ID       = P_DIVISION_ID
           /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
           AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
           AND A.MEASURE           = 'RTF_SYS_RP'

        UNION ALL

        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , 'SalesAmt_USD' AS MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , IA.CURRENCY
             , ROUND(A.QTY * NVL(IA.PRICE, 0), 5)
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , NULL
             , A.ATTRIBUTE2
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
          FROM GT_DPSPCQB_SALES_PLAN A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'USD'
           AND A.DIVISION_ID       = P_DIVISION_ID
           /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
           AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
           AND A.MEASURE           = 'RTF_SYS_RP'

        UNION ALL
        /* MKT_AMT_KRW (C20200803-000105, [C20210629-000239] 사업부제한 없앰) */
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , 'MKT_AMT_KRW' AS MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , IA.CURRENCY
             , ROUND(A.QTY * NVL(IA.PRICE, 0), 5)
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
          FROM GT_DPSPCQB_SALES_PLAN A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'KRW'
           AND A.MEASURE           = 'MKT_FCST'
        UNION ALL

        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , 'MKT_AMT_LOC' AS MEASURE
             , A.PLANT_SITE_ID
             , A.CELL_PROD_SITE_ID
             , A.YYYYMMDD
             , IA.CURRENCY
             , ROUND(A.QTY * NVL(IA.PRICE, 0), 5)
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
             , NULL
          FROM GT_DPSPCQB_SALES_PLAN A
             , SCM_SYS_CALENDAR_M B
             , (SELECT *
                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                  WHERE DIVISION_ID  = P_DIVISION_ID
                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
           AND A.ITEM_ID           = IA.ITEM_ID(+)
           AND A.DOM_EXP           = IA.DOM_EXP(+)
           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
           AND A.INCOTERMS         = IA.INCOTERMS(+)
           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
           AND IA.MEASURE(+)       = 'LOC'
           AND A.MEASURE           = 'MKT_FCST';

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A014: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* [C20210204-000387] / 2024-04-03 기타매출(ETC) -> GT_DPSPCQB_SALES_ETC_PLAN */
        INSERT
          INTO GT_DPSPCQB_SALES_ETC_PLAN
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , REMARK_TEXT
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.REMARK_TEXT
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , A.CURRENCY
             , A.QTY
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , 'ADD.ETC'
          FROM DM_PLN_SALES_ETC_PLAN A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD  = A.YYYYMMDD
           AND A.DIVISION_ID     = P_DIVISION_ID
           AND A.YYYYMMDD       >= V_PLAN_START_YYYYMMDD
           AND A.FCST_TYPE IN (SELECT DISTINCT SEGMENT2
                                  FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                 WHERE LOOKUP_TYPE  = 'DM_SALES_PLAN_WATERFALL_SP_W_ADD'
                                   AND VALID_YN     = 'Y'
                                   AND SEGMENT1     = A.DIVISION_ID )
           AND A.ITEM_ID IN (SELECT DISTINCT SEGMENT3
                                FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                               WHERE LOOKUP_TYPE  = 'DM_SALES_PLAN_WATERFALL_SP_W_ADD'
                                 AND VALID_YN     = 'Y'
                                 AND SEGMENT1     = A.DIVISION_ID )
           /* [ETC 매출 조회 불가] GSCM MKT FCST 수정 요청 (DM_SALE_PLAN_ETC_EXCEPTION 제외) */
           AND NOT EXISTS (SELECT 1
                              FROM SCM_ADM_LOOKUP_MASTER_DETAIL SA
                             WHERE SA.LOOKUP_TYPE  = 'DM_SALE_PLAN_ETC_EXCEPTION'
                               AND SA.VALID_YN     = 'Y'
                               AND A.PROJECT_CODE  = SA.ATTRIBUTE1
                               AND A.ITEM_ID       = SA.SEGMENT2
                               AND A.YYYYMMDD      = SA.SEGMENT4
                               AND A.FCST_TYPE     = SA.ATTRIBUTE3
                               AND A.MEASURE       = SA.SEGMENT3 );

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A015: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* [PJ2024-50611] 소형사업부 Sales Plan Catch Up 컷오프 추가 */
        INSERT
          INTO GT_DPSPCQB_SALES_ETC_PLAN
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , REMARK_TEXT
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.REMARK_TEXT
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , A.CURRENCY
             , A.QTY
             , A.CREATED_BY
             , A.CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
          FROM DM_PLN_SALES_ETC_PLAN A
             , SCM_SYS_CALENDAR_M B
         WHERE B.BASIS_YYYYMMDD  = A.YYYYMMDD
           AND A.DIVISION_ID     = P_DIVISION_ID
           AND A.YYYYMMDD       >= V_PLAN_START_YYYYMMDD
           AND A.MEASURE IN ('Catch_Up','SalesAmt_KRW_Catch_Up','SalesAmt_LOC_Catch_Up','SalesAmt_USD_Catch_Up');

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A016: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* [E20230309-000241] 자동차사업부 선박 고객사 RTF 미부여 (81) */
        V_COUNT := 0;
        S_COUNT := 0;
        V_CNT   := 0;
        IF (P_DIVISION_ID = '81') THEN
            DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A017: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

            SELECT COUNT(SEGMENT2)
              INTO V_CNT
              FROM SCM_ADM_LOOKUP_MASTER_DETAIL
             WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
               AND VALID_YN     = 'Y';

            V_I := 1;
            WHILE V_I <= V_CNT LOOP
                V_SITE_ID := '';
                BEGIN
                    SELECT SEGMENT2
                      INTO V_SITE_ID
                      FROM (SELECT ROW_NUMBER() OVER(ORDER BY SEGMENT2) AS SEQ
                                  , SEGMENT2
                               FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                              WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                AND VALID_YN     = 'Y' ) IA
                     WHERE IA.SEQ = V_I;
                EXCEPTION WHEN NO_DATA_FOUND THEN
                    V_SITE_ID := NULL;
                END;

                SELECT COUNT(*)
                  INTO V_COUNT
                  FROM GT_DPSPCQB_SALES_PLAN
                 WHERE DIVISION_ID  = '81'
                   AND MEASURE      = 'RTF_SYS_RP'
                   AND SCM_SITE_ID  = V_SITE_ID;

                IF (V_COUNT = 0) THEN
                    SELECT COUNT(*)
                      INTO S_COUNT
                      FROM GT_DPSPCQB_SALES_PLAN
                     WHERE DIVISION_ID  = '81'
                       AND SCM_SITE_ID  = V_SITE_ID
                       AND MEASURE      = 'RTF';

                    IF (S_COUNT > 0) THEN
                        UPDATE GT_DPSPCQB_SALES_PLAN
                           SET MEASURE = 'RTF_SYS_RP'
                         WHERE DIVISION_ID  = '81'
                           AND SCM_SITE_ID  = V_SITE_ID
                           AND MEASURE      = 'RTF';
                        DBMS_OUTPUT.PUT_LINE(V_SITE_ID);
                    ELSE
                        INSERT
                          INTO GT_DPSPCQB_SALES_PLAN
                             ( DIVISION_ID
                             , PROJECT_CODE
                             , SCM_SITE_ID
                             , ITEM_ID
                             , DOM_EXP
                             , FCST_TYPE
                             , INCOTERMS
                             , MEASURE
                             , PLANT_SITE_ID
                             , CELL_PROD_SITE_ID
                             , YYYYMMDD
                             , CURRENCY
                             , QTY
                             , CREATED_BY
                             , CREATION_DATE
                             , LAST_UPDATED_BY
                             , LAST_UPDATE_DATE
                             , ATTRIBUTE1
                             , ATTRIBUTE2
                             , ATTRIBUTE3
                             , ATTRIBUTE4
                             , ATTRIBUTE5
                             , ATTRIBUTE6
                             , ATTRIBUTE7
                             , ATTRIBUTE8
                             , ATTRIBUTE9
                             , ATTRIBUTE10 )
                        SELECT A.DIVISION_ID
                             , A.PROJECT_CODE
                             , A.SCM_SITE_ID
                             , A.ITEM_ID
                             , A.DOM_EXP
                             , A.FCST_TYPE
                             , A.INCOTERMS
                             , 'RTF_SYS_RP' AS MEASURE
                             , A.PLANT_SITE_ID
                             , A.CELL_PROD_SITE_ID
                             , A.YYYYMMDD
                             , NVL(IA.CURRENCY, ' ') AS CURRENCY
                             , A.QTY
                             , A.CREATED_BY
                             , A.CREATION_DATE
                             , V_CREATED_BY AS LAST_UPDATED_BY
                             , SYSDATE
                             , A.ATTRIBUTE1
                             , A.ATTRIBUTE2
                             , A.ATTRIBUTE3
                             , A.ATTRIBUTE4
                             , A.ATTRIBUTE5
                             , A.ATTRIBUTE6
                             , A.ATTRIBUTE7
                             , A.ATTRIBUTE8
                             , A.ATTRIBUTE9
                             , A.ATTRIBUTE10
                          FROM GT_DPSPCQB_SP_C_BALANCE_MKT_FCST A
                             , SCM_SYS_CALENDAR_M B
                             , (SELECT *
                                   FROM GT_DPSPCQB_SP_C_BALANCE_PRICE
                                  WHERE DIVISION_ID  = P_DIVISION_ID
                                    AND VERSION_NO   = V_VER_RETURN_NO ) IA
                         WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
                           AND A.DIVISION_ID       = IA.DIVISION_ID(+)
                           AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
                           AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
                           AND A.ITEM_ID           = IA.ITEM_ID(+)
                           AND A.DOM_EXP           = IA.DOM_EXP(+)
                           AND A.FCST_TYPE         = IA.FCST_TYPE(+)
                           AND A.INCOTERMS         = IA.INCOTERMS(+)
                           AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
                           AND CASE WHEN A.DIVISION_ID = '40' THEN A.CELL_PROD_SITE_ID ELSE '-' END = IA.CELL_PROD_SITE_ID(+)
                           AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
                           AND IA.MEASURE(+)       = 'LOC'
                           AND A.DIVISION_ID       = P_DIVISION_ID
                           AND A.VERSION_NO        = C_MF_VERSION
                           AND A.YYYYMMDD         >= V_PLAN_START_YYYYMMDD
                           AND A.MEASURE    IN ('MKT_FCST')
                           AND A.SCM_SITE_ID       = V_SITE_ID;
                        DBMS_OUTPUT.PUT_LINE(V_SITE_ID);
                    END IF;
                END IF;

                V_I := V_I + 1;
            END LOOP;
            DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A018: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);
        END IF;

        /* dm_pln_sales_plan_c 에 cutoff data insert (CUTOFF_YYYYMMDD_DATE 가상컬럼 제외) */
        INSERT
          INTO DM_PLN_SALES_PLAN_C
             ( DIVISION_ID
             , VERSION_NO
             , CUTOFF_TYPE
             , CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , CELL_PROD_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT DISTINCT
               DIVISION_ID
             , V_VER_RETURN_NO
             , C_VER_TYPE
             , L_CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , CELL_PROD_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , SYSDATE AS LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
          FROM GT_DPSPCQB_SALES_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A019: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* [PJ2024-50611] 기타매출, Catch Up 별도 테이블 컷오프 */
        INSERT
          INTO DM_PLN_SALES_ETC_PLAN_C
             ( DIVISION_ID
             , VERSION_NO
             , CUTOFF_TYPE
             , CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , REMARK_TEXT
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10 )
        SELECT DISTINCT
               DIVISION_ID
             , V_VER_RETURN_NO
             , C_VER_TYPE
             , L_CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , REMARK_TEXT
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , SYSDATE AS LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
          FROM GT_DPSPCQB_SALES_ETC_PLAN
         WHERE DIVISION_ID = P_DIVISION_ID;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A020: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /*=========================================================================================================== */
        /* 2. DM_PLN_SALES_PLAN_RESULT_C CUTOFF */
        /*=========================================================================================================== */
        INSERT
          INTO DM_PLN_SALES_PLAN_RESULT_C
             ( DIVISION_ID
             , VERSION_NO
             , CUTOFF_TYPE
             , CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , COMPANY_ID
             , CELL_PROD_SITE_ID )
        SELECT DIVISION_ID
             , V_VER_RETURN_NO AS VERSION_NO
             , C_VER_TYPE AS CUTOFF_TYPE
             , TO_CHAR(SYSDATE, 'YYYYMMDD') AS CUTOFF_YYYYMMDD
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , NVL(NULLIF(RTRIM(CURRENCY),''), '/')
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , V_CREATED_BY AS LAST_UPDATED_BY
             , SYSDATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , COMPANY_ID
             , CELL_PROD_SITE_ID
          FROM DM_PLN_SALES_PLAN_RESULT_C   /* [PJ20200138] 실적은 화요일 Cutoff 실적 사용 */
         WHERE DIVISION_ID  = P_DIVISION_ID
           AND VERSION_NO   = C_SP_RESULT_VERSION;

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A021: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /*=========================================================================================================== */
        /* 3. 81번 선박사업부 82번 매출 매핑 */
        /*=========================================================================================================== */
        IF (P_DIVISION_ID = '82') THEN
            DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A022: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

            /* MKT_FCST Cutoff 버전 */
            SELECT MAX(VERSION_NO)
              INTO C_MF_VERSION_81
              FROM DM_MST_VERSION
             WHERE DIVISION_ID   = '81'
               AND VERSION_TYPE  = 'MF_W'
               AND YYYYMMDD     >= V_PLAN_START_YYYYMMDD;

            /* Sales_Plan Cutoff 버전 */
            SELECT MAX(VERSION_NO)
                 , MAX(YYYYMMDD)
              INTO C_SP_VERSION_81
                 , P_CUTOFF_YYYYMMDD_81
              FROM DM_MST_VERSION
             WHERE DIVISION_ID   = '81'
               AND VERSION_TYPE  = 'SP_W'
               AND YYYYMMDD     >= V_PLAN_START_YYYYMMDD;

            DBMS_OUTPUT.PUT_LINE(NVL(C_MF_VERSION_81,'Z') || '||' || NVL(C_SP_VERSION_81,'X') || '||' || NVL(P_CUTOFF_YYYYMMDD_81,'Y'));

            INSERT
              INTO GT_DPSPCQB_AFTER_RTF_81
                 ( DIVISION_ID
                 , VERSION_NO
                 , CUTOFF_TYPE
                 , CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , YYYYMMDD
                 , CURRENCY
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
                 , CELL_PROD_SITE_ID )
            WITH SALES_PLAN_TEMP_81 AS (
                /* QTY MEASURE 생성 */
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , A.MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , NVL(IA.CURRENCY, ' ') AS CURRENCY
                     , A.QTY
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , 'system' AS LAST_UPDATED_BY
                     , SYSDATE AS LAST_UPDATE_DATE
                     , A.ATTRIBUTE1
                     , A.ATTRIBUTE2
                     , A.ATTRIBUTE3
                     , A.ATTRIBUTE4
                     , A.ATTRIBUTE5
                     , A.ATTRIBUTE6
                     , A.ATTRIBUTE7
                     , A.ATTRIBUTE8
                     , A.ATTRIBUTE9
                     , A.ATTRIBUTE10
                     , A.CELL_PROD_SITE_ID
                  FROM DM_PLN_CFM_MKT_DEMAND_PLAN_C A
                     , SCM_SYS_CALENDAR_M B
                     , (SELECT *
                           FROM SCM_MST_FUTURE_PRICE_C
                          WHERE DIVISION_ID  = '81'
                            AND VERSION_NO   = C_SP_VERSION_81 ) IA
                 WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
                   AND A.DIVISION_ID       = IA.DIVISION_ID(+)
                   AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
                   AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
                   AND A.ITEM_ID           = IA.ITEM_ID(+)
                   AND A.DOM_EXP           = IA.DOM_EXP(+)
                   AND A.FCST_TYPE         = IA.FCST_TYPE(+)
                   AND A.INCOTERMS         = IA.INCOTERMS(+)
                   AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
                   AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
                   AND IA.MEASURE(+)       = 'LOC'
                   AND A.DIVISION_ID       = '81'
                   AND A.VERSION_NO        = C_MF_VERSION_81
                   AND A.YYYYMMDD         >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
                   AND A.ITEM_ID    IN (SELECT ITEM_ID
                                           FROM SCM_MST_ITEM_SN
                                          GROUP BY ITEM_ID )
                   AND A.MEASURE    IN ('RTF_SCP','RTF_SYS_RP','RTF')
                   AND A.SCM_SITE_ID IN (SELECT SEGMENT2
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                             AND VALID_YN     = 'Y' )
            )
            , SALES_PLAN_TEMP_81_2 AS (
                /* KRW */
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , 'SalesAmt_KRW' AS MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , IA.CURRENCY
                     , ROUND(A.QTY * NVL(IA.PRICE, 0), 5) AS QTY
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , 'system' AS LAST_UPDATED_BY
                     , SYSDATE AS LAST_UPDATE_DATE
                     , NULL AS ATTRIBUTE1
                     , NULL AS ATTRIBUTE2
                     , NULL AS ATTRIBUTE3
                     , NULL AS ATTRIBUTE4
                     , NULL AS ATTRIBUTE5
                     , NULL AS ATTRIBUTE6
                     , NULL AS ATTRIBUTE7
                     , NULL AS ATTRIBUTE8
                     , NULL AS ATTRIBUTE9
                     , NULL AS ATTRIBUTE10
                     , A.CELL_PROD_SITE_ID
                  FROM SALES_PLAN_TEMP_81 A
                     , SCM_SYS_CALENDAR_M B
                     , (SELECT *
                           FROM SCM_MST_FUTURE_PRICE_C
                          WHERE DIVISION_ID  = '81'
                            AND VERSION_NO   = C_SP_VERSION_81 ) IA
                 WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
                   AND A.DIVISION_ID       = IA.DIVISION_ID(+)
                   AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
                   AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
                   AND A.ITEM_ID           = IA.ITEM_ID(+)
                   AND A.DOM_EXP           = IA.DOM_EXP(+)
                   AND A.FCST_TYPE         = IA.FCST_TYPE(+)
                   AND A.INCOTERMS         = IA.INCOTERMS(+)
                   AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
                   AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
                   AND IA.MEASURE(+)       = 'KRW'
                   AND A.DIVISION_ID       = '81'
                   /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
                   AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
                   AND A.MEASURE           = 'RTF_SYS_RP'

                   AND A.SCM_SITE_ID IN (SELECT SEGMENT2
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                             AND VALID_YN     = 'Y' )
                UNION ALL
                /* LOC */
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , 'SalesAmt_LOC' AS MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , IA.CURRENCY
                     , ROUND(A.QTY * NVL(IA.PRICE, 0), 5) AS QTY
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , 'system' AS LAST_UPDATED_BY
                     , SYSDATE AS LAST_UPDATE_DATE
                     , NULL AS ATTRIBUTE1
                     , NULL AS ATTRIBUTE2
                     , NULL AS ATTRIBUTE3
                     , NULL AS ATTRIBUTE4
                     , NULL AS ATTRIBUTE5
                     , NULL AS ATTRIBUTE6
                     , NULL AS ATTRIBUTE7
                     , NULL AS ATTRIBUTE8
                     , NULL AS ATTRIBUTE9
                     , NULL AS ATTRIBUTE10
                     , A.CELL_PROD_SITE_ID
                  FROM SALES_PLAN_TEMP_81 A
                     , SCM_SYS_CALENDAR_M B
                     , (SELECT *
                           FROM SCM_MST_FUTURE_PRICE_C
                          WHERE DIVISION_ID  = '81'
                            AND VERSION_NO   = C_SP_VERSION_81 ) IA
                 WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
                   AND A.DIVISION_ID       = IA.DIVISION_ID(+)
                   AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
                   AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
                   AND A.ITEM_ID           = IA.ITEM_ID(+)
                   AND A.DOM_EXP           = IA.DOM_EXP(+)
                   AND A.FCST_TYPE         = IA.FCST_TYPE(+)
                   AND A.INCOTERMS         = IA.INCOTERMS(+)
                   AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
                   AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
                   AND IA.MEASURE(+)       = 'LOC'
                   AND A.DIVISION_ID       = '81'
                   /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
                   AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
                   AND A.MEASURE           = 'RTF_SYS_RP'

                   AND A.SCM_SITE_ID IN (SELECT SEGMENT2
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                             AND VALID_YN     = 'Y' )
                UNION ALL
                /* USD */
                SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.SCM_SITE_ID
                     , A.ITEM_ID
                     , A.DOM_EXP
                     , A.FCST_TYPE
                     , A.INCOTERMS
                     , 'SalesAmt_USD' AS MEASURE
                     , A.PLANT_SITE_ID
                     , A.YYYYMMDD
                     , IA.CURRENCY
                     , ROUND(A.QTY * NVL(IA.PRICE, 0), 5) AS QTY
                     , A.CREATED_BY
                     , A.CREATION_DATE
                     , 'system' AS LAST_UPDATED_BY
                     , SYSDATE AS LAST_UPDATE_DATE
                     , NULL AS ATTRIBUTE1
                     , NULL AS ATTRIBUTE2
                     , NULL AS ATTRIBUTE3
                     , NULL AS ATTRIBUTE4
                     , NULL AS ATTRIBUTE5
                     , NULL AS ATTRIBUTE6
                     , NULL AS ATTRIBUTE7
                     , NULL AS ATTRIBUTE8
                     , NULL AS ATTRIBUTE9
                     , NULL AS ATTRIBUTE10
                     , A.CELL_PROD_SITE_ID
                  FROM SALES_PLAN_TEMP_81 A
                     , SCM_SYS_CALENDAR_M B
                     , (SELECT *
                           FROM SCM_MST_FUTURE_PRICE_C
                          WHERE DIVISION_ID  = '81'
                            AND VERSION_NO   = C_SP_VERSION_81 ) IA
                 WHERE B.BASIS_YYYYMMDD    = A.YYYYMMDD
                   AND A.DIVISION_ID       = IA.DIVISION_ID(+)
                   AND A.PROJECT_CODE      = IA.PROJECT_CODE(+)
                   AND A.SCM_SITE_ID       = IA.SCM_SITE_ID(+)
                   AND A.ITEM_ID           = IA.ITEM_ID(+)
                   AND A.DOM_EXP           = IA.DOM_EXP(+)
                   AND A.FCST_TYPE         = IA.FCST_TYPE(+)
                   AND A.INCOTERMS         = IA.INCOTERMS(+)
                   AND A.PLANT_SITE_ID     = IA.PLANT_SITE_ID(+)
                   AND B.BASIS_START_DATE  = IA.YYYYMMDD(+)
                   AND IA.MEASURE(+)       = 'USD'
                   AND A.DIVISION_ID       = '81'
                   /* [E20260630-000725]_현업사용자가 보이는 수량으로 계산할 수있도록 변경한다 [RTF_SYS_RP] 로 계산하는것으로 변경한다 원소스 주석처리 (START)
                   AND A.MEASURE           = 'RTF_SCP'   [C20201208-000087] ESS 'RTF'(RTF_MKT) -> 'RTF_SYS_RP'(RTF_SCP) 적용 */
                   AND A.MEASURE           = 'RTF_SYS_RP'

                   AND A.SCM_SITE_ID IN (SELECT SEGMENT2
                                            FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                           WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                             AND VALID_YN     = 'Y' )
            )
            , FINAL_DATA AS (
                SELECT *
                  FROM SALES_PLAN_TEMP_81    /* 수량 */
                UNION ALL
                SELECT *
                  FROM SALES_PLAN_TEMP_81_2  /* 금액 */
            )
            SELECT DIVISION_ID
                 , C_SP_VERSION_81 AS VERSION_NO
                 , 'SP_W' AS CUTOFF_TYPE
                 , P_CUTOFF_YYYYMMDD_81 AS CUTOFF_YYYYMMDD
                 , PROJECT_CODE
                 , SCM_SITE_ID
                 , ITEM_ID
                 , DOM_EXP
                 , FCST_TYPE
                 , INCOTERMS
                 , MEASURE
                 , PLANT_SITE_ID
                 , YYYYMMDD
                 , CURRENCY
                 , QTY
                 , CREATED_BY
                 , CREATION_DATE
                 , LAST_UPDATED_BY
                 , SYSDATE AS LAST_UPDATE_DATE
                 , ATTRIBUTE1
                 , ATTRIBUTE2
                 , ATTRIBUTE3
                 , ATTRIBUTE4
                 , ATTRIBUTE5
                 , ATTRIBUTE6
                 , ATTRIBUTE7
                 , ATTRIBUTE8
                 , ATTRIBUTE9
                 , ATTRIBUTE10
                 , CELL_PROD_SITE_ID
              FROM FINAL_DATA;

            V_COUNT := 0;
            S_COUNT := 0;
            V_CNT   := 0;
            SELECT COUNT(DISTINCT SCM_SITE_ID)
              INTO V_CNT
              FROM GT_DPSPCQB_AFTER_RTF_81;
            DBMS_OUTPUT.PUT_LINE(V_CNT);

            V_I := 1;
            WHILE V_I <= V_CNT LOOP
                V_SITE_ID := '';
                BEGIN
                    SELECT SCM_SITE_ID
                      INTO V_SITE_ID
                      FROM (SELECT ROW_NUMBER() OVER(ORDER BY SCM_SITE_ID) AS SEQ
                                  , SCM_SITE_ID
                               FROM GT_DPSPCQB_AFTER_RTF_81
                              GROUP BY SCM_SITE_ID ) IA
                     WHERE IA.SEQ = V_I;
                EXCEPTION WHEN NO_DATA_FOUND THEN
                    V_SITE_ID := NULL;
                END;

                SELECT COUNT(*)
                  INTO V_COUNT
                  FROM GT_DPSPCQB_AFTER_RTF_81
                 WHERE DIVISION_ID  = '81'
                   AND MEASURE      = 'RTF_SYS_RP'
                   AND SCM_SITE_ID  = V_SITE_ID;

                IF (V_COUNT = 0) THEN
                    SELECT COUNT(*)
                      INTO S_COUNT
                      FROM GT_DPSPCQB_AFTER_RTF_81
                     WHERE DIVISION_ID  = '81'
                       AND SCM_SITE_ID  = V_SITE_ID
                       AND MEASURE      = 'RTF';

                    IF (S_COUNT > 0) THEN
                        UPDATE GT_DPSPCQB_AFTER_RTF_81
                           SET MEASURE = 'RTF_SYS_RP'
                         WHERE DIVISION_ID  = '81'
                           AND SCM_SITE_ID  = V_SITE_ID
                           AND MEASURE      = 'RTF';
                        DBMS_OUTPUT.PUT_LINE(V_SITE_ID);
                    END IF;
                END IF;

                V_I := V_I + 1;
            END LOOP;

            IF (V_CNT > 0) THEN
                DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A023: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);
                DELETE
                  FROM DM_PLN_SALES_PLAN_C
                 WHERE DIVISION_ID  = '81'
                   AND VERSION_NO   = C_SP_VERSION_81
                   AND SCM_SITE_ID IN (SELECT SEGMENT2
                                          FROM SCM_ADM_LOOKUP_MASTER_DETAIL
                                         WHERE LOOKUP_TYPE  = 'DM_NET_DEMAND_EXCEPTION'
                                           AND VALID_YN     = 'Y' )
                   AND SCM_SITE_ID IN (SELECT SCM_SITE_ID
                                          FROM GT_DPSPCQB_AFTER_RTF_81
                                         GROUP BY SCM_SITE_ID )
                   AND MEASURE IN ('RTF','RTF_SCP','RTF_SYS_RP','SalesAmt_KRW','SalesAmt_LOC','SalesAmt_USD');

                INSERT
                  INTO DM_PLN_SALES_PLAN_C
                     ( DIVISION_ID
                     , VERSION_NO
                     , CUTOFF_TYPE
                     , CUTOFF_YYYYMMDD
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , CELL_PROD_SITE_ID
                     , YYYYMMDD
                     , CURRENCY
                     , QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , ATTRIBUTE1
                     , ATTRIBUTE2
                     , ATTRIBUTE3
                     , ATTRIBUTE4
                     , ATTRIBUTE5
                     , ATTRIBUTE6
                     , ATTRIBUTE7
                     , ATTRIBUTE8
                     , ATTRIBUTE9
                     , ATTRIBUTE10 )
                SELECT DIVISION_ID
                     , VERSION_NO
                     , CUTOFF_TYPE
                     , CUTOFF_YYYYMMDD
                     , PROJECT_CODE
                     , SCM_SITE_ID
                     , ITEM_ID
                     , DOM_EXP
                     , FCST_TYPE
                     , INCOTERMS
                     , MEASURE
                     , PLANT_SITE_ID
                     , CELL_PROD_SITE_ID
                     , YYYYMMDD
                     , CURRENCY
                     , QTY
                     , CREATED_BY
                     , CREATION_DATE
                     , LAST_UPDATED_BY
                     , LAST_UPDATE_DATE
                     , ATTRIBUTE1
                     , ATTRIBUTE2
                     , ATTRIBUTE3
                     , ATTRIBUTE4
                     , ATTRIBUTE5
                     , ATTRIBUTE6
                     , ATTRIBUTE7
                     , ATTRIBUTE8
                     , ATTRIBUTE9
                     , ATTRIBUTE10
                  FROM GT_DPSPCQB_AFTER_RTF_81;
            END IF;
        END IF;
        /* 3-END */

        DBMS_OUTPUT.PUT_LINE(V_PROGRAM_NAME || ' A024: DIVISION_ID: ' || P_DIVISION_ID || ' / SP_W버전: ' || V_VER_RETURN_NO);

        /* (원본 #T3_MKT_FCST / #T3_PRICE DROP-if-exists : 리네임 이전 obsolete temp 정리 -> Oracle GTT 자동관리로 불요) */

        /* [E20250529-001289] SALES PLAN CUTOFF 완료 후 메일링 */
        PR_DM_IRREGULAR_SALES_PLAN_CUTOFF_MAIL_SEND(P_DIVISION_ID, P_CREATION_TYPE);

    /*------------------------------------------------------------------------------------------ */
    EXCEPTION
    /*------------------------------------------------------------------------------------------ */
    WHEN OTHERS THEN
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE;
        D_EVENT_DATE  := SYSDATE;
        DBMS_OUTPUT.PUT_LINE('[' || SQLCODE || ']' || SQLERRM);   /* 에러메시지 DISPLAY */

        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE
                           , JSON_OBJECT('p_division_id' VALUE P_DIVISION_ID, 'p_cutoff_yyyymmdd' VALUE P_CUTOFF_YYYYMMDD, 'p_creation_type' VALUE P_CREATION_TYPE RETURNING VARCHAR2(4000 CHAR))
                           , SQLCODE, SQLERRM, DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);

        RAISE_APPLICATION_ERROR(-20001, '[' || V_PROGRAM_NAME || '] SQLCODE=' || SQLCODE || ' / SQLERRM=' || SQLERRM || ' / ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '@p_division_id : ' || RTRIM(LTRIM(P_DIVISION_ID));
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE
-- ##### END PROCEDURE PR_DM_PLN_SALES_PLAN_C_QTY_BALANCE_CREATE

-- ##### START PROCEDURE PR_DM_PLN_SALES_PLAN_RESULT_MOVE
CREATE OR REPLACE PROCEDURE           "PR_DM_PLN_SALES_PLAN_RESULT_MOVE" 
(
    P_DIVISION_ID  IN VARCHAR2
)
/* ============================================================
 * Program ID   : PR_DM_PLN_SALES_PLAN_RESULT_MOVE
 * Description  :
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2018.03.29    JHBAEK         Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 *                              [DM_PLN_MKT_FCST] -> [DM_PLN_MKT_FCST_RESULT] 테이블에 자료(과거 1주일) INSERT PROCEDURE
 *                              WEEKLY RUNNNG.
 * 2019.07.12    KHSONG         [CSR ID:4023158] 'RTF_SYS_RP' MEASURE 추가
 * 2020.02.13    HWI1993        COMPANY_ID 추가 안되서 오류발생
 * 2020.03.09    KHSONG         TMM_FCST ADD
 * 2022.04.07    hwi1993        GM JV 작업
 * 2025.04.22    JSSBAE         [E20250401-000548]_선감지(SMS) 대상 기준 정리
 * 2025.06.23    KANG.H.J       [PJ2025-50188] 매출실적 CELL_PROD_SITE_ID 추가
 * 2026.07.06    ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_DM_PLN_SALES_PLAN_RESULT_MOVE';
    V_LOG_TYPE      VARCHAR2(30 CHAR);
    V_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    V_EVENT_DATE    DATE;
    V_DIVISION_ID   VARCHAR2(4000 CHAR);
BEGIN

    V_DIVISION_ID := NULL;

    /* START LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    V_LOG_MESSAGE := NULL;

    BEGIN

        IF P_DIVISION_ID = 'ALL' THEN
            V_DIVISION_ID := '';
        ELSE
            V_DIVISION_ID := P_DIVISION_ID;
        END IF;

        /* RESULT DATA DELETE */
        DELETE
          FROM DM_PLN_SALES_PLAN_RESULT L
         WHERE L.DIVISION_ID LIKE '%' || V_DIVISION_ID || '%'
           AND L.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
           AND L.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 2, 'YYYYMMDD')
           AND L.MEASURE IN ('MKT_FCST', 'CUST_FCST', 'RTF_SYS_RP', 'TMM_FCST');

        /* RESULT DATA INSERT */
        INSERT
          INTO DM_PLN_SALES_PLAN_RESULT
             ( DIVISION_ID
             , PROJECT_CODE
             , SCM_SITE_ID
             , ITEM_ID
             , DOM_EXP
             , FCST_TYPE
             , INCOTERMS
             , MEASURE
             , PLANT_SITE_ID
             , YYYYMMDD
             , CURRENCY
             , QTY
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , COMPANY_ID
             , CELL_PROD_SITE_ID )
        SELECT A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , NVL(NULLIF(RTRIM(A.CURRENCY),''), '/') AS CURRENCY
             , SUM(A.QTY) AS QTY
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , SYSDATE
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , ' ' AS COMPANY_ID
             , A.CELL_PROD_SITE_ID
          FROM DM_PLN_SALES_PLAN A
             , SCM_MST_DIVISION B
         WHERE A.DIVISION_ID = B.DIVISION_ID
           AND B.DIVISION_ID LIKE '%' || V_DIVISION_ID || '%'
           AND 1 = 1
           AND A.YYYYMMDD <  TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7, 'YYYYMMDD')
           AND A.YYYYMMDD >= TO_CHAR(FN_NEXT_DAY(SYSDATE, 'MON') - 7 * 2, 'YYYYMMDD')
           AND A.MEASURE IN ('MKT_FCST', 'CUST_FCST', 'RTF_SYS_RP', 'TMM_FCST')
      GROUP BY A.DIVISION_ID
             , A.PROJECT_CODE
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.DOM_EXP
             , A.FCST_TYPE
             , A.INCOTERMS
             , A.MEASURE
             , A.PLANT_SITE_ID
             , A.YYYYMMDD
             , NVL(A.CURRENCY, '-')
             , A.CREATED_BY
             , A.CREATION_DATE
             , A.LAST_UPDATED_BY
             , A.ATTRIBUTE1
             , A.ATTRIBUTE2
             , A.ATTRIBUTE3
             , A.ATTRIBUTE4
             , A.ATTRIBUTE5
             , A.ATTRIBUTE6
             , A.ATTRIBUTE7
             , A.ATTRIBUTE8
             , A.ATTRIBUTE9
             , A.ATTRIBUTE10
             , A.CELL_PROD_SITE_ID;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            V_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    END;

    /* END LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

END;
/
SHOW ERRORS PROCEDURE PR_DM_PLN_SALES_PLAN_RESULT_MOVE
-- ##### END PROCEDURE PR_DM_PLN_SALES_PLAN_RESULT_MOVE

-- ##### START PROCEDURE PR_SCM_ADM_DEPT_CHANGED_AUTH_SYNC
CREATE OR REPLACE PROCEDURE           "PR_SCM_ADM_DEPT_CHANGED_AUTH_SYNC" 
/* ============================================================
 * Program ID   : PR_SCM_ADM_FP_AUTH_SYNC
 * Description  : FP 권한과 SCM 권한 동기화
 * Program History
 *------------------------------------------------------------
 *   Date         In Charge      Description
 *------------------------------------------------------------
 * 2023.03.20     FP Pjt.        FP 권한과 SCM 권한 동기화
 * 2023.04.24     FP Pjt.        EE 사업부 추가
 * 2026.07.06     ZIONEX         [PJ202650304]  NextSCM Migration
 * ============================================================ */
AS
    V_USER_ID       VARCHAR2(30 CHAR);    /* 사용자ID */
    V_USER_NAME     VARCHAR2(150 CHAR);   /* 사용자명 */
    V_REMAIN_DAY    VARCHAR2(30 CHAR);    /* 권한회수까지 남은 일수 */
    V_DBNAME        VARCHAR2(50 CHAR);

    /* LOG 용 변수 설정 */
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_ADM_DEPT_CHANGED_AUTH_SYNC';
    V_LOG_TYPE      VARCHAR2(30 CHAR);    /* START/END/ERROR/... */
    N_LOG_COUNT     NUMBER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;

    T_GROUP_ID      VARCHAR2(20 CHAR);
    T_DIVISION_ID   VARCHAR2(30 CHAR);
BEGIN

    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    /* fp 권한 없는 scm 권한 delete */
    DELETE
/* 2026.09.30 AJS 수정 (START) */
--      FROM TB_FX_USERGROUPAUTHEXTENTION E
--     WHERE E.GROUPID IN ('FP Viewer', 'FP Planner')
--       AND E.CODE NOT LIKE 'EE%'
      FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M E
     WHERE E.USER_GR_ID IN ('FP Viewer', 'FP Planner')
       AND E.UNIT_ID NOT LIKE 'EE%'
/* 2026.09.30 AJS 수정 (END) */
       AND NOT EXISTS (SELECT 1
                         FROM TH_UIS_USER_INSTANCE_RELATE_SN UIR
                            , TH_UIS_ROLE_INSTANCE_SN RI
                            , TH_UIS_ROLE_INSTANCE_RELATE_SN RIR
                            , SCM_FACTORY_M_SN F
                        WHERE UIR.ROLE_ID = RI.ROLE_ID
                          AND RIR.ROLE_ID = RI.ROLE_ID
                          AND RIR.COMPANY_ID = F.COMPANY_ID
                          AND RIR.FACTORY_ID = F.FACTORY_ID
                          AND UIR.USE_AT_FLAG = 'Y'
                          AND RIR.USE_AT_FLAG = 'Y'
/* 2026.09.30 AJS 수정 (START) */
--                          AND UIR.USER_ID = E.USERID
--                          AND UIR.SAVE_FLAG = CASE WHEN E.GROUPID = 'FP Planner' THEN 'Y' ELSE 'N' END
--                          AND RIR.DIVISION_ID = E.CODE);
                          AND UIR.USER_ID = E.USER_ID
                          AND UIR.SAVE_FLAG = CASE WHEN E.USER_GR_ID = 'FP Planner' THEN 'Y' ELSE 'N' END
                          AND RIR.DIVISION_ID = E.UNIT_ID);
/* 2026.09.30 AJS 수정 (END) */

    /* EE 사업부 삭제 */
    DELETE
/* 2026.09.30 AJS 수정 (START) */
--      FROM TB_FX_USERGROUPAUTHEXTENTION E
--     WHERE E.GROUPID IN ('FP Viewer', 'FP Planner')
--       AND E.CODE LIKE 'EE%'
      FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M E
     WHERE E.USER_GR_ID IN ('FP Viewer', 'FP Planner')
       AND E.UNIT_ID LIKE 'EE%'
/* 2026.09.30 AJS 수정 (END) */
       AND NOT EXISTS (SELECT 1
                         FROM TH_UIS_USER_INSTANCE_RELATE_SN UIR
                            , TH_UIS_ROLE_INSTANCE_SN RI
                            , TH_UIS_ROLE_INSTANCE_RELATE_SN RIR
                            , SCM_FACTORY_M_SN F
                        WHERE UIR.ROLE_ID = RI.ROLE_ID
                          AND RIR.ROLE_ID = RI.ROLE_ID
                          AND RIR.COMPANY_ID = F.COMPANY_ID
                          AND RIR.FACTORY_ID = F.FACTORY_ID
                          AND UIR.USE_AT_FLAG = 'Y'
                          AND RIR.USE_AT_FLAG = 'Y'
                          AND F.SHOP_GROUP_ID = 'E'
/* 2026.09.30 AJS 수정 (START) */
--                          AND UIR.USER_ID = E.USERID
--                          AND UIR.SAVE_FLAG = CASE WHEN E.GROUPID = 'FP Planner' THEN 'Y' ELSE 'N' END
                          AND UIR.USER_ID = E.USER_ID
                          AND UIR.SAVE_FLAG = CASE WHEN E.USER_GR_ID = 'FP Planner' THEN 'Y' ELSE 'N' END
/* 2026.09.30 AJS 수정 (END) */
                          AND CASE WHEN F.SHOP_GROUP_ID = 'E' THEN (CASE WHEN F.DIVISION_ID IN ('40', '81', '82') THEN 'EE' ELSE 'EE' || SUBSTR(F.DIVISION_ID, 3, 3) END)
/* 2026.09.30 AJS 수정 (START) */
--                                   ELSE RIR.DIVISION_ID END = E.CODE);
                                   ELSE RIR.DIVISION_ID END = E.UNIT_ID);
/* 2026.09.30 AJS 수정 (END) */


/* 2026.09.30 AJS 수정 (START) */
--    UPDATE TB_FX_USERGROUPINFO UG
--       SET UG.USEYN          = 'N'
--         , UG.UPDATEUSERID   = 'scm_batch'
--         , UG.UPDATEDATETIME = SYSDATE
--     WHERE UG.GROUPID IN ('FP Viewer', 'FP Planner')
--       AND UG.USEYN = 'Y'
    UPDATE SCM_ADM_USER_GR_MPG_M UG
       SET UG.USE_YN         = 'N'
         , UG.LAST_UPDATED_BY   = 'scm_batch'
         , UG.LAST_UPDATE_DATE = SYSDATE
     WHERE UG.USER_GR_ID IN ('FP Viewer', 'FP Planner')
       AND UG.USE_YN = 'Y'
/* 2026.09.30 AJS 수정 (END) */
       AND NOT EXISTS (SELECT 1
/* 2026.09.30 AJS 수정 (START) */
--                         FROM TB_FX_USERGROUPAUTHEXTENTION X
--                        WHERE X.USERID = UG.USERID
--                          AND X.GROUPID = UG.GROUPID);
                         FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M X
                        WHERE X.USER_ID = UG.USER_ID
                          AND X.USER_GR_ID = UG.USER_GR_ID);
/* 2026.09.30 AJS 수정 (END) */


    UPDATE SCM_MST_AUTH_REQUEST R
       SET R.APPROVAL_RESULT  = 'REJECT'
         , R.REJECT_REASON    = 'DEPT_CHANGED_AUTH_DELETE'
         , R.LAST_UPDATED_BY  = 'scm_batch'
         , R.LAST_UPDATE_DATE = SYSDATE
     WHERE R.GROUP_ID IN ('FP Viewer', 'FP Planner')
       AND R.APPROVAL_RESULT != 'REJECT'
       AND NOT EXISTS (SELECT 1
                         FROM TH_UIS_USER_INSTANCE_RELATE_SN UIR
                            , TH_UIS_ROLE_INSTANCE_SN RI
                            , TH_UIS_ROLE_INSTANCE_RELATE_SN RIR
                        WHERE UIR.ROLE_ID = RI.ROLE_ID
