         , X.CODE
         , '/'
         , CASE WHEN UPPER(X.GROUPID) LIKE '%VIEWER%' THEN 'N' ELSE 'Y' END   /* EDIT_YN : TO-BE 신설 필수 칸 */
         , 'Y'   /* USE_YN : TO-BE 신설 필수 칸 */
/* 2026.09.30 AJS 수정 (END) */
         , 'scm_batch'
         , SYSDATE
         , 'scm_batch'
         , SYSDATE
