         , '/'
         , CASE WHEN UPPER(X.GROUPID) LIKE '%VIEWER%' THEN 'N' ELSE 'Y' END   /* EDIT_YN : TO-BE 신설 필수 칸 */
         , 'Y'   /* USE_YN : TO-BE 신설 필수 칸 */
/* 2026.09.30 AJS 수정 (END) */
         , 'scm_batch'
         , SYSDATE
         , 'scm_batch'
         , SYSDATE
/* 2026.09.30 AJS 수정 (START) */
--         , ''
/* 2026.09.30 AJS 수정 (END) */
      FROM (SELECT DISTINCT UIR.USER_ID AS USERID
                 , CASE WHEN UIR.SAVE_FLAG = 'Y' THEN 'FP Planner' ELSE 'FP Viewer' END AS GROUPID
                 , CASE WHEN F.SHOP_GROUP_ID = 'E' THEN (CASE WHEN F.DIVISION_ID IN ('40', '81', '82') THEN 'EE' ELSE 'EE' || SUBSTR(F.DIVISION_ID, 3, 3) END)
                        ELSE RIR.DIVISION_ID END AS CODE
              FROM TH_UIS_USER_INSTANCE_RELATE_SN UIR
                 , TH_UIS_ROLE_INSTANCE_SN RI
                 , TH_UIS_ROLE_INSTANCE_RELATE_SN RIR
                 , SCM_FACTORY_M_SN F
             WHERE UIR.ROLE_ID = RI.ROLE_ID
               AND RIR.ROLE_ID = RI.ROLE_ID
               AND RIR.COMPANY_ID = F.COMPANY_ID
               AND RIR.FACTORY_ID = F.FACTORY_ID
               AND UIR.USE_AT_FLAG = 'Y'
               AND RIR.USE_AT_FLAG = 'Y'
               AND F.SHOP_GROUP_ID = 'E') X    /* 전극만 추가 */
/* 2026.09.30 AJS 수정 (START) */
--         , TB_FX_USERGROUPINFO UG
--         , TB_FX_USERGROUPAUTHEXTENTION UGA
--     WHERE X.USERID = UG.USERID
--       AND X.GROUPID = UG.GROUPID
--       AND X.USERID = UGA.USERID(+)
--       AND X.GROUPID = UGA.GROUPID(+)
--       AND X.CODE = UGA.CODE(+)
--       AND UGA.GROUPID IS NULL;
         , SCM_ADM_USER_GR_MPG_M UG
         , SCM_ADM_USER_GR_UNIT_AUTH_MPG_M UGA
     WHERE X.USERID = UG.USER_ID
       AND X.GROUPID = UG.USER_GR_ID
       AND X.USERID = UGA.USER_ID(+)
       AND X.GROUPID = UGA.USER_GR_ID(+)
       AND X.CODE = UGA.UNIT_ID(+)
       AND UGA.USER_GR_ID IS NULL;
/* 2026.09.30 AJS 수정 (END) */


/* 2026.09.30 AJS 수정 (START) */
--    UPDATE TB_FX_USERGROUPINFO UG
--       SET UG.USEYN          = 'Y'
--         , UG.UPDATEUSERID   = 'scm_batch'
--         , UG.UPDATEDATETIME = SYSDATE
--     WHERE UG.GROUPID IN ('FP Viewer', 'FP Planner')
--       AND UG.USEYN = 'N'
    UPDATE SCM_ADM_USER_GR_MPG_M UG
       SET UG.USE_YN         = 'Y'
         , UG.LAST_UPDATED_BY   = 'scm_batch'
         , UG.LAST_UPDATE_DATE = SYSDATE
     WHERE UG.USER_GR_ID IN ('FP Viewer', 'FP Planner')
       AND UG.USE_YN = 'N'
/* 2026.09.30 AJS 수정 (END) */
       AND EXISTS (SELECT 1
/* 2026.09.30 AJS 수정 (START) */
--                     FROM TB_FX_USERGROUPAUTHEXTENTION X
--                    WHERE X.USERID = UG.USERID
--                      AND X.GROUPID = UG.GROUPID);
                     FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M X
                    WHERE X.USER_ID = UG.USER_ID
                      AND X.USER_GR_ID = UG.USER_GR_ID);
/* 2026.09.30 AJS 수정 (END) */

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
        /* SQLERRM 은 정적 INSERT VALUES 에 직접 쓰면 ORA-00984 → 변수에 먼저 담음 */
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := SUBSTR(V_PROGRAM_NAME || 'ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
        INSERT
          INTO SCM_SYS_LOG_BATCH
             ( PROGRAM_NAME
             , LOG_TYPE
             , LOG_COUNT
             , LOG_MESSAGE
             , DESCRIPTION
             , EVENT_DATE
             , CREATION_DATE
             , CREATED_BY
             , LAST_UPDATE_DATE
             , LAST_UPDATED_BY )
        VALUES ( V_PROGRAM_NAME
             , 'ERROR'
             , NULL
             , V_LOG_MESSAGE
             , V_DESCRIPTION
             , SYSDATE
             , SYSDATE
             , V_PROGRAM_NAME
             , SYSDATE
             , V_PROGRAM_NAME );
        COMMIT;
        /*         *   SELECT 'F' AS result_code;
         *   SELECT '[' + CONVERT(nvarchar(10), ERROR_NUMBER()) + ']' + ERROR_MESSAGE(); */
END;
/
SHOW ERRORS PROCEDURE PR_SCM_ADM_DEPT_CHANGED_AUTH_SYNC
-- ##### END PROCEDURE PR_SCM_ADM_DEPT_CHANGED_AUTH_SYNC

-- ##### START PROCEDURE PR_SCM_MST_PROJECT_SCHEDULE
CREATE OR REPLACE PROCEDURE PR_SCM_MST_PROJECT_SCHEDULE
/* ============================================================
 * Program ID   : PR_SCM_MST_PROJECT_SCHEDULE
 * Description  : GPLM Project Schedule I/F
 * Program History
 *------------------------------------------------------------
 * Date          In Charge      Description
 *------------------------------------------------------------
 * 2018. 1. 10   Kim Jaejung    Initial Release [PJ20170278] 전지본부 자동차 GSCM(DM/SCP) 구축 프로젝트
 * 2026.07.06    ZIONEX         [PJ202650304] NextSCM Migration
 * ============================================================ */
IS
    /* LOG 용 변수 설정 */
    V_BATCH_USER    VARCHAR2(150 CHAR) := 'scm_batch';
    V_PROGRAM_NAME  VARCHAR2(150 CHAR) := 'PR_SCM_MST_PROJECT_SCHEDULE';
    V_LOG_TYPE      VARCHAR2(30 CHAR);          /* START/END/ERROR/... */
    N_LOG_COUNT     PLS_INTEGER := 0;
    V_LOG_MESSAGE   VARCHAR2(1000 CHAR);
    V_DESCRIPTION   VARCHAR2(500 CHAR);
    D_EVENT_DATE    DATE;
    V_IFSEQNO       VARCHAR2(30 CHAR);
    N_HISTORY_SEQ   NUMBER(19);

    /* 지나간 배치까지 적용하기 위해 Cursor 로 처리 */
    CURSOR CUR_PROJECT IS
        SELECT IF_SEQ
          FROM XIF_PLM_PJT_SCHEDULE_R_SN
         WHERE ATTR_10 = 'P'
         GROUP BY IF_SEQ
         ORDER BY IF_SEQ ASC;
BEGIN
    /* 시작 LOG */
    V_LOG_TYPE    := 'START';
    V_LOG_MESSAGE := '########## Start of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

    BEGIN
        /* 인터페이스 테이블 처리 ROW UPDATE */
        UPDATE XIF_PLM_PJT_SCHEDULE_R_SN
           SET ATTR_10 = 'P'
         WHERE NVL(ATTR_10, 'N') = 'N';

        /* History 데이터 처리를 위한 TEMP Table 삭제 및 생성 (Oracle: GTT GT_SMPS_SCHEDULE 스냅샷) */
        /* 원본 #temp 는 매 실행 DROP 후 SELECT INTO 재생성(빈 상태) → PRESERVE GTT 는 첫 적재 전 비운다 */
        DELETE
          FROM GT_SMPS_SCHEDULE;
        INSERT
          INTO GT_SMPS_SCHEDULE
        SELECT DIVISION_ID
             , PROJECT_CODE
             , PROJECT_VER_SEQ
             , CV_APP_PLAN_START_DATE
             , CV_APP_PLAN_END_DATE
             , CV_PLAN_START_DATE
             , CV_PLAN_END_DATE
             , CV_ACTUAL_START_DATE
             , CV_ACTUAL_END_DATE
             , DV_APP_PLAN_START_DATE
             , DV_APP_PLAN_END_DATE
             , DV_PLAN_START_DATE
             , DV_PLAN_END_DATE
             , DV_ACTUAL_START_DATE
             , DV_ACTUAL_END_DATE
             , PD_APP_PLAN_START_DATE
             , PD_APP_PLAN_END_DATE
             , PD_PLAN_START_DATE
             , PD_PLAN_END_DATE
             , PD_ACTUAL_START_DATE
             , PD_ACTUAL_END_DATE
             , PV_APP_PLAN_START_DATE
             , PV_APP_PLAN_END_DATE
             , PV_PLAN_START_DATE
             , PV_PLAN_END_DATE
             , PV_ACTUAL_START_DATE
             , PV_ACTUAL_END_DATE
             , VALID_YN
             , CREATION_DATE
             , LAST_UPDATE_DATE
          FROM SCM_MST_PROJECT_SCHEDULE;

        FOR R IN CUR_PROJECT LOOP
            V_IFSEQNO := R.IF_SEQ;

            MERGE INTO SCM_MST_PROJECT_SCHEDULE A
            USING (SELECT DISTINCT /* PR_SCM_MST_PROJECT_SCHEDULE */
                          A0.PROJECT_ID
                        , B0.DIVISION_ID AS DIVISION_ID
                        , NVL(B0.PROJECT_VER_SEQ, '/') AS PROJECT_VER_SEQ
                        , CASE A0.IF_TYPE WHEN 'D' THEN 'N' ELSE 'Y' END AS VALID_YN
                        , A0.CV_APP_PLAN_START_DATE
                        , A0.CV_APP_PLAN_END_DATE
                        , A0.CV_PLAN_START_DATE
                        , A0.CV_PLAN_END_DATE
                        , A0.CV_ACTUAL_START_DATE
                        , A0.CV_ACTUAL_END_DATE
                        , A0.DV_APP_PLAN_START_DATE
                        , A0.DV_APP_PLAN_END_DATE
                        , A0.DV_PLAN_START_DATE
                        , A0.DV_PLAN_END_DATE
                        , A0.DV_ACTUAL_START_DATE
                        , A0.DV_ACTUAL_END_DATE
                        , A0.PD_APP_PLAN_START_DATE
                        , A0.PD_APP_PLAN_END_DATE
                        , A0.PD_PLAN_START_DATE
                        , A0.PD_PLAN_END_DATE
                        , A0.PD_ACTUAL_START_DATE
                        , A0.PD_ACTUAL_END_DATE
                        , A0.PV_APP_PLAN_START_DATE
                        , A0.PV_APP_PLAN_END_DATE
                        , A0.PV_PLAN_START_DATE
                        , A0.PV_PLAN_END_DATE
                        , A0.PV_ACTUAL_START_DATE
                        , A0.PV_ACTUAL_END_DATE
                     FROM XIF_PLM_PJT_SCHEDULE_R_SN A0
                        , (SELECT * FROM SCM_MST_PROJECT_MAPPING) B0
                    /* ★MSSQL nchar 는 = 비교에서 후행 공백을 무시한다(blank-padded). Oracle VARCHAR2 는 구분하므로 RTRIM 으로 원본과 같은 동작을 복원한다 — 없으면 이 조인이 0행이 되어 프로시저가 무동작한다. 2026-08-20 실측 : 조인 MSSQL 5,124,239행 vs ORACLE 0행 */
                    WHERE RTRIM(A0.PROJECT_ID) = RTRIM(B0.GPLM_PROJECT_CODE)
                      AND A0.IF_SEQ     = V_IFSEQNO
                      AND A0.ATTR_10    = 'P'
                      /* 김춘동 임시 처리 2025-11-30 */
                      AND A0.CV_APP_PLAN_START_DATE IS NOT NULL) B
            ON (A.DIVISION_ID  = B.DIVISION_ID
                AND A.PROJECT_CODE = B.PROJECT_ID
                /*AND A.project_ver_seq   =  B.project_ver_seq 수정 필요*/
               )
            WHEN MATCHED THEN
                UPDATE
                   SET A.CV_APP_PLAN_START_DATE = B.CV_APP_PLAN_START_DATE
                     , A.CV_APP_PLAN_END_DATE   = B.CV_APP_PLAN_END_DATE
                     , A.CV_PLAN_START_DATE     = B.CV_PLAN_START_DATE
                     , A.CV_PLAN_END_DATE       = B.CV_PLAN_END_DATE
                     , A.CV_ACTUAL_START_DATE   = B.CV_ACTUAL_START_DATE
                     , A.CV_ACTUAL_END_DATE     = B.CV_ACTUAL_END_DATE
                     , A.DV_APP_PLAN_START_DATE = B.DV_APP_PLAN_START_DATE
                     , A.DV_APP_PLAN_END_DATE   = B.DV_APP_PLAN_END_DATE
                     , A.DV_PLAN_START_DATE     = B.DV_PLAN_START_DATE
                     , A.DV_PLAN_END_DATE       = B.DV_PLAN_END_DATE
                     , A.DV_ACTUAL_START_DATE   = B.DV_ACTUAL_START_DATE
                     , A.DV_ACTUAL_END_DATE     = B.DV_ACTUAL_END_DATE
                     , A.PD_APP_PLAN_START_DATE = B.PD_APP_PLAN_START_DATE
                     , A.PD_APP_PLAN_END_DATE   = B.PD_APP_PLAN_END_DATE
                     , A.PD_PLAN_START_DATE     = B.PD_PLAN_START_DATE
                     , A.PD_PLAN_END_DATE       = B.PD_PLAN_END_DATE
                     , A.PD_ACTUAL_START_DATE   = B.PD_ACTUAL_START_DATE
                     , A.PD_ACTUAL_END_DATE     = B.PD_ACTUAL_END_DATE
                     , A.PV_APP_PLAN_START_DATE = B.PV_APP_PLAN_START_DATE
                     , A.PV_APP_PLAN_END_DATE   = B.PV_APP_PLAN_END_DATE
                     , A.PV_PLAN_START_DATE     = B.PV_PLAN_START_DATE
                     , A.PV_PLAN_END_DATE       = B.PV_PLAN_END_DATE
                     , A.PV_ACTUAL_START_DATE   = B.PV_ACTUAL_START_DATE
                     , A.PV_ACTUAL_END_DATE     = B.PV_ACTUAL_END_DATE
                     , A.VALID_YN               = B.VALID_YN
                     , A.LAST_UPDATED_BY        = V_BATCH_USER
                     , A.LAST_UPDATE_DATE       = SYSDATE
            WHEN NOT MATCHED THEN
                INSERT ( DIVISION_ID
                       , PROJECT_CODE
                       , PROJECT_VER_SEQ
                       , CV_APP_PLAN_START_DATE
                       , CV_APP_PLAN_END_DATE
                       , CV_PLAN_START_DATE
                       , CV_PLAN_END_DATE
                       , CV_ACTUAL_START_DATE
                       , CV_ACTUAL_END_DATE
                       , DV_APP_PLAN_START_DATE
                       , DV_APP_PLAN_END_DATE
                       , DV_PLAN_START_DATE
                       , DV_PLAN_END_DATE
                       , DV_ACTUAL_START_DATE
                       , DV_ACTUAL_END_DATE
                       , PD_APP_PLAN_START_DATE
                       , PD_APP_PLAN_END_DATE
                       , PD_PLAN_START_DATE
                       , PD_PLAN_END_DATE
                       , PD_ACTUAL_START_DATE
                       , PD_ACTUAL_END_DATE
                       , PV_APP_PLAN_START_DATE
                       , PV_APP_PLAN_END_DATE
                       , PV_PLAN_START_DATE
                       , PV_PLAN_END_DATE
                       , PV_ACTUAL_START_DATE
                       , PV_ACTUAL_END_DATE
                       , VALID_YN
                       , CREATED_BY
                       , CREATION_DATE
                       , LAST_UPDATED_BY
                       , LAST_UPDATE_DATE )
                VALUES ( B.DIVISION_ID
                       , B.PROJECT_ID
                       , B.PROJECT_VER_SEQ
                       , B.CV_APP_PLAN_START_DATE
                       , B.CV_APP_PLAN_END_DATE
                       , B.CV_PLAN_START_DATE
                       , B.CV_PLAN_END_DATE
                       , B.CV_ACTUAL_START_DATE
                       , B.CV_ACTUAL_END_DATE
                       , B.DV_APP_PLAN_START_DATE
                       , B.DV_APP_PLAN_END_DATE
                       , B.DV_PLAN_START_DATE
                       , B.DV_PLAN_END_DATE
                       , B.DV_ACTUAL_START_DATE
                       , B.DV_ACTUAL_END_DATE
                       , B.PD_APP_PLAN_START_DATE
                       , B.PD_APP_PLAN_END_DATE
                       , B.PD_PLAN_START_DATE
                       , B.PD_PLAN_END_DATE
                       , B.PD_ACTUAL_START_DATE
                       , B.PD_ACTUAL_END_DATE
                       , B.PV_APP_PLAN_START_DATE
                       , B.PV_APP_PLAN_END_DATE
                       , B.PV_PLAN_START_DATE
                       , B.PV_PLAN_END_DATE
                       , B.PV_ACTUAL_START_DATE
                       , B.PV_ACTUAL_END_DATE
                       , B.VALID_YN
                       , V_BATCH_USER
                       , SYSDATE
                       , V_BATCH_USER
                       , SYSDATE );

            /* 처리 row 마킹 */
            UPDATE XIF_PLM_PJT_SCHEDULE_R_SN
               SET ATTR_10 = 'Y'
             WHERE IF_SEQ  = V_IFSEQNO
               AND ATTR_10 = 'P'
               /* ★MSSQL nchar 는 = 비교에서 후행 공백을 무시한다(blank-padded). Oracle VARCHAR2 는 구분하므로 RTRIM 으로 원본과 같은 동작을 복원한다 — 없으면 이 조인이 0행이 되어 프로시저가 무동작한다. 2026-08-20 실측 : 조인 MSSQL 5,124,239행 vs ORACLE 0행 */
               AND RTRIM(PROJECT_ID) IN (SELECT RTRIM(GPLM_PROJECT_CODE)
                                           FROM SCM_MST_PROJECT_MAPPING);

            /* --------------------------------------------------------- */
            /* Merge LOG */
            /* --------------------------------------------------------- */
            V_LOG_TYPE    := 'APPEND';
            V_LOG_MESSAGE := 'MERGE INTO scm_mst_project_schedule';
            V_DESCRIPTION := 'if_seq = ' || V_IFSEQNO;
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
            /* --------------------------------------------------------- */
        END LOOP;

        /* History 저장, history 생성 날짜와 기존 데이터 insert 날짜를 다르게 하기 위해 조인해서 처리 */
        N_HISTORY_SEQ := SEQ1_SCM_MST_PROJECT_SCHEDULE_H.NEXTVAL;
        INSERT
          INTO SCM_MST_PROJECT_SCHEDULE_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PROJECT_CODE
             , PROJECT_VER_SEQ
             , CV_APP_PLAN_START_DATE
             , CV_APP_PLAN_END_DATE
             , CV_PLAN_START_DATE
             , CV_PLAN_END_DATE
             , CV_ACTUAL_START_DATE
             , CV_ACTUAL_END_DATE
             , DV_APP_PLAN_START_DATE
             , DV_APP_PLAN_END_DATE
             , DV_PLAN_START_DATE
             , DV_PLAN_END_DATE
             , DV_ACTUAL_START_DATE
             , DV_ACTUAL_END_DATE
             , PD_APP_PLAN_START_DATE
             , PD_APP_PLAN_END_DATE
             , PD_PLAN_START_DATE
             , PD_PLAN_END_DATE
             , PD_ACTUAL_START_DATE
             , PD_ACTUAL_END_DATE
             , PV_APP_PLAN_START_DATE
             , PV_APP_PLAN_END_DATE
             , PV_PLAN_START_DATE
             , PV_PLAN_END_DATE
             , PV_ACTUAL_START_DATE
             , PV_ACTUAL_END_DATE
             , VALID_YN
             , CREATION_DATE
             , LAST_UPDATE_DATE
             , CREATED_BY
             , LAST_UPDATED_BY
             , HISTORY_CREATION_DATE )
        SELECT N_HISTORY_SEQ
             , A.DIVISION_ID
             , A.PROJECT_CODE
             , A.PROJECT_VER_SEQ
             , A.CV_APP_PLAN_START_DATE
             , A.CV_APP_PLAN_END_DATE
             , A.CV_PLAN_START_DATE
             , A.CV_PLAN_END_DATE
             , A.CV_ACTUAL_START_DATE
             , A.CV_ACTUAL_END_DATE
             , A.DV_APP_PLAN_START_DATE
             , A.DV_APP_PLAN_END_DATE
             , A.DV_PLAN_START_DATE
             , A.DV_PLAN_END_DATE
             , A.DV_ACTUAL_START_DATE
             , A.DV_ACTUAL_END_DATE
             , A.PD_APP_PLAN_START_DATE
             , A.PD_APP_PLAN_END_DATE
             , A.PD_PLAN_START_DATE
             , A.PD_PLAN_END_DATE
             , A.PD_ACTUAL_START_DATE
             , A.PD_ACTUAL_END_DATE
             , A.PV_APP_PLAN_START_DATE
             , A.PV_APP_PLAN_END_DATE
             , A.PV_PLAN_START_DATE
             , A.PV_PLAN_END_DATE
             , A.PV_ACTUAL_START_DATE
             , A.PV_ACTUAL_END_DATE
             , A.VALID_YN
             , A.CREATION_DATE
             , A.LAST_UPDATE_DATE
             , V_BATCH_USER
             , V_BATCH_USER
             , SYSDATE
          FROM (SELECT A.DIVISION_ID
                     , A.PROJECT_CODE
                     , A.PROJECT_VER_SEQ
                     , A.CV_APP_PLAN_START_DATE
                     , A.CV_APP_PLAN_END_DATE
                     , A.CV_PLAN_START_DATE
                     , A.CV_PLAN_END_DATE
                     , A.CV_ACTUAL_START_DATE
                     , A.CV_ACTUAL_END_DATE
                     , A.DV_APP_PLAN_START_DATE
                     , A.DV_APP_PLAN_END_DATE
                     , A.DV_PLAN_START_DATE
                     , A.DV_PLAN_END_DATE
                     , A.DV_ACTUAL_START_DATE
                     , A.DV_ACTUAL_END_DATE
                     , A.PD_APP_PLAN_START_DATE
                     , A.PD_APP_PLAN_END_DATE
                     , A.PD_PLAN_START_DATE
                     , A.PD_PLAN_END_DATE
                     , A.PD_ACTUAL_START_DATE
                     , A.PD_ACTUAL_END_DATE
                     , A.PV_APP_PLAN_START_DATE
                     , A.PV_APP_PLAN_END_DATE
                     , A.PV_PLAN_START_DATE
                     , A.PV_PLAN_END_DATE
                     , A.PV_ACTUAL_START_DATE
                     , A.PV_ACTUAL_END_DATE
                     , A.VALID_YN
                     , B.CREATION_DATE
                     , B.LAST_UPDATE_DATE
                  FROM (SELECT /* scm_mst_project_schedule_h */
                               DIVISION_ID
                             , PROJECT_CODE
                             , PROJECT_VER_SEQ
                             , CV_APP_PLAN_START_DATE
                             , CV_APP_PLAN_END_DATE
                             , CV_PLAN_START_DATE
                             , CV_PLAN_END_DATE
                             , CV_ACTUAL_START_DATE
                             , CV_ACTUAL_END_DATE
                             , DV_APP_PLAN_START_DATE
                             , DV_APP_PLAN_END_DATE
                             , DV_PLAN_START_DATE
                             , DV_PLAN_END_DATE
                             , DV_ACTUAL_START_DATE
                             , DV_ACTUAL_END_DATE
                             , PD_APP_PLAN_START_DATE
                             , PD_APP_PLAN_END_DATE
                             , PD_PLAN_START_DATE
                             , PD_PLAN_END_DATE
                             , PD_ACTUAL_START_DATE
                             , PD_ACTUAL_END_DATE
                             , PV_APP_PLAN_START_DATE
                             , PV_APP_PLAN_END_DATE
                             , PV_PLAN_START_DATE
                             , PV_PLAN_END_DATE
                             , PV_ACTUAL_START_DATE
                             , PV_ACTUAL_END_DATE
                             , VALID_YN
                          FROM GT_SMPS_SCHEDULE
                        MINUS
                        SELECT /* scm_mst_project_schedule_h */
                               DIVISION_ID
                             , PROJECT_CODE
                             , PROJECT_VER_SEQ
                             , CV_APP_PLAN_START_DATE
                             , CV_APP_PLAN_END_DATE
                             , CV_PLAN_START_DATE
                             , CV_PLAN_END_DATE
                             , CV_ACTUAL_START_DATE
                             , CV_ACTUAL_END_DATE
                             , DV_APP_PLAN_START_DATE
                             , DV_APP_PLAN_END_DATE
                             , DV_PLAN_START_DATE
                             , DV_PLAN_END_DATE
                             , DV_ACTUAL_START_DATE
                             , DV_ACTUAL_END_DATE
                             , PD_APP_PLAN_START_DATE
                             , PD_APP_PLAN_END_DATE
                             , PD_PLAN_START_DATE
                             , PD_PLAN_END_DATE
                             , PD_ACTUAL_START_DATE
                             , PD_ACTUAL_END_DATE
                             , PV_APP_PLAN_START_DATE
                             , PV_APP_PLAN_END_DATE
                             , PV_PLAN_START_DATE
                             , PV_PLAN_END_DATE
                             , PV_ACTUAL_START_DATE
                             , PV_ACTUAL_END_DATE
                             , VALID_YN
                          FROM SCM_MST_PROJECT_SCHEDULE) A
                     , GT_SMPS_SCHEDULE B
                 WHERE A.DIVISION_ID     = B.DIVISION_ID
                   AND A.PROJECT_CODE    = B.PROJECT_CODE
                   AND A.PROJECT_VER_SEQ = B.PROJECT_VER_SEQ) A;
        N_LOG_COUNT := SQL%ROWCOUNT;

        /* 처리 안된 row 마킹 */
        UPDATE XIF_PLM_PJT_SCHEDULE_R_SN
           SET ATTR_10 = 'X'
         WHERE ATTR_10 = 'P';

        /* HISTORY LOG */
        V_LOG_TYPE    := 'HISTORY';
        V_LOG_MESSAGE := 'INSERT INTO scm_mst_project_schedule_h';
        V_DESCRIPTION := '@n_history_seq' || ':' || TO_CHAR(N_HISTORY_SEQ);
        D_EVENT_DATE  := SYSDATE;
        PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);


    EXCEPTION
        WHEN OTHERS THEN

            /* ERROR LOG */
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := SUBSTR('ERROR_LINE : ' || DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 500);
            D_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);
    END;

    /* 종료 LOG */
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := '';
    D_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, N_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, D_EVENT_DATE);

END PR_SCM_MST_PROJECT_SCHEDULE;
/
SHOW ERRORS PROCEDURE PR_SCM_MST_PROJECT_SCHEDULE
-- ##### END PROCEDURE PR_SCM_MST_PROJECT_SCHEDULE

-- ##### START PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL
CREATE OR REPLACE PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL
(
    P_PLAN_ID                IN VARCHAR2
  , P_PLAN_START_YYYYMMDD    IN VARCHAR2
)
IS
/*******************************************************************************
 * 프로시저명 : PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL
 * 설명       : 2025.02.07 Taehyun Initial Release
 *              엔진 결과(생산·SEMI 출하·FG 출하) → SCP_ANL_PRODUCTION_PLAN / SCP_ANL_SHIPMENT_PLAN_SEMI
 *              / SCP_ANL_SHIPMENT_PLAN_FG / 각 FIX 테이블 / SCP_XLS_PSI_GLOBAL 반영
 * 2026.10.06   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
 *******************************************************************************/
    --2025.02.07 Taehyun Initial Release
	------------------------------------------------------------------------
    -- Procedure 기본조건.
	------------------------------------------------------------------------
	/* SET XACT_ABORT ON / SET NOCOUNT ON / SET TRANSACTION ISOLATION LEVEL READ COMMITTED : Oracle 해당 없음(삭제) */
	------------------------------------------------------------------------

	------------------------------------------------------------------------
	-- Set Param for Log
	------------------------------------------------------------------------
    V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL';
    V_PLAN_ID                   VARCHAR2(50 CHAR)  := SUBSTR(P_PLAN_ID, 1, 50);   /* AS-IS NVARCHAR(50) 인자 길이로 잘림 */
    V_MESSAGE_TEXT              VARCHAR2(1000 CHAR);
    ------------------------------------------------------------------------
	-- LOG 용 변수 설정
	------------------------------------------------------------------------
    --DECLARE @v_program_name NVARCHAR(150) = 'PR_SCM_LGTM_INV_ALLOCATION';
    V_LOG_TYPE                  VARCHAR2(30 CHAR); -- START/END/ERROR/...
    V_LOG_COUNT                 PLS_INTEGER := 0;
    V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
    V_DESCRIPTION               VARCHAR2(500 CHAR);
    V_EVENT_DATE                DATE;
    ---------------------   ---------------------------------------------------
    -- Set Param for Biz
    ------------------------------------------------------------------------
    V_SCP_PLAN_DATE             VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE             VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ              VARCHAR2(8 CHAR);
    V_DIVISION_ID               VARCHAR2(10 CHAR);
    V_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD         VARCHAR2(8 CHAR);
    V_2ND_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    V_NOW_DATE                  DATE;
    V_MIN_WEEK                  NUMBER;
    V_2ND_MIN_WEEK              NUMBER;
    -- 2026.07.22 Minyong Lee : [E20260713-000080] [ODS] 업로드 수량 이상건 수정
    V_WEEKS_IN_YEAR             NUMBER;
    V_2ND_WEEKS_IN_YEAR         NUMBER;
    V_UPDATE_NAME               VARCHAR2(100 CHAR);
    V_OP_COUNT                  NUMBER;
    V_CHK_INTEGRAL              VARCHAR2(100 CHAR);
    /* 테이블 변수 → GTT(파일 (DDL) 00_GTT_TANL_SCP0123.sql)
       @OP_RESULT         → GT_TANL_OP_RESULT
       @OS_RESULT         → GT_TANL_OS_RESULT
       @OS_RESULT_FG      → GT_TANL_OS_RESULT_FG
       @OS_RESULT_FG_SMMR → GT_TANL_OS_RESULT_FG_SMMR
       @XLS_PV_READY      → GT_TANL_XLS_PV_READY
       @XLS_PV_TABLE      → GT_TANL_XLS_PV_TABLE */
BEGIN
    /* GTT 초기화 (TRUNCATE 금지 : 암묵적 커밋) */
    DELETE FROM GT_TANL_OP_RESULT;
    DELETE FROM GT_TANL_OS_RESULT;
    DELETE FROM GT_TANL_OS_RESULT_FG;
    DELETE FROM GT_TANL_OS_RESULT_FG_SMMR;
    DELETE FROM GT_TANL_XLS_PV_READY;
    DELETE FROM GT_TANL_XLS_PV_TABLE;

	------------------------------------------------------------------------
	-- LOG 시작
	------------------------------------------------------------------------
	V_LOG_TYPE    := 'START';
	V_LOG_MESSAGE := '########## Start of procedure ##########';
	V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
	                      ELSE 'START_' || V_PROGRAM_NAME || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
	                 END;   /* AS-IS 문자 + 는 NULL 이 하나라도 있으면 NULL */
	V_EVENT_DATE  := SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
	------------------------------------------------------------------------

    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_MIN_WEEK := NULL;
    END;
    V_UPDATE_NAME := CASE WHEN V_PLAN_ID IS NULL THEN NULL ELSE 'OPT_ENG_' || V_PLAN_ID END;
    --52주 이후 구간의 데이터를 GLOBAL 테이블에 넣기 위한 변수 설정
    V_2ND_PLAN_START_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');
    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_2ND_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_2ND_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_2ND_MIN_WEEK := NULL;
    END;

    -- 2026.07.22 Minyong Lee : [E20260713-000080] [ODS] 업로드 수량 이상건 수정
    -- 섹션1 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE SUBSTR(BASIS_YYYYMMDD, 1, 4) = SUBSTR(P_PLAN_START_YYYYMMDD, 1, 4);
    -- 섹션2(52주 이후 구간) 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_2ND_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE SUBSTR(BASIS_YYYYMMDD, 1, 4) = SUBSTR(V_2ND_PLAN_START_YYYYMMDD, 1, 4);

    V_NOW_DATE := SYSDATE;
    --SELECT  @V_DIVISION_ID = DIVISION_ID
    --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
    --       ,@V_PLAN_END_YYYYMMDD   = PLAN_END_YYYYMMDD
    --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
    --WHERE   1=1
    --AND     PLAN_ID = @V_PLAN_ID

    --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
    --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
    --        ,@V_PLAN_END_YYYYMMDD   = PM.PLAN_END_YYYYMMDD
    --FROM    SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
    --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID

    BEGIN
        SELECT SUBSTR(IA.DIVISION_ID, 1, 10)
             , SUBSTR(IA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(IA.PLAN_END_YYYYMMDD, 1, 8)
          INTO V_DIVISION_ID
             , V_PLAN_START_YYYYMMDD
             , V_PLAN_END_YYYYMMDD
          FROM (
                SELECT A.DIVISION_ID
                     , A.PLAN_START_YYYYMMDD
                     , A.PLAN_END_YYYYMMDD
                  FROM SCP_OPMZ_PLAN_M A
                 WHERE A.OPMZ_PLAN_ID = V_PLAN_ID
                 UNION
                SELECT B.DIVISION_ID
                     , B.PLAN_START_YYYYMMDD
                     , B.PLAN_END_YYYYMMDD
                  FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN B
                 WHERE B.PLAN_ID = V_PLAN_ID
                 ORDER BY DIVISION_ID DESC NULLS LAST
                        , PLAN_START_YYYYMMDD DESC NULLS LAST
                        , PLAN_END_YYYYMMDD DESC NULLS LAST
               ) IA
         WHERE ROWNUM = 1;   /* AS-IS 변수 대입 SELECT : 0행이면 NULL 유지, 두 원천 값이 달라 여러 행이면 AS-IS 는 마지막 행(비결정) → 정렬 고정 */
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    BEGIN
        SELECT SUBSTR(IA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(IA.PLAN_TYPE, 1, 8)
             , SUBSTR(TO_CHAR(IA.PLAN_SEQ), 1, 8)
          INTO V_SCP_PLAN_DATE
             , V_SCP_PLAN_TYPE
             , V_SCP_PLAN_SEQ
          FROM (
                SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , PLAN_SEQ
                     , PLAN_TYPE_ORDER
                     , CONFIRM_FLAG
                  FROM SCP_PLAN_VERSION_V
                 WHERE DIVISION_ID         = V_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                -- 2026.03.17 Minyong Lee : FN 이후 TE Plan Type 추가 건 대응
                --ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC
                 ORDER BY CASE WHEN PLAN_TYPE = 'TE' THEN 0 ELSE 1 END ASC
                        , PLAN_TYPE_ORDER DESC NULLS LAST
                        , CONFIRM_FLAG DESC NULLS LAST
                        , PLAN_SEQ DESC
               ) IA
         WHERE ROWNUM = 1;   /* TOP 1 */
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    SELECT MAX(PLAN_ID)   /* AS-IS 변수 대입 SELECT : 맞는 행은 모두 PLAN_ID = V_PLAN_ID 라 MAX 와 같다. 0행이면 NULL */
      INTO V_CHK_INTEGRAL
      FROM SCP_OPT_ENG_PHASES_SN
     WHERE UPPER(PRINT_RESULT) LIKE '%INTEGRAL%'   /* AS-IS 대소문자 무시 비교 */
       AND PLAN_ID = V_PLAN_ID;

    IF (V_SCP_PLAN_TYPE = 'FN') THEN
            ------------------------------------------------------------------------
            -- 종료 LOG
	        ------------------------------------------------------------------------
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                                  ELSE 'SCP_PLAN_TYPE IS FN' || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
                             END;
            V_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

            /* SET XACT_ABORT OFF : 삭제. AS-IS 는 호출자 TRY 안이라 여기서 중단되어 호출자 CATCH 로 간다 */
            RAISE_APPLICATION_ERROR(-20001, ' I/F not executed because PLAN_TYPE is FN.');
    END IF;
    ------------------------------------------------------------------------
	-- Transaction (START)
	------------------------------------------------------------------------
	BEGIN   /* BEGIN TRY / BEGIN TRAN */

        ------------------------------------------------------------------------
        -- 엔진 결과에서 문자열 'E'를 붙여서 나오는 데이터 치환
        ------------------------------------------------------------------------
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN
           SET ATTRIBUTE1 = OUT_QTY
             , OUT_QTY    = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY) END))
         WHERE UPPER(OUT_QTY) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN
           SET ATTRIBUTE1  = OUT_QTY_INT
             , OUT_QTY_INT = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY_INT) END))
         WHERE UPPER(OUT_QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN
           SET ATTRIBUTE1 = QTY_INT
             , QTY_INT    = TO_CHAR(ROUND(CASE WHEN UPPER(QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY_INT) END))
         WHERE UPPER(QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN
           SET ATTRIBUTE1 = QTY
             , QTY        = TO_CHAR(ROUND(CASE WHEN UPPER(QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY) END))
         WHERE UPPER(QTY) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;

    ------------------------------------------------------------------------
    -- ORDER_PRODUCTION DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Production Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TANL_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , D.BASIS_YYYYMMDD      AS START_DATE
                 , SUM(CASE WHEN D.BASIS_YYYYMMDD = A.START_DATE THEN CAST(TO_NUMBER(A.OUT_QTY) AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY
                 , B.RESOURCE_NAME       AS LINE_ID
                 , C.OPERATION_GROUP
                 , C.FLOW_ID             AS OPERATION_ID
                 , NULL                  AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN A
                 , (
                    SELECT E.PRODUCTION_ORDER_ID
                         , E.PRODUCTION_LINE_ID
                         , E.PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_SN E
                     WHERE E.PLAN_ID = V_PLAN_ID
                     GROUP BY E.PRODUCTION_ORDER_ID
                            , E.PRODUCTION_LINE_ID
                            , E.PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCP_MST_FINAL_ITEM C
                 , SCM_SYS_CALENDAR_M D
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND C.ITEM_ID             = A.ITEM_ID
               AND A.GRADE IN ( 'ASSY','PACK','MDLE')
               AND IA.PLAN_ID IS NOT NULL
               AND C.DIVISION_ID         = V_DIVISION_ID
               AND A.PLAN_ID             = V_PLAN_ID
               AND D.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , D.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , C.OPERATION_GROUP
                    , C.FLOW_ID;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TANL_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , D.BASIS_YYYYMMDD      AS START_DATE
                 , SUM(CASE WHEN D.BASIS_YYYYMMDD = A.START_DATE THEN CAST(TO_NUMBER(A.OUT_QTY_INT) AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , B.RESOURCE_NAME       AS LINE_ID
                 , C.OPERATION_GROUP
                 , C.FLOW_ID             AS OPERATION_ID
                 , NULL                  AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN A
                 , (
                    SELECT E.PRODUCTION_ORDER_ID
                         , E.PRODUCTION_LINE_ID
                         , E.PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_INT_SN E
                     WHERE E.PLAN_ID = V_PLAN_ID
                     GROUP BY E.PRODUCTION_ORDER_ID
                            , E.PRODUCTION_LINE_ID
                            , E.PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCP_MST_FINAL_ITEM C
                 , SCM_SYS_CALENDAR_M D
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND C.ITEM_ID             = A.ITEM_ID
               AND A.GRADE IN ( 'ASSY','PACK','MDLE')
               AND IA.PLAN_ID IS NOT NULL
               AND C.DIVISION_ID         = V_DIVISION_ID
               AND A.PLAN_ID             = V_PLAN_ID
               AND D.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , D.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , C.OPERATION_GROUP
                    , C.FLOW_ID;
        END IF;

        ------------------------------------------------------------------------
        -- 생산 결과가 없으면 Error 생성
        ------------------------------------------------------------------------
        SELECT COUNT(*)
          INTO V_OP_COUNT
          FROM GT_TANL_OP_RESULT;

        IF V_OP_COUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20001, 'Order Production count is zero');
        END IF;
        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.SCM_SITE_ID
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;

        DBMS_OUTPUT.PUT_LINE('SCP_ANL_PRODUCTION_PLAN');

        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        /* MERGE(온라인 금지) → ① WHEN MATCHED : UPDATE */
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET A.QTY              = (SELECT B.OUT_QTY_INT
                                       FROM GT_TANL_OP_RESULT B
                                      WHERE B.OPERATION_GROUP = A.OPERATION_GROUP
                                        AND B.SITE_ID         = A.SCM_SITE_ID
                                        AND B.ITEM_ID         = A.ITEM_ID
                                        AND B.LINE_ID         = A.LINE_ID
                                        AND B.OPERATION_ID    = A.OPERATION_ID
                                        AND B.START_DATE      = A.YYYYMMDD
                                        AND ROWNUM            = 1
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9        = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_OP_RESULT C
                        WHERE C.OPERATION_GROUP = A.OPERATION_GROUP
                          AND C.SITE_ID         = A.SCM_SITE_ID
                          AND C.ITEM_ID         = A.ITEM_ID
                          AND C.LINE_ID         = A.LINE_ID
                          AND C.OPERATION_ID    = A.OPERATION_ID
                          AND C.START_DATE      = A.YYYYMMDD
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        /* MERGE → ② WHEN NOT MATCHED : INSERT */
        INSERT INTO SCP_ANL_PRODUCTION_PLAN
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , A.OPERATION_GROUP
             , A.SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , 'PROD_PLAN_AMEND'
             , A.START_DATE
             , A.OUT_QTY_INT
             , V_DIVISION_ID
             , A.ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM GT_TANL_OP_RESULT A
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_PRODUCTION_PLAN B
                            WHERE B.OPERATION_GROUP     = A.OPERATION_GROUP
                              AND B.SCM_SITE_ID         = A.SITE_ID
                              AND B.ITEM_ID             = A.ITEM_ID
                              AND B.LINE_ID             = A.LINE_ID
                              AND B.OPERATION_ID        = A.OPERATION_ID
                              AND B.YYYYMMDD            = A.START_DATE
                              AND B.MEASURE             IN ('PROD_PLAN_AMEND')
                              AND B.DIVISION_ID         = V_DIVISION_ID
                              AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND B.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN
         WHERE MEASURE             IN ('PROD_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;

        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.SCM_SITE_ID
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.QTY != 0
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- UPDATE SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET A.QTY              = (SELECT B.OUT_QTY_INT
                                       FROM GT_TANL_OP_RESULT B
                                      WHERE B.OPERATION_GROUP = A.OPERATION_GROUP
                                        AND B.SITE_ID         = A.SCM_SITE_ID
                                        AND B.ITEM_ID         = A.ITEM_ID
                                        AND B.LINE_ID         = A.LINE_ID
                                        AND B.OPERATION_ID    = A.OPERATION_ID
                                        AND B.START_DATE      = A.YYYYMMDD
                                        AND ROWNUM            = 1   /* 원천 중복 가능(GRADE 축), AS-IS 비결정 */
                                    )
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, SCP_ANL_PRODUCTION_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_OP_RESULT C
                        WHERE C.OPERATION_GROUP = A.OPERATION_GROUP
                          AND C.SITE_ID         = A.SCM_SITE_ID
                          AND C.ITEM_ID         = A.ITEM_ID
                          AND C.LINE_ID         = A.LINE_ID
                          AND C.OPERATION_ID    = A.OPERATION_ID
                          AND C.START_DATE      = A.YYYYMMDD
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
             ( HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN_FIX
         WHERE DIVISION_ID      = V_DIVISION_ID
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY  = V_UPDATE_NAME
           AND LAST_UPDATE_DATE = V_NOW_DATE;

    ------------------------------------------------------------------------
    -- ORDER_SHIPPING SEMI DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TANL_OS_RESULT
                 ( OPERATION_GROUP
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 )
            SELECT IA.OPERATION_GROUP
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                 , F.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN F.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
              FROM (
                    SELECT C.OPERATION_GROUP
                         , A.ITEM_ID        AS ITEM_ID
                         , A.FROM_SITE_ID   AS FROM_SITE
                         , B.ATTRIBUTE7     AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , A.DEPARTURE_DATE AS YYYYMMDD
                         , A.TO_SITE_ID     AS TO_SITE
                         , TO_NUMBER(A.QTY) AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID    AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID    AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL             AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , B.ATTRIBUTE8     AS BOD_TYPE
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN A
                         , SCP_OPT_ENG_BOD_SN B
                         , SCP_MST_FINAL_ITEM C
                     WHERE A.BOD_ID      = B.BOD_ID
                       AND C.ITEM_ID     = A.ITEM_ID
                       AND B.ATTRIBUTE8  = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND B.PLAN_ID     = V_PLAN_ID
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND A.PLAN_ID     = V_PLAN_ID

                     UNION ALL
                    SELECT E.OPERATION_GROUP
                         , D.ATTRIBUTE2      AS ITEM_ID
                         , D.ATTRIBUTE1      AS FROM_SITE
                         , D.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , D.DEPARTURE_DATE  AS YYYYMMDD
                         , D.ATTRIBUTE4      AS TO_SITE
                         , D.QUANTITY        AS QTY
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , D.ATTRIBUTE8      AS BOD_TYPE
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN D
                         , SCP_MST_FINAL_ITEM E
                     WHERE E.ITEM_ID     = D.ATTRIBUTE2
                       AND D.ATTRIBUTE6  = 'IN'
                       AND D.ATTRIBUTE8  = 'PLANT'
                       AND E.DIVISION_ID = V_DIVISION_ID
                       AND D.PLAN_ID     = V_PLAN_ID
                   ) IA
                 , SCM_SYS_CALENDAR_M F
             WHERE F.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.OPERATION_GROUP
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , F.BASIS_YYYYMMDD;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TANL_OS_RESULT
                 ( OPERATION_GROUP
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 )
            SELECT IA.OPERATION_GROUP
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                 , F.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN F.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
              FROM (
                    SELECT C.OPERATION_GROUP
                         , A.ITEM_ID        AS ITEM_ID
                         , A.FROM_SITE_ID   AS FROM_SITE
                         , B.ATTRIBUTE7     AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , A.DEPARTURE_DATE AS YYYYMMDD
                         , A.TO_SITE_ID     AS TO_SITE
                         , TO_NUMBER(A.QTY_INT) AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID    AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID    AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL             AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , B.ATTRIBUTE8     AS BOD_TYPE
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN A
                         , SCP_OPT_ENG_BOD_SN B
                         , SCP_MST_FINAL_ITEM C
                     WHERE A.BOD_ID      = B.BOD_ID
                       AND C.ITEM_ID     = A.ITEM_ID
                       AND B.ATTRIBUTE8  = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND B.PLAN_ID     = V_PLAN_ID
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND A.PLAN_ID     = V_PLAN_ID

                     UNION ALL
                    SELECT E.OPERATION_GROUP
                         , D.ATTRIBUTE2      AS ITEM_ID
                         , D.ATTRIBUTE1      AS FROM_SITE
                         , D.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , D.DEPARTURE_DATE  AS YYYYMMDD
                         , D.ATTRIBUTE4      AS TO_SITE
                         , D.QUANTITY        AS QTY
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , D.ATTRIBUTE8      AS BOD_TYPE
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN D
                         , SCP_MST_FINAL_ITEM E
                     WHERE E.ITEM_ID     = D.ATTRIBUTE2
                       AND D.ATTRIBUTE6  = 'IN'
                       AND D.ATTRIBUTE8  = 'PLANT'
                       AND E.DIVISION_ID = V_DIVISION_ID
                       AND D.PLAN_ID     = V_PLAN_ID
                   ) IA
                 , SCM_SYS_CALENDAR_M F
             WHERE F.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.OPERATION_GROUP
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , F.BASIS_YYYYMMDD;
        END IF;

        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_SEMI A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.FROM_SITE
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.MEASURE             IN ('SHIP_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;


        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_SEMI');
        /* MERGE(온라인 금지) → ① WHEN MATCHED : UPDATE */
        UPDATE SCP_ANL_SHIPMENT_PLAN_SEMI A
           SET A.QTY              = (SELECT B.QTY
                                       FROM GT_TANL_OS_RESULT B
                                      WHERE B.OPERATION_GROUP = A.OPERATION_GROUP
                                        AND B.ITEM_ID         = A.ITEM_ID
                                        AND B.FROM_SITE       = A.FROM_SITE
                                        AND B.BOD_ID          = A.BOD_ID
                                        AND B.MEASURE         = A.MEASURE
                                        AND B.YYYYMMDD        = A.YYYYMMDD
                                        AND ROWNUM            = 1
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_OS_RESULT C
                        WHERE C.OPERATION_GROUP = A.OPERATION_GROUP
                          AND C.ITEM_ID         = A.ITEM_ID
                          AND C.FROM_SITE       = A.FROM_SITE
                          AND C.BOD_ID          = A.BOD_ID
                          AND C.MEASURE         = A.MEASURE
                          AND C.YYYYMMDD        = A.YYYYMMDD
                      )
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        /* MERGE → ② WHEN NOT MATCHED : INSERT */
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , TO_SITE
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , A.OPERATION_GROUP
             , A.ITEM_ID
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , A.YYYYMMDD
             , A.TO_SITE
             , A.QTY
             , A.ORIGIN_TO_DIVISION_ID     /* AS-IS 그대로 : FROM 칸에 TO 값 */
             , A.ORIGIN_FROM_DIVISION_ID   /* AS-IS 그대로 : TO 칸에 FROM 값 */
             , A.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM GT_TANL_OS_RESULT A
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
                            WHERE B.OPERATION_GROUP     = A.OPERATION_GROUP
                              AND B.ITEM_ID             = A.ITEM_ID
                              AND B.FROM_SITE           = A.FROM_SITE
                              AND B.BOD_ID              = A.BOD_ID
                              AND B.MEASURE             = A.MEASURE
                              AND B.YYYYMMDD            = A.YYYYMMDD
                              AND B.DIVISION_ID         = V_DIVISION_ID
                              AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND B.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , UPDATE_REASON_BOD
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_SEMI_H.NEXTVAL AS HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , NULL AS UPDATE_REASON_BOD
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE AS HISTORY_CREATION_DATE
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI
         WHERE MEASURE             IN ('SHIP_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;


        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.FROM_SITE
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.QTY != 0
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND A.DIVISION_ID = V_DIVISION_ID;


        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET A.QTY              = (SELECT B.QTY
                                       FROM GT_TANL_OS_RESULT B
                                      WHERE B.OPERATION_GROUP = A.BIZ_TYPE
                                        AND B.ITEM_ID         = A.ITEM_ID
                                        AND B.TO_SITE         = A.TO_SITE
                                        AND B.FROM_SITE       = A.FROM_SITE
                                        AND B.BOD_ID          = A.BOD_ID
                                        AND B.YYYYMMDD        = A.YYYYMMDD
                                        AND ROWNUM            = 1   /* 원천 중복 가능(MEASURE·BOD_TYPE 축), AS-IS 비결정 */
                                    )
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_OS_RESULT C
                        WHERE C.OPERATION_GROUP = A.BIZ_TYPE
                          AND C.ITEM_ID         = A.ITEM_ID
                          AND C.TO_SITE         = A.TO_SITE
                          AND C.FROM_SITE       = A.FROM_SITE
                          AND C.BOD_ID          = A.BOD_ID
                          AND C.YYYYMMDD        = A.YYYYMMDD
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;

    ------------------------------------------------------------------------
    -- ORDER_SHIPPING FG DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TANL_OS_RESULT_FG
                 ( OPERATION_GROUP
                 , PROJECT_CODE
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 , INCOTERMS
                 )
            SELECT IA.BIZ_TYPE
                 , IA.PROJECT_CODE
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                  --,YYYYMMDD
                 , F.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN F.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                  --,QTY
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
                 , IA.INCOTERMS
              FROM (
                    SELECT C.OPERATION_GROUP AS BIZ_TYPE
                         , B.ATTRIBUTE9      AS PROJECT_CODE
                         , A.ITEM_ID         AS ITEM_ID
                         , A.FROM_SITE_ID    AS FROM_SITE
                         , B.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , A.DEPARTURE_DATE  AS YYYYMMDD
                         , A.TO_SITE_ID      AS TO_SITE
                         , TO_NUMBER(A.QTY)  AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , B.ATTRIBUTE8      AS BOD_TYPE
                         , B.ATTRIBUTE6      AS INCOTERMS
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN A
                         , SCP_OPT_ENG_BOD_SN B
                         , SCP_MST_FINAL_ITEM C
                     WHERE A.BOD_ID      = B.BOD_ID
                       AND C.ITEM_ID     = A.ITEM_ID
                       AND B.ATTRIBUTE8  = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND B.ATTRIBUTE7 <> 'DUMMY'
                       AND B.PLAN_ID     = V_PLAN_ID
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND A.PLAN_ID     = V_PLAN_ID
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                     UNION ALL
                    SELECT E.OPERATION_GROUP
                         , D.ATTRIBUTE10     AS PROJECT_CODE
                         , D.ATTRIBUTE2      AS ITEM_ID
                         , D.ATTRIBUTE1      AS FROM_SITE
                         , D.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , D.DEPARTURE_DATE  AS YYYYMMDD
                         , D.ATTRIBUTE4      AS TO_SITE
                         , SUM(D.QUANTITY)   AS QTY
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , D.ATTRIBUTE8      AS BOD_TYPE
                         , D.ATTRIBUTE9      AS INCOTERMS
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN D
                         , SCP_MST_FINAL_ITEM E
                     WHERE E.ITEM_ID     = D.ATTRIBUTE2
                       AND D.ATTRIBUTE6  = 'IN'
                       AND D.ATTRIBUTE8  = 'SALES'
                       AND E.DIVISION_ID = V_DIVISION_ID
                       AND D.PLAN_ID     = V_PLAN_ID
                     GROUP BY E.OPERATION_GROUP
                            , D.ATTRIBUTE10
                            , D.ATTRIBUTE2
                            , D.ATTRIBUTE1
                            , D.ATTRIBUTE7
                            , D.DEPARTURE_DATE
                            , D.ATTRIBUTE4
                            , D.ATTRIBUTE8
                            , D.ATTRIBUTE9 -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                   ) IA
                 , SCM_SYS_CALENDAR_M F
             WHERE F.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.BIZ_TYPE
                    , IA.PROJECT_CODE
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , IA.INCOTERMS
                    , F.BASIS_YYYYMMDD;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TANL_OS_RESULT_FG
                 ( OPERATION_GROUP
                 , PROJECT_CODE
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 , INCOTERMS
                 )
            SELECT IA.BIZ_TYPE
                 , IA.PROJECT_CODE
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                  --,YYYYMMDD
                 , F.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN F.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                  --,QTY
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
                 , IA.INCOTERMS
              FROM (
                    SELECT C.OPERATION_GROUP AS BIZ_TYPE
                         , B.ATTRIBUTE9      AS PROJECT_CODE
                         , A.ITEM_ID         AS ITEM_ID
                         , A.FROM_SITE_ID    AS FROM_SITE
                         , B.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , A.DEPARTURE_DATE  AS YYYYMMDD
                         , A.TO_SITE_ID      AS TO_SITE
                         , TO_NUMBER(A.QTY_INT) AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , B.ATTRIBUTE8      AS BOD_TYPE
                         , B.ATTRIBUTE6      AS INCOTERMS
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN A
                         , SCP_OPT_ENG_BOD_SN B
                         , SCP_MST_FINAL_ITEM C
                     WHERE A.BOD_ID      = B.BOD_ID
                       AND C.ITEM_ID     = A.ITEM_ID
                       AND B.ATTRIBUTE8  = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND B.ATTRIBUTE7 <> 'DUMMY'
                       AND B.PLAN_ID     = V_PLAN_ID
                       AND C.DIVISION_ID = V_DIVISION_ID
                       AND A.PLAN_ID     = V_PLAN_ID
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                     UNION ALL
                    SELECT E.OPERATION_GROUP
                         , D.ATTRIBUTE10     AS PROJECT_CODE
                         , D.ATTRIBUTE2      AS ITEM_ID
                         , D.ATTRIBUTE1      AS FROM_SITE
                         , D.ATTRIBUTE7      AS BOD_ID
                         , 'SHIP_PLAN_AMEND' AS MEASURE
                         , D.DEPARTURE_DATE  AS YYYYMMDD
                         , D.ATTRIBUTE4      AS TO_SITE
                         , SUM(D.QUANTITY)   AS QTY
                         , V_DIVISION_ID     AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID     AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL              AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , D.ATTRIBUTE8      AS BOD_TYPE
                         , D.ATTRIBUTE9      AS INCOTERMS
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN D
                         , SCP_MST_FINAL_ITEM E
                     WHERE E.ITEM_ID     = D.ATTRIBUTE2
                       AND D.ATTRIBUTE6  = 'IN'
                       AND D.ATTRIBUTE8  = 'SALES'
                       AND E.DIVISION_ID = V_DIVISION_ID
                       AND D.PLAN_ID     = V_PLAN_ID
                     GROUP BY E.OPERATION_GROUP
                            , D.ATTRIBUTE10
                            , D.ATTRIBUTE2
                            , D.ATTRIBUTE1
                            , D.ATTRIBUTE7
                            , D.DEPARTURE_DATE
                            , D.ATTRIBUTE4
                            , D.ATTRIBUTE8
                            , D.ATTRIBUTE9 -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                   ) IA
                 , SCM_SYS_CALENDAR_M F
             WHERE F.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.BIZ_TYPE
                    , IA.PROJECT_CODE
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , IA.INCOTERMS
                    , F.BASIS_YYYYMMDD;
        END IF;

        ------------------------------------------------------------------------
        -- 0. 입력할 데이터가 있으면 진행
        ------------------------------------------------------------------------

        ------------------------------------------------------------------------
        -- 1. Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9       = 'U'
          --, ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.FROM_SITE
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.MEASURE             IN ('SHIP_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;

        ------------------------------------------------------------------------
        -- 2. Get SCP_ANL_SHIPMENT_PLAN_FG DATA
        -- 프로젝트 코드가 1개인 대상만 추출 -> 속도 개선을 위한 TEMP 테이블 사용
        -- '-'는 제외하고 COUNTING
        ------------------------------------------------------------------------
        INSERT INTO GT_TANL_OS_RESULT_FG_SMMR
             ( ITEM_ID
             , BOD_ID
             , PROJECT_CODE
             )
        SELECT IA.ITEM_ID
             , IA.BOD_ID
             , C.PROJECT_CODE
          FROM (
                SELECT IB.DIVISION_ID
                     , IB.PLAN_START_YYYYMMDD
                     , IB.PLAN_TYPE
                     , IB.SEQ
                     , IB.BIZ_TYPE
                     , IB.ITEM_ID
                     , IB.MEASURE
                     , IB.BOD_ID
                  FROM (
                        SELECT A.DIVISION_ID
                             , A.PLAN_START_YYYYMMDD
                             , A.PLAN_TYPE
                             , A.SEQ
                             , A.BIZ_TYPE
                             , A.PROJECT_CODE
                             , A.ITEM_ID
                             , A.MEASURE
                             , A.BOD_ID
                          FROM SCP_ANL_SHIPMENT_PLAN_FG A
                             , (
                                SELECT B.SCM_SITE_ID
                                     , B.ITEM_ID
                                  FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                                 WHERE B.PLAN_ID = V_PLAN_ID
                                 GROUP BY B.SCM_SITE_ID
                                        , B.ITEM_ID
                               ) IC
                         WHERE A.FROM_SITE           = IC.SCM_SITE_ID
                           AND A.ITEM_ID             = IC.ITEM_ID
                           AND A.MEASURE             IN ('SHIP_PLAN_AMEND')
                           AND A.PROJECT_CODE       != '-'
                           AND A.DIVISION_ID         = V_DIVISION_ID
                           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
                           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
                         GROUP BY A.DIVISION_ID
                                , A.PLAN_START_YYYYMMDD
                                , A.PLAN_TYPE
                                , A.SEQ
                                , A.BIZ_TYPE
                                , A.PROJECT_CODE
                                , A.ITEM_ID
                                , A.MEASURE
                                , A.BOD_ID
                       ) IB
                 GROUP BY IB.DIVISION_ID
                        , IB.PLAN_START_YYYYMMDD
                        , IB.PLAN_TYPE
                        , IB.SEQ
                        , IB.BIZ_TYPE
                        , IB.ITEM_ID
                        , IB.MEASURE
                        , IB.BOD_ID
                HAVING COUNT(IB.DIVISION_ID) = 1
               ) IA
             , SCP_ANL_SHIPMENT_PLAN_FG C
         WHERE IA.ITEM_ID             = C.ITEM_ID
           AND IA.BOD_ID              = C.BOD_ID
           AND C.DIVISION_ID          = IA.DIVISION_ID
           AND C.MEASURE              = IA.MEASURE
           AND C.PLAN_START_YYYYMMDD  = IA.PLAN_START_YYYYMMDD
           AND C.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 (안쪽 집합이 같은 계획 시작일) */
           AND C.PLAN_TYPE            = IA.PLAN_TYPE
           AND C.SEQ                  = IA.SEQ
           AND C.PROJECT_CODE        != '-'
           AND C.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
         GROUP BY IA.ITEM_ID
                , IA.BOD_ID
                , C.PROJECT_CODE;


        ------------------------------------------------------------------------
        -- 2-1. 프로젝트 코드가 있으면 바로 넣고, 없는 애들만 2-2에서 프로젝트 코드를 찾아서 넣음
        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_FG');
        /* MERGE(온라인 금지) → ① WHEN MATCHED : UPDATE (USING 서브쿼리를 XA 로 그대로 사용) */
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET A.QTY              = (SELECT XA.QTY
                                       FROM (
                                             SELECT B.OPERATION_GROUP
                                                  , B.PROJECT_CODE
                                                  , B.ITEM_ID
                                                  , B.TO_SITE
                                                  , B.INCOTERMS
                                                  , B.FROM_SITE
                                                  , B.BOD_ID
                                                  , B.MEASURE
                                                  , B.YYYYMMDD
                                                  , B.QTY
                                                  , B.ORIGIN_FROM_DIVISION_ID
                                                  , B.ORIGIN_TO_DIVISION_ID
                                                  , B.ELECTRODE_TYPE
                                               FROM GT_TANL_OS_RESULT_FG B
                                              WHERE B.PROJECT_CODE != '/' --프로젝트 코드를 가지고있는 애들은 바로 MERGE INTO
                                            ) XA
                                      WHERE XA.OPERATION_GROUP = A.BIZ_TYPE
                                        AND XA.PROJECT_CODE    = A.PROJECT_CODE
                                        AND XA.ITEM_ID         = A.ITEM_ID
                                        AND XA.TO_SITE         = A.TO_SITE
                                        AND XA.INCOTERMS       = A.INCOTERMS
                                        AND XA.FROM_SITE       = A.FROM_SITE
                                        AND XA.BOD_ID          = A.BOD_ID
                                        AND XA.MEASURE         = A.MEASURE
                                        AND XA.YYYYMMDD        = A.YYYYMMDD
                                        AND ROWNUM             = 1
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM (
                               SELECT C.OPERATION_GROUP
                                    , C.PROJECT_CODE
                                    , C.ITEM_ID
                                    , C.TO_SITE
                                    , C.INCOTERMS
                                    , C.FROM_SITE
                                    , C.BOD_ID
                                    , C.MEASURE
                                    , C.YYYYMMDD
                                 FROM GT_TANL_OS_RESULT_FG C
                                WHERE C.PROJECT_CODE != '/' --프로젝트 코드를 가지고있는 애들은 바로 MERGE INTO
                              ) XB
                        WHERE XB.OPERATION_GROUP = A.BIZ_TYPE
                          AND XB.PROJECT_CODE    = A.PROJECT_CODE
                          AND XB.ITEM_ID         = A.ITEM_ID
                          AND XB.TO_SITE         = A.TO_SITE
                          AND XB.INCOTERMS       = A.INCOTERMS
                          AND XB.FROM_SITE       = A.FROM_SITE
                          AND XB.BOD_ID          = A.BOD_ID
                          AND XB.MEASURE         = A.MEASURE
                          AND XB.YYYYMMDD        = A.YYYYMMDD
                      )
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        /* MERGE → ② WHEN NOT MATCHED : INSERT */
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , XA.OPERATION_GROUP
             , XA.PROJECT_CODE
             , XA.ITEM_ID
             , XA.TO_SITE
             , XA.INCOTERMS
             , XA.FROM_SITE
             , XA.BOD_ID
             , XA.MEASURE
             , XA.YYYYMMDD
             , XA.QTY
             , XA.ORIGIN_FROM_DIVISION_ID
             , XA.ORIGIN_TO_DIVISION_ID
             , XA.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM (
                SELECT A.OPERATION_GROUP
                     , A.PROJECT_CODE
                     , A.ITEM_ID
                     , A.TO_SITE
                     , A.INCOTERMS
                     , A.FROM_SITE
                     , A.BOD_ID
                     , A.MEASURE
                     , A.YYYYMMDD
                     , A.QTY
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , A.ELECTRODE_TYPE
                  FROM GT_TANL_OS_RESULT_FG A
                 WHERE A.PROJECT_CODE != '/' --프로젝트 코드를 가지고있는 애들은 바로 MERGE INTO
               ) XA
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_SHIPMENT_PLAN_FG B
                            WHERE B.BIZ_TYPE            = XA.OPERATION_GROUP
                              AND B.PROJECT_CODE        = XA.PROJECT_CODE
                              AND B.ITEM_ID             = XA.ITEM_ID
                              AND B.TO_SITE             = XA.TO_SITE
                              AND B.INCOTERMS           = XA.INCOTERMS
                              AND B.FROM_SITE           = XA.FROM_SITE
                              AND B.BOD_ID              = XA.BOD_ID
                              AND B.MEASURE             = XA.MEASURE
                              AND B.YYYYMMDD            = XA.YYYYMMDD
                              AND B.DIVISION_ID         = V_DIVISION_ID
                              AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND B.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );


        ------------------------------------------------------------------------
        -- 2-2. 엔진 결과에서 프로젝트 코드가 없는('-') 대상은 찾아서 넣어야 함
        -- FG에  PROJECT가 한개인 것 MERGE INTO
        -- 프로젝트가 한 개 라면, 그 프로젝트를 찾아서 INSERT 하기위해
        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_FG_____2');
        /* MERGE(온라인 금지) → ① WHEN MATCHED : UPDATE (USING 서브쿼리를 XA 로 그대로 사용) */
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET A.QTY              = (SELECT XA.QTY
                                       FROM (
                                             SELECT B.OPERATION_GROUP
                                                  , C.PROJECT_CODE
                                                  , B.ITEM_ID
                                                  , B.TO_SITE
                                                  , B.INCOTERMS
                                                  , B.FROM_SITE
                                                  , B.BOD_ID
                                                  , B.MEASURE
                                                  , B.YYYYMMDD
                                                  , B.QTY
                                                  , B.ORIGIN_FROM_DIVISION_ID
                                                  , B.ORIGIN_TO_DIVISION_ID
                                                  , B.ELECTRODE_TYPE
                                               FROM GT_TANL_OS_RESULT_FG B
                                                  , GT_TANL_OS_RESULT_FG_SMMR C
                                              WHERE B.ITEM_ID      = C.ITEM_ID
                                                AND B.BOD_ID       = C.BOD_ID
                                                AND B.PROJECT_CODE = '/'
                                            ) XA
                                      WHERE XA.OPERATION_GROUP = A.BIZ_TYPE
                                        AND XA.PROJECT_CODE    = A.PROJECT_CODE
                                        AND XA.ITEM_ID         = A.ITEM_ID
                                        AND XA.TO_SITE         = A.TO_SITE
                                        AND XA.INCOTERMS       = A.INCOTERMS
                                        AND XA.FROM_SITE       = A.FROM_SITE
                                        AND XA.BOD_ID          = A.BOD_ID
                                        AND XA.MEASURE         = A.MEASURE
                                        AND XA.YYYYMMDD        = A.YYYYMMDD
                                        AND ROWNUM             = 1   /* 원천 중복 가능(SMMR 한 ITEM·BOD 에 프로젝트 여러 개), AS-IS MERGE 는 오류 */
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM (
                               SELECT D.OPERATION_GROUP
                                    , E.PROJECT_CODE
                                    , D.ITEM_ID
                                    , D.TO_SITE
                                    , D.INCOTERMS
                                    , D.FROM_SITE
                                    , D.BOD_ID
                                    , D.MEASURE
                                    , D.YYYYMMDD
                                 FROM GT_TANL_OS_RESULT_FG D
                                    , GT_TANL_OS_RESULT_FG_SMMR E
                                WHERE D.ITEM_ID      = E.ITEM_ID
                                  AND D.BOD_ID       = E.BOD_ID
                                  AND D.PROJECT_CODE = '/'
                              ) XB
                        WHERE XB.OPERATION_GROUP = A.BIZ_TYPE
                          AND XB.PROJECT_CODE    = A.PROJECT_CODE
                          AND XB.ITEM_ID         = A.ITEM_ID
                          AND XB.TO_SITE         = A.TO_SITE
                          AND XB.INCOTERMS       = A.INCOTERMS
                          AND XB.FROM_SITE       = A.FROM_SITE
                          AND XB.BOD_ID          = A.BOD_ID
                          AND XB.MEASURE         = A.MEASURE
                          AND XB.YYYYMMDD        = A.YYYYMMDD
                      )
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        /* MERGE → ② WHEN NOT MATCHED : INSERT */
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , XA.OPERATION_GROUP
             , XA.PROJECT_CODE    --OSF를 만들 때 하나인 프로젝트 코드를 찾았음
             , XA.ITEM_ID
             , XA.TO_SITE
             , XA.INCOTERMS
             , XA.FROM_SITE
             , XA.BOD_ID
             , XA.MEASURE
             , XA.YYYYMMDD
             , XA.QTY
             , XA.ORIGIN_FROM_DIVISION_ID
             , XA.ORIGIN_TO_DIVISION_ID
             , XA.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM (
                SELECT A.OPERATION_GROUP
                     , B.PROJECT_CODE
                     , A.ITEM_ID
                     , A.TO_SITE
                     , A.INCOTERMS
                     , A.FROM_SITE
                     , A.BOD_ID
                     , A.MEASURE
                     , A.YYYYMMDD
                     , A.QTY
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , A.ELECTRODE_TYPE
                  FROM GT_TANL_OS_RESULT_FG A
                     , GT_TANL_OS_RESULT_FG_SMMR B
                 WHERE A.ITEM_ID      = B.ITEM_ID
                   AND A.BOD_ID       = B.BOD_ID
                   AND A.PROJECT_CODE = '/'
               ) XA
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_SHIPMENT_PLAN_FG C
                            WHERE C.BIZ_TYPE            = XA.OPERATION_GROUP
                              AND C.PROJECT_CODE        = XA.PROJECT_CODE
                              AND C.ITEM_ID             = XA.ITEM_ID
                              AND C.TO_SITE             = XA.TO_SITE
                              AND C.INCOTERMS           = XA.INCOTERMS
                              AND C.FROM_SITE           = XA.FROM_SITE
                              AND C.BOD_ID              = XA.BOD_ID
                              AND C.MEASURE             = XA.MEASURE
                              AND C.YYYYMMDD            = XA.YYYYMMDD
                              AND C.DIVISION_ID         = V_DIVISION_ID
                              AND C.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND C.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND C.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND C.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );

        ------------------------------------------------------------------------
        -- 3. FG에 프로젝트가 여러개인 애들 MERGE INTO
        -- Project Code가 -로 등록되어있으면 update, 아니면 Project Code를 -로 insert
        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_FG_____3');
        /* MERGE(온라인 금지) → ① WHEN MATCHED : UPDATE (USING 서브쿼리를 XA 로 그대로 사용) */
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET A.QTY              = (SELECT XA.QTY
                                       FROM (
                                             SELECT B.OPERATION_GROUP
                                                  , B.PROJECT_CODE
                                                  , B.ITEM_ID
                                                  , B.TO_SITE
                                                  , B.INCOTERMS
                                                  , B.FROM_SITE
                                                  , B.BOD_ID
                                                  , B.MEASURE
                                                  , B.YYYYMMDD
                                                  , B.QTY
                                                  , B.ORIGIN_FROM_DIVISION_ID
                                                  , B.ORIGIN_TO_DIVISION_ID
                                                  , B.ELECTRODE_TYPE
                                               FROM GT_TANL_OS_RESULT_FG B
                                                  , GT_TANL_OS_RESULT_FG_SMMR C
                                              WHERE B.ITEM_ID      = C.ITEM_ID(+)
                                                AND B.BOD_ID       = C.BOD_ID(+)
                                                AND C.ITEM_ID IS NULL
                                                AND B.PROJECT_CODE = '/'
                                            ) XA
                                      WHERE XA.OPERATION_GROUP = A.BIZ_TYPE
                                        AND XA.PROJECT_CODE    = A.PROJECT_CODE
                                        AND XA.ITEM_ID         = A.ITEM_ID
                                        AND XA.TO_SITE         = A.TO_SITE
                                        AND XA.INCOTERMS       = A.INCOTERMS
                                        AND XA.FROM_SITE       = A.FROM_SITE
                                        AND XA.BOD_ID          = A.BOD_ID
                                        AND XA.MEASURE         = A.MEASURE
                                        AND XA.YYYYMMDD        = A.YYYYMMDD
                                        AND ROWNUM             = 1
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM (
                               SELECT D.OPERATION_GROUP
                                    , D.PROJECT_CODE
                                    , D.ITEM_ID
                                    , D.TO_SITE
                                    , D.INCOTERMS
                                    , D.FROM_SITE
                                    , D.BOD_ID
                                    , D.MEASURE
                                    , D.YYYYMMDD
                                 FROM GT_TANL_OS_RESULT_FG D
                                    , GT_TANL_OS_RESULT_FG_SMMR E
                                WHERE D.ITEM_ID      = E.ITEM_ID(+)
                                  AND D.BOD_ID       = E.BOD_ID(+)
                                  AND E.ITEM_ID IS NULL
                                  AND D.PROJECT_CODE = '/'
                              ) XB
                        WHERE XB.OPERATION_GROUP = A.BIZ_TYPE
                          AND XB.PROJECT_CODE    = A.PROJECT_CODE
                          AND XB.ITEM_ID         = A.ITEM_ID
                          AND XB.TO_SITE         = A.TO_SITE
                          AND XB.INCOTERMS       = A.INCOTERMS
                          AND XB.FROM_SITE       = A.FROM_SITE
                          AND XB.BOD_ID          = A.BOD_ID
                          AND XB.MEASURE         = A.MEASURE
                          AND XB.YYYYMMDD        = A.YYYYMMDD
                      )
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        /* MERGE → ② WHEN NOT MATCHED : INSERT */
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , XA.OPERATION_GROUP
             , XA.PROJECT_CODE    --OSF를 만들 때 '-'로 넣었음
             , XA.ITEM_ID
             , XA.TO_SITE
             , XA.INCOTERMS
             , XA.FROM_SITE
             , XA.BOD_ID
             , XA.MEASURE
             , XA.YYYYMMDD
             , XA.QTY
             , XA.ORIGIN_FROM_DIVISION_ID
             , XA.ORIGIN_TO_DIVISION_ID
             , XA.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM (
                SELECT A.OPERATION_GROUP
                     , A.PROJECT_CODE
                     , A.ITEM_ID
                     , A.TO_SITE
                     , A.INCOTERMS
                     , A.FROM_SITE
                     , A.BOD_ID
                     , A.MEASURE
                     , A.YYYYMMDD
                     , A.QTY
                     , A.ORIGIN_FROM_DIVISION_ID
                     , A.ORIGIN_TO_DIVISION_ID
                     , A.ELECTRODE_TYPE
                  FROM GT_TANL_OS_RESULT_FG A
                     , GT_TANL_OS_RESULT_FG_SMMR B
                 WHERE A.ITEM_ID      = B.ITEM_ID(+)
                   AND A.BOD_ID       = B.BOD_ID(+)
                   AND B.ITEM_ID IS NULL
                   AND A.PROJECT_CODE = '/'
               ) XA
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_SHIPMENT_PLAN_FG C
                            WHERE C.BIZ_TYPE            = XA.OPERATION_GROUP
                              AND C.PROJECT_CODE        = XA.PROJECT_CODE
                              AND C.ITEM_ID             = XA.ITEM_ID
                              AND C.TO_SITE             = XA.TO_SITE
                              AND C.INCOTERMS           = XA.INCOTERMS
                              AND C.FROM_SITE           = XA.FROM_SITE
                              AND C.BOD_ID              = XA.BOD_ID
                              AND C.MEASURE             = XA.MEASURE
                              AND C.YYYYMMDD            = XA.YYYYMMDD
                              AND C.DIVISION_ID         = V_DIVISION_ID
                              AND C.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND C.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND C.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND C.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );

        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_TO_DIVISION_ID
             , ORIGIN_FROM_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
