             )
        SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H.NEXTVAL AS HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , BIZ_TYPE
             , PROJECT_CODE
             , ITEM_ID
             , TO_SITE
             , INCOTERMS
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_FROM_DIVISION_ID   /* AS-IS 그대로 : 목록은 TO·FROM 순, 값은 FROM·TO 순(위치 대응) */
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE AS HISTORY_CREATION_DATE
          FROM SCP_ANL_SHIPMENT_PLAN_FG
         WHERE MEASURE             IN ('SHIP_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;
        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET A.QTY              = (SELECT B.QTY
                                       FROM GT_TANL_OS_RESULT_FG B
                                      WHERE B.OPERATION_GROUP = A.BIZ_TYPE
                                        AND B.ITEM_ID         = A.ITEM_ID
                                        AND B.TO_SITE         = A.TO_SITE
                                        AND B.FROM_SITE       = A.FROM_SITE
                                        AND B.BOD_ID          = A.BOD_ID
                                        AND B.YYYYMMDD        = A.YYYYMMDD
                                        AND B.PROJECT_CODE    = A.PROJECT_CODE
                                        AND ROWNUM            = 1   /* 원천 중복 가능(INCOTERMS·BOD_TYPE 축), AS-IS 비결정 */
                                    )
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_OS_RESULT_FG C
                        WHERE C.OPERATION_GROUP = A.BIZ_TYPE
                          AND C.ITEM_ID         = A.ITEM_ID
                          AND C.TO_SITE         = A.TO_SITE
                          AND C.FROM_SITE       = A.FROM_SITE
                          AND C.BOD_ID          = A.BOD_ID
                          AND C.YYYYMMDD        = A.YYYYMMDD
                          AND C.PROJECT_CODE    = A.PROJECT_CODE
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
             ( HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , BIZ_TYPE
             , ITEM_ID
             , TO_SITE
             , FROM_SITE
             , BOD_ID
             , YYYYMMDD
             , PROJECT_CODE
             , INCOTERMS
             , QTY
             , FIX_REASON
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
