             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL -- 원본에서 SCP_ANL_SHIPMENT_PLAN_FIX_H의 SEQ를 SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H로 생성 중.
             , FIX_ID
             , DIVISION_ID
             , BIZ_TYPE
             , ITEM_ID
             , TO_SITE
             , FROM_SITE
             , BOD_ID
             , YYYYMMDD
             , PROJECT_CODE
             , INCOTERMS
             , QTY
             , FIX_REASON
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_SHIPMENT_PLAN_FIX
         WHERE DIVISION_ID      = V_DIVISION_ID
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY  = V_UPDATE_NAME
           AND LAST_UPDATE_DATE = V_NOW_DATE;

    ------------------------------------------------------------------------
    -- UPDATE SCP_XLS_PSI_GLOBAL
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- 52주 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TANL_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE             AS TRG_DATE
             , B.DIVISION_ID
             , B.PLAN_START_YYYYMMDD
             , B.PLAN_TYPE
             , TO_CHAR(B.SEQ)          AS SEQ
             , B.OPERATION_GROUP
             , B.SCM_SITE_ID
             , B.ITEM_ID
             , B.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , CASE WHEN B.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN B.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                     AS MEASURE
             , SUM(NVL(B.QTY,0))       AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(A.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(A.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(A.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(A.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(A.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(A.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , A.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN B
         WHERE IA.BASIS_YYYYMMDD     = B.YYYYMMDD(+)
           AND B.MEASURE             = 'PROD_PLAN_AMEND'
           AND B.QTY                != 0
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND B.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
         GROUP BY IA.TRG_DATE
                , B.DIVISION_ID
                , B.PLAN_START_YYYYMMDD
                , B.PLAN_TYPE
                , B.SEQ
                , B.OPERATION_GROUP
                , B.SCM_SITE_ID
                , B.ITEM_ID
                , B.LINE_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IB.WEEK_NUM             AS TRG_DATE
             , D.DIVISION_ID
             , D.PLAN_START_YYYYMMDD
             , D.PLAN_TYPE
             , TO_CHAR(D.SEQ)          AS SEQ
             , D.OPERATION_GROUP
             , D.SCM_SITE_ID
             , D.ITEM_ID
             , D.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , CASE WHEN D.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN D.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                     AS MEASURE
             , SUM(D.QTY)              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(C.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(C.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(C.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(C.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(C.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(C.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , C.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE C.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IB
             , SCP_ANL_PRODUCTION_PLAN D
         WHERE IB.BASIS_YYYYMMDD     = D.YYYYMMDD(+)
           AND D.MEASURE             = 'PROD_PLAN_AMEND'
           AND D.QTY                != 0
           AND D.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND D.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
         GROUP BY IB.WEEK_NUM
                , D.DIVISION_ID
                , D.PLAN_START_YYYYMMDD
                , D.PLAN_TYPE
                , D.SEQ
                , D.OPERATION_GROUP
                , D.SCM_SITE_ID
                , D.ITEM_ID
                , D.LINE_ID

        ------------------------------------------------------------------------
        -- Get Daily SCP_ANL_SHIPMENT_PLAN_SEMI data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IC.TRG_DATE             AS TRG_DATE
             , F.DIVISION_ID
             , F.PLAN_START_YYYYMMDD
             , F.PLAN_TYPE
             , TO_CHAR(F.SEQ)          AS SEQ
             , F.OPERATION_GROUP
             , F.FROM_SITE
             , F.ITEM_ID
             , '-'                     AS LINE_ID
             , F.BOD_ID
             , '/'                     AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'        AS MEASURE
             , SUM(NVL(F.QTY,0))       AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(E.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(E.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(E.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(E.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(E.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(E.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY E.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , E.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M E
                 WHERE E.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IC
             , SCP_ANL_SHIPMENT_PLAN_SEMI F
         WHERE IC.BASIS_YYYYMMDD     = F.YYYYMMDD(+)
           AND F.MEASURE             = 'SHIP_PLAN_AMEND'
           AND F.QTY                != 0
           AND F.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND F.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND F.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9      = 'U'
         GROUP BY IC.TRG_DATE
                , F.DIVISION_ID
                , F.PLAN_START_YYYYMMDD
                , F.PLAN_TYPE
                , F.SEQ
                , F.OPERATION_GROUP
                , F.FROM_SITE
                , F.ITEM_ID
                , F.BOD_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT ID.WEEK_NUM             AS TRG_DATE
             , H.DIVISION_ID
             , H.PLAN_START_YYYYMMDD
             , H.PLAN_TYPE
             , TO_CHAR(H.SEQ)          AS SEQ
             , H.OPERATION_GROUP
             , H.FROM_SITE
             , H.ITEM_ID
             , '-'                     AS LINE_ID
             , H.BOD_ID
             , '/'                     AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'        AS MEASURE
             , SUM(H.QTY)              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(G.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(G.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(G.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(G.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(G.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(G.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , G.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M G
                 WHERE G.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) ID
             , SCP_ANL_SHIPMENT_PLAN_SEMI H
         WHERE ID.BASIS_YYYYMMDD     = H.YYYYMMDD(+)
           AND H.MEASURE             = 'SHIP_PLAN_AMEND'
           AND H.QTY                != 0
           AND H.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9 ='U'
           AND H.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND H.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
         GROUP BY ID.WEEK_NUM
                , H.DIVISION_ID
                , H.PLAN_START_YYYYMMDD
                , H.PLAN_TYPE
                , H.SEQ
                , H.OPERATION_GROUP
                , H.FROM_SITE
                , H.ITEM_ID
                , H.BOD_ID
        ------------------------------------------------------------------------
        -- Get Daily SCP_ANL_SHIPMENT_PLAN_FG data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IE.TRG_DATE             AS TRG_DATE
             , J.DIVISION_ID
             , J.PLAN_START_YYYYMMDD
             , J.PLAN_TYPE
             , TO_CHAR(J.SEQ)          AS SEQ
             , J.BIZ_TYPE              AS OPERATION_GROUP
             , J.FROM_SITE
             , J.ITEM_ID
             , '-'                     AS LINE_ID
             , J.BOD_ID
             , J.PROJECT_CODE
             , 'SHIP_PLAN'             AS MEASURE
             , SUM(NVL(J.QTY,0))       AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(I.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(I.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(I.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(I.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(I.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(I.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY I.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , I.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M I
                 WHERE I.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IE
             , SCP_ANL_SHIPMENT_PLAN_FG J
         WHERE IE.BASIS_YYYYMMDD     = J.YYYYMMDD(+)
           AND J.MEASURE             = 'SHIP_PLAN_AMEND'
           AND J.QTY                != 0
           AND J.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND J.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND J.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASF.ATTRIBUTE9 ='U'
         GROUP BY IE.TRG_DATE
                , J.DIVISION_ID
                , J.PLAN_START_YYYYMMDD
                , J.PLAN_TYPE
                , J.SEQ
                , J.BIZ_TYPE
                , J.FROM_SITE
                , J.ITEM_ID
                , J.BOD_ID
                , J.PROJECT_CODE
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN_FG data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IZ.WEEK_NUM             AS TRG_DATE
             , L.DIVISION_ID
             , L.PLAN_START_YYYYMMDD
             , L.PLAN_TYPE
             , TO_CHAR(L.SEQ)          AS SEQ
             , L.BIZ_TYPE              AS OPERATION_GROUP
             , L.FROM_SITE
             , L.ITEM_ID
             , '-'                     AS LINE_ID
             , L.BOD_ID
             , L.PROJECT_CODE
             , 'SHIP_PLAN'             AS MEASURE
             , SUM(L.QTY)              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD        AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(K.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(K.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(K.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(K.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(K.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(K.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , K.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M K
                 WHERE K.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IZ
             , SCP_ANL_SHIPMENT_PLAN_FG L
         WHERE IZ.BASIS_YYYYMMDD     = L.YYYYMMDD(+)
           AND L.MEASURE             = 'SHIP_PLAN_AMEND'
           AND L.QTY                != 0
           AND L.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASF.ATTRIBUTE9 ='U'
           AND L.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND L.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
         GROUP BY IZ.WEEK_NUM
                , L.DIVISION_ID
                , L.PLAN_START_YYYYMMDD
                , L.PLAN_TYPE
                , L.SEQ
                , L.BIZ_TYPE
                , L.FROM_SITE
                , L.ITEM_ID
                , L.BOD_ID
                , L.PROJECT_CODE
        ------------------------------------------------------------------------
        -- Get Daily CHAR data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IG.TRG_DATE                                    AS TRG_DATE
             , IH.DIVISION_ID
             , IH.PLAN_START_YYYYMMDD
             , IH.PLAN_TYPE
             , IH.SEQ
             , IH.OPERATION_GROUP
             , IH.FROM_SITE
             , II.ITEM_ID_ASSY                                AS ITEM_ID
             , '-'                                            AS LINE_ID
             , '-'                                            AS BOD_ID
             , '/'                                            AS PROJECT_CODE
             , 'CELL_CHAR_PLAN'                               AS MEASURE
             , SUM(CAST(TO_NUMBER(IH.QTY) AS NUMBER(20,10)))  AS QTY_SUM
             , P_PLAN_START_YYYYMMDD                    AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(M.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(M.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(M.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(M.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(M.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(M.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY M.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , M.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M M
                 WHERE M.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IG
             , (
                SELECT V_DIVISION_ID         AS DIVISION_ID
                     , P_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
                     , V_SCP_PLAN_TYPE       AS PLAN_TYPE
                     , V_SCP_PLAN_SEQ        AS SEQ
                     , O.OPERATION_GROUP     AS OPERATION_GROUP
                     , N.SITE_ID             AS FROM_SITE
                     , N.ITEM_ID             AS ITEM_ID
                     , N.GRADE               AS GRADE
                     , N.START_DATE          AS YYYYMMDD
                     , N.OUT_QTY_INT         AS QTY
                  FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN N
                     , SCP_MST_FINAL_ITEM O
                 WHERE O.ITEM_ID     = N.ITEM_ID
                   AND N.GRADE IN ('CHAR')
                   AND O.DIVISION_ID = V_DIVISION_ID
                   AND N.PLAN_ID     = V_PLAN_ID
               ) IH
             , (
                SELECT DISTINCT P.ITEM_ID_PROD
                     , P.ITEM_ID_ASSY
                  FROM SCP_MST_CELL_PROD_ASSY_MAP P
                 WHERE P.CELL_TYPE   = 'CA1'
                   AND P.DIVISION_ID = V_DIVISION_ID
               ) II
         WHERE IG.BASIS_YYYYMMDD = IH.YYYYMMDD(+)
           AND IH.ITEM_ID        = II.ITEM_ID_PROD
           AND CAST(TO_NUMBER(IH.QTY) AS NUMBER(20,10)) != 0
         GROUP BY IG.TRG_DATE
                , IH.DIVISION_ID
                , IH.PLAN_START_YYYYMMDD
                , IH.PLAN_TYPE
                , IH.SEQ
                , IH.OPERATION_GROUP
                , IH.FROM_SITE
                , II.ITEM_ID_ASSY
        ------------------------------------------------------------------------
        -- Get Weekly CHAR data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IJ.WEEK_NUM                                    AS TRG_DATE
             , IK.DIVISION_ID
             , IK.PLAN_START_YYYYMMDD
             , IK.PLAN_TYPE
             , IK.SEQ
             , IK.OPERATION_GROUP
             , IK.FROM_SITE
             , IL.ITEM_ID_ASSY                                AS ITEM_ID
             , '-'                                            AS LINE_ID
             , '-'                                            AS BOD_ID
             , '/'                                            AS PROJECT_CODE
             , 'CELL_CHAR_PLAN'                               AS MEASURE
             , SUM(CAST(TO_NUMBER(IK.QTY) AS NUMBER(20,10)))  AS QTY_SUM
             , P_PLAN_START_YYYYMMDD                    AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(Q.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(Q.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(Q.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(Q.ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(Q.ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(Q.ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , Q.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M Q
                 WHERE Q.BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IJ
             , (
                SELECT V_DIVISION_ID         AS DIVISION_ID
                     , P_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
                     , V_SCP_PLAN_TYPE       AS PLAN_TYPE
                     , V_SCP_PLAN_SEQ        AS SEQ
                     , S.OPERATION_GROUP     AS OPERATION_GROUP
                     , R.SITE_ID             AS FROM_SITE
                     , R.ITEM_ID             AS ITEM_ID
                     , R.GRADE               AS GRADE
                     , R.START_DATE          AS YYYYMMDD
                     , R.OUT_QTY_INT         AS QTY
                  FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN R
                     , SCP_MST_FINAL_ITEM S
                 WHERE S.ITEM_ID     = R.ITEM_ID
                   AND R.GRADE IN ( 'CHAR')
                   AND S.DIVISION_ID = V_DIVISION_ID
                   AND R.PLAN_ID     = V_PLAN_ID
               ) IK
             , (
                SELECT DISTINCT T.ITEM_ID_PROD
                     , T.ITEM_ID_ASSY
                  FROM SCP_MST_CELL_PROD_ASSY_MAP T
                 WHERE T.CELL_TYPE   = 'CA1'
                   AND T.DIVISION_ID = V_DIVISION_ID
               ) IL
         WHERE IJ.BASIS_YYYYMMDD = IK.YYYYMMDD(+)
           AND IK.ITEM_ID        = IL.ITEM_ID_PROD
           AND CAST(TO_NUMBER(IK.QTY) AS NUMBER(20,10)) != 0
         GROUP BY IJ.WEEK_NUM
                , IK.DIVISION_ID
                , IK.PLAN_START_YYYYMMDD
                , IK.PLAN_TYPE
                , IK.SEQ
                , IK.OPERATION_GROUP
                , IK.FROM_SITE
                , IL.ITEM_ID_ASSY;
        ------------------------------------------------------------------------
        -- 52주 이후 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TANL_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE             AS TRG_DATE
             , B.DIVISION_ID
             , B.PLAN_START_YYYYMMDD
             , B.PLAN_TYPE
             , TO_CHAR(B.SEQ)          AS SEQ
             , B.OPERATION_GROUP
             , B.SCM_SITE_ID
             , B.ITEM_ID
             , B.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , CASE WHEN B.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN B.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                     AS MEASURE
             , SUM(NVL(B.QTY,0))       AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD    AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(A.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(A.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(A.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(A.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(A.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(A.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY A.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , A.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M A
                 WHERE A.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN B
         WHERE IA.BASIS_YYYYMMDD     = B.YYYYMMDD(+)
           AND B.MEASURE             = 'PROD_PLAN_AMEND'
           AND B.QTY                != 0
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND B.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
         GROUP BY IA.TRG_DATE
                , B.DIVISION_ID
                , B.PLAN_START_YYYYMMDD
                , B.PLAN_TYPE
                , B.SEQ
                , B.OPERATION_GROUP
                , B.SCM_SITE_ID
                , B.ITEM_ID
                , B.LINE_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IB.WEEK_NUM             AS TRG_DATE
             , D.DIVISION_ID
             , D.PLAN_START_YYYYMMDD
             , D.PLAN_TYPE
             , TO_CHAR(D.SEQ)          AS SEQ
             , D.OPERATION_GROUP
             , D.SCM_SITE_ID
             , D.ITEM_ID
             , D.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , CASE WHEN D.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN D.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                     AS MEASURE
             , SUM(D.QTY)              AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD    AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(C.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(C.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(C.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(C.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(C.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(C.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , C.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M C
                 WHERE C.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IB
             , SCP_ANL_PRODUCTION_PLAN D
         WHERE IB.BASIS_YYYYMMDD     = D.YYYYMMDD(+)
           AND D.MEASURE             = 'PROD_PLAN_AMEND'
           AND D.QTY                != 0
           AND D.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND D.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
         GROUP BY IB.WEEK_NUM
                , D.DIVISION_ID
                , D.PLAN_START_YYYYMMDD
                , D.PLAN_TYPE
                , D.SEQ
                , D.OPERATION_GROUP
                , D.SCM_SITE_ID
                , D.ITEM_ID
                , D.LINE_ID

