                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY E.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , E.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M E
                 WHERE E.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IC
