          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(G.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(G.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(G.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(G.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(G.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(G.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , G.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M G
                 WHERE G.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) ID
