                     , K.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M K
                 WHERE K.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IZ
             , SCP_ANL_SHIPMENT_PLAN_FG L
         WHERE IZ.BASIS_YYYYMMDD     = L.YYYYMMDD(+)
           AND L.MEASURE             = 'SHIP_PLAN_AMEND'
           AND L.QTY                != 0
           AND L.LAST_UPDATED_BY     = V_UPDATE_NAME
