        ------------------------------------------------------------------------
        -- Get Daily CHAR data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IG.TRG_DATE                                    AS TRG_DATE
             , IH.DIVISION_ID
             , IH.PLAN_START_YYYYMMDD
             , IH.PLAN_TYPE
             , IH.SEQ
             , IH.OPERATION_GROUP
             , IH.FROM_SITE
             , II.ITEM_ID_ASSY                                AS ITEM_ID
             , '-'                                            AS LINE_ID
             , '-'                                            AS BOD_ID
             , '/'                                            AS PROJECT_CODE
             , 'CELL_CHAR_PLAN'                               AS MEASURE
             , SUM(CAST(TO_NUMBER(IH.QTY) AS NUMBER(20,10)))  AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD                AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(M.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(M.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(M.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(M.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(M.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(M.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY M.BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , M.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M M
                 WHERE M.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IG
             , (
                SELECT V_DIVISION_ID         AS DIVISION_ID
                     , P_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
                     , V_SCP_PLAN_TYPE       AS PLAN_TYPE
                     , V_SCP_PLAN_SEQ        AS SEQ
                     , O.OPERATION_GROUP     AS OPERATION_GROUP
                     , N.SITE_ID             AS FROM_SITE
                     , N.ITEM_ID             AS ITEM_ID
                     , N.GRADE               AS GRADE
                     , N.START_DATE          AS YYYYMMDD
                     , N.OUT_QTY_INT         AS QTY
                  FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN N
                     , SCP_MST_FINAL_ITEM O
                 WHERE O.ITEM_ID     = N.ITEM_ID
                   AND N.GRADE IN ('CHAR')
                   AND O.DIVISION_ID = V_DIVISION_ID
                   AND N.PLAN_ID     = V_PLAN_ID
               ) IH
             , (
                SELECT DISTINCT P.ITEM_ID_PROD
                     , P.ITEM_ID_ASSY
                  FROM SCP_MST_CELL_PROD_ASSY_MAP P
                 WHERE P.CELL_TYPE   = 'CA1'
                   AND P.DIVISION_ID = V_DIVISION_ID
               ) II
         WHERE IG.BASIS_YYYYMMDD = IH.YYYYMMDD(+)
           AND IH.ITEM_ID        = II.ITEM_ID_PROD
           AND CAST(TO_NUMBER(IH.QTY) AS NUMBER(20,10)) != 0
         GROUP BY IG.TRG_DATE
                , IH.DIVISION_ID
                , IH.PLAN_START_YYYYMMDD
                , IH.PLAN_TYPE
                , IH.SEQ
                , IH.OPERATION_GROUP
                , IH.FROM_SITE
                , II.ITEM_ID_ASSY
        ------------------------------------------------------------------------
        -- Get Weekly CHAR data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IJ.WEEK_NUM                                    AS TRG_DATE
             , IK.DIVISION_ID
             , IK.PLAN_START_YYYYMMDD
             , IK.PLAN_TYPE
             , IK.SEQ
             , IK.OPERATION_GROUP
             , IK.FROM_SITE
             , IL.ITEM_ID_ASSY                                AS ITEM_ID
             , '-'                                            AS LINE_ID
             , '-'                                            AS BOD_ID
             , '/'                                            AS PROJECT_CODE
             , 'CELL_CHAR_PLAN'                               AS MEASURE
             , SUM(CAST(TO_NUMBER(IK.QTY) AS NUMBER(20,10)))  AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD                AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT CASE WHEN LPAD(TO_CHAR(CASE WHEN TO_NUMBER(Q.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(Q.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(Q.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') IS NULL THEN NULL ELSE 'WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(Q.ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(Q.ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(Q.ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0') END AS WEEK_NUM   /* AS-IS 문자 + : NULL 이면 NULL */
                     , Q.BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M Q
                 WHERE Q.BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IJ
             , (
                SELECT V_DIVISION_ID         AS DIVISION_ID
                     , P_PLAN_START_YYYYMMDD AS PLAN_START_YYYYMMDD
                     , V_SCP_PLAN_TYPE       AS PLAN_TYPE
                     , V_SCP_PLAN_SEQ        AS SEQ
                     , S.OPERATION_GROUP     AS OPERATION_GROUP
                     , R.SITE_ID             AS FROM_SITE
                     , R.ITEM_ID             AS ITEM_ID
                     , R.GRADE               AS GRADE
                     , R.START_DATE          AS YYYYMMDD
                     , R.OUT_QTY_INT         AS QTY
                  FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN R
                     , SCP_MST_FINAL_ITEM S
                 WHERE S.ITEM_ID     = R.ITEM_ID
                   AND R.GRADE IN ( 'CHAR')
                   AND S.DIVISION_ID = V_DIVISION_ID
                   AND R.PLAN_ID     = V_PLAN_ID
               ) IK
             , (
                SELECT DISTINCT T.ITEM_ID_PROD
                     , T.ITEM_ID_ASSY
                  FROM SCP_MST_CELL_PROD_ASSY_MAP T
                 WHERE T.CELL_TYPE   = 'CA1'
                   AND T.DIVISION_ID = V_DIVISION_ID
               ) IL
         WHERE IJ.BASIS_YYYYMMDD = IK.YYYYMMDD(+)
           AND IK.ITEM_ID        = IL.ITEM_ID_PROD
           AND CAST(TO_NUMBER(IK.QTY) AS NUMBER(20,10)) != 0
         GROUP BY IJ.WEEK_NUM
                , IK.DIVISION_ID
                , IK.PLAN_START_YYYYMMDD
                , IK.PLAN_TYPE
                , IK.SEQ
                , IK.OPERATION_GROUP
                , IK.FROM_SITE
                , IL.ITEM_ID_ASSY;


