                     WHERE B.DIVISION_ID          = A.DIVISION_ID
                       AND B.PLAN_START_YYYYMMDD  = A.PLAN_START_YYYYMMDD
                       AND B.PLAN_TYPE            = A.PLAN_TYPE
                       AND TO_NUMBER(B.SEQ)       = A.SEQ
                       AND B.OPERATION_GROUP      = A.OPERATION_GROUP
                       AND B.FROM_SITE            = A.FROM_SITE
                       AND B.ITEM_ID              = A.ITEM_ID
                       AND B.LINE_ID              = A.PROD_LINE
                       AND B.BOD_ID               = A.BOD_ID
                       AND B.MEASURE              = A.MEASURE
                       AND B.PROJECT_CODE         = A.PROJECT_CODE
                       AND B.CREATE_FROM_YYYYMMDD = A.CREATE_FROM_YYYYMMDD
                       AND ROWNUM                 = 1   /* PIVOT 결과는 조인 키 12개로 유일. 안전장치 */
                   )
         WHERE EXISTS (SELECT 1
                         FROM GT_TANL_XLS_PV_TABLE C
                        WHERE C.DIVISION_ID          = A.DIVISION_ID
                          AND C.PLAN_START_YYYYMMDD  = A.PLAN_START_YYYYMMDD
                          AND C.PLAN_TYPE            = A.PLAN_TYPE
                          AND TO_NUMBER(C.SEQ)       = A.SEQ
                          AND C.OPERATION_GROUP      = A.OPERATION_GROUP
                          AND C.FROM_SITE            = A.FROM_SITE
                          AND C.ITEM_ID              = A.ITEM_ID
                          AND C.LINE_ID              = A.PROD_LINE
                          AND C.BOD_ID               = A.BOD_ID
                          AND C.MEASURE              = A.MEASURE
