    V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                          ELSE P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
                     END;
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    ------------------------------------------------------------------------
    -- Data Insert End
    ------------------------------------------------------------------------
        COMMIT;   /* COMMIT TRAN */
	/* END TRY */
	------------------------------------------------------------------------
    EXCEPTION   /* BEGIN CATCH */
        WHEN OTHERS THEN
	------------------------------------------------------------------------
	--ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC;
	------------------------------------------------------------------------
            ROLLBACK;

	    ------------------------------------------------------------------------
          -- ERROR LOG
	    ------------------------------------------------------------------------
            V_LOG_TYPE    := 'ERROR';
            V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
            V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                                  ELSE 'ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 200) || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
                             END;
            V_EVENT_DATE  := SYSDATE;
	    --SELECT '' + Convert(NVARCHAR(10), ERROR_NUMBER()) + '' + ERROR_MESSAGE();
	    ------------------------------------------------------------------------
            INSERT INTO SCM_SYS_LOG_BATCH
                 ( PROGRAM_NAME
                 , LOG_TYPE
                 , LOG_COUNT
                 , LOG_MESSAGE
                 , DESCRIPTION
                 , EVENT_DATE
                 , CREATION_DATE
                 , CREATED_BY
                 , LAST_UPDATE_DATE
                 , LAST_UPDATED_BY
                 )
            VALUES
                 ( 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL'   /* ERROR_PROCEDURE() */
                 , V_LOG_TYPE
                 , NULL
                 , V_LOG_MESSAGE
                 , V_DESCRIPTION
                 , SYSDATE
                 , SYSDATE
                 , 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL'   /* ERROR_PROCEDURE() */
                 , SYSDATE
                 , 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL'   /* ERROR_PROCEDURE() */
                 );
	    --EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
	    ------------------------------------------------------------------------
            COMMIT;
            V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
            DBMS_OUTPUT.PUT_LINE(V_MESSAGE_TEXT);   /* SELECT @V_MESSAGE_TEXT */
            RAISE;   /* THROW */

    END;   /* END CATCH */

	------------------------------------------------------------------------

    ------------------------------------------------------------------------
END PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL;
/
SHOW ERRORS PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL
