-- ##### START PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE
CREATE OR REPLACE PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE
(
    P_PLAN_ID             IN VARCHAR2
  , P_PLAN_START_YYYYMMDD IN VARCHAR2
)
IS
    /******************************************************************************
     * Program Name : PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE
     * Description  : 전극 엔진 결과(생산) → SCP_ANL_PRODUCTION_PLAN / FIX 반영 및 SCP_XLS_PSI_GLOBAL_ELECTRODE 갱신
     *                (AS-IS 첫 주석 : 2025.02.07 Initial Release)
     * Program History
     * 2026.10.06   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     ******************************************************************************/
    --2025.02.07 Taehyun Initial Release
	------------------------------------------------------------------------
    -- Procedure 기본조건.
	------------------------------------------------------------------------
	------------------------------------------------------------------------

	------------------------------------------------------------------------
	-- Set Param for Log
	------------------------------------------------------------------------
    V_PROGRAM_NAME           VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE';
    V_PLAN_ID                VARCHAR2(50 CHAR)  := SUBSTR(P_PLAN_ID, 1, 50);
    V_MESSAGE_TEXT           VARCHAR2(1000 CHAR);
    ------------------------------------------------------------------------
	-- LOG 용 변수 설정
	------------------------------------------------------------------------
    --DECLARE @v_program_name NVARCHAR(150) = 'PR_SCM_LGTM_INV_ALLOCATION';
    V_LOG_TYPE               VARCHAR2(30 CHAR); -- START/END/ERROR/...
    V_LOG_COUNT              NUMBER := 0;
    V_LOG_MESSAGE            VARCHAR2(1000 CHAR);
    V_DESCRIPTION            VARCHAR2(500 CHAR);
    V_EVENT_DATE             DATE;
    ---------------------   ---------------------------------------------------
    -- Set Param for Biz
    ------------------------------------------------------------------------
    V_SCP_PLAN_DATE          VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE          VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ           VARCHAR2(8 CHAR);
    V_SCP_PLAN_CYCLE         VARCHAR2(100 CHAR);
    V_SCP_PLAN_ID            VARCHAR2(100 CHAR);
    V_SCP_MODELING_ID        VARCHAR2(100 CHAR);
    V_SCP_MASTER_ID          VARCHAR2(100 CHAR);
    V_SCP_ENGINE_PLAN_ID     VARCHAR2(100 CHAR);

    V_DIVISION_ID            VARCHAR2(10 CHAR);
    V_PLAN_START_YYYYMMDD    VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD      VARCHAR2(8 CHAR);
    V_2ND_PLAN_START_YYYYMMDD VARCHAR2(8 CHAR);
    V_NOW_DATE               DATE;
    V_MIN_WEEK               NUMBER;
    V_2ND_MIN_WEEK           NUMBER;
    -- 2026.07.22 Minyong Lee : 시뮬레이터 I/F 주차 계산 오류 수정 (53주 연도 대응)
    V_WEEKS_IN_YEAR          NUMBER;
    V_2ND_WEEKS_IN_YEAR      NUMBER;
    V_UPDATE_NAME            VARCHAR2(100 CHAR);
    V_OP_COUNT               NUMBER;
    V_CHK_INTEGRAL           VARCHAR2(100 CHAR);
    --속도이슈
    /* 테이블 변수 @MS_TEMP / @CFY_TEMP / @OP_RESULT / @OS_RESULT / @OS_RESULT_FG / @OS_RESULT_FG_SMMR / @XLS_PV_READY / @XLS_PV_TABLE
       → GTT GT_TAEE_MS_TEMP / GT_TAEE_CFY_TEMP / GT_TAEE_OP_RESULT / GT_TAEE_OS_RESULT / GT_TAEE_OS_RESULT_FG / GT_TAEE_OS_RESULT_FG_SMMR / GT_TAEE_XLS_PV_READY / GT_TAEE_XLS_PV_TABLE
       (DDL : (DDL) 00_GTT_TAEE_SCP0123.sql) */
BEGIN
    /* GTT 초기화 (TRUNCATE 금지 : 암묵적 커밋) */
    DELETE FROM GT_TAEE_MS_TEMP;
    DELETE FROM GT_TAEE_CFY_TEMP;
    DELETE FROM GT_TAEE_OP_RESULT;
    DELETE FROM GT_TAEE_OS_RESULT;
    DELETE FROM GT_TAEE_OS_RESULT_FG;
    DELETE FROM GT_TAEE_OS_RESULT_FG_SMMR;
    DELETE FROM GT_TAEE_XLS_PV_READY;
    DELETE FROM GT_TAEE_XLS_PV_TABLE;

	------------------------------------------------------------------------
	-- LOG 시작
	------------------------------------------------------------------------
	V_LOG_TYPE    := 'START';
	V_LOG_MESSAGE := '########## Start of procedure ##########';
	V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL /* MSSQL 문자 + NULL = NULL */
	                      ELSE 'START_' || V_PROGRAM_NAME || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
	                 END;
	V_EVENT_DATE  := SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
	------------------------------------------------------------------------

    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_MIN_WEEK := NULL;
    END;
    V_UPDATE_NAME := CASE WHEN V_PLAN_ID IS NULL THEN NULL ELSE 'OPT_ENG_' || V_PLAN_ID END;
    --52주 이후 구간의 데이터를 GLOBAL 테이블에 넣기 위한 변수 설정
    V_2ND_PLAN_START_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');
    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_2ND_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_2ND_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_2ND_MIN_WEEK := NULL;
    END;

    -- 2026.07.22 Minyong Lee : 시뮬레이터 I/F 주차 계산 오류 수정 (53주 연도 대응)
    -- 섹션1 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD LIKE SUBSTR(P_PLAN_START_YYYYMMDD, 1, 4) || '%'; /* LEFT(BASIS_YYYYMMDD,4) = LEFT(@PLAN_START_YYYYMMDD,4) */
    -- 섹션2(52주 이후 구간) 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_2ND_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD LIKE SUBSTR(V_2ND_PLAN_START_YYYYMMDD, 1, 4) || '%'; /* LEFT(BASIS_YYYYMMDD,4) = LEFT(@2ND_PLAN_START_YYYYMMDD,4) */

    V_NOW_DATE := SYSDATE;
    --SELECT  @V_DIVISION_ID = DIVISION_ID
    --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
    --       ,@V_PLAN_END_YYYYMMDD   = PLAN_END_YYYYMMDD
    --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
    --WHERE   1=1
    --AND     PLAN_ID = @V_PLAN_ID

    --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
    --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
    --        ,@V_PLAN_END_YYYYMMDD   = PM.PLAN_END_YYYYMMDD
    --FROM    SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
    --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID

    BEGIN
        SELECT SUBSTR(IA.DIVISION_ID, 1, 10)
             , SUBSTR(IA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(IA.PLAN_END_YYYYMMDD, 1, 8)
          INTO V_DIVISION_ID
             , V_PLAN_START_YYYYMMDD
             , V_PLAN_END_YYYYMMDD
          FROM (
                SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_END_YYYYMMDD
                  FROM SCP_OPMZ_PLAN_M
                 WHERE OPMZ_PLAN_ID = V_PLAN_ID
                 UNION
                SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_END_YYYYMMDD
                  FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                 WHERE 1 = 1
                   AND PLAN_ID = V_PLAN_ID
                 /* AS-IS 는 여러 행이면 마지막 행 값(UNION 정렬 결과의 끝 = NULL 이 가장 작은 값) → 내림차순 NULLS LAST 의 첫 행 */
                 ORDER BY DIVISION_ID DESC NULLS LAST
                        , PLAN_START_YYYYMMDD DESC NULLS LAST
                        , PLAN_END_YYYYMMDD DESC NULLS LAST
               ) IA
         WHERE ROWNUM = 1; /* 0행이면 변수 유지(NULL) */
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    BEGIN
        SELECT SUBSTR(IA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(IA.PLAN_TYPE, 1, 8)
             , SUBSTR(TO_CHAR(IA.PLAN_SEQ), 1, 8)
             , IA.PLAN_CYCLE
             , IA.PLAN_ID
             , IA.MODELING_ID
             , SUBSTR(IA.ENG_PLAN_ID, 1, 100)
             , CASE WHEN V_DIVISION_ID IS NULL OR IA.PLAN_CYCLE IS NULL THEN NULL /* MSSQL 문자 + NULL = NULL */
                    ELSE SUBSTR(V_DIVISION_ID || '::' || IA.PLAN_CYCLE, 1, 100)
               END
          INTO V_SCP_PLAN_DATE
             , V_SCP_PLAN_TYPE
             , V_SCP_PLAN_SEQ
             , V_SCP_PLAN_CYCLE
             , V_SCP_PLAN_ID
             , V_SCP_MODELING_ID
             , V_SCP_ENGINE_PLAN_ID
             , V_SCP_MASTER_ID
          FROM (
                SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , PLAN_SEQ
                     , PLAN_TYPE_ORDER
                     , CONFIRM_FLAG
                     , PLAN_CYCLE
                     , PLAN_ID
                     , MODELING_ID
                     , ENG_PLAN_ID
                  FROM SCP_PLAN_VERSION_V
                 WHERE DIVISION_ID         = V_DIVISION_ID
                   AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                -- 2026.03.17 Minyong Lee : FN 이후 TE Plan Type 추가 건 대응
                --ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC
                 ORDER BY
                       CASE WHEN PLAN_TYPE = 'TE' THEN 0 ELSE 1 END ASC
                     , PLAN_TYPE_ORDER DESC NULLS LAST /* MSSQL DESC 의 NULL 위치 */
                     , CONFIRM_FLAG DESC NULLS LAST    /* MSSQL DESC 의 NULL 위치 */
                     , PLAN_SEQ DESC
               ) IA
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    SELECT MAX(PLAN_ID) /* 0행이면 NULL 유지, 여러 행이어도 같은 PLAN_ID */
      INTO V_CHK_INTEGRAL
      FROM SCP_OPT_ENG_PHASES_SN
     WHERE 1 = 1
       AND UPPER(PRINT_RESULT) LIKE '%INTEGRAL%' /* AS-IS LIKE 는 대소문자 무시, 실데이터는 소문자 'integral' */
       AND PLAN_ID = V_PLAN_ID;

    IF (V_SCP_PLAN_TYPE = 'FN') THEN
            ------------------------------------------------------------------------
            -- 종료 LOG
	        ------------------------------------------------------------------------
            V_LOG_TYPE    := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                                  ELSE 'SCP_PLAN_TYPE IS FN' || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
                             END;
            V_EVENT_DATE  := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

            /* SET XACT_ABORT OFF 삭제. TRY 밖 RAISERROR → 즉시 종료(호출자 예외 처리로 전달) */
            RAISE_APPLICATION_ERROR(-20001, ' I/F not executed because PLAN_TYPE is FN.');
    END IF;
    ------------------------------------------------------------------------
	-- Transaction (START)
	------------------------------------------------------------------------
	BEGIN

        ------------------------------------------------------------------------
        -- 엔진 결과에서 문자열 'E'를 붙여서 나오는 데이터 치환
        ------------------------------------------------------------------------
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN
           SET ATTRIBUTE1 = OUT_QTY
             , OUT_QTY    = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY) END))
         WHERE UPPER(OUT_QTY) LIKE '%E%' /* AS-IS LIKE 는 대소문자 무시 */
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN
           SET ATTRIBUTE1  = OUT_QTY_INT
             , OUT_QTY_INT = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY_INT) END))
         WHERE UPPER(OUT_QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN
           SET ATTRIBUTE1 = QTY_INT
             , QTY_INT    = TO_CHAR(ROUND(CASE WHEN UPPER(QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY_INT) END))
         WHERE UPPER(QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN
           SET ATTRIBUTE1 = QTY
             , QTY        = TO_CHAR(ROUND(CASE WHEN UPPER(QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY) END))
         WHERE UPPER(QTY) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;

    ------------------------------------------------------------------------
    -- ORDER_PRODUCTION DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Production Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TAEE_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , E.BASIS_YYYYMMDD                                                                              AS START_DATE
                 , SUM(CASE WHEN E.BASIS_YYYYMMDD = A.START_DATE THEN CAST(TO_NUMBER(A.OUT_QTY) AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY
                 , B.RESOURCE_NAME                                                                               AS LINE_ID
                 , D.SCP_OPERATION_GROUP                                                                         AS OPERATION_GROUP
                 , CASE WHEN D.FLOW_ID LIKE '%E2000%' THEN 'E2000' ELSE D.FLOW_ID END                            AS OPERATION_ID
                 , C.DIVISION_ID                                                                                 AS ORIGIN_DIVISION_ID
                 , CASE WHEN SUBSTR(A.ITEM_ID, 1, 5) = 'APCAN' THEN 'ANODE'
                        WHEN SUBSTR(A.ITEM_ID, 1, 5) = 'APCCA' THEN 'CATHODE'
                   ELSE ''  -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                   END                                                                                           AS ELECTRODE_TYPE /* Oracle 에서 '' 는 NULL */
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN A
                 , (
                    SELECT PRODUCTION_ORDER_ID
                         , PRODUCTION_LINE_ID
                         , PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_SN
                     WHERE PLAN_ID = V_PLAN_ID
                     GROUP BY PRODUCTION_ORDER_ID
                            , PRODUCTION_LINE_ID
                            , PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCM_MST_SITE C
                 , SCM_ITEM_M_SN D
                 , SCM_SYS_CALENDAR_M E
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND A.SITE_ID             = C.SCM_SITE_ID
               AND C.DIVISION_ID         = D.DIVISION_ID
               AND C.COMPANY_ID          = D.COMPANY_ID
               AND C.SITE_ID             = D.SITE_ID
               AND D.ITEM_ID             = A.ITEM_ID
               AND C.VALID_YN            = 'Y'
               AND A.GRADE IN ('COATING')
               AND IA.PLAN_ID IS NOT NULL
               AND A.PLAN_ID             = V_PLAN_ID
               AND E.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , E.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , D.SCP_OPERATION_GROUP
                    , D.FLOW_ID
                    , C.DIVISION_ID;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TAEE_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ORIGIN_DIVISION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , E.BASIS_YYYYMMDD                                                                                  AS START_DATE
                 , SUM(CASE WHEN E.BASIS_YYYYMMDD = A.START_DATE THEN CAST(TO_NUMBER(A.OUT_QTY_INT) AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , B.RESOURCE_NAME                                                                                   AS LINE_ID
                 , D.SCP_OPERATION_GROUP                                                                             AS OPERATION_GROUP
                 , CASE WHEN D.FLOW_ID LIKE '%E2000%' THEN 'E2000' ELSE D.FLOW_ID END                                AS OPERATION_ID
                 , C.DIVISION_ID                                                                                     AS ORIGIN_DIVISION_ID
                 , CASE WHEN SUBSTR(A.ITEM_ID, 1, 5) = 'APCAN' THEN 'ANODE'
                        WHEN SUBSTR(A.ITEM_ID, 1, 5) = 'APCCA' THEN 'CATHODE'
                   ELSE ''  -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                   END                                                                                               AS ELECTRODE_TYPE /* Oracle 에서 '' 는 NULL */
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN A
                 , (
                    SELECT PRODUCTION_ORDER_ID
                         , PRODUCTION_LINE_ID
                         , PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_INT_SN
                     WHERE PLAN_ID = V_PLAN_ID
                     GROUP BY PRODUCTION_ORDER_ID
                            , PRODUCTION_LINE_ID
                            , PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCM_MST_SITE C
                 , SCM_ITEM_M_SN D
                 , SCM_SYS_CALENDAR_M E
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND A.SITE_ID             = C.SCM_SITE_ID
               AND C.DIVISION_ID         = D.DIVISION_ID
               AND C.COMPANY_ID          = D.COMPANY_ID
               AND C.SITE_ID             = D.SITE_ID
               AND D.ITEM_ID             = A.ITEM_ID
               AND C.VALID_YN            = 'Y'
               AND A.GRADE IN ('COATING')
               AND IA.PLAN_ID IS NOT NULL
               AND A.PLAN_ID             = V_PLAN_ID
               AND E.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , E.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , D.SCP_OPERATION_GROUP
                    , D.FLOW_ID
                    , C.DIVISION_ID;
        END IF;

        ------------------------------------------------------------------------
        -- 생산 결과가 없으면 Error 생성
        ------------------------------------------------------------------------
        SELECT COUNT(*)
          INTO V_OP_COUNT
          FROM GT_TAEE_OP_RESULT;

        IF V_OP_COUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20001, 'Order Production count is zero');
        END IF;
        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.SCM_SITE_ID
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;

        DBMS_OUTPUT.PUT_LINE('SCP_ANL_PRODUCTION_PLAN');

        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        /* MERGE → UPDATE(일치) + INSERT(불일치) */
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET A.QTY              = (SELECT B.OUT_QTY_INT
                                       FROM GT_TAEE_OP_RESULT B
                                      WHERE A.OPERATION_GROUP    = B.OPERATION_GROUP
                                        AND A.SCM_SITE_ID        = B.SITE_ID
                                        AND A.ITEM_ID            = B.ITEM_ID
                                        AND A.LINE_ID            = B.LINE_ID
                                        AND A.OPERATION_ID       = B.OPERATION_ID
                                        AND A.YYYYMMDD           = B.START_DATE
                                        AND A.ORIGIN_DIVISION_ID = B.ORIGIN_DIVISION_ID
                                        AND ROWNUM               = 1
                                    )
             , A.LAST_UPDATE_DATE = V_NOW_DATE
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
                      --,ANL.ATTRIBUTE9        = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAEE_OP_RESULT B
                        WHERE A.OPERATION_GROUP    = B.OPERATION_GROUP
                          AND A.SCM_SITE_ID        = B.SITE_ID
                          AND A.ITEM_ID            = B.ITEM_ID
                          AND A.LINE_ID            = B.LINE_ID
                          AND A.OPERATION_ID       = B.OPERATION_ID
                          AND A.YYYYMMDD           = B.START_DATE
                          AND A.ORIGIN_DIVISION_ID = B.ORIGIN_DIVISION_ID
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        INSERT INTO SCP_ANL_PRODUCTION_PLAN
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , B.OPERATION_GROUP
             , B.SITE_ID
             , B.ITEM_ID
             , B.LINE_ID
             , B.OPERATION_ID
             , 'PROD_PLAN_AMEND'
             , B.START_DATE
             , B.OUT_QTY_INT
             , B.ORIGIN_DIVISION_ID
             , B.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM GT_TAEE_OP_RESULT B
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_PRODUCTION_PLAN A
                            WHERE A.OPERATION_GROUP     = B.OPERATION_GROUP
                              AND A.SCM_SITE_ID         = B.SITE_ID
                              AND A.ITEM_ID             = B.ITEM_ID
                              AND A.LINE_ID             = B.LINE_ID
                              AND A.OPERATION_ID        = B.OPERATION_ID
                              AND A.YYYYMMDD            = B.START_DATE
                              AND A.ORIGIN_DIVISION_ID  = B.ORIGIN_DIVISION_ID
                              AND A.MEASURE             IN ('PROD_PLAN_AMEND')
                              AND A.DIVISION_ID         = V_DIVISION_ID
                              AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN
         WHERE MEASURE             IN ('PROD_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;

        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM SCP_OPT_ENG_MODEL_LIST_N_SN B
                        WHERE B.SCM_SITE_ID = A.SCM_SITE_ID
                          AND B.ITEM_ID     = A.ITEM_ID
                          AND B.PLAN_ID     = V_PLAN_ID
                      )
           AND A.QTY         != 0
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- UPDATE SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET A.QTY              = (SELECT B.OUT_QTY_INT
                                       FROM GT_TAEE_OP_RESULT B
                                      WHERE A.OPERATION_GROUP    = B.OPERATION_GROUP
                                        AND A.SCM_SITE_ID        = B.SITE_ID
                                        AND A.ITEM_ID            = B.ITEM_ID
                                        AND A.LINE_ID            = B.LINE_ID
                                        AND A.OPERATION_ID       = B.OPERATION_ID
                                        AND A.YYYYMMDD           = B.START_DATE
                                        AND A.ORIGIN_DIVISION_ID = B.ORIGIN_DIVISION_ID
                                        AND ROWNUM               = 1
                                    )
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, SCP_ANL_PRODUCTION_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAEE_OP_RESULT B
                        WHERE A.OPERATION_GROUP    = B.OPERATION_GROUP
                          AND A.SCM_SITE_ID        = B.SITE_ID
                          AND A.ITEM_ID            = B.ITEM_ID
                          AND A.LINE_ID            = B.LINE_ID
                          AND A.OPERATION_ID       = B.OPERATION_ID
                          AND A.YYYYMMDD           = B.START_DATE
                          AND A.ORIGIN_DIVISION_ID = B.ORIGIN_DIVISION_ID
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
             ( HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN_FIX
         WHERE DIVISION_ID      = V_DIVISION_ID
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY  = V_UPDATE_NAME
           AND LAST_UPDATE_DATE = V_NOW_DATE;
    ------------------------------------------------------------------------
    -- ORDER_SHIPPING SEMI DATA START
    -- 2025.09.18 Philsu Park: 전극 엔진결과는 생산계획만 사용하므로 주석 처리(백선우 책임님 요청)
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        /* IF @CHK_INTEGRAL IS NULL
        BEGIN
            INSERT INTO @OS_RESULT
            SELECT OPERATION_GROUP
                  ,ITEM_ID
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,CM.BASIS_YYYYMMDD
                  ,TO_SITE
                  ,SUM(IIF(CM.BASIS_YYYYMMDD = YYYYMMDD, CONVERT(NUMERIC(30,10), QTY), 0)) AS OUT_QTY_INT
                  ,ORIGIN_FROM_DIVISION_ID
                  ,ORIGIN_TO_DIVISION_ID  
                  ,ELECTRODE_TYPE
                  ,BOD_TYPE
            FROM(
                SELECT IM.SCP_OPERATION_GROUP AS OPERATION_GROUP
                      ,OS.ITEM_ID             AS ITEM_ID
                      ,OS.FROM_SITE_ID        AS FROM_SITE
                      ,BOD.ATTRIBUTE7         AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,OS.DEPARTURE_DATE      AS YYYYMMDD
                      ,OS.TO_SITE_ID          AS TO_SITE
                      ,CONVERT(FLOAT,OS.QTY)  AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,BOD.ATTRIBUTE8         AS BOD_TYPE
                FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN  OS WITH(NOLOCK)
                    INNER JOIN SCP_OPT_ENG_BOD_SN BOD WITH(NOLOCK) 
                        ON  BOD.PLAN_ID = @V_PLAN_ID
                        AND OS.BOD_ID   = BOD.BOD_ID
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  OS.FROM_SITE_ID = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = OS.ITEM_ID
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  OS.TO_SITE_ID   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE 1=1
                AND BOD.ATTRIBUTE8 = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                AND OS.PLAN_ID = @V_PLAN_ID

                UNION ALL
                SELECT IM.SCP_OPERATION_GROUP AS OPERATION_GROUP
                      ,SM.ATTRIBUTE2          AS ITEM_ID
                      ,SM.ATTRIBUTE1          AS FROM_SITE
                      ,SM.ATTRIBUTE7          AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,SM.DEPARTURE_DATE      AS YYYYMMDD
                      ,SM.ATTRIBUTE4          AS TO_SITE
                      ,SM.QUANTITY            AS QTY
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,SM.ATTRIBUTE8          AS BOD_TYPE
                FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SM WITH(NOLOCK)
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  SM.ATTRIBUTE1 = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = SM.ATTRIBUTE2
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  SM.ATTRIBUTE4   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'


                WHERE   SM.PLAN_ID = @V_PLAN_ID
                AND     SM.ATTRIBUTE6 ='IN'
                AND     SM.ATTRIBUTE8 ='PLANT'
            ) A 
                INNER JOIN SCM_SYS_CALENDAR_M CM WITH(NOLOCK)
                    ON 1=1
            WHERE   1=1
            AND     CM.BASIS_YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
            GROUP BY OPERATION_GROUP,ITEM_ID,FROM_SITE,BOD_ID,MEASURE,TO_SITE,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE,BOD_TYPE,CM.BASIS_YYYYMMDD
        END
        ELSE IF @CHK_INTEGRAL IS NOT NULL
        BEGIN
            INSERT INTO @OS_RESULT
            SELECT OPERATION_GROUP
                  ,ITEM_ID
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  ,CM.BASIS_YYYYMMDD
                  ,TO_SITE
                  ,SUM(IIF(CM.BASIS_YYYYMMDD = YYYYMMDD, CONVERT(NUMERIC(30,10), QTY), 0)) AS OUT_QTY_INT
                  ,ORIGIN_FROM_DIVISION_ID
                  ,ORIGIN_TO_DIVISION_ID  
                  ,ELECTRODE_TYPE
                  ,BOD_TYPE
            FROM(
                SELECT IM.SCP_OPERATION_GROUP AS OPERATION_GROUP
                      ,OS.ITEM_ID             AS ITEM_ID
                      ,OS.FROM_SITE_ID        AS FROM_SITE
                      ,BOD.ATTRIBUTE7         AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,OS.DEPARTURE_DATE      AS YYYYMMDD
                      ,OS.TO_SITE_ID          AS TO_SITE
                      ,CONVERT(FLOAT,OS.QTY_INT) AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,BOD.ATTRIBUTE8         AS BOD_TYPE
                FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN  OS WITH(NOLOCK)
                    INNER JOIN SCP_OPT_ENG_BOD_SN BOD WITH(NOLOCK) 
                        ON  BOD.PLAN_ID = @V_PLAN_ID
                        AND OS.BOD_ID   = BOD.BOD_ID
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  OS.FROM_SITE_ID = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = OS.ITEM_ID
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  OS.TO_SITE_ID   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE 1=1
                AND BOD.ATTRIBUTE8 = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                AND OS.PLAN_ID = @V_PLAN_ID

                UNION ALL
                SELECT IM.SCP_OPERATION_GROUP AS OPERATION_GROUP
                      ,SM.ATTRIBUTE2          AS ITEM_ID
                      ,SM.ATTRIBUTE1          AS FROM_SITE
                      ,SM.ATTRIBUTE7          AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,SM.DEPARTURE_DATE      AS YYYYMMDD
                      ,SM.ATTRIBUTE4          AS TO_SITE
                      ,SM.QUANTITY            AS QTY
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,SM.ATTRIBUTE8          AS BOD_TYPE
                FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SM WITH(NOLOCK)
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  SM.ATTRIBUTE1 = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = SM.ATTRIBUTE2
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  SM.ATTRIBUTE4   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE   SM.PLAN_ID = @V_PLAN_ID
                AND     SM.ATTRIBUTE6 ='IN'
                AND     SM.ATTRIBUTE8 ='PLANT'
            ) A 
                INNER JOIN SCM_SYS_CALENDAR_M CM WITH(NOLOCK)
                    ON 1=1
            WHERE   1=1
            AND     CM.BASIS_YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
            GROUP BY OPERATION_GROUP,ITEM_ID,FROM_SITE,BOD_ID,MEASURE,TO_SITE,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE,BOD_TYPE,CM.BASIS_YYYYMMDD
        END
        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_SEMI
        SET SCP_ANL_SHIPMENT_PLAN_SEMI.QTY = 0
          , LAST_UPDATED_BY  = @UPDATE_NAME
          , LAST_UPDATE_DATE = @NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
        FROM SCP_ANL_SHIPMENT_PLAN_SEMI 
        INNER JOIN  (SELECT SCM_SITE_ID
                           ,ITEM_ID
                     FROM   SCP_OPT_ENG_MODEL_LIST_N_SN ML WITH(NOLOCK)
                     WHERE  PLAN_ID = @V_PLAN_ID
                     GROUP BY SCM_SITE_ID, ITEM_ID
                   ) ML
        ON  SCP_ANL_SHIPMENT_PLAN_SEMI.FROM_SITE = ML.SCM_SITE_ID
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.ITEM_ID   = ML.ITEM_ID
        WHERE 1=1
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.DIVISION_ID         = @V_DIVISION_ID
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.MEASURE             IN ('SHIP_PLAN_AMEND')
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.PLAN_TYPE           = @V_SCP_PLAN_TYPE
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.SEQ                 = @V_SCP_PLAN_SEQ
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND SCP_ANL_SHIPMENT_PLAN_SEMI.QTY != 0 


        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        MERGE INTO SCP_ANL_SHIPMENT_PLAN_SEMI AS ANL
        USING @OS_RESULT AS OSR
        ON(    ANL.DIVISION_ID             = @V_DIVISION_ID
           AND ANL.PLAN_START_YYYYMMDD     = @PLAN_START_YYYYMMDD
           AND ANL.PLAN_TYPE               = @V_SCP_PLAN_TYPE
           AND ANL.SEQ                     = @V_SCP_PLAN_SEQ
           AND ANL.OPERATION_GROUP         = OSR.OPERATION_GROUP
           AND ANL.ITEM_ID                 = OSR.ITEM_ID
           AND ANL.FROM_SITE               = OSR.FROM_SITE
           AND ANL.BOD_ID                  = OSR.BOD_ID
           AND ANL.MEASURE                 = OSR.MEASURE
           AND ANL.YYYYMMDD                = OSR.YYYYMMDD
          )
        WHEN MATCHED THEN 
            UPDATE SET ANL.QTY = OSR.QTY
                      ,ANL.LAST_UPDATE_DATE = @NOW_DATE
                      ,ANL.LAST_UPDATED_BY  = @UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
        WHEN NOT MATCHED THEN
        INSERT (DIVISION_ID
               ,PLAN_START_YYYYMMDD
               ,PLAN_TYPE
               ,SEQ
               ,OPERATION_GROUP
               ,ITEM_ID  
               ,FROM_SITE
               ,BOD_ID   
               ,MEASURE  
               ,YYYYMMDD 
               ,TO_SITE
               ,QTY
               ,ORIGIN_FROM_DIVISION_ID
               ,ORIGIN_TO_DIVISION_ID
               ,ELECTRODE_TYPE
               ,CREATED_BY
               ,CREATION_DATE
               ,LAST_UPDATED_BY
               ,LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
               )
        VALUES(@V_DIVISION_ID
              ,@PLAN_START_YYYYMMDD
              ,@V_SCP_PLAN_TYPE
              ,@V_SCP_PLAN_SEQ
              ,OSR.OPERATION_GROUP
              ,OSR.ITEM_ID
              ,OSR.FROM_SITE
              ,OSR.BOD_ID
              ,OSR.MEASURE
              ,OSR.YYYYMMDD
              ,OSR.TO_SITE
              ,OSR.QTY
              ,OSR.ORIGIN_TO_DIVISION_ID
              ,OSR.ORIGIN_FROM_DIVISION_ID
              ,OSR.ELECTRODE_TYPE
              ,@UPDATE_NAME
              ,@NOW_DATE
              ,@UPDATE_NAME
              ,@NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
              );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI_H(
                                                 HISTORY_SEQ
                                                ,DIVISION_ID
                                                ,PLAN_START_YYYYMMDD
                                                ,PLAN_TYPE
                                                ,SEQ
                                                ,OPERATION_GROUP
                                                ,ITEM_ID
                                                ,FROM_SITE
                                                ,TO_SITE
                                                ,BOD_ID
                                                ,MEASURE
                                                ,YYYYMMDD
                                                ,QTY
                                                ,UPDATE_REASON_BOD
                                                ,ORIGIN_FROM_DIVISION_ID
                                                ,ORIGIN_TO_DIVISION_ID
                                                ,ELECTRODE_TYPE
                                                ,CREATED_BY
                                                ,CREATION_DATE
                                                ,LAST_UPDATED_BY
                                                ,LAST_UPDATE_DATE
                                                ,ATTRIBUTE1
                                                ,ATTRIBUTE2
                                                ,ATTRIBUTE3
                                                ,ATTRIBUTE4
                                                ,ATTRIBUTE5
                                                ,ATTRIBUTE6
                                                ,ATTRIBUTE7
                                                ,ATTRIBUTE8
                                                ,ATTRIBUTE9
                                                ,ATTRIBUTE10
                                                ,HISTORY_CREATION_DATE
                                                )
        SELECT NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_SEMI_H
               HISTORY_SEQ
              ,DIVISION_ID
              ,PLAN_START_YYYYMMDD
              ,PLAN_TYPE
              ,SEQ
              ,OPERATION_GROUP
              ,ITEM_ID
              ,FROM_SITE
              ,TO_SITE
              ,BOD_ID
              ,MEASURE
              ,YYYYMMDD
              ,QTY
              ,NULL AS UPDATE_REASON_BOD
              ,ORIGIN_FROM_DIVISION_ID
              ,ORIGIN_TO_DIVISION_ID
              ,ELECTRODE_TYPE
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              ,ATTRIBUTE5
              ,ATTRIBUTE6
              ,ATTRIBUTE7
              ,ATTRIBUTE8
              ,ATTRIBUTE9
              ,ATTRIBUTE10
              ,@NOW_DATE AS HISTORY_CREATION_DATE
        FROM SCP_ANL_SHIPMENT_PLAN_SEMI WITH(NOLOCK)
        WHERE DIVISION_ID         = @V_DIVISION_ID
        AND MEASURE             IN ('SHIP_PLAN_AMEND')
        AND PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
        AND PLAN_TYPE           = @V_SCP_PLAN_TYPE
        AND SEQ                 = @V_SCP_PLAN_SEQ
        AND YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND LAST_UPDATED_BY = @UPDATE_NAME
        AND LAST_UPDATE_DATE =@NOW_DATE


        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_SHIPMENT_PLAN_FIX QTY 
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX
        SET SCP_ANL_SHIPMENT_PLAN_FIX.QTY = 0
          , LAST_UPDATED_BY  = @UPDATE_NAME
          , LAST_UPDATE_DATE = @NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
        FROM SCP_ANL_SHIPMENT_PLAN_FIX FX WITH(NOLOCK)
            INNER JOIN (SELECT SCM_SITE_ID
                              ,ITEM_ID
                        FROM   SCP_OPT_ENG_MODEL_LIST_N_SN ML WITH(NOLOCK)
                        WHERE  PLAN_ID = @V_PLAN_ID
                        GROUP BY SCM_SITE_ID, ITEM_ID
                      ) ML
                ON  FX.FROM_SITE = ML.SCM_SITE_ID
                AND FX.ITEM_ID     = ML.ITEM_ID
        WHERE FX.YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND   FX.DIVISION_ID         = @V_DIVISION_ID
        AND   FX.QTY != 0 


        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY 
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX
        SET SCP_ANL_SHIPMENT_PLAN_FIX.QTY = OSR.QTY
          , SCP_ANL_SHIPMENT_PLAN_FIX.LAST_UPDATED_BY  = @UPDATE_NAME
          , SCP_ANL_SHIPMENT_PLAN_FIX.LAST_UPDATE_DATE = @NOW_DATE
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
        FROM SCP_ANL_SHIPMENT_PLAN_FIX FX WITH(NOLOCK) 
            INNER JOIN @OS_RESULT OSR
                ON  FX.DIVISION_ID             = @V_DIVISION_ID
                AND FX.BIZ_TYPE                = OSR.OPERATION_GROUP
                AND FX.ITEM_ID                 = OSR.ITEM_ID
                AND FX.TO_SITE                 = OSR.TO_SITE
                AND FX.FROM_SITE               = OSR.FROM_SITE
                AND FX.BOD_ID                  = OSR.BOD_ID
                AND FX.YYYYMMDD                = OSR.YYYYMMDD
                AND FX.ORIGIN_FROM_DIVISION_ID = OSR.ORIGIN_FROM_DIVISION_ID
                AND FX.ORIGIN_TO_DIVISION_ID   = OSR.ORIGIN_TO_DIVISION_ID

        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        -- 원래는 FG가 끝나고 한 번에 INSERT를 했지만, FG를 넣지 않기로 했으므로 SEMI가 끝나고 INSERT
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H( HISTORY_SEQ
                                                ,FIX_ID
                                                ,DIVISION_ID
                                                ,BIZ_TYPE
                                                ,ITEM_ID
                                                ,TO_SITE
                                                ,FROM_SITE
                                                ,BOD_ID
                                                ,YYYYMMDD
                                                ,PROJECT_CODE
                                                ,INCOTERMS
                                                ,QTY
                                                ,FIX_REASON
                                                ,ORIGIN_FROM_DIVISION_ID
                                                ,ORIGIN_TO_DIVISION_ID
                                                ,ELECTRODE_TYPE
                                                ,CREATED_BY
                                                ,CREATION_DATE
                                                ,LAST_UPDATED_BY
                                                ,LAST_UPDATE_DATE
                                                ,ATTRIBUTE1
                                                ,ATTRIBUTE2
                                                ,ATTRIBUTE3
                                                ,ATTRIBUTE4
                                                ,ATTRIBUTE5
                                                ,ATTRIBUTE6
                                                ,ATTRIBUTE7
                                                ,ATTRIBUTE8
                                                ,ATTRIBUTE9
                                                ,ATTRIBUTE10
                                                ,HISTORY_CREATION_DATE
                                                )
        SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H -- 원본에서 SCP_ANL_SHIPMENT_PLAN_FIX_H의 SEQ를 SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H로 생성 중.
              ,FIX_ID
              ,DIVISION_ID
              ,BIZ_TYPE
              ,ITEM_ID
              ,TO_SITE
              ,FROM_SITE
              ,BOD_ID
              ,YYYYMMDD
              ,PROJECT_CODE
              ,INCOTERMS
              ,QTY
              ,FIX_REASON
              ,ORIGIN_FROM_DIVISION_ID
              ,ORIGIN_TO_DIVISION_ID
              ,ELECTRODE_TYPE
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              ,ATTRIBUTE5
              ,ATTRIBUTE6
              ,ATTRIBUTE7
              ,ATTRIBUTE8
              ,ATTRIBUTE9
              ,ATTRIBUTE10
              ,@NOW_DATE
        FROM SCP_ANL_SHIPMENT_PLAN_FIX WITH(NOLOCK)
        WHERE DIVISION_ID         = @V_DIVISION_ID
        AND YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND LAST_UPDATED_BY       = @UPDATE_NAME
        AND LAST_UPDATE_DATE      = @NOW_DATE */

        ------------------------------------------------------------------------
        -- PROD, SEMI까지 넣고서 엑셀 시뮬레이션에 INSERT는 기존에 있던 SP를 호출
        -- 전극도 GLOBAL 테이블을 UPDATE하는 방식으로 변경/김태현 선임/선우 책임님 요청/20250905
        ------------------------------------------------------------------------
        --EXEC PR_SCP_XLS_PSI_GLOBAL_ELECTRODE @V_SCP_PLAN_CYCLE, @V_SCP_PLAN_DATE, @V_SCP_PLAN_ID, @V_SCP_MODELING_ID, @V_SCP_PLAN_SEQ, @V_SCP_PLAN_TYPE, @V_SCP_MASTER_ID, @V_DIVISION_ID, @V_SCP_ENGINE_PLAN_ID


    /********************************전극은 FG 전송하지 않도록/20250812/김태현 선임/선우 책임님과 정리
    ------------------------------------------------------------------------
    -- ORDER_SHIPPING FG DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        IF @CHK_INTEGRAL IS NULL
        BEGIN
            INSERT INTO @OS_RESULT_FG
            SELECT BIZ_TYPE
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  --,YYYYMMDD
                  ,CM.BASIS_YYYYMMDD
                  ,TO_SITE
                  ,SUM(IIF(CM.BASIS_YYYYMMDD = YYYYMMDD, CONVERT(NUMERIC(30,10), QTY), 0)) AS OUT_QTY_INT
                  --,QTY
                  ,ORIGIN_FROM_DIVISION_ID
                  ,ORIGIN_TO_DIVISION_ID
                  ,ELECTRODE_TYPE
                  ,BOD_TYPE
                  ,INCOTERMS
            FROM(
                SELECT IM.SCP_OPERATION_GROUP AS BIZ_TYPE
                      ,BOD.ATTRIBUTE9         AS PROJECT_CODE
                      ,OS.ITEM_ID             AS ITEM_ID
                      ,OS.FROM_SITE_ID        AS FROM_SITE
                      ,BOD.ATTRIBUTE7         AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,OS.DEPARTURE_DATE      AS YYYYMMDD
                      ,OS.TO_SITE_ID          AS TO_SITE
                      ,CONVERT(FLOAT,OS.QTY)  AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,BOD.ATTRIBUTE8         AS BOD_TYPE
                      ,BOD.ATTRIBUTE6         AS INCOTERMS
                FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN  OS WITH(NOLOCK)
                    INNER JOIN SCP_OPT_ENG_BOD_SN BOD WITH(NOLOCK) 
                        ON  BOD.PLAN_ID = @V_PLAN_ID
                        AND OS.BOD_ID   = BOD.BOD_ID
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  OS.FROM_SITE_ID = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = OS.ITEM_ID
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  OS.TO_SITE_ID   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE 1=1
                AND OS.PLAN_ID=@V_PLAN_ID
                AND BOD.ATTRIBUTE8 = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                AND BOD.ATTRIBUTE7 <> 'DUMMY'
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                UNION ALL
                SELECT IM.SCP_OPERATION_GROUP AS BIZ_TYPE
                      ,SM.ATTRIBUTE10         AS PROJECT_CODE
                      ,SM.ATTRIBUTE2          AS ITEM_ID
                      ,SM.ATTRIBUTE1          AS FROM_SITE
                      ,SM.ATTRIBUTE7          AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,SM.DEPARTURE_DATE      AS YYYYMMDD
                      ,SM.ATTRIBUTE4          AS TO_SITE
                      ,SUM(SM.QUANTITY)       AS QTY
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,SM.ATTRIBUTE8          AS BOD_TYPE
                      ,SM.ATTRIBUTE9          AS INCOTERMS
                FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SM WITH(NOLOCK)
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  SM.ATTRIBUTE1 = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = SM.ATTRIBUTE2
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  SM.ATTRIBUTE4   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE   SM.PLAN_ID = @V_PLAN_ID
                AND     SM.ATTRIBUTE6 ='IN'
                AND     SM.ATTRIBUTE8 ='SALES'
                GROUP BY IM.SCP_OPERATION_GROUP, SM.ATTRIBUTE10,SM.ATTRIBUTE2,SM.ATTRIBUTE1,SM.ATTRIBUTE7,SM.DEPARTURE_DATE,SM.ATTRIBUTE4,SM.ATTRIBUTE8,SM.ATTRIBUTE9,MSF.DIVISION_ID,MST.DIVISION_ID -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                ) A
                INNER JOIN SCM_SYS_CALENDAR_M CM WITH(NOLOCK)
                    ON 1=1
            WHERE   CM.BASIS_YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
            GROUP BY BIZ_TYPE,PROJECT_CODE,ITEM_ID,FROM_SITE,BOD_ID,MEASURE,TO_SITE,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE,BOD_TYPE,INCOTERMS,CM.BASIS_YYYYMMDD
        END
        ELSE IF @CHK_INTEGRAL IS NOT NULL
        BEGIN
            INSERT INTO @OS_RESULT_FG
            SELECT BIZ_TYPE
                  ,PROJECT_CODE
                  ,ITEM_ID
                  ,FROM_SITE
                  ,BOD_ID
                  ,MEASURE
                  --,YYYYMMDD
                  ,CM.BASIS_YYYYMMDD
                  ,TO_SITE
                  ,SUM(IIF(CM.BASIS_YYYYMMDD = YYYYMMDD, CONVERT(NUMERIC(30,10), QTY), 0)) AS OUT_QTY_INT
                  --,QTY
                  ,ORIGIN_FROM_DIVISION_ID
                  ,ORIGIN_TO_DIVISION_ID
                  ,ELECTRODE_TYPE
                  ,BOD_TYPE
                  ,INCOTERMS
            FROM(
                SELECT IM.SCP_OPERATION_GROUP AS BIZ_TYPE
                      ,BOD.ATTRIBUTE9         AS PROJECT_CODE
                      ,OS.ITEM_ID             AS ITEM_ID
                      ,OS.FROM_SITE_ID        AS FROM_SITE
                      ,BOD.ATTRIBUTE7         AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,OS.DEPARTURE_DATE      AS YYYYMMDD
                      ,OS.TO_SITE_ID          AS TO_SITE
                      ,CONVERT(FLOAT,OS.QTY_INT) AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,BOD.ATTRIBUTE8         AS BOD_TYPE
                      ,BOD.ATTRIBUTE6         AS INCOTERMS
                FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN  OS WITH(NOLOCK)
                    INNER JOIN SCP_OPT_ENG_BOD_SN BOD WITH(NOLOCK) 
                        ON  BOD.PLAN_ID = @V_PLAN_ID
                        AND OS.BOD_ID   = BOD.BOD_ID
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  OS.FROM_SITE_ID = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = OS.ITEM_ID
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  OS.TO_SITE_ID   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE 1=1
                AND OS.PLAN_ID=@V_PLAN_ID
                AND BOD.ATTRIBUTE8 = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                AND BOD.ATTRIBUTE7 <> 'DUMMY'
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                UNION ALL
                SELECT IM.SCP_OPERATION_GROUP AS BIZ_TYPE
                      ,SM.ATTRIBUTE10         AS PROJECT_CODE
                      ,SM.ATTRIBUTE2          AS ITEM_ID
                      ,SM.ATTRIBUTE1          AS FROM_SITE
                      ,SM.ATTRIBUTE7          AS BOD_ID
                      ,'SHIP_PLAN_AMEND'      AS MEASURE
                      ,SM.DEPARTURE_DATE      AS YYYYMMDD
                      ,SM.ATTRIBUTE4          AS TO_SITE
                      ,SUM(SM.QUANTITY)       AS QTY
                      ,MSF.DIVISION_ID        AS ORIGIN_FROM_DIVISION_ID
                      ,MST.DIVISION_ID        AS ORIGIN_TO_DIVISION_ID  
                      ,NULL                   AS ELECTRODE_TYPE
                      ,SM.ATTRIBUTE8          AS BOD_TYPE
                      ,SM.ATTRIBUTE9          AS INCOTERMS
                FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SM WITH(NOLOCK)
                    INNER JOIN SCM_MST_SITE MSF WITH(NOLOCK)
                        ON  SM.ATTRIBUTE1 = MSF.SCM_SITE_ID
                        AND MSF.VALID_YN    = 'Y'
                    INNER JOIN SCM_ITEM_M_SN IM WITH(NOLOCK)
                        ON  MSF.DIVISION_ID = IM.DIVISION_ID
                        AND MSF.COMPANY_ID  = IM.COMPANY_ID
                        AND MSF.SITE_ID     = IM.SITE_ID
                        AND IM.ITEM_ID      = SM.ATTRIBUTE2
                    INNER JOIN SCM_MST_SITE MST WITH(NOLOCK)
                        ON  SM.ATTRIBUTE4   = MST.SCM_SITE_ID
                        AND MST.VALID_YN    = 'Y'
                WHERE   SM.PLAN_ID = @V_PLAN_ID
                AND     SM.ATTRIBUTE6 ='IN'
                AND     SM.ATTRIBUTE8 ='SALES'
                GROUP BY IM.SCP_OPERATION_GROUP, SM.ATTRIBUTE10,SM.ATTRIBUTE2,SM.ATTRIBUTE1,SM.ATTRIBUTE7,SM.DEPARTURE_DATE,SM.ATTRIBUTE4,SM.ATTRIBUTE8,SM.ATTRIBUTE9,MSF.DIVISION_ID,MST.DIVISION_ID -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                ) A
                INNER JOIN SCM_SYS_CALENDAR_M CM WITH(NOLOCK)
                    ON 1=1
            WHERE   CM.BASIS_YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
            GROUP BY BIZ_TYPE,PROJECT_CODE,ITEM_ID,FROM_SITE,BOD_ID,MEASURE,TO_SITE,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID,ELECTRODE_TYPE,BOD_TYPE,INCOTERMS,CM.BASIS_YYYYMMDD
        END
        ------------------------------------------------------------------------
        -- 0. 입력할 데이터가 있으면 진행
        ------------------------------------------------------------------------

        ------------------------------------------------------------------------
        -- 1. Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG
        SET SCP_ANL_SHIPMENT_PLAN_FG.QTY = 0
          , LAST_UPDATED_BY  = @UPDATE_NAME
          , LAST_UPDATE_DATE = @NOW_DATE
          --, ATTRIBUTE9       = 'U'
          --, ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
        FROM SCP_ANL_SHIPMENT_PLAN_FG 
        INNER JOIN  (SELECT SCM_SITE_ID
                           ,ITEM_ID
                     FROM   SCP_OPT_ENG_MODEL_LIST_N_SN ML WITH(NOLOCK)
                     WHERE  PLAN_ID = @V_PLAN_ID
                     GROUP BY SCM_SITE_ID, ITEM_ID
                   ) ML
        ON  SCP_ANL_SHIPMENT_PLAN_FG.FROM_SITE = ML.SCM_SITE_ID
        AND SCP_ANL_SHIPMENT_PLAN_FG.ITEM_ID   = ML.ITEM_ID
        WHERE 1=1
        AND SCP_ANL_SHIPMENT_PLAN_FG.DIVISION_ID         = @V_DIVISION_ID
        AND SCP_ANL_SHIPMENT_PLAN_FG.MEASURE             IN ('SHIP_PLAN_AMEND')
        AND SCP_ANL_SHIPMENT_PLAN_FG.PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
        AND SCP_ANL_SHIPMENT_PLAN_FG.PLAN_TYPE           = @V_SCP_PLAN_TYPE
        AND SCP_ANL_SHIPMENT_PLAN_FG.SEQ                 = @V_SCP_PLAN_SEQ
        AND SCP_ANL_SHIPMENT_PLAN_FG.YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND SCP_ANL_SHIPMENT_PLAN_FG.QTY != 0 

        ------------------------------------------------------------------------
        -- 2. Get SCP_ANL_SHIPMENT_PLAN_FG DATA
        -- 프로젝트 코드가 1개인 대상만 추출 -> 속도 개선을 위한 TEMP 테이블 사용
        -- '-'는 제외하고 COUNTING
        ------------------------------------------------------------------------
        INSERT INTO @OS_RESULT_FG_SMMR
        SELECT NPC.ITEM_ID
              ,NPC.BOD_ID
              ,FG.PROJECT_CODE
        FROM(
            SELECT DIVISION_ID
                  ,PLAN_START_YYYYMMDD
                  ,PLAN_TYPE
                  ,SEQ
                  ,BIZ_TYPE
                  ,FG.ITEM_ID
                  ,MEASURE
                  ,BOD_ID
                  ,ORIGIN_FROM_DIVISION_ID
                  ,ORIGIN_TO_DIVISION_ID
            FROM(
                SELECT DIVISION_ID
                      ,PLAN_START_YYYYMMDD
                      ,PLAN_TYPE
                      ,SEQ
                      ,BIZ_TYPE
                      ,PROJECT_CODE
                      ,FG.ITEM_ID
                      ,MEASURE
                      ,BOD_ID
                      ,ORIGIN_FROM_DIVISION_ID
                      ,ORIGIN_TO_DIVISION_ID
                FROM SCP_ANL_SHIPMENT_PLAN_FG FG WITH(NOLOCK)
                    INNER JOIN (SELECT SCM_SITE_ID
                                      ,ITEM_ID
                                FROM   SCP_OPT_ENG_MODEL_LIST_N_SN ML WITH(NOLOCK)
                                WHERE  PLAN_ID = @V_PLAN_ID
                                GROUP BY SCM_SITE_ID, ITEM_ID
                               ) ML
                        ON  FG.FROM_SITE   = ML.SCM_SITE_ID
                        AND FG.ITEM_ID     = ML.ITEM_ID
                WHERE 1=1
                AND FG.DIVISION_ID         = @V_DIVISION_ID
                AND FG.MEASURE             IN ('SHIP_PLAN_AMEND')
                AND FG.PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
                AND FG.PLAN_TYPE           = @V_SCP_PLAN_TYPE
                AND FG.SEQ                 = @V_SCP_PLAN_SEQ
                AND FG.YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
                AND FG.PROJECT_CODE       != '-'
                GROUP BY DIVISION_ID,PLAN_START_YYYYMMDD,PLAN_TYPE,SEQ,BIZ_TYPE,PROJECT_CODE,FG.ITEM_ID,MEASURE,BOD_ID,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID
                ) FG
            GROUP BY  DIVISION_ID,PLAN_START_YYYYMMDD,PLAN_TYPE,SEQ,BIZ_TYPE,ITEM_ID,MEASURE,BOD_ID,ORIGIN_FROM_DIVISION_ID,ORIGIN_TO_DIVISION_ID
            HAVING COUNT(DIVISION_ID) =1
            ) NPC
            INNER JOIN SCP_ANL_SHIPMENT_PLAN_FG FG WITH(NOLOCK)
                ON  NPC.ITEM_ID = FG.ITEM_ID
                AND NPC.BOD_ID  = FG.BOD_ID
                AND FG.DIVISION_ID             = NPC.DIVISION_ID        
                AND FG.MEASURE                 = NPC.MEASURE            
                AND FG.PLAN_START_YYYYMMDD     = NPC.PLAN_START_YYYYMMDD
                AND FG.PLAN_TYPE               = NPC.PLAN_TYPE          
                AND FG.SEQ                     = NPC.SEQ                
                AND FG.YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
                AND FG.PROJECT_CODE           != '-'
                AND FG.ORIGIN_FROM_DIVISION_ID = NPC.ORIGIN_FROM_DIVISION_ID
                AND FG.ORIGIN_TO_DIVISION_ID   = NPC.ORIGIN_TO_DIVISION_ID
        GROUP BY NPC.ITEM_ID,NPC.BOD_ID,FG.PROJECT_CODE


        ------------------------------------------------------------------------
        -- 2-1. 프로젝트 코드가 있으면 바로 넣고, 없는 애들만 2-2에서 프로젝트 코드를 찾아서 넣음
        ------------------------------------------------------------------------
        MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG AS ANL
        USING (SELECT OSF.OPERATION_GROUP        
                     ,OSF.PROJECT_CODE    
                     ,OSF.ITEM_ID            
                     ,OSF.TO_SITE            
                     ,OSF.INCOTERMS          
                     ,OSF.FROM_SITE          
                     ,OSF.BOD_ID             
                     ,OSF.MEASURE            
                     ,OSF.YYYYMMDD          
                     ,OSF.QTY
                     ,OSF.ORIGIN_FROM_DIVISION_ID
                     ,OSF.ORIGIN_TO_DIVISION_ID
                     ,OSF.ELECTRODE_TYPE
               FROM @OS_RESULT_FG OSF
               WHERE OSF.PROJECT_CODE != '-' --프로젝트 코드를 가지고있는 애들은 바로 MERGE INTO
              ) AS OSF
        ON(    ANL.DIVISION_ID             = @V_DIVISION_ID
           AND ANL.PLAN_START_YYYYMMDD     = @PLAN_START_YYYYMMDD
           AND ANL.PLAN_TYPE               = @V_SCP_PLAN_TYPE
           AND ANL.SEQ                     = @V_SCP_PLAN_SEQ
           AND ANL.BIZ_TYPE                = OSF.OPERATION_GROUP
           AND ANL.PROJECT_CODE            = OSF.PROJECT_CODE
           AND ANL.ITEM_ID                 = OSF.ITEM_ID
           AND ANL.TO_SITE                 = OSF.TO_SITE
           AND ANL.INCOTERMS               = OSF.INCOTERMS
           AND ANL.FROM_SITE               = OSF.FROM_SITE
           AND ANL.BOD_ID                  = OSF.BOD_ID
           AND ANL.MEASURE                 = OSF.MEASURE
           AND ANL.YYYYMMDD                = OSF.YYYYMMDD
           AND ANL.ORIGIN_FROM_DIVISION_ID = OSF.ORIGIN_FROM_DIVISION_ID
           AND ANL.ORIGIN_TO_DIVISION_ID   = OSF.ORIGIN_TO_DIVISION_ID
          )
        WHEN MATCHED THEN 
            UPDATE SET ANL.QTY = OSF.QTY
                      ,ANL.LAST_UPDATE_DATE = @NOW_DATE
                      ,ANL.LAST_UPDATED_BY  = @UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
        WHEN NOT MATCHED THEN
        INSERT (DIVISION_ID        
               ,PLAN_START_YYYYMMDD
               ,PLAN_TYPE          
               ,SEQ                
               ,BIZ_TYPE           
               ,PROJECT_CODE       
               ,ITEM_ID            
               ,TO_SITE            
               ,INCOTERMS          
               ,FROM_SITE          
               ,BOD_ID             
               ,MEASURE            
               ,YYYYMMDD          
               ,QTY
               ,ORIGIN_FROM_DIVISION_ID
               ,ORIGIN_TO_DIVISION_ID
               ,ELECTRODE_TYPE
               ,CREATED_BY
               ,CREATION_DATE
               ,LAST_UPDATED_BY
               ,LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
               )
        VALUES(@V_DIVISION_ID
              ,@PLAN_START_YYYYMMDD
              ,@V_SCP_PLAN_TYPE
              ,@V_SCP_PLAN_SEQ
              ,OSF.OPERATION_GROUP         
              ,OSF.PROJECT_CODE
              ,OSF.ITEM_ID            
              ,OSF.TO_SITE            
              ,OSF.INCOTERMS          
              ,OSF.FROM_SITE          
              ,OSF.BOD_ID             
              ,OSF.MEASURE            
              ,OSF.YYYYMMDD          
              ,OSF.QTY
              ,OSF.ORIGIN_FROM_DIVISION_ID
              ,OSF.ORIGIN_TO_DIVISION_ID
              ,OSF.ELECTRODE_TYPE
              ,@UPDATE_NAME
              ,@NOW_DATE
              ,@UPDATE_NAME
              ,@NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
              );


        ------------------------------------------------------------------------
        -- 2-2. 엔진 결과에서 프로젝트 코드가 없는('-') 대상은 찾아서 넣어야 함
        -- FG에  PROJECT가 한개인 것 MERGE INTO 
        -- 프로젝트가 한 개 라면, 그 프로젝트를 찾아서 INSERT 하기위해
        ------------------------------------------------------------------------
        PRINT 'SCP_ANL_SHIPMENT_PLAN_FG_____2'
        MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG AS ANL
        USING (SELECT OSF.OPERATION_GROUP        
                     ,SMMR.PROJECT_CODE    
                     ,OSF.ITEM_ID            
                     ,OSF.TO_SITE            
                     ,OSF.INCOTERMS          
                     ,OSF.FROM_SITE          
                     ,OSF.BOD_ID             
                     ,OSF.MEASURE            
                     ,OSF.YYYYMMDD          
                     ,OSF.QTY
                     ,OSF.ORIGIN_FROM_DIVISION_ID
                     ,OSF.ORIGIN_TO_DIVISION_ID
                     ,OSF.ELECTRODE_TYPE
               FROM @OS_RESULT_FG OSF
                   INNER JOIN @OS_RESULT_FG_SMMR SMMR
                            ON  OSF.ITEM_ID = SMMR.ITEM_ID
                            AND OSF.BOD_ID  = SMMR.BOD_ID
               WHERE OSF.PROJECT_CODE = '-'
              ) AS OSF
        ON(    ANL.DIVISION_ID             = @V_DIVISION_ID
           AND ANL.PLAN_START_YYYYMMDD     = @PLAN_START_YYYYMMDD
           AND ANL.PLAN_TYPE               = @V_SCP_PLAN_TYPE
           AND ANL.SEQ                     = @V_SCP_PLAN_SEQ
           AND ANL.BIZ_TYPE                = OSF.OPERATION_GROUP
           AND ANL.PROJECT_CODE            = OSF.PROJECT_CODE
           AND ANL.ITEM_ID                 = OSF.ITEM_ID
           AND ANL.TO_SITE                 = OSF.TO_SITE
           AND ANL.INCOTERMS               = OSF.INCOTERMS
           AND ANL.FROM_SITE               = OSF.FROM_SITE
           AND ANL.BOD_ID                  = OSF.BOD_ID
           AND ANL.MEASURE                 = OSF.MEASURE
           AND ANL.YYYYMMDD                = OSF.YYYYMMDD
           AND ANL.ORIGIN_FROM_DIVISION_ID = OSF.ORIGIN_FROM_DIVISION_ID
           AND ANL.ORIGIN_TO_DIVISION_ID   = OSF.ORIGIN_TO_DIVISION_ID
          )
        WHEN MATCHED THEN 
            UPDATE SET ANL.QTY = OSF.QTY
                      ,ANL.LAST_UPDATE_DATE = @NOW_DATE
                      ,ANL.LAST_UPDATED_BY  = @UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
        WHEN NOT MATCHED THEN
        INSERT (DIVISION_ID        
               ,PLAN_START_YYYYMMDD
               ,PLAN_TYPE          
               ,SEQ                
               ,BIZ_TYPE           
               ,PROJECT_CODE       
               ,ITEM_ID            
               ,TO_SITE            
               ,INCOTERMS          
               ,FROM_SITE          
               ,BOD_ID             
               ,MEASURE            
               ,YYYYMMDD          
               ,QTY
               ,ORIGIN_FROM_DIVISION_ID
               ,ORIGIN_TO_DIVISION_ID
               ,ELECTRODE_TYPE
               ,CREATED_BY
               ,CREATION_DATE
               ,LAST_UPDATED_BY
               ,LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
               )
        VALUES(@V_DIVISION_ID
              ,@PLAN_START_YYYYMMDD
              ,@V_SCP_PLAN_TYPE
              ,@V_SCP_PLAN_SEQ
              ,OSF.OPERATION_GROUP         
              ,OSF.PROJECT_CODE    --OSF를 만들 때 하나인 프로젝트 코드를 찾았음
              ,OSF.ITEM_ID            
              ,OSF.TO_SITE            
              ,OSF.INCOTERMS          
              ,OSF.FROM_SITE          
              ,OSF.BOD_ID             
              ,OSF.MEASURE            
              ,OSF.YYYYMMDD          
              ,OSF.QTY
              ,OSF.ORIGIN_FROM_DIVISION_ID
              ,OSF.ORIGIN_TO_DIVISION_ID
              ,OSF.ELECTRODE_TYPE
              ,@UPDATE_NAME
              ,@NOW_DATE
              ,@UPDATE_NAME
              ,@NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
              );

        ------------------------------------------------------------------------
        -- 3. FG에 프로젝트가 여러개인 애들 MERGE INTO
        -- Project Code가 -로 등록되어있으면 update, 아니면 Project Code를 -로 insert
        ------------------------------------------------------------------------
        MERGE INTO SCP_ANL_SHIPMENT_PLAN_FG AS ANL
        USING (SELECT OSF.OPERATION_GROUP        
                     ,OSF.PROJECT_CODE    
                     ,OSF.ITEM_ID            
                     ,OSF.TO_SITE            
                     ,OSF.INCOTERMS          
                     ,OSF.FROM_SITE          
                     ,OSF.BOD_ID             
                     ,OSF.MEASURE            
                     ,OSF.YYYYMMDD          
                     ,OSF.QTY
                     ,OSF.ORIGIN_FROM_DIVISION_ID
                     ,OSF.ORIGIN_TO_DIVISION_ID
                     ,OSF.ELECTRODE_TYPE
               FROM   @OS_RESULT_FG OSF
               LEFT OUTER JOIN @OS_RESULT_FG_SMMR SMMR
                            ON  OSF.ITEM_ID = SMMR.ITEM_ID
                            AND OSF.BOD_ID  = SMMR.BOD_ID
               WHERE SMMR.ITEM_ID IS NULL
               AND   OSF.PROJECT_CODE = '-'
              ) AS OSF
        ON(    ANL.DIVISION_ID             = @V_DIVISION_ID
           AND ANL.PLAN_START_YYYYMMDD     = @PLAN_START_YYYYMMDD
           AND ANL.PLAN_TYPE               = @V_SCP_PLAN_TYPE
           AND ANL.SEQ                     = @V_SCP_PLAN_SEQ
           AND ANL.BIZ_TYPE                = OSF.OPERATION_GROUP
           AND ANL.PROJECT_CODE            = OSF.PROJECT_CODE
           AND ANL.ITEM_ID                 = OSF.ITEM_ID
           AND ANL.TO_SITE                 = OSF.TO_SITE
           AND ANL.INCOTERMS               = OSF.INCOTERMS
           AND ANL.FROM_SITE               = OSF.FROM_SITE
           AND ANL.BOD_ID                  = OSF.BOD_ID
           AND ANL.MEASURE                 = OSF.MEASURE
           AND ANL.YYYYMMDD                = OSF.YYYYMMDD
           AND ANL.ORIGIN_FROM_DIVISION_ID = OSF.ORIGIN_FROM_DIVISION_ID
           AND ANL.ORIGIN_TO_DIVISION_ID   = OSF.ORIGIN_TO_DIVISION_ID
          )
        WHEN MATCHED THEN 
            UPDATE SET ANL.QTY = OSF.QTY
                      ,ANL.LAST_UPDATE_DATE = @NOW_DATE
                      ,ANL.LAST_UPDATED_BY  = @UPDATE_NAME
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
        WHEN NOT MATCHED THEN
        INSERT (DIVISION_ID        
               ,PLAN_START_YYYYMMDD
               ,PLAN_TYPE          
               ,SEQ                
               ,BIZ_TYPE           
               ,PROJECT_CODE       
               ,ITEM_ID            
               ,TO_SITE            
               ,INCOTERMS          
               ,FROM_SITE          
               ,BOD_ID             
               ,MEASURE            
               ,YYYYMMDD          
               ,QTY
               ,ORIGIN_FROM_DIVISION_ID
               ,ORIGIN_TO_DIVISION_ID
               ,ELECTRODE_TYPE
               ,CREATED_BY
               ,CREATION_DATE
               ,LAST_UPDATED_BY
               ,LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
               )
        VALUES(@V_DIVISION_ID
              ,@PLAN_START_YYYYMMDD
              ,@V_SCP_PLAN_TYPE
              ,@V_SCP_PLAN_SEQ
              ,OSF.OPERATION_GROUP         
              ,OSF.PROJECT_CODE    --OSF를 만들 때 '-'로 넣었음
              ,OSF.ITEM_ID            
              ,OSF.TO_SITE            
              ,OSF.INCOTERMS          
              ,OSF.FROM_SITE          
              ,OSF.BOD_ID             
              ,OSF.MEASURE            
              ,OSF.YYYYMMDD          
              ,OSF.QTY
              ,OSF.ORIGIN_FROM_DIVISION_ID
              ,OSF.ORIGIN_TO_DIVISION_ID
              ,OSF.ELECTRODE_TYPE
              ,@UPDATE_NAME
              ,@NOW_DATE
              ,@UPDATE_NAME
              ,@NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
              );

        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FG_H(
                                               HISTORY_SEQ
                                              ,DIVISION_ID
                                              ,PLAN_START_YYYYMMDD
                                              ,PLAN_TYPE
                                              ,SEQ
                                              ,BIZ_TYPE
                                              ,PROJECT_CODE
                                              ,ITEM_ID
                                              ,TO_SITE
                                              ,INCOTERMS
                                              ,FROM_SITE
                                              ,BOD_ID
                                              ,MEASURE
                                              ,YYYYMMDD
                                              ,QTY
                                              ,ORIGIN_TO_DIVISION_ID
                                              ,ORIGIN_FROM_DIVISION_ID
                                              ,ELECTRODE_TYPE
                                              ,CREATED_BY
                                              ,CREATION_DATE
                                              ,LAST_UPDATED_BY
                                              ,LAST_UPDATE_DATE
                                              ,ATTRIBUTE1
                                              ,ATTRIBUTE2
                                              ,ATTRIBUTE3
                                              ,ATTRIBUTE4
                                              ,ATTRIBUTE5
                                              ,ATTRIBUTE6
                                              ,ATTRIBUTE7
                                              ,ATTRIBUTE8
                                              ,ATTRIBUTE9
                                              ,ATTRIBUTE10
                                              ,HISTORY_CREATION_DATE
                                              )
        SELECT NEXT VALUE FOR SEQ1_SCP_ANL_SHIPMENT_PLAN_FG_H AS HISTORY_SEQ
              ,DIVISION_ID
              ,PLAN_START_YYYYMMDD
              ,PLAN_TYPE
              ,SEQ
              ,BIZ_TYPE
              ,PROJECT_CODE
              ,ITEM_ID
              ,TO_SITE
              ,INCOTERMS
              ,FROM_SITE
              ,BOD_ID
              ,MEASURE
              ,YYYYMMDD
              ,QTY
              ,ORIGIN_FROM_DIVISION_ID
              ,ORIGIN_TO_DIVISION_ID
              ,ELECTRODE_TYPE
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              ,ATTRIBUTE5
              ,ATTRIBUTE6
              ,ATTRIBUTE7
              ,ATTRIBUTE8
              ,ATTRIBUTE9
              ,ATTRIBUTE10
              ,@NOW_DATE AS HISTORY_CREATION_DATE
        FROM SCP_ANL_SHIPMENT_PLAN_FG WITH(NOLOCK)
        WHERE DIVISION_ID         = @V_DIVISION_ID
        AND MEASURE             IN ('SHIP_PLAN_AMEND')
        AND PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
        AND PLAN_TYPE           = @V_SCP_PLAN_TYPE
        AND SEQ                 = @V_SCP_PLAN_SEQ
        AND YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND LAST_UPDATED_BY = @UPDATE_NAME
        AND LAST_UPDATE_DATE =@NOW_DATE
        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY 
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX
        SET SCP_ANL_SHIPMENT_PLAN_FIX.QTY = OSF.QTY
          , SCP_ANL_SHIPMENT_PLAN_FIX.LAST_UPDATED_BY  = @UPDATE_NAME
          , SCP_ANL_SHIPMENT_PLAN_FIX.LAST_UPDATE_DATE = @NOW_DATE
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
        FROM SCP_ANL_SHIPMENT_PLAN_FIX FX WITH(NOLOCK) 
            INNER JOIN @OS_RESULT_FG OSF
                ON  FX.DIVISION_ID             = @V_DIVISION_ID
                AND FX.BIZ_TYPE                = OSF.OPERATION_GROUP
                AND FX.ITEM_ID                 = OSF.ITEM_ID
                AND FX.TO_SITE                 = OSF.TO_SITE
                AND FX.FROM_SITE               = OSF.FROM_SITE
                AND FX.BOD_ID                  = OSF.BOD_ID
                AND FX.YYYYMMDD                = OSF.YYYYMMDD
                AND FX.PROJECT_CODE            = OSF.PROJECT_CODE
                AND FX.ORIGIN_FROM_DIVISION_ID = OSF.ORIGIN_FROM_DIVISION_ID
                AND FX.ORIGIN_TO_DIVISION_ID   = OSF.ORIGIN_TO_DIVISION_ID
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H( HISTORY_SEQ
                                                ,FIX_ID
                                                ,DIVISION_ID
                                                ,BIZ_TYPE
                                                ,ITEM_ID
                                                ,TO_SITE
                                                ,FROM_SITE
                                                ,BOD_ID
                                                ,YYYYMMDD
                                                ,PROJECT_CODE
                                                ,INCOTERMS
                                                ,QTY
                                                ,FIX_REASON
                                                ,ORIGIN_FROM_DIVISION_ID
                                                ,ORIGIN_TO_DIVISION_ID
                                                ,ELECTRODE_TYPE
                                                ,CREATED_BY
                                                ,CREATION_DATE
                                                ,LAST_UPDATED_BY
                                                ,LAST_UPDATE_DATE
                                                ,ATTRIBUTE1
                                                ,ATTRIBUTE2
                                                ,ATTRIBUTE3
                                                ,ATTRIBUTE4
                                                ,ATTRIBUTE5
                                                ,ATTRIBUTE6
                                                ,ATTRIBUTE7
                                                ,ATTRIBUTE8
                                                ,ATTRIBUTE9
                                                ,ATTRIBUTE10
                                                ,HISTORY_CREATION_DATE
                                                )
        SELECT NEXT VALUE FOR SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H -- 원본에서 SCP_ANL_SHIPMENT_PLAN_FIX_H의 SEQ를 SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H로 생성 중.
              ,FIX_ID
              ,DIVISION_ID
              ,BIZ_TYPE
              ,ITEM_ID
              ,TO_SITE
              ,FROM_SITE
              ,BOD_ID
              ,YYYYMMDD
              ,PROJECT_CODE
              ,INCOTERMS
              ,QTY
              ,FIX_REASON
              ,ORIGIN_FROM_DIVISION_ID
              ,ORIGIN_TO_DIVISION_ID
              ,ELECTRODE_TYPE
              ,CREATED_BY
              ,CREATION_DATE
              ,LAST_UPDATED_BY
              ,LAST_UPDATE_DATE
              ,ATTRIBUTE1
              ,ATTRIBUTE2
              ,ATTRIBUTE3
              ,ATTRIBUTE4
              ,ATTRIBUTE5
              ,ATTRIBUTE6
              ,ATTRIBUTE7
              ,ATTRIBUTE8
              ,ATTRIBUTE9
              ,ATTRIBUTE10
              ,@NOW_DATE
        FROM SCP_ANL_SHIPMENT_PLAN_FIX WITH(NOLOCK)
        WHERE DIVISION_ID         = @V_DIVISION_ID
        AND YYYYMMDD BETWEEN @V_PLAN_START_YYYYMMDD AND @V_PLAN_END_YYYYMMDD
        AND LAST_UPDATED_BY       = @UPDATE_NAME
        AND LAST_UPDATE_DATE      = @NOW_DATE

    ******************************************************************************************/
    ------------------------------------------------------------------------
    -- UPDATE SCP_XLS_PSI_GLOBAL_ELECTRODE
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- 52주 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TAEE_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_CHAR(A.SEQ)          AS SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , A.MEASURE
             , SUM(NVL(A.QTY, 0))      AS QTY_SUM
             , P_PLAN_START_YYYYMMDD   AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN A
         WHERE IA.BASIS_YYYYMMDD     = A.YYYYMMDD(+)
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND A.MEASURE             = 'PROD_PLAN_AMEND'
           AND A.QTY                != 0
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IA.TRG_DATE
                , A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.MEASURE
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IB.WEEK_NUM             AS TRG_DATE
             , B.DIVISION_ID
             , B.PLAN_START_YYYYMMDD
             , B.PLAN_TYPE
             , TO_CHAR(B.SEQ)          AS SEQ
             , B.OPERATION_GROUP
             , B.SCM_SITE_ID
             , B.ITEM_ID
             , B.LINE_ID
             , '-'                     AS BOD_ID
             , '/'                     AS PROJECT_CODE
             , B.MEASURE
             , SUM(B.QTY)              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD   AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IB
             , SCP_ANL_PRODUCTION_PLAN B
         WHERE IB.BASIS_YYYYMMDD     = B.YYYYMMDD(+)
           AND B.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND B.MEASURE             = 'PROD_PLAN_AMEND'
           AND B.QTY                != 0
           AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IB.WEEK_NUM
                , B.DIVISION_ID
                , B.PLAN_START_YYYYMMDD
                , B.PLAN_TYPE
                , B.SEQ
                , B.OPERATION_GROUP
                , B.SCM_SITE_ID
                , B.ITEM_ID
                , B.LINE_ID
                , B.MEASURE

        ------------------------------------------------------------------------
        -- Get Daily SCP_ANL_SHIPMENT_PLAN_SEMI data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IC.TRG_DATE
             , C.DIVISION_ID
             , C.PLAN_START_YYYYMMDD
             , C.PLAN_TYPE
             , TO_CHAR(C.SEQ)          AS SEQ
             , C.OPERATION_GROUP
             , C.FROM_SITE
             , C.ITEM_ID
             , '-'                     AS LINE_ID
             , C.BOD_ID
             , '/'                     AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'        AS MEASURE
             , SUM(NVL(C.QTY, 0))      AS QTY_SUM
             , P_PLAN_START_YYYYMMDD   AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IC
             , SCP_ANL_SHIPMENT_PLAN_SEMI C
         WHERE IC.BASIS_YYYYMMDD     = C.YYYYMMDD(+)
           AND C.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND C.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND C.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9      = 'U'
           AND C.MEASURE             = 'SHIP_PLAN_AMEND'
           AND C.QTY                != 0
           AND C.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IC.TRG_DATE
                , C.DIVISION_ID
                , C.PLAN_START_YYYYMMDD
                , C.PLAN_TYPE
                , C.SEQ
                , C.OPERATION_GROUP
                , C.FROM_SITE
                , C.ITEM_ID
                , C.BOD_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT ID.WEEK_NUM             AS TRG_DATE
             , D.DIVISION_ID
             , D.PLAN_START_YYYYMMDD
             , D.PLAN_TYPE
             , TO_CHAR(D.SEQ)          AS SEQ
             , D.OPERATION_GROUP
             , D.FROM_SITE
             , D.ITEM_ID
             , '-'                     AS LINE_ID
             , D.BOD_ID
             , '/'                     AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'        AS MEASURE
             , SUM(D.QTY)              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD   AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) ID
             , SCP_ANL_SHIPMENT_PLAN_SEMI D
         WHERE ID.BASIS_YYYYMMDD     = D.YYYYMMDD(+)
           AND D.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9 ='U'
           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND D.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND D.MEASURE             = 'SHIP_PLAN_AMEND'
           AND D.QTY                != 0
           AND D.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY ID.WEEK_NUM
                , D.DIVISION_ID
                , D.PLAN_START_YYYYMMDD
                , D.PLAN_TYPE
                , D.SEQ
                , D.OPERATION_GROUP
                , D.FROM_SITE
                , D.ITEM_ID
                , D.BOD_ID;
        ------------------------------------------------------------------------
        -- Get Daily SCP_ANL_SHIPMENT_PLAN_FG data
        ------------------------------------------------------------------------
        --UNION ALL
        --SELECT CAL.TRG_DATE             AS TRG_DATE
        --      ,ASF.DIVISION_ID          AS DIVISION_ID
        --      ,ASF.PLAN_START_YYYYMMDD  AS PLAN_START_YYYYMMDD
        --      ,ASF.PLAN_TYPE            AS PLAN_TYPE
        --      ,ASF.SEQ                  AS SEQ
        --      ,ASF.BIZ_TYPE             AS OPERATION_GROUP
        --      ,ASF.FROM_SITE            AS FROM_SITE
        --      ,ASF.ITEM_ID              AS ITEM_ID
        --      ,'-'                      AS LINE_ID
        --      ,ASF.BOD_ID               AS BOD_ID
        --      ,ASF.PROJECT_CODE         AS PROJECT_CODE
        --      ,'SHIP_PLAN'              AS MEASURE
        --      ,SUM(ISNULL(ASF.QTY,0))   AS QTY_SUM
        --      ,@PLAN_START_YYYYMMDD     AS CREATE_FROM_YYYYMMDD
        --FROM(
        --    SELECT  'WQTY'+FORMAT(IIF(CAL.ISO_WEEK - @MIN_WEEK>0,CAL.ISO_WEEK - @MIN_WEEK,CAL.ISO_WEEK +@WEEKS_IN_YEAR - @MIN_WEEK),'00') AS WEEK_NUM
        --           ,'QTY'+FORMAT(ROW_NUMBER() OVER(ORDER BY CAL.BASIS_YYYYMMDD),'000') AS TRG_DATE
        --           ,CAL.BASIS_YYYYMMDD
        --    FROM    SCM_SYS_CALENDAR_M CAL WITH(NOLOCK)
        --    WHERE   CAL.BASIS_YYYYMMDD BETWEEN @PLAN_START_YYYYMMDD AND CONVERT(NVARCHAR(8),DATEADD(DAY,363,@PLAN_START_YYYYMMDD),112)
        --    ) CAL    
        --        LEFT OUTER JOIN SCP_ANL_SHIPMENT_PLAN_FG ASF
        --        ON  CAL.BASIS_YYYYMMDD = ASF.YYYYMMDD
        --WHERE   1=1
        --AND     ASF.PLAN_START_YYYYMMDD = @PLAN_START_YYYYMMDD
        --AND     ASF.LAST_UPDATED_BY =@UPDATE_NAME
