        ------------------------------------------------------------------------
        -- 52주 이후 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TAEE_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , TO_CHAR(A.SEQ)            AS SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , '-'                       AS BOD_ID
             , '/'                       AS PROJECT_CODE
             , A.MEASURE
             , SUM(NVL(A.QTY, 0))        AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN A
         WHERE IA.BASIS_YYYYMMDD     = A.YYYYMMDD(+)
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND A.MEASURE             = 'PROD_PLAN_AMEND'
           AND A.QTY                != 0
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IA.TRG_DATE
                , A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
                , A.MEASURE
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IB.WEEK_NUM               AS TRG_DATE
             , B.DIVISION_ID
             , B.PLAN_START_YYYYMMDD
             , B.PLAN_TYPE
             , TO_CHAR(B.SEQ)            AS SEQ
             , B.OPERATION_GROUP
             , B.SCM_SITE_ID
             , B.ITEM_ID
             , B.LINE_ID
             , '-'                       AS BOD_ID
             , '/'                       AS PROJECT_CODE
             , B.MEASURE
             , SUM(B.QTY)                AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IB
             , SCP_ANL_PRODUCTION_PLAN B
         WHERE IB.BASIS_YYYYMMDD     = B.YYYYMMDD(+)
           AND B.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
           AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND B.MEASURE             = 'PROD_PLAN_AMEND'
           AND B.QTY                != 0
           AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IB.WEEK_NUM
                , B.DIVISION_ID
                , B.PLAN_START_YYYYMMDD
                , B.PLAN_TYPE
                , B.SEQ
                , B.OPERATION_GROUP
                , B.SCM_SITE_ID
                , B.ITEM_ID
                , B.LINE_ID
                , B.MEASURE

        ------------------------------------------------------------------------
        -- Get Daily SCP_ANL_SHIPMENT_PLAN_SEMI data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IC.TRG_DATE
             , C.DIVISION_ID
             , C.PLAN_START_YYYYMMDD
             , C.PLAN_TYPE
             , TO_CHAR(C.SEQ)            AS SEQ
             , C.OPERATION_GROUP
             , C.FROM_SITE
             , C.ITEM_ID
             , '-'                       AS LINE_ID
             , C.BOD_ID
             , '/'                       AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'          AS MEASURE
             , SUM(NVL(C.QTY, 0))        AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , 'QTY' || LPAD(TO_CHAR(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD)), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IC
             , SCP_ANL_SHIPMENT_PLAN_SEMI C
         WHERE IC.BASIS_YYYYMMDD     = C.YYYYMMDD(+)
           AND C.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND C.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND C.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9      = 'U'
           AND C.MEASURE             = 'SHIP_PLAN_AMEND'
           AND C.QTY                != 0
           AND C.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY IC.TRG_DATE
                , C.DIVISION_ID
                , C.PLAN_START_YYYYMMDD
                , C.PLAN_TYPE
                , C.SEQ
                , C.OPERATION_GROUP
                , C.FROM_SITE
                , C.ITEM_ID
                , C.BOD_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT ID.WEEK_NUM               AS TRG_DATE
             , D.DIVISION_ID
             , D.PLAN_START_YYYYMMDD
             , D.PLAN_TYPE
             , TO_CHAR(D.SEQ)            AS SEQ
             , D.OPERATION_GROUP
             , D.FROM_SITE
             , D.ITEM_ID
             , '-'                       AS LINE_ID
             , D.BOD_ID
             , '/'                       AS PROJECT_CODE
             , 'SEMI_SHIP_PLAN'          AS MEASURE
             , SUM(D.QTY)                AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD AS CREATE_FROM_YYYYMMDD
          FROM (
                SELECT NULLIF('WQTY' || LPAD(TO_CHAR(CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END), 2, '0'), 'WQTY') /* NULL 이면 AS-IS 도 NULL */ AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) ID
             , SCP_ANL_SHIPMENT_PLAN_SEMI D
         WHERE ID.BASIS_YYYYMMDD     = D.YYYYMMDD(+)
           AND D.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     ASS.ATTRIBUTE9 ='U'
           AND D.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND D.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND D.MEASURE             = 'SHIP_PLAN_AMEND'
           AND D.QTY                != 0
           AND D.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
         GROUP BY ID.WEEK_NUM
                , D.DIVISION_ID
                , D.PLAN_START_YYYYMMDD
                , D.PLAN_TYPE
                , D.SEQ
                , D.OPERATION_GROUP
                , D.FROM_SITE
                , D.ITEM_ID
                , D.BOD_ID;
