        /* UPDATE PR ... FROM @XLS_PV_READY PR : 대상 = GT_TAEE_XLS_PV_READY */
        UPDATE GT_TAEE_XLS_PV_READY A
           SET A.QTY_SUM = (SELECT CAST(ROUND(A.QTY_SUM / IA.USAGE, 10) AS NUMBER(20,10))
                              FROM (
                                    SELECT CHILD_ITEM_ID
                                         , MAX(USAGE) AS USAGE
                                      FROM SCP_MST_BOM_ELEC
                                     WHERE 1 = 1
                                       AND SCP_YN = 'Y'
                                     GROUP BY CHILD_ITEM_ID
                                   ) IA
                             WHERE IA.CHILD_ITEM_ID = A.ITEM_ID
                           )
         WHERE EXISTS (SELECT 1
                         FROM SCP_MST_BOM_ELEC B
                        WHERE B.CHILD_ITEM_ID = A.ITEM_ID
                          AND B.SCP_YN        = 'Y'
                      );

        -- 속도 이슈
        INSERT INTO GT_TAEE_MS_TEMP
             ( MEASURE
             )
        SELECT DISTINCT MEASURE
          FROM GT_TAEE_XLS_PV_READY;
        INSERT INTO GT_TAEE_CFY_TEMP
             ( CREATE_FROM_YYYMMDD /* AS-IS 테이블 변수 컬럼명 그대로(YYY) */
             )
        SELECT DISTINCT CREATE_FROM_YYYYMMDD
          FROM GT_TAEE_XLS_PV_READY;

