                   AND A.PLAN_START_YYYYMMDD  = B.PLAN_START_YYYYMMDD
                   AND A.PLAN_TYPE            = B.PLAN_TYPE
                   AND A.SEQ                  = TO_NUMBER(B.SEQ)
                --AND XLS.OPERATION_GROUP      = PV.OPERATION_GROUP
                   AND A.FROM_SITE_ID         = B.FROM_SITE
                   AND A.ITEM_ID              = B.ITEM_ID
                   AND A.PROD_LINE            = B.LINE_ID
                --AND XLS.BOD_ID               = PV.BOD_ID
                   AND A.MEASURE              = B.MEASURE
                   AND A.CREATE_FROM_YYYYMMDD = B.CREATE_FROM_YYYYMMDD
                --AND XLS.PROJECT_CODE        = PV.PROJECT_CODE
                   AND ROWNUM                 = 1
               )
         WHERE EXISTS (SELECT 1
                         FROM GT_TAEE_XLS_PV_TABLE B
                        WHERE A.DIVISION_ID          = B.DIVISION_ID
                          AND A.PLAN_START_YYYYMMDD  = B.PLAN_START_YYYYMMDD
                          AND A.PLAN_TYPE            = B.PLAN_TYPE
                          AND A.SEQ                  = TO_NUMBER(B.SEQ)
                          AND A.FROM_SITE_ID         = B.FROM_SITE
                          AND A.ITEM_ID              = B.ITEM_ID
                          AND A.PROD_LINE            = B.LINE_ID
                          AND A.MEASURE              = B.MEASURE
                          AND A.CREATE_FROM_YYYYMMDD = B.CREATE_FROM_YYYYMMDD
                      )

    ;

    -- 2026.01.23 Minyong Lee : 전극 ANL 프로시저 완료 시, PLAN_MASTER에 수행 완료시점 마킹
    UPDATE SCP_OPT_ENG_PLAN_MASTER_SN
       SET ATTRIBUTE14 = TO_CHAR(SYSDATE, 'YYYY-MM-DD HH24:MI:SS') /* AS-IS GETDATE() 그대로(@NOW_DATE 아님) */
     WHERE PLAN_ID = V_PLAN_ID;

    -- 2026.06.15 Minyong Lee : I/F 수행된 버전 PLAN_MASTER ATTRIBUTE13에 마킹
    UPDATE SCP_OPT_ENG_PLAN_MASTER_SN
       SET ATTRIBUTE13 = CASE WHEN V_SCP_PLAN_DATE IS NULL OR V_SCP_PLAN_TYPE IS NULL OR V_SCP_PLAN_SEQ IS NULL THEN NULL /* MSSQL 문자 + NULL = NULL */
                              ELSE V_SCP_PLAN_DATE || ',' || V_SCP_PLAN_TYPE || ',' || V_SCP_PLAN_SEQ
                         END
     WHERE PLAN_ID = V_PLAN_ID;

    ------------------------------------------------------------------------
    -- 종료 LOG
	------------------------------------------------------------------------
    V_LOG_TYPE    := 'END';
    V_LOG_MESSAGE := '########## END of procedure ##########';
    V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                          ELSE P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID
                     END;
    V_EVENT_DATE  := SYSDATE;
    PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
    ------------------------------------------------------------------------
    -- Data Insert End
    ------------------------------------------------------------------------
        COMMIT;
	------------------------------------------------------------------------
    EXCEPTION
        WHEN OTHERS THEN
	------------------------------------------------------------------------
	--ROLLBACK TRANSACTION PR_SCP_OPT_ENG_RUN_MAIN_PROC;
	------------------------------------------------------------------------
        ROLLBACK;
	    ------------------------------------------------------------------------
          -- ERROR LOG
	    ------------------------------------------------------------------------
        V_LOG_TYPE    := 'ERROR';
        V_LOG_MESSAGE := SUBSTR(SQLERRM, 1, 1000);
        V_DESCRIPTION := CASE WHEN P_PLAN_START_YYYYMMDD IS NULL OR V_PLAN_ID IS NULL THEN NULL
                              ELSE SUBSTR('ERROR_LINE : ' || SUBSTR(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE, 1, 200) || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID, 1, 500)
                         END;
        V_EVENT_DATE  := SYSDATE;
	    --SELECT '' + Convert(NVARCHAR(10), ERROR_NUMBER()) + '' + ERROR_MESSAGE();
	    ------------------------------------------------------------------------
		INSERT INTO SCM_SYS_LOG_BATCH
		     ( PROGRAM_NAME
		     , LOG_TYPE
		     , LOG_COUNT
		     , LOG_MESSAGE
		     , DESCRIPTION
		     , EVENT_DATE
		     , CREATION_DATE
		     , CREATED_BY
		     , LAST_UPDATE_DATE
		     , LAST_UPDATED_BY
		     )
		VALUES
		     ( 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE'
		     , V_LOG_TYPE
		     , NULL
		     , V_LOG_MESSAGE
		     , V_DESCRIPTION
		     , SYSDATE
		     , SYSDATE
		     , 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE'
		     , SYSDATE
		     , 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE'
		     );
		COMMIT;
	    --EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
	    ------------------------------------------------------------------------
        V_MESSAGE_TEXT := SUBSTR(SQLERRM, 1, 1000);
        DBMS_OUTPUT.PUT_LINE(V_MESSAGE_TEXT);
        RAISE;

    END;

	------------------------------------------------------------------------

    ------------------------------------------------------------------------
END PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE;
/
SHOW ERRORS PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE
-- ##### END PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_EE

-- ##### START PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_ESS
CREATE OR REPLACE PROCEDURE PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_ESS
(
    P_PLAN_ID               IN  VARCHAR2
  , P_PLAN_START_YYYYMMDD   IN  VARCHAR2
)
IS
    /*
     * Program ID   : PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_ESS
     * Description  : 최적화 엔진 결과(ESS)를 SCP 분석 테이블(생산·SEMI 출하·FG 출하·FIX)과 SCP_XLS_PSI_GLOBAL_ESS 에 반영
     * Program History
     *===================================================================================================
     *   Date       In Charge      Description
     *===================================================================================================
     * 2025.02.07   Taehyun      Initial Release
     * 2026.10.06   ZIONEX       [PJ202650304] MSSQL -> Oracle 전환
     */

	------------------------------------------------------------------------
	-- Set Param for Log
	------------------------------------------------------------------------
    V_PROGRAM_NAME              VARCHAR2(150 CHAR) := 'PR_SCP_OPT_ENG_OUTPUT_TRANS_ANL_ESS';
    V_PLAN_ID                   VARCHAR2(50 CHAR)  := SUBSTR(P_PLAN_ID, 1, 50);   /* AS-IS @P_PLAN_ID NVARCHAR(50) 길이로 잘림 */
    V_MESSAGE_TEXT              VARCHAR2(1000 CHAR);
    ------------------------------------------------------------------------
	-- LOG 용 변수 설정
	------------------------------------------------------------------------
    --DECLARE @v_program_name NVARCHAR(150) = 'PR_SCM_LGTM_INV_ALLOCATION';
    V_LOG_TYPE                  VARCHAR2(30 CHAR); -- START/END/ERROR/...
    V_LOG_COUNT                 NUMBER := 0;
    V_LOG_MESSAGE               VARCHAR2(1000 CHAR);
    V_DESCRIPTION               VARCHAR2(500 CHAR);
    V_EVENT_DATE                DATE;
    ---------------------   ---------------------------------------------------
    -- Set Param for Biz
    ------------------------------------------------------------------------
    V_SCP_PLAN_DATE             VARCHAR2(8 CHAR);
    V_SCP_PLAN_TYPE             VARCHAR2(8 CHAR);
    V_SCP_PLAN_SEQ              VARCHAR2(8 CHAR);
    V_DIVISION_ID               VARCHAR2(10 CHAR);
    V_PLAN_START_YYYYMMDD       VARCHAR2(8 CHAR);
    V_PLAN_END_YYYYMMDD         VARCHAR2(8 CHAR);
    V_2ND_PLAN_START_YYYYMMDD   VARCHAR2(8 CHAR);
    V_NOW_DATE                  DATE;
    V_MIN_WEEK                  NUMBER;
    V_2ND_MIN_WEEK              NUMBER;
    -- 2026.07.22 Minyong Lee : [E20260713-000080] [ODS] 업로드 수량 이상건 수정
    V_WEEKS_IN_YEAR             NUMBER;
    V_2ND_WEEKS_IN_YEAR         NUMBER;
    V_UPDATE_NAME               VARCHAR2(100 CHAR);
    V_OP_COUNT                  PLS_INTEGER;
    V_CHK_INTEGRAL              VARCHAR2(100 CHAR);
    --속도이슈
    /* AS-IS 테이블 변수 8종 → GTT : GT_TAES_MS_TEMP, GT_TAES_CFY_TEMP, GT_TAES_OP_RESULT, GT_TAES_OS_RESULT,
       GT_TAES_OS_RESULT_FG, GT_TAES_OS_RESULT_FG_SMMR, GT_TAES_XLS_PV_READY, GT_TAES_XLS_PV_TABLE
       (DDL : (DDL) 00_GTT_TAES_SCP0123.sql) */
BEGIN
    --2025.02.07 Taehyun Initial Release
	------------------------------------------------------------------------
    -- Procedure 기본조건.
	------------------------------------------------------------------------
	/* AS-IS SET XACT_ABORT ON / SET NOCOUNT ON / SET TRANSACTION ISOLATION LEVEL READ COMMITTED 삭제 */
	/* GTT 초기화 (AS-IS 테이블 변수는 호출마다 빈 상태로 시작) */
    DELETE FROM GT_TAES_MS_TEMP;
    DELETE FROM GT_TAES_CFY_TEMP;
    DELETE FROM GT_TAES_OP_RESULT;
    DELETE FROM GT_TAES_OS_RESULT;
    DELETE FROM GT_TAES_OS_RESULT_FG;
    DELETE FROM GT_TAES_OS_RESULT_FG_SMMR;
    DELETE FROM GT_TAES_XLS_PV_READY;
    DELETE FROM GT_TAES_XLS_PV_TABLE;
	------------------------------------------------------------------------

	------------------------------------------------------------------------
	-- LOG 시작
	------------------------------------------------------------------------
	V_LOG_TYPE := 'START';
	V_LOG_MESSAGE := '########## Start of procedure ##########';
	V_DESCRIPTION := 'START_' || V_PROGRAM_NAME || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID;
	V_EVENT_DATE := SYSDATE;
	PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);
	------------------------------------------------------------------------
    /* 스칼라 서브쿼리 대입 : 0행이면 NULL */
    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = P_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_MIN_WEEK := NULL;
    END;
    V_UPDATE_NAME := CASE WHEN V_PLAN_ID IS NULL THEN NULL ELSE 'OPT_ENG_' || V_PLAN_ID END;   /* AS-IS 문자 + 는 NULL 이 있으면 NULL */
    --52주 이후 구간의 데이터를 GLOBAL 테이블에 넣기 위한 변수 설정
    V_2ND_PLAN_START_YYYYMMDD := TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 364, 'YYYYMMDD');
    BEGIN
        SELECT TO_NUMBER(ISO_WEEK) - 1
          INTO V_2ND_MIN_WEEK
          FROM SCM_SYS_CALENDAR_M
         WHERE BASIS_YYYYMMDD = V_2ND_PLAN_START_YYYYMMDD;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            V_2ND_MIN_WEEK := NULL;
    END;

    -- 2026.07.22 Minyong Lee : [E20260713-000080] [ODS] 업로드 수량 이상건 수정
    -- 섹션1 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD LIKE SUBSTR(P_PLAN_START_YYYYMMDD, 1, 4) || '%';   /* AS-IS LEFT(BASIS_YYYYMMDD,4) = LEFT(@PLAN_START_YYYYMMDD,4) */
    -- 섹션2(52주 이후 구간) 시작연도의 실제 주차 수 (52 or 53)
    SELECT MAX(TO_NUMBER(ISO_WEEK))
      INTO V_2ND_WEEKS_IN_YEAR
      FROM SCM_SYS_CALENDAR_M
     WHERE BASIS_YYYYMMDD LIKE SUBSTR(V_2ND_PLAN_START_YYYYMMDD, 1, 4) || '%';   /* AS-IS LEFT(BASIS_YYYYMMDD,4) = LEFT(@2ND_PLAN_START_YYYYMMDD,4) */

    V_NOW_DATE := SYSDATE;
    --SELECT  @V_DIVISION_ID = DIVISION_ID
    --       ,@V_PLAN_START_YYYYMMDD = PLAN_START_YYYYMMDD
    --       ,@V_PLAN_END_YYYYMMDD   = PLAN_END_YYYYMMDD
    --FROM    SCP_OPT_ENG_SCP_PLAN_ID_M_SN WITH(NOLOCK)
    --WHERE   1=1
    --AND     PLAN_ID = @V_PLAN_ID

    --SELECT   @V_DIVISION_ID         = PM.DIVISION_ID
    --        ,@V_PLAN_START_YYYYMMDD = PM.PLAN_START_YYYYMMDD
    --        ,@V_PLAN_END_YYYYMMDD   = PM.PLAN_END_YYYYMMDD
    --FROM    SCP_OPMZ_PLAN_M PM WITH(NOLOCK)
    --WHERE   PM.OPMZ_PLAN_ID = @V_PLAN_ID

    /* 변수 대입 SELECT : 0행이면 변수 유지(NULL), 여러 행이면 정렬 마지막 행 1건 */
    BEGIN
        SELECT SUBSTR(XA.DIVISION_ID, 1, 10)
             , SUBSTR(XA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(XA.PLAN_END_YYYYMMDD, 1, 8)
          INTO V_DIVISION_ID
             , V_PLAN_START_YYYYMMDD
             , V_PLAN_END_YYYYMMDD
          FROM (SELECT IA.DIVISION_ID
                     , IA.PLAN_START_YYYYMMDD
                     , IA.PLAN_END_YYYYMMDD
                  FROM (SELECT DIVISION_ID
                             , PLAN_START_YYYYMMDD
                             , PLAN_END_YYYYMMDD
                          FROM SCP_OPMZ_PLAN_M
                         WHERE OPMZ_PLAN_ID = V_PLAN_ID
                         UNION
                        SELECT DIVISION_ID
                             , PLAN_START_YYYYMMDD
                             , PLAN_END_YYYYMMDD
                          FROM SCP_OPT_ENG_SCP_PLAN_ID_M_SN
                         WHERE PLAN_ID = V_PLAN_ID
                       ) IA
                 ORDER BY IA.DIVISION_ID DESC NULLS LAST
                        , IA.PLAN_START_YYYYMMDD DESC NULLS LAST
                        , IA.PLAN_END_YYYYMMDD DESC NULLS LAST
               ) XA
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    /* 변수 대입 SELECT (TOP 1) : 0행이면 변수 유지(NULL) */
    BEGIN
        SELECT SUBSTR(XA.PLAN_START_YYYYMMDD, 1, 8)
             , SUBSTR(XA.PLAN_TYPE, 1, 8)
             , TO_CHAR(XA.PLAN_SEQ)
          INTO V_SCP_PLAN_DATE
             , V_SCP_PLAN_TYPE
             , V_SCP_PLAN_SEQ
          FROM (SELECT DIVISION_ID
                     , PLAN_START_YYYYMMDD
                     , PLAN_TYPE
                     , PLAN_SEQ
                     , PLAN_TYPE_ORDER
                     , CONFIRM_FLAG
                  FROM SCP_PLAN_VERSION_V
                 WHERE DIVISION_ID          = V_DIVISION_ID
                   AND PLAN_START_YYYYMMDD  = P_PLAN_START_YYYYMMDD
                 -- 2026.03.17 Minyong Lee : FN 이후 TE Plan Type 추가 건 대응
                 --ORDER BY PLAN_TYPE_ORDER DESC, CONFIRM_FLAG DESC, PLAN_SEQ DESC
                 ORDER BY CASE WHEN PLAN_TYPE = 'TE' THEN 0 ELSE 1 END ASC
                        , PLAN_TYPE_ORDER DESC NULLS LAST
                        , CONFIRM_FLAG DESC NULLS LAST
                        , PLAN_SEQ DESC
               ) XA
         WHERE ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            NULL;
    END;

    /* 변수 대입 SELECT : 0행이면 변수 유지(NULL) → MAX 로 같은 결과 */
    SELECT MAX(PLAN_ID)
      INTO V_CHK_INTEGRAL
      FROM SCP_OPT_ENG_PHASES_SN
     WHERE UPPER(PRINT_RESULT) LIKE '%INTEGRAL%'   /* AS-IS 대소문자 무시 LIKE */
       AND PLAN_ID = V_PLAN_ID;


    IF (V_SCP_PLAN_TYPE = 'FN') THEN
            ------------------------------------------------------------------------
            -- 종료 LOG
	        ------------------------------------------------------------------------
            V_LOG_TYPE := 'END';
            V_LOG_MESSAGE := '########## END of procedure ##########';
            V_DESCRIPTION := 'SCP_PLAN_TYPE IS FN' || '@' || P_PLAN_START_YYYYMMDD || '@' || V_PLAN_ID;
            V_EVENT_DATE := SYSDATE;
            PR_SCM_SYS_LOG_BATCH(V_PROGRAM_NAME, V_LOG_TYPE, V_LOG_COUNT, V_LOG_MESSAGE, V_DESCRIPTION, V_EVENT_DATE);

            /* AS-IS SET XACT_ABORT OFF 삭제 */
            RAISE_APPLICATION_ERROR(-20001, ' I/F not executed because PLAN_TYPE is FN.');
    END IF;
    ------------------------------------------------------------------------
	-- Transaction (START)
	------------------------------------------------------------------------
	BEGIN
        /* AS-IS BEGIN TRAN : Oracle 은 첫 DML 에서 트랜잭션 시작 */

        ------------------------------------------------------------------------
        -- 엔진 결과에서 문자열 'E'를 붙여서 나오는 데이터 치환
        ------------------------------------------------------------------------
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN
           SET ATTRIBUTE1  = OUT_QTY
             , OUT_QTY     = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY) END))
         WHERE UPPER(OUT_QTY) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN
           SET ATTRIBUTE1  = OUT_QTY_INT
             , OUT_QTY_INT = TO_CHAR(ROUND(CASE WHEN UPPER(OUT_QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(OUT_QTY_INT) END))
         WHERE UPPER(OUT_QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN
           SET ATTRIBUTE1  = QTY_INT
             , QTY_INT     = TO_CHAR(ROUND(CASE WHEN UPPER(QTY_INT) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY_INT) END))
         WHERE UPPER(QTY_INT) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;
        UPDATE SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN
           SET ATTRIBUTE1  = QTY
             , QTY         = TO_CHAR(ROUND(CASE WHEN UPPER(QTY) LIKE '%E-%' THEN 0 ELSE TO_NUMBER(QTY) END))
         WHERE UPPER(QTY) LIKE '%E%'
           AND PLAN_ID = V_PLAN_ID;

    ------------------------------------------------------------------------
    -- ORDER_PRODUCTION DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Production Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TAES_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , D.BASIS_YYYYMMDD                     AS START_DATE
                 , SUM(CASE WHEN D.BASIS_YYYYMMDD = A.START_DATE THEN CAST(A.OUT_QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY
                 , B.RESOURCE_NAME                      AS LINE_ID
                 , C.OPERATION_GROUP
                 , NVL(E.OPERATION_ID, C.FLOW_ID)       AS OPERATION_ID
                 , NULL                                 AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN A
                 , (SELECT PRODUCTION_ORDER_ID
                         , PRODUCTION_LINE_ID
                         , PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_SN
                     WHERE PLAN_ID = V_PLAN_ID
                     GROUP BY PRODUCTION_ORDER_ID
                            , PRODUCTION_LINE_ID
                            , PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCP_MST_FINAL_ITEM C
                 , SCM_SYS_CALENDAR_M D
                 , SCM_MST_LINE_OSP E
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND C.ITEM_ID             = A.ITEM_ID
               AND A.SITE_ID             = E.SCM_SITE_ID(+)
               AND B.RESOURCE_NAME       = E.LINE_ID(+)
            -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
            --AND   OP.GRADE IN ( 'ASSY','PACK','MDLE','RACK','LINK')
               AND A.GRADE IN ('LINK')
               AND IA.PLAN_ID IS NOT NULL
               AND C.DIVISION_ID         = V_DIVISION_ID
               AND A.PLAN_ID             = V_PLAN_ID
               AND D.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , D.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , C.OPERATION_GROUP
                    , C.FLOW_ID
                    , E.OPERATION_ID;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TAES_OP_RESULT
                 ( SITE_ID
                 , ITEM_ID
                 , GRADE
                 , START_DATE
                 , OUT_QTY_INT
                 , LINE_ID
                 , OPERATION_GROUP
                 , OPERATION_ID
                 , ELECTRODE_TYPE
                 )
            SELECT A.SITE_ID
                 , A.ITEM_ID
                 , A.GRADE
                 , D.BASIS_YYYYMMDD                     AS START_DATE
                 , SUM(CASE WHEN D.BASIS_YYYYMMDD = A.START_DATE THEN CAST(A.OUT_QTY_INT AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , B.RESOURCE_NAME                      AS LINE_ID
                 , C.OPERATION_GROUP
                 , NVL(E.OPERATION_ID, C.FLOW_ID)       AS OPERATION_ID
                 , NULL                                 AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
              FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_INT_SN A
                 , (SELECT PRODUCTION_ORDER_ID
                         , PRODUCTION_LINE_ID
                         , PLAN_ID
                      FROM SCP_OPT_ENG_OUT_DEMAND_ASSIGN_PEGGING_INT_SN
                     WHERE PLAN_ID = V_PLAN_ID
                     GROUP BY PRODUCTION_ORDER_ID
                            , PRODUCTION_LINE_ID
                            , PLAN_ID
                   ) IA
                 , SCP_OPT_ENG_RESOURCE_SN B
                 , SCP_MST_FINAL_ITEM C
                 , SCM_SYS_CALENDAR_M D
                 , SCM_MST_LINE_OSP E
             WHERE A.PLAN_ID             = IA.PLAN_ID(+)
               AND A.PRODUCTION_ORDER_ID = IA.PRODUCTION_ORDER_ID(+)
               AND A.PLAN_ID             = B.PLAN_ID
               AND IA.PRODUCTION_LINE_ID = B.RESOURCE_ID
               AND C.ITEM_ID             = A.ITEM_ID
               AND A.SITE_ID             = E.SCM_SITE_ID(+)
               AND B.RESOURCE_NAME       = E.LINE_ID(+)
            -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
            --AND   OP.GRADE IN ( 'ASSY','PACK','MDLE','RACK','LINK')
               AND A.GRADE IN ('LINK')
               AND IA.PLAN_ID IS NOT NULL
               AND C.DIVISION_ID         = V_DIVISION_ID
               AND A.PLAN_ID             = V_PLAN_ID
               AND D.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY A.SITE_ID
                    , A.ITEM_ID
                    , A.GRADE
                    , D.BASIS_YYYYMMDD
                    , B.RESOURCE_NAME
                    , C.OPERATION_GROUP
                    , C.FLOW_ID
                    , E.OPERATION_ID;
        END IF;

        ------------------------------------------------------------------------
        -- 생산 결과가 없으면 Error 생성
        ------------------------------------------------------------------------
        SELECT COUNT(*)
          INTO V_OP_COUNT
          FROM GT_TAES_OP_RESULT;

        IF V_OP_COUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20001, 'Order Production count is zero');
        END IF;
        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.SCM_SITE_ID = SA.SCM_SITE_ID
                          AND A.ITEM_ID     = SA.ITEM_ID
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;

        DBMS_OUTPUT.PUT_LINE('SCP_ANL_PRODUCTION_PLAN');

        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        /* AS-IS MERGE → ① UPDATE (WHEN MATCHED) ② INSERT (WHEN NOT MATCHED) */
        UPDATE SCP_ANL_PRODUCTION_PLAN A
           SET ( A.QTY
               , A.LAST_UPDATE_DATE
               , A.LAST_UPDATED_BY
               ) = (SELECT B.OUT_QTY_INT
                         , V_NOW_DATE
                         , V_UPDATE_NAME
                      FROM GT_TAES_OP_RESULT B
                     WHERE A.OPERATION_GROUP = B.OPERATION_GROUP
                       AND A.SCM_SITE_ID     = B.SITE_ID
                       AND A.ITEM_ID         = B.ITEM_ID
                       AND A.LINE_ID         = B.LINE_ID
                       AND A.OPERATION_ID    = B.OPERATION_ID
                       AND A.YYYYMMDD        = B.START_DATE
                       AND ROWNUM = 1
                   )
                      --,ANL.ATTRIBUTE9        = 'U'
                      --,ANL.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAES_OP_RESULT C
                        WHERE A.OPERATION_GROUP = C.OPERATION_GROUP
                          AND A.SCM_SITE_ID     = C.SITE_ID
                          AND A.ITEM_ID         = C.ITEM_ID
                          AND A.LINE_ID         = C.LINE_ID
                          AND A.OPERATION_ID    = C.OPERATION_ID
                          AND A.YYYYMMDD        = C.START_DATE
                      )
           AND A.MEASURE             IN ('PROD_PLAN_AMEND')
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        INSERT INTO SCP_ANL_PRODUCTION_PLAN
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , A.OPERATION_GROUP
             , A.SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , A.OPERATION_ID
             , 'PROD_PLAN_AMEND'
             , A.START_DATE
             , A.OUT_QTY_INT
             , V_DIVISION_ID
             , A.ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM GT_TAES_OP_RESULT A
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_PRODUCTION_PLAN B
                            WHERE B.OPERATION_GROUP     = A.OPERATION_GROUP
                              AND B.SCM_SITE_ID         = A.SITE_ID
                              AND B.ITEM_ID             = A.ITEM_ID
                              AND B.LINE_ID             = A.LINE_ID
                              AND B.OPERATION_ID        = A.OPERATION_ID
                              AND B.YYYYMMDD            = A.START_DATE
                              AND B.MEASURE             IN ('PROD_PLAN_AMEND')
                              AND B.DIVISION_ID         = V_DIVISION_ID
                              AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND B.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_H.NEXTVAL
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN
         WHERE MEASURE             IN ('PROD_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;

        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.SCM_SITE_ID = SA.SCM_SITE_ID
                          AND A.ITEM_ID     = SA.ITEM_ID
                      )
           AND A.QTY != 0
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- UPDATE SCP_ANL_PRODUCTION_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_PRODUCTION_PLAN_FIX A
           SET ( A.QTY
               , A.LAST_UPDATED_BY
               , A.LAST_UPDATE_DATE
               ) = (SELECT B.OUT_QTY_INT
                         , V_UPDATE_NAME
                         , V_NOW_DATE
                      FROM GT_TAES_OP_RESULT B
                     WHERE A.OPERATION_GROUP = B.OPERATION_GROUP
                       AND A.SCM_SITE_ID     = B.SITE_ID
                       AND A.ITEM_ID         = B.ITEM_ID
                       AND A.LINE_ID         = B.LINE_ID
                       AND A.OPERATION_ID    = B.OPERATION_ID
                       AND A.YYYYMMDD        = B.START_DATE
                       AND ROWNUM = 1
                   )
          --, SCP_ANL_PRODUCTION_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAES_OP_RESULT C
                        WHERE A.OPERATION_GROUP = C.OPERATION_GROUP
                          AND A.SCM_SITE_ID     = C.SITE_ID
                          AND A.ITEM_ID         = C.ITEM_ID
                          AND A.LINE_ID         = C.LINE_ID
                          AND A.OPERATION_ID    = C.OPERATION_ID
                          AND A.YYYYMMDD        = C.START_DATE
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_PRODUCTION_PLAN_FIX_H
             ( HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL
             , FIX_ID
             , DIVISION_ID
             , OPERATION_GROUP
             , SCM_SITE_ID
             , ITEM_ID
             , LINE_ID
             , OPERATION_ID
             , YYYYMMDD
             , QTY
             , FIX_REASON
             , ORIGIN_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_PRODUCTION_PLAN_FIX
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;

    ------------------------------------------------------------------------
    -- ORDER_SHIPPING SEMI DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TAES_OS_RESULT
                 ( OPERATION_GROUP
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 )
            SELECT IA.OPERATION_GROUP
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                 , A.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN A.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
              FROM (SELECT SC.OPERATION_GROUP
                         , SA.ITEM_ID
                         , SA.FROM_SITE_ID          AS FROM_SITE
                         , SB.ATTRIBUTE7            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'        AS MEASURE
                         , SA.DEPARTURE_DATE        AS YYYYMMDD
                         , SA.TO_SITE_ID            AS TO_SITE
                         , TO_NUMBER(SA.QTY)        AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SB.ATTRIBUTE8            AS BOD_TYPE
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN SA
                         , SCP_OPT_ENG_BOD_SN SB
                         , SCP_MST_FINAL_ITEM SC
                     WHERE SA.BOD_ID   = SB.BOD_ID
                       AND SC.ITEM_ID  = SA.ITEM_ID
                       AND SB.ATTRIBUTE8 = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND SA.GRADE IN ('PACK', 'LINK') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SB.PLAN_ID    = V_PLAN_ID
                       AND SC.DIVISION_ID = V_DIVISION_ID
                       AND SA.PLAN_ID    = V_PLAN_ID

                     UNION ALL
                    SELECT SE.OPERATION_GROUP
                         , SD.ATTRIBUTE2                       AS ITEM_ID
                         , SD.ATTRIBUTE1                       AS FROM_SITE
                         , SD.ATTRIBUTE7                       AS BOD_ID
                         , 'SHIP_PLAN_AMEND'                   AS MEASURE
                         , SD.DEPARTURE_DATE                   AS YYYYMMDD
                         , SD.ATTRIBUTE4                       AS TO_SITE
                         , CAST(SD.QUANTITY AS NUMBER(38,10))  AS QTY
                         , V_DIVISION_ID                       AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID                       AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                                AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SD.ATTRIBUTE8                       AS BOD_TYPE
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SD
                         , SCP_MST_FINAL_ITEM SE
                     WHERE SE.ITEM_ID     = SD.ATTRIBUTE2
                       AND SD.ATTRIBUTE5 IN ('PACK', 'LINK') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SD.ATTRIBUTE6 ='IN'
                       AND SD.ATTRIBUTE8 ='PLANT'
                       AND SE.DIVISION_ID = V_DIVISION_ID
                       AND SD.PLAN_ID     = V_PLAN_ID
                   ) IA
                 , SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.OPERATION_GROUP
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , A.BASIS_YYYYMMDD;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TAES_OS_RESULT
                 ( OPERATION_GROUP
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 )
            SELECT IA.OPERATION_GROUP
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                 , A.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN A.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
              FROM (SELECT SC.OPERATION_GROUP
                         , SA.ITEM_ID
                         , SA.FROM_SITE_ID          AS FROM_SITE
                         , SB.ATTRIBUTE7            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'        AS MEASURE
                         , SA.DEPARTURE_DATE        AS YYYYMMDD
                         , SA.TO_SITE_ID            AS TO_SITE
                         , TO_NUMBER(SA.QTY_INT)    AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SB.ATTRIBUTE8            AS BOD_TYPE
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN SA
                         , SCP_OPT_ENG_BOD_SN SB
                         , SCP_MST_FINAL_ITEM SC
                     WHERE SA.BOD_ID   = SB.BOD_ID
                       AND SC.ITEM_ID  = SA.ITEM_ID
                       AND SB.ATTRIBUTE8 = 'PLANT'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND SA.GRADE IN ('PACK', 'LINK') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SB.PLAN_ID    = V_PLAN_ID
                       AND SC.DIVISION_ID = V_DIVISION_ID
                       AND SA.PLAN_ID    = V_PLAN_ID

                     UNION ALL
                    SELECT SE.OPERATION_GROUP
                         , SD.ATTRIBUTE2                       AS ITEM_ID
                         , SD.ATTRIBUTE1                       AS FROM_SITE
                         , SD.ATTRIBUTE7                       AS BOD_ID
                         , 'SHIP_PLAN_AMEND'                   AS MEASURE
                         , SD.DEPARTURE_DATE                   AS YYYYMMDD
                         , SD.ATTRIBUTE4                       AS TO_SITE
                         , CAST(SD.QUANTITY AS NUMBER(38,10))  AS QTY
                         , V_DIVISION_ID                       AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID                       AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                                AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SD.ATTRIBUTE8                       AS BOD_TYPE
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SD
                         , SCP_MST_FINAL_ITEM SE
                     WHERE SE.ITEM_ID     = SD.ATTRIBUTE2
                       AND SD.ATTRIBUTE5 IN ('PACK', 'LINK') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SD.ATTRIBUTE6 ='IN'
                       AND SD.ATTRIBUTE8 ='PLANT'
                       AND SE.DIVISION_ID = V_DIVISION_ID
                       AND SD.PLAN_ID     = V_PLAN_ID
                   ) IA
                 , SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.OPERATION_GROUP
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , A.BASIS_YYYYMMDD;
        END IF;

        ------------------------------------------------------------------------
        -- Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_SEMI A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9        = 'U'
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.FROM_SITE = SA.SCM_SITE_ID
                          AND A.ITEM_ID   = SA.ITEM_ID
                      )
           AND A.MEASURE             IN ('SHIP_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;


        ------------------------------------------------------------------------
        -- MERGE INTO OPT ENG Data
        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_SEMI');
        /* AS-IS MERGE → ① UPDATE (WHEN MATCHED) ② INSERT (WHEN NOT MATCHED) */
        UPDATE SCP_ANL_SHIPMENT_PLAN_SEMI A
           SET ( A.QTY
               , A.LAST_UPDATE_DATE
               , A.LAST_UPDATED_BY
               ) = (SELECT B.QTY
                         , V_NOW_DATE
                         , V_UPDATE_NAME
                      FROM GT_TAES_OS_RESULT B
                     WHERE A.OPERATION_GROUP = B.OPERATION_GROUP
                       AND A.ITEM_ID         = B.ITEM_ID
                       AND A.FROM_SITE       = B.FROM_SITE
                       AND A.BOD_ID          = B.BOD_ID
                       AND A.MEASURE         = B.MEASURE
                       AND A.YYYYMMDD        = B.YYYYMMDD
                       AND ROWNUM = 1
                   )
                      --,ANL.ATTRIBUTE9       = 'U'
                      --,ANL.ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAES_OS_RESULT C
                        WHERE A.OPERATION_GROUP = C.OPERATION_GROUP
                          AND A.ITEM_ID         = C.ITEM_ID
                          AND A.FROM_SITE       = C.FROM_SITE
                          AND A.BOD_ID          = C.BOD_ID
                          AND A.MEASURE         = C.MEASURE
                          AND A.YYYYMMDD        = C.YYYYMMDD
                      )
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ);

        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI
             ( DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , TO_SITE
             , QTY
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
               --,ATTRIBUTE9
               --,ATTRIBUTE10
             )
        SELECT V_DIVISION_ID
             , P_PLAN_START_YYYYMMDD
             , V_SCP_PLAN_TYPE
             , TO_NUMBER(V_SCP_PLAN_SEQ)
             , A.OPERATION_GROUP
             , A.ITEM_ID
             , A.FROM_SITE
             , A.BOD_ID
             , A.MEASURE
             , A.YYYYMMDD
             , A.TO_SITE
             , A.QTY
             , A.ORIGIN_TO_DIVISION_ID   /* AS-IS 그대로 : FROM 칸에 TO 값 */
             , A.ORIGIN_FROM_DIVISION_ID /* AS-IS 그대로 : TO 칸에 FROM 값 */
             , A.ELECTRODE_TYPE
             , V_UPDATE_NAME
             , V_NOW_DATE
             , V_UPDATE_NAME
             , V_NOW_DATE
              --,'I'
              --,CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/MERGE'
          FROM GT_TAES_OS_RESULT A
         WHERE NOT EXISTS (SELECT 1
                             FROM SCP_ANL_SHIPMENT_PLAN_SEMI B
                            WHERE B.OPERATION_GROUP     = A.OPERATION_GROUP
                              AND B.ITEM_ID             = A.ITEM_ID
                              AND B.FROM_SITE           = A.FROM_SITE
                              AND B.BOD_ID              = A.BOD_ID
                              AND B.MEASURE             = A.MEASURE
                              AND B.YYYYMMDD            = A.YYYYMMDD
                              AND B.DIVISION_ID         = V_DIVISION_ID
                              AND B.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                              AND B.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                              AND B.PLAN_TYPE           = V_SCP_PLAN_TYPE
                              AND B.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                          );
        ------------------------------------------------------------------------
        -- INSERT HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_SEMI_H
             ( HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , UPDATE_REASON_BOD
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_SHIPMENT_PLAN_SEMI_H.NEXTVAL AS HISTORY_SEQ
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , ITEM_ID
             , FROM_SITE
             , TO_SITE
             , BOD_ID
             , MEASURE
             , YYYYMMDD
             , QTY
             , NULL                 AS UPDATE_REASON_BOD
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE           AS HISTORY_CREATION_DATE
          FROM SCP_ANL_SHIPMENT_PLAN_SEMI
         WHERE MEASURE             IN ('SHIP_PLAN_AMEND')
           AND DIVISION_ID         = V_DIVISION_ID
           AND PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;


        ------------------------------------------------------------------------
        -- Initialization SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.FROM_SITE = SA.SCM_SITE_ID
                          AND A.ITEM_ID   = SA.ITEM_ID
                      )
           AND A.QTY != 0
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND A.DIVISION_ID = V_DIVISION_ID;


        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET ( A.QTY
               , A.LAST_UPDATED_BY
               , A.LAST_UPDATE_DATE
               ) = (SELECT B.QTY
                         , V_UPDATE_NAME
                         , V_NOW_DATE
                      FROM GT_TAES_OS_RESULT B
                     WHERE A.BIZ_TYPE  = B.OPERATION_GROUP
                       AND A.ITEM_ID   = B.ITEM_ID
                       AND A.TO_SITE   = B.TO_SITE
                       AND A.FROM_SITE = B.FROM_SITE
                       AND A.BOD_ID    = B.BOD_ID
                       AND A.YYYYMMDD  = B.YYYYMMDD
                       AND ROWNUM = 1
                   )
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAES_OS_RESULT C
                        WHERE A.BIZ_TYPE  = C.OPERATION_GROUP
                          AND A.ITEM_ID   = C.ITEM_ID
                          AND A.TO_SITE   = C.TO_SITE
                          AND A.FROM_SITE = C.FROM_SITE
                          AND A.BOD_ID    = C.BOD_ID
                          AND A.YYYYMMDD  = C.YYYYMMDD
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;

    ------------------------------------------------------------------------
    -- ORDER_SHIPPING FG DATA START
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- Get Order Shipping Int data
        ------------------------------------------------------------------------
        IF V_CHK_INTEGRAL IS NULL THEN
            INSERT INTO GT_TAES_OS_RESULT_FG
                 ( OPERATION_GROUP
                 , PROJECT_CODE
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 , INCOTERMS
                 )
            SELECT IA.BIZ_TYPE
                 , IA.PROJECT_CODE
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                  --,YYYYMMDD
                 , A.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN A.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                  --,QTY
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
                 , IA.INCOTERMS
              FROM (SELECT SC.OPERATION_GROUP       AS BIZ_TYPE
                         , SB.ATTRIBUTE9            AS PROJECT_CODE
                         , SA.ITEM_ID
                         , SA.FROM_SITE_ID          AS FROM_SITE
                         , SB.ATTRIBUTE7            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'        AS MEASURE
                         , SA.DEPARTURE_DATE        AS YYYYMMDD
                         , SA.TO_SITE_ID            AS TO_SITE
                         , TO_NUMBER(SA.QTY)        AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SB.ATTRIBUTE8            AS BOD_TYPE
                         , SB.ATTRIBUTE6            AS INCOTERMS
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_SN SA
                         , SCP_OPT_ENG_BOD_SN SB
                         , SCP_MST_FINAL_ITEM SC
                     WHERE SA.BOD_ID   = SB.BOD_ID
                       AND SC.ITEM_ID  = SA.ITEM_ID
                       AND (SA.GRADE LIKE 'PACKBIZ%' OR SA.GRADE LIKE 'LINKBIZ%') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SB.ATTRIBUTE8 = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND SB.ATTRIBUTE7 <> 'DUMMY'
                       AND SB.PLAN_ID     = V_PLAN_ID
                       AND SC.DIVISION_ID = V_DIVISION_ID
                       AND SA.PLAN_ID     = V_PLAN_ID
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                     UNION ALL
                    SELECT SE.OPERATION_GROUP
                         , SD.ATTRIBUTE10                           AS PROJECT_CODE
                         , SD.ATTRIBUTE2                            AS ITEM_ID
                         , SD.ATTRIBUTE1                            AS FROM_SITE
                         , SD.ATTRIBUTE7                            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'                        AS MEASURE
                         , SD.DEPARTURE_DATE                        AS YYYYMMDD
                         , SD.ATTRIBUTE4                            AS TO_SITE
                         , CAST(SUM(SD.QUANTITY) AS NUMBER(38,10))  AS QTY
                         , V_DIVISION_ID                            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID                            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SD.ATTRIBUTE8                            AS BOD_TYPE
                         , SD.ATTRIBUTE9                            AS INCOTERMS
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SD
                         , SCP_MST_FINAL_ITEM SE
                     WHERE SE.ITEM_ID     = SD.ATTRIBUTE2
                       AND SD.ATTRIBUTE5 IN ('PACKBIZ', 'LINKBIZ') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SD.ATTRIBUTE6 ='IN'
                       AND SD.ATTRIBUTE8 ='SALES'
                       AND SE.DIVISION_ID = V_DIVISION_ID
                       AND SD.PLAN_ID     = V_PLAN_ID
                     GROUP BY SE.OPERATION_GROUP
                            , SD.ATTRIBUTE10
                            , SD.ATTRIBUTE2
                            , SD.ATTRIBUTE1
                            , SD.ATTRIBUTE7
                            , SD.DEPARTURE_DATE
                            , SD.ATTRIBUTE4
                            , SD.ATTRIBUTE8
                            , SD.ATTRIBUTE9 -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                   ) IA
                 , SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.BIZ_TYPE
                    , IA.PROJECT_CODE
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , IA.INCOTERMS
                    , A.BASIS_YYYYMMDD;
        ELSIF V_CHK_INTEGRAL IS NOT NULL THEN
            INSERT INTO GT_TAES_OS_RESULT_FG
                 ( OPERATION_GROUP
                 , PROJECT_CODE
                 , ITEM_ID
                 , FROM_SITE
                 , BOD_ID
                 , MEASURE
                 , YYYYMMDD
                 , TO_SITE
                 , QTY
                 , ORIGIN_FROM_DIVISION_ID
                 , ORIGIN_TO_DIVISION_ID
                 , ELECTRODE_TYPE
                 , BOD_TYPE
                 , INCOTERMS
                 )
            SELECT IA.BIZ_TYPE
                 , IA.PROJECT_CODE
                 , IA.ITEM_ID
                 , IA.FROM_SITE
                 , IA.BOD_ID
                 , IA.MEASURE
                  --,YYYYMMDD
                 , A.BASIS_YYYYMMDD
                 , IA.TO_SITE
                 , SUM(CASE WHEN A.BASIS_YYYYMMDD = IA.YYYYMMDD THEN CAST(IA.QTY AS NUMBER(30,10)) ELSE 0 END) AS OUT_QTY_INT
                  --,QTY
                 , IA.ORIGIN_FROM_DIVISION_ID
                 , IA.ORIGIN_TO_DIVISION_ID
                 , IA.ELECTRODE_TYPE
                 , IA.BOD_TYPE
                 , IA.INCOTERMS
              FROM (SELECT SC.OPERATION_GROUP       AS BIZ_TYPE
                         , SB.ATTRIBUTE9            AS PROJECT_CODE
                         , SA.ITEM_ID
                         , SA.FROM_SITE_ID          AS FROM_SITE
                         , SB.ATTRIBUTE7            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'        AS MEASURE
                         , SA.DEPARTURE_DATE        AS YYYYMMDD
                         , SA.TO_SITE_ID            AS TO_SITE
                         , TO_NUMBER(SA.QTY_INT)    AS QTY -- 2026.04.16 Minyong Lee : UNION ALL로 인한 의도치 않은 타입캐스팅 및 소수 데이터 유실 에러 수정
                         , V_DIVISION_ID            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SB.ATTRIBUTE8            AS BOD_TYPE
                         , SB.ATTRIBUTE6            AS INCOTERMS
                      FROM SCP_OPT_ENG_OUT_ORDER_SHIPPING_INT_SN SA
                         , SCP_OPT_ENG_BOD_SN SB
                         , SCP_MST_FINAL_ITEM SC
                     WHERE SA.BOD_ID   = SB.BOD_ID
                       AND SC.ITEM_ID  = SA.ITEM_ID
                       AND (SA.GRADE LIKE 'PACKBIZ%' OR SA.GRADE LIKE 'LINKBIZ%') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SB.ATTRIBUTE8 = 'SALES'  --SALES는 FG에 넣고 PLANT만 SEMI에 넣으면 됨.
                       AND SB.ATTRIBUTE7 <> 'DUMMY'
                       AND SB.PLAN_ID     = V_PLAN_ID
                       AND SC.DIVISION_ID = V_DIVISION_ID
                       AND SA.PLAN_ID     = V_PLAN_ID
                ------------------------------------------------------------------------
                -- Get Scheduled Move data
                -- INT 테이블 결과에 Scheduled Move 데이터는 나오지 않음
                ------------------------------------------------------------------------
                     UNION ALL
                    SELECT SE.OPERATION_GROUP
                         , SD.ATTRIBUTE10                           AS PROJECT_CODE
                         , SD.ATTRIBUTE2                            AS ITEM_ID
                         , SD.ATTRIBUTE1                            AS FROM_SITE
                         , SD.ATTRIBUTE7                            AS BOD_ID
                         , 'SHIP_PLAN_AMEND'                        AS MEASURE
                         , SD.DEPARTURE_DATE                        AS YYYYMMDD
                         , SD.ATTRIBUTE4                            AS TO_SITE
                         , CAST(SUM(SD.QUANTITY) AS NUMBER(38,10))  AS QTY
                         , V_DIVISION_ID                            AS ORIGIN_FROM_DIVISION_ID -- 전극 할 땐 찾아서 넣어야 함
                         , V_DIVISION_ID                            AS ORIGIN_TO_DIVISION_ID   -- 전극 할 땐 찾아서 넣어야 함
                         , NULL                                     AS ELECTRODE_TYPE -- 2025.11.05 Minyong Lee : ELECTRODE_TYPE NULL -> ''
                         , SD.ATTRIBUTE8                            AS BOD_TYPE
                         , SD.ATTRIBUTE9                            AS INCOTERMS
                      FROM SCP_OPT_ENG_SCHEDULED_MOVE_SN SD
                         , SCP_MST_FINAL_ITEM SE
                     WHERE SE.ITEM_ID     = SD.ATTRIBUTE2
                       AND SD.ATTRIBUTE5 IN ('PACKBIZ', 'LINKBIZ') -- 2026.09.04 Minyong Lee : [E20260828-002050] ESS Link 최적화 엔진 결과 SCM 시스템에 IF 개발요청드립니다.
                       AND SD.ATTRIBUTE6 ='IN'
                       AND SD.ATTRIBUTE8 ='SALES'
                       AND SE.DIVISION_ID = V_DIVISION_ID
                       AND SD.PLAN_ID     = V_PLAN_ID
                     GROUP BY SE.OPERATION_GROUP
                            , SD.ATTRIBUTE10
                            , SD.ATTRIBUTE2
                            , SD.ATTRIBUTE1
                            , SD.ATTRIBUTE7
                            , SD.DEPARTURE_DATE
                            , SD.ATTRIBUTE4
                            , SD.ATTRIBUTE8
                            , SD.ATTRIBUTE9 -- SCHEDULED MOVE 테이블을 만들 때 PROJECT CODE가 없으면 찾아주는데, 원본에 있는거 하나, 없는거 하나 생길 수 있음
                   ) IA
                 , SCM_SYS_CALENDAR_M A
             WHERE A.BASIS_YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD  -- Plan From - To 구간 전체.
             GROUP BY IA.BIZ_TYPE
                    , IA.PROJECT_CODE
                    , IA.ITEM_ID
                    , IA.FROM_SITE
                    , IA.BOD_ID
                    , IA.MEASURE
                    , IA.TO_SITE
                    , IA.ORIGIN_FROM_DIVISION_ID
                    , IA.ORIGIN_TO_DIVISION_ID
                    , IA.ELECTRODE_TYPE
                    , IA.BOD_TYPE
                    , IA.INCOTERMS
                    , A.BASIS_YYYYMMDD;
        END IF;

        ------------------------------------------------------------------------
        -- 0. 입력할 데이터가 있으면 진행
        ------------------------------------------------------------------------

        ------------------------------------------------------------------------
        -- 1. Initialization Qty
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET A.QTY              = 0
             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
          --, ATTRIBUTE9       = 'U'
          --, ATTRIBUTE10      = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/INIT'
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.FROM_SITE = SA.SCM_SITE_ID
                          AND A.ITEM_ID   = SA.ITEM_ID
                      )
           AND A.MEASURE             IN ('SHIP_PLAN_AMEND')
           AND A.QTY                 != 0
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD;

        ------------------------------------------------------------------------
        -- 2. Get SCP_ANL_SHIPMENT_PLAN_FG DATA
        -- 프로젝트 코드가 1개인 대상만 추출 -> 속도 개선을 위한 TEMP 테이블 사용
        -- '-'는 제외하고 COUNTING
        ------------------------------------------------------------------------
        INSERT INTO GT_TAES_OS_RESULT_FG_SMMR
             ( ITEM_ID
             , BOD_ID
             , PROJECT_CODE
             )
        SELECT IA.ITEM_ID
             , IA.BOD_ID
             , A.PROJECT_CODE
          FROM (SELECT XA.DIVISION_ID
                     , XA.PLAN_START_YYYYMMDD
                     , XA.PLAN_TYPE
                     , XA.SEQ
                     , XA.BIZ_TYPE
                     , XA.ITEM_ID
                     , XA.MEASURE
                     , XA.BOD_ID
                  FROM (SELECT SA.DIVISION_ID
                             , SA.PLAN_START_YYYYMMDD
                             , SA.PLAN_TYPE
                             , SA.SEQ
                             , SA.BIZ_TYPE
                             , SA.PROJECT_CODE
                             , SA.ITEM_ID
                             , SA.MEASURE
                             , SA.BOD_ID
                          FROM SCP_ANL_SHIPMENT_PLAN_FG SA
                             , (SELECT SCM_SITE_ID
                                     , ITEM_ID
                                  FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                 WHERE PLAN_ID = V_PLAN_ID
                                 GROUP BY SCM_SITE_ID
                                        , ITEM_ID
                               ) SB
                         WHERE SA.FROM_SITE           = SB.SCM_SITE_ID
                           AND SA.ITEM_ID             = SB.ITEM_ID
                           AND SA.MEASURE             IN ('SHIP_PLAN_AMEND')
                           AND SA.PROJECT_CODE        != '-'
                           AND SA.DIVISION_ID         = V_DIVISION_ID
                           AND SA.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
                           AND SA.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
                           AND SA.PLAN_TYPE           = V_SCP_PLAN_TYPE
                           AND SA.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
                           AND SA.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
                         GROUP BY SA.DIVISION_ID
                                , SA.PLAN_START_YYYYMMDD
                                , SA.PLAN_TYPE
                                , SA.SEQ
                                , SA.BIZ_TYPE
                                , SA.PROJECT_CODE
                                , SA.ITEM_ID
                                , SA.MEASURE
                                , SA.BOD_ID
                       ) XA
                 GROUP BY XA.DIVISION_ID
                        , XA.PLAN_START_YYYYMMDD
                        , XA.PLAN_TYPE
                        , XA.SEQ
                        , XA.BIZ_TYPE
                        , XA.ITEM_ID
                        , XA.MEASURE
                        , XA.BOD_ID
                HAVING COUNT(XA.DIVISION_ID) = 1
               ) IA
             , SCP_ANL_SHIPMENT_PLAN_FG A
         WHERE IA.ITEM_ID             = A.ITEM_ID
           AND IA.BOD_ID              = A.BOD_ID
           AND IA.DIVISION_ID         = A.DIVISION_ID
           AND IA.MEASURE             = A.MEASURE
           AND IA.PLAN_START_YYYYMMDD = A.PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 (안쪽 집합이 같은 계획 시작일) */
           AND IA.PLAN_TYPE           = A.PLAN_TYPE
           AND IA.SEQ                 = A.SEQ
           AND A.PROJECT_CODE         != '-'
           AND A.YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
         GROUP BY IA.ITEM_ID
