                       AND A.PROJECT_CODE = XA.PROJECT_CODE
                       AND A.ITEM_ID      = XA.ITEM_ID
                       AND A.TO_SITE      = XA.TO_SITE
                       AND A.INCOTERMS    = XA.INCOTERMS
