        ------------------------------------------------------------------------
        DBMS_OUTPUT.PUT_LINE('SCP_ANL_SHIPMENT_PLAN_FG_____3');
        /* AS-IS MERGE → ① UPDATE (WHEN MATCHED) ② INSERT (WHEN NOT MATCHED) */
        UPDATE SCP_ANL_SHIPMENT_PLAN_FG A
           SET ( A.QTY
               , A.LAST_UPDATE_DATE
               , A.LAST_UPDATED_BY
               ) = (SELECT XA.QTY
                         , V_NOW_DATE
                         , V_UPDATE_NAME
                      FROM (SELECT XB.OPERATION_GROUP
                                 , XB.PROJECT_CODE
                                 , XB.ITEM_ID
                                 , XB.TO_SITE
                                 , XB.INCOTERMS
                                 , XB.FROM_SITE
