           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;
        ------------------------------------------------------------------------
        -- Update SCP_ANL_SHIPMENT_PLAN_FIX QTY
        ------------------------------------------------------------------------
        UPDATE SCP_ANL_SHIPMENT_PLAN_FIX A
           SET ( A.QTY
               , A.LAST_UPDATED_BY
               , A.LAST_UPDATE_DATE
               ) = (SELECT B.QTY
                         , V_UPDATE_NAME
                         , V_NOW_DATE
                      FROM GT_TAES_OS_RESULT_FG B
                     WHERE A.BIZ_TYPE     = B.OPERATION_GROUP
                       AND A.ITEM_ID      = B.ITEM_ID
                       AND A.TO_SITE      = B.TO_SITE
                       AND A.FROM_SITE    = B.FROM_SITE
                       AND A.BOD_ID       = B.BOD_ID
                       AND A.YYYYMMDD     = B.YYYYMMDD
                       AND A.PROJECT_CODE = B.PROJECT_CODE
                       AND ROWNUM = 1
                   )
          --, SCP_ANL_SHIPMENT_PLAN_FIX.ATTRIBUTE10       = CONVERT(NVARCHAR(30),@NOW_DATE,120) + '/OPT_ENG/UPDATE'
         WHERE EXISTS (SELECT 1
                         FROM GT_TAES_OS_RESULT_FG C
                        WHERE A.BIZ_TYPE     = C.OPERATION_GROUP
                          AND A.ITEM_ID      = C.ITEM_ID
                          AND A.TO_SITE      = C.TO_SITE
                          AND A.FROM_SITE    = C.FROM_SITE
                          AND A.BOD_ID       = C.BOD_ID
                          AND A.YYYYMMDD     = C.YYYYMMDD
                          AND A.PROJECT_CODE = C.PROJECT_CODE
                      )
           AND A.DIVISION_ID = V_DIVISION_ID;
        ------------------------------------------------------------------------
        -- INSERT FIX HISTORY
        ------------------------------------------------------------------------
        INSERT INTO SCP_ANL_SHIPMENT_PLAN_FIX_H
             ( HISTORY_SEQ
             , FIX_ID
             , DIVISION_ID
             , BIZ_TYPE
             , ITEM_ID
             , TO_SITE
             , FROM_SITE
             , BOD_ID
             , YYYYMMDD
             , PROJECT_CODE
             , INCOTERMS
             , QTY
             , FIX_REASON
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , HISTORY_CREATION_DATE
             )
        SELECT SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H.NEXTVAL -- 원본에서 SCP_ANL_SHIPMENT_PLAN_FIX_H의 SEQ를 SEQ1_SCP_ANL_PRODUCTION_PLAN_FIX_H로 생성 중.
             , FIX_ID
             , DIVISION_ID
             , BIZ_TYPE
             , ITEM_ID
             , TO_SITE
             , FROM_SITE
             , BOD_ID
             , YYYYMMDD
             , PROJECT_CODE
             , INCOTERMS
             , QTY
             , FIX_REASON
             , ORIGIN_FROM_DIVISION_ID
             , ORIGIN_TO_DIVISION_ID
             , ELECTRODE_TYPE
             , CREATED_BY
             , CREATION_DATE
             , LAST_UPDATED_BY
             , LAST_UPDATE_DATE
             , ATTRIBUTE1
             , ATTRIBUTE2
             , ATTRIBUTE3
             , ATTRIBUTE4
             , ATTRIBUTE5
             , ATTRIBUTE6
             , ATTRIBUTE7
             , ATTRIBUTE8
             , ATTRIBUTE9
             , ATTRIBUTE10
             , V_NOW_DATE
          FROM SCP_ANL_SHIPMENT_PLAN_FIX
         WHERE DIVISION_ID         = V_DIVISION_ID
           AND YYYYMMDD BETWEEN V_PLAN_START_YYYYMMDD AND V_PLAN_END_YYYYMMDD
           AND LAST_UPDATED_BY     = V_UPDATE_NAME
           AND LAST_UPDATE_DATE    = V_NOW_DATE;
    ------------------------------------------------------------------------
    -- UPDATE SCP_XLS_PSI_GLOBAL_ESS
    ------------------------------------------------------------------------
        ------------------------------------------------------------------------
        -- 52주 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TAES_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , '-'                             AS BOD_ID
             , '/'                             AS PROJECT_CODE
             , CASE WHEN A.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN A.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                             AS MEASURE
             , SUM(NVL(A.QTY, 0))              AS QTY_SUM
             , P_PLAN_START_YYYYMMDD           AS CREATE_FROM_YYYYMMDD
          FROM (SELECT CASE WHEN CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END IS NULL THEN NULL   /* AS-IS 'WQTY' + NULL = NULL */
                            ELSE 'WQTY' || LPAD(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END, 2, '0')
                       END AS WEEK_NUM
                     , 'QTY' || LPAD(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN A
         WHERE IA.BASIS_YYYYMMDD     = A.YYYYMMDD(+)
           AND A.MEASURE             = 'PROD_PLAN_AMEND'
           AND A.QTY                 != 0
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
         GROUP BY IA.TRG_DATE
                , A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IA.WEEK_NUM                     AS TRG_DATE
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , '-'                             AS BOD_ID
             , '/'                             AS PROJECT_CODE
             , CASE WHEN A.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN A.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                             AS MEASURE
             , SUM(A.QTY)                      AS QTY_SUM
             , P_PLAN_START_YYYYMMDD           AS CREATE_FROM_YYYYMMDD
          FROM (SELECT CASE WHEN CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END IS NULL THEN NULL   /* AS-IS 'WQTY' + NULL = NULL */
                            ELSE 'WQTY' || LPAD(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END, 2, '0')
                       END AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN A
         WHERE IA.BASIS_YYYYMMDD     = A.YYYYMMDD(+)
           AND A.MEASURE             = 'PROD_PLAN_AMEND'
           AND A.QTY                 != 0
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
         GROUP BY IA.WEEK_NUM
                , A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
        
