        ------------------------------------------------------------------------
        -- Get Daily CHAR data
        ------------------------------------------------------------------------
         UNION ALL
        SELECT IA.TRG_DATE
             , IB.DIVISION_ID
             , IB.PLAN_START_YYYYMMDD
             , IB.PLAN_TYPE
             , IB.SEQ
             , IB.OPERATION_GROUP
             , IB.FROM_SITE
             , IC.ITEM_ID_ASSY                 AS ITEM_ID
             , '-'                             AS LINE_ID
             , '-'                             AS BOD_ID
             , '/'                             AS PROJECT_CODE
             , 'CELL_CHAR_PLAN'                AS MEASURE
             , SUM(CAST(IB.QTY AS NUMBER(20,10))) AS QTY_SUM
             , P_PLAN_START_YYYYMMDD           AS CREATE_FROM_YYYYMMDD
          FROM (SELECT CASE WHEN CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END IS NULL THEN NULL   /* AS-IS 'WQTY' + NULL = NULL */
