                            ELSE 'WQTY' || LPAD(CASE WHEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_WEEKS_IN_YEAR - V_MIN_WEEK END, 2, '0')
                       END AS WEEK_NUM
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN P_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , (SELECT V_DIVISION_ID                 AS DIVISION_ID
                     , P_PLAN_START_YYYYMMDD         AS PLAN_START_YYYYMMDD
                     , V_SCP_PLAN_TYPE               AS PLAN_TYPE
                     , TO_NUMBER(V_SCP_PLAN_SEQ)     AS SEQ
                     , SB.OPERATION_GROUP
                     , SA.SITE_ID                    AS FROM_SITE
                     , SA.ITEM_ID
                     , SA.GRADE
                     , SA.START_DATE                 AS YYYYMMDD
                     , SA.OUT_QTY                    AS QTY
                  FROM SCP_OPT_ENG_OUT_ORDER_PRODUCTION_SN SA
                     , SCP_MST_FINAL_ITEM SB
                 WHERE SB.ITEM_ID     = SA.ITEM_ID
                   AND SA.GRADE IN ( 'CHAR')
                   AND SB.DIVISION_ID = V_DIVISION_ID
                   AND SA.PLAN_ID     = V_PLAN_ID
               ) IB
             , (SELECT DISTINCT ITEM_ID_PROD
                     , ITEM_ID_ASSY
                  FROM SCP_MST_CELL_PROD_ASSY_MAP
                 WHERE CELL_TYPE   = 'CA1'
                   AND DIVISION_ID = V_DIVISION_ID
               ) IC
         WHERE IA.BASIS_YYYYMMDD = IB.YYYYMMDD(+)
           AND IB.ITEM_ID        = IC.ITEM_ID_PROD
           AND CAST(IB.QTY AS NUMBER(20,10)) != 0
         GROUP BY IA.WEEK_NUM
                , IB.DIVISION_ID
                , IB.PLAN_START_YYYYMMDD
                , IB.PLAN_TYPE
                , IB.SEQ
                , IB.OPERATION_GROUP
                , IB.FROM_SITE
                , IC.ITEM_ID_ASSY;
        ------------------------------------------------------------------------
        -- 52주 이후 구간 : 52주 구간과 52주 이후 구간을 나눠서 넣어야 함
        -- Get Daily SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
        INSERT INTO GT_TAES_XLS_PV_READY
             ( TRG_DATE
             , DIVISION_ID
             , PLAN_START_YYYYMMDD
             , PLAN_TYPE
             , SEQ
             , OPERATION_GROUP
             , FROM_SITE
             , ITEM_ID
             , LINE_ID
             , BOD_ID
             , PROJECT_CODE
             , MEASURE
             , QTY_SUM
             , CREATE_FROM_YYYYMMDD
             )
        SELECT IA.TRG_DATE
             , A.DIVISION_ID
             , A.PLAN_START_YYYYMMDD
             , A.PLAN_TYPE
             , A.SEQ
             , A.OPERATION_GROUP
             , A.SCM_SITE_ID
             , A.ITEM_ID
             , A.LINE_ID
             , '-'                             AS BOD_ID
             , '/'                             AS PROJECT_CODE
             , CASE WHEN A.OPERATION_GROUP = 'A' THEN 'CELL_PROD'
                    WHEN A.OPERATION_GROUP = 'P' THEN 'PACK_PROD'
                    ELSE NULL
               END                             AS MEASURE
             , SUM(NVL(A.QTY, 0))              AS QTY_SUM
             , V_2ND_PLAN_START_YYYYMMDD       AS CREATE_FROM_YYYYMMDD
          FROM (SELECT CASE WHEN CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END IS NULL THEN NULL   /* AS-IS 'WQTY' + NULL = NULL */
                            ELSE 'WQTY' || LPAD(CASE WHEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK > 0 THEN TO_NUMBER(ISO_WEEK) - V_2ND_MIN_WEEK ELSE TO_NUMBER(ISO_WEEK) + V_2ND_WEEKS_IN_YEAR - V_2ND_MIN_WEEK END, 2, '0')
                       END AS WEEK_NUM
                     , 'QTY' || LPAD(ROW_NUMBER() OVER(ORDER BY BASIS_YYYYMMDD), 3, '0') AS TRG_DATE
                     , BASIS_YYYYMMDD
                  FROM SCM_SYS_CALENDAR_M
                 WHERE BASIS_YYYYMMDD BETWEEN V_2ND_PLAN_START_YYYYMMDD AND TO_CHAR(TO_DATE(V_2ND_PLAN_START_YYYYMMDD, 'YYYYMMDD') + 363, 'YYYYMMDD')
               ) IA
             , SCP_ANL_PRODUCTION_PLAN A
         WHERE IA.BASIS_YYYYMMDD     = A.YYYYMMDD(+)
           AND A.MEASURE             = 'PROD_PLAN_AMEND'
           AND A.QTY                 != 0
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.PLAN_START_YYYYMMDD_DATE = TO_DATE(P_PLAN_START_YYYYMMDD, 'YYYYMMDD')   /* 파티션 키 */
           AND A.LAST_UPDATED_BY     = V_UPDATE_NAME
        --AND     AP.ATTRIBUTE9          = 'U'
         GROUP BY IA.TRG_DATE
                , A.DIVISION_ID
                , A.PLAN_START_YYYYMMDD
                , A.PLAN_TYPE
                , A.SEQ
                , A.OPERATION_GROUP
                , A.SCM_SITE_ID
                , A.ITEM_ID
                , A.LINE_ID
        ------------------------------------------------------------------------
        -- Get Weekly SCP_ANL_PRODUCTION_PLAN data
        ------------------------------------------------------------------------
         UNION ALL
