             , A.LAST_UPDATED_BY  = V_UPDATE_NAME
             , A.LAST_UPDATE_DATE = V_NOW_DATE
         WHERE EXISTS (SELECT 1
                         FROM (SELECT SCM_SITE_ID
                                    , ITEM_ID
                                 FROM SCP_OPT_ENG_MODEL_LIST_N_SN
                                WHERE PLAN_ID = V_PLAN_ID
                                GROUP BY SCM_SITE_ID
                                       , ITEM_ID
                              ) SA
                        WHERE A.FROM_SITE = SA.SCM_SITE_ID
                          AND A.ITEM_ID   = SA.ITEM_ID
                      )
           /* AS-IS 그대로 : @CFY_TEMP 의 컬럼명은 CREATE_FROM_YYYMMDD(Y 3개)라 서브쿼리의 CREATE_FROM_YYYYMMDD 는
              바깥 SCP_XLS_PSI_GLOBAL_ESS 컬럼으로 해석됨 → 「GT 에 1행 이상 있고 A.CREATE_FROM_YYYYMMDD 가 NULL 이 아님」과 같은 조건 */
           AND A.CREATE_FROM_YYYYMMDD IN (SELECT A.CREATE_FROM_YYYYMMDD
                                            FROM GT_TAES_CFY_TEMP
                                         )
           AND A.MEASURE IN (SELECT MEASURE
                               FROM GT_TAES_MS_TEMP
                            )
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD
           AND A.DIVISION_ID         = V_DIVISION_ID
           AND A.PLAN_TYPE           = V_SCP_PLAN_TYPE
           AND A.SEQ                 = TO_NUMBER(V_SCP_PLAN_SEQ)
           AND A.PLAN_START_YYYYMMDD = P_PLAN_START_YYYYMMDD;

