                 ,SB.PLAN_START_YYYYMMDD
                 ,SB.PLAN_TYPE
                 ,SB.SEQ
                 ,SB.OPERATION_GROUP
                 ,SB.FROM_SITE
                 ,SD.ITEM_ID_ASSY
