                    , Y1.PLAN_TYPE
                    , Y1.SEQ
                    , Y1.OPERATION_GROUP
                    , Y1.OPERATION_GROUP_NAME
                    , Y1.FROM_SITE
                    , Y1.ATTRIBUTE9 AS OPERATION_ID
                    , Y1.CELL_ITEM_ID
                    , Y1.ITEM_ID
