            , WQTY63/7, WQTY64/7, WQTY65/7, WQTY66/7, WQTY67/7, WQTY68/7, WQTY69/7, WQTY70/7, WQTY71/7, WQTY72/7
            , WQTY73/7, WQTY74/7, WQTY75/7, WQTY76/7, WQTY77/7, WQTY78/7, WQTY79/7, WQTY80/7, WQTY81/7, WQTY82/7

            , WQTY83/7, WQTY84/7, WQTY85/7, WQTY86/7, WQTY87/7, WQTY88/7, WQTY89/7, WQTY90/7, WQTY91/7, WQTY92/7   /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
            , WQTY93/7, WQTY94/7, WQTY95/7, WQTY96/7, WQTY97/7, WQTY98/7, WQTY99/7, WQTY100/7,WQTY101/7,WQTY102/7
