                  AND Y1.PROD_LINE    = Y2.PROD_LINE
                  AND Y1.PROJECT_CODE = Y2.PROJECT_CODE
                  AND Y1.INCOTERMS    = Y2.INCOTERMS
              ) X
        WHERE 0 = 0
          AND X.MEASURE IN ('PACK_WORKING_TIME','CELL_WORKING_TIME')
       GROUP BY X.DIVISION_ID
            , X.PLAN_START_YYYYMMDD
            , X.PLAN_TYPE
            , X.SEQ
            , X.OPERATION_GROUP
            , X.OPERATION_GROUP_NAME
            , X.FROM_SITE
            , X.ATTRIBUTE9
            , X.CELL_ITEM_ID
            , X.PROD_LINE
            , X.FROM_BOH_QTY
            , X.YIELD
            , X.LT_DAY
            , X.CELL_QTY_PACK
