            , NULL AS ATTRIBUTE6   /* DC LINK 적용 */
         FROM (SELECT Y1.DIVISION_ID
                    , Y1.PLAN_START_YYYYMMDD
                    , Y1.PLAN_TYPE
                    , Y1.SEQ
                    , Y1.OPERATION_GROUP
