			,MAX(WQTY73), MAX(WQTY74), MAX(WQTY75), MAX(WQTY76), MAX(WQTY77), MAX(WQTY78), MAX(WQTY79), MAX(WQTY80), MAX(WQTY81), MAX(WQTY82)
