            ,X.ITEM_ID
            ,X.NICK_NAME
            ,'Total' AS PROD_LINE
             ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
