        INNER JOIN SCP_MST_TACT_TIME_OSP Y  /* ESS 외주 Line별 생산 Target 관련 OSP_YN로직 수정 */
                ON X.DIVISION_ID = Y.DIVISION_ID
               AND X.ITEM_ID    = Y.ITEM_ID
               AND X.FROM_SITE  = Y.PLANT_SITE_ID
               AND X.PROD_LINE  = Y.LINE_ID
        INNER JOIN SCM_MST_SITE S
                ON S.DIVISION_ID              = X.DIVISION_ID
               AND S.SCM_SITE_ID              = X.FROM_SITE
               AND S.OSP_YN                   = 'Y'
               AND NVL(S.ATTRIBUTE1, 'N')  = 'Y'
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_PROD_TOTAL')
          GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,X.MEASURE
            ,X.MEASURE_LABEL
			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
UNION
        /* PACK_PROD_LOAD_TOTAL */
         SELECT  DISTINCT X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.FROM_SITE AND ROWNUM = 1) , '/') AS FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            /* ,X.CELL_ITEM_ID */
            ,(CASE WHEN X.MEASURE IN ('PACK_PROD_LOAD_TOTAL')  THEN '-' ELSE CELL_ITEM_ID END) AS CELL_ITEM_ID
            ,'-' AS ITEM_ID
            ,'-' AS NICK_NAME
            ,'Total' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,0 AS CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,X.MEASURE
            ,X.MEASURE_LABEL
            ,MAX(X.SORT_ORDER_NO)
            ,8888888 AS XLS_KEY1
            ,SUM(WQTY01),SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10)
            ,SUM(WQTY11),SUM(WQTY12),SUM(WQTY13),SUM(WQTY14),SUM(WQTY15),SUM(WQTY16),SUM(WQTY17),SUM(WQTY18),SUM(WQTY19),SUM(WQTY20)
            ,SUM(WQTY21),SUM(WQTY22),SUM(WQTY23),SUM(WQTY24),SUM(WQTY25),SUM(WQTY26),SUM(WQTY27),SUM(WQTY28),SUM(WQTY29),SUM(WQTY30)
            ,SUM(WQTY31),SUM(WQTY32),SUM(WQTY33),SUM(WQTY34),SUM(WQTY35),SUM(WQTY36),SUM(WQTY37),SUM(WQTY38),SUM(WQTY39),SUM(WQTY40)
            ,SUM(WQTY41),SUM(WQTY42),SUM(WQTY43),SUM(WQTY44),SUM(WQTY45),SUM(WQTY46),SUM(WQTY47),SUM(WQTY48),SUM(WQTY49),SUM(WQTY50)
            ,SUM(WQTY51),SUM(WQTY52)

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,SUM(WQTY53), SUM(WQTY54), SUM(WQTY55), SUM(WQTY56), SUM(WQTY57), SUM(WQTY58), SUM(WQTY59), SUM(WQTY60), SUM(WQTY61), SUM(WQTY62)
			,SUM(WQTY63), SUM(WQTY64), SUM(WQTY65), SUM(WQTY66), SUM(WQTY67), SUM(WQTY68), SUM(WQTY69), SUM(WQTY70), SUM(WQTY71), SUM(WQTY72)
			,SUM(WQTY73), SUM(WQTY74), SUM(WQTY75), SUM(WQTY76), SUM(WQTY77), SUM(WQTY78), SUM(WQTY79), SUM(WQTY80), SUM(WQTY81), SUM(WQTY82)
			,SUM(WQTY83), SUM(WQTY84), SUM(WQTY85), SUM(WQTY86), SUM(WQTY87), SUM(WQTY88), SUM(WQTY89), SUM(WQTY90), SUM(WQTY91), SUM(WQTY92)  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,SUM(WQTY93), SUM(WQTY94), SUM(WQTY95), SUM(WQTY96), SUM(WQTY97), SUM(WQTY98), SUM(WQTY99), SUM(WQTY100),SUM(WQTY101),SUM(WQTY102)
			,SUM(WQTY103),SUM(WQTY104)

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,NULL AS ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
        INNER JOIN SCP_MST_TACT_TIME_OSP Y  /* ESS 외주 Line별 생산 Target 관련 OSP_YN로직 수정 */
                ON X.DIVISION_ID = Y.DIVISION_ID
               AND X.ITEM_ID    = Y.ITEM_ID
               AND X.FROM_SITE  = Y.PLANT_SITE_ID
               AND X.PROD_LINE  = Y.LINE_ID
        INNER JOIN SCM_MST_SITE S
                ON S.DIVISION_ID              = X.DIVISION_ID
               AND S.SCM_SITE_ID              = X.FROM_SITE
               AND S.OSP_YN                   = 'Y'
               AND NVL(S.ATTRIBUTE1, 'N')  = 'Y'
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_PROD_LOAD_TOTAL')
          GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,X.MEASURE
            ,X.MEASURE_LABEL
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
UNION
       /* 'PACK_BOH','PACK_EOH','PACK_DIO' */
         SELECT  X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,X.FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
            ,'Total2' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,X.MEASURE
			,(CASE WHEN SUBSTR(X.ATTRIBUTE6, 1, 1) = 1 AND X.MEASURE = 'PACK_BOH' THEN 'DC Link BOH'
			       WHEN SUBSTR(X.ATTRIBUTE6, 1, 1) = 1 AND X.MEASURE = 'PACK_EOH' THEN 'DC Link Inventory'
			       ELSE X.MEASURE_LABEL END) AS MEASURE_LABEL  /* X.MEASURE_LABEL -- 2022.02.11 DC LINK 적용 */
            ,MAX(X.SORT_ORDER_NO)
            ,MAX(XLS_KEY1)
            ,SUM(WQTY01),SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10)
            ,SUM(WQTY11),SUM(WQTY12),SUM(WQTY13),SUM(WQTY14),SUM(WQTY15),SUM(WQTY16),SUM(WQTY17),SUM(WQTY18),SUM(WQTY19),SUM(WQTY20)
            ,SUM(WQTY21),SUM(WQTY22),SUM(WQTY23),SUM(WQTY24),SUM(WQTY25),SUM(WQTY26),SUM(WQTY27),SUM(WQTY28),SUM(WQTY29),SUM(WQTY30)
            ,SUM(WQTY31),SUM(WQTY32),SUM(WQTY33),SUM(WQTY34),SUM(WQTY35),SUM(WQTY36),SUM(WQTY37),SUM(WQTY38),SUM(WQTY39),SUM(WQTY40)
            ,SUM(WQTY41),SUM(WQTY42),SUM(WQTY43),SUM(WQTY44),SUM(WQTY45),SUM(WQTY46),SUM(WQTY47),SUM(WQTY48),SUM(WQTY49),SUM(WQTY50)
            ,SUM(WQTY51),SUM(WQTY52)

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,SUM(WQTY53), SUM(WQTY54), SUM(WQTY55), SUM(WQTY56), SUM(WQTY57), SUM(WQTY58), SUM(WQTY59), SUM(WQTY60), SUM(WQTY61), SUM(WQTY62)
			,SUM(WQTY63), SUM(WQTY64), SUM(WQTY65), SUM(WQTY66), SUM(WQTY67), SUM(WQTY68), SUM(WQTY69), SUM(WQTY70), SUM(WQTY71), SUM(WQTY72)
			,SUM(WQTY73), SUM(WQTY74), SUM(WQTY75), SUM(WQTY76), SUM(WQTY77), SUM(WQTY78), SUM(WQTY79), SUM(WQTY80), SUM(WQTY81), SUM(WQTY82)
			,SUM(WQTY83), SUM(WQTY84), SUM(WQTY85), SUM(WQTY86), SUM(WQTY87), SUM(WQTY88), SUM(WQTY89), SUM(WQTY90), SUM(WQTY91), SUM(WQTY92)  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,SUM(WQTY93), SUM(WQTY94), SUM(WQTY95), SUM(WQTY96), SUM(WQTY97), SUM(WQTY98), SUM(WQTY99), SUM(WQTY100),SUM(WQTY101),SUM(WQTY102)
			,SUM(WQTY103),SUM(WQTY104)

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.FROM_SITE_DESCRIPTION
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
					,Y1.ITEM_ID || '|' || Y1.FROM_SITE AS ITEM_FROM
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
        INNER JOIN SCM_MST_SITE S
                ON S.DIVISION_ID              = X.DIVISION_ID
               AND S.SCM_SITE_ID              = X.FROM_SITE
               AND S.OSP_YN                   = 'Y'
               AND NVL(S.ATTRIBUTE1, 'N')  = 'Y'
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_BOH','PACK_EOH','PACK_DIO')
		 /* DC Link 사용 pack 모듈 제외 - 2022.04.11 */
		 AND NOT X.ITEM_FROM IN (SELECT DISTINCT ITEM_ID || '|' || TO_SITE AS ITEM_FROM
								   FROM SCP_XLS_PSI_GLOBAL_ESS A
								  WHERE CREATE_FROM_YYYYMMDD = (SELECT PLAN_START_YYYYMMDD FROM PLAN_NAME)
									AND MEASURE = 'SEMI_SHIP_PLAN'
									AND ATTRIBUTE6 IS NOT NULL)
		 /* AND 'N' = (CASE WHEN X.ATTRIBUTE6 IS NULL OR LEFT(X.ATTRIBUTE6, 1) = '1' THEN 'N' */
			/* WHEN NOT X.FROM_SITE IN (SELECT DISTINCT FROM_SITE */
			/* FROM SCP_XLS_PSI_GLOBAL_ESS WITH (NOLOCK) */
			/* WHERE ITEM_ID = (CASE WHEN CHARINDEX('|', ATTRIBUTE6) > 0 THEN SUBSTRING(ATTRIBUTE6, 4, CHARINDEX('|', ATTRIBUTE6) - 4) */
			/* ELSE SUBSTRING(ATTRIBUTE6, 4, LEN(ATTRIBUTE6) - 3) END) */
			/* AND MEASURE IN ('PACK_BOH','PACK_EOH') */
			/* AND LEFT(ATTRIBUTE6, 1) = '1') THEN 'N' ELSE 'Y' END) */
          GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
			,X.FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,X.NICK_NAME
            ,X.MEASURE
            ,X.MEASURE_LABEL
			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
UNION
        /* DC link Pack 'PACK_BOH','PACK_EOH','PACK_DIO' */
         SELECT  X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
			,X.FROM_SITE_DESCRIPTION
            ,(SELECT ATTRIBUTE9 FROM SCP_XLS_PSI_GLOBAL_ESS A
				WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD
				AND ITEM_ID = SUBSTR(X.ATTRIBUTE6, 4, 12)
				AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_BOH' AND ROWNUM = 1) AS OPERATION_ID  /* X.ATTRIBUTE9 AS OPERATION_ID */
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
            ,'Total2' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,NULL AS TO_SITE  /* (SELECT TO_SITE FROM SCP_XLS_PSI_GLOBAL_ESS A WITH (NOLOCK) WHERE ITEM_ID = X.ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'SEMI_SHIP_PLAN') AS TO_SITE -- NULL AS TO_SITE */
            ,NULL AS TO_SITE_DESCRIPTION  /* (SELECT TO_SITE_DESCRIPTION FROM SCP_XLS_PSI_GLOBAL_ESS A WITH (NOLOCK) WHERE ITEM_ID = X.ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'SEMI_SHIP_PLAN') AS TO_SITE_DESCRIPTION -- NULL AS TO_SITE_DESCRIPTION */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,'DC_P_' || X.MEASURE AS MEASURE
            ,X.MEASURE_LABEL || '(to DC Link)' AS MEASURE_LABEL
            ,(CASE WHEN X.MEASURE = 'PACK_BOH' THEN 165 WHEN X.MEASURE = 'PACK_EOH' THEN 166 WHEN X.MEASURE = 'PACK_DIO' THEN 167 ELSE 168 END) AS SORT_ORDER_NO  /* MAX(X.SORT_ORDER_NO) */
            ,(SELECT MAX(XLS_KEY1) FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND ITEM_ID = X.ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_DIO') + 10 AS XLS_KEY1  /* MAX(XLS_KEY1) */
            ,SUM(WQTY01),SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10)
			/* ,(CASE WHEN LEFT(X.ATTRIBUTE6, 1) = 2 AND X.MEASURE = 'PACK_BOH' THEN 0.0 ELSE SUM(WQTY01) END) AS WQTY01 */
			/* ,SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10) */
            ,SUM(WQTY11),SUM(WQTY12),SUM(WQTY13),SUM(WQTY14),SUM(WQTY15),SUM(WQTY16),SUM(WQTY17),SUM(WQTY18),SUM(WQTY19),SUM(WQTY20)
            ,SUM(WQTY21),SUM(WQTY22),SUM(WQTY23),SUM(WQTY24),SUM(WQTY25),SUM(WQTY26),SUM(WQTY27),SUM(WQTY28),SUM(WQTY29),SUM(WQTY30)
            ,SUM(WQTY31),SUM(WQTY32),SUM(WQTY33),SUM(WQTY34),SUM(WQTY35),SUM(WQTY36),SUM(WQTY37),SUM(WQTY38),SUM(WQTY39),SUM(WQTY40)
            ,SUM(WQTY41),SUM(WQTY42),SUM(WQTY43),SUM(WQTY44),SUM(WQTY45),SUM(WQTY46),SUM(WQTY47),SUM(WQTY48),SUM(WQTY49),SUM(WQTY50)
            ,SUM(WQTY51),SUM(WQTY52)

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,SUM(WQTY53), SUM(WQTY54), SUM(WQTY55), SUM(WQTY56), SUM(WQTY57), SUM(WQTY58), SUM(WQTY59), SUM(WQTY60), SUM(WQTY61), SUM(WQTY62)
			,SUM(WQTY63), SUM(WQTY64), SUM(WQTY65), SUM(WQTY66), SUM(WQTY67), SUM(WQTY68), SUM(WQTY69), SUM(WQTY70), SUM(WQTY71), SUM(WQTY72)
			,SUM(WQTY73), SUM(WQTY74), SUM(WQTY75), SUM(WQTY76), SUM(WQTY77), SUM(WQTY78), SUM(WQTY79), SUM(WQTY80), SUM(WQTY81), SUM(WQTY82)
			,SUM(WQTY83), SUM(WQTY84), SUM(WQTY85), SUM(WQTY86), SUM(WQTY87), SUM(WQTY88), SUM(WQTY89), SUM(WQTY90), SUM(WQTY91), SUM(WQTY92)  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,SUM(WQTY93), SUM(WQTY94), SUM(WQTY95), SUM(WQTY96), SUM(WQTY97), SUM(WQTY98), SUM(WQTY99), SUM(WQTY100),SUM(WQTY101),SUM(WQTY102)
			,SUM(WQTY103),SUM(WQTY104)

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.FROM_SITE_DESCRIPTION
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
        INNER JOIN SCM_MST_SITE S
                ON S.DIVISION_ID              = X.DIVISION_ID
               AND S.SCM_SITE_ID              = X.FROM_SITE
               AND S.OSP_YN                   = 'Y'
               AND NVL(S.ATTRIBUTE1, 'N')  = 'Y'
			   AND SUBSTR(X.ATTRIBUTE6, 1, 1) = '2'
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_BOH','PACK_EOH','PACK_DIO')
		 /* E20240402-000726(ESS 사업부 시뮬레이터 팩재고 불일치 수정) */
		 AND X.FROM_SITE = CASE  WHEN X.MEASURE IN ( 'PACK_BOH', 'PACK_EOH') THEN 'KR012031-P'  ELSE X.FROM_SITE END
		 /* PACK_BOH (to DC Link) 에 첫주 BOH 를 표시할 경우 추가조건 */
		 /*-----------------------------------------------------------------------DELETE DHJ...08/04/2023
		 AND X.FROM_SITE IN (CASE WHEN X.MEASURE IN ('PACK_BOH','PACK_EOH') THEN (SELECT TO_SITE FROM SCP_XLS_PSI_GLOBAL_ESS A WITH (NOLOCK) WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND ITEM_ID = X.ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'SEMI_SHIP_PLAN')
		                         ELSE X.FROM_SITE END)
								 */

		 /* AND X.FROM_SITE IN (SELECT PLANT_SITE_ID */
			/* FROM SCM_MST_SITE_ITEM_PRIORITY P WITH (NOLOCK) */
			/* WHERE ITEM_ID = X.ITEM_ID) */
          GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
		   , X.FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,X.NICK_NAME
            ,X.MEASURE
            ,X.MEASURE_LABEL
			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
UNION
 /* DC link Production(Pack) - Pack 소요량 */
         SELECT  X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,(SELECT FROM_SITE FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND ITEM_ID = X.P_ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_BOH' AND ROWNUM = 1) AS FROM_SITE
            ,(SELECT FROM_SITE_DESCRIPTION FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND ITEM_ID = X.P_ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_BOH' AND ROWNUM = 1) AS FROM_SITE_DESCRIPTION
            ,(SELECT ATTRIBUTE9 FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND ITEM_ID = X.P_ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_BOH' AND ROWNUM = 1) AS OPERATION_ID
            ,X.CELL_ITEM_ID
            ,X.P_ITEM_ID AS ITEM_ID
            ,(SELECT NICK_NAME FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE CREATE_FROM_YYYYMMDD = X.PLAN_START_YYYYMMDD AND CELL_ITEM_ID = X.CELL_ITEM_ID AND ITEM_ID = X.P_ITEM_ID AND MEASURE = 'PACK_BOH' AND ROWNUM = 1) AS NICK_NAME
            ,'Total2' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
			,(SELECT DISTINCT A.CHILD_QTY AS MODULE_QTY_PACK
			   FROM SCM_MST_BOM_SN_V A
					INNER JOIN SCM_MST_ITEM_SN I
					ON  A.CHILD_DIVISION_ID = I.DIVISION_ID
					AND A.CHILD_ITEM_ID     = I.ITEM_ID
					AND A.CHILD_COMPANY_ID  = I.COMPANY_ID  /* A002 빈강 추가 따른 조건 추가 */
					AND A.CHILD_SITE_ID     = I.SITE_ID
					AND I.ACTIVE_FLAG       = 'Y'
			  WHERE 1=1
				AND A.DIVISION_ID = '82'
				AND A.CHILD_ITEM_ID IN (SELECT DISTINCT ITEM_ID FROM SCP_XLS_PSI_GLOBAL_ESS WHERE SUBSTR(ATTRIBUTE6, 1, 1) = '2')
				AND A.MODEL_ID      = X.P_ITEM_ID  /* SUBSTRING(X.ATTRIBUTE6, 4, LEN(X.ATTRIBUTE6)-3) */
			) AS CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,'DC_PACK_PROD_PACK'      AS MEASURE
            ,'Production(Pack)'       AS MEASURE_LABEL
            ,168 AS SORT_ORDER_NO  /* MAX(X.SORT_ORDER_NO) */
            ,(SELECT MAX(XLS_KEY1) FROM SCP_XLS_PSI_GLOBAL_ESS A WHERE ITEM_ID = X.ITEM_ID AND CELL_ITEM_ID = X.CELL_ITEM_ID AND MEASURE = 'PACK_DIO') + 10 AS XLS_KEY1  /* MAX(XLS_KEY1) */
            ,SUM(WQTY01),SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10)
            ,SUM(WQTY11),SUM(WQTY12),SUM(WQTY13),SUM(WQTY14),SUM(WQTY15),SUM(WQTY16),SUM(WQTY17),SUM(WQTY18),SUM(WQTY19),SUM(WQTY20)
            ,SUM(WQTY21),SUM(WQTY22),SUM(WQTY23),SUM(WQTY24),SUM(WQTY25),SUM(WQTY26),SUM(WQTY27),SUM(WQTY28),SUM(WQTY29),SUM(WQTY30)
            ,SUM(WQTY31),SUM(WQTY32),SUM(WQTY33),SUM(WQTY34),SUM(WQTY35),SUM(WQTY36),SUM(WQTY37),SUM(WQTY38),SUM(WQTY39),SUM(WQTY40)
            ,SUM(WQTY41),SUM(WQTY42),SUM(WQTY43),SUM(WQTY44),SUM(WQTY45),SUM(WQTY46),SUM(WQTY47),SUM(WQTY48),SUM(WQTY49),SUM(WQTY50)
            ,SUM(WQTY51),SUM(WQTY52)

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,SUM(WQTY53), SUM(WQTY54), SUM(WQTY55), SUM(WQTY56), SUM(WQTY57), SUM(WQTY58), SUM(WQTY59), SUM(WQTY60), SUM(WQTY61), SUM(WQTY62)
			,SUM(WQTY63), SUM(WQTY64), SUM(WQTY65), SUM(WQTY66), SUM(WQTY67), SUM(WQTY68), SUM(WQTY69), SUM(WQTY70), SUM(WQTY71), SUM(WQTY72)
			,SUM(WQTY73), SUM(WQTY74), SUM(WQTY75), SUM(WQTY76), SUM(WQTY77), SUM(WQTY78), SUM(WQTY79), SUM(WQTY80), SUM(WQTY81), SUM(WQTY82)
			,SUM(WQTY83), SUM(WQTY84), SUM(WQTY85), SUM(WQTY86), SUM(WQTY87), SUM(WQTY88), SUM(WQTY89), SUM(WQTY90), SUM(WQTY91), SUM(WQTY92)  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,SUM(WQTY93), SUM(WQTY94), SUM(WQTY95), SUM(WQTY96), SUM(WQTY97), SUM(WQTY98), SUM(WQTY99), SUM(WQTY100),SUM(WQTY101),SUM(WQTY102)
			,SUM(WQTY103),SUM(WQTY104)

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104

					,Y3.ITEM_ID AS P_ITEM_ID
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
				INNER JOIN  /* 동종 팩을 사용하는 DC LINK 적용 */
					 (SELECT ITEM_ID
				        FROM SCP_XLS_PSI_GLOBAL_ESS AA
					   WHERE CREATE_FROM_YYYYMMDD = (SELECT PLAN_START_YYYYMMDD FROM SCP_XLS_PSI_GLOBAL_ESS WHERE ROWNUM = 1)
					     AND SUBSTR(ATTRIBUTE6, 1, 1) = '1'
					) Y3
					ON INSTR(Y1.ATTRIBUTE6, Y3.ITEM_ID) > 0
			 ) X
        INNER JOIN SCM_MST_SITE S
                ON S.DIVISION_ID              = X.DIVISION_ID
               AND S.SCM_SITE_ID              = X.FROM_SITE
               AND S.OSP_YN                   = 'Y'
               AND NVL(S.ATTRIBUTE1, 'N')  = 'Y'
			   AND SUBSTR(X.ATTRIBUTE6, 1, 1) = '1'
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_DIO')
          GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            /* ,X.CELL_QTY_PACK */
            /* ,X.NICK_NAME */
            ,X.MEASURE
            ,X.MEASURE_LABEL
			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
			,X.P_ITEM_ID
 UNION
 /* 'PACK_PROD','CELL_PROD' */
      SELECT DISTINCT
             X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.FROM_SITE AND ROWNUM = 1) , '/') AS FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            /* ,X.CELL_ITEM_ID */
            ,(CASE WHEN SUB.MEASURE IN ('PACK_PROD_LOAD','CELL_PROD_LOAD')  THEN '-' ELSE CELL_ITEM_ID END) AS CELL_ITEM_ID
            ,'-' AS ITEM_ID
            ,'-' AS NICK_NAME
            ,X.PROD_LINE
            ,0 AS DAILY_CAPA_QTY
            ,0 AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,NVL(X.YIELD, 1) AS YIELD  /* X.YIELD	-- 2021-06-03 : PACK_PROD_LOAD 중복제거 */
            ,0 AS LT_DAY
            ,0 AS CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,SUB.MEASURE
            ,SUB.MEASURE_LABEL
            ,SUB.SORT_ORDER_NO
            ,99999999 AS XLS_KEY1

            ,0 AS WQTY01,0 AS WQTY02,0 AS WQTY03,0 AS WQTY04,0 AS WQTY05,0 AS WQTY06,0 AS WQTY07,0 AS WQTY08,0 AS WQTY09,0 AS WQTY10
            ,0 AS WQTY11,0 AS WQTY12,0 AS WQTY13,0 AS WQTY14,0 AS WQTY15,0 AS WQTY16,0 AS WQTY17,0 AS WQTY18,0 AS WQTY19,0 AS WQTY20
            ,0 AS WQTY21,0 AS WQTY22,0 AS WQTY23,0 AS WQTY24,0 AS WQTY25,0 AS WQTY26,0 AS WQTY27,0 AS WQTY28,0 AS WQTY29,0 AS WQTY30
            ,0 AS WQTY31,0 AS WQTY32,0 AS WQTY33,0 AS WQTY34,0 AS WQTY35,0 AS WQTY36,0 AS WQTY37,0 AS WQTY38,0 AS WQTY39,0 AS WQTY40
            ,0 AS WQTY41,0 AS WQTY42,0 AS WQTY43,0 AS WQTY44,0 AS WQTY45,0 AS WQTY46,0 AS WQTY47,0 AS WQTY48,0 AS WQTY49,0 AS WQTY50
            ,0 AS WQTY51,0 AS WQTY52

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,0 AS WQTY53, 0 AS WQTY54, 0 AS WQTY55, 0 AS WQTY56, 0 AS WQTY57, 0 AS WQTY58, 0 AS WQTY59, 0 AS WQTY60, 0 AS WQTY61, 0 AS WQTY62
			,0 AS WQTY63, 0 AS WQTY64, 0 AS WQTY65, 0 AS WQTY66, 0 AS WQTY67, 0 AS WQTY68, 0 AS WQTY69, 0 AS WQTY70, 0 AS WQTY71, 0 AS WQTY72
			,0 AS WQTY73, 0 AS WQTY74, 0 AS WQTY75, 0 AS WQTY76, 0 AS WQTY77, 0 AS WQTY78, 0 AS WQTY79, 0 AS WQTY80, 0 AS WQTY81, 0 AS WQTY82

			/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,0 AS WQTY83, 0 AS WQTY84, 0 AS WQTY85, 0 AS WQTY86, 0 AS WQTY87, 0 AS WQTY88, 0 AS WQTY89, 0 AS WQTY90, 0 AS WQTY91, 0 AS WQTY92
			,0 AS WQTY93, 0 AS WQTY94, 0 AS WQTY95, 0 AS WQTY96, 0 AS WQTY97, 0 AS WQTY98, 0 AS WQTY99, 0 AS WQTY100,0 AS WQTY101,0 AS WQTY102
			,0 AS WQTY103,0 AS WQTY104

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,(CASE WHEN SUB.MEASURE IN ('PACK_PROD_LOAD', 'PACK_TOTAL_TIME')  THEN NULL ELSE X.ATTRIBUTE6 END) AS ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
        CROSS JOIN SUB
        WHERE X.OPERATION_GROUP = SUB.OPERATION_GROUP
          AND X.MEASURE IN ('PACK_PROD','CELL_PROD')
UNION
/* 'PACK_CELL_BOH' ,'PACK_CELL_EOH_TOTAL' ,'PACK_CELL_EOH' */
SELECT X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.FROM_SITE AND ROWNUM = 1) , '/') AS FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
            /* ,X.PROD_LINE */
            ,'Total3' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,X.LT_DAY
            ,X.CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,X.MEASURE
            ,X.MEASURE_LABEL
            ,X.SORT_ORDER_NO
/* ,'9999' AS XLS_KEY1 */
            ,(CASE  WHEN X.MEASURE = 'PACK_CELL_BOH'        THEN 6666666
                    WHEN X.MEASURE = 'PACK_CELL_EOH'        THEN 7777777
                    WHEN X.MEASURE = 'PACK_CELL_EOH_TOTAL'  THEN 8888888
              ELSE 9999999 END ) AS XLS_KEY1
            ,WQTY01,WQTY02,WQTY03,WQTY04,WQTY05,WQTY06,WQTY07,WQTY08,WQTY09,WQTY10
            ,WQTY11,WQTY12,WQTY13,WQTY14,WQTY15,WQTY16,WQTY17,WQTY18,WQTY19,WQTY20
            ,WQTY21,WQTY22,WQTY23,WQTY24,WQTY25,WQTY26,WQTY27,WQTY28,WQTY29,WQTY30
            ,WQTY31,WQTY32,WQTY33,WQTY34,WQTY35,WQTY36,WQTY37,WQTY38,WQTY39,WQTY40
            ,WQTY41,WQTY42,WQTY43,WQTY44,WQTY45,WQTY46,WQTY47,WQTY48,WQTY49,WQTY50
            ,WQTY51,WQTY52

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,WQTY53, WQTY54, WQTY55, WQTY56, WQTY57, WQTY58, WQTY59, WQTY60, WQTY61, WQTY62
			,WQTY63, WQTY64, WQTY65, WQTY66, WQTY67, WQTY68, WQTY69, WQTY70, WQTY71, WQTY72
			,WQTY73, WQTY74, WQTY75, WQTY76, WQTY77, WQTY78, WQTY79, WQTY80, WQTY81, WQTY82
			,WQTY83, WQTY84, WQTY85, WQTY86, WQTY87, WQTY88, WQTY89, WQTY90, WQTY91, WQTY92  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,WQTY93, WQTY94, WQTY95, WQTY96, WQTY97, WQTY98, WQTY99, WQTY100,WQTY101,WQTY102
			,WQTY103,WQTY104

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
       WHERE 0 = 0
         AND X.MEASURE IN ('PACK_CELL_BOH'
                          ,'PACK_CELL_EOH_TOTAL'
                          ,'PACK_CELL_EOH'
                          )
UNION
/* PACK_CELL_EOH_TOTAL_SUM		Cell Total measure 추가 :: 2022.05.19 - start */
SELECT X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.FROM_SITE AND ROWNUM = 1) , '/') AS FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            ,'-'  AS CELL_ITEM_ID
            ,'-'  AS ITEM_ID
            ,'-'  AS NICK_NAME
            ,'Total3' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,0    AS FROM_BOH_QTY
            ,0    AS YIELD
            ,0    AS LT_DAY
            ,0    AS CELL_QTY_PACK
            ,NULL AS TO_SITE
            ,NULL AS TO_SITE_DESCRIPTION
			,'-'  AS BOD_ID
            ,'PACK_CELL_EOH_TOTAL_SUM' AS MEASURE
            ,'Cell Total'  AS MEASURE_LABEL
            ,999 AS SORT_ORDER_NO
            ,8888888	   AS XLS_KEY1

            ,0 AS WQTY01,0 AS WQTY02,0 AS WQTY03,0 AS WQTY04,0 AS WQTY05,0 AS WQTY06,0 AS WQTY07,0 AS WQTY08,0 AS WQTY09,0 AS WQTY10
            ,0 AS WQTY11,0 AS WQTY12,0 AS WQTY13,0 AS WQTY14,0 AS WQTY15,0 AS WQTY16,0 AS WQTY17,0 AS WQTY18,0 AS WQTY19,0 AS WQTY20
            ,0 AS WQTY21,0 AS WQTY22,0 AS WQTY23,0 AS WQTY24,0 AS WQTY25,0 AS WQTY26,0 AS WQTY27,0 AS WQTY28,0 AS WQTY29,0 AS WQTY30
            ,0 AS WQTY31,0 AS WQTY32,0 AS WQTY33,0 AS WQTY34,0 AS WQTY35,0 AS WQTY36,0 AS WQTY37,0 AS WQTY38,0 AS WQTY39,0 AS WQTY40
            ,0 AS WQTY41,0 AS WQTY42,0 AS WQTY43,0 AS WQTY44,0 AS WQTY45,0 AS WQTY46,0 AS WQTY47,0 AS WQTY48,0 AS WQTY49,0 AS WQTY50
            ,0 AS WQTY51,0 AS WQTY52

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,0 AS WQTY53, 0 AS WQTY54, 0 AS WQTY55, 0 AS WQTY56, 0 AS WQTY57, 0 AS WQTY58, 0 AS WQTY59, 0 AS WQTY60, 0 AS WQTY61, 0 AS WQTY62
			,0 AS WQTY63, 0 AS WQTY64, 0 AS WQTY65, 0 AS WQTY66, 0 AS WQTY67, 0 AS WQTY68, 0 AS WQTY69, 0 AS WQTY70, 0 AS WQTY71, 0 AS WQTY72
			,0 AS WQTY73, 0 AS WQTY74, 0 AS WQTY75, 0 AS WQTY76, 0 AS WQTY77, 0 AS WQTY78, 0 AS WQTY79, 0 AS WQTY80, 0 AS WQTY81, 0 AS WQTY82

			/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,0 AS WQTY83, 0 AS WQTY84, 0 AS WQTY85, 0 AS WQTY86, 0 AS WQTY87, 0 AS WQTY88, 0 AS WQTY89, 0 AS WQTY90, 0 AS WQTY91, 0 AS WQTY92
			,0 AS WQTY93, 0 AS WQTY94, 0 AS WQTY95, 0 AS WQTY96, 0 AS WQTY97, 0 AS WQTY98, 0 AS WQTY99, 0 AS WQTY100,0 AS WQTY101,0 AS WQTY102
			,0 AS WQTY103,0 AS WQTY104

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT DISTINCT
			         Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					/* ,Y1.ATTRIBUTE9 AS OPERATION_ID */
					/* ,Y1.CELL_ITEM_ID */
					/* ,Y1.ITEM_ID */
					/* ,Y1.NICK_NAME */
					,Y1.PROD_LINE
					/* ,Y1.FROM_BOH_QTY */
					/* ,Y1.YIELD */
					/* ,Y1.LT_DAY */
					/* ,Y1.CELL_QTY_PACK */
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					/* ,Y1.BOD_ID			-- PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6

		        FROM (SELECT *
				        FROM SCP_XLS_PSI_GLOBAL_ESS AA
					   WHERE CREATE_FROM_YYYYMMDD = (SELECT PLAN_START_YYYYMMDD FROM SCP_XLS_PSI_GLOBAL_ESS WHERE ROWNUM = 1)
					     AND MEASURE = 'PACK_CELL_EOH_TOTAL'
					 ) Y1
			 ) X
       WHERE 0 = 0
         AND X.MEASURE = 'PACK_CELL_EOH_TOTAL'
UNION
/* ('SEMI_SHIP_PLAN', 'SEMI_WHIN', 'SEMI_INTRANSIT', 'SEMI_INTRANSIT_ETA', 'SEMI_SHIP_PLAN_ETA')	-- 2021.12.20 ESS 운송중 재고 반영 */
SELECT DISTINCT X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.FROM_SITE AND ROWNUM = 1) , '/') AS FROM_SITE_DESCRIPTION
            ,X.ATTRIBUTE9 AS OPERATION_ID
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
            ,'Total3' AS PROD_LINE
            ,NULL AS DAILY_CAPA_QTY
            ,NULL AS TACT_TIME
            ,X.FROM_BOH_QTY
            ,X.YIELD
            ,MAX(X.LT_DAY)
            ,X.CELL_QTY_PACK
            ,X.TO_SITE
            ,NVL((SELECT M.SITE_DESCRIPTION FROM SCM_MST_SITE M WHERE M.SCM_SITE_ID = X.TO_SITE AND ROWNUM = 1) , '/')  AS TO_SITE_DESCRIPTION
			,X.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
            ,X.MEASURE
            ,X.MEASURE_LABEL
            ,X.SORT_ORDER_NO

			/* 2021.04.07  KSW      C20210323-000513 - GSCM 시뮬레이터의 라인 가동율 정확도 향상을 위한 로직 변경 건 - start */
			/* 원래 키값으로 복원 : 저장 안되는 문제해결 */
            /* ,'9999999' AS XLS_KEY1 */
			,X.XLS_KEY1
			/* 2021.04.07  KSW      C20210323-000513 - GSCM 시뮬레이터의 라인 가동율 정확도 향상을 위한 로직 변경 건 - end */

            ,SUM(WQTY01),SUM(WQTY02),SUM(WQTY03),SUM(WQTY04),SUM(WQTY05),SUM(WQTY06),SUM(WQTY07),SUM(WQTY08),SUM(WQTY09),SUM(WQTY10)
            ,SUM(WQTY11),SUM(WQTY12),SUM(WQTY13),SUM(WQTY14),SUM(WQTY15),SUM(WQTY16),SUM(WQTY17),SUM(WQTY18),SUM(WQTY19),SUM(WQTY20)
            ,SUM(WQTY21),SUM(WQTY22),SUM(WQTY23),SUM(WQTY24),SUM(WQTY25),SUM(WQTY26),SUM(WQTY27),SUM(WQTY28),SUM(WQTY29),SUM(WQTY30)
            ,SUM(WQTY31),SUM(WQTY32),SUM(WQTY33),SUM(WQTY34),SUM(WQTY35),SUM(WQTY36),SUM(WQTY37),SUM(WQTY38),SUM(WQTY39),SUM(WQTY40)
            ,SUM(WQTY41),SUM(WQTY42),SUM(WQTY43),SUM(WQTY44),SUM(WQTY45),SUM(WQTY46),SUM(WQTY47),SUM(WQTY48),SUM(WQTY49),SUM(WQTY50)
            ,SUM(WQTY51),SUM(WQTY52)

			/* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			,SUM(WQTY53), SUM(WQTY54), SUM(WQTY55), SUM(WQTY56), SUM(WQTY57), SUM(WQTY58), SUM(WQTY59), SUM(WQTY60), SUM(WQTY61), SUM(WQTY62)
			,SUM(WQTY63), SUM(WQTY64), SUM(WQTY65), SUM(WQTY66), SUM(WQTY67), SUM(WQTY68), SUM(WQTY69), SUM(WQTY70), SUM(WQTY71), SUM(WQTY72)
			,SUM(WQTY73), SUM(WQTY74), SUM(WQTY75), SUM(WQTY76), SUM(WQTY77), SUM(WQTY78), SUM(WQTY79), SUM(WQTY80), SUM(WQTY81), SUM(WQTY82)
			,SUM(WQTY83), SUM(WQTY84), SUM(WQTY85), SUM(WQTY86), SUM(WQTY87), SUM(WQTY88), SUM(WQTY89), SUM(WQTY90), SUM(WQTY91), SUM(WQTY92)  /* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
			,SUM(WQTY93), SUM(WQTY94), SUM(WQTY95), SUM(WQTY96), SUM(WQTY97), SUM(WQTY98), SUM(WQTY99), SUM(WQTY100),SUM(WQTY101),SUM(WQTY102)
			,SUM(WQTY103),SUM(WQTY104)

			,X.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
			,X.ATTRIBUTE6  /* DC LINK 적용 */
        FROM (
		      /* PJ20209642 LGES Digital SCM Level.3 달성을 위한 개선 - 중장기 플랜 대응 */
			  SELECT Y1.DIVISION_ID
					,Y1.PLAN_START_YYYYMMDD
					,Y1.PLAN_TYPE
					,Y1.SEQ
					,Y1.OPERATION_GROUP
					,Y1.OPERATION_GROUP_NAME
					,Y1.FROM_SITE
					,Y1.ATTRIBUTE9 AS OPERATION_ID
					,Y1.CELL_ITEM_ID
					,Y1.ITEM_ID
					,Y1.NICK_NAME
					,Y1.PROD_LINE
					,Y1.FROM_BOH_QTY
					,Y1.YIELD
					,Y1.LT_DAY
					,Y1.CELL_QTY_PACK
					,Y1.TO_SITE
					,Y1.MEASURE
					,Y1.MEASURE_LABEL
					,Y1.SORT_ORDER_NO
					,Y1.XLS_KEY1
					,Y1.ATTRIBUTE9
					,Y1.ATTRIBUTE3  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.BOD_ID  /* PJ20209643 LGES Digital SCM Level.3 달성을 위한 개선 (Phase.2) - BOD L/T 2단계 */
					,Y1.ATTRIBUTE6  /* DC LINK 적용 */

					,Y1.WQTY01,Y1.WQTY02,Y1.WQTY03,Y1.WQTY04,Y1.WQTY05,Y1.WQTY06,Y1.WQTY07,Y1.WQTY08,Y1.WQTY09,Y1.WQTY10
					,Y1.WQTY11,Y1.WQTY12,Y1.WQTY13,Y1.WQTY14,Y1.WQTY15,Y1.WQTY16,Y1.WQTY17,Y1.WQTY18,Y1.WQTY19,Y1.WQTY20
					,Y1.WQTY21,Y1.WQTY22,Y1.WQTY23,Y1.WQTY24,Y1.WQTY25,Y1.WQTY26,Y1.WQTY27,Y1.WQTY28,Y1.WQTY29,Y1.WQTY30
					,Y1.WQTY31,Y1.WQTY32,Y1.WQTY33,Y1.WQTY34,Y1.WQTY35,Y1.WQTY36,Y1.WQTY37,Y1.WQTY38,Y1.WQTY39,Y1.WQTY40
					,Y1.WQTY41,Y1.WQTY42,Y1.WQTY43,Y1.WQTY44,Y1.WQTY45,Y1.WQTY46,Y1.WQTY47,Y1.WQTY48,Y1.WQTY49,Y1.WQTY50
					,Y1.WQTY51,Y1.WQTY52

					,Y2.WQTY01 AS WQTY53, Y2.WQTY02 AS WQTY54, Y2.WQTY03 AS WQTY55, Y2.WQTY04 AS WQTY56, Y2.WQTY05 AS WQTY57
					,Y2.WQTY06 AS WQTY58, Y2.WQTY07 AS WQTY59, Y2.WQTY08 AS WQTY60, Y2.WQTY09 AS WQTY61, Y2.WQTY10 AS WQTY62
					,Y2.WQTY11 AS WQTY63, Y2.WQTY12 AS WQTY64, Y2.WQTY13 AS WQTY65, Y2.WQTY14 AS WQTY66, Y2.WQTY15 AS WQTY67
					,Y2.WQTY16 AS WQTY68, Y2.WQTY17 AS WQTY69, Y2.WQTY18 AS WQTY70, Y2.WQTY19 AS WQTY71, Y2.WQTY20 AS WQTY72
					,Y2.WQTY21 AS WQTY73, Y2.WQTY22 AS WQTY74, Y2.WQTY23 AS WQTY75, Y2.WQTY24 AS WQTY76, Y2.WQTY25 AS WQTY77
					,Y2.WQTY26 AS WQTY78, Y2.WQTY27 AS WQTY79, Y2.WQTY28 AS WQTY80, Y2.WQTY29 AS WQTY81, Y2.WQTY30 AS WQTY82

					/* 중장기 +1 Year 변경처리 :: 2022.08.11 컬럼활성화 */
					,Y2.WQTY31 AS WQTY83, Y2.WQTY32 AS WQTY84, Y2.WQTY33 AS WQTY85, Y2.WQTY34 AS WQTY86, Y2.WQTY35 AS WQTY87
					,Y2.WQTY36 AS WQTY88, Y2.WQTY37 AS WQTY89, Y2.WQTY38 AS WQTY90, Y2.WQTY39 AS WQTY91, Y2.WQTY40 AS WQTY92
					,Y2.WQTY41 AS WQTY93, Y2.WQTY42 AS WQTY94, Y2.WQTY43 AS WQTY95, Y2.WQTY44 AS WQTY96, Y2.WQTY45 AS WQTY97
					,Y2.WQTY46 AS WQTY98, Y2.WQTY47 AS WQTY99, Y2.WQTY48 AS WQTY100,Y2.WQTY49 AS WQTY101,Y2.WQTY50 AS WQTY102
					,Y2.WQTY51 AS WQTY103,Y2.WQTY52 AS WQTY104
		         FROM  SCP_XLS_PSI_GLOBAL_ESS Y1
				CROSS JOIN PLAN_NAME PN
				LEFT JOIN SCP_XLS_PSI_GLOBAL_ESS Y2
					ON Y1.XLS_KEY1 = Y2.XLS_KEY1
					AND  Y1.CREATE_FROM_YYYYMMDD = PN.PLAN_START_YYYYMMDD
					AND  Y2.CREATE_FROM_YYYYMMDD = PN.PLAN2_START_YYYYMMDD
			 ) X
       WHERE 0 = 0
         AND X.MEASURE IN ('SEMI_SHIP_PLAN', 'SEMI_WHIN', 'SEMI_INTRANSIT', 'SEMI_INTRANSIT_ETA', 'SEMI_SHIP_PLAN_ETA')  /* 2021.12.20 ESS 운송중 재고 반영 */
		 AND (CASE WHEN X.OPERATION_GROUP = 'P' AND X.ATTRIBUTE6 IS NOT NULL THEN 'Y'
		           WHEN X.OPERATION_GROUP = 'A' THEN 'Y' ELSE 'N' END) = 'Y'  /* 2021.12.20 ESS 운송중 재고 반영 */
      GROUP BY X.DIVISION_ID
            ,X.PLAN_START_YYYYMMDD
            ,X.PLAN_TYPE
            ,X.SEQ
            ,X.OPERATION_GROUP
            ,X.OPERATION_GROUP_NAME
            ,X.FROM_SITE
            ,X.ATTRIBUTE9
            ,X.CELL_ITEM_ID
            ,X.ITEM_ID
            ,X.NICK_NAME
